INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Alussa Jumala loi taivaan ja maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Mutta maa oli autio ja tyhjä, pimeys oli syvyyden päällä, ja Jumalan Henki liikkui vetten päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Jumala sanoi: \"Tulkoon valkeus!\" ja valkeus tuli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Jumala näki, että valkeus oli hyvä, ja Jumala erotti valkeuden pimeydestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Jumala nimitti valkeuden päiväksi, ja pimeyden hän nimitti yöksi. Illasta ja aamusta oli tullut yksi päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Jumala sanoi: \"Tulkoon taivaanvahvuus vesien keskuuteen ja olkoon erotuksena vesien välillä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Jumala teki taivaanvahvuuden ja erotti vedet, jotka ovat taivaanvahvuuden alla, vesistä, jotka ovat taivaanvahvuudessa, ja tapahtui niin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Jumala kutsui vahvuuden taivaaksi. Illasta ja aamusta oli tullut toinen päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Jumala sanoi: \"Kokoontukoot vedet, jotka ovat taivaan alla, yhteen paikkaan, niin että kuiva tulee näkyviin.\" Tapahtui niin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Jumala kutsui kuivan maaksi, ja paikan, mihin vedet olivat kokoontuneet, hän kutsui mereksi. Jumala näki, että se oli hyvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Jumala sanoi: \"Kasvakoon maa vihantaa, ruohoja, jotka tekevät siementä, ja hedelmäpuita, jotka lajiensa mukaan kantavat maan päällä hedelmää, jossa niiden siemen on.\" Tapahtui niin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'maa tuotti vihanneskasveja, ruohoja, jotka tekivät siementä lajiensa mukaan, ja puita, jotka lajiensa mukaan kantoivat hedelmää, jossa niiden siemen oli. Jumala näki, että se oli hyvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Illasta ja aamusta oli tullut kolmas päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Jumala sanoi: \"Tulkoot valot taivaanvahvuuteen erottamaan päivää yöstä, ja olkoot ne merkkeinä osoittamassa aikoja, päiviä ja vuosia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'Olkoot ne valoina taivaanvahvuu-dessa paistamassa maan päälle.\" Tapahtui niin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Jumala teki kaksi suurta valoa, suuremman valon hallitsemaan päivää ja pienemmän valon hallitsemaan yötä, sekä tähdet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Jumala pani ne taivaanvahvuuteen paistamaan maan päälle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'ja hallitsemaan päivää ja yötä sekä erottamaan valkeuden pimeästä. Jumala näki, että se oli hyvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Illasta ja aamusta oli tullut neljäs päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Jumala sanoi: \"Viliskööt vedet eläviä olentoja, ja lennelkööt linnut maan yllä taivaanvahvuudella.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Jumala loi suuret merieläimet ja kaikki liikkuvat, vesissä vilisevät elävät olennot, kunkin lajinsa mukaan, ja kaikki siivekkäät linnut, kunkin lajinsa mukaan. Jumala näki, että se oli hyvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Jumala siunasi ne sanoen: \"Olkaa hedelmälliset, lisääntykää ja täyttäkää meren vedet, ja linnut lisääntykööt maan päällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Illasta ja aamusta oli tullut viides päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Jumala sanoi: \"Tuottakoon maa elävät olennot, kunkin lajinsa mukaan, karjaeläimet, matelijat ja maaeläimet, kunkin lajinsa mukaan.\" Tapahtui niin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Jumala teki metsäeläimet, kunkin lajinsa mukaan, ja karjaeläimet, kunkin lajinsa mukaan, ja kaikki maan matelijat, kunkin lajinsa mukaan. Jumala näki, että se oli hyvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Jumala sanoi: \"Tehkäämme ihminen kuvaksemme, kaltaiseksemme. Vallitkoot he meren kalat ja taivaan linnut ja karjaeläimet ja koko maan ja kaikki matelijat, jotka maassa matelevat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Jumala loi ihmisen omaksi kuvakseen, Jumalan kuvaksi hän loi hänet, mieheksi ja naiseksi hän loi heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Jumala siunasi heidät, ja Jumala sanoi heille: \"Olkaa hedelmälliset, lisääntykää, täyttäkää maa ja tehkää se itsellenne alamaiseksi. Hallitkaa myös meren kalat, taivaan linnut ja kaikki maan päällä liikkuvat eläimet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Jumala sanoi: \"Katso, minä annan teille kaikki siementä tekevät ruohot, joita kasvaa kaikkialla maan päällä, ja kaikki puut, joissa on siementä tekevä hedelmä. Olkoot ne teille ravinnoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Kaikille metsäeläimille, kaikille taivaan linnuille ja kaikille, jotka maassa matelevat ja joissa on elävä henki, minä annan kaikki vihreät ruohot ravinnoksi.\" Tapahtui niin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Jumala katsoi kaikkea, mitä hän oli tehnyt, ja katso, se oli erittäin hyvää. Illasta ja aamusta oli tullut kuudes päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Taivas ja maa kaikkine joukkoineen olivat tulleet valmiiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Jumala päätti seitsemäntenä päivänä työnsä, jonka hän oli tehnyt, ja lepäsi seitsemäntenä päivänä kaikesta työstään, jonka hän oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Jumala siunasi seitsemännen päivän ja pyhitti sen, koska hän sinä päivänä lepäsi kaikesta luomistyöstään, jonka hän oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Tämä on taivaan ja maan syntykirja, kun ne luotiin tyhjästä sinä päivänä, kun Herra Jumala teki maan ja taivaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'eikä ollut vielä yhtään kedon pensasta maan päällä, eikä mikään ruoho ollut vielä versonut kedolla, koska Herra Jumala ei ollut antanut sataa maan päälle eikä ollut ihmistä maata viljelemässä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'vaan sumu nousi maasta ja kasteli koko maan pinnan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Herra Jumala oli tehnyt maan tomusta ihmisen ja puhaltanut hänen sieraimiinsa elämän hengen, ja niin ihmisestä oli tullut elävä sielu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Herra Jumala istutti paratiisin Eedeniin, itään, ja asetti sinne ihmisen, jonka hän oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Herra Jumala kasvatti maasta kaikenlaisia puita, ihania nähdä ja hyviä syödä, ja elämän puun keskelle paratiisia, sekä myös hyvän- ja pahantiedon puun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Eedenistä lähti joki, joka kasteli paratiisia, ja se jakautui sieltä neljään haaraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Ensimmäisen nimi on Piison. Se kiertää koko Havilan maan, jossa on kultaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'ja sen maan kulta on hyvää. Siellä on myös bedellion-pihkaa ja onyks-kiveä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Toisen virran nimi on Giihon. Se kiertää koko Kuusin maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Kolmannen virran nimi on Hiddekel. Se juoksee Assurin editse. Neljäs virta on Eufrat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Herra Jumala oli ottanut ihmisen ja pannut hänet Eedenin paratiisiin viljelemään ja varjelemaan sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Herra Jumala käski ihmistä sanoen: \"Syö vapaasti kaikista muista paratiisin puista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'mutta hyvän- ja pahantiedon puusta älä syö, sillä sinä päivänä, jona sinä siitä syöt, on sinun totisesti kuoltava.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Herra Jumala sanoi: \"Ei ole ihmisen hyvä olla yksin, minä teen hänelle avun, joka on hänelle sopiva.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Herra Jumala oli tehnyt maasta kaikki metsän eläimet ja kaikki taivaan linnut ja toi ne ihmisen eteen nähdäkseen, kuinka hän ne nimittäisi. Niin kuin ihminen nimitti kunkin elävän olennon, niin sen nimi oli oleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Ihminen antoi nimet kaikille karjaeläimille, taivaan linnuille ja kaikille metsän eläimille. Mutta Aadamille ei löytynyt apua, joka olisi hänelle sopinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Herra Jumala vaivutti ihmisen raskaaseen uneen. Kun hän nukkui, Jumala otti yhden hänen kylkiluistaan ja täytti sen paikan lihalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Sitten Herra Jumala rakensi vaimon siitä kylkiluusta, jonka hän oli ottanut miehestä, ja toi hänet miehen luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Mies sanoi: \"Tämä on nyt luu minun luistani ja liha minun lihastani. Kutsuttakoon häntä naiseksi, sillä hän on miehestä otettu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Sen tähden mies luopukoon isästään ja äidistään ja liittyköön vaimoonsa, ja he tulevat yhdeksi lihaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'He olivat molemmat, mies ja hänen vaimonsa, alasti eivätkä he hävenneet toisiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Mutta käärme oli älykkäin kaikista kedon eläimistä, jotka Herra Jumala oli tehnyt. Se sanoi vaimolle: \"Onko Jumala todellakin sanonut: \'Älkää syökö kaikista paratiisin puista\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Vaimo vastasi käärmeelle: \"Me saamme syödä muiden puiden hedelmiä paratiisissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'mutta sen puun hedelmästä, joka on keskellä paratiisia, Jumala on sanonut: \'Älkää syökö siitä älkääkä koskeko siihen, ettette kuolisi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Käärme sanoi vaimolle: \"Ette suinkaan kuole,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'vaan Jumala tietää, että sinä päivänä, jona te siitä syötte, aukenevat teidän silmänne, ja te tulette kuin Jumala tietämään hyvän ja pahan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Vaimo näki, että siitä puusta oli hyvä syödä ja että se oli ihana katsella ja suloinen puu antamaan ymmärrystä. Hän otti sen hedelmästä, söi ja antoi myös miehelleen, joka oli hänen kanssaan, ja hänkin söi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Silloin heidän molempien silmät aukenivat, ja he huomasivat olevansa alasti, ja he sitoivat yhteen viikunapuun lehtiä ja tekivät itselleen lannevaatteet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'He kuulivat, kuinka Herra Jumala kulki paratiisissa illan viileydessä. Niin mies piiloutui vaimonsa kanssa Herran Jumalan kasvojen edestä paratiisin puiden sekaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Mutta Herra Jumala huusi miestä ja sanoi hänelle: \"Missä olet?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Hän vastasi: \"Minä kuulin askeleesi paratiisissa ja pelkäsin, sillä minä olen alasti, ja sen tähden minä menin piiloon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Niin hän sanoi: \"Kuka sinulle ilmoitti, että olet alasti? Etkö olekin syönyt siitä puusta, josta minä kielsin sinua syömästä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Mies vastasi: \"Vaimo, jonka annoit olemaan kanssani, antoi minulle siitä puusta, ja minä söin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Herra Jumala sanoi vaimolle: \"Mitä olet tehnyt?\" Vaimo vastasi: \"Käärme petti minut, ja minä söin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Sitten Herra Jumala sanoi käärmeelle: \"Koska tämän teit, kirottu ole sinä kaikkien karjaeläinten ja kaikkien metsän eläinten joukossa. Vatsallasi sinun pitää käydä ja syödä tomua koko elinaikasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Minä panen vihollisuuden sinun ja vaimon välille ja sinun siemenesi ja hänen Siemenensä välille. Hän on polkeva rikki sinun pääsi, ja sinä olet pistävä häntä kantapäähän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Vaimolle hän sanoi: \"Minä teen suuriksi raskautesi vaivat. Kivulla sinun on synnytettävä lapset, mutta mieheesi on sinun halusi oleva, ja hän on sinua vallitseva.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Mutta Aadamille hän sanoi: \"Koska kuulit vaimoasi ja söit puusta, josta minä kielsin sinua sanoen: \'Älä syö siitä\', niin kirottu olkoon maa sinun tähtesi. Vaivaa nähden on sinun elätettävä itseäsi siitä koko elinaikasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Orjantappuroita ja ohdakkeita se on kasvava sinulle, ja kedon ruohoja sinun on syötävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Otsasi hiessä sinun pitää syödä leipäsi, kunnes tulet maaksi jälleen, sillä siitä sinut on otettu. Sillä maasta sinä olet, ja maaksi on sinun jälleen tultava.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Mies antoi vaimolleen nimen Eeva, sillä hänestä tuli kaiken elävän äiti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Herra Jumala teki Aadamille ja hänen vaimolleen puvut nahasta ja puki ne heidän ylleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Herra Jumala sanoi: \"Katso, ihminen on tullut sellaiseksi kuin joku meistä, niin että hän tietää hyvän ja pahan. Kunpa hän ei nyt vain ojentaisi kättään ja ottaisi myös elämän puusta ja söisi ja eläisi iankaikkisesti!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Niin Herra Jumala ajoi hänet pois Eedenin paratiisista viljelemään maata, josta hänet oli otettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Hän karkotti ihmisen ja asetti Eedenin paratiisin itäpuolelle kerubit sekä välkkyvän, leimuavan miekan vartioimaan elämän puun tietä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Mies yhtyi vaimoonsa Eevaan, ja tämä tuli raskaaksi ja synnytti Kainin ja sanoi: \"Minä olen saanut miehen, Herran.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Hän synnytti taas pojan, veljen Kainille, Aabelin. Aabelista tuli lammaspaimen, mutta Kainista maanviljelijä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Jonkin ajan kuluttua tapahtui, että Kain toi maan hedelmistä uhrilahjan Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Aabelkin toi uhrilahjan laumansa esikoisista, niiden rasvoista. Herra katsoi Aabelin ja hänen uhrilahjansa puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Mutta Kainin ja hänen uhrilahjansa puoleen hän ei katsonut. Silloin Kain vihastui kovin, ja hänen kasvonsa synkistyivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Herra sanoi Kainille: \"Miksi olet vihastunut, ja miksi kasvosi synkistyvät?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Eikö niin: jos teet hyvin, voit kohottaa katseesi. Mutta jos et hyvin tee, niin synti väijyy ovella, ja se haluaa sinut valtaansa, mutta hallitse sinä sitä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Sitten Kain puheli veljensä Aabelin kanssa, ja tapahtui heidän kedolla ollessaan, että Kain kävi veljensä Aabelin kimppuun ja tappoi hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Herra sanoi Kainille: \"Missä on veljesi Aabel?\" Hän vastasi: \"En tiedä. Olenko minä veljeni vartija?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Hän sanoi: \"Mitä olet tehnyt? Kuule, veljesi veri huutaa minulle maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Nyt ole kirottu ja karkotettu pois tältä vainiolta, joka avasi suunsa ottamaan veljesi veren kädestäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Kun maata viljelet, se ei ole enää sinulle satoaan antava. Kulkija ja pakolainen on sinun oltava maan päällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Niin Kain sanoi Herralle: \"Syyllisyyteni on suurempi, kuin että se voitaisiin antaa minulle anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Katso, sinä karkotat minut nyt pois vainiolta, ja minun täytyy piiloutua kasvojesi edestä ja olla kulkija ja pakolainen maan päällä. Kuka ikinä minut kohtaa, tappaa minut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Mutta Herra sanoi hänelle: \"Sen tähden, kuka ikinä tappaa Kainin, se pitää kostaa hänelle seitsenkertaisesti.\" Niin Herra pani Kainiin merkin, ettei kukaan, joka hänet kohtaisi, tappaisi häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Kain poistui Herran kasvojen edestä ja asettui asumaan Noodin maahan, itään Eedenistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Kain yhtyi vaimoonsa, ja tämä tuli raskaaksi ja synnytti Hanokin. Hän rakensi kaupungin ja antoi kaupungille poikansa nimen Hanok.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Hanokille syntyi Iirad, Iiradille syntyi Mehujael, Mehujaelille syntyi Metusael, Metusaelille syntyi Lemek.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Lemek otti itselleen kaksi vaimoa, toisen nimi oli Aada ja toisen nimi Silla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Aada synnytti Jaabalin. Hänestä tuli niiden kantaisä, jotka asuvat teltoissa ja harjoittavat karjanhoitoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Hänen veljensä nimi oli Juubal. Hänestä tuli kaikkien niiden kantaisä, jotka soittavat lyyraa ja huilua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Myös Silla synnytti pojan, Tuubal-Kainin. Hänestä tuli kaikkien vaski- ja rauta-aseiden takoja. Tuubal-Kainin sisar oli Naema.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Lemek lausui vaimoilleen: \"Aada ja Silla, kuulkaa puhettani, te Lemekin vaimot, ottakaa sanani korviinne: minä olen tappanut miehen haavastani ja nuorukaisen mustelmastani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Sillä Kain kostetaan seitsenkertaisesti, mutta Lemek seitsemänkymmentä seitsemän kertaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Aadam yhtyi taas vaimoonsa, ja tämä synnytti pojan ja antoi hänelle nimen Seet, sanoen: \"Jumala on suonut minulle toisen pojan Aabelin sijaan, koska Kain hänet tappoi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Myös Seetille syntyi poika, ja hän antoi hänelle nimen Enos. Siihen aikaan alettiin saarnata Herran nimestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Tämä on Aadamin sukukirja. Kun Jumala loi ihmisen, hän teki hänet Jumalan kaltaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Mieheksi ja naiseksi hän loi heidät, siunasi heidät ja antoi heille nimen ihminen, silloin kun heidät luotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Kun Aadam oli sadan kolmenkymmenen vuoden vanha, syntyi hänelle poika, joka oli hänen kaltaisensa, hänen kuvansa, ja hän antoi hänelle nimen Seet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Aadam eli Seetin syntymän jälkeen kahdeksansataa vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Aadamin koko elinaika oli yhdeksänsataa kolmekymmentä vuotta, ja hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Kun Seet oli sadan viiden vuoden vanha, syntyi hänelle Enos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Seet eli Enoksen syntymän jälkeen kahdeksansataa seitsemän vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Seetin koko elinaika oli yhdeksänsataa kaksitoista vuotta, ja hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Kun Enos oli yhdeksänkymmenen vuoden vanha, hänelle syntyi Keenan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Enos eli Keenanin syntymän jälkeen kahdeksansataa viisitoista vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Enoksen koko elinaika oli yhdeksänsataa viisi vuotta, ja hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Kun Keenan oli seitsemänkymmenen vuoden vanha, syntyi hänelle Mahalalel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Keenan eli Mahalalelin syntymän jälkeen kahdeksansataa neljäkymmentä vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Keenanin koko elinaika oli yhdeksänsataa kymmenen vuotta, ja hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Kun Mahalalel oli kuudenkymmenen viiden vuoden vanha, syntyi hänelle Jered.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Mahalalel eli Jeredin syntymän jälkeen kahdeksansataa kolmekymmentä vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Mahalalelin koko elinaika oli kahdeksansataa yhdeksänkymmentä viisi vuotta, ja hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Kun Jered oli sadan kuudenkymmenen kahden vuoden vanha, hänelle syntyi Hanok.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Jered eli Hanokin syntymän jälkeen kahdeksansataa vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Jeredin koko elinaika oli yhdeksänsataa kuusikymmentä kaksi vuotta. Sitten hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Kun Hanok oli kuudenkymmenen viiden vuoden vanha, hänelle syntyi Metusalah.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Hanok vaelsi Metusalahin syntymän jälkeen Jumalan yhteydessä kolmesataa vuotta ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Hanokin koko elinaika oli kolmesataa kuusikymmentä viisi vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Kun Hanok oli vaeltanut Jumalan yhteydessä, häntä ei enää ollut, sillä Jumala oli ottanut hänet luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Kun Metusalah oli sadan kahdeksankymmenen seitsemän vuoden vanha, hänelle syntyi Lemek.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Metusalah eli Lemekin syntymän jälkeen seitsemänsataa kahdeksankymmentä kaksi vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Metusalahin koko elinaika oli yhdeksänsataa kuusikymmentä yhdeksän vuotta, ja hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Kun Lemek oli sadan kahdeksankymmenen kahden vuoden vanha, syntyi hänelle poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Hän antoi hänelle nimen Nooa, sanoen: \"Tämä lohduttaa meitä työssämme ja kättemme vaivoissa viljellessämme maata, jonka Herra on kironnut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Lemek eli Nooan syntymän jälkeen viisisataa yhdeksänkymmentä viisi vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Lemekin koko elinaika oli seitsemänsataa seitsemänkymmentä seitsemän vuotta, ja hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Kun Nooa oli viidensadan vuoden vanha, hänelle syntyivät Seem, Haam ja Jaafet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Kun ihmiset alkoivat lisääntyä maan päällä ja heille syntyi tyttäriä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Jumalan lapset huomasivat, että ihmisten tyttäret olivat ihania ja ottivat vaimoikseen kaikki, jotka he parhaiksi katsoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Herra sanoi: \"Minun Henkeni ei ole tuomitseva ihmisessä loputtomasti, koska hän on liha. Niin olkoon hänen määräaikansa sata kaksikymmentä vuotta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Siihen aikaan eli maan päällä tyranneja kuten sen jälkeenkin, kun Jumalan lapset yhtyivät ihmisten tyttäriin ja nämä synnyttivät heille lapsia. Nämä olivat noita muinaisajan kuuluisia valtiaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Mutta kun Herra näki, että ihmisten pahuus oli suuri maan päällä ja että kaikki heidän sydämensä aivoitukset ja ajatukset olivat kaiken aikaa ainoastaan pahat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Herra katui tehneensä ihmiset maan päälle, ja hän tuli murheelliseksi sydämessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Herra sanoi: \"Minä hävitän maan päältä ihmiset, jotka loin, sekä ihmiset että karjan, matelijat ja taivaan linnut. Sillä kadun ne tehneeni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Mutta Nooa löysi armon Herran silmien edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Tämä on Nooan suvun syntykirja. Nooa oli aikalaistensa keskuudessa vanhurskas ja nuhteeton mies ja vaelsi Jumalan yhteydessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Nooalle syntyi kolme poikaa, Seem, Haam ja Jaafet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Mutta maa turmeltui Jumalan edessä, ja maa tuli täyteen väkivaltaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Jumala näki, että maa oli turmeltunut, sillä kaikki liha oli turmellut vaelluksensa maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Silloin Jumala sanoi Nooalle: \"Minä olen päättänyt tehdä lopun kaikesta lihasta, sillä maa on heidän tähtensä täynnä väkivaltaa. Katso, hävitän heidät sekä maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Tee itsellesi arkki gooferpuusta, rakenna arkki täyteen kammioita, ja tervaa se sisältä ja ulkoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Näin sinun on se rakennettava: kolmesataa kyynärää olkoon arkin pituus, viisikymmentä kyynärää sen leveys ja kolmekymmentä kyynärää sen korkeus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Tee arkkiin valoaukko, ja tee se kyynärän korkuiseksi, ja sijoita arkin ovi sen kylkeen. Rakenna siihen kolme kerrosta, alimmainen, keskimmäinen ja ylimmäinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Sillä katso, minä annan vedenpaisumuksen tulla yli maan hävittämään taivaan alta kaiken lihan, kaiken, jossa on elämän henki. Kaikki, mitä on maan päällä, on hukkuva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Mutta sinun kanssasi minä teen liiton, ja sinun on mentävä arkkiin, sinun, poikiesi, vaimosi ja miniäsi sinun kanssasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Kaikista eläimistä, kaikesta lihasta, sinun on vietävä arkkiin kaksi kutakin lajia säilyttääksesi ne hengissä kanssasi. Niitä olkoon koiras ja naaras.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Lintuja lajiensa mukaan, karjaeläimiä lajiensa mukaan ja kaikkia maan matelijoita lajiensa mukaan tulkoon kaksi kutakin lajia luoksesi säilyttääksesi ne hengissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Hanki itsellesi kaikkea ravintoa, syötäväksi kelpaavaa, ja kokoa sitä varastoosi, että se olisi ruuaksi sinulle ja heille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Nooa teki näin. Juuri niin kuin Jumala käski hänen tehdä, hän teki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Herra sanoi Nooalle: \"Mene sinä ja koko perheesi arkkiin, sillä sinut minä olen tässä sukukunnassa havainnut vanhurskaaksi edessäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Kaikkia puhtaita eläimiä ota luoksesi seitsemän paria, koiraita ja naaraita, mutta epäpuhtaita eläimiä kutakin yksi pari, koiras ja naaras.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, '[Ota] myös taivaan lintuja seitsemän paria, koiraita ja naaraita, että [niiden] siemen säilyisi elossa koko maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Sillä seitsemän päivän kuluttua minä annan sataa maan päälle neljäkymmentä päivää ja neljäkymmentä yötä ja hävitän maan päältä kaikki olennot, jotka olen tehnyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Nooa teki näin, aivan kuin Herra oli hänen käskenyt tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Nooa oli kuudensadan vuoden vanha, kun vedenpaisumus tuli maan päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Nooa ja hänen poikansa, vaimonsa ja miniänsä hänen kanssaan menivät arkkiin vedenpaisumuksen tieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Puhtaita eläimiä ja epäpuhtaita eläimiä, lintuja ja kaikkia, joita maassa matelee,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'meni Nooan luo arkkiin kaksittain, koiras ja naaras, niin kuin Jumala oli Nooalle käskyn antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Niiden seitsemän päivän kuluttua tuli vedenpaisumus maan päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Sinä vuonna, jona Nooa oli kuudensadan vuoden vanha, sen toisena kuukautena, kuukauden seitsemäntenätoista päivänä, sinä päivänä puhkesivat kaikki suuren syvyyden lähteet, ja taivaan ikkunat aukenivat');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'ja satoi rankasti maan päälle neljäkymmentä päivää ja neljäkymmentä yötä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Juuri sinä päivänä Nooa sekä Seem, Haam ja Jaafet, Nooan pojat, ja Nooan vaimo ja hänen kolme miniäänsä menivät heidän kanssaan arkkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'He ja kaikki metsäeläimet lajiensa mukaan ja kaikki karjaeläimet lajiensa mukaan ja kaikki matelijat, jotka maan päällä matelevat, lajiensa mukaan ja kaikki lentävät olennot lajiensa mukaan, kaikki linnut ja kaikki siivekkäät');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'menivät Nooan luo arkkiin kaksittain. [Sinne meni] kaikki liha, kaikki, jossa oli elämän henki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Ne, jotka menivät sisälle, olivat koiras ja naaras kaikesta lihasta, niin kuin Jumala oli hänelle käskyn antanut. Herra sulki oven hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Silloin tuli vedenpaisumus maan päälle, tuli neljänäkymmenenä päivänä, ja vedet paisuivat ja nostivat arkin, niin että se kohosi maasta korkealle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Vedet voimistuivat ja paisuivat suuresti maan päällä, ja arkki kulki veden pinnalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Vedet nousivat nousemistaan maan päällä, niin että kaikki korkeat vuoret kaiken taivaan alla peittyivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Vesi nousi vuorten yli viisitoista kyynärää, niin että ne peittyivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Silloin hukkui kaikki liha, joka maan päällä liikkui: linnut, karjaeläimet, maaeläimet ja kaikki pikkueläimet, joita maassa vilisi, sekä kaikki ihmiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Kaikki, joiden sieraimissa oli elämän hengen henkäys, kaikki, jotka elivät kuivalla maalla, kuolivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Niin Herra hävitti kaikki olennot, jotka maan päällä olivat, sekä ihmiset että karjaeläimet, matelijat ja taivaan linnut. Ne hävisivät maan päältä. Ainoastaan Nooa sekä ne, jotka olivat hänen kanssaan arkissa, jäivät henkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Vedet vallitsivat maan päällä sataviisikymmentä päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Jumala muisti Nooaa, kaikkia metsäeläimiä ja kaikkia karjaeläimiä, jotka olivat hänen kanssaan arkissa. Jumala nosti tuulen puhaltamaan yli maan, niin että vesi laski.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Syvyyden lähteet ja taivaan ikkunat sulkeutuivat, ja sade taivaasta taukosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Vesi väistyi väistymistään maan päältä. Sadan viidenkymmenen päivän kuluttua vesi alkoi vähentyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Arkki pysähtyi seitsemäntenä kuukautena kuukauden seitsemäntenätoista päivänä Araratin vuorille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Vesi väheni vähenemistään aina kymmenenteen kuukauteen asti. Kymmenentenä kuukautena, kuukauden ensimmäisenä päivänä, tulivat vuorten huiput näkyviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Neljänkymmenen päivän kuluttua Nooa avasi arkin ikkunan, jonka hän oli tehnyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'ja laski korpin lentoon. Se lenteli edestakaisin, kunnes vesi maan päältä kuivui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Hän lähetti luotaan kyyhkysen nähdäkseen, oliko vesi vähentynyt maan pinnalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Mutta kyyhkynen ei löytänyt paikkaa, missä lepuuttaa jalkaansa, vaan palasi hänen luokseen arkkiin, sillä koko maa oli vielä veden peitossa. Hän ojensi kätensä ja otti sen luokseen arkkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Sitten hän odotti vielä toiset seitsemän päivää ja laski taas kyyhkysen arkista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Kyyhkynen palasi hänen luokseen ilta-aikaan, ja katso, sen suussa oli tuore öljypuun lehti. Niin Nooa ymmärsi, että vesi oli vähentynyt maan päältä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Mutta hän odotti vielä toiset seitsemän päivää ja laski kyyhkysen lentoon, eikä se enää palannut hänen luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Nooan kuudentenasadantena ensim-mäisenä ikävuotena, vuoden ensimmäisenä kuukautena, kuukauden ensimmäisenä päivänä, vesi oli kuivunut maan päältä. Niin Nooa poisti katon arkista, ja katso, hän näki, että maan pinta oli kuivunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Toisena kuukautena, kuukauden kahdentenakymmenentenä seitsemäntenä päivänä, oli maa aivan kuiva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Jumala puhui Nooalle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, '\"Lähde arkista, sinä ja vaimosi, poikasi ja miniäsi kanssasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Kaikki eläimet, jotka ovat luonasi, kaikki liha, linnut, karjaeläimet ja kaikki matelijat, jotka maan päällä matelevat, vie ne ulos kanssasi. Niitä vilisköön maassa, ja ne olkoot hedelmälliset ja lisääntykööt maan päällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Nooa ja hänen poikansa, vaimonsa ja miniänsä lähtivät ulos hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Samoin lähtivät arkista suvuittain kaikki maaeläimet, kaikki matelijat ja kaikki linnut, kaikki, mikä liikkuu maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Nooa rakensi alttarin Herralle ja otti kaikkia puhtaita karjaeläimiä ja kaikkia puhtaita lintuja ja uhrasi polttouhreja alttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Herra tunsi suloisen tuoksun ja sanoi sydämessään: \"En enää koskaan kiroa maata ihmisen tähden, sillä ihmisen sydämen ajatukset ovat pahat nuoruudesta saakka. Enkä enää koskaan tuhoa kaikkea, mikä elää, kuten nyt olen tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Niin kauan kuin maa pysyy, ei lakkaa kylväminen eikä leikkaaminen, ei vilu eikä helle, ei kesä eikä talvi, ei päivä eikä yö.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Jumala siunasi Nooan ja hänen poikansa ja sanoi heille: \"Olkaa hedelmällisiä, lisääntykää ja täyttäkää maa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Pelätkööt ja vaviskoot teitä kaikki eläimet maan päällä ja kaikki taivaan linnut ja kaikki, jotka maassa matelevat, ja kaikki meren kalat. Olkoot ne teidän valtaanne annetut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Kaikki, mikä liikkuu ja elää, olkoon teille ravinnoksi. Samoin kuin olen antanut teille vihreät kasvit, annan teille myös tämän kaiken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Älkää vain syökö lihaa, jossa sen henki, sen veri, vielä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Mutta teidän oman verenne minä kostan. Jokaiselle eläimelle sen kostan, ja myös ihmisille kostan ihmisen hengen, sillä hän on hänen veljensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Sen veri, joka ihmisen veren vuodattaa, pitää ihmisen vuodattaa, sillä Jumala on tehnyt ihmisen kuvakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Mutta te olkaa hedelmällisiä ja lisääntykää, enentykää maassa ja lisääntykää siinä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Jumala puhui Nooalle ja hänen pojilleen, jotka olivat hänen kanssaan, sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, '\"Katso, minä teen liiton teidän ja teidän jälkeläistenne kanssa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'ja kaikkien elävien olentojen kanssa, jotka ovat luonanne, lintujen, karjaeläinten ja kaikkien maaeläinten kanssa, jotka ovat luonanne, kaikkien kanssa, jotka arkista lähtivät, kaikkien maan eläinten kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Teen liiton teidän kanssanne: koskaan ei enää kaikkea lihaa hukuteta vedenpaisumuksella, eikä vedenpaisumus koskaan enää tuhoa maata.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Jumala sanoi: \"Tämä on sen liiton merkki, jonka minä teen ikuisiksi ajoiksi itseni ja teidän ja kaikkien elävien olentojen välillä, jotka ovat luonanne:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'panen kaareni pilviin, ja se on oleva liiton merkkinä minun ja maan välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Kun kokoan pilviä maan päälle ja kaari näkyy pilvissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'muistan liittoni, joka on minun ja teidän ja kaikkien elävien olentojen, kaiken lihan välillä, eikä vesi enää paisu tulvaksi hävittämään kaikkea lihaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Niin kaari on oleva pilvissä, ja katselen sitä muistaakseni iankaikkista liittoa Jumalan ja kaikkien elävien olentojen, kaiken lihan välillä, joka maan päällä on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Jumala sanoi Nooalle: \"Tämä on sen liiton merkki, jonka minä olen tehnyt itseni ja kaiken lihan välillä, joka maan päällä on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Nooan pojat, jotka lähtivät arkista, olivat Seem, Haam ja Jaafet. Haam oli Kanaanin isä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Nämä kolme ovat Nooan pojat, ja heistä kaikki maan asukkaat polveutuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Nooa oli viljelijä ja ensimmäinen, joka istutti viinitarhan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Mutta kun hän joi viiniä, hän juopui ja makasi alasti majassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Haam, Kanaanin isä, näki isänsä hävyn ja kertoi siitä molemmille veljilleen ulkona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Niin Seem ja Jaafet ottivat viitan ja panivat molemmat sen hartioilleen ja menivät selin sisään ja peittivät isänsä hävyn. Heidän kasvonsa olivat käännetyt toisaalle, niin etteivät he nähneet isänsä häpyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Kun Nooa heräsi päihtymyksestään ja sai tietää, mitä hänen nuorin poikansa oli hänelle tehnyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'hän sanoi: \"Kirottu olkoon Kanaan, olkoon hän veljiensä orjien orja.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Vielä hän sanoi: \"Kiitetty olkoon Herra, Seemin Jumala, ja olkoon Kanaan heidän palvelijansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Jumala laajentakoon Jaafetin, ja asukoon hän Seemin majoissa, ja Kanaan olkoon heidän palvelijansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Nooa eli vedenpaisumuksen jälkeen kolmesataa viisikymmentä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Nooan koko ikä oli yhdeksänsataa viisikymmentä vuotta. Sitten hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Tämä on Nooan poikien, Seemin, Haamin ja Jaafetin, suvun syntykirja. Heille syntyi poikia vedenpaisumuksen jälkeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Jaafetin pojat olivat Goomer, Maagog, Maadai, Jaavan, Tuubal, Mesek ja Tiiras.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Goomerin pojat olivat Askenas, Riifat ja Toogarma.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Jaavanin pojat olivat Elisa, Tarsis, kittiläiset ja doodanilaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Heistä haarautuivat pakanoiden saarten asukkaat maittensa, eri kieltensä, heimojensa ja kansakuntiensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Haamin pojat olivat Kuus, Misraim, Puut ja Kanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Kuusin pojat olivat Seba, Havila, Sabta, Raema ja Sabteka. Raeman pojat olivat Saba ja Dedan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Kuusille syntyi Nimrod. Hän oli ensimmäinen valtias maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Hän oli mahtava saalistaja Herran edessä. Siitä on sananparsi: \"Mahtava saalistaja Herran edessä kuin Nimrod.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Hänen valtakuntansa alkuna olivat Baabel, Erek, Akkad ja Kalne Sinearin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Siitä maasta hän lähti Assuriin ja rakensi Niiniven, Rehobot-Iirin ja Kelahin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'sekä Resenin Niiniven ja Kelahin välille. Se on tuo suuri kaupunki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Misraimille syntyivät luudilaiset, anamilaiset, lehabilaiset, naftuhilaiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'patrokselaiset, kasluhilaiset, joista filistealaiset ovat lähteneet, sekä kaftorilaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Kanaanille syntyivät Siidon, hänen esikoisensa, ja Heet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'sekä jebusilaiset, amorilaiset, girgasilaiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'hivviläiset, arkilaiset, siiniläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'arvadilaiset, semarilaiset ja hamatilaiset. Myöhemmin kanaanilaisten heimot hajaantuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Kanaanilaisten alue ulottui Siidonista Gerariin päin aina Gassaan asti sekä Sodomaan, Gomorraan, Admaan ja Seboimiin päin aina Lesaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Nämä olivat Haamin pojat heimojensa, kieltensä, maittensa ja kansakuntiensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Myös Seemille, Jaafetin, [Nooan] vanhimman [pojan], veljelle, josta tuli kaikkien Eeberin poikien kantaisä, syntyi poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Seemin pojat olivat Eelam, Assur, Arpaksad, Luud ja Aram.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Aramin pojat olivat Uus, Huul, Geter ja Mas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arpaksadille syntyi Selah, ja Selahille syntyi Eeber.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Eeberille syntyi kaksi poikaa: toisen nimi oli Peleg, sillä hänen aikanaan maa jakautui, ja hänen veljensä nimi oli Joktan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Joktanille syntyi Almodad, Selef, Hasarmavet, Jerah,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadoram, Uusal, Dikla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Oobal, Abimael, Saba,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Oofir, Havila ja Joobab. Kaikki nämä olivat Joktanin poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Heidän asumasijansa ulottuivat Meesasta aina Sefariin, Itävuorelle asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Nämä olivat Seemin pojat heimojensa, kieltensä, maittensa ja kansakuntiensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Nämä olivat Nooan poikien heimot sukukuntiensa ja kansakuntiensa mukaan, ja niistä haarautuivat kansat maan päälle vedenpaisumuksen jälkeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Kaikkialla maan päällä oli yksi kieli ja yksi puhetapa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Kun he lähtivät liikkeelle idän suuntaan, he löysivät alangon Sinearin maassa ja asettuivat sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'He sanoivat toisilleen: \"Tulkaa, tehkäämme tiiliä ja polttakaamme ne koviksi.\" He käyttivät savitiiltä rakennuskivenä, ja asfalttipikeä he käyttivät laastina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'He sanoivat: \"Tulkaa, rakentakaamme itsellemme kaupunki ja torni, jonka huippu on taivaassa, ja tehkäämme itsellemme nimi, ettemme hajaantuisi yli kaiken maan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Herra astui alas katsomaan kaupunkia ja tornia, jonka ihmisen lapset olivat rakentaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Herra sanoi: \"Katso, he ovat yksi kansa, ja heillä kaikilla on yksi kieli, ja tämä on heidän ensimmäinen yrityksensä. Nyt heille ei ole mahdotonta mikään, mihin ryhtyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Tulkaa, astukaamme alas ja sekoittakaamme siellä heidän kielensä, niin ettei toinen ymmärrä toisensa kieltä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Herra hajotti heidät sieltä yli koko maan, niin että he lakkasivat rakentamasta kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Siitä tuli sen nimeksi Baabel, koska Herra siellä sekoitti kaiken maan kielen. Sieltä Herra hajotti heidät yli koko maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Tämä on Seemin suvun syntykirja. Kun Seem oli sadan vuoden vanha, hänelle syntyi Arpaksad kaksi vuotta vedenpaisumuksen jälkeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Seem eli Arpaksadin syntymän jälkeen viisisataa vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Kun Arpaksad oli kolmenkymmenen viiden vuoden vanha, hänelle syntyi Selah.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Arpaksad eli Selahin syntymän jälkeen neljäsataa kolme vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Kun Selah oli kolmenkymmenen vuoden vanha, hänelle syntyi Eeber.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Selah eli Eeberin syntymän jälkeen neljäsataa kolme vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Kun Eeber oli kolmenkymmenen neljän vuoden vanha, hänelle syntyi Peleg.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Eeber eli Pelegin syntymän jälkeen neljäsataa kolmekymmentä vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Kun Peleg oli kolmenkymmenen vuoden vanha, hänelle syntyi Regu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Peleg eli Regun syntymän jälkeen kaksisataa yhdeksän vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Kun Regu oli kolmenkymmenen kahden vuoden vanha, hänelle syntyi Serug.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Regu eli Serugin syntymän jälkeen kaksisataa seitsemän vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Kun Serug oli kolmenkymmenen vuoden vanha, hänelle syntyi Naahor.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Serug eli Naahorin syntymän jälkeen kaksisataa vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Kun Naahor oli kahdenkymmenen yhdeksän vuoden vanha, hänelle syntyi Terah.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Naahor eli Terahin syntymän jälkeen sata yhdeksäntoista vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Kun Terah oli seitsemänkymmenen vuoden vanha, hänelle syntyivät Abram, Naahor ja Haaran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Tämä on Terahin suvun syntykirja. Terahille syntyivät Abram, Naahor ja Haaran. Haaranille syntyi Loot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Haaran kuoli ennen isäänsä Terahia synnyinmaassaan Kaldean Uurissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Abram ja Naahor ottivat itselleen vaimot. Abramin vaimon nimi oli Saarai, ja Naahorin vaimon nimi oli Milka, Haaranin tytär. Haaran oli Milkan ja Jiskan isä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Saarai oli hedelmätön. Hänellä ei ollut lasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Terah otti poikansa Abramin ja poikansa pojan Lootin, Haaranin pojan, ja miniänsä Saarain, poikansa Abramin vaimon, ja he lähtivät heidän kanssaan Kaldean Uurista mennäkseen Kanaanin maahan. He saapuivat Harraniin asti ja asuivat siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Terahin elinikä oli kaksisataa viisi vuotta. Terah kuoli Harranissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Herra oli sanonut Abramille: \"Lähde maastasi, suvustasi ja isäsi kodista siihen maahan, jonka sinulle osoitan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Teen sinusta suuren kansan, siunaan sinut ja teen nimesi suureksi, ja olet tuleva siunaukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Siunaan niitä, jotka sinua siunaavat, ja kiroan ne, jotka sinua kiroavat, ja sinussa tulevat siunatuiksi kaikki sukukunnat maan päällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Abram lähti, kuten Herra oli hänelle puhunut, ja Loot meni hänen kanssaan. Abram oli Harranista lähtiessään seitsemänkymmentä viisi vuotta vanha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Abram otti vaimonsa Saarain ja veljensä pojan Lootin sekä kaiken omaisuuden, jonka he olivat koonneet, ja ne palvelijat, jotka he olivat hankkineet Harranissa, ja he lähtivät menemään Kanaanin maahan. He saapuivat Kanaanin maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Abram kulki halki maan aina Sikemin paikkakunnalle, Mooren tammelle asti. Siihen aikaan kanaanilaiset asuivat siinä maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Silloin Herra ilmestyi Abramille ja sanoi: \"Sinun jälkeläisillesi annan tämän maan.\" Hän rakensi sinne alttarin Herralle, joka oli hänelle ilmestynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Sieltä hän siirtyi edemmäksi vuoristoon, Beetelistä itään, ja pystytti telttansa, niin että Beetel oli lännessä ja Ai idässä. Hän rakensi sinne alttarin Herralle ja saarnasi Herran nimestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Sieltä Abram lähti ja vaelsi yhä edemmäksi Etelämaahan päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Maahan tuli nälänhätä, ja Abram meni Egyptiin asuakseen siellä jonkin aikaa, sillä nälänhätä maassa oli kova.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Kun hän lähestyi Egyptiä, hän puhui vaimolleen Saaraille: \"Katso, tiedän, että sinä olet kaunis nainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Kun egyptiläiset saavat nähdä sinut, he sanovat: \'Hän on hänen vaimonsa\', ja tappavat minut, mutta antavat sinun elää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Sano siis olevasi sisareni, että minun kävisi hyvin sinun tähtesi ja sinun takiasi saisin jäädä henkiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Kun Abram tuli Egyptiin, egyptiläiset näkivät, että Saarai oli hyvin kaunis nainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Kun faraon ruhtinaat olivat nähneet hänet, he ylistelivät häntä faraolle, ja vaimo vietiin faraon hoviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Hän kohteli Abramia hyvin Saarain tähden. Hän sai lampaita ja vuohia, nautoja ja aaseja, palvelijoita ja palvelijattaria, aasintammoja ja kameleja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Mutta Herra antoi kovien vitsausten kohdata faraota ja hänen hoviaan Saarain, Abramin vaimon, tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Silloin farao kutsui Abramin luokseen ja sanoi: \"Mitä olet minulle tehnyt? Miksi et ilmoittanut minulle, että hän on vaimosi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Miksi sanoit: \'Hän on minun sisareni\', niin että otin hänet vaimokseni? Katso, tässä on vaimosi, ota hänet ja mene.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Farao antoi hänestä käskyn miehilleen, että he saattaisivat hänet pois, hänet ja hänen vaimonsa sekä kaiken, mitä hänellä oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Abram poistui Egyptistä Negeviin, hän ja hänen vaimonsa ja kaikki, mitä hänellä oli, ja Loot hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Abram oli hyvin rikas: hänellä oli karjaa, hopeaa ja kultaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Hän vaelsi kulkien levähdyspaikasta toiseen Negevistä Beeteliin asti, aina siihen paikkaan, missä hänen telttamajansa oli ensi kerralla ollut Beetelin ja Ain välillä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'siihen paikkaan, johon hän ennen oli rakentanut alttarin. Abram saarnasi siinä Herran nimestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Myös Lootilla, joka vaelsi Abramin kanssa, oli lampaita ja vuohia, nautoja ja telttoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Eikä maa riittänyt heidän asuakseen yhdessä, sillä heillä oli paljon omaisuutta, niin etteivät he voineet asua yhdessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Syntyi riitaa Abramin karjapaimenten ja Lootin karjapaimenten välillä. Siihen aikaan siinä maassa asuivat kanaanilaiset ja perissiläiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Abram sanoi Lootille: \"Älköön olko riitaa meidän välillämme, minun ja sinun, älköönkä minun paimenteni ja sinun paimentesi välillä, sillä olemmehan veljeksiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Eikö koko maa ole avoinna edessäsi? Eroa minusta. Jos menet vasemmalle, minä menen oikealle, tai jos sinä menet oikealle, niin minä menen vasemmalle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Loot nosti silmänsä ja näki koko Jordanin alangon olevan runsasvetistä seutua. Ennen kuin Herra hävitti Sodoman ja Gomorran, se oli Sooariin asti kuin Herran puutarha, kuin Egyptin maa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Loot valitsi itselleen koko Jordanin alangon ja siirtyi itään päin, ja he erkanivat toisistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram asettui Kanaanin maahan. Loot asettui alangon kaupunkeihin ja siirtyi siirtymistään telttoineen Sodomaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Mutta Sodoman kansa oli kovin pahaa ja syntistä Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Herra sanoi Abramille, sen jälkeen kun Loot oli hänestä eronnut: \"Nosta silmäsi ja katso siitä paikasta, missä olet, pohjoiseen, etelään, itään ja länteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Sillä kaiken maan, jonka sinä näet, annan sinulle ja sinun jälkeläisillesi ikiajoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Minä teen jälkeläistesi luvun paljoksi kuin maan tomu. Jos voidaan lukea maan tomu, voidaan lukea myös jälkeläisesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Nouse ja vaella maata pitkin ja poikin, sillä sinulle sen annan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Abram siirtyi siirtymistään telttoineen ja tuli ja asettui Mamren tammistoon, joka on Hebronin luona, ja rakensi sinne alttarin Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Tapahtui siihen aikaan, kun Amrafel oli Sinearin kuninkaana, Arjok Ellasarin kuninkaana, Kedorlaomer Eelamin kuninkaana ja Tidal Goojimin kuninkaana,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'että he aloittivat sodan Beraa, Sodoman kuningasta, Birsaa, Gomorran kuningasta, Sinabia, Adman kuningasta, Semeberiä, Seboimin kuningasta, ja Belan, se on Sooarin, kuningasta vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Nämä kaikki liittoutuivat kokoontuen Siddimin laaksoon, jossa on nykyisin Suolameri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Kaksitoista vuotta he olivat olleet Kedorlaomerille alamaisia, mutta kolmantenatoista vuotena he tekivät kapinan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Neljäntenätoista vuotena tulivat Kedorlaomer ja ne kuninkaat, jotka olivat hänen kanssaan, voittivat refalaiset Astarot-Karnaimissa ja suusilaiset Haamissa, niin myös eemiläiset Kirjataimin tasangolla');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'ja hoorilaiset heidän vuoristossaan, Seirissä, aina Eel-Paaraniin asti, joka on erämaan laidassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Sitten he palasivat ja tulivat Mispatin lähteelle, se on Kaadekseen, ja valloittivat koko amalekilaisten maan ja voittivat myös amorilaiset, jotka asuivat Hasason-Taamarissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Silloin lähtivät Sodoman kuningas, Gomorran kuningas, Adman kuningas, Seboimin kuningas ja Belan, se on Sooarin, kuningas ja asettuivat Siddimin laaksossa taistelurintamaan heitä vastaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'Eelamin kuningasta Kedorlaomeria, Goojimin kuningasta Tidalia, Sinearin kuningasta Amrafelia ja Ellasarin kuningasta Arjokia vastaan, neljä kuningasta viittä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Mutta Siddimin laakso oli täynnä maapihkakuoppia. Sodoman ja Gomorran kuninkaat pakenivat ja putosivat niihin, mutta henkiin jääneet pakenivat vuoristoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Niin he ottivat Sodomasta ja Gomorrasta kaiken tavaran ja kaikki ruokavarat ja menivät matkaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Lähtiessään he ottivat mukaansa myös Lootin, Abramin veljenpojan, ja hänen omaisuutensa. Hän näet asui Sodomassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Sitten muuan pakolainen tuli ja ilmoitti siitä Abramille, heprealaiselle. Tämä asui tammistossa, joka oli amorilaisen Mamren, Eskolin ja Aanerin veljen, oma. He olivat Abramin liittolaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Kun Abram kuuli, että hänen veljensä oli otettu vangiksi, hän aseisti luotettavimmat palvelijansa, jotka olivat hänen kodissaan syntyneet, kolmesataa kahdeksantoista miestä, ja ajoi vihollisia takaa aina Daaniin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Hän jakoi väkensä ja hyökkäsi palvelijoineen yöllä vihollisten kimppuun ja voitti heidät. Hän ajoi heitä takaa aina Hoobaan saakka, joka on Damaskosta pohjoiseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Hän toi takaisin kaiken tavaran. Myös sukulaisensa Lootin ja hänen tavaransa hän toi takaisin, niin myös vaimot ja muun väen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Kun hän oli paluumatkalla voitettuaan Kedorlaomerin ja ne kuninkaat, jotka olivat tämän kanssa, Sodoman kuningas meni häntä vastaan Saaven laaksoon, jota sanotaan \"Kuninkaan laaksoksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Mutta Melkisedek, Saalemin kuningas, toi leipää ja viiniä. Hän oli Jumalan, Korkeimman, pappi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Hän siunasi hänet sanoen: \"Siunatkoon Abramia Jumala, Korkein, taivaan ja maan omistaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Kiitetty olkoon Jumala, Korkein, joka antoi vihollisesi käsiisi.\" Abram antoi hänelle kymmenykset kaikesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Sodoman kuningas sanoi Abramille: \"Anna minulle väki ja pidä sinä tavara.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Mutta Abram sanoi Sodoman kuninkaalle: \"Nostan käteni Herran, Jumalan, Korkeimman, taivaan ja maan omistajan, puoleen ja vannon:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'En totisesti ota, en langan päätä, en sandaalin nyöriä enkä mitään muuta, mikä on sinun, ettet sanoisi: \'Minä olen tehnyt Abramin rikkaaksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'En tahdo mitään, paitsi mitä palvelijat ovat kuluttaneet ja mikä on niille miehille tuleva, jotka minua seurasivat, Aanerille, Eskolille ja Mamrelle. He saakoot osansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Näiden tapausten jälkeen Abramille tuli näyssä tämä Herran sana: \"Älä pelkää, Abram! Minä olen kilpesi. Palkkasi on oleva erittäin suuri.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Mutta Abram sanoi: \" Herra, Herra, mitä minulle annat? Minä lähden täältä lapsettomana, ja omaisuuteni haltijaksi tulee damaskolainen mies, Elieser.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Abram sanoi vielä: \"Katso, et ole antanut minulle jälkeläistä. Katso, talossani syntynyt [palvelija] on minut perivä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Mutta katso, hänelle tuli tämä Herran sana: \"Hän ei ole sinua perivä, vaan se, joka lähtee omasta ruumiistasi, on sinut perivä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Hän vei hänet ulos ja sanoi: \"Katso taivaalle ja lue tähdet, jos osaat ne laskea.\" Hän sanoi hänelle: \"Niin paljon sinulla on oleva jälkeläisiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Abram uskoi Herraa, ja Herra luki sen hänelle vanhurskaudeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Hän sanoi hänelle: \"Minä olen Herra, joka toin sinut Kaldean Uurista, antaakseni sinulle tämän maan omaksesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Mutta hän sanoi: \"Herra, Herra, mistä minä tiedän, että saan sen omakseni?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Hän sanoi hänelle: \"Tuo minulle kolmivuotias hieho, kolmivuotias vuohi ja kolmivuotias pässi sekä metsäkyyhkynen ja nuori kyyhkynen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Niin hän toi nämä kaikki ja halkaisi ne ja asetti puolikkaat vastakkain. Lintuja hän ei kuitenkaan halkaissut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Silloin petolintuja laskeutui ruhojen päälle, mutta Abram karkotti ne pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Kun aurinko oli laskemassa, Abramin valtasi raskas uni, ja katso, kauhu ja suuri pimeys valtasi hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Herra sanoi Abramille: \"Niin tiedä totisesti, että jälkeläisesi tulevat elämään muukalaisina maassa, joka ei ole heidän omansa, ja heidän pitää palvella näitä, ja nämä sortavat heitä, – neljäsataa vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Mutta minä tuomitsen myös sen kansan, jota he palvelevat. Sitten he pääsevät lähtemään mukanaan paljon tavaraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Mutta sinä menet isiesi luo rauhassa, ja sinut haudataan päästyäsi korkeaan ikään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Neljännessä polvessa jälkeläisesi palaavat tänne takaisin, sillä amorilaisten syntivelka ei ole vielä täysi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Kun aurinko oli laskenut ja oli tullut pilkkopimeä, näkyi savuava pätsi ja liekehtivä tuli, joka liikkui uhrikappaleiden välissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Sinä päivänä Herra teki Abramin kanssa liiton, sanoen: \"Sinun jälkeläisillesi annan tämän maan, Egyptin virrasta aina suureen virtaan, Eufrat-virtaan saakka:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'keeniläiset, kenissiläiset, kadmonilaiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'heettiläiset, perissiläiset, refalaiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'amorilaiset, kanaanilaiset, girgasilaiset ja jebusilaiset.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Mutta Saarai, Abramin vaimo, ei synnyttänyt hänelle lasta. Saarailla oli egyptiläinen orjatar, jonka nimi oli Haagar.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Saarai sanoi Abramille: \"Katso, Herra on sulkenut kohtuni synnyttämästä. Yhdy siis orjattareeni, ehkä saisin lapsia hänestä.\" Abram kuuli Saaraita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Saarai, Abramin vaimo, otti egyptiläisen orjattarensa Haagarin, sitten kun Abram oli asunut kymmenen vuotta Kanaanin maassa, ja antoi hänet miehelleen Abramille vaimoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Hän yhtyi Haagariin, ja Haagar tuli raskaaksi. Kun Haagar huomasi olevansa raskaana, hänen emäntänsä tuli halvaksi hänen silmissään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Silloin Saarai sanoi Abramille: \"Kärsimäni vääryys kohdatkoon sinua. Minä annoin orjattareni syliisi, mutta kun hän huomasi olevansa raskaana, tulin halvaksi hänen silmissään. Herra tuomitkoon välillämme, minun ja sinun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Abram sanoi Saaraille: \"Katso, orjattaresi on sinun vallassasi, tee hänelle, mitä tahdot.\" Saarai kuritti häntä, ja hän pakeni hänen luotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Sitten Herran Enkeli tapasi hänet vesilähteeltä erämaassa, sen lähteen luota, joka on Suurin tien varressa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Hän sanoi: \"Haagar, Saarain orjatar, mistä tulet ja mihin menet?\" Hän vastasi: \"Olen paossa emäntääni Saaraita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Herran Enkeli sanoi hänelle: \"Palaa emäntäsi luo ja nöyrry hänen kätensä alle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Herran Enkeli sanoi hänelle: \"Teen jälkeläistesi luvun niin suureksi, ettei heitä lasketa heidän paljoutensa tähden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Herran Enkeli puhui hänelle: \"Katso, sinä olet raskaana ja synnytät pojan ja annat hänelle nimen Ismael, sillä Herra on kuullut sinun hätäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Hänestä tulee mies kuin villiaasi: hänen kätensä on kaikkia vastaan, ja kaikkien käsi on häntä vastaan, ja hän on asuva kaikkien veljiensä edessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Haagar antoi nimeksi Herralle, joka oli häntä puhutellut: Eel Roi, sillä hän sanoi: \"Olenko minä tässä nähnyt takaa hänet, joka minut näkee?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Sen tähden kutsutaan kaivoa nimellä Lahai-Roin kaivo. Se on Kaadeksen ja Beredin välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Haagar synnytti Abramille pojan, ja Abram antoi pojalleen, jonka Haagar oli hänelle synnyttänyt, nimen Ismael.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Abram oli kahdeksankymmenen kuuden vuoden vanha, kun Haagar synnytti hänelle Ismaelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Kun Abram oli yhdeksänkymmentä yhdeksän vuotta vanha, Herra ilmestyi hänelle ja sanoi hänelle: \"Minä olen Jumala, Kaikkivaltias. Vaella edessäni ja ole nuhteeton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Teen liittoni välillemme, minun ja sinun, ja lisään sinut hyvin runsaasti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Abram lankesi kasvoilleen, ja Jumala puhui hänelle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, '\"Katso, tämä on liittoni kanssasi: sinusta tulee kansojen paljouden isä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Älköön sinua enää kutsuttako Abramiksi, vaan nimesi olkoon Aabraham, sillä teen sinusta monien kansojen isän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Teen sinut todella hyvin hedelmälliseksi ja annan sinusta tulla kansoja, ja sinusta on polveutuva kuninkaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Teen liiton kanssasi ja jälkeläistesi kanssa, sukupolvesta sukupolveen, iankaikkisen liiton ollakseni sinun ja sinun jälkeläistesi Jumala,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'ja annan sinulle ja jälkeläisillesi sen maan, jossa asut muukalaisena, koko Kanaanin maan, ikuiseksi omaisuudeksi, ja minä olen heidän Jumalansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Jumala sanoi Aabrahamille: \"Mutta pidä sinä minun liittoni, sinä ja jälkeläisesi, sukupolvesta sukupolveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Tämä on minun liittoni sinun ja jälkeläistesi kanssa. Pitäkää se: ympärileikatkaa jokainen miespuolinen keskuudessanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Ympärileikatkaa esinahkanne liha, ja se olkoon liiton merkki välillämme, minun ja teidän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Sukupolvesta sukupolveen ympärileikattakoon jokainen poikalapsi keskuudessanne kahdeksan päivän ikäisenä, sekä kotona syntynyt palvelija että muukalaiselta, keneltä tahansa, rahalla ostettu, joka ei ole jälkeläisiäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Ympärileikattakoon sekä kotonasi syntynyt että rahalla ostamasi, ja liittoni on oleva merkitty lihaanne ikuiseksi liitoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Mutta ympärileikkaamaton miehenpuoli, jonka esinahan liha ei ole ympärileikattu, hävitettäköön kansastaan. Hän on rikkonut liittoni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Sitten Jumala sanoi Aabrahamille: \"Älä kutsu vaimoasi Saaraita enää Saaraiksi, sillä Saara on hänen nimensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Siunaan häntä ja annan hänestäkin sinulle pojan. Siunaan häntä, ja hänestä tulee kansakuntia, polveutuu kansojen kuninkaita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Aabraham lankesi kasvoilleen ja nauroi, sillä hän ajatteli sydämessään: \"Satavuotiaalleko syntyy poika, ja Saarako, yhdeksänkymmenen vuoden vanha, synnyttää?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Niin Aabraham sanoi Jumalalle: \"Kunpa Ismael saisi elää edessäsi!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Jumala sanoi: \"Totisesti, vaimosi Saara synnyttää sinulle pojan, ja sinun on pantava hänelle nimeksi Iisak, ja teen liittoni hänen kanssaan ikuiseksi liitoksi hänen jälkeläisilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Mutta myös Ismaelista olen kuullut rukouksesi. Katso, siunaan häntä ja teen hänet hedelmälliseksi ja annan hänen lisääntyä hyvin runsaasti. Hänestä on polveutuva kaksitoista ruhtinasta, ja teen hänestä suuren kansan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Mutta liittoni teen Iisakin kanssa, jonka Saara sinulle synnyttää tähän aikaan tulevana vuonna.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Kun Jumala oli lakannut puhumasta Aabrahamin kanssa, hän kohosi ylös hänen luotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Sitten Aabraham otti poikansa Ismaelin sekä kaikki kotona syntyneet ja kaikki rahalla ostamansa palvelijat, kaikki Aabrahamin perheen miespuoliset, ja ympärileikkasi sinä samana päivänä heidän esinahkansa lihan, niin kuin Jumala oli hänelle sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Aabraham oli yhdeksänkymmenen yhdeksän vuoden vanha, kun hänen esinahkansa liha ympärileikattiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Hänen poikansa Ismael oli kolmentoista vuoden vanha, kun hänen esinahkansa liha ympärileikattiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Aabraham ja hänen poikansa Ismael ympärileikattiin samana päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Kaikki hänen perheensä miehet, sekä kotona syntyneet että muukalaisilta rahalla ostetut, ympärileikattiin hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Herra ilmestyi hänelle Mamren tammistossa, jossa hän istui telttamajansa ovella päivän ollessa palavimmillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Kun hän nosti silmänsä ja katseli, niin, katso, kolme miestä seisoi hänen edessään. Nähdessään heidät hän riensi heitä vastaan majan ovelta ja kumartui maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'Hän sanoi: \"Herrani, jos olen saanut armon silmiesi edessä, älä mene palvelijasi ohi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Sallikaa tuoda vähän vettä ja peskää jalkanne ja levätkää puun siimeksessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Tuon palan leipää virkistääksenne itseänne, ennen kuin jatkatte matkaanne, sillä kaiketi sitä varten olette poikenneet palvelijanne luo.\" He sanoivat: \"Tee, niin kuin olet puhunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Aabraham kiiruhti majaan Saaran luo ja sanoi: \"Hae kiireesti kolme vakallista ydinjauhoja, sotke taikina ja leivo leipiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Aabraham juoksi karjan luo, otti nuoren ja hyvän vasikan ja antoi palvelijalle, joka riensi nopeasti sitä valmistamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Hän otti voita ja maitoa sekä vasikan, jonka hän oli valmistuttanut, ja pani ne heidän eteensä. Itse hän seisoi heidän luonaan puun alla sillä aikaa, kun he söivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'He kysyivät häneltä: \"Missä vaimosi Saara on?\" Hän vastasi: \"Tuolla majassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Hän sanoi: \"Palaan todella luoksesi tulevana vuonna tähän aikaan, ja katso, vaimollasi Saaralla on silloin poika.\" Saara kuunteli majan ovella hänen takanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Mutta Aabraham ja Saara olivat iäkkäitä, eikä Saaran laita enää ollut, kuten naisten tavallisesti on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Sen tähden Saara naurahti mielessään ja ajatteli: \"Heräisikö minussa näin kuihduttuani vielä halu? Myös minun herrani on vanha.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Mutta Herra sanoi Aabrahamille: \"Miksi Saara nauroi ajatellen: \'Synnyttäisinkö todella, minä, joka olen näin vanha?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Onko mikään Herralle mahdotonta? Tähän aikaan palaan luoksesi tulevana vuonna, ja Saaralla on silloin poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Saara kielsi sanoen: \"En minä nauranut\", sillä hän pelkäsi. Mutta hän sanoi: \"Ei ole niin. Sinä nauroit.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Sitten miehet nousivat siitä ja kääntyivät Sodomaan päin, ja Aabraham kulki heidän kanssaan saattaakseen heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Herra sanoi: \"Salaisinko minä Aabrahamilta, mitä olen tekevä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Onhan Aabrahamista tuleva suuri ja voimakas kansa, ja kaikki kansakunnat maan päällä tulevat hänessä siunatuiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Sillä olen valinnut hänet, että hän käskisi lapsiaan ja perhettään, joka jää hänen jälkeensä, noudattamaan Herran tietä ja tekemään sitä, mikä on vanhurskaus ja oikeus, jotta Herra antaisi Aabrahamille tapahtua, mitä hän on hänelle luvannut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Herra sanoi: \"Valitushuuto Sodoman ja Gomorran tähden on suuri, ja heidän syntinsä ovat hyvin raskaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Sen tähden menen alas katsomaan, ovatko he todella tehneet kaiken sen, josta huuto on tullut eteeni, vai eivät. Tahdon sen tietää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Miehet kääntyivät sieltä ja kulkivat Sodomaan päin, mutta Aabraham jäi vielä seisomaan Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Aabraham lähestyi häntä ja sanoi: \"Aiotko siis hukuttaa vanhurskaan yhdessä jumalattoman kanssa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Entä jos kaupungissa on viisikymmentä vanhurskasta? Aiotko hukuttaa heidät etkä säästä paikkaa siellä olevien viidenkymmenen vanhurskaan tähden?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Pois se, että näin tekisit: surmaisit vanhurskaan yhdessä jumalattoman kanssa, niin että vanhurskaan kävisi samoin kuin jumalattoman! Pois se sinusta! Eikö kaiken maan tuomari tekisi oikeutta?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Herra sanoi: \"Jos löydän Sodoman kaupungista viisikymmentä vanhurskasta, niin säästän heidän tähtensä koko paikan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Aabraham vastasi ja sanoi: \"Katso, olen rohjennut puhua Herralleni, vaikka olen tomu ja tuhka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Entä jos viidestäkymmenestä vanhurskaasta puuttuu viisi? Hävitätkö viiden tähden koko kaupungin?\" Hän sanoi: \"En hävitä, jos löydän sieltä neljäkymmentä viisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Hän puhui vielä hänelle sanoen: \"Entä jos siellä on neljäkymmentä?\" Hän vastasi: \"Niiden neljänkymmenen tähden jätän sen tekemättä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Aabraham sanoi: \"Älköön Herrani vihastuko, että vielä puhun. Entä jos siellä on kolmekymmentä?\" Hän vastasi: \"En tee sitä, jos löydän sieltä kolmekymmentä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Mutta hän sanoi: \"Katso, minä olen rohjennut puhua Herralleni. Entä jos siellä on kaksikymmentä?\" Hän vastasi: \"Niiden kahdenkymmenen tähden jätän hävittämättä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Hän sanoi: \"Älköön Herrani vihastuko, että puhun vielä tämän ainoan kerran. Entä jos siellä on kymmenen?\" Hän vastasi: \"Niiden kymmenen tähden jätän hävittämättä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Herra lähti pois, sen jälkeen kun hän oli lakannut puhumasta Aabrahamin kanssa, ja Aabraham palasi kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Ne kaksi enkeliä saapuivat Sodomaan illalla, ja Loot istui Sodoman portissa. Nähtyään heidät Loot nousi heitä vastaan ja kumartui maahan kasvoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Hän sanoi: \"Katsokaahan, herrani, poiketkaa palvelijanne taloon yöksi ja peskää jalkanne! Aamulla varhain voitte jatkaa matkaanne.\" He sanoivat: \"Emme, vaan me jäämme yöksi ulos.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Mutta hän pyysi heitä pyytämällä, ja he poikkesivat hänen luokseen ja tulivat hänen taloonsa. Niin hän valmisti heille aterian ja leipoi happamattomia leipiä, ja he söivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Ennen kuin he olivat laskeutuneet levolle, kaupungin miehet, sodomalaiset, sekä nuoret että vanhat, koko kansa kaikkialta, piirittivät talon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'He huusivat Lootia sanoen hänelle: \"Missä ovat ne miehet, jotka tulivat luoksesi yöllä? Tuo heidät tänne luoksemme yhtyäksemme heihin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Silloin Loot meni ulos heidän luokseen portille ja sulki oven jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'Hän sanoi: \"Älkää, veljeni, tehkö niin pahoin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Katsokaa, minulla on kaksi tytärtä, jotka eivät vielä tiedä miehestä. Tuon heidät teille, tehkää heille, mitä tahdotte. Älkää vain tehkö näille miehille mitään pahaa, sillä he ovat tulleet minun kattoni suojaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Mutta he vastasivat: \"Mene tiehesi!\" He sanoivat: \"Tuo yksi on tullut tänne asumaan muukalaisena, ja toimii tosiaan tuomarina. Nytpä me pitelemmekin sinua pahemmin kuin heitä.\" He tunkeutuivat väkivaltaisesti miehen, Lootin, kimppuun ja kävivät murtamaan ovea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Mutta miehet ojensivat kätensä, vetivät Lootin luokseen huoneeseen ja sulkivat oven.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'He sokaisivat ne miehet, jotka olivat talon ovella, sekä nuoret että vanhat, niin että he yrittivät turhaan löytää ovea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Miehet sanoivat Lootille: \"Vieläkö sinulla on ketään omaista täällä? Vie pois täältä vävysi, poikasi, tyttäresi ja kaikki, keitä sinulla on kaupungissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Sillä me hävitämme tämän paikan. Koska huuto heistä on käynyt suureksi Herran edessä, Herra lähetti meidät hävittämään sen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Loot meni puhuttelemaan vävyjään, joiden oli aikomus ottaa hänen tyttärensä, ja sanoi: \"Nouskaa, lähtekää pois tästä paikasta, sillä Herra hävittää tämän kaupungin.\" Mutta hänen vävynsä luulivat hänen laskevan leikkiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Mutta aamun sarastaessa enkelit kiirehtivät Lootia sanoen: \"Nouse, ota vaimosi ja molemmat tyttäresi, jotka ovat luonasi, ettet kuolisi kaupungin syntivelan tähden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Kun hän vielä vitkasteli, miehet tarttuivat hänen käteensä sekä hänen vaimonsa ja molempien tyttäriensä käteen, sillä Herra tahtoi säästää hänet, ja veivät hänet ulos ja jättivät hänet kaupungin ulkopuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Viedessään heitä ulos mies sanoi: \"Pakene henkesi tähden, älä katsele taaksesi äläkä pysähdy mihinkään alangolla. Pakene vuorille, ettet hukkuisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Mutta Loot sanoi heille: \"Oi Herrani, ei niin!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Katso, palvelijasi on saanut armon silmiesi edessä, ja suuri on laupeutesi, jota olet minulle osoittanut pelastaaksesi henkeni, mutta minä en voi päästä pakoon vuorille. Pelkään, että onnettomuus saavuttaa minut ja minä kuolen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Katso, tuolla on lähellä vähän matkan päässä kaupunki paetakseni sinne. Salli minun pelastua sinne – onhan se vain vähän matkan päässä – jäädäkseni eloon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Hän sanoi hänelle: \"Katso, minä teen sinulle mieliksi tässäkin kohden. En hävitä kaupunkia, josta puhut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Pakene nopeasti sinne, sillä en voi tehdä mitään, ennen kuin olet saapunut sinne.\" Siitä kaupunki sai nimekseen Sooar.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Aurinko oli noussut, kun Loot saapui Sooariin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Herra antoi sataa Sodoman ja Gomorran päälle rikkiä ja tulta Herralta taivaalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Hän hävitti nämä kaupungit ja koko alangon sekä kaikki niiden kaupunkien asukkaat ja maan kasvillisuuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Mutta hänen vaimonsa, joka oli tullut hänen jäljessään, katsoi taakseen, ja muuttui suolapatsaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Aabraham nousi varhain aamulla ja meni siihen paikkaan, jossa hän oli seisonut Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Hän katseli Sodomaan ja Gomorraan päin ja yli koko alangon, ja katso, maasta nousi paksu savu niin kuin sulatusuunin savu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Kun Jumala tuhosi alangon kaupungit, Jumala muisti Aabrahamia ja johdatti Lootin pois hävityksen keskeltä hävittäessään ne kaupungit, joissa Loot oli asunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Loot lähti Sooarista ja asettui vuoristoon molempien tyttäriensä kanssa, sillä hän pelkäsi asua Sooarissa. Hän asui luolassa, hän ja hänen molemmat tyttärensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Niin vanhempi sanoi nuoremmalle: \"Isämme on vanha, eikä tässä maassa ole ketään miestä, joka voisi tulla luoksemme siten, kuin on kaiken maan tapa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Tule, juottakaamme isällemme viiniä ja maatkaamme hänen kanssaan saadaksemme isästämme jälkeläisen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Niin he juottivat sinä yönä isälleen viiniä. Vanhempi meni ja makasi hänen kanssaan, eikä tämä huomannut, milloin hän tuli hänen viereensä ja milloin hän nousi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Seuraavana päivänä vanhempi sanoi nuoremmalle: \"Katso, minä makasin viime yönä isäni kanssa. Juottakaamme hänelle tänäkin yönä viiniä. Mene sinä ja makaa hänen kanssaan saadaksemme isästämme jälkeläisen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Niin he juottivat sinäkin yönä isälleen viiniä, ja nuorempi meni ja makasi hänen kanssaan, eikä tämä huomannut, milloin hän tuli hänen viereensä ja milloin hän nousi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Lootin molemmat tyttäret tulivat raskaaksi isästään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Vanhempi synnytti pojan ja antoi hänelle nimen Mooab. Hänestä polveutuvat mooabilaiset aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Nuorempikin synnytti pojan ja antoi hänelle nimen Ben-Ammi. Hänestä polveutuvat ammonilaiset aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Aabraham siirtyi sieltä Negeviin ja asettui Kaadeksen ja Suurin välille. Hän asui jonkin aikaa Gerarissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Aabraham sanoi vaimostaan Saarasta: \"Hän on sisareni.\" Abimelek, Gerarin kuningas, lähetti noutamaan Saaran luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Mutta Jumala tuli Abimelekin luo yöllä unessa ja sanoi hänelle: \"Katso, sinun on kuoltava sen vaimon tähden, jonka olet ottanut, sillä hän on toisen miehen aviovaimo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Mutta Abimelek ei ollut yhtynyt häneen, ja hän sanoi: \"Herra, surmaatko syyttömänkin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Eikö hän itse sanonut minulle: \'Hän on sisareni\'? Samoin tämäkin sanoi: \'Hän on veljeni.\' Olen tehnyt tämän vilpittömin sydämin ja viattomin käsin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Jumala sanoi hänelle unessa: \"Minäkin tiedän, että sinä teit sen vilpittömin sydämin. Sen tähden minä estinkin sinua tekemästä syntiä minua vastaan enkä sallinut sinun kajota häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Anna nyt miehelle hänen vaimonsa takaisin, sillä hän on profeetta, ja hän on rukoileva puolestasi, että saisit elää. Mutta ellet anna häntä takaisin, niin tiedä, että olet totisesti kuoleva, sinä ja kaikki omaisesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Abimelek nousi varhain aamulla ja kutsui kaikki palvelijansa ja kertoi heille tämän kaiken, ja miehet olivat kovin peloissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Abimelek kutsui Aabrahamin ja sanoi hänelle: \"Mitä oletkaan meille tehnyt! Mitä olen rikkonut sinua vastaan, koska olet saattanut minut ja valtakuntani syypääksi näin suureen rikokseen? Sinä olet tehnyt minulle, mitä ei sovi tehdä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Abimelek sanoi vielä Aabrahamille: \"Mikä oli tarkoituksesi, kun tämän teit?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Aabraham vastasi: \"Ajattelin näin: \'Tällä paikkakunnalla ei varmaankaan pelätä Jumalaa. He surmaavat minut vaimoni tähden.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Hän onkin todella sisareni, isäni tytär, vaikkei olekaan äitini tytär, ja niin hänestä tuli vaimoni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Mutta kun Jumala lähetti minut kulkemaan pois isäni kodista, sanoin vaimolleni: \'Osoita minulle se rakkaus, että mihin paikkaan ikinä tulemmekin, sanot minusta: hän on veljeni.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Abimelek otti lampaita ja vuohia, nautoja, palvelijoita ja palvelijattaria ja antoi ne Aabrahamille ja lähetti hänen vaimonsa Saaran hänelle takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Abimelek sanoi: \"Katso, maani on avoinna edessäsi. Asu, missä mielesi tekee!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Saaralle hän sanoi: \"Katso, annan veljellesi tuhat sekeliä hopeaa. Olkoot ne sinulle hyvitykseksi kaikkien niiden edessä, jotka ovat kanssasi. Niin olet kaikkien edessä todistettu viattomaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Mutta Aabraham rukoili Jumalaa, ja Jumala paransi Abimelekin ja hänen vaimonsa ja hänen orjattarensa, niin että he synnyttivät lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Sillä Herra oli sulkenut jokaisen kohdun Abimelekin huoneessa Saaran, Aabrahamin vaimon, tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Herra piti Saarasta huolen, kuten oli luvannut. Herra teki Saaralle, niin kuin oli puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Saara tuli raskaaksi ja synnytti Aabrahamille pojan hänen vanhoilla päivillään, juuri sinä aikana, jonka Jumala oli hänelle sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Aabraham antoi pojalleen, joka oli hänelle syntynyt, sille, jonka Saara oli hänelle synnyttänyt, nimen Iisak.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Aabraham ympärileikkasi poikansa Iisakin tämän ollessa kahdeksan päivän vanha, niin kuin Jumala oli käskenyt hänen tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Aabraham oli sadan vuoden vanha, kun hänen poikansa Iisak syntyi hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Saara sanoi: \"Jumala on saattanut minut riemuitsemaan. Kuka ikinä saa tämän kuulla, se nauraa kanssani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Hän sanoi vielä: \"Kuka olisi tiennyt sanoa Aabrahamille: Saara on imettävä lapsia? Nyt minä kuitenkin olen synnyttänyt hänelle pojan hänen vanhoilla päivillään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Poika kasvoi, ja hänet vieroitettiin. Aabraham laittoi suuret pidot siksi päiväksi, jona Iisak vieroitettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Saara näki egyptiläisen Haagarin pojan, jonka tämä oli Aabrahamille synnyttänyt, ilkkuvan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'ja sanoi Aabrahamille: \"Aja pois tuo orjatar poikineen, sillä orjattaren poika ei saa periä poikani, Iisakin, kanssa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Aabraham pahastui suuresti tästä puheesta poikansa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Mutta Jumala sanoi Aabrahamille: \"Älä pahastu siitä poikasi ja orjattaresi tähden. Kuule Saaraa kaikessa, mitä hän sinulle sanoo, sillä ainoastaan Iisakista sinä saat nimellesi jälkeläiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Mutta myös orjattaren pojasta minä teen suuren kansan, koska hän on jälkeläisesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Varhain seuraavana aamuna Aabraham otti leipää ja vesileilin ja antoi ne Haagarille pannen ne hänen olalleen sekä pojan ja lähetti Haagarin menemään. Hän lähti ja harhaili Beerseban erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Mutta kun vesi loppui leilistä, hän heitti pojan pensaan alle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'ja meni istumaan syrjään jousenkantaman päähän, sillä hän ajatteli: \"En voi nähdä pojan kuolevan.\" Istuessaan siinä syrjässä Haagar korotti äänensä ja itki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Jumala kuuli pojan valituksen, ja Jumalan enkeli huusi taivaasta Haagarille sanoen: \"Mikä sinun on, Haagar? Älä pelkää, sillä Jumala on kuullut pojan valituksen siinä, missä hän makaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Nouse, nosta poika maasta ja tartu hänen käteensä, sillä minä teen hänestä suuren kansan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Jumala avasi hänen silmänsä, niin että hän huomasi vesikaivon. Hän meni ja täytti leilin vedellä ja antoi pojan juoda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Jumala oli pojan kanssa, ja hän kasvoi ja asui erämaassa, ja hänestä tuli jousimies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Hän asui Paaranin erämaassa, ja hänen äitinsä otti hänelle vaimon Egyptin maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Siihen aikaan Abimelek ja hänen sotapäällikkönsä Piikol puhuivat Aabrahamille sanoen: \"Jumala on kanssasi kaikessa, mitä teet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Vanno nyt tässä minulle Jumalan kautta, ettet ole oleva petollinen minulle etkä suvulleni etkä jälkeläisilleni, vaan tee sinäkin laupeus minulle ja sille maalle, jossa muukalaisena asut, niin kuin olen sinulle tehnyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Aabraham sanoi: \"Minä vannon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Aabraham nuhteli kuitenkin Abimelekia vesikaivon tähden, jonka Abimelekin palvelijat olivat vallanneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Mutta Abimelek vastasi: \"En tiedä, kuka sen on tehnyt. Et ole itse minulle mitään ilmoittanut, enkä ole siitä kuullut ennen kuin tänään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Silloin Aabraham otti lampaita ja vuohia ja nautoja ja antoi Abimelekille, ja he tekivät molemmat keskenään liiton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Aabraham asetti laumasta seitsemän naaraslampaan karitsaa erilleen muista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Silloin Abimelek sanoi Aabrahamille: \"Mitä tarkoittavat nuo seitsemän karitsaa, jotka olet asettanut tuonne erilleen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Hän vastasi: \"Nämä seitsemän karitsaa on sinun otettava minun kädestäni todistukseksi minulle siitä, että tämä kaivo on minun kaivamani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Sen vuoksi sitä paikkaa on sanottu Beersebaksi, koska he molemmat vannoivat siinä toisilleen valan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'He tekivät liiton Beersebassa. Abimelek nousi ja myös Piikol, hänen sotapäällikkönsä, ja he palasivat filistealaisten maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Aabraham istutti tamariskipuun Beersebaan ja saarnasi siinä Herran, iankaikkisen Jumalan nimestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Aabraham asui kauan muukalaisena filistealaisten maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Näiden tapausten jälkeen Jumala koetteli Aabrahamia ja sanoi hänelle: \"Aabraham!\" Hän vastasi: \"Tässä olen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Hän sanoi: \"Ota Iisak, ainoa poikasi, jota rakastat, ja mene Moorian maahan ja uhraa hänet siellä polttouhriksi vuorella, jonka sinulle sanon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Varhain seuraavana aamuna Aabraham satuloi aasinsa ja otti mukaansa kaksi palvelijaansa sekä poikansa Iisakin. Pilkottuaan polttouhripuita hän lähti menemään siihen paikkaan, jonka Jumala oli hänelle sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Kolmantena päivänä Aabraham nosti silmänsä ja näki paikan kaukaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Silloin Aabraham sanoi palvelijoilleen: \"Jääkää tähän aasin kanssa. Minä ja poika menemme tuonne rukoilemaan ja palaamme luoksenne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Aabraham otti polttouhripuut ja pani ne poikansa Iisakin selkään. Itse hän otti käteensä tulen ja veitsen, ja niin he kulkivat molemmat yhdessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Iisak puhui isälleen Aabrahamille sanoen: \"Isäni!\" Tämä vastasi: \"Tässä olen, poikani.\" Hän sanoi: \"Katso, tässä on tuli ja polttopuut, mutta missä on lammas polttouhriksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Aabraham vastasi: \"Jumala on katsova itselleen lampaan polttouhriksi, poikani.\" He kulkivat molemmat yhdessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Kun he olivat tulleet siihen paikkaan, jonka Jumala oli hänelle sanonut, Aabraham rakensi siihen alttarin, latoi sille polttopuut, sitoi poikansa Iisakin ja pani hänet alttarille puiden päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Aabraham ojensi kätensä ja tarttui veitseen teurastaakseen poikansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Silloin Herran Enkeli huusi hänelle taivaasta sanoen: \"Aabraham, Aabraham!\" Hän vastasi: \"Tässä olen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Niin hän sanoi: \"Älä satuta kättäsi poikaan äläkä tee hänelle mitään, sillä nyt minä tiedän, että sinä pelkäät Jumalaa, kun et kieltänyt minulta ainoaa poikaasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Aabraham nosti silmänsä ja huomasi takanaan pässin, joka oli sarvistaan takertunut pensaikkoon. Aabraham meni, otti pässin ja uhrasi sen polttouhriksi poikansa sijasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Aabraham pani sen paikan nimeksi \" Herra näkee.\" Niinpä vielä tänä päivänä sanotaan: \"Vuorella, missä Herra tullaan näkemään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Herran Enkeli huusi Aabrahamille toistamiseen taivaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'Hän sanoi: \"Minä vannon itseni kautta, sanoo Herra: Sen tähden että tämän teit etkä kieltänyt minulta ainoaa poikaasi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'minä siunaan runsaasti sinua ja teen jälkeläistesi luvun paljoksi kuin taivaan tähdet ja hiekka, joka on meren rannalla, ja jälkeläisesi valtaavat vihollistensa portit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Sinun Siemenessäsi tulevat siunatuiksi kaikki kansakunnat maan päällä, sen tähden että olit minun äänelleni kuuliainen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Sitten Aabraham palasi palvelijoidensa luo, ja he nousivat ja kulkivat yhdessä Beersebaan, ja Aabraham jäi asumaan Beersebaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Näiden tapausten jälkeen ilmoitettiin Aabrahamille: \"Katso, myös Milka on synnyttänyt poikia veljellesi Naahorille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Nämä olivat Uus, hänen esikoisensa, tämän veli Buus, Kemuel, Aramin isä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Kesed, Haso, Pildas, Jidlaf ja Betuel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Betuelille syntyi Rebekka. Nämä kahdeksan synnytti Milka Naahorille, Aabrahamin veljelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Hänen sivuvaimonsa, nimeltä Reuma, synnytti myös lapsia: Tebahin, Gahamin, Tahaan ja Maakan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Saara eli sadan kahdenkymmenen seitsemän vuoden vanhaksi. Niin vanhaksi eli Saara.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Saara kuoli Kirjat-Arbassa, se on Hebronissa, Kanaanin maassa. Aabraham meni suremaan Saaraa ja itkemään häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Aabraham nousi ja lähti vainajan luota ja puhui heettiläisille sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, '\"Minä olen muukalainen ja vieras keskuudessanne. Antakaa minulle perintöhauta maassanne haudatakseni ja kätkeäkseni siihen vainajani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Heettiläiset vastasivat Aabrahamille sanoen hänelle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, '\"Kuule meitä, herra. Sinä olet Jumalan ruhtinas keskuudessamme. Hautaa vainajasi parhaaseen hautaamme. Ei kukaan meistä kiellä sinua hautaamasta vainajaasi hautaansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Aabraham nousi ja kumarsi maan kansalle, heettiläisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Hän puhui heille sanoen: \"Jos teille sopii, että hautaan ja kätken vainajani, niin kuulkaa minua ja taivuttakaa Efron, Sooharin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'antamaan minulle Makpelan luola, joka on hänen omansa ja on hänen vainionsa perällä. Täydestä hinnasta hän antakoon sen minulle perintöhaudaksi teidän keskuudessanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Efron istui siellä heettiläisten joukossa. Efron, heettiläinen, vastasi Aabrahamille heettiläisten kuullen, kaikkien, jotka kulkivat hänen kaupunkinsa portista, sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, '\"Ei, herrani, vaan kuule minua. Vainion lahjoitan sinulle ja myös luolan, joka siinä on, lahjoitan sinulle. Kansalaisteni nähden sen sinulle lahjoitan. Hautaa vainajasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Aabraham kumarsi maan kansalle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'ja puhui Efronille, maan kansan kuullen, sanoen: \"Jospa kuitenkin – oi, kuule minua! – maksan vainion hinnan. Ota se minulta ja anna minun haudata siihen vainajani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Efron vastasi Aabrahamille, sanoen hänelle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, '\"Herrani, kuule minua. Neljänsadan hopeasekelin maa, mitä se minulle ja sinulle merkitsee? Hautaa vainajasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Kuultuaan Efronin sanat Aabraham punnitsi Efronille sen rahasumman, jonka tämä oli maininnut heettiläisten kuullen, neljäsataa hopeasekeliä, kaupassa käypää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Niin Efronin vainio, joka on Makpelassa itään päin Mamresta, sekä vainio että siellä oleva luola sekä kaikki puut, jotka kasvoivat vainiolla, koko sillä alueella,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'tulivat Aabrahamin omiksi kaikkien heettiläisten nähden, jotka kulkivat hänen kaupunkinsa portista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Sen jälkeen Aabraham hautasi vaimonsa Saaran luolaan, joka on Makpelan vainiolla itään Mamresta, se on Hebronista, Kanaanin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Vainio ja siellä oleva luola siirtyi heettiläisiltä Aabrahamille perintöhaudaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Aabraham oli tullut iältään vanhaksi, ja Herra oli siunannut Aabrahamia kaikessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Aabraham sanoi palvelijalleen, talonsa vanhimmalle, joka hallitsi kaikkea, mitä hänellä oli: \"Pane kätesi kupeeni alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Minä vannotan sinua Herran, taivaan ja maan Jumalan, kautta, ettet ota pojalleni vaimoa kanaanilaisten tyttäristä, joiden keskuudessa minä asun,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'vaan että menet minun omaan maahani ja sukuni luo ja otat sieltä vaimon pojalleni Iisakille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Palvelija sanoi hänelle: \"Entä jos nainen ei tahdo seurata minua tähän maahan, onko minun silloin vietävä poikasi takaisin siihen maahan, josta olet lähtenyt?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Aabraham vastasi hänelle: \"Varo, ettet vie poikaani takaisin sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Herra, taivaan Jumala, joka otti minut pois isäni kodista ja synnyinmaastani, hän, joka puhui minulle ja vannoi minulle sanoen: \'Sinun jälkeläisillesi annan tämän maan\', hän lähettää enkelinsä edelläsi, niin että saat sieltä vaimon pojalleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Mutta jos nainen ei tahdo seurata sinua, olet tästä valasta vapaa. Älä vain vie poikaani sinne takaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Palvelija pani kätensä herransa Aabrahamin kupeen alle ja lupasi sen hänelle valalla vannoen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Palvelija otti herransa kameleista kymmenen sekä kaikenlaisia kalleuksia herransa tavaroista, nousi ja lähti Mesopotamiaan, Naahorin kaupunkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Hän antoi kamelien asettua kaupungin ulkopuolelle vesikaivon luo lepäämään illan suussa, jolloin naiset tulivat vettä ammentamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Hän sanoi: \" Herra, minun herrani Aabrahamin Jumala, suo minulle tänään menestystä ja tee laupeus herralleni Aabrahamille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Katso, minä seison tässä lähteellä, ja kaupunkilaisten tyttäret tulevat ammentamaan vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Tapahtukoon, että tyttö, jolle sanon: \'Kallista tänne vesiastiaasi juodakseni\', ja joka vastaa: \'Juo, juotan kamelisikin\', on juuri se, jonka sinä olet määrännyt palvelijallesi Iisakille, ja siitä tiedän, että olet tehnyt laupeuden herralleni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Tuskin hän oli lakannut puhumasta, kun siihen tuli Rebekka, joka oli Aabrahamin veljen Naahorin ja hänen vaimonsa Milkan pojan, Betuelin, tytär, ja hänellä oli vesiastia olallaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Tyttö oli näöltään hyvin ihana, neitsyt, johon ei mies ollut koskenut. Hän astui alas lähteelle, täytti astiansa ja tuli ylös.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Silloin palvelija riensi häntä vastaan ja sanoi: \"Anna minun juoda vähän vettä astiastasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Hän vastasi: \"Juo, herrani.\" Hän laski nopeasti astiansa alas kädelleen ja antoi hänen juoda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Annettuaan hänen juoda hän sanoi: \"Minä ammennan vettä myös kameleillesi, kunnes ne ovat juoneet kyllikseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Hän tyhjensi nopeasti astiansa juottokaukaloon ja riensi uudestaan kaivolle ammentamaan vettä ja ammensi kaikille hänen kameleilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Mies katseli häntä ääneti saadakseen tietää, oliko Herra antanut hänen matkansa onnistua vai ei.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Kun kamelit olivat juoneet, mies otti esiin kultaisen nenärenkaan, joka painoi puoli sekeliä, ja pani hänen käsiinsä kaksi rannerengasta, jotka painoivat kymmenen kultasekeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Hän kysyi: \"Kenen tytär olet? Sano minulle. Onko isäsi talossa tilaa yöpyäksemme siinä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Hän vastasi hänelle: \"Olen Betuelin, Naahorin ja Milkan pojan, tytär.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Hän sanoi hänelle vielä: \"Meillä on runsaasti olkia ja rehua. Meillä on myös paikka yöpyä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Silloin mies kumartui maahan ja rukoili Herraa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'ja sanoi: \"Kiitetty olkoon Herra, minun herrani Aabrahamin Jumala, joka ei ole ottanut pois armoaan ja totuuttaan minun herraltani. Herra on johdattanut minut tätä tietä herrani veljen kotiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Tyttö riensi ilmoittamaan äitinsä perheelle, mitä oli tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Rebekalla oli veli, jonka nimi oli Laaban. Laaban riensi ulos miehen luo lähteelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Sillä kun hän näki nenärenkaan ja rannerenkaat sisarensa käsissä ja kuuli sisarensa Rebekan kertovan ja sanovan: \"Näin mies puhui minulle\", hän meni miehen luo – ja katso, hän seisoi vielä kamelien luona lähteellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Hän sanoi hänelle: \"Tule sisään, sinä Herran siunattu. Minkä tähden seisot ulkona? Minä olen valmistanut tilaa talossa ja sijaa kameleille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Mies tuli taloon, ja Laaban riisui kamelit ja antoi kameleille olkia ja rehua sekä hänelle ja hänen seuralaisilleen vettä jalkojen pesuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Sitten pantiin ruokaa hänen eteensä, mutta hän sanoi: \"En syö, ennen kuin olen puhunut asiani.\" Laaban vastasi: \"Puhu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Hän sanoi: \"Minä olen Aabrahamin palvelija.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Herra on suuresti siunannut herraani, niin että hänestä on tullut mahtava mies. Hän on antanut hänelle lampaita, vuohia ja nautoja, hopeaa ja kultaa, palvelijoita ja palvelijattaria, kameleja ja aaseja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Saara, herrani vaimo, on vanhalla iällään synnyttänyt herralleni pojan, jolle herrani on antanut kaiken omaisuutensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Herrani vannotti minua sanoen: \'Älä ota pojalleni vaimoa kanaanilaisten tyttäristä, joiden maassa minä asun,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'vaan mene isäni kotiin ja sukuni luo ja ota sieltä pojalleni vaimo.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Silloin sanoin herralleni: \'Entä jos tyttö ei seuraa minua?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Hän vastasi minulle: \' Herra, jonka edessä olen vaeltanut, lähettää enkelinsä kanssasi ja antaa matkasi onnistua, niin että saat pojalleni vaimon suvustani ja isäni perheestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Silloin, kun saavut sukuni luo, olet vapaa valasta, jonka minulle vannoit. Jos he eivät häntä sinulle anna, olet valasta vapaa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Tulin tänään lähteelle ja sanoin: \' Herra, herrani Aabrahamin Jumala! Jos annat onnistua sen matkan, jolla olen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'salli tapahtua, että neitsyt, joka minun seisoessani tässä vesilähteellä tulee ammentamaan vettä ja sanoessani hänelle: \'Anna minun juoda vähän vettä astiastasi\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'vastaa minulle: \'Juo itse, ja ammennan myös kameleillesi\' – että hän on se nainen, jonka Herra on määrännyt herrani pojalle.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Tuskin olin lakannut näin puhumasta itsekseni, katso, Rebekka tuli siihen vesiastia olallaan, astui alas lähteelle ja ammensi. Sanoin hänelle: \'Anna minun juoda.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Hän laski nopeasti astian alas olaltaan ja sanoi: \'Juo, juotan myös kamelisi.\' Join, ja hän juotti myös kamelit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Kysyin häneltä sanoen: \'Kenen tytär olet?\' Hän vastasi: \'Olen Betuelin, Naahorin ja Milkan pojan, tytär.\' Panin nenärenkaan hänen nenäänsä ja rannerenkaat hänen käsiinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Kumarruin maahan ja rukoilin Herraa, kiittäen Herraa, herrani Aabrahamin Jumalaa, joka oli johdattanut minut oikeaa tietä saamaan herrani veljen tyttären hänen pojalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Jos nyt tahdotte osoittaa suosiota ja uskollisuutta herralleni, ilmoittakaa se minulle. Mutta jos ette, niin ilmoittakaa sekin minulle kääntyäkseni toisaalle, oikealle tai vasemmalle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Laaban ja Betuel vastasivat sanoen: \" Herralta tämä on tullut. Emme voi tässä asiassa puhua sinulle hyvää emmekä pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Katso, siinä on Rebekka edessäsi, ota hänet ja mene. Tulkoon hän herrasi pojan vaimoksi, niin kuin Herra on sanonut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Kuultuaan heidän sanansa Aabrahamin palvelija kumartui maahan Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Sitten palvelija otti esille hopea- ja kultaesineitä sekä vaatteita ja antoi ne Rebekalle. Hän antoi kallisarvoisia lahjoja myös hänen veljelleen ja äidilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'He söivät ja joivat, hän ja hänen seuralaisensa, ja olivat siellä yötä. Mutta kun he olivat nousseet seuraavana aamuna, hän sanoi: \"Päästäkää minut menemään herrani luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Tytön veli ja äiti vastasivat: \"Anna tytön viipyä luonamme vielä jonkin aikaa, edes kymmenen päivää. Sitten lähde.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Mutta hän sanoi heille: \"Älkää viivyttäkö minua, koska Herra on antanut matkani onnistua. Päästäkää minut menemään, tahdon lähteä herrani luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'He vastasivat: \"Kutsukaamme tänne tyttö ja kysykäämme häneltä itseltään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'He kutsuivat Rebekan ja sanoivat hänelle: \"Tahdotko lähteä tämän miehen kanssa?\" Hän vastasi: \"Tahdon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'He lähettivät sisarensa Rebekan imettäjineen matkalle Aabrahamin palvelijan ja hänen miestensä mukana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'He siunasivat Rebekan ja lausuivat hänelle: \"Oi sisaremme, tulkoon sinusta tuhat kertaa kymmenentuhatta, ja vallatkoot siemenesi vihamiestensä portit!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Rebekka nousi palvelijattarineen, ja he istuivat kamelien selkään ja seurasivat miestä. Palvelija otti Rebekan mukaansa ja lähti matkalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Iisak oli tulossa Lahai-Roin kaivon tienoilta. Hän asui näet Negevissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Iisak oli illan suussa lähtenyt kedolle kävelemään, ja kun hän nosti silmänsä, hän näki kamelien lähestyvän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Kun Rebekka nosti silmänsä ja näki Iisakin, hän pudottautui nopeasti maahan kamelin selästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Hän kysyi palvelijalta: \"Kuka on tuo mies, joka tulee kedolla meitä vastaan?\" Palvelija vastasi: \"Hän on herrani.\" Niin hän otti hunnun ja verhoutui siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Palvelija kertoi Iisakille kaikki, mitä hän oli toimittanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Iisak vei Rebekan äitinsä Saaran majaan ja otti hänet luokseen, ja hänestä tuli hänen vaimonsa, ja hän rakasti häntä. Iisak sai lohdutuksen äitinsä kuoltua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Aabraham otti vielä vaimon. Hänen nimensä oli Ketura.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Hän synnytti hänelle Simranin ja Joksanin, Medanin ja Midianin, Jisbakin ja Suuahin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Joksanille syntyi Seba ja Dedan. Dedanin jälkeläisiä olivat assurilaiset, letusilaiset ja leummilaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Midianin pojat olivat Eefa, Eefer, Hanok, Abida ja Eldaa. Kaikki nämä ovat Keturan jälkeläisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Aabraham antoi kaiken omaisuutensa Iisakille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Mutta sivuvaimojensa pojille Aabraham antoi lahjoja. Hän lähetti heidät vielä eläessään pois poikansa Iisakin luota idän suuntaan, Itäiselle maalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Tämä on Aabrahamin elinvuosien luku: sata seitsemänkymmentä viisi vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Aabraham vaipui kuolemaan korkeassa iässä, vanhana ja elämästä kyllikseen saaneena, ja tuli otetuksi heimonsa luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Hänen poikansa Iisak ja Ismael hautasivat hänet Makpelan luolaan, heettiläisen Efronin, Sooharin pojan, vainiolle, joka on Mamren edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'sille vainiolle, jonka Aabraham oli ostanut heettiläisiltä. Siihen haudattiin Aabraham ja hänen vaimonsa Saara.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Aabrahamin kuoltua Jumala siunasi hänen poikaansa Iisakia. Iisak asui Lahai-Roin kaivon tienoilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Tämä on Ismaelin suvun syntykirja. Aabrahamin pojan, jonka Saaran egyptiläinen orjatar Haagar synnytti Aabrahamille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Nämä ovat Ismaelin poikien nimet heidän nimiensä ja polveutumisensa mukaan: Nebajot, Ismaelin esikoinen, Keedar, Adbeel, Mibsam,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Misma, Duuma, Massa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadad, Teema, Jetur, Naafis ja Keedma.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Nämä ovat Ismaelin pojat ja nämä ovat heidän nimensä heidän kyliensä ja leiripaikkojensa mukaan, kaksitoista ruhtinasta heimokuntineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Tämä on Ismaelin elinvuosien luku: sata kolmekymmentä seitsemän vuotta. Hän vaipui kuolemaan ja tuli otetuksi heimonsa luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'He asuivat Havilasta aina Suuriin asti, joka on Egyptistä itään Assyriaan mentäessä. Hän asettui asumaan kaikkien veljiensä eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Tämä on Iisakin, Aabrahamin pojan, suvun syntykirja. Aabrahamille syntyi Iisak.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Iisak oli neljänkymmenen vuoden vanha, kun hän otti vaimokseen Rebekan, joka oli aramilaisen Betuelin tytär Mesopotamiasta ja aramilaisen Laabanin sisar.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Iisak rukoili Herraa vaimonsa puolesta, sillä tämä oli hedelmätön. Herra kuuli hänen rukouksensa, ja hänen vaimonsa Rebekka tuli raskaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Lapset sysäsivät toisiaan hänen kohdussaan. Niin hän sanoi: \"Jos näin käy, miksi tämä tapahtuu minulle?\" Hän meni kysymään Herralta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Herra sanoi hänelle: \"Kaksi kansaa on kohdussasi, kaksi heimoa lähtee ruumiistasi, toinen heimo on toista voimakkaampi, vanhempi palvelee nuorempaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Kun hänen synnyttämisensä aika oli tullut, katso, hänen kohdussaan oli kaksoset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Se, joka ensiksi tuli hänen kohdustaan, oli ruskea ja yltympäri kuin karvainen viitta. Hänelle annettiin nimeksi Eesau.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Sen jälkeen tuli ulos hänen veljensä. Hän piti kädellään Eesauta kantapäästä. Hänelle annettiin nimeksi Jaakob. Iisak oli kuudenkymmenen vuoden vanha heidän syntyessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Pojat kasvoivat suuriksi. Eesausta tuli taitava metsästäjä, eränkävijä. Jaakob sitä vastoin oli hurskas ja asui teltoissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Iisak rakasti enemmän Eesauta, sillä hän söi mielellään riistaa, mutta Rebekka rakasti enemmän Jaakobia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Kerran, kun Jaakob oli keittänyt itselleen keiton, Eesau tuli kedolta nälästä näännyksissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Eesau sanoi Jaakobille: \"Anna minun ahmia tuota ruskeaa, tuota ruskeaa keittoa, sillä minä olen nälästä näännyksissä.\" Sen tähden hän sai nimen Edom.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Mutta Jaakob sanoi: \"Myy minulle ensin esikoisuutesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Eesau vastasi: \"Katso, minä kuolen kuitenkin, mitä teen esikoisuudellani?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Jaakob sanoi: \"Vanno minulle ensin.\" Niin hän vannoi hänelle ja myi esikoisuutensa Jaakobille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Jaakob antoi Eesaulle leipää ja linssikeittoa. Hän söi ja joi, nousi ja meni matkoihinsa. Niin halpana Eesau piti esikoisuutensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Maahan tuli nälänhätä, eri nälänhätä kuin se, joka oli ollut aikaisemmin Aabrahamin päivinä. Silloin Iisak meni Abimelekin, filistealaisten kuninkaan, luo Gerariin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Herra ilmestyi hänelle ja sanoi: \"Älä mene Egyptiin, vaan jää asumaan maahan, jonka sinulle sanon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Oleskele muukalaisena tässä maassa. Olen kanssasi ja siunaan sinua. Sillä sinulle ja siemenellesi annan kaikki nämä maat ja pidän valan, jonka olen vannonut isällesi Aabrahamille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Teen siemenesi luvun paljoksi kuin taivaan tähdet ja annan siemenellesi kaikki nämä maat, ja sinun Siemenessäsi tulevat siunatuiksi kaikki kansakunnat maan päällä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'sen tähden, että Aabraham kuuli minua ja noudatti, mitä noudatettavaksi annoin, käskyjäni, säädöksiäni ja opetuksiani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Iisak asettui Gerariin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Kun paikkakunnan miehet kysyivät hänen vaimostaan, hän sanoi: \"Hän on sisareni.\" Hän näet pelkäsi sanoa: \"Hän on vaimoni\", sillä hän ajatteli: \"Nuo miehet voivat tappaa minut Rebekan tähden, sillä hän on näöltään kaunis.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Kun hän oli viipynyt siellä jonkin aikaa, tapahtui, että Abimelek, filistealaisten kuningas, kerran katsellessaan ulos ikkunasta näki Iisakin hyväilevän vaimoaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Abimelek kutsutti Iisakin ja sanoi: \"Katso, hänhän on vaimosi! Miksi olet sanonut: \'Hän on sisareni\'?\" Iisak vastasi hänelle: \"Ajattelin, että minut muuten ehkä tapetaan hänen tähtensä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Abimelek sanoi: \"Mitä oletkaan meille tehnyt! Kuinka helposti olisikaan voinut tapahtua, että joku kansasta olisi maannut vaimosi kanssa, ja olisit saattanut meidät syyllistymään syntiin!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Abimelek antoi käskyn kaikelle kansalle sanoen: \"Joka koskee tähän mieheen tai hänen vaimoonsa, se on kuolemalla rangaistava.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Iisak kylvi siinä maassa ja sai sinä vuonna satakertaisesti, sillä Herra siunasi häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Hän rikastui ja hyötyi hyötymistään, kunnes hänestä tuli hyvin rikas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Hänellä oli laumoittain sekä lampaita ja vuohia että nautoja ja paljon palvelijoita, niin että filistealaiset alkoivat kadehtia häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Niin filistealaiset tukkivat kaikki ne kaivot, jotka hänen isänsä palvelijat olivat kaivaneet hänen isänsä Aabrahamin päivinä, ja täyttivät ne maalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Abimelek sanoi Iisakille: \"Mene pois luotamme, sillä sinä olet tullut meitä paljon voimakkaammaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Iisak lähti sieltä ja leiriytyi Gerarin laaksoon ja asui siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Iisak kaivatti uudelleen auki ne vesikaivot, jotka hänen isänsä Aabrahamin päivinä oli kaivettu, mutta jotka filistealaiset olivat Aabrahamin kuoltua tukkineet, ja antoi niille jälleen ne nimet, jotka hänen isänsä oli niille antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Iisakin palvelijat kaivoivat laaksossa ja löysivät sieltä kaivon, jossa oli juoksevaa vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Mutta Gerarin paimenet alkoivat riidellä Iisakin paimenten kanssa sanoen: \"Vesi on meidän.\" Niin hän kutsui kaivon Eesekiksi, koska he olivat riidelleet hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'He kaivoivat toisen kaivon ja joutuivat riitaan siitäkin. Niin hän antoi sille nimen Sitna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Hän muutti sieltä pois ja kaivoi vielä yhden kaivon. Siitä ei syntynyt riitaa. Sen tähden hän nimitti sen Rehobotiksi ja sanoi: \"Nyt Herra on antanut meille tilaa, niin että voimme lisääntyä maassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Sieltä hän meni Beersebaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Herra ilmestyi hänelle sinä yönä ja sanoi: \"Minä olen isäsi Aabrahamin Jumala. Älä pelkää, sillä minä olen kanssasi ja siunaan sinua ja teen siemenesi luvun suureksi palvelijani Aabrahamin tähden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Hän rakensi sinne alttarin, saarnasi Herran nimestä ja pystytti sinne telttansa. Iisakin palvelijat kaivoivat siihen kaivon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Niin Abimelek lähti hänen luokseen Gerarista ystävänsä Ahusatin ja sotapäällikkönsä Piikolin seuraamana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Mutta Iisak sanoi heille: \"Minkä tähden tulette minun luokseni, vaikka olette minulle vihamielisiä ja karkotitte minut luotanne?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'He vastasivat: \"Me olemme selvästi nähneet, että Herra on kanssasi. Sen tähden ajattelimme: \'Olkoon sinun ja meidän välillämme valallinen sopimus. Tahdomme tehdä kanssasi liiton,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'ettet tee meille mitään pahaa, niin kuin mekään emme ole sinuun koskeneet, vaan olemme tehneet sinulle ainoastaan hyvää ja sallineet sinun lähteä rauhassa.\' Sinä olet nyt Herran siunattu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Silloin hän laittoi heille pidot, ja he söivät ja joivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Varhain seuraavana aamuna he vannoivat valan toisilleen. Sen jälkeen Iisak päästi heidät menemään, ja he lähtivät hänen luotaan rauhassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Samana päivänä Iisakin palvelijat tulivat ja kertoivat hänelle kaivosta, jonka he olivat kaivaneet, sanoen hänelle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, '\"Me löysimme vettä.\" Hän antoi sille nimen Siba. Sen tähden on kaupungin nimi vielä tänäkin päivänä Beerseba.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Kun Eesau oli neljänkymmenen vuoden vanha, hän otti vaimoikseen Jehuditin, heettiläisen Beerin tyttären, ja Baasematin, heettiläisen Eelonin tyttären.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Näistä tuli Iisakille ja Rebekalle katkera murhe.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Kun Iisak oli tullut vanhaksi ja hänen silmänsä olivat hämärtyneet, ettei hän enää voinut nähdä, hän kutsui Eesaun, vanhimman poikansa, ja sanoi hänelle: \"Poikani!\" Tämä vastasi hänelle: \"Tässä olen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Niin hän sanoi: \"Katso, minä olen tullut vanhaksi enkä tiedä kuolinpäivääni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Ota siis aseesi, nuolikotelosi ja jousesi, ja mene kedolle ja pyydystä minulle riistaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Laita minulle herkkuruokaa, mieliruokaani, ja tuo sitä syödäkseni, että siunaisin sinut, ennen kuin kuolen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Rebekka kuuli, kuinka Iisak puhui pojalleen Eesaulle. Kun Eesau oli lähtenyt kedolle pyydystämään riistaa tuodakseen sitä isälleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Rebekka puhui pojalleen Jaakobille sanoen: \"Katso, kuulin isäsi puhuvan veljellesi Eesaulle ja sanovan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, '\'Tuo minulle riistaa ja laita minulle herkkuruoka syödäkseni, että siunaisin sinut Herran edessä, ennen kuin kuolen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Kuule siis, poikani, mitä sanon, ja tee, mitä minä käsken sinulle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'mene laumaan ja ota sieltä minulle kaksi hyvää kiliä laittaakseni niistä isällesi herkkuruokaa, hänen mieliruokaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Sinun on vietävä se isällesi syötäväksi, että hän siunaisi sinut ennen kuolemaansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Jaakob sanoi äidilleen Rebekalle: \"Katso, veljeni Eesau on karvainen, mutta minä olen sileäihoinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Entä jos isäni tunnustelee minua? Silloin minusta tulee hänen silmissään pilkkaaja ja hankin itselleni kirouksen enkä siunausta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Hänen äitinsä sanoi hänelle: \"Kohdatkoon kirous minua, poikani. Kuule vain ääntäni, mene ja nouda.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Niin hän meni noutamaan ne ja toi ne äidilleen. Hänen äitinsä laittoi herkkuruoan, hänen isänsä mieliruoan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Rebekka otti vanhemman poikansa Eesaun parhaat vaatteet, jotka olivat hänen hallussaan talossa, ja puki ne nuoremman poikansa Jaakobin ylle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Mutta kilien nahat hän kääri hänen käsiinsä ja paljaaseen kaulaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Sitten hän antoi herkkuruoan sekä leipomansa leivän poikansa Jaakobin käteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Jaakob meni isänsä luo ja sanoi: \"Isäni!\" Hän vastasi: \"Tässä olen. Kuka sinä olet, poikani?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Jaakob sanoi isälleen: \"Minä olen Eesau, esikoisesi. Olen tehnyt, niin kuin käskit minun tehdä. Nouse istumaan ja syö riistaani siunataksesi minut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Mutta Iisak sanoi pojalleen: \"Kuinka olet, poikani, niin pian löytänyt?\" Hän vastasi: \" Herra, Jumalasi, johdatti sen eteeni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Niin Iisak sanoi Jaakobille: \"Tulehan lähemmäksi, poikani, tunnustellakseni, oletko sinä poikani Eesau vai et.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Jaakob astui isänsä Iisakin luo. Tämä tunnusteli häntä ja sanoi: \"Ääni on Jaakobin ääni, mutta kädet ovat Eesaun kädet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Eikä Iisak tuntenut häntä, sillä hänen kätensä olivat karvaiset, niin kuin hänen veljensä Eesaun kädet, ja hän siunasi hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Vielä hän kysyi: \"Oletko sinä todella poikani Eesau?\" Hän vastasi: \"Olen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Silloin hän sanoi: \"Tuo ruoka minulle syödäkseni poikani riistaa, että siunaisin sinut.\" Niin hän toi sen hänelle, ja hän söi. Ja hän tarjosi hänelle viiniä, ja hän joi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Sen jälkeen hänen isänsä Iisak sanoi hänelle: \"Tule tänne ja suutele minua, poikani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Hän astui hänen luokseen ja suuteli häntä. Niin Iisak tunsi hänen vaatteittensa hajun ja siunasi hänet, sanoen: \"Katso, minun poikani tuoksu on kuin kedon tuoksu, jonka Herra on siunannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Jumala antakoon sinulle taivaan kastetta ja maan lihavuutta, jyviä ja viiniä yllin kyllin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Kansat palvelkoot sinua, kansakunnat sinua kumartakoot. Ole veljiesi herra, ja äitisi pojat kumartakoot sinua. Kirottu olkoon, joka sinua kiroaa, siunattu, joka sinua siunaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Kun Iisak oli ehtinyt siunata Jaakobin ja tämä oli juuri lähtenyt isänsä Iisakin luota, niin hänen veljensä Eesau tuli kotiin metsästämästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Hänkin laittoi herkkuruoan, vei sen isälleen ja sanoi isälleen: \"Nouse, isäni, ja syö poikasi riistaa siunataksesi minut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Hänen isänsä Iisak kysyi häneltä: \"Kuka olet?\" Hän vastasi: \"Minä olen poikasi Eesau, esikoisesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Silloin Iisak säikähti kovin ja sanoi: \"Kuka sitten oli se metsästäjä, joka toi minulle riistaa, niin että minä, ennen kuin tulit, söin kaikkea ja siunasin hänet? Siunattu hän myös on oleva.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Kun Eesau kuuli isänsä sanat, hän puhkesi valittamaan äänekkäästi ja haikeasti ja sanoi isälleen: \"Siunaa minutkin, isäni!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Mutta hän vastasi: \"Veljesi tuli kavalasti ja riisti sinulta siunauksen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Hän sanoi: \"Oikeinpa häntä kutsutaankin Jaakobiksi. Sillä hän on nyt kahdesti minut pettänyt: esikoisuuteni hän on minulta vienyt, ja katso, nyt hän riisti minulta myös siunauksen.\" Hän kysyi: \"Eikö sinulla ole mitään siunausta minun varalleni?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Iisak vastasi ja sanoi Eesaulle: \"Katso, minä olen asettanut hänet herraksesi ja antanut kaikki hänen veljensä hänelle palvelijoiksi sekä varustanut hänet jyvillä ja viinillä. Mitä voisin enää tehdä hyväksesi, poikani?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Eesau sanoi isälleen: \"Tuo yksi ainoa siunausko sinulla vain onkin, isäni? Siunaa minutkin, isäni!\" Niin Eesau korotti äänensä ja itki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Mutta hänen isänsä Iisak vastasi ja sanoi hänelle: \"Katso, asuinpaikkasi on oleva kaukana lihavasta maasta ja vailla taivaan kastetta ylhäältä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Miekkasi varassa sinä olet elävä ja palveleva veljeäsi. Mutta valtoimena kierrellen riisut hänen ikeensä niskaltasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Eesau alkoi vihata Jaakobia siunauksen tähden, jolla hänen isänsä oli hänet siunannut. Eesau ajatteli itsekseen: \"Pian tulee aika, jolloin suremme isäämme, ja tapan veljeni Jaakobin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Mutta Rebekalle ilmoitettiin hänen vanhemman poikansa Eesaun aikeista. Hän lähetti kutsumaan luokseen nuoremman poikansa Jaakobin ja sanoi hänelle: \"Katso, veljesi Eesau uhkaa kostaa sinulle ja tappaa sinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Kuule siis, mitä sanon, poikani: nouse ja pakene veljeni Laabanin luo Harraniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Jää hänen luokseen joksikin aikaa, kunnes veljesi viha asettuu,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'kunnes veljesi lakkaa sinua vihaamasta ja unohtaa, mitä olet hänelle tehnyt. Sitten lähetän noutamaan sinut sieltä. Minkä tähden menettäisin teidät molemmat samana päivänä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Rebekka sanoi Iisakille: \"Olen kyllästynyt elämääni Heetin tyttärien tähden. Jos Jaakobkin ottaa vaimon Heetin tyttäristä, tässä maassa syntyneen, sellaisen kuin nämä, niin mitä varten minä elän?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Iisak kutsui Jaakobin ja siunasi hänet. Hän käski häntä ja sanoi hänelle: \"Älä ota vaimoksesi ketään Kanaanin tyttäristä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'vaan nouse ja mene Mesopotamiaan, isoisäsi Betuelin kotiin, ja ota sieltä itsellesi vaimo enosi Laabanin tyttäristä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Jumala, Kaikkivaltias, siunatkoon sinua ja antakoon sinun tulla hedelmälliseksi ja lisääntyä, niin että sinusta tulee suuri kansojen joukko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Hän suokoon sinulle Aabrahamin siunauksen, sinulle sekä siemenellesi, että saisit omaksesi maan, jossa asut muukalaisena ja jonka Jumala on antanut Aabrahamille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Iisak lähetti Jaakobin matkaan. Hän lähti Mesopotamiaan Laabanin luo, joka oli aramilaisen Betuelin poika ja Rebekan, Jaakobin ja Eesaun äidin, veli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Kun Eesau näki, että Iisak oli siunannut Jaakobin ja lähettänyt hänet Mesopotamiaan ottamaan sieltä itselleen vaimon – sillä hän oli siunannut hänet, käskenyt häntä ja sanonut: \"Älä ota vaimoa Kanaanin tyttäristä\" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'ja että Jaakob oli totellut isäänsä ja äitiään ja lähtenyt Mesopotamiaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'hän huomasi, että Kanaanin tyttäret olivat hänen isälleen Iisakille vastenmielisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Eesau meni Ismaelin luo ja otti Mahalatin, Aabrahamin pojan Ismaelin tyttären, Nebajotin sisaren, vaimokseen entisten lisäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Jaakob lähti Beersebasta mennäkseen Harraniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Hän tuli erääseen paikkaan, jossa yöpyi, sillä aurinko oli laskenut. Hän otti paikan kivistä yhden, pani sen päänsä aluseksi ja asettui nukkumaan siihen paikkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Hän näki unta: Katso, maan päälle oli asetettu tikapuut, joiden pää ulottui taivaaseen. Katso, Jumalan enkelit kulkivat niitä myöten ylös ja alas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Katso, Herra seisoi hänen edessään ja sanoi: \"Minä olen Herra, isäsi Aabrahamin Jumala ja Iisakin Jumala. Tämän maan, jonka päällä sinä makaat, annan sinulle ja siemenellesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Jälkeläistesi paljous on oleva kuin maan tomu, ja sinä leviät länteen ja itään, pohjoiseen ja etelään, ja sinussa ja sinun Siemenessäsi tulevat siunatuiksi kaikki sukukunnat maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Katso, minä olen kanssasi ja varjelen sinua, missä ikinä kuljet, ja saatan sinut takaisin tähän maahan. Sillä en jätä sinua, ennen kuin olen toteuttanut sen, minkä olen sinulle puhunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Silloin Jaakob heräsi unestaan ja sanoi: \" Herra on totisesti tässä paikassa, enkä minä sitä tiennyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Pelko valtasi hänet, ja hän sanoi: \"Kuinka pelottava onkaan tämä paikka! Tässä on varmasti Jumalan huone ja taivaan portti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Jaakob nousi varhain aamulla, otti kiven, jonka hän oli pannut päänsä aluseksi, nosti sen pystyyn patsaaksi ja vuodatti öljyä sen päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Hän antoi paikalle nimen Beetel, mutta ennen kaupungin nimenä oli Luus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Sitten Jaakob teki lupauksen, sanoen: \"Jos Jumala on kanssani ja varjelee minut sillä tiellä, jota nyt kuljen, ja antaa minulle leipää syödäkseni ja vaatteita pukeutuakseni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'että saan palata rauhassa isäni kotiin, Herra on oleva minun Jumalani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'ja tämä kivi, jonka olen pystyttänyt patsaaksi, on oleva Jumalan huone, ja kaikesta, mitä minulle suot, totisesti annan sinulle kymmenykset.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Jaakob lähti matkaan ja tuli Idän miesten maalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Katso, hän huomasi kedolla kaivon, ja katso, sen luona oli makuulla kolme lammaslaumaa, sillä kaivosta oli tapana juottaa laumoja. Kaivon suulla oli suuri kivi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Sen tähden annettiin kaikkien laumojen kokoontua sinne, vieritettiin kivi kaivon suulta ja juotettiin lampaat. Sen jälkeen kivi taas pantiin paikoilleen kaivon suulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Jaakob sanoi heille: \"Veljeni, mistä te olette?\" He vastasivat: \"Olemme Harranista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Hän kysyi heiltä: \"Tunnetteko Laabanin, Naahorin pojan?\" He vastasivat: \"Tunnemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Hän kysyi heiltä: \"Voiko hän hyvin?\" He vastasivat: \"Hyvin hän voi, ja katso, Raakel, hänen tyttärensä, tulee tuolla lammasten kanssa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Hän sanoi: \"Vielä on täysi päivä ja on liian aikaista koota lauma. Juottakaa lampaat ja viekää ne takaisin laitumelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'He vastasivat: \"Emme voi, ennen kuin kaikki laumat ovat koolla ja kivi on vieritetty kaivon suulta. Sitten juotamme lampaat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Hänen vielä puhuessaan heidän kanssaan tuli Raakel isänsä lammasten kanssa, sillä hänellä oli tapana olla paimenessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Kun Jaakob näki Raakelin, enonsa Laabanin tyttären, ja enonsa Laabanin lampaat, hän astui esiin ja vieritti kiven kaivon suulta ja juotti enonsa Laabanin lampaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Jaakob suuteli Raakelia, korotti äänensä ja itki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Jaakob ilmoitti Raakelille, että hän oli hänen isänsä sukulainen ja Rebekan poika. Raakel riensi pois ja ilmoitti sen isälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Kun Laaban kuuli kerrottavan Jaakobista, sisarensa pojasta, riensi hän häntä vastaan, syleili ja suuteli häntä ja toi hänet kotiinsa. Hän kertoi Laabanille kaiken, mitä oli tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Laaban sanoi hänelle: \"Todellakin, sinä olet minun luutani ja lihaani.\" Sitten hän asui hänen luonaan kuukauden päivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Laaban sanoi Jaakobille: \"Olet tosin sukulaiseni, mutta palvelisitko silti minua palkatta? Sano minulle, mikä on palkkasi oleva.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Laabanilla oli kaksi tytärtä. Vanhemman nimi oli Leea, nuoremman nimi oli Raakel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Leealla oli sameat silmät, mutta Raakelilla oli kaunis vartalo ja kauniit kasvot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Jaakob rakasti Raakelia. Hän sanoi: \"Minä palvelen sinua seitsemän vuotta saadakseni Raakelin, nuoremman tyttäresi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Laaban vastasi: \"Parempi on, että annan hänet sinulle, kuin että antaisin hänet jollekin toiselle. Jää luokseni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Jaakob palveli siis seitsemän vuotta saadakseen Raakelin, ja ne tuntuivat hänestä muutamilta päiviltä. Niin hän rakasti häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Sen jälkeen Jaakob sanoi Laabanille: \"Anna minulle vaimoni, sillä aikani on nyt kulunut umpeen, mennäkseni hänen luokseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Silloin Laaban kutsui kokoon kaikki paikkakunnan asukkaat ja laittoi pidot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Mutta illalla hän otti tyttärensä Leean ja vei hänet hänen luokseen. Jaakob yhtyi häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Laaban antoi orjattarensa Silpan tyttärelleen Leealle orjattareksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Aamulla Jaakob näki, että se oli Leea. Hän sanoi Laabanille: \"Mitä oletkaan minulle tehnyt? Olenhan palvellut sinua saadakseni Raakelin! Miksi petit minut?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Laaban vastasi: \"Maassamme ei ole tapana antaa nuorempaa ennen vanhempaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Vietä nyt vain tämä hääviikko loppuun, niin annetaan sinulle toinenkin, kunhan olet palveluksessani vielä toiset seitsemän vuotta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jaakob suostui siihen, ja kun hän oli viettänyt sen viikon loppuun, Laaban antoi myös tyttärensä Raakelin hänelle vaimoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Laaban antoi orjattarensa Bilhan tyttärelleen Raakelille orjattareksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Jaakob yhtyi myös Raakeliin, ja Raakel oli hänelle rakkaampi kuin Leea. Hän palveli Laabanin luona vielä toiset seitsemän vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Kun Herra näki, että Leeaa hyljittiin, hän avasi hänen kohtunsa, mutta Raakel oli hedelmätön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Leea tuli raskaaksi ja synnytti pojan ja antoi hänelle nimen Ruuben, sanoen: \" Herra on nähnyt kurjuuteni. Nyt on mieheni rakastava minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Hän tuli jälleen raskaaksi ja synnytti pojan ja sanoi: \" Herra on kuullut, että minua hyljitään, ja on antanut minulle myös tämän.\" Niin hän antoi hänelle nimen Simeon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Hän tuli jälleen raskaaksi, synnytti pojan ja sanoi: \"Nyt kai mieheni vihdoinkin kiintyy minuun, sillä olenhan synnyttänyt hänelle kolme poikaa.\" Sen tähden hän antoi hänelle nimen Leevi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Hän tuli vieläkin raskaaksi ja synnytti pojan ja sanoi: \"Nyt minä kiitän Herraa.\" Sen tähden hän antoi hänelle nimen Juuda. Sitten hän lakkasi synnyttämästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Kun Raakel näki, ettei hän synnyttänyt Jaakobille, hän kadehti sisartaan ja sanoi Jaakobille: \"Hanki minulle lapsia, muuten minä kuolen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Niin Jaakob vihastui Raakeliin ja sanoi: \"Minäkö olen Jumala, joka on kieltänyt sinulta kohdun hedelmän?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Raakel sanoi: \"Tässä on orjattareni Bilha. Yhdy häneen, että hän synnyttäisi minun helmaani ja minäkin siten saisin lapsia hänestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Hän antoi hänelle orjattarensa Bilhan vaimoksi, ja Jaakob yhtyi häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Bilha tuli raskaaksi ja synnytti Jaakobille pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Raakel sanoi: \"Jumala hankki minulle oikeuden, ja hän kuuli ääntäni ja antoi minulle pojan.\" Sen tähden hän antoi hänelle nimen Daan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Bilha, Raakelin orjatar, tuli jälleen raskaaksi ja synnytti Jaakobille toisen pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Raakel sanoi: \"Jumalan taisteluja olen taistellut sisareni kanssa ja olen voittanut.\" Hän antoi hänelle nimen Naftali.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Kun Leea näki lakanneensa synnyttämästä, hän otti orjattarensa Silpan ja antoi hänet Jaakobille vaimoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Silpa, Leean orjatar, synnytti Jaakobille pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Leea sanoi: \"Onneksi!\", ja antoi hänelle nimen Gaad.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Silpa, Leean orjatar, synnytti Jaakobille toisen pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Leea sanoi: \"Oi minua onnellista! Tyttäret ylistävät minua onnelliseksi.\" Hän antoi hänelle nimen Asser.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Mutta Ruuben meni kerran ulos vehnänleikkuun aikaan ja löysi lemmenmarjoja vainiolta ja toi ne äidilleen Leealle. Niin Raakel sanoi Leealle: \"Anna minulle poikasi lemmenmarjoja.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Leea vastasi hänelle: \"Eikö riitä, että olet vienyt minulta mieheni, kun tahdot ottaa vielä poikani lemmenmarjatkin?\" Raakel sanoi: \"Olkoon, maatkoon hän tämän yön kanssasi, kunhan saan poikasi lemmenmarjat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Kun Jaakob illalla palasi vainiolta, Leea meni häntä vastaan ja sanoi: \"Minun luokseni sinun on tultava, sillä olen todella ostanut sinut poikani lemmenmarjoilla.\" Niin hän makasi sen yön hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Jumala kuuli Leeaa, ja Leea tuli raskaaksi ja synnytti Jaakobille viidennen pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Leea sanoi: \"Jumala on palkinnut minulle sen, että annoin orjattareni miehelleni.\" Hän antoi hänelle nimen Isaskar.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Leea tuli jälleen raskaaksi ja synnytti Jaakobille kuudennen pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Silloin Leea sanoi: \"Jumala on antanut minulle hyvän lahjan. Nyt mieheni on asuva luonani, sillä olen synnyttänyt hänelle kuusi poikaa.\" Hän antoi hänelle nimen Sebulon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Sitten hän synnytti tyttären ja antoi hänelle nimen Diina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Mutta Jumala muisti Raakeliakin. Jumala kuuli häntä ja avasi hänen kohtunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Hän tuli raskaaksi ja synnytti pojan ja sanoi: \"Jumala on ottanut pois häpeäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Hän antoi hänelle nimen Joosef, sanoen: \" Herra antakoon minulle vielä toisen pojan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Kun Raakel oli synnyttänyt Joosefin, Jaakob sanoi Laabanille: \"Päästä minut menemään kotiini ja omaan maahani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Anna minulle vaimoni ja lapseni, joiden vuoksi olen sinua palvellut, lähteäkseni pois, sillä tiedäthän itse, kuinka olen sinua palvellut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Laaban vastasi hänelle: \"Jospa saisin armon silmiesi edessä! Merkkini ilmoittavat, että Herra on sinun tähtesi siunannut minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Hän sanoi vielä: \"Määrää palkka, joka minun on sinulle maksettava, niin sen annan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Hän vastasi hänelle: \"Itsehän tiedät, kuinka olen sinua palvellut ja millaiseksi karjasi on tullut hoidossani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Sillä vähän sinulla oli ennen minun tuloani, mutta sitten se on karttunut suureksi, ja Herra on siunannut sinua minun askeleistani. Mutta milloin minäkin saan ruveta tekemään työtä oman perheeni hyväksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Hän vastasi: \"Mitä minun on sinulle annettava?\" Jaakob sanoi: \"Ei sinun tarvitse antaa minulle mitään. Jos myönnät minulle tämän, niin yhä edelleen paimennan ja vartioin laumojasi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Tarkastan tänään koko laumasi. Erota siitä pois kaikki pilkulliset ja kirjavat lampaat sekä karitsoista kaikki mustat ja vuohista kirjavat ja pilkulliset. Ne ovat palkkani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Siinä vanhurskauteni tulee näytetyksi toteen: Kun vastaisuudessa tulet omin silmin katsomaan palkkaani, niin kaikki vuohet, jotka eivät ole pilkullisia eivätkä kirjavia, ja kaikki karitsat, jotka eivät ole mustia, katsottakoon minun varastamikseni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Laaban vastasi: \"Hyvä, olkoon, kuten olet puhunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Samana päivänä hän erotti pois juovikkaat ja kirjavat vuohipukit ja kaikki pilkulliset ja kirjavat vuohet – kaikki, joissa oli jotakin valkoista – sekä kaikki mustat karitsat ja jätti ne poikiensa hoitoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Hän asetti niin, että oli kolmen päivän välimatka hänen ja Jaakobin välillä, ja Jaakob paimensi Laabanin muuta karjaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Mutta Jaakob otti itselleen tuoreita poppelin, mantelipuun ja plataanin oksia ja kuori niihin valkoisia juovia paljastaen oksien valkoisen rungon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Kuorimansa oksat hän pani eläinten eteen vesikaukaloihin eli juoma-astioihin, joista ne tulivat juomaan. Ne olivat kiimassa juomaan tullessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Eläimet pariutuivat oksien edessä ja synnyttivät juovikkaita, pilkullisia ja kirjavia karitsoita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Sitten Jaakob erotti karitsat. Hän asetti eläinten päät niihin päin, jotka olivat pilkullisia, ja kaikkiin niihin päin, jotka olivat mustia Laabanin laumassa. Siten hän hankki itselleen eri laumansa eikä päästänyt niitä Laabanin laumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Joka kerta kun voimakkaat eläimet olivat kiimassa, Jaakob pani oksat eläinten silmien eteen vesikaukaloihin, niin että ne pariutuivat oksien edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Mutta heikkojen eläinten eteen hän ei niitä pannut. Niin heikot joutuivat Laabanille ja voimakkaat Jaakobille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Mies tuli hyvin rikkaaksi. Hän sai paljon lampaita ja vuohia sekä palvelijattaria, palvelijoita, kameleja ja aaseja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Hän sai kuulla, että Laabanin pojat puhuivat näin: \"Jaakob on anastanut kaiken, mitä isämme omisti. Isämme omaisuudesta hän on hankkinut itselleen kaiken tämän rikkauden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Jaakob huomasi Laabanin kasvoista, ettei hän ollut häntä kohtaan kuten ennen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Herra sanoi Jaakobille: \"Palaa isiesi maahan ja sukusi luo. Minä olen kanssasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Jaakob lähetti kutsumaan Raakelin ja Leean kedolle laumansa luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Hän sanoi heille: \"Minä huomaan isänne kasvoista, ettei hän ole minua kohtaan kuten ennen, vaikka isäni Jumala on ollut kanssani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Te tiedätte, että olen palvellut isäänne kaikin voimin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'mutta isänne on kohdellut minua petollisesti ja muuttanut palkkaani kymmenen kertaa. Jumala ei kuitenkaan ole sallinut hänen tehdä minulle mitään vahinkoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Kun hän sanoi: \'Pilkulliset olkoot palkkasi\', niin koko lauma kantoi pilkullisia. Kun hän sanoi: \'Juovikkaat olkoot palkkasi\', niin koko lauma kantoi juovikkaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Jumala on ottanut isänne omaisuuden ja antanut minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Mutta lauman pariutumisen aikana nostin silmäni ja näin unessa, että pukit, jotka astuivat laumaa, olivat juovikkaita, pilkullisia ja kirjavia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Jumalan Enkeli sanoi minulle unessa: \'Jaakob!\' Vastasin: \'Tässä olen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Hän sanoi: \'Nosta silmäsi ja katso, kaikki pukit, jotka astuvat laumaa, ovat juovikkaita, pilkullisia ja kirjavia, sillä minä olen nähnyt kaiken, mitä Laaban tekee sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Minä olen Jumala, joka ilmestyin Beetelissä, jossa voitelit patsaan ja jossa teit minulle lupauksen. Nouse nyt ja lähde tästä maasta ja palaa synnyinmaahasi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Raakel ja Leea vastasivat ja sanoivat hänelle: \"Meillä ei ole enää osaa eikä perintöä isämme talossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Eikö hän pitänyt meitä muukalaisina, koska myi meidät ja söi suuhunsa meistä saamansa hinnan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Sillä koko se rikkaus, jonka Jumala on ottanut isältämme, on meidän ja meidän lastemme. Tee siis nyt kaikki, mitä Jumala on sinulle sanonut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Jaakob nousi ja nosti lapsensa ja vaimonsa kamelien selkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Hän kuljetti pois kaiken karjansa ja kaiken omaisuutensa, jonka hän oli koonnut, kaiken omistamansa ja Mesopotamiassa hankkimansa karjan mennäkseen isänsä Iisakin luo Kanaanin maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Laaban oli mennyt keritsemään lampaitaan. Silloin Raakel varasti isänsä kotijumalat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Jaakob lähti salaa aramilaisen Laabanin luota eikä ilmaissut hänelle aikomustaan paeta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Hän pakeni kaikkineen, lähti ja meni virran yli ja suuntasi kulkunsa Gileadin vuoria kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Mutta kolmantena päivänä Laabanille ilmoitettiin, että Jaakob oli paennut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Silloin hän otti mukaansa heimonsa miehet ja ajoi häntä takaa seitsemän päivämatkaa ja saavutti hänet Gileadin vuorilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Mutta Jumala tuli aramilaisen Laabanin luo unessa yöllä ja sanoi hänelle: \"Varo, ettet puhu Jaakobille hyvää etkä pahaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Laaban saavutti Jaakobin. Jaakob oli pystyttänyt telttansa vuorelle, Laaban taas pystytti telttansa Gileadin vuorelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Laaban sanoi Jaakobille: \"Mitä oletkaan tehnyt? Olet pettänyt minut ja kuljettanut pois tyttäreni kuin miekalla otetut!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Minkä tähden pakenit salaa ja lähdit luotani varkain? Et ilmoittanut minulle mitään, enkä saanut saattaa sinua matkalle iloiten ja laulaen, tamburiinein ja harpuin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'etkä suonut minun suudella lasteni lapsia ja tyttäriäni. Tyhmästi olet menetellyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Minulla olisi valta tehdä teille pahaa, mutta teidän isänne Jumala sanoi minulle viime yönä näin: \'Varo, ettet puhu Jaakobille hyvää etkä pahaa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Olet nyt lähtenyt matkaan, koska niin suuresti ikävöit isäsi kotiin, mutta minkä tähden olet varastanut minun jumalani?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Jaakob vastasi ja sanoi Laabanille: \"Minä pelkäsin, sillä ajattelin, että sinä riistäisit minulta tyttäresi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Mutta se, jonka hallusta löydät jumalasi, menettäköön henkensä. Heimojemme miesten läsnä ollessa tutki, mitä minulla on, ja ota pois, mikä on omaasi.\" Sillä Jaakob ei tiennyt, että Raakel oli ne varastanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Laaban meni Jaakobin telttaan, Leean telttaan ja molempien orjattarien telttaan, mutta ei löytänyt mitään. Tultuaan ulos Leean teltasta hän meni Raakelin telttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Mutta Raakel oli ottanut kotijumalat, pannut ne kamelin satulaan ja istunut niiden päälle. Laaban penkoi koko teltan, mutta ei löytänyt mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Raakel sanoi isälleen: \"Älä vihastu, herrani, siitä, etten voi nousta edessäsi, sillä minun on, niin kuin naisten tavallisesti on.\" Laaban etsi, mutta ei löytänyt kotijumalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Jaakob vihastui ja soimasi Laabania. Jaakob puhkesi puhumaan ja sanoi Laabanille: \"Mitä olen rikkonut, mitä pahaa olen tehnyt, että näin minua ahdistat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Nyt olet penkonut kaikki tavarani. Mitä olet löytänyt sellaista, joka olisi talosi tavaraa? Tuo se tähän minun heimoni ja sinun heimosi miesten eteen, että he ratkaisisivat meidän molempien välin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Nämä kaksikymmentä vuotta minä olen ollut luonasi. Lampaasi ja vuohesi eivät ole synnyttäneet keskosia, enkä minä ole syönyt pässejä laumastasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Pedon raatelemaa en ole sinulle tuonut. Se oli minun itseni korvattava. Minulta sinä sen vaadit, olipa se viety päivällä tai viety yöllä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Päivällä vaivasi minua helle, yöllä vilu, ja uni pakeni silmistäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Nämä kaksikymmentä vuotta olen ollut talossasi. Neljätoista vuotta palvelin sinua saadakseni molemmat tyttäresi ja kuusi vuotta saadakseni sinulta karjaa, mutta kymmenen kertaa sinä muutit palkkani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Jos minun isäni Jumala, Aabrahamin Jumala, jota myös Iisak pelkää, ei olisi ollut puolellani, niin olisit nyt lähettänyt minut tyhjänä tieheni. Jumala on nähnyt kurjuuteni ja kätteni vaivannäön, ja hän ratkaisi viime yönä asian.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Laaban vastasi ja sanoi Jaakobille: \"Tyttäret ovat minun tyttäriäni, ja lapset ovat minun lapsiani, ja karja on minun karjaani, ja kaikki, mitä sinä näet, on minun omaani. Mutta minkä minä nyt teen näille tyttärilleni tai lapsille, jotka he ovat synnyttäneet!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Tule siis, tehkäämme liitto keskenämme, ja olkoon se todistuksena välillämme, minun ja sinun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Silloin Jaakob otti kiven ja nosti sen pystyyn patsaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Jaakob sanoi heimonsa miehille: \"Kootkaa kiviä.\" He ottivat kiviä ja rakensivat niistä röykkiön ja aterioivat siinä kivikasan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Laaban antoi sille nimen Jegar-Saahaduta, mutta Jaakob antoi sille nimen Galed.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Laaban sanoi: \"Tämä kivikasa olkoon tänään todistajana välillämme, minun ja sinun.\" Sen tähden hän antoi sille nimen Galed');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'ja myös nimen Mispa, sillä hän sanoi: \" Herra olkoon vartija välillämme, minun ja sinun, kun joudumme loitolle toistemme näkyvistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Jos sinä kohtelet pahasti tyttäriäni tai otat toisia vaimoja tyttärieni lisäksi, niin tiedä, että vaikkei ketään ihmistä olekaan läsnä, Jumala on kuitenkin todistajana välillämme, minun ja sinun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Laaban sanoi vielä Jaakobille: \"Katso, tämä kivikasa ja tämä patsas, jonka olen pystyttänyt välillemme, minun ja sinun');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, '– tämä kivikasa olkoon todistuksena, ja myös tämä patsas olkoon todistuksena siitä, etten minä kulje tämän kivikasan ohi luoksesi ja ettet sinäkään kulje tämän kivikasan ja tämän patsaan ohi minun luokseni paha mielessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Aabrahamin Jumala ja Naahorin Jumala, heidän isiensä Jumala, olkoon tuomarina välillämme.\" Jaakob vannoi valansa Jumalan kautta, jota hänen isänsä Iisak pelkäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Jaakob uhrasi vuorella teurasuhrin ja kutsui heimonsa miehet aterioimaan, ja he aterioivat ja olivat yötä vuorella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Mutta varhain seuraavana aamuna Laaban nousi, suuteli lastensa lapsia ja tyttäriään ja hyvästeli heidät. Sitten hän lähti matkaan ja palasi kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Jaakob kulki tietään, ja Jumalan enkeleitä tuli häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Nähdessään heidät Jaakob sanoi: \"Tämä on Jumalan sotajoukkoa.\" Hän antoi sille paikalle nimen Mahanaim.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Sitten Jaakob lähetti sanansaattajat edellään veljensä Eesaun luo Seirin maahan Edomin alueelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Hän käski heitä sanoen: \"Sanokaa herralleni Eesaulle näin: \'Palvelijasi Jaakob sanoo: Olen oleskellut Laabanin luona ja viipynyt siellä tähän saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Olen saanut nautoja, aaseja, lampaita ja vuohia, palvelijoita ja palvelijattaria ja lähetän nyt sanan herralleni, että saisin armon silmiesi edessä.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Sanansaattajat palasivat Jaakobin luo ja sanoivat: \"Tulimme veljesi Eesaun luo. Hän on jo matkalla sinua vastaan neljäsataa miestä mukanaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Jaakobin valtasi suuri pelko ja ahdistus. Hän jakoi väen, joka oli hänen kanssaan, sekä lampaat, vuohet, naudat ja kamelit kahteen joukkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Hän näet ajatteli: \"Jos Eesau hyökkää toisen joukon kimppuun ja tuhoaa sen, niin toinen joukko pääsee pakoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Jaakob sanoi: \"Isäni Aabrahamin Jumala ja isäni Iisakin Jumala, Herra, sinä, joka sanoit minulle: \'Palaa maahasi ja sukusi luo, niin teen sinulle hyvää!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Minä olen liian halpa kaikkeen siihen armoon ja kaikkeen siihen uskollisuuteen, jota olet palvelijallesi osoittanut. Sillä ainoastaan sauva kädessäni kuljin tämän Jordanin yli, ja nyt minulla on kaksi joukkoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Pelasta minut veljeni Eesaun käsistä, sillä minä pelkään, että hän tulee ja tuhoaa minut sekä äidit lapsineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Olethan sinä sanonut: \'Minä teen sinulle hyvää ja annan siemenesi luvun tulla paljoksi kuin meren hiekka, jota sen paljouden tähden ei voi lukea.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Hän jäi siihen yöksi. Sitten hän erotti omaisuudestaan lahjaksi veljelleen Eesaulle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'kaksisataa vuohta ja kaksikymmentä vuohipukkia, kaksisataa emälammasta ja kaksikymmentä pässiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'kolmekymmentä imettävää kamelia varsoineen, neljäkymmentä lehmää ja kymmenen härkää, kaksikymmentä aasintammaa ja kymmenen aasia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Hän jätti ne palvelijoittensa haltuun, kunkin lauman erikseen, ja sanoi palvelijoilleen: \"Menkää edelläni ja jättäkää välimatka kunkin lauman välille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Hän käski ensimmäistä sanoen: \"Kun veljeni Eesau kohtaa sinut ja kysyy: \'Kenen sinä olet, ja mihin menet, ja kenen ovat nuo eläimet tuolla edelläsi?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'vastaa: \'Ne ovat palvelijasi Jaakobin, lähetetyt lahjaksi herralleni Eesaulle. Katso, myös hän itse tulee jäljessämme.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Samoin hän käski toista ja kolmatta ja kaikkia muita, jotka laumoja ajoivat, sanoen: \"Juuri näin on teidän sanottava Eesaulle, kun tapaatte hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Sanokaa myös: \'Katso, palvelijasi Jaakob tulee jäljessämme.\'\" Sillä hän ajatteli: \"Minä lepytän häntä lahjalla, joka kulkee edelläni. Sitten astun itse hänen kasvojensa eteen. Ehkä hän ottaa minut ystävällisesti vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Niin lahja kulki hänen edellään, mutta itse hän jäi siksi yöksi leiriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Mutta yöllä hän nousi, otti molemmat vaimonsa, molemmat orjattarensa ja yksitoista lastaan ja meni kahlauspaikasta Jabbokin yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Hän otti heidät ja vei heidät joen yli. Hän vei yli kaiken, mitä hänellä oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Jaakob jäi yksin toiselle puolelle. Silloin hänen kanssaan painiskeli muuan mies päivän koittoon asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Kun mies huomasi, ettei hän voittanut häntä, hän iski häntä lonkkaluuhun, niin että Jaakobin lonkka nyrjähti hänen painiskellessaan hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Mies sanoi: \"Päästä minut, sillä päivä koittaa.\" Mutta hän vastasi: \"En päästä sinua, ellet siunaa minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Hän sanoi hänelle: \"Mikä on nimesi?\" Hän vastasi: \"Jaakob.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Hän sanoi: \"Nimesi älköön enää olko Jaakob, vaan Israel, sillä sinä olet taistellut Jumalan ja ihmisten kanssa ja olet voittanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Jaakob kysyi ja sanoi: \"Ilmoita nimesi.\" Hän vastasi: \"Miksi kysyt nimeäni?\" Hän siunasi hänet siinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Jaakob antoi paikalle nimen Penuel, \"sillä\", hän sanoi, \"minä olen nähnyt Jumalan kasvoista kasvoihin, ja kuitenkin henkeni on pelastunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Kun hän oli kulkenut Penuelin ohi, nousi aurinko, mutta hän ontui lonkkaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 33, 'Sen tähden israelilaiset eivät vielä tänäkään päivänä syö reisijännettä, joka kulkee lonkkaluun yli, sillä hän iski Jaakobia lonkkaluuhun, reisijänteen kohdalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Kun Jaakob nosti silmänsä ja katseli, niin, katso, Eesau oli tulossa neljäsataa miestä mukanaan. Hän jakoi lapset Leealle, Raakelille ja molemmille orjattarille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Hän asetti orjattaret lapsineen ensimmäisiksi, niiden jälkeen Leean lapsineen ja Raakelin Joosefin kanssa viimeiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Mutta itse hän meni heidän edellään ja kumartui maahan seitsemän kertaa, kunnes oli saapunut veljensä eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Mutta Eesau riensi häntä vastaan, sulki hänet syliinsä, halasi häntä kaulasta ja suuteli häntä, ja he itkivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Hän nosti silmänsä, näki vaimot ja lapset ja kysyi: \"Keitä ovat nämä sinulla?\" Hän vastasi: \"Ne ovat lapsiani, jotka Jumala on palvelijallesi lahjoittanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Orjattaret lähestyivät lapsineen ja kumartuivat maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Myös Leea lapsineen lähestyi, ja he kumartuivat maahan. Viimein lähestyivät Joosef ja Raakel ja kumartuivat maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Sitten hän sanoi: \"Mitä tarkoitit kaikella sillä joukolla, jonka kohtasin?\" Hän vastasi: \"Saada armon herrani silmien edessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Mutta Eesau sanoi: \"Minulla on paljon. Pidä, veljeni, omanasi, mitä sinulla on!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Jaakob vastasi: \"Ei niin. Jos olen saanut armon silmiesi edessä, niin ota minulta vastaan lahjani. Sillä olenhan saanut nähdä kasvosi, niin kuin nähdään Jumalan kasvot, ja sinä olet ottanut minut suosiollisesti vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Ota siis tervehdyslahjani, joka sinulle tuotiin, sillä Jumala on ollut minulle armollinen, ja minulla on kaikkea.\" Hän vaati häntä, ja hän [Eesau] otti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Sitten Eesau sanoi: \"Lähtekäämme liikkeelle ja vaeltakaamme eteenpäin. Minä vaellan edelläsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Mutta Jaakob sanoi hänelle: \"Herrani näkee itse, että lapset ovat pieniä ja että minulla on imettäviä lampaita ja lehmiä mukanani. Jos näitä ajaa kiivaasti päivänkään, kuolee koko lauma.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Kulkekoon siis herrani palvelijansa edellä. Minä seuraan hiljalleen jäljessä, sen mukaan kuin karja, jota kuljetan, ja lapset jaksavat kulkea kunnes saavun herrani luo Seiriin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Eesau vastasi: \"Jätän luoksesi osan väestäni.\" Hän sanoi: \"Minkä tähden niin? Kunhan vain saan armon herrani silmien edessä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Eesau kääntyi sinä päivänä takaisin ja meni tietään Seiriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Mutta Jaakob lähti Sukkotiin ja rakensi siellä itselleen majan, mutta karjalleen hän teki katoksia. Siitä tuli paikan nimeksi Sukkot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Jaakob saapui matkallaan Mesopotamiasta onnellisesti Sikemin kaupunkiin, joka on Kanaanin maassa, ja leiriytyi kaupungin edustalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Hän osti sen maapalstan, johon hän oli pystyttänyt telttansa, Hamorin, Sikemin isän, pojilta sadalla kesitalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Hän pystytti siihen alttarin ja antoi sille nimen Eel, Israelin Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Diina, Leean tytär, jonka hän oli synnyttänyt Jaakobille, meni tapaamaan maan tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Sikem, joka oli hivviläisen Hamorin, maan ruhtinaan, poika, näki hänet, otti hänet luokseen, makasi hänen kanssaan ja teki hänelle väkivaltaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Hänen sydämensä kiintyi Diinaan, Jaakobin tyttäreen, ja hän rakasti tyttöä ja puheli hellästi hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Sikem puhui isälleen Hamorille sanoen: \"Ota minulle tämä tyttö vaimoksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Jaakob oli saanut kuulla, että Sikem oli raiskannut hänen tyttärensä Diinan. Mutta kun hänen poikansa olivat hänen laumansa kanssa kedolla, Jaakob oli vaiti siihen asti, kunnes he palasivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Hamor, Sikemin isä, meni Jaakobin luo puhuttelemaan häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Jaakobin pojat tulivat kedolta. Kuultuaan, mitä oli tapahtunut, miehet sydämistyivät ja vihastuivat kovin siitä, että hän oli tehnyt häpeällisen teon Israelissa, kun oli maannut Jaakobin tyttären, sillä semmoista ei saa tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Niin Hamor puhui heille sanoen: \"Poikani Sikemin sydän on mielistynyt teidän sisareenne. Antakaa hänet hänelle vaimoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Lankoutukaa kanssamme, antakaa te tyttäriänne meille, ja ottakaa te itsellenne meidän tyttäriämme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Jääkää asumaan luoksemme. Maa on oleva teille avoinna, asukaa siinä, kierrelkää siinä ja asettukaa siihen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Sikem sanoi tytön isälle ja veljille: \"Suokaa minun saada armo silmienne edessä, ja mitä minulta vaaditte, sen minä annan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Vaatikaa minulta kuinka suuri morsiamen hinta ja kuinka suuret lahjat tahansa: annan, mitä te minulle sanotte. Antakaa minulle vain tyttö vaimoksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Mutta Jaakobin pojat vastasivat Sikemille ja hänen isälleen Hamorille puhuen petollisesti, koska hän oli raiskannut heidän sisarensa Diinan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'He sanoivat heille: \"Emme voi tehdä sitä, että antaisimme sisaremme ympärileikkaamattomalle miehelle, sillä se olisi meistä häpeällistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Suostumme ainoastaan sillä ehdolla, että te tulette meidän kaltaisiksemme, niin että kaikki miespuolet ympärileikataan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Silloin annamme omia tyttäriämme teille ja otamme itsellemme teidän tyttäriänne, ja asetumme luoksenne ja tulemme yhdeksi kansaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Mutta jos ette kuule meitä ettekä ympärileikkauta itseänne, niin otamme sisaremme ja menemme tiehemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Heidän puheensa kelpasi Hamorille ja Sikemille, Hamorin pojalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Eikä nuori mies viivytellyt sen tekemisessä, sillä hän oli mieltynyt Jaakobin tyttäreen. Hän oli suuremmassa arvossa kuin kukaan toinen hänen isänsä perheessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Hamor ja hänen poikansa Sikem lähtivät kaupunkinsa porttiin ja puhuivat kaupunkinsa miehille sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, '\"Näillä miehillä on rauha mielessä meitä kohtaan. Asukoot maassa ja kierrelkööt siinä, onhan maa tilava heillekin joka suuntaan. Ottakaamme heidän tyttäriään vaimoiksemme, ja antakaamme tyttäriämme heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Mutta ainoastaan sillä ehdolla miehet suostuvat asettumaan luoksemme tullakseen kanssamme yhdeksi kansaksi, että kaikki miehenpuolemme ympärileikataan, niin kuin he itsekin ovat ympärileikattuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Tulevathan silloin heidän karjansa ja tavaransa ja kaikki heidän juhtansa omiksemme. Suostukaamme, niin he asettuvat luoksemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'He kuulivat Hamoria ja hänen poikaansa Sikemiä, kaikki, jotka kulkivat hänen kaupunkinsa portista, ja kaikki miespuoliset, kaikki, jotka kulkivat hänen kaupunkinsa portista, ympärileikkauttivat itsensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Mutta kolmantena päivänä, kun he olivat kipeimmillään, Jaakobin kaksi poikaa, Simeon ja Leevi, Diinan veljet, otti kumpikin miekkansa. He hyökkäsivät kenenkään aavistamatta kaupunkiin ja tappoivat jokaisen miespuolisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Myös Hamorin ja hänen poikansa Sikemin he tappoivat miekan terällä, ottivat Diinan Sikemin talosta ja menivät pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Jaakobin pojat kävivät haavoitettujen kimppuun ja ryöstivät kaupungin, sen tähden että he olivat raiskanneet heidän sisarensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'He anastivat heidän lampaansa, vuohensa, nautansa ja aasinsa ja kaikki, mitä oli sekä kaupungissa että kedolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Kaikki heidän tavaransa, kaikki heidän lapsensa ja vaimonsa he veivät saaliinaan, ja he ryöstivät samoin kaiken muun, mitä taloissa oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Jaakob sanoi Simeonille ja Leeville: \"Te olette syösseet minut onnettomuuteen, saattaneet minut maan asukkaiden, kanaanilaisten ja perissiläisten, vihoihin. Joukkoni on vähäinen. Jos he kokoontuvat minua vastaan, he tuhoavat minut, ja minut ja sukuni hävitetään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Mutta he vastasivat: \"Pitikö hänen kohdella sisartamme kuin porttoa!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Jumala sanoi Jaakobille: \"Nouse, mene Beeteliin, asetu sinne ja rakenna sinne alttari Jumalalle, joka ilmestyi sinulle paetessasi veljeäsi Eesauta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Jaakob sanoi perheelleen ja kaikille, jotka olivat hänen kanssaan: \"Poistakaa vieraat jumalat, joita teillä on keskuudessanne, puhdistautukaa ja muuttakaa vaatteenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Nouskaamme ja menkäämme Beeteliin rakentaakseni sinne alttarin Jumalalle, joka kuuli minua ahdistukseni aikana ja oli kanssani tiellä, jota vaelsin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'He jättivät Jaakobille kaikki vieraat jumalat, jotka olivat heidän hallussaan, sekä renkaat, jotka olivat heidän korvissaan, ja Jaakob kätki ne maahan tammen alle, joka oli Sikemissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'He lähtivät liikkeelle. Jumalan kauhu valtasi heidän ympärillään olevat kaupungit, niin etteivät nämä ajaneet takaa Jaakobin poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Jaakob saapui Luusiin, joka on Kanaanin maassa, se on Beeteliin, ja kaikki väki hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Hän rakensi sinne alttarin ja nimitti paikan Eel-Beeteliksi, koska Jumala oli siellä ilmestynyt hänelle, kun hän pakeni veljeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Debora, Rebekan imettäjä, kuoli, ja hänet haudattiin Beetelin alapuolelle tammen alle. Siitä se sai nimen Allon-Baakuut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Jumala ilmestyi jälleen Jaakobille hänen palattuaan Mesopotamiasta ja siunasi hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Jumala sanoi hänelle: \"Sinun nimesi on Jaakob, mutta älköön sinua enää kutsuttako Jaakobiksi, vaan nimesi olkoon Israel.\" – Ja hän sai nimen Israel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Jumala sanoi hänelle: \"Minä olen Jumala, Kaikkivaltias. Ole hedelmällinen ja lisäänny. Kansa, suuri kansojen joukko on sinusta tuleva, ja kuninkaita lähtee kupeistasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Maan, jonka olen antanut Aabrahamille ja Iisakille, annan sinulle. Myös siemenellesi annan sen maan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Jumala kohosi ylös hänen luotaan siitä paikasta, jossa oli häntä puhutellut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Jaakob pystytti patsaan siihen paikkaan, jossa hän oli häntä puhutellut, kivipatsaan, ja vuodatti juomauhrin sen päälle ja kaatoi öljyä sen päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Jaakob nimitti paikan, jossa Jumala oli häntä puhutellut, Beeteliksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'He lähtivät liikkeelle Beetelistä. Kun vielä oli jonkin verran matkaa Efrataan, Raakel synnytti, ja hänen synnytystuskansa olivat hyvin kovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Tapahtui hänen synnytystuskiensa ollessa kovimmillaan, että kätilö sanoi hänelle: \"Älä pelkää, sillä tämäkin on sinulle poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Kun hänen henkensä oli lähtemäisillään – sillä hänen oli kuoltava – hän antoi hänelle nimen Benoni, mutta hänen isänsä antoi hänelle nimen Benjamin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Niin Raakel kuoli siellä, ja hänet haudattiin Efratan tien varteen Beetlehemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Jaakob pystytti hänen haudalleen patsaan. Tämä Raakelin hautapatsas on olemassa vielä tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Israel lähti liikkeelle sieltä ja pystytti telttansa Migdal-Ederin tuolle puolen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Tapahtui, kun Israel asui siinä maassa, että Ruuben meni ja makasi Bilhan, isänsä sivuvaimon, kanssa, ja Israel sai sen kuulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Jaakobilla oli kaksitoista poikaa. Leean pojat olivat Ruuben, Jaakobin esikoinen, Simeon, Leevi, Juuda, Isaskar ja Sebulon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Raakelin pojat olivat Joosef ja Benjamin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Bilhan, Raakelin orjattaren, pojat olivat Daan ja Naftali.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Silpan, Leean orjattaren, pojat olivat Gaad ja Asser. Nämä ovat ne Jaakobin pojat, jotka syntyivät hänelle Mesopotamiassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Jaakob saapui isänsä Iisakin luo Mamreen, Kirjat-Arbaan, se on Hebroniin, jossa Aabraham ja Iisak olivat asuneet muukalaisina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Iisakin elinaika oli sata kahdeksankymmentä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Iisak vaipui kuolemaan ja tuli otetuksi heimonsa luo, vanhana ja elämästä kylliksi saaneena. Hänen poikansa Eesau ja Jaakob hautasivat hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Tämä on Eesaun eli Edomin suvun syntykirja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Eesau otti vaimoikseen Kanaanin tyttäristä Aadan, heettiläisen Eelonin tyttären, ja Oholibaman, joka oli hivviläisen Sibonin pojan Anan tytär,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'ja Baasematin, Ismaelin tyttären, Nebajotin sisaren.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Aada synnytti Eesaulle Elifaan, ja Baasemat synnytti Reguelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Oholibama synnytti Jeuksen, Jalamin ja Koorahin. Nämä olivat Eesaun pojat, jotka syntyivät hänelle Kanaanin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Eesau otti vaimonsa, poikansa ja tyttärensä ja kaiken talonväkensä, karjansa ja kaikki juhtansa ja kaiken tavaransa, jonka hän oli hankkinut Kanaanin maassa, ja lähti toiseen maahan pois veljensä Jaakobin luota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Sillä heidän omaisuutensa oli niin suuri, etteivät he voineet asua yhdessä, eikä se maa, jossa he asuivat muukalaisina, riittänyt heille heidän karjansa paljouden tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Eesau asui Seirin vuoristossa. Eesau on sama kuin Edom.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Tämä on edomilaisten kantaisän Eesaun suvun syntykirja, hänen, joka asui Seirin vuoristossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Nämä ovat Eesaun poikien nimet: Elifas, Eesaun vaimon Aadan poika, ja Reguel, Eesaun vaimon Baasematin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Elifaan pojat olivat Teeman, Oomar, Sefo, Gaetam ja Kenas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Timna oli Elifaan, Eesaun pojan, sivuvaimo, ja hän synnytti Elifaalle Amalekin. Nämä olivat Eesaun vaimon Aadan pojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Reguelin pojat olivat nämä: Nahat ja Sera, Samma ja Missa. He olivat Eesaun vaimon Baasematin pojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Nämä olivat Eesaun vaimon Oholibaman, Sibonin pojan Anan tyttären, pojat, jotka hän synnytti Eesaulle: Jeus, Jalam ja Koorah.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Nämä olivat Eesaun poikien sukuruhtinaat: Elifaan, Eesaun esikoisen, pojat olivat ruhtinas Teeman, ruhtinas Oomar, ruhtinas Sefo, ruhtinas Kenas,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'ruhtinas Koorah, ruhtinas Gaetam, ruhtinas Amalek. Nämä olivat ne ruhtinaat, jotka polveutuivat Elifaasta Edomin maassa. He olivat Aadan pojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Nämä olivat Reguelin, Eesaun pojan, pojat: ruhtinas Nahat, ruhtinas Sera, ruhtinas Samma, ruhtinas Missa. Nämä olivat ne ruhtinaat, jotka polveutuivat Reguelista Edomin maassa. Ne olivat Eesaun vaimon Baasematin poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Nämä olivat Eesaun vaimon Oholibaman pojat: ruhtinas Jeus, ruhtinas Jalam, ruhtinas Koorah. Nämä olivat ne ruhtinaat, jotka polveutuivat Eesaun vaimosta, Anan tyttärestä Oholibamasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Nämä olivat Eesaun, se on Edomin, pojat, ja nämä heidän sukuruhtinaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Nämä olivat hoorilaisen Seirin pojat, sen maan asukkaat: Lootan, Soobal, Sibon, Ana,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Diison, Eeser ja Diisan. Nämä olivat hoorilaisten sukuruhtinaat, Seirin pojat, Edomin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Lootanin pojat olivat Hoori ja Heemam, ja Lootanin sisar oli Timna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Nämä olivat Soobalin pojat: Alvan, Maanahat ja Eebal, Sefo ja Oonam.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Nämä olivat Sibonin pojat: Aija ja Ana. Tämä oli se Ana, joka löysi lämpimät lähteet erämaassa, paimentaessaan isänsä Sibonin aaseja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Nämä olivat Anan lapset: Diison ja Oholiba, Anan tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Nämä olivat Diisonin pojat: Hemdan, Esban, Jitran ja Keran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Nämä olivat Eeserin pojat: Bilhan, Saavan ja Akan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Nämä olivat Diisanin pojat: Uus ja Aran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Nämä olivat hoorilaisten sukuruhtinaat: ruhtinas Lootan, ruhtinas Soobal, ruhtinas Sibon, ruhtinas Ana,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'ruhtinas Diison, ruhtinas Eeser, ruhtinas Diisan. Nämä olivat hoorilaisten sukuruhtinaat, ruhtinas ruhtinaalta, Seirin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Nämä olivat ne kuninkaat, jotka hallitsivat Edomin maassa ennen kuin yksikään kuningas oli hallinnut israelilaisia:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Bela, Beorin poika, oli kuninkaana Edomissa, ja hänen kaupunkinsa nimi oli Dinhaba.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Kun Bela kuoli, tuli Joobab, Seran poika, Bosrasta, kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Kun Joobab kuoli, tuli Huusam, teemanilaisten maasta, kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Kun Huusam kuoli, tuli Hadad, Bedadin poika, kuninkaaksi hänen jälkeensä, hän, joka voitti midianilaiset Mooabin arolla, ja hänen kaupunkinsa nimi oli Avit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Kun Hadad kuoli, tuli Samla, Masrekasta, kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Kun Samla kuoli, tuli Saul, Rehobotista, virran varrelta, kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Kun Saul kuoli, tuli Baal-Haanan, Akborin poika, kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Kun Baal-Haanan, Akborin poika, kuoli, tuli Hadar kuninkaaksi hänen jälkeensä, ja hänen kaupunkinsa nimi oli Paagu. Hänen vaimonsa nimi oli Mehetabel, joka oli Matredin, Mee-Saahabin tyttären, tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Nämä ovat Eesaun sukuruhtinaiden nimet, heidän sukujensa, asuinpaikkojensa ja nimiensä mukaan: ruhtinas Timna, ruhtinas Alva, ruhtinas Jetet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'ruhtinas Oholibama, ruhtinas Eela, ruhtinas Piinon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'ruhtinas Kenas, ruhtinas Teeman, ruhtinas Mibsar,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'ruhtinas Magdiel, ruhtinas Iiram. Nämä olivat Edomin sukuruhtinaat, heidän asuinpaikkojensa mukaan heidän perintömaassaan – Edomin, se on Eesaun, edomilaisten kantaisän, sukuruhtinaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Jaakob asui siinä maassa, jossa hänen isänsä oli oleskellut muukalaisena, Kanaanin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Tämä on Jaakobin suvun syntykirja. Kun Joosef oli seitsemäntoista vuoden vanha, hän oli veljiensä kanssa paimentamassa lampaita. Hän oli nuorukaisena isänsä vaimojen Bilhan ja Silpan poikien seurassa. Hän kertoi isälleen, mitä pahaa kuuli heistä puhuttavan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Israel rakasti Joosefia enemmän kuin kaikkia muita poikiaan, koska hän oli syntynyt hänelle hänen vanhalla iällään, ja hän teetti hänelle pitkäliepeisen, hihallisen viitan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Kun hänen veljensä näkivät, että heidän isänsä rakasti häntä enemmän kuin kaikkia hänen veljiään, he vihasivat häntä eivätkä voineet puhua hänelle ystävällisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Kerran Joosef näki unen ja kertoi sen veljilleen. Sen jälkeen he vihasivat häntä vielä enemmän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Hän näet sanoi heille: \"Kuulkaa, minkä unen olen nähnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Katso, olimme sitomassa lyhteitä vainiolla, ja katso, minun lyhteeni nousi seisomaan, ja teidän lyhteenne asettuivat sen ympärille ja kumarsivat minun lyhdettäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Niin hänen veljensä sanoivat hänelle: \"Sinäkö tulisit meidän kuninkaaksemme, sinäkö hallitsisit meitä?\" He vihasivat häntä vielä enemmän hänen uniensa ja puheidensa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Hän näki vielä toisenkin unen, jonka hän kertoi veljilleen ja sanoi: \"Minä näin vielä unen: katso, aurinko, kuu ja yksitoista tähteä kumarsivat minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Kun hän kertoi sen isälleen ja veljilleen, hänen isänsä nuhteli häntä ja sanoi hänelle: \"Mikä se sellainen uni on, jonka olet nähnyt? Olisiko minun, äitisi ja veljiesi tultava kumartumaan eteesi maahan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Hänen veljensä kadehtivat häntä. Mutta hänen isänsä pani tämän mieleensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Kun hänen veljensä olivat menneet kaitsemaan isänsä lampaita Sikemiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Israel sanoi Joosefille: \"Eivätkö veljesi ole paimenessa Sikemissä. Tule, lähetän sinut heidän luokseen.\" Hän vastasi: \"Tässä olen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Hän sanoi hänelle: \"Mene katsomaan, kuinka veljesi ja karja voivat, ja kerro sitten minulle.\" Niin hän lähetti hänet matkalle Hebronin laaksosta, ja hän tuli Sikemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Muuan mies kohtasi hänet, hänen harhaillessaan kedolla. Mies kysyi häneltä: \"Mitä etsit?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Hän vastasi: \"Minä etsin veljiäni. Sano minulle, missä he ovat paimentamassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Mies vastasi: \"He lähtivät pois täältä, sillä kuulin heidän sanovan: \'Menkäämme Dootaniin.\'\" Niin Joosef meni veljiensä perässä ja löysi heidät Dootanista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Kun he kaukaa näkivät hänet ja ennen kuin hän saapui heidän luokseen, he pitivät neuvoa tappaakseen hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'He sanoivat toisilleen: \"Katso, tuolla se unennäkijä tulee!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Tulkaa, tappakaamme nyt hänet ja heittäkäämme hänet johonkin kaivoon ja sanokaamme: villipeto on hänet syönyt. Saammepa sitten nähdä, mitä hänen unistaan tulee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Kun Ruuben kuuli sen, hän tahtoi pelastaa hänet heidän käsistään ja sanoi: \"Älkäämme lyökö häntä kuoliaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Vielä Ruuben sanoi heille: \"Älkää vuodattako verta. Heittäkää hänet tähän kaivoon, joka on täällä erämaassa, mutta älkää tehkö hänelle väkivaltaa.\" Hän näet tahtoi pelastaa hänet heidän käsistään saattaakseen hänet takaisin isänsä luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Kun Joosef sitten tuli veljiensä luo, he riisuivat Joosefilta hänen viittansa, pitkäliepeisen, hihallisen viitan, joka oli hänen yllään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'ja ottivat hänet ja heittivät hänet kaivoon. Mutta kaivo oli tyhjä. Siinä ei ollut vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Sen jälkeen he istuivat aterioimaan. Kun he nostivat silmänsä, he näkivät ismaelilaisten karavaanin tulevan Gileadista. Heidän kamelinsa kuljettivat kumihartsia, balsamia ja mirhaa. He olivat viemässä niitä Egyptiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Silloin Juuda sanoi veljillensä: \"Mitä hyötyä meillä on siitä, että surmaamme veljemme ja salaamme hänen verensä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Tulkaa, myykäämme hänet ismaelilaisille, mutta älköön kätemme kajotko häneen, sillä hän on veljemme, omaa lihaamme.\" Hänen veljensä kuulivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Kun nyt midianilaiset kauppiaat olivat menossa ohi, veljet vetivät Joosefin ylös kaivosta ja myivät Joosefin kahdestakymmenestä hopeasekelistä ismaelilaisille. Nämä veivät Joosefin Egyptiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Kun Ruuben palasi kaivolle, katso, Joosefia ei enää ollut kaivossa. Silloin hän repäisi vaatteensa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'palasi veljiensä luo ja sanoi: \"Poika on kadonnut. Voi minua, minne minä joudun!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Niin he ottivat Joosefin viitan, teurastivat vuohipukin ja kastoivat viitan vereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Sitten he lähettivät tuon pitkäliepeisen, hihallisen viitan kotiin isälleen ja sanoivat: \"Tämän me löysimme. Tarkasta, onko se poikasi viitta vai ei.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Tarkastettuaan sen hän sanoi: \"Tämä on poikani viitta. Villipeto on hänet syönyt. Totisesti, Joosef on raadeltu kuoliaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Jaakob repäisi vaatteensa, pani säkin lanteilleen ja suri poikaansa pitkät ajat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Kaikki hänen poikansa ja tyttärensä kävivät häntä lohduttamaan, mutta hän ei huolinut lohdutuksesta, vaan sanoi: \"Murehtien minä menen hautaan poikani luo\", ja hänen isänsä itki häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Mutta midianilaiset myivät hänet Egyptiin Potifarille, joka oli faraon varainhoitaja ja henkivartioston päällikkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Siihen aikaan Juuda lähti pois veljiensä luota ja asettui erään Adullamissa asuvan miehen luo, jonka nimi oli Hiira.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Siellä Juuda näki Suua-nimisen kanaanilaisen miehen tyttären, ja hän otti tämän omakseen ja yhtyi häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Hän tuli raskaaksi ja synnytti pojan, ja hän antoi hänelle nimen Eer.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Taas hän tuli raskaaksi ja synnytti pojan ja antoi hänelle nimen Oonan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Hän synnytti vieläkin pojan ja antoi hänelle nimen Seela. Synnyttäessään hänet hän oli Kesibissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Juuda otti Eerille, esikoiselleen, vaimon, jonka nimi oli Taamar.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Mutta Eer, Juudan esikoinen, ei ollut Herralle otollinen. Sen tähden Herra antoi hänen kuolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Niin Juuda sanoi Oonanille: \"Yhdy veljesi leskeen ja ota hänet lankousavioon ja herätä siemen veljellesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Mutta kun Oonan tiesi, ettei siemen olisi oleva hänen, hän antoi aina yhtyessään veljensä vaimoon siemenensä mennä maahan, ettei hankkisi jälkeläistä veljelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Mutta se, minkä hän teki, oli paha Herran silmissä. Siksi Herra antoi hänenkin kuolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Silloin Juuda sanoi miniälleen Taamarille: \"Asu leskenä isäsi talossa, kunnes poikani Seela tulee täysikasvuiseksi.\" Hän näet ajatteli: \"Kun ei vain tämäkin kuolisi niin kuin hänen veljensä.\" Niin Taamar meni pois ja jäi asumaan isänsä kotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Pitkän aikaa sen jälkeen Suuan tytär, Juudan vaimo, kuoli. Suruajan mentyä Juuda lähti ystävänsä adullamilaisen Hiiran kanssa Timnaan lammastensa keritsiäisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Niin Taamarille tuotiin sanoma: \"Katso, appesi menee Timnaan keritsemään lampaitaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Silloin hän riisui pois leskenvaatteensa ja verhoutui huntuun peittäytyen siihen ja istui Eenaimin portille, Timnaan vievän tien varteen. Sillä hän oli nähnyt, että vaikka Seela oli täysikasvuinen, häntä ei annettu Seelalle vaimoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Kun nyt Juuda näki hänet, hän luuli häntä portoksi, sillä hän oli peittänyt kasvonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Hän poikkesi hänen luokseen tiepuoleen ja sanoi: \"Anna minun yhtyä sinuun.\" Hän näet ei tiennyt, että nainen oli hänen miniänsä. Tämä vastasi: \"Mitä annat minulle saadaksesi yhtyä minuun?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Hän sanoi: \"Lähetän sinulle kilin laumastani.\" Nainen vastasi: \"Annatko minulle pantin, kunnes lähetät sen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Hän sanoi: \"Mitä minun on annettava sinulle pantiksi?\" Hän vastasi: \"Sinettisi, nauhasi ja sauvasi, joka on kädessäsi.\" Niin hän antoi ne hänelle ja yhtyi häneen, ja hän tuli hänestä raskaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Hän nousi ja meni sieltä ja pani pois huntunsa ja pukeutui lesken vaatteisiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Mutta Juuda lähetti adullamilaisen ystävänsä viemään kiliä saadakseen pantin takaisin naiselta, mutta hän ei löytänyt häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Hän kyseli paikkakunnan miehiltä ja sanoi: \"Missä on se pyhäkköportto, joka istui Enaimissa tien varressa?\" He vastasivat: \"Ei täällä ole ollut mitään pyhäkköporttoa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Hän palasi Juudan luo ja sanoi: \"En löytänyt häntä, ja myös sen paikkakunnan miehet sanoivat, ettei siellä ole ollutkaan mitään pyhäkköporttoa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Juuda sanoi: \"Pitäköön sen, ettemme joutuisi häpeään. Katso, olen lähettänyt tämän kilin, mutta et ole löytänyt häntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Noin kolmen kuukauden kuluttua ilmoitettiin Juudalle: \"Sinun miniäsi Taamar on harjoittanut haureutta, ja haureudesta hän on myös tullut raskaaksi.\" Juuda sanoi: \"Viekää hänet poltettavaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Mutta kun häntä vietiin, hän lähetti sanan apelleen sanoen: \"Minä olen raskaana siitä miehestä, jonka nämä ovat.\" Hän käski sanoa: \"Tarkasta, kenen tämä sinetti, nämä nauhat ja tämä sauva ovat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Juuda tunsi ne ja sanoi: \"Hän on oikeassa minua vastaan, koska en antanut häntä pojalleni Seelalle.\" Hän ei kuitenkaan enää yhtynyt häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Kun hänen synnyttämisensä aika tuli, katso, hänen kohdussaan oli kaksoset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Hänen synnyttäessään pisti toinen kätensä ulos. Kätilövaimo otti punaista lankaa ja sitoi sen hänen käteensä ja sanoi: \"Tämä tuli ensiksi ulos.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Mutta kun hän sitten taas veti kätensä takaisin, katso, silloin tuli hänen veljensä ulos, ja kätilövaimo sanoi: \"Minkä repeämän oletkaan reväissyt itsellesi!\" Hän sai nimen Peres.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Sitten tuli hänen veljensä, jonka kädessä oli punainen lanka, ja hän sai nimen Sera.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Joosef vietiin Egyptiin, ja Potifar, egyptiläinen mies, joka oli faraon varainhoitaja ja henkivartioston päämies, osti hänet ismaelilaisilta, jotka olivat hänet sinne tuoneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Herra oli Joosefin kanssa, niin että hän menestyi. Hän oli isäntänsä, egyptiläisen, talossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Hänen isäntänsä näki, että Herra oli hänen kanssaan ja että Herra antoi kaiken, mitä hän teki, menestyä hänen käsissään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Niin Joosef saavutti hänen suosionsa ja sai palvella häntä. Hän asetti hänet talonsa hoitajaksi ja uskoi hänen haltuunsa kaikki, mitä hänellä oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Siitä ajasta lähtien, kun hän oli uskonut hänen hoitoonsa talonsa ja kaiken, mitä hänellä oli, Herra siunasi egyptiläisen taloa Joosefin tähden. Herran siunaus oli kaikessa, mitä hänellä oli kotona ja kedolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Hän jätti Joosefin haltuun kaiken, mitä hänellä oli, eikä hän itse välittänyt mistään, paitsi ruoasta, jota söi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Joosefilla oli kaunis vartalo ja kauniit kasvot. Sitten tapahtui jonkin ajan kuluttua, että hänen isäntänsä puoliso iski silmänsä Joosefiin ja sanoi: \"Makaa kanssani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Mutta hän kieltäytyi ja sanoi isäntänsä puolisolle: \"Katso, isäntäni ei itse välitä mistään, mitä talossa on, vaan on uskonut minun haltuuni kaiken, mitä hänellä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Hänellä ei ole tässä talossa enempää valtaa kuin minulla, eikä hän ole kieltänyt minulta mitään, paitsi sinut, koska olet hänen puolisonsa. Kuinka siis tekisin niin suuren vääryyden ja rikkoisin Jumalaa vastaan!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Vaikka vaimo joka päivä puhui sellaista Joosefille, tämä ei suostunut makaamaan hänen vieressään eikä olemaan hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Mutta eräänä päivänä, kun Joosef tuli taloon toimittamaan askareitaan eikä ketään talonväestä ollut sisällä saapuvilla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'hän tarttui Joosefin viittaan ja sanoi: \"Makaa kanssani.\" Mutta tämä jätti viittansa hänen käsiinsä, pakeni ja riensi ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Kun hän nyt huomasi, että Joosef oli jättänyt viittansa hänen käsiinsä ja paennut ulos,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'hän huusi talonväkeään ja sanoi heille näin: \"Katsokaa, hän on tuonut meille heprealaisen miehen pitämään meitä pilkkanaan. Tämä tuli luokseni maatakseen kanssani, mutta minä huusin kovalla äänellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Kun hän kuuli minun kirkaisevan ja huutavan, hän jätti viittansa viereeni, pakeni ja riensi ulos.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Hän pani viitan viereensä siihen asti, kunnes Joosefin isäntä tuli kotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Hän puhui hänelle samalla tavalla, sanoen: \"Tuo heprealainen orja, jonka olet tuonut meille, tuli luokseni pitämään minua pilkkanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Mutta kun kirkaisin ja huusin, hän jätti viittansa viereeni ja pakeni ulos.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Kun hänen isäntänsä kuuli puolisonsa kertovan ja sanovan: \"Näin orjasi on tehnyt minulle\", syttyi hänen vihansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Joosefin isäntä otti hänet ja pani hänet vankilaan, paikkaan, jossa kuninkaan vankeja säilytettiin. Hän jäi siihen vankilaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Mutta Herra oli Joosefin kanssa ja oli hänelle suosiollinen ja päästi hänet vankilan päällikön armoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Vankilan päällikkö uskoi kaikki vangit, jotka vankilassa olivat, Joosefin haltuun. Kaikki, mitä siellä toimitettiin, tehtiin hänen toimestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Vankilan päällikkö ei valvonut ollenkaan Joosefille uskottua, sillä Herra oli Joosefin kanssa. Herra antoi menestyä sen, mitä hän teki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Jonkin ajan kuluttua tapahtui, että Egyptin kuninkaan juomanlaskija ja leipuri rikkoivat herraansa, Egyptin kuningasta, vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Farao vihastui näihin kahteen hoviherraansa, ylimpään juomanlaskijaan ja ylimpään leipuriin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'ja pani heidät vankilaan henkivartioston päämiehen taloon, samaan vankilaan, jossa Joosef oli vankina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Henkivartioston päällikkö antoi heille Joosefin heitä palvelemaan. He olivat jonkin aikaa vankilassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Ollessaan vankilassa vangittuina he molemmat, Egyptin kuninkaan juomanlaskija ja leipuri, näkivät samana yönä unta, kumpikin unensa. Kummankin unella oli oma selityksensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Kun Joosef aamulla tuli heidän luokseen, hän huomasi heidät alakuloisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Hän kysyi faraon hoviherroilta, jotka olivat hänen kanssaan vankilassa hänen isäntänsä talossa: \"Miksi olette tänään niin murheellisen näköisiä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'He vastasivat hänelle: \"Olemme kumpikin nähneet unen, eikä ole niille selittäjää.\" Joosef sanoi heille: \"Unien selitykset ovat Jumalan. Kertokaa kuitenkin minulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Niin ylin juomanlaskija kertoi unensa Joosefille ja sanoi hänelle: \"Näin unta, ja katso, edessäni oli viinipuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'Viinipuussa oli kolme oksaa, ja samassa kun se alkoi versoa, sen kukat puhkesivat ja marjat kypsyivät sen tertuissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Minulla oli faraon malja kädessäni, ja otin marjat ja pusersin niistä mehun faraon maljaan ja annoin maljan faraon käteen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Joosef sanoi hänelle: \"Tämä on sen selitys: kolme oksaa merkitsee kolmea päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Kolmen päivän kuluttua farao korottaa pääsi ja asettaa sinut takaisin virkaasi. Sinä annat faraon maljan hänen käteensä kuten ennenkin, kun olit hänen juomanlaskijansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Mutta muista minua, kun sinun käy hyvin, ja osoita minua kohtaan laupeutta mainitsemalla minusta faraolle ja toimittamalla minut pois tästä talosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Sillä minut on varastettu heprealaisten maasta, enkä ole täälläkään tehnyt mitään, mistä minut olisi tullut panna tähän vankikuoppaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Kun ylin leipuri näki, että Joosef antoi hyvän selityksen, hän sanoi hänelle: \"Minäkin näin unen, ja katso, kolme vehnäleipäkoria oli pääni päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Ylimmässä korissa oli kaikenlaisia leivoksia faraon syötäväksi, mutta linnut söivät ne korista, joka oli minun pääni päällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Joosef vastasi ja sanoi: \"Tämä on sen selitys: kolme koria merkitsee kolmea päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Kolmen päivän kuluttua farao korottaa pääsi ripustamalla sinut hirsipuuhun, ja taivaan linnut syövät lihasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Kolmantena päivänä sen jälkeen, faraon syntymäpäivänä, farao laittoi pidot kaikille palvelijoilleen. Silloin hän korotti palvelijoidensa joukosta sekä ylimmän juomanlaskijan että ylimmän leipurin pään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Ylimmän juomanlaskijan hän asetti hänen entiseen juomanlaskijan toimeensa, niin että hän sai antaa maljan faraon käteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'Mutta ylimmän leipurin hän hirtätti, niin kuin Joosef oli heille selityksessään sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Mutta ylin juomanlaskija ei muistanut Joosefia, vaan unohti hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Kahden vuoden kuluttua tapahtui, että farao näki unen. Hän oli seisovinaan Niilin rannalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Katso, virrasta nousi seitsemän kaunista ja lihavaa lehmää, jotka kävivät laitumella kaislikossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Katso, niiden jälkeen nousi virrasta toiset seitsemän lehmää, rumia ja laihoja. Ne asettuivat edellisten lehmien viereen virran rannalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Rumat ja laihat lehmät söivät seitsemän kaunista ja lihavaa lehmää. Siihen farao heräsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Mutta hän nukahti uudestaan ja näki toisen unen: seitsemän paksua ja kaunista tähkää kasvoi samassa korressa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Katso, niiden jälkeen kasvoi vielä seitsemän tähkää, ohutta ja itätuulen polttamaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Ohuet tähkät nielivät seitsemän paksua ja täyteläistä tähkää. Siihen farao heräsi, ja katso, se oli ollut unta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Mutta aamulla hänen mielensä oli levoton, ja hän lähetti kutsumaan eteensä kaikki Egyptin tietäjät ja kaikki viisaat. Farao kertoi heille unensa, mutta ei ollut ketään, joka olisi selittänyt ne faraolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Silloin ylin juomanlaskija puhui faraolle sanoen: \"Nyt minä muistan syntini.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Farao oli vihastunut palvelijoihinsa, ja hän pani minut vankilaan henkivartijoiden päämiehen taloon, minut ja ylimmän leipurin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Me molemmat, minä ja hän, näimme samana yönä unta. Näimme kumpikin unemme, jolle oli oma selityksensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Siellä oli kanssamme heprealainen nuorukainen, henkivartijoiden päämiehen palvelija. Kerroimme hänelle unemme. Hän selitti ne meille. Hän selitti, mitä kummankin uni merkitsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Niin kuin hän meille oli selittänyt, niin kävikin: minut asetettiin entiseen virkaani, toinen hirtettiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Silloin farao lähetti kutsumaan Joosefin eteensä. Hänet tuotiin kiireesti vankikuopasta. Hän ajatti hiuksensa, vaihtoi vaatteensa ja tuli faraon eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Farao sanoi Joosefille: \"Minä olen nähnyt unen, eikä ole sille selittäjää, mutta olen kuullut kerrottavan sinusta, että kun kuulet unen, voit sen selittää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Joosef vastasi faraolle sanoen: \"En minä, mutta Jumala antaa faraolle suotuisan vastauksen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Farao puhui Joosefille: \"Näin unen: Seisoin Niilin rannalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Katso, virrasta nousi seitsemän lihavaa ja kaunista lehmää, jotka kävivät laitumella kaislikossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Katso, niiden jälkeen nousi virrasta toiset seitsemän lehmää, kurjia, kovin rumia ja laihoja. En ole koko Egyptin maassa nähnyt niin rumia kuin ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Laihat ja rumat lehmät söivät ensimmäiset, lihavat lehmät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Mutta vaikka ne olivat nielleet nämä, ei voinut huomata, että ne olivat nielleet ne, vaan ne olivat näöltään yhtä rumia kuin ennenkin. Silloin heräsin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Mutta taas näin unta: seitsemän täyteläistä ja kaunista tähkää kasvoi samassa oljessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Katso, niiden jälkeen kasvoi vielä seitsemän tähkää, kuivunutta, ohutta ja itätuulen polttamaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Ohuet tähkät nielivät seitsemän kaunista tähkää. Kerroin tämän tietäjille, mutta kukaan ei kyennyt sanomaan minulle, mitä se merkitsee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Niin Joosef sanoi faraolle: \"Faraon unet merkitsevät kumpikin samaa. Jumala on ilmaissut faraolle, mitä hän on tekevä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Seitsemän kaunista lehmää ovat seitsemän vuotta, seitsemän kaunista tähkää ovat myös seitsemän vuotta. Unilla on sama merkitys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Seitsemän laihaa ja rumaa lehmää, jotka nousivat niiden jälkeen, ovat seitsemän vuotta, ja seitsemän tyhjää, itätuulen polttamaa tähkää ovat seitsemän nälkävuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Tätä tarkoitin, kun sanoin faraolle: Jumala on antanut faraon nähdä, mitä hän on tekevä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Katso, tulee seitsemän vuotta, jolloin on suuri viljavuus koko Egyptin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Mutta niitä seuraa seitsemän sellaista nälkävuotta, että Egyptin maan entinen viljavuus kokonaan unohtuu, ja nälänhätä tuottaa maalle häviön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Silloin ei enää tiedetä mitään maassa vallinneesta viljavuudesta sitä seuraavan nälänhädän vuoksi, sillä se on oleva erittäin kova.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Mutta että uni toistui faraolle, se tietää, että Jumala on asian varmasti päättänyt ja että Jumala antaa sen pian tapahtua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Nyt valitkoon farao ymmärtäväisen ja taitavan miehen ja asettakoon hänet Egyptin hallitusmieheksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Näin tehköön farao: asettakoon päällysmiehiä maahan ja ottakoon viidennen osan Egyptin maan sadosta seitsemänä viljavuotena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Koottakoon näinä hyvinä vuosina, jotka tulevat, kaikki niiden sato ja koottakoon viljaa faraon haltuun, talletettakoon sato kaupunkeihin ja säilytettäköön,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'niin että maalla on viljaa säästössä seitsemän nälkävuoden varalle, jotka kohtaavat Egyptin maata, eikä maa joudu perikatoon nälänhädän aikana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Puhe oli hyvä faraon ja kaikkien hänen palvelijoidensa silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Farao sanoi palvelijoilleen: \"Voisimmeko löytää ketään, jossa on Jumalan Henki niin kuin tässä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Farao sanoi Joosefille: \"Koska Jumala on ilmoittanut sinulle kaiken tämän, ei ole ketään toista niin ymmärtäväistä ja taitavaa kuin sinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Hoida sinä taloani, ja käskyäsi totelkoon koko kansani. Ainoastaan valtaistuimen puolesta olen sinua korkeampi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Farao sanoi Joosefille: \"Katso, olen asettanut sinut koko Egyptin maan hallitsijaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Farao otti sinettisormuksensa kädestään, pani sen Joosefin käteen, puetti hänen ylleen hienot pellavavaatteet ja ripusti kultakäädyt hänen kaulaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Hän antoi hänen ajaa omissa, lähinnä parhaissa vaunuissaan, hänen edellään huudettiin: abrek! ja hänet oli asetettu koko Egyptin maan hallitsijaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Farao sanoi Joosefille: \"Minä olen farao, mutta sinun tahtomattasi älköön kukaan nostako kättä tai jalkaa koko Egyptin maassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Farao nimitti Joosefin Saafenat-Paneahiksi ja antoi hänelle puolisoksi Aasenatin, Oonin papin Poti-Feran tyttären. Joosef lähti tarkastamaan Egyptin maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Joosef oli kolmenkymmenen vuoden vanha, kun hän tuli faraon, Egyptin kuninkaan, palvelijaksi. Joosef lähti faraon luota ja kulki läpi koko Egyptin maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Seitsemänä viljavuotena maa kasvoi hyvin runsaasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Näinä seitsemänä hyvänä vuotena, jotka tulivat Egyptin maahan, hän kokosi kaikkea viljaa ja talletti sen kaupunkeihin. Hän talletti kuhunkin kaupunkiin sen viljan, joka tuotiin ympäristön vainioilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Joosef kokosi viljaa kuin meren hiekkaa, hyvin suuret määrät, siihen asti että lakattiin sitä mittaamasta, sillä se ei ollut enää mitattavissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Joosefille syntyi, ennen kuin nälkävuosi tuli, kaksi poikaa, jotka Aasenat, Oonin papin Poti-Feran tytär, synnytti hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Esikoiselle Joosef antoi nimen Manasse, \"sillä\", hän sanoi, \"Jumala on saattanut minut unohtamaan kaikki vaivani ja koko isäni kodin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Toiselle hän antoi nimen Efraim, \"sillä\", hän sanoi, \"Jumala on tehnyt minut hedelmälliseksi kärsimysteni maassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Ne seitsemän viljavuotta, jotka tulivat Egyptin maahan, tulivat täyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Sen jälkeen alkoi seitsemän nälkävuotta, niin kuin Joosef oli sanonut, ja nälänhätä tuli kaikkiin maihin, mutta Egyptin maassa oli leipäviljaa kaikkialla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Sitten koko Egyptin maa näki nälkää, ja kansa huusi faraolta leipää. Silloin farao sanoi kaikille egyptiläisille: \"Menkää Joosefin luo ja tehkää, mitä hän käskee teidän tehdä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Kun nälkä ahdisti koko maata, Joosef avasi kaikki varastot ja myi viljaa egyptiläisille. Mutta nälänhätä tuli yhä kovemmaksi Egyptin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Kaikista maista tultiin Egyptiin Joosefin luo ostamaan viljaa, sillä kaikissa maissa oli kova nälänhätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Kun Jaakob sai tietää, että Egyptissä oli viljaa, hän sanoi pojilleen: \"Mitä epäröitte?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Hän sanoi: \"Katso, olen kuullut, että Egyptissä on viljaa. Menkää sinne ja ostakaa meille sieltä viljaa, että pysyisimme hengissä emmekä kuolisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Kymmenen Joosefin veljeä lähti ostamaan viljaa Egyptistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Mutta Benjaminia, Joosefin veljeä, Jaakob ei lähettänyt hänen veljiensä mukana, sillä hän pelkäsi, että häntä kohtaisi jokin onnettomuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Niin Israelin pojat tulivat muiden tulijoiden mukana ostamaan viljaa, sillä Kanaanin maassa oli nälänhätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Joosef oli käskynhaltijana maassa. Hän myi viljaa kaikelle maan kansalle. Niin Joosefin veljet tulivat ja kumartuivat hänen edessään kasvoilleen maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Joosef näki veljensä ja tunsi heidät, mutta tekeytyi heille vieraaksi, puhutteli heitä ankarasti ja kysyi heiltä: \"Mistä tulette?\" He vastasivat: \"Kanaanin maasta tulemme ostamaan ruokaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Joosef tunsi veljensä, mutta he eivät tunteneet häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Joosef muisti unet, jotka hän oli nähnyt heistä, ja sanoi heille: \"Te olette vakoojia. Olette tulleet katsomaan, mistä maa olisi avoin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'He vastasivat hänelle: \"Ei, herra, palvelijasi ovat tulleet ostamaan elintarpeita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Olemme kaikki saman miehen poikia, olemme rehellisiä miehiä. Palvelijasi eivät ole vakoojia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Mutta hän sanoi heille: \"Ei ole niin, vaan te olette tulleet katsomaan, mistä maa olisi avoin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'He vastasivat: \"Meitä, palvelijoitasi, on kaksitoista veljestä, saman miehen poikia Kanaanin maasta. Nuorin on nyt kotona isämme luona, ja yhtä ei enää ole.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Joosef sanoi heille: \"Niin on, kuin olen teille puhunut: te olette vakoojia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Näin te tulette koeteltaviksi: niin totta kuin farao elää, te ette pääse täältä lähtemään, ellei nuorin veljenne tule tänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Lähettäkää yksi joukostanne noutamaan veljenne tänne, mutta teidän muiden pitää jäädä tänne vangeiksi, että koeteltaisiin, oletteko puhuneet totta. Muuten, niin totta kuin farao elää, te olette vakoojia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Sitten hän pani heidät vankilaan kolmeksi päiväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Kolmantena päivänä Joosef sanoi heille: \"Jos tahdotte elää, tehkää näin, sillä minä olen Jumalaa pelkäävä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'jos olette rehellisiä miehiä, jääköön teistä veljeksistä yksi vangiksi vankilaan, jossa teitä säilytettiin, mutta te muut menkää viemään kotiin viljaa perheittenne nälänhätään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Tuokaa nuorin veljenne luokseni. Jos teidän puheenne siten vahvistuu todeksi, vältätte kuoleman.\" Heidän täytyi tehdä niin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Mutta he sanoivat toinen toiselleen: \"Totisesti, me olemme syylliset sen tähden, mitä teimme veljellemme. Sillä me näimme hänen sielunsa tuskan, kun hän anoi meiltä armoa, emmekä kuulleet häntä. Sen tähden tämä tuska on tullut meille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Ruuben vastasi heille sanoen: \"Enkö sanonut teille: \'Älkää tehkö pahoin nuorukaista vastaan!\' Mutta ette kuulleet minua. Katsokaa, nyt kostetaan hänen verensä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Mutta he eivät tienneet, että Joosef ymmärsi heitä, sillä hän puhui heille tulkin kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Hän kääntyi heistä pois ja itki. Sitten hän kääntyi taas heihin päin ja puhui heidän kanssaan. Hän otti heidän joukostaan Simeonin ja vangitutti hänet heidän nähtensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Joosef käski täyttää heidän säkkinsä viljalla ja panna jokaisen rahat takaisin hänen säkkiinsä sekä antaa heille evästä matkalle. Heille tehtiin niin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'He sälyttivät viljansa aasien selkään ja lähtivät sieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Kun sitten eräs heistä yöpymispaikassa avasi säkkinsä syöttääkseen aasiaan, hän huomasi rahansa säkin suussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Hän sanoi veljilleen: \"Minulle on annettu rahani takaisin. Katso, se on säkissäni.\" Silloin heidän sydämensä vavahti, ja he katsoivat säikähtyneinä toisiinsa sanoen: \"Mitä Jumala on meille tehnyt?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Tultuaan isänsä Jaakobin luo Kanaanin maahan he ilmoittivat hänelle kaikki, mitä heille oli tapahtunut, ja sanoivat:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, '\"Mies, joka on sen maan valtiaana, puhutteli meitä ankarasti ja kohteli meitä, kuin olisimme olleet maata vakoilemassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Mutta sanoimme hänelle: \'Olemme rehellisiä miehiä emmekä mitään vakoojia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Meitä on kaksitoista veljestä saman isän poikia. Yhtä ei enää ole, ja nuorin on nyt kotona isämme luona Kanaanin maassa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Mutta mies, sen maan valtias, sanoi meille: \'Siitä saan tietää, oletteko te rehellisiä miehiä: jättäkää yksi veljistänne luokseni. Ottakaa sitten viljaa perheittenne nälänhätään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Menkää ja tuokaa nuorin veljenne luokseni saadakseni tietää, ettette ole vakoojia, vaan rehellisiä miehiä. Sitten annan teille veljenne takaisin, ja te saatte vapaasti liikkua maassa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Kun he sitten tyhjensivät säkkinsä, niin, katso, kunkin rahakukkaro oli hänen säkissään. Nähdessään rahakukkaronsa he sekä heidän isänsä pelästyivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Heidän isänsä Jaakob sanoi heille: \"Teette minut lapsettomaksi. Joosefia ei enää ole, Simeonia ei enää ole, ja Benjamininkin tahdotte viedä minulta. Tämä kaikki kohtaa minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Ruuben vastasi isälleen sanoen: \"Saat surmata molemmat poikani, jos en tuo häntä sinulle takaisin. Anna hänet huostaani, niin minä tuon hänet sinulle takaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Mutta hän sanoi: \"Poikani ei saa lähteä kanssanne, sillä hänen veljensä on kuollut, ja hän on yksin jäljellä. Jos onnettomuus kohtaa häntä matkalla, jolle aiotte lähteä, saatatte harmaat hapseni vaipumaan murheella hautaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Maassa oli kova nälänhätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Kun he olivat syöneet loppuun viljan, jonka olivat tuoneet Egyptistä, heidän isänsä sanoi heille: \"Menkää jälleen ostamaan meille vähän ruokaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Juuda vastasi hänelle sanoen: \"Mies teroitti meille teroittamalla: \'Ette saa tulla kasvojeni eteen, ellei veljenne ole kanssanne.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Jos annat veljemme seurata mukanamme, lähdemme ostamaan sinulle elintarpeita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Mutta jos et anna, emme lähde. Sillä mies sanoi meille: \'Ette saa tulla kasvojeni eteen, ellei veljenne ole kanssanne.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Israel sanoi: \"Minkä tähden teitte niin pahasti minua kohtaan, että ilmaisitte tuolle miehelle teillä olevan vielä veljen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'He vastasivat: \"Mies kyseli todella tarkasti meistä ja suvustamme, sanoen: \'Elääkö isänne vielä? Onko teillä vielä veljeä?\' Silloin ilmoitimme hänelle, kuten asia on. Saatoimmeko tietää, että hän sanoisi: \'Tuokaa veljenne tänne\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Juuda sanoi isälleen Israelille: \"Anna nuorukaisen seurata mukanani, niin me nousemme ja lähdemme matkalle, että jäisimme eloon, sekä me että sinä, vaimomme ja lapsemme, emmekä kuolisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Minä vastaan hänestä, minun kädestäni saat vaatia hänet. Jos en tuo häntä takaisin luoksesi ja aseta häntä eteesi, olen syyllinen edessäsi koko elinaikani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Totisesti, jos emme olisi näin vitkastelleet, olisimme jo kaksikin kertaa palanneet sieltä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Silloin heidän isänsä Israel sanoi heille: \"Jos niin on, tehkää ainakin tämä: ottakaa säkkeihinne maan parhaimpia tuotteita ja viekää ne miehelle lahjaksi: vähän balsamia ja vähän hunajaa, kumihartsia ja mirhaa, pähkinöitä ja manteleita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Ottakaa mukaanne kaksinkertainen raha, niin että viette takaisin rahan, joka palautettiin säkkienne suussa. Ehkä se oli erehdys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Ottakaa mukaanne myös veljenne, nouskaa ja menkää jälleen miehen luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Jumala, Kaikkivaltias, suokoon, että mies tekisi teille laupeuden ja antaisi toisen veljenne sekä Benjaminin palata kotiin kanssanne. Mutta jos tulen lapsettomaksi, tulen lapsettomaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Miehet ottivat mukaansa lahjan ja kaksinkertaisen rahan sekä myös Benjaminin, nousivat, menivät Egyptiin ja astuivat Joosefin eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Kun Joosef näki Benjaminin heidän seurassaan, hän sanoi huoneenhaltijalleen: \"Vie nämä miehet sisään. Teurasta teuras ja valmista se, sillä miehet saavat syödä päivällistä kanssani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Mies teki, kuten Joosef oli käskenyt, ja vei miehet Joosefin taloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Mutta miehet pelkäsivät, kun heitä vietiin Joosefin taloon, arvellen: \"Sen rahan tähden, joka viime kerralla tuli takaisin säkeissämme, he nyt vievät meitä tänne hyökätäkseen ja karatakseen kimppuumme ottaakseen meidät orjiksi ja anastaakseen aasimme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Niin he menivät Joosefin huoneenhaltijan luo ja puhuttelivat häntä talon ovella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'He sanoivat: \"Oi kuule, herra, me olemme kerran ennen käyneet täällä ostamassa elintarpeita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Kun tulimme yöpaikkaan ja avasimme säkkimme, niin, katso, jokaisen raha oli hänen säkkinsä suussa täysipainoisena. Olemme nyt tuoneet ne mukanamme takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Olemme tuoneet mukanamme toisenkin rahan ostaaksemme viljaa elatukseksemme. Emme tiedä, kuka on pannut rahamme säkkeihimme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Hän vastasi: \"Olkaa rauhassa, älkää pelätkö. Teidän Jumalanne ja teidän isänne Jumala on antanut teidän löytää aarteen säkeistänne. Teidän rahanne on tullut minulle.\" Sitten hän toi heidän luokseen Simeonin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Hän vei miehet Joosefin taloon ja antoi heille vettä jalkojen pesuun ja rehua heidän aaseilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'He laittoivat lahjansa järjestykseen siihen asti, kunnes Joosef tulisi päivälliselle. Sillä he olivat kuulleet, että saisivat aterioida siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Kun Joosef oli tullut kotiin, he veivät hänelle taloon lahjat, jotka heillä oli mukanaan, ja kumartuivat maahan hänen edessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Hän tervehti heitä ja kysyi: \"Kuinka voi teidän vanha isänne, josta puhuitte? Vieläkö hän elää?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'He vastasivat: \"Palvelijasi, meidän isämme, voi hyvin. Hän elää vielä\" ja he kumartuivat ja heittäytyivät maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Hän nosti silmänsä ja näki veljensä Benjaminin, äitinsä pojan, ja kysyi: \"Onko tämä teidän nuorin veljenne, josta puhuitte?\" Sitten hän sanoi: \"Jumala olkoon sinulle, poikani, armollinen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Silloin Joosef keskeytti äkkiä puheensa, sillä nähdessään veljensä hän tuli sydämessään liikutetuksi ja etsi tilaisuutta itkeäkseen. Niin hän meni sisähuoneeseen ja itki siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Pestyään kasvonsa hän tuli sieltä pois, hillitsi itsensä ja käski: \"Tarjotkaa ruokaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Tarjottiin erikseen hänelle ja erikseen heille ja erikseen egyptiläisille, jotka aterioivat hänen kanssaan. Egyptiläiset näet eivät voi syödä yhdessä heprealaisten kanssa, sillä se on egyptiläisille kauhistus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'He istuivat vastapäätä häntä iän mukaan esikoinen ensimmäisenä ja nuorin viimeisenä. Ihmetellen miehet katselivat toisiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Hän antoi kantaa omasta pöydästään ruokia heille, ja Benjaminin annos oli viisi kertaa suurempi kuin kaikkien muiden. He joivat hänen kanssaan ja juopuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Joosef käski huoneenhaltijaansa sanoen: \"Täytä miesten säkit viljalla, niin paljon kuin he voivat kuljettaa, ja pane jokaisen raha hänen säkkinsä suuhun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Nuorimman säkin suuhun pane minun maljani, tuo hopeamalja, lisäksi hänen viljarahansa.\" Hän teki, niin kuin Joosef käski.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Aamulla päivän valjetessa miehet saivat aaseineen lähteä matkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Kun he olivat ehtineet vähän matkaa kaupungin ulkopuolelle, Joosef sanoi huoneenhaltijalleen: \"Nouse ja aja miehiä takaa, ja kun saavutat heidät, sano heille: \'Minkä tähden olette palkinneet hyvän pahalla?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Eikö tämä ole juuri se, josta isäntäni juo ja jolla hän ennustaa. Te olette tehneet väärin näin menetellessänne.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Kun hän sitten saavutti heidät, hän sanoi heille nämä sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'He vastasivat hänelle: \"Minkä tähden herramme sanoo näin? Pois se, että palvelijasi tekisivät niin!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Katso, rahan, jonka löysimme säkkiemme suusta, me olemme tuoneet takaisin sinulle Kanaanin maasta. Kuinka siis olisimme varastaneet hopeaa tai kultaa herrasi talosta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Se palvelijoistasi, jolta se löydetään, kuolkoon, ja me muut tulemme herramme orjiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Hän vastasi: \"Olkoon niin, kuin olette puhuneet. Se, jolta se löydetään, olkoon orjani. Mutta te muut pääsette vapaiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'He laskivat nopeasti säkkinsä maahan, ja jokainen avasi säkkinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Hän etsi alkaen vanhimmasta ja lopettaen nuorimpaan, ja malja löytyi Benjaminin säkistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Silloin he repäisivät vaatteensa, kuormasivat kukin tavaransa aasinsa selkään ja palasivat kaupunkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Juuda meni veljineen Joosefin taloon, jossa tämä vielä oli, ja he lankesivat maahan hänen eteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Joosef sanoi heille: \"Mitä olettekaan tehneet! Ettekö tienneet, että minun kaltaiseni mies saa salaisuudet ilmi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Juuda vastasi: \"Mitä sanoisimmekaan herralleni, mitä puhuisimme ja millä puolustautuisimme! Jumala on paljastanut palvelijoittesi syyllisyyden. Katso, me olemme herrani orjat, niin hyvin me muut kuin se, jolta malja löytyi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Hän sanoi: \"Pois se, että minä tekisin niin! Se, jolta malja löytyi, olkoon orjani, mutta te muut menkää rauhassa kotiin isänne luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Silloin Juuda astui hänen eteensä ja sanoi: \"Oi herrani, salli palvelijasi puhua sana herrani kuullen, älköönkä vihasi syttykö palvelijaasi kohtaan, sillä olet kuin itse farao!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Herrani kysyi palvelijoiltaan sanoen: \'Onko teillä isää tai veljeä?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Me vastasimme herralleni: \'Meillä on kotona vanha isä ja veli, joka on syntynyt hänen vanhoilla päivillään ja on vielä nuori. Mutta tämän veli on kuollut, ja niin hän on jäänyt yksin äidistään, ja hänen isänsä rakastaa häntä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Sanoit palvelijoillesi: \'Tuokaa hänet tänne luokseni, että silmäni saisivat katsella häntä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Sanoimme herralleni: \'Nuorukainen ei voi jättää isäänsä, sillä jos hän jättäisi isänsä, tämä kuolisi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Mutta sinä sanoit palvelijoillesi: \'Jos nuorin veljenne ei tule tänne kanssanne, älkää enää näyttäytykö kasvojeni edessä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Menimme kotiin palvelijasi, minun isäni, luo ja kerroimme hänelle herrani sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Niin isämme sanoi: \'Menkää jälleen ostamaan meille vähän elintarpeita.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Me sanoimme: \'Emme voi lähteä sinne. Me lähdemme ainoastaan, jos nuorin veljemme seuraa mukanamme, sillä emme voi näyttäytyä sen miehen kasvojen edessä, ellei nuorin veljemme ole mukanamme.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Palvelijasi, minun isäni, sanoi meille: \'Tiedättehän itse, että vaimoni synnytti minulle kaksi poikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Toinen lähti pois luotani, ja sanoin: Varmaan hänet on raadeltu kuoliaaksi, enkä ole häntä sen jälkeen nähnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Jos nyt viette minulta tämänkin ja jos onnettomuus kohtaa häntä, saatatte harmaat hapseni vaipumaan tuskalla hautaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Jos nyt tulisin kotiin palvelijasi, isäni, luo eikä meillä olisi mukanamme nuorukaista, johon hän on kaikesta sielustaan kiintynyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'hän kuolisi nähdessään, ettei nuorukainen ole kanssamme, ja me, palvelijasi, saattaisimme palvelijasi, isämme, harmaat hapset vaipumaan murheella hautaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Sillä palvelijasi on luvannut isälleen vastata nuorukaisesta ja sanonut: \'Jos en tuo häntä takaisin luoksesi, olen syyllinen isäni edessä koko elinaikani.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Jääköön siis palvelijasi herralleni orjaksi nuorukaisen sijaan, ja nuorukainen menköön kotiin veljiensä kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Sillä kuinka menen kotiin isäni luo, ellei nuorukainen ole kanssani? En voi nähdä sitä surkeutta, joka tulee isäni osaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Joosef ei voinut kauemmin hillitä itseään kaikkien niiden nähden, jotka seisoivat hänen ympärillään. Hän huusi: \"Antakaa kaikkien mennä pois luotani!\" Niin ei ollut ketään paikalla, kun Joosef ilmaisi itsensä veljilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Hän purskahti ääneen itkemään, niin että egyptiläiset ja faraon hoviväki kuulivat sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Joosef sanoi veljilleen: \"Minä olen Joosef. Vieläkö isäni elää?\" Mutta hänen veljensä eivät voineet vastata hänelle, niin hämmästyksissään he olivat hänen edessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Joosef sanoi veljilleen: \"Tulkaa tänne luokseni.\" He tulivat. Hän sanoi: \"Minä olen Joosef, veljenne, jonka myitte Egyptiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Mutta älkää nyt olko murheissanne älkääkä pahoitelko sitä, että olette myyneet minut tänne, sillä Jumala on lähettänyt minut edellänne pitääkseen teidät hengissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Kaksi vuotta nälänhätä on nyt ollut maassa, ja vielä on jäljellä viisi vuotta, joina ei kynnetä eikä eloa korjata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Jumala lähetti minut edellänne säilyttääkseen teille siemenen maan päällä ja pitääkseen teidät hengissä pelastukseksi monille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Ette siis te ole lähettäneet minua tänne, vaan Jumala. Hän asetti minut faraon neuvonantajaksi ja koko hänen hovinsa herraksi ja koko Egyptin maan valtiaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Menkää, rientäkää isäni luo ja sanokaa hänelle: \'Näin sanoo poikasi Joosef: Jumala on asettanut minut koko Egyptin herraksi, tule luokseni, älä viivyttele!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Asetut Goosenin maakuntaan ja olet minua lähellä, sinä, lapsesi ja lastesi lapset, lampaasi, vuohesi ja nautasi, kaikki, mitä sinulla on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Elätän sinua siellä – vielä on näet viisi nälkävuotta – niin ettet sinä eikä perheesi eikä kukaan omaisistasi sorru puutteeseen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Katso, näette omin silmin, ja myös veljeni Benjamin näkee, että suullani teille puhun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Kertokaa siis isällenne kaikesta siitä kunniasta, joka on tullut osakseni Egyptissä, ja kaikesta, mitä olette nähneet, ja rientäkää ja tuokaa isäni tänne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Hän lankesi veljensä Benjaminin kaulaan ja itki, ja myös Benjamin itki hänen kaulassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Hän suuteli kaikkia veljiään ja itki heidän rinnoillaan. Sen jälkeen hänen veljensä puhelivat hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Kun sanoma siitä, että Joosefin veljet olivat saapuneet, kuului faraon hoviin, se oli faraon ja kaikkien hänen palvelijoidensa mieleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Farao sanoi Joosefille: \"Sano veljillesi: \'Tehkää näin: sälyttäkää kuormat juhtienne selkään ja lähtekää kotiin Kanaanin maahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'ottakaa isänne ja perheenne ja tulkaa luokseni, niin annan teille parasta, mitä Egyptissä on, ja syötte maan lihavuudesta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Näin sinun on käskettävä heitä: \'Tehkää näin: ottakaa itsellenne vaunuja Egyptin maasta lapsianne ja vaimojanne varten ja tuokaa isänne ja tulkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Älkää surko taloustavaroitanne, sillä se, mikä on parasta koko Egyptin maassa, on oleva omaanne.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Israelin pojat tekivät niin, ja Joosef antoi heille vaunuja faraon käskyn mukaan sekä evästä matkaa varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Hän antoi kullekin heistä juhlapuvun, mutta Benjaminille hän antoi kolmesataa hopeasekeliä sekä viisi juhlapukua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Samoin hän lähetti isälleen lahjaksi kymmenen aasia, jotka olivat kuormitetut Egyptin parhaimmilla tavaroilla, ja kymmenen aasintammaa, jotka kantoivat viljaa ja leipää sekä eväitä hänen isälleen matkaa varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Hän päästi veljensä menemään ja sanoi heille: \"Älkää riidelkö matkalla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'He lähtivät Egyptistä ja tulivat isänsä Jaakobin luo Kanaanin maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'He kertoivat hänelle ja sanoivat: \"Joosef on vielä elossa ja on koko Egyptin maan valtias.\" Mutta hänen sydämensä pysyi kylmänä, sillä hän ei uskonut heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Niin he kertoivat hänelle kaiken, mitä Joosef oli puhunut heille. Kun hän näki vaunut, jotka Joosef oli lähettänyt häntä tuomaan, elpyi heidän isänsä Jaakobin henki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Israel sanoi: \"Nyt on minulla kyllin. Poikani Joosef elää vielä, minä menen häntä katsomaan, ennen kuin kuolen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Israel lähti matkalle mukanaan kaikki, mitä hänellä oli. Kun hän saapui Beersebaan, hän uhrasi teurasuhreja isänsä Iisakin Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Jumala puhui Israelille näyssä yöllä. Hän sanoi: \"Jaakob, Jaakob!\" Tämä vastasi: \"Tässä olen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Niin hän sanoi: \"Minä olen Jumala, isäsi Jumala. Älä pelkää mennä Egyptiin, sillä teen siellä sinusta suuren kansan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Minä menen kanssasi alas Egyptiin, ja minä myös johdatan sinut sieltä takaisin. Joosefin käsi on sulkeva silmäsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Jaakob lähti Beersebasta, ja Israelin pojat nostivat isänsä Jaakobin, lapsensa ja vaimonsa vaunuihin, jotka farao oli lähettänyt häntä noutamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'He ottivat karjansa ja tavaransa, jotka he olivat hankkineet Kanaanin maassa, ja tulivat Egyptiin, Jaakob sekä kaikki hänen jälkeläisensä hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Hän vei mukanaan Egyptiin poikansa ja poikiensa pojat, tyttärensä ja poikiensa tyttäret, kaikki jälkeläisensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Nämä ovat Israelin lasten nimet, niiden, jotka tulivat Egyptiin: Jaakob ja hänen poikansa. Jaakobin esikoinen oli Ruuben.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Ruubenin pojat olivat Hanok, Pallu, Hesron ja Karmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Simeonin pojat olivat Jemuel, Jaamin, Oohad, Jaakin, Soohar ja Saul, kanaanilaisen vaimon poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Leevin pojat olivat Geerson, Kehat ja Merari.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Juudan pojat olivat Eer, Oonan, Seela, Peres ja Sera. Mutta Eer ja Oonan olivat kuolleet Kanaanin maassa. Peresin pojat olivat Hesron ja Haamul.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Isaskarin pojat olivat Toola, Puvva, Joob ja Simron.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Sebulonin pojat olivat Sered, Eelon ja Jahleel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Nämä olivat Leean pojat. Hän synnytti heidät Jaakobille Mesopotamiassa sekä tyttären, Diinan. Näitä Jaakobin poikia ja tyttäriä oli kaikkiaan kolmekymmentä kolme henkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Gaadin pojat olivat Sifjon ja Haggi, Suuni ja Esbon, Eeri ja Arodi sekä Areli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Asserin pojat olivat Jimna, Jisva, Jisvi ja Beria. Heidän sisarensa oli Serah. Berian pojat olivat Heber ja Malkiel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Nämä olivat Silpan lapset, hänen, jonka Laaban antoi tyttärelleen Leealle. Hän oli synnyttänyt ne Jaakobille, kuusitoista henkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Raakelin, Jaakobin vaimon, pojat olivat Joosef ja Benjamin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Pojat, jotka syntyivät Joosefille Egyptin maassa, olivat Manasse ja Efraim. Nämä synnytti hänelle Aasenat, Oonin papin Poti-Feran tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Benjaminin pojat olivat Bela, Beker ja Asbel, Geera ja Naaman, Eehi ja Roos, Muppim ja Huppim sekä Ard.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Nämä olivat Raakelin pojat, jotka olivat syntyneet Jaakobille, kaikkiaan neljätoista henkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Daanin poika oli Husim.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Naftalin pojat olivat Jahseel, Guuni, Jeeser ja Sillem.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Nämä olivat Bilhan pojat, hänen, jonka Laaban antoi tyttärelleen Raakelille. Hän oli synnyttänyt ne Jaakobille, kaikkiaan seitsemän henkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Kaikkiaan niitä, jotka Jaakobin kanssa siirtyivät Egyptiin ja olivat lähteneet hänen kupeistaan, paitsi Jaakobin miniöitä, oli yhteensä kuusikymmentä kuusi henkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Joosefin poikia, jotka syntyivät hänelle Egyptissä, oli kaksi. Jaakobin perheen jäseniä, jotka siirtyivät Egyptiin, oli kaikkiaan seitsemänkymmentä henkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Hän lähetti Juudan edellään Joosefin luo ilmoittamaan hänelle tulostaan Gooseniin. He tulivat Goosenin maakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Joosef valjasti vaununsa ja meni isäänsä Israelia vastaan Gooseniin. Kun hän saapui hänen eteensä, hän lankesi hänen kaulaansa ja itki kauan hänen kaulassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Israel sanoi Joosefille: \"Nyt minä kuolen mielelläni, kun olen nähnyt kasvosi ja tiedän, että sinä vielä elät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Sen jälkeen Joosef sanoi veljilleen ja isänsä perheelle: \"Menen ilmoittamaan faraolle ja sanon hänelle: \'Veljeni ja isäni perhe, jotka ovat olleet Kanaanin maassa, ovat saapuneet luokseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Nämä miehet ovat paimenia, sillä he hoitavat karjaa. He ovat tuoneet mukanaan lampaansa, karjansa ja koko muun omaisuutensa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Kun siis farao kutsuu teidät eteensä ja kysyy: \'Mikä on ammattinne?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'vastatkaa: \'Me, palvelijasi, olemme hoitaneet karjaa nuoruudestamme tähän asti, me kuten isämmekin\' – että saisitte asettua Goosenin maakuntaan. Sillä kaikki paimenet ovat egyptiläisille kauhistus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Joosef meni ja ilmoitti faraolle, sanoen: \"Isäni ja veljeni ovat pikkukarjoineen ja nautoineen, kaikkine omaisuuksineen tulleet Kanaanin maasta, ja katso, he ovat Goosenin maakunnassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Hän oli ottanut mukaansa veljiensä joukosta viisi miestä. Hän toi heidät faraon eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Farao kysyi hänen veljiltään: \"Mikä on ammattinne?\" He vastasivat faraolle: \"Me, palvelijasi, olemme paimenia, me kuten isämmekin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'He sanoivat vielä faraolle: \"Olemme tulleet asuaksemme jonkin aikaa tässä maassa. Palvelijoillasi ei näet ollut laidunta karjalleen, koska kova nälänhätä on Kanaanin maassa. Suo siis palvelijaisi asettua Goosenin maakuntaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Farao sanoi Joosefille: \"Isäsi ja veljesi ovat tulleet luoksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Egyptin maa on avoinna edessäsi. Sijoita isäsi ja veljesi maan parhaaseen osaan. Asukoot Goosenin maakunnassa. Jos tiedät heidän joukossaan olevan kelvollisia miehiä, niin aseta heidät minun karjani päällysmiehiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Sen jälkeen Joosef toi isänsä Jaakobin sisään ja esitteli hänet faraolle. Jaakob toivotti faraolle siunausta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Farao kysyi Jaakobilta: \"Kuinka monta ikävuotta sinulla on?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jaakob vastasi faraolle: \"Vaellusaikani on kestänyt sata kolmekymmentä vuotta. Vähät ja pahat ovat olleet elinvuosieni päivät eivätkä ole saavuttaneet sitä elinvuosien määrää, mikä isilläni oli vaelluksensa aikana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Jaakob toivotti faraolle siunausta ja lähti hänen luotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Joosef sijoitti isänsä ja veljensä Egyptin maahan ja antoi heille maaomaisuutta maan parhaasta osasta, Ramseksen maakunnasta, kuten farao oli käskenyt hänen tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Joosef elätti isäänsä, veljiään ja koko isänsä perhettä antamalla jokaiselle elatusta vaimojen ja lasten luvun mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Mutta missään koko maassa ei ollut leipää. Nälänhätä oli näet hyvin kova, niin että Egyptin maa ja Kanaanin maa olivat nääntymässä nälkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Viljalla, jota ostettiin, Joosef kokosi kaiken rahan, mitä oli Egyptin maassa ja Kanaanin maassa, ja Joosef vei rahat faraon hoviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Kun raha oli loppunut Egyptin maasta ja Kanaanin maasta, kaikki egyptiläiset tulivat Joosefin luo sanoen: \"Anna meille leipää. Miksi kuolisimme silmiesi edessä? Sillä raha on loppunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Joosef vastasi: \"Tuokaa tänne karjanne. Annan teille leipää karjastanne, jos rahanne on loppunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'He toivat Joosefille karjansa, ja Joosef antoi heille leipää hevosista, lampaista, naudoista ja aaseista. Hän elätti heitä sen vuoden leivällä kaiken heidän karjansa hinnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Niin kului se vuosi. Seuraavana vuonna he tulivat taas hänen luokseen ja sanoivat hänelle: \"Emme tahdo salata herraltamme, että raha on lopussa, ja myös eläimemme ovat joutuneet herramme omiksi. Meillä ei ole muuta jäljellä annettavana herrallemme kuin ruumiimme ja peltomme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Miksi menehtyisimme silmiesi edessä, sekä me itse että peltomme? Osta meidät ja peltomme leivällä, niin me tulemme peltoinemme faraon palvelijoiksi. Anna meille siementä, että eläisimme emmekä kuolisi eivätkä peltomme joutuisi autioiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Niin Joosef osti faraolle kaikki Egyptin pellot, sillä egyptiläiset myivät jokainen vainionsa, koska nälkä ahdisti heitä. Maa joutui faraon omaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Hän siirsi kansan kaupunkeihin Egyptin toisesta äärestä toiseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Ainoastaan pappien peltoja hän ei ostanut. Sillä papeilla oli määrätyt tulot faraolta ja he elivät niistä määrätyistä tuloistaan, jotka he faraolta saivat. Sen tähden heidän ei tarvinnut myydä peltojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Joosef sanoi kansalle: \"Katso, olen nyt ostanut teidät ja peltonne faraolle. Katso, tässä on teille siementä, kylväkää peltonne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Mutta sadosta teidän on annettava viides osa faraolle. Neljä viidettä osaa jääköön teille sen sijaan pellon siemeneksi sekä ravinnoksi itsellenne ja niille, jotka talossanne ovat, sekä elatukseksi vaimoillenne ja lapsillenne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'He vastasivat: \"Sinä olet pitänyt meidät hengissä. Suo meidän vain saada armo herramme silmien edessä, niin olemme faraon palvelijoita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Niin Joosef teki sen säädökseksi, joka vielä tänäkin päivänä on voimassa Egyptin pelloista, että faraolle on annettava viides osa. Ainoastaan pappien pellot eivät joutuneet faraon omiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Niin Israel jäi asumaan Egyptiin Goosenin maakuntaan. He asettuivat sinne, olivat hedelmällisiä ja lisääntyivät suuresti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Jaakob eli Egyptin maassa seitsemäntoista vuotta, ja koko hänen elinaikansa oli sata neljäkymmentä seitsemän vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Kun lähestyi aika, jolloin Israelin oli kuoltava, hän kutsui poikansa Joosefin ja sanoi hänelle: \"Jos olen saanut armon silmiesi edessä, niin pane nyt kätesi kupeeni alle ja osoita minulle laupeus ja uskollisuus: älä hautaa minua Egyptiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Tahdon näet levätä isieni luona. Vie siis minut Egyptistä ja hautaa minut heidän hautaansa.\" Hän vastasi: \"Minä teen, kuten sanot.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Hän sanoi: \"Vanno se minulle\", ja hän vannoi sen hänelle. Silloin Israel rukoili kumartuneena vuoteensa päänalusta vasten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Näiden tapahtumien jälkeen tuotiin Joosefille sana: \"Katso, isäsi on sairaana.\" Hän otti mukaansa molemmat poikansa, Manassen ja Efraimin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Jaakobille ilmoitettiin ja sanottiin: \"Katso, poikasi Joosef on tullut luoksesi.\" Israel kokosi voimansa ja nousi istumaan vuoteellaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Jaakob sanoi Joosefille: \"Jumala, Kaikkivaltias, ilmestyi minulle Luusissa Kanaanin maassa ja siunasi minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'Hän sanoi minulle: \'Katso, teen sinut hedelmälliseksi ja annan sinun lisääntyä, annan sinusta tulla suuren kansojen joukon, ja annan jälkeläisillesi tämän maan ikiaikaiseksi perintömaaksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Kaksi poikaasi, jotka ovat sinulle syntyneet Egyptin maassa, ennen kuin tulin luoksesi Egyptiin, olkoot omiani. Efraim ja Manasse olkoot omiani niin kuin Ruuben ja Simeon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Mutta ne lapsesi, jotka ovat syntyneet sinulle heidän jälkeensä, olkoot sinun. Nimitettäköön heitä veljiensä nimellä heidän perintöosassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Palatessani Mesopotamiasta kuoli minulta Raakel matkalla Kanaanissa, kun vielä oli jonkin verran matkaa Efrataan. Hautasin hänet siellä Efratan\" – se on Beetlehemin – \"tien varteen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Kun nyt Israel huomasi Joosefin pojat, hän kysyi: \"Keitä nämä ovat?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Joosef vastasi isälleen: \"He ovat poikani, jotka Jumala on antanut minulle täällä.\" Hän sanoi: \"Tuo heidät luokseni siunatakseni heidät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Israelin silmät olivat vanhuudesta hämärät, niin ettei hän voinut nähdä. Niin Joosef toi heidät hänen luokseen, ja hän suuteli heitä ja syleili heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Israel sanoi Joosefille: \"En olisi uskonut saavani nähdä kasvojasi. Katso, Jumala on suonut minun nähdä jälkeläisiäsikin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Joosef otti heidät pois hänen polviltaan ja kumartui maahan kasvoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Sitten Joosef tarttui heihin molempiin, Efraimiin oikealla kädellään Israelin vasemmalla puolella ja Manasseen vasemmalla kädellään Israelin oikealla puolella, ja toi heidät niin hänen eteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Mutta Israel ojensi oikean kätensä ja laski sen Efraimin pään päälle, vaikka tämä oli nuorempi, ja vasemman kätensä Manassen pään päälle. Hän pani siis kätensä ristikkäin, sillä Manasse oli esikoinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Hän siunasi Joosefin sanoen: \"Jumala, jonka kasvojen edessä isäni Aabraham ja Iisak ovat vaeltaneet, Jumala, joka on ollut paimeneni syntymästäni hamaan tähän päivään asti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'Enkeli, joka on pelastanut minut kaikesta pahasta, siunatkoon näitä nuorukaisia. Heitä mainittaessa mainittakoon minun nimeni ja minun isieni Aabrahamin ja Iisakin nimi, ja he lisääntykööt suuresti keskellä maata.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Kun Joosef huomasi, että hänen isänsä laski oikean kätensä Efraimin pään päälle, hän pani sen pahakseen ja tarttui isänsä käteen siirtääkseen sen Efraimin pään päältä Manassen pään päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Joosef sanoi isälleen: \"Ei niin, isäni, sillä tämä on esikoinen. Pane oikea kätesi hänen päänsä päälle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Mutta hänen isänsä epäsi ja sanoi: \"Kyllä tiedän, poikani, kyllä tiedän. Hänestäkin on tuleva kansa, hänkin on tuleva suureksi, mutta hänen nuorempi veljensä on kuitenkin tuleva häntä suuremmaksi, ja hänen siemenestään on tuleva kansan paljous.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Hän siunasi heidät sinä päivänä, sanoen: \"Sinun nimelläsi siunataan Israelissa, kun sanotaan: Jumala tehköön sinut Efraimin ja Manassen kaltaiseksi.\" Hän asetti Efraimin Manassen edelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Israel sanoi Joosefille: \"Katso, minä kuolen, mutta Jumala on kanssanne ja vie teidät takaisin isienne maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Sen lisäksi, minkä veljesi saavat, minä annan sinulle Sikemin, jonka olen ottanut miekallani ja jousellani amorilaisilta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Jaakob kutsui poikansa luokseen ja sanoi: \"Kokoontukaa, ja minä ilmoitan teille, mitä teille päivien lopulla tapahtuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Tulkaa kokoon ja kuulkaa, Jaakobin pojat, kuulkaa isäänne Israelia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruuben, sinä olet esikoiseni, voimani ja miehuuteni ensimmäinen, ensi sijalla arvossa, ensi sijalla vallassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Mutta sinä kuohahdat kuin vesi, et pysy ensi sijalla, sillä sinä nousit isäsi leposijalle. Silloin sen saastutit. Hän nousi vuoteeseeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeon ja Leevi, veljekset, heidän aseensa ovat väkivallan aseet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Heidän neuvoonsa ei suostu sieluni, heidän seuraansa ei yhdy sydämeni. Sillä vihassaan he murhasivat miehiä, omavaltaisuudessaan he silpoivat härkiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Kirottu olkoon heidän vihansa, sillä se on raju, [kirottu] heidän kiukkunsa, sillä se on julma. Jaan heidät Jaakobin sekaan ja hajotan heidät Israelin sekaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juuda, sinua veljesi ylistävät. Kätesi on vihollistesi niskassa, sinua kumartavat isäsi pojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Juuda on nuori leijona. Saaliilta olet, poikani, noussut. Hän on asettunut makaamaan, hän lepää kuin leijona, kuin naarasleijona – kuka uskaltaa häntä häiritä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Ei siirry valtikka pois Juudalta eikä hallitsijansauva hänen polviensa välistä, kunnes tulee Šilo, jota kansat tottelevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Hän sitoo aasinsa viinipuuhun, viiniköynnökseen aasinsa varsan. Hän huuhtoo vaatteensa viinissä, viittansa rypäleen veressä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Hänen silmänsä ovat viinistä kirkkaat, hänen hampaansa valkeat maidosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Sebulon asuu meren rannalla, laivojen rannikolla, hänen alueensa reuna ulottuu Siidoniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Isaskar on luiseva aasi, joka loikoilee karjatarhojen välissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Hän huomasi lepopaikkansa suloiseksi ja maan ihanaksi. Hän taivutti olkansa taakan alla ja joutui työveroa tekemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Daan hankkii oikeutta kansalleen, hänkin yhtenä Israelin sukukunnista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Daan on käärmeenä tiellä, on polulla kyynä, joka puree hevosta vuohiseen, niin että ratsastaja syöksyy selin maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Sinulta minä odotan pelastusta, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gaadia ahdistavat rosvojoukot, mutta hän itse ahdistaa heitä heidän kintereillään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Asserista tulee lihavuus, hänen leipänsä. Hän tarjoaa kuninkaan herkkuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naftali on nopea peura. Hän antaa kauniita sanoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Joosef on nuori hedelmäpuu, nuori hedelmäpuu lähteen reunalla. Sen oksat ulottuvat yli muurin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Jousimiehet hätyyttävät häntä, ampuvat ja ahdistavat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Mutta hänen jousensa pysyy lujana, ja hänen käsivartensa ovat notkeat Jaakobin Väkevän avulla, paimenen, Israelin kallion,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'isäsi Jumalan, avulla, joka sinua auttakoon, Kaikkivaltiaan avulla, joka sinua siunatkoon, antakoon siunauksia taivaasta ylhäältä, siunauksia syvyydestä alhaalta, siunauksia rinnoista ja kohdusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Sinun isäsi siunaukset kohoavat yli minun vanhempieni siunausten, yli ikuisten kukkuloiden ihanuuden. Ne laskeutukoot Joosefin pään päälle, veljiensä ruhtinaan päälaelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin on raateleva susi. Aamulla hän syö riistaa ja illalla jakaa saalista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Nämä ovat kaikki Israelin sukukunnat, luvultaan kaksitoista, ja tämän puhui heille heidän isänsä siunatessaan heidät. Hän siunasi jokaisen erikseen erityisellä siunauksella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Hän käski heitä ja sanoi heille: \"Minut otetaan pois heimoni luo. Haudatkaa minut isieni viereen, siihen luolaan, joka on heettiläisen Efronin vainiolla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'luolaan, joka on Makpelan vainiolla, itään Mamresta Kanaanin maassa, jonka vainion Aabraham osti heettiläiseltä Efronilta perintöhaudakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Siihen on haudattu Aabraham ja hänen vaimonsa Saara, siihen on haudattu Iisak ja hänen vaimonsa Rebekka, ja siihen minäkin hautasin Leean,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'siihen vainioon, joka luolineen on ostettu heettiläisiltä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Kun Jaakob oli antanut määräyksensä pojilleen, hän veti jalkansa vuoteeseen, kuoli ja tuli otetuksi heimonsa luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Joosef vaipui isänsä kasvoja vasten, itki siinä kumartuneena hänen ylitseen ja suuteli häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Sitten Joosef käski lääkäreitä, jotka olivat hänen palveluksessaan, balsamoimaan hänen isänsä, ja lääkärit balsamoivat Israelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Siihen kului neljäkymmentä päivää, sillä niin pitkä aika kuluu balsamoimiseen. Egyptiläiset itkivät häntä seitsemänkymmentä päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Sitten kun hänen muistokseen vietetty suruaika oli päättynyt, Joosef puhui hoviväelle: \"Jos olen saanut armon silmienne edessä, puhukaa puolestani faraolle näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Isäni vannotti minua sanoen: \'Katso, minä kuolen, hautaa minut omaan hautaani, jonka olen kaivanut itselleni Kanaanin maassa.\' Anna minun siis nyt mennä hautaamaan isäni, sitten palaan takaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Farao vastasi: \"Mene hautaamaan isäsi sen valan mukaan, jonka olet hänelle vannonut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Niin Joosef meni hautaamaan isäänsä, ja hänen kanssaan menivät kaikki faraon palvelijat, hänen hovinsa vanhimmat ja kaikki Egyptin maan vanhimmat');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'sekä koko Joosefin perhe, hänen veljensä ja hänen isänsä perhe. Ainoastaan vaimonsa, lapsensa, lampaansa, vuohensa ja nautansa he jättivät Goosenin maakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Hänen mukanaan meni myös sekä vaunuja että ratsumiehiä. Heitä oli hyvin suuri joukko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Kun he saapuivat Gooren-Aatadiin, joka on Jordanin tuolla puolella, he panivat siellä toimeen hyvin suuret ja juhlalliset valittajaiset, ja hän vietti isänsä surujuhlaa seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Kun maan asukkaat, kanaanilaiset, näkivät surujuhlan Gooren-Aatadissa, he sanoivat: \"Siellä on egyptiläisillä suuri surujuhla.\" Siitä sai paikka nimekseen Aabel-Misraim. Se on Jordanin tuolla puolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Hänen poikansa tekivät hänelle, niin kuin hän oli heille määrännyt:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'hänen poikansa veivät hänet Kanaanin maahan ja hautasivat hänet Makpelan vainiolla olevaan luolaan, jonka vainion Aabraham oli ostanut perintöhaudaksi heettiläiseltä Efronilta ja joka oli Mamresta itään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Sen jälkeen kun Joosef oli haudannut isänsä, hän palasi Egyptiin, hän ja hänen veljensä sekä kaikki, jotka hänen kanssaan olivat menneet hautaamaan hänen isäänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Mutta Joosefin veljet pelkäsivät, kun heidän isänsä oli kuollut, ja ajattelivat: \"Ehkä Joosef nyt alkaa vainota meitä ja kostaa meille kaiken sen pahan, mitä olemme hänelle tehneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'He lähettivät Joosefille tämän sanan: \"Isäsi käski ennen kuolemaansa ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, '\'Sanokaa Joosefille näin: Oi, anna anteeksi veljiesi rikos ja synti, sillä pahasti he ovat menetelleet sinua kohtaan.\' Anna siis isäsi Jumalan palvelijoille anteeksi heidän rikoksensa.\" Joosef itki kuullessaan nämä heidän sanansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Sitten tulivat Joosefin veljet itse, lankesivat maahan hänen eteensä ja sanoivat: \"Katso, me olemme sinun orjiasi!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Mutta Joosef vastasi heille: \"Älkää pelätkö, olenko minä Jumalan sijassa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Tosin te pyritte saamaan aikaan pahaa minua vastaan, mutta Jumala on kääntänyt sen hyväksi, että hän saisi aikaan sen, mikä nyt on tapahtunut, ja pitäisi hengissä paljon kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Älkää siis pelätkö. Minä elätän teidät, vaimonne ja lapsenne.\" Hän lohdutti ja rauhoitti heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Joosef sekä hänen isänsä perhe jäivät asumaan Egyptiin. Joosef eli sata kymmenen vuotta vanhaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Joosef sai nähdä Efraimin lapsia kolmanteen polveen. Myös Maakirista, Ma-nassen pojasta, syntyi lapsia Joosefin polville.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Joosef sanoi veljilleen: \"Minä kuolen, mutta Jumala pitää huolen teistä ja johdattaa teidät tästä maasta siihen maahan, jonka hän valalla vannoen on luvannut Aabrahamille, Iisakille ja Jaakobille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Joosef vannotti Israelin poikia sanoen: \"Kun Jumala pitää huolen teistä, viekää silloin luuni täältä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Joosef kuoli sadan kymmenen vuoden ikäisenä. Hänet balsamoitiin ja pantiin arkkuun Egyptissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Nämä ovat Egyptiin tulleiden Israelin poikien nimet. Jaakobin kanssa he olivat itse kukin tulleet sinne perheineen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruuben, Simeon, Leevi ja Juuda,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Isaskar, Sebulon ja Benjamin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Daan, Naftali, Gaad ja Asser.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Jaakobin kupeista lähteneitä oli kaikkiaan seitsemänkymmentä henkeä. Joosef taas oli jo edeltä käsin Egyptissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Sitten Joosef kuoli ja kaikki hänen veljensä sekä koko se sukupolvi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Israelilaiset olivat hedelmällisiä ja sikisivät, lisääntyivät ja kasvoivat hyvin suurilukuisiksi. Maa tuli heitä täyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Sitten Egyptiin nousi uusi kuningas, joka ei tiennyt Joosefista mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Tämä sanoi kansalleen: \"Katso, israelilaisten kansa on meitä suurempi ja voimakkaampi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Tulkaa, menetelkäämme viisaasti heitä kohtaan, etteivät he lisääntyisi eivätkä – jos sota syttyisi – hekin liittyisi vihollisiimme ja sotisi meitä vastaan ja lähtisi maasta pois.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Heille asetettiin työnjohtajia rasittamaan heitä raskaalla työllä, ja heidän täytyi rakentaa faraolle varastokaupungit Piitom ja Ramses.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Mutta mitä enemmän kansaa rasitettiin, sitä enemmän se lisääntyi, ja sitä enemmän se levisi, niin että israelilaisia ruvettiin pelkäämään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Egyptiläiset pitivät israelilaisia väkisin orjatyössä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'ja katkeroittivat heidän elämänsä kovalla laasti- ja tiilityöllä ja kaikella työllä ulkona kedolla, kaikella työllä, jota he väkisin heillä teettivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Egyptin kuningas puhui heprealaisille kätilöille, joista toisen nimi oli Sifra ja toisen Puua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Hän sanoi: \"Kun autatte heprealaisia vaimoja heidän synnyttäessään, tarkastakaa lapsen sukupuoli. Jos se on poika, surmatkaa se, mutta jos se on tyttö, jääköön eloon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Mutta kätilöt pelkäsivät Jumalaa eivätkä tehneet, kuten Egyptin kuningas oli heille sanonut, vaan antoivat poikalasten elää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Egyptin kuningas kutsui kätilöt ja sanoi heille: \"Miksi te näin teette ja annatte poikalasten elää?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Kätilöt vastasivat faraolle: \"Heprealaiset vaimot eivät ole kuin egyptiläiset. He ovat voimakkaita. Ennen kuin kätilö tulee heidän luokseen, he ovat jo synnyttäneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Mutta Jumala salli kätilöiden menestyä. Kansa lisääntyi ja kasvoi suurilukuiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Koska kätilöt pelkäsivät Jumalaa, hän antoi heille jälkeläisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Farao antoi käskyn kaikelle kansalleen sanoen: \"Kaikki poikalapset, jotka syntyvät, heittäkää Niiliin, mutta kaikkien tyttölasten antakaa elää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Eräs mies, joka oli Leevin sukua, meni ja otti itselleen leeviläisen tyttären.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Vaimo tuli raskaaksi ja synnytti pojan. Kun hän näki, että se oli ihana lapsi, hän salasi sitä kolme kuukautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Mutta kun hän ei voinut sitä enää salata, hän otti kaisla-arkun, siveli sen maapihkalla ja piellä, pani lapsen siihen ja laski sen kaislikkoon Niilin rantaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Lapsen sisar asettui taaemmaksi nähdäkseen, mitä hänelle tapahtuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Faraon tytär tuli alas peseytymään virrassa, ja hänen seuranaisensa kävelivät virran rannalla. Kun hän näki arkun kaislikossa, hän lähetti palvelijattarensa ottamaan sen ylös.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Kun hän avasi sen, hän näki lapsen. Katso, siinä oli pieni poika, joka itki. Niin hänen tuli sitä sääli, ja hän sanoi: \"Tämä on heprealaisten lapsia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Niin lapsen sisar sanoi faraon tyttärelle: \"Menenkö kutsumaan sinulle heprealaisen imettäjän, joka voi imettää lapsen sinulle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Faraon tytär vastasi hänelle: \"Mene!\" Niin tyttö meni ja kutsui lapsen äidin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Faraon tytär sanoi hänelle: \"Ota tämä lapsi ja imetä se minulle, niin minä maksan sinulle siitä palkan.\" Vaimo otti lapsen ja imetti sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Kun lapsi oli kasvanut, hän toi sen faraon tyttärelle. Tämä otti hänet pojakseen ja antoi hänelle nimen Mooses, sillä hän sanoi: \"Minä olen vetänyt hänet ylös vedestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Tapahtui niihin aikoihin, kun Mooses oli kasvanut suureksi, että hän meni veljiensä luo ja näki heidän raskaan työnsä. Hän näki egyptiläisen miehen lyövän heprealaista miestä, erästä hänen veljistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Hän katseli ympärilleen joka taholle. Kun hän näki, ettei ketään ollut lähellä, hän löi egyptiläisen kuoliaaksi ja kätki hänet hiekkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Hän meni seuraavana päivänä ulos ja näki kaksi heprealaista miestä tappelemassa keskenään. Niin hän sanoi syylliselle: \"Miksi lyöt toveriasi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Tämä vastasi: \"Kuka on asettanut sinut päämieheksemme ja tuomariksemme? Aiotko tappaa minutkin, kuten tapoit egyptiläisen?\" Silloin Mooses pelästyi ja ajatteli: \"Se on todella tullut ilmi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Kun farao sai kuulla tästä tapahtumasta, hän etsi Moosesta tappaakseen hänet. Mutta Mooses lähti faraota pakoon ja pysähtyi Midianin maahan ja istahti eräälle kaivolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Midianin papilla oli seitsemän tytärtä. Nämä tulivat vettä ammentamaan ja täyttivät vesikaukalot juottaakseen isänsä lampaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Mutta paimenet tulivat ja ajoivat heidät pois. Mooses nousi, auttoi heitä ja juotti heidän lampaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Kun he tulivat isänsä Reguelin luo, hän kysyi: \"Kuinka te tänä päivänä niin pian tulitte?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'He vastasivat: \"Egyptiläinen mies auttoi meitä paimenten käsistä, ammensi vielä meille vettäkin ja juotti lampaat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Hän sanoi tyttärilleen: \"Missä hän on? Miksi te niin jätitte miehen? Kutsukaa hänet aterioimaan kanssamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Mooses suostui asumaan miehen luona. Hän antoi Moosekselle tyttärensä Sipporan vaimoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Tämä synnytti pojan, ja Mooses antoi hänelle nimen Geersom, sillä hän sanoi: \"Muukalainen minä olen ollut vieraalla maalla.\" [Hän synnytti vielä toisenkin pojan. Mooses antoi hänelle nimeksi Elieser, ja sanoi: \"Isäni Jumala on apuni ja on pelastanut minut faraon kädestä.\"]');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Kun oli kulunut pitkä aika, Egyptin kuningas kuoli. Israelilaiset huokailivat orjuuttaan ja valittivat. Heidän huutonsa heidän orjuutensa tähden nousi Jumalan luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Jumala kuuli heidän vaikeroimisensa, ja Jumala muisti liittonsa Aabrahamin, Iisakin ja Jaakobin kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Jumala katsoi israelilaisten puoleen. Jumala piti omistaan huolen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Mooses kaitsi appensa Jetron, Midianin papin, lampaita. Kun hän kerran ajoi lampaita erämaan tuolle puolen, hän tuli Jumalan vuoren, Hoorebin, juurelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Silloin Herran Enkeli ilmestyi hänelle tulen liekissä keskellä orjantappurapensasta. Katso, hän näki pensaan palavan tulessa, mutta pensas ei kuitenkaan kulunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Mooses sanoi: \"Minä käyn tuonne ja katson tätä suurta näkyä, miksi pensas ei pala poroksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Kun Herra näki hänen tulevan katsomaan, hän, Jumala, huusi hänelle pensaasta ja sanoi: \"Mooses, Mooses!\" Hän vastasi: \"Tässä olen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Hän sanoi: \"Älä tule tänne! Riisu kengät jalastasi, sillä paikka, missä seisot, on pyhää maata.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Hän sanoi: \"Minä olen isäsi Jumala, Aabrahamin Jumala, Iisakin Jumala ja Jaakobin Jumala.\" Mooses peitti kasvonsa, sillä hän pelkäsi katsoa Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Herra sanoi: \"Olen totisesti nähnyt kansani kurjuuden Egyptissä ja kuullut heidän huutonsa heidän sortajiensa tähden, sillä tiedän heidän kärsimyksensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Olen astunut alas vapauttamaan heidät egyptiläisten kädestä ja johdattamaan heidät siitä maasta hyvään ja tilavaan maahan, maahan, joka vuotaa maitoa ja mettä, sinne, missä kanaanilaiset, heettiläiset, amorilaiset, perissiläiset, hivviläiset ja jebusilaiset asuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Katso, nyt on israelilaisten huuto tullut kuuluviini, ja olen myös nähnyt sen sorron, jolla egyptiläiset heitä sortavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Mene nyt, lähetän sinut faraon luo, ja vie kansani, israelilaiset, pois Egyptistä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Mutta Mooses sanoi Jumalalle: \"Mikä minä olen menemään faraon luo ja viemään israelilaiset pois Egyptistä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Hän vastasi: \"Olen kanssasi. Tämä olkoon sinulle merkkinä siitä, että minä olen sinut lähettänyt: kun olet vienyt kansan pois Egyptistä, niin te palvelette Jumalaa tällä vuorella.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Mooses sanoi Jumalalle: \"Katso, kun minä menen israelilaisten luo ja sanon heille: \'Teidän isienne Jumala on lähettänyt minut teidän luoksenne\', ja kun he kysyvät minulta: \'Mikä hänen nimensä on?\' mitä sanon heille?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Jumala sanoi Moosekselle: \"Olen se, joka olen.\" Hän sanoi vielä: \"Sano israelilaisille näin: \' Minä olen \' lähetti minut teidän luoksenne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Jumala sanoi vielä Moosekselle: \"Sano israelilaisille näin: Herra, isienne Jumala, Aabrahamin Jumala, Iisakin Jumala ja Jaakobin Jumala, lähetti minut luoksenne. Tämä on minun nimeni iankaikkisesti, ja näin minua kutsuttakoon sukupolvesta sukupolveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Mene ja kokoa Israelin vanhimmat ja sano heille: Herra, teidän isienne Jumala, Aabrahamin, Iisakin ja Jaakobin Jumala, on ilmestynyt minulle ja sanonut: \'Totisesti minä pidän teistä huolen ja pidän silmällä, mitä teille tapahtuu Egyptissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Hän sanoi: minä johdatan teidät pois Egyptin kurjuudesta kanaanilaisten, heettiläisten, amorilaisten, perissiläisten, hivviläisten ja jebusilaisten maahan, siihen maahan, joka vuotaa maitoa ja hunajaa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'He kuulevat sinua. Mene sitten, sinä ja Israelin vanhimmat, Egyptin kuninkaan luo, ja sanokaa hänelle: \' Herra, heprealaisten Jumala, on kohdannut meidät. Anna siis meidän mennä kolmen päivän matka erämaahan uhraamaan Herralle, Jumalallemme.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Mutta minä tiedän, että Egyptin kuningas ei päästä teitä menemään, ei edes väkevän käden pakolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Kun ojennan käteni ja lyön Egyptiä kaikilla ihmeilläni, joita teen heidän keskuudessaan, hän päästää teidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Annan tämän kansan päästä egyptiläisten suosioon, niin että te lähtiessänne ette lähde tyhjin käsin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'vaan jokainen nainen pyytää naapuriltaan ja luonaan majailevalta naiselta hopea- ja kultaesineitä ja vaatteita. Niihin puette poikanne ja tyttärenne ja viette ne saaliina egyptiläisiltä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Mooses vastasi ja sanoi: \"Katso, he eivät usko minua eivätkä kuule minua, vaan sanovat: \' Herra ei ole sinulle ilmestynyt.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Herra sanoi hänelle: \"Mikä sinulla on kädessäsi?\" Hän vastasi: \"Sauva.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Hän sanoi: \"Heitä se maahan.\" Hän heitti sen maahan. Se muuttui käärmeeksi, ja Mooses pakeni sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Mutta Herra sanoi Moosekselle: \"Ojenna kätesi ja tartu sen pyrstöön.\" Hän ojensi kätensä ja tarttui siihen, ja se muuttui sauvaksi hänen kädessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, '\"Siitä he uskovat, että Herra, heidän isiensä Jumala, Aabrahamin Jumala, Iisakin Jumala ja Jaakobin Jumala, on sinulle ilmestynyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Herra sanoi vielä hänelle: \"Pistä kätesi poveesi.\" Hän pisti kätensä poveensa. Kun hän veti sen ulos, niin, katso, hänen kätensä oli spitaalista valkoinen kuin lumi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Sitten hän sanoi: \"Pistä kätesi takaisin poveesi.\" Hän pisti kätensä takaisin poveensa. Kun hän veti sen ulos povestaan, katso, se oli taas niin kuin hänen muukin ihonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Herra sanoi: \"Jos he eivät usko sinua eivätkä tottele ensimmäistä tunnustekoa, he uskovat toisen tunnusteon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Mutta jos he eivät usko näitäkään kahta tunnustekoa eivätkä kuule sinua, niin ota vettä Niilistä ja kaada kuivalle maalle, niin vesi, jonka virrasta otat, muuttuu vereksi kuivalla maalla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Mooses sanoi Herralle: \"Oi Herra, minä en ole puhetaitoinen mies. En ole ollut ennen enkä senkään jälkeen, kuin sinä puhuit palvelijallesi. Sillä minulla on hidas puhe ja kankea kieli.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Herra sanoi hänelle: \"Kuka on antanut ihmiselle suun, tai kuka tekee mykän tai kuuron, näkevän tai sokean? Enkö minä, Herra?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Mene siis nyt, minä olen suusi apuna ja opetan sinulle, mitä sinun on puhuttava.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Mutta hän sanoi: \"Oi Herra, lähetä kuka muu tahansa!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Herra vihastui Moosekseen ja sanoi: \"Eikö sinulla ole veljesi Aaron, leeviläinen? Tiedän, että hän osaa puhua. Katso, hän tuleekin sinua vastaan. Kun hän näkee sinut, hän iloitsee sydämestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Puhu hänelle ja pane sanat hänen suuhunsa. Minä olen sinun suusi apuna ja hänen suunsa apuna ja opetan teille, mitä teidän on tehtävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Hän on puhuva puolestasi kansalle. Hän on oleva sinulla suuna, ja sinä olet oleva hänellä jumalana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Ota käteesi tämä sauva, jolla teet tunnusteot.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Niin Mooses tuli takaisin appensa Jetron luo ja sanoi hänelle: \"Anna minun mennä takaisin veljieni luo Egyptiin katsomaan, ovatko he vielä elossa.\" Jetro sanoi Moosekselle: \"Mene rauhassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Herra sanoi Moosekselle Midianissa: \"Mene takaisin Egyptiin, sillä kaikki ne, jotka väijyivät henkeäsi, ovat kuolleet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Mooses otti vaimonsa ja poikansa ja pani heidät aasin selkään ja palasi Egyptin maahan. Mooses otti käteensä Jumalan sauvan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Herra sanoi Moosekselle: \"Kun tulet takaisin Egyptiin, katso, että teet faraon edessä kaikki ne ihmeet, jotka minä olen pannut käteesi. Mutta minä paadutan hänen sydämensä, niin ettei hän päästä kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Sano faraolle: \'Näin sanoo Herra: Israel on minun esikoispoikani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Sanon sinulle: Päästä minun poikani palvelemaan minua. Mutta jos kieltäydyt päästämästä häntä, katso, minä tapan esikoispoikasi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Matkalla yöpaikassa tapahtui, että Herra kohtasi hänet ja yritti surmata hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Sippora otti terävän kiven ja leikkasi pois poikansa esinahan, kosketti sillä Mooseksen jalkoja ja sanoi: \"Sinä olet minun veriylkäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Herra jätti hänet rauhaan. Sippora sanoi: \"Veriylkä ympärileikkauksen kautta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Herra sanoi Aaronille: \"Mene Moosesta vastaan erämaahan.\" Hän meni ja kohtasi hänet Jumalan vuorella ja suuteli häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Mooses kertoi Aaronille kaikki, mitä Herra oli puhunut lähettäessään hänet, ja kaikki ne tunnusteot, jotka hän oli käskenyt hänen tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Mooses ja Aaron menivät ja kokosivat kaikki israelilaisten vanhimmat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Aaron puhui kaikki, mitä Herra oli Moosekselle sanonut, ja Mooses teki tunnusteot kansan silmien edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'ja kansa uskoi. Kun he kuulivat, että Herra oli pitänyt huolta israelilaisista ja nähnyt heidän kurjuutensa, he kumartuivat maahan ja rukoilivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Sen jälkeen Mooses ja Aaron menivät sanomaan faraolle: \"Näin sanoo Herra, Israelin Jumala: Päästä kansani viettämään minulle juhlaa erämaassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Mutta farao sanoi: \"Kuka on Herra, jota minun pitäisi kuulla ja päästää Israel? En tunne Herraa enkä päästä Israelia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'He sanoivat: \"Heprealaisten Jumala on tavannut meidät. Anna siis meidän mennä kolmen päivän matka erämaahan uhraamaan Herralle, Jumalallemme, ettei hän rankaisisi meitä rutolla tai miekalla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Mutta Egyptin kuningas sanoi heille: \"Miksi te, Mooses ja Aaron, pidätätte kansaa heidän työstään? Menkää pakkotöihinne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Farao sanoi vielä: \"Katsokaa, liian paljon on muutenkin joutoväkeä maassa, ja tahdotte saattaa heidät vapaiksi pakkotyöstä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Farao antoi sinä päivänä käskyn kansan työnvalvojille ja työnjohtajille, sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, '\"Älkää enää antako kansalle olkia tiilien tekoa varten kuten ennen. Menkööt itse ja kootkoot itselleen oljet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Pankaa kuitenkin heidän tehtäväkseen sama tiilimäärä, jonka he ovat ennenkin tehneet, siitä mitään vähentämättä. Koska he ovat laiskoja, he huutavat: \'Menkäämme uhraamaan Jumalallemme!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Pantakoon miehille raskasta työtä, että heillä olisi siinä tekemistä ja etteivät he kuuntelisi valheellisia puheita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Kansan työnvalvojat ja työnjohtajat menivät ja sanoivat kansalle: \"Näin sanoo farao: \'Enää en anna teille olkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Menkää itse ja hankkikaa itsellenne olkia, mistä löydätte, mutta teidän työstänne ei vähennetä mitään.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Kansa hajaantui pitkin Egyptin maata keräämään pahnoja olkien sijasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Työnvalvojat ahdistivat heitä sanoen: \"Tehkää työnne valmiiksi, kunkin päivän määrä päivälleen, niin kuin silloinkin, kun saitte olkia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Israelilaisten työnjohtajia, joita faraon työnvalvojat olivat heille asettaneet, piestiin, ja heille sanottiin: \"Miksi ette ole eilen ettekä tänään suorittaneet tähänastista määräänne tiilien teossa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Israelilaisten työnjohtajat tulivat ja valittivat faraolle, sanoen: \"Miksi teet näin palvelijoillesi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Olkia palvelijoillesi ei anneta, mutta kuitenkin sanotaan meille: \'Tehkää tiilet.\' Katso, palvelijoitasi ruoskitaan, vaikka vika on oman väkesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Mutta hän sanoi: \"Laiskoja te olette, laiskoja. Sen tähden te sanotte: \'Menkäämme uhraamaan Herralle.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Menkää nyt työhönne. Olkia ei teille anneta, mutta sama määrä tiiliä on teidän toimitettava.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Israelilaisten työnjohtajat huomasivat olevansa pahassa tilanteessa, kun heille sanottiin: \"Ette saa mitään tiililuvun vähennystä kunkin päivän määrästä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Kun he lähtivät faraon luota, he tapasivat Mooseksen ja Aaronin, jotka odottivat heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'He sanoivat näille: \" Herra kostakoon teille ja tuomitkoon teidät. Sillä olette saattaneet meidät faraon ja hänen palvelijoidensa vihoihin ja antaneet heidän käteensä miekan, meille surmaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Mooses palasi Herran luo ja sanoi: \"Herra, miksi olet tehnyt niin pahoin tälle kansalle? Miksi lähetit minut?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Sillä siitä asti, kun menin faraon luo puhumaan nimessäsi, hän on tehnyt pahaa tälle kansalle, etkä todellakaan ole kansaasi vapauttanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Mutta Herra vastasi Moosekselle: \"Nyt näet, mitä teen faraolle. Väkevän käden pakottamana hän päästää heidät, ja väkevän käden pakottamana hän ajaa heidät maastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Jumala puhui Moosekselle ja sanoi hänelle: \"Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Minä olen ilmestynyt Aabrahamille, Iisakille ja Jaakobille \'Jumalana Kaikkivaltiaana\', mutta nimelläni \' Herra \' minä en ole tehnyt itseäni heille tunnetuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Tein myös liittoni heidän kanssaan antaakseni heille Kanaanin maan, sen maan, jossa he muukalaisina asuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Nyt minä olen kuullut israelilaisten vaikeroimisen, kun egyptiläiset pitävät heitä orjantyössä, ja olen muistanut liittoni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Sano sen tähden israelilaisille: \'Minä olen Herra, ja vien teidät pois egyptiläisten sorron alta ja vapautan teidät orjuudesta ja pelastan teidät ojennetulla käsivarrella ja suurilla rangaistustuomioilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Otan teidät kansakseni ja olen teidän Jumalanne. Tulette tietämään, että minä olen Herra, teidän Jumalanne, joka vien teidät pois egyptiläisten sorron alta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Johdatan teidät siihen maahan, jonka olen kättä kohottaen luvannut antaa Aabrahamille, Iisakille ja Jaakobille. Annan sen teille omaksi. Minä olen Herra.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Mooses puhui näin israelilaisille. Mutta he eivät kuulleet Moosesta tuskaantumisensa ja raskaan orjuutensa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Herra puhui Moosekselle ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, '\"Mene ja sano faraolle, Egyptin kuninkaalle, että hän päästää israelilaiset maastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Mutta Mooses puhui Herran edessä ja sanoi: \"Katso, israelilaiset eivät kuulleet minua. Kuinka sitten farao kuulisi minua, joka olen huuliltani ympärileikkaamaton?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Mutta Herra puhui Moosekselle ja Aaronille ja käski heidän mennä israelilaisten ja faraon, Egyptin kuninkaan, luo ja viedä israelilaiset pois Egyptin maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Nämä ovat heidän perhekuntiensa päämiehet: Ruubenin, Israelin esikoisen, pojat olivat Hanok ja Pallu, Hesron ja Karmi. Nämä ovat Ruubenin sukukunnat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Simeonin pojat olivat Jemuel, Jaamin, Oohad, Jaakin, Soohar ja Saul, kanaanilaisen naisen poika. Nämä ovat Simeonin sukukunnat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Nämä ovat Leevin poikien nimet heidän polveutumisensa mukaan: Geerson, Kehat ja Merari. Leevin elinaika oli sata kolmekymmentä seitsemän vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Geersonin pojat olivat Libni ja Siimei, sukujensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Kehatin pojat olivat Amram, Jishar, Hebron ja Ussiel. Kehatin elinaika oli sata kolmekymmentä kolme vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Merarin pojat olivat Mahli ja Muusi. Nämä ovat Leevin suvut polveutumisensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Amram otti isänsä sisaren Jookebedin vaimokseen, ja tämä synnytti hänelle Aaronin ja Mooseksen. Amramin elinaika oli sata kolmekymmentä seitsemän vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Jisharin pojat olivat Koorah, Nefeg ja Sikri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Ussielin pojat olivat Miisael, Elsafan ja Sitri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Aaron otti vaimokseen Eliseban, Amminadabin tyttären, Nahsonin sisaren, ja tämä synnytti hänelle Naadabin, Abihun, Eleasarin ja Iitamarin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Koorahin pojat olivat Assir, Elkana ja Abiasaf. Nämä ovat koorahilaisten suvut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Eleasar, Aaronin poika, otti itselleen vaimon Puutielin tyttäristä, ja tämä synnytti hänelle Piinehaan. Nämä ovat leeviläisten perhekuntien päämiehet heidän sukujensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Nämä olivat Aaron ja Mooses, joille Herra sanoi: \"Viekää israelilaiset joukkoineen pois Egyptin maasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Nämä, nimittäin Mooses ja Aaron, puhuivat faraolle, Egyptin kuninkaalle, että he vievät israelilaiset pois Egyptistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Sinä päivänä, kun Herra puhui Moosekselle Egyptin maassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Herra puhui Moosekselle näin: \"Minä olen Herra. Sano faraolle, Egyptin kuninkaalle, kaikki, mitä minä sinulle puhun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Mutta Mooses vastasi Herran edessä: \"Katso, minä olen huuliltani ympärileikkaamaton, kuinka farao kuulisi minua?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Mutta Herra sanoi Moosekselle: \"Katso, minä asetan sinut jumalaksi faraolle, ja veljesi Aaron on oleva profeettasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Puhu kaikki, mitä minä käsken sinun puhua, ja Aaron, veljesi, puhukoon faraolle, että hän päästäisi israelilaiset maastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Mutta minä paadutan faraon sydämen ja teen monta tunnustekoa ja ihmettä Egyptin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Farao ei kuule teitä, mutta asetan käteni Egyptiä vastaan ja vien pois joukkoni, kansani, israelilaiset, Egyptin maasta suurilla rangaistustuomioilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Egyptiläiset tulevat tietämään, että minä olen Herra, kun ojennan käteni Egyptiin ja vien pois israelilaiset heidän keskeltään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Mooses ja Aaron tekivät, kuten Herra oli heitä käskenyt. Niin he tekivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Mooses oli kahdeksankymmenen vuoden vanha ja Aaron kahdeksankymmentä kolme vuotta vanha, kun he puhuivat faraon kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Herra puhui Moosekselle ja Aaronille ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, '\"Kun farao puhuu teille ja sanoo: \'Tehkää jokin ihmeteko\', sano sinä Aaronille: \'Ota sauvasi ja heitä se faraon eteen, niin se muuttuu käärmeeksi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Mooses ja Aaron menivät faraon luo ja tekivät, kuten Herra oli käskenyt. Aaron heitti sauvansa faraon ja hänen palvelijoidensa eteen, ja se muuttui käärmeeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Faraokin kutsui maansa viisaat ja velhot. Nämä Egyptin tietäjät tekivät samoin taioillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'He heittivät kukin sauvansa maahan, ja ne muuttuivat käärmeiksi. Mutta Aaronin sauva nieli heidän sauvansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Faraon sydän paatui, eikä hän kuullut heitä, kuten Herra oli sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Herra sanoi Moosekselle: \"Faraon sydän on kovettunut. Hän kieltäytyy päästämästä kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Mene faraon luo huomenaamulla, kun hän menee veden ääreen, ja seisahdu hänen tielleen Niilin reunalle. Ota käteesi sauva, joka oli muuttunut käärmeeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Sano hänelle: \' Herra, heprealaisten Jumala, on lähettänyt minut luoksesi ja käskenyt sanoa: Päästä kansani palvelemaan minua erämaassa. Mutta katso, sinä et ole totellut tähän mennessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Sen tähden Herra sanoo näin: Tästä olet tunteva, että minä olen Herra: katso, minä lyön sauvalla, joka on kädessäni, virran veteen, ja se muuttuu vereksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Kalat virrassa kuolevat, ja virta rupeaa haisemaan, niin että egyptiläisiä inhottaa juoda vettä virrasta.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Herra sanoi Moosekselle: \"Sano Aaronille: \'Ota sauvasi ja ojenna kätesi Egyptin vetten yli, sen jokien, kanavien ja lammikkojen yli ja kaikkien niiden paikkojen yli, joihin on vettä kokoontunut, niin ne muuttuvat vereksi. Verta on oleva Egyptin maassa kaikkialla, sekä puuastioissa että kiviastioissa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Mooses ja Aaron tekivät, kuten Herra oli käskenyt. Hän kohotti sauvan ja löi Niilin veteen faraon ja hänen palvelijoidensa nähden. Kaikki vesi, joka virrassa oli, muuttui vereksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Kalat virrassa kuolivat, ja virta haisi, niin että egyptiläiset eivät voineet juoda vettä virrasta. Verta oli kaikkialla Egyptin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Mutta Egyptin tietäjät tekivät samoin taioillaan. Faraon sydän paatui, eikä hän kuullut heitä, kuten Herra oli sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Farao kääntyi ja palasi kotiinsa eikä välittänyt tästäkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Kaikki egyptiläiset kaivoivat Niilin ympäriltä vettä juodakseen. Sillä he eivät voineet juoda virran vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Oli kulunut seitsemän päivää siitä, kun Herra oli lyönyt Niiliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 26, '');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 27, '');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 28, '');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 29, '');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Herra sanoi Moosekselle: \"Käske Aaronin ojentaa kädessään oleva sauva jokien, Niilin ja lammikoiden yli ja saata sammakot esiin Egyptin maassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Aaron ojensi sauvansa kohti Egyptin vesiä, ja sammakot nousivat maalle ja peittivät Egyptin maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Tietäjät tekivät samoin taioillaan ja nostattivat sammakoita Egyptin maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Farao kutsui luokseen Mooseksen ja Aaronin ja sanoi: \"Rukoilkaa Herraa, että hän ottaisi sammakot pois minun ja kansani kimpusta, niin lähetän kansanne uhraamaan Herralle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Mooses sanoi faraolle: \"Ilmoita minulle, milloin rukoilen puolestasi sekä palvelijoidesi ja kansasi puolesta, niin että sammakot häviävät sinun ja tämän maan talojen päältä ja että niitä jää ainoastaan Niiliin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Farao vastasi: \"Huomiseen mennessä.\" Mooses sanoi: \"Olkoon, kuten sanot, jotta näkisit, ettei ole ketään Herran, Jumalamme, vertaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Sammakot lähtevät kimpustasi, palatsistasi sekä palvelijoittesi ja kansasi kimpusta ja niitä jää vain Niiliin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Mooses ja Aaron lähtivät faraon luota, ja Mooses rukoili Herraa ottamaan pois sammakot faraon kimpusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Herra teki niin kuin Mooses oli puhunut, ja sammakot kuolivat taloista, pihoilta ja pelloilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Vaikka niitä kerättiin pois kasoittain, silti löyhkä täytti maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Mutta kun farao näki, että vitsaus oli ohi, hän paadutti sydämensä eikä kuunnellut heitä, kuten Herra oli sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Herra sanoi Moosekselle: \"Käske Aaronia ojentamaan sauvansa ja lyömään maan tomua, niin sääsket valtaavat koko Egyptin maan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'He tekivät niin. Aaron ojensi kätensä ja löi sauvallaan maan tomua, ja kaikesta maan tomusta tuli sääskiä sekä ihmisiin että karjaan koko Egyptin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Tietäjätkin koettivat taioillaan saada aikaan sääskiä ihmisten ja karjan kimppuun, mutta eivät voineet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Tietäjät sanoivat faraolle: \"Se on Jumalan sormi\", mutta farao paadutti sydämensä eikä kuunnellut heitä, kuten Herra oli sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Herra sanoi Moosekselle: \"Nouse huomenna aamulla varhain ja asetu faraota vastaan, kun hän menee veden ääreen, ja sano hänelle: \'Näin sanoo Herra: Lähetä kansani palvelemaan minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Sillä jos et lähetä kansaani, niin, katso, minä lähetän paarmoja sinun, palvelijoittesi ja kansasi kimppuun ja taloihisi, niin että ne täyttävät Egyptin talot, vieläpä sen maankin, jonka päällä ne ovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Mutta erotan sinä päivänä Goosenin maan, jossa minun kansani asuu, ettei sinne tule paarmoja, tietääksesi, että minä olen Herra tässä maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Asetan pelastuksen oman kansani ja sinun kansasi välille. Huomenna tämä merkki tapahtuu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Herra teki niin, ja paarmat täyttivät faraon talon, hänen palvelijoidensa talon ja koko Egyptin maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Farao kutsui Mooseksen ja Aaronin luokseen ja sanoi: \"Menkää uhraamaan Jumalallenne tässä maassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Mutta Mooses sanoi: \"Niin ei ole lupa tehdä, sillä egyptiläisille on kauhistus uhrata Herralle Jumalallemme. Katso, jos uhraamme egyptiläisten nähden sellaista, mikä on heille kauhistus, eivätkö he kivitä meitä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Menemme kolmen päivämatkan päähän erämaahan uhraamaan Herralle, kuten hän on meille sanonut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Farao sanoi: \"Minä lähetän teidät uhraamaan Herralle Jumalallenne erämaassa. Älkää vain menkö kovin kauaksi. Rukoilkaa puolestani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Mooses sanoi: \"Minä lähden luotasi rukoilemaan Herraa, ja paarmat lähtevät faraon, hänen palvelijoidensa ja hänen kansansa kimpusta huomenna. Älköön vain farao enää pettäkö, niin ettei hän lähetäkään kansaa uhraamaan Herralle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Mooses lähti faraon luota ja rukoili Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Herra teki niin, kuin hän oli sanonut Moosekselle ja poisti paarmat faraon, hänen palvelijoidensa ja hänen kansansa kimpusta niin, ettei niitä jäänyt ainoatakaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Mutta farao paadutti sydämensä tässäkin tapauksessa eikä lähettänyt kansaa menemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Herra sanoi Moosekselle: \"Mene faraon luo ja puhu hänelle: \'Näin sanoo Herra, heprealaisten Jumala: Päästä kansani palvelemaan minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Sillä jos kieltäydyt päästämästä heitä ja vielä pidätät heitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'niin, katso, Herran käsi on lyövä karjaasi, joka on kedolla, hevosia, aaseja, kameleita, nautoja ja lampaita hyvin ankaralla ruttotaudilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Mutta Herra on tekevä erotuksen israelilaisten karjan ja egyptiläisten karjan välillä, niin ettei mitään kuole siitä, mikä on israelilaisten omaa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Herra asetti määräajan ja sanoi: \"Huomenna Herra on tekevä niin tässä maassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Seuraavana päivänä Herra teki niin, ja kaikki Egyptin karja kuoli, mutta israelilaisten karjasta ei kuollut ainoakaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Kun farao lähetti tiedustelemaan, niin, katso, israelilaisten karjasta ei ollut kuollut ainoakaan. Mutta faraon sydän paatui, eikä hän päästänyt kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Herra sanoi Moosekselle ja Aaronille: \"Ottakaa kouranne täyteen pätsin nokea, ja Mooses viskatkoon sen taivasta kohti faraon silmien edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Se tulee tomuksi, joka peittää koko Egyptin maan, ja siitä tulee ihmisiin ja karjaan märkäpaiseita kaikkialla Egyptin maassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'He ottivat pätsin nokea ja astuivat faraon eteen. Mooses viskasi sen taivasta kohti, ja märkäpaiseita tuli ihmisiin ja karjaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Eivätkä tietäjätkään voineet pitää puoliaan Moosesta vastaan paiseiden tähden, sillä paiseita oli loihtijoissa samoin kuin kaikissa muissakin egyptiläisissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Mutta Herra paadutti faraon sydämen, niin ettei hän kuullut heitä, kuten Herra oli sanonut Moosekselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Herra sanoi Moosekselle: \"Astu huomenaamulla varhain faraon eteen ja sano hänelle: \'Näin sanoo Herra, heprealaisten Jumala: Päästä kansani palvelemaan minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Muuten tällä kertaa minä lähetän kaikki vitsaukseni vaivaamaan sinua itseäsi sekä sinun palvelijoitasi ja kansaasi tietääksesi, ettei ole ketään vertaistani koko maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Sillä olisin jo ojentanut käteni ja lyönyt sinua ja kansaasi ruttotaudilla, niin että olisit kokonaan hävinnyt maan päältä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'mutta juuri sitä varten minä olen antanut sinun nousta, että näyttäisin sinussa voimani ja että minun nimeäni julistettaisiin kaiken maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Jos sinä vielä estät kansaani etkä päästä heitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'niin, katso, huomenna tähän aikaan minä annan tulla hyvin ankaran raesateen, jonka kaltaista ei ole ollut Egyptissä siitä päivästä saakka, jona sen perustus laskettiin, aina tähän asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Lähetä nyt saattamaan suojaan karjasi ja kaikki, mitä sinulla on kedolla. Sillä kaikki ihmiset ja karja, jotka ovat kedolla ja joita ei ole korjattu kotiin, joutuvat raesateen alle ja kuolevat.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Se faraon palvelijoista, joka pelkäsi Herran sanaa, toimitti silloin palvelijansa ja karjansa talojen suojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Se taas, joka ei välittänyt Herran sanasta, jätti palvelijansa ja karjansa ulos kedolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Herra sanoi Moosekselle: \"Ojenna kätesi taivasta kohti, niin raesade kohtaa koko Egyptin maata, ihmisiä, karjaa ja kaikkia kedon kasveja Egyptin maassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Mooses ojensi sauvansa taivasta kohti, ja Herra antoi jyristä ja lähetti rakeita, ja tulta iski maahan. Näin Herra antoi sataa rakeita yli Egyptin maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Rakeita tuli, ja tulta leimahteli rakeiden keskellä. Raesade oli hyvin ankara, niin ettei sellainen ollut kohdannut koko Egyptin maata siitä ajasta saakka, jolloin se asutettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Rakeet löivät maahan kaikkialla Egyptin maassa kaiken, mitä kedolla oli, sekä ihmiset että karjan. Rakeet tuhosivat kaikki maan kasvit ja pirstoivat kaikki kedon puut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Ainoastaan Goosenin maata, jossa israelilaiset olivat, raesade ei kohdannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Farao kutsutti Mooseksen ja Aaronin ja sanoi heille: \"Minä olen tehnyt syntiä tällä kertaa. Herra on oikeassa, mutta minä ja kansani olemme väärässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Rukoilkaa Herraa, sillä meillä on jo tarpeeksi Jumalan jyrinää ja rakeita. Minä päästän teidät, eikä teidän tarvitse enää viipyä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Mooses vastasi hänelle: \"Kun lähden kaupungista, minä ojennan käteni Herran puoleen, ja jyrinä lakkaa eikä rakeita enää tule tietääksesi, että maa on Herran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Mutta et sinä eivätkä palvelijasi, sen kyllä tiedän, vielä nytkään pelkää Herraa Jumalaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Pellava ja ohra tuhoutuivat, sillä ohra oli tähkällä ja pellava kukassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Mutta vehnä ja speltti eivät turmeltuneet, sillä ne tuleentuvat myöhemmin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Mooses lähti faraon luota ulos kaupungista, ja ojensi kätensä Herran puoleen. Jyrinä ja rakeet lakkasivat, eikä sade enää vuotanut maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Kun farao näki, että sade, rakeet ja jyrinä lakkasivat, hän teki yhä edelleen syntiä ja paadutti sydämensä, sekä hän että hänen palvelijansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Faraon sydän paatui, eikä hän päästänyt israelilaisia, kuten Herra oli Mooseksen kautta sanonutkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Herra sanoi Moosekselle: \"Mene faraon luo, sillä minä olen kovettanut hänen sydämensä ja hänen palvelijoidensa sydämet, että tekisin nämä merkit heidän keskellään');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'ja että kertoisit lapsillesi ja lastesi lapsille, mitä olen tehnyt egyptiläisille, ja merkkini, jotka olen tehnyt heidän keskuudessaan tietääksenne, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Mooses ja Aaron menivät faraon luo ja sanoivat hänelle: \"Näin sanoo Herra, heprealaisten Jumala: Kuinka kauan sinä kieltäydyt nöyrtymästä edessäni? Päästä kansani palvelemaan minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Sillä jos sinä kieltäydyt päästämästä kansaani, katso, annan huomenna tulla maahasi heinäsirkkoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Ne peittävät maan pinnan, niin ettei maata näy, ja ne syövät tähteet siitä, mikä teille rakeilta pelastui ja jäi, ja ne syövät kaikki puunne, jotka kedolla kasvavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Ne täyttävät talosi, kaikkien palvelijoittesi talot ja kaikkien egyptiläisten talot, niin ettei isäsi eivätkä esi-isäsi ole sellaista nähneet siitä päivästä, jona tulivat maailmaan, hamaan tähän päivään asti.\" Hän kääntyi pois ja lähti faraon luota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Mutta faraon palvelijat sanoivat hänelle: \"Kuinka kauan tämä mies on oleva meille paulaksi? Päästä miehet palvelemaan Herraa, heidän Jumalaansa. Etkö vieläkään ymmärrä, että Egypti joutuu perikatoon?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Mooses ja Aaron tuotiin takaisin faraon eteen. Hän sanoi heille: \"Menkää ja palvelkaa Herraa, Jumalaanne. Ketkä kaikki menevät?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Mooses vastasi: \"Menemme, nuoret ja vanhat, menemme poikinemme ja tyttärinemme, lampainemme ja karjoinemme, sillä meillä on Herran juhla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Hän sanoi heille: \"Olkoon niin! Herra olkoon kanssanne! Lähetän teidät menemään. Entä lapsenne? Katsokaa, teillähän on paha mielessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Se ei tule tapahtumaan. Mutta menkää te, vahvat miehet, ja palvelkaa Herraa, sillä sitähän te olette pyytäneetkin.\" Heidät ajettiin pois faraon edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Sitten Herra sanoi Moosekselle: \"Ojenna kätesi Egyptin maan yli ja tuo tänne heinäsirkat. Tulkoon niitä Egyptin maahan, ja syökööt ne kaikki maan kasvit, kaikki, mitä rakeilta on jäänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Mooses ojensi sauvansa Egyptin maan yli, ja Herra antoi itätuulen puhaltaa yli maan koko sen päivän ja koko yön. Kun aamu tuli, itätuuli toi heinäsirkat mukanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Heinäsirkkoja tuli koko Egyptin maahan, ja ne laskeutuivat hyvin suurina parvina koko Egyptin alueelle. Niin paljon heinäsirkkoja ei ole koskaan sitä ennen tullut eikä sen jälkeen tule.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Ne peittivät koko maan pinnan, niin että maa tuli mustaksi. Ne söivät kaikki maan kasvit ja kaikki puiden hedelmät, jotka olivat rakeilta säilyneet. Mitään vihantaa ei jäänyt jäljelle puihin eikä kedon kasveihin koko Egyptin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Farao kutsutti kiireesti Mooseksen ja Aaronin ja sanoi: \"Olen rikkonut Herraa, teidän Jumalaanne, ja teitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Anna nyt anteeksi syntini vielä tämä kerta, ja rukoilkaa Herraa, Jumalaanne, että hän vain poistaisi minulta tämän surman.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Hän lähti pois faraon luota ja rukoili Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Herra käänsi tuulen hyvin kovaksi länsituuleksi. Se vei heinäsirkat mukanaan ja painoi ne Kaislamereen, niin ettei yhtään heinäsirkkaa jäänyt koko Egyptin alueelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Mutta Herra paadutti faraon sydämen, niin ettei hän päästänyt israelilaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Herra sanoi Moosekselle: \"Ojenna kätesi taivasta kohti, niin Egyptin maahan tulee sellainen pimeys, että siihen voi käsin tarttua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Mooses ojensi kätensä taivasta kohti, ja koko Egyptin maahan tuli synkkä pimeys kolmeksi päiväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Kukaan ei voinut nähdä toistaan, eikä kukaan voinut liikkua paikaltaan kolmeen päivään. Mutta kaikilla israelilaisilla oli valoisaa asuinpaikoissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Niin farao kutsui Mooseksen ja sanoi: \"Menkää ja palvelkaa Herraa. Ainoastaan lampaanne ja karjanne jääkööt tänne. Myös vaimonne ja lapsenne menkööt teidän mukananne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Mutta Mooses sanoi: \"Sinun on annettava mukaamme myös teurasuhrit ja polttouhrit uhrataksemme niitä Herralle, Jumalallemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Karjammekin täytyy tulla kanssamme, ei sorkkaakaan saa jäädä, sillä siitä meidän on otettava uhrit palvellaksemme Herraa, Jumalaamme, emmekä ennen sinne tuloa itsekään tiedä, mitä meidän on uhrattava palvellessamme Herraa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Mutta Herra paadutti faraon sydämen, niin että hän ei tahtonut päästää heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Farao sanoi hänelle: \"Mene pois luotani ja varo, ettet enää tule kasvojeni eteen, sillä sinä päivänä, jona tulet kasvojeni eteen, sinä kuolet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Mooses vastasi: \"Oikein puhuit. Enää en näe kasvojasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Herra sanoi Moosekselle: \"Vielä yhden vitsauksen tuotan faraolle ja Egyptiin. Sen jälkeen hän päästää teidät täältä. Kun hän todella päästää teidät, hän ajamalla ajaa teidät täältä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Puhu siis nyt kansalle, että he, jokainen mies ja jokainen nainen, pyytävät lähimmäisiltään hopea- ja kultaesineitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Herra antoi kansan päästä egyptiläisten suosioon. Myös Mooses oli hyvin arvossapidetty mies Egyptin maassa, sekä faraon palvelijoiden että kansan silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Mooses sanoi: \"Näin sanoo Herra: Puolenyön aikaan minä lähden kulkemaan kautta Egyptin maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Kaikki esikoiset Egyptin maassa kuolevat, valtaistuimellaan istuvan faraon esikoisesta käsikiveä pyörittävän orjattaren esikoiseen asti, sekä kaikki karjan esikoiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Koko Egyptin maassa on oleva kova valitus, jonka kaltaista ei ole ollut eikä koskaan tule.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Mutta kenellekään israelilaiselle ei koirakaan murise, ei ihmiselle eikä eläimelle, tietääksesi, että Herra tekee erotuksen egyptiläisten ja Israelin välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Kaikki nämä palvelijasi tulevat luokseni, kumartavat minua ja sanovat: \'Mene pois, sinä ja kaikki kansa, joka sinua seuraa.\'\" Hän lähti faraon luota vihasta hehkuen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Mutta Herra sanoi Moosekselle: \"Farao ei kuule teitä, jotta paljon ihmeitäni tapahtuisi Egyptin maassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Mooses ja Aaron olivat tehneet kaikki nämä ihmeet faraon edessä, mutta Herra oli paaduttanut faraon sydämen, niin ettei hän päästänyt israelilaisia maastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Herra puhui Moosekselle ja Aaronille Egyptin maassa sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, '\"Tämä kuukausi olkoon teillä kuukausista ensimmäinen. Siitä aloittakaa vuoden kuukaudet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Puhukaa koko Israelin kansalle ja sanokaa: Tämän kuun kymmenentenä päivänä ottakoon kukin perheenisäntä itselleen karitsan, yhden karitsan joka perhekuntaa kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Mutta jos perhe on liian pieni syödäkseen koko karitsan, ottakoon lähimmän naapurinsa kanssa yhteisen karitsan, henkilöluvun mukaan. Karitsaa kohti laskekaa niin monta, että voivat sen syödä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Karitsanne olkoon virheetön, vuoden vanha urospuoli. Ottakaa se lampaista tai vuohista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Säästäkää se neljänteentoista päivään tätä kuuta. Silloin Israelin koko seurakunta teurastakoon sen iltahämärässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Ottakoot sen verta ja sivelkööt sillä molemmat pihtipielet ja ovenkamanan niissä taloissa, joissa he sitä syövät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Syökööt lihan samana yönä. Syökööt sen tulessa paistettuna, happamattoman leivän ja katkerien yrttien kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Älkää syökö siitä mitään raakana tai vedessä keitettynä, vaan tulessa paistettuna päineen, jalkoineen ja sisälmyksineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Älkää jättäkö siitä mitään huomenaamuksi. Mutta jos jotakin siitä jäisi huomenaamuksi, niin polttakaa se tulessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Syökää se näin: lanteet vyötettyinä, kengät jalassanne ja sauva kädessänne. Syökää se kiirettä pitäen. Tämä on pääsiäinen Herran kunniaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Sillä kuljen sinä yönä kautta Egyptin maan ja surmaan kaikki esikoiset Egyptin maassa, sekä ihmiset että eläimet, ja panen toimeen rangaistustuomion, jonka olen langettanut kaikista Egyptin jumalista. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Veri on oleva merkki teille suojelukseksi taloissa, joissa olette. Sillä kun näen veren, menen teidän ohitsenne, eikä rangaistus tuhoa teitä, kun rankaisen Egyptin maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Tämä päivä olkoon teille muistopäivä, ja viettäkää sitä Herran juhlana. Sukupolvesta sukupolveen viettäkää sitä ikiaikaisena säädöksenä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Seitsemän päivää syökää happamatonta leipää. Jo ensimmäisenä päivänä korjatkaa pois hapan taikina taloistanne. Sillä jokainen, joka syö hapanta ensimmäisestä päivästä seitsemänteen päivään asti, hävitettäköön Israelista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Ensimmäisenä päivänä pitäkää pyhä kokous ja samoin myös seitsemäntenä päivänä pyhä kokous. Mitään työtä älköön tehtäkö niinä päivinä. Ainoastaan se, mitä kukin tarvitsee ruuaksi, ainoastaan se valmistettakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Pitäkää tätä happamattoman leivän juhlaa, sillä juuri sinä päivänä vein teidän joukkonne pois Egyptin maasta. Sen tähden pitäkää tätä päivää sukupolvesta sukupolveen ikuisena säädöksenä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Ensimmäisessä kuussa kuukauden neljännentoista päivän iltana syökää happamatonta leipää. Tehkää niin aina saman kuun kahdennenkymmenennen ensimmäisen päivän iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Seitsemään päivään älköön hapanta taikinaa olko taloissanne. Sillä jokainen, joka syö hapanta leipää, hävitettäköön Israelin kansasta, olipa hän muukalainen tai maassa syntynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Älkää syökö mitään hapanta, vaan syökää happamatonta leipää, missä asuttekin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Niin Mooses kutsui kaikki Israelin vanhimmat ja sanoi heille: \"Menkää ja ottakaa lammas jokaista perhekuntaanne kohti ja teurastakaa pääsiäislammas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Ottakaa iisoppikimppu, kastakaa se vereen, joka on maljassa, ja sivelkää oven kamana ja molemmat pihtipielet sillä verellä, joka on maljassa. Älköön kukaan menkö ulos talonsa ovesta ennen aamua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Sillä Herra kulkee rankaisemassa egyptiläisiä. Mutta kun Herra näkee veren ovenkamanassa ja molemmissa pihtipielissä, hän menee sen oven ohi eikä salli tuhoojan tulla taloihinne lyömään teitä vitsauksella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Noudattakaa tätä. Olkoon se ikuinen säädös sinulle ja lapsillesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Kun te tulette siihen maahan, jonka Herra teille antaa, kuten hän on sanonut, noudattakaa näitä menoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Kun sitten lapsenne kysyvät teiltä: \'Mitä nämä menot merkitsevät?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'niin vastatkaa: \'Tämä on pääsiäisuhri Herralle, joka meni israelilaisten talojen ohi Egyptissä, kun hän rankaisi egyptiläisiä, mutta säästi meidän kotimme.\'\" Kansa kumartui maahan ja rukoili.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Israelilaiset menivät ja tekivät, kuten Herra oli Moosekselle ja Aaronille käskyn antanut. Niin he tekivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Puolenyön aikaan tapahtui, että Herra surmasi kaikki Egyptin maan esikoiset valtaistuimellaan istuvan faraon esikoisesta vankikuopassa olevan vangin esikoiseen asti, sekä kaikki karjan esikoiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Farao nousi sinä yönä ja kaikki hänen palvelijansa sekä kaikki egyptiläiset, ja kova valitus oli Egyptissä. Sillä ei ollut yhtään taloa, jossa ei ollut kuollutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Hän kutsutti yöllä Mooseksen ja Aaronin ja sanoi: \"Nouskaa ja menkää pois kansani joukosta, sekä te että israelilaiset. Menkää ja palvelkaa Herraa, niin kuin olette puhuneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Ottakaa myös lampaanne ja karjanne mukaanne, niin kuin olette puhuneet, ja menkää ja rukoilkaa minullekin siunausta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Egyptiläiset ahdistivat kansaa jouduttaakseen heidän lähtöään maasta pois, sillä he ajattelivat: \"Me kaikki kuolemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Kansa otti taikinansa, ennen kuin se oli hapantunut, ja kantoi taikinakaukalonsa vaatteisiin käärittynä olkapäillään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Israelilaiset olivat tehneet Mooseksen sanan mukaan: he olivat pyytäneet egyptiläisiltä hopea- ja kultaesineitä sekä vaatteita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Herra oli antanut kansan päästä egyptiläisten suosioon, niin että nämä suostuivat heidän pyyntöönsä. He veivät saalista egyptiläisiltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Israelilaiset lähtivät liikkeelle ja kulkivat Ramseksesta Sukkotiin. Heitä oli noin kuusisataa tuhatta jalkamiestä, laskematta mukaan vaimoja ja lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Myös paljon sekakansaa meni heidän kanssaan, sekä suuret laumat lampaita ja nautakarjaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'He leipoivat happamattomia leipiä siitä taikinasta, jonka olivat tuoneet Egyptistä, sillä se ei ollut hapantunut, kun heidät karkotettiin Egyptistä. He eivät olleet saaneet viipyä, eivätkä he myöskään olleet valmistaneet itselleen evästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Aika, jonka israelilaiset olivat asuneet Egyptissä, oli neljäsataa kolmekymmentä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Kun ne neljäsataa kolmekymmentä vuotta olivat kuluneet, niin juuri sinä päivänä kaikki Herran joukot lähtivät Egyptin maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Valvontayö Herran kunniaksi on tämä yö, koska hän silloin vei heidät pois Egyptin maasta. Tämän yön kaikki israelilaiset valvokoot Herran kunniaksi, sukupolvesta sukupolveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Herra sanoi Moosekselle ja Aaronille: \"Tämä on säädös pääsiäislampaasta: Kukaan muukalainen älköön siitä syökö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Mutta jokainen rahalla ostettu orja syököön siitä, kunhan olet ympärileikannut hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Kansalaisoikeutta vailla oleva ja päiväpalkkalainen älkööt siitä syökö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Samassa talossa se syötäköön. Älköön talosta vietäkö ulos mitään siitä lihasta, älkääkä siitä luuta rikkoko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Koko Israelin seurakunta viettäköön tätä ateriaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Jos joku muukalainen asuu luonasi ja tahtoo viettää pääsiäistä Herran kunniaksi, ympärileikkauttakoon kaikki talonsa miespuoliset ja sitten käyköön sitä viettämään ja olkoon silloin kuin maan kansalainen. Mutta yksikään ympärileikkaamaton älköön siitä syökö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Sama laki olkoon maassa syntyneellä ja muukalaisella, joka asuu keskuudessanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Kaikki israelilaiset tekivät, kuten Herra oli Moosekselle ja Aaronille käskyn antanut. Niin he tekivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Juuri sinä päivänä Herra vei israelilaiset joukkoineen pois Egyptin maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, '\"Pyhitä minulle jokainen esikoinen, jokainen, joka israelilaisten keskuudessa, sekä ihmisistä että karjasta, avaa äidinkohdun. Se on minun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Mooses sanoi kansalle: \"Muistakaa tämä päivä, jona te lähditte Egyptistä, orjuuden pesästä, sillä Herra vei teidät sieltä pois väkevällä kädellä. Sen tähden älköön silloin mitään hapanta syötäkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Tänä päivänä aabib-kuussa te lähditte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Kun Herra vie sinut kanaanilaisten, heettiläisten, amorilaisten, hivviläisten ja jebusilaisten maahan, jonka hän isillesi vannotulla valalla on luvannut antaa sinulle, siihen maahan, joka vuotaa maitoa ja hunajaa, niin vietä tämä jumalanpalvelus tässä kuussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Syö seitsemänä päivänä happamatonta leipää, ja seitsemäntenä päivänä olkoon Herran juhla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Happamatonta leipää syötäköön näinä seitsemänä päivänä. Älköön mitään hapanta olko, älköön olko hapanta taikinaa koko maassasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Kerro pojallesi sinä päivänä ja sano: \'Näin tehdään sen johdosta, mitä Herra minulle teki, kun lähdin Egyptistä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Se olkoon merkkinä kädessäsi ja muistutuksena otsallasi, että Herran laki olisi suussasi, sillä Herra vei sinut väkevällä kädellä pois Egyptistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Sen tähden noudata tätä säädöstä määräaikana vuodesta vuoteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Kun Herra on vienyt sinut kanaanilaisten maahan, kuten hän on sinulle ja isillesi vannonut, sitten kun hän on sen sinulle antanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'luovuta Herralle kaikki, mikä avaa äidinkohdun. Kaikki urospuoliset esikoiset karjastasi olkoot Herran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Mutta jokainen aasin esikoinen lunasta lampaalla. Mutta jos et sitä lunasta, niin taita siltä niska. Lunasta jokainen ihmisen esikoinen poikiesi joukosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Kun poikasi vastaisuudessa kysyy sinulta ja sanoo: \'Mitä tämä merkitsee?\' vastaa hänelle: \' Herra vei meidät väkevällä kädellä pois Egyptistä, orjuuden pesästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Sillä kun farao paatui ja kieltäytyi päästämästä meitä, Herra surmasi kaikki esikoiset Egyptin maassa, ihmisten esikoisista karjan esikoisiin asti. Sen tähden minä uhraan Herralle jokaisen urospuolen, joka avaa äidinkohdun, ja lunastan jokaisen esikoisen pojistani.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Se olkoon merkkinä kädessäsi ja muistolauseena otsallasi. Sillä Herra vei meidät väkevällä kädellä pois Egyptistä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Mutta kun farao oli päästänyt kansan, Jumala ei johdattanut heitä sitä tietä, joka kulki filistealaisten maan kautta, vaikka se oli suorin. Jumalalla näet oli huoli siitä, että kansa katuu nähdessään sodan syttyvän ja palaa Egyptiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Sen sijaan Jumala antoi kansan poiketa erämaahan vievälle tielle Kaislamerta kohti. Taisteluvalmiina israelilaiset lähtivät Egyptin maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Mooses otti mukaansa Joosefin luut, sillä tämä oli vannottanut israelilaisia ja sanonut: \"Kun Jumala pitää huolen teistä, viekää silloin luuni täältä mukananne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'He lähtivät liikkeelle Sukkotista ja leiriytyivät erämaan reunaan Eetamiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Herra kulki heidän edellään päivällä pilvenpatsaassa johdattaakseen heitä tietä myöten ja yöllä tulenpatsaassa valaistakseen heidän kulkunsa, niin että he voivat vaeltaa sekä päivällä että yöllä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Pilvenpatsas ei poistunut päivällä eikä tulenpatsas yöllä kansan edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, '\"Sano israelilaisille, että he kääntyvät takaisin ja leiriytyvät Pii-Hahirotin kohdalle Migdolin ja meren välille. Leiriytykää vastapäätä Baal-Sefonia meren rannalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Farao sanoo sydämessään, että israelilaiset ovat eksyneet maassa ja että erämaa on saartanut heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Paadutan faraon sydämen, niin että hän ajaa heitä takaa. Mutta näytän kunniani faraossa ja koko hänen sotajoukossaan. Egyptiläiset tulevat tietämään, että minä olen Herra.\" He tekivät niin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Kun Egyptin kuninkaalle ilmoitettiin, että kansa oli paennut, faraon ja hänen palvelijoidensa mieli muuttui kansaa kohtaan. He sanoivat: \"Mitä teimmekään, kun päästimme Israelin meitä palvelemasta!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Hän valjastutti hevoset sotavaunujensa eteen ja otti sotaväkensä mukaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Hän otti kuusisataa valiosotavaunua sekä kaikki muut Egyptin sotavaunut sekä valiomiehistöt niihin kaikkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Sillä Herra paadutti faraon, Egyptin kuninkaan, sydämen, niin että hän lähti ajamaan takaa israelilaisia, vaikka israelilaiset olivat lähteneet matkaan voimallisen käden suojassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Egyptiläiset, kaikki faraon hevoset, sotavaunut ja ratsumiehet ja koko hänen sotajoukkonsa, ajoivat heitä takaa ja saavuttivat heidät leiriytyneinä meren rannalla, Pii-Hahirotin kohdalla, vastapäätä Baal-Sefonia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Kun farao oli lähellä, israelilaiset nostivat silmänsä ja näkivät, että egyptiläiset olivat tulossa heidän perässään. Silloin israelilaiset pelästyivät suuresti ja huusivat Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'He sanoivat Moosekselle: \"Eikö Egyptissä ollut hautoja, kun toit meidät tänne erämaahan kuolemaan? Mitä teitkään meille, kun johdatit meidät pois Egyptistä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Emmekö sanoneet tätä sinulle Egyptissä? Sanoimmehan: Anna meidän olla rauhassa, että palvelisimme egyptiläisiä. Sillä parempi olisi ollut palvella egyptiläisiä kuin kuolla erämaahan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Mooses vastasi kansalle: \"Älkää pelätkö. Pysykää paikoillanne, niin näette, minkä pelastuksen Herra tänä päivänä antaa teille, sillä sellaista, minkä näette egyptiläisille tapahtuvan tänä päivänä, ette tule enää koskaan näkemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Herra sotii teidän puolestanne, mutta te olkaa hiljaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Herra sanoi Moosekselle: \"Miksi huudat minulle? Sano israelilaisille, että he lähtevät liikkeelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Mutta nosta sinä sauvasi ja ojenna kätesi meren yli ja halkaise se, niin että israelilaiset voivat käydä meren poikki kuivaa maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Katso, minä paadutan egyptiläisten sydämet, niin että he tulevat heidän perässään. Näytän kunniani faraossa ja koko hänen sotajoukossaan, hänen sotavaunuissaan ja ratsumiehissään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Egyptiläiset tulevat tietämään, että minä olen Herra, kun näytän kunniani faraossa, hänen sotavaunuissaan ja ratsumiehissään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Jumalan Enkeli, joka oli kulkenut Israelin joukon edellä, siirtyi kulkemaan heidän takanaan, ja pilvenpatsas siirtyi heidän edeltään ja asettui heidän taakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'Se tuli egyptiläisten joukon ja Israelin joukon väliin. Pilvi oli pimeä heille, mutta valaisi yön Israelille. Näin koko yönä toinen joukko ei voinut lähestyä toista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Sitten Mooses ojensi kätensä meren yli. Herra saattoi vahvalla itätuulella, joka puhalsi koko yön, meren väistymään ja muutti meren kuivaksi maaksi, ja vesi jakautui kahtia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Israelilaiset kulkivat meren poikki kuivaa maata, ja vesi oli heillä muurina sekä oikealla että vasemmalla puolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Egyptiläiset, kaikki faraon hevoset, hänen sotavaununsa ja ratsumiehensä, ajoivat heitä takaa ja tulivat heidän perässään keskelle merta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Kun aamuvartio tuli, Herra katsoi egyptiläisten joukkoon tulenpatsaasta ja pilvestä ja saattoi hämminkiin egyptiläisten joukon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Hän antoi heidän vaunujensa pyörien irtautua, niin että heille kävi vaikeaksi päästä eteenpäin. Niin egyptiläiset sanoivat: \"Paetkaamme Israelia, sillä Herra sotii heidän puolestaan egyptiläisiä vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Herra sanoi Moosekselle: \"Ojenna kätesi meren yli, että vedet palautuisivat ja peittäisivät egyptiläiset, heidän sotavaununsa ja ratsumiehensä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Mooses ojensi kätensä meren yli, ja aamun koittaessa meri palasi paikalleen egyptiläisten paetessa sitä vastaan. Herra syöksi egyptiläiset keskelle merta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Vedet palasivat ja peittivät sotavaunut ja ratsumiehet, koko faraon sotajoukon, joka oli seurannut heitä mereen. Yksikään heistä ei pelastunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Mutta israelilaiset olivat kulkeneet kuivaa maata meren poikki. Vesi oli heillä muurina sekä oikealla että vasemmalla puolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Herra pelasti Israelin sinä päivänä egyptiläisten käsistä, ja Israel näki egyptiläiset kuolleina meren rannalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Israel näki sen suuren teon, jonka Herra teki tuhotessaan egyptiläiset. Kansa pelkäsi Herraa ja uskoi Herraan ja uskoi hänen palvelijaansa Moosesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Silloin Mooses ja israelilaiset veisasivat Herralle tämän virren. He sanoivat näin: \"Veisaan Herralle, sillä hän on hyvin korkea. Hevoset ja miehet hän mereen syöksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Herra on väkevyyteni ja ylistysvirteni. Hänestä tuli minulle pelastus. Hän on Jumalani, ja ylistän häntä, hän on isäni Jumala, ja kunnioitan häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Herra on sodankävijä. Herra on hänen nimensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Faraon vaunut ja hänen sotajoukkonsa hän suisti mereen, hänen valiovaunusoturinsa hukkuivat Kaislamereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Syvyys peitti heidät. He vajosivat pohjaan kuin kivi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Sinun oikea kätesi, Herra, on suuri voimassa. Sinun oikea kätesi, Herra, murskaa vihollisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Valtasuuruudessasi kukistat vastustajasi. Päästät vihasi valloilleen, ja se kuluttaa heidät kuin korret.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Vihasi puhalluksesta vedet kasaantuivat, laineet seisahtuivat röykkiöiksi, syvyyden aallot hyytyivät keskelle merta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Vihollinen sanoi: Ajan heitä takaa ja saavutan heidät. Jaan saaliin ja tyydytän heissä kostonhimoni. Paljastan miekkani, ja käteni hävittää heidät.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Tuulesi puhalsi, ja meri peitti heidät. He upposivat mahtaviin vesiin kuin lyijy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Herra, kuka on vertaisesi jumalien joukossa! Kuka on vertaisesi, sinä pyhyydessä jalo, sinä ylistettävissä teoissa pelottava, sinä ihmeiden tekijä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Ojensit oikean kätesi, ja maa nielaisi heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Mutta armossasi sinä johdatit lunastamaasi kansaa ja veit sen voimallasi pyhään asuntoosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Kansat kuulevat sen ja vapisevat, tuska valtaa Filistean asukkaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Silloin pelästyvät Edomin ruhtinaat, Mooabin päämiehet valtaa vapina, kaikki Kanaanin asukkaat menehtyvät pelkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Kauhu ja väristys valtaa heidät. Käsivartesi väkevyyden tähden he käyvät mykiksi kuin kivi. Sinun kansasi, Herra, kulkee perille, kulkee perille se kansa, jonka olet hankkinut itsellesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Viet heidät perille ja istutat heidät vuorelle, joka on perintöosasi, paikkaan, jonka sinä, Herra, olet asunnoksesi valmistanut, pyhäkköösi, Herra, jonka kätesi ovat tehneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Herra on kuningas aina ja iankaikkisesti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Sillä kun faraon hevoset ja hänen sotavaununsa ja ratsumiehensä menivät mereen, Herra palautti meren vedet heidän päälleen, mutta israelilaiset kulkivat kuivaa maata meren poikki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Naisprofeetta Mirjam, Aaronin sisar, otti tamburiinin käteensä, ja kaikki naiset seurasivat häntä tamburiineja lyöden ja karkeloiden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Mirjam viritti heille virren: \"Veisatkaa Herralle, sillä hän on hyvin korkea, hevoset ja miehet hän mereen syöksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Mooses antoi israelilaisten lähteä liikkeelle Kaislameren luota, ja he menivät Suurin erämaahan. He vaelsivat kolme päivää erämaassa löytämättä vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'He tulivat Maaraan. Mutta he eivät voineet juoda Maaran vettä, sillä se oli karvasta. Sen tähden paikka sai nimen Maara.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Niin kansa niskoitteli Moosesta vastaan ja sanoi: \"Mitä juomme?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Mutta hän huusi Herran puoleen. Herra osoitti hänelle puun, jonka hän heitti veteen, ja vesi tuli makeaksi. Siellä hän antoi kansalle lain ja oikeussäädöksiä, ja siellä hän koetteli sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Hän sanoi: \"Jos sinä kuulet Herraa, Jumalaasi, ja teet, mikä on oikein hänen silmissään, otat vaarin hänen käskyistään ja noudatat koko hänen lakiaan, niin en pane kärsittäväksesi ainoatakaan niistä vaivoista, jotka olen pannut egyptiläisten kärsittäviksi, sillä minä olen Herra, parantajasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'He saapuivat Eelimiin. Siellä oli kaksitoista vesilähdettä ja seitsemänkymmentä palmupuuta. He leiriytyivät siellä veden ääreen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Toisen kuun viidentenätoista päivänä sen jälkeen, kun he olivat lähteneet Egyptin maasta, he, koko Israelin kansa, lähtivät liikkeelle Eelimistä ja tulivat Siinin erämaahan, joka on Eelimin ja Siinain välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Koko Israelin kansa niskoitteli Moosesta ja Aaronia vastaan erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Israelilaiset sanoivat heille: \"Jospa olisimme saaneet surmamme Herran kädestä Egyptin maassa, jossa istuimme lihapatojen ääressä ja meillä oli leipää kyllin syödäksemme! Mutta olette tuoneet meidät tähän erämaahan antaaksenne koko tämän seurakunnan kuolla nälkään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Herra sanoi Moosekselle: \"Katso, annan sataa teille leipää taivaasta. Kansa menköön ja kootkoon kunakin päivänä päivän tarpeen. Näin koettelen heitä, vaeltavatko he laissani vai eivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Kun he kuudentena päivänä valmistavat sen, mitä ovat tuoneet kotiin, niin sitä on oleva kaksi kertaa niin paljon, kuin mitä he muuten joka päivä kokoavat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Mooses ja Aaron sanoivat kaikille israelilaisille: \"Tänä iltana te tulette tietämään, että Herra on vienyt teidät pois Egyptin maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'Aamulla näette Herran kunnian, koska Herra on kuullut napinanne häntä vastaan. Sillä mitä me olemme, että te meitä vastaan niskoittelette?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Mooses sanoi: \" Herra antaa teille tänä iltana lihaa syödäksenne ja huomenna leipää yllin kyllin, koska Herra on kuullut napinanne, kun olette niskoitelleet häntä vastaan. Sillä mitä me olemme? Ette ole niskoitelleet meitä vastaan, vaan Herraa vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Mooses sanoi Aaronille: \"Sano koko Israelin kansalle: Astukaa Herran eteen, sillä hän on kuullut napinanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Kun Aaron oli puhunut tämän koko Israelin seurakunnalle, he kääntyivät erämaahan päin, ja katso, Herran kunnia näkyi pilvessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, '\"Olen kuullut israelilaisten napinan. Puhu heille ja sano: iltahämärässä teillä on oleva lihaa syödäksenne, ja huomenna on teillä leipää yllin kyllin tietääksenne, että minä olen Herra, teidän Jumalanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Illalla tuli viiriäisiä, ja ne peittivät leirin, ja aamulla laskeutui kastesumu leirin ympärille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Kun kastesumu oli haihtunut, katso, erämaassa oli maan pinnalla hienoa mannaa, hienoa kuin härmä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Kun israelilaiset näkivät sen, he sanoivat toisilleen: \"Se on mannaa.\" Sillä he eivät tienneet, mitä se oli. Mooses sanoi heille: \"Tämä on se leipä, jonka Herra on antanut teille syötäväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Näin Herra on käskenyt: Kootkaa sitä, jokainen tarpeenne mukaan. Ottakaa kukin goomer-mitta perheenne pääluvun mukaan, kukin niin monelle, kuinka monta kullakin on teltassaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Israelilaiset tekivät niin, ja he kokosivat, yksi enemmän, toinen vähemmän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Mutta kun he mittasivat sen goomer-mitalla, sille ei jäänyt liikaa, joka oli koonnut enemmän, eikä siltä puuttunut, joka oli koonnut vähemmän. Jokainen oli koonnut niin paljon, kuin tarvitsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Mooses sanoi heille: \"Älköön kukaan jättäkö siitä mitään huomiseksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Mutta he eivät kuulleet Moosesta, vaan muutamat jättivät siitä huomiseksi. Siihen kasvoi matoja, ja se rupesi haisemaan, ja Mooses vihastui heihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'He kokosivat sitä joka aamu sen verran, kuin kukin tarvitsi. Mutta kun aurinko alkoi paahtaa, se suli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Mutta kuudentena päivänä he kokosivat leipää kaksinkertaisesti, kaksi goomeria kullekin. Kaikki kansan päämiehet tulivat ja ilmoittivat sen Moosekselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Hän sanoi heille: \"Tämä tapahtuu Herran sanan mukaan. Huomenna on sapattijuhla, Herralle pyhitetty sapatti. Mitä leivotte, se leipokaa, ja mitä keitätte, se keittäkää. Mutta kaikki, mitä jää tähteeksi, pankaa talteen huomiseksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'He panivat sen talteen huomiseksi, kuten Mooses oli käskenyt, eikä se ruvennut haisemaan, eikä siihen tullut matoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Mooses sanoi: \"Syökää se tänä päivänä, sillä tänä päivänä on Herran sapatti. Tänään ette löydä kedolta mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Kuutena päivänä on teidän sitä koottava, mutta seitsemäntenä päivänä on sapatti, eikä sitä ole.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Kuitenkin muutamat kansasta lähtivät seitsemäntenä päivänä kokoamaan sitä, mutta eivät löytäneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Herra sanoi Moosekselle: \"Kuinka kauan aiotte kieltäytyä noudattamasta käskyjäni ja lakiani?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Katsokaa, Herra on antanut teille sapatin. Sen tähden hän antaa teille kuudentena päivänä kahden päivän leivän. Pysyköön jokainen paikallaan. Älköön kukaan lähtekö paikaltaan seitsemäntenä päivänä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Kansa lepäsi seitsemäntenä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Israelin heimo antoi sille nimen manna. Se oli valkean korianterin siemenen kaltaista ja maistui hunajakakulta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Mooses sanoi: \"Näin on Herra käskenyt: Ota sitä täysi goomer-mitta säilytettäväksi sukupolvesta sukupolveen, että he näkisivät sen leivän, jolla olen ravinnut teitä erämaassa johdattaessani teitä Egyptin maasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Mooses sanoi Aaronille: \"Ota astia ja pane siihen täysi goomer-mitta mannaa ja aseta se Herran eteen säilytettäväksi sukupolvesta sukupolveen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Aaron asetti sen sitten talteen lain arkin eteen, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Israelilaiset söivät mannaa neljäkymmentä vuotta, kunnes he tulivat asuttuun maahan. He söivät mannaa siihen asti, kunnes he tulivat Kanaanin maan rajalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, '– Goomer on kymmenesosa eefaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Koko israelilaisten seurakunta lähti liikkeelle Siinin erämaasta ja kulki päivämatkojaan Herran sanan mukaan. He leiriytyivät Refidimiin, mutta siellä ei ollut vettä kansan juoda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Kansa niskoitteli Moosesta vastaan ja sanoi: \"Antakaa meille vettä juoda!\" Mooses vastasi heille: \"Miksi niskoittelette minua vastaan? Miksi kiusaatte Herraa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Mutta kansalla oli siellä jano, ja he niskoittelivat yhä Moosesta vastaan ja sanoivat: \"Minkä tähden toit meidät Egyptistä antaaksesi meidän, lastemme ja karjamme kuolla janoon?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Mooses huusi Herraa ja sanoi: \"Mitä teen tälle kansalle? Vielä vähän aikaa, ja he kivittävät minut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Herra vastasi Moosekselle: \"Mene kansan edellä ja ota mukaasi muutamia Israelin vanhimpia. Ota käteesi sauva, jolla löit Niiliä, ja mene.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Katso, seison siellä edessäsi kalliolla Hoorebin luona. Lyö kallioon, ja siitä vuotaa vettä, niin että kansa saa juoda.\" Mooses teki niin Israelin vanhimpien nähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Hän antoi paikalle nimen Massa ja Meriba, koska israelilaiset siellä riitelivät ja kiusasivat Herraa, sanoen: \"Onko Herra keskellämme vai ei?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Amalekilaiset tulivat ja taistelivat Israelia vastaan Refidimissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Mooses sanoi Joosualle: \"Valitse meille miehiä, mene ja taistele huomenna amalekilaisia vastaan. Minä asetun vuoren huipulle Jumalan sauva kädessäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Joosua teki, kuten Mooses oli hänelle sanonut, ja taisteli amalekilaisia vastaan. Mutta Mooses, Aaron ja Huur nousivat vuoren huipulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Niin kauan kuin Mooses piti kätensä ylhäällä, Israel oli voitolla. Mutta kun hän antoi kätensä laskea, amalekilaiset olivat voitolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Mutta kun Mooseksen kädet väsyivät, he ottivat kiven ja asettivat sen hänen alleen, ja hän istui sille, ja Aaron ja Huur kannattivat hänen käsiään molemmin puolin. Näin hänen kätensä kestivät vahvoina auringon laskuun asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Joosua voitti amalekilaiset ja heidän sotaväkensä miekan terällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Herra sanoi Moosekselle: \"Kirjoita tämä kirjaan muistoksi ja teroita se Joosuan mieleen: Pyyhkimällä pyyhin pois amalekilaisten muiston taivaan alta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Mooses rakensi alttarin ja pani sille nimeksi: \" Herra on lippuni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Hän sanoi: \"Minä nostan käteni Herran istuinta kohden: Herra sotii amalekilaisia vastaan sukupolvesta sukupolveen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Midianin pappi Jetro, Mooseksen appi, sai kuulla kaiken, mitä Jumala oli tehnyt Moosekselle ja kansalleen Israelille, ja että Herra oli vienyt Israelin pois Egyptistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Jetro, Mooseksen appi, oli ottanut mukaansa Sipporan, Mooseksen vaimon, jonka Mooses oli lähettänyt kotiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'ja hänen kaksi poikaansa. Näistä toisen nimi oli Geersom, koska Mooses oli sanonut: \"Minä olen muukalainen vieraalla maalla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'Toisen nimi oli Elieser, koska hän oli sanonut: \"Isäni Jumala oli apuni ja pelasti minut faraon miekalta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Jetro, Mooseksen appi, tuli hänen poikiensa ja hänen vaimonsa kanssa Mooseksen luo erämaahan, jossa tämä oli leiriytynyt Jumalan vuoren juurelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Hän käski sanoa Moosekselle: \"Minä Jetro, appesi, sekä vaimosi kahden poikansa kanssa olemme tulleet luoksesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Mooses meni appeaan vastaan, kumarsi ja suuteli häntä. Kun he olivat tervehtineet toisiaan, he menivät telttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Mooses kertoi apelleen kaiken, mitä Herra oli tehnyt faraolle ja egyptiläisille Israelin tähden, ja kaikki ne vaikeudet, jotka olivat kohdanneet heitä matkalla, ja kuinka Herra oli pelastanut heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Jetro iloitsi kaikesta siitä hyvästä, mitä Herra oli tehnyt Israelille pelastaessaan heidät egyptiläisten kädestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Jetro sanoi: \"Kiitetty olkoon Herra, joka on pelastanut teidät egyptiläisten ja faraon kädestä, Herra, joka on pelastanut kansansa egyptiläisten vallasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nyt tiedän, että Herra on suurempi kaikkia jumalia. Sillä sen tähden, että egyptiläiset ylpeilivät, heidän kävi näin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Jetro, Mooseksen appi, toimitti polttouhrin ja teurasuhreja Jumalalle. Aaron ja kaikki Israelin vanhimmat tulivat aterioimaan Mooseksen apen kanssa Jumalan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Seuraavana päivänä Mooses istui jakamaan oikeutta kansalle, ja kansa seisoi Mooseksen ympärillä aamusta iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Kun Mooseksen appi näki kaiken, mitä hän teki kansalle, hän sanoi: \"Mitä tämä tehtävä on, joka sinulla on kansan kanssa? Miksi sinä istut yksin ja kaikki kansa seisoo ympärilläsi aamusta iltaan asti?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Mooses vastasi apelleen: \"Kansa tulee luokseni kysymään Jumalalta neuvoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Kun heillä on jokin riita-asia, he tulevat luokseni, ja tuomitsen heidän välillään ja ilmoitan heille Jumalan säädökset ja hänen lakinsa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Mooseksen appi sanoi hänelle: \"Siinä et menettele hyvin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Sinä uuvutat sekä itsesi että tämän kansan, joka on kanssasi. Tämä tehtävä on näet sinulle liian raskas, etkä voi sitä yksin toimittaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Kuule nyt ääntäni. Neuvon sinua, ja Jumala on oleva kanssasi. Ole sinä kansan edustaja Jumalan edessä, ja saata sinä sen asiat Jumalan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Opeta heille säädökset ja lait, ja neuvo heille tie, jota heidän on kuljettava, ja mitä heidän on tehtävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Valitse koko kansasta kelvollisia ja Jumalaa pelkääviä, luotettavia ja väärää voittoa vihaavia miehiä, ja aseta ne heille tuhannen, sadan, viidenkymmenen ja kymmenen päämiehiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Nämä jakakoot aina oikeutta kansalle. Kaikki suuret asiat he saattakoot sinun tietoosi, mutta kaikki vähäiset asiat ratkaiskoot itse. Huojenna näin kuormaa itseltäsi, ja kantakoot he kuormaa kanssasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Jos näin teet ja Jumala itse sinua näin käskee, jaksat sen kestää, ja myös koko tämä kansa saa mennä rauhassa paikalleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Mooses noudatti appensa puhetta ja teki kaiken, mitä tämä oli sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Mooses valitsi kelvollisia miehiä koko Israelista ja asetti heidät kansan johtoon, tuhannen, sadan, viidenkymmenen ja kymmenen päämiehiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Nämä jakoivat aina oikeutta kansalle. Vaikeat asiat he siirsivät Moosekselle, mutta vähäiset asiat he ratkaisivat itse.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Mooses saattoi appensa matkaan, ja tämä meni omaan maahansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Kolmantena kuukautena sen jälkeen, kun israelilaiset olivat lähteneet Egyptin maasta, juuri samana kuukauden päivänä, he tulivat Siinain erämaahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'He olivat lähteneet Refidimistä, ja tulleet Siinain erämaahan sekä leiriytyneet erämaahan. Israel oli siellä leirissä vuoren juurella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Mooses nousi Jumalan luo, ja Herra huusi häntä vuorelta ja sanoi: \"Sano näin Jaakobin heimolle ja ilmoita israelilaisille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, '\'Te olette nähneet, mitä olen tehnyt egyptiläisille ja kuinka olen kantanut teitä kotkan siivillä ja tuonut teidät luokseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Jos nyt todella kuulette ääntäni ja pidätte liittoni, olette omaisuuteni ennen kaikkia muita kansoja, sillä koko maa on minun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Te olette minulle pappisvaltakunta ja pyhä kansa.\' Sano nämä sanat israelilaisille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Kun Mooses tuli takaisin, hän kutsui kokoon kansan vanhimmat ja puhui heille kaikki ne sanat, jotka Herra oli käskenyt hänen puhua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Koko kansa vastasi yksimielisesti ja sanoi: \"Kaiken, mitä Herra on puhunut, teemme.\" Mooses vei kansan vastauksen Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Herra sanoi Moosekselle: \"Katso, minä tulen luoksesi sakeassa pilvessä, että kansa kuulisi, kun puhun kanssasi, ja myös uskoisi sinua ainiaan.\" Mooses ilmoitti Herralle kansan vastauksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Herra sanoi Moosekselle: \"Mene kansan luo ja pyhitä heidät tänä päivänä ja huomenna, ja peskööt he vaatteensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Olkoot valmiit kolmanneksi päiväksi. Kolmantena päivänä Herra näet astuu koko kansan nähden alas Siinain vuorelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Merkitse raja kansan ympärille ja sano: \'Varokaa nousemasta vuorelle tai koskettamasta sen juurta. Jokaista, joka vuoreen koskee, rangaistakoon kuolemalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Älköön kenenkään käsi häneen koskeko, vaan hänet kivitettäköön tai ammuttakoon kuoliaaksi. Olipa eläin tai ihminen, se ei saa jäädä eloon.\' Vasta kun kuuluu pitkä torven puhallus, he nouskoot vuorelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Mooses astui alas vuorelta kansan luo ja pyhitti kansan, ja he pesivät vaatteensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Hän sanoi kansalle: \"Olkaa ylihuomiseksi valmiit. Älköön kukaan koskeko naiseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Kolmantena päivänä, kun aamu oli tullut, alkoi jyristä ja salamoida, ja sakea pilvi laskeutui vuoren ylle, ja kuului erittäin kova torven ääni, niin että koko kansa, joka oli leirissä, vapisi pelosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Mooses vei kansan leiristä Jumalaa vastaan, ja he asettuivat vuoren juurelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Koko Siinain vuori peittyi savuun, kun Herra astui sille alas tulessa. Siitä nousi savu kuin uunista, ja koko vuori vapisi kovasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Torven ääni koveni kovenemistaan. Mooses puhui, ja Jumala vastasi hänelle jyrinällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Herra astui alas Siinain vuorelle, vuoren laelle. Herra kutsui Mooseksen vuoren huipulle, ja Mooses nousi sinne ylös.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Herra sanoi Moosekselle: \"Astu alas ja varoita kansaa tunkeutumasta lähelle Herraa hänet nähdäkseen, sillä heistä kaatuu monta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Myös papit, jotka saavat lähestyä Herraa, pyhittäkööt itsensä, ettei Herra tuhoaisi heitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Mooses vastasi Herralle: \"Kansa ei voi nousta Siinain vuorelle, sillä sinä olet varoittanut meitä ja sanonut: \'Merkitse raja vuoren ympäri ja pyhitä se.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Herra sanoi hänelle: \"Astu alas ja tule taas ylös, sinä ja Aaron kanssasi. Mutta papit ja kansa älkööt tunkeutuko ylös lähelle Herraa, ettei hän heitä tuhoaisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Mooses astui alas kansan luo ja sanoi heille tämän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Jumala puhui kaikki nämä sanat ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, '\"Minä olen Herra, Jumalasi, joka vein sinut pois Egyptin maasta, orjuuden talosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Älä pidä muita jumalia minun rinnallani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Älä tee itsellesi jumalankuvaa äläkä mitään kuvaa, älä niistä, jotka ovat ylhäällä taivaassa, älä niistä, jotka ovat alhaalla maan päällä, äläkä niistä, jotka ovat vesissä maan alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Älä kumarra niitä äläkä palvele niitä. Sillä minä, Herra, sinun Jumalasi, olen kiivas Jumala, joka kostan isien pahat teot lapsille kolmanteen ja neljänteen polveen, niille, jotka minua vihaavat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'mutta teen laupeuden tuhansille, jotka rakastavat minua ja pitävät käskyni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Älä turhaan lausu Herran, sinun Jumalasi, nimeä, sillä Herra ei jätä rankaisematta sitä, joka hänen nimensä turhaan lausuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Muista pyhittää lepopäivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Kuusi päivää tee työtä ja toimita kaikki askareesi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'mutta seitsemäs päivä on Herran, sinun Jumalasi, sapatti. Silloin älä toimita mitään askaretta, älä sinä älköönkä poikasi tai tyttäresi, palvelijasi tai palvelijattaresi tai juhtasi älköönkä muukalaisesi, joka porteissasi on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Sillä kuutena päivänä Herra teki taivaan ja maan ja meren ja kaikki, mitä niissä on, mutta seitsemäntenä päivänä hän lepäsi. Sen tähden Herra siunasi lepopäivän ja pyhitti sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Kunnioita isääsi ja äitiäsi, että kauan eläisit siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Älä tapa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Älä tee huorin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Älä varasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Älä sano väärää todistusta lähimmäisestäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Älä himoitse lähimmäisesi huonetta. Älä himoitse lähimmäisesi vaimoa äläkä hänen palvelijaansa, palvelijatartaan, härkäänsä, aasiaan äläkä mitään, mikä on lähimmäisesi omaa.\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Kaikki kansa havaitsi jyrinän, tulen leimaukset, torven äänen ja vuoren suitsuamisen. Kun he sen havaitsivat, he vapisivat ja pysyivät taaempana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'He sanoivat Moosekselle: \"Puhu sinä kanssamme, niin me kuulemme. Älköön Jumala puhuko kanssamme, ettemme kuolisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Mutta Mooses vastasi kansalle: \"Älkää pelätkö, sillä Jumala on tullut koettelemaan teitä, että Herran pelko olisi edessänne ja ettette tekisi syntiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Kansa pysyi taaempana, mutta Mooses lähestyi pimeyttä, jossa Jumala oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Herra sanoi Moosekselle: \"Sano israelilaisille näin: Te olette nähneet, että minä olen puhunut teille taivaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Älkää tehkö jumalia minun rinnalleni. Älkää tehkö itsellenne hopeisia tai kultaisia jumalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Tee minulle alttari maasta, ja uhraa sen päällä polttouhrisi ja rauhanuhrisi, lampaasi ja nautasi. Joka paikassa, mihin säädän nimeni muiston, tulen luoksesi ja siunaan sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Mutta jos sinä teet minulle kivialttarin, älä rakenna sitä hakatusta kivestä. Sillä jos kosket taltallasi kiveen, saastutat sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Äläkä nouse portaita myöten minun alttarilleni, ettei häpysi sen päällä paljastuisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, '\"Nämä ovat ne oikeudet, jotka sinun tulee asettaa heidän eteensä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Jos sinä ostat heprealaisen orjan, hän palvelkoon kuusi vuotta, mutta seitsemäntenä hän pääsköön maksutta vapaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Jos hän on tullut yksin, yksin lähteköönkin. Mutta jos hän oli naimisissa, niin lähteköön vaimo hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Jos hänen isäntänsä on antanut hänelle vaimon, ja tämä on synnyttänyt hänelle poikia tai tyttäriä, vaimo lapsineen jääköön isännän omaksi, ja hän lähteköön yksin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Mutta jos orja vakuuttaa: \'Minä rakastan isäntääni, vaimoani ja lapsiani enkä tahdo päästä vapaaksi\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'niin hänen isäntänsä vieköön hänet Jumalan eteen ja asettakoon hänet ovea tai pihtipieltä vasten, ja hänen isäntänsä lävistäköön hänen korvansa naskalilla, ja hän olkoon hänen orjansa ainiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Jos joku myy tyttärensä orjaksi, älköön tämä pääskö vapaaksi, kuten miesorjat pääsevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Jos hän ei miellytä isäntäänsä, sitten kun tämä jo on määrännyt hänet itselleen, tämä sallikoon lunastaa hänet pois. Vieraaseen kansaan älköön hänellä olko valtaa häntä myydä, kun hän hänet hylkää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Mutta jos hän määrää hänet pojalleen, antakoon hänen nauttia tyttärien oikeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Jos hän ottaa itselleen toisen vaimon, älköön vähentäkö ensimmäiseltä tämän ravintoa, vaatetusta eikä avio-oikeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Jos hän ei tee hänelle näitä kolmea, lähteköön vaimo pois maksutta ja rahakorvauksetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Sitä, joka lyö ihmistä, niin että tämä kuolee, rangaistakoon kuolemalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Mutta jos hän ei ole tehnyt sitä murha-aikeessa, vaan Jumala on sallinut vahingon tapahtua hänen kätensä kautta, minä määrään sinulle paikan, jonne hän voi paeta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Mutta jos joku menettelee niin rikollisesti lähimmäistään kohtaan, että tappaa hänet kavalasti, sinun on otettava hänet minun alttarinikin luota surmattavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Sitä, joka lyö isäänsä tai äitiään, rangaistakoon kuolemalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Sitä, joka varastaa ihmisen ja joko myy hänet tai pitää häntä hallussaan, rangaistakoon kuolemalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Sitä, joka kiroaa isäänsä tai äitiään, rangaistakoon kuolemalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Jos miehet riitelevät keskenään ja toinen lyö toista kivellä tai nyrkillä, mutta tämä ei kuole, vaan joutuu vuoteen omaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'niin olkoon, jos hän tointuu ja voi mennä ulos sauvaansa nojaten, lyöjä vapaa rangaistuksesta. Korvatkoon ainoastaan hänen sairastamisaikansa ja pitäköön huolta hänen paranemisestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Jos joku lyö orjaansa tai orjatartaan sauvalla, niin että tämä kuolee hänen käsiinsä, häntä rangaistakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Mutta jos hän elää päivän tai kaksi, niin älköön lyöjää rangaistako, sillä se on hänen omaa rahaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Jos miehet tappelevat keskenään ja loukkaavat raskaana olevaa vaimoa, niin että hän synnyttää kesken, mutta vahinkoa ei tapahdu, niin sakotettakoon syyllistä vaimon miehen vaatimuksen ja riidanratkaisijan harkinnan mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Mutta jos vahinko tapahtuu, annettakoon henki hengestä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'silmä silmästä, hammas hampaasta, käsi kädestä, jalka jalasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'palovamma palovammasta, haava haavasta, mustelma mustelmasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Jos joku lyö orjaansa tai orjatartaan silmään ja turmelee sen, päästäköön hänet vapaaksi silmän tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Jos hän lyö orjaltaan tai orjattareltaan hampaan suusta, päästäköön hänet vapaaksi hampaan tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Jos härkä puskee miehen tai naisen kuoliaaksi, härkä kivitettäköön älköönkä sen lihaa syötäkö. Mutta härän omistaja olkoon vapaa rangaistuksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Jos taas härkä on ennenkin puskenut ja sen isäntää on varoitettu eikä hän ole sitä vartioinut, ja jos se tappaa miehen tai naisen, härkä kivitettäköön, ja myös sen isäntää rangaistakoon kuolemalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Mutta jos hänelle määrätään lunastusmaksu, maksakoon henkensä lunnaiksi niin paljon, kuin hänelle määrätään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Jos se puskee pojan tai tytön hengiltä, meneteltäköön saman lain mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Jos härkä puskee orjan tai orjattaren hengiltä, maksakoon sen omistaja pusketun isännälle kolmekymmentä hopeasekeliä, ja härkä kivitettäköön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Jos joku jättää kaivon auki tai kaivaa kaivon eikä peitä sitä, ja härkä tai aasi putoaa siihen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'kaivon omistaja korvatkoon isännälle sen rahassa, mutta kuollut eläin olkoon hänen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Jos jonkun härkä puskee toisen härän kuoliaaksi, myykööt elävän härän ja jakakoot sen hinnan, ja jakakoot myös kuolleen keskenään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Jos taas oli tunnettua, että härkä oli ennenkin puskenut eikä sen isäntä ollut sitä vartioinut, antakoon härän härästä, mutta kuollut olkoon hänen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 37, '\"Jos joku varastaa härän tai lampaan ja teurastaa tai myy sen, antakoon viisi nautaa yhdestä härästä ja neljä lammasta yhdestä lampaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Jos varas tavataan murtautumasta sisälle ja lyödään kuoliaaksi, tappaja ei ole vereen syypää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Mutta jos aurinko oli jo noussut, tappaja on vereen syypää. Varas maksakoon korvauksen. Mutta jos hänellä ei ole mitään, myytäköön hänet varastamansa tavaran korvaukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Jos varastettu eläin, olipa härkä, aasi tai lammas, tavataan hänen hallustaan elävänä, korvatkoon sen kaksinkertaisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Jos joku turmelee toisen pellon tai viinitarhan päästämällä siihen karjansa ja syöttämällä sitä toisen pellossa, antakoon korvaukseksi peltonsa tai viinitarhansa parhaimman kasvun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Jos tuli pääsee irti ja tarttuu orjantappuroihin ja jos kuhilaat tai vilja tai pelto palavat, vahingon korvatkoon se, joka on kulovalkean sytyttänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Jos joku antaa toiselle rahaa tai tavaraa säilytettäväksi ja se varastetaan tämän talosta, varas, jos hänet tavataan, korvatkoon sen kaksinkertaisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Mutta jos varasta ei tavata, astukoon talon omistaja Jumalan eteen ja vannokoon, ettei ole kädellään kajonnut toisen omaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Jokaisessa anastusasiassa, koskipa se härkää, aasia, lammasta, vaatetta tai mitä tahansa kadonnutta, josta joku sanoo: \'Tämä se on\', tulkoon kummankin asia Jumalan eteen. Se, jonka Jumala tuomitsee syylliseksi, korvatkoon toiselle kaksinkertaisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Jos joku antaa toiselle aasin tai härän tai lampaan tai minkä eläimen tahansa säilytettäväksi ja se kuolee, vahingoittuu tai ryöstetään kenenkään näkemättä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'vala Herran edessä ratkaiskoon heidän välillään, onko toinen kädellään kajonnut toisen omaan. Omistaja hyväksyköön valan, ja toinen olkoon korvauksesta vapaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Mutta jos se on häneltä varastettu, korvatkoon sen omistajalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Jos se on raadeltu, tuokoon sen esiin todistukseksi. Raadeltua hänen ei tarvitse korvata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Jos joku lainaa toiselta eläimen ja se vahingoittuu tai kuolee eikä omistaja ole saapuvilla, korvatkoon sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Jos omistaja on saapuvilla, korvausta ei tarvitse maksaa. Jos se oli vuokralla, olkoon korvauksena vuokra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Jos joku viettelee neitsyen, joka ei ole kihlattu, ja makaa hänet, maksakoon hänestä morsiamenhinnan ja ottakoon hänet vaimokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Jos isä kieltäytyy antamasta häntä hänelle, maksakoon mies rahassa morsiamen hinnan kuten neitsyestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Noituuden harjoittajan älä salli elää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Rangaistakoon kuolemalla jokaista, joka sekaantuu eläimeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Joka uhraa muille jumalille kuin Herralle, ainoalle, olkoon vihitty tuhon omaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Älä sorra äläkä ahdista muukalaista, sillä te olette itse olleet muukalaisina Egyptin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Älkää sortako leskeä tai orpoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Sillä jos sinä sorrat heitä ja he huutavat minua avukseen, niin minä totisesti kuulen heidän huutonsa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'ja vihani syttyy, ja surmaan teidät miekalla, niin että teidän vaimonne joutuvat leskiksi ja lapsenne orvoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Jos lainaat rahaa jollekulle kansastani, jollekulle köyhälle, joka on luonasi, älä menettele häntä kohtaan koronkiskurin tavoin. Älkää panko korkoa hänen maksettavakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Jos olet ottanut lähimmäiseltäsi pantiksi peiton, anna se hänelle takaisin, ennen kuin aurinko laskee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Sillä se on hänen ainoa peitteensä, johon hän käärii ruumiinsa. Missä hän muuten makaisi? Jos hän huutaa minua avukseen, minä kuulen häntä, sillä minä olen laupias.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Älä herjaa Jumalaa äläkä kiroa kansasi ruhtinasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Älä viivyttele antamasta antia vilja- ja mehusatosi runsaudesta. Esikoinen pojistasi anna minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Samoin tee nautojesi ja lampaittesi esikoiselle. Seitsemän päivää se olkoon emänsä kanssa. Kahdeksantena päivänä anna se minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Olkaa te minulle pyhä kansa. Älkää syökö kedolla raadellun eläimen lihaa, vaan heittäkää se koirille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, '\"Älä levitä valheellista huhua äläkä anna apuasi syylliselle rupeamalla vääräksi todistajaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Älä ole joukon mukana tekemässä pahaa äläkä todista riita-asiassa niin, että taivut joukon mukaan ja väännät oikean vääräksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Älä suosi alhaista hänen asiassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Jos tapaat vihollisesi härän tai aasin eksyksissä, saata se hänelle takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Jos näet vihamiehesi aasin makaavan kuormansa alla, älä jätä häntä auttamatta, vaan auta häntä päästämään se.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Älä vääristä keskuudessanne asuvan köyhän oikeutta hänen riita-asiassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Pysy loitolla väärästä asiasta äläkä surmaa viatonta ja vanhurskasta, sillä minä en julista syyllistä vanhurskaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Äläkä ota lahjusta, sillä lahjus sokaisee näkevät ja vääristää syyttömien asiat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Muukalaista älä sorra, sillä te tiedätte muukalaisen mielen, koska itsekin olette olleet muukalaisina Egyptin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Kuutena vuotena kylvä maasi ja korjaa sen sato.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Mutta seitsemäntenä vuotena jätä se korjaamatta ja lepäämään, että kansasi köyhät saisivat siitä syödä. Sen, mitä jää jäljelle, metsän eläimet syökööt. Samoin tee viinitarhallesi ja öljytarhallesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Kuusi päivää tee työtäsi, mutta lepää seitsemäs päivä, että härkäsi ja aasisi saisivat hengähtää ja orjattaresi poika sekä muukalainen saisivat virkistyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Noudattakaa kaikkea, mitä olen sanonut teille. Vierasten jumalien nimiä älkää mainitko, älköön niitä kuultako teidän huuliltanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Kolme kertaa vuodessa vietä juhlaa minun kunniakseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Pidä happamattoman leivän juhla: seitsemänä päivänä syö happamatonta leipää, kuten olen sinua käskenyt, määrättynä aikana aabib-kuussa, sillä siinä kuussa sinä olet lähtenyt Egyptistä. Mutta tyhjänä älköön ilmaannuttako kasvojeni eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Vietä leikkuujuhla, kun leikkaat ensisadon viljastasi, jonka olet kylvänyt peltoon, ja korjuujuhla vuoden lopussa, kun korjaat satosi pellolta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Kolme kertaa vuodessa tulkoon kaikki miesväkesi Herran, Herran, kasvojen eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Älä uhraa teurasuhrini verta happaman leivän kanssa. Juhlauhrini rasvaa älköön jääkö yön yli seuraavaan aamuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Parhaat maasi ensisadosta tuo Herran, Jumalasi, huoneeseen. Älä keitä kiliä emänsä maidossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Katso, minä lähetän Enkelin edelläsi varjelemaan sinua tiellä ja johdattamaan sinut siihen paikkaan, jonka olen valmistanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Ole varuillasi hänen edessään ja kuule häntä äläkä pahoita hänen mieltään. Hän ei jätä teidän rikoksianne rankaisematta, sillä minun nimeni on hänessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Mutta jos sinä kuulet häntä ja teet kaikki, mitä minä käsken, niin minä olen vihollistesi vihollinen ja vastustajiesi vastustaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Sillä Enkelini käy edelläsi ja johdattaa sinut amorilaisten, heettiläisten, perissiläisten, kanaanilaisten, hivviläisten ja jebusilaisten maahan, ja minä hävitän heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Älä kumarra heidän jumaliaan, älä palvele niitä äläkä tee, kuten he tekevät, vaan kukista ne maahan ja murskaa niiden patsaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Palvelkaa Herraa, Jumalaanne, niin hän siunaa ruokasi ja juomasi, ja minä pidän puutteen sinusta kaukana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Maassasi ei ole oleva sitä, jolle on tapahtunut keskenmeno, eikä hedelmätöntä. Päiviesi luvun minä teen täydeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Minä lähetän kauhuni edelläsi ja saatan hämminkiin kaikki kansat, joiden luo sinä tulet, ja ajan kaikki vihollisesi pakoon edestäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Minä lähetän herhiläisiä edelläsi karkottamaan hivviläiset, kanaanilaiset ja heettiläiset tieltäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Mutta minä en karkota heitä tieltäsi yhtenä vuotena, ettei maa tulisi autioksi eivätkä metsän pedot lisääntyisi vahingoksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Vähitellen minä karkotan heidät tieltäsi, kunnes olet tullut kyllin lukuisaksi ottamaan maan haltuusi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Minä asetan rajasi Kaislamerestä filistealaisten mereen ja erämaasta Eufrat-virtaan asti. Minä nimittäin annan maan asukkaat valtaanne, ja sinä karkotat heidät tieltäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Älä tee liittoa heidän äläkä heidän jumaliensa kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Älkööt he jääkö asumaan maahasi, etteivät saattaisi sinua tekemään syntiä minua vastaan. Sillä jos sinä palvelet heidän jumaliaan, se on sinulle ansaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Sitten hän sanoi Moosekselle: \"Nouse Herran luo, sinä ja Aaron, Naadab ja Abihu sekä seitsemänkymmentä Israelin vanhinta, ja kumartukaa ja rukoilkaa taaempana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Lähestyköön Mooses yksin Herraa. Muut älkööt lähestykö, ja kansa älköön nousko sinne hänen kanssaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Mooses tuli ja kertoi kansalle kaikki Herran sanat ja kaikki hänen säädöksensä. Niin koko kansa vastasi yhteen ääneen ja sanoi: \"Kaikkia sanoja, jotka Herra on puhunut, me noudatamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Mooses kirjoitti kaikki Herran sanat. Hän nousi varhain seuraavana aamuna ja rakensi alttarin vuoren juurelle sekä pystytti kaksitoista patsasta Israelin kahdentoista sukukunnan mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Hän lähetti israelilaisten joukosta nuoria miehiä uhraamaan polttouhreja ja teurastamaan härkiä rauhanuhriksi Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Mooses otti verestä puolet ja pani uhrimaljoihin, ja toisen puolen hän vihmoi alttarille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Hän otti liiton kirjan ja luki sen kansan kuullen. He sanoivat: \"Kaikkea, minkä Herra on puhunut, me noudatamme ja tottelemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Mooses otti veren, vihmoi sitä kansan päälle ja sanoi: \"Katso, tämä on sen liiton veri, jonka Herra on tehnyt kanssanne kaikkien näiden sanojen perusteella.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Mooses ja Aaron, Naadab ja Abihu sekä seitsemänkymmentä Israelin vanhinta nousivat vuorelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'He näkivät Israelin Jumalan. Hänen jalkojensa alla oli alusta kuin safiirikivistä, kirkas kuin itse taivas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Eikä hän kajonnut kädellään israelilaisten päälliköihin, ja he katselivat Jumalaa, söivät ja joivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Herra sanoi Moosekselle: \"Nouse luokseni vuorelle ja ole siellä, niin annan sinulle kivitaulut sekä lain ja käskyt, jotka olen kirjoittanut heille opetukseksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Mooses ja hänen palvelijansa Joosua lähtivät, ja Mooses nousi Jumalan vuorelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Mutta vanhimmille hän sanoi: \"Odottakaa meitä täällä, kunnes palaamme luoksenne. Katso, Aaron ja Huur ovat kanssanne. Se, jolla on jotakin asiaa, kääntyköön heidän puoleensa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Kun Mooses oli noussut vuorelle, peitti pilvi vuoren.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Herran kirkkaus laskeutui Siinain vuorelle, ja pilvi peitti sen kuusi päivää. Seitsemäntenä päivänä hän huusi Moosesta pilven keskeltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Herran kirkkaus vuoren huipulla näytti israelilaisten silmissä kuluttavalta tulelta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Mooses meni pilven keskelle ja nousi vuorelle. Mooses oli vuorella neljäkymmentä päivää ja neljäkymmentä yötä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, '\"Sano israelilaisille, että he kokoavat anteja minulle. Ottakaa vastaan anti minulle jokaiselta, jonka sydän on siihen altis.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Nämä ovat ne annit, joita teidän on otettava heiltä vastaan: kultaa, hopeaa ja vaskea,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'sinipunaisia, purppuranpunaisia ja karmiininpunaisia lankoja ja valkoisia pellavalankoja sekä vuohenkarvoja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'punaisia pässin nahkoja, tahašin nahkoja, akasiapuuta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'öljyä seitsenhaaraista lamppua varten, tuoksuvia voiteita öljyä ja suitsuketta varten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'onykskiviä ja muita jalokiviä kasukkaa ja rintakilpeä varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Tehkööt minulle pyhäkön asuakseni heidän keskellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Tehkää asumus ja kaikki sen kalusto tarkasti sen kaavan mukaan, jonka sinulle näytän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Tehkööt arkin akasiapuusta, kaksi ja puoli kyynärää pitkän, puolitoista kyynärää leveän ja puolitoista kyynärää korkean.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Päällystä se puhtaalla kullalla, päällystä se sisältä ja ulkoa. Tee siihen kultareunus yltympäri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Vala siihen neljä kultarengasta ja kiinnitä ne sen neljään jalkaan, niin että kaksi rengasta tulee toiselle puolelle ja kaksi rengasta toiselle puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Tee korennot akasiapuusta ja päällystä ne kullalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Pistä renkaisiin arkin sivuille korennot, joilla arkkia on kannettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Korennot jääkööt arkin renkaisiin, älköönkä niitä vedettäkö pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Pane arkkiin laki, jonka sinulle annan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Tee myös armoistuin puhtaasta kullasta, kaksi ja puoli kyynärää pitkä ja puolitoista kyynärää leveä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Tee kaksi kultakerubia. Tee ne takomalla armoistuimen molempiin päihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Tee toinen kerubi toiseen päähän ja toinen kerubi toiseen päähän. Tehkää kerubit armoistuimesta kohoaviksi, sen kumpaankin päähän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Kerubit levittäkööt siipensä ylöspäin, niin että ne peittävät siivillään armoistuimen. Niiden kasvot olkoot vastakkain. Kerubien kasvot olkoot käännetyt armoistuinta kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Aseta armoistuin arkin päälle ja pane arkkiin laki, jonka sinulle annan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Siinä ilmestyn sinulle ja puhun sinulle armoistuimelta niiden kahden kerubin välistä, jotka ovat lain arkin päällä, kaiken sen, minkä sinun kauttasi israelilaisille säädän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Tee pöytä akasiapuusta, kahden kyynärän pituinen, kyynärän levyinen ja puolentoista kyynärän korkuinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Päällystä se puhtaalla kullalla ja tee siihen kultareunus yltympäri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Tee sen ympäri kämmenen korkuinen lista ja listan ympäri kultareunus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Tee siihen neljä kultarengasta ja kiinnitä renkaat sen neljään kulmaan kunkin neljän jalan kohdalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Renkaat olkoot juuri listan alla niiden korentojen pitiminä, joilla pöytää on kannettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Tee korennot akasiapuusta ja päällystä ne kullalla. Niillä on pöytää kannettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Tee myös siihen vadit ja kupit, kannut ja maljat, joista juomauhrit vuodatetaan. Tee ne puhtaasta kullasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Pidä aina minun edessäni pöydällä näkyleivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Tee myös seitsenhaarainen lamppu puhtaasta kullasta. Tee lamppu jalkoineen ja varsineen taottua tekoa. Sen kukkakuvut ja nuput kukkalehtineen olkoot samaa kappaletta kuin se.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Kuusi haaraa lähteköön lampun sivuista, kolme haaraa toisesta sivusta ja kolme haaraa toisesta sivusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Toisessa haarassa olkoon kolme mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen, ja toisessa haarassa samoin kolme mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen. Näin olkoon jokaisessa kuudessa haarassa, jotka lampusta lähtevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Mutta lampussa itsessään olkoon neljä mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Yksi nuppu olkoon aina jokaisen haaraparin alla niistä kuudesta haarasta, jotka lampusta lähtevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Nuput ja haarat olkoot samaa kappaletta kuin se. Olkoon se kauttaaltaan samaa taottua tekoa, puhdasta kultaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Tee siihen seitsemän lamppua, ja lamput asetettakoon niin, että seitsenhaarainen lamppu antaa valonsa etupuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Sen lamppusakset ja karstakupit olkoot puhdasta kultaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Yhdestä talentista puhdasta kultaa tehtäköön sekä se että kaikki nämä esineet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Katso, että teet ne sen kaavan mukaan, joka sinulle niistä vuorella näytettiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, '\"Tee asumus kymmenestä telttakankaan kaistasta, jotka ovat valmistetut kerratuista valkoisista pellavalangoista ja sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista, ja tee niihin taidokkaasti kudottuja kerubeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Kunkin kaistan pituus olkoon kaksikymmentä kahdeksan kyynärää ja leveys neljä kyynärää. Kaikilla kaistoilla olkoon sama mitta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Viisi kaistaa yhdistettäköön toisiinsa, ja samoin toiset viisi kaistaa yhdistettäköön toisiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Tee silmukat sinipunaisesta langasta ensimmäisen kaistan reunaan yhdistetyn kappaleen laitaan, ja samoin toisen yhdistetyn kappaleen viimeisen kaistan reunaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Tee viisikymmentä silmukkaa ensimmäiseen kaistaan ja tee viisikymmentä silmukkaa vastaavan kaistan laitaan toiseen yhdistettyyn kappaleeseen, niin että silmukat ovat kohdakkain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Tee viisikymmentä kultahakasta ja yhdistä kaistat toisiinsa näillä hakasilla, niin että siitä tulee yhtenäinen asumus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Tee vielä vuohenkarvoista kudotuista kaistoista teltta asumuksen suojaksi. Tee niitä kaistoja yksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Kunkin kaistan pituus olkoon kolmekymmentä kyynärää ja leveys neljä kyynärää. Niillä yhdellätoista kaistalla olkoon sama mitta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Liitä yhteen viisi kaistaa erikseen ja kuusi kaistaa erikseen, ja aseta kuudes niistä kaksin kerroin teltan etupuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Tee viisikymmentä silmukkaa toisen yhdistetyn kappaleen viimeisen kaistan reunaan ja viisikymmentä silmukkaa toisen yhdistetyn kappaleen vastaavan kaistan reunaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Tee myös viisikymmentä vaskihakasta ja pistä hakaset silmukoihin ja liitä teltta yhteen, niin että siitä tulee yhtenäinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Siitä telttakaistojen liiasta osasta, joka jää riippumaan, jääköön puolet riippumaan asumuksen takasivulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Siitä, mikä telttakaistoissa on liikaa pituutta, riippukoon kyynärän verran asumuksen kummallakin sivulla sitä peittämässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Tee teltalle peite punaisista pässin nahoista ja sen päälle vielä toinen peite tahašin nahoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Asumuksen laudat tee akasiapuusta pystyyn asetettaviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Jokainen lauta olkoon kymmenen kyynärää pitkä ja puolitoista kyynärää leveä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Jokaisessa laudassa olkoon kaksi tappia, jotka ovat poikkilistalla yhdistetyt keskenään. Tee näin kaikki asumuksen laudat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Asumuksen lautoja tee kaksikymmentä lautaa eteläpuolta varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Tee neljäkymmentä hopeajalustaa kahdenkymmenen laudan alle, aina kaksi jalustaa kunkin laudan alle sen kahta tappia varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Samoin asumuksen toista sivua, pohjoispuolta, varten kaksikymmentä lautaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'ja neljäkymmentä hopeajalustaa, aina kaksi jalustaa kunkin laudan alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Asumuksen takasivua, sen länsipuolta varten tee kuusi lautaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Tee kaksi lautaa asumuksen peränurkkia varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Ne olkoot yhteen liitettyjä kaksoislautoja ja alhaalta alkaen kiinni toisissaan ylös saakka, ensimmäiseen renkaaseen asti. Näin tehtäköön ne molemmat ja asetettakoon kumpaankin nurkkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Siten tulee olemaan yhteensä kahdeksan lautaa ja niihin kuusitoista hopeajalustaa, aina kaksi jalustaa kunkin laudan alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Tee myös viisi poikkitankoa akasiasta asumuksen toisen sivun lautoja varten');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'ja viisi poikkitankoa asumuksen toisen sivun lautoja varten sekä viisi poikkitankoa asumuksen takasivun, länsipuolen, lautoja varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Keskimmäinen poikkitanko asetettakoon keskelle lautoja. Kulkekoon se reunasta reunaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Päällystä laudat kullalla ja tee kullasta niiden renkaat poikkitankojen pitimiksi ja päällystä poikkitangot kullalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Aseta asumus pystyyn sen muotoiseksi, kuin sinulle vuorella näytettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Tee vielä esirippu sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista ja kerratuista valkoisista pellavalangoista, ja tehtäköön siihen taidokkaasti kudottuja kerubeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Ripusta se neljään akasiapuiseen kullalla päällystettyyn pylvääseen, joissa on kultakoukut ja jotka seisovat neljällä hopeajalustalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Ripusta esirippu hakasten alle ja vie sinne esiripun sisäpuolelle lain arkki. Olkoon esirippu teille väliseinänä pyhän ja kaikkeinpyhimmän välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Aseta armoistuin todistusten arkin päälle, joka on kaikkeinpyhimmässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Mutta pöytä sijoita esiripun ulkopuolelle ja seitsenhaarainen lamppu vastapäätä pöytää, asumuksen eteläsivulle. Aseta siis pöytä pohjoissivulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Tee myös teltan oveen verho, kirjaillen kudottu sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista ja kerratuista valkoisista pellavalangoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Tee verhoa varten viisi pylvästä akasiapuusta ja päällystä ne kullalla, mutta niiden koukut olkoot kultaa, ja vala niille viisi vaskijalustaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, '\"Tee alttari akasiapuusta. Se olkoon neliskulmainen, viisi kyynärää pitkä ja viisi kyynärää leveä sekä kolme kyynärää korkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Tee sarvet sen neljään kulmaan, niin että sarvet ovat samaa kappaletta kuin se. Päällystä se vaskella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Tee siihen kuuluvat kattilat tuhkan pois viemistä varten sekä lapiot, maljat, haarukat ja hiilipannut. Tee kaikki sen kalusto vaskesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Tee siihen myös verkonkaltainen ristikkokehys vaskesta ja tee verkkoon ristikon neljään kulmaan neljä vaskirengasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Aseta se alttarin välireunuksen alle maahan kiinni, niin että verkko ulottuu puoliväliin alttaria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Tee alttariin korennot akasiapuusta ja päällystä ne vaskella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Korennot pistettäköön renkaisiin, niin että korennot ovat molemmilla puolilla alttaria sitä kannettaessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Tee se laudoista ontoksi. Kuten sinulle näytettiin vuorella, niin se tehtäköön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Tee myös asumukselle esipiha. Etelän puolella esipihan ympärysverhot olkoot kerratuista valkoisista pellavalangoista ja sadan kyynärän pituisia tätä yhtä sivua varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Olkoon niiden pylväitä kaksikymmentä ja näiden vaskijalustoja kaksikymmentä, mutta pylväiden koukut ja niiden koristepienat olkoot hopeaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Samoin myös pohjoisen puolen ympärysverhot olkoot sata kyynärää pitkiä, ja olkoon niiden pylväitä kaksikymmentä ja näiden vaskijalustoja kaksikymmentä. Pylväiden koukut ja niiden koristepienat olkoot hopeaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Esipihan länsisivustalla olkoot ympärysverhot viidenkymmenen kyynärän pituisia, ja olkoon niiden pylväitä kymmenen ja näiden jalustoja kymmenen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Esipihan leveys etupuolella itään päin olkoon viisikymmentä kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Ympärysverhot portin toisella puolella olkoot viisitoista kyynärää pitkiä, ja olkoon niiden pylväitä kolme ja näiden jalustoja kolme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Samoin olkoot ympärysverhot toisella puolella viisitoista kyynärää pitkiä, ja olkoon niiden pylväitä kolme ja näiden jalustoja kolme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Esipihan portissa olkoon kahdenkymmenen kyynärän pituinen verho kirjaillen kudottu sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista ja kerratuista valkoisista pellavalangoista, ja olkoon sen pylväitä neljä ja näiden jalustoja neljä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Kaikissa pylväissä esipihan ympärillä olkoot koristepienat hopeaa ja koukut hopeaa, mutta jalustat vaskea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Esipihan pituus olkoon sata kyynärää ja leveys viisikymmentä kyynärää. Ympärysverho olkoon viisi kyynärää korkea ja kudottu kerratuista valkoisista pellavalangoista, ja jalustat olkoot vaskea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Koko asumuksen kalusto kaikkia siinä tehtäviä töitä varten, samoin kuin kaikki sen vaarnat ja kaikki esipihan vaarnat olkoot vaskea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Käske israelilaisten tuoda sinulle puhdasta, survomalla saatua öljypuun öljyä seitsenhaaraista lamppua varten, että lamput aina voidaan nostaa paikoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Ilmestysmajassa, ulkopuolella esiripun, joka on todistusten [arkin] edessä, hoitakoon Aaron poikineen niitä illasta aamuun asti Herran edessä. Tämä olkoon ikuinen säädös, jota israelilaiset noudattakoot sukupolvesta sukupolveen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, '\"Kutsu luoksesi israelilaisten joukosta veljesi Aaron poikineen, että he pappeina palvelisivat minua: Aaron ja hänen poikansa Naadab ja Abihu, Eleasar ja Iitamar.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Teetä veljellesi Aaronille pyhät vaatteet kunniaksi ja kaunistukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Mutta sinä, puhuttele kaikkia taitavia miehiä, jotka olen täyttänyt taitavuuden Hengellä, että he tekevät vaatteet Aaronille, jotta hänet pyhitettäisiin pappina palvelemaan minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Nämä ovat ne vaatteet, jotka heidän on tehtävä: rintakilpi, kasukka, viitta, ruudullinen paita, turbaani ja vyö. He tehkööt veljellesi Aaronille ja hänen pojilleen pyhät vaatteet, että he pappeina palvelisivat minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'He ottakoot tätä varten kultaa sekä sinipunaisia, purppuranpunaisia ja karmiininpunaisia lankoja ja valkoisia pellavalankoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Kasukan he tehkööt kullasta sekä sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista ja kerratuista valkoisista pellavalangoista, taitavasti kutomalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Siinä olkoon kaksi yhdistettävää olkakappaletta, ja se kiinnitettäköön niihin molemmista päistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Vyö, jolla kasukka kiinnitetään, olkoon tehty samalla tavalla ja samasta kappaleesta kuin se: kullasta sekä sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista ja kerratuista valkoisista pellavalangoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Ota sitten kaksi onyks-kiveä ja kaiverra niihin Israelin poikien nimet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'kuusi heidän nimeään toiseen kiveen ja toiset kuusi nimeä toiseen kiveen siinä järjestyksessä, kuin he ovat syntyneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Kuten taidokkaasti hiotaan kiveä ja kaiverretaan sinettisormuksia, kaiverra Israelin poikien nimet niihin kahteen kiveen. Kehystettäköön ne kultapunoksilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Pane molemmat kivet kasukan olkakappaleisiin kiviksi, jotka johdattavat muistoon israelilaiset. Näin Aaron kantakoon heidän nimiään molemmilla olkapäillään Herran kasvojen edessä, että heitä muistettaisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Tee kultapunokset');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'ja kahdet ketjut puhtaasta kullasta. Tee ne punomalla, kuten punosta tehdään, ja kiinnitä punotut ketjut punoksiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, '[Jumalan] ratkaisun rintakilpi tee taidokkaasti kutomalla. Tee sekin samalla tavalla, kuin kasukka on tehty: tee se kullasta sekä sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista ja kerratuista valkoisista pellavalangoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Se olkoon neliskulmainen ja taskun muotoon tehty, vaaksan pituinen ja vaaksan levyinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Kiinnitä sen pintaan kiviä joka puolelle, neljään riviin: ensimmäiseen riviin karneoli, topaasi ja smaragdi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'toiseen riviin rubiini, safiiri ja jaspis;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'kolmanteen riviin hyasintti, akaatti ja ametisti;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'ja neljänteen riviin krysoliitti, onyks ja berylli. Kultapunoksilla kehystettyinä kiinnitettäköön ne paikalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Kiviä olkoon Israelin poikien nimien mukaan kaksitoista, yksi kutakin nimeä kohti. Kussakin kivessä olkoon yksi kahdentoista sukukunnan nimistä, kaiverrettuna samalla tavalla, kuin kaiverretaan sinettisormuksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Tee rintakilpeen puhtaasta kullasta ketjut, punotut, niin kuin punonnaista tehdään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Tee rintakilpeen kaksi kultarengasta ja kiinnitä molemmat renkaat rintakilven kahteen yläkulmaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Kiinnitä ne molemmat kultapunonnaiset kahteen renkaaseen rintakilven yläkulmiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Kiinnitä molempien punonnaisten toiset kaksi päätä kahteen palmikkoon ja kiinnitä nämä kasukan olkakappaleisiin, sen etupuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Tee vielä kaksi kultarengasta ja pane ne rintakilven molempiin alakulmiin, sen sisäpuoliseen, kasukkaa vasten olevaan reunaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Tee lisäksi kaksi kultarengasta ja kiinnitä ne kasukan molempiin olkakappaleisiin, niiden alareunaan, etupuolelle sauman kohdalle, kasukan vyön yläpuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Rintakilpi solmittakoon renkaistaan sinipunaisella nauhalla kasukan renkaisiin, niin että se on kasukan vyön yläpuolella. Näin rintakilpi ei irtoa kasukasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Aaron kantakoon [Jumalan] ratkaisun rintakilvessä sydämensä päällä Israelin poikien nimiä astuessaan pyhäkköön, että heidät alati johdatettaisiin muistoon Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Pane jumalanvastausten rintakilpeen uurim ja tummim, niin että ne ovat Aaronin sydämen päällä, hänen astuessaan Herran eteen. Kantakoon Aaron Jumalan ratkaisun israelilaisille sydämensä päällä aina Herran edessä ollessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Kasukan viitta tee kokonaan sinipunaisista langoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Sen keskellä olkoon pääntie, ja tämä pääntie ympäröitäköön kudotulla päärmeellä niin kuin haarniskan aukko, ettei se repeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Tee sen helmaan granaattiomenia sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista, ja kiinnitä ne helmaan ympäriinsä ja niiden väliin kultatiukuja yltympäri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Kiinnitä vuorotellen kultatiuku ja granaattiomena viitan helmaan ympäriinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Aaron pitäköön sitä yllään toimittaessaan virkaansa, niin että kuuluu, kun hän menee pyhäkköön Herran eteen ja tulee sieltä ulos, ettei hän kuolisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Tee myös otsakoriste puhtaasta kullasta ja kaiverra siihen, kuten sinettisormusta kaiverretaan, sanat: \' Herralle pyhitetty.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Sido se sinipunaisella nauhalla, niin että se on kiinni turbaanissa. Olkoon se turbaanin etupuolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Se olkoon Aaronin otsalla, niin että Aaron kantaa kaiken sen, mitä israelilaiset rikkovat uhratessaan pyhiä uhrejaan ja antaessaan pyhiä lahjojaan. Se olkoon aina hänen otsallaan, jotta Herran mielisuosio tulisi heidän osakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Kudo myös ruudullinen paita valkoisista pellavalangoista. Tee turbaani valkoisista pellavalangoista, ja tee vyö kirjokudoksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Aaronin pojille tee paidat ja vyöt. Tee heille myös päähineet kunniaksi ja kaunistukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Pue ne veljesi Aaronin ja hänen poikiensa päälle. Voitele heidät ja vihi heidät virkaansa ja pyhitä heidät pappeina palvelemaan minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Tee heille pellavahousut hävyn peitteeksi. Ulottukoot ne lanteilta reisiin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Aaron ja hänen poikansa pitäkööt ne yllään mennessään ilmestysmajaan tai lähestyessään alttaria tehdäkseen palvelusta pyhäkössä, etteivät joutuisi syynalaisiksi ja kuolisi. Tämä olkoon ikuinen säädös hänelle ja hänen jälkeläisilleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, '\"Pyhittääksesi heidät pappeina palvelemaan minua tee heille näin: Ota mulli ja kaksi virheetöntä pässiä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'ja happamatonta leipää ja öljyyn leivottuja happamattomia leipäkakkuja ja öljyllä voideltuja happamattomia ohuita leipiä. Leivo ne ydinvehnäjauhoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Pane ne samaan koriin ja tuo ne korissa, samalla kertaa kuin tuot mullin ja kaksi pässiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Tuo sitten Aaron poikineen ilmestysmajan ovelle ja pese heidät vedellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Ota vaatteet ja pue Aaronin ylle paita ja kasukan viitta ja kasukka ja rintakilpi. Sido sitten hänen ympärilleen kasukan vyö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Pane myös turbaani hänen päähänsä ja kiinnitä pyhä kruunu turbaaniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Ota voiteluöljyä ja vuodata sitä hänen päähänsä ja voitele hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Tuo hänen poikansa esille ja pue heidän ylleen paidat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Vyötä heidät vyöllä, sekä Aaron että hänen poikansa, ja sido päähineet heidän päähänsä, että pappeus olisi heille ikuisena säätynä. Vihi näin virkaansa Aaron ja hänen poikansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Tuo mulli ilmestysmajan eteen, ja Aaron poikineen laskekoon kätensä mullin pään päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Teurasta sitten mulli Herran edessä ilmestysmajan ovella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Ota mullin verta ja sivele sitä sormellasi alttarin sarviin, mutta kaikki muu veri vuodata alttarin juurelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Ota kaikki sisälmyksiä peittävä rasva ja maksan takalohko ja molemmat munuaiset sekä niiden päällä oleva rasva, ja polta ne alttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Mutta mullin liha, nahka ja ruokasula polta tulella leirin ulkopuolella. Se on syntiuhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Ota toinen pässeistä, ja Aaron poikineen laskekoon kätensä pässin pään päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Teurasta sitten pässi ja ota sen veri ja vihmo se alttarille ympäriinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Leikkele pässi määräkappaleiksi ja pese sen sisälmykset ja jalat ja pane ne kappaleiden ja pään päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Polta koko pässi alttarilla. Se on polttouhri Herralle. Se on suloisesti tuoksuva uhri Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Ota sitten toinen pässi, ja Aaron poikineen laskekoon kätensä pässin pään päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Teurasta pässi ja ota sen verta ja sivele Aaronin ja hänen poikiensa oikean korvan lehteen ja oikean käden peukaloon ja heidän oikean jalkansa isoonvarpaaseen, mutta vihmo muu veri alttarille ympäriinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Ota alttarilla olevaa verta ja voiteluöljyä ja pirskota Aaronin ja hänen vaatteittensa päälle, ja samoin hänen poikiensa ja heidän vaatteittensa päälle. Näin hän tulee pyhäkölle pyhitetyksi, sekä hän itse että hänen vaatteensa, ja samoin hänen poikansa ja hänen poikiensa vaatteet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Ota sitten pässistä rasva ja rasvahäntä ja sisälmyksiä peittävä rasva ja maksan takalohko ja molemmat munuaiset sekä niiden päällä oleva rasva ja oikea reisi, sillä tämä on vihkiäispässi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Ota pyöreä leipä ja öljyyn leivottu leipäkakku ja ohut leipä happamattomien leipien korista, joka on Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Pane sitten kaikki nämä Aaronin käsiin ja hänen poikiensa käsiin, että toimitettaisiin niiden heilutus Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Ota ne sitten heidän käsistään ja polta alttarilla, polttouhrin päällä, suloiseksi tuoksuksi Herran edessä. Se on Herran uhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Ota rintaliha Aaronin vihkiäispässistä ja toimita sen heilutus Herran edessä. Se olkoon sinun osasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Näin sinun on pyhitettävä heilutettu rintaliha ja anniksi annettu reisi, se, mitä on heilutettu ja anniksi annettu Aaronin ja hänen poikiensa vihkiäispässistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Ne olkoot Aaronin ja hänen poikiensa ikuinen osuus, israelilaisilta saatu, sillä se on anti. Se olkoon israelilaisten anti heidän rauhanuhreistaan, heidän antinsa Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Aaronin pyhät vaatteet tulkoot hänen pojilleen hänen jälkeensä, että heidät niissä voideltaisiin ja vihittäisiin virkaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Seitsemänä päivänä on sen hänen pojistaan, joka tulee papiksi hänen tilalleen, puettava ne ylleen, kun hän menee ilmestysmajaan toimittamaan virkaansa pyhäkössä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Ota vihkiäispässi ja keitä sen liha pyhässä paikassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Aaron poikineen syököön ilmestysmajan ovella pässin lihan sekä leivän, joka on korissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'He syökööt sen, mitä käytettiin heidän sovittamisekseen, kun heidät vihittiin virkaansa ja pyhitettiin, mutta ulkopuolinen älköön sitä syökö, sillä se on pyhää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Jos jotakin jää tähteeksi vihkiäislihasta tai leivästä seuraavaan aamuun, polta tähteeksi jäänyt tulessa. Älköön sitä syötäkö, sillä se on pyhää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Tee näin Aaronille ja hänen pojilleen, aivan kuten olen sinua käskenyt. Seitsemän päivää kestäköön heidän vihkimisensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Uhraa joka päivä syntiuhrimulli sovitukseksi, ja puhdista alttari toimittamalla sen sovitus ja voitele se pyhittääksesi sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Seitsemänä päivänä toimita alttarin sovitus ja pyhitä se. Näin tulee alttarista korkeasti pyhä. Jokainen, joka alttariin koskee, on pyhäkölle pyhitetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Uhraa alttarilla tämä: kaksi vuoden vanhaa karitsaa joka päivä, ainiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Uhraa toinen karitsa aamulla ja toinen karitsa iltahämärässä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'ja kumpaakin karitsaa kohti kymmenesosa [eefaa] ydinjauhoja, sekoitettuna neljännekseen hiin-mittaa survomalla saatua öljyä, ja juomauhriksi neljännes hiin-mittaa viiniä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Uhraa toinen karitsa iltahämärässä. Uhrattakoon se toimittamalla samankaltainen ruokauhri ja juomauhri kuin aamullakin, suloisesti tuoksuvaksi uhriksi Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Tämä olkoon teillä jokapäiväinen polttouhri sukupolvesta sukupolveen ilmestysmajan ovella Herran edessä, jossa ilmestyn teille puhuakseni kanssasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Siinä ilmestyn israelilaisille, ja se on oleva kirkkauteni pyhittämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Pyhitän ilmestysmajan ja alttarin, ja pyhitän Aaronin poikineen pappeina palvelemaan minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Asun israelilaisten keskellä ja olen heidän Jumalansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'He tulevat tietämään, että minä olen Herra, heidän Jumalansa, joka vein heidät pois Egyptin maasta asuakseni heidän keskellään. Minä olen Herra, heidän Jumalansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, '\"Tee myös alttari suitsutuksen polttamista varten. Tee se akasiapuusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Olkoon se kyynärän pituinen ja kyynärän levyinen, siis neliskulmainen, ja kaksi kyynärää korkea. Sen sarvet olkoot samaa kappaletta kuin se itsekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Päällystä se puhtaalla kullalla, sekä sen levy että sivut ympäriinsä ja sen sarvet, ja tee kultareunus sen ympäri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Tee siihen kaksi kultarengasta. Pane ne reunuksen alle, kummallekin sivulle, molempiin sivukappaleisiin. Ne olkoot niiden korentojen pitiminä, joilla alttaria on kannettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Tee korennotkin akasiapuusta ja päällystä ne kullalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Aseta se todistuksen arkin edessä olevan esiripun eteen, niin että se tulee armoistuimen kohdalle, joka on todistuksen arkin päällä ja jossa minä sinulle ilmestyn.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Aaron polttakoon sen päällä hyvänhajuista suitsutusta. Hän polttakoon sitä joka aamu pannessaan lamput kuntoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Samoin Aaron polttakoon sitä myös iltahämärässä, kun hän nostaa lamput paikoilleen. Tämä olkoon teillä jokapäiväinen suitsutusuhri Herran edessä sukupolvesta sukupolveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Älkää uhratko sen päällä vierasta suitsutusta älkääkä polttouhria tai ruokauhria. Älkää myöskään vuodattako juomauhria sen päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Aaron toimittakoon kerran vuodessa sen sarvien sovituksen. Sovitukseksi uhratun syntiuhrin verellä hän toimittakoon kerran vuodessa sen sovituksen sukupolvesta sukupolveen. Se on korkeasti pyhä Herralle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Sitten Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, '\"Kun sinä lasket israelilaisten lukumäärän – niiden, joiden on oltava katselmuksessa – niin jokainen heistä suorittakoon, kun pidetään heistä katselmusta, hengestään sovitusmaksun Herralle, ettei mikään rangaistus kohtaisi heitä heistä katselmusta pidettäessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Jokainen katselmuksessa oleva antakoon puoli sekeliä pyhäkkösekelin painon mukaan, kaksikymmentä geeraa laskettuna sekeliin. Puoli sekeliä olkoon anti Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Kaikki katselmuksessa olevat, kaksikymmentävuotiaat ja sitä vanhemmat, antakoot tämän annin Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Rikas älköön antako enempää älköönkä köyhä vähempää kuin puoli sekeliä antina Herralle maksaaksenne sovituksen hengestänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Ota sovitusrahat israelilaisilta ja käytä ne palvelukseen ilmestysmajassa, että israelilaiset johdatettaisiin muistoon Herran edessä henkenne sovitukseksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, '\"Tee myös vaskiallas vaskijalustoineen peseytymistä varten ja aseta se ilmestysmajan ja alttarin välille ja kaada siihen vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Aaron ja hänen poikansa peskööt siinä kätensä ja jalkansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Kun he menevät ilmestysmajaan, peseytykööt vedessä, etteivät kuolisi. Samoin myös, kun he lähestyvät alttaria ja käyvät toimittamaan virkaansa polttamalla uhrin Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Peskööt kätensä ja jalkansa, etteivät kuolisi. Tämä olkoon heille ikuinen säädös, hänelle itselleen ja hänen jälkeläisilleen sukupolvesta sukupolveen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, '\"Ota itsellesi hajusteita parasta lajia: sulavaa mirhaa viisisataa sekeliä, hyvälle tuoksuvaa kanelia puolet siitä eli kaksisataa viisikymmentä sekeliä ja hyvälle tuoksuvaa kalmoruokoa samoin kaksisataa viisikymmentä sekeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'Ota sitten vielä kassiaa viisisataa sekeliä pyhäkkösekelin painon mukaan, ja hiin-mitta oliiviöljyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Tee siitä pyhä voiteluöljy, voidesekoitus, jollaista voiteensekoittaja valmistaa. Se olkoon pyhä voiteluöljy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Voitele sillä ilmestysmaja, lain arkki');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'ja pöytä kaikkine esineineen, seitsenhaarainen lamppu varusteineen, niin myös suitsutusalttari,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'polttouhrialttari kaikkine varusteineen sekä allas jalustoineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Pyhitä ne, niin että ne tulevat korkeasti pyhiksi. Jokainen, joka niihin koskee, tulee pyhäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Voitele myös Aaron ja hänen poikansa ja pyhitä heidät pappeina palvelemaan minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Puhu myös israelilaisille ja sano: Tämä olkoon teillä minun pyhä voiteluöljyni sukupolvesta sukupolveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Kenenkään muun ihmisen ruumiille älköön sitä vuodatettako, älkääkä jäljitelkö sen sekoitusta. Pyhä se on, ja pyhänä se pitäkää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Jokainen, joka valmistaa sellaisen voiteen, ja jokainen, joka sivelee sitä ulkopuoliseen, hävitettäköön kansastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Herra sanoi vielä Moosekselle: \"Ota itsellesi hyvälle tuoksuvia aineita, mirhaa, simpukankuorta, tuoksuvaa kumia, näitä hyvälle tuoksuvia aineita, ja puhdasta suitsuketta, yhtä paljon kutakin lajia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Tee niistä suitsutus, voidesekoitus, jollaista voiteensekoittaja valmistaa, suolansekainen, puhdas ja pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Hienonna osa siitä jauhoksi ja pane sitä todistuksen arkin eteen ilmestysmajaan, jossa minä ilmestyn sinulle. Pitäkää se korkeasti pyhänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Älkää valmistako itsellenne mitään muuta suitsutusta tämän sekoituksen mukaan. Pidä tämä Herralle pyhitettynä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Jokainen, joka sellaista tekee nauttiakseen sen tuoksusta, hävitettäköön kansastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, '\"Katso, olen kutsunut nimeltä Besalelin, Uurin pojan, Huurin pojanpojan, Juudan sukukunnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'Olen täyttänyt hänet Jumalan Hengellä, taidolla, ymmärryksellä, tiedolla ja kaikella kätevyydellä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'sommittelemaan taidokkaita teoksia ja valmistamaan niitä kullasta, hopeasta ja vaskesta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'hiomaan ja kiinnittämään kiviä ja veistämään puuta, tekemään kaikkia töitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Katso, minä olen antanut hänelle apulaiseksi Oholiabin, Ahisamakin pojan, Daanin sukukunnasta, ja olen antanut kaikkien taitavien sydämeen taidon tehdä kaikkea, mitä olen sinulle käskenyt:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'ilmestysmajan, todistuksen arkin, armoistuimen sen päälle, kaiken majan kaluston,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'pöydän varusteineen, seitsenhaaraisen lampun aidosta kullasta kaikkine varusteineen, suitsutusalttarin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'polttouhrialttarin kaikkine varusteineen, altaan jalustoineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'virkapuvut ja pappi Aaronin muut pyhät vaatteet sekä hänen poikiensa papinpuvut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'voiteluöljyn ja hyvälle tuoksuvan suitsukkeen pyhäkköä varten. He tehkööt kaiken niin, kuin olen sinua käskenyt heitä tekemään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, '\"Puhu sinä israelilaisille ja sano: Pitäkää sapattini, sillä se on merkkinä välillämme, minun ja teidän sukupolvesta sukupolveen tietääksenne, että minä olen Herra, joka pyhitän teidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Siis pitäkää sapatti, sillä se on teille pyhä. Sitä, joka sen rikkoo, rangaistakoon kuolemalla. Sillä kuka ikinä silloin tekee työtä, hävitettäköön kansastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Kuusi päivää tehtäköön työtä, mutta seitsemäntenä päivänä on sapatti, levon päivä, Herralle pyhitetty. Sitä, kuka ikinä tekee työtä sapatinpäivänä, rangaistakoon kuolemalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Pitäkööt israelilaiset sapatin, niin että he viettävät sapattia sukupolvesta sukupolveen ikuisena liittona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Se on oleva ikuinen merkki minun ja israelilaisten välillä. Sillä kuutena päivänä Herra teki taivaan ja maan, mutta seitsemäntenä päivänä hän lepäsi ja hengähti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Kun hän oli lakannut puhumasta Mooseksen kanssa Siinain vuorella, hän antoi hänelle kaksi todistuksen taulua, joiden kirjoitus oli Jumalan sormella kirjoitettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Mutta kun kansa näki, että Mooses viipyi eikä tullut alas vuorelta, kansa kokoontui Aaronin ympärille ja sanoi hänelle: \"Nouse, tee meille Jumala, joka käy edellämme. Sillä me emme tiedä, mitä on tapahtunut Moosekselle, tälle miehelle, joka johdatti meidät Egyptin maasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Niin Aaron sanoi heille: \"Irrottakaa kultarenkaat, jotka ovat vaimojenne, poikienne ja tyttärienne korvissa, ja tuokaa ne minulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Silloin kaikki kansa irrotti kultarenkaat, jotka heillä oli korvissaan, ja he toivat ne Aaronille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Hän otti kullan vastaan heidän käsistään, muotoili sitä piirtimellä ja teki siitä valetun vasikan. He sanoivat: \"Tämä on jumalasi, Israel, se, joka on johdattanut sinut Egyptin maasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Kun Aaron tämän näki, rakensi hän sille alttarin. Aaron julisti ja sanoi: \"Huomenna on Herran juhla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'He nousivat varhain seuraavana päivänä ja uhrasivat polttouhreja ja toivat rauhanuhreja. Kansa istui syömään ja juomaan, ja sitten he nousivat iloa pitämään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Silloin Herra sanoi Moosekselle: \"Mene, astu alas, sillä kansasi, jonka johdatit Egyptin maasta, on tehnyt turmiollisen asian.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Pian he poikkesivat siltä tieltä, jota käskin heidän kulkea. He tekivät itselleen valetun vasikan. Sitä he ovat kumartaneet, ja sille he ovat uhranneet ja sanoneet: \'Tämä on jumalasi, Israel, se, joka on johdattanut sinut Egyptin maasta.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Herra sanoi vielä Moosekselle: \"Näen, että tämä kansa on niskurikansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Anna minun olla rauhassa, että vihani leimahtaisi heitä vastaan hukuttaakseni heidät. Mutta sinusta minä teen suuren kansan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Mooses rukoili armoa Herralta, Jumalaltaan, ja sanoi: \" Herra, miksi vihasi syttyy omaa kansaasi vastaan, jonka olet vienyt pois Egyptin maasta suurella voimalla ja väkevällä kädellä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Miksi egyptiläiset saisivat sanoa: \'Heidän onnettomuudekseen hän vei heidät pois tappaakseen heidät vuorilla ja hävittääkseen heidät maan päältä\'? Käänny vihasi hehkusta ja kadu sitä turmiota, jonka aiot tuottaa kansallesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Muista palvelijoitasi Aabrahamia, Iisakia ja Israelia, joille olet itse itsesi kautta vannonut ja sanonut: \'Minä teen teidän jälkeläistenne luvun paljoksi kuin taivaan tähdet. Koko tämän maan, josta olen puhunut, minä annan jälkeläisillenne, ja he saavat sen ikiaikaiseksi perinnöksi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Niin Herra katui sitä turmiota, jonka hän oli uhannut tuottaa kansalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Mooses kääntyi ja astui alas vuorelta, ja hänen kädessään oli kaksi todistuksen taulua. Tauluihin oli kirjoitettu molemmille puolille. Niiden etu- ja takapuolelle oli kirjoitettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Taulut olivat Jumalan tekemät, ja kirjoitus oli Jumalan kirjoitusta, joka oli tauluihin kaiverrettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Kun Joosua kuuli kansan huudon sen melutessa, hän sanoi Moosekselle: \"Sotahuuto kuuluu leiristä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Mutta tämä vastasi: \"Se ei ole voittajien huutoa eikä voitettujen huutoa. Minä kuulen laulua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Kun Mooses lähestyi leiriä ja näki vasikan ja karkelon, niin hänen vihansa syttyi, ja hän heitti taulut käsistään ja murskasi ne vuoren juurella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Sen jälkeen hän otti vasikan, jonka he olivat tehneet, poltti sen tulessa ja rouhensi sen hienoksi ja hajotti veteen ja juotti sen israelilaisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Mooses sanoi Aaronille: \"Mitä tämä kansa on tehnyt sinulle, kun olet saattanut heidät näin suureen syntiin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Aaron vastasi: \"Älköön herrani viha syttykö. Sinä tiedät itse, että tämä kansa on paha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'He sanoivat minulle: \'Tee meille jumala, joka käy edellämme. Sillä emme tiedä, mitä on tapahtunut Moosekselle, miehelle, joka johdatti meidät Egyptin maasta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Sanoin heille: \'Jolla on kultaa, irrottakoon sen yltään.\' Niin he antoivat sen minulle, ja minä heitin sen tuleen, ja siitä tuli tämä vasikka.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Kun Mooses näki, että kansa oli kurittomuuden vallassa, koska Aaron oli päästänyt heidät kurittomuuden valtaan vahingoniloksi heidän vihollisilleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'niin Mooses seisahtui leirin portille ja huusi: \"Se, joka on Herran oma, tulkoon luokseni.\" Silloin kokoontuivat hänen luokseen kaikki leeviläiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Hän sanoi heille: \"Näin sanoo Herra, Israelin Jumala: \'Jokainen sitokoon miekkansa vyölleen. Menkää sitten edestakaisin leirin halki portista porttiin ja tappakaa jokainen, olkoon vaikka oma veli, ystävä tai sukulainen.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Niin leeviläiset tekivät Mooseksen käskyn mukaan. Sinä päivänä kaatui kansaa noin kolmetuhatta miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Mooses sanoi: \"Koska te nyt olette olleet omia poikianne ja veljiänne vastaan, vihkiytykää tänä päivänä Herran palvelukseen, että hän tänä päivänä antaisi siunauksen teille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Seuraavana päivänä Mooses sanoi kansalle: \"Te olette tehneet suuren synnin. Minä nousen nyt Herran luo – jos ehkä voisin sovittaa rikoksenne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Mooses palasi Herran luo ja sanoi: \"Voi, tämä kansa on tehnyt suuren synnin! He ovat tehneet itselleen jumalan kullasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Jospa nyt antaisit anteeksi heidän rikoksensa! Mutta jos et, niin pyyhi minut pois kirjastasi, johon kirjoitat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Mutta Herra vastasi Moosekselle: \"Joka on tehnyt syntiä minua vastaan, sen minä pyyhin pois kirjastani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Mene nyt ja johdata kansa siihen paikkaan, josta minä olen sinulle puhunut. Katso, enkelini kulkee edelläsi. Mutta kostoni päivänä minä kostan heille heidän rikoksensa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Herra rankaisi kansaa, koska he olivat teettäneet vasikan, jonka Aaron teki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Sitten Herra sanoi Moosekselle: \"Lähde täältä ja vaella, sinä ja kansa, jonka olet johdattanut Egyptin maasta, siihen maahan, jonka olen vannoen luvannut Aabrahamille, Iisakille ja Jaakobille, sanoen: \'Sinun jälkeläisillesi minä annan sen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Lähetän enkelin edelläsi ja karkotan pois kanaanilaiset, amorilaiset, heettiläiset, perissiläiset, hivviläiset ja jebusilaiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'että tulisit siihen maahan, joka vuotaa maitoa ja hunajaa. Sillä minä en vaella kanssasi, koska sinä olet niskurikansa, etten hukuttaisi sinua tiellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Kun kansa kuuli tämän kovan puheen, he tulivat murheellisiksi, eikä yksikään pukenut korujaan ylleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Herra sanoi Moosekselle: \"Sano israelilaisille: Te olette niskurikansa. Jos minä silmänräpäyksenkään vaeltaisin keskelläsi, minä hukuttaisin sinut. Riisu nyt korusi yltäsi tietääkseni, mitä sinulle teen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Israelilaiset riisuivat korunsa ja olivat Hoorebin vuoren luota lähtien ilman niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Mooses otti telttamajan ja pystytti sen leirin ulkopuolelle, jonkin matkan päähän leiristä, ja nimitti sen ilmestysmajaksi. Jokaisen, jolla oli kysyttävää Herralta, oli mentävä ilmestysmajalle, leirin ulkopuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Kun Mooses lähti majalle, nousi koko kansa, ja kukin asettui telttansa ovelle ja katseli Mooseksen jälkeen, kunnes hän oli mennyt majaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Aina kun Mooses meni majaan, laskeutui pilvenpatsas ja seisahtui majan ovelle, ja Herra puhutteli Moosesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Kaikki kansa näki pilvenpatsaan seisovan majan ovella. Kaikki kansa nousi, ja he kumartuivat kukin telttansa ovella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Herra puhutteli Moosesta kasvoista kasvoihin, niin kuin mies puhuttelee toista. Sitten Mooses palasi takaisin leiriin, mutta Joosua, Nuunin poika, hänen apumiehensä ja palvelijansa, ei poistunut majasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Mooses sanoi Herralle: \"Katso, sinä sanot minulle: \'Johdata tämä kansa sinne\', mutta et ole ilmoittanut minulle, kenen sinä lähetät kanssani. Kuitenkin sinä sanoit: \'Minä tunnen sinut nimeltä, ja sinä olet myös löytänyt armon silmieni edessä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Jos siis olen saanut armon silmiesi edessä, ilmoita minulle tiesi, että tulisin tuntemaan sinut ja tietäisin saaneeni armon silmiesi edessä. Katso: tämä kansa on sinun kansasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Hän sanoi: \"Pitäisikö kasvojeni kulkea kanssasi ja minun viedä sinut lepoon?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Hän vastasi hänelle: \"Jos kasvosi eivät kulje kanssamme, älä johdata meitä täältä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Sillä mistä muusta tiedetään, että olen löytänyt armon silmiesi edessä, ellei siitä, että kuljet kanssamme. Niin me, minä ja kansasi, olemme erikoisia kaikkien kansojen joukossa, jotka maan päällä ovat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Herra vastasi Moosekselle: \"Mitä sinä nyt pyydät, sen myös teen, sillä sinä olet löytänyt armon silmieni edessä, ja minä tunnen sinut nimeltä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Silloin hän sanoi: \"Anna siis minun nähdä kirkkautesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Hän vastasi: \"Minä annan kaiken hyvyyteni kulkea kasvojesi editse ja saarnaan Herran nimestä edessäsi. Olen armollinen, kenelle olen armollinen, ja armahdan, ketä armahdan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Hän sanoi vielä: \"Et voi nähdä kasvojani. Sillä ei kukaan, joka näkee minut, jää eloon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Sitten Herra sanoi: \"Katso, tässä on paikka minua lähellä. Astu tuohon kalliolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Kun kunniani kulkee ohi, asetan sinut kallionrotkoon ja peitän sinut kädelläni, kunnes olen kulkenut ohi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Kun sitten siirrän käteni pois, näet selkäpuoleni, mutta kasvojani ei voi nähdä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Herra sanoi Moosekselle: \"Veistä itsellesi kaksi kivitaulua, entisten kaltaista, niin kirjoitan tauluihin ne sanat, jotka olivat entisissä tauluissa, jotka murskasit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Ole valmis huomenaamuksi. Nouse huomenna aamulla Siinain vuorelle ja seiso siellä minua vastassa vuoren huipulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Mutta älköön kukaan nousko sinne kanssasi, älköönkä ketään näkykö koko vuorella. Lampaita ja karjaakaan älköön käykö laitumella vuoren vaiheilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Mooses veisti kaksi kivitaulua, entisten kaltaista. Varhain seuraavana aamuna Mooses nousi Siinain vuorelle, kuten Herra oli häntä käskenyt, ja otti ne kaksi kivitaulua käteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Herra astui alas pilvessä, ja seisoi siellä hänen kanssaan ja saarnasi Herran nimestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Herra kulki ohi hänen editseen ja julisti: \" Herra, Herra on laupias ja armahtavainen Jumala, pitkämielinen ja suuri armossa ja uskollisuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Hän pysyy armollisena tuhansille ja antaa anteeksi pahat teot, rikokset ja synnit, mutta ei kuitenkaan jätä rankaisematta, vaan kostaa isien pahat teot lapsille ja lasten lapsille kolmanteen ja neljänteen polveen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Mooses kumartui nopeasti maahan, rukoili ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, '\"Herra, jos olen löytänyt armon silmiesi edessä, käyköön Herra keskellämme. Sillä tämä on tosin niskurikansa, mutta anna anteeksi pahat tekomme ja syntimme ja ota meidät perintöosaksesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Hän sanoi: \"Katso, minä teen liiton, teen koko kansasi nähden ihmeellisiä tekoja, joiden kaltaisia ei ole tehty yhdessäkään maassa, ei minkään kansan keskuudessa. Koko kansa, jonka keskellä sinä olet, on näkevä Herran teot, sillä pelottavaa on, mitä minä sinulle teen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Noudata, mitä minä tänä päivänä käsken sinun noudattaa. Katso, minä karkotan tieltäsi amorilaiset, kanaanilaiset, heettiläiset, perissiläiset, hivviläiset ja jebusilaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Varo, ettet tee liittoa sen maan asukasten kanssa, johon tulet, etteivät he tulisi ansaksi teidän keskuudessanne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'vaan kukistakaa heidän alttarinsa, murskatkaa heidän patsaansa ja hakatkaa maahan heidän aserapaalunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Älä kumarra muuta jumalaa, sillä Herra on nimeltään Kiivas. Hän on kiivas Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Älä siis tee liittoa maan asukkaiden kanssa, niin ettet sinä, kun he kulkevat haureudessa jumaliensa jäljessä ja uhraavat jumalilleen ja kutsuvat sinua, söisi heidän uhristaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'ja etteivät heidän tyttärensä, kun otat heitä pojillesi vaimoiksi ja kun he kulkevat haureudessa jumaliensa perässä, viettelisi poikiasikin haureudessa kulkemaan heidän jumaliensa perässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Älä tee itsellesi valettuja jumalankuvia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Vietä happamattoman leivän juhlaa: seitsemänä päivänä syö happamatonta leipää, kuten olen sinua käskenyt, määrättynä aikana, aabib-kuussa, sillä aabib-kuussa sinä lähdit Egyptistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Kaikki, mikä avaa äidinkohdun, on minun, samoin myös kaikki karjasi urospuolet, nautojesi ja lampaittesi ensiksi synnyttämät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Mutta aasin ensiksi synnyttämä lunasta lampaalla, mutta jos et sitä lunasta, taita siltä niska. Jokainen esikoinen pojistasi lunasta. Tyhjänä älköön tultako kasvojeni eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Kuusi päivää tee työtä, mutta lepää seitsemäs päivä. Myös kyntö- ja elonleikkuuaikana sinun on levättävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Vietä viikkojuhla, kun leikkaat vehnäsi ensi sadon, ja korjuujuhla vuoden vaihteessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Kolme kertaa vuodessa kaikki miesväkesi tulkoon Herran, Herran, Israelin Jumalan, kasvojen eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Sillä minä karkotan kansat tieltäsi ja laajennan alueesi, eikä kukaan ole himoitseva maatasi, kun sinä kolme kertaa vuodessa vaellat tullaksesi Herran, Jumalasi, kasvojen eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Älä uhraa teurasuhrini verta hapanleivän kanssa. Pääsiäisjuhlan uhrista älköön jääkö mitään yli yön seuraavaan aamuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Tuo parhaat antimet maasi ensi sadosta Herran, Jumalasi, huoneeseen. Älä keitä kiliä emänsä maidossa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Herra sanoi Moosekselle: \"Kirjoita itsellesi nämä sanat, sillä näiden sanojen mukaisesti olen tehnyt liiton sinun ja Israelin kanssa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Hän oli siellä Herran luona neljäkymmentä päivää ja neljäkymmentä yötä syömättä ja juomatta. Hän kirjoitti tauluihin liiton sanat, ne kymmenen sanaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Kun Mooses astui alas Siinain vuorelta ja hänellä vuorelta alas astuessaan oli kädessään kaksi laintaulua, hän ei tiennyt, että hänen kasvojensa iho oli tullut säteileväksi hänen puhuessaan Herran kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Kun Aaron ja kaikki israelilaiset näkivät Mooseksen kasvojen ihon säteilevän, he pelkäsivät tulla hänen lähelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Mutta Mooses kutsui heitä. Aaron ja kaikki kansan päämiehet kääntyivät takaisin hänen luokseen, ja Mooses puhui heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Sitten kaikki israelilaiset lähestyivät häntä, ja hän käski heidän noudattaa kaikkea, mitä Herra oli puhunut hänelle Siinain vuorella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Kun Mooses oli lakannut puhumasta heidän kanssaan, hän pani peitteen kasvoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Mutta mennessään Herran eteen puhumaan hänelle hän poisti peitteen, siihen asti kunnes tuli ulos. Tultuaan ulos hän puhui israelilaisille, mitä hänen oli käsketty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Israelilaiset näkivät joka kerta Mooseksen kasvojen ihon säteilevän. Mooses veti peitteen kasvoilleen, siihen asti kunnes hän jälleen meni puhumaan hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Mooses kokosi koko Israelin kansan ja sanoi heille: \"Näin Herra on käskenyt teidän tehdä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Kuusi päivää tehtäköön työtä, mutta seitsemäs päivä olkoon teille pyhä sapatti, levon päivä, Herralle pyhitetty. Kuka ikinä silloin työtä tekee, surmattakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Älkää sytyttäkö tulta sapatin päivänä, missä asuttekin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Mooses sanoi koko Israelin kansalle näin: \"Näin Herra on käskenyt ja sanonut:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Ottakaa anti Herralle siitä, mitä teillä on. Jokainen, jonka sydän on siihen altis, tuokoon Herralle anniksi kultaa, hopeaa ja vaskea,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'sinipunaisia, purppuranpunaisia ja karmiininpunaisia lankoja ja valkoisia pellavalankoja sekä vuohenkarvoja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'punaisia pässin nahkoja, tahašin nahkoja, akasiapuuta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'öljyä seitsenhaaraista lamppua varten, hajuaineita voiteluöljyä ja hyvänhajuista suitsutusta varten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'onyks-kiviä ja muita jalokiviä kasukkaa ja rintakilpeä varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Kaikki taitavat keskuudessanne tulkoot ja tehkööt kaiken, mitä Herra on käskenyt:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'asumuksen telttoineen ja peitteineen, hakasineen, lautoineen, poikkitankoineen, pylväineen ja jalustoineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'arkin korentoineen, armoistuimen ja sitä verhoavan esiripun,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'pöydän korentoineen ja kaikkine varusteineen sekä näkyleivät,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'seitsenhaaraisen lampun varusteineen ja lamppuineen, öljyä seitsenhaaraista lamppua varten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'suitsutusalttarin korentoineen, voiteluöljyn ja hyvänhajuisen suitsukkeen, oviverhon asumuksen ovelle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'polttouhrialttarin vaskiristikkoineen, korentoineen ja kaikkine esineineen, altaan jalustoineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'esipihan ympärysverhot pylväineen ja jalustoineen sekä esipihan porttiin verhon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'ilmestysmajan vaarnat ja esipihan vaarnat köysineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'virkapuvut pyhäkköpalvelusta varten ja pappi Aaronin muut pyhät vaatteet sekä hänen poikiensa papinpuvut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Koko israelilaisten seurakunta meni pois Mooseksen luota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'He tulivat takaisin, jokainen, jonka sydän häntä siihen vaati, ja jokainen, jonka henki oli siihen altis, ja toivat antinsa Herralle ilmestysmajan valmistamista varten ja kaikkea siinä vietettävää jumalanpalvelusta varten ja pyhiä vaatteita varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'He tulivat, sekä miehet että naiset, jokainen, jonka sydän oli siihen altis, ja toivat solkia, korvarenkaita, sormuksia ja kaulakoristeita, kaikkia kultaesineitä – jokainen, joka toi Herralle kultaa heilutusuhriksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Jokainen, jolla oli sinipunaisia, purppuranpunaisia ja karmiininpunaisia lankoja, valkoisia pellavalankoja, vuohenkarvoja, punaisia pässin nahkoja tai tahašin nahkoja, toi niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Jokainen, joka saattoi antaa anniksi hopeaa ja vaskea, toi annin Herralle. Jokainen, jolla oli akasiapuuta, toi sitä kaikkien töiden valmistamista varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Kaikki taitavat naiset kehräsivät omin käsin ja toivat kehräämänsä sinipunaiset, purppuranpunaiset ja karmiininpunaiset langat ja valkoiset pellavalangat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Kaikki naiset, joiden taitava sydän heitä siihen vaati, kehräsivät vuohenkarvoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Mutta päämiehet toivat onyks-kiviä ja muita jalokiviä kasukkaa ja rintakilpeä varten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'ja hajuaineita ja öljyä seitsenhaaraista lamppua varten sekä voiteluöljyksi ja hyvänhajuiseksi suitsutukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Kaikki israelilaiset, miehet ja naiset, joiden sydän oli altis ja vaati heitä tuomaan jotakin niitä töitä varten, joita Herra Mooseksen kautta oli käskenyt tehdä, toivat vapaaehtoisen lahjan Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Mooses sanoi israelilaisille: \"Katsokaa, Herra on nimeltään kutsunut Besalelin, Uurin pojan, Huurin pojanpojan, Juudan sukukunnasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'Hän on täyttänyt hänet Jumalan Hengellä, taidolla, ymmärryksellä, tiedolla ja kaikella kätevyydellä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'sommittelemaan taidokkaita teoksia ja valmistamaan niitä kullasta, hopeasta ja vaskesta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'hiomaan ja kiinnittämään kiviä ja veistämään puuta, tekemään kaikenlaisia taidokkaita töitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Hänelle ja Oholiabille, Ahisamakin pojalle, Daanin sukukunnasta, hän on myös antanut kyvyn opettaa muita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Nämä hän on täyttänyt taidolla tekemään kaikkia töitä, jollaisia tekevät seppä, kuvakudosten tekijä, kirjokankaiden kutoja, joka valmistaa sinipunaisia, purppuranpunaisia ja karmiininpunaisia kankaita ja valkoisia pellavakankaita, sekä muu kankaan kutoja, ne, jotka valmistavat kaikkia töitä ja sommittelevat taidokkaita teoksia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, '\"Besalel ja Oholiab sekä kaikki taitajat, joille Herra on antanut taidon ja ymmärryksen tietää, miten mikin pyhäkössä tehtävä työ on suoritettava, tehkööt kaikissa kohdin, niin kuin Herra on käskenyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Mooses kutsui luokseen Besalelin ja Oholiabin ja kaikki taitajat, joiden sydämeen Herra oli antanut taidon, kaikki, joiden sydän vaati heitä ryhtymään työhön suorittaakseen sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'He ottivat Moosekselta kaikki annit, jotka israelilaiset olivat tuoneet pyhäkössä tehtävien töiden suorittamista varten. He toivat hänelle vielä joka aamu vapaaehtoisia lahjoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Niin tulivat kaikki taitajat, jotka tekivät kaikkia töitä pyhäkössä, mies toisensa jälkeen, siitä työstä, jota kukin oli tekemässä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'ja sanoivat Moosekselle näin: \"Kansa tuo enemmän, kuin mitä tarvitaan sen työn valmistamiseksi, jonka Herra on käskenyt tehdä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Mooses käski kuuluttaa leirissä ja sanoa: \"Älköön kukaan, mies tai nainen, enää valmistako mitään anniksi pyhäkköä varten.\" Niin kansa lakkasi tuomasta lahjoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Sillä kaikkea työtä varten, mikä oli tehtävä, oli jo koottu riittävästi, jopa yli tarpeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Niin kaikki taitajat, jotka siinä työssä olivat, tekivät asumuksen kymmenestä telttakankaan kaistasta, jotka olivat valmistetut kerratuista valkoisista pellavalangoista ja sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista. Niihin tehtiin taitavasti kudottuja kerubeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Kunkin kaistan pituus oli kaksikymmentä kahdeksan kyynärää ja leveys neljä kyynärää. Kaikilla kaistoilla oli sama mitta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Viisi kaistaa yhdistettiin toisiinsa, ja samoin toiset viisi kaistaa yhdistettiin toisiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Sitten tehtiin silmukat sinipunaisesta langasta ensimmäisen kaistan reunaan, yhdistetyn kappaleen laitaan, ja samoin toisen yhdistetyn kappaleen viimeisen kaistan reunaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Viisikymmentä silmukkaa tehtiin ensimmäiseen kaistaan ja viisikymmentä silmukkaa vastaavan kaistan laitaan toiseen yhdistettyyn kappaleeseen, niin että silmukat olivat kohdakkain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Sitten tehtiin viisikymmentä kultahakasta, ja kaistat yhdistettiin toisiinsa näillä hakasilla, niin että siitä tuli yhtenäinen asumus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Vielä tehtiin vuohenkarvoista telttakankaan kaistoja asumusta suojaavaksi teltaksi. Niitä kaistoja tehtiin yksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Kunkin kaistan pituus oli kolmekymmentä kyynärää ja leveys neljä kyynärää. Niillä yhdellätoista kaistalla oli sama mitta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Kaistat liitettiin yhteen, viisi kaistaa erikseen ja kuusi kaistaa erikseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Viisikymmentä silmukkaa tehtiin toisen yhdistetyn kappaleen viimeisen kaistan reunaan ja viisikymmentä silmukkaa toisen yhdistetyn kappaleen vastaavan kaistan reunaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Sitten tehtiin viisikymmentä vaskihakasta, joilla teltta liitettiin yhteen, niin että siitä tuli yhtenäinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Teltalle tehtiin peite punaisista pässin nahoista ja sen päälle vielä toinen peite tahašin nahoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Asumuksen laudat tehtiin akasiasta, pystyyn asetettaviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Jokainen lauta oli kymmenen kyynärää pitkä ja puolitoista kyynärää leveä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Jokaisessa laudassa oli kaksi tappia, jotka oli yhdistetty keskenään poikkilistalla. Näin tehtiin kaikki asumuksen laudat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Asumuksen lautoja tehtiin kaksikymmentä lautaa eteläpuolta varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Kahdenkymmenen laudan alle tehtiin neljäkymmentä hopeajalustaa, aina kaksi jalustaa kunkin laudan alle sen kahta tappia varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Samoin asumuksen toista sivua, pohjoispuolta, varten tehtiin kaksikymmentä lautaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'ja neljäkymmentä hopeajalustaa, aina kaksi jalustaa kunkin laudan alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Mutta asumuksen takasivua, länsipuolta, varten tehtiin kuusi lautaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Kaksi lautaa tehtiin asumuksen peränurkkia varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Ne olivat yhteen liitettyjä kaksoislautoja ja alhaalta alkaen kiinni toisissaan ylös saakka, ensimmäiseen renkaaseen asti. Näin ne molemmat tehtiin kumpaakin nurkkaa varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Näin tuli olemaan yhteensä kahdeksan lautaa ja niihin kuusitoista hopeajalustaa, aina kaksi jalustaa kunkin laudan alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Tehtiin myös viisi poikkitankoa akasiasta asumuksen toisen sivun lautoja varten');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'ja viisi poikkitankoa asumuksen toisen sivun lautoja varten ja viisi poikkitankoa asumuksen takasivun, länsipuolen, lautoja varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Keskimmäinen poikkitanko tehtiin ulottumaan lautojen keskikohdalta reunasta reunaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Laudat päällystettiin kullalla, ja niiden renkaat tehtiin kullasta poikkitankojen pitimiksi, ja poikkitangotkin päällystettiin kullalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Vielä tehtiin esirippu sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista ja kerratuista valkoisista pellavalangoista. Siihen tehtiin taitavasti kudottuja kerubeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Siihen tehtiin neljä pylvästä akasiasta, ja ne päällystettiin kullalla, ja niiden koukut olivat kultaa, ja niitä varten valettiin neljä hopeajalustaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, '[Tehtiin] teltan oveen verho, kirjaillen kudottu sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista ja kerratuista valkoisista pellavalangoista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'viisi pylvästä koukkuineen, ja niiden päät ja niiden koristepienat päällystettiin kullalla. Niiden viisi jalustaa tehtiin vaskesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Besalel teki arkin akasiapuusta, kaksi ja puoli kyynärää pitkän, puolitoista kyynärää leveän ja puolitoista kyynärää korkean.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Hän päällysti sen puhtaalla kullalla sisältä ja ulkoa ja teki siihen kultareunuksen yltympäri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Hän valoi siihen neljä kultarengasta, sen neljään kulmaan, niin että kaksi rengasta tuli toiselle puolelle ja kaksi rengasta toiselle puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Hän teki korennot akasiapuusta ja päällysti ne kullalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Hän pisti arkin sivuilla oleviin renkaisiin korennot, joilla arkkia oli kannettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Hän teki armoistuimen puhtaasta kullasta, kaksi ja puoli kyynärää pitkän ja puolitoista kyynärää leveän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Hän teki kaksi kultakerubia, taottua tekoa, armoistuimen molempiin päihin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'toisen kerubin toiseen päähän ja toisen kerubin toiseen päähän. Armoistuimesta kohoaviksi hän teki kerubit sen kumpaankin päähän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Kerubit levittivät siipensä ylöspäin, niin että ne peittivät siivillään armoistuimen, ja niiden kasvot olivat vastakkain. Kerubien kasvot olivat käännetyt armoistuinta kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Hän teki myös pöydän akasiapuusta, kaksi kyynärää pitkän, kyynärän leveän ja puolitoista kyynärää korkean.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Hän päällysti sen puhtaalla kullalla ja teki siihen kultareunuksen yltympäri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Hän teki sen ympäri kämmenen korkuisen listan, ja listan ympäri kultareunuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Hän valoi siihen neljä kultarengasta ja kiinnitti renkaat neljään kulmaan, sen neljän jalan kohdalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Renkaat olivat juuri listan alla niiden korentojen pitiminä, joilla pöytää oli kannettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Hän teki korennot akasiapuusta ja päällysti ne kullalla. Pöytää oli niillä kannettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Hän teki puhtaasta kullasta pöydällä pidettävät astiat: vadit ja kupit, maljat ja kannut, joista juomauhri vuodatetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Hän teki myös seitsenhaaraisen lampun puhtaasta kullasta. Hän teki seitsenhaaraisen lampun taottua tekoa jalkoineen ja varsineen. Sen kukkakuvut, nuput kukkalehtineen, olivat samaa kappaletta kuin sekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Kuusi haaraa lähti lampun sivuista, kolme haaraa toisesta sivusta ja kolme haaraa toisesta sivusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Toisessa haarassa oli kolme mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen, ja toisessa haarassa samoin kolme mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen. Näin oli jokaisessa kuudessa haarassa, jotka lähtivät lampusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Itse seitsenhaaraisessa lampussa taas oli neljä mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'Yksi nuppu oli aina jokaisen haaraparin alla niistä kuudesta haarasta, jotka lähtivät lampusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Nuput ja haarat olivat samaa kappaletta kuin se. Se oli kokonaan samalla tavalla takomalla tehtyä, puhdasta kultaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Hän teki siihen seitsemän lamppua ja siihen kuuluvat lamppusakset ja karstakupit puhtaasta kullasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Yhdestä talentista puhdasta kultaa hän teki sekä sen että kaikki siihen kuuluvat esineet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Hän teki myös suitsutusalttarin akasiapuusta, kyynärän pituisen ja kyynärän levyisen, siis neliskulmaisen, ja kaksi kyynärää korkean. Sen sarvet olivat samaa kappaletta kuin sekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Hän päällysti sen puhtaalla kullalla, sekä sen levyn että sivut ympäriinsä ja sen sarvet. Hän teki kultareunuksen sen ympärille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Hän teki siihen kaksi kultarengasta reunuksen alle molemmin puolin, molempiin sivuihin, niiden korentojen pitimiksi, joilla alttaria oli kannettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Korennotkin hän teki akasiapuusta ja päällysti ne kullalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Hän teki pyhän voiteluöljyn ja puhtaan, hyvälle tuoksuvan suitsukkeen, jollaista voiteensekoittaja valmistaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Hän teki polttouhrialttarin akasiapuusta, neliskulmaisen, viisi kyynärää pitkän, viisi kyynärää leveän ja kolme kyynärää korkean.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Hän teki siihen sarvet sen neljään kulmaan, niin että sarvet olivat samaa kappaletta kuin sekin. Hän päällysti sen vaskella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Hän teki kaikki alttariesineet: kattilat, lapiot, maljat, haarukat ja hiilipannut. Kaikki sen esineet hän teki vaskesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Hän teki alttariin verkonkaltaisen ristikkokehyksen vaskesta alttarin välireunuksen alle maahan kiinni, niin että se ulottui puoliväliin alttaria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Hän valoi neljä rengasta vaskiristikon neljään kulmaan, korentojen pitimiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Korennot hän teki akasiapuusta ja päällysti ne vaskella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Hän pisti alttarin sivuilla oleviin renkaisiin korennot, joilla oli kannettava sitä. Hän teki sen laudoista sisältä avoimeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Hän teki vaskialtaan vaskijalustoineen niiden naisten vaskipeileistä, jotka toimittivat palvelusta ilmestysmajan ovella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Sitten hän teki esipihan. Etelän puolella olivat esipihan ympärysverhot kerratuista valkoisista pellavalangoista, sata kyynärää pitkiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Niiden pylväitä oli kaksikymmentä ja näiden vaskijalustoja kaksikymmentä, mutta pylväiden koukut ja niiden koristepienat olivat hopeaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Samoin olivat ympärysverhot myös pohjoisen puolella sadan kyynärän pituiset. Niiden pylväitä oli kaksikymmentä ja näiden vaskijalustoja kaksikymmentä, mutta pylväiden koukut ja niiden koristepienat olivat hopeaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Länsipuolella ympärysverhot sen sijaan olivat viisikymmentä kyynärää pitkiä. Niiden pylväitä oli kymmenen ja näiden jalustoja kymmenen, ja pylväiden koukut ja niiden koristepienat olivat hopeaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Etupuolella itään päin ympärysverhot olivat viisikymmentä kyynärää pitkiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Ympärysverhot olivat portin toisella sivulla viisitoista kyynärää pitkiä. Niiden pylväitä oli kolme ja näiden jalustoja kolme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Samoin olivat ympärysverhot toisellakin sivulla, siis esipihan portin kummallakin puolella, viisitoista kyynärää pitkiä. Niiden pylväitä oli kolme ja näiden jalustoja kolme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Kaikki esipihan ympärysverhot yltympäri olivat kerratuista valkoisista pellavalangoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Pylväiden jalustat olivat vaskea, mutta pylväiden koukut ja niiden koristepienat olivat hopeaa, ja niiden päiden päällys oli hopeaa. Kaikki esipihan pylväät oli ympäröity hopeisilla koristepienoilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Esipihan portin verho oli kirjaillen kudottu sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista ja kerratuista valkoisista pellavalangoista, kaksikymmentä kyynärää pitkä ja niin kuin esipihan ympärysverhotkin viisi kyynärää korkea vaatteen leveyden mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Sen pylväitä oli neljä ja näiden vaskijalustoja neljä, mutta niiden koukut olivat hopeaa, ja niiden päiden päällystys ja niiden koristepienat olivat hopeaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Kaikki asumuksen ja ympärillä olevan esipihan vaarnat olivat vaskea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Näin paljon lasketaan menneen asumuksen, todistuksen asumuksen, kustannuksiin, joka lasku tehtiin Mooseksen käskyn mukaan leeviläisten toimesta Iitamarin, pappi Aaronin pojan, johdolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Besalel, Uurin poika, Huurin pojanpoika, Juudan sukukunnasta, oli tehnyt kaikki, mistä Herra oli Moosekselle antanut käskyn.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'Apulaisena hänellä oli Oholiab, Ahisamakin poika, Daanin sukukunnasta, seppä ja kuvakudosten tekijä. Tämä valmisti kirjokankaita sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista ja valkoisista pellavalangoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Kultaa, joka käytettiin tähän työhön, kaikkeen työhön pyhäkössä, oli heilutusuhrina tuotu kaikkiaan kaksikymmentä yhdeksän talenttia, seitsemänsataa kolmekymmentä sekeliä pyhäkkösekelin painon mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Hopeaa, joka kansalta katselmusta pidettäessä kerääntyi, oli sata talenttia ja tuhat seitsemänsataa seitsemänkymmentä viisi sekeliä pyhäkkösekelin painon mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'puolikas, puoli sekeliä henkeä kohti pyhäkkösekelin painon mukaan, jokaiselta katselmuksessa olleelta kaksikymmenvuotiaalta ja sitä vanhemmalta, kaikkiaan kuudeltasadalta kolmelta tuhannelta viideltäsadalta viideltäkymmeneltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Ne sata talenttia hopeaa käytettiin pyhäkön jalustojen ja esiripun jalustojen valamiseen, sata talenttia sataan jalustaan, talentti jalustaa kohden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Niistä tuhannesta seitsemästäsadasta seitsemästäkymmenestä viidestä sekelistä tehtiin koukut pylväisiin ja päällystettiin hopealla niiden päät ja tehtiin niihin koristepienat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Heilutusuhrivaskea oli seitsemänkymmentä talenttia, kaksituhatta neljäsataa sekeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Siitä tehtiin jalustat ilmestysmajan oveen, vaskialttari ja siihen kuuluva vaskinen ristikkokehys ja kaikki alttarin esineet');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'sekä jalustat ympärillä olevaan esipihaan ja jalustat esipihan porttiin ja kaikki asumuksen vaarnat ja kaikki vaarnat ympärillä olevaan esipihaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista tehtiin virkapuvut pyhäkköpalvelusta varten. Samoin tehtiin muut pyhät vaatteet Aaronille, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Kasukat tehtiin kullasta sekä sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista ja kerratuista valkoisista pellavalangoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Kultalevyt taottiin ohuiksi ja leikattiin säikeiksi, taitavasti kudottaviksi sinipunaisten, purppuranpunaisten ja karmiininpunaisten lankojen ja valkoisten pellavalankojen sekaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Siihen tehtiin yhdistettävät olkakappaleet. Se kiinnitettiin niihin molemmista päistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Vyö kasukan kiinnittämiseksi tehtiin samasta kappaleesta kuin se, samalla tavalla kullasta sekä sinipunaisista, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Sitten valmistettiin kultapalmikoilla kehystetyt onykskivet, joihin oli kaiverrettu Israelin poikien nimet, niin kuin kaiverretaan sinettisormuksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Kivet pantiin kasukan olkakappaleisiin, että ne toisivat mieleen israelilaiset, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Rintakilpi tehtiin taitavasti kutomalla, samalla tavalla kuin kasukkakin oli tehty, kullasta sekä sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista ja kerratuista valkoisista pellavalangoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Se oli neliskulmainen ja taskun muotoon tehty. Rintakilvestä tehtiin vaaksan mittainen ja vaaksan levyinen, taskun muotoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Sen pintaan kiinnitettiin kiviä joka puolelle, neljään riviin: ensimmäiseen riviin karneoli, topaasi ja smaragdi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'toiseen riviin rubiini, safiiri ja jaspis,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'kolmanteen riviin hyasintti, akaatti ja ametisti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'ja neljänteen riviin krysoliitti, onyks ja berylli. Kultapunoksilla kehystettyinä ne kiinnitettiin paikoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Kiviä oli Israelin poikien nimien mukaan kaksitoista, yksi kutakin nimeä kohti. Kussakin kivessä oli yksi kahdentoista sukukunnan nimistä, kaiverrettuna samalla tavalla, kuin kaiverretaan sinettisormuksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Rintakilpeen tehtiin puhtaasta kullasta ketjut, punotut, niin kuin punosta tehdään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Sitten tehtiin kaksi kultapunosta ja kaksi kultarengasta, ja molemmat renkaat kiinnitettiin rintakilven molempiin yläkulmiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Molemmat kultapunokset kiinnitettiin kahteen renkaaseen rintakilven yläkulmiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Molempien punosten toiset kaksi päätä kiinnitettiin kahteen palmikkoon, ja nämä kiinnitettiin kasukan olkakappaleisiin, sen etupuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Sitten tehtiin kaksi kultarengasta, jotka pantiin rintakilven molempiin alakulmiin, sen sisäpuoliseen, kasukkaa vasten olevaan reunaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Vielä tehtiin kaksi kultarengasta, ja ne kiinnitettiin kasukan molempiin olkakappaleisiin, niiden alareunaan, etupuolelle, sauman kohdalle, kasukan vyön yläpuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Sitten rintakilpi solmittiin renkaistaan sinipunaisella nauhalla kasukan renkaisiin, niin että se oli kasukan vyön yläpuolella, eikä rintakilpi siis irronnut kasukasta – kaikki, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Kasukan viitta tehtiin kokonaan kutomalla sinipunaisista langoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Pääntie viitan keskellä oli kuin haarniskan aukko. Pääntie ympäröitiin päärmeellä, ettei se repeäisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Viitan helmaan tehtiin granaattiomenia sinipunaisista, purppuranpunaisista ja karmiininpunaisista kerratuista langoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Sitten tehtiin tiukuja puhtaasta kullasta. Tiu\'ut kiinnitettiin granaattiomenien väliin viitan helmaan ympäriinsä, granaattiomenien väliin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'vuorotellen tiuku ja granaattiomena viitan helmaan ympäriinsä, käytettäviksi virantoimituksessa, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Sitten tehtiin Aaronille ja hänen pojilleen valkoisista pellavalangoista kudotut paidat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'turbaani valkoisista pellavalangoista, koristepäähineet valkoisista pellavalangoista ja pellavahousut kerratuista valkoisista pellavalangoista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'ja vyö kerratuista valkoisista pellavalangoista ja sinipunaisista, purppuranpunaisista ja karmiininpunaisista langoista, kirjaillen kudottu, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Tehtiin otsakoriste, pyhä otsalehti, puhtaasta kullasta ja siihen piirrettiin, niin kuin sinettisormusta kaiverretaan, kirjoitus: \" Herralle pyhitetty.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Siihen kiinnitettiin sinipunainen nauha sidottavaksi turbaanin yläreunaan, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Niin valmistui koko työ: asumus, todistuksen maja. Israelilaiset tekivät kaiken, kuten Herra oli Moosesta käskenyt, niin he tekivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'He toivat Mooseksen eteen asumuksen, telttamajan kaikkine varusteineen, hakasineen, lautoineen, poikkitankoineen, pylväineen ja jalustoineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'punaisista pässin nahoista tehdyn peitteen ja tahašin nahoista tehdyn peitteen ja verhona olevan esiripun,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'todistuksen arkin korentoineen, armoistuimen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'pöydän kaikkine esineineen ja näkyleivät,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'aitokultaisen seitsenhaaraisen lampun riviin pantavine lamppuineen ja kaikkine varusteineen sekä öljyä seitsenhaaraista lamppua varten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'kultaisen alttarin, voiteluöljyn ja hyvälle tuoksuvan suitsukkeen, telttamajan oviverhon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'vaskialttarin vaskisine ristikkokehyksineen, sen korennot ja kaikki esineet, altaan jalustoineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'esipihan ympärysverhot pylväineen ja jalustoineen, esipihan portin verhon sekä sen köydet ja vaarnat, ja kaikki esineet, joita tarvitaan asumuksen, todistuksen telttamajan, tehtävissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'virkapuvut pyhäkköpalvelusta varten ja pappi Aaronin muut pyhät vaatteet sekä hänen poikiensa papinpuvut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Aivan niin kuin Herra oli Moosesta käskenyt, niin israelilaiset olivat tehneet kaiken tämän työn.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Mooses katseli kaikkea työtä, ja katso, he olivat tehneet sen niin, kuin Herra oli käskenyt. Niin he olivat sen tehneet. Sitten Mooses siunasi heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, '\"Ensimmäisen kuukauden ensimmäisenä päivänä pystytä asumus, todistuksen telttamaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Aseta sinne todistuksen arkki ja ripusta esirippu arkin eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Tuo sinne pöytä ja lado sille näkyleivät päälletysten. Tuo sinne seitsenhaarainen lamppu ja nosta sen lamput paikoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Sijoita kultainen suitsutusalttari lain arkin eteen ja ripusta verho telttamajan oveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Sijoita polttouhrialttari asumuksen, ilmestysmajan, oven eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Sijoita allas ilmestysmajan ja alttarin välille ja kaada siihen vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Tee esipiha yltympäri ja pane verho esipihan porttiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Ota sitten voiteluöljyä ja voitele asumus ja kaikki, mitä siinä on, ja pyhitä se kalustoineen, että siitä tulisi pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Voitele polttouhrialttari kaikkine esineineen ja pyhitä alttari, että alttarista tulisi korkeasti pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Voitele myös allas jalustoineen ja pyhitä se.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Tuo sitten Aaron poikineen ilmestysmajan ovelle ja pese heidät vedellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Pue Aaron pyhiin vaatteisiin ja voitele hänet ja pyhitä hänet, että hän palvelisi minua pappina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Tuo myös hänen poikansa ja pue heidän ylleen viitat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Voitele heidät, niin kuin sinä voitelit heidän isänsäkin, että he pappeina palvelisivat minua. Niin tämä on oleva heille voitelu ikuiseen pappeuteen, sukupolvesta sukupolveen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Mooses teki kaiken, kuten Herra oli häntä käskenyt. Niin hän teki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Asumus pystytettiin toisen vuoden ensimmäisessä kuussa, kuukauden ensimmäisenä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Silloin Mooses pystytti asumuksen. Hän asetti paikoilleen sen jalustat, kiinnitti sen laudat, sovitti paikoilleen sen poikkitangot ja pystytti sen pylväät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Hän levitti asumuksen ylle teltan ja asetti ylimmäksi sen päälle telttapeitteen, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Sitten hän otti lain, pani sen arkkiin ja kiinnitti arkkiin korennot ja asetti armoistuimen arkin päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Hän toi arkin asumukseen ja sijoitti paikoilleen sitä verhoavan esiripun ripustaen sen todistuksen arkin eteen, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Hän asetti pöydän todistuksen telttamajaan asumuksen pohjoissivulle esiripun ulkopuolelle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'ja latoi sille näkyleivät päälletysten Herran eteen, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Hän asetti seitsenhaaraisen lampun ilmestysmajaan, vastapäätä pöytää, asumuksen eteläsivulle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'ja nosti lamput paikoilleen Herran eteen, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Hän asetti kultaisen alttarin ilmestysmajaan esiripun eteen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'ja poltti siinä hyvälle tuoksuvaa suitsuketta, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Hän ripusti verhon asumuksen oveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Polttouhrialttarin hän asetti asumuksen, todistuksen telttamajan, oven eteen ja uhrasi sen päällä polttouhrin ja ruokauhrin, niin kuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Hän asetti altaan ilmestysmajan ja alttarin välille ja kaatoi siihen vettä peseytymistä varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Mooses ja Aaron ja hänen poikansa pesivät siinä kätensä ja jalkansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Kun he menivät todistuksen telttamajaan tai lähestyivät alttaria, niin he aina peseytyivät, niin kuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Asumuksen ja alttarin ympärille hän laittoi esipihan ja ripusti verhon esipihan porttiin. Niin Mooses päätti sen työn.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Sitten pilvi peitti todistuksen telttamajan, ja Herran kirkkaus täytti asumuksen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'eikä Mooses voinut mennä todistuksen telttamajaan, sillä pilvi oli laskeutunut sen päälle, ja Herran kirkkaus täytti asumuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Joka kerta, kun pilvi kohosi asumuksen päältä, israelilaiset lähtivät liikkeelle. Näin oli koko heidän vaelluksensa ajan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Mutta milloin pilvi ei kohonnut, he eivät lähteneet liikkeelle, ennen kuin sinä päivänä, jona se taas kohosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Sillä Herran pilvi oli päivällä asumuksen päällä, ja yöllä oli pilvessä tulen hohde kaikkien israelilaisten silmien edessä. Näin oli koko heidän vaelluksensa ajan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Herra kutsui Mooseksen ja puhui hänelle ilmestysmajan sisältä sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, '\"Puhu israelilaisille ja sano heille: Jos joku teistä tahtoo tuoda uhrilahjan Herralle, niin tuokaa uhrilahjanne karjasta, joko nautakarjasta tai lampaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Jos hänen uhrilahjansa on nautapolttouhri, tuokoon virheettömän urospuolen. Tuokoon sen ilmestysmajan ovelle, jotta Herran mielisuosio tulisi hänen osakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Laskekoon kätensä polttouhriteuraan pään päälle, niin se on otollinen ja tuottaa hänelle sovituksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Teurastakoon mullin Herran kasvojen edessä, ja papit, Aaronin pojat, tuokoot veren ja vihmokoot veren ympäriinsä alttarille, joka on ilmestysmajan ovella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Nylkeköön polttouhriteuraan ja leikelköön sen määräpaloiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Pappi Aaronin pojat tehkööt tulen alttarille ja pankoot puita tuleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Papit, Aaronin pojat, asettakoot palat sekä pään ja rasvan puiden päälle, jotka ovat tulella alttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Mutta sisälmykset ja jalat hän pesköön vedessä, ja pappi polttakoon kaiken alttarilla. Se on polttouhri, suloisesti tuoksuva uhri Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Jos hänen uhrilahjansa, joka on tarkoitettu polttouhriksi, on otettu lampaista tai vuohista, tuokoon virheettömän urospuolen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Teurastakoon sen alttarin pohjoissivulla, Herran edessä, ja papit, Aaronin pojat, vihmokoot sen veren alttarille ympäriinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Leikelköön sen määräpaloiksi, ja pappi asettakoon ne sekä pään ja rasvan puiden päälle, jotka ovat tulella alttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Mutta sisälmykset ja jalat hän pesköön vedessä, ja pappi tuokoon sen kaiken ja polttakoon sen alttarilla. Se on polttouhri, suloisesti tuoksuva uhri Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Jos hänen uhrilahjansa Herralle on polttouhri linnuista, tuokoon uhrilahjanaan metsäkyyhkysiä tai kyyhkysenpoikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Pappi tuokoon sen alttarille, vääntäköön siltä niskat nurin ja polttakoon sen alttarilla, ja puserrettakoon sen veri alttarin seinään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Hän irrottakoon sen kuvun ruokasulineen ja heittäköön sen alttarin viereen itäpuolelle tuhkaläjälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Sitten hän reväisköön linnun auki siipien kohdalta niitä irrottamatta, ja pappi polttakoon sen alttarilla puiden päällä, jotka ovat tulella. Se on polttouhri, suloisesti tuoksuva uhri Herralle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, '\"Jos joku tahtoo tuoda Herralle lahjaksi ruokauhrin, olkoon hänen uhrilahjanaan ydinjauhoja, vuodattakoon siihen öljyä ja pankoon sen päälle suitsuketta sekä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'vieköön sen papeille, Aaronin pojille. Pappi ottakoon kourallisen näitä jauhoja ja tätä öljyä sekä kaiken suitsukkeen ja polttakoon tämän muistouhrin alttarilla suloisesti tuoksuvana polttouhrina Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Mutta se, mitä jää tähteeksi ruokauhrista, olkoon Aaronin ja hänen poikiensa. Se on korkeasti pyhää, Herran uhria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Mutta jos tahdot tuoda ruokauhrilahjan uunissa paistetusta, olkoon uhrinasi ydinjauhoista valmistetut, öljyyn leivotut happamattomat leipäkakut tai öljyllä voidellut happamattomat rieskat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Jos taas uhrilahjasi on ruokauhri, joka paistetaan leivinlevyllä, olkoon se valmistettu ydinjauhoista, öljyyn leivottu ja happamaton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Paloittele se palasiksi ja vuodata öljyä sen päälle. Se on ruokauhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Jos uhrilahjasi on ruokauhri, joka paistetaan pannussa, valmistettakoon se ydinjauhoista ja öljystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Vie näin valmistettu ruokauhri Herralle. Vietäköön se papille. Hän tuokoon sen sitten alttarille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Pappi uhratkoon ruokauhrista muistouhrin ja polttakoon sen alttarilla suloisesti tuoksuvana uhrina Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Mutta se, mitä jää tähteeksi ruokauhrista, olkoon Aaronin ja hänen poikiensa. Se on korkeasti pyhää, Herran uhria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Mitään ruokauhria, jonka te tuotte Herralle, älköön valmistettako happamasta. Älkää polttako uhria Herralle mistään happamasta taikinasta tai hunajasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Uutisuhrilahjana saatte tuoda niitä Herralle, mutta älkööt ne tulko alttarille suloiseksi tuoksuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Jokainen ruokauhrilahjasi suolaa suolalla äläkä anna Jumalasi liitonsuolan puuttua ruokauhristasi. Jokaiseen uhrilahjaasi sinun on tuotava suolaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Mutta jos tahdot tuoda ensisadosta ruokauhrin Herralle, niin tuo ensisadon ruokauhrinasi tulella paahdettuja tähkiä tai survottuja jyviä tuleentumattomasta viljasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Vuodata siihen sitten öljyä ja pane siihen suitsuketta. Se on ruokauhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Pappi polttakoon alttariuhriosan survotuista jyvistä ja öljystä sekä kaiken suitsukkeen uhrina Herralle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, '\"Jos hänen uhrilahjansa on rauhanuhri nautakarjasta joko härkä tai lehmä, tuokoon virheettömän eläimen Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Laskekoon kätensä uhriteuraansa pään päälle ja teurastakoon sen ilmestysmajan oven edustalla. Papit, Aaronin pojat, vihmokoot veren alttarille, sen joka taholle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Tuokoon rauhanuhrista uhrina Herralle sisälmyksiä peittävän rasvan ja kaiken sisälmysten rasvan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'sekä molemmat munuaiset ja niiden päällä lantiolihaksissa olevan rasvan ja maksan takalohkon, joka on irrotettava munuaisten kohdalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Aaronin pojat polttakoot sen alttarilla polttouhrin päällä, joka on polttopuiden päällä tulella, suloisesti tuoksuvana uhrina Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Jos hän tuo uhrilahjanaan Herralle rauhanuhriksi lampaista ja vuohista urospuolen tai naaraspuolen, niin tuokoon virheettömän eläimen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Jos hän tuo uhrilahjanaan lampaan, tuokoon sen Herran eteen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'ja laskekoon kätensä uhriteuraansa pään päälle ja teurastakoon sen ilmestysmajan oven edustalla, ja Aaronin pojat vihmokoot sen veren alttarille joka taholle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Hän tuokoon rauhanuhrista uhrina Herralle sen rasvan, koko rasvahännän, joka on irrotettava häntänikamista, sisälmyksiä peittävän rasvan ja kaiken sisälmysten rasvan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'ja molemmat munuaiset sekä niiden päällä lantiolihaksissa olevan rasvan ja maksan takalohkon, joka on irrotettava munuaisten kohdalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Pappi polttakoon sen alttarilla uhriruokana Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Jos hänen uhrilahjansa on vuohi, tuokoon sen Herran eteen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'ja laskekoon kätensä sen pään päälle ja teurastakoon sen ilmestysmajan ovella. Aaronin pojat vihmokoot sen veren alttarille, sen joka puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Tuokoon siitä uhrilahjanaan Herralle uhriksi sisälmyksiä peittävän rasvan ja kaiken sisälmysten rasvan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'ja molemmat munuaiset sekä niiden päällä lantiolihaksissa olevan rasvan ja maksan takalohkon, joka on irrotettava munuaisten kohdalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Pappi polttakoon ne alttarilla uhriruokana, suloisesti tuoksuvana uhrina. Kaikki rasva olkoon Herralle tuleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Tämä olkoon teille ikiaikainen säädös sukupolvesta sukupolveen, missä asuttekin: mitään rasvaa tai verta älkää siitä syökö.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, '\"Puhu israelilaisille ja sano: Jos joku erehdyksestä rikkoo jotakin Herran käskyä vastaan ja tekee sellaista, mitä ei saa tehdä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'ja jos voideltu pappi tekee synnin ja saattaa kansan syynalaiseksi, tuokoon tekemänsä synnin tähden virheettömän mullin Herralle syntiuhriksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Vieköön mullin ilmestysmajan ovelle Herran eteen ja laskekoon kätensä mullin pään päälle ja teurastakoon mullin Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Voideltu pappi ottakoon mullin verta ja vieköön sen ilmestysmajaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'kastakoon sormensa vereen ja pirskottakoon verta seitsemän kertaa Herran edessä, pyhäkön esiripun edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Pappi sivelköön verta alttarin sarviin, jolla poltetaan hyvänhajuista suitsutusta Herran edessä ja joka on ilmestysmajassa. Kaiken muun mullin veren hän vuodattakoon ilmestysmajan oven edustalla olevan polttouhrialttarin juurelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Kaiken syntiuhrimullin rasvan hän erottakoon siitä pois, sekä sisälmyksiä peittävän rasvan että kaiken sisälmysten rasvan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'ja molemmat munuaiset sekä niiden päällä lantiolihaksissa olevan rasvan ja maksan takalohkon, joka on irrotettava munuaisten kohdalta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'samalla tavalla kuin se erotetaan pois rauhanuhrin härästä. Pappi polttakoon ne polttouhrialttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Mutta mullin nahan ja kaiken lihan sekä pään ja jalat, sisälmykset ja ruokasulan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'koko mullin, hän vieköön leirin ulkopuolelle puhtaaseen paikkaan, johon tuhka heitetään, ja polttakoon sen polttopuiden päällä tulella. Poltettakoon se siinä paikassa, johon tuhka heitetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Jos koko Israelin seurakunta tahattomasti tekee synnin seurakunnan sitä tietämättä ja jos he rikkomalla jotakin Herran käskyä vastaan ovat tehneet sellaista, mitä ei saa tehdä, he ovat siten joutuneet syynalaisiksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'ja jos sitten synti, jonka he ovat tehneet jotakin käskyä vastaan, tulee ilmi, seurakunta tuokoon mullin syntiuhriksi ja vieköön sen ilmestysmajan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Seurakunnan vanhimmat laskekoot kätensä mullin pään päälle Herran edessä, ja mulli teurastettakoon Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Voideltu pappi vieköön mullin verta ilmestysmajaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Pappi kastakoon sormensa vereen ja pirskottakoon sitä seitsemän kertaa Herran edessä, esiripun edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Sivelköön sitten verta alttarin sarviin, joka on Herran edessä ilmestysmajassa. Kaiken muun veren hän vuodattakoon ilmestysmajan oven edustalla olevan polttouhrialttarin juurelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Erottakoon siitä pois kaiken rasvan ja polttakoon sen alttarilla');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'ja tehköön mullille, niin kuin hän teki syntiuhrimullille. Tehköön sille samalla tavalla. Kun pappi on näin toimittanut heille sovituksen, heille annetaan anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Vieköön mullin leirin ulkopuolelle ja polttakoon sen, niin kuin hän poltti edellisen mullin. Se on seurakunnan syntiuhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Jos kansan johtomies tekee synnin rikkoen tietämättään jotakin Herran, Jumalansa, käskyä vastaan tehden sellaista, mitä ei saa tehdä ja joutuu syynalaiseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'ja kun hän sitten tulee tietoiseksi synnistään, tuokoon uhrilahjanaan vuohen, virheettömän urospuolen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Laskekoon sitten kätensä vuohen pään päälle ja teurastakoon sen siinä paikassa, jossa polttouhriteuraat Herran edessä teurastetaan. Se on hänen syntiuhrinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Pappi ottakoon syntiuhrin verta sormeensa ja sivelköön sitä polttouhrialttarin sarviin. Muun veren hän vuodattakoon polttouhrialttarin juurelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Mutta kaiken sen rasvan hän polttakoon alttarilla, samalla tavalla kuin rauhanuhrin rasvan. Kun pappi on näin toimittanut hänelle sovituksen hänen synnistään, se annetaan hänelle anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Jos joku kansasta erehdyksessä rikkoo jotakin Herran käskyä vastaan tekemällä sellaista, mitä ei saa tehdä, ja joutuu syynalaiseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'ja kun hän sitten saa tietää tehneensä synnin, tuokoon tekemänsä synnin tähden uhrilahjana vuohen, virheettömän naaraspuolen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'ja laskekoon kätensä syntiuhriteuraan pään päälle ja teurastakoon sen polttouhripaikalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Pappi ottakoon vuohen verta sormeensa ja sivelköön sitä polttouhrialttarin sarviin. Kaiken muun veren hän vuodattakoon alttarin juurelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Pappi irrottakoon kaiken sen rasvan, niin kuin rasva irrotetaan rauhanuhrista, ja polttakoon sen alttarilla suloisena tuoksuna Herralle. Kun pappi on näin toimittanut hänelle sovituksen, hänelle annetaan anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Mutta jos hän tuo lampaan syntiuhriksi, niin tuokoon virheettömän naaraan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'ja laskekoon kätensä tämän syntiuhriteuraan pään päälle ja teurastakoon sen syntiuhriksi siinä paikassa, missä polttouhrieläin teurastetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Pappi ottakoon syntiuhrin verta sormeensa ja sivelköön polttouhrialttarin sarviin. Kaiken muun veren hän vuodattakoon alttarin juurelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Kaiken lampaan rasvan hän irrottakoon, samoin kuin rauhanuhrilampaan rasva irrotetaan, ja pappi polttakoon sen alttarilla Herran uhrin päällä. Kun pappi on toimittanut hänelle sovituksen tekemästään synnistä, hänelle annetaan anteeksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, '\"Joka tekee syntiä kuultuaan jonkun kiroavan toisen tai on sen todistaja joko silminnäkijänä tai muuten asiasta tietoinen, mutta ei kuitenkaan ilmoita sitä, on syynalainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Joka tietämättään koskee johonkin saastaiseen, mihin tahansa, joko saastaisen metsäeläimen raatoon tai saastaisen kotieläimen raatoon tai saastaisen matelijan raatoon, on siten tullut saastaiseksi ja syynalaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Tai joka tietämättään koskee ihmisen saastaan, olipa se mitä saastaa tahansa, josta tulee saastaiseksi, mutta salaa sen, joutuu syynalaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Tai joka ajattelemattomasti puhuen huulillaan tietämättään vannoo tekevänsä jotakin pahaa tai hyvää – vannoipa mitä hyvänsä, mitä ihminen saattaa ajattelemattomasti vannoa – mutta tultuaan siitä tietoiseksi salaa sen, syyllistyy johonkin näistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Joka on syyllinen johonkin näistä, tunnustakoon syntinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'Tuokoon sitten syntiuhriksi tekemästään synnistä naaraspuolen lampaista ja vuohista, uuhen tai vuohen. Pappi toimittakoon hänelle sovituksen hänen synnistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Mutta jos hän ei voi hankkia sellaista eläintä, tuokoon Herralle hyvitykseksi synnistään kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa, toisen syntiuhriksi ja toisen polttouhriksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'ja vieköön ne papille. Tämä uhratkoon ensiksi sen, joka on määrätty syntiuhriksi, vääntäköön siltä niskat poikki, päätä kuitenkaan irrottamatta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'ja pirskottakoon syntiuhrin verta alttarin seinälle, ja jäljelle jäävä veri puserrettakoon alttarin juurelle. Se on syntiuhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Toisen kyyhkysen hän valmistakoon säädetyllä tavalla polttouhriksi. Kun pappi on näin toimittanut hänelle sovituksen hänen tekemästään synnistä, annetaan hänelle anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Jollei hän voi hankkia kahta metsäkyyhkystä tai kahta kyyhkysenpoikaa, tuokoon uhrilahjanaan tekemänsä synnin sovittamiseksi kymmenennen osan eefa-mittaa ydinjauhoja syntiuhriksi, mutta älköön vuodattako siihen öljyä älköönkä panko sen päälle suitsuketta, sillä se on syntiuhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Vieköön sen sitten papille, ja pappi ottakoon niitä kourallisen, alttariuhriosan, ja polttakoon sen alttarilla Herran uhrin päällä. Se on syntiuhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Kun pappi näin on toimittanut hänelle sovituksen jostakin sellaisesta hänen tekemästään synnistä, annetaan hänelle anteeksi. Papille tulkoon se, mikä ruokauhristakin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Sitten Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, '\"Jos joku laiminlyö uskollisuuden ja erehdyksessä rikkoo anastamalla sitä, mikä on Herralle pyhitetty, tuokoon hyvityksenä Herralle vikauhriksi virheettömän pässin lampaista, niin monen hopeasekelin arvoisen, pyhäkkösekelin painon mukaan, kuin sinä arvioit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Sen, mitä hän on anastanut pyhitetystä itselleen, hän korvatkoon. Lisätköön siihen vielä viidennen osan sen arvosta ja antakoon sen papille. Kun pappi on näin toimittanut hänelle sovituksen uhraamalla pässin vikauhriksi, annetaan hänelle anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Jos joku rikkoo jotakin Herran käskyä vastaan ja tekee tietämättään sellaista, mitä ei saa tehdä, ja tulee syynalaiseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'tuokoon papille vikauhriksi lampaista arviosi mukaisen, virheettömän pässin. Kun pappi on toimittanut hänelle sovituksen siitä erehdyksestä, jonka hän tietämättään teki, hänelle annetaan anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Se on vikauhri, sillä hän oli tullut syylliseksi Herran edessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 20, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 21, '\"Jos joku tekee synnin olemalla uskoton Herraa kohtaan kieltäessään saaneensa lähimmäiseltään, mitä tämä on hänen haltuunsa antanut tai hänen hoitoonsa uskonut, tai mitä hän itse on lähimmäiseltään väkisin ottanut tai vääryydellä anastanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 22, 'tai jos hän on löytänyt kadotetun esineen ja kieltää sen, tai vannoo väärin missä asiassa tahansa, jossa ihminen helposti rikkoo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 23, 'niin jos hän näin on tehnyt syntiä ja tullut syynalaiseksi, antakoon takaisin, mitä hän on väkisin ottanut tai vääryydellä anastanut, tai mitä hänen haltuunsa oli uskottu, tai löytämänsä kadotetun esineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 24, 'kaiken, minkä tähden hän oli väärin vannonut, korvatkoon sen täyteen määrään ja pankoon siihen vielä lisäksi viidennen osan sen arvosta. Sille, jonka oma se on, hän antakoon sen sinä päivänä, jona hän toimittaa vikauhrinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 25, 'Mutta hyvityksenä Herralle hän tuokoon papille vikauhriksi arviosi mukaisen, virheettömän pässin lampaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 26, 'Kun pappi on näin toimittanut hänelle sovituksen Herran edessä, annetaan hänelle anteeksi kaikki, mitä hän on tehnyt sellaista, josta hän on tullut syynalaiseksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, '\"Käske Aaronia ja hänen poikiaan ja sano: Tämä on laki polttouhrista. Polttouhri olkoon alttarin liedellä koko yön aamuun asti, ja tulta pidettäköön siten vireillä alttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Pappi pukeutukoon pellavapukuunsa ja pukeutukoon pellavahousuihin peittääkseen häpynsä. Korjatkoon pois tuhkan, joksi tuli on kuluttanut polttouhrin alttarilla, ja pankoon sen alttarin viereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Riisukoon sitten vaatteensa ja pukeutukoon toisiin vaatteisiin, ja vieköön tuhkan leirin ulkopuolelle puhtaaseen paikkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Tulta pidettäköön siten vireillä alttarilla älköönkä se koskaan sammuko. Pappi sytyttäköön alttarilla puut joka aamu ja asettakoon sen päälle polttouhrin ja polttakoon sen päällä rauhanuhrin rasvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Tuli palakoon aina alttarilla koskaan sammumatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Tämä on laki ruokauhrista: Aaronin pojat tuokoot sen Herran eteen, alttarin ääreen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Pappi erottakoon ruokauhrista kourallisen ydinjauhoja, öljyä ja kaiken suitsukkeen, joka on ruokauhrin päällä, ja polttakoon alttarilla alttariuhriosan suloiseksi tuoksuksi Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Sen, mikä siitä jää tähteeksi, Aaron syököön poikiensa kanssa. Happamattomana se syötäköön pyhässä paikassa. Ilmestysmajan esipihalla he sen syökööt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Älköön sitä leivottako hapatettuna. Heidän osakseen minä olen sen uhreistani antanut. Se on korkeasti pyhä, kuten myös syntiuhri ja vikauhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Jokainen miehenpuoli Aaronin jälkeläisistä syököön siitä. Tämä olkoon heidän ikuinen osuutensa Herran uhreista sukupolvesta sukupolveen. Jokainen, joka niihin koskee, on pyhäkölle pyhitetty.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, '\"Tämä olkoon Aaronin ja hänen poikiensa uhrilahja, joka heidän on tuotava Herralle heidän voitelupäivänään: kymmenesosa eefa-mittaa ydinjauhoja jokapäiväiseksi ruokauhriksi, puolet aamulla ja puolet illalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Se valmistettakoon leivinlevyllä öljyyn leivottuna. Tuo se hyvin sotkettuna ja uhraa se palasiksi paloiteltuna ruokauhrina suloiseksi tuoksuksi Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Se pappi, joka hänen pojistaan on voideltu hänen sijaansa, toimittakoon sen. Se on Herran ikuinen osuus. Poltettakoon se kokonaisuhrina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Jokainen papin ruokauhri on kokonaisuhri. Älköön sitä syötäkö.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, '\"Puhu Aaronille ja hänen pojilleen ja sano: Tämä on laki syntiuhrista. Siinä paikassa, missä polttouhri teurastetaan, teurastettakoon myös syntiuhri Herran edessä. Se on korkeasti pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Pappi, joka syntiuhrin uhraa, syököön sen. Syötäköön se pyhässä paikassa ilmestysmajan esipihalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Jokainen, joka koskee sen lihaan, on pyhäkölle pyhitetty, ja jos sen verta on roiskunut vaatteille, niin pese pyhässä paikassa se, mihin sitä on roiskunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Saviastia, jossa se keitetään, rikottakoon. Jos se on keitetty vaskiastiassa, hangattakoon astia puhtaaksi ja huuhdottakoon vedellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Jokainen miehenpuoli papeista saakoon sitä syödä. Se on korkeasti pyhää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Älköön kuitenkaan syötäkö mitään syntiuhria, jonka verta viedään ilmestysmajaan sovituksen toimittamista varten pyhäkössä, vaan se poltettakoon tulella.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, '\"Tämä on laki vikauhrista. Se on korkeasti pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Siinä paikassa, missä polttouhri teurastetaan, teurastettakoon myös vikauhri, ja sen veri vihmottakoon alttarin joka puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Sen kaikki rasva uhrattakoon, sekä rasvahäntä että sisälmyksiä peittävä rasva,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'ja molemmat munuaiset sekä niiden päällä lantiolihaksissa oleva rasva ja maksan takalohko, joka tulee irrottaa munuaisten kohdalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Pappi polttakoon ne alttarilla uhrina Herralle. Se on vikauhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Jokainen miehenpuoli papeista saakoon sitä syödä. Se syötäköön pyhässä paikassa. Se on korkeasti pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Se, mitä on säädetty syntiuhrista, koskee vikauhriakin. Laki on molemmista sama. Se olkoon sen papin, joka sillä sovituksen toimittaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Pappi, joka toimittaa jonkun puolesta polttouhrin, saakoon uhraamansa polttouhriteuraan nahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Jokainen ruokauhri, joka paistetaan uunissa, ja jokainen pannussa tai leivinlevyllä valmistettu, olkoon sen papin, joka uhrin toimittaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Mutta jokainen muu ruokauhri, oli siihen sekoitettu öljyä tai olipa se kuiva, olkoon kaikkien Aaronin poikien, yhden niin kuin toisenkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Tämä on laki rauhanuhrista, joka tuodaan Herralle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Jos joku tuo sen kiitokseksi, niin tuokoon rauhanuhriteuraan lisäksi öljyyn leivottuja happamattomia leipäkakkuja, öljyllä voideltuja happamattomia rieskoja ja sekoitettuja ydinjauhoja öljyyn leivottuina leipäkakkuina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Hapatetusta taikinasta leivottujen leipäkakkujen ohella tuokoon tämän uhrilahjansa rauhanuhrina uhratun rauhanuhriteuraan lisäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Tuokoon siitä yhden kutakin uhrilahjalajia anniksi Herralle. Olkoon se sen papin, joka vihmoo rauhanuhrin veren.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Rauhanuhrina uhratun rauhanuhriteuraan liha syötäköön sinä päivänä, jona se on uhrattu, älköönkä siitä jätettäkö mitään seuraavaan aamuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Mutta jos uhrilahjana tuotu teuras on lupausuhri tai vapaaehtoinen uhri, syötäköön se sinä päivänä, jona se on tuotu. Jos kuitenkin siitä jää jotakin tähteeksi, se saadaan syödä seuraavana päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Mutta mitä uhrilihasta on tähteenä kolmantena päivänä, se poltettakoon tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Jos rauhanuhriteuraan lihaa syödään kolmantena päivänä, se ei ole otollista eikä sitä lueta tuojan hyväksi, vaan se on saastaista. Jokainen, joka sitä syö, joutuu syynalaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Sitä lihaa, joka on ollut kosketuksissa saastaiseen, mihin tahansa, älköön syötäkö, vaan se poltettakoon tulessa. Muuten jokainen, joka on puhdas, saakoon syödä rauhanuhriteuraan lihaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Mutta jokainen, joka saastaisena ollessaan syö rauhanuhriteuraan lihaa, joka kuuluu Herralle, hävitettäköön kansastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Jos joku koskee johonkin saastaiseen, mihin tahansa, joko ihmisen saastaan tai saastaiseen karjaeläimeen tai mihin inhottavaan saastaan tahansa, ja syö rauhanuhriteuraan lihaa, joka kuuluu Herralle, hänet hävitettäköön kansastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, '\"Puhu israelilaisille ja sano: Älkää syökö mitään härän, lampaan tai vuohen rasvaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Itsestään kuolleen tai kuoliaaksi raadellun eläimen rasva käytettäköön kaikkinaisiin tarpeisiin, mutta älkää sitä syökö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Sillä jokainen, joka syö sen eläimen rasvaa, josta tuodaan uhri Herralle, hävitettäköön kansastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Älkää myöskään, missä asuttekin, syökö mitään verta, älkää lintujen älkääkä karjaeläinten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Jokainen, joka syö verta, minkälaista hyvänsä, hävitettäköön kansastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, '\"Puhu israelilaisille ja sano: Joka tuo Herralle rauhanuhrinsa, tuokoon Herralle uhrilahjan tästä rauhanuhristaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Tuokoon omin käsin Herran uhrit. Tuokoon rasvan sekä rintalihan, ja toimitettakoon niiden heilutus Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Pappi polttakoon rasvan alttarilla, mutta rintaliha olkoon Aaronin ja hänen poikiensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Oikea reisi antakaa papille anniksi rauhanuhriteuraistanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Se Aaronin pojista, joka uhraa rauhanuhrin veren ja rasvan, saakoon oikean reiden osakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Sillä minä olen ottanut heilutusrintalihan ja anniksi annetun reiden israelilaisilta heidän rauhanuhriteuraistaan ja antanut ne pappi Aaronille ja hänen pojilleen ikuiseksi osuudeksi israelilaisilta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Tämä on Aaronin ja hänen poikiensa osa Herran uhreista, joka heille määrättiin sinä päivänä, jona hän toi heidät pappeina palvelemaan Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'Sen osan Herra käski sinä päivänä, jona hän heidät voiteli, israelilaisten antaa heille ikuiseksi osuudeksi sukupolvesta sukupolveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Nämä ovat lait polttouhrista, ruokauhrista, syntiuhrista, vikauhrista, vihkiäisuhrista ja rauhanuhrista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'Nämä lait Herra antoi Moosekselle Siinain vuorella sinä päivänä, jona hän antoi israelilaisille käskyn tuoda uhrilahjansa Herralle Siinain erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Sitten Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, '\"Ota Aaron ja hänen poikansa sekä heidän vaatteensa ja voiteluöljy sekä syntiuhrimulli ja ne kaksi pässiä ja kori, jossa ovat happamattomat leivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'Kokoa koko seurakunta ilmestysmajan oven edustalle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Mooses teki, niin kuin Herra oli häntä käskenyt, ja seurakunta kokoontui ilmestysmajan oven edustalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Mooses sanoi seurakunnalle: \"Näin on Herra käskenyt tehdä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Mooses toi Aaronin ja hänen poikansa esille ja pesi heidät vedellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Sitten hän pani hänen päälleen paidan, vyötti hänet vyöllä, puki hänet viittaan ja pani kasukan hänen päälleen, vyötti hänet kasukan vyöllä ja sitoi sen hänen ympärilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Sitten hän asetti hänen rintaansa rintakilven, pani kilpeen uurimin ja tummimin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Vielä hän pani turbaanin hänen päähänsä ja kiinnitti turbaanin etupuolelle kultaisen otsakoristeen, pyhän otsalehden, niin kuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Sitten Mooses otti voiteluöljyn ja voiteli asumuksen ja kaikki, mitä siinä oli, ja pyhitti ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Hän pirskotti sitä seitsemän kertaa alttarille ja voiteli alttarin ja sen koko esineistön sekä altaan jalustoineen pyhittäen ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Hän vuodatti voiteluöljyä Aaronin päähän ja voiteli hänet pyhittäen hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Mooses toi esille Aaronin pojat ja puki heidän ylleen paidat ja vyötti heidät vyöllä ja sitoi päähineet heidän päähänsä, niin kuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Hän toi syntiuhrimullin, ja Aaron ja hänen poikansa laskivat kätensä syntiuhrimullin pään päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Mooses teurasti mullin, otti sen verta, siveli sitä sormellaan alttarin sarviin ympäriinsä ja puhdisti alttarin. Muun veren hän vuodatti alttarin juurelle ja pyhitti sen toimittamalla sen sovituksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Mooses otti kaiken sisälmysten päällä olevan rasvan ja maksan takalohkon ja molemmat munuaiset rasvoineen ja poltti ne alttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Mutta mullin nahkoineen, lihoineen ja ruokasulineen hän poltti tulessa leirin ulkopuolella, niin kuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Hän toi esille polttouhripässin, ja Aaron ja hänen poikansa laskivat kätensä pässin pään päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Mooses teurasti sen ja vihmoi veren alttarille sen joka puolelle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'ja leikkeli pässin määräpaloiksi. Sitten Mooses poltti pään sekä palat ja rasvan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Mutta sisälmykset ja jalat hän pesi vedessä. Sitten Mooses poltti koko pässin alttarilla. Se oli polttouhri suloiseksi tuoksuksi, uhri Herralle, niin kuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Sitten hän toi esille toisen pässin, vihkiäispässin, ja Aaron ja hänen poikansa laskivat kätensä pässin pään päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Mooses teurasti sen, otti sen verta ja siveli sitä Aaronin oikeaan korvalehteen, oikean käden peukaloon ja oikean jalan isoonvarpaaseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Sitten Mooses toi Aaronin pojat esille ja siveli verta heidän oikeaan korvalehteensä, oikean kätensä peukaloon ja heidän oikean jalkansa isoonvarpaaseen, mutta vihmoi muun veren alttarin joka puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Hän otti rasvan ja rasvahännän ja kaiken sisälmysten päällä olevan rasvan ja maksan takalohkon ja molemmat munuaiset rasvoineen ja oikean reiden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Hän otti happamattomien leipien korista, joka oli Herran edessä, yhden happamattoman leipäkakun, yhden öljyyn leivotun leipäkakun ja yhden rieskan ja pani ne rasvojen ja oikean reiden päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Hän pani kaikki nämä Aaronin käsiin ja hänen poikiensa käsiin, ja toimitutti niiden heilutuksen Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Mooses otti ne heidän käsistään ja poltti ne alttarilla polttouhrin päällä. Tämä oli vihkiäisuhri suloiseksi tuoksuksi, uhri Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Sitten Mooses otti rintalihan ja toimitti sen heilutuksen Herran edessä. Vihkiäispässistä tämä tuli Mooseksen osalle, niin kuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Mooses otti voiteluöljyä ja verta, jota oli alttarilla, pirskotti sitä Aaronin ja hänen vaatteittensa päälle ja samoin hänen poikiensa ja heidän vaatteittensa päälle ja pyhitti niin Aaronin ja hänen vaatteensa sekä hänen poikansa ja heidän vaatteensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Mooses sanoi Aaronille ja hänen pojilleen: \"Keittäkää liha ilmestysmajan ovella ja syökää se siinä sekä leipä, joka on vihkiäisuhriin kuuluvassa korissa, niin kuin minä olen käskenyt ja sanonut: Aaron poikineen syököön sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Mutta mitä jää tähteeksi lihasta ja leivästä, polttakaa tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Seitsemään päivään älkää lähtekö ilmestysmajan ovelta, älkää ennen kuin vihkimispäivänne ovat kuluneet umpeen, sillä seitsemän päivää kestää vihkimisenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Niin kuin on tehty tänä päivänä, niin Herra on käskenyt vastakin tehdä toimittaakseen teille sovituksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Olkaa seitsemän päivää ilmestysmajan oven edustalla, päivät ja yöt, ja toimittakaa Herran palvelustehtävät, ettette kuolisi. Sillä niin on minulle käsky annettu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Aaron ja hänen poikansa tekivät kaiken, mitä Herra oli Mooseksen kautta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Kahdeksantena päivänä Mooses kutsui Aaronin, hänen poikansa ja Israelin vanhimmat');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'ja sanoi Aaronille: \"Ota itsellesi härkävasikka syntiuhriksi ja pässi polttouhriksi, molemmat virheettömiä, ja tuo ne Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Puhu israelilaisille ja sano: \'Ottakaa vuohipukki syntiuhriksi ja vasikka ja karitsa, molemmat vuoden vanhoja ja virheettömiä, polttouhriksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, '[Ottakaa] myös härkä ja pässi rauhanuhriksi, uhrattaviksi Herran edessä, sekä ruokauhri, johon on sekoitettu öljyä, sillä tänä päivänä ilmestyy teille Herra.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Niin he toivat, mitä Mooses oli käskenyt, ilmestysmajan edustalle, ja koko seurakunta astui esiin ja asettui Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Mooses sanoi: \"Näin Herra on käskenyt teidän tehdä, jotta Herran kirkkaus ilmestyisi teille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Mooses sanoi Aaronille: \"Astu alttarin luo, uhraa syntiuhrisi ja polttouhrisi ja toimita itsellesi ja kansalle sovitus sekä uhraa sitten kansan uhrilahja ja toimita heille sovitus, niin kuin Herra on käskenyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Aaron astui alttarin luo ja teurasti oman syntiuhrivasikkansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Aaronin pojat ojensivat hänelle veren. Hän kastoi sormensa vereen ja siveli sitä alttarin sarviin, mutta muun veren hän vuodatti alttarin juurelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Mutta syntiuhriteuraan rasvan ja munuaiset ja maksan takalohkon hän poltti alttarilla, niin kuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Lihan ja nahan hän poltti tulella leirin ulkopuolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Hän teurasti polttouhrin, ja Aaronin pojat ojensivat hänelle veren, ja hän vihmoi sen alttarin joka taholle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'He ojensivat hänelle polttouhrin paloina sekä pään, ja hän poltti ne alttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Hän pesi sisälmykset ja jalat ja poltti ne polttouhrin päällä alttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Sitten hän toi kansan uhrilahjan ja otti kansan syntiuhrivuohen, teurasti sen ja uhrasi sen syntiuhrina samalla tavalla kuin edellisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Hän toi myös polttouhrin ja uhrasi sen säädetyllä tavalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Hän toi ruokauhrin ja otti siitä täyden kourallisen ja poltti sen alttarilla aamupolttouhrin lisäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Hän teurasti härän ja pässin kansan rauhanuhriksi, ja Aaronin pojat ojensivat hänelle veren, ja hän vihmoi sen alttarin joka puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Mutta härän ja pässin rasvat, rasvahännän, rasvakalvon, munuaiset ja maksan takalohkon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'nämä rasvat he panivat rintalihojen päälle, ja hän poltti rasvat alttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Rintalihan ja oikean reiden heilutuksen Aaron toimitti Herran edessä, niin kuin Mooses oli käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Aaron kohotti kätensä kansaa kohti ja siunasi heidät. Kun hän oli toimittanut syntiuhrin, polttouhrin ja rauhanuhrin, hän astui alas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Mooses ja Aaron menivät ilmestysmajaan. Kun he tulivat sieltä ulos, he siunasivat kansan. Silloin Herran kirkkaus ilmestyi kaikelle kansalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Tuli lähti Herran luota ja kulutti polttouhrin ja rasvat alttarilta. Kaikki kansa näki sen, ja he riemuitsivat ja lankesivat kasvoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Aaronin pojat Naadab ja Abihu ottivat kumpikin hiilipannunsa ja virittivät niihin tulen ja panivat suitsuketta sen päälle ja toivat vierasta tulta Herran eteen vastoin hänen käskyään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Silloin tuli lähti Herran luota ja kulutti heidät, niin että he kuolivat Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Mooses sanoi Aaronille: \"Tämä tapahtuu Herran sanan mukaan: Niissä, jotka ovat minua lähellä, minä osoitan pyhyyteni ja kaiken kansan edessä kirkkauteni.\" – Mutta Aaron oli ääneti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Mooses kutsui Miisaelin ja Elsafanin, Aaronin sedän Ussielin pojat, ja sanoi heille: \"Astukaa esiin ja kantakaa sukulaisenne pyhäkön läheisyydestä leirin ulkopuolelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'He astuivat esiin ja kantoivat heidät viittoineen leirin ulkopuolelle, niin kuin Mooses oli sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Mooses sanoi Aaronille ja hänen pojilleen Eleasarille ja Iitamarille: \"Älkää päästäkö tukkaanne hajalle älkääkä repikö vaatteitanne, ettette kuolisi ja ettei hänen vihansa kohtaisi koko seurakuntaa. Mutta teidän veljenne, koko Israelin heimo, itkekööt tätä paloa, jonka Herra on sytyttänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Älkää poistuko ilmestysmajan ovelta, ettette kuolisi, sillä Herran voiteluöljy on teissä.\" He tekivät, niin kuin Mooses oli sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Herra puhui Aaronille sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, '\"Viiniä ja väkijuomaa älkää juoko, älä sinä älköötkä poikasi kanssasi, kun menette ilmestysmajaan, ettette kuolisi. Tämä olkoon teille ikuinen säädös sukupolvesta sukupolveen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'tehdäksenne erotuksen pyhän ja epäpyhän, saastaisen ja puhtaan välillä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'ja opettaaksenne israelilaisille kaikki ne käskyt, jotka Herra on heille puhunut Mooseksen kautta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Mooses puhui Aaronille ja hänen eloon jääneille pojilleen Eleasarille ja Iitamarille: \"Ottakaa Herran uhreista tähteeksi jäänyt ruokauhri ja syökää se happamattomana alttarin ääressä, sillä se on korkeasti pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Syökää se pyhässä paikassa, sillä se on sinun osuutesi ja poikiesi osuus Herran uhreista. Niin on minulle käsky annettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Heilutusrintaliha ja anniksi annettu reisi syökää puhtaassa paikassa, sinä ja poikasi ja tyttäresi kanssasi. Sillä ne ovat sinun osuudeksesi ja sinun poikiesi osuudeksi annetut israelilaisten rauhanuhriteuraista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Anniksi annettu reisi ja heilutusrintaliha tuotakoon uhrirasvojen kanssa ja toimitettakoon niiden heilutus Herran edessä. Ne olkoot sinun ja poikiesi ikuinen osuus, niin kuin Herra on käskenyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Mooses tiedusteli syntiuhripukkia, ja katso, se oli poltettu. Silloin hän vihastui Eleasariin ja Iitamariin, Aaronin eloon jääneille pojille, ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, '\"Miksi ette ole syöneet syntiuhria pyhässä paikassa? Sehän on korkeasti pyhä. Hän on antanut sen teille, että poistaisitte kansan syntivelan ja toimittaisitte heille sovituksen Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Katso, sen verta ei ole tuotu pyhäkköön sisälle. Teidän olisi tullut syödä se pyhäkössä, niin kuin olen käskenyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Mutta Aaron sanoi Moosekselle: \"Katso, he ovat tänä päivänä tuoneet syntiuhrinsa ja polttouhrinsa Herran eteen, ja kuitenkin on tämä minua kohdannut. Jos minä tänä päivänä söisin syntiuhria, olisikohan se Herralle otollista?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Sen kuultuaan Mooses hyväksyi sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Herra puhui Moosekselle ja Aaronille sanoen heille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, '\"Puhukaa israelilaisille ja sanokaa: Näitä eläimiä saatte syödä kaikista nelijalkaisista eläimistä maan päällä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Kaikkia nelijalkaisia eläimiä, joilla on kokonaan halkinaiset sorkat ja jotka märehtivät, saatte syödä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Näitä älkää kuitenkaan syökö niistä, jotka märehtivät, ja niistä, joilla on sorkat: Kameli, joka kyllä märehtii, mutta jolla ei ole sorkkia, olkoon teille saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Tamaani, joka tosin märehtii, mutta jolla ei ole sorkkia, olkoon teille saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Jänis, joka kyllä märehtii, mutta jolla ei ole sorkkia, olkoon teille saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Sika, jolla tosin on kokonaan halkinaiset sorkat, mutta joka ei märehdi, olkoon teille saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Näiden lihaa älkää syökö ja näiden raatoihin älkää koskeko. Ne olkoot teille saastaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Näitä saatte syödä kaikista vesieläimistä: te saatte syödä kaikkia, joilla on evät ja suomukset ja jotka elävät vedessä, niin hyvin merissä kuin joissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Mutta inhotkaa kaikkia niitä, joita vedet vilisevät, kaikkia veden eläviä, mutta joilla ei ole eviä eikä suomuksia, elivätpä merissä tai joissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Niitä inhotkaa. Älkää syökö niiden lihaa. Inhotkaa myös niiden raatoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Kaikkia niitä vesieläimiä, joilla ei ole eviä eikä suomuksia, inhotkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Linnuista taas inhotkaa seuraavia älkääkä niitä syökö, vaan olkoot ne teille iljettäviä: kotka, partakorppikotka ja hanhikorppikotka,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'haarahaukka ja muut haukat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'kaikki korpit,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'strutsi, pääskynen, lokki ja jalohaukkalajit,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'huuhkaja, kalasääski ja kissapöllö,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'sarvipöllö, pelikaani ja likakorppikotka,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'haikara ja sirriäislajit, harjalintu ja lepakko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Kaikkia siivellisiä pikkueläimiä, jotka liikkuvat neljällä jalalla, inhotkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Kuitenkin saatte siivellisistä pikkueläimistä, jotka liikkuvat neljällä jalalla, syödä niitä, joilla jalkaterien yläpuolella on kaksi säärtä hypelläkseen niillä maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Niistä saatte syödä seuraavia: heinäsirkkalajeja, solam-sirkkalajeja, hargol-sirkkalajeja ja haagab-sirkkalajeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Mutta kaikkia muita siivellisiä pikkueläimiä, joilla on neljä jalkaa, inhotkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Seuraavista eläimistä te tulette saastaisiksi. Jokainen, joka koskee niiden raatoihin, olkoon iltaan asti saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Jokainen, joka kantaa niiden raatoja, pesköön vaatteensa ja olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Kaikki nelijalkaiset eläimet, joilla on sorkat, mutta ei kokonaan halkinaiset, ja jotka eivät märehdi, olkoot teille saastaiset. Jokainen, joka koskee niihin, olkoon saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Kaikki nelijalkaiset eläimet, jotka kulkevat käpälillä, olkoot teille saastaisia. Jokainen, joka koskettaa niiden raatoja, olkoon iltaan asti saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Joka kantaa niiden raatoja, pesköön vaatteensa ja olkoon saastainen iltaan asti. Ne olkoot teille saastaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Myös nämä olkoot teille saastaisia niistä pikkueläimistä, jotka liikkuvat maassa: myyrä, hiiri ja sisiliskolajit,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'anaka-eläin, kooah-eläin, leeta-eläin, hoomet-eläin ja kameleontti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Ne olkoot teille saastaisia kaikista pikkueläimistä. Jokainen, joka niihin koskee, kun ne ovat kuolleet, olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Kaikki, minkä päälle jokin niistä kuolleena putoaa, on saastaista, olipa se sitten puuastia tai vaatekappale tai nahka tai säkki tai mikä tahansa tarvekalu. Se pantakoon veteen ja olkoon saastainen iltaan asti. Sitten se on puhdas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Jos jokin niistä putoaa saviastiaan, kaikki, mitä siinä on, on saastaista, ja astia rikottakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Kaikki ruoka, jota syödään, on saastaista, jos sen astian vettä tulee siihen, ja kaikki juoma, jota juodaan, on jokaisessa sellaisessa astiassa saastaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Kaikki, minkä päälle niiden raato putoaa, tulee saastaiseksi. Olkoonpa se leivinuuni tai liesi, revittäköön se maahan. Sillä saastaisia ne ovat ja saastaisia ne olkoot teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Kuitenkin lähde tai kaivo, paikka, johon vettä on kokoontunut, pysyy puhtaana. Mutta joka niiden raatoon koskee, olkoon saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Jos niiden raato putoaa kylvösiemenen päälle, minkä hyvänsä, joka kylvetään, pysyy tämä puhtaana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Mutta jos siemen on vedellä kasteltu ja niiden raato putoaa sen päälle, tulee siemen teille saastaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Jos jokin eläin, joka on teille ravinnoksi, kuolee, olkoon se, joka sen raatoon koskee, saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Joka syö sen raatoa, pesköön vaatteensa ja olkoon saastainen iltaan asti. Se, joka kantaa sen raatoa, pesköön vaatteensa ja olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Kaikki pikkueläimet, jotka liikkuvat maassa, olkoot inhottavia. Älköön niitä syötäkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Kaikista niistä, jotka kulkevat vatsallaan, ja kaikista pikkueläimistä, jotka liikkuvat maassa, kulkien neljällä tai useammalla jalalla, älkää syökö niistä mitään, sillä ne ovat inhottavia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Älkää saattako itseänne inhottaviksi koskettamalla matelevaa pikkueläintä, mitä tahansa, älkääkä saastuttako itseänne niillä, niin että tulette niistä saastaisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Sillä minä olen Herra, teidän Jumalanne. Pyhittäkää siis itsenne ja olkaa pyhät, sillä minä olen pyhä. Älkää saastuttako itseänne koskemalla mihinkään pikkueläimeen, joka liikkuu maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Sillä minä olen Herra, joka olen johdattanut teidät Egyptin maasta, ja joka olen teidän Jumalanne. Olkaa siis pyhät, sillä minä olen pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Tämä on laki nelijalkaisista eläimistä ja linnuista ja kaikista elollisista, joita vilisee vedessä, ja kaikista olennoista, joita liikkuu maassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'että tietäisitte erottaa puhtaat saastaisista ja syötävät eläimet niistä eläimistä, joita ei saa syödä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Sitten Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, '\"Puhu israelilaisille ja sano: Kun vaimo tulee hedelmälliseksi ja synnyttää pojan, olkoon saastainen seitsemän päivää. Hän olkoon saastainen yhtä monta päivää kuin hänen kuukautisensa kestävät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Kahdeksantena päivänä ympärileikattakoon pojan esinahan liha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Mutta vaimo pysyköön kotona kolmekymmentä kolme päivää puhdistavan verenvuotonsa aikana. Älköön koskeko mihinkään, mikä on pyhää. Älköön myöskään tulko pyhäkköön, ennen kuin hänen puhdistuspäivänsä ovat kuluneet umpeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Mutta jos hän synnyttää tytön, olkoon saastainen kaksi viikkoa samoin kuin kuukautisissaan, ja pysyköön kotona kuusikymmentä kuusi päivää puhdistavan verenvuotonsa aikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Mutta kun hänen puhdistuspäivänsä pojan tai tyttären jälkeen ovat kuluneet umpeen, vieköön vuoden vanhan karitsan polttouhriksi ja kyyhkysenpojan tai metsäkyyhkysen syntiuhriksi ilmestysmajan oven edustalle papille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Tämä tuokoon ne Herran eteen ja toimittakoon hänelle sovituksen, niin hän on puhdas verenvuodostaan. Tämä on laki lapsensynnyttäjästä, olipa hän synnyttänyt pojan tai tytön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Mutta jos hän ei saa hankituksi lammasta, ottakoon kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa, toisen polttouhriksi ja toisen syntiuhriksi. Sitten pappi toimittakoon hänelle sovituksen, niin hän on puhdas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, '\"Jos jonkun ihoon tulee nystyrä tai ihottuma tai vaalea pilkku, niin kuin spitaalilaikku olisi tulossa hänen ihoonsa, vietäköön hänet pappi Aaronin tai jonkun hänen poikansa, pappien, eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Jos pappi tutkiessaan laikkua iholla huomaa, että karvat laikussa ovat muuttuneet valkoisiksi ja että laikku näyttää muuta ihoa matalammalta, se on spitaalilaikku. Heti kun pappi on sen huomannut, julistakoon hänet saastaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Jos taas hänen ihollaan on valkea pilkku, mutta se ei näytä muuta ihoa matalammalta eivätkä karvat ole muuttuneet valkoisiksi, sulkekoon pappi laikkuisen sisälle seitsemäksi päiväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Seitsemäntenä päivänä pappi tarkastakoon hänet. Jos laikku hänestä näyttää pysyneen entisellään vaivan leviämättä ihossa, sulkekoon pappi hänet sisälle vielä seitsemäksi päiväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Seitsemäntenä päivänä pappi tutkikoon hänet uudestaan. Jos hän huomaa, että laikku on käynyt vaaleaksi ja että laikku ei ole ihossa levinnyt, julistakoon pappi hänet puhtaaksi, sillä se on ihottumaa. Pesköön vaatteensa, ja niin hän on puhdas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Mutta jos ihottuma leviää leviämistään hänen ihollaan, sen jälkeen kun hän oli näyttäytynyt papille tullakseen puhtaaksi julistetuksi, näyttäytyköön uudestaan papille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Jos pappi huomaa ihottuman levinneen iholla, julistakoon pappi hänet saastaiseksi. Se on spitaalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Jos spitaalilaikku ilmestyy ihmiseen, vietäköön hänet papin luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Jos pappi tutkiessaan huomaa iholla valkoisen nystyrän, jonka kohdalta karvat ovat muuttuneet valkoisiksi, ja liikaa lihaa kasvavan nystyrän,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'on hänen ihollaan jo vanha spitaali, ja sen tähden pappi julistakoon hänet saastaiseksi älköönkä enää sulkeko häntä sisälle, sillä hän on saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Jos taas spitaali puhkeaa iholla, niin että se peittää koko ihon päästä jalkoihin asti, minne pappi katsookin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'ja jos pappi tutkiessaan huomaa spitaalin peittävän koko ihon, julistakoon hänet puhtaaksi. Hän on kokonaan muuttunut valkoiseksi ja on puhdas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Mutta niin pian kuin häneen ilmestyy verestävää lihaa, hän on saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Kun pappi huomaa verestävän lihan, julistakoon hänet saastaiseksi. Verestävä liha on saastaista. Se on spitaalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Mutta jos verestävä liha häviää ja paikka muuttuu valkoiseksi, menköön papin luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Jos pappi huomaa, että paikka on muuttunut valkoiseksi, julistakoon hänet puhtaaksi. Hän on puhdas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Jos jonkun ihoon tulee paise, joka paranee,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'ja paiseen tilalle tulee valkoinen nystyrä tai vaaleanpunainen pilkku, näyttäytyköön papille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Jos pappi tutkiessaan huomaa, että paikka näyttää muuta ihoa matalammalta ja että karvat siinä ovat muuttuneet valkoisiksi, julistakoon hänet saastaiseksi. Paiseeseen on puhjennut spitaali.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Mutta jos pappi tutkiessaan huomaa, ettei siinä ole valkoisia karvoja ja ettei paikka ole muuta ihoa matalampi ja että se on käynyt vaaleaksi, sulkekoon hänet sisälle seitsemäksi päiväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Jos se leviää leviämistään hänen ihollaan, julistakoon pappi hänet saastaiseksi. Se on spitaalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Mutta jos laikku pysyy ennallaan laajenematta, se on paiseen arpi. Pappi julistakoon hänet puhtaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Jos taas joku saa palohaavan ihoonsa ja palohaavaan kasvavaan lihaan ilmestyy vaaleanpunainen tai valkoinen pilkku,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'ja jos pappi tutkiessaan huomaa laikun karvojen muuttuneen valkoisiksi ja paikan näyttävän muuta ihoa matalammalta, niin palohaavaan on puhjennut spitaali. Pappi julistakoon hänet saastaiseksi. Se on spitaalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Mutta jos pappi tutkiessaan huomaa, ettei pilkussa ole valkoisia karvoja eikä se ole muuta ihoa matalampi ja että se on käynyt vaaleaksi, sulkekoon hänet sisälle seitsemäksi päiväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Seitsemäntenä päivänä pappi tutkikoon hänet. Jos se on yhä levinnyt iholla, julistakoon hänet saastaiseksi. Se on spitaalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Mutta jos pilkku on pysynyt alallaan eikä ole levinnyt iholla ja on edelleen vaalennut, se on palohaavasta syntynyt nystyrä. Pappi julistakoon hänet puhtaaksi. Se on palohaavan arpi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Jos mieheen tai naiseen tulee läikkä päähän tai partaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'ja jos pappi tutkiessaan läikkää huomaa, että se näyttää muuta ihoa matalammalta ja että siinä on ohuita, kellertäviä karvoja, julistakoon hänet saastaiseksi. Se on spitaalisyyhyä. Se on pää- tai partaspitaalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Jos pappi tutkiessaan paikkaa huomaa, ettei se näytä muuta ihoa matalammalta, mutta ettei siinä ole mustia karvoja, sulkekoon syyhyisen sisälle seitsemäksi päiväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Jos pappi seitsemäntenä päivänä tutkiessaan läikkää huomaa, ettei syyhy ole levinnyt ja ettei siinä ole kellertäviä karvoja ja ettei syyhy näytä muuta ihoa matalammalta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'tutkittava ajakoon hiuksensa tai partansa, kuitenkaan ajamatta läikkää, ja pappi sulkekoon syyhyisen sisälle vielä seitsemäksi päiväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Jos pappi seitsemäntenä päivänä tutkiessaan läikkää huomaa, ettei syyhy ole levinnyt iholla ja ettei se näytä muuta ihoa matalammalta, julistakoon hänet puhtaaksi. Hän pesköön vaatteensa, ja niin hän on puhdas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Mutta jos syyhy leviää leviämistään iholla, sen jälkeen kun hänet julistettiin puhtaaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'ja jos pappi tutkiessaan häntä huomaa, että syyhy on levinnyt iholla, älköön pappi enää etsikö kellertäviä karvoja. Hän on saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Mutta jos syyhy näyttää hänestä pysyneen entisellään ja jos siihen on kasvanut mustia karvoja, syyhy on parantunut. Hän on puhdas. Pappi julistakoon hänet puhtaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Jos miehen tai naisen ihoon tulee pilkkuja, jotka ovat valkoisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'ja jos pappi tutkiessaan huomaa vaalenevia, valkoisia pilkkuja heidän ihollaan, se on vaaratonta valkoista ihottumaa, joka on puhjennut ihoon. Hän on puhdas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Jos hiukset lähtevät miehen päästä takaraivolta, hän on takakalju. Hän on puhdas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Jos taas hiukset lähtevät päästä ohimoista, hän on otsakalju. Hän on puhdas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Mutta jos vaaleanpunainen laikku ilmestyy takaraivon tai otsapuolen paljaaseen paikkaan, se on spitaalia, joka on puhkeamassa takaraivon tai otsapuolen paljaaseen kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Jos pappi tutkiessaan häntä huomaa, että nystyrä takaraivon tai otsapuolen paljaassa kohdassa on vaaleanpunainen näyttäen samanlaiselta kuin spitaali muussa ihossa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'mies on spitaalinen ja saastainen. Pappi julistakoon hänet heti saastaiseksi hänen päässään olevan läikän tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Jolla on spitaali, käyköön rikkirevityissä vaatteissa, tukka hajalla ja parta peitettynä ja huutakoon: \'Saastainen, saastainen!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Niin kauan kuin ihomuutos hänessä on, hän olkoon saastainen. Koska hän on saastainen, asukoon yksinään. Hänen asuinpaikkansa olkoon leirin ulkopuolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Jos spitaalilaikku tulee vaatteeseen, olipa vaate villainen tai pellavainen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'tai kudottuun tai solmustettuun kankaaseen, olipa se pellavaa tai villaa, tai nahkaa tai mikä tahansa nahasta tehty esine,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'ja jos laikku näyttää vihertävältä tai punertavalta vaatekappaleessa, nahassa, kudotussa tai solmustetussa kankaassa tai missä nahasta tehdyssä esineessä tahansa, se on spitaalia. Se on näytettävä papille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Kun pappi on tutkinut laikun, sulkekoon esineen sisälle seitsemäksi päiväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Jos hän seitsemäntenä päivänä tutkiessaan laikun huomaa, että laikku on levinnyt vaatteessa tai kudotussa tai solmustetussa kankaassa tai nahassa tai mihin nahasta tehdyssä esineessä tahansa, laikku on pahanlaatuista spitaalia. Ne ovat saastaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Polttakoon vaatteen tai kudotun tai solmustetun kankaan, olipa se villaa, pellavaa tai nahasta tehty esine, tai olipa se mikä tahansa, jossa laikku on, sillä se on pahanlaatuista spitaalia. Kaikki sellainen poltettakoon tulessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Mutta jos pappi tarkastaessaan huomaa, ettei laikku ole levinnyt vaatekappaleessa, kudotussa tai solmustetussa kankaassa tai nahasta tehdyssä esineessä, olipa se mikä tahansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'käskeköön pestä esineen, jossa laikku on, ja sulkekoon sen sisälle vielä seitsemäksi päiväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Jos pappi tarkastaessaan esinettä, sen jälkeen kun se on pesty, huomaa, ettei laikku ole muuttunut näöltään, esine, vaikka laikku ei olekaan levinnyt, on saastainen. Se poltettakoon tulessa. Se on spitaalin syömä, olkoon sitten nurjalta tai oikealta puolelta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Mutta jos pappi tutkiessaan huomaa, että laikku on pesemisen jälkeen vaalennut, reväisköön sen pois vaatekappaleesta, nahasta tai kudotusta tai solmustetusta kankaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Jos sitten vielä laikku ilmestyy vaatekappaleeseen, kudottuun tai solmustettuun kankaaseen tai mihin nahasta tehtyyn esineeseen tahansa, se on puhkeavaa spitaalia. Esine, jossa laikku on, poltettakoon tulessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Mutta vaatekappale, kudottu tai solmustettu kangas tai mikä nahasta tehty esine tahansa, josta laikku on pesemällä kadonnut, pestäköön vielä kerran, ja niin se on puhdas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Tämä on laki spitaalilaikusta vaatteessa, villaisessa tai pellavaisessa, kudotussa tai solmustetussa kankaassa tai missä nahasta tehdyssä esineessä tahansa. Tämä on laki niiden puhtaiksi tai saastaisiksi julistamisesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Sitten Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, '\"Tämä olkoon laki spitaalisen puhdistamispäivästä. Hänet tuotakoon papin luo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'ja pappi menköön leirin ulkopuolelle. Jos pappi tarkastaessaan spitaalista huomaa, että hän on parantunut spitaaliläikästä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'käskeköön pappi puhdistettavaa varten ottamaan kaksi elävää, puhdasta lintua, setripuuta, helakanpunaista lankaa ja iisoppikorren.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Pappi käskeköön teurastamaan toisen linnun saviastian päällä, jossa on raikasta vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Sitten hän ottakoon elävän linnun ja setripuun, helakanpunaisen langan ja iisoppikorren ja kastakoon ne sekä elävän linnun sen linnun vereen, joka teurastettiin raikkaan veden päällä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'ja pirskottakoon sitä seitsemän kertaa siihen, joka on spitaalista puhdistettava. Puhdistettuaan hänet päästäköön elävän linnun lentämään kedolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Puhdistettava pesköön vaatteensa, ajakoon kaikki hiuksensa ja peseytyköön vedessä, niin hän on puhdas. Sen jälkeen hän saa mennä leiriin. Asukoon kuitenkin telttansa ulkopuolella seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Ajakoon seitsemäntenä päivänä kaikki hiukset päästään, partansa ja kulmakarvansa. Ajakoon kaikki karvansa. Pesköön sitten vaatteensa ja ruumiinsa vedessä, niin hän on puhdas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Kahdeksantena päivänä ottakoon kaksi virheetöntä karitsaa ja virheettömän, vuoden vanhan uuhikaritsan sekä ruokauhriksi kolme kymmenennestä ydinjauhoja, joihin on sekoitettu öljyä, ja yhden loog-mitan öljyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Puhdistusta toimittava pappi asettakoon puhdistettavan henkilön ja nämä esineet Herran eteen ilmestysmajan ovelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Sitten pappi ottakoon toisen karitsan ja tuokoon sen vikauhriksi sekä loog-mitan öljyä, ja toimittakoon niiden heilutuksen Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Teurastakoon sitten karitsan siinä paikassa, jossa syntiuhri- ja polttouhriteuraat teurastetaan, pyhässä paikassa, sillä vikauhri on kuten syntiuhrikin papin. Se on korkeasti pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Pappi ottakoon vikauhrin verta ja sivelköön sitä puhdistettavan oikeaan korvalehteen sekä oikean käden peukaloon ja oikean jalan isoonvarpaaseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Sen jälkeen pappi ottakoon öljyä loog-mitasta ja kaatakoon sitä vasempaan käteensä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'ja kastakoon oikean kätensä etusormen öljyyn, jota on hänen vasemmassa kädessään, ja pirskottakoon öljyä sormellaan seitsemän kertaa Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Käteensä jäänyttä öljyä pappi sivelköön puhdistettavan oikeaan korvalehteen sekä oikean käden peukaloon ja oikean jalan isoonvarpaaseen vikauhrin veren päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Käteensä vielä jääneen öljyn pappi sivelköön puhdistettavan päähän. Näin pappi toimittakoon hänelle sovituksen Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Sitten pappi uhratkoon syntiuhrin ja toimittakoon puhdistettavalle sovituksen hänen saastaisuudestaan ja sen jälkeen teurastakoon polttouhriteuraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Pappi uhratkoon polttouhrin ja ruokauhrin alttarilla. Kun pappi on toimittanut hänelle sovituksen, hän on puhdas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Mutta jos hän on köyhä eikä saa hankituksi niin paljoa, ottakoon vain yhden karitsan vikauhriksi heilutettavaksi toimittaakseen itselleen sovituksen, sekä ruokauhriksi vain yhden kymmenenneksen ydinjauhoja, joihin on sekoitettu öljyä ja loog-mitan öljyä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'sekä kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa, mikäli hän on voinut ne hankkia. Toinen olkoon syntiuhriksi ja toinen polttouhriksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Vieköön ne papille puhdistustaan varten kahdeksantena päivänä ilmestysmajan ovelle Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Pappi ottakoon vikauhrikaritsan ja loog-mitan öljyä ja toimittakoon niiden heilutuksen Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Vikauhrikaritsa teurastettakoon, ja pappi ottakoon vikauhrin verta ja sivelköön sitä puhdistettavan oikeaan korvalehteen sekä oikean käden peukaloon ja oikean jalan isoonvarpaaseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Sitten pappi kaatakoon öljyä vasempaan käteensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'ja pappi pirskottakoon oikealla etusormellaan öljyä, jota on hänen vasemmassa kädessään, seitsemän kertaa Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Käteensä jäänyttä öljyä pappi sivelköön puhdistettavan oikeaan korvalehteen sekä oikean käden peukaloon ja oikean jalan isoonvarpaaseen, siihen paikkaan, missä on vikauhrin verta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Käteensä vielä jääneen öljyn pappi sivelköön puhdistettavan päähän toimittaakseen hänelle sovituksen Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Hän uhratkoon toisen niistä metsäkyyhkysistä tai kyyhkysenpojista, jotka hän on hankkinut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'mikäli on voinut ne hankkia, toisen syntiuhriksi ja toisen polttouhriksi ruokauhrin ohella. Pappi toimittakoon puhdistettavalle sovituksen Herran edessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Tämä on laki spitaalisesta, joka ei pysty hankkimaan puhdistukseen sitä, mikä on säädetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Sitten Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, '\"Kun tulette Kanaanin maahan, jonka minä annan teille perintömaaksi, ja minä sallin spitaalin tulla johonkin taloon siinä maassa, jonka saatte perintömaaksenne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'talon omistaja menköön ja ilmoittakoon sen papille sanoen: \'Minun talooni näyttää ilmestyneen jotakin spitaalilaikun tapaista.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Pappi käskeköön tyhjentää talon, ennen kuin menee tutkimaan laikkua, ettei kaikki, mitä talossa on, tulisi saastaiseksi. Sitten pappi menköön tutkimaan laikkua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Jos hän tutkiessaan laikkua näkee laikun kohdalla talon seinissä vihertäviä tai punertavia syvennyksiä, jotka näyttävät muuta seinää matalammilta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'menköön talosta ulos talon ovelle ja sulkekoon talon seitsemäksi päiväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Jos pappi palattuaan seitsemäntenä päivänä tarkastaessaan huomaa laikun levinneen talon seinissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'käskeköön murtaa pois ne kivet, joissa laikkua on, ja heittää ne ulos kaupungista saastaiseen paikkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Talo kaavittakoon sisältä ympäriinsä puhtaaksi, ja kaavittu savi heitettäköön ulos kaupungista saastaiseen paikkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Sitten otettakoon uusia kiviä ja pantakoon entisten kivien sijaan, ja otettakoon uutta savea ja savettakoon talo sillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Jos laikku ilmestyy taloon uudestaan, sen jälkeen kun kivet ovat murretut pois ja talo on puhtaaksi kaavittu ja uudelleen savettu,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'menköön pappi sisälle, ja jos hän tarkastaessaan huomaa laikun levinneen talossa, niin talossa on pahanlaatuinen spitaali. Se on saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Sen tähden talo revittäköön, sekä sen kivet että puuaines ja kaikki sen savi, ja vietäköön ne ulos kaupungista saastaiseen paikkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Se, joka on käynyt talossa sinä aikana, jona sen oli oltava suljettuna, olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Se, joka on maannut siinä talossa, pesköön vaatteensa, ja se, joka on syönyt talossa, pesköön vaatteensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Mutta jos pappi menee sisälle ja tarkastaessaan huomaa, ettei laikku ole levinnyt talossa sen saveamisen jälkeen, julistakoon pappi talon puhtaaksi, sillä tartunta on hävinnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Ottakoon kaksi lintua, setripuuta, helakanpunaista lankaa ja iisoppikorren talon puhdistamista varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Teurastakoon toisen linnun saviastian päällä, jossa on raikasta vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Ottakoon setripuun, iisoppikorren ja helakanpunaisen langan ja elävän linnun, kastakoon ne teurastetun linnun vereen ja raikkaaseen veteen ja pirskottakoon sitä taloon seitsemän kertaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Puhdistakoon näin talon linnun verellä ja raikkaalla vedellä, elävällä linnulla, setripuulla, iisoppikorrella ja helakanpunaisella langalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Päästäköön sitten elävän linnun lentämään kaupungin ulkopuolelle kedolle. Toimitettuaan talolle sovituksen, se on puhdas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Tämä on laki kaikkinaisesta spitaalista ja syyhystä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'spitaalista vaatteissa ja taloissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'nystyröistä, ihottumista ja vaaleista pilkuista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'neuvoksi siitä, milloin mikin on saastainen, milloin puhdas. Tämä on laki spitaalista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Sitten Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, '\"Puhukaa israelilaisille ja sanokaa heille: Jos jollakulla, kenellä tahansa, on elimestään liman vuoto, hänen vuotonsa on saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Hänen vuotonsa saastaisuus on sellainen, että hän, sekä silloin, kun hänen elimestään vuotaa, että silloin, kun hänen elimensä pidättää vuodon, on saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Jokainen vuode, jossa se lepää, jolla on vuoto, tulee saastaiseksi, ja jokainen istuin, jolla hän istuu, tulee saastaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Joka koskee hänen vuoteeseensa, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Joka istuu istuimelle, jolla on istunut sellainen, jolla on vuoto, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Joka koskee sellaisen ruumiiseen, jolla on vuoto, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Jos se, jolla on vuoto, sylkee puhtaan ihmisen päälle, tämä pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Jokainen satula, jossa sellainen, jolla on vuoto, ratsastaa, tulee saastaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Jokainen, joka koskee mihin hyvänsä, mikä on ollut hänen allaan, olkoon saastainen iltaan asti. Joka sellaista kantaa, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Jokainen, johon sellainen, jolla on vuoto, koskee, ennen kuin on huuhtonut kätensä vedessä, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Saviastia, johon sellainen, jolla on vuoto, koskee, rikottakoon, mutta jokainen puuastia huuhdottakoon vedessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Kun se, jolla on ollut vuoto, tulee puhtaaksi vuodostaan, laskekoon puhdistumisestaan seitsemän päivää ja sitten pesköön vaatteensa ja pesköön ruumiinsa raikkaassa vedessä, niin hän on puhdas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Ottakoon kahdeksantena päivänä kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa ja tulkoon Herran eteen ilmestysmajan ovelle ja antakoon ne papille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Pappi uhratkoon ne, toisen syntiuhriksi ja toisen polttouhriksi. Näin pappi toimittakoon Herran edessä hänelle sovituksen hänen vuodostaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Kun miehellä on ollut siemenvuoto, pesköön koko ruumiinsa vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Jokainen vaate ja jokainen nahka, johon siemenvuotoa on tullut, pestäköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Kun mies on maannut naisen kanssa ja vuodattanut siemenensä, peseytykööt vedessä ja olkoot saastaiset iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Kun naisella on vuoto, niin että verta vuotaa hänen ruumiistaan, olkoon kuukautistilassaan seitsemän päivää, ja jokainen, joka häneen koskee, olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Kaikki, minkä päällä hän lepää kuukautistilansa aikana, tulee saastaiseksi, ja kaikki, minkä päällä hän istuu, tulee saastaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Jokainen, joka koskee hänen vuoteeseensa, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Jokainen, joka koskee istuimeen, mihin hyvänsä, jolla hän on istunut, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Jos joku koskee esineeseen, joka on hänen vuoteellaan tai istuimella, jolla hän on istunut, olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Jos mies makaa hänen kanssaan ja hänen kuukautistaan tulee hänen päälleen, olkoon saastainen seitsemän päivää, ja jokainen vuode, jolla mies lepää, tulee saastaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Jos naisen verenvuoto kestää kauan aikaa, vaikka ei ole hänen kuukautisaikansa, tai jos se jatkuu hänen kuukautisaikansa ohi, pidettäköön hänet koko vuotonsa ajan saastaisena kuten hänen kuukautisaikanaankin. Hän on saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Jokaisesta vuoteesta, jolla hän lepää vuotonsa aikana, olkoon voimassa, mitä on säädetty hänen kuukautisaikana käyttämästään vuoteesta. Jokainen istuin, jolla hän istuu, tulee saastaiseksi kuten hänen kuukautisaikanaankin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Jokainen, joka niihin koskee, tulee saastaiseksi. Hän pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Mutta kun hän tulee puhtaaksi vuodostaan, laskekoon seitsemän päivää, ja sitten hän on puhdas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Ottakoon kahdeksantena päivänä kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa ja tuokoon ne papille ilmestysmajan ovelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Pappi uhratkoon toisen syntiuhriksi ja toisen polttouhriksi. Näin pappi toimittakoon Herran edessä hänelle sovituksen hänen saastaisesta vuodostaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Näin teidän on varoitettava israelilaisia saastaisuudesta, etteivät he saastaisuudessaan kuolisi, jos saastuttavat minun asumukseni, joka on heidän keskellään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Tämä on laki miehestä, jolla on vuoto, ja miehestä, jolla on siemenvuoto ja joka tulee siitä saastaiseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'ja naisesta, jolla on kuukautisensa, ja miehestä ja naisesta, joilla on jotakin vuotoa, sekä miehestä, joka makaa saastaisen naisen kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Herra puhui Moosekselle sen jälkeen, kun Aaronin kaksi poikaa oli kuollut, ne, joita kuolema oli kohdannut, kun he astuivat Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Herra sanoi Moosekselle: \"Sano veljellesi Aaronille: hänen ei tule joka aika mennä pyhimpään esiripun sisäpuolelle armoistuimen eteen, joka on arkin päällä, ettei hän kuolisi, sillä minä ilmestyn pilvessä armoistuimen kohdalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Mutta näin Aaron menköön pyhimpään: hänellä olkoon mukanaan mulli syntiuhriksi ja pässi polttouhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'ja pukekoon pyhän pellavaihokkaan ylleen, peittäköön häpynsä pellavahousuilla, vyöttäköön itsensä pellavavyöllä ja pankoon pellavaisen turbaanin päähänsä. Nämä ovat pyhät vaatteet. Pesköön ruumiinsa vedessä ja pukekoon ne ylleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Ottakoon israelilaisten seurakunnalta kaksi pukkia syntiuhriksi ja yhden pässin polttouhriksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Aaron tuokoon oman syntiuhrimullinsa ja toimittakoon sovituksen itselleen ja perheelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Ottakoon sitten ne kaksi vuohipukkia ja asettakoon ne Herran eteen ilmestysmajan ovelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Aaron heittäköön arpaa niistä kahdesta vuohesta: toisen arvan Herralle ja toisen vapauteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Aaron tuokoon vuohen, jonka arpa määräsi Herralle, ja uhratkoon sen syntiuhriksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Mutta vuohi, jonka arpa määräsi vapauteen, asetettakoon elävänä Herran eteen, että sille toimitettaisiin sovitus ja se sitten päästettäisiin erämaahan vapauteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Sen jälkeen Aaron tuokoon oman syntiuhrimullinsa ja toimittakoon sovituksen itselleen ja perheelleen ja teurastakoon oman syntiuhrimullinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Ottakoon sitten hiilipannun täyteen tulisia hiiliä alttarilta, joka on Herran edessä, ja kouransa täyteen survottua hyvänhajuista suitsuketta ja vieköön ne esiripun sisäpuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Pankoon sitten suitsukkeen tulen päälle Herran eteen, niin että suitsutus peittää pilvenä lain arkin päällä olevan armoistuimen, ettei hän kuolisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Ottakoon sitten mullin verta ja pirskottakoon sitä sormellaan armoistuimen etupuolelle. Pirskottakoon sitten armoistuimen eteen sormellaan verta seitsemän kertaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Teurastakoon sitten kansan syntiuhripukin ja vieköön sen verta esiripun sisäpuolelle ja tehköön sen verellä, niin kuin hän teki mullin verellä: pirskottakoon sitä armoistuimelle ja armoistuimen eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Toimittakoon pyhäkölle sovituksen israelilaisten saastaisuudesta ja heidän rikoksistaan, kaikista heidän synneistään. Tehköön samoin myös ilmestysmajalle, joka on heidän luonaan keskellä heidän saastaisuuttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Älköön ketään olko ilmestysmajassa, kun hän tulee toimittamaan sovitusta pyhimmässä, siihen asti kunnes hän sieltä lähtee ja on toimittanut sovituksen itselleen, perheelleen ja koko Israelin seurakunnalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Menköön sieltä sitten alttarin luo, joka on Herran edessä, ja toimittakoon sille sovituksen. Ottakoon mullin verta ja vuohipukin verta ja sivelköön sitä alttarin sarviin joka puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Pirskottakoon sormellaan sen päälle verta seitsemän kertaa ja puhdistakoon ja pyhittäköön sen israelilaisten saastaisuudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Kun hän on toimittanut valmiiksi pyhäkön ja ilmestysmajan ja alttarin sovituksen, tuokoon elävän vuohipukin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Aaron laskekoon molemmat kätensä elävän vuohen pään päälle ja tunnustakoon siinä kaikki israelilaisten pahat teot, kaikki heidän rikoksensa ja kaikki heidän syntinsä ja pankoon ne vuohen pään päälle ja lähettäköön sen sitä varten varatun miehen viemänä erämaahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Näin vuohi kantakoon kaikki heidän pahat tekonsa autioon seutuun, ja vuohi päästettäköön erämaahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Aaron menköön ilmestysmajaan ja riisukoon päältään pellavavaatteet, jotka hän oli pukenut ylleen mennessään pyhäkköön, ja jättäköön ne sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Pesköön sitten pyhässä paikassa ruumiinsa vedellä ja pukekoon ylleen omat vaatteensa. Lähteköön sitten sieltä ja uhratkoon sekä oman polttouhrinsa että kansan polttouhrin ja toimittakoon sekä itselleen että kansalle sovituksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Polttakoon sitten syntiuhrin rasvan alttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Se, joka päästi vuohen vapauteen, pesköön vaatteensa ja myös ruumiinsa vedellä, ja tulkoon vasta sitten leiriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Syntiuhrimulli ja syntiuhripukki, joiden veri tuotiin sovitukseksi pyhäkköön, vietäköön leirin ulkopuolelle, ja niiden nahka, liha ja ruokasula poltettakoon tulessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Se, joka ne polttaa, pesköön sekä vaatteensa että ruumiinsa vedessä, ja tulkoon vasta sitten leiriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Tämä olkoon teille ikuinen säädös: seitsemännessä kuussa, kuukauden kymmenentenä päivänä kurittakaa itseänne paastolla älkääkä toimittako yhtään askaretta, älköön maassa syntynyt älköönkä muukalainen, joka asuu keskellänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Sillä sinä päivänä toimitetaan teille sovitus teidän puhdistamiseksenne. Te tulette puhtaiksi kaikista synneistänne Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Se olkoon teille levon päivä. Kurittakaa silloin itseänne paastolla. Se olkoon ikuinen säädös.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Sovituksen toimittakoon pappi, joka on voideltu ja joka on vihitty papinvirkaan isänsä sijaan. Hän pukekoon ylleen pellavavaatteet, pyhät vaatteet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'ja toimittakoon sovituksen kaikkeinpyhimmälle ja sovituksen ilmestysmajalle ja alttarille sekä sovituksen myös papeille ja kaikelle seurakunnan kansalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Olkoon tämä teille ikuisena säädöksenä, niin että toimitatte israelilaisille sovituksen kaikista heidän synneistään kerran vuodessa.\" Niin Aaron teki, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, '\"Puhu Aaronille ja hänen pojilleen ja kaikille israelilaisille ja sano heille: Näin on Herra käskenyt sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Kuka ikinä Israelin heimosta teurastaa härän tai karitsan tai vuohen leirissä tai leirin ulkopuolella');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'eikä tuo sitä ilmestysmajan ovelle antaakseen sen uhrilahjana Herralle Herran asumuksen edessä, hänet pidettäköön vereen vikapäänä. Hän on vuodattanut verta. Mies hävitettäköön kansastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Sen tähden israelilaiset tuokoot uhriteuraansa, jotka he ovat teurastaneet kedolla, Herran eteen ilmestysmajan ovelle papille, ja siellä uhratkoot ne rauhanuhriksi Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Pappi vihmokoon veren Herran alttarille ilmestysmajan oven edessä ja polttakoon rasvan suloiseksi tuoksuksi Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Älkööt he enää uhratko uhrejaan pukeille, joiden jäljessä he kulkevat haureudessa. Tämä olkoon heille ikuinen säädös sukupolvesta sukupolveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Sano heille: Kuka ikinä Israelin heimosta tai muukalaisista, jotka asuvat keskuudessanne, uhraa polttouhrin tai teurasuhrin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'eikä tuo sitä ilmestysmajan ovelle, Herralle uhrattavaksi, se mies hävitettäköön kansastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Kuka ikinä Israelin heimosta tai muukalaisista, jotka asuvat teidän keskuudessanne, syö verta, mitä tahansa, minä käännän kasvoni sitä ihmistä vastaan, joka syö verta, ja hävitän hänet kansastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Sillä lihan henki on sen veri, ja minä olen antanut sen teille alttarille, että se tuottaisi teille sovituksen. Sillä veri tuottaa sovituksen, koska elämä on siinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Sen tähden minä olen sanonut israelilaisille: Älköön kukaan teistä syökö verta. Älköön myöskään muukalainen, joka asuu keskuudessanne, syökö verta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Kuka ikinä Israelin heimosta tai muukalaisista, jotka asuvat keskuudessanne, saa pyydystetyksi syötävän metsäeläimen tai linnun, vuodattakoon sen veren maahan ja peittäköön multaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Sillä kaiken lihan henki on sen veressä sen eläessä. Sen tähden minä sanon israelilaisille: Älkää syökö minkään lihan verta. Sillä kaiken lihan henki on sen veri. Jokainen, joka sitä syö, hävitettäköön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Jokainen, olipa hän maassa syntynyt tai muukalainen, joka syö itsestään kuollutta tai kuoliaaksi raadeltua eläintä, pesköön vaatteensa ja peseytyköön vedellä ja olkoon saastainen iltaan asti. Niin hän tulee puhtaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Mutta jos hän ei pese vaatteitaan eikä pese ruumistaan, hän joutuu syynalaiseksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Sitten Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, '\"Puhu israelilaisille ja sano heille: Minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Älkää tehkö, kuten tehdään Egyptin maassa, jossa asuitte. Älkää myöskään tehkö, niin kuin tehdään Kanaanin maassa, johon minä teidät vien. Älkää vaeltako heidän tapojensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Vaan seuratkaa minun säädöksiäni ja noudattakaa minun käskyjäni vaeltaaksenne niiden mukaan. Minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Noudattakaa käskyjäni ja säädöksiäni, sillä se ihminen, joka ne pitää, on niistä elävä. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Älköön kukaan teistä yhtykö veriheimolaiseensa paljastaakseen hänen häpynsä. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Isäsi häpyä ja äitisi häpyä älä paljasta. Hän on äitisi, älä hänen häpyään paljasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Älä paljasta äitipuolesi häpyä, se on isäsi häpy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Älä paljasta sisaresi häpyä, olipa hän isäsi tytär tai äitisi tytär, kotona tai sen ulkopuolella syntynyt. Älä paljasta heidän häpyään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Älä paljasta poikasi tyttären tai tyttäresi tyttären häpyä, sillä se on oma häpysi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Älä paljasta äitipuolesi tyttären häpyä, tyttären, joka on isällesi syntynyt. Hän on sisaresi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Älä paljasta isäsi sisaren häpyä. Hän on isäsi veriheimolainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Älä paljasta äitisi sisaren häpyä, sillä hän on äitisi veriheimolainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Älä paljasta setäsi häpyä, älä ryhdy hänen vaimoonsa. Hän on tätisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Älä paljasta miniäsi häpyä. Hän on poikasi vaimo, älä paljasta hänen häpyään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Älä paljasta veljesi vaimon häpyä. Se on veljesi häpy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Älä paljasta kenenkään muun veriheimolaisvaimon ja hänen tyttärensä häpyä, äläkä ota vaimoksi hänen poikansa tytärtä tai tyttärensä tytärtä paljastaaksesi hänen häpynsä, sillä he ovat veriheimolaisia. Se on sukurutsausta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Älä ota vaimosi eläessä hänen sisartaan vaimoksesi ja paljasta hänen häpyään, sillä se tuo riidan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Älä yhdy vaimoon paljastaaksesi hänen häpynsä, kun hän on saastainen kuukautisaikanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Älä makaa lähimmäisesi vaimon kanssa, ettet saastuttaisi itseäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Älä anna lapsiasi poltettaviksi uhrina Molokille, ettet häpäisisi Jumalasi nimeä. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Älä makaa miehenpuolen kanssa, niin kuin naisen kanssa maataan. Se on kauhistus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Älä sekaannu mihinkään eläimeen, ettet siten saastuttaisi itseäsi. Älköön nainen tarjoutuko eläimelle pariutuakseen sen kanssa. Se on iljettävyys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Älkää saastuttako itseänne millään näistä, sillä näillä kaikilla ovat itsensä saastuttaneet ne kansat, jotka minä karkotan teidän tieltänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Maa saastui, ja minä kostin sille sen pahat teot, niin että maa oksensi ulos asukkaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Sen tähden noudattakaa minun käskyjäni ja säädöksiäni älkääkä tehkö mitään näistä kauhistuksista, älköön maassa syntynyt älköönkä muukalainen, joka asuu teidän keskuudessanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Sillä kaikkia näitä kauhistuksia tekivät tämän maan asukkaat, jotka olivat ennen teitä, niin että maa saastui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Älkää niitä tehkö, ettei maa oksentaisi teitäkin ulos, jos te sen saastutatte, niin kuin se oksensi ulos kansan, joka oli ennen teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Sillä jokainen, joka tekee minkä tahansa näistä kauhistuksista, hävitettäköön kansastaan, kaikki, jotka semmoista tekevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Sen tähden noudattakaa minun määräyksiäni, ettette seuraisi niitä kauhistavia tapoja, joita on seurattu ennen teitä, ettekä saastuttaisi itseänne niillä. Minä olen Herra, teidän Jumalanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, '\"Puhu kaikelle israelilaisten seurakunnalle ja sano heille: Olkaa pyhät, sillä minä, Herra, teidän Jumalanne, olen pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Jokainen teistä osoittakoon [kunnioittavaa] pelkoa äidilleen ja isälleen, ja pitäkää sapattini. Minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Älkää kääntykö epäjumalien puoleen älkääkä tehkö itsellenne valettuja jumalankuvia. Minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Kun uhraatte rauhanuhria Herralle, uhratkaa se niin, että hänen mielisuosionsa tulee osaksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Syökää se samana päivänä, jona sen uhraatte, tai seuraavana päivänä, mutta mitä tähteeksi jää kolmanteen päivään, se poltettakoon tulessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Jos sitä syödään kolmantena päivänä, se on saastaista eikä otollista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Joka sitä syö, joutuu syynalaiseksi, sillä hän on häväissyt Herran pyhän, ja hänet hävitettäköön kansastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Kun korjaatte satoa maastanne, älä leikkaa viljaa pelloltasi reunoja myöten äläkä poimi tähkää leikkuun jäljeltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Älä myöskään korjaa tyhjäksi viinitarhaasi äläkä poimi varisseita marjoja, vaan jätä ne köyhälle ja muukalaiselle. Minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Älkää varastako, älkää valehdelko älkääkä pettäkö lähimmäistänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Älkää vannoko väärin minun nimeeni, ettet häpäisisi Jumalasi nimeä. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Älä tee lähimmäisellesi vääryyttä äläkä ota mitään väkisin. Päivämiehesi palkka älköön olko hallussasi huomiseen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Älä kiroa kuuroa äläkä pane kompastusta sokean eteen, vaan pelkää Jumalaasi. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Älkää tehkö vääryyttä tuomitessanne. Älä ole puolueellinen köyhän hyväksi äläkä pidä ylhäisen puolta, vaan tuomitse lähimmäisesi oikein.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Älä liiku panettelijana kansasi keskellä äläkä vaani lähimmäisesi verta. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Älä vihaa veljeäsi sydämessäsi, vaan nuhtele lähimmäistäsi, ettet joutuisi hänen tähtensä syynalaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Älä kosta äläkä pidä vihaa kansasi lapsia vastaan, vaan rakasta lähimmäistäsi niin kuin itseäsi. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Noudattakaa käskyjäni. Älä anna karjassasi kahden erilaisen eläimen pariutua, älä kylvä peltoosi kahdenlaista siementä, älköönkä kahdenlaisista langoista kudottua vaatetta tulko yllesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Jos mies makaa naisen, joka on orjatar ja toisen miehen oma eikä ole lunastettu eikä vapaaksi laskettu, rangaistakoon heitä, ei kuitenkaan kuolemalla, koska nainen ei ollut vapaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Mies tuokoon hyvityksenään Herralle vikauhripässin ilmestysmajan ovelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Kun pappi on toimittanut hänelle sovituksen vikauhripässillä Herran edessä siitä synnistä, jonka hän oli tehnyt, annetaan hänelle hänen tekemänsä synti anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Kun tulette siihen maahan ja istutatte kaikenlaisia hedelmäpuita, jättäkää niiden hedelmä, niiden esinahka, koskemattomaksi. Kolmena vuotena pitäkää ne ympärileikkaamattomina, älkää niitä syökö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Mutta neljäntenä vuotena pyhitettäköön kaikki niiden hedelmät ilojuhlassa Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Vasta viidentenä vuotena syökää niiden hedelmää. Näin te lisäätte niiden tuottoa. Minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Älkää syökö mitään verineen. Älkää ennustelko merkeistä älkääkä harjoittako noituutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Älkää ajako tukkaanne päälaen ympäriltä, äläkä leikkaamalla turmele partasi reunaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Älkää viileskelkö ihoanne vainajan tähden älkääkä piirrelkö siihen tatuointeja. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Älä häpäise tytärtäsi antamalla hänen tulla portoksi, ettei maa harjoittaisi haureutta ja tulisi täyteen iljettävyyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Pitäkää sapattini ja osoittakaa pelkoa pyhäkölleni. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Älkää kääntykö vainaja- ja tietäjähenkien puoleen. Älkää etsikö heitä, ettette saastuisi heistä. Minä olen Herra, teidän Jumalanne');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Nouse harmaapään edessä ja kunnioita vanhusta sekä pelkää Jumalaasi. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Kun muukalainen asuu luonasi teidän maassanne, älkää sortako häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Muukalainen, joka asuu luonanne, olkoon niin kuin maassa syntynyt teikäläinen. Rakasta häntä niin kuin itseäsi, sillä tekin olitte muukalaisina Egyptin maassa. Minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Älkää tehkö vääryyttä tuomitessanne älkääkä käyttäessänne pituus-, paino- tai tilavuusmittaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Olkoon teillä oikea vaaka, oikeat punnukset, oikea eefa-mitta ja oikea hiin-mitta. Minä olen Herra, teidän Jumalanne, joka vein teidät pois Egyptin maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Noudattakaa kaikkia käskyjäni ja kaikkia säädöksiäni ja pitäkää ne. Minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, '\"Sano israelilaisille: Jos joku, kuka tahansa israelilainen tai muukalainen, joka asuu Israelissa, antaa lapsiaan Molokille, häntä rangaistakoon kuolemalla. Maan kansa kivittäköön hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Minä käännän kasvoni sitä miestä vastaan ja hävitän hänet hänen kansastaan, koska hän on antanut Molokille lapsiaan saastuttaen pyhäkköni ja häväisten pyhän nimeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Jos maan kansa säästää sen miehen, joka antaa lapsiaan Molokille, niin etteivät he häntä surmaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'niin minä itse käännän kasvoni sitä miestä vastaan ja hänen sukuaan vastaan. Hänet ja kaikki, jotka häntä seuraten ovat lähteneet haureudessa kulkemaan Molokin jäljessä, minä hävitän kansastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Jos joku kääntyy vainaja- tai tietäjähenkien puoleen lähtien haureudessa kulkemaan niiden perässä, sitä ihmistä vastaan minä käännän kasvoni ja hävitän hänet kansastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Pyhittäkää siis itsenne ja olkaa pyhät, sillä minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Noudattakaa käskyjäni ja pitäkää ne. Minä olen Herra, joka pyhitän teidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Kuka ikinä kiroaa isäänsä tai äitiään, hänen pitää totisesti kuolla. Koska hän on kironnut isäänsä ja äitiään, hän on verivelan alainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Jos joku tekee aviorikoksen toisen miehen vaimon kanssa, jos hän tekee aviorikoksen lähimmäisensä vaimon kanssa, niin heidät, sekä aviorikoksen tehnyt mies että nainen, rangaistakoon kuolemalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Jos joku makaa äitipuolensa kanssa paljastaen isänsä hävyn, heidät molemmat rangaistakoon kuolemalla. He ovat verivelan alaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Jos joku makaa miniänsä kanssa, rangaistakoon heidät molemmat kuolemalla. He ovat tehneet iljettävyyden ja ovat verivelan alaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Jos joku makaa miehenpuolen kanssa, niin kuin naisen kanssa maataan, tekevät molemmat kauhistuksen. Heitä rangaistakoon kuolemalla. He ovat verivelan alaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Jos joku ottaa vaimoksi naisen ja hänen äitinsä, se on iljettävyys. Sekä hänet että ne molemmat poltettakoon tulessa, ettei mitään iljettävyyttä olisi teidän keskuudessanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Jos joku sekaantuu eläimeen, rangaistakoon hänet kuolemalla. Eläin tappakaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Jos nainen ryhtyy eläimeen, mihin tahansa, pariutuakseen sen kanssa, niin surmaa sekä nainen että eläin. Heidät rangaistakoon kuolemalla. He ovat verivelan alaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Jos joku ottaa vaimoksi sisarensa, isänsä tyttären tai äitinsä tyttären, ja näkee hänen häpynsä ja tämä näkee hänen häpynsä, niin se on häpeä, ja heidät hävitettäköön kansalaistensa silmistä. Hän on paljastanut sisarensa hävyn, hän on joutunut syynalaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Jos joku makaa kuukautistilassa olevan naisen kanssa ja paljastaa hänen häpynsä, avaa hänen lähteensä, ja nainen paljastaa verensä lähteen, niin heidät molemmat hävitettäköön kansastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Älä paljasta äitisi sisaren tai isäsi sisaren häpyä. Sillä se, joka niin tekee, on paljastanut veriheimolaisensa. He joutuvat syynalaisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Jos joku makaa setänsä vaimon kanssa, hän on paljastanut setänsä hävyn. He joutuvat syynalaisiksi. Lapsettomina he kuolkoot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Jos joku ottaa vaimoksi veljensä vaimon, se on saastaisuus. Hän on paljastanut veljensä hävyn, lapsettomiksi he jääkööt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Noudattakaa siis kaikkia käskyjäni ja kaikkia säädöksiäni ja pitäkää ne, ettei teitä oksentaisi ulos se maa, johon minä vien teidät asumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Älkää vaeltako sen kansan tapojen mukaan, jonka minä karkotan teidän tieltänne. Sillä kaikkia näitä he ovat tehneet ja nostaneet minun inhoni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Mutta minä sanon teille: Te saatte ottaa omaksenne heidän maansa, sillä minä annan sen teille omaksi, maan, joka vuotaa maitoa ja hunajaa. Minä olen Herra, teidän Jumalanne, joka olen teidät erottanut muista kansoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Erottakaa myös puhtaat eläimet saastaisista ja saastaiset linnut puhtaista, ettette saattaisi itseänne inhottaviksi koskemalla nelijalkaisiin eläimiin, lintuihin tai maan matelijoihin, mihin tahansa, jotka minä olen erottanut, että te pitäisitte niitä saastaisina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Olkaa siis minulle pyhät, sillä minä, Herra, olen pyhä, ja minä olen teidät erottanut muista kansoista olemaan omiani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Jos jossakin miehessä tai naisessa on vainaja- tai tietäjähenki, niin heitä rangaistakoon kuolemalla. Heidät kivitettäköön, he ovat verivelan alaiset.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Herra sanoi Moosekselle: \"Puhu papeille, Aaronin pojille, ja sano heille: Pappi älköön saattako itseään saastaiseksi kenestäkään kuolleesta sukulaisestaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'paitsi lähimmästä veriheimolaisestaan: äidistään, isästään, pojastaan, tyttärestään ja veljestään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'sekä sisarestaan, jos tämä oli neitsyt ja eli hänen luonaan eikä ollut naitu. Hänestä hän saa saastua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Älköön hän, sukunsa päämies, saattako itseään saastaiseksi, ettei häpäisisi itseään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Älkööt he ajako paljaaksi päälakeaan, älkööt leikatko partansa reunaa älköötkä viileskelkö ruumistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Olkoot Jumalalleen pyhät älköötkä häväiskö Jumalansa nimeä, sillä he uhraavat Herran uhreja, Jumalansa leipää. Sen tähden olkoot pyhät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Älkööt ottako vaimoksi porttoa tai häväistyä naista älköötkä ottako miehensä hylkäämää vaimoa, sillä pappi on pyhä Jumalalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Sinun on pidettävä häntä pyhänä, koska hän uhraa sinun Jumalasi leipää. Hän olkoon sinulle pyhä, sillä minä, Herra, joka pyhitän teidät, olen pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Jos papin tytär häpäisee itsensä haureudella, hän häpäisee isänsä. Hänet poltettakoon tulessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Pappi, joka on ylimmäinen veljiensä seassa, jonka pään päälle voiteluöljy on vuodatettu ja joka on vihitty virkaansa pukemalla hänet pyhiin vaatteisiin, älköön päästäkö tukkaansa hajalle älköönkä reväiskö vaatteitaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Älköön hän myöskään menkö minkään kuolleen luo. Isästäänkään tai äidistään hän älköön saastuko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Älköön hän lähtekö pyhäköstä, ettei hän häpäisisi Jumalansa pyhäkköä, sillä hänessä on hänen Jumalansa voiteluöljyn vihkimys. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Hän ottakoon vaimokseen neitsyen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Leskeä, hylättyä vaimoa, häväistyä naista tai porttoa hän älköön ottako, vaan ottakoon vaimokseen neitsyen omasta suvustaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'ettei häpäisisi jälkeläisiään suvussaan. Sillä minä olen Herra, joka pyhitän hänet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, '\"Puhu Aaronille ja sano: jos jossakussa jälkeläisistäsi tulevissa sukupolvissa on jokin vamma, älköön hän lähestykö uhraamaan Jumalansa leipää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Älköön uhraamaan lähestykö kukaan, jossa on jokin vamma, älköön kukaan sokea tai ontuva, kukaan kasvoiltaan tai jäseniltään muodoton,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'jalkansa tai kätensä taittanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'kyttyräselkäinen, surkastunut, silmävikainen, ihotautinen, rupinen tai kuohittu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Pappi Aaronin jälkeläisistä älköön kukaan, jossa on jokin vamma, lähestykö uhraamaan Herran uhreja. Koska hänessä on vamma, älköön sellainen lähestykö uhraamaan Jumalansa leipää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Syököön kuitenkin Jumalansa leipää, sekä korkeasti pyhää että pyhää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Älköön kuitenkaan tulko esiripun luo älköönkä lähestykö alttaria, koska hänessä on vamma, ettei hän häpäisisi minun pyhäkköäni. Sillä minä olen Herra, joka pyhitän heidät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Mooses sanoi tämän Aaronille ja hänen pojilleen ja kaikille israelilaisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, '\"Käske Aaronia ja hänen poikiaan pyhästi käsittelemään israelilaisten pyhiä lahjoja, heidän minulle pyhittämiään, etteivät he häpäisisi pyhää nimeäni. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Sano heille polvesta polveen: Jos kuka tahansa jälkeläisistänne saastuneena ollessaan lähestyy niitä pyhiä lahjoja, joita israelilaiset pyhittävät Herralle, hänet hävitettäköön kasvojeni edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Minä olen Herra. Älköön kukaan Aaronin jälkeläinen, joka on spitaalinen tai jolla on vuoto, syökö pyhistä lahjoista, ennen kuin on tullut puhtaaksi. Joka koskee johonkin kuolleesta saastuneeseen tai jolla on siemenvuoto,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'tai joka koskee mihin tahansa pikkueläimeen, josta saastuu, tai ihmiseen, josta saastuu, olipa sen saastaisuus mitä laatua tahansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'niin jokainen, joka koskee johonkin sellaiseen, olkoon saastainen iltaan asti älköönkä syökö pyhistä lahjoista, ellei ole pessyt ruumistaan vedellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Mutta kun aurinko on laskenut, hän on puhdas. Sitten syököön pyhistä lahjoista, sillä se on hänen ruokaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Itsestään kuollutta tai kuoliaaksi raadeltua eläintä älköön syökö, ettei saastuisi. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Noudattakoot määräyksiäni, etteivät joutuisi syynalaisiksi pyhitetyn tähden ja kuolisi sen vuoksi, että häpäisevät pyhitetyn. Minä olen Herra, joka pyhitän heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Kukaan muu kuin pappi älköön syökö pyhästä lahjasta. Älköön muukalainen tai papin luona asuva tai päiväpalkkalainen syökö pyhästä lahjasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Mutta kun pappi ostaa rahallaan orjan, saakoon tämä siitä syödä. Samoin hänen kodissaan syntyneet orjat syökööt hänen ruokaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Jos papin tytär tulee muukalaisen miehen vaimoksi, älköön hän syökö pyhistä uhrilahjoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Mutta jos papin tytär tulee leskeksi tai hylätyksi ja on lapseton ja tulee takaisin isänsä taloon ja asuu siellä niin kuin nuoruudessaan, syököön isänsä ruokaa. Mutta kukaan muukalainen älköön sitä syökö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Jos joku erehdyksessä syö pyhästä lahjasta, korvatkoon papille pyhän lahjan ja pankoon siihen vielä lisäksi viidennen osan sen arvosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Älkööt papit häväiskö israelilaisten pyhiä lahjoja, joita nämä antavat Herralle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'älköötkä saattako heitä syynalaisiksi ja vikapäiksi sallimalla heidän syödä pyhiä lahjojaan. Sillä minä olen Herra, joka pyhitän heidät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, '\"Puhu Aaronille ja hänen pojilleen ja kaikille israelilaisille ja sano heille: Kuka ikinä Israelin heimosta tai muukalaisista Israelissa tuo polttouhriksi uhrilahjansa, olipa se mikä hyvänsä lupausuhri tai vapaaehtoinen uhri, jonka he tuovat Herralle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'niin tuokaa sellainen uhri, että hänen mielisuosionsa tulee osaksenne: virheetön urospuoli naudoista, lampaista tai vuohista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Mutta yhtään eläintä, jossa on vamma, älkää tuoko, sillä siitä hänen mielisuosionsa ei tule teidän osaksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Jos joku tuo Herralle rauhanuhrin naudoista tai lampaista, joko lupausta täyttääkseen tai vapaaehtoisena uhrina, olkoon eläin virheetön ollakseen otollinen. Älköön siinä olko mitään vammaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Sokeaa tai raajarikkoa tai silvottua tai paiseista tai ihotautista tai rupista älkää Herralle tuoko, älkääkä sellaisia asettako alttarille uhriksi Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Härän tai lampaan, joka on jäseniltään muodoton tai vaivainen, saat uhrata vapaaehtoisena uhrina, mutta lupausuhriksi se ei ole otollinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Älkää uhratko Herralle eläintä, joka on kuohittu puristamalla, musertamalla, repimällä tai leikkaamalla. Älkää tehkö maassanne sellaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Älkää myöskään ostako muukalaiselta mitään sellaisia eläimiä tuodaksenne niitä Jumalanne ruoaksi. Sillä ne ovat turmeltuja, niissä on vamma. Niistä ei tule osaksenne mielisuosiota.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, '\"Kun vasikka, karitsa tai kili on syntynyt, olkoon se emänsä luona seitsemän päivää. Mutta kahdeksannesta päivästä alkaen se on otollinen uhrilahjaksi Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Älkää teurastako samana päivänä nautaa vasikkansa kanssa tai lammasta karitsansa kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Kun uhraatte Herralle rauhanuhrin, uhratkaa se niin, että hänen mielisuosionsa tulee osaksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Syötäköön se samana päivänä. Älkää jättäkö siitä mitään seuraavaan aamuun. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Noudattakaa siis käskyjäni ja pitäkää ne. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Älkää häväiskö pyhää nimeäni: minä tahdon olla pyhä israelilaisten keskellä. Minä olen Herra, joka pyhitän teidät');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'ja joka vein teidät pois Egyptin maasta, ollakseni Jumalanne. Minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, '\"Puhu israelilaisille ja sano heille: Herran juhla-ajat, joiksi teidän on kuulutettava pyhät kokoukset, minun juhlani, ovat nämä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Kuusi päivää tehtäköön työtä, mutta seitsemäntenä päivänä on sapatti, levon päivä, pyhä kokous. Silloin älkää toimittako yhtään askaretta. Se on Herran sapatti, missä asuttekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Nämä ovat Herran juhlat, pyhät kokoukset, jotka teidän on kuulutettava määräajallaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Ensimmäisessä kuussa, kuukauden neljäntenätoista päivänä, iltahämärässä, on pääsiäinen Herran kunniaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Saman kuukauden viidentenätoista päivänä on happamattoman leivän juhla Herran kunniaksi. Syökää happamatonta leipää seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Ensimmäisenä päivänä olkoon teillä pyhä kokous, silloin älkää toimittako mitään arkiaskaretta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Tuokaa Herralle uhri seitsemänä päivänä. Seitsemäntenä päivänä on pyhä kokous. Silloin älkää toimittako mitään arkiaskaretta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, '\"Puhu israelilaisille ja sano heille: Kun te tulette siihen maahan, jonka minä teille annan, ja leikkaatte sen viljaa, niin viekää papille viljastanne ensimmäinen lyhde.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Hän toimittakoon lyhteen heilutuksen Herran edessä, että hänen mielisuosionsa tulisi osaksenne. Pappi toimittakoon heilutuksen sapatin jälkeisenä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Sinä päivänä, jona lyhteenne heilutus toimitetaan, uhratkaa virheetön, vuoden vanha karitsa polttouhriksi Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Uhratkaa myös siihen kuuluvana ruokauhrina kaksi kymmenesosaa ydinjauhoja öljyyn sekoitettuna, uhrina, suloisena tuoksuna Herralle, sekä siihen kuuluvana juomauhrina neljännes hiin-mittaa viiniä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Älkääkä syökö ensi sadon leipää, paahdettuja jyviä tai tuleentumatonta viljaa ennen sitä päivää, jona tuotte uhrilahjan Jumalallenne. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen, missä asuttekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Sitten laskekaa sapatin jälkeisestä päivästä, siitä päivästä, jona toitte heilutuslyhteen, seitsemän täyttä viikkoa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'laskekaa viisikymmentä päivää seitsemännen sapatin jälkeiseen päivään asti. Sitten tuokaa Herralle uusi ruokauhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Sieltä, missä asutte, tuokaa heilutusleiväksi kaksi leipäkakkua, jotka on leivottava happamena kahdesta kymmenesosasta ydinjauhoja, Herralle ensi sadon lahjaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Tuokaa leipänne ohella seitsemän virheetöntä, vuoden vanhaa karitsaa ja mulli sekä kaksi pässiä. Ne olkoot ruoka- ja juomauhreineen polttouhri Herralle, suloisesti tuoksuva uhri Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Uhratkaa vuohipukki syntiuhriksi sekä kaksi vuoden vanhaa karitsaa rauhanuhriksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Pappi toimittakoon niiden ja ensi sadon leivän sekä kahden karitsan heilutuksen Herran edessä. Ne olkoot Herralle pyhät ja papille tulevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Kuuluttakaa pyhä kokous juuri siksi päiväksi. Älkää toimittako silloin mitään arkiaskaretta. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen, missä asuttekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Kun korjaatte eloa maastanne, älä leikkaa viljaa pelloltasi reunoja myöten äläkä poimi tähkää leikkuun jälkeen, vaan jätä ne köyhälle ja muukalaiselle. Minä olen Herra, teidän Jumalanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, '\"Puhu israelilaisille ja sano: Seitsemännessä kuussa, kuukauden ensimmäisenä päivänä, pitäkää sapattilepo, muistojuhla torvea soittaen, pyhä kokous.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Älkää silloin toimittako mitään arkiaskaretta, vaan tuokaa uhri Herralle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, '\"Tämän seitsemännen kuun kymmenentenä päivänä on sovituspäivä. Pitäkää silloin pyhä kokous, kurittakaa itseänne paastolla ja tuokaa Herralle uhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Älkää toimittako yhtään askaretta sinä päivänä, sillä se on sovituspäivä, jolloin teille toimitetaan sovitus Herran, Jumalanne, edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Sillä jokainen, joka sinä päivänä ei kurita itseään paastolla, hävitettäköön kansastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Jokaisen, joka sinä päivänä toimittaa jotakin askaretta, minä hävitän hänen kansastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Älkää silloin toimittako yhtään askaretta. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen, missä asuttekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Se on oleva teille levon päivä. Kurittakaa itseänne paastolla. Kuukauden yhdeksäntenä päivänä illalla, illasta iltaan, pitäkää tämä sapatti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, '\"Puhu israelilaisille ja sano: Tämän seitsemännen kuun viidentenätoista päivänä on lehtimajanjuhla Herran kunniaksi. Se kestää seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Ensimmäisenä päivänä pidettäköön pyhä kokous. Älkää silloin toimittako mitään arkiaskaretta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Seitsemänä päivänä tuokaa uhri Herralle. Kahdeksantena päivänä olkoon teillä pyhä kokous, ja tuokaa uhri Herralle. Se on juhlakokous, älkää silloin toimittako mitään arkiaskaretta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Nämä ovat Herran juhla-ajat, joiksi teidän on kuulutettava pyhät kokoukset tuodaksenne Herralle uhreja: polttouhreja ja ruokauhreja, teurasuhreja ja juomauhreja, kunakin päivänä sen päivän uhrit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Nämä ovat Herran sapattien ja teidän muiden lahjojenne ja kaikkien lupausuhrienne ja kaikkien vapaaehtoisten uhrienne lisäksi, joita te Herralle annatte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Seitsemännen kuukauden viidentenätoista päivänä, kun te olette korjanneet maan sadon, viettäkää Herran juhlaa seitsemän päivää. Ensimmäinen päivä on levon päivä, ja myös kahdeksas päivä on levon päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Ensimmäisenä päivänä ottakaa puista ihania hedelmiä, palmunoksia ja tuuheiden puiden lehviä sekä pajuja purojen varsilta, ja pitäkää iloa seitsemän päivää Herran, Jumalanne edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Viettäkää sitä juhlana Herran kunniaksi seitsemän päivää vuodessa. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen. Viettäkää se seitsemännessä kuussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Seitsemän päivää asukaa lehtimajoissa. Kaikki Israelissa syntyneet asukoot lehtimajoissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'että jälkeläisenne tietäisivät, kuinka minä annoin israelilaisten asua lehtimajoissa, kun vein heidät pois Egyptin maasta. Minä olen Herra, teidän Jumalanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Mooses ilmoitti israelilaisille nämä Herran juhla-ajat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, '\"Käske israelilaisia tuomaan sinulle puhdasta, survomalla saatua öljypuun öljyä seitsenhaaraista lamppua varten, että lamput voidaan aina nostaa paikoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Esiripun ulkopuolella, joka on lain arkin edessä ilmestysmajassa, Aaron hoitakoon sitä niin, että se palaa aina illasta aamuun Herran edessä. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Aidosta kullasta valmistetun seitsenhaaraisen lampun lamppuja hän hoitakoon niin, että ne palavat aina Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Ota ydinjauhoja ja leivo niistä kaksitoista leipäkakkua. Jokaisessa kakussa olkoon jauhoja kaksi kymmenesosaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Lado ne päällekkäin kahteen pinoon, kuusi pinoonsa, aidosta kullasta valmistetulle pöydälle Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Pane pinojen päälle puhdasta suitsuketta. Leivät ovat muistouhri, tuliuhri Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Sapatti sapatilta hän asettakoon ne aina Herran eteen israelilaisten antina. Se on ikuinen liitto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Ne olkoot Aaronin ja hänen poikiensa. He syökööt ne pyhässä paikassa, sillä ne ovat korkeasti pyhät. Ne ovat hänen ikuinen osuutensa Herran uhreista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Erään israelilaisen vaimon poika, jonka isä oli egyptiläinen mies, oli lähtenyt maasta israelilaisten mukana. Tämän israelilaisen vaimon poika ja muuan israelilainen mies riitelivät keskenään leirissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Israelilaisen vaimon poika pilkkasi Herran nimeä ja kirosi sitä. Silloin he toivat hänet Mooseksen eteen. Hänen äitinsä nimi oli Selomit, Dibrin tytär, Daanin sukukunnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'He panivat hänet vankilaan, kunnes heille ilmoitettaisiin Herran vastaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, '\"Vie kiroaja leirin ulkopuolelle, ja kaikki, jotka kuulivat sen, laskekoot kätensä hänen päänsä päälle, ja koko kansa kivittäköön hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Puhu israelilaisille ja sano: Kuka ikinä Jumalaansa kiroaa, se joutuu syynalaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Sitä, joka Herran nimeä pilkkaa, rangaistakoon kuolemalla. Koko kansa kivittäköön hänet kuoliaaksi. Olipa se muukalainen tai maassa syntynyt, joka pilkkaa Herran nimeä, hänet surmattakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Jos joku lyö kuoliaaksi ihmisen, kenet hyvänsä, häntä rangaistakoon kuolemalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Mutta joka lyö kuoliaaksi kotieläimen, korvatkoon sen: henki hengestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Joka tuottaa lähimmäiselleen vamman, sille tehtäköön, niin kuin hänkin oli tehnyt:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'ruhje ruhjeesta, silmä silmästä, hammas hampaasta. Saman vamman, jonka hän on toiselle tuottanut, saakoon hän itsekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Joka lyö kuoliaaksi kotieläimen, korvatkoon sen. Mutta se, joka lyö kuoliaaksi ihmisen, surmattakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Sama laki olkoon teillä, niin muukalaisella kuin maassa syntyneelläkin. Sillä minä olen Herra, teidän Jumalanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Mooses puhui näin israelilaisille. Niin he veivät kiroajan leirin ulkopuolelle ja kivittivät hänet kuoliaaksi. Näin israelilaiset tekivät, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Herra puhui Moosekselle Siinain vuorella sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, '\"Puhu israelilaisille ja sano heille: Kun tulette siihen maahan, jonka minä teille annan, pitäköön maa sapattia Herran kunniaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Kuutena vuotena kylvä peltosi ja kuutena vuotena leikkaa viinitarhasi ja korjaa niiden sato.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Seitsemäntenä vuotena sen sijaan olkoon maalla levon aika, sapatti Herran kunniaksi. Älä silloin kylvä peltoasi äläkä leikkaa viinitarhaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Leikatun viljasi jälkikasvua älä leikkaa. Älä myöskään poimi viinirypäleitä, jotka ovat kasvaneet leikkaamattomissa viinipuissasi. Olkoon maalla silloin lepovuosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Se, mitä itsestään kasvaa maan levätessä, olkoon teille ruoaksi, sinulle itsellesi, palvelijallesi ja palvelijattarellesi, päiväpalkkalaisellesi ja muukalaisille, jotka asuvat kanssasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'Karjallesi ja metsäeläimille maassasi olkoon kaikki maan sato ruuaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Laske seitsemän vuosiviikkoa: seitsemän kertaa seitsemän vuotta, niin että seitsemän vuosiviikon aika on neljäkymmentä yhdeksän vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Seitsemännessä kuussa, kuukauden kymmenentenä päivänä anna torven raikuen soida. Sovituspäivänä antakaa torven soida koko maassanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Pyhittäkää viideskymmenes vuosi ja julistakaa vapautus maassa kaikille sen asukkaille. Se olkoon teille riemuvuosi. Jokainen teistä saa silloin palata perintömaalleen ja sukunsa luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Riemuvuosi olkoon teille viideskymmenes vuosi. Älkää silloin kylväkö älkääkä jälkikasvua leikatko. Älkää myöskään poimiko, mitä leikkaamattomissa viinipuissa on kasvanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Sillä se on riemuvuosi. Olkoon se teille pyhä. Syökää sen sato pellolta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'Riemuvuotena saa jokainen teistä palata perintömaalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Jos myyt jotakin lähimmäisellesi tai ostat jotakin lähimmäiseltäsi, älkää tehkö vääryyttä toinen toisellenne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'vaan maksa lähimmäisellesi riemuvuoden jälkeisten vuosien luvun mukaan. Satovuosien luvun mukaan hän saakoon sinulta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Maksa sitä suurempi hinta, mitä useampia vuosia on, ja maksa sitä pienempi hinta, mitä vähemmän vuosia on, sillä sadon määrän hän myy sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Älköön teistä kukaan tehkö vääryyttä lähimmäiselleen, vaan pelkää Jumalaasi, sillä minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Sen tähden pitäkää käskyni ja noudattakaa säädöksiäni ja pitäkää ne, niin saatte turvallisesti asua maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Maa on antava hedelmänsä, ja teillä on kyllin syötävää, ja te saatte turvallisesti asua siinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Jos te sanotte: \'Mitä syömme seitsemäntenä vuotena, kun meidän ei ole lupa kylvää eikä korjata satoamme?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Niin minä käsken siunaukseni kuudentena vuotena tulemaan teille, niin että se tuottaa teille kolmen vuoden sadon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Kun kylvätte kahdeksantena vuotena, teillä on vielä vanhaa satoa syödäksenne. Teillä on vanhaa satoa syödäksenne siihen asti, kunnes yhdeksännen vuoden sato on saatu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Älköön myytäkö maata ainaiseksi, sillä maa on minun ja te olette muukalaisia ja vieraita minun luonani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Kaikessa siinä maassa, jonka te saatte perintömaaksenne, antakaa oikeus maan sukulunastamiseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Jos veljesi köyhtyy ja myy perintömaatansa, hänen lähin sukulunastajansa tulkoon ja lunastakoon sen, minkä hänen veljensä on myynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Mutta jos jollakulla ei ole sukulunastajaa, mutta hän itse voi hankkia niin paljon, kuin lunastukseen tarvitaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'laskekoon, kuinka monta vuotta on kulunut myymisestä, ja maksakoon jäljellä olevasta ajasta miehelle, jolle hän myi, ja palatkoon perintömaalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Mutta jos hän ei voi hankkia niin paljon, kuin maksamiseen tarvitaan, niin jääköön ostajalle se, minkä hän on myynyt, riemuvuoteen asti. Mutta riemuvuotena se on vapaa. Sitten hän palatkoon perintömaalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Jos joku myy asuinrakennuksen muureilla varustetussa kaupungissa, olkoon hänellä oikeus lunastaa se vuoden kuluessa siitä, kun hän sen myi. Sen ajan kestää hänen sukulunastusoikeutensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Mutta jollei sitä lunasteta, ennen kuin vuosi on kulunut umpeen, jääköön talo muureilla varustetussa kaupungissa ainaiseksi ostajalle ja hänen suvulleen tulematta vapaaksi riemuvuotena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Mutta talot kylissä, joiden ympärillä ei ole muuria, luettakoon peltomaaksi. Ne olkoot lunastettavissa. Ne tulevat vapaiksi riemuvuotena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Leeviläisillä olkoon kuitenkin ikuinen oikeus talojen lunastamiseen niissä kaupungeissa, jotka ovat heidän perintöomaisuuttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Jos joku leeviläinen käyttää lunastusoikeutta, niin myyty talo kaupungissa, joka on leeviläistä perintöomaisuutta, palautuu riemuvuotena vapaaksi. Sillä talot leeviläiskaupungeissa ovat heidän perintöomaisuuttaan israelilaisten keskuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Heidän kaupunkeihinsa kuuluvaa laidunmaata älköön myytäkö, sillä se on heidän ikuista perintöomaisuuttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Jos veljesi luonasi köyhtyy eikä jaksa pysyä pystyssä, tue häntä samoin kuin muukalaista tai talossasi asuvaa. Hän eläköön luonasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Älä ota korkoa tai voittoa häneltä, vaan pelkää Jumalaasi ja anna veljesi elää luonasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Älä anna hänelle rahaasi korolle äläkä ota elintarpeista voittoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Minä olen Herra, teidän Jumalanne, joka vein teidät pois Egyptin maasta antaakseni teille Kanaanin maan ja ollakseni Jumalanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Jos veljesi luonasi köyhtyy ja myy itsensä sinulle, älä pane häntä orjan työhön,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'vaan hän olkoon päiväpalkkalaisena ja loisena luonasi. Riemuvuoteen asti hän palvelkoon sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Silloin hän lähteköön luotasi vapaana, hän ja hänen lapsensa hänen kanssaan, ja palatkoon sukunsa luo ja isiensä perintömaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Sillä he ovat palvelijoitani, jotka minä vein pois Egyptin maasta. Sen tähden älköön heitä orjan tavalla myytäkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Älä hallitse heitä kovuudella, vaan pelkää Jumalaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Mutta orjasi ja orjattaresi, jotka hankit itsellesi, ostakaa kansoista, jotka asuvat ympärillänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Tai ostakaa ne luonanne asuvien suojattien lapsista ja heidän sukulaisistaan, jotka ovat luonanne ja jotka ovat heille syntyneet maassanne. He olkoot perintöomaisuuttanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Jättäkää heidät jälkeenne perinnöksi lapsillenne, pysyväksi perintöomaisuudeksi. Heitä saatte pitää ainaisesti orjinanne. Mutta veljistänne, israelilaisista, älä hallitse ketään kovuudella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Jos luonasi asuva muukalainen tai suojatti tulee varoihin veljesi köyhtyessä hänen luonaan, niin että hän myy itsensä luonasi asuvalle muukalaiselle, suojatille tai jollekin muukalaisen suvun jäsenelle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'olkoon hän sen jälkeen, kun hän myi itsensä, lunastettavissa. Joku hänen veljistään lunastakoon hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Tai lunastakoon hänet hänen setänsä, setänsä poika tai joku veriheimolainen hänen suvustaan. Tai jos hän tulee varoihin, lunastakoon itse itsensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Hänen on laskettava yhdessä ostajansa kanssa, kuinka pitkä aika on riemuvuoteen siitä vuodesta, jolloin hän myi itsensä hänelle. Hänen myyntihintansa jaettakoon vuosien luvulla. Hänen palvelusaikansa laskettakoon samanarvoiseksi kuin päiväpalkkalaisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Jos hänellä on vielä monta vuotta jäljellä, maksakoon takaisin lunastushintanaan niitä vastaavan osan siitä summasta, jolla hänet ostettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Mutta jos vain vähän vuosia on jäljellä riemuvuoteen, laskekoon ostaja ne hänen kanssaan, ja hän maksakoon lunastushintansa sen mukaan, kuin hänellä on vuosia jäljellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Palvelkoon vuosikaupalla otetun päiväpalkkalaisen tavalla häntä, mutta älköön tämä kovuudella hallitko häntä silmiesi edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Mutta jos häntä ei näin lunasteta, hän tulkoon riemuvuotena vapaaksi, hän itse ja hänen lapsensa hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Sillä israelilaiset ovat minun palvelijoitani. He ovat palvelijani, jotka minä vein pois Egyptin maasta. Minä olen Herra, teidän Jumalanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, '\"Älkää tehkö itsellenne epäjumalia. Älkää pystyttäkö itsellenne jumalankuvia tai patsaita. Älkää myöskään asettako maahanne kiviä, joissa on kuvia, kumartaaksenne niitä, sillä minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Pitäkää sapattini ja osoittakaa pelkoa pyhäkölleni. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Jos te vaellatte säädöksieni mukaan ja noudatatte käskyjäni ja pidätte ne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'minä annan teille sateen ajallaan, niin että maa antaa satonsa ja kedon puut kantavat hedelmänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Silloin puiminen kestää teillä viininkorjuuseen asti, ja viininkorjuu kestää kylvöön asti. Teillä on kyllin leipää syödäksenne, ja saatte asua turvallisesti maassanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Minä annan rauhan maallenne, ja te saatte levätä, eikä kukaan ole teille pelkona. Minä hävitän pahat pedot maastanne, eikä miekka käy maanne yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Te ajatte pakoon vihollisenne, ja he kaatuvat miekkaan edessänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Viisi teistä ajaa pakoon sata, ja sata teistä ajaa pakoon kymmenentuhatta. Teidän vihollisenne kaatuvat miekkaan teidän edessänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Minä käännän kasvoni teidän puoleenne ja teen teidät hedelmällisiksi ja annan teidän lisääntyä. Minä pidän liittoni teidän kanssanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Te saatte syödä vanhaa, viime vuoden satoa, ja te joudutte viemään vanhan pois uuden tieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Minä panen asumukseni keskuuteenne enkä vieroksu teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Minä vaellan teidän keskellänne ja olen teidän Jumalanne, ja te olette minun kansani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Minä olen Herra, teidän Jumalanne, joka vein teidät pois Egyptin maasta, olemasta heidän orjinaan, ja minä mursin rikki teidän ikeenne puut ja annoin teidän kulkea pystypäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Mutta jos te ette kuule minua ettekä pidä kaikkia näitä käskyjä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'vaan hylkäätte määräykseni ja sielunne luopuu säädöksistäni, niin ettette pidä kaikkia käskyjäni, vaan rikotte liittoni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'minäkin teen teille samoin. Minä rankaisen teitä hirveillä onnettomuuksilla, hivuttavalla taudilla ja kuumeella, jotka sumentavat silmänne ja näännyttävät sielunne. Te kylvätte siemenenne turhaan, sillä vihollisenne syövät sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Minä käännän kasvoni teitä vastaan, ja teidän vihollisenne voittavat teidät. Teidän vihamiehenne hallitsevat teitä, ja te pakenette, vaikka kukaan ei aja teitä takaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Jos ette sittenkään kuule minua, niin minä vielä kuritan teitä seitsenkertaisesti syntienne tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Minä murran ylpeän uhmanne. Minä teen taivaanne raudankovaksi ja maanne vasken kaltaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Teidän voimanne kuluu hukkaan, sillä teidän maanne ei suo satoaan eivätkä maan puut anna hedelmäänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Jos te sittenkin käytte minua vastaan ettekä tahdo kuulla minua, minä lyön teitä vielä seitsenkertaisesti syntienne mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Minä lähetän keskuuteenne metsän pedot riistämään teiltä lapsenne, raatelemaan karjaanne ja vähentämään lukuanne, niin että tienne tulevat autioiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Jos te ette vielä tästäkään kurituksestani ojennu, vaan käytte yhä minua vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'niin minäkin käyn teitä vastaan ja lyön teitä seitsenkertaisesti syntienne tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Minä saatan kimppuunne miekan, joka kostaa rikotun liiton. Kun kokoonnutte kaupunkeihinne, lähetän keskuuteenne ruttotaudin, ja teidän täytyy antautua vihollisen valtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Kun murran teiltä leivän tuen, kymmenen vaimoa paistaa leipänne yhdessä uunissa. He tuovat kotiin leipänne vaa\'alla punnittuna. Kun sen syötte, ette tule ravituiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Jos ette vielä sittenkään kuule minua, vaan yhä käytte minua vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'minäkin kiivastuksessani käyn teitä vastaan ja kuritan teitä seitsenkertaisesti syntienne tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Te syötte poikienne lihaa, ja tyttärienne lihaa te syötte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Minä kukistan uhrikukkulanne ja hävitän auringonpatsaanne ja panen ruumiinne epäjumalienne ruumiiden päälle, ja sieluni inhoaa teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Minä teen kaupunkinne raunioiksi ja hävitän pyhäkkönne enkä mielisty uhrienne tuoksuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Minä hävitän maan, niin että vihollisenne, jotka siinä asuvat, siitä tyrmistyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Mutta teidät minä hajotan pakanakansojen sekaan ja ajan teitä takaa paljastetulla miekalla, ja maanne tulee autioksi ja kaupunkinne raunioiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Silloin maa saa hyvityksen sapateistaan, niin kauan se on autiona ja te olette vihollistenne maassa. Silloin maa lepää ja saa hyvityksen sapateistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Kun se on autiona, se saa levätä nauttien sitä lepoa, jota se ei saanut sapatteinanne asuessanne siinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Niille teistä, jotka jäävät jäljelle, minä annan pelokkaan sydämen heidän vihollistensa maassa, niin että lentävän lehden kahina ajaa heidät pakoon. He pakenevat, niin kuin pakenisivat miekkaa, ja kaatuvat, vaikka ei kukaan aja heitä takaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'He kompastuvat toisiinsa kuin miekkaa paeten, vaikka ei kukaan aja heitä takaa, ettekä voi pitää puolianne vihollisianne vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Te häviätte kansojen sekaan, ja vihollistenne maa nielee teidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Ne teistä, jotka jäävät jäljelle, riutuvat vihollistenne maassa syntivelkansa tähden. Myös isiensä syntivelan tähden he riutuvat kuten hekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Silloin he tunnustavat syntivelkansa ja isiensä syntivelan, sen että ovat olleet minulle uskottomat ja käyneet minua vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'jonka tähden minäkin kävin heitä vastaan ja vein heidät heidän vihollistensa maahan. Silloin heidän ympärileikkaamaton sydämensä nöyrtyy, ja silloin he sovittavat syntivelkansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Silloin minä muistan liittoni Jaakobin kanssa ja muistan liittoni Iisakin kanssa ja liittoni Aabrahamin kanssa, ja minä muistan myös maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Mutta ensin tulkoon maa tyhjäksi heistä ja saakoon hyvityksen sapateistaan olemalla autiona, niin kauan kuin he ovat poissa. Sovittakoot syntivelkansa sen tähden, juuri sen tähden, että he hylkäsivät säädökseni ja että heidän sielunsa luopui käskyistäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Mutta sittenkään, vaikka he ovat vihollistensa maassa, en minä heitä hylkää enkä hylkää heitä niin, että tekisin heistä lopun ja rikkoisin liittoni heidän kanssaan, sillä minä olen Herra, heidän Jumalansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Minä muistan heidän hyväkseen liiton heidän isiensä kanssa, jotka minä vein pois Egyptin maasta pakanakansojen silmien edessä, ollakseni heidän Jumalansa. Minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Nämä ovat ne käskyt, säädökset ja lait, jotka Herra asetti itsensä ja israelilaisten välille Siinain vuorella Mooseksen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, '\"Puhu israelilaisille ja sano heille: Jos jollakin on täytettävänä lupaus Herralle ja sinun on arvioitava luvatun ihmisen arvo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'niin arvioi mies, joka on kahdenkymmenen ja kuudenkymmenen vuoden välillä, viiteenkymmeneen hopeasekeliin pyhäkkösekelin painon mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Mutta jos se on nainen, arvioi hänet kolmeenkymmeneen sekeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Viisivuotiaasta kaksikymmenvuotiaaseen asti arvioi miespuoli kahteenkymmeneen sekeliin ja naispuoli kymmeneen sekeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Kuukauden vanhasta viisivuotiaaseen asti arvioi miespuoli viiteen hopeasekeliin ja naispuoli kolmeen hopeasekeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Kuusikymmenvuotias ja sitä vanhempi miespuoli arvioi viiteentoista sekeliin ja naispuoli kymmeneen sekeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Jos joku on liian köyhä maksamaan arviohintaa, vietäköön hänet papin eteen, ja pappi arvioikoon hänet. Pappi arvioikoon hänet lupauksen tekijän varallisuuden mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Jos lupaus sen sijaan koskee karjaa, josta voidaan tuoda uhrilahja Herralle, olkoon kaikki, mikä siitä annetaan Herralle, pyhää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Älköön sitä vaihdettako älköönkä muutettako, ei hyvää huonoon eikä huonoa hyvään. Jos joku kuitenkin vaihtaa eläimen toiseen, olkoon sekä se että siihen vaihdettu pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Mutta jos se on saastainen eläin, mikä tahansa, joita ei saa tuoda uhrilahjaksi Herralle, vietäköön eläin papin eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'Pappi arvioikoon sen tarkastaen, onko se hyvä vai huono. Olkoon sillä se arviohinta, jonka pappi määrää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Jos omistaja tahtoo sen lunastaa, antakoon arviohinnan lisäksi viidennen osan siitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Jos joku pyhittää talonsa pyhäksi lahjaksi Herralle, pappi arvioikoon sen tarkastaen, onko se hyvä vai huono. Olkoon sillä se arviohinta, jonka pappi määrää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Mutta jos se, joka on talonsa pyhittänyt, tahtoo lunastaa sen, niin antakoon arviosumman lisäksi viidennen osan siitä. Niin se on hänen omansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Jos joku pyhittää Herralle kappaleen perintömaataan, niin arvioi se kylvön suuruuden mukaan. Hoomer-mitta ohria vastatkoon viittäkymmentä hopeasekeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Jos hän pyhittää peltonsa riemuvuodesta alkaen, jääköön sille arvioimasi täysi hinta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Mutta jos hän pyhittää peltonsa riemuvuoden jälkeen, laskekoon pappi hänelle rahasumman niiden vuosien luvun mukaan, jotka ovat jäljellä seuraavaan riemuvuoteen. Vähennettäköön se arvioimastasi hinnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Jos se, joka on pellon pyhittänyt, tahtoo lunastaa sen, niin antakoon arvioimasi hinnan lisäksi viidennen osan siitä, ja niin se jää hänen omakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Mutta jos hän ei lunasta peltoa, vaan myy sen toiselle, se ei ole enää lunastettavissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Kun pelto riemuvuotena tulee vapaaksi, olkoon se Herralle pyhitetty, niin kuin vihitty pelto. Se tulee papin omaisuudeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Jos joku pyhittää Herralle ostamansa pellon, joka ei ole hänen perintömaataan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'laskekoon pappi hänelle arviohinnan riemuvuoteen asti. Suorittakoon hän samana päivänä arvioimasi hinnan pyhänä lahjana Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Riemuvuotena pelto palautukoon sille, jolta se on ostettu ja jonka perintömaata se on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Kaikki arvioimisesi tapahtukoon pyhäkkösekelin painon mukaan. Sekelissä olkoon kaksikymmentä geeraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Mutta karjan esikoista, joka ensiksi syntyneenä on jo Herralle tuleva, älköön kukaan pyhittäkö, olipa se härkä tai lammas. Se on jo Herran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Jos se on saastaisia eläimiä, lunastakoon omistaja sen arvioimastasi hinnasta ja pankoon lisäksi viidennen osan sen arvosta. Jos sitä ei lunasteta, myytäköön se arvioimaasi hintaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Mitään vihittyä, mitä hyvänsä, jonka joku on vihkinyt Herralle omaisuudestaan, olipa se ihminen, eläin tai perintömaa, älköön myytäkö älköönkä lunastettako. Kaikki vihitty on näet korkeasti pyhää, Herralle tulevaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Ihmistä, ketä hyvänsä, joka on tuhon omaksi vihitty, älköön lunastettako, vaan hänet surmattakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Kaikki maan kymmenykset, sekä pellon viljasta että puiden hedelmistä, ovat Herran. Ne ovat pyhä lahja Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Jos joku tahtoo lunastaa jotakin kymmenyksistään, antakoon siihen lisäksi viidennen osan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Kaikki kymmenykset nautakarjasta ja lampaista ja vuohista, sekä joka kymmenes eläin kaikesta, mikä kulkee paimenen sauvan ali, olkoot pyhiä lahjoja Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Älköön kysyttäkö, onko se hyvä vai huono, älköönkä sitä vaihdettako. Jos joku kuitenkin vaihtaa sen, olkoon sekä se että siihen vaihdettu pyhä. Älköön niitä lunastettako.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Nämä ovat ne käskyt, jotka Herra Siinain vuorella antoi Moosekselle israelilaisia varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Herra puhui Moosekselle Siinain erämaassa ilmestysmajassa toisen kuukauden ensimmäisenä päivänä, toisena vuotena siitä, kun he olivat lähteneet Egyptin maasta, sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, '\"Laskekaa koko Israelin kansan väkiluku suvuittain ja perhekunnittain nimien lukumäärän mukaan, kaikki miespuolet heidän päälukunsa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Pitäkää katselmus, sinä ja Aaron, kaikista Israelin sotakelpoisista miehistä, kahdenkymmenen vuoden ikäisistä ja sitä vanhemmista, osastoittain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Apuna teillä olkoon yksi mies jokaisesta sukukunnasta, sen perhekuntien päämies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Nämä ovat niiden miesten nimet, jotka teitä avustakoot: Ruubenista Elisur, Sedeurin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'Simeonista Selumiel, Suurisaddain poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'Juudasta Nahson, Amminadabin poika');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'Isaskarista Netanel, Suuarin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'Sebulonista Eliab, Heelonin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'Joosefin pojista: Efraimista Elisama, Ammihudin poika ja Manassesta Gamliel, Pedasurin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'Benjaminista Abidan, Gideonin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'Daanista Ahieser, Ammisaddain poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'Asserista Pagiel, Okranin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'Gaadista Eljasaf, Deguelin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'Naftalista Ahira, Eenanin poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Nämä, heidän isiensä sukukuntien ruhtinaat, Israelin heimojen päämiehet, olivat kutsutut tehtäväänsä seurakunnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Mooses ja Aaron ottivat luokseen nämä nimeltä mainitut miehet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'He kokosivat koko seurakunnan toisen kuukauden ensimmäisenä päivänä. Kansa pantiin luetteloihin suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmentävuotiaat ja sitä vanhemmat heidän päälukunsa mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'niin kuin Herra oli Moosesta käskenyt. Silloin hän piti heistä katselmuksen Siinain erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Ruubenin, Israelin esikoisen, jälkeläisiä oli heidän polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän, heidän päälukunsa mukaan, kaikkiaan miespuolisia, kaksikymmentävuotiaita ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'näitä Ruubenin sukukunnasta katselmuksessa olleita oli neljäkymmentäkuusi tuhatta viisisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Simeonin jälkeläisiä oli katselmuksessa heidän polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän, heidän päälukunsa mukaan, kaikkiaan miespuolisia kaksikymmentävuotiaita ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'näitä Simeonin sukukunnasta katselmuksessa olleita oli viisikymmentäyhdeksän tuhatta kolmesataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Gaadin jälkeläisiä oli katselmuksessa heidän polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmentävuotiaita ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'näitä Gaadin sukukunnasta katselmuksessa olleita oli neljäkymmentäviisi tuhatta kuusisataa viisikymmentä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Juudan jälkeläisiä oli katselmuksessa heidän polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotiaita ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'näitä Juudan sukukunnasta katselmuksessa olleita oli seitsemänkymmentäneljä tuhatta kuusisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Isaskarin jälkeläisiä oli katselmuksessa heidän polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmentävuotiaita ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'näitä Isaskarin sukukunnasta katselmuksessa olleita oli viisikymmentäneljä tuhatta neljäsataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Sebulonin jälkeläisiä oli heidän polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmentävuotiaita ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'näitä Sebulonin sukukunnasta katselmuksessa olleita oli viisikymmentäseitsemän tuhatta neljäsataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Joosefin jälkeläisistä Efraimin jälkeläisiä, oli heidän polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmentävuotiaita ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'näitä Efraimin sukukunnasta katselmuksessa olleita oli neljäkymmentätuhatta viisisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, '[Joosefin jälkeläisistä] Manassen jälkeläisiä oli katselmuksessa heidän polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmentävuotiaita ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'näitä Manassen sukukunnasta katselmuksessa olleita oli kolmekymmentäkaksi tuhatta kaksisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Benjaminin jälkeläisiä oli katselmuksessa heidän polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmentävuotiaita ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'näitä Benjaminin sukukunnasta katselmuksessa olleita oli kolmekymmentäviisi tuhatta neljäsataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Daanin jälkeläisiä oli katselmuksessa heidän polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmentävuotiaita ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'näitä Daanin sukukunnasta katselmuksessa olleita oli kuusikymmentäkaksi tuhatta seitsemänsataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Asserin jälkeläisiä oli katselmuksessa heidän polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmentävuotiaita ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'näitä Gaadin sukukunnasta katselmuksessa olleita oli neljäkymmentäyksi tuhatta viisisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Naftalin jälkeläisiä oli katselmuksessa heidän polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmentävuotiaita ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'näitä Naftalin sukukunnasta katselmuksessa olleita oli viisikymmentäkolme tuhatta neljäsataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Nämä ovat ne katselmuksessa olleet, joista Mooses ja Aaron ja Israelin ruhtinaat, nuo kaksitoista miestä, perhekuntiaan edustaen, pitivät katselmuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Kaikkiaan katselmuksessa olleita israelilaisia oli perhekunnittain, kaksikymmentävuotiaita ja sitä vanhempia, kaikkia Israelin sotakelpoisia miehiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'näitä katselmuksessa olleita oli yhteensä kuusisataakolme tuhatta viisisataa viisikymmentä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Mutta leeviläisistä, heidän isiensä sukukunnasta, ei pidetty katselmusta yhdessä muiden kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Sillä Herra oli puhunut Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, '\"Ainoastaan Leevin sukukunnasta älä pidä katselmusta äläkä laske heidän väkilukuaan yhdessä muiden israelilaisten kanssa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'vaan pane leeviläiset hoitamaan lain asumusta ja sen kaikkea kalustoa ja kaikkea, mitä siihen kuuluu. He kantakoot asumusta ja sen kaikkea kalustoa, ja toimittakoot siinä palvelusta sekä leiriytykööt asumuksen ympärille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Kun asumus lähtee liikkeelle, purkakoot leeviläiset sen. Kun asumus pysähtyy leiriytymispaikalle, pystyttäkööt leeviläiset sen. Heihin kuulumaton, joka sitä lähestyy, surmattakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Muut israelilaiset asettukoot osastoittain kukin omaan leiriinsä ja kukin lippunsa luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Mutta leeviläiset leiriytykööt lain asumuksen ympärille, ettei Herran viha kohtaisi Israelin kansaa. Leeviläiset hoitakoot tehtäviä lain asumuksessa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Israelilaiset tekivät kaiken, niin kuin Herra oli Moosesta käskenyt. Niin he tekivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, '\"Israelilaiset leiriytykööt kukin lippunsa luo perhekuntiensa sotamerkkien kohdalle. He leiriytykööt taaemmaksi ilmestysmajan ympärille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Etupuolelle itään päin leiriytyköön Juudan leirin lippukunta osastoittain. Juudan jälkeläisten päämiehenä olkoon Nahson, Amminadabin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'Hänen osastonsa, katselmuksessa olleet, on seitsemänkymmentäneljä tuhatta kuusisataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Hänen viereensä leiriytyköön Isaskarin sukukunta. Isaskarin jälkeläisten päämiehenä olkoon Netanel, Suuarin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'Hänen osastonsa, katselmuksessa olleet, on viisikymmentäneljä tuhatta neljäsataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Sitten leiriytyköön Sebulonin sukukunta. Sebulonin jälkeläisten päämiehenä olkoon Eliab, Heelonin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'Hänen osastonsa, katselmuksessa olleet, on viisikymmentäseitsemän tuhatta neljäsataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Juudan leirin katselmuksessa olleita on siis kaikkiaan sata kahdeksankymmentäkuusi tuhatta neljäsataa miestä, osastoittain. He lähtekööt liikkeelle ensimmäisenä joukkona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Ruubenin leirin lippukunta leiriytyköön etelään päin osastoittain. Ruubenin jälkeläisten päämiehenä olkoon Elisur, Sedeurin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'Hänen osastonsa, katselmuksessa olleet, on neljäkymmentäkuusi tuhatta viisisataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Hänen viereensä leiriytyköön Simeonin sukukunta. Simeonin jälkeläisten päämiehenä olkoon Selumiel, Suurisaddain poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'Hänen osastonsa, katselmuksessa olleet, on viisikymmentäyhdeksän tuhatta kolmesataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Sitten Gaadin sukukunta, ja Gaadin jälkeläisten päämiehenä olkoon Eljasaf, Reguelin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'Hänen osastonsa, katselmuksessa olleet, on neljäkymmentäviisi tuhatta kuusisataa viisikymmentä miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Ruubenin leirin katselmuksessa olleita on siis kaikkiaan sata viisikymmentäyksi tuhatta neljäsataa viisikymmentä miestä, osastoittain. He lähtekööt liikkeelle toisena joukkona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Sitten lähtee liikkeelle ilmestysmaja ja leeviläisten leiri toisten leirien keskellä. Niin kuin olivat leiriytyneet, niin lähteköötkin, kukin kohdallaan, lippukunnittain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Efraimin leirin lippukunta leiriytyköön länteen päin osastoittain. Efraimin jälkeläisten päämiehenä olkoon Elisama, Ammihudin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'Hänen osastonsa, katselmuksessa olleet, on neljäkymmentä tuhatta viisisataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Hänen viereensä leiriytyköön Manassen sukukunta, ja Manassen jälkeläisten päämiehenä olkoon Gamliel, Pedasurin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'Hänen osastonsa, katselmuksessa olleet, on kolmekymmentäkaksi tuhatta kaksisataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Sitten leiriytyköön Benjaminin sukukunta. Benjaminin jälkeläisten päämiehenä olkoon Abidan, Gideonin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'Hänen osastonsa, katselmuksessa olleet, on kolmekymmentäviisi tuhatta neljäsataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Efraimin leirin katselmuksessa olleita on siis osastoittain kaikkiaan satakahdeksan tuhatta ja sata miestä. He lähtekööt liikkeelle kolmantena joukkona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Daanin leirin lippukunta leiriytyköön pohjoiseen päin osastoittain. Daanin jälkeläisten päämiehenä olkoon Ahieser, Ammisaddain poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'Hänen osastonsa, katselmuksessa olleet, on kuusikymmentäkaksi tuhatta seitsemänsataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Hänen viereensä leiriytyköön Asserin sukukunta, ja Asserin jälkeläisten päämiehenä olkoon Pagiel, Okranin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'Hänen osastonsa, katselmuksessa olleet, on neljäkymmentäyksi tuhatta viisisataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Sitten leiriytyköön Naftalin sukukunta. Naftalin jälkeläisten päämiehenä olkoon Ahira, Eenanin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'Hänen osastonsa, katselmuksessa olleet, on viisikymmentäkolme tuhatta neljäsataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Daanin leirin katselmuksessa olleita on siis kaikkiaan sata viisikymmentäseitsemän tuhatta kuusisataa miestä. He lähtekööt liikkeelle viimeisenä joukkona, lippukuntineen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Nämä olivat israelilaisten katselmuksessa olleet, perhekunnittain. Eri leirien katselmuksessa olleita oli osastoittain kaikkiaan kuusisataakolme tuhatta viisisataa viisikymmentä miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Leeviläisten katselmusta ei kuitenkaan pidetty samalla kuin muiden israelilaisten, sillä niin oli Herra Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Israelilaiset tekivät kaiken, niin kuin Herra oli Moosesta käskenyt. He leiriytyivät lippukunnittain, ja lähtivät liikkeelle kukin suvuittain ja perhekunnittain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Tämä on kertomus Aaronin ja Mooseksen suvusta, siihen aikaan kun Herra puhui Moosekselle Siinain vuorella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Nämä ovat Aaronin poikien nimet: Naadab, esikoinen, Abihu, Eleasar ja Iitamar.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Nämä ovat Aaronin poikien, voideltujen pappien, nimet, niiden, jotka olivat vihityt papinvirkaa toimittamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Mutta Naadab ja Abihu olivat kuolleet Herran edessä tuodessaan vierasta tulta Herran eteen Siinain erämaassa. Heillä ei ollut poikia. Niin Eleasar ja Iitamar toimittivat papinvirkaa isänsä Aaronin edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, '\"Tuo Leevin sukukunta esille ja aseta se pappi Aaronin eteen palvelemaan häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'He hoitakoot sekä hänen että koko kansan tehtäviä ilmestysmajan edustalla. He toimittakoot palvelusta asumuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'He hoitakoot kaikkea ilmestysmajan kalustoa ja israelilaisten tehtäviä. He toimittakoot palvelusta asumuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Niin sinun on annettava leeviläiset Aaronille ja hänen pojilleen. Antakoot israelilaiset heidät hänen haltuunsa hänelle palvelijoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Käske Aaronin ja hänen poikiensa hoitaa papinvirkansa. Mutta ulkopuolinen, joka siihen ryhtyy, surmattakoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, '\"Katso, minä itse olen ottanut leeviläiset israelilaisten keskuudesta israelilaisten kaikkien esikoisten sijaan, kaiken sijaan, joka avaa äidinkohdun. Leeviläiset ovat siis tulleet minun omikseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Sillä minun omani on jokainen esikoinen. Sinä päivänä, jona minä surmasin kaikki Egyptin maan esikoiset, minä pyhitin itselleni kaikki Israelin esikoiset, sekä ihmisten että karjan. Minun ne ovat. Minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Herra puhui Moosekselle Siinain erämaassa sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, '\"Toimita leeviläisten katselmus perhekunnittain ja suvuittain. Pidä katselmus kaikista miespuolisista, kuukauden ikäisistä ja sitä vanhemmista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Mooses piti heistä katselmuksen Herran käskyn mukaan, kuten hänelle oli määrätty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Nämä olivat Leevin poikien nimet: Geerson, Kehat ja Merari.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Nämä olivat Geersonin poikien nimet suvuittain: Libni ja Siimei.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Kehatin pojat olivat suvuittain: Amram, Jishar, Hebron ja Ussiel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Merarin pojat olivat, suvuittain, Mahli ja Muusi. Nämä olivat Leevin suvut perhekunnittain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Geersonista polveutuivat libniläisten suku ja siimeiläisten suku. Nämä olivat geersonilaisten suvut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Heitä oli katselmuksessa kaikkien miespuolisten kuukauden ikäisten ja sitä vanhempien lukumäärän mukaan seitsemäntuhatta viisisataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Geersonilaisten suvut leiriytyivät asumuksen taakse länteen päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Geersonilaisten perhekunnan päämies oli Eljasaf, Laaelin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Geersonin poikien hoidettavana ilmestysmajassa oli asumus ja teltta, sen peite, ilmestysmajan oviverho sekä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'asumusta ja alttaria ympäröivän esipihan ympärysverhot ja sen portin verho sekä sen köydet kaikkine niihin kuuluvine palvelustehtävineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Kehatista polveutuivat amramilaisten suku, jisharilaisten suku, hebronilaisten suku ja ussielilaisten suku. Nämä olivat kehatilaisten suvut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Miespuolisten, kuukauden ikäisten ja sitä vanhempien, lukumäärän mukaan heitä oli kaikkiaan kahdeksantuhatta kuusisataa, jotka hoitivat pyhäkkötehtäviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Kehatilaisten suvut leiriytyivät asumuksen sivulle etelään päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Kehatilaisten sukujen perhekunnan päämies oli Elisafan, Ussielin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Heidän hoidettavanaan oli arkki, pöytä, seitsenhaarainen lamppu, alttarit ja pyhä kalusto, jota jumalanpalveluksessa käytettiin, sekä esirippu kaikkine niihin liittyvine palvelustehtävineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Leeviläisten päämiesten esimies oli Eleasar, pappi Aaronin poika. Hän oli niiden päällysmies, jotka hoitivat tehtäviä pyhäkössä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Merarista polveutuivat mahlilaisten suku ja muusilaisten suku. Nämä olivat Merarin suvut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Heitä oli katselmuksessa kaikkien miespuolisten, kuukauden ikäisten ja sitä vanhempien lukumäärän mukaan kuusituhatta kaksisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Merarin sukujen perhekunnan päämies oli Suuriel, Abihailin poika. He leiriytyivät asumuksen sivulle pohjoiseen päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Merarin poikien hoidettavaksi oli uskottu asumuksen laudat, poikkitangot, pylväät ja jalustat sekä kaikki sen kalusto kaikkine palvelustehtävineen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'sekä myös ympärillä olevan esipihan pylväät jalustoineen, vaarnoineen ja köysineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Mutta asumuksen eteen, itään päin, ilmestysmajan eteen, auringonnousuun päin, leiriytyivät Mooses ja Aaron sekä hänen poikansa. Heidän hoidettavanaan oli pyhäkkö, mikä oli israelilaisten hoitoon annettu. Mutta ulkopuolinen, joka ryhtyi siihen, oli surmattava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Katselmuksessa olleita leeviläisiä, joista Mooses ja Aaron Herran käskyn mukaan pitivät katselmuksen suvuittain, kaikkia miespuolisia kuukauden ikäisiä ja sitä vanhempia, oli kaikkiaan kaksikymmentäkaksi tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Herra sanoi Moosekselle: \"Katsasta kaikki israelilaisten miespuoliset esikoiset kuukauden ikäisistä ja sitä vanhemmista ja laske heidän nimiensä lukumäärä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Ota minulle – minä olen Herra – leeviläiset israelilaisten kaikkien esikoisten sijaan sekä myös leeviläisten karja israelilaisten karjan kaikkien esikoisten sijaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Mooses katsasti, kuten Herra oli häntä käskenyt, kaikki israelilaisten esikoiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Heitä oli katselmuksessa kaikkia miespuolisia esikoisia, nimien lukumäärän mukaan kuukauden ikäisiä ja sitä vanhempia, kaikkiaan kaksikymmentä kaksituhatta kaksisataa seitsemänkymmentä kolme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, '\"Ota leeviläiset israelilaisten kaikkien esikoisten sijaan ja leeviläisten karja heidän karjansa sijaan. Niin leeviläiset ovat minun. Minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Mutta lunastukseksi noista kahdestasadasta seitsemästäkymmenestä kolmesta, jonka verran israelilaisten esikoisia on yli leeviläisten määrän,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'ota miestä kohti viisi sekeliä. Ota ne pyhäkkösekelin painon mukaan, kaksikymmentä geeraa laskettuna sekeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Anna raha Aaronille ja hänen pojilleen lunastukseksi niistä, joita on yli leeviläisten määrän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Mooses otti lunastushinnan niistä, joita oli yli leeviläisillä lunastettujen määrän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Hän otti israelilaisten esikoisista tämän rahan, tuhat kolmesataa kuusikymmentä viisi sekeliä pyhäkkösekelin painon mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Mooses antoi sen lunastushinnaksi Aaronille ja hänen pojilleen Herran käskyn mukaan, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Sitten Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, '\"Laske Leevin jälkeläisten joukosta Kehatin jälkeläisten lukumäärä suvuittain ja perhekunnittain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, '[Laske] kolmekymmentävuotiaat ja sitä vanhemmat aina viisikymmentävuotiaisiin asti, kaikki, joiden on palveltava toimittamalla tehtäviä ilmestysmajassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Kehatin poikien palvelustehtävänä ilmestysmajassa olkoon huolenpito korkeasti pyhistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Leirin liikkeelle lähtiessä menkööt Aaron ja hänen poikansa ja päästäkööt alas esiripun sekä peittäkööt sillä lain arkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Pankoot sitten sen päälle tahašinnahkaisen peitteen ja levittäkööt päällimmäiseksi kokonaan sinipunaisista langoista tehdyn vaatteen ja asettakoot paikoilleen sen korennot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Leipien esillepanopöydälle he levittäkööt sinipunaisen vaatteen ja pankoot sen päälle vadit ja kupit, maljat ja juomauhrikannut. Sen päällä olkoon aina myös esillä oleva näkyleipä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Levittäkööt sitten näiden päälle karmiininpunaisen vaatteen ja peittäkööt sen tahašinnahkaisella peitteellä ja asettakoot paikoilleen sen korennot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Ottakoot sitten sinipunaisen vaatteen ja peittäkööt seitsenhaaraisen lampun lamppuineen, lamppusaksineen, karstakuppeineen ja kaikkine öljyastioineen, joita sen hoitamiseen käytetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Käärikööt sen ja kaiken siihen kuuluvan kaluston tahašinnahkaiseen peitteeseen ja pankoot kantopaareille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Levittäkööt sitten kultaiselle alttarille sinipunaisen vaatteen ja peittäkööt sen tahašinnahkaisella peitteellä ja asettakoot paikoilleen sen korennot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Ottakoot mukaan kaiken jumalanpalveluskaluston, jota pyhäkössä käytetään, ja käärikööt sen sinipunaiseen vaatteeseen ja peittäkööt sen tahašinnahkaisella peitteellä ja pankoot kantopaareille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Puhdistakoot alttarin tuhkasta sekä levittäkööt sen päälle purppuranpunaisen vaatteen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Pankoot sen päälle kaiken kaluston, jota alttarilla käytetään: hiilipannut, haarukat, lapiot ja maljat, kaiken alttarikaluston. Levittäkööt sitten sen päälle tahašinnahkaisen peitteen ja asettakoot paikoilleen sen korennot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Kun leirin lähtiessä liikkeelle Aaron ja hänen poikansa ovat valmiiksi peittäneet pyhäkön ja pyhäkön kaiken kaluston, niin tulkoot Kehatin pojat kantamaan, mutta älkööt koskeko pyhäkköön, etteivät kuolisi. Tämä on se kuorma ilmestysmajasta, mitä Kehatin poikien on kannettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Eleasar, pappi Aaronin poika, puolestaan pitäköön huolen seitsenhaaraisen lampun öljystä, hyvänhajuisesta suitsukkeesta, jokapäiväisestä ruokauhrista ja voiteluöljystä. Hän pitäköön huolen koko asumuksesta ja kaikesta, mitä siinä on, pyhäköstä ja sen kalustosta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, '\"Älkää päästäkö kehatilaisten sukuhaaraa häviämään leeviläisten joukosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Tehkää siis heille näin, että he saisivat elää eivätkä kuolisi lähestyessään kaikkeinpyhintä: Aaron ja hänen poikansa menkööt ja asettakoot jokaisen heistä tekemään palvelustehtäväänsä ja kantamaan kannettavaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Mutta älkööt nämä menkö katsomaan pyhiä esineitä, älkööt silmänräpäykseksikään, jotta eivät kuolisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, '\"Laske myös Geersonin jälkeläisten lukumäärä perhekunnittain ja suvuittain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Pidä sotakelpoisten kolmekymmentävuotiaiden ja sitä vanhempien katselmus viisikymmentävuotiaisiin asti, kaikkien niiden, joiden tulee toimittaa palvelusta ilmestysmajassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Geersonilaissukujen tehtävänä palveltaessa ja kannettaessa olkoon tämä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'he kantakoot asumuksen telttakankaan kaistat ja ilmestysmajan, sen peitteen ja tahašinnahkaisen peitteen, joka on sen päällä päällimmäisenä, sekä ilmestysmajan oviverhon');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'ja asumusta ja alttaria ympäröivän esipihan ympärysverhot ja sen portin verhon sekä niiden köydet ja kaiken niiden hoitamiseen tarvittavan kaluston. He toimittakoot kaiken, mitä siinä on tehtävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Aaronin ja hänen poikiensa käskyn mukaisesti tapahtukoon kaikki geersonilaisten palvelus, mitä hyvänsä he kantavat ja toimittavatkin, ja antakaa heidän hoitoonsa kaikki heidän kannettavansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Tämä on geersonilaissukujen palvelustehtävä ilmestysmajassa. He hoitakoot toimensa Iitamarin, pappi Aaronin pojan, johdolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Pidä Merarin jälkeläisten katselmus suvuittain ja perhekunnittain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Pidä kolmekymmentävuotiaiden ja sitä vanhempien katselmus, viisikymmentävuotiaisiin asti, kaikkien, joiden on palveltava toimittamalla palvelusta ilmestysmajassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Nämä ovat uskotut heille kannettaviksi heidän toimittaessaan palvelusta ilmestysmajassa: asumuksen laudat, sen poikkitangot, pylväät ja jalustat');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'sekä ympärillä olevan esipihan pylväät jalustoineen, vaarnoineen ja köysineen, kaikki niiden kalusto ja kaikki, mitä tarvitaan niiden hoitamiseen. Antakaa heidän hoitoonsa nimeltä mainittuina ne esineet, joiden kantaminen on heidän tehtävänään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Tämä on merarilaissukujen palvelustehtävä, mitä hyvänsä he toimittavatkin ilmestysmajassa Iitamarin, pappi Aaronin pojan, johdolla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Mooses ja Aaron sekä kansan päämiehet pitivät Kehatin jälkeläisten katselmuksen suvuittain ja perhekunnittain,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'kolmekymmentävuotiaiden ja sitä vanhempien, aina viisikymmentävuotiaisiin asti, kaikkien, joiden oli toimitettava palvelusta ilmestysmajassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Heitä oli suvuittain katselmuksessa kaksituhatta seitsemänsataa viisikymmentä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Näin paljon kehatilaissuvuista oli katselmuksessa kaikkia ilmestysmajassa palvelevia, joiden katselmuksen Mooses ja Aaron pitivät sen käskyn mukaisesti, jonka Herra oli Mooseksen kautta antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Geersonin jälkeläisistä pidettiin katselmus suvuittain ja perhekunnittain,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'kolmekymmentävuotiaista ja sitä vanhemmista viisikymmentävuotiaisiin asti, kaikista, joiden oli toimitettava palvelusta ilmestysmajassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Heitä oli katselmuksessa suvuittain ja perhekunnittain kaksituhatta kuusisataa kolmekymmentä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Niin paljon oli geersonilaisten suvuista katselmuksessa olleita, kaikkia ilmestysmajassa palvelevia, joiden katselmuksen Mooses ja Aaron pitivät Herran käskyn mukaisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Merarilaisten suvuista pidettiin katselmus suvuittain ja perhekunnittain,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'kolmekymmenvuotiaista ja sitä vanhemmista viisikymmentävuotiaisiin asti, kaikista, joiden oli toimitettava palvelusta ilmestysmajassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Heitä oli suvuittain katselmuksessa kolmetuhatta kaksisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Niin paljon oli merarilaisten suvuista katselmuksessa olleita, joista Mooses ja Aaron pitivät katselmuksen sen käskyn mukaisesti, jonka Herra oli Mooseksen kautta antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Kaikkia katselmuksessa olleita leeviläisiä, joiden katselmuksen Mooses ja Aaron ja Israelin päämiehet pitivät suvuittain ja perhekunnittain,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'kolmekymmenvuotiaita ja sitä vanhempia, viisikymmentävuotiaisiin asti, kaikkia, joiden oli toimitettava palvelusta ja kantamistyötä ilmestysmajassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'oli katselmuksessa kahdeksantuhatta viisisataa kahdeksankymmentä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Sen käskyn mukaisesti, jonka Herra oli Mooseksen kautta antanut, määrättiin jokaiselle heistä oma palvelustehtävänsä ja kantamistyönsä. Tämän katselmuksen Mooses piti, kuten Herra oli häntä käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, '\"Käske israelilaisten karkottaa leiristä jokainen spitaalinen ja jokainen jolla on vuoto ja jokainen kuolleesta saastunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Karkottakaa sellaiset, sekä miehet että naiset, leirin ulkopuolelle, etteivät he saastuttaisi leiriään, jossa minä asun heidän keskellään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Israelilaiset tekivät niin ja karkottivat heidät leirin ulkopuolelle, kuten Herra oli puhunut Moosekselle. Niin israelilaiset tekivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, '\"Puhu israelilaisille: Jos mies tai nainen tekee synnin, minkä tahansa, jonka ihminen tekee menettelemällä uskottomasti Herraa kohtaan, ja se sielu tulee syynalaiseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'tunnustakoon syntinsä, jonka on tehnyt, ja maksakoon velkansa täyteen määrään sekä pankoon siihen lisäksi viidennen osan sen arvosta ja antakoon sen sille, jolle hän on velkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Mutta jos hänellä ei ole sukulunastajaa, jolle velka olisi maksettava, maksettakoon velka Herralle papille tulevana ja sen lisäksi pässi, jolla toimitetaan syynalaiselle sovitus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Jokainen anti, mikä tahansa israelilaisten papille tuomista pyhistä lahjoista, olkoon papin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Jokaisen pyhät lahjat olkoot papille tulevat. Se, mitä joku antaa papille, olkoon papin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, '\"Puhu israelilaisille ja sano heille: jos jonkun miehen vaimo on pettänyt miestään olemalla hänelle uskoton');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'ja jos joku on maannut hänen kanssaan miehen saamatta sitä tietää ja vaimo, vaikka on saastuttanut itsensä, on saanut sen salatuksi, kun ei ole todistajaa häntä vastaan eikä häntä ole teosta tavattu,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'mutta mustasukkaisuuden henki on vallannut miehen ja hän epäilee vaimoaan, joka onkin saastuttanut itsensä, tai jos mustasukkaisuuden henki on vallannut miehen ja hän epäilee vaimoaan, vaikka tämä ei ole saastuttanut itseään, toimittakoon seuraavasti:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'Mies tuokoon vaimonsa papin eteen ja uhrilahjana hänen puolestaan kymmenesosan eefa-mittaa ohrajauhoja, mutta älköön vuodattako sen päälle öljyä älköönkä panko suitsuketta, sillä se on mustasukkaisuusuhri, muistutusuhri, joka johdattaa muistoon pahan teon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Pappi tuokoon vaimon ja asettakoon hänet Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Pappi ottakoon pyhää vettä saviastiaan, ja sitten pappi ottakoon tomua asumuksen lattialta ja pankoon veteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Pappi asettakoon vaimon Herran eteen, päästäköön vaimon tukan hajalle ja asettakoon hänen käsiinsä muistutusuhrin, se on mustasukkaisuusuhrin, ja papin kädessä olkoon katkera kirovesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Sitten pappi vannottakoon vaimoa ja sanokoon hänelle: \'Jos ei kukaan ole maannut kanssasi etkä ole pettänyt miestäsi ja saastuttanut itseäsi, älköön tämä katkera kirovesi vahingoittako sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Mutta jos olet pettänyt miehesi ja saastuttanut itsesi ja joku muu kuin miehesi on maannut kanssasi\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'pappi vannottakoon vaimoa kirovalalla ja sanokoon vaimolle: \'Tehköön Herra nimesi kiroukseksi ja sadatukseksi kansasi keskuudessa, kuihduttakoon Herra lanteesi ja paisuttakoon vatsasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Menköön kirovesi sisuksiisi, niin että vatsasi paisuu ja lanteesi kuihtuvat.\' Vaimo sanokoon: \'Aamen, Aamen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Pappi kirjoittakoon nämä kiroukset ja huuhtokoon kirjoituksen kiroveteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Sitten hän juottakoon vaimolle sen katkeran kiroveden, ja menköön kirovesi häneen, tuskaksi hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Pappi ottakoon vaimon kädestä mustasukkaisuusuhrin ja toimittakoon uhrin heilutuksen Herran edessä ja tuokoon sen alttarille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Pappi ottakoon uhrista kourallisen alttariuhriosaksi ja polttakoon sen alttarilla ja juottakoon sitten vaimolle veden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Kun hän on juottanut vaimolle veden, niin, jos vaimo on saastuttanut itsensä ja ollut miehelleen uskoton, menee kirovesi häneen, hänelle tuskaksi, ja hänen vatsansa paisuu ja lanteensa kuihtuvat, ja vaimon nimi tulee kiroukseksi hänen kansansa keskuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Mutta jos vaimo ei ole saastuttanut itseään, vaan on puhdas, hän ei vahingoitu, vaan pysyy hedelmällisenä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Tämä on laki mustasukkaisuudesta. Jos vaimo pettää miehensä ja saastuttaa itsensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'tai jos jonkun valtaa mustasukkaisuuden henki ja hän epäilee vaimoaan, asettakoon vaimonsa Herran eteen, ja pappi tehköön vaimolle kaiken tämän lain mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Niin mies olkoon syyllisyydestä vapaa, mutta vaimo kantakoon syyllisyytensä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, '\"Puhu israelilaisille ja sano heille: Kun mies tai nainen tekee nasiirilupauksen vihkiytyäkseen Herralle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'pidättyköön viinistä ja väkijuomasta. Älköön juoko hapanviiniä tai hapanta juomaa älköönkä mitään viinirypäleen mehua. Älköön syökö tuoreita älköönkä kuivia rypäleitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Niin kauan kuin hänen nasiirilupauksensa kestää, älköön hän syökö mitään viiniköynnöksestä saatavaa, älköön edes raakileita tai köynnösten versoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Niin kauan kuin hänen nasiirilupauksensa kestää, älköön partaveitsi koskettako hänen päätään. Siihen asti kunnes kuluu umpeen aika, joksi hän on vihkiytynyt Herralle, hän olkoon pyhä ja kasvattakoon päänsä hiukset pitkiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Niin kauan kuin hän on Herralle vihkiytynyt, älköön hän menkö kuolleen luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Älköön hän saastuko edes isästään tai äidistään, veljestään tai sisarestaan heidän kuoltuaan, sillä hänen päässään on Jumalalle vihkiytymisen merkki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Niin kauan kuin hänen nasiirilupauksensa kestää, hän on pyhä Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Jos joku odottamatta, äkkiarvaamatta kuolee hänen läheisyydessään ja hän niin saastuttaa vihityn päänsä, niin ajattakoon hiuksensa puhdistuspäivänään. Seitsemäntenä päivänä hän ne ajattakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Kahdeksantena päivänä hän tuokoon kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa papille ilmestysmajan ovelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Pappi uhratkoon toisen syntiuhriksi ja toisen polttouhriksi ja toimittakoon hänelle sovituksen kuolleen tähden tulleesta synnistä ja pyhittäköön uudelleen hänen päänsä sinä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Vihkiytyköön uudelleen Herralle nasiirilupauksensa ajaksi ja tuokoon vuoden vanhan karitsan vikauhriksi. Mutta kulunut aika jääköön ottamatta huomioon, koska hän saastutti vihkimyksensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Tämä on nasiirilaki: Sinä päivänä, jona hänen nasiirilupauksensa aika on kulunut umpeen, tuotakoon hänet ilmestysmajan ovelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Hän tuokoon uhrilahjanaan Herralle vuoden vanhan virheettömän karitsan polttouhriksi ja vuoden vanhan virheettömän uuhikaritsan syntiuhriksi sekä virheettömän pässin rauhanuhriksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'sekä korillisen ydinjauhoista leivottuja happamattomia leipiä, öljyyn leivottuja kakkuja ja öljyllä voideltuja happamattomia rieskoja sekä niihin kuuluvan ruoka- ja juomauhrin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Pappi tuokoon ne Herran eteen ja toimittakoon hänen syntiuhrinsa ja polttouhrinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Mutta pässin hän uhratkoon rauhanuhriksi Herralle sekä korillisen happamattomia leipiä. Pappi toimittakoon myös hänen ruoka- ja juomauhrinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Nasiiri ajattakoon hiuksensa, vihkiytymisensä merkin, ilmestysmajan ovella ja ottakoon päänsä hiukset, vihkiytymisensä merkin, ja pankoon ne tuleen, joka palaa rauhanuhrin alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Pappi ottakoon pässin keitetyn lavan ja korista happamattoman leipäkakun sekä happamattoman rieskan ja pankoon ne nasiirin käsiin, sen jälkeen kun tämä on ajattanut pois vihkiytymisensä merkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Pappi toimittakoon niiden heilutuksen Herran edessä. Se olkoon pyhä lahja papille. Se annetaan heilutetun rintalihan ja anniksi annetun reiden lisäksi. Sen jälkeen nasiiri saakoon juoda viiniä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Tämä on laki nasiirista, joka tekee lupauksen, ja hänen uhrilahjastaan, jonka hän uhraa Herralle vihkiytymisensä tähden, sen lisäksi, mitä hän muuten saa hankituksi. Tekemänsä lupauksen mukaan hän menetelköön näin, noudattaen vihkiytymistään koskevaa lakia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, '\"Puhu Aaronille ja hänen pojilleen ja sano: Siunatessanne israelilaisia sanokaa heille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Herra siunatkoon sinua ja varjelkoon sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Herra valaiskoon kasvonsa sinulle ja olkoon sinulle armollinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Herra kääntäköön kasvonsa sinun puoleesi ja antakoon sinulle rauhan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Näin he laskekoot nimeni israelilaisten ylle, ja minä siunaan heitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Kun Mooses oli nyt saanut pystytetyksi asumuksen, voidellut ja pyhittänyt sen kaikkine kalustoineen sekä voidellut ja pyhittänyt alttarin kaikkine esineineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Israelin ruhtinaat, perhekuntien päämiehet, nimittäin heimoruhtinaat, katselmuksessa olleiden esimiehet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'toivat lahjanaan Herran eteen kuudet katetut vaunut ja kaksitoista nautaa, kaksi ruhtinasta aina yhdet vaunut ja kukin ruhtinas härän. He toivat ne asumuksen eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Herra sanoi Moosekselle näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, '\"Ota ne heiltä vastaan ilmestysmajan palveluksessa käytettäviksi ja anna ne leeviläisille, kullekin hänen palvelustehtävänsä mukaisesti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Mooses otti vastaan vaunut ja naudat ja antoi ne leeviläisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Hän antoi kahdet vaunut ja neljä nautaa Geersonin pojille heidän palvelustehtävänsä mukaisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Hän antoi neljät vaunut sekä kahdeksan nautaa Merarin pojille sen palvelustehtävän mukaisesti, joka heidän oli suoritettava Iitamarin, pappi Aaronin pojan, johdolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Mutta Kehatin pojille hän ei antanut mitään, koska heidän hoidettavinaan olivat olalla kannettavat pyhät esineet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Ruhtinaat toivat vihkiäislahjoja alttaria varten sinä päivänä, jona se voideltiin, ja ruhtinaat toivat lahjansa alttarin eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Herra sanoi Moosekselle: \"Ruhtinaat tuokoot yksitellen kukin hänelle määrättynä päivänä uhrilahjansa alttarin vihkiäisiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Ensimmäisenä päivänä toi uhrilahjansa Nahson, Amminadabin poika, Juudan sukukunnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Hänen uhrilahjanaan oli hopeavati, sadan kolmenkymmenen sekelin painoinen, ja hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja ydinjauhoja ruokauhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'kymmenen sekelin painoinen kultakuppi täynnä suitsuketta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'mulli, pässi ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'vuohipukki syntiuhriksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'ja rauhanuhriksi kaksi nautaa, viisi pässiä, viisi vuohipukkia ja viisi vuoden vanhaa karitsaa. Tämä oli Nahsonin, Amminadabin pojan, uhrilahja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Toisena päivänä Netanel, Suuarin poika, Isaskarin ruhtinas, toi uhrilahjansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Hän toi uhrilahjanaan hopeavadin, sadan kolmenkymmenen sekelin painoisen, hopeamaljan, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja ydinjauhoja ruokauhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'kymmenen sekelin painoisen kultakupin, täynnä suitsuketta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'mullin, pässin ja vuoden vanhan karitsan polttouhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'vuohipukin syntiuhriksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'ja rauhanuhriksi kaksi nautaa, viisi pässiä, viisi vuohipukkia ja viisi vuoden vanhaa karitsaa. Tämä oli Netanelin, Suuarin pojan, uhrilahja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Kolmantena päivänä Sebulonin jälkeläisten ruhtinas Eliab, Heelonin poika toi uhrilahjansa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'hänen uhrilahjanaan oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja ydinjauhoja ruokauhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'mulli, pässi ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'vuohipukki syntiuhriksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'ja rauhanuhriksi kaksi nautaa, viisi pässiä, viisi vuohipukkia ja viisi vuoden vanhaa karitsaa. Tämä oli Eliabin, Heelonin pojan, uhrilahja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Neljäntenä päivänä Ruubenin jälkeläisten ruhtinas Elisur, Sedeurin poika toi uhrilahjansa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'hänen uhrilahjanaan oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja ydinjauhoja ruokauhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'mulli, pässi ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'vuohipukki syntiuhriksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'ja rauhanuhriksi kaksi nautaa, viisi pässiä, viisi vuohipukkia ja viisi vuoden vanhaa karitsaa. Tämä oli Elisurin, Sedeurin pojan, uhrilahja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Viidentenä päivänä Simeonin jälkeläisten ruhtinas Selumiel, Suurisaddain poika toi uhrilahjansa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'hänen uhrilahjanaan oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja ydinjauhoja ruokauhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, 'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 39, 'mulli, pässi ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, 'vuohipukki syntiuhriksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, 'ja rauhanuhriksi kaksi nautaa, viisi pässiä, viisi vuohipukkia ja viisi vuoden vanhaa karitsaa. Tämä oli Selumielin, Suurisaddain pojan, uhrilahja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'Kuudentena päivänä Gaadin jälkeläisten ruhtinas Eljasaf, Deguelin poika toi uhrilahjansa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'hänen uhrilahjanaan oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja ydinjauhoja ruokauhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 44, 'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 45, 'mulli, pässi ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 46, 'vuohipukki syntiuhriksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 47, 'ja rauhanuhriksi kaksi nautaa, viisi pässiä, viisi vuohipukkia ja viisi vuoden vanhaa karitsaa. Tämä oli Eljasafin, Deguelin pojan, uhrilahja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'Seitsemäntenä päivänä Efraimin jälkeläisten ruhtinas Elisama, Ammihudin poika toi uhrilahjansa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'hänen uhrilahjanaan oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja ydinjauhoja ruokauhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 50, 'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 51, 'mulli, pässi ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 52, 'vuohipukki syntiuhriksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 53, 'ja rauhanuhriksi kaksi nautaa, viisi pässiä, viisi vuohipukkia ja viisi vuoden vanhaa karitsaa. Tämä oli Elisaman, Ammihudin pojan, uhrilahja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'Kahdeksantena päivänä Manassen jälkeläisten ruhtinas Gamliel, Pedasurin poika toi uhrilahjansa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'hänen uhrilahjanaan oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja ydinjauhoja ruokauhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, 'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'mulli, pässi ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, 'vuohipukki syntiuhriksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'ja rauhanuhriksi kaksi nautaa, viisi pässiä, viisi vuohipukkia ja viisi vuoden vanhaa karitsaa. Tämä oli Gamlielin, Pedasurin pojan, uhrilahja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Yhdeksäntenä päivänä Benjaminin jälkeläisten ruhtinas Abidan, Gideonin poika toi uhrilahjansa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'hänen uhrilahjanaan oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja ydinjauhoja ruokauhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, 'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'mulli, pässi ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'vuohipukki syntiuhriksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'ja rauhanuhriksi kaksi nautaa, viisi pässiä, viisi vuohipukkia ja viisi vuoden vanhaa karitsaa. Tämä oli Abidanin, Gideonin pojan, uhrilahja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Kymmenentenä päivänä Daanin jälkeläisten ruhtinas Ahieser, Ammisaddain poika toi uhrilahjansa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'hänen uhrilahjanaan oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja ydinjauhoja ruokauhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'mulli, pässi ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'vuohipukki syntiuhriksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'ja rauhanuhriksi kaksi nautaa, viisi pässiä, viisi vuohipukkia ja viisi vuoden vanhaa karitsaa. Tämä oli Ahieserin, Ammisaddain pojan, uhrilahja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Yhdentenätoista päivänä Asserin jälkeläisten ruhtinas Pagiel, Okranin poika toi uhrilahjansa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'hänen uhrilahjanaan oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja ydinjauhoja ruokauhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'mulli, pässi ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'vuohipukki syntiuhriksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'ja rauhanuhriksi kaksi nautaa, viisi pässiä, viisi vuohipukkia ja viisi vuoden vanhaa karitsaa. Tämä oli Pagielin, Okranin pojan, uhrilahja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Kahdentenatoista päivänä Naftalin jälkeläisten ruhtinas Ahira, Eenanin poika toi uhrilahjansa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'hänen uhrilahjanaan oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja ydinjauhoja ruokauhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'mulli, pässi ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'vuohipukki syntiuhriksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'ja rauhanuhriksi kaksi nautaa, viisi pässiä, viisi vuohipukkia ja viisi vuoden vanhaa karitsaa. Tämä oli Ahiran, Eenanin pojan, uhrilahja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Nämä olivat ne vihkiäislahjat, jotka Israelin ruhtinaat antoivat alttaria varten sinä päivänä, jona se voideltiin: kaksitoista hopeavatia, kaksitoista maljaa, kaksitoista kultakuppia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'kukin hopeavati sadan kolmenkymmenen sekelin ja kukin malja seitsemänkymmenen sekelin painoinen. Näissä astioissa oli siis hopeaa yhteensä kaksituhatta neljäsataa sekeliä pyhäkkösekelin painon mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Kultakuppeja oli kaksitoista, täynnä suitsuketta, kukin kuppi kymmenen sekelin painoinen pyhäkkösekelin painon mukaan. Kupeissa oli siis kultaa yhteensä sata kaksikymmentä sekeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Polttouhrieläimiä oli yhteensä: kaksitoista härkää, kaksitoista pässiä, kaksitoista vuoden vanhaa karitsaa sekä niihin kuuluva ruokauhri. Syntiuhripukkeja oli kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Rauhanuhrieläimiä oli yhteensä kaksikymmentä neljä härkää, kuusikymmentä pässiä, kuusikymmentä vuohipukkia ja kuusikymmentä vuoden vanhaa karitsaa. Nämä olivat ne vihkiäislahjat, jotka annettiin alttaria varten, sen jälkeen kun se oli voideltu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Kun Mooses sitten meni ilmestysmajaan puhumaan Herran kanssa, hän kuuli äänen, joka puhutteli häntä lain arkin päällä olevalta armoistuimelta, molempien kerubien välistä. Silloin Herra puhui hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, '\"Puhu Aaronille ja sano hänelle: kun nostat lamput paikoilleen, niin valaiskoot nuo seitsemän lamppua seitsenhaaraisen lampun edustaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Aaron teki niin. Hän nosti lamput valaisemaan seitsenhaaraisen lampun edustaa, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Seitsenhaarainen lamppu oli tehty näin: se oli kullasta, taottua tekoa, myös sen jalka ja kukkalehdet olivat taottua tekoa. Aivan sen kaavan mukaan, jonka Herra oli Moosekselle näyttänyt, hän teki seitsenhaaraisen lampun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, '\"Ota leeviläiset israelilaisten keskuudesta ja puhdista heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Puhdistaaksesi heidät tee näin: Pirskota heihin synnistä puhdistavaa vettä, ja ajattakoot he koko ruumiinsa partaveitsellä ja peskööt vaatteensa ja puhdistakoot itsensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Sitten ottakoot mullin sekä siihen kuuluvana ruokauhrina öljyllä sekoitettuja ydinjauhoja. Ota toinen mulli syntiuhriksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Tuo sitten leeviläiset ilmestysmajan eteen sekä kokoa kaikki Israelin kansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Kun olet tuonut leeviläiset Herran eteen, israelilaiset laskekoot kätensä leeviläisten päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Sitten Aaron toimittakoon leeviläisille israelilaisten puolesta heilutuksen Herran edessä, että he kelpaisivat Herran palvelukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Mutta leeviläiset laskekoot kätensä mullien pään päälle. Valmista sitten toinen syntiuhriksi ja toinen polttouhriksi Herralle toimittaaksesi sovituksen leeviläisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Aseta sitten leeviläiset Aaronin ja hänen poikiensa eteen ja toimita heille heilutus Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Erota leeviläiset israelilaisten keskuudesta, että leeviläiset olisivat palveluksessani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Sen jälkeen leeviläiset menkööt palvelemaan ilmestysmajaa, sitten kun sinä olet puhdistanut heidät ja toimittanut heille heilutuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Sillä he ovat kokonaan annetut palvelukseeni israelilaisten keskuudesta. Kaiken sen sijaan, joka avaa äidinkohdun, israelilaisten kaikkien esikoisten sijaan, minä olen heidät ottanut palvelukseeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Sillä jokainen esikoinen israelilaisten keskuudessa, niin ihmisten kuin karjankin, on minun. Sinä päivänä, jona minä surmasin kaikki Egyptin maan esikoiset, minä pyhitin heidät itselleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Minä otin leeviläiset israelilaisten kaikkien esikoisten sijaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'Minä annoin leeviläiset Aaronille ja hänen pojilleen palvelijoiksi, israelilaisten keskuudesta, suorittamaan israelilaisten puolesta palvelusta ilmestysmajassa ja toimittamaan israelilaisille sovitusta. Niin israelilaisia ei kohtaa rangaistus siitä, että lähestyvät pyhäkköä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Mooses ja Aaron ja koko Israelin kansa tekivät leeviläisille kaiken, kuten Herra oli antanut Moosekselle käskyn leeviläisistä. Niin israelilaiset heille tekivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Sitten leeviläiset puhdistautuivat synnistä ja pesivät vaatteensa. Aaron toimitti heille heilutuksen Herran edessä, ja Aaron toimitti heille sovituksen heidän puhdistamisekseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Sen jälkeen leeviläiset menivät toimittamaan palvelustaan ilmestysmajassa Aaronin ja hänen poikiensa edessä. Niin kuin Herra oli antanut Moosekselle käskyn leeviläisistä, niin heille tehtiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, '\"Tämä olkoon voimassa leeviläisistä: Kaksikymmentäviisivuotiaat ja sitä vanhemmat menkööt palvelemaan ja toimittamaan palvelusta ilmestysmajassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Mutta viidennestäkymmenennestä ikävuodesta alkaen leeviläinen olkoon palveluksesta vapaa älköönkä enää palvelko,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'vaan auttakoon veljiään heidän tehtäviensä hoitamisessa ilmestysmajassa, mutta palvelusta hän älköön enää toimittako. Järjestä näin leeviläisille heidän tehtävänsä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Herra puhui Moosekselle Siinain erämaassa seuraavana vuotena siitä, kun he olivat lähteneet Egyptin maasta, sen vuoden ensimmäisessä kuussa, sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, '\"Israelilaiset viettäkööt pääsiäisen sille määrättynä aikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Tämän kuukauden neljäntenätoista päivänä, iltahämärässä, viettäkää se sille määrättynä aikana. Viettäkää se kaikkien sitä koskevien käskyjen ja säädösten mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Mooses käski israelilaisten viettää pääsiäistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Niin he viettivät pääsiäisen ensimmäisessä kuussa, kuukauden neljäntenätoista päivänä iltahämärässä, Siinain erämaassa. Israelilaiset tekivät kaiken, niin kuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Mutta siellä oli miehiä, jotka olivat saastuneet kuolleesta eivätkä voineet viettää pääsiäistä sinä päivänä. Niin he astuivat sinä päivänä Mooseksen ja Aaronin eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'Miehet sanoivat hänelle: \"Me olemme saastuneet kuolleesta. Miksi meitä estetään tuomasta Herralle uhrilahjaa sen määräaikana israelilaisten keskuudessa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Mooses sanoi heille: \"Jääkää tähän, minä menen kuulemaan, mitä Herra teistä säätää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, '\"Puhu israelilaisille näin: Jos joku teistä tai teidän jälkeläisistänne on saastunut kuolleesta tai on kaukana matkalla, viettäköön kuitenkin pääsiäistä Herran kunniaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Viettäkööt sitä toisen kuukauden neljäntenätoista päivänä iltahämärässä. Happamattoman leivän ja katkerien yrttien kanssa he syökööt pääsiäislampaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Älkööt jättäkö siitä mitään seuraavaan aamuun älköötkä he siitä luuta rikkoko. Kaikkien pääsiäistä koskevien käskyjen mukaan he viettäkööt sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Mutta se mies, joka on puhdas eikä ole matkoilla ja kuitenkin jättää pääsiäisen viettämättä, hävitettäköön kansastaan, koska hän ei tuonut uhrilahjaa Herralle sille määrättynä aikana. Se mies tulee syynalaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Jos taas muukalainen asuu luonanne ja tahtoo viettää pääsiäistä Herran kunniaksi, viettäköön sitä pääsiäistä koskevien käskyjen ja säädösten mukaan. Samat käskyt olkoot teillä, niin muukalaisella kuin maassa syntyneelläkin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Mutta sinä päivänä, jona asumus pystytettiin, peitti pilvi asumuksen, lain majan, ja illalla näkyi asumuksen päällä kuin tulen hohde aina aamuun asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Niin oli aina: pilvi peitti sen päivällä ja tulen hohde yöllä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Niin usein kuin pilvi kohosi majan päältä, israelilaiset lähtivät liikkeelle. Siihen, mihin pilvi laskeutui, israelilaiset leiriytyivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Herran käskyn mukaan israelilaiset lähtivät liikkeelle, ja Herran käskyn mukaan israelilaiset leiriytyivät. He olivat leiriytyneinä, niin kauan kuin pilvi pysyi asumuksen päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Kun pilvi viipyi asumuksen päällä useampia päiviä, noudattivat israelilaiset, mitä Herra oli käskenyt heidän noudattaa, eivätkä lähteneet liikkeelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Mutta joskus pilvi viipyi asumuksen päällä vain muutamia päiviä. Silloinkin he Herran käskyn mukaan olivat leiriytyneinä ja lähtivät Herran käskyn mukaan liikkeelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Joskus pilvi pysyi paikallaan vain illasta aamuun ja kohosi aamulla. Silloinkin he lähtivät liikkeelle. Tai jos pilvi pysyi päivän ja yön ja sitten kohosi, niin he lähtivät liikkeelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Tai kun pilvi viipyi pysyen asumuksen päällä pari päivää tai kuukauden tai vielä pidemmän ajan, niin israelilaiset olivat leiriytyneinä eivätkä lähteneet liikkeelle. Mutta kun se kohosi, he lähtivät liikkeelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Herran käskyn mukaan he leiriytyivät ja Herran käskyn mukaan he lähtivät liikkeelle. He noudattivat, mitä Herra Mooseksen kautta oli käskenyt heidän noudattaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, '\"Tee itsellesi kaksi hopeatorvea, tee ne taottua tekoa, käyttääksesi niitä kansan koolle kutsumiseen ja leirien liikkeellepanoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Kun niihin molempiin puhalletaan, kokoontukoon koko kansa luoksesi ilmestysmajan oven edustalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Mutta kun ainoastaan toiseen puhalletaan, kokoontukoot sinun luoksesi ruhtinaat, Israelin heimojen päämiehet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Mutta kun puhallatte hälytyssoiton, silloin lähtekööt itään päin leiriytyneet leirit liikkeelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Kun puhallatte toistamiseen hälytyssoiton, lähtekööt etelään päin leiriytyneet leirit liikkeelle. Hälytyssoitto puhallettakoon liikkeelle lähdettäessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Seurakuntaa koolle kutsuttaessa puhaltakaa torveen hälytyssoittoa soittamatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Aaronin pojat, papit, puhaltakoot näitä torvia. Tämä olkoon teille ikuinen säädös sukupolvesta sukupolveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Kun te maassanne lähdette taisteluun vihollista vastaan, joka teitä ahdistaa, soittakaa torvilla hälytys. Silloin te muistutte Herran, Jumalanne, mieleen ja pelastutte vihollisistanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Ilopäivinänne sekä juhlinanne sekä uudenkuun päivinä puhaltakaa torviin uhratessanne poltto- ja rauhanuhrejanne, niin ne saattavat teidän Jumalanne muistamaan teitä. Minä olen Herra, teidän Jumalanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'Toisen vuoden toisen kuukauden kahdentenakymmenentenä päivänä pilvi kohosi lain asumuksen päältä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Silloin israelilaiset lähtivät liikkeelle, leiri leirin jälkeen, Siinain erämaasta, ja pilvi pysähtyi Paaranin erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Niin he ensi kerran lähtivät liikkeelle sillä tavoin, kuten Herra oli Mooseksen kautta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Juudan jälkeläisten leirin lippukunta lähti ensimmäisenä joukkona liikkeelle osastoittain, ja tätä osastoa johti Nahson, Amminadabin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Isaskarin jälkeläisten sukukuntaosastoa johti Netanel, Suuarin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'Sebulonin jälkeläisten sukukuntaosastoa johti Eliab, Heelonin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Kun asumus oli purettu, lähtivät liikkeelle Geersonin pojat ja Merarin pojat, jotka kantoivat asumusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Sitten lähti Ruubenin leirin lippukunta liikkeelle osastoittain. Tätä osastoa johti Elisur, Sedeurin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Simeonin jälkeläisten sukukuntaosastoa johti Selumiel, Suurisaddain poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'Gaadin jälkeläisten sukukuntaosastoa johti Eljasaf, Deguelin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Sitten lähtivät kehatilaiset liikkeelle kantaen pyhiä esineitä. Asumus pantiin pystyyn ennen kuin he saapuivat perille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Sitten lähti Efraimin jälkeläisten leirin lippukunta liikkeelle osastoittain. Tätä osastoa johti Elisama, Ammihudin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Manassen jälkeläisten sukukuntaosastoa johti Gamliel, Pedasurin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'Benjaminin jälkeläisten sukukuntaosastoa johti Abidan, Gideonin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Sitten lähti Daanin jälkeläisten leirin lippukunta liikkeelle kaikkien leirien jälkijoukkona, osastoittain. Tätä osastoa johti Ahieser, Ammisaddain poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Asserin jälkeläisten sukukuntaosastoa johti Pagiel, Okranin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'Naftalin jälkeläisten sukukuntaosastoa johti Ahira, Eenanin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Tällainen oli israelilaisten liikkeellelähtö osastoittain. Niin he lähtivät liikkeelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Mooses puhui Hoobabille, midianilaisen Reguelin, Mooseksen apen, pojalle: \"Me lähdemme siihen paikkaan, josta Herra on sanonut: \'Sen minä annan teille.\' Lähde kanssamme, niin me palkitsemme sinut hyvin, sillä Herra on luvannut hyvää Israelille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Mutta hän vastasi hänelle: \"En lähde, vaan minä menen omaan maahani ja sukuni luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Niin Mooses sanoi: \"Älä jätä meitä, sillä sinähän tiedät, mihin meidän sopii leiriytyä erämaassa. Ryhdy siis meille oppaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Jos lähdet kanssamme, me annamme sinun saada osasi siitä hyvästä, minkä Herra meille suo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Niin he lähtivät liikkeelle Herran vuoren luota ja vaelsivat kolme päivämatkaa. Herran liitonarkki kulki heidän edellään kolme päivämatkaa etsimässä heille levähdyspaikkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Herran pilvi oli heidän päällään päivällä, kun he lähtivät leiristä liikkeelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Kun arkki lähti liikkeelle, Mooses lausui: \"Nouse, Herra, hajaantukoot vihollisesi, ja vihamiehesi paetkoot sinua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Kun arkki laskettiin maahan, hän lausui: \"Palaa, Herra, Israelin heimojen monituhatpäisen joukon luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Mutta kansa tuskitteli. Se oli paha Herran korvissa. Sen kuullessaan Herra vihastui, ja Herran tuli syttyi heidän keskelleen. Se kulutti ulommaisen osan leiriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Silloin kansa huusi Moosesta apuun. Niin Mooses rukoili Herraa, ja tuli alkoi sammua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Paikan nimeksi pantiin Tabeera, koska Herran tuli oli syttynyt siellä heidän keskelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Mutta heidän joukossaan olleelle sekakansalle tuli kova ruuan himo. Silloin israelilaisetkin rupesivat jälleen valittamaan, sanoen: \"Voi, jospa meillä olisi lihaa syödäksemme!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Me muistelemme kaloja, joita söimme Egyptissä ilmaiseksi, kurkkuja, meloneja, ruohosipulia, sipulia ja valkosipulia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Mutta nyt sielumme nääntyy, koska täällä ei ole silmillemme mitään muuta kuin mannaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Manna oli korianterin siemenen kaltaista ja bedellion-pihkan näköistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Kansa riensi sitä kokoamaan ja jauhoi sitä käsikivillä tai survoi huhmaressa. Sitten he keittivät sitä padassa ja valmistivat siitä leipiä. Sen maku oli samanlainen kuin öljyleivoksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Kasteen laskeutuessa yöllä leiriin laskeutui siihen mannakin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Mooses kuuli, kuinka kansa ja jokainen sukukunta vaikeroi, kukin telttansa ovella. Silloin Herra vihastui kovin. Se oli paha myös Mooseksen silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Mooses sanoi Herralle: \"Miksi olet tehnyt niin pahoin palvelijallesi, ja miksi en ole saanut armoa silmiesi edessä, koska olet pannut kaiken tämän kansan taakakseni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Olenko minä kaiken tämän kansan äiti tai isä, koska käsket minua kantamaan sitä sylissäni, niin kuin hoitaja kantaa imeväistä lasta, siihen maahan, jonka olet valalla vannoen luvannut heidän isilleen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Mistä minulla on lihaa antaa kaikelle tälle kansalle, kun he ahdistavat minua itkullaan sanoen: \'Anna meille lihaa syödäksemme\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'En minä jaksa yksinäni kantaa koko tätä kansaa, sillä se on minulle liian raskas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Jos näin aiot kohdella minua, surmaa minut mieluummin, jos olen saanut armon silmiesi edessä, ja päästä minut tätä kurjuutta näkemästä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Silloin Herra puhui Moosekselle: \"Kutsu kokoon minua varten seitsemänkymmentä miestä Israelin vanhimpia, jotka tiedät kansan vanhimmiksi ja päällysmiehiksi. Tuo heidät ilmestysmajalle. Asettukoot he sinne kanssasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Minä astun sitten alas ja puhun siellä kanssasi ja otan henkeä, joka sinussa on, ja annan heille. Siten he voivat auttaa sinua kansataakan kantamisessa, ettei sinun tarvitse kantaa sitä yksinäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Mutta kansalle sano: Pyhittäytykää huomiseksi, niin saatte syödä lihaa, koska itkitte Herran kuullen, sanoen: \'Voi, jospa meillä olisi lihaa syödäksemme! Egyptissä meidän oli hyvä olla.\' Herra antaa nyt teille lihaa syödäksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Siinä ei ole teillä syömistä ainoastaan päiväksi tai kahdeksi, tai viideksi tai kymmeneksi tai kahdeksikymmeneksi päiväksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'vaan kuukauden päiviksi, kunnes ette enää siedä sen hajua ja se iljettää teitä. Sillä te olette pitäneet halpana Herran, joka on keskellänne, ja vaikeroineet hänen edessään sanoen: \'Miksi lähdimme Egyptistä!\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Mooses vastasi: \"Kuusisataa tuhatta jalkamiestä on kansaa, jonka keskuudessa minä elän, ja kuitenkin sinä sanot: \'Minä annan heille lihaa, niin että heillä on sitä syödä kuukauden päivät.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Onko lampaita ja nautoja teurastettaviksi heille, niin että heille riittää, vai kootaanko heille kaikki meren kalat, niin että heille riittää?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Mutta Herra sanoi Moosekselle: \"Onko Herran käsi lyhyt? Nyt saat nähdä, toteutuuko sinulle minun sanani vai ei.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Niin Mooses meni ulos ja kertoi kansalle Herran sanat. Sitten hän kutsui kokoon seitsemänkymmentä miestä kansan vanhimpia ja asetti heidät majan ympärille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Silloin Herra astui alas pilvessä ja puhutteli häntä, otti henkeä, joka hänessä oli, ja antoi sitä niille seitsemällekymmenelle vanhimmalle. Kun henki laskeutui heihin, he profetoivat, mutta sen jälkeen he eivät enää profetoineet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Mutta leiriin oli heitä jäänyt kaksi miestä, toisen nimi oli Eldad ja toisen nimi Meedad. Heihinkin henki laskeutui, sillä hekin olivat luetteloon merkityt, vaikka eivät olleet lähteneet majalle. Nämä profetoivat leirissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Silloin riensi muuan nuorukainen ja ilmoitti Moosekselle sanoen: \"Eldad ja Meedad profetoivat leirissä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Mutta Joosua, Nuunin poika, joka oli ollut Mooseksen palvelija nuoruudestaan asti, puuttui puheeseen sanoen: \"Oi, herrani Mooses, kiellä heitä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Mutta Mooses vastasi hänelle: \"Oletko kateellinen minun puolestani? Oi, jospa koko Herran kansa olisi profeettoja, niin että Herra antaisi Henkensä heihin!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Sitten Mooses siirtyi takaisin leiriin ja hänen kanssaan Israelin vanhimmat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Mutta Herran lähettämä tuuli nousi ja ajoi edellään viiriäisiä mereltä päin ja painoi niitä leiriin päivämatkan laajuudelta joka suunnalle leiristä, lähes kahden kyynärän korkeuteen maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Silloin kansa ryhtyi kokoamaan viiriäisiä ja kokosi niitä koko sen päivän ja koko yön ja koko seuraavan päivän. Vähin määrä, jonka joku sai kootuksi, oli kymmenen hoomer-mittaa. He levittivät niitä pitkin leiriä kuivumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Mutta lihan vielä ollessa heidän hampaissaan, ennen kuin se oli syöty loppuun, syttyi Herran viha kansaa kohtaan, ja Herra tuotti kansalle hyvin suuren surman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Sen paikan nimeksi pantiin Kibrot-Hattaava, koska sinne haudattiin kansasta ne, jotka olivat antautuneet halunsa valtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'Kibrot-Hattaavasta kansa lähti liikkeelle Haserotia kohti ja pysähtyi Haserotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Mutta Mirjam ja Aaron parjasivat Moosesta kuusilaisen naisen tähden, jonka Mooses oli ottanut vaimokseen. Hän oli näet ottanut vaimokseen kuusilaisen naisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'He sanoivat: \"Ainoastaan Mooseksen kauttako Herra puhuu? Eikö hän puhu myös meidän kauttamme?\" Herra kuuli sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Mutta Mooses oli hyvin nöyrä mies, nöyrempi kuin kukaan toinen ihminen maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Niin yhtäkkiä Herra sanoi Moosekselle, Aaronille ja Mirjamille: \"Menkää kaikki kolme ilmestysmajalle.\" Niin he kaikki kolme menivät sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Silloin Herra astui alas pilvenpatsaassa, asettui majan ovelle ja kutsui Aaronia ja Mirjamia. Molemmat menivät sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Herra sanoi: \"Kuulkaa minun sanani. Jos keskuudessanne on profeetta, niin minä ilmestyn hänelle näyssä, puhun hänen kanssaan unessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Niin ei ole minun palvelijani Mooses. Hän on uskollinen koko minun talossani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Hänen kanssaan minä puhun suusta suuhun, avoimesti enkä peitetyin sanoin, ja hän saa katsella Herran muotoa. Miksi siis rohkenitte puhua palvelijaani Moosesta vastaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Niin Herran viha syttyi heitä kohtaan, ja hän meni pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Kun pilvi oli poistunut majan päältä, niin, katso, Mirjam oli lumivalkea spitaalista. Aaron kääntyi Mirjamiin päin, ja katso, tämä oli spitaalinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Silloin Aaron sanoi Moosekselle: \"Oi, herrani! Älä pane meidän päällemme syntiä, jonka olemme tyhmyydessä tehneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Älä anna hänen jäädä kuolleen sikiön kaltaiseksi, sellaiseksi, jonka ruumis on puoleksi mädännyt, kun se tulee äitinsä kohdusta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Silloin Mooses huusi Herran puoleen sanoen: \"Oi, Jumala! Paranna hänet!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Herra vastasi Moosekselle: \"Jos hänen isänsä olisi sylkenyt häntä silmille, eikö hänen olisi ollut hävettävä seitsemän päivää? Olkoon hän nyt suljettuna leirin ulkopuolelle seitsemäksi päiväksi, ja sitten pääsköön takaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Niin Mirjam oli suljettuna leirin ulkopuolelle seitsemäksi päiväksi eikä kansa lähtenyt liikkeelle, ennen kuin Mirjam oli tuotu takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Sen jälkeen kansa lähti liikkeelle Haserotista ja leiriytyi Paaranin erämaahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, '\"Lähetä miehiä vakoilemaan Kanaanin maata, jonka minä annan israelilaisille. Lähettäkää mies kustakin isien sukukunnasta, ainoastaan niitä, jotka ovat ruhtinaita heidän keskuudessaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Mooses lähetti heidät Paaranin erämaasta Herran käskyn mukaan. Miehet olivat kaikki israelilaisten päämiehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Nämä olivat heidän nimensä: Ruubenin sukukunnasta Sammua, Sakkurin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'Simeonin sukukunnasta Saafat, Hoorin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'Juudan sukukunnasta Kaaleb, Jefunnen poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'Isaskarin sukukunnasta Jigal, Joosefin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'Efraimin sukukunnasta Hoosea, Nuunin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'Benjaminin sukukunnasta Palti, Raafun poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'Sebulonin sukukunnasta Gaddiel, Soodin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'Manassen sukukunnasta Joosefin sukukuntaa Gaddi, Suusin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'Daanin sukukunnasta Ammiel, Gemallin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'Asserin sukukunnasta Setur, Miikaelin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'Naftalin sukukunnasta Nahbi, Vofsin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'Gaadin sukukunnasta Genuel, Maakin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Nämä olivat niiden miesten nimet, jotka Mooses lähetti vakoilemaan maata. Mooses antoi Hoosealle, Nuunin pojalle, nimen Joosua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Lähettäessään heidät vakoilemaan Kanaanin maata Mooses sanoi heille: \"Lähtekää nyt Etelämaahan ja nouskaa vuoristoon');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'ja katselkaa, millainen maa on ja millainen kansa, joka siinä asuu, onko se voimakas vai heikko, onko sitä vähän vai paljon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'ja millainen maa on, jossa se asuu, onko se hyvä vai huono, ja millaiset ovat ne kaupungit, joissa se asuu, ovatko ne avonaisia kyliä vai varustettuja kaupunkeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'Katselkaa, millaista maa on, onko se lihavaa vai laihaa, onko siinä puita vai ei. Olkaa rohkealla mielellä ja ottakaa mukaanne sen maan hedelmiä.\" Oli näet se aika, jolloin ensimmäiset rypäleet kypsyivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Niin he lähtivät sinne ja vakoilivat maata Siinin erämaasta Rehobiin asti, josta mennään Hamatiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'He lähtivät Negeviin ja tulivat Hebroniin, jossa asuivat Ahiman, Seesai ja Talmai, Anakin jälkeläiset. Hebron oli rakennettu seitsemän vuotta ennen Egyptin Sooania.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'He tulivat Rypälelaaksoon. Sieltä he leikkasivat viiniköynnöksen, jossa oli rypäleterttu. Kahden miehen täytyi kantaa sitä korennolla. Samoin he ottivat granaattiomenia ja viikunoita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Paikka nimitettiin Rypälelaaksoksi, rypäleen tähden, jonka israelilaiset sieltä leikkasivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'He palasivat maata vakoilemasta neljänkymmenen päivän kuluttua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'He vaelsivat ja tulivat Mooseksen, Aaronin ja kaiken Israelin kansan luo Paaranin erämaahan Kaadekseen. He tekivät heille ja kaikelle kansalle selkoa matkastaan ja näyttivät heille sen maan hedelmiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'He kertoivat hänelle sanoen: \"Me menimme siihen maahan, jonne meidät lähetit. Se tosiaan vuotaa maitoa ja hunajaa, ja tällaisia ovat sen hedelmät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Mutta kansa, joka siinä maassa asuu, on voimakasta, ja kaupungit ovat lujasti varustettuja ja hyvin suuria. Näimmepä siellä Anakin jälkeläisiäkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Amalekilaiset asuvat Negevissä ja heettiläiset, jebusilaiset ja amorilaiset asuvat vuoristossa. Kanaanilaiset taas asuvat meren rannalla ja Jordanin varsilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Kaaleb koetti tyynnyttää kansaa niskoittelemasta Moosesta vastaan ja sanoi: \"Menkäämme sittenkin sinne ja ottakaamme se haltuumme, sillä varmasti me sen voitamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Mutta miehet, jotka olivat käyneet siellä hänen kanssaan, sanoivat: \"Emme me kykene käymään sen kansan kimppuun, sillä se on meitä voimakkaampi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Niin he saattoivat israelilaisten keskuudessa pahaan huutoon sen maan, jota olivat olleet vakoilemassa, sanoessaan: \"Maa, jota olemme kierrelleet ja vakoilleet, on maa, joka syö omia asukkaitaan. Kaikki kansa, jota siellä näimme, oli kookasta väkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Näimmepä siellä jättiläisiäkin, Anakin jättiläisheimon jälkeläisiä. Me olimme mielestämme kuin heinäsirkkoja. Sellaisia me heistäkin olimme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Silloin koko kansa alkoi huutaa ja parkua, ja kansa itki sen yön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Kaikki israelilaiset niskoittelivat Moosesta ja Aaronia vastaan, ja koko kansa sanoi heille: \"Jospa olisimme kuolleet Egyptin maahan tai tähän erämaahan! Jospa olisimme kuolleet!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Miksi Herra viekään meitä tuohon maahan, jossa me kaadumme miekkaan ja vaimomme ja lapsemme joutuvat vihollisen saaliiksi! Eikö meidän olisi parempi palata Egyptiin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'He puhuivat toinen toiselleen: \"Valitkaamme johtaja ja palatkaamme Egyptiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Silloin Mooses ja Aaron lankesivat kasvoilleen Israelin kansan koko seurakunnan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Mutta Joosua, Nuunin poika, ja Kaaleb, Jefunnen poika, jotka olivat olleet mukana maata vakoilemassa, repäisivät vaatteensa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'ja puhuivat kaikelle israelilaisten seurakunnalle näin: \"Maa, jota kävimme vakoilemassa, on hyvin ihana maa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Jos Herra on meille suosiollinen, hän vie meidät siihen maahan ja antaa sen meille, maan, joka vuotaa maitoa ja hunajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Älkää vain kapinoiko Herraa vastaan älkääkä pelätkö sen maan kansaa, sillä heitä ei ole meille kuin suupalaksi. Heidän varjelijansa on väistynyt heistä, mutta meidän kanssamme on Herra. Älkää te heitä pelätkö.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Silloin koko seurakunta vaati heitä kivitettäviksi, mutta Herran kirkkaus ilmestyi kaikille israelilaisille ilmestysmajassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Herra sanoi Moosekselle: \"Kuinka kauan tämä kansa pitää minua pilkkanaan eikä usko minuun, huolimatta kaikista tunnusteoista, jotka olen tehnyt sen keskuudessa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Minä tuhoan sen rutolla ja hävitän sen perin juurin, mutta sinusta minä teen suuremman ja väkevämmän kansan, kuin se on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Mutta Mooses sanoi Herralle: \"Ovathan egyptiläiset kuulleet, että sinä voimallasi olet vienyt tämän kansan heidän keskeltään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'He ovat puhuneet siitä sen maan asukkaille. Hekin ovat siis kuulleet, että sinä, Herra, olet tämän kansan keskellä, sinä Herra, joka olet sille ilmestynyt silmästä silmään, ja että sinun pilvesi pysyy heidän päällään ja että sinä kuljet heidän edellään pilvenpatsaassa päivin ja tulenpatsaassa öin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Mutta jos sinä nyt surmaat tämän kansan, niin kuin yhden miehen, niin kansat, jotka saavat kuulla sitä kerrottavan sinusta, sanovat näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, '\'Koska Herra ei kyennyt viemään tätä kansaa siihen maahan, jonka hän oli heille valalla vannoen luvannut, tappoi hän heidät erämaahan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Osoittautukoon nyt sinun suuri voimasi, Herra, kuten olet puhunut sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, '\' Herra on pitkämielinen ja suuri armossa, hän antaa anteeksi pahat teot ja rikokset, mutta ei jätä niitä rankaisematta, vaan kostaa isien pahat teot lapsille kolmanteen ja neljänteen polveen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Anna siis anteeksi tämän kansan pahat teot suuressa armossasi, niin kuin sinä olet ennenkin antanut anteeksi tälle kansalle, Egyptistä tänne saakka.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Herra vastasi: \"Minä annan anteeksi, niin kuin sinä olet anonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Mutta niin totta kuin minä elän, ja niin totta kuin Herran kirkkaus on täyttävä kaiken maan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'ei kukaan niistä miehistä, jotka ovat nähneet kirkkauteni ja tunnustekoni, jotka minä olen tehnyt Egyptissä ja tässä erämaassa, mutta kuitenkin nyt jo kymmenen kertaa ovat minua kiusanneet eivätkä ole kuulleet ääntäni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'ei yksikään heistä ole näkevä sitä maata, jonka minä valalla vannoen lupasin heidän isilleen. Ei yksikään pilkkaajistani ole sitä näkevä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Mutta koska minun palvelijassani Kaalebissa on toinen henki, niin että hän on seurannut minua uskollisesti, niin hänet minä vien siihen maahan, jossa hän kävi, ja hänen jälkeläisensä saavat sen omakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Mutta koska amalekilaiset ja kanaanilaiset asuvat laaksoissa, kääntykää huomenna toisaalle ja painukaa erämaahan, Kaislameren tietä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, '\"Kuinka kauan tämä paha joukko niskoittelee minua vastaan? Minä olen kuullut, kuinka israelilaiset niskoittelevat minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Sano heille: Niin totta kuin minä elän, sanoo Herra, aivan niin kuin te olette minulle puhuneet, niin minä teille teen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Tähän erämaahan kaatuvat teidän ruumiinne, teidän kaikkien, jotka olette katselmuksessa olleet, niin monta kuin teitä on kaksikymmenvuotiaita ja sitä vanhempia, jotka olette niskoitelleet minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Totisesti, te ette pääse siihen maahan, jonka minä olen kättä kohottaen luvannut antaa teille asuinsijaksi, ei kukaan teistä, paitsi Kaaleb, Jefunnen poika, ja Joosua, Nuunin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Mutta teidän lapsenne, joiden sanoitte joutuvan vihollisen saaliiksi, heidät minä vien sinne, ja he saavat tulla tuntemaan sen maan, jota te halveksitte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Mutta teidän ruumiinne kaatuvat tähän erämaahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'ja teidän lastenne täytyy harhailla paimentolaisina tässä erämaassa neljäkymmentä vuotta ja kärsiä uskottomuutenne tähden, kunnes ruumiinne ovat maatuneet tähän erämaahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Niin kuin te neljäkymmentä päivää vakoilitte maata, niin saatte nyt, päivä vuodeksi luettuna, neljäkymmentä vuotta kärsiä pahoista teoistanne ja tulla tuntemaan, mitä se on, että minä käännyn teistä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Minä, Herra, olen puhunut. Totisesti, niin minä teen tälle pahalle kansalle, joka on käynyt kapinoimaan minua vastaan: he hukkuvat tähän erämaahan, tänne he kuolevat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Mutta ne miehet, jotka Mooses oli lähettänyt maata vakoilemaan ja jotka palattuaan olivat saattaneet koko kansan niskoittelemaan häntä vastaan saattamalla sen maan pahaan huutoon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'ne miehet, jotka olivat saattaneet sen maan pahaan huutoon, kuolivat äkkikuolemalla Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Mutta Joosua, Nuunin poika, ja Kaaleb, Jefunnen poika, jäivät eloon niistä miehistä, jotka olivat käyneet maata vakoilemassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Mooses puhui tämän kaikille israelilaisille. Niin kansa tuli kovin murheelliseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'He nousivat varhain seuraavana aamuna lähteäkseen ylös vuoristoon ja sanoivat: \"Katso, tässä olemme. Lähdemme siihen paikkaan, josta Herra on puhunut, sillä olemme syntiä tehneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Mutta Mooses sanoi: \"Minkä tähden te nyt käytte rikkomaan Herran käskyä? Ei se onnistu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Älkää lähtekö sinne, sillä Herra ei ole keskellänne. Älkää lähtekö, etteivät vihollisenne voittaisi teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Sillä amalekilaiset ja kanaanilaiset ovat siellä teitä vastassa, ja niin te kaadutte miekkaan, sillä te olette kääntyneet pois Herrasta eikä Herra ole kanssanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Yhtäkaikki he lähtivät uppiniskaisuudessaan kulkemaan ylös vuoristoon. Kuitenkaan Herran liitonarkki eikä Mooseskaan siirtynyt leiristä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Silloin amalekilaiset ja kanaanilaiset, jotka asuivat vuoristossa, syöksyivät alas ja voittivat heidät ja hajottivat heidät ajaen heitä aina Hormaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, '\"Puhu israelilaisille ja sano heille: Kun tulette siihen maahan, jonka minä annan teille asuinpaikaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'ja uhraatte Herralle uhrin, poltto- tai teurasuhrin, joko lupausta täyttääksenne tai vapaaehtoisena lahjana tai juhlissanne valmistaaksenne Herralle suloisen tuoksun naudoista tai lampaista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'niin se, joka tuo uhrin, tuokoon lahjanaan Herralle ruokauhriksi kymmenesosan ydinjauhoja, sekoitettuna neljännekseen hiin-mittaa öljyä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'ja juomauhriksi, polttouhrin tai teurasuhrin lisäksi, uhraa neljännes hiin-mittaa viiniä kutakin karitsaa kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Mutta pässin lisäksi uhraa ruokauhrina kaksi kymmenesosaa ydinjauhoja sekoitettuna kolmannekseen hiin-mittaa öljyä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'ja juomauhriksi tuo kolmannes hiin-mittaa viiniä suloiseksi tuoksuksi Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Mutta kun uhraat mullin poltto- tai teurasuhriksi, joko lupausta täyttääksesi tai rauhanuhriksi Herralle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'niin tuotakoon mullin lisäksi ruokauhrina kolme kymmenesosaa ydinjauhoja sekoitettuna puoleen hiin-mittaa öljyä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'ja juomauhriksi tuo puoli hiin-mittaa viiniä suloisesti tuoksuvaksi uhriksi Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Näin tehtäköön kutakin härkää, pässiä, karitsaa tai kiliä uhrattaessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Niin monta kuin uhrieläimiä on, niin tehkää näin kullekin, sen mukaan kuinka monta niitä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Jokainen maassa syntynyt tehköön näin tuodessaan suloisesti tuoksuvan uhrin Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Jos muukalainen, joka asuu luonanne tai on ainiaaksi asettunut keskuuteenne, tahtoo uhrata suloisesti tuoksuvan uhrin Herralle, hän tehköön, niin kuin tekin teette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Seurakunnassa olkoon laki sama teillä kuin muukalaisellakin, joka asuu luonanne. Tämä olkoon teille ikuinen säädös sukupolvesta sukupolveen. Se, mikä koskee teitä, koskekoon myös muukalaista Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Sama laki ja sama oikeus olkoon sekä teillä että muukalaisella, joka asuu luonanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, '\"Puhu israelilaisille ja sano heille: Kun tulette siihen maahan, johon minä teidät vien,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'niin syödessänne sen maan leipää antakaa Herralle anti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Ensimmäisistä jyvärouheistanne antakaa leipäkakku anniksi. Antakaa se, niin kuin puimatantereelta annatte annin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Ensimmäisistä jyvärouheistanne antakaa Herralle anti sukupolvesta sukupolveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Mutta jos erehdyksestä jätätte täyttämättä jonkin näistä käskyistä, jotka Herra on Moosekselle puhunut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'minkä hyvänsä, mistä Herra Mooseksen kautta on teille käskyn antanut siitä päivästä lähtien, jolloin Herra antoi käskynsä, ja edelleen sukupolvesta sukupolveen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'niin, jos rikkomus tapahtui seurakunnan tietämättä, erehdyksestä, uhratkoon koko seurakunta mullin polttouhriksi, suloiseksi tuoksuksi Herralle, myös siihen kuuluvan ruoka- ja juomauhrin, kuten on säädetty, sekä vuohipukin syntiuhriksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Kun pappi sitten on toimittanut sovituksen koko israelilaisten seurakunnalle, rikkomus annetaan heille anteeksi. Se on näet ollut erehdys ja he ovat tuoneet lahjansa uhriksi Herralle sekä syntiuhrinsa Herran eteen erehdyksensä vuoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Se annetaan silloin anteeksi koko israelilaisten seurakunnalle samoin kuin muukalaiselle, joka asuu heidän keskellään, sillä koko kansa on vastuunalainen erehdyksestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Mutta jos joku yksityinen rikkoo erehdyksestä, tuokoon vuoden vanhan vuohen syntiuhriksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Kun pappi on toimittanut sovituksen sille, joka on erehdyksestä, tahtomattaan, rikkonut Herraa vastaan, kun hän on toimittanut hänelle sovituksen, niin hänelle annetaan anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Sama laki olkoon sekä maassa syntyneillä israelilaisilla että muukalaisella, joka asuu heidän keskellään, kun joku rikkoo erehdyksestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Mutta se, joka tahallisesti tekee syntiä, olipa hän maassa syntynyt tai muukalainen, pilkkaa Herraa, niin hänet hävitettäköön kansastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Sillä hän on pitänyt halpana Herran sanan ja rikkonut hänen käskynsä. Hänet tuhottakoon, syntivelka painaa häntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Israelilaisten oleskellessa erämaassa tavattiin mies kokoamassa puita sapatinpäivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Niin ne, jotka hänet tapasivat puita kokoamasta, toivat hänet Mooseksen ja Aaronin ja koko seurakunnan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'He panivat hänet vankilaan, koska ei ollut vielä määrätty, mitä hänelle oli tehtävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Mutta Herra sanoi Moosekselle: \"Se mies rangaistakoon kuolemalla, koko seurakunta kivittäköön hänet leirin ulkopuolella.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Silloin koko seurakunta vei hänet leirin ulkopuolelle, ja he kivittivät hänet kuoliaaksi, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, '\"Puhu israelilaisille ja sano heille, että heidän on sukupolvesta sukupolveen tehtävä itselleen tupsut viittojensa kulmiin ja sidottava kulmien tupsuihin sinipunainen lanka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Tupsut olkoot teillä niin, että ne nähdessänne muistaisitte kaikki Herran käskyt ja noudattaisitte niitä ettekä seuraisi sydämenne ettekä silmienne himoja, jotka houkuttelevat teitä haureuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Niin muistakaa ja täyttäkää kaikki minun käskyni ja olkaa pyhät Jumalallenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Minä olen Herra, teidän Jumalanne, joka vein teidät pois Egyptin maasta ollakseni teidän Jumalanne. Minä olen Herra, teidän Jumalanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Mutta Koorah, Jisharin poika, joka oli Leevin pojan Kehatin poika, otti Daatanin ja Abiramin, Eliabin pojat, ja Oonin, joka oli Ruubenin pojan Peletin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'ja he nousivat kapinaan Moosesta vastaan, ja heihin yhtyi israelilaisista kaksisataa viisikymmentä miestä, kansan päämiehiä, kansankokouksen jäseniä, arvokkaita miehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'He kokoontuivat Moosesta ja Aaronia vastaan ja sanoivat heille: \"Jo riittää! Koko seurakunta, he kaikki, ovat pyhät, ja Herra on heidän keskellään. Miksi te siis korotatte itsenne Herran seurakunnan yli?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Kun Mooses sen kuuli, hän lankesi kasvoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Sitten hän puhui Koorahille ja kaikelle hänen joukolleen sanoen: \"Huomenna Herra ilmoittaa, kuka on hänen omansa, kuka on pyhä ja kenen hän sallii käydä luokseen. Sen, kenet hän valitsee, hän sallii käydä luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Tehkää näin: Ottakaa itsellenne hiilipannut, sinä Koorah ja kaikki joukkosi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'ja virittäkää niihin tuli ja pankaa niihin huomenna suitsuketta Herran edessä, niin se mies, jonka Herra silloin valitsee, on pyhä. Riittäköön se teille, te leeviläiset!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Mooses puhui Koorahille: \"Kuulkaa, te leeviläiset!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Eikö teille jo riitä, että Israelin Jumala on erottanut teidät palvelukseensa Israelin seurakunnasta, sallinut teidän käydä hänen luokseen toimittamaan palvelusta Herran asumuksessa ja seisomaan seurakunnan edessä palvelemassa heitä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Hän salli käydä luokseen sinun ja kaikkien veljiesi, leeviläisten, sinun kanssasi, ja nyt te tavoittelette pappeuttakin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Niin siis sinä ja koko joukkosi käytte kapinoimaan Herraa vastaan, sillä mikä on Aaron, että te häntä vastaan niskoittelette!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Mooses kutsutti Daatanin ja Abiramin, Eliabin pojat. Mutta he sanoivat: \"Emme tule.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Eikö jo riitä, että olet tuonut meidät tänne maasta, joka vuotaa maitoa ja hunajaa, hukuttaaksesi meidät erämaahan? Pyritkö vielä valtiaaksemmekin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Oletpa totisesti tuonut meidät maahan, joka vuotaa maitoa ja hunajaa, ja antanut meille perintöosaksi vainioita ja viinitarhoja! Luuletko voivasi sokaista silmät näiltä ihmisiltä? Emme tule.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Silloin Mooses vihastui kovin ja sanoi Herralle: \"Älä katso heidän uhrilahjansa puoleen. En ole keneltäkään heistä aasiakaan anastanut enkä kenellekään heistä mitään vääryyttä tehnyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Silloin Mooses sanoi Koorahille: \"Astukaa huomenna Herran eteen, sinä itse ja koko joukkosi, sekä myös Aaron.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Ottakoon kukin teistä hiilipannunsa ja pankoon siihen suitsuketta sekä tuokoon Herran eteen hiilipannunsa, kaksisataa viisikymmentä hiilipannua. Myös sinä ja Aaron tuokaa kumpikin hiilipannunne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Niin he ottivat kukin hiilipannunsa, virittivät niihin tulen ja panivat niihin suitsuketta ja asettuivat ilmestysmajan ovelle, samoin myös Mooses ja Aaron.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Mutta Koorah kokosi heitä vastaan koko seurakunnan ilmestysmajan ovelle. Silloin Herran kirkkaus näkyi koko seurakunnalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, '\"Erottautukaa te tästä joukosta, niin minä tuokiossa heidät tuhoan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Mutta he lankesivat kasvoilleen ja sanoivat: \"Oi Jumala, sinä Jumala, jonka vallassa on kaiken lihan henki: jos yksi mies rikkoo, vihastutko silloin koko seurakuntaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Niin Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, '\"Puhu seurakunnalle näin: Lähtekää pois Koorahin, Daatanin ja Abiramin asumuksen ympäriltä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Sitten Mooses nousi ja meni Daatanin ja Abiramin luo, ja Israelin vanhimmat seurasivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Hän puhui seurakunnalle sanoen: \"Siirtykää pois näiden jumalattomien miesten majoilta älkääkä koskeko mihinkään, mikä on heidän, ettette tuhoutuisi kaikkien heidän syntiensä tähden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Niin he lähtivät pois Koorahin, Daatanin ja Abiramin asumuksen ympäriltä. Mutta Daatan ja Abiram olivat tulleet ulos ja asettuneet majojensa ovelle vaimoineen ja suurine ja pienine lapsineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Mooses puhui: \"Tietäkää tästä, että Herra on minut lähettänyt tekemään kaikki nämä teot ja etteivät ne ole tapahtuneet minun omasta tahdostani:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'jos nämä kuolevat samalla tavalla, kuin muut ihmiset kuolevat, ja heidän käy, kuten kaikkien muiden ihmisten käy, niin Herra ei ole minua lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Mutta jos Herra antaa jotakin erikoista tapahtua ja maa avaa kitansa ja nielaisee heidät kaikkineen, niin että he elävältä suistuvat hautaan, niin siitä tietäkää, että nämä miehet ovat pilkanneet Herraa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Tuskin hän oli saanut kaiken tämän sanotuksi, niin maa halkesi heidän altaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'ja maa avasi kitansa ja nielaisi heidät, heidän asuntonsa, kaiken Koorahin väen ja kaikki heidän tavaransa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'He suistuivat kaikkineen elävältä hautaan, ja maa peitti heidät, ja niin heidät hävitettiin seurakunnan keskeltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Koko Israel, joka oli heidän ympärillään, pakeni kuullessaan heidän huutonsa, sillä he pelkäsivät maan nielaisevan heidätkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Mutta tuli lähti Herran luota ja kulutti ne kaksisataa viisikymmentä miestä, jotka olivat tuoneet suitsutusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, '\"Käske Eleasaria, pappi Aaronin poikaa, korjaamaan talteen hiilipannut palosta, mutta pudistamaan tuli niistä kauas,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'sillä ne ovat tulleet pyhäkön omiksi. Noiden henkensä menettäneiden syntisten hiilipannuista takokaa ohuita levyjä alttarin päällystämiseksi, sillä he toivat ne Herran eteen, ja niin ne tulivat pyhäkön omiksi ja merkiksi israelilaisille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Niin pappi Eleasar otti vaskiset hiilipannut, jotka tulen polttamat miehet olivat tuoneet, ja ne taottiin alttarin päällystykseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'muistuttamaan israelilaisille, ettei kukaan ulkopuolinen, joka ei ole Aaronin sukua, lähestyisi polttamaan suitsuketta Herran edessä, niin ettei hänen kävisi samoin kuin Koorahin ja hänen joukkonsa, kuten Herra oli hänelle Mooseksen kautta puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Mutta seuraavana päivänä koko israelilaisten seurakunta niskoitteli Moosesta ja Aaronia vastaan sanoen: \"Te olette surmanneet Herran kansaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Mutta kun kansa kokoontui Moosesta ja Aaronia vastaan, niin he kääntyivät ilmestysmajaan päin, ja katso, pilvi peitti sen, ja Herran kirkkaus näkyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Silloin Mooses ja Aaron menivät ilmestysmajan edustalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, '\"Poistukaa tämän joukon luota, niin minä tuokiossa heidät tuhoan.\" Silloin he lankesivat kasvoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Mooses sanoi Aaronille: \"Ota hiilipannu ja sytytä siihen tuli alttarilta, pane siihen suitsuketta ja vie se nopeasti seurakunnan luo ja toimita heille sovitus, sillä viha on lähtenyt liikkeelle Herran luota, vitsaus on jo alkanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Aaron teki, niin kuin Mooses oli käskenyt, ja riensi seurakunnan keskelle, ja katso, vitsaus oli jo alkanut kansan keskuudessa. Silloin hän suitsutti ja toimitti kansalle sovituksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Hänen siinä seisoessaan kuolleitten ja elävien vaiheilla vitsaus taukosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 14, 'Mutta niitä, jotka vitsauksesta kuolivat, oli neljätoista tuhatta seitsemänsataa henkeä, paitsi niitä, jotka saivat surmansa Koorahin tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 15, 'Sitten Aaron palasi takaisin Mooseksen luo ilmestysmajan ovelle, ja vitsaus oli tauonnut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 16, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 17, '\"Puhu israelilaisille ja ota heiltä, kaikilta heidän ruhtinailtaan, sauva kutakin sukukuntaa kohti, heidän sukukuntiensa mukaan, kaksitoista sauvaa. Kirjoita kunkin nimi hänen sauvaansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 18, 'mutta Leevin sauvaan kirjoita Aaronin nimi, sillä tämänkin sukukunnan päämiehellä olkoon sauvansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 19, 'Pane ne sitten ilmestysmajaan lain arkin eteen, missä ilmestyn teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 20, 'Niin tapahtuu, että sen sauva, kenet minä valitsen, versoo. Siten minä lopetan israelilaisten napinan, niin että pääsen kuulemasta heidän napinaansa teitä vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 21, 'Mooses puhui tämän israelilaisille, ja kaikki heidän ruhtinaansa antoivat hänelle kukin sauvansa sukukunnittain, yhteensä kaksitoista sauvaa, ja Aaronin sauva oli heidän sauvojensa joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 22, 'Mooses pani sauvat lain majaan, Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 23, 'Kun Mooses seuraavana päivänä meni lain majaan, niin, katso, Aaronin sauva, joka oli siinä Leevin sukukunnan puolesta, oli alkanut versoa. Siihen oli ilmestynyt silmuja, puhjennut kukkia ja kasvanut kypsiä manteleita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 24, 'Mooses vei ulos kaikki sauvat Herran kasvojen edestä kaikkien israelilaisten luo. He katselivat niitä ja ottivat kukin sauvansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 25, 'Herra sanoi Moosekselle: \"Vie Aaronin sauva takaisin lain arkin eteen säilytettäväksi merkkinä uppiniskaisille, ja lopeta heidän napinansa, niin että minä pääsen sitä kuulemasta, jotta he eivät kuolisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 26, 'Mooses teki sen. Niin kuin Herra häntä käski, niin hän teki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 27, 'Mutta israelilaiset sanoivat Moosekselle näin: \"Katso, me menehdymme, me hukumme, me kaikki hukumme!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 28, 'Kuka vain lähestyy, kuka ikinä lähestyy Herran asumusta, se kuolee! Onko meidän kaikkien hukuttava?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Herra puhui Aaronille sanoen: \"Sinun, poikiesi ja isäsi suvun on kanssasi kannettava pyhäkköä vastaan tehdyt rikokset. Samoin sinun ja poikiesi on kanssasi kannettava pappeutta vastaan tehdyt rikokset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Mutta salli myös veljiesi, Leevin sukukunnan, isäsi heimon, käydä sinne kanssasi. He liittykööt sinuun ja palvelkoot sinua, kun sinä ja poikasi kanssasi toimitatte palvelusta lain majan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'He hoitakoot sekä sinun tehtäviäsi että kaikkia majan tehtäviä, mutta älkööt lähestykö pyhiä esineitä tai alttaria, etteivät kuolisi, niin he kuin tekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Liittykööt he sinuun ja hoitakoot ilmestysmajan tehtävät, majan kaikki palvelustehtävät, mutta ulkopuolinen älköön lähestykö teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Teidän on hoidettava tehtävät pyhäkössä ja alttarilla, ettei Herran viha enää kohtaisi israelilaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Katso, minä olen ottanut teidän veljenne, leeviläiset, israelilaisten keskuudesta teille lahjaksi, Herralle annettuina toimittamaan palvelusta ilmestysmajassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Mutta sinä ja poikasi kanssasi hoitakaa papinvirkaanne, pitäen huolta kaikista alttarilla ja esiripun sisäpuolella suoritettavista tehtävistä, ja toimittakaa palvelusta siellä. Lahjana minä annan teille papinvirkanne, mutta ulkopuolinen, joka siihen ryhtyy, surmattakoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Herra puhui Aaronille: \"Katso, minä annan sinulle sen, mikä saamistani anneista on otettava talteen. Kaikista israelilaisten pyhistä lahjoista minä annan sen sinulle osuudeksi ja pojillesi ikuiseksi oikeudeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Korkeasti pyhistä lahjoista olkoon omasi tämä, jota ei tulessa polteta: kaikki ne heidän uhrilahjansa, jotka kuuluvat kaikkiin heidän ruokauhreihinsa, syntiuhreihinsa ja vikauhreihinsa, joita he suorittavat minulle korvauksena. Se on korkeasti pyhää. Se olkoon sinulle ja pojillesi tulevaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Syökää se korkeasti pyhässä paikassa. Jokainen miespuolinen saakoon syödä sitä. Olkoon se sinulle pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Antina heidän lahjoistaan olkoon sinulle tuleva tämä: kaiken sen, minkä israelilaiset uhraavat heilutusmenoin, minä annan sinulle, sinun pojillesi ja tyttärillesi ikuiseksi oikeudeksi. Jokainen, joka on puhdas perheessäsi, saakoon syödä sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Kaiken parhaan öljyn ja kaiken parhaan viinin ja viljan, minkä he ensi sadosta antavat Herralle, sen minä annan sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Ensi sato kaikesta, mitä heidän maassaan kasvaa ja minkä he tuovat Herralle, olkoot sinun. Jokainen, joka on puhdas perheessäsi, saakoon syödä niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Kaikki, mitä Israelissa on vihittyä Herralle, olkoon sinun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Kaikki, mikä avaa äidinkohdun, mikä elollinen hyvänsä, joka tuodaan Herralle, ihmisistä tai karjasta, olkoon sinun. Lunastuta kuitenkin ihmisen esikoinen samoin kuin saastaisen eläimen esikoinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Mitä heidän lunastamiseensa tulee, niin lunastuta heidät kuukauden ikäisistä alkaen sinun asettamastasi viiden sekelin arviohinnasta pyhäkkösekelin painon mukaan, sekeli kaksikymmentä geeraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Mutta naudan tai lampaan tai vuohen esikoista älä lunastuta. Ne ovat pyhiä. Vihmo niiden veri alttarille ja polta niiden rasva uhriksi, suloiseksi tuoksuksi Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Mutta niiden liha olkoon sinun. Niin kuin heilutettu rintalihakin ja oikea reisi olkoot sinun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Kaikki pyhät annit, joita israelilaiset antavat Herralle, minä annan sinulle, sinun pojillesi ja tyttärillesi ikuiseksi oikeudeksi. Se olkoon ikuinen suolaliitto Herran edessä sinulle ja jälkeläisillesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Herra puhui Aaronille: \"Sinulla älköön olko perintöosaa heidän maassaan älköönkä osuutta heidän keskellään. Minä itse olen sinun osuutesi ja perintöosasi israelilaisten keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Mutta leeviläisille minä annan kaikki kymmenykset Israelissa perintöosaksi palkkana siitä palveluksesta, jonka he toimittavat ilmestysmajassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Älkööt muut israelilaiset enää lähestykö ilmestysmajaa, etteivät joutuisi syynalaisiksi ja kuolisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Ainoastaan leeviläiset toimittakoot palvelusta ilmestysmajassa ja kantakoot tehdyt rikokset. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen. Mutta perintöosaa israelilaisten keskellä älköön heillä olko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Sillä israelilaisten kymmenykset, jotka he antavat Herralle anniksi, minä annan leeviläisille perintöosaksi. Sen vuoksi minä kiellän heiltä perintöosan israelilaisten keskuudessa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, '\"Puhu leeviläisille ja sano: Kun otatte israelilaisilta kymmenykset, jotka minä olen määrännyt heidän teille annettavaksi perintöosaksenne, niin antakaa siitä Herralle anti, kymmenykset kymmenyksistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Se katsotaan teidän anniksenne, niin kuin puimatantereelta annetut jyvät tai kuurnasta tullut mehu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Niin antakaa tekin Herralle anti kaikista kymmenyksistä, jotka te saatte israelilaisilta. Tämä Herralle niistä tuleva anti antakaa pappi Aaronille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Kaikista saamistanne lahjoista antakaa Herralle täysi anti. Kaikesta, mikä on parasta, antakaa pyhä lahja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Sano heille: Kun te siitä annatte parhaimman osan, niin se katsotaan leeviläisten anniksi niin kuin puimatantereen tai kuurnan sato.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Te ja teidän perheenne saatte sen syödä missä hyvänsä, sillä se on teille palkka palveluksestanne ilmestysmajassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Kun te näin annatte siitä anniksi parhaimman osan, ette joudu syynalaisiksi ettekä saastuta israelilaisten pyhiä lahjoja ettekä kuole.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, '\"Tämä on lain määräys, jonka Herra sääti sanoen: Käske israelilaisia tuomaan sinulle ruskeanpunainen, virheetön hieho, jossa ei ole mitään vammaa ja jonka päälle iestä ei ole vielä pantu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Antakaa se pappi Eleasarin haltuun, ja vietäköön se leiristä ulos ja teurastettakoon hänen edessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Pappi Eleasar ottakoon sen verta sormeensa ja pirskottakoon sen verta ilmestysmajan etupuolta kohti seitsemän kertaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Hieho poltettakoon hänen nähtensä. Nahkoineen, lihoineen ja verineen sekä ruokasulineen se poltettakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Mutta pappi ottakoon setripuuta, iisoppikorren ja helakanpunaista lankaa ja viskatkoon ne tuleen, missä hieho palaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Sitten pappi pesköön vaatteensa ja pesköön ruumiinsa vedessä ja menköön leiriin. Mutta pappi olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Sekin, joka poltti hiehon, pesköön vaatteensa vedellä ja pesköön ruumiinsa vedellä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Sitten joku, joka on puhdas, kootkoon hiehon tuhkan ja pankoon sen talteen leirin ulkopuolelle puhtaaseen paikkaan. Säilytettäköön se israelilaisten seurakunnalle puhdistusvettä varten. Tämä on syntiuhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Se, joka kokosi hiehon tuhkan, pesköön vaatteensa ja olkoon saastainen iltaan asti. Tämä olkoon ikuinen säädös israelilaisille ja muukalaiselle, joka asuu heidän keskellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Joka koskee kuolleen ihmisen ruumiiseen, kenen hyvänsä, olkoon saastainen seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Hän puhdistakoon itsensä tällä vedellä kolmantena ja seitsemäntenä päivänä, niin hän tulee puhtaaksi. Mutta jos hän ei puhdistaudu kolmantena ja seitsemäntenä päivänä, hän ei tule puhtaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Jokainen, joka koskee kuolleeseen, kuolleen ihmisen ruumiiseen, eikä puhdistaudu, saastuttaa Herran asumuksen. Hänet hävitettäköön Israelista, koska puhdistusvettä ei ole vihmottu häneen. Hän on saastainen. Hänen saastaisuutensa pysyy hänessä yhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Tämä on laki: Kun joku kuolee telttamajassa, niin jokainen, joka menee siihen majaan, ja jokainen, joka on siinä majassa, olkoon saastainen seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Jokainen avoin astia, johon ei ole peitettä sidottu, olkoon saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Jokainen, joka ulkona kedolla koskee miekalla surmattuun tai muulla tavoin kuolleeseen tai ihmisluuhun tai hautaan, olkoon saastainen seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Mutta näin saastunutta varten otettakoon poltetun syntiuhrin tuhkaa ja kaadettakoon sen päälle astiaan raikasta vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Ottakoon sitten joku, joka on puhdas, iisoppikorren ja kastakoon sen siihen veteen ja pirskottakoon sitä tuohon majaan ja kaikkiin sen esineisiin ja ihmisiin, jotka siellä olivat, samoin kuin siihen, joka on koskenut luuhun tai surmattuun tai muulla tavoin kuolleeseen tai hautaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Puhdas pirskottakoon sitä saastuneeseen kolmantena ja seitsemäntenä päivänä ja puhdistakoon hänet seitsemäntenä päivänä. Sitten hän pesköön vaatteensa ja peseytyköön vedessä, niin hän tulee illalla puhtaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Mutta se, joka on saastunut eikä puhdistaudu, hävitettäköön seurakunnasta, koska hän on saastuttanut Herran pyhäkön eikä puhdistusvettä ole vihmottu häneen. Hän on saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Tämä olkoon heille ikuinen säädös. Mutta puhdistusveden pirskottaja pesköön vaatteensa, ja se, joka koskee puhdistusveteen, olkoon saastainen iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Kaikki, mihin saastunut koskee, olkoon saastaista. Myös se, joka koskee häneen, olkoon saastainen iltaan asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Sen jälkeen israelilaiset, koko seurakunta, tulivat Siinin erämaahan ensimmäisenä kuukautena, ja kansa asettui Kaadekseen. Siellä Mirjam kuoli, ja hänet haudattiin sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Mutta kansalla ei ollut vettä. Niin he kokoontuivat Moosesta ja Aaronia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Kansa riiteli Moosesta vastaan ja sanoi näin: \"Jospa mekin olisimme hukkuneet silloin, kun veljemme hukkuivat Herran edessä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Minkä tähden toitte Herran seurakunnan tähän erämaahan kuollaksemme karjoinemme tänne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Miksi johdatitte meidät pois Egyptistä tuodaksenne meidät tähän pahaan paikkaan, jossa ei kasva viljaa eikä viikunoita, ei viiniköynnöksiä eikä granaattiomenia, ja jossa ei ole vettä juoda?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Mutta Mooses ja Aaron menivät seurakunnan luota ilmestysmajan ovelle ja lankesivat kasvoilleen. Silloin heille näkyi Herran kirkkaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, '\"Ota sauva ja kokoa seurakunta, sinä ja veljesi Aaron. Puhukaa heidän silmiensä edessä kalliolle, niin se antaa vettä. Sinä saat vettä tulemaan heille kalliosta ja juotat joukon ja sen karjan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Niin Mooses otti sauvan Herran kasvojen edestä, niin kuin hän oli häntä käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Mooses ja Aaron kokosivat seurakunnan kallion eteen. Hän sanoi heille: \"Kuulkaa nyt, te niskurit! Onko meidän saatava teille vettä tästä kalliosta?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Niin Mooses nosti kätensä ja iski kalliota kahdesti sauvallaan, ja siitä lähti runsaasti vettä, niin että kansa ja sen karja saivat juoda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Mutta Moosekselle ja Aaronille Herra sanoi: \"Koska ette uskoneet minuun ettekä pitäneet minua pyhänä israelilaisten silmien edessä, ette saa viedä tätä seurakuntaa siihen maahan, jonka minä heille annan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Tämä oli Meriban vesi, jonka luona israelilaiset riitelivät Herraa vastaan ja hän näytti heille pyhyytensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Mutta Mooses lähetti Kaadeksesta sanansaattajat Edomin kuninkaan luo sanomaan: \"Näin sanoo veljesi Israel: Sinä tunnet kaiken vaivan, joka on meitä kohdannut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'kuinka isämme lähtivät Egyptiin, kuinka olemme asuneet Egyptissä kauan aikaa ja kuinka egyptiläiset kohtelivat pahoin meitä ja isiämme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'Mutta me huusimme Herran puoleen, ja hän kuuli huutomme ja lähetti Enkelin, joka vei meidät pois Egyptistä. Katso, me olemme nyt Kaadeksessa, kaupungissa, joka on maasi rajalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Salli meidän kulkea maasi läpi. Me emme kulje peltojen emmekä viinitarhojen poikki emmekä juo vettä kaivoista. Poikkeamatta oikealle tai vasemmalle me kuljemme valtatietä, kunnes olemme päässeet alueesi läpi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Mutta Edom vastasi hänelle: \"Älä kulje maani läpi. Muuten lähden miekka kädessä sinua vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Mutta israelilaiset sanoivat hänelle: \"Maantietä me kuljemme, ja jos juomme vettäsi, me tai karjamme, niin maksamme sen, kun vain saamme jalkaisin kulkea maasi läpi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Mutta hän vastasi: \"Tästä et kulje!\" Sitten Edom lähti häntä vastaan suurella sotajoukolla ja vahvasti varustettuna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Kun siis Edom kielsi Israelia kulkemasta maansa läpi, niin Israel väistyi sieltä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'He lähtivät liikkeelle Kaadeksesta. Sitten israelilaiset, koko kansa, tulivat Hoorin vuorelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Mutta Herra sanoi Moosekselle ja Aaronille Hoorin vuorella, Edomin maan rajalla, näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, '\"Aaron otetaan nyt pois heimonsa luo, sillä hän ei pääse siihen maahan, jonka annan israelilaisille, koska te niskoittelitte käskyäni vastaan Meriban veden luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Ota Aaron ja hänen poikansa Eleasar ja vie heidät Hoorin vuorelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'Riisu Aaronilta vaatteet ja pue ne hänen poikansa Eleasarin ylle. Aaron otetaan pois ja kuolee siellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Mooses teki, niin kuin Herra oli käskenyt. He nousivat Hoorin vuorelle koko kansan silmien edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Mooses riisui Aaronilta vaatteet ja puki ne hänen poikansa Eleasarin ylle. Niin Aaron kuoli siellä vuoren huipulla, mutta Mooses ja Eleasar astuivat alas vuorelta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Kun koko kansa sai tietää, että Aaron oli kuollut, niin he, koko Israelin heimo, itkivät Aaronia kolmekymmentä päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Mutta kun Aradin kuningas, kanaanilainen, joka asui Negevissä, kuuli, että Israel oli tulossa Atarimin tietä, hän ryhtyi sotimaan Israelia vastaan ja otti muutamia heistä vangiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Silloin Israel teki lupauksen Herralle ja sanoi: \"Jos sinä annat tämän kansan käsiini, niin minä vihin sen kaupungit tuhon omiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Herra kuuli Israelin ääntä ja antoi kanaanilaiset heidän käsiinsä. Niin Israel vihki heidät ja heidän kaupunkinsa tuhon omiksi. Sen paikan nimeksi pantiin Horma.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Sen jälkeen he lähtivät liikkeelle Hoorin vuorelta Kaislameren tietä kiertääkseen Edomin maan. Mutta matkalla kansa kävi kärsimättömäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Kansa puhui Jumalaa ja Moosesta vastaan: \"Minkä tähden te johdatitte meidät pois Egyptistä kuolemaan erämaahan? Eihän täällä ole leipää eikä vettä, ja me olemme kyllästyneet tähän huonoon ruokaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Silloin Herra lähetti kansan sekaan myrkkykäärmeitä, jotka purivat kansaa, niin että paljon kansaa Israelista kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Niin kansa tuli Mooseksen luo, ja he sanoivat: \"Me teimme syntiä, kun puhuimme Herraa ja sinua vastaan. Rukoile Herraa, että hän poistaa käärmeet kimpustamme.\" Mooses rukoili kansan puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Silloin Herra sanoi Moosekselle: \"Tee itsellesi käärme ja pane se tangon päähän, niin jokainen purtu, joka siihen katsoo, jää eloon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Niin Mooses teki vaskikäärmeen ja pani sen tangon päähän. Jos sitten käärmeet purivat ketä hyvänsä ja tämä katsoi vaskikäärmeeseen, hän jäi eloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Sitten israelilaiset lähtivät liikkeelle ja leiriytyivät Oobotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'He lähtivät liikkeelle Oobotista ja leiriytyivät Iije-Abarimiin siinä erämaassa, joka on Mooabista itään, auringon nousun puolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Sieltä he lähtivät liikkeelle ja leiriytyivät Seredin laaksoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Sieltä he lähtivät liikkeelle ja leiriytyivät erämaahan tuolle puolelle Arnon-jokea, joka lähtee amorilaisten alueelta, sillä Arnon on Mooabin rajana Mooabin ja amorilaisten maan välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Sen tähden sanotaan \" Herran sotien kirjassa\": \"Vaaheb Suufassa ja Arnonin laaksot');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'ja laaksojen rinteet, jotka ulottuvat Aarin tienoille ja kallistuvat Mooabin rajaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Sieltä he kulkivat Beeriin. Se oli se kaivo, josta Herra oli sanonut Moosekselle: \"Kokoa kansa, niin minä annan heille vettä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Silloin Israel lauloi tämän laulun: \"Kuohu, kaivo! – laulakaa sille laulu –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'kaivo, jonka ruhtinaat kaivoivat, kansan parhaat koversivat valtikallaan, sauvoillaan!\" Tästä erämaasta he kulkivat Mattanaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'ja Mattanasta Nahalieliin ja Nahalielista Baamotiin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'ja Baamotista siihen laaksoon, joka on Mooabin maassa, Pisgan huipun juurella, joka kohoaa yli erämaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Israel lähetti sanansaattajat Siihonin, amorilaisten kuninkaan, luo sanomaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, '\"Salli minun kulkea maasi läpi. Me emme poikkea pelloille emmekä viinitarhoihin emmekä juo vettä kaivoista. Kuninkaan tietä me kuljemme, kunnes olemme päässeet alueesi läpi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Mutta Siihon ei sallinut Israelin kulkea alueensa läpi, vaan kokosi kaiken väkensä ja lähti Israelia vastaan erämaahan. Kun hän oli tullut Jahaaseen, hän ryhtyi taisteluun Israelia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Mutta Israel voitti hänet miekan terällä ja valloitti hänen maansa Arnonista Jabbokiin, aina ammonilaisten maahan asti, sillä ammonilaisten raja oli varustettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Israel valtasi sieltä kaikki kaupungit. Israel asettui kaikkiin amorilaisten kaupunkeihin, Hesboniin ja kaikkiin sen tytärkaupunkeihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Sillä Hesbon oli amorilaisten kuninkaan Siihonin kaupunki. Hän oli näet käynyt sotaa entistä Mooabin kuningasta vastaan sekä vallannut häneltä koko hänen maansa Arnoniin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Niinpä runosepät sanovat: \"Tulkaa Hesboniin! Rakennettakoon ja varustettakoon Siihonin kaupunki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Sillä tuli lähti Hesbonista, liekki Siihonin kaupungista. Se kulutti Aar-Mooabin, Arnonin kukkuloiden valtiaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Voi sinua, Mooab! Sinä hukuit, Kemoksen kansa! Poikiensa hän salli tulla pakolaisiksi, tyttäriensä amorilaisten kuninkaan Siihonin vangeiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Me ammuimme heidät, Hesbon kukistui Diibonia myöten. Me hävitimme Noofahiin asti, aina Meedebaan saakka.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Niin Israel asettui amorilaisten maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Mooses lähetti vakoilemaan Jaeseria, ja he valloittivat sen tytärkaupungit. Hän karkotti siellä olleet amorilaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Sitten he kääntyivät toisaalle ja kulkivat Baasanin tietä. Silloin lähti Oog, Baasanin kuningas, heitä vastaan. Hän ja kaikki hänen väkensä lähtivät Edreihin taistelemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Mutta Herra sanoi Moosekselle: \"Älä pelkää häntä, sillä minä annan hänet ja kaiken hänen kansansa ja maansa käteesi. Tee hänelle, niin kuin teit Siihonille, amorilaisten kuninkaalle, joka asui Hesbonissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'He voittivat hänet, hänen poikansa ja kaiken hänen väkensä päästämättä pakoon ainoatakaan. Niin he valloittivat hänen maansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Sitten israelilaiset lähtivät liikkeelle ja leiriytyivät Mooabin arolle Jordanin tuolle puolelle Jerikon kohdalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Mutta Baalak, Sipporin poika, näki kaiken, mitä Israel oli tehnyt amorilaisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Mooab pelkäsi tätä kansaa suuresti, kun sitä oli niin paljon, ja Mooab kauhistui israelilaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Mooab sanoi Midianin vanhimmille: \"Nyt tuo lauma syö puhtaaksi kaiken ympäriltämme, niin kuin härkä syö kedon vihannuuden.\" Baalak, Sipporin poika, oli Mooabin kuninkaana siihen aikaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Hän lähetti sanansaattajat Bileamin, Beorin pojan, luo Petoriin, joka on Eufrat-virran varrella, heimolaistensa maahan kutsumaan häntä ja käski sanoa hänelle: \"Katso, Egyptistä on lähtenyt liikkeelle kansa. Katso, se on tulvinut yli maan ja asettunut minua lähelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Tule siis ja kiroa puolestani tämä kansa, sillä se on minua väkevämpi. Ehkä minä sitten saan sen voitetuksi ja karkotetuksi maasta. Sillä minä tiedän, että se, jonka sinä siunaat, on siunattu, ja se, jonka sinä kiroat, on kirottu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Niin Mooabin vanhimmat ja Midianin vanhimmat lähtivät matkaan, tietäjänpalkka mukanaan. Kun he saapuivat Bileamin luo, he puhuivat hänelle Baalakin sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Hän vastasi heille: \"Viipykää täällä tämä yö, niin minä annan teille vastauksen sen mukaan, kuin Herra minulle puhuu.\" Silloin jäivät mooabilaisten päämiehet Bileamin luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Niin Jumala tuli Bileamin luo ja kysyi: \"Keitä ovat ne miehet, jotka ovat luonasi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Bileam vastasi Jumalalle: \"Baalak, Sipporin poika, Mooabin kuningas, on lähettänyt heidät tuomaan minulle tämän sanan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, '\'Katso, kansa on lähtenyt Egyptistä ja on tulvinut yli maan. Tule siis, kiroa se minun puolestani, ehkä sitten voin ryhtyä taisteluun sitä vastaan ja karkottaa sen.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Mutta Jumala sanoi Bileamille: \"Älä mene heidän kanssaan äläkä kiroa sitä kansaa, sillä se on siunattu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Niin Bileam nousi aamulla ja sanoi Baalakin päämiehille: \"Menkää takaisin maahanne, sillä Herra ei ole sallinut minun lähteä teidän kanssanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Silloin Mooabin päämiehet nousivat ja tulivat Baalakin luo ja sanoivat: \"Bileam ei suostunut lähtemään kanssamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Mutta Baalak lähetti uudestaan päämiehiä matkaan, vielä useampia ja arvokkaampia kuin edelliset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'He saapuivat Bileamin luo ja sanoivat hänelle: \"Näin sanoo Baalak, Sipporin poika: \'Älä kieltäydy tulemasta luokseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Sillä minä palkitsen sinut ylenpalttisesti ja teen kaiken, mitä minulta vaadit. Tule siis ja kiroa minun puolestani tämä kansa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Mutta Bileam vastasi ja sanoi Baalakin palvelijoille: \"Vaikka Baalak antaisi minulle talonsa täyden hopeaa ja kultaa, en sittenkään voisi, en pienessä enkä suuressa, rikkoa Herran, Jumalani, käskyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Mutta jääkää nyt tänne tekin täksi yöksi saadakseni tietää, mitä Herra vielä minulle sanoo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Niin Jumala tuli Bileamin luo yöllä ja sanoi hänelle: \"Jos nämä miehet ovat tulleet kutsumaan sinua, nouse ja lähde heidän kanssaan, mutta tee vain se, mitä minä sinulle sanon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Bileam nousi aamulla, satuloi aasintammansa ja lähti matkaan Mooabin päämiesten kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Mutta kun hän lähti, syttyi Jumalan viha, ja Herran Enkeli asettui tielle estämään häntä hänen ratsastaessaan aasintammallaan mukanaan kaksi palvelijaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Kun aasintamma näki Herran Enkelin seisovan tiellä paljastettu miekka kädessään, niin se poikkesi tieltä ja meni peltoon. Mutta Bileam löi aasintammaa palauttaakseen sen tielle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Sitten Herran Enkeli asettui solaan viinitarhojen välille, jossa oli kiviaita kummallakin puolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Kun aasintamma näki Herran Enkelin, niin se painautui aitaan ja likisti Bileamin jalkaa aitaa vasten. Niin hän löi sitä vielä kerran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Silloin Herran Enkeli meni taas edemmäksi ja asettui ahtaaseen paikkaan, jossa ei ollut tilaa väistyä oikealle eikä vasemmalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Kun aasintamma näki Herran Enkelin, se laskeutui maahan Bileamin alla. Silloin Bileamin viha syttyi, ja hän löi aasintammaa sauvalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Niin Herra avasi aasintamman suun, ja se sanoi Bileamille: \"Mitä minä olen sinulle tehnyt, koska lyöt minua jo kolmannen kerran?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Bileam vastasi aasintammalle: \"Sinä olet pitänyt minua pilkkanasi. Olisipa minulla miekka kädessäni, niin minä tappaisin sinut nyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Mutta aasintamma sanoi Bileamille: \"Enkö minä ole aasintammasi, jolla olet ratsastanut kaiken aikasi tähän päivään asti? Onko minulla ollut tapana tehdä näin sinulle?\" Hän vastasi: \"Ei.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Niin Herra avasi Bileamin silmät, niin että hän näki Herran Enkelin seisovan tiellä, paljastettu miekka kädessään. Silloin hän kumartui ja heittäytyi kasvoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Niin Herran Enkeli sanoi hänelle: \"Minkä tähden olet lyönyt aasintammaasi jo kolme kertaa? Katso, minä olen tullut sinua estämään, sillä ajattelemattomasti olet lähtenyt tälle matkalle vastoin minun tahtoani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Mutta aasintamma näki minut ja on väistynyt minun edestäni jo kolme kertaa. Jos se ei olisi väistynyt minun edestäni, niin minä olisin surmannut sinut, mutta jättänyt sen elämään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Niin Bileam vastasi Herran Enkelille: \"Minä olen tehnyt syntiä, sillä minä en tiennyt, että sinä olit asettunut minua vastaan tielle. Mutta jos tämä ei ole sinulle mieleen, niin minä nyt palaan takaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Mutta Herran Enkeli sanoi Bileamille: \"Mene näiden miesten kanssa, mutta puhu ainoastaan se, minkä minä sinulle puhun.\" Niin Bileam lähti Baalakin päämiesten kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Kun Baalak kuuli, että Bileam oli tulossa, hän meni häntä vastaan Iir-Mooabiin, joka on Arnonia pitkin kulkevalla rajalla, uloimmalla rajalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Baalak sanoi Bileamille: \"Enkö minä varta vasten lähettänyt kutsumaan sinua? Minkä tähden et tahtonut tulla luokseni? Enkö minä tosiaankaan voi sinua palkita?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Mutta Bileam vastasi Baalakille: \"Olenhan minä nyt tullut luoksesi. Mutta onko minun vallassani puhua mitään? Minkä Jumala panee minun suuhuni, sen minä puhun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Niin Bileam lähti Baalakin kanssa, ja he saapuivat Kirjat-Husotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Baalak teurasti nautoja ja lampaita ja lähetti ne Bileamille ja päämiehille, jotka olivat hänen luonaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Seuraavana aamuna Baalak otti Bileamin mukaansa ja vei hänet Baamot-Baalin kukkulalle, josta hän näki reunimmaisen osan tuota kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Bileam sanoi Baalakille: \"Rakenna minulle tähän seitsemän alttaria ja hanki minulle tänne seitsemän härkää ja seitsemän pässiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Baalak teki, niin kuin Bileam käski. Baalak ja Bileam uhrasivat härän ja pässin jokaisella alttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Bileam sanoi Baalakille: \"Asetu tähän polttouhrisi luo, minä menen tuonne, ehkä saan kohdata Herran. Minkä hän minulle näyttää, sen ilmoitan sinulle.\" Sitten hän meni eräälle autiolle kukkulalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Jumala tuli ja kohtasi Bileamin. Silloin tämä sanoi hänelle: \"Seitsemän alttaria minä olen pannut kuntoon ja olen uhrannut härän ja pässin jokaisella alttarilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Herra pani sanat Bileamin suuhun ja sanoi: \"Palaa Baalakin luo ja puhu hänelle näin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Hän palasi hänen luokseen, ja hän seisoi siinä polttouhrinsa luona, hän ja kaikki Mooabin päämiehet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Niin hän puhkesi lausumaan ja sanoi: \"Aramista nouti minut Baalak, idän vuorilta Mooabin kuningas: \'Tule, kiroa puolestani Jaakob, tule ja sadattele Israelia.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Kuinka minä kiroaisin sen, jota Jumala ei kiroa, kuinka sadattelisin sitä, jota Herra ei sadattele?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Näen sen kallioiden huipulta, katselen sitä kukkuloilta: katso, se on erillään asuva kansa, se ei lukeudu pakanakansojen joukkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Kuka mittaa Jaakobin hiekkajyväset, kuka Israelin tomuhiukkasten luvun? Suotakoon minun kuolla oikeamielisten kuolema, olkoon loppuni niin kuin heidän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Silloin Baalak sanoi Bileamille: \"Mitä oletkaan minulle tehnyt! Minä toin sinut tänne vihollisiani kiroamaan, vaan katso, sinä olet siunannut heidät!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Mutta hän vastasi ja sanoi: \"Eikö minun ole puhuttava tarkasti se, minkä Herra panee suuhuni?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Niin Baalak sanoi hänelle: \"Tule kanssani toiseen paikkaan, josta voit nähdä tuon kansan, kuitenkin ainoastaan sen äärimmäisen reunan, et sitä kokonaisuudessaan, ja kiroa se minun puolestani sieltä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Hän vei hänet Vartijakedolle Pisga-vuoren huipulle ja rakensi siihen seitsemän alttaria ja uhrasi härän ja pässin jokaisella alttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Sitten Bileam sanoi Baalakille: \"Asetu tähän polttouhrisi luo, ehkä hän kohtaa minut tuolla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Niin Herra tuli kohtaamaan Bileamia, pani sanat hänen suuhunsa ja sanoi: \"Palaa Baalakin luo ja puhu hänelle näin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Niin hän tuli hänen luokseen ja seisoi siinä polttouhrinsa luona Mooabin päämiehet kanssaan. Baalak kysyi häneltä: \"Mitä Herra puhui?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Niin hän puhkesi lausumaan ja sanoi: \"Nouse, Baalak, ja kuule! Kuuntele minua, sinä Sipporin poika!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Jumala ei ole ihminen, niin että hän valehtelisi, eikä ihmislapsi, että hän katuisi. Sanoisiko hän jotakin eikä tekisi sitä, puhuisiko jotakin eikä täyttäisi sitä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Katso, minä sain tehtäväkseni siunata: hän on siunannut, enkä minä voi sitä peruuttaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Ei havaita vaivaa Jaakobissa eikä nähdä onnettomuutta Israelissa. Herra, hänen Jumalansa, on hänen kanssaan, riemuhuuto kuninkaalle kaikuu siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Jumala vei sen pois Egyptistä. Sen sarvet ovat kuin re\'eem-eläimen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Sillä ei ole noituutta Jaakobissa eikä tavata taikuutta Israelissa. Aikanaan ilmoitetaan Jaakobille ja Israelille, mitä Jumala on tekevä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Katso, se on kansa, joka nousee kuin naarasleijona, joka kohoaa kuin leijona. Se ei paneudu levolle, ennen kuin on saalista syönyt ja juonut surmattujen verta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Mutta Baalak sanoi Bileamille: \"Sinä et kiroa kirotessasi etkä siunaa siunatessasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Mutta Bileam vastasi ja sanoi Baalakille: \"Enkö minä puhunut sinulle näin: \'Kaikki, mitä Herra sanoo, minun on tehtävä\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Niin Baalak sanoi Bileamille: \"Tule, minä vien sinut toiseen paikkaan. Ehkäpä Jumalan silmissä on otollista, että sieltä käsin kiroat kansan puolestani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Sitten Baalak vei Bileamin Peor-vuoren huipulle, joka kohoaa erämaan ylle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Sitten Bileam sanoi Baalakille: \"Rakenna minulle tähän seitsemän alttaria ja hanki minulle tänne seitsemän härkää ja seitsemän pässiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Baalak teki, niin kuin Bileam käski, ja uhrasi härän ja pässin kullakin alttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Kun Bileam näki, että Israelin siunaaminen oli Herralle otollista, hän ei enää mennyt kuten aina ennen ennusmerkkejä etsimään, vaan käänsi kasvonsa erämaahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Kun Bileam nosti silmänsä ja näki Israelin leiriytyneenä heimokunnittain, Jumalan Henki tuli häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Hän puhkesi lausumaan ja sanoi: \"Näin puhuu Bileam, Beorin poika, näin puhuu mies, jonka silmä on avattu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Näin puhuu se, joka kuulee Jumalan puheen, joka katselee Kaikkivaltiaan näkyjä, kun hän lankeaa maahan, hänen silmänsä avataan ilmoitukselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Kuinka ihanat ovat majasi, Jaakob, asuinpaikkasi, Israel!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Niin kuin laajat purolaaksot, kuin puutarhat virran varrella, kuin aloepuut, Herran istuttamat, kuin setripuut vesien varsilla!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Sen vesisangoista läikkyy vettä, ja sen laihot saavat runsaasti vettä. Agagia mahtavampi on sen kuningas, ylhäinen sen kuningasvalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Jumala vei sen pois Egyptistä. Sen sarvet ovat kuin re\'eem-eläimen. Se syö suuhunsa viholliskansat, heidän luunsa se murskaa ja lävistää heidät nuolillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Se on kyyristynyt, se on laskeutunut maahan kuin leijona, kuin naarasleijona – kuka sitä uskaltaa häiritä? Siunattu olkoon, joka sinua siunaa, kirottu, joka sinua kiroaa!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Silloin Baalak vihastui Bileamiin ja löi kätensä yhteen. Baalak sanoi Bileamille: \"Minä kutsuin sinut vihollisiani kiroamaan, ja nyt sinä olet siunannut heidät jo kolme kertaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Mene tiehesi! Minä aioin sinut runsaasti palkita, mutta katso, Herra on sinulta palkan kieltänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Bileam vastasi Baalakille: \"Enkö minä jo sanonut sanansaattajillesi, jotka lähetit luokseni:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, '\'Vaikka Baalak antaisi minulle talonsa täyden hopeaa ja kultaa, en sittenkään voisi rikkoa Herran käskyä, en tehdä mitään oman mieleni mukaan, en hyvää, en pahaa.\' Minkä Herra puhuu, sen minäkin puhun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Nyt minä lähden kansani luo, mutta sitä ennen minä ilmoitan sinulle, mitä tämä kansa on tekevä sinun kansallesi päivien lopulla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Hän puhkesi lausumaan ja sanoi: \"Näin puhuu Bileam, Beorin poika, näin puhuu mies, jonka silmä on avattu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Näin puhuu se, joka kuulee Jumalan puheen ja saa tiedon Korkeimmalta, joka näkee Kaikkivaltiaan näkyjä, joka saa [häneltä] ilmoituksia ja jonka silmät ovat avatut:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Minä näen hänet, en kuitenkaan nyt, minä katselen häntä, en kuitenkaan läheltä. Tähti nousee Jaakobista, ja valtikka kohoaa Israelista. Se ruhjoo Mooabilta ohimot, päälaen kaikilta Seetin pojilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Edomista tulee alusmaa, Seir joutuu vihollistensa omaksi, mutta Israel tekee väkeviä tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Jaakobista tulee valtias, hän hävittää kaupungeista niihin pelastuneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Kun hän näki Amalekin, hän puhkesi lausumaan ja sanoi: \"Kansakunnista ensimmäinen on Amalek, mutta sen loppu on perikato.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Kun hän näki keeniläiset, hän puhkesi lausumaan ja sanoi: \"Järkkymätön on asumuksesi, ja kalliolle on pesäsi pantu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Mutta sittenkin Kain hävitetään: ei aikaakaan, niin Assur vie sinut vangiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Hän puhkesi lausumaan ja sanoi: \"Voi! Kuka jää enää elämään, kun Jumala tämän tekee!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Laivoja saapuu kittiläisten suunnalta, ja ne kurittavat Assurin ja kurittavat Eeberin. Hänkin on perikadon oma.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Sen jälkeen Bileam nousi, lähti matkaan ja palasi kotiinsa, ja myös Baalak lähti tiehensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Israel asettui Sittimiin. Kansa rupesi irstailemaan Mooabin tyttärien kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Nämä kutsuivat kansaa jumaliensa uhreille, ja kansa söi ja kumarsi heidän jumaliaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Kun Israel näin antautui palvelemaan Baal-Peoria, Herran viha syttyi Israelia kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Herra sanoi Moosekselle: \"Ota kansan kaikki päämiehet ja lävistä heidät paaluihin Herralle, vasten aurinkoa, että Herran vihan hehku kääntyisi pois Israelista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Niin Mooses sanoi Israelin tuomareille: \"Surmatkoon jokainen miehistään ne, jotka ovat antautuneet palvelemaan Baal-Peoria.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Katso, muuan mies israelilaisista tuli ja toi veljiensä luo midianilaisen naisen Mooseksen ja kaiken israelilaisten seurakunnan nähden, kun nämä olivat itkemässä ilmestysmajan ovella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Kun Piinehas, pappi Aaronin pojan Eleasarin poika, näki sen, hän nousi kansan keskeltä ja otti keihään käteensä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'ja seurasi tuota Israelin miestä makuusuojaan ja lävisti heidät molemmat, Israelin miehen ja sen naisen, vatsan kohdalta. Silloin taukosi israelilaisilta vitsaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Niitä, jotka kuolivat tässä vitsauksessa, oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, '\"Piinehas, pappi Aaronin pojan Eleasarin poika, on kääntänyt vihani pois israelilaisista, kun hän on kiivaillut puolestani heidän keskuudessaan, ettei minun ole tarvinnut kiivaudessani tehdä loppua israelilaisista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Sano siis: Katso, minä teen hänen kanssaan liiton hänen menestymisekseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'Se tulee hänelle ja hänen jälkeläisilleen ikuiseksi pappeuden liitoksi, koska hän kiivaili Jumalansa puolesta ja toimitti sovituksen israelilaisille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Surmatun Israelin miehen nimi, sen, joka surmattiin midianilaisen naisen kanssa, oli Simri, simeonilaisen perhekunnan päämiehen Saalun poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Surmatun midianilaisen naisen nimi oli Kosbi, Suurin, midianilaisen perhekunnan heimopäällikön, tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, '\"Ahdistakaa midianilaisia ja tuhotkaa heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Sillä he ahdistivat teitä viekkailla juonillaan, joilla he houkuttelivat teidät Peorin ja sisarensa Kosbin, midianilaisen päämiehen tyttären, ansaan, hänen, joka surmattiin Peorin vuoksi tapahtuneen vitsauksen päivänä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 19, '');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Tämän vitsauksen jälkeen Herra puhui Moosekselle ja Eleasarille, pappi Aaronin pojalle, sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, '\"Laskekaa koko israelilaisten seurakunnan väkiluku, kaksikymmentävuotiaat ja sitä vanhemmat, perhekunnittain, kaikki Israelin sotakelpoiset miehet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Mooses ja pappi Eleasar puhuivat heille Mooabin arolla Jordanin luona Jerikon kohdalla sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, '\"Kaksikymmentävuotiaat ja sitä vanhemmat laskettakoot\", kuten Herra oli Moosesta käskenyt. Israelilaiset, jotka olivat lähteneet Egyptin maasta, olivat:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruuben, Israelin esikoinen. Ruubenin jälkeläisiä olivat: Hanokista hanokilaisten suku, Pallusta pallulaisten suku,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'Hesronista hesronilaisten suku, Karmista karmilaisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Nämä olivat ruubenilaisten suvut. Katselmuksessa olleita heitä oli neljäkymmentäkolme tuhatta seitsemänsataa kolmekymmentä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Pallun poika oli Eliab.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Eliabin pojat olivat Nemuel ja Daatan ja Abiram. Nämä olivat ne kansan edusmiehet Daatan ja Abiram, jotka taistelivat Moosesta ja Aaronia vastaan Koorahin joukossa ja taistelivat Herraa vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'jolloin maa avasi kitansa ja nielaisi heidät ja Koorahin, silloin kun hänen joukkonsa kuoli ja tuli kulutti kaksisataa viisikymmentä miestä, ja heistä tuli varoitusmerkki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Mutta Koorahin pojat eivät kuolleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Simeonin jälkeläisiä sukujensa mukaan olivat: Nemuelista nemuelilaisten suku, Jaaminista jaaminilaisten suku, Jaakinista jaakinilaisten suku,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'Serahista serahilaisten suku, Saulista saulilaisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Nämä olivat simeonilaisten suvut, kaksikymmentäkaksi tuhatta kaksisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Gaadin jälkeläisiä, sukujensa mukaan, olivat: Sefonista sefonilaisten suku, Haggista haggilaisten suku, Suunista suunilaisten suku,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'Osnista osnilaisten suku, Eeristä eeriläisten suku,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'Arodista arodilaisten suku, Arelista arelilaisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Nämä olivat Gaadin jälkeläisten suvut. Katselmuksessa olleita oli heitä neljäkymmentä tuhatta viisisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Juudan poikia olivat Eer ja Oonan, mutta Eer ja Oonan kuolivat Kanaanin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Juudan jälkeläisiä sukujensa mukaan olivat: Seelasta seelalaisten suku, Pereksestä perekseläisten suku, Serahista serahilaisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Pereksen jälkeläisiä olivat: Hesronista hesronilaisten suku, Haamulista haamulilaisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Nämä olivat Juudan suvut. Katselmuksessa olleita heitä oli seitsemänkymmentäkuusi tuhatta viisisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Isaskarin jälkeläisiä sukujensa mukaan olivat: Toolasta toolalaisten suku, Puvvasta puunilaisten suku,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'Jaasubista jaasubilaisten suku, Simronista simronilaisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Nämä olivat Isaskarin suvut. Katselmuksessa olleita heitä oli kuusikymmentäneljätuhatta kolmesataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Sebulonin jälkeläisiä sukujensa mukaan olivat: Seredistä serediläisten suku, Eelonista eelonilaisten suku, Jahlelista jahlelilaisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Nämä olivat sebulonilaisten suvut. Katselmuksessa olleita heitä oli kuusikymmentä tuhatta viisisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Joosefin jälkeläisiä sukujensa mukaan olivat Manasse ja Efraim.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Manassen jälkeläisiä olivat: Maakirista maakirilaisten suku. Maakirille syntyi Gilead. Gileadista on gileadilaisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Nämä olivat Gileadin jälkeläisiä. Iieseristä iieseriläisten suku, Helekistä helekiläisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'Asrielista asrielilaisten suku, Sekemistä sekemiläisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'Semidasta semidalaisten suku, Heeferistä heeferiläisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Mutta Selofhadilla, Heeferin pojalla, ei ollut poikia, vaan ainoastaan tyttäriä. Selofhadin tyttärien nimet olivat: Mahla, Nooga, Hogla, Milka ja Tirsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Nämä olivat Manassen suvut. Katselmuksessa olleita heitä oli viisikymmentäkaksi tuhatta seitsemänsataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Nämä olivat Efraimin jälkeläisiä, sukujensa mukaan: Suutelahista suutelahilaisten suku, Bekeristä bekeriläisten suku, Tahanista tahanilaisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Nämä olivat Suutelahin jälkeläisiä: Eeranista eeranilaisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Nämä olivat efraimilaisten suvut. Katselmuksessa olleita heitä oli kolmekymmentäkaksi tuhatta viisisataa. Nämä olivat Joosefin jälkeläiset sukujensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Benjaminin jälkeläisiä, sukujensa mukaan, olivat: Belasta belalaisten suku, Asbelista asbelilaisten suku, Ahiramista ahiramilaisten suku,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'Sefufamista suufamilaisten suku, Huufamista huufamilaisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Mutta Belan jälkeläisiä olivat Ard ja Naaman: Ardista ardilaisten suku, Naamanista naamilaisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Nämä olivat Benjaminin jälkeläiset sukujensa mukaan. Katselmuksessa olleita heitä oli neljäkymmentäviisi tuhatta kuusisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Nämä olivat Daanin jälkeläisiä, sukujensa mukaan: Suuhamista suuhamilaisten suku. Nämä ovat Daanin suvut sukujensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Kaikista suuhamilaisten suvuista oli katselmuksessa olleita kuusikymmentäneljätuhatta neljäsataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Asserin jälkeläisiä, sukujensa mukaan, olivat: Jimnasta jimnalaisten suku, Jisvistä jisviläisten suku, Beriasta berialaisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Berian jälkeläisiä olivat: Heeberistä heeberiläisten suku, Malkielista malkielilaisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Asserin tyttären nimi oli Serah.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Nämä olivat asserilaisten suvut. Katselmuksessa olleita heitä oli viisikymmentäkolme tuhatta neljäsataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Naftalin jälkeläisiä, sukujensa mukaan, olivat: Jahselista jahselilaisten suku, Guunista guunilaisten suku,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'Jeeseristä jeeseriläisten suku, Sillemistä sillemiläisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Nämä olivat Naftalin suvut sukujensa mukaan. Katselmuksessa olleita heitä oli neljäkymmentäviisi tuhatta neljäsataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Nämä olivat katselmuksessa olleet israelilaiset: kuusisataayksi tuhatta seitsemänsataa kolmekymmentä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, '\"Näille jaettakoon maa perintöosiksi nimien lukumäärän mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Isommalle suvulle anna isompi perintöosa ja pienemmälle pienempi perintöosa. Kullekin annettakoon perintöosa katselmuksessa olleiden määrän mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Maa jaettakoon arvalla. Isiensä heimojen nimien mukaan he saakoot perintöosansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Arvan määräyksen mukaan jaettakoon perintöosat suurilukuisten ja vähälukuisten heimojen kesken.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Nämä olivat Leevin katselmuksessa olleet sukujensa mukaan: Geersonista geersonilaisten suku, Kehatista kehatilaisten suku, Merarista merarilaisten suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Nämä olivat leeviläisten suvut: libniläisten suku, hebronilaisten suku, mahlilaisten suku, muusilaisten suku, koorahilaisten suku. Kehatille oli syntynyt Amram.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Amramin vaimon nimi oli Jookebed, Leevin tytär, joka oli Leeville syntynyt Egyptissä. Hän synnytti Amramille Aaronin ja Mooseksen sekä heidän sisarensa Mirjamin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Aaronille syntyi Naadab ja Abihu, Eleasar ja Iitamar.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Mutta Naadab ja Abihu kuolivat, kun toivat vierasta tulta Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Katselmuksessa olleita heitä oli kaksikymmentäkolme tuhatta, kaikki miespuolisia, kuukauden vanhoja ja sitä vanhempia. Sillä heistä ei pidetty katselmusta yhdessä muiden israelilaisten kanssa, koska heille ei annettu perintöosaa israelilaisten keskuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Nämä olivat siinä israelilaisten katselmuksessa, jonka Mooses ja pappi Eleasar pitivät Mooabin arolla lähellä Jordania, Jerikon kohdalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Heidän joukossaan ei ollut ketään siinä israelilaisten katselmuksessa ollutta, jonka Mooses ja pappi Aaron olivat pitäneet Siinain erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Sillä Herra oli heille sanonut, että heidän oli kuoltava erämaassa. Eikä heistä jäänyt ketään, paitsi Kaaleb, Jefunnen poika, ja Joosua, Nuunin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Niin astuivat esiin Selofhadin tyttäret – Selofhadin, Heeferin pojan, Gileadin pojan, Maakirin pojan, Manassen pojan, tyttäret – jotka olivat Manassen, Joosefin pojan, suvuista ja joiden nimet olivat Mahla, Nooga, Hogla, Milka ja Tirsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'He asettuivat Mooseksen ja pappi Eleasarin ja päämiesten ja kaiken kansan eteen ilmestysmajan ovelle ja sanoivat:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, '\"Meidän isämme kuoli erämaassa, mutta hän ei ollut siinä joukossa, joka kävi kapinoimaan Herraa vastaan, Koorahin joukossa, vaan hän kuoli oman syntinsä tähden, eikä hänellä ollut poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Miksi häviäisi nyt isämme nimi hänen sukunsa keskuudesta sen tähden, ettei hänellä ollut poikaa? Anna meille perintöosuus isämme veljien keskuudessa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Mooses saattoi heidän asiansa Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, '\"Selofhadin tyttäret puhuvat oikein. Anna heille perintöosuus heidän isänsä veljien keskuudessa ja siirrä heidän isänsä perintöosa heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Puhu israelilaisille sanoen: jos joku kuolee ilman poikaa, siirtäkää hänen perintöosansa hänen tyttärelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Mutta jos hänellä ei ole tytärtä, antakaa hänen perintöosansa hänen veljilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Mutta jos hänellä ei ole veljiä, antakaa hänen perintöosansa hänen isänsä veljille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Mutta jos hänen isällään ei ole veljiä, antakaa hänen perintöosansa sille hänen veriheimolaiselleen, joka hänen suvussaan on häntä lähin. Tämä ottakoon sen haltuunsa. Tämä olkoon oikeussäädöksenä israelilaisilla, niin kuin Herra on Moosesta käskenyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Herra sanoi Moosekselle: \"Nouse tälle Abarimin vuorelle ja katsele sitä maata, jonka minä annan israelilaisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Kun olet sitä katsellut, sinutkin otetaan pois heimosi luo, niin kuin veljesi Aaron otettiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'sen tähden että te Siinin erämaassa, kansan riidellessä, niskoittelitte minun käskyjäni vastaan ettekä pyhittäneet minua vedellä. Se oli Meriban vesi Kaadeksessa Siinin erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Mooses puhui Herralle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, '\"Asettakoon Herra, Jumala, jonka vallassa on kaiken lihan henki, tämän seurakunnan johtoon miehen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'joka lähtee heidän edellään ja joka tulee heidän edellään, joka saattaa heidät lähtemään ja tulemaan, ettei Herran seurakunta olisi kuin lammaslauma, jolla ei ole paimenta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Herra sanoi Moosekselle: \"Ota Joosua, Nuunin poika, mies, jossa on Henki, ja pane kätesi hänen päälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'Aseta hänet pappi Eleasarin ja kaiken kansan eteen ja aseta hänet virkaan heidän nähtensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'Anna hänelle arvovaltasi, että kaikki israelilaisten seurakunta tottelisi häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Hän astukoon pappi Eleasarin eteen, ja tämä kysyköön hänen puolestaan uurimin kautta Jumalan vastausta Herran edessä. Hänen käskystään he lähtekööt ja hänen käskystään he tulkoot, hän ja kaikki israelilaiset hänen kanssaan, koko seurakunta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Mooses teki, niin kuin Herra oli häntä käskenyt, ja otti Joosuan ja asetti hänet pappi Eleasarin ja kaiken seurakunnan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'Hän pani kätensä hänen päälleen ja asetti hänet virkaan, niin kuin Herra oli puhunut Mooseksen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, '\"Käske israelilaisia ja sano heille: tuokaa minulle määräaikana ruokauhrini ja polttouhrini, suloisesti tuoksuvat uhrini.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Sano heille: Tämä on se uhri, joka teidän on tuotava joka päivä Herralle: kaksi vuoden vanhaa virheetöntä karitsaa jokapäiväiseksi polttouhriksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Uhraa toinen karitsa aamulla, ja toinen karitsa uhraa iltahämärässä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'ja ruokauhriksi kymmenesosa eefa-mittaa ydinjauhoja sekoitettuna neljännekseen hiin-mittaa survomalla saatua öljyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Tämä on jokapäiväinen polttouhri, joka toimitettiin Siinain vuorella suloisesti tuoksuvana uhrina Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Siihen kuulukoon juomauhrina neljännes hiin-mittaa viiniä kumpaakin karitsaa kohti. Pyhäkössä vuodata Herralle höysteviiniuhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Toinen karitsa uhraa iltahämärässä ja toimita siihen kuuluva ruoka- ja juomauhri samalla tavoin kuin aamullakin suloisesti tuoksuvana uhrina Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Mutta sapatinpäivänä uhraa kaksi vuoden vanhaa virheetöntä karitsaa sekä kaksi kymmenesosaa ydinjauhoja öljyyn sekoitettuna ruokauhrina sekä siihen kuuluva juomauhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Tämä on sapattipolttouhri, joka uhrattakoon kunakin sapattina jokapäiväisen polttouhrin ja siihen kuuluvan juomauhrin lisäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Kuukausienne ensimmäisenä päivänä tuokaa polttouhriksi Herralle kaksi mullia, pässi ja seitsemän virheetöntä vuoden vanhaa karitsaa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'sekä kolme kymmenesosaa ydinjauhoja öljyyn sekoitettuna ruokauhrina kutakin mullia kohti sekä kaksi kymmenesosaa ydinjauhoja öljyyn sekoitettuna ruokauhrina pässiä kohti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'sekä yksi kymmenesosa ydinjauhoja öljyyn sekoitettuna, ruokauhriksi kutakin karitsaa kohti. Tämä on polttouhri, suloisesti tuoksuva uhri Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Niihin kuulukoon juomauhrina puoli hiin-mittaa viiniä kutakin mullia kohti ja kolmannes hiin-mittaa pässiä kohti ja neljännes hiin-mittaa karitsaa kohti. Tämä on uudenkuun polttouhri, joka uhrattakoon kunakin uutenakuuna vuoden kaikkina kuukausina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Sen lisäksi uhratkaa yksi vuohipukki syntiuhrina Herralle. Se uhrattakoon jokapäiväisen polttouhrin sekä siihen kuuluvan juomauhrin ohella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Ensimmäisessä kuussa kuukauden neljäntenätoista päivänä on pääsiäinen Herran kunniaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Saman kuukauden viidentenätoista päivänä on juhla. Seitsemän päivää syötäköön happamatonta leipää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Ensimmäisenä päivänä on pyhä kokous. Älkää silloin toimittako yhtään arkiaskaretta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Tuokaa polttouhriksi Herralle kaksi mullia, pässi ja seitsemän vuoden vanhaa karitsaa. Ne olkoot virheettömiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'Niihin kuuluvana ruokauhrina uhratkaa ydinjauhoja öljyyn sekoitettuna kolme kymmenesosaa mullia kohti ja kaksi kymmenesosaa pässiä kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'Kutakin kohti niistä seitsemästä karitsasta uhratkaa kymmenesosa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'Uhratkaa vielä vuohipukki syntiuhriksi, joka tuottaa teille sovituksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Aamupolttouhrin lisäksi, joka on jokapäiväinen polttouhri, uhratkaa nämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Samoin uhratkaa Herralle joka päivä seitsemän päivän aikana leipää suloisesti tuoksuvaksi uhriksi. Uhratkaa tämä jokapäiväisen polttouhrin sekä siihen kuuluvan juomauhrin ohella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Seitsemäntenä päivänä olkoon teillä pyhä kokous. Älkää silloin toimittako mitään arkiaskaretta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Mutta ensi sadon päivänä, kun tuotte uuden ruokauhrin Herralle viikkojuhlananne, olkoon teillä pyhä kokous. Älkää silloin toimittako mitään arkiaskaretta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Tuokaa suloisesti tuoksuvana polttouhrina Herralle kaksi mullia, pässi ja seitsemän vuoden vanhaa karitsaa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'ja niihin kuuluvana ruokauhrina ydinjauhoja öljyyn sekoitettuna kolme kymmenesosaa kutakin mullia kohti, kaksi kymmenesosaa pässiä kohti');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'ja yksi kymmenesosa kutakin kohti niistä seitsemästä karitsasta, sekä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'yksi vuohipukki itsenne sovittamiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Paitsi jokapäiväistä polttouhria ja siihen kuuluvaa ruokauhria uhratkaa nämä sekä niihin kuuluvat juomauhrit. Eläimet olkoot virheettömiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, '\"Seitsemännessä kuussa kuukauden ensimmäisenä päivänä olkoon teillä pyhä kokous. Älkää silloin toimittako mitään arkiaskaretta. Olkoon se teille torvensoiton päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Uhratkaa suloisesti tuoksuvana polttouhrina Herralle mulli, pässi ja seitsemän vuoden vanhaa virheetöntä karitsaa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'ja niihin kuuluvana ruokauhrina ydinjauhoja öljyyn sekoitettuna kolme kymmenesosaa mullia kohti, kaksi kymmenesosaa pässiä kohti');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'ja yksi kymmenesosa kutakin kohti niistä seitsemästä karitsasta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'sekä vuohipukki syntiuhriksi teidän sovittamiseksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'Paitsi uudenkuun polttouhria sekä siihen kuuluvaa ruokauhria ja jokapäiväistä polttouhria sekä siihen kuuluvaa ruokauhria ja niihin kuuluvia juomauhreja, niin kuin niistä on säädetty, uhratkaa kaikki tämä suloisena tuoksuvana uhrina Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Saman seitsemännen kuun kymmenentenä päivänä olkoon teillä pyhä kokous. Kurittakaa itseänne silloin paastolla älkääkä toimittako mitään askaretta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Tuokaa suloisesti tuoksuvana polttouhrina Herralle mulli, pässi ja seitsemän vuoden vanhaa karitsaa. Ne olkoot virheettömiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'Niihin kuulukoon ruokauhrina ydinjauhoja, öljyyn sekoitettuna kolme kymmenesosaa mullia kohti, kaksi kymmenesosaa pässiä kohti');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'ja yksi kymmenesosa kutakin kohti niistä seitsemästä karitsasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'ja vuohipukki syntiuhriksi, paitsi sovitusuhria ja jokapäiväistä polttouhria sekä niihin kuuluvia ruoka- ja juomauhreja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Seitsemännen kuukauden viidentenätoista päivänä olkoon teillä pyhä kokous. Älkää toimittako silloin mitään arkiaskaretta, vaan viettäkää juhlaa Herran kunniaksi seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Tuokaa polttouhrina, suloisesti tuoksuvana uhrina Herralle, kolmetoista mullia, kaksi pässiä ja neljätoista vuoden vanhaa karitsaa. Ne olkoot virheettömiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'Niihin kuulukoon ruokauhrina ydinjauhoja öljyyn sekoitettuna kolme kymmenesosaa kutakin kohti niistä kolmestatoista mullista, kaksi kymmenesosaa kumpaakin kohti niistä kahdesta pässistä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'ja yksi kymmenesosa kutakin kohti niistä neljästätoista karitsasta sekä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'vuohipukki syntiuhrina jokapäiväisen polttouhrin sekä siihen kuuluvan ruoka- ja juomauhrin lisäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Uhratkaa toisena päivänä: kaksitoista mullia, kaksi pässiä ja neljätoista vuoden vanhaa virheetöntä karitsaa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'ja niihin kuuluvat ruoka- ja juomauhrit mullien, pässien ja karitsojen luvun mukaan, kuten on säädetty,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'sekä vuohipukki syntiuhrina, lisäksi jokapäiväinen polttouhri sekä siihen kuuluva ruoka- ja juomauhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Kolmantena päivänä: yksitoista mullia, kaksi pässiä ja neljätoista vuoden vanhaa virheetöntä karitsaa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'ja niihin kuuluvat ruoka- ja juomauhrit mullien, pässien ja karitsojen luvun mukaan, kuten on säädetty,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'sekä vuohipukki syntiuhriksi, lisäksi jokapäiväinen polttouhri sekä siihen kuuluva ruoka- ja juomauhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Neljäntenä päivänä: kymmenen mullia, kaksi pässiä ja neljätoista vuoden vanhaa virheetöntä karitsaa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'ja niihin kuuluvat ruoka- ja juomauhrit mullien, pässien ja karitsojen luvun mukaan, kuten on säädetty,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'sekä vuohipukki syntiuhrina, paitsi jokapäiväistä polttouhria sekä siihen kuuluvaa ruoka- ja juomauhria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Viidentenä päivänä uhratkaa yhdeksän mullia, kaksi pässiä ja neljätoista vuoden vanhaa virheetöntä karitsaa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'ja niihin kuuluvat ruoka- ja juomauhrit mullien, pässien ja karitsojen luvun mukaan, kuten on säädetty,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'sekä vuohipukki syntiuhrina, paitsi jokapäiväistä polttouhria sekä siihen kuuluvaa ruoka- ja juomauhria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Kuudentena päivänä: kahdeksan mullia, kaksi pässiä ja neljätoista vuoden vanhaa virheetöntä karitsaa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'ja niihin kuuluvat ruoka- ja juomauhrit mullien, pässien ja karitsojen luvun mukaan, kuten on säädetty,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'sekä vuohipukki syntiuhrina, paitsi jokapäiväistä polttouhria sekä siihen kuuluvaa ruoka- ja juomauhria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Seitsemäntenä päivänä uhratkaa: seitsemän mullia, kaksi pässiä ja neljätoista vuoden vanhaa virheetöntä karitsaa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'ja niihin kuuluvat ruoka- ja juomauhrit mullien, pässien ja karitsojen luvun mukaan, kuten on säädetty,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'sekä vuohipukki syntiuhrina, paitsi jokapäiväistä polttouhria sekä siihen kuuluvaa ruoka- ja juomauhria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Kahdeksantena päivänä olkoon teillä juhlakokous. Älkää silloin toimittako mitään arkiaskaretta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'vaan tuokaa suloisesti tuoksuvana polttouhrina Herralle mulli, pässi ja seitsemän vuoden vanhaa virheetöntä karitsaa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'ja niihin kuuluvat ruoka- ja juomauhrit mullin, pässin ja karitsojen luvun mukaan, kuten on säädetty,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'sekä vuohipukki syntiuhrina, paitsi jokapäiväistä polttouhria sekä siihen kuuluvaa ruoka- ja juomauhria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Nämä uhratkaa Herralle juhla-aikoinanne, paitsi mitä lupausuhreinanne ja vapaaehtoisina lahjoinanne tuotte polttouhreiksi, ruokauhreiksi, juomauhreiksi ja rauhanuhreiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Mooses puhui israelilaisille kaiken, mitä Herra oli Mooseksen käskenyt puhua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Mooses puhui Israelin sukukuntien päämiehille sanoen: \"Näin on Herra käskenyt:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Jos mies tekee lupauksen Herralle tai valalla vannoen sitoutuu kieltäytymään jostakin, älköön rikkoko sanaansa, vaan tehköön kaiken, mitä hänen suunsa on sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Jos nainen ollessaan nuorena tyttönä isänsä kodissa tekee lupauksen Herralle tai sitoutuu kieltäytymään jostakin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'ja hänen isänsä kuulee hänen lupauksensa tai sitoumuksensa eikä hänen isänsä hänelle siitä mitään puhu, niin kaikki hänen lupauksensa ja kaikki hänen sitoumuksensa, joilla hän kieltäytyy jostakin, olkoot päteviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Mutta jos hänen isänsä kieltää häntä sinä päivänä, jona hän ne kuulee, niin hänen lupauksensa ja sitoumuksensa, joilla hän kieltäytyy jostakin, älkööt olko päteviä, olivatpa ne mitkä hyvänsä, ja Herra antaa hänelle anteeksi, sen tähden että hänen isänsä on häntä kieltänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Jos hän joutuu miehelle ja hänellä on täytettävänä lupauksia tai ajattelemattomasti lausuttu sana, jolla hän on kieltäytynyt jostakin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'ja hänen miehensä saa sen kuulla, mutta ei puhu hänelle siitä mitään sinä päivänä, jona hän sen kuulee, niin hänen lupauksensa ja hänen sitoumuksensa, joilla hän on kieltäytynyt jostakin, olkoot päteviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Mutta jos hänen miehensä sinä päivänä, jona hän sen kuulee, kieltää häntä, niin hän purkaa hänen lupauksensa, jonka täyttämiseen hän on sitoutunut, ja sen ajattelemattomasti lausutun sanan, jolla hän on kieltäytynyt jostakin, ja Herra antaa hänelle anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Mutta lesken tai hylätyn vaimon lupaus, mihin hyvänsä hän onkin sitoutunut, olkoon pätevä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Jos vaimo on miehensä kodissa tehnyt lupauksen tai valalla sitoutunut kieltäytymään jostakin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'ja hänen miehensä saa sen kuulla, mutta ei puhu hänelle siitä mitään eikä kiellä häntä, niin kaikki hänen lupauksensa ja kaikki sitoumukset, joilla hän on kieltäytynyt jostakin, olkoot päteviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Mutta jos hänen miehensä purkaa ne sinä päivänä, jona hän niistä kuulee, älköön yksikään hänen huuliltaan lähtenyt lupaus tai sitoumus olko pätevä. Hänen miehensä on ne purkanut, ja Herra antaa hänelle anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Jokaisen lupauksen ja jokaisen valallisen sitoumuksen, jonka vaimo itsensä kurittamiseksi tekee, saakoon hänen miehensä joko vahvistaa tai purkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Mutta jos hänen miehensä ei puhu hänelle niistä mitään sen päivän kuluessa, niin hän on vahvistanut kaikki hänen lupauksensa ja kaikki hänen sitoumuksensa, jotka hänellä on täytettävinä. Hän on ne vahvistanut, koska hän ei niistä hänelle mitään puhunut sinä päivänä, jona hän niistä kuuli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Mutta jos hän ne purkaa vasta jonkin aikaa sen jälkeen, kun on niistä kuullut, hän joutuu kantamaan vaimonsa syyllisyyden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 17, 'Nämä ovat ne säädökset, jotka Herra antoi Moosekselle, olemaan voimassa miehen ja hänen vaimonsa välillä sekä isän ja hänen tyttärensä välillä, tämän ollessa nuorena tyttönä isänsä kodissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, '\"Kosta israelilaisten puolesta midianilaisille. Sen jälkeen sinut otetaan pois heimosi luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Niin Mooses puhui kansalle sanoen: \"Varustakaa joukostanne miehiä sotaan. He lähtekööt Midiania vastaan toimittamaan Herran koston Midianille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Lähettäkää sotaan tuhat miestä jokaisesta sukukunnasta kaikista Israelin sukukunnista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Silloin annettiin Israelin heimoista tuhat miestä jokaisesta sukukunnasta, yhteensä kaksitoista tuhatta sotaan varustettua miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Mooses lähetti heidät, tuhat miestä jokaisesta sukukunnasta, sotaan sekä heidän kanssaan Piinehaan, pappi Eleasarin pojan. Tällä oli mukanaan pyhät esineet ja hälytystorvet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Niin he lähtivät sotimaan Midiania vastaan, niin kuin Herra oli Moosesta käskenyt, ja surmasivat kaikki miespuoliset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Muiden mukana, jotka kaatuivat, he surmasivat Midianin kuninkaat Evin, Rekemin, Suurin, Huurin ja Reban, Midianin viisi kuningasta. Myös Bileamin, Beorin pojan, he surmasivat miekalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Mutta israelilaiset ottivat vangiksi midianilaisten vaimot ja lapset ja ryöstivät kaikki heidän juhtansa ja koko heidän karjansa ja kaikki heidän tavaransa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'He polttivat tulella kaikki heidän asumansa kaupungit ja kaikki heidän leiripaikkansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'He ottivat kaiken ryöstettävän ja kaiken otettavan, sekä ihmiset että karjan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'He toivat Moosekselle ja pappi Eleasarille sekä Israelin kansalle vangit ja ottamansa ja ryöstämänsä saaliin leiriin Mooabin arolle, joka on Jordanin luona, Jerikon kohdalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Silloin Mooses ja pappi Eleasar ja kaikki kansan päämiehet lähtivät heitä vastaan leirin ulkopuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Mooses vihastui sotajoukon johtajiin, tuhannen- ja sadanpäämiehiin, kun he palasivat sotaretkeltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Mooses sanoi heille: \"Oletteko siis jättäneet henkiin kaikki naiset?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Katso, nehän ne olivat, jotka Bileamin neuvosta saivat israelilaiset antautumaan uskottomuuteen Herraa vastaan Peorin vuoksi, niin että vitsaus kohtasi Herran seurakuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Niin surmatkaa siis kaikki poikalapset ja surmatkaa myös jokainen vaimo, joka on yhtynyt mieheen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Mutta jokainen tyttö naisista, joka ei ole yhtynyt mieheen, jättäkää itsellenne henkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Mutta itse oleskelkaa leirin ulkopuolella seitsemän päivää. Jokainen teistä, joka on jonkun surmannut, ja jokainen teistä, joka on koskenut surmattuun, puhdistautukoon kolmantena ja seitsemäntenä päivänä, sekä te että teidän vankinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Puhdistettakoon jokainen vaate ja jokainen nahkaesine ja kaikki, mikä on tehty vuohen karvoista, ja jokainen puuesine.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Silloin pappi Eleasar sanoi sotamiehille, jotka olivat menneet sotaan: \"Tämä on lakisäädös, jonka Herra antoi Moosekselle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Vain kulta, hopea, vaski, rauta, tina ja lyijy,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'kaikki, mikä tulta kestää, käyttäkää tulessa, niin se puhdistuu, Puhdistettakoon se kuitenkin vielä puhdistusvedellä. Mutta se, mikä ei tulta kestä, käyttäkää vedessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Peskää vaatteenne seitsemäntenä päivänä, niin te puhdistutte, ja tulkaa sitten leiriin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, '\"Laskekaa, sinä ja pappi Eleasar ja kansan perhekuntien päämiehet, otetun saaliin määrä, ihmiset ja karja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'Jaa saalis kahtia soturien, sotaan lähteneiden, ja kaiken muun kansan kesken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Ota Herralle verona sotamiehiltä, sotaan lähteneiltä, yksi viidestäsadasta, ihmisiä, nautoja, aaseja ja lampaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Ota se heille tulevasta puoliskosta ja anna se pappi Eleasarille antina Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Israelilaisille tulevasta puoliskosta ota yksi viidestäkymmenestä, ihmisiä, nautoja, aaseja, lampaita ja kaikkia karjaeläimiä, ja anna ne leeviläisille, joiden on hoidettava tehtävät Herran asumuksessa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Mooses ja pappi Eleasar tekivät, niin kuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Saalis, jäännös siitä, mitä sotajoukko oli ryöstänyt, oli: lampaita kuusisataa seitsemänkymmentäviisi tuhatta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'nautoja seitsemänkymmentäkaksi tuhatta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'aaseja kuusikymmentäyksi tuhatta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'ja ihmisiä, naisia, jotka eivät olleet yhtyneet mieheen, kaikkiaan kolmekymmentäkaksi tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Puolet siitä eli se osa, joka tuli sotaan lähteneille, oli: lampaita kolmesataa kolmekymmentäseitsemän tuhatta viisisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'Herralle tuleva vero lampaista oli kuusisataa seitsemänkymmentä viisi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'ja nautoja kolmekymmentäkuusi tuhatta sekä niistä Herralle tuleva vero seitsemänkymmentä kaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'Aaseja oli kolmekymmentä tuhatta viisisataa sekä niistä Herralle tuleva vero kuusikymmentä yksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'Ihmisiä oli kuusitoista tuhatta sekä niistä Herralle tuleva vero kolmekymmentä kaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Mooses antoi veron Herralle tulevista anneista pappi Eleasarille, niin kuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Israelilaisille tuleva puolisko, jonka Mooses oli erottanut sotamiesten osasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, 'tämä seurakunnalle tuleva puolisko oli: lampaita kolmesataa kolmekymmentäseitsemän tuhatta viisisataa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'ja nautoja kolmekymmentäkuusi tuhatta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'ja aaseja kolmekymmentä tuhatta viisisataa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'sekä ihmisiä kuusitoista tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Tästä israelilaisille tulevasta puoliskosta Mooses otti yhden viidestäkymmenestä, ihmisiä ja karjaa, sekä antoi ne leeviläisille, joiden oli hoidettava tehtävät Herran asumuksessa, niin kuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Silloin tulivat sotajoukon osastojen johtajat, tuhannen- ja sadanpäämiehet, Mooseksen luo');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'ja sanoivat Moosekselle: \"Palvelijasi ovat laskeneet niiden sotamiesten luvun, jotka ovat olleet hallussamme, eikä meistä puutu yhtään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Sen tähden me tuomme nyt Herralle lahjaksi, mitä kukin on saanut kultaesineitä: käätyjä, rannerenkaita, sormuksia, korvarenkaita ja kaulakoristeita, saadaksemme itsellemme sovituksen Herran edessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Niin Mooses ja pappi Eleasar ottivat heiltä kullan, kaikkinaiset taidokkaasti valmistetut esineet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Anniksi annettua kultaa, jonka he antoivat Herralle tuhannen- ja sadanpäämiesten puolesta, oli kaikkiaan kuusitoista tuhatta seitsemänsataa viisikymmentä sekeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Sotamiehet olivat ottaneet saalista kukin itselleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Mooses ja pappi Eleasar ottivat kullan tuhannen- ja sadanpäämiehiltä ja veivät sen ilmestysmajaan, että se johdattaisi israelilaiset Herran muistoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Mutta ruubenilaisilla ja gaadilaisilla oli paljon karjaa, hyvin runsaasti. Kun he nyt katselivat Jaeserin maata ja Gileadin maata, he huomasivat, että seutu oli karjanhoitoon sopiva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Niin gaadilaiset ja ruubenilaiset tulivat ja puhuivat Moosekselle ja pappi Eleasarille ja seurakunnan päämiehille sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, '\"Atarot, Diibon, Jaeser, Nimra, Hesbon, Elale, Sebam, Nebo ja Beon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'tämä maa, jonka Herra on vallannut Israelin seurakunnalle, on karjanhoitoon sopivaa maata, ja sinun palvelijoillasi on karjaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'He sanoivat vielä: \"Jos olemme saaneet armon silmiesi edessä, niin annettakoon tämä maa palvelijoillesi omaksi, äläkä vie meitä Jordanin yli.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Mutta Mooses vastasi gaadilaisille ja ruubenilaisille: \"Onko teidän veljienne lähdettävä sotaan, ja te jäisitte tänne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Miksi viette israelilaisilta halun mennä siihen maahan, jonka Herra on heille antanut?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Niin teidän isännekin tekivät, kun minä lähetin heidät Kaades-Barneasta katselemaan sitä maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Kun he olivat saapuneet Rypälelaaksoon asti ja katselleet sitä maata, he veivät israelilaisilta halun lähteä siihen maahan, jonka Herra oli heille antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Sinä päivänä syttyi Herran viha, ja hän vannoi sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, '\'Ne miehet, jotka lähtivät Egyptistä, kaksikymmentävuotiaat ja sitä vanhemmat, eivät saa nähdä sitä maata, jonka minä vannoen lupasin Aabrahamille, Iisakille ja Jaakobille, sillä he eivät ole minua uskollisesti seuranneet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'paitsi Kaaleb, kenissiläisen Jefunnen poika, ja Joosua, Nuunin poika, sillä nämä ovat uskollisesti seuranneet Herraa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Herran viha syttyi Israelia kohtaan, ja hän antoi heidän harhailla erämaassa neljäkymmentä vuotta, kunnes koko se sukupolvi hävisi, joka oli tehnyt sitä, mikä oli pahaa Herran silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Mutta katso, te olette nyt astuneet isienne sijaan, te syntisten sikiöt, lisätäksenne vielä Herran vihan kiivautta Israelia kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Jos te nyt käännytte pois hänestä, niin hän jättää kansan vielä kauemmaksi aikaa tähän erämaahan, ja te tuotatte tuhon kaikelle tälle kansalle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Niin he lähestyivät häntä ja sanoivat: \"Karjatarhoja me vain rakentaisimme tänne laumoillemme ja kaupunkeja vaimojamme ja lapsiamme varten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'mutta itse me varustautuisimme ja rientäisimme israelilaisten etunenässä, kunnes saisimme viedyksi heidät määräpaikkoihinsa, mutta vaimomme ja lapsemme asuisivat sillä aikaa varustetuissa kaupungeissa maan asukkailta rauhassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Emme palaisi koteihimme, ennen kuin israelilaiset ovat saaneet haltuunsa kukin perintöosansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'sillä me emme tahdo perintöosaa heidän kanssaan tuolta puolen Jordanin emmekä kauempaa, vaan meidän perintöosamme on tullut meille tältä puolelta Jordanin, siitä itään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Niin Mooses vastasi heille: \"Jos näin teette, jos Herran edessä varustaudutte sotaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'ja teistä jokainen, sotaan varustettuna, menee Jordanin yli Herran edessä niin pitkäksi aikaa, kunnes on karkottanut vihollisensa edeltään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'ja palaatte vasta sen jälkeen, kun maa on tehty alamaiseksi Herralle, olette vastuusta vapaat Herran ja Israelin edessä, ja tämä maa tulee teidän omaksenne Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Mutta jos ette tee näin, niin, katso, te rikotte Herraa vastaan ja saatte tuntea syntinne palkan, joka kohtaa teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Rakentakaa siis itsellenne kaupunkeja vaimojanne ja lapsianne varten ja tarhoja karjallenne ja tehkää se, mitä suunne on sanonut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Niin gaadilaiset ja ruubenilaiset vastasivat Moosekselle sanoen: \"Sinun palvelijasi tekevät, kuten herramme käskee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Lapsemme, vaimomme, laumamme ja kaikki juhtamme jääkööt tänne Gileadin kaupunkeihin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'mutta palvelijasi lähtevät, jokainen sotaan varustettuna, sinne taisteluun Herran edessä, kuten herramme sanoi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Mooses antoi heistä käskyn pappi Eleasarille ja Joosualle, Nuunin pojalle, ja Israelin sukukuntien perhekuntien päämiehille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'ja Mooses sanoi heille: \"Jos gaadilaiset ja ruubenilaiset teidän kanssanne lähtevät Jordanin yli, jokainen varustettuna taisteluun Herran edessä, ja maa tulee teille alamaiseksi, niin antakaa heille Gileadin maa omaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Mutta jolleivät he varustaudu ja lähde teidän kanssanne sinne, asettukoot teidän keskuuteenne Kanaanin maahan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Silloin gaadilaiset ja ruubenilaiset vastasivat sanoen: \"Mitä Herra on puhunut palvelijoillesi, sen teemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Me lähdemme varustettuina Herran edessä Kanaanin maahan, että saisimme omaksemme perintöosan tältä puolen Jordanin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Mooses antoi heille, gaadilaisille ja ruubenilaisille sekä puolelle Manassen, Joosefin pojan, sukukuntaa, amorilaisten kuninkaan Siihonin valtakunnan ja Baasanin kuninkaan Oogin valtakunnan, maan ja sen kaupungit alueineen, maan kaupungit ympäristöstä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Gaadilaiset rakensivat Diibonin, Atarotin, Aroerin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Atrot-Soofanin, Jaeserin, Jogbehan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Beet-Nimran ja Beet-Haaranin varustetuiksi kaupungeiksi sekä karjatarhoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Ruubenilaiset puolestaan rakensivat Hesbonin, Elalen ja Kirjataimin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Nebon ja Baal-Meonin, joiden nimet muutettiin, sekä Sibman. He antoivat nimet niille kaupungeille, jotka he rakensivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Mutta Maakir, Manassen poika, lähti Gileadiin ja valloitti sen ja karkotti amorilaiset, jotka asuivat siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Mooses antoi Gileadin Maakirille, Manassen pojalle, ja hän asettui sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Jaair, Manassen poika, meni ja valloitti heidän leirikylänsä ja kutsui ne Jaairin leirikyliksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Noobah meni ja valloitti Kenatin sekä sen alueella olevat kylät ja kutsui sen, nimensä mukaan, Noobahiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Nämä olivat israelilaisten matkat, jotka he kulkivat Egyptistä osastoittain Mooseksen ja Aaronin johdolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Mooses kirjoitti Herran käskyn mukaan muistiin ne paikat, joista he lähtivät liikkeelle matkoillaan. Nämä ovat heidän matkansa heidän lähtöpaikkojensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'He lähtivät liikkeelle Ramseksesta ensimmäisessä kuussa ensimmäisen kuukauden viidentenätoista päivänä. Israelilaiset lähtivät matkaan pääsiäisen jälkeisenä päivänä voimallisen käden suojassa kaikkien egyptiläisten nähden');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'egyptiläisten haudatessa kaikkia esikoisiaan, jotka Herra heidän keskuudestaan oli surmannut, ja Herran antaessa tuomion kohdata heidän jumaliaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Israelilaiset lähtivät Ramseksesta ja leiriytyivät Sukkotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'He lähtivät Sukkotista ja leiriytyivät Eetamiin, joka on erämaan reunassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'He lähtivät Eetamista ja kääntyivät takaisin Pii-Hahirotiin päin, joka on vastapäätä Baal-Sefonia, ja leiriytyivät Migdolin kohdalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'He lähtivät Pii-Hahirotista ja kulkivat meren keskitse erämaahan ja vaelsivat kolmen päivän matkan Eetamin erämaassa ja leiriytyivät Maaraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'He lähtivät Maarasta ja tulivat Eelimiin. Eelimissä oli kaksitoista vesilähdettä ja seitsemänkymmentä palmupuuta, ja he leiriytyivät sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'He lähtivät Eelimistä ja leiriytyivät Kaislameren rannalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'He lähtivät Kaislameren rannalta ja leiriytyivät Siinin erämaahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'He lähtivät Siinin erämaasta ja leiriytyivät Dofkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'He lähtivät Dofkasta ja leiriytyivät Aalukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'He lähtivät Aaluksesta ja leiriytyivät Refidimiin. Siellä ei ollut vettä kansan juoda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'He lähtivät Refidimistä ja leiriytyivät Siinain erämaahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'He lähtivät Siinain erämaasta ja leiriytyivät Kibrot-Hattaavaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'He lähtivät Kibrot-Hattaavasta ja leiriytyivät Haserotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'He lähtivät Haserotista ja leiriytyivät Ritmaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'He lähtivät Ritmasta ja leiriytyivät Rimmon-Perekseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'He lähtivät Rimmon-Pereksestä ja leiriytyivät Libnaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'He lähtivät Libnasta ja leiriytyivät Rissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'He lähtivät Rissasta ja leiriytyivät Kehelataan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'He lähtivät Kehelatasta ja leiriytyivät Seferin vuoren juurelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'He lähtivät Seferin vuoren juurelta ja leiriytyivät Haradaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'He lähtivät Haradasta ja leiriytyivät Makhelotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'He lähtivät Makhelotista ja leiriytyivät Tahatiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'He lähtivät Tahatista ja leiriytyivät Tarahiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'He lähtivät Tarahista ja leiriytyivät Mitkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'He lähtivät Mitkasta ja leiriytyivät Hasmonaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'He lähtivät Hasmonasta ja leiriytyivät Mooserotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'He lähtivät Mooserotista ja leiriytyivät Bene-Jaakaniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'He lähtivät Bene-Jaakanista ja leiriytyivät Hoor-Gidgadiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'He lähtivät Hoor-Gidgadista ja leiriytyivät Jotbataan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'He lähtivät Jotbatasta ja leiriytyivät Abronaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'He lähtivät Abronasta ja leiriytyivät Esjon-Geberiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'He lähtivät Esjon-Geberistä ja leiriytyivät Siinin erämaahan, se on Kaadekseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'He lähtivät Kaadeksesta ja leiriytyivät Hoorin vuoren juurelle, Edomin maan rajalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Pappi Aaron nousi Hoorin vuorelle Herran käskyn mukaan ja kuoli siellä neljäntenäkymmenentenä vuotena siitä, kun israelilaiset olivat lähteneet Egyptin maasta, viidennessä kuussa, kuukauden ensimmäisenä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Aaron oli sadan kahdenkymmenen kolmen vuoden vanha kuollessaan Hoorin vuorella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Aradin kuningas, kanaanilainen, joka asui Kanaanin maan eteläosassa, sai kuulla israelilaisten tulosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'He lähtivät Hoorin vuorelta ja leiriytyivät Salmonaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'He lähtivät Salmonasta ja leiriytyivät Puunoniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'He lähtivät Puunonista ja leiriytyivät Oobotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'He lähtivät Oobotista ja leiriytyivät Iije-Abarimiin Mooabin rajalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'He lähtivät Iijimistä ja leiriytyivät Diibon-Gaadiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'He lähtivät Diibon-Gaadista ja leiriytyivät Almon-Diblataimiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'He lähtivät Almon-Diblataimista ja leiriytyivät Abarimin vuoristoon vastapäätä Neboa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'He lähtivät Abarimin vuoristosta ja leiriytyivät Mooabin arolle Jordanin rantaan, Jerikon kohdalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Jordanin rannalla heidän leirinsä ulottui Beet-Jesimotista aina Aabel-Sittimiin asti Mooabin arolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Herra puhui Moosekselle Mooabin arolla Jordanin rannalla Jerikon kohdalla sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, '\"Puhu israelilaisille ja sano heille: Kun olette kulkeneet Jordanin yli Kanaanin maahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'niin karkottakaa tieltänne kaikki maan asukkaat ja hävittäkää kaikki heidän jumalankuvansa, hävittäkää kaikki heidän valetut kuvansa ja kukistakaa kaikki heidän uhrikukkulansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'Ottakaa sitten maa haltuunne ja asukaa siinä, sillä teille minä annan omaksi sen maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Jakakaa maa keskenänne arvalla sukujenne mukaan. Suuremmalle suvulle antakaa suurempi perintöosa ja pienemmälle pienempi perintöosa. Kukin saakoon perintöosansa siinä, mihin arpa sen hänelle määrää. Jakakaa maa isienne sukukuntien mukaan keskenänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Mutta jos ette karkota maan asukkaita tieltänne, niin ne, jotka te heistä jätätte jäljelle, tulevat teille okaiksi silmiinne ja tutkaimiksi kylkiinne, ja he ahdistavat teitä siinä maassa, jossa te asutte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Silloin minä teen teille, niin kuin aioin tehdä heille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, '\"Käske israelilaisia ja sano heille: Kun tulette Kanaanin maahan – se on se maa, jonka te saatte perintöosaksenne, Kanaanin maa rajasta rajaan –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'niin teidän etelärajanne kulkekoon Siinin erämaasta Edomia pitkin. Eteläraja alkakoon idässä Suolameren päästä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'ja kääntyköön Skorpionisolasta etelään ja kulkekoon Siiniin, ja päättyköön Kaades-Barneasta etelään. Sieltä raja lähteköön Hasar-Addariin, kulkekoon Asmoniin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'ja kääntyköön Asmonista Egyptin purolle ja päättyköön mereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Teidän länsirajananne olkoon Suuri meri. Tämä olkoon länsirajananne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Teidän pohjoisrajanne olkoon tämä: Suuresta merestä vetäkää raja Hoorin vuoreen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'Hoorin vuoresta vetäkää raja siihen, mistä mennään Hamatiin, ja raja päättyköön Sedadiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'Sieltä raja lähteköön Sifroniin ja päättyköön Hasar-Eenaniin. Tämä olkoon pohjoisrajananne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Itärajanne vetäkää Hasar-Eenanista Sefamiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'Sefamista raja kulkekoon Riblaan, Ainista itään, ja sieltä raja kulkekoon edelleen, kunnes se kohtaa vuoriselänteen Kinneretin järven itäpuolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'Sitten raja yhtyköön Jordaniin ja päättyköön Suolamereen. Tämä on oleva teidän maanne rajoineen ympäriinsä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Mooses käski israelilaisia sanoen: \"Tämä on se maa, joka teidän on jaettava arvalla keskenänne ja jonka Herra määräsi annettavaksi yhdeksälle ja puolelle sukukunnalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Sillä ruubenilaisten sukukunta perhekunnittain ja gaadilaisten sukukunta perhekunnittain ja toinen puoli Manassen sukukuntaa ovat jo saaneet perintöosansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Nämä kaksi ja puoli sukukuntaa ovat jo saaneet perintöosansa tällä puolella Jordania Jerikon kohdalla, itään, auringon nousun suuntaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, '\"Nämä ovat niiden miesten nimet, joiden on maa teille jaettava: pappi Eleasar ja Joosua, Nuunin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Näiden lisäksi valitkaa päämies kustakin sukukunnasta maata jakamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Nämä ovat niiden miesten nimet: Juudan sukukunnasta Kaaleb, Jefunnen poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'simeonilaisten sukukunnasta Semuel, Ammihudin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Benjaminin sukukunnasta Elidad, Kislonin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'daanilaisten sukukunnasta päämies Bukki, Joglin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'joosefilaisista, manasselaisten sukukunnasta, päämies Hanniel, Eefodin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'efraimilaisten sukukunnasta päämies Kemuel, Siftanin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'sebulonilaisten sukukunnasta päämies Elisafan, Parnakin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'isaskarilaisten sukukunnasta päämies Paltiel, Assanin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'asserilaisten sukukunnasta päämies Ahihud, Selomin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'ja naftalilaisten sukukunnasta Pedahel, Ammihudin poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Nämä Herra määräsi jakamaan israelilaisille Kanaanin maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Herra puhui Moosekselle Mooabin arolla Jordanin rannalla Jerikon kohdalla sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, '\"Käske israelilaisia antamaan omistamistaan perintöosista leeviläisille kaupunkeja heidän asuakseen ja antamaan leeviläisille myös laidunmaata kaupunkien ympäriltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Nämä kaupungit olkoot heillä asuntoina, ja niiden laidunmaat olkoot heidän juhtiaan, karjaansa ja kaikkia muita eläimiään varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Näiden kaupunkien laidunmaat, jotka teidän on annettava leeviläisille, ulottukoot kaupungin muurista ulospäin tuhat kyynärää joka taholle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Mitatkaa kaupungin ulkopuolella itään kaksituhatta kyynärää ja etelään kaksituhatta kyynärää ja länteen kaksituhatta kyynärää ja pohjoiseen kaksituhatta kyynärää, ja kaupunki olkoon siinä keskellä. Tämä olkoon heillä kaupunkien laidunmaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Niistä kaupungeista, jotka teidän on annettava leeviläisille, olkoon kuusi turvakaupunkia, jotka teidän on annettava pakopaikaksi sille, joka on jonkun tappanut. Niiden lisäksi antakaa neljäkymmentä kaksi kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Kaikkiaan olkoon kaupunkeja ja niiden laidunmaita, jotka teidän on annettava leeviläisille, neljäkymmentä kahdeksan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Niitä israelilaisten omistamia kaupunkeja, jotka teidän on annettava, otettakoon useampia siltä sukukunnalta, jolla niitä on paljon, ja vähemmän siltä, jolla on niitä vähemmän. Kukin sukukunta antakoon leeviläisille kaupunkejaan saamansa perintöosan mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, '\"Puhu israelilaisille ja sano heille: Kun olette menneet Jordanin yli Kanaanin maahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'niin valitkaa itsellenne kaupunkeja turvakaupungeiksenne. Niihin paetkoon tappaja, joka on jonkun surmannut vahingossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Nämä kaupungit olkoot teillä turvapaikkoina verenkostajalta, niin ettei tappajan tarvitse kuolla, ennen kuin hän on ollut seurakunnan tuomittavana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Kaupunkeja, jotka teidän on määrättävä turvakaupungeiksi, olkoon teillä kuusi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Kolme kaupunkia teidän on määrättävä tältä puolelta Jordanin, ja kolme kaupunkia teidän on määrättävä Kanaanin maasta. Ne olkoot turvakaupunkeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Israelilaisille ja teidän keskuudessanne asuvalle muukalaiselle ja talonne suojatille olkoot ne kuusi kaupunkia turvapaikkoina, joihin voi paeta jokainen, joka surmaa jonkun tahattomasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Mutta jos joku rauta-aseella lyö toista, niin että tämä kuolee, hän on tahallinen tappaja. Tappaja rangaistakoon kuolemalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Jos joku ottaa käteensä kiven, jolla voi lyödä kuoliaaksi, ja lyö toista, niin että tämä kuolee, hän on tahallinen tappaja. Tappaja rangaistakoon kuolemalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Tai jos joku ottaa käteensä puuaseen, jolla voi lyödä kuoliaaksi, ja lyö toista, niin että tämä kuolee, on hän tahallinen tappaja. Tappaja rangaistakoon kuolemalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Verenkostaja ottakoon tappajan hengiltä. Hän ottakoon hänet hengiltä, milloin vain hänet tapaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Jos joku vihassa iskee toista tai heittää häntä jollakin murhaamistarkoituksessa, niin että tämä kuolee,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'tai vihaa kantaen lyö häntä kädellään, niin että hän kuolee, rangaistakoon lyöjä kuolemalla, sillä hän on tahallinen tappaja. Verenkostaja ottakoon sellaisen tappajan hengiltä, milloin vain hänet tapaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Mutta jos joku vahingossa, vaan ei vihassa, satuttaa toista tai heittää häntä jollakin esineellä, millä hyvänsä, ilman murhaamistarkoitusta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'tai jos hän kivellä, jolla voi lyödä kuoliaaksi, huomaamattaan satuttaa toista, niin että tämä kuolee, eikä hän ollut hänen vihamiehensä eikä tarkoittanut häntä vahingoittaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'seurakunta ratkaiskoon tappajan ja verenkostajan välin näiden säädösten mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'Seurakunta päästäköön tappajan verenkostajan kädestä, ja seurakunta antakoon hänen palata turvakaupunkiin, johon hän oli paennut. Asukoon siellä pyhällä öljyllä voidellun ylimmäisen papin kuolemaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Mutta jos tappaja menee sen turvakaupungin alueen ulkopuolelle, johon hän on paennut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'ja verenkostaja tapaa hänet hänen turvakaupunkinsa alueen ulkopuolella ja verenkostaja surmaa tappajan, hän ei joudu verenvikaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Hänen on näet asuttava turvakaupungissaan ylimmäisen papin kuolemaan asti. Mutta ylimmäisen papin kuoltua tappaja saa palata perintömaalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Tämä olkoon teillä oikeussäädöksenä sukupolvesta sukupolveen, missä asuttekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Jos joku lyö toisen kuoliaaksi, surmattakoon tappaja todistajien antaman todistuksen nojalla, mutta yhden todistajan todistuksen nojalla älköön ketään kuolemalla rangaistako.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Älkää ottako lunastusmaksua sellaisen tappajan hengestä, joka on tehnyt henkirikoksen, vaan rangaistakoon hänet kuolemalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Älkääkä ottako lunastusmaksua siltä, joka on paennut turvakaupunkiin, ettei hän ennen papin kuolemaa saisi palata asumaan omalle maalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Älkääkä saastuttako sitä maata, jossa olette, sillä veri saastuttaa maan. Maalle ei voi toimittaa sovitusta verestä, joka siihen on vuodatettu, muulla kuin sen verellä, joka on sen vuodattanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Älkää siis saastuttako maata, jossa asutte ja jossa minäkin asun teidän keskellänne, sillä minä, Herra, asun israelilaisten keskellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Gileadin, Maakirin pojan, Manassen pojanpojan, suvun perhekuntapäämiehet, jotka olivat Joosefin poikien sukua, astuivat esiin ja puhuivat Moosekselle ja ruhtinaille, israelilaisten perhekuntien päämiehille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'ja sanoivat: \" Herra käski herrani jakaa sen maan arvalla israelilaisille perintöosaksi, ja herrani sai käskyn Herralta antaa Selofhadin, veljemme, perintöosan hänen tyttärilleen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Mutta jos he joutuvat vaimoiksi joillekin israelilaisten muiden heimojen pojista, heidän perintöosansa siirtyy pois isiemme perintöosasta ja liitetään sen sukukunnan perintöosaan, johon he tulevat kuulumaan, mutta meidän perintöosamme vähenee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Kun israelilaisten riemuvuosi tulee, niin heidän perintöosansa lisätään sen sukukunnan perintöosaan, johon he tulevat kuulumaan, mutta meidän isiemme sukukunnan perintöosasta vähentyy heidän perintöosansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Silloin Mooses sääti israelilaisille Herran käskyn mukaan, sanoen: \"Joosefilaisten sukukunta puhuu oikein.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Näin Herra säätää Selofhadin tyttäristä: Menkööt vaimoiksi kenelle tahtovat, kunhan vain menevät vaimoiksi johonkin isänsä sukukunnan sukuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Sillä älköön perintöosa israelilaisilta siirtykö sukukunnasta toiseen, vaan israelilaiset säilyttäkööt kukin isiensä sukukunnan perintöosan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Mutta jokainen tytär, joka saa perintöosan israelilaisten sukukunnissa, menköön vaimoksi johonkin isänsä sukukunnan sukuun, että israelilaiset saisivat periä kukin isiensä perintöosan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'ja ettei perintöosa siirtyisi sukukunnasta toiseen, vaan israelilaisten sukukunnat säilyttäisivät kukin perintöosansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Kuten Herra oli Moosesta käskenyt, niin Selofhadin tyttäret tekivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Mahla, Tirsa, Hogla, Milka ja Nooga, Selofhadin tyttäret, menivät vaimoiksi setiensä pojille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'He menivät vaimoiksi Joosefin pojan Manassen poikien sukuihin, ja niin heidän perintöosansa jäi heidän isänsä suvun sukukuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Nämä ovat ne käskyt ja säädökset, jotka Herra Mooseksen kautta antoi israelilaisille Mooabin arolla Jordanin rannalla, Jerikon luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Nämä ovat ne sanat, jotka Mooses puhui kaikelle Israelille, tuolla puolella Jordanin erämaassa, Aromaassa, vastapäätä Suufia, Paaranin, Toofelin, Laabanin, Haserotin ja Dii-Saahabin välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Hoorebista on yksitoista päivämatkaa, Seirin vuoriston tietä, Kaades-Barneaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Neljäntenäkymmenentenä vuotena yhdennessätoista kuussa kuukauden ensimmäisenä päivänä Mooses puhui israelilaisille kaiken, mitä Herra oli käskenyt hänen heille puhua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Tämä tapahtui sen jälkeen, kun hän oli voittanut Siihonin, amorilaisten kuninkaan, joka asui Hesbonissa, ja Oogin, Baasanin kuninkaan, joka asui Astarotissa, Edrein luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Tuolla puolella Jordanin Mooabin maassa Mooses alkoi selittää tätä lakia sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, '\" Herra, Jumalamme, puhui meille Hoorebilla näin: \'Te olette jo tarpeeksi kauan olleet tämän vuoren vaiheilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Kääntykää toisaalle, lähtekää liikkeelle ja menkää amorilaisten vuoristoon ja kaikkien heidän naapuriensa luo Aromaahan, Vuoristoon, Alankomaahan, Negeviin ja Merenrannikolle, kanaanilaisten maahan ja Libanoniin, aina suureen virtaan, Eufrat-virtaan, saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Katso, minä annan maan teidän valtaanne. Menkää ja ottakaa omaksenne maa, jonka Herra teidän isillenne, Aabrahamille, Iisakille ja Jaakobille, vannotulla valalla on luvannut antaa heille ja heidän jälkeläisilleen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Silloin minä puhuin teille sanoen: \'Minä en jaksa yksin kantaa teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Herra, teidän Jumalanne, on antanut teidän lisääntyä, ja katso, teidän lukunne on tänä päivänä kuin taivaan tähtien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Lisätköön Herra, isienne Jumala, teitä vielä tuhatkertaisesti ja siunatkoon teitä, niin kuin hän on teille puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Mutta kuinka minä voin yksin kantaa sitä kuormaa ja taakkaa, joka minulla on teistä ja teidän riitelemisistänne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Tuokaa tänne viisaita, ymmärtäväisiä ja tunnettuja miehiä jokaisesta sukukunnastanne, niin minä asetan heidät päämiehiksenne.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Te vastasitte minulle ja sanoitte: \'On hyvä, mitä ehdotat tehtäväksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Silloin otin sukukuntienne päämiehet, jotka olivat viisaita ja tunnettuja miehiä, ja asetin heidät päämiehiksenne, tuhannen-, sadan-, viidenkymmenen- ja kymmenenjohtajiksi, ja päälliköiksi sukukuntiinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Käskin tuomareitanne sanoen: \'Kuulustelkaa veljiänne ja tuomitkaa oikein, jos jollakulla on riita-asia veljensä tai luonaan asuvan muukalaisen kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Älkää katsoko henkilöön tuomitessanne, vaan kuulkaa pientä yhtä hyvin kuin suurtakin. Älkää pelätkö ketään ihmistä, sillä tuomio on Jumalan. Mutta asia, joka on teistä liian vaikea, lykätkää minulle kuullakseni sen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Silloin annoin teille käskyt kaikesta, mitä teidän oli tehtävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Lähdimme liikkeelle Hoorebilta ja kuljimme koko sen suuren ja pelottavan erämaan kautta, jonka te olette nähneet, amorilaisten vuoriston tietä, niin kuin Herra, Jumalamme, oli käskenyt meitä, ja tulimme Kaades-Barneaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Sanoin teille: \'Te olette tulleet amorilaisten vuoristoon, jonka Herra, Jumalamme, meille antaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Katso, Herra, Jumalasi, antaa maan valtaasi. Mene ja ota se omaksesi, niin kuin Herra, isiesi Jumala, on sinulle puhunut. Älä pelkää äläkä arkaile.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Te astuitte kaikki minun eteeni ja sanoitte: \'Lähettäkäämme miehiä edellämme tutkimaan maata ja antamaan meille tietoja tiestä, jota meidän on sinne mentävä, ja kaupungeista, joihin tulemme.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Tämä puhe oli minun silmissäni hyvä, ja minä otin kaksitoista miestä teidän keskuudestanne, yhden jokaisesta sukukunnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Nämä lähtivät ja nousivat vuoristoon ja tulivat Rypälelaaksoon ja vakoilivat maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'He ottivat mukaansa maan hedelmiä ja toivat meille ja antoivat meille tietoja ja sanoivat: \'Maa, jonka Herra, Jumalamme, antaa meille, on hyvä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Mutta te ette tahtoneet mennä sinne, vaan niskoittelitte Herran, Jumalanne, käskyä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'Te niskoittelitte teltoissanne ja sanoitte: \'Sen tähden että Herra vihaa meitä, hän vei meidät pois Egyptin maasta antaakseen meidät amorilaisten käsiin ja tuhotakseen meidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Mihin me menemme? Veljemme ovat saattaneet meidän rohkeutemme raukeamaan, sillä he sanovat: Siellä on meitä suurempi ja kookkaampi kansa, siellä on suuria, taivaan tasalle varustettuja kaupunkeja. Näimmepä siellä anakilaisiakin.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Niin minä vastasin teille: \'Älkää säikähtykö älkääkä pelätkö heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Herra, teidän Jumalanne, joka käy teidän edellänne, taistelee itse teidän puolestanne, aivan kuin hän teki teille Egyptissä teidän silmienne edessä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'ja erämaassa, jossa sinä olet nähnyt, kuinka Herra, Jumalasi, on kantanut sinua, niin kuin mies kantaa poikaansa, koko sen matkan, jonka te olette kulkeneet, kunnes tulitte tähän paikkaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Mutta sittenkään te ette uskoneet Herraan, teidän Jumalaanne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'joka kävi teidän edellänne tiellä katsoakseen teille leiripaikat: yöllä tulessa, valaistakseen teille tien, jota teidän oli kuljettava, ja päivällä pilvessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Kun Herra kuuli teidän puheenne, hän vihastui ja vannoi sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, '\'Totisesti, ei kukaan näistä miehistä, tästä pahasta sukupolvesta, saa nähdä sitä hyvää maata, jonka minä valalla vannoen olen luvannut antaa isillenne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'ei kukaan, paitsi Kaaleb, Jefunnen poika. Hän saa sen nähdä, ja hänelle ja hänen lapsilleen minä annan sen maan, johon hän on astunut, sen tähden että hän on uskollisesti seurannut Herraa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Minuunkin Herra vihastui teidän tähtenne ja sanoi: \'Et sinäkään pääse sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Joosua, Nuunin poika, joka sinua palvelee, hän pääsee sinne. Vahvista häntä, sillä hän on jakava maan Israelille perinnöksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Teidän lapsenne, joiden sanoitte joutuvan vihollisen saaliiksi, ja teidän poikanne, jotka eivät vielä tiedä, mikä on hyvä, mikä paha, he pääsevät sinne. Heille minä annan maan, ja he ottavat sen omakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Mutta te kääntykää takaisin ja lähtekää liikkeelle erämaahan Kaislameren tietä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Silloin te vastasitte ja sanoitte minulle: \'Me olemme tehneet syntiä Herraa vastaan. Me menemme ja taistelemme, aivan kuten Herra, Jumalamme, on meitä käskenyt.\' Te vyöttäydyitte kaikki sota-aseisiinne ja lähditte kevytmielisesti nousemaan vuoristoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Mutta Herra sanoi minulle: \'Sano heille: Älkää nousko sinne älkääkä antautuko taisteluun, sillä minä en ole teidän keskellänne. Älkää tehkö niin, etteivät vihollisenne voittaisi teitä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Minä puhuin teille, mutta te ette kuulleet, vaan niskoittelitte Herran käskyä vastaan ja lähditte ylimielisesti vuoristoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Amorilaiset, jotka asuvat siinä vuoristossa, lähtivät teitä vastaan ja ajoivat teitä takaa, niin kuin mehiläiset tekevät, ja hajottivat teidät Seirissä, ja aina Hormaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Niin te palasitte ja itkitte Herran edessä. Mutta Herra ei kuullut huutoanne eikä kuunnellut teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Teidän täytyi viipyä Kaadeksessa se pitkä aika, minkä siellä viivyitte.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, '\"Sitten me käännyimme toisaalle ja lähdimme liikkeelle erämaahan Kaislameren tietä, niin kuin Herra oli minulle puhunut, ja kiertelimme kauan aikaa Seirin vuoristossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Herra sanoi minulle näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, '\'Te olette jo tarpeeksi kauan kierrelleet tässä vuoristossa. Kääntykää nyt pohjoista kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Käske kansaa sanoen: Te tulette kulkemaan Seirissä asuvien veljienne, Eesaun jälkeläisten, alueen kautta. He pelkäävät teitä, mutta te pitäkää itsestänne tarkka vaari:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'älkää ryhtykö taisteluun heidän kanssaan, sillä minä en anna teille jalanleveyttäkään heidän maastaan, koska minä olen antanut Seirin vuoriston Eesaun omaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Rahalla ostakaa heiltä ruokaa syödäksenne, vesikin hankkikaa heiltä rahalla juodaksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Sillä Herra, Jumalasi, on siunannut sinua kaikissa kättesi töissä. Hän on pitänyt huolen vaelluksestasi tässä suuressa erämaassa. Jo neljäkymmentä vuotta on Herra, Jumalasi, ollut kanssasi, eikä sinulta ole puuttunut mitään.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Niin me lähdimme pois veljiemme Eesaun jälkeläisten luota, jotka asuvat Seirissä, poiketen Aromaan tieltä, joka tulee Eilatista ja Esjon-Geberistä. Me käännyimme toisaalle ja lähdimme kulkemaan Mooabin erämaan tietä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Silloin Herra sanoi minulle: \'Älä käy Mooabin kimppuun äläkä ryhdy taisteluun heidän kanssaan, sillä minä en anna heidän maastaan mitään omaksesi, koska minä olen antanut Aarin Lootin jälkeläisten omaksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'Eemiläiset asuivat muinoin siellä. He olivat suuri, lukuisa ja kookas kansa niin kuin anakilaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Samoin kuin anakilaiset heidätkin luettiin refalaisiin, mutta mooabilaiset kutsuivat heitä eemiläisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Hoorilaiset sitä vastoin asuivat muinoin Seirissä, mutta Eesaun jälkeläiset karkottivat heidät tieltään ja tuhosivat heidät ja asettuivat heidän sijaansa, samoin kuin Israel teki siinä maassa, jonka Herra oli antanut heidän omakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, '\'Nouskaa siis ja kulkekaa Seredin puron poikki.\' Niin me kuljimme Seredin puron yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Aika, joka kului vaellukseemme Kaades-Barneasta siihen asti, että kuljimme Seredin puron yli, oli kolmekymmentä kahdeksan vuotta, kunnes hävisi koko se sukupolvi, kaikki sotakuntoiset miehet, leiristä, niin kuin Herra oli heille vannonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Myös Herran käsi oli heitä vastaan hävittämässä heitä leiristä viimeiseen mieheen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Kun kaikki sotakuntoiset miehet olivat kuolleet pois kansasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'puhui Herra minulle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, '\'Sinä kuljet nyt Mooabin alueen kautta, Aarin kautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'ja lähestyt ammonilaisia. Mutta älä käy heidän kimppuunsa äläkä ryhdy taisteluun heidän kanssaan, sillä minä en anna ammonilaisten maasta mitään omaksesi, koska minä olen antanut sen Lootin jälkeläisten omaksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, 'Tämäkin on luettu refalaisten maaksi. Refalaiset asuivat muinoin siellä, mutta ammonilaiset kutsuivat heitä samsumilaisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'He olivat kuin anakilaiset suuri, lukuisa ja kookas kansa. Mutta Herra tuhosi nämä heidän tieltään. He karkottivat heidät ja asettuivat näiden sijaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'Samoin hän on tehnyt Eesaun jälkeläisille, jotka asuvat Seirissä, kun hän tuhosi hoorilaiset heidän tieltään. He karkottivat nämä ja asettuivat näiden sijaan, ja siellä he asuvat vielä tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Mutta avvilaisille, jotka asuivat maakylissä aina Gassaan asti, tuottivat tuhon kaftorilaiset, jotka olivat lähteneet Kaftorista, ja asettuivat heidän sijaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, '\'Nouskaa ja lähtekää liikkeelle ja kulkekaa Arnon-joen yli. Katso, minä annan käsiisi amorilaisen Siihonin, Hesbonin kuninkaan, ja hänen maansa. Käy sitä valloittamaan ja ryhdy taisteluun häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Tästä päivästä alkaen minä saatan kauhuun ja pelkoon edessäsi kansat kaiken taivaan alla, niin että kun ne kuulevat sinusta kerrottavan, ne pelkäävät ja vapisevat edessäsi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Minä lähetin sanansaattajat Kedemotin erämaasta Siihonille, Hesbonin kuninkaalle, viemään rauhan tervehdyksen ja sanomaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, '\'Salli minun kulkea maasi kautta. Aina tiellä pysyen minä kuljen poikkeamatta oikealle tai vasemmalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Anna minun rahalla ostaa ruokaa syödäkseni ja anna minulle rahalla vettä juodakseni. Salli vain minun jalkaisin kulkea maasi kautta\' –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'sen minulle myönsivät Eesaun jälkeläiset, jotka asuvat Seirissä, ja mooabilaiset, jotka asuvat Aarissa – \'kunnes menen Jordanin yli siihen maahan, jonka Herra, Jumalamme, meille antaa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Mutta Siihon, Hesbonin kuningas, ei tahtonut antaa meidän kulkea maansa kautta, sillä Herra, Jumalasi, paadutti hänen mielensä ja kovensi hänen sydämensä antaakseen hänet käsiisi, niin kuin nyt onkin tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Herra sanoi minulle: \'Katso, minä annan nyt Siihonin ja hänen maansa valtaasi. Ryhdy sitä valloittamaan ja ota hänen maansa omaksesi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Siihon ja kaikki hänen sotaväkensä lähti Jahaaseen taistelemaan meitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Mutta Herra, Jumalamme, antoi hänet valtaamme, ja me voitimme hänet ja hänen poikansa ja kaiken hänen sotaväkensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Me valloitimme silloin kaikki hänen kaupunkinsa ja vihimme tuhon omiksi jokaisessa kaupungissa miehet, naiset ja lapset, päästämättä ainoatakaan pakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Ainoastaan karjan me ryöstimme itsellemme sekä saaliin valloittamistamme kaupungeista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Aroerista, joka on Arnon-joen rannalla, ja jokilaaksossa olevasta kaupungista Gileadiin saakka ei ollut ainoatakaan kaupunkia, joka olisi ollut meille liian korkealla. Herra, Jumalamme, antoi kaikki valtaamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Ainoastaan ammonilaisten maahan sinä et astunut, et mihinkään, mikä on Jabbok-joen varrella, et vuoriston kaupunkeihin etkä mihinkään muuhun. Sen Herra, Jumalamme, oli niin määrännyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, '\"Käännyimme toisaalle ja kuljimme Baasanin tietä. Silloin lähti Oog, Baasanin kuningas, hän ja koko hänen sotajoukkonsa, Edreihin taistelemaan meitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Mutta Herra sanoi minulle: \'Älä pelkää häntä, sillä minä annan hänet käsiisi ja kaiken hänen kansansa ja hänen maansa. Tee hänelle, niin kuin teit Siihonille, amorilaisten kuninkaalle, joka asui Hesbonissa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Niin Herra, Jumalamme, antoi käsiimme myös Oogin, Baasanin kuninkaan, ja kaiken hänen sotaväkensä, ja me voitimme hänet päästämättä ainoatakaan pakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Me valloitimme silloin kaikki hänen kaupunkinsa – ei ollut ainoatakaan kaupunkia, jota emme olisi heiltä ottaneet – kuusikymmentä kaupunkia, koko Argobin seudun, Oogin valtakunnan Baasanissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'kaikki nämä kaupungit korkeilla muureilla, porteilla ja salvoilla varustettuja, ja sen lisäksi vielä suuren joukon linnoittamattomia pikkukaupunkeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Vihimme ne tuhon omiksi, niin kuin olimme tehneet Siihonille, Hesbonin kuninkaalle. Vihimme tuhon omiksi jokaisessa kaupungissa miehet, naiset ja lapset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Mutta kaiken karjan sekä saaliin kaupungeista ryöstimme itsellemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Otimme silloin kahdelta amorilaisten kuninkaalta, jotka hallitsivat tuolla puolella Jordanin, heidän maansa Arnon-joesta aina Hermonin vuoreen asti –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, 'siidonilaiset kutsuvat Hermonia Sirjoniksi, mutta amorilaiset kutsuvat sitä Seniriksi –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'otimme kaikki ylätasangon kaupungit ja koko Gileadin ja koko Baasanin aina Salkaan ja Edreihin, Baasanissa oleviin Oogin valtakunnan kaupunkeihin, saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Sillä Baasanin kuningas Oog oli yksin enää jäljellä viimeisistä refalaisista. Hänen basaltista tehty ruumisarkkunsa on vieläkin ammonilaisten kaupungissa Rabbassa. Se on yhdeksän kyynärää pitkä ja neljä kyynärää leveä, mitattuna tavallisella kyynärämitalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Kun olimme ottaneet silloin omaksemme tämän maan, annoin ruubenilaisille ja gaadilaisille sen osan siitä, joka alkaa Aroerista, Arnon-joen varrelta, sekä puolet Gileadin vuoristoa kaupunkeineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Loput Gileadista ja koko Baasanin, Oogin valtakunnan, annoin toiselle puolelle Manassen sukukuntaa, koko Argobin seudun. Koko tätä Baasania kutsutaan refalaisten maaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jaair, Manassen poika, valtasi koko Argobin seudun aina gesurilaisten ja maakatilaisten alueeseen saakka, ja hän kutsui nämä seudut, se on Baasanin, oman nimensä mukaan Jaairin leirikyliksi, niin kuin niitä kutsutaan vielä tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Maakirille annoin Gileadin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Ruubenilaisille ja gaadilaisille annoin maan Gileadista aina Arnon-jokeen, jokilaakson keskikohtaan saakka, joka on rajana, ja Jabbok-jokeen saakka, joka on ammonilaisten rajana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'Samoin annoin heille Aromaan, Jordan rajana, Kinneretistä aina Aromaan mereen, Suolamereen, saakka, Pisgan rinteiden juurelle, itään päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Silloin minä käskin teitä ja sanoin: \' Herra, teidän Jumalanne, on antanut teille tämän maan omaksenne. Mutta te, kaikki sotakuntoiset miehet, lähtekää aseistettuina veljienne, israelilaisten, etunenässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Ainoastaan vaimonne, lapsenne ja karjanne – sillä tiedän teillä olevan paljon karjaa – jääkööt kaupunkeihinne, jotka olen teille antanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'kunnes Herra suo veljienne, samoin kuin teidänkin, päästä rauhaan, kun hekin ovat ottaneet omakseen sen maan, jonka Herra, teidän Jumalanne, antaa teille Jordanin tuolta puolelta. Sitten saatte palata takaisin, kukin omistamalleen maalle, jonka olen teille antanut.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Silloin käskin Joosuaa ja sanoin: \'Sinä olet omin silmin nähnyt kaiken, mitä Herra, teidän Jumalanne, on tehnyt näille kahdelle kuninkaalle. Samalla tavalla Herra on tekevä kaikille valtakunnille, joihin menet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Älkää niitä pelätkö, sillä Herra, teidän Jumalanne, sotii itse teidän puolestanne.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Silloin anoin Herralta armoa sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, '\' Herra, Herra, sinä olet alkanut näyttää palvelijallesi valtasuuruuttasi ja väkevää kättäsi. Sillä kuka on se jumala taivaassa tai maassa, joka voi tehdä sellaisia töitä ja niin voimallisia tekoja kuin sinä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Niin salli minun nyt mennä katsomaan sitä hyvää maata, joka on tuolla puolella Jordanin, tuota ihanaa vuoristoa ja Libanonia.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Mutta Herra oli vihastunut minuun teidän tähtenne eikä kuullut minua, vaan sanoi minulle: \'Riittää! Älä puhu minulle enempää tästä asiasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Nouse Pisgan huipulle ja kohota katseesi länteen ja pohjoiseen, etelään ja itään ja katsele silmilläsi. Sillä tämän Jordanin yli sinä et mene.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Anna määräyksiä Joosualle, vahvista ja rohkaise häntä. Sillä hän menee sinne tämän kansan edellä, ja hän jakaa heille perinnöksi maan, jonka näet.\'.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Niin me jäimme laaksoon, vastapäätä Beet-Peoria.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, '\"Nyt, Israel, kuule ne käskyt ja säädökset, jotka teille opetan, että seuraisitte niitä, eläisitte ja ottaisitte omaksenne sen maan, jonka Herra, teidän isienne Jumala, antaa teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Älkää lisätkö mitään siihen, mitä minä teille määrään, älkääkä ottako siitä mitään pois, vaan noudattakaa Herran, Jumalanne, käskyjä, jotka minä teille säädän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Te olette omin silmin nähneet, mitä Herra teki Baal-Peorin asiassa, kuinka Herra, Jumalasi, hävitti keskuudestasi jokaisen, joka lähti kulkemaan Baal-Peorin perässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Mutta te, jotka riipuitte kiinni Herrassa, teidän Jumalassanne, te kaikki olette elossa vielä tänä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Katso, minä olen opettanut teille käskyt ja säädökset, niin kuin Herra, minun Jumalani, on minua käskenyt, että seuraisitte niitä siinä maassa, jota te menette ottamaan omaksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Noudattakaa ja seuratkaa niitä, sillä se on oleva teidän viisautenne ja ymmärryksenne kansojen silmissä. Kun he kuulevat kaikki nämä käskyt, he sanovat: \'Totisesti, viisas ja ymmärtäväinen kansa on tämä suuri kansa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Sillä onko toista suurta kansaa, jonka jumalat ovat sitä niin lähellä, kuin Herra, Jumalamme, on lähellä meitä, niin usein kuin me häntä rukoilemme?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Onko toista suurta kansaa, jolla on niin vanhurskaat käskyt ja säädökset, kuin on koko tämä laki, jonka minä tänä päivänä teille annan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Ole vain varuillasi ja ota itsestäsi tarkka vaari, ettet unohda, mitä olet omin silmin nähnyt, ja ettei se lähde sydämestäsi koko elinaikanasi, vaan että ilmoitat sen lapsillesi ja lastesi lapsille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'mitä tapahtui sinä päivänä, jona seisoit Herran, Jumalasi, edessä Hoorebilla, kun Herra sanoi minulle: \'Kokoa kansa, niin minä julistan heille sanani, että he oppisivat pelkäämään minua, niin kauan kuin elävät maan päällä, ja opettaisivat lapsensakin siihen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Te astuitte esille ja jäitte seisomaan vuoren juurelle, ja vuori paloi tulena, joka loimusi sisimpään taivaaseen asti pimeyden ja synkkien pilvien keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Silloin Herra puhui teille tulen keskeltä. Sanat te kuulitte, mutta ette nähneet hänen muotoaan, kuulitte vain äänen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Hän ilmoitti teille liittonsa, jonka hän käski teidän pitää, nimittäin nuo kymmenen käskysanaa. Hän kirjoitti ne kahteen kivitauluun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Silloin Herra käski minun opettaa teille käskyt ja säädökset, että te seuraisitte niitä siinä maassa, jota te menette ottamaan omaksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Ottakaa siis itsestänne tarkka vaari – sillä te ette nähneet sinä päivänä, jona Herra puhui teille tulen keskeltä Hoorebilla, hänestä minkäänlaista muotoa –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'ettette menettele kelvottomasti ettekä tee itsellenne jumalankuvaa, ette minkään muotoista patsasta, ette miehen tai naisen kuvaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'ette maan päällä liikkuvan nelijalkaisen eläimen kuvaa, ette taivaan alla lentävän siivekkään linnun kuvaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'ette maassa matelevan kuvaa ettekä vesissä maan alla olevan kalan kuvaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'ja ettet, kun nostat silmäsi taivasta kohti ja katselet aurinkoa, kuuta ja tähtiä, kaikkea taivaan joukkoa, anna vietellä itseäsi kumartamaan ja palvelemaan niitä, sillä Herra, Jumalasi, on jakanut ne kaikille muille kansoille koko taivaan alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Onhan Herra ottanut teidät ja vienyt pois rautapätsistä, Egyptistä, että teistä tulisi hänen perintökansansa, niin kuin nyt on tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Mutta Herra vihastui minuun teidän tähtenne ja vannoi, etten minä saa mennä Jordanin yli enkä tulla siihen hyvään maahan, jonka Herra, Jumalasi, antaa sinulle perintöosaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'vaan että minä kuolen tässä maassa enkä mene Jordanin yli. Mutta te menette sen yli ja otatte tuon hyvän maan omaksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Niin varokaa, ettette unohda Herran, Jumalanne, liittoa, jonka hän on tehnyt kanssanne, ettekä tee itsellenne jumalankuvaa, ette mitään sen muotoista kuvaa, jota Herra, Jumalasi, on kieltänyt sinua tekemästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Sillä Herra, Jumalasi, on kuluttava tuli, kiivas Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Kun sitten sinulle on syntynyt lapsia ja lastenlapsia ja te olette vanhentuneet maassa, ja jos te silloin menettelette kelvottomasti ja teette itsellenne jumalankuvan, minkämuotoisen kuvan tahansa, ja siten teette sitä, mikä on pahaa Herran, Jumalasi, silmissä, ja vihoitatte hänet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'minä otan tänä päivänä taivaan ja maan todistajiksi teitä vastaan, että teidät äkkiä hävitetään siitä maasta, johon te menette Jordanin yli ottamaan sen omaksenne. Te ette saa kauan elää siellä, vaan teidät tuhotaan kokonaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Herra hajottaa teidät kansojen sekaan, ja ainoastaan vähäinen joukko teitä on jäävä niiden pakanakansojen keskelle, joiden luo Herra kuljettaa teidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Siellä te palvelette jumalia, jotka ovat ihmiskätten tekoa, puuta ja kiveä, jotka eivät näe eivätkä kuule, eivät syö eivätkä hajua tunne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Mutta sitten sinä siellä etsit Herraa, Jumalaasi, ja sinä löydät hänet, kun kysyt häntä kaikesta sydämestäsi ja kaikesta sielustasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Kun olet ahdistuksessa ja kaikki tämä kohtaa sinua aikojen lopussa, niin sinä palaat Herran, Jumalasi, luo ja kuulet hänen ääntään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Sillä Herra, Jumalasi, on laupias Jumala. Hän ei jätä sinua eikä hukuta sinua. Hän ei unohda isiesi kanssa tekemäänsä liittoa, jonka hän on heille valalla vahvistanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Sillä kysy menneiltä ajoilta, jotka ovat olleet ennen sinua, alkaen siitä päivästä, jona Jumala loi ihmiset maan päälle, kysy taivaan äärestä toiseen, että onko koskaan mitään näin suurta tapahtunut tai onko mitään tällaista ikinä kuultu?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Onko mikään kansa kuullut Jumalan äänen puhuvan tulen keskeltä, niin kuin sinä olet kuullut, ja kuitenkin jäänyt elämään?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Tai onko mikään jumala koettanut mennä ottamaan itselleen kansaa toisen kansan keskuudesta koettelemuksilla, tunnusteoilla ja ihmeillä, sodalla, väkevällä kädellä ja ojennetulla käsivarrella ja suurilla, pelottavilla teoilla, minkä kaiken Herra, teidän Jumalanne, on tehnyt teille Egyptissä, silmiesi edessä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Sinun on annettu se nähdä, tietääksesi, että Herra on Jumala, eikä muuta jumalaa ole kuin hän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Taivaasta hän antoi sinun kuulla äänensä opettaakseen sinua, ja maan päällä hän antoi sinun nähdä suuren tulensa, ja sinä kuulit hänen sanansa tulen keskeltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Koska hän siis rakasti isiäsi ja valitsi heidän jälkeläisensä itselleen ja itse suurella voimallaan vei sinut pois Egyptistä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'karkottaen tieltäsi kansoja, suurempia ja väkevämpiä kuin sinä, ja tuoden sinut heidän maahansa antaakseen sen sinulle perintöosaksi, niin kuin nyt on tapahtunut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'niin tiedä siis tänä päivänä ja paina se sydämeesi, että Herra on Jumala ylhäällä taivaassa ja alhaalla maan päällä, eikä muuta jumalaa ole');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Noudata hänen säädöksiään ja käskyjään, jotka minä tänä päivänä sinulle annan, että sinä ja lapsesi sinun jälkeesi menestyisitte ja että eläisit kauan siinä maassa, jonka Herra, Jumalasi, antaa sinulle ikiajoiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Silloin Mooses erotti kolme kaupunkia tuolta puolelta Jordanin, auringon nousun puolelta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'että niihin voisi paeta tappaja, joka on tappanut toisen tahtomattaan ja häntä ennestään vihaamatta. Paetkoon sellainen johonkin näistä kaupungeista, niin hän saa elää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Ne olivat: ruubenilaisille Beser erämaassa, ylätasangolla, gaadilaisille Raamot Gileadissa ja manasselaisille Goolan Baasanissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Tämä on se laki, jonka Mooses antoi israelilaisille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'ja nämä ovat ne todistukset, käskyt ja oikeudet, jotka Mooses julisti israelilaisille, heidän lähdettyään Egyptistä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'tuolla puolella Jordanin laaksossa vastapäätä Beet-Peoria Siihonin, amorilaisten kuninkaan, maassa, hänen, joka asui Hesbonissa ja jonka Mooses ja israelilaiset voittivat lähdettyään Egyptistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'He ottivat omakseen hänen maansa ja Oogin, Baasanin kuninkaan, maan, kahden amorilaisten kuninkaan maat, jotka ovat Jordanin tuolla puolella, auringon nousun suuntaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'alkaen Aroerista, joka on Arnon-joen rannalla, aina Sirjonin vuoreen, se on Hermoniin, saakka,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'sekä koko Aromaan, Jordanin tuolla puolella, idän puolella, aina Kuolleeseen mereen saakka, Pisgan rinteiden juurelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Sitten Mooses kutsui kokoon koko Israelin ja sanoi heille: \"Kuule, Israel, nämä käskyt ja oikeudet, jotka minä tänä päivänä julistan teidän korvienne kuullen, oppikaa ne ja noudattakaa niitä tarkasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Herra, Jumalamme, teki liiton kanssamme Hoorebilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Herra ei tehnyt tätä liittoa isiemme kanssa, vaan meidän kanssamme, jotka olemme tässä tänä päivänä, kaikkien meidän kanssa, jotka nyt elämme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Kasvoista kasvoihin Herra puhui teidän kanssanne vuorelta, tulen keskeltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'Minä seisoin silloin Herran ja teidän välillänne ja ilmoitin teille Herran sanan, sillä te pelkäsitte tulta ettekä nousseet vuorelle. Hän sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, '\'Minä olen Herra, Jumalasi, joka vein sinut pois Egyptin maasta, orjuuden pesästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Älä pidä muita jumalia minun rinnallani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Älä tee itsellesi jumalankuvaa, älä mitään kuvaa, älä niistä, jotka ovat ylhäällä taivaassa, älä niistä, jotka ovat alhaalla maan päällä, äläkä niistä, jotka ovat vesissä maan alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Älä kumarra niitä äläkä palvele niitä. Sillä minä, Herra, Jumalasi, olen kiivas Jumala, joka kostan isien pahat teot lapsille kolmanteen ja neljänteen polveen, niille, jotka minua vihaavat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'mutta teen laupeuden tuhansille, jotka minua rakastavat ja pitävät minun käskyni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Älä lausu turhaan Herran, Jumalasi, nimeä, sillä Herra ei jätä rankaisematta sitä, joka lausuu turhaan hänen nimensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Ota vaari lepopäivästä, niin että sen pyhität, niin kuin Herra, Jumalasi, on sinua käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Kuusi päivää tee työtä ja toimita kaikki askareesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Mutta seitsemäs päivä on Herran, Jumalasi, sapatti. Silloin älä mitään askaretta toimita, älä sinä älköön myöskään poikasi tai tyttäresi, palvelijasi tai palvelijattaresi, härkäsi, aasisi tai muu juhtasi älköönkä muukalaisesi, joka on porteissasi, että palvelijasi ja palvelijattaresi saisivat levätä niin kuin sinäkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Muista, että itse olit orjana Egyptin maassa ja että Herra, Jumalasi, vei sinut sieltä pois väkevällä kädellä ja ojennetulla käsivarrella. Sen tähden Herra, Jumalasi, käski sinun viettää lepopäivän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Kunnioita isääsi ja äitiäsi, niin kuin Herra, Jumalasi, on sinua käskenyt, että kauan eläisit ja menestyisit siinä maassa, jonka Herra, Jumalasi, sinulle antaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Älä tapa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Älä tee huorin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Älä varasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Älä sano väärää todistusta lähimmäisestäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Älä himoitse lähimmäisesi vaimoa. Älä himoitse itsellesi lähimmäisesi huonetta, älä hänen peltoaan, älä hänen palvelijaansa, palvelijatartaan, härkäänsä, aasiaan, äläkä mitään, mikä on lähimmäisesi omaa.\'.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Nämä sanat Herra puhui koko teidän seurakunnallenne vuorelta, tulen ja synkkien pilvien keskeltä, suurella äänellä, eikä siihen enempää lisännyt. Hän kirjoitti ne kahteen kivitauluun ja antoi ne minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Kun te kuulitte äänen pimeyden keskeltä, vuoren palaessa tulena, niin te astuitte luokseni, kaikki teidän sukukuntienne päämiehet, niin myös teidän vanhimpanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'Te sanoitte: \'Katso, Herra, Jumalamme, on antanut meidän nähdä kirkkautensa ja valtasuuruutensa, ja me olemme kuulleet hänen äänensä tulen keskeltä. Tänä päivänä olemme nähneet, että Jumala voi puhua ihmisen kanssa, ja tämä jää kuitenkin henkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Miksi meidän on siis kuoleminen? Sillä tämä suuri tuli kuluttaa meidät. Jos me vielä kuulemme Herran, Jumalamme, äänen, niin me kuolemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Sillä kuka kaikesta lihasta koskaan on niin kuin me kuullut elävän Jumalan äänen puhuvan tulen keskeltä ja jäänyt henkiin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Astu siis esiin ja kuule kaikki, mitä Herra, Jumalamme, sanoo. Puhu sinä meille kaikki, mitä Herra, Jumalamme, sinulle puhuu, niin kuulemme ja teemme.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Herra kuuli puheenne, kun te puhuitte minulle, ja Herra sanoi minulle: \'Minä olen kuullut, mitä tämä kansa on puhunut sinulle. Kaikki, mitä he ovat puhuneet, on oikein puhuttu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Jospa heillä olisi sellainen sydän, että he alati pelkäisivät minua ja noudattaisivat kaikkia käskyjäni, niin he ja heidän lapsensa menestyisivät iankaikkisesti!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Mene siis ja sano heille: Palatkaa majoillenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Mutta jää sinä tähän minun eteeni, niin minä puhun sinulle kaikki ne käskyt, säädökset ja oikeudet, jotka sinun on opetettava heille, että he seuraisivat niitä siinä maassa, jonka minä annan heille omaksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Niin noudattakaa siis tarkasti niitä, niin kuin Herra, teidän Jumalanne, on teitä käskenyt. Älkää poiketko oikealle älkääkä vasemmalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'vaan vaeltakaa aina sitä tietä, jota Herra, teidän Jumalanne, käski teidän vaeltaa, että eläisitte, menestyisitte ja elinpäivänne olisivat pitkät siinä maassa, jonka otatte omaksenne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, '\"Nämä ovat ne käskyt, säädökset ja oikeudet, jotka Herra, teidän Jumalanne, on käskenyt teille opettaa, että seuraisitte niitä siinä maassa, jota menette ottamaan omaksenne');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'ja että sinä pelkäisit Herraa, Jumalaasi, ja noudattaisit kaikkia hänen säädöksiään ja käskyjään, jotka minä sinulle annan, sekä sinä että poikasi ja poikasi poika, kaikkena elinaikanasi, ja että saisit kauan elää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Niin kuule siis, Israel, ja noudata tarkasti niitä, että niin kuin Herra, isiesi Jumala, on sinulle luvannut, menestyisit ja te lisääntyisitte suuresti siinä maassa, joka vuotaa maitoa ja hunajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Kuule, Israel! Herra, Jumalamme, Herra on yksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Rakasta Herraa, Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi ja kaikesta voimastasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Nämä sanat, jotka minä tänä päivänä sinulle annan, painukoot sydämeesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'Teroita niitä lastesi mieleen ja puhu niistä kotona istuessasi ja tietä käydessäsi, maata pannessasi ja ylös noustessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Sido ne merkiksi käteesi. Olkoot ne muistolauseena otsallasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Kirjoita ne talosi pihtipieliin ja portteihisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'Kun Herra, Jumalasi, on vienyt sinut siihen maahan, jonka hän isillesi, Aabrahamille, Iisakille ja Jaakobille, vannotulla valalla on luvannut antaa sinulle – suuret ja kauniit kaupungit, joita sinä et ole rakentanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'ja talot, täynnä kaikkea hyvää, joita sinä et ole täyttänyt, ja kallioon hakatut vesisäiliöt, joita sinä et ole hakannut, viinitarhat ja öljypuut, joita sinä et ole istuttanut. Kun olet syönyt ja olet ravittu,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'niin varo, ettet unohda Herraa, joka vei sinut pois Egyptin maasta, orjuuden pesästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Pelkää Herraa, Jumalaasi, ja palvele häntä ja vanno hänen nimeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Älkää kulkeko muiden jumalien perässä, niiden kansojen jumalien, jotka asuvat ympärillänne –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'sillä Herra, Jumalasi, on kiivas Jumala keskelläsi – ettei Herran, Jumalasi, viha syttyisi sinua vastaan ja hän hävittäisi sinua maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Älkää kiusatko Herraa, teidän Jumalaanne, niin kuin kiusasitte häntä Massassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'vaan noudattakaa Herran, Jumalanne, käskyjä ja niitä todistuksia ja säädöksiä, jotka hän on sinulle antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Tee, mikä on oikein ja hyvää Herran silmissä, että menestyisit ja pääsisit siihen hyvään maahan, jonka Herra valalla vannoen on luvannut isillesi, ja ottaisit sen omaksesi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'ja karkottaisit tieltäsi kaikki vihollisesi, niin kuin Herra on puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Kun poikasi vastaisuudessa kysyy sinulta ja sanoo: \'Mitä merkitsevät ne todistukset, säädökset ja oikeudet, jotka Herra, Jumalamme, on teille antanut?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'niin vastaa pojallesi: \'Me olimme faraon orjia Egyptissä, mutta väkevällä kädellä Herra vei meidät pois Egyptistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'Herra teki suuria ja tuhoisia tunnustekoja ja ihmeitä Egyptissä faraolle ja kaikelle hänen hoviväelleen silmiemme edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'mutta meidät hän vei sieltä pois ja johdatti meidät siihen maahan, jonka hän valalla vannoen oli luvannut isillemme, ja antoi sen meille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Herra käski meidän pitää kaikki nämä säädökset ja pelätä Herraa, Jumalaamme, että aina menestyisimme ja hän pitäisi meidät elossa, kuten on tapahtunut tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'On oleva meille vanhurskaudeksi, että noudatamme tarkasti kaikkia näitä käskyjä Herran, Jumalamme, edessä, kuten hän on meitä käskenyt.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, '\"Kun Herra, Jumalasi, vie sinut siihen maahan, jonka menet ottamaan omaksesi, ja kun hän karkottaa tieltäsi suuret kansat, heettiläiset, girgasilaiset, amorilaiset, kanaanilaiset, perissiläiset, hivviläiset ja jebusilaiset, nuo seitsemän kansaa, jotka ovat sinua suuremmat ja väkevämmät,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'ja kun Herra, Jumalasi, antaa ne sinulle alttiiksi ja sinä voitat ne, niin vihi heidät tuhon omiksi, älä tee liittoa heidän kanssaan äläkä osoita heille armoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Älä lankoudu heidän kanssaan. Älä anna tyttäriäsi heidän pojilleen äläkä ota heidän tyttäriään pojillesi vaimoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Sillä he viettelevät poikasi luopumaan minusta ja palvelemaan muita jumalia. Silloin Herran viha syttyy teitä kohtaan, ja hän hävittää sinut nopeasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Vaan tehkää heille näin: kukistakaa heidän alttarinsa, murskatkaa heidän patsaansa, hakatkaa maahan heidän aserapaalunsa ja polttakaa tulessa heidän jumalankuvansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Sillä sinä olet Herralle, Jumalallesi, pyhitetty kansa. Herra, Jumalasi, on valinnut sinut omaisuuskansakseen ennen kaikkia muita kansoja, mitä maan päällä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Ei Herra sen tähden ole mielistynyt teihin ja valinnut teitä, että olisitte lukuisammat kaikkia muita kansoja, sillä tehän olette kaikkia muita kansoja vähälukuisemmat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'vaan sen tähden, että Herra rakasti teitä ja tahtoi pitää valan, jonka hän oli vannonut isillenne. Niin Herra vei teidät pois väkevällä kädellä ja vapahti sinut orjuuden pesästä, faraon, Egyptin kuninkaan, käsistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Tiedä siis, että Herra, Jumalasi, on Jumala, uskollinen Jumala, joka pitää liiton ja on laupias tuhansiin polviin asti niille, jotka häntä rakastavat ja pitävät hänen käskynsä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'mutta kostaa sille, joka häntä vihaa, ja hukuttaa hänet. Hän ei vitkastele, vaan kostaa sille, joka häntä vihaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Noudata siis näitä käskyjä, säädöksiä ja oikeuksia, jotka minä tänä päivänä sinulle annan, ja pidä ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Jos te tottelette näitä säädöksiä, noudatatte ja seuraatte niitä, niin Herra, Jumalasi, pitää liittonsa ja on laupias sinulle, niin kuin hän valalla vannoen on isillesi luvannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'Hän rakastaa sinua, siunaa sinua ja antaa sinun lisääntyä. Hän siunaa kohtusi hedelmän ja maasi hedelmän. Hän siunaa viljasi, viinisi ja öljysi, nautojesi vasikat ja lampaittesi karitsat siinä maassa, jonka hän isillesi vannotulla valalla on luvannut antaa sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Siunattu olet sinä oleva yli kaikkien muiden kansojen. Hedelmätöntä miestä tai naista ei ole keskuudessasi oleva, eikä myöskään karjassasi ole yhtään hedelmätöntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Herra on poistava sinusta kaikki sairaudet. Hän ei ole paneva kärsittäväksesi ainoatakaan Egyptin kovista taudeista, jotka sinä tunnet, vaan hän antaa niiden tulla kaikkiin niihin, jotka sinua vihaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Tuhoa kaikki kansat, jotka Herra, Jumalasi, antaa sinulle. Älä heitä sääli. Älä myöskään palvele heidän jumaliaan, sillä se tulee sinulle ansaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Vaikka ajatteletkin sydämessäsi: \'Nämä kansat ovat minua suuremmat, kuinka voisin karkottaa ne\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'niin älä kuitenkaan pelkää niitä. Muista, mitä Herra, Jumalasi, teki faraolle ja kaikille egyptiläisille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'niitä suuria koettelemuksia, jotka näit omin silmin, ja niitä tunnustekoja ja ihmeitä ja sitä väkevää kättä ja ojennettua käsivartta, joilla Herra, Jumalasi, vei sinut pois. Samoin Herra, Jumalasi, on tekevä kaikille niille kansoille, joita sinä pelkäät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Niin, Herra, Jumalasi, lähettää heidän kimppuunsa herhiläisiä, kunnes ne, jotka ovat jäljellä ja ovat sinulta piiloutuneet, on hävitetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Älä heitä säikähdä, sillä Herra, Jumalasi, on keskelläsi, suuri ja pelottava Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Herra, Jumalasi, karkottaa nämä kansat tieltäsi vähitellen. Älä lopeta heitä yhtäkkiä, etteivät metsän pedot lisääntyisi vahingoksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Herra, Jumalasi, antaa heidät sinulle alttiiksi ja saattaa heidät suureen hämminkiin, kunnes he tuhoutuvat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'ja hän antaa heidän kuninkaansa käsiisi, ja sinä hävität heidän nimensä taivaan alta. Ei kukaan kestä edessäsi, vaan sinä tuhoat heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Heidän jumaliensa kuvat polttakaa tulessa. Älä himoitse hopeaa ja kultaa, joka niissä on, äläkä ota siitä itsellesi mitään, ettet joutuisi sen pauloihin, sillä se on Herralle, Jumalallesi, kauhistus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Äläkä vie noita kauhistuksia taloosi, ettet sinäkin samoin kuin ne joutuisi vihittäväksi tuhon omaksi. Katso ne inhottaviksi ja kauhistaviksi, sillä ne on vihitty tuhon omaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, '\"Pitäkää tarkasti kaikki käskyt, jotka minä tänä päivänä sinulle annan, että eläisitte ja lisääntyisitte ja pääsisitte ottamaan omaksenne sen maan, jonka Herra valalla vannoen on luvannut teidän isillenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Muista kaikki, mitä on tapahtunut sillä tiellä, jota Herra, Jumalasi, näinä neljänäkymmenenä vuotena on sinua kuljettanut erämaassa nöyryyttääkseen sinua ja koetellakseen sinua ja tietääkseen, mitä sydämessäsi on: tahdotko noudattaa hänen käskyjään vai et.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Hän nöyryytti sinua ja antoi sinun nähdä nälkää, ja hän antoi sinulle mannaa syödä, jota et ennen tuntenut ja jota eivät isäsikään tunteneet, opettaakseen sinut ymmärtämään, ettei ihminen elä ainoastaan leivästä, vaan että hän elää jokaisesta sanasta, joka Herran suusta lähtee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Vaatteesi eivät kuluneet yltäsi, eivätkä jalkasi turvonneet näinä neljänäkymmenenä vuotena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Tiedä siis sydämessäsi, että Herra, Jumalasi, kasvattaa sinua, niin kuin isä kasvattaa poikaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Noudata Herran, Jumalasi, käskyjä, vaella hänen teitään ja pelkää häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Sillä Herra, Jumalasi, vie sinut hyvään maahan, laaksoissa ja vuorilla vuotavien purojen, lähteiden ja syvien vesien maahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'vehnän ja ohran, viiniköynnöksen, viikunapuun ja granaattiomenapuun maahan, jalostetun öljypuun ja hunajan maahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'maahan, jossa sinun ei tarvitse syödä leipääsi puutteessa eikä nähdä mitään puutetta, maahan, jonka kivet ovat rautaa ja jonka vuorista voit louhia vaskea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Kun syöt ja tulet ravituksi, niin ylistä Herraa, Jumalaasi, siitä hyvästä maasta, jonka hän on antanut sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Varo, ettet unohda Herraa, Jumalaasi, ja muista noudattaa hänen käskyjään, oikeuksiaan ja säädöksiään, jotka minä tänä päivänä sinulle annan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Kun syöt ja tulet ravituksi, kun rakennat kauniita taloja ja asut niissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'kun karjasi ja lampaasi lisääntyvät ja kun hopeasi ja kultasi lisääntyvät ja kaikki, mitä sinulla on, lisääntyy,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'niin älköön sydämesi ylpistykö, äläkä unohda Herraa, Jumalaasi, joka vei sinut pois Egyptin maasta, orjuuden pesästä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'kuljetti sinua suuressa ja hirmuisessa, myrkyllisten käärmeiden ja skorpionien ja kuivien, vedettömien maiden erämaassa, vuodatti sinulle vettä kovasta kalliosta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'ja antoi erämaassa sinulle mannaa syödä, jota isäsi eivät tunteneet – nöyryyttääkseen ja koetellakseen sinua ja tehdäkseen lopuksi sinulle hyvää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Älä ajattele sydämessäsi: \'Oma voimani ja oman käteni väkevyys on hankkinut minulle tämän rikkauden\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'vaan muista, että Herra, Jumalasi, antaa sinulle voiman hankkia rikkautta pitääkseen liittonsa, jonka hän valalla vannoen teki isiesi kanssa, niin kuin tähän päivään saakka on tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Mutta jos sinä tosiaan unohdat Herran, Jumalasi, ja seuraat muita jumalia, palvelet niitä ja kumarrat niitä, niin vakuutan teille tänä päivänä, että te todella hukutte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Niin kuin ne kansat, jotka Herra hukuttaa tieltänne, niin tekin hukutte, kun ette kuulleet Herraa, teidän Jumalaanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, '\"Kuule, Israel! Sinä menet nyt Jordanin yli laskeaksesi valtasi alle kansoja, jotka ovat sinua suuremmat ja väkevämmät, ja suuria, taivaan tasalle varustettuja kaupunkeja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'anakilaisten suuren ja kookkaan kansan, jonka sinä tunnet ja josta olet kuullut sanottavan: \'Kuka kestää anakilaisten edessä?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Niin tiedä nyt, että Herra, Jumalasi, käy edelläsi kuin kuluttava tuli. Hän hävittää heidät ja nöyryyttää heidät edessäsi, ja sinä karkotat heidät ja hukutat heidät nopeasti, kuten Herra on sinulle puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Kun Herra, Jumalasi, työntää heidät tieltäsi, älä ajattele sydämessäsi näin: \'Vanhurskauteni tähden Herra on tuonut minut ottamaan tämän maan omakseni.\' Sillä näiden kansojen jumalattomuuden tähden Herra karkottaa heidät tieltäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Et sinä vanhurskautesi ja oikeamielisyytesi tähden pääse ottamaan heidän maataan omaksesi, vaan näiden kansojen jumalattomuuden tähden Herra, Jumalasi, karkottaa heidät edestäsi ja täyttääkseen, mitä Herra valalla vannoen on luvannut isillesi, Aabrahamille, Iisakille ja Jaakobille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Tiedä siis, ettei Herra, Jumalasi, vanhurskautesi tähden anna sinulle tätä hyvää maata omaksesi, sillä sinä olet niskurikansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Muista äläkä unohda, kuinka sinä erämaassa vihoitit Herran, Jumalasi. Siitä päivästä alkaen, jona sinä lähdit Egyptin maasta, aina siihen saakka, kun tulitte tähän paikkaan, te olette niskoitelleet Herraa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Myös Hoorebilla te vihoititte Herran, ja Herra vihastui teihin, että hän aikoi tuhota teidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Kun minä olin noussut vuorelle vastaanottamaan kivitaulut, sen liiton taulut, jonka Herra oli tehnyt kanssanne, olin vuorella neljäkymmentä päivää ja neljäkymmentä yötä syömättä ja juomatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Herra antoi minulle ne kaksi kivitaulua, joihin oli kirjoitettu Jumalan sormella, ja niissä oli kaikki ne sanat, jotka Herra oli puhunut teille vuorelta, tulen keskeltä, silloin kun seurakunta oli koolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Niiden neljänkymmenen päivän ja neljänkymmenen yön kuluttua Herra antoi minulle ne kaksi kivitaulua, liitontaulut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'Herra sanoi minulle: \'Nouse ja astu nopeasti täältä alas, sillä kansasi, jonka sinä veit pois Egyptistä, on tehnyt turmiollisen teon. Pian he poikkesivat siltä tieltä, jota minä käskin heidän vaeltaa. He tekivät itselleen valetun kuvan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Herra puhui minulle sanoen: \'Olen nähnyt, että tämä kansa on niskurikansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Anna minun olla, minä tuhoan heidät ja pyyhin pois heidän nimensä taivaan alta. Mutta sinusta minä teen väkevämmän ja lukuisamman kansan kuin se.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Silloin minä käännyin ja astuin alas vuorelta vuoren palaessa tulena, ja minulla oli käsissäni ne kaksi liitontaulua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Minä näin, että te olitte rikkoneet Herraa, Jumalaanne, vastaan. Te olitte tehneet itsellenne valetun vasikankuvan ja pian poikenneet siltä tieltä, jota Herra oli käskenyt teidän vaeltaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Silloin minä tartuin molempiin tauluihin ja heitin ne käsistäni ja murskasin ne teidän silmienne edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Heittäydyin Herran eteen ja olin, kuten edelliselläkin kerralla, neljäkymmentä päivää ja neljäkymmentä yötä syömättä ja juomatta, kaiken sen synnin tähden, jota te olitte tehneet, kun teitte sitä, mikä on pahaa Herran silmissä, ja vihoititte hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Sillä minä pelkäsin sitä vihaa ja kiivautta teitä vastaan, joka oli vallannut Herran, niin että hän aikoi tuhota teidät. Herra kuuli minua vielä silläkin kertaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Myös Aaroniin Herra vihastui niin suuresti, että hän aikoi tuhota hänet, ja minä rukoilin silloin myös Aaronin puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Sitten otin teidän tekemänne syntikuvatuksen, vasikan, ja poltin sen tulessa, löin sen palasiksi ja rouhensin sen hienoksi, aivan kuin tuhkaksi, ja heitin tuhkan puroon, joka juoksi vuorelta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Tabeerassa, Massassa ja Kibrot-Hattavassa te vielä vihoititte Herran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Kun Herra tahtoi lähettää teidät Kaades-Barneasta ja sanoi: \'Menkää ja ottakaa omaksenne se maa, jonka minä teille annan\', te niskoittelitte Herran, Jumalanne, käskyä vastaan ettekä uskoneet häntä ettekä kuulleet hänen ääntään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Olette niskoitelleet Herraa, Jumalaanne, vastaan aina siitä päivästä alkaen, jona opin teidät tuntemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Heittäydyin Herran eteen ja olin siinä neljäkymmentä päivää ja neljäkymmentä yötä. Sillä Herra oli sanonut aikovansa tuhota teidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Rukoilin Herraa ja sanoin: Herra, Herra, älä tuhoa kansaasi ja perintöosaasi, jonka sinä suuruudessasi vapahdit ja jonka sinä veit pois Egyptistä väkevällä kädellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Muista palvelijoitasi Aabrahamia, Iisakia ja Jaakobia, älä katso tämän kansan uppiniskaisuutta, jumalattomuutta ja syntiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'ettei sanottaisi siinä maassa, josta sinä veit meidät pois: \'Koska Herra ei kyennyt viemään heitä siihen maahan, jonka hän oli heille luvannut, ja koska hän vihasi heitä, hän vei heidät täältä pois surmatakseen heidät erämaassa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Ovathan he sinun kansasi ja perintöosasi, jonka veit sieltä pois suurella voimallasi ja ojennetulla käsivarrellasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, '\"Silloin Herra sanoi minulle: \'Veistä itsellesi kaksi kivitaulua, entisten kaltaista, ja nouse vuorelle luokseni. Tee myös itsellesi puusta arkki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'Minä kirjoitan niihin tauluihin ne sanat, jotka olivat entisissä tauluissa, niissä, jotka sinä murskasit. Pane ne arkkiin.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Minä tein arkin akasiapuusta ja veistin kaksi kivitaulua, entisten kaltaista, ja nousin vuorelle, kädessäni nuo kaksi taulua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Hän kirjoitti tauluihin saman, minkä edellisellä kerralla, ne kymmenen sanaa, jotka Herra oli puhunut teille vuorelta, tulen keskeltä, seurakunnan kokouspäivänä. Herra antoi ne minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Sitten käännyin ja astuin alas vuorelta ja panin taulut tekemääni arkkiin, niin kuin Herra oli minua käskenyt, ja siinä ne ovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Israelilaiset lähtivät liikkeelle Bene-Jaakanin kaivoilta ja vaelsivat Mooseraan. Aaron kuoli siellä, ja hänet haudattiin sinne. Hänen poikansa Eleasar tuli papiksi hänen sijaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Sieltä he lähtivät liikkeelle Gudgodaan, ja Gudgodasta Jotbataan, seutuun, jossa on vesipuroja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Siihen aikaan Herra erotti Leevin sukukunnan kantamaan Herran liitonarkkia, seisomaan Herran edessä, palvelemaan häntä ja siunaamaan hänen nimeensä, kuten tähän päivään asti on tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Sen tähden Leevi ei saanut osuutta eikä perintöosaa veljiensä rinnalla, sillä Herra on hänen perintöosansa, kuten Herra, Jumalasi, on hänelle puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Minä viivyin vuorella, niin kuin edelliselläkin kerralla, neljäkymmentä päivää ja neljäkymmentä yötä. Herra kuuli minua vielä silläkin kerralla, sillä Herra ei tahtonut tuhota sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Herra sanoi minulle: \'Nouse ja lähde, kulje kansan edellä, että he menevät ja ottavat omakseen maan, jonka heidän isilleen vannotulla valalla olen luvannut antaa heille.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Nyt, Israel, mitä Herra, Jumalasi, sinulta muuta vaatii, kuin että pelkäät Herraa, Jumalaasi, että aina vaellat hänen teitään ja rakastat häntä, ja että palvelet Herraa, Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'noudattaen Herran käskyjä ja säädöksiä, jotka minä sinulle tänä päivänä annan, että menestyisit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Katso, taivaat ja taivasten taivaat, maa ja kaikki, mitä siinä on, ovat Herran, Jumalasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Mutta ainoastaan isiisi Herra mielistyi ja rakasti heitä. Hän valitsi omikseen heidän jälkeläisensä, hän valitsi teidät kaikista kansoista, niin kuin yhä vielä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Ympärileikatkaa sen tähden sydämenne älkääkä enää olko niskureita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Sillä Herra, teidän Jumalanne, on jumalien Jumala ja herrain Herra, suuri, voimallinen ja pelottava Jumala, joka ei katso henkilöön eikä ota lahjusta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'joka hankkii orvolle ja leskelle oikeuden ja joka rakastaa muukalaista ja antaa hänelle ruuan ja vaatetuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Sen tähden rakastakaa muukalaista, sillä te olette itse olleet muukalaisina Egyptin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Herraa, Jumalaasi, pelkää, häntä palvele, hänessä riipu kiinni ja vanno hänen nimeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Hän on ylistyksesi, ja hän on Jumalasi, joka on tehnyt sinulle nuo suuret ja pelottavat teot, jotka silmäsi ovat nähneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Seitsemänkymmentä henkeä oli isiesi joukkoa, kun he menivät Egyptiin, mutta nyt Herra, Jumalasi, on tehnyt lukusi paljoksi kuin taivaan tähdet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, '\"Rakasta siis Herraa, Jumalaasi, ja noudata alati hänen määräyksiään, säädöksiään, oikeuksiaan ja käskyjään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Tietäkää tänä päivänä, etten puhu teidän lapsillenne, jotka eivät ole kokeneet eivätkä nähneet Herran, Jumalanne, kuritusta, hänen suuruuttaan, väkevää kättään ja ojennettua käsivarttaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'eivät hänen tunnustekojaan ja töitään, jotka hän teki Egyptissä faraolle, Egyptin kuninkaalle, ja koko hänen maalleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'eivätkä sitä, mitä hän teki egyptiläisten sotajoukolle, heidän hevosilleen ja vaunuilleen, joiden päälle hän vyörytti Kaislameren vedet, kun he ajoivat teitä takaa, ja jotka Herra hukutti, niin ettei heitä enää ole,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'eivätkä, mitä hän teki teille erämaassa, aina siihen saakka, kunnes te tulitte tähän paikkaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'eivätkä, mitä hän teki Daatanille ja Abiramille, Eliabin, Ruubenin pojan pojille, kun maa avasi kitansa ja nielaisi koko Israelin keskeltä heidät ja heidän perheensä ja telttamajansa ja kaiken, mitä heillä oli mukanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Vaan minä puhun teille, jotka olette omin silmin nähneet kaikki Herran suuret teot, jotka hän on tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Pitäkää kaikki käskyt, jotka minä tänä päivänä teille annan, että tulisitte voimakkaiksi, menisitte ja ottaisitte omaksenne sen maan, jota nyt menette ottamaan omaksenne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'ja että eläisitte kauan siinä maassa, jonka Herra teidän isillenne vannotulla valalla on luvannut antaa heille ja heidän jälkeläisilleen, maan, joka vuotaa maitoa ja hunajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Sillä maa, jota sinä menet ottamaan omaksesi, ei ole kuin Egyptin maa, josta te olette lähteneet ja jota siemenesi siihen kylvettyäsi jalalla polkien kastelit kuin vihannestarhaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Vaan se maa, jota te menette ottamaan omaksenne, on maa, jossa on vuoria ja laaksoja ja joka juo vettä taivaan sateesta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'maa, josta Herra, Jumalasi, pitää huolen ja jota Herran, Jumalasi, silmät tarkastelevat alati, vuoden alusta sen loppuun saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Jos nyt todella tottelette käskyjäni, jotka minä tänä päivänä teille annan, että rakastatte Herraa, teidän Jumalaanne, ja palvelette häntä kaikesta sydämestänne ja kaikesta sielustanne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'annan teidän maallenne sateen ajallaan, syyssateen ja kevätsateen, ja saat korjata viljasi ja viinisi ja öljysi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Annan karjallesi ruohoa kedoillesi, että saat syödä ja tulet ravituksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Varokaa, ettei sydämenne antaudu vieteltäväksi, että poikkeatte pois ja palvelette muita jumalia ja kumarratte niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Muuten Herran viha syttyy teitä kohtaan, ja hän sulkee taivaan, niin ettei tule sadetta eikä maa anna satoaan, ja te häviätte pian siitä hyvästä maasta, jonka Herra antaa teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Painakaa siis nämä sanani sydämeenne ja mieleenne ja sitokaa ne merkiksi käteenne, ja ne olkoot muistolauseena otsallanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Opettakaa ne lapsillenne, että puhut niistä kotona istuessasi ja tietä käydessäsi, maata pannessasi ja ylös noustessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Kirjoita ne talosi pihtipieliin ja portteihisi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'että te ja teidän lapsenne kauan eläisitte siinä maassa, jonka Herra teidän isillenne vannotulla valalla lupasi antaa heille, niin kauan kuin taivas on maan yllä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Sillä jos pidätte kaikki nämä käskyt, jotka minä teille annan, ja seuraatte niitä, että rakastatte Herraa, teidän Jumalaanne, ja aina vaellatte hänen teitään ja riiputte hänessä kiinni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'Herra karkottaa kaikki nämä kansat tieltänne, ja te laskette valtanne alle kansoja, jotka ovat teitä suuremmat ja väkevämmät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Mihin paikkaan te jalallanne astutte, se on oleva teidän. Erämaasta ja Libanonista, virrasta, Eufrat-virrasta, aina Länsimereen saakka on teidän alueenne ulottuva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Ei kukaan kestä edessänne. Kauhuun ja pelästykseen edessänne on Herra saattava koko sen maan, johon astutte, kuten hän on teille puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Katso, minä asetan tänä päivänä eteenne siunauksen ja kirouksen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'siunauksen, jos te tottelette Herran, Jumalanne, käskyjä, jotka minä tänä päivänä teille annan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'mutta kirouksen, jos ette tottele Herran, Jumalanne, käskyjä, vaan poikkeatte siltä tieltä, jota minä tänä päivänä käsken teidän vaeltaa, ja seuraatte muita jumalia, joita ette tunne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Kun Herra, Jumalasi, on vienyt sinut siihen maahan, jota nyt menet ottamaan omaksesi, niin tee Garissimin vuoresta siunauksen paikka ja Eebalin vuoresta kirouksen paikka.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Ne ovat toisella puolella Jordanin, länteen auringonlaskun tiestä, kanaanilaisten maassa, niiden, jotka asuvat Aromaassa, vastapäätä Gilgalia, Mooren tammiston luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, '\"Sillä te kuljette Jordanin yli ja menette ottamaan omaksenne maan, jonka Herra, teidän Jumalanne, teille antaa. Kun sitten olette ottaneet sen omaksenne ja asettuneet siihen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'noudattakaa tarkasti kaikkia niitä käskyjä ja oikeuksia, jotka minä tänä päivänä teille annan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, '\"Nämä ovat ne käskyt ja oikeudet, joita teidän on tarkasti noudatettava siinä maassa, jonka Herra, isiesi Jumala, sinulle antaa, että ottaisit sen omaksesi. [Sinun on] noudatettava [niitä] niin kauan kuin elätte maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Hävittäkää perin pohjin kaikki ne paikat, missä karkottamanne kansat ovat jumaliaan palvelleet, korkeilla vuorilla, kukkuloilla tai vihreiden puiden alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Kukistakaa heidän alttarinsa, murskatkaa heidän patsaansa, polttakaa tulessa heidän aserapaalunsa ja hakatkaa maahan heidän jumaliensa kuvat, ja hävittäkää heidän nimensä niistä paikoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Palvellessanne Herraa, teidän Jumalaanne, älkää tehkö niin kuin he,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'vaan se paikka, jonka Herra, teidän Jumalanne, valitsee teidän sukukuntienne alueelta ja johon hän asettaa nimensä asuakseen siellä, se etsikää, niin sinä tulet sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'Viekää sinne polttouhrinne ja teurasuhrinne, kymmenyksenne, kätenne anti, lupausuhrinne ja vapaaehtoiset uhrinne sekä nautojenne ja lampaittenne esikoiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Syökää siellä Herran, Jumalanne, edessä, ja iloitkaa perheinenne kaikesta, mitä kätenne on hankkinut, millä Herra, Jumalasi, on sinua siunannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Älkää tehkö, niin kuin me tässä tänä päivänä teemme, älköön jokainen tehkö sitä, mikä hänen omasta mielestään on oikein,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'sillä te ette vielä ole päässeet lepoon ettekä sille perintömaalle, jonka Herra, Jumalasi, on sinulle antava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Mutta kun olette menneet Jordanin yli ja asettuneet siihen maahan, jonka Herra, teidän Jumalanne, jakaa teille perinnöksi, ja kun hän on suonut teidän päästä rauhaan kaikista vihollisistanne joka taholta, niin että asutte turvassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'silloin viekää siihen paikkaan, jonka Herra, Jumalanne, valitsee nimensä asuinpaikaksi, kaikki, mitä minä käsken teidän viedä: polttouhrinne ja teurasuhrinne, kymmenyksenne, kätenne anti, niin myös kaikki parhaat lupausuhrinne, jotka te lupaatte Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Iloitkaa Herran, Jumalanne, edessä, sekä te että teidän poikanne ja tyttärenne, palvelijanne ja palvelijattarenne, ja leeviläiset, jotka asuvat teidän porttienne sisäpuolella, sillä heillä ei ole osuutta eikä perintöosaa teidän rinnallanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Varo, ettet uhraa polttouhrejasi missä tahansa mieleisessäsi paikassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'vaan siinä paikassa, jonka Herra valitsee jonkin sukukuntasi alueelta. Siinä uhraa polttouhrisi ja tee kaikki, mitä minä käsken sinun tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Kuitenkin saat kaikkialla porttiesi sisäpuolella teurastaa mielin määrin ja syödä lihaa, sen mukaan kuin Herra, Jumalasi, sinulle siunaa. Sekä saastainen että puhdas saakoon syödä sitä, niin kuin syödään gasellia tai peuraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Vain verta älkää syökö, vuodattakaa se maahan kuin vesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Sinä et saa omien porttiesi sisäpuolella syödä jyviesi, viinisi ja öljysi kymmenyksiä etkä myöskään nautojesi ja lampaittesi esikoisia etkä mitään lupaamaasi lupausuhria, vapaaehtoisia uhreja tai kätesi antia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'vaan syö niitä Herran, Jumalasi, edessä siinä paikassa, jonka Herra, Jumalasi, valitsee, sekä sinä että poikasi ja tyttäresi, palvelijasi ja palvelijattaresi ja leeviläinen, joka asuu porttiesi sisäpuolella. Iloitse näin Herran, Jumalasi, edessä kaikesta, mitä kätesi on hankkinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Varo, ettet jätä osattomaksi leeviläistä, niin kauan kuin sinä elät maassasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Kun Herra, Jumalasi, on laajentanut alueesi, niin kuin hän on sinulle luvannut, ja sinä ajattelet: \'Minä tahdon syödä lihaa\' – koska haluat syödä lihaa – niin syö lihaa mielin määrin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Jos se paikka, jonka Herra, Jumalasi, valitsee asettaakseen siihen nimensä, on liian kaukana sinusta, niin teurasta, niin kuin olen sinua käskenyt, nautojasi ja lampaitasi, joita Herra on sinulle antanut, ja syö niitä porttiesi sisäpuolella mielin määrin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Mutta syö niitä, niin kuin syödään gasellia ja peuraa. Yhtä hyvin saastainen kuin puhdas saakoon syödä niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Ole vain luja siinä, ettet syö verta. Sillä sen veri on sen henki, ja henkeä sinun ei pidä syödä lihan kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Älä syö sitä. Vuodata se maahan kuin vesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Älä syö sitä, että menestyisit, sinä ja sinun lapsesi sinun jälkeesi, kun teet, mikä on oikeaa Herran silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Mutta pyhät lahjasi, jotka sinä tuot, sekä lupausuhrisi, ota ja vie siihen paikkaan, jonka Herra on valinnut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'Uhraa polttouhrisi, sekä liha että veri, Herran, Jumalasi, alttarilla. Teurasuhreistasi vuodatettakoon veri Herran Jumalasi, alttarille, mutta lihan saat syödä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Noudata ja tottele kaikkia näitä sanoja, jotka minä sinulle annan, että menestyisit, sinä ja sinun lapsesi jälkeesi, ikuisesti, kun teet sitä, mikä on hyvää ja oikeaa Herran, Jumalasi, silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Kun Herra, Jumalasi, on hävittänyt ne kansat, joita menet karkottamaan tieltäsi, ja kun olet karkottanut heidät ja asettunut heidän maahansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'varo, sitten kun he ovat hävitetyt tieltäsi, ettet kietoudu heidän ansoihinsa seuraamaan heitä. [Varo,] ettet etsi heidän jumaliaan ja kysy: \'Miten näiden kansojen tapana oli palvella jumaliaan, että minäkin tekisin niin?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Älä tee niin Herraa, Jumalaasi, kohtaan, sillä kaikkea, mikä on Herralle kauhistus ja mitä hän vihaa, he ovat tehneet palvellessaan jumaliaan: omia poikiansakin ja tyttäriään he ovat jumalilleen polttaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Kaikkea, mitä minä käsken, noudattakaa tarkasti. Älkää lisätkö siihen mitään älkääkä ottako siitä mitään pois.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, '\"Jos teidän keskuuteenne ilmestyy profeetta tai unennäkijä ja lupaa sinulle jonkin tunnusteon tai ihmeen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'ja jos sitten todellakin tapahtuu se tunnusteko tai ihme, josta hän puhui sinulle sanoen: \'Lähtekäämme seuraamaan muita jumalia, joita te ette tunne, ja palvelkaamme niitä\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'niin älä kuuntele sen profeetan puhetta tai sitä unennäkijää, sillä Herra, teidän Jumalanne, ainoastaan koettelee teitä tietääkseen, rakastatteko Herraa, teidän Jumalaanne, kaikesta sydämestänne ja kaikesta sielustanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Seuratkaa Herraa, teidän Jumalaanne, häntä pelätkää ja pitäkää hänen käskynsä, häntä kuulkaa, häntä palvelkaa ja riippukaa hänessä kiinni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Mutta se profeetta tai unennäkijä surmattakoon, sillä hän on julistanut luopumusta Herrasta, teidän Jumalastanne, joka vei teidät pois Egyptin maasta ja vapahti sinut orjuuden pesästä, ja on tahtonut vietellä sinut siltä tieltä, jota Herra, Jumalasi, käski sinun vaeltaa. Poista paha keskuudestasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'Jos veljesi, äitisi poika, poikasi, tyttäresi, vaimo, joka on sylissäsi, tai ystäväsi, joka on sinulle kuin oma sielusi, salaa houkuttelisi sinua ja sanoisi: \'Käykäämme palvelemaan muita jumalia\', joita sinä et tunne eivätkä isäsi tunteneet –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'niiden kansojen jumalia, jotka asuvat teidän ympärillänne, lähellä sinua tai kaukana sinusta, maan äärestä toiseen –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'niin älä noudata hänen mieltään äläkä kuule häntä. Älä sääli äläkä armahda häntä äläkä salaa hänen rikostaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'vaan tapa hänet: oma kätesi kohotkoon ensimmäisenä häntä vastaan surmatakseen hänet, ja sitten koko kansan käsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Kivitä hänet kuoliaaksi, sillä hän koetti saada sinut luopumaan Herrasta, Jumalastasi, joka vei sinut pois Egyptin maasta, orjuuden pesästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Koko Israel kuulkoon sen ja pelätköön, ettei kukaan enää tekisi sellaista pahaa keskuudessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Jos sinä kuulet sanottavan, että jossakin kaupungeistasi, jotka Herra, Jumalasi, antaa sinun asuttaviksesi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'keskuudestasi on lähtenyt kelvottomia miehiä, jotka viettelevät kaupunkinsa asukkaita sanoen: \'Käykäämme palvelemaan muita jumalia\', joita ette tunne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'niin tutki, tiedustele ja kysele tarkasti. Jos on totta ja varmaa, että sellaista kauhistusta on harjoitettu keskuudessasi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'niin surmaa kaupungin asukkaat miekan terällä ja vihi tuhon omaksi se ja kaikki, mitä siinä on, ja tapa sen karjakin miekan terällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Kokoa kaikki siitä otettu saalis keskelle sen toria ja polta tulella sekä kaupunki että kaikki siitä otettu saalis kokonaisuhrina Herralle, Jumalallesi. Jääköön se rauniokummuksi ikuisesti, älköönkä sitä koskaan enää rakennettako.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Älköön tuhon omaksi vihitystä tarttuko mitään käsiisi, että Herra kääntyisi pois vihansa hehkusta, antaisi sinulle armon ja armahtaisi sinua ja sallisi sinun lisääntyä, niin kuin hän on vannonut isillesi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 19, 'jos sinä vain kuulet Herran, Jumalasi ääntä ja pidät kaikki hänen käskynsä, jotka minä tänä päivänä sinulle annan, ja teet sitä, mikä on oikein Herran, Jumalasi, silmissä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, '\"Te olette Herran, Jumalanne, lapsia. Älkää viileskelkö ihoanne älkääkä ajako paljaaksi päätänne otsapuolelta vainajan tähden,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'sillä sinä olet Herralle, Jumalallesi, pyhitetty kansa, ja Herra on valinnut sinut omaisuuskansakseen ennen kaikkia muita kansoja, mitä maan päällä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Älä syö mitään, mikä on kauhistus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Nämä ovat ne nelijalkaiset eläimet, joita saatte syödä: nauta, lammas ja vuohi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'peura, gaselli, metsäkauris, vuorikauris, musta antilooppi, keihäsantilooppi ja betsoari-vuohi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'kaikkia niitä nelijalkaisia eläimiä, joilla on kokonaan halkinaiset, kaksivarpaiset sorkat ja jotka märehtivät, saatte syödä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Näitä älkää kuitenkaan syökö märehtivistä ja niistä, joilla on kokonaan halkinaiset sorkat: kamelia, jänistä ja tamaania, jotka kyllä märehtivät, mutta joilla ei ole sorkkia. Olkoot ne teille saastaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Älkää syökö sikaa, jolla kyllä on sorkat, mutta joka ei märehdi. Se olkoon teille saastainen. Näiden lihaa älkää syökö älkääkä koskeko niiden raatoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Näitä saatte syödä kaikista vesieläimistä: kaikkia, joilla on evät ja suomukset, saatte syödä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Mutta mitään niistä, joilla ei ole eviä eikä suomuksia, älkää syökö. Ne olkoot teille saastaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Kaikkia puhtaita lintuja saatte syödä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Nämä ovat linnuista ne, joita älkää syökö: kotka, partakorppikotka, harmaa korppikotka,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'haarahaukka ja suohaukkalajit,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'kaikki korppilajit,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'strutsi, pääskynen, kalalokki, jalohaukkalajit,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'huuhkaja, kissapöllö, sarvipöllö,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'pelikaani, lihakorppikotka, kalasääski,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'haikara, sirriäislajit, harjalintu ja lepakko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Kaikki siivelliset pikkueläimet olkoot teille myös saastaisia, niitä älköön syötäkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Kaikkia puhtaita siivellisiä te saatte syödä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Älkää syökö mitään itsestään kuollutta. Muukalaiselle, joka on porteissasi, saat antaa sitä syötäväksi, tai myy se vieraalle, sillä sinä olet Herralle, Jumalallesi, pyhitetty kansa. Älä keitä kiliä emänsä maidossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Kaikesta kylvösi sadosta, joka kasvaa pellollasi, anna joka vuosi kymmenykset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'ja syö ne Herran, Jumalasi, edessä, siinä paikassa, jonka hän valitsee nimensä asuinpaikaksi: kymmenykset jyvistäsi, viinistäsi ja öljystäsi, niin myös nautojesi ja lampaittesi esikoiset, että oppisit pelkäämään Herraa, Jumalaasi, koko elinaikasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Mutta jos tie on sinulle liian pitkä, niin ettet voi kantaa kannettavaasi, koska se paikka, jonka Herra, Jumalasi, on valinnut asettaakseen siihen nimensä, on sinulle liian kaukana, – sillä Herra, Jumalasi, on sinua siunaava –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'niin muuta se rahaksi, pane raha kääröön, ota käteesi ja mene siihen paikkaan, jonka Herra, Jumalasi, valitsee,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'ja osta rahalla kaikkea, mitä haluat, joko nautoja tai lampaita, viiniä tai väkijuomaa, kaikkea, mitä mielesi tekee, ja syö siellä Herran, Jumalasi, edessä ja iloitse, sinä ja perheesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Äläkä jätä osattomaksi leeviläistä, joka asuu porttiesi sisäpuolella, sillä hänellä ei ole osuutta eikä perintöosaa rinnallasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Joka kolmas vuosi tuo kaikki kymmenykset sinä vuonna saamastasi sadosta ja pane ne talteen porttiesi sisäpuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Sitten tulkoon leeviläinen, jolla ei ole osuutta eikä perintöosaa rinnallasi, samoin myös muukalainen, orpo ja leski, jotka asuvat porttiesi sisäpuolella, ja syökööt ja tulkoot ravituiksi, että Herra, Jumalasi, siunaisi sinua kaikissa kättesi töissä, joita teet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, '\"Joka seitsemäs vuosi pane toimeen vapautus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Näin on vapautuksesta määrätty: jokainen saamamies luopukoon siitä, minkä hän on lähimmäiselleen lainannut, älköönkä velkoko lähimmäistään ja veljeään, sillä silloin on julistettu vapautus Herran kunniaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Vierasta saat velkoa, mutta luovu siitä, mitä sinulla on saamista veljeltäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Tosin köyhää ei tulisi ollakaan keskuudessasi, sillä Herra on runsaasti siunaava sinua siinä maassa, jonka Herra, Jumalasi, antaa sinulle perintöosaksi ja jonka saat ottaa omaksesi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'jos vain kuulet Herran, Jumalasi, ääntä ja tarkasti noudatat kaikkia näitä käskyjä, jotka minä tänä päivänä sinulle annan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Sillä Herra, Jumalasi, on siunaava sinua, niin kuin hän on sinulle puhunut. Sinä lainaat monelle kansalle, mutta sinun ei tarvitse lainaa ottaa, ja sinä vallitset monia kansoja, mutta he eivät vallitse sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Jos keskuudessasi on joku köyhä, joku veljesi jossakin porttiesi sisäpuolella siinä maassa, jonka Herra, Jumalasi, sinulle antaa, niin älä paaduta sydäntäsi äläkä sulje kättäsi köyhältä veljeltäsi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'vaan avaa auliisti kätesi hänelle ja lainaa mielelläsi, mitä hän tarvitsee puutteessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Varo, ettei sydämessäsi synny tämä paha ajatus: \'Seitsemäs vuosi, vapautusvuosi, on lähellä\', ja ettet sen tähden katso karsaasti köyhää veljeäsi etkä anna hänelle mitään. Jos hän silloin huutaa sinun tähtesi Herran puoleen, sinä joudut syynalaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Anna mielelläsi hänelle, älköönkä sydämesi olko vastahakoinen antaessasi, sillä lahjasi tähden on Herra, Jumalasi, siunaava sinua kaikissa töissäsi, kaikessa, mihin ryhdyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Koska köyhiä ei koskaan puutu maasta, sen tähden minä käsken sinua näin: Avaa auliisti kätesi veljellesi, kurjalle ja köyhälle, joita maassasi on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Jos joku veljesi, heprealainen mies tai nainen, on myynyt itsensä sinulle ja palvellut sinua kuusi vuotta, niin päästä hänet seitsemäntenä vuotena luotasi vapaaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'ja kun päästät hänet vapaaksi luotasi, älä lähetä häntä tyhjin käsin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'vaan sälytä hänen selkäänsä runsaasti lahjoja laumastasi, puimatantereeltasi ja kuurnastasi. Anna hänellekin siitä, millä Herra, Jumalasi, on sinua siunannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Muista, että itse olit orjana Egyptin maassa ja että Herra, Jumalasi, lunasti sinut. Sen tähden minä tänä päivänä annan sinulle tämän käskyn.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Mutta jos hän sanoo sinulle: \'En tahdo lähteä luotasi\', koska hän rakastaa sinua ja perhettäsi ja koska hänen on ollut hyvä olla luonasi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'ota naskali ja pistä se hänen korvansa läpi oveen. Olkoon hän sitten orjasi ainiaan. Samoin tee myös orjattarellesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Älköön sinusta olko vaikeaa päästää häntä luotasi vapaaksi: onhan hänestä kuutena vuotena ollut sinulle kaksin verroin suurempi hyöty kuin palkkalaisesta. Niin Herra, Jumalasi, on siunaava sinua kaikessa, mitä teet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Kaikki urospuoliset esikoiset, jotka syntyvät nautakarjassasi, lampaissasi ja vuohissasi, pyhitä Herralle, Jumalallesi. Nautasi esikoisella älä tee työtä, älä myöskään keritse lampaasi esikoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Herran, Jumalasi, edessä syö perheinesi se joka vuosi siinä paikassa, jonka Herra valitsee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Jos siinä on jokin vamma, jos se ontuu tai on sokea tai jos sillä on jokin muu paha vamma, mikä tahansa, niin älä uhraa sitä Herralle, Jumalallesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'Syö se porttiesi sisäpuolella. Niin hyvin saastainen kuin puhdas saakoon syödä sitä, niin kuin syödään gasellia tai peuraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Vain verta älä syö. Vuodata se maahan kuin vesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, '\"Ota vaari aabib-kuusta ja vietä pääsiäinen Herran, Jumalasi, kunniaksi, sillä aabib-kuussa Herra, Jumalasi, vei sinut pois Egyptistä, yöllä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Teurasta Herralle, Jumalallesi, pääsiäisuhri, lampaita ja nautoja, siinä paikassa, jonka Herra valitsee nimensä asuinpaikaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Älä syö sen ohella hapanta. Syö seitsemänä päivänä sen ohella happamatonta leipää, kurjuuden leipää – sillä kiireellä sinä lähdit pois Egyptin maasta – että alati muistaisit sitä päivää, jona lähdit Egyptin maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Seitsemään päivään älköön hapanta taikinaa olko koko maassasi, eikä siitä, mitä teurastat ensimmäisen päivän ehtoona, jääkö mitään lihaa yli seuraavaan aamuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Sinä et saa teurastaa pääsiäisuhria niiden kaupunkiesi porttien sisäpuolella, jotka Herra, Jumalasi, sinulle antaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'vaan siinä paikassa, jonka Herra, Jumalasi, valitsee nimensä asuinpaikaksi. Teurasta pääsiäisuhri ehtoolla auringon laskiessa sinä määrähetkenä, jona Egyptistä lähdit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Keitä ja syö se siinä paikassa, jonka Herra, Jumalasi, valitsee. Aamulla saat sitten lähteä paluumatkalle ja mennä kotiisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Kuutena päivänä syö happamatonta leipää, ja seitsemäntenä päivänä olkoon juhlakokous Herran, Jumalasi, kunniaksi. Silloin älä toimita yhtään askaretta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Laske seitsemän viikkoa siitä alkaen, kun sirppi ensi kerran pannaan olkeen. Laske [siitä] seitsemän viikkoa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'ja vietä viikkojuhla Herran, Jumalasi, kunniaksi kätesi vapaaehtoisin lahjoin, joita sinä annat sen mukaan, kuin Herra, Jumalasi, on sinulle siunausta antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'Iloitse Herran, Jumalasi, edessä, sinä, poikasi ja tyttäresi, palvelijasi ja palvelijattaresi, leeviläinen, joka asuu porttiesi sisäpuolella, muukalainen, orpo ja leski, jotka keskuudessasi ovat, siinä paikassa, jonka Herra, Jumalasi, valitsee nimensä asuinpaikaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Muista, että itse olit orjana Egyptissä, ja noudata tarkasti näitä käskyjä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Lehtimajanjuhlaa vietä seitsemän päivää, korjatessasi satoa puimatantereeltasi ja kuurnastasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Iloitse tänä juhlanasi, sinä, poikasi ja tyttäresi, palvelijasi ja palvelijattaresi, leeviläinen, muukalainen, orpo ja leski, jotka asuvat porttiesi sisäpuolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Seitsemän päivää juhli Herran, Jumalasi, kunniaksi siinä paikassa, jonka Herra valitsee. Sillä Herra, Jumalasi, on siunaava sinua kaikessa, minkä saat satona, ja kaikissa kättesi töissä. Ole sen tähden iloinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Kolme kertaa vuodessa tulkoon kaikki miesväkesi Herran, Jumalasi, kasvojen eteen siihen paikkaan, jonka hän valitsee: happamattoman leivän juhlana, viikkojuhlana ja lehtimajanjuhlana. Mutta tyhjin käsin älköön tultako Herran kasvojen eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Kukin tuokoon lahjana sen, minkä voi, sen siunauksen mukaan, minkä Herra, Jumalasi, on sinulle antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Aseta tuomarit ja päällysmiehet eri sukukuntiasi varten kaikkien niiden kaupunkiesi portteihin, jotka Herra, Jumalasi, antaa sinulle. He tuomitkoot kansaa oikein.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Älä vääristä oikeutta: älä katso henkilöön äläkä ota lahjusta, sillä lahjus sokaisee viisaiden silmät ja vääristää syyttömien asiat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Vanhurskautta, ainoastaan vanhurskautta harrasta, että eläisit ja ottaisit omaksesi sen maan, jonka Herra, Jumalasi, sinulle antaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Älä pystytä itsellesi aserapaaluja, älä mitään puuta, Herran, Jumalasi, alttarin viereen, jonka itsellesi teet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Älä myöskään pystytä itsellesi patsasta, sillä niitä Herra, Jumalasi, vihaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, '\"Älä uhraa Herralle, Jumalallesi, nautaa tai lammasta, jossa on jokin vamma, mikä paha vika tahansa, sillä se on kauhistus Herralle, Jumalallesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Jos keskuudessasi niiden kaupunkiesi porttien sisäpuolella, jotka Herra, Jumalasi, sinulle antaa, on mies tai nainen, joka tekee sitä, mikä on pahaa Herran, Jumalasi, silmissä, rikkoo hänen liittonsa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'ja menee ja palvelee muita jumalia ja kumartaa niitä: aurinkoa, kuuta tai kaikkea taivaan joukkoa, minkä olen kieltänyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'ja siitä ilmoitetaan sinulle, että saat sen kuulla, niin tutki asia tarkasti, ja jos on totta ja varmaa, että sellaista kauhistusta on harjoitettu Israelissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'vie se mies tai se nainen, joka on sellaisen pahan tehnyt, porttiesi edustalle – vie sinne se mies tai se nainen – ja kivitä heidät kuoliaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Kahden tai kolmen todistajan todistuksen nojalla kuolemaan tuomittu surmattakoon. Yhden ainoan todistajan todistuksen nojalla älköön häntä surmattako.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Todistajien käsi kohotkoon ensimmäisenä häntä vastaan surmatakseen hänet, ja sitten koko kansan käsi. Poista paha keskuudestasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Jos jokin murhaa, omaisuusriitaa tai pahoinpitelyä koskeva asia tai mikä muu asia hyvänsä, josta porteissasi riidellään, näyttää sinusta liian vaikealta ratkaista, nouse ja lähde siihen paikkaan, jonka Herra, Jumalasi, valitsee,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'ja mene leeviläisten pappien luo ja sen luo, joka siihen aikaan on tuomarina. Kysy heiltä, ja he ilmoittavat sinulle tuomion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Toimi sen sanan mukaan, minkä he sinulle ilmoittavat siinä paikassa, jonka Herra valitsee. Noudata tarkasti kaikkea, mitä he sinulle opettavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Tee sen lain mukaan, minkä he sinulle opettavat, ja sen tuomiopäätöksen mukaan, minkä he sinulle julistavat, poikkeamatta oikealle tai vasemmalle siitä, mitä he sinulle ilmoittavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Mutta jos joku menettelisi niin julkeasti, ettei kuulisi pappia, joka siellä seisoo palvelemassa Herraa, Jumalaasi, tai tuomaria, niin se mies kuolkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Poista paha Israelista. Kaikki kansa kuulkoon sen ja pelätköön, ettei kukaan enää olisi niin julkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Kun tulet siihen maahan, jonka Herra, Jumalasi, sinulle antaa, ja otat sen omaksesi ja asetut siihen ja ajattelet: \'Minä asetan itselleni kuninkaan, kuten on kaikilla kansoilla, jotka minun ympärilläni asuvat\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'niin aseta itsellesi kuninkaaksi se, jonka Herra, Jumalasi, valitsee. Aseta joku veljistäsi kuninkaaksesi. Älä korota hallitsijaksesi muukalaista miestä, joka ei ole veljesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Mutta älköön hän hankkiko itselleen suurta määrää hevosia älköönkä viekö kansaa takaisin Egyptiin hankkiakseen paljon hevosia, sillä Herra on teille sanonut: \'Älkää palatko enää tätä tietä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Älköön hän ottako monta vaimoa, ettei hänen sydämensä luopuisi pois. Älköön hän myöskään kootko itselleen hyvin paljon hopeaa ja kultaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Kun hän on noussut valtaistuimelleen, kirjoituttakoon itselleen kirjaan jäljennöksen tästä laista, joka on leeviläisten pappien huostassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Pitäköön sen luonaan ja lukekoon sitä, niin kauan kuin elää, oppiakseen pelkäämään Herraa, Jumalaansa, ja noudattamaan tarkasti kaikkia tämän lain sanoja ja näitä käskyjä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'ettei hänen sydämensä ylpistyisi veljiään kohtaan ja ettei hän poikkeaisi käskyistä, ei oikealle eikä vasemmalle – että hän ja hänen poikansa kauan hallitsisivat Israelin keskuudessa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, '\"Leeviläisillä papeilla, Leevin koko sukukunnalla, älköön olko osuutta tai perintöosaa muun Israelin rinnalla. He saakoot elatuksensa Herran uhreista, nimittäin siitä, mikä hänen osakseen tulee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Heillä ei ole oleva perintöosaa veljiensä keskuudessa. Herra itse on heidän perintöosansa, kuten hän on heille puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Tämä olkoon pappien oikeus saada kansalta, niiltä, jotka uhraavat teurasuhrin, naudan tai lampaan: papille annettakoon lapa, leukaluut ja maha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Ensi sato jyvistäsi, viinistäsi, öljystäsi ja lammastesi ensimmäiset kerityt villat anna hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Sillä hänet Herra, Jumalasi, on valinnut kaikista sukukunnistasi, että hän ja hänen poikansa alati seisoisivat ja palvelisivat Herran nimessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Jos leeviläinen tahtoo tulla jostakin kaupungistasi, jonka porttien sisäpuolella hän muukalaisena asuu, missä hyvänsä Israelissa, tulkoon vapaasti, kuten hänen mielensä tekee, siihen paikkaan, jonka Herra valitsee,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'ja palvelkoon Herran, Jumalansa, nimessä, niin kuin kaikki muutkin hänen veljensä, leeviläiset, jotka seisovat siellä Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'He kaikki saakoot elatukseksensa yhtäläisen osuuden lukuun ottamatta sitä, mitä joku on saanut myymällä perheomaisuuttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Kun tulet siihen maahan, jonka Herra, Jumalasi, sinulle antaa, niin älä opettele jäljittelemään niiden kansojen kauhistavia tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Älköön keskuudessasi olko ketään, joka panee poikansa tai tyttärensä kulkemaan tulen läpi, tai joka tekee taikoja, ennustelee merkeistä, harjoittaa noituutta tai velhoutta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'joka lukee loitsuja, kysyy vainaja- tai tietäjähengiltä tai kääntyy vainajien puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Sillä jokainen, joka sellaista tekee, on kauhistus Herralle, ja sellaisten kauhistusten tähden Herra, Jumalasi, karkottaa heidät tieltäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Ole siis nuhteeton Herran, Jumalasi, edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Sillä nämä kansat, jotka sinä nyt karkotat, kuuntelevat kyllä merkeistä ennustajia ja taikureita, mutta sinulle Herra, Jumalasi, ei sitä salli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Sinun keskuudestasi, veljiesi joukosta, Herra, Jumalasi, herättää sinulle profeetan, minun kaltaiseni. Häntä kuulkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'On tapahtuva aivan niin, kuin sinä Herralta, Jumalaltasi, anoit Hoorebilla, silloin kun seurakunta oli koolla ja sanoit: \'Älköön minun enää suotako kuulla Herran, Jumalani, ääntä älköönkä nähdä tätä suurta tulta, etten kuolisi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Silloin Herra sanoi minulle: \'Mitä he ovat puhuneet, on oikein puhuttu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Profeetan minä olen herättävä heille heidän veljiensä keskuudesta, kaltaisesi, ja minä panen sanani hänen suuhunsa, ja hän puhuu heille kaikki, mitä minä käsken hänen puhua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Joka ei kuule sanojani, joita hän minun nimessäni puhuu, hänet minä itse vaadin tilille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Mutta profeetta, joka julkeaa puhua minun nimessäni jotakin, jota minä en ole käskenyt hänen puhua, tai puhuu muiden jumalien nimessä, sellainen profeetta kuolkoon.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Jos sanot sydämessäsi: \'Mistä tiedämme, mikä sana ei ole Herran puhetta?\' niin huomaa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'kun profeetta puhuu Herran nimessä, ja kun se, mitä hän on puhunut, ei tapahdu eikä käy toteen, sitä sanaa Herra ei ole puhunut. Julkeuttaan profeetta on niin puhunut. Älä pelkää häntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, '\"Kun Herra, Jumalasi, on hävittänyt ne kansat, joiden maan Herra, Jumalasi, antaa sinulle, ja kun olet karkottanut heidät ja asettunut heidän kaupunkeihinsa ja heidän taloihinsa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'erota itsellesi kolme kaupunkia siinä maassa, jonka Herra, Jumalasi, sinulle antaa, että ottaisit sen omaksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Mittaa matkat ja jaa kolmeen osaan sen maan alue, jonka Herra, Jumalasi, antaa sinulle perinnöksi, että niihin voisi paeta jokainen tappaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Näin on määrätty tappajasta, joka pakenee niihin saadakseen elää: kun joku tappaa lähimmäisensä tahtomattaan ja häntä ennestään vihaamatta –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'niin kuin jos joku menee lähimmäisensä kanssa metsään puita hakkaamaan ja hänen kätensä heiluttaa kirvestä kaataakseen puun ja rauta lentää varresta ja sattuu toiseen, niin että tämä kuolee – niin paetkoon sellainen johonkin näistä kaupungeista saadakseen elää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'ettei verenkostaja, sydämensä kiihkossa tappajaa takaa ajaessaan, saavuttaisi häntä, jos tie on pitkä, ja surmaisi häntä, vaikka hän ei ole ansainnut kuolemaa, koska ei ennestään toista vihannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Sen tähden minä käsken sinua sanoen: \'Erota itsellesi kolme kaupunkia.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Jos Herra, Jumalasi, laajentaa aluettasi, niin kuin hän on vannonut isillesi, ja antaa sinulle kaiken sen maan, jonka hän on sanonut antavansa isillesi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'jos sinä noudatat tarkasti kaikkia näitä käskyjä, jotka minä tänä päivänä sinulle annan, että alati rakastat Herraa, Jumalaasi, ja vaellat hänen teitään, lisää silloin vielä kolme kaupunkia näihin kolmeen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'ettei viatonta verta vuodatettaisi maassasi, jonka Herra, Jumalasi, antaa sinulle perintöosaksi, ja ettet joutuisi verivelan alaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Mutta jos joku vihaa lähimmäistään ja asettuu häntä väijymään ja karkaa hänen kimppuunsa ja lyö hänet kuoliaaksi ja sitten pakenee johonkin näistä kaupungeista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'niin lähettäkööt hänen kaupunkinsa vanhimmat noutamaan hänet sieltä ja antakoot hänet verenkostajan käsiin, ja hän kuolkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Älä sääli häntä, vaan poista viattoman veren velka Israelista, että menestyisit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Älä siirrä lähimmäisesi rajaa, jonka entiset polvet ovat määränneet perintöosallesi siinä maassa, jonka Herra, Jumalasi, sinulle antaa, että ottaisit sen omaksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Yksi ainoa todistaja älköön olko pätevä ketään vastaan, olkoonpa mikä pahanteko tai rikos, mikä synti tahansa, jonka joku tekee. Kahden tai kolmen todistajan sanalla on asia vahva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Jos väärä todistaja nousee jotakuta vastaan ja syyttää häntä jostakin rikoksesta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'astukoot molemmat riitapuolet Herran eteen, pappien eteen ja niiden eteen, jotka siihen aikaan ovat tuomareina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'Tuomarit tutkikoot asian tarkasti, ja jos todistaja on väärä todistaja, joka on tehnyt väärän syytöksen veljeään vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'tehkää hänelle samoin, kuin hän aikoi tehdä veljelleen. Poista paha keskuudestasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Muut kuulkoot sen ja pelätkööt, niin ettei kukaan enää tekisi sellaista pahaa keskuudessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Älä sääli häntä: henki hengestä, silmä silmästä, hammas hampaasta, käsi kädestä, jalka jalasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, '\"Jos lähdet sotaan vihollistasi vastaan ja näet hevosia, sotavaunuja ja sotajoukon, joka on sinua suurempi, älä pelkää heitä, sillä Herra, Jumalasi, on kanssasi, hän, joka johdatti sinut Egyptin maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Kun olette ryhtymässä taisteluun, astukoon pappi esiin puhumaan kansalle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'ja sanokoon heille: \'Kuule, Israel! Te ryhdytte nyt taisteluun vihollisianne vastaan. Älkää arkailko, älkää pelätkö, älkää hätääntykö älkääkä säikähtykö heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Sillä Herra, Jumalanne, käy kanssanne, sotii puolestanne vihollisianne vastaan ja antaa teille voiton.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Päällysmiehet puhukoot kansalle ja sanokoot: \'Joka on rakentanut uuden talon, mutta ei ole vielä sitä vihkinyt, menköön ja palatkoon kotiinsa, ettei hän kaatuisi taistelussa ja joku toinen vihkisi sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Joka on istuttanut viinitarhan, mutta ei ole vielä korjannut sen ensi hedelmää, menköön ja palatkoon kotiinsa, ettei hän kaatuisi taistelussa ja joku toinen korjaisi sen ensi hedelmän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Joka on kihlannut naisen, mutta ei vielä ole ottanut häntä vaimokseen, menköön ja palatkoon kotiinsa, ettei hän kaatuisi taistelussa ja joku toinen ottaisi hänen morsiantaan vaimokseen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Vielä puhukoot päällysmiehet kansalle ja sanokoot: \'Joka pelkää ja arkailee, menköön ja palatkoon kotiinsa, etteivät hänen veljensäkin menettäisi rohkeuttaan niin kuin hän.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Kun päällysmiehet ovat tämän kaiken kansalle puhuneet, asettakoot he osastopäälliköt väen johtoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Kun lähestyt jotakin kaupunkia sotiaksesi sitä vastaan, tarjoa sille ensin rauhaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Jos se suostuu tarjoamaasi rauhaan ja avaa sinulle porttinsa, kaikki siellä oleva kansa suorittakoon sinulle työveroa ja palvelkoon sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Mutta jos se ei tee rauhaa kanssasi, vaan valmistautuu taistelemaan sinua vastaan, niin piiritä sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'Jos Herra, Jumalasi, antaa sen käsiisi, surmaa kaikki sen miesväki miekan terällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Mutta naiset, lapset, karja ja kaikki, mitä kaupungissa on, kaikki, mitä sieltä on saatavana saalista, ryöstä itsellesi, ja nauti vihollisiltasi saatu saalis, minkä Herra, Jumalasi, sinulle antaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Tee näin kaikille niille kaupungeille, jotka ovat sinusta hyvin kaukana, jotka eivät ole näiden kansojen kaupunkeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Mutta näiden kansojen kaupungeissa, jotka Herra, Jumalasi, antaa sinulle perintöosaksi, älä jätä ainoatakaan henkeä eloon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'vaan vihi ne tuhon omiksi: heettiläiset ja amorilaiset, kanaanilaiset ja perissiläiset, hivviläiset ja jebusilaiset, niin kuin Herra, Jumalasi, on sinua käskenyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'etteivät he opettaisi teitä tekemään kaikkia niitä kauhistavia tekoja, joita he ovat tehneet palvellessaan jumaliaan, ja ettette rikkoisi Herraa, teidän Jumalaanne, vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Jos joudut kauan piirittämään kaupunkia ja sotimaan sitä vastaan valloittaaksesi sen, älä hävitä sen puita äläkä heiluta kirvestäsi niitä vastaan. Niiden hedelmiä saat nauttia, mutta älä hakkaa niitä maahan, sillä eivät kedon puut ole ihmisiä joutuakseen sinun piiritettäviksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Ainoastaan ne puut, joista tiedät, että niissä ei ole mitään syötävää, saat hävittää ja hakata maahan rakentaaksesi niistä varustuksia sinua vastaan sotivaa kaupunkia vastaan, kunnes se kukistuu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, '\"Jos siinä maassa, jonka Herra, Jumalasi, sinulle antaa ottaaksesi sen omaksesi, löydetään murhattu virumassa kedolla, eikä tiedetä, kuka hänet tappoi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'niin lähettäkööt vanhimpasi ja tuomarisi mittaamaan välimatkan niihin kaupunkeihin, jotka ovat murhatun ympärillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Sen kaupungin vanhimmat, joka on murhattua lähinnä, ottakoot hiehon, jolla ei ole työtä tehty ja joka ei ole ollut vetojuhtana ikeen alla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'ja sen kaupungin vanhimmat viekööt hiehon alas ehtymättömän puron notkoon, jossa ei ole kynnetty eikä kylvetty. He taittakoot hieholta niskan siinä notkossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Papit, leeviläiset, astukoot esiin, sillä heidät on Herra, Jumalasi, valinnut palvelemaan häntä ja Herran nimeen siunaamaan, ja heidän sanansa mukaan ratkaistakoon jokainen riita ja pahoinpitely.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Kaikki sen kaupungin vanhimmat, he kun asuvat murhattua lähinnä, peskööt kätensä pitäen niitä hiehon päällä, jolta niska taitettiin siinä notkossa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'ja lausukoot sanoen: \'Meidän kätemme eivät ole tätä verta vuodattaneet, eivätkä silmämme tapausta nähneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Anna anteeksi, Herra, kansallesi Israelille, jonka lunastit, äläkä lue viatonta verta syyksi kansallesi Israelille.\' Verivelka annetaan heille anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Poista keskuudestasi viattoman veren velka, sillä sinun on tehtävä se, mikä on oikeaa Herran silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Kun lähdet sotaan vihollisiasi vastaan ja Herra, Jumalasi, antaa heidät käsiisi ja sinä otat heistä vankeja');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'ja vankien joukossa näet kaunisvartaloisen naisen ja mielistyt häneen ja tahdot ottaa hänet vaimoksesi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'niin vie hänet kotiisi, ja hän ajattakoon hiuksensa ja leikatkoon kyntensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'Hän riisukoon vaatteensa, joissa hänet vangittiin, ja asukoon kodissasi ja saakoon itkeä kuukauden päivät isäänsä ja äitiään. Sitten saat yhtyä häneen ja naida hänet, niin että hän tulee vaimoksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Mutta jos hän ei sitten enää sinua miellytä, niin päästä hänet menemään vapaana äläkä myy häntä rahasta. Älä kohtele häntä tylysti, koska olet kohdellut häntä alentavasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Jos jollakulla miehellä on kaksi vaimoa, toinen, jota hän rakastaa, ja toinen, jota hän hylkii, ja he synnyttävät hänelle lapsia, sekä se, jota hän rakastaa, että se, jota hän hylkii, ja esikoinen on hyljityn poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'älköön hän, kun jakaa pojilleen omaisuutensa perinnöksi, antako esikoisoikeutta rakastetun pojalle syrjäyttämällä hyljityn vaimon pojan, joka on esikoinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Vaan tunnustakoon esikoisekseen hyljityn vaimon pojan ja antakoon hänelle kaksinkertaisen osan kaikesta, minkä omistaa. Sillä hän on hänen miehuutensa paras. Hänen on esikoisoikeus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Jos jollakulla on uppiniskainen ja kovakorvainen poika, joka ei ota kuullakseen, mitä hänen isänsä ja äitinsä sanovat, eikä tottele heitä, vaikka he kurittavat häntä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'niin hänen isänsä ja äitinsä ottakoot hänet ja viekööt kaupunkinsa vanhinten eteen asuinpaikkansa porttiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'ja sanokoot kaupunkinsa vanhimmille: \'Tämä poikamme on uppiniskainen ja kovakorvainen. Hän ei ota kuullakseen, mitä sanomme, vaan on irstailija ja juomari.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Silloin kaikki hänen kaupunkinsa miehet kivittäkööt hänet kuoliaaksi. Poista paha keskuudestasi, ja koko Israel kuulkoon sen ja pelätköön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Jos joku on tehnyt itsensä syypääksi rikokseen, josta rangaistaan kuolemalla, ja hänet surmataan, ja sinä olet ripustanut hänet puuhun,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'älköön hänen ruumiinsa jääkö puuhun yöksi, vaan hautaa hänet samana päivänä, sillä Jumalan kiroama on se, joka on puuhun ripustettu. Älä saastuta maata, jonka Herra, Jumalasi, antaa sinulle perintöosaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, '\"Jos näet veljesi härän tai lampaan eksyneen, älä jätä sitä siihen. Vie se takaisin veljellesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Jos veljesi ei asu sinua lähellä tai jos et tiedä, kuka hän on, korjaa eksynyt taloosi, ja olkoon se huostassasi, kunnes veljesi tiedustelee sitä. Anna se silloin hänelle takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Tee samoin, jos veljeltäsi on kadonnut aasi, samoin, jos vaate, samoin, jos mitä muuta hyvänsä, jonka löydät. Älä jätä sitä siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Jos näet veljesi aasin tai härän kaatuneen tielle, älä jätä sitä siihen. Auta häntä nostamaan se jaloilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Nainen älköön käyttäkö miehen asusteita, älköönkä mies pukeutuko naisen vaatteisiin. Sillä jokainen, joka niin tekee, on kauhistus Herralle, Jumalallesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Jos kulkiessasi tapaat puusta tai maasta linnun pesän, jossa on poikaset tai munat ja emo makaamassa poikien tai munien päällä, niin älä ota emoa poikineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'vaan päästä emo lentämään ja ota vain poikaset, että menestyisit ja kauan eläisit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Kun rakennat uuden talon, tee kaide kattosi ympärille, ettet saattaisi verenvikaa taloosi, jos joku sieltä putoaisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Älä kylvä viinitarhaasi kahdenlaista siementä, muuten kaikki, mitä siinä on, sekä siemen, jonka kylvit, että viinitarhan sato, on oleva pyhäkölle pyhitetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Älä kynnä yhtä aikaa härällä ja aasilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Älä pue yllesi vaatetta, joka on kudottu kahdenlaisista langoista, villaisista ja pellavaisista sekaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Tee itsellesi tupsut viittasi neljään kulmaan, johon verhoudut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Jos joku on ottanut vaimon ja yhtynyt häneen, mutta sitten hylkii häntä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'ja esittää häntä vastaan perättömiä syytöksiä ja saattaa hänet pahaan maineeseen ja sanoo: \'Minä otin tämän naisen vaimokseni, mutta kun yhdyin häneen, en tavannut hänessä neitsyyden merkkiä\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'niin tytön isä ja äiti ottakoot ja tuokoot tytön neitsyyden merkin kaupungin vanhimmille, porttiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'Tytön isä sanokoon vanhimmille: \'Minä annoin tyttäreni vaimoksi tälle miehelle, mutta hän hylkii häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'Katso, hän esittää häntä vastaan perättömiä syytöksiä sanoen: Minä en tavannut tyttäressäsi neitsyyden merkkiä. Mutta tässä on tyttäreni neitsyyden merkki,\' levittäkööt vaatteen kaupungin vanhinten eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Silloin kaupungin vanhimmat ottakoot sen miehen ja kurittakoot häntä. Määrätkööt hänelle sakkoa sata hopeasekeliä annettavaksi tytön isälle, sen tähden että hän saattoi Israelin neitsyen huonoon maineeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'Hän olkoon hänen vaimonsa. Älköön hylätkö häntä koko elinaikanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Mutta jos syytös on tosi, jos tytössä ei tavattu neitsyyden merkkiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'vietäköön tyttö isänsä talon ovelle, ja kaupungin miehet kivittäkööt hänet kuoliaaksi, koska hän teki häpeällisen teon Israelissa, harjoittaen haureutta isänsä kodissa. Poista paha keskuudestasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Jos joku tavataan makaamasta naisen kanssa, joka on toisen miehen aviovaimo, niin kuolkoot molemmat, sekä mies, joka makasi vaimon kanssa, että vaimo. Poista paha Israelista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Jos joku neitsyt on kihloissa miehen kanssa ja toinen tapaa hänet kaupungissa ja makaa hänen kanssaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'viekää molemmat sen kaupungin portille ja kivittäkää heidät kuoliaaksi, tyttö siksi, että hän ei huutanut apua kaupungissa, ja mies siksi, että hän teki väkivaltaa lähimmäisensä morsiamelle. Poista paha keskuudestasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Mutta jos mies tapaa kihlatun tytön kedolla, käy häneen käsiksi ja makaa hänen kanssaan, mies, joka makasi hänen kanssaan, kuolkoon yksin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Mutta tytölle älä tee mitään, sillä tyttö ei ole tehnyt kuoleman rikosta. Tässä on samanlainen tapaus, kuin jos mies karkaa toisen kimppuun ja tappaa hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Sillä hän tapasi hänet kedolla. Kihlattu tyttö huusi, mutta hänellä ei ollut auttajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Jos joku tapaa neitsyen, joka ei ole kihlattu, ja ottaa hänet kiinni ja makaa hänen kanssaan ja heidät siitä tavataan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'niin mies, joka makasi hänen kanssaan, antakoon tytön isälle viisikymmentä hopeasekeliä, ja tyttö tulkoon hänen vaimokseen, koska hän raiskasi hänet. Älköön hylätkö häntä koko elinaikanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Älköön kukaan ottako vaimoksi äitipuoltaan älköönkä nostako isänsä peitettä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, '\"Älköön kukaan, joka on kuohittu musertamalla tai leikkaamalla, pääskö Herran seurakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Älköön kukaan sekasikiö pääskö Herran seurakuntaan. Älköön sellaisen jälkeläinen edes kymmenennessä polvessa pääskö Herran seurakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Älköön ammonilainen ja mooabilainen pääskö Herran seurakuntaan. Älkööt heidän jälkeläisensä edes kymmenennessä polvessa koskaan pääskö Herran seurakuntaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'sen tähden että he eivät tulleet leipää ja vettä tuoden teitä vastaan matkalla, kun olitte lähteneet Egyptistä, ja sen tähden että hän palkkasi sinua vastaan Bileamin, Beorin pojan, Mesopotamian Petorista, sinua kiroamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Mutta Herra, Jumalasi, ei tahtonut kuulla Bileamia, vaan Herra, Jumalasi, muutti kirouksen sinulle siunaukseksi, sillä Herra, Jumalasi, rakasti sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Älä koskaan, älä koko elinaikanasi, etsi heidän menestystään ja onneaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Edomilaista älä inhoa, sillä hän on veljesi. Älä inhoa egyptiläistä, sillä sinä olet asunut muukalaisena hänen maassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Lapset, jotka heille syntyvät kolmannessa polvessa, pääskööt Herran seurakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Kun lähdettyäsi vihollisiasi vastaan asetut leiriin, karta kaikkea epäsiistiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Jos keskuudessasi on joku, joka ei ole puhdas sen johdosta, mitä hänelle yöllä on tapahtunut, menköön leirin ulkopuolelle älköönkä tulko leiriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Illan suussa peseytyköön vedessä, ja auringon laskettua tulkoon leiriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Leirin ulkopuolella olkoon sinulla syrjäinen paikka, johon sinun on mentävä tarpeellesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Sinulla olkoon aseittesi lisänä pieni lapio, ja kun istut siellä ulkona tarpeellesi, kaiva sillä kuoppa ja peitä ulosteesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Sillä Herra, Jumalasi, vaeltaa leirissä auttaakseen sinua ja antaakseen vihollisesi sinulle alttiiksi. Sen tähden olkoon leirisi pyhä, ettei hän näkisi keskuudessasi mitään häpeällistä ja kääntyisi sinusta pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Älä luovuta isännälleen orjaa, joka on paennut isäntänsä luota luoksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Asukoon luonasi, keskuudessasi, valitsemassaan paikassa, jonkin kaupunkisi porttien sisäpuolella, missä hän viihtyy. Älä sorra häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Älköön pyhäkköporttoa olko Israelin tyttärien joukossa älköönkä haureellista pyhäkköpoikaa Israelin poikien joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Älä tuo portonpalkkaa äläkä koiranpalkkaa Herran, Jumalasi, huoneeseen lupauksen suoritukseksi, sillä molemmat ovat kauhistus Herralle, Jumalallesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Älä pane veljeäsi maksamaan korkoa rahasta tai elintarpeista tai muusta, mitä korkoa vastaan lainataan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Muukalaisen saat panna korkoa maksamaan, mutta et veljeäsi, että Herra, Jumalasi, siunaisi sinua kaikessa, mihin ryhdyt, siinä maassa, jota menet ottamaan omaksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Kun teet lupauksen Herralle, Jumalallesi, niin täytä se aikailematta, sillä totisesti Herra, Jumalasi, on vaativa sen sinulta, ja sinä joudut syynalaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Mutta jos jätät lupauksen tekemättä, et joudu syynalaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Pidä se, mikä on huuliltasi lähtenyt, ja tee, niin kuin vapaaehtoisesti olet luvannut Herralle, Jumalallesi, niin kuin olet suullasi puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Kun tulet lähimmäisesi viinitarhaan, syö rypäleitä, minkä mielesi tekee, kunnes olet saanut tarpeeksi, mutta älä pane mitään astiaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 26, 'Kun tulet lähimmäisesi viljapellolle, saat kädelläsi katkoa tähkiä, mutta sirppiä älä heiluta lähimmäisesi viljapellolla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, '\"Jos joku ottaa vaimon ja nai hänet ja vaimo ei häntä enää miellytä, koska mies on tavannut hänessä jotakin häpeällistä, ja hän kirjoittaa hänelle erokirjan, antaa sen hänen käteensä ja lähettää hänet pois talostaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'ja jos nainen sitten lähdettyään hänen talostaan menee ja joutuu toisen miehen vaimoksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'ja tämäkin, toinen mies, hylkii häntä ja kirjoittaa hänelle erokirjan, antaa sen hänen käteensä ja lähettää hänet pois talostaan, tai jos tämä toinen mies, joka on ottanut hänet vaimokseen, kuolee,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'älköön hänen ensimmäinen miehensä, joka lähetti hänet pois, ottako häntä uudestaan vaimokseen, sitten kun tämä on tullut saastutetuksi, sillä se olisi kauhistus Herran edessä. Älä saata syynalaiseksi maata, jonka Herra, Jumalasi, antaa sinulle perintöosaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Jos joku on hiljan ottanut vaimon, hänen ei tarvitse lähteä sotaan. Älköön hänen päälleen pantako muutakaan rasitusta. Olkoon vuoden vapaa perhettään varten ja iloksi vaimolleen, jonka on ottanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Älköön pantiksi otettako käsikiviä, ei päällimmäistäkään kiveä, sillä se olisi hengen ottamista pantiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Jos joku tavataan siitä, että hän on varastanut jonkun veljistään, israelilaisista, ja kohdellut häntä tylysti tai myynyt hänet, varas kuolkoon. Poista paha keskuudestasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Ole varuillasi spitaalilaikkua vastaan, niin että tarkasti noudatat kaikkea, mitä leeviläiset papit teille opettavat. Noudattakaa tarkasti käskyjä, jotka olen heille antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Muista, mitä Herra, Jumalasi, teki Mirjamille matkalla, kun te olitte lähteneet Egyptistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Jos lainaat jotakin lähimmäisellesi, älä mene hänen taloonsa ottamaan häneltä panttia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Jää ulos. Mies, jolle lainasit, tuokoon pantin sinulle ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Jos hän on köyhä mies, älä mene nukkumaan pitäen hänen panttinsa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'vaan anna hänelle takaisin hänen panttinsa auringon laskiessa, että hän voisi maata paidassaan ja siunaisi sinua. Se koituu sinulle vanhurskaudeksi Herran, Jumalasi, edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Älä tee vääryyttä kurjalle ja köyhälle palkkalaiselle, olipa hän veljiäsi tai muukalaisia, joita asuu maassasi, porttiesi sisäpuolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Maksa hänelle hänen palkkansa samana päivänä, ennen kuin aurinko laskee, sillä hän on kurja ja haluaa palkkaansa – ettei hän huutaisi tähtesi Herran puoleen ja ettet joutuisi syynalaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Älköön isiä rangaistako kuolemalla lasten tähden älköönkä lapsia isien tähden. Jokainen rangaistakoon kuolemalla oman syntinsä tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Älä vääristä muukalaisen äläkä orvon oikeutta, äläkä ota lesken vaatteita pantiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Muista, että itse olit orjana Egyptissä ja että Herra, Jumalasi, sinut sieltä vapahti. Sen tähden minä käsken sinua näin tekemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Jos korjatessasi eloa pelloltasi unohdat pellolle lyhteen, älä palaa sitä hakemaan. Se olkoon muukalaisen, orvon ja lesken oma, että Herra, Jumalasi, siunaisi sinua kaikissa kättesi töissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Kun olet pudistanut öljypuustasi hedelmät, älä enää poimi oksilta, mitä sinne on jäänyt. Se olkoon muukalaisen, orvon ja lesken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Kun olet korjannut sadon viinitarhastasi, älä toimita enää jälkikorjuuta. Se jääköön muukalaiselle, orvolle ja leskelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Muista, että itse olit orjana Egyptin maassa. Sen tähden minä käsken sinua noudattamaan näitä sanoja.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, '\"Jos syntyy riita miesten välillä ja he astuvat oikeuden eteen ja heidät tuomitaan, syytön syyttömäksi ja syyllinen syylliseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'ja jos syyllinen tuomitaan raippoihin, käskeköön tuomari hänen laskeutua maahan ja läsnä ollessaan hänelle annettavaksi hänen rikostaan vastaavan määräluvun raippoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Neljäkymmentä raippaa saa hän hänelle antaa, ei enempää, ettei veljeäsi häväistäisi silmiesi edessä antamalla hänelle vielä useampia lyöntejä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Älä sido puivan härän suuta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Kun veljeksiä asuu yhdessä ja joku heistä kuolee eikä hänellä ole poikaa, älköön vainajan leski menkö naimisiin muuhun sukuun, suvun ulkopuolisen miehen kanssa. Hänen lankonsa yhtyköön häneen, ottakoon hänet vaimokseen ja täyttäköön häntä kohtaan langon velvollisuuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Esikoinen, jonka vaimo synnyttää, katsottakoon kuolleen veljen omaksi, ettei hänen nimeään pyyhittäisi pois Israelista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Mutta jos mies ei suostu ottamaan kälyään vaimoksi, niin menköön käly porttiin vanhinten eteen ja sanokoon: \'Minun lankoni kieltäytyy säilyttämästä veljensä nimeä Israelissa. Hän ei tahdo täyttää langon velvollisuutta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Silloin hänen kaupunkinsa vanhimmat kutsukoot hänet ja puhutelkoot häntä. Jos hän pysyy päätöksessään ja sanoo: \'En suostu ottamaan häntä vaimokseni\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'hänen kälynsä astukoon hänen luokseen vanhinten silmien eteen ja vetäköön kengän hänen jalastaan, sylkeköön häntä silmille ja lausukoon sanoen: \'Näin tehtäköön jokaiselle, joka ei rakenna veljensä huonetta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Hänen perhettään nimitettäköön sitten Israelissa \'paljasjalan perheeksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Jos kaksi miestä tappelee keskenään ja toisen vaimo tulee auttamaan miestään sen käsistä, joka häntä lyö, ja ojentaa kätensä ja tarttuu tämän häpyyn,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'hakkaa poikki hänen kätensä säälimättä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Älä pidä kukkarossasi kahdenlaisia punnuksia, suurempia ja pienempiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Älä pidä talossasi kahdenlaista eefa-mittaa, suurempaa ja pienempää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Olkoon sinulla täydet ja oikeat punnukset. Olkoon sinulla täysi ja oikea eefa-mitta, että eläisit kauan siinä maassa, jonka Herra, Jumalasi, sinulle antaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Sillä jokainen, joka näitä tekee, on kauhistus Herralle, jokainen, joka vääryyttä tekee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Muista, mitä Amalek teki sinulle matkalla, kun olit lähtenyt Egyptistä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'kuinka hän, Jumalaa pelkäämättä, tuli sinua vastaan tiellä, kun sinä olit väsynyt ja uuvuksissa, ja eristi yhteydestäsi kaikki heikommat, jotka kulkivat jälkipäässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Sen tähden, kun Herra, Jumalasi, antaa sinun päästä rauhaan kaikista ympärillä olevista vihollisistasi siinä maassa, jonka Herra, Jumalasi, antaa sinulle perintöosaksi, ottaaksesi sen omaksesi, pyyhi pois Amalekin muisto taivaan alta. Älä tätä unohda.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, '\"Kun tulet maahan, jonka Herra, Jumalasi, antaa sinulle perintöosaksi, ja otat sen omaksesi ja asetut siihen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'niin ota ensisato kaikista maasi hedelmistä, mitä saat satona maastasi, jonka Herra, Jumalasi, sinulle antaa, ja pane ne koriin ja lähde siihen paikkaan, jonka Herra, Jumalasi, valitsee nimensä asuinpaikaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'Mene sen luo, joka siihen aikaan on pappina, ja sano hänelle: \'Tunnustan tänä päivänä Herralle, Jumalallesi, että olen tullut siihen maahan, jonka Herra isillemme vannotulla valalla on luvannut antaa meille.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Pappi ottakoon korin kädestäsi ja asettakoon sen Herran, Jumalasi, alttarin eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Sitten lausu Herran, Jumalasi, edessä sanoen: \'Isäni oli vaelteleva aramealainen, joka meni Egyptiin vähäinen joukko mukanaan, ja asui siellä muukalaisena ja tuli siellä suureksi, väkeväksi ja lukuisaksi kansaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Mutta egyptiläiset kohtelivat meitä pahoin ja rasittivat meitä ja teettivät meillä kovaa työtä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Huusimme Herran, isiemme Jumalan, puoleen, ja Herra kuuli huutomme ja näki kurjuutemme, vaivamme ja kärsimämme sorron.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'Herra vei meidät pois Egyptistä väkevällä kädellä ja ojennetulla käsivarrella tehden suuria pelottavia tunnustekoja ja ihmeitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'Hän toi meidät tähän paikkaan ja antoi meille tämän maan, maan, joka vuotaa maitoa ja hunajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Katso, minä tuon nyt ensisadon sen maan hedelmistä, jonka sinä, Herra, minulle annoit.\' Niin aseta ne Herran, Jumalasi, eteen ja kumartaen rukoile Herran, Jumalasi, edessä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'ja iloitse kaikesta hyvästä, minkä Herra, Jumalasi, on antanut sinulle ja perheellesi, sinä, leeviläinen ja muukalainen, joka asuu keskuudessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Kun kolmantena vuotena, kymmenysten vuotena, olet suorittanut loppuun kaikki kymmenykset saamastasi sadosta ja antanut ne leeviläiselle, muukalaiselle, orvolle ja leskelle, ja he ovat syöneet porttiesi sisäpuolella ja tulleet ravituiksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'sano Herran, Jumalasi, edessä: \'Minä olen vienyt pois talostani sen, mikä on pyhäkölle pyhitettyä, ja olen antanut sen leeviläiselle ja muukalaiselle, orvolle ja leskelle, aivan käskysi mukaan, jonka olet minulle antanut. En ole rikkonut käskyjäsi enkä niitä unohtanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'En syönyt siitä mitään silloin, kun minulla oli suru, enkä vienyt siitä mitään pois silloin, kun olin saastunut, enkä antanut siitä mitään vainajalle. Olen kuullut Herran, Jumalani, ääntä. Olen tehnyt aivan niin, kuin olet käskenyt minun tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Katso pyhästä asunnostasi, taivaasta, ja siunaa kansaasi Israelia ja sitä maata, jonka olet meille antanut, niin kuin valalla vannoen lupasit isillemme, maata, joka vuotaa maitoa ja hunajaa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Tänä päivänä Herra, Jumalasi, käskee sinun seurata näitä käskyjä ja oikeuksia. Noudata ja seuraa niitä kaikesta sydämestäsi ja kaikesta sielustasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Sinä olet tänään kuullut Herran, Jumalasi, julistavan, että hän tahtoo olla Jumalasi ja että sinun on vaellettava hänen teitään ja noudatettava hänen käskyjään, säädöksiään ja oikeuksiaan sekä kuultava häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Herra on kuullut sinun tänä päivänä julistavan, että tahdot olla hänen omaisuuskansansa, niin kuin hän on sinulle puhunut, ja noudattaa kaikkia hänen käskyjään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'että hän asettaisi sinut korkeammaksi kaikkia luomiaan kansoja, ylistykseksi, kunniaksi ja kiitokseksi, ja että olisit Herralle, Jumalallesi, pyhitetty kansa, niin kuin hän on puhunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Niin Mooses ja Israelin vanhimmat käskivät kansaa sanoen: \"Noudattakaa kaikkia niitä käskyjä, jotka minä tänä päivänä teille käsken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'Kun menette Jordanin yli siihen maahan, jonka Herra, Jumalasi, sinulle antaa, pystytä itsellesi suuria kiviä ja sivele ne kalkilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'Kirjoita niihin kaikki tämän lain sanat, kun menet joen yli siihen maahan, jonka Herra, Jumalasi, sinulle antaa, maahan, joka vuotaa maitoa ja hunajaa, niin kuin Herra, isiesi Jumala, on sinulle puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Kun olette menneet Jordanin yli, pystyttäkää Eebalin vuorelle ne kivet, joista minä tänä päivänä annan teille käskyn, ja sivele ne kalkilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Rakenna siihen alttari Herralle, Jumalallesi, alttari kivistä, joihin et saa rauta-aseella koskea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Hakkaamattomista kivistä rakenna Herran, Jumalasi, alttari. Uhraa sen päällä polttouhreja Herralle, Jumalallesi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'ja teurasta teuraita rauhanuhriksi ja syö siellä ja iloitse Herran, Jumalasi, edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Kirjoita kiviin kaikki tämän lain sanat hyvin selvästi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Mooses ja leeviläiset papit puhuivat kaikelle Israelille sanoen: \"Ole hiljaa ja kuule, Israel! Tänä päivänä on sinusta tullut Herran, Jumalasi, kansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Kuule Herraa, Jumalaasi, ja noudata hänen käskyjään ja ohjeitaan, jotka minä tänä päivänä sinulle käsken.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Mooses käski kansaa sinä päivänä sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, '\"Kun olette menneet Jordanin yli, asettukoot nämä Garissimin vuorelle siunaamaan kansaa: Simeon, Leevi, Juuda, Isaskar, Joosef ja Benjamin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Nämä taas asettukoot Eebalin vuorelle lausumaan kirouksen: Ruuben, Gaad, Asser, Sebulon, Daan ja Naftali.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Leeviläiset lausukoot ja sanokoot kovalla äänellä kaikille Israelin miehille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, '\'Kirottu olkoon se, joka tekee jumalankuvan, veistetyn tai valetun taitajan käden tekemän kauhistukseksi Herralle, ja joka salaa sen pystyttää.\' Kaikki kansa vastatkoon ja sanokoon: \'Aamen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Kirottu olkoon se, joka häpäisee isäänsä tai äitiään. Kaikki kansa sanokoon: \'Aamen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Kirottu olkoon se, joka siirtää lähimmäisensä rajan. Kaikki kansa sanokoon: \'Aamen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Kirottu olkoon se, joka vie sokean harhaan tieltä. Kaikki kansa sanokoon: \'Aamen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Kirottu olkoon se, joka vääristää muukalaisen, orvon tai lesken oikeuden. Kaikki kansa sanokoon: \'Aamen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Kirottu olkoon se, joka makaa äitipuolensa kanssa, sillä hän nostaa isänsä peitteen. Kaikki kansa sanokoon: \'Aamen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Kirottu olkoon se, joka sekaantuu eläimeen. Kaikki kansa sanokoon: \'Aamen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Kirottu olkoon se, joka makaa sisarensa, isänsä tyttären tai äitinsä tyttären, kanssa. Kaikki kansa sanokoon: \'Aamen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Kirottu olkoon se, joka makaa anoppinsa kanssa. Kaikki kansa sanokoon: \'Aamen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Kirottu olkoon se, joka salaa murhaa lähimmäisensä. Kaikki kansa sanokoon: \'Aamen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Kirottu olkoon se, joka ottaa lahjuksen surmatakseen viattoman. Kaikki kansa sanokoon: \'Aamen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Kirottu olkoon se, joka ei pidä tämän lain sanoja eikä täytä niitä. Kaikki kansa sanokoon: \'Aamen.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, '\"Jos kuulet Herran, Jumalasi, ääntä ja pidät tarkasti kaikki hänen käskynsä, jotka minä tänä päivänä sinulle käsken, niin Herra, Jumalasi, asettaa sinut korkeammaksi kaikkia kansoja maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'Jos kuulet Herran, Jumalasi, ääntä, kaikki nämä siunaukset tulevat osaksesi ja saavuttavat sinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Siunattu olet sinä kaupungissa ja siunattu olet kedolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Siunattu on kohtusi hedelmä, maasi hedelmä ja karjasi hedelmä, nautojesi vasikat ja lampaittesi karitsat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Siunattu on korisi ja taikinakaukalosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Siunattu olet tullessasi ja siunattu olet lähtiessäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Herra antaa sinun voittaa vihollisesi, jotka nousevat sinua vastaan. Yhtä tietä he lähtevät sinua vastaan, mutta seitsemää tietä he sinua pakenevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Herra käskee siunauksen seurata sinua jyväaitoissasi ja kaikessa, mihin ryhdyt. Hän siunaa sinua maassa, jonka Herra, Jumalasi, sinulle antaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Herra korottaa sinut hänelle pyhitetyksi kansaksi, niin kuin hän valalla vannoen on sinulle luvannut, jos sinä noudatat Herran, Jumalasi, käskyjä ja vaellat hänen teitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Silloin kaikki kansat maan päällä näkevät, että Herra on ottanut sinut nimiinsä, ja he pelkäävät sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Herra antaa sinulle hyvin runsaasti hyvää, tekee kohtusi hedelmän, karjasi hedelmän ja maasi hedelmän hyvin runsaaksi siinä maassa, jonka Herra isillesi vannotulla valalla on luvannut antaa sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Herra avaa sinulle rikkaan aarrekammionsa, taivaan, antaakseen maallesi sateen ajallaan ja siunatakseen kaikki kättesi työt. Sinä lainaat monelle kansalle, mutta sinun itsesi ei tarvitse ottaa lainaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Herra tekee sinut pääksi eikä hännäksi. Sinä aina vain ylenet etkä koskaan alene, jos tottelet Herran, Jumalasi, käskyjä, jotka minä tänä päivänä sinulle annan, jotta pitäisit ne tarkasti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'etkä poikkea oikealle etkä vasemmalle yhdestäkään niistä sanoista, jotka minä tänä päivänä teille annan, et seuraa muita jumalia etkä palvele niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Mutta jos sinä et kuule Herran, Jumalasi, ääntä etkä tarkasti pidä kaikkia hänen käskyjään ja säädöksiään, jotka minä tänä päivänä sinulle käsken, niin kaikki nämä kiroukset tulevat päällesi ja saavuttavat sinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Kirottu olet sinä kaupungissa ja kirottu olet kedolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Kirottu on korisi ja taikinakaukalosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Kirottu on kohtusi hedelmä ja maasi hedelmä, kirotut nautojesi vasikat ja lampaittesi karitsat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Kirottu olet tullessasi ja kirottu olet lähtiessäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Herra lähettää keskellesi kirousta, hämminkiä ja uhkaa, mihin tahansa ryhdyt, kunnes äkisti tuhoudut ja hukut töittesi pahuuden tähden, kun olet minut hylännyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Herra antaa ruttotaudin tarttua sinuun, kunnes se hävittää sinut sukupuuttoon maasta, jota menet ottamaan omaksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Herra lyö sinua hivutustaudilla, kuumeella, poltteella ja tulehduksella, kuivuudella, nokitähkillä ja viljan ruosteella, ja ne vainoavat sinua, kunnes menehdyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Taivaasi, joka on pääsi päällä, on kuin vaskea, ja maa, joka on allasi, on kuin rautaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Herra muuttaa maasi sateen tomuksi ja tuhkaksi. Se tulee päällesi taivaasta, kunnes tuhoudut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Herra antaa vihollistesi voittaa sinut. Yhtä tietä sinä menet heitä vastaan, mutta seitsemää tietä sinä heitä pakenet, ja sinä tulet kauhistukseksi kaikille valtakunnille maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Ruumiisi joutuvat ruuaksi kaikille taivaan linnuille ja maan eläimille, eikä kukaan karkota niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Herra lyö sinua Egyptin paiseilla ja ajoksilla, ihottumalla ja ruvella, joista et parane.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Herra lyö sinua hulluudella, sokeudella ja mielisairaudella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Sinä haparoit keskellä päivää, kuin sokea haparoi pimeässä. Sinä et menesty teilläsi, vaan kaiken elinaikasi sinä olet oleva sorrettu ja ryöstetty, eikä ole auttajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Sinä kihlaat naisen, mutta toinen makaa hänet. Sinä rakennat talon, mutta et siinä asu. Sinä istutat viinitarhan, mutta et korjaa sen hedelmää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Härkäsi teurastetaan silmiesi edessä, mutta sinä et sitä syö. Aasisi ryöstetään sinulta nähtesi eikä sitä anneta sinulle takaisin. Lampaasi joutuvat vihollistesi valtaan, eikä sinulla ole auttajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Poikasi ja tyttäresi joutuvat vieraan kansan valtaan, ja silmäsi näkevät sen ja raukeavat heitä alinomaa ikävöidessäsi, mutta sinä et voi sille mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Maasi hedelmän ja kaiken vaivannäkösi kuluttaa kansa, jota et tunne. Kaiken elinaikasi olet oleva sorrettu ja runneltu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Sinä tulet hulluksi siitä, mitä silmäsi näkevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Herra lyö sinuun, polviisi ja pohkeisiisi, pahoja paiseita, joista et parane, kantapäästä kiireeseen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Herra vie sinut ja kuninkaan, jonka sinä itsellesi asetat, kansan luo, jota sinä et tunne ja jota isäsi eivät tunteneet. Siellä sinä palvelet muita jumalia, puu- ja epäjumalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Sinä tulet kauhistukseksi, sananparreksi ja ivailun kohteeksi kaikille niille kansoille, joiden keskuuteen Herra kuljettaa sinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Sinä viet paljon siementä pellollesi, mutta korjaat vähän, sillä heinäsirkat hävittävät sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Viinitarhoja sinä istutat ja hoidat, mutta viiniä et saa juodaksesi etkä tallettaaksesi, sillä madot syövät sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Öljypuita sinulla on kaikkialla alueellasi, mutta öljyllä et itseäsi voitele, sillä öljymarjasi varisevat maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Poikia ja tyttäriä sinulle syntyy, mutta et saa niitä pitää, sillä he vaeltavat vankeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Tuhohyönteiset valtaavat kaikki puusi ja maasi hedelmän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Muukalainen, joka asuu keskuudessasi, kohoaa ylitsesi yhä ylemmäksi, mutta sinä painut aina alemmaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Hän lainaa sinulle, mutta sinä et voi lainata hänelle. Hän tulee pääksi, mutta sinä hännäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Kaikki nämä kiroukset tulevat päällesi, vainoavat sinua ja saavuttavat sinut, kunnes tuhoudut, koska et kuullut Herran, Jumalasi, ääntä etkä noudattanut hänen käskyjään ja säädöksiään, jotka hän on sinulle antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Ne jäävät merkkeinä ja ihmeinä sinuun ja jälkeläisiisi ikiajoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Koska et palvellut Herraa, Jumalaasi, ilolla ja sydämen halulla, kun sinulla oli yltäkyllin kaikkea,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'on sinun palveltava nälässä, janossa, alastomuudessa ja kaiken puutteessa vihollisiasi, jotka Herra lähettää kimppuusi. Hän panee kaulallesi rautaikeen, kunnes hän sinut tuhoaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Herra nostaa sinua vastaan kaukaisen kansan, joka tulee maan äärestä lentäen kuin kotka, kansan, jonka kieltä et ymmärrä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'Tuimakatseisen kansan, joka ei armahda vanhaa eikä sääli nuorta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Se syö karjasi hedelmän ja maasi hedelmän, kunnes tuhoudut. Se ei jätä sinulle mitään, ei jyviä, ei viiniä eikä öljyä, ei nautojesi vasikoita eikä lampaittesi karitsoita, kunnes on tehnyt sinusta lopun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Se ahdistaa sinua kaikissa porteissasi, kunnes korkeat ja lujat muurisi, joihin luotit, kukistuvat kaikkialla maassasi. Se ahdistaa sinua kaikissa porteissasi kaikkialla maassasi, jonka Herra, Jumalasi, on sinulle antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Siinä hädässä ja ahdistuksessa, johon vihollisesi saattaa sinut, sinä syöt oman kohtusi hedelmän, syöt poikiesi ja tyttäriesi lihaa, jotka Herra, Jumalasi, on sinulle antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Hemmoteltu ja suuressa ylellisyydessä elänyt mies keskuudessasi katselee karsaasti veljeään ja vaimoaan, joka on hänen sylissään, ja jäljellä olevia lapsiaan, jotka hän on jättänyt henkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'Kenellekään heistä hän ei anna lastensa lihaa, jota hän itse syö, kun hänellä ei ole mitään muuta jäljellä, siinä hädässä ja ahdistuksessa, johon vihollisesi saattaa sinut kaikissa porteissasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Hemmoteltu ja keimaileva nainen keskuudessasi, joka nautinnonhalunsa ja ylellisyytensä tähden ei edes yrittänyt laskea jalkaansa maahan, katselee silloin karsaasti miestä, joka on hänen sylissään, ja poikaansa ja tytärtään');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'eikä suo heille jälkeläisiä, jotka tulevat hänen kohdustaan, eikä lapsia, jotka hän synnyttää, sillä kaiken muun puutteessa hän syö ne salaa itse siinä hädässä ja ahdistuksessa, johon vihollisesi saattaa sinut porteissasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Jos et tarkasti noudata kaikkia tämän lain sanoja, jotka ovat kirjoitetut tähän kirjaan, niin että pelkäät tätä kunniallista ja pelottavaa nimeä, Herraa, Jumalaasi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'niin Herra panee sinun ja jälkeläistesi kärsittäväksi ihmeenomaisia vaivoja, suuria ja pitkällisiä vaivoja, pahoja ja pitkällisiä sairauksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Hän kääntää sinua vastaan kaikki Egyptin taudit, joita sinä pelkäät, ja ne tarttuvat sinuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Kaikenlaisia muita sairauksia ja vaivoja, joista ei ole kirjoitettu tähän lain kirjaan, Herra nostattaa sinua vastaan, kunnes tuhoudut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Teistä, jotka ennen olitte monilukuiset kuin taivaan tähdet, jää jäljelle ainoastaan vähäinen joukko, koska et kuullut Herran, Jumalasi, ääntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Niin kuin Herra ennen iloitsi teistä, siitä, että teki teille hyvää ja antoi teidän lisääntyä, niin Herra silloin iloitsee teistä, siitä, että hävittää ja tuhoaa teidät. Teidät temmataan irti maasta, jota menet ottamaan omaksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Herra hajottaa sinut kaikkien kansojen sekaan maan äärestä toiseen, ja sinä palvelet siellä muita jumalia, joita et tunne ja joita isäsi eivät tunteneet, puuta ja kiveä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Niiden kansojen seassa sinä et saa rauhaa, eikä jalkasi löydä lepopaikkaa. Herra antaa sinulle siellä vapisevan sydämen, rauenneet silmät ja nääntyvän sielun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Elämäsi näyttää sinusta olevan hiuskarvan varassa, yöt ja päivät sinä olet pelon vallassa etkä ole varma hengestäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Aamulla sinä sanot: \'Jospa olisi ilta!\' ja illalla sanot: \'Jospa olisi aamu!\' – sellaista pelkoa tunnet sydämessäsi, ja sellaisia näkyjä näet silmissäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Herra vie sinut laivoilla takaisin Egyptiin samaa tietä, josta minä sanoin sinulle: \'Et ole sitä enää näkevä.\' Siellä teitä kaupitellaan vihollisillenne orjiksi ja orjattariksi, mutta ostajaa ei ole.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 69, 'Nämä ovat sen liiton sanat, jonka Herra käski Mooseksen tehdä israelilaisten kanssa Mooabin maassa, sen liiton lisäksi, jonka hän oli tehnyt heidän kanssaan Hoorebilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Mooses kutsui kokoon koko Israelin ja sanoi heille: \"Te olette nähneet kaiken, minkä Herra teki silmienne edessä Egyptin maassa faraolle ja kaikille hänen palvelijoilleen ja koko hänen maalleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'ne suuret koettelemukset, jotka silmäsi näkivät, ne suuret tunnusteot ja ihmeet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Mutta tähän päivään asti Herra ei vielä ole antanut teille sydäntä ymmärtääksenne ja silmiä nähdäksenne ja korvia kuullaksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Kuljetin teitä erämaassa neljäkymmentä vuotta: teidän vaatteenne eivät kuluneet yltänne, eivätkä sandaalisi kuluneet jalassasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Leipää ette saaneet syödäksenne ettekä viiniä ja väkijuomaa juodaksenne, jotta tietäisitte, että minä olen Herra, Jumalanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Kun te tulitte tähän paikkaan, niin lähtivät Siihon, Hesbonin kuningas, ja Oog, Baasanin kuningas, sotimaan meitä vastaan, mutta me voitimme heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'Me valloitimme heidän maansa ja annoimme sen perintöosaksi ruubenilaisille, gaadilaisille ja toiselle puolelle Manassen sukukuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'Noudattakaa siis tämän liiton sanoja ja täyttäkää ne menestyäksenne kaikessa, mitä teette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Te seisotte tänä päivänä kaikki Herran, Jumalanne, edessä: päämiehenne, sukukuntanne, vanhimpanne ja päällysmiehenne, kaikki Israelin miehet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'teidän lapsenne ja vaimonne sekä muukalainen, joka on leirissäsi, jopa puunhakkaajasi ja vedenkantajasikin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'käydäksenne Herran, Jumalanne, liittoon, siihen valaliittoon, jonka Herra, Jumalasi, tänä päivänä tekee kanssasi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'että hän tänä päivänä korottaisi sinut kansakseen ja tulisi Jumalaksesi, niin kuin hän on sinulle puhunut ja niin kuin hän on vannonut isillesi, Aabrahamille, Iisakille ja Jaakobille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Enkä minä tee tätä liittoa, tätä valaliittoa, ainoastaan teidän kanssanne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'vaan yhtä hyvin niiden kanssa, jotka tänä päivänä ovat tässä meidän kanssamme seisomassa Herran, Jumalamme, edessä kuin niidenkin kanssa, jotka eivät ole tänä päivänä tässä meidän kanssamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Sillä te tiedätte, kuinka asuimme Egyptin maassa ja kuinka kuljimme niiden kansojen keskitse, joiden kautta te olette kulkeneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Te näitte heidän iljetyksensä, ne puu-, kivi-, hopea- ja kultajumalat, jotka heillä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'Älköön siis joukossanne olko ainoatakaan miestä tai naista, sukua tai sukukuntaa, jonka sydän tänä päivänä kääntyy pois Herrasta, Jumalastamme mennäkseen palvelemaan noiden kansojen jumalia. Älköön keskuudessanne olko juurta, josta kasvaa koiruohoa ja marunaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'niin että, se joka kuulee tämän valan sanat, siunaisi itseään sydämessään sanoen: \'Minun käy hyvin, vaikka vaellankin sydämeni paatumuksessa.\' Siten hän hukuttaisi kaiken, sekä kostean että kuivan maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Herra ei tahdo antaa hänelle anteeksi, vaan silloin suitsuaa Herran viha ja kiivaus sitä miestä vastaan, ja kaikki se kirous, joka on kirjoitettu tähän kirjaan, laskeutuu hänen päälleen, ja Herra pyyhkii pois hänen nimensä taivaan alta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Herra erottaa hänet kaikista Israelin sukukunnista tuottaakseen hänelle onnettomuuden, kaikki ne kiroukset, jotka sisältyvät tähän lainkirjaan kirjoitettuun liittoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Tuleva sukupolvi, lapsenne, jotka nousevat teidän jälkeenne, ja vieras, joka tulee kaukaisesta maasta, kysyvät [syytä] nähdessään sen maan vaivat ja ne sairaudet, joilla Herra sitä rasittaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'rikin ja suolan, kun koko maa on poltettu, niin ettei siihen kylvetä eikä se kasva eikä siitä nouse ruohonkortta, niin kuin oli silloin, kun Sodoma ja Gomorra, Adma ja Seboim hävitettiin, kun Herra vihassaan ja kiivastuksessaan hävitti ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'Kaikki kansat kysyvät: \'Minkä tähden Herra on näin tehnyt tälle maalle? Mistä tämä hänen suuri vihansa hehku?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Silloin vastataan: \'Siitä, että he hylkäsivät Herran, isiensä Jumalan, liiton, jonka hän teki heidän kanssaan viedessään heidät pois Egyptin maasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'ja menivät palvelemaan muita jumalia ja kumarsivat niitä, jumalia, joita eivät tunteneet ja joita hän ei ollut heidän osalleen jakanut –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'siitä syttyi Herran viha tätä maata kohtaan, niin että hän antoi kohdata sitä kaiken sen kirouksen, joka on kirjoitettu tähän kirjaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Herra tempasi heidät irti heidän maastaan vihassa ja kiivastuksessa ja suuressa suuttumuksessa ja heitti heidät toiseen maahan, niin kuin nyt on tapahtunut.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Se, mikä on salassa, on Herran, Jumalamme. Mutta mikä on ilmoitettu, on meitä ja lapsiamme varten ikuisesti, että pitäisimme kaikki tämän lain sanat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, '\"Jos sinä silloin, kun tämä kaikki sinua kohtaa, siunaus tai kirous, jotka minä olen asettanut valittavaksesi, painat sen sydämeesi kaikkien kansojen keskellä, joiden luo Herra, Jumalasi, on sinut karkottanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'ja palaat Herran, Jumalasi, luo ja kuulet hänen ääntään kaikesta sydämestäsi ja kaikesta sielustasi, sinä itse ja lapsesi, kaikessa, niin kuin minä tänä päivänä sinua käsken,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'niin Herra, Jumalasi, kääntää kohtalosi ja armahtaa sinua. Herra, Jumalasi, kokoaa sinut jälleen kaikista kansoista, joiden sekaan hän on hajottanut sinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Vaikka sinun karkotettusi olisivat taivaan äärissä, niin Herra, Jumalasi, kokoaa ja noutaa sinut sieltäkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'Herra, Jumalasi, tuo sinut siihen maahan, jonka isäsi ovat omistaneet, ja otat sen omaksesi, ja hän tekee sinulle hyvää ja antaa sinun lisääntyä enemmän kuin isiesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Herra, Jumalasi, ympärileikkaa sydämesi ja jälkeläistesi sydämet, niin että rakastat Herraa, Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi sinulle elämäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Herra, Jumalasi, antaa kaikkien näiden kirousten kohdata vihollisiasi ja vihamiehiäsi, jotka sinua vainosivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Sinä kuulet jälleen Herran ääntä ja pidät kaikki hänen käskynsä, jotka minä tänä päivänä sinulle annan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Herra, Jumalasi, antaa sinulle hyvin runsaasti hyvää kaikissa kättesi töissä. Hän tekee hyvin runsaaksi kohtusi hedelmän, karjasi hedelmän ja maasi hedelmän. Sillä niin kuin Herra iloitsi isistäsi, hän jälleen iloitsee sinusta, siitä, että hän tekee sinulle hyvää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'kun sinä kuulet Herran, Jumalasi, ääntä ja noudatat hänen käskyjään ja säädöksiään, jotka ovat kirjoitetut tähän lain kirjaan, ja kun sinä palaat Herran, Jumalasi, luo kaikesta sydämestäsi ja kaikesta sielustasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Sillä tämä käsky, jonka minä tänä päivänä sinulle annan, ei ole sinulle vaikea täyttää eikä liian kaukana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Se ei ole taivaassa, eikä sinun tarvitse sanoa: \'Kuka nousisi puolestamme taivaaseen noutamaan sen meille ja julistaisi sen meille, että sen täyttäisimme?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Se ei ole meren takana, eikä sinun tarvitse sanoa: \'Kuka menisi puolestamme meren taakse noutamaan sen meille ja julistaisi sen meille, että sen täyttäisimme?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Vaan sana on sinua aivan lähellä, sinun suussasi ja sydämessäsi, niin että voit sen täyttää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Katso, minä panen tänä päivänä eteesi elämän ja hyvän, kuoleman ja pahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'kun minä tänä päivänä käsken sinua rakastamaan Herraa, Jumalaasi, ja vaeltamaan hänen teitään ja noudattamaan hänen käskyjään, säädöksiään ja oikeuksiaan, että eläisit ja lisääntyisit ja että Herra, Jumalasi, siunaisi sinua siinä maassa, jota menet ottamaan omaksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Mutta jos sydämesi kääntyy pois etkä tottele, vaan annat vietellä itsesi kumartamaan muita jumalia ja palvelemaan niitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'julistan teille tänä päivänä, että te totisesti hukutte. Te ette kauan elä siinä maassa, johon sinä menet Jordanin yli, ottamaan sen omaksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Minä otan tänä päivänä taivaan ja maan todistajiksi teitä vastaan, että minä olen pannut eteesi elämän ja kuoleman, siunauksen ja kirouksen. Valitse elämä, että sinä ja sinun jälkeläisesi eläisitte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'Rakasta Herraa, Jumalaasi, kuule hänen ääntään ja riipu hänessä kiinni, sillä siinä on elämäsi ja pitkä ikäsi asuaksesi siinä maassa, jonka Herra sinun isillesi, Aabrahamille, Iisakille ja Jaakobille, vannotulla valalla on luvannut heille antaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Sitten Mooses meni ja puhui kaikelle Israelille nämä sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'Hän sanoi heille: \"Minä olen nyt sadan kahdenkymmenen vuoden vanha. En voi enää mennä ja tulla, ja Herra on sanonut minulle: \'Sinä et mene tämän Jordanin yli.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Mutta Herra, Jumalasi, kulkee edelläsi. Hän tuhoaa nämä kansat tieltäsi, ja sinä lasket heidät valtasi alle. Joosua kulkee edelläsi, kuten Herra on puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Herra tekee heille, niin kuin hän teki Siihonille ja Oogille, tuhoamilleen amorilaisten kuninkaille, ja heidän maalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Herra antaa heidät teille alttiiksi. Tehkää heille kaikessa sen käskyn mukaan, jonka olen teille käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Olkaa lujat ja rohkeat. Älkää pelätkö älkääkä säikähtäkö heitä, sillä Herra, Jumalasi, käy itse sinun kanssasi. Hän ei jätä eikä hylkää sinua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Mooses kutsui Joosuan ja sanoi hänelle koko Israelin läsnä ollessa: \"Ole luja ja rohkea, sillä sinä viet tämän kansan siihen maahan, jonka Herra heidän isilleen vannotulla valalla on luvannut antaa heille. Sinä jaat sen heille perinnöksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Herra itse käy edelläsi. Hän on kanssasi, hän ei jätä sinua eikä hylkää sinua. Älä pelkää äläkä arkaile.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Mooses kirjoitti tämän lain ja antoi sen papeille, leeviläisille, jotka kantoivat Herran liitonarkkia, ja kaikille Israelin vanhimmille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Mooses käski heitä sanoen: \"Joka seitsemäs vuosi, määrättynä aikana vapautusvuonna, lehtimajanjuhlassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'kun koko Israel tulee Herran, Jumalasi, kasvojen eteen siinä paikassa, jonka hän valitsee, lue tämä laki koko Israelin läsnä ollessa, heidän kuultensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Kokoa kansa, miehet, naiset ja lapset sekä muukalaiset, jotka asuvat porttiesi sisäpuolella, että he kuulisivat sen ja oppisivat pelkäämään Herraa, Jumalaanne, ja tarkasti pitämään kaikki tämän lain sanat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'ja että heidän lapsensa, jotka eivät vielä sitä tunne, kuulisivat sen ja oppisivat pelkäämään Herraa, Jumalaanne, niin kauan kuin elätte siinä maassa, johon menette Jordanin yli, ottamaan sen omaksenne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Herra sanoi Moosekselle: \"Katso, lähestyy aika, jolloin sinun on kuoltava. Kutsu Joosua, ja asettukaa ilmestysmajaan, niin minä asetan hänet virkaansa.\" Niin Mooses ja Joosua menivät ja asettuivat ilmestysmajaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Niin Herra ilmestyi majassa pilvenpatsaassa, ja pilvenpatsas seisahtui majan ovelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Herra sanoi Moosekselle: \"Katso, sinä käyt lepäämään isiesi luo. Silloin tämä kansa nousee ja lähtee haureudessa kulkemaan vieraiden jumalien perässä, joita palvellaan siinä maassa, johon se menee, ja hylkää minut ja rikkoo liiton, jonka minä olen tehnyt sen kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Sinä päivänä minun vihani syttyy sitä vastaan, ja minä hylkään heidät ja peitän kasvoni heiltä, niin että he joutuvat tuhon omiksi, ja suuret onnettomuudet ja ahdistukset kohtaavat sitä. Sinä päivänä se sanoo: \'Eivätkö nämä onnettomuudet ole kohdanneet minua sen tähden, ettei minun Jumalani ole keskuudessani?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Mutta sinä päivänä minä kokonaan peitän kasvoni kaiken sen pahan tähden, mitä he ovat tehneet, kun ovat kääntyneet muiden jumalien puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Kirjoittakaa nyt itsellenne tämä virsi. Opeta se israelilaisille ja pane se heidän suuhunsa, että tämä laulu olisi minulle todistajana israelilaisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Sillä minä vien heidät siihen maahan, jonka minä valalla vannoen olen luvannut heidän isilleen, maahan, joka vuotaa maitoa ja hunajaa, ja he syövät ja tulevat ravituiksi ja lihaviksi. Mutta he kääntyvät muiden jumalien puoleen ja palvelevat niitä ja pitävät pilkkanaan minua ja rikkovat liittoni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Kun suuret onnettomuudet ja ahdistukset kohtaavat heitä, tämä laulu on oleva todistajana heitä vastaan, eikä se unohdu heidän jälkeläistensä suusta. Sillä minä tiedän heidän aikeensa, joita he hautovat jo ennen kuin minä olen vienyt heidät siihen maahan, josta minä olen valan vannonut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Mooses kirjoitti tämän laulun sinä päivänä ja opetti sen israelilaisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Hän asetti virkaan Joosuan, Nuunin pojan, ja [Herra] sanoi: \"Ole luja ja rohkea, sillä sinä viet israelilaiset siihen maahan, jonka minä valalla vannoen olen heille luvannut, ja minä olen kanssasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Kun Mooses oli kirjoittanut kirjaan tämän lain sanat alusta loppuun asti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'hän käski leeviläisiä, jotka kantoivat Herran liitonarkkia, sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, '\"Ottakaa tämä lain kirja ja pankaa se Herran, Jumalanne, liitonarkin viereen, olemaan siellä todistajana sinua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Sillä minä tunnen sinun tottelemattomuutesi ja uppiniskaisuutesi. Katso, minun vielä eläessäni teidän kanssanne te olette niskoitelleet Herraa vastaan, saati sitten kuoltuani!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Kootkaa luokseni kaikki sukukuntienne vanhimmat sekä päällysmiehenne, että minä heidän kuultensa puhuisin nämä sanat ja ottaisin taivaan ja maan todistajiksi heitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Sillä minä tiedän, että te minun kuoltuani vaellatte kelvottomasti ja poikkeatte siltä tieltä, jota minä käskin teidän vaeltaa. Sen tähden on onnettomuus kohtaava teitä aikojen lopulla, kun te teette sitä, mikä on pahaa Herran silmissä, ja vihoitatte hänet kättenne teoilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Sitten Mooses lausui koko Israelin seurakunnan kuullen tämän virren sanat alusta loppuun asti:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, '\"Kuunnelkaa, te taivaat, kun minä puhun, ja kuulkoon maa suuni sanat!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Sateena pisaroikoon opetukseni, kasteena valukoon puheeni kuin vihma vihannalle, kuin sadekuuro ruohikolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Sillä minä julistan Herran nimeä. Antakaa kunnia meidän Jumalallemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Hän on kallio. Täydelliset ovat hänen tekonsa, sillä kaikki hänen tiensä ovat oikeat. Uskollinen Jumala ja ilman vääryyttä, vanhurskas ja vakaa hän on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Heidän menonsa oli paha häntä kohtaan, he eivät olleet hänen lapsiaan, vaan häpeäpilkku – tuo nurja ja kiero sukupolvi!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Niinkö sinä maksat Herralle, sinä houkka ja tyhmä kansa? Eikö hän ole sinun isäsi, joka sinut loi? Hän sinut teki ja valmisti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Muistele muinaisia päiviä, ajattele menneiden sukupolvien vuosia. Kysy isältäsi, niin hän sen sinulle ilmoittaa, vanhoilta, niin he sen sinulle sanovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Kun Korkein jakoi perinnöt kansoille, kun hän erotteli ihmisten lapset, silloin hän määräsi kansojen rajat israelilaisten luvun mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Sillä Herran kansa on hänen osuutensa, Jaakob on hänen perintöosansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Erämaasta hän löysi sen, autiosta, ulvovasta korvesta. Hän otti sen suojaansa ja hoitoonsa ja varjeli sitä kuin silmäteräänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Niin kuin kotka kiihottaa pesuettaan lentoon ja liitelee poikastensa suojana, niin hän levitti siipensä, otti sen luokseen ja kantoi sitä sulillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Herra yksin johdatti sitä, eikä hänen kanssaan ollut ketään vierasta jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Hän kuljetti sen maan kukkuloiden yli ja ruokki sitä pellon antimilla. Hän antoi sen imeä hunajaa kalliosta ja öljyä kovasta kivestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Hän antoi voita lehmistä ja maitoa lampaista sekä karitsojen ja pässien rasvaa, Baasanin härkiä ja vuohipukkeja ja parasta vehnän ydintä. Sinä sait juoda rypäleen verta, tulista viiniä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Jesurun lihoi ja alkoi potkia, sinä tulit lihavaksi, paksuksi ja aloit äksyillä. Niin se hylkäsi Jumalan, joka oli sen tehnyt, ja halveksui pelastuksensa kalliota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'He herättivät hänen kiivautensa vierailla jumalillaan. He vihoittivat hänet kauhistuksillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'He uhrasivat riivaajille, epäjumalille, jumalille, joita he eivät tunteneet, uusille, äsken tulleille, joista isänne eivät tienneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Kalliota, joka sinut synnytti, sinä et muistanut. Sinä unohdit Jumalan, joka antoi sinulle elämän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Herra näki sen ja hylkäsi heidät, sillä hän vihastui poikiinsa ja tyttäriinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Hän sanoi: \'Minä peitän heiltä kasvoni, minä katson, mikä heidän loppunsa on. Sillä he ovat nurja suku, lapsia, joissa ei ole uskollisuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'He ovat herättäneet minun kiivauteni jumalilla, jotka eivät ole jumalia, ovat vihoittaneet minut turhilla jumalillaan. Niin minäkin herätän heidän kiivautensa kansalla, joka ei ole kansa. Vihoitan heidät houkalla pakanakansalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Sillä minun vihani tuli on syttynyt, ja se leimuaa helvetin syvyyksiin saakka. Se kuluttaa maan kasvuineen ja polttaa vuorten perustukset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Minä kasaan onnettomuuksia heidän päälleen, kaikki nuoleni minä ammun heihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'He nääntyvät nälkään ja menehtyvät ruttoon, kulkutautien poltteeseen. Minä lähetän heidän kimppuunsa petojen hampaat ja tomussa matelevaisten myrkyn.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Ulkona surmaa miekka ja sisällä kauhu sekä nuorukaisen että neitsyen, sekä imeväisen että harmaapään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Minä sanoisin: \'Minä puhallan heidät pois, hävitän heidän muistonsa ihmisten seasta\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'jollen varoisi, että vihollinen tuottaisi minulle mielipahaa, että heidän vastustajansa selittäisivät sen väärin, että he sanoisivat: \'Meidän kätemme oli korotettu, eikä Herra ole tästä kaikesta mitään tehnyt.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Sillä he ovat neuvoton kansa, eikä heissä ole ymmärrystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Jos he olisivat viisaita, he käsittäisivät tämän, he ymmärtäisivät, mikä on heidän loppunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Kuinka yksi ajaisi tuhatta takaa, kuinka kaksi ajaisi pakoon kymmenentuhatta, jollei heidän kallionsa olisi heitä myynyt ja Herra luovuttanut heitä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Sillä heidän kallionsa ei ole kuin meidän kalliomme. Niin vihollisemmekin päättelevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Sillä Sodoman viinipuita on heidän viinipuunsa. Se on kotoisin Gomorran viinitarhoista. Heidän rypäleensä ovat myrkkyrypäleitä, heidän viiniterttujensa maku on karvas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Heidän viininsä on lohikäärmeitten kähyä, kyykäärmeitten kauheaa myrkkyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Eikö sitä ole talletettuna minun takanani, sinetillä lukittuna aitoissani?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Minun on kosto ja rankaiseminen, säästetty siksi ajaksi, jolloin heidän jalkansa horjuu. Sillä heidän onnettomuutensa päivä on lähellä, ja se, mikä heitä odottaa, tulee rientäen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Sillä Herra hankkii oikeuden kansalleen ja armahtaa palvelijoitaan. Hän näet näkee, että heidän voimansa on poissa ja että kaikki tyynni on lopussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Silloin hän kysyy: \'Missä ovat nyt niiden jumalat, missä kallio, johon he turvasivat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'missä ne, jotka söivät heidän teurasuhriensa rasvan ja joivat heidän juomauhriensa viinin?\' Nouskoot he auttamaan teitä, olkoot he teidän suojananne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Katsokaa nyt, että minä, minä se olen, eikä yhtään jumalaa ole minun rinnallani. Minä kuoletan ja minä teen eläväksi, minä lyön ja minä parannan. Eikä ole ketään, joka pelastaisi minun käsistäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Minä nostan käteni taivasta kohti ja sanon: Niin totta kuin minä elän iankaikkisesti, kun minä terotan miekkani salaman,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'kun minun käteni ryhtyy pitämään tuomiota, niin minä kostan vastustajilleni ja maksan vihamiehilleni. Minä annan nuolteni juopua verestä –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'ja minun miekkani syö lihaa – surmattujen ja vangittujen verestä, vihollispäällikköjen päistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Riemuiten ylistäkää, te pakanakansat, hänen kansaansa, sillä hän kostaa palvelijoittensa veren. Hän antaa koston kohdata vastustajiaan ja toimittaa sovituksen maalleen, kansalleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Mooses tuli ja lausui kaikki tämän virren sanat kansan kuullen, hän itse ja Joosua, Nuunin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Kun Mooses oli puhunut loppuun kaikki nämä sanat koko Israelille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'hän sanoi heille: \"Painakaa sydämiinne kaikki ne sanat, jotka minä tänä päivänä teen todistajiksi teitä vastaan, niin että käskette lapsianne tarkasti täyttämään kaikki tämän lain sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Sillä se ei ole turha sana, joka ei koskisi teitä, vaan siinä on teidän elämänne. Sen sanan varassa te elätte kauan siinä maassa, johon te menette Jordanin yli ottamaan sen omaksenne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Herra puhui Moosekselle sinä samana päivänä sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, '\"Nouse tänne Abarimin vuoristoon, Nebon vuorelle, joka on Mooabin maassa vastapäätä Jerikoa, ja katsele Kanaanin maata, jonka minä annan israelilaisten omaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Sinä kuolet sillä vuorella, jolle nouset, ja tulet otetuksi heimosi luo, niin kuin veljesi Aaron kuoli Hoorin vuorella ja tuli otetuksi heimonsa luo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'koska te lankesitte uskottomuuteen minua kohtaan israelilaisten keskellä Meriban veden ääressä Kaadeksessa, Siinin erämaassa, kun ette pitäneet minua pyhänä israelilaisten keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Niin, sinä saat katsella sitä maata matkan päästä, mutta sinne sinä et pääse, siihen maahan, jonka minä annan israelilaisille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Tämä on se siunaus, jolla Jumalan mies Mooses siunasi israelilaiset ennen kuolemaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Hän sanoi: \" Herra tuli Siinailta, Seiristä hän nousi loistaen heille. Hän ilmestyi kirkkaudessa Paaranin vuoristosta, hän tuli kymmentuhantisesta pyhien joukosta. Hänen oikealla puolellaan liekehti lain tuli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Hän rakastaa kansoja. Kaikki niiden pyhät ovat kädessäsi. He asettuvat jalkojesi juureen, ottavat oppia sanoistasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Mooses antoi meille lain, perintönä Jaakobin seurakunnalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Herra tuli kuninkaaksi Jesurunissa, kun kansan päämiehet kokoontuivat, kaikki Israelin sukukunnat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Ruuben eläköön, älköön hän kuolko, mutta vähäiseksi jääköön hänen miestensä joukko.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Tämän hän sanoi Juudasta: \"Kuule, Herra, Juudan huuto ja tuo hänet kansansa luo. Hän taisteli sen puolesta käsillään. Ole sinä apuna hänen vihollisiaan vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Leevistä hän sanoi: \"Sinun tummimisi ja uurimisi olkoot hurskaasi omat, sen miehen, jota sinä Massassa koettelit, jonka kanssa sinä riitelit Meriban veden luona,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'joka sanoi isästään ja äidistään: \'Minä en heitä nähnyt\', ja joka ei tunnustanut veljiään omikseen eikä tuntenut omia lapsiaan. Sillä he noudattivat sinun sanaasi ja pysyivät liitossasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'He opettavat säädöksesi Jaakobille ja Israelille lakisi. He panevat suitsutusta eteesi ja kokonaisuhreja alttarillesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Siunaa, Herra, hänen voimansa, ja olkoon hänen kättensä työ sinulle otollinen. Ruhjo hänen vastustajiensa lanteet ja hänen vihamiehensä niin, etteivät he enää nouse.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Benjaminista hän sanoi: \" Herran rakkaana hän asuu hänen turvissaan. Herra suojelee häntä aina ja asuu hänen kukkuloittensa välissä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Joosefista hän sanoi: \" Herra siunatkoon hänen maansa kalleimmalla, kasteella, joka tulee taivaasta, kalleimmalla, mikä tulee syvyydestä alhaalta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'kalleimmalla, minkä aurinko antaa, kalleimmalla, minkä kuun vaiheet tuottavat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'kalleimmalla, mikä tulee ikivuorten huipuilta, kalleimmalla, mikä tulee ikikukkuloilta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'kalleimmalla, minkä maa kasvaa, ja kaikella, mitä siinä on, ja mielisuosiollaan, hän, joka pensaassa asui. Ne laskeutukoot Joosefin pään päälle, hänen päälaelleen, hänen, joka on ruhtinas veljiensä joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Uljas on hänen härkiensä esikoinen, sen sarvet ovat kuin re\'eem-eläimen sarvet. Niillä se puskee kumoon kansat, kaikki tyynni maan ääriin asti. Sellaisia ovat Efraimin kymmenet tuhannet, sellaisia Manassen tuhannet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Sebulonista hän sanoi: \"Iloitse, Sebulon, kun liikkeelle lähdet, ja sinä, Isaskar, majoissasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'He kutsuvat kansoja vuorelleen, siellä he uhraavat oikeita uhreja. Sillä he imevät merten rikkauden ja hiekkaan kätketyt aarteet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Gaadista hän sanoi: \"Kiitetty olkoon hän, joka on niin laajentanut Gaadin. Kuin naarasleijona hän asettuu leposijaansa ja raatelee sekä käsivarren että päälaen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Hän katsoi itselleen parhaan osan maata, sillä siellä oli hänelle johtajan osa varattu. Mutta hän tuli kansan päämiesten kanssa, pani toimeen Herran vanhurskauden ja hänen tuomionsa yhdessä muun Israelin kanssa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Daanista hän sanoi: \"Daan on nuori leijona, joka syöksyy esiin Baasanista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Naftalista hän sanoi: \"Naftali on kylläinen mielisuosiosta ja täynnä Herran siunausta. Lännen ja etelän hän ottakoon omakseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Asserista hän sanoi: \"Siunattu olkoon Asser poikien joukossa. Olkoon hän veljiensä lemmikki, ja kastakoon hän jalkansa öljyyn.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Rautaa ja vaskea olkoot salpasi, ja niin kuin sinun päiväsi, niin olkoon voimasikin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Ei kukaan ole kuin Jesurunin Jumala, joka kulkee taivasten yli sinun apunasi ja korkeudessaan pilvien yltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Sinun turvasi on ikiaikojen Jumala, sinua kannattavat iankaikkiset käsivarret. Hän karkotti viholliset tieltäsi, hän sanoi: \'Hävitä!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Näin Israel asuu turvassa, Jaakobin lähde erillään viljan ja viinin maassa, jonka taivaskin pisaroi kastetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Autuas olet sinä, Israel! Kukapa on sinun vertaisesi! Sinä olet kansa, jota Herra auttaa, hän, joka on kilpesi ja suojasi, miekkasi ja korkeutesi. Vihollisesi mielistelevät sinua, ja sinä astelet heidän kukkuloillaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Mooses nousi Mooabin arolta Nebon vuorelle, Pisgan huipulle, vastapäätä Jerikoa. Herra näytti hänelle koko maan: Gileadin Daaniin asti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'koko Naftalin, Efraimin ja Manassen maan, koko Juudan maan aina Länsimereen asti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'Etelämaan sekä Lakeuden, se on Jerikon, Palmukaupungin, laakson, aina Sooariin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Herra sanoi hänelle: \"Tämä on se maa, jonka minä valalla vannoen olen luvannut Aabrahamille, Iisakille ja Jaakobille, sanoen: \'Sinun jälkeläisillesi minä annan sen.\' Minä olen nyt antanut sinun omin silmin nähdä sen, mutta sinne sinä et mene.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Herran palvelija Mooses kuoli siellä Mooabin maassa, Herran sanan mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Hän hautasi hänet laaksoon Mooabin maahan, vastapäätä Beet-Peoria, mutta ei kukaan ole saanut tietää hänen hautaansa tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Mooses oli kuollessaan sadan kahdenkymmenen vuoden vanha, mutta hänen silmänsä eivät olleet hämärtyneet, eikä hänen elinvoimansa ollut kadonnut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Israelilaiset itkivät Moosesta Mooabin arolla kolmekymmentä päivää. Sitten päättyi Mooseksen muistoksi vietetty itku- ja suruaika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Joosua, Nuunin poika, oli täynnä viisauden henkeä, sillä Mooses oli pannut kätensä hänen päälleen. Israelilaiset tottelivat häntä ja tekivät, niin kuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Mutta Israelissa ei enää noussut yhtään sellaista profeettaa kuin Mooses, jonka kanssa Herra seurusteli kasvoista kasvoihin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'ei ketään, joka olisi tehnyt sellaisia tunnustekoja ja ihmeitä, kuin hän Herran lähettämänä teki Egyptin maassa faraolle ja kaikille hänen palvelijoilleen, koko hänen maalleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'ei ketään, jolla olisi ollut niin väkevä käsi ja joka olisi tehnyt niin suuria, pelättäviä tekoja, kuin hän teki koko Israelin silmien edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Herran palvelijan Mooseksen kuoltua Herra puhui Joosualle, Nuunin pojalle, Mooseksen palvelijalle, sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, '\"Palvelijani Mooses on kuollut. Mutta nouse nyt ja mene Jordanin yli, sinä ja koko tämä kansa, siihen maahan, jonka minä annan heille, israelilaisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Jokaisen paikan, johon jalkanne astuu, annan teille, kuten olen Moosekselle puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Maa erämaasta ja tuolta Libanonilta aina suureen virtaan, Eufrat-virtaan, saakka, koko heettiläisten maa, ja aina Suureen mereen asti, auringonlaskuun päin, on oleva aluettanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Kukaan ei kestä edessäsi koko elinaikanasi. Niin kuin minä olin Mooseksen kanssa, olen sinunkin kanssasi. En jätä sinua enkä hylkää sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Ole luja ja rohkea. Sillä sinä jaat tälle kansalle perinnöksi sen maan, jonka olen heidän isilleen vannonut antavani heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Ole vain luja ja aivan rohkea ja noudata tarkasti kaikessa sitä lakia, jonka palvelijani Mooses on sinulle antanut. Älä poikkea siitä oikealle äläkä vasemmalle, että menestyisit, missä kuljet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Älköön tämä lain kirja poistuko suustasi, vaan tutki sitä päivät ja yöt, että noudattaisit kaikkea, mitä siihen on kirjoitettu, sillä silloin tiesi käy hyvin ja silloin menestyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Olenhan sinua käskenyt: Ole luja ja rohkea. Älä säikähdä äläkä arkaile, sillä Herra, Jumalasi, on kanssasi, missä kuljet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Silloin Joosua käski kansan päämiehiä sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, '\"Kulkekaa leirin halki ja käskekää kansaa sanoen: \'Valmistakaa itsellenne evästä, sillä kolmen päivän kuluttua te kuljette tämän Jordanin yli mennäksenne ottamaan omaksenne maan, jonka Herra, teidän Jumalanne, antaa teidän omaksenne.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Mutta ruubenilaisille, gaadilaisille ja toiselle puolelle Manassen sukukuntaa Joosua puhui sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, '\"Muistakaa sitä käskyä, jonka Herran palvelija Mooses käski teille sanoen: \' Herra, teidän Jumalanne, suo teidän päästä rauhaan ja antaa teille tämän maan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Vaimonne, lapsenne ja karjanne jääkööt siihen maahan, jonka Mooses antoi teille Jordanin tältä puolelta. Mutta teidän itsenne, kaikkien väkevien sankarien, on lähdettävä taisteluun valmiina veljienne etunenässä ja autettava heitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'kunnes Herra suo veljienne päästä rauhaan niin kuin teidänkin, ja hekin ottavat omakseen sen maan, jonka Herra, Jumalanne, heille antaa. Sitten saatte palata takaisin siihen maahan, joka on teidän omanne, ja ottaa omaksenne sen maan, jonka Herran palvelija Mooses antoi teille tältä puolelta Jordanin, päivänkoiton puolelta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Niin he vastasivat Joosualle sanoen: \"Kaiken, minkä olet käskenyt meille, teemme, ja mihin meidät lähetät, sinne menemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Niin kuin olemme kaikessa totelleet Moosesta, niin tottelemme sinuakin. Olkoon vain Herra, Jumalasi, kanssasi, niin kuin hän oli Mooseksen kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Jokainen, joka niskoittelee suusi puhetta vastaan eikä tottele sanojasi kaikessa, mitä hänelle käsket, surmattakoon. Ole vain luja ja rohkea.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Niin Joosua, Nuunin poika, lähetti salaa Sittimistä kaksi vakoojaa, sanoen: \"Menkää, katselkaa maata ja Jerikoa.\" Niin he menivät ja tulivat Rahab-nimisen porton taloon ja laskeutuivat siellä levolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Mutta Jerikon kuninkaalle kerrottiin näin: \"Katso, tänne on yöllä tullut miehiä israelilaisten joukosta vakoilemaan maata.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Silloin Jerikon kuningas lähetti sanan Rahabille: \"Tuo ulos ne miehet, jotka ovat tulleet luoksesi, jotka ovat tulleet taloosi, sillä he ovat tulleet vakoilemaan koko maata.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Mutta nainen otti molemmat miehet, piilotti heidät ja sanoi: \"Miehet kyllä tulivat luokseni, mutta en tiennyt, mistä he olivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'Kun kaupungin porttia oltiin pimeän tullen sulkemassa, miehet lähtivät ulos. En tiedä, minne miehet menivät. Ajakaa nopeasti heitä takaa, että saavutatte heidät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Mutta hän oli vienyt heidät katolle ja kätkenyt heidät pellavanvarsien alle, joita hän oli asetellut katolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Niin miehet ajoivat heitä takaa Jordanin tietä kahluupaikoille saakka, ja kaupungin portti suljettiin, heti kun heidän takaa-ajajansa olivat menneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Mutta ennen kuin he olivat laskeutuneet levolle, hän nousi heidän luokseen katolle ja sanoi miehille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, '\"Minä tiedän, että Herra antaa teille tämän maan ja että kauhu teitä kohtaan on vallannut meidät ja että kaikki maan asukkaat menehtyvät pelkoon edessänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Sillä olemme kuulleet, kuinka Herra kuivasi Kaislameren vedet tieltänne, kun lähditte Egyptistä, ja mitä teitte niille kahdelle amorilaisten kuninkaalle tuolla puolella Jordanin, Siihonille ja Oogille, jotka vihitte tuhon omiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Kun sen kuulimme, raukesi sydämemme, eikä kenelläkään ole enää rohkeutta asettua teitä vastaan. Sillä Herra, Jumalanne, on Jumala ylhäällä taivaassa ja alhaalla maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Niin vannokaa nyt minulle Herran kautta, että niin kuin olen tehnyt teille laupeuden, tekin teette laupeuden isäni perheelle. Antakaa minulle varma merkki siitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'että jätätte eloon isäni, äitini, veljeni, sisareni ja kaikki heidän omaisensa ja pelastatte meidät kuolemasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Niin miehet sanoivat hänelle: \"Me vastaamme hengellämme hengestänne, kunhan vain ette ilmaise tätä meidän asiaamme. Kun Herra antaa meille tämän maan, niin osoitamme sinulle laupeutta ja uskollisuutta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Hän laski heidät köydellä alas ikkunasta, sillä hänen talonsa oli kiinni kaupungin muurissa, niin että hän asui muurissa kiinni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Hän sanoi heille: \"Menkää vuoristoon, etteivät takaa-ajajat kohtaisi teitä, ja olkaa siellä piilossa kolme päivää, kunnes takaa-ajajat ovat palanneet. Sitten voitte lähteä matkaanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Niin miehet sanoivat hänelle: \"Me olemme vapaat siitä valasta, jonka meillä vannotit,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'jollet sinä, kun tulemme tähän maahan, sido tätä punaista nauhaa siihen ikkunaan, josta laskit meidät alas, ja kokoa isääsi, äitiäsi, veljiäsi ja isäsi koko perhettä luoksesi taloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Kuka vain menee talosi ovesta ulos, sen veri tulkoon hänen oman päänsä päälle, ja me olemme vastuusta vapaat. Mutta kuka vain on kanssasi talossa, sen veri tulkoon meidän päämme päälle, jos kenen tahansa käsi sattuu häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Mutta jos sinä ilmaiset tämän asiamme, niin me olemme vapaat valasta, jonka meillä vannotit.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Niin hän sanoi: \"Olkoon, niin kuin sanotte\", ja hän päästi heidät menemään, ja he lähtivät. Hän sitoi punaisen nauhan ikkunaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Niin he lähtivät ja tulivat vuoristoon ja viipyivät siellä kolme päivää, kunnes takaa-ajajat olivat palanneet. Takaa-ajajat etsivät heitä kaikkialta tien varrelta, mutta eivät löytäneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Sitten nuo kaksi miestä kääntyivät paluumatkalle. He laskeutuivat alas vuoristosta, menivät virran yli ja tulivat Joosuan, Nuunin pojan, luo ja kertoivat hänelle kaiken, mitä heille oli tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'He sanoivat Joosualle: \" Herra on antanut koko maan käsiimme, ja kaikki maan asukkaat menehtyvät pelkoon edessämme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Niin Joosua nousi varhain seuraavana aamuna, ja he lähtivät liikkeelle Sittimistä ja tulivat Jordanille, hän ja kaikki israelilaiset. He olivat siellä yötä, ennen kuin menivät virran yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Mutta kolmen päivän kuluttua päällysmiehet kulkivat leirin halki');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'ja käskivät kansaa sanoen: \"Kun näette Herran, Jumalanne, liitonarkin ja leeviläiset papit sitä kantamassa, niin lähtekää tekin liikkeelle paikoiltanne ja seuratkaa sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Kuitenkin olkoon noin kahdentuhannen kyynärän välimatka teidän ja sen välillä – älkää menkö sitä lähelle – että tietäisitte tien, jota teidän on kuljettava, sillä te ette ole ennen menneet sitä tietä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Joosua sanoi kansalle: \"Pyhittäytykää, sillä huomenna Herra tekee ihmeellisiä tekoja teidän keskuudessanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Mutta papeille Joosua puhui sanoen: \"Ottakaa liitonarkki ja kulkekaa kansan edellä.\" Niin he ottivat liitonarkin ja kulkivat kansan edellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Silloin Herra sanoi Joosualle: \"Tästä päivästä alkaen minä teen sinut suureksi koko Israelin silmissä, jotta he tietäisivät, että niin kuin minä olin Mooseksen kanssa, niin minä olen sinunkin kanssasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Käske pappeja, jotka kantavat liitonarkkia, ja sano: \'Kun tulette Jordanin veden ääreen, niin pysähtykää Jordanin rantaan.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Sitten Joosua sanoi israelilaisille: \"Tulkaa tänne ja kuulkaa Herran, Jumalanne, sanat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Joosua sanoi: \"Tästä saatte tietää, että elävä Jumala on keskellänne ja karkottaa tieltänne kanaanilaiset, heettiläiset, hivviläiset, perissiläiset, girgasilaiset, amorilaiset ja jebusilaiset:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'katso, kaiken maan Herran liitonarkki kulkee edellänne Jordanin poikki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Ottakaa siis kaksitoista miestä Israelin sukukunnista, yksi mies kustakin sukukunnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Niin pian kuin papit, jotka kantavat Herran, kaiken maan Herran, liitonarkkia, laskevat jalkansa Jordanin veteen, katkeaa Jordanin vesi, ylhäältä päin virtaava vesi, juoksussaan ja pysähtyy röykkiöksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Kun kansa sitten lähti liikkeelle teltoistaan mennäkseen Jordanin poikki, liitonarkkia kantavien pappien kulkiessa kansan edellä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'ja niin pian kuin liitonarkin kantajat tulivat Jordanille ja liitonarkkia kantavien pappien jalat painuivat rantaveteen, niin vaikka Jordan koko elonleikkuuajan tulvii yli kaikkien äyräidensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'pysähtyi ylhäältä päin virtaava vesi ja seisoi yhtenä röykkiönä hyvin kaukana Adamin luona, sen kaupungin, joka on Saaretanin vieressä. Vesi, joka virtasi alaspäin Aromereen, Kuolleeseen mereen, hävisi kokonaan. Niin kansa kulki virran yli Jerikon kohdalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Herran liitonarkkia kantavat papit seisoivat alallaan kuivalla pohjalla keskellä Jordania, koko Israelin kulkiessa kuivaa myöten, kunnes kaikki kansa oli ehtinyt kulkea Jordanin yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Kun koko kansa oli ehtinyt kulkea Jordanin yli, Herra puhui Joosualle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, '\"Ottakaa kansasta kaksitoista miestä, kustakin sukukunnasta yksi mies,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'ja käskekää heitä sanoen: \'Ottakaa itsellenne tästä, keskeltä Jordania, siltä kohdalta, missä papit seisovat paikoillaan, kaksitoista kiveä ja viekää ne mukananne ja asettakaa ne siihen paikkaan, mihin jäätte seuraavaksi yöksi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Niin Joosua kutsui ne kaksitoista miestä, jotka hän oli määrännyt otettaviksi israelilaisista, yhden miehen kustakin sukukunnasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'ja Joosua sanoi heille: \"Menkää Herran, Jumalanne, arkin eteen keskelle Jordania, ja nostakoon kukin kiven olalleen israelilaisten sukukuntien luvun mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'että ne olisivat merkkinä teidän keskellänne. Kun lapsenne vastaisuudessa kysyvät ja sanovat: \'Mitä nämä kivet merkitsevät?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'niin vastatkaa heille: \'Sitä, että Jordanin vedet katkesivat Herran liitonarkin edessä. Kun se kulki Jordanin poikki, Jordanin vedet katkesivat juoksussaan. Siitä nämä kivet ovat muistona israelilaisille ikiajoiksi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Israelilaiset tekivät, kuten Joosua oli käskenyt, ja ottivat israelilaisten sukukuntien luvun mukaan kaksitoista kiveä keskeltä Jordania, niin kuin Herra oli puhunut Joosualle. He veivät ne mukanaan yöpymispaikkaan ja asettivat ne sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Joosua pystytti kaksitoista [muuta] kiveä keskelle Jordania sille kohdalle, jossa liitonarkkia kantavat papit seisoivat. Siellä ne ovat vielä tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Papit, jotka kantoivat arkkia, seisoivat keskellä Jordania, kunnes oli suoritettu kaikki, mitä Herra oli käskenyt Joosuan puhua kansalle, kaikki tyynni, mistä Mooses oli Joosualle käskyn antanut. Sitten kansa kulki nopeasti virran yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Kun koko kansa oli ehtinyt kulkea virran yli, menivät Herran arkki ja papit yli, kansan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa kulkivat taisteluvalmiina israelilaisten etunenässä, niin kuin Mooses oli heille puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Heitä kulki noin neljäkymmentätuhantinen sotaan varustettu joukko Herran edellä taisteluun Jerikon arolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'Sinä päivänä Herra teki Joosuan suureksi koko Israelin silmissä. He pelkäsivät häntä koko hänen elinaikansa, niin kuin olivat pelänneet Moosesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Herra puhui Joosualle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, '\"Käske pappien, jotka kantavat lain arkkia, astua ylös Jordanista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Niin Joosua käski pappeja sanoen: \"Astukaa ylös Jordanista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Kun nyt Herran liitonarkkia kantavat papit astuivat ylös Jordanista, niin tuskin olivat pappien jalat nousseet kuivalle maalle, kun Jordanin vesi palasi paikoilleen ja juoksi kuten ennenkin yli kaikkien äyräidensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Kansa astui ylös Jordanista ensimmäisen kuun kymmenentenä päivänä. He leiriytyivät Gilgaliin, Jerikon itäiselle rajalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Ne kaksitoista kiveä, jotka he olivat ottaneet Jordanista, Joosua pystytti Gilgaliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Hän puhui israelilaisille sanoen: \"Kun lapsenne vastaisuudessa kysyvät isiltään ja sanovat: \'Mitä nämä kivet merkitsevät?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'niin ilmoittakaa se lapsillenne ja sanokaa: \'Israel kulki tämän Jordanin poikki kuivaa myöten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'koska Herra, Jumalanne, kuivasi Jordanin veden tieltänne, kunnes olitte kulkeneet virran poikki, samoin kuin Herra, Jumalanne, teki Kaislamerelle, jonka hän kuivasi tieltämme, kunnes olimme kulkeneet sen poikki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'Hän teki niin, jotta kaikki maan kansat tulisivat tietämään, että Herran käsi on väkevä, ja jotta te pelkäisitte Herraa, Jumalaanne, ainiaan.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Kun kaikki amorilaisten kuninkaat, jotka asuivat Jordanin tällä puolella, lännen puolella, ja kaikki kanaanilaisten kuninkaat, jotka asuivat meren rannalla, kuulivat, kuinka Herra oli kuivannut Jordanin veden israelilaisten tieltä, kunnes he olivat kulkeneet yli, niin raukesi heidän sydämensä, eikä heillä enää ollut rohkeutta asettua israelilaisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Siihen aikaan Herra sanoi Joosualle: \"Tee itsellesi kiviveitsiä ja ympärileikkaa taas israelilaiset toistamiseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Niin Joosua teki itselleen kiviveitsiä ja ympärileikkasi israelilaiset Esinahkakukkulan luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Syy siihen, että Joosua toimitti ympärileikkauksen, oli tämä: koko kansa, joka oli lähtenyt Egyptistä, miespuoliset, kaikki sotakuntoiset miehet, olivat kuolleet matkalla erämaassa heidän lähdettyään Egyptistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Sillä kaikki se kansa, joka oli lähtenyt, oli ollut ympärileikattu, mutta sitä kansaa, joka oli syntynyt matkalla erämaassa, heidän lähdettyään Egyptistä, ei ollut ympärileikattu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Sillä neljäkymmentä vuotta olivat israelilaiset vaeltaneet erämaassa, kunnes oli hävinnyt koko se kansa, ne sotakuntoiset miehet, jotka olivat lähteneet Egyptistä, ne, jotka eivät olleet totelleet Herran ääntä ja joille Herra sen tähden oli vannonut, ettei hän ollut salliva heidän nähdä sitä maata, jonka Herra heidän isilleen vannotulla valalla oli luvannut antaa meille, sitä maata, joka vuotaa maitoa ja hunajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Mutta hän herätti heidän poikansa heidän sijaansa. Ne Joosua ympärileikkasi, sillä he olivat ympärileikkaamattomia, koska heitä ei ollut ympärileikattu matkalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Kun koko kansa oli saatu ympärileikatuksi, he pysyivät paikallaan leirissä, kunnes olivat toipuneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Niin Herra sanoi Joosualle: \"Tänä päivänä minä olen vierittänyt päältänne Egyptin häväistyksen.\" Sen tähden kutsutaan paikkaa vielä tänäkin päivänä Gilgaliksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Kun israelilaiset olivat leiriytyneet Gilgaliin, he viettivät sen kuukauden neljäntenätoista päivänä, illalla, pääsiäistä Jerikon arolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Pääsiäisen jälkeisenä päivänä he söivät sen maan tuotteista happamatonta leipää ja paahdettuja jyviä, juuri sinä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Mutta seuraavana päivänä lakkasi manna, koska he söivät sen maan tuotteita, eivätkä israelilaiset enää saaneet mannaa, vaan he söivät sinä vuonna Kanaanin maan satoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Tapahtui Joosuan ollessa Jerikon luona, että hän nosti silmänsä ja näki miehen seisovan edessään, paljastettu miekka kädessä. Joosua meni hänen luokseen ja sanoi hänelle: \"Oletko sinä meikäläisiä vai vihollisiamme?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Niin hän sanoi: \"En, vaan minä olen Herran sotajoukon Päällikkö ja olen juuri nyt tullut.\" Niin Joosua heittäytyi kasvoilleen maahan, kumarsi ja sanoi hänelle: \"Mitä herrallani on sanottavana palvelijalleen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Herran sotajoukon Päällikkö sanoi Joosualle: \"Riisu kengät jalastasi, sillä paikka, jossa seisot, on pyhä.\" Joosua teki niin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Mutta Jeriko sulki porttinsa ja oli suljettuna israelilaisilta: ei kukaan kulkenut siitä ulos, eikä kukaan kulkenut sisälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Niin Herra sanoi Joosualle: \"Katso, minä annan käsiisi Jerikon sekä sen kuninkaan ja väkevät sankarit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Kulkekaa siis, kaikki sotakuntoiset miehet, kaupungin ympäri. Kiertäkää kerran kaupunki ympäri. Tee niin kuutena päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Seitsemän pappia kantakoon seitsemää pässinsarvista tehtyä torvea arkin edellä. Seitsemäntenä päivänä kulkekaa kaupungin ympäri seitsemän kertaa, ja papit puhaltakoot torviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Kun kuuluu pitkä pässin sarven puhallus, kun kuulette torven äänen, koko kansa nostakoon kovan sotahuudon. Silloin kaupungin muuri luhistuu siihen paikkaan, ja kansa voi rynnätä sinne ylös, kukin suoraan eteensä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Silloin Joosua, Nuunin poika, kutsui papit ja sanoi heille: \"Ottakaa liitonarkki, ja seitsemän pappia kantakoon seitsemää pässin sarvista tehtyä torvea Herran arkin edellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Sitten hän sanoi kansalle: \"Lähtekää ja kulkekaa kaupungin ympäri. Aseväki käyköön Herran arkin edellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Tapahtui, kuten Joosua oli kansalle sanonut. Ne seitsemän pappia, jotka kantoivat niitä seitsemää pässin sarvista tehtyä torvea Herran edellä, lähtivät ja puhalsivat torviin, ja Herran liitonarkki kulki heidän jäljessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Aseväki kulki torvea puhaltavien pappien edellä, mutta muu väki kulki arkin jäljessä, samalla kun torviin puhallettiin taukoamatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Joosua käski kansaa sanoen: \"Älkää nostako sotahuutoa älkääkä antako äänenne kuulua, älköönkä sanaakaan pääskö suustanne ennen kuin sinä päivänä, jona teille sanon: \'Nostakaa sotahuuto\'. Silloin se nostakaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Hän antoi Herran arkin kulkea yhden kierroksen kaupungin ympäri. Sitten he menivät leiriin ja jäivät yöksi leiriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Joosua nousi varhain seuraavana aamuna, ja papit ottivat Herran arkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Ne seitsemän pappia, jotka kantoivat seitsemää pässin sarvista tehtyä torvea Herran arkin edellä, kulkivat puhaltaen torviin taukoamatta, ja aseväki kulki heidän edellään, mutta muu väki kulki Herran arkin jäljessä samalla, kun torviin puhallettiin taukoamatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Tänä toisenakin päivänä he kulkivat kerran kaupungin ympäri ja palasivat sitten leiriin. Niin he tekivät kuutena päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Mutta seitsemäntenä päivänä he nousivat varhain aamun sarastaessa ja kulkivat kaupungin ympäri samalla tavalla seitsemän kertaa. Ainoastaan sinä päivänä he kulkivat kaupungin ympäri seitsemän kertaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Kun papit seitsemännellä kerralla puhalsivat torviin, Joosua sanoi kansalle: \"Nostakaa sotahuuto, sillä Herra antaa teille kaupungin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Kaupunki ja kaikki, mitä siinä on, vihittäköön tuhon omaksi Herran kunniaksi. Ainoastaan portto Rahab jääköön henkiin, hän ja kaikki, jotka ovat hänen kanssaan hänen talossaan, sillä hän piilotti tiedustelijat, jotka lähetimme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Mutta karttakaa tuhon omaksi vihittyä, ettette vihi jotakin tuhon omaksi ja kuitenkin ota tuhon omaksi vihittyä ja niin tule vihkineiksi Israelin leiriä tuhon omaksi ja syökse sitä onnettomuuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Kaikki hopea ja kulta sekä vaski- ja rautaesineet olkoot pyhitetyt Herralle. Ne tulkoot Herran aarteistoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Silloin kansa nosti sotahuudon ja torviin puhallettiin. Kun kansa kuuli torven äänen, se nosti kovan sotahuudon. Silloin muuri luhistui juuri siihen paikkaan, ja kansa ryntäsi ylös kaupunkiin, kukin suoraan eteensä. Niin he valloittivat kaupungin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'He vihkivät miekan terällä tuhon omaksi kaiken, mitä kaupungissa oli, miehet ja naiset, nuoret ja vanhat, vieläpä härät, lampaat ja aasit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Mutta niille kahdelle miehelle, jotka olivat olleet vakoilemassa maata, Joosua sanoi: \"Menkää sen porton taloon ja tuokaa nainen ja kaikki hänen omaisensa sieltä ulos, niin kuin olette hänelle vannoneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Silloin ne nuoret miehet, jotka olivat olleet vakoilemassa, menivät ja toivat ulos Rahabin sekä hänen isänsä, äitinsä, veljensä ja kaikki hänen omaisensa. He toivat ulos kaikki hänen sukulaisensa ja jättivät heidät Israelin leirin ulkopuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Mutta kaupungin ja kaikki, mitä siinä oli, he polttivat tulella. Ainoastaan hopean, kullan sekä vaski- ja rautaesineet he panivat Herran huoneen aarteistoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Mutta portto Rahabin sekä hänen isänsä perheen ja kaikki hänen omaisensa Joosua jätti henkiin. Hän jäi asumaan Israelin keskuuteen, aina tähän päivään asti, koska hän oli piilottanut ne tiedustelijat, jotka Joosua oli lähettänyt vakoilemaan Jerikoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Siihen aikaan Joosua vannotti tämän valan: \"Kirottu olkoon Herran edessä se mies, joka nousee rakentamaan tätä Jerikon kaupunkia. Sen perustuksen laskemisesta hän menettäköön esikoisensa ja sen porttien pystyttämisestä nuorimpansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Herra oli Joosuan kanssa, ja hänen maineensa levisi kautta koko maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Mutta israelilaiset menettelivät uskottomasti anastamalla itselleen tuhon omaksi vihittyä. Aakan, Karmin poika, joka oli Sabdin poika, joka Seran poika, Juudan sukukuntaa, otti näet itselleen tuhon omaksi vihittyä. Silloin syttyi Herran viha israelilaisia kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Joosua lähetti miehiä Jerikosta Aihin, joka on lähellä Beet-Aavenia, itään Beetelistä, ja puhui heille sanoen: \"Menkää vakoilemaan maata.\" Niin miehet menivät ja vakoilivat Aita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Kun he palasivat Joosuan luo, he sanoivat hänelle: \"Älköön koko kansa menkö, vaan menköön Aita valloittamaan noin kaksi tai kolme tuhatta miestä. Älä vaivaa koko kansaa sinne, sillä niitä on vähän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Niin sinne meni kansasta noin kolme tuhatta miestä, mutta he kääntyivät pakoon Ain miesten edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Ain miehet löivät heitä kuoliaaksi noin kolmekymmentä kuusi miestä, ajoivat heitä takaa kaupungin portilta Sebarimiin asti ja voittivat heidät rinteessä. Silloin kansan sydän raukesi ja tuli kuin vedeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Niin Joosua repäisi vaatteensa ja lankesi kasvoilleen maahan Herran arkin eteen ja oli siinä iltaan saakka, hän ja Israelin vanhimmat. He heittivät tomua päänsä päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Joosua sanoi: \"Voi, Herra, Herra, minkä tähden toit tämän kansan Jordanin yli antaaksesi meidät amorilaisten käsiin ja tuhotaksesi meidät? Oi, jospa olisimme päättäneet jäädä tuolle puolelle Jordanin!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Oi, Herra, mitä sanoisinkaan, kun Israel on kääntynyt pakoon vihollistensa edestä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Kun kanaanilaiset ja kaikki muut maan asukkaat sen kuulevat, he saartavat meidät ja hävittävät nimemme maan päältä. Mitä aiot tehdä suuren nimesi puolesta?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Mutta Herra sanoi Joosualle: \"Nouse! Miksi makaat kasvoillasi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Israel on tehnyt syntiä. He ovat rikkoneet liittoni, jonka olen heille säätänyt. He ovat ottaneet sitä, mikä oli tuhon omaksi vihittyä. He ovat varastaneet ja valehdelleet. He ovat panneet sen omien tavaroidensa joukkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Sen tähden israelilaiset eivät voi kestää vihollistensa edessä, vaan heidän täytyy kääntyä pakoon vihollistensa edestä, sillä he itse ovat vihityt tuhon omiksi. En ole enää kanssanne, ellette hävitä keskuudestanne tuhon omaksi vihittyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Nouse, pyhitä kansa ja sano: Pyhittäytykää huomiseksi, sillä näin sanoo Herra, Israelin Jumala: Keskuudessasi, Israel, on jotakin tuhon omaksi vihittyä. Sinä et voi kestää vihollistesi edessä, ennen kuin olette poistaneet keskuudestanne tuhon omaksi vihityn.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Astukaa siis huomenaamuna sukukunnittain esiin. Se sukukunta, johon Herran arpa osuu, astukoon esiin suvuittain. Se suku, johon Herran arpa osuu, astukoon esiin perhekunnittain. Se perhekunta, johon Herran arpa osuu, astukoon esiin mies mieheltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Mutta se, jolta tavataan tuhon omaksi vihittyä, poltettakoon tulessa, hän ja kaikki, mitä hänellä on, sillä hän on rikkonut Herran liiton ja tehnyt häpeällisen teon Israelissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Joosua antoi varhain seuraavana aamuna Israelin astua sukukunnittain esiin, ja arpa osui Juudan sukukuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Silloin hän antoi Juudan sukukunnan astua esiin, ja arpa osui serahilaisten sukuun. Sitten hän antoi serahilaisten suvun astua esiin mies mieheltä, ja arpa osui Sabdiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Niin hän antoi hänen perhekuntansa astua esiin mies mieheltä, ja arpa osui Aakaniin, Karmin poikaan, joka oli Sabdin poika, joka Seran poika, Juudan sukukuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Silloin Joosua sanoi Aakanille: \"Poikani, anna Herralle, Israelin Jumalalle, kunnia ja anna hänelle ylistys: tunnusta minulle, mitä olet tehnyt, äläkä salaa sitä minulta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Niin Aakan vastasi Joosualle ja sanoi: \"Minä olen todella tehnyt syntiä Herraa, Israelin Jumalaa, vastaan, sillä näin minä tein:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'kun minä näin saaliin joukossa kauniin sinearilaisen paidan, kaksisataa sekeliä hopeaa ja kultalevyn, viidenkymmenen sekelin painoisen, niin minussa syttyi niihin himo, ja minä otin ne. Ne ovat kätkettyinä maahan keskelle telttaani, hopea alimpana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Niin Joosua lähetti miehiä ottamaan selvää asiasta, ja he juoksivat telttaan. Siellä oli kätkö hänen teltassaan, hopea alimpana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'He ottivat ne teltasta, veivät ne Joosuan ja kaikkien israelilaisten luo ja panivat Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Joosua otti yhdessä koko Israelin kanssa Aakanin, Seran pojan, ja hopean, paidan ja kultalevyn, sekä hänen poikansa, tyttärensä, härkänsä, aasinsa, lampaansa, telttansa sekä kaikki, mitä hänellä oli, ja he veivät ne Aakorin laaksoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Joosua sanoi: \"Miksi olet syössyt meidät onnettomuuteen? Herra syöksee sinut onnettomuuteen tänä päivänä.\" Silloin koko Israel kivitti hänet kuoliaaksi. He polttivat heidät tulessa ja kivittivät heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'He kasasivat hänen päälleen suuren kivikasan, joka vielä tänäkin päivänä on olemassa, ja niin Herra lauhtui vihansa hehkusta. Sen tähden kutsutaan sitä paikkaa vielä tänäkin päivänä Aakorin laaksoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Sitten Herra sanoi Joosualle: \"Älä pelkää äläkä arkaile. Ota mukaasi kaikki sotaväki ja lähde ja mene Aihin. Katso, minä annan sinun käsiisi Ain kuninkaan ja hänen kansansa, hänen kaupunkinsa ja maansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Tee Aille ja sen kuninkaalle, niin kuin teit Jerikolle ja sen kuninkaalle. Kuitenkin saatte ryöstää itsellenne, mitä sieltä on saatavana saalista ja karjaa. Aseta väijytys kaupungin taakse.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Niin Joosua sekä kaikki sotaväki lähti liikkeelle noustakseen ylös Aihin. Joosua valitsi kolmekymmentä tuhatta miestä, voimakkaita sankareita, ja lähetti heidät menemään yöllä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'Hän käski heitä sanoen: \"Asettukaa väijyksiin kaupungin taakse, ei aivan kauas kaupungista, ja olkaa kaikki valmiina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Mutta minä sekä kaikki väki, joka on kanssani, lähestymme kaupunkia. Kun he sitten tulevat ulos meitä vastaan niin kuin ensimmäiselläkin kerralla, niin käännymme pakoon heidän edestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'He seuraavat meitä niin kauas, että eristämme heidät kaupungista, sillä he sanovat: \'He pakenevat meitä niin kuin ensimmäiselläkin kerralla.\' Kun näin pakenemme heitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'silloin nouskaa te väijytyksestä ja ottakaa kaupunki haltuunne, sillä Herra, teidän Jumalanne, antaa sen käsiinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Kun olette saaneet kaupungin valtaanne, sytyttäkää kaupunki palamaan. Tehkää Herran sanan mukaan. Huomatkaa, että käsken teitä sen tekemään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Sitten Joosua lähetti heidät menemään, ja he menivät ja asettuivat väijyksiin Beetelin ja Ain välille, länteen Aista. Mutta Joosua oli sen yön kansan kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Varhain seuraavana aamuna Joosua piti kansan katselmuksen ja lähti, hän ja Israelin vanhimmat, kansan etunenässä nousemaan Aihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Kaikki sotaväki, joka oli hänen kanssaan, nousi, lähestyi ja tuli kaupungin edustalle, ja he leiriytyivät Ain pohjoispuolelle, niin että laakso oli heidän ja Ain välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Sitten hän otti noin viisituhatta miestä ja asetti heidät väijyksiin Beetelin ja Ain välille, kaupungista länteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Niin kansa, koko leiri, joka oli kaupungin pohjoispuolella, ja kaupungin länsipuolella oleva jälkijoukko asetettiin asemiinsa. Mutta Joosua meni sinä yönä keskelle laaksoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Kun Ain kuningas näki sen, kaupungin miehet, kuningas ja kaikki hänen väkensä, lähtivät varhain aamulla nopeasti taisteluun Israelia vastaan määrättyyn paikkaan aromaan puolelle. Hän ei näet tiennyt, että kaupungin takana oli väijytys häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Niin Joosua ja koko Israel olivat joutuvinaan tappiolle ja pakenivat erämaahan päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Silloin kaupungin koko väki kutsuttiin ajamaan heitä takaa. He ajoivat Joosuaa takaa, ja niin heidät eristettiin kaupungista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'Eikä Aihin eikä Beeteliin jäänyt ainoatakaan miestä, joka ei lähtenyt Israelin perään, vaan he jättivät kaupungin avoimeksi ja ajoivat takaa Israelia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Niin Herra sanoi Joosualle: \"Ojenna keihäs, joka on kädessäsi, Aita kohti, sillä annan sen käsiisi.\" Joosua ojensi keihään, joka oli hänen kädessään, kaupunkia kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Silloin väijyksissä oleva joukko nousi kiireesti paikaltaan ja riensi, heti kun hän ojensi kätensä, ja tunkeutui kaupunkiin, valloitti sen ja sytytti heti kaupungin palamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Kun Ain miehet kääntyivät ja katsoivat taakseen, niin he näkivät kaupungista savun nousevan taivasta kohti, eivätkä he kyenneet pakenemaan, ei sinne eikä tänne. Väki, joka oli paennut erämaahan, kääntyi näet takaa-ajajia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Kun Joosua ja koko Israel näki, että väijyksissä ollut joukko oli valloittanut kaupungin ja että kaupungista nousi savu, he palasivat takaisin ja voittivat Ain miehet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Myös toiset lähtivät kaupungista heitä vastaan, joten he joutuivat israelilaisten väliin, toisten ollessa edessä, toisten takana. He voittivat heidät, päästämättä pakoon ja pelastumaan ainoaakaan heistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Mutta Ain kuninkaan he ottivat kiinni elävänä ja toivat hänet Joosuan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Kun Israel oli surmannut kaikki Ain asukkaat kedolla, erämaassa, jonne he olivat heitä ajaneet takaa, ja he kaikki olivat kaatuneet viimeiseen mieheen miekan terään, koko Israel palasi Aihin, ja siellä olevat tapettiin miekan terällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Niitä, jotka sinä päivänä kaatuivat, miehiä ja naisia, oli kaikkiaan kaksitoista tuhatta, kaikki Ain asukkaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Joosua ei vetänyt takaisin kättään, jossa hänellä oli keihäs ojennettuna, ennen kuin oli vihkinyt tuhon omiksi kaikki Ain asukkaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Ainoastaan karjan, ja mitä kaupungista oli saatavana saalista, Israel ryösti itselleen sen määräyksen mukaan, jonka Herra oli Joosualle antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Joosua poltti Ain ja teki siitä ikiajoiksi rauniokummun, aution aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Mutta Ain kuninkaan hän ripusti hirteen, jossa hän riippui iltaan asti. Mutta auringon laskiessa Joosua käski ottaa hänen ruumiinsa alas hirrestä, ja he heittivät sen kaupungin portin edustalle ja kasasivat sen päälle suuren kivikasan, joka on siellä vielä tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Silloin Joosua rakensi Eebalin vuorelle alttarin Herralle, Israelin Jumalalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'niin kuin Herran palvelija Mooses oli käskenyt israelilaisten tehdä ja niin kuin on kirjoitettuna Mooseksen lain kirjassa: alttarin hakkaamattomista kivistä, joihin ei ollut rauta-aseella koskettu. He uhrasivat sen päällä Herralle polttouhreja ja rauhanuhreja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Hän kirjoitti siellä kiviin jäljennöksen Mooseksen laista, jonka tämä oli kirjoittanut israelilaisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Koko Israel vanhimpineen, päämiehineen ja tuomareineen seisoi kummallakin puolella arkkia, [kääntyneinä] kohti leeviläisiä pappeja, jotka kantoivat Herran liitonarkkia, niin muukalaiset kuin maassa syntyneetkin, toinen puoli kääntyneenä Garissimin vuorta kohti, toinen puoli Eebalin vuorta kohti. Niin Israelin kansa ensiksi siunattiin, niin kuin Herran palvelija Mooses oli käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Sitten hän luki kaikki lain sanat, siunauksen ja kirouksen, aivan niin kuin lain kirjassa on kirjoitettuna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Joosua ei jättänyt lukematta mitään siitä, mitä Mooses oli käskenyt, kaiken Israelin seurakunnan läsnä ollessa, niin myös naisten, lasten ja mukana kulkevien muukalaisten läsnä ollessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Kun kaikki kuninkaat, jotka asuivat Jordanin tällä puolella, Vuoristossa, Alankomaassa ja pitkin Suuren meren koko rannikkoa Libanoniin päin, heettiläiset, amorilaiset, kanaanilaiset, perissiläiset, hivviläiset ja jebusilaiset, kuulivat, mitä oli tapahtunut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'he kokoontuivat yhteen sotiakseen yksimielisesti Joosuaa ja Israelia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Mutta kun Gibeonin asukkaat kuulivat, mitä Joosua oli tehnyt Jerikolle ja Aille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'hekin menettelivät viekkaasti: he menivät ja tekeytyivät lähettiläiksi, ottivat kuluneita säkkejä aasiensa selkään sekä kuluneita, repeytyneitä ja korjattuja viinileilejä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'ja panivat kuluneet, paikatut sandaalit jalkaansa ja kuluneet vaatteet päälleen. Kaikki heidän eväsleipänsä olivat kuivia ja murentuneita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'He menivät Joosuan luo Gilgalin leiriin ja sanoivat hänelle sekä Israelin miehille: \"Olemme tulleet kaukaisesta maasta. Tehkää siis liitto kanssamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Mutta Israelin miehet vastasivat hivviläisille: \"Kenties asutte täällä keskellämme, kuinka me tekisimme liiton teidän kanssanne?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'He sanoivat Joosualle: \"Me olemme palvelijoitasi.\" Joosua sanoi heille: \"Keitä te olette ja mistä tulette?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'He vastasivat hänelle: \"Palvelijasi tulevat hyvin kaukaisesta maasta Herran, Jumalasi, nimen tähden. Sillä me olemme kuulleet hänestä kaiken, mitä hän teki Egyptissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'ja kaiken, mitä hän teki niille kahdelle amorilaisten kuninkaalle, jotka asuivat tuolla puolella Jordanin, Siihonille, Hesbonin kuninkaalle, ja Oogille, Baasanin kuninkaalle, joka asui Astarotissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Sen tähden vanhimpamme ja kaikki maamme asukkaat puhuivat meille sanoen: \'Ottakaa evästä mukaanne matkalle ja menkää heitä vastaan ja sanokaa heille: Me olemme teidän palvelijanne, tehkää nyt liitto kanssamme.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Tämä leipämme oli vielä lämmintä, kun kotoa otimme sen evääksi lähtiessämme matkalle luoksenne, ja katso, nyt se on kuivaa ja murentunutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Nämä viinileilit, jotka uusina täytimme, ovat nyt repeytyneitä. Nämä vaatteemme ja sandaalimme ovat kovin pitkällä matkalla kuluneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Niin miehet ottivat heidän evästään, mutta eivät kysyneet Herran mieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Niin Joosua takasi heille rauhan ja teki heidän kanssaan liiton, luvaten jättää heidät henkiin. Kansan päämiehet vannoivat heille valan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Mutta kolmen päivän kuluttua, sen jälkeen kun liitto heidän kanssaan oli tehty, saatiin kuulla, että he olivat lähiseuduilta ja asuivat heidän keskellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Israelilaiset lähtivät liikkeelle ja tulivat kolmantena päivänä heidän kaupunkeihinsa. Heidän kaupunkinsa olivat Gibeon, Kefira, Beerot ja Kirjat-Jearim.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Mutta israelilaiset eivät surmanneet heitä, sillä kansan päämiehet olivat vannoneet heille valan Herran, Israelin Jumalan, kautta. Koko seurakunta niskoitteli päämiehiä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Silloin kaikki päämiehet sanoivat koko seurakunnalle: \"Me olemme vannoneet heille valan Herran, Israelin Jumalan, kautta emmekä nyt voi koskea heihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Mutta tämän me teemme heille: jätämme heidät henkiin, ettei viha kohtaisi meitä valan tähden, jonka olemme vannoneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Päämiehet sanoivat heistä: \"Jääkööt henkiin, mutta tulkoon heistä puunhakkaajia ja vedenkantajia kaikelle kansalle\" Niin päämiehet heitä käskivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Silloin Joosua kutsui heidät ja puhui heille sanoen: \"Miksi olette pettäneet meidät ja sanoneet: \'Me asumme hyvin kaukana teistä\', vaikka asutte täällä keskellämme?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Sen tähden olkaa kirotut! Älköön ikinä ketään teistä päästettäkö olemasta minun Jumalani huoneen palvelijana, puunhakkaajana ja vedenkantajana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'He vastasivat Joosualle ja sanoivat: \"Sinun palvelijoillesi oli kerrottu, että Herra, Jumalasi, oli käskenyt palvelijaansa Moosesta antamaan teille koko tämän maan ja tuhoamaan kaikki maan asukkaat teidän tieltänne. Sen tähden suuresti pelkäsimme henkeämme edessänne ja teimme tämän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Mutta katso, nyt me olemme käsissäsi: tee meille, mikä mielestäsi on hyvin ja oikein.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Silloin hän teki heille näin: hän pelasti heidät israelilaisten käsistä, niin etteivät he heitä surmanneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Niin Joosua määräsi heidät sinä päivänä seurakunnan ja Herran alttarin puunhakkaajiksi ja vedenkantajiksi, aina tähän päivään asti, sitä paikkaa varten, jonka Herra oli valitseva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Kun Adonisedek, Jerusalemin kuningas, kuuli, että Joosua oli valloittanut Ain ja vihkinyt sen tuhon omaksi, tehden Aille ja sen kuninkaalle, niin kuin oli tehnyt Jerikolle ja sen kuninkaalle, ja että Gibeonin asukkaat olivat tehneet rauhan Israelin kanssa ja jääneet heidän keskuuteensa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'niin he pelästyivät suuresti, sillä Gibeon oli suuri kaupunki, niin kuin jokin kuninkaankaupunki, ja suurempi kuin Ai, ja kaikki sen miehet olivat urhoollisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Adonisedek, Jerusalemin kuningas, lähetti sanan Hoohamille, Hebronin kuninkaalle, Piramille, Jarmutin kuninkaalle, Jaafialle, Laakiin kuninkaalle, ja Debirille, Eglonin kuninkaalle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, '\"Tulkaa luokseni ja auttakaa minua, ja kukistakaamme Gibeon, koska se on tehnyt rauhan Joosuan ja israelilaisten kanssa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Nuo viisi amorilaisten kuningasta, Jerusalemin kuningas, Hebronin kuningas, Jarmutin kuningas, Laakiin kuningas ja Eglonin kuningas, kokoontuivat ja lähtivät liikkeelle kaikkine joukkoineen. He asettuivat leiriin Gibeonin edustalle ja ryhtyivät taisteluun sitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Gibeonin miehet lähettivät sanan Joosualle Gilgalin leiriin: \"Älköön kätesi vetäytykö auttamasta palvelijoitasi. Tule nopeasti luoksemme, pelasta meidät ja auta meitä, sillä kaikki vuoristossa asuvien amorilaisten kuninkaat ovat kokoontuneet meitä vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Niin Joosua lähti Gilgalista, hän ja kaikki sotaväki hänen kanssaan ja kaikki väkevät sankarit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Silloin Herra sanoi Joosualle: \"Älä pelkää heitä, sillä minä annan heidät käsiisi. Ei kukaan heistä kestä sinun edessäsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Niin Joosua yllätti heidät kuljettuaan koko yön Gilgalista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Herra saattoi heidät hämminkiin israelilaisten edessä, niin että nämä tuottivat heille suuren tappion Gibeonissa ja ajoivat heitä takaa Beet-Hooronin solatietä surmaten heitä aina Asekaan ja Makkedaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Kun he paetessaan Israelia olivat Beet-Hooronin rinteessä, Herra heitti taivaasta heidän päälleen isoja kiviä, koko matkan Asekaan asti, niin että he kuolivat. Niitä, jotka kuolivat raekivistä, oli useampia kuin niitä, jotka israelilaiset surmasivat miekalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Silloin Joosua puhui Herralle, sinä päivänä, jona Herra antoi amorilaiset israelilaisten valtaan, ja sanoi Israelin silmien edessä: \"Aurinko, seiso alallasi Gibeonissa, ja kuu Aijalonin laaksossa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Niin aurinko seisoi liikkumatta, ja kuu pysyi paikallaan, kunnes kansa oli kostanut vihollisilleen. Niin on kirjoitettuna \"Oikeamielisen kirjassa.\" Niin aurinko pysyi paikallaan keskitaivaalla päiväkauden, kiirehtimättä laskemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Eikä ole ollut sen päivän vertaista, ei ennen eikä jälkeen, jona Herra näin kuuli ihmisen ääntä, sillä Herra soti Israelin puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Joosua ja koko Israel hänen kanssaan palasi Gilgalin leiriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Mutta nuo viisi kuningasta pakenivat ja piiloutuivat Makkedan luolaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Joosualle ilmoitettiin: \"Ne viisi kuningasta on löydetty piiloutuneina Makkedan luolaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Joosua sanoi: \"Vierittäkää isoja kiviä luolan suulle ja asettakaa sen eteen miehiä vartioimaan heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Mutta te muut, älkää pysähtykö, vaan ajakaa takaa vihollisianne ja hakatkaa maahan heidän jälkijoukkonsa älkääkä päästäkö heitä menemään kaupunkeihinsa, sillä Herra, teidän Jumalanne, on antanut heidät käsiinne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Kun sitten Joosua ja israelilaiset olivat tuottaneet heille hyvin suuren, perinpohjaisen tappion ja ne harvat, jotka olivat pelastuneet, olivat päässeet varustettuihin kaupunkeihin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'niin koko kansa palasi vahingoittumattomana takaisin Joosuan luo leiriin Makkedaan, eikä kukaan uskaltanut hiiskua sanaakaan israelilaisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Silloin Joosua sanoi: \"Avatkaa luolan suu ja tuokaa ne viisi kuningasta eteeni luolasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'He tekivät niin ja toivat hänen eteensä ne viisi kuningasta luolasta: Jerusalemin kuninkaan, Hebronin kuninkaan, Jarmutin kuninkaan, Laakiin kuninkaan ja Eglonin kuninkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Kun he olivat noutaneet nämä kuninkaat Joosuan eteen, Joosua kutsui kaikki Israelin miehet ja sanoi sotaväen päälliköille, jotka olivat seuranneet häntä: \"Astukaa esiin ja pankaa jalkanne näiden kuninkaiden niskalle.\" He astuivat esiin ja panivat jalkansa heidän niskalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Joosua sanoi heille: \"Älkää pelätkö älkääkä arkailko, vaan olkaa lujat ja rohkeat, sillä näin on Herra tekevä kaikille vihollisillenne, joita vastaan te joudutte sotimaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Sen jälkeen Joosua löi heidät kuoliaaksi ja ripusti heidät viiteen hirsipuuhun. He riippuivat hirressä iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Mutta auringonlaskun aikaan Joosua käski ottaa heidät alas hirrestä ja heittää luolaan, johon he olivat olleet piiloutuneina. He panivat luolan suulle isoja kiviä, jotka ovat siinä vielä tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Samana päivänä Joosua valloitti Makkedan ja surmasi miekan terällä sen asukkaat ja sen kuninkaan. Hän vihki tuhon omiksi heidät ja jokaisen, joka siellä oli, päästämättä pakoon ainoatakaan. Hän teki Makkedan kuninkaalle, niin kuin oli tehnyt Jerikon kuninkaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Sitten Joosua ja koko Israel hänen kanssaan lähti Makkedasta Libnaan ja ryhtyi taisteluun Libnaa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Herra antoi senkin ja sen kuninkaan Israelin käsiin. Joosua surmasi miekan terällä sen asukkaat, jokaisen, joka siellä oli, päästämättä sieltä pakoon ainoatakaan. Hän teki sen kuninkaalle saman, minkä oli tehnyt Jerikon kuninkaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Sitten Joosua ja koko Israel hänen kanssaan lähti Libnasta Laakiiseen ja asettui leiriin sen edustalle ja ryhtyi taisteluun sitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Herra antoi Laakiin Israelin käsiin, niin että hän valloitti sen toisena päivänä. Hän surmasi miekan terällä sen asukkaat, jokaisen, joka siellä oli, samoin kuin oli tehnyt Libnalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Silloin Hooram, Geserin kuningas, tuli auttamaan Laakista, mutta Joosua voitti hänet ja hänen väkensä päästämättä heistä ainoatakaan pakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Laakiista Joosua ja koko Israel hänen kanssaan lähti Egloniin, ja he asettuivat leiriin sen edustalle ja ryhtyivät taisteluun sitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'He valloittivat sen samana päivänä ja surmasivat miekan terällä sen asukkaat. Hän vihki tuhon omaksi sinä päivänä jokaisen, joka siellä oli, samoin kuin oli tehnyt Laakiille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Joosua ja koko Israel hänen kanssaan lähti Eglonista Hebroniin, ja he ryhtyivät taisteluun sitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'He valloittivat sen ja surmasivat miekan terällä sen asukkaat ja sen kuninkaan, ja samoin kaikki sen alaiset kaupungit ja jokaisen, joka siellä oli, päästämättä pakoon ainoatakaan, samoin kuin hän oli tehnyt Eglonille. Hän vihki tuhon omaksi sen ja jokaisen, joka siellä oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Sitten Joosua ja koko Israel hänen kanssaan kääntyi Debiriin ja ryhtyi taisteluun sitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'Hän sai valtaansa sen ja sen kuninkaan sekä kaikki sen alaiset kaupungit, ja he surmasivat miekan terällä niiden asukkaat ja vihkivät tuhon omaksi jokaisen, joka siellä oli, päästämättä pakoon ainoatakaan. Hän teki Debirille ja sen kuninkaalle saman, minkä oli tehnyt Hebronille ja minkä oli tehnyt Libnalle ja sen kuninkaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Joosua valtasi koko maan, Vuoriston, Negevin, Alankomaan ja Rinnemaat, ja surmasi kaikki niiden kuninkaat, päästämättä pakoon ainoaakaan, ja vihki tuhon omaksi joka hengen, niin kuin Herra, Israelin Jumala, oli käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Joosua valtasi heidän alueensa Kaades-Barneasta Gassaan saakka ja koko Goosenin maakunnan Gibeoniin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Kaikki nämä kuninkaat ja heidän maansa Joosua sai valtaansa yhdellä kerralla. Sillä Herra, Israelin Jumala, soti Israelin puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Sitten Joosua ja koko Israel hänen kanssaan palasi Gilgalin leiriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Kun Jaabin, Haasorin kuningas, sen kuuli, hän lähetti sanan Joobabille, Maadonin kuninkaalle, ja Simronin kuninkaalle ja Aksafin kuninkaalle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'ja niille kuninkaille, jotka asuivat pohjoisessa, Vuoristossa, Aromaassa Kinarotista etelään päin, Alankomaassa ja Doorin kukkuloilla lännessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'kanaanilaisille itään ja länteen, amorilaisille, heettiläisille, perissiläisille ja jebusilaisille vuoristoon ja hivviläisille Hermonin juurelle Mispan maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Nämä lähtivät liikkeelle kaikkine joukkoineen. Väkeä oli niin paljon kuin hiekkaa meren rannalla ja hevosia ja sotavaunuja hyvin paljon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Kaikki nämä kuninkaat liittyivät yhteen, tulivat ja leiriytyivät yhdessä Meeromin veden rannalle sotiakseen Israelia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Silloin Herra sanoi Joosualle: \"Älä pelkää heitä, sillä huomenna tähän aikaan minä annan heidät kaikki voitettuina Israelin valtaan. Sinä katkot heidän ratsujensa vuohisjänteet, ja heidän vaununsa sinä poltat tulessa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Joosua ja kaikki sotaväki hänen kanssaan yllätti heidät Meeromin veden rannalla ja hyökkäsi heidän kimppuunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Herra antoi heidät Israelin käsiin, niin että he voittivat heidät ja ajoivat heitä takaa aina suureen Siidoniin, Misrefot-Majimiin ja itään päin Mispan laaksoon asti. He voittivat heidät päästämättä heistä ainoatakaan pakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Joosua teki heille, niin kuin Herra oli hänelle sanonut: heidän ratsujensa vuohisjänteet hän katkoi, ja heidän vaununsa hän poltti tulessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Sitten Joosua kääntyi takaisin ja valloitti Haasorin ja surmasi miekalla sen kuninkaan. Haasor oli näet muinoin kaikkien näiden kuningaskuntien pääkaupunki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'He surmasivat miekan terällä ja vihkivät tuhon omaksi jokaisen, joka siellä oli, niin ettei jäänyt jäljelle ainoatakaan henkeä. Haasorin hän poltti tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Kaikki nämä kuninkaankaupungit ja niiden kuninkaat Joosua sai valtaansa, ja hän surmasi miekan terällä niiden asukkaat vihkien heidät tuhon omiksi, niin kuin Herran palvelija Mooses oli käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Mutta kukkuloilla olevista kaupungeista Israel ei polttanut ainoatakaan, paitsi Haasorin, jonka Joosua poltti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Kaiken, mitä näistä kaupungeista oli saatavana saalista, sekä karjan israelilaiset ryöstivät itselleen. Mutta kaikki ihmiset he surmasivat miekan terällä ja tuhosivat heidät jättämättä eloon ainoaakaan henkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Niin kuin Herra oli käskenyt palvelijaansa Moosesta, niin Mooses oli käskenyt Joosuaa, ja niin Joosua teki, eikä hän jättänyt tekemättä mitään kaikesta siitä, minkä Herra oli Moosekselle käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Niin Joosua valloitti koko tämän maan, Vuoriston, koko Negevin ja koko Goosenin maakunnan, Alankomaan ja Aromaan, niin myös Israelin vuoriston ja sen alankomaan –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'maan Seiriin päin kohoavasta Sileästä vuoresta aina Baal-Gaadiin saakka, Libanonin laaksoon, Hermonin vuoren juurelle. Kaikki heidän kuninkaansa hän sai valtaansa ja löi heidät kuoliaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Kauan aikaa Joosua kävi sotaa kaikkia näitä kuninkaita vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Eikä ollut ainoaakaan kaupunkia, joka olisi tehnyt rauhan Israelin kanssa, paitsi ne hivviläiset, jotka asuivat Gibeonissa, vaan kaikki valloitettiin asevoimin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Sillä Herralta tämä tuli. Hän paadutti heidän sydämensä, niin että he kävivät taisteluun Israelia vastaan, jotta heidät armotta vihittäisiin tuhon omiksi ja hävitettäisiin, kuten Herra oli Moosesta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Siihen aikaan Joosua tuli ja hävitti anakilaiset vuoristosta, Hebronista, Debiristä ja Anabista, koko Juudan vuoristosta ja koko Israelin vuoristosta. Joosua vihki heidät kaupunkeineen tuhon omiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Israelilaisten maahan ei jäänyt anakilaisia. Ainoastaan Gassaan, Gatiin ja Asdodiin heitä jäi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Näin Joosua valloitti koko maan, aivan niin kuin Herra oli Moosekselle puhunut. Joosua antoi sen perintöosaksi Israelille, heidän sukukunnilleen heidän osastojensa mukaan. Maa pääsi rauhaan sodasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Nämä olivat ne [Kanaanin] maan kuninkaat, jotka israelilaiset voittivat ja joiden maan he ottivat omakseen tuolla puolella Jordanin, päivänkoiton puolella, maan Arnon-joesta aina Hermonin vuoreen saakka ja koko itäpuolisen Aromaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Siihon, amorilaisten kuningas, joka asui Hesbonissa ja hallitsi maata Arnon-joen rannalla olevasta Aroerista ja jokilaakson keskikohdalta, ja puolta Gileadia, Jabbok-jokeen saakka, joka on ammonilaisten rajana,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'ja Aromaata aina Kinneretin järveen, sen itärantaan, saakka ja Aromaan mereen, Kuolleeseen mereen, sen itärantaan, saakka, Beet-Jesimotin tienoille, ja etelään päin Pisgan rinteiden juurelle saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'He ottivat omakseen Oogin, Baasanin kuninkaan, alueen, hänen, joka oli viimeisiä refalaisia ja asui Astarotissa ja Edreissä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'ja hallitsi Hermonin vuorta, Salkaa ja koko Baasania gesurilaisten ja maakatilaisten alueeseen saakka ja toista puolta Gileadia, Hesbonin kuninkaan Siihonin alueeseen saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Herran palvelija Mooses ja israelilaiset olivat voittaneet heidät. Herran palvelija Mooses oli antanut maan omaksi ruubenilaisille ja gaadilaisille ja toiselle puolelle Manassen sukukuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Nämä olivat ne maan kuninkaat, jotka Joosua ja israelilaiset voittivat Jordanin tällä puolella, sen länsipuolella, Libanonin laaksossa olevasta Baal-Gaadista aina Seiriin päin kohoavaan Sileään vuoreen saakka, ja joiden maan Joosua antoi Israelin sukukuntien omaksi, heidän osastojensa mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'Vuoristossa, Alankomaassa, Aromaassa, Rinnemaissa, Erämaassa ja Negevissä, heettiläisten, amorilaisten, kanaanilaisten, perissiläisten, hivviläisten ja jebusilaisten maan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Jerikon kuningas yksi, lähellä Beeteliä olevan Ain kuningas yksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'Jerusalemin kuningas yksi, Hebronin kuningas yksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'Jarmutin kuningas yksi, Laakiin kuningas yksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'Eglonin kuningas yksi, Geserin kuningas yksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'Debirin kuningas yksi, Gederin kuningas yksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'Horman kuningas yksi, Aradin kuningas yksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'Libnan kuningas yksi, Adullamin kuningas yksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'Makkedan kuningas yksi, Beetelin kuningas yksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'Tappuahin kuningas yksi, Heeferin kuningas yksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'Afekin kuningas yksi, Lassaronin kuningas yksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'Maadonin kuningas yksi, Haasorin kuningas yksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'Simron-Meronin kuningas yksi, Aksafin kuningas yksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'Taanakin kuningas yksi, Megiddon kuningas yksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'Kedeksen kuningas yksi, Karmelin juurella olevan Jokneamin kuningas yksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'Doorin kukkuloilla olevan Doorin kuningas yksi, Gilgalin seudun pakanoiden kuningas yksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'Tirsan kuningas yksi. Kaikkiaan kolmekymmentä yksi kuningasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Kun Joosua oli käynyt vanhaksi ja iäkkääksi, Herra sanoi hänelle: \"Sinä olet käynyt vanhaksi ja iäkkääksi, mutta vielä on hyvin paljon maata valtaamatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Tämä on se maa, mikä vielä on jäljellä: kaikki filistealaisten alueet ja koko gesurilaisten maa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'Siihorista alkaen, joka on itään Egyptistä, aina Ekronin alueeseen asti pohjoisen suuntaan – se luetaan kanaanilaisten alueeseen – viisi filistealaista ruhtinasta, nimittäin Gassan, Asdodin, Askelonin, Gatin ja Ekronin ruhtinaat, niin myös avvilaiset');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'etelässä päin, koko kanaanilaisten maa ja Meara, joka on siidonilaisten, Afekiin saakka, amorilaisten alueeseen saakka,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'ja gebalilaisten maa ja koko Libanon, päivänkoiton puolella, Hermonin vuoren juurella olevasta Baal-Gaadista siihen saakka, mistä mennään Hamatiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Kaikki vuoriston asukkaat Libanonista Misrefot-Majimiin saakka, kaikki siidonilaiset, minä karkotan israelilaisten tieltä. Arvo vain niiden maa Israelin kesken perintöosaksi, niin kuin olen sinua käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Jaa siis tämä maa perintöosana yhdeksälle sukukunnalle ja toiselle puolelle Manassen sukukuntaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Samalla kun sen toinen puoli olivat näet myös ruubenilaiset ja gaadilaiset saaneet perintöosansa, jonka Mooses antoi heille tuolta puolelta Jordanin, idän puolelta, kuten Herran palvelija Mooses sen heille antoi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'maan Arnon-joen rannalla olevasta Aroerista ja jokilaakson keskikohdalla olevasta kaupungista alkaen ja koko Meedeban ylätasangon Diiboniin saakka,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'kaikki Siihonin, amorilaisten kuninkaan, kaupungit, hänen, joka hallitsi Hesbonissa, aina ammonilaisten alueeseen saakka,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'Gileadin sekä gesurilaisten ja maakatilaisten alueet ja koko Hermonin vuoren ja koko Baasanin Salkaan saakka,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'ja koko Oogin valtakunnan Baasanissa, hänen, joka hallitsi Astarotissa ja Edreissä ja oli viimeisiä refalaisia. Nämä Mooses voitti ja karkotti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Mutta israelilaiset eivät karkottaneet gesurilaisia ja maakatilaisia, vaan gesurilaiset ja maakatilaiset jäivät asumaan Israelin keskuuteen aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Ainoastaan Leevin sukukunnalle hän ei antanut perintöosaa. Herran, Israelin Jumalan, uhrit ovat sen perintöosa, niin kuin hän on sille puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Mooses oli antanut maata ruubenilaisten sukukunnalle, heidän suvuilleen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'heille tuli alue Arnon-joen rannalla olevasta Aroerista ja jokilaakson keskikohdalla olevasta kaupungista alkaen ja koko ylätasanko Meedeban luona,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hesbon sekä kaikki sen alaiset kaupungit, jotka ovat ylätasangolla, Diibon, Baamot-Baal, Beet-Baal-Meon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Jahas, Kedemot, Meefaat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Kirjataim, Sibma, Seret-Sahar Laaksovuorella,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Beet-Peor ja Pisgan rinteet ja Beet-Jesimot,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'ja kaikki ylätasangon kaupungit ja Siihonin, amorilaisten kuninkaan, koko valtakunta, hänen, joka hallitsi Hesbonissa ja jonka Mooses oli voittanut samalla kun Midianin ruhtinaat Evin, Rekemin, Suurin, Huurin ja Reban, jotka olivat Siihonin aliruhtinaita ja asuivat siinä maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Muiden mukana, jotka olivat kaatuneet, israelilaiset olivat surmanneet miekalla myös tietäjä Bileamin, Beorin pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Ruubenilaisten raja on Jordan, se on rajana. Tämä on ruubenilaisten, heidän sukujensa, perintöosa, kaupungit kylineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Mooses oli antanut Gaadin sukukunnalle, gaadilaisille, heidän suvuilleen, maata:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'heidän alueekseen tuli Jaeser ja kaikki Gileadin kaupungit ja puolet ammonilaisten maata Aroeriin asti, joka on itään Rabbasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'ja maa Hesbonista Raamat-Mispeen ja Betonimiin saakka, ja Mahanaimista Lidebirin alueeseen saakka;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'ja laaksossa: Beet-Raam, Beet-Nimra, Sukkot ja Saafon, loput Siihonin, Hesbonin kuninkaan, valtakunnasta, rajana Jordan Kinneretin järven päähän saakka, Jordanin tuolla puolella, idän puolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Tämä on gaadilaisten, heidän sukujensa, perintöosa, kaupungit kylineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Mooses oli antanut toiselle puolelle Manassen sukukuntaa maata, ja se tuli toiselle puolelle Manassen sukukuntaa, heidän suvuilleen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'heidän alueekseen tuli Mahanaimista alkaen koko Baasan, Oogin, Baasanin kuninkaan, koko valtakunta, kaikki Jaairin leirikylät Baasanissa, kuusikymmentä kaupunkia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'ja puolet Gileadia sekä Astarot ja Edrei, Oogin valtakunnan pääkaupungit Baasanissa. Tämä tuli Maakirin, Manassen pojan, jälkeläisille, toiselle puolelle Maakirin jälkeläisiä, heidän suvuilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Nämä ovat ne alueet, jotka Mooses oli jakanut perintöosiksi Mooabin arolla, Jordanin tuolla puolen, Jerikon kohdalla, idän puolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Mutta Leevin sukukunnalle Mooses ei ollut antanut perintöosaa. Herra, Israelin Jumala, on heidän perintöosansa, niin kuin hän on heille puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Nämä ovat ne alueet, jotka israelilaiset saivat perintöosiksi Kanaanin maassa, ne, jotka pappi Eleasar ja Joosua, Nuunin poika, ja israelilaisten sukukuntien perhekuntien päämiehet jakoivat heille');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'arvalla perintöosiksi sen käskyn mukaan, jonka Herra oli yhdeksästä ja puolesta sukukunnasta antanut Mooseksen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Sillä Mooses oli antanut kahdelle ja puolelle sukukunnalle perintöosat Jordanin tuolta puolen, mutta leeviläisille hän ei ollut antanut perintöosaa heidän keskeltään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Sillä joosefilaisia oli kaksi sukukuntaa, Manasse ja Efraim. Leeviläisille taas ei annettu osuutta maahan, vaan ainoastaan kaupunkeja heidän asuttavikseen sekä niiden laidunmaat heidän karjaansa ja omaisuuttaan varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Niin kuin Herra oli Moosesta käskenyt, niin israelilaiset tekivät ja jakoivat maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Silloin juudalaiset astuivat Joosuan eteen Gilgalissa, ja kenissiläinen Kaaleb, Jefunnen poika, sanoi hänelle: \"Sinä tunnet sanan, jonka Herra puhui Jumalan miehelle Moosekselle minusta ja sinusta Kaades-Barneassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Minä olin neljänkymmenen vuoden vanha, kun Herran palvelija Mooses lähetti minut Kaades-Barneasta vakoilemaan maata, ja minä annoin hänelle tietoja parhaan ymmärrykseni mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Mutta veljeni, jotka olivat käyneet siellä kanssani, saivat kansan sydämen raukeamaan, kun minä seurasin uskollisesti Herraa, Jumalaani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Sinä päivänä Mooses vannoi sanoen: \'Totisesti, se maa, johon sinä olet jalkasi astunut, on tuleva sinulle ja sinun lapsillesi perintöosaksi ikiaikoihin asti, koska olet uskollisesti seurannut Herraa, minun Jumalaani.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Mutta nyt, katso, Herra on antanut minun elää, niin kuin hän oli sanonut, vielä neljäkymmentä viisi vuotta sen jälkeen, kun Herra puhui tämän sanan Moosekselle, Israelin vaeltaessa erämaassa. Katso, minä olen nyt kahdeksankymmenen viiden vuoden vanha');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'ja olen vielä tänä päivänä yhtä voimakas, kuin olin sinä päivänä, jona Mooses minut lähetti. Niin kuin voimani oli silloin, niin se on vielä nytkin: minä kykenen sotimaan, lähtemään ja tulemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Anna minulle siis tämä vuoristo, josta Herra sinä päivänä puhui. Sinähän kuulit sinä päivänä, että siellä asuu anakilaisia ja että siellä on suuria, varustettuja kaupunkeja. Ehkä Herra on kanssani, ja karkotan heidät, kuten Herra on puhunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Silloin Joosua siunasi Kaalebin, Jefunnen pojan, ja antoi hänelle perintöosaksi Hebronin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Hebron tuli kenissiläisen Kaalebin, Jefunnen pojan, perintöosaksi, kuten se on tänäkin päivänä, sen tähden että hän oli uskollisesti seurannut Herraa, Israelin Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Mutta Hebronin nimi oli muinoin Kirjat-Arba, Arban mukaan, joka oli mahtavin mies anakilaisten joukossa, kun maa oli päässyt sodasta rauhaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Juudan jälkeläisten sukukunta, heidän sukunsa, saivat arpaosansa etelästä Edomin rajaan ja Siinin erämaahan päin, etäisintä etelää myöten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Heidän eteläinen rajansa alkaa Kuolleen meren päästä, sen eteläisimmästä pohjukasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'jatkuu Skorpionisolan eteläpuolitse, kulkee Siiniin, nousee Kaades-Barnean eteläpuolitse, kulkee Hesroniin, nousee Addariin ja kääntyy Karkaan päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Se kulkee edelleen Asmoniin ja jatkuu Egyptin puroon. Sitten raja päättyy mereen. Tämä olkoon teidän eteläinen rajanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Itäisenä rajana on Kuollut meri Jordanin suuhun saakka. Pohjoinen raja alkaa siitä meren pohjukasta, jossa on Jordanin suu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Sieltä raja nousee Beet-Hoglaan ja kulkee Beet-Araban pohjoispuolitse. Edelleen raja nousee Boohanin, Ruubenin pojan, kiveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Sitten raja nousee Debiriin Aakorin laaksosta ja kääntyy pohjoiseen päin Gilgalia kohti, joka on vastapäätä puron eteläpuolella olevaa Adummimin solaa. Sitten raja kulkee Een-Semeksen veteen ja päättyy Roogelin lähteeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Edelleen raja nousee Ben-Hinnomin laaksoon, Jebusilaiskukkulan, se on Jerusalemin, eteläpuolitse. Sitten raja nousee sen vuoren laelle, joka on vastapäätä Hinnomin laaksoa, lännessä päin, Refaimin tasangon pohjoisessa laidassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Tämän vuoren laelta raja kaartuu Neftoahin veden lähteelle ja jatkuu Efronin vuoren kaupunkeihin, ja sitten raja kaartuu Baalaan, se on Kirjat-Jearimiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Baalasta raja kääntyy länteen päin Seirin vuoreen, kulkee Jearimin vuoren kukkulan, se on Kesalonin, pohjoispuolitse, laskeutuu Beet-Semekseen ja kulkee sitten Timnaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Edelleen raja jatkuu Ekronin kukkulaan, pohjoiseen päin. Sitten raja kaartuu Sikkeroniin, kulkee Baala-vuoreen ja jatkuu Jabneeliin. Sitten raja päättyy mereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Läntisenä rajana on Suuri meri. Se on rajana. Nämä ovat Juudan jälkeläisten, heidän sukukuntiensa, rajat yltympäri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Mutta Kaalebille, Jefunnen pojalle, Joosua antoi, niin kuin Herra oli häntä käskenyt, osuuden Juudan jälkeläisten keskuudessa, Kirjat-Arban, anakilaisten isän Arban kaupungin, se on Hebronin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Kaaleb karkotti sieltä kolme anakilaista, Anakin jälkeläiset Seesain, Ahimanin ja Talmain,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'ja lähti sieltä Debirin asukkaita vastaan. Mutta Debirin nimi oli muinoin Kirjat-Seefer.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Silloin Kaaleb sanoi: \"Joka voittaa ja valloittaa Kirjat-Seeferin, sille minä annan tyttäreni Aksan vaimoksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Niin Otniel, Kenaan, Kaalebin veljen, poika, valloitti sen. Niin Kaaleb antoi tälle tyttärensä Aksan vaimoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Kun Aksa tuli, hän yllytti miestään, että tämä pyytäisi hänen isältään peltomaata. Aksa pudottautui aasin selästä maahan. Silloin Kaaleb sanoi hänelle: \"Mikä sinun on?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Niin hän vastasi: \"Anna minulle siunaus, sillä sinä olet naittanut minut kuivaan maahan. Anna siis minulle vesilähteitä.\" Silloin hän antoi hänelle Ylälähteet ja Alalähteet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Tämä on Juudan jälkeläisten sukukunnan, heidän sukujensa, perintöosa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Juudan jälkeläisten sukukunnan etäisimmät kaupungit Edomin rajalla Negevissä ovat: Kabseel, Eeder, Jaagur,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Kiina, Diimona, Adada,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Kedes, Haasor, Jitnan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Siif, Telem, Bealot,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Haasor-Hadatta, Kerijot-Hesron, se on Haasor,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam, Sema, Moolada,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'Hasar-Gadda, Hesmon, Beet-Pelet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Hasar-Suual, Beerseba ja Bisjotja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala, Ijjim, Esem,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Eltolad, Kesil, Horma,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Siklag, Madmanna, Sansanna,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaot, Silhim, Ain ja Rimmon – kaikkiaan kaksikymmentä yhdeksän kaupunkia kylineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'Alankomaassa: Estaol, Sora, Asna,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Saanoah, Een-Gannim, Tappuah, Eenam,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmut, Adullam, Sooko, Aseka,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Saaraim, Aditaim, Gedera ja Gederotaim – neljätoista kaupunkia kylineen;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Senan, Hadasa, Migdal-Gaad,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dilan, Mispe, Jokteel,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Laakis, Boskat, Eglon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Kabbon, Lahmas, Kitlis,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Gederot, Beet-Daagon, Naema ja Makkeda – kuusitoista kaupunkia kylineen;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, Eter, Aasan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jiftah, Asna, Nesib,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Kegila, Aksib ja Maaresa – yhdeksän kaupunkia kylineen;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekron ja sen tytärkaupungit ja kylät;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'koko se alue kylineen, joka on Asdodin puolella Ekronista mereen kulkevaa rajaa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdod ja sen tytärkaupungit ja kylät; Gassa ja sen tytärkaupungit ja kylät Egyptin puroon asti. Ja Suuri meri on rajana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Ja vuoristossa: Saamir, Jattir, Sooko,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Danna, Kirjat-Sanna, se on Debir,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anab, Estemo, Aanim,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Goosen, Hoolon ja Giilo – yksitoista kaupunkia kylineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab, Duuma, Esan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Jaanum, Beet-Tappuah, Afeka,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Humta, Kirjat-Arba, se on Hebron, ja Siior – yhdeksän kaupunkia kylineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maaon, Karmel, Siif, Jutta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jisreel, Jokdeam ja Saanoah,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kain, Gibea, Timna – kymmenen kaupunkia kylineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halhul, Beet-Suur, Gedor,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Maarat, Beet-Anot ja Eltekon – kuusi kaupunkia kylineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kirjat-Baal, se on Kirjat-Jearim, ja Rabba – kaksi kaupunkia kylineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'Ja erämaassa: Beet-Araba, Middin, Sekaka,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Nibsan, Iir-Melah ja Een-Gedi – kuusi kaupunkia kylineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Mutta jebusilaisia, jotka asuivat Jerusalemissa, eivät Juudan jälkeläiset kyenneet karkottamaan, ja niin jebusilaiset jäivät asumaan Juudan jälkeläisten sekaan, Jerusalemiin, aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Joosefilaisille määräsi arpa rajan kulkemaan idästä Jerikon Jordanista Jerikon veteen ja sieltä erämaahan, joka kohoaa Jerikosta vuoristoon Beeteliä kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Beetelistä raja jatkuu Luusiin ja kulkee arkilaisten alueelle, Atarotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Sitten se laskeutuu länteen päin jafletilaisten alueelle, aina alemman Beet-Hooronin alueelle ja Geseriin asti ja päättyy mereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Joosefilaiset, Manasse ja Efraim, saivat perintöosakseen tämän:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Efraimilaisille, heidän suvuilleen, tuli seuraava alue: heidän perintöosansa itäinen raja kulkee Aterot-Addarista yliseen Beet-Hooroniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'Sitten raja päättyy mereen. Pohjoisessa on Mikmetat rajana. Sieltä raja kääntyy itään päin Taanat-Siiloon ja menee sen itäpuolitse Janohaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'Janohasta se laskeutuu Atarotiin ja Naaraan, koskettaa Jerikoa ja päättyy Jordaniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Tappuahista raja kulkee länteen päin Kaana-puroon ja päättyy mereen. Tämä on efraimilaisten sukukunnan, heidän sukujensa, perintöosa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'ja lisäksi ne kaupungit, jotka erotettiin efraimilaisille keskeltä manasselaisten perintöosaa, kaikki ne kaupungit kylineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Mutta he eivät karkottaneet kanaanilaisia, jotka asuivat Geserissä, ja kanaanilaiset jäivät asumaan Efraimin keskuuteen aina tähän päivään asti, mutta joutuivat työveron alaisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Manassen sukukunta sai sekin arpaosansa, sillä hän oli Joosefin esikoinen. Maakir, Manassen esikoinen, Gileadin isä, sai Gileadin ja Baasanin, sillä hän oli sotilas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Muutkin manasselaiset saivat osuutensa, suvuittain: abieserilaiset, heelekiläiset, asrielilaiset, sekemiläiset, heeferiläiset ja semidalaiset. Nämä ovat Manassen, Joosefin pojan, miespuoliset jälkeläiset, suvuittain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Mutta Selofhadilla, Heeferin pojalla, joka oli Gileadin poika, joka Maakirin poika, joka Manassen poika, ei ollut poikia, vaan ainoastaan tyttäriä. Nämä olivat hänen tyttäriensä nimet: Mahla, Nooga, Hogla, Milka ja Tirsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Nämä astuivat pappi Eleasarin ja Joosuan, Nuunin pojan, ja päämiesten eteen ja sanoivat: \" Herra käski Mooseksen antaa meille perintöosan veljiemme keskuudessa.\" Silloin Joosua antoi heille Herran käskyn mukaisesti perintöosan heidän isänsä veljien keskuudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Niin lankesi Manasselle kymmenen osaa lukuun ottamatta Gileadin maata ja Baasania tuolla puolella Jordanin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'koska Manassen tyttäret saivat perintöosan hänen poikiensa keskuudessa, mutta Gileadin maa joutui Manassen muille jälkeläisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Manassen raja kulkee Asserista Mikmetatiin, joka on Sikemin itäpuolella. Sitten raja menee oikealle Een-Tappuahin asukkaiden tienoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Tappuahin maa joutui Manasselle, mutta Tappuah, Manassen rajalla, efraimilaisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Sitten raja laskeutuu Kaana-puroon, puron eteläpuolelle. Mutta siellä, Manassen kaupunkien keskellä, olevat kaupungit joutuivat Efraimille. Sitten Manassen raja kulkee puron pohjoispuolelle ja päättyy mereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Eteläpuolella oleva maa joutui Efraimille, mutta pohjoispuolella oleva maa joutui Manasselle, ja sen rajana on meri. Pohjoisessa taas sen raja koskettaa Asseria ja idässä Isaskaria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Isaskarista ja Asserista joutui Manasselle Beet-Sean ja sen tytärkaupungit, Jibleam ja sen tytärkaupungit, Een-Doorin asukkaat ja sen tytärkaupungit, Taanakin asukkaat ja sen tytärkaupungit, Megiddon asukkaat ja sen tytärkaupungit, kolme kukkulaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Mutta manasselaiset eivät kyenneet ottamaan haltuunsa näitä kaupunkeja, vaan kanaanilaisten onnistui jäädä asumaan siihen maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Kun israelilaiset voimistuivat, he saattoivat kanaanilaiset työveron alaisiksi, mutta eivät karkottaneet heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Joosefilaiset puhuivat Joosualle sanoen: \"Miksi olet antanut minulle perintöosaksi vain yhden arvan ja yhden osan, vaikka minä olen lukuisa kansa, kun Herra on siunannut minua aina tähän asti?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Joosua sanoi heille: \"Jos sinä olet niin lukuisa kansa, niin mene metsäseudulle ja raivaa itsellesi maata sieltä perissiläisten ja refalaisten maasta, koska Efraimin vuoristo on sinulle liian ahdas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Mutta joosefilaiset vastasivat: \"Ei vuoristo riitä meille. Kaikilla kanaanilaisilla, jotka asuvat tasangoilla, on raudoitettuja sotavaunuja, sekä niillä, jotka asuvat Beet-Seanissa ja sen tytärkaupungeissa, että niillä, jotka asuvat Jisreelin tasangolla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Silloin Joosua puhui Joosefin heimolle, Efraimille ja Manasselle, sanoen: \"Sinä olet lukuisa kansa ja sinun voimasi on suuri. Sinua ei ole jätettävä yhdelle ainoalle arpaosalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'vaan vuoristo on tuleva omaksesi. Koska se on metsäseutua, sinun on se raivattava, ja sen laitapuoletkin tulevat omiksesi. Sillä sinun on karkotettava kanaanilaiset, vaikka heillä on raudoitettuja sotavaunuja ja vaikka he ovat voimakkaita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Sitten koko israelilaisten seurakunta kokoontui Siiloon, ja he pystyttivät sinne ilmestysmajan, sitten kun maa oli tullut heille alamaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Mutta israelilaisista oli jäljellä vielä seitsemän sukukuntaa, joiden perintöosa oli jakamatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Joosua sanoi israelilaisille: \"Kuinka kauan hidastelette ettekä mene ottamaan omaksenne maata, jonka Herra, isienne Jumala, on teille antanut?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Tuokaa tänne jokaisesta sukukunnasta kolme miestä, niin lähetän heidät menemään ja kiertelemään maata ja kirjaamaan sen heidän perintöosiensa [jakoa] varten. Tulkoot sitten takaisin luokseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'He jakakoot maan seitsemään osaan. Juuda pysyköön alueellaan etelässä, ja Joosefin heimo pysyköön alueellaan pohjoisessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Pankaa maa, ne seitsemän osaa, kirjaan ja tuokaa kirja tänne minulle, niin minä heitän teidän puolestanne arpaa täällä Herran, Jumalamme, edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Sillä leeviläisillä ei ole osuutta teidän keskuudessanne, vaan Herran pappeus on heidän perintöosansa. Gaad ja Ruuben ja toinen puoli Manassen sukukuntaa taas ovat saaneet tuolta puolelta Jordanin, idän puolelta, perintöosansa, jonka Herran palvelija Mooses antoi heille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Miehet nousivat ja lähtivät. Joosua käski lähtevien panna kirjaan maan sanoen: \"Menkää maa ristiin rastiin ja pankaa se kirjaan ja palatkaa sitten luokseni, niin heitän teidän puolestanne arpaa täällä Herran edessä Siilossa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Miehet lähtivät, kulkivat kautta maan ja panivat sen kirjaan kaupunki kaupungilta, seitsemänä osana, ja tulivat takaisin Joosuan luo Siilon leiriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Sitten Joosua heitti heidän puolestaan arpaa Siilossa Herran edessä, ja Joosua jakoi siellä maan israelilaisille, heidän osastojensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Arpa nousi benjaminilaisten sukukunnalle, heidän suvuilleen. Heidän arvalla saamansa alue oli Juudan jälkeläisten ja joosefilaisten välissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Heidän pohjoinen rajansa lähtee Jordanista, ja raja nousee Jerikon pohjoispuolella olevalle kukkulalle ja nousee vuoristoon länteen päin ja päättyy Beet-Aavenin erämaahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'Sieltä raja kulkee Luusiin, Luusin eteläpuolella olevalle kukkulalle, se on Beeteliin. Sitten raja laskeutuu Aterot-Addariin vuoren yli, joka on alemman Beet-Hooronin eteläpuolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Sitten raja kaartuu ja kääntyy läntisenä rajana etelään siitä vuoresta, joka on vastapäätä Beet-Hooronia, sen eteläpuolella, ja päättyy Kirjat-Baaliin, se on Kirjat-Jearimiin, Juudan jälkeläisten kaupunkiin. Tämä on läntinen raja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Mutta eteläinen raja lähtee Kirjat-Jearimin laidasta lännen puolelta ja jatkuu Neftoahin veden lähteelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'Sitten raja laskeutuu sen vuoren päähän, joka on vastapäätä Ben-Hinnomin laaksoa, Refaimin tasangon pohjoisessa laidassa. Sieltä se laskeutuu Hinnomin laaksoon Jebusilaiskukkulan eteläpuolitse ja edelleen Roogelin lähteelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Sitten se kaartuu pohjoiseen päin ja jatkuu Een-Semekseen ja edelleen kivikoille, jotka ovat vastapäätä Adummimin solaa, ja laskeutuu Boohanin, Ruubenin pojan, kiveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Edelleen se kulkee Aromaahan päin olevan kukkulan pohjoispuolitse ja laskeutuu Aromaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Sitten raja kulkee Beet-Hoglan kukkulan pohjoispuolitse, ja raja päättyy Kuolleen meren pohjoiseen pohjukkaan, Jordanin eteläpäähän. Tämä on eteläinen raja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Mutta idän puolella rajana on Jordan. Tämä on benjaminilaisten, heidän sukujensa, perintöosa rajoineen ympäriinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Benjaminilaisten sukukunnan, heidän sukujensa, kaupungit ovat: Jeriko, Beet-Hogla, Eemek-Kesis,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Beet-Araba, Semaraim, Beetel,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Avvim, Paara, Ofra,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Kefar-Ammoni, Ofni ja Geba – kaksitoista kaupunkia kylineen;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeon, Raama, Beerot,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Mispe, Kefira, Moosa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Jirpeel, Tarala,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Seela, Elef, Jebus, se on Jerusalem, Gibeat ja Kirjat – neljätoista kaupunkia kylineen. Tämä on benjaminilaisten, heidän sukujensa, perintöosa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Toinen arpa tuli Simeonille, simeonilaisten sukukunnalle, heidän suvuilleen. Heidän perintöosansa tuli olemaan keskellä Juudan jälkeläisten perintöosaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Heidän perintöosakseen tuli: Beerseba, Seba, Moolada,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Hasar-Suual, Baala, Esem,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltolad, Betul, Horma,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Siklag, Beet-Markabot, Hasar-Suusa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Beet-Lebaot ja Saaruhen – kolmetoista kaupunkia kylineen;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ain, Rimmon, Eeter ja Aasan – neljä kaupunkia kylineen;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'sitten kaikki ne kylät, jotka ovat näiden kaupunkien ympärillä, aina Baalat-Beeriin, Negevin Raamaan, saakka. Tämä on simeonilaisten sukukunnan, heidän sukujensa, perintöosa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Juudan jälkeläisten osasta saivat simeonilaiset perintöosansa, sillä Juudan jälkeläisille oli heidän osuutensa liian suuri. Niin simeonilaiset saivat perintöosansa heidän perintöosansa keskeltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Kolmas arpa nousi sebulonilaisille, heidän suvuilleen, ja heidän perintöosansa alue tuli ulottumaan Saaridiin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Lännen suuntaan heidän rajansa nousee Maralaan, koskettaa Dabbesetia ja puroa, joka on Jokneamin itäpuolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Itään, päivänkoittoon päin, kääntyy raja Saaridista Kislot-Taaborin alueelle ja jatkuu Daberatiin ja nousee Jaafiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Sieltä se kulkee itään, päivänkoittoon päin, Gat-Heeferiin ja Eet-Kasiniin ja jatkuu Rimmoniin, joka ulottuu Neegaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Sitten raja kääntyy sen pohjoispuolitse Hannatoniin ja päättyy Jiftah-Eelin laaksoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Kattat, Nahalal, Simron, Jidala ja Beetlehem – kaksitoista kaupunkia kylineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Tämä on sebulonilaisten, heidän sukujensa, perintöosa, nämä kaupungit kylineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Neljäs arpa tuli Isaskarille, isaskarilaisille, heidän suvuilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Heidän alueellaan tuli olemaan Jisreel, Kesullot, Suunem,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Hafaraim, Siion, Anaharat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Rabbit, Kisjon, Ebes,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Remet, Een-Gannim, Een-Hadda ja Beet-Passes;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'ja raja koskettaa Taaboria, Sahasimia, Beet-Semestä, ja heidän rajansa päättyy Jordaniin – kuusitoista kaupunkia kylineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Tämä on isaskarilaisten sukukunnan, heidän sukujensa, perintöosa, kaupungit kylineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Viides arpa tuli asserilaisten sukukunnalle, heidän suvuilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Heidän alueellaan tulivat olemaan Helkat, Hali, Beten ja Aksaf,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Alammelek, Amad ja Misal. Lännessä raja koskettaa Karmelia ja Siihor-Libnatia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'kääntyy sitten auringonnousuun päin Beet-Daagoniin ja koskettaa Sebulonia ja Jiftah-Eelin laaksoa pohjoisessa, Beet-Eemekiä ja Negieliä ja jatkuu Kaabulin pohjoispuolitse');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'Ebroniin, Rehobiin, Hammoniin ja Kaanaan, aina suureen Siidoniin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Sitten raja kääntyy Raamaan ja menee Tyyron varustettuun kaupunkiin saakka. Sitten raja kääntyy Hoosaan ja päättyy mereen, Heebelistä Aksibiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Umma, Afek ja Rehob – kaksikymmentä kaksi kaupunkia kylineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Tämä on asserilaisten sukukunnan, heidän sukujensa, perintöosa, nämä kaupungit kylineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Kuudes arpa tuli naftalilaisille, naftalilaisten suvuille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Heidän rajansa tuli kulkemaan Heelefistä, Saanannimin tammesta, Adami-Nekebin ja Jabneelin kautta Lakkumiin asti ja päättyy Jordaniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Raja kääntyy länteen päin Asnot-Taaboriin ja jatkuu sieltä Hukkokiin ja koskettaa etelässä Sebulonia, lännessä Asseria ja idässä Juudaa Jordanin luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Varustettuja kaupunkeja ovat: Siddim, Seer, Hammat, Rakkat, Kinneret,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adama, Raama, Haasor,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Kedes, Edrei, Een-Haasor,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Jireon, Migdal-Eel, Horem, Beet-Anat ja Beet-Semes – yhdeksäntoista kaupunkia kylineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Tämä on naftalilaisten sukukunnan, heidän sukujensa, perintöosa, kaupungit kylineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Seitsemäs arpa tuli daanilaisten sukukunnalle, heidän suvuilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Heidän perintöosansa alueella tulivat olemaan Sora, Estaol, Iir-Semes,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Saalabbin, Aijalon, Jitla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Eelon, Timna, Ekron,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Elteke, Gibbeton, Baalat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jehud, Bene-Berak, Gat-Rimmon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'Mee-Jarkon ja Rakkon, sekä Jaafoon päin oleva alue.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Mutta daanilaisten alue joutui heiltä pois. Niin daanilaiset lähtivät ja taistelivat Lesemiä vastaan ja valloittivat sen ja surmasivat miekan terällä sen asukkaat ja ottivat sen omakseen ja asettuivat sinne. He antoivat Lesemille nimen Daan, isänsä Daanin mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Tämä on daanilaisten sukukunnan, heidän sukujensa, perintöosa, nämä kaupungit kylineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Kun israelilaiset olivat saaneet jaetuksi maan sen rajoja myöten, he antoivat Joosualle, Nuunin pojalle, perintöosan keskuudessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Herran käskyn mukaisesti he antoivat hänelle sen kaupungin, jota hän pyysi, Timnat-Serahin Efraimin vuoristossa. Hän rakensi kaupungin uudestaan ja asettui sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Nämä ovat ne perintöosat, jotka pappi Eleasar ja Joosua, Nuunin poika, ja israelilaisten sukukuntien perhekuntapäämiehet jakoivat arvalla Siilossa Herran edessä, ilmestysmajan ovella. He saivat tehdyksi maan jakamisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Herra puhui Joosualle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, '\"Puhu israelilaisille ja sano: Määrätkää itsellenne ne turvakaupungit, joista minä olen teille Mooseksen kautta puhunut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'että niihin voisi paeta tappaja, joka tapaturmaisesti, tahtomattaan, on surmannut jonkun. Ne olkoot teillä turvapaikkoina verenkostajalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Kun joku pakenee johonkin näistä kaupungeista, pysähtyköön kaupungin portin ovelle ja kertokoon asiansa sen kaupungin vanhimmille. He ottakoot hänet luokseen turvaan kaupunkiin ja antakoot hänelle paikan, jossa hän saa asua heidän luonaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Jos verenkostaja ajaa häntä takaa, älkööt he luovuttako tappajaa hänen käsiinsä, koska hän tahtomattaan ja häntä ennestään vihaamatta tappoi lähimmäisensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Asukoon hän siinä kaupungissa, kunnes on ollut kansan tuomittavana, ja silloisen ylipapin kuolemaan saakka. Sitten tappaja tulkoon taas takaisin omaan kaupunkiinsa ja kotiinsa, kaupunkiin, josta oli paennut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Niin he pyhittivät sitä varten Kedeksen Galileasta, Naftalin vuoristosta, Sikemin Efraimin vuoristosta ja Kirjat-Arban, se on Hebronin, Juudan vuoristosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Jerikon tuolta puolen Jordanin itäpuolelta he määräsivät Ruubenin sukukunnasta Beserin erämaasta, ylätasangolta, ja Gaadin sukukunnasta Raamotin, Gileadista, ja Manassen sukukunnasta Goolanin, Baasanista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Nämä ovat ne kaupungit, jotka asetettiin kaikille israelilaisille ja heidän keskuudessaan asuville muukalaisille sitä varten, että niihin voisi paeta jokainen, joka tahattomasti oli surmannut jonkun, eikä hänen tarvitsisi kuolla verenkostajan käden kautta, ennen kuin oli ollut kansan tuomittavana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Leeviläisten perhekuntien päämiehet astuivat pappi Eleasarin ja Joosuan, Nuunin pojan, eteen ja israelilaisten sukukuntien perhekuntien päämiesten eteen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'ja puhuivat heille Siilossa Kanaanin maassa, sanoen: \" Herra käski Mooseksen kautta antaa meille kaupunkeja asuaksemme ja niiden laidunmaat karjaamme varten.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Niin israelilaiset antoivat leeviläisille perintöosastaan Herran käskyn mukaan nämä kaupungit laidunmaineen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Arpa tuli kehatilaisten suvuille niin, että leeviläisistä pappi Aaronin jälkeläiset saivat arvalla Juudan sukukunnalta, Simeonin sukukunnalta ja Benjaminin sukukunnalta kolmetoista kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'Mutta muut kehatilaiset saivat arvalla Efraimin sukukunnan suvuilta, Daanin sukukunnalta ja toiselta puolelta Manassen sukukuntaa kymmenen kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Geersonilaiset saivat arvalla Isaskarin sukukunnan suvuilta, Asserin sukukunnalta ja Naftalin sukukunnalta, sekä toiselta puolelta Manassen sukukuntaa Baasanista, kolmetoista kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Merarilaiset, heidän sukunsa, saivat Ruubenin sukukunnalta, Gaadin sukukunnalta ja Sebulonin sukukunnalta kaksitoista kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Israelilaiset antoivat arvalla leeviläisille nämä kaupungit laidunmaineen, niin kuin Herra oli Mooseksen kautta käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Juudan jälkeläisten sukukunnasta ja simeonilaisten sukukunnasta annettiin nämä nimeltä mainitut kaupungit:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'Leevin jälkeläisiin, kehatilaisten sukuihin, kuuluville Aaronin jälkeläisille, sillä heille arpa tuli ensin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'annettiin Kirjat-Arba, anakilaisten kantaisän Arban kaupunki, se on Hebron, Juudan vuoristosta, ympärillä olevine laidunmaineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Mutta kaupungin peltomaat kylineen annettiin Kaalebille, Jefunnen pojalle, perintömaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Pappi Aaronin jälkeläisille annettiin tappajan turvakaupunki Hebron laidunmaineen, Libna laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Jattir laidunmaineen, Estemoa laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Hoolon laidunmaineen, Debir laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Ain laidunmaineen, Jutta laidunmaineen ja Beet-Semes laidunmaineen – yhdeksän kaupunkia näistä kahdesta sukukunnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Sitten Benjaminin sukukunnasta Gibeon laidunmaineen, Geba laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anatot laidunmaineen ja Almon laidunmaineen – neljä kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Aaronin jälkeläisten, pappien, kaupunkeja oli kaikkiaan kolmetoista kaupunkia laidunmaineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Muut leeviläisiin kuuluvat kehatilaisten suvut, muut kehatilaiset, saivat arvalla Efraimin sukukunnalta seuraavat kaupungit:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'heille annettiin tappajan turvakaupunki Sikem laidunmaineen Efraimin vuoristosta, Geser laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Kibsaim laidunmaineen, Beet-Hooron laidunmaineen – neljä kaupunkia;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'ja Daanin sukukunnasta Elteke laidunmaineen, Gibbeton laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Aijalon laidunmaineen ja Gat-Rimmon laidunmaineen – neljä kaupunkia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'ja toisesta puolesta Manassen sukukuntaa Taanak laidunmaineen ja Gat-Rimmon laidunmaineen – kaksi kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Näiden muiden kehatilaisten sukujen kaupunkeja laidunmaineen oli kaikkiaan kymmenen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Leeviläisten sukuihin kuuluvat geersonilaiset saivat toiselta puolelta Manassen sukukuntaa tappajan turvakaupungin Goolanin laidunmaineen Baasanista ja Beesteran laidunmaineen – kaksi kaupunkia;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'ja Isaskarin sukukunnalta Kisjonin laidunmaineen, Daberatin laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmutin laidunmaineen ja Een-Gannimin laidunmaineen – neljä kaupunkia;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'ja Asserin sukukunnalta Misalin laidunmaineen, Abdonin laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkatin laidunmaineen ja Rehobin laidunmaineen – neljä kaupunkia;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'ja Naftalin sukukunnalta tappajan turvakaupungin Kedeksen laidunmaineen Galileasta, Hammot-Doorin laidunmaineen ja Kartanin laidunmaineen – kolme kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Geersonilaisten, heidän sukujensa, kaupunkeja oli kaikkiaan kolmetoista kaupunkia laidunmaineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Muut leeviläisiin kuuluvat merarilaisten suvut saivat Sebulonin sukukunnalta Jokneamin laidunmaineen, Kartan laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimnan laidunmaineen, Nahalalin laidunmaineen – neljä kaupunkia;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'ja Ruubenin sukukunnalta Beserin laidunmaineen, Jahaan laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemotin laidunmaineen ja Meefaatin laidunmaineen – neljä kaupunkia;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'ja Gaadin sukukunnalta tappajan turvakaupungin Raamotin laidunmaineen Gileadista ja Mahanaimin laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Hesbonin laidunmaineen ja Jaeserin laidunmaineen – yhteensä neljä kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Niitä kaupunkeja, jotka nämä muut leeviläisten sukuihin kuuluvat merarilaiset, heidän sukunsa, saivat arvalla, oli kaikkiaan kaksitoista kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Kaikkiaan oli leeviläisten kaupunkeja israelilaisten perintömaassa neljäkymmentä kahdeksan kaupunkia laidunmaineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Näihin kaupunkeihin kuului kuhunkin itse kaupunki ja sen ympärillä olevat laidunmaat. Sellaisia olivat kaikki nämä kaupungit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Niin Herra antoi Israelille koko sen maan, jonka hän oli vannonut antavansa heidän isilleen. Niin he ottivat sen omakseen ja asettuivat siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Herra soi heidän päästä rauhaan kaikkialla, aivan niin kuin hän valalla vannoen oli luvannut heidän isilleen. Yksikään heidän vihollisistaan ei kestänyt heidän edessään, vaan kaikki heidän vihollisensa Herra antoi heidän käsiinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Ei jäänyt täyttämättä mikään niistä kaikista lupauksista, jotka Herra oli antanut Israelin heimolle, vaan kaikki toteutui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Sitten Joosua kutsui ruubenilaiset, gaadilaiset ja toisen puolen Manassen sukukuntaa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'ja sanoi heille: \"Te olette noudattaneet kaikkea, mitä Herran palvelija Mooses on käskenyt teidän noudattaa, ja olette kuulleet minua kaikessa, mitä minä olen käskenyt teidän tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Te ette ole hylänneet veljiänne koko tämän pitkän ajan kuluessa aina tähän päivään asti, ja te olette noudattaneet, mitä Herra, teidän Jumalanne, on käskenyt noudattaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Nyt Herra, Jumalanne, on suonut teidän veljienne päästä rauhaan, niin kuin hän heille puhui. Kääntykää siis takaisin ja menkää majoillenne, siihen perintömaahanne, jonka Herran palvelija Mooses antoi teille tuolta puolelta Jordanin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Noudattakaa vain tarkasti niitä käskyjä ja sitä lakia, jotka Herran palvelija Mooses on teille antanut, rakastakaa Herraa, teidän Jumalaanne, vaeltakaa aina hänen teitään, noudattakaa hänen käskyjään, riippukaa hänessä kiinni ja palvelkaa häntä kaikesta sydämestänne ja kaikesta sielustanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Niin Joosua siunasi heidät ja päästi heidät menemään, ja he menivät teltoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Toiselle puolelle Manassen sukukuntaa Mooses oli antanut maata Baasanista, ja toiselle puolelle Joosua oli antanut maata Jordanin länsipuolelta, heille samoin kuin heidän veljilleen. Kun Joosua päästi heidät menemään teltoilleen ja siunasi heidät,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'hän puhui heille sanoen: \"Kun te palaatte teltoillenne, mukananne suuret rikkaudet ja suuri määrä karjaa, suuri määrä hopeaa, kultaa, vaskea, rautaa ja vaatteita, jakakaa veljienne kanssa vihollisiltanne saatu saalis.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Niin ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa palasivat takaisin ja lähtivät pois israelilaisten luota Siilosta, joka on Kanaanin maassa, mennäkseen Gileadin maahan, perintömaahansa, johon he olivat asettuneet sen käskyn mukaan, jonka Herra oli Mooseksen kautta antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Kun ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa tulivat Jordanin kivikoille, jotka ovat Kanaanin maan puolella, he rakensivat sinne Jordanille alttarin, valtavan kokoisen alttarin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Israelilaiset kuulivat sanottavan: \"Katso, ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa ovat rakentaneet alttarin, Kanaanin maan suuntaan, Jordanin kivikkojen luo, israelilaisten puolelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Kun israelilaiset sen kuulivat, koko israelilaisten seurakunta kokoontui Siiloon lähteäkseen sotaan heitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Israelilaiset lähettivät ruubenilaisten ja gaadilaisten luo ja Manassen sukukunnan toisen puolen luo Gileadin maahan pappi Piinehaan, Eleasarin pojan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'ja hänen kanssaan kymmenen ruhtinasta, yhden ruhtinaan kustakin perhekunnasta, kaikista Israelin sukukunnista. Jokainen heistä oli perhekunnan päämies Israelin heimojen joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'He tulivat ruubenilaisten ja gaadilaisten luo ja Manassen sukukunnan toisen puolen luo Gileadin maahan, puhuivat heille ja sanoivat:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, '\"Näin sanoo koko Herran seurakunta: Kuinka te menettelette näin uskottomasti Israelin Jumalaa kohtaan, että nyt käännytte pois Herrasta rakentamalla itsellenne alttarin ja nyt kapinoitte Herraa vastaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Eikö meille jo riitä Peorin vuoksi tehty rikos, josta emme ole päässeet puhdistumaan vielä tänäkään päivänä ja josta rangaistus kohtasi Herran seurakuntaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Kuitenkin te nytkin käännytte pois Herrasta! Kun te tänä päivänä kapinoitte Herraa vastaan, niin hän huomenna vihastuu koko Israelin seurakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Mutta jos teidän perintömaanne on saastainen, niin tulkaa Herran perintömaahan, jossa on Herran asumus, ja asettukaa keskellemme. Älkää kapinoiko Herraa vastaan älkääkä kapinoiko meitä vastaan rakentamalla itsellenne alttaria, toista kuin Herran, Jumalamme, alttari.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Eikö silloin, kun Aakan, Seran poika, oli ollut uskoton ja anastanut itselleen sitä, mikä oli vihitty tuhon omaksi, viha kohdannut koko Israelin seurakuntaa, vaikka hän olikin vain yksi mies? Eikö hänen täytynyt kuolla rikoksensa tähden?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Silloin ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa vastasivat ja puhuivat Israelin heimojen päämiehille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, '\"Jumala, Jumala, Herra, Jumala, Jumala Herra, hän tietää sen, ja Israel myös tietäköön sen: jos olemme kapinamielessä tai uskottomuudesta Herraa kohtaan – älä meitä silloin tänä päivänä auta –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'rakentaneet alttarin kääntyäksemme pois Herrasta, uhrataksemme sen päällä polttouhria ja ruokauhria tai toimittaaksemme sen päällä rauhanuhreja, niin kostakoon Herra itse sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Totisesti, me olemme tehneet sen vain huolestuneina yhdestä asiasta, siitä, että teidän lapsenne vastaisuudessa voivat sanoa meidän lapsillemme näin: \'Mitä teillä on tekemistä Herran, Israelin Jumalan, kanssa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Onhan Herra pannut Jordanin välirajaksi meille ja teille, te ruubenilaiset ja gaadilaiset. Teillä ei ole mitään osuutta Herraan.\' Niin teidän lapsenne voivat saada aikaan, että meidän lapsemme lakkaavat pelkäämästä Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Sen tähden me sanoimme: Tehkäämme itsellemme alttari, rakentakaamme se, ei polttouhria eikä teurasuhria varten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'vaan olemaan meidän ja teidän sekä myös meidän jälkeläistemme välillä meidän jälkeemme todistajana siitä, että tahdomme toimittaa Herran palvelusta hänen edessään, polttouhreja, teurasuhreja ja rauhanuhreja, etteivät teidän lapsenne vastaisuudessa sanoisi meidän lapsillemme: \'Teillä ei ole mitään osuutta Herraan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Me ajattelimme: Jos he vastaisuudessa sanovat näin meille ja meidän jälkeläisillemme, niin me voimme vastata: \'Katsokaa Herran alttarin kuvaa, jonka esi-isämme ovat tehneet, ei polttouhria eikä teurasuhria varten, vaan olemaan todistajana meidän välillämme ja teidän.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Pois se, että me kapinoisimme Herraa vastaan ja kääntyisimme tänä päivänä pois Herrasta rakentamalla alttarin polttouhria, ruokauhria ja teurasuhria varten, toisen kuin Herran, Jumalamme, alttarin, joka on hänen asumuksensa edessä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Kun pappi Piinehas ja kansan ruhtinaat, Israelin heimojen päämiehet, jotka olivat hänen kanssaan, kuulivat, mitä ruubenilaiset, gaadilaiset ja manasselaiset puhuivat, se oli heille mieleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Pappi Piinehas, Eleasarin poika, sanoi ruubenilaisille, gaadilaisille ja manasselaisille: \"Nyt me tiedämme, että Herra on keskellämme, koska ette olekaan menetelleet uskottomasti Herraa kohtaan. Näin te pelastitte israelilaiset joutumasta Herran käsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Sen jälkeen pappi Piinehas, Eleasarin poika, ja ruhtinaat palasivat Gileadin maasta, ruubenilaisten ja gaadilaisten luota, takaisin Kanaanin maahan israelilaisten luo ja antoivat heille nämä tiedot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Ne olivat israelilaisille mieleen, ja israelilaiset ylistivät Jumalaa, eivätkä he enää ajatelleet lähteä sotaan heitä vastaan hävittämään sitä maata, jossa ruubenilaiset ja gaadilaiset asuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Ruubenilaiset ja gaadilaiset kutsuivat alttaria nimellä Ed, sillä se on [todistaja] meidän välillämme siitä, että Herra on Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Pitkän ajan kuluttua, sitten kun Herra oli suonut Israelin päästä rauhaan kaikilta sen ympärillä asuvilta vihollisilta, ja kun Joosua oli käynyt vanhaksi ja iäkkääksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Joosua kutsui koolle koko Israelin, sen vanhimmat, päämiehet, tuomarit ja päällysmiehet ja sanoi heille: \"Minä olen käynyt vanhaksi ja iäkkääksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'Te olette itse nähneet kaiken, mitä Herra, Jumalanne, on tehnyt kaikille näille kansoille, jotka hän on karkottanut tieltänne, sillä Herra, teidän Jumalanne, on itse sotinut puolestanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Katsokaa, minä olen arponut teille, teidän sukukunnillenne, perintöosaksi nämä kansat, jotka vielä ovat jäljellä, ja kaikki kansat, jotka minä hävitin Jordanista Suureen mereen asti, auringon laskuun päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Herra, Jumalanne, työntää itse ne pois edestänne ja karkottaa ne tieltänne, niin että te otatte omaksenne heidän maansa, niin kuin Herra, teidän Jumalanne, on teille puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Olkaa siis aivan lujat ja noudattakaa tarkasti kaikkea, mitä Mooseksen lain kirjaan on kirjoitettu, poikkeamatta siitä oikealle tai vasemmalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'niin ettette yhdy näihin teidän keskuuteenne jääneisiin kansoihin, ette mainitse heidän jumaliensa nimiä ettekä vanno niiden nimeen, ette palvele niitä ettekä kumarra niitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'vaan että riiputte kiinni Herrassa, Jumalassanne, niin kuin olette tehneet aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Sen tähden Herra on karkottanut teidän tieltänne suuret ja mahtavat kansat, eikä ainoakaan ole kestänyt teidän edessänne aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Yksi ainoa mies teistä ajoi pakoon tuhat, sillä Herra, Jumalanne, soti itse puolestanne, niin kuin hän on teille puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Ottakaa siis henkenne tähden tarkka vaari siitä, että rakastatte Herraa, Jumalaanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Sillä jos te käännytte hänestä pois ja liitytte näiden keskuuteenne jääneiden kansojen tähteisiin ja lankoudutte heidän kanssaan ja yhdytte heihin ja he teihin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'niin tietäkää, ettei Herra, Jumalanne, enää karkota näitä kansoja tieltänne, vaan ne tulevat teille paulaksi ja ansaksi, kylkienne ruoskaksi ja okaiksi silmiinne, kunnes te häviätte tästä hyvästä maasta, jonka Herra, Jumalanne, on teille antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Katso, minä menen nyt kaiken maailman tietä. Koko sydämenne ja koko sielunne tietäköön, ettei ainoakaan kaikista niistä teitä koskevista lupauksista, jotka Herra, teidän Jumalanne, on antanut, ole jäänyt täyttämättä. Kaikki ovat toteutuneet teille, eikä ainoakaan niistä ole jäänyt täyttämättä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Niin kuin kaikki teitä koskevat lupaukset, jotka Herra, teidän Jumalanne, on antanut, ovat toteutuneet teille, niin Herra myös antaa kaikkien uhkauksiensa toteutua teille, kunnes hän on hävittänyt teidät tästä hyvästä maasta, jonka Herra, teidän Jumalanne, on teille antanut:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'jos te rikotte Herran, Jumalanne, liiton, jonka hän on teille säätänyt, ja menette ja palvelette muita jumalia ja niitä kumarratte, niin Herran viha syttyy teitä kohtaan, ja te häviätte pian siitä hyvästä maasta, jonka hän on teille antanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Joosua kokosi kaikki Israelin sukukunnat Sikemiin ja kutsui Israelin vanhimmat, sen päämiehet, tuomarit ja päämiehet, ja he asettuivat Jumalan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Joosua puhui koko kansalle: \"Näin sanoo Herra, Israelin Jumala: Tuolla puolella Eufrat-virran asuivat muinoin teidän isänne, myös Terah, Aabrahamin ja Naahorin isä, ja he palvelivat muita jumalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Mutta minä otin teidän isänne Aabrahamin tuolta puolelta virran ja kuljetin häntä kautta koko Kanaanin maan ja tein hänen jälkeläisensä lukuisiksi ja annoin hänelle Iisakin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Iisakille minä annoin Jaakobin ja Eesaun. Eesaulle minä annoin Seirin vuoriston omaksi, mutta Jaakob ja hänen poikansa menivät Egyptiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Lähetin Mooseksen ja Aaronin ja rankaisin Egyptiä sillä, mitä siellä tein, ja sen jälkeen vein teidät sieltä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Kun vein isänne pois Egyptistä ja olitte saapuneet meren rannalle, egyptiläiset ajoivat isiänne takaa sotavaunuilla ja ratsumiehillä Kaislamereen saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'He huusivat Herraa, ja hän pani pimeyden teidän ja egyptiläisten välille ja antoi meren tulla heidän ylitseen. Se peitti heidät. Omin silmin näitte, mitä tein egyptiläisille. Kun olitte asuneet kauan aikaa erämaassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'toin teidät amorilaisten maahan, jotka asuivat tuolla puolella Jordanin, ja he taistelivat teitä vastaan. Mutta annoin heidät käsiinne, ja otitte omaksenne heidän maansa, ja tuhosin heidät tieltänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Silloin nousi Baalak, Sipporin poika, Mooabin kuningas ja taisteli Israelia vastaan. Hän lähetti kutsumaan Bileamin, Beorin pojan, että hän kiroaisi teidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Mutta en tahtonut kuulla Bileamia, vaan hänen täytyi siunata teidät, ja pelastin teidät hänen käsistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Kun te olitte menneet Jordanin yli ja tulleet Jerikoon, Jerikon miehet ja amorilaiset, perissiläiset, kanaanilaiset, heettiläiset, girgasilaiset, hivviläiset ja jebusilaiset taistelivat teitä vastaan, mutta annoin heidät teidän käsiinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Lähetin herhiläisiä edellänne, ja ne karkottivat heidät tieltänne, ne kaksi amorilaisten kuningasta. Et tehnyt sitä miekallasi ja jousellasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Annoin teille maan, josta et ollut vaivaa nähnyt, ja kaupunkeja, joita ette olleet rakentaneet, mutta joihin asetuitte. Te söitte viinitarhoista ja öljypuista, joita ette olleet istuttaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Pelätkää nyt Herraa, palvelkaa häntä nuhteettomasti ja uskollisesti ja poistakaa ne jumalat, joita isänne palvelivat tuolla puolen virran ja Egyptissä, ja palvelkaa Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Mutta jos pidätte pahana palvella Herraa, niin valitkaa tänä päivänä, ketä tahdotte palvella, niitäkö jumalia, joita teidän isänne palvelivat virran tuolla puolen, vai amorilaisten jumalia, niiden, joiden maassa te asutte. Mutta minä ja minun perheeni, me palvelemme Herraa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Kansa vastasi ja sanoi: \"Pois se, että me hylkäisimme Herran ja palvelisimme muita jumalia!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Sillä Herra on meidän Jumalamme, hän, joka johdatti meidät ja isämme pois Egyptin maasta, orjuuden pesästä, ja joka teki silmiemme edessä suuret tunnusteot ja aina varjeli meitä sillä tiellä, jota vaelsimme, ja kaikkien niiden kansojen keskellä, joiden kautta kuljimme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Herra karkotti tieltämme kaikki ne kansat, myös amorilaiset, jotka asuivat tässä maassa. Sen tähden me palvelemme Herraa, sillä hän on Jumalamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Niin Joosua sanoi kansalle: \"Te ette voi palvella Herraa, sillä hän on pyhä Jumala. Hän on kiivas Jumala, hän ei anna anteeksi teidän rikoksianne ja syntejänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Jos te hylkäätte Herran ja palvelette vieraita jumalia, niin hän kääntyy pois ja antaa teille käydä pahoin ja tekee teistä lopun, sen sijaan että hän on ennen antanut teille käydä hyvin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Mutta kansa sanoi Joosualle: \"Ei niin, vaan me palvelemme Herraa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Joosua sanoi kansalle: \"Te olette itse todistajina itseänne vastaan, että olette valinneet itsellenne Herran palvellaksenne häntä.\" He vastasivat: \"Olemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Hän sanoi: \"Poistakaa nyt vieraat jumalat, joita on keskuudessanne, ja taivuttakaa sydämenne Herran, Israelin Jumalan, puoleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Kansa vastasi Joosualle: \" Herraa, Jumalaamme, me palvelemme, ja hänen ääntään me kuulemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Joosua teki sinä päivänä liiton kansan kanssa ja antoi heille Sikemissä käskyt ja oikeudet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Joosua kirjoitti nämä puheet Jumalan lain kirjaan, ja hän otti suuren kiven ja pystytti sen sinne, tammen alle, joka oli Herran pyhäkössä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Joosua sanoi kaikelle kansalle: \"Katso, tämä kivi on oleva todistajana meitä vastaan, sillä se on kuullut kaikki Herran sanat, jotka hän on meille puhunut, ja se on oleva todistajana teitä vastaan, ettette kieltäisi Jumalaanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Sitten Joosua päästi kansan menemään, kunkin perintöosalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Näiden tapausten jälkeen Herran palvelija Joosua, Nuunin poika, kuoli sadan kymmenen vuoden vanhana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'He hautasivat hänet hänen perintöosansa alueelle, Timnat-Serahiin, joka on Efraimin vuoristossa, pohjoispuolelle Gaas-vuorta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Israel palveli Herraa Joosuan koko elinajan ja niiden vanhinten koko elinajan, jotka elivät vielä kauan Joosuan jälkeen ja tunsivat kaikki ne teot, jotka Herra oli Israelille tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Joosefin luut, jotka israelilaiset olivat tuoneet Egyptistä, he hautasivat Sikemiin, sille maapalstalle, jonka Jaakob oli ostanut Hamorin, Sikemin isän, pojilta sadalla kesitalla ja jonka joosefilaiset olivat saaneet perintöosakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Eleasar, Aaronin poika, kuoli, ja he hautasivat hänet Gibeaan, hänen poikansa Piinehaan kaupunkiin, joka oli annettu hänelle Efraimin vuoristosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Joosuan kuoleman jälkeen israelilaiset kysyivät Herralta ja sanoivat: \"Kenen meistä on lähdettävä ensiksi sotimaan kanaanilaisia vastaan?\" Herra vastasi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, '\"Juuda lähteköön. Katso, minä annan maan hänen käsiinsä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Juuda sanoi veljelleen Simeonille: \"Lähde kanssani arpaosaani. Sotikaamme kanaanilaisia vastaan, niin minäkin tulen kanssasi sinun arpaosaasi.\" Simeon lähti hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Juuda lähti. Herra antoi kanaanilaiset ja perissiläiset heidän käsiinsä. He voittivat heidät Besekissä – kymmenentuhatta miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'He kohtasivat Adoni-Besekin Besekissä ja taistelivat häntä vastaan ja voittivat kanaanilaiset ja perissiläiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Adoni-Besek pakeni, mutta he ajoivat häntä takaa ja ottivat hänet kiinni ja hakkasivat häneltä peukalot ja isotvarpaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Silloin Adoni-Besek sanoi: \"Seitsemänkymmentä kuningasta, joilta oli hakattu peukalot ja isotvarpaat, kokosi muruja pöytäni alta. Niin kuin minä olen tehnyt, niin on Jumala minulle maksanut.\" He veivät hänet Jerusalemiin, ja siellä hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Juudan miehet ryhtyivät taisteluun Jerusalemia vastaan ja valloittivat sen ja surmasivat miekan terällä sen asukkaat ja pistivät kaupungin tuleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Sen jälkeen Juudan miehet laskeutuivat sotimaan niitä kanaanilaisia vastaan, jotka asuivat Vuoristossa, Negevissä ja Alankomaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Juuda meni niitä kanaanilaisia vastaan, jotka asuivat Hebronissa – Hebronin nimi oli muinoin Kirjat-Arba – ja he voittivat Seesain, Ahimanin ja Talmain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Sieltä hän meni Debirin asukkaita vastaan – Debirin nimi oli muinoin Kirjat-Seefer –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'ja Kaaleb sanoi: \"Joka voittaa ja valloittaa Kirjat-Seeferin, sille annan tyttäreni Aksan vaimoksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Niin Otniel, Kenaan, Kaalebin nuoremman veljen, poika, valloitti sen, ja hän [Kaaleb] antoi hänelle tyttärensä Aksan vaimoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Kun Aksa tuli, hän yllytti miestään, että tämä pyytäisi hänen isältään peltomaata, ja Aksa pudottautui aasin selästä maahan. Silloin Kaaleb sanoi hänelle: \"Mikä sinun on?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Niin hän vastasi hänelle: \"Anna minulle siunaus, sillä sinä olet antanut minut kuivaan maahan. Anna siis minulle vesilähteitä.\" Silloin Kaaleb antoi hänelle Ylälähteet ja Alalähteet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Keeniläisen, Mooseksen apen, jälkeläiset olivat lähteneet Palmukaupungista Juudan jälkeläisten kanssa Juudan erämaahan, eteläpuolelle Aradia. He menivät ja asettuivat sikäläisen kansan sekaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Mutta Juuda meni veljensä Simeonin kanssa, ja he voittivat kanaanilaiset, jotka asuivat Sefatissa, ja he vihkivät kaupungin tuhon omaksi ja kutsuivat sen Hormaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Juuda valloitti Gassan alueineen, Askelonin alueineen ja Ekronin alueineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Herra oli Juudan kanssa, niin että hän sai haltuunsa vuoriston. Hän ei näet kyennyt karkottamaan niitä, jotka asuivat tasangolla, koska heillä oli raudoitettuja sotavaunuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'He antoivat Kaalebille Hebronin, niin kuin Mooses oli puhunut. Hän karkotti sieltä ne kolme anakilaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Mutta benjaminilaiset eivät karkottaneet jebusilaisia, jotka asuivat Jerusalemissa, ja jebusilaiset jäivät asumaan benjaminilaisten keskuuteen Jerusalemiin aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Myös Joosefin heimo lähti liikkeelle. Se lähti Beeteliin, ja Herra oli heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Joosefin heimo lähetti vakoilijoita Beeteliin – kaupungin nimi oli muinoin Luus –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'ja vakoilijat näkivät miehen tulevan kaupungista ja sanoivat hänelle: \"Näytä meille, mistä päästään kaupunkiin, niin teemme sinulle laupeuden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Hän näytti heille, mistä päästiin kaupunkiin, ja he surmasivat miekan terällä kaupungin asukkaat, mutta miehen ja koko hänen sukunsa he päästivät menemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Mies meni heettiläisten maahan ja rakensi kaupungin ja antoi sille nimen Luus. Se nimi sillä on vielä tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Mutta Manasse ei saanut haltuunsa Beet-Seania ja sen tytärkaupunkeja, ei Taanakia ja sen tytärkaupunkeja, ei Doorin asukkaita ja sen tytärkaupunkeja, ei Jibleamin asukkaita ja sen tytärkaupunkeja eikä Megiddon asukkaita ja sen tytärkaupunkeja, vaan kanaanilaisten onnistui jäädä asumaan maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Kun Israel sitten voimistui, se saattoi kanaanilaiset työveron alaisiksi, mutta ei karkottanut heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Efraim ei karkottanut kanaanilaisia, jotka asuivat Geserissä. Niin kanaanilaiset jäivät asumaan sen keskuuteen Geseriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Sebulon ei karkottanut Kidronin asukkaita eikä Nahalolin asukkaita. Kanaanilaiset jäivät asumaan sen keskuuteen, mutta joutuivat työveron alaisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Asser ei karkottanut Akkon asukkaita eikä Siidonin asukkaita eikä myöskään Ahlabin, Aksibin, Helban, Afekin ja Rehobin asukkaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'Asserilaiset asuivat maan asukkaiden, kanaanilaisten, keskuudessa, koska eivät karkottaneet heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Naftali ei karkottanut Beet-Semeksen asukkaita eikä Beet-Anatin asukkaita ja asui maan asukkaiden, kanaanilaisten, keskuudessa. Mutta Beet-Semeksen ja Beet-Anatin asukkaat olivat heille työveron alaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Amorilaiset tunkivat daanilaiset vuoristoon, sillä he eivät sallineet heidän laskeutua tasangolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Amorilaisten onnistui jäädä asumaan Har-Herekseen, Aijaloniin ja Saalbimiin, mutta Joosefin heimon käsi kävi heille raskaaksi, ja he olivat työveron alaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Amorilaisten alue ulottui Skorpionisolasta, Seelasta, ylöspäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Herran Enkeli tuli Gilgalista ylös Bookimiin. Hän sanoi: \"Johdatin teidät Egyptistä ja toin teidät maahan, jonka valalla vannoen olin luvannut isillenne, ja sanoin: \'Minä en riko liittoani teidän kanssanne ikinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Te taas älkää tehkö liittoa tämän maan asukasten kanssa, vaan kukistakaa heidän alttarinsa.\' Mutta te ette ole kuulleet minun ääntäni. Mitä olettekaan tehneet!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Minäkin sanon nyt teille: Minä en karkota heitä tieltänne, vaan heistä tulee teille ahdistajia, ja heidän jumalansa tulevat teille ansaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Kun Herran Enkeli oli puhunut nämä sanat kaikille israelilaisille, kansa korotti äänensä ja itki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'He antoivat paikalle nimen Bookim ja uhrasivat siinä Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Kun Joosua oli päästänyt kansan menemään, israelilaiset olivat menneet kukin perintöosalleen ottaakseen maan omakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Kansa oli palvellut Herraa Joosuan koko elinajan ja niiden vanhinten koko elinajan, jotka elivät vielä kauan Joosuan jälkeen ja jotka olivat nähneet kaikki ne suuret teot, jotka Herra oli tehnyt Israelille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Mutta Herran palvelija Joosua, Nuunin poika, oli kuollut sadan kymmenen vuoden vanhana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'He olivat haudanneet hänet hänen perintöosansa alueelle Timnat-Herekseen, Efraimin vuoristoon, Gaas-vuoren pohjoispuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Kun koko sekin sukupolvi oli tullut kootuksi isiensä luo, heidän jälkeensä nousi toinen sukupolvi, joka ei tuntenut Herraa eikä niitä tekoja, jotka hän oli tehnyt Israelille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Israelilaiset tekivät sitä, mikä oli pahaa Herran silmissä, ja palvelivat baaleja');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'ja hylkäsivät Herran, isiensä Jumalan, joka oli vienyt heidät pois Egyptin maasta. He lähtivät kulkemaan muiden jumalien perässä, niiden kansojen jumalien, jotka asuivat heidän ympärillään, kumarsivat niitä ja vihoittivat Herran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Mutta kun he hylkäsivät Herran ja palvelivat baalia ja astarteja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Herran viha syttyi Israelia kohtaan, ja hän antoi heidät ryöstäjien käsiin, jotka ryöstivät heitä, ja myi heidät heidän ympärillään asuvien vihollisten käsiin, niin etteivät he enää voineet kestää vihollistensa edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Mihin he lähtivätkin, Herran käsi oli heitä vastaan tuottaen onnettomuutta, niin kuin Herra oli puhunut ja niin kuin Herra oli heille vannonut. He joutuivat suureen ahdinkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Silloin Herra herätti tuomareita, jotka pelastivat heidät heidän ryöstäjiensä käsistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Mutta he eivät totelleet tuomareitansakaan, vaan kulkivat haureudessa muiden jumalien jäljessä ja kumarsivat niitä. Pian he poikkesivat siltä tieltä, jota heidän isänsä Herran käskyjä totellen olivat kulkeneet eivätkä tehneet niin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Kun siis Herra herätti heille tuomareita, niin Herra oli tuomarin kanssa ja pelasti heidät heidän vihollistensa käsistä niin kauaksi aikaa, kuin tuomari eli. Sillä Herran tuli sääli, kun he voihkivat sortajiensa ja ahdistajiensa käsissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Mutta kun tuomari kuoli, he vaelsivat jälleen kelvottomasti, vielä pahemmin kuin heidän isänsä, kulkien muiden jumalien perässä, palvellen ja kumartaen niitä. He eivät lakanneet teoistaan eivätkä paatuneesta vaelluksestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Herran viha syttyi Israelia kohtaan, ja hän sanoi: \"Koska tämä kansa on rikkonut liittoni, jonka minä säädin heidän isilleen, eivätkä he ole kuulleet ääntäni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'en minäkään enää karkota heidän tieltään ainoatakaan niistä kansoista, jotka Joosua kuollessaan jätti jäljelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'Minä tahdon näin heissä koetella Israelia, noudattavatko he Herran tietä ja vaeltavatko sitä, niin kuin heidän isänsä tekivät, vai eivät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Niin Herra jätti nämä kansat paikoilleen karkottamatta niitä heti. Hän ei ollut antanut niitä Joosuan käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Nämä ovat ne kansat, jotka Herra jätti paikoilleen koetellakseen niillä Israelia, kaikkia niitä, jotka eivät olleet kokeneet mitään mistään Kanaanin sodista –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'hän jätti ne ainoastaan sitä varten, että israelilaisten sukupolvet saisivat kokea sotaa hänen opettaessaan heitä sotimaan, kuitenkin ainoastaan niitä, jotka eivät ennen olleet sotaa kokeneet –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'filistealaisten viisi ruhtinasta ja kaikki kanaanilaiset ja siidonilaiset ja hivviläiset, jotka asuivat Libanonin vuoristossa, Baal-Hermonin vuoresta siihen saakka, mistä mennään Hamatiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Nämä jäivät, että hän niiden kautta koettelisi Israelia saadakseen tietää, tottelisivatko he Herran käskyjä, jotka hän oli antanut Mooseksen kautta heidän isilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Israelilaiset asuivat siis kanaanilaisten, heettiläisten, amorilaisten, perissiläisten, hivviläisten ja jebusilaisten keskellä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'ja ottivat heidän tyttäriään vaimoikseen ja antoivat omia tyttäriään heidän pojilleen ja palvelivat heidän jumaliaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Israelilaiset tekivät sitä, mikä oli pahaa Herran silmissä, ja unohtivat Herran, Jumalansa, ja palvelivat baaleja ja aseroja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Herran viha syttyi Israelia kohtaan, ja hän myi heidät Kuusan-Risataimin, Mesopotamian kuninkaan, käsiin. Israelilaiset palvelivat Kuusan-Risataimia kahdeksan vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Mutta israelilaiset huusivat Herraa, ja Herra herätti israelilaisille vapauttajan, joka heidät vapautti, Otnielin, Kenaan, Kaalebin nuoremman veljen, pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Herran Henki tuli häneen, ja hän oli tuomarina Israelissa. Hän lähti sotaan, ja Herra antoi Kuusan-Risataimin, Aramin kuninkaan, hänen käsiinsä, ja Kuusan-Risataim sai tuntea hänen kätensä voiman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Maassa oli rauha neljäkymmentä vuotta. Sitten Otniel, Kenaan poika, kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Mutta israelilaiset tekivät jälleen sitä, mikä oli pahaa Herran silmissä. Silloin Herra vahvisti Eglonin, Mooabin kuninkaan, Israelia väkevämmäksi, koska he tekivät sitä, mikä oli pahaa Herran silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Tämä kokosi luokseen ammonilaiset ja amalekilaiset, lähti liikkeelle ja voitti Israelin, ja he valtasivat Palmukaupungin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Israelilaiset palvelivat Eglonia, mooabilaisten kuningasta, kahdeksantoista vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Israelilaiset huusivat Herraa, ja Herra herätti heille vapauttajan, benjaminilaisen Eehudin, Geeran pojan, vasenkätisen miehen. Kun israelilaiset lähettivät hänet viemään veroa Eglonille, Mooabin kuninkaalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'niin Eehud teki itselleen kaksiteräisen miekan, jalan pituisen, ja sitoi sen takkinsa alle oikealle lanteelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'Hän toi veron Eglonille, Mooabin kuninkaalle. Mutta Eglon oli hyvin lihava mies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Kun Eehud oli saanut tuoduksi veron, hän lähetti matkaan väen, joka oli kantanut verolahjoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Mutta hän itse kääntyi takaisin Gilgalin luona olevilta jumalankuvilta ja käski sanoa: \"Minulla on salaista asiaa sinulle, kuningas.\" Niin tämä sanoi: \"Hiljaa!\" Silloin kaikki, jotka seisoivat hänen luonaan, poistuivat hänen luotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Kun Eehud oli tullut hänen luokseen hänen istuessaan yksin viileässä yläsalissa, Eehud sanoi: \"Minulla on sinulle sana Jumalalta.\" Silloin hän nousi istuimeltaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'mutta Eehud ojensi vasemman kätensä ja tempasi miekan oikealta lanteeltaan ja pisti sen hänen vatsaansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'niin että kahvakin meni sisään terän mukana ja terä upposi kokonaan ihraan, sillä hän ei vetänyt ulos miekkaa hänen vatsastaan. Sitten hän meni ulos laakealle katolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Kun Eehud oli tullut pylväskäytävään, hän sulki yläsalin ovet jälkeensä ja lukitsi ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Hänen mentyään tulivat kuninkaan palvelijat, ja kun he näkivät, että yläsalin ovet olivat lukitut, niin he ajattelivat: \"Varmaankin hän on tarpeellaan viileässä kammiossa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Sitten he odottivat kyllästymiseen asti, mutta kun hän ei sittenkään avannut yläsalin ovia, he ottivat avaimen ja avasivat itse. Niin, katso, heidän herransa makasi kuolleena lattialla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Mutta Eehud oli paennut heidän vitkastellessaan. Hän oli jo päässyt jumalankuvien ohi ja pakeni Seiraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Sinne tultuaan hän puhalsi torveen Efraimin vuoristossa. Silloin israelilaiset laskeutuivat hänen kanssaan vuoristosta, ja hän heidän etunenässään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Hän sanoi heille: \"Seuratkaa minua, sillä Herra antaa vihollisenne, mooabilaiset, käsiinne.\" Silloin he laskeutuivat hänen jäljessään alas, valtasivat mooabilaisten tieltä Jordanin kahluupaikat eivätkä päästäneet ketään yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'He voittivat silloin Mooabin, lähes kymmenen tuhatta miestä, kaikki voimakkaita ja sotakuntoisia miehiä, eikä ainoakaan päässyt pakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Mooab nöyrtyi sinä päivänä Israelin käden alle. Maassa oli rauha kahdeksankymmentä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Hänen jälkeensä tuli Samgar, Anatin poika. Hän surmasi filistealaisia kuusisataa miestä häränpistimellä. Hänkin vapautti Israelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Mutta Eehudin kuoltua israelilaiset tekivät jälleen sitä, mikä oli pahaa Herran silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Herra myi heidät Jaabinin, Kanaanin kuninkaan, käsiin, joka hallitsi Haasorissa. Hänen sotapäällikkönsä oli Siisera, joka asui Haroset-Goojimissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Israelilaiset huusivat Herraa, sillä Siiseralla oli yhdeksänsataa raudoitettua sotavaunua, ja hän sorti ankarasti israelilaisia kaksikymmentä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'Debora, naisprofeetta, Lappidotin vaimo, oli siihen aikaan tuomarina Israelissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Hänen oli tapana istua Debora-palmun alla, Raaman ja Beetelin välillä Efraimin vuoristossa, ja israelilaiset menivät hänen luokseen saamaan oikeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Hän lähetti kutsumaan Baarakin, Abinoamin pojan, Naftalin Kedeksestä, ja sanoi hänelle: \"Näin käskee Herra, Israelin Jumala: Lähde ja mene Taaborin vuorelle ja ota mukaasi kymmenentuhatta miestä naftalilaisia ja sebulonilaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Minä tuon luoksesi Kiisonin purolle Siiseran, Jaabinin sotapäällikön, sotavaunuineen ja laumoineen ja annan hänet käsiisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Niin Baarak sanoi hänelle: \"Jos sinä lähdet kanssani, niin minäkin lähden, mutta jos et lähde kanssani, niin en minäkään lähde.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Hän vastasi: \"Lähden kanssasi, mutta kunnia siitä retkestä, jolle lähdet, ei tule sinulle, vaan Herra on myyvä Siiseran naisen käsiin.\" Debora nousi ja lähti Baarakin kanssa Kedekseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Baarak kutsui Sebulonin ja Naftalin koolle Kedekseen. Kymmenentuhatta miestä seurasi häntä, ja Debora lähti hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Mutta keeniläinen Heber oli eronnut keeniläisistä, Hoobabin, Mooseksen apen, jälkeläisistä. Hän oli telttaansa pystytellen tullut aina Saanaimin tammelle asti, joka on Kedeksen luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Kun Siiseralle ilmoitettiin, että Baarak, Abinoamin poika, oli noussut Taaborin vuorelle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Siisera kutsui koolle kaikki sotavaununsa, yhdeksänsataa raudoitettua sotavaunua, ja kaiken väen, mikä hänellä oli, Haroset-Goojimista Kiisonin purolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Debora sanoi Baarakille: \"Nouse, sillä tämä on se päivä, jona Herra antaa Siiseran käsiisi. Onhan Herra lähtenyt edelläsi.\" Baarak laskeutui Taaborin vuorelta, ja häntä seurasi kymmenentuhatta miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Herra saattoi Baarakin miekan terän edessä sekasortoon Siiseran ja kaikki hänen sotavaununsa ja koko hänen joukkonsa. Siisera astui alas vaunuistaan ja pakeni jalkaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Mutta Baarak ajoi takaa sotavaunuja ja sotajoukkoa Haroset-Goojimiin saakka. Koko Siiseran joukko kaatui miekan terään. Ainoakaan ei pelastunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Siisera oli paennut jalkaisin Jaaelin, keeniläisen Heberin vaimon, teltalle. Jaabinin, Haasorin kuninkaan, ja keeniläisen Heberin perheen välillä oli näet rauha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Jaael meni Siiseraa vastaan ja sanoi hänelle: \"Poikkea, herrani, poikkea luokseni, älä pelkää.\" Hän poikkesi hänen luokseen telttaan, ja hän peitti hänet peitteellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Hän sanoi hänelle: \"Anna minulle vähän vettä juodakseni, sillä minun on jano.\" Niin hän avasi maitoleilin ja antoi hänen juoda ja peitti hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Hän sanoi hänelle: \"Asetu teltan ovelle. Jos joku tulee ja kysyy sinulta ja sanoo: \'Onko täällä ketään?\' vastaa: \'Ei ole.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Mutta Jaael, Heberin vaimo, tempasi telttavaarnan, otti vasaran käteensä, hiipi hänen luokseen ja löi vaarnan hänen ohimoonsa, niin että se tunkeutui aina maahan asti. Hän oli näet väsymyksestä vaipunut sikeään uneen, ja hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Katso, silloin Baarak tuli ajaen Siiseraa takaa. Jaael meni häntä vastaan ja sanoi hänelle: \"Tule, näytän sinulle miehen, jota etsit.\" Hän tuli hänen luokseen, ja katso, Siisera makasi kuolleena, vaarna ohimossaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Näin Jumala sinä päivänä nöyryytti Jaabinin, Kanaanin kuninkaan, israelilaisten edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Israelilaisten käsi painoi yhä raskaammin Jaabinia, Kanaanin kuningasta, kunnes he tuhosivat Jaabinin, Kanaanin kuninkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Sinä päivänä Debora ja Baarak, Abinoamin poika, lauloivat näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, '\"Johtajat johtivat Israelia, kansa oli altis. Kiittäkää Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Kuulkaa, te kuninkaat, kuunnelkaa, te ruhtinaat. Herran kiitosta minä laulan. Minä veisaan Herran, Israelin Jumalan, ylistystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Kun sinä, Herra, lähdit liikkeelle Seiristä, kun marssit Edomin maasta, maa järisi, ja taivaat vuotivat, pilvet vuotivat vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Vuoret järkkyivät Herran edessä, itse Siinai Herran, Israelin Jumalan, edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Samgarin, Anatin pojan, päivinä, Jaaelin päivinä tiet olivat tyhjät, matkamiehet kiertelivät syrjäisiä polkuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Israel oli johtoa vailla, peräti vailla, kunnes sinä, Debora, nousit, sinä, Israelin äiti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'He valitsivat uusia jumalia. Silloin oli sota porteilla asti, mutta ei näkynyt kilpeä, ei keihästä Israelin neljänkymmenen tuhannen joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Sydämeni on kiintynyt Israelin johtomiehiin. Te kansan joukossa alttiit, kiittäkää Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Te, jotka ratsastatte valkoisilla aasintammoilla, te, jotka istutte matoilla, ja te, jotka kuljette teillä, puhukaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Laulu kuuluu juotto-ojilta, siellä ylistetään Herran vanhurskaita tekoja, hänen johdatuksensa vanhurskautta Israelissa. Silloin Herran kansa laskeutui porteille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Herää, herää, Debora! Herää, herää, laula laulu! Nouse, Baarak! Ota vankeja saaliiksesi, sinä Abinoamin poika!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Silloin pakolaiset laskeutuivat näiden jalojen luo. Herran kansa, sankarien joukko, laskeutui luokseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Efraimista tulivat ne, jotka saivat juurensa Amalekiin, he seurasivat joukkojesi mukana, Benjamin. Maakirista laskeutuivat johtomiehet, Sebulonista ne, jotka vetävät esiin kirjurin valtikan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Isaskarin ruhtinaat tulivat Deboran kanssa, ja niin kuin Baarak, niin Isaskar: hän kiiti tasangolle hänen jäljessään. Ruubenin suvuissa oli suuria neuvotteluja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Miksi jäit istumaan karjatarhojen välille, kuuntelemaan paimenpillin soittoa? Ruubenin suvuissa oli suuria neuvonpitoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gilead pysyi alallaan tuolla puolella Jordanin, ja Daan – miksi hän viipyi vierailla laivoilla? Asser jäi istumaan meren rannalle ja pysyi alallaan lahtiensa luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Sebulon on kansa, joka antaa henkensä alttiiksi kuolemaan, samoin Naftali kedon kummuilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Kuninkaat tulivat ja taistelivat. Silloin taistelivat Kanaanin kuninkaat Taanakissa, Megiddon vesien varsilla. Mutta hopeaa he eivät saaneet saaliikseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Tähdet taivaalta kävivät sotaa. Radoiltaan ne sotivat Siiseraa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Kiisonin puro tempasi heidät mukaansa, taistelujen puro, Kiisonin puro. Astu esiin, sieluni, voimassa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Silloin hevoset tömistivät kavioillaan, kun he rynnistivät urhoollisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Kirotkaa Meeros, sanoo Herran Enkeli, kiroamalla kirotkaa sen asukkaat, koska eivät tulleet Herran avuksi, Herran avuksi sankarien joukkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Siunattu olkoon vaimojen joukossa Jaael, keeniläisen Heberin vaimo, siunattu vaimojen joukossa, jotka teltoissa asuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Vettä toinen pyysi, maitoa hän antoi, toi juhlamaljassa kokkelipiimää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Hän ojensi kätensä ottamaan vaarnaa, oikean kätensä työvasaraa. Hän iski Siiseraa, löi murskaksi hänen päänsä, musersi ja lävisti hänen ohimonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Hänen jalkojensa juureen hän vaipui, kaatui, jäi siihen, hänen jalkojensa juureen hän vaipui, kaatui, ja jäi kuolleena makaamaan siihen, mihin vaipui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Siiseran äiti katselee ikkunasta ja huutaa ristikon läpi: \'Miksi hänen sotavaunujensa tulo viipyy? Miksi hänen valjakkonsa askeleet ovat niin hitaat?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Viisain hänen ruhtinattaristaan vastaa hänelle, ja hän kertaa itselleen hänen sanansa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, '\'Varmaankin he ovat saaneet saalista ja jakavat sitä: tytön, kaksikin mieheen, kirjavaa kangasta saaliiksi Siiseralle, kirjavaa kangasta, kirjailtua vaatetta saaliiksi, kaksi kirjailtua, kirjavaa huivia saatujen saalisten kaulaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Niin häviävät kaikki vihollisesi, Herra. Mutta ne, jotka häntä rakastavat, ovat kuin aurinko, kun se nousee voimassaan.\" Maassa oli rauha neljäkymmentä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Mutta israelilaiset tekivät sitä, mikä oli pahaa Herran silmissä, ja Herra antoi heidät Midianin käsiin seitsemäksi vuodeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Silloin Israel sai tuntea Midianin käden voiman, ja israelilaiset tekivät suojakseen midianilaisia vastaan ne onkalot, joita on vuorissa, ja luolat ja vuorilinnat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Joka kerta kun israelilaiset olivat kylväneet, tulivat midianilaiset, amalekilaiset ja Idän miehet ja hyökkäsivät heidän kimppuunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'He leiriytyivät heitä vastaan ja hävittivät maan sadon aina Gassaa myöten eivätkä jättäneet mitään elintarpeita Israeliin, eivät myöskään lampaita, nautakarjaa eivätkä aaseja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Sillä he lähtivät liikkeelle laumoineen ja telttoineen, he tulivat monilukuisina kuin heinäsirkat, heitä ja heidän kameleitaan oli lukematon määrä, ja he tulivat maahan hävittämään sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Niin Israel joutui suureen kurjuuteen midianilaisten tähden, ja israelilaiset huusivat avuksi Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Kun israelilaiset huusivat Herraa Midianin tähden,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'Herra lähetti israelilaisten luo profeetan, joka sanoi heille: \"Näin sanoo Herra, Israelin Jumala: Minä johdatin teidät Egyptistä ja vein teidät pois orjuuden pesästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'Pelastin teidät egyptiläisten käsistä ja kaikkien sortajienne käsistä. Karkotin heidät teidän tieltänne ja annoin teille heidän maansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'Sanoin teille: Minä olen Herra, teidän Jumalanne, älkää pelätkö amorilaisten jumalia, joiden maassa asutte. Mutta ette kuulleet ääntäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Herran Enkeli tuli ja istui Ofran tammen alle, joka oli abieserilaisen Jooaan oma, juuri kun tämän poika Gideon oli puimassa vehnää viinikuurnassa korjatakseen ne talteen midianilaisilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Herran Enkeli ilmestyi hänelle ja sanoi hänelle: \" Herra olkoon kanssasi, sinä väkevä sankari!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Gideon vastasi hänelle: \"Oi, Herrani, jos Herra on kanssamme, miksi sitten kaikki tämä on kohdannut meitä? Missä ovat kaikki hänen ihmetekonsa, joista isämme ovat meille kertoneet sanoen: \' Herra on johdattanut meidät tänne Egyptistä\'? Mutta nyt Herra on hylännyt meidät ja antanut meidät Midianin kouriin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Silloin Herra kääntyi häneen ja sanoi: \"Mene tässä voimassasi ja vapauta Israel Midianin kourista. Enkö ole sinua lähettänyt?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Hän vastasi hänelle: \"Oi, Herrani, millä minä vapautan Israelin? Sukunihan on heikoin Manassessa, ja minä olen kaikkein vähäpätöisin isäni perheessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Herra sanoi hänelle: \"Olen kanssasi, ja [sinä] voitat midianilaiset kuin yhden miehen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Mutta hän sanoi hänelle: \"Jos olen saanut armon silmiesi edessä, osoita minulle tunnusteolla, että sinä itse puhut kanssani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Älä poistu täältä, ennen kuin tulen takaisin luoksesi ja tuon uhrilahjani ja panen sen eteesi.\" Hän sanoi: \"Minä jään, kunnes tulet takaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Gideon meni ja valmisti kilin, ja eefa-mitan jauhoja happamattomiksi leiviksi, pani lihan koriin ja liemen pataan ja vei ne hänen luokseen tammen alle ja pani ne tarjolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Mutta Jumalan Enkeli sanoi hänelle: \"Ota liha ja happamattomat leivät ja pane ne tälle kalliolle ja vuodata liemi.\" Hän teki niin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Herran Enkeli ojensi sauvan, joka hänellä oli kädessään, ja kosketti sen kärjellä lihaa ja happamattomia leipiä. Kalliosta nousi tuli, ja se kulutti lihan ja happamattomat leivät. Sitten Herran Enkeli meni pois hänen silmistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Kun Gideon näki, että se oli ollut Herran Enkeli, Gideon sanoi: \"Voi minua, Herra, Herra, kun olen nähnyt Herran Enkelin kasvoista kasvoihin!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Mutta Herra sanoi hänelle: \"Rauha sinulle! Älä pelkää, sinä et kuole.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Silloin Gideon rakensi siihen Herralle alttarin ja pani sen nimeksi: \" Herra on rauha.\" Se on vielä tänäkin päivänä abieserilaisten Ofrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Sinä yönä Herra sanoi hänelle: \"Ota härkä, joka on isälläsi, ja toinen seitsenvuotias härkä ja hajota Baalin alttari, joka isälläsi on, ja hakkaa maahan aserapaalu, joka on sen vieressä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Rakenna sitten ladotuista kivistä alttari Herralle, Jumalallesi, tämän vuorenkukkulan laelle. Ota sitten toinen härkä ja uhraa se polttouhriksi polttopuiden päällä, jotka saat hakkaamastasi aserapaalusta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Gideon otti palvelijoitaan kymmenen miestä ja teki, niin kuin Herra oli hänelle puhunut. Mutta kun hän isänsä perhettä ja kaupungin miehiä peläten ei uskaltanut tehdä sitä päivällä, hän teki sen yöllä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Kun kaupungin miehet varhain seuraavana aamuna nousivat, katso, Baalin alttari oli kukistettu ja aserapaalu oli sen vierestä hakattu maahan, ja toinen härkä oli uhrattu polttouhriksi vastarakennetulla alttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'He sanoivat toinen toiselleen: \"Kuka tämän on tehnyt?\" Kun he tutkivat ja tiedustelivat, sanottiin: \"Gideon, Jooaan poika, on sen tehnyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Silloin kaupungin miehet sanoivat Jooaalle: \"Tuo tänne poikasi, hänen täytyy kuolla, sillä hän on tuhonnut Baalin alttarin ja hakannut maahan aserapaalun sen vierestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Mutta Jooas vastasi kaikille, jotka seisoivat hänen ympärillään: \"Tekö ajatte Baalin asiaa, tekö autatte häntä? Se, joka ajaa hänen asiaansa, rangaistakoon kuolemalla ennen huomisaamua. Jos hän on jumala, ajakoon itse asiansa, koska kukistettu alttari oli hänen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Sinä päivänä Gideon sai nimekseen Jerubbaal, sillä sanottiin: \"Baal ajakoon itse asiansa häntä vastaan, koska hän on kukistanut hänen alttarinsa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Kaikki midianilaiset, amalekilaiset ja Idän miehet olivat kokoontuneet yhteen, tulleet virran yli ja leiriytyneet Jisreelin tasangolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Herran Henki täytti Gideonin. Hän puhalsi torveen, ja abieserilaiset kutsuttiin koolle seuraamaan häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Hän lähetti sanansaattajia koko Manasseen, niin että heidätkin kutsuttiin koolle seuraamaan häntä. Samoin hän lähetti sanansaattajat Asseriin, Sebuloniin ja Naftaliin, ja nämä lähtivät vihollisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Silloin Gideon sanoi Jumalalle: \"Jos sinä aiot vapauttaa Israelin kädelläni, niin kuin olet puhunut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'katso, minä panen nämä kerityt villat puimatantereelle: jos kastetta tulee ainoastaan villoihin ja kaikki maa muuten jää kuivaksi, tiedän, että sinä vapautat kädelläni Israelin, niin kuin olet puhunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Tapahtui niin. Sillä kun hän varhain seuraavana päivänä nousi ja puristi villoja, pusersi hän kastetta villoista koko vesimaljan täyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Gideon sanoi Jumalalle: \"Älköön vihasi syttykö minua kohtaan, jos minä vielä kerran puhun. Anna minun tehdä vielä yksi koe villoilla. Anna ainoastaan villojen jäädä kuiviksi ja kastetta tulla kaikkialle muualle maahan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Jumala teki niin sinä yönä. Ainoastaan villat jäivät kuiviksi, ja kastetta tuli kaikkialle muualle maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Varhain seuraavana aamuna Jerubbaal, se on Gideon, sekä kaikki väki, joka oli hänen kanssaan, leiriytyi Harodin lähteelle. Midianilaisten leiri taas oli siitä, Mooren kukkulasta, pohjoiseen tasangolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Herra sanoi Gideonille: \"Sinulla on kanssasi liian paljon väkeä antaakseni Midianin heidän käsiinsä. Muuten Israel voisi kerskua minua vastaan ja sanoa: \'Oma käteni vapautti minut.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Julista siis kansan kuullen näin: \'Se, joka pelkää ja on arka, palatkoon takaisin ja väistyköön Gileadin vuorilta.\'\" Niin kansasta palasi takaisin kaksikymmentäkaksi tuhatta, ja kymmenentuhatta jäi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Herra sanoi Gideonille: \"Vielä on väkeä liian paljon. Vie heidät alas veden ääreen, niin minä tutkin heidät siellä sinulle. Se, josta minä sinulle sanon: \'Tämä lähteköön kanssasi\', se lähteköön kanssasi. Mutta kukaan, josta minä sinulle sanon: \'Tämä älköön lähtekö kanssasi\', älköön lähtekö.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Hän vei väen alas veden ääreen. Herra sanoi Gideonille: \"Aseta erikseen jokainen, joka latkii vettä kielellään, niin kuin koira latkii, ja samoin jokainen, joka laskeutuu polvilleen juomaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Niiden luku, jotka latkivat kädestä suuhunsa, oli kolmesataa miestä. Kaikki muu väki oli laskeutunut polvilleen juomaan vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Herra sanoi Gideonille: \"Niillä kolmellasadalla miehellä, jotka latkivat, vapautan teidät ja annan Midianin käsiisi. Kaikki muu väki menköön kukin kotiinsa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Sitten väki otti mukaansa eväät ja torvensa, ja hän päästi kaikki Israelin miehet menemään kunkin majalleen pitäen ainoastaan ne kolmesataa miestä. Midianilaisten leiri oli hänen alapuolellaan tasangolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Sinä yönä Herra sanoi hänelle: \"Nouse ja käy leirin kimppuun, sillä minä annan sen sinun käsiisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Mutta jos sinä pelkäät käydä sen kimppuun, mene palvelijasi Puuran kanssa alas leiriin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'ja kuuntele, mitä siellä puhutaan. Sitten saat rohkeutta käydä leirin kimppuun.\" Hän meni palvelijansa Puuran kanssa alas aina leirin etuvartijoiden luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Midianilaisia, amalekilaisia ja kaikkia Idän miehiä oli asettunut tasangolle paljon kuin heinäsirkkoja, eikä heidän kameleillaan ollut määrää, niitä oli niin paljon kuin hiekkaa meren rannalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Kun Gideon tuli, muuan mies kertoi untaan toiselle. Hän sanoi: \"Minä näin unta ja katso, ohraleipäkakku tuli pyörien midianilaisten leiriin. Se tuli teltalle saakka, iski siihen niin, että se kaatui, ja käänsi sen ylösalaisin, ja teltta jäi kumoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Toinen vastasi ja sanoi: \"Se ei ole mikään muu kuin israelilaisen Gideonin, Jooaan pojan, miekka. Jumala antaa hänen käsiinsä Midianin ja koko leirin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Kun Gideon oli kuullut kertomuksen unesta ja sen selityksen, hän rukoili kumartaen, palasi sitten takaisin Israelin leiriin ja sanoi: \"Nouskaa, sillä Herra antaa midianilaisten leirin käsiinne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Hän jakoi ne kolmesataa miestä kolmeen joukkoon ja antoi heille kullekin käteen torven ja tyhjän saviruukun tulisoihdun ollessa ruukussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Hän sanoi heille: \"Ottakaa minusta mallia ja tehkää kuten minä. Katso, kun minä olen tullut leirin laitaan, tehkää, kuten minä teen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Kun minä ja kaikki, jotka ovat kanssani, puhallamme torviin, niin puhaltakaa tekin torviin kaikkialla leirin ympärillä ja huutakaa: \' Herran ja Gideonin puolesta!\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Niin Gideon ja ne sata miestä, jotka olivat hänen kanssaan, tulivat leirin laitaan keskimmäisen yövartion alussa. Vartijat olivat juuri asetetut paikoilleen. He puhalsivat torviin ja särkivät saviruukut, jotka heillä oli käsissään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Ne kolme joukkoa puhalsivat torviin, murskasivat saviruukut, tempasivat vasempaan käteensä tulisoihdut ja oikeaan torvet, puhalsivat niihin ja huusivat: \" Herran ja Gideonin miekka!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'He seisoivat kukin paikallaan leirin ympärillä. Mutta leirissä kaikki juoksivat sekaisin, huusivat ja pakenivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Kun he puhalsivat noihin kolmeensataan torveen, Herra käänsi toisen miekan toista vastaan koko leirissä, ja leiri pakeni Beet-Sittaan asti Sereraan päin, Tabbatin luona olevan Aabel-Meholan rantaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Sitten Israelin miehet kutsuttiin koolle Naftalista, Asserista ja koko Manassesta, ja he ajoivat midianilaisia takaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Gideon oli lähettänyt sanansaattajia koko Efraimin vuoristoon sanomaan: \"Tulkaa alas midianilaisia vastaan ja vallatkaa heidän tieltään vedet aina Beet-Baaraan asti sekä Jordan.\" Kaikki Efraimin miehet kutsuttiin koolle, ja he valtasivat vedet aina Beet-Baaraan asti sekä Jordanin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'He ottivat vangiksi kaksi midianilaisten ruhtinasta, Oorebin ja Seebin. Oorebin he surmasivat Oorebin kalliolla, ja Seebin he surmasivat Seebin viinikuurnan luona, ja he ajoivat midianilaisia takaa. Oorebin ja Seebin päät he toivat Gideonille tuolta puolelta Jordanin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Efraimin miehet sanoivat hänelle: \"Miksi teit meille sen, ettet kutsunut meitä, kun lähdit taistelemaan midianilaisia vastaan?\" He riitelivät kovasti häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Niin hän sanoi heille: \"Mitä olen nyt tehnyt teihin verraten? Eikö Efraimin jälkikorjuu ole parempi kuin Abieserin viininkorjuu?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Teidän käsiinnehän Jumala antoi midianilaisten ruhtinaat Oorebin ja Seebin. Mitä minä olen voinut tehdä teihin verraten?\" Kun hän näin puhui, asettui heidän suuttumuksensa häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Kun Gideon tuli Jordanille, hän meni sen yli, hän ja ne kolmesataa miestä, jotka olivat hänen kanssaan. He olivat uuvuksissa takaa-ajosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Hän sanoi Sukkotin miehille: \"Antakaa joitakin leipäkakkuja väelle, joka seuraa minua, sillä he ovat uuvuksissa. Minä olen ajamassa takaa midianilaisten kuninkaita Sebahia ja Salmunnaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Mutta Sukkotin päämiehet sanoivat: \"Onko sinulla sitten jo Sebahin ja Salmunnan nyrkki kädessäsi, että antaisimme leipää sotajoukollesi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Gideon vastasi: \"Hyvä! Kun Herra antaa Sebahin ja Salmunnan käsiini, puin lihanne rikki erämaan orjantappuroilla ja orjanruoskilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Sitten hän kulki sieltä ylös Penueliin ja puhui heille samalla tavalla. Myös Penuelin miehet vastasivat hänelle samoin, kuin Sukkotin miehet olivat vastanneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Hän sanoi myös Penuelin miehille: \"Kunhan palaan voittajana, kukistan tämän tornin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Sebah ja Salmunna olivat Karkorissa ja heidän joukkonsa heidän kanssaan, noin viisitoista tuhatta miestä, kaikki, mitä oli jäljellä Idän miesten koko joukosta. Kaatuneita oli sata kaksikymmentä tuhatta miekkamiestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Gideon kulki teltoissa eläjien tietä Noobahin ja Jogbehan itäpuolitse ja voitti joukon, kun se oli huolettomana leirissään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Sebah ja Salmunna pakenivat, mutta hän ajoi heitä takaa. Hän otti molemmat midianilaisten kuninkaat, Sebahin ja Salmunnan, vangiksi saatettuaan koko leirin pakokauhun valtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Gideon, Jooaan poika, palasi taistelusta Hereksen solalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Hän otti kiinni erään nuorukaisen, joka oli Sukkotin miehiä, ja kyseli häneltä, ja tämä kirjoitti hänelle Sukkotin päämiehet ja vanhimmat, seitsemänkymmentä seitsemän miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Kun hän sitten tuli Sukkotin miesten luo, hän sanoi: \"Tässä ovat nyt Sebah ja Salmunna, joilla te pilkkasitte minua sanoen: \'Onko sinulla sitten jo Sebahin ja Salmunnan nyrkki kädessäsi, että antaisimme leipää uupuneille miehillesi?\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Hän otti kiinni kaupungin vanhimmat, otti sitten erämaan orjantappuroita ja orjanruoskia ja antoi Sukkotin miesten maistaa niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Hän kukisti Penuelin tornin ja surmasi kaupungin miehet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Sitten hän sanoi Sebahille ja Salmunnalle: \"Minkä näköisiä ne miehet olivat, jotka tapoitte Taaborilla?\" He vastasivat: \"Ne olivat niin kuin sinä. Jokainen oli varreltaan kuin kuninkaan poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Hän sanoi: \"He olivat veljiäni, äitini poikia. Niin totta kuin Herra elää: jos te olisitte jättäneet heidät henkiin, en surmaisi teitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Sitten hän sanoi Jeterille, esikoiselleen: \"Nouse ja surmaa heidät.\" Mutta nuorukainen ei paljastanut miekkaansa, sillä hän pelkäsi, koska oli vielä nuori.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Silloin sanoivat Sebah ja Salmunna: \"Nouse sinä ja pistä meidät kuoliaaksi, sillä miehellä on miehen voima.\" Gideon nousi ja surmasi Sebahin ja Salmunnan. Hän otti heidän kameliensa kaulasta puolikuukorut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Niin Israelin miehet sanoivat Gideonille: \"Hallitse sinä meitä, sekä sinä itse että poikasi ja poikasi poika. Olethan vapauttanut meidät Midianin käsistä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Mutta Gideon vastasi heille: \"En minä hallitse teitä, eikä poikani ole hallitseva teitä. Herra on teitä hallitseva.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Gideon sanoi heille: \"Yhtä pyydän teiltä: antakoon kukin minulle heiltä saaliiksi saamansa nenärenkaan.\" Heikäläisillä näet on kultaiset nenärenkaat, koska ovat ismaelilaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'He vastasivat: \"Annamme mielellämme.\" He levittivät viitan ja heittivät siihen kukin saaliiksi saamansa nenärenkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Hänen pyytämänsä kultaiset nenärenkaat painoivat tuhat seitsemänsataa kultasekeliä lukuun ottamatta niitä puolikuukoruja, korvarenkaita ja purppuravaatteita, joita midianilaisten kuninkaat olivat kantaneet, ja heidän kameliensa kaulaketjuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Gideon valmisti niistä kasukan, jonka hän sijoitti kaupunkiinsa Ofraan, ja koko Israel kulki haureudessa siellä sen jäljessä. Se tuli ansaksi Gideonille ja hänen perheelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Niin täytyi Midianin nöyrtyä israelilaisten edessä, eikä se enää nostanut päätään. Maassa oli rauha neljäkymmentä vuotta, niin kauan kuin Gideon eli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Jerubbaal, Jooaan poika, meni ja jäi asumaan taloonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Gideonilla oli seitsemänkymmentä poikaa, jotka olivat lähteneet hänen kupeistaan, sillä hänellä oli monta vaimoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Myös hänen sivuvaimonsa, joka hänellä oli Sikemissä, synnytti hänelle pojan, ja hän antoi tälle nimen Abimelek.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Gideon, Jooaan poika, kuoli päästyään korkeaan ikään, ja hänet haudattiin isänsä Jooaan hautaan abieserilaisten Ofraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Mutta kun Gideon oli kuollut, israelilaiset lähtivät haureudessa kulkemaan baalien jäljessä ja ottivat Baal-Beritin jumalakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Eivätkä israelilaiset enää muistaneet Herraa, Jumalaansa, joka oli pelastanut heidät kaikkien heidän vihollistensa käsistä, jotka asuivat heidän ympärillään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'He eivät myöskään tehneet Jerubbaalin, Gideonin, perheelle laupeutta kaiken sen hyvän tähden, mitä hän oli tehnyt Israelille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Abimelek, Jerubbaalin poika, meni Sikemiin äitinsä veljien luo ja puhui heille sekä kaikille, jotka olivat sukua hänen äitinsä isän perheelle, ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, '\"Puhukaa kaikkien Sikemin miesten kuullen: Kumpi teille on parempi, sekö, että teitä hallitsee seitsemänkymmentä miestä, kaikki Jerubbaalin pojat, vai että teitä hallitsee yksi mies? Muistakaa, että minä olen luutanne ja lihaanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Hänen äitinsä veljet puhuivat hänen puolestaan kaikkien Sikemin miesten kuullen kaiken tämän. Heidän sydämensä taipui Abimelekin puolelle, sillä he sanoivat: \"Hän on veljemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'He antoivat hänelle seitsemänkymmentä hopeasekeliä Baal-Beritin temppelistä. Niillä Abimelek palkkasi tyhjäntoimittajia ja huikentelijoita, ja ne seurasivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Sitten hän lähti isänsä taloon Ofraan ja surmasi veljensä, Jerubbaalin pojat, seitsemänkymmentä miestä, saman kiven päällä. Mutta Jootam, Jerubbaalin nuorin poika, jäi henkiin, sillä hän oli mennyt piiloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Sen jälkeen kaikki Sikemin miehet ja koko Millon väki kokoontuivat, menivät ja tekivät Abimelekin kuninkaaksi Muistomerkkitammen luona, joka on Sikemissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Kun se kerrottiin Jootamille, hän meni, asettui seisomaan Garissimin vuoren laelle ja korotti äänensä, huusi ja sanoi heille: \"Kuulkaa minua, te Sikemin miehet, että Jumalakin kuulisi teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Puut lähtivät voitelemaan itselleen kuningasta. He sanoivat öljypuulle: \'Ole sinä kuninkaamme.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Mutta öljypuu vastasi heille: \'Jättäisinkö lihavuuteni, josta jumalat ja ihmiset minua ylistävät, mennäkseni huojumaan ylempänä muita puita!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Puut sanoivat viikunapuulle: \'Tule sinä ja ole kuninkaamme.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Mutta viikunapuu vastasi heille: \'Jättäisinkö makeuteni ja hyvät hedelmäni mennäkseni huojumaan ylempänä muita puita!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Puut sanoivat viinipuulle: \'Tule sinä ja ole kuninkaamme.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Mutta viinipuu vastasi heille: \'Jättäisinkö rypälemehuni, joka saa jumalat ja ihmiset iloisiksi, mennäkseni huojumaan ylempänä muita puita!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Kaikki puut sanoivat orjantappuralle: \'Tule sinä ja ole kuninkaamme.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Orjantappura vastasi puille: \'Jos todella aiotte voidella minut kuninkaaksenne, tulkaa ja etsikää suojaa varjossani, mutta ellette, lähtee tuli orjantappurasta ja kuluttaa Libanonin setrit.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Jos te nyt olette menetelleet uskollisesti ja rehellisesti tehdessänne Abimelekin kuninkaaksi ja jos olette kohdelleet hyvin Jerubbaalia ja hänen perhettään ja jos olette palkinneet häntä siitä, mitä hyvää hänen kätensä ovat tehneet –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'sillä sotihan isäni teidän puolestanne ja pani alttiiksi henkensä ja pelasti teidät Midianin käsistä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'mutta te olette tänä päivänä nousseet isäni perhettä vastaan ja surmanneet hänen poikansa, seitsemänkymmentä miestä, saman kiven päällä ja tehneet Abimelekin, hänen orjattarensa pojan, Sikemin miesten kuninkaaksi, koska hän on teidän veljenne –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'jos te siis olette tänä päivänä menetelleet uskollisesti ja rehellisesti Jerubbaalia ja hänen perhettään kohtaan, olkoon teillä iloa Abimelekista ja olkoon hänelläkin iloa teistä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'mutta ellette ole, lähteköön tuli Abimelekista ja kuluttakoon Sikemin miehet sekä Millon väen. Samoin lähteköön tuli Sikemin miehistä ja Millon väestä ja kuluttakoon Abimelekin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Jootam lähti pakoon ja pääsi pakenemaan Beeriin. Hän asettui sinne suojaan veljeltään Abimelekilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Kun Abimelek oli hallinnut Israelia kolme vuotta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Jumala lähetti pahan hengen Abimelekin ja Sikemin miesten väliin, niin että Sikemin miehet luopuivat Abimelekista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'jotta Jerubbaalin seitsemällekymmenelle pojalle tehty väkivalta tulisi kostetuksi ja heidän verensä tulisi Abimelekin, heidän veljensä, päälle, joka oli heidät surmannut, ja Sikemin miesten päälle, jotka olivat auttaneet häntä surmaamaan veljensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Sikemin miehet asettivat vuorten kukkuloille väijyjiä, ja nämä ryöstivät jokaisen, joka kulki sitä tietä heidän ohitseen. Se kerrottiin Abimelekille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Mutta Gaal, Ebedin poika, tuli veljineen, ja he poikkesivat Sikemiin, ja Sikemin miehet luottivat häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'He menivät kedolle ja korjasivat sadon viinitarhoistaan, polkivat rypäleet ja pitivät ilojuhlan. He menivät jumalansa huoneeseen ja söivät, joivat ja kirosivat Abimelekia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Gaal, Ebedin poika, sanoi: \"Mikä on Abimelek, ja mikä on Sikem, että me häntä palvelisimme? Eikö hän ole Jerubbaalin poika, eikö Sebul ole hänen käskynhaltijansa? Palvelkaa Hamorin, Sikemin isän, miehiä. Miksi me palvelisimme häntä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Olisipa minulla tuo kansa vallassani, minä toimittaisin pois Abimelekin. Mutta Abimelekista hän sanoi: \'Lisää sotajoukkoasi ja tule!\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Mutta kun Sebul, kaupungin päällikkö, kuuli Gaalin, Ebedin pojan, sanat, syttyi hänen vihansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'Hän lähetti salaa sanansaattajia Abimelekin luo sanomaan: \"Katso, Gaal, Ebedin poika, ja hänen veljensä ovat tulleet Sikemiin, ja nyt he yllyttävät kaupunkia sinua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Nouse siis yöllä, sinä ja väki, joka on kanssasi, ja asetu kedolle väijyksiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Karkaa aamulla varhain, auringon noustessa, kaupungin kimppuun. Kun hän ja väki, joka on hänen kanssaan, lähtee silloin sinua vastaan, tee hänelle, minkä voit.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Silloin Abimelek ja kaikki väki, joka oli hänen kanssaan, lähti liikkeelle yöllä, ja he asettuivat väijyksiin Sikemiä vastaan neljässä joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Gaal, Ebedin poika, tuli ulos ja asettui kaupungin portin ovelle. Silloin Abimelek ja väki, joka oli hänen kanssaan, nousi väijyksistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Kun Gaal näki väen, hän sanoi Sebulille: \"Katso, väkeä tulee alas vuorten kukkuloilta.\" Mutta Sebul vastasi hänelle: \"Vuorten varjot näyttävät sinusta miehiltä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Gaal puhui taas ja sanoi: \"Katso, väkeä tulee alas Maan navalta, ja toinen joukko tulee Tietäjätammelta päin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Sebul sanoi hänelle: \"Missä on nyt sinun suuri suusi, kun sanoit: \'Mikä on Abimelek, että häntä palvelisimme?\' Siinä on nyt se väki, jota halveksit. Mene nyt ja taistele heitä vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Gaal lähti Sikemin miesten etunenässä ja taisteli Abimelekia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Mutta Abimelek ajoi hänet pakoon, ja hän pääsi pakenemaan häntä. Heitä kaatui paljon, aina portin ovelle asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Abimelek jäi Arumaan, mutta Sebul karkotti Gaalin ja hänen veljensä pois Sikemistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Seuraavana päivänä kansa lähti ulos kedolle, ja siitä ilmoitettiin Abimelekille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Hän otti väkensä ja jakoi sen kolmeen joukkoon ja asettui väijyksiin kedolle. Kun hän näki kansan lähtevän kaupungista, hän hyökkäsi heidän kimppuunsa ja surmasi heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Abimelek ja ne joukot, jotka olivat hänen kanssaan, karkasivat näet esiin ja asettuivat kaupungin portin ovelle, samalla kun muut kaksi joukkoa kävivät kaikkien niiden kimppuun, jotka olivat kedolla, ja surmasivat heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Abimelek taisteli kaupunkia vastaan koko sen päivän, valloitti kaupungin ja surmasi kansan, joka siellä oli. Hän hävitti kaupungin ja kylvi suolaa sen paikalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Kun kaikki Sikemin tornin miehet sen kuulivat, menivät he Eel-Beritin temppelin holviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Mutta kun Abimelekille kerrottiin, että kaikki Sikemin tornin miehet olivat kokoontuneet sinne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Abimelek nousi Salmonin vuorelle, hän ja kaikki väki, joka oli hänen kanssaan. Abimelek otti kirveen käteensä ja löi poikki puunoksan, nosti ja pani sen olalleen ja sanoi väelle, joka oli hänen kanssaan: \"Mitä näitte minun tekevän, tehkää tekin kiireesti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Kukin väestäkin löi poikki oksansa, ja he seurasivat Abimelekia, panivat oksat holvin päälle ja sytyttivät holvin heidän päällään palamaan. Niin saivat surmansa myös kaikki Sikemin tornin asukkaat, noin tuhat miestä ja naista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Sitten Abimelek meni Teebekseen, asettui leiriin Teebestä vastaan ja valloitti sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Mutta kaupungin keskellä oli luja torni, ja kaikki miehet ja naiset, kaikki kaupungin asukkaat, pakenivat sinne. He sulkivat oven jälkeensä ja nousivat tornin katolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Abimelek tuli tornin luo ja ryhtyi taisteluun sitä vastaan, ja hän astui tornin ovelle polttaakseen sen tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Mutta eräs nainen heitti jauhinkiven Abimelekin päähän ja murskasi hänen pääkallonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Silloin hän heti huusi palvelijalle, joka kantoi hänen aseitaan, ja sanoi hänelle: \"Paljasta miekkasi ja surmaa minut, ettei minusta sanottaisi: \'Nainen tappoi hänet.\'\" Hänen palvelijansa lävisti hänet, ja hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Kun Israelin miehet näkivät, että Abimelek oli kuollut, he menivät kukin kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Näin Jumala kosti Abimelekille sen pahan, minkä tämä oli tehnyt isäänsä kohtaan surmatessaan seitsemänkymmentä veljeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Jumala käänsi kaiken Sikemin miesten tekemän pahan heidän omaan päähänsä, ja heidät saavutti Jootamin, Jerubbaalin pojan, kirous.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Abimelekin jälkeen nousi Israelia vapauttamaan isaskarilainen Toola, Doodon pojan Puuan poika, joka asui Saamirissa, Efraimin vuoristossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Hän oli tuomarina Israelissa kaksikymmentä kolme vuotta. Sitten hän kuoli, ja hänet haudattiin Saamiriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Hänen jälkeensä nousi gileadilainen Jaair. Hän oli tuomarina Israelissa kaksikymmentä kaksi vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Hänellä oli kolmekymmentä poikaa, jotka ratsastivat kolmellakymmenellä aasilla. Heillä oli kolmekymmentä kaupunkia, joita vielä tänäkin päivänä kutsutaan Jaairin leirikyliksi ja jotka ovat Gileadin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Jaair kuoli, ja hänet haudattiin Kaamoniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Mutta israelilaiset tekivät jälleen sitä, mikä oli pahaa Herran silmissä. He palvelivat baaleja ja astarteja ja Aramin jumalia, Siidonin jumalia, Mooabin jumalia, ammonilaisten jumalia ja filistealaisten jumalia. He hylkäsivät Herran eivätkä palvelleet häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Herran viha syttyi Israelia kohtaan, ja hän myi heidät filistealaisten ja ammonilaisten käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Nämä riistivät ja sortivat israelilaisia sen vuoden ja vielä kahdeksantoista vuotta, kaikkia israelilaisia, jotka asuivat Jordanin tuolla puolen amorilaisten maassa, Gileadissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Ammonilaiset menivät Jordanin yli taistelemaan myös Juudaa, Benjaminia ja Efraimin heimoa vastaan, ja niin Israel joutui suureen ahdinkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Silloin israelilaiset huusivat Herraa sanoen: \"Me olemme tehneet syntiä sinua vastaan, sillä me olemme hylänneet oman Jumalamme ja palvelleet baaleja.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Herra vastasi israelilaisille: \"Eivätkö egyptiläiset, amorilaiset, ammonilaiset, filistealaiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'siidonilaiset, amalekilaiset ja maaonilaiset sortaneet teitä, ja kun huusitte minua avuksi, enkö minä pelastanut teitä heidän käsistään?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Mutta te hylkäsitte minut ja palvelitte muita jumalia. Sen tähden en enää teitä pelasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Menkää ja huutakaa avuksenne niitä jumalia, jotka olette valinneet. Pelastakoot ne teidät ahdinkonne aikana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Israelilaiset sanoivat Herralle: \"Me olemme tehneet syntiä. Tee sinä meille aivan kuten hyväksi näet, kunhan vain tänä päivänä autat meitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'He poistivat vieraat jumalat keskuudestaan ja palvelivat Herraa. Hän ei enää kärsinyt sitä, että Israelia vaivattiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Ammonilaiset kutsuttiin koolle, ja he leiriytyivät Gileadiin. Mutta israelilaiset kokoontuivat ja leiriytyivät Mispaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Silloin kansa, Gileadin ruhtinaat, sanoivat toisilleen: \"Kuka on se mies, joka alkaa taistelun ammonilaisia vastaan? Hän on oleva kaikkien Gileadin asukkaiden päämies.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Gileadilainen Jefta oli väkevä sankari, mutta hän oli porton poika. Jeftan isä oli Gilead.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Mutta Gileadin vaimo oli synnyttänyt hänelle poikia, ja kun tämän vaimon pojat kasvoivat suuriksi, he karkottivat Jeftan ja sanoivat hänelle: \"Et sinä saa perintöosaa isämme talossa, sillä sinä olet toisen naisen poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Jefta lähti pakoon veljiään ja asettui Toobin maahan. Jeftan luo kerääntyi tyhjäntoimittajia, ja he kuljeksivat yhdessä hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Jonkun ajan kuluttua ammonilaiset aloittivat sodan Israelia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Kun nyt ammonilaiset aloittivat sodan Israelia vastaan, niin Gileadin vanhimmat lähtivät noutamaan Jeftaa Toobin maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'He sanoivat Jeftalle: \"Tule ja ryhdy päälliköksemme sotiaksemme ammonilaisia vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Mutta Jefta vastasi Gileadin vanhimmille: \"Ettekö te vihanneet minua ja karkottaneet minut isäni talosta? Miksi nyt, kun teillä on hätä, tulette luokseni?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Gileadin vanhimmat sanoivat Jeftalle: \"Juuri sen tähden olemme nyt kääntyneet puoleesi, ja jos sinä tulet kanssamme ja ryhdyt taistelemaan ammonilaisia vastaan, sinä olet oleva meidän, kaikkien Gileadin asukkaiden, päämies.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Jefta vastasi Gileadin vanhimmille: \"Jos te viette minut takaisin taistelemaan ammonilaisia vastaan, ja Herra antaa heidät valtaani, minä tulen päämieheksenne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Silloin Gileadin vanhimmat sanoivat Jeftalle: \" Herra kuulee välipuheemme. Totisesti teemme kaiken, mitä sanoit.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Niin Jefta lähti Gileadin vanhinten kanssa, ja kansa asetti hänet päämiehekseen ja päällikökseen. Jefta lausui Herran edessä Mispassa kaiken, mitä oli puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Sitten Jefta lähetti ammonilaisten kuninkaan luo sanansaattajia sanomaan: \"Mitä sinulla on kanssani tekemistä, kun tulet minua vastaan sotimaan maatani vastaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Niin ammonilaisten kuningas vastasi Jeftan sanansaattajille: \"Ottihan Israel tullessaan Egyptistä maani Arnonista Jabbokiin ja Jordaniin asti. Anna se nyt hyvällä takaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Jefta lähetti taas sanansaattajia ammonilaisten kuninkaan luo');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'ja käski sanoa hänelle: \"Näin sanoo Jefta: Israel ei ole ottanut Mooabin maata eikä ammonilaisten maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Sillä tullessaan Egyptistä Israel kulki erämaan kautta Kaislamerelle saakka ja tuli Kaadekseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Israel lähetti sanansaattajia Edomin kuninkaan luo sanomaan: \'Salli minun kulkea maasi läpi.\' Mutta Edomin kuningas ei kuullut heitä. He lähettivät sanan myös Mooabin kuninkaalle, mutta hänkään ei suostunut. Niin Israel asettui Kaadekseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Sitten he kulkivat erämaan kautta ja kiersivät Edomin maan ja Mooabin maan ja tulivat itäpuolelle Mooabin maata ja leiriytyivät Arnonin toiselle puolelle. He eivät tulleet Mooabin alueelle, sillä Arnon on Mooabin raja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Silloin Israel lähetti sanansaattajia Siihonin, amorilaisten kuninkaan, Hesbonin kuninkaan, luo, ja Israel käski sanoa hänelle: \'Salli meidän kulkea maasi läpi määräpaikkaamme.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Mutta Siihon ei uskonut Israelia, että olisi sallinut sen kulkea alueensa läpi, vaan Siihon kokosi kaiken joukkonsa, ja he leiriytyivät Jahaaseen, ja hän ryhtyi taisteluun Israelia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Mutta Herra, Israelin Jumala, antoi Siihonin ja kaiken hänen väkensä Israelin käsiin, niin että nämä voittivat heidät. Israel valloitti koko amorilaisten maan, niiden, jotka asuivat siinä maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'He ottivat omakseen koko amorilaisten alueen Arnonista Jabbokiin asti ja erämaasta Jordaniin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Näin siis Herra, Israelin Jumala, karkotti amorilaiset kansansa Israelin tieltä. Mutta nyt sinä ottaisit omaksesi heidän maansa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Eikö ole niin: minkä jumalasi Kemos antaa omaksesi, sen sinä otat omaksesi, ja kenen hyvänsä Herra, meidän Jumalamme, karkottaa tieltämme, sen maan otamme omaksemme?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Vai oletko sinä parempi kuin Baalak, Sipporin poika, Mooabin kuningas? Rakensiko hän riitaa Israelin kanssa, tai ryhtyikö hän sotaan heitä vastaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Israel on nyt asunut Hesbonissa ja sen tytärkaupungeissa, Aroerissa ja sen tytärkaupungeissa ja kaikissa Arnonin varrella olevissa kaupungeissa kolmesataa vuotta. Miksi te ette sen ajan kuluessa ole ottaneet niitä pois?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Minä en ole rikkonut sinua vastaan, mutta sinä teet pahasti minua kohtaan, kun ryhdyt sotimaan minua vastaan. Herra, joka on tuomari, tuomitkoon tänä päivänä israelilaisten ja ammonilaisten välillä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Mutta ammonilaisten kuningas ei ottanut kuullakseen, mitä Jefta lähetti hänelle sanomaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Herran Henki tuli Jeftaan, ja hän kulki Gileadin ja Manassen läpi ja kulki edelleen Gileadin Mispaan, ja Gileadin Mispasta hän lähti ammonilaisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Jefta teki lupauksen Herralle ja sanoi: \"Jos annat ammonilaiset käsiini,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'tulkoon kuka tulkoonkin minua vastaan taloni ovesta, kun voittajana palaan ammonilaisten luota, hän on oleva Herran, ja minä uhraan hänet polttouhriksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Jefta lähti ammonilaisia vastaan, sotimaan heitä vastaan, ja Herra antoi heidät hänen käsiinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Hän tuotti heille hyvin suuren tappion, valloittaen maan Aroerista Minnitiin ja Aabel-Keramimiin asti, kaksikymmentä kaupunkia. Niin täytyi ammonilaisten nöyrtyä israelilaisten edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Kun Jefta sitten tuli kotiinsa Mispaan, katso, hänen tyttärensä tuli ulos häntä vastaan tamburiinia lyöden ja karkeloiden. Hän oli hänen ainoa lapsensa. Tämän lisäksi hänellä ei ollut poikaa eikä tytärtä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Nähdessään hänet hän repäisi vaatteensa ja sanoi: \"Voi, tyttäreni, nyt sinä masennat minut maahan, nyt sinä syökset minut onnettomuuteen! Sillä minä avasin suuni Herralle enkä voi sanaani peruuttaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Hän vastasi hänelle: \"Isäni, jos sinä avasit suusi Herralle, tee minulle, niin kuin suusi on puhunut, koska Herra on antanut sinun kostaa vihollisillesi, ammonilaisille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Hän sanoi isälleen: \"Myönnettäköön minulle kuitenkin tämä: jätä minut vapauteeni kahdeksi kuukaudeksi, että minä yhdessä ystävättärieni kanssa menen vuorille itkemään neitsyyttäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Niin hän sanoi: \"Mene!\" ja päästi hänet menemään kahdeksi kuukaudeksi. Hän meni ystävättärineen ja itki neitsyyttään vuorilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Mutta kahden kuukauden kuluttua hän palasi isänsä luo, ja tämä pani hänessä täytäntöön lupauksensa, jonka oli tehnyt. Eikä hän miehestä tietänyt. Tuli tavaksi Israelissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'että Israelin tyttäret joka vuosi menivät lauluin ylistämään gileadilaisen Jeftan tytärtä – neljän päivän ajaksi joka vuosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Efraimin miehet kutsuttiin koolle, ja he lähtivät pohjoista kohti ja sanoivat Jeftalle: \"Miksi lähdit sotimaan ammonilaisia vastaan kutsumatta meitä tulemaan kanssasi? Poltamme tulella talosi pääsi päältä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Jefta vastasi heille: \"Minulla ja kansallani oli kova taistelu ammonilaisten kanssa. Silloin kutsuin teitä, mutta te ette tulleet auttamaan minua heidän käsistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Kun näin, ettette te tulleet auttamaan minua, panin henkeni kämmenelleni ja lähdin ammonilaisia vastaan, ja Herra antoi heidät käsiini. Miksi te nyt olette lähteneet minua vastaan, sotimaan minua vastaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Jefta kokosi kaikki Gileadin miehet ja ryhtyi taisteluun Efraimia vastaan. Gileadin miehet voittivat efraimilaiset, jotka olivat sanoneet: \"Te olette karkureita Efraimista. Gilead on Efraimin ja Manassen keskuudessa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Gileadilaiset valtasivat efraimilaisten tieltä Jordanin kahluupaikat. Kun sitten Efraimin pakolaiset sanoivat: \"Antakaa minun mennä yli\", Gileadin miehet kysyivät heiltä jokaiselta: \"Oletko efraimilainen?\" Jos hän vastasi: \"En\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'niin he sanoivat hänelle: \"Sano \'šibbolet.\'\" Jos hän sanoi \"sibbolet\", kun ei osannut ääntää oikein, ottivat he hänet kiinni ja tappoivat Jordanin kahluupaikoilla. Niin kaatui silloin Efraimista neljäkymmentä kaksi tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Jefta oli tuomarina Israelissa kuusi vuotta. Sitten gileadilainen Jefta kuoli, ja hänet haudattiin erääseen Gileadin kaupunkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Hänen jälkeensä oli Ibsan, Beetlehemistä, tuomarina Israelissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Hänellä oli kolmekymmentä poikaa, ja hän naitti kolmekymmentä tytärtään muualle ja toi muualta kolmekymmentä tyttöä pojilleen vaimoiksi. Hän oli tuomarina Israelissa seitsemän vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Sitten Ibsan kuoli, ja hänet haudattiin Beetlehemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Hänen jälkeensä oli sebulonilainen Eelon tuomarina Israelissa. Hän oli tuomarina Israelissa kymmenen vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Sitten sebulonilainen Eelon kuoli, ja hänet haudattiin Aijaloniin, Sebulonin maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Hänen jälkeensä oli piratonilainen Abdon, Hillelin poika, tuomarina Israelissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Hänellä oli neljäkymmentä poikaa ja kolmekymmentä pojanpoikaa, jotka ratsastivat seitsemälläkymmenellä aasilla. Hän oli tuomarina Israelissa kahdeksan vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Sitten piratonilainen Abdon, Hillelin poika, kuoli, ja hänet haudattiin Piratoniin, Efraimin maahan, amalekilaisten vuoristoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Kun israelilaiset yhä tekivät sitä, mikä oli pahaa Herran silmissä, Herra antoi heidät filistealaisten käsiin neljäksikymmeneksi vuodeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Sorassa oli mies, Daanin sukukuntaa, nimeltä Maanoah. Hänen vaimonsa oli hedelmätön eikä ollut synnyttänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Silloin Herran Enkeli ilmestyi vaimolle ja sanoi hänelle: \"Katso, sinä olet hedelmätön etkä ole synnyttänyt, mutta sinä tulet raskaaksi ja synnytät pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Varo siis, ettet juo viiniä ja väkijuomaa etkä syö mitään saastaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Sillä katso, sinä tulet raskaaksi ja synnytät pojan. Partaveitsi älköön koskettako hänen päätään, sillä poika on oleva Jumalan nasiiri äitinsä kohdusta asti, ja hän on aloittava Israelin vapauttamisen filistealaisten käsistä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Vaimo lähti ja sanoi miehelleen näin: \"Jumalan mies tuli luokseni. Hän oli näöltään kuin Jumalan Enkeli, hyvin pelottava. En kysynyt häneltä, mistä hän oli, eikä hän ilmaissut minulle nimeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Hän sanoi minulle: \'Katso, sinä tulet raskaaksi ja synnytät pojan. Älä siis juo viiniä ja väkijuomaa äläkä syö mitään saastaista, sillä poika on oleva Jumalan nasiiri äitinsä kohdusta aina kuolinpäiväänsä asti.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Silloin Maanoah rukoili Herraa ja sanoi: \"Oi Herra, salli Jumalan miehen, jonka lähetit, vielä tulla luoksemme opettamaan meille, mitä meidän on tehtävä pojalle, joka on syntyvä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Jumala kuuli Maanoahin rukouksen, ja Jumalan Enkeli tuli jälleen vaimon luo, kun tämä istui kedolla. Mutta Maanoah, hänen miehensä, ei ollut hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Vaimo juoksi nopeasti ilmoittamaan miehelleen ja sanoi hänelle: \"Katso, sama mies, joka äsken kävi luonani, ilmestyi minulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Niin Maanoah nousi ja seurasi vaimoaan. Kun hän tuli miehen luo, hän sanoi tälle: \"Sinäkö olet se mies, joka puhuttelit tätä vaimoa?\" Hän vastasi: \"Minä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Silloin Maanoah sanoi: \"Kun sanasi käy toteen, miten sitten on meneteltävä pojan kanssa ja mitä hänelle on tehtävä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Herran Enkeli sanoi Maanoahille: \"Varokoon vaimo kaikkea, mistä minä olen hänelle puhunut:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'älköön syökö mitään, mikä viiniköynnöksestä tulee, viiniä ja väkijuomaa hän älköön juoko älköönkä syökö mitään saastaista. Noudattakoon kaikkea, mitä minä olen käskenyt hänen noudattaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Maanoah sanoi Herran Enkelille: \"Salli meidän pidätellä sinua valmistaaksemme sinulle kilin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Mutta Herran Enkeli vastasi Maanoahille: \"Vaikka pidättelisitkin minua, en kuitenkaan söisi ruokaasi. Mutta jos tahdot valmistaa polttouhrin, uhraa se Herralle.\" Sillä Maanoah ei tiennyt häntä Herran Enkeliksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Maanoah sanoi Herran Enkelille: \"Mikä on nimesi kunnioittaaksemme sinua, kun sinun sanasi käy toteen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Herran Enkeli vastasi hänelle: \"Minkä tähden kysyt minun nimeäni? Se on Ihmeellinen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Maanoah otti kilin ja ruokauhrin ja uhrasi sen kalliolla Herralle. Herra teki ihmeen Maanoahin ja hänen vaimonsa nähden:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'liekin kohotessa alttarilta taivasta kohti kohosi Herran Enkeli alttarin liekissä ylös Maanoahin ja hänen vaimonsa nähden, ja he heittäytyivät kasvoilleen maahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'eikä Herran Enkeli enää ilmestynyt Maanoahille ja hänen vaimolleen. Nyt Maanoah tiesi hänet Herran Enkeliksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Niin Maanoah sanoi vaimolleen: \"Olemme kuoleman omat, sillä olemme nähneet Jumalan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Mutta hänen vaimonsa vastasi hänelle: \"Jos Herra tahtoisi surmata meidät, hän ei olisi ottanut meiltä vastaan polttouhria ja ruokauhria eikä antanut meidän nähdä tätä kaikkea eikä antanut meidän juuri nyt tätä kuulla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Sen jälkeen vaimo synnytti pojan ja antoi hänelle nimen Simson, ja poika kasvoi, ja Herra siunasi häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Herran Henki alkoi hänessä vaikuttaa Daanin leirissä Soran ja Estaolin välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Simson meni alas Timnaan ja näki Timnassa naisen, filistealaisten tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Hän tuli sieltä ja kertoi sen isälleen ja äidilleen ja sanoi: \"Minä näin Timnassa naisen, filistealaisten tyttäriä. Ottakaa hänet nyt minulle vaimoksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Hänen isänsä ja äitinsä sanoivat hänelle: \"Eikö veljiesi tyttärien joukossa ja koko kansassani ole yhtään naista, kun aiot mennä ottamaan vaimon ympärileikkaamattomien filistealaisten joukosta?\" Mutta Simson sanoi isälleen: \"Ota hänet minulle, sillä hän on mieluinen silmissäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Mutta hänen isänsä ja äitinsä eivät tienneet, että se tuli Herralta, sillä hän etsi tilaisuutta filistealaisia vastaan. Filistealaiset näet hallitsivat siihen aikaan Israelia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Simson meni isänsä ja äitinsä kanssa alas Timnaan. Mutta kun he saapuivat Timnan viinitarhoille, katso, nuori leijona tuli ärjyen häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Silloin Herran Henki tuli häneen, niin että hän repäisi sen, niin kuin olisi reväissyt kilin, paljain käsin. Eikä hän ilmoittanut isälleen eikä äidilleen, mitä oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Hän meni sinne ja puhutteli naista, ja tämä oli mieluinen Simsonin silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Kun hän jonkin ajan kuluttua palasi sinne ottaakseen hänet, hän poikkesi katsomaan leijonan raatoa, ja katso, leijonan ruumiissa oli mehiläisparvi ja hunajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Hän kaapi hunajan kouriinsa ja kulki edelleen ja söi sitä. Hän tuli isänsä ja äitinsä luo ja antoi heille, ja he söivät. Mutta hän ei sanonut heille, että oli kaapinut hunajan leijonan ruumiista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Hänen isänsä meni naisen luo, ja Simson laittoi siellä pidot, sillä niin oli nuorten miesten tapa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Mutta kun he näkivät hänet, valitsivat he kolmekymmentä sulhaspoikaa olemaan hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Simson sanoi heille: \"Minä panen teille arvoituksen. Jos selitätte sen minulle seitsemän pitopäivän kuluessa ja arvaatte oikein, annan teille kolmekymmentä pellavapaitaa ja kolmekymmentä juhlapukua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Mutta ellette voi sitä minulle selittää, te annatte minulle kolmekymmentä pellavapaitaa ja kolmekymmentä juhlapukua.\" He sanoivat hänelle: \"Lausu arvoituksesi, että saamme sen kuulla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Hän sanoi heille: \"Lähti syötävä syömäristä, lähti väkevästä makea.\" Mutta he eivät voineet kolmen päivän kuluessa selittää arvoitusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Seitsemäntenä päivänä he sanoivat Simsonin vaimolle: \"Viekoittele miehesi selittämään meille arvoitus, muuten poltamme sinut ja sinun isäsi talon tulella. Oletteko kutsuneet meidät tänne köyhdyttääksenne meitä, vai kuinka?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Simsonin vaimo ahdisti häntä itkullaan ja sanoi: \"Sinähän vihaat minua etkä rakasta. Sinä olet pannut arvoituksen kansalaisilleni etkä selitä sitä minulle.\" Mutta hän vastasi hänelle: \"En ole selittänyt sitä edes isälleni enkä äidilleni, sinulleko sen selittäisin!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Hän ahdisti häntä itkullaan ne seitsemän päivää, jotka heidän pitonsa kestivät. Mutta seitsemäntenä päivänä Simson selitti hänelle, koska vaimo häntä ahdisti. Sen jälkeen vaimo selitti arvoituksen kansalaisilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Kaupungin miehet sanoivat hänelle seitsemäntenä päivänä, ennen kuin aurinko laski: \"Mikä on makeampaa kuin hunaja, ja mikä leijonaa väkevämpi?\" Hän vastasi heille: \"Ellette olisi kyntäneet vasikallani, ette olisi arvoitustani arvanneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Silloin Herran Henki tuli häneen, ja hän meni Askeloniin, löi siellä kuoliaaksi kolmekymmentä miestä, otti heiltä vaatteet ja antoi juhlapuvut arvoituksen selittäjille. Hänen vihansa syttyi, ja hän meni isänsä kotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Mutta Simsonin vaimo tuli sille sulhaspojista, joka oli ollut yljän ystävänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Jonkin ajan kuluttua, vehnänleikkuuaikaan, tuli Simson katsomaan vaimoaan tuomisinaan kili, ja sanoi: \"Minä menen vaimoni luo sisähuoneeseen.\" Mutta tämän isä ei sallinut hänen mennä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'vaan sanoi: \"Minä tosiaankin luulin, että olit ruvennut vihaamaan häntä, ja annoin hänet sulhaspojallesi. Mutta onhan hänen nuorempi sisarensa häntä kauniimpi, saat hänet toisen sijaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Mutta Simson vastasi heille: \"Nyt minä en tule syynalaiseksi filistealaisista, vaikka teenkin heille pahaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Simson meni ja pyydysti kolmesataa kettua. Hän otti tulisoihtuja, sitoi aina kaksi häntää yhteen ja asetti tulisoihdun kunkin häntäparin väliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Hän sytytti tulisoihdut ja päästi ketut menemään filistealaisten viljapeltoihin. Hän sytytti palamaan sekä kuhilaat että kasvavan viljan, viinitarhat ja öljypuut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Filistealaiset kysyivät: \"Kuka tämän on tehnyt?\" Vastattiin: \"Simson, timnalaisen vävy, koska tämä otti hänen vaimonsa ja antoi sen hänen sulhaspojalleen.\" Filistealaiset menivät ja polttivat sekä vaimon että hänen isänsä tulessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Mutta Simson sanoi heille: \"Koska te näin teitte, totisesti lakkaan vasta sitten, kun olen kostanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Hän piiskasi heitä lanteisiin ja jalkoihin pahasti haavoittaen heitä. Hän meni ja asettui asumaan Eetamin kallioluolaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Filistealaiset lähtivät liikkeelle, leiriytyivät Juudaan ja levittäytyivät Lehin tienoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Juudan miehet kysyivät: \"Miksi olette tulleet meitä vastaan?\" He vastasivat: \"Me olemme tulleet sitomaan Simsonin tehdäksemme hänelle, niin kuin hän teki meille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Niin kolmetuhatta miestä Juudasta meni Eetamin kallioluolalle, ja he sanoivat Simsonille: \"Etkö tiedä, että filistealaiset hallitsevat meitä? Mitä oletkaan meille tehnyt!\" Hän vastasi heille: \"Niin kuin he tekivät minulle, niin minäkin tein heille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'He sanoivat hänelle: \"Tulimme sitomaan sinut antaaksemme sinut filistealaisten käsiin.\" Mutta Simson sanoi heille: \"Vannokaa minulle, ettette itse lyö minua kuoliaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'He vastasivat hänelle sanoen: \"Emme lyö. Me vain sidomme sinut ja annamme sinut heidän käsiinsä, mutta emme sinua surmaa.\" He sitoivat hänet kahdella uudella köydellä ja veivät hänet pois kalliolta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Kun hän saapui Lehiin, filistealaiset riensivät riemuhuudoin häntä vastaan. Silloin Herran Henki tuli häneen, ja samalla köydet hänen käsivarsissaan olivat kuin tulen polttamat pellavalangat, ja hänen siteensä sulivat pois hänen käsistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Hän huomasi tuoreen aasinleukaluun, ojensi kätensä, otti sen ja löi sillä kuoliaaksi tuhat miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Simson sanoi: \"Aasinleukaluulla minä löin heitä läjään, löin kahteen, aasinleukaluulla löin heitä tuhat miestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Sen sanottuaan hän heitti leukaluun kädestään. Sen paikan nimeksi tuli Raamat-Lehi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Mutta kun hänellä oli kova jano, hän huusi Herraa ja sanoi: \"Sinä annoit palvelijasi käden kautta tämän suuren voiton, mutta nyt kuolen janoon ja joudun ympärileikkaamattomien käsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Jumala avasi syvänteen Lehiin, ja siitä vuoti vettä. Hän joi, ja hänen henkensä elpyi, ja hän virkistyi. Siitä lähde sai nimekseen Een-Hakkore. Se on vielä tänäkin päivänä Lehissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Hän oli filistealaisten aikana tuomarina Israelissa kaksikymmentä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Niin Simson meni Gassaan ja näki siellä porton ja meni tämän luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Kun gassalaisille kerrottiin, että Simson oli tullut sinne, he piirittivät hänet ja väijyivät häntä koko yön kaupungin portilla. He olivat hiljaa koko yön ajatellen: \"Kun aamu valkenee, surmaamme hänet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Simson makasi siellä puoliyöhön asti. Mutta keskiyöllä hän nousi, tarttui kaupungin portin oviin ja molempiin pihtipieliin, nosti ne salpoineen paikaltaan, asetti hartioilleen ja vei ne sen vuoren laelle, joka on vastapäätä Hebronia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Sen jälkeen hän rakastui erääseen Soorekin laaksossa asuvaan naiseen, jonka nimi oli Delila.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Filistealaisten ruhtinaat tulivat naisen luo ja sanoivat hänelle: \"Viettele hänet ja ota selko, missä hänen suuri voimansa on ja miten voisimme voittaa hänet, että saisimme hänet sidotuksi ja masennetuksi, niin annamme sinulle kukin tuhat ja sata hopeasekeliä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Silloin Delila sanoi Simsonille: \"Ilmaise minulle, missä suuri voimasi on ja miten sinut voidaan sitoa ja lannistaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Simson vastasi hänelle: \"Jos minut sidotaan seitsemällä tuoreella jänteellä, jotka eivät ole kuivuneet, tulen heikoksi ja olen kuin muutkin ihmiset.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Niin filistealaisten ruhtinaat toivat naiselle seitsemän tuoretta jännettä, jotka eivät olleet kuivuneet, ja hän sitoi hänet niillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Mutta sisähuoneessa hänellä istui väijyjiä. Niin hän sanoi hänelle: \"Filistealaiset ovat kimpussasi, Simson!\" Silloin tämä katkaisi jänteet, niin kuin katkeaa tulen kärventämä rohdinlanka. Ei siis päästy perille hänen voimastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Delila sanoi Simsonille: \"Katso, sinä olet pettänyt minut ja valehdellut minulle. Ilmaise nyt minulle, miten sinut voidaan sitoa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Hän sanoi hänelle: \"Jos minut sidotaan uusilla köysillä, joilla ei ole tehty työtä, tulen heikoksi ja olen kuin muutkin ihmiset.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Delila otti uudet köydet, sitoi hänet niillä ja sanoi hänelle: \"Filistealaiset ovat kimpussasi, Simson!\" Sisähuoneessa istui väijyjiä. Mutta hän katkaisi ne käsivarsistaan kuin langan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Niin Delila sanoi Simsonille: \"Sinä olet tähän asti minua pettänyt ja valehdellut minulle. Ilmaise minulle, miten sinut voidaan sitoa.\" Hän vastasi hänelle: \"Jos kudot päässäni olevat seitsemän palmikkoa kankaan loimiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Niin Delila löi ne kiinni lujaan vaarnalla. Sitten hän sanoi hänelle: \"Filistealaiset ovat kimpussasi, Simson!\" Kun hän heräsi unestaan, hän repäisi irti vaarnan ja loimet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Niin nainen sanoi hänelle: \"Kuinka saatat sanoa: \'Rakastan sinua\', vaikka sydämesi ei ole kanssani? Jo kolme kertaa olet pettänyt minut etkä ole ilmaissut minulle, missä suuri voimasi on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Kun hän joka päivä ahdisti häntä sanoillaan ja vaivasi häntä, hän tuskastui kuollakseen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'ja paljasti hänelle koko sydämensä ja sanoi hänelle: \"Ei ole partaveitsi päähäni koskenut, sillä minä olen Jumalan nasiiri äitini kohdusta asti. Jos minun hiukseni ajetaan, voimani lähtee minusta pois, ja tulen heikoksi ja olen kuin kaikki muutkin ihmiset.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Kun Delila huomasi, että hän oli paljastanut hänelle koko sydämensä, hän lähetti kutsumaan filistealaisten ruhtinaat sanoen: \"Nyt tulkaa, sillä hän on paljastanut minulle koko sydämensä.\" Niin filistealaisten ruhtinaat tulivat hänen luokseen tuoden mukanaan rahat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Sitten hän nukutti hänet polvilleen ja kutsui miehen, joka leikkasi hänen päänsä seitsemän palmikkoa. Hän alkoi saada hänet lannistetuksi, ja hänen voimansa poistui hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Delila sanoi: \"Filistealaiset ovat kimpussasi, Simson!\" Kun hän heräsi unestaan, hän ajatteli: \"Kyllä minä selviydyn niin kuin aina ennenkin ja ravistan itseni vapaaksi.\" Eikä hän tiennyt, että Herra oli poistunut hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Filistealaiset ottivat hänet kiinni ja puhkaisivat hänen silmänsä. He veivät hänet Gassaan ja sitoivat hänet vaskikahleisiin, ja hänen täytyi jauhaa vankilassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Mutta hiukset rupesivat jälleen kasvamaan hänen päähänsä sen jälkeen, kun ne olivat ajetut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Filistealaisten ruhtinaat kokoontuivat uhraamaan suurta uhria jumalalleen Daagonille ja iloa pitämään, sillä he sanoivat: \"Jumalamme on antanut vihollisemme Simsonin käsiimme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Kun kansa näki hänet, he ylistivät jumalaansa, sillä he sanoivat: \"Jumalamme on antanut käsiimme vihollisemme, maamme hävittäjän, sen, joka surmasi meistä niin monta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Kun heidän sydämensä olivat tulleet iloisiksi, he sanoivat: \"Noutakaa Simson huvittamaan meitä.\" Simson noudettiin vankilasta huvittamaan heitä. He asettivat hänet seisomaan pylväiden väliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Simson sanoi palvelijalle, joka piti kiinni hänen kädestään: \"Päästä minut tunnustelemaan pylväitä, joiden varassa rakennus on, nojatakseni niihin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Mutta huone oli täynnä miehiä ja naisia, myös kaikki filistealaisten ruhtinaat olivat siellä, ja katolla oli noin kolmetuhatta miestä ja naista katselemassa, kuinka Simson heitä huvitti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Simson huusi Herraa ja sanoi: \"Herra, Herra, muista minua ja vahvista minua ainoastaan tämä kerta, oi Jumala, että saisin filistealaisille yhdellä kertaa kostetuksi molemmat silmäni!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Simson kiersi käsivartensa molempien keskipylväiden ympäri, joiden varassa rakennus oli, toisen ympäri oikean ja toisen ympäri vasemman käsivartensa, ja painautui niitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Simson sanoi: \"Menköön oma henkeni yhdessä filistealaisten kanssa!\" Sitten hän taivuttautui eteenpäin niin rajusti, että rakennus luhistui ruhtinaiden ja kaiken siinä olevan kansan päälle. Kuolleita, jotka hän surmasi kuollessaan, oli enemmän kuin niitä, jotka hän oli surmannut eläessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Hänen veljensä ja koko hänen isänsä perhe menivät, ottivat hänet, veivät ja hautasivat hänet Soran ja Estaolin välille, hänen isänsä Maanoahin hautaan. Hän oli ollut tuomarina Israelissa kaksikymmentä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Efraimin vuoristossa oli mies, nimeltä Miika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Hän sanoi äidilleen: \"Ne tuhatsata hopeasekeliä, jotka sinulta otettiin ja joiden tähden sinä lausuit vannotuksen minunkin kuulteni, katso, rahat ovat minulla. Minä ne otin.\" Silloin hänen äitinsä sanoi: \" Herra siunatkoon sinua, poikani!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Hän palautti äidilleen tuhatsata hopeasekeliä. Mutta hänen äitinsä sanoi: \"Minä pyhitän nämä rahat Herralle ja luovutan ne pojalleni veistetyn ja valetun jumalankuvan teettämistä varten. Nyt annan ne sinulle takaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Mutta hän antoi rahat takaisin äidilleen. Hänen äitinsä otti kaksisataa hopeasekeliä ja antoi ne kultasepälle, joka teki niistä veistetyn ja valetun jumalankuvan. Se oli sitten Miikan talossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Miehellä, Miikalla, oli jumalanhuone, ja hän teetti papinpuvun ja kotijumalien kuvia ja asetti yhden pojistaan itselleen papiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'Siihen aikaan ei ollut kuningasta Israelissa, ja jokainen teki sitä, mikä hänen omasta mielestään oli oikein.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Juudan Beetlehemissä oli nuori mies, Juudan sukukuntaa. Hän oli leeviläinen ja asui siellä muukalaisena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Mies lähti siitä kaupungista, Juudan Beetlehemistä, asuakseen muukalaisena, missä vain sopisi, ja vaeltaessaan tietään hän tuli Efraimin vuoristoon, Miikan talolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Miika kysyi häneltä: \"Mistä tulet?\" Hän vastasi: \"Minä olen leeviläinen Juudan Beetlehemistä ja vaellan asuakseni muukalaisena, missä vain sopii.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Miika sanoi hänelle: \"Asetu luokseni ja tule isäkseni ja papikseni, niin minä annan sinulle vuosittain kymmenen hopeasekeliä, vaatetuksen ja elatuksesi.\" Leeviläinen tuli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Leeviläinen suostui asettumaan miehen luo, ja tämä piti nuorta miestä kuin omaa poikaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Miika asetti leeviläisen virkaan, ja nuoresta miehestä tuli hänen pappinsa, ja hän jäi Miikan taloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Miika sanoi: \"Nyt tiedän, että Herra tekee minulle hyvää, sillä minulla on pappina leeviläinen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'Siihen aikaan ei ollut kuningasta Israelissa, ja siihen aikaan daanilaisten sukukunta etsi itselleen perintöosaa asuttavakseen, sillä siihen päivään asti se ei ollut saanut perintöosaa Israelin sukukuntien keskuudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Daanilaiset lähettivät sukukuntansa keskuudesta viisi miestä, sotakuntoisia miehiä Sorasta ja Estaolista, vakoilemaan maata ja tutkimaan sitä. He sanoivat heille: \"Menkää tutkimaan maata.\" Nämä tulivat Efraimin vuoristoon, Miikan talolle, ja yöpyivät sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Ollessaan Miikan talon luona he tunsivat nuoren miehen hänen äänestään leeviläiseksi. He poikkesivat sinne ja kysyivät häneltä: \"Kuka on tuonut sinut tänne? Mitä sinä täällä toimitat, ja mitä sinulla on täällä tekemistä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Hän vastasi heille: \"Niin ja niin teki Miika minulle ja palkkasi minut papikseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'He sanoivat hänelle: \"Kysy Jumalalta, että saisimme tietää, onnistuuko matka, jolla olemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Pappi vastasi heille: \"Menkää rauhassa. Matka, jolla olette, tapahtuu Herran edessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Nuo viisi miestä jatkoivat matkaansa ja tulivat Laikseen ja näkivät, että sikäläinen kansa asui huoleti siidonilaisten tavoin, rauhassa ja turvassa, eikä kukaan tehnyt vahinkoa tässä maassa rikkauksia anastamalla. He olivat myös etäällä siidonilaisista eivätkä olleet tekemisissä muiden ihmisten kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'He tulivat veljiensä luo Soraan ja Estaoliin, ja heidän veljensä kysyivät heiltä: \"Mitä kuuluu?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'He sanoivat: \"Nouskaa, lähtekäämme heitä vastaan. Sillä olemme katselleet maata, ja katso, se on oikein hyvä. Tekö jäisitte toimettomiksi! Älkää vitkastelko, lähtekää liikkeelle, menkää sinne ja ottakaa maa omaksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Kun tulette sinne, tulette huolettomana elävän kansan luo, ja maassa on tilaa joka suuntaan. Niin, Jumala antaa teidän käsiinne paikan, jossa ei ole puutetta mistään, mitä maan päällä on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Niin sieltä, daanilaisten sukukunnasta, Sorasta ja Estaolista, lähti liikkeelle kuusisataa sota-asein varustettua miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'He nousivat Juudan Kirjat-Jearimiin ja leiriytyivät sinne. Sen tähden paikkaa kutsutaan vielä tänäkin päivänä \"Daanin leiriksi\". Se on Kirjat-Jearimin takana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Sieltä he kulkivat Efraimin vuoristoon ja tulivat Miikan talolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Nuo viisi miestä, jotka olivat käyneet vakoilemassa Laiksen maata, rupesivat puhumaan ja sanoivat veljilleen: \"Tiedättekö, että noissa huoneissa on kasukka ja kotijumalia sekä veistetty ja valettu jumalankuva? Miettikää siis, mitä teidän on tehtävä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'He poikkesivat sinne ja tulivat nuoren leeviläisen miehen asunnolle Miikan taloon ja tervehtivät häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Ne kuusisataa sota-asein varustettua daanilaista asettuivat portin oven eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Mutta nuo viisi miestä, jotka olivat käyneet vakoilemassa maata, nousivat taloon, menivät sisään ja ottivat veistetyn jumalankuvan, kasukan, kotijumalat ja valetun jumalankuvan, kun taas pappi ja ne kuusisataa sota-asein varustettua miestä seisoivat portin oven edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Kun he menivät Miikan taloon ja ottivat veistetyn jumalankuvan, kasukan, kotijumalat ja valetun jumalankuvan, pappi kysyi heiltä: \"Mitä te teette?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'He vastasivat hänelle: \"Vaikene, pidä suusi kiinni ja lähde kanssamme ja tule isäksemme ja papiksemme. Onko sinun parempi olla pappina yhden miehen talossa kuin Israelin heimon ja sukukunnan pappina?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Silloin pappi tuli hyville mielin ja otti kasukan, kotijumalat ja veistetyn jumalankuvan ja meni väkijoukkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'He kääntyivät jatkamaan matkaansa ja panivat vaimot ja lapset sekä karjan ja kuormaston kulkemaan edellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'He olivat ehtineet vähän matkaa Miikan talosta, kun Miikan talon lähitalojen miehet kutsuttiin koolle, ja he pääsivät daanilaisten kintereille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'He huusivat daanilaisille. Nämä kääntyivät ja kysyivät Miikalta: \"Mikä sinun on, kun väkesi on noin kutsuttu koolle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Hän vastasi: \"Te olette vieneet jumalani, jotka olen teettänyt, ja papin, ja menette matkoihinne. Mitä minulla on enää jäljellä? Kuinka te vielä kysytte minulta: \'Mikä sinun on\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Mutta daanilaiset sanoivat hänelle: \"Lakkaa huutamasta meille, muuten miehet ärtyvät ja käyvät kimppuunne, ja menetätte henkenne, sekä sinä että perheesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Daanilaiset jatkoivat matkaansa, ja kun Miika näki, että he olivat häntä voimakkaammat, hän kääntyi ja palasi kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Otettuaan siis sen, minkä Miika oli teettänyt, sekä hänen pappinsa, he tulivat Laikseen rauhassa ja huolettomina elävän kansan kimppuun ja surmasivat heidät miekan terällä ja polttivat kaupungin tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Eikä kukaan tullut avuksi, sillä se oli kaukana Siidonista eivätkä he olleet tekemisissä muitten ihmisten kanssa. Se oli Beet-Rehobin tasangolla. Daanilaiset rakensivat kaupungin uudestaan ja asettuivat siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'He antoivat kaupungille nimen Daan, isänsä Daanin nimen mukaan, hänen, joka oli Israelille syntynyt. Mutta ennen kaupungin nimi oli ollut Lais.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Sitten daanilaiset pystyttivät itselleen tuon veistetyn jumalankuvan. Joonatan, Manassen pojan Geersomin poika, ja hänen poikansa olivat daanilaisten sukukunnan pappeina, kunnes maan väestö vietiin karkotukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'He pystyttivät itselleen sen veistetyn jumalankuvan, jonka Miika oli teettänyt, ja se oli siellä koko sen ajan, minkä Jumalan huone oli Siilossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Siihen aikaan, kun Israelissa ei ollut kuningasta, eräs leeviläinen mies asui muukalaisena Efraimin vuoriston perukoilla ja otti itselleen sivuvaimon Juudan Beetlehemistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Mutta hänen sivuvaimonsa oli hänelle uskoton ja meni hänen luotaan isänsä kotiin Juudan Beetlehemiin, ja hän oli siellä jonkin aikaa, neljä kuukautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Sitten hänen miehensä nousi ja lähti hänen jälkeensä puhuakseen hänelle mieliksi ja palauttaakseen hänet luokseen. Hänellä oli mukanaan palvelija ja aasipari. Nainen vei hänet isänsä kotiin, ja kun naisen isä näki hänet, hän riensi iloisena häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Hänen appensa, naisen isä, pidätteli häntä, niin että hän viipyi hänen luonaan kolme päivää. He söivät ja joivat ja olivat siellä yötä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Neljäntenä päivänä hän varhain aamulla nousi lähteäkseen, mutta naisen isä sanoi vävylleen: \"Vahvista itseäsi leipäpalalla. Sitten saatte lähteä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'He istuivat, söivät ja joivat molemmat yhdessä. Sitten naisen isä sanoi miehelle: \"Suostu jäämään yöksi, ja olkoon sydämesi iloinen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Mies nousi lähteäkseen. Silloin hänen appensa pyysi häntä pyytämällä, ja hän jäi sinne vielä yöksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Viidentenä päivänä hän varhain aamulla nousi lähteäkseen, mutta naisen isä sanoi hänelle: \"Vahvista itseäsi, ja viipykää iltapäivään asti.\" He söivät toistensa kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Mies nousi lähteäkseen sivuvaimonsa ja palvelijansa kanssa, mutta hänen appensa, naisen isä, sanoi hänelle: \"Katso, päivä kallistuu iltaan, jääkää yöksi, päivä on menemässä mailleen, jää tänne yöksi, ja olkoon sydämesi iloinen. Nouskaa huomenna varhain matkallenne, ja lähde sitten majallesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Mutta mies ei tahtonut jäädä yöksi, vaan nousi ja lähti ja tuli Jebuksen, se on Jerusalemin, kohdalle, mukanaan satuloitu aasipari ja sivuvaimonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Kun he olivat Jebuksen luona ja päivä oli kohta laskemassa, palvelija sanoi isännälleen: \"Tule, poiketkaamme tuohon jebusilaisten kaupunkiin ja yöpykäämme siellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Mutta hänen isäntänsä vastasi hänelle: \"Emme poikkea vieraiden kaupunkiin, jotka eivät ole israelilaisia, vaan menemme edelleen Gibeaan asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Hän sanoi palvelijalleen: \"Tule, pyrkikäämme toiseen paikkaan, yöpykäämme Gibeassa tai Raamassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'He jatkoivat matkaansa, ja aurinko laski heiltä lähellä Gibeaa, joka on Benjaminissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'He poikkesivat Gibeaan yöpyäkseen siellä. Hän tuli sinne ja istuutui kaupungin torille, mutta kukaan ei ottanut heitä yöksi huoneeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Mutta katso, illalla tuli vanha mies työstään kedolta. Hän oli Efraimin vuoristosta ja asui muukalaisena Gibeassa. Mutta paikkakunnan miehet olivat benjaminilaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Kun hän nosti silmänsä, hän näki matkamiehen kaupungin torilla. Silloin vanha mies sanoi: \"Minne olet matkalla ja mistä tulet?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Hän vastasi hänelle sanoen: \"Olemme matkalla Juudan Beetlehemistä Efraimin vuoriston perukoille. Sieltä olen kotoisin ja olen käynyt Juudan Beetlehemissä asti. Olen matkalla Herran huoneeseen, mutta kukaan ei ota minua sisälle taloonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Meillä on sekä olkia että muuta rehua aaseillemme, niin myös leipää ja viiniä minulle itselleni ja palvelijattarellesi ja nuorelle miehelle, joka on palvelijasi kanssa, niin ettei meiltä puutu mitään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Vanha mies sanoi: \"Rauha sinulle! Minun asiani on, jos sinulta jotakin puuttuisi. Älä vain jää yöksi tähän torille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Sitten hän vei hänet taloonsa ja teki aaseille appeen. He pesivät jalkansa ja söivät ja joivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Kun he olivat ilahduttamassa sydäntään, katso, kaupungin miehet, kelvottomat miehet, piirittivät talon, kolkuttivat ovelle ja sanoivat vanhalle miehelle, talon isännälle, näin: \"Tuo tänne se mies, joka tuli taloosi, yhtyäksemme häneen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Mutta mies, talon isäntä, meni ulos heidän luokseen ja sanoi heille: \"Älkää, veljeni, älkää tehkö niin pahoin! Kun kerran tämä mies on tullut minun talooni, älkää tehkö sellaista häpeällistä tekoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Katso, täällä on tyttäreni, joka on neitsyt, ja tämän miehen sivuvaimo. Minä tuon heidät tänne. Tehkää heille väkivaltaa, tehkää heille, mitä tahdotte, mutta tälle miehelle älkää tehkö sellaista häpeällistä tekoa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Mutta miehet eivät tahtoneet häntä kuulla. Silloin mies tarttui sivuvaimoonsa ja vei hänet heidän luokseen kadulle, ja he yhtyivät häneen ja pitelivät häntä pahoin koko yön aina aamuun asti, ja vasta aamun sarastaessa he hänet päästivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Päivän koittaessa vaimo tuli ja kaatui [kuolleena] sen miehen talon oven eteen, jonka talossa hänen isäntänsä oli, ja makasi siinä, kunnes päivä valkeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Kun hänen isäntänsä aamulla nousi ja avasi talon oven ja tuli ulos lähteäkseen matkalle, katso, hänen sivuvaimonsa makasi talon oven edessä, kädet kynnyksellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Hän sanoi hänelle: \"Nouse ja lähtekäämme!\" Mutta vastausta ei tullut. Silloin mies nosti hänet aasin selkään, nousi ja lähti kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Mutta kotiin tultuaan hän otti veitsen, tarttui sivuvaimoonsa, paloitteli hänet luineen kaikkineen kahdeksitoista kappaleeksi ja lähetti ne kaikkialle Israelin alueelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Jokainen, joka sen näki, sanoi: \"Mitään sellaista ei ole tapahtunut eikä nähty siitä päivästä lähtien, jona israelilaiset tulivat Egyptin maasta, aina tähän päivään saakka. Harkitkaa tätä, neuvotelkaa ja puhukaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Kaikki israelilaiset lähtivät liikkeelle, ja kansa kokoontui yhtenä miehenä Daanista aina Beersebaan saakka, niin myös Gileadin maasta, Herran eteen Mispaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Koko kansan päämiehet ja kaikki Israelin sukukunnat astuivat esiin Jumalan kansan seurakunnassa: neljäsataa tuhatta miekalla varustettua jalkamiestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Benjaminilaiset saivat kuulla, että israelilaiset olivat menneet Mispaan. Israelilaiset sanoivat: \"Kertokaa, kuinka tämä ilkityö tapahtui.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Niin leeviläinen mies, murhatun vaimon mies, vastasi ja sanoi: \"Minä ja minun sivuvaimoni olimme tulleet Benjaminin Gibeaan yöpyäksemme sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Silloin Gibean miehet nousivat minua vastaan ja piirittivät yöllä talon, jossa olin. Minut he aikoivat tappaa ja sivuvaimolleni he tekivät väkivaltaa, niin että hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Sitten tartuin sivuvaimooni ja paloittelin hänet ja lähetin kappaleet kaikkialle Israelin perintömaahan, koska he olivat tehneet ilkityön ja häpeällisen teon Israelissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Katso, te israelilaiset, te olette nyt tässä kaikki. Keskustelkaa ja neuvotelkaa tässä paikassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Silloin nousi kaikki kansa yhtenä miehenä ja sanoi: \"Älköön meistä kukaan menkö teltalleen, älköön kukaan poistuko kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Tämän me nyt teemme Gibealle: menemme sitä vastaan arvan mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Me otamme kymmenen miestä sadasta, Israelin kaikista sukukunnista, ja sata tuhannesta ja tuhat kymmenestätuhannesta, hankkimaan muonaa kansalle, kun se menee kostamaan Benjaminin Gibealle sen häpeällisen teon, minkä se on tehnyt Israelissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Niin kokoontuivat kaikki Israelin miehet kaupunkia vastaan kuin yhdeksi mieheksi yhtyneinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Israelin sukukunnat lähettivät miehiä kaikkiin Benjaminin sukuihin sanomaan: \"Millainen rikos onkaan tehty teidän keskuudessanne!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Luovuttakaa nyt ne Gibean kelvottomat miehet, surmataksemme heidät ja poistaaksemme pahan Israelista.\" Mutta benjaminilaiset eivät tahtoneet kuulla veljiään, israelilaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Benjaminilaiset kokoontuivat kaupungeistaan Gibeaan lähteäkseen sotaan israelilaisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Sinä päivänä pidettiin benjaminilaisten katselmus. Heitä oli muista kaupungeista kaksikymmentäkuusi tuhatta miekkamiestä, ottamatta lukuun Gibean asukkaita, joita katselmuksessa oli seitsemänsataa valiomiestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Kaikesta tästä väestä oli seitsemänsataa valiomiestä vasenkätistä. Jokainen näistä osasi lingota kiven hiuskarvalleen, erehtymättä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Myös pidettiin Israelin miesten katselmus, ja heitä oli, paitsi benjaminilaisia, neljäsataa tuhatta miekkamiestä, kaikki sotilaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'He nousivat ja lähtivät Beeteliin ja kysyivät Jumalalta. Israelilaiset sanoivat: \"Kenen meistä on ensiksi lähdettävä taistelemaan benjaminilaisia vastaan?\" Herra vastasi: \"Juuda ensiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Israelilaiset lähtivät liikkeelle seuraavana aamuna ja asettuivat leiriin Gibean edustalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Israelin miehet lähtivät taistelemaan Benjaminia vastaan, ja Israelin miehet asettuivat sotarintaan heitä vastaan Gibean edustalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Mutta benjaminilaiset ryntäsivät ulos Gibeasta ja kaatoivat sinä päivänä Israelista kaksikymmentäkaksi tuhatta miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Mutta kansa, Israelin miehet, rohkaisivat mielensä ja asettuivat jälleen rintamaan samalle paikalle, mihin olivat asettuneet ensimmäisenä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Sillä kun israelilaiset menivät ja itkivät Herran edessä iltaan asti ja kysyivät Herralta sanoen: \"Onko minun vielä ryhdyttävä taisteluun veljiäni, benjaminilaisia, vastaan?\" Herra vastasi: \"Menkää heitä vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Toisena päivänä israelilaiset lähenivät benjaminilaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'Benjaminilaiset toisena päivänä ryntäsivät Gibeasta heitä vastaan ja kaatoivat israelilaisia vielä kahdeksantoista tuhatta miestä, kaikki miekkamiehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Silloin kaikki israelilaiset, koko kansa, lähtivät ja tulivat Beeteliin ja itkivät ja istuivat siellä Herran edessä ja paastosivat sen päivän aina iltaan asti. He uhrasivat polttouhreja ja rauhanuhreja Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Israelilaiset kysyivät Herralta – sillä Jumalan liitonarkki oli siihen aikaan siellä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'ja Piinehas, Aaronin pojan Eleasarin poika, seisoi siihen aikaan sen edessä – ja sanoivat: \"Onko minun vielä lähdettävä taisteluun veljiäni, benjaminilaisia, vastaan, vai onko minun siitä luovuttava?\" Herra vastasi: \"Lähtekää, sillä huomenna minä annan heidät sinun käsiisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Silloin Israel asetti väijytyksiä Gibean ympärille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'ja israelilaiset menivät kolmantena päivänä benjaminilaisia vastaan ja asettuivat rintamaan Gibeaa vastaan niin kuin edellisilläkin kerroilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Benjaminilaiset ryntäsivät ulos kansaa vastaan, mutta tulivat eristetyiksi kaupungista. Kuten edellisilläkin kerroilla he aluksi saivat lyödyksi kansaa kuoliaaksi niillä valtateillä, joista toinen vie Beeteliin, toinen kedon yli Gibeaan, noin kolmekymmentä Israelin miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Silloin benjaminilaiset sanoivat: \"Me voitimme heidät nyt niin kuin ennenkin.\" Mutta israelilaiset sanoivat: \"Paetkaamme ja eristäkäämme heidät kaupungista valtateille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Kaikki Israelin miehet nousivat kukin paikaltaan ja asettuivat rintamaan Baal-Taamariin, ja väijyksissä oleva Israelin joukko syöksyi esiin paikaltaan Geban aukealta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Niin tuli kymmenentuhatta valiomiestä koko Israelista Gibean edustalle, ja syntyi ankara taistelu, eivätkä he huomanneet, että onnettomuus oli kohtaamassa heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Herra antoi Israelin voittaa Benjaminin, ja israelilaiset kaatoivat sinä päivänä Benjaminista kaksikymmentäviisi tuhatta ja sata miestä, kaikki miekkamiehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Nyt benjaminilaiset näkivät olevansa voitetut. Mutta Israelin miehet väistyivät benjaminilaisten tieltä, sillä he luottivat väijytykseen, jonka olivat asettaneet Gibeaa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Silloin väijyksissä ollut joukko riensi ja karkasi Gibeaan. Väijyksissä ollut joukko meni ja surmasi kaikki kaupungin asukkaat miekan terällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Israelin miehet olivat sopineet väijyksissä olevan joukon kanssa, että se panisi sakean savupilven nousemaan kaupungista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Kun siis Israelin miehet olivat kääntyneet pakoon taistelussa, ja kun Benjaminin miehet aluksi olivat lyöneet kuoliaaksi Israelin miehiä noin kolmekymmentä miestä ja sanoneet: \"Varmasti me voitamme heidät niin kuin ensimmäisessäkin taistelussa\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'niin alkoi pilvi, savupatsas, nousta kaupungista. Kun benjaminilaiset kääntyivät taaksepäin, katso, koko kaupunki nousi savuna taivasta kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Israelin miehet kääntyivät takaisin, mutta Benjaminin miehet kauhistuivat, sillä he näkivät, että onnettomuus oli kohdannut heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'He kääntyivät pakoon Israelin miesten edestä erämaan tielle, mutta sota seurasi heitä heidän kintereillään. Sikäläisten kaupunkien asukkaat kaatoivat heitä heidän keskeltään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'He saartoivat Benjaminin, ajoivat heitä takaa ja tallasivat heitä maahan levähdyspaikassa ja aina Gibean kohdalle asti auringonnousuun päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Niin kaatui Benjaminista kahdeksantoistatuhatta miestä, kaikki sotakuntoisia miehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'He kääntyivät ja pakenivat erämaahan päin Rimmonin kalliolle. Israelilaiset tekivät heistä valtateillä vielä jälkikorjuun, surmaten viisituhatta miestä, ja seurasivat heitä heidän kintereillään aina Gideomiin asti ja surmasivat heitä kaksituhatta miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Kaikkiaan oli niitä, jotka sinä päivänä kaatuivat Benjaminista, kaksikymmentäviisi tuhatta miekkamiestä, kaikki sotakuntoisia miehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Heitä kääntyi pakoon kohti erämaata, Rimmonin kalliolle, kuusisataa miestä. He jäivät Rimmonin kalliolle neljäksi kuukaudeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Mutta Israelin miehet palasivat takaisin benjaminilaisten luo ja surmasivat heidät miekan terällä, [tuhosivat] kaupungin sekä vahingoittumatta jääneet ihmiset että eläimet, kaiken, minkä tapasivat. Myös he pistivät tuleen kaikki kaupungit, joihin tulivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Israelin miehet olivat vannoneet Mispassa ja sanoneet: \"Kukaan meistä ei anna tytärtään benjaminilaiselle vaimoksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Kansa oli tullut Beeteliin, ja he istuivat siellä aina iltaan asti Jumalan edessä, korottivat äänensä ja itkivät katkerasti');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'ja sanoivat: \"Miksi, oi Herra, Israelin Jumala, Israelissa on käynyt niin, että Israelista puuttuu nyt yksi sukukunta?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Varhain seuraavana päivänä kansa nousi ja rakensi sinne alttarin ja uhrasi polttouhreja ja rauhanuhreja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Israelilaiset sanoivat: \"Onko yhdessäkään Israelin sukukunnassa ketään, joka ei ole tullut seurakunnan kanssa tänne Herran eteen?\" Sillä siitä, joka ei tulisi Herran luo Mispaan, oli vannottu ankara vala: \"Hänet on kuolemalla rangaistava.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Israelilaisten tuli sääli veljeään Benjaminia, ja he sanoivat: \"Tänä päivänä yksi sukukunta on hakattu pois Israelista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Mitä meidän on tehtävä, että jäljelle jääneet saavat vaimoja? Sillä itse me olemme vannoneet Herran kautta, ettemme anna heille tyttäriämme vaimoiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'He kysyivät: \"Onko Israelin sukukunnissa ainoatakaan, joka ei ollut tullut Herran eteen Mispaan?\" Niin, katso, Gileadin Jaabeksesta ei ollut ketään tullut leiriin, seurakuntakokoukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Sillä kun kansasta pidettiin katselmus, katso, siellä ei ollut ketään Gileadin Jaabeksen asukkaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Kansa lähetti sinne kaksitoista tuhatta sotakuntoista miestä ja käski heitä sanoen: \"Menkää ja surmatkaa miekan terällä Gileadin Jaabeksen asukkaat vaimoineen ja lapsineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Tehkää näin: kaikki miespuoliset ja kaikki naiset, jotka ovat yhtyneet mieheen, vihkikää tuhon omiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Mutta Gileadin Jaabeksen asukkaista he löysivät neljäsataa nuorta naista, jotka olivat neitsyitä eivätkä olleet yhtyneet mieheen. He veivät nämä leiriin Siiloon, joka on Kanaanin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Sitten koko kansa lähetti sanansaattajia puhumaan benjaminilaisten kanssa, jotka olivat Rimmonin kalliolla, ja tarjosi heille rauhaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Silloin benjaminilaiset palasivat takaisin, ja heille annettiin ne naiset, jotka oli jätetty henkiin Gileadin Jaabeksen naisista. Mutta ne eivät riittäneet heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Kansan tuli sääli Benjaminia, koska Herra oli tehnyt aukon Israelin sukukuntiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Silloin kansan vanhimmat sanoivat: \"Mitä meidän on tehtävä, että jäljelle jääneet saisivat vaimoja? Sillä onhan naiset hävitetty Benjaminista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'He sanoivat: \"Pelastuneiden perintöomaisuus on jäävä Benjaminille, ettei yksikään sukukunta häviäisi Israelista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Mutta itse emme voi antaa heille tyttäriämme vaimoiksi, sillä israelilaiset ovat vannoneet ja sanoneet: kirottu olkoon se, joka antaa vaimon benjaminilaiselle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'He sanoivat: \"Katso, joka vuosi vietetään Herran juhla Siilossa, joka on pohjoiseen Beetelistä, auringonnousun suuntaan siitä valtatiestä, joka vie Beetelistä Sikemiin, ja etelään Lebonasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'He käskivät benjaminilaisia sanoen: \"Menkää ja asettukaa väijyksiin viinitarhoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Kun näette Siilon tyttärien tulevan ulos karkeloimaan, rynnätkää viinitarhoista ja ryöstäkää jokainen itsellenne vaimo Siilon tyttäristä ja lähtekää Benjaminin maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Kun heidän isänsä tai veljensä tulevat valittamaan meille, sanomme heille: \'Lahjoittakaa heidät meille, sillä ei kukaan meistä ole ottanut sodalla vaimoa. Ettehän te ole itse antaneet niitä heille, muuten olisitte joutuneet syyllisiksi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Benjaminilaiset tekivät niin ja ottivat lukumääränsä mukaan itselleen vaimoja karkeloivien joukosta ryöstäen heidät. Sitten he palasivat perintöosaansa ja rakensivat uudestaan kaupungit ja asettuivat niihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Silloin israelilaisetkin vaelsivat sieltä, kukin sukukuntaansa ja sukuunsa, ja menivät sieltä kukin perintöosalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'Siihen aikaan ei ollut kuningasta Israelissa. Jokainen teki sitä, mikä hänen omasta mielestään oli oikein.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'Siihen aikaan kun tuomarit hallitsivat, maahan tuli nälänhätä. Silloin muuan Juudan Beetlehemin mies lähti sieltä ja asettui vaimonsa ja kahden poikansa kanssa asumaan muukalaisena Mooabin maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Miehen nimi oli Elimelek, hänen vaimonsa nimi Noomi ja hänen kahden poikansa nimet Mahlon ja Kiljon. He olivat efratilaisia Juudan Beetlehemistä. He tulivat Mooabin maahan ja oleskelivat siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Elimelek, Noomin mies, kuoli, ja Noomi jäi elämään kahden poikansa kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Nämä ottivat itselleen mooabilaiset vaimot. Toisen nimi oli Orpa ja toisen nimi Ruut. He asuivat siellä noin kymmenen vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Sitten myös molemmat, Mahlon ja Kiljon, kuolivat, niin että vaimo jäi yksin jäljelle kahden poikansa ja miehensä kuoltua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Hän nousi miniöineen palatakseen Mooabin maasta, sillä hän oli kuullut Mooabin maassa, että Herra oli pitänyt kansastaan huolen ja antanut sille leipää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Hän lähti yhdessä molempien miniöidensä kanssa siitä paikasta, jossa oli oleskellut. Heidän tietä käydessään matkalla Juudan maahan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Noomi sanoi molemmille miniöilleen: \"Menkää, palatkaa kumpikin äitinne kotiin. Herra tehköön teille laupeuden, kuten olette tehneet vainajille ja minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Herra suokoon, että saisitte turvan kumpikin miehenne kodissa.\" Sitten hän suuteli heitä. Mutta he korottivat äänensä ja itkivät');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'ja sanoivat hänelle: \"Me palaamme kanssasi kansasi luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Mutta Noomi vastasi: \"Kääntykää takaisin, tyttäreni, miksi lähtisitte kanssani? Voinko minä enää saada poikia miehiksi teille?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Kääntykää takaisin, tyttäreni, menkää, sillä minä olen liian vanha mennäkseni miehelle. Vaikka ajattelisinkin: \'Minulla on vielä toivoa\', ja vaikka vielä tänä yönä tulisin miehelle vaimoksi ja synnyttäisin poikia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'ette kai te kuitenkaan odottaisi, kunnes he kasvaisivat suuriksi, ette kai te kuitenkaan sulkeutuisi huoneeseen ja olisi menemättä miehelle vaimoksi. Ei, tyttäreni. Minä olen hyvin murheissani tähtenne, sillä Herran käsi on koskenut minuun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Niin he korottivat vielä äänensä ja itkivät. Silloin Orpa suuteli anoppiaan jäähyväisiksi, mutta Ruut riippui hänessä kiinni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Noomi sanoi: \"Katso, kälysi on kääntynyt takaisin oman kansansa ja jumalansa luo, käänny sinäkin kälysi kanssa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Mutta Ruut vastasi: \"Älä vaadi minua jättämään sinua ja kääntymään takaisin, pois luotasi. Sillä mihin sinä menet, sinne minäkin menen, ja missä sinä yövyt, siellä minäkin yövyn. Sinun kansasi on minun kansani, sinun Jumalasi on minun Jumalani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Missä sinä kuolet, siellä minäkin tahdon kuolla ja tulla sinne haudatuksi. Herra rangaiskoon minua nyt ja vasta, jos muu kuin kuolema erottaa meidät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Kun Noomi näki, että hän oli lujasti päättänyt seurata häntä, hän ei enää puhunut siitä hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Niin he kulkivat molemmat yhdessä, kunnes tulivat Beetlehemiin. Kun he tulivat Beetlehemiin, koko kaupunki joutui liikkeelle heidän tähtensä, ja vaimot sanoivat: \"Onko tämä Noomi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Mutta hän vastasi heille: \"Älkää kutsuko minua Noomiksi, kutsukaa minua Maaraksi, sillä Kaikkivaltias on antanut minulle paljon katkeraa murhetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Rikkaana minä lähdin, mutta tyhjänä Herra antaa minun palata. Miksi siis kutsutte minua Noomiksi, kun Herra on todistanut minua vastaan ja Kaikkivaltias on tuottanut onnettomuutta minulle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Niin Noomi oli palannut miniänsä, mooabilaisen Ruutin, kanssa, joka tuli Mooabin maasta. He olivat saapuneet Beetlehemiin ohranleikkuun alussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Noomilla oli miehensä puolelta sukulainen, hyvin varakas mies, Elimelekin sukua, nimeltä Booas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Mooabilainen Ruut sanoi Noomille: \"Anna minun mennä pellolle poimimaan tähkiä jonkun jäljessä, jonka silmien edessä saan armon.\" Noomi vastasi hänelle: \"Mene, tyttäreni!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Niin hän lähti ja meni poimimaan eräälle pellolle leikkuuväen jäljessä. Niin hänelle kävi niin, että se peltopalsta oli Booaan, joka oli Elimelekin sukua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Silloin, katso, Booas tuli Beetlehemistä ja sanoi leikkuuväelle: \" Herra olkoon kanssanne!\" He vastasivat hänelle: \" Herra siunatkoon sinua!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Sitten Booas sanoi palvelijalleen, joka oli leikkuuväen päällysmiehenä: \"Kenen tuo nuori nainen on?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Palvelija, joka oli leikkaajien päämiehenä, vastasi ja sanoi: \"Se on nuori mooabitar, joka tuli Noomin mukana Mooabin maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Ruut sanoi: \'Salli minun poimia ja koota tähkiä lyhteiden väliltä leikkaajien jäljessä.\' Niin hän tuli ja on ahertanut aamusta varhain tähän saakka. Vasta äsken hän hiukan levähti tuolla majassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Niin Booas sanoi Ruutille: \"Kuule, tyttäreni! Älä mene muiden pelloille poimimaan äläkä lähde pois täältä, vaan pysy täällä palvelijattarieni mukana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Pidä silmällä, millä pellolla leikataan, ja kulje heidän perässään. Olen kieltänyt palvelijoitani koskemasta sinuun. Jos sinun tulee jano, mene astioille ja juo vettä, jota palvelijat ammentavat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Ruut heittäytyi kasvoilleen, kumartui maahan ja sanoi hänelle: \"Miten olen saanut armon silmiesi edessä, niin että huolehdit minusta, vaikka olen vieras?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Booas vastasi ja sanoi hänelle: \"Minulle on kerrottu kaikki, mitä olet tehnyt anopillesi miehesi kuoltua, kuinka jätit isäsi ja äitisi ja synnyinmaasi ja lähdit kansan luo, jota et ennen tuntenut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Herra palkitkoon sinulle tekosi. Tulkoon sinulle täysi palkka Herralta, Israelin Jumalalta, jonka siipien alta olet tullut etsimään turvaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Ruut sanoi: \"Minä olen saanut armon silmiesi edessä, herrani, sillä sinä olet lohduttanut minua ja puhutellut palvelijatartasi ystävällisesti, vaikka en ole yhdenkään palvelijattaresi vertainen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Ruoka-ajan tultua Booas sanoi hänelle: \"Tule tänne syömään leipää ja kasta palasesi hapanviiniin.\" Ruut istui viljan leikkaajien viereen. Booas pani hänen eteensä paahdettuja jyviä, niin että hän söi tarpeekseen ja jäi tähteeksikin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Kun hän sitten nousi poimimaan, Booas käski palvelijoitaan sanoen: \"Hän saa poimia myös lyhteiden väliltä, ettekä te saa loukata häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Voittepa vetää lyhteistäkin joitakin tähkiä ja jättää ne hänen poimittavikseen, ettekä saa nuhdella häntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Ruut poimi pellolla iltaan asti. Sitten hän pui, mitä oli saanut poimituksi, ja siitä tuli noin eefa-mitan verran ohria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Hän otti ne, tuli kaupunkiin ja näytti anopilleen, mitä oli poiminut. Sen jälkeen Ruut otti esille tähteet ruuasta, josta oli syönyt tarpeekseen, ja antoi ne hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Silloin hänen anoppinsa sanoi hänelle: \"Missä olet tänään poiminut ja missä olet tehnyt työtä? Siunattu olkoon se, joka on sinusta huolehtinut.\" Sitten hän ilmoitti anopilleen, kenen luona hän oli ollut työssä, sanoen: \"Se mies, jonka luona olin tänä päivänä työssä, on nimeltään Booas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Noomi sanoi miniälleen: \"Siunatkoon häntä Herra, joka on osoittanut laupeutta eläviä ja kuolleita kohtaan.\" Noomi sanoi vielä: \"Hän on sukulaisemme ja sukulunastajiamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Silloin mooabilainen Ruut sanoi: \"Vielä hän sanoi minulle: \'Pysyttele vain palvelijoitteni mukana siihen asti, että he saavat päätökseen kaiken leikkuuni.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Niin Noomi sanoi miniälleen Ruutille: \"Hyvä on, tyttäreni, lähde hänen palvelijattariensa mukana, niin et joudu tönittäväksi muiden pelloilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Hän pysytteli Booaan palvelijattarien seurassa poimien tähkiä, kunnes ohran- ja vehnänleikkuu oli lopussa. Sitten hän jäi asumaan anoppinsa luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Niin Noomi, hänen anoppinsa, sanoi hänelle: \"Tyttäreni, minäpä hankin sinulle turvapaikan, että sinun kävisi hyvin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Onhan Booas, jonka palvelijattarien kanssa olit, sukulaisemme. Katso, hän viskaa tänä yönä ohria puimatantereella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Niin peseydy nyt, voitele itsesi, pukeudu ja mene puimatantereelle. Mutta älä näyttäydy hänelle, ennen kuin hän on syönyt ja juonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Kun hän panee maata, niin, katso, mihin paikkaan hän panee maata, ja mene ja nosta peitettä hänen jalkojensa kohdalta ja pane siihen maata. Hän sanoo sitten sinulle, mitä sinun on tehtävä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Ruut vastasi hänelle: \"Teen kaiken, mitä sanot.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Hän meni alas puimatantereelle ja teki aivan niin, kuin hänen anoppinsa oli häntä käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Kun Booas oli syönyt ja juonut, tuli hänen sydämensä iloiseksi, ja hän meni maata viljakasan viereen. Ruut tuli hiljaa ja nosti peitettä hänen jalkojensa kohdalta ja pani siihen maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Puoliyön aikaan mies säikähti ja kumartui eteenpäin. Niin, katso, nainen makasi hänen jalkopäässään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Hän kysyi: \"Kuka sinä olet?\" Hän vastasi: \"Minä olen Ruut, palvelijattaresi. Levitä helmasi palvelijattaresi yli, sillä sinä olet sukulunastajani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Hän sanoi: \" Herra siunatkoon sinua, tyttäreni! Sinä olet osoittanut sukurakkauttasi nyt viimeksi vielä kauniimmin kuin aikaisemmin, kun et ole kulkenut nuorten miesten jäljessä, et köyhien etkä rikkaitten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Nyt, tyttäreni, älä pelkää. Kaiken, mitä sanot, teen sinulle. Sillä kansani portissa jokainen tietää sinut kunnialliseksi naiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Totta on, että olen sukulunastajasi, mutta on vielä toinen sukulunastaja, joka on läheisempi kuin minä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Jää tähän yöksi. Jos hän huomenna lunastaa sinut, niin hyvä, lunastakoon. Mutta jollei hän halua lunastaa sinua, niin minä lunastan sinut, niin totta kuin Herra elää. Lepää siinä aamuun asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'Niin hän lepäsi hänen jalkopäässään aamuun asti, mutta nousi, ennen kuin kukaan vielä voi tuntea toisensa. Booas ajatteli: \"Älköön tulko tietoon, että tuo nainen on tullut tänne puimatantereelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Hän sanoi: \"Anna tänne viitta, joka on ylläsi, ja pidä siitä kiinni.\" Niin Ruut piti siitä kiinni. Silloin hän mittasi siihen kuusi mittaa ohria ja pani ne hänen selkäänsä. Sitten Ruut meni kaupunkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Ruut tuli anoppinsa luo, joka sanoi: \"Kuinka kävi, tyttäreni?\" Niin hän kertoi hänelle kaikki, mitä mies oli hänelle tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'Hän sanoi: \"Nämä kuusi mittaa ohria hän antoi minulle, sanoen: \'Et saa mennä tyhjin käsin anoppisi luo.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Silloin Noomi sanoi: \"Pysy alallasi, tyttäreni, kunnes saat tietää, kuinka asia päättyy; sillä mies ei suo itselleen lepoa, ennen kuin hän tänä päivänä saattaa asian päätökseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Mutta Booas meni kaupungin porttiin ja istuutui sinne. Katso, sukulunastaja, josta Booas oli puhunut, kulki siitä ohitse. Booas sanoi: \"Sinä siellä, poikkea tänne istumaan.\" Hän poikkesi ja istui siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Sen jälkeen Booas otti kaupungin vanhimpia kymmenen miestä ja sanoi: \"Istukaa tähän.\" Niin he istuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Sitten Booas sanoi sukulunastajalle: \"Sen peltopalstan, joka oli veljellämme Elimelekillä, Noomi, joka on palannut Mooabin maasta, haluaa myydä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Sen tähden minä ajattelin: ilmoitan siitä sinulle ja sanon: osta se tässä saapuvilla olevien ja kansani vanhimpien läsnä ollessa. Jos tahdot sen lunastaa sukuun, niin lunasta. Mutta ellet tahdo sitä lunastaa, ilmoita minulle, että saan sen tietää. Sillä ei ole ketään muuta sukulunastajaa kuin sinä, ja sinun jälkeesi minä.\" Hän sanoi: \"Minä lunastan sen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Niin Booas sanoi: \"Ostaessasi pellon Noomilta ostat sen myös mooabilaiselta Ruutilta, vainajan leskeltä, ja sinun on pysytettävä vainajan nimi hänen perintöosassaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Silloin sukulunastaja sanoi: \"En voi lunastaa sitä itselleni, sillä siten turmelisin oman perintöosani. Lunasta sinä itsellesi, mitä minun olisi lunastettava, sillä en voi sitä lunastaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Muinoin oli Israelissa lunastus- ja vaihtokauppoja vahvistettaessa tällainen tapa: riisuttiin sandaali ja annettiin toiselle. Tätä käytettiin Israelissa todisteena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Sukulunastaja sanoi Booaalle: \"Osta sinä se itsellesi.\" Ja hän veti kengän jalastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Silloin Booas sanoi vanhimmille ja kaikelle kansalle: \"Te olette tänään todistajina, että ostan Noomilta kaiken Elimelekin ja kaiken Kiljonin ja Mahlonin omaisuuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Samalla minä olen ostanut myös mooabilaisen Ruutin, Mahlonin lesken, vaimokseni, pysyttääkseni vainajan nimen hänen perintöosassaan, ettei vainajan nimi häviäisi hänen veljiensä keskuudesta eikä hänen kotipaikkansa portista. Sen todistajia te olette tänä päivänä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Niin kaikki kansa, joka oli portissa saapuvilla, ja vanhimmat sanoivat: \"Me olemme sen todistajia. Suokoon Herra, että vaimo, joka tulee taloosi, tulisi Raakelin ja Leean kaltaiseksi, jotka molemmat rakensivat Israelin huoneen. Tee väkeviä tekoja Efratassa ja saata nimesi kuuluisaksi Beetlehemissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Tulkoon niistä jälkeläisistä, jotka Herra antaa sinulle tästä nuoresta naisesta, sinulle suku, Pereksen suvun kaltainen, hänen, jonka Taamar synnytti Juudalle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Niin Booas otti Ruutin, ja tämä tuli hänen vaimokseen. Hän yhtyi häneen. Herra antoi hänen tulla raskaaksi, ja hän synnytti pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Silloin vaimot sanoivat Noomille: \"Kiitetty olkoon Herra, joka tänä päivänä salli sinun saada sukulunastajan. Hänen nimensä tulee kuuluisaksi Israelissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Hän on virvoittava sinua, ja hänestä on tuleva vanhuutesi tuki, sillä miniäsi, joka rakastaa sinua, on hänet synnyttänyt, hän, joka on sinulle parempi kuin seitsemän poikaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Niin Noomi otti lapsen, pani sen helmaansa ja rupesi sen hoitajaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Naapurivaimot antoivat lapselle nimen, sanoen: \"Noomille on syntynyt poika.\" He panivat hänelle nimeksi Oobed. Hänestä tuli Daavidin isän, Iisain, isä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Tämä on Pereksen sukuluettelo: Perekselle syntyi Hesron.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Hesronille syntyi Raam, ja Raamille syntyi Amminadab.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Amminadabille syntyi Nahson, ja Nahsonille syntyi Salma.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Salmalle syntyi Booas, ja Booaalle syntyi Oobed.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Oobedille syntyi Iisai, ja Iisaille syntyi Daavid.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Raamataim-Soofimissa, Efraimin vuoristossa, oli mies, nimeltä Elkana, Jerohamin poika, joka oli Elihun poika, joka Toohun poika, joka Suufin poika, efratilainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Hänellä oli kaksi vaimoa. Toisen nimi oli Hanna, ja toisen nimi oli Peninna. Peninnalla oli lapsia, mutta Hanna oli lapseton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Mies meni joka vuosi kaupungistaan Siiloon rukoilemaan Herraa Sebaotia ja uhraamaan hänelle. Siellä oli kaksi Eelin poikaa, Hofni ja Piinehas, Herran pappeina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Elkana uhrasi eräänä päivänä. Hänellä oli tapana antaa vaimolleen Peninnalle ja kaikille tämän pojille ja tyttärille uhrista määräosat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Mutta Hannalle hän antoi kaksinkertaisen osan, sillä hän rakasti Hannaa, vaikka Herra oli sulkenut hänen kohtunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Hänen kilpailijattarensa kiusasi häntä kiusaamistaan ärsyttääkseen häntä, koska Herra oli sulkenut Hannan kohdun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Näin tapahtui joka vuosi, niin usein kuin hän meni ylös Herran huoneeseen. Niinpä Peninna nytkin kiusasi Hannaa, ja Hanna itki eikä syönyt mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Hänen miehensä Elkana sanoi hänelle: \"Hanna, mitä itket, miksi et syö ja miksi olet noin apealla mielellä? Enkö minä ole sinulle enemmän kuin kymmenen poikaa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Kun he olivat syöneet ja juoneet Siilossa ja pappi Eeli istui istuimellaan Herran temppelin ovenpielessä, Hanna nousi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'rukoili Herraa mieli murheellisena, itki katkerasti');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'ja teki lupauksen sanoen: \" Herra Sebaot, jos katsot palvelijattaresi kurjuutta, muistat minua etkä unohda palvelijatartasi, vaan annat palvelijattarellesi miespuolisen perillisen, niin annan hänet Herralle hänen koko elinajakseen, eikä partaveitsi ole koskettava hänen päätään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Kun hän kauan rukoili Herran edessä, tarkkaili Eeli hänen suutaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'sillä Hanna puhui sydämessään ja ainoastaan hänen huulensa liikkuivat, mutta ääntä häneltä ei kuulunut. Eeli luuli, että hän oli juovuksissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Eeli sanoi hänelle: \"Kuinka kauan sinä olet siinä juovuksissa? Haihduta humalasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Mutta Hanna vastasi ja sanoi: \"Ei, herrani, minä olen murheen raskauttama nainen. Viiniä ja väkijuomaa en ole juonut, vaan vuodatin sydämeni Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Älä pidä palvelijatartasi kelvottomana naisena, sillä tuskani ja suruni suuruuden tähden olen näin kauan puhunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Eeli vastasi ja sanoi: \"Mene rauhaan, Israelin Jumala antakoon sinulle, mitä olet häneltä pyytänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Hän sanoi: \"Salli palvelijattaresi saada armo silmiesi edessä.\" Nainen meni pois, söi eikä enää näyttänyt murheelliselta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Varhain seuraavana aamuna he nousivat ja kumartaen rukoilivat Herran edessä. Sitten he palasivat ja tulivat kotiinsa Raamaan. Elkana yhtyi vaimoonsa Hannaan, ja Herra muisti tätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Tapahtui joidenkin päivien kuluttua, että Hanna tuli raskaaksi ja synnytti pojan ja antoi hänelle nimen Samuel, sanoen: \" Herralta olen hänet pyytänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Sitten hänen miehensä Elkana, ja koko hänen perheensä lähti uhraamaan Herralle jokavuotista teurasuhria ja lupausuhriaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'mutta Hanna ei lähtenyt, vaan sanoi miehelleen: \"Kun poika on vieroitettu, vien hänet sinne, että hän tulee Herran kasvojen eteen ja saa jäädä sinne ainiaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Hänen miehensä Elkana sanoi hänelle: \"Tee, kuten hyväksi näet, jää kotiin, kunnes olet hänet vieroittanut. Herra vahvistakoon sanansa.\" Vaimo jäi kotiin ja imetti poikaansa, kunnes hän vieroitti tämän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Mutta kun hän oli hänet vieroittanut, hän vei hänet kanssaan ottaen mukaansa kolme härkää, yhden eefa-mitan jauhoja ja leilin viiniä. Hän toi hänet Herran huoneeseen Siiloon. Mutta poika oli vielä pieni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Teurastettuaan härän he toivat pojan Eelin luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Hanna sanoi: \"Oi, herrani, niin totta kuin sinä elät, herrani, minä olen se vaimo, joka seisoin tässä sinun luonasi rukoillen Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Tätä poikaa rukoilin, ja Herra antoi minulle, mitä häneltä pyysin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Minäkin annan hänet Herralle kaikiksi elinpäivikseen. Hän olkoon Herralle annettu.\" Ja hän rukoili siellä Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Hanna rukoili ja sanoi: \"Sydämeni riemuitsee Herrassa. Sarveni kohoaa korkealle Herrassa. Suuni on avartunut vihollisiani vastaan, sillä iloitsen avustasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Kukaan ei ole pyhä niin kuin Herra. Sinun lisäksesi ei ole ketään toista. Ei ole kalliota Jumalamme vertaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Älkää yhä ylpeitä puhuko, älköön suustanne lähtekö julkeita sanoja. Sillä Herra on kaikkitietävä Jumala, hänen edessään punnitaan teot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Sankarien jouset ovat särjetyt, väsyneet vyöttäytyvät voimalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Kylläisinä olleet käyvät palvelukseen leipäpalkoilla, nälkää nähneet eivät enää nälkää näe. Hedelmätön synnyttää seitsemän lasta, monilapsinen kuihtuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Herra antaa kuoleman ja antaa elämän, hän vie alas helvettiin ja tuo ylös jälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Herra köyhdyttää ja rikastuttaa, hän alentaa ja ylentää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Hän nostaa tomusta halvan, hän korottaa loasta köyhän asettaakseen heidät ruhtinasten rinnalle ja tehdäkseen heistä kirkkauden valtaistuimen perillisiä. Sillä maailman perustukset ovat Herran, hän on asettanut maanpiirin niiden varaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Hän varjelee pyhiensä jalat, mutta jumalattomat hukkuvat pimeyteen. Sillä mies ei voi mitään omassa voimassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Ne, jotka taistelevat Herraa vastaan, joutuvat kauhun valtaan. Hän jylisee taivaasta heidän ylitseen. Herra tuomitsee maan ääret. Hän antaa vallan Kuninkaalleen ja korottaa korkealle Voideltunsa sarven.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Elkana meni kotiinsa Raamaan, mutta poika palveli Herraa pappi Eelin johdolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Eelin pojat olivat kelvottomia miehiä. He eivät välittäneet Herrasta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'eivätkä siitä, mitä papeilla oli oikeus saada kansalta. Niin usein kuin joku uhrasi teurasuhria, papin palvelija tuli lihan kiehuessa kolmihaarainen haarukka kädessään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'ja pisti sen kattilaan, ruukkuun, pannuun tai pataan, ja pappi otti itselleen kaiken sen, minkä haarukka toi mukanaan. Niin he tekivät kaikille israelilaisille, jotka tulivat sinne Siiloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Jo ennen kuin rasva oli poltettu, tuli papin palvelija ja sanoi miehelle, joka uhrasi: \"Anna liha paistettavaksi papille, sillä hän ei ota sinulta keitettyä lihaa, vaan raakaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Kun mies sanoi hänelle: \"Ensin poltettakoon rasva. Ota sitten itsellesi, mitä haluat.\" Hän sanoi: \"Ei niin, vaan anna se nyt heti, muuten otan väkisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Nuorten miesten synti oli kovin suuri Herran edessä, koska he pitivät halpana Herran uhrilahjan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Mutta Samuel palveli Herran edessä. Poikanen oli puettuna pellavakasukkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Hänen äitinsä teki hänelle joka vuosi pienen viitan ja toi sen hänelle, kun hän miehensä kanssa tuli uhraamaan jokavuotista teurasuhria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Eeli aina siunasi Elkanan ja hänen vaimonsa ja sanoi: \" Herra antakoon sinulle lapsen tästä vaimosta sen tilalle, jonka hän on suostunut antamaan Herralle.\" Sitten he menivät kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Herra piti Hannasta huolen, niin että hän tuli raskaaksi ja synnytti vielä kolme poikaa ja kaksi tytärtä. Mutta poikanen Samuel kasvoi Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Eeli oli käynyt hyvin vanhaksi. Kun hän sai kuulla, mitä hänen poikansa tekivät kaikelle Israelille, nimittäin että he makasivat niiden naisten kanssa, jotka toimittivat palvelusta ilmestysmajan ovella,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'hän sanoi heille: \"Miksi teette sellaista pahaa, mitä minä teistä kuulen kaikelta tältä kansalta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Ei niin, poikani! Ei ole hyvä se puhe, jonka kuulen kulkevan Herran kansan keskuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Jos ihminen rikkoo ihmistä vastaan, Jumala voi olla hänelle välittäjänä. Mutta jos ihminen rikkoo Herraa vastaan, kuka voi ruveta hänelle välittäjäksi?\" Mutta he eivät kuulleet isäänsä, sillä Herra tahtoi surmata heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Mutta poikanen Samuel kasvoi kasvamistaan ja oli sekä Herralle että ihmisille otollinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Eelin luo tuli Jumalan mies ja sanoi hänelle: \"Näin sanoo Herra: Enkö toden totta ilmestynyt sinun isäsi suvulle, kun he olivat Egyptissä faraon huoneen vallan alla?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'Valitsin heidät kaikista Israelin sukukunnista olemaan pappeinani, nousemaan alttarilleni, polttamaan suitsuketta ja kantamaan kasukkaa edessäni, ja annoin isäsi suvulle kaikki israelilaisten uhrit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Miksi häpäisette teurasuhrini ja ruokauhrini, jotka olen säätänyt asuntooni? Miksi kunnioitat poikiasi enemmän kuin minua, niin että te lihotatte itseänne parhaalla osalla jokaisesta kansani Israelin uhrilahjasta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Sen tähden Herra, Israelin Jumala, sanoo: Olen tosiaan sanonut: sukusi ja isäsi suku saavat vaeltaa edessäni iäti. Nyt on Herran sana: Pois se minusta! Sillä kunnioitan niitä, jotka minua kunnioittavat, mutta jotka katsovat minut ylen, ovat kirottuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Katso, päivät tulevat, jolloin katkaisen käsivartesi ja isäsi suvun käsivarren, niin ettei kukaan suvussasi elä vanhaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Saat nähdä asuntosi olevan puutteessa huolimatta kaikesta siitä hyvästä, mikä tulee Israelille. Eikä kukaan suvussasi ole koskaan elävä vanhaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'En hävitä jokaista alttariltani, niin että sammuttaisin silmäsi ja näännyttäisin sielusi, mutta kaikki suvussasi kasvaneet kuolevat miehiksi tultuaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Merkkinä tästä on sinulla oleva se, mitä tapahtuu kahdelle pojallesi, Hofnille ja Piinehaalle: he kuolevat molemmat samana päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Mutta herätän itselleni uskollisen papin, joka tekee sydämeni ja mieleni mukaan. Hänelle rakennan pysyvän huoneen, ja hän on vaeltava minun voideltuni edessä koko elinaikansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Jokainen, joka jää jäljelle suvustasi, on tuleva kumartamaan häntä saadakseen hopearahan ja leipäkakun ja sanova: \'Päästä minutkin johonkin papintehtävään, että saisin palan leipää syödäkseni.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Poikanen Samuel palveli Herraa Eelin johdolla. Mutta Herran sana oli harvinainen siihen aikaan, eivätkä näyt olleet tavallisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Siihen aikaan tapahtui kerran, kun Eeli, jonka silmiä alkoi hämärtää, ettei hän voinut nähdä, makasi paikallaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'eikä Jumalan lamppu ollut vielä sammunut ja Samuel makasi Herran temppelissä, jossa Jumalan arkki oli,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'että Herra kutsui Samuelia. Hän vastasi: \"Tässä olen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Hän riensi Eelin luo ja sanoi: \"Tässä olen, kutsuit minua.\" Mutta hän vastasi: \"En minä kutsunut. Pane jälleen maata.\" Hän meni ja pani maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Mutta Herra kutsui taas Samuelia. Samuel nousi ja meni Eelin luo ja sanoi: \"Tässä olen, kutsuit minua.\" Mutta tämä vastasi: \"En minä kutsunut, poikani. Pane jälleen maata.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Samuel ei silloin vielä tuntenut Herraa, eikä Herran sana ollut vielä ilmestynyt hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Herra kutsui Samuelia vielä kolmannen kerran. Hän nousi ja meni Eelin luo ja sanoi: \"Tässä olen, kutsuit minua.\" Silloin Eeli ymmärsi, että Herra oli kutsunut poikasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Eeli sanoi Samuelille: \"Mene ja pane maata. Jos sinua vielä kutsutaan, sano: \'Puhu, Herra, palvelijasi kuulee.\'\" Samuel meni ja pani maata paikalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Herra tuli, seisoi ja huusi kuten edellisilläkin kerroilla: \"Samuel, Samuel!\" Samuel vastasi: \"Puhu, palvelijasi kuulee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Herra sanoi Samuelille: \"Katso, minä teen Israelissa sellaisen teon, että joka sen kuulee, sen molemmat korvat soivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'Sinä päivänä minä toteutan Eelille kaiken, mitä hänen sukuaan vastaan olen puhunut, alusta loppuun asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Ilmoitan hänelle, että minä tuomitsen hänen sukunsa ikiajoiksi sen rikoksen tähden, kun hän tiesi poikiensa pilkkaavan Jumalaa eikä pannut heitä kuriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Sen tähden olen vannonut Eelin suvusta: \'Totisesti, Eelin suvun rikosta ei koskaan soviteta, ei teurasuhrilla eikä ruokauhrilla.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Samuel makasi aamuun asti ja avasi Herran huoneen ovet. Eikä Samuel uskaltanut kertoa Eelille näkyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Mutta Eeli kutsui Samuelin ja sanoi: \"Samuel, poikani!\" Hän vastasi: \"Tässä olen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Hän sanoi: \"Mikä oli asia, josta hän sinulle puhui? Älä salaa sitä minulta. Jumala rangaiskoon sinua nyt ja vasta, jos salaat minulta mitään siitä, mitä hän sinulle puhui.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Samuel kertoi hänelle kaiken eikä salannut häneltä mitään. Hän sanoi: \"Hän on Herra, hän tehköön, minkä hyväksi näkee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Samuel kasvoi, ja Herra oli hänen kanssaan eikä antanut yhdenkään hänen sanoistaan pudota maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Koko Israel Daanista Beersebaan asti tiesi, että Samuelille oli uskottu Herran profeetan tehtävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Herra ilmestyi edelleenkin Siilossa. Herra ilmestyi näet Samuelille Siilossa Herran sanan kautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'ja Samuelin sana tuli koko Israelille. Israel lähti sotaan filistealaisia vastaan ja leiriytyi Eben-Eserin luo, mutta filistealaiset olivat leiriytyneet Afekiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Filistealaiset asettuivat sotarintaan Israelia vastaan, ja taistelu levisi laajalle, ja filistealaiset voittivat Israelin ja surmasivat taistelukentällä noin neljätuhatta miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Kun kansa tuli leiriin, Israelin vanhimmat sanoivat: \"Minkä tähden Herra antoi tänä päivänä filistealaisten voittaa meidät? Ottakaamme Herran liitonarkki Siilosta luoksemme, tulkoon se keskellemme pelastamaan meidät vihollistemme käsistä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Kansa lähetti sanan Siiloon, ja sieltä tuotiin Herran Sebaotin liitonarkki, hänen, jonka valtaistuinta kerubit kannattavat, ja Eelin kaksi poikaa, Hofni ja Piinehas, seurasivat sieltä Jumalan liitonarkkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Kun sitten Herran liitonarkki tuli leiriin, koko Israel nosti suuren riemuhuudon, niin että maa tömisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Kun filistealaiset kuulivat riemuhuudon, he sanoivat: \"Mitä tuo suuri riemuhuuto on heprealaisten leirissä?\" He saivat tietää, että leiriin oli tullut Herran arkki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Filistealaiset pelästyivät, sillä he sanoivat: \"Jumala on tullut leiriin.\" He sanoivat: \"Voi meitä! Tällaista ei ole milloinkaan ennen tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Voi meitä! Kuka pelastaa meidät tämän voimallisen jumalan kädestä? Tämähän on se jumala, joka löi egyptiläisiä kaikkinaisilla vaivoilla erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Rohkaiskaa mielenne ja olkaa miehiä, filistealaiset, ettette joutuisi palvelemaan heprealaisia, niin kuin he ovat palvelleet teitä. Olkaa miehiä ja taistelkaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Filistealaiset ryhtyivät taisteluun, ja Israel voitettiin, niin että he pakenivat kukin majalleen, ja tappio oli hyvin suuri: Israelista kaatui kolmekymmentä tuhatta jalkamiestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Jumalan arkki ryöstettiin, ja Eelin kaksi poikaa, Hofni ja Piinehas, saivat surmansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Eräs benjaminilainen mies juoksi rintamalta ja tuli samana päivänä Siiloon takki reväistynä ja multaa pään päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Kun hän saapui sinne, Eeli istui istuimellaan tien vieressä tähystellen, sillä hänen sydämensä oli levoton Jumalan arkin tähden. Kun mies tuli ja kertoi kaupungissa tapahtumasta, koko kaupunki puhkesi valittamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Kun Eeli kuuli valitushuudon, hän kysyi: \"Mikä meteli tämä on?\" Mies riensi sinne ja kertoi sen Eelille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Eeli oli yhdeksänkymmentä kahdeksan vuotta vanha, ja hänen silmissään oli kaihi, niin ettei hän voinut nähdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Mies sanoi Eelille: \"Minä tulen rintamalta, olen tänä päivänä paennut rintamalta.\" Hän kysyi: \"Miten ovat asiat, poikani?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Sanansaattaja vastasi ja sanoi: \"Israel on paennut filistealaisia, ja kansan mieshukka on suuri. Myös molemmat poikasi, Hofni ja Piinehas, ovat saaneet surmansa, ja Jumalan arkki on ryöstetty.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Kun hän mainitsi Jumalan arkin, Eeli kaatui istuimeltaan taaksepäin portin viereen, taittoi niskansa ja kuoli, sillä hän oli vanha ja painava mies. Hän oli ollut tuomarina Israelissa neljäkymmentä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Hänen miniänsä, Piinehaan vaimo, oli viimeisillään raskaana. Kun hän kuuli sanoman Jumalan arkin ryöstöstä ja appensa ja miehensä kuolemasta, hän vaipui maahan ja synnytti, sillä poltot yllättivät hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Kun hän silloin oli kuolemaisillaan, sanoivat vaimot, jotka seisoivat hänen luonaan: \"Älä pelkää, sillä sinä olet synnyttänyt pojan.\" Mutta hän ei vastannut mitään eikä välittänyt siitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'vaan nimitti pojan Iikabodiksi ja sanoi: \"Kunnia on mennyt Israelilta\" – hän tarkoitti Jumalan arkin ryöstöä sekä appeaan ja miestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Hän sanoi: \"Kunnia on mennyt Israelilta\", koska Jumalan arkki oli ryöstetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Kun filistealaiset olivat ryöstäneet Jumalan arkin, he veivät sen Eben-Eseristä Asdodiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Filistealaiset ottivat Jumalan arkin ja veivät sen Daagonin temppeliin ja asettivat sen Daagonin rinnalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Kun asdodilaiset nousivat varhain seuraavana päivänä, katso: Daagon makasi kasvoillaan maassa Herran arkin edessä. Mutta he ottivat Daagonin ja asettivat sen takaisin paikoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Kun he taas nousivat varhain seuraavana aamuna, niin katso: Daagon makasi kasvoillaan maassa Herran arkin edessä, mutta Daagonin pää ja molemmat kädet olivat katkaistuina kynnyksellä, ja ainoastaan [muuta] Daagonia oli siinä jäljellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Sen tähden eivät Daagonin papit eikä kukaan, joka menee Daagonin temppeliin, astu Daagonin kynnykselle Asdodissa vielä tänäkään päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Herran käsi painoi asdodilaisia, ja hän tuhosi heitä. Hän löi heitä paiseilla, sekä Asdodia että sen aluetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Kun Asdodin miehet näkivät, miten oli, he sanoivat: \"Älköön Israelin Jumalan arkki jääkö luoksemme, sillä hänen kätensä on käynyt raskaaksi meille ja jumalallemme Daagonille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'He lähettivät sanan ja kokosivat kaikki filistealaiset ruhtinaat luokseen ja sanoivat: \"Mitä teemme Israelin Jumalan arkille?\" He vastasivat: \"Israelin Jumalan arkki siirtyköön Gatiin.\" He siirsivät Israelin Jumalan arkin sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Kun he olivat siirtäneet sen sinne, kohtasi Herran käsi kaupunkia ja sai aikaan suuren hämmingin: hän löi kaupungin asukkaita, sekä pieniä että suuria, niin että heihin puhkesi paiseita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Silloin he lähettivät Jumalan arkin Ekroniin. Kun Jumalan arkki tuli Ekroniin, huusivat ekronilaiset sanoen: \"He ovat siirtäneet Israelin Jumalan arkin tänne luokseni surmaamaan minut ja kansani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'He lähettivät sanan ja kokosivat kaikki filistealaisten ruhtinaat ja sanoivat: \"Lähettäkää Israelin Jumalan arkki pois, ja palatkoon se kotiinsa älköönkä se enää surmatko minua ja kansaani.\" Sillä surma oli saattanut koko kaupungin hämminkiin. Jumalan käsi painoi sitä kovasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Ne asukkaat, jotka eivät olleet kuolleet, olivat paiseilla lyötyjä, ja huuto nousi kaupungista ylös taivaaseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Herran arkki oli ollut filistealaisten maassa seitsemän kuukautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Filistealaiset kutsuivat papit ja tietäjät ja sanoivat: \"Mitä teemme Herran arkille? Antakaa meidän tietää, millä tavalla lähettäisimme sen kotiinsa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'He vastasivat: \"Jos te lähetätte Israelin Jumalan arkin pois, älkää lähettäkö sitä tyhjin käsin, vaan antakaa hänelle hyvitys. Silloin te tulette terveiksi ja saatte tietää, minkä tähden hänen kätensä ei heltiä teistä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Mutta he kysyivät: \"Millainen hyvitys meidän on annettava hänelle?\" He vastasivat: \"Viisi kultaista paisetta ja viisi kultahiirtä, yhtä monta, kuin on filistealaisten ruhtinasta, sillä sama vitsaus on kohdannut kaikkia, myös teidän ruhtinaitanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Tehkää siis kuvat paiseistanne, samoin hiiristänne, jotka hävittävät maata, ja antakaa kunnia Israelin Jumalalle. Kenties hän silloin hellittää kätensä teistä, jumalistanne ja maastanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Miksi paadutatte sydämenne, niin kuin egyptiläiset ja farao paaduttivat sydämensä? Eivätkö he, sitten kun hän oli näyttänyt heille voimansa, päästäneet israelilaisia menemään?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Tehkää nyt uudet vaunut ja ottakaa kaksi imettävää lehmää, joiden niskassa ei ole ollut iestä, ja valjastakaa lehmät vaunujen eteen, mutta ajakaa vasikat kotiin pois niiden perästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Ottakaa Herran arkki ja asettakaa se vaunuihin ja pankaa ne kultaesineet, jotka annatte hänelle hyvitykseksi, lippaaseen sen viereen, ja lähettäkää se menemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Sitten katsokaa: jos se menee omaa aluettaan kohti ylös Beet-Semekseen, niin se on tuottanut meille tämän suuren onnettomuuden. Mutta jos ei, niin tiedämme, ettei hänen kätensä ole meihin koskenut. Se on silloin tapahtunut meille sattumalta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Miehet tekivät niin. He ottivat kaksi imettävää lehmää ja valjastivat ne vaunujen eteen, mutta niiden vasikat he jättivät kotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'He panivat Herran arkin vaunuihin sekä lippaan, kultahiiret ja paiseittensa kuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Lehmät menivät suoraan Beet-Semestä kohden. Ne kulkivat koko ajan samaa tietä poikkeamatta oikealle tai vasemmalle ja ammuivat lakkaamatta. Filistealaisten ruhtinaat seurasivat niitä Beet-Semeksen alueelle asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Mutta Beet-Semeksessä oltiin leikkaamassa vehnää laaksossa. Kun he nostivat silmänsä, he näkivät arkin ja ilahtuivat sen nähdessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Vaunut tulivat beet-semekseläisen Joosuan pellolle ja pysähtyivät sinne. Siellä oli suuri kivi. He hakkasivat vaunut polttopuiksi ja uhrasivat lehmät polttouhriksi Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Leeviläiset nostivat maahan Herran arkin ja sen vieressä olevan lippaan, jossa kultaesineet olivat, ja panivat ne suurelle kivelle. Beet-Semeksen miehet uhrasivat sinä päivänä Herralle polttouhreja ja teurasuhreja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Katseltuaan tätä nuo filistealaisten viisi ruhtinasta palasivat samana päivänä Ekroniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Nämä ovat ne kultapaiseet, jotka filistealaiset antoivat Herralle hyvitykseksi: yksi Asdodin puolesta, yksi Gassan puolesta, yksi Askelonin puolesta, yksi Gatin puolesta ja yksi Ekronin puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Kultahiiriä taas oli yhtä monta, kuin oli kaikkiaan filistealaisten kaupunkeja viidellä ruhtinaalla, sekä varustettuja kaupunkeja että linnoittamattomia kyliä, suureen kiveen asti, jolle he laskivat Herran arkin ja joka on vielä tänäkin päivänä beet-semekseläisen Joosuan pellolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Mutta Herra surmasi Beet-Semeksen miehiä sen tähden, että he olivat katsoneet Herran arkkiin. Hän surmasi kansasta seitsemänkymmentä miestä, viisikymmentä päämiestä. Kansa suri, että Herra oli surmannut niin paljon kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Beet-Semeksen miehet sanoivat: \"Kuka voi kestää Herran, tämän pyhän Jumalan, edessä? Kenen luo hän menee meidän luotamme?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'He lähettivät sanansaattajat Kirjat-Jearimin asukkaiden luo sanomaan: \"Filistealaiset ovat tuoneet Herran arkin takaisin. Tulkaa tänne ja viekää se luoksenne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Kirjat-Jearimin miehet tulivat ja veivät Herran arkin sinne ja toivat sen Abinadabin taloon mäelle, ja pyhittivät hänen poikansa Eleasarin pitämään huolta Herran arkista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Siitä päivästä, jona arkki oli asettunut Kirjat-Jearimiin, kului pitkä aika, kului kaksikymmentä vuotta, ja koko Israelin heimo kääntyi valittaen Herran puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Mutta Samuel puhui koko Israelin huoneelle sanoen: \"Jos te kaikesta sydämestänne käännytte Herran puoleen, poistakaa keskuudestanne vieraat jumalat ja astartet ja kiinnittäkää sydämenne Herraan ja palvelkaa ainoastaan häntä, niin hän pelastaa teidät filistealaisten käsistä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Israelilaiset poistivat baalit ja astartet ja palvelivat ainoastaan Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Silloin Samuel sanoi: \"Kootkaa koko Israel Mispaan, ja [minä] rukoilen puolestanne Herraa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Niin he kokoontuivat Mispaan, ammensivat vettä, vuodattivat sitä Herran eteen sekä paastosivat sen päivän, ja he sanoivat siellä: \"Me olemme tehneet syntiä Herraa vastaan.\" Samuel jakoi israelilaisille oikeutta Mispassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Kun filistealaiset kuulivat israelilaisten kokoontuneen Mispaan, filistealaisten ruhtinaat lähtivät Israelia vastaan. Kun israelilaiset kuulivat sen, he pelkäsivät filistealaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Israelilaiset sanoivat Samuelille: \"Älä kieltäydy huutamasta avuksi puolestamme Herraa, Jumalaamme, että hän pelastaisi meidät filistealaisten käsistä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Samuel otti imevän karitsan ja uhrasi sen polttouhriksi, kokonaisuhriksi, Herralle, ja Samuel huusi Herraa avuksi Israelin puolesta, ja Herra kuuli häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Sillä kun Samuelin uhratessa polttouhria filistealaiset lähestyivät käydäkseen taisteluun Israelia vastaan, Herra jyrisi kovalla ukkosen jyrinällä sinä päivänä filistealaisia vastaan ja saattoi heidät hämminkiin, niin että Israel voitti heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Israelin miehet lähtivät Mispasta ja ajoivat filistealaisia takaa surmaten heitä aina Beet-Kaarin alapuolelle asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Samuel otti kiven ja pani sen Mispan ja Seenin välille ja antoi sille nimen Eben-Eser ja sanoi: \"Tähän asti Herra on meitä auttanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Niin filistealaiset lannistettiin, eivätkä he enää tulleet Israelin alueelle. Herran käsi oli filistealaisia vastaan Samuelin koko elinajan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Ne kaupungit, jotka filistealaiset olivat ottaneet Israelilta, joutuivat takaisin Israelille, Ekronista Gatiin saakka. Myös niiden alueet Israel vapautti filistealaisten käsistä. Myös Israelin ja amorilaisten välillä oli rauha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Samuel oli tuomarina Israelissa koko elinaikansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Hän teki joka vuosi kiertomatkoja Beeteliin, Gilgaliin ja Mispaan, ja hän jakoi Israelille oikeutta kaikissa näissä paikoissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Hän palasi jälleen Raamaan, sillä siellä oli hänen kotinsa ja siellä hän jakoi oikeutta Israelille. Hän rakensi sinne alttarin Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Kun Samuel oli käynyt vanhaksi, hän pani poikansa Israelin tuomareiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Hänen esikoisensa nimi oli Jooel, ja hänen toisen poikansa nimi oli Abia. Nämä olivat tuomareina Beersebassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Mutta hänen poikansa eivät vaeltaneet hänen teitään, vaan olivat väärän voiton pyytäjiä, ottivat lahjuksia ja vääristivät oikeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Kaikki Israelin vanhimmat kokoontuivat ja tulivat Samuelin luo Raamaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'ja sanoivat hänelle: \"Katso, sinä olet käynyt vanhaksi, eivätkä poikasi vaella teitäsi. Aseta nyt meille oikeutta jakamaan kuningas, jollainen kaikilla muillakin kansoilla on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Mutta Samuel pahastui siitä, että he sanoivat: \"Anna meille kuningas jakamaan meille oikeutta.\" Samuel rukoili Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Niin Herra sanoi Samuelille: \"Kuule kansan ääntä kaikessa, mitä he sinulle sanovat, sillä sinua he eivät ole pitäneet halpana, vaan minut he ovat pitäneet halpana olemaan heidän kuninkaanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Kuten he ovat tehneet aina siitä päivästä, jona johdatin heidät tänne Egyptistä, tähän päivään asti, kun ovat hylänneet minut ja palvelleet muita jumalia, aivan niin he tekevät nyt sinullekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Kuule siis heidän ääntään. Kuitenkin varoita heitä vakavasti ja ilmoita heille, mitkä oikeudet on kuninkaalla, joka on heitä hallitseva.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Samuel puhui kaikki Herran sanat kansalle, joka pyysi häneltä kuningasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Hän sanoi: \"Nämä oikeudet on kuninkaalla, joka on teitä hallitseva: Hän ottaa poikanne ja panee heidät vaunumiehikseen, ratsumiehikseen ja vaunujensa edellä juoksijoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'Hän panee heitä myös tuhannen- ja viidenkymmenenpäämiehiksi ja kyntämään kyntöjään ja leikkaamaan viljaansa sekä tekemään itselleen sotatarvikkeita ja vaunujen osia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Tyttärenne hän ottaa voiteiden tekijöiksi, keittäjiksi ja leipojiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Hän ottaa parhaat peltonne, viinitarhanne ja öljypuunne ja antaa ne palvelijoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Hän ottaa kymmenykset kylvöstänne ja viinitarhojenne sadosta ja antaa ne hoviherroilleen ja palvelijoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Hän ottaa myös palvelijanne ja palvelijattarenne ja parhaat nuoret miehenne sekä aasinne ja teettää niillä työnsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Hän ottaa myös kymmenykset lampaistanne, ja te tulette hänen palvelijoikseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Silloin te huudatte Herraa kuninkaanne tähden, jonka olette itsellenne valinneet, mutta hän ei silloin teitä kuule.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Mutta kansa ei tahtonut kuulla Samuelin puhetta, vaan sanoi: \"Ei, kuningas meillä pitää olla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'Mekin tahdomme olla niin kuin kaikki muut kansat: kuningas jakaa meille oikeutta, johtaa meitä ja käy sotiamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Kun Samuel kuuli kaikki kansan puheet, hän puhui ne Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Herra sanoi Samuelille: \"Kuule heidän ääntään ja aseta heille kuningas.\" Niin Samuel sanoi Israelin miehille: \"Menkää kukin kaupunkiinne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Benjaminissa oli mies, hyvin varakas, nimeltä Kiis, Abielin poika, joka oli Serorin poika, joka Bekoratin poika, joka Afiahin poika, joka erään benjaminilaisen miehen poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Hänellä oli poika, nimeltä Saul, nuori, komea mies. Israelilaisten joukossa ei ollut komeampaa miestä kuin hän: hän oli päätään pitempi kaikkea kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Kiisiltä, Saulin isältä, olivat aasintammat joutuneet kadoksiin, ja Kiis sanoi pojalleen Saulille: \"Ota palvelijoista joku mukaasi, nouse ja mene etsimään aasintammoja.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Hän kulki Efraimin vuoriston halki, ja hän kulki Salisan maan halki, mutta he eivät löytäneet niitä. Sitten he kulkivat Saalimin maan halki, eikä niitä ollut sielläkään. Sitten he kulkivat Benjaminin maan halki eivätkä löytäneet niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Kun he olivat tulleet Suufin maahan, Saul sanoi palvelijalleen, joka oli hänellä mukana: \"Tule, palatkaamme. Muuten isäni käy levottomaksi tähtemme ja jättää mielestään aasintammat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Mutta palvelija sanoi hänelle: \"Katso, tässä kaupungissa on Jumalan mies, arvossa pidetty mies. Kaikki, mitä hän sanoo, varmasti toteutuu. Menkäämme nyt sinne. Kenties hän ilmaisee meille jotakin matkasta, jolla olemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Niin Saul sanoi palvelijalleen: \"Jos menemme sinne, niin mitä viemme miehelle? Sillä leipä on loppunut repuistamme, eikä meillä ole muutakaan lahjaa vietäväksi Jumalan miehelle. Vai onko meillä mitään?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Palvelija vastasi vielä Saulille ja sanoi: \"Katso, tässä on minulla neljännes sekeliä hopeaa. Minä annan sen Jumalan miehelle, että hän ilmaisisi meille jotakin matkastamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '– Muinoin sanottiin Israelissa, kun mentiin kysymään Jumalalta, näin: \"Tulkaa, menkäämme näkijän luo.\" Sillä sitä, jota nyt sanotaan profeetaksi, kutsuttiin muinoin näkijäksi. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Saul vastasi palvelijalleen: \"Puheesi on hyvä, tule, menkäämme.\" He menivät kaupunkiin, jossa Jumalan mies oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Kun he nousivat rinnettä ylös kaupunkiin, he kohtasivat tyttöjä, jotka olivat menossa ammentamaan vettä. Näiltä he kysyivät: \"Onko näkijä täällä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Nämä vastasivat heille ja sanoivat: \"On, katso, hän on tuolla edessäpäin. Riennä, sillä hän on juuri nyt tullut kaupunkiin, koska kansalla tänä päivänä on teurasuhrit uhrikukkulalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Kun tulette kaupunkiin, tapaatte hänet, ennen kuin hän menee uhrikukkulalle aterioimaan. Sillä kansa ei aterioi, ennen kuin hän tulee. Kun hän on siunannut uhrin, sitten vasta kutsuvieraat aterioivat. Menkää siis sinne, sillä juuri nyt tapaatte hänet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Niin he menivät kaupunkiin. Kun he tulivat kaupunkiin, katso, Samuel tuli heitä vastaan ollessaan menossa uhrikukkulalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Mutta päivää ennen Saulin tuloa oli Herra ilmoittanut ja sanonut Samuelille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, '\"Huomenna tähän aikaan minä lähetän luoksesi miehen Benjaminin maasta. Voitele hänet kansani Israelin ruhtinaaksi. Hän on vapauttava kansani filistealaisten käsistä. Sillä minä olen katsonut kansani puoleen. Sen huuto on tullut eteeni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Kun Samuel näki Saulin, ilmoitti Herra hänelle: \"Katso, tässä on mies, josta minä olen sinulle sanonut: \'Tämä on hallitseva kansaani.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Saul meni Samuelin luo keskelle porttia ja sanoi: \"Sano minulle, missä on näkijän asunto?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Samuel vastasi Saulille ja sanoi: \"Minä olen näkijä. Mene edelläni uhrikukkulalle. Aterioikaa tänä päivänä kanssani. Huomenaamuna lasken sinut menemään, ja kaiken, mitä sinulla on sydämelläsi, selvitän sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Äläkä enää ole huolissasi aasintammoista, jotka ovat olleet sinulta kateissa kolme päivää, sillä ne ovat löytyneet. Kenen on kaikki, mitä kallisarvoisinta Israelissa on, jollei sinun ja koko isäsi perheen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Saul vastasi ja sanoi: \"Minähän olen benjaminilainen, olen sukukunnasta, joka on Israelin pienimpiä, ja minun sukuni on vähäisin kaikista Benjaminin sukukunnan suvuista. Miksi puhut minulle näin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Samuel otti Saulin palvelijoineen ja vei heidät ruokailuhuoneeseen ja antoi heille ylimmän sijan kutsuvierasten joukossa, joita oli noin kolmekymmentä miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Samuel sanoi keittäjälle: \"Tuo tänne se kappale, jonka sinulle annoin ja josta sanoin sinulle: \'Pane se sivuun.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Keittäjä otti reiden, ja mitä siihen kuului, ja pani sen Saulin eteen. Samuel sanoi: \"Katso, tässä pannaan eteesi se, mikä on varattu. Syö siitä. Sillä juuri täksi hetkeksi se säästettiin sinua varten, kun sanoin: \'Minä olen kutsunut kansan.\'\" Saul aterioi Samuelin kanssa sinä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Kun he sitten olivat tulleet uhrikukkulalta alas kaupunkiin, hän puhui Saulin kanssa katolla. Sitten he nousivat varhain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Aamun sarastaessa Samuel kutsui Saulia katolta ja sanoi: \"Nouse, lähden saattamaan sinua.\" Saul nousi, ja hän ja Samuel menivät yhdessä ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Kun he tulivat alas kaupungin laitaan, sanoi Samuel Saulille: \"Sano palvelijalle, että hän menee meidän edellämme\" – ja tämä meni edelle – \"mutta pysähdy sinä hetkeksi tähän, niin julistan sinulle Jumalan sanan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Samuel otti öljyastian, vuodatti öljyä hänen päähänsä, suuteli häntä ja sanoi: \"Katso, Herra on voidellut sinut perintöosansa ruhtinaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Kun tänä päivänä lähdet luotani, kohtaat kaksi miestä Raakelin haudan luona Selsahissa Benjaminin rajalla. He sanovat sinulle: \'Aasintammat, joita olet lähtenyt etsimään, ovat löytyneet. Katso, isäsi on heittänyt mielestään aasintammat, kun on levoton tähtenne ja sanoo: Mitä teen poikani avuksi?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Kun menet edemmäksi ja tulet Taaborin tammelle, siellä tulee sinua vastaan kolme miestä menossa Jumalan eteen Beeteliin. Yksi kantaa kolmea kiliä, toinen kantaa kolmea leipäkakkua, ja kolmas kantaa viinileiliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'He tervehtivät sinua ja antavat sinulle kaksi leipää. Ota ne heiltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Sen jälkeen tulet Jumalan kukkulalle, missä on filistealaisten leiri. Tullessasi kaupunkiin kohtaat joukon profeettoja, jotka tulevat alas uhrikukkulalta profetoiden, harppu, tamburiini, huilu ja lyyra edellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Herran Henki tulee sinuun, ja sinäkin profetoit niin kuin hekin. Sinä muutut toiseksi mieheksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Kun nämä ennusmerkit käyvät toteen, niin tee, mikä tehtäväksesi tulee, sillä Jumala on kanssasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Mene sitten edelläni Gilgaliin, niin tulen sinne luoksesi uhraamaan polttouhreja ja rauhanuhreja. Odota seitsemän päivää, kunnes tulen luoksesi ja ilmoitan sinulle, mitä sinun on tehtävä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Kun hän käänsi selkänsä lähteäkseen Samuelin luota, Jumala muutti hänen sydämensä, ja kaikki nämä ennusmerkit kävivät sinä päivänä toteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Kun he tulivat sinne kukkulalle, katso, joukko profeettoja tuli häntä vastaan. Silloin Jumalan Henki tuli häneen, ja hänkin profetoi heidän keskellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Kun kaikki, jotka ennestään tunsivat hänet, näkivät hänen profetoivan niin kuin profeetat, he sanoivat toisilleen: \"Mikä Kiisin pojalle on tullut? Onko Saulkin profeettojen joukossa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Mutta eräs sikäläisistä miehistä vastasi ja sanoi: \"Kuka sitten heidän isänsä on?\" – Niin tuli sananlaskuksi: \"Onko Saulkin profeettojen joukossa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Lopetettuaan profetoimisen hän meni uhrikukkulalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Saulin setä kysyi häneltä ja hänen palvelijaltaan: \"Missä olette käyneet?\" Hän vastasi: \"Aasintammoja etsimässä. Mutta kun emme niitä missään nähneet, menimme Samuelin luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Saulin setä sanoi: \"Kerro minulle, mitä Samuel teille sanoi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Saul vastasi sedälleen: \"Hän ilmoitti meille aasintammojen löytyneen.\" Mutta sitä, mitä Samuel oli sanonut kuninkuudesta, hän ei hänelle kertonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Sitten Samuel kutsui kansan koolle Herran eteen Mispaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'Hän sanoi israelilaisille: \"Näin sanoo Herra, Israelin Jumala: Minä johdatin Israelin Egyptistä, ja vapautin teidät egyptiläisten käsistä sekä kaikkien niiden valtakuntien käsistä, jotka teitä sortivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Mutta nyt te olette pitäneet halpana Jumalanne, joka on auttanut teidät kaikista onnettomuuksistanne ja ahdingoistanne, ja olette sanoneet hänelle: \'Aseta meille kuningas.\' Asettukaa siis Herran eteen sukukunnittain ja suvuittain.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Samuel antoi kaikkien Israelin sukukuntien astua esiin, ja arpa osui Benjaminin sukukuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Kun hän sitten antoi Benjaminin sukukunnan astua esiin suvuittain, arpa osui Matrin sukuun. Sen jälkeen osui arpa Sauliin, Kiisin poikaan. Mutta kun häntä etsittiin, häntä ei löydetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'He kysyivät vielä kerran Herralta: \"Onko ketään muuta vielä tullut tänne?\" Herra vastasi: \"Katso, hän on piiloutunut kuormastoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Niin he juoksivat ja toivat hänet sieltä, ja kun hän asettui kansan keskelle, hän oli päätään pitempi kaikkea kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Samuel sanoi kaikelle kansalle: \"Näettekö, kenet Herra on valinnut, sillä ei ole hänen vertaistaan koko kansan joukossa.\" Koko kansa riemuitsi huutaen: \"Eläköön kuningas!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Samuel julisti kansalle kuninkuuden oikeudet, kirjoitti ne kirjaan ja asetti sen Herran eteen. Sitten Samuel päästi kaiken kansan menemään, kunkin kotiinsa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Myös Saul meni kotiinsa Gibeaan, ja hänen kanssaan lähti sotaväki, ne, joiden sydämiä Jumala oli koskettanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Mutta kelvottomat miehet sanoivat: \"Mitä apua meille on tästä?\" He halveksivat häntä eivätkä tuoneet hänelle mitään lahjoja, mutta hän oli ääneti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Ammonilainen Naahas meni ylös ja piiritti Gileadin Jaabesta. Niin kaikki Jaabeksen miehet sanoivat Naahaalle: \"Tee liitto kanssamme, niin palvelemme sinua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Mutta ammonilainen Naahas vastasi heille: \"Sillä ehdolla teen liiton kanssanne, että saan puhkaista jokaiselta teiltä oikean silmän ja tuottaa koko Israelille häpeän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Jaabeksen vanhimmat sanoivat hänelle: \"Jätä meidät rauhaan seitsemäksi päiväksi, niin lähetämme sanansaattajia kaikkialle Israelin alueelle. Ellei kukaan meitä auta, antaudumme sinulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Sanansaattajat tulivat Saulin Gibeaan ja puhuivat asian kansalle. Kaikki kansa korotti äänensä ja itki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Katso, Saul tuli kävellen härkien perässä pellolta. Saul kysyi: \"Mikä kansalla on, kun he itkevät?\" He kertoivat hänelle Jaabeksen miesten asian.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Kun Saul kuuli nämä sanat, Jumalan Henki tuli häneen, ja hän vihastui kovin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Hän otti härkäparin, paloitteli härät ja lähetti kappaleet kaikkialle Israelin alueelle sanansaattajien mukana ja käski sanoa: \"Näin tehdään jokaisen härille, joka ei seuraa Saulia ja Samuelia.\" Herran kauhu valtasi kansan, niin että he lähtivät yhtenä miehenä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Hän piti katselmuksen heistä Besekissä. Iraelilaisia oli kolmesataa tuhatta ja Juudan miehiä kolmekymmentä tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'He sanoivat sanansaattajille, jotka olivat tulleet: \"Sanokaa näin Gileadin Jaabeksen miehille: \'Huomenna auringon ollessa polttavimmillaan te saatte apua.\'\" Sanansaattajat tulivat ja ilmoittivat sen Jaabeksen miehille, ja nämä ilahtuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Jaabeksen miehet sanoivat: \"Huomenna tulemme ulos luoksenne, ja te saatte tehdä meille, mitä hyväksi näette.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Seuraavana päivänä Saul jakoi kansan kolmeen joukkoon, ja he tunkeutuivat leiriin aamuvartion aikana ja voittivat ammonilaiset surmaten heitä, kunnes päivä tuli palavimmilleen. Jäljelle jääneet hajaantuivat, niin ettei heistä jäänyt kahta yhteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Kansa sanoi Samuelille: \"Ketkä olivat ne, jotka sanoivat: \'Saulko tulisi meidän kuninkaaksemme?\' Antakaa tänne ne miehet surmataksemme heidät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Mutta Saul sanoi: \"Tänä päivänä ei ketään surmata, sillä tänä päivänä Herra on antanut voiton Israelille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Samuel sanoi kansalle: \"Tulkaa, menkäämme Gilgaliin ja uudistakaamme siellä kuninkuus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Kaikki kansa meni Gilgaliin ja teki Saulin kuninkaaksi siellä, Herran edessä Gilgalissa, ja he uhrasivat siellä rauhanuhreja Herran edessä. Saul ja kaikki Israelin miehet iloitsivat siellä suuresti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Samuel sanoi kaikelle Israelille: \"Katso, minä olen kuullut teidän ääntänne kaikessa, mitä olette minulle sanoneet, ja olen asettanut kuninkaan teitä hallitsemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Nyt teidän kuninkaanne on käyvä teidän edellänne, kun minä olen tullut vanhaksi ja harmaaksi – ovathan jo poikani kanssanne. Mutta minä olen käynyt edellänne nuoruudestani tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Katso, tässä minä olen. Todistakaa minua vastaan Herran ja hänen voideltunsa edessä. Keneltä olen vienyt härän tai keneltä aasin? Kenelle olen tehnyt vääryyttä, kenelle väkivaltaa? Keneltä olen ottanut lahjuksia ummistaakseni silmäni hänen hyväkseen? Todistakaa, niin korvaan sen teille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'He vastasivat: \"Et ole tehnyt meille vääryyttä etkä väkivaltaa, et ole myöskään ottanut keneltäkään mitään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Hän sanoi heille: \" Herra on todistaja teitä vastaan, ja hänen voideltunsa on todistaja tänä päivänä, että te ette ole löytäneet mitään kädestäni.\" He vastasivat: \"Hän on todistaja.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Samuel sanoi kansalle: \"Todistaja on Herra, joka kutsui Mooseksen ja Aaronin ja johdatti isänne Egyptin maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Astukaa nyt esiin, minä haastan teidät tuomiolle Herran edessä kaikista Herran vanhurskaista teoista, jotka hän on teille ja isillenne tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Kun Jaakob oli tullut Egyptiin, isänne huusivat avuksi Herraa, ja Herra lähetti Mooseksen ja Aaronin viemään isänne pois Egyptistä ja sijoittamaan heidät tähän paikkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Mutta he unohtivat Herran, Jumalansa, ja hän myi heidät Siiseran, Haasorin sotapäällikön, käsiin ja filistealaisten käsiin ja Mooabin kuninkaan käsiin, ja nämä sotivat heitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'He huusivat avuksi Herraa ja sanoivat: \'Me olemme tehneet syntiä, kun hylkäsimme Herran ja palvelimme baaleja ja astarteja. Mutta vapauta nyt meidät vihollistemme käsistä, niin palvelemme sinua.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Sitten Herra lähetti Jerubbaalin, Bedanin, Jeftan ja Samuelin ja vapautti teidät ympärillä asuvien vihollistenne käsistä, niin että saitte asua turvassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Mutta kun näitte Naahaan, ammonilaisten kuninkaan, hyökkäävän teitä vastaan, te sanoitte minulle: \'Ei, vaan kuningas hallitkoon meitä\', vaikka Herra, Jumalanne, on kuninkaanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Tässä on nyt kuningas, jonka te valitsitte ja jota anoitte: katso, Herra on antanut teille kuninkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Jos te pelkäätte Herraa ja palvelette häntä, kuulette hänen ääntään ettekä niskoittele hänen käskyjään vastaan, niin te seuraatte Herraa, Jumalaanne, sekä te että kuningas, joka teitä hallitsee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Mutta ellette kuule Herran ääntä, vaan niskoittelette hänen käskyjään vastaan, Herran käsi on oleva teitä vastaan, niin kuin oli myös isiänne vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Astukaa nyt esiin ja katsokaa tätä suurta tekoa, jonka Herra tekee teidän silmienne edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Nythän on vehnänleikkuun aika. Mutta huudan Herraa, että hän antaa ukkosenjylinän ja sateen, että ymmärtäisitte ja näkisitte, kuinka paha Herran silmissä on se, minkä olette tehneet anoessanne itsellenne kuningasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Samuel huusi Herraa, ja Herra antoi ukkosenjylinän ja sateen sinä päivänä. Kaikki kansa pelkäsi suuresti Herraa ja Samuelia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Kaikki kansa sanoi Samuelille: \"Rukoile palvelijoittesi puolesta Herraa, Jumalaasi, ettemme kuolisi. Sillä olemme tehneet kaikkien muiden syntiemme lisäksi senkin pahan, että anoimme itsellemme kuninkaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Samuel sanoi kansalle: \"Älkää pelätkö. Te olette tosin tehneet kaiken tämän pahan, mutta älkää kuitenkaan poiketko pois seuraamasta Herraa, vaan palvelkaa Herraa kaikesta sydämestänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Älkää poiketko seuraamaan turhia jumalia, joista ei ole hyötyä eikä apua, sillä turhia ne ovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Suuren nimensä tähden Herra ei hylkää kansaansa, koska Herra on tahtonut tehdä teidät omaksi kansakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Pois se minusta, että tekisin sen synnin Herraa vastaan, että lakkaisin rukoilemasta puolestanne ja opettamasta teille hyvää ja oikeaa tietä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Pelätkää vain Herraa ja palvelkaa häntä uskollisesti kaikesta sydämestänne. Sillä katsokaa, kuinka suuria hän on teille tehnyt');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Mutta jos teette pahaa, niin hukutte, sekä te itse että teidän kuninkaanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Saul oli ollut vuoden kuninkaana ja hallitsi Israelia toista vuotta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'kun Saul valitsi itselleen kolmetuhatta miestä Israelista. Näistä oli kaksituhatta Saulin kanssa Mikmaassa ja Beetelin vuoristossa, ja tuhat Joonatanin kanssa Benjaminin Gibeassa. Mutta muun väen hän oli päästänyt menemään, kunkin telttamajalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Mutta Joonatan, Saulin poika, löi kuoliaaksi filistealaisten maaherran, joka asui Gebassa, ja filistealaiset saivat kuulla sen. Silloin Saul puhallutti torveen kaikkialla maassa ja käski sanoa: \"Heprealaiset kuulkoot tämän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Koko Israel kuuli sen sanoman, että Saul oli lyönyt kuoliaaksi filistealaisten maaherran ja että Israel oli joutunut filistealaisten vihoihin. Kansa kutsuttiin koolle Gilgaliin seuraamaan Saulia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Sillä filistealaiset olivat kokoontuneet sotimaan Israelia vastaan: kolmekymmentä tuhatta sotavaunua, kuusituhatta ratsumiestä ja muuta väkeä niin paljon kuin hiekkaa meren rannalla. He nousivat ylös ja leiriytyivät Mikmaaseen, vastapäätä Beet-Aavenia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Kun Israelin miehet näkivät joutuneensa hätään ja kansaa ahdistettavan, he piiloutuivat luoliin, onkaloihin, kalliorotkoihin, hautoihin ja kaivoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Heprealaisia meni myös Jordanin yli Gaadiin ja Gileadin maahan. Mutta Saul oli vielä Gilgalissa, ja kaikki sotaväki seurasi häntä peloissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Kun hän oli odottanut seitsemän päivää, sen ajan, jonka Samuel oli määrännyt, eikä Samuel tullutkaan Gilgaliin, kansa alkoi hajaantua pois hänen luotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Silloin Saul sanoi: \"Tuokaa minulle polttouhri ja rauhanuhri.\" Sitten hän uhrasi polttouhrin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Mutta juuri kun hän oli saanut polttouhrin uhratuksi, katso, Samuel tuli. Saul meni häntä vastaan tervehtimään häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Mutta Samuel sanoi: \"Mitä olet tehnyt?\" Saul vastasi: \"Kun näin, että kansa hajaantui pois luotani etkä sinä tullut määräaikaan mennessä, vaikka filistealaiset olivat kokoontuneet Mikmaaseen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'niin ajattelin: nyt filistealaiset hyökkäävät minua vastaan alas Gilgaliin, enkä minä ole etsinyt Herran mielisuosiota. Minä rohkaisin itseni ja uhrasin polttouhrin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Samuel sanoi Saulille: \"Sinä olet tehnyt tyhmästi. Et ole noudattanut Herran, Jumalasi, käskyä, jonka hän antoi sinulle. Muuten Herra olisi vahvistanut sinun kuninkuutesi Israelissa ikiajoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Mutta nyt kuninkuutesi ei ole pysyvä. Herra on etsinyt itselleen mielensä mukaisen miehen, ja hänet Herra on määrännyt kansansa ruhtinaaksi, koska sinä et noudattanut käskyä, minkä Herra sinulle antoi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Samuel nousi ja meni Gilgalista Benjaminin Gibeaan. Saul piti mukanaan olevan väen katselmuksen: noin kuusisataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Saul ja hänen poikansa Joonatan sekä väki, joka oli heidän kanssaan, jäivät Benjaminin Gebaan, mutta filistealaiset olivat leiriytyneet Mikmaaseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Filistealaisten leiristä lähti ryöstöosasto kolmena joukkona: yksi joukko kääntyi Ofran tielle Suualin maahan päin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'toinen joukko kääntyi Beet-Hooronin tielle, ja kolmas joukko kääntyi sille tielle, joka vie Seboimin laakson yli kohoavalle alueelle erämaahan päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Mutta yhtään seppää ei ollut löydettävissä koko Israelin maasta, sillä filistealaiset ajattelivat, että muuten heprealaiset teettäisivät miekkoja tai keihäitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Koko Israelin, joka miehen, oli mentävä filistealaisten luo taotuttamaan auran vannastaan, kuokkaansa, kirvestään tai muuta teräkaluaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'kun auran vannasten, kuokkien, talikkojen tai kirvesten terät olivat tylsyneet, tai kun häränpistimen tutkain oli oikaistava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Niinpä taistelupäivänä ei ollut yhtään miekkaa eikä keihästä kenelläkään siitä väestä, joka oli Saulin ja Joonatanin kanssa. Ainoastaan Saulilla ja hänen pojallaan Joonatanilla oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Mutta filistealaisten vartiosto lähti Mikmaan solatielle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Eräänä päivänä tapahtui, että Joonatan, Saulin poika, sanoi palvelijalle, joka kantoi hänen aseitaan: \"Tule, menkäämme lähelle filistealaisten vartiostoa, joka on tuolla toisella puolella.\" Mutta isälleen hän ei ilmoittanut sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Saul istui granaattiomenapuun juurella Migronissa Gibean rajalla, ja väkeä oli hänen kanssaan noin kuusisataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Kasukankantajana oli Ahia, Ahitubin, Iikabodin veljen, poika, joka oli Piinehaan poika, joka Eelin poika, sen, joka oli ollut Herran pappina Siilossa. Mutta kansa ei tiennyt, että Joonatan oli lähtenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Kummallakin puolen solatietä, jota Joonatan koetti mennä lähelle filistealaisten vartiostoa, oli jyrkkä kallionkieleke. Toisen nimi on Booses, toisen Sene.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Toinen kallionkieleke on kuin pylväs, pohjoispuolella, Mikmaaseen päin, toinen on eteläpuolella, Gebaan päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Joonatan sanoi palvelijalle, joka kantoi hänen aseitaan: \"Tule, menkäämme lähelle noiden ympärileikkaamattomien vartiostoa. Ehkä Herra on tekevä jotain puolestamme, sillä ei mikään estä Herraa antamasta voittoa harvojen kautta yhtä hyvin kuin monien.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Hänen aseenkantajansa vastasi hänelle: \"Tee, mitä mielessäsi on. Lähde, seuraan sinua mielesi mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Joonatan sanoi: \"Katso, me menemme tuonne lähelle noita miehiä, ja näyttäydymme heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Jos he sanovat meille näin: \'Olkaa hiljaa, kunnes tulemme luoksenne\', niin seisomme alallamme emmekä lähde nousemaan heidän luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Mutta jos he sanovat näin: \'Nouskaa tänne meidän luoksemme\', niin nousemme, sillä silloin Herra on antanut heidät käsiimme. Tämä olkoon meille merkkinä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Kun he molemmat tulivat sitten filistealaisten vartioston näkyviin, filistealaiset sanoivat: \"Katso, heprealaiset tulevat esiin koloistaan, joihin ovat piiloutuneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Vartioston miehet huusivat Joonatanille ja hänen aseenkantajalleen ja sanoivat: \"Nouskaa tänne luoksemme, niin me ilmoitamme teille jotakin.\" Silloin Joonatan sanoi aseenkantajalleen: \"Nouse minun perässäni, sillä Herra on antanut heidät Israelin käsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Niin Joonatan kiipesi käsin ja jaloin ylöspäin, ja aseenkantaja hänen perässään. Silloin he kaatuivat Joonatanin edessä, ja aseenkantaja surmasi heidät hänen jäljessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'Tässä ensimmäisessä kahakassa Joonatan ja hänen aseenkantajansa surmasivat noin kaksikymmentä miestä, noin puolen auranalan suuruisella maa-alalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Silloin syntyi kauhu leirissä ja sen ulkopuolella koko sotaväessä. Myös vartiosto ja ryöstöosasto joutuivat kauhun valtaan. Maakin järisi, ja niin syntyi Jumalan kauhu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Saulin tähystäjät Benjaminin Gibeassa huomasivat lauman hajoavan ja menevän sinne tänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Niin Saul sanoi väelle, joka oli hänen kanssaan: \"Pitäkää katselmus ja katsokaa, kuka on mennyt pois luotamme.\" Kun katselmus pidettiin, huomattiin, etteivät Joonatan ja hänen aseenkantajansa olleet läsnä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Saul sanoi Ahialle: \"Tuo tänne Jumalan arkki.\" Sillä Jumalan arkki oli siihen aikaan israelilaisten hallussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Mutta Saulin vielä puhutellessa pappia kävi meteli filistealaisten leirissä yhä suuremmaksi. Saul sanoi papille: \"Jätä sikseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Saul kutsui koolle kaiken väen, joka oli hänen kanssaan, ja he tulivat taistelupaikalle, ja katso, toisen miekka oli toista vastaan, ja oli mitä suurin hämminki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Myös ne heprealaiset, jotka ennestään olivat filistealaisten vallassa ja jotka olivat tulleet heidän kanssaan ja olivat leirissä, menivät niiden israelilaisten puolelle, jotka olivat Saulin ja Joonatanin kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Kun sitten ne Israelin miehet, jotka olivat piiloutuneet Efraimin vuoristoon, kuulivat filistealaisten pakenevan, hekin yhtyivät kaikki ajamaan heitä takaa taistelussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Herra antoi Israelille voiton sinä päivänä, ja taistelu levisi Beet-Aavenin toiselle puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Israelin miehet olivat sinä päivänä hyvin rasitettuja, mutta Saul vannotti kansan ja sanoi: \"Kirottu olkoon mies, joka syö mitään ennen iltaa ja ennen kuin olen kostanut vihollisilleni.\" Koko kansa oli ruokaa maistamatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Kun he kaikki sitten tulivat metsään, maassa oli hunajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Kun kansa tuli kennokakkujen ääreen, niin, katso, niistä vuoti hunajaa, mutta kukaan ei vienyt kättään suuhun, sillä kansa pelkäsi valaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Mutta Joonatan ei ollut kuulemassa, kun hänen isänsä vannotti kansan. Niin hän ojensi sauvan, joka oli hänen kädessään, pisti sen kärjen kennokakkuun ja vei sitten kätensä suuhunsa, ja silloin hänen silmänsä kirkastuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Mutta eräs mies väestä puhkesi puhumaan ja sanoi: \"Sinun isäsi vannotti väen ja sanoi: \'Kirottu olkoon se mies, joka tänä päivänä syö jotakin.\" Mutta väki oli näännyksissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Joonatan vastasi: \"Isäni on syössyt maan onnettomuuteen. Katsokaa, kuinka silmäni kirkastuivat, kun vähän maistoin tätä hunajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Jos myös väki olisi tänä päivänä saanut syödä vihollisiltaan ottamaansa saalista, niin eiköhän filistealaisten tappio olisi ollut vieläkin suurempi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'He voittivat sinä päivänä filistealaiset ja ajoivat heitä takaa Mikmaasta Aijaloniin asti. Mutta väki oli kovin näännyksissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Sen tähden väki syöksyi saaliin kimppuun ja otti lampaita, nautoja ja vasikoita ja teurasti niitä paljaan maan päällä, ja väki söi lihan verineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Niin Saulille ilmoitettiin tämä: \"Katso, väki tekee syntiä Herraa vastaan, kun syö lihaa verineen.\" Hän sanoi: \"Te olette menetelleet uskottomasti. Vierittäkää nyt minun eteeni tänne suuri kivi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Sitten Saul sanoi: \"Menkää väen sekaan ja sanokaa heille: \'Tuokaa kukin härkänne ja lampaanne luokseni ja teurastakaa ne täällä. Sitten syökää, älkääkä tehkö syntiä Herraa vastaan syömällä lihaa verineen.\'\" Väestä jokainen toi silloin yöllä omin käsin härkänsä ja teurasti sen siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Saul rakensi alttarin Herralle. Tämä oli ensimmäinen alttari, jonka hän Herralle rakensi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Sitten Saul sanoi: \"Lähtekäämme tänä yönä filistealaisten perään ja ryöstäkäämme heitä, kunnes aamu valkenee. Älkäämme jättäkö heistä jäljelle ainoatakaan.\" He vastasivat: \"Tee kaikki, mitä hyväksi näet.\" Mutta pappi sanoi: \"Astukaamme tänne Jumalan eteen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Silloin Saul kysyi Jumalalta: \"Lähdenkö filistealaisten perään? Annatko sinä heidät Israelin käsiin?\" Mutta hän ei vastannut hänelle sinä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Niin Saul sanoi: \"Tulkaa tänne, kaikki kansan päämiehet, saadaksenne tietää ja nähdä, mikä synti nyt on tähän syynä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Sillä niin totta kuin Herra elää, hän, joka on antanut Israelille voiton: vaikka syy olisi minun poikani Joonatanin, hänen on kuoltava.\" Mutta ei kukaan koko kansasta vastannut hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Silloin hän sanoi koko Israelille: \"Olkaa te toisella puolella, niin minä ja poikani Joonatan olemme toisella puolella.\" Kansa vastasi Saulille: \"Tee, kuten hyväksi näet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Saul sanoi Herralle, Israelin Jumalalle: \"Anna oikea arpa.\" Niin arpa osui Joonataniin ja Sauliin, ja kansa pääsi vapaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Saul sanoi: \"Heittäkää arpaa minun ja poikani Joonatanin välillä.\" Niin arpa osui Joonataniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Saul sanoi Joonatanille: \"Ilmaise minulle, mitä olet tehnyt.\" Joonatan ilmaisi sen hänelle ja sanoi: \"Minä maistoin vähän hunajaa sauvan kärjellä, joka oli kädessäni. Katso, minä olen valmis kuolemaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Saul sanoi: \"Jumala rangaiskoon minua nyt ja vasta: sinun on totisesti kuoltava, Joonatan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Mutta kansa sanoi Saulille: \"Onko Joonatanin kuoltava, hänen, joka on hankkinut tämän suuren voiton Israelille? Pois se! Niin totta kuin Herra elää: hiuskarvakaan ei saa pudota maahan hänen päästään, sillä Jumalan avulla hän on sen tänä päivänä tehnyt.\" Ja kansa vapautti Joonatanin kuolemasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Sitten Saul lähti eikä ajanut filistealaisia takaa, ja filistealaiset menivät kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Kun Saul oli nyt saanut kuninkuuden Israelissa, hän soti kaikkia vihollisiaan vastaan joka taholla: mooabilaisia, ammonilaisia, edomilaisia, Sooban kuninkaita ja filistealaisia vastaan, ja minne tahansa hän kääntyi, siellä hän rankaisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Hän teki väkeviä tekoja ja voitti amalekilaiset ja vapautti Israelin sen ryöstäjien käsistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Saulin pojat olivat Joonatan, Jisvi ja Malkisua, ja hänen kahden tyttärensä nimet olivat: vanhemman nimi Meerab ja nuoremman nimi Miikal.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Saulin vaimon nimi oli Ahinoam, Ahimaan tytär. Hänen sotapäällikkönsä nimi oli Abner, Neerin, Saulin sedän, poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Sillä Kiis, Saulin isä, ja Neer, Abnerin isä, olivat Abielin poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Filistealaisia vastaan käytiin kiivaasti sotaa, niin kauan kuin Saul eli. Kenet vain, urhoollisen ja sotakuntoisen miehen, Saul tapasi, sen hän otti luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Mutta Samuel sanoi Saulille: \"Minut Herra lähetti voitelemaan sinut kansansa Israelin kuninkaaksi. Kuule siis Herran ääntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Näin sanoo Herra Sebaot: Kostan Amalekille sen, mitä hän teki Israelille asettumalla hänen tielleen, kun hän tuli Egyptistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Mene siis ja voita amalekilaiset. Vihkikää tuhon omaksi kaikki, mitä heillä on, älä säästä heitä, vaan surmaa miehet ja naiset, lapset ja imeväiset, naudat ja lampaat, kamelit ja aasit.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Saul kuulutti kansan kokoon ja piti heistä katselmuksen Telaimissa: kaksisataa tuhatta jalkamiestä sekä kymmenentuhatta Juudan miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Kun Saul tuli lähelle amalekilaisten kaupunkia, hän asettui laaksoon väijyksiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Silloin Saul sanoi keeniläisille: \"Tulkaa, erotkaa ja siirtykää pois amalekilaisten joukosta, etten hukuttaisi teitä heidän kanssaan. Sillä te teitte laupeuden kaikille israelilaisille, kun he tulivat Egyptistä.\" Niin keeniläiset erosivat amalekilaisista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Saul voitti amalekilaiset ja ajoi heitä takaa Havilasta Suuriin päin, joka on Egyptistä itään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Hän otti Agagin, Amalekin kuninkaan, elävänä vangiksi, mutta kaiken kansan hän vihki tuhon omaksi miekan terällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Saul ja väki säästivät Agagin sekä parhaat lampaat, lihavimmat naudat ja karitsat, kaiken, mikä oli arvokasta. Sitä he eivät tahtoneet vihkiä tuhon omaksi. Mutta kaiken karjan, mikä oli halpaa ja arvotonta, he vihkivät tuhon omaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Silloin Samuelille tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, '\"Kadun, että tein Saulin kuninkaaksi, sillä hän on kääntynyt minusta pois eikä ole täyttänyt käskyjäni.\" Samuel pahastui, ja hän huusi Herraa koko sen yön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Varhain seuraavana aamuna Samuel lähti tapaamaan Saulia. Samuelille ilmoitettiin: \"Saul on mennyt Karmeliin ja pystyttänyt sinne itselleen muistomerkin. Hän on palannut sieltä ja mennyt alas Gilgaliin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Kun Samuel tuli Saulin luo, Saul sanoi hänelle: \" Herra siunatkoon sinua! Minä olen täyttänyt Herran käskyn.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Mutta Samuel sanoi: \"Mitä tämä lammasten määkiminen on, joka kuuluu korviini, ja tämä nautojen ammuminen, jonka kuulen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Saul vastasi: \"Amalekilaisilta ne on tuotu, sillä kansa säästi parhaat lampaat ja naudat uhratakseen ne Herralle, sinun Jumalallesi, mutta muut olemme vihkineet tuhon omiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Samuel sanoi Saulille: \"Lopeta! Ilmoitan sinulle, mitä Herra on minulle tänä yönä puhunut.\" Tämä sanoi hänelle: \"Puhu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Samuel sanoi: \"Sinä olet Israelin sukukuntien päämies, vaikka oletkin vähäinen omissa silmissäsi: Herra on voidellut sinut Israelin kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Herra lähetti sinut matkaan ja sanoi: \'Mene ja vihi tuhon omiksi nämä syntiset, amalekilaiset, ja sodi heitä vastaan, kunnes olet tehnyt heistä lopun.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Miksi et kuullut Herran ääntä, vaan syöksyit saaliin kimppuun ja teit sitä, mikä on pahaa Herran silmissä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Saul vastasi Samuelille: \"Minähän olen kuullut Herran ääntä ja tehnyt sen matkan, jolle Herra minut lähetti. Minä olen tuonut tänne Agagin, Amalekin kuninkaan, ja vihkinyt amalekilaiset tuhon omiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Mutta väki on ottanut saaliista lampaita ja nautoja, parhaan osan siitä, mikä oli vihitty tuhon omaksi, uhratakseen ne Herralle, sinun Jumalallesi, Gilgalissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Silloin Samuel sanoi: \"Haluaako Herra polttouhreja ja teurasuhreja yhtä paljon kuin kuuliaisuutta Herran äänelle? Katso, kuuliaisuus on parempi kuin uhri ja tottelevaisuus parempi kuin pässien rasva');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Sillä tottelemattomuus on taikuuden syntiä, ja niskoittelu on valhetta ja kuin kotijumalien palvomista. Koska olet hylännyt Herran sanan, hänkin on hylännyt sinut, etkä saa olla kuninkaana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Saul sanoi Samuelille: \"Minä olen tehnyt syntiä, kun olen rikkonut Herran käskyn ja sanasi. Sillä minä pelkäsin kansaa ja kuulin heidän ääntään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Anna nyt minulle anteeksi syntini ja palaa kanssani, niin kumartaen rukoilen Herraa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Samuel sanoi Saulille: \"Minä en palaa kanssasi, sillä sinä olet hylännyt Herran sanan, ja Herra on myös hylännyt sinut, niin että et enää saa olla Israelin kuninkaana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Kun Samuel kääntyi menemään pois, Saul tarttui hänen viittansa liepeeseen, niin että se repesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Samuel sanoi hänelle: \" Herra on tänä päivänä repäissyt Israelin kuninkuuden sinulta ja antanut sen toiselle, joka on sinua parempi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Hän, joka on Israelin kunnia, ei valehtele eikä kadu, sillä hän ei ole ihminen, että hän katuisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Hän vastasi: \"Minä olen tehnyt syntiä. Mutta osoita minulle kuitenkin se kunnia kansani vanhimpien edessä ja Israelin edessä, että palaat kanssani, niin minä kumartaen rukoilen Herraa, Jumalaasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Samuel palasi Saulin jäljessä, ja Saul kumartaen rukoili Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Samuel sanoi: \"Tuokaa eteeni Agag, Amalekin kuningas.\" Agag tuli iloisesti hänen eteensä, ja Agag sanoi: \"Totisesti on katkera kuolema väistynyt pois.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Samuel sanoi: \"Niin kuin miekkasi on tehnyt vaimoja lapsettomiksi, on myös äitisi tuleva lapsettomaksi ennen muita vaimoja.\" Samuel hakkasi Agagin kappaleiksi Herran edessä Gilgalissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Samuel lähti Raamaan, mutta Saul meni kotiinsa Saulin Gibeaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Eikä Samuel enää nähnyt Saulia kuolinpäiväänsä asti, ja Samuel suri Saulia. Mutta Herra katui, että oli tehnyt Saulin Israelin kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Herra sanoi Samuelille: \"Kuinka kauan sinä suret Saulia? Minähän olen hylännyt hänet, niin ettei hän saa enää olla Israelin kuninkaana. Täytä sarvesi öljyllä ja mene. Lähetän sinut beetlehemiläisen Iisain luo, sillä hänen pojistaan olen katsonut itselleni kuninkaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Mutta Samuel sanoi: \"Kuinka menen sinne? Jos Saul saa sen kuulla, hän tappaa minut.\" Herra vastasi: \"Ota mukaasi vasikka ja sano: \'Minä tulin uhraamaan Herralle.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Kutsu sitten Iisai uhrille, niin minä ilmoitan sinulle, mitä sinun on tehtävä, ja voitele minulle se, jonka sinulle sanon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Samuel teki, kuten Herra oli puhunut. Mutta kun hän saapui Beetlehemiin, kaupungin vanhimmat tulivat vavisten häntä vastaan ja kysyivät: \"Tietääkö tulosi rauhaa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Hän vastasi: \"Rauhaa. Minä olen tullut uhraamaan Herralle. Pyhittäytykää ja tulkaa kanssani uhrille.\" Niin hän pyhitti Iisain ja hänen poikansa ja kutsui heidät uhrille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Kun he tulivat ja hän näki Eliabin, hän ajatteli: \"Varmaan tässä on nyt Herran edessä hänen voideltunsa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Mutta Herra sanoi Samuelille: \"Älä katso hänen näköään äläkä kookasta vartaloaan, sillä olen hänet hylännyt. Sillä ei ole, niin kuin ihminen näkee: ihminen näkee ulkomuodon, mutta Herra näkee sydämen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Iisai kutsui Abinadabin ja toi hänet Samuelin eteen. Mutta hän sanoi: \"Ei ole Herra tätäkään valinnut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Silloin Iisai toi Samman esille. Mutta hän sanoi: \"Ei ole Herra tätäkään valinnut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Iisai toi seitsemän poikaansa Samuelin eteen. Mutta Samuel sanoi Iisaille: \" Herra ei ole valinnut näistä ketään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Samuel kysyi Iisailta: \"Siinäkö olivat kaikki nuorukaiset?\" Hän vastasi: \"Vielä on nuorin jäljellä, mutta hän on kaitsemassa lampaita.\" Samuel sanoi Iisaille: \"Lähetä noutamaan hänet, sillä emme istu ruualle, ennen kuin hän tulee tänne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Tämä haetti hänet, ja hän oli verevä, kaunissilmäinen ja komea näöltään. Herra sanoi: \"Nouse ja voitele tämä, sillä hän se on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Samuel otti öljysarven ja voiteli hänet hänen veljiensä keskellä. Herran Henki tuli Daavidiin siitä päivästä lähtien ja yhä edelleen. Samuel nousi ja meni Raamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Mutta Herran Henki poistui Saulista, ja Herran lähettämä paha henki vaivasi häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Saulin palvelijat sanoivat hänelle: \"Katso, Jumalan lähettämä paha henki vaivaa sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Käskeköön vain herramme, niin palvelijasi, jotka ovat edessäsi, etsivät miehen, joka osaa soittaa lyyraa, että hän, kun Jumalan lähettämä paha henki tulee sinuun, soittaisi sitä, ja sinun olisi parempi olla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Silloin Saul sanoi palvelijoilleen: \"Katsokaa minulle mies, joka on taitava soittaja, ja tuokaa hänet luokseni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Eräs nuorista miehistä vastasi ja sanoi: \"Katso, minä olen nähnyt beetlehemiläisellä Iisailla pojan, joka osaa soittaa ja joka on kunnon mies ja sotilas sekä ymmärtäväinen puheiltaan ja komea mies, ja Herra on hänen kanssaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Saul lähetti sanansaattajat Iisain luo ja käski sanoa: \"Lähetä luokseni poikasi Daavid, joka kaitsee lampaita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Iisai otti aasin sekä leipää, viinileilin ja kilin ja lähetti ne poikansa Daavidin mukana Saulille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Daavid tuli Saulin luo ja rupesi palvelemaan häntä. Hän tuli hänelle hyvin rakkaaksi ja pääsi hänen aseenkantajakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Saul lähetti sanan Iisaille ja käski sanoa: \"Anna Daavidin jäädä minua palvelemaan, sillä hän on saanut armon silmieni edessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Niin usein kuin Jumalan lähettämä henki tuli Sauliin, Daavid otti lyyran ja soitti sitä. Silloin Saulin oli helpompi ja parempi olla, ja paha henki väistyi hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Filistealaiset kokosivat joukkonsa sotaan ja kokoontuivat lähelle Sookoa, joka on Juudassa. He leiriytyivät Sookon ja Asekan välille, Efes-Dammimiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Saul ja Israelin miehet olivat myös kokoontuneet ja leiriytyneet Tammilaaksoon ja asettuivat rintamaan filistealaisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Filistealaiset olivat vuorella, joka oli toisella puolella, ja israelilaiset olivat vuorella, joka oli toisella puolella, ja laakso oli heidän välissään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Niin filistealaisten joukoista tuli kaksintaistelija nimeltä Goljat, kotoisin Gatista. Hän oli kuuden kyynärän ja vaaksan pituinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Hänellä oli vaskikypärä päässä ja suomuspanssari yllä. Rintahaarniska, joka painoi viisituhatta sekeliä, oli vaskea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Hänellä oli säärissään vaskisuojukset ja hartioillaan vaskikeihäs.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'Hänen peitsensä varsi oli kuin kangastukki, ja hänen peitsensä kärki, joka painoi kuusisataa sekeliä, oli rautaa. Kilvenkantaja kulki hänen edellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Hän astui esiin ja huusi Israelin taisteluriveille sanoen: \"Miksi te lähditte sotaan ja asetuitte sotarintaan? Minä olen filistealainen, ja te olette Saulin palvelijoita. Valitkaa joukostanne mies, joka tulee tänne alas luokseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Jos hän kykenee taistelemaan minua vastaan ja surmaa minut, olemme teidän palvelijanne. Mutta jos minä voitan ja surmaan hänet, te olette meidän palvelijoitamme ja palvelette meitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Vielä filistealainen sanoi: \"Minä olen tänä päivänä häväissyt Israelin taistelurivit. Antakaa tänne mies, niin taistelemme keskenämme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Kun Saul ja koko Israel kuuli nämä filistealaisen puheet, heidät valtasi kauhu, ja he pelkäsivät suuresti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'Mutta Daavid oli sen efratilaisen miehen poika Juudan Beetlehemistä, jonka nimi oli Iisai, ja tällä oli kahdeksan poikaa. Hän oli Saulin aikana jo vanha, iäkäs mies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Iisain kolme vanhinta poikaa oli seurannut Saulia sotaan. Näiden hänen kolmen sotaan lähteneen poikansa nimet olivat: esikoisen Eliab, toisen Abinadab ja kolmannen Samma.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'Daavid oli nuorin. Nuo kolme vanhinta olivat seuranneet Saulia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'Mutta Daavid kävi välillä Saulin luota Beetlehemissä kaitsemassa isänsä lampaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Niin filistealainen astui esiin haastaen taisteluun joka aamu ja ilta neljänäkymmenenä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Iisai sanoi pojalleen Daavidille: \"Ota veljillesi eefa-mitta näitä paahdettuja jyviä ja nämä kymmenen leipää, ja vie ne nopeasti leiriin veljillesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'Vie nämä kymmenen juustoa tuhannenpäällikölle. Tiedustele veljiesi vointia ja hanki varmuus, että lähetys on heille saapunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Saul, he sekä kaikki Israelin miehet ovat Tammilaaksossa sotimassa filistealaisia vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Varhain seuraavana aamuna Daavid jätti lampaat vartijan haltuun, otti kantamuksensa ja lähti matkalle, niin kuin Iisai oli häntä käskenyt. Kun hän tuli leiriin, sotaväki lähti taistelurintamaan ja nosti sotahuudon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Israel ja filistealaiset asettuivat rintamaan toisiaan vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Niin Daavid heitti tavarat selästään kuormaston vartijalle ja riensi rintamaan. Sinne tultuaan hän tervehti veljiään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Kun hän puhutteli heitä, niin, katso, kaksintaistelija, Goljat niminen filistealainen, kotoisin Gatista, tuli filistealaisten taisteluriveistä ja puhui kuten ennenkin, ja Daavid kuuli sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Kun israelilaiset näkivät miehen, he pakenivat häntä kaikki ja pelkäsivät suuresti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Israelin miehet sanoivat: \"Katsokaa miestä, joka tuolla tulee! Hän tulee häpäisemään Israelia. Mutta sen miehen, joka surmaa hänet, kuningas tekee hyvin rikkaaksi ja antaa hänelle tyttärensä ja tekee Israelissa hänen isänsä perheen vapaaksi veroista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Niin Daavid sanoi miehille, jotka seisoivat siinä hänen kanssaan: \"Mitä se mies saa, joka surmaa filistealaisen ja poistaa häväistyksen Israelista? Sillä mikä tuo ympärileikkaamaton filistealainen on häpäisemään elävän Jumalan taistelurivejä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Väki sanoi hänelle saman, minkä ennenkin: sen ja sen saa se mies, joka hänet surmaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Mutta kun hänen vanhin veljensä Eliab kuuli hänen puhuvan miesten kanssa, Eliab vihastui Daavidiin ja sanoi: \"Miksi sinä olet tullut tänne, ja kenelle olet jättänyt sen pienen lammaslauman siellä erämaassa? Minä tunnen julkeutesi ja pahan sisusi. Sinä olet tullut tänne katsomaan sotaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'Daavid vastasi: \"Mitä minä sitten olen tehnyt? Saaneehan tuon verran kysyä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Hän kääntyi hänen luotaan toisen puoleen ja kysyi kuten ennenkin, ja väki vastasi hänelle samoin kuin äsken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Niin tuli tunnetuksi, mitä Daavid oli puhunut, ja se kerrottiin Saulille, ja tämä noudatti hänet luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Daavid sanoi Saulille: \"Älköön kenenkään mieli masentuko hänen tähtensä. Palvelijasi käy taistelemaan tuota filistealaista vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Saul sanoi Daavidille: \"Et sinä voi mennä tuota filistealaista vastaan etkä taistella hänen kanssaan, sillä sinä olet nuorukainen, mutta hän on sotilas nuoruudestaan saakka.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Mutta Daavid sanoi Saulille: \"Palvelijasi on ollut kaitsemassa isänsä lampaita. Jos leijona tai karhu tuli ja vei lampaan laumasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'minä lähdin sen perään, löin sen maahan ja tempasin saaliin sen suusta. Jos se karkasi minua vastaan, tartuin sen partaan, löin sen maahan ja tapoin sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Kun palvelijasi on lyönyt maahan sekä leijonan että karhun, tuolle ympärileikkaamattomalle filistealaiselle käy kuten niille, sillä hän on häväissyt elävän Jumalan taistelurivejä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Sitten Daavid sanoi: \" Herra, joka on pelastanut minut leijonan ja karhun kynsistä, pelastaa minut myös tämän filistealaisen käsistä.\" Silloin Saul sanoi Daavidille: \"Mene, Herra olkoon kanssasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Saul puki takkinsa Daavidin ylle ja pani vaskikypärän hänen päähänsä sekä panssarin hänen ylleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Daavid sitoi hänen miekkansa vyölleen takin päälle ja yritti kävellä, sillä hän ei ollut koskaan sellaisia kokeillut. Niin Daavid sanoi Saulille: \"En minä voi näissä kulkea, sillä en ole koskaan tällaisia kokeillut.\" Daavid riisui ne päältään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Sitten hän otti käteen sauvansa, valitsi purosta viisi sileää kiveä, pani ne paimenlaukkuun, joka hänellä oli linkokivisäiliönä, otti lingon käteensä ja meni filistealaista vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Filistealainen tuli yhä lähemmäksi Daavidia, ja kilvenkantaja kulki hänen edellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Kun filistealainen katsoi ja näki Daavidin, hän halveksi häntä, sillä tämä oli vielä nuorukainen, verevä ja komea näöltään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Filistealainen sanoi Daavidille: \"Olenko minä koira, kun tulet sauva kädessä minua vastaan?\" Ja filistealainen kiroili Daavidia vannoen jumaliensa kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Filistealainen sanoi Daavidille: \"Tule tänne luokseni, ja annan lihasi taivaan linnuille ja metsän eläimille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Daavid sanoi filistealaiselle: \"Sinä tulet minua vastaan miekan, peitsen ja keihään voimalla, mutta minä tulen sinua vastaan Herran Sebaotin nimeen, Israelin sotajoukon Jumalan, jota olet häväissyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Tänä päivänä Herra antaa sinut käsiini, ja surmaan sinut, katkaisen sinulta pään ja annan filistealaisten sotajoukon ruumiit tänä päivänä taivaan linnuille ja metsän pedoille, ja kaikki maat tulevat tietämään, että Israelilla on Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'Koko tämä suuri joukko tulee tietämään, ettei Herra anna voittoa miekan eikä keihään voimalla, sillä sota on Herran, ja hän antaa teidät käsiimme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Kun filistealainen lähti tulemaan ja lähestyi Daavidia, niin Daavid juoksi nopeasti rintamaan filistealaista vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'Daavid pisti kätensä reppuunsa, otti sieltä kiven, linkosi ja osui filistealaista otsaan, niin että kivi upposi hänen otsaansa, ja hän kaatui maahan kasvoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Niin Daavid sai voiton filistealaisesta lingolla ja kivellä ja löi filistealaisen kuoliaaksi, eikä Daavidilla ollut miekkaa kädessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'Sitten Daavid juoksi ja asettui filistealaisen viereen, tarttui hänen miekkaansa, veti sen tupesta ja tappoi hänet ja löi sillä häneltä pään poikki. Kun filistealaiset näkivät, että heidän sankarinsa oli kuollut, he pakenivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Israelin ja Juudan miehet nousivat, nostivat huudon ja ajoivat filistealaisia takaa laakson suulle ja Ekronin porteille saakka. Filistealaisia kaatui surmattuina Saaraimin tiellä aina Gatiin ja Ekroniin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Israelilaiset palasivat ajamasta filistealaisia takaa ja ryöstivät heidän leirinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'Daavid otti filistealaisen pään ja vei sen Jerusalemiin, mutta hänen aseensa hän asetti telttaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Kun Saul oli nähnyt Daavidin menevän filistealaista vastaan, hän oli kysynyt sotapäälliköltään Abnerilta: \"Kenen poika tuo nuorukainen on, Abner?\" Abner vastasi: \"Niin totta kuin sinä, kuningas, elät, en sitä tiedä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Niin kuningas sanoi: \"Kysele sitten, kenen poika nuori mies on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Kun Daavid palasi takaisin surmattuaan filistealaisen, Abner otti hänet ja vei hänet Saulin eteen, ja hänellä oli kädessään filistealaisen pää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Niin Saul kysyi häneltä: \"Kenen poika sinä olet, nuorukainen?\" Daavid vastasi: \"Palvelijasi beetlehemiläisen Iisain poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Kun hän [Daavid] oli lakannut puhumasta Saulin kanssa, kiintyi Joonatan kaikesta sielustaan Daavidiin, ja Joonatan rakasti häntä kuin omaa sieluaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Saul otti hänet sinä päivänä luokseen eikä sallinut hänen enää palata isänsä kotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Joonatan teki liiton Daavidin kanssa, sillä hän rakasti häntä kuin omaa sieluaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Joonatan riisui viitan, joka hänellä oli yllään, ja antoi sen Daavidille, ja samoin takkinsa, vieläpä miekkansa, jousensa ja vyönsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Daavid lähti, minne vain Saul hänet lähetti, ja hän menestyi. Niin Saul asetti hänet sotamiesten päälliköksi, ja se oli mieleen kaikelle kansalle ja myös Saulin palvelijoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Kun he olivat tulossa, silloin kun Daavid palasi takaisin surmattuaan filistealaisen, menivät naiset kaikista Israelin kaupungeista laulaen ja karkeloiden kuningas Saulia vastaan, riemuiten, tamburiineja ja symbaaleja lyöden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Karkeloivat naiset virittivät laulun ja sanoivat: \"Saul voitti tuhat, mutta Daavid kymmenentuhatta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Saul vihastui kovin, sillä hän pani puheen pahakseen, ja sanoi: \"Daavidille he antavat kymmenen tuhatta, ja minulle he antavat tuhat. Nyt häneltä puuttuu enää vain kuninkuus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Saul katsoi karsain silmin Daavidia siitä päivästä alkaen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Seuraavana päivänä Jumalan lähettämä paha henki valtasi Saulin, niin että hän profetoi kotonaan, mutta Daavid soitteli, niin kuin muulloinkin joka päivä, ja Saulilla oli kädessään keihäs.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Niin Saul heitti keihään ja ajatteli: \"Minä keihästän Daavidin seinään.\" Mutta Daavid väisti häntä kaksi kertaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Saul pelkäsi Daavidia, koska Herra oli hänen kanssaan, mutta oli poistunut Saulista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Sen tähden Saul toimitti hänet pois luotaan ja teki hänet tuhannenpäämieheksi. Niin hän lähti ja tuli väen edellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'Daavid menestyi kaikilla teillään, ja Herra oli hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Kun Saul näki, että hänellä oli niin suuri menestys, rupesi hän häntä kammoamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Mutta koko Israel ja Juuda rakasti Daavidia, koska hän lähti ja tuli heidän edellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Saul sanoi Daavidille: \"Katso, vanhimman tyttäreni, Meerabin, annan sinulle vaimoksi. Ole vain urhoollinen ja käy Herran sotia.\" Sillä Saul ajatteli: \"Minun käteni älköön sattuko häneen, vaan sattukoon häneen filistealaisten käsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Mutta Daavid vastasi Saulille: \"Mikä minä olen, mikä on minun elämäni ja mikä on isäni suku Israelissa, että tulisin kuninkaan vävyksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Kun aika tuli, että Saulin tytär Meerab oli annettava Daavidille, annettiinkin hänet vaimoksi meholalaiselle Adrielille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Mutta Saulin tytär Miikal rakasti Daavidia. Kun se ilmoitettiin Saulille, se oli hänelle mieleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Sillä Saul ajatteli: \"Minä annan hänet Daavidille, että hän tulisi hänelle ansaksi ja filistealaisten käsi sattuisi häneen.\" Saul sanoi Daavidille: \"Nyt voit toisen kerran tulla vävykseni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Sitten Saul käski palvelijoitaan: \"Puhukaa salaa Daavidille näin: \'Katso, kuningas on mieltynyt sinuun, ja kaikki hänen palvelijansa rakastavat sinua. Sinun on nyt tultava kuninkaan vävyksi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Saulin palvelijat puhuivat nämä sanat Daavidille. Mutta Daavid sanoi: \"Onko teidän mielestänne niin pieni asia tulla kuninkaan vävyksi? Minähän olen köyhä ja halpa mies.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Saulin palvelijat ilmoittivat hänelle tämän, sanoen: \"Näin on Daavid puhunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Niin Saul sanoi: \"Sanokaa Daavidille näin: \'Kuningas ei halua muuta morsiamenhintaa kuin sata filistealaisten esinahkaa, että kuninkaan vihollisille kostettaisiin.\'\" Sillä Saul ajatteli kaataa Daavidin filistealaisten käden kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Kun hänen palvelijansa ilmoittivat tämän Daavidille, Daavidia miellytti tulla näin kuninkaan vävyksi. Ennen kuin määräaika oli kulunut umpeen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'Daavid nousi ja lähti miehineen ja kaatoi filistealaisia kaksisataa miestä. Daavid toi heidän esinahkansa, täyden määrän, kuninkaalle, tullakseen kuninkaan vävyksi. Silloin Saul antoi tyttärensä Miikalin hänelle vaimoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Saul näki ja ymmärsi, että Herra oli Daavidin kanssa, ja Saulin tytär Miikal rakasti häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Saul pelkäsi vielä enemmän Daavidia, ja Saulista tuli koko loppuiäkseen Daavidin vihamies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Mutta filistealaisten ruhtinaat lähtivät sotaan, ja niin usein kuin he lähtivät sotaan, oli Daavidilla suurempi menestys kuin kaikilla muilla Saulin palvelijoilla, niin että hänen nimensä tuli sangen kuuluisaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Saul puhui pojalleen Joonatanille ja kaikille palvelijoilleen, että Daavid oli surmattava. Mutta Saulin poika Joonatan oli suuresti mieltynyt Daavidiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'Sen tähden Joonatan ilmaisi sen Daavidille ja sanoi: \"Minun isäni Saul koettaa saada sinut surmatuksi. Ole siis varuillasi huomenaamuna, kätkeydy ja pysy piilossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Mutta minä menen ja asetun isäni viereen kedolle, sinne, missä olet, ja puhun sinusta isälleni, ja jos jotakin huomaan, ilmaisen sen sinulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Joonatan puhui hyvää Daavidista isälleen Saulille ja sanoi hänelle: \"Älköön kuningas rikkoko palvelijaansa Daavidia vastaan, sillä hän ei ole rikkonut sinua vastaan, vaan hänen työnsä ovat olleet sinulle suureksi hyödyksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Hänhän pani henkensä kämmenelleen ja surmasi filistealaisen, ja Herra antoi suuren voiton koko Israelille. Sinä olet itse nähnyt sen ja iloinnut. Miksi siis rikkoisit viatonta verta vastaan surmaamalla Daavidin syyttömästi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Saul kuuli Joonatanin ääntä, ja Saul vannoi: \"Niin totta kuin Herra elää, häntä ei surmata.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Joonatan kutsui Daavidin, ja Joonatan ilmoitti hänelle kaiken tämän. Joonatan vei Daavidin Saulin luo, ja hän palveli häntä kuten ennenkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Kun sota alkoi uudestaan, Daavid lähti taistelemaan filistealaisia vastaan ja tuotti heille suuren tappion, niin että he pakenivat hänen edestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Herran lähettämä paha henki tuli Sauliin, kun hän istui kotonaan keihäs kädessä ja Daavid soitteli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Saul yritti keihästää Daavidin seinään. Mutta hän väisti Saulia, ja tämä iski keihään seinään. Daavid pakeni ja pelastui sinä yönä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Saul lähetti miehiä Daavidin kotiin vartioimaan häntä ja surmaamaan hänet aamulla. Mutta Daavidin vaimo Miikal ilmaisi sen hänelle ja sanoi: \"Jollet tänä yönä pelasta henkeäsi, sinä huomenna olet surman oma.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Miikal laski Daavidin alas ikkunasta, ja hän lähti pakoon ja pelastui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Miikal otti kotijumalan ja asetti sen vuoteeseen, ja levitettyään vuohenkarvoista tehdyn kärpäsverkon sen pään yli hän peitti sen vaatteella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Kun Saul lähetti miehiä ottamaan Daavidia, Miikal sanoi: \"Hän on sairas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Saul lähetti miehiä katsomaan Daavidia, sanoen: \"Tuokaa hänet vuoteessa tänne luokseni surmattavaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Mutta kun miehet tulivat sisälle, katso, vuoteessa olikin kotijumala vuohenkarvoista tehty kärpäsverkko pään päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Saul sanoi Miikalille: \"Miksi sinä olet minut näin pettänyt ja olet päästänyt vihamieheni pelastumaan?\" Miikal vastasi Saulille: \"Hän sanoi minulle: \'Päästä minut, muutoin surmaan sinut.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Kun Daavid oli paennut ja pelastunut, hän meni Samuelin luo Raamaan ja kertoi hänelle kaikki, mitä Saul oli hänelle tehnyt. Sitten hän ja Samuel menivät Naajotiin ja he jäivät sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Saulille ilmoitettiin: \"Katso, Daavid on Raaman Naajotissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Saul lähetti miehiä ottamaan Daavidia. Mutta kun he näkivät profeettajoukon profetoivan ja Samuelin seisovan johtamassa heitä, tuli Jumalan Henki Saulin miehiin, niin että hekin profetoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Kun se ilmoitettiin Saulille, hän lähetti toiset miehet, mutta hekin profetoivat. Saul lähetti vielä kolmannet miehet, mutta hekin profetoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Silloin hän itse lähti Raamaan. Kun hän sitten tuli sen suuren vesisäiliön luo, joka on Seekussa, hän kysyi ja sanoi: \"Missä ovat Samuel ja Daavid?\" Hänelle vastattiin: \"He ovat Raaman Naajotissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Kun hän oli menossa sinne, Raaman Naajotiin, Jumalan Henki tuli häneenkin, niin että hän kulki profetoiden, kunnes tuli Raaman Naajotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Hänkin riisui vaatteensa ja profetoi Samuelin edessä. Hän kaatui maahan ja makasi alastomana koko sen päivän ja koko sen yön. Sen tähden on tapana sanoa: \"Onko Saulkin profeettojen joukossa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Daavid pakeni Raaman Naajotista. Hän tuli ja puhui Joonatanille: \"Mitä olen tehnyt? Mitä vääryyttä, mitä syntiä olen tehnyt isääsi vastaan, kun hän väijyy henkeäni?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Tämä vastasi hänelle: \"Pois se! Et sinä kuole. Katso, isäni ei tee mitään, suurta eikä pientä, ilmoittamatta minulle. Miksi sitten isäni salaisi minulta tämän? Ei ole niin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Mutta Daavid vielä vakuutti vannoen ja sanoi: \"Isäsi tietää, että olen saanut armon silmiesi edessä. Sen tähden hän ajattelee: \'Älköön Joonatan saako tietää tätä, ettei hän tulisi murheelliseksi.\' Mutta niin totta kuin Herra elää ja niin totta kuin sinä itse elät: on vain askel minun ja kuoleman välillä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Joonatan sanoi Daavidille: \"Mitä vain lausut toivovasi, sen minä sinulle teen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'Daavid sanoi Joonatanille: \"Katso, huomenna on uusikuu, ja minun pitäisi istua aterioimassa kuninkaan kanssa. Mutta salli minun mennä ja kätkeytyä ulos kedolle ylihuomeniltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Jos isäsi kaipaa minua, sano: \'Daavid pyysi minulta, että saisi käväistä kaupungissaan Beetlehemissä, sillä koko suvulla on siellä jokavuotiset teurasuhrit.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Jos hän sanoo: \'Hyvä on\', voi palvelijasi olla rauhassa. Mutta jos hän vihastuu, tiedä, että hänellä on paha mielessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Tee siis laupeus palvelijallesi, koska olet ottanut palvelijasi Herran liittoon kanssasi. Mutta jos minussa on vääryys, surmaa sinä minut, sillä miksi veisit minut isäsi eteen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Joonatan sanoi: \"Pois se! Jos huomaan, että isälläni on paha mielessä sinua vastaan, enkä sitä sinulle ilmoita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Mutta Daavid sanoi Joonatanille: \"Kunpa sitten joku ilmoittaisi minulle, antaako isäsi sinulle kovan vastauksen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Joonatan sanoi Daavidille: \"Tule, menkäämme ulos kedolle.\" He menivät molemmat ulos kedolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Joonatan sanoi Daavidille: \"Minä vakuutan Herran, Israelin Jumalan, kautta, että koetan huomenna tai ylihuomenna tähän aikaan päästä selville isästäni. Jos Daavidin asiat ovat hyvin, varmasti lähetän siitä tiedon ja ilmoitan sen sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Herra rangaiskoon Joonatania nyt ja vasta, jollen minä, jos isäni mielii tehdä sinulle pahaa, ilmoita sitä sinulle ja päästä sinua menemään rauhassa. Herra olkoon kanssasi, kuten hän on ollut isäni kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Etkö sinäkin, jos minä silloin vielä elän, etkö sinäkin tee Herran laupeutta minulle, niin etten kuole?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Ethän koskaan kiellä laupeuttasi suvultani, et silloinkaan, kun Herra hävittää Daavidin vihamiehet kaikki tyynni maan päältä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Joonatan teki liiton Daavidin huoneen kanssa ja [sanoi:] Herra on vaativa sen Daavidin vihamiesten kädestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Joonatan vannotti vielä Daavidin heidän keskinäisen rakkautensa kautta, sillä hän rakasti häntä kuin omaa sieluaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Joonatan sanoi hänelle: \"Huomenna on uusikuu, ja sinua kaivataan, kun paikkasi on tyhjä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Mutta ylihuomenna mene nopeasti siihen paikkaan, johon kätkeydyit tuon teon päivänä ja istuudu Eselin kiven viereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Minä ammun kolme nuolta sen laitaa kohti, kuin ampuisin maaliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Katso, [minä] lähetän palvelijan sanoen: \'Mene ja hae nuolet.\' Jos silloin tosiaan sanon palvelijalle: \'Katso, nuolet ovat takanasi, tännempänä, ota ne\', niin tule kotiin, sillä silloin voit olla rauhassa eikä mitään ole tekeillä, niin totta kuin Herra elää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Mutta jos sanon nuorelle miehelle näin: \'Katso, nuolet ovat edessäsi, sinnempänä\', niin lähde, sillä Herra lähettää sinut pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Sen, mitä minä ja sinä olemme keskenämme puhuneet, todistajana meidän välillämme, minun ja sinun, on Herra iankaikkisesti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Daavid kätkeytyi kedolle. Kun sitten uusikuu tuli, kuningas istuutui aterialle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Kuningas istui tavallisella istuimellaan, istuimella seinän vieressä. Joonatan nousi seisomaan, ja Abner istuutui Saulin viereen. Mutta Daavidin paikka oli tyhjä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Saul ei kuitenkaan sanonut mitään sinä päivänä, sillä hän ajatteli: \"Jotakin on hänelle tapahtunut: hän ei ole puhdas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Mutta kun Daavidin paikka oli tyhjä seuraavanakin päivänä, toisena uudenkuun päivänä, Saul sanoi pojalleen Joonatanille: \"Miksi Iisain poika ei ole eilen eikä tänään tullut aterialle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Joonatan vastasi Saulille: \"Daavid pyysi minulta, että saisi mennä Beetlehemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'Hän sanoi: \'Salli minun mennä, sillä meillä on suvun teurasuhrit kaupungissa, ja veljeni itse on käskenyt minut sinne. Jos siis olen saanut armon silmiesi edessä, päästä minut katsomaan veljiäni.\' Sen tähden hän ei ole tullut kuninkaan pöytään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Saul vihastui Joonataniin ja sanoi hänelle: \"Sinä säädyttömän naisen poika! Tiesinhän, että olet mieltynyt Iisain poikaan häpeäksi itsellesi ja häpeäksi äitisi hävylle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Sillä niin kauan kuin Iisain poika elää maan päällä, et sinä eikä kuninkuutesi ole turvassa. Lähetä nyt noutamaan hänet luokseni, sillä hän on kuoleman oma.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Joonatan vastasi isälleen Saulille ja sanoi hänelle: \"Miksi hänet on surmattava? Mitä hän on tehnyt?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Saul heitti keihään häntä kohti surmatakseen hänet. Joonatan ymmärsi, että hänen isänsä oli päättänyt tappaa Daavidin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Joonatan nousi pöydästä vihasta hehkuen eikä syönyt mitään toisena uudenkuun päivänä, sillä hän oli murheissaan Daavidin tähden, koska hänen isänsä oli häväissyt tätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Seuraavana aamuna Joonatan lähti ulos kedolle, niin kuin hän oli sopinut Daavidin kanssa, ja hänellä oli mukanaan pieni poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Hän sanoi pojalle: \"Juokse noutamaan nuolet, jotka ammun.\" Pojan juostessa hän ampui nuolen hänen ylitseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Kun poika oli tulossa siihen paikkaan, missä Joonatanin ampuma nuoli oli, Joonatan huusi pojalle ja sanoi: \"Nuoli on edessäsi, sinnempänä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Joonatan huusi vielä pojalle: \"Riennä nopeasti, älä seisahtele!\" Joonatanin poika otti nuolen ja tuli herransa luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Eikä poika tiennyt asiasta mitään, ainoastaan Joonatan ja Daavid tiesivät sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Joonatan antoi aseensa pojalle, joka hänellä oli mukanaan, ja sanoi hänelle: \"Mene ja vie nämä kaupunkiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Kun poika oli mennyt, Daavid nousi ylös etelän puolelta, ja lankesi kasvoilleen maahan ja kumartui kolme kertaa. He suutelivat toisiaan ja itkivät yhdessä. Daavid itki hillittömästi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Joonatan sanoi Daavidille: \"Mene rauhassa. Niin on, kuin me molemmat olemme vannoneet Herran nimeen ja sanoneet: \' Herra on todistaja välillämme, minun ja sinun, ja minun jälkeläisteni ja sinun jälkeläistesi välillä iankaikkisesti.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Sitten Daavid nousi ja lähti, mutta Joonatan palasi kaupunkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'Daavid tuli pappi Ahimelekin luo Noobiin. Mutta Ahimelek tuli vavisten Daavidia vastaan ja kysyi häneltä: \"Miksi sinä tulet yksin, eikä ketään ole kanssasi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Daavid vastasi pappi Ahimelekille: \"Kuningas on käskenyt minut asialle ja sanoi minulle: \'Älköön kukaan saako tietää mitään asiasta, jolle minä sinut lähetän, ja siitä käskystä, jonka olen sinulle antanut.\' Palvelijat olen määrännyt siihen ja siihen paikkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Anna nyt minulle, mitä sinulla on, viisi leipää, tai mitä muuta löytyy.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Pappi vastasi Daavidille ja sanoi: \"Tavallista leipää minulla ei ole, ainoastaan pyhää leipää on, jos vain palvelijat ovat karttaneet naisia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Daavid vastasi papille ja sanoi hänelle: \"Totisesti naiset olivat eristettyinä meistä kuten ennenkin, kun lähdin. Ovatpa palvelijoiden astiatkin olleet aina pyhät, vaikka matka on ollut tavallinen matka. Sitä enemmän leipä astioissa pysyy nyt pyhänä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Pappi antoi hänelle pyhää leipää, sillä siellä ei ollut muuta leipää kuin näkyleipiä, jotka oli siirretty pois Herran edestä, että sinne samana päivänä, jona ne oli otettu pois, pantaisiin tuoreet leivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Mutta siellä oli sinä päivänä eristettynä Herran edessä eräs Saulin palvelija, nimeltä Dooeg, edomilainen, Saulin paimenten päämies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Daavid kysyi vielä Ahimelekilta: \"Eikö sinulla ole täällä keihästä tai miekkaa? Sillä en ottanut mukaani, en miekkaani enkä muita aseitani, koska kuninkaan asia oli kiireellinen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Pappi vastasi: \"On, sen filistealaisen Goljatin miekka, jonka sinä surmasit Tammilaaksossa. Katso, se on viittaan käärittynä kasukan takana. Jos tahdot ottaa sen itsellesi, ota. Sillä muuta kuin se ei täällä ole.\" Daavid sanoi: \"Ei ole toista sen veroista. Anna se minulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Sitten Daavid nousi ja pakeni sinä päivänä Saulia ja tuli Aakiin, Gatin kuninkaan, luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Aakiin palvelijat sanoivat hänelle: \"Eikö tämä ole Daavid, sen maan kuningas? Eivätkö he karkeloiden virittäneet hänelle tätä laulua: \'Saul voitti tuhat, mutta Daavid kymmenentuhatta\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Daavid painoi mieleensä nämä sanat ja pelkäsi suuresti Aakista, Gatin kuningasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Hän tekeytyi mielipuoleksi heidän silmissään ja raivosi heidän käsissään ja piirusteli portin oviin ja valutti sylkeä partaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Silloin Aakis sanoi palvelijoilleen: \"Näettehän, että mies on hullu. Miksi toitte hänet luokseni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 16, 'Puuttuuko minulta hulluja, kun toitte tämän mielipuolen eteeni? Tällainenko saisi tulla hoviini?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Daavid lähti sieltä ja pääsi pakoon Adullamin luolaan. Kun hänen veljensä ja koko hänen isänsä perhe kuulivat sen, he tulivat sinne hänen luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Hänen luokseen kokoontui kaikenlaista ahdingossa olevaa, velkaantunutta ja katkeroitunutta väkeä, ja hän rupesi heidän päämiehekseen. Häneen liittyi noin neljäsataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Sieltä Daavid meni Mooabin Mispeen. Hän sanoi Mooabin kuninkaalle: \"Salli isäni ja äitini tulla asumaan luoksenne, kunnes saan tietää, mitä Jumala minulle tekee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Hän vei heidät Mooabin kuninkaan eteen, ja he jäivät tämän luo kaikeksi aikaa, minkä Daavid oli Vuorilinnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Profeetta Gaad sanoi Daavidille: \"Älä jää Vuorilinnaan, lähde täältä ja mene Juudan maahan.\" Daavid lähti ja tuli Jaar-Heretiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Saul kuuli, että oli saatu vihiä Daavidista ja niistä miehistä, jotka olivat hänen kanssaan. Saul istui Gibeassa tamariskipuun alla kummulla keihäs kädessä, ja kaikki hänen palvelijansa seisoivat hänen luonaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Saul sanoi palvelijoilleen, jotka seisoivat hänen luonaan: \"Kuulkaa, benjaminilaiset! Antaako Iisain poika teillekin kaikille pellot ja viinitarhat, ja tekeekö hän teidät kaikki tuhannen- ja sadanpäämiehiksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'Tehän olette kaikki salaliitossa minua vastaan, eikä kukaan ole ilmaissut minulle, että oma poikani on tehnyt liiton Iisain pojan kanssa. Ei kukaan teistä välitä niin paljoa minusta, että olisi ilmaissut sen minulle. Sillä poikani on yllyttänyt palvelijani väijymään minua, niin kuin nyt tapahtuu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Edomilainen Dooeg, joka seisoi siinä Saulin palvelijain kanssa, vastasi ja sanoi: \"Näin Iisain pojan tulevan Noobiin, Ahimelekin, Ahitubin pojan, luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Tämä kysyi hänelle neuvoa Herralta ja antoi hänelle evästä ja antoi hänelle filistealaisen Goljatin miekan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Kuningas lähetti kutsumaan pappi Ahimelekin, Ahitubin pojan, ja koko hänen isänsä suvun, Noobin papit. He tulivat kaikki kuninkaan luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Saul sanoi: \"Kuule, Ahitubin poika!\" Hän vastasi: \"Tässä olen, herrani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Saul sanoi hänelle: \"Miksi olette salaliitossa minua vastaan, sinä ja Iisain poika, koska olet antanut hänelle leipää ja miekan ja kysynyt hänelle Herralta neuvoa, että hän ryhtyisi väijymään minua, niin kuin nyt tapahtuu?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Ahimelek vastasi kuninkaalle ja sanoi: \"Kuka on kaikkien palvelijoittesi joukossa niin uskottu kuin Daavid, joka on kuninkaan vävy ja henkivartiostosi päällikkö ja korkeassa arvossa hovissasi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Olenko tänään ensi kertaa kysynyt hänelle Jumalalta neuvoa? Pois se! Älköön kuningas lukeko mitään viaksi minulle, palvelijalleen, älköönkä kaikelle isäni suvulle, sillä palvelijasi ei tietänyt lainkaan tästä kaikesta, ei vähää eikä suurta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Mutta kuningas sanoi: \"Sinun on kuolemalla kuoltava, Ahimelek, sinun ja koko sinun isäsi suvun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Kuningas sanoi henkivartijoille, jotka seisoivat hänen luonaan: \"Käykää tänne ja surmatkaa Herran papit, sillä hekin pitävät Daavidin puolta, ja vaikka tiesivät hänen paenneen, eivät ilmoittaneet sitä minulle.\" Mutta kuninkaan palvelijat eivät tahtoneet ojentaa kättään lyömään kuoliaaksi Herran pappeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Kuningas sanoi Dooegille: \"Käy sinä tänne ja lyö papit kuoliaaksi.\" Silloin edomilainen Dooeg astui esiin ja löi papit kuoliaaksi, ja hän tappoi sinä päivänä kahdeksankymmentä viisi pellavakasukkaa kantavaa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Myös pappiskaupungin Noobin asukkaat hän surmasi miekan terällä, sekä miehet että naiset, sekä lapset että imeväiset, jopa naudat, aasit ja lampaatkin hän tappoi miekan terällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Ainoastaan yksi Ahimelekin, Ahitubin pojan, poika, nimeltä Ebjatar, pelastui ja pakeni Daavidin luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Ebjatar kertoi Daavidille, että Saul oli tappanut Herran papit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Niin Daavid sanoi Ebjatarille: \"Minä ymmärsin jo silloin, että edomilainen Dooeg, kun hän oli siellä, oli ilmaiseva sen todella Saulille. Minä olen syypää koko sinun isäsi suvun joka hengen kuolemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Jää luokseni, älä pelkää. Sillä joka väijyy sinun henkeäsi, väijyy minun henkeäni. Olethan turvassa luonani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Daavidille ilmoitettiin: \"Katso, filistealaiset ovat taistelemassa Kegilaa vastaan ja ryöstävät puimatantereita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Daavid kysyi Herralta: \"Lähdenkö ja lyönkö nämä filistealaiset maahan?\" Herra vastasi Daavidille: \"Mene, lyö filistealaiset maahan ja pelasta Kegila.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Mutta Daavidin miehet sanoivat hänelle: \"Mehän elämme pelossa jo täällä Juudassa. Menisimmekö vielä Kegilaan filistealaisten taistelurivejä vastaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Daavid kysyi taas Herralta, ja Herra vastasi hänelle ja sanoi: \"Nouse ja mene alas Kegilaan. Sillä minä annan filistealaiset käsiisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Daavid meni miehineen Kegilaan ja ryhtyi taisteluun filistealaisia vastaan ja kuljetti heidän karjansa pois ja tuotti heille suuren tappion. Näin Daavid pelasti Kegilan asukkaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Kun Ebjatar, Ahimelekin poika, pakeni Daavidin luo Kegilaan, seurasi kasukka hänen mukanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Saulille ilmoitettiin, että Daavid oli mennyt Kegilaan. Saul sanoi: \"Jumala on jättänyt hänet käsiini, sillä hän on itse sulkenut itsensä sisälle, kun on mennyt kaupunkiin, jossa on ovet ja salvat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Saul kuulutti kaiken kansan sotaan menemään alas Kegilaan piirittämään Daavidia ja hänen miehiään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Kun Daavid sai tietää, että Saul suunnitteli hänelle tuhoa, hän sanoi pappi Ebjatarille: \"Tuo tänne kasukka.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Silloin Daavid sanoi: \" Herra, Israelin Jumala! Palvelijasi on kuullut, että Saul aikoo tulla Kegilaan hävittämään kaupungin takiani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Luovuttavatko Kegilan miehet minut hänen käsiinsä? Tuleeko Saul, kuten palvelijasi on kuullut? Herra, Israelin Jumala, ilmoita se palvelijallesi.\" Herra vastasi: \"Tulee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Daavid kysyi vielä: \"Luovuttavatko Kegilan miehet minut ja mieheni Saulin käsiin?\" Herra vastasi: \"Luovuttavat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Niin Daavid nousi miehineen, joita oli noin kuusisataa miestä, ja he lähtivät Kegilasta ja kuljeskelivat paikasta toiseen. Mutta kun Saulille kerrottiin, että Daavid oli päässyt pakoon Kegilasta, hän ei lähtenyt matkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'Sitten Daavid oleskeli erämaassa vuorten huipuilla. Hän oleskeli Siifin erämaan vuoristossa. Niin Saul etsi häntä kaiken aikaa, mutta Jumala ei antanut häntä tämän käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Daavid huomasi, että Saul oli lähtenyt väijymään hänen henkeään, ja Daavid oli Hooreksessa, Siifin erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Saulin poika Joonatan nousi ja meni Daavidin luo Hoorekseen ja rohkaisi häntä Jumalassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Hän sanoi hänelle: \"Älä pelkää. Sillä isäni Saulin käsi ei ole löytävä sinua, vaan sinusta tulee Israelin kuningas, ja minä tulen olemaan lähinnä sinua. Myös isäni Saul tietää sen kyllä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'He molemmat tekivät liiton Herran edessä. Daavid jäi Hoorekseen, mutta Joonatan palasi kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Siifiläisiä meni Saulin luo Gibeaan, ja he sanoivat: \"Daavid piileskelee meillä päin, vuorten huipuilla Hooreksessa, Gibeat-Hakilassa, joka on Jesimasta etelään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Tule nyt sinne, kuningas, milloin vain haluat tulla. Me kyllä luovutamme hänet kuninkaan käsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Saul sanoi: \" Herra siunatkoon teitä, kun te säälitte minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Menkää, pitäkää häntä vielä silmällä, tiedustelkaa ja katsokaa, missä paikassa hänen jalkansa liikkuu ja kuka hänet on siellä nähnyt. Sillä minulle on sanottu, että hän on hyvin kavala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Katsokaa ja tiedustelkaa kaikki piilopaikat, joihin hän voi piiloutua. Palatkaa luokseni ja tuokaa varmat tiedot, niin lähden kanssanne. Jos hän on tässä maassa, etsin hänet kaikkien Juudan sukujen seasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'He nousivat ja menivät Siifiin Saulin edellä. Mutta Daavid miehineen oli Maaonin erämaassa, aromaassa, kallioerämaasta etelään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Kun Saul miehineen meni etsimään Daavidia, ilmoitettiin se tälle, ja hän laskeutui eräälle kalliolle ja jäi Maaonin erämaahan. Kun Saul kuuli sen, hän lähti ajamaan Daavidia takaa Maaonin erämaahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Saul kulki vuoren toista puolta ja Daavid miehineen vuoren toista puolta. Kun Daavid riensi pakoon Saulin tieltä ja Saul miehineen oli kiertämässä Daavidia ja hänen miehiään ottaakseen heidät kiinni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'tuli sanansaattaja Saulin luo ja sanoi: \"Tule nopeasti, sillä filistealaiset ovat hyökänneet maahan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Saul lakkasi ajamasta takaa Daavidia ja lähti filistealaisia vastaan. Siitä paikka sai nimekseen Mahlekotin kallio.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'Mutta Daavid lähti sieltä ja oleskeli Een-Gedin vuorten huipuilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Kun Saul palasi ajamasta filistealaisia takaa, ilmoitettiin hänelle: \"Katso, Daavid on Een-Gedin erämaassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Saul otti kolmetuhatta valiomiestä koko Israelista ja meni etsimään Daavidia ja hänen miehiään Kauriskallioiden itäpuolelta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Kun hän tuli tien varrella oleville lammas- ja vuohitarhoille, siellä oli luola, ja Saul meni luolaan tarpeelleen. Mutta Daavid ja hänen miehensä istuivat luolan perällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Niin Daavidin miehet sanoivat hänelle: \"Katso, tämä on päivä, josta Herra on sanonut sinulle: \'Minä annan vihamiehesi sinun käsiisi tehdäksesi hänelle, mitä hyväksi näet.\'\" Daavid nousi ja leikkasi salaa kappaleen Saulin viitan liepeestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Mutta sen jälkeen Daavidin sydän soimasi häntä siitä, että hän oli leikannut Saulin viitan lievettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Hän sanoi miehilleen: \"Pois se! Herra varjelkoon minua tekemästä sitä herralleni, Herran voidellulle, että satuttaisin käteni häneen. Sillä hän on Herran voideltu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Daavid kovisti miehiään eikä sallinut heidän hyökätä Saulin kimppuun. Saul nousi luolasta ja meni matkaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Daavidkin nousi, lähti luolasta ja huusi Saulin jälkeen: \"Herrani, kuningas!\" Kun Saul katsoi taakseen, Daavid kumartui kasvoilleen maahan ja osoitti kunnioitusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Daavid sanoi Saulille: \"Miksi kuuntelet ihmisten puheita, jotka sanovat: \'Daavid hankkii sinulle onnettomuutta\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Katso, näethän nyt omin silmin, kuinka Herra tänä päivänä antoi sinut käsiini luolassa, mutta säästin sinut, vaikka minua neuvottiin tappamaan sinut. Ajattelin näet: \'En satuta kättäni herraani, sillä hän on Herran voideltu.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Katso itse, isäni, katso tätä viittasi liepeen kappaletta, joka on kädessäni. Kun leikkasin sen viittasi liepeestä enkä sinua tappanut, ymmärrä siitä ja näe: minulla ei ole tekeillä mitään pahaa tai rikollista enkä ole sinua vastaan rikkonut, vaikka vainoat minua ottaaksesi minulta hengen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Herra tuomitkoon välillämme, minun ja sinun, ja Herra kostakoon sinulle puolestani, mutta minun käteni ei sinuun satu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'On, niin kuin vanha sananlasku sanoo: \'Jumalattomuus tulee jumalattomista\', mutta minun käteni ei sinuun satu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Kenen perään Israelin kuningas on lähtenyt? Ketä sinä ajat takaa? Koiranraatoa, yhtä kirppua!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Herra olkoon tuomari ja tuomitkoon välillämme, minun ja sinun. Hän nähköön ja ajakoon asiani ja auttakoon minut käsistäsi oikeuteeni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Kun Daavid oli päättänyt tämän puheensa Saulille, Saul sanoi: \"Eikö se ole äänesi, poikani Daavid?\" Saul korotti äänensä ja itki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Hän sanoi Daavidille: \"Sinä olet minua vanhurskaampi, sillä sinä olet tehnyt minulle hyvää, vaikka minä olen tehnyt sinulle pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Sinä olet tänä päivänä osoittanut hyvyyttäsi minua kohtaan, kun et tappanut minua, vaikka Herra oli antanut minut käsiisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Sillä kun joku kohtaa vihollisensa, päästääkö hän hänet menemään rauhassa? Herra palkitkoon sinulle runsaasti sen, mitä olet tänä päivänä tehnyt minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Katso, nyt tiedän, että sinä tulet kuninkaaksi ja että Israelin kuninkuus on pysyvä kädessäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'Vanno nyt minulle Herran kautta, ettet hukuta jälkeläisiäni etkä hävitä nimeäni isäni suvusta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 23, 'Daavid vannoi Saulille. Saul lähti kotiinsa, mutta Daavid ja hänen miehensä nousivat Vuorilinnaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Samuel kuoli, ja koko Israel kokoontui pitämään hänelle valittajaisia. He hautasivat hänet hänen kotipaikkaansa Raamaan. Daavid nousi ja meni Paaranin erämaahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Maaonissa oli mies, jolla oli taloutensa Karmelissa. Mies oli hyvin rikas: hänellä oli kolmetuhatta lammasta ja tuhat vuohta. Hän oli keritsemässä lampaitaan Karmelissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Miehen nimi oli Naabal, ja hänen vaimonsa nimi oli Abigail. Vaimo oli hyvin ymmärtäväinen ja vartaloltaan kaunis, mutta mies oli tyly ja raaka. Hän oli kaalebilainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Kun Daavid kuuli erämaassa, että Naabal keritsi lampaitaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'hän lähetti sinne kymmenen nuorta miestä. Daavid sanoi nuorille miehille: \"Menkää Karmeliin, ja kun tulette Naabalin luo, tervehtikää häntä nimessäni');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'ja sanokaa hänelle: \'Sinä elät rauhassa. Rauhassa elää myös perheesi ja kaikki, mitä sinulla on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Olen nyt kuullut, että sinulla on lammasten keritsiäiset. Paimenesi ovat olleet läheisyydessämme. Me emme ole heitä loukanneet, eikä heiltä ole mitään hävinnyt koko sinä aikana, minkä he ovat olleet Karmelissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Kysy nuorilta miehiltäsi, niin he sanovat sen sinulle. Saakoot siis nämä miehet armon silmiesi edessä, sillä mehän olemme tulleet juhlapäivänä. Anna sen tähden palvelijoillesi ja pojallesi Daavidille sitä, mitä sinulla on käsillä.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Kun Daavidin miehet tulivat sinne, he puhuivat Daavidin nimessä Naabalille tämän kaiken ja jäivät hiljaa odottamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Mutta Naabal vastasi Daavidin palvelijoille ja sanoi: \"Kuka Daavid on, kuka on Iisain poika? Tätä nykyä on paljon orjia, jotka karkaavat isäntiensä luota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Ottaisinko minä ruokani, juomaveteni ja teuraani, jotka olen teurastanut keritsiäisiini, ja antaisin ne miehille, jotka ovat kotoisin ties mistä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Daavidin miehet kääntyivät ja menivät pois. Tultuaan takaisin he kertoivat hänelle tämän kaiken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Daavid sanoi miehilleen: \"Jokainen sitokoon miekkansa vyölleen.\" Jokainen sitoi miekkansa vyölleen. Daavid itsekin sitoi miekkansa vyölleen. Noin neljäsataa miestä lähti seuraamaan Daavidia, mutta kaksisataa jäi kuormaston luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Eräs nuori mies toi sanan Abigailille, Naabalin vaimolle, ja sanoi: \"Katso, Daavid lähetti sanansaattajia erämaasta tervehtimään isäntäämme, mutta hän vain haukkui heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Miehet ovat kuitenkin olleet meille varsin hyviä: he eivät loukanneet meitä, eikä meiltä hävinnyt mitään koko sinä aikana, minkä kuljeskelimme heidän läheisyydessään ollessamme kedolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'He olivat muurina ympärillämme yöllä ja päivällä koko sen ajan, minkä oleskelimme heidän läheisyydessään paimentaessamme lampaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Ajattele nyt ja katso, mitä voit tehdä, sillä onnettomuus uhkaa isäntäämme ja koko hänen taloaan. Hän itse on kelvoton mies, niin ettei hänelle auta puhua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Abigail otti joutuin kaksisataa leipää, kaksi leiliä viiniä, viisi lampaanpaistia, viisi sea-mittaa paahdettuja jyviä, sata rusinakakkua ja kaksisataa viikunakakkua ja pani ne aasien selkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'Hän sanoi palvelijoilleen: \"Menkää edelläni, minä tulen perässänne.\" Mutta hän ei ilmoittanut sitä miehelleen Naabalille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Kun hän sitten ratsasti aasilla alamäkeä vuoren suojassa, katso, Daavid miehineen tuli toista mäkeä alas häntä vastaan, niin että hän joutui kohtaamaan heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Mutta Daavid oli sanonut: \"Mitään saamatta olen suojellut kaikkea, mitä tällä miehellä oli erämaassa, niin ettei mitään ole hävinnyt kaikesta, mitä hänellä oli. Hän on palkinnut minulle hyvän pahalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Jumala rangaiskoon Daavidin vihamiehiä nyt ja vasta: totisesti, minä en jätä kaikesta hänen väestään huomenaamuksi yhtään miespuolista henkiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Mutta kun Abigail näki Daavidin, hän laskeutui nopeasti aasin selästä maahan, lankesi kasvoilleen Daavidin eteen ja kumartui maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'Kun hän oli langennut hänen jalkojensa juureen, hän sanoi: \"Minun on syy, herrani. Mutta salli palvelijattaresi puhua sinulle ja kuule palvelijattaresi sanoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Älköön herrani välittäkö mitään tuosta kelvottomasta miehestä, Naabalista, sillä nimi on miestä myöten. Naabal on hänen nimensä, ja houkkamainen hän on. Mutta minä, sinun palvelijattaresi, en ole nähnyt niitä miehiä, jotka sinä, herrani, lähetit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Nyt, herrani, niin totta kuin Herra elää ja niin totta kuin sinä itse elät, jonka Herra on estänyt joutumasta verivelan alaiseksi ja auttamasta itseäsi omalla kädelläsi: käyköön nyt vihamiehillesi ja kaikille, jotka hankkivat onnettomuutta herralleni, niin kuin Naabalille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Annettakoon nyt tämä tervehdyslahja, jonka palvelijattaresi on herralleni tuonut, niille miehille, jotka seuraavat herraani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Anna palvelijattaresi rikos anteeksi. Sillä Herra on rakentava minun herralleni pysyvän huoneen, koska minun herrani käy Herran sotia, eikä mitään pahaa löydetä sinussa koko elinaikanasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Jos joku nousee vainoamaan sinua ja väijymään henkeäsi, niin herrani henki on tallella elävien kukkarossa Herran, Jumalasi, luona, mutta sinun vihollistesi hengen hän lingolla linkoaa pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'Kun Herra tekee herralleni kaiken hyvän, josta hän on sinulle puhunut, ja määrää sinut Israelin ruhtinaaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'niin ei sinua kaada eikä herrani tuntoa vaivaa se, että olisit aiheettomasti vuodattanut verta ja että herrani olisi itse auttanut itseään. Mutta kun Herra on tekevä hyvää herralleni, niin muista palvelijatartasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Niin Daavid sanoi Abigailille: \"Kiitetty olkoon Herra, Israelin Jumala, joka tänä päivänä lähetti sinut minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Siunattu olkoon ymmärtäväisyytesi, ja siunattu ole sinä itse, joka tänä päivänä estit minut joutumasta verivelan alaiseksi ja auttamasta itseäni omalla kädelläni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Mutta niin totta kuin Herra, Israelin Jumala, elää, hän, joka on pidättänyt minut tekemästä sinulle pahaa: jollet sinä joutuin olisi tullut minua vastaan, niin totisesti ei Naabalin väestä olisi huomenna aamun valjetessa ollut jäljellä yhtään miespuolista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Sitten Daavid otti häneltä, mitä hän oli hänelle tuonut, ja sanoi hänelle: \"Mene rauhassa kotiisi. Katso, olen kuullut sinua ja tehnyt sinulle mieliksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Kun Abigail sitten tuli Naabalin luo, tällä oli talossaan pidot, kuin kuninkaan pidot. Naabalin sydän oli iloinen, ja hän oli kovin juovuksissa. Abigail ei kertonut Naabalille mitään, ennen kuin aamu valkeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Mutta seuraavana aamuna, kun Naabalista oli humala haihtunut, hänen vaimonsa kertoi hänelle, mitä oli tapahtunut. Silloin hänen sydämensä kuoleutui hänen rinnassaan, ja hän ikään kuin kivettyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Sitten noin kymmenen päivän kuluttua Herra löi Naabalia, niin että hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Kun Daavid kuuli, että Naabal oli kuollut, hän sanoi: \"Kiitetty olkoon Herra, joka on kostanut Naabalille häväistykseni ja pidättänyt palvelijansa pahasta ja kääntänyt Naabalin pahuuden hänen oman päänsä päälle.\" Sen jälkeen Daavid lähetti sanomaan Abigailille, että hän halusi ottaa hänet vaimokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Kun Daavidin palvelijat tulivat Abigailin luo Karmeliin, he puhuivat hänelle ja sanoivat: \"Daavid lähetti meidät luoksesi ottamaan sinut hänelle vaimoksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Hän nousi ylös, kumartui kasvoilleen maahan ja sanoi: \"Katso, palvelijattaresi on valmis rupeamaan orjattareksi ja pesemään herrani palvelijain jalat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Abigail nousi kiireesti ylös ja istuutui aasin selkään, samoin hänen viisi palvelijatartaan, jotka olivat hänellä seuralaisina. Hän seurasi Daavidin sanansaattajia ja tuli hänen vaimokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Daavid oli nainut myös Ahinoamin Jisreelistä, niin että he molemmat tulivat hänen vaimoikseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Mutta Saul oli antanut tyttärensä Miikalin, Daavidin vaimon, Paltille, Laiksen pojalle, joka oli kotoisin Gallimista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Siifiläiset tulivat Saulin luo Gibeaan ja sanoivat: \"Daavid piileksii Gibeat-Hakilassa, kallioerämaan puolella.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Saul nousi ja meni Siifin erämaahan ja hänen mukanaan kolmetuhatta Israelin valiomiestä etsimään Daavidia Siifin erämaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Saul leiriytyi Gibeat-Hakilaan, joka on kallioerämaan puolella tien varrella. Mutta Daavid oleskeli erämaassa. Kun Daavid huomasi, että Saul oli tullut hänen perässään erämaahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'hän lähetti vakoojia ja sai varman tiedon Saulin tulosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Daavid nousi ja meni siihen paikkaan, johon Saul oli leiriytynyt. Daavid näki, missä paikassa Saul ja hänen sotapäällikkönsä Abner, Neerin poika, makasivat. Saul näet makasi leirissä, ja väki oli asettunut hänen ympärilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Silloin Daavid puhui heettiläiselle Ahimelekille ja Abisaille, Serujan pojalle, Jooabin veljelle, ja sanoi: \"Kuka lähtee kanssani Saulin luo leiriin?\" Abisai vastasi: \"Minä lähden kanssasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Daavid ja Abisai menivät yöllä väen luo ja näkivät, että Saul makasi ja nukkui leirissä, ja hänen keihäänsä oli pistettynä maahan hänen päänsä taakse. Mutta Abner ja väki makasivat hänen ympärillään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Silloin Abisai sanoi Daavidille: \"Jumala on tänä päivänä antanut vihamiehesi käsiisi. Salli nyt minun keihästää hänet maahan. Vain yksi isku, toista ei tarvita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Mutta Daavid vastasi Abisaille: \"Älä surmaa häntä, sillä kuka on rankaisematta satuttanut kätensä Herran voideltuun?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Vielä Daavid sanoi: \"Niin totta kuin Herra elää: joko Herra itse lyö hänet tai hänen kuolinpäivänsä tulee tai hän lähtee sotaan ja tuhoutuu siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Mutta minä en satuta kättäni Herran voideltuun. Pois se, Herra varjelkoon! Vaan ota nyt keihäs hänen päänsä takaa ja vesiastia, ja sitten lähtekäämme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Niin Daavid otti keihään ja vesiastian Saulin pään takaa, ja sitten he menivät tiehensä. Eikä kukaan nähnyt tai huomannut sitä, eikä kukaan herännyt, vaan he kaikki nukkuivat, sillä Herran lähettämä raskas uni oli vallannut heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Kun sitten Daavid oli tullut toiselle puolelle, hän asettui kauas vuoren laelle pitkän välimatkan päähän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Daavid huusi väelle ja Abnerille, Neerin pojalle, ja sanoi: \"Etkö vastaa, Abner?\" Abner vastasi ja sanoi: \"Kuka sinä olet, joka huudat kuninkaalle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Daavid sanoi Abnerille: \"Sinähän olet mies, eikä vertaistasi ole Israelissa. Miksi et vartioinut herraasi, kuningasta? Sillä joku kansasta tuli surmaamaan kuningasta, herraasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Se, mitä teit, ei ollut hyvin tehty. Niin totta kuin Herra elää: te olette kuoleman omat, koska ette vartioineet herraanne, Herran voideltua. Katsohan nyt: missä ovat kuninkaan keihäs ja vesiastia, jotka olivat hänen päänsä takana?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Niin Saul tunsi Daavidin äänen ja sanoi: \"Sehän on sinun äänesi, poikani Daavid.\" Daavid vastasi: \"Niin on, herrani, kuningas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Vielä hän sanoi: \"Miksi herrani vainoaa palvelijaansa? Mitä minä olen tehnyt, tai mitä pahaa minulla on tekeillä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Kuulkoon nyt herrani, kuningas, mitä hänen palvelijansa sanoo. Jos Herra on yllyttänyt sinut minua vastaan, saakoon hän tuntea ruokauhrin hajua. Mutta jos sen ovat tehneet ihmiset, niin olkoot he kirotut Herran edessä, koska he tänä päivänä karkottavat minut pois Herran perintöosasta sanoen: \'Mene ja palvele muita jumalia.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Älköön kuitenkaan vereni vuotako maahan kaukana Herran kasvoista. Niin, Israelin kuningas on lähtenyt liikkeelle etsimään yhtä kirppua kuin ajetaan peltokanaa vuorilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Silloin Saul sanoi: \"Minä olen tehnyt syntiä. Tule takaisin, poikani Daavid, sillä minä en enää tee sinulle pahaa, koska henkeni tänä päivänä on ollut kallis silmissäsi. Katso, olen tehnyt tyhmästi ja erehtynyt kovin pahoin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'Daavid vastasi ja sanoi: \"Tässä on kuninkaan keihäs. Tulkoon joku miehistä tänne ottamaan sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Herra palkitsee jokaiselle hänen vanhurskautensa ja uskollisuutensa. Sillä Herra antoi sinut tänä päivänä käsiini, mutta en tahtonut satuttaa kättäni Herran voideltuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Katso, niin kuin henkesi on tänä päivänä ollut suuriarvoinen silmissäni, niin on myös minun henkeni oleva suuriarvoinen Herran silmissä, ja hän on pelastava minut kaikesta hädästä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Saul sanoi Daavidille: \"Siunattu ole sinä, poikani Daavid! Minkä teet, sen teet, mitä voit, sen voit.\" Sitten Daavid meni pois, ja Saul palasi kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Mutta Daavid ajatteli mielessään: \"Kerran Saulin käsi kuitenkin tuhoaa minut. En voi muuta kuin pelastautua filistealaisten maahan. Silloin Saul huomaa turhaksi enää etsiä minua kaikkialta Israelin alueelta, ja minä pelastun hänen käsistään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Daavid nousi ja meni, hän ja ne kuusisataa miestä, jotka olivat hänen kanssaan, Aakiin, Maaokin pojan, Gatin kuninkaan, luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Daavid asettui miehineen Aakiin luo Gatiin. Jokaisella oli perheensä mukanaan, Daavidilla molemmat vaimonsa, jisreeliläinen Ahinoam ja karmelilainen Abigail, Naabalin [leski] vaimo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Kun sitten Saulille ilmoitettiin, että Daavid oli paennut Gatiin, hän ei enää etsinyt häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'Daavid sanoi Aakiille: \"Jos olen löytänyt armon silmiesi edessä, annettakoon minulle paikka jossakin maaseutukaupungissa asuakseni siellä. Sillä miksi palvelijasi asuisi kuninkaan kaupungissa luonasi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Aakis antoi hänelle sinä päivänä Siklagin. Sen tähden Siklag on Juudan kuningasten oma vielä tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Aika, jonka Daavid asui filistealaisten maassa, oli vuosi ja neljä kuukautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'Daavid lähti miehineen, ja he tekivät ryöstöretkiä gesurilaisten, geresiläisten ja amalekilaisten maahan. Sillä nämä asuivat maassa, joka muinoin ulottui Suuriin päin ja Egyptin maahan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Hävittäessään maata Daavid ei jättänyt yhtään miestä eikä naista henkiin, otti lampaat, naudat, aasit, kamelit ja vaatteet ja palasi sitten takaisin ja tuli Aakiin luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Kun Aakis kysyi: \"Ettehän ole tehneet tänään ryöstöretkeä?\" Daavid vastasi: \"Olemme, Juudan Negeviin\", tai: \"Jerahmeelilaisten Negeviin\", tai: \"Keeniläisten Negeviin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Daavid ei jättänyt yhtään miestä eikä naista henkiin vietäväksi Gatiin, sillä hän ajatteli: \"Ne voisivat kertoa meistä ja sanoa: \'Näin on Daavid tehnyt, tämä on ollut hänen tapansa kaiken aikaa, minkä hän asui filistealaisten maassa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Aakis luotti Daavidiin ja ajatteli: \"Hän on saattanut itsensä kansansa Israelin vihoihin ja tulee olemaan palvelijani ikuisesti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Tapahtui siihen aikaan, että filistealaiset kokosivat joukkonsa sotaretkelle Israelia vastaan, ja Aakis sanoi Daavidille: \"Tiedä, että sinun on miehinesi lähdettävä kanssani sotajoukon mukana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'Daavid vastasi Aakiille: \"Nyt tulet tietämään, mitä palvelijasi saa aikaan.\" Aakis sanoi Daavidille: \"Siispä asetan sinut pääni vartijaksi koko täksi aikaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Samuel oli kuollut, ja koko Israel oli pitänyt hänelle valittajaiset, ja he olivat haudanneet hänet hänen kaupunkiinsa Raamaan. Saul oli toimittanut pois maasta vainaja- ja tietäjähenkien manaajat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Filistealaiset kokoontuivat, ja he tulivat ja leiriytyivät Suunemiin. Saulkin kokosi koko Israelin, ja he leiriytyivät Gilboaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Mutta kun Saul näki filistealaisten leirin, hän pelästyi, ja hänen sydämensä vapisi kovin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Saul kysyi Herralta, mutta Herra ei vastannut hänelle, ei unissa, ei uurimin eikä profeettojen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Saul sanoi palvelijoilleen: \"Etsikää minulle joku nainen, jolla on vallassaan vainajahenki, niin minä menen hänen luokseen ja kysyn häneltä.\" Hänen palvelijansa vastasivat hänelle: \"Katso, Een-Doorissa on nainen, jolla on vallassaan vainajahenki.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Saul tekeytyi tuntemattomaksi, pukeutui toisiin vaatteisiin ja lähti matkalle, mukanaan kaksi miestä. He tulivat yöllä naisen luo, ja hän sanoi: \"Ennusta minulle vainajahengen avulla ja nostata minulle se, jonka minä sinulle sanon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Mutta nainen vastasi hänelle: \"Sinä tiedät kyllä, mitä Saul on tehnyt, kuinka hän on hävittänyt vainaja- ja tietäjähenkien manaajat maasta. Miksi virität minulle ansan tuottaaksesi minulle kuoleman?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Saul vannoi hänelle Herran kautta ja sanoi: \"Niin totta kuin Herra elää: tästä asiasta sinulle ei koidu mitään syyllisyyttä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Nainen kysyi: \"Kenet minä nostatan sinulle?\" Hän vastasi: \"Nostata minulle Samuel.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Mutta kun nainen näki Samuelin, hän huusi kovalla äänellä. Nainen sanoi Saulille: \"Miksi olet pettänyt minut? Sinähän olet Saul.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Kuningas sanoi hänelle: \"Älä pelkää. Mitä sinä näet?\" Nainen vastasi Saulille: \"Minä näen jumal\'olennon nousevan maasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Hän kysyi häneltä: \"Minkä näköinen hän on?\" Nainen vastasi: \"Vanha mies nousee ylös viittaan verhoutuneena.\" Saul ymmärsi, että se oli Samuel, ja kumartui kasvoilleen maahan ja osoitti kunnioitusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Samuel sanoi Saulille: \"Miksi sinä olet häirinnyt minua ja nostattanut minut?\" Saul vastasi: \"Minä olen suuressa hädässä. Filistealaiset sotivat minua vastaan, ja Jumala on poistunut minusta eikä vastaa minulle enää, ei profeettojen kautta eikä unissa. Minä kutsutin sinut, että ilmoittaisit minulle, mitä minun on tehtävä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Samuel vastasi: \"Miksi kysyt minulta, kun Herra on poistunut sinusta ja tullut vihamieheksesi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Herra on tehnyt sen, minkä hän on kauttani puhunut: Herra on reväissyt kuninkuuden kädestäsi ja on antanut sen toiselle, Daavidille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Kun et kuullut Herran ääntä etkä tehnyt Amalekille, mitä hänen hehkuva vihansa vaati, sen tähden Herra on tänä päivänä tehnyt sinulle tämän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Herra antaa myös Israelin yhdessä kanssasi filistealaisten käsiin, ja huomenna olet poikinesi luonani. Myös Israelin leirin Herra antaa filistealaisten käsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Saul tuossa tuokiossa kaatui pitkin koko pituuttaan maahan, sillä hän pelästyi kovin Samuelin puheesta. Hänen voimansakin olivat häneltä lopussa, sillä vuorokauteen hän ei ollut syönyt mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Mutta nainen meni Saulin luo, ja kun hän näki, että tämä oli kauhun vallassa, hän sanoi hänelle: \"Katso, palvelijattaresi kuuli sinua, minä panin henkeni kämmenelleni ja tottelin käskyä, jonka sinä minulle lausuit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Kuule nyt sinäkin palvelijatartasi ja salli minun asettaa eteesi palanen leipää, ja syö, että olisit voimissasi, kun lähdet matkalle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Hän kieltäytyi ja sanoi: \"Minä en syö.\" Mutta kun hänen palvelijansa yhdessä naisen kanssa pyytämällä pyysivät häntä, hän kuuli heitä, nousi maasta ja istui vuoteelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Vaimolla oli juottovasikka kotonaan. Sen hän teurasti kiireesti. Sitten hän otti jauhoja, sotki ne ja leipoi niistä happamattomia leipiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Hän toi ruuan Saulin ja hänen palvelijoidensa eteen, ja he söivät. Sitten he nousivat ja lähtivät samana yönä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Filistealaiset kokosivat kaikki joukkonsa Afekiin, mutta israelilaiset olivat leiriytyneet lähteelle, joka on Jisreelissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Kun filistealaisten ruhtinaat tulivat satoineen ja tuhansineen, ja Daavid miehineen tuli viimeiseksi Aakiin kanssa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'filistealaisten päälliköt sanoivat: \"Mitä nuo heprealaiset täällä tekevät?\" Aakis vastasi filistealaisten päälliköille: \"Tämähän on Daavid, Saulin, Israelin kuninkaan, palvelija, joka on ollut luonani toista vuotta, enkä ole havainnut hänessä mitään vikaa siitä päivästä alkaen, jona hän siirtyi luokseni, tähän päivään asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Filistealaisten päälliköt vihastuivat häneen. Filistealaisten päälliköt sanoivat hänelle: \"Toimita mies takaisin. Palatkoon siihen paikkaan, jonka olet hänelle määrännyt. Älköön hän tulko kanssamme taisteluun, ettei hän taistelussa tulisi vastustajaksemme. Sillä miten hän voisi hankkia itselleen Herransa suosion paremmin kuin näiden miesten päillä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Eikö tämä ole se Daavid, jolle he karkeloiden virittivät tämän laulun: \'Saul voitti tuhat, mutta Daavid kymmenentuhatta\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Niin Aakis kutsui Daavidin ja sanoi hänelle: \"Niin totta kuin Herra elää: sinä olet rehellinen, ja minulle olisi mieleen, että olisit täällä leirissä, lähtisit ja tulisit kanssani. Sillä en ole havainnut mitään pahaa sinussa siitä päivästä alkaen, jona tulit luokseni, tähän päivään asti. Mutta ruhtinaille sinä et ole mieluinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Lähde siis takaisin ja mene rauhassa, ettet tekisi mitään, joka ei olisi filistealaisten ruhtinaille mieleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'Daavid sanoi Aakiille: \"Mitä olen tehnyt, ja mitä olet havainnut palvelijassasi siitä päivästä alkaen, jona tulin palvelukseesi, tähän päivään asti, koska en saa tulla taistelemaan herrani, kuninkaan, vihollisia vastaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Aakis vastasi ja sanoi Daavidille: \"Tiedän, että sinä olet minulle hyvä kuin Jumalan enkeli. Mutta filistealaisten päälliköt sanovat: \'Hän ei saa lähteä kanssamme taisteluun.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Nouse siis huomenna aamulla varhain, sinä ja herrasi palvelijat, jotka ovat tulleet kanssasi, ja lähtekää matkaan varhain huomenna aamulla, kun päivä valkenee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Daavid miehineen lähti varhain seuraavana aamuna matkalle palatakseen filistealaisten maahan, mutta filistealaiset menivät Jisreeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Kun Daavid miehineen kolmantena päivänä tuli Siklagiin, amalekilaiset olivat tehneet ryöstöretken Negeviin ja Siklagiin, ja he olivat vallanneet Siklagin ja polttaneet sen tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'Naiset, joita siellä oli, sekä pienet että suuret, he olivat ottaneet vangiksi surmaamatta ketään. He olivat vieneet heidät pois ja menneet matkoihinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Kun Daavid miehineen tuli kaupunkiin, katso, se oli poltettu tulella, ja heidän vaimonsa, poikansa ja tyttärensä oli otettu vangeiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Daavid ja väki, joka oli hänen kanssaan, korottivat äänensä ja itkivät, kunnes eivät enää jaksaneet itkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Vangeiksi oli otettu myös Daavidin molemmat vaimot, jisreeliläinen Ahinoam ja Abigail, karmelilaisen Naabalin [leski] vaimo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'Silloin Daavid joutui suureen hätään, sillä kansa aikoi kivittää hänet: niin katkeroitunut oli koko kansa, kukin poikiensa ja tyttäriensä tähden. Mutta Daavid rohkaisi mielensä Herrassa, Jumalassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Daavid sanoi pappi Ebjatarille, Ahimelekin pojalle: \"Tuo minulle kasukka.\" Ebjatar toi kasukan Daavidille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Daavid kysyi Herralta: \"Ajanko takaa tuota rosvojoukkoa? Saavutanko sen?\" Hän vastasi hänelle: \"Aja, sillä saavutat sen ja pelastat pelastettavat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Daavid lähti, hän ja ne kuusisataa miestä, jotka olivat hänen kanssaan, ja he tulivat Besorin purolle. Siihen pysähtyivät ne, jotka olivat jääneet muista jälkeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Mutta Daavid jatkoi takaa-ajoa neljänsadan miehen kanssa, sillä niitä, jotka väsyneinä pysähtyivät eivätkä menneet Besorin puron poikki, oli kaksisataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'He tapasivat kedolla egyptiläisen miehen ja toivat hänet Daavidin luo. He antoivat hänelle leipää syödä ja vettä juoda,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'ja vielä he antoivat hänelle syötäväksi viikunakakun ja kaksi rusinakakkua. Silloin hänen henkensä virkistyi, sillä hän ei ollut syönyt eikä juonut kolmeen vuorokauteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Daavid kysyi häneltä: \"Kenen miehiä olet ja mistä tulet?\" Hän vastasi: \"Minä olen egyptiläinen nuorukainen, erään amalekilaisen miehen palvelija. Mutta herrani jätti minut, sillä sairastuin kolme päivää sitten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Me teimme ryöstöretken kreettien, Juudan ja Kaalebin Negeviin ja poltimme Siklagin tulella.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'Daavid sanoi hänelle: \"Vietkö minut tuon rosvojoukon luo?\" Hän vastasi: \"Vanno minulle Jumalan kautta, ettet surmaa minua etkä luovuta minua herrani käsiin, niin vien sinut sen rosvojoukon luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Niin hän vei hänet sinne, ja katso, heitä oli hajallaan maassa kaikkialla syömässä, juomassa ja juhlimassa kaikkea sitä suurta saalista, jonka he olivat ottaneet filistealaisten maasta ja Juudan maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Daavid kaatoi heitä aamuhämärästä iltaan asti, eikä heistä pelastunut kuin neljäsataa nuorta miestä, jotka nousivat kamelien selkään ja pakenivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'Daavid pelasti kaikki, mitä amalekilaiset olivat ottaneet. Myös molemmat vaimonsa Daavid pelasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Ei ketään puuttunut, ei pientä eikä suurta, ei kenenkään poikaa eikä kenenkään tytärtä eikä saalista tai muuta, mitä he olivat ottaneet itselleen. Kaiken Daavid toi takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Daavid otti myös kaikki lampaat ja naudat, ja niitä ajettiin muun karjan edellä ja huudettiin: \"Tämä on Daavidin saalis!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Kun Daavid tuli niiden kahdensadan miehen luo, jotka olivat väsyneet, jaksamatta seurata Daavidia, ja jotka oli jätetty Besorin purolle, he tulivat Daavidia vastaan ja sitä väkeä, joka oli hänen kanssaan. Kun Daavid joukkoineen lähestyi, hän tervehti heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Mutta kaikenlaiset huonot ja kelvottomat miehet niiden joukosta, jotka olivat kulkeneet Daavidin mukana, rupesivat sanomaan: \"Koska nämä eivät ole kulkeneet mukanamme, emme anna heille mitään saaliista, jonka pelastimme, paitsi kunkin vaimon ja lapset. Ottakoot ne ja menkööt matkoihinsa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Mutta Daavid sanoi: \"Älkää tehkö niin, veljeni, sen jälkeen, mitä Herra on meille suonut, kun hän varjeli meidät ja antoi käsiimme rosvojoukon, joka hyökkäsi kimppuumme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Kukapa teitä kuulisi tässä asiassa? Sillä taisteluun menevällä ja kuormaston luo jäävällä on oleva yhtäläinen osuus. Heidän on jaettava tasan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Silleen asia jäi silloin ja sen jälkeenkin: hän teki sen säännöksi ja tavaksi Israelissa aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Kun Daavid tuli Siklagiin, hän lähetti osan saaliista Juudan vanhimmille, ystävilleen, sanoen: \"Tässä on teille tervehdyslahja siitä saaliista, joka otettiin Herran vihollisilta\" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'lahja niille, jotka olivat Beetelissä, Negevin Raamotissa, Jattirissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'Aroerissa, Sifmotissa, Estemoassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'Raakalissa, jerahmeelilaisten kaupungeissa, keeniläisten kaupungeissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'Hormassa, Boor-Aasanissa, Atakissa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'ja Hebronissa, ja samoin lahja kaikille muille paikkakunnille, joissa Daavid miehineen oli kulkenut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Filistealaiset taistelivat Israelia vastaan. Israelin miehet pakenivat filistealaisia, ja heitä kaatui surmattuina Gilboan vuorella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Filistealaiset pääsivät Saulin ja hänen poikiensa kintereille, ja filistealaiset surmasivat Joonatanin, Abinadabin ja Malkisuan, Saulin pojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Kun taistelu kiihtyi ankaraksi Saulia vastaan ja jousimiehet keksivät hänet, hän joutui suureen hätään jousimiesten ahdistaessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Saul sanoi aseenkantajalleen: \"Paljasta miekkasi ja lävistä sillä minut, etteivät nuo ympärileikkaamattomat tulisi lävistämään minua ja pitämään minua pilkkanaan.\" Mutta hänen aseenkantajansa ei tahtonut, sillä hän pelkäsi kovin. Saul itse otti miekan ja heittäytyi siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Mutta kun hänen aseenkantajansa näki, että Saul oli kuollut, hänkin heittäytyi miekkaansa ja kuoli hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Niin kuolivat sinä päivänä yhdessä Saul, hänen kolme poikaansa ja hänen aseenkantajansa sekä kaikki hänen miehensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Kun Israelin miehet, jotka asuivat laakson tuolla puolen ja Jordanin tuolla puolen, huomasivat, että Israelin miehet olivat paenneet ja että Saul poikineen oli kuollut, he jättivät kaupungit ja pakenivat, ja filistealaiset tulivat ja asettuivat niihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Seuraavana päivänä filistealaiset tulivat ryöstämään surmattuja ja löysivät Saulin ja hänen kolme poikaansa kaatuneina Gilboan vuorella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'He löivät häneltä pään poikki, ryöstivät häneltä aseet ja lähettivät ne ympäri filistealaisten maata julistaakseen voitonsanomaa epäjumaliensa temppeleissä ja kansan seassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'He asettivat hänen aseensa Astarten temppeliin, mutta hänen ruumiinsa he kiinnittivät Beet-Seanin muurille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Kun Gileadin Jaabeksen asukkaat kuulivat, mitä filistealaiset olivat tehneet Saulille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'he nousivat, kaikki sotakuntoiset miehet kulkivat kaiken yötä ja ottivat Saulin ja hänen poikiensa ruumiit alas Beet-Seanin muurilta, menivät Jaabekseen ja polttivat ne siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Sitten he ottivat heidän luunsa, hautasivat ne tamariskipuun alle Jaabekseen ja paastosivat seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Tapahtui Saulin kuoleman jälkeen, että Daavid voitettuaan amalekilaiset oli palannut takaisin ja ollut Siklagissa pari päivää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'kolmantena päivänä tuli eräs mies leiristä Saulin luota vaatteet reväistyinä ja multaa pään päällä. Kun hän tuli Daavidin luo, hän lankesi ja kumartui maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'Daavid kysyi häneltä: \"Mistä tulet?\" Hän vastasi hänelle: \"Minä olen päässyt pakoon Israelin leiristä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'Daavid sanoi hänelle: \"Miten asiat ovat? Kerro minulle.\" Hän vastasi: \"Väki on paennut taistelusta, paljon väkeä on kaatunut ja kuollut, myös Saul ja hänen poikansa Joonatan ovat kuolleet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Daavid kysyi nuorelta mieheltä, joka kertoi tämän hänelle: \"Mistä tiedät, että Saul ja hänen poikansa Joonatan ovat kuolleet?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Nuorukainen, joka oli kertonut hänelle tämän, vastasi: \"Minä tulin sattumalta Gilboan vuorelle, ja katso, Saul nojasi keihääseensä, ja sotavaunut ja ratsumiehet ahdistivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Hän kääntyi taakseen ja nähdessään minut hän huusi minua. Vastasin: \'Tässä olen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Niin hän kysyi minulta: \'Kuka olet?\' Vastasin hänelle: \'Olen amalekilainen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Sitten hän sanoi minulle: \'Asetu vierelleni seisomaan ja surmaa minut, sillä minä olen kangistumassa, vaikka olenkin vielä täysin hengissä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Niin astuin hänen luokseen ja surmasin hänet, sillä käsitin, ettei hän kaatumisensa jälkeen jäisi henkiin. Sitten otin kruunun, joka oli hänen päässään, ja rannerenkaan, joka oli hänen käsivarressaan, ja toin ne tänne herralleni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Daavid tarttui vaatteisiinsa ja repäisi ne, samoin tekivät kaikki miehet, jotka olivat hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'He pitivät valittajaisia ja itkivät ja paastosivat iltaan asti Saulin ja hänen poikansa Joonatanin tähden ja Herran kansan tähden ja Israelin heimon tähden, koska he olivat kaatuneet miekkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Daavid kysyi nuorukaiselta, joka oli hänelle kertonut tämän: \"Mistä sinä olet?\" Hän vastasi: \"Minä olen muukalaisen, amalekilaisen miehen poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Daavid sanoi hänelle: \"Kuinka et pelännyt ojentaa kättäsi tuhotaksesi Herran voidellun?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Daavid kutsui yhden palvelijoistaan ja sanoi: \"Käy tänne, lyö hänet kuoliaaksi.\" Ja hän iski hänet kuoliaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Mutta Daavid sanoi hänelle: \"Sinun veresi tulkoon oman pääsi päälle, sillä oma suusi on todistanut sinua vastaan, kun sanoit: \'Minä olen surmannut Herran voidellun.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Daavid viritti tämän itkuvirren Saulista ja hänen pojastaan Joonatanista');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'ja käski opettaa sen, \"Jousilaulun\", Juudan pojille: katso, se on kirjoitettuna \"Oikeamielisen kirjassa\":');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, '\"Kaunistuksesi, Israel, on surmattuna kukkuloillasi. Kuinka ovatkaan sankarit kaatuneet!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Älkää ilmoittako sitä Gatissa, älkää julistako voitonsanomaa Askelonin kaduilla, etteivät filistealaisten tyttäret iloitsisi, etteivät ympärileikkaamattomien tyttäret riemuitsisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Te Gilboan vuoret, älköön teille kastetta tulko, älköön sadetta, älköön peltoja, joista anteja uhrataan. Sillä sinne on heitetty pois sankarien kilpi, Saulin kilpi, öljyllä voitelemattomana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Kaatuneitten verta, sankarien rasvaa Joonatanin jousi ei väistänyt, eikä palannut tyhjänä Saulin miekka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul ja Joonatan, rakkaat ja armaat, olivat elämässä ja kuolemassa erottamattomat, olivat nopeammat kuin kotkat, leijonia väkevämmät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Te Israelin tyttäret, itkekää Saulia, häntä, joka puetti teidät purppuraan ja koruihin, joka kiinnitti pukuunne kultakoristeita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Kuinka ovat sankarit taistelussa kaatuneet! Joonatan on surmattuna kukkuloillasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Minä suren sinua, veljeni Joonatan. Sinä olit minulle hyvin rakas. Rakkautesi oli minulle ihmeellisempi kuin naisen rakkaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Kuinka ovatkaan sankarit kaatuneet, kuinka ovat hukkuneet taisteluaseet!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Sen jälkeen tapahtui, että Daavid kysyi Herralta: \"Menenkö ylös johonkin Juudan kaupunkiin?\" Herra vastasi hänelle: \"Mene.\" Vielä Daavid kysyi: \"Mihin [kaupunkiin] menen?\" Hän vastasi: \"Hebroniin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Daavid meni sinne mukanaan molemmat vaimonsa, jisreeliläinen Ahinoam ja Abigail, karmelilaisen Naabalin [leski] vaimo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Daavid vei sinne myös miehet, jotka olivat hänen kanssaan, kunkin perheineen, ja he asettuivat Hebronin ympärillä oleviin kaupunkeihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Sitten Juudan miehet tulivat ja voitelivat siellä Daavidin Juudan heimon kuninkaaksi. Kun Daavidille ilmoitettiin, että Gileadin Jaabeksen miehet olivat haudanneet Saulin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Daavid lähetti lähettiläät Gileadin Jaabeksen miesten luo sanomaan heille: \" Herra siunatkoon teitä, koska olette osoittaneet herrallenne Saulille laupeutta hautaamalla hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Osoittakoon Herra nyt laupeutta ja uskollisuutta teitä kohtaan. Minäkin teen teille hyvää, koska tämän teitte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Rohkaiskaa siis itsenne ja olkaa urhoolliset. Tosin teidän herranne Saul on kuollut, mutta Juudan heimo on voidellut minut kuninkaakseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Mutta Abner, Neerin poika, Saulin sotapäällikkö, otti Saulin pojan Iisbosetin ja vei hänet Mahanaimiin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'ja asetti hänet Gileadin, Asurin, Jisreelin, Efraimin, Benjaminin ja koko Israelin kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Saulin poika Iisboset oli neljänkymmenen vuoden vanha tullessaan Israelin kuninkaaksi ja hallitsi kaksi vuotta. Ainoastaan Juudan heimo seurasi Daavidia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Aika, minkä Daavid oli Juudan heimon kuninkaana Hebronissa, oli seitsemän vuotta ja kuusi kuukautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Abner, Neerin poika, ja Saulin pojan Iisbosetin palvelijat lähtivät Mahanaimista Gibeoniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Jooab, Serujan poika, ja Daavidin palvelijat lähtivät hekin liikkeelle ja kohtasivat toisensa Gibeonin lammikolla. He asettuivat toiset tälle, toiset tuolle puolelle lammikkoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Silloin Abner sanoi Jooabille: \"Nouskoon nuoria miehiä pitämään taistelukisaa edessämme.\" Jooab sanoi: \"Nouskoon vain.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Heitä nousi ja astui esiin sama määrä: kaksitoista Benjaminin ja Saulin pojan Iisbosetin puolelta sekä kaksitoista Daavidin palvelijaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'He tarttuivat kukin vastustajaansa päästä ja pistivät miekkansa toinen toisensa kylkeen ja kaatuivat yhdessä. Niin sen paikan nimeksi tuli Helkat-Suurim. Se on Gibeonin luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Sinä päivänä syntyi erittäin kova taistelu, mutta Daavidin palvelijat voittivat Abnerin ja Israelin miehet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Siellä oli kolme Serujan poikaa: Jooab, Abisai ja Asael. Mutta Asael oli nopeajalkainen kuin gaselli kedolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Asael ajoi takaa Abneria eikä poikennut oikealle eikä vasemmalle Abnerin jäljestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Abner kääntyi taakseen ja sanoi: \"Sinäkö se olet, Asael?\" Hän vastasi: \"Minä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Abner sanoi hänelle: \"Käänny oikealle tai vasemmalle ja ota joku noista nuorukaisista kiinni ja riistä häneltä sota-asu.\" Mutta Asael ei tahtonut luopua hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Abner vielä kerran sanoi Asaelille: \"Luovu minusta, muuten lyön sinut maahan. Mutta kuinka sitten voisin katsoa veljeäsi Jooabia silmiin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Mutta kun hän ei tahtonut luopua hänestä, Abner pisti häntä keihään varsipuolella vatsaan, niin että keihäs tuli takaa ulos. Niin hän kaatui ja kuoli siihen paikkaan. Jokainen, joka tuli siihen paikkaan, mihin Asael oli kaatunut ja kuollut, pysähtyi siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Mutta Jooab ja Abisai ajoivat Abneria takaa ja tulivat, kun aurinko oli laskenut, Amman kukkulalle, joka on vastapäätä Giiahia, Gibeonin erämaahan päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Benjaminilaiset kokoontuivat Abnerin taakse yhteen joukkoon ja asettuivat kukkulan laelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Abner huusi Jooabille ja sanoi: \"Pitääkö miekan syödä ikuisesti? Etkö ymmärrä, että siitä tulee vain katkeruutta perästäpäin? Etkö jo käske väen lakata ajamasta takaa veljiään?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Jooab vastasi: \"Niin totta kuin Jumala elää: jos et olisi puhunut, varmasti väki olisi vasta huomenaamulla lähtenyt pois ajamasta takaa veljiään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Jooab puhalsi torveen, ja kaikki väki pysähtyi eikä enää ajanut takaa Israelia, eivätkä he enää taistelleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Abner ja hänen miehensä kulkivat koko sen yön Aromaata ja menivät Jordanin yli, vaelsivat koko Bitronin läpi ja tulivat Mahanaimiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Jooab kokosi kaiken kansan palattuaan ajamasta takaa Abneria. Daavidin palvelijoista puuttui yhdeksäntoista miestä ja Asael.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Daavidin palvelijat olivat lyöneet benjaminilaisia ja Abnerin miehiä kuoliaaksi kolmesataa kuusikymmentä miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'He ottivat Asaelin ja hautasivat hänet hänen isänsä hautaan Beetlehemiin. Jooab ja hänen miehensä kulkivat koko sen yön ja tulivat päivän valjetessa Hebroniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Sota Saulin suvun ja Daavidin suvun välillä pitkittyi. Daavid vahvistui vahvistumistaan, mutta Saulin suku heikkeni heikkenemistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Daavidille syntyi poikia Hebronissa. Hänen esikoisensa oli Amnon, jonka äiti oli jisreeliläinen Ahinoam.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'Hänen toinen poikansa oli Kilab, jonka äiti oli Abigail, karmelilaisen Naabalin [leski] vaimo. Kolmas oli Absalom, Gesurin kuninkaan Talmain tyttären, Maakan, poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'Neljäs oli Adonia, Haggitin poika, ja viides Sefatja, Abitalin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'Kuudes oli Jitream, Daavidin vaimon Eglan poika. Nämä syntyivät Daavidille Hebronissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Niin kauan kuin sota oli Saulin suvun ja Daavidin suvun välillä, piti Abner voimakkaasti Saulin suvun puolta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Saulilla oli ollut sivuvaimo, nimeltä Rispa, Aijan tytär. Iisboset sanoi Abnerille: \"Miksi olet mennyt isäni sivuvaimon luo?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Abner vihastui kovin Iisbosetin sanoista ja sanoi: \"Olenko minä koiranpää, Juudasta kotoisin? Kun nytkin osoitan laupeutta isäsi Saulin suvulle, hänen veljilleen ja ystävilleen enkä ole antanut sinun joutua Daavidin käsiin, niin kuitenkin nyt syytät minua rikoksen teosta naiselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Jumala rangaiskoon Abneria nyt ja vasta, jos en tee Daavidille, niin kuin Herra on hänelle vannonut:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'otan pois kuninkuuden Saulin suvulta ja pystytän Daavidille valtaistuimen Israeliin ja Juudaan, Daanista aina Beersebaan asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Hän ei voinut enää vastata Abnerille sanaakaan, sillä hän pelkäsi häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Mutta Abner lähetti sanansaattajia Daavidin luo sanomaan: \"Kenen on maa?\" ja vielä näin: \"Tee liitto kanssani. Katso, käteni on oleva kanssasi ja kääntävä koko Israelin puolellesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Hän vastasi: \"Hyvä, minä teen liiton kanssasi. Yhtä minä kuitenkin vaadin sinulta: älä astu kasvojeni eteen tuomatta Miikalia, Saulin tytärtä, kun tulet astuaksesi kasvojeni eteen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Sitten Daavid lähetti sanansaattajat Iisbosetin, Saulin pojan, luo sanomaan: \"Anna minulle vaimoni Miikal, jonka olen kihlannut itselleni sadalla filistealaisten esinahalla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Iisboset lähetti ottamaan hänet hänen mieheltään Paltielilta, Laiksen pojalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Hänen miehensä lähti hänen mukanaan ja seurasi häntä aina Bahurimiin asti itkien lakkaamatta. Abner sanoi hänelle: \"Mene tiehesi, palaa takaisin.\" Hän palasi takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Abner oli neuvotellut Israelin vanhinten kanssa sanoen: \"Jo kauan olette halunneet saada Daavidin kuninkaaksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Pankaa se nyt toimeen, sillä Herra on sanonut Daavidille näin: \'Palvelijani Daavidin kädellä vapautan kansani Israelin filistealaisten käsistä ja kaikkien heidän vihollistensa käsistä.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Abner puhui tämän myös benjaminilaisille, ja Abner meni ja puhui Daavidillekin Hebronissa, mitä mieltä Israel ja koko Benjaminin heimo olivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Kun Abner tuli Daavidin luo Hebroniin, mukanaan kaksikymmentä miestä, Daavid laittoi pidot Abnerille ja miehille, jotka olivat hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Abner sanoi Daavidille: \"Nousen ja menen kokoamaan kaiken Israelin herrani, kuninkaan, luo, että he tekisivät liiton kanssasi ja saisit hallittaviksesi kaikki, joita haluat.\" Daavid päästi Abnerin menemään, ja hän lähti rauhassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Katso, Daavidin palvelijat ja Jooab tulivat ryöstöretkeltä ja toivat mukanaan paljon saalista. Mutta Abner ei ollut enää Daavidin luona Hebronissa, sillä tämä oli päästänyt hänet menemään, ja hän oli lähtenyt rauhassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Kun Jooab ja kaikki sotaväki, joka oli hänen kanssaan, tulivat, kerrottiin Jooabille: \"Abner, Neerin poika, tuli kuninkaan luo, ja hän päästi hänet menemään, ja hän lähti rauhassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Silloin Jooab meni kuninkaan luo ja sanoi: \"Mitä olet tehnyt? Katso, Abner tuli luoksesi, miksi päästit hänet menemään menojaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Etkö ymmärrä, että Abner, Neerin poika, tuli pettämään sinua ja urkkimaan lähtöäsi ja tuloasi ja kaikkea, mitä teet?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Jooab lähti Daavidin luota ja lähetti sanansaattajat Abnerin jälkeen, ja he palauttivat hänet takaisin Boor-Siirasta, eikä Daavid tiennyt siitä mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Kun Abner tuli takaisin Hebroniin, Jooab vei hänet syrjään porttiholvin keskelle muka puhutellakseen häntä kahden kesken, ja pisti häntä siellä vatsaan, niin että hän kuoli Jooabin veljen Asaelin veren tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Kun Daavid sitten sai sen kuulla, hän sanoi: \"Abnerin, Neerin pojan, vereen minä olen viaton ja myös kuninkuuteni Herran edessä iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Tulkoon se Jooabin pään päälle ja kaiken hänen isänsä perheen päälle, älköötkä Jooabin suvusta loppuko vuotoa tai spitaalia sairastavat, kainalosauvoilla kulkijat, miekkaan kaatuvat ja leivän puutteessa olijat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Näin Jooab ja hänen veljensä Abisai tappoivat Abnerin, sen tähden että tämä oli surmannut heidän veljensä Asaelin taistelussa Gibeonin luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Mutta Daavid sanoi Jooabille ja kaikelle väelle, joka oli hänen kanssaan: \"Reväiskää vaatteenne ja kääriytykää säkkeihin ja pitäkää valittajaiset Abnerille.\" Kuningas Daavid kulki paarien perässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'He hautasivat Abnerin Hebroniin, ja kuningas korotti äänensä ja itki Abnerin haudalla, ja kaikki kansa itki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Kuningas viritti itkuvirren Abnerista ja sanoi: \"Pitikö Abnerin kuolla, niin kuin houkka kuolee?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Eivät olleet kätesi sidotut eivätkä jalkasi vaskikahleisiin pannut. Sinä kaaduit, kuin kaadutaan vilpillisten käden kautta.\" Kaikki kansa itki häntä vielä enemmän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Sitten kaikki kansa tuli, kun vielä oli päivä, vaatimaan, että Daavid söisi jotakin. Mutta Daavid vannoi sanoen: \"Jumala rangaiskoon minua nyt ja vasta, jos maistan leipää tai muuta, ennen kuin aurinko laskee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Kun kaikki kansa sai kuulla sen, se miellytti heitä, samoin kuin kaikelle kansalle oli mieleen kaikki muukin, mitä kuningas teki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Kaikki kansa ja koko Israel ymmärsivät sinä päivänä, että Abnerin, Neerin pojan, surma ei ollut lähtenyt kuninkaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Kuningas sanoi palvelijoilleen: \"Ettekö tiedä, että ruhtinas ja suuri mies on tänä päivänä kaatunut Israelissa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Minä olen kuitenkin vielä heikko, vaikka minut on voideltu kuninkaaksi, mutta nuo miehet, Serujan pojat, ovat liian väkivaltaisia minun hillitä. Herra maksakoon sille, joka tekee pahaa, hänen pahuutensa mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Kun Saulin poika kuuli Abnerin kuolleen Hebronissa, hänen kätensä herposivat, ja koko Israel pelästyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Saulin pojalla oli partiojoukkojen päämiehinä kaksi miestä, toisen nimi oli Baana ja toisen Reekab, beerotilaisen Rimmonin poikia, benjaminilaisia, sillä Beerotkin luetaan kuuluvaksi Benjaminiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Mutta beerotilaiset olivat paenneet Gittaimiin ja asuivat siellä muukalaisina, niin kuin he asuvat vielä tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Joonatanilla, Saulin pojalla, oli poika, joka oli rampa jaloistaan. Hän oli viiden vuoden vanha, kun sanoma Saulista ja Joonatanista tuli Jisreelistä. Hänen hoitajansa otti hänet mukaansa ja pakeni. Mutta kun tämä hätääntyneenä pakeni, poika putosi ja tuli ontuvaksi, ja hänen nimensä oli Mefiboset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Beerotilaisen Rimmonin pojat Reekab ja Baana lähtivät matkaan ja tulivat päivän ollessa palavimmillaan Iisbosetin taloon, kun hän oli päivälevolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Katso, he tulivat silloin sisälle taloon muka ottamaan vehnänjyviä, mutta pistivät häntä vatsaan. Mutta Reekab ja hänen veljensä Baana pääsivät pakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'He tulivat taloon, kun hän lepäsi vuoteellaan makuuhuoneessaan, pistivät hänet kuoliaaksi, löivät häneltä pään poikki ja ottivat sen mukaansa. He kulkivat sitten Aromaan tietä koko yön,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'toivat Iisbosetin pään Daavidille Hebroniin ja sanoivat kuninkaalle: \"Katso, tässä on Iisbosetin, Saulin pojan, sinun vihamiehesi, pää, hänen, joka väijyi henkeäsi. Herra on tänä päivänä kostanut Saulille ja hänen jälkeläisilleen herrani, kuninkaan, puolesta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Niin Daavid vastasi Reekabille ja hänen veljelleen Baanalle, beerotilaisen Rimmonin pojille, ja sanoi heille: \"Niin totta kuin Herra elää, joka on vapahtanut minut kaikesta hädästä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'Se, joka ilmoitti minulle ja sanoi: \'Katso, Saul on kuollut\', luuli tuovansa ilosanoman. Mutta minä otatin hänet kiinni ja surmautin Siklagissa antaakseni hänelle sanantuojan palkan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Eikö minun nyt paljoa suuremmassa määrin, kun jumalattomat miehet ovat murhanneet syyttömän miehen hänen omassa kodissaan hänen vuoteeseensa, ole vaadittava hänen verensä kädestänne ja hävitettävä teidät maan päältä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Daavid käski nuorukaisten surmata heidät. He hakkasivat poikki heidän kätensä ja jalkansa ja hirttivät heidät Hebronin lammikon rannalle. Mutta Iisbosetin pään he ottivat ja hautasivat sen Abnerin hautaan Hebroniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Kaikki Israelin sukukunnat tulivat Daavidin luo Hebroniin ja sanoivat näin: \"Katso, me olemme sinun luutasi ja lihaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Jo aikaisemmin Saulin vielä ollessa kuninkaanamme sinä saatoit Israelin lähtemään ja tulemaan. Sinulle Herra on sanonut: \'Sinä olet kaitseva kansaani Israelia, ja sinä olet oleva Israelin ruhtinas.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Kaikki Israelin vanhimmat olivat tulleet kuninkaan luo Hebroniin, ja kuningas Daavid teki heidän kanssaan liiton Hebronissa Herran edessä. He voitelivat Daavidin Israelin kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Daavid oli kolmenkymmenen vuoden vanha tullessaan kuninkaaksi ja hallitsi neljäkymmentä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'Hebronissa hän hallitsi Juudaa seitsemän vuotta ja kuusi kuukautta, ja Jerusalemissa hän hallitsi koko Israelia ja Juudaa kolmekymmentä kolme vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Kuningas meni miehineen Jerusalemiin jebusilaisia vastaan, jotka asuivat siinä maassa. He sanoivat Daavidille näin: \"Tänne sinä et tule, vaan sokeat ja ontuvat karkottavat sinut sanomalla: \'Ei tule Daavid tänne.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Mutta Daavid valloitti Siionin Vuorilinnan, se on Daavidin kaupungin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Daavid sanoi sinä päivänä: \"Jokainen, joka surmaa jebusilaisen ja tunkeutuu vesijohdolle asti, voittaa ne sokeat ja ontuvat, joita Daavid vihaa.\" Sen tähden on tapana sanoa: \"Sokea ja ontuva älköön tulko taloon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'Daavid asettui Vuorilinnaan ja kutsui sen Daavidin kaupungiksi. Daavid rakensi Millon ympäristössä ja talonsa sisällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Daavid tuli yhä mahtavammaksi, ja Herra, Jumala Sebaot, oli hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Hiiram, Tyyron kuningas, lähetti sanansaattajat Daavidin luo sekä setripuita, puuseppiä ja kivenhakkaajia, ja nämä rakensivat Daavidille palatsin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Daavid ymmärsi, että Herra oli vahvistanut hänet Israelin kuninkaaksi ja korottanut hänen kuninkuutensa kansansa Israelin tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Hebronista tultuaan Daavid oli ottanut Jerusalemista vielä useampia sivuvaimoja ja vaimoja. Daavidille syntyi vielä poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Nämä ovat niiden poikien nimet, jotka syntyivät hänelle Jerusalemissa: Sammua, Soobab, Naatan, Salomo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Jibhar, Elisua, Nefeg, Jaafia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Elisama, Eljada ja Elifelet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Kun filistealaiset kuulivat, että Daavid oli voideltu Israelin kuninkaaksi, kaikki filistealaiset lähtivät etsimään Daavidia. Kun Daavid sen kuuli, hän meni alas Vuorilinnaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Kun filistealaiset olivat tulleet ja levittäytyneet Refaimin tasangolle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Daavid kysyi Herralta: \"Menenkö filistealaisia vastaan? Annatko heidät käsiini?\" Herra sanoi Daavidille: \"Mene, sillä tosiaan annan filistealaiset käsiisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Daavid tuli Baal-Perasimiin. Siellä Daavid voitti heidät ja sanoi: \" Herra on murtanut viholliseni edessäni, niin kuin vedet murtavat.\" Siitä sen paikan nimeksi tuli Baal-Perasim.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'He jättivät siihen epäjumalankuvansa, ja Daavid ja hänen miehensä veivät ne pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Filistealaiset tulivat vielä kerran ja levittäytyivät Refaimin tasangolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Daavid kysyi Herralta, ja hän vastasi: \"Älä mene heitä vastaan, vaan kierrä heidät takaapäin ja hyökkää heidän kimppuunsa balsamipuiden puolelta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Kun kuulet astunnan kahinan balsamipuiden latvoista, ryntää nopeasti, sillä silloin Herra on käynyt edelläsi tuhotakseen filistealaisten leirin.\" Daavid teki, niin kuin Herra oli häntä käskenyt, ja hän voitti filistealaiset ja ajoi heitä takaa Gebasta aina Geseriin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, '');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Daavid kokosi jälleen kaikki valiomiehet Israelista, kolmekymmentä tuhatta miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Daavid ja kaikki väki, joka oli hänen kanssaan, nousi ja lähti Juudan Baalasta, tuomaan sieltä Jumalan arkkia, jonka Herra Sebaot oli ottanut nimiinsä, hän, jonka istuinta kerubit kannattavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'He panivat Jumalan arkin uusiin vaunuihin ja veivät sen pois Abinadabin talosta, joka oli mäellä, ja Ussa ja Ahjo, Abinadabin pojat, ohjasivat uusia vaunuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'He veivät Jumalan arkin pois Abinadabin talosta, joka oli mäellä, kulkien Jumalan arkin mukana, ja Ahjo kulki arkin edellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Daavid sekä koko Israelin heimo karkeloi kaikin voimin Herran edessä soittaen kaikilla sypressipuisilla soittimilla, lyyroilla, harpuilla, tamburiineilla, helistimillä ja symbaaleilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Kun he tulivat Naakonin puimatantereen luo, Ussa ojensi kätensä Jumalan arkkiin ja tarttui siihen, sillä härät kompastuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Herran viha syttyi Ussaa kohtaan, ja Jumala löi hänet siinä hänen hairahduksensa tähden, niin että hän kuoli siihen Jumalan arkin ääreen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Mutta Daavid pahastui siitä, että Herra niin oli murtanut Ussan. Siitä paikka sai nimekseen Peres-Ussa aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Daavid pelästyi sinä päivänä Herraa, niin että hän sanoi: \"Kuinka Herran arkki voi tulla luokseni?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Daavid ei tahtonut siirtää Herran arkkia luokseen Daavidin kaupunkiin, vaan Daavid toimitti sen syrjään gatilaisen Oobed-Edomin taloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'Herran arkki jäi kolmeksi kuukaudeksi gatilaisen Oobed-Edomin taloon. Herra siunasi Oobed-Edomia ja koko hänen taloaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Kun kuningas Daavidille kerrottiin, että Herra oli Jumalan arkin tähden siunannut Oobed-Edomin taloa ja kaikkea, mitä hänellä oli, Daavid meni ja toi riemuiten Jumalan arkin Oobed-Edomin talosta Daavidin kaupunkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Kun Herran arkin kantajat olivat astuneet kuusi askelta, hän uhrasi härän ja juottovasikan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Daavid hyppi kaikin voimin Herran edessä, ja Daavid oli puettu pellavakasukkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Daavid ja koko Israelin heimo toivat Herran arkin riemun raikuessa ja torvien raikuessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Kun Herran arkki tuli Daavidin kaupunkiin, katseli Miikal, Saulin tytär, ikkunasta. Nähdessään kuningas Daavidin karkeloivan ja hyppivän Herran edessä hän halveksi häntä sydämessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Kun he olivat tuoneet Herran arkin ja asettaneet sen paikalleen majaan, jonka Daavid oli sille pystyttänyt, Daavid uhrasi polttouhreja ja rauhanuhreja Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Kun Daavid oli uhrannut polttouhrin ja rauhanuhrit, hän siunasi kansan Herran Sebaotin nimeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Hän jakoi koko kansalle, koko Israelin joukolle, sekä miehille että naisille, kullekin leipäkakun, palan lihaa ja rypälekakun. Sitten kaikki kansa lähti, kukin kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Kun Daavid palasi takaisin tervehtimään perhettään, Miikal, Saulin tytär, meni ulos Daavidia vastaan ja sanoi: \"Kuinka arvokkaana onkaan Israelin kuningas nyt esiintynyt, kun on tänä päivänä paljastanut itsensä palvelijainsa palvelijattarien silmien edessä, niin kuin kevytmielinen ihminen paljastaa itsensä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Daavid sanoi Miikalille: \" Herran edessä, joka on valinnut minut, ohi isäsi ja koko hänen sukunsa, ja asettanut minut Herran kansan, Israelin, ruhtinaaksi – Herran edessä minä karkeloin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'Tähänkin minä pidän itseni liian vähäisenä ja olen omissa silmissäni halpa. Mutta ne palvelijattaret, joista puhuit, tulevat minua kunnioittamaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Miikal, Saulin tytär, ei saanut lasta kuolinpäiväänsä asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Kerran, kun kuningas istui linnassaan, sitten kun Herra oli suonut hänen päästä rauhaan kaikilta hänen ympärillään olevilta vihollisilta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'kuningas sanoi profeetta Naatanille: \"Katso, minä asun setripuisessa linnassa, mutta Jumalan arkki asuu telttakankaan suojassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Naatan sanoi kuninkaalle: \"Tee vain kaikki, mitä mielessäsi on, sillä Herra on kanssasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Mutta sinä yönä tapahtui, että Naatanille tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, '\"Mene ja sano palvelijalleni Daavidille: Näin sanoo Herra: Sinäkö rakentaisit minulle huoneen asuakseni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Enhän ole asunut huoneessa siitä päivästä asti, jona johdatin israelilaiset Egyptistä, tähän päivään saakka, vaan olen vaeltanut asuen teltta-asumuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Olenko koskaan, missä olenkin vaeltanut kaikkien israelilaisten keskuudessa, millekään Israelin sukukunnalle, jonka olen asettanut kaitsemaan kansaani Israelia, sanonut näin: Miksi ette ole rakentaneet minulle setripuista huonetta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Sano nyt palvelijalleni Daavidille: Näin sanoo Herra Sebaot: Minä olen ottanut sinut laitumelta lammasten jäljestä kansani Israelin ruhtinaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'Olen ollut kanssasi kaikkialla, missä vaelsit, ja olen hävittänyt kaikki vihollisesi tieltäsi. Teen sinulle suuren nimen, suurimpien nimien vertaisen maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Valmistan sijan kansalleni Israelille ja istutan sen niin, että se asuu paikallaan eikä enää ole levoton, eivätkä vääryyden tekijät sitä enää sorra kuten ennen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'siitä päivästä saakka, jolloin asetin tuomareita kansalleni Israelille, ja annan sinun päästä rauhaan kaikista vihollisistasi. Herra ilmoittaa sinulle, että Herra on tekevä sinulle huoneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Kun päiväsi ovat päättyneet ja lepäät isiesi luona, minä korotan sinun seuraajaksesi jälkeläisesi, joka lähtee ruumiistasi, ja vahvistan hänen kuninkuutensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Hän on rakentava huoneen nimelleni, ja vahvistan hänen valtaistuimensa ikuisiksi ajoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Minä olen oleva hänen Isänsä ja hän minun Poikani, niin että, jos hän tekee väärin, minä rankaisen häntä ihmisvitsalla, niin kuin ihmislapsia lyödään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'mutta armoni ei poistu hänestä, niin kuin poistin sen Saulista, jonka poistin tieltäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Sukusi ja kuninkuutesi pysyvät edessäsi iäti, ja valtaistuimesi on oleva iäti vahva.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Aivan näillä sanoilla ja tämän näyn mukaan Naatan puhui Daavidille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Kuningas Daavid meni ja asettui Herran eteen ja sanoi: \"Mikä olen minä, Herra, Herra, ja mikä on sukuni, että olet saattanut minut tähän asti?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Mutta tämäkin on ollut vähän silmissäsi, Herra Herra, ja niin olet sinä puhunut palvelijasi suvulle myös kaukaisista asioista. Tämä on sen ihmisen tapa, joka on Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Mitä Daavid enää sinulle puhuisi? Sinähän tunnet palvelijasi, Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Sanasi tähden ja mielesi mukaan sinä olet tehnyt sen, että ilmoitit palvelijallesi kaikki nämä suuret asiat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Sen tähden olet sinä, Herra Jumala, suuri. Sillä kaiken sen mukaan, mitä olemme korvillamme kuulleet, ei ole vertaistasi, eikä ole muuta jumalaa kuin sinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Missä maan päällä on toista kansaa kansasi Israelin vertaista, jota Jumala itse on käynyt lunastamaan kansakseen tehdäkseen sen nimen kuuluisaksi ja tehdäkseen teille, maallesi, suuria ja pelottavia tekoja kansasi edessä, jonka lunastit itsellesi Egyptistä, pakanoiden ja heidän jumaliensa vallasta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Olet valmistanut itsellesi kansasi Israelin, omaksi kansaksesi ikiajoiksi, ja sinä, Herra, olet tullut heidän Jumalakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Täytä nyt, Herra Jumala, ikiajoiksi se, mitä olet puhunut palvelijastasi ja hänen suvustaan. Tee, niin kuin olet puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Nimesi tulee suureksi iankaikkisesti, ja se on oleva: Herra Sebaot, Israelin Jumala. Palvelijasi Daavidin suku on pysyvä edessäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Sillä sinä, Herra Sebaot, Israelin Jumala, olet ilmoittanut palvelijallesi ja sanonut: \'Minä rakennan sinulle huoneen.\' Siitä palvelijasi on saanut rohkeuden rukoilla tämän rukouksen kuullaksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Nyt, Herra, Herra, sinä olet Jumala, ja sanasi ovat todet. Kun olet luvannut palvelijallesi tämän hyvän,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'suvaitse nyt siunata palvelijasi sukua, että se pysyisi iäti edessäsi. Sillä sinä, Herra, Herra, olet sen luvannut, ja palvelijasi suku on oleva siunattu siunauksellasi iankaikkisesti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Sen jälkeen Daavid löi filistealaiset ja alisti heidät valtaansa. Daavid otti vallan ohjat filistealaisten käsistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Hän voitti myös mooabilaiset ja mittasi heitä nuoralla pantuaan heidät makaamaan maahan: aina kaksi nuoranpituutta hän mittasi surmattavaksi ja yhden nuoranpituuden henkiin jätettäväksi. Mooabilaiset tulivat Daavidin veronalaisiksi palvelijoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Samoin Daavid voitti Hadadeserin, Rehobin pojan, Sooban kuninkaan, kun tämä oli lähtenyt palauttamaan valtaansa Eufratille ulottuvia alueita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'Daavid otti häneltä vangiksi tuhat seitsemänsataa ratsumiestä ja kaksikymmentä tuhatta jalkamiestä ja katkoi kaikilta vaunuhevosilta vuohisjänteet. Ainoastaan sata vaunuhevosta hän niistä säästi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Kun Damaskon aramilaiset tulivat auttamaan Hadadeseria, Sooban kuningasta, Daavid voitti kaksikymmentä kaksi tuhatta aramilaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Daavid asetti maaherroja Damaskon Aramiin, ja aramilaiset tulivat Daavidin veronalaisiksi palvelijoiksi. Herra antoi Daavidille voiton, mihin tahansa hän meni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Daavid otti ne kultakilvet, jotka Hadadeserin palvelijoilla oli, ja vei ne Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Hadadeserin kaupungeista, Betahista ja Beerotaista, kuningas Daavid otti sangen paljon vaskea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Kun Tooi, Hamatin kuningas, kuuli, että Daavid oli voittanut Hadadeserin koko sotajoukon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'Tooi lähetti poikansa Jooramin kuningas Daavidin luo tervehtimään häntä ja onnittelemaan häntä siitä, että hän oli taistellut Hadadeserin kanssa ja voittanut hänet, sillä Hadadeser oli ollut Tooin vastustaja. Hänellä oli mukanaan hopea-, kulta- ja vaskiesineitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Nekin kuningas Daavid pyhitti Herralle, samoin kuin oli pyhittänyt sen hopean ja kullan, minkä hän oli ottanut kaikilta kukistamiltaan kansoilta:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'Aramilta, Mooabilta, ammonilaisilta, filistealaisilta ja Amalekilta, sekä sen saaliin, minkä hän oli ottanut Hadadeserilta, Rehobin pojalta, Sooban kuninkaalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'Daavid teki nimensä kuuluisaksi, kun hän palasi takaisin voitettuaan Suolalaaksossa edomilaiset, kahdeksantoista tuhatta miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Hän asetti maaherroja Edomiin. Koko Edomiin hän asetti maaherrat, ja kaikki edomilaiset tulivat Daavidin palvelijoiksi. Herra antoi Daavidille voiton, mihin tahansa tämä meni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'Niin Daavid hallitsi koko Israelia, ja Daavid teki kaikelle kansalleen sitä, mikä oikeus ja vanhurskaus on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Jooab, Serujan poika, oli sotajoukon ylipäällikkönä, ja Joosafat, Ahiludin poika, oli kanslerina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Saadok, Ahitubin poika, ja Ahimelek, Ebjatarin poika, olivat pappeina, ja Seraja oli kirjurina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Benaja, Joojadan poika, oli kreettien ja pleettien päällikkönä. Daavidin pojat olivat myös pappeina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Daavid kysyi: \"Onko Saulin suvusta enää jäljellä ketään, jolle voin tehdä laupeuden Joonatanin tähden?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Saulin perheessä oli ollut palvelija nimeltä Siiba, ja hänet he kutsuivat Daavidin eteen. Kuningas sanoi hänelle: \"Oletko sinä Siiba?\" Hän vastasi: \"Palvelijasi on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Kuningas kysyi: \"Eikö Saulin suvusta ole enää jäljellä ketään, jolle voisin tehdä Jumalan laupeuden?\" Siiba vastasi kuninkaalle: \"Vielä on Joonatanin poika, joka on rampa jaloistaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Kuningas kysyi häneltä: \"Missä hän on?\" Siiba vastasi kuninkaalle: \"Hän on Maakirin, Ammielin pojan, talossa Loodebarissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Kuningas Daavid lähetti noutamaan hänet Maakirin, Ammielin pojan, talosta Loodebarista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Kun Mefiboset, Saulin pojan Joonatanin poika, tuli Daavidin luo, lankesi hän kasvoilleen ja osoitti kunnioitusta. Niin Daavid sanoi: \"Mefiboset!\" Hän vastasi: \"Tässä on palvelijasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'Daavid sanoi hänelle: \"Älä pelkää, sillä teen todellakin sinulle laupeuden isäsi Joonatanin tähden, ja minä palautan sinulle isoisäsi Saulin kaiken maaomaisuuden, ja sinä aterioit aina pöydässäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Niin tämä kumarsi ja sanoi: \"Mikä on palvelijasi, että käännyt minunlaiseni koiranraadon puoleen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Sitten kuningas kutsui Siiban, Saulin palvelijan, ja sanoi hänelle: \"Kaiken, mikä on ollut Saulin ja koko hänen sukunsa omaa, annan herrasi pojalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Viljele sinä poikinesi ja palvelijoinesi hänelle sitä maata ja korjaa sato, että herrasi pojalla olisi leipää syödä. Kuitenkin Mefiboset, herrasi poika, aterioi aina pöydässäni.\" Siiballa oli viisitoista poikaa ja kaksikymmentä palvelijaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Siiba sanoi kuninkaalle: \"Aivan kuten herrani, kuningas, käskee palvelijaansa, palvelijasi tekee.\" – \"Niin Mefiboset on syövä pöydässäni, niin kuin hän olisi kuninkaan poikia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Mefibosetilla oli pieni poika nimeltä Miika. Koko Siiban talonväki oli Mefibosetin palvelijoita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Mutta Mefiboset asui Jerusalemissa, koska hän aina söi kuninkaan pöydässä. Hän ontui kumpaakin jalkaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Tapahtui sen jälkeen, että ammonilaisten kuningas kuoli, ja hänen poikansa Haanun tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Daavid sanoi: \"Minä osoitan laupeutta Haanunille, Naahaan pojalle, niin kuin hänen isänsä osoitti laupeutta minulle.\" Sitten Daavid lähetti palvelijoitaan lohduttamaan häntä hänen isänsä kuoleman johdosta. Kun Daavidin palvelijat tulivat ammonilaisten maahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'sanoivat ammonilaisten päämiehet herralleen Haanunille: \"Luuletko, että Daavid tahtoo kunnioittaa isääsi, kun hän lähettää lohduttajia luoksesi? Varmasti Daavid on lähettänyt palvelijansa luoksesi tutkimaan kaupunkia, vakoilemaan ja hävittämään sitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Haanun otatti kiinni Daavidin palvelijat, ajatti toisen puolen heidän partaansa ja leikkautti toisen puolen heidän vaatteistaan, niiden takaosia myöten, ja päästi heidät sitten menemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Kun se ilmoitettiin Daavidille, hän lähetti sanan heitä vastaan, sillä miehiä oli pahasti häväisty. Kuningas käski sanoa: \"Jääkää Jerikoon, kunnes partanne on kasvanut, ja tulkaa sitten takaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Kun ammonilaiset näkivät joutuneensa Daavidin vihoihin, ammonilaiset lähettivät lähettiläitä ja palkkasivat Beet-Rehobin ja Sooban aramilaisia, kaksikymmentä tuhatta jalkamiestä, ja Maakan kuninkaalta tuhat miestä ja Toobin miehiä kaksitoista tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Kun Daavid sen kuuli, hän lähetti Jooabin ja koko sotajoukon, kaikki valiot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Niin ammonilaiset lähtivät ja asettuivat rintamaan portin oven edustalle, mutta Sooban ja Rehobin aramilaiset ja Toobin ja Maakan miehet olivat eri joukkona kedolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Kun Jooab näki, että häntä uhkasi hyökkäys edestä ja takaa, hän valitsi miehiä kaikista Israelin valiomiehistä ja asettui rintamaan aramilaisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Mutta muun väen hän antoi veljensä Abisain johtoon, ja tämä asettui rintamaan ammonilaisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Hän sanoi: \"Jos aramilaiset tulevat minulle ylivoimaisiksi, tule avukseni. Jos taas ammonilaiset tulevat sinulle ylivoimaisiksi, minä tulen sinua auttamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Ole luja, ja pysykäämme lujina kansamme puolesta ja Jumalamme kaupunkien puolesta. Tehköön sitten Herra, minkä hyväksi näkee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Sitten Jooab ja väki, joka oli hänen kanssaan, ryhtyi taisteluun aramilaisia vastaan, ja nämä pakenivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Kun ammonilaiset näkivät aramilaisten pakenevan, hekin pakenivat Abisaita ja menivät kaupunkiin. Sitten Jooab palasi ahdistamasta ammonilaisia ja tuli Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Kun aramilaiset näkivät, että Israel oli voittanut heidät, he kaikki kokoontuivat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'ja Hadareser lähetti nostattamaan niitä aramilaisia, jotka asuivat tuolla puolella Eufrat-virran. He tulivat Heelamiin, ja Soobak, Hadareserin sotapäällikkö, johti heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Kun se ilmoitettiin Daavidille, hän kokosi kaiken Israelin ja meni Jordanin yli ja tuli Heelamiin. Aramilaiset taas asettuivat sotarintaan Daavidia vastaan ja taistelivat häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Mutta aramilaiset pakenivat Israelia, ja Daavid surmasi aramilaisilta seitsemän sataa vaunuhevosta ja neljäkymmentä tuhatta ratsumiestä, ja heidän sotapäällikkönsä Soobakin hän löi siellä kuoliaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Kun kaikki Hadareserin alaiset kuninkaat näkivät, että Israel oli voittanut heidät, he tekivät Israelin kanssa rauhan ja palvelivat heitä. Sen jälkeen aramilaiset eivät enää uskaltaneet auttaa ammonilaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Vuoden vaihteessa kuningasten sotaan lähtöaikaan Daavid lähetti Jooabin ja hänen kanssaan palvelijansa ja koko Israelin sotaretkelle. He hävittivät ammonilaisten maata ja piirittivät Rabbaa. Mutta Daavid itse jäi Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Niin tapahtui eräänä iltana, kun Daavid oli noussut vuoteeltaan ja käveli kuninkaan linnan katolla, että hän näki katolta naisen peseytymässä, ja nainen oli näöltään hyvin ihana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Daavid lähetti hankkimaan tietoja naisesta, ja sanottiin: \"Se on Batseba, Eliamin tytär, heettiläisen Uurian vaimo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Daavid lähetti sanansaattajat häntä noutamaan. Hän tuli hänen luokseen, ja Daavid makasi naisen kanssa, joka juuri oli puhdistautunut saastaisuudestaan. Sitten tämä palasi kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Vaimo tuli raskaaksi, ja hän lähetti ilmoittamaan Daavidille: \"Minä olen raskaana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Silloin Daavid lähetti Jooabille sanan: \"Lähetä luokseni heettiläinen Uuria.\" Jooab lähetti Uurian Daavidin luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Kun Uuria tuli Daavidin luo, tämä kysyi, kuinka Jooab ja väki voivat ja kuinka sota menestyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Daavid sanoi Uurialle: \"Mene kotiisi ja pese jalkasi.\" Uuria lähti kuninkaan linnasta, ja kuninkaan lahja seurasi häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Mutta Uuria menikin maata kuninkaan linnan oven eteen kaikkien muiden herransa palvelijain joukkoon eikä mennyt kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Kun Daavidille ilmoitettiin: \"Uuria ei ole mennytkään kotiinsa\", Daavid sanoi Uurialle: \"Tulethan sinä matkalta, mikset mennyt kotiisi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Mutta Uuria sanoi Daavidille: \"Arkki ja Israel ja Juuda asuvat lehtimajoissa, herrani Jooab ja herrani palvelijat ovat leiriytyneinä kedolla. Menisinkö minä kotiin syömään, juomaan ja makaamaan vaimoni kanssa? Niin totta kuin sinä elät ja sinun sielusi elää: sitä minä en tee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Daavid sanoi Uurialle: \"Jää tänne vielä täksi päiväksi, huomenna päästän sinut menemään.\" Uuria jäi Jerusalemiin vielä siksi päiväksi. Seuraavana päivänä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Daavid kutsui hänet luokseen syömään ja juomaan ja juotti hänet juovuksiin. Mutta illalla hän meni maata vuoteelleen herransa palvelijain joukkoon eikä mennyt kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Seuraavana aamuna Daavid kirjoitti kirjeen Jooabille ja lähetti sen Uurian mukana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Kirjeessä hän kirjoitti näin: \"Pankaa Uuria eturintaan kiivaimpaan taisteluun ja vetäytykää takaisin hänen luotaan, että hänet lyötäisiin kuoliaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Piirittäessään kaupunkia Jooab asetti Uurian siihen paikkaan, missä tiesi urhoollisimpien miesten olevan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Kun sitten kaupungin miehet ryntäsivät ulos ja ryhtyivät taisteluun Jooabin kanssa, niin väkeä, Daavidin palvelijoita, kaatui, ja myös heettiläinen Uuria kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Jooab lähetti ilmoittamaan Daavidille kaikki, mitä taistelussa oli tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'Hän käski sanansaattajaa sanoen: \"Kun olet kertonut kuninkaalle kaiken, mitä sodassa on tapahtunut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'kuningas ehkä kiivastuu ja sanoo sinulle: \'Miksi menitte niin lähelle kaupunkia taistelemaan? Ettekö tienneet, että ne ampuvat muurilta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Kuka surmasi Abimelekin, Jerubbesetin pojan? Eikö nainen heittänyt muurilta jauhinkiven hänen päälleen, niin että hän kuoli Teebeksessä? Miksi menitte niin lähelle muuria?\' Sano silloin: \'Myös palvelijasi heettiläinen Uuria on kuollut.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Sanansaattaja lähti, ja tultuaan hän ilmoitti Daavidille kaiken, mitä Jooab oli lähettänyt hänet ilmoittamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Sanansaattaja sanoi Daavidille: \"Ne miehet olivat meille ylivoimaiset ja ryntäsivät meitä vastaan ulos kedolle, mutta työnsimme heidät takaisin portin ovelle saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Silloin ampujat ampuivat muurilta palvelijoitasi, ja kuninkaan palvelijoita kuoli, myös palvelijasi heettiläinen Uuria kuoli.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Silloin Daavid sanoi sanansaattajalle: \"Sano näin Jooabille: \'Älä pane sitä pahaksesi, sillä miekka syö milloin yhden, milloin toisen. Taistele urheasti kaupunkia vastaan ja hävitä se.\' Rohkaise häntä näin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Kun Uurian vaimo kuuli, että hänen miehensä Uuria oli kuollut, hän piti puolisolleen valittajaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Mutta kun suruaika oli ohi, Daavid lähetti ottamaan hänet linnaansa, ja hän tuli hänen vaimokseen. Sitten hän synnytti hänelle pojan. Mutta se, minkä Daavid oli tehnyt, oli paha Herran silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Herra lähetti Naatanin Daavidin luo. Kun hän tuli hänen luokseen, hän sanoi hänelle: \"Kaksi miestä oli samassa kaupungissa, toinen rikas ja toinen köyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Rikkaalla oli lampaita ja nautoja hyvin paljon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'Mutta köyhällä ei ollut muuta kuin yksi ainoa pieni karitsa, jonka hän oli ostanut. Hän elätti sitä, ja se kasvoi hänen luonaan yhdessä hänen lastensa kanssa: se söi hänen leipäpalastaan, joi hänen maljastaan, makasi hänen sylissään ja oli hänelle kuin tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Rikkaalle miehelle tuli vieras. Mutta hän ei raskinut ottaa omia lampaitaan eikä nautojaan valmistaakseen ruokaa matkamiehelle, joka oli tullut hänen luokseen, vaan hän otti köyhän miehen karitsan ja valmisti sen miehelle, joka oli tullut hänen luokseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Daavid vihastui kovin siihen mieheen ja sanoi Naatanille: \"Niin totta kuin Herra elää: mies, joka on tämän tehnyt, on kuoleman oma.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Mutta karitsa hänen on korvattava nelinkertaisesti, koska hän teki näin ja koska hän ei tuntenut sääliä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Naatan sanoi Daavidille: \"Sinä olet se mies. Näin sanoo Herra, Israelin Jumala: \'Minä olen voidellut sinut Israelin kuninkaaksi ja pelastanut sinut Saulin käsistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'Olen antanut sinulle herrasi linnan ja antanut herrasi vaimot syliisi. Olen antanut sinulle Israelin ja Juudan heimot. Jos tämä olisi vähän, antaisin sinulle vielä sekä sitä että tätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Miksi olet pitänyt halpana Herran sanan ja tehnyt sitä, mikä on pahaa hänen silmissään? Heettiläisen Uurian olet surmannut miekalla, olet tappanut hänet ammonilaisten miekalla, ja hänen vaimonsa olet ottanut vaimoksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Sen tähden miekka ei ole milloinkaan väistyvä suvustasi, koska olet pitänyt halpana minut ja ottanut vaimoksesi heettiläisen Uurian vaimon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Näin sanoo Herra: Katso, minä nostatan sinulle onnettomuuden omasta perheestäsi, ja silmiesi edessä otan vaimosi ja annan heidät toiselle, ja hän on makaava vaimojesi kanssa tämän auringon nähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Sillä sinä olet tehnyt tekosi salassa, mutta minä teen tämän koko Israelin ja auringon nähden.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Daavid sanoi Naatanille: \"Olen tehnyt syntiä Herraa vastaan.\" Naatan sanoi Daavidille: \"Niin on myös Herra antanut syntisi anteeksi. Sinä et kuole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Mutta koska tällä teolla olet saattanut Herran viholliset pilkkaamaan häntä, niin se poika, joka sinulle on syntynyt, kuolee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Naatan meni kotiinsa. Herra löi lasta, jonka Uurian vaimo oli Daavidille synnyttänyt, että se sairastui vaikeasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Silloin Daavid etsi Jumalaa pojan tähden, ja Daavid paastosi, ja aina kun hän tuli kotiinsa, makasi hän yötä paljaalla maalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Hänen hovinsa vanhimmat menivät hänen luokseen saadakseen hänet nousemaan ylös maasta, mutta hän ei tahtonut, eikä hän syönyt mitään heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Seitsemäntenä päivänä lapsi kuoli. Mutta Daavidin palvelijat eivät uskaltaneet ilmoittaa hänelle, että lapsi oli kuollut, sillä he ajattelivat: \"Katso, kun me puhuimme hänelle lapsen vielä eläessä, hän ei kuullut meitä. Kuinka voisimme sitten sanoa hänelle, että lapsi on kuollut? Hän voisi tehdä itselleen pahaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Mutta kun Daavid näki, että hänen palvelijansa kuiskailivat keskenään, hän käsitti, että lapsi oli kuollut. Silloin Daavid kysyi palvelijoiltaan: \"Onko lapsi kuollut?\" He vastasivat: \"On.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Niin Daavid nousi maasta, peseytyi ja voiteli itsensä, muutti vaatteensa, meni Herran huoneeseen ja rukoili. Kun hän tuli kotiinsa, hän pyysi ruokaa, ja he tarjosivat, ja hän söi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Mutta hänen palvelijansa sanoivat hänelle: \"Miksi teet näin? Lapsen eläessä sinä paastosit ja itkit, mutta lapsen kuoltua sinä nouset ja syöt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Hän vastasi: \"Kun lapsi vielä eli, paastosin minä ja itkin, sillä ajattelin: Kenties Herra on minulle armollinen, niin että lapsi jää eloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Mutta kun hän nyt on kuollut, niin mitä minä enää paastoaisin? Enhän minä enää voi palauttaa häntä. Minä menen hänen luokseen, mutta hän ei enää palaa minun luokseni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Daavid lohdutti vaimoaan Batsebaa ja meni hänen luokseen ja makasi hänen kanssaan. Sitten tämä synnytti pojan, ja hän antoi tälle nimen Salomo, ja Herra rakasti häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Daavid lähetti sanoman profeetta Naatanin välityksellä, ja tämä kutsui häntä Jedidjaksi Herran tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Mutta Jooab ryhtyi taistelemaan ammonilaisten Rabbaa vastaan ja valloitti kuninkaan kaupungin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Jooab lähetti sanansaattajat Daavidin luo ja käski sanoa: \"Olen ryhtynyt taisteluun Rabbaa vastaan ja olen jo valloittanut vesikaupungin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Niin kokoa nyt jäljellä oleva väki ja asetu leiriin kaupungin edustalle ja valloita se, etten minä sitä valloittaisi ja ottaisi sitä nimiini.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Silloin Daavid kokosi kaiken väen ja lähti Rabbaan, ryhtyi taisteluun sitä vastaan ja valloitti sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Hän otti heidän kuninkaansa kruunun hänen päästään – se painoi talentin kultaa, ja siinä oli kallis kivi – ja se pantiin Daavidin päähän. Hän vei sangen paljon saalista kaupungista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Hän vei pois myös kansan, mitä siellä oli, ja asetti heitä kivisahojen ja rautahakkujen ja rautakirveiden ääreen ja pani heitä tiilentekoon. Näin hän teki kaikille ammonilaisten kaupungeille. Sitten Daavid ja kaikki väki palasi Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Sen jälkeen tapahtui tämä. Daavidin pojalla Absalomilla oli kaunis sisar nimeltä Taamar, ja Daavidin poika Amnon rakastui häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Amnon tuli aivan sairaaksi tuskasta sisarensa Taamarin tähden. Sillä kun tämä oli neitsyt, näytti Amnonista mahdottomalta tehdä hänelle mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Mutta Amnonilla oli ystävä, nimeltä Joonadab, Daavidin veljen Simean poika, ja Joonadab oli hyvin ovela mies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Tämä sanoi hänelle: \"Miksi sinä kuihdut noin joka aamu, kuninkaan poika? Etkö ilmaise minulle sitä?\" Amnon vastasi hänelle: \"Minä olen rakastunut veljeni Absalomin sisareen Taamariin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Joonadab sanoi hänelle: \"Paneudu vuoteeseesi ja tekeydy sairaaksi. Kun isäsi tulee katsomaan sinua, sano hänelle: \'Salli minun sisareni Taamarin tulla antamaan minulle jotain syötävää. Jos hän valmistaisi ruuan silmieni edessä, että minä näkisin sen, niin söisin hänen kädestään.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Amnon paneutui maata ja tekeytyi sairaaksi. Kun kuningas tuli katsomaan häntä, Amnon sanoi kuninkaalle: \"Salli sisareni Taamarin tulla tekemään kaksi kakkua silmieni edessä, niin minä syön hänen kädestään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Silloin Daavid lähetti sanan Taamarille linnaan ja käski sanoa hänelle: \"Mene veljesi Amnonin taloon ja valmista hänelle ruokaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Niin Taamar meni veljensä Amnonin taloon, jossa tämä makasi. Hän otti taikinaa, sotki ja teki leipäkakkuja hänen silmiensä edessä ja paistoi kakut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'otti pannun ja kaatoi hänen eteensä, mutta tämä ei tahtonut syödä. Amnon sanoi: \"Toimittakaa kaikki luotani ulos.\" Niin kaikki lähtivät hänen luotaan ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Sitten Amnon sanoi Taamarille: \"Tuo ruoka tänne sisähuoneeseen syödäkseni kädestäsi.\" Taamar otti tekemänsä kakut ja toi ne sisähuoneeseen veljelleen Amnonille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Mutta kun hän tarjosi niitä tälle syödä, tämä tarttui häneen ja sanoi hänelle: \"Tule, makaa kanssani, sisareni!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Hän sanoi: \"Pois se, veljeni, älä tee minulle väkivaltaa, sillä semmoista ei saa tehdä Israelissa. Älä tee sellaista häpeällistä tekoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Mihin minä joutuisin häpeäni kanssa? Ja sinua pidettäisiin Israelissa houkkana. Puhu nyt kuninkaan kanssa, hän ei minua sinulta kiellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Mutta tämä ei tahtonut kuulla häntä, vaan voitti hänet, teki hänelle väkivaltaa ja makasi hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Mutta sitten valtasi Amnonin hyvin suuri vastenmielisyys häntä kohtaan. Vastenmielisyys häntä kohtaan oli suurempi kuin rakkaus, jolla hän oli häntä rakastanut. Amnon sanoi hänelle: \"Nouse, mene tiehesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Hän sanoi hänelle: \"Eikö tämä rikos, että ajat minut pois, ole vielä suurempi kuin se toinen, jonka olet minulle tehnyt?\" Mutta hän ei tahtonut kuulla häntä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'vaan kutsui nuoren miehen, joka häntä palveli, ja sanoi: \"Ajakaa ulos luotani tämä, ja lukitse ovi hänen jälkeensä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Tytöllä oli yllään pitkäliepeinen, hihallinen ihokas. Sillä sellaisiin viittoihin olivat kuninkaan tyttäret puetut neitsyenä ollessaan. Kun palvelija oli vienyt hänet ulos ja lukinnut oven hänen jälkeensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Taamar otti tuhkaa päänsä päälle ja repäisi rikki pitkäliepeisen, hihallisen paidan, joka hänellä oli yllään, pani kätensä päänsä päälle ja käveli huutaen lakkaamatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Hänen veljensä Absalom sanoi hänelle: \"Onko veljesi Amnon ollut kanssasi? Vaikene nyt, sisareni, onhan hän veljesi. Älä pane tätä asiaa niin sydämellesi.\" Taamar jäi hylättynä veljensä Absalomin taloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Kun kuningas Daavid kuuli kaiken tämän, hän vihastui kovin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Mutta Absalom ei puhunut Amnonille sanaakaan, ei pahaa eikä hyvää, sillä Absalom vihasi Amnonia sen tähden, että tämä oli tehnyt väkivaltaa hänen sisarelleen Taamarille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Kahden vuoden kuluttua tapahtui, että Absalomilla oli lammasten keritsiäiset Baal-Haasorissa, joka on Efraimin luona. Absalom kutsui sinne kaikki kuninkaan pojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Absalom tuli kuninkaan luo ja sanoi: \"Katso, palvelijallasi on lammasten keritsiäiset. Jospa kuningaskin palvelijoineen tulisi palvelijansa luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Mutta kuningas vastasi Absalomille: \"Ei niin, poikani, älkäämme tulko kaikki, ettemme olisi sinulle vaivaksi.\" Vaikka hän pyytämällä pyysi häntä, hän ei kuitenkaan tahtonut mennä, vaan siunasi hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Silloin Absalom sanoi: \"Jollet itse tulekaan, lähteköön kuitenkin veljeni Amnon kanssamme.\" Kuningas sanoi hänelle: \"Miksi juuri hänen olisi mentävä kanssasi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Mutta kun Absalom vaati häntä, hän päästi Amnonin ja kaikki muut kuninkaan pojat menemään hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Absalom käski palvelijoitaan ja sanoi: \"Pitäkää silmällä, milloin Amnonin sydän tulee iloiseksi viinistä, ja kun minä sanon teille: \'Surmatkaa Amnon\', niin tappakaa hänet älkääkä pelätkö, sillä minä olen teitä käskenyt. Olkaa lujat ja urhoolliset.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Absalomin palvelijat tekivät Amnonille, kuten Absalom oli käskenyt. Silloin kaikki kuninkaan pojat nousivat, istuivat kukin muulinsa selkään ja pakenivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Heidän vielä ollessaan matkalla tuli Daavidille sanoma: \"Absalom on surmannut kaikki kuninkaan pojat, niin ettei ainoatakaan ole jäänyt heistä jäljelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Silloin kuningas nousi, repäisi vaatteensa ja paneutui maahan maata, ja kaikki hänen palvelijansa seisoivat siinä reväistyin vaattein.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Joonadab, Daavidin veljen Simean poika, vastasi ja sanoi: \"Älköön herrani luulko, että kaikki nuoret miehet, kuninkaan pojat, ovat tapetut, ainoastaan Amnon on kuollut. Sillä ilme Absalomin kasvoilla on tiennyt pahaa siitä päivästä lähtien, jona Amnon teki väkivaltaa hänen sisarelleen Taamarille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Älköön siis herrani, kuningas, panko sydämelleen sitä puhetta, että muka kaikki kuninkaan pojat olisivat kuolleet, sillä ainoastaan Amnon on kuollut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Mutta Absalom pakeni. Kun palvelija, joka oli tähystäjänä, nosti silmänsä ja katseli, katso, paljon väkeä tuli tietä pitkin vuoren rinnettä, joka oli hänen takanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Silloin Joonadab sanoi kuninkaalle: \"Katso, kuninkaan pojat tulevat. On tapahtunut, niin kuin palvelijasi sanoi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Juuri kun hän oli saanut sen sanotuksi, katso, kuninkaan pojat tulivat ja korottivat äänensä ja itkivät. Myös kuningas ja kaikki hänen palvelijansa itkivät hyvin katkerasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Mutta Absalom oli paennut ja mennyt Gesurin kuninkaan Talmain, Ammihudin pojan, luo. Daavid suri poikaansa kaiken aikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Kun Absalom oli paennut ja tullut Gesuriin, hän jäi sinne kolmeksi vuodeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Mutta kuningas Daavid ikävöi päästä Absalomin luo, sillä hän oli lohduttautunut Amnonin kuolemasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Kun Jooab, Serujan poika, huomasi, että kuninkaan sydän oli kääntynyt Absalomin puoleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Jooab lähetti noutamaan Tekoasta taitavan naisen ja sanoi hänelle: \"Ole surevinasi ja pukeudu suruvaatteisiin äläkä voitele itseäsi öljyllä, vaan ole kuin vaimo, joka jo kauan on surrut vainajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Mene kuninkaan eteen ja puhu hänelle näin.\" Sitten Jooab pani sanat hänen suuhunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Tekoalainen nainen meni kuninkaan eteen, lankesi kasvoilleen maahan ja osoitti kunnioitusta ja sanoi: \"Auta, kuningas!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Kuningas sanoi hänelle: \"Mikä sinun on?\" Hän vastasi: \"Totisesti, minä olen leskivaimo. Mieheni on kuollut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Palvelijattarellasi oli kaksi poikaa. He tulivat riitaan keskenään kedolla, eikä siellä ollut ketään, joka olisi sovittanut heidän välinsä, ja toinen löi toisen kuoliaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Katso, koko suku on noussut palvelijatartasi vastaan, ja he sanovat: \'Anna tänne veljensä surmaaja, että otamme häneltä hengen hänen tapetun veljensä hengestä ja hävitämme perillisenkin.\' He sammuttaisivat kipinänkin, joka minulla vielä on jäljellä, ettei miehestäni jäisi nimeä eikä jälkeläistä maan päälle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Kuningas sanoi vaimolle: \"Mene kotiisi, minä annan käskyn sinusta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Mutta tekoalainen nainen sanoi kuninkaalle: \"Herrani, kuningas, tulkoon tämä rikos minun ja minun isäni perheen kannettavaksi, mutta kuningas ja hänen valtaistuimensa olkoon siitä vapaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Kuningas sanoi: \"Tuo minun eteeni se, joka puhuu sinulle noin, niin hän ei enää sinuun koske.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Nainen sanoi: \"Muistakoon kuningas Herraa Jumalaansa, ettei verenkostaja saisi tuottaa vielä suurempaa turmiota, ja ettei poikaani tuhottaisi.\" Hän sanoi: \"Niin totta kuin Herra elää: ei hiuskarvakaan poikasi päästä ole putoava maahan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Mutta nainen sanoi: \"Salli palvelijattaresi puhua vielä sananen herralleni, kuninkaalle.\" Hän vastasi: \"Puhu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Nainen sanoi: \"Miksi sinä ajattelet tehdä juuri samoin Jumalan kansaa vastaan, koskapa kuningas ei salli oman hylkäämänsä tulla takaisin? Noin puhuessaanhan kuningas itse joutuu ikään kuin syylliseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Mehän kuolemme ja olemme kuin maahan kaadettu vesi, jota ei voi koota takaisin. Mutta Jumala ei ota pois elämää, vaan sitä hän ajattelee, ettei vain hylätty joutuisi hänestä erotetuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Sen tähden tulin nyt puhumaan tätä herralleni, kuninkaalle, kun kansa sai minut pelkäämään. Palvelijattaresi ajatteli: puhun kuninkaalle, ehkä kuningas tekee palvelijattarensa sanan mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Kuningas on kuuleva ja pelastava palvelijattarensa sen miehen kourista, joka tahtoo hävittää sekä minut että poikani Jumalan perintöosasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Palvelijattaresi ajatteli: herrani kuninkaan sana on rauhoittava minut. Sillä herrani kuningas on Jumalan enkelin kaltainen, niin että hän kuulee, mikä on hyvää ja mikä pahaa. Herra, Jumalasi, olkoon kanssasi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Kuningas vastasi ja sanoi naiselle: \"Älä salaa minulta mitään, mitä minä sinulta kysyn.\" Vaimo sanoi: \"Herrani, kuningas, puhukoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Kuningas kysyi: \"Eikö Jooabin käsi ole mukanasi kaikessa tässä?\" Vaimo vastasi ja sanoi: \"Niin totta kuin sielusi, herrani kuningas elää: ei pääse oikeaan eikä vasempaan siitä, mitä herrani kuningas, puhuu. Palvelijasi Jooab on käskenyt minua tähän ja pannut kaikki nämä sanat palvelijattaresi suuhun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Antaakseen asialle toisen muodon on palvelijasi Jooab näin tehnyt, mutta herrani on viisas kuin Jumalan enkeli ja tietää kaiken, mitä maan päällä tapahtuu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Kuningas sanoi Jooabille: \"Katso, tämän minä teen: mene ja tuo takaisin nuorukainen Absalom.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Jooab lankesi kasvoilleen maahan, osoitti kunnioitusta ja siunasi kuningasta. Jooab sanoi: \"Nyt palvelijasi tietää, että olen löytänyt armon silmiesi edessä, herrani, kuningas, koska kuningas tekee palvelijansa sanan mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Jooab nousi ja meni Gesuriin ja toi Absalomin Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Kuningas sanoi: \"Hän siirtyköön omaan taloonsa, mutta älköön tulko kasvojeni eteen.\" Niin Absalom siirtyi omaan taloonsa eikä tullut kuninkaan kasvojen eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Mutta koko Israelissa ei ollut yhtään niin komeaa miestä kuin Absalom, eikä ketään niin ylisteltyä. Kantapäästä kiireeseen asti hänessä ei ollut yhtään virhettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Kun hän ajatti hiuksensa – aina vuoden kuluttua hän ajatti ne, sillä ne tulivat hänelle niin raskaiksi, että hänen täytyi ne ajattaa – hänen hiuksensa painoivat kaksisataa sekeliä kuninkaan painoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Absalomille oli syntynyt kolme poikaa ja tytär, jonka nimi oli Taamar. Hän oli kaunis nainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Absalom asui kaksi vuotta Jerusalemissa tulematta kuninkaan kasvojen eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Absalom lähetti sanan Jooabille lähettääkseen hänet kuninkaan luo, mutta tämä ei tahtonut tulla hänen luokseen. Hän lähetti vielä toisen kerran, mutta hän ei tahtonut tulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Hän sanoi palvelijoilleen: \"Katsokaa, Jooabin maapalsta on maapalstani vieressä, ja hänellä on siinä ohraa. Menkää ja sytyttäkää se palamaan.\" Sitten Absalomin palvelijat sytyttivät maapalstan palamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Jooab nousi ja meni Absalomin luo taloon ja sanoi hänelle: \"Miksi palvelijasi ovat sytyttäneet palamaan maapalstan, joka on minun omani?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Absalom vastasi Jooabille: \"Katso, minä lähetin sinulle sanan: Tule tänne, lähetän sinut kuninkaan luo sanomaan: Mitä varten minä olen tullut kotiin Gesurista? Olisi parempi, jos vielä olisin siellä. Nyt minä tahdon nähdä kuninkaan kasvot, ja jos minussa on vääryys, surmatkoon hän minut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Jooab meni kuninkaan luo ja kertoi hänelle tämän. Hän kutsui Absalomin, ja tämä tuli kuninkaan luo ja kumartui kasvoilleen maahan kuninkaan eteen, ja kuningas suuteli Absalomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Mutta sitten tapahtui, että Absalom hankki itselleen vaunut ja hevoset sekä viisikymmentä miestä, jotka juoksivat hänen edellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Absalomilla oli tapana asettua varhain aamulla sen tien viereen, joka vei portille, ja kun joku oli tulossa kuninkaan eteen saamaan oikeutta riita-asiassaan, Absalom kutsui hänet ja kysyi: \"Mistä kaupungista olet?\" Kun tämä vastasi: \"Palvelijasi on siitä tai siitä Israelin sukukunnasta\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Absalom sanoi hänelle: \"Asiasi on kyllä hyvä ja oikea, mutta kuninkaan luona ei ole ketään, joka sinua kuulisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Absalom sanoi vielä: \"Jospa minut asetettaisiin tuomariksi maahan! Silloin tulisi minun eteeni jokainen, jolla on riita- tai oikeusasia, ja antaisin hänelle oikeuden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Kun joku lähestyi kumartaakseen häntä, hän ojensi kätensä, tarttui häneen ja suuteli häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Näin Absalom teki kaikille israelilaisille, jotka tulivat kuninkaan eteen saamaan oikeutta. Ja Absalom varasti Israelin miesten sydämet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Neljän vuoden kuluttua Absalom sanoi kerran kuninkaalle: \"Salli minun mennä Hebroniin täyttämään lupaus, jonka olen Herralle tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Sillä asuessani Gesurissa, Aramissa, palvelijasi teki lupauksen ja sanoi: \'Jos Herra antaa minun tulla takaisin Jerusalemiin, palvelen Herraa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Kuningas sanoi hänelle: \"Mene rauhassa.\" Hän nousi ja meni Hebroniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Mutta Absalom lähetti vakoojia kaikkiin Israelin sukukuntiin ja sanoi: \"Kun kuulette torven äänen, sanokaa: \'Absalom on tullut kuninkaaksi Hebronissa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Absalomin kanssa oli Jerusalemista kutsuvieraina mennyt kaksisataa miestä, jotka menivät sinne aivan viattomina tietämättä koko asiasta mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Absalom lähetti myös, sillä aikaa kun hän uhrasi teurasuhrejaan, noutamaan giilolaisen Ahitofelin, Daavidin neuvonantajan, hänen kaupungistaan Giilosta. Salaliitto vahvistui, ja yhä enemmän kansaa meni Absalomin puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Daavidin luo tultiin ilmoittamaan: \"Israelin miesten sydämet ovat kääntyneet Absalomin puolelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Daavid sanoi kaikille palvelijoilleen, jotka olivat hänen luonaan Jerusalemissa: \"Nouskaa, paetkaamme, sillä meillä ei ole muuta pelastusta Absalomin käsistä. Lähtekää nopeasti, ettei hän äkkiä saavuttaisi meitä ja saattaisi onnettomuutta meille ja surmaisi kaupungin asukkaita miekan terällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Kuninkaan palvelijat vastasivat kuninkaalle: \"Tehtäköön aivan niin kuin herrani, kuningas, harkitsee parhaaksi. Me olemme palvelijoitasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Kuningas lähti jalkaisin, ja koko hänen hovinsa seurasi häntä. Kuitenkin kuningas jätti kymmenen sivuvaimoaan jäljelle vartioimaan linnaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Kuningas lähti, ja kaikki väki seurasi häntä. He pysähtyivät kaukaisimman talon kohdalle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'kaikkien hänen palvelijoidensa kulkiessa hänen ohitseen. Myös kaikki kreetit ja pleetit sekä kaikki gatilaiset, kuusisataa miestä, jotka olivat tulleet hänen perässään Gatista, kulkivat kuninkaan ohi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Kuningas sanoi gatilaiselle Ittaille: \"Miksi sinäkin tulet kanssamme? Käänny takaisin ja jää kuninkaan luo, sillä sinä olet vieras, vieläpä maanpaossa kotoasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Eilen sinä tulit. Ottaisinko minä jo tänä päivänä sinut harhailemaan meidän kanssamme matkallemme, kun minä itsekin menen, minne menenkin? Käänny takaisin ja vie veljesi mukanasi. Armo ja uskollisuus sinulle!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Mutta Ittai vastasi kuninkaalle ja sanoi: \"Niin totta kuin Herra elää, ja niin totta kuin herrani, kuningas, elää: missä paikassa herrani kuningas on, siellä tahtoo myös palvelijasi olla, olkoonpa se elämäksi tai kuolemaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'Daavid sanoi Ittaille: \"Tule sitten ja kulje ohitseni.\" Niin gatilainen Ittai kulki ohi ja kaikki hänen miehensä ja kaikki lapset, jotka olivat hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Koko maa itki suureen ääneen, kun kaikki väki kulki ohi. Kun kuningas oli kulkemassa Kidronin laakson poikki kaiken väen kulkiessa erämaan tielle päin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'katso, siinä oli myös Saadok sekä hänen kanssaan kaikki leeviläiset, jotka kantoivat Jumalan liitonarkkia. He laskivat Jumalan arkin maahan, ja Ebjatar uhrasi, kunnes kaikki väki kaupungista oli ehtinyt kulkea ohi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Kuningas sanoi Saadokille: \"Vie Jumalan arkki takaisin kaupunkiin. Jos löydän armon Herran silmien edessä, hän tuo minut takaisin ja antaa minun vielä nähdä hänet ja hänen asumuksensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Mutta jos hän sanoo näin: \'Minä en ole mieltynyt sinuun\', niin, katso, hän tehköön minulle, minkä hyväksi näkee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Vielä kuningas sanoi pappi Saadokille: \"Sinähän olet näkijä. Palaa rauhassa kaupunkiin, sinä ja sinun poikasi Ahimaas ja Ebjatarin poika Joonatan, molemmat poikanne, teidän kanssanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Katsokaa, minä viivyn kahlauspaikoissa erämaassa, kunnes teiltä tulee sana tiedokseni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Saadok ja Ebjatar veivät Jumalan arkin takaisin Jerusalemiin ja jäivät sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Daavid kulki itkien Öljymäkeä ylös, pää peitettynä ja paljain jaloin. Myös kaikki väki, mikä oli hänen kanssaan, oli peittänyt päänsä, ja he kulkivat itkien lakkaamatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Kun sitten Daavidille kerrottiin, että myös Ahitofel oli salaliittolaisten joukossa Absalomin puolella, Daavid sanoi: \" Herra, käännä Ahitofelin neuvo hulluudeksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Kun sitten Daavid oli tullut vuoren laelle, jossa Jumalaa rukoiltiin, tuli arkilainen Huusai häntä vastaan viitta reväistynä ja multaa pään päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Daavid sanoi hänelle: \"Jos sinä tulet kanssani, olet minulle vain kuormaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Mutta jos palaat kaupunkiin ja sanot Absalomille: \'Minä tahdon olla palvelijasi, kuningas. Minä olen ennen ollut isäsi palvelija, mutta nyt tahdon olla sinun palvelijasi\', voit olla minulle avuksi tekemällä Ahitofelin neuvon tyhjäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Siellähän ovat kanssasi myös papit, Saadok ja Ebjatar. Kaikki, mitä kuulet kuninkaan linnasta, ilmoita papeille, Saadokille ja Ebjatarille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Katso, heillä on siellä mukanaan myös molemmat poikansa, Saadokilla Ahimaas ja Ebjatarilla Joonatan. Näiden kautta voitte lähettää minulle tiedon kaikesta, mitä kuulette.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Huusai, Daavidin ystävä, meni kaupunkiin, juuri kun Absalom tuli Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Kun Daavid oli kulkenut vähän matkaa vuoren laelta, tuli häntä vastaan Siiba, Mefibosetin palvelija, mukanaan satuloitu aasipari, jonka selässä oli kaksisataa leipää, sata rusinakakkua, sata hedelmää ja leili viiniä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Kuningas sanoi Siiballe: \"Mitä sinä näillä teet?\" Siiba vastasi: \"Aasit ovat kuninkaan perheelle ratsastettaviksi, leipä ja hedelmät palvelijoille syötäviksi ja viini uupuneiden juotavaksi erämaassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Kuningas sanoi: \"Mutta missä herrasi poika on?\" Siiba vastasi kuninkaalle: \"Hän jäi Jerusalemiin, sillä hän ajatteli: \'Nyt Israelin heimo antaa minulle takaisin isäni kuninkuuden.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Kuningas sanoi Siiballe: \"Katso, kaikki, mitä Mefibosetilla on, tulee omaksesi.\" Siiba vastasi: \"Minä kumarran, suo minun löytää armo silmiesi edessä, herrani, kuningas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Kun kuningas Daavid tuli Bahurimiin, katso, sieltä tuli mies, joka oli sukua Saulin perheelle, nimeltä Siimei, Geeran poika. Hän tuli ja kiroili tullessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'Hän viskeli kivillä Daavidia ja kaikkia kuningas Daavidin palvelijoita, vaikka kaikki väki ja kaikki sankarit olivat hänen oikealla ja vasemmalla puolellaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Kiroillessaan häntä Siimei sanoi näin: \"Pois, pois, sinä murhamies, sinä kelvoton!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Herra kostaa sinulle kaiken Saulin perheen veren, hänen, jonka sijaan olet tullut kuninkaaksi. Herra antaa nyt kuninkuuden poikasi Absalomin käteen. Katso, sinä olet itse joutunut onnettomuuteen, sillä murhamies sinä olet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Abisai, Serujan poika, sanoi kuninkaalle: \"Miksi tuo koiranraato saa kiroilla herraani, kuningasta? Anna minun mennä ja lyödä häneltä pää poikki.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Mutta kuningas vastasi: \"Mitä teillä on minun kanssani tekemistä, te Serujan pojat? Jos hän kiroilee ja jos Herra on käskenyt häntä: \'Kiroile Daavidia\', niin kuka voi sanoa: \'Miksi niin teet?\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Daavid sanoi vielä Abisaille ja kaikille palvelijoilleen: \"Katso, oma poikani, joka on lähtenyt minun ruumiistani, väijyy henkeäni, miksi ei sitten tämä benjaminilainen? Antakaa hänen olla, kiroilkoon vain, sillä Herra on häntä käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Ehkä Herra vielä näkee kurjuuteni, ja ehkä Herra maksaa minulle hyvällä hänen tämänpäiväisen kiroilunsa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Daavid kulki miehineen tietä myöten, ja Siimei kulki pitkin vuoren rinnettä rinnan hänen kanssaan, kiroili kulkiessaan ja viskeli kiviä ja heitteli soraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Kun kuningas ja kaikki väki, joka oli hänen kanssaan, olivat tulleet sinne uupuneina, hän hengähti siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Absalom ja kaikki kansa, Israelin miehet, olivat tulleet Jerusalemiin, ja Ahitofel oli hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Kun arkilainen Huusai, Daavidin ystävä, tuli Absalomin luo, Huusai sanoi Absalomille: \"Eläköön kuningas! Eläköön kuningas!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Absalom sanoi Huusaille: \"Tällainenko on rakkautesi ystävääsi kohtaan? Miksi et mennyt ystäväsi kanssa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Huusai vastasi Absalomille: \"Ei, vaan kenet Herra ja tämä kansa ja kaikki Israelin miehet ovat valinneet, sen puolella olen, ja sen luokse jään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Myös toiseksi: ketä minä palvelisin? Enkö hänen poikaansa? Niin kuin olen palvellut isääsi, tahdon palvella sinuakin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Absalom sanoi Ahitofelille: \"Antakaa nyt neuvo, mitä meidän on tehtävä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Ahitofel vastasi Absalomille: \"Mene isäsi sivuvaimojen luo, jotka hän on jättänyt linnaa vartioimaan. Silloin koko Israel saa kuulla, että sinä olet saattanut itsesi isäsi vihoihin, ja kaikki, jotka ovat kanssasi, saavat rohkeutta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Absalomille pystytettiin teltta katolle, ja Absalom meni isänsä sivuvaimojen luo koko Israelin nähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Ahitofelin antama neuvo oli siihen aikaan kuin Jumalalta saatu vastaus: sen arvoinen oli jokainen Ahitofelin neuvo sekä Daavidille että Absalomille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Ahitofel sanoi Absalomille: \"Salli minun valita kaksitoista tuhatta miestä ja nousta tänä yönä ajamaan takaa Daavidia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'niin karkaan hänen kimppuunsa, kun hän on väsynyt ja hänen kätensä ovat herpautuneet, ja saatan hänet kauhun valtaan, niin että kaikki väki, mitä hänen kanssaan on, pakenee, ja surmaan kuninkaan yksinään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'Sitten palautan kaiken kansan luoksesi. Kaikkien palaaminen riippuu siitä miehestä, jota sinä etsit. Kaikki kansa saa rauhan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Tämä miellytti Absalomia ja kaikkia Israelin vanhimpia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Kuitenkin Absalom sanoi: \"Kutsukaa myös arkilainen Huusai kuullaksemme, mitä hänellä on sanottavana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Kun Huusai tuli Absalomin luo, Absalom sanoi hänelle: \"Niin ja niin puhui Ahitofel. Onko meidän tehtävä hänen sanansa mukaan? Jollei, puhu sinä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Huusai vastasi Absalomille: \"Ei ole hyvä se neuvo, jonka Ahitofel tällä kertaa on antanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Huusai sanoi vielä: \"Sinä tiedät, että isäsi ja hänen miehensä ovat sankareita ja julmistuneita kuin karhu kedolla, jolta on poikaset riistetty. Myös isäsi on sotilas, joka ei lepää yöllä väen kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Katso, hän on nyt piiloutunut johonkin onkaloon tai muuhun paikkaan. Jos jo alussa meikäläisiä kaatuisi ja se saataisiin kuulla, niin sanottaisiin: \'Väelle, joka seurasi Absalomia, on tullut tappio.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Silloin urhoollisinkin, jolla on sydän kuin leijonalla, menettäisi rohkeutensa, sillä koko Israel tietää, että isäsi on sankari ja että ne, jotka ovat hänen kanssaan, ovat urhoollisia miehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Sen tähden neuvoni on tämä: Koottakoon sinun luoksesi koko Israel Daanista aina Beersebaan asti, että niitä tulee niin paljon kuin hiekkaa meren rannalla. Lähde sinä itsekin taisteluun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Kun karkaamme hänen kimppuunsa, missä ikinä hänet tavataan, painumme hänen päälleen, niin kuin kaste laskeutuu maahan. Eikä hänestä ja kaikista niistä miehistä, jotka ovat hänen kanssaan, jää jäljelle ainoatakaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Jos hän vetäytyisi johonkin kaupunkiin, niin koko Israel asettaisi köydet sen kaupungin ympärille, ja kiskoisimme sen alas laaksoon, kunnes siitä ei löytyisi kiveäkään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Silloin Absalom ja kaikki Israelin miehet sanoivat: \"Arkilaisen Huusain neuvo on parempi kuin Ahitofelin neuvo.\" Sillä Herra oli säätänyt sen näin tehdäkseen tyhjäksi Ahitofelin hyvän neuvon, että Herra saattaisi Absalomin onnettomuuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Huusai sanoi papeille, Saadokille ja Ebjatarille: \"Sen ja sen neuvon Ahitofel on antanut Absalomille ja Israelin vanhimmille, ja sen ja sen neuvon olen minä antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Lähettäkää nyt pian ja ilmoittakaa Daavidille tämä sana: \'Älä jää yöksi kahluupaikkoihin erämaahan, vaan mene joen yli, ettei kuningas ja kaikki väki, joka on hänen kanssaan, joutuisi perikatoon.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Joonatan ja Ahimaas olivat asettuneet Roogelin lähteelle, ja eräs palvelijatar kuljetti heille sinne sanaa. Sitten he menivät aina ja veivät sanan kuningas Daavidille. Sillä he eivät uskaltaneet näyttäytyä menemällä kaupunkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Mutta eräs poikanen näki heidät ja ilmoitti Absalomille. Silloin he molemmat menivät kiireesti pois ja tulivat erään miehen taloon Bahurimiin. Hänellä oli kaivo pihallaan, ja he laskeutuivat siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Hänen vaimonsa otti peitteen ja levitti sen kaivon suulle ja sirotti jyviä sen päälle, niin ettei voitu huomata mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Kun Absalomin palvelijat tulivat vaimon luo taloon, he kysyivät: \"Missä ovat Ahimaas ja Joonatan?\" Vaimo vastasi heille: \"Tuosta he menivät vesilätäkön yli.\" He etsivät, ja kun eivät heitä löytäneet, he palasivat takaisin Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Mutta heti kun he olivat menneet, nousivat toiset kaivosta, menivät ja veivät sanan kuningas Daavidille. He sanoivat Daavidille: \"Nouskaa ja menkää joutuin veden yli, sillä sen ja sen neuvon on Ahitofel antanut teitä vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Silloin Daavid ja kaikki väki, mikä oli hänen kanssaan, nousi, ja he menivät Jordanin yli. Kun aamu valkeni, ei ollut ainoatakaan, joka ei olisi tullut Jordanin yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Mutta kun Ahitofel näki, ettei hänen neuvoaan noudatettu, hän satuloi aasinsa, nousi ja lähti kotiinsa omaan kaupunkiinsa. Kun hän oli toimittanut talonsa, hän hirttäytyi. Hän kuoli, ja hänet haudattiin isänsä hautaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'Daavid oli tullut Mahanaimiin, kun Absalom ja kaikki Israelin miehet hänen kanssaan menivät Jordanin yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Mutta Absalom oli asettanut Amasan Jooabin sijaan sotajoukon ylipäälliköksi. Amasa oli Jitra-nimisen israelilaisen miehen poika. Tämä mies oli yhtynyt Abigailiin, Naahaan tyttäreen, Jooabin äidin Serujan sisareen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Israel ja Absalom leiriytyivät Gileadin maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Kun Daavid tuli Mahanaimiin, niin Soobi, Naahaan poika, ammonilaisten Rabbasta, ja Maakir, Ammielin poika, Loodebarista, ja gileadilainen Barsillai, Roogelimista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'toivat sinne vuoteita, vateja ja saviastioita, vehnänjyviä, ohria, jauhoja ja paahdettuja jyviä, papuja, herneitä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'sekä hunajaa, voita, lampaita ja juustoja ruuaksi Daavidille ja väelle, mikä oli hänen kanssaan, sillä he ajattelivat: \"Väki on nälissään, uuvuksissa ja janoissaan erämaassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Daavid piti katselmuksen mukanaan olevalle väelle, ja asetti sille tuhannen- ja sadanpäämiehet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Daavid lähetti väen liikkeelle: yhden kolmanneksen Jooabin johdolla, toisen kolmanneksen Abisain, Serujan pojan, Jooabin veljen, johdolla ja kolmannen kolmanneksen gatilaisen Ittain johdolla. Kuningas sanoi kansalle: \"Minä lähden myös itse teidän kanssanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Mutta kansa vastasi: \"Älä lähde. Sillä jos me pakenemme, meistä ei välitetä, ja jos puolet meistä saa surmansa, meistä ei silloinkaan välitetä, mutta sinä olet kuin kymmenen tuhatta meistä. Sen tähden on nyt parempi, että sinä olet valmiina tulemaan meille avuksi kaupungista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Niin kuningas sanoi heille: \"Minä teen, minkä hyväksi näette.\" Kuningas asettui portin pieleen, mutta kaikki väki lähti liikkeelle sadan ja tuhannen joukkoina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Kuningas käski myös Jooabia, Abisaita ja Ittaita ja sanoi: \"Pidelkää minulle mieliksi hellävaroin nuorukaista Absalomia.\" Kaikki kansa kuuli, kuinka kuningas antoi kaikille päälliköille käskyn Absalomista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Väki lähti kentälle Israelia vastaan, ja taistelu tapahtui Efraimin metsässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Siellä Daavidin palvelijat voittivat Israelin väen, ja siellä oli sinä päivänä suuri mieshukka: kaksikymmentä tuhatta miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Taistelu levisi koko siihen seutuun, ja metsä söi sinä päivänä enemmän väkeä kuin miekka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Absalom osui yhteen Daavidin palvelijain kanssa. Absalom ratsasti muulilla, ja kun muuli tuli suuren, tiheäoksaisen tammen alle, hän tarttui päästään tammeen, niin että hän jäi riippumaan taivaan ja maan välille, kun muuli juoksi pois hänen altaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Sen näki eräs mies ja ilmoitti sen Jooabille ja sanoi: \"Katso, minä näin Absalomin riippuvan tammessa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Niin Jooab sanoi miehelle, joka ilmoitti hänelle tämän: \"Jos näit sen, miksi et lyönyt häntä siinä maahan? Minun olisi ollut annettava sinulle kymmenen hopeasekeliä ja vyö.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Mutta mies vastasi Jooabille: \"Vaikka käsiini punnittaisiin tuhat hopeasekeliä, en sittenkään kävisi käsiksi kuninkaan poikaan, sillä kuningas käski meidän kuultemme sinua, Abisaita ja Ittaita sanoen: \'Pitäkää vaari nuorukaisesta, Absalomista.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Vai kavaltaisinko minä oman henkeni? Sillä eihän mikään pysy salassa kuninkaalta, ja sinä pysyisit kyllä syrjässä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Niin Jooab sanoi: \"Minä en enää kuluta aikaa kanssasi.\" Hän otti kolme keihästä käteensä ja pisti ne Absalomin rintaan, kun hän vielä eli tammessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Kymmenen nuorta miestä, Jooabin aseenkantajaa, astui Absalomin luo, ja he löivät hänet kuoliaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Jooab puhalsi torveen, ja väki palasi ajamasta takaa Israelia, kun Jooab pysäytti väen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'He ottivat Absalomin ja heittivät hänet metsässä suureen kuoppaan ja pystyttivät sangen suuren kivikasan hänen päälleen. Mutta koko Israel pakeni, kukin teltalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Absalom oli eläessään hankkinut ja pystyttänyt itselleen patsaan, joka on Kuninkaanlaaksossa, sillä hän sanoi: \"Minulla ei ole poikaa, joka säilyttäisi nimeni muiston.\" Patsaan hän oli kutsunut nimensä mukaan, ja sen nimi on vielä tänäkin päivänä Absalomin muistomerkki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Ahimaas, Saadokin poika, sanoi: \"Juoksen saattamaan kuninkaalle ilosanoman, että Herra on auttanut hänet hänen vihollistensa käsistä oikeuteensa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Mutta Jooab sanoi hänelle: \"Tänä päivänä et ole ilosanoman viejä. Jonakin muuna päivänä vienet ilosanoman, mutta tänä päivänä et vie ilosanomaa, sillä onhan kuninkaan poika kuollut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Sitten Jooab sanoi eräälle kuusilaiselle: \"Mene ja ilmoita kuninkaalle, mitä olet nähnyt.\" Niin kuusilainen kumarsi Jooabille ja lähti juoksemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Mutta Ahimaas, Saadokin poika, sanoi taas Jooabille: \"Tulkoon mitä tahansa, mutta minäkin juoksen kuusilaisen jälkeen.\" Jooab sanoi: \"Miksi sinä juoksisit, poikani, eihän sinulle siitä ilosanoman saattajan palkkaa tule?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, '\"Tulkoon mitä tahansa, mutta juoksen.\" Silloin hän sanoi hänelle: \"Juokse sitten.\" Ahimaas lähti juoksemaan Lakeuden tietä ja sivuutti kuusilaisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'Daavid istui molempien porttien välissä. Tähystäjä meni portin katolle muurin päälle. Kun hän nosti silmänsä ja katseli, katso: mies tuli juosten yksinään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Tähystäjä huusi ja ilmoitti sen kuninkaalle. Kuningas sanoi: \"Jos hän on yksin, hänellä on ilosanoma.\" Hän tuli yhä lähemmäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Tähystäjä näki toisen miehen tulevan juosten, ja hän huusi porttiin sanoen: \"Minä näen vielä toisenkin miehen tulevan ja hän juoksee yksin.\" Kuningas sanoi: \"Sekin tuo ilosanomaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Sitten tähystäjä sanoi: \"Ensimmäisen juoksu näyttää minusta Ahimaasin, Saadokin pojan, juoksulta.\" Kuningas sanoi: \"Hän on hyvä mies. Hän tulee hyviä sanomia tuoden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Ahimaas huusi ja sanoi kuninkaalle: \"Rauha!\" Hän kumartui kasvoilleen maahan kuninkaan eteen ja sanoi: \"Kiitetty olkoon Herra, Jumalasi, joka on antanut käsiisi ne miehet, jotka nostivat kätensä herraani, kuningasta, vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Kuningas kysyi: \"Voiko nuorukainen Absalom hyvin?\" Ahimaas vastasi: \"Minä näin suuren väkijoukon, kun kuninkaan palvelija Jooab lähetti minut, palvelijasi, mutta en tiedä, mitä se oli.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Kuningas sanoi: \"Astu syrjään ja asetu sinne.\" Hän astui syrjään ja jäi seisomaan sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Katso, sitten kuusilainen tuli perille, ja kuusilainen sanoi: \"Ilosanoma herralleni, kuninkaalle: Herra on tänä päivänä auttanut sinut oikeuteesi kaikkien niiden käsistä, jotka ovat nousseet sinua vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Kuningas kysyi kuusilaiselta: \"Voiko nuorukainen Absalom hyvin?\" Kuusilainen vastasi: \"Käyköön herrani kuninkaan vihollisille ja kaikille, jotka nousevat sinua vastaan tehdäkseen sinulle pahaa, niin kuin on käynyt sille nuorukaiselle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Kuningas tuli kovin järkytetyksi, nousi portin päällä olevaan yläsaliin ja itki. Mennessään hän huusi näin: \"Poikani Absalom, minun poikani, oma poikani Absalom! Jospa minä olisin kuollut sinun sijastasi! Absalom, poikani, oma poikani!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Jooabille ilmoitettiin: \"Katso, kuningas itkee ja suree Absalomia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Voitto muuttui sinä päivänä suruksi kaikelle kansalle, koska kansa sinä päivänä kuuli sanottavan, että kuningas oli murheissaan poikansa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Kansa tuli kaupunkiin kuin varkain sinä päivänä, niin kuin tulee varkain väki, joka on häväissyt itsensä pakenemalla taistelusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Kuningas oli peittänyt kasvonsa, ja hän huusi kovalla äänellä: \"Poikani Absalom! Absalom, poikani, oma poikani!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Jooab meni sisälle kuninkaan luo ja sanoi: \"Sinä olet tänä päivänä nostanut häpeän kaikkien palvelijoittesi kasvoille, vaikka he tänä päivänä ovat pelastaneet sekä oman henkesi että poikiesi, tyttäriesi, vaimojesi ja sivuvaimojesi hengen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Rakastathan niitä, jotka vihaavat sinua, ja vihaat niitä, jotka rakastavat sinua. Sillä olet tänään antanut tietää, ettei sinulla olekaan päälliköitä eikä palvelijoita, – niin, nyt tiedän, että jos Absalom olisi elossa ja me kaikki olisimme tänään kuolleet, se olisi sinulle mieleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Mutta nouse nyt ylös ja mene ulos ja puhuttele ystävällisesti palvelijoitasi. Sillä vannon Herran kautta: jollet mene ulos, niin totisesti yhtään ainoatakaan miestä ei jää luoksesi tänä yönä. Niin tämä on oleva sinulle suurempi onnettomuus kuin mikään muu, joka on kohdannut sinua nuoruudestasi tähän päivään saakka.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Kuningas nousi ja asettui istumaan porttiin, ja kaikelle kansalle ilmoitettiin ja sanottiin: \"Kuningas istuu nyt portissa.\" Kaikki kansa tuli kuninkaan eteen. Mutta kun Israel oli paennut, kukin telttamajalleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'alkoi kaikki kansa kaikkien Israelin heimojen keskuudessa riidellä ja sanoa: \"Kuningas on pelastanut meidät vihollistemme kourista, hän on vapauttanut meidät filistealaisten kourista, ja nyt hän on Absalomia paossa, maasta poissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Mutta Absalom, jonka me olemme voidelleet kuninkaaksemme, on kuollut taistelussa. Miksi ette nyt ryhdy tuomaan kuningasta takaisin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Kuningas Daavid lähetti sanan papeille Saadokille ja Ebjatarille ja käski sanoa: \"Puhukaa Juudan vanhimmille ja sanokaa: \'Miksi te olette viimeiset tuomaan kuningasta takaisin hänen linnaansa? Sillä se, mitä koko Israel puhuu, on tullut kuninkaan tietoon hänen olinpaikkaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Te olette veljiäni, luutani ja lihaani. Miksi te olisitte viimeiset tuomaan kuningasta takaisin?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Amasalle sanokaa: \'Olethan sinä luutani ja lihaani. Jumala rangaiskoon minua nyt ja vasta, jollet sinä koko elinaikaasi ole sotapäällikköni Jooabin sijassa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Hän taivutti kaikkien Juudan miesten sydämet, niin että he yhtenä miehenä lähettivät sanomaan kuninkaalle: \"Palaa takaisin, sinä ja kaikki palvelijasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Kuningas palasi takaisin ja tuli Jordanille. Juuda oli tullut Gilgaliin mennäkseen kuningasta vastaan ja tuodakseen kuninkaan Jordanin yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Myös Siimei, Geeran poika, benjaminilainen Bahurimista, lähti kiireellä Juudan miesten kanssa kuningas Daavidia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Hänen kanssaan oli tuhat miestä Benjaminista sekä Siiba, Saulin perheen palvelija, viidentoista poikansa ja kahdenkymmenen palvelijansa kanssa. Nämä olivat rientäneet Jordanille ennen kuningasta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'ja menneet kahluupaikasta yli noutamaan kuninkaan perheen ja toimittamaan, mitä hän näkisi hyväksi määrätä. Mutta Siimei, Geeran poika, heittäytyi kuninkaan eteen, kun hän oli lähtemässä Jordanin yli,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'ja sanoi kuninkaalle: \"Älköön herrani lukeko minulle pahaa tekoani älköönkä muistelko, kuinka väärin palvelijasi teki sinä päivänä, jona herrani, kuningas, lähti Jerusalemista. Älköön kuningas panko sitä sydämelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Sillä palvelijasi tuntee, että minä olen tehnyt synnin. Sen tähden olen tänä päivänä ensimmäisenä koko Joosefin heimosta tullut tänne herraani, kuningasta, vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Abisai, Serujan poika, puuttui puheeseen ja sanoi: \"Eikö Siimeitä ole rangaistava kuolemalla siitä, että hän on kiroillut Herran voideltua?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Daavid vastasi: \"Mitä teillä on tekemistä kanssani, te Serujan pojat, kun tulette minulle tänä päivänä kiusaajaksi? Olisiko ketään Israelissa tänä päivänä kuolemalla rangaistava? Minä tiedän tulleeni tänä päivänä Israelin kuninkaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Kuningas sanoi Siimeille: \"Sinä et kuole\", ja kuningas vannoi sen hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Mefiboset, Saulin pojanpoika, oli myös tullut kuningasta vastaan. Hän ei ollut pessyt jalkojaan, ei siistinyt partaansa eikä pesettänyt vaatteitaan siitä päivästä, jona kuningas lähti, siihen päivään asti, jona hän rauhassa tuli takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Kun hän nyt tuli Jerusalemista kuningasta vastaan, kuningas sanoi hänelle: \"Miksi sinä et tullut kanssani, Mefiboset?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'Hän vastasi: \"Herrani, kuningas, palvelijani petti minut. Sillä palvelijasi sanoi hänelle: \'Satuloi aasini ratsastaakseni sillä ja mennäkseni kuninkaan kanssa\' – sillä palvelijasihan on ontuva –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'mutta hän on panetellut palvelijaasi herralle kuninkaalle. Herrani, kuningas, on kuitenkin kuin Jumalan enkeli. Tee siis, mitä hyväksi näet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Sillä koko isäni suku oli herrani, kuninkaan, edessä kuoleman oma, ja kuitenkin sinä asetit palvelijasi niiden joukkoon, jotka syövät pöydässäsi. Mitäpä minulla on enää muuta oikeutta ja mitä valittamista kuninkaalle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Kuningas sanoi hänelle: \"Mitäpä tuosta enää puhut? Minä olen sanonut, että sinä ja Siiba saatte jakaa keskenänne maaomaisuuden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Mefiboset sanoi kuninkaalle: \"Ottakoon hän sen vaikka kokonaan, kun kerran herrani, kuningas, on palannut rauhassa kotiinsa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Gileadilainen Barsillai oli myös tullut Roogelimista ja meni kuninkaan kanssa Jordanille saattamaan häntä Jordanin yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Barsillai oli hyvin vanha, kahdeksankymmenen vuoden vanha. Hän oli elättänyt kuningasta tämän ollessa Mahanaimissa, sillä hän oli hyvin rikas mies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Kuningas sanoi nyt Barsillaille: \"Tule sinä mukaani, niin elätän sinut luonani Jerusalemissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Mutta Barsillai vastasi kuninkaalle: \"Montako ikävuotta minulla enää lienee, että menisin kuninkaan kanssa Jerusalemiin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Minä olen nyt kahdeksankymmenen vuoden vanha. Osaisinko minä enää erottaa hyvää pahasta, tai maistuisiko palvelijastasi miltään se, mitä hän syö ja mitä juo? Tai kuulostaisiko minusta enää miltään laulajien ja laulajattarien laulu? Miksi palvelijasi vielä tulisi kuormaksi herralleni, kuninkaalle?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Ainoastaan vähän matkaa seuraa palvelijasi kuningasta tuolle puolelle Jordanin. Miksi kuningas antaisi minulle sellaisen korvauksen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Salli palvelijasi palata takaisin saadakseni kuolla omassa kaupungissani isäni ja äitini haudan ääressä. Mutta katso, tässä on palvelijasi Kimham, menköön hän Herrani, kuninkaan, kanssa. Tee hänelle, mitä hyväksi näet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Niin kuningas sanoi: \"Kimham tulkoon kanssani, ja minä teen hänelle, mitä hyväksi näet, ja kaiken, mitä sinä minulta toivot, teen sinulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Kaikki kansa meni Jordanin yli, ja kuningas itsekin meni. Kuningas suuteli Barsillaita ja hyvästeli hänet. Tämä palasi takaisin kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Kuningas meni Gilgaliin, ja Kimham meni hänen mukanaan, samoin myös kaikki Juudan kansa. He ja puolet Israelin kansasta veivät kuninkaan sinne yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Katso, silloin kaikki muut Israelin miehet tulivat kuninkaan luo ja sanoivat kuninkaalle: \"Miksi meidän veljemme, Juudan miehet, ovat varkain tuoneet kuninkaan ja hänen perheensä sekä kaikki Daavidin miehet hänen kanssaan Jordanin yli?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Mutta kaikki Juudan miehet vastasivat Israelin miehille: \"Onhan kuningas meille läheisempi. Miksi vihastut siitä? Olemmeko me syöneet kuningasta, tai olemmeko vieneet hänet itsellemme?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 44, 'Israelin miehet vastasivat Juudan miehille ja sanoivat: \"Minulla on kymmenen kertaa suurempi osa kuninkaaseen, myös Daavidiin, kuin sinulla. Miksi siis olet katsonut minut ylen? Enkö minä ensin puhunut kuninkaani takaisin tuomisesta?\" Mutta Juudan miesten sanat olivat vielä ankarammat kuin Israelin miesten sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Siellä oli sattumalta kelvoton mies, nimeltä Seba, Bikrin poika, benjaminilainen. Hän puhalsi torveen ja sanoi: \"Meillä ei ole mitään osaa Daavidiin eikä perintöosaa Iisain poikaan. Kukin teltalleen, Israel!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Silloin kaikki Israelin miehet luopuivat Daavidista ja seurasivat Sebaa, Bikrin poikaa, mutta Juudan miehet riippuivat kiinni kuninkaassaan ja seurasivat häntä Jordanilta aina Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Daavid tuli linnaansa Jerusalemiin. Kuningas otti ne kymmenen sivuvaimoa, jotka hän oli jättänyt palatsia vartioimaan, ja pani heidät vartioituun taloon. Hän elätti heitä, mutta ei mennyt heidän luokseen. Siellä he olivat eristettyinä kuolinpäiväänsä asti, elävän miehen leskinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Kuningas sanoi Amasalle: \"Kutsu koolle Juudan miehet kolmen päivän kuluessa ja ole silloin itse paikallasi täällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Amasa meni kutsumaan koolle Juudaa, mutta hän viipyi yli sen ajan, jonka hän oli määrännyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Silloin Daavid sanoi Abisaille: \"Nyt Seba, Bikrin poika, tekee meille enemmän pahaa kuin Absalom. Ota sinä herrasi palvelijat ja aja häntä takaa, ettei hän saisi haltuunsa varustettuja kaupunkeja ja repisi meiltä silmiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Jooabin miehet sekä kreetit ja pleetit ja kaikki valiosotilaat lähtivät liikkeelle hänen jäljessään. He lähtivät Jerusalemista ajamaan takaa Sebaa, Bikrin poikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Mutta kun he olivat suuren kiven luona, joka on Gibeonissa, tuli Amasa heitä vastaan. Jooab oli puettu takkiinsa, ja sen päällä oli miekkavyö vyötäisille kiinnitettynä. Miekka oli tupessaan, mutta kun hän lähti liikkeelle, niin se putosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Silloin Jooab sanoi Amasalle: \"Voitko hyvin, veljeni?\" Jooab tarttui oikealla kädellään Amasaa partaan muka suudellakseen häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Kun Amasa ei varonut miekkaa, joka Jooabilla oli kädessään, tämä pisti häntä sillä vatsaan, niin että hänen sisälmyksensä valuivat maahan. Toista pistoa ei tarvittu: hän kuoli. Jooab ja hänen veljensä Abisai ajoivat takaa Sebaa, Bikrin poikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Mutta eräs Jooabin palvelijoista jäi seisomaan Amasan ääreen ja huusi: \"Jokainen, joka on Jooabille myötämielinen ja joka on Daavidin puolella, seuratkoon Jooabia!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Amasa virui verissään keskellä tietä. Mutta kun mies näki, että kaikki väki pysähtyi siihen, hän vei Amasan tieltä syrjään pellolle ja heitti vaatteen hänen päälleen nähdessään, että kaikki ohikulkijat pysähtyivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Kun hänet oli toimitettu pois tieltä, kulkivat kaikki ohi ja seurasivat Jooabia ajaakseen takaa Sebaa, Bikrin poikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Tämä kulki kaikkien Israelin sukukuntien kautta Aabeliin ja Beet-Maakaan, ja kaikki beeriläiset kokoontuivat ja seurasivat häntä sinne asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'He tulivat ja piirittivät häntä Aabel-Beet-Maakassa ja loivat kaupunkia vastaan vallin, joka ulottui ulkomuuriin. Kaikki Jooabin väki teki hävitystyötä kukistaakseen muurin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Silloin eräs viisas nainen huusi kaupungista: \"Kuulkaa! Kuulkaa! Sanokaa Jooabille, että hän tulee tänne lähelle puhutellakseni häntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Kun tämä tuli häntä lähelle, nainen sanoi: \"Oletko Jooab?\" Hän vastasi: \"Olen.\" Nainen sanoi hänelle: \"Kuule palvelijattaresi sanoja.\" Hän vastasi: \"Minä kuulen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Silloin nainen sanoi: \"Muinoin oli tapana sanoa: \'On kysyttävä neuvoa Aabelista\', ja niin tuli valmista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Minä olen rauhallisimpia ja uskollisimpia Israelissa, ja sinä koetat ottaa hengen kaupungilta, joka on äiti Israelissa. Miksi sinä tahdot hävittää Herran perintöosan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Jooab vastasi ja sanoi: \"Pois se, pois se! En tahdo hävittää enkä tuhota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Niin ei ole asia, vaan eräs mies Efraimin vuoristosta, nimeltä Seba, Bikrin poika, on nostanut kätensä kuningas Daavidia vastaan. Luovuttakaa hänet yksin, niin lähden pois kaupungin edustalta.\" Nainen vastasi Jooabille: \"Katso, hänen päänsä heitetään sinulle muurin yli.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Sitten nainen viisaudessaan meni kaiken kansan luo. He löivät Sebalta, Bikrin pojalta, pään poikki ja heittivät sen Jooabille. Silloin tämä puhalsi torveen, ja he hajaantuivat kaupungin edustalta, kukin teltalleen. Mutta Jooab palasi kuninkaan luo Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Jooab oli Israelin koko sotajoukon ylipäällikkönä, ja Benaja, Joojadan poika, oli kreettien ja pleettien päällikkönä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Adoram oli verotöiden valvojana, ja Joosafat, Ahiludin poika, oli kanslerina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Seja oli kirjurina, ja Saadok ja Ebjatar olivat pappeina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Myös jaairilainen Iira oli Daavidilla pappina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Daavidin aikana oli nälänhätä, jota kesti kolme vuotta peräkkäin. Silloin Daavid etsi Herran kasvoja. Herra vastasi: \"Saulin tähden, verivelan alaisen suvun tähden, koska hän surmasi gibeonilaisia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Kuningas kutsui gibeonilaiset ja puhutteli heitä. Gibeonilaiset eivät olleet israelilaisia, vaan amorilaisten jäljelle jääneitä, ja israelilaiset olivat vannoneet heille valan, mutta Saul oli kiivaillessaan israelilaisten ja Juudan puolesta koettanut hävittää heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'Daavid sanoi gibeonilaisille: \"Mitä minun on tehtävä hyväksenne, ja millä minun on sovitettava teidät, että siunaisitte Herran perintöosaa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Gibeonilaiset vastasivat hänelle: \"Ei ole meidän ja Saulin sekä hänen sukunsa välillä kysymys hopeasta eikä kullasta, eikä meillä ole valtaa surmata ketään Israelissa.\" Hän sanoi: \"Mitä sitten vaaditte minua tekemään hyväksenne?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'He vastasivat kuninkaalle: \"Sen miehen, joka tahtoi meidät lopettaa ja joka aikoi hävittää meidät, niin ettei meillä olisi missä olla koko Israelin alueella,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'sen miehen jälkeläisistä luovutettakoon meille seitsemän miestä lävistääksemme heidät paaluihin Herralle Saulin, Herran valitun, Gibeassa.\" Kuningas sanoi: \"Minä luovutan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Mefibosetin, Saulin pojan Joonatanin pojan, kuningas kuitenkin säästi Herran valan tähden, joka oli heidän välillään, Daavidin ja Joonatanin, Saulin pojan, välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Kuningas otti Rispan, Aijan tyttären, kaksi poikaa, Armonin ja Mefibosetin, jotka tämä oli synnyttänyt Saulille, sekä Meerabin, Saulin tyttären, viisi poikaa, jotka tämä oli synnyttänyt Adrielille, meholalaisen Barsillain pojalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'ja luovutti heidät gibeonilaisten käsiin. Nämä teloittivat heidät vuorella Herran edessä, niin että ne seitsemän sortuivat kaikki yhdessä. Näin heidät surmattiin elonleikkuun ensimmäisinä päivinä, ohranleikkuun alussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Silloin Rispa, Aijan tytär, otti säkin ja levitti sen kalliolle, ja se oli hänen vuoteenaan elonleikkuun alusta siihen asti, kunnes sade taivaasta vuoti heidän päälleen, eikä hän sallinut taivaan lintujen päivällä eikä metsän eläinten yöllä tulla heidän päälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Kun Daavidille kerrottiin, mitä Rispa, Aijan tytär, Saulin sivuvaimo, oli tehnyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Daavid lähti ja otti Saulin ja hänen poikansa Joonatanin luut Gileadin Jaabeksen miehiltä, jotka olivat varkain ottaneet ne siltä torilta Beet-Seanista, jolle filistealaiset olivat heidät ripustaneet silloin, kun filistealaiset surmasivat Saulin Gilboassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Hän toi sieltä Saulin ja hänen poikansa Joonatanin luut. Myös teloitettujen luut koottiin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'ja haudattiin yhdessä Saulin ja hänen poikansa Joonatanin luiden kanssa Benjaminin maahan Seelaan, Saulin isän, Kiisin, hautaan. Tehtiin kaikki, mitä kuningas oli käskenyt. Sen jälkeen Jumala armahti maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Taas syttyi sota filistealaisten ja Israelin välillä. Daavid lähti palvelijoineen sotimaan filistealaisia vastaan, ja Daavid väsyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Jisbi-Benob, Raafan jälkeläisiä, jonka keihäs painoi kolmesataa sekeliä vaskea ja joka oli puettu uusiin varusteisiin, aikoi surmata Daavidin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Mutta Abisai, Serujan poika, tuli hänen avukseen ja löi filistealaisen kuoliaaksi. Daavidin miehet vannottivat hänellä valan sanoen: \"Sinä et saa enää lähteä kanssamme taisteluun, ettet sammuttaisi Israelin lamppua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Sen jälkeen oli taas taistelu filistealaisten kanssa Goobissa: silloin huusailainen Sibbekai surmasi Safin, joka myös oli Raafan jälkeläisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Taas oli taistelu filistealaisia vastaan Goobissa, Elhanan, Jare-Ooregimin poika, beetlehemiläinen, surmasi gatilaisen Goljatin, jonka peitsen varsi oli kuin kangastukki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Taas oli taistelu Gatissa. Siellä oli kookas mies, jolla oli kuusi sormea kummassakin kädessä ja kuusi varvasta kummassakin jalassa, yhteensä kaksikymmentä neljä. Hänkin polveutui Raafasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Kun hän häpäisi Israelia, surmasi hänet Joonatan, Daavidin veljen Simean poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Nämä neljä polveutuivat gatilaisesta Raafasta. He kaatuivat Daavidin ja hänen palvelijoidensa käden kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Daavid puhui Herralle tämän laulun sanat sinä päivänä, jona Herra oli pelastanut hänet kaikkien hänen vihollistensa ja Saulin vallasta. Hän sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, '\" Herra, kallioni, linnani ja pelastajani!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Jumala, vuoreni, jonka turviin pakenen, kilpeni, autuuteni sarvi, varustukseni ja pakopaikkani, pelastajani, joka pelastat minut väkivallasta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, '\'Ylistetty olkoon Herra \' – niin minä huudan, ja pelastun vihollisistani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Sillä kuoleman aallot piirittivät minut, turmion virrat pelästyttivät minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Helvetin paulat kietoivat minut, kuoleman ansat yllättivät minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'Ahdistuksessani huusin Herraa, huusin Jumalaani. Hän kuuli ääneni temppelistään, huutoni kohosi hänen korviinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Maa huojui ja järisi, taivaan perustukset järkkyivät. Ne horjuivat, sillä hänen vihansa syttyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Savu suitsusi hänen sieraimistaan, kuluttava tuli hänen suustaan, palavat hiilet hehkuivat hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Hän notkisti taivaan ja astui alas, synkkä pilvi jalkojensa alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Hän ajoi kerubin kannattamana ja lensi, hän näkyi tuulen siipien päältä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Hän pani pimeyden majaksi ympärilleen, synkät vedet, paksut pilvet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Hohteesta, joka kävi hänen edellään, hehkuivat palavat hiilet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Herra jyrisi taivaasta, Korkein antoi äänensä kaikua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Hän lennätti nuolia ja hajotti heidät, salamoita, ja kauhistutti heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Meren syvyydet tulivat näkyviin, maanpiirin perustukset paljastuivat Herran nuhtelusta, hänen vihansa hengen puuskasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Hän ojensi kätensä korkeudesta ja tarttui minuun, veti minut ylös suurista vesistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Hän pelasti minut voimallisesta vihollisestani, vihamiehistäni, sillä he olivat minua väkevämmät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'He hyökkäsivät kimppuuni hätäni päivänä, mutta Herra tuli tuekseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Hän toi minut avaraan paikkaan, hän vapautti minut, sillä hän oli minuun mieltynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Herra tekee minulle vanhurskauteni mukaan. Kätteni puhtauden mukaan hän minulle maksaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Sillä minä noudatan Herran teitä enkä luovu Jumalastani jumalattomuuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Kaikki hänen oikeutensa ovat silmieni edessä, enkä poikkea hänen käskyistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Olen vilpitön häntä kohtaan ja varon itseni pahoista teoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Sen tähden Herra palkitsee minulle vanhurskauteni mukaan, sen mukaan kuin olen puhdas hänen silmiensä edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Hurskasta kohtaan olet hurskas, nuhteetonta sankaria kohtaan nuhteeton,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'puhdasta kohtaan olet puhdas, mutta kieroa kohtaan nurja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Pelastat nöyrän kansan, mutta silmäsi ovat ylpeitä vastaan, sinä alennat heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Sillä sinä, Herra, olet lamppuni. Herra valaisee pimeyteni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Avullasi hyökkään rosvojoukkoa vastaan. Jumalani avulla ryntään muurin yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Jumalan tie on nuhteeton, Herran sana tulessa koeteltu. Hän on kaikkien kilpi, jotka häneen turvaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Sillä kuka muu on Jumala paitsi Herra, ja kuka muu on pelastuksen kallio paitsi Jumalamme?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Se Jumala, joka on vahva turvani ja johdattaa nuhteetonta hänen tiellään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'tekee hänen jalkansa nopeiksi kuin peurat ja asettaa minut kukkuloilleni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'joka opettaa käteni sotimaan ja käsivarteni vaskijousta jännittämään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Sinä annat minulle pelastuksen kilven, ja kun kuulet rukoukseni, teet minut suureksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Sinä annat askeleilleni avaran tilan, eivätkä jalkani horju.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Minä ajan vihollisiani takaa ja tuhoan heidät enkä palaa, ennen kuin teen heistä lopun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Lopetan heidät ja murskaan heidät, niin etteivät he enää nouse. He sortuvat jalkojeni alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Sinä vyötät minut voimalla sotaan, sinä painat vastustajani alleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Sinä ajat viholliseni pakoon, vihamieheni minä hukutan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'He katselevat, mutta pelastajaa ei ole, katsovat Herran puoleen, mutta hän ei heille vastaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Survon heidät maan tomuksi, kadun loaksi heidät poljen ja tallaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Sinä pelastat minut kansani riidoista, sinä varjelet minua, niin että tulen pakanoiden pääksi. Kansa, jota en tuntenut, palvelee minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Muukalaiset minua mielistelevät, jo korvan kuulemalta he tottelevat minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Muukalaiset masentuvat. He tulevat vyöttäytyneinä varustuksistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Herra elää! Kiitetty olkoon kallioni, ja ylistetty Jumala, pelastukseni kallio,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Jumala, joka hankkii minulle koston ja laskee kansat valtani alle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'sinä, joka vapahdat minut vihollisistani ja korotat minut vastustajieni yläpuolelle ja päästät minut väkivaltaisesta miehestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Sen tähden ylistän sinua, Herra, kansojen keskuudessa ja veisaan nimesi kiitosta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'sinun, joka annat kuninkaallesi suuren avun ja osoitat armoa voidellullesi, Daavidille, ja hänen jälkeläisilleen, iankaikkisesti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Nämä olivat Daavidin viimeiset sanat: Näin puhuu Daavid, Iisain poika, näin puhuu korkealle korotettu mies, Jaakobin Jumalan voideltu, ihana Israelin ylistysvirsissä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, '\" Herran Henki on puhunut minulle, ja hänen sanansa on kielelläni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Israelin Jumala on sanonut, Israelin kallio on puhunut minulle: \'Joka hallitsee ihmisiä vanhurskaudella, joka hallitsee jumalanpelolla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'hän on kuin huomenhohde auringon noustessa pilvettömänä aamuna, kun maa kirkkaassa valossa vihannoi sateen jälkeen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Eikö sukuni ole näin Jumalan edessä? Sillä hän on tehnyt kanssani iankaikkisen liiton, kaikin puolin taatun ja vakaan. Hän antaa versoa minulle kaiken autuuden ja kaiken ilon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Mutta kaikki kelvottomat ovat kuin pois heitetyt orjantappurat, joihin ei käsin tartuta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Jos jonkun on koskettava niihin, hän varustautuu raudalla ja keihäänvarrella. Sitten ne tulella poltetaan, siinä missä ovat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Nämä ovat Daavidin sankarien nimet: Jooseb-Bassebet, tahkemonilainen, vaunusoturien päällikkö, hän, joka oli heiluttanut keihästään kahdeksansadan kaatuneen yli yhdellä kertaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Hänen jälkeensä Eleasar, Doodin poika, joka oli erään aholilaisen poika. Hän oli yksi niistä kolmesta valiosotilaasta, jotka olivat Daavidin kanssa silloin, kun he saattoivat häpeään filistealaiset, jotka olivat kokoontuneet sinne sotimaan. Israelin miehet vetäytyivät silloin takaisin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'mutta hän jäi paikalleen ja surmasi filistealaisia, kunnes hänen kätensä uupui niin, että se kouristui kiinni miekkaan. Herra antoi suuren voiton sinä päivänä. Väki kääntyi vain hänen jälkeensä ryöstämään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Hänen jälkeensä oli Samma, Aagen poika, hararilainen. Kerran olivat filistealaiset kokoontuneet yhteen joukkoon, ja siellä oli peltopalsta, kokonaan hernettä kasvamassa. Väki pakeni filistealaisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'mutta hän asettui keskelle palstaa, sai sen pelastetuksi ja voitti filistealaiset, ja niin Herra antoi suuren voiton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Kerran lähti kolme niistä kolmestakymmenestä päälliköstä liikkeelle, ja he tulivat elonleikkuun aikana Daavidin luo Adullamin luolalle. Filistealaisten joukko oli leiriytynyt Refaimin tasangolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'Daavid oli silloin Vuorilinnassa, ja filistealaisten vartiosto oli Beetlehemissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Daavidin rupesi tekemään mieli vettä, ja hän sanoi: \"Jospa joku toisi minulle vettä juodakseni Beetlehemin kaivosta, joka on portin edustalla!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Silloin murtautuivat ne kolme sankaria filistealaisten leirin läpi ja ammensivat vettä Beetlehemin kaivosta portin edustalta, kantoivat ja toivat sen Daavidille. Mutta hän ei tahtonut sitä juoda, vaan vuodatti sen juomauhriksi Herralle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'ja sanoi: \"Pois se! Herra varjelkoon minut sitä tekemästä. Onhan se niiden miesten veri, jotka menivät sinne oman henkensä uhalla.\" Eikä hän tahtonut juoda sitä. Tämän tekivät ne kolme sankaria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Abisai, Jooabin veli, Serujan poika, oli niiden kolmen päällikkö. Hän oli heiluttanut keihästään kolmensadan kaatuneen yli. Hän oli kuuluisa niiden kolmen joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Hän oli arvossa pidetty niiden kolmen joukossa ja oli heidän päämiehensä, mutta hän ei vetänyt vertoja niille kolmelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Benaja, Joojadan poika, joka oli urhoollisen ja suurista teoistaan kuuluisan miehen poika, oli kotoisin Kabseelista. Hän surmasi kaksi mooabilaista sankaria, laskeutui alas ja tappoi lumituiskun aikana leijonan kaivoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Myös hän surmasi egyptiläisen miehen, sen kauhean miehen. Egyptiläisellä oli keihäs kädessä, mutta hän meni häntä vastaan ainoastaan sauva kädessä. Hän tempasi keihään egyptiläisen kädestä ja tappoi hänet hänen omalla keihäällään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Tällaisia teki Benaja, Joojadan poika. Hän oli kuuluisa niiden kolmen sankarin joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Hän oli arvossa pidetty niiden kolmenkymmenen joukossa, mutta hän ei vetänyt vertoja niille kolmelle. Daavid asetti hänet henkivartiostonsa päälliköksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Niiden kolmenkymmenen joukossa oli Asael, Jooabin veli; Elhanan, Doodon poika, Beetlehemistä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'harodilainen Samma; harodilainen Elika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'pleettiläinen Heles; tekoalainen Iira, Ikkeksen poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'anatotilainen Abieser; huusalainen Mebunnai;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'ahohilainen Salmon; netofalainen Maharai;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'netofalainen Heeleb, Baanan poika; Ittai, Riibain poika, benjaminilaisten Gibeasta;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'piratonilainen Benaja; Hiddai Nahale-Gaasista;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'arabilainen Abi-Albon; barhumilainen Asmavet;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'saalbonilainen Eljahba; Bene-Jaasen; Joonatan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'hararilainen Samma; ararilainen Ahiam, Sararin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Elifelet, Ahasbain poika, joka oli erään maakatilaisen poika; giilolainen Eliam, Ahitofelin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'karmelilainen Hesrai; arabilainen Paarai;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jigal, Naatanin poika, Soobasta; gaadilainen Vaani;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'ammonilainen Selek; beerotilainen Naharai, Jooabin, Serujan pojan, aseenkantaja;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'jeteriläinen Iira; jeteriläinen Gaareb;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'heettiläinen Uuria. Kaikkiaan kolmekymmentä seitsemän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Herran viha syttyi taas Israelia kohtaan, niin että hän yllytti Daavidin heitä vastaan, sanoen: \"Mene ja laske Israel ja Juuda.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Niin kuningas sanoi Jooabille, sotajoukon päällikölle, joka oli hänen luonaan: \"Kiertele kaikki Israelin sukukunnat Daanista Beersebaan asti, ja pitäkää kansan katselmus, että saisin tietää kansan lukumäärän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Jooab vastasi kuninkaalle: \" Herra, Jumalasi, lisätköön kansan, olkoon se kuinka suuri tahansa, satakertaiseksi, ja saakoon herrani, kuningas, nähdä sen omin silmin. Mutta miksi herrani, kuningas, haluaa sellaista?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Kuitenkin kuninkaan sana velvoitti Jooabia ja sotapäälliköitä. Niin Jooab ja sotapäälliköt lähtivät kuninkaan luota pitämään Israelin kansan katselmusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'He menivät Jordanin yli ja leiriytyivät Aroeriin, oikealle puolelle jokilaakson keskikohdalla olevaa kaupunkia, Gaadiin ja Jaeseriin päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'He tulivat Gileadiin ja Tahtim-Hodsin maahan. Sitten he tulivat Daan-Jaaniin ja sieltä ympäri Siidoniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'He tulivat Tyyron linnoitukseen ja kaikkiin hivviläisten ja kanaanilaisten kaupunkeihin ja menivät sieltä Juudan Etelämaahan Beersebaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Kun he olivat kierrelleet koko maan, he tulivat yhdeksän kuukauden ja kahdenkymmenen päivän kuluttua takaisin Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Jooab ilmoitti kuninkaalle kansan lasketun lukumäärän: Israelissa oli kahdeksansataa tuhatta sotakuntoista miekkamiestä, ja Juudassa oli viisisataa tuhatta miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Mutta Daavidin sydän soimasi häntä, sitten kun hän oli laskenut kansan, ja Daavid sanoi Herralle: \"Olen tehnyt suuren synnin tehdessäni tämän. Mutta, Herra, anna nyt anteeksi palvelijasi rikos, sillä olen menetellyt hyvin tyhmästi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Kun Daavid nousi aamulla, profeetta Gaadille, Daavidin näkijälle, oli tullut tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, '\"Mene ja puhu Daavidille: Näin sanoo Herra: Kolme vaihtoehtoa minä asetan eteesi. Valitse niistä yksi, niin teen sen sinulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Gaad meni Daavidin luo, ilmoitti ja sanoi hänelle: \"Tuleeko nälkä seitsemäksi vuodeksi maahasi, vai pakenetko sinä kolme kuukautta vihollisiasi, jotka ajavat sinua takaa, vai tuleeko rutto maahasi kolmeksi päiväksi? Mieti nyt ja katso, mitä vastaan hänelle, joka minut lähetti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'Daavid vastasi Gaadille: \"Olen suuressa hädässä. Tahdomme langeta Herran käsiin, sillä hänen laupeutensa on suuri. Ihmisten käsiin en tahdo langeta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Herra antoi ruton tulla Israeliin, aamusta alkaen määrättyyn aikaan asti. Kansaa kuoli Daanista Beersebaan asti seitsemänkymmentä tuhatta miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Mutta kun enkeli ojensi kätensä Jerusalemia kohti tuhotakseen sen, Herra katui sitä pahaa ja sanoi enkelille, joka tuhosi kansaa: \"Jo riittää. Laske kätesi alas.\" Herran enkeli oli silloin jebusilaisen Araunan puimatantereen luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Mutta nähdessään enkelin surmaavan kansaa Daavid sanoi Herralle: \"Katso, minä olen tehnyt syntiä, minä olen tehnyt väärin. Mutta mitä nämä lampaani ovat tehneet? Sattukoon kätesi minuun ja isäni perheeseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Gaad tuli Daavidin luo samana päivänä ja sanoi hänelle: \"Mene ja pystytä Herralle alttari jebusilaisen Araunan puimatantereelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Daavid meni, Gaadin sanan ja Herran käskyn mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Mutta kun Arauna katsoi ulos ja näki kuninkaan palvelijoineen tulevan luokseen, hän meni ulos ja kumartui kasvoilleen maahan kuninkaan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Arauna sanoi: \"Miksi herrani kuningas tulee palvelijansa luo?\" Daavid vastasi: \"Ostamaan sinulta puimatantereen rakentaakseni Herralle alttarin, että vitsaus väistyisi kansasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Arauna sanoi Daavidille: \"Herrani kuningas ottakoon ja uhratkoon, mitä hyväksi näkee. Katso, tässä on härät polttouhriksi ja puimaäkeet sekä härkien kalustoa polttopuiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Tämän kaiken, kuningas, Arauna antaa kuninkaalle.\" Arauna sanoi kuninkaalle: \"Olkoon Herra, Jumalasi, sinulle suosiollinen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Mutta kuningas sanoi Araunalle: \"Ei niin, vaan ostan ne sinulta täydestä hinnasta, sillä en uhraa Herralleni, Jumalalleni, ilmaiseksi saatuja polttouhreja.\" Daavid osti puimatantereen ja härät viidelläkymmenellä hopeasekelillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Daavid rakensi sinne alttarin Herralle ja uhrasi polttouhreja ja rauhanuhreja. Herra armahti maata, ja vitsaus taukosi Israelista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Kun kuningas Daavid oli käynyt vanhaksi ja iäkkääksi, hän ei voinut enää pysyä lämpimänä, vaikka häntä peiteltiin peitteillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Hänen palvelijansa sanoivat hänelle: \"Etsittäköön herralleni kuninkaalle tyttö, neitsyt, palvelemaan kuningasta ja olemaan hänen hoitajattarenaan. Jos hän makaa sylissäsi, herrani kuningas pysyy lämpimänä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'He etsivät koko Israelin alueelta kaunista tyttöä ja löysivät suunemilaisen Abisagin ja veivät hänet kuninkaan luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Hän oli hyvin kaunis tyttö ja tuli kuninkaan hoitajattareksi ja palveli häntä. Kuningas ei kuitenkaan yhtynyt häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Adonia, Haggitin poika, korotti itsensä ja sanoi: \"Minä tahdon tulla kuninkaaksi.\" Hän oli hankkinut itselleen sotavaunuja ja ratsumiehiä ja viisikymmentä miestä, jotka juoksivat hänen edellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Hänen isänsä ei koskaan elämässään ollut pahoittanut hänen mieltään sanomalla: \"Miten sinä noin teet?\" Hän oli myös hyvin kaunis mies, ja äiti oli synnyttänyt hänet Absalomin jälkeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Hän neuvotteli Jooabin, Serujan pojan, ja pappi Ebjatarin kanssa, ja he kannattivat Adonian puoluetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Mutta pappi Saadok ja Benaja, Joojadan poika, sekä profeetta Naatan, Siimei, Rei ja Daavidin sotasankarit eivät olleet Adonian puolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Adonia teurasti lampaita, nautoja ja juottovasikoita Soohelet-kiven luona, joka on Roogelin lähteen vieressä. Hän kutsui kaikki veljensä, kuninkaan pojat, ja kaikki Juudan miehet, kuninkaan palvelijat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'mutta hän jätti kutsumatta profeetta Naatanin, Benajan, sotasankarit ja veljensä Salomon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Naatan sanoi Batseballe, Salomon äidille, näin: \"Etkö ole kuullut, että Adonia, Haggitin poika, on tullut kuninkaaksi, herramme Daavidin siitä mitään tietämättä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Niin tule nyt, annan sinulle neuvon, että pelastat oman henkesi ja poikasi Salomon hengen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Mene kuningas Daavidin luo ja sano hänelle: Herrani, kuningas, etkö sinä itse ole vannonut palvelijattarellesi ja sanonut: Sinun poikasi Salomo on tuleva kuninkaaksi jälkeeni ja hän on istuva valtaistuimellani? Miksi siis Adoniasta on tullut kuningas?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Katso, kun sinä vielä puhuttelet siellä kuningasta, tulen jälkeesi sisään ja vahvistan sanasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Batseba meni kuninkaan luo makuuhuoneeseen. Kuningas oli hyvin vanha, ja suunemilainen Abisag palveli kuningasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Batseba kumarsi ja osoitti kuninkaalle kunnioitusta. Kuningas sanoi: \"Mikä sinun on?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Hän vastasi hänelle: \"Herrani, sinä olet itse vannonut palvelijattarellesi Herran, Jumalasi, kautta: \'Poikasi Salomo on tuleva kuninkaaksi jälkeeni ja hän on istuva valtaistuimellani.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Mutta katso, nyt on Adonia tullut kuninkaaksi, ja sinä, herrani, kuningas, et tiedä siitä mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Hän on teurastanut paljon härkiä, juottovasikoita ja lampaita ja kutsunut kaikki kuninkaan pojat, pappi Ebjatarin ja sotapäällikkö Jooabin, mutta palvelijasi Salomon hän on jättänyt kutsumatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Sinua kohti, herrani kuningas, ovat nyt koko Israelin silmät tähdätyt, että ilmoittaisit heille, kuka on istuva herrani kuninkaan valtaistuimella hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Muuten käy niin, että kun herrani kuningas on mennyt lepoon isiensä luo, minua ja poikaani Salomoa pidetään rikollisina.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Katso, hänen vielä puhutellessaan kuningasta tuli profeetta Naatan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Kuninkaalle ilmoitettiin: \"Katso, profeetta Naatan on täällä.\" Tämä tuli kuninkaan eteen ja kumartui kasvoilleen maahan kuninkaan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Naatan sanoi: \"Herrani kuningas, sinäkö olet sanonut: \'Adonia on tuleva kuninkaaksi jälkeeni. Hän on istuva valtaistuimellani\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Sillä hän on tänä päivänä mennyt ja teurastanut paljon härkiä, juottovasikoita ja lampaita ja kutsunut kaikki kuninkaan pojat, sotapäälliköt ja pappi Ebjatarin. Katso, he syövät ja juovat hänen edessään, ja he huutavat: \'Eläköön kuningas Adonia!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Mutta minut, palvelijasi, pappi Saadokin, Benajan, Joojadan pojan, ja palvelijasi Salomon hän on jättänyt kutsumatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Onko tämä lähtenyt herrastani kuninkaasta ilman, että olisit antanut palvelijasi tietää, kuka on istuva herrani kuninkaan valtaistuimella hänen jälkeensä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Kuningas Daavid vastasi ja sanoi: \"Kutsukaa luokseni Batseba.\" Kun hän tuli kuninkaan eteen ja seisoi kuninkaan edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'vannoi kuningas ja sanoi: \"Niin totta kuin Herra elää, joka on pelastanut minut kaikesta hädästä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'niin kuin minä vannoin sinulle Herran, Israelin Jumalan, kautta ja sanoin: \'Sinun poikasi Salomo on tuleva kuninkaaksi jälkeeni, hän on istuva valtaistuimellani sijassani\', niin minä tänä päivänä teen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Silloin Batseba kumartui kasvoilleen maahan ja osoitti kuninkaalle kunnioitusta ja sanoi: \"Herrani, kuningas Daavid, eläköön iankaikkisesti!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Sitten kuningas Daavid sanoi: \"Kutsukaa luokseni pappi Saadok, profeetta Naatan ja Benaja, Joojadan poika.\" He tulivat kuninkaan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'Kuningas sanoi heille: \"Ottakaa mukaanne herranne palvelijat ja pankaa poikani Salomo oman muulini selkään ja viekää hänet alas Giihonille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Siellä pappi Saadok ja profeetta Naatan voidelkoot hänet Israelin kuninkaaksi. Puhaltakaa torveen ja huutakaa: \'Eläköön kuningas Salomo!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Seuratkaa häntä tänne, että hän tulisi ja istuisi valtaistuimelleni ja olisi kuninkaana sijassani. Sillä hänet olen määrännyt Israelin ja Juudan ruhtinaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Silloin Benaja, Joojadan poika, vastasi kuninkaalle ja sanoi: \"Aamen! Niin sanokoon Herra, herrani kuninkaan Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Niin kuin Herra on ollut herrani kuninkaan, kanssa, niin olkoon hän Salomon kanssa ja tehköön hänen valtaistuimensa vielä suuremmaksi kuin on herrani kuningas Daavidin valtaistuin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Niin pappi Saadok, profeetta Naatan ja Benaja, Joojadan poika, sekä kreetit ja pleetit menivät sinne. He panivat Salomon kuningas Daavidin muulin selkään ja saattoivat hänet Giihonille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Pappi Saadok otti öljysarven telttamajasta ja voiteli Salomon. He puhalsivat torveen, ja kaikki kansa huusi: \"Eläköön kuningas Salomo!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Kaikki kansa seurasi häntä, ja kansa soitti huiluilla ja ratkesi niin suureen riemuun, että maa oli haljeta heidän huudostaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Silloin Adonia ja kaikki kutsuvieraat, jotka olivat hänen kanssaan, kuulivat sen, juuri kun he olivat lopettaneet syömisen. Kun Jooab kuuli torven äänen, hän sanoi: \"Mitä tuo huuto ja pauhu kaupungissa tietää?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Hänen vielä puhuessaan tuli Joonatan, pappi Ebjatarin poika. Adonia sanoi: \"Tule tänne, sillä sinä olet kunnon mies ja tuot hyviä sanomia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Joonatan vastasi ja sanoi Adonialle: \"Päinvastoin! Herramme, kuningas Daavid, on tehnyt Salomon kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Kuningas lähetti hänen kanssaan pappi Saadokin, profeetta Naatanin ja Benajan, Joojadan pojan, sekä kreetit ja pleetit, ja he panivat hänet kuninkaan muulin selkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'Pappi Saadok ja profeetta Naatan voitelivat hänet Giihonilla kuninkaaksi, ja he tulivat sieltä riemuiten, ja koko kaupunki joutui liikkeelle. Sitä oli se huuto, jonka kuulitte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Onpa Salomo jo istunut kuninkaan valtaistuimellakin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'ja kuninkaan palvelijat ovat tulleet onnittelemaan herraamme kuningas Daavidia ja sanoneet: \'Antakoon Jumalasi Salomon nimen tulla vielä maineikkaammaksi kuin sinun nimesi ja tehköön hänen valtaistuimensa vielä suuremmaksi kuin on sinun valtaistuimesi.\' Kuningas on rukoillut vuoteessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Vielä on kuningas puhunut näin: \'Kiitetty olkoon Herra, Israelin Jumala, joka tänä päivänä on asettanut jälkeläisen istumaan valtaistuimellani, niin että olen sen omin silmin nähnyt.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Silloin kaikki Adonian kutsuvieraat joutuivat kauhun valtaan, nousivat ja menivät kukin tiehensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Mutta Adonia pelkäsi Salomoa, nousi, meni ja tarttui alttarin sarviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Salomolle ilmoitettiin: \"Katso, Adonia on peläten kuningas Salomoa tarttunut alttarin sarviin ja sanonut: \'Kuningas Salomo vannokoon minulle tänä päivänä, ettei hän miekalla surmaa palvelijaansa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Salomo sanoi: \"Jos hän osoittautuu kunnon mieheksi, hiuskarvaakaan hänen päästään ei putoa maahan. Mutta jos hänessä huomataan jotakin pahaa, hänen on kuoltava.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Kuningas Salomo lähetti tuomaan hänet pois alttarilta. Hän tuli ja kumarsi kuningas Salomoa, ja Salomo sanoi hänelle: \"Mene kotiisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Kun lähestyi aika, jolloin Daavidin oli kuoltava, hän käski poikaansa Salomoa sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, '\"Minä menen koko maailman tietä. Ole luja ja ole mies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Noudata Herran, Jumalasi, määräyksiä, niin että vaellat hänen teitään ja noudatat hänen säädöksiään, käskyjään, oikeuksiaan ja todistuksiaan, niin kuin on kirjoitettuna Mooseksen laissa, että menestyisit kaikessa, mitä teet, ja kaikkialla, minne käännyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, '[Noudata niitä,] että Herra täyttäisi tämän sanansa, jonka hän on puhunut minusta: \'Jos poikasi pitävät vaarin teistään, niin että vaeltavat edessäni uskollisesti, kaikesta sydämestään ja kaikesta sielustaan, niin on mies suvustasi aina oleva Israelin valtaistuimella.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Sinä tiedät myös, mitä Jooab, Serujan poika, on tehnyt minulle – tiedät, mitä hän teki kahdelle Israelin sotapäällikölle, Abnerille, Neerin pojalle, ja Amasalle, Jeterin pojalle: kuinka hän tappoi heidät vuodattaen sotaverta rauhan aikana ja tahraten sotaverellä vyönsä, joka hänellä oli vyötäisillään, ja sandaalinsa, jotka hänellä oli jalassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Tee nyt viisautesi mukaan äläkä anna hänen harmaiden hapsiensa rauhassa mennä alas hautaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Mutta gileadilaisen Barsillain pojille osoita laupeutta, että he pääsevät niiden joukkoon, jotka syövät pöydästäsi, sillä hekin tulivat avukseni, kun pakenin veljeäsi Absalomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Katso, vielä on luonasi Siimei, Geeran poika, benjaminilainen Bahurimista, joka hirveillä kirouksilla kiroili minua, kun menin Mahanaimiin. Kun hän tuli minua vastaan alas Jordanille, vannoin hänelle Herran kautta ja sanoin: \'Minä en surmaa sinua miekalla.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Mutta älä sinä jätä häntä rankaisematta, sillä sinä olet viisas mies ja tiedät, mitä sinun on hänelle tehtävä, saattaaksesi hänen harmaat hapsensa verisinä alas hautaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Sitten Daavid meni lepoon isiensä luo, ja hänet haudattiin Daavidin kaupunkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Aika, jonka Daavid hallitsi Israelia, oli neljäkymmentä vuotta: Hebronissa hän hallitsi seitsemän vuotta, ja Jerusalemissa hän hallitsi kolmekymmentä kolme vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Salomo istui isänsä Daavidin valtaistuimelle, ja hänen kuninkuutensa tuli hyvin vahvaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Mutta Adonia, Haggitin poika, tuli Batseban, Salomon äidin, luo. Tämä sanoi: \"Rauhaako tulosi tietää?\" Hän vastasi: \"Rauhaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Sitten hän sanoi: \"Minulla on asiaa sinulle.\" Batseba sanoi: \"Puhu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Silloin hän sanoi: \"Sinä tiedät, että kuninkuus oli minun, ja että koko Israel oli kääntänyt katseensa minuun, että minusta tulisi kuningas. Mutta sitten kuninkuus meni minulta pois ja joutui veljelleni, sillä Herralta se hänelle tuli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Yhtä minä nyt sinulta pyydän. Älä sitä minulta kiellä.\" Hän sanoi hänelle: \"Puhu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Hän sanoi: \"Puhu kuningas Salomolle – sillä sinulta hän ei sitä kiellä – että hän antaisi minulle suunemilaisen Abisagin vaimoksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Batseba vastasi: \"Hyvä. Minä puhun kuninkaalle puolestasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Silloin Batseba meni kuningas Salomon luo puhumaan hänelle Adonian puolesta. Kuningas nousi ja meni häntä vastaan ja kumarsi häntä ja istui valtaistuimelleen. Myös kuninkaan äidille asetettiin istuin, ja hän istui hänen oikealle puolelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Hän sanoi: \"Minulla on sinulle pieni pyyntö, älä sitä minulta kiellä.\" Kuningas sanoi hänelle: \"Pyydä, äiti, minä en sinulta kiellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Hän sanoi: \"Annettakoon suunemilainen Abisag veljellesi Adonialle vaimoksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Mutta kuningas Salomo vastasi ja sanoi äidilleen: \"Miksi pyydät vain suunemilaista Abisagia Adonialle? Pyydä myös kuninkuutta hänelle – hänhän on vanhin veljeni – hänelle ja pappi Ebjatarille ja Jooabille, Serujan pojalle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Kuningas Salomo vannoi Herran kautta, sanoen: \"Jumala rangaiskoon minua nyt ja vasta, jollei Adonia saa hengellään maksaa sitä, että on puhunut näin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Nyt, niin totta kuin Herra elää, joka on minut vahvistanut ja on asettanut minut isäni Daavidin valtaistuimelle ja joka lupauksensa mukaan on perustanut sukuni: Adoniaa on tänä päivänä kuolemalla rangaistava.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Kuningas Salomo lähetti Benajan, Joojadan pojan, lyömään hänet kuoliaaksi, ja hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Mutta pappi Ebjatarille kuningas sanoi: \"Mene maatilallesi Anatotiin, sillä sinä olet kuoleman oma. En surmaa sinua tänään, koska olet kantanut Herran Jumalan arkkia isäni Daavidin edessä ja koska olet kärsinyt kaikkea, mitä isäni on kärsinyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Salomo karkotti Ebjatarin olemasta Herran pappina ja täytti sen sanan, minkä Herra oli Siilossa puhunut Eelin suvusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Kun sanoma tästä tuli Jooabille – sillä Jooab oli liittynyt Adoniaan, vaikka hän ei ollut liittynyt Absalomiin – pakeni Jooab Herran telttamajaan ja tarttui alttarin sarviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Mutta kun kuningas Salomolle ilmoitettiin: \"Jooab on paennut Herran telttamajaan ja on alttarin luona\", Salomo lähetti Benajan, Joojadan pojan, sanoen: \"Mene ja lyö hänet kuoliaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Benaja meni Herran telttamajaan ja sanoi hänelle: \"Näin käskee kuningas: \'Tule ulos.\'\" Mutta hän vastasi: \"En, tässä minä kuolen.\" Silloin Benaja palasi kertomaan sen kuninkaalle ja sanoi: \"Näin Jooab puhui, ja näin hän vastasi minulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Kuningas sanoi hänelle: \"Tee, niin kuin hän on puhunut, lyö hänet kuoliaaksi ja hautaa hänet, että poistaisit minusta ja isäni perheestä sen viattoman veren, jonka Jooab on vuodattanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Herra antakoon hänen verensä tulla hänen oman päänsä päälle, koska hän löi kuoliaaksi kaksi miestä, jotka olivat häntä hurskaammat ja paremmat, ja tappoi heidät miekalla isäni Daavidin siitä mitään tietämättä: Abnerin, Neerin pojan, Israelin sotapäällikön, ja Amasan, Jeterin pojan, Juudan sotapäällikön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Heidän verensä tulkoon Jooabin pään päälle ja hänen jälkeläistensä pään päälle, ikuisesti. Mutta Daavidilla ja hänen jälkeläisillään, hänen suvullaan ja hänen valtaistuimellaan olkoon rauha Herralta iankaikkisesti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Benaja, Joojadan poika, meni ja löi hänet kuoliaaksi, ja hänet haudattiin omaan taloonsa erämaahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Kuningas asetti Benajan, Joojadan pojan, hänen sijaansa sotaväen päälliköksi, ja pappi Saadokin kuningas asetti Ebjatarin sijaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Sen jälkeen kuningas lähetti kutsumaan Siimein ja sanoi hänelle: \"Rakenna itsellesi talo Jerusalemiin ja asu siellä menemättä sieltä sinne tai tänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Sillä sinä päivänä, jona lähdet sieltä ja menet Kidronin laakson poikki, sinä päivänä on sinun – tiedä se – kuolemalla kuoltava. Sinun veresi on tuleva oman pääsi päälle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Siimei sanoi kuninkaalle: \"Hyvä on, niin kuin herrani kuningas on puhunut, niin on palvelijasi tekevä.\" Siimei asui Jerusalemissa kauan aikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Mutta kolmen vuoden kuluttua tapahtui, että Siimeiltä karkasi kaksi palvelijaa Aakiin, Maakan pojan, Gatin kuninkaan, luo. Siimeille ilmoitettiin: \"Katso, sinun palvelijasi ovat Gatissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Siimei nousi ja satuloi aasinsa ja lähti Aakiin luo Gatiin etsimään palvelijoitaan, ja Siimei meni ja toi palvelijansa Gatista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Kun Salomolle ilmoitettiin, että Siimei oli mennyt Jerusalemista Gatiin ja palannut takaisin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'kuningas lähetti kutsumaan Siimein ja sanoi hänelle: \"Enkö minä ollut vannottanut sinua Herran kautta ja varoittanut sinua sanoen: \'Sinä päivänä, jona sinä lähdet ja menet sinne tai tänne, sinä päivänä on sinun – tiedä se – kuolemalla kuoltava\'? Niin sinä sanoit minulle: \'Hyvä on, minä olen kuullut.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Miksi et ole pitänyt Herran valaa etkä sitä käskyä, jonka sinulle annoin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Sitten kuningas sanoi vielä Siimeille: \"Sinä tiedät, sydämessäsi tiedät, kaiken pahan, minkä olet tehnyt minun isälleni Daavidille. Herra kääntää tekemäsi pahan omaan päähäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Mutta kuningas Salomo on oleva siunattu, ja Daavidin valtaistuin on oleva iäti vahva Herran edessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Sitten kuningas käski Benajaa, Joojadan poikaa, ja tämä meni ja löi hänet kuoliaaksi, ja hän kuoli. Niin kuninkuus vahvistui Salomon käsissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Salomo tuli faraon, Egyptin kuninkaan, vävyksi: hän otti faraon tyttären vaimokseen. Hän vei hänet Daavidin kaupunkiin, kunnes oli saanut rakennetuksi oman linnansa, Herran temppelin ja Jerusalemin ympärysmuurin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Mutta kansa uhrasi uhrikukkuloilla, koska niihin aikoihin ei vielä ollut rakennettu temppeliä Herran nimelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Salomo rakasti Herraa ja vaelsi isänsä Daavidin käskyjen mukaan. Kuitenkin hän uhrasi ja suitsutti uhrikukkuloilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Kuningas meni Gibeoniin uhraamaan siellä, sillä se oli suurin uhrikukkula. Tuhat polttouhria Salomo uhrasi sillä alttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'Gibeonissa Herra ilmestyi Salomolle yöllä unessa, ja Jumala sanoi: \"Ano, mitä tahdot, että sinulle antaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Salomo vastasi: \"Sinä olet tehnyt suuren laupeuden palvelijallesi, isälleni Daavidille, koska hän vaelsi edessäsi totuudessa ja vanhurskaudessa sekä eheällä sydämellä sinua kohtaan. Olet säilyttänyt hänelle tämän suuren laupeuden ja antanut hänelle pojan, joka istuu hänen valtaistuimellaan, kuten on tänä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Nyt, Herra, Jumalani, sinä olet tehnyt palvelijasi kuninkaaksi isäni Daavidin sijaan. Mutta minä olen kuin pieni poika: en osaa lähteä enkä tulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Palvelijasi on keskellä kansaasi, jonka olet valinnut, niin monilukuista kansaa, että sitä ei voi laskea eikä lukea sen paljouden tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Anna sen tähden palvelijallesi kuuleva sydän jakaakseni oikeutta kansallesi ja erottaakseni hyvän pahasta, sillä kuka voi muuten jakaa oikeutta tälle suurelle kansallesi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Herralle oli otollista, että Salomo tätä anoi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Jumala sanoi hänelle: \"Koska sinä anoit tätä etkä anonut itsellesi pitkää ikää, et rikkautta etkä vihamiestesi henkeä, vaan anoit itsellesi ymmärrystä kuullaksesi, mikä on oikein,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'katso, teen, kuten sanot: katso, annan sinulle viisaan ja ymmärtäväisen sydämen, niin ettei sinun vertaistasi ole ollut ennen sinua eikä tule jälkeesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Lisäksi minä annan sinulle, mitä et anonutkaan: sekä rikkautta että kunniaa, niin ettei koko elinaikanasi ole kuningasten joukossa oleva sinun vertaistasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Jos vaellat teitäni noudattaen säädöksiäni ja käskyjäni, kuten isäsi Daavid vaelsi, niin teen sinusta pitkäikäisen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Siihen Salomo heräsi, ja katso, se oli unta. Kun hän tuli Jerusalemiin, hän astui Herran liitonarkin eteen, uhrasi polttouhreja ja toimitti rauhanuhrin ja laittoi pidot kaikille palvelijoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Siihen aikaan tuli kaksi porttoa kuninkaan luo, ja he astuivat hänen eteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Toinen nainen sanoi: \"Oi herrani, minä ja tämä nainen asumme samassa huoneessa. Synnytin hänen luonaan siinä huoneessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Kolmantena päivänä sen jälkeen, kun olin synnyttänyt, synnytti myös tämä nainen. Me olimme yhdessä. Ketään vierasta ei ollut kanssamme huoneessa. Vain me kahdestaan olimme huoneessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Mutta tämän naisen poika kuoli yöllä, sillä hän oli maannut sen [kuoliaaksi].');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Hän nousi keskellä yötä ja otti minun poikani vierestäni palvelijattaresi nukkuessa ja pani sen povelleen, mutta oman kuolleen poikansa hän pani minun povelleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Kun aamulla nousin imettämään poikaani, niin, katso, se oli kuollut. Mutta kun katsoin sitä tarkasti aamulla, niin, katso, se ei ollutkaan minun poikani, jonka olin synnyttänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Toinen nainen sanoi: \"Ei ole niin, vaan tuo elossa oleva on minun poikani, ja tämä kuollut on sinun poikasi.\" Mutta edellinen vastasi: \"Ei ole niin, tuo kuollut on sinun poikasi, ja tämä elossa oleva on minun poikani.\" Ja he riitelivät kuninkaan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Kuningas sanoi: \"Toinen sanoo: \'Elossa oleva on minun poikani, ja kuollut on sinun poikasi.\' Ja toinen sanoo: \'Ei ole niin, vaan kuollut on sinun poikasi, ja elossa oleva on minun poikani.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Kuningas sanoi: \"Antakaa minulle miekka.\" Kuninkaan eteen tuotiin miekka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Kuningas sanoi: \"Viiltäkää elossa oleva lapsi kahtia, ja antakaa toinen puoli toiselle ja toinen puoli toiselle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Mutta se nainen, jonka oma elossa oleva poika oli, sanoi silloin kuninkaalle – hän näet liikuttui sydämessään poikansa tähden – hän sanoi: \"Oi herrani, antakaa tuolle elossa oleva lapsi, älkää surmatko sitä.\" Mutta toinen sanoi: \"Ei minulle eikä sinulle, viiltäkää!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Kuningas vastasi ja sanoi: \"Antakaa tälle elossa oleva lapsi. Älkää surmatko sitä. Hän on sen äiti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Koko Israel kuuli tästä tuomiosta, jonka kuningas oli antanut, ja he pelkäsivät kuningasta. Sillä he näkivät, että hänessä oli Jumalan viisaus oikeuden jakamiseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Kuningas Salomosta oli tullut koko Israelin kuningas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Nämä olivat hänen ylimmät virkamiehensä: Asarja, Saadokin poika, oli ylimmäisenä pappina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elihoref ja Ahia, Siisan pojat, olivat kirjureina. Joosafat, Ahiludin poika, oli kanslerina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Benaja, Joojadan poika, oli sotaväen ylipäällikkönä. Saadok ja Ebjatar olivat pappeina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Asarja, Naatanin poika, oli ylimaaherrana. Saabud, Naatanin poika, pappi, oli kuninkaan ystävänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Ahisar oli linnanpäällikkönä. Adoniram, Abdan poika, oli verotöiden valvojana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Salomolla oli kaksitoista maaherraa, koko Israelin alueella, joiden oli hankittava kuninkaan ja hänen hovinsa elintarpeet. Kunkin oli hankittava elintarpeet yhtenä kuukautena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Nämä olivat heidän nimensä: Huurin poika Efraimin vuoristossa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Dekerin poika Maakaassa, Saalbimissa, Beet-Semeksessä, Eelonissa ja Beet-Haananissa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Hesedin poika Arubbotissa; hänellä oli Sooko ja koko Heeferin maa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Abinadabin poika koko Doorin kukkula-alueella. Hänellä oli vaimona Taafat, Salomon tytär;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baana, Ahiludin poika, Taanakissa ja Megiddossa ja koko Beet-Seanissa, joka on Saaretanin sivulla Jisreelin alapuolella, Beet-Seanista Aabel-Meholaan asti, tuolle puolelle Jokmeamin;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Geberin poika Gileadin Raamotissa; hänellä oli Jaairin, Manassen pojan, leirikylät, jotka ovat Gileadissa; hänellä oli siis Argobin seutu, joka on Baasanissa, kuusikymmentä suurta, muureilla ja vaskisalvoilla varustettua kaupunkia;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ahinadab, Iddon poika, Mahanaimissa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Ahimaas Naftalissa; hänkin oli ottanut vaimokseen Salomon tyttären, Baasematin;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baana, Huusain poika, Asserissa ja Bealotissa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Joosafat, Paaruahin poika, Isaskarissa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Siimei, Eelan poika, Benjaminissa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Geber, Uurin poika, Gileadin maassa, Siihonin, amorilaisten kuninkaan, ja Oogin, Baasanin kuninkaan, maassa, sillä siinä maassa oli yksi maaherra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Juudaa ja Israelia oli paljon, niin paljon kuin hiekkaa meren rannalla. He söivät ja joivat ja olivat iloisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Salomo hallitsi kaikkia valtakuntia Eufrat-virrasta aina filistealaisten maahan ja Egyptin rajaan asti. He toivat lahjoja ja palvelivat Salomoa, niin kauan kuin hän eli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Salomon jokapäiväinen muona oli: kolmekymmentä koor-mittaa ydinjauhoja ja kuusikymmentä koor-mittaa muita jauhoja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'kymmenen syöttönautaa, kaksikymmentä laitumella käyvää nautaa ja sata lammasta. Näiden lisäksi peuroja, gaselleja, metsäkauriita ja syöttöhanhia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Sillä hän vallitsi kaikkea Eufrat-virran senpuoleista maata, Tifsahista aina Gassaan saakka, kaikkia Eufrat-virran senpuoleisia kuninkaita. Hänellä oli rauha joka puolelta ympäriinsä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'niin että Juuda ja Israel asuivat turvallisesti, itse kukin viinipuunsa ja viikunapuunsa alla, Daanista Beersebaan asti, niin kauan kuin Salomo eli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Salomolla oli neljäkymmentä tuhatta hevosvaljakkoa vaunujaan varten ja kaksitoista tuhatta ratsuhevosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Maaherrat hankkivat kukin kuukautenaan elintarpeet kuningas Salomolle ja kaikille, joilla oli pääsy kuningas Salomon pöytään, antamatta minkään puuttua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'He toivat kukin vuorollaan myös ohrat ja oljet hevosille ja juoksijoille siihen paikkaan, missä hän oleskeli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Jumala antoi Salomolle viisautta ja ymmärrystä hyvin runsaasti ja sydämen laajakatseisuutta niin paljon, kuin on hiekkaa meren rannalla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'niin että Salomon viisaus oli suurempi kuin kaikkien Idän miesten ja kaikkien egyptiläisten viisaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Hän oli viisaampi kaikkia ihmisiä, viisaampi kuin esrahilainen Eetan ja Heeman, Kalkol ja Darda, Maaholin pojat. Hänen nimensä tuli kuuluisaksi kaikkien ympärillä olevien kansojen keskuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Salomo lausui kolmetuhatta sananlaskua, ja hänen laulujaan oli tuhatviisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Hän puhui puista, Libanonin setripuusta alkaen iisoppiin asti, joka kasvaa seinän vieressä. Hän puhui myös karjaeläimistä, linnuista, matelijoista ja kaloista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Salomon viisautta tultiin kuulemaan kaikista kansoista, kaikkien maan kuninkaiden luota, jotka olivat kuulleet hänen viisaudestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Hiiram, Tyyron kuningas, lähetti palvelijoitaan Salomon luo kuultuaan, että hänet oli voideltu kuninkaaksi isänsä jälkeen. Hiiram oli näet aina ollut Daavidin läheinen ystävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Salomo lähetti Hiiramille tämän sanan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, '\"Sinä tiedät, ettei isäni Daavid voinut rakentaa temppeliä Herran, Jumalansa, nimelle niiden sotien tähden, joilla häntä joka puolelta ahdistettiin, kunnes Herra oli laskenut viholliset hänen jalkojensa alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Mutta nyt Herra, minun Jumalani, on suonut minun päästä rauhaan joka taholla. Ei ole vastustajaa eikä vaaran uhkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 19, 'Sen tähden aion rakentaa temppelin Herran, Jumalani, nimelle, niin kuin Herra puhui isälleni Daavidille, sanoen: \'Sinun poikasi, jonka asetan valtaistuimellesi sijaasi, on rakentava nimelleni temppelin.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 20, 'Käske nyt hakata minulle setripuita Libanonilta. Minun palvelijani olkoot sinun palvelijoittesi kanssa. Annan sinulle palvelijoittesi palkan, aivan niin kuin sinä määräät. Sillä sinä tiedät, ettei meillä ole ketään, joka osaisi niin hakata puita kuin siidonilaiset.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 21, 'Kun Hiiram kuuli Salomon sanat, hän tuli hyvin iloiseksi ja sanoi: \"Kiitetty olkoon tänä päivänä Herra, joka on antanut Daavidille viisaan pojan hallitsemaan tuota monilukuista kansaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 22, 'Hiiram lähetti Salomolle tämän sanan: \"Olen kuullut sanan, jonka minulle lähetit. Olen täyttävä kaikessa toivomuksesi, mitä tulee setripuihin ja sypressipuihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 23, 'Minun palvelijani vetäkööt ne Libanonilta alas mereen, ja minä käsken panna ne meressä lauttoihin kuljetettaviksi paikkaan, minkä sinä minulle määräät, ja hajotan ne siellä. Sinä saat noutaa ne sieltä. Mutta täytä sinä minun toivomukseni ja anna minun hovilleni muonaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 24, 'Niin Hiiram antoi Salomolle setripuita ja sypressipuita niin paljon, kuin tämä toivoi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 25, 'Mutta Salomo antoi Hiiramille kaksikymmentä tuhatta koor-mittaa vehnää ravinnoksi hänen hovilleen ja kaksikymmentä koor-mittaa survomalla saatua öljyä. Tämän Salomo antoi Hiiramille joka vuosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 26, 'Herra oli antanut Salomolle viisautta, kuten hän oli hänelle luvannut. Rauha vallitsi Hiiramin ja Salomon välillä, ja he tekivät liiton keskenään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 27, 'Kuningas Salomo otti verotyöläisiä koko Israelista, ja verotyöläisiä oli kolmekymmentä tuhatta miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 28, 'Nämä hän lähetti Libanonille vuorotellen, kymmenentuhatta kunakin kuukautena, niin että he olivat yhden kuukauden Libanonilla ja kaksi kuukautta kotonaan. Verotöiden valvojana oli Adoniram.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 29, 'Salomolla oli seitsemänkymmentä tuhatta taakankantajaa ja kahdeksankymmentä tuhatta kivenhakkaajaa vuoristossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 30, 'Sen lisäksi Salomon maaherrojen virkamiehiä, jotka valvoivat töitä, oli kolmetuhatta kolmesataa miestä, johtamassa väkeä, joka teki työtä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 31, 'Kuningas käski louhia suuria kiviä, kallisarvoisia kiviä, laskeakseen temppelin perustuksen hakatuista kivistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 32, 'Salomon ja Hiiramin rakentajat ja gebalilaiset hakkasivat niitä ja valmistivat puut ja kivet temppelin rakentamiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Neljäntenäsadantena kahdeksantenakymmenentenä vuotena siitä, kun israelilaiset olivat lähteneet Egyptin maasta, neljäntenä vuotena siitä, kun Salomo oli tullut Israelin kuninkaaksi, hän alkoi siiv-kuussa, joka on toinen kuukausi, rakentaa temppeliä Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Temppeli, jonka kuningas Salomo Herralle rakensi, oli kuusikymmentä kyynärää pitkä, kaksikymmentä kyynärää leveä ja kolmekymmentä kyynärää korkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Temppelisalin eteinen, joka oli temppelin itäpäässä, oli kaksikymmentä kyynärää pitkä, ja sen leveys temppelin itäsuuntaan oli kymmenen kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Hän teki temppeliin sisäänpäin avartuvat ikkuna-aukot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Hän rakensi temppelin seiniin kiinni kylkirakennuksen. Se kiersi temppelin seinien, sekä temppelisalin että kaikkeinpyhimmän, ympäri. Hän teki siihen kaikkialle sivuhuoneita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Kylkirakennuksen alin kerros oli viisi kyynärää leveä, keskimmäinen kuusi kyynärää leveä ja kolmas seitsemän kyynärää leveä. Hän näet teki temppelin muurille ympäriinsä ulkoneman, ettei tukirakennelmia tarvittu temppelin seiniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Kun temppeli rakennettiin, tehtiin se kivistä, jotka tulivat valmiina louhimolta, niin ettei kuulunut vasaran, ei minkään rauta-aseen kalketta temppeliä rakennettaessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Alimman kerroksen ovi oli temppelin eteläsivussa. Portaita myöten noustiin keskimmäiseen kerrokseen ja keskimmäisestä kolmanteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Rakennettuaan temppelin valmiiksi hän laudoitti sen sisältä setripuisilla parruilla ja laudoilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Hän rakensi kauttaaltaan kiinni temppeliin kylkirakennuksen, jonka kerrokset olivat viiden kyynärän korkuiset ja joka oli kiinnitetty temppeliin setripalkeilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Salomolle tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, '\"Tälle temppelille, jota rakennat, käy näin: jos vaellat säädöksieni mukaan ja noudatat oikeuksiani, otat vaarin kaikista käskyistäni vaeltaaksesi niissä, niin täytän sinulle sanani, jonka olen puhunut isällesi Daavidille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'ja asun israelilaisten keskellä enkä hylkää kansaani Israelia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Salomo rakensi temppelin valmiiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Hän laudoitti temppelin seinät sisäpuolelta setrilaudoilla. Temppelin lattiasta kattopalkkeihin asti hän päällysti puulla sisäpuolelta. Temppelin lattian hän päällysti sypressilaudoilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Temppelin peräosan, kaksikymmentä kyynärää, hän laudoitti erilleen setrilaudoilla lattiasta kattopalkkeihin asti. Hän rakensi siihen sisälle kuorin, kaikkeinpyhimmän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Temppeli, se on temppelisali kaikkeinpyhimmän edessä, oli neljäkymmentä kyynärää pitkä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Temppeli oli sisäpuolelta setripuuta, koristettu metsäkurpitsa- ja kukkakiehkura-leikkauksin. Kaikki oli setripuuta, kiveä ei näkynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Temppelin sisään hän laittoi kaikkeinpyhimmän pannakseen sinne Herran liitonarkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Kaikkeinpyhin oli kaksikymmentä kyynärää pitkä, kaksikymmentä kyynärää leveä ja kaksikymmentä kyynärää korkea. Hän päällysti sen sisältä puhtaalla kullalla, ja hän teki alttarin setripuusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Salomo päällysti temppelin sisäpuolelta puhtaalla kullalla. Hän sulki kultaketjuilla kaikkeinpyhimmän, jonka oli päällystänyt kullalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Koko temppelin hän päällysti sisältä kullalla, koko temppelin joka kohdasta. Myös koko sen alttarin, joka oli kaikkeinpyhimmän edessä, hän päällysti kullalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Hän teki kaikkeinpyhimpään kaksi kerubia öljypuusta, kymmenen kyynärän korkuisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Kerubin toinen siipi oli viisi kyynärää, ja kerubin toinen siipi oli myös viisi kyynärää, niin että toisen siiven kärjestä toisen kärkeen oli kymmenen kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Toinen kerubi oli myös kymmenen kyynärää. Molemmat kerubit olivat yhtä suuret ja yhdenmuotoiset:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'toinen kerubi oli kymmenen kyynärää korkea ja samoin toinenkin kerubi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Hän asetti kerubit temppelin sisimpään osaan. Kerubit levittivät siipensä niin, että toisen siipi kosketti toista seinää ja toisen kerubin siipi kosketti toista seinää. Temppelin keskikohdalla koskettivat niiden toiset siivet toisiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Hän päällysti kerubit kullalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Kaikkiin temppelin seiniin ympäriinsä hän leikkautti veistoksia, kerubeja, palmuja ja kukkakiehkuroita sekä perä- että etuosaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Temppelin lattian hän päällysti kullalla, sekä perä- että etuosan lattian.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Kaikkeinpyhimmän oviaukkoon hän teki ovet öljypuusta. Kamana ja pielet muodostivat viisikulmion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Molempiin öljypuusta tehtyihin oviin hän leikkautti kerubeja, palmuja ja kukkakiehkuroita, ja päällysti ne kullalla. Hän levitti kultaa kerubien ja palmujen päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Hän teki myös temppelisalin oviaukkoon öljypuusta pielet, neliön muotoiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'ja sypressipuusta kaksi ovea. Toisen oven molemmat laudat olivat kääntyviä, ja toisen oven molemmat laudat olivat kääntyviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Hän leikkautti niihin kerubeja, palmuja ja kukkakiehkuroita ja päällysti ne kullalla, joka levitettiin veistosten päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Hän rakensi sisemmän esipihan muurin, jossa oli aina rinnakkain kolme kivikertaa hakattuja kiviä ja yksi hirsikerta veistettyjä setrihirsiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Neljäntenä vuotena, siiv-kuussa, laskettiin Herran temppelin perustus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'Yhdentenätoista vuotena, buul-kuussa, joka on kahdeksas kuukausi, temppeli oli kokonaan ja kaikkineen valmis. Hän rakensi sitä seitsemän vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Mutta omaa linnaansa Salomo rakensi kolmetoista vuotta, kunnes sai koko linnansa valmiiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Hän rakensi talon Libanonin metsästä [tuoduista puista], sata kyynärää pitkän, viisikymmentä kyynärää leveän ja kolmekymmentä kyynärää korkean, kolmen setripylväsrivin varaan, ja pylväiden päällä oli veistetyt setriset ansaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Siinä oli setripuukatto sivukammioiden päällä, jotka olivat pylväiden varassa. Pylväitä oli yhteensä neljäkymmentä viisi, viisitoista kussakin rivissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Ikkunoita oli siinä kolmessa rivissä, ja valoaukot olivat vastakkain, aina kolme ja kolme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Kaikki oviaukot ja valoaukot olivat nelikulmaiset. Oviaukot olivat vastakkain, aina kolme ja kolme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Hän rakensi myös pylvässalin, viisikymmentä kyynärää pitkän ja kolmekymmentä kyynärää leveän, ja sen eteen eteisen pylväineen sekä pylväiden eteen porraskatoksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Sitten hän teki valtaistuinsalin, jossa hän jakoi oikeutta, oikeussalin. Se oli laudoitettu sisältä setripuulla lattiasta kattoon asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Hänen linnansa, jossa hän itse asui, oli toisella esipihalla, salin takana, ja oli rakennettu samalla tavalla. Salomo teki myös faraon tyttärelle, jonka hän oli nainut, palatsin, samanlaisen kuin sali.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Kaikki nämä olivat rakennetut kallisarvoisista, mitan mukaan hakatuista ja sisältä ja ulkoa sahalla sahatuista kivistä perustuksesta räystäisiin asti, samoin ulkopuolella suureen esipihaan saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Perustus oli laskettu kallisarvoisista kivistä, suurista kivistä, kymmenkyynäräisistä ja kahdeksankyynäräisistä kivistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Sen päällä oli kallisarvoisia, mitan mukaan hakattuja kiviä sekä setripuuta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Suuren esipihan muurissa oli ympäriinsä aina rinnakkain kolme kivikertaa hakattuja kiviä ja yksi hirsikerta veistettyjä setrihirsiä. Samoin oli rakennettu Herran temppelin sisemmän esipihan muuri ja myös palatsin eteisen esipihan muuri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Kuningas Salomo lähetti noutamaan Hiiramin Tyyrosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Hän oli leskivaimon poika Naftalin sukukunnasta, ja hänen isänsä oli ollut tyyrolainen vaskiseppä. Hän oli täynnä taitoa, ymmärrystä ja tietoa, niin että hän kykeni valmistamaan kaikenlaisia vaskitöitä. Hän saapui kuningas Salomon luo ja valmisti kaikki hänen työnsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Hän teki vaskesta kaksi pylvästä. Toinen pylväs oli kahdeksantoista kyynärää korkea, ja kaksitoista kyynärää pitkä nauha ulottui toisen pylvään ympäri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Hän teki myös kaksi pylväänpäätä, vaskesta valettua, pylväiden päähän pantavaksi. Kummankin pylväänpään korkeus oli viisi kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Verkon kaltaisia ristikkokoristeita, ketjun kaltaisia riippukoristeita, oli pylväänpäissä, jotka olivat pylväiden päässä, seitsemän kummassakin pylväänpäässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Hän teki granaattiomenia kahteen riviin toisen ristikkokoristeen päälle ympäriinsä peittämään pylväänpäät, jotka olivat pylväiden päässä, ja samoin hän teki niitä toiseen pylväänpäähän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Pylväänpäät, jotka olivat pylväiden päässä eteisessä, olivat liljan muotoiset, nelikyynäräiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Pylväänpäissä, ylhäällä kahden pylvään päässä, olivat kuperat alaosat, joihin ristikkokoriste ei ulottunut. Granaattiomenia oli kaksisataa, riveittäin yltympäri toisen pylväänpään päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Hän pystytti pylväät temppelin eteisen eteen. Pylväälle, jonka hän pystytti oikealle puolelle, hän antoi nimen Jaakin, ja pylväälle, jonka hän pystytti vasemmalle puolelle, hän antoi nimen Booas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Ylinnä pylväiden päällä oli liljan muotoinen sommitelma. Niin päättyi pylväiden valmistus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Hän teki myös meren, valetun, kymmenen kyynärää leveän reunasta reunaan, ympäriinsä pyöreän ja viisi kyynärää korkean. Kolmekymmentä kyynärää pitkä mittanuora ulottui sen ympäri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Sen reunan alla oli metsäkurpitsakoristeita, jotka kulkivat sen ympäri. Ne ympäröivät merta ympäriinsä, kymmenen joka kyynärällä. Metsäkurpitsakoristeet olivat kahdessa rivissä, valettuina meren kanssa yhteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Se seisoi kahdentoista naudan varassa, joista kolme oli käännettynä pohjoiseen, kolme länteen, kolme etelään ja kolme itään päin. Meri oli niiden yläpuolella, niiden varassa, ja kaikkien niiden pakarat olivat sisäänpäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Se oli kämmenen paksuinen, ja sen reuna oli maljan reunan kaltainen, puhjenneen liljan muotoinen. Se veti kaksituhatta bat-mittaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Hän teki myös kymmenen telinettä vaskesta. Kukin teline oli neljä kyynärää pitkä, neljä kyynärää leveä ja kolme kyynärää korkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Telineet olivat rakenteeltaan tällaiset: niissä oli kehäpienat, ja myös poikkitankojen välissä oli kehäpienat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'Kehäpienojen päällä, jotka olivat poikkitankojen välissä, oli leijonia, nautoja ja kerubeja, ja samoin poikkitankojen päällä, sekä ylhäällä että alhaalla. Leijonissa ja naudoissa oli takomalla tehtyjä punoskoristeita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Kussakin telineessä oli neljä vaskipyörää ja vaskiakselit, ja niiden neljässä jalkapylväässä oli olkapää. Olkapäät olivat valetut altaan alle. Kunkin ulkopuolella oli punoskoristeita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Telineen aukko oli olkapäiden sisäpuolella, ja sen reuna oli kyynärän korkuinen. Aukko oli pyöreä, jalustan tapaan tehty, puolitoistakyynäräinen. Myös aukon reunassa oli leikkauksia. Kehäpienat olivat nelikulmaiset eivätkä pyöreät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Neljä pyörää oli kehäpienojen alla, ja pyörien pitimet olivat telineessä kiinni. Kukin pyörä oli puolitoista kyynärää korkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Pyörät olivat tehdyt kuin vaununpyörät, ja niiden pitimet, kehät, puolat ja navat olivat kaikki valetut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Neljä olkapäätä oli kussakin telineessä, sen neljässä kulmassa. Olkapäät olivat yhtä telineen kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Ylinnä telineen päällä oli puolen kyynärän korkuinen laite, ympäriinsä pyöreä. Telineen pitimet ja kehäpienat olivat yhtä sen kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Sen kehäpienojen pintoihin hän kaiversi kerubeja, leijonia ja palmuja, niin paljon kuin kussakin oli tilaa, sekä punonnaiskoristeita yltympäri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Hän teki kymmenen telinettä. Ne olivat kaikki valetut samalla tavalla, yhtä suuret ja yhdenmuotoiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Hän teki myös kymmenen vaskiallasta. Kukin allas veti neljäkymmentä bat-mittaa, ja kukin allas oli neljä kyynärää läpimitaltaan. Kullakin kymmenellä telineellä oli altaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Hän asetti viisi telinettä temppelin oikealle sivulle ja viisi temppelin vasemmalle sivulle. Meren hän asetti temppelin oikealle sivulle kohti kaakkoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Hiiram teki myös kattilat, lapiot ja maljat. Sitten Hiiram sai suoritetuksi kaiken työn, mikä hänen oli tehtävä kuningas Salomolle Herran temppeliin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'kaksi pylvästä ja kaksi pallonmuotoista pylväänpäätä, jotka olivat pylväiden päässä, ja kaksi ristikkokoristetta peittämään kahta pallonmuotoista pylväänpäätä, jotka olivat pylväiden päässä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'ja neljäsataa granaattiomenaa kahteen ristikkokoristeeseen, kaksi riviä granaattiomenia kumpaankin ristikkokoristeeseen peittämään kahta pallonmuotoista pylväänpäätä, jotka olivat pylväiden päässä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'kymmenen telinettä ja kymmenen allasta telineiden päälle;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'ja meri, ja kaksitoista nautaa meren alle, lisäksi kattilat, lapiot ja maljat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'Kaikki nämä esineet, jotka Hiiram teki kuningas Salomolle Herran temppeliin, olivat kiillotetusta vaskesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'Jordanin lakeudella kuningas valoi ne savimuotteihin, Sukkotin ja Saaretanin välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Salomo jätti kaikki esineet punnitsematta, koska niitä oli hyvin paljon, vasken painoa ei määritelty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Salomo teetti myös kaikki muut esineet, mitä Herran temppelissä on: kulta-alttarin, kultaisen pöydän, jolla näkyleivät ovat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'lampunjalat, viisi oikealle puolelle ja viisi vasemmalle puolelle kaikkeinpyhimmän eteen, puhtaasta kullasta, kultaisine kukkalehtineen, lamppuineen ja lamppusaksineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'vadit, veitset, maljat, kupit ja hiilipannut, puhtaasta kullasta, sekä kultasaranat niihin temppelin sisäosan oviin, jotka vievät kaikkeinpyhimpään, ja niihin temppelin oviin, jotka vievät temppelisaliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Kun kaikki työ, minkä kuningas Salomo teetti Herran temppeliin, oli valmis, Salomo vei sinne isänsä Daavidin pyhät lahjat. Hän pani hopean, kullan ja esineet Herran temppelin aarrekammioihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Salomo kokosi Israelin vanhimmat ja kaikki sukukuntien johtomiehet, israelilaisten perhekuntapäämiehet, kuningas Salomon luo Jerusalemiin, tuomaan Herran liitonarkkia Daavidin kaupungista, se on Siionista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Kuningas Salomon luo kokoontuivat kaikki Israelin miehet juhlapäivänä eetanim-kuussa, joka on seitsemäs kuukausi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Kun kaikki Israelin vanhimmat olivat tulleet saapuville, nostivat papit arkin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'ja veivät Herran arkin ja ilmestysmajan sinne, sekä kaiken pyhän kaluston, joka oli telttamajassa. Papit ja leeviläiset veivät ne sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Kuningas Salomo seisoi arkin edessä ja hänen kanssaan koko Israelin kansa, joka oli kokoontunut hänen luokseen. He uhrasivat lampaita ja nautoja niin paljon, ettei niitä voitu lukea eikä laskea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Papit toivat Herran liitonarkin paikoilleen temppelin kuoriin, kaikkeinpyhimpään, kerubien siipien alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Sillä kerubit levittivät siipensä sen paikan yli, missä arkki oli, ja kerubit suojasivat ylhäältä päin arkkia ja sen korentoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Korennot olivat niin pitkät, että niiden päät saattoi nähdä kaikkeinpyhimmästä kuorin edestä, mutta ulkoa niitä ei voinut nähdä. Ne jäivät sinne tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Arkissa ei ollut muuta kuin ne kaksi kivitaulua, jotka Mooses oli pannut sinne Hoorebilla, kun Herra teki liiton israelilaisten kanssa, heidän lähdettyään Egyptin maasta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Kun papit lähtivät pyhäköstä, pilvi täytti Herran temppelin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'niin että papit eivät voineet astua toimittamaan virkaansa pilven tähden, sillä Herran kirkkaus täytti Herran temppelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Salomo sanoi: \" Herra on sanonut tahtovansa asua pimeässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Minä olen rakentanut huoneen sinulle asunnoksi, asuinpaikan, asuaksesi siinä iäti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Kuningas käänsi kasvonsa ja siunasi koko Israelin seurakunnan, ja koko Israelin seurakunta seisoi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Hän sanoi: \"Kiitetty olkoon Herra, Israelin Jumala, joka kädellään on täyttänyt sen, mitä hän suullaan puhui isälleni Daavidille, sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, '\'Siitä päivästä saakka, jona vein kansani Israelin pois Egyptistä, en ole mistään Israelin sukukunnasta valinnut yhtään kaupunkia, että siihen rakennettaisiin temppeli, jossa nimeni asuisi. Mutta olen valinnut Daavidin hallitsemaan kansaani Israelia.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Isäni Daavid aikoi rakentaa temppelin Herran, Israelin Jumalan, nimelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Mutta Herra sanoi isälleni Daavidille: \'Kun aiot rakentaa temppelin nimelleni, niin tosin teet siinä hyvin, että sitä aiot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Kuitenkaan sinä et ole temppeliä rakentava, vaan poikasi, joka lähtee kupeistasi. Hän on rakentava temppelin nimelleni.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Herra on täyttänyt sanansa, jonka hän puhui: olen noussut isäni Daavidin sijaan ja istun Israelin valtaistuimella, niin kuin Herra puhui, ja olen rakentanut temppelin Herran, Israelin Jumalan, nimelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'Olen valmistanut siihen paikan arkille, jossa on Herran liitto, minkä hän teki isiemme kanssa viedessään heidät pois Egyptin maasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Salomo astui Herran alttarin eteen koko Israelin seurakunnan nähden, ojensi kätensä taivasta kohti');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'ja sanoi: \" Herra, Israelin Jumala, ei ole vertaistasi jumalaa, ei ylhäällä taivaassa eikä alhaalla maan päällä, sinun, joka pidät liiton ja säilytät laupeuden palvelijoitasi kohtaan, jotka vaeltavat edessäsi kaikesta sydämestään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'sinun, joka olet pitänyt, mitä puhuit palvelijallesi Daavidille, isälleni. Mitä suullasi puhuit, sen sinä kädelläsi täytit, kuten nyt on tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Nyt, Herra, Israelin Jumala, pidä, mitä puhuit palvelijallesi Daavidille, isälleni, sanoen: \'Aina on mies suvustasi istuva edessäni Israelin valtaistuimella, jos vain poikasi pitävät vaarin tiestään, että he vaeltavat edessäni, niin kuin sinä olet edessäni vaeltanut.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Toteutukoot nyt, Israelin Jumala, sanasi, jotka puhuit palvelijallesi Daavidille, isälleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Mutta asuuko todella Jumala maan päällä? Katso, taivaisiin ja taivasten taivaisiin sinä et mahdu, kuinka sitten tähän temppeliin, jonka olen rakentanut!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Käänny kuitenkin palvelijasi rukouksen ja anomisen puoleen, Herra, Jumalani, niin että kuulet huudon ja rukouksen, jonka palvelijasi tänä päivänä rukoilee edessäsi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'ja että silmäsi ovat yöt ja päivät avoinna tätä temppeliä kohti, tätä paikkaa kohti, josta olet sanonut: \'Nimeni on asuva siellä\', niin että kuulet rukouksen, jonka palvelijasi tähän paikkaan päin kääntyneenä rukoilee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Kuule palvelijasi ja kansasi Israelin rukous, jonka he rukoilevat tähän paikkaan päin kääntyneinä, kuule asuinpaikastasi, taivaasta, ja kun kuulet, niin anna anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Jos joku rikkoo lähimmäistään vastaan ja hänet pannaan valalle ja vannotetaan, ja jos hän tulee ja vannoo alttarisi edessä tässä temppelissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'kuule taivaasta ja auta palvelijasi oikeuteensa. Tee niin, että tuomitset syyllisen syylliseksi ja annat hänen tekojensa tulla hänen päänsä päälle, mutta julistat syyttömän syyttömäksi ja annat hänelle hänen vanhurskautensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Jos vihollinen voittaa kansasi Israelin, sen tähden että he ovat tehneet syntiä sinua vastaan, mutta he palaavat luoksesi, kiittävät nimeäsi, rukoilevat sinua ja anovat sinulta armoa tässä temppelissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'kuule taivaasta ja anna anteeksi kansasi Israelin synti ja tuo heidät takaisin tähän maahan, jonka olet antanut heidän isilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Jos taivas suljetaan, niin ettei tule sadetta, koska he ovat tehneet syntiä sinua vastaan, mutta he rukoilevat kääntyneinä tähän paikkaan päin, ja kiittävät nimeäsi ja kääntyvät synnistään, koska kuulet heitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'niin kuule taivaasta ja anna anteeksi palvelijoidesi ja kansasi Israelin synti – sillä sinä osoitat heille hyvän tien, jota heidän tulee vaeltaa – ja suo sade maallesi, jonka olet antanut kansallesi perintöosaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Jos maahan tulee nälänhätä, rutto, jos tulee nokitähkä ja viljanruoste, jos tulevat heinäsirkat ja tuhosirkat, jos vihollinen ahdistaa sitä maassa, jossa sen portit ovat, jos tulee mikä tahansa vitsaus tai vaiva,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'ja jos joku ihminen, kuka hyvänsä, tai koko kansasi Israel rukoilee ja anoo armoa, kun he kukin tuntevat omantunnon vaivoja ja ojentavat kätensä tähän temppeliin päin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'kuule silloin taivaasta, asuinpaikastasi, ja anna anteeksi ja tee niin, että annat jokaiselle aivan hänen tekojensa mukaan, koska sinä tunnet hänen sydämensä – sillä sinä yksin tunnet kaikkien ihmislasten sydämet –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'jotta he sinua pelkäisivät niin kauan kuin he elävät tässä maassa, jonka olet isillemme antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Myös jos joku muukalainen, joka ei ole kansaasi Israelia, tulee kaukaisesta maasta nimesi tähden –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, 'sillä sielläkin kuullaan suuresta nimestäsi, väkevästä kädestäsi ja ojennetusta käsivarrestasi – jos hän tulee ja rukoilee kääntyneenä tähän temppeliin päin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'niin kuule taivaasta, asuinpaikastasi, häntä ja tee kaikki, mitä muukalainen sinulta rukoilee, että kaikki maan kansat tuntisivat nimesi ja pelkäisivät sinua, samoin kuin kansasi Israel, ja tulisivat tietämään, että olet ottanut nimiisi tämän temppelin, jonka olen rakentanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Jos kansasi lähtee sotaan vihollistaan vastaan sitä tietä, jota sinä heidät lähetät, ja he rukoilevat Herraa kääntyneinä tähän kaupunkiin päin, jonka olet valinnut, ja tähän temppeliin päin, jonka olen nimellesi rakentanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'niin kuule taivaasta heidän rukouksensa ja anomisensa ja hanki heille oikeus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Jos he tekevät syntiä sinua vastaan – sillä ei ole ihmistä, joka ei syntiä tee – ja sinä vihastut heihin ja annat heidät vihollisen valtaan, niin että heidän vangitsijansa vievät heidät vangeiksi vihollismaahan, kaukaiseen tai läheiseen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'mutta jos he sitten menevät itseensä siinä maassa, johon heidät on viety vangeiksi, kääntyvät ja anovat sinulta armoa vangitsijoittensa maassa, sanoen: \'Me olemme tehneet syntiä, tehneet väärin ja olleet jumalattomat\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'ja palaavat luoksesi kaikesta sydämestään ja kaikesta sielustaan vihollistensa maassa, jotka veivät heidät vangeiksi, ja rukoilevat sinua kääntyneinä tähän maahan päin, jonka sinä olet antanut heidän isilleen, tähän kaupunkiin päin, jonka olet valinnut, ja tähän temppeliin päin, jonka minä olen nimellesi rakentanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'kuule taivaasta, asuinsijastasi, heidän rukouksensa ja anomisensa, hanki heille oikeus');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'ja anna anteeksi kansallesi, mitä he ovat rikkoneet sinua vastaan, ja kaikki heidän syntinsä, jotka he ovat tehneet sinua vastaan, ja suo, että heidän vangitsijansa olisivat laupiaat heitä kohtaan ja armahtaisivat heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Sillä ovathan he kansasi ja perintöosasi, jonka olet vienyt pois Egyptistä, rautapätsistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Olkoot siis silmäsi avoinna palvelijasi ja kansasi Israelin anomisen puoleen, niin että kuulet heitä kaikessa, mitä he sinulta rukoilevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Sillä sinä olet erottanut heidät perintöosaksesi kaikista maan kansoista, niin kuin puhuit palvelijasi Mooseksen kautta viedessäsi isämme pois Egyptistä, Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Kun Salomo oli lakannut rukoilemasta ja anomasta Herralta kaikkea tätä, hän nousi Herran alttarin edestä, jossa hän oli ollut polvillaan kädet ojennettuina taivasta kohti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'astui esille ja siunasi koko Israelin seurakunnan suurella äänellä sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, '\"Kiitetty olkoon Herra, joka on antanut levon kansalleen Israelille, aivan niin kuin hän on puhunut. Ei ole jäänyt täyttämättä ainoakaan kaikista lupauksista, jotka Herra on antanut palvelijansa Mooseksen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Olkoon Herra, Jumalamme, kanssamme, niin kuin hän on ollut isiemme kanssa. Älköön hän meitä jättäkö älköönkä hylätkö,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'vaan kääntäköön sydämemme puoleensa, niin että aina vaellamme hänen teitään ja noudatamme hänen käskyjään, säädöksiään ja oikeuksiaan, jotka hän on antanut isillemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Olkoot nämä sanani, joilla olen anonut armoa Herran edessä, päivät ja yöt Herraa, meidän Jumalaamme lähellä, että hän hankkisi oikeuden palvelijalleen ja kansalleen Israelille, kunkin päivän tarpeen mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'niin että kaikki maan kansat tulisivat tietämään, että Herra on Jumala eikä muuta jumalaa ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Olkoon sydämenne eheästi Herran, Jumalanne kanssa, niin että vaellatte hänen säädöksiensä mukaan ja noudatatte hänen käskyjään samoin kuin nytkin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Sitten kuningas ja koko Israel hänen kanssaan uhrasivat teurasuhrin Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Salomo uhrasi rauhanuhrina, jonka hän Herralle uhrasi, kaksikymmentäkaksi tuhatta nautaa ja satakaksikymmentä tuhatta lammasta. He, kuningas ja kaikki israelilaiset, vihkivät Herran temppelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'Sinä päivänä kuningas pyhitti Herran temppelin edessä olevan esipihan keskiosan, sillä hänen oli uhrattava siellä polttouhri, ruokauhri ja rauhanuhrin rasvat. Vaskialttari, joka oli Herran edessä, oli näet liian pieni, jotta polttouhri, ruokauhri ja rauhanuhrin rasvat olisivat siihen mahtuneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Salomo vietti siihen aikaan juhlaa, ja koko Israel hänen kanssaan, Herran, Jumalamme, edessä seitsemän päivää ja vielä toiset seitsemän päivää, yhteensä neljätoista päivää. Se oli suuri kokous, johon kokoonnuttiin aina sieltä, mistä mennään Hamatiin, ja aina Egyptin purolta asti');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Kahdeksantena päivänä hän päästi kansan menemään, ja he hyvästelivät kuninkaan. Sitten he menivät teltoilleen iloiten ja hyvillä mielin kaikesta hyvästä, mitä Herra oli tehnyt palvelijalleen Daavidille ja kansalleen Israelille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Kun Salomo oli saanut rakennetuksi Herran temppelin ja kuninkaan linnan ja kaiken, mitä Salomo oli halunnut tehdä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'Herra ilmestyi Salomolle toisen kerran,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'niin kuin hän oli ilmestynyt hänelle Gibeonissa. Herra sanoi hänelle: \"Olen kuullut rukouksesi ja anomisesi, kun anoit armoa edessäni. Olen pyhittänyt tämän temppelin, jonka olet rakentanut sitä varten, että sijoittaisin nimeni siihen ainiaaksi. Silmäni ja sydämeni tulevat olemaan alati siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Jos vaellat edessäni, niin kuin isäsi Daavid vaelsi, eheällä sydämellä ja oikeamielisesti, niin että teet kaiken, mitä olen käskenyt sinun tehdä, ja noudatat käskyjäni ja oikeuksiani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'niin pidän pystyssä kuninkaallisen valtaistuimesi Israelissa ikuisesti, niin kuin puhuin isällesi Daavidille sanoen: \'Aina on mies suvustasi oleva Israelin valtaistuimella.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Mutta jos te käännytte minusta pois, te ja teidän lapsenne, ettekä noudata käskyjäni ja säädöksiäni, jotka olen teille antanut, vaan menette ja palvelette muita jumalia ja kumarratte niitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'niin hävitän Israelin siitä maasta, jonka olen antanut heille, ja heitän pois kasvojeni edestä temppelin, jonka olen pyhittänyt nimelleni, ja Israel tulee sananparreksi ja ivapuheeksi kaikille kansoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Vaikka tämä temppeli on kaikkein korkein, kuitenkin jokainen, joka kulkee siitä ohi, on tyrmistyvä ja viheltävä, ja kun kysytään: \'Miksi on Herra tehnyt näin tälle maalle ja tälle temppelille?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'niin vastataan: \'Siksi, että he hylkäsivät Herran, Jumalansa, joka oli vienyt heidän isänsä pois Egyptin maasta, ja liittyivät muihin jumaliin ja kumarsivat niitä ja palvelivat niitä. Sen tähden Herra on antanut kaiken tämän pahan kohdata heitä.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Kun ne kaksikymmentä vuotta olivat loppuun kuluneet, joiden kuluessa Salomo oli rakentanut nuo kaksi rakennusta, Herran temppelin ja kuninkaan linnan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'Hiiramin, Tyyron kuninkaan, avustaessa Salomoa setripuilla, sypressipuilla ja kullalla, niin paljolla kuin tämä halusi, silloin kuningas Salomo antoi Hiiramille kaksikymmentä kaupunkia Galilean maakunnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Hiiram lähti Tyyrosta katsomaan kaupunkeja, jotka Salomo oli antanut hänelle, mutta ne eivät miellyttäneet häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Hän sanoi: \"Mitä kaupunkeja nämä ovat, jotka olet antanut minulle, veljeni!\" Niitä kutsutaan Kaabulin maaksi vielä tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Mutta Hiiram lähetti kuninkaalle sata kaksikymmentä talenttia kultaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Näin on sen työveron laita, jota kuningas Salomo otti rakentaakseen Herran temppeliä, omaa linnaansa, Milloa ja Jerusalemin muuria sekä Haasoria, Megiddoa ja Geseriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Farao, Egyptin kuningas, oli näet tullut ja valloittanut Geserin, polttanut sen tulella ja surmannut kanaanilaiset, jotka asuivat kaupungissa, ja antanut sen myötäjäisiksi tyttärelleen, Salomon puolisolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Salomo linnoitti Geserin, alemman Beet-Hooronin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Baalatin ja Taamarin sen maan erämaassa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'ja kaikki varastokaupungit, jotka hänellä oli, ja kaikki vaunukaupungit ja ratsumiesten kaupungit ja mitä muuta Salomo oli tahtonut linnoittaa Jerusalemissa ja Libanonilla ja koko hallitsemassaan maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Kaiken kansan, mitä oli jäänyt jäljelle amorilaisista, heettiläisistä, perissiläisistä, hivviläisistä ja jebusilaisista, kaikki, jotka eivät olleet israelilaisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'ne niiden jälkeläiset, jotka vielä olivat jäljellä maassa ja joita israelilaiset eivät olleet kyenneet vihkimään tuhon omiksi, ne Salomo saattoi työveron alaisiksi aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Mutta israelilaisista Salomo ei tehnyt ketään orjaksi, vaan heitä oli sotilaina, hänen palvelijoinaan, päällikköinään, vaunusotureinaan ja hänen sotavaunujensa ja ratsumiestensä päälliköinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Maaherrojen virkamiehiä, jotka valvoivat Salomon töitä, oli viisisataa viisikymmentä miestä, vallitsemassa väkeä, joka teki työtä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Heti kun faraon tytär oli muuttanut Daavidin kaupungista omaan linnaansa, jonka Salomo oli hänelle rakentanut, tämä rakensi Millon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Salomo uhrasi kolme kertaa vuodessa polttouhreja ja rauhanuhreja alttarilla, jonka hän oli rakentanut Herralle, ja suitsutti alttarin ääressä, joka oli Herran edessä. Hän oli saanut temppelin valmiiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Kuningas Salomo rakensi myös laivaston Esjon-Geberissä, joka on lähellä Eilatia Kaislameren rannalla Edomin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Tähän laivastoon Hiiram lähetti palvelijoitaan, meritaitoisia laivamiehiä Salomon palvelijoiden mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'He menivät Oofiriin ja noutivat sieltä kultaa neljäsataa kaksikymmentä talenttia ja toivat sen kuningas Salomolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Kun Saban kuningatar kuuli, mitä Salomosta kerrottiin Herran nimen kunniaksi, hän tuli koettelemaan häntä arvoituksilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Hän tuli Jerusalemiin sangen suuren seurueen kanssa mukanaan kameleja, jotka kantoivat hajuaineita, kultaa hyvin paljon ja kalliita kiviä. Kun hän tuli Salomon luo, hän puhui tälle kaikki, mitä hänellä oli sydämellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Mutta Salomo selitti hänelle kaikki hänen kysymyksensä. Kuninkaalle ei jäänyt mikään ongelmaksi, jota hän ei olisi hänelle selittänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Kun Saban kuningatar näki kaiken Salomon viisauden, linnan, jonka hän oli rakentanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'ruuat hänen pöydällään, kuinka hänen palvelijansa asuivat ja hänen palvelusväkensä palveli ja kuinka he olivat puetut, ja näki hänen juomanlaskijansa ja hänen polttouhrinsa, jotka hän uhrasi Herran temppelissä, hän meni melkein hengettömäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Sitten hän sanoi kuninkaalle: \"Totta oli puhe, jonka olin kuullut kotimaahani sinusta ja viisaudestasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'En uskonut, mitä sanottiin, ennen kuin itse tulin ja sain omin silmin nähdä, ja katso, puoltakaan ei ollut minulle kerrottu. Sinulla on paljon enemmän viisautta ja rikkautta, kuin olin kuullut huhuttavan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Onnellisia ovat miehesi, onnellisia nämä palvelijasi, jotka aina saavat olla edessäsi ja kuulla viisauttasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Kiitetty olkoon Herra, Jumalasi, joka on sinuun niin mieltynyt, että on asettanut sinut Israelin valtaistuimelle. Sen tähden, että Herra rakastaa Israelia ainiaan, hän on pannut sinut kuninkaaksi tekemään sitä, mikä on oikeus ja vanhurskaus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Hän antoi kuninkaalle sata kaksikymmentä talenttia kultaa, hyvin paljon hajuaineita ja kalliita kiviä. Niin suurta määrää hajuaineita, kuin mitä Saban kuningatar antoi kuningas Salomolle, ei ole sinne sen jälkeen tullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Myös Hiiramin laivat, jotka kuljettivat kultaa Oofirista, toivat Oofirista hyvin paljon santelipuuta ja kalliita kiviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Kuningas teetti santelipuusta kalustoa Herran temppeliin ja kuninkaan linnaan sekä lyyroja ja harppuja laulajille. Sellaista santelipuumäärää ei ole tuotu eikä nähty tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Kuningas Salomo taas antoi Saban kuningattarelle kaiken, mitä tämä halusi ja pyysi, ja sen lisäksi hän antoi muutakin kuninkaallisella anteliaisuudella. Tämä lähti ja meni palvelijoineen omaan maahansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Kullan paino, mikä yhtenä vuotena tuli Salomolle, oli kuusisataa kuusikymmentä kuusi talenttia kultaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'paitsi mitä tuli kauppamiehiltä ja kaupustelijoiden kaupanteosta ja kaikilta Arabian kuninkailta ja maan käskynhaltijoilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Kuningas Salomo teetti pakotetusta kullasta kaksisataa suurta kilpeä ja käytti jokaiseen kilpeen kuusisataa sekeliä kultaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'ja pakotetusta kullasta kolmesataa pienempää kilpeä. Hän käytti jokaiseen kilpeen kolme miinaa kultaa. Kuningas asetti ne Libanonin metsän puista rakennettuun taloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Kuningas teetti suuren norsunluisen valtaistuimen ja päällysti sen puhdistetulla kullalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Valtaistuimessa oli kuusi porrasta, ja valtaistuimen selusta oli ylhäältä kaareva. Istuimen kummallakin puolella oli käsinoja, ja kaksi leijonaa seisoi käsinojien vieressä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Kaksitoista leijonaa seisoi siinä kuudella portaalla, kummallakin puolella. Sellaista ei ole tehty missään muussa valtakunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Kaikki kuningas Salomon juoma-astiat olivat kultaa. Myös kaikki Libanonin metsän puista rakennetun talon astiat olivat puhdasta kultaa. Hopeaa ei siellä ollut, eikä sitä Salomon päivinä pidetty minkään arvoisena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Kuninkaalla oli Tarsiin laivasto merellä Hiiramin laivaston kanssa. Kerran kolmessa vuodessa Tarsiin laivasto tuli ja toi kultaa ja hopeaa, norsunluuta, apinoita ja riikinkukkoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Kuningas Salomo oli kaikkia maan kuninkaita suurempi rikkaudessa ja viisaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Koko maa pyrki näkemään Salomon kuullakseen hänen viisauttaan, jonka Jumala oli antanut hänen sydämeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'He toivat kukin lahjansa: hopea- ja kultaesineitä, vaatteita, aseita, hajuaineita, hevosia ja muuleja joka vuosi vuoden tarpeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Salomo kokosi sotavaunuja ja ratsumiehiä, niin että hänellä oli tuhat neljäsataa sotavaunua ja kaksitoista tuhatta ratsumiestä. Ne hän sijoitti vaunukaupunkeihin ja Jerusalemiin kuninkaan luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Kuningas toimitti niin, että Jerusalemissa oli hopeaa kuin kiviä, ja setripuuta niin paljon kuin metsäviikunapuita Alankomaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Hevoset, joita Salomolla oli, tuotiin Egyptistä ja Kuvesta. Kuninkaan kauppiaat noutivat niitä Kuvesta maksua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Egyptistä tuodut vaunut maksoivat kuusisataa hopeasekeliä ja hevonen sata viisikymmentä. Samoin tuotiin niitä heidän välityksellään kaikille heettiläisten ja aramilaisten kuninkaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Kuningas Salomolla oli faraon tyttären lisäksi monta muuta muukalaista vaimoa, joita hän rakasti: mooabilaisia, ammonilaisia, edomilaisia, siidonilaisia ja heettiläisiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'niiden kansojen naisia, joista Herra oli sanonut israelilaisille: \"Älkää yhtykö heihin, älköötkä hekään yhtykö teihin. He varmasti taivuttavat sydämenne seuraamaan heidän jumaliaan.\" Näihin Salomo kiintyi rakkaudella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Hänellä oli seitsemänsataa ruhtinaallista puolisoa ja kolmesataa sivuvaimoa, ja hänen vaimonsa taivuttivat hänen sydämensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Kun Salomo vanheni, hänen vaimonsa taivuttivat hänen sydämensä seuraamaan muita jumalia, niin ettei hänen sydämensä ollut eheä Herraa, hänen Jumalaansa kohtaan, kuten hänen isänsä Daavidin sydän oli ollut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Salomo lähti seuraamaan Astartea, siidonilaisten jumalatarta, ja Milkomia, ammonilaisten iljetystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Salomo teki sitä, mikä on pahaa Herran silmissä, eikä uskollisesti seurannut Herraa kuten hänen isänsä Daavid.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Salomo rakensi Kemokselle, mooabilaisten iljetykselle, uhrikukkulan sille vuorelle, joka on itään Jerusalemista, ja samoin Moolokille, ammonilaisten iljetykselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Näin hän teki kaikkien muukalaisten vaimojensa mieliksi, jotka suitsuttivat ja uhrasivat jumalilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Herra vihastui Salomoon, koska hänen sydämensä oli kääntynyt pois Herrasta, Israelin Jumalasta, joka kahdesti oli ilmestynyt hänelle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'ja nimenomaan kieltänyt häntä seuraamasta muita jumalia, ja koska hän ei ollut noudattanut Herran kieltoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Sen tähden Herra sanoi Salomolle: \"Koska sinun on käynyt näin, ja koska et ole pitänyt liittoani etkä noudattanut käskyjäni, jotka sinulle annoin, minä repäisen valtakunnan sinulta ja annan sen palvelijallesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Mutta isäsi Daavidin tähden minä en tee sitä sinun päivinäsi. Poikasi kädestä minä sen repäisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Kuitenkaan minä en repäise koko valtakuntaa: yhden sukukunnan annan pojallesi palvelijani Daavidin tähden ja Jerusalemin tähden, jonka olen valinnut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Herra nostatti Salomolle vastustajaksi edomilaisen Hadadin. Tämä oli edomilaista kuningassukua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Kun Daavid oli ollut sodassa Edomin kanssa ja sotapäällikkö Jooab oli mennyt hautaamaan kaatuneita ja surmannut kaikki miehenpuolet Edomissa –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, 'sillä Jooab ja koko Israel viipyi siellä kuusi kuukautta, kunnes he olivat hävittäneet kaikki miehenpuolet Edomista –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Hadad ja hänen kanssaan muutamat edomilaiset miehet, hänen isänsä palvelijat, olivat paenneet Egyptiin päin. Silloin Hadad oli ollut vielä pieni poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'He olivat lähteneet liikkeelle Midianista ja tulleet Paaraniin. He olivat ottaneet mukaansa miehiä Paaranista ja tulleet Egyptiin faraon, Egyptin kuninkaan, luo. Tämä oli antanut hänelle talon ja määrännyt hänelle elatuksen ja antanut hänelle myös maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Hadad oli päässyt faraon suureen suosioon, niin että hän antoi hänelle vaimoksi kälynsä, kuningatar Tahpeneen sisaren.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Tahpeneen sisar synnytti hänelle hänen poikansa Genubatin, ja Tahpenes vieroitti hänet faraon palatsissa. Niin Genubat jäi faraon palatsiin faraon lasten joukkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Kun Hadad kuuli Egyptissä, että Daavid oli mennyt lepoon isiensä luo ja että sotapäällikkö Jooab oli kuollut, Hadad sanoi faraolle: \"Päästä minut menemään omaan maahani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Mutta farao sanoi hänelle: \"Mitä sinulta puuttuu luonani, koska haluat mennä omaan maahasi?\" Hän vastasi: \"Ei mitään, mutta päästä minut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Jumala nostatti Salomolle vastustajaksi Resonin, Eljadan pojan, joka oli paennut herransa Hadadeserin, Sooban kuninkaan, luota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Tämä kokosi miehiä ympärilleen ja oli ollut partiojoukon päällikkönä silloin, kun Daavid surmasi heitä. He olivat menneet sitten Damaskoon, asettuneet sinne ja hallitsivat Damaskossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Hän oli Israelin vastustaja, niin kauan kuin Salomo eli, ja teki sille pahaa samoin kuin Hadadkin. Hän inhosi Israelia, ja hänestä tuli Aramin kuningas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Salomon palvelija Jerobeam, Nebatin poika, efraimilainen Seredasta, jonka äiti oli nimeltään Serua ja oli leskivaimo, kohotti kätensä kuningasta vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Hän joutui kohottamaan kätensä kuningasta vastaan seuraavalla tavalla. Salomo rakensi Milloa ja sulki siten aukon isänsä Daavidin kaupungissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Jerobeam oli kelpo mies. Kun Salomo näki, kuinka tämä nuori mies teki työtä, hän asetti hänet kaiken sen pakkotyön valvojaksi, mikä oli Joosefin heimon osalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Siihen aikaan tapahtui, kun Jerobeam kerran oli lähtenyt Jerusalemista, että siilolainen Ahia, profeetta, kohtasi hänet tiellä. Tämä oli puettuna uuteen viittaan, ja he olivat kahden kesken kedolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Ahia tarttui uuteen viittaan, joka hänellä oli yllään, ja repäisi sen kahdeksitoista kappaleeksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'ja sanoi Jerobeamille: \"Ota itsellesi kymmenen kappaletta, sillä näin sanoo Herra, Israelin Jumala: Katso, minä repäisen valtakunnan Salomon kädestä ja annan kymmenen sukukuntaa sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'Yksi sukukunta jääköön hänelle palvelijani Daavidin tähden ja Jerusalemin kaupungin tähden, jonka olen valinnut kaikista Israelin sukukunnista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'Näin on tapahtuva, koska he ovat hylänneet minut ja kumartaneet Astartea, siidonilaisten jumalatarta, ja Kemosta, Mooabin jumalaa, ja Milkomia, ammonilaisten jumalaa, eivätkä ole vaeltaneet teitäni eivätkä tehneet sitä, mikä on oikein silmissäni, eivätkä noudattaneet käskyjäni ja oikeuksiani niin kuin Salomon isä Daavid.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Kuitenkaan en ota hänen kädestään koko valtakuntaa, vaan annan hänen olla ruhtinaana koko elinaikansa palvelijani Daavidin tähden, jonka valitsin, koska hän noudatti käskyjäni ja säädöksiäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Mutta hänen poikansa kädestä otan kuninkuuden ja annan sen sinulle, nimittäin ne kymmenen sukukuntaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'ja hänen pojalleen annan yhden sukukunnan, että palvelijallani Daavidilla olisi aina lamppu palamassa edessäni Jerusalemissa, siinä kaupungissa, jonka olen itselleni valinnut asettaakseni nimeni siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Mutta sinut otan, ja tulet hallitsemaan kaikkia, joita haluat. Sinusta tulee Israelin kuningas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Jos olet kuuliainen kaikessa, mitä käsken sinun tehdä, ja vaellat tietäni ja teet sitä, mikä on oikein silmissäni, ja noudatat säädöksiäni ja käskyjäni, niin kuin palvelijani Daavid teki, niin olen kanssasi ja rakennan sinulle pysyvän huoneen, niin kuin rakensin Daavidille, ja annan sinulle Israelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Nöyryytän Daavidin jälkeläiset, en kuitenkaan ainiaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Salomo yritti saada surmatuksi Jerobeamin, mutta Jerobeam lähti ja pakeni Egyptiin, Suusakin, Egyptin kuninkaan, luo. Hän oli Egyptissä Salomon kuolemaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Mitä muuta Salomosta on kerrottavaa, kaikesta, mitä hän teki, ja hänen viisaudestaan, se on kirjoitettuna Salomon historiassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Aika, minkä Salomo hallitsi Jerusalemissa koko Israelia, oli neljäkymmentä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Salomo meni lepoon isiensä luo ja hänet haudattiin isänsä Daavidin kaupunkiin. Hänen poikansa Rehabeam tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Rehabeam meni Sikemiin, sillä koko Israel oli tullut Sikemiin tekemään hänet kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Kun Jerobeam, Nebatin poika, sen kuuli – hän oli vielä Egyptissä, jonne hän oli paennut kuningas Salomoa, ja Jerobeam asui Egyptissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'mutta he lähettivät kutsumaan hänet – niin Jerobeam ja koko Israelin seurakunta tuli saapuville, ja he puhuivat Rehabeamille sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, '\"Isäsi teki ikeemme raskaaksi, mutta huojenna sinä nyt se kova työ, jota isäsi teetti, ja se raskas ies, jonka hän pani niskaamme, niin palvelemme sinua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Hän vastasi heille: \"Menkää ja odottakaa kolme päivää ja tulkaa sitten takaisin luokseni.\" Niin kansa meni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Kuningas Rehabeam neuvotteli vanhojen kanssa, jotka olivat palvelleet hänen isäänsä Salomoa, kun tämä vielä eli, ja kysyi: \"Kuinka te neuvotte vastaamaan tälle kansalle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'He vastasivat hänelle ja sanoivat: \"Jos tänä päivänä rupeat tämän kansan palvelijaksi ja palvelet heitä, jos kuulet heitä ja puhut heille hyviä sanoja, he ovat palvelijoitasi koko elinaikasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Mutta hän hylkäsi tämän neuvon, jonka vanhat hänelle antoivat, ja neuvotteli nuorten miesten kanssa, jotka olivat kasvaneet hänen kanssaan ja jotka palvelivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Hän kysyi heiltä: \"Kuinka te neuvotte meitä vastaamaan tälle kansalle, joka on puhunut minulle sanoen: \'Huojenna ies, jonka isäsi on pannut niskaamme\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Nuoret miehet, jotka olivat kasvaneet hänen kanssaan, vastasivat hänelle sanoen: \"Sano näin tälle kansalle, joka on puhunut sinulle sanoen: \'Isäsi teki ikeemme raskaaksi, mutta huojenna sinä sitä meiltä\' – puhu heille näin: \'Pikkusormeni on paksumpi kuin isäni lantio.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Jos siis isäni on sälyttänyt selkäänne raskaan ikeen, niin minä teen ikeenne vielä raskaammaksi. Jos isäni on kurittanut teitä raipoilla, minä kuritan teitä piikkiruoskilla.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Jerobeam ja kaikki kansa tuli Rehabeamin luo kolmantena päivänä, niin kuin kuningas oli käskenyt sanoen: \"Tulkaa takaisin luokseni kolmantena päivänä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Kuningas antoi kansalle kovan vastauksen hyläten sen neuvon, jonka vanhat olivat hänelle antaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'Hän puhui heille nuorten miesten neuvon mukaan sanoen: \"Jos isäni on tehnyt ikeenne raskaaksi, minä teen ikeenne vielä raskaammaksi. Jos isäni on kurittanut teitä raipoilla, minä kuritan teitä piikkiruoskilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Kuningas ei siis kuullut kansaa. Sillä Herra salli sen niin täyttääkseen sanansa, jonka Herra oli puhunut Jerobeamille, Nebatin pojalle, siilolaisen Ahian kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Kun koko Israel huomasi, ettei kuningas heitä kuullut, kansa vastasi kuninkaalle näin: \"Mitä osaa meillä on Daavidiin? Ei meillä ole perintöosaa Iisain poikaan. Teltoillesi, Israel! Valvo nyt huonettasi, Daavid!\" Israel meni teltoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Niin Rehabeam tuli ainoastaan niiden israelilaisten kuninkaaksi, jotka asuivat Juudan kaupungeissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Kun kuningas Rehabeam lähetti matkaan verotöiden valvojan Adoramin, koko Israel kivitti tämän kuoliaaksi. Silloin kuningas Rehabeam nousi nopeasti vaunuihinsa ja pakeni Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Israel luopui Daavidin suvusta aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Kun koko Israel kuuli, että Jerobeam oli tullut takaisin, he lähettivät kutsumaan hänet kansankokoukseen ja tekivät hänet koko Israelin kuninkaaksi. Daavidin sukua ei seurannut kukaan muu kuin yksin Juudan sukukunta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Kun Rehabeam tuli Jerusalemiin, hän kokosi koko Juudan heimon ja Benjaminin sukukunnan, satakahdeksankymmentä tuhatta sotakuntoista valiomiestä, sotimaan Israelin heimoa vastaan ja palauttamaan kuninkuutta Rehabeamille, Salomon pojalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Mutta Jumalan miehelle Semajalle tuli tämä Jumalan sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, '\"Sano Rehabeamille, Salomon pojalle, Juudan kuninkaalle, ja koko Juudan ja Benjaminin heimoille sekä muulle kansalle näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, '\'Näin sanoo Herra: Älkää menkö sotimaan veljiänne, israelilaisia, vastaan. Palatkaa kukin kotiinne, sillä minä olen sallinut tämän tapahtua.\'\" He kuulivat Herran sanaa, kääntyivät takaisin ja menivät pois Herran sanan mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Mutta Jerobeam linnoitti Sikemin Efraimin vuoristossa ja asettui sinne. Sitten hän lähti sieltä ja linnoitti Penuelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Jerobeam ajatteli sydämessään: \"Nyt valtakunta joutuu takaisin Daavidin suvulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Jos tämä kansa menee ja uhraa teurasuhreja Herran temppelissä Jerusalemissa, tämän kansan sydän kääntyy jälleen heidän herransa Rehabeamin, Juudan kuninkaan, puolelle, ja he tappavat minut ja palaavat takaisin Rehabeamin, Juudan kuninkaan, luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Mietittyään asiaa kuningas teetti kaksi kultaista vasikkaa ja sanoi heille: \"Te olette jo tarpeeksi kauan kulkeneet Jerusalemissa. Katso, Israel, tässä on Jumalasi, joka on johdattanut sinut Egyptin maasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Hän pystytti toisen Beeteliin, ja toisen hän asetti Daaniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Tämä koitui synniksi. Kansa kulki toisen kuvan luo Daaniin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Hän rakensi myös uhrikukkulatemppeleitä ja teki kansan keskuudesta papeiksi kaikenlaisia miehiä, jotka eivät olleet leeviläisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Jerobeam järjesti juhlan kahdeksannessa kuussa, kuukauden viidentenätoista päivänä, sen juhlan kaltaisen, jota vietetään Juudassa, ja nousi silloin itse alttarille. Niin hän teki Beetelissä ja uhrasi niille vasikoille, jotka hän oli teettänyt. Tekemiään uhrikukkulapappeja hän asetti virkaan Beeteliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Hän nousi sille alttarille, jonka oli teettänyt Beeteliin, viidentenätoista päivänä kahdeksatta kuuta, jonka kuukauden hän oli omasta päästään keksinyt. Hän laittoi silloin juhlan israelilaisille ja nousi alttarille polttamaan uhreja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Katso, Juudasta Beeteliin tuli Herran käskystä Jumalan mies, juuri kun Jerobeam seisoi alttarin vierellä polttamassa uhreja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Hän huusi alttaria kohti Herran käskystä ja sanoi: \"Alttari, alttari, näin sanoo Herra: Katso, Daavidin suvusta on syntyvä poika, nimeltä Joosia. Hän on teurastava päälläsi uhrikukkulapapit, jotka polttavat uhreja päälläsi, ja päälläsi tullaan polttamaan ihmisten luita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Hän antoi sinä päivänä ennusmerkin, sanoen: \"Ennusmerkki siitä, että Herra on puhunut, on tämä: alttari halkeaa, ja tuhka, joka on sen päällä, hajoaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Kun kuningas Jerobeam kuuli Jumalan miehen sanan, jonka hän huusi alttaria kohti Beetelissä, hän ojensi kätensä alttarilta ja sanoi: \"Ottakaa hänet kiinni.\" Hänen kätensä, jonka hän oli ojentanut häntä vastaan, kuivettui, eikä hän enää voinut vetää sitä takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Alttari halkesi ja tuhka hajosi alttarilta, niin kuin Jumalan mies Herran käskystä oli antanut ennusmerkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Silloin kuningas puhkesi puhumaan ja sanoi Jumalan miehelle: \"Lepytä Herraa, Jumalaasi, ja rukoile puolestani, että voisin vetää käteni takaisin.\" Silloin Jumalan mies lepytti Herran, niin että kuningas saattoi vetää kätensä takaisin, ja se tuli entiselleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Kuningas puhui Jumalan miehelle: \"Tule kotiini kanssani virkistämään itseäsi, niin annan sinulle lahjan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Mutta Jumalan mies sanoi kuninkaalle: \"Vaikka antaisit minulle puolet linnastasi, en tulisi kanssasi. Tässä paikassa en syö leipää enkä juo vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Sillä niin käski minua Herra sanallaan sanoen: Älä syö leipää, älä juo vettä äläkä palaa samaa tietä, jota olet tullut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Sitten hän meni toista tietä eikä palannut samaa tietä, jota oli tullut Beeteliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Mutta Beetelissä asui vanha profeetta, ja hänen poikansa tuli ja kertoi hänelle kaiken, mitä Jumalan mies sinä päivänä oli tehnyt Beetelissä ja mitä hän oli puhunut kuninkaalle. Kun he olivat kertoneet sen isälleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'heidän isänsä kysyi heiltä, mitä tietä hän oli mennyt. Hänen poikansa olivat nähneet, mitä tietä Juudasta tullut Jumalan mies oli lähtenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Hän sanoi pojilleen: \"Satuloikaa minulle aasi.\" Kun he olivat satuloineet hänelle aasin, hän istui sen selkään');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'ja lähti Jumalan miehen perään ja tapasi hänet istumassa tammen alla. Hän kysyi häneltä: \"Sinäkö olet se Juudasta tullut Jumalan mies?\" Hän vastasi: \"Minä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Hän sanoi hänelle: \"Tule kanssani kotiini syömään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Hän vastasi: \"En voi palata enkä tulla kanssasi, en voi syödä leipää enkä juoda vettä kanssasi tässä paikassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'sillä minulle on tullut sana, Herran sana: \'Älä syö leipää äläkä juo vettä siellä, älä myöskään tule takaisin samaa tietä, jota olet mennyt.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Hän sanoi hänelle: \"Minäkin olen profeetta niin kuin sinä, ja enkeli on puhunut minulle Herran käskystä, sanoen: \'Vie hänet kanssasi takaisin kotiisi syömään leipää ja juomaan vettä.\'\" Mutta sen hän valehteli hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Niin tämä palasi hänen kanssaan ja söi leipää ja joi vettä hänen kodissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Mutta heidän istuessaan pöydässä tuli Herran sana profeetalle, joka oli tuonut hänet takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'Hän huusi Juudasta tulleelle Jumalan miehelle, sanoen: \"Näin sanoo Herra: Koska sinä olet niskoitellut Herran käskyä vastaan etkä ole noudattanut sitä määräystä, jonka Herra, Jumalasi, sinulle antoi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'vaan olet palannut syömään leipää ja juomaan vettä siinä paikassa, josta sinulle oli sanottu: \'Älä siellä syö leipää äläkä juo vettä\', niin älköön ruumiisi tulko isiesi hautaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Kun hän oli syönyt leipää ja juonut, hän satuloi aasin profeetalle, jonka hän oli tuonut takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Kun tämä oli lähtenyt, hänet kohtasi leijona tiellä ja tappoi hänet. Hänen ruumiinsa oli pitkin pituuttaan tiellä, ja aasi seisoi hänen vieressään, ja leijona seisoi ruumiin luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Katso, siitä kulki ohi miehiä, ja he näkivät ruumiin heitettynä tielle ja leijonan seisomassa ruumiin vieressä. He menivät ja puhuivat siitä kaupungissa, jossa vanha profeetta asui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Kun profeetta, joka oli palauttanut hänet tieltä, sen kuuli, hän sanoi: \"Se on se Jumalan mies, joka niskoitteli Herran käskyä vastaan. Sen tähden Herra on antanut hänet leijonalle, ja se on ruhjonut ja tappanut hänet sen Herran sanan mukaan, jonka hän oli hänelle puhunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Hän puhui pojilleen sanoen: \"Satuloikaa minulle aasi.\" Niin he satuloivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Hän lähti ja löysi hänen ruumiinsa, joka oli heitetty tielle, ja aasin ja leijonan seisomasta ruumiin luona. Leijona ei ollut syönyt ruumista eikä myöskään ruhjonut aasia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Profeetta otti Jumalan miehen ruumiin, pani sen aasin selkään ja vei sen takaisin, ja vanha profeetta tuli kaupunkiin pitämään valittajaisia ja hautaamaan häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Hän pani ruumiin omaan hautaansa, ja he pitivät valittajaiset hänelle ja huusivat: \"Voi, veljeni!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Kun hän oli haudannut hänet, hän sanoi pojilleen näin: \"Kun minä kuolen, haudatkaa minut siihen hautaan, johon Jumalan mies on haudattu, ja pankaa minun luuni hänen luittensa viereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Sillä toteutuva on sana, jonka hän Herran käskystä huusi Beetelissä olevaa alttaria vastaan ja kaikkia Samarian kaupungeissa olevia uhrikukkulatemppeleitä vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Tämänkään jälkeen Jerobeam ei kääntynyt pahalta tieltään, vaan teki taas uhrikukkulapapeiksi kaikenlaisia miehiä kansan keskuudesta. Kuka vain halusi, sen hän vihki papin virkaan, ja niin hänestä tuli uhrikukkulapappi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Tällä tavalla tämä tuli synniksi Jerobeamin suvulle ja syyksi siihen, että se hävitettiin ja hukutettiin maan päältä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Siihen aikaan sairastui Abia, Jerobeamin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Jerobeam sanoi vaimolleen: \"Nouse ja pukeudu niin, ettei sinua tunneta Jerobeamin vaimoksi, ja mene Siiloon. Katso, siellä on profeetta Ahia, joka ilmoitti, että minusta on tuleva tämän kansan kuningas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Ota mukaasi kymmenen leipää sekä pieniä leivoksia ja ruukullinen hunajaa ja mene hänen luokseen. Hän ilmaisee sinulle, kuinka pojan käy.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Jerobeamin vaimo teki niin: hän nousi ja meni Siiloon ja tuli Ahian taloon. Mutta Ahia ei voinut nähdä, sillä hänellä oli vanhuuttaan kaihi silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Mutta Herra oli sanonut Ahialle: \"Katso, Jerobeamin vaimo tulee kysymään sinulta pojastaan, sillä hän on sairaana. Niin ja niin on sinun puhuttava hänelle.\" Kun hän tuli tekeytyen tuntemattomaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'ja kun Ahia kuuli hänen askeleensa hänen tullessaan ovesta, hän sanoi: \"Tule sisään, Jerobeamin vaimo. Miksi tekeydyt tuntemattomaksi? Minä olen saanut kovan sanoman ilmoittaakseni sen sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Mene ja sano Jerobeamille: \'Näin sanoo Herra, Israelin Jumala: Korotin sinut kansan seasta ja asetin sinut kansani Israelin ruhtinaaksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'ja repäisin valtakunnan Daavidin suvulta ja annoin sen sinulle. Mutta et ole ollut kuin palvelijani Daavid, joka noudatti käskyjäni ja seurasi minua kaikesta sydämestään, niin että hän teki ainoastaan sitä, mikä oli oikeaa silmissäni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'vaan sinä olet tehnyt enemmän pahaa kuin kaikki edeltäjäsi. Sinä olet mennyt ja tehnyt itsellesi muita jumalia, valettuja kuvia, ja olet vihoittanut minut ja heittänyt minut selkäsi taa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Katso, sen tähden minä annan onnettomuuden kohdata Jerobeamin sukua ja hävitän Israelista Jerobeamin miespuoliset jälkeläiset, kaikki tyynni, ja lakaisen pois Jerobeamin suvun, niin kuin saasta lakaistaan, kunnes siitä on tullut loppu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Joka Jerobeamin jälkeläisistä kuolee kaupungissa, sen koirat syövät, ja joka kuolee kedolle, sen syövät taivaan linnut. Sillä Herra on puhunut.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Nouse nyt ja mene kotiisi. Kun jalkasi astuu kaupunkiin, kuolee lapsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Koko Israel on pitävä valittajaiset hänelle, ja hänet haudataan. Sillä Jerobeamin jälkeläisistä hän yksin on tuleva hautaan, koska Jerobeamin suvussa on vain hänessä havaittu jotakin Herralle, Israelin Jumalalle, otollista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Mutta Herra on herättävä itselleen Israeliin kuninkaan, joka hävittää Jerobeamin suvun. Se on se päivä, – ja mitä sitten?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Herra on lyövä Israelia, niin että se tulee ruo\'on kaltaiseksi, joka häilyy vedessä. Hän kiskaisee Israelin irti tästä hyvästä maasta, jonka hän on antanut heidän isilleen, ja hajottaa heidät tuolle puolelle Eufrat-virran, koska he ovat tehneet itselleen aserapaaluja ja siten vihoittaneet Herran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Hän antaa alttiiksi Israelin niiden syntien tähden, jotka Jerobeam on tehnyt ja joilla hän on saattanut Israelin tekemään syntiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Jerobeamin vaimo nousi, lähti matkaansa ja tuli Tirsaan. Juuri kun hän tuli talon kynnykselle, kuoli poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Hänet haudattiin, ja koko Israel piti valittajaiset hänelle, sen sanan mukaan, jonka Herra oli puhunut palvelijansa, profeetta Ahian, kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Mitä muuta on kerrottavaa Jerobeamista, kuinka hän soti ja kuinka hän hallitsi, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Aika, minkä Jerobeam hallitsi, oli kaksikymmentä kaksi vuotta. Sitten hän meni lepoon isiensä luo. Hänen poikansa Naadab tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Mutta Rehabeam, Salomon poika, tuli Juudan kuninkaaksi. Rehabeam oli neljäkymmentä yksi vuotta vanha tullessaan kuninkaaksi, ja hän hallitsi seitsemäntoista vuotta Jerusalemissa, siinä kaupungissa, jonka Herra oli valinnut kaikista Israelin sukukunnista asettaakseen siihen nimensä. Hänen äitinsä oli nimeltään Naema, ammonilainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Juuda teki sitä, mikä oli pahaa Herran silmissä. Synneillään, joita he tekivät, he vihoittivat Herraa paljon enemmän, kuin heidän isänsä olivat tehneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Hekin tekivät itselleen uhrikukkuloita, patsaita ja aserapaaluja kaikille korkeille kukkuloille ja jokaisen vihreän puun alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Maassa oli myös mieshuoria. He jäljittelivät niiden kansojen kaikkia kauhistavia tekoja, jotka Herra oli karkottanut israelilaisten tieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Mutta kuningas Rehabeamin viidentenä hallitusvuotena hyökkäsi Suusak, Egyptin kuningas, Jerusalemin kimppuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Hän otti Herran temppelin aarteet ja kuninkaan palatsin aarteet. Hän vei mukanaan ne kaikki tyynni. Hän otti myös kaikki kultakilvet, jotka Salomo oli teettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Kuningas Rehabeam teetti niiden sijaan vaskikilvet ja jätti ne henkivartijoiden päälliköiden haltuun, jotka vartioivat kuninkaan linnan ovella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Niin usein kuin kuningas meni Herran temppeliin, henkivartijat kantoivat niitä ja veivät ne sitten takaisin henkivartijoiden huoneeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Mitä muuta on kerrottavaa Rehabeamista ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Rehabeam ja Jerobeam olivat kaiken aikaa sodassa keskenään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Rehabeam meni lepoon isiensä luo, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Hänen äitinsä oli nimeltään Naema, ammonilainen. Hänen poikansa Abijam tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'Kuningas Jerobeamin, Nebatin pojan, kahdeksantenatoista hallitusvuotena tuli Abijam Juudan kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Hän hallitsi kolme vuotta Jerusalemissa. Hänen äitinsä oli nimeltään Maaka, Abisalomin tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Hän vaelsi kaikissa isänsä synneissä, joita tämä oli tehnyt ennen häntä, eikä hän ollut sydämeltään eheä Herraa, hänen Jumalaansa kohtaan, niin kuin hänen isänsä Daavidin sydän oli ollut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Mutta Daavidin tähden Herra, hänen Jumalansa, antoi hänelle lampun Jerusalemissa, ja salli hänen poikansa nousta hänen jälkeensä ja salli Jerusalemin pysyä pystyssä –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'koska Daavid oli tehnyt sitä, mikä on oikein Herran silmissä, eikä koko elinaikanaan ollut poikennut mistään, mitä hän oli käskenyt, paitsi heettiläisen Uurian asiassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Abijam oli koko elinaikansa sodassa Jerobeamin kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Mitä muuta kerrottavaa on Abijamista ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa. Mutta Abijam ja Jerobeam olivat sodassa keskenään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Abijam meni lepoon isiensä luo, ja hänet haudattiin Daavidin kaupunkiin. Aasa, hänen poikansa, tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Israelin kuninkaan Jerobeamin kahdentenakymmenentenä hallitusvuotena tuli Aasa Juudan kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Hän hallitsi neljäkymmentä yksi vuotta Jerusalemissa. Hänen äitinsä oli nimeltään Maaka, Abisalomin tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Aasa teki sitä, mikä oli oikein Herran silmissä, niin kuin hänen isänsä Daavid.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Hän toimitti pyhäkköhuorat pois maasta ja hävitti kaikki epäjumalat, jotka hänen isänsä olivat tehneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Hän jopa erotti äitinsä Maakan kuningattaren arvosta, koska tämä oli pystyttänyt inhotuksen Aseralle. Aasa kukisti inhotuksen ja poltti sen Kidronin laaksossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Mutta uhrikukkulat eivät hävinneet. Kuitenkin oli Aasan sydän eheä Herralle, niin kauan kuin hän eli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Hän vei Herran temppeliin isänsä pyhät lahjat ja omat pyhät lahjansa: hopeaa, kultaa ja esineistöä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Mutta Aasa ja Israelin kuningas Baesa olivat kaiken aikansa sodassa keskenään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Baesa, Israelin kuningas, lähti Juudaa vastaan ja linnoitti Raaman estääkseen ketään pääsemästä Aasan, Juudan kuninkaan, luota tai hänen luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Aasa otti kaiken hopean ja kullan, mikä vielä oli jäljellä Herran temppelin ja kuninkaan linnan aarrekammioissa, ja antoi sen palvelijoidensa haltuun. Kuningas Aasa lähetti heidät Benhadadin, Tabrimmonin pojan, Hesjonin pojanpojan, Aramin kuninkaan, luo, joka asui Damaskossa, ja käski sanoa hänelle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, '\"Onhan liitto meidän välillämme, minun ja sinun, niin kuin oli minun isäni ja sinun isäsi välillä. Katso, minä lähetän sinulle hopeaa ja kultaa lahjaksi. Mene ja riko Baesan, Israelin kuninkaan, kanssa tekemäsi liitto, että hän lähtisi pois kimpustani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Niin Benhadad kuuli kuningas Aasaa ja lähetti sotajoukkojensa päälliköt Israelin kaupunkeja vastaan ja valtasi Iijonin, Daanin, Aabel-Beet-Maakan ja koko Kinnerotin sekä koko Naftalin maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Kun Baesa kuuli sen, hän lakkasi linnoittamasta Raamaa ja jäi Tirsaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Kuningas Aasa kutsui kokoon koko Juudan vapauttamatta ketään. He veivät pois kivet ja puut, joilla Baesa oli linnoittanut Raamaa. Niillä kuningas Aasa linnoitti Geban, joka on Benjaminissa, ja Mispan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Mitä kaikkea muuta on kerrottavaa Aasasta, kaikista hänen urotöistään, kaikesta, mitä hän teki, ja kaupungeista, jotka hän rakensi, se on kirjoitettuna Juudan kuningasten aikakirjassa. Mutta vanhuutensa päivinä hän oli sairas jaloistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Sitten Aasa meni lepoon isiensä luo, ja hänet haudattiin isiensä viereen hänen isänsä Daavidin kaupunkiin. Hänen poikansa Joosafat tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Sitten Naadab, Jerobeamin poika, tuli Israelin kuninkaaksi Aasan, Juudan kuninkaan, toisena hallitusvuotena, ja hän hallitsi Israelia kaksi vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Hän teki sitä, mikä on pahaa Herran silmissä, ja vaelsi isänsä teitä ja hänen synnissään, jolla hän oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Mutta Baesa, Ahian poika, Isaskarin sukua, teki salaliiton häntä vastaan, ja Baesa surmasi hänet Gibbetonin luona, joka oli filistealaisilla, sillä Naadab ja koko Israel piirittivät Gibbetonia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Baesa tappoi hänet Juudan kuninkaan Aasan kolmantena hallitusvuotena ja tuli kuninkaaksi Naadabin jälkeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Kuninkaaksi tultuaan hän surmasi koko Jerobeamin suvun jättämättä Jerobeamin jälkeläisistä eloon ainoatakaan henkeä: hän hävitti heidät Herran sanan mukaan, jonka hän oli puhunut palvelijansa, siilolaisen Ahian, kautta –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'niiden syntien tähden, jotka Jerobeam oli tehnyt ja joilla hän oli saattanut Israelin tekemään syntiä, siten vihoittaen Herran, Israelin Jumalan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Mitä muuta on kerrottavaa Naadabista ja kaikesta, mitä hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Mutta Aasa ja Israelin kuningas Baesa olivat kaiken aikansa sodassa keskenään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Aasan, Juudan kuninkaan, kolmantena hallitusvuotena tuli Baesa, Ahian poika, koko Israelin kuninkaaksi Tirsassa, ja hän hallitsi kaksikymmentä neljä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Hän teki sitä, mikä on pahaa Herran silmissä, ja vaelsi Jerobeamin teitä ja hänen synneissään, joilla hän oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Jeehulle, Hananin pojalle, tuli tämä Herran sana Baesaa vastaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, '\"Sen tähden, että sinä, vaikka minä olen korottanut sinut tomusta ja pannut sinut kansani Israelin ruhtinaaksi, olet vaeltanut Jerobeamin teitä ja saattanut kansani Israelin tekemään syntiä, niin että he ovat vihoittaneet minut synneillään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'katso, minä lakaisen pois Baesan ja hänen sukunsa. Minä teen suvullesi, kuten tein Jerobeamin, Nebatin pojan, suvulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Joka Baesan jälkeläisistä kuolee kaupungissa, sen koirat syövät, ja joka kuolee kedolla, sen syövät taivaan linnut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Mitä muuta on kerrottavaa Baesasta, siitä, mitä hän teki, ja hänen urotöistään, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Baesa meni lepoon isiensä luo, ja hänet haudattiin Tirsaan. Sitten hänen poikansa Eela tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Mutta profeetta Jeehun, Hananin pojan, kautta oli tullut Herran sana Baesaa ja hänen sukuaan vastaan kaiken sen tähden, mitä hän oli tehnyt ja mikä oli paha Herran silmissä, hänen kättensä tekojen tähden, joilla hän oli vihoittanut Herran, niin että hänen kävi niin kuin Jerobeamin suvun, sekä myös sen tähden, että hän oli surmannut tämän suvun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Aasan, Juudan kuninkaan, kahdentenakymmenentenä kuudentena hallitusvuotena tuli Eela, Baesan poika, Israelin kuninkaaksi Tirsassa, ja hän hallitsi kaksi vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Mutta hänen palvelijansa Simri, jolla oli johdossaan puolet sotavaunuista, teki salaliiton häntä vastaan. Kun hän Tirsassa oli kerran juonut itsensä juovuksiin Arsan talossa, joka oli päällikkönä Tirsassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Simri tuli sinne, löi hänet kuoliaaksi Juudan kuninkaan Aasan kahdentenakymmenentenä seitsemäntenä hallitusvuotena ja tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Kun hän oli tullut kuninkaaksi ja istunut valtaistuimelleen, hän surmasi koko Baesan suvun eikä jättänyt hänen jälkeläisistään eloon ainoatakaan miespuolista, ei sukulunastajaa eikä ystävää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Niin Simri tuhosi koko Baesan suvun Herran sanan mukaan, jonka hän oli puhunut Baesaa vastaan profeetta Jeehun kautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'kaikkien Baesan ja hänen poikansa Eelan syntien tähden, jotka nämä olivat tehneet ja joilla he olivat saattaneet Israelin tekemään syntiä. He olivat vihoittaneet Herran, Israelin Jumalan, turhilla jumalilla, joita he palvelivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Mitä muuta on kerrottavaa Eelasta ja kaikesta, mitä hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Juudan kuninkaan Aasan kahdentenakymmenentenä seitsemäntenä hallitusvuotena tuli Simri kuninkaaksi, ja hän hallitsi Tirsassa seitsemän päivää. Väki oli silloin asettuneena leiriin Gibbetonin edustalle, joka oli filistealaisilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Kun leiriin asettunut väki kuuli sanottavan: \"Simri on tehnyt salaliiton ja on myös surmannut kuninkaan\", koko Israel teki sinä päivänä kuninkaaksi leirissä Omrin, Israelin sotapäällikön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Omri ja koko Israel hänen kanssaan lähti Gibbetonista, ja he saarsivat Tirsan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Kun Simri näki, että kaupunki oli vallattu, hän meni kuninkaan linnan palatsiin ja poltti kuninkaan linnan päänsä päältä tulella ja kuoli');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'syntiensä tähden, jotka hän oli tehnyt, kun oli tehnyt sitä, mikä on pahaa Herran silmissä, vaeltamalla Jerobeamin teitä ja hänen synnissään, jota tämä oli tehnyt ja jolla hän oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Mitä muuta on kerrottavaa Simristä ja salaliitosta, jonka hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Silloin Israelin kansa jakaantui kahtia. Toinen puoli kansaa seurasi Tibniä, Giinatin poikaa, tehdäkseen hänet kuninkaaksi, toinen puoli seurasi Omria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Mutta se osa kansaa, joka seurasi Omria, sai voiton siitä osasta kansaa, joka seurasi Tibniä, Giinatin poikaa. Tibni kuoli, ja Omri tuli kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Juudan kuninkaan Aasan kolmantenakymmenentenä ensimmäisenä hallitusvuotena tuli Omri Israelin kuninkaaksi, ja hän hallitsi kaksitoista vuotta. Tirsassa hän hallitsi kuusi vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Hän osti Samarian vuoren Semeriltä kahdella talentilla hopeaa ja rakensi vuorelle kaupungin ja kutsui rakentamansa kaupungin Samariaksi Semerin, vuoren omistajan, nimen mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Omri teki sitä, mikä on pahaa Herran silmissä. Hän teki enemmän pahaa kuin kaikki hänen edeltäjänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Hän vaelsi kaikessa Jerobeamin, Nebatin pojan, tietä ja hänen synneissään, joilla hän oli saattanut Israelin tekemään syntiä, niin että he vihoittivat Herran, Israelin Jumalan, turhilla jumalillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Mitä muuta on kerrottavaa Omrista, siitä, mitä hän teki, ja hänen tekemistään urotöistä, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Omri meni lepoon isiensä luo, ja hänet haudattiin Samariaan. Hänen poikansa Ahab tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Ahab, Omrin poika, tuli Israelin kuninkaaksi Aasan, Juudan kuninkaan, kolmantenakymmenentenä kahdeksantena hallitusvuotena. Sitten Ahab, Omrin poika, hallitsi Israelia Samariassa kaksikymmentä kaksi vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Mutta Ahab, Omrin poika, teki sitä, mikä on pahaa Herran silmissä, enemmän kuin kaikki hänen edeltäjänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Ei ollut siinä kylliksi, että hän vaelsi Jerobeamin, Nebatin pojan, synneissä, vaan hän otti myös vaimokseen Iisebelin, siidonilaisten kuninkaan Etbaalin tyttären, ja rupesi palvelemaan Baalia ja kumartamaan sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Hän pystytti alttarin Baalille Baalin temppeliin, jonka hän oli rakentanut Samariaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Ahab teki myös aseran. Ahab teki vielä paljon muutakin ja vihoitti Herraa, Israelin Jumalaa, enemmän kuin kukaan niistä Israelin kuninkaista, jotka olivat olleet ennen häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'Hänen aikanaan beeteliläinen Hiiel rakensi uudelleen Jerikon. Sen perustuksen laskemisesta hän menetti esikoisensa Abiramin, ja sen ovien pystyttämisestä hän menetti nuorimpansa Segubin, Herran sanan mukaan, jonka hän oli puhunut Joosuan, Nuunin pojan, kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Tisbeläinen Elia, eräs Gileadiin asettuneita siirtolaisia, sanoi Ahabille: \"Niin totta kuin Herra, Israelin Jumala, elää, jonka edessä minä seison: näinä vuosina ei tule kastetta eikä sadetta muuten kuin minun sanani kautta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Hänelle tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, '\"Mene pois täältä ja käänny itään päin ja kätkeydy Keritin purolle, joka on Jordanin itäpuolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Sinä saat juoda purosta, ja olen käskenyt korppien elättää sinua siellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Niin hän meni ja teki Herran sanan mukaan: hän meni ja asettui Keritin purolle, joka on Jordanin itäpuolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Korpit toivat hänelle leipää ja lihaa aamuin sekä leipää ja lihaa illoin, ja hän joi purosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Mutta jonkin ajan kuluttua puro kuivui, koska maassa ei ollut satanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Hänelle tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, '\"Nouse ja mene Sarpatiin, joka on Siidonin aluetta, ja asetu sinne. Katso, olen käskenyt leskivaimon elättää sinua siellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Hän nousi ja meni Sarpatiin. Kun hän tuli kaupungin portille, katso, siellä oli leskivaimo keräämässä puita. Hän huusi tälle ja sanoi: \"Tuo minulle vähän vettä astiassa juodakseni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Kun hän lähti hakemaan, hän huusi hänelle ja sanoi: \"Tuo minulle myös leipäpala kädessäsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Mutta hän vastasi: \"Niin totta kuin Herra, Jumalasi, elää, minulla ei ole leipäkakkuakaan, vaan ainoastaan kourallinen jauhoja ruukussa ja vähän öljyä astiassa. Katso, kerättyäni pari puuta menen leipomaan itselleni ja pojalleni syödäksemme ja sitten kuollaksemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Elia sanoi hänelle: \"Älä pelkää, mene ja tee, kuten olet sanonut. Mutta leivo minulle ensin pieni leipäkakku ja tuo se minulle. Leivo sitten itsellesi ja pojallesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Sillä näin sanoo Herra, Israelin Jumala: Jauhot eivät lopu ruukusta, eikä öljyä puutu astiasta siihen päivään asti, jona Herra antaa sateen maan päälle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Hän meni ja teki, kuten Elia oli sanonut. Hänellä sekä myös Elialla ja vaimon perheellä oli syötävää pitkäksi aikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Jauhot eivät loppuneet ruukusta, eikä öljyä puuttunut astiasta, sen Herran sanan mukaan, jonka hän oli Elian kautta puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Sen jälkeen naisen, talon emännän, poika sairastui. Hänen tautinsa kävi hyvin kovaksi, niin ettei hänessä enää ollut henkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Nainen sanoi Elialle: \"Mitä minulla on tekemistä kanssasi, Jumalan mies? Olet tullut luokseni saattamaan pahat tekoni muistoon ja tuottamaan kuoleman pojalleni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Mutta hän sanoi hänelle: \"Anna poikasi minulle.\" Hän otti tämän hänen sylistään ja vei hänet ullakkohuoneeseen, jossa hän asui, ja pani hänet vuoteelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Sitten hän huusi Herraa ja sanoi: \" Herra, Jumalani, oletko tehnyt niin pahoin tätä leskeä kohtaan, jonka vieraana olen, että olet surmannut hänen poikansa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Hän ojentautui pojan yli kolme kertaa, huusi Herraa ja sanoi: \" Herra, Jumalani, anna tämän pojan sielun tulla häneen takaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Herra kuuli Eliaa, ja pojan sielu tuli häneen takaisin, ja hän virkosi henkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Elia otti pojan ja toi hänet yliskammiosta alas huoneeseen ja antoi hänet hänen äidilleen. Elia sanoi: \"Katso, poikasi elää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Nainen sanoi Elialle: \"Nyt tiedän, että sinä olet Jumalan mies ja että Herran sana suussasi on tosi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Pitkän ajan kuluttua, kolmantena vuotena, tuli Elialle tämä Herran sana: \"Mene ja näyttäydy Ahabille, niin minä annan sateen maan päälle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Elia meni näyttäytymään Ahabille. Mutta Samariassa oli kova nälänhätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Ahab kutsui Obadjan, joka oli palatsin päällikkönä. Obadja taas oli hyvin Herraa pelkäävä mies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Niinpä Obadja oli silloin, kun Iisebel hävitti Herran profeettoja, ottanut sata profeettaa ja piilottanut heidät luolaan, viisikymmentä kerrallaan, ja elättänyt heitä leivällä ja vedellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Ahab sanoi Obadjalle: \"Kierrä maa, kaikki vesilähteet ja kaikki purot. Kenties löydämme ruohoa pitääksemme hevoset ja muulit hengissä, niin ettei meidän tarvitse hävittää eläimiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'He jakoivat keskenään maan, joka heidän oli kuljettava. Ahab kulki toista tietä yksin, ja Obadja kulki toista tietä yksin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Kun nyt Obadja oli matkalla, katso, Elia tuli häntä vastaan. Tuntiessaan tämän hän heittäytyi kasvoilleen ja sanoi: \"Sinäkö se olet, herrani Elia?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Tämä vastasi hänelle: \"Minä. Mene ja sano herrallesi: \'Katso, Elia on täällä.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Hän sanoi: \"Mitä olen rikkonut, koska sinä annat palvelijasi Ahabin käsiin, hänen surmattavakseen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Niin totta kuin Herra, Jumalasi, elää, ei ole sitä kansaa eikä sitä valtakuntaa, josta herrani ei olisi lähettänyt etsimään sinua, mutta kun on vastattu: \'Ei hän ole täällä\', hän on vannottanut sillä valtakunnalla ja sillä kansalla valan, ettei sinua ole löydetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Mutta nyt sinä sanot: \'Mene ja sano herrallesi: Katso, Elia on täällä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Kun minä lähden pois luotasi, niin Herran Henki kuljettaa sinut, en tiedä minne, ja kun menen ilmoittamaan Ahabille eikä hän löydä sinua, hän tappaa minut. Kuitenkin palvelijasi on pelännyt Herraa nuoruudestaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Eikö herralleni ole kerrottu, mitä tein, kun Iisebel tappoi Herran profeettoja: kuinka piilotin luolaan sata Herran profeettaa, viisikymmentä kerrallaan, ja elätin heitä leivällä ja vedellä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Nyt sinä sanot: \'Mene ja sano herrallesi: Katso, Elia on täällä\', ja niin hän tappaa minut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Mutta Elia sanoi: \"Niin totta kuin Herra Sebaot elää, jonka edessä seison, näyttäydyn tänä päivänä hänelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Obadja meni Ahabia vastaan ja ilmoitti hänelle tämän. Ahab meni silloin Eliaa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Nähdessään Elian Ahab sanoi hänelle: \"Siinäkö sinä olet, sinä, joka syökset Israelin onnettomuuteen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Tämä vastasi: \"En minä syökse Israelia onnettomuuteen, vaan sinä ja isäsi suku, koska te hylkäätte Herran käskyt ja koska seuraat baaleja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Mutta lähetä nyt kokoamaan kaikki Israel luokseni Karmel-vuorelle, sekä neljäsataa viisikymmentä Baalin profeettaa ja neljäsataa Aseran profeettaa, jotka syövät Iisebelin pöydästä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Ahab lähetti sanan kaikille israelilaisille ja kokosi profeetat Karmel-vuorelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Elia astui kaiken kansan eteen ja sanoi: \"Kuinka kauan te onnutte molemmille puolille? Jos Herra on Jumala, seuratkaa häntä, mutta jos Baal on Jumala, seuratkaa häntä.\" Eikä kansa vastannut hänelle mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Elia sanoi kansalle: \"Minä olen ainoa jäljelle jäänyt Herran profeetta, mutta Baalin profeettoja on neljäsataa viisikymmentä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Antakaa meille kaksi mullia, ja valitkoot he itselleen toisen mullin, paloitelkoot sen ja pankoot kappaleet puiden päälle, mutta älkööt panko tulta. Minä valmistan toisen mullin ja asetan sen puiden päälle, mutta en pane tulta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Sitten huutakaa jumalanne nimeä, ja minä huudan Herran nimeä. Se jumala, joka vastaa tulella, on Jumala.\" Kaikki kansa vastasi ja sanoi: \"Niin on hyvä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Elia sanoi Baalin profeetoille: \"Valitkaa itsellenne toinen mulli ja valmistakaa se ensin, sillä teitä on enemmän. Huutakaa sitten jumalanne nimeä, mutta älkää panko tulta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Niin he ottivat mullin, jonka hän antoi heille, ja valmistivat sen. Sitten he huusivat Baalin nimeä aamusta puolipäivään asti, sanoen: \"Baal, vastaa meille!\" Mutta ei ääntä, ei vastausta! He hyppelivät alttarin ääressä, joka oli tehty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Puolenpäivän aikaan Elia pilkkasi heitä ja sanoi: \"Huutakaa kovemmin. Hän on tosin jumala, mutta hänellä voi olla jotakin toimittamista, tai hän on poistunut johonkin, tai on matkalla. Kenties hän nukkuu, mutta kyllä hän herää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'He huusivat vielä kovemmin ja viileskelivät itseään tapansa mukaan miekoilla ja keihäillä, niin että heistä vuoti verta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Kun puolipäivä oli kulunut, he joutuivat hurmoksiin aina siihen hetkeen asti, jolloin ruokauhri uhrataan. Mutta ei ääntä, ei vastausta, ei vaarinottoa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Elia sanoi kaikelle kansalle: \"Astukaa luokseni.\" Kaikki kansa astui hänen luokseen. Hän korjasi Herran alttarin, joka oli hajotettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Elia otti kaksitoista kiveä, yhtä monta kuin oli Jaakobin poikien sukukuntia, hänen, jolle oli tullut tämä Herran sana: \"Israel on oleva nimesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Hän rakensi kivistä alttarin Herran nimeen ja teki alttarin ympärille ojan, johon olisi mahtunut kaksi sea-mittaa jyviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Hän latoi puut, paloitteli mullin ja pani kappaleet puiden päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Hän sanoi: \"Täyttäkää neljä ruukkua vedellä ja vuodattakaa se polttouhrin ja puiden päälle.\" Ja hän sanoi: \"Tehkää se toinen kerta.\" He tekivät niin toisen kerran. Vielä hän sanoi: \"Tehkää se kolmas kerta.\" Ja he tekivät niin kolmannen kerran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Vesi juoksi ympäri alttarin. Ojankin hän täytti vedellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Kun oli tullut hetki, jolloin ruokauhri uhrataan, profeetta Elia astui esiin ja sanoi: \" Herra, Aabrahamin, Iisakin ja Israelin Jumala, tulkoon tänä päivänä tiettäväksi, että sinä olet Jumala Israelissa ja että minä olen palvelijasi ja että minä olen käskystäsi tehnyt kaiken tämän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Vastaa minulle, Herra, vastaa minulle, että tämä kansa tulisi näkemään, että sinä, Herra, olet Jumala ja että sinä käännät heidän sydämensä takaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Silloin Herran tuli iski alas ja kulutti polttouhrin, puut, kivet ja mullan sekä nuoli veden, joka oli ojassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Kun kaikki kansa näki tämän, he lankesivat kasvoilleen ja sanoivat: \" Herra on Jumala! Herra on Jumala!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Mutta Elia sanoi heille: \"Ottakaa Baalin profeetat kiinni. Älköön yksikään heistä pääskö pakoon.\" Niin he ottivat heidät kiinni. Sitten Elia vei heidät Kiisonin purolle ja tappoi heidät siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Elia sanoi Ahabille: \"Nouse, syö ja juo, sillä sateen kohina kuuluu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Ahab nousi syömään ja juomaan. Mutta Elia nousi Karmelin huipulle, kumartui maahan ja painoi kasvonsa polviensa väliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Hän sanoi palvelijalleen: \"Nouse ja katso merelle päin.\" Tämä nousi, katsoi ja sanoi: \"Ei näy mitään.\" Hän sanoi: \"Mene takaisin.\" Näin seitsemän kertaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Seitsemännellä kerralla palvelija sanoi: \"Katso, pieni pilvi, miehen kämmenen kokoinen, nousee merestä.\" Elia sanoi: \"Nouse ja sano Ahabille: \'Valjasta ja lähde alas, ettei sade sinua pidättäisi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Tuossa tuokiossa taivas kävi mustaksi pilvistä ja myrskytuulesta, ja tuli ankara sade. Mutta Ahab nousi vaunuihinsa ja lähti Jisreeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Herran käsi tuli Elian päälle, ja hän vyötti lanteensa ja juoksi Ahabin edellä Jisreeliin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Mutta kun Ahab kertoi Iisebelille kaiken, mitä Elia oli tehnyt ja kuinka hän oli tappanut miekalla kaikki profeetat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Iisebel lähetti sanansaattajan Elian luo ja käski sanoa: \"Jumalat rangaiskoot minua nyt ja vasta, jollen minä huomenna tähän aikaan tee sinulle samaa, mikä jokaiselle näistä on tehty.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Kun Elia sen näki, hän nousi ja lähti matkaan pelastaakseen henkensä ja tuli Beersebaan, joka on Juudan aluetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Hän jätti sinne palvelijansa, mutta meni itse erämaahan päivämatkan päähän. Hän tuli ja istuutui kinsteripensaan juurelle. Hän toivotti itselleen kuolemaa ja sanoi: \"Jo riittää, Herra, ota henkeni, sillä minä en ole isiäni parempi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Hän paneutui makuulle ja nukahti kinsteripensaan juurelle. Mutta katso, enkeli kosketti häntä ja sanoi hänelle: \"Nouse ja syö.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Kun hän katsahti, niin, katso, hänen päänsä takana oli kuumennetuilla kivillä paistettu leipäkakku ja vesiastia. Niin hän söi, joi ja pani jälleen maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Mutta Herran enkeli kosketti häntä vielä toisen kerran ja sanoi: \"Nouse ja syö, sillä muuten käy matka sinulle liian pitkäksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Hän nousi, söi ja joi. Hän kulki sen ruuan voimalla neljäkymmentä päivää ja neljäkymmentä yötä Jumalan vuorelle, Hoorebille, asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Siellä hän meni luolaan ja yöpyi siinä. Mutta katso, Herran sana [tuli] hänelle: hän kysyi häneltä: \"Mitä sinä teet täällä, Elia?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Hän vastasi: \"Olen totisesti kiivaillut Herran, Jumalan Sebaotin, puolesta. Sillä israelilaiset ovat hylänneet liittosi, hajottaneet alttarisi ja tappaneet miekalla profeettasi. Minä olen yksin jäänyt jäljelle, mutta minunkin henkeäni he väijyvät ottaakseen sen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Hän sanoi: \"Mene ulos ja asetu vuorelle Herran eteen.\" Katso, Herra kulki ohi, ja suuri ja raju myrsky, joka halkoi vuoret ja särki kalliot, kävi Herran edellä, mutta Herra ei ollut myrskyssä. Myrskyn jälkeen tuli maanjäristys, mutta Herra ei ollut maanjäristyksessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Maanjäristyksen jälkeen tuli tulta, mutta Herra ei ollut tulessa. Tulen jälkeen tuli hiljainen tuulen hyminä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Kun Elia sen kuuli, hän peitti kasvonsa viitallaan, meni ulos ja asettui luolan suulle. Katso, hänelle puhui ääni ja sanoi: \"Mitä sinä teet täällä, Elia?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Hän vastasi: \"Olen totisesti kiivaillut Herran, Jumalan Sebaotin, puolesta. Sillä israelilaiset ovat hylänneet liittosi, hajottaneet alttarisi ja tappaneet miekalla profeettasi. Minä olen yksin jäänyt jäljelle, mutta minunkin henkeäni he väijyvät ottaakseen sen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Herra sanoi hänelle: \"Lähde takaisin samaa tietä, jota tulit, erämaan kautta Damaskoon. Mene ja voitele Hasael Aramin kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Voitele Jeehu, Nimsin poika, Israelin kuninkaaksi. Ja voitele sijaasi profeetaksi Elisa, Saafatin poika, Aabel-Meholasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'On tapahtuva näin: joka välttää Hasaelin miekan, sen surmaa Jeehu, ja joka välttää Jeehun miekan, sen surmaa Elisa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Mutta jätän jäljelle Israeliin seitsemäntuhatta: kaikki polvet, jotka eivät ole notkistuneet Baalille, ja kaikki suut, jotka eivät ole suudelleet häntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Hän lähti sieltä ja kohtasi Elisan, Saafatin pojan, kun tämä oli kyntämässä. Kaksitoista härkäparia kulki hänen edellään, ja hän ajoi itse kahdettatoista. Kulkiessaan hänen ohitseen Elia heitti viittansa hänen päälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Hän jätti härät, riensi Elian jälkeen ja sanoi: \"Salli minun ensin suudella isääni ja äitiäni, sitten seuraan sinua.\" Elia sanoi hänelle: \"Mene, mutta tule takaisin. Tiedäthän, mitä olen sinulle tehnyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Hän palasi hänen luotaan takaisin, otti härkäparinsa ja teurasti sen, ja härkien ikeellä hän keitti lihat. Ne hän antoi väelle, ja he söivät. Sitten hän nousi ja seurasi Eliaa ja palveli häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Benhadad, Aramin kuningas, kokosi kaiken sotajoukkonsa. Hänellä oli mukanaan kolmekymmentä kaksi kuningasta sekä hevosia ja sotavaunuja. Hän meni ja piiritti Samariaa ja ryhtyi taisteluun sitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Hän lähetti sanansaattajat kaupunkiin Ahabin, Israelin kuninkaan, luo');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'ja käski sanoa hänelle: \"Näin sanoo Benhadad: \'Hopeasi ja kultasi ovat minun, ja kauneimmat vaimosi ja lapsesi ovat myös minun.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Israelin kuningas vastasi ja sanoi: \"Niin kuin sinä olet sanonut, herrani, kuningas, minä olen sinun, minä ja kaikki, mitä minulla on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Sanansaattajat tulivat takaisin ja sanoivat: \"Näin sanoo Benhadad: \'Minä olen lähettänyt sinulle tämän sanan: Anna minulle hopeasi ja kultasi, vaimosi ja lapsesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Totisesti minä lähetän huomenna tähän aikaan palvelijani luoksesi tutkimaan talosi ja palvelijaisi talot. Kaiken, mikä on silmiesi ihastus, he ottavat haltuunsa ja vievät.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Silloin Israelin kuningas kutsui kaikki maan vanhimmat ja sanoi: \"Ymmärtäkää ja nähkää, että hän hankkii meille onnettomuutta, sillä kun hän lähetti vaatimaan minulta vaimojani ja lapsiani, hopeaani ja kultaani, en minä niitä häneltä kieltänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Kaikki vanhimmat ja kaikki kansa sanoivat hänelle: \"Älä kuule häntä äläkä suostu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Hän sanoi Benhadadin sanansaattajille: \"Sanokaa herralleni, kuninkaalle: \'Kaiken, mitä sinä ensi kerralla käskit palvelijasi tehdä, teen, mutta tätä en voi tehdä.\'\" Sanansaattajat menivät ja veivät tämän vastauksen hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Mutta Benhadad lähetti hänelle sanan: \"Jumalat rangaiskoot minua nyt ja vasta, jos Samarian tomu riittää täyttämään kaiken sen väen kourat, joka minua seuraa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Mutta Israelin kuningas vastasi ja sanoi: \"Sanokaa hänelle: \'Älköön se, joka vyöttäytyy miekkaan, kerskatko niin kuin se, joka sen riisuu.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Kun hän, juodessaan kuninkaitten kanssa lehtimajoissa, kuuli tämän vastauksen, hän sanoi palvelijoilleen: \"Piiritys käyntiin!\" Ja he panivat piirityksen käyntiin kaupunkia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Katso, eräs profeetta astui Ahabin, Israelin kuninkaan, eteen ja sanoi: \"Näin sanoo Herra: Näetkö kaiken tuon suuren lauman? Katso, minä annan sen tänä päivänä käsiisi, että tulisit tietämään, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Ahab kysyi: \"Kenen avulla?\" Hän vastasi: \"Näin sanoo Herra: Maaherrojen palvelijoiden avulla.\" Ahab kysyi vielä: \"Kuka aloittaa taistelun?\" Hän vastasi: \"Sinä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Hän katsasti herrojen palvelijat, ja niitä oli kaksisataa kolmekymmentä kaksi. Niitten jälkeen hän katsasti kaiken väen, kaikki israelilaiset, joita oli seitsemäntuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'He tekivät hyökkäyksen puolenpäivän aikana, kun Benhadad oli juovuksissa ja joi lehtimajoissa, hän ja ne kolmekymmentä kaksi kuningasta, jotka olivat tulleet hänen avukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Maaherrojen palvelijat hyökkäsivät ensimmäisinä. Silloin Benhadad lähetti tiedustelemaan, ja hänelle ilmoitettiin: \"Miehiä on lähtenyt liikkeelle Samariasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Hän sanoi: \"Jos he ovat lähteneet liikkeelle rauha mielessä, ottakaa heidät kiinni elävinä. Mutta jos he ovat lähteneet taistellakseen, ottakaa heidät silloinkin kiinni elävinä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Mutta kun maaherrojen palvelijat ja sotajoukko, joka seurasi heitä, olivat hyökänneet kaupungista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'he surmasivat kukin miehen. Aramilaiset pakenivat, ja Israel ajoi heitä takaa. Benhadad, Aramin kuningas, pääsi muutamien ratsumiesten kanssa pakoon hevosen selässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Mutta Israelin kuningas lähti liikkeelle ja valtasi hevoset ja sotavaunut. Hän tuotti aramilaisille suuren tappion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Profeetta astui Israelin kuninkaan eteen ja sanoi hänelle: \"Vahvista itsesi, ymmärrä ja katso, mitä sinun on tehtävä, sillä vuoden vaihteessa hyökkää Aramin kuningas kimppuusi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Aramin kuninkaan palvelijat sanoivat tälle: \"Heidän jumalansa on vuorijumala. Sen tähden he saivat meistä voiton. Mutta taistelkaamme heitä vastaan tasangolla, silloin varmasti saamme heistä voiton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Tee näin: Pane pois kuninkaat, kukin paikaltaan, ja aseta käskynhaltijat heidän sijaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Hanki itsellesi sotajoukko, yhtä suuri kuin menettämäsi oli, yhtä monta hevosta ja yhtä monet sotavaunut, ja taistelkaamme heitä vastaan tasangolla, niin varmasti saamme heistä voiton.\" Hän kuuli heitä ja teki niin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Vuoden vaihteessa Benhadad katsasti aramilaiset ja lähti Afekiin taistelemaan Israelia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Israelilaiset katsastettiin ja muonitettiin, ja he lähtivät heitä vastaan. Israelilaiset leiriytyivät heidän eteensä niin kuin kaksi pientä vuohilaumaa, mutta aramilaiset täyttivät maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Silloin Jumalan mies astui Israelin kuninkaan eteen ja sanoi: \"Näin sanoo Herra: Sen tähden, että aramilaiset ovat sanoneet: \' Herra on vuorijumala eikä laaksojumala\', minä annan koko tämän suuren lauman käsiisi tullaksenne tietämään, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'He olivat leiriytyneinä vastakkain seitsemän päivää. Seitsemäntenä päivänä syntyi taistelu, ja israelilaiset surmasivat aramilaisia satatuhatta jalkamiestä yhtenä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Jäljellejääneet pakenivat Afekiin, kaupunkiin. Muuri kaatui kahdenkymmenen seitsemän tuhannen jäljellejääneen miehen päälle. Mutta Benhadad pakeni, tuli kaupunkiin ja juoksi huoneesta huoneeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Hänen palvelijansa sanoivat hänelle: \"Katso, olemme kuulleet, että Israelin heimon kuninkaat ovat laupiaita kuninkaita. Pankaamme säkit lanteillemme ja nuorat päämme ympärille ja antautukaamme Israelin kuninkaalle. Ehkäpä hän jättää sinut henkiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'He käärivät säkit lanteilleen ja panivat nuorat päänsä ympärille ja tulivat Israelin kuninkaan luo ja sanoivat: \"Palvelijasi Benhadad sanoo: \'Salli minun elää.\'\" Hän sanoi: \"Vieläkö hän elää? Hän on minun veljeni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Niin miehet katsoivat sen hyväksi enteeksi, tarttuivat kiireen vilkkaa hänen sanaansa ja sanoivat: \"Benhadad on veljesi.\" Hän sanoi: \"Menkää ja noutakaa hänet.\" Silloin Benhadad antautui hänelle, ja hän antoi hänen nousta vaunuihinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Benhadad sanoi hänelle: \"Kaupungit, jotka minun isäni otti isältäsi, minä annan takaisin. Laita itsellesi katumyymälöitä Damaskoon, niin kuin isäni laittoi Samariaan.\" Ahab vastasi: \"Minä päästän sinut menemään sillä välipuheella.\" Hän teki liiton hänen kanssaan ja päästi hänet menemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Silloin eräs profeetanoppilaista sanoi Herran käskystä toverilleen: \"Lyö minua.\" Mutta mies ei tahtonut lyödä häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Hän sanoi tälle: \"Koska et kuullut Herran ääntä, niin, katso, leijona surmaa sinut, kun lähdet luotani.\" Kun hän lähti hänen luotaan, kohtasi leijona hänet ja surmasi hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Sitten hän tapasi toisen miehen ja sanoi: \"Lyö minua.\" Mies löi hänet haavoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Profeetta meni ja asettui tielle, jota kuninkaan oli kuljettava, ja teki itsensä tuntemattomaksi panemalla siteen silmilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Kun kuningas kulki ohi, hän huusi kuninkaalle ja sanoi: \"Palvelijasi oli lähtenyt keskelle taistelua, ja katso, sieltä tuli mies ja toi toisen miehen luokseni ja sanoi: \'Vartioi tätä miestä. Jos hän katoaa, henkesi menee hänen hengestään, tai sinä maksat talentin hopeaa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Palvelijallasi oli tehtävää siellä ja täällä, ja sitten miestä ei enää ollut.\" Israelin kuningas sanoi hänelle: \"Tuomiosi on siis se. Olet sen itse julistanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Hän poisti nopeasti siteen silmiltään, ja Israelin kuningas tunsi hänet, että hän oli profeettoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Tämä sanoi hänelle: \"Näin sanoo Herra: Koska sinä päästit käsistäsi menemään minulle tuhon omaksi vihityn miehen, menee henkesi hänen hengestään ja kansasi hänen kansastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Israelin kuningas meni kotiinsa pahastuneena ja alakuloisena ja tuli Samariaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Näiden tapausten jälkeen tapahtui tämä. Jisreeliläisellä Naabotilla oli viinitarha, joka oli Jisreelissä Samarian kuninkaan Ahabin palatsin vieressä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Ahab puhui Naabotille sanoen: \"Anna minulle viinitarhasi vihannestarhaksi, koska se on niin lähellä linnaani. Annan sinulle sen tilalle paremman viinitarhan, tai, jos niin tahdot, annan sinulle sen hinnan rahana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Mutta Naabot vastasi Ahabille: \"Pois se, Herra varjelkoon minua antamasta sinulle isieni perintöosaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Ahab tuli kotiinsa pahastuneena ja alakuloisena vastauksesta, jonka jisreeliläinen Naabot oli hänelle antanut, kun tämä oli sanonut: \"En anna sinulle isieni perintöosaa.\" Hän pani maata vuoteelleen, käänsi kasvonsa pois eikä syönyt mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Hänen vaimonsa Iisebel tuli hänen luokseen ja puhui hänelle: \"Miksi olet niin pahoilla mielin ja miksi et syö mitään?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Ahab vastasi hänelle: \"Siksi, että puhuttelin jisreeliläistä Naabotia ja sanoin hänelle: \'Anna minulle viinitarhasi rahasta, tai jos haluat, annan sinulle toisen viinitarhan sen sijaan\', mutta hän vastasi: \'En minä anna sinulle viinitarhaani.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Niin hänen vaimonsa Iisebel sanoi hänelle: \"Sinäkö olet käyttävinäsi kuninkaanvaltaa Israelissa? Nouse ja syö, ja olkoon sydämesi iloinen. Minä kyllä toimitan sinulle jisreeliläisen Naabotin viinitarhan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Hän kirjoitti kirjeen Ahabin nimessä, sinetöi sen hänen sinetillään ja lähetti kirjeen vanhimmille ja ylimyksille, jotka olivat Naabotin kaupungissa ja asuivat siellä hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Kirjeessä hän kirjoitti näin: \"Kuuluttakaa paasto ja asettakaa Naabot istumaan etummaiseksi kansan joukkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Asettakaa kaksi kelvotonta miestä istumaan häntä vastapäätä, että he todistaisivat hänestä näin: \'Sinä olet kironnut Jumalaa ja kuningasta.\' Viekää hänet sitten ulos ja kivittäkää hänet kuoliaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Kaupungin miehet, vanhimmat ja ylimykset, jotka asuivat hänen kaupungissaan, tekivät, kuten Iisebel oli käskenyt heitä ja niin kuin oli kirjoitettu kirjeessä, jonka hän oli heille lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'He kuuluttivat paaston ja asettivat Naabotin istumaan etummaiseksi kansan joukkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Kaksi kelvotonta miestä tuli ja istui häntä vastapäätä, ja kelvottomat miehet todistivat Naabotista kansan edessä sanoen: \"Naabot on kironnut Jumalaa ja kuningasta.\" Ja he veivät hänet kaupungin ulkopuolelle ja kivittivät hänet kuoliaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'He lähettivät Iisebelille tämän sanan: \"Naabot on kivitetty kuoliaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Kun Iisebel kuuli, että Naabot oli kivitetty kuoliaaksi, Iisebel sanoi Ahabille: \"Nouse ja ota haltuusi jisreeliläisen Naabotin viinitarha, jota hän ei tahtonut antaa sinulle rahasta. Sillä Naabot ei ole enää elossa, vaan on kuollut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Kun Ahab kuuli, että Naabot oli kuollut, hän nousi ja lähti jisreeliläisen Naabotin viinitarhalle ottamaan sen haltuunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Mutta tisbeläiselle Elialle tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, '\"Nouse ja mene tapaamaan Ahabia, Israelin kuningasta, joka asuu Samariassa. Katso, hän on Naabotin viinitarhassa, jota hän on mennyt ottamaan haltuunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Puhu hänelle ja sano: \'Näin sanoo Herra: Oletko sinä sekä tappanut että anastanut perinnön?\' Puhu sitten hänelle ja sano: \'Näin sanoo Herra: Siinä paikassa, missä koirat nuoleskelivat Naabotin veren, koirat nuoleskelevat sinunkin veresi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Ahab sanoi Elialle: \"Joko löysit minut, sinä vihamieheni?\" Hän vastasi: \"Jo löysin. Koska sinä olet myynyt itsesi tekemään sitä, mikä on pahaa Herran silmissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'niin, katso, minä annan onnettomuuden kohdata sinua ja lakaisen sinut pois ja hävitän Israelista Ahabin miespuoliset jälkeläiset, kaikki tyynni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Minä teen suvullesi niin kuin Jerobeamin, Nebatin pojan, suvulle ja niin kuin Baesan, Ahian pojan, suvulle, koska olet vihoittanut minut ja saattanut Israelin tekemään syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Myös Iisebelistä Herra on puhunut sanoen: Koirat syövät Iisebelin Jisreelin muurin luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Joka Ahabin jälkeläisistä kuolee kaupungissa, sen koirat syövät, ja joka kuolee kedolle, sen syövät taivaan linnut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Totisesti ei ole ollut ketään, joka olisi niin myynyt itsensä tekemään sitä, mikä on pahaa Herran silmissä, kuin Ahab, kun hänen vaimonsa Iisebel vietteli hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Hän teki hyvin kauhistavasti, kun lähti seuraamaan epäjumalia, aivan kuten amorilaiset tekivät, jotka Herra karkotti israelilaisten tieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Kun Ahab kuuli nämä sanat, hän repäisi vaatteensa, pani paljaalle iholleen säkin ja paastosi. Hän makasi säkki yllään ja liikkui hiljaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Niin tisbeläiselle Elialle tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, '\"Oletko nähnyt, kuinka Ahab on nöyrtynyt edessäni? Koska hän on nöyrtynyt edessäni, en anna onnettomuuden tulla hänen aikanaan: hänen poikansa aikana annan onnettomuuden kohdata hänen sukuaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'He olivat alallaan kolme vuotta: ei ollut sotaa Aramin ja Israelin välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'Mutta kolmantena vuotena tuli Joosafat, Juudan kuningas, Israelin kuninkaan luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Israelin kuningas sanoi palvelijoilleen: \"Tiedättehän, että Gileadin Raamot on meidän. Kuitenkin olemme toimettomia emmekä ota sitä pois Aramin kuninkaan käsistä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Hän sanoi Joosafatille: \"Lähdetkö kanssani sotaan Gileadin Raamotiin?\" Joosafat vastasi Israelin kuninkaalle: \"Minä niin kuin sinä, minun kansani niin kuin sinun kansasi, minun hevoseni niin kuin sinun hevosesi!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Mutta Joosafat sanoi Israelin kuninkaalle: \"Kysy kuitenkin ensin, mitä Herra sanoo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Niin Israelin kuningas kokosi profeetat, noin neljäsataa miestä, ja sanoi heille: \"Onko minun lähdettävä sotaan Gileadin Raamotia vastaan vai oltava lähtemättä?\" He vastasivat: \"Lähde, Herra antaa sen kuninkaan käsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Mutta Joosafat sanoi: \"Eikö täällä ole enää ketään muuta Herran profeettaa, jolta voisimme kysyä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Israelin kuningas vastasi Joosafatille: \"On täällä vielä mies, jolta voisimme kysyä Herran mieltä, mutta minä vihaan häntä, sillä hän ei koskaan ennusta minulle hyvää, vaan aina pahaa, se on Miika, Jimlan poika.\" Joosafat sanoi: \"Älköön kuningas niin puhuko.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Israelin kuningas kutsui erään hoviherran ja sanoi: \"Nouda kiireen vilkkaa Miika, Jimlan poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Mutta Israelin kuningas ja Joosafat, Juudan kuningas, istuivat kumpikin valtaistuimellaan puettuina kuninkaallisiin pukuihinsa puimatantereella Samarian portin ovella. Kaikki profeetat olivat hurmoksissa heidän edessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Sidkia, Kenaanan poika, teki itselleen rautasarvet ja sanoi: \"Näin sanoo Herra: Näillä sinä pusket aramilaisia, kunnes teet heistä lopun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Kaikki profeetat ennustivat samalla tavalla sanoen: \"Mene ylös Gileadin Raamotiin, saat voiton. Herra antaa sen kuninkaan käsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Sanansaattaja, joka oli mennyt kutsumaan Miikaa, puhui hänelle sanoen: \"Katso, kaikki profeetat ovat yhdestä suusta luvanneet kuninkaalle hyvää. Olkoon sanasi heidän sanansa kaltainen, ja lupaa sinäkin hyvää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Mutta Miika vastasi: \"Niin totta kuin Herra elää, sen puhun, minkä Herra minulle sanoo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Kun hän tuli kuninkaan eteen, kuningas sanoi hänelle: \"Miika, onko meidän lähdettävä sotaan Gileadin Raamotiin vai oltava lähtemättä?\" Hän vastasi hänelle: \"Lähde, niin saat voiton. Herra antaa sen kuninkaan käsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Mutta kuningas sanoi hänelle: \"Kuinka monta kertaa minun on vannotettava sinua, ettet puhu minulle muuta kuin totuutta Herran nimessä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Silloin hän sanoi: \"Minä näin koko Israelin hajallaan vuorilla kuin lampaat, joilla ei ole paimenta. Herra sanoi: \'Näillä ei ole isäntää, palatkoon kukin rauhassa kotiinsa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Israelin kuningas sanoi Joosafatille: \"Enkö sanonut sinulle, ettei tämä koskaan ennusta minulle hyvää, vaan aina pahaa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Mutta hän sanoi: \"Kuule siis Herran sana: Näin Herran istuvan istuimellaan ja kaiken taivaan joukon seisovan hänen edessään, hänen oikealla ja vasemmalla puolellaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Herra sanoi: \'Kuka viekoittelisi Ahabin lähtemään sotaan, että hän kaatuisi Gileadin Raamotissa?\' Mikä vastasi niin, mikä näin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Silloin tuli henki ja asettui Herran eteen ja sanoi: \'Minä viekoittelen hänet.\' Herra kysyi häneltä: \'Miten?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Hän vastasi: \'Minä menen valheen hengeksi kaikkien hänen profeettojensa suuhun.\' Silloin Herra sanoi: \'Saat viekoitella, siihen sinä pystyt, mene ja tee niin.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Katso, nyt Herra on pannut valheen hengen kaikkien näiden profeettojesi suuhun, sillä Herra on päättänyt osaksesi onnettomuuden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Silloin astui esille Sidkia, Kenaanan poika, löi Miikaa poskelle ja sanoi: \"Mitä tietä Herran Henki on poistunut minusta puhuakseen kanssasi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Miika vastasi: \"Sen saat nähdä sinä päivänä, jona kuljet huoneesta huoneeseen piiloutuaksesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Mutta Israelin kuningas sanoi: \"Ota Miika ja vie hänet takaisin Aamonin, kaupungin päällikön, ja Jooaan, kuninkaan pojan, luo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'ja sano: \'Näin sanoo kuningas: Pankaa tämä vankilaan ja elättäkää häntä kovassa nälässä vedellä ja leivällä, kunnes palaan rauhassa takaisin.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Miika vastasi: \"Jos palaat rauhassa takaisin, Herra ei ole puhunut kauttani.\" Hän sanoi vielä: \"Kuulkaa tämä, kaikki kansat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Israelin kuningas ja Joosafat, Juudan kuningas, menivät Gileadin Raamotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Israelin kuningas sanoi Joosafatille: \"Täytyypä pukeutua tuntemattomaksi, kun käy taisteluun, mutta ole sinä omissa vaatteissasi.\" Israelin kuningas pukeutui tuntemattomaksi ja kävi taisteluun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Mutta Aramin kuningas oli käskenyt sotavaunujen päälliköitä, joita hänellä oli kolmekymmentä kaksi, sanoen: \"Älkää ryhtykö taisteluun kenenkään muun kanssa, olkoon alempi tai ylempi, kuin ainoastaan Israelin kuninkaan kanssa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Kun sotavaunujen päälliköt näkivät Joosafatin, he ajattelivat: \"Tuo on varmaankin Israelin kuningas\", ja kääntyivät hyökkäämään häntä vastaan. Silloin Joosafat huusi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Kun sotavaunujen päälliköt näkivät, ettei se ollutkaan Israelin kuningas, he vetäytyivät hänestä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Mutta eräs mies, joka oli jännittänyt jousensa ja ampui umpimähkään, satutti Israelin kuningasta vyöpanssarin ja rintahaarniskan väliin. Niin tämä sanoi vaunujensa ohjaajalle: \"Käännä vaunut ja vie minut pois rintamalta, sillä olen haavoittunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Mutta kun taistelu sinä päivänä yltyi yltymistään, kuningas jäi seisomaan vaunuihinsa, päin aramilaisia. Illalla hän kuoli, ja verta oli vuotanut haavasta vaunun pohjalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Auringon laskiessa kaikui kautta sotajoukon huuto: \"Joka mies kaupunkiinsa! Joka mies maahansa!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Näin kuoli kuningas, ja hänet vietiin Samariaan, ja kuningas haudattiin Samariaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Kun vaunut huuhdottiin Samarian lammikolla, nuoleskelivat koirat hänen vertaan, ja portot peseytyivät siinä, sen sanan mukaan, jonka Herra oli puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Mitä muuta on kerrottavaa Ahabista ja kaikesta, mitä hän teki, siitä norsunluisesta palatsista, jonka hän rakensi, ja kaikista kaupungeista, jotka hän linnoitti, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Niin Ahab meni lepoon isiensä luo. Hänen poikansa Ahasja tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Joosafat, Aasan poika, tuli Juudan kuninkaaksi Ahabin, Israelin kuninkaan, neljäntenä hallitusvuotena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Joosafat oli kolmenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi kaksikymmentä viisi vuotta Jerusalemissa. Hänen äitinsä oli nimeltään Asuba, Silhin tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Hän vaelsi kaikessa isänsä Aasan tietä, siltä poikkeamatta, ja teki sitä, mikä oli oikein Herran silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Mutta uhrikukkulat eivät hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Joosafat teki rauhan Israelin kuninkaan kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Mitä muuta on kerrottavaa Joosafatista, hänen urotöistään ja hänen sodistaan, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Hän hävitti maasta viimeiset niistä haureellisista pyhäkköpojista, jotka olivat jääneet jäljelle hänen isänsä Aasan ajoilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Edomissa ei siihen aikaan ollut kuningasta. Maaherra oli kuninkaana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Joosafat oli teettänyt Tarsiin laivoja, joiden oli määrä kulkea Oofiriin kultaa noutamaan. Mutta laivat eivät päässeet lähtemään, sillä ne särkyivät Esjon-Geberissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Silloin Ahasja, Ahabin poika, sanoi Joosafatille: \"Anna palvelijoitteni kulkea palvelijoittesi kanssa laivoissa.\" Mutta Joosafat ei tahtonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Joosafat meni lepoon isiensä luo, ja hänet haudattiin isiensä viereen hänen isänsä Daavidin kaupunkiin. Hänen poikansa Jooram tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Ahasja, Ahabin poika, tuli Israelin kuninkaaksi Samariassa Joosafatin, Juudan kuninkaan, seitsemäntenätoista hallitusvuotena ja hallitsi Israelia kaksi vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Hän teki sitä, mikä on pahaa Herran silmissä, ja vaelsi isänsä ja äitinsä tietä ja Jerobeamin, Nebatin pojan, tietä, hänen, joka oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 54, 'Hän palveli Baalia ja kumarsi häntä ja vihoitti Herran, Israelin Jumalan, samoin kuin hänen isänsä oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Ahabin kuoleman jälkeen Mooab luopui Israelista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Ahasja putosi Samariassa yläsalinsa ristikon läpi ja makasi sairaana. Hän lähetti sanansaattajia ja sanoi heille: \"Menkää ja kysykää Baal-Sebubilta, Ekronin jumalalta, toivunko tästä taudista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Mutta Herran enkeli oli sanonut tisbeläiselle Elialle: \"Nouse ja mene Samarian kuninkaan sanansaattajia vastaan ja sano heille: \'Eikö ole Jumalaa Israelissa, koska menette kysymään neuvoa Baal-Sebubilta, Ekronin jumalalta?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Sen tähden Herra sanoo näin: \'Vuoteesta, johon olet noussut, et enää astu alas, sillä sinun on kuoltava.\'\" Ja Elia lähti tiehensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Kun sanansaattajat palasivat kuninkaan luo, hän kysyi heiltä: \"Minkä tähden te tulette takaisin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'He vastasivat hänelle: \"Meitä vastaan tuli mies, joka sanoi meille: \'Menkää takaisin kuninkaan luo, joka on teidät lähettänyt, ja sanokaa hänelle: Näin sanoo Herra: Eikö ole Jumalaa Israelissa, koska sinä lähetät kysymään neuvoa Baal-Sebubilta, Ekronin jumalalta? Sen tähden sinä et enää astu alas vuoteesta, johon olet noussut, sillä sinun on kuoltava.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Hän kysyi heiltä: \"Minkä näköinen mies oli, joka tuli teitä vastaan ja puhui teille tuollaista?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'He vastasivat hänelle: \"Hänellä oli yllään karvanahka ja nahkavyö vyötäisillä.\" Silloin hän sanoi: \"Se oli tisbeläinen Elia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Sitten hän lähetti hänen luokseen viidenkymmenen päämiehen ja hänen viisikymmentä miestään. Kun tämä tuli hänen luokseen hänen istuessaan vuoren kukkulalla, hän sanoi hänelle: \"Sinä Jumalan mies, kuningas käskee: Tule alas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Mutta Elia vastasi ja sanoi viidenkymmenen päämiehelle: \"Jos minä olen Jumalan mies, niin tulkoon tuli taivaasta ja kuluttakoon sinut ja viisikymmentä miestäsi.\" Silloin tuli taivaasta tuli ja kulutti hänet ja hänen viisikymmentä miestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Hän lähetti taas hänen luokseen toisen viidenkymmenen päämiehen ja hänen viisikymmentä miestään. Tämä lausui ja sanoi hänelle: \"Sinä Jumalan mies, näin käskee kuningas: Tule kiireen vilkkaa alas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Mutta Elia vastasi ja sanoi heille: \"Jos minä olen Jumalan mies, niin tulkoon tuli taivaasta ja kuluttakoon sinut ja viisikymmentä miestäsi.\" Silloin tuli taivaasta Jumalan tuli ja kulutti hänet ja hänen viisikymmentä miestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Hän lähetti vielä kolmannen viidenkymmenen päämiehen ja hänen viisikymmentä miestään. Tämä kolmas viidenkymmenen päämies meni sinne, ja kun hän tuli perille, hän polvistui Elian eteen ja anoi häneltä armoa ja sanoi hänelle: \"Sinä Jumalan mies, olkoon henkeni ja näiden viidenkymmenen palvelijasi henki kallis silmissäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Katso, tuli on tullut taivaasta ja kuluttanut ne kaksi ensimmäistä viidenkymmenen päämiestä ja heidän viisikymmentä miestään, mutta olkoon henkeni kallis silmissäsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Herran enkeli sanoi Elialle: \"Mene alas hänen kanssaan, älä pelkää häntä.\" Hän nousi ja meni hänen kanssaan kuninkaan luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Hän sanoi hänelle: \"Näin sanoo Herra: Koska lähetit sanansaattajia kysymään neuvoa Baal-Sebubilta, Ekronin jumalalta, ikään kuin Israelissa ei olisi Jumalaa, jolta voisi kysyä neuvoa, sen tähden sinä et astu alas vuoteesta, johon olet noussut, sillä sinun on kuoltava.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Ja hän kuoli, Herran sanan mukaan, jonka Elia oli puhunut. Jooram tuli kuninkaaksi hänen jälkeensä Jooramin, Joosafatin pojan, Juudan kuninkaan, toisena hallitusvuotena, sillä Ahasjalla ei ollut poikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Mitä muuta on kerrottavaa Ahasjasta, siitä, mitä hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Silloin, kun Herra oli vievä Elian tuulispäässä taivaaseen, kulkivat Elia ja Elisa Gilgalista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Elia sanoi Elisalle: \"Jää tähän, sillä Herra on lähettänyt minut Beeteliin asti.\" Mutta Elisa vastasi: \"Niin totta kuin Herra elää, ja niin totta kuin sielusi elää: en jätä sinua.\" Ja he menivät Beeteliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Beetelissä olevat profeetanoppilaat tulivat Elisan luo ja sanoivat hänelle: \"Tiedätkö, että Herra tänä päivänä ottaa herrasi pois sinun pääsi yli?\" Hän vastasi: \"Tiedän kyllä, olkaa vaiti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Elia sanoi hänelle: \"Elisa, jää tähän, sillä Herra on lähettänyt minut Jerikoon.\" Mutta hän vastasi: \"Niin totta kuin Herra elää, ja niin totta kuin sielusi elää: en jätä sinua.\" He tulivat Jerikoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Jerikossa olevat profeetanoppilaat astuivat Elisan luo ja sanoivat hänelle: \"Tiedätkö, että Herra tänä päivänä ottaa herrasi pois pääsi yli?\" Hän vastasi: \"Minä kyllä tiedän, olkaa vaiti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Elia sanoi hänelle: \"Jää tähän, sillä Herra on lähettänyt minut Jordanille.\" Mutta hän vastasi: \"Niin totta kuin Herra elää, ja niin totta kuin sielusi elää: en jätä sinua.\" He kulkivat molemmat yhdessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Mutta myös profeetanoppilaita lähti matkaan viisikymmentä miestä, ja he asettuivat syrjään jonkin matkan päähän näiden kahden pysähtyessä Jordanille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Elia otti viittansa, kääri sen kokoon ja löi veteen, ja vesi jakaantui kummallekin puolelle, ja he kävivät molemmat virran yli kuivaa myöten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Kun he olivat tulleet yli, Elia sanoi Elisalle: \"Pyydä minua tekemään hyväksesi jotakin, ennen kuin minut otetaan pois luotasi.\" Elisa sanoi: \"Tulkoon minuun hengestäsi kaksinkertainen osa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Hän vastasi: \"Pyyntösi on vaikea täyttää. Mutta jos näet, kuinka minut otetaan pois luotasi, se täytetään, jollet, se jää täyttämättä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Kun he niin kulkivat ja puhelivat, katso, äkkiä ilmestyivät tuliset vaunut ja tuliset hevoset, ja ne erottivat heidät toisistaan, ja Elia nousi tuulispäässä taivaaseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Kun Elisa sen näki, hän huusi: \"Isäni, isäni! Israelin sotavaunut ja ratsumiehet!\" Hän ei enää nähnyt häntä. Hän tarttui vaatteisiinsa ja repäisi ne kahdeksi kappaleeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Sitten hän otti maasta Elian viitan, joka oli pudonnut hänen päältään, palasi takaisin ja pysähtyi Jordanin rannalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Hän otti Elian viitan, joka oli pudonnut tämän päältä, löi veteen ja sanoi: \"Missä on Herra, Elian Jumala?\" Kun hän siis löi veteen, se jakaantui kummallekin puolelle, ja Elisa käveli virran yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Kun Jerikosta tulleet profeetanoppilaat näkivät sen edessään, he sanoivat: \"Elian henki on laskeutunut Elisaan.\" Niin he tulivat häntä vastaan ja kumartuivat hänen edessään maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'He sanoivat hänelle: \"Katso, palvelijoidesi joukossa on viisikymmentä urhoollista miestä, menkööt he etsimään isäntääsi. Ehkä Herran Henki on vienyt hänet ja heittänyt jollekin vuorelle tai johonkin laaksoon.\" Hän vastasi: \"Älkää lähettäkö.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Mutta he pyysivät häntä pyytämällä kyllästyksiin asti, kunnes hän sanoi: \"Lähettäkää.\" Niin he lähettivät viisikymmentä miestä. Nämä etsivät kolme päivää, mutta eivät löytäneet häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Kun he tulivat takaisin hänen luokseen, hänen ollessaan Jerikossa, hän sanoi heille: \"Enkö minä kieltänyt teitä menemästä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Kaupungin miehet sanoivat Elisalle: \"Katso, kaupungin asema on hyvä, niin kuin herrani näkee, mutta vesi on huonoa, ja maassa syntyy keskosia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Hän sanoi: \"Tuokaa minulle uusi malja ja pankaa siihen suoloja.\" He toivat sen hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Hän meni vesien lähteelle ja heitti siihen suolat, sanoen: \"Näin sanoo Herra: Minä olen parantanut tämän veden. Siitä ei tule enää kuolemaa eikä keskenmenoa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Vesi tuli terveelliseksi aina tähän päivään asti Elisan sanan mukaan, jonka hän puhui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Sieltä hän meni Beeteliin, ja hänen kävellessään tietä tuli nuoria poikia kaupungista, ja he pilkkasivat häntä ja sanoivat hänelle: \"Nouse ylös, kaljupää, nouse ylös, kaljupää!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Kun hän kääntyi ja näki heidät, hän kirosi heidät Herran nimeen. Silloin tuli metsästä kaksi karhua ja raateli neljäkymmentä kaksi poikaa kuoliaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Sieltä hän meni Karmel-vuorelle ja palasi sieltä Samariaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Jooram, Ahabin poika, tuli Israelin kuninkaaksi Samariassa Joosafatin, Juudan kuninkaan, kahdeksantenatoista hallitusvuotena, ja hän hallitsi kaksitoista vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Hän teki sitä, mikä on pahaa Herran silmissä, ei kuitenkaan niin kuin hänen isänsä ja äitinsä, sillä hän poisti Baalin patsaan, jonka hänen isänsä oli teettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Kuitenkin hän riippui kiinni Jerobeamin, Nebatin pojan, synnissä, jolla tämä oli saattanut Israelin tekemään syntiä. Siitä hän ei luopunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Meesa, Mooabin kuningas, omisti lammaslaumoja ja maksoi verona Israelin kuninkaalle satatuhatta karitsaa ja sadantuhannen pässin villat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Mutta Ahabin kuoltua Mooabin kuningas luopui Israelin kuninkaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Siihen aikaan kuningas Jooram lähti Samariasta ja katsasti koko Israelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Hän meni ja lähetti Joosafatille Juudan kuninkaalle sanan: \"Mooabin kuningas on luopunut minusta. Lähdetkö kanssani sotaan Mooabia vastaan?\" Hän vastasi: \"Lähden, minä niin kuin sinä, minun kansani niin kuin sinun kansasi, minun hevoseni niin kuin sinun hevosesi!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Joosafat kysyi: \"Mitä tietä meidän on sinne mentävä?\" Hän vastasi: \"Edomin erämaan tietä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Israelin kuningas, Juudan kuningas ja Edomin kuningas lähtivät liikkeelle. Mutta kun he olivat kierrellen kulkeneet seitsemän päivän matkan eikä ollut vettä sotajoukolle eikä juhdille, jotka seurasivat heitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Israelin kuningas sanoi: \"Voi, Herra on kutsunut nämä kolme kuningasta kokoon antaakseen heidät Mooabin käsiin!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Mutta Joosafat sanoi: \"Eikö täällä ole ketään Herran profeettaa, kysyäksemme hänen kauttaan neuvoa Herralta?\" Silloin eräs Israelin kuninkaan palvelijoista vastasi ja sanoi: \"Täällä on Elisa, Saafatin poika, joka vuodatti vettä Elian käsille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Joosafat sanoi: \"Hänellä on Herran sana.\" Israelin kuningas, Joosafat ja Edomin kuningas menivät hänen luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Elisa sanoi Israelin kuninkaalle: \"Mitä minulla on tekemistä kanssasi? Mene isäsi ja äitisi profeettojen luo.\" Israelin kuningas sanoi hänelle: \"Ei niin! Sillä Herra on kutsunut nämä kolme kuningasta kokoon antaakseen heidät Mooabin käsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Elisa sanoi: \"Niin totta kuin Herra Sebaot elää, jonka edessä seison: jollen tahtoisi tehdä Joosafatille, Juudan kuninkaalle, mieliksi, tosiaankaan en katsoisi sinuun enkä huomaisi sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Mutta tuokaa minulle nyt harpunsoittaja.\" Kun harpunsoittaja soitti, Herran käsi laskeutui hänen päälleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'ja hän sanoi: \"Näin sanoo Herra: Tehkää tämä laakso kuoppia täyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Sillä näin sanoo Herra: Te ette tule näkemään tuulta ettekä sadetta, ja kuitenkin tämä laakso tulee vettä täyteen. Niin te saatte juoda, sekä te että karjanne ja juhtanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Mutta tämä on Herran silmissä pieni asia: hän antaa Mooabin teidän käsiinne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'ja te valloitatte kaikki varustetut kaupungit ja kaikki valitut kaupungit, kaadatte kaikki hedelmäpuut, tukitte kaikki vesilähteet ja turmelette kivillä kaikki hyvät peltopalstat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Katso, seuraavana aamuna, sinä hetkenä, jona ruokauhri uhrataan, vettä tuli Edomista päin, niin että maa tuli vettä täyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Kun kaikki mooabilaiset kuulivat, että kuninkaat olivat lähteneet sotaan heitä vastaan, kutsuttiin koolle kaikki miekkaan vyöttäytyvät ja myös vanhemmat miehet, ja he asettuivat rajalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Varhain aamulla, kun aurinko nousi ja paistoi veteen, näkivät mooabilaiset, että vesi heidän edessään oli punaista kuin veri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'He sanoivat: \"Se on verta. Varmaan kuninkaat ovat joutuneet taisteluun keskenään ja surmanneet toisensa. Nyt saaliin ryöstöön, Mooab!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Mutta kun he tulivat Israelin leiriin, nousivat israelilaiset ja voittivat mooabilaiset, niin että nämä pakenivat heitä. He hyökkäsivät maahan ja voittivat uudelleen mooabilaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'He hävittivät kaupungit, kaikille hyville peltopalstoille heitti kukin heistä kiven, täyttäen ne. He tukkivat kaikki vesilähteet ja kaatoivat kaikki hedelmäpuut, niin että ainoastaan Kiir-Haresetissa jäivät kivet paikoilleen. Linkomiehet piirittivät kaupungin ja ampuivat sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Kun Mooabin kuningas näki joutuvansa tappiolle taistelussa, hän otti mukaansa seitsemänsataa miekkamiestä murtautuakseen Edomin kuninkaan luo. Mutta he eivät voineet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Hän otti poikansa, esikoisensa, jonka oli määrä tulla kuninkaaksi hänen jälkeensä, ja uhrasi hänet polttouhriksi muurilla. Silloin suuri viha kohtasi Israelia, niin että he lähtivät sieltä ja palasivat omaan maahansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Eräs nainen, profeetanoppilaan vaimo, huusi Elisalle sanoen: \"Mieheni, palvelijasi, kuoli, ja sinä tiedät, että palvelijasi oli herraapelkäävä mies. Nyt velkoja tulee ottamaan molemmat poikani orjikseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Elisa sanoi hänelle: \"Mitä teen hyväksesi? Sano minulle, mitä sinulla on talossasi.\" Hän vastasi: \"Palvelijattarellasi ei ole talossa muuta kuin öljyä sen verran, mitä tarvitsen voidellakseni itseäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Silloin hän sanoi: \"Mene ja lainaa itsellesi astioita kylästä, kaikilta naapureiltasi, tyhjiä astioita, tarpeeksi paljon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Mene sitten sisään, sulje ovi jälkeesi ja poikiesi jälkeen ja kaada kaikkiin niihin astioihin. Aina kun astia on täysi, nosta se syrjään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Niin hän meni pois hänen luotaan ja sulki oven jälkeensä ja poikiensa jälkeen. Nämä toivat sitten hänelle astiat, ja hän kaatoi niihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Kun astiat olivat täynnä, hän sanoi pojalleen: \"Tuo minulle vielä yksi astia.\" Mutta hän vastasi hänelle: \"Ei ole enää astiaa.\" Silloin öljy tyrehtyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Hän meni ja kertoi sen Jumalan miehelle. Tämä sanoi: \"Mene, myy öljy ja maksa velkasi. Sinä ja poikasi elätte siitä, mikä jää jäljelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Eräänä päivänä Elisa meni Suunemiin, ja siellä oli arvossa pidetty nainen, joka vaati häntä aterioimaan. Niin usein kuin hän kulki sen kautta, hän poikkesi sinne aterioimaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Nainen sanoi miehelleen: \"Katso, minä olen huomannut, että hän, joka aina kulkee kauttamme, on pyhä Jumalan mies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Muurauttakaamme pieni ullakkohuone ja pankaamme hänelle sinne vuode, pöytä, tuoli ja lamppu, niin että hän tullessaan luoksemme voi vetäytyä sinne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Eräänä päivänä hän sitten tuli sinne, poikkesi ullakkohuoneeseen ja pani sinne maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Hän sanoi palvelijalleen Geehasille: \"Kutsu suunemilainen nainen.\" Hän kutsui tämän, ja hän astui hänen eteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Hän sanoi palvelijalle: \"Sano hänelle: \'Katso, sinä olet nähnyt kaiken tämän vaivan meidän tähtemme. Voinko tehdä jotakin hyväksesi? Onko sinulla jotakin esitettävää kuninkaalle tai sotapäällikölle?\'\" Mutta hän vastasi: \"Minähän asun heimoni keskellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Hän kysyi: \"Eikö siis voi tehdä mitään hänen hyväkseen?\" Geehasi vastasi: \"Voi kyllä: hänellä ei ole poikaa, ja hänen miehensä on vanha.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Hän sanoi: \"Kutsu hänet.\" Niin tämä kutsui hänet, ja hän astui ovelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Elisa sanoi: \"Tähän aikaan tulevana vuonna on sinulla sylissäsi poika.\" Hän vastasi: \"Ei, herrani, sinä Jumalan mies, älä petä palvelijatartasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Mutta vaimo tuli raskaaksi ja synnytti pojan seuraavana vuonna juuri sinä aikana, jonka Elisa oli hänelle sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Kun poika oli kasvanut isoksi, hän meni eräänä päivänä isänsä luo, joka oli leikkuuväen luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Hän valitti isälleen: \"Voi minun päätäni, voi minun päätäni!\" Tämä sanoi palvelijalle: \"Kanna hänet äitinsä luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Niin palvelija otti hänet ja vei hänet äitinsä luo. Poika istui hänen polvillaan puoleenpäivään asti. Sitten hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Äiti meni ylös ja laski hänet Jumalan miehen vuoteeseen, sulki oven, niin että poika jäi yksin, ja lähti pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Hän kutsui miehensä ja sanoi: \"Lähetä minulle palvelija ja aasintamma, niin minä riennän Jumalan miehen luo ja tulen heti takaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Hän sanoi: \"Miksi menet hänen luokseen tänä päivänä? Eihän nyt ole uusikuu eikä sapatti.\" Hän vastasi: \"Ole huoleti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Hän satuloi aasintamman ja sanoi palvelijalleen: \"Aja yhä eteenpäin äläkä keskeytä matkaani, ennen kuin sanon sinulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Hän lähti ja tuli Jumalan miehen luo Karmel-vuorelle. Kun Jumalan mies näki hänet kaukaa, hän sanoi palvelijalleen Geehasille: \"Katso, se on suunemilainen nainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Riennä nyt häntä vastaan ja kysy häneltä: \'Voitko hyvin, voivatko miehesi ja poikasi hyvin?\'\" Hän vastasi: \"Hyvin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Tultuaan vuorelle Jumalan miehen luo hän tarttui hänen jalkoihinsa. Geehasi astui esiin työntääkseen hänet pois. Mutta Jumalan mies sanoi: \"Jätä hänet rauhaan, sillä hänen sielunsa on murheellinen, ja Herra on salannut sen minulta eikä ole ilmoittanut sitä minulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Hän sanoi: \"Pyysinkö minä poikaa herraltani? Enkö sanonut: \'Älä uskottele minulle\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Silloin Elisa sanoi Geehasille: \"Vyötä kupeesi ja ota sauvani käteesi ja mene. Jos kohtaat jonkun, älä tervehdi häntä, ja jos joku tervehtii sinua, älä vastaa. Pane sauvani pojan kasvoille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Mutta pojan äiti sanoi: \"Niin totta kuin Herra elää, ja niin totta kuin sielusi elää: en jätä sinua.\" Elisa nousi ja seurasi häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Mutta Geehasi oli mennyt heidän edellään ja pannut sauvan pojan kasvoille, mutta tämä ei äännähtänyt eikä kuullut. Hän tuli takaisin häntä vastaan ja kertoi hänelle sanoen: \"Poika ei herännyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Kun Elisa tuli huoneeseen, katso, poika makasi hänen vuoteessaan kuolleena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Tultuaan sisään hän sulki oven, niin että he jäivät kahden, ja hän rukoili Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Sen jälkeen hän nousi vuoteelle ja laskeutui pojan yli, pannen suunsa hänen suunsa päälle, silmänsä hänen silmiensä päälle ja kätensä hänen kättensä päälle. Kun hän näin kumartui hänen ylitseen, lämpeni pojan ruumis.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Sitten hän kulki huoneessa kerran edestakaisin ja nousi ja kumartui hänen ylitseen. Silloin poika aivasti seitsemän kertaa, ja sen jälkeen poika avasi silmänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Hän kutsui Geehasin ja sanoi: \"Kutsu suunemilainen nainen.\" Niin hän kutsui naisen, ja tämä tuli hänen luokseen. Hän sanoi: \"Ota poikasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Silloin nainen tuli ja lankesi hänen jalkojensa juureen, kumartui maahan ja otti poikansa ja meni ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Elisa palasi Gilgaliin, ja maassa oli nälänhätä. Kun profeetanoppilaat istuivat hänen edessään, hän sanoi palvelijalleen: \"Pane suuri pata liedelle ja keitä keitto profeetanoppilaille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Eräs heistä meni kedolle poimimaan yrttejä ja löysi villin köynnöskasvin ja poimi siitä villikurkkuja viittansa täyteen. Tultuaan hän leikkeli ne keittopataan, sillä he eivät tunteneet niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'He kaatoivat miesten syödä, mutta kun nämä maistoivat keittoa, he huusivat ja sanoivat: \"Jumalan mies, padassa on kuolema!\" Eivätkä he voineet syödä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Silloin hän sanoi: \"Tuokaa jauhoja.\" Sitten hän heitti ne pataan, ja sanoi: \"Kaatakaa väen syödä\", eikä padassa ollut mitään vahingollista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Eräs mies tuli Baal-Saalisasta ja toi Jumalan miehelle ensi sadon leipää, kaksikymmentä ohraleipää ja uutta viljaa repussaan. Silloin Elisa sanoi: \"Anna väelle syötävää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Mutta hänen palvelijansa sanoi: \"Kuinka voin tarjota siitä sadalle miehelle?\" Hän sanoi: \"Anna väelle syödä, sillä näin sanoo Herra: He syövät, ja jää tähteeksikin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Niin hän tarjosi heille, ja he söivät, ja jäi tähteeksikin, Herran sanan mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Naeman, Aramin kuninkaan sotapäällikkö, oli herransa hyvin arvossa pitämä ja suurta kunnioitusta nauttiva mies, sillä hänen kauttaan Herra oli antanut Aramille voiton. Hän oli väkevä sankari, mutta spitaalinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Kerran aramilaiset olivat menneet ryöstöretkelle ja tuoneet Israelin maasta vankina pienen tytön, joka joutui palvelukseen Naemanin puolisolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Tyttö sanoi emännälleen: \"Oi, jospa herrani kävisi profeetan luona Samariassa! Hän kyllä päästäisi hänet hänen spitaalistaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Naeman meni ja kertoi tämän herralleen, sanoen: \"Niin ja niin on tyttö, joka on Israelin maasta, puhunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Aramin kuningas vastasi: \"Mene vain sinne. Minä lähetän kirjeen Israelin kuninkaalle.\" Naeman lähti sinne ja otti mukaansa kymmenen talenttia hopeaa, kuusituhatta sekeliä kultaa ja kymmenen juhlapukua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Hän vei Israelin kuninkaalle kirjeen, joka kuului näin: \"Kun tämä kirje tulee sinulle, katso, minä olen lähettänyt luoksesi palvelijani Naemanin, että päästäisit hänet hänen spitaalistaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Kun Israelin kuningas oli lukenut kirjeen, hän repäisi vaatteensa ja sanoi: \"Olenko minä Jumala, joka ottaa elämän ja antaa elämän, koska hän käskee minua päästämään miehen hänen spitaalistaan? Ymmärtäkää ja nähkää, että hän etsii aihetta minua vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Kun Jumalan mies Elisa kuuli, että Israelin kuningas oli reväissyt vaatteensa, hän lähetti kuninkaalle sanan: \"Miksi olet reväissyt vaatteesi? Anna hänen tulla luokseni, niin hän tulee tietämään, että Israelissa on profeetta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Naeman tuli hevosineen ja vaunuineen ja pysähtyi Elisan talon oven eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Elisa lähetti hänen luokseen sanansaattajan ja käski sanoa: \"Mene ja peseydy seitsemän kertaa Jordanissa, niin lihasi tulee entiselleen, ja tulet puhtaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Mutta Naeman vihastui ja lähti pois sanoen: \"Katso, minä luulin hänen edes tulevan ja astuvan esiin ja rukoilevan Herran, Jumalansa, nimeä, heiluttavan kättään sen paikan yli ja poistavan spitaalin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Eivätkö Damaskon virrat, Abana ja Parpar, ole kaikkia Israelin vesiä paremmat? Voinhan yhtä hyvin peseytyä niissä tullakseni puhtaaksi.\" Hän kääntyi pois ja meni tiehensä kiukustuneena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Mutta hänen palvelijansa astuivat esiin ja puhuttelivat häntä ja sanoivat: \"Isäni, jos profeetta olisi määrännyt sinulle jotakin erinomaista, etkö tekisi sitä? Saati sitten, kun hän sanoi sinulle ainoastaan: \'Peseydy, niin tulet puhtaaksi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Hän meni ja kastoi itsensä Jordanissa seitsemän kertaa, niin kuin Jumalan mies oli sanonut. Hänen lihansa tuli entiselleen, pienen pojan lihan kaltaiseksi, ja hän tuli puhtaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Sitten hän palasi Jumalan miehen luo, hän ja koko hänen joukkonsa, meni sisälle, astui hänen eteensä ja sanoi: \"Katso, nyt tiedän, ettei Jumalaa ole missään muualla maan päällä kuin Israelissa. Ota siis vastaan jäähyväislahja palvelijaltasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Mutta hän vastasi: \"Niin totta kuin Herra elää, jonka edessä seison, en sitä ota.\" Naeman pyytämällä pyysi häntä ottamaan, mutta hän epäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Niin Naeman sanoi: \"Jos et tätä otakaan, salli kuitenkin palvelijasi saada sen verran maata, kuin muulipari voi kantaa. Sillä palvelijasi ei enää uhraa polttouhria eikä teurasuhria muille jumalille kuin Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Tämän antakoon kuitenkin Herra anteeksi palvelijallesi: kun herrani menee Rimmonin temppeliin rukoilemaan nojaten käteeni, ja minäkin kumarrun Rimmonin temppelissä, niin antakoon Herra palvelijallesi anteeksi sen, että kumarrun Rimmonin temppelissä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Elisa sanoi hänelle: \"Mene rauhassa.\" Kun hän oli kulkenut hänen luotaan jonkin matkaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'ajatteli Geehasi, Jumalan miehen Elisan palvelija: \"Katso, minun herrani säästi tuota aramilaista Naemania, niin ettei ottanut häneltä, mitä hän oli tuonut. Niin totta kuin Herra elää, riennän hänen jälkeensä ja otan häneltä jotakin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Geehasi juoksi Naemanin jälkeen. Kun Naeman näki hänen rientävän jäljessään, hän hyppäsi alas vaunuistaan, meni häntä vastaan ja kysyi: \"Onko kaikki hyvin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Hän vastasi: \"Hyvin on, mutta herrani on lähettänyt minut ja käskee sanoa: \'Nyt juuri tuli luokseni Efraimin vuoristosta kaksi nuorta miestä, profeetanoppilaita. Anna heille talentti hopeaa ja kaksi juhlapukua.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Naeman vastasi: \"Suvaitse ottaa kaksi talenttia.\" Hän pyytämällä pyysi häntä. Hän sitoi kaksi talenttia hopeaa kahteen kukkaroon ja antoi ne sekä kaksi juhlapukua kahdelle palvelijalleen, ja he kantoivat niitä hänen edellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Mutta kun hän tuli kummulle, hän otti ne heidän käsistään ja kätki ne taloon ja päästi miehet menemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Sitten hän meni sisälle ja astui herransa luo. Niin Elisa kysyi häneltä: \"Mistä tulet, Geehasi?\" Hän vastasi: \"Palvelijasi ei ole käynyt missään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Elisa sanoi hänelle: \"Eikö henkeni kulkenut kanssasi, kun eräs mies kääntyi vaunuissaan sinua vastaan? Oliko nyt aika ottaa hopeaa ja hankkia vaatteita, öljytarhoja, viinitarhoja, lampaita, nautoja, palvelijoita ja palvelijattaria?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Naemanin spitaali tarttuu sinuun ja sinun jälkeläisiisi ikiajoiksi.\" Niin Geehasi lähti hänen luotaan lumivalkeana spitaalista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Profeetanoppilaat sanoivat Elisalle: \"Katso, huone, jossa istumme edessäsi, on meille liian ahdas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Menkäämme siis Jordanille ja tuokaamme sieltä kukin yksi hirsi ja rakentakaamme sinne huone, missä voimme istua.\" Hän sanoi: \"Menkää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Eräs heistä sanoi: \"Suvaitse tulla palvelijasi kanssa.\" Hän sanoi: \"Minä tulen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Niin hän meni heidän kanssaan. Jordanille tultuaan he hakkasivat puita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Mutta erään heistä kaataessa puuta kirposi kirves veteen. Niin hän huusi ja sanoi: \"Voi, herrani, se oli vielä lainattu!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Jumalan mies kysyi: \"Mihin se kirposi?\" Niin hän näytti hänelle paikan. Silloin hän veisti puupalan ja heitti sen siihen ja sai kirveen nousemaan pinnalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Sitten hän sanoi: \"Nosta se ylös.\" Mies ojensi kätensä ja otti sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Kun Aramin kuningas oli sodassa Israelia vastaan, hän neuvotteli palvelijoidensa kanssa ja sanoi: \"Siihen ja siihen paikkaan asetun leiriin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Mutta Jumalan mies lähetti Israelin kuninkaalle sanan: \"Varo, ettet mene siihen paikkaan, sillä aramilaiset ovat asettuneet sinne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Israelin kuningas lähetti sanan siihen paikkaan, jonka Jumalan mies oli hänelle sanonut. Näin tämä varoitti häntä, ja hän oli siellä varuillaan. Eikä se tapahtunut ainoastaan kerran tai kahdesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Aramin kuninkaan sydän tuli tästä levottomaksi, ja hän kutsui palvelijansa ja sanoi heille: \"Ettekö voi ilmaista minulle, kuka meikäläisistä pitää Israelin kuninkaan puolta?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Silloin eräs hänen palvelijoistaan sanoi: \"Ei niin, herrani, kuningas, vaan profeetta Elisa, joka on Israelissa, ilmaisee Israelin kuninkaalle nekin sanat, jotka puhut makuuhuoneessasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Hän sanoi: \"Menkää ja katsokaa, missä hän on, niin lähetän ottamaan hänet kiinni.\" Hänelle ilmoitettiin: \"Katso, hän on Dootanissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Hän lähetti sinne hevosia ja sotavaunuja ja suuren sotajoukon. He tulivat sinne yöllä ja ympäröivät kaupungin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Kun Jumalan miehen palvelija nousi aamulla varhain ja meni ulos, katso, sotajoukko, hevoset ja sotavaunut piirittivät kaupunkia. Hänen palvelijansa sanoi hänelle: \"Voi, herrani, mitä me nyt teemme?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Hän sanoi: \"Älä pelkää, sillä niitä, jotka ovat kanssamme, on enemmän kuin niitä, jotka ovat heidän kanssaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Elisa rukoili ja sanoi: \" Herra, avaa hänen silmänsä, että hän näkisi.\" Herra avasi palvelijan silmät, ja hän näki, ja katso: vuori oli täynnä tulisia hevosia ja tulisia vaunuja Elisan ympärillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Kun viholliset sitten tulivat häntä vastaan, Elisa rukoili Herraa ja sanoi: \"Sokaise tämä väki.\" Hän sokaisi heidät Elisan pyynnön mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Elisa sanoi heille: \"Ei tämä ole oikea tie, eikä tämä ole oikea kaupunki. Seuratkaa minua, niin minä vien teidät sen miehen luo, jota te etsitte.\" Sitten hän vei heidät Samariaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Mutta kun he tulivat Samariaan, Elisa sanoi: \" Herra, avaa näiden silmät, että he näkisivät.\" Silloin Herra avasi heidän silmänsä, ja he näkivät, ja katso: he olivat keskellä Samariaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Kun Israelin kuningas näki heidät, hän sanoi Elisalle: \"Surmaanko heidät, isäni, surmaanko heidät?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Hän sanoi: \"Älä surmaa. Surmaatko ne, jotka otat vangiksi miekallasi ja jousellasi? Pane heidän eteensä ruokaa ja juomaa heidän syödä ja juoda. Menkööt sitten takaisin herransa luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Tämä valmisti heille suuren aterian, ja kun he olivat syöneet ja juoneet, hän päästi heidät menemään, ja he menivät herransa luo. Aramilaisia partiojoukkoja ei enää tullut Israelin maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Sen jälkeen Benhadad, Aramin kuningas, kokosi kaiken sotajoukkonsa ja tuli ja piiritti Samarian.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Silloin syntyi Samariassa heidän sitä piirittäessään suuri nälänhätä, niin että aasinpää maksoi kahdeksankymmentä hopeasekeliä ja neljännes kab-mittaa kyyhkysen lantaa viisi hopeasekeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Kun Israelin kuningas käveli muurin päällä, huusi muuan nainen hänelle ja sanoi: \"Auta, herrani, kuningas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Hän vastasi: \"Ellei Herra auta sinua, niin mistä minä hankin sinulle apua? Puimatantereeltako vai viinikuurnasta?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Kuningas sanoi hänelle: \"Mikä sinun on?\" Hän vastasi: \"Tämä nainen sanoi minulle: \'Anna tänne poikasi syödäksemme hänet tänä päivänä, niin syömme huomenna minun poikani.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Me keitimme minun poikani ja söimme hänet. Minä sanoin toisena päivänä hänelle: \'Anna tänne poikasi syödäksemme hänet.\' Mutta hän piilotti poikansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Kun kuningas kuuli naisen sanat, hän repäisi vaatteensa kävellessään muurin päällä. Kansa näki, että hänellä oli vaatteiden alla säkki, paljaalla iholla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Hän sanoi: \"Jumala rangaiskoon minua nyt ja vasta, jos Elisan, Saafatin pojan, pää tänä päivänä jää hänen hartioilleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Elisa istui talossaan, ja vanhimmat istuivat hänen luonaan. Mutta kuningas oli lähettänyt miehen edellään. Ennen kuin sanansaattaja tuli hänen luokseen, hän sanoi vanhimmille: \"Näettekö, kuinka se murhamiehen poika lähettää hakkaamaan minulta päätä poikki? Mutta kun sanansaattaja tulee, katsokaa, että suljette oven ja pidätte oven kiinni häneltä. Eivätkö hänen herransa askeleet kuulu jo hänen perässään?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Hänen vielä puhuessaan heidän kanssaan tuli sanansaattaja hänen luokseen ja sanoi: \"Katso, tämä onnettomuus tulee Herralta, miksi minä enää odottaisin Herraa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Mutta Elisa vastasi: \"Kuulkaa Herran sana. Näin sanoo Herra: Huomenna tähän aikaan maksaa Samarian portissa sea-mitta ydinjauhoja sekelin ja kaksi sea-mittaa ohria sekelin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Vaunusoturi, jonka käsivarteen kuningas nojasi, vastasi Jumalan miehelle ja sanoi: \"Katso, vaikka Herra tekisi ikkunat taivaaseen, kuinka tämä voisi tapahtua?\" Hän sanoi: \"Sinä olet sen omin silmin näkevä, mutta siitä et syö.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Kaupungin portin oven edustalla oleskeli neljä spitaalista miestä. He sanoivat toisilleen: \"Mitä me tässä istumme, kunnes kuolemme?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Jos päätämme mennä kaupunkiin, jossa on nälänhätä, niin kuolemme. Jos jäämme tähän, kuolemme. Tulkaa, siirtykäämme nyt aramilaisten leiriin. Jos he jättävät meidät eloon, jäämme eloon. Jos he surmaavat meidät, kuolemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'He nousivat hämärissä mennäkseen aramilaisten leiriin. Kun he tulivat aramilaisten leirin laitaan, katso: siellä ei ollut ketään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Sillä Herra oli antanut aramilaisten sotajoukon kuulla sotavaunujen, hevosten ja suuren sotajoukon töminää, ja niin he olivat sanoneet toisilleen: \"Katso, Israelin kuningas on palkannut meitä vastaan heettiläisten kuninkaat ja egyptiläisten kuninkaat käydäkseen meitä vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'He olivat lähteneet liikkeelle ja paenneet hämärissä ja jättäneet telttansa, hevosensa, aasinsa ja leirinsä, niin kuin se oli. He olivat paenneet pelastaakseen henkensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Tultuaan leirin laitaan spitaaliset menivät erääseen telttaan, söivät ja joivat, ottivat sieltä hopeaa ja kultaa ja vaatteita, menivät pois ja kätkivät ne. Sitten he tulivat takaisin ja menivät toiseen telttaan ja ottivat sieltä saalista ja menivät pois ja kätkivät sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Mutta sitten he sanoivat toisilleen: \"Emme tee oikein. Tämä päivä on hyvän sanoman päivä. Jos olemme vaiti ja odotamme aamun valkenemiseen asti joudumme syyllisiksi. Tulkaa, menkäämme nyt ilmoittamaan tämä kuninkaan linnaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'He tulivat ja kutsuivat kaupungin portinvartijat ja ilmoittivat heille sanoen: \"Me tulimme aramilaisten leiriin, ja katso, siellä ei ollut ketään eikä kuulunut ihmisääntä. Siellä oli vain hevosia ja aaseja kytkettyinä kiinni, ja teltat olivat, niin kuin olivat olleet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Portinvartijat kuuluttivat ja ilmoittivat tämän kuninkaan linnaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Silloin kuningas nousi yöllä ja sanoi palvelijoilleen: \"Minä sanon teille, minkä aramilaiset meille tekevät. He tietävät meidän kärsivän nälkää, ja sen tähden he ovat poistuneet leiristä ja piiloutuneet kedolle, ajatellen: kun he lähtevät kaupungista, otamme heidät elävinä kiinni ja menemme kaupunkiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Mutta eräs hänen palvelijoistaan vastasi ja sanoi: \"Otettakoon viisi jäljelle jäänyttä hevosta, jotka ovat vielä täällä jäljellä – niidenhän käy kuitenkin samoin kuin kaiken Israelin joukon, joka on täällä jäljellä, ja samoin kuin kaiken Israelin joukon, joka on hukkunut – ja lähettäkäämme katsomaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'He ottivat kahdet sotavaunut hevosineen, ja kuningas lähetti ne aramilaisten sotajoukon perään, sanoen: \"Menkää ja katsokaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'He menivät heidän jälkeensä aina Jordanille asti. Katso: koko tie oli täynnä vaatteita ja aseita, jotka aramilaiset olivat heittäneet pois rientäessään pakoon. Sanansaattajat tulivat takaisin ja ilmoittivat sen kuninkaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Silloin kansa lähti ja ryösti aramilaisten leirin. Niin sea-mitta ydinjauhoja maksoi sekelin ja kaksi sea-mittaa ohria sekelin Herran sanan mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Kuningas oli asettanut sen vaunusoturin, jonka käsivarteen hän nojasi, porttiin valvomaan järjestystä. Mutta kansa tallasi hänet kuoliaaksi portissa, kuten Jumalan mies oli puhunut, silloin kun kuningas tuli hänen luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Sillä kun Jumalan mies oli puhunut kuninkaalle näin: \"Huomenna tähän aikaan maksaa kaksi sea-mittaa ohria Samarian portissa sekelin ja sea-mitta ydinjauhoja sekelin\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'vaunusoturi oli vastannut Jumalan miehelle ja sanonut: \"Katso, vaikka Herra tekisi ikkunat taivaaseen, kuinka tämä voisi tapahtua?\" Silloin hän oli sanonut: \"Sinä olet näkevä sen omin silmin, mutta siitä et syö.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Niin hänen myös kävi: kansa tallasi hänet kuoliaaksi portissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Elisa sanoi naiselle, jonka pojan hän oli palauttanut henkiin, ja sanoi: \"Nouse ja lähde, sinä ja perheesi, asumaan muukalaisena, missä vain voit asua, sillä Herra on käskenyt nälänhädän tulla, ja se myös tulee maahan seitsemäksi vuodeksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Nainen oli noussut ja tehnyt Jumalan miehen sanan mukaan: hän oli lähtenyt ja asunut perheineen muukalaisena filistealaisten maassa seitsemän vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Mutta niiden seitsemän vuoden kuluttua nainen palasi filistealaisten maasta. Hän tuli anomaan kuninkaalta taloaan ja peltoaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Kuningas puhutteli juuri Geehasia, Jumalan miehen palvelijaa, ja sanoi: \"Kerro minulle kaikki ne suuret teot, jotka Elisa on tehnyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Juuri kun hän kertoi kuninkaalle, kuinka Elisa oli palauttanut kuolleen henkiin, nainen, jonka pojan hän oli palauttanut henkiin, tuli anomaan kuninkaalta taloaan ja peltoaan. Silloin Geehasi sanoi: \"Herrani, kuningas, tämä on se nainen, ja tämä on se poika, jonka Elisa palautti henkiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Kuningas kyseli naiselta, ja tämä kertoi sen hänelle. Kuningas antoi hänen mukaansa hoviherran ja sanoi: \"Toimita naiselle takaisin kaikki, mikä on hänen omaansa, ja lisäksi kaikki pellon sadot siitä päivästä alkaen, jona hän jätti maan, aina tähän asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Elisa tuli Damaskoon. Aramin kuningas Benhadad oli sairaana. Kun hänelle ilmoitettiin: \"Jumalan mies on tullut tänne\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'kuningas sanoi Hasaelille: \"Ota mukaasi lahja ja mene Jumalan miestä vastaan ja kysy hänen kauttaan Herralta: \'Toivunko tästä taudista?\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Hasael meni häntä vastaan ja otti mukaansa lahjaksi kaikkea, mitä Damaskossa oli parasta, neljäkymmentä kamelinkuormaa. Hän tuli ja astui hänen eteensä ja sanoi: \"Poikasi Benhadad, Aramin kuningas, lähetti minut luoksesi ja käski kysyä: \'Toivunko tästä taudista?\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Elisa sanoi: \"Mene ja sano hänelle: \'Toivut.\' Mutta Herra on ilmoittanut minulle, että hänen on kuoltava.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Hän tuijotti eteensä kauan ja liikahtamatta, sitten Jumalan mies alkoi itkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Niin Hasael sanoi: \"Minkä tähden herrani itkee?\" Hän vastasi: \"Sen tähden, että tiedän, kuinka paljon pahaa olet tekevä israelilaisille: pistät heidän varustetut kaupunkinsa tuleen, surmaat miekalla heidän sankarinsa, murskaat heidän pienet lapsensa ja halkaiset heidän raskaana olevat vaimonsa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Hasael sanoi: \"Mikä on palvelijasi, tällainen koira, tekemään näitä suuria asioita?\" Elisa vastasi: \" Herra on ilmoittanut minulle, että sinusta on tuleva Aramin kuningas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Hän meni Elisan luota, ja kun hän tuli herransa luo, tämä kysyi häneltä: \"Mitä Elisa sanoi sinulle?\" Hän vastasi: \"Hän sanoi minulle, että toivut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Mutta seuraavana päivänä hän otti peitteen ja kastoi sen veteen ja levitti sen hänen kasvoilleen. Niin hän kuoli. Hasael tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'Israelin kuninkaan Jooramin, Ahabin pojan, viidentenä hallitusvuotena tuli Jooram, Juudan kuninkaan Joosafatin poika, kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Hän oli kolmenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kahdeksan vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Mutta hän vaelsi Israelin kuningasten tietä, niin kuin Ahabin suku oli tehnyt, sillä hänellä oli puolisona Ahabin tytär. Hän teki sitä, mikä on pahaa Herran silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Mutta palvelijansa Daavidin tähden Herra ei tahtonut tuhota Juudaa, koska hän oli luvannut antaa hänelle ja hänen pojilleen lampun ainiaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Hänen aikanaan edomilaiset luopuivat Juudan vallanalaisuudesta ja asettivat itselleen kuninkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Jooram lähti Saairiin kaikkine sotavaunuineen. Hän nousi yöllä ja voitti edomilaiset, jotka olivat saartaneet hänet, sekä sotavaunujen päälliköt. Mutta väki pakeni teltoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Edomilaiset luopuivat Juudan vallanalaisuudesta aina tähän päivään asti. Siihen aikaan luopui myös Libna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Mitä muuta on kerrottavaa Jooramista ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Sitten Jooram meni lepoon isiensä luo, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Hänen poikansa Ahasja tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Israelin kuninkaan Jooramin, Ahabin pojan, kahdentenatoista hallitusvuotena tuli kuninkaaksi Ahasja, Juudan kuninkaan Jooramin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Ahasja oli kahdenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa vuoden. Hänen äitinsä oli nimeltään Atalja, Israelin kuninkaan Omrin tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Ahasja vaelsi Ahabin suvun tietä ja teki sitä, mikä on pahaa Herran silmissä, samoin kuin Ahabin suku, sillä hän oli lankoutunut Ahabin suvun kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Hän lähti Jooramin, Ahabin pojan, kanssa sotimaan Hasaelia, Aramin kuningasta, vastaan Gileadin Raamotiin, mutta aramilaiset haavoittivat Jooramia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Niin kuningas Jooram tuli takaisin parantuakseen Jisreelissä haavoista, joita aramilaiset olivat iskeneet häneen Raamassa hänen taistellessaan Hasaelia, Aramin kuningasta, vastaan. Ahasja, Jooramin poika, Juudan kuningas, tuli Jisreeliin katsomaan Jooramia, Ahabin poikaa, koska tämä oli sairas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Profeetta Elisa kutsui erään profeetanoppilaan ja sanoi hänelle: \"Vyötä kupeesi ja ota tämä öljyastia mukaasi ja mene Gileadin Raamotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Tultuasi sinne hae sieltä käsiisi Jeehu, Joosafatin poika, Nimsin pojanpoika. Mene sisälle, käske hänen nousta toveriensa keskeltä ja vie hänet sisimpään huoneeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Ota sitten öljyastia, vuodata öljyä hänen päähänsä ja sano: \'Näin sanoo Herra: Olen voidellut sinut Israelin kuninkaaksi.\' Avaa sitten ovi ja pakene viivyttelemättä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Niin nuorukainen, profeetan palvelija, meni Gileadin Raamotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Kun hän tuli sinne, katso: sotaväen päälliköt istuivat siellä. Hän sanoi: \"Minulla on asiaa sinulle, päällikkö.\" Jeehu kysyi: \"Kenelle meistä kaikista?\" Hän vastasi: \"Sinulle itsellesi, päällikkö.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Silloin tämä nousi ja meni sisälle huoneeseen, ja hän vuodatti öljyä tämän päähän ja sanoi hänelle: \"Näin sanoo Herra, Israelin Jumala: Olen voidellut sinut Herran kansan, Israelin, kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Sinä olet surmaava herrasi Ahabin suvun, sillä kostan Iisebelille palvelijoitteni, profeettojen, veren ja kaikkien Herran palvelijoiden veren.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Koko Ahabin suku on tuhoutuva: hävitän Israelista Ahabin miespuoliset jälkeläiset, kaikki tyynni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Teen Ahabin suvulle saman, minkä Jerobeamin, Nebatin pojan, suvulle ja saman, minkä Baesan, Ahian pojan, suvulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Koirat syövät Iisebelin Jisreelin vainiolla, eikä kukaan ole hautaava häntä.\" Sitten hän avasi oven ja pakeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Kun Jeehu tuli ulos herransa palvelijoiden luo, häneltä kysyttiin: \"Onko kaikki hyvin? Miksi tuo hullu kävi luonasi?\" Hän vastasi heille: \"Tehän tunnette miehen ja hänen puheensa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Mutta he sanoivat: \"Valetta! Sano meille totuus.\" Hän sanoi: \"Niin ja niin hän puhui minulle ja sanoi: \'Näin sanoo Herra: Minä olen voidellut sinut Israelin kuninkaaksi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'He ottivat kiireen vilkkaa kukin vaatteensa ja panivat ne hänen alleen paljaille portaille, puhalsivat torveen ja huusivat: \"Jeehu on tullut kuninkaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Jeehu, Joosafatin poika, Nimsin pojanpoika, teki salaliiton Jooramia vastaan. Jooram oli ollut koko Israelin kanssa puolustamassa Gileadin Raamotia Hasaelia, Aramin kuningasta, vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Mutta kuningas Jooram oli tullut takaisin parantuakseen Jisreelissä haavoista, joita aramilaiset olivat iskeneet häneen hänen taistellessaan Hasaelia, Aramin kuningasta, vastaan. Jeehu sanoi: \"Jos se teille kelpaa, älkää päästäkö pakoon kaupungista ketään, joka menisi ilmoittamaan tätä Jisreeliin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Jeehu nousi vaunuihinsa ja lähti Jisreeliin, sillä Jooram makasi siellä, ja Ahasja, Juudan kuningas, oli tullut sinne katsomaan Jooramia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Mutta tähystäjä seisoi Jisreelin tornissa, ja kun hän näki Jeehun joukon tulevan, hän sanoi: \"Minä näen väkijoukon.\" Niin Jooram sanoi: \"Otettakoon ratsumies ja lähetettäköön heitä vastaan kysymään, onko kaikki hyvin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Ratsumies lähti häntä vastaan ja sanoi: \"Näin kysyy kuningas: \'Onko kaikki hyvin?\'\" Jeehu vastasi: \"Mitä se sinua liikuttaa, onko hyvin? Käänny ja seuraa minua.\" Niin tähystäjä ilmoitti sanoen: \"Sanansaattaja on tullut heidän luokseen, mutta ei palaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Hän lähetti toisen ratsumiehen. Kun tämä oli tullut heidän luokseen, hän sanoi: \"Näin kysyy kuningas: \'Onko kaikki hyvin?\'\" Jeehu vastasi: \"Mitä se sinua liikuttaa, onko hyvin? Käänny ja seuraa minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Tähystäjä ilmoitti sanoen: \"Hän on tullut heidän luokseen, mutta ei palaa, ja ajo on aivan kuin Jeehun, Nimsin pojan, ajoa. Sillä hän ajaa kuin hurjapää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Silloin Jooram sanoi: \"Valjastettakoon!\" He valjastivat hänen sotavaununsa. Jooram, Israelin kuningas, ja Ahasja, Juudan kuningas, lähtivät kumpikin sotavaunuissaan ja menivät Jeehua vastaan. He kohtasivat hänet jisreeliläisen Naabotin maapalstalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Kun Jooram näki Jeehun, hän kysyi: \"Onko kaikki hyvin, Jeehu?\" Tämä vastasi: \"Kuinka kaikki voisi olla hyvin, kun äitisi Iisebelin haureus ja hänen monet velhoutensa yhä vielä jatkuvat?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Silloin Jooram käänsi vaununsa ja pakeni, huutaen Ahasjalle: \"Kavallus, Ahasja!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Mutta Jeehu sieppasi jousen käteensä ja ampui Jooramia hartioiden väliin, niin että nuoli meni sydämen lävitse, ja hän vaipui vaunuihinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Hän sanoi Bidkarille, vaunusoturille: \"Ota hänet ja heitä jisreeliläisen Naabotin maapalstalle, sillä muistathan, että Herra meidän ratsastaessamme rinnakkain hänen isänsä Ahabin jäljessä lausui hänestä tämän ennustuksen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, '\'Totisesti, minä näin eilen Naabotin ja hänen poikiensa veren, sanoo Herra, ja minä olen juuri tällä maapalstalla kostava sinulle, sanoo Herra.\' Ota siis hänet ja heitä tälle maapalstalle, Herran sanan mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Kun Ahasja, Juudan kuningas, näki sen, hän pakeni Beet-Gaaniin päin. Mutta Jeehu ajoi häntä takaa ja sanoi: \"Ampukaa hänetkin vaunuihinsa.\" He ampuivat häntä Guurin solassa, joka on Jibleamin luona, mutta hän pakeni Megiddoon ja kuoli siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Hänen palvelijansa veivät hänet vaunuissa Jerusalemiin ja hautasivat hänet hänen omaan hautaansa, hänen isiensä viereen, Daavidin kaupunkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Ahasja oli tullut Juudan kuninkaaksi Jooramin, Ahabin pojan, yhdentenätoista hallitusvuotena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Jeehu tuli Jisreeliin. Kun Iisebel kuuli sen, hän maalasi ihomaalilla silmäluomensa, koristeli päänsä ja katseli ulos ikkunasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Kun Jeehu tuli portista sisään, Iisebel kysyi: \"Kävikö hyvin Simrille, herransa murhaajalle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Hän käänsi kasvonsa ikkunaa kohti ja sanoi: \"Kuka on minun puolellani? Kuka?\" Niin pari kolme hoviherraa katsoi alas häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Jeehu sanoi: \"Syöskää hänet alas.\" Niin he syöksivät hänet alas, niin että hänen vertaan roiskui seinään ja hevosiin, ja ne tallasivat hänet jalkoihinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Sitten Jeehu meni sisään, söi ja joi. Hän sanoi: \"Korjatkaa se kirottu ja haudatkaa hänet, sillä onhan hän kuninkaan tytär.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Mutta kun he menivät hautaamaan häntä, he eivät löytäneet hänestä muuta kuin pääkallon, jalat ja kädet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'He tulivat takaisin ja ilmoittivat sen Jeehulle. Hän sanoi: \"Tässä on toteutunut Herran sana, jonka hän puhui palvelijansa tisbeläisen Elian kautta: \'Jisreelin vainiolla koirat syövät Iisebelin lihan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'ja Iisebelin ruumis on oleva kuin pellon lantaa Jisreelin vainiolla, niin ettei voida sanoa: Tämä on Iisebel.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Mutta Ahabilla oli seitsemänkymmentä poikaa Samariassa. Jeehu kirjoitti kirjeet ja lähetti ne Samariaan, Jisreelin päämiehille, vanhimmille ja Ahabin poikien holhoojille. Hän kirjoitti näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, '\"Kun tämä kirje tulee teille, joiden hallussa herranne pojat ovat ja joiden hallussa ovat sotavaunut, hevoset, varustettu kaupunki ja aseet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'valitkaa herranne pojista paras ja oikeamielisin ja asettakaa hänet isänsä valtaistuimelle ja sotikaa herranne suvun puolesta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Mutta he pelästyivät kovin ja sanoivat: \"Katso, ne kaksi kuningasta eivät kestäneet hänen edessään, kuinka me kestäisimme?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Linnan päällikkö ja kaupungin päällikkö sekä vanhimmat ja holhoojat lähettivät Jeehulle sanan: \"Olemme palvelijoitasi. Teemme kaiken, mitä meille määräät. Emme tee ketään kuninkaaksi. Tee, mitä tahdot.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Hän kirjoitti heille toisen kirjeen, joka kuului näin: \"Jos te olette puolellani ja kuulette minua, ottakaa herranne poikien päät ja tulkaa huomenna tähän aikaan luokseni Jisreeliin.\" Ne seitsemänkymmentä kuninkaan poikaa asuivat näet kaupungin ylimysten luona, jotka kasvattivat heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Kun kirje tuli heille, he ottivat kuninkaan pojat ja tappoivat heidät, seitsemänkymmentä miestä, panivat heidän päänsä koreihin ja lähettivät ne Jeehulle Jisreeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Sanansaattaja tuli ja ilmoitti hänelle sanoen: \"He ovat tuoneet kuninkaan poikien päät.\" Hän sanoi: \"Pankaa ne kahteen kasaan portin oven edustalle huomiseen saakka.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Aamulla hän meni ulos, asettui siihen ja sanoi kaikelle kansalle: \"Te olette syyttömät. Katso, minä olen tehnyt salaliiton herraani vastaan ja tappanut hänet. Mutta kuka on surmannut nämä kaikki?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Tietäkää siis, ettei ainoakaan Herran sana, jonka Herra on puhunut Ahabin sukua vastaan, putoa maahan. Herra on tehnyt, minkä hän on puhunut palvelijansa Elian kautta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Jeehu surmasi kaikki, jotka olivat Ahabin suvusta jäljellä Jisreelissä, sekä kaikki hänen ylimyksensä, uskottunsa ja pappinsa päästämättä pakoon ainoatakaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Hän nousi ja lähti Samariaan. Mutta tullessaan paimenten Beet-Eekediin, joka on tien varrella,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Jeehu kohtasi Ahasjan, Juudan kuninkaan, veljet ja kysyi: \"Keitä te olette?\" He vastasivat: \"Me olemme Ahasjan veljiä ja menemme tervehtimään kuninkaan poikia ja kuninkaan äidin poikia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Hän sanoi: \"Ottakaa nämä elävinä kiinni.\" He ottivat heidät elävinä kiinni ja tappoivat heidät ja heittivät Beet-Eekedin vesisäiliöön, neljäkymmentä kaksi miestä. Hän ei jättänyt heistä ainoatakaan eloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Kun hän lähti sieltä, kohtasi hän Joonadabin, Reekabin pojan, joka tuli häntä vastaan. Hän tervehti häntä ja sanoi hänelle: \"Onko sydämesi yhtä vilpitön minua kohtaan, kuin sydämeni on sinua kohtaan?\" Joonadab vastasi: \"On.\" – \"Jos niin on, lyö kättä kanssani.\" Hän löi kättä, ja hän otti hänet vaunuihinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'Hän sanoi: \"Lähde kanssani katsomaan kiivailuani Herran puolesta.\" Ja hän ajoi hänen vaunuissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Tultuaan Samariaan hän surmasi kaikki, jotka olivat Ahabin jälkeläisistä jäljellä Samariassa, kunnes hän oli hävittänyt hänen sukunsa, Herran sanan mukaan, jonka Herra oli puhunut Elialle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Sitten Jeehu kokosi kaiken kansan ja sanoi heille: \"Ahab on palvellut Baalia vähän. Jeehu on palveleva häntä paljon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Kutsukaa nyt luokseni kaikki Baalin profeetat, kaikki hänen palvelijansa ja kaikki hänen pappinsa, älköönkä kukaan jääkö pois, sillä aion uhrata suuret uhrit Baalille. Eloon ei jää kukaan, joka jää pois.\" Mutta Jeehu menetteli kavalasti tuhotakseen Baalin palvelijat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Jeehu sanoi: \"Kuuluttakaa pyhä juhlakokous Baalin kunniaksi.\" Se kutsuttiin koolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Jeehu lähetti sanan kaikkeen Israeliin, ja kaikki Baalin palvelijat tulivat. Yksikään ei jäänyt tulematta. He menivät Baalin temppeliin, ja Baalin temppeli täyttyi ääriään myöten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Hän sanoi vaatekammion hoitajalle: \"Tuo puvut kaikille Baalin palvelijoille.\" Tämä toi heille puvut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Kun Jeehu Joonadabin, Reekabin pojan, kanssa tuli Baalin temppeliin, hän sanoi Baalin palvelijoille: \"Tutkikaa ja katsokaa, ettei täällä joukossanne ole ketään Herran palvelijaa, vaan ainoastaan Baalin palvelijoita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'He menivät uhraamaan teurasuhreja ja polttouhreja. Mutta Jeehu oli asettanut ulkopuolelle kahdeksankymmentä miestä ja sanonut: \"Jos kuka päästää pakoon yhdenkään niistä miehistä, jotka tuon teidän käsiinne, menee henki hengestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Päätettyään polttouhrin uhraamisen Jeehu sanoi henkivartijoille ja vaunusotureille: \"Menkää sisään ja surmatkaa heidät, älköön yksikään pääskö ulos.\" He surmasivat heidät miekan terällä, ja henkivartijat ja vaunusoturit heittivät heidän ruumiinsa ulos. Sitten he menivät Baalin temppelilinnaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'ja toivat ulos Baalin temppelin patsaat ja polttivat ne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'ja he kukistivat Baalin patsaan. He hävittivät Baalin temppelin ja tekivät siitä käymälöitä. Niin on aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Näin Jeehu hävitti Baalin Israelista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Mutta Jerobeamin, Nebatin pojan, synneistä, joilla hän oli saattanut Israelin tekemään syntiä, Beetelissä ja Daanissa olevista kultavasikoista, Jeehu ei luopunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Herra sanoi Jeehulle: \"Koska olet hyvin toimittanut sen, mikä oli oikein silmissäni, ja koska teit Ahabin suvulle aivan mieleni mukaan, niin istukoot poikasi Israelin valtaistuimella neljänteen polveen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Mutta Jeehu ei vaeltanut tarkasti, kaikesta sydämestään, Herran, Israelin Jumalan, lain mukaan. Hän ei luopunut Jerobeamin synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'Niihin aikoihin Herra rupesi lohkomaan Israelia, sillä Hasael voitti heidät kaikkialla Israelin raja-alueella');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'ja valloitti Jordanista auringonnousuun päin koko Gileadin maan, gaadilaiset, ruubenilaiset ja manasselaiset, alkaen Aroerista, joka on Arnon-joen rannalla – sekä Gileadin että Baasanin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Mitä muuta on kerrottavaa Jeehusta ja kaikesta, mitä hän teki, ja kaikista hänen urotöistään, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Jeehu meni lepoon isiensä luo, ja hänet haudattiin Samariaan. Hänen poikansa Jooahas tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Aika, jonka Jeehu hallitsi Israelia Samariassa, oli kaksikymmentä kahdeksan vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Kun Atalja, Ahasjan äiti, näki, että hänen poikansa oli kuollut, hän nousi ja tuhosi koko kuningassuvun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Mutta kuningas Jooramin tytär Jooseba, Ahasjan sisar, otti surmattavien kuninkaan poikien joukosta Ahasjan pojan Jooaan ja vei hänet ja hänen imettäjänsä salaa makuuhuoneeseen. Täällä pidettiin Jooasta kätkettynä Ataljalta, niin ettei hän tullut surmatuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Sitten poika oli Jooseban luona Herran temppeliin piilotettuna kuusi vuotta Ataljan hallitessa maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Mutta seitsemäntenä vuotena Joojada lähetti hakemaan kaarilaisten ja henkivartijoiden sadanpäämiehiä ja tuotti heidät luokseen Herran temppeliin. Kun hän oli tehnyt liiton heidän kanssaan ja vannottanut heidät siellä Herran temppelissä, hän näytti heille kuninkaan pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Hän käski heitä sanoen: \"Tehkää näin: kolmas osa teistä, joiden on mentävä vartioon sapattina, vartioikoon kuninkaan palatsia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'kolmas osa olkoon sivuportilla ja kolmas osa henkivartijoiden takana olevalla portilla. Vartioikaa kukin vuorollanne palatsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Mutta kaksi muuta teidän osastoanne, kaikki, jotka pääsevät vartionpidosta sapattina, vartioikoot Herran temppeliä kuninkaan luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Asettukaa kuninkaan ympärille, kullakin ase kädessä. Joka tunkeutuu rivien läpi, surmattakoon. Näin olkaa kuninkaan luona, menköön hän ulos tai sisään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Sadanpäämiehet tekivät, aivan kuten pappi Joojada oli heitä käskenyt: kukin heistä otti miehensä, sekä ne, joiden oli mentävä vartioon sapattina, että ne, jotka pääsivät vartiosta sapattina, ja he tulivat pappi Joojadan luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Pappi antoi sadanpäämiehille keihäät ja varustukset, jotka olivat olleet kuningas Daavidin omat ja olivat Herran temppelissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Henkivartijat asettuivat, kullakin ase kädessä, temppelin eteläsivulta aina sen pohjoissivulle saakka, päin alttaria ja temppeliä, kuninkaan ympärille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Sitten hän toi kuninkaan pojan esille, pani hänen päähänsä kruunun ja antoi hänelle lain kirjan, ja he tekivät hänet kuninkaaksi, voitelivat hänet, paukuttivat käsiään ja huusivat: \"Eläköön kuningas!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Kun Atalja kuuli henkivartijoiden ja kansan huudon, hän meni kansan luo Herran temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Hän näki kuninkaan seisovan pylvään vieressä, kuten tapana oli, ja päälliköt ja torvensoittajat kuninkaan luona, ja kaiken maan kansan, joka riemuitsi ja puhalsi torviin. Atalja repäisi vaatteensa ja huusi: \"Kapina! Kapina!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Mutta pappi Joojada käski sadanpäämiehiä, sotajoukon johtajia, ja sanoi heille: \"Viekää hänet pois rivien välitse, ja se, joka yrittää seurata häntä, surmatkaa miekalla.\" Sillä pappi oli sanonut: \"Älköön häntä surmattako Herran temppelissä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'He kävivät häneen käsiksi, ja kun hän oli tullut tielle, jota myöten hevosia kuljetettiin kuninkaan palatsiin, surmattiin hänet palatsissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Joojada teki liiton Herran, kuninkaan ja kansan kanssa, että he olisivat Herran kansa, niin myös [liiton] kuninkaan ja kansan kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Koko maan kansa meni Baalin temppeliin, ja he hävittivät sen. Sen alttarit ja kuvat he löivät aivan murskaksi ja tappoivat alttarien edessä Mattanin, Baalin papin. Sitten pappi asetti vartijat vartioimaan Herran temppeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Hän otti mukaansa sadanpäämiehet sekä kaarilaiset, henkivartijat ja kaiken maan kansan, ja he veivät kuninkaan Herran temppelistä ja tulivat henkivartijoiden portin kautta kuninkaan linnaan, ja hän istui kuninkaalliselle valtaistuimelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Kaikki maan kansa iloitsi, ja kaupunki pysyi rauhallisena. Mutta Ataljan he olivat surmanneet miekalla kuninkaan linnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Jooas oli seitsemän vuoden vanha tullessaan kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Jeehun seitsemäntenä hallitusvuotena tuli Jooas kuninkaaksi, ja hän hallitsi Jerusalemissa neljäkymmentä vuotta. Hänen äitinsä oli nimeltään Sibja Beersebasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Jooas teki sitä, mikä on oikein Herran silmissä, niin kauan kuin hän eli, sillä pappi Joojada oli opettanut häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Kuitenkaan uhrikukkulat eivät hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Jooas sanoi papeille: \"Kaiken rahan, joka pyhinä lahjoina tuodaan Herran temppeliin, käyvän rahan, kaiken arvion mukaan suoritettavan henkilörahan ja kaiken rahan, jonka joku sydämensä vaatimuksesta tuo Herran temppeliin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'papit ottakoot itselleen, kukin tuttavaltaan. Mutta heidän on niillä korjattava, mitä on rappeutunutta Herran temppelissä, missä vain on jotakin rappeutunutta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Mutta vielä kuningas Jooaan kahdentenakymmenentenä kolmantena hallitusvuotena papit eivät olleet korjanneet mitään, mikä temppelissä oli rappeutunutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Kuningas Jooas kutsui pappi Joojadan ja muut papit ja sanoi heille: \"Miksi te ette ole korjanneet mitään, mikä temppelissä on rappeutunutta? Nyt te ette enää saa ottaa rahaa tuttaviltanne, vaan teidän on annettava se siihen, mikä temppelissä on rappeutunutta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Papit suostuivat siihen, etteivät ota rahaa kansalta paitsi korjatakseen sitä, mikä temppelissä oli rappeutunutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Pappi Joojada otti arkun ja kaivoi reiän sen kanteen ja asetti sen alttarin ääreen, oikealle puolelle, kun mennään Herran temppeliin. Papit, jotka vartioivat ovea, panivat siihen kaiken rahan, mikä tuotiin Herran temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Kun he näkivät, että arkussa oli paljon rahaa, meni kuninkaan kirjuri sinne ylimmäisen papin kanssa. He panivat rahat säkkeihin ja laskivat rahat, jotka olivat Herran temppelissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'Sitten punnitut rahat annettiin työnteettäjille, jotka oli pantu valvomaan töitä Herran temppelissä. He maksoivat niillä puusepät ja rakentajat, jotka tekivät työtä Herran temppelissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'sekä muurarit ja kivenhakkaajat, myös puutavarat ja hakatut kivet, jotka oli ostettava sen korjaamiseksi, mikä Herran temppelissä oli rappeutunutta, kaikki temppelin korjausmenot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Kuitenkaan Herran temppeliin ei teetetty hopeavateja, veitsiä, maljoja, torvia eikä mitään kulta- tai hopeaesineitä sillä rahalla, joka tuotiin Herran temppeliin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'vaan se annettiin työmiehille, että he sillä korjaisivat Herran temppeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Miehiltä, joille rahat luovutettiin työmiehille annettaviksi, ei vaadittu tilintekoa, vaan he toimivat luottamusmiehinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Vikauhri- ja syntiuhrirahoja ei tuotu Herran temppeliin. Ne tulivat papeille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Siihen aikaan Hasael, Aramin kuningas, tuli ja ryhtyi sotimaan Gatia vastaan ja valloitti sen. Sitten Hasael kävi hyökkäämään Jerusalemia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Jooas, Juudan kuningas, otti kaikki pyhät lahjat, jotka hänen isänsä, Juudan kuninkaat Joosafat, Jooram ja Ahasja, olivat pyhittäneet, ja omat pyhät lahjansa sekä kaiken kullan, mitä oli Herran temppelin aarrekammioissa ja kuninkaan linnassa, ja lähetti ne Hasaelille, Aramin kuninkaalle. Tämä lähti pois Jerusalemin kimpusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Mitä muuta on kerrottavaa Jooaasta ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Mutta hänen palvelijansa nousivat ja tekivät salaliiton ja surmasivat Jooaan Millossa olevassa rakennuksessa, siinä, mistä mennään alas Sillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 22, 'Hänen palvelijansa Joosakar, Simeatin poika, ja Joosabad, Soomerin poika, löivät hänet kuoliaaksi, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Hänen poikansa Amasja tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Juudan kuninkaan Jooaan, Ahasjan pojan, kahdentenakymmenentenä kolmantena hallitusvuotena tuli Jooahas, Jeehun poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa seitsemäntoista vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Hän teki sitä, mikä on pahaa Herran silmissä, ja vaelsi Jerobeamin, Nebatin pojan, synneissä, joilla tämä oli saattanut Israelin tekemään syntiä. Hän ei luopunut niistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Herran viha syttyi Israelia kohtaan, ja hän antoi heidät Hasaelin, Aramin kuninkaan, ja Benhadadin, Hasaelin pojan, käsiin koko siksi ajaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Mutta Jooahas lepytti Herraa, ja Herra kuuli häntä, sillä hän näki Israelin sorron, kun Aramin kuningas sorti heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Herra antoi Israelille vapauttajan, ja he pääsivät aramilaisten käsistä. Israelilaiset asuivat teltoissaan kuten ennenkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'He eivät kuitenkaan luopuneet Jerobeamin suvun synneistä, joilla hän oli saattanut Israelin tekemään syntiä, vaan he vaelsivat niissä. Aserakin jäi paikoilleen Samariaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Herra ei jättänyt Jooahaalle väkeä enempää kuin viisikymmentä ratsumiestä, kymmenen sotavaunua ja kymmenentuhatta jalkamiestä. Sillä Aramin kuningas oli hävittänyt ne ja pannut ne tomuksi, niin kuin puitaessa pölyää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Mitä muuta on kerrottavaa Jooahaasta, kaikesta, mitä hän teki, ja hänen urotöistään, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Sitten Jooahas meni lepoon isiensä luo, ja hänet haudattiin Samariaan. Hänen poikansa Jooas tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Juudan kuninkaan Jooaan kolmantenakymmenentenä seitsemäntenä hallitusvuotena tuli Jooas, Jooahaan poika, Israelin kuninkaaksi. Hän hallitsi Samariassa kuusitoista vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Hän teki sitä, mikä on pahaa Herran silmissä. Hän ei luopunut mistään Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä, vaan vaelsi niissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Mitä muuta on kerrottavaa Jooaasta, kaikesta, mitä hän teki, ja hänen urotöistään, kuinka hän soti Juudan kuningasta Amasjaa vastaan, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Jooas meni lepoon isiensä luo, ja Jerobeam istui hänen valtaistuimelleen. Jooas haudattiin Samariaan Israelin kuningasten viereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Kun Elisa oli sairastanut kuolintautiaan, Jooas, Israelin kuningas, oli tullut hänen luokseen. Kumartuneena hänen kasvojensa yli hän oli itkenyt ja sanonut: \"Isäni, isäni! Israelin sotavaunut ja ratsumiehet!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Elisa oli sanonut hänelle: \"Nouda jousi ja nuolia.\" Hän oli noutanut hänelle jousen ja nuolia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Sitten hän oli sanonut Israelin kuninkaalle: \"Laske kätesi jouselle.\" Kun hän oli laskenut kätensä, Elisa pani kätensä kuninkaan kätten päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'Hän sanoi: \"Avaa ikkuna itään päin.\" Kun tämä oli avannut sen, Elisa sanoi: \"Ammu.\" Niin hän ampui. Hän sanoi: \" Herran voitonnuoli, voitonnuoli Aramia vastaan! Sinä olet voittava aramilaiset Afekissa perin pohjin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Ja hän sanoi: \"Ota nuolet.\" Kun hän oli ne ottanut, hän sanoi Israelin kuninkaalle: \"Tao [niitä] maahan.\" Niin hän löi kolme kertaa ja lakkasi sitten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Mutta Jumalan mies vihastui häneen ja sanoi: \"Sinun olisi pitänyt lyödä viisi tai kuusi kertaa: silloin olisit voittanut aramilaiset perin pohjin. Mutta nyt olet voittava aramilaiset ainoastaan kolme kertaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Elisa kuoli, ja hänet haudattiin. Mooabilaisten partiojoukkoja tuli maahan vuosi vuodelta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Kerran, kun he haudatessaan erästä miestä näkivät partiojoukon, he heittivät miehen Elisan hautaan ja menivät matkoihinsa. Kun mies kosketti Elisan luita, hän virkosi ja nousi jaloilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Hasael, Aramin kuningas, sorti Israelia, niin kauan kuin Jooahas eli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Mutta Herra oli heille laupias, armahti heitä ja kääntyi heidän puoleensa liiton tähden, jonka hän oli tehnyt Aabrahamin, Iisakin ja Jaakobin kanssa. Sillä hän ei tahtonut tuhota heitä, eikä hän ollut vielä heittänyt heitä pois kasvojensa edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Hasael, Aramin kuningas, kuoli, ja hänen poikansa Benhadad tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Jooas, Jooahaan poika, otti Benhadadilta, Hasaelin pojalta, takaisin ne kaupungit, jotka tämä oli asevoimin ottanut hänen isältään Jooahaalta. Kolme kertaa Jooas voitti hänet ja otti takaisin Israelin kaupungit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'Israelin kuninkaan Jooaan, Jooahaan pojan, toisena hallitusvuotena tuli Amasja, Jooaan poika, Juudan kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Hän oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kaksikymmentä yhdeksän vuotta. Hänen äitinsä oli nimeltään Jooaddin Jerusalemista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Hän teki sitä, mikä on oikein Herran silmissä, ei kuitenkaan niin kuin hänen isänsä Daavid. Kaikessa hän teki, niin kuin hänen isänsä Jooas oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Kuitenkaan eivät uhrikukkulat hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Kun kuninkuus oli vahvistunut hänen käsissään, hän surmautti ne palvelijansa, jotka olivat murhanneet kuninkaan, hänen isänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Mutta murhaajien lapset hän jätti surmaamatta, kuten on kirjoitettu Mooseksen lain kirjaan, jossa Herra on käskenyt: \"Älköön isiä rangaistako kuolemalla lasten tähden älköönkä lapsia isien tähden. Kukin rangaistakoon kuolemalla oman syntinsä tähden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Hän voitti edomilaiset Suolalaaksossa, kymmenentuhatta miestä, ja valloitti Seelan asevoimin ja antoi sille nimen Jokteel, joka sillä on tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Silloin Amasja lähetti sanansaattajat Israelin kuninkaan Jooaan, Jooahaan pojan, Jeehun pojanpojan luo ja käski sanoa hänelle: \"Tule, otelkaamme keskenämme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Mutta Jooas, Israelin kuningas, lähetti Amasjalle, Juudan kuninkaalle tämän sanan: \"Libanonilla kasvava ohdake lähetti setripuulle, joka kasvoi Libanonilla, sanan: \'Anna tyttäresi vaimoksi pojalleni.\' Mutta metsän eläimet Libanonilla kulkivat ohdakkeen ylitse ja tallasivat sen maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Sinä olet voittanut Edomin, ja siitä olet käynyt ylpeäksi. Tyydy siihen kunniaan ja pysy kotonasi. Minkä tähden tuotat onnettomuuden? Sinä kukistut itse ja Juuda kanssasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Mutta Amasja ei totellut. Niin Jooas, Israelin kuningas, lähti liikkeelle, ja he, hän ja Amasja, Juudan kuningas, ottelivat keskenään Beet-Semeksessä, joka on Juudan aluetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Israelilaiset voittivat Juudan miehet, ja nämä pakenivat kukin teltalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Jooas, Israelin kuningas, otti Juudan kuninkaan Amasjan, Jooaan pojan, Ahasjan pojanpojan, Beet-Semeksessä vangiksi. Kun hän tuli Jerusalemiin, hän revitti Jerusalemin muuria Efraimin portista Kulmaporttiin saakka, neljäsataa kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Hän otti kaiken kullan ja hopean sekä kaiken esineistön, mitä Herran temppelissä ja kuninkaan linnan aarrekammioissa oli, sekä panttivankeja, ja palasi Samariaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Mitä muuta on kerrottavaa Jooaasta, siitä, mitä hän teki, ja hänen urotöistään, kuinka hän soti Amasjaa, Juudan kuningasta, vastaan, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Jooas meni lepoon isiensä luo, ja hänet haudattiin Samariaan Israelin kuningasten viereen. Hänen poikansa Jerobeam tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Mutta Juudan kuningas Amasja, Jooaan poika, eli Israelin kuninkaan Jooaan, Jooahaan pojan, kuoleman jälkeen viisitoista vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Mitä muuta on kerrottavaa Amasjasta, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Häntä vastaan tehtiin Jerusalemissa salaliitto. Hän pakeni Laakiiseen, mutta Laakiiseen lähetettiin miehiä hänen jälkeensä, ja he surmasivat hänet siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Hänet nostettiin hevosten selkään ja haudattiin Jerusalemiin isiensä viereen Daavidin kaupunkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Mutta koko Juudan kansa otti Asarjan, joka oli kuudentoista vuoden vanha, ja teki hänet kuninkaaksi hänen isänsä Amasjan sijaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Hän linnoitti Eilatin ja palautti sen Juudalle, sitten kun kuningas oli mennyt lepoon isiensä luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'Juudan kuninkaan Amasjan, Jooaan pojan, viidentenätoista hallitusvuotena tuli Jerobeam, Jooaan poika, Israelin kuninkaaksi ja hallitsi Samariassa neljäkymmentä yksi vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Hän teki sitä, mikä on pahaa Herran silmissä, hän ei luopunut mistään Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Hän palautti entiselleen Israelin alueen, siitä, mistä mennään Hamatiin, aina Aromaan mereen saakka, sen sanan mukaan, jonka Herra, Israelin Jumala, oli puhunut palvelijansa, profeetta Joonan, Amittain pojan, kautta, joka oli kotoisin Gat-Heeferistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Sillä Herra oli nähnyt Israelin hyvin katkeran kurjuuden, kuinka kaikki tyynni menehtyivät eikä Israelilla ollut auttajaa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Silloin Herra ei ollut vielä sanonut, että hän pyyhkii Israelin nimen pois taivaan alta, ja niin hän vapautti heidät Jerobeamin, Jooaan pojan, kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Mitä muuta on kerrottavaa Jerobeamista, kaikesta, mitä hän teki, ja hänen urotöistään, kuinka hän kävi sotaa ja kuinka hän palautti Israelille Damaskosta ja Hamatista sen, mikä oli ollut Juudan. Se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Jerobeam meni lepoon isiensä, Israelin kuningasten, luo. Hänen poikansa Sakarja tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Jerobeamin, Israelin kuninkaan, kahdentenakymmenentenä seitsemäntenä hallitusvuotena tuli Asarja, Amasjan poika, Juudan kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Hän oli kuudentoista vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa viisikymmentä kaksi vuotta. Hänen äitinsä oli nimeltään Jekolja Jerusalemista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Hän teki sitä, mikä on oikein Herran silmissä, aivan kuten hänen isänsä Amasja oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Kuitenkaan eivät uhrikukkulat hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Herra löi kuningasta, niin että hän oli spitaalinen kuolinpäiväänsä saakka. Hän asui eri talossa, mutta Jootam, kuninkaan poika, oli linnan päällikkönä ja jakoi oikeutta maan kansalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Mitä muuta on kerrottavaa Asarjasta ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Asarja meni lepoon isiensä luo, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Hänen poikansa Jootam tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Asarjan, Juudan kuninkaan, kolmantenakymmenentenä kahdeksantena hallitusvuotena tuli Sakarja, Jerobeamin poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa kuusi kuukautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Hän teki sitä, mikä on pahaa Herran silmissä, kuten hänen isänsäkin olivat tehneet. Hän ei luopunut Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Sallum, Jaabeksen poika, teki salaliiton häntä vastaan ja löi hänet kuoliaaksi kansan nähden ja tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Mitä muuta on kerrottavaa Sakarjasta, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Näin toteutui Herran sana, jonka hän oli puhunut Jeehulle sanoen: \"Sinun poikasi istukoot Israelin valtaistuimella neljänteen polveen\". Niin tapahtui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Sallum, Jaabeksen poika, tuli kuninkaaksi Ussian, Juudan kuninkaan, kolmantenakymmenentenä yhdeksäntenä hallitusvuotena, ja hän hallitsi Samariassa kuukauden päivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Mutta silloin Menahem, Gaadin poika, lähti liikkeelle Tirsasta, tuli Samariaan ja löi Sallumin, Jaabeksen pojan, kuoliaaksi Samariassa. Hän tuli kuninkaaksi tämän jälkeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Mitä muuta on kerrottavaa Sallumista ja salaliitosta, jonka hän teki, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Siihen aikaan Menahem hävitti Tifsahin ja kaiken, mitä siellä oli, niin myös sen alueen Tirsasta lähtien, koska he eivät avanneet hänelle portteja. Hän hävitti sen ja halkaisi kaikki raskaana olevat vaimot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Juudan kuninkaan Asarjan kolmantenakymmenentenä yhdeksäntenä hallitusvuotena tuli Menahem, Gaadin poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa kymmenen vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Hän teki sitä, mikä on pahaa Herran edessä. Hän ei luopunut koko elinaikanaan mistään Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Puul, Assurin kuningas, hyökkäsi maahan, ja Menahem antoi Puulille tuhat talenttia hopeaa, että tämä auttaisi häntä ja vahvistaisi kuninkuuden hänen käsiinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Menahem otti rahat verona Israelilta, kaikilta varakkailta miehiltä, niin että jokainen joutui maksamaan Assurin kuninkaalle viisikymmentä sekeliä hopeaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Assurin kuningas palasi takaisin eikä jäänyt maahan. Mitä muuta on kerrottavaa Menahemista ja kaikesta, mitä hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Menahem meni lepoon isiensä luo. Hänen poikansa Pekahja tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'Juudan kuninkaan Asarjan viidentenäkymmenentenä hallitusvuotena tuli Pekahja, Menahemin poika, Israelin kuninkaaksi ja hallitsi Samariassa kaksi vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Hän teki sitä, mikä on pahaa Herran silmissä. Hän ei luopunut Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Pekah, Remaljan poika, hänen vaunusoturinsa, teki salaliiton häntä vastaan ja tappoi hänet Samariassa kuninkaan linnan palatsissa, sekä hänet että Argobin ja Arjen, jolloin Pekahilla oli mukanaan viisikymmentä Gileadin miestä. Hän surmasi hänet ja tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Mitä muuta on kerrottavaa Pekahjasta ja kaikesta, mitä hän teki, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'Juudan kuninkaan Asarjan viidentenäkymmenentenä toisena hallitusvuotena tuli Pekah, Remaljan poika, Israelin kuninkaaksi ja hallitsi Samariassa kaksikymmentä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Hän teki sitä, mikä on pahaa Herran silmissä. Hän ei luopunut Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Israelin kuninkaan Pekahin aikana tuli Tiglat-Pileser, Assurin kuningas, ja valloitti Iijonin, Aabel-Beet-Maakan, Jaanoahin, Kedeksen, Haasorin, Gileadin ja Galilean, koko Naftalin maan, ja vei asukkaat karkotukseen Assuriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Mutta Hoosea, Eelan poika, teki salaliiton Pekahia, Remaljan poikaa, vastaan ja löi hänet kuoliaaksi ja tuli kuninkaaksi hänen jälkeensä Jootamin, Ussian pojan, kahdentenakymmenentenä hallitusvuotena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Mitä muuta on kerrottavaa Pekahista ja kaikesta, mitä hän teki, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Israelin kuninkaan Pekahin, Remaljan pojan, toisena hallitusvuotena tuli Jootam, Juudan kuninkaan Ussian poika, kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Hän oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa kuusitoista vuotta. Hänen äitinsä oli nimeltään Jerusa Saadokin tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Hän teki sitä, mikä on oikein Herran silmissä, aivan niin kuin hänen isänsä Ussia oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Kuitenkaan uhrikukkulat eivät hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla. Hän rakennutti Yläportin Herran temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Mitä muuta on kerrottavaa Jootamista ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'Niihin aikoihin alkoivat Resin, Aramin kuningas, ja Pekah, Remaljan poika, Herran lähettäminä käydä Juudan kimppuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Jootam meni lepoon isiensä luo, ja hänet haudattiin isiensä viereen, isänsä Daavidin kaupunkiin. Hänen poikansa Aahas tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 39, '');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Pekahin, Remaljan pojan, seitsemäntenätoista hallitusvuotena tuli Aahas, Juudan kuninkaan Jootamin poika, kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Aahas oli kahdenkymmenen vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa kuusitoista vuotta. Hän ei tehnyt sitä, mikä oli oikein Herran, hänen Jumalansa, silmissä, kuten hänen isänsä Daavid,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'vaan vaelsi Israelin kuningasten tietä. Jopa hän pani poikansakin kulkemaan tulen läpi, niiden kansojen kauhistavien tekojen mukaan, jotka Herra oli karkottanut israelilaisten tieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Hän uhrasi ja suitsutti uhrikukkuloilla ja kummuilla ja jokaisen vihreän puun alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Siihen aikaan Resin, Aramin kuningas, ja Pekah, Remaljan poika, Israelin kuningas, lähtivät sotimaan Jerusalemia vastaan. He saartoivat Aahaan, mutta eivät voineet valloittaa kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'Samaan aikaan Resin, Aramin kuningas, palautti Eilatin Aramille ja karkotti Juudan miehet Eilatista. Niin tulivat aramilaiset Eilatiin ja asettuivat sinne, ja siellä heitä on tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Mutta Aahas lähetti sanansaattajat Assurin kuninkaan Tiglat-Pileserin luo ja käski sanoa hänelle: \"Minä olen palvelijasi ja poikasi. Tule ja pelasta minut Aramin kuninkaan ja Israelin kuninkaan käsistä. He ovat hyökänneet kimppuuni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Aahas otti hopean ja kullan, mitä Herran temppelissä ja kuninkaan palatsin aarrekammioissa oli, ja lähetti sen lahjaksi Assurin kuninkaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Assurin kuningas kuuli häntä. Assurin kuningas lähti Damaskoa vastaan, valloitti sen, ja vei asukkaat karkotukseen Kiiriin ja surmasi Resinin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Kuningas Aahas lähti Damaskoon kohtaamaan Assurin kuningasta Tiglat-Pileseriä. Kun kuningas Aahas näki Damaskossa olevan alttarin, hän lähetti pappi Uurialle kuvan alttarista ja sen mukaan tehdyn tarkan mallin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Pappi Uuria rakensi alttarin aivan sen määräyksen mukaan, jonka kuningas Aahas oli hänelle lähettänyt Damaskosta. Aivan sen mukaan pappi Uuria teki, jo ennen kuin kuningas Aahas oli palannut Damaskosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Kun kuningas palasi Damaskosta ja näki alttarin, hän astui alttarin luo ja nousi sen päälle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'poltti polttouhrinsa ja ruokauhrinsa, vuodatti juomauhrinsa ja vihmoi uhraamansa uhrin veren alttarille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Mutta vaskialttarin, joka oli Herran edessä, hän siirsi pois temppelin edustalta, alttarin ja Herran temppelin väliltä, ja pani sen alttarin pohjoissivulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Kuningas Aahas käski pappi Uuriaa ja sanoi: \"Polta suuremmalla alttarilla aamun polttouhri ja ehtoon ruokauhri ja kuninkaan polttouhri sekä hänen ruokauhrinsa, niin myös koko maan kansan polttouhri sekä heidän ruoka- ja juomauhrinsa, ja vihmo kaikki sekä polttouhrin että teurasuhrin veri sen päälle. Mutta vaskialttarin käyttämistä minä vielä mietin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Pappi Uuria teki kaiken, mitä kuningas Aahas oli käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Kuningas Aahas leikkautti irti telineiden kehäpienat ja otti altaat pois niiden päältä. Mutta meren hän nostatti pois vaskinautojen päältä, jotka olivat sen alla, ja panetti sen kivialustalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Katetun sapattikäytävän, joka oli rakennettu temppeliin, ja kuninkaan ulkopuolisen sisäänkäynnin hän muutti Herran temppelin sisään Assurin kuninkaan vuoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Mitä muuta on vielä kerrottavaa Aahaasta, siitä, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Aahas meni lepoon isiensä luo, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Sitten hänen poikansa Hiskia tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Juudan kuninkaan Aahaan kahdentenatoista hallitusvuotena tuli Hoosea, Eelan poika, Israelin kuninkaaksi Samariaan ja hallitsi yhdeksän vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Hän teki sitä, mikä on pahaa Herran silmissä, ei kuitenkaan niin kuin ne Israelin kuninkaat, jotka olivat olleet ennen häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Hänen kimppuunsa hyökkäsi Salmaneser, Assurin kuningas, ja Hoosea tuli hänen palvelijakseen ja maksoi hänelle veroa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Mutta Assurin kuningas huomasi Hoosean olevan salahankkeissa, koska tämä lähetti sanansaattajat Soon, Egyptin kuninkaan, luo eikä suorittanut enää kuten ennen vuotuista veroa Assurin kuninkaalle. Niin Assurin kuningas vangitutti hänet ja piti häntä sidottuna vankilassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Assurin kuningas hyökkäsi koko maan kimppuun ja meni Samariaan ja piiritti sitä kolme vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Hoosean yhdeksäntenä hallitusvuotena Assurin kuningas valloitti Samarian ja vei Israelin karkotukseen Assuriin ja asetti heidät asumaan Halahiin ja Haaborin, Goosanin joen, rannoille sekä Meedian kaupunkeihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Näin tapahtui, koska israelilaiset olivat tehneet syntiä Herraa, Jumalaansa, vastaan, joka oli johdattanut heidät Egyptin maasta, pois faraon, Egyptin kuninkaan, käsistä, ja koska he olivat pelänneet muita jumalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'He olivat myös vaeltaneet niiden kansojen säädösten mukaan, jotka Herra oli karkottanut israelilaisten tieltä, ja tehneet sitä, mitä Israelin kuninkaatkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Israelilaiset olivat tehneet Herraa, Jumalaansa, vastaan sellaista, mikä ei ole oikein: he olivat rakentaneet itselleen uhrikukkuloita kaikkiin kaupunkeihinsa, sekä vartiotornien luo että varustettuihin kaupunkeihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'He olivat pystyttäneet itselleen patsaita ja aserapaaluja jokaiselle korkealle kummulle ja jokaisen vihreän puun alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'He olivat polttaneet uhreja kaikilla uhrikukkuloilla, kuten ne kansat, jotka Herra oli karkottanut heidän tieltään. He olivat harjoittaneet pahuutta ja vihoittaneet Herran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'He olivat palvelleet epäjumalia, vaikka Herra oli heille sanonut: \"Älkää tehkö sitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Herra oli varoittanut sekä Israelia että Juudaa kaikkien profeettojensa, kaikkien näkijöiden, kautta ja sanonut: \"Palatkaa pahoilta teiltänne ja noudattakaa käskyjäni ja säädöksiäni, kaiken sen lain mukaan, jonka minä säädin isillenne ja jonka olen teille ilmoittanut palvelijoitteni, profeettojen, kautta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Mutta he eivät kuulleet, vaan olivat niskureita niin kuin heidän isänsäkin, jotka eivät uskoneet Herraan, Jumalaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'He olivat hylänneet hänen käskynsä ja hänen liittonsa, jonka hän oli tehnyt heidän isiensä kanssa, ja todistukset, jotka hän oli heille antanut. He olivat seuranneet turhia jumalia, ja tulleet turhanaikaisiksi, kun seurasivat pakanakansoja, jotka asuivat heidän ympärillään, vaikka Herra oli kieltänyt heitä tekemästä niin kuin ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'He olivat hylänneet Herran, Jumalansa, kaikki käskyt ja tehneet itselleen valettuja kuvia, kaksi vasikkaa. He olivat tehneet itselleen myös aserapaaluja ja kumarsivat kaikkea taivaan joukkoa ja palvelivat Baalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'He panivat poikansa ja tyttärensä kulkemaan tulen läpi ja tekivät taikoja ja harjoittivat noituutta. He myivät itsensä tekemään sitä, mikä on pahaa Herran silmissä, ja vihoittivat hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Herra vihastui suuresti Israeliin ja poisti heidät kasvojensa edestä, ettei jäänyt jäljelle muuta kuin yksin Juudan sukukunta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Juudakaan ei pitänyt Herran, Jumalansa, käskyjä, vaan he vaelsivat niiden säädösten mukaan, jotka Israel itse oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Herra hylkäsi koko Israelin heimon, nöyryytti heitä ja antoi heidät ryöstäjien käsiin ja heitti viimein heidät pois kasvojensa edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Sillä kun hän oli reväissyt Israelin Daavidin suvulta ja he olivat tehneet kuninkaaksi Jerobeamin, Nebatin pojan, Jerobeam oli kääntänyt Israelin pois Herrasta ja saattanut heidät tekemään suuren synnin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Israelilaiset vaelsivat kaikissa synneissä, joita Jerobeam oli tehnyt, eivätkä luopuneet niistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'Herra poisti lopulta Israelin kasvojensa edestä, niin kuin hän oli puhunut kaikkien palvelijoidensa, profeettojen, kautta. Israel vietiin pois maastaan karkotukseen Assuriin, jossa he ovat tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Sen jälkeen Assurin kuningas antoi tuoda kansaa Baabelista, Kuutasta, Avvasta, Hamatista ja Sefarvaimista ja asetti heidät asumaan Samarian kaupunkeihin israelilaisten sijaan. He ottivat Samarian omakseen ja asettuivat sen kaupunkeihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Kun he siellä olonsa ensi aikoina eivät pelänneet Herraa, lähetti Herra heidän keskuuteensa leijonia, jotka tappoivat heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Se kerrottiin Assurin kuninkaalle sanoen: \"Kansat, jotka veit karkotukseen ja asetit asumaan Samarian kaupunkeihin, eivät tiedä, millä tavalla sen maan Jumalaa on palveltava. Sen tähden hän on lähettänyt leijonia heidän keskuuteensa, ja katso, ne surmaavat heitä, koska he eivät tiedä, millä tavalla sen maan Jumalaa on palveltava.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Silloin Assurin kuningas käski sanoen: \"Viekää sinne joku niistä papeista, jotka toitte sieltä karkotukseen. Joku heistä menköön sinne ja asukoon siellä ja opettakoon heille, millä tavalla maan Jumalaa on palveltava.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Niin eräs niistä papeista, jotka he olivat vieneet Samariasta karkotukseen, tuli ja asettui Beeteliin. Hän opetti heille, kuinka heidän oli pelättävä Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Mutta jokainen kansa teki itselleen omat jumalansa, ja he panivat ne samarialaisten rakentamiin uhrikukkulatemppeleihin, jokainen kansa niissä kaupungeissa, joissa se asui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Baabelin miehet tekivät itselleen Sukkot-Benotin, Kuutin miehet tekivät Neergalin, Hamatin miehet Asiman,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'avvalaiset tekivät Nibhaan ja Tartakin, sefarvaimilaiset polttivat poikiaan tulessa Adrammelekille ja Annammelekille, Sefarvaimin jumalille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Mutta he pelkäsivät myös Herraa. He asettivat itselleen uhrikukkulapappeja omasta keskuudestaan, ja nämä uhrasivat heidän puolestaan uhrikukkulatemppeleissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'He pelkäsivät tosin Herraa, mutta palvelivat myös omia jumaliaan samalla tavalla kuin ne kansat, joiden keskuudesta heidät oli tuotu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Vielä tänäkin päivänä he tekevät vanhan tapansa mukaan: he eivät pelkää Herraa eivätkä tee saamiensa säädösten ja oikeuksien mukaan, eivät sen lain ja niiden käskyjen mukaan, jotka Herra on antanut Jaakobin pojille, hänen, jolle hän antoi nimen Israel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Herra oli tehnyt liiton näiden kanssa ja käskenyt heitä sanoen: \"Älkää pelätkö muita jumalia, älkää kumartako ja palvelko niitä älkääkä uhratko niille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'vaan [pelätkää] Herraa, joka johdatti teidät Egyptin maasta suurella voimalla ja ojennetulla käsivarrella, häntä te pelätkää, häntä kumartakaa ja hänelle uhratkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Niitä säädöksiä ja oikeuksia, sitä lakia ja niitä käskyjä, jotka hän on teille kirjoittanut, noudattakaa alati tarkoin, mutta älkää pelätkö muita jumalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Liittoa, jonka tein kanssanne, älkää unohtako. Älkääkä pelätkö muita jumalia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'vaan pelätkää ainoastaan Herraa, Jumalaanne, niin hän pelastaa teidät kaikkien vihollistenne käsistä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Mutta he eivät totelleet, vaan tekivät vanhan tapansa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Nämä kansat pelkäsivät Herraa, mutta palvelivat samalla omia jumalankuviaan. Myös heidän lapsensa ja heidän lastensa lapset tekevät vielä tänä päivänä samoin, kuin heidän isänsä ovat tehneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'Israelin kuninkaan Hoosean, Eelan pojan, kolmantena hallitusvuotena tuli Hiskia, Juudan kuninkaan Aahaan poika, kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Hän oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kaksikymmentä yhdeksän vuotta. Hänen äitinsä oli nimeltään Abi, Sakarjan tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Hän teki sitä, mikä on oikein Herran silmissä, aivan kuin hänen isänsä Daavid oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Hän poisti uhrikukkulat, murskasi patsaat, hakkasi maahan aserapaalun ja löi palasiksi vaskikäärmeen, jonka Mooses oli tehnyt. Sillä niihin aikoihin asti israelilaiset olivat polttaneet uhreja sille. Sitä kutsuttiin nimellä Nehustan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Hän turvasi Herraan, Israelin Jumalaan, niin ettei kukaan ollut hänen kaltaisensa kaikista hänen jälkeensä tulleista Juudan kuninkaista eikä niistä, jotka olivat olleet ennen häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Hän riippui kiinni Herrassa eikä luopunut hänestä, vaan noudatti hänen käskyjään, jotka Herra oli antanut Moosekselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Herra oli hänen kanssaan. Hän menestyi kaikessa, mihin ryhtyi. Hän kapinoi Assurin kuningasta vastaan eikä enää palvellut häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Hän voitti filistealaiset ja valtasi heidän alueensa aina Gassaan asti, sekä vartiotornit että varustetut kaupungit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Mutta kuningas Hiskian neljäntenä hallitusvuotena, joka oli Israelin kuninkaan Hoosean, Eelan pojan, seitsemäs hallitusvuosi, hyökkäsi Salmaneser, Assurin kuningas, Samarian kimppuun ja piiritti sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Hän valloitti sen kolmen vuoden kuluttua. Hiskian kuudentena hallitusvuotena, joka oli Israelin kuninkaan Hoosean yhdeksäs hallitusvuosi, valloitettiin Samaria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Assurin kuningas vei Israelin karkotukseen Assuriin ja sijoitti heidät Halahiin ja Haaborin, Goosanin joen, rannoille ja Meedian kaupunkeihin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'sen tähden että he eivät olleet kuulleet Herran, Jumalansa, ääntä, vaan olivat rikkoneet hänen liittonsa, kaiken, mitä Mooses, Herran palvelija, oli käskenyt. He eivät olleet kuulleet sitä eivätkä tehneet sen mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Kuningas Hiskian neljäntenätoista hallitusvuotena hyökkäsi Sanherib, Assurin kuningas, kaikkien Juudan varustettujen kaupunkien kimppuun ja valloitti ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Hiskia, Juudan kuningas, lähetti Assurin kuninkaalle Laakiiseen sanan: \"Olen rikkonut, käänny pois kimpustani. Kannan, mitä panet kannettavakseni.\" Assurin kuningas määräsi Hiskian, Juudan kuninkaan, maksettavaksi kolmesataa talenttia hopeaa ja kolmekymmentä talenttia kultaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Hiskia antoi kaikki rahat, mitä Herran temppelissä ja kuninkaan linnan aarrekammioissa oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Siihen aikaan Hiskia leikkautti irti Herran temppelin ovista ja pihtipielistä sen päällystyksen, jolla Hiskia, Juudan kuningas, oli ne päällystänyt, ja antoi sen Assurin kuninkaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Mutta Assurin kuningas lähetti Laakiista Tartanin ja ylimmäisen hoviherran ja Rabsaken suuren sotajoukon kanssa kuningas Hiskiaa vastaan Jerusalemiin. Nämä lähtivät liikkeelle ja tulivat Jerusalemiin, ja lähdettyään liikkeelle ja tultuaan he pysähtyivät Ylälammikon vesijohdolle, joka on Vanuttajankedon tien varrella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Kun he sitten kutsuivat kuningasta, menivät Eljakim, Hilkian poika, joka oli linnan päällikkönä, ja kirjuri Sebna ja kansleri Jooah, Aasafin poika, heidän luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Rabsake sanoi heille: \"Sanokaa Hiskialle: Näin sanoo suurkuningas, Assurin kuningas: \'Mitä on tuo luottamus, mikä sinulla on?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Arvelet kai, että pelkästä huulten puheesta tulee neuvo ja voima sodankäyntiin. Keneen sinä oikein luotat, kun kapinoit minua vastaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Katso, sinä luotat nyt Egyptiin, tuohon särkyneeseen ruokosauvaan, joka tunkeutuu sen käteen, joka siihen nojaa, ja lävistää sen. Sellainen on farao, Egyptin kuningas, kaikille, jotka häneen luottavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Vai sanotteko te ehkä minulle: Me luotamme Herraan, meidän Jumalaamme? Mutta eikö hän ole se, jonka uhrikukkulat ja alttarit Hiskia poisti, kun hän sanoi Juudalle ja Jerusalemille: Tämän alttarin edessä on teidän kumartaen rukoiltava, täällä Jerusalemissa?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Mutta lyö nyt vetoa herrani, Assurin kuninkaan, kanssa: annan sinulle kaksi tuhatta hevosta, jos sinä voit hankkia niille ratsastajat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Kuinka torjut ainoankaan käskynhaltijan, ainoankaan herrani vähimmän palvelijan, hyökkäyksen? Luotat Egyptiin, sen vaunuihin ja ratsumiehiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Olenko minä siis Herran sallimatta hyökännyt tämän paikan kimppuun hävittämään sitä? Herra itse on sanonut minulle: \'Hyökkää tähän maahan ja hävitä se.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Eljakim, Hilkian poika, ja Sebna ja Jooah sanoivat Rabsakelle: \"Puhu palvelijoillesi aramin kieltä, sillä me ymmärrämme sitä. Älä puhu kanssamme juudan kieltä kansan kuullen, jota on muurilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Mutta Rabsake vastasi heille: \"Onko herrani lähettänyt minut puhumaan näitä sanoja herrallesi ja sinulle? Eikö juuri niille miehille, jotka istuvat muurilla syödäkseen kanssanne omaa ulostettaan ja juodakseen omaa virtsaansa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Rabsake astui esiin, huusi kovalla äänellä juudan kielellä, puhui ja sanoi: \"Kuulkaa suurkuninkaan, Assurin kuninkaan, sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Näin sanoo kuningas: \'Älkää antako Hiskian pettää itseänne, sillä hän ei voi pelastaa teitä käsistäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Älköön Hiskia saako teitä luottamaan Herraan, kun hän sanoo: Herra on varmasti pelastava meidät, eikä tätä kaupunkia anneta Assurin kuninkaan käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Älkää kuulko Hiskiaa.\' Sillä Assurin kuningas sanoo näin: \'Tehkää sovinto kanssani ja antautukaa minulle, niin saatte syödä kukin omasta viinipuustanne ja viikunapuustanne ja juoda kukin omasta kaivostanne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'kunnes tulen ja vien teidät maahan, joka on maanne kaltainen, vilja-, viini- ja leipämaahan, viinitarhojen, jalon öljypuun ja hunajan maahan. Niin elätte ettekä kuole. Mutta älkää kuulko Hiskiaa, sillä hän viettelee teidät sanoessaan: Herra pelastaa meidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Onko muidenkaan kansojen jumalista yksikään pelastanut maatansa Assurin kuninkaan käsistä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Missä ovat Hamatin ja Arpadin jumalat? Missä ovat Sefarvaimin, Heenan ja Ivvan jumalat? Ovatko ne pelastaneet Samariaa käsistäni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Onko muiden maiden kaikista jumalista ainoakaan pelastanut maatansa käsistäni? Kuinka sitten Herra pelastaisi Jerusalemin käsistäni?\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Mutta kansa oli vaiti, eivätkä he vastanneet hänelle mitään. Sillä kuningas oli käskenyt niin ja sanonut: \"Älkää vastatko hänelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Palatsin päällikkö Eljakim, Hilkian poika, ja kirjuri Sebna ja kansleri Jooah, Aasafin poika, tulivat Hiskian luo vaatteet reväistyinä ja kertoivat hänelle, mitä Rabsake oli sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Kun kuningas Hiskia kuuli sen, hän repäisi vaatteensa, pukeutui säkkiin ja meni Herran temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Hän lähetti palatsin päällikön Eljakimin ja kirjuri Sebnan sekä pappien vanhimmat säkkeihin puettuina profeetta Jesajan, Aamosin pojan, luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'He sanoivat hänelle: \"Näin sanoo Hiskia: \'Hädän, kurituksen ja häväistyksen päivä on tämä päivä, sillä lapset ovat tulleet kohdun suulle saakka, mutta ei ole voimaa synnyttää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Ehkä Herra, Jumalasi, kuulee kaikki Rabsaken sanat, joilla hänen herransa, Assurin kuningas, on lähettänyt hänet herjaamaan elävää Jumalaa, ja rankaisee häntä näistä sanoista, jotka Herra, Jumalasi, on kuullut. Kohota nyt rukous jäännöksen puolesta, joka vielä on olemassa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Kun kuningas Hiskian palvelijat tulivat Jesajan luo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Jesaja sanoi heille: \"Sanokaa näin herrallenne: \'Näin sanoo Herra: Älä pelkää niitä sanoja, jotka olet kuullut ja joilla Assurin kuninkaan nuorukaiset ovat häväisseet minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Katso, [minä] annan sellaisen hengen mennä häneen, että hän kuultuaan sanoman palaa omaan maahansa. Annan hänen kaatua miekkaan omassa maassaan.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Rabsake kääntyi takaisin ja tapasi Assurin kuninkaan sotimassa Libnaa vastaan, sillä hän oli kuullut, että tämä oli lähtenyt pois Laakiista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Mutta kun Sanherib kuuli sanottavan Tirhakasta, Kuusin kuninkaasta: \"Katso, hän on lähtenyt liikkeelle sotiakseen sinua vastaan\", hän lähetti taas sanansaattajat Hiskian luo ja käski sanoa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, '\"Sanokaa näin Hiskialle, Juudan kuninkaalle: \'Älä anna Jumalasi, johon luotat, pettää itseäsi äläkä ajattele: Jerusalem ei joudu Assurin kuninkaan käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Olethan kuullut, mitä Assurin kuninkaat ovat tehneet kaikille maille, kuinka he ovat vihkineet ne tuhon omiksi. Mutta sinäkö pelastuisit!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Ovatko kansojen jumalat pelastaneet niitä, jotka isäni ovat tuhonneet: Goosania, Harrania, Resefiä ja Telassarin edeniläisiä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Missä on Hamatin kuningas ja Arpadin kuningas, Sefarvaimin kaupungin, Heenan ja Ivvan kuningas?\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Kun Hiskia oli ottanut kirjeen sanansaattajilta ja lukenut sen, hän meni Herran temppeliin, ja Hiskia levitti sen Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Hiskia rukoili Herran edessä ja sanoi: \" Herra, Israelin Jumala, jonka valtaistuinta kerubit kannattavat, sinä yksin olet maan kaikkien valtakuntien Jumala, sinä olet tehnyt taivaan ja maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Herra, kallista korvasi ja kuule, Herra, avaa silmäsi ja katso. Kuule Sanheribin sanat, kuinka hän lähetti tuon miehen herjaamaan elävää Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'On totta, Herra, että Assurin kuninkaat ovat hävittäneet kansat ja heidän maansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'He ovat heittäneet heidän jumalansa tuleen, sillä ne eivät olleet jumalia, vaan ihmiskätten tekoa, puuta ja kiveä, ja sen tähden he saattoivat hävittää ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Mutta pelasta nyt meidät, Herra, Jumalamme, hänen käsistään, että kaikki maan valtakunnat tulisivat tietämään, että sinä, Herra, yksin olet Jumala.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Jesaja, Aamosin poika, lähetti Hiskialle tämän sanan: \"Näin sanoo Herra, Israelin Jumala: Mitä olet minulta Sanheribin, Assurin kuninkaan, tähden rukoillut, sen olen kuullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Tämä on sana, jonka Herra on puhunut hänestä: Neitsyt, tytär Siion, halveksii ja pilkkaa sinua, tytär Jerusalem nyökyttää ilkkuen päätään jälkeesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Ketä olet herjannut ja häväissyt, ja ketä vastaan olet korottanut äänesi? Korkealle olet kohottanut silmäsi Israelin Pyhää vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Sanansaattajiesi kautta herjasit Herraa ja sanoit: \'Monilla vaunuillani minä nousin vuorten harjalle, Libanonin ääriin asti. Hakkasin maahan sen korkeat setrit, sen parhaat sypressit, ja tunkeuduin sen etäisimpään yöpymispaikkaan, sen rehevimpään metsään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Minä kaivoin kaivoja ja join kuiviin muukalaisten vedet, ja jalkapohjallani kuivasin kaikki Egyptin virrat.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Etkö ole kuullut: kauan sitten olen tämän valmistanut, muinaisuudesta asti tämän ajatellut! Nyt olen sen toteuttanut, että hävittäisit varustetut kaupungit autioiksi kivikasoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Niiden asukkaat olivat voimattomat, he kauhistuivat ja joutuivat häpeään. Heidän kävi kuin kedon ruohon, kuin vihannan heinän, kuin katolla kasvavien kortten ja kuin laihon, joka kuivettuu ennen tuleentumistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Istuitpa tai lähdit tai tulit, sen tiedän ja sen, että raivoat minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Koska raivoat minua vastaan ja koska ylpeytesi on tullut korviini, panen koukkuni nenääsi ja suitseni suuhusi ja vien sinut takaisin samaa tietä, jota tulitkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Tämä on oleva sinulle merkkinä: tänä vuonna syödään jälkikasvua ja toisena vuonna kesannon odelmaa, mutta kolmantena vuonna kylväkää ja leikatkaa, istuttakaa viinitarhoja ja syökää niiden hedelmää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Juudan heimon pelastuneet, jotka ovat jäljelle jääneet, tekevät taas juurta alaspäin ja hedelmää ylöspäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Sillä Jerusalemista lähtee kasvamaan jäännös, pelastunut joukko Siionin vuorelta. Herran kiivaus on sen tekevä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Sen tähden, näin sanoo Herra Assurin kuninkaasta: Hän ei tule tähän kaupunkiin eikä ammu siihen nuolta. Hän ei tuo sitä vastaan kilpeä eikä luo sitä vastaan vallia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Samaa tietä, jota hän tuli, hän palaa, mutta tähän kaupunkiin hän ei tule, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Sillä minä varjelen tämän kaupungin ja pelastan sen itseni tähden ja palvelijani Daavidin tähden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Sinä yönä Herran enkeli lähti ja löi Assurin leirissä sata kahdeksankymmentä viisi tuhatta miestä, ja kun noustiin aamulla varhain, katso, he olivat kaikki kuolleina ruumiina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Silloin Sanherib, Assurin kuningas, lähti liikkeelle ja meni pois. Hän palasi takaisin ja jäi Niiniveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Mutta kun hän oli kerran rukoilemassa jumalansa Nisrokin temppelissä, surmasivat Adrammelek ja Sareser hänet miekalla. Sitten he pakenivat Araratin maahan. Hänen poikansa Eesarhaddon tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'Niihin aikoihin Hiskia sairastui ja oli kuolemaisillaan. Silloin profeetta Jesaja, Aamosin poika, tuli hänen luokseen ja sanoi hänelle: \"Näin sanoo Herra: Järjestä asiasi, sillä sinä kuolet etkä enää parane.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Hän käänsi kasvonsa seinään päin ja rukoili Herraa sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, '\"Oi Herra, muista, kuinka olen vaeltanut edessäsi uskollisesti ja ehyellä sydämellä ja tehnyt sitä, mikä on hyvää silmissäsi!\" Hiskia itki katkerasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Mutta Jesaja ei ollut vielä lähtenyt keskimmäiseltä esipihalta, kun hänelle tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, '\"Palaa takaisin ja sano Hiskialle, kansani ruhtinaalle: \'Näin sanoo Herra, isäsi Daavidin Jumala: Olen kuullut rukouksesi, olen nähnyt kyyneleesi. Katso, olen parantava sinut: jo kolmantena päivänä menet Herran temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Lisään sinulle ikää viisitoista vuotta. Pelastan sinut ja tämän kaupungin Assurin kuninkaan käsistä. Varjelen tätä kaupunkia itseni tähden ja palvelijani Daavidin tähden.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Jesaja sanoi: \"Toimittakaa tänne viikunakakkua.\" Niin he toivat sitä ja panivat sitä paiseen päälle, ja hän parani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Hiskia oli sanonut Jesajalle: \"Mikä on merkkinä siitä, että Herra on parantava minut, niin että kolmantena päivänä voin mennä Herran temppeliin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Jesaja sanoi: \"Tämä on oleva sinulle merkkinä Herralta siitä, että Herra tekee, mitä hän on sanonut: varjo kulkee kymmenen astetta eteenpäin tai siirtyy kymmenen astetta takaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Hiskia sanoi: \"Varjon on helppo edetä kymmenen astetta. Ei, vaan siirtyköön varjo takaisin kymmenen astetta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Profeetta Jesaja huusi Herraa, ja hän antoi varjon Aahaan aurinkokellossa siirtyä takaisin kymmenen astetta, jotka se oli jo laskeutunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Siihen aikaan Merodak-Baladan, Baladanin poika, Baabelin kuningas, lähetti kirjeen ja lahjoja Hiskialle, sillä hän oli kuullut, että Hiskia oli ollut sairaana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Kuultuaan heitä Hiskia näytti heille koko varastohuoneensa, hopean ja kullan, hajuaineet ja kalliin öljyn ja koko asehuoneensa ja kaikki, mitä hänen aarrekammioissaan oli. Hiskian talossa ja koko hänen valtakunnassaan ei ollut mitään, mitä hän ei olisi heille näyttänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Mutta profeetta Jesaja tuli kuningas Hiskian luo ja sanoi hänelle: \"Mitä nämä miehet ovat sanoneet, ja mistä he ovat tulleet luoksesi?\" Hiskia vastasi: \"He ovat tulleet kaukaisesta maasta, Baabelista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Hän sanoi: \"Mitä he ovat nähneet talossasi?\" Hiskia vastasi: \"Kaiken, mitä talossani on, he ovat nähneet. Aarrekammioissani ei ole mitään, mitä en olisi heille näyttänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Jesaja sanoi Hiskialle: \"Kuule Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Katso, päivät tulevat, jolloin kaikki, mitä talossasi on ja mitä isäsi ovat koonneet tähän päivään asti, viedään pois Baabeliin, eikä mitään jää jäljelle, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Omia poikiasi, jotka sinusta polveutuvat, jotka sinulle syntyvät, viedään hovipalvelijoiksi Baabelin kuninkaan palatsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Hiskia sanoi Jesajalle: \" Herran sana, jonka olet puhunut, on hyvä.\" Sillä hän ajatteli: \"Onpahan rauha ja turvallisuus minun päivinäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Mitä muuta on kerrottavaa Hiskiasta ja kaikista hänen urotöistään, sekä se, kuinka hän rakensi lammikon ja vesijohdon ja johti veden kaupunkiin, on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Hiskia meni lepoon isiensä luo, ja hänen poikansa Manasse tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manasse oli kahdentoista vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa viisikymmentä viisi vuotta. Hänen äitinsä oli nimeltään Hefsibah.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Hän teki sitä, mikä on pahaa Herran silmissä, niiden kansojen kauhistavien tekojen mukaan, jotka Herra oli karkottanut israelilaisten tieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Hän rakensi jälleen uhrikukkulat, jotka hänen isänsä Hiskia oli hävittänyt, ja pystytti alttareita Baalille ja teki aseran, niin kuin Israelin kuningas Ahab oli tehnyt, kumarsi ja palveli kaikkea taivaan joukkoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Hän rakensi alttareita myös Herran temppeliin, josta paikasta Herra oli sanonut: \"Jerusalemiin asetan nimeni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Hän rakensi alttareita kaikelle taivaan joukolle Herran temppelin molempiin esipihoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Hän pani myös poikansa kulkemaan tulen läpi, ennusteli merkeistä, harjoitti noituutta ja hankki itselleen vainaja- ja tietäjähenkien manaajia. Hän teki paljon sitä, mikä on pahaa Herran silmissä, ja vihoitti hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Teettämänsä Aseran kuvan hän asetti temppeliin, josta Herra oli sanonut Daavidille ja hänen pojalleen Salomolle: \"Tähän temppeliin ja Jerusalemiin, jonka olen valinnut kaikista Israelin sukukunnista, asetan nimeni ikiajoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Enkä anna enää Israelin jalkojen harhailla pois siitä maasta, jonka olen antanut heidän isilleen, jos he vain kaikessa noudattavat sitä, mitä olen käskenyt heidän noudattaa – koko sitä lakia, jonka palvelijani Mooses on heille antanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Mutta he eivät totelleet, ja Manasse eksytti heidät tekemään pahaa enemmän kuin ne kansat, jotka Herra oli hävittänyt israelilaisten tieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Herra puhui palvelijoidensa, profeettojen, kautta ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, '\"Koska Manasse, Juudan kuningas, on tehnyt nämä kauhistavat teot ja siten tehnyt pahaa enemmän kuin amorilaiset, jotka olivat ennen häntä, ja on saattanut epäjumalillaan myös Juudan tekemään syntiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'sen tähden sanoo Herra, Israelin Jumala, näin: Katso, annan sellaisen onnettomuuden kohdata Jerusalemia ja Juudaa, että joka sen kuulee, sen molemmat korvat soivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Mittaan Jerusalemin samalla mittanuoralla kuin Samarian ja punnitsen sen samalla vaa\'alla kuin Ahabin suvun. Huuhdon Jerusalemin, niin kuin vati huuhdotaan: se huuhdotaan ja käännetään kumolleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Hylkään perintöosani jäännöksen ja annan heidät vihollistensa käsiin, niin että he joutuvat kaikkien vihollistensa saaliiksi ja ryöstettäviksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'koska ovat tehneet sitä, mikä on pahaa silmissäni, ja vihoittaneet minut siitä päivästä lähtien, jona heidän isänsä lähtivät Egyptin maasta, tähän päivään asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Manasse vuodatti myös sangen paljon viatonta verta, niin että hän täytti sillä Jerusalemin ääriään myöten sen syntinsä lisäksi, jolla hän saattoi Juudan tekemään syntiä, tekemään sitä, mikä on pahaa Herran silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Mitä muuta on kerrottavaa Manassesta ja kaikesta, mitä hän teki, ja synnistä, minkä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Manasse meni lepoon isiensä luo, ja hänet haudattiin linnansa puutarhaan, Ussan puutarhaan. Hänen poikansa Aamon tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Aamon oli kahdenkymmenen kahden vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa kaksi vuotta. Hänen äitinsä oli nimeltään Mesullemet, Haaruksen tytär, Jotbasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Hän teki sitä, mikä on pahaa Herran silmissä, niin kuin hänen isänsä Manasse oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Hän vaelsi kaikessa samaa tietä, mitä hänen isänsä oli vaeltanut: hän palveli niitä epäjumalia, joita hänen isänsä oli palvellut, ja kumarsi niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Hän hylkäsi Herran, isiensä Jumalan, eikä vaeltanut Herran tietä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Aamonin palvelijat tekivät salaliiton häntä vastaan ja tappoivat kuninkaan hänen linnassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Mutta maan kansa surmasi kaikki, jotka olivat tehneet salaliiton kuningas Aamonia vastaan. Maan kansa teki hänen poikansa Joosian kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Mitä muuta on kerrottavaa Aamonista, siitä, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Hänet haudattiin omaan hautaansa Ussan puutarhaan. Hänen poikansa Joosia tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Joosia oli kahdeksan vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kolmekymmentä yksi vuotta. Hänen äitinsä oli nimeltään Jedida, Adajan tytär, Boskatista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Hän teki sitä, mikä on oikein Herran silmissä, ja vaelsi kaikessa isänsä Daavidin tietä poikkeamatta oikealle tai vasemmalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'Kahdeksantenatoista hallitusvuotenaan kuningas Joosia lähetti kirjuri Saafanin, Asaljan pojan, Mesullamin pojanpojan, Herran temppeliin ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, '\"Mene ylimmäisen papin Hilkian luo, että hän laskisi valmiiksi Herran temppeliin tuodut rahat, joita ovenvartijat ovat koonneet kansalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'Hän antakoon ne työnteettäjille, jotka on pantu valvomaan töitä Herran temppelissä, ja nämä maksakoot niillä työmiehet, jotka ovat Herran temppelissä korjaamassa sitä, mikä temppelissä on rappeutunutta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'puusepät, rakentajat ja muurarit, sekä temppelin korjaamista varten ostettavat puutavarat ja hakatut kivet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Älköön heiltä kuitenkaan vaadittako tilintekoa rahoista, jotka heille luovutetaan, vaan toimikoot he luottamusmiehinä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Ylipappi Hilkia sanoi kirjuri Saafanille: \"Löysin lain kirjan Herran temppelistä.\" Hilkia antoi kirjan Saafanille, ja tämä luki sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Kirjuri Saafan meni kuninkaan luo ja teki kuninkaalle selon asiasta sanoen: \"Palvelijasi ovat ottaneet esille rahat, mitä temppelissä oli, ja ovat antaneet ne työnteettäjille, jotka on pantu valvomaan töitä Herran temppelissä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Kirjuri Saafan kertoi kuninkaalle sanoen: \"Pappi Hilkia antoi minulle erään kirjan.\" Sitten Saafan luki sen kuninkaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Kun kuningas kuuli lain kirjan sanat, repäisi hän vaatteensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Kuningas käski pappi Hilkiaa, Ahikamia, Saafanin poikaa, Akboria, Miikajan poikaa, kirjuri Saafania ja Asajaa, kuninkaan palvelijaa, sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, '\"Menkää ja kysykää minun, kansan ja koko Juudan puolesta neuvoa Herralta tästä löydetystä kirjasta. Sillä suuri on Herran viha, joka on syttynyt meitä vastaan, koska isämme eivät ole totelleet tämän kirjan sanoja eivätkä tehneet mitään kaikesta siitä, mitä siinä on meille kirjoitettuna.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Pappi Hilkia, Ahikam, Akbor, Saafan ja Asaja menivät naisprofeetta Huldan luo, joka oli vaatevaraston hoitajan Sallumin, Tikvan pojan, Harhaan pojanpojan, vaimo ja asui Jerusalemissa, toisessa kaupunginosassa. He puhuivat hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Hän sanoi heille: \"Näin sanoo Herra, Israelin Jumala: Sanokaa sille miehelle, joka lähetti teidät luokseni:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, '\'Näin sanoo Herra: Katso, annan tätä paikkaa ja sen asukkaita kohdata onnettomuuden, kaiken, mitä sanotaan siinä kirjassa, jonka Juudan kuningas on lukenut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'sillä he ovat hylänneet minut ja polttaneet uhreja muille jumalille ja vihoittaneet minut kaikilla kättensä teoilla. Minussa on syttynyt viha tätä paikkaa kohtaan eikä sammu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Mutta Juudan kuninkaalle, joka on lähettänyt teidät kysymään neuvoa Herralta, sanokaa näin: Näin sanoo Herra, Israelin Jumala, niistä sanoista, jotka olet kuullut:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Koska sydämesi on pehmennyt ja olet nöyrtynyt Herran edessä kuullessasi, mitä olen puhunut tätä paikkaa ja sen asukkaita vastaan, että he tulevat kauhistukseksi ja kiroussanaksi, ja koska olet reväissyt vaatteesi ja itkenyt edessäni, minäkin olen kuullut sinua, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Sen tähden katso, korjaan sinut isiesi luo, ja sinä siirryt rauhassa hautaasi, ja silmäsi pääsevät näkemästä kaikkea sitä onnettomuutta, minkä tuotan tälle paikalle.\'\" He toivat kuninkaalle tämän sanan vastauksena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Kuningas lähetti kokoamaan luokseen kaikki Juudan ja Jerusalemin vanhimmat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Kuningas meni Herran temppeliin, ja hänen kanssaan kaikki Juudan miehet ja kaikki Jerusalemin asukkaat, myös papit ja profeetat, koko kansa pienimmästä suurimpaan. Hän luki heidän kuultensa kaikki Herran temppelistä löydetyn liitonkirjan sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Kuningas asettui pylvään viereen ja teki Herran edessä sen liiton, että heidän tuli seurata Herraa, noudattaa hänen käskyjään, todistuksiaan ja säädöksiään kaikesta sydämestään ja kaikesta sielustaan ja pitää liiton sanat, jotka olivat kirjoitettuina siinä kirjassa. Kaikki kansa yhtyi siihen liittoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Kuningas käski ylimmäistä pappia Hilkiaa ja häntä lähimpiä pappeja sekä ovenvartijoita viemään Herran temppelistä pois kaikki esineet, joita oli tehty Baalille, Aseralle ja kaikelle taivaan joukolle. Hän poltatti ne Jerusalemin ulkopuolella Kidronin kedoilla, mutta vei niiden tuhkan Beeteliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Hän pani myös viralta epäjumalien papit, jotka Juudan kuninkaat olivat asettaneet polttamaan uhreja uhrikukkuloilla Juudan kaupungeissa ja Jerusalemin ympäristössä ja jotka polttivat uhreja Baalille, auringolle, kuulle, eläinradan tähdille ja kaikelle taivaan joukolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Hän vei aseran pois Herran temppelistä Jerusalemin ulkopuolelle Kidronin laaksoon ja poltti sen Kidronin laaksossa, rouhensi sen tomuksi ja heitti tomun yhteiselle hautausmaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Hän kukisti haureellisten pyhäkköpoikien huoneet, jotka olivat Herran temppelissä ja joissa naiset kutoivat verhoja Aseralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Hän toi pois kaikki papit Juudan kaupungeista ja hävitti uhrikukkulat, joilla papit olivat polttaneet uhreja, Gebasta Beersebaan asti. Hän kukisti porteilla olevat uhrikukkulat, joita oli kaupungin päällikön Joosuan portin oven edustalla vasemmalla puolella mentäessä sisään kaupungin portista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Uhrikukkulapapit eivät kuitenkaan saaneet nousta Herran alttarille Jerusalemissa. He saivat vain syödä happamatonta leipää veljiensä kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Hän hävitti myös polttopaikan Ben-Hinnomin laaksossa, ettei kukaan voisi panna poikaansa tai tytärtään kulkemaan tulen läpi Molokin kunniaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Hän poisti hevoset, jotka Juudan kuninkaat olivat asettaneet auringon kunniaksi, siitä, mistä mennään Herran temppeliin, hoviherra Netan-Melekin kammion vierestä, joka oli Parvarimissa, ja poltti auringonvaunut tulessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Kuningas kukisti Aahaan yläsalin katolla olevat alttarit, jotka Juudan kuninkaat olivat teettäneet, ja ne alttarit, jotka Manasse oli teettänyt Herran temppelin molempiin esipihoihin. Hän riensi sieltä ja heitti niiden tomun Kidronin laaksoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Ne uhrikukkulat, jotka olivat itään päin Jerusalemista, etelään päin Turmiovuoresta, ja jotka Salomo, Israelin kuningas, oli rakentanut Astartelle, siidonilaisten iljetykselle, ja Kemokselle, Mooabin iljetykselle, ja Milkomille, ammonilaisten kauhistukselle, ne kuningas hävitti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Hän murskasi patsaat ja hakkasi maahan aserapaalut ja täytti niiden paikan ihmisten luilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Myös Beetelissä olevan alttarin, sen uhrikukkulan, jonka oli teettänyt Jerobeam, Nebatin poika, joka saattoi Israelin tekemään syntiä, senkin alttarin uhrikukkuloineen hän kukisti. Hän poltti uhrikukkulan ja rouhensi sen tomuksi sekä poltti aserapaalun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Kun Joosia sitten kääntyi ja näki haudat, jotka olivat vuorella, hän lähetti ottamaan luut haudoista, poltti ne alttarilla ja saastutti näin alttarin, Herran sanan mukaan, jonka oli julistanut se Jumalan mies, joka nämä julisti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Hän kysyi: \"Mikä tuo hautamerkki on, jonka minä näen?\" Kaupungin miehet vastasivat hänelle: \"Se on sen Jumalan miehen hauta, joka tuli Juudasta ja julisti sen, minkä sinä nyt olet tehnyt Beetelin alttarille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Hän sanoi: \"Antakaa hänen olla, älköön kukaan koskeko hänen luihinsa.\" He jättivät hänen luunsa rauhaan ja samoin sen profeetan luut, joka oli tullut Samariasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Myös Samarian kaupungeista Joosia poisti kaikki uhrikukkulatemppelit, jotka Israelin kuninkaat olivat rakentaneet ja niin vihoittaneet Herran, ja hän teki niille saman, minkä oli tehnyt Beetelissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Kaikki siellä olevat uhrikukkulapapit hän teurasti alttareilla ja poltti ihmisten luita niiden päällä. Hän palasi takaisin Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Kuningas käski kaikkea kansaa sanoen: \"Viettäkää pääsiäistä Herran, Jumalanne, kunniaksi, niin kuin on kirjoitettuna tässä liiton kirjassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Sillä tätä pääsiäistä ei ollut vietetty sen ajan jälkeen, jona tuomarit tuomitsivat Israelia, ei Israelin kuningasten eikä Juudan kuningasten koko aikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Vasta kuningas Joosian kahdeksantenatoista hallitusvuotena vietettiin tämä pääsiäinen Jerusalemissa Herran kunniaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Myös vainaja- ja tietäjähenkien manaajat, kotijumalat ja epäjumalat ja kaikki iljetykset, joita oli nähty Juudan maassa ja Jerusalemissa, Joosia hävitti täyttääkseen lain sanat, jotka olivat kirjoitettuina siinä kirjassa, minkä pappi Hilkia oli löytänyt Herran temppelistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Ei ollut ennen häntä ollut hänen vertaistaan kuningasta, joka niin kaikesta sydämestään, kaikesta sielustaan ja kaikesta voimastaan olisi kääntynyt Herran puoleen, kaiken Mooseksen lain mukaan, eikä hänen jälkeensä tullut hänen vertaistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Kuitenkaan Herra ei kääntynyt suuren vihansa hehkusta, kun kerran hänen vihansa oli syttynyt Juudaa vastaan kaikesta siitä, millä Manasse oli vihoittanut hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Herra sanoi: \"Juudankin toimitan pois kasvojeni edestä, niin kuin minä olen toimittanut pois Israelin. Hylkään myös Jerusalemin, tämän kaupungin, jonka olin valinnut, ja temppelin, josta olin sanonut: \'Nimeni on siellä oleva.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Se, mitä muuta on kerrottavaa Joosiasta ja kaikesta, mitä hän teki, on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Hänen aikanaan farao Neko, Egyptin kuningas, lähti Assurin kuningasta vastaan Eufrat-virralle. Kuningas Joosia meni häntä vastaan, mutta farao surmasi hänet Megiddossa heti, kun näki hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Hänen palvelijansa veivät hänet kuolleena vaunuissa Megiddosta, toivat hänet Jerusalemiin ja hautasivat hänet hänen omaan hautaansa. Mutta maan kansa otti Joosian pojan Jooahaan, voiteli hänet ja teki hänet kuninkaaksi hänen isänsä sijaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Jooahas oli kahdenkymmenen kolmen vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi kolme kuukautta Jerusalemissa. Hänen äitinsä oli nimeltään Hamutal, Jeremian tytär, Libnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Hän teki sitä, mikä on pahaa Herran silmissä, aivan niin kuin hänen isänsä olivat tehneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Mutta farao Neko vangitutti hänet Riblassa, Hamatin maassa, ettei hän hallitsisi Jerusalemissa, ja määräsi maan maksettavaksi pakkoveron: sata talenttia hopeaa ja kymmenen talenttia kultaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Farao Neko teki Eljakimin, Joosian pojan, kuninkaaksi hänen isänsä Joosian sijaan ja muutti hänen nimensä Joojakimiksi. Mutta Jooahaan hän otti vangiksi, ja tämä joutui Egyptiin. Siellä hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Hopean ja kullan Joojakim maksoi faraolle, mutta voidakseen maksaa rahat faraon käskyn mukaan hän verotti maata ottaen maan kansalta, sen mukaan kuin kutakin oli verotettu, hopeaa ja kultaa antaakseen farao Nekolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Joojakim oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa yksitoista vuotta. Hänen äitinsä oli nimeltään Sebida, Pedajan tytär, Ruumasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Hän teki sitä, mikä on pahaa Herran silmissä, aivan niin kuin hänen isänsä olivat tehneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'Hänen aikanaan Nebukadnessar, Baabelin kuningas, lähti liikkeelle, ja Joojakim tuli hänen palvelijakseen. Kolmen vuoden kuluttua tämä jälleen kapinoi häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Herra lähetti hänen kimppuunsa kaldealaisten, aramilaisten, mooabilaisten ja ammonilaisten partiojoukkoja. Hän lähetti ne Juudan kimppuun sitä tuhoamaan Herran sanan mukaan, jonka hän oli puhunut palvelijoidensa, profeettojen, kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Mutta tämä tapahtui Juudalle Herran käskystä. Näin hän toimitti heidät pois kasvojensa edestä Manassen syntien tähden, kaiken tähden, mitä hän oli tehnyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'ja myös viattoman veren tähden, minkä hän oli vuodattanut täyttäessään Jerusalemin viattomalla verellä. Sitä Herra ei halunnut antaa anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Se, mitä muuta kerrottavaa on Joojakimista ja kaikesta, mitä hän teki, on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Joojakim meni lepoon isiensä luo. Hänen poikansa Joojakin tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Egyptin kuningas ei enää lähtenyt maastaan, sillä Baabelin kuningas oli vallannut kaiken, mikä oli Egyptin kuninkaan omaa, Egyptin purosta aina Eufrat-virtaan saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Joojakin oli kahdeksantoista vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa kolme kuukautta. Hänen äitinsä oli nimeltään Nehusta, Elnatanin tytär, Jerusalemista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Hän teki sitä, mikä on pahaa Herran silmissä, aivan kuin hänen isänsä oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'Siihen aikaan Baabelin kuninkaan Nebukadnessarin palvelijat tulivat Jerusalemiin, ja kaupunki saarrettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Nebukadnessar, Baabelin kuningas, ryntäsi kaupunkiin hänen palvelijoidensa saartaessa sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Joojakin, Juudan kuningas, antautui Baabelin kuninkaalle äitineen ja palvelijoineen, päällikköineen ja hoviherroineen. Baabelin kuningas otti hänet vangiksi kahdeksantena hallitusvuotenaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Hän vei sieltä pois kaikki Herran temppelin ja kuninkaan linnan aarteet, ja hän rikkoi kaikki kultaesineet, jotka Israelin kuningas Salomo oli teettänyt Herran temppeliin. Tapahtui, niin kuin Herra oli puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Hän vei karkotukseen koko Jerusalemin, kaikki päälliköt ja kaikki väkevät sankarit, kymmenentuhatta karkotettua, ja kaikki sepät ja lukkosepät. Jäljelle ei jäänyt muita kuin maan köyhiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Hän siirsi Joojakinin vankina Baabeliin, samoin hän vei kuninkaan äidin, kuninkaan puolisot ja hänen hoviherransa sekä muut maan mahtavat karkotettuina Jerusalemista Baabeliin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'niin myös kaikki sotilaat luvultaan seitsemäntuhatta, sepät ja lukkosepät luvultaan tuhat, kaikki sotasankareita. Ne Baabelin kuningas vei karkotettuina Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Mutta Baabelin kuningas asetti hänen setänsä Mattanjan kuninkaaksi hänen jälkeensä ja muutti hänen nimensä Sidkiaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Sidkia oli kahdenkymmenen yhden vuoden vanha tullessaan kuninkaaksi, ja hallitsi Jerusalemissa yksitoista vuotta. Hänen äitinsä oli nimeltään Hamutal, Jeremian tytär, Libnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Sidkia teki sitä, mikä on pahaa Herran silmissä, aivan samoin kuin Joojakim oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Sillä Herran vihan tähden kävi näin Jerusalemille ja Juudalle, kunnes hän vihdoin heitti heidät pois kasvojensa edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Sidkia kapinoi Baabelin kuningasta vastaan. Hänen yhdeksäntenä hallitusvuotenaan, sen kymmenennessä kuussa, kuukauden kymmenentenä päivänä, kävi Nebukadnessar, Baabelin kuningas, hän ja koko hänen sotajoukkonsa, Jerusalemin kimppuun ja asettui leiriin sitä vastaan. He rakensivat saartovarusteet sitä vastaan sen ympäri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Näin kaupunkia piiritettiin kuningas Sidkian yhdenteentoista hallitusvuoteen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Mutta neljännen kuukauden yhdeksäntenä päivänä, kun nälänhätä ahdisti kaupunkia eikä ollut leipää maan kansalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'valloitettiin kaupunki, ja kaikki sotilaat pakenivat yöllä molempien muurien välistä porttitietä, joka oli kuninkaan puutarhan puolella kaldealaisten ollessa kaupungin ympärillä, ja he kulkivat Aromaahan päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Mutta kaldealaisten sotajoukko ajoi kuningasta takaa, ja he saavuttivat hänet Jerikon aroilla. Koko hänen sotaväkensä oli jättänyt hänet ja hajaantunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'He ottivat kuninkaan kiinni ja veivät hänet Baabelin kuninkaan eteen Riblaan. Hänelle julistettiin tuomio:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Sidkian pojat teurastettiin hänen silmiensä edessä, ja Sidkialta itseltään hän sokaisi silmät ja kytki hänet vaskikahleisiin, ja hänet vietiin Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Viidennessä kuussa, kuukauden seitsemäntenä päivänä, Baabelin kuninkaan Nebukadnessarin yhdeksäntenätoista hallitusvuotena, tuli Baabelin kuninkaan palvelija Nebusaradan, henkivartijoiden päällikkö, Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Hän poltti Herran temppelin ja kuninkaan linnan ja kaikki Jerusalemin talot. Kaikki ylhäisten talot hän poltti tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Koko kaldealaisten sotajoukko, joka henkivartijoiden päälliköllä oli mukanaan, repi maahan Jerusalemin muurit joka puolelta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Nebusaradan, henkivartijoiden päällikkö, vei karkotukseen kansan tähteet, mitä oli jäljellä kaupungissa, sekä ne, jotka olivat menneet Baabelin kuninkaan puolelle, ja muun rahvaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Mutta osan maan köyhiä henkivartioiden päällikkö jätti jäljelle viinitarhureiksi ja peltomiehiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Vaskipylväät, jotka olivat Herran temppelissä, altaiden telineet ja vaskimeren, jotka olivat Herran temppelissä, kaldealaiset särkivät ja veivät vasken Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Kattilat, lapiot, veitset, kupit ja kaikki vaskiesineet, joita oli käytetty jumalanpalveluksessa, he ottivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Samoin henkivartijoiden päällikkö otti hiilipannut ja maljat, jotka olivat kokonaan kultaa tai hopeaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Molempien pylväiden, meren ja telineiden, jotka Salomo oli teettänyt Herran temppeliin – näiden kaikkien esineiden vaski ei ollut punnittavissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Toisen pylvään korkeus oli kahdeksantoista kyynärää. Sen päässä oli pylväänpää vaskesta. Pylväänpään korkeus oli kolme kyynärää. Pylväänpään päällä oli ristikkokoriste ja granaattiomenia yltympäri, kaikki vaskea, ja samanlaiset oli toisessa pylväässä ristikkokoristeen päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Henkivartijoiden päällikkö otti ylimmäisen papin Serajan ja häntä lähimmän papin Sefanjan sekä kolme ovenvartijaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'ja kaupungista hän otti yhden hoviherran, joka oli sotaväen tarkastaja, ja viisi kuninkaan lähintä miestä, jotka tavattiin kaupungista, sekä sotapäällikön kirjurin, jonka tehtävänä oli ottaa maan kansaa sotapalvelukseen, ja kuusikymmentä miestä maan kansasta, jotka tavattiin kaupungista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Nämä Nebusaradan, henkivartijoiden päällikkö otti ja vei heidät Baabelin kuninkaan eteen Riblaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Baabelin kuningas löi heidät kuoliaiksi Riblassa Hamatin maassa. Juuda vietiin pois maastaan karkotukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Mutta sen väen käskynhaltijaksi, joka jäi Juudan maahan, sen, jonka Nebukadnessar, Baabelin kuningas, jätti sinne, hän asetti Gedaljan, Ahikamin pojan, Saafanin pojanpojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Kun kaikki sotaväen päälliköt, he ja heidän miehensä, kuulivat, että Baabelin kuningas oli asettanut Gedaljan käskynhaltijaksi, he tulivat miehineen Gedaljan luo Mispaan, nimittäin Ismael, Netanjan poika, Joohanan, Kaareahin poika, netofalainen Seraja, Tanhumetin poika, ja Jaasanja, maakatilaisen poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Gedalja vannoi heille ja heidän miehilleen ja sanoi heille: \"Älkää pelätkö kaldealaisten palvelijoita. Jääkää maahan ja palvelkaa Baabelin kuningasta, niin menestytte.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Mutta seitsemännessä kuussa tuli Ismael, Netanjan poika, Elisaman pojanpoika, joka oli kuninkaallista sukua, mukanaan kymmenen miestä, ja he löivät kuoliaaksi Gedaljan ja ne Juudan miehet ja kaldealaiset, jotka olivat hänen kanssaan Mispassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Silloin nousi kaikki kansa, pienimmästä suurimpaan, ja samoin sotaväen päälliköt, ja he menivät Egyptiin, sillä he pelkäsivät kaldealaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Mutta kolmantenakymmenentenä seitsemäntenä vuotena siitä, kun Joojakin, Juudan kuningas, oli viety karkotukseen, kahdennessatoista kuussa, kuukauden kahdentenakymmenentenä seitsemäntenä päivänä, korotti Evil-Merodak, Baabelin kuningas, samana vuonna, jona hän tuli kuninkaaksi, Juudan kuninkaan Joojakinin pään vapauttaen hänet vankilasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Hän puhutteli häntä ystävällisesti ja asetti hänen istuimensa ylemmäksi muiden kuninkaiden istuimia, jotka olivat hänen luonaan Baabelissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Hän sai panna pois vangin puvun ja aterioida aina hänen luonaan, niin kauan kuin eli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Hän sai kuninkaalta elatuksensa, mitä kunakin päivänä tarvitsi, vakinaisen elatuksen, niin kauan kuin eli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Aadam, Seet, Enos,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Keenan, Mahalalel, Jered,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Hanok, Metusalah, Lemek,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Nooa, Seem, Haam ja Jaafet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Jaafetin pojat olivat Goomer, Maagog, Maadai, Jaavan, Tuubal, Mesek ja Tiiras.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Goomerin pojat olivat Askenas, Diifat ja Toogarma.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Jaavanin pojat olivat Elisa ja Tarsisa, kittiläiset ja roodanilaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Haamin pojat olivat Kuus, Misraim, Puut ja Kanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Kuusin pojat olivat Seba, Havila, Sabta, Raema ja Sabteka. Raeman pojat olivat Saba ja Dedan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Kuusille syntyi Nimrod. Hän oli ensimmäinen valtias maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Misraimille syntyivät luudilaiset, anamilaiset, lehabilaiset, naftuhilaiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'patrokselaiset ja kasluhilaiset, joista filistealaiset ovat lähteneet, sekä kaftorilaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Kanaanille syntyivät Siidon, hänen esikoisensa, ja Heet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'sekä jebusilaiset, amorilaiset, girgasilaiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'hivviläiset, arkilaiset, siiniläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'arvadilaiset, semarilaiset ja hamatilaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Seemin pojat olivat Eelam, Assur, Arpaksad, Luud, Aram, Uus, Huul, Geter ja Mesek.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Arpaksadille syntyi Selah, ja Selahille syntyi Eeber.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Eeberille syntyi kaksi poikaa. Toisen nimi oli Peleg, sillä hänen aikanaan jakaantui maa, ja hänen veljensä nimi oli Joktan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Joktanille syntyivät Almodad, Selef, Hasarmavet, Jerah,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Hadoram, Uusal, Dikla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Eebal, Abimael, Saba,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Oofir, Havila ja Joobab. Kaikki nämä olivat Joktanin poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Seem, Arpaksad, Selah,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Eeber, Peleg, Regu,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Naahor, Terah,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, se on Aabraham.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Aabrahamin pojat olivat Iisak ja Ismael.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Tämä on heidän sukuluettelonsa: Nebajot, Ismaelin esikoinen, Keedar, Adbeel, Mibsam,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Misma, Duuma, Massa, Hadad, Teema,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Naafis ja Keedma. Nämä olivat Ismaelin pojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Keturan, Aabrahamin sivuvaimon, pojat, jotka tämä synnytti, olivat Simran, Joksan, Medan, Midian, Jisbak ja Suuah. Joksanin pojat olivat Saba ja Dedan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Midianin pojat olivat Eefa, Eefer, Hanok, Abida ja Eldaa. Kaikki nämä olivat Keturan jälkeläisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Aabrahamille syntyi Iisak. Iisakin pojat olivat Eesau ja Israel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Eesaun pojat olivat Elifas, Reguel, Jeus, Jaelam ja Koorah.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Elifaan pojat olivat Teeman, Oomar, Sefi, Gaetam, Kenas, Timna ja Amalek.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Reguelin pojat olivat Nahat, Sera, Samma ja Missa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Seirin pojat olivat Lootan, Soobal, Sibon, Ana, Diison, Eeser ja Diisan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Lootanin pojat olivat Hoori ja Hoomam, ja Lootanin sisar oli Timna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Soobalin pojat olivat Aljan, Maanahat, Eebal, Sefi ja Oonan. Sibonin pojat olivat Aija ja Ana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Anan pojat olivat Diison sekä Diisonin pojat Hamran, Esban, Jitran ja Keran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Eeserin pojat olivat Bilhan, Saavan ja Jaakan. Diisanin pojat olivat Uus ja Aran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Nämä olivat ne kuninkaat, jotka hallitsivat Edomin maassa, ennen kuin mikään kuningas oli hallinnut israelilaisia: Bela, Beorin poika, ja hänen kaupunkinsa nimi oli Dinhaba.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Kun Bela kuoli, tuli Joobab, Seran poika, Bosrasta, kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Kun Joobab kuoli, tuli Huusam, teemanilaisten maasta, kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Kun Huusam kuoli, tuli Hadad, Bedadin poika, kuninkaaksi hänen jälkeensä, hän, joka voitti midianilaiset Mooabin maassa. Hänen kaupunkinsa nimi oli Avit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Kun Hadad kuoli, tuli Samla, Masrekasta, kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Kun Samla kuoli, tuli Saul, virran rannalla olevasta Rehobotista, kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Kun Saul kuoli, tuli Baal-Haanan, Akborin poika, kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Kun Baal-Haanan kuoli, tuli Hadad kuninkaaksi hänen jälkeensä, ja hänen kaupunkinsa nimi oli Paagi, ja hänen vaimonsa nimi oli Mehetabel, Matredin tytär, joka oli Mee-Saahabin tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Hadad kuoli. Edomin sukuruhtinaat olivat: ruhtinas Timna, ruhtinas Alva, ruhtinas Jetet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'ruhtinas Oholibama, ruhtinas Eela, ruhtinas Piinon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'ruhtinas Kenas, ruhtinas Teeman, ruhtinas Mibsar,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'ruhtinas Magdiel, ruhtinas Iiram. Nämä olivat Edomin sukuruhtinaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Nämä olivat Israelin pojat: Ruuben, Simeon, Leevi ja Juuda, Isaskar ja Sebulon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Daan, Joosef ja Benjamin, Naftali, Gaad ja Asser.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Juudan pojat olivat Eer, Oonan ja Seela. Nämä kolme synnytti hänelle Suuahin tytär, kanaanilainen. Eer, Juudan esikoinen, ei ollut otollinen Herran silmissä. Sen tähden hän antoi hänen kuolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Taamar, Juudan miniä, synnytti hänelle Pereksen ja Seran. Juudan poikia oli kaikkiaan viisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Pereksen pojat olivat Hesron ja Haamul.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Seran pojat olivat Simri, Eetan, Heeman, Kalkol ja Daara. Heitä oli kaikkiaan viisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Karmin pojat olivat Aakar, joka syöksi Israelin onnettomuuteen, kun oli uskoton ja anasti tuhon omaksi vihittyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Eetanin poika oli Asarja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Hesronin pojat, jotka hänelle syntyivät, olivat Jerahmeel, Raam ja Kelubai.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Raamille syntyi Amminadab, ja Amminadabille syntyi Nahson, Juudan jälkeläisten ruhtinas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Nahsonille syntyi Salma, ja Salmalle syntyi Booas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Booaalle syntyi Oobed, ja Oobedille syntyi Iisai.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Iisaille syntyi esikoisena Eliab, toisena Abinadab, kolmantena Simea,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'neljäntenä Netanel, viidentenä Raddai,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'kuudentena Oosem ja seitsemäntenä Daavid.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Heidän sisarensa olivat Seruja ja Abigail. Serujan pojat olivat Abisai, Jooab ja Asael, kaikkiaan kolme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Abigail synnytti Amasan, ja Amasan isä oli ismaelilainen Jeter.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Kaalebille, Hesronin pojalle, syntyi lapsia Asubasta, hänen vaimostaan, ja Jeriotista. Nämä olivat Asuban pojat: Jeeser, Soobab ja Ardon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Kun Asuba kuoli, Kaaleb nai Efratin, ja tämä synnytti hänelle Huurin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Huurille syntyi Uuri, ja Uurille syntyi Besalel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Sen jälkeen Hesron meni Maakirin, Gileadin isän, tyttären luo ja nai tämän ollessaan kuudenkymmenen vuoden vanha. Tämä synnytti hänelle Segubin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Segubille syntyi Jaair. Tällä oli kaksikymmentä kolme kaupunkia Gileadin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Gesurilaiset ja aramilaiset ottivat heiltä Jaairin leirikylät ja Kenatin sekä sen tytärkaupungit, kuusikymmentä kaupunkia. Kaikki nämä olivat Maakirin, Gileadin isän, poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Kun Hesron oli kuollut Kaaleb-Efratassa, synnytti Abia – hän oli Hesronin vaimo – hänelle Ashurin, Tekoan isän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Jerahmeelin, Hesronin esikoisen, pojat olivat Raam, esikoinen, ja Buuna, Ooren, Oosem ja Ahia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Jerahmeelilla oli vielä toinen vaimo, jonka nimi oli Atara. Hän oli Oonamin äiti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Raamin, Jerahmeelin esikoisen, pojat olivat Maas, Jaamin ja Eeker.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Oonamin pojat olivat Sammai ja Jaada. Sammain pojat olivat Naadab ja Abisur.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Abisurin vaimon nimi oli Abihail, ja tämä synnytti hänelle Ahbanin ja Moolidin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Naadabin pojat olivat Seled ja Appaim. Seled kuoli lapsettomana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Appaimin poika oli Jisi, ja Jisin poika oli Seesan. Seesanin poika oli Ahlai.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Jaadan, Sammain veljen, pojat olivat Jeter ja Joonatan. Jeter kuoli lapsettomana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Joonatanin pojat olivat Pelet ja Saasa. Nämä olivat Jerahmeelin jälkeläisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Mutta Seesanilla ei ollut poikia, vaan ainoastaan tyttäriä. Seesanilla oli egyptiläinen palvelija, jonka nimi oli Jarha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Seesan antoi tyttärensä vaimoksi palvelijalleen Jarhalle, ja hän synnytti tälle Attain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Attaille syntyi Naatan, ja Naatanille syntyi Saabad.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Saabadille syntyi Eflal, ja Eflalille syntyi Oobed.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Oobedille syntyi Jeehu, ja Jeehulle syntyi Asarja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Asarjalle syntyi Heles, ja Helekselle syntyi Eleasa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Eleasalle syntyi Sismai, ja Sismaille syntyi Sallum.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Sallumille syntyi Jekamja, ja Jekamjalle syntyi Elisama.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Kaalebin, Jerahmeelin veljen, pojat olivat Meesa, hänen esikoisensa, joka oli Siifin isä, ja Maaresan, Hebronin isän, pojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Hebronin pojat olivat Koorah, Tappuuah, Rekem ja Sema.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Semalle syntyi Raham, Jorkeamin isä, ja Rekemille syntyi Sammai.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Sammain poika oli Maaon, ja Maaon oli Beet-Suurin isä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Eefa, Kaalebin sivuvaimo, synnytti Haaranin, Moosan ja Gaaseksen. Haaranille syntyi Gaases.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Jahdain pojat olivat Regem, Jootam, Geesan, Pelet, Eefa ja Saaf.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Maaka, Kaalebin sivuvaimo, synnytti Seberin ja Tirhanan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Hän synnytti myös Saafin, Madmannan isän, Sevan, Makbenan isän ja Gibean isän. Kaalebin tytär oli Aksa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Nämä olivat Kaalebin jälkeläisiä. Huurin, Efratan esikoisen, pojat olivat Soobal, Kirjat-Jearimin isä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, Beetlehemin isä, ja Haaref, Beet-Gaaderin isä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Soobalin, Kirjat-Jearimin isän, jälkeläiset olivat Rooe ja toinen puoli Menuhotia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'Kirjat-Jearimin suvut olivat jeteriläiset, puutilaiset, suumatilaiset ja misrailaiset. Heistä ovat soratilaiset ja estaolilaiset lähteneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Salman jälkeläiset olivat Beetlehem ja netofalaiset, Atrot, Beet-Jooab ja toinen puoli manahtilaisia, sorilaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'Kirjanoppineiden suvut, jotka asuivat Jaebeksessa, olivat tiratilaiset, simatilaiset ja sukatilaiset. Nämä olivat ne keeniläiset, jotka polveutuvat Hammatista, Reekabin suvun isästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Nämä ovat ne Daavidin pojat, jotka syntyivät hänelle Hebronissa: esikoinen Amnon, jisreeliläisestä Ahinoamista; toinen Daniel, karmelilaisesta Abigailista;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'kolmas Absalom, Maakan, Gesurin kuninkaan Talmain tyttären, poika; neljäs Adonia, Haggitin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'viides Sefatja, Abitalista; kuudes Jitream, hänen vaimostaan Eglasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Nämä kuusi syntyivät hänelle Hebronissa, jossa hän hallitsi seitsemän vuotta ja kuusi kuukautta. Mutta Jerusalemissa hän hallitsi kolmekymmentä kolme vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Nämä syntyivät hänelle Jerusalemissa: Simea, Soobab, Naatan ja Salomo, kaikkiaan neljä, Batsuuasta, Ammielin tyttärestä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'sitten Jibhar, Elisama, Elifelet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Noogah, Nefeg, Jaafia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elisama, Eljada ja Elifelet; kaikkiaan yhdeksän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Tässä ovat kaikki Daavidin pojat, lukuun ottamatta sivuvaimojen poikia. Taamar oli heidän sisarensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Salomon poika oli Rehabeam; tämän poika Abia; tämän poika Aasa; tämän poika Joosafat;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'tämän poika Jooram; tämän poika Ahasja; tämän poika Jooas;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'tämän poika Amasja; tämän poika Asarja; tämän poika Jootam;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'tämän poika Aahas; tämän poika Hiskia; tämän poika Manasse;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'tämän poika Aamon; tämän poika Joosia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Joosian pojat olivat esikoinen Joohanan, toinen Joojakim, kolmas Sidkia, neljäs Sallum.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Joojakimin pojat olivat hänen poikansa Jekonja ja tämän poika Sidkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Vangitun Jekonjan pojat olivat: hänen poikansa Sealtiel,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Malkiram, Pedaja, Senassar, Jekamja, Hoosama ja Nebadja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Pedajan pojat olivat Serubbaabel ja Siimei. Serubbaabelin pojat olivat Mesullam ja Hananja, ja heidän sisarensa oli Selomit;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'vielä Hasuba, Oohel, Berekja, Hasadja ja Juusab-Hesed, kaikkiaan viisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Hananjan pojat olivat Pelatja ja Jesaja, Refajan pojat, Arnanin pojat, Obadjan pojat ja Sekanjan pojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Sekanjan poika oli Semaja. Semajan pojat olivat Hattus, Jigal, Baariah, Nearja ja Saafat, kaikkiaan kuusi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Nearjan pojat olivat Eljoenai, Hiskia, Asrikam, kaikkiaan kolme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Eljoenain pojat olivat Hoodavja, Eljasib, Pelaja, Akkub, Joohanan, Delaja ja Anani, kaikkiaan seitsemän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Juudan pojat olivat Peres, Hesron, Karmi, Huur ja Soobal.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Reajalle, Soobalin pojalle, syntyi Jahat, ja Jahatille syntyivät Ahumai ja Lahad. Nämä ovat soratilaisten suvut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Nämä olivat Eetamin isän pojat: Jisreel, Jisma ja Jidbas, ja heidän sisarensa nimi oli Haslelponi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'vielä Penuel, Gedorin isä, ja Eeser, Huusan isä. Nämä olivat Huurin, Efratan esikoisen, Beetlehemin isän, pojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Ashurilla, Tekoan isällä, oli kaksi vaimoa, Hela ja Naara.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Naara synnytti hänelle Ahussamin, Heeferin, Teemenin ja ahastarilaiset. Nämä olivat Naaran pojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Helan pojat olivat Seret, Soohar ja Etnan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Koosille syntyivät Aanub ja Soobeba sekä Aharhelin, Haarumin pojan, suvut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Jabes oli suuremmassa arvossa pidetty kuin hänen veljensä. Hänen äitinsä oli antanut hänelle nimen Jabes sanoen: \"Olen synnyttänyt hänet kipuja kärsien.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Jabes huusi Israelin Jumalaa, sanoen: \"Jospa siunaisit minua ja laajentaisit alueeni. Jospa kätesi olisi kanssani ja varjelisit pahasta, että pääsisin kipuja kärsimästä!\" Jumala antoi hänen pyyntönsä toteutua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Kelubille, Suuhan veljelle, syntyi Mehir. Hän oli Estonin isä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Estonille syntyivät Beet-Raafa, Paaseah ja Tehinna, Naahaan kaupungin isä. Nämä olivat Reekan miehet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Kenaan pojat olivat Otniel ja Seraja. Otnielin pojat olivat: Hatat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Meonotaille syntyi Ofra. Serajalle syntyi Jooab, Seppienlaakson isä. Sillä he olivat seppiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Kaalebin, Jefunnen pojan, pojat olivat Iiru, Eela ja Naam sekä Eelan pojat ja Kenas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Jehallelelin pojat olivat Siif, Siifa, Tiireja ja Asarel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Esran pojat olivat Jeter, Mered, Eefer ja Jaalon. Vaimo tuli raskaaksi ja synnytti Mirjamin, Sammain ja Jisbahin, Estemoan isän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Hänen juudansukuinen vaimonsa synnytti Jeredin, Gedorin isän, Heberin, Sookon isän, ja Jekutielin, Saanoahin isän. Nämä olivat Bitjan, faraon tyttären, poikia, jonka Mered oli ottanut vaimokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Hoodian vaimon, Nahamin sisaren, pojat olivat Kegilan isä, garmilainen, ja maakatilainen Estemoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Siimonin pojat olivat Amnon ja Rinna, Ben-Haanan ja Tiilon. Jisin pojat olivat Soohet ja Soohetin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Seelan, Juudan pojan, pojat olivat Eer, Leekan isä, Lada, Maaresan isä, ja pellavakankaiden kutojien suvut Beet-Asbeasta;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'Jookim ja Kooseban miehet sekä Jooas ja Saaraf, jotka hallitsivat Mooabia, ja Jaasubi-Lehem. Mutta nämä ovat vanhoja asioita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'He olivat niitä savenvalajia, jotka asuvat Netaimissa ja Gederassa. He asuivat siellä kuninkaan luona ja olivat hänen työssään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Simeonin pojat olivat Nemuel ja Jaamin, Jaarib, Sera ja Saul.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Tämän poika oli Sallum, tämän poika Mibsam, tämän poika Misma.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Misman pojat olivat: hänen poikansa Hammuel, tämän poika Sakkur ja tämän poika Siimei.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Siimeillä oli kuusitoista poikaa ja kuusi tytärtä, mutta hänen veljillään ei ollut monta lasta, eikä koko heidän sukunsa lisääntynyt Juudan lasten määrään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'He asuivat Beersebassa, Mooladassa ja Hasar-Suualissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'Bilhassa, Esemissä ja Tooladissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'Betuelissa, Hormassa ja Siklagissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'Beet-Markabotissa, Hasar-Suusimissa, Beet-Birissä ja Saaraimissa. Nämä olivat heidän kaupunkinsa Daavidin hallitukseen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Heidän kylänsä olivat Eetam, Ain, Rimmon, Tooken ja Aasan – viisi kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'Siihen tulivat lisäksi kaikki ne heidän kylänsä, jotka olivat näiden kaupunkien ympärillä, aina Baaliin asti. Nämä olivat heidän asuinpaikkansa ja heillä oli omat sukuluettelonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Vielä: Mesobab, Jamlek, Joosa, Amasjan poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Jooel, Jeehu, Joosibjan poika, joka oli Serajan poika, joka Asielin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'Eljoenai, Jaakoba, Jesohaja, Asaja, Adiel, Jesimiel, Benaja');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'ja Siisa, Sifin poika, joka oli Allonin poika, joka Jedajan poika, joka Simrin poika, joka Semajan poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Nämä nimeltä mainitut olivat sukujensa ruhtinaita, ja heidän perhekuntansa olivat levinneet ja lisääntyneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'He kulkivat Gedoriin päin, aina laakson itäiseen osaan saakka hakeakseen laidunta lampailleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'He löysivät lihavan ja hyvän laitumen, ja maa oli tilava joka suuntaan sekä rauhallinen ja levollinen, sillä ne, jotka olivat asuneet siellä ennen, olivat haamilaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Mutta nämä nimeltä luetellut tulivat Hiskian, Juudan kuninkaan, päivinä ja valtasivat heidän telttansa ja voittivat meunilaiset, jotka olivat siellä, ja vihkivät heidät tuhon omiksi, aina tähän päivään asti, ja asettuivat heidän sijaansa, sillä siellä oli laidunta heidän lampailleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Heistä, simeonilaisista, meni viisisataa miestä Seirin vuoristoon, ja heidän etunenässään olivat Pelatja, Nearja, Refaja ja Ussiel, Jisin pojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'He surmasivat ne, jotka olivat jäljellä pelastuneista amalekilaisista, ja jäivät sinne asumaan aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Ruubenin, Israelin esikoisen, pojat olivat – hän oli näet esikoinen, mutta koska hän saastutti isänsä vuoteen, annettiin hänen esikoisuutensa Joosefin, Israelin pojan, pojille, kuitenkin niin, ettei heitä merkitty sukuluetteloon esikoisina,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'sillä Juuda tuli voimallisimmaksi veljiensä joukossa, ja yhdestä hänen jälkeläisistään tuli ruhtinas, mutta esikoisuus joutui Joosefille –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Ruubenin, Israelin esikoisen, pojat olivat Hanok ja Pallu, Hesron ja Karmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Jooelin pojat olivat: hänen poikansa Semaja, tämän poika Goog, tämän poika Siimei,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'tämän poika Miika, tämän poika Reaja, tämän poika Baal');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'ja tämän poika Beera, jonka Assurin kuningas Tillegat-Pilneser vei karkotukseen. Hän oli ruubenilaisten ruhtinas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Hänen veljensä olivat sukujensa mukaan, kun heidät merkittiin sukuluetteloon heidän polveutumisensa mukaan: Jegiel, päämies, Sakarja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'Bela, Aasaan poika, joka oli Seman poika, joka Jooelin poika. Hän asui Aroerissa ja aina Neboon ja Baal-Meoniin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Idässä hän asui erämaahan saakka, joka alkaa Eufrat-virrasta, sillä heillä oli suuria karjalaumoja Gileadin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Mutta Saulin päivinä he kävivät sotaa hagrilaisia vastaan, ja kun nämä olivat joutuneet heidän käsiinsä, he asettuivat heidän telttoihinsa Gileadin koko itäistä rajaseutua myöten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Gaadilaiset asuivat heidän kanssaan rajanaapureina Baasanin maassa Salkaan saakka:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Jooel päämiehenä ja Saafam toisena, sitten Janai ja Saafat Baasanissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Heidän veljensä olivat, perhekuntiensa mukaan: Miikael, Mesullam, Seba, Joorai, Jakan, Siia ja Eeber, kaikkiaan seitsemän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Nämä olivat Abihailin pojat, joka oli Huurin poika, joka Jaaroahin poika, joka Gileadin poika, joka Miikaelin poika, joka Jesisain poika, joka Jahdon poika, joka Buusin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Ahi, Abdielin poika, joka oli Guunin poika, oli heidän perhekuntiensa päämies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'He asuivat Gileadissa, Baasanissa ja sen tytärkaupungeissa sekä kaikilla Saaronin laidunmailla, niin kauas kuin ne ulottuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Kaikki nämä merkittiin sukuluetteloon Juudan kuninkaan Jootamin ja Israelin kuninkaan Jerobeamin päivinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa – sotakuntoisia miehiä, jotka kantoivat kilpeä ja miekkaa ja jännittivät jousta ja olivat taisteluun harjaantuneita, neljäkymmentäneljä tuhatta seitsemänsataa kuusikymmentä sotakelpoista miestä –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'kävivät sotaa hagrilaisia, Jeturia, Naafista ja Noodabia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'He saivat apua näitä vastaan, niin että hagrilaiset ja kaikki, jotka olivat heidän kanssaan, joutuivat heidän käsiinsä. Sillä he huusivat taistelussa Jumalan puoleen, ja hän kuuli heidän rukouksensa, koska he turvasivat häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'He veivät saaliinaan heidän karjansa, viisikymmentä tuhatta kamelia, kaksisataa viisikymmentä tuhatta lammasta ja kaksituhatta aasia, sekä satatuhatta ihmistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Paljon oli surmattuina kaatuneita, sillä sota oli Jumalan sota. He asettuivat asumaan heidän sijaansa aina karkotukseen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Toinen puoli Manassen sukukuntaa asui siinä maassa, Baasanista aina Baal-Hermoniin ja Seniriin ja Hermon-vuoreen saakka. Heitä oli paljon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Nämä olivat heidän perhekuntiensa päämiehet: Eefer, Jisi, Eliel, Asriel, Jeremia, Hoodavja ja Jahdiel, väkeviä sankareita, nimekkäitä miehiä, perhekuntiensa päämiehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Mutta he tulivat uskottomiksi isiensä Jumalaa kohtaan ja juoksivat haureudessa maan kansojen jumalien perässä, niiden kansojen, jotka Jumala oli hävittänyt heidän edeltään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Niin Israelin Jumala herätti Puulin, Assurin kuninkaan, hengen ja Tillegat-Pilneserin, Assurin kuninkaan, hengen ja kuljetutti heidät, ruubenilaiset, gaadilaiset ja toisen puolen Manassen sukukuntaa, karkotukseen ja antoi viedä heidät Halahiin, Haaboriin, Haaraan ja Goosanin joen rannoille, missä he tänäkin päivänä ovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 27, 'Leevin pojat olivat Geerson, Kehat ja Merari.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 28, 'Kehatin pojat olivat Amram, Jishar, Hebron ja Ussiel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 29, 'Amramin lapset olivat Aaron, Mooses ja Mirjam. Aaronin pojat olivat Naadab, Abihu, Eleasar ja Iitamar.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 30, 'Eleasarille syntyi Piinehas, Piinehaalle syntyi Abisua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 31, 'Abisualle syntyi Bukki, ja Bukille syntyi Ussi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 32, 'Ussille syntyi Serahja, ja Serahjalle syntyi Merajot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 33, 'Merajotille syntyi Amarja, ja Amarjalle syntyi Ahitub.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 34, 'Ahitubille syntyi Saadok, ja Saadokille syntyi Ahimaas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 35, 'Ahimaasille syntyi Asarja, ja Asarjalle syntyi Joohanan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 36, 'Joohananille syntyi Asarja, hän joka toimitti papinvirkaa temppelissä, jonka Salomo rakennutti Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 37, 'Asarjalle syntyi Amarja, ja Amarjalle syntyi Ahitub.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 38, 'Ahitubille syntyi Saadok, ja Saadokille syntyi Sallum.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 39, 'Sallumille syntyi Hilkia, ja Hilkialle syntyi Asarja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 40, 'Asarjalle syntyi Seraja, ja Serajalle syntyi Jehosadak.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 41, 'Mutta Jehosadakin oli lähdettävä mukaan silloin, kun Herra antoi Nebukadnessarin viedä Juudan ja Jerusalemin karkotukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Leevin pojat olivat Geersom, Kehat ja Merari.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Nämä ovat Geersomin poikien nimet: Libni ja Siimei.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Kehatin pojat olivat Amram, Jishar, Hebron ja Ussiel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Merarin pojat olivat Mahli ja Muusi. Nämä olivat leeviläisten suvut heidän isiensä mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Geersomista polveutuivat hänen poikansa Libni, tämän poika Jahat, tämän poika Simma,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'tämän poika Jooah, tämän poika Iddo, tämän Sera ja tämän poika Jeatrai.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Kehatin pojat olivat: hänen poikansa Amminadab, tämän poika Koorah, tämän poika Assir,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'tämän poika Elkana, tämän poika Ebjasaf, tämän poika Assir,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'tämän poika Tahat, tämän poika Uuriel, tämän poika Ussia ja tämän poika Saul.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Elkanan pojat olivat Amasai ja Ahimot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Elkana: Elkanan pojat, Suufai, tämän poika Nahat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'tämän poika Eliab, tämän poika Jeroham, tämän poika Elkana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Samuelin pojat olivat esikoinen Vasni ja Abia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Merarin pojat olivat: Mahli, tämän poika Libni, tämän poika Siimei, tämän poika Ussa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'tämän poika Simea, tämän poika Haggia ja tämän poika Asaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Nämä ovat ne, jotka Daavid asetti pitämään huolta laulusta Herran temppelissä, sen jälkeen kun arkki oli saanut leposijan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'He palvelivat veisaajina ilmestysmajan asumuksen edessä, kunnes Salomo rakensi Herran temppelin Jerusalemiin. He toimittivat virkaansa, kuten heille oli säädetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Nämä ovat ne, jotka palvelivat, ja nämä heidän poikansa: Kehatilaisia: Heeman, veisaaja, Jooelin poika, joka oli Samuelin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'joka Elkanan poika, joka Jerohamin poika, joka Elielin poika, joka Tooahin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'joka Suufin poika, joka Elkanan poika, joka Mahatin poika, joka Amasain poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'joka Elkanan poika, joka Jooelin poika, joka Asarjan poika, joka Sefanjan poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'joka Tahatin poika, joka Assirin poika, joka Ebjasafin poika, joka Koorahin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'joka Jisharin poika, joka Kehatin poika, joka Leevin poika, joka Israelin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Ja hänen veljensä Aasaf, joka seisoi hänen oikealla puolellaan, Aasaf, Berekjan poika, joka oli Simean poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'joka Miikaelin poika, joka Baasejan poika, joka Malkian poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'joka Etnin poika, joka Seran poika, joka Adajan poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'joka Eetanin poika, joka Simman poika, joka Siimein poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'joka Jahatin poika, joka Geersomin poika, joka Leevin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Heidän veljensä, Merarin pojat, vasemmalla puolella: Eetan, Kiisin poika, joka oli Abdin poika, joka Mallukin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'joka Hasabjan poika, joka Amasjan poika, joka Hilkian poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'joka Amsin poika, joka Baanin poika, joka Semerin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'joka Mahlin poika, joka Muusin poika, joka Merarin poika, joka Leevin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Heidän veljensä, leeviläiset, olivat annetut toimittamaan kaikkinaista palvelusta Jumalan temppeliasumuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Mutta Aaron ja hänen poikansa polttivat uhreja polttouhrialttarilla ja suitsutusalttarilla, toimittivat kaikki tehtävät kaikkeinpyhimmässä ja Israelin sovituksen, aivan niin kuin Jumalan palvelija Mooses oli käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Nämä olivat Aaronin pojat: hänen poikansa Eleasar, tämän poika Piinehas, tämän poika Abisua,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'tämän poika Bukki, tämän poika Ussi, tämän poika Serahja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'tämän poika Merajot, tämän poika Amarja, tämän poika Ahitub,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'tämän poika Saadok, tämän poika Ahimaas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Nämä olivat heidän asuinpaikkansa, heidän leiripaikkojensa mukaan, heidän alueellaan: Niille Aaronin jälkeläisille, jotka olivat kehatilaisten sukua, sillä he saivat arpaosan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'annettiin Hebron Juudan maasta, ympärillä olevine laidunmaineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Mutta kaupungin peltomaat kylineen annettiin Kaalebille, Jefunnen pojalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Aaronin jälkeläisille annettiin turvakaupungit Hebron, Libna laidunmaineen, Jattir, Estemoa laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Hiilen laidunmaineen, Debir laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Aasan laidunmaineen ja Beet-Semes laidunmaineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Benjaminin sukukunnasta Geba laidunmaineen, Aalemet laidunmaineen ja Anatot laidunmaineen. Heidän kaupunkejaan oli kaikkiaan kolmetoista kaupunkia, heidän sukujensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Muut kehatilaiset saivat arvalla sukujensa mukaan Efraimin sukukunnalta, Daanin sukukunnalta ja toiselta puolelta Manassen sukukuntaa kymmenen kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Geersomilaiset saivat sukujensa mukaan Isaskarin sukukunnalta, Asserin sukukunnalta, Naftalin sukukunnalta ja Manassen sukukunnalta Baasanista kolmetoista kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Merarilaiset saivat arvalla sukujensa mukaan Ruubenin sukukunnalta, Gaadin sukukunnalta ja Sebulonin sukukunnalta kaksitoista kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Israelilaiset antoivat leeviläisille nämä kaupungit laidunmaineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'He antoivat arvalla Juudan lasten sukukunnasta, simeonilaisten sukukunnasta ja benjaminilaisten sukukunnasta nämä nimeltä mainitut kaupungit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Kehatilaisten suvuista muutamat saivat arvalla Efraimin sukukunnalta alueekseen seuraavat kaupungit:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'heille annettiin turvakaupungit Sikem laidunmaineen Efraimin vuoristosta, Geser laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Jokmeam laidunmaineen, Beet-Hooron laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Aijalon laidunmaineen ja Gat-Rimmon laidunmaineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'Toisesta puolesta Manassen sukukuntaa Aaner laidunmaineen ja Bileam laidunmaineen. Nämä tulivat muitten kehatilaisten suvuille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Geersomilaiset saivat sukujensa mukaan toiselta puolelta Manassen sukukuntaa Goolanin laidunmaineen Baasanista ja Astarotin laidunmaineen;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'ja Isaskarin sukukunnalta Kedeksen laidunmaineen, Dobratin laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Raamotin laidunmaineen ja Aanemin laidunmaineen;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'ja Asserin sukukunnalta Maasalin laidunmaineen, Abdonin laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Huukokin laidunmaineen ja Rehobin laidunmaineen;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'ja Naftalin sukukunnalta Kedeksen laidunmaineen Galileasta, Hammonin laidunmaineen ja Kirjataimin laidunmaineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Muut merarilaiset saivat Sebulonin sukukunnalta Rimmonin laidunmaineen ja Taaborin laidunmaineen;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'ja tuolta puolelta Jerikon Jordanin, Jordanista auringonnousuun päin, Ruubenin sukukunnalta Beserin laidunmaineen erämaasta, Jahaan laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Kedemotin laidunmaineen, Meefatin laidunmaineen;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'ja Gaadin sukukunnalta Raamotin laidunmaineen Gileadista, Mahanaimin laidunmaineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Hesbonin laidunmaineen ja Jaeserin laidunmaineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Isaskarin pojat olivat Toola, Puua, Jaasub ja Simron, kaikkiaan neljä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Toolan pojat olivat Ussi, Refaja, Jeriel, Jahmai, Jibsam ja Samuel, jotka olivat perhekuntiensa päämiehiä, Toolan jälkeläisiä, väkeviä sankareita, polveutumisensa mukaan. Daavidin aikana oli heidän lukumääränsä kaksikymmentäkaksi tuhatta kuusisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Ussin poika oli Jisrahja, ja Jisrahjan pojat olivat Miikael, Obadja, Jooel ja Jissia, kaikkiaan viisi, kaikki päämiehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Heitä seurasi polveutumisensa ja perhekuntiensa mukaan taisteluun valmiina sotajoukkoina kolmekymmentäkuusi tuhatta miestä, sillä heillä oli paljon vaimoja ja lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Heidän veljensä, kaikissa Isaskarin suvuissa, olivat väkeviä sankareita. Sukuluetteloihin heitä oli merkitty kaikkiaan kahdeksankymmentäseitsemän tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Benjaminin [poikia olivat]: Bela, Beker ja Jediael, kaikkiaan kolme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Belan pojat olivat Esbon, Ussi, Ussiel, Jerimot ja Iiri, kaikkiaan viisi, perhekuntapäämiehiä, väkeviä sankareita. Sukuluetteloihin heitä oli merkitty kaksikymmentäkaksi tuhatta kolmekymmentä neljä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Bekerin pojat olivat Semira, Jooas, Elieser, Eljoenai, Omri, Jeremot, Abia, Anatot ja Aalemet; kaikki nämä olivat Bekerin poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'Heitä oli sukuluetteloihin merkitty polveutumisensa mukaan, perhekuntapäämiestensä, väkevien sankareiden, mukaan, kaksikymmentä tuhatta kaksisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Jediaelin poika oli Bilhan, ja Bilhanin pojat olivat Jeus, Benjamin, Eehud, Kenaana, Seetan, Tarsis ja Ahisahar.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Kaikki nämä olivat Jediaelin poikia perhekuntapäämiesten, väkevien sankareiden, mukaan; seitsemäntoista tuhatta kaksisataa sotakelpoista miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Suppim ja Huppim olivat Iirin poikia; Huusim oli Aherin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Naftalin pojat olivat Jahasiel, Guuni, Jeeser ja Sallum, Bilhan jälkeläisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Manassen poika oli Asriel, jonka hänen aramilainen sivuvaimonsa synnytti. Tämä synnytti Maakirin, Gileadin isän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Maakir otti vaimon Huppimille ja Suppimille, ja hänen sisarensa nimi oli Maaka. Toisen nimi oli Selofhad; ja Selofhadilla oli tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Maaka, Maakirin vaimo, synnytti pojan, jolle hän antoi nimen Peres; hänen veljensä nimi oli Seres, ja hänen poikansa olivat Uulam ja Rekem.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Uulamin poika oli Bedan. Nämä olivat Gileadin pojat, joka oli Maakirin poika, joka Manassen poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Hänen sisarensa Mooleket synnytti Iishodin, Abieserin ja Mahlan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Semidan pojat olivat Ahjan, Sekem, Likhi ja Aniam.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Efraimin pojat olivat: Suutelah, tämän poika Bered, tämän poika Tahat, tämän poika Elada, tämän poika Tahat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'tämän poika Saabad, tämän poika Suutelah, sekä Eser ja Elead. Gatin miehet, siinä maassa syntyneet, tappoivat heidät, koska he olivat lähteneet ottamaan heidän karjaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Heidän isänsä Efraim suri pitkät ajat, ja hänen veljensä tulivat lohduttamaan häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Sitten hän yhtyi vaimoonsa, ja tämä tuli raskaaksi ja synnytti pojan. Hän antoi tälle nimen Beria, koska se oli tapahtunut hänen perheensä onnettomuuden aikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Hänen tyttärensä oli Seera. Tämä rakensi Ala- ja Ylä-Beet-Hooronin sekä Ussen-Seeran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Berian poika oli Refah, samoin Resef, tämän poika Telah, tämän poika Tahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'tämän poika Ladan, tämän poika Ammihud, tämän poika Elisama,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'tämän poika Nuun ja tämän poika Joosua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Heidän perintömaansa ja asuinpaikkansa olivat Beetel ja sen tytärkaupungit, itään Naaran ja länteen Geser ja sen tytärkaupungit, sekä Sikem ja sen tytärkaupungit, aina Aijaan ja sen tytärkaupunkeihin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Manasselaisten hallussa olivat Beet-Sean ja sen tytärkaupungit, Taanak ja sen tytärkaupungit, Megiddo ja sen tytärkaupungit, Door ja sen tytärkaupungit. Näissä asuivat Joosefin, Israelin pojan, jälkeläiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Asserin pojat olivat Jimna, Jisva, Jisvi ja Beria, heidän sisarensa oli Serah.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Berian pojat olivat Heber ja Malkiel. Tämä oli Birsaitin isä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Heberille syntyi Jaflet, Soomer, Hootam ja heidän sisarensa Suua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Jafletin pojat olivat Paasak, Bimhal ja Asva. Nämä ovat Jafletin pojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Semerin pojat olivat Ahi, Rohga, Hubba ja Aram.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Hänen veljensä Heelemin pojat olivat Soofah, Jimna, Seeles ja Aamal.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Soofahin pojat olivat Suuah, Harnefer, Suual, Beeri, Jimra,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Beser, Hood, Samma, Silsa, Jitran ja Beera.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Jeterin pojat olivat Jefunne, Fispa ja Ara.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Ullan pojat olivat Aarah, Hanniel ja Risja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Kaikki nämä olivat Asserin jälkeläisiä, perhekuntien päämiehiä, väkeviä sankareita, ruhtinaiden päämiehiä. Heidän sukuluetteloihin merkittyjen sotakelpoisten miestensä lukumäärä oli kaksikymmentäkuusi tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Benjaminille syntyi esikoisena Bela, toisena Asbel, kolmantena Ahrah,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'neljäntenä Nooha ja viidentenä Raafa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Belalla oli pojat: Addar, Geera, Abihud,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abisua, Naaman, Ahoah,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Geera, Sefufan ja Huuram.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Nämä olivat Eehudin pojat – nämä olivat Geban asukkaiden perhekuntien päämiehet. Heidät siirrettiin pois Manahatiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'myös Naaman, Ahia ja Geera. Hän siirsi heidät pois. Hänelle syntyi Ussa ja Ahihud.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Saharaimille syntyi Mooabin maassa, sitten kun hän oli hylännyt vaimonsa Huusimin ja Baaran,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'hänelle syntyi hänen vaimostaan Hoodeksesta Joobab, Sibja, Meesa, Malkam,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jeus, Sokja ja Mirma. Nämä olivat hänen poikiansa, perhekuntien päämiehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Huusimista oli hänelle syntynyt Abitub ja Elpaal.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Elpaalin pojat olivat Eeber, Misam ja Semed. Tämä rakensi Oonon ja Loodin sekä sen tytärkaupungit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Beria ja Sema olivat Aijalonin asukkaiden perhekuntien päämiehiä. He karkottivat Gatin asukkaat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'he ja Ahjo, Saasak ja Jeremot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Sebadja, Arad, Eder,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Miikael, Jispa ja Jooha olivat Berian poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Sebadja, Mesullam, Hiski, Heber,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Jismerai, Jislia ja Joobab olivat Elpaalin poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Jaakim, Sikri, Sabdi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elienai, Silletai, Eliel,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaja, Beraja ja Simrat olivat Siimein poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Jispan, Eder, Eliel,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Sikri, Haanan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Hananja, Eelam, Antotia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Jifdeja ja Penuel olivat Saasakin poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Samserai, Seharja, Atalja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaaresja, Elia ja Sikri olivat Jerohamin poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Nämä olivat perhekuntien päämiehiä, päämiehiä polveutumisensa mukaan. He asuivat Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'Gibeonissa asui Gibeonin isä, jonka vaimon nimi oli Maaka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Hänen esikoispoikansa oli Abdon, sitten Suur, Kiis, Baal, Naadab,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedor, Ahjo ja Seker.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Miklotille syntyi Simea. Hekin asuivat veljineen Jerusalemissa, rajakkain veljiensä kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Neerille syntyi Kiis, Kiisille syntyi Saul, ja Saulille syntyi Joonatan, Malkisua, Abinadab ja Esbaal.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Joonatanin poika oli Meribbaal, ja Meribbaalille syntyi Miika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Miikan pojat olivat Piiton, Melek, Tarea ja Aahas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Aahaalle syntyi Jooadda, Jooaddalle syntyi Aalemet, Asmavet ja Simri. Simrille syntyi Moosa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'ja Moosalle syntyi Binea. Hänen poikansa oli Raafa, tämän poika Elasa ja tämän poika Aasel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Aaselilla oli kuusi poikaa, ja nämä ovat heidän nimensä: Asrikam, Bookeru, Jismael, Searja, Obadja ja Haanan. Nämä kaikki olivat Aaselin poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Eesekin, hänen veljensä, pojat olivat: hänen esikoisensa Uulam, toinen Jeus ja kolmas Elifelet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Uulamin pojat olivat väkeviä sankareita, jousen jännittäjiä, ja heillä oli paljon poikia ja poikien poikia, sataviisikymmentä. Nämä kaikki ovat benjaminilaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Koko Israel merkittiin sukuluetteloon, ja katso, he ovat kirjoitetut Israelin kuningasten kirjaan. Mutta Juuda vietiin Baabeliin karkotukseen uskottomuutensa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Entiset asukkaat, jotka elivät perintömaillaan, kaupungeissaan, olivat israelilaisia, pappeja, leeviläisiä ja temppelipalvelijoita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Jerusalemissa oli asunut Juudan lapsia, benjaminilaisia, efraimilaisia ja manasselaisia, nimittäin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Uutai, Ammihudin poika, joka oli Omrin poika, joka Imrin poika, joka Baanin poika, Pereksen, Juudan pojan, jälkeläisiä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'seelalaisia: Asaja, esikoinen, ja hänen poikansa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'serahilaisia: Jeguel ja hänen veljensä, kuusisataa yhdeksänkymmentä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'benjaminilaisia: Sallu, Mesullamin poika, joka oli Hoodavjan poika, joka Senuan poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'Jibneja, Jerohamin poika, Eela, Ussin poika, joka oli Mikrin poika, ja Mesullam, Sefatjan poika, joka oli Reguelin poika, joka Jibnean poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'sekä heidän veljensä, heidän polveutumisensa mukaan, yhdeksänsataa viisikymmentä kuusi. Kaikki nämä olivat perhekuntien päämiehiä perhekunnissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Pappeja: Jedaja, Joojarib, Jaakin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Asarja, Hilkian poika, joka oli Mesullamin poika, joka Saadokin poika, joka Merajotin poika, joka Ahitubin poika, Jumalan temppelin esimies;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'Adaja, Jerohamin poika, joka oli Pashurin poika, joka Malkian poika, ja Maesai, Adielin poika, joka oli Jahseran poika, joka Mesullamin poika, joka Mesillemitin poika, joka Immerin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'sekä heidän veljensä, heidän perhekuntiensa päämiehet, tuhat seitsemänsataa kuusikymmentä miestä, kelvollisia toimittamaan palvelusta Jumalan temppelissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Leeviläisiä: Semaja, Hassubin poika, joka oli Asrikamin poika, joka Hasabjan poika, merarilaisia;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'Bakbakkar, Heres, Gaalal, Mattanja, Miikan poika, joka oli Sikrin poika, joka Aasafin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Obadja, Semajan poika, joka oli Gaalalin poika, joka Jedutunin poika; ja Berekja, Aasan poika, joka oli Elkanan poika, hänen, joka asui netofalaisten kylissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Ovenvartijat: Sallum, Akkub, Talmon ja Ahiman veljineen: Sallum oli päämies,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'ja tähän saakka hän on ollut vartijana Kuninkaan portilla, idän puolella. Nämä olivat ovenvartijoina leeviläisten leirissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Mutta Sallumilla, Kooren pojalla, joka oli Ebjasafin poika, joka Koorahin poika, ja hänen veljillään, jotka olivat hänen perhekuntaansa – koorahilaisilla, oli palvelustehtävänä telttamajan kynnysten vartioiminen; heidän isänsä olivat näet vartioineet sisäänkäyntiä Herran leirissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Piinehas, Eleasarin poika, oli muinoin heidän esimiehenään – Herra olkoon hänen kanssaan! –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Sakarja, Meselemjan poika, oli ovenvartijana ilmestysmajan ovella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Kaikkiaan oli kynnysten ovenvartijoiksi valittuja kaksisataa kaksitoista. He olivat kylissään merkityt sukuluetteloon. Daavid ja Samuel, näkijä, olivat asettaneet heidät heidän luottamustoimeensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'He ja heidän poikansa olivat vartijoina Herran temppelin, telttapyhäkön, ovilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Ovenvartijat olivat asetetut neljälle ilmansuunnalle: idän, lännen, pohjoisen ja etelän puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Heidän veljiensä, jotka asuivat kylissään, oli aina määräaikoina seitsemäksi päiväksi tultava toimittamaan palvelusta yhdessä heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Sillä nämä neljä ylintä ovenvartijaa olivat pysyvästi luottamustoimessaan. Nämä olivat leeviläisiä. Heidän oli myös valvottava kammioita ja Jumalan temppelin aarteita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'He viettivät yönsä Jumalan temppelin ympärillä, sillä heidän tehtävänään oli vartiointi ja heidän oli huolehdittava ovien avaamisesta joka aamu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Muutamien heistä oli huolehdittava jumalanpalveluksessa tarvittavasta kalustosta, sillä heidän oli tuotava se sisään täysilukuisena ja vietävä se ulos täysilukuisena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Muutamat heistä olivat määrätyt pitämään huolta kalustosta, koko pyhästä kalustosta, sekä ydinjauhoista, viinistä, öljystä, suitsukkeista ja hajuaineista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Muutamat pappien pojista valmistivat voiteita hajuaineista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Mattitjalla, joka oli leeviläisiä ja oli koorahilaisen Sallumin esikoinen, oli luottamustoimena leivonnaisten valmistus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Muutamien kehatilaisista, heidän veljistään, oli huolehdittava näkyleivistä ja valmistettava ne joka sapatiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Mutta veisaajat, leeviläisten perhekuntien päämiehet, oleskelivat kammioissa, muusta palveluksesta vapaina, sillä he olivat toimessa sekä päivällä että yöllä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'He olivat leeviläisten perhekuntien päämiehiä, päämiehiä polveutumisensa mukaan. He asuivat Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'Gibeonissa asuivat Gibeonin isä, jonka vaimon nimi oli Maaka,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'hänen esikoispoikansa Abjon, sitten Suur, Kiis, Baal, Neer, Naadab,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedor, Ahjo, Sakarja ja Mikleot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Mikleotille syntyi Simeam. Hekin asuivat veljineen Jerusalemissa, rajakkain veljiensä kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Neerille syntyi Kiis, Kiisille syntyi Saul, ja Saulille syntyi Joonatan, Malkisua, Abinadab ja Esbaal.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Joonatanin poika oli Meribbaal, ja Meribbaalille syntyi Miika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Miikan pojat olivat Piiton, Melek ja Tahrea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Aahaalle syntyi Jaera, Jaeralle syntyi Aalemet, Asmavet ja Simri. Simrille syntyi Moosa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'ja Moosalle syntyi Binea, hänen poikansa oli Refaja, tämän poika Elasa ja tämän poika Aasel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Aaselilla oli kuusi poikaa, ja nämä ovat heidän nimensä: Asrikam, Bookeru, Jismael, Searja, Obadja ja Haanan. Nämä olivat Aaselin pojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Filistealaiset taistelivat Israelia vastaan, ja Israelin miehet pakenivat filistealaisia, ja heitä kaatui surmattuina Gilboan vuorella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Filistealaiset pääsivät Saulin ja hänen poikiensa kintereille, ja filistealaiset surmasivat Joonatanin, Abinadabin ja Malkisuan, Saulin pojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Kun taistelu kiihtyi ankaraksi Saulia vastaan ja jousimiehet keksivät hänet, hän joutui hätään jousimiesten ahdistaessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Saul sanoi aseenkantajalleen: \"Paljasta miekkasi ja lävistä sillä minut, etteivät nuo ympärileikkaamattomat tulisi pitämään minua pilkkanaan.\" Mutta hänen aseenkantajansa ei tahtonut, sillä hän pelkäsi kovin. Saul otti itse miekan ja heittäytyi siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Mutta kun hänen aseenkantajansa näki, että Saul oli kuollut, hänkin heittäytyi miekkaansa ja kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Niin kuolivat Saul ja hänen kolme poikaansa sekä koko hänen perheensä. He kuolivat yhdessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Kun kaikki Israelin miehet, jotka asuivat tasangolla, huomasivat, että he olivat paenneet ja että Saul poikineen oli kuollut, he jättivät kaupunkinsa ja pakenivat, ja filistealaiset tulivat ja asettuivat niihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Seuraavana päivänä filistealaiset tulivat ryöstämään surmattuja ja löysivät Saulin ja hänen poikansa kaatuneina Gilboan vuorelta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'He ryöstivät hänet ja ottivat hänen päänsä ja hänen aseensa ja lähettivät ne ympäri filistealaisten maata julistaakseen voitonsanomaa epäjumalilleen ja kansalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'He asettivat hänen aseensa jumalansa temppeliin, ja hänen pääkallonsa he kiinnittivät Daagonin temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Kun koko Gileadin Jaabes kuuli, mitä kaikkea filistealaiset olivat tehneet Saulille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'he nousivat, kaikki asekuntoiset miehet, ja ottivat Saulin ja hänen poikiensa ruumiit ja toivat ne Jaabekseen. He hautasivat heidän luunsa tammen alle Jaabekseen ja paastosivat seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Saul kuoli, koska hän oli ollut uskoton Herraa kohtaan eikä ollut ottanut vaarin Herran sanasta, ja myös sen tähden, että hän oli kysynyt vainajahengeltä neuvoa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'mutta ei ollut kysynyt neuvoa Herralta. Sen tähden hän surmasi hänet ja siirsi kuninkuuden Daavidille, Iisain pojalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Koko Israel kokoontui Daavidin luo Hebroniin, ja he sanoivat: \"Katso, me olemme luutasi ja lihaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Jo kauan sitten Saulin vielä ollessa kuninkaana sinä sait Israelin lähtemään ja tulemaan. Sinulle on Herra, Jumalasi, sanonut: \'Sinä olet kaitseva kansaani Israelia, ja sinä olet oleva kansani Israelin ruhtinas.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Kaikki Israelin vanhimmat tulivat kuninkaan luo Hebroniin, ja Daavid teki heidän kanssaan liiton Hebronissa Herran edessä. He voitelivat Daavidin Israelin kuninkaaksi sen sanan mukaan, jonka Herra oli puhunut Samuelin kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Daavid ja koko Israel menivät Jerusalemiin, se on Jebukseen, ja siellä olivat jebusilaiset, jotka asuivat siinä maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Jebuksen asukkaat sanoivat Daavidille: \"Tänne et tule.\" Mutta Daavid valloitti Siionin Vuorilinnan, se on Daavidin kaupungin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Daavid sanoi: \"Joka ensimmäisenä surmaa jebusilaisen, hän on oleva päämies ja päällikkö.\" Jooab, Serujan poika, tuli ensimmäisenä sinne ylös, ja niin hänestä tuli päämies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Daavid asettui Vuorilinnaan. Sen tähden sitä kutsuttiin Daavidin kaupungiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Hän rakensi kaupunkia joka taholle, Millosta [vuoren] reunoihin asti. Jooab rakensi entiselleen muun osan kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Daavid tuli yhä suuremmaksi, ja Herra Sebaot oli hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Nämä ovat ensimmäiset Daavidin sankareista, jotka voimakkaasti auttoivat häntä kuninkuuteen yhdessä koko Israelin kanssa tehdäkseen hänet Israelin kuninkaaksi Herran sanan mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Tämä on Daavidin sankareiden luettelo: Jaasobeam, hakmonilaisen poika, niiden kolmen päällikkö, hän, joka oli heiluttanut keihästään kolmensadan kaatuneen yli yhdellä kertaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Hänen jälkeensä Eleasar, Doodon poika, ahohilainen, yksi niistä kolmesta sankarista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Hän oli Daavidin kanssa Pas-Dammimissa, kun filistealaiset olivat kokoontuneet sinne sotimaan. Siellä oli peltopalsta täynnä ohraa. Väki pakeni filistealaisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'mutta he asettuivat keskelle palstaa, saivat sen pelastetuksi ja voittivat filistealaiset. Herra antoi suuren pelastuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Kerran lähti kolme noista kolmestakymmenestä päälliköstä Daavidin luo kalliolinnaan, Adullamin luolalle. Filistealaisten joukko oli leiriytynyt Refaimin tasangolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'Daavid oli Vuorilinnassa, ja filistealaisten vartiosto oli Beetlehemissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Daavidin rupesi tekemään mieli vettä, ja hän sanoi: \"Jospa joku toisi minulle vettä juodakseni Beetlehemin kaivosta, joka on portin edustalla!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Nämä kolme murtautuivat filistealaisten leirin läpi ja ammensivat vettä Beetlehemin kaivosta portin edustalta, kantoivat ja toivat Daavidille. Mutta Daavid ei tahtonut sitä juoda, vaan vuodatti sen juomauhriksi Herralle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'ja sanoi: \"Pois se! Jumala varjelkoon minut sitä tekemästä. Joisinko minä näiden miesten verta, heidän henkeään, sillä henkensä uhalla he sen toivat.\" Eikä hän tahtonut juoda sitä. Tämän olivat tehneet nuo kolme sankaria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Abisai, Jooabin veli, oli niiden kolmen päällikkö. Hän oli heiluttanut keihästään kolmensadan kaatuneen yli. Hän oli maineikas niiden kolmen joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Hän oli kaksinkertaisessa arvossa pidetty niiden kolmen joukossa ja oli heidän päämiehensä, mutta hän ei vetänyt vertoja niille kolmelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benaja, Joojadan poika, joka oli urhoollisen ja suurista teoistaan kuuluisan miehen poika, oli kotoisin Kabseelista. Hän surmasi kaksi mooabilaista sankaria, ja hän laskeutui alas ja tappoi lumituiskun aikana leijonan kaivoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Hän surmasi myös egyptiläisen miehen, suurikasvuisen, viisi kyynärää pitkän miehen. Egyptiläisellä oli kädessä keihäs, joka oli kuin kangastukki, mutta hän meni häntä vastaan ainoastaan sauva kädessä. Hän tempasi keihään egyptiläisen kädestä ja tappoi hänet hänen omalla keihäällään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Tällaisia teki Benaja, Joojadan poika. Hän oli kuulu näiden kolmen sankarin joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Hän oli arvossa pidetty niiden kolmenkymmenen joukossa, mutta hän ei vetänyt vertoja niille kolmelle. Daavid asetti hänet henkivartiostonsa päälliköksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Sankarit olivat: Asael, Jooabin veli; Elhanan, Doodon poika, Beetlehemistä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'harorilainen Sammot; pelonilainen Heeles;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'tekoalainen Iira, Ikkeksen poika; anatotilainen Abieser;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'huusalainen Sibbekai; ahohilainen Iilai;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'netofalainen Maharai; netofalainen Heeled, Baanan poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Iitai, Riibain poika, benjaminilaisten Gibeasta, piratonilainen Benaja;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Huurai Nahale-Gaasista; arabalainen Abiel;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'baharumilainen Asmavet; saalbonilainen Eljahba;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'gisonilainen Bene-Haasem; hararilainen Joonatan, Saagen poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'hararilainen Abijam, Saakarin poika; Elifal, Uurin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'mekeralainen Heefer; pelonilainen Ahia;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'karmelilainen Hesro; Naarai, Esbain poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Jooel, Naatanin veli; Mibhar, Hagrin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'ammonilainen Selek; beerotilainen Nahrai, Jooabin, Serujan pojan aseenkantaja;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'jeteriläinen Iira; jeteriläinen Gaareb;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'heettiläinen Uuria; Saabad, Ahlain poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'ruubenilainen Adina, Siisan poika, ruubenilaisten päämies, ja hänen kanssaan kolmekymmentä muuta;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Haanan, Maakan poika, ja mitniläinen Joosafat;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'astarotilainen Ussia; Saama ja Jegiel, aroerilaisen Hootamin pojat;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediael, Simrin poika, ja hänen veljensä Jooha, tiisiläinen;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel-Mahavim sekä Jeribai ja Joosavja, Elnaamin pojat, ja mooabilainen Jitma;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel, Oobed ja Jaasiel-Mesobaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Nämä olivat ne, jotka tulivat Daavidin luo Siklagiin, kun hän vielä piileskeli Saulia, Kiisin poikaa. He olivat niitä sankareita, jotka auttoivat häntä sodassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'He olivat aseistettuja jousella ja olivat taitavia sekä oikealla että vasemmalla kädellä linkoamaan kiviä ja ampumaan jousella nuolia. Saulin heimolaisia, benjaminilaisia:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Ahieser, päämies, ja Jooas, gibealaisen Hassemaan pojat; Jesiel ja Pelet, Asmavetin pojat; Beraka; anatotilainen Jeehu;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'gibeonilainen Jismaja, sankari niiden kolmenkymmenen joukossa ja niiden kolmenkymmenen päällikkö;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Jeremia; Jahasiel; Joohanan; gederalainen Joosabad;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elusai; Jerimot; Bealja; Semarja; harufilainen Sefatja;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'koorahilaiset Elkana, Jissia, Asarel, Jooeser ja Jaasobeam;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Jooela ja Sebadja, Jerohamin pojat, Gedrista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Gaadilaisista meni Daavidin puolelle Vuorilinnaan, erämaahan, sankareita, sotakelpoisia miehiä, kilpeä ja keihästä käyttäviä, jotka olivat näöltään kuin leijonat ja nopeat kuin gasellit vuorilla:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Eeser, päämies Obadja toinen, Eliab kolmas,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Masmanna neljäs, Jeremia viides,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Attai kuudes, Eliel seitsemäs,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Joohanan kahdeksas, Elsabad yhdeksäs,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Jeremia kymmenes, Makbannai yhdestoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Nämä olivat gaadilaisia, sotajoukon päälliköitä, pienin sadan, suurin tuhannen miehen veroinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Nämä olivat ne, jotka ensimmäisessä kuussa menivät Jordanin poikki, kun se tulvi yli kaikkien äyräittensä, ja jotka karkottivat kaikki tasangoilla asujat itään ja länteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Myös benjaminilaisia ja Juudan miehiä tuli Daavidin Vuorilinnaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Daavid meni heitä vastaan, lausui ja sanoi heille: \"Jos tulette luokseni rauha mielessä, auttaaksenne minua, sydämeni yhtyy teihin. Mutta jos tulette kavaltamaan minut vihollisilleni, vaikkei väkivalta tahraa käsiäni, isiemme Jumala nähköön sen ja rangaiskoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Mutta Henki täytti Amasain, niiden kolmenkymmenen päällikön, ja hän sanoi: \"Sinun me olemme, Daavid, ja sinun puolellasi olemme, sinä Iisain poika. Rauha, rauha sinulle, ja rauha auttajillesi, sillä Jumalasi auttoi sinua!\" Niin Daavid otti heidät vastaan ja asetti heidät partiojoukon päälliköiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Manassesta siirtyi muutamia Daavidin puolelle, kun hän filistealaisten kanssa meni taistelemaan Saulia vastaan, vaikkeivät he joutuneetkaan auttamaan näitä, sillä filistealaisten ruhtinaat neuvoteltuaan lähettivät hänet [Daavidin] pois sanoen: \"Hän voisi päämme menoksi siirtyä herransa Saulin puolelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Kun hän siis lähti Siklagiin, siirtyivät hänen puolelleen Manassesta: Adna, Joosabad, Jediael, Miikael, Joosabad, Elihu ja Silletai, tuhannenpäämiehet Manassesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Nämä auttoivat Daavidia rosvojoukkoa vastaan, sillä he olivat kaikki sankareita, ja heistä tuli sotajoukon päälliköitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Sillä joka päivä tuli väkeä Daavidin luo auttamaan häntä, kunnes joukko oli suuri kuin Jumalan joukko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Tämä on sotaan varustetun aseväen lukumäärä, niiden, jotka tulivat Daavidin luo Hebroniin siirtääkseen Saulin kuninkuuden hänelle Herran käskyn mukaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Juudan miehiä, jotka kantoivat kilpeä ja keihästä, kuusituhatta kahdeksansataa, sotaan varustettua;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'simeonilaisia, väkeviä sankareita, seitsemäntuhatta sata;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'leeviläisiä neljätuhatta kuusisataa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'sekä Joojada, Aaronin suvun ruhtinas, sekä kolmetuhatta seitsemänsataa hänen kanssaan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'ja Saadok, nuorukainen, väkevä sankari, perhekuntineen, kaksikymmentä kaksi päällikköä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'benjaminilaisia, Saulin veljiä, kolmetuhatta, sillä vielä siihen aikaan suurin osa heistä palveli uskollisesti Saulin sukua');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'efraimilaisia kaksikymmentä tuhatta kahdeksansataa, väkeviä sankareita, nimekkäitä miehiä perhekunnissaan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'toisesta puolesta Manassen sukukuntaa kahdeksantoista tuhatta, jotka olivat nimeltä mainitut menemään ja tekemään Daavidin kuninkaaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'isaskarilaisia, jotka ymmärsivät ajan ja käsittivät, mitä Israelin oli tehtävä, kaksisataa päämiestä, ja kaikki heidän veljensä heidän johdollaan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'Sebulonista sotakelpoisia miehiä, kaikkinaisilla sota-aseilla sotaan varustettuja, viisikymmentä tuhatta, yksimielisiä taistelurintamaan järjestymään;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'Naftalista tuhat päällikköä, ja heidän kanssaan kolmekymmentäseitsemän tuhatta kilvellä ja keihäällä varustettua miestä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'daanilaisia kaksikymmentäkahdeksan tuhatta kuusisataa sotaan varustettua miestä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'Asserista sotakelpoisia miehiä, taisteluun valmiita, neljäkymmentä tuhatta;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'tuolta puolelta Jordanin, ruubenilaisia, gaadilaisia ja manasselaisia sukukunnan toisesta puolesta, satakaksikymmentä tuhatta, kaikilla sota-aseilla varustettuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Kaikki nämä sotilaat, taistelurintamaan järjestyneinä, tulivat ehyellä sydämen halulla Hebroniin tehdäkseen Daavidin koko Israelin kuninkaaksi. Myös koko muu Israel oli yksimielinen tehdäkseen Daavidin kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'He olivat siellä Daavidin luona kolme päivää ja söivät ja joivat, sillä heidän heimolaisensa olivat antaneet heille evästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 41, 'Nekin, jotka asuivat lähellä heitä, aina Isaskariin, Sebuloniin ja Naftaliin saakka, toivat aasien, kamelien, muulien ja härkien selässä ruokatavaraa: jauhoja, viikunakakkuja ja rusinakakkuja, viiniä ja öljyä, nautoja ja lampaita ja vuohia hyvin runsaasti, sillä Israelissa oli ilo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Daavid neuvotteli tuhannen- ja sadanpäämiesten, kaikkien ruhtinasten, kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Daavid sanoi kaikelle Israelin seurakunnalle: \"Jos teistä on hyvä ja jos se tulee Herralta, Jumalaltamme, lähettäkäämme joka taholle sana veljillemme, jotka ovat jääneet kaikkiin Israelin maakuntiin, ja papeille ja leeviläisille, jotka asuvat heidän luonaan laidunmaittensa kaupungeissa, että he kokoontuvat luoksemme,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'ja siirtäkäämme Jumalamme arkki luoksemme, sillä Saulin päivinä emme siitä välittäneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Koko seurakunta vastasi, että niin oli tehtävä, sillä se oli oikein koko kansan silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Daavid kokosi koko Israelin, aina Egyptin Siihorista asti ja aina sieltä, mistä mennään Hamatiin, tuomaan Jumalan arkkia Kirjat-Jearimista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Daavid ja koko Israel meni Baalatiin, Kirjat-Jearimiin, joka on Juudassa, tuomaan sieltä Jumalan arkkia, jonka Herra oli ottanut nimiinsä, hän, jonka istuinta kerubit kannattavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'He panivat Jumalan arkin uusiin vaunuihin ja veivät sen pois Abinadabin talosta, ja Ussa ja Ahjo ohjasivat vaunuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Daavid sekä koko Israel karkeloivat kaikin voimin Jumalan edessä laulaen sekä soittaen lyyraa, harppuja, tamburiineja, symbaaleja ja torvia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Mutta kun he tulivat Kiidonin puimatantereen luo, Ussa ojensi kätensä tarttuakseen arkkiin, sillä härät kompastuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Herran viha syttyi Ussaa kohtaan, ja hän löi häntä sen tähden, että hän oli ojentanut kätensä arkkiin, ja hän kuoli siihen, Jumalan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Mutta Daavid pahastui siitä, että Herra niin oli murtanut Ussan. Siitä paikan nimenä on Peres-Ussa vielä tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Daavid pelästyi sinä päivänä Jumalaa, niin että hän sanoi: \"Kuinka voin tuoda Jumalan arkin luokseni?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Eikä Daavid siirtänyt arkkia luokseen Daavidin kaupunkiin, vaan toimitti sen syrjään gatilaisen Oobed-Edomin taloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Jumalan arkki jäi kolmeksi kuukaudeksi Oobed-Edomin talon luo. Herra siunasi Oobed-Edomin taloa ja kaikkea, mitä hänellä oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Hiiram, Tyyron kuningas, lähetti sanansaattajat Daavidin luo, sekä setripuita ja puuseppiä ja kivenhakkaajia rakentamaan hänelle linnaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Daavid ymmärsi, että Herra oli vahvistanut hänet Israelin kuninkaaksi, koska hänen kuninkuutensa oli korotettu korkealle Herran kansan Israelin tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Jerusalemissa Daavid vielä otti vaimoja, ja Daavidille syntyi vielä poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Nämä ovat niiden poikien nimet, jotka syntyivät hänelle Jerusalemissa: Sammua, Soobab, Naatan, Salomo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Jibhar, Elisua, Elpelet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Noogah, Nefeg, Jaafia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisama, Beeljada ja Elifelet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Mutta kun filistealaiset kuulivat, että Daavid oli voideltu koko Israelin kuninkaaksi, kaikki filistealaiset lähtivät etsimään Daavidia. Kun Daavid kuuli sen, hän lähti heitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Kun filistealaiset olivat tulleet ja tehneet ryöstöretken Refaimin tasangolle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Daavid kysyi Jumalalta: \"Menenkö filistealaisia vastaan, ja annatko heidät käsiini?\" Herra sanoi hänelle: \"Mene. Annan heidät käsiisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'He menivät Baal-Perasimiin, ja siellä Daavid voitti heidät. Daavid sanoi: \"Jumala on murtanut viholliseni kädelläni, niin kuin vedet murtavat.\" Siitä sen paikan nimeksi tuli Baal-Perasim.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Filistealaiset jättivät siihen jumalansa, ja Daavid käski polttaa ne tulessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Filistealaiset tekivät kuitenkin vielä kerran ryöstöretken tasangolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Daavid kysyi taas Jumalalta, ja Jumala vastasi hänelle: \"Älä mene heidän jälkeensä, vaan kierrä heidät ja hyökkää heidän kimppuunsa balsamipuiden puolelta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'Kun kuulet askelten äänen balsamipuiden latvoista, käy taisteluun, sillä Jumala on käynyt edelläsi tuhotakseen filistealaisten leirin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'Daavid teki, niin kuin Jumala oli häntä käskenyt, ja he voittivat filistealaisten sotajoukon ja ajoivat heitä takaa Gibeonista aina Geseriin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Daavidin maine levisi kaikkiin maihin, ja Herra nosti kaikissa kansoissa pelon häntä kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Hän rakensi itselleen taloja Daavidin kaupunkiin ja valmisti paikan Jumalan arkille ja pystytti sille telttamajan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Daavid käski: \"Älkööt muut kuin leeviläiset kantako Jumalan arkkia, sillä heidät Herra on valinnut kantamaan Jumalan arkkia ja palvelemaan häntä ikiajoiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Daavid kokosi koko Israelin Jerusalemiin, tuomaan Herran arkin siihen paikkaan, jonka hän oli sille valmistanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Daavid kokosi Aaronin jälkeläiset ja leeviläiset;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Kehatin jälkeläisistä: Uurielin, päämiehen, ja hänen veljensä, sata kaksikymmentä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'Merarin jälkeläisistä: Asajan, päämiehen, ja hänen veljensä, kaksisataa kaksikymmentä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'Geersomin jälkeläisistä: Jooelin, päämiehen, ja hänen veljensä, sata kolmekymmentä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Elisafanin jälkeläisistä: Semajan, päämiehen, ja hänen veljensä, kaksisataa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'Hebronin jälkeläisistä: Elielin, päämiehen, ja hänen veljensä, kahdeksankymmentä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'Ussielin jälkeläisistä: Amminadabin, päämiehen, ja hänen veljensä, sata kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Daavid kutsui papit Saadokin ja Ebjatarin sekä leeviläiset Uurielin, Asajan, Jooelin, Semajan, Elielin ja Amminadabin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'ja sanoi heille: \"Te olette leeviläisten perhekuntien päämiehet. Pyhittäkää itsenne ja veljenne ja tuokaa Herran, Israelin Jumalan, arkki siihen paikkaan, jonka olen sille valmistanut');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Sillä sen tähden, ettette ensimmäisellä kerralla olleet läsnä, mursi Herra, meidän Jumalamme, meidät. Sillä me emme etsineet häntä, niin kuin olisi pitänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Papit ja leeviläiset pyhittäytyivät tuomaan Herran, Israelin Jumalan, arkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Leeviläiset kantoivat Jumalan arkkia korennoilla olallaan, kuten Mooses oli Herran sanan mukaan käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Daavid käski leeviläisten päämiesten asettaa veljensä, veisaajat, soittimilla, lyyroilla, harpuilla ja symbaaleilla kaiuttamaan riemuvirsiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Leeviläiset asettivat soittamaan Heemanin, Jooelin pojan, ja hänen heimolaisistaan Aasafin, Berekjan pojan, ja heidän heimolaisistaan, Merarin jälkeläisistä, Eetanin, Kuusajan pojan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'ja heidän kanssaan heidän arvossa lähinnä olevista heimolaisistaan: Sakarjan, Benin ja Jaasielin, Semiramotin, Jehielin, Unnin, Eliabin, Benajan, Maasejan, Mattitjan, Elifelehun, Miknejan, Oobed-Edomin ja Jegielin, ovenvartijat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Veisaajista oli Heemanin, Aasafin ja Eetanin soitettava vaskisymbaaleilla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Sakarjan, Ussielin, Semiramotin, Jehielin, Unnin, Eliabin, Maasejan ja Benajan harpuilla korkeassa äänialassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Mattitjan, Elifelehun, Miknejan, Oobed-Edomin, Jegielin ja Asasjan sitroilla matalassa äänialassa, veisuuta johtaakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Kenanja, leeviläisten johtaja kantajatehtävässä, valvoi kantamista, sillä hän oli siinä taitava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Berekja ja Elkana olivat arkin ovenvartijat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Papit Sebanja, Joosafat, Netanel, Amasai, Sakarja, Benaja ja Elieser puhalsivat torviin Jumalan arkin edellä, ja Oobed-Edom ja Jehia olivat arkin ovenvartijat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Daavid, Israelin vanhimmat ja tuhannenpäämiehet menivät ja toivat riemuiten Herran liitonarkin Oobed-Edomin talosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Kun Jumala auttoi leeviläisiä, jotka kantoivat Herran liitonarkkia, uhrattiin seitsemän härkää ja seitsemän pässiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Daavid oli puettu hienosta pellavakankaasta tehtyyn viittaan ja samoin kaikki leeviläiset, jotka kantoivat arkkia, sekä veisaajat ja kantamisen johtaja Kenanja veisaajien kanssa. Daavidilla oli yllään pellavakasukka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Koko Israel toi Herran liitonarkin riemun raikuessa ja torvien raikuessa, torvien, symbaalien, harppujen ja lyyrojen soidessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Kun Herran liitonarkki tuli Daavidin kaupunkiin, katseli Miikal, Saulin tytär, ikkunasta, ja nähdessään kuningas Daavidin hyppivän ja karkeloivan hän halveksi häntä sydämessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Kun he olivat tuoneet Jumalan arkin ja asettaneet sen telttamajaan, jonka Daavid oli sille pystyttänyt, he uhrasivat polttouhreja ja rauhanuhreja Jumalan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Kun Daavid oli uhrannut polttouhrin ja rauhanuhrit, hän siunasi kansan Herran nimeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Hän jakoi kaikille israelilaisille, sekä miehille että naisille, kullekin leipäkakun, palan lihaa ja rypälekakun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Hän asetti Herran arkin eteen leeviläisiä palvelemaan ja kunnioittamaan, kiittämään ja ylistämään Herraa, Israelin Jumalaa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Aasafin johtajaksi, toiseksi Sakarjan, sitten Jegielin, Semiramotin, Jehielin, Mattitjan, Eliabin, Benajan, Oobed-Edomin ja Jegielin soittamaan harpuilla ja lyyroilla, Aasafin helistäessä symbaaleja');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'ja pappien, Benajan ja Jahasielin, soittaessa taukoamatta torvia Jumalan liitonarkin edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Silloin, sinä päivänä, Daavid asetti Aasafin ja hänen veljensä ensi kerran kiittämään Herraa näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, '\"Kiittäkää Herraa, julistakaa hänen nimeään, tehkää hänen suuret tekonsa tiettäviksi kansojen keskuudessa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Laulakaa hänelle, veisatkaa hänelle, puhukaa kaikista hänen ihmeistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Kerskatkaa hänen pyhässä nimessään. Iloitkoon niiden sydän, jotka Herraa etsivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Kysykää Herraa ja hänen voimaansa, etsikää alati hänen kasvojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Muistakaa hänen ihmetekojaan, jotka hän on tehnyt, hänen ihmeitään ja hänen suunsa tuomioita,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'te Israelin, hänen palvelijansa, siemen, Jaakobin lapset, te hänen valittunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Hän, Herra, on Jumalamme. Hänen tuomionsa käyvät yli koko maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Muistakaa hänen liittonsa iankaikkisesti, hamaan tuhansiin polviin, sana, jonka hän on säätänyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'liitto, jonka hän teki Aabrahamin kanssa, ja hänen Iisakille vannomansa vala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'Hän vahvisti sen käskyksi Jaakobille, Israelille ikuiseksi liitoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Hän sanoi: \'Sinulle annan Kanaanin maan. Olkoon se perintöosanne.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Teitä oli vähäinen joukko, vain harvoja, ja te olitte siellä muukalaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'He vaelsivat kansasta kansaan ja yhdestä valtakunnasta toiseen kansakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Hän ei sallinut kenenkään heitä vahingoittaa, ja hän rankaisi kuninkaita heidän tähtensä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, '\'Älkää koskeko Messiaaseeni, älkää tehkö pahaa Profeetalleni.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Veisatkaa Herralle, kaikki maa, julistakaa päivästä päivään hänen pelastustekojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Ilmoittakaa pakanoiden keskellä hänen kunniansa, hänen ihmeensä kaikkien kansojen seassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Sillä Herra on suuri ja sangen ylistettävä, hän on pelottava yli kaikkien jumalien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Sillä kaikki pakanakansojen jumalat ovat epäjumalia, mutta Herra on tehnyt taivaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Kirkkaus ja kunnia on hänen kasvojensa edessä, väkevyys ja riemu hänen asuinsijassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Antakaa Herralle, te kansojen sukukunnat, antakaa Herralle kunnia ja väkevyys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Antakaa Herralle hänen nimensä kunnia, tuokaa lahjoja ja tulkaa hänen kasvojensa eteen, kumartakaa Herraa pyhässä kaunistuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Vaviskaa hänen kasvojensa edessä, kaikki maa. Maanpiiri pysyy lujana eikä horju.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Iloitkoot taivaat, ja riemuitkoon maa, ja sanottakoon pakanoiden keskuudessa: \' Herra on kuningas!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Pauhatkoon meri ja kaikki, mitä siinä on. Ihastukoot kedot ja kaikki, mitä niissä on,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'riemuitkoot silloin metsän puut Herran edessä, sillä hän saapuu tuomitsemaan maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Sanokaa: \'Pelasta meidät, sinä pelastuksemme Jumala, kokoa ja vapahda meidät pakanoiden seasta, että kiittäisimme sinun pyhää nimeäsi ja kerskaisimme ylistyksestäsi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Ylistetty olkoon Herra, Israelin Jumala, iankaikkisesta iankaikkiseen.\" Kaikki kansa sanoi: \"Aamen\", ja ylisti Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Hän [Daavid] asetti Aasafin ja hänen veljensä Herran liitonarkin eteen tekemään vakituista palvelusta arkin edessä, kunakin päivänä sen päivän palveluksen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'mutta Oobed-Edomin ja heidän veljensä, yhteensä kuusikymmentä kahdeksan, nimittäin Oobed-Edomin, Jeditunin pojan, ja Hoosan, ovenvartijoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Pappi Saadokin ja hänen veljensä, papit, hän asetti Herran asumuksen eteen, uhrikukkulalle, joka on Gibeonissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'uhraamaan polttouhreja Herralle polttouhrialttarilla, aina aamuin ja illoin, kaikki niin kuin on kirjoitettuna Herran laissa, jonka hän on antanut Israelille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'Heidän kanssaan olivat Heeman ja Jedutun sekä muut valitut, nimeltä mainitut, kiittämässä Herraa siitä, että hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Näiden, Heemanin ja Jedutunin, hallussa oli torvet ja symbaalit soittajia varten sekä muut soittimet Jumalan virttä varten. Jedutunin pojat vartioivat ovia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Kaikki kansa lähti kukin kotiinsa, ja Daavid kääntyi takaisin siunaamaan perhettään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Kerran kun Daavid istui linnassaan, Daavid sanoi profeetta Naatanille: \"Katso, minä asun setripuisessa palatsissa, mutta Herran liitonarkki on telttakankaan alla.\" Naatan sanoi Daavidille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, '\"Tee vain kaikki, mitä mielessäsi on, sillä Jumala on kanssasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Mutta tapahtui sinä yönä, että Naatanille tuli tämä Jumalan sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, '\"Mene ja sano palvelijalleni Daavidille: Näin sanoo Herra: Sinä et ole rakentava minulle temppeliä siinä asuakseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Sillä en ole asunut temppelissä siitä päivästä asti, jona johdatin Israelin tänne, tähän päivään saakka, vaan olen muuttanut teltasta telttaan ja asumuksesta asumukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Olenko missään, missä olenkin vaeltanut kaikessa Israelissa, sanonut kenellekään Israelin tuomareista, joita olen asettanut kaitsemaan kansaani: Miksi ette ole rakentaneet minulle setripuista huonetta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Sano siis palvelijalleni Daavidille: Näin sanoo Herra Sebaot: Minä olen ottanut sinut laitumelta lammasten jäljestä kansani Israelin ruhtinaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'Olen ollut kanssasi kaikkialla, missä vaelsit, ja olen hävittänyt kaikki vihollisesi tieltäsi. Teen sinulle nimen, suurimpien nimien vertaisen maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Valmistan sijan kansalleni Israelille ja istutan sen niin, että se asuu paikallaan eikä ole enää levoton eivätkä vääryydentekijät vaivaa sitä enää kuten ennen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'siitä ajasta saakka, jolloin asetin tuomareita kansalleni Israelille. Nöyryytän kaikki vihollisesi. Ilmoitan sinulle, että Herra on rakentava sinulle temppelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Kun päiväsi ovat päättyneet lähteäksesi isiesi luo, korotan seuraajaksesi jälkeläisesi, joka on yksi pojistasi, ja vahvistan hänen kuninkuutensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Hän on rakentava minulle temppelin, ja vahvistan hänen valtaistuimensa ikiajoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Minä olen oleva hänen Isänsä, ja hän on oleva minun Poikani, ja armoani en häneltä ota pois, niin kuin otin siltä, joka oli edelläsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Pidän hänet pystyssä huoneessani ja valtakunnassani iäti, ja hänen valtaistuimensa on oleva iäti vahva.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Aivan näillä sanoilla ja tämän näyn mukaan Naatan puhui Daavidille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Kuningas Daavid meni ja asettui Herran eteen ja sanoi: \"Mikä olen minä, Herra Jumala, ja mikä on sukuni, että olet saattanut minut tähän asti?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Mutta tämäkin on ollut vähän sinun silmissäsi, Jumala, ja niin olet puhunut palvelijasi suvusta kaukaisina tulevina aikoina ja olet nähnyt minut ylennettynä ihmiskyyhkynä, joka on Herra Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Mitä Daavid enää sinulle puhuisi kunniasta, jota olet osoittanut palvelijallesi? Sinähän tunnet palvelijasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Herra, palvelijasi tähden ja oman mielesi mukaan sinä olet tehnyt kaiken tämän suuren ja ilmoittanut kaikki nämä suuret asiat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Herra, kaiken sen mukaan, mitä me olemme korvillamme kuulleet, ei ole vertaistasi, eikä ole muuta jumalaa kuin sinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Missä on maan päällä toista kansaa kansasi Israelin vertaista, jota Jumala itse on käynyt lunastamaan kansakseen ja tehdäkseen itselleen suuren ja pelottavan nimen karkottamalla pakanat kansasi tieltä, jonka Egyptistä lunastit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Olet asettanut kansasi Israelin omaksi kansaksesi ikuisiksi ajoiksi, ja sinä, Herra, olet heidän Jumalansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Olkoon nyt, Herra, se sana, jonka sinä olet puhunut palvelijastasi ja hänen suvustaan, vahva ikuisiksi ajoiksi. Tee, niin kuin olet puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Nimesi on oleva vahva ja tuleva suureksi ikuisiksi ajoiksi, ja se on oleva: Herra Sebaot, Israelin Jumala, Jumala Israelissa. Palvelijasi Daavidin suku on pysyvä edessäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Sillä sinä, Jumalani, olet ilmoittanut palvelijallesi rakentavasi hänelle temppelin. Siitä palvelijasi on saanut rohkeuden rukoilla edessäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Nyt, Herra, sinä olet Jumala. Kun olet luvannut palvelijallesi tämän hyvän,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'suvaitse nyt siunata palvelijasi sukua, että se pysyisi iäti edessäsi. Sillä se, minkä sinä, Herra, siunaat, on oleva siunattu iäti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Sen jälkeen Daavid voitti filistealaiset ja nöyryytti heidät. Hän otti Gatin ja sen tytärkaupungit filistealaisten käsistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Hän voitti myös mooabilaiset, ja mooabilaiset tulivat Daavidin veronalaisiksi palvelijoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Samoin Daavid voitti Hadareserin, Sooban kuninkaan, Hamatin suunnalla, kun tämä oli menossa lujittamaan valtaansa Eufrat-virran rannoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Daavid otti häneltä tuhat vaunuhevosta, seitsemäntuhatta ratsumiestä ja kaksikymmentä tuhatta jalkamiestä, ja Daavid katkoi kaikilta vaunuhevosilta vuohisjänteet. Ainoastaan sata vaunuhevosta hän niistä säästi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Kun Damaskon aramilaiset tulivat auttamaan Hadareseria, Sooban kuningasta, Daavid voitti kaksikymmentäkaksi tuhatta aramilaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Daavid asetti maaherroja Damaskon Aramiin, ja aramilaiset tulivat Daavidin veronalaisiksi palvelijoiksi. Herra antoi Daavidille voiton, mihin tahansa tämä meni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Daavid otti ne kultavarustukset, jotka Hadareserin palvelijoilla oli yllään, ja vei ne Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Mutta Hadareserin kaupungeista, Tibhatista ja Kuunista, Daavid otti erittäin paljon vaskea. Siitä Salomo teetti vaskimeren, pylväät ja vaskiesineet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Kun Toou, Hamatin kuningas, kuuli, että Daavid oli voittanut Hadareserin, Sooban kuninkaan, koko sotajoukon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'hän lähetti poikansa Hadoramin kuningas Daavidin luo tervehtimään häntä ja onnittelemaan häntä siitä, että hän oli taistellut Hadareserin kanssa ja voittanut hänet. Hadareser oli näet ollut Tooun vastustaja. Hänellä oli mukanaan kaikenlaisia kulta-, hopea- ja vaskiesineitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Nekin kuningas Daavid pyhitti Herralle samoin kuin hopean ja kullan, minkä hän oli ottanut kaikilta kansoilta: Edomilta, Mooabilta, ammonilaisilta, filistealaisilta ja Amalekilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Kun Abisai, Serujan poika, oli Suolalaaksossa voittanut edomilaiset, kahdeksantoista tuhatta miestä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'hän asetti maaherroja Edomiin, ja kaikki edomilaiset tulivat Daavidin palvelijoiksi. Herra antoi Daavidille voiton, mihin tahansa Daavid meni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Daavid hallitsi koko Israelia ja teki kaikelle kansalleen sitä, mikä on oikeus ja vanhurskaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Jooab, Serujan poika, oli sotajoukon ylipäällikkönä, ja Joosafat, Ahiludin poika, oli kanslerina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Saadok, Ahitubin poika, ja Abimelek, Ebjatarin poika, olivat pappeina, ja Savsa oli kirjurina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Benaja, Joojadan poika, oli kreettien ja pleettien päällikkönä, mutta Daavidin pojat olivat ensimmäiset kuninkaan rinnalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Sen jälkeen ammonilaisten kuningas Naahas kuoli, ja hänen poikansa tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Daavid sanoi: \"Minä osoitan laupeutta Haanunille, Naahaan pojalle, sillä hänen isänsä osoitti laupeutta minulle.\" Daavid lähetti sanansaattajat lohduttamaan häntä hänen isänsä kuoleman johdosta. Kun Daavidin palvelijat tulivat ammonilaisten maahan Haanunin luo lohduttamaan häntä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'ammonilaisten päämiehet sanoivat Haanunille: \"Kunnioittaako Daavid isääsi, kun hän lähettää lohduttajia luoksesi? Varmaankin hänen palvelijansa ovat tulleet luoksesi tutkimaan ja hävittämään ja vakoilemaan maata.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Haanun otatti kiinni Daavidin palvelijat, ajatti heidän partansa ja leikkautti toisen puolen heidän vaatteistaan, lonkkia myöten, ja lähetti heidät menemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Kun tultiin kertomaan Daavidille miehistä, hän lähetti sanan heitä vastaan, sillä miehiä oli pahasti häväisty. Kuningas käski sanoa: \"Jääkää Jerikoon, kunnes partanne on kasvanut, ja palatkaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Kun ammonilaiset huomasivat joutuneensa Daavidin vihoihin, Haanun ja ammonilaiset lähettivät tuhat talenttia hopeaa palkatakseen itselleen Mesopotamiasta, Maakan Aramista ja Soobasta sotavaunuja ja ratsumiehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'He palkkasivat itselleen kolmekymmentäkaksi tuhatta sotavaunua sekä Maakan kuninkaan ja hänen väkensä. Nämä tulivat ja leiriytyivät Meedeban edustalle. Ammonilaiset kokoontuivat kaupungeistaan ja lähtivät sotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Kun Daavid kuuli sen, hän lähetti Jooabin ja koko sankareiden sotajoukon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Ammonilaiset lähtivät ja asettuivat sotarintamaan kaupungin portin edustalle, mutta kuninkaat, jotka olivat tulleet sinne, olivat eri joukkona kedolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Kun Jooab näki, että häntä uhkasi hyökkäys edestä ja takaa, hän valitsi miehiä kaikista Israelin valioista ja asettui rintamaan aramilaisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Mutta muun väen hän antoi veljensä Abisain johtoon. Nämä asettuivat taistelurintamaan ammonilaisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Hän sanoi: \"Jos aramilaiset tulevat minulle ylivoimaisiksi, niin tule avukseni: jos taas ammonilaiset tulevat sinulle ylivoimaisiksi, autan sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Ole luja, ja pysykäämme lujina kansamme puolesta ja Jumalamme kaupunkien puolesta. Tehköön sitten Herra, minkä hyväksi näkee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Jooab ja väki, joka oli hänen kanssaan, ryhtyi taisteluun aramilaisia vastaan, ja nämä pakenivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Kun ammonilaiset näkivät aramilaisten pakenevan, hekin pakenivat hänen veljeään Abisaita ja menivät kaupunkiin. Mutta Jooab lähti Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Kun aramilaiset näkivät, että Israel oli voittanut heidät, he lähettivät sanansaattajat nostattamaan niitä aramilaisia, jotka asuivat tuolla puolella Eufrat-virran ja joita johti Soofak, Hadareserin sotapäällikkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Kun se ilmoitettiin Daavidille, hän kokosi koko Israelin ja meni Jordanin yli, ja tultuaan heitä lähelle hän asettui sotarintamaan heitä vastaan. Kun Daavid oli asettunut rintamaan aramilaisia vastaan, nämä ryhtyivät taisteluun hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Mutta aramilaiset pakenivat Israelia, ja Daavid tappoi aramilaisilta seitsemäntuhatta vaunuhevosta ja neljäkymmentä tuhatta jalkamiestä ja surmasi heidän sotapäällikkönsä Soofakin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Kun Hadareserin palvelijat näkivät, että Israel oli voittanut heidät, he tekivät Daavidin kanssa rauhan ja palvelivat häntä. Aramilaiset eivät enää tahtoneet auttaa ammonilaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Vuoden vaihteessa kuningasten sotaanlähtöaikaan Jooab vei sotajoukon sotaretkelle ja hävitti ammonilaisten maata ja piiritti Rabbaa. Mutta Daavid itse jäi Jerusalemiin. Jooab valtasi Rabban ja hävitti sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Daavid otti heidän kuninkaansa kruunun hänen päästään ja havaitsi sen painavan talentin kultaa. Siinä oli kallis kivi. Kruunu pantiin Daavidin päähän. Hän vei kaupungista hyvin paljon saalista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Kansan, joka oli siellä, hän vei pois ja pani sahaamaan kiviä, pani rautahakkujen ja kivisahojen ääreen. Näin Daavid teki kaikille ammonilaisten kaupungeille. Daavid ja kaikki väki palasi Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Sen jälkeen syttyi taistelu filistealaisia vastaan Geserissä. Huusalainen Sibbekai surmasi Sippain, joka oli Raafan jälkeläisiä, ja heidät nöyryytettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Taas oli taistelu filistealaisia vastaan, ja Elhanan, Jaaorin poika, surmasi Lahmin, gatilaisen Goljatin veljen, jonka peitsen varsi oli kuin kangastukki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Taas oli taistelu Gatissa. Siellä oli suurikasvuinen mies, jolla oli kuusi sormea ja kuusi varvasta, yhteensä kaksikymmentä neljä. Hänkin polveutui Raafasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Kun hän häpäisi Israelia, hänet surmasi Joonatan, Daavidin veljen Simean poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Nämä polveutuivat gatilaisesta Raafasta. He kaatuivat Daavidin ja hänen palvelijoidensa käden kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Mutta saatana nousi Israelia vastaan ja yllytti Daavidin laskemaan Israelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Daavid sanoi Jooabille ja kansan päämiehille: \"Menkää ja laskekaa Israel Beersebasta Daaniin asti ja ilmoittakaa minulle, että saan tietää heidän lukumääränsä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Jooab vastasi: \" Herra lisätköön kansansa, olkoon se kuinka suuri tahansa, satakertaiseksi. Ovathan he, herrani, kuningas, kaikki herrani palvelijoita. Miksi herrani pyytää tätä? Miksi Israel näin joutuisi vikapääksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Kuitenkin kuninkaan sana velvoitti Jooabia, ja Jooab lähti ja kierteli koko Israelin. Sitten hän tuli Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Jooab ilmoitti Daavidille kansan lasketun lukumäärän: koko Israelissa oli miljoona satatuhatta sotakuntoista miekkamiestä, ja Juudassa oli neljäsataa seitsemänkymmentä tuhatta miekkamiestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Leevistä ja Benjaminista hän ei pitänyt katselmusta yhdessä muiden kanssa, sillä kuninkaan käsky oli Jooabille kauhistus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Mutta tämä asia oli Jumalan silmissä paha, ja hän löi Israelia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Daavid sanoi Jumalalle: \"Minä olen tehnyt suuren synnin tehdessäni tämän. Mutta anna nyt anteeksi palvelijasi rikos, sillä olen menetellyt hyvin tyhmästi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Herra puhui Gaadille, Daavidin näkijälle, näin: \"Mene ja puhu Daavidille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Näin sanoo Herra: Kolme minä asetan eteesi: valitse itsellesi niistä yksi, teen sen sinulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Niin Gaad meni Daavidin luo ja sanoi hänelle: \"Näin sanoo Herra: Valitse itsellesi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'joko kolme nälkävuotta tai kolme kuukautta hävitystä ahdistajaisi vainotessa, vihollistesi miekka kintereilläsi, tai kolmeksi päiväksi Herran miekka ja rutto maahan, Herran enkeli tuottamaan tuhoa koko Israelin alueelle. Katso nyt, mitä minä vastaan hänelle, joka minut lähetti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'Daavid vastasi Gaadille: \"Olen suuressa hädässä. Tahdon langeta Herran käsiin, sillä hänen laupeutensa on sangen suuri, – ihmisten käsiin en tahdo langeta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Niin Herra antoi ruton tulla Israeliin, ja Israelista kaatui seitsemänkymmentä tuhatta miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Jumala lähetti enkelin Jerusalemia vastaan tuhoamaan sitä. Kun se sitä tuhosi, Herra katsoi siihen ja katui sitä pahaa ja sanoi tuhoojaenkelille: \"Jo riittää, laske kätesi alas.\" Herran enkeli seisoi silloin jebusilaisen Ornanin puimatantereen luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Kun Daavid nosti silmänsä ja näki Herran enkelin seisovan maan ja taivaan välillä, kädessään paljastettu miekka ojennettuna Jerusalemin yli, Daavid ja vanhimmat lankesivat säkkeihin verhottuina kasvoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Daavid sanoi Jumalalle: \"Minähän käskin laskea kansan, ja minä siis olen se, joka olen tehnyt syntiä ja menetellyt pahoin. Mutta nämä lampaani, mitä he ovat tehneet? Herra, Jumalani, sattukoon kätesi minuun ja isäni perheeseen, mutta ei sinun kansaasi, sille vitsaukseksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Herran enkeli käski Gaadin sanoa Daavidille, että Daavid menisi pystyttämään Herralle alttarin jebusilaisen Ornanin puimatantereelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Daavid meni sen sanan mukaan, jonka Gaad oli Herran nimeen puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Kun Ornan kääntyi, hän näki enkelin, ja hänen neljä poikaansa piiloutui, sillä Ornan oli puimassa vehnää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Mutta Daavid meni Ornanin luo, ja kun Ornan katsoi ylös ja näki Daavidin, hän lähti puimatantereelta ja kumartui Daavidin eteen kasvoilleen maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Daavid sanoi Ornanille: \"Anna minulle puimatantereen paikka rakentaakseni siihen Herralle alttarin. Anna se minulle täydestä hinnasta, että vitsaus taukoaisi kansasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Ornan vastasi Daavidille: \"Ota se itsellesi, ja herrani, kuningas, tehköön, mitä hyväksi näkee. Katso, annan härät polttouhriksi ja puimaäkeet polttopuiksi sekä vehnänjyvät ruokauhriksi. Annan ne kaikki.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Mutta kuningas Daavid sanoi Ornanille: \"Ei niin, vaan totisesti ostan ne sinulta täydestä hinnasta. Sillä minä en ota Herralle sitä, mikä on sinun, enkä uhraa ilmaiseksi saatua polttouhria.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'Daavid antoi Ornanille siitä paikasta kuudensadan sekelin painon kultaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Daavid rakensi sinne alttarin Herralle ja uhrasi polttouhreja ja rauhanuhreja, ja kun hän huusi Herraa, vastasi Herra tulella, jonka hän lähetti taivaasta polttouhrialttarille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Herra käski enkelin pistää miekkansa tuppeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Siihen aikaan kun Daavid näki, että Herra oli kuullut häntä jebusilaisen Ornanin puimatantereella, hän uhrasi siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Mutta Herran asumus, jonka Mooses oli teettänyt erämaassa, ja polttouhrialttari olivat siihen aikaan Gibeonin uhrikukkulalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Eikä Daavid rohjennut mennä Jumalan eteen etsimään häntä, sillä hän oli pelästynyt Herran enkelin miekkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Daavid sanoi: \"Tässä olkoon Herran Jumalan temppeli ja tässä alttari Israelin polttouhria varten.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Daavid käski koota muukalaiset, jotka olivat Israelin maassa. Hän asetti kivenhakkaajia hakkaamaan kiviä Jumalan temppelin rakentamiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Daavid hankki paljon rautaa portin ovien nauloiksi ja sinkilöiksi ja niin paljon vaskea, ettei se ollut punnittavissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'sekä suunnattomat määrät setripuita, sillä siidonilaiset ja tyyrolaiset toivat paljon setripuita Daavidille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Sillä Daavid ajatteli: \"Poikani Salomo on nuori ja hento, mutta Herralle rakennettavan temppelin tulee olla hyvin suuri, niin että sitä mainitaan ja kiitetään kaikissa maissa. Minä siis hankin hänelle varastot.\" Daavid hankki ennen kuolemaansa suuret varastot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Hän kutsui poikansa Salomon ja käski hänen rakentaa temppelin Herralle, Israelin Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Daavid sanoi Salomolle: \"Poikani, minä aioin itse rakentaa temppelin Herran, Jumalani, nimelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Mutta minulle tuli tämä Herran sana: \'Sinä olet vuodattanut paljon verta ja käynyt suuria sotia. Sinä et ole rakentava temppeliä nimelleni, koska olet vuodattanut niin paljon verta maahan edessäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Katso, sinulle on syntyvä poika. Hänestä on tuleva rauhan mies, ja annan hänen päästä rauhaan kaikilta hänen ympärillään asuvilta vihollisilta, sillä Salomo on oleva hänen nimensä, ja minä annan rauhan ja levon Israelille hänen päivinään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Hän on rakentava temppelin minun nimelleni. Hän on oleva poikani, ja minä olen oleva hänen Isänsä. Minä vahvistan hänen kuninkuutensa valtaistuimen ikiajoiksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Olkoon siis Herra kanssasi, poikani, että menestyisit ja saisit rakennetuksi temppelin Herralle, Jumalallesi, niin kuin hän on sinusta puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Antakoon vain Herra sinulle älyä ja ymmärrystä ja asettakoon sinut hallitsemaan Israelia ja noudattamaan Herran, Jumalasi, lakia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Silloin menestyt, jos tarkasti noudatat niitä käskyjä ja oikeuksia, jotka Herra antoi Moosekselle Israelia varten. Ole luja ja rohkea, älä pelkää äläkä arkaile.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Katso, vaivanalaisenakin olen hankkinut Herran temppeliä varten satatuhatta talenttia kultaa ja tuhat kertaa tuhat talenttia hopeaa sekä vaskea ja rautaa niin paljon, ettei se ole punnittavissa, sillä sitä on erittäin paljon. Olen myös hankkinut hirsiä ja kiviä, ja sinä saat hankkia vielä lisää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Paljon on sinulla myös työmiehiä, kivenhakkaajia, muurareita, puuseppiä ja kaikenlaisen työn taitajia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'Kullalla, hopealla, vaskella ja raudalla ei ole määrää. Nouse, ryhdy työhön, ja Herra olkoon kanssasi!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Daavid käski kaikkia Israelin päämiehiä auttamaan poikaansa Salomoa sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, '\"Onhan Herra, Jumalanne, ollut kanssanne ja suonut teidän päästä joka taholla rauhaan, sillä hän on antanut maan asukkaat käsiini ja maa on tehty alamaiseksi Herralle ja hänen kansalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Antakaa siis sydämenne ja sielunne etsimään Herraa, Jumalaanne. Nouskaa ja rakentakaa Herran, Jumalan, pyhäkkö, että Herran liitonarkki ja Jumalan pyhä kalusto voitaisiin viedä temppeliin, joka on rakennettava Herran nimelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Kun Daavid oli tullut vanhaksi ja saanut elämästä kylliksi, hän teki poikansa Salomon Israelin kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Hän kutsui kokoon kaikki Israelin päämiehet, papit ja leeviläiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Leeviläiset laskettiin, kolmekymmentävuotiaat ja sitä vanhemmat, ja heidän lukumääränsä pääluvun mukaan oli kolmekymmentäkahdeksan tuhatta miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, '\"Näistä olkoon kaksikymmentäneljä tuhatta johtamassa töitä Herran temppelissä ja kuusi tuhatta päällysmiehinä ja tuomareina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'Neljä tuhatta olkoon ovenvartijoina, ja neljä tuhatta ylistäköön Herraa soittimilla, jotka olen teettänyt ylistämistä varten.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'Daavid jakoi heidät osastoihin Leevin poikien Geersonin, Kehatin ja Merarin mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Geersonilaisia olivat Ladan ja Siimei.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Ladanin pojat olivat Jehiel, päämies, Seetam ja Jooel, kaikkiaan kolme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Siimein pojat olivat Selomit, Hasiel ja Haaran, kaikkiaan kolme. Nämä olivat Ladanin perhekuntien päämiehet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Siimein pojat olivat Jahat, Siina, Jeus ja Beria. Nämä olivat Siimein pojat, kaikkiaan neljä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jahat oli päämies, Siisa toinen, mutta Jeuksella ja Berialla ei ollut monta poikaa, niin että heistä tuli yksi perhekunta, yksi palvelusvuoro.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Kehatin pojat olivat Amram, Jishar, Hebron ja Ussiel, kaikkiaan neljä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Amramin pojat olivat Aaron ja Mooses. Mutta Aaron poikineen erotettiin olemaan ikuisesti pyhitetty, korkeasti pyhä, ikuisesti suitsuttamaan Herran edessä, palvelemaan häntä ja siunaamaan hänen nimessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Jumalan miehen Mooseksen pojat luettiin Leevin sukukuntaan kuuluviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Mooseksen pojat olivat Geersom ja Elieser.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Geersomin poika oli Sebuel, päämies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Elieserin poika oli Rehabja, päämies. Elieserillä ei ollut muita poikia. Mutta Rehabjan poikia oli hyvin paljon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Jisharin poika oli Selomit, päämies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Hebronin pojat olivat Jeria, päämies, Amarja toinen, Jahasiel kolmas ja Jekamam neljäs.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Ussielin pojat olivat Miika, päämies, ja Jissia toinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Merarin pojat olivat Mahli ja Muusi. Mahlin pojat olivat Eleasar ja Kiis.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Kun Eleasar kuoli, häneltä ei jäänyt poikia, vaan ainoastaan tyttäriä, jotka heidän serkkunsa, Kiisin pojat, ottivat vaimoikseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Muusin pojat olivat Mahli, Eeder ja Jeremot, kaikkiaan kolme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Nämä olivat Leevin pojat, heidän perhekuntiensa mukaan, perhekuntien päämiehet, niin monta kuin heitä oli ollut katselmuksessa, nimien lukumäärän mukaan, pääluvun mukaan, ne, jotka toimittivat palvelustehtäviä Herran temppelissä, kaksikymmentävuotiaat ja sitä vanhemmat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Sillä Daavid sanoi: \" Herra, Israelin Jumala, on suonut kansansa päästä lepoon ja on asuva Jerusalemissa ikuisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Niinpä ei leeviläistenkään tarvitse kantaa asumusta eikä mitään esineitä, joita tarvitaan siinä tehtävissä töissä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, '– Sillä Daavidin viimeisten määräysten mukaan laskettiin Leevin poikien lukuun kaksikymmentävuotiaat ja sitä vanhemmat. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Heidän tehtäväkseen tuli: olla Aaronin poikien apuna Herran temppelin töissä, pitää huoli esikartanoista ja kammioista, kaiken pyhän puhtaana pitämisestä ja Jumalan temppelin töistä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'näkyleivistä, ruokauhriin tarvittavista ydinjauhoista, happamattomista ohuista leivistä, leivinlevystä ja jauhosekoituksesta sekä astia- ja pituusmitoista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'seisoa joka aamu kiittämässä ja ylistämässä Herraa, ja samoin joka ilta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'ja uhrata kaikki polttouhrit Herralle sapatteina, uudenkuun päivinä ja juhlina, niin paljon kuin niitä oli säädetty aina uhrattavaksi Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'Heidän oli hoidettava ilmestysmajan ja pyhäkön tehtävät sekä ne tehtävät, jotka heidän veljillään Aaronin pojilla oli palvellessaan Herran temppelissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Nämä olivat Aaronin poikien osastot: Aaronin pojat olivat Naadab, Abihu, Eleasar ja Iitamar.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Naadab ja Abihu kuolivat ennen isäänsä, eikä heillä ollut poikia. Pappeina palvelivat ainoastaan Eleasar ja Iitamar.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Daavid yhdessä Saadokin kanssa, joka oli Eleasarin poikia, ja Ahimelekin kanssa, joka oli Iitamarin poikia, jakoi heidät osastoihin heidän palvelusvuorojensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Kun Eleasarin pojilla havaittiin olevan enemmän päämiehiä kuin Iitamarin pojilla, heidät jaettiin niin, että Eleasarin pojat saivat kuusitoista päämiestä perhekunnilleen ja Iitamarin pojat kahdeksan päämiestä perhekunnilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Heidät jaettiin arvalla, toiset niin kuin toisetkin, sillä pyhäkköruhtinaat ja Jumalan ruhtinaat otettiin sekä Eleasarin pojista että Iitamarin pojista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Semaja, Netanelin poika, kirjuri, joka oli Leevin sukua, kirjoitti heidät muistiin kuninkaan, päämiesten, pappi Saadokin ja Ahimelekin, Ebjatarin pojan, sekä pappien ja leeviläisten perhekuntien päämiesten läsnäollessa. Yksi perhekunta otettiin vuorotellen Eleasarin ja Iitamarin suvusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Ensimmäinen arpa tuli Joojaribille, toinen Jedajalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'kolmas Haarimille, neljäs Seoromille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'viides Malkialle, kuudes Miijaminille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'seitsemäs Koosille, kahdeksas Abialle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'yhdeksäs Jeesualle, kymmenes Sekanjalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'yhdestoista Eljasibille, kahdestoista Jaakimille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'kolmastoista Huppalle, neljästoista Jesebabille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'viidestoista Bilgalle, kuudestoista Immerille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'seitsemästoista Heesirille, kahdeksastoista Pissekselle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'yhdeksästoista Petahjalle, kahdeskymmenes Hesekielille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'kahdeskymmenes ensimmäinen Jaakinille, kahdeskymmenes toinen Gaamulille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'kahdeskymmenes kolmas Delajalle ja kahdeskymmenes neljäs Maasjalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Nämä ovat heidän palvelusvuoronsa, kun he menevät Herran temppeliin, niin kuin heidän isänsä Aaron oli heille säätänyt, sen mukaan, kuin Herra, Israelin Jumala, oli häntä käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Mitä tulee muihin Leevin jälkeläisiin, niin oli Amramin jälkeläisiä Suubael, Suubaelin jälkeläisiä Jehdeja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Rehabjan jälkeläisiä päämies Jissia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'jisharilaisia Selomot, Selomotin jälkeläisiä Jahat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'Jerian jälkeläisiä olivat: Amarja toinen, Jahasiel kolmas, Jekamam neljäs.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Ussielin jälkeläisiä oli Miika, Miikan jälkeläisiä Saamir.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Miikan veli oli Jissia. Jissian jälkeläisiä oli Sakarja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Merarin jälkeläisiä olivat Mahli ja Muusi sekä hänen poikansa Jaasian jälkeläiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Merarilla oli jälkeläisiä pojastaan Jaasiasta sekä Sooham, Sakkur ja Ibri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Mahlista polveutui Eleasar, jolla ei ollut poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Kiisistä polveutui Jerahmeel, joka oli Kiisin jälkeläisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Muusin jälkeläisiä olivat Mahli, Eeder ja Jerimot. Nämä olivat leeviläisten jälkeläiset heidän perhekuntiensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Myös nämä, niin hyvin perhekuntien päämiehet kuin heidän nuoremmat veljensä, heittivät arpaa samoin kuin heidän veljensä, Aaronin pojat, kuningas Daavidin, Saadokin ja Ahimelekin sekä pappien ja leeviläisten perhekuntien päämiesten läsnä ollessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Daavid ja sotapäälliköt erottivat palvelukseen Aasafin, Heemanin ja Jedutunin pojat, jotka profetoivat lyyroilla, harpuilla ja symbaaleilla. Tämä on luettelo miehistä, jotka toimittivat tätä palvelustaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Aasafin poikia oli Sakkur, Joosef, Netanja ja Asarela, Aasafin pojat, Aasafin johdolla, joka profetoi kuninkaan johdolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Jedutunista: Jedutunin pojat Gedalja, Seri, Jesaja, Hasabja ja Mattitja, kaikkiaan kuusi, isänsä Jedutunin johdolla, joka profetoi lyyralla kiittäen ja ylistäen Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Heemanista: Heemanin pojat Bukkia, Mattanja, Ussiel, Sebuel ja Jerimot, Hananja, Hanani, Eliata, Giddalti ja Roomamti-Eser, Josbekasa, Malloti, Hootir ja Mahasiot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Nämä ovat kaikki Heemanin, kuninkaan näkijän, poikia, sen Jumalan sanan mukaan, että hän on korottava korkealle hänen sarvensa: Jumala oli antanut Heemanille neljätoista poikaa ja kolme tytärtä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Nämä kaikki veisasivat isänsä johdon alaisina Herran temppelissä symbaalien, harppujen ja lyyrojen säestäessä, Jumalan temppelipalveluksessa, kuninkaan, Aasafin, Jedutunin ja Heemanin johdolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Heidän ja heidän veljiensä lukumäärä, jotka oli opetettu veisaamaan Herran kunniaksi, kaikkien taitajien, oli kaksisataa kahdeksankymmentä kahdeksan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'He heittivät arpaa palvelusjärjestyksestä, nuoremmat niin kuin vanhemmatkin, taitajat yhdessä oppilaiden kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Ensimmäinen arpa, Aasafin arpa, tuli Joosefille. Toinen Gedaljalle, hänelle itselleen sekä hänen veljilleen ja pojilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Kolmas Sakkurille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Neljäs Jisrille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Viides Netanjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Kuudes Bukkialle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Seitsemäs Jesarelalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Kahdeksas Jesajalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Yhdeksäs Mattanjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Kymmenes Siimeille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Yhdestoista Asarelille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Kahdestoista Hasabjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Kolmastoista Suubaelille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Neljästoista Mattitjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Viidestoista Jeremotille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Kuudestoista Hananjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Seitsemästoista Josbekasalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Kahdeksastoista Hananille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Yhdeksästoista Mallotille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Kahdeskymmenes Elijjatalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Kahdeskymmenes ensimmäinen Hootirille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Kahdeskymmenes toinen Giddaltille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Kahdeskymmenes kolmas Mahasiotille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Kahdeskymmenes neljäs Roomamti-Eserille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Mitä tulee ovenvartijoiden osastoihin, niin oli koorahilaisia Meselemja, Kooren poika, Aasafin jälkeläisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Meselemjalla oli pojat: esikoinen Sakarja, toinen Jediael, kolmas Sebadja, neljäs Jatniel,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'viides Eelam, kuudes Joohanan, seitsemäs Eljoenai.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Oobed-Edomilla oli pojat: esikoinen Semaja, toinen Joosabad, kolmas Jooah, neljäs Saakar, viides Netanel,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'kuudes Ammiel, seitsemäs Isaskar, kahdeksas Peulletai, sillä Jumala oli siunannut häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Hänen pojalleen Semajalle syntyi poikia, jotka hallitsivat isänsä sukua, sillä he olivat kykeneviä miehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Semajan pojat olivat Otni, Refael, Oobed ja Elsabad ja hänen veljensä, kykeneviä miehiä, Elihu ja Semakja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Kaikki nämä olivat Oobed-Edomin jälkeläisiä, he sekä heidän poikansa ja veljensä, kykeneviä miehiä, tarmokkaita palveluksessaan, kaikkiaan kuusikymmentä kaksi Oobed-Edomin jälkeläistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Meselemjalla oli poikia ja veljiä, kykeneviä miehiä, kaikkiaan kahdeksantoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Hoosalla, joka oli Merarin jälkeläisiä, oli poikia: päämies Simri, jonka hänen isänsä, kun ei ollut esikoista, asetti päämieheksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'toinen Hilkia, kolmas Tebalja, neljäs Sakarja; Hoosan poikia ja veljiä oli kaikkiaan kolmetoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Näiden ovenvartijain osastojen, päämiesten, samoin kuin heidän veljiensä, tehtävänä oli vartiopalvelus, sillä heidän oli palveltava Herran temppelissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'He heittivät arpaa joka ovesta, nuoremmat niin kuin vanhemmatkin, perhekuntiensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Itäpuolen arpa lankesi Selemjalle, myös hänen pojalleen Sakarjalle, joka oli ymmärtäväinen neuvonantaja, heitettiin arpa, ja hänelle tuli pohjoispuolen arpa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Oobed-Edomille määräsi arpa etelän ja hänen pojilleen varastohuoneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Suppimille ja Hoosalle lännen, jossa on Salleket-portti ylöspäin kohoavan tien kohdalla: vartiopaikan toisen vartiopaikan viereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Idän puolella oli kuusi leeviläistä, pohjoisen puolella neljä joka päivä, etelän puolella neljä joka päivä ja varastohuoneen luona kaksi ja kaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'Parparin luona, lännen puolella, oli neljä tiellä ja kaksi Parparin luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Nämä ovat ovenvartijoiden osastot, koorahilaisten jälkeläisten ja Merarin jälkeläisten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Leeviläisistä hoiti Ahia Jumalan temppelin aarrekammioita ja pyhien lahjojen aarteita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Ladanin pojat, geersonilaisten jälkeläiset, Ladanista polveutuvat geersonilaisen Ladanin perhekuntien päämiehet, jehieliläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'jehieliläisten jälkeläiset, olivat Seetam ja hänen veljensä Jooel. He hoitivat Herran temppelin aarrekammioita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Mitä tulee amramilaisiin, jisharilaisiin, hebronilaisiin ja ossielilaisiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'niin Sebuel, Geersomin poika, joka oli Mooseksen poika, oli aarrekammioiden esimies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Hänen Elieseristä polveutuvat veljensä olivat: tämän poika Rehabja, tämän poika Jesaja, tämän poika Jooram, tämän poika Sikri ja tämän poika Selomot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Tämä Selomot ja hänen veljensä hoitivat kaikkia niiden pyhien lahjojen aarteita, jotka kuningas Daavid, perhekuntien päämiehet, tuhannen- ja sadanpäämiehet ja sotapäälliköt olivat pyhittäneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Sodista ja saaliista he olivat ne pyhittäneet Herran temppelin voimassapitämiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Samoin kaikki, mitä Samuel, näkijä, Saul, Kiisin poika, Abner, Neerin poika, ja Jooab, Serujan poika, olivat pyhittäneet, kaikki, mikä pyhitettiin, jätettiin Selomitin ja hänen veljiensä hoitoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Jisharilaisista määrättiin Kenanja ja hänen poikansa maallisiin toimiin Israelissa, päällysmiehiksi ja tuomareiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Hebronilaisista määrättiin Hasabja ja hänen veljensä, tuhat seitsemänsataa kykenevää miestä, Israelin hallinnon hoitoon Jordanin länsipuolella, kaikkiin Herran toimiin ja kuninkaan palvelukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Hebronilaisia oli Jeria, hebronilaisten päämies, heidän polveutumisensa ja isiensä mukaan – Daavidin neljäntenäkymmenentenä hallitusvuotena heidät tutkittiin ja heidän joukostaan tavattiin kykeneviä miehiä Gileadin Jaeserissa –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'sekä hänen veljensä, kaksituhatta seitsemänsataa kykenevää miestä, perhekuntien päämiehiä. Heidät kuningas Daavid asetti johtamaan ruubenilaisia, gaadilaisia ja toista puolta manasselaisten sukukuntaa kaikissa Jumalan ja kuninkaan asioissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Israelilaisia, lukumääränsä mukaan, sekä perhekuntapäämiehiä, tuhannen- ja sadanpäämiehiä ja heidän päällysmiehiään, jotka palvelivat kuningasta kaikessa, mikä koski osastoja, jotka tulivat ja lähtivät kuukausi kuukaudelta, vuoden kaikkina kuukausina, oli kussakin osastossa kaksikymmentäneljä tuhatta miestä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Ensimmäisen osaston, ensimmäisen kuukauden osaston, johtajana oli Jaasobeam, Sabdielin poika, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Hän oli Pereksen jälkeläisiä ja oli kaikkien sotapäällikköjen ylipäällikkö, ensimmäisenä kuukautena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Toisen kuukauden osaston johtajana oli ahohilainen Doodai. Hänen osastonsa johdossa oli myös ruhtinas Miklot, ja hänen osastossaan oli kaksikymmentä neljä tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Kolmas sotapäällikkö, kolmantena kuukautena, oli Benaja, pappi Joojadan poika, ylipäällikkö, ja hänen osastossaan oli kaksikymmentä neljä tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Tämä Benaja oli sankari niiden kolmenkymmenen joukossa ja niiden kolmenkymmenen johtaja, ja hänen osastossaan oli hänen poikansa Ammisabad.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Neljäs, neljäntenä kuukautena, oli Asahel, Jooabin veli, ja hänen jälkeensä hänen poikansa Sebadja; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Viides, viidentenä kuukautena, oli päällikkö Samhut, jisrahilainen, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Kuudes, kuudentena kuukautena, oli tekoalainen Iira, Ikkeksen poika, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Seitsemäs, seitsemäntenä kuukautena, oli pelonilainen Heeles, efraimilaisia, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Kahdeksas, kahdeksantena kuukautena, oli huusalainen Sibbekai, serahilaisia, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Yhdeksäs, yhdeksäntenä kuukautena, oli anatotilainen Abieser, benjaminilaisia, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Kymmenes, kymmenentenä kuukautena, oli netofalainen Mahrai, serahilaisia, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Yhdestoista, yhdentenätoista kuukautena, oli piratonilainen Benaja, efraimilaisia, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Kahdestoista, kahdentenatoista kuukautena, oli netofalainen Heldai, Otnielista polveutuva, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Israelin sukukuntien johtajat olivat: ruubenilaisten ruhtinas oli Elieser, Sikrin poika, simeonilaisten Sefatja, Maakan poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Leevin oli Hasabja, Kemuelin poika; Aaronin Saadok,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'Juudan oli Elihu, Daavidin veljiä, Isaskarin Omri, Miikaelin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'Sebulonin oli Jismaja, Obadjan poika, Naftalin Jerimot, Asrielin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'efraimilaisten oli Hoosea, Asasjan poika, toisen puolen Manassen sukukuntaa Jooel, Pedajan poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'toisen puolen Manassea, Gileadissa, oli Jiddo, Sakarjan poika, Benjaminin Jaasiel, Abnerin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'Daanin Asarel, Jerohamin poika. Nämä olivat Israelin sukukuntien ruhtinaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Daavid ei ottanut luetteloon kaksikymmenvuotiaita ja sitä nuorempia, sillä Herra oli luvannut tehdä Israelin monilukuiseksi kuin taivaan tähdet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Jooab, Serujan poika, oli aloittanut laskemisen, mutta ei sitä lopettanut, sillä siitä viha kohtasi Israelia, eikä luku tullut kuningas Daavidin aikakirjaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Kuninkaan varastojen hoitaja oli Asmavet, Adielin poika. Kedolla, kaupungeissa, kylissä ja torneissa olevien varastojen hoitaja oli Joonatan, Ussian poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Maatöitä tekevien peltotyömiesten kaitsija oli Esri, Kelubin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Viinitarhan hoitaja oli raamatilainen Siimei. Viinitarhoista koottujen viinivarastojen hoitaja oli sifmiläinen Sabdi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Öljypuiden ja Alankomaassa kasvavien metsäviikunapuiden hoitaja oli gaderilainen Baal-Haanan. Öljyvarastojen hoitaja oli Jooas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Saaronissa laitumella käyvien nautojen kaitsija oli saaronilainen Sitrai, ja tasangoilla laitumella käyvien nautojen kaitsija Saafat, Adlain poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Kamelien kaitsija oli ismaelilainen Oobil, aasintammojen meeronotilainen Jehdeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Lampaiden ja vuohien kaitsija oli hagrilainen Jaasis. Nämä kaikki olivat kuningas Daavidin omaisuuden ylihoitajia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Joonatan, Daavidin setä, joka oli ymmärtäväinen mies ja kirjanoppinut, oli neuvonantaja. Jehiel, Hakmonin poika, oli kuninkaan lasten luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Ahitofel oli kuninkaan neuvonantaja, ja arkilainen Huusai oli kuninkaan ystävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Ahitofelin jälkeen tulivat Joojada, Benajan poika, ja Ebjatar. Kuninkaan sotapäällikkö oli Jooab.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Daavid kokosi Jerusalemiin kaikki Israelin päämiehet, sukukuntien päämiehet, osastojen päälliköt, jotka palvelivat kuningasta, tuhannen- ja sadanpäämiehet, kuninkaan ja hänen poikiensa kaiken omaisuuden ja karjan ylihoitajat, hovimiehet, sankarit ja kaikki valiosotilaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Kuningas Daavid nousi seisomaan jaloilleen ja sanoi: \"Kuulkaa minua, veljeni ja kansani. Minä olin aikonut rakentaa huoneen Herran liitonarkin leposijaksi ja Jumalamme jalkojen astinlaudaksi ja olin valmistautunut rakentamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Mutta Jumala sanoi minulle: \'Älä sinä rakenna temppeliä nimelleni, sillä sinä olet sotilas ja olet vuodattanut verta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Kuitenkin valitsi Herra, Israelin Jumala, minut kaikesta isäni suvusta olemaan Israelin kuninkaana ikuisesti. Sillä Juudan hän valitsi ruhtinaaksi ja Juudan heimosta isäni suvun, ja isäni poikien joukossa olin otollinen hänelle, niin että hän teki minut koko Israelin kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Kaikkien poikieni joukosta, sillä Herra on antanut minulle monta poikaa, hän valitsi poikani Salomon istumaan Herran valtakunnan valtaistuimella ja hallitsemaan Israelia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Hän sanoi minulle: \'Sinun poikasi Salomo on rakentava temppelini ja esikartanoni, sillä olen valinnut hänet pojakseni ja minä olen oleva hänelle Isänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Vahvistan hänen kuninkuutensa iankaikkisesti, jos hän on luja ja pitää käskyni ja oikeuteni, niin kuin hän nyt tekee.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Nyt sanon koko Israelin, Herran seurakunnan, edessä ja Jumalamme kuullen: Noudattakaa ja tutkikaa kaikkia Herran, Jumalanne, käskyjä, että saisitte pitää omananne tämän hyvän maan ja jättäisitte sen perinnöksi lapsillenne jälkeenne ikiajoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Sinä, poikani Salomo, opi tuntemaan isäsi Jumala ja palvele häntä ehyellä sydämellä ja alttiilla mielellä, sillä Herra tutkii kaikki sydämet ja ymmärtää kaikki ajatukset ja aivoitukset. Jos häntä etsit, löydät hänet, mutta jos luovut hänestä, hän hylkää sinut iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Katso nyt eteesi, sillä Herra on valinnut sinut rakentamaan temppelipyhäkön. Ole luja ja ryhdy työhön.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Sen jälkeen Daavid antoi pojalleen Salomolle temppelin eteisen, sen rakennusten, varastohuoneiden, yläsalien, sisähuoneiden ja armoistuimen huoneen mallin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'sekä määräykset kaikesta, mitä hänellä oli mielessään: Herran temppelin esikartanoista ja kaikista kammioista [temppelin] ympärillä, Jumalan temppelin ja pyhien lahjojen aarrekammioista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'sekä myös pappien ja leeviläisten osastoista, kaikesta Herran temppelissä toimitettavasta palveluksesta ja kaikista Herran temppelin palveluksessa tarvittavista esineistä: kullasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'jokaisen palveluksessa tarvittavan kultaesineen painosta, kaikista hopeakaluista, jokaisen palveluksessa tarvittavan hopeaesineen painosta;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'kullasta tehtävien lampunjalkojen ja niiden kunkin lampun kullan painosta, jokaisen lampunjalan ja sen lamppujen painosta; samoin hopeasta tehtävien lampunjalkojen painosta, jokaisen lampunjalan ja sen lamppujen painosta, jokaisen lampunjalan käytön mukaan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'edelleen näkyleipäpöytien kullan painosta, kunkin pöydän erikseen, samoin hopeasta tehtävien pöytien hopeasta;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'haarukoiden, maljojen ja kannujen puhtaasta kullasta, samoin kultapikareista, kunkin pikarin painosta, ja hopeapikareista, kunkin pikarin painosta;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'myös suitsutusalttarin puhdistetun kullan painosta ja vaunujen mallista, kultakerubeista, joitten tuli levittää siipensä ja peittää Herran liitonarkki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, '\"Tämä kaikki on kirjoituksessa, joka on lähtenyt Herran kädestä. Hän on opettanut minulle kaikki tämän mallin mukaan tehtävät työt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Daavid sanoi pojalleen Salomolle: \"Ole luja ja rohkea ja ryhdy työhön, älä pelkää äläkä arkaile, sillä Herra Jumala, Jumalani, on oleva kanssasi. Hän ei jätä sinua eikä hylkää sinua, kunnes olet saanut valmiiksi kaikki Herran temppelissä tehtävät työt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Katso, pappien ja leeviläisten osastot ovat valmiit kaikkeen palvelukseen Jumalan temppelissä, ja sinulla on kaikkiin töihin käytettävinäsi niitä, jotka alttiisti ja taitavasti tekevät kaikkea palvelusta, niin myös päämiehet ja koko kansa kaikkiin tehtäviisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Kuningas Daavid sanoi koko seurakunnalle: \"Poikani Salomo, ainoa Jumalan valittu, on nuori ja hento, ja työ on suuri, sillä tämä linna ei ole aiottu ihmiselle, vaan Herralle Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Kaikin voimin olen hankkinut Jumalani temppeliä varten kultaa kultaesineisiin, hopeaa hopeaesineisiin, vaskea vaskiesineisiin, rautaa rautaesineisiin ja puuta puuesineisiin, onykskiviä ja muita jalokiviä, mustankiiltävää ja kirjavaa kiveä, kaikenlaisia kalliita kiviä ja marmorikiveä suuret määrät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Koska Jumalani temppeli on minulle rakas, luovutan omistamani kullan ja hopean Jumalani temppeliä varten, kaiken sen lisäksi, minkä olen pyhäkköä varten hankkinut:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'kolmetuhatta talenttia kultaa, Oofirin kultaa, ja seitsemäntuhatta talenttia puhdistettua hopeaa huoneitten seinien silaamiseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'kultaa kultaesineisiin ja hopeaa hopeaesineisiin ja kaikkiin taitajien kätten töihin. Tahtooko kukaan muu tänä päivänä tuoda vapaaehtoisesti täysin käsin lahjoja Herralle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Silloin tulivat vapaaehtoisesti perhekuntien päämiehet, Israelin sukukuntien ruhtinaat, tuhannen- ja sadanpäämiehet ja kuninkaan töiden ylivalvojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'He antoivat Jumalan temppelissä tehtäviin töihin viisituhatta talenttia ja kymmenentuhatta dareikkia kultaa, kymmenentuhatta talenttia hopeaa, kahdeksantoista tuhatta talenttia vaskea ja satatuhatta talenttia rautaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Jolla oli hallussaan jalokiviä, antoi ne Herran temppelin aarteisiin geersonilaisen Jehielin huostaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Kansa iloitsi heidän alttiudestaan, sillä he antoivat ehyellä sydämellä vapaaehtoiset lahjansa Herralle, ja kuningas Daavid oli myös suuresti iloissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Daavid kiitti Herraa koko seurakunnan läsnäollessa. Daavid sanoi: \"Ole kiitetty, Herra, isämme Israelin Jumala, iankaikkisesta iankaikkiseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Sinun, Herra, on suuruus ja väkevyys ja loisto ja kunnia ja kirkkaus, sillä sinun on kaikki taivaassa ja maan päällä. Sinun, Herra, on valtakunta, ja sinä olet korotettu kaiken pääksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Rikkaus ja kunnia tulevat sinulta, sinä hallitset kaikki, ja kädessäsi on voima ja väkevyys. Vallassasi on tehdä mikä tahansa suureksi ja väkeväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Nyt, Jumalamme, me kiitämme sinua ja ylistämme ihanaa nimeäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Sillä mikä olen minä, ja mikä on kansani kyetäksemme antamaan tällaisia vapaaehtoisia lahjoja? Vaan kaikki tulee sinulta, ja omasta kädestäsi olemme sen sinulle antaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Sillä me olemme muukalaisia ja vieraita edessäsi, niin kuin kaikki isämmekin. Kuin varjo ovat päivämme maan päällä eikä ole, mihin toivonsa panna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Herra, Jumalamme, kaikki tämä runsaus, jonka olemme hankkineet rakentaaksemme temppelin sinulle, sinun pyhälle nimellesi, on kädestäsi, ja sinun on kaikki tyynni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Tiedän, Jumalani, että sinä tutkit sydämen ja mielistyt vilpittömyyteen. Vilpittömällä sydämellä minä olen antanut kaikki nämä vapaaehtoiset lahjat, ja nyt olen ilolla nähnyt, kuinka sinun täällä oleva kansasi on antanut sinulle vapaaehtoiset lahjansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Herra, meidän isiemme Aabrahamin, Iisakin ja Israelin Jumala, säilytä tällaisina ainiaan kansasi sydämen ajatukset ja aivoitukset ja ohjaa heidän sydämensä puoleesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Anna pojalleni Salomolle ehyt sydän noudattamaan käskyjäsi, todistuksiasi ja säädöksiäsi, toimittamaan kaikki tämä ja rakentamaan tämä linna, jota varten minä olen tehnyt valmistuksia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Daavid sanoi kaikelle seurakunnalle: \"Kiittäkää Herraa, Jumalaanne.\" Koko seurakunta kiitti Herraa, isiensä Jumalaa, ja he kumartuivat maahan ja osoittivat kunniaa Herralle ja kuninkaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Seuraavana päivänä he teurastivat teuraita Herralle ja uhrasivat polttouhreja Herralle: tuhat härkää, tuhat pässiä ja tuhat karitsaa ja niihin kuuluvat juomauhrit sekä teurasuhreja suuren joukon koko Israelin puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'He söivät ja joivat Herran edessä sinä päivänä suuresti iloiten ja tekivät toistamiseen Salomon, Daavidin pojan, kuninkaaksi ja voitelivat hänet Herralle ruhtinaaksi, ja Saadokin papiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Salomo istui Herran valtaistuimelle kuninkaaksi isänsä Daavidin sijaan, ja hän menestyi, ja koko Israel totteli häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Samoin kaikki päämiehet, sankarit ja myös kaikki kuningas Daavidin pojat kättä lyöden lupautuivat kuningas Salomon alamaisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Herra teki Salomon erittäin suureksi koko Israelin silmissä ja antoi hänelle kuninkuuden loiston, jonka kaltaista yhdelläkään kuninkaalla Israelissa ei ollut ollut ennen häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Daavid, Iisain poika, oli hallinnut koko Israelia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Aika, jonka hän hallitsi Israelia, oli neljäkymmentä vuotta. Hebronissa hän hallitsi seitsemän vuotta, ja Jerusalemissa hän hallitsi kolmekymmentä kolme vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Hän kuoli päästyään korkeaan ikään, elämästä, rikkaudesta ja kunniasta kylliksi saaneena, ja hänen poikansa Salomo tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Daavidin vaiheet, sekä aikaisemmat että myöhemmät, ovat kirjoitettuina näkijä Samuelin historiassa, profeetta Naatanin historiassa ja tietäjä Gaadin historiassa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'samoin koko hänen hallituksensa ja hänen tekemänsä urotyöt sekä hänen, Israelin ja kaikkien maitten valtakuntien kohtalot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Salomo, Daavidin poika, vahvistui kuninkuudessaan, ja Herra, hänen Jumalansa, oli hänen kanssaan ja teki hänet erittäin suureksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Salomo antoi kutsun kaikelle Israelille, tuhannen- ja sadanpäämiehille, tuomareille ja kaikille ruhtinaille koko Israelissa ja perhekuntien päämiehille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'Salomo ja koko seurakunta hänen kanssaan menivät uhrikukkulalle, joka oli Gibeonissa, sillä siellä oli Jumalan ilmestysmaja, jonka Herran palvelija Mooses oli tehnyt erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Mutta Jumalan arkin Daavid oli tuonut Kirjat-Jearimista siihen paikkaan, jonka Daavid oli sille valmistanut. Hän oli näet pystyttänyt sille teltan Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Vaskialttari, jonka Besalel, Uurin poika, Huurin pojanpoika, oli rakentanut, oli siellä Herran asumuksen edessä. Salomo ja seurakunta etsivät häntä siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Salomo uhrasi siellä Herran edessä ilmestysmajan vaskialttarilla. Hän uhrasi sen päällä tuhat polttouhria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'Sinä yönä Jumala ilmestyi Salomolle ja sanoi hänelle: \"Ano, mitä tahdot minun sinulle antavan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Salomo vastasi Jumalalle: \"Sinä olet tehnyt suuren laupeuden isälleni Daavidille ja tehnyt minut kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Niin toteutukoon nyt, Herra Jumala, sinun isälleni Daavidille antamasi sana. Olethan pannut minut hallitsemaan kansaa, jota on paljon kuin tomua maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Anna siis minulle viisautta ja taitoa lähteä ja tulla tämän kansan edellä, sillä kuka voi muuten jakaa oikeutta tälle suurelle kansallesi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Jumala sanoi Salomolle: \"Koska sinulla on tämä mieli etkä anonut rikkautta, tavaraa ja kunniaa, et vihamiestesi henkeä, etkä myöskään anonut pitkää ikää, vaan anoit itsellesi viisautta ja taitoa jakaaksesi oikeutta kansalleni, jonka kuninkaaksi olen sinut tehnyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'niin sinulle annetaan viisautta ja taitoa. Lisäksi annan sinulle rikkautta, tavaraa ja kunniaa, niin ettei sitä ole ollut niin paljon kellään kuninkaalla ennen sinua eikä tule olemaan jälkeesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Käytyään uhrikukkulalla, joka oli Gibeonissa, Salomo palasi ilmestysmajalta Jerusalemiin ja hallitsi Israelia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Salomo kokosi sotavaunuja ja ratsumiehiä, niin että hänellä oli tuhat neljäsataa sotavaunua ja kaksitoista tuhatta ratsumiestä. Hän sijoitti ne vaunukaupunkeihin ja kuninkaan luo Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Kuningas toimitti niin, että Jerusalemissa oli hopeaa ja kultaa kuin kiviä, ja setripuuta niin paljon kuin metsäviikunapuita Alankomaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Hevoset, joita Salomolla oli, tuotiin Egyptistä ja Kuvesta. Kuninkaan kauppiaat noutivat niitä Kuvesta maksua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Egyptistä tuodut vaunut maksoivat kuusisataa hopeasekeliä ja hevonen sata viisikymmentä. Samoin tuotiin niitä heidän välityksellään kaikille heettiläisten ja aramilaisten kuninkaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 18, 'Salomo käski ryhtyä rakentamaan temppeliä Herran nimelle ja kuninkaallista linnaa itselleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Salomo määräsi seitsemänkymmentä tuhatta miestä taakankantajiksi ja kahdeksankymmentä tuhatta miestä kivenhakkaajiksi vuoristoon ja niille kolmetuhatta kuusisataa työnjohtajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Salomo lähetti Huuramille, Tyyron kuninkaalle, sanan: \"Tee minulle sama, minkä teit isälleni Daavidille, jolle lähetit setripuita, että hän rakentaisi itselleen linnan siinä asuakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Katso, minä rakennan temppelin Herran, Jumalani, nimelle, pyhittääkseni sen hänelle, että siinä poltettaisiin hyvänhajuista suitsutusta hänen edessään, pidettäisiin aina esillä näkyleipiä ja uhrattaisiin polttouhreja aamuin ja illoin, sapatteina, uudenkuun päivinä ja Herran, meidän Jumalamme, juhlina. Tämä on Israelin ikiaikainen velvollisuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Temppeli, jonka minä rakennan, on oleva suuri, sillä meidän Jumalamme on suurin kaikista jumalista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Kuka kykenisi rakentamaan hänelle huoneen? Taivaisiin ja taivasten taivaisiin hän ei mahdu. Mikä siis olen minä rakentamaan hänelle temppeliä muuta varten kuin uhratakseni hänen edessään?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Niin lähetä nyt minulle mies, joka on taitava tekemään kulta-, hopea-, vaski- ja rautatöitä, niin myös töitä purppuranpunaisista, helakanpunaisista ja sinipunaisista langoista, ja joka osaa veistää veistoksia, työskentelemään yhdessä niiden taitajien kanssa, joita minulla on Juudassa ja Jerusalemissa ja jotka isäni Daavid on hankkinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Lähetä minulle setripuita, sypressipuita ja santelipuita Libanonilta, sillä minä tiedän, että palvelijasi osaavat hakata Libanonin puita. Katso, palvelijani olkoot palvelijoidesi kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Minulle on hankittava paljon puuta, sillä temppeli, jonka minä rakennan, on oleva suuri ja ihmeellinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Katso, minä annan kirvesmiehille, jotka puita hakkaavat, kaksikymmentä tuhatta koor-mittaa vehnää, palvelijoittesi ravinnoksi, ja kaksikymmentä tuhatta koor-mittaa ohria, kaksikymmentä tuhatta bat-mittaa viiniä ja kaksikymmentä tuhatta bat-mittaa öljyä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Huuram, Tyyron kuningas, vastasi kirjeellä, jonka hän lähetti Salomolle: \"Sen tähden, että Herra rakastaa kansaansa, hän on asettanut sinut heidän kuninkaakseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Huuram sanoi: \"Kiitetty olkoon Herra, Israelin Jumala, joka on tehnyt taivaan ja maan, siitä että hän on antanut kuningas Daavidille viisaan pojan, jolla on älyä ja ymmärrystä rakentaa temppeli Herralle ja kuninkaallinen linna itselleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Nyt lähetän taitavan, ymmärtäväisen miehen, Huuram-Aabin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'joka on daanilaisen vaimon poika ja jonka isä on tyyrolainen. Hän osaa tehdä kulta- ja hopea-, vaski- ja rauta-, kivi- ja puutöitä, niin myös töitä purppuranpunaisista ja sinipunaisista langoista, valkoisista pellavalangoista ja helakanpunaisista langoista. Hän osaa veistää veistoksia ja sommitella kaikkia taideteoksia, joita hänen tehtäväkseen annetaan, yhdessä taitajiesi ja herrani, isäsi Daavidin, taitajien kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Lähettäköön siis herrani palvelijoilleen vehnää, ohria, öljyä ja viiniä, niin kuin hän on sanonut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'ja me hakkaamme puita Libanonilta niin paljon, kuin tarvitset, ja kuljetamme ne lautoissa meritse sinulle Jaafoon. Toimita sinä ne sitten ylös Jerusalemiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Salomo toimitti kaikkien muukalaisten miesten väestönlaskun Israelin maassa, sen jälkeen kun hänen isänsä Daavid oli sen heistä toimittanut. Heitä huomattiin olevan sata viisikymmentäkolme tuhatta kuusisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Näistä hän teki seitsemänkymmentä tuhatta taakankantajiksi, kahdeksankymmentä tuhatta kivenhakkaajiksi vuoristoon ja kolmetuhatta kuusisataa työnjohtajiksi, joiden oli pidettävä väki työssä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Salomo alkoi rakentaa Herran temppeliä Jerusalemiin, Moorian vuorelle, jossa Herra oli ilmestynyt hänen isälleen Daavidille, siihen paikkaan, jonka Daavid oli valmistanut, jebusilaisen Ornanin puimatantereelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Hän alkoi rakentamisen toisen kuun toisena päivänä, neljäntenä hallitusvuotenaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Tällaisen perustuksen Salomo laski rakennettavalle Jumalan temppelille: pituus oli vanhan mitan mukaan, kuusikymmentä kyynärää, leveys kaksikymmentä kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Eteinen, temppelin itäpäässä, oli yhtä pitkä kuin temppeli leveä, kaksikymmentä kyynärää, ja sen korkeus oli kaksikymmentä kyynärää. Hän päällysti sen sisältä puhtaalla kullalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Suuren huoneen hän laudoitti sisältä sypressipuulla, jonka hän päällysti parhaalla kullalla ja johon hän laittoi palmuja ja ketjuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Hän koristi huoneen kalliilla kivillä. Kulta oli Parvaimin kultaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Hän päällysti huoneen, palkit, kynnykset, seinät ja ovet, kullalla ja kaiverrutti kerubeja seiniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Hän teki kaikkeinpyhimmän huoneen. Se oli yhtä pitkä kuin temppeli leveä, kaksikymmentä kyynärää, ja myös kaksikymmentä kyynärää leveä. Hän päällysti sen parhaalla kullalla, joka painoi kuusisataa talenttia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Kultanaulojen paino oli viisikymmentä sekeliä. Myös yläsalit hän päällysti kullalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Kaikkein pyhimpään huoneeseen hän teki kaksi kerubia, taitavasti tehtyä, ja päällysti ne kullalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Kerubien siipien pituus oli yhteensä kaksikymmentä kyynärää. Toisen kerubin toinen siipi oli viisi kyynärää pitkä ja kosketti huoneen toista seinää, ja sen toinen siipi oli viisi kyynärää pitkä ja ulottui toisen kerubin siipeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Toisen kerubin toinen siipi oli viisi kyynärää pitkä ja ulottui huoneen toiseen seinään, ja sen toinen siipi oli viisi kyynärää pitkä ja oli kiinni toisen kerubin siivessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Nämä kerubit levittivät siipensä kaksikymmentä kyynärää leveälle, ja ne seisoivat jaloillaan, kasvot käännettyinä huoneeseen päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Hän teki esiripun sinipunaisista, purppuranpunaisista ja helakanpunaisista langoista ja valkoisista pellavalangoista ja laittoi siihen kerubeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Hän teki temppelin eteen kaksi pylvästä, kolmenkymmenen viiden kyynärän korkuista. Pylväänpää, joka oli niiden päässä, oli viisi kyynärää korkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Hän teki ketjuja kaikkeinpyhimpään, ja hän pani niitä pylväiden päähän. Hän teki sata granaattiomenaa ja asetti ne ketjuihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Hän pystytti pylväät temppelin eteen, toisen oikealle puolelle ja toisen vasemmalle puolelle: oikeanpuoliselle hän antoi nimen Jaakin ja vasemmanpuoliselle nimen Booas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Hän teki alttarin vaskesta, kaksikymmentä kyynärää pitkän, kaksikymmentä kyynärää leveän ja kymmenen kyynärää korkean.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Hän teki myös meren, valetun, kymmenen kyynärää leveän reunasta reunaan, ympäriinsä pyöreän, ja viisi kyynärää korkean. Kolmekymmentä kyynärää pitkä mittanuora ulottui sen ympäri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Sen alaosassa oli yltympäri häränkuvia, jotka kulkivat sen ympäri. Ne ympäröivät merta joka puolelta. Niitä oli kymmenen kullakin kyynärällä. Härkiä oli kahdessa rivissä, meren kanssa yhteen valettuina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Se seisoi kahdentoista härän varassa, joista kolme oli käännettynä pohjoiseen, kolme länteen, kolme etelään ja kolme itään päin. Meri oli niiden yläpuolella, niiden varassa, ja kaikkien niiden takamukset olivat sisäänpäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Se oli kämmenen paksuinen, ja sen reuna oli maljan reunan kaltainen, puhjenneen liljan muotoinen. Siihen mahtui paljon, se veti kolmetuhatta bat-mittaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Hän teki myös kymmenen allasta ja asetti viisi oikealle puolelle ja viisi vasemmalle puolelle pesemistä varten. Sillä niissä huuhdottiin se, mikä kuului polttouhriin. Mutta meri oli pappien peseytymistä varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Hän teki myös kymmenen kultaista lampunjalkaa, niin kuin niistä oli säädetty, ja pani ne temppelisaliin, viisi oikealle puolelle ja viisi vasemmalle puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Hän teki myös kymmenen pöytää ja asetti ne temppelisaliin, viisi oikealle puolelle ja viisi vasemmalle puolelle. Hän teki myös sata kultamaljaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Hän teki pappien esipihan ja suuren esikartanon sekä esikartanon ovet. Ovet hän päällysti vaskella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Meren hän asetti oikealle sivulle, kaakkoa kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Huuram teki myös kattilat, lapiot ja maljat. Huuram sai suoritetuksi työn, mikä hänen oli tehtävä kuningas Salomolle Jumalan temppeliin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'kaksi pylvästä ja kaksi palloa, pylväänpäätä, pylväiden päähän, ja kaksi ristikkokoristetta peittämään kahta pallonmuotoista pylväänpäätä, jotka olivat pylväitten päässä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'ja neljäsataa granaattiomenaa kahteen ristikkokoristeeseen, kaksi riviä granaattiomenia kumpaankin ristikkokoristeeseen, peittämään kahta pallonmuotoista pylväänpäätä, jotka olivat pylväitten päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Hän teki telineet ja rakensi altaat telineitten päälle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'ja yhden meren ja kaksitoista härkää sen alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Kattilat, lapiot ja haarukat sekä kaikki niihin kuuluvat esineet Huuram-Aabiv teki kuningas Salomolle Herran temppeliin kiillotetusta vaskesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Kuningas valatti ne savimuotteihin Jordanin lakeudella Sukkotin ja Seredan välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Salomo teetti kaikkia näitä esineitä erittäin paljon, sillä vasken painoa ei määrätty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Salomo teetti myös kaikki esineet, joita tuli olla Herran temppelissä: kulta-alttarin, pöydät, joilla näkyleivät olivat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'lampunjalat lamppuineen, jotka oli sytytettävä säädetyllä tavalla kaikkeinpyhimmän eteen, puhtaasta kullasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'kultaisine kukkalehtineen, lamppuineen ja lamppusaksineen – puhtainta kultaa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'veitset, maljat, kupit ja hiilipannut puhtaasta kullasta; ja temppelin oviaukkojen sisemmät ovet, jotka veivät kaikkeinpyhimpään, sekä ne temppelin ovet, jotka veivät temppelisaliin, kullasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Kun kaikki työ, minkä Salomo teetti Herran temppeliin, oli valmis, Salomo vei sinne isänsä Daavidin pyhät lahjat. Hopean, kullan ja kaikki esineet hän pani Jumalan temppelin aarrekammioihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Salomo kokosi Israelin vanhimmat ja kaikki sukukuntien johtomiehet, israelilaisten perhekuntien päämiehet, Jerusalemiin, tuomaan Herran liitonarkin Daavidin kaupungista, se on Siionista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Kuninkaan luo kokoontuivat kaikki Israelin miehet juhlapäivänä, joka on seitsemännessä kuussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Kun kaikki Israelin vanhimmat olivat tulleet saapuville, nostivat leeviläiset arkin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'ja veivät arkin ja ilmestysmajan sinne, sekä kaiken pyhän kaluston, joka oli teltassa. Leeviläiset papit veivät ne sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Kuningas Salomo seisoi arkin edessä sekä koko Israelin kansa, joka oli kokoontunut hänen luokseen, ja he uhrasivat lampaita ja nautoja niin paljon, että niitä ei voitu luetella eikä laskea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Papit toivat Herran liitonarkin paikoilleen temppelin kuoriin, kaikkeinpyhimpään, kerubien siipien alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Sillä kerubit levittivät siipensä sen paikan yli, missä arkki oli. Siten kerubit peittivät ylhäältä päin arkin ja sen korennot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Korennot olivat niin pitkiä, että niiden arkista ulkonevat päät saattoi nähdä kaikkeinpyhimmän edustalta, mutta ulkoa niitä ei voinut nähdä. Ne jäivät sinne tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Arkissa ei ollut muuta kuin ne kaksi taulua, jotka Mooses oli pannut sinne Hoorebilla, kun Herra oli tehnyt liiton israelilaisten kanssa heidän lähdettyään Egyptistä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Papit lähtivät pyhäköstä. Kaikki siellä olevat papit olivat pyhittäytyneet osastoihin katsomatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'Kaikki leeviläiset veisaajat, Aasaf, Heeman ja Jedutun poikineen ja veljineen, seisoivat hienoihin pellavavaatteisiin puettuina symbaaleineen, harppuineen ja lyyroineen itään päin alttarista. Heidän kanssaan oli 120 pappia, jotka puhalsivat torviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'Puhaltajien ja veisaajien oli yhdyttävä yhtaikaa ja yhteen ääneen ylistämään ja kiittämään Herraa. Torvien, symbaalien ja muiden soittimien soidessa viritettiin Herran ylistys: \"Hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.\" Silloin pilvi täytti Herran temppelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Papit eivät voineet astua toimittamaan virkaansa pilven tähden, koska Herran kirkkaus täytti Jumalan temppelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Salomo sanoi: \" Herra on sanonut tahtovansa asua pimeässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Mutta minä olen rakentanut huoneen sinulle asunnoksi, asuinsijan, asuaksesi siinä ikiajat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Kuningas käänsi kasvonsa ja siunasi koko Israelin seurakunnan, ja koko Israelin seurakunta seisoi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Hän sanoi: \"Kiitetty olkoon Herra, Israelin Jumala, joka on täyttänyt kädellään sen, mitä hän puhui suullaan isälleni Daavidille, sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, '\'Siitä päivästä saakka, jona vein kansani Egyptistä, en ole mistään Israelin sukukunnasta valinnut yhtään kaupunkia, että siihen rakennettaisiin temppeli, missä nimeni asuisi, enkä myöskään ole valinnut ketään olemaan kansani Israelin ruhtinaana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Mutta Jerusalemin olen valinnut nimeni asuinsijaksi, ja Daavidin olen valinnut kansani Israelin ylle.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Isäni Daavid aikoi rakentaa temppelin Herran, Israelin Jumalan, nimelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Mutta Herra sanoi isälleni Daavidille: \'Kun aiot rakentaa temppelin nimelleni, niin tosin teet siinä hyvin, että sitä aiot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Kuitenkaan sinä et ole rakentava temppeliä, vaan poikasi, joka lähtee kupeistasi, hän on rakentava temppelin nimelleni.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Herra on täyttänyt sanansa, minkä hän puhui: olen noussut isäni Daavidin sijaan ja istun Israelin valtaistuimella, niin kuin Herra puhui, ja olen rakentanut temppelin Herran, Israelin Jumalan, nimelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Olen sijoittanut siihen arkin, jossa on se Herran liitto, jonka hän teki israelilaisten kanssa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Sitten hän astui Herran alttarin eteen koko Israelin seurakunnan nähden ja ojensi kätensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Salomo oli näet teettänyt lavan vaskesta, viisi kyynärää pitkän, viisi kyynärää leveän ja kolme kyynärää korkean, ja asettanut sen esikartanon keskelle. Sille hän nousi, polvistui koko Israelin seurakunnan nähden, ojensi kätensä taivasta kohti');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'ja sanoi: \" Herra, Israelin Jumala, ei ole sinun vertaistasi Jumalaa, ei taivaassa eikä maan päällä, sinun, joka pidät liiton ja säilytät laupeuden palvelijoitasi kohtaan, jotka vaeltavat edessäsi kaikesta sydämestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Sinä olet pitänyt, mitä puhuit palvelijallesi Daavidille, isälleni. Minkä suullasi puhuit, sen kädelläsi täytit, niin kuin nyt on tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Pidä nytkin, Herra, Israelin Jumala, mitä puhuit palvelijallesi Daavidille, isälleni, sanoen: \'Aina on mies suvustasi oleva edessäni, istumassa Israelin valtaistuimella, jos vain poikasi pitävät vaarin teistään, niin että he vaeltavat lakini mukaan, niin kuin olet vaeltanut edessäni.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Toteutukoon nyt, Herra, Israelin Jumala, sanasi, jonka puhuit palvelijallesi Daavidille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Mutta asuuko Jumala todella maan päällä ihmisten keskellä? Katso, taivaisiin ja taivasten taivaisiin sinä et mahdu, kuinka sitten tähän temppeliin, jonka olen rakentanut!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Käänny kuitenkin palvelijasi rukouksen ja anomisen puoleen, Herra, Jumalani, niin että kuulet huudon ja rukouksen, jonka palvelijasi edessäsi rukoilee,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'ja että silmäsi ovat päivät ja yöt avoinna tätä temppeliä kohti, tätä paikkaa kohti, johon sinä olet sanonut asettavasi nimesi, niin että kuulet rukouksen, jonka palvelijasi tähän paikkaan päin kääntyneenä rukoilee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Kuule palvelijasi ja kansasi Israelin rukoukset, jotka he rukoilevat tähän paikkaan päin kääntyneinä, kuule asuinpaikastasi, taivaasta, ja kun kuulet, niin anna anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Jos joku rikkoo lähimmäistään vastaan ja hänet pannaan valalle ja vannotetaan, ja jos hän tulee ja vannoo alttarisi edessä tässä temppelissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'kuule taivaasta ja auta palvelijasi oikeuteensa. Tee niin, että kostat syylliselle ja annat hänen tekojensa tulla hänen päänsä päälle, mutta julistat syyttömän syyttömäksi ja annat hänelle hänen vanhurskautensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Jos vihollinen voittaa kansasi Israelin, sen tähden että he ovat tehneet syntiä sinua vastaan, mutta he kääntyvät ja kiittävät nimeäsi, rukoilevat ja anovat armoa kasvojesi edessä tässä temppelissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'kuule taivaasta ja anna anteeksi kansasi Israelin synti ja tuo heidät takaisin tähän maahan, jonka olet antanut heille ja heidän isilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Kun taivas pidättää sateen, koska he ovat tehneet syntiä sinua vastaan, mutta kun he rukoilevat kääntyneinä tähän paikkaan päin ja ylistävät nimeäsi ja kääntyvät synnistään, koska olet nöyryyttänyt heitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'kuule taivaasta ja anna anteeksi palvelijoittesi ja kansasi Israelin synti – sillä osoitat heille hyvän tien, jota heidän tulee vaeltaa – ja suo sade maallesi, jonka olet antanut kansallesi perintöosaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Jos maahan tulee nälänhätä, rutto, jos tulee nokitähkä ja viljanruoste, jos tulevat heinäsirkat ja tuhosirkat, jos sen viholliset ahdistavat sitä maassa, jossa sen portit ovat, jos tulee mikä tahansa vitsaus tai vaiva,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'ja jos joku ihminen, kuka hyvänsä, tai koko kansasi Israel, rukoilee ja anoo armoa, kun he kukin tuntevat vitsauksen ja tuskan, joka on kohdannut heitä, ja ojentavat kätensä tähän temppeliin päin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'kuule silloin taivaasta, asuinpaikastasi, ja anna anteeksi ja anna jokaiselle aivan hänen tekojensa mukaan, koska sinä tunnet hänen sydämensä – sillä sinä yksin tunnet ihmislasten sydämet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'että he pelkäisivät sinua ja vaeltaisivat teitäsi, niin kauan kuin he elävät tässä maassa, jonka olet isillemme antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Myös jos joku muukalainen, joka ei ole kansaasi Israelia, tulee kaukaisesta maasta suuren nimesi, väkevän kätesi ja ojennetun käsivartesi tähden – jos hän tulee ja rukoilee kääntyneenä tähän temppeliin päin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'kuule taivaasta, asuinpaikastasi, häntä ja tee kaikki, mitä muukalainen sinulta rukoilee, että kaikki maan kansat tuntisivat nimesi ja pelkäisivät sinua, samoin kansasi Israel, ja tulisivat tietämään, että olet ottanut nimiisi tämän temppelin, jonka olen rakentanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Jos kansasi lähtee sotaan vihollisiaan vastaan sitä tietä, jota heidät lähetät, ja he rukoilevat sinua kääntyneinä tähän kaupunkiin päin, jonka olet valinnut, ja tähän temppeliin päin, jonka olen sinun nimellesi rakentanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'kuule taivaasta heidän rukouksensa ja anomisensa ja hanki heille oikeus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Jos he tekevät syntiä sinua vastaan – sillä ei ole ihmistä, joka ei syntiä tee – ja vihastut heihin ja annat heidät vihollisen valtaan, niin että heidän vangitsijansa vievät heidät vangeiksi kaukaiseen tai läheiseen maahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'mutta jos he sitten menevät itseensä siinä maassa, johon heidät on viety vangeiksi, kääntyvät ja anovat sinulta armoa vankeutensa maassa, sanoen: \'Me olemme tehneet syntiä, tehneet väärin ja olleet jumalattomat\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'ja palaavat luoksesi kaikesta sydämestään ja kaikesta sielustaan vankeutensa maassa, johon heidät on viety vangeiksi, ja rukoilevat kääntyneinä tähän maahan päin, jonka sinä olet heidän isilleen antanut, tähän kaupunkiin päin, jonka sinä olet valinnut, ja tähän temppeliin päin, jonka olen nimellesi rakentanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'kuule taivaasta, asuinpaikastasi, heidän rukouksensa ja anomisensa, hanki heille oikeus ja anna anteeksi kansallesi, mitä he ovat rikkoneet sinua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Olkoot siis, Jumalani, silmäsi avoinna, ja tarkatkoot korvasi rukouksia tässä paikassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Ja nyt, nouse, Herra Jumala, tule leposijaasi, sinä ja sinun voimasi arkki. Pappisi, Herra Jumala, olkoot puetut autuuteen, ja pyhäsi riemuitkoot siitä, mikä hyvä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Herra Jumala, älä hylkää voideltuasi. Muista armolupauksiasi, jotka annoit Daavidille, palvelijallesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Kun Salomo oli lakannut rukoilemasta, tuli taivaasta tuli ja kulutti polttouhrin ja teurasuhrit, ja Herran kirkkaus täytti temppelin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'niin että papit eivät voineet mennä Herran temppeliin, sillä Herran kirkkaus täytti Herran temppelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Kun kaikki israelilaiset näkivät tulen tulevan alas ja näkivät temppelin päällä Herran kirkkauden, he polvistuivat kivillä päällystetylle pihalle kasvoilleen maahan ja rukoilivat ja kiittivät Herraa siitä, että hän on hyvä ja että hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Kuningas ja kaikki kansa uhrasivat teurasuhrin Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Kuningas Salomo uhrasi teurasuhrina kaksikymmentäkaksi tuhatta nautaa ja satakaksikymmentä tuhatta lammasta. Näin he, kuningas ja koko kansa, vihkivät Herran temppelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Papit olivat seisaallaan kukin virkatoimessaan. Leeviläiset käsissään Herran soittimet, jotka kuningas Daavid oli teettänyt, seisoivat kiittämässä Herraa Daavidin ylistysvirsillä siitä, että hänen armonsa pysyy iankaikkisesti. Heitä vastapäätä papit soittivat torvia koko Israelin seistessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Salomo pyhitti Herran temppelin edessä olevan esipihan keskiosan, sillä hänen oli uhrattava siellä polttouhri ja rauhanuhrin rasvat, koska polttouhri, ruokauhri ja rasvat eivät mahtuneet vaskialttarille, jonka Salomo oli teettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Salomo vietti siihen aikaan juhlaa seitsemän päivää, ja koko Israel hänen kanssaan. Se oli sangen suuri kokous, johon kokoonnuttiin aina sieltä saakka, mistä mennään Hamatiin, ja aina Egyptin purolta asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Kahdeksantena päivänä heillä oli juhlakokous. Sillä he viettivät alttarin vihkimistä seitsemän päivää ja juhlaa seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Mutta seitsemännen kuun kahdentenakymmenentenä kolmantena päivänä hän päästi kansan menemään teltoilleen. He iloitsivat ja olivat hyvillä mielin siitä hyvästä, minkä Herra oli tehnyt Daavidille ja Salomolle ja kansalleen Israelille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Kun Salomo oli saanut valmiiksi Herran temppelin ja kuninkaan linnan ja menestynyt kaikessa, mitä oli ajatellut tehdä Herran temppelissä ja omassa linnassaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Herra ilmestyi Salomolle yöllä ja sanoi hänelle: \"Minä olen kuullut rukouksesi ja valinnut tämän paikan uhripaikakseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Katso, jos suljen taivaan, niin ettei tule sadetta, katso, jos käsken heinäsirkkojen syödä maan tai jos lähetän ruton kansaani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'mutta kansani, joka on otettu nimiini, nöyrtyy, ja he rukoilevat ja etsivät kasvojani ja palaavat pahoilta teiltään, minä kuulen taivaasta ja annan anteeksi heidän syntinsä ja teen heidän maansa jälleen terveeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Nyt silmäni ovat avoinna, ja korvani tarkkaavat rukouksia tässä paikassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Nyt olen valinnut ja pyhittänyt tämän temppelin, että nimeni olisi siinä iäti. Niin silmäni ja sydämeni tulevat aina olemaan siinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Jos sinä vaellat edessäni, niin kuin isäsi Daavid vaelsi, ja teet kaiken, mitä olen käskenyt sinun tehdä, ja noudatat käskyjäni ja oikeuksiani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'pidän pystyssä kuninkaallisen valtaistuimesi, niin kuin minä lupasin isällesi Daavidille sanoen: \'Aina on mies suvustasi hallitseva Israelia.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Mutta jos te käännytte pois ja hylkäätte käskyni ja säädökseni, jotka olen teille antanut, ja menette ja palvelette muita jumalia ja kumarratte niitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'kiskaisen sellaiset irti maastani, jonka olen heille antanut, ja heitän pois kasvojeni edestä tämän temppelin, jonka olen nimelleni pyhittänyt, ja teen sen sananparreksi ja ivapuheeksi kaikille kansoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Tämän temppelin tähden, joka ennen oli korkein, jokainen ohikulkija kauhistuu. Kun hän kysyy: \'Miksi Herra on näin tehnyt tälle maalle ja tälle temppelille?\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'niin vastataan: \'Siksi, että he hylkäsivät Herran, isiensä Jumalan, joka oli vienyt heidät pois Egyptin maasta, ja liittyivät muihin jumaliin, kumarsivat niitä ja palvelivat niitä. Sen takia hän on antanut kaiken tämän pahan kohdata heitä.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Niiden kahdenkymmenen vuoden kuluttua, joina Salomo rakensi Herran temppelin ja oman linnansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'Salomo linnoitti ne kaupungit, jotka Huuram oli hänelle antanut, ja hän asetti israelilaisia niihin asumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Salomo meni Hamat-Soobaan ja valloitti sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Hän linnoitti myös Tadmorin erämaassa ja kaikki varastokaupungit, jotka hän oli rakentanut Hamatiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Vielä hän linnoitti Ylä-Beet-Hooronin ja Ala-Beet-Hooronin muureilla, porteilla ja salvoilla varustetuiksi kaupungeiksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'samoin Baalatin ja kaikki varastokaupungit, jotka hänellä oli, ja kaikki vaunukaupungit ja ratsumiesten kaupungit ja kaikki muut paikat, mitkä hän tahtoi linnoittaa Jerusalemissa ja Libanonilla ja kaikessa hallitsemassaan maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Kaiken kansan, mitä oli jäänyt jäljelle heettiläisistä, amorilaisista, perissiläisistä, hivviläisistä ja jebusilaisista, kaikki, jotka eivät olleet israelilaisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'ne niiden jälkeläiset, jotka vielä olivat jäljellä maassa ja joita israelilaiset eivät olleet tuhonneet, Salomo saattoi työveron alaisiksi aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Mutta israelilaisista Salomo ei tehnyt ketään työorjakseen, vaan heitä oli sotilaina, hänen vaunusoturiensa päälliköinä ja hänen sotavaunujensa ja ratsumiestensä päälliköinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Maaherrojen virkamiehiä oli Salomolla kaksisataa viisikymmentä, jotka vallitsivat väkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Salomo toi faraon tyttären Daavidin kaupungista linnaan, jonka hän oli tälle rakentanut, sillä hän sanoi: \"Älköön nainen asuko Daavidin, Israelin kuninkaan, linnassa. Se on näet pyhäkkö, koska Herran arkki oli tullut sinne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Siihen aikaan Salomo uhrasi polttouhreja Herralle Herran alttarilla, jonka hän oli rakentanut eteisen edustalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Hän uhrasi kunakin päivänä sen päivän uhrit Mooseksen käskyn mukaan, sapatteina ja uudenkuun päivinä sekä juhlina kolme kertaa vuodessa: happamattoman leivän juhlana, viikkojuhlana ja lehtimajanjuhlana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Hän oli asettanut, niin kuin hänen isänsä Daavid oli säätänyt, pappien osastot toimittamaan virkaansa ja leeviläiset suorittamaan tehtäviään, veisaamaan ylistysvirsiä ja palvelemaan pappeja, kunakin päivänä sen päivän tehtävissä, sekä ovenvartijat osastoittain joka ovelle, sillä niin oli Jumalan mies Daavid käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Eikä missään ollut poikettu kuninkaan käskyistä, mitä tuli pappeihin, leeviläisiin ja aarrekammioihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Salomon kaikki työt Herran temppelin perustamispäivästä Herran temppelin täydelliseen valmistumiseen olivat saatetut päätökseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Siihen aikaan Salomo meni Esjon-Geberiin ja Eilatiin, joka on meren rannalla Edomin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Huuram lähetti palvelijansa tuomaan hänelle laivoja. Palvelijat olivat meritaitoisia ja menivät yhdessä Salomon palvelijoiden kanssa Oofiriin ja noutivat sieltä kultaa neljäsataa viisikymmentä talenttia ja toivat sen kuningas Salomolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Kun Saban kuningatar kuuli Salomon maineen, hän tuli Jerusalemiin koettelemaan Salomoa arvoituksilla. Hän tuli sangen suuren seurueen kanssa mukanaan kameleja, jotka kantoivat hajuaineita, kultaa hyvin paljon ja kalliita kiviä. Kun hän tuli Salomon luo, hän puhui tälle kaikki, mitä hänellä oli mielessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Salomo selitti hänelle kaikki hänen kysymyksensä. Mikään ei jäänyt Salomolle ongelmaksi, jota hän ei olisi hänelle selittänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Kun Saban kuningatar näki kaiken Salomon viisauden, linnan, jonka hän oli rakentanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'ruuat hänen pöydällään, kuinka hänen palvelijansa asuivat ja hänen palvelusväkensä palveli ja kuinka he olivat puetut, ja kun hän näki hänen juomanlaskijansa ja kuinka he olivat puetut, ja hänen yläsalinsa, josta hän nousi Herran temppeliin, hän meni lähes hengettömäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Sitten hän sanoi kuninkaalle: \"Totta oli puhe, jonka kuulin kotimaahani sinusta ja viisaudestasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'En uskonut, mitä sanottiin, ennen kuin itse tulin ja sain omin silmin nähdä. Katso, puoltakaan suuresta viisaudestasi ei ollut minulle kerrottu. Olet paljon suurempi, kuin olin kuullut huhuttavan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Onnellisia ovat miehesi, onnellisia nämä palvelijasi, jotka saavat aina olla edessäsi ja kuulla viisauttasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Kiitetty olkoon Herra, Jumalasi, joka sinuun on niin mieltynyt, että on asettanut sinut valtaistuimelleen olemaan kuninkaana Herran, Jumalasi, kunniaksi. Sen tähden, että Jumalasi rakastaa Israelia ja tahtoo pitää sen ainiaan pystyssä, hän on antanut sinut heille kuninkaaksi tekemään sitä, mikä on oikeus ja vanhurskaus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Hän antoi kuninkaalle sata kaksikymmentä talenttia kultaa, sangen paljon hajuaineita ja kalliita kiviä. Milloinkaan ei ole ollut sellaisia hajuaineita kuin ne, jotka Saban kuningatar antoi kuningas Salomolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Huuramin palvelijat ja Salomon palvelijat, jotka toivat kultaa Oofirista, toivat myös santelipuuta ja kalliita kiviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Kuningas teetti santelipuusta portaat Herran temppeliin ja kuninkaan palatsiin ja lyyroja ja harppuja laulajille. Sellaisia ei ollut ennen nähty Juudan maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Kuningas Salomo taas antoi Saban kuningattarelle kaikki, mitä tämä halusi ja pyysi, antoipa vielä enemmän, kuin mitä tämä oli tuonut kuninkaalle. Sitten hän lähti paluumatkalle ja meni palvelijoineen omaan maahansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Kullan paino, mikä yhtenä vuotena tuli Salomolle, oli kuusisataa kuusikymmentä kuusi talenttia kultaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'paitsi mitä kauppamiehet ja kaupustelijat toivat. Sen lisäksi kaikki Arabian kuninkaat ja maan käskynhaltijat toivat Salomolle kultaa ja hopeaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Kuningas Salomo teetti kaksisataa suurta kilpeä pakotetusta kullasta ja käytti jokaiseen kilpeen kuusisataa sekeliä pakotettua kultaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'samoin kolmesataa pienempää kilpeä pakotetusta kullasta, ja käytti jokaiseen kilpeen kolmesataa sekeliä kultaa. Kuningas asetti ne Libanonin metsän puista rakennettuun taloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Vielä kuningas teetti suuren norsunluisen valtaistuimen ja päällysti sen puhtaalla kullalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Valtaistuimessa oli kuusi porrasta ja astinlauta, kullalla kiinnitettyinä valtaistuimeen. Istuimen kummallakin puolella oli käsinoja, ja kaksi leijonaa seisoi käsinojan vieressä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Kaksitoista leijonaa seisoi siinä kuudella portaalla, kummallakin puolella. Sellaista ei ole tehty missään muussa valtakunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Kaikki kuningas Salomon juoma-astiat olivat kultaa, ja kaikki Libanonin metsän puista rakennetun talon astiat olivat puhdasta kultaa. Hopeaa ei Salomon päivinä pidetty minkään arvoisena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Kuninkaalla oli näet laivoja, jotka kulkivat Tarsiiseen Huuramin palvelijoiden kanssa. Kerran kolmessa vuodessa Tarsiin laivat tulivat ja toivat kultaa ja hopeaa, norsunluuta, apinoita ja riikinkukkoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Kuningas Salomo oli kaikkia maan kuninkaita suurempi rikkaudessa ja viisaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Kaikki maan kuninkaat pyrkivät näkemään Salomoa kuullakseen hänen viisauttaan, jonka Jumala oli antanut hänen sydämeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'He toivat kukin lahjansa: hopea- ja kultaesineitä, vaatteita, aseita, hajuaineita, hevosia ja muuleja, joka vuosi vuoden tarpeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Salomolla oli neljätuhatta hevosvaljakkoa vaunuineen ja kaksitoista tuhatta ratsumiestä. Ne hän sijoitti vaunukaupunkeihin ja kuninkaan luo Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Hän vallitsi kaikkia kuninkaita Eufrat-virrasta aina filistealaisten maahan ja Egyptin rajaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Kuningas toimitti niin, että Jerusalemissa oli hopeaa kuin kiviä, ja setripuuta niin paljon kuin metsäviikunapuita Alankomaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Hevosia tuotiin Salomolle Egyptistä ja kaikista muista maista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Mitä muuta Salomosta on kerrottavaa, hänen sekä aikaisemmista että myöhemmistä vaiheistaan, se on kirjoitettuna profeetta Naatanin historiassa, siilolaisen Ahian ennustuksessa ja näkijä Jeddon näyssä Jerobeamista, Nebatin pojasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Salomo hallitsi Jerusalemissa koko Israelia neljäkymmentä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Salomo meni lepoon isiensä luo, ja hänet haudattiin isänsä Daavidin kaupunkiin. Hänen poikansa Rehabeam tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Rehabeam meni Sikemiin, sillä koko Israel oli tullut Sikemiin tekemään häntä kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Kun Jerobeam, Nebatin poika, kuuli sen – hän oli Egyptissä, jonne oli paennut kuningas Salomoa – Jerobeam palasi Egyptistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'He lähettivät kutsumaan hänet. Jerobeam ja koko Israel tuli saapuville, ja he puhuivat Rehabeamille sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, '\"Isäsi teki ikeemme raskaaksi, mutta huojenna sinä nyt se kova työ, jota isäsi teetti, ja se raskas ies, jonka hän pani niskaamme, niin palvelemme sinua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Hän vastasi heille: \"Odottakaa kolme päivää ja tulkaa sitten takaisin luokseni.\" Ja kansa meni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Kuningas Rehabeam neuvotteli vanhojen kanssa, jotka olivat palvelleet hänen isäänsä Salomoa, kun tämä vielä eli, ja kysyi: \"Kuinka te neuvotte vastaamaan tälle kansalle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'He vastasivat hänelle ja sanoivat: \"Jos sinä olet hyvä tätä kansaa kohtaan, olet armollinen heille ja puhut heille hyviä sanoja, he ovat palvelijoitasi koko elinaikasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Mutta hän hylkäsi tämän neuvon, jonka vanhat hänelle antoivat, ja neuvotteli nuorten miesten kanssa, jotka olivat kasvaneet hänen kanssaan ja jotka palvelivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Hän kysyi heiltä: \"Kuinka te neuvotte meitä vastaamaan tälle kansalle, joka on puhunut minulle sanoen: \'Huojenna ies, jonka isäsi on pannut niskaamme\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Nuoret miehet, jotka olivat kasvaneet hänen kanssaan, vastasivat hänelle sanoen: \"Sano näin tälle kansalle, joka on puhunut sinulle sanoen: \'Isäsi teki ikeemme raskaaksi, mutta huojenna sinä se meiltä\' – sano heille näin: \'Pikkusormeni on paksumpi kuin isäni lantio.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Jos siis isäni on sälyttänyt selkäänne raskaan ikeen, minä teen ikeenne vielä raskaammaksi. Jos isäni on kurittanut teitä raipoilla, minä kuritan teitä piikkiruoskilla.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Jerobeam ja koko kansa tuli Rehabeamin luo kolmantena päivänä, niin kuin kuningas oli käskenyt, sanoen: \"Tulkaa takaisin luokseni kolmantena päivänä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Silloin kuningas antoi heille kovan vastauksen. Sillä kuningas Rehabeam hylkäsi vanhojen neuvon');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'ja puhui heille nuorten miesten neuvon mukaan, sanoen: \"Jos isäni on tehnyt ikeenne raskaaksi, minä teen sen vielä raskaammaksi. Jos isäni on kurittanut teitä raipoilla, minä kuritan teitä piikkiruoskilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Kuningas ei siis kuullut kansaa, sillä Jumala salli sen niin täyttääkseen sanansa, jonka hän oli puhunut Jerobeamille, Nebatin pojalle, siilolaisen Ahian kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Kun koko Israel huomasi, ettei kuningas heitä kuullut, kansa vastasi kuninkaalle näin: \"Mitä osaa meillä on Daavidiin? Meillä ei ole perintöosaa Iisain poikaan. Teltoillesi, Israel, joka mies! Valvo nyt huonettasi, Daavid!\" Ja koko Israel meni teltoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Rehabeam tuli ainoastaan niiden israelilaisten kuninkaaksi, jotka asuivat Juudan kaupungeissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Kun kuningas Rehabeam lähetti matkaan verotöiden valvojan Hadoramin, israelilaiset kivittivät tämän kuoliaaksi. Silloin kuningas Rehabeam nousi nopeasti vaunuihinsa ja pakeni Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Näin Israel luopui Daavidin suvusta, aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Kun Rehabeam tuli Jerusalemiin, hän kokosi Juudan ja Benjaminin heimot, sata kahdeksankymmentä tuhatta sotakuntoista valiomiestä sotimaan Israelia vastaan ja palauttamaan kuninkuuden Rehabeamille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Mutta Jumalan miehelle Semajalle tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, '\"Sano Rehabeamille, Salomon pojalle, Juudan kuninkaalle, ja koko Israelille Juudassa ja Benjaminissa näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, '\'Näin sanoo Herra: Älkää menkö sotimaan veljiänne vastaan. Palatkaa kukin kotiinne, sillä tämä asia on minulta.\'\" He kuulivat Herran sanoja, kääntyivät takaisin eivätkä menneet Jerobeamia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Rehabeam asui Jerusalemissa ja linnoitti lujasti Juudan kaupunkeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Hän linnoitti Beetlehemin, Eetanin, Tekoan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Beet-Suurin, Sookon, Adullamin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gatin, Maaresan, Siifin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoraimin, Laakiin, Asekan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Soran, Aijalonin ja Hebronin, jotka ovat Juudassa ja Benjaminissa. Hän linnoitti ne lujiksi kaupungeiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Hän varusti linnoitukset ja sijoitti niihin päämiehiä sekä muonavarastoja, öljyä ja viiniä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'ja jokaiseen kaupunkiin kilpiä ja keihäitä. Hän varusti ne hyvin lujasti. Juuda ja Benjamin olivat hänen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Papit ja leeviläiset, mitä koko Israelissa oli, tulivat kaikilta alueiltaan ja asettuivat palvelemaan häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Sillä leeviläiset jättivät laidunmaansa ja perintömaansa ja lähtivät Juudaan ja Jerusalemiin, koska Jerobeam ja hänen poikansa olivat hylänneet heidät, niin etteivät he saaneet palvella pappeina Herraa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'Jerobeam kun oli asettanut itselleen pappeja uhrikukkuloita varten sekä pukkeja ja vasikoita varten, jotka hän oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Heitä seurasivat kaikista Israelin sukukunnista Jerusalemiin ne, jotka panivat sydämensä etsimään Herraa, Israelin Jumalaa, uhratakseen Herralle, isiensä Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Näin he vahvistivat Juudan valtakuntaa ja tukivat Rehabeamia, Salomon poikaa, kolme vuotta, sillä he vaelsivat Daavidin ja Salomon teitä kolme vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Rehabeam otti vaimokseen Mahlatin, joka oli Daavidin pojan Jerimotin ja Iisain pojan Eliabin tyttären Abihailin tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Tämä synnytti hänelle pojat Jeuksen, Semarjan ja Saahamin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Hänen jälkeensä hän nai Maakan, Absalomin tyttären, joka synnytti hänelle Abian, Attain, Siisan ja Selomitin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Rehabeam rakasti Maakaa, Absalomin tytärtä, enemmän kuin kaikkia muita vaimojaan ja sivuvaimojaan. Sillä hän oli ottanut kahdeksantoista vaimoa ja kuusikymmentä sivuvaimoa, ja hänelle syntyi kaksikymmentä kahdeksan poikaa ja kuusikymmentä tytärtä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Rehabeam asetti Abian, Maakan pojan, päämieheksi, ruhtinaaksi hänen veljiensä joukkoon, sillä hän aikoi tehdä hänet kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Viisaasti hän jakoi kaikki Juudan ja Benjaminin maakunnat ja kaikki varustetut kaupungit kaikkien poikiensa kesken ja antoi heille runsaasti elintarpeita ja hankki heille paljon vaimoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Kun Rehabeamin kuninkuus oli vahvistunut ja hän oli voimistunut, hän hylkäsi Herran lain, hän ja koko Israel hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Mutta kuningas Rehabeamin viidentenä hallitusvuotena hyökkäsi Siisak, Egyptin kuningas, Jerusalemin kimppuun, sillä he olivat tulleet uskottomiksi Herraa kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'Hänellä oli mukanaan sotavaunuja tuhat kaksisataa ja ratsumiehiä kuusikymmentä tuhatta, ja lukematon oli se väki, joka tuli hänen kanssaan Egyptistä: libyalaisia, sukkilaisia ja kuusilaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Hän valloitti Juudan varustetut kaupungit ja tuli aina Jerusalemiin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Profeetta Semaja tuli Rehabeamin ja Juudan päämiesten luo, jotka olivat kokoontuneet Jerusalemiin Siisakia pakoon, ja sanoi heille: \"Näin sanoo Herra: Te olette hylänneet minut, sen tähden minäkin olen hylännyt teidät Siisakin käsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Israelin päämiehet ja kuningas nöyrtyivät ja sanoivat: \" Herra on vanhurskas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Kun Herra näki heidän nöyrtyvän, Semajalle tuli tämä Herran sana: \"He ovat nöyrtyneet. En tuhoa heitä, vaan annan heidän vähäksi aikaa pelastua, eikä vihaani vuodateta Jerusalemin päälle Siisakin käden kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Kuitenkin heidän on tultava hänen palvelijoikseen, että he tulisivat tietämään, mitä on palvella minua ja mitä on palvella vieraiden maiden valtakuntia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Siisak, Egyptin kuningas, hyökkäsi Jerusalemin kimppuun ja otti Herran temppelin aarteet ja kuninkaan linnan aarteet, hän otti ne kaikki tyynni. Hän otti myös kaikki kultakilvet, jotka Salomo oli teettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'Kuningas Rehabeam teetti niiden sijaan vaskikilvet ja jätti ne henkivartijoiden päälliköiden haltuun, jotka vartioivat kuninkaan linnan ovella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Niin usein kuin kuningas meni Herran temppeliin, menivät henkivartijatkin ja kantoivat niitä ja veivät ne sitten takaisin henkivartijoiden huoneeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Sen tähden, että Rehabeam nöyrtyi, Herran viha kääntyi hänestä pois, niin ettei tullut täydellistä tuhoa, ja olivathan asiat Juudassa vielä hyvin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Kuningas Rehabeam vahvistui Jerusalemissa ja hallitsi edelleen. Sillä Rehabeam oli neljänkymmenen yhden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi seitsemäntoista vuotta Jerusalemissa, siinä kaupungissa, jonka Herra oli valinnut kaikista Israelin sukukunnista sijoittaakseen nimensä siihen. Hänen äitinsä oli nimeltään Naema, ammonilainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Hän teki sitä, mikä on pahaa, sillä hän ei kiinnittänyt sydäntään etsimään Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Rehabeamin vaiheet, sekä aikaisemmat että myöhemmät, ovat kirjoitetut profeetta Semajan ja näkijä Iddon historiaan, sukuluettelojen tapaan. Mutta Rehabeamin ja Jerobeamin väliset taistelut jatkuivat kaiken aikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Rehabeam meni lepoon isiensä luo, ja hänet haudattiin Daavidin kaupunkiin. Hänen poikansa Abia tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Kuningas Jerobeamin kahdeksantenatoista hallitusvuotena tuli Abia Juudan kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Hän hallitsi kolme vuotta Jerusalemissa. Hänen äitinsä nimi oli Mikaja, Uurielin tytär, Gibeasta. Abia ja Jerobeam olivat sodassa keskenään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Abia aloitti sodan urhoollisella sotajoukolla, neljälläsadalla tuhannella sankarilla, mutta Jerobeam asettui sotarintaan häntä vastaan kahdeksallasadalla tuhannella valiomiehellä, sotasankarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Abia nousi Semaraimin vuoren laelle Efraimin vuoristossa ja sanoi: \"Kuulkaa minua, Jerobeam ja koko Israel!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Täytyyhän teidän tietää, että Herra, Israelin Jumala, on antanut Daavidille ja hänen pojilleen ikiajoiksi Israelin kuninkuuden, lujan kuin suolaliitto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Mutta Jerobeam, Nebatin poika, Daavidin pojan Salomon palvelija, nousi ja kapinoi herraansa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Hänen luokseen kokoontui tyhjäntoimittajia, kelvottomia miehiä, ja he pääsivät voitolle Rehabeamista, Salomon pojasta, sillä Rehabeam oli nuori ja arka eikä voinut heitä vastustaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Nyt te luulette voivanne vastustaa Herran kuninkuutta, joka on Daavidin poikien käsissä, koska teitä on suuri joukko ja teillä on kultavasikat, jotka Jerobeam on teettänyt teille jumaliksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Ettekö te ole karkottaneet Herran pappeja, Aaronin poikia, ja leeviläisiä, ja itse tehneet itsellenne pappeja, niin kuin muiden maiden kansat tekevät? Kuka tahansa tuli papinvirkaan vihittäväksi, mukanaan mulli ja seitsemän pässiä, hänestä tuli epäjumalan pappi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Mutta meidän Jumalamme on Herra, ja häntä me emme ole hylänneet. Pappeina palvelevat Herraa Aaronin pojat, ja leeviläiset toimittavat palvelustehtäviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'He polttavat Herralle polttouhreja joka aamu ja joka ilta ja hyvänhajuista suitsutusta, ja he latovat leivät päälletysten aitokultaiselle pöydälle ja sytyttävät joka ilta kultaisen seitsenhaaraisen lampun lamppuineen. Sillä me hoidamme Herran, meidän Jumalamme, meille antamat tehtävät, mutta te olette hänet hylänneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Katso, meidän kanssamme, edellämme on Jumala ja hänen pappinsa ja hälytystorvet ovat toitottamassa teitä vastaan. Te israelilaiset, älkää sotiko Herraa, isienne Jumalaa, vastaan, sillä se ei teille onnistu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Mutta Jerobeam oli pannut väkeä kiertämään heidän taakseen väijyksiin, niin että toiset olivat Juudan miesten edessä ja toiset väijyksissä heidän takanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Kun Juudan miehet kääntyivät, niin, katso, heillä oli sota edessä ja takana. Silloin he huusivat Herraa, ja papit puhalsivat torviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Ja Juudan miehet nostivat sotahuudon. Kun Juudan miehet nostivat sotahuudon, antoi Jumala Abian ja Juudan voittaa Jerobeamin ja koko Israelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Israelilaiset kääntyivät Juudan miehiä pakoon, ja Jumala antoi heidät näiden käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Abia väkineen tuotti heille suuren tappion, niin että israelilaisia kaatui viisisataa tuhatta valiomiestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Näin israelilaisia nöyryytettiin siihen aikaan, mutta Juudan miehet voimistuivat, sillä he turvautuivat Herraan, isiensä Jumalaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Abia ajoi Jerobeamia takaa ja valloitti häneltä muutamia kaupunkeja: Beetelin ja sen tytärkaupungit, Jesanan ja sen tytärkaupungit ja Efronin ja sen tytärkaupungit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Jerobeam ei enää tullut voimiinsa Abian elinpäivinä, vaan Herra löi häntä, niin että hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Mutta Abia vahvistui. Hän otti itselleen neljätoista vaimoa, ja hänelle syntyi kaksikymmentä kaksi poikaa ja kuusitoista tytärtä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Mitä muuta on kerrottavaa Abiasta, hänen vaelluksestaan ja hänen puheistaan, se on kirjoitettuna profeetta Iddon selityskirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 23, 'Abia meni lepoon isiensä luo, ja hänet haudattiin Daavidin kaupunkiin. Hänen poikansa Aasa tuli kuninkaaksi hänen jälkeensä. Hänen aikanaan oli maassa rauha kymmenen vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Aasa teki sitä, mikä oli hyvää ja oikeaa Herran, hänen Jumalansa, silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Hän poisti vieraat alttarit ja uhrikukkulat, murskasi patsaat ja hakkasi maahan aserapaalut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Hän kehotti Juudaa etsimään Herraa, heidän isiensä Jumalaa, ja noudattamaan lakia ja käskyjä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Kaikista Juudan kaupungeista hän poisti uhrikukkulat ja auringonpatsaat, ja valtakunnassa oli rauha hänen aikanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Hän rakensi varustettuja kaupunkeja Juudaan, koska maassa oli rauha eikä hänellä näinä vuosina ollut mitään sotaa, sillä Herra oli suonut hänen päästä rauhaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Hän sanoi Juudalle: \"Linnoittakaamme nämä kaupungit, ympäröikäämme ne muureilla ja torneilla, ovilla ja salvoilla. Vielä on maa vallassamme, sen tähden että olemme etsineet Herraa, Jumalaamme. Me olemme etsineet häntä, ja hän on suonut meidän päästä rauhaan joka taholla.\" He rakensivat, ja se onnistui heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Aasalla oli sotajoukko, joka oli varustettu kilvillä ja keihäillä: Juudasta oli kolmesataa tuhatta miestä ja Benjaminista kaksisataa kahdeksankymmentä tuhatta, jotka kantoivat kilpeä ja jännittivät jousta. Kaikki nämä olivat väkeviä sankareita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Mutta kuusilainen Sera lähti heitä vastaan sotajoukolla, jossa oli miehiä tuhannen tuhatta ja sotavaunuja kolmesataa, ja hän tuli Maaresaan saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Aasa lähti häntä vastaan, ja he asettuivat rintamaan Sefatan laaksoon, Maaresaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Aasa huusi Herraa, Jumalaansa, ja sanoi: \" Herra, sinä yksin voit auttaa taistelussa voimakkaan ja voimattoman välillä. Auta meitä, Herra, Jumalamme, sillä sinuun me turvaudumme ja sinun nimessäsi me olemme tulleet tätä suurta joukkoa vastaan. Herra, sinä olet Jumalamme. Älä salli ihmisen päästä voitolle sinusta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Herra antoi Aasan ja Juudan voittaa kuusilaiset, ja kuusilaiset pakenivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Aasa ja väki, joka oli hänen kanssaan, ajoivat heitä takaa Gerariin saakka. Kuusilaisia kaatui niin paljon, ettei heistä jäänyt ketään henkiin, sillä Herra ja hänen sotajoukkonsa tuhosivat heidät. Nämä ottivat paljon saalista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'valloittivat kaikki kaupungit Gerarin ympäriltä, sillä Herran kauhu oli vallannut nämä, ja ryöstivät kaikki kaupungit, sillä niissä oli paljon ryöstettävää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Jopa karjojen teltatkin he valtasivat. He veivät pois saaliinaan paljon lampaita ja kameleja ja palasivat Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Jumalan Henki tuli Asarjaan, Oodedin poikaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Hän meni Aasaa vastaan ja sanoi hänelle: \"Kuulkaa minua, Aasa ja koko Juuda ja Benjamin. Herra on kanssanne, kun olette hänen kanssaan. Jos etsitte häntä, löydätte hänet, mutta jos hylkäätte hänet, hän hylkää teidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Kauan aikaa Israel oli ilman oikeaa Jumalaa, ilman opetusta antavaa pappia ja ilman lakia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Mutta kun he ahdistuksessaan palasivat Herran, Israelin Jumalan, luo ja etsivät häntä, niin he löysivät hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Niinä aikoina ei ollut rauhaa niillä, jotka lähtivät ja tulivat, vaan suuri sekasorto vallitsi kaikkien maakuntien asukasten keskuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Kansa törmäsi kansaa vastaan ja kaupunki kaupunkia vastaan, sillä Jumala oli saattanut heidät sekasortoon lähettäen kaikkia ahdistuksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Mutta te olkaa lujat älkääkä antako kättenne vaipua, sillä työllänne on palkkansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Kun Aasa kuuli nämä profeetta Oodedin sanat ja ennustuksen, hän rohkaisi mielensä ja toimitti pois iljetykset koko Juudan ja Benjaminin maasta ja niistä kaupungeista, jotka hän oli valloittanut Efraimin vuoristosta, ja uudisti Herran alttarin, joka oli Herran eteisen edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Hän kokosi koko Juudan ja Benjaminin ja myös heidän luonaan asuvat muukalaiset, jotka olivat tulleet Efraimista, Manassesta ja Simeonista, sillä monet olivat siirtyneet Israelista hänen luokseen nähtyään, että Herra, hänen Jumalansa, oli hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'He kokoontuivat Jerusalemiin Aasan viidennentoista hallitusvuoden kolmannessa kuussa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'ja uhrasivat sinä päivänä Herralle saaliista, minkä he olivat tuoneet, seitsemänsataa nautaa ja seitsemäntuhatta lammasta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'He tekivät liiton, että etsisivät Herraa, isiensä Jumalaa, kaikesta sydämestään ja kaikesta sielustaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'ja että jokainen, joka ei etsinyt Herraa, Israelin Jumalaa, oli surmattava, olipa hän pieni tai suuri, mies tai nainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'He vannoivat valan Herralle suurella äänellä riemun raikuessa ja trumpettien ja torvien pauhatessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Koko Juuda iloitsi siitä valasta, sillä he olivat vannoneet sen kaikesta sydämestään, ja he etsivät Herraa kaikesta mielestään ja löysivät hänet. Herra soi heidän päästä rauhaan joka taholla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Kuningas Aasa erotti Maakankin, äitinsä, kuningattaren arvosta, koska tämä oli pystyttänyt inhotuksen Aseralle. Aasa kukisti inhotuksen, rouhensi ja poltti sen Kidronin laaksossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Mutta uhrikukkulat eivät hävinneet Israelista. Kuitenkin Aasan sydän oli vilpitön, niin kauan kuin hän eli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Hän vei Jumalan temppeliin isänsä pyhät lahjat ja omat pyhät lahjansa: hopeaa, kultaa ja kalustoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Eikä ollut sotaa Aasan kolmanteenkymmenenteen viidenteen hallitusvuoteen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Aasan kolmantenakymmenentenä kuudentena hallitusvuotena lähti Baesa, Israelin kuningas, Juudaa vastaan ja linnoitti Raaman estääkseen ketään pääsemästä Aasan, Juudan kuninkaan luota tai hänen luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Aasa toi hopeaa ja kultaa Herran temppelin ja kuninkaan linnan aarrekammioista ja lähetti sen Benhadadille, Aramin kuninkaalle, joka asui Damaskossa, ja käski sanoa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, '\"Onhan liitto välillämme, minun ja sinun, niin kuin oli minun isäni ja sinun isäsi välillä. Katso, minä lähetän sinulle hopeaa ja kultaa. Mene ja riko liittosi Baesan, Israelin kuninkaan, kanssa, että hän lähtisi pois kimpustani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Benhadad kuuli kuningas Aasaa ja lähetti sotajoukkojensa päälliköt Israelin kaupunkeja vastaan, ja he valtasivat Iijonin, Daanin ja Aabel-Maimin sekä kaikki Naftalin kaupunkien varastohuoneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Kun Baesa kuuli sen, hän lakkasi linnoittamasta Raamaa ja keskeytti työnsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Kuningas Aasa otti työhön koko Juudan, ja he veivät pois Raamasta kivet ja puut, joilla Baesa oli sitä linnoittanut. Niillä hän linnoitti Geban ja Mispan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'Siihen aikaan tuli näkijä Hanani Aasan, Juudan kuninkaan, luo ja sanoi hänelle: \"Koska turvauduit Aramin kuninkaaseen etkä turvautunut Herraan, Jumalaasi, sen tähden on Aramin kuninkaan sotajoukko päässyt käsistäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Eikö kuusilaisia ja libyalaisia ollut suuri sotajoukko, eikö heillä ollut hyvin paljon sotavaunuja ja ratsumiehiä? Mutta turvautuessasi Herraan hän antoi heidät käsiisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Sillä Herran silmät katsovat tarkasti kaikkea maata, että hän voimakkaasti auttaisi niitä, joiden sydän on eheä häntä kohtaan. Tässä teit tyhmästi, sillä tästä lähtien sinulla on oleva sotia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Mutta Aasa vihastui näkijään ja pani hänet vankilaan, sillä niin vihoissaan hän oli hänelle tästä. Myös muutamille muille kansasta Aasa teki siihen aikaan väkivaltaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Aasan vaiheet, sekä aikaisemmat että myöhemmät, katso, ne ovat kirjoitettuina Juudan ja Israelin kuningasten kirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'Kolmantenakymmenentenä yhdeksäntenä hallitusvuotenaan Aasa sairastui jaloistaan, ja hänen tautinsa yltyi hyvin kovaksi. Mutta taudissaankaan hän ei etsinyt Herraa, vaan lääkäreitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Sitten Aasa meni lepoon isiensä luo ja kuoli neljäntenäkymmenentenä ensimmäisenä hallitusvuotenaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Hänet haudattiin omaan hautaansa, jonka hän oli hakkauttanut itselleen Daavidin kaupunkiin. Hänet laskettiin vuoteelle, joka oli täytetty hajuaineilla ja erilaisilla voideseoksilla, ja hänen kunniakseen poltettiin hyvin runsas kuolinsuitsutus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Hänen poikansa Joosafat tuli kuninkaaksi hänen jälkeensä. Hän voimistui Israelia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Hän sijoitti sotaväkeä kaikkiin Juudan varustettuihin kaupunkeihin ja asetti maaherroja Juudan maahan ja Efraimin kaupunkeihin, jotka hänen isänsä Aasa oli valloittanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Herra oli Joosafatin kanssa, sillä hän vaelsi isänsä Daavidin aikaisempia teitä eikä etsinyt baaleja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'vaan hän etsi isänsä Jumalaa ja vaelsi hänen käskyjensä mukaan eikä tehnyt, niin kuin Israel teki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Herra vahvisti kuninkuuden hänen käsissään, ja koko Juuda antoi lahjoja Joosafatille, niin että hänelle tuli paljon rikkautta ja kunniaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Kun hänen rohkeutensa kasvoi Herran teillä, hän poisti vielä uhrikukkulatkin ja aserapaalut Juudasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Kolmantena hallitusvuotenaan hän lähetti ylimmät virkamiehensä Benhailin, Obadjan, Sakarjan, Netanelin ja Miikajan Juudan kaupunkeihin antamaan opetusta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'ja heidän kanssaan leeviläiset Semajan, Netanjan, Sebadjan, Asahelin, Semiramotin, Joonatanin, Adonian, Tobian ja Toob-Adonian, leeviläiset. Näillä oli mukanaan papit Elisama ja Jooram.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Nämä opettivat Juudassa, ja heillä oli mukanaan Herran lain kirja. He kiertelivät kaikissa Juudan kaupungeissa ja opettivat kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Herran kauhu valtasi kaikki Juudaa ympäröivien maiden valtakunnat, niin etteivät ne sotineet Joosafatia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Osa filistealaisia toi Joosafatille lahjoja ja hopeaa veroksi. Arabialaisetkin toivat hänelle lampaita ja vuohia: seitsemäntuhatta seitsemänsataa pässiä ja seitsemäntuhatta seitsemänsataa pukkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Joosafat tuli yhä mahtavammaksi, jopa hyvin mahtavaksi, ja hän rakensi Juudaan linnoja ja varastokaupunkeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Hänellä oli suuria varastoja Juudan kaupungeissa ja sotilaita, väkeviä sankareita, Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Tämä oli heidän palvelusvuoronsa heidän perhekuntiensa mukaan: Juudan tuhannenpäämiehet olivat: päämies Adna ja hänen kanssaan kolmesataa tuhatta väkevää sankaria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'Hänen rinnallaan oli päämies Joohanan ja hänen kanssaan kaksisataa kahdeksankymmentä tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'Hänen rinnallaan oli Amasja, Sikrin poika, Herran vapaaehtoinen, ja hänen kanssaan kaksisataa tuhatta väkevää sankaria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Benjaminista: Eljada, väkevä sankari, ja hänen kanssaan kaksisataa tuhatta jousella ja kilvellä aseistettua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'Hänen rinnallaan oli Joosabad ja hänen kanssaan sata kahdeksankymmentä tuhatta sotaan varustettua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Nämä palvelivat kuningasta, ja lisäksi ne, jotka kuningas oli sijoittanut varustettuihin kaupunkeihin koko Juudaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Joosafatille tuli paljon rikkautta ja kunniaa, ja hän lankoutui Ahabin kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Muutamien vuosien kuluttua hän meni Ahabin luo Samariaan. Ahab teurastutti hänelle ja väelle, joka oli hänen mukanaan, paljon lampaita ja nautoja. Ahab yllytti häntä lähtemään sotaan Gileadin Raamotia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Israelin kuningas Ahab sanoi Juudan kuninkaalle Joosafatille: \"Lähdetkö kanssani Gileadin Raamotiin?\" Hän vastasi hänelle: \"Minä niin kuin sinä, minun kansani niin kuin sinun kansasi. Tulen kanssasi sotaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Joosafat sanoi Israelin kuninkaalle: \"Kysy kuitenkin ensin, mitä Herra sanoo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Israelin kuningas kokosi profeetat, neljäsataa miestä, ja sanoi heille: \"Onko meidän lähdettävä sotaan Gileadin Raamotia vastaan, vai onko minun oltava lähtemättä?\" He vastasivat: \"Lähde, Jumala antaa sen kuninkaan käsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Joosafat sanoi: \"Eikö täällä ole enää ketään muuta Herran profeettaa, jolta voisimme kysyä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Israelin kuningas vastasi Joosafatille: \"On vielä mies, jolta voisimme kysyä Herran mieltä, mutta minä vihaan häntä, sillä hän ei koskaan ennusta minulle hyvää, vaan aina pahaa. Hän on Miika, Jimlan poika.\" Joosafat sanoi: \"Älköön kuningas niin puhuko.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Israelin kuningas kutsui erään hoviherran ja sanoi: \"Nouda kiireen kaupalla Miika, Jimlan poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Mutta Israelin kuningas ja Joosafat, Juudan kuningas, istuivat kumpikin valtaistuimellaan puettuina kuninkaallisiin pukuihinsa. He istuivat puimatantereella Samarian portin ovella, ja kaikki profeetat olivat hurmoksissa heidän edessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Sidkia, Kenaanan poika, teki itselleen rautasarvet ja sanoi: \"Näin sanoo Herra: Näillä sinä pusket aramilaisia, kunnes teet heistä lopun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Kaikki profeetat ennustivat samalla tavalla sanoen: \"Mene Gileadin Raamotiin, saat voiton. Herra antaa sen kuninkaan käsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Sanansaattaja, joka oli mennyt kutsumaan Miikaa, puhui hänelle sanoen: \"Katso, kaikki profeetat ovat yhdestä suusta luvanneet kuninkaalle hyvää. Olkoon sanasi heidän sanansa kaltainen, ja lupaa sinäkin hyvää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Mutta Miika vastasi: \"Niin totta kuin Herra elää, sen minä puhun, minkä Jumalani sanoo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Kun hän tuli kuninkaan eteen, kuningas sanoi hänelle: \"Miika, onko meidän lähdettävä sotaan Gileadin Raamotiin, vai onko minun oltava lähtemättä?\" Hän vastasi hänelle: \"Menkää, saatte voiton. Heidät annetaan käsiinne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Mutta kuningas sanoi hänelle: \"Kuinka monta kertaa minun on vannotettava sinua, ettet puhu minulle muuta kuin totuutta Herran nimessä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Hän sanoi: \"Näin koko Israelin hajallaan vuorilla, niin kuin lampaat, joilla ei ole paimenta. Herra sanoi: \'Näillä ei ole isäntää, palatkoon heistä jokainen rauhassa kotiinsa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Israelin kuningas sanoi Joosafatille: \"Enkö sanonut sinulle, ettei tämä koskaan ennusta minulle hyvää, vaan aina pahaa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Mutta hän sanoi: \"Kuulkaa Herran sana: Näin Herran istuvan istuimellaan ja kaiken taivaan joukon seisovan hänen edessään, hänen oikealla ja vasemmalla puolellaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Herra sanoi: \'Kuka viekoittelisi Ahabin, Israelin kuninkaan, lähtemään sotaan, että hän kaatuisi Gileadin Raamotissa?\' Mikä vastasi niin, mikä näin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Silloin tuli eräs henki ja asettui Herran eteen ja sanoi: \'Minä viekoittelen hänet.\' Herra kysyi häneltä: \'Miten?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Hän vastasi: \'Minä menen valheen hengeksi kaikkien hänen profeettojensa suuhun.\' Silloin Herra sanoi: \'Saat viekoitella, siihen sinä pystyt. Mene ja tee niin.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Katso, nyt Herra on pannut valheen hengen näiden profeettojesi suuhun, sillä Herra on päättänyt osaksesi onnettomuuden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Silloin astui esille Sidkia, Kenaanan poika, löi Miikaa poskelle ja sanoi: \"Mitä tietä Herran Henki on poistunut minusta puhuakseen kanssasi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Miika vastasi: \"Sen saat nähdä sinä päivänä, jona kuljet huoneesta huoneeseen piiloutuaksesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Israelin kuningas sanoi: \"Ottakaa Miika ja viekää hänet takaisin Aamonin, kaupungin päällikön, ja Jooaan, kuninkaan pojan, luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'Sanokaa: \'Näin sanoo kuningas: Pankaa tämä vankilaan ja elättäkää häntä vaivaisella vedellä ja leivällä, kunnes minä palaan voittajana takaisin.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Miika vastasi: \"Jos sinä palaat voittajana takaisin, Herra ei ole puhunut kauttani.\" Vielä hän sanoi: \"Kuulkaa tämä, kaikki kansat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Israelin kuningas ja Joosafat, Juudan kuningas, menivät ylös Gileadin Raamotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Israelin kuningas sanoi Joosafatille: \"Täytyypä pukeutua tuntemattomaksi, kun käy taisteluun, mutta ole sinä omissa vaatteissasi.\" Israelin kuningas pukeutui tuntemattomaksi ja kävi taisteluun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Aramin kuningas oli käskenyt sotavaunujensa päälliköitä sanoen: \"Älkää ryhtykö taisteluun kenenkään muun kanssa, olkoon alempi tai ylempi, kuin ainoastaan Israelin kuninkaan kanssa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Kun sotavaunujen päälliköt näkivät Joosafatin, he ajattelivat: \"Tuo on Israelin kuningas\", ja ympäröivät hänet hyökätäkseen hänen kimppuunsa. Silloin Joosafat huusi, ja Herra auttoi häntä, ja Jumala houkutteli heidät pois hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Kun sotavaunujen päälliköt näkivät, ettei se ollutkaan Israelin kuningas, he vetäytyivät hänestä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Mutta eräs mies, joka oli jännittänyt jousensa ja ampui umpimähkään, satutti Israelin kuningasta vyöpanssarin ja rintahaarniskan väliin. Tämä sanoi vaunujensa ohjaajalle: \"Käännä vaunut ja vie minut pois rintamalta, sillä olen haavoittunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Mutta kun taistelu sinä päivänä yltyi yltymistään, Israelin kuningas jäi seisomaan iltaan asti vaunuihinsa niiden ollessa kohti aramilaisia. Auringonlaskun aikaan hän kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Joosafat, Juudan kuningas, palasi onnellisesti takaisin kotiinsa Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Jeehu, Hananin poika, näkijä, meni kuningas Joosafatia vastaan ja sanoi hänelle: \"Oliko sinun autettava jumalatonta, ja rakastatko niitä, jotka vihaavat Herraa? Sen tähden päälläsi on Herran viha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Kuitenkin sinusta on löydetty myös hyvää, sillä sinä olet polttanut aserat maasta ja kiinnittänyt sydämesi Jumalan etsimiseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Joosafat palasi Jerusalemiin. Hän meni jälleen kansan keskuuteen Beersebasta lähtien aina Efraimin vuoristoon saakka, ja palautti heidät takaisin Herran, heidän isiensä Jumalan, luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Hän asetti tuomareita maahan kaikkiin Juudan varustettuihin kaupunkeihin, kaupunki kaupungilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Hän sanoi tuomareille: \"Katsokaa, mitä te teette, sillä ette ole tekemässä ihmisten tuomioita, vaan Herran tuomioita, ja hän on kanssanne antaessanne tuomion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Hallitkoon nyt teitä Herran pelko. Ottakaa vaari siitä, mitä teette, sillä Herrassa, Jumalassamme, ei ole vääryyttä eikä puolueellisuutta, eikä hän ota lahjuksia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Myös Joosafat asetti Jerusalemiin leeviläisiä, pappeja ja Israelin perhekuntien päämiehiä jakamaan Herran oikeutta ja ratkaisemaan riita-asioita. He palasivat Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Hän käski heitä sanoen: \"Tehkää Herraa peläten uskollisesti ja ehyellä sydämellä näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Jokaisessa riita-asiassa, minkä veljenne, jotka asuvat kaupungeissaan, tuovat eteenne, koskipa se murhaa tai lakia, käskyä, säädöksiä tai oikeuksia, varoittakaa heitä, niin etteivät saattaisi itseään vikapäiksi Herran edessä ja ettei viha kohtaisi teitä ja veljiänne. Näin tehkää, ettette tulisi syynalaisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Katso, ylipappi Amarja olkoon teillä esimiehenä kaikissa Herran asioissa ja Sebadja, Ismaelin poika, Juudan heimoruhtinas, kaikissa kuninkaan asioissa, ja olkoot leeviläiset teillä virkamiehinä. Olkaa lujat ja ryhtykää työhön. Herra olkoon sen kanssa, joka on hyvä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Sen jälkeen tulivat mooabilaiset ja ammonilaiset, ja heidän kanssaan myös muita kuin ammonilaisia, sotimaan Joosafatia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Tästä tultiin ilmoittamaan Joosafatille: \"Suuri joukko tulee sinua vastaan meren toiselta puolelta, Aramista, ja katso, he ovat jo Hasason-Taamarissa\". Se on Een-Gedissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Joosafat pelästyi ja kääntyi kysymään Herralta ja kuulutti paaston koko Juudaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Juuda kokoontui etsimään apua Herralta. Myös kaikista Juudan kaupungeista tultiin etsimään Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Joosafat astui esiin Juudan ja Jerusalemin seurakunnassa Herran temppelissä uuden esipihan edessä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'ja sanoi: \" Herra, meidän isiemme Jumala, sinä olet Jumala taivaassa, ja sinä hallitset kaikkia pakanakansojen valtakuntia. Kädessäsi on voima ja väkevyys, eikä kukaan kestä edessäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Sinä, meidän Jumalamme, karkotit tämän maan asukkaat kansasi Israelin tieltä ja annoit sen ystäväsi Aabrahamin jälkeläisille ikiajoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'He asettuivat tänne ja rakensivat täällä sinulle, nimellesi, pyhäkön sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, '\'Jos meitä kohtaa jokin onnettomuus, miekka, rangaistustuomio, rutto tai nälänhätä, niin me astumme tämän temppelin eteen ja sinun eteesi, sillä nimesi on tässä temppelissä, ja huudamme sinua hädässämme, ja sinä kuulet ja autat.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Katso, siinä ovat nyt ammonilaiset ja mooabilaiset ja Seirin vuoristolaiset, joiden alueen kautta sinä et antanut israelilaisten kulkea, kun he tulivat Egyptin maasta, vaan nämä kääntyivät heistä pois eivätkä tuhonneet heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'Katso, nyt he kostavat sen meille: he tulevat karkottamaan meitä maasta, joka on sinun omasi ja jonka olet antanut omaksemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Jumalamme, etkö tuomitse heitä? Sillä meillä ei ole voimaa tätä suurta joukkoa vastaan, joka hyökkää kimppuumme, emmekä itse tiedä mitä tehdä, vaan silmämme katsovat sinuun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Kaikki Juudan miehet seisoivat siinä Herran edessä pikkulapsineen, vaimoineen ja poikineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Herran Henki tuli seurakunnan keskellä Jahasieliin, Sakarjan poikaan, joka oli Benajan poika, joka Jegielin poika, joka Mattanjan poika, leeviläisen, joka oli Aasafin jälkeläisiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'ja hän sanoi: \"Kuunnelkaa, kaikki te Juudan miehet ja Jerusalemin asukkaat ja sinä kuningas Joosafat. Näin sanoo teille Herra: Älkää pelätkö älkääkä arkailko tätä suurta joukkoa, sillä sota ei ole teidän, vaan Jumalan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Menkää huomenna heitä vastaan. Katso, he nousevat Siisin solaa pitkin, ja te kohtaatte heidät laakson päässä, itään Jeruelin erämaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Mutta silloin ei ole teidän asianne taistella. Astukaa esiin, seisokaa ja katsokaa, kuinka Herra pelastaa teidät, Juuda ja Jerusalem. Älkää pelätkö älkääkä arkailko. Menkää huomenna heitä vastaan, ja Herra on oleva kanssanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Joosafat kumartui kasvoilleen maahan, ja kaikki Juudan miehet ja Jerusalemin asukkaat lankesivat Herran eteen rukoilemaan Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Ne leeviläiset, jotka olivat Kehatin ja Koorahin jälkeläisiä, nousivat ylistämään Herraa, Israelin Jumalaa, hyvin korkealla äänellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Mutta varhain seuraavana aamuna he menivät Tekoan erämaahan. Heidän lähtiessään Joosafat astui esiin ja sanoi: \"Kuulkaa minua, te Juudan ja Jerusalemin asukkaat. Uskokaa Herraan, Jumalaanne, niin te olette hyvässä turvassa, ja uskokaa hänen profeettojaan, niin menestytte.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Neuvoteltuaan kansan kanssa hän asetti veisaajat veisaamaan Herralle ylistysvirsiä pyhässä kaunistuksessa ja kulkemaan aseväen edellä sanoen: \"Kiittäkää Herraa, sillä hänen armonsa pysyy iankaikkisesti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Juuri kun he aloittivat riemuhuudon ja ylistysvirren, Herra antoi väijyjiä tulla ammonilaisten, mooabilaisten ja Seirin vuoristolaisten selkään, jotka olivat hyökänneet Juudan kimppuun, ja heidät voitettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Sillä ammonilaiset ja mooabilaiset asettuivat Seirin vuoristolaisia vastaan tuhoamaan ja hävittämään heitä, ja kun he olivat tehneet lopun Seirin asukkaista, he auttoivat toisiaan toistensa tuhoamisessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Kun Juudan miehet tulivat paikalle, josta voi tähystää erämaahan, ja kääntyivät joukkoa kohden, katso, ruumiita makasi maassa, eikä kukaan ollut pelastunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Joosafat väkineen tuli ryöstämään heiltä saalista, ja he löysivät heidän seastaan paljon sekä tavaraa että ruumiita ja kalliita esineitä. He ottivat itselleen enemmän kuin saivat kannetuksi. He ryöstivät saalista kolme päivää, sillä sitä oli paljon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Neljäntenä päivänä he kokoontuivat Beraka-laaksoon, sillä siellä he kiittivät Herraa. Siitä on sen paikan nimenä Beraka-laakso vielä tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Sen jälkeen kaikki Juudan ja Jerusalemin miehet, ja Joosafat heidän etunenässään, kääntyivät iloiten paluumatkalle Jerusalemiin, sillä Herra oli antanut heille ilon heidän vihollisistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'He tulivat soittaen harpuilla, lyyroilla ja torvilla Jerusalemiin, Herran temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Jumalan kauhu valtasi kaikkien maiden valtakunnat, kun he kuulivat Herran sotineen Israelin vihollisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Ja Joosafatin valtakunnalla oli rauha. Hänen Jumalansa soi hänen päästä rauhaan joka taholla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Joosafat hallitsi Juudaa. Hän oli kolmenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kaksikymmentä viisi vuotta. Hänen äitinsä oli nimeltään Asuba, Silhin tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Hän vaelsi isänsä Aasan tietä, siltä poikkeamatta, ja teki sitä, mikä on oikein Herran silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Mutta uhrikukkulat eivät hävinneet, eikä kansa vielä ollut kiinnittänyt sydäntään isiensä Jumalaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Mitä muuta on kerrottavaa Joosafatista, sekä hänen aikaisemmista että myöhemmistä vaiheistaan, katso, se on kirjoitettuna Jeehun, Hananin pojan, historiassa, joka on otettu Israelin kuningasten kirjaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Sen jälkeen Joosafat, Juudan kuningas, liittoutui Ahasjan, Israelin kuninkaan, kanssa, joka oli jumalaton menoissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Hän liittoutui tämän kanssa rakentaakseen laivoja, joiden oli määrä kulkea Tarsiiseen, ja niin he rakensivat laivoja Esjon-Geberissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Mutta Elieser, Doodavahun poika, Maaresasta, ennusti Joosafatia vastaan sanoen: \"Koska olet liittoutunut Ahasjan kanssa, Herra on särkevä työsi.\" Laivat rikkoutuivat eivätkä kyenneet menemään Tarsiiseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Sitten Joosafat meni lepoon isiensä luo, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Hänen poikansa Jooram tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Hänellä oli veljiä: Joosafatin pojat Asarja, Jehiel, Sakarja, Asarjahu, Miikael ja Sefatja. Nämä kaikki olivat Joosafatin, Israelin kuninkaan, poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Heidän isänsä oli antanut heille suuria lahjoja, hopeaa, kultaa ja kalleuksia, sekä varustettuja kaupunkeja Juudassa. Kuninkuuden hän oli antanut Jooramille, sillä tämä oli esikoinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Kun Jooram nousi isänsä valtaistuimelle ja vahvistui, hän tappoi miekalla kaikki veljensä, myös muutamia Israelin päämiehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Jooram oli kolmenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kahdeksan vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Hän vaelsi Israelin kuningasten tietä, kuten Ahabin suku oli tehnyt, sillä hänellä oli puolisona Ahabin tytär. Hän teki sitä, mikä on pahaa Herran silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Mutta Herra ei tahtonut tuhota Daavidin sukua, koska hän oli tehnyt liiton Daavidin kanssa ja koska hän oli luvannut antaa hänelle ja hänen pojilleen lampun ainiaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'Hänen aikanaan edomilaiset luopuivat Juudan vallanalaisuudesta ja asettivat itselleen kuninkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Jooram lähti sinne päällikköineen ja kaikkine sotavaunuineen. Hän nousi yöllä ja voitti edomilaiset, jotka olivat saartaneet hänet, ja sotavaunujen päälliköt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Niin edomilaiset luopuivat Juudan vallanalaisuudesta vapaiksi aina tähän päivään asti. Siihen aikaan luopui hänen vallanalaisuudestaan myös Libna, koska hän oli hylännyt Herran, isiensä Jumalan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Hänkin teetti uhrikukkuloita Juudan vuoristoon ja saattoi Jerusalemin asukkaat haureuteen ja vietteli Juudan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Profeetta Elialta tuli hänelle tällainen kirjoitus: \"Näin sanoo Herra, isäsi Daavidin Jumala: Koska et ole vaeltanut isäsi Joosafatin teitä etkä Aasan, Juudan kuninkaan, teitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'vaan olet vaeltanut Israelin kuningasten tietä ja saattanut Juudan ja Jerusalemin asukkaat haureuteen, niin kuin Ahabin suku saattoi heidät haureuteen, ja koska olet myös tappanut veljesi, jotka olivat sinun isäsi perhekuntaa ja sinua parempia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'katso, sen vuoksi Herra rankaisee kovalla vitsauksella kansaasi, poikiasi, vaimojasi ja kaikkea, mitä sinulla on,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'ja sinä olet sairastava vaikeaa tautia, sisusvaivaa, kunnes vuoden, parin kuluttua sisuksesi taudin voimasta tunkeutuvat ulos.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Niin Herra herätti Jooramia vastaan filistealaisten hengen ja niiden arabialaisten hengen, jotka asuivat kuusilaisten naapureina,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'ja he menivät Juudaa vastaan, valloittivat sen ja veivät saaliinaan kaiken tavaran, mitä oli kuninkaan linnassa, myös hänen poikansa ja vaimonsa, niin ettei hänelle jäänyt muuta poikaa kuin Jooahas, hänen nuorin poikansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Kaiken tämän jälkeen Herra rankaisi häntä parantumattomalla sisusvaivalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Parin vuoden kuluttua, toisen vuoden lopulla, hänen sisuksensa taudin voimasta tunkeutuivat ulos, ja hän kuoli koviin tuskiin. Mutta hänen kansansa ei polttanut hänen kunniakseen kuolinsuitsutusta, niin kuin oli poltettu hänen isiensä kunniaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Hän oli kolmenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kahdeksan vuotta. Hän meni pois kenenkään kaipaamatta, ja hänet haudattiin Daavidin kaupunkiin, mutta ei kuningasten hautoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Jerusalemin asukkaat tekivät Ahasjan, hänen nuorimman poikansa, kuninkaaksi hänen jälkeensä. Sillä kaikki häntä vanhemmat oli tappanut se rosvojoukko, joka arabialaisten kanssa oli tullut leiriin. Niin tuli Ahasja, Jooramin poika, Juudan kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Ahasja oli kahdenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa vuoden. Hänen äitinsä oli nimeltään Atalja, Omrin tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Hänkin vaelsi Ahabin suvun teitä, sillä hänen äitinsä oli häntä neuvomassa jumalattomuuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Hän teki sitä, mikä on pahaa Herran silmissä, samoin kuin Ahabin suku. Sillä he olivat hänen isänsä kuoleman jälkeen hänen neuvonantajiaan hänen turmiokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Heidän neuvostaan hän myös lähti Israelin kuninkaan Jooramin, Ahabin pojan, kanssa taistelemaan Hasaelia, Aramin kuningasta, vastaan Gileadin Raamotiin, mutta aramilaiset haavoittivat Jooramia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Hän tuli takaisin Jisreeliin parantuakseen, sillä hänessä oli haavoja, jotka häneen oli isketty Raamassa hänen taistellessaan Hasaelia, Aramin kuningasta, vastaan. Juudan kuningas Ahasja, Jooramin poika, tuli Jisreeliin katsomaan Jooramia, Ahabin poikaa, koska tämä oli sairaana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Jumalalta tuli Ahasjan tuhoksi se, että hän meni Jooramin luo. Sillä sinne tultuaan hän meni Jooramin kanssa Jeehua, Nimsin poikaa, vastaan, jonka Herra oli voidellut hävittämään Ahabin sukua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Kun Jeehu oli toimeenpanemassa Ahabin suvun tuomiota, hän tapasi Juudan ruhtinaat ja Ahasjan veljenpojat, jotka palvelivat Ahasjaa, ja surmasi heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Hän etsi Ahasjaa, ja tämä saatiin kiinni Samariassa, jossa hän piileskeli. Hänet vietiin Jeehun eteen ja surmattiin. He hautasivat hänet, sillä he sanoivat: \"Hän on Joosafatin poika, hänen, joka kaikesta sydämestään etsi Herraa.\" Eikä Ahasjan perheessä ollut ketään, joka olisi kyennyt hallitsemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Kun Atalja, Ahasjan äiti, näki, että hänen poikansa oli kuollut, hän nousi ja tuhosi koko Juudan heimon kuningassuvun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Mutta kuninkaan tytär Joosabat otti surmattavien kuninkaan poikien joukosta salaa Ahasjan pojan Jooaan ja pani hänet imettäjineen makuuhuoneeseen. Näin pappi Joojadan vaimo Joosabat, joka oli kuningas Jooramin tytär ja Ahasjan sisar, sai hänet kätketyksi Ataljalta, niin ettei tämä voinut häntä surmata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Poika oli heidän luonaan Jumalan temppeliin piilotettuna kuusi vuotta, Ataljan hallitessa maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Seitsemäntenä vuotena Joojada rohkaisi mielensä ja liittoutui sadanpäämiesten Asarjan, Jerohamin pojan, Ismaelin, Joohananin pojan, Asarjan, Oobedin pojan, Maasejan, Adajan pojan, ja Elisafatin, Sikrin pojan, kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Nämä kiertelivät Juudassa ja kokosivat leeviläiset kaikista Juudan kaupungeista sekä Israelin perhekuntien päämiehet ja tulivat Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Koko seurakunta teki Jumalan temppelissä liiton kuninkaan kanssa. Joojada sanoi heille: \"Katso, kuninkaan poika on tuleva kuninkaaksi, niin kuin Herra on puhunut Daavidin pojista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Tehkää näin: Kolmas osa teistä, papeista ja leeviläisistä, joiden on mentävä vartioon sapattina, olkoon ovenvartijoina kynnyksillä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'kolmas osa miehittäköön kuninkaan linnan ja kolmas osa Jesod-portin, ja koko kansa Herran temppelin esikartanot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Älköön kukaan muu kuin papit ja palvelusta tekevät leeviläiset menkö Herran temppeliin. He saavat mennä sisään, sillä he ovat pyhät, mutta kaikki muu kansa noudattakoon Herran määräystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Leeviläiset asettukoot kuninkaan ympärille, kullakin ase kädessä, ja joka tunkeutuu temppeliin, se surmattakoon. Näin olkaa kuninkaan luona, menköön hän ulos tai sisään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Leeviläiset ja koko Juuda tekivät kaiken, mitä pappi Joojada oli käskenyt heidän tehdä. Kukin heistä otti miehensä, sekä ne, joiden oli mentävä vartioon sapattina, että ne, jotka sapattina pääsivät vartiosta, sillä pappi Joojada ei ollut vapauttanut osastoja palveluksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Pappi Joojada antoi sadanpäämiehille keihäät, kilvet ja varustukset, jotka olivat olleet kuningas Daavidin omat ja olivat Jumalan temppelissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Hän asetti koko kansan, kullakin peitsi kädessä, temppelin eteläsivulta aina sen pohjoissivulle saakka, päin alttaria ja temppeliä kuninkaan ympärille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Sitten he toivat kuninkaan pojan esille, panivat hänen päähänsä kruunun ja antoivat hänelle lain kirjan ja tekivät hänet kuninkaaksi. Joojada ja hänen poikansa voitelivat hänet ja huusivat: \"Eläköön kuningas!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Kun Atalja kuuli kansan huudon sen juostessa ja huutaessa riemuhuutoja kuninkaalle, hän meni kansan luo Herran temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Hän näki kuninkaan seisovan korkealla paikallaan sisäänkäynnin luona, ja päälliköt ja torvensoittajat kuninkaan luona, ja kaiken maan kansan, joka riemuitsi ja puhalsi torviin, ja veisaajat, jotka soittimillaan johtivat ylistyslaulua. Silloin Atalja repäisi vaatteensa ja huusi: \"Kapina, kapina!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Mutta pappi Joojada antoi sadanpäämiesten, sotajoukon johtajien, astua esiin ja sanoi heille: \"Viekää hänet pois rivien välitse, ja se, joka yrittää seurata häntä, surmattakoon miekalla.\" Sillä pappi oli sanonut: \"Älkää surmatko häntä Herran temppelissä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'He kävivät häneen käsiksi, ja kun hän oli tullut kuninkaan linnan Hevosportin sisäänkäynnin luo, he surmasivat hänet siinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Sitten Joojada teki liiton itsensä, koko kansan ja kuninkaan kesken, että he olisivat Herran kansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Kaikki kansa meni Baalin temppeliin, ja he hävittivät sen. Sen alttarit ja kuvat he murskasivat, ja he tappoivat Mattanin, Baalin papin alttarien edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Joojada asetti päällysmiehiä Herran temppeliin, leeviläisiä pappeja, jotka Daavid oli määrännyt Herran temppeliin, uhraamaan Herran polttouhreja, niin kuin on kirjoitettuna Mooseksen laissa, riemuhuudoin ja lauluin, Daavidin järjestelyn mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Hän asetti ovenvartijat Herran temppelin porteille, ettei kukaan, joka oli jollakin tavalla saastainen, pääsisi sisään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Hän otti mukaansa sadanpäämiehet, ylimykset ja kansan hallitusmiehet sekä kaiken maan kansan ja vei kuninkaan Herran temppelistä, ja he tulivat Yläportin kautta kuninkaan linnaan ja asettivat kuninkaan kuninkaalliselle valtaistuimelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Kaikki maan kansa iloitsi, ja kaupunki pysyi rauhallisena. Mutta Ataljan he olivat surmanneet miekalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Jooas oli seitsemän vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa neljäkymmentä vuotta. Hänen äitinsä nimi oli Sibja, Beersebasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Jooas teki sitä, mikä on oikein Herran silmissä, niin kauan kuin pappi Joojada eli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Joojada otti hänelle kaksi vaimoa, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Sen jälkeen Jooas aikoi uudistaa Herran temppelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Hän kutsui kokoon papit ja leeviläiset ja sanoi heille: \"Menkää Juudan kaupunkeihin ja kootkaa kaikesta Israelista rahaa Jumalanne temppelin korjaamiseksi, vuodesta vuoteen, ja jouduttakaa tätä asiaa.\" Mutta leeviläiset eivät jouduttaneet sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Silloin kuningas kutsui luokseen ylimmäisen papin Joojadan ja sanoi hänelle: \"Miksi et ole pitänyt huolta siitä, että leeviläiset toisivat Juudasta ja Jerusalemista Herran palvelijan Mooseksen määräämän Israelin seurakunnan veron todistuksen telttamajaa varten?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Sillä jumalaton Atalja ja hänen poikansa ovat murtautuneet Jumalan temppeliin. He ovat myös käyttäneet baaleja varten kaikki Herran temppelin pyhät lahjat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Kuninkaan käskystä tehtiin arkku, ja se asetettiin Herran temppelin portin ulkopuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Juudassa ja Jerusalemissa kuulutettiin, että vero, jonka Jumalan palvelija Mooses oli erämaassa määrännyt Israelille, oli tuotava Herralle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Kaikki päämiehet ja kaikki kansa toivat iloiten rahaa ja heittivät arkkuun, kunnes se täyttyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Aina kun leeviläiset toivat arkun kuninkaan asettamien tarkastusmiesten luo huomattuaan, että siinä oli paljon rahaa, kuninkaan kirjuri ja ylimmäisen papin käskyläinen tulivat tyhjentämään arkun. Sitten he kantoivat sen takaisin paikoilleen. Niin he tekivät päivä päivältä ja kokosivat paljon rahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Sitten kuningas ja Joojada antoivat sen niille, jotka teettivät työt Herran temppelissä, ja nämä palkkasivat kivenhakkaajia ja puuseppiä uudistamaan Herran temppeliä, niin myös rauta- ja vaskiseppiä korjaamaan Herran temppeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Työnteettäjät toimivat niin, että työ edistyi heidän käsissään, ja he asettivat Jumalan temppelin entiselleen sen määrämittojen mukaan ja panivat sen kuntoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Kun he olivat päättäneet työnsä, he veivät loput rahat kuninkaalle ja Joojadalle, ja niillä teetettiin kalustoa Herran temppeliin, jumalanpalvelus- ja uhraamiskalustoa, kuppeja sekä kulta- ja hopeaesineitä. Herran temppelissä uhrattiin vakituisesti polttouhreja, niin kauan kuin Joojada eli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Mutta Joojada kävi vanhaksi ja sai elämästä kyllikseen, ja hän kuoli. Hän oli kuollessaan sadan kolmenkymmenen vuoden vanha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Hänet haudattiin Daavidin kaupunkiin kuningasten joukkoon, sillä hän oli tehnyt sitä, mikä oli hyvää Israelille ja Jumalalle ja hänen temppelilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Mutta Joojadan kuoleman jälkeen tulivat Juudan päämiehet ja kumarsivat kuningasta, ja kuningas kuuli heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'He hylkäsivät Herran, isiensä Jumalan, temppelin ja palvelivat aseroita ja jumalankuvia. Viha kohtasi Juudaa ja Jerusalemia tämän heidän rikoksensa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Hän lähetti heidän keskuuteensa profeettoja palauttamaan heidät Herran luo, ja nämä varoittivat heitä, mutta he eivät kuulleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Jumalan Henki täytti Sakarjan, pappi Joojadan pojan, ja hän astui kansan eteen ja sanoi heille: \"Näin sanoo Jumala: Miksi te rikotte Herran käskyt omaksi onnettomuudeksenne? Koska olette hylänneet Herran, hänkin hylkää teidät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Mutta he tekivät salaliiton häntä vastaan ja kivittivät hänet kuoliaaksi kuninkaan käskystä Herran temppelin esipihalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Sillä kuningas Jooas ei muistanut rakkautta, jota hänen isänsä Joojada oli hänelle osoittanut, vaan tappoi Joojadan pojan. Tämä sanoi kuollessaan: \" Herra nähköön ja kostakoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Vuoden vaihteessa kävi aramilaisten sotajoukko Jooaan kimppuun, ja he tunkeutuivat Juudaan ja Jerusalemiin asti ja tuhosivat kansasta kaikki kansan päämiehet. Kaiken saaliinsa he lähettivät Damaskon kuninkaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Sillä vaikka aramilaisten sotajoukko tuli vähälukuisena, Herra antoi näiden käsiin hyvin suuren sotajoukon, koska he olivat hylänneet Herran, isiensä Jumalan. Nämä panivat toimeen rangaistustuomion Jooaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Kun he lähtivät häntä ahdistamasta – hän jäi heidän lähtiessään hyvin sairaaksi – hänen palvelijansa tekivät salaliiton häntä vastaan pappi Joojadan pojan murhan tähden ja tappoivat hänet hänen vuoteeseensa, ja hän kuoli. Hänet haudattiin Daavidin kaupunkiin. Häntä ei kuitenkaan haudattu kuningasten hautoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Ne, jotka tekivät salaliiton häntä vastaan, olivat Saabad, ammonilaisen vaimon Simeatin poika, ja Joosabad, mooabilaisen vaimon Simritin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Hänen pojistaan, monista häntä vastaan lausutuista ennustuksista ja Jumalan temppelin jälleen rakentamisesta, katso, niistä on kirjoitettu Kuningasten kirjan selityskirjaan. Hänen poikansa Amasja tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Amasja oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kaksikymmentä yhdeksän vuotta. Hänen äitinsä oli nimeltään Jooaddan, Jerusalemista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Hän teki sitä, mikä on oikein Herran silmissä, ei kuitenkaan ehyellä sydämellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Kun hänen kuninkuutensa oli vahvistunut, hän tappoi ne palvelijansa, jotka olivat murhanneet kuninkaan, hänen isänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Mutta heidän lapsensa hän jätti surmaamatta: hän teki, niin kuin on kirjoitettu laissa, Mooseksen kirjassa, jossa Herra on käskenyt sanoen: \"Älkööt isät kuolko lasten tähden älköötkä lapset isien tähden. Kukin kuolkoon oman syntinsä tähden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Sitten Amasja kokosi Juudan miehet ja asetti heidät perhekunnittain, tuhannen- ja sadanpäämiesten mukaan, koko Juudan ja Benjaminin. Hän piti katselmuksen heistä, kaksikymmenvuotiaista ja sitä vanhemmista, ja huomasi heitä olevan kolmesataa tuhatta sotakelpoista, keihästä ja kilpeä käyttävää valiomiestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Lisäksi hän palkkasi Israelista sadalla hopeatalentilla satatuhatta valiosotilasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Mutta Jumalan mies tuli hänen luokseen ja sanoi: \"Kuningas! Älköön Israelin sotajoukko lähtekö kanssasi, sillä Herra ei ole Israelin, kaikkien näiden efraimilaisten, kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Vaan lähde sinä yksin, käy rohkeasti taisteluun, muuten Jumala kaataa sinut vihollistesi eteen, sillä Jumalalla on valta auttaa ja kaataa.\" Amasja sanoi Jumalan miehelle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, '\"Mutta mitä on tehtävä niille sadalle talentille, jotka olen antanut Israelin joukolle?\" Jumalan mies vastasi: \" Herra voi antaa sinulle paljon enemmän, kuin se on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Amasja erotti sen joukon, joka oli tullut hänen luokseen Efraimista, palaamaan kotiinsa. Siitä he vihastuivat kovin Juudaan ja menivät kotiinsa vihasta hehkuen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Amasja rohkaisi mielensä, lähti ja vei väkensä Suolalaaksoon ja surmasi seiriläisiä kymmenen tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Toiset kymmenen tuhatta Juudan miehet ottivat elävinä vangeiksi. Nämä he veivät kallion laelle ja syöksivät heidät kallion laelta alas, niin että he kaikki ruhjoutuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Ne, jotka kuuluivat Amasjan palauttamaan joukkoon ja jotka eivät olleet päässeet hänen kanssaan sotaan, hyökkäsivät Juudan kaupunkeihin, Samariaan ja aina Beet-Hooroniin saakka. He surmasivat asukkaista kolmetuhatta ja ottivat paljon saalista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Kun Amasja voitettuaan edomilaiset tuli takaisin, hän toi mukanaan seiriläisten jumalat ja asetti ne itselleen jumaliksi, ja hän kumarsi niitä ja poltti niille uhreja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Herran viha syttyi Amasjaa kohtaan, ja hän lähetti hänen luokseen profeetan. Tämä sanoi hänelle: \"Miksi etsit tuon kansan jumalia, jotka eivät voineet pelastaa omaa kansaansa käsistäsi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Hänen näin hänelle puhuessaan Amasja sanoi hänelle: \"Olemmeko asettaneet sinut kuninkaan neuvonantajaksi? Lopeta jo, muutoin sinut surmataan.\" Profeetta lopetti ja sanoi: \"Minä tiedän, että Jumala on päättänyt tuhota sinut, koska teet näin etkä kuule neuvoani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Amasja, Juudan kuningas, lähetti neuvoteltuaan asiasta Jooaalle, Jooahaan pojalle, Jeehun pojanpojalle, Israelin kuninkaalle, tämän sanan: \"Tule, otelkaamme keskenämme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Mutta Jooas, Israelin kuningas, lähetti Amasjalle, Juudan kuninkaalle tämän sanan: \"Libanonilla kasvava ohdake lähetti setripuulle, joka kasvoi Libanonilla, tämän sanan: \'Anna tyttäresi vaimoksi pojalleni.\' Mutta metsän eläimet Libanonilla kulkivat ohdakkeen yli ja tallasivat sen maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Sinä sanot: \'Katso, olen voittanut Edomin\', ja olet käynyt ylpeäksi saatuasi kunniaa. Mutta pysy kotonasi. Minkä tähden tahdot tuottaa onnettomuuden: sinä kukistut ja Juuda kanssasi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Mutta Amasja ei totellut, sillä tämä tuli Jumalalta. Hän tahtoi antaa heidät alttiiksi, koska he olivat etsineet Edomin jumalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Jooas, Israelin kuningas, lähti liikkeelle, ja he ottelivat keskenään, hän ja Amasja, Juudan kuningas, Beet-Semeksessä, joka on Juudan aluetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Niin israelilaiset voittivat Juudan miehet, ja nämä pakenivat kukin teltalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Jooas, Israelin kuningas, otti Juudan kuninkaan Amasjan, Jooaan pojan, Jooahaan pojanpojan, Beet-Semeksessä vangiksi ja toi hänet Jerusalemiin. Hän revitti Jerusalemin muuria Efraimin portista Kulmaporttiin saakka neljäsataa kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Hän otti kaiken kullan ja hopean sekä esineistön, mitä Jumalan temppelissä, Oobed-Edomin huostassa oli, ja kuninkaan linnan aarteet sekä panttivankeja ja palasi Samariaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Mutta Amasja, Jooaan poika, Juudan kuningas, eli Jooaan, Jooahaan pojan, Israelin kuninkaan, kuoleman jälkeen viisitoista vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Mitä muuta on kerrottavaa Amasjan aikaisemmista ja myöhemmistä vaiheista, se on kirjoitettuna Juudan ja Israelin kuningasten kirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Siitä ajasta alkaen, jolloin Amasja luopui Herrasta, punottiin Jerusalemissa salaliittoa häntä vastaan. Hän pakeni Laakiiseen, mutta Laakiiseen lähetettiin miehiä hänen jälkeensä, ja he surmasivat hänet siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Hänet nostettiin hevosten selkään ja haudattiin isiensä viereen Juudan kaupunkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Mutta koko Juudan kansa otti Ussian, joka oli kuudentoista vuoden vanha, ja teki hänet kuninkaaksi hänen isänsä Amasjan sijaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Hän linnoitti Eilatin ja palautti sen Juudalle sitten, kun kuningas oli mennyt lepoon isiensä luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Ussia oli kuudentoista vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa viisikymmentä kaksi vuotta. Hänen äitinsä oli nimeltään Jekolja Jerusalemista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Hän teki sitä, mikä on oikein Herran silmissä, aivan niin kuin hänen isänsä Amasja oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Hän etsi Jumalaa, niin kauan kuin Sakarja eli, joka ymmärsi Jumalan näkyjä. Niin kauan kuin hän etsi Herraa, Jumala antoi hänen menestyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Hän lähti sotimaan filistealaisia vastaan ja revitti Gatin, Jabnen ja Asdodin muurit ja rakennutti kaupunkeja Asdodin alueelle ja muualle filistealaisten maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Jumala auttoi häntä filistealaisia vastaan ja niitä arabialaisia vastaan, jotka asuivat Guur-Baalissa, sekä meunilaisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Ammonilaiset maksoivat veroa Ussialle, ja hänen maineensa levisi aina Egyptiin saakka, sillä hän tuli erittäin mahtavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Ussia rakennutti Jerusalemiin tornit Kulmaportin ja Laaksoportin päälle ja Kulmauksen päälle ja varusti ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Hän rakennutti torneja myös erämaahan ja hakkautti paljon vesisäiliöitä, sillä hänellä oli paljon karjaa sekä Alankomaassa että ylätasangolla. Peltomiehiä ja viinitarhureita hänellä oli vuoristossa ja puutarhamailla, sillä hän harjoitti maanviljelyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Ussialla oli sotajoukko, joka teki sotapalvelusta ja lähti sotaan osastoittain sen lukumäärän mukaan, mikä heitä oli katselmuksessa, jonka kirjuri Jegiel ja päällysmies Maaseja olivat toimittaneet Hananjan, kuninkaallisen päällikön, johdolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Perhekuntapäämiesten, sotasankareitten, koko lukumäärä oli kaksituhatta kuusisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Heidän johdossaan oli kolmensadan seitsemän tuhannen viidensadan miehen suuruinen sotajoukko, joka teki väellä ja voimalla sotapalvelusta auttaakseen kuningasta vihollista vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Ussia varusti heidät, koko sotajoukon, kilvillä, keihäillä, kypärillä, rintahaarniskoilla, jousilla ja linkokivillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Hän teetti Jerusalemiin taidokkaasti sommiteltuja sotakoneita, jotka asetettiin torneihin ja muurien kulmiin ja joilla ammuttiin nuolia ja suuria kiviä. Niin hänen maineensa levisi kauas, sillä hän sai ihmeteltävästi apua, kunnes hän tuli mahtavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Mutta kun hän oli tullut mahtavaksi, ylpistyi hänen sydämensä, niin että hän teki kelvottoman teon, hän tuli uskottomaksi Herraa, Jumalaansa, kohtaan ja meni Herran temppeliin, suitsutusalttarille, suitsuttamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Pappi Asarja meni hänen jälkeensä sinne, mukanaan kahdeksankymmentä Herran pappia, rohkeita miehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'Nämä astuivat kuningas Ussiaa vastaan ja sanoivat hänelle: \"Ei ole sinun asiasi, Ussia, suitsuttaa Herralle, vaan pappien, Aaronin poikien, jotka ovat pyhitetyt suitsuttamaan. Mene ulos pyhäköstä, sillä sinä olet ollut uskoton, eikä siitä tule sinulle kunniaa Herralta Jumalalta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Ussia vihastui, ja hän piti juuri suitsutusastiaa kädessään suitsuttaakseen. Mutta kun hän vihastui pappeihin, puhkesi hänen otsaansa spitaali pappien läsnä ollessa Herran temppelissä suitsutusalttarin ääressä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Kun ylipappi Asarja ja kaikki muut papit kääntyivät hänen puoleensa, katso, hänellä oli spitaali otsassa. Silloin he karkottivat äkkiä hänet sieltä, ja itsekin hän lähti pois kiireen vilkkaa, kun Herra oli häntä lyönyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Kuningas Ussia tuli spitaaliseksi kuolinpäiväänsä saakka ja asui spitaalisena eri talossa, sillä hänet oli eristetty Herran temppelistä. Hänen poikansa Jootam hallitsi kuninkaan linnaa ja jakoi oikeutta maan kansalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Mitä muuta on kerrottavaa Ussiasta, hänen aikaisemmista ja myöhemmistä vaiheistaan, sen on profeetta Jesaja, Aamosin poika, pannut kirjaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Ussia meni lepoon isiensä luo, ja hänet haudattiin isiensä viereen vainiolle syrjään kuningasten haudoista. Sanottiin näet: \"Hän on spitaalinen.\" Hänen poikansa Jootam tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Jootam oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kuusitoista vuotta. Hänen äitinsä nimi oli Jerusa, Saadokin tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Hän teki sitä, mikä on oikein Herran silmissä, kuten hänen isänsä Ussia oli tehnyt, paitsi ettei hän tunkeutunut Herran temppeliin. Mutta kansa vaelsi yhä kelvottomasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Hän rakennutti Yläportin Herran temppeliin ja rakennutti paljon Oofelin muuria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Hän rakennutti myös kaupunkeja Juudan vuoristoon, ja metsiin hän rakennutti linnoja ja torneja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Hän kävi sotaa ammonilaisten kuningasta vastaan ja voitti heidät. Ammonilaiset antoivat hänelle sinä vuonna sata talenttia hopeaa, kymmenentuhatta koor-mittaa vehnää ja kymmenentuhatta koor-mittaa ohria. Tämän ammonilaiset suorittivat hänelle myös toisena ja kolmantena vuotena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Jootam tuli yhä mahtavammaksi, koska hän vaelsi vakaasti Herran, Jumalansa, edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Mitä muuta on kerrottavaa Jootamista ja kaikista hänen sodistaan ja hänen vaelluksestaan, katso, se on kirjoitettuna Israelin ja Juudan kuningasten kirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Hän oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kuusitoista vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Jootam meni lepoon isiensä luo, ja hänet haudattiin Daavidin kaupunkiin. Hänen poikansa Aahas tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Aahas oli kahdenkymmenen vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kuusitoista vuotta. Hän ei tehnyt sitä, mikä on oikein Herran silmissä, niin kuin hänen isänsä Daavid,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'vaan vaelsi Israelin kuningasten teitä. Hän jopa teki valettuja kuvia baaleille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Hän poltti uhreja Ben-Hinnomin laaksossa ja poltti poikansa tulessa, niiden kansojen kauhistavien tekojen mukaan, jotka Herra oli karkottanut israelilaisten tieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Hän teurasti ja poltti uhreja uhrikukkuloilla ja kummuilla ja jokaisen vihreän puun alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Sen tähden Herra, hänen Jumalansa, antoi hänet Aramin kuninkaan käsiin. He voittivat hänet ja ottivat hänen väestään suuren joukon vangiksi ja veivät Damaskoon. Hänet annettiin myös Israelin kuninkaan käsiin, ja tämä tuotti hänelle suuren tappion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Pekah, Remaljan poika, surmasi Juudasta satakaksikymmentä tuhatta yhtenä päivänä, kaikki sotakuntoisia miehiä, koska he olivat hylänneet Herran, isiensä Jumalan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Sikri, efraimilainen soturi, tappoi kuninkaan pojan Maasejan, linnan esimiehen Asrikamin ja kuninkaan lähimmän miehen, Elkanan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Israelilaiset veivät veljiltään vangeiksi vaimoja, poikia ja tyttäriä kaksisataa tuhatta, ryöstivät heiltä myös paljon saalista ja veivät saaliin Samariaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Siellä oli Herran profeetta nimeltä Ooded. Tämä meni sotajoukkoa vastaan, kun se oli tulossa Samariaan, ja sanoi heille: \"Katso, Herra, isienne Jumala, on vihastunut Juudaan ja antanut heidät käsiinne, ja olette tappaneet heitä raivossa, joka ulottuu taivaaseen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Mutta nyt te ajattelette pakottaa tämän Juudan väen ja Jerusalemin orjiksenne ja orjattariksenne. Eikö teillä jo ole tunnollanne kyllin rikoksia Herraa, Jumalaanne, vastaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Kuulkaa nyt minua ja palauttakaa vangit, jotka olette ottaneet veljienne joukosta, sillä Herran vihan hehku on päällänne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Muutamat efraimilaisten päämiehistä, Asarja, Joohananin poika, Berekia, Mesillemotin poika, Hiskia, Sallumin poika, ja Amasa, Hadlain poika, nousivat sotaretkeltä tulevia vastaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'ja sanoivat heille: \"Älkää tuoko tänne noita vankeja, sillä te saatatte meidät syyllisiksi Herran edessä, kun aiotte lisätä syntejämme ja syyllisyyttämme. Onhan syyllisyytemme jo suuri, ja vihan hehku on Israelin päällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Aseväki luopui vangeista ja saaliista päämiesten ja koko seurakunnan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Nimeltä mainitut miehet nousivat ja ottivat huostaansa vangit ja antoivat saaliista vaatteita kaikille niille heidän joukossaan, jotka olivat alasti. He antoivat näille vaatteita ja sandaaleja, ruokaa ja juomaa, voitelivat heitä ja toimittivat heille, kaikille uupuneille, aasit ja veivät heidät Jerikoon, Palmukaupunkiin, lähelle heidän veljiään. Sitten he palasivat Samariaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'Siihen aikaan kuningas Aahas lähetti sanansaattajat Assurin kuningasten luo saadakseen apua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Sillä vielä edomilaisetkin olivat tulleet ja voittaneet Juudan ja ottaneet vankeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Filistealaiset olivat tehneet ryöstöretken Alankomaan ja Juudan Negevin kaupunkeihin ja valloittaneet Beet-Semeksen, Aijalonin ja Gederotin, myös Sookon ja sen tytärkaupungit, Timran ja sen tytärkaupungit ja Gimson ja sen tytärkaupungit, ja he olivat asettuneet niihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Sillä Herra nöyryytti Juudaa Aahaan, Israelin kuninkaan, tähden, koska tämä oli harjoittanut kurittomuutta Juudassa ja ollut uskoton Herraa kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Tillegat-Pilneser, Assurin kuningas, lähti häntä vastaan ja ahdisti häntä eikä tukenut häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Sillä vaikka Aahas ryösti Herran temppeliä ja kuninkaan ja päämiesten linnoja ja antoi kaiken Assurin kuninkaalle, hänelle ei ollut siitä apua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Silloinkin kun häntä ahdistettiin, hän, kuningas Aahas, oli edelleen uskoton Herraa kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Sillä hän uhrasi Damaskon jumalille, jotka olivat voittaneet hänet. Hän ajatteli: \"Koska Aramin kuningasten jumalat ovat auttaneet heitä, uhraan minäkin niille, että ne minuakin auttaisivat.\" Mutta ne tulivatkin hänelle ja koko Israelille lankeemukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Aahas kokosi Jumalan temppelin kaluston ja hakkasi Jumalan temppelin kaluston kappaleiksi. Hän sulki Herran temppelin ovet ja teetti itselleen alttareita Jerusalemin joka kolkkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Jokaiseen Juudan kaupunkiin hän teetti uhrikukkuloita polttaakseen uhreja muille jumalille, ja niin hän vihoitti Herran, isiensä Jumalan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Mitä muuta on kerrottavaa hänestä ja kaikesta hänen vaelluksestaan, sekä aikaisemmasta että myöhemmästä, katso, se on kirjoitettuna Juudan ja Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Aahas meni lepoon isiensä luo, ja hänet haudattiin kaupunkiin, Jerusalemiin. Sillä häntä ei viety Israelin kuningasten hautoihin. Hänen poikansa Hiskia tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Hiskia tuli kuninkaaksi kahdenkymmenen viiden vuoden ikäisenä ja hallitsi Jerusalemissa kaksikymmentä yhdeksän vuotta. Hänen äitinsä oli nimeltään Abia, Sakarjan tytär.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Hän teki sitä, mikä on oikein Herran silmissä, aivan niin kuin hänen isänsä Daavid oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Ensimmäisenä hallitusvuotenaan sen ensimmäisessä kuussa hän avasi Herran temppelin ovet ja korjasi ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Sitten hän toi papit ja leeviläiset ja kokosi heidät itään olevalle aukiolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'Hän sanoi heille: \"Kuulkaa minua, te leeviläiset! Pyhittäytykää nyt ja pyhittäkää Herran, isienne Jumalan, temppeli ja toimittakaa saastaisuus pois pyhäköstä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Sillä isämme ovat olleet uskottomia ja tehneet sitä, mikä on pahaa Herran, Jumalamme, silmissä, ja hylänneet hänet. He käänsivät kasvonsa pois Herran asumuksesta ja käänsivät selkänsä sille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'He sulkivat myös eteisen ovet, sammuttivat lamput, eivät polttaneet suitsuketta eivätkä uhranneet polttouhreja pyhäkössä Israelin Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Sen tähden Herran viha on kohdannut Juudaa ja Jerusalemia, ja hän on tehnyt heidät kauhuksi, hämmästykseksi ja pilkaksi, niin kuin te omin silmin näette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Katso, isämme ovat kaatuneet miekkaan, ja poikamme, tyttäremme ja vaimomme ovat joutuneet vankeuteen tästä syystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Nyt aion tehdä liiton Herran, Israelin Jumalan, kanssa, että hänen vihansa hehku kääntyisi meistä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Älkää siis, lapseni, olko leväperäisiä, sillä teidät Herra on valinnut seisomaan hänen edessään ja palvelemaan häntä, olemaan hänen palvelijansa ja suitsuttamaan hänelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Silloin nousivat leeviläiset: Mahat, Amasain poika, ja Jooel, Asarjan poika, Kehatin jälkeläisistä; Merarin jälkeläisistä Kiis, Abdin poika, ja Asarja, Jehallelelin poika; geersonilaisista Jooah, Simman poika, ja Eeden, Jooahin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'Elisafanin jälkeläisistä Simri ja Jegiel; Aasafin jälkeläisistä Sakarja ja Mattanja;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'Heemanin jälkeläisistä Jehiel ja Siimei; ja Jedutunin jälkeläisistä Semaja ja Ussiel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Nämä kokosivat veljensä, pyhittäytyivät ja menivät, kuten kuningas oli Herran sanan mukaan käskenyt, puhdistamaan Herran temppeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Papit menivät sisälle Herran temppeliin puhdistamaan sitä, ja kaiken saastaisuuden, minkä löysivät Herran temppelistä, he veivät Herran temppelin esipihalle. Sieltä leeviläiset ottivat sen ja veivät sen ulos Kidronin laaksoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'He alkoivat pyhittämisen ensimmäisen kuun ensimmäisenä päivänä, ja kuukauden kahdeksantena päivänä he olivat ehtineet Herran eteiseen, ja he pyhittivät Herran temppeliä kahdeksan päivää. Ensimmäisen kuun kuudentenatoista päivänä he lopettivat työnsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'He menivät sisälle kuningas Hiskian luo ja sanoivat: \"Olemme puhdistaneet koko Herran temppelin, polttouhrialttarin ja koko sen kaluston ja näkyleipäpöydän ja koko sen kaluston.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Koko kaluston, jonka kuningas Aahas hallitusaikanaan uskottomuudessaan saastutti, olemme panneet kuntoon ja pyhittäneet, ja katso, ne ovat Herran alttarin edessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Kuningas Hiskia kokosi varhain aamulla kaupungin päämiehet ja meni Herran temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'He toivat seitsemän härkää, seitsemän pässiä ja seitsemän karitsaa sekä seitsemän vuohipukkia syntiuhriksi valtakunnan puolesta, pyhäkön puolesta ja Juudan puolesta. Hän käski pappi Aaronin poikien, pappien, uhrata ne Herran alttarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'He teurastivat naudat, ja papit ottivat veren ja vihmoivat sen alttarille. He teurastivat myös pässit ja vihmoivat veren alttarille. He teurastivat karitsat ja vihmoivat veren alttarille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Sen jälkeen he toivat syntiuhripukit kuninkaan ja seurakunnan eteen, ja nämä laskivat kätensä niiden päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Papit teurastivat ne ja uhrasivat niiden veren syntiuhrina alttarilla toimittaen koko Israelille sovituksen. Sillä kuningas oli käskenyt uhrata polttouhrin ja syntiuhrin koko Israelin puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Hän asetti leeviläiset Herran temppeliin, symbaalit, harput ja lyyrat käsissä, niin kuin Daavid ja kuninkaan näkijä Gaad ja profeetta Naatan olivat käskeneet. Käsky oli nimittäin Herran antama hänen profeettojensa kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Niin leeviläiset seisoivat siinä Daavidin soittimet käsissä, ja papit torvet käsissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Hiskia käski uhrata alttarilla polttouhrin. Kun uhraaminen alkoi, alkoi myös Herran veisuu ja torvien soitto Daavidin, Israelin kuninkaan, soittimien johtaessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Koko seurakunta kumartaen rukoili, veisuu kaikui, ja torvet soivat – kaikkea tätä kesti, kunnes polttouhri oli uhrattu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Kun uhraaminen oli päättynyt, kuningas ja kaikki, jotka olivat hänen kanssaan saapuvilla, polvistuivat kumartaen rukoilemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Kuningas Hiskia ja päämiehet käskivät leeviläisten ylistää Herraa Daavidin ja näkijä Aasafin sanoilla. Nämä ylistivät häntä iloiten, polvistuivat ja kumartaen rukoilivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Sitten Hiskia lausui ja sanoi: \"Nyt te olette tuoneet täysin käsin lahjoja Herralle. Astukaa esiin ja tuokaa teurasuhreja ja kiitosuhreja Herran temppeliin.\" Silloin seurakunta toi teurasuhreja ja kiitosuhreja, ja jokainen, jonka sydän häntä siihen vaati, myös polttouhreja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Seurakunnan tuomien polttouhrien lukumäärä oli seitsemänkymmentä nautaa, sata pässiä ja kaksisataa karitsaa, nämä kaikki polttouhriksi Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Pyhiä lahjoja oli kuusisataa nautaa ja kolmetuhatta lammasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Mutta pappeja oli niin vähän, etteivät he voineet nylkeä kaikkia polttouhriteuraita. Sen tähden heidän veljensä leeviläiset auttoivat heitä, kunnes tämä työ oli suoritettu ja kunnes papit olivat pyhittäytyneet, sillä leeviläiset pyrkivät vilpittömämmin kuin papit pyhittäytymään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Myös polttouhreja oli paljon sekä rauhanuhrirasvoja ja polttouhriin kuuluvia juomauhreja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Näin järjestettiin palvelus Herran temppelissä. Hiskia ja kaikki kansa iloitsivat siitä, mitä Jumala oli kansalle valmistanut, sillä se oli tapahtunut nopeasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Hiskia lähetti sanansaattajat koko Israeliin ja Juudaan ja kirjoitti myös kirjeet Efraimiin ja Manasseen, että he tulisivat Herran temppeliin Jerusalemiin viettämään pääsiäistä Herran, Israelin Jumalan, kunniaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Kuningas, hänen päämiehensä ja koko Jerusalemin seurakunta päättivät viettää pääsiäistä toisessa kuussa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'sillä he eivät voineet viettää sitä silloin heti, koska pappeja ei ollut pyhittäytynyt riittävää määrää eikä kansa ollut kokoontunut Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Tämä kelpasi kuninkaalle ja koko seurakunnalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'ja niin he päättivät kuuluttaa koko Israelissa Beersebasta Daaniin saakka, että oli tultava Jerusalemiin viettämään pääsiäistä Herran, Israelin Jumalan, kunniaksi. Sillä sitä ei ollut vietetty joukolla, niin kuin kirjoitettu oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Juoksijat kulkivat, mukanaan kuninkaan ja hänen päämiestensä kirjeet, halki koko Israelin ja Juudan ja julistivat kuninkaan käskystä: \"Te israelilaiset, palatkaa Herran, Aabrahamin, Iisakin ja Israelin Jumalan, luo, että hän palaisi niiden luo, jotka teistä ovat säilyneet ja pelastuneet Assurin kuninkaiden käsistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Älkää olko niin kuin isänne ja veljenne, jotka olivat uskottomat Herralle, isiensä Jumalalle, niin että hän antoi teidät häviön omiksi, niin kuin te näette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Älkää siis olko niskureita niin kuin teidän isänne. Ojentakaa kätenne Herralle ja tulkaa hänen pyhäkköönsä, jonka hän on pyhittänyt ikiajoiksi, ja palvelkaa Herraa, Jumalaanne, että hänen vihansa hehku kääntyisi teistä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Sillä jos te palaatte Herran luo, veljenne ja poikanne saavat osakseen laupeuden voittajiltaan ja voivat palata takaisin tähän maahan. Sillä Herra, teidän Jumalanne, on armollinen ja laupias, eikä hän käännä kasvojaan pois teistä, jos palaatte hänen luokseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Juoksijat kulkivat kaupungista kaupunkiin Efraimin ja Manassen maassa ja aina Sebuloniin saakka. Mutta heille naurettiin ja heitä pilkattiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Kuitenkin Asserista, Manassesta ja Sebulonista muutamat nöyrtyivät ja tulivat Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Myös Juudassa vaikutti Jumalan käsi, ja hän antoi heille yksimielisen sydämen tekemään, mitä kuningas ja päämiehet olivat Herran sanan mukaan käskeneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Niin kokoontui paljon kansaa Jerusalemiin viettämään happamattoman leivän juhlaa toisessa kuussa. Se oli hyvin suuri kokous.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'He nousivat ja poistivat alttarit Jerusalemista. Myös kaikki suitsutusalttarit he poistivat ja heittivät Kidronin laaksoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'He teurastivat pääsiäislampaan toisen kuun neljäntenätoista päivänä. Papit ja leeviläiset häpesivät ja pyhittäytyivät ja toivat polttouhreja Herran temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'He asettuivat paikoilleen, niin kuin heidän velvollisuutensa oli Jumalan miehen Mooseksen lain mukaan. Papit vihmoivat veren, otettuaan sen leeviläisten käsistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Sillä seurakunnassa oli monta, jotka eivät olleet pyhittäytyneet. Niin leeviläiset huolehtivat pääsiäislammasten teurastamisesta kaikille, jotka eivät olleet puhtaita, ja niiden pyhittämisestä Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Sillä suurin osa kansasta, monet Efraimista ja Manassesta, Isaskarista ja Sebulonista, eivät olleet puhdistautuneet, vaan söivät pääsiäislampaan toisin, kuin oli kirjoitettu. Hiskia oli näet rukoillut heidän puolestaan sanoen: \" Herra, joka on hyvä, antakoon anteeksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'jokaiselle, joka on kiinnittänyt sydämensä Jumalan, Herran, isiensä Jumalan, etsimiseen, vaikka onkin vailla pyhäkköpuhtautta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Herra kuuli Hiskiaa ja säästi kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Israelilaiset, jotka olivat Jerusalemissa, viettivät seitsemän päivää happamattoman leivän juhlaa iloiten suuresti. Leeviläiset ja papit ylistivät joka päivä Herraa voimakkailla soittimilla, Herran kunniaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Hiskia puhutteli ystävällisesti kaikkia leeviläisiä, jotka taitavasti suorittivat tehtävänsä Herran kunniaksi. He söivät seitsemän päivää juhlauhreja ja uhrasivat rauhanuhreja ja ylistivät Herraa, isiensä Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Koko seurakunta päätti viettää juhlaa vielä toiset seitsemän päivää, ja niin vietettiin ilojuhlaa vielä seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Sillä Hiskia, Juudan kuningas, oli antanut seurakunnalle anniksi tuhat härkää ja seitsemän tuhatta lammasta, ja päämiehet olivat antaneet seurakunnalle anniksi tuhat härkää ja kymmenen tuhatta lammasta. Paljon pappeja pyhittäytyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Koko Juudan seurakunta iloitsi ja samoin papit ja leeviläiset ja koko Israelista tullut seurakunta, myös muukalaiset, jotka olivat tulleet Israelin maasta tai asuivat Juudassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Jerusalemissa oli ilo suuri, sillä Israelin kuninkaan Salomon, Daavidin pojan, ajoista asti ei sellaista ollut tapahtunut Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Leeviläiset papit nousivat ja siunasivat kansan. Heidän äänensä tuli kuulluksi, ja heidän rukouksensa tuli Herran pyhään asumukseen, taivaaseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Kun kaikki tämä oli päättynyt, kaikki saapuvilla olevat israelilaiset lähtivät Juudan kaupunkeihin ja murskasivat patsaat, hakkasivat maahan aserapaalut ja kukistivat uhrikukkulat ja alttarit perin pohjin koko Juudassa, Benjaminissa, Efraimissa ja Manassessa. Sitten kaikki israelilaiset palasivat kukin perintömaalleen, kaupunkeihinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Hiskia asetti pappien ja leeviläisten osastot, heidän osastojensa mukaan, kunkin hänen papillisen tai leeviläisen palvelustehtävänsä mukaan, polttouhreja ja rauhanuhreja toimitettaessa palvelemaan, kiittämään ja ylistämään Herran leirin porteissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Minkä kuningas antoi omaisuudestaan, se käytettiin polttouhreiksi, aamu- ja ehtoopolttouhreiksi sekä sapatteina, uudenkuun päivinä ja juhlina uhrattaviksi polttouhreiksi, niin kuin on kirjoitettuna Herran laissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Hän käski kansan, Jerusalemin asukkaiden, antaa papeille ja leeviläisille heidän osuutensa, että nämä pitäisivät kiinni Herran laista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Kun sana levisi, israelilaiset antoivat runsaan määrän ensisatoa jyvistä, viinistä, öljystä ja hunajasta ja kaikesta pellon sadosta. He toivat runsaat kymmenykset kaikesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Myös ne israelilaiset ja Juudan miehet, jotka asuivat Juudan kaupungeissa, toivat kymmenykset naudoista, lampaista ja vuohista sekä kymmenykset Herralle, Jumalalleen, pyhitetyistä pyhistä lahjoista, ja panivat ne eri kasoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Kolmannessa kuussa he alkoivat panna niitä kasoihin, ja seitsemännessä kuussa he sen lopettivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Kun Hiskia ja päämiehet tulivat ja näkivät kasat, he kiittivät Herraa ja hänen kansaansa Israelia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Kun Hiskia kysyi papeilta ja leeviläisiltä näistä kasoista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'vastasi hänelle ylipappi Asarja, joka oli Saadokin sukua, ja sanoi: \"Siitä alkaen, kun ruvettiin tuomaan antia Herran temppeliin, olemme syöneet ja tulleet ravituiksi, ja kuitenkin on jäänyt paljon tähteeksi. Herra on nimittäin siunannut kansaansa, ja tämä paljous on jäänyt tähteeksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Hiskia käski laittaa kammioita Herran temppeliin. Kun ne oli laitettu,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'tuotiin niihin tunnollisesti anti, kymmenys ja pyhät lahjat. Niiden esimiehenä oli leeviläinen Koonanja, ja hänen veljensä Siimei oli häntä lähinnä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Jehiel, Asasja, Nahat, Asael, Jerimot, Joosabat, Eliel, Jismakja, Mahat ja Benaja olivat Koonanjan ja hänen veljensä Siimein käskyläisinä kuningas Hiskian ja Asarjan, Jumalan temppelin esimiehen, määräyksestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Leeviläinen Koore, Jimnan poika, joka oli ovenvartijana idän puolella, hoiti Jumalalle annetut vapaaehtoiset lahjat ja Herralle tulevan annin ja korkeasti pyhien lahjojen suorituksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Hänen johdossaan olivat Eedem, Minjamin, Jeesua, Semaja, Amarja ja Sekanja, joiden oli pappiskaupungeissa tunnollisesti suoritettava osuudet veljilleen, niin pienille kuin suurille, osastoittain,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'paitsi sukuluetteloihin merkityille miespuolisille, kolmivuotiaille ja sitä vanhemmille, kaikille, jotka menivät Herran temppeliin tekemään palvelusta, kunakin päivänä sen päivän palveluksen, hoitamaan tehtäviään, osastoittain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Papit merkittiin sukuluetteloihin perhekunnittain ja leeviläisistä kaksikymmenvuotiaat ja sitä vanhemmat, palvelustehtäviensä mukaan, osastoittain,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'nimittäin niin, että sukuluetteloihin merkittiin kaikki heidän pienet lapsensa, vaimonsa, poikansa ja tyttärensä, koko heidän joukkonsa, sillä he hoitivat tunnollisesti sitä, mikä oli pyhää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Aaronin pojilla, papeilla, jotka asuivat kaupunkiensa laidunmailla, oli joka kaupungissa nimeltä mainitut miehet, joiden oli suoritettava osuudet kaikille miespuolisille pappien joukossa ja kaikille sukuluetteloihin merkityille leeviläisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Näin Hiskia teki koko Juudassa. Hän teki sitä, mikä oli hyvää, oikeaa ja totta Herran, hänen Jumalansa, edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Kaiken, mihin hän ryhtyi etsiessään Jumalaansa, koskipa se palvelusta Jumalan temppelissä tai lakia ja käskyjä, hän teki kaikesta sydämestään ja menestyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Näiden tapausten ja Hiskian vakaan vaelluksen jälkeen tuli Sanherib, Assurin kuningas, ja hyökkäsi Juudaan, piiritti sen varustettuja kaupunkeja ja aikoi valloittaa ne itselleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Kun Hiskia näki Sanheribin tulevan ja olevan aikeessa sotia Jerusalemia vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'hän neuvotteli päämiestensä ja soturiensa kanssa tukkiakseen vesilähteet, jotka olivat kaupungin ulkopuolella, ja he kannattivat häntä siinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Kokoontui paljon kansaa, ja he tukkivat kaikki lähteet ja puron, joka juoksee sen seudun läpi, sillä he sanoivat: \"Miksi Assurin kuninkaat tultuaan löytäisivät runsaasti vettä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Hän rohkaisi mielensä, rakensi koko revityn osan muuria ja korotti torneja ja teki sen ulkopuolelle toisen muurin, varusti Millon Daavidin kaupungissa ja teetti paljon heittoaseita ja kilpiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Hän asetti sotapäälliköitä kansalle ja kokosi heidät luokseen aukealle kaupungin portin eteen ja puhui ystävällisesti heille ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, '\"Olkaa lujat ja rohkeat, älkää pelätkö älkääkä arkailko Assurin kuningasta ja kaikkea joukkoa, joka on hänen kanssaan, sillä se, joka on kanssamme, on suurempi kuin se, joka on hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Hänen kanssaan on lihan käsivarsi, mutta meidän kanssamme on Herra, Jumalamme, meitä auttamassa ja sotiamme sotimassa.\" Kansa luotti Hiskian, Juudan kuninkaan, sanoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Tämän jälkeen Sanherib, Assurin kuningas, ollessaan itse koko sotavoimansa kanssa Laakiin edustalla, lähetti palvelijoitaan Jerusalemiin Hiskian, Juudan kuninkaan, luo ja kaikkien Jerusalemissa olevien Juudan miesten luo ja käski sanoa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, '\"Näin sanoo Sanherib, Assurin kuningas: Mihin te luotatte, kun jäätte Jerusalemiin saarroksiin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Eikö Hiskia viettele teitä ja saata teitä kuolemaan nälkään ja janoon, kun hän sanoo: Herra, meidän Jumalamme, pelastaa meidät Assurin kuninkaan käsistä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Eikö tämä sama Hiskia ole poistanut hänen uhrikukkuloitaan ja alttareitaan ja sanonut Juudalle ja Jerusalemille näin: \'Yhden ainoan alttarin edessä teidän on kumartaen rukoiltava ja sillä poltettava uhreja\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Ettekö tiedä, mitä minä ja isäni olemme tehneet muiden maiden kaikille kansoille? Ovatko näiden maiden kansojen jumalat voineet pelastaa maatansa käsistäni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Onko kukaan isieni tuhoamien kansojen kaikista jumalista voinut pelastaa kansaansa käsistäni? Kuinka sitten Jumalanne voisi pelastaa teidät minun käsistäni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Älkää siis antako Hiskian näin pettää ja vietellä itseänne älkääkä uskoko häntä, sillä ei minkään kansan eikä minkään valtakunnan jumala ole voinut pelastaa kansaansa käsistäni tai isieni käsistä, saati sitten teidän Jumalanne: ei hän pelasta teitä minun käsistäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Hänen palvelijansa puhuivat vielä enemmän Herraa Jumalaa ja hänen palvelijaansa Hiskiaa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Hän kirjoitti myös kirjeen herjatakseen Herraa, Israelin Jumalaa, ja puhuakseen häntä vastaan. Siinä sanottiin näin: \"Niin kuin muiden maiden kansojen jumalat eivät ole pelastaneet kansojansa minun käsistäni, niin ei Hiskiankaan Jumala ole pelastava kansaansa minun käsistäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Jerusalemin kansalle, jota oli muurilla, he huusivat kovalla äänellä juudan kielellä nostaakseen heissä pelon ja kauhun, että saisivat kaupungin valloitetuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'He puhuivat Jerusalemin Jumalasta kuin muiden maiden kansojen jumalista, jotka ovat ihmiskätten tekoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Mutta kuningas Hiskia ja profeetta Jesaja, Aamosin poika, rukoilivat tämän tähden ja huusivat taivaan puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Herra lähetti enkelin, joka tuhosi kaikki soturit, ruhtinaat ja päälliköt Assurin kuninkaan leirissä, niin että hän häpeä kasvoillaan palasi takaisin maahansa. Kun hän kerran meni jumalansa temppeliin, kaatoivat hänet siellä miekalla ne, jotka olivat lähteneet hänen omasta ruumiistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Näin Herra vapahti Hiskian ja Jerusalemin asukkaat Sanheribin, Assurin kuninkaan, käsistä ja kaikkien käsistä, ja hän johdatti heitä joka taholla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Monet toivat Herralle lahjoja Jerusalemiin ja Hiskialle, Juudan kuninkaalle, kalleuksia, ja hän kohosi sen jälkeen kaikkien kansojen silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'Niihin aikoihin Hiskia sairastui ja oli kuolemaisillaan. Niin hän rukoili Herraa, ja hän vastasi hänelle ja antoi tapahtua hänelle ihmeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Mutta Hiskia ei palkinnut hyvää hyvällä, vaan hänen sydämensä ylpistyi. Sen vuoksi hänen ja Juudan ja Jerusalemin osaksi tuli viha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Mutta kun Hiskia nöyrtyi sydämensä ylpeydestä, hän ja Jerusalemin asukkaat, Herran viha ei kohdannut heitä Hiskian päivinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Hiskialle tuli hyvin paljon rikkautta ja kunniaa. Hän hankki itselleen aarrekammioita hopeaa, kultaa, kalliita kiviä, hajuaineita, kilpiä ja kaikkia kallisarvoisia esineitä varten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'varastohuoneita jyvä-, viini- ja öljysatoa varten ja talleja kaikille juhdille ja karjalaumoja tarhoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Hän rakennutti itselleen myös kaupunkeja ja hankki suuret laumat lampaita ja vuohia ja nautakarjaa, sillä Jumala oli antanut hänelle hyvin suuren omaisuuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Hiskia myös tukki Giihonin veden yläjuoksun ja johti veden alas, länteen päin, Daavidin kaupunkiin. Hiskia menestyi kaikessa, mitä hän teki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Niinpä Jumala ainoastaan koetellakseen häntä ja tullakseen tuntemaan kaiken, mitä hänen sydämessään oli, jätti hänet Baabelin ruhtinasten lähettiläiden valtaan, jotka olivat lähetetyt hänen luokseen tiedustelemaan ihmettä, joka oli tapahtunut maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Mitä muuta on kerrottavaa Hiskiasta ja hänen hurskaista teoistaan, katso, se on kirjoitettuna profeetta Jesajan, Aamosin pojan, näyssä, Juudan ja Israelin kuningasten kirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Hiskia meni lepoon isiensä luo, ja hänet haudattiin siihen, mistä noustaan Daavidin jälkeläisten haudoille. Koko Juuda ja Jerusalemin asukkaat osoittivat hänelle kunniaa, kun hän kuoli. Hänen poikansa Manasse tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manasse oli kahdentoista vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa viisikymmentä viisi vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Hän teki sitä, mikä on pahaa Herran silmissä, niiden kansojen kauhistavien tekojen mukaan, jotka Herra oli karkottanut israelilaisten tieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Hän rakensi jälleen uhrikukkulat, jotka hänen isänsä Hiskia oli kukistanut, pystytti alttareita baaleille, teki aseroja ja kumarsi ja palveli kaikkea taivaan joukkoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Hän rakensi alttareita myös Herran temppeliin, josta Herra oli sanonut: \"Jerusalemissa on minun nimeni oleva ikuisesti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Hän rakensi alttareita kaikelle taivaan joukolle Herran temppelin molempiin esipihoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Hän myös pani poikansa kulkemaan tulen läpi Ben-Hinnomin laaksossa, ennusteli merkeistä, harjoitti noituutta ja velhoutta ja hankki itselleen vainaja- ja tietäjähenkien manaajia. Hän teki paljon sitä, mikä on pahaa Herran silmissä, ja vihoitti hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Teettämänsä veistetyn kuvapatsaan hän asetti Jumalan temppeliin, josta Jumala oli sanonut Daavidille ja hänen pojalleen Salomolle: \"Tähän temppeliin ja Jerusalemiin, jonka olen valinnut kaikista Israelin sukukunnista, asetan nimeni ikiajoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Enkä enää kuljeta Israelin jalkoja pois siitä maasta, jonka olen määrännyt isillenne, jos Israel vain tarkasti noudattaa kaikkea, mitä olen käskenyt heidän noudattaa, koko lakia ja käskyjä ja oikeuksia, jotka ovat Mooseksen kautta annetut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Mutta Manasse eksytti Juudan ja Jerusalemin asukkaat tekemään enemmän pahaa, kuin olivat tehneet ne kansat, jotka Herra oli hävittänyt israelilaisten tieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Herra puhui Manasselle ja hänen kansalleen, mutta he eivät kuunnelleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Herra toi Assurin kuninkaan sotapäälliköt heidän kimppuunsa. He ottivat Manassen kiinni koukuilla, kytkivät hänet vaskikahleisiin ja veivät hänet Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Mutta ahdingossa ollessaan hän etsi Herran, Jumalansa, mielisuosiota ja nöyrtyi syvästi isiensä Jumalan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'Kun hän näin rukoili ja itki hänen edessään, Jumala kuuli hänen rukouksensa ja toi hänet takaisin Jerusalemiin, hänen valtakuntaansa. Silloin Manasse tuli tietämään, että Herra on Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Sen jälkeen hän rakennutti Daavidin kaupungin ulomman muurin, länteen päin Giihonista, laaksoon, aina Kalaporttiin saakka, niin että se ympäröi Oofelin, ja hän teki siitä hyvin korkean. Hän asetti sotapäälliköitä kaikkiin Juudan varustettuihin kaupunkeihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Hän poisti vieraat jumalat ja kuvapatsaan Herran temppelistä sekä kaikki alttarit, jotka hän oli rakennuttanut Herran temppelin vuorelle ja Jerusalemiin, ja heitätti ne kaupungin ulkopuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Hän kunnosti Herran alttarin ja uhrasi sillä rauhan- ja kiitosuhreja ja kehotti Juudaa palvelemaan Herraa, Israelin Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Mutta kansa uhrasi edelleen uhrikukkuloilla, kuitenkin ainoastaan Herralle, Jumalalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Mitä muuta on kerrottavaa Manassesta, ja kuinka hän rukoili Jumalaansa, ja näkijöiden puheista, jotka puhuivat hänelle Herran, Israelin Jumalan, nimessä, katso, se on Israelin kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Hänen rukouksestaan ja kuinka hän tuli kuulluksi, ja kaikista hänen synneistään ja uskottomuudestaan ja niistä paikoista, joihin hän rakennutti uhrikukkuloita ja pystytti aserapaaluja ja jumalankuvia, ennen kuin hän nöyrtyi, katso, niistä on kirjoitettu Hoosain aikakirjaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Manasse meni lepoon isiensä luo, ja hänet haudattiin linnaansa. Hänen poikansa Aamon tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Aamon oli kahdenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kaksi vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Hän teki sitä, mikä on pahaa Herran silmissä, niin kuin hänen isänsä Manasse oli tehnyt. Aamon uhrasi kaikille niille jumalankuville, jotka hänen isänsä Manasse oli teettänyt, ja palveli niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Mutta hän ei nöyrtynyt Herran edessä, niin kuin hänen isänsä Manasse oli nöyrtynyt, vaan hän, Aamon, sälytti päälleen suuren syntivelan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Hänen palvelijansa tekivät salaliiton häntä vastaan ja tappoivat hänet hänen linnassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Mutta maan kansa surmasi kaikki ne, jotka olivat tehneet salaliiton kuningas Aamonia vastaan. Maan kansa teki hänen poikansa Joosian kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Joosia oli kahdeksan vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kolmekymmentä yksi vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Hän teki sitä, mikä on oikein Herran silmissä, ja vaelsi isänsä Daavidin teitä, poikkeamatta oikealle tai vasemmalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Kahdeksantena hallitusvuotenaan ollessaan vielä nuorukainen hän alkoi etsiä isänsä Daavidin Jumalaa ja kahdentenatoista vuotena hän alkoi puhdistaa Juudaa ja Jerusalemia uhrikukkuloista ja aserapaaluista sekä veistetyistä ja valetuista jumalankuvista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Baalin alttarit kukistettiin hänen läsnä ollessaan, ja niiden yli kohoavat auringonpatsaat hän hakkasi maahan, ja aserapaalut sekä veistetyt ja valetut jumalankuvat hän murskasi ja rouhensi ja sirotteli niiden haudoille, jotka olivat niille uhranneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Pappien luut hän poltti heidän alttareillaan. Niin hän puhdisti Juudan ja Jerusalemin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Manassen, Efraimin ja Simeonin kaupungeissa aina Naftaliin asti kaikkialla hän heidän miekoillaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'kukisti alttarit, löi palasiksi ja rouhensi aserapaalut ja jumalankuvat, ja hakkasi maahan kaikki auringonpatsaat koko Israelin maasta. Sitten hän palasi Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Kahdeksantenatoista hallitusvuotenaan puhdistaessaan maata ja temppeliä hän lähetti Saafanin, Asaljan pojan, kaupungin päällikön Maasejan ja kirjaaja Jooahin, Jooahaan pojan, korjaamaan Herran, hänen Jumalansa, temppeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'He tulivat ylimmäisen papin Hilkian luo ja jättivät Jumalan temppeliin tuodut rahat, joita leeviläiset, ovenvartijat, olivat koonneet Manassesta, Efraimista ja koko muusta Israelista ja koko Juudasta, Benjaminista ja Jerusalemin asukkailta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'He antoivat ne työnteettäjille, jotka oli pantu valvomaan töitä Herran temppelissä, ja nämä maksoivat niillä työmiehet, jotka työskentelivät Herran temppelissä ja laittoivat ja korjasivat temppeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'Niistä annettiin myös puusepille ja rakentajille, että nämä ostaisivat hakattuja kiviä ja puutavaraa kiinnitysparruiksi ja kattohirsiksi niihin rakennuksiin, jotka Juudan kuninkaat olivat turmelleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Nämä miehet toimivat työssään luottamusmiehinä. Leeviläiset Jahat ja Obadja, Merarin jälkeläiset, ja Sakarja ja Mesullam, Kehatin jälkeläiset, oli pantu valvomaan ja johtamaan heitä, myös kaikki leeviläiset, jotka ymmärsivät soittimista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'He myös valvoivat taakankantajia ja johtivat kaikkia työmiehiä eri töissä. Leeviläisiä oli kirjureina, virkamiehinä ja ovenvartijoina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Kun he olivat viemässä ulos Herran temppeliin tuotuja rahoja, pappi Hilkia löysi Herran lain kirjan, joka oli annettu Mooseksen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Hilkia lausui ja sanoi kirjuri Saafanille: \"Minä löysin Herran temppelistä lain kirjan.\" Hilkia antoi kirjan Saafanille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Saafan vei kirjan kuninkaalle ja teki lisäksi kuninkaalle selon asiasta, sanoen: \"Kaikki, mitä annettiin palvelijoillesi tehtäväksi, he ovat tehneet:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'he ovat ottaneet esille rahat, jotka olivat Herran temppelissä, ja antaneet ne työnvalvojille ja työnteettäjille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Kirjuri Saafan kertoi kuninkaalle sanoen: \"Pappi Hilkia antoi minulle erään kirjan.\" Saafan luki sen kuuluvasti kuninkaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Kun kuningas kuuli lain sanat, hän repäisi vaatteensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Kuningas käski Hilkiaa, Ahikamia, Saafanin poikaa, Abdonia, Miikan poikaa, kirjuri Saafania ja Asajaa, kuninkaan palvelijaa, sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, '\"Menkää ja kysykää puolestani ja niiden puolesta, joita on jäljellä Israelista ja Juudasta, neuvoa Herralta tästä löydetystä kirjasta. Sillä suuri on Herran viha, joka on vuodatettu ylitsemme, sen tähden että isämme eivät ole noudattaneet Herran sanaa eivätkä tehneet mitään kaikesta siitä, mikä on kirjoitettuna tässä kirjassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Hilkia sekä ne muut, jotka kuningas määräsi, menivät naisprofeetta Huldan luo, joka oli vaatevarastonhoitajan Sallumin, Tokhatin pojan, Hasran pojanpojan, vaimo ja asui Jerusalemissa, toisessa kaupunginosassa. He puhuivat hänelle, niin kuin edellä mainittiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Hän sanoi heille: \"Näin sanoo Herra, Israelin Jumala: Sanokaa sille miehelle, joka lähetti teidät luokseni:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, '\'Näin sanoo Herra: Katso, minä annan onnettomuuden kohdata tätä paikkaa ja sen asukkaita, kaikkien kirousten, jotka on kirjoitettu siihen kirjaan, joka on luettu Juudan kuninkaalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'koska he ovat hylänneet minut ja polttaneet uhreja muille jumalille ja vihoittaneet minut kaikilla kättensä teoilla. Sillä vihani on vuodatettu tämän paikan yli eikä ole sammuva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Mutta Juudan kuninkaalle, joka on lähettänyt teidät kysymään neuvoa Herralta, sanokaa näin: Näin sanoo Herra, Israelin Jumala, niistä sanoista, jotka olet kuullut:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Koska sydämesi on pehmennyt ja sinä olet nöyrtynyt Jumalan edessä kuullessasi, mitä hän on puhunut tätä paikkaa ja sen asukkaita vastaan, koska sinä olet nöyrtynyt edessäni ja reväissyt vaatteesi ja itkenyt edessäni, minäkin olen kuullut sinua, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Katso, korjaan sinut isiesi luo, ja saat rauhassa siirtyä hautaasi, ja silmäsi pääsevät näkemästä kaikkea onnettomuutta, minkä minä tuotan tälle paikalle ja sen asukkaille.\'\" He toivat kuninkaalle tämän vastauksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Kuningas lähetti kokoamaan luokseen kaikki Juudan ja Jerusalemin vanhimmat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Kuningas meni Herran temppeliin, hän ja kaikki Juudan miehet ja Jerusalemin asukkaat, myös papit ja leeviläiset, kaikki kansa suurimmasta pienimpään asti, ja hän luki heidän kuultensa kaikki Herran temppelistä löydetyn liitonkirjan sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Kuningas asettui paikalleen ja teki Herran edessä liiton, että heidän tuli seurata Herraa, noudattaa hänen käskyjään, todistuksiaan ja säädöksiään kaikesta sydämestään ja kaikesta sielustaan ja täyttää liiton sanat, jotka ovat kirjoitetut siihen kirjaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Hän otti siihen liittoon kaikki, jotka olivat Jerusalemissa ja Benjaminissa. Jerusalemin asukkaat tekivät, niin kuin Jumalan, heidän isiensä Jumalan, liitto vaati.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Joosia poisti kaikki kauhistukset israelilaisten kaikista maakunnista ja vaati jokaista, joka Israelissa oli, palvelemaan Herraa, heidän Jumalaansa. Niin kauan kuin hän eli, he eivät luopuneet Herrasta, isiensä Jumalasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Joosia vietti Jerusalemissa pääsiäistä Herran kunniaksi. Pääsiäislammas teurastettiin ensimmäisen kuun neljäntenätoista päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Hän asetti papit heidän palvelustehtäviinsä ja rohkaisi heitä palvelemaan Herran temppelissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Hän sanoi leeviläisille, jotka opettivat kaikkea Israelia ja jotka olivat pyhitetyt Herralle: \"Pankaa pyhä arkki temppeliin, jonka Salomo, Daavidin poika, Israelin kuningas, on rakentanut. Teidän ei enää tarvitse kantaa sitä olallanne. Palvelkaa nyt Herraa, Jumalaanne, ja hänen kansaansa Israelia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Valmistautukaa perhekunnittain osastojenne mukaan Daavidin, Israelin kuninkaan, määräyksen ja hänen poikansa Salomon käskykirjan mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'ja asettukaa pyhäkköön veljienne, kansan, perhekuntaryhmien mukaan, niin että jokaista ryhmää kohden on yksi leeviläisten perhekuntaosasto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Teurastakaa pääsiäislammas ja pyhittäytykää ja valmistakaa se veljillenne tehdäksenne Herran sanan mukaan, joka on puhuttu Mooseksen kautta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Joosia antoi kansalle anniksi lampaita ja vuohia, karitsoja ja kilejä, kolmekymmentä tuhatta luvultaan, kaikki pääsiäisuhreiksi kaikille saapuvilla oleville, ja kolmetuhatta nautaa, kaikki nämä kuninkaan omaisuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Hänen päämiehensä antoivat vapaaehtoisesti annin kansalle, papeille ja leeviläisille. Hilkia, Sakarja ja Jehiel, Jumalan temppelin esimiehet, antoivat papeille pääsiäisuhreiksi kaksituhatta kuusisataa karitsaa, sekä myös kolmesataa nautaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Koonanja, Semaja ja hänen veljensä Netanel, sekä Hasabja, Jegiel ja Joosabad, leeviläisten päämiehet, antoivat antina leeviläisille pääsiäisuhreiksi viisituhatta karitsaa ja viisisataa nautaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Näin järjestettiin jumalanpalvelus. Papit asettuivat paikoilleen ja samoin leeviläiset osastoittain, kuten kuningas oli käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Teurastettiin pääsiäislammas, ja papit vihmoivat veren, jonka olivat ottaneet leeviläisten käsistä, ja leeviläiset nylkivät nahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Mutta he panivat syrjään polttouhrikappaleet, antaakseen ne rahvaalle perhekuntaryhmittäin uhrattaviksi Herralle, niin kuin on kirjoitettuna Mooseksen kirjassa, samoin he tekivät myös naudoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'He paistoivat tulella pääsiäislampaan säädetyllä tavalla, mutta pyhät lahjat he keittivät padoissa, ruukuissa ja vadeissa ja veivät ne kiirettä pitäen kansalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Sitten he valmistivat ne itselleen ja papeille, sillä papit, Aaronin pojat, olivat yöhön saakka uhraamassa polttouhria ja rasvoja, – sen tähden leeviläiset valmistivat [ne] itselleen ja papeille, Aaronin pojille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Veisaajat, Aasafin pojat, olivat paikoillaan, niin kuin Daavid, Aasaf, Heeman ja Jedutun, kuninkaan näkijä, olivat määränneet, niin myös ovenvartijat jokaisella portilla. Heidän ei ollut lupa lähteä palveluksestaan, vaan heidän leeviläiset veljensä valmistivat heille [aterian].');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Näin järjestettiin kaikki Herran palvelus sinä päivänä, pääsiäisen vietto ja polttouhrien uhraaminen Herran alttarilla, kuten kuningas Joosia oli käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Näin viettivät saapuvilla olevat israelilaiset sinä aikana pääsiäistä ja happamattoman leivän juhlaa seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Sellaista pääsiäistä ei ollut vietetty Israelissa profeetta Samuelin päivistä. Sillä ei kukaan Israelin kuninkaista ollut viettänyt sellaista pääsiäistä, kuin nyt viettivät Joosia, papit ja leeviläiset, koko Juuda ja saapuvilla olevat israelilaiset sekä Jerusalemin asukkaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Joosian kahdeksantenatoista hallitusvuotena vietettiin tämä pääsiäinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Kaiken tämän jälkeen, sitten kun Joosia oli pannut kuntoon temppelin, lähti Neko, Egyptin kuningas, sotimaan Karkemista vastaan, joka on Eufratin varrella, ja Joosia meni häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Neko lähetti sanansaattajat hänen luokseen ja käski sanoa: \"Mitä sinulla on tekemistä minun kanssani, Juudan kuningas? Enhän minä nyt tule sinua vastaan, vaan sitä sukua vastaan, joka on sodassa minun kanssani, ja Jumala on käskenyt minua kiiruhtamaan. Jätä rauhaan Jumala, joka on kanssani, ettei hän tuhoaisi sinua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Mutta Joosia ei väistänyt häntä, vaan pukeutui tuntemattomaksi taistellakseen häntä vastaan, eikä kuullut Nekon sanoja, jotka kuitenkin tulivat Jumalan suusta. Hän meni taistelemaan Megiddon tasangolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Mutta ampujat ampuivat kuningas Joosiaa. Kuningas sanoi palvelijoilleen: \"Viekää minut pois, sillä olen pahasti haavoittunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Hänen palvelijansa siirsivät hänet sotavaunuista ja panivat hänet hänen toisiin vaunuihinsa ja kuljettivat hänet Jerusalemiin. Hän kuoli, ja hänet haudattiin isiensä hautoihin. Koko Juuda ja Jerusalem surivat Joosiaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Jeremia sepitti itkuvirren Joosiasta. Kaikki laulajat ja laulajattaret ovat itkuvirsissään puhuneet Joosiasta aina tähän päivään asti, ja nämä ovat tulleet yleisiksi Israelissa. Katso, ne ovat kirjoitettuina Itkuvirsissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Mitä muuta on kerrottavaa Joosiasta ja hänen hurskaista teoistaan, joita hän teki sen mukaan, kuin on kirjoitettuna Herran laissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'hänen sekä aikaisemmista että myöhemmistä vaiheistaan, katso, se on kirjoitettuna Israelin ja Juudan kuningasten kirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Maan kansa otti Joosian pojan Jooahaan ja teki hänet kuninkaaksi Jerusalemiin hänen isänsä jälkeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Jooahas oli kahdenkymmenen kolmen vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa kolme kuukautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Mutta Egyptin kuningas pani hänet viralta Jerusalemissa ja otti maasta pakkoverona sata talenttia hopeaa ja yhden talentin kultaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Egyptin kuningas teki hänen veljensä Eljakimin Juudan ja Jerusalemin kuninkaaksi ja muutti hänen nimensä Joojakimiksi. Mutta hänen veljensä Jooahaan Neko otti ja vei Egyptiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Joojakim oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa yksitoista vuotta. Hän teki sitä, mikä oli pahaa Herran, hänen Jumalansa, silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Nebukadnessar, Baabelin kuningas, lähti häntä vastaan ja kytki hänet vaskikahleisiin viedäkseen hänet Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Nebukadnessar vei Herran temppelin kalustoa Baabeliin ja pani ne temppeliinsä Baabelissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Mitä muuta on kerrottavaa Joojakimista ja niistä kauhistuksista, joita hän teki, ja mitä hänessä havaittiin, katso, se on kirjoitettuna Israelin ja Juudan kuningasten kirjassa. Hänen poikansa Joojakin tuli kuninkaaksi hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Joojakin oli kahdeksantoista vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kolme kuukautta ja kymmenen päivää. Hän teki sitä, mikä on pahaa Herran silmissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Vuoden vaihteessa kuningas Nebukadnessar lähetti noutamaan hänet Baabeliin, hänet sekä Herran temppelin kallisarvoiset esineet. Hän teki hänen veljensä Sidkian Juudan ja Jerusalemin kuninkaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Sidkia oli kahdenkymmenen yhden vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa yksitoista vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Hän teki sitä, mikä oli pahaa Herran, hänen Jumalansa, silmissä. Hän ei nöyrtynyt profeetta Jeremian edessä, jonka sana tuli Herran suusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Myös hän kapinoi kuningas Nebukadnessaria vastaan, joka kuitenkin oli vannottanut hänet Jumalan kautta. Hän oli niskuri ja paadutti sydämensä, niin ettei hän kääntynyt Herran, Israelin Jumalan, puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Myös kaikki pappien päämiehet ja kansa harjoittivat paljon uskottomuutta jäljittelemällä kaikkia pakanoiden kauhistuksia ja saastuttivat Herran temppelin, jonka hän oli pyhittänyt Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Herra, heidän isiensä Jumala, lähetti, varhaisesta alkaen, vähän väliä heille varoituksia sanansaattajiensa kautta, sillä hän sääli kansaansa ja asumustaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Mutta he pilkkasivat Jumalan sanansaattajia ja halveksivat hänen sanaansa ja häpäisivät hänen profeettojaan, kunnes Herran viha hänen kansaansa kohtaan oli kasvanut niin, ettei ollut enää apua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Hän toi heidän kimppuunsa kaldealaisten kuninkaan ja surmautti miekalla heidän nuoret miehensä heidän pyhäkössään eikä säästänyt nuorukaista eikä neitosta, ei vanhusta eikä harmaapäätä. Kaikki hän antoi tämän käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Kaikki Jumalan temppelin esineet, sekä suuret että pienet, ja Herran temppelin aarteet sekä kuninkaan ja hänen päämiestensä aarteet, kaikki hän vei Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Jumalan temppeli poltettiin, Jerusalemin muurit revittiin, kaikki sen palatsit poltettiin tulella, ja kaikki sen kallisarvoiset esineet hävitettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Ne, jotka olivat säilyneet miekalta, vietiin karkotukseen Baabeliin. He olivat hänen ja hänen poikiensa palvelijoina, kunnes Persian valtakunta sai vallan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'Niin toteutui Herran sana, jonka hän oli puhunut Jeremian suun kautta, kunnes maa oli saanut hyvityksen sapateistaan – niin kauan kuin se oli autiona, se lepäsi – kunnes seitsemänkymmentä vuotta oli kulunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Mutta Kooreksen, Persian kuninkaan, ensimmäisenä hallitusvuotena herätti Herra, että täyttyisi Herran sana, jonka hän oli puhunut Jeremian suun kautta, Kooreksen, Persian kuninkaan, hengen, niin että tämä koko valtakunnassaan kuulutti ja julisti myös käskykirjalla näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, '\"Näin sanoo Koores, Persian kuningas: Kaikki maan valtakunnat on Herra, taivaan Jumala, antanut minulle, ja hän on käskenyt minun rakentaa itselleen temppelin Jerusalemiin, joka on Juudassa. Kuka vain teidän joukossanne on hänen kansaansa, sen kanssa olkoon Herra, hänen Jumalansa, ja hän menköön sinne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Kooreksen, Persian kuninkaan, ensimmäisenä hallitusvuotena Herra herätti Kooreksen, Persian kuninkaan, hengen, että täyttyisi Herran sana, jonka hän oli puhunut Jeremian suun kautta, niin että tämä koko valtakunnassaan kuulutti ja julisti myös käskykirjassa näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, '\"Näin sanoo Koores, Persian kuningas: Kaikki maan valtakunnat on Herra, taivaan Jumala, antanut minulle, ja hän on käskenyt minun rakentaa itselleen temppelin Jerusalemiin, joka on Juudassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Kuka vain joukossanne on hänen kansaansa, sen kanssa olkoon hänen Jumalansa, ja hän menköön Jerusalemiin, joka on Juudassa, rakentamaan Herran, Israelin Jumalan, temppeliä. Hän on se Jumala, joka asuu Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Kuka vain on jäljellä, saakoon, missä asuukin muukalaisena, paikkakuntansa miehiltä kannatukseksi hopeaa ja kultaa, tavaraa ja karjaa sekä vapaaehtoisia lahjoja Jumalan temppelin rakentamiseksi Jerusalemiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Silloin nousivat Juudan ja Benjaminin perhekuntien päämiehet sekä papit ja leeviläiset, kaikki, joiden hengen Jumala herätti menemään ja rakentamaan Herran temppeliä Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Kaikki, jotka asuivat heidän ympärillään, avustivat heitä hopeaesineillä, kullalla, tavaralla, karjalla ja kalleuksilla kaiken sen lisäksi, mitä annettiin vapaaehtoisina lahjoina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Kuningas Koores tuotti esiin Herran temppelin esineet, jotka Nebukadnessar oli vienyt pois Jerusalemista ja pannut oman jumalansa temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Ne Koores, Persian kuningas, tuotti aarteistonvartijalle, Mitredatille, ja tämä laski niiden luvun Sesbassarille, Juudan ruhtinaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Tämä oli niiden luku: kolmekymmentä kultamaljaa, tuhat hopeamaljaa, kaksikymmentä yhdeksän uhriastiaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'kolmekymmentä kultapikaria, neljäsataa kymmenen kaksoishopeapikaria, tuhat muuta esinettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Kulta- ja hopeaesineitä oli kaikkiaan viisituhatta neljäsataa. Kaikki nämä Sesbassar toi, silloin kun karkotetut tuotiin Baabelista Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Nämä olivat ne tämän maakunnan asukkaat, jotka lähtivät karkotettujen vankeudesta Baabelista, jonne Nebukadnessar, Baabelin kuningas, oli vienyt heidät karkotukseen, ja jotka palasivat Jerusalemiin ja Juudaan, kukin kaupunkiinsa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'ne, jotka tulivat Serubbaabelin, Jeesuan, Nehemian, Serajan, Reelajan, Mordekain, Bilsanin, Misparin, Bigvain, Rehumin ja Baanan kanssa. Israelin kansan miesten lukumäärä oli:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Paroksen jälkeläisiä kaksituhatta sata seitsemänkymmentä kaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Sefatjan jälkeläisiä kolmesataa seitsemänkymmentä kaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Aarahin jälkeläisiä seitsemänsataa seitsemänkymmentä viisi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Pahat-Mooabin jälkeläisiä, nimittäin Jeesuan ja Jooabin jälkeläisiä, kaksituhatta kahdeksansataa kaksitoista;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Eelamin jälkeläisiä tuhat kaksisataa viisikymmentä neljä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Sattun jälkeläisiä yhdeksänsataa neljäkymmentä viisi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Sakkain jälkeläisiä seitsemänsataa kuusikymmentä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Baanin jälkeläisiä kuusisataa neljäkymmentä kaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Beebain jälkeläisiä kuusisataa kaksikymmentä kolme;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Asgadin jälkeläisiä tuhat kaksisataa kaksikymmentä kaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Adonikamin jälkeläisiä kuusisataa kuusikymmentä kuusi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Bigvain jälkeläisiä kaksituhatta viisikymmentä kuusi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Aadinin jälkeläisiä neljäsataa viisikymmentä neljä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Aaterin, nimittäin Hiskian, jälkeläisiä yhdeksänkymmentä kahdeksan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Beesain jälkeläisiä kolmesataa kaksikymmentä kolme;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Jooran jälkeläisiä sata kaksitoista;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Haasumin jälkeläisiä kaksisataa kaksikymmentä kolme;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Gibbarin jälkeläisiä yhdeksänkymmentä viisi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'beetlehemiläisiä sata kaksikymmentä kolme;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Netofan miehiä viisikymmentä kuusi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'Anatotin miehiä sata kaksikymmentä kahdeksan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'asmavetilaisia neljäkymmentä kaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'kirjat-aarimilaisia, kefiralaisia ja beerotilaisia seitsemänsataa neljäkymmentä kolme;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'raamalaisia ja gebalaisia kuusisataa kaksikymmentä yksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'Mikmaan miehiä sata kaksikymmentä kaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'Beetelin ja Ain miehiä kaksisataa kaksikymmentä kolme;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'nebolaisia viisikymmentä kaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'Magbiin jälkeläisiä sata viisikymmentä kuusi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'toisen Eelamin jälkeläisiä tuhat kaksisataa viisikymmentä neljä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Haarimin jälkeläisiä kolmesataa kaksikymmentä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'loodilaisia, haadidilaisia ja oonolaisia seitsemänsataa kaksikymmentä viisi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'jerikolaisia kolmesataa neljäkymmentä viisi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'senaalaisia kolmetuhatta kuusisataa kolmekymmentä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Pappeja oli: Jedajan jälkeläisiä, nimittäin Jeesuan sukua, yhdeksänsataa seitsemänkymmentä kolme;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Immerin jälkeläisiä tuhat viisikymmentä kaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Pashurin jälkeläisiä tuhat kaksisataa neljäkymmentä seitsemän;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Haarimin jälkeläisiä tuhat seitsemäntoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Leeviläisiä oli: Jeesuan ja Kadmielin jälkeläisiä, nimittäin Hoodavjan jälkeläisiä, seitsemänkymmentä neljä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Veisaajia oli: Aasafin jälkeläisiä sata kaksikymmentä kahdeksan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Ovenvartijoiden jälkeläisiä oli: Sallumin jälkeläisiä, Aaterin jälkeläisiä, Talmonin jälkeläisiä, Akkubin jälkeläisiä, Hatitan jälkeläisiä, Soobain jälkeläisiä, kaikkiaan sata kolmekymmentä yhdeksän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Temppelipalvelijoita oli: Siihan jälkeläiset, Hasufan jälkeläiset, Tabbaotin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'Keeroksen jälkeläiset, Siiahan jälkeläiset, Paadonin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'Lebanan jälkeläiset, Hagaban jälkeläiset, Akkubin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'Haagabin jälkeläiset, Samlain jälkeläiset, Haananin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'Giddelin jälkeläiset, Gaharin jälkeläiset, Reajan jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'Resinin jälkeläiset, Nekodan jälkeläiset, Gassamin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'Ussan jälkeläiset, Paaseahin jälkeläiset, Beesain jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'Asnan jälkeläiset, Meunimin jälkeläiset, Nefusimin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'Bakbukin jälkeläiset, Hakufan jälkeläiset, Harhurin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'Baslutin jälkeläiset, Mehidan jälkeläiset, Harsan jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'Barkoksen jälkeläiset, Siiseran jälkeläiset, Taamahin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'Nesiahin jälkeläiset, Hatifan jälkeläiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Salomon palvelijoiden jälkeläisiä oli: Sootain jälkeläiset, Sooferetin jälkeläiset, Perudan jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'Jaalan jälkeläiset, Darkonin jälkeläiset, Giddelin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'Sefatjan jälkeläiset, Hattilin jälkeläiset, Pookeret-Sebaimin jälkeläiset, Aamin jälkeläiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Temppelipalvelijoita ja Salomon palvelijoiden jälkeläisiä oli kaikkiaan kolmesataa yhdeksänkymmentä kaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Nämä olivat ne, jotka lähtivät Teel-Melahista, Teel-Harsasta, Kerub-Addanista ja Immeristä, voimatta ilmoittaa perhekuntaansa ja syntyperäänsä, olivatko israelilaisia:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Delajan jälkeläisiä, Tobian jälkeläisiä, Nedokan jälkeläisiä, kuusisataa viisikymmentä kaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'Pappien poikien joukossa olivat Habaijan jälkeläiset, Koosin jälkeläiset ja Barsillain jälkeläiset, sen, joka oli ottanut vaimon gileadilaisen Barsillain tyttäristä ja jota kutsuttiin heidän nimellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Nämä etsivät sukuluetteloitaan, niitä löytämättä, ja niin heidät julistettiin pappeuteen kelpaamattomiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Maaherra kielsi heitä syömästä korkeasti pyhää, ennen kuin nousisi pappi, joka voi hoitaa uurimia ja tummimia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Koko seurakunta oli yhteensä neljäkymmentä kaksi tuhatta kolmesataa kuusikymmentä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'paitsi heidän palvelijoitaan ja palvelijattariaan, joita oli seitsemäntuhatta kolmesataa kolmekymmentä seitsemän. Lisäksi oli heillä kaksisataa mies- ja naisveisaajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Hevosia heillä oli seitsemänsataa kolmekymmentä kuusi, muuleja kaksisataa neljäkymmentä viisi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'kameleja neljäsataa kolmekymmentä viisi, aaseja kuusituhatta seitsemänsataa kaksikymmentä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Perhekuntien päämiehistä muutamat, tullessaan Herran temppelin paikalle, joka on Jerusalemissa, antoivat vapaaehtoisia lahjoja Jumalan temppelille sen pystyttämiseksi paikalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'He antoivat sen mukaan, kuin voivat, rakennusrahastoon: kuusikymmentä yksi tuhatta dareikkia kultaa, viisituhatta miinaa hopeaa ja sata papinviittaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Papit, leeviläiset ja osa kansaa sekä veisaajat, ovenvartijat ja temppelipalvelijat asettuivat kaupunkeihinsa, ja kaikki muut israelilaiset kaupunkeihinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Kun seitsemäs kuukausi tuli ja israelilaiset olivat jo kaupungeissa, kansa kokoontui yhtenä miehenä Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Jeesua, Joosadakin poika, ja hänen veljensä, papit, ja Serubbaabel, Sealtielin poika, ja hänen veljensä nousivat rakentamaan Israelin Jumalan alttaria uhratakseen sen päällä polttouhreja, niin kuin on kirjoitettuna Jumalan miehen Mooseksen laissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'He pystyttivät paikalleen alttarin, sillä he olivat kauhuissaan maan kansojen tähden, ja he uhrasivat alttarilla polttouhreja Herralle, polttouhreja aamuin ja illoin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'He viettivät lehtimajanjuhlaa, niin kuin oli säädetty, ja uhrasivat polttouhreja joka päivä niin paljon, kuin oli säädetty, kunakin päivänä sen päivän uhrit,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'ja sen jälkeen jokapäiväisen polttouhrin ja uudenkuun päivien ja kaikkien muiden Herran pyhien juhlien uhrit sekä kaikkien niiden uhrit, jotka toivat vapaaehtoisia lahjoja Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Seitsemännen kuun ensimmäisestä päivästä alkaen he uhrasivat polttouhreja Herralle, vaikka temppelin perustusta ei ollut vielä laskettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'He antoivat rahaa kivenhakkaajille ja puusepille sekä ruoka- ja juomatavaroita ja öljyä siidonilaisille ja tyyrolaisille, että nämä kuljettaisivat setripuita Libanonilta meritse Jaafoon sen valtuuden nojalla, jonka Koores, Persian kuningas, oli antanut heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Toisena vuotena siitä, kun he olivat tulleet Jumalan temppelin paikalle Jerusalemiin, sen toisessa kuussa, ryhtyivät Serubbaabel, Sealtielin poika, ja Jeesua, Joosadakin poika, ja heidän muut veljensä, papit ja leeviläiset, ja kaikki, jotka vankeudesta olivat tulleet Jerusalemiin, työhön ja panivat kaksikymmentävuotiaat ja sitä vanhemmat leeviläiset johtamaan Herran temppelin rakennustyötä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Jeesua poikineen ja veljineen ja Kadmiel poikineen, Juudan jälkeläiset, astuivat yhdessä johtamaan niitä, jotka tekivät Jumalan temppelin rakennustyötä, samoin myös Heenadadin pojat poikineen ja veljineen, leeviläiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Kun rakentajat laskivat Herran temppelin perustusta, asetettiin papit virkapuvuissaan torvilla ja leeviläiset, Aasafin jälkeläiset, symbaaleilla ylistämään Herraa, Israelin kuninkaan Daavidin järjestelyn mukaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'He virittivät ylistys- ja kiitosvirren Herralle: \"Sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti Israelia kohtaan.\" Kaikki kansa nosti suuren riemuhuudon ylistäen Herraa siitä, että Herran temppelin perustus oli laskettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Monet papit, leeviläiset ja perhekuntien päämiehet, vanhukset, jotka olivat nähneet edellisen temppelin, itkivät suurella äänellä, kun tämän temppelin perustus laskettiin heidän nähtensä. Monet taas korottivat äänensä riemuiten ja iloiten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Eikä voitu erottaa raikuvaa riemuhuutoa kansan äänekkäästä itkusta, sillä kansa nosti suuren huudon, niin että huuto kuului kauas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Mutta kun Juudan ja Benjaminin vastustajat kuulivat, että karkotetut rakensivat temppeliä Herralle, Israelin Jumalalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'he astuivat Serubbaabelin ja perhekuntien päämiesten luo ja sanoivat heille: \"Tahdomme rakentaa kanssanne yhdessä, sillä etsimme teidän Jumalaanne, niin kuin tekin, ja hänelle me olemme uhranneet Eesarhaddonin, Assurin kuninkaan, päivistä asti, hänen, joka toi meidät tänne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Mutta Serubbaabel ja Jeesua ja muut Israelin perhekuntien päämiehet sanoivat heille: \"Ei sovi teidän ja meidän yhdessä rakentaa temppeliä Jumalallemme, vaan me yksin rakennamme Herralle, Israelin Jumalalle, niin kuin kuningas Koores, Persian kuningas, on meitä käskenyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Mutta maan kansa sai Juudan kansan kädet herpoamaan ja pelotti heidät rakentamasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'He palkkasivat heitä vastaan neuvonantajia, jotka tekivät heidän hankkeensa tyhjäksi, niin kauan kuin Koores, Persian kuningas, eli, ja aina Daarejaveksen, Persian kuninkaan, hallitusaikaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Ahasveroksen hallituksen aikana, hänen hallituksensa alussa, he kirjoittivat syytekirjelmän Juudan ja Jerusalemin asukkaita vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Artahsastan aikana kirjoittivat Bislam, Mitredat ja Taabeel sekä näiden muut virkatoverit Artahsastalle, Persian kuninkaalle. Kirje oli kirjoitettu aramin kirjoituksella ja käännetty aramin kielelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Käskynhaltija Rehum ja kirjuri Simsai kirjoittivat kuningas Artahsastalle Jerusalemia vastaan kirjeen, joka kuului näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Silloin ja silloin. \"Käskynhaltija Rehum ja kirjuri Simsai sekä muut heidän virkatoverinsa, tuomarit, järjestysmiehet, tarpelilaiset, afarsilaiset, erekiläiset, babylonialaiset, suusanilaiset, dehavilaiset, eelamilaiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'ja muut kansat, jotka suuri ja maineikas Aasenappar vei karkotukseen ja sijoitti Samarian kaupunkiin ja muualle, tälle puolelle Eufrat-virran,\" ja niin edespäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Tämä on jäljennös kirjeestä, jonka he lähettivät hänelle: \"Kuningas Artahsastalle palvelijasi, miehet tältä puolelta Eufrat-virran,\" ja niin edespäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, '\"Tietäköön kuningas, että ne juutalaiset, jotka lähtivät luotasi meidän luoksemme, ovat tulleet Jerusalemiin. He ovat nyt rakentamassa tuota kapinallista ja pahaa kaupunkia ja panemassa kuntoon muureja ja korjaamassa perustuksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Tietäköön kuningas, että jos kaupunki rakennetaan ja muurit pannaan kuntoon, he eivät suorita rahaveroa, eivät luonnontuotteita eivätkä tierahaa, ja siitä kärsivät kuninkaiden tulot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Koska kerran syömme palatsin suolaa eikä meidän sovi nähdä kuninkaan häpäisemistä, sen tähden lähetämme ja ilmoitamme tämän kuninkaalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'että hän tutkituttaisi sinun isiesi aikakirjaa. Aikakirjasta näet huomaat ja saat tietää, että kaupunki on ollut kapinallinen kaupunki, joka on tuottanut kuninkaille ja maakunnille vahinkoa ja jossa ammoisista ajoista on pantu toimeen levottomuuksia. Sen tähden kaupunki on hävitetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Ilmoitamme siis kuninkaalle, että jos kaupunki rakennetaan ja muurit pannaan kuntoon, ei sinulla ole oleva mitään osaa tällä puolella Eufrat-virran olevaan maahan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Kuningas lähetti vastauksen käskynhaltija Rehumille ja kirjuri Simsaille ja muille heidän virkatovereilleen, jotka asuivat Samariassa ja muualla tällä puolella Eufrat-virran: \"Rauhaa\" ja niin edespäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, '\"Kirjelmä, jonka meille lähetitte, on minulle tarkkaan luettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Annoin käskyn tutkia asian, ja huomattiin, että kaupunki ammoisista ajoista asti on noussut kuninkaita vastaan ja että siellä on pantu toimeen kapinoita ja levottomuuksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Jerusalemissa on ollut mahtavia kuninkaita, jotka ovat hallinneet kaikkea Eufrat-virran senpuoleista maata ja joille on suoritettu rahaveroa, luonnontuotteita ja tierahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Antakaa siis käsky, että miehet on estettävä työstään ja että kaupunki on jätettävä rakentamatta, kunnes minulta tulee käsky.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Varokaa, ettette lyö laimin mitään tässä asiassa, etteivät kuninkaat kärsisi siitä suurta vahinkoa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Niin pian kuin kuningas Artahsastan kirjelmän jäljennös oli luettu Rehumille, kirjuri Simsaille ja heidän virkatovereilleen, he menivät kiireesti Jerusalemiin juutalaisten luo ja estivät heidät väkisin työtä tekemästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Silloin pysähtyi Jumalan temppelin rakennustyö Jerusalemissa ja oli pysähdyksissä Daarejaveksen, Persian kuninkaan, toiseen hallitusvuoteen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Mutta profeetta Haggai ja Sakarja, Iddon poika, profeetat, ennustivat Juudassa ja Jerusalemissa oleville juutalaisille Israelin Jumalan nimeen, hänen, jonka nimiin heidät oli otettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Serubbaabel, Sealtielin poika, ja Jeesua, Joosadakin poika, nousivat ja alkoivat rakentaa Jumalan temppeliä Jerusalemissa, ja heidän kanssaan Jumalan profeetat, jotka tukivat heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'Siihen aikaan heidän luokseen tulivat Tattenai, Eufrat-virran tämänpuoleisen maan käskynhaltija, ja Setar-Boosenai sekä heidän virkatoverinsa ja sanoivat heille näin: \"Kuka on käskenyt teitä rakentamaan tätä temppeliä ja panemaan kuntoon tätä muuria?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Sanoimme heille niiden miesten nimet, jotka tätä rakennusta rakensivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Juutalaisten vanhinten yllä oli heidän Jumalansa silmä, niin ettei heitä estetty työstä, vaan asiasta meni selonteko Daarejavekselle ja odotettiin sitä koskevan kirjoituksen tuloa sieltä takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Jäljennös kirjeestä, jonka Tattenai, Eufrat-virran tämänpuoleisen maan käskynhaltija, ja Setar-Boosenai sekä tämän virkatoverit, ne afarsakilaiset, jotka olivat tällä puolella Eufrat-virran, lähettivät kuningas Daarejavekselle –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'he näet lähettivät hänelle kertomuksen – ja siihen oli kirjoitettu näin: \"Kuningas Daarejavekselle kaikkea rauhaa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Tietäköön kuningas, että me menimme Juudan maakuntaan, suuren Jumalan temppelille. Sitä rakennetaan suurista kivistä, ja hirsiä pannaan seiniin. Työ tehdään tarkasti ja sujuu heidän käsissään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Kysyimme vanhimmilta ja sanoimme heille näin: \'Kuka on käskenyt teitä rakentamaan tätä temppeliä ja panemaan kuntoon tätä muuria?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Kysyimme heiltä myös heidän nimensä ilmoittaaksemme ne sinulle ja kirjoitimme muistiin niiden miesten nimet, jotka ovat heitä johtamassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'He antoivat meille tämän vastauksen: \'Me olemme taivaan ja maan Jumalan palvelijoita, ja rakennamme uudestaan temppeliä, joka oli rakennettu monta vuotta sitten. Suuri Israelin kuningas sen rakensi ja sai sen valmiiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Mutta koska isämme vihoittivat taivaan Jumalan, hän antoi heidät kaldealaisen Nebukadnessarin, Baabelin kuninkaan, käsiin, ja hän hävitti tämän temppelin ja vei kansan karkotukseen Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Mutta Kooreksen, Baabelin kuninkaan, ensimmäisenä hallitusvuotena antoi kuningas Koores käskyn rakentaa uudestaan tämän Jumalan temppelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Kuningas Koores antoi myös tuoda Baabelin temppelistä esiin Jumalan temppelin kulta- ja hopeaesineet, jotka Nebukadnessar oli vienyt pois Jerusalemin temppelistä ja tuonut Baabelin temppeliin. Ne annettiin Sesbassar-nimiselle miehelle, jonka hän oli asettanut käskynhaltijaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'Hän sanoi tälle: Ota nämä esineet, mene ja pane ne Jerusalemin temppeliin. Jumalan temppeli rakennettakoon entiselle paikalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Tämä Sesbassar tuli ja laski Jumalan temppelin perustuksen Jerusalemissa. Siitä ajasta alkaen tähän saakka sitä on rakennettu, eikä se ole valmis vieläkään.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Jos kuningas siis hyväksi näkee, niin tutkittakoon kuninkaan aarrekammiossa siellä Baabelissa, onko niin, että kuningas Koores on antanut käskyn rakentaa tämän Jumalan temppelin Jerusalemissa. Kuningas lähettänee meille tiedon tahdostaan tässä asiassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Kuningas Daarejaves antoi käskyn, että asia tutkittaisiin Baabelin arkistossa, jonne myös aarteet koottiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Ahmetan linnasta, Meedian maakunnasta, löydettiin kirjakäärö, johon oli kirjoitettu seuraavasti: \"Muistettava tapahtuma:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'Kuningas Kooreksen ensimmäisenä hallitusvuotena kuningas Koores antoi käskyn: Jumalan temppeli Jerusalemissa, temppeli rakennettakoon paikaksi, jossa uhreja uhrataan. Sen perustukset laskettakoon lujiksi, sen korkeus olkoon kuusikymmentä kyynärää ja leveys kuusikymmentä kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Siinä olkoon aina rinnakkain kolme kivikerrosta suuria kiviä ja yksi hirsikerros uusia hirsiä, ja kustannukset suoritettakoon kuninkaan hovista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Myös Jumalan temppelin kulta- ja hopeaesineet, jotka Nebukadnessar vei pois Jerusalemin temppelistä ja toi Baabeliin, annettakoon takaisin. Ne tulkoot paikoilleen Jerusalemin temppeliin, pantakoon ne Jumalan temppeliin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, '– \"Niin ollen on sinun, Tattenai, joka olet Eufrat-virran tuonpuoleisen maan käskynhaltija, sinun, Setar-Boosenai, ja teidän virkatoverienne, niiden afarsakilaisten, jotka ovat tuolla puolella Eufrat-virran, pysyttävä siitä erillänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Antakaa Jumalan temppelin rakennustyön olla rauhassa. Juutalaisten käskynhaltija ja juutalaisten vanhimmat rakentakoot Jumalan temppelin paikalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Annan käskyn, mitä teidän on tehtävä juutalaisten vanhimmille heidän rakentaessaan Jumalan temppeliä: tuolta puolelta Eufrat-virran tulevista kuninkaan verotuloista suoritettakoon niille miehille tarkasti ja viivyttelemättä kustannukset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Mitä tarvitaan, mulleja, pässejä ja karitsoita polttouhreiksi taivaan Jumalalle, vehnää, suolaa, viiniä ja öljyä, se annettakoon heille Jerusalemin pappien esityksestä joka päivä laiminlyömättä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'että he uhraisivat suloisesti tuoksuvia uhreja taivaan Jumalalle ja rukoilisivat kuninkaan ja hänen poikiensa hengen puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Annan käskyn, että kuka ikinä rikkoo tämän määräyksen, hänen talostaan revittäköön hirsi, ja hänet ripustettakoon ja naulittakoon siihen, ja hänen talostaan tehtäköön siitä syystä soraläjä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Jumala, joka on asettanut nimensä siihen, kukistakoon jokaisen kuninkaan ja kansan, joka ojentaa kätensä rikkomaan tätä määräystä hävittämällä Jumalan temppelin Jerusalemissa. Minä Daarejaves olen antanut tämän käskyn. Se täytettäköön tarkasti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Silloin Tattenai, Eufrat-virran tämänpuoleisen maan käskynhaltija, Setar-Boosenai ja heidän virkatoverinsa täyttivät tarkasti käskyn, jonka kuningas Daarejaves oli heille lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Juutalaisten vanhimmat rakensivat, ja työ onnistui heille profeetta Haggain ja Sakarjan, Iddon pojan, ennustuksen kautta. He saivat sen valmiiksi Israelin Jumalan käskyn ja Kooreksen, Daarejaveksen ja Artahsastan, Persian kuninkaan, käskyn mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Tämä temppeli valmistui adar-kuun kolmanneksi päiväksi, nimittäin kuningas Daarejaveksen kuudentena hallitusvuotena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Silloin israelilaiset, papit ja leeviläiset ja muut karkotetut, viettivät Jumalan temppelin vihkiäisiä iloiten');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'ja uhrasivat Jumalan temppelin vihkiäisissä sata härkää, kaksisataa pässiä ja neljäsataa karitsaa sekä syntiuhriksi koko Israelin puolesta kaksitoista kaurista, Israelin sukukuntien luvun mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'He asettivat papit ryhmittäin ja leeviläiset osastoittain Jumalan palvelukseen Jerusalemissa, niin kuin on kirjoitettuna Mooseksen kirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Karkotetut viettivät pääsiäistä ensimmäisen kuun neljäntenätoista päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Sillä papit ja leeviläiset olivat yhtenä miehenä puhdistautuneet, niin että he kaikki olivat puhtaat. He teurastivat pääsiäislampaan kaikille karkotetuille, veljilleen papeille ja itselleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Sitä söivät kaikki karkotuksesta palanneet israelilaiset sekä kaikki, jotka olivat eristäytyneet maassa asuvien pakanoiden saastaisuudesta ja liittyneet heihin etsiäkseen Herraa, Israelin Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'He viettivät happamattoman leivän juhlaa seitsemän päivää iloiten, sillä Herra oli ilahduttanut heitä, kun oli kääntänyt Assurin kuninkaan sydämen heidän puolelleen, niin että hän avusti heitä Jumalan, Israelin Jumalan, temppelin rakentamistyössä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Näiden tapausten jälkeen, Persian kuninkaan Artahsastan hallituksen aikana, lähti Esra, Serajan poika, joka oli Asarjan poika, joka Hilkian poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'joka Sallumin poika, joka Saadokin poika, joka Ahitubin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'joka Amarjan poika, joka Asarjan poika, joka Merajotin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'joka Serahjan poika, joka Ussin poika, joka Bukkin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'joka Abisuan poika, joka Piinehaan poika, joka Eleasarin poika, joka Aaronin, ylimmäisen papin, poika –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'tämä Esra lähti Baabelista. Hän oli kirjanoppinut, perehtynyt Mooseksen lakiin, jonka Herra, Israelin Jumala, oli antanut. Kuningas antoi hänelle kaikki, mitä hän halusi, koska Esran päällä oli Herran, hänen Jumalansa, käsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Myös israelilaisia ja pappeja, leeviläisiä, veisaajia, ovenvartijoita ja temppelipalvelijoita lähti Jerusalemiin kuningas Artahsastan seitsemäntenä hallitusvuotena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Hän tuli Jerusalemiin viidennessä kuussa kuninkaan seitsemäntenä hallitusvuotena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Sillä ensimmäisen kuun ensimmäisenä päivänä alkoi lähtö Baabelista, ja viidennen kuun ensimmäisenä päivänä hän tuli Jerusalemiin, koska Jumalan hyvä käsi oli hänen päällään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Sillä Esra oli kiinnittänyt sydämensä Herran lain tutkimiseen seuratakseen sitä ja opettaakseen Israelissa lakia ja oikeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Tämä on jäljennös kirjeestä, jonka kuningas Artahsasta antoi pappi Esralle, kirjanoppineelle, joka oli Herran Israelille antamien käskyjen ja ohjeitten tuntija:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, '\"Artahsasta, kuningasten kuningas, pappi Esralle, taivaan Jumalan lain tuntijalle\", ja niin edespäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, '\"Minä annan käskyn, että minun valtakunnassani jokainen Israelin kansan jäsen ja sen papit ja leeviläiset, jotka ovat halukkaat lähtemään Jerusalemiin, lähtekööt kanssasi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'koska kuningas ja hänen seitsemän neuvonantajaansa ovat lähettäneet sinut tarkastamaan, ovatko olot Juudassa ja Jerusalemissa sen Jumalasi lain mukaiset, joka on kädessäsi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'ja viemään sinne hopean ja kullan, minkä kuningas ja hänen neuvonantajansa ovat antaneet vapaaehtoisena lahjana Israelin Jumalalle, jonka asumus on Jerusalemissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'ja myös kaiken hopean ja kullan, minkä saat koko Baabelin maakunnasta, sekä ne vapaaehtoiset lahjat, jotka kansa ja papit antavat Jumalansa temppeliin Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Osta siis näillä rahoilla mitä tunnollisimmin härkiä, pässejä ja karitsoita sekä niihin kuuluvia ruoka- ja juomauhreja. Uhraa ne Jumalanne temppelin alttarilla Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Mitä sinä ja veljesi näette hyväksi tehdä hopean ja kullan tähteillä, se tehkää Jumalanne tahdon mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Ne esineet, jotka sinulle annetaan jumalanpalvelusta varten Jumalasi temppelissä, jätä Jerusalemin Jumalan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Muut Jumalasi temppelin tarpeet, joita joudut suorittamaan, sinä saat suorittaa kuninkaan aarrekammiosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Minä, kuningas Artahsasta, annan käskyn kaikille aarteistojen vartijoille tuolla puolella Eufrat-virran: \'Kaikki, mitä pappi Esra, taivaan Jumalan lain tuntija, teiltä pyytää, se tunnollisesti toimitettakoon:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'hopeaa aina sataan talenttiin, vehnää sataan koor-mittaan, viiniä sataan bat-mittaan, öljyä sataan bat-mittaan saakka, niin myös suolaa ilman määrää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Kaikki, mitä taivaan Jumala käskee, tehtäköön taivaan Jumalan temppelille täsmällisesti, ettei viha kohtaisi kuninkaan ja hänen poikiensa valtakuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Vielä tehdään teille tiettäväksi, ettei kukaan ole oikeutettu vaatimaan rahaveroa, luonnontuotteita tai tierahoja yhdeltäkään papilta tai leeviläiseltä, veisaajalta, ovenvartijalta, temppelipalvelijalta tai muulta tämän Jumalan temppelin tehtäviä toimittavalta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Ja sinä, Esra, aseta Jumalasi viisauden mukaan, joka on kädessäsi, tuomareita ja lakimiehiä tuomitsemaan kaikkea kansaa tuolla puolella Eufrat-virran, kaikkia, jotka tuntevat Jumalasi lain. Mutta niille, jotka eivät sitä tunne, opettakaa sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Jokainen, joka ei seuraa Jumalasi lakia ja kuninkaan lakia, tuomittakoon tarkasti harkiten joko kuolemaan tai karkotukseen, rahasakkoon tai vankeuteen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Kiitetty olkoon Herra, isiemme Jumala, joka on pannut kuninkaan sydämeen, että hänen on kaunistettava Herran temppeliä Jerusalemissa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'ja joka on suonut minun saavuttaa kuninkaan, hänen neuvonantajiensa ja kaikkien kuninkaan mahtavien ruhtinasten suosion. Minä rohkaisin mieleni, koska Herran, Jumalani, käsi oli päälläni, ja kokosin Israelista päämiehiä lähtemään kanssani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Nämä olivat ne heidän perhekuntiensa päämiehet ja heidän sukuluetteloihinsa merkityt, jotka kuningas Artahsastan hallituksen aikana lähtivät kanssani Baabelista:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Piinehaan jälkeläisiä Geersom; Iitamarin jälkeläisiä Daniel; Daavidin jälkeläisiä Hattus;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'Sekanjan jälkeläisiä, Paroksen jälkeläisiä, Sakarja ja hänen kanssaan sata viisikymmentä sukuluetteloihin merkittyä miestä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'Pahat-Mooabin jälkeläisiä Eljoenai, Serahjan poika, ja hänen kanssaan kaksisataa miestä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Sekanjan jälkeläisiä Jahasielin poika ja hänen kanssaan kolmesataa miestä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'Aadinin jälkeläisiä Ebed, Joonatanin poika, ja hänen kanssaan viisikymmentä miestä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'Eelamin jälkeläisiä Jesaja, Ataljan poika, ja hänen kanssaan seitsemänkymmentä miestä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'Sefatjan jälkeläisiä Sebadja, Miikaelin poika, ja hänen kanssaan kahdeksankymmentä miestä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Jooabin jälkeläisiä Obadja, Jehielin poika, ja hänen kanssaan kaksisataa kahdeksantoista miestä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'Selomitin jälkeläisiä Joosifjan poika ja hänen kanssaan sata kuusikymmentä miestä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'Beebain jälkeläisiä Sakarja, Beebain poika, ja hänen kanssaan kaksikymmentä kahdeksan miestä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'Asgadin jälkeläisiä Joohanan, Hakkatanin poika, ja hänen kanssaan sata kymmenen miestä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'Adonikamin jälkeläisiä myöhemmin tulleet, joiden nimet olivat Elifelet, Jeguel ja Semaja, ja heidän kanssaan kuusikymmentä miestä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'Bigvain jälkeläisiä Uutai ja Sabbud ja heidän kanssaan seitsemänkymmentä miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Kokosin heidät joelle, joka juoksee Ahavaan päin, ja olimme siellä leiriytyneinä kolme päivää. Mutta kun tarkastin kansaa ja pappeja, en löytänyt sieltä yhtään leeviläistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Lähetin päämiehet Elieserin, Arielin, Semajan, Elnatanin, Jaaribin, Elnatanin, Naatanin, Sakarjan ja Mesullamin sekä opettajat Joojaribin ja Elnatanin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'ja käskin heidän mennä päämies Iddon luo Kaasifjan paikkakunnalle ja panin heidän suuhunsa sanat, jotka heidän oli puhuttava veljilleen Iddolle ja temppelipalvelijoille, Kaasifjan paikkakunnalla, että he toisivat meille palvelijoita Jumalamme temppeliä varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Koska Jumalamme hyvä käsi oli päällämme, he toivat meille ymmärtäväisen miehen, joka oli Mahlin, Leevin pojan ja Israelin pojan, jälkeläisiä, ja Seerebjan poikineen ja veljineen, kahdeksantoista miestä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'ja Hasabjan ja hänen kanssaan Jesajan, joka oli Merarin jälkeläisiä, veljineen ja poikineen, kaksikymmentä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'niin myös temppelipalvelijoista, jotka Daavid ja päämiehet olivat antaneet leeviläisille palvelemaan heitä, kaksisataa kaksikymmentä temppelipalvelijaa, kaikki nimeltä mainittuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Minä kuulutin siellä Ahava-joella paaston, että nöyrtyisimme Jumalamme edessä ja anoisimme häneltä suotuisaa matkaa itsellemme, vaimoillemme ja lapsillemme ja kaikelle omaisuudellemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Sillä minua hävetti pyytää kuninkaalta sotaväkeä ja ratsumiehiä auttamaan meitä vihollisia vastaan matkalla, koska olimme sanoneet kuninkaalle näin: \"Jumalamme käsi on kaikkien päällä, jotka etsivät häntä, heidän parhaakseen, mutta hänen voimansa ja vihansa on kaikkia vastaan, jotka hylkäävät hänet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Paastosimme ja anoimme tätä Jumalaltamme, ja hän kuuli rukouksemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Valitsin pappien päämiehistä kaksitoista, nimittäin Seerebjan ja Hasabjan ja heidän kanssaan kymmenen heidän veljistään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'ja punnitsin heille hopean ja kullan ja esineet, sen antimen, jonka kuningas ja hänen neuvonantajansa ja ruhtinaansa ja kaikki siellä olevat israelilaiset olivat antaneet Jumalamme temppeliä varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Punnitsin heille käteen hopeaa kuusisataa viisikymmentä talenttia sekä hopeaesineitä sata talenttia ja kultaa sata talenttia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'kaksikymmentä kultapikaria, arvoltaan tuhat dareikkia, sekä kaksi hienoa, kullankiiltävää vaskiastiaa, kallisarvoista kuin kulta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Sanoin heille: \"Te olette pyhitetyt Herralle, ja esineet ovat pyhitetyt. Hopea ja kulta ovat vapaaehtoinen lahja Herralle, isienne Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Vartioikaa siis niitä ja säilyttäkää ne, kunnes punnitsette ne pappien päämiesten ja leeviläisten ja Israelin perhekuntien päämiesten edessä Jerusalemissa, Herran temppelin kammioissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Papit ja leeviläiset ottivat vastaan punnitun hopean ja kullan ja esineet viedäkseen ne Jerusalemiin, Jumalamme temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Sitten lähdimme liikkeelle Ahava-joelta ensimmäisen kuun kahdentenatoista päivänä mennäksemme Jerusalemiin. Jumalamme käsi oli päällämme, ja hän pelasti meidät vihollisten käsistä ja väijytyksistä tiellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Tulimme Jerusalemiin ja olimme siellä alallamme kolme päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Mutta neljäntenä päivänä punnittiin hopea ja kulta ja esineet Jumalamme temppelissä pappi Meremotille, Uurian pojalle, käteen. Hänen kanssaan oli Eleasar, Piinehaan poika, ja heidän kanssaan leeviläiset Joosabad, Jeesuan poika, ja Nooadja, Binnuin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Kaikki punnittiin lukumäärän ja painon mukaan, ja koko paino kirjoitettiin silloin muistiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Vankeudesta tulleet karkotetut uhrasivat polttouhreiksi Israelin Jumalalle kaksitoista härkää koko Israelin puolesta, yhdeksänkymmentä kuusi pässiä, seitsemänkymmentä seitsemän karitsaa ja kaksitoista syntiuhripukkia, kaikki polttouhriksi Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'He jättivät kuninkaan määräykset kuninkaan satraapeille ja käskynhaltijoille, jotka olivat Eufrat-virran tällä puolella, ja nämä avustivat kansaa ja Jumalan temppeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Kun tämä oli suoritettu loppuun, päämiehet astuivat luokseni ja sanoivat: \"Ei kansa, ei Israel eivätkä papit ja leeviläiset ole eristäytyneet maan kansoista ja niiden kauhistavista teoista – ei kanaanilaisista, heettiläisistä, perissiläisistä, jebusilaisista, ammonilaisista, mooabilaisista, egyptiläisistä eikä amorilaisista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Sillä he ovat ottaneet itselleen ja pojilleen näiden tyttäriä vaimoiksi, ja niin on pyhä siemen sekaantunut maan kansoihin. Päämiesten ja esimiesten käsi on ollut ensimmäisenä tässä uskottomassa menossa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Kun kuulin tämän, repäisin vaatteeni ja viittani, revin pääni hiuksia ja partaani ja istuin kauhuissani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Luokseni kokoontuivat kaikki, jotka pelkäsivät sitä, mitä Israelin Jumala oli puhunut karkotettujen uskottomuudesta, ja minä jäin istumaan kauhistuneena ehtoouhriin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Ehtoouhrin aikana nousin nöyryyttämästä itseäni ja polvistuin, repäisin vaatteeni ja viittani ja ojensin käteni Herran, Jumalani, puoleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'ja sanoin: \"Jumalani, häpeän enkä kehtaa kohottaa kasvojani puoleesi, Jumalani, sillä rikoksemme ovat nousseet päämme yli ja syyllisyytemme on kohonnut taivaaseen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Isiemme päivistä aina tähän päivään asti on syyllisyytemme ollut suuri, ja rikostemme tähden meidät, kuninkaamme ja pappimme on annettu maan kuningasten käsiin miekan, vankeuden, ryöstön ja häpeän alaisiksi, niin kuin tähän päivään saakka on tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Mutta nyt on meille hetkeksi tullut armo Herralta, Jumalaltamme, koska hän on sallinut pelastuneen joukon meistä jäädä jäljelle ja antanut meille jalansijan pyhässä paikassaan, että hän, Jumalamme, valaisisi silmämme ja soisi meidän hiukan hengähtää orjuudessamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Sillä orjia me olemme, mutta orjuudessamme Jumalamme ei ole meitä hylännyt, vaan on suonut meidän saavuttaa Persian kuningasten suosion ja hengähtää pystyttääksemme Jumalamme temppelin ja kohottaaksemme sen raunioistaan. Hän on antanut meille suojatun paikan Juudassa ja Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Mutta nyt, Jumalamme, mitä sanomme kaiken tämän jälkeen? Olemmehan hylänneet käskysi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'jotka sinä olet antanut palvelijoittesi, profeettojen, kautta, sanoen: \'Maa, jota te menette ottamaan omaksenne, se maa on saastainen maan kansojen saastaisuuden tähden ja niiden kauhistavien tekojen tähden, joilla he saastaisuudessaan ovat täyttäneet sen äärestä ääreen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Älkää siis antako tyttäriänne heidän pojilleen älkääkä ottako heidän tyttäriään pojillenne vaimoiksi. Älkää myöskään koskaan toimiko heidän menestyksekseen ja onnekseen, että te vahvistuisitte ja saisitte syödä parasta, mitä maassa on, ja jättäisitte sen perinnöksi lapsillenne ikiajoiksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Kaiken sen jälkeen, mikä on meitä kohdannut pahojen tekojemme ja suuren syyllisyytemme tähden – kuitenkin sinä, Jumalamme, olet jättänyt huomioon ottamatta rikoksemme ja olet sallinut meistä tämmöisen joukon pelastua –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'kävisimmekö nyt jälleen rikkomaan sinun käskyjäsi ja lankoutumaan kansojen kanssa, joiden teot ovat kauhistavat? Etkö sinä silloin vihastuisi meihin, kunnes tekisit meistä lopun, niin ettei ketään jäisi jäljelle eikä kukaan pelastuisi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Herra, Israelin Jumala, sinä olet vanhurskas, sillä meistä on jäljellä pelastuneita vain sen verran, kuin tänä päivänä on. Katso, olemme sinun edessäsi syyllisyydessämme, emmekä tämän tähden voi sinun edessäsi kestää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Kun Esra näin rukoili ja tunnusti itkien ja maahan langeten Jumalan temppelin edustalla, hänen luokseen kokoontui sangen suuri joukko Israelin miehiä, naisia ja lapsia, sillä kansakin itki katkerasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Sekanoja, Jehielin poika, Eelamin jälkeläisiä, puhkesi puhumaan ja sanoi Esralle: \"Me olemme olleet uskottomat Jumalaamme kohtaan, kun olemme ottaneet muukalaisia vaimoja maan kansoista. Mutta kuitenkin on Israelilla vielä toivoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Tehkäämme nyt Jumalamme kanssa liitto, että Jumalan neuvon mukaan ja niiden neuvon mukaan, jotka pelkäävät Jumalamme käskyä, toimitamme pois kaikki ne vaimot ja heistä syntyneet lapset. Tehtäköön lain mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Nouse, sillä tämä on sinun asiasi, ja me olemme kanssasi. Ole luja ja ryhdy toimeen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Esra nousi ja vannotti pappien päämiehet, leeviläiset ja kaiken Israelin tekemään näin, ja he vannoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Esra nousi Jumalan temppelin edustalta ja meni Joohananin, Eljasibin pojan, kammioon. Sinne tultuaan hän ei syönyt leipää eikä juonut vettä, sillä niin hän suri karkotettujen uskottomuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Kaikille karkotetuille kuulutettiin Juudassa ja Jerusalemissa, että heidän tuli kokoontua Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'Mutta se, joka ei tullut kolmen päivän kuluessa, päämiesten ja vanhinten päätöksen mukaan, sen koko omaisuus oli vihittävä tuhon omaksi ja hän itse oli tuleva erotetuksi karkotettujen seurakunnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Kaikki Juudan ja Benjaminin miehet kokoontuivat Jerusalemiin kolmanneksi päiväksi, joka oli yhdeksännen kuun kahdeskymmenes päivä. Kaikki kansa asettui Jumalan temppelin aukealle vavisten sekä asian tähden että rankkasateen vuoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Pappi Esra nousi ja sanoi heille: \"Te olette olleet uskottomat, kun olette ottaneet muukalaisia vaimoja, ja niin te olette lisänneet Israelin syyllisyyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Mutta antakaa nyt Herralle, isienne Jumalalle, kunnia ja tehkää hänen tahtonsa: eristäytykää maan kansoista ja muukalaisista vaimoista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Koko seurakunta vastasi ja sanoi suurella äänellä: \"Niin kuin sinä olet puhunut, niin on meidän tehtävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Mutta kansaa on paljon, ja on sadeaika, niin ettei voi seistä ulkona. Eikä tämä ole yhden tai kahden päivän toimitus, sillä olemme paljon siinä asiassa rikkoneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Käykööt päämiehemme esiin koko seurakunnan puolesta, ja kaikki, jotka kaupungeissamme ovat ottaneet muukalaisia vaimoja, tulkoot tänne määrättyinä aikoina ja heidän kanssaan kunkin kaupungin vanhimmat ja tuomarit, kunnes meistä on käännetty pois Jumalan viha, joka on syttynyt tämän asian tähden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Ainoastaan Joonatan, Asaelin poika, ja Jahseja, Tikvan poika, nousivat tätä vastustamaan, ja Mesullam ja leeviläinen Sabbetai kannattivat heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Mutta karkotetut tekivät näin, ja valittiin pappi Esra sekä miehiä, perhekuntien päämiehiä perhekuntien mukaan, kaikki nimeltään mainittuja. Kymmenennen kuun ensimmäisenä päivänä he istuivat tutkimaan asiaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'ja ensimmäisen kuun ensimmäiseen päivään he olivat selvillä kaikista miehistä, jotka olivat ottaneet muukalaisia vaimoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Pappien poikia, jotka olivat ottaneet muukalaisia vaimoja, havaittiin olevan: Jeesuan, Joosadakin pojan, jälkeläisiä ja hänen veljiään, Maaseja, Elieser, Jaarib ja Gedalja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'jotka kättä lyöden lupasivat toimittaa pois vaimonsa ja syyllisinä uhrata pässin syyllisyytensä sovittamiseksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Immerin jälkeläisiä Hanani ja Sebadja;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'Haarimin jälkeläisiä Maaseja, Elia, Semaja, Jehiel ja Ussia;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'Pashurin jälkeläisiä Eljoenai, Maaseja, Ismael, Netanel, Joosabad ja Elasa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Leeviläisiä: Joosabad, Siimei, Kelaja, se on Kelita, Petahja, Juuda ja Elieser.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Veisaajia: Eljasib. Ovenvartijoita: Sallum, Telem ja Uuri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Israelilaisia: Paroksen jälkeläisiä Ramja, Jissia, Malkia, Miijamin, Elasar, Malkia ja Benaja;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'Eelamin jälkeläisiä Mattanja, Sakarja, Jehiel, Abdi, Jeremot ja Elia;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'Sattun jälkeläisiä Eljoenai, Eljasib, Mattanja, Jeremot, Saabad ja Asisa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'Beebain jälkeläisiä Joohanan, Hananja, Sabbai ja Atlai;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'Baanin jälkeläisiä Mesullam, Malluk, Adaja, Jaasub, Seal ja Jeramot;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'Pahat-Mooabin jälkeläisiä Adna, Kelal, Benaja, Maaseja, Mattanja, Besalel, Binnui ja Manasse;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'Haarimin jälkeläisiä Elieser, Jissia, Malkia, Semaja, Simeon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamin, Malluk ja Semarja;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Haasumin jälkeläisiä Mattenai, Mattatta, Saabad, Elifelet, Jeremai, Manasse ja Siimei;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Baanin jälkeläisiä Maadai, Amram, Uuel,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaja, Beedja, Keluhu,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Vanja, Meremot, Eljasib,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Mattanja, Mattenai, Jaasai,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Baani, Binnui, Siimei,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Selemja, Naatan, Adaja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Maknadbai, Saasai, Saarai,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Asarel, Selemja, Semarja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Sallum, Amarja ja Joosef;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'Nebon jälkeläisiä Jegiel, Mattitja, Saabad, Sebina, Jaddai, Jooel ja Benaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Nämä kaikki olivat ottaneet muukalaisia vaimoja; ja osa näistä vaimoista oli synnyttänyt lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Nehemian, Hakaljan pojan, kertomus. Kislev-kuussa kahdentenakymmenentenä vuotena ollessani Suusanin linnassa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'tuli Hanani, eräs veljistäni, ja muita miehiä Juudasta. Minä kyselin heiltä juutalaisista, siitä pelastuneesta joukosta, joka vankeudesta palanneena oli jäljellä, ja Jerusalemista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'He sanoivat minulle: \"Ne, jotka vankeudesta palanneina ovat jäljellä siinä maakunnassa, ovat suuressa kurjuudessa ja häväistyksen alaisina. Lisäksi Jerusalemin muuri on revitty maahan, ja sen portit on tulella poltettu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Kuultuani nämä sanat istuin monta päivää itkien ja murehtien, ja paastosin ja rukoilin taivaan Jumalan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'Sanoin: \"Oi Herra, taivaan Jumala, sinä suuri ja pelättävä Jumala, joka pidät liiton ja säilytät laupeuden niille, jotka sinua rakastavat ja noudattavat käskyjäsi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'olkoon korvasi tarkkaavainen ja silmäsi avoin kuullaksesi palvelijasi rukoukset, joita minä nyt päivät ja yöt rukoilen edessäsi palvelijoidesi, israelilaisten, puolesta tunnustaen israelilaisten synnit, jotka olemme tehneet sinua vastaan. Sillä minäkin ja perhekuntani olemme syntiä tehneet!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Olemme tehneet pahoin sinua vastaan. Emme ole noudattaneet käskyjä, säädöksiä ja oikeuksia, jotka säädit palvelijallesi Moosekselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Muista sana, jonka säädit palvelijallesi Moosekselle, sanoen: \'Jos te tulette uskottomiksi, niin minä hajotan teidät kansojen sekaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'mutta jos te palaatte luokseni, noudatatte käskyjäni ja seuraatte niitä, niin vaikka karkotettunne olisivat taivaan ääressä, sieltäkin kokoan heidät ja tuon heidät siihen paikkaan, jonka olen valinnut nimeni asuinsijaksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Ovathan he palvelijasi ja kansasi, jotka vapahdit suurella voimallasi ja väkevällä kädelläsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Oi Herra, tarkatkoon korvasi palvelijasi rukousta ja niiden palvelijoittesi rukousta, jotka tahtovat pelätä nimeäsi! Anna tänä päivänä palvelijasi hankkeen menestyä ja suo hänen saada armo sen miehen edessä.\" Minä olin näet kuninkaan juomanlaskija.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Niisan-kuussa, kuningas Artahsastan kahdentenakymmenentenä hallitusvuotena, kun viini oli hänen edessään, minä otin viinin ja annoin kuninkaalle. Kun en ollut ennen ollut hänen edessään murheellisena,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'kuningas sanoi minulle: \"Miksi olet niin murheellisen näköinen? Ethän vain ole sairas, sinulla on varmaan jokin sydämen suru.\" Silloin pelästyin kovin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'mutta sanoin kuninkaalle: \"Eläköön kuningas ikuisesti. Kuinka en olisi murheellisen näköinen, kun kaupunki, jossa isieni haudat ovat, on autio ja sen portit on tulella poltettu?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Kuningas sanoi minulle: \"Mitä sinä siis pyydät?\" Rukoilin taivaan Jumalaa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'ja sanoin kuninkaalle: \"Jos kuningas hyväksi näkee ja jos olet mieltynyt palvelijaasi, lähetä minut Juudaan, siihen kaupunkiin, jossa isieni haudat ovat, se jälleenrakentamaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Kuningas kysyi minulta kuningattaren istuessa hänen vieressään: \"Kuinka kauan matkasi kestäisi ja milloin voisit palata?\" Kun siis kuningas näki hyväksi lähettää minut, ilmoitin hänelle määräajan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Sanoin kuninkaalle: \"Jos kuningas hyväksi näkee, niin annettakoon mukaani kirjeet Eufrat-virran tuonpuoleisen maan käskynhaltijoille, että he sallivat minun kulkea sen kautta perille Juudaan asti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'samoin kirje Aasafille, kuninkaan puiston vartijalle, että hän antaa minulle hirsiä temppelilinnan porttien kattamista varten sekä kaupungin muuria ja sitä taloa varten, johon menen asumaan.\" Silloin kuningas myönsi minulle sen, koska Jumalani hyvä käsi oli päälläni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Kun tulin Eufrat-virran tämänpuoleisen maan käskynhaltijoiden luo, annoin heille kuninkaan kirjeet. Kuningas oli lähettänyt kanssani sotapäälliköitä ja ratsumiehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Mutta kun hooronilainen Sanballat ja ammonilainen virkamies Tobia sen kuulivat, he pahastuivat kovin siitä, että oli tullut joku, joka toimi israelilaisten parhaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Tultuani sitten Jerusalemiin ja oltuani siellä kolme päivää');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'nousin yöllä ja muutamat miehet kanssani ilmoittamatta kenellekään, mitä Jumalani oli pannut sydämeeni ja määrännyt tehtäväksi Jerusalemille. Eikä minulla ollut mukanani muuta juhtaakaan kuin se juhta, jolla ratsastin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Lähdin yöllä Laaksoportista Lohikäärmelähteelle päin ja Lantaportille ja tarkastelin Jerusalemin maahan revittyjä muureja ja sen tulella poltettuja portteja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Kuljin eteenpäin Lähdeportille ja Kuninkaanlammikolle, mutta siellä ei ollut juhdalla, jonka selässä istuin, tilaa päästä eteenpäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Menin yöllä laaksoa myöten ylöspäin ja tarkastin muuria. Sitten palasin taas Laaksoportin kautta ja tulin takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Mutta esimiehet eivät tietäneet, mihin olin mennyt ja mitä tein, sillä en ollut vielä ilmaissut mitään kenellekään, en juutalaisille, en papeille, ylimyksille, esimiehille enkä muille, joiden oli oltava mukana siinä työssä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Mutta nyt sanoin heille: \"Te näette, missä kurjuudessa olemme, kun Jerusalem on autio ja sen portit tulella poltetut. Tulkaa, rakentakaamme uudestaan Jerusalemin muuri, ettemme olisi enää häväistyksen alaisia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Sitten kerroin heille, kuinka minun Jumalani hyvä käsi oli ollut päälläni ja myös mitä kuningas oli minulle sanonut. He sanoivat: \"Nouskaamme ja rakentakaamme.\" Niin he saivat rohkeuden käydä käsiksi tähän hyvään työhön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Mutta kun hooronilainen Sanballat ja ammonilainen virkamies Tobia ja arabialainen Gesem sen kuulivat, he pilkkasivat meitä, osoittivat meille halveksumistaan ja sanoivat: \"Mitä te siinä teette? Kapinoitteko te kuningasta vastaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Vastasin ja sanoin heille: \"Taivaan Jumala on antava meille menestystä, ja me, hänen palvelijansa, nousemme ja rakennamme. Mutta teillä ei ole mitään osuutta eikä oikeutta Jerusalemiin, eikä muistonne ole siellä pysyvä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Ylipappi Eljasib ja hänen veljensä, papit, nousivat ja rakensivat Lammasportin, jonka he pyhittivät ja jonka ovet he asettivat paikoilleen, edelleen Hammea-torniin asti, jonka he pyhittivät, ja edelleen Hananelin-torniin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Heistä eteenpäin rakensivat Jerikon miehet, ja näistä eteenpäin rakensi Sakkur, Imrin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Kalaportin rakensivat senaalaiset. He kattoivat sen ja asettivat paikoilleen sen ovet, teljet ja salvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Heistä eteenpäin korjasi muuria Meremot, Uurian poika, joka oli Koosin poika. Hänestä eteenpäin korjasi Mesullam, Berekjan poika, joka oli Mesesabelin poika, ja hänestä eteenpäin korjasi Saadok, Baanan poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Hänestä eteenpäin korjasivat muuria tekoalaiset, mutta heidän ylhäisensä eivät notkistaneet niskaansa Herransa palvelukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Vanhan portin korjasivat Joojada, Paaseahin poika, ja Mesullam, Besodjan poika. He kattoivat sen ja asettivat paikoilleen sen ovet, teljet ja salvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Heistä eteenpäin korjasivat muuria gibeonilainen Melatja ja meeronotilainen Jaadon sekä Gibeonin ja Mispan miehet, jotka olivat Eufrat-virran tämänpuoleisen käskynhaltijan vallan alaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Heistä eteenpäin korjasi muuria Ussiel, Harhajan poika, yksi kultasepistä, ja hänestä eteenpäin korjasi Hananja, yksi voiteensekoittajista. He panivat kuntoon Jerusalemia Leveään muuriin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Heistä eteenpäin korjasi muuria Refaja, Huurin poika, Jerusalemin piirin toisen puolen päällikkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Hänestä eteenpäin korjasi Jedaja, Harumafin poika, oman talonsa kohdalta. Hänestä eteenpäin korjasi Hattus, Hasabnejan poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Toisen osan korjasivat Malkia, Haarimin poika, ja Hassub, Pahat-Mooabin poika, sekä sen lisäksi Uunitornin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Heistä eteenpäin korjasi Sallum, Looheksen poika, Jerusalemin piirin toisen puolen päällikkö, hän ja hänen tyttärensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Laaksoportin korjasivat Haanun ja Saanoahin asukkaat. He rakensivat sen ja asettivat paikoilleen sen ovet, teljet ja salvat. Sen lisäksi he korjasivat tuhat kyynärää muuria Lantaporttiin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Lantaportin korjasi Malkia, Reekabin poika, Beet-Keremin piirin päällikkö. Hän rakensi sen ja asetti paikoilleen sen ovet, teljet ja salvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Lähdeportin korjasi Sallum, Kolhoosen poika, Mispan piirin päällikkö. Hän rakensi sen, teki siihen katon ja asetti paikoilleen sen ovet, teljet ja salvat. Sen lisäksi hän korjasi Vesijohtolammikon muurin kuninkaan puutarhan luota aina niihin portaisiin saakka, jotka laskeutuvat Daavidin kaupungista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Hänen jälkeensä korjasi Nehemia, Asbukin poika, Beet-Suurin piirin toisen puolen päällikkö, aina Daavidin hautojen kohdalle ja Tekolammikolle ja Sankarien talolle saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Hänen jälkeensä korjasivat muuria leeviläiset: Rehum, Baanin poika. Hänestä eteenpäin korjasi Hasabja, Kegilan piirin toisen puolen päällikkö, piirinsä puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Hänen jälkeensä korjasivat heidän veljensä: Bavvai, Heenadadin poika, joka oli Kegilan piirin toisen puolen päällikkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Hänestä eteenpäin korjasi Eeser, Jeesuan poika, Mispan päällikkö, toisen osan siltä kohdalta, mistä noustaan asehuoneeseen, joka on Kulmauksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Hänen jälkeensä korjasi Baaruk, Sabbain poika, suurella innolla toisen osan Kulmauksesta aina ylipappi Eljasibin talon oveen saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Hänen jälkeensä korjasi Meremot, Uurian poika, joka oli Koosin poika, toisen osan Eljasibin talon ovesta Eljasibin talon päähän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Hänen jälkeensä korjasivat papit, Lakeuden miehet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Heidän jälkeensä korjasivat Benjamin ja Hassub oman talonsa kohdalta. Heidän jälkeensä korjasi Asarja, Maasejan poika, joka oli Ananjan poika, talonsa viereltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Hänen jälkeensä korjasi Binnui, Heenadadin poika, toisen osan Asarjan talosta aina Kulmaukseen ja kulmaan saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Paalal, Uusain poika, korjasi Kulmauksen ja Ylätornin kohdalta, joka ulkonee kuninkaan linnasta vankilan pihaan päin. Hänen jälkeensä Pedaja, Paroksen poika');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, '– temppelipalvelijat asuivat Oofelilla ja korjasivat itäisen Vesiportin ja ulkonevan tornin kohdalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Hänen jälkeensä korjasivat tekoalaiset toisen osan, suuren, ulkonevan tornin kohdalta aina Oofelin muuriin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Hevosportin yläpuolelta korjasivat papit, kukin oman talonsa kohdalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Heidän jälkeensä korjasi Saadok, Immerin poika, oman talonsa kohdalta. Hänen jälkeensä korjasi Semaja, Sekanjan poika, Itäportin vartija.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Hänen jälkeensä korjasivat Hananja, Selemjan poika, ja Haanun, Saalafin kuudes poika, toisen osan. Hänen jälkeensä korjasi Mesullam, Berekjan poika, ullakkohuoneensa kohdalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Hänen jälkeensä korjasi Malkia, yksi kultasepistä, temppelipalvelijoiden ja kauppiaiden taloon asti, Vartiotornin kohdalta, ja aina Kulmasaliin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'Kultasepät ja kauppiaat korjasivat muurin Kulmasalin ja Lammasportin väliltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 33, 'Kun Sanballat kuuli meidän rakentavan muuria, hän vihastui ja närkästyi kovin. Hän pilkkasi juutalaisia');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 34, 'ja puhui veljilleen ja Samarian sotaväelle ja sanoi: \"Mitä nuo viheliäiset juutalaiset tekevät? Jätetäänkö heidät omiin valtoihinsa? Tulevatko he uhraamaan? Saavatko he työnsä kohta valmiiksi? Voivatko he tehdä eläviksi poltetut kivet tuhkaläjissä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 35, 'Ammonilainen Tobia seisoi hänen vieressään ja sanoi: \"Rakentakoot vain! Kettukin saa heidän kivimuurinsa hajoamaan, jos hyppää sen päälle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 36, 'Kuule, Jumalamme, kuinka halveksittuja olemme! Käännä heidän häpäisynsä heidän omaan päähänsä! Saata heidät ryöstetyiksi vankeuden maassa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 37, 'Älä peitä heidän rikostaan, älköönkä heidän syntiään pyyhittäkö pois kasvojesi edestä, koska he ovat vihoittaneet sinut kohtelemalla noin rakentajia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 38, 'Mutta rakensimme muuria, ja koko muuri tuli valmiiksi puoleen korkeuteensa asti, ja siitä kansa sai rohkeutta työhön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Tapahtui, kun Sanballat, Tobia, arabialaiset, ammonilaiset ja asdodilaiset kuulivat, että Jerusalemin muurien korjaus edistyi, niin että niiden aukot alkoivat täyttyä, he vihastuivat suuresti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'He tekivät kaikki liiton keskenään käydäkseen taisteluun Jerusalemia vastaan ja tehdäkseen siellä häiriötä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Rukoilimme Jumalaamme ja asetimme vartijat heitä vastaan suojelemaan itseämme heiltä päivin ja öin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Juuda sanoi: \"Taakankantajien voima raukeaa, ja soraa on hyvin paljon. Emme jaksa rakentaa muuria.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Vastustajamme taas sanoivat: \"Ennen kuin he tietävät tai huomaavat, tulemme heidän keskelleen ja tapamme heidät ja lopetamme työn.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Mutta kun heidän läheisyydessään asuvat juutalaiset tulivat ja sanoivat meille joka taholta kymmenenkin kertaa: \"Vetäytykää luoksemme\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'silloin asetin kansan muurin taakse, alempiin ja suojattomiin paikkoihin, asetin heidät sukukunnittain asemiinsa miekkoineen, keihäineen ja jousineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Katsastettuani kaiken nousin ja sanoin ylimyksille ja esimiehille ja muulle kansalle: \"Älkää pelätkö heitä. Muistakaa suurta ja pelättävää Herraa, ja taistelkaa veljienne, poikienne ja tyttärienne, vaimojenne ja kotienne puolesta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Sitten kun vihollisemme olivat kuulleet, että olimme saaneet tietää asian ja että Jumala oli tehnyt heidän hankkeensa tyhjäksi, palasimme kaikki takaisin muurille, itse kukin työhönsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Siitä päivästä alkaen teki toinen puoli palvelijoistani työtä, ja toinen puoli oli aseistettuna keihäin, kilvin, jousin ja rintahaarniskoin. Päämiehet seisoivat kaikkien niiden juutalaisten takana,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'jotka rakensivat muurilla. Nekin, jotka kantoivat taakkoja ja kuljettivat kuormia, tekivät toisella kädellään työtä ja toisessa pitivät keihästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Rakentajilla oli kullakin miekka sidottuna vyölleen heidän rakentaessaan, ja torvensoittaja seisoi vieressäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Sanoin ylimyksille, esimiehille ja muulle kansalle: \"Työ on suuri ja laaja, mutta me olemme muurilla hajallamme, kaukana toisistamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Missä kuulette torven soivan, kokoontukaa sinne luoksemme. Jumalamme sotii puolestamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Näin siis teimme työtä, ja toinen puoli väkeä oli aseistettuna keihäin päivänkoitosta siihen asti, kunnes tähdet tulivat näkyviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Siihen aikaan myös sanoin kansalle: \"Kukin jääköön palvelijoineen yöksi Jerusalemiin, että he olisivat apunamme yöllä vartioimassa ja päivällä työssä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Emmekä me, en minä, eivät veljeni ja palvelijani eivätkä ne vartijat, jotka minua seurasivat, riisuneet vaatteitamme. Kullakin oli keihäs ja vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Kansa ja heidän vaimonsa nostivat suuren metelin juutalaisia veljiään vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Muutamat sanoivat: \"Meitä, poikiamme ja tyttäriämme on paljon. Meidän täytyy saada viljaa, että meillä olisi mitä syödä pysyäksemme hengissä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Toiset sanoivat: \"Peltomme, viinitarhamme ja talomme meidän täytyy pantata saadaksemme viljaa nälkäämme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Toiset sanoivat: \"Meidän on täytynyt lainata kuninkaan veroihin rahaa peltojamme ja viinitarhojamme vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Ovathan meidän ruumiimme veljiemme ruumiitten veroisia ja lapsemme heidän lastensa veroisia, ja katso, kuitenkin meidän täytyy antaa poikamme ja tyttäremme orjiksi. Tyttäriämme onkin jo annettu orjuuteen, emmekä voi sille mitään, koska peltomme ja viinitarhamme ovat toisten käsissä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Kun kuulin heidän valituksensa ja nämä puheet, vihastuin kovin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Harkittuani mielessäni tätä asiaa nuhtelin ylimyksiä ja esimiehiä ja sanoin heille: \"Tehän kiskotte kukin veljeltänne korkoa.\" Panin toimeen suuren kokouksen heitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'Sanoin heille: \"Me olemme, sen mukaan kuin olemme voineet, ostaneet vapaiksi juutalaisia veljiämme, joita oli myyty pakanoille. Tekö nyt myytte veljiänne, ja täytyykö heidän myydä itsensä meille?\" He olivat vaiti eivätkä voineet vastata mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Sanoin: \"Ette tee siinä hyvin. Teidänhän tulisi vaeltaa Jumalamme pelossa jo pakanoiden, vihollistemme, häväistyksen tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Myös me, minä, veljeni ja palvelijani, olemme lainanneet heille rahaa ja viljaa. Luopukaamme tästä saatavasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Luovuttakaa heille jo tänä päivänä heidän peltonsa, viinitarhansa, öljypuunsa ja talonsa, ja luopukaa rahan korosta sekä viljasta, viinistä ja öljystä, jonka olette heille lainanneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'He vastasivat: \"Luovutamme ne emmekä vaadi heiltä mitään. Teemme, kuten olet sanonut.\" Sitten minä kutsuin papit ja vannotin heidät tekemään näin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Minä myös pudistin liepeeni ja sanoin: \"Jokaisen, joka ei tätä sanaa täytä, pudistakoon Jumala näin pois hänen talostaan ja vaivannäkönsä hedelmistä. Hän tulkoon tällä tavalla pudistetuksi ja tyhjennetyksi.\" Koko seurakunta sanoi: \"Aamen\", ja ylisti Herraa. Kansa teki, kuten oli sanottu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Myöskään en minä eivätkä veljeni siitä päivästä asti, jona minut määrättiin olemaan heidän käskynhaltijanaan Juudan maassa, siis kuningas Artahsastan kahdennestakymmenennestä hallitusvuodesta aina hänen kolmanteenkymmenenteen toiseen hallitusvuoteensa saakka eli kahtenatoista vuotena, emme syöneet käskynhaltijalle tulevaa ruokaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Sillä aikaisemmat käskynhaltijat, jotka olivat olleet ennen minua, olivat rasittaneet kansaa ja ottaneet siltä leipää ja viiniä sekä vielä neljäkymmentä hopeasekeliä. Heidän palvelijansakin olivat sortaneet kansaa. Mutta minä en tehnyt niin, sillä pelkäsin Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Jatkoin myös tämän muurin tekemistä, emmekä ostaneet mitään peltoa. Kaikki palvelijani olivat kokoontuneet sinne työhön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Myös sata viisikymmentä miestä, juutalaisia ja esimiehiä, söi pöydässäni sekä ne, jotka ympärillämme olevista pakanakansoista tulivat luoksemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Se, mitä päivittäin valmistettiin ruuaksi, nimittäin härkä ja kuusi valiolammasta sekä lintuja, valmistettiin kustannuksellani, ja joka kymmenes päivä hankittiin runsaasti kaikenlaisia viinejä. Mutta siitä huolimatta en vaatinut itselleni käskynhaltijalle tulevaa ruokaa, koska työ painoi raskaasti tätä kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Muista, Jumalani, hyväkseni kaikki, mitä olen tehnyt tämän kansan puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Kun Sanballat, Tobia, arabialainen Gesem ja meidän muut vihollisemme kuulivat, että olin rakentanut muurin ja ettei siinä enää ollut aukkoa – vaikken ollutkaan vielä siihen aikaan asettanut ovia paikoilleen portteihin –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'niin Sanballat ja Gesem lähettivät minulle sanan: \"Tule, kohdatkaamme toisemme Kefirimissä, Oonon laaksossa.\" He näet ajattelivat tehdä minulle pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Lähetin heidän luokseen sanansaattajat ja käskin sanoa: \"Minulla on tekeillä suuri työ, niin etten voi tulla. Keskeytyisihän työ, jos jättäisin sen ja tulisin luoksenne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'He lähettivät minulle saman sanan neljä kertaa, mutta vastasin heille aina samalla tavalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Sanballat lähetti viidennen kerran palvelijansa minun luokseni samassa asiassa, ja tällä oli kädessään avoin kirje.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Siihen oli kirjoitettu: \"Kansojen kesken huhuillaan, ja myös Gasmu sanoo, että sinä ja juutalaiset suunnittelette kapinaa. Sen tähden sinä rakennat muuria, ja itse sinä pyrit heidän kuninkaakseen – niin kerrotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Olet hankkinut myös profeettoja julistamaan itsestäsi Jerusalemissa näin: \'Juudassa on kuningas.\' Tämän nyt kuningas saa kuulla. Tule siis ja neuvotelkaamme keskenämme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Lähetin hänelle sanan: \"Ei ole tapahtunut mitään sellaista, mistä puhut, vaan olet keksinyt sen omasta päästäsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'He näet kaikki pelottelivat meitä arvellen: \"Heidän kätensä herpoavat työstä, ja se jää tekemättä.\" Mutta vahvista sinä käteni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Minä menin Semajan, Delajan pojan, Mehetabelin pojanpojan, taloon, hänen ollessaan eristettynä. Hän sanoi: \"Menkäämme yhdessä Jumalan temppeliin, temppelisaliin, ja sulkekaamme temppelisalin ovet. Sillä he tulevat tappamaan sinua. He tulevat yöllä ja tappavat sinut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Mutta vastasin: \"Pakenisiko minunlaiseni mies? Tai kuinka voisi minunlaiseni mies mennä temppeliin ja kuitenkin jäädä eloon? En mene.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Ymmärsin näet, ettei Jumala ollut häntä lähettänyt, vaan että hän oli lausunut minulle ennustuksen siitä syystä, että Tobia ja Sanballat olivat palkanneet hänet:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Hänet oli palkattu siinä tarkoituksessa, että pelästyisin ja menettelisin sillä tavalla ja niin tekisin syntiä. Siitä he saisivat panettelun aiheen häväistäkseen minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Muista, Jumalani, Tobiaa ja Sanballatia näiden heidän tekojensa mukaan, niin myös naisprofeetta Nooadjaa ja muita profeettoja, jotka minua pelottelivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Muuri valmistui elul-kuun kahdentenakymmenentenä viidentenä päivänä viidenkymmenen kahden päivän kuluttua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Kun kaikki vihollisemme sen kuulivat, ja kaikki ympärillämme asuvat kansat näkivät sen, he havaitsivat joutuneensa aivan alakynteen. Sillä he tunsivat, että tämä työ oli suoritettu Jumalamme avulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Niinä päivinä meni myös Juudan ylimyksiltä lukuisia kirjeitä Tobialle, ja Tobialta tuli kirjeitä heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Sillä Juudassa oli monta, jotka olivat valalla liittoutuneet hänen kanssaan. Hän näet oli Sekanjan, Aarahin pojan, vävy, ja hänen poikansa Joohanan oli ottanut vaimokseen Mesullamin, Berekjan pojan, tyttären.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'He myös puhuivat minulle hyvää hänestä ja veivät puheeni hänelle. Kirjeitäkin Tobia lähetti pelotellakseen minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Kun muuri oli rakennettu, asetin ovet paikoilleen. Niiden vartioimisen saivat tehtäväkseen ovenvartijat, veisaajat ja leeviläiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Jerusalemin päämiehiksi asetin veljeni Hananin ja linnanpäällikön Hananjan, sillä hän oli luotettava mies ja pelkäsi Jumalaa enemmän kuin moni muu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'Sanoin heille: \"Jerusalemin portteja älköön avattako, ennen kuin aurinko on polttavimmillaan. Ovet on suljettava ja salvoilla teljettävä vartijoiden vielä seisoessa paikoillaan. Jerusalemin asukkaita pantakoon vartioimaan, kukin vartiopaikalleen, kukin oman talonsa kohdalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Kaupunki oli joka suuntaan tilava ja suuri, mutta väkeä siinä oli vähän, ja taloja oli vielä rakentamatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Jumala pani sydämeeni, että minun oli koottava ylimykset, esimiehet ja kansa sukuluetteloon merkittäviksi. Silloin löysin niiden sukuluettelon, jotka ensin olivat tulleet sinne, ja huomasin siihen kirjoitetun:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Nämä ovat tämän maakunnan asukkaat, jotka lähtivät karkotettujen vankeudesta, johon Nebukadnessar, Baabelin kuningas, oli heidät vienyt, ja palasivat Jerusalemiin ja Juudaan, kukin kaupunkiinsa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'ne, jotka tulivat Serubbaabelin, Jeesuan, Nehemian, Asarjan, Raamian, Nahamanin, Mordokain, Bilsanin, Misperetin, Bigvain, Nehumin ja Baanan kanssa. Israelin kansan miesten lukumäärä oli:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Paroksen jälkeläisiä kaksituhatta sata seitsemänkymmentä kaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Sefatjan jälkeläisiä kolmesataa seitsemänkymmentä kaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Aarahin jälkeläisiä kuusisataa viisikymmentä kaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'Pahat-Mooabin jälkeläisiä, nimittäin Jeesuan ja Jooabin jälkeläisiä, kaksituhatta kahdeksansataa kahdeksantoista;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Eelamin jälkeläisiä tuhat kaksisataa viisikymmentä neljä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Sattun jälkeläisiä kahdeksansataa neljäkymmentä viisi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Sakkain jälkeläisiä seitsemänsataa kuusikymmentä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Binnuin jälkeläisiä kuusisataa neljäkymmentä kahdeksan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Beebain jälkeläisiä kuusisataa kaksikymmentä kahdeksan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Asgadin jälkeläisiä kaksituhatta kolmesataa kaksikymmentä kaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Adonikamin jälkeläisiä kuusisataa kuusikymmentä seitsemän;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Bigvain jälkeläisiä kaksituhatta kuusikymmentä seitsemän;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'Aadinin jälkeläisiä kuusisataa viisikymmentä viisi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Aaterin, nimittäin Hiskian, jälkeläisiä yhdeksänkymmentä kahdeksan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Haasumin jälkeläisiä kolmesataa kaksikymmentä kahdeksan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Beesain jälkeläisiä kolmesataa kaksikymmentä neljä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Haarifin jälkeläisiä sata kaksitoista;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'gibeonilaisia yhdeksänkymmentä viisi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'Beetlehemin ja Netofan miehiä sata kahdeksankymmentä kahdeksan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Anatotin miehiä sata kaksikymmentä kahdeksan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'Beet-Asmavetin miehiä neljäkymmentä kaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'Kirjat-Jearimin, Kefiran ja Beerotin miehiä seitsemänsataa neljäkymmentä kolme;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'Raaman ja Geban miehiä kuusisataa kaksikymmentä yksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'Mikmaan miehiä sata kaksikymmentä kaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'Beetelin ja Ain miehiä sata kaksikymmentä kolme;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'toisen Nebon miehiä viisikymmentä kaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'toisen Eelamin jälkeläisiä tuhat kaksisataa viisikymmentä neljä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Haarimin jälkeläisiä kolmesataa kaksikymmentä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'jerikolaisia kolmesataa neljäkymmentä viisi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'loodilaisia, haadidilaisia ja oonolaisia seitsemänsataa kaksikymmentä yksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'senaalaisia kolmetuhatta yhdeksänsataa kolmekymmentä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Pappeja oli: Jedajan jälkeläisiä, nimittäin Jeesuan sukua, yhdeksänsataa seitsemänkymmentä kolme;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Immerin jälkeläisiä tuhat viisikymmentä kaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Pashurin jälkeläisiä tuhat kaksisataa neljäkymmentä seitsemän;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Haarimin jälkeläisiä tuhat seitsemäntoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Leeviläisiä oli: Jeesuan ja Kadmielin jälkeläisiä, nimittäin Hoodevan jälkeläisiä, seitsemänkymmentä neljä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Veisaajia oli: Aasafin jälkeläisiä sata neljäkymmentä kahdeksan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Ovenvartijoita oli: Sallumin jälkeläisiä, Aaterin jälkeläisiä, Talmonin jälkeläisiä, Akkubin jälkeläisiä, Hatitan jälkeläisiä, Soobain jälkeläisiä sata kolmekymmentä kahdeksan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Temppelipalvelijoita oli: Siihan jälkeläiset, Hasufan jälkeläiset, Tabbaotin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'Keeroksen jälkeläiset, Siian jälkeläiset, Paadonin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'Lebanan jälkeläiset, Hagaban jälkeläiset, Salmain jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'Haananin jälkeläiset, Giddelin jälkeläiset, Gaharin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'Reajan jälkeläiset, Resinin jälkeläiset, Nekodan jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'Gassamin jälkeläiset, Ussan jälkeläiset, Paaseahin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'Beesain jälkeläiset, Meunimin jälkeläiset, Nefusesimin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'Bakbukin jälkeläiset, Hakufan jälkeläiset, Harhurin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'Baslutin jälkeläiset, Mehidan jälkeläiset, Harsan jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'Barkoksen jälkeläiset, Siiseran jälkeläiset, Taamahin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'Nesiahin jälkeläiset, Hatifan jälkeläiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Salomon palvelijoiden jälkeläisiä oli: Sootain jälkeläiset, Sooferetin jälkeläiset, Peridan jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'Jaalan jälkeläiset, Darkonin jälkeläiset, Giddelin jälkeläiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'Sefatjan jälkeläiset, Hattilin jälkeläiset, Kooferet-Sebaimin jälkeläiset, Aamonin jälkeläiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Temppelipalvelijoita ja Salomon palvelijoiden jälkeläisiä oli kaikkiaan kolmesataa yhdeksänkymmentä kaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Nämä taas ovat ne, jotka lähtivät Teel-Melahista, Teel-Harsasta, Kerub-Addonista ja Immeristä, voimatta ilmoittaa perhekuntaansa ja syntyperäänsä, olivatko israelilaisia:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'Delajan jälkeläiset, Tobian jälkeläiset, Nekodan jälkeläiset, kuusisataa neljäkymmentä kaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'Pappeja: Habaijan jälkeläiset, Koosin jälkeläiset, Barsillain jälkeläiset, sen, joka oli ottanut itselleen vaimon gileadilaisen Barsillain tyttäristä ja jota kutsuttiin heidän nimellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Nämä etsivät sukuluetteloitaan niitä löytämättä, ja niin heidät julistettiin pappeuteen kelpaamattomiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Maaherra kielsi heitä syömästä korkeasti pyhää, ennen kuin nousisi pappi, joka voi käyttää uurimia ja tummimia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Koko seurakunta yhteenlaskettuna oli neljäkymmentäkaksi tuhatta kolmesataa kuusikymmentä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'paitsi heidän palvelijoitaan ja palvelijattariaan, joita oli seitsemäntuhatta kolmesataa kolmekymmentä seitsemän. Lisäksi oli heillä kaksisataa neljäkymmentä viisi mies- ja naisveisaajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Kameleja heillä oli neljäsataa kolmekymmentä viisi, aaseja kuusituhatta seitsemänsataa kaksikymmentä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'Osa perhekuntien päämiehistä antoi lahjoja rakennustyötä varten. Maaherra antoi rahastoon tuhat dareikkia kultaa, viisikymmentä maljaa ja viisisataa kolmekymmentä papin paitaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Muutamat perhekuntien päämiehistä antoivat rakennusrahastoon kaksikymmentä tuhatta dareikkia kultaa ja kaksituhatta kaksisataa miinaa hopeaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Muu kansa antoi yhteensä kaksikymmentä tuhatta dareikkia kultaa ja kaksituhatta miinaa hopeaa sekä kuusikymmentä seitsemän papin paitaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Papit, leeviläiset, ovenvartijat, veisaajat ja osa kansasta sekä temppelipalvelijat, koko Israel, asettuivat kaupunkeihinsa. Niin tuli seitsemäs kuukausi, ja israelilaiset olivat jo kaupungeissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, '');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Kaikki kansa kokoontui yhtenä miehenä Vesiportin edustalla olevalle aukiolle, ja he pyysivät Esraa, kirjanoppinutta, tuomaan Mooseksen lain kirjan, jonka Herra oli säätänyt Israelille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Pappi Esra toi lain seurakunnan eteen, sekä miesten että naisten, kaikkien, jotka voivat ymmärtää, mitä kuulivat. Tämä tapahtui seitsemännen kuun ensimmäisenä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Hän luki sitä Vesiportin edustalla olevalla aukiolla päivän koitosta puoleenpäivään asti miehille ja naisille, niille, jotka voivat sitä ymmärtää, kaiken kansan kuunnellessa lain kirjan lukemista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Esra, kirjanoppinut, seisoi korkealla puisella lavalla, joka oli tätä varten tehty. Hänen vieressään seisoivat: hänen oikealla puolellaan Mattitja, Sema, Anaja, Uuria, Hilkia ja Maaseja, ja hänen vasemmalla puolellaan Pedaja, Miisael, Malkia, Haasum, Hasbaddana, Sakarja ja Mesullam.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Esra avasi kirjan kaiken kansan nähden, sillä hän seisoi ylempänä kaikkea kansaa, ja kun hän avasi sen, koko kansa nousi seisomaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Esra kiitti Herraa, suurta Jumalaa, ja kaikki kansa vastasi kohottaen kätensä ylös: \"Aamen, aamen\", ja he kumarsivat ja rukoilivat Herraa heittäytyneinä kasvoilleen maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Jeesua, Baani, Seerebja, Jaamin, Akkub, Sabbetai, Hoodia, Maaseja, Kelita, Asarja, Joosabad, Haanan, Pelaja ja muut leeviläiset opettivat kansalle lakia, kansan seisoessa alallaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'He lukivat Jumalan lain kirjaa kappale kappaleelta ja selittivät sen sisällön, niin että luettu ymmärrettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Nehemia, maaherra, ja pappi Esra, kirjanoppinut, ja leeviläiset, jotka opettivat kansaa, sanoivat kaikelle kansalle: \"Tämä päivä on pyhitetty Herralle, Jumalallenne, älkää murehtiko älkääkä itkekö.\" Sillä kaikki kansa itki, kun he kuulivat lain sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Sitten hän sanoi vielä heille: \"Menkää ja syökää rasvaisia ruokia ja juokaa makeita juomia ja lähettäkää maistiaisia niille, joilla ei ole mitään valmistettuna, sillä tämä päivä on pyhitetty Herrallemme. Älkää olko murheelliset, sillä ilo Herrassa on väkevyytenne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Leeviläiset rauhoittelivat kaikkea kansaa ja sanoivat: \"Olkaa hiljaa, sillä tämä päivä on pyhä, älkää olko murheellisia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Kaikki kansa meni, söi ja joi, lähetti maistiaisia ja vietti suurta ilojuhlaa, sillä he olivat ymmärtäneet, mitä heille oli julistettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Seuraavana päivänä kokoontuivat koko kansan perhekuntien päämiehet, papit ja leeviläiset Esran, kirjanoppineen, luo painamaan lain sanoja mieleensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'He huomasivat lakiin kirjoitetun, että Herra oli Mooseksen kautta käskenyt israelilaisia asumaan lehtimajoissa juhlan aikana seitsemännessä kuussa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'ja että kaikissa heidän kaupungeissaan ja Jerusalemissa oli julistettava ja kuulutettava näin: \"Menkää vuorille ja tuokaa öljypuun lehviä tai metsäöljypuun lehviä sekä myrtin, palmupuun ja muiden tuuheiden puiden lehviä, ja tehkää lehtimajoja, niin kuin on säädetty.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Kansa meni ja toi niitä ja teki itselleen lehtimajoja kukin katolleen ja pihoihinsa ja Jumalan temppelin esipihoihin sekä Vesiportin aukealle ja Efraimin portin aukealle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Koko seurakunta, kaikki vankeudesta palanneet, tekivät lehtimajoja ja asuivat lehtimajoissa. Sillä aina Joosuan, Nuunin pojan, ajoista siihen päivään saakka eivät israelilaiset olleet niin tehneet. Vallitsi hyvin suuri ilo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Sitten Jumalan lain kirjaa luettiin joka päivä, ensimmäisestä päivästä viimeiseen saakka. He viettivät juhlaa seitsemän päivää, ja kahdeksantena päivänä pidettiin juhlakokous säädetyllä tavalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Saman kuun kahdentenakymmenentenä neljäntenä päivänä israelilaiset kokoontuivat paastoten säkit yllään ja multaa pään päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Israelin heimo eristäytyi kaikista muukalaisista, astui esiin ja tunnusti syntinsä ja isiensä rikkomiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'He nousivat seisomaan, kukin paikallaan, ja heille luettiin Herran, heidän Jumalansa, lain kirjaa neljännes päivää. Toisen neljänneksen aikana he tunnustivat syntinsä ja kumartaen rukoilivat Herraa, Jumalaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Jeesua, Baani, Kadmiel, Sebanja, Bunni, Seerebja, Baani ja Kenani nousivat leeviläisten korokkeelle ja huusivat suurella äänellä Herraa, Jumalaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Leeviläiset Jeesua, Kadmiel, Baani, Hasabneja, Seerebja, Hoodia, Sebanja ja Petahja sanoivat: \"Nouskaa ja kiittäkää Herraa, Jumalaanne, iankaikkisesta iankaikkiseen. Kiitettäköön sinun kunniakasta nimeäsi, joka on korotettu yli kaiken kiitoksen ja ylistyksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Sinä yksin olet Herra. Sinä olet tehnyt taivaat ja taivasten taivaat kaikkine joukkoineen, maan ja kaikki, mitä siinä on, meret ja kaikki, mitä niissä on. Sinä annat elämän niille kaikille, ja taivaan joukot kumartavat sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Sinä olet Herra Jumala, joka valitsit Abramin ja veit hänet pois Kaldean Uurista ja annoit hänelle nimen Aabraham.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Havaitsit hänen sydämensä uskolliseksi itseäsi kohtaan, ja teit hänen kanssaan liiton antaaksesi hänen jälkeläisilleen kanaanilaisten, heettiläisten, amorilaisten, perissiläisten, jebusilaisten ja girgasilaisten maan. Olet täyttänyt sanasi, sillä sinä olet vanhurskas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Näit isiemme kurjuuden Egyptissä ja kuulit heidän huutonsa Kaislameren rannalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Teit tunnustekoja ja ihmeitä rangaisten faraota ja kaikkia hänen palvelijoitaan ja kaikkea hänen maansa kansaa. Sillä tiesit näiden kohdelleen heitä ylimielisesti, ja teit itsellesi nimen, niin kuin se tänäkin päivänä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Meren halkaisit heidän edessään kahtia, niin että he kulkivat kuivaa myöten meren poikki. Heidän takaa-ajajansa sinä syöksit syvyyteen, niin kuin kiven valtaviin vesiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Sinä johdatit heitä päivällä pilvenpatsaasta ja yöllä tulenpatsaasta valaisten heille tien, jota heidän oli kuljettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Sinä astuit alas Siinain vuorelle ja puhuit heille taivaasta ja annoit heille oikeat tuomiot ja totuuden mukaiset lait, hyvät säädökset ja käskyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Ilmoitit heille pyhän sapattisi ja annoit heille käskyt, säädökset ja lain palvelijasi Mooseksen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Annoit heille leipää taivaasta heidän nälkäänsä, ja hankit heille vettä kalliosta heidän janoonsa. Sinä käskit heidän mennä ottamaan omakseen maan, jonka olit kättä kohottaen luvannut heille antaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Mutta he, isämme, olivat ylimielisiä. He olivat niskureita eivätkä totelleet käskyjäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'He eivät tahtoneet totella eivätkä muistaneet ihmetekoja, jotka olit heille tehnyt, vaan olivat niskureita ja valitsivat uppiniskaisuudessaan johtajan palatakseen takaisin orjuuteensa. Mutta sinä olet anteeksiantava Jumala, armahtava ja laupias, pitkämielinen ja suuri armossa: sinä et heitä hylännyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Vaikka he tekivät itselleen valetun vasikankuvan ja sanoivat: \'Tämä on jumalasi, joka on johdattanut sinut Egyptistä\', ja vaikka he pilkkasivat paljon Jumalaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'sinä et suuressa laupeudessasi kuitenkaan hylännyt heitä erämaassa. Pilvenpatsas ei väistynyt heidän luotaan päivällä johtamasta heitä tiellä, eikä tulenpatsas yöllä valaisemasta heille tietä, jota heidän oli kuljettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Hyvän Henkesi annoit heitä opettamaan, mannaasi et kieltänyt heidän suustaan, ja vettä annoit heille heidän janoonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Neljäkymmentä vuotta sinä elätit heitä erämaassa, niin ettei heiltä puuttunut mitään. Heidän vaatteensa eivät kuluneet, eivätkä heidän jalkansa turvonneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Sinä annoit heille valtakuntia ja kansoja ja jaoit ne alue alueelta. He valloittivat Siihonin maan – Hesbonin kuninkaan maan – ja Oogin, Baasanin kuninkaan, maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Heidän lastensa luvun teit paljoksi kuin taivaan tähdet, ja veit heidät siihen maahan, josta olit antanut heidän isillensä lupauksen, että he saavat mennä ottamaan sen omakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Lapset tulivat ja ottivat maan omakseen, ja nöyryytit heidän edessään maan asukkaat, kanaanilaiset. Annoit nämä heidän käsiinsä, sekä heidän kuninkaansa että maan kansat, niin että he tekivät näille, mitä tahtoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'He valloittivat varustetut kaupungit ja lihavan maan ja ottivat omikseen talot, jotka olivat täynnä kaikkea hyvää, kallioon hakatut vesisäiliöt, viinitarhat, öljypuut ja hedelmäpuita suuret määrät. He söivät ja tulivat ravituiksi ja lihaviksi ja pitivät hyviä päiviä lahjojesi runsaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Mutta he niskoittelivat ja kapinoivat sinua vastaan, heittivät selkänsä taa lakisi ja tappoivat profeettasi, jotka heitä varoittivat palauttaakseen heidät luoksesi, ja he pilkkasivat paljon Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Sen tähden annoit heidät heidän ahdistajiensa käsiin, ja nämä ahdistivat heitä. Mutta kun he ahdinkonsa aikana huusivat sinua, niin sinä taivaasta kuulit ja suuressa laupeudessasi annoit heille vapauttajia, jotka vapauttivat heidät heidän ahdistajiensa käsistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Mutta rauhaan päästyään he jälleen tekivät sitä, mikä on pahaa edessäsi. Jätit heidät heidän vihollistensa käsiin, niin että nämä vallitsivat heitä. Mutta kun he jälleen huusivat sinua avukseen, sinä kuulit taivaasta ja pelastit heidät laupeudessasi monta kertaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Varoitit heitä palauttaaksesi heidät seuraamaan lakiasi, mutta he olivat ylimielisiä eivätkä totelleet käskyjäsi, vaan he rikkoivat oikeutesi – se ihminen, joka ne pitää, on niistä elävä – mutta he käänsivät uppiniskaisina selkänsä ja olivat niskureita eivätkä totelleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Kärsit heitä monta vuotta ja varoitit heitä Hengelläsi profeettojesi kautta, mutta he eivät ottaneet sitä korviinsa. Annoit heidät pakanallisten kansojen käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Mutta suuressa laupeudessasi et tehnyt loppua heistä etkä hylännyt heitä, sillä sinä olet armahtavainen ja laupias Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Mutta nyt, Jumalamme, sinä suuri, väkevä ja pelättävä Jumala, joka pidät liiton ja säilytät laupeuden: älä katso vähäksi kaikkea sitä vaivaa, joka on kohdannut meitä, kuninkaitamme, päämiehiämme, pappejamme, profeettojamme, isiämme ja koko kansaasi Assurin kuningasten ajoista aina tähän päivään saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Sinä olet vanhurskas kaikessa, mikä on meitä kohdannut, sillä sinä olet ollut uskollinen teoissasi, mutta me olemme olleet jumalattomat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Kuninkaamme, päämiehemme, pappimme ja isämme eivät ole seuranneet lakiasi eivätkä tarkanneet käskyjäsi ja säädöksiäsi, jotka olit heille antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Vaikka he elivät omassa valtakunnassaan ja siinä lahjojesi runsaudessa, jotka olit antanut heille, ja avarassa ja lihavassa maassa, jonka olit antanut heille, he eivät kuitenkaan palvelleet sinua eivätkä kääntyneet pois pahoista teoistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Katso, me olemme nyt orjia. Maassa, jonka isillemme annoit, jotta he söisivät sen hedelmiä ja hyvyyttä, meidän täytyy olla orjina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Sen runsas sato tulee niille kuninkaille, jotka syntiemme tähden olet pannut meitä hallitsemaan. He vallitsevat meitä ja karjaamme, niin kuin tahtovat, ja me olemme suuressa ahdistuksessa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, '\"Kaiken tämän johdosta me teemme sitoumuksen ja kirjoitamme siihen nimemme. Sinetöidyssä asiakirjassa ovat päämiestemme, leeviläistemme ja pappiemme nimet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Sinetöidyissä asiakirjoissa ovat nämä nimet: Nehemia, Hakaljan poika, maaherra, ja Sidkia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Seraja, Asarja, Jeremia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Pashur, Amarja, Malkia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Hattus, Sebanja, Malluk,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Haarim, Meremot, Obadja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Daniel, Ginneton, Baaruk,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Mesullam, Abia, Miijamin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Maasja, Bilgai ja Semaja – nämä ovat pappeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'Leeviläisiä ovat: Jeesua, Asanjan poika, Binnui, Heenadadin jälkeläinen, Kadmiel');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'ja heidän veljensä Sebanja, Hoodia, Kelita, Pelaja, Haanan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Miika, Rehob, Hasabja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Sakkur, Seerebja, Sebanja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Hoodia, Baani ja Beninu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Kansan päämiehiä ovat: Paros, Pahat-Mooab, Eelam, Sattu, Baani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Bunni, Asgad, Beebai,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Adonia, Bigvai, Aadin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Aater, Hiskia, Assur,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Hoodia, Haasum, Beesai,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Haarif, Anatot, Nuubai,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Magpias, Mesullam, Heesir,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Mesesabel, Saadok, Jaddua,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Pelatja, Haanan, Anaja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Hoosea, Hananja, Hassub,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Loohes, Pilha, Soobek,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Rehum, Hasabna, Maaseja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Ahia, Haanan, Aanan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Malluk, Haarim ja Baana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Muu kansa, papit, leeviläiset, ovenvartijat, veisaajat, temppelipalvelijat ja kaikki, jotka ovat eristäytyneet pakanallisista kansoista Jumalan lain puolelle, sekä heidän vaimonsa, poikansa ja tyttärensä, kaikki, jotka pystyvät sen ymmärtämään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'liittyvät ylhäisiin veljiinsä, tulevat valalle ja vannovat vaeltavansa Jumalan lain mukaan, joka on annettu Jumalan palvelijan Mooseksen kautta, ja noudattavansa ja seuraavansa kaikkia Herran, Herramme, käskyjä, oikeuksia ja säädöksiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'Emme anna tyttäriämme maan kansoille emmekä ota heidän tyttäriään pojillemme vaimoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Emme osta sapattina tai pyhäpäivänä maan kansoilta, jos ne tuovat kauppatavaraa tai viljaa mitä tahansa kaupaksi sapattina. Jätämme joka seitsemäntenä vuotena maan lepäämään ja kaikki saatavat velkomatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Sitoudumme suorittamaan vuodessa kolmannessekelin palvelusta varten Jumalamme temppelissä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'näkyleipiin, jokapäiväiseen ruokauhriin ja jokapäiväiseen polttouhriin, uhreihin sapatteina ja uudenkuun päivinä, juhlauhreihin ja pyhiin lahjoihin, syntiuhreihin sovituksen toimittamiseksi Israelille ja kaikkeen, mikä Jumalamme temppelissä on toimitettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Me, papit, leeviläiset ja kansa, olemme heittäneet arpaa uhrilahjapolttopuiden tuomisesta perhekunnittain Jumalamme temppeliin määräaikoina joka vuosi poltettaviksi Herran, Jumalamme, alttarilla, niin kuin laissa on kirjoitettuna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'Sitoudumme tuomaan maamme ensisadon ja kaikkien hedelmäpuiden ensisadon joka vuosi Herran temppeliin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'sekä esikoiset pojistamme ja karjastamme, niin kuin laissa on kirjoitettuna, ja tuomaan nautojemme ja lampaittemme esikoiset Jumalamme temppeliin papeille, jotka toimittavat virkaansa Jumalamme temppelissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Tuomme parhaat jyvärouheemme ja antimemme, parhaat kaikkien puiden hedelmät, parhaan viinin ja öljyn papeille, Jumalamme temppelin kammioihin, ja maamme kymmenykset leeviläisille. Leeviläiset itse kantavat kymmenykset kaikista kaupungeista, missä meillä on maanviljelystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Papin, Aaronin pojan, tulee olla leeviläisten kanssa heidän kantaessaan kymmenyksiä ja leeviläisten tulee viedä kymmenykset kymmenyksistä Jumalamme temppeliin, varastohuoneen kammioihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 40, 'Sillä israelilaisten ja leeviläisten on vietävä anti jyvistä, viinistä ja öljystä näihin kammioihin, joissa pyhäkön kalusto ja virkaansa toimittavat papit, ovenvartijat ja veisaajat ovat. Emme laiminlyö Jumalamme temppeliä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Kansan päämiehet asettuivat Jerusalemiin, mutta muu kansa heitti arpaa saadakseen joka kymmenennen asettumaan Jerusalemiin, pyhään kaupunkiin, yhdeksän kymmenesosan jäädessä asumaan muihin kaupunkeihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Kansa siunasi kaikkia miehiä, jotka vapaaehtoisesti asettuivat Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Nämä olivat ne maakunnan päämiehet, jotka asettuivat Jerusalemiin ja Juudan kaupunkeihin. He asuivat kukin perintöosallaan kaupungeissaan, Israel, papit, leeviläiset ja temppelipalvelijat sekä Salomon palvelijoiden jälkeläiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'Jerusalemissa asuivat seuraavat Juudan ja Benjamin miehet: Juudan miehistä Ataja, Ussian poika, joka oli Sakarjan poika, joka Amarjan poika, joka Sefatjan poika, joka Mahalalelin poika, Pereksen jälkeläisiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'ja Maaseja, Baarukin poika, joka oli Kolhoosen poika, joka Hasajan poika, joka Adajan poika, joka Joojaribin poika, joka Sakarjan poika, joka siilonilaisen poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Jerusalemissa asuvia Pereksen jälkeläisiä oli kaikkiaan neljäsataa kuusikymmentä kahdeksan sotakuntoista miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Benjaminilaiset olivat nämä: Sallu, Mesullamin poika, joka oli Jooedin poika, joka Pedajan poika, joka Koolajan poika, joka Maasejan poika, joka Iitielin poika, joka Jesajan poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'ja hänen jälkeensä Gabbai ja Sallai, yhdeksänsataa kaksikymmentä kahdeksan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Jooel, Sikrin poika, oli heidän päällysmiehenään ja Juuda, Senuan poika, toisena kaupunginpäällikkönä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Pappeja: Jedaja, Joojaribin poika, Jaakin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Seraja, Hilkian poika, joka oli Mesullamin poika, joka Saadokin poika, joka Merajotin poika, joka Ahitubin poika, Jumalan temppelin esimies,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'sekä heidän veljensä, jotka toimittivat palvelusta temppelissä, kahdeksansataa kaksikymmentä kaksi miestä; ja Adaja, Jerohamin poika, joka oli Pelaljan poika, joka Amsin poika, joka Sakarjan poika, joka Pashurin poika, joka Malkian poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'sekä hänen veljensä, jotka olivat perhekuntapäämiehiä, kaksisataa neljäkymmentä kaksi miestä; ja Amassai, Asarelin poika, joka oli Ahsain poika, joka Mesillemotin poika, joka Immerin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'sekä heidän veljensä, jotka olivat väkeviä sankareita, sata kaksikymmentä kahdeksan miestä. Heidän päällysmiehenään oli Sabdiel, Gedolimin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Leeviläisiä: Semaja, Hassubin poika, joka oli Asrikamin poika, joka Hasabjan poika, joka Bunnin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'ja Sabbetai ja Joosabad, jotka valvoivat ulkotöitä Jumalan temppelissä ja olivat leeviläisten päämiehiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'ja Mattanja, Miikan poika, joka oli Sabdin poika, joka Aasafin, ensimmäisen johtajan, poika, joka rukoiltaessa aloitti kiitosvirren, ja Bakbukja, hänen veljistään toinen, ja Abda, Sammuan poika, joka oli Gaalalin poika, joka Jedutunin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Leeviläisiä oli pyhässä kaupungissa kaikkiaan kaksisataa kahdeksankymmentä neljä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Ovenvartijat olivat Akkub, Talmon sekä heidän veljensä, jotka vartioivat portteja, sata seitsemänkymmentä kaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Muut israelilaiset, papit ja leeviläiset asuivat kaikissa muissa Juudan kaupungeissa kukin perintöosallaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Temppelipalvelijat asuivat Oofelilla; Siiha ja Gispa valvoivat temppelipalvelijoita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Leeviläisten päällysmiehenä Jerusalemissa Jumalan temppelin toimissa oli Ussi, Baanin poika, joka oli Hasabjan poika, joka Mattanjan poika, joka Miikan poika, Aasafin jälkeläisiä, veisaajia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Oli näet heitä koskeva kuninkaan käsky, joka takasi veisaajille heidän jokapäiväiset tarpeensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Petahja, Mesesabelin poika, Serahin, Juudan pojan, jälkeläisiä, oli kuninkaan edusmiehenä kaikissa kansaa koskevissa asioissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Heidän peltomaillaan olevissa kylissä asui Juudan miehiä: Kirjat-Arbassa ja sen tytärkaupungeissa, Diibonissa ja sen tytärkaupungeissa, Jekabseelissa ja siihen kuuluvissa kylissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'Jeesuassa, Mooladassa, Beet-Peletissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'Hasar-Suualissa, Beersebassa ja sen tytärkaupungeissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'Siklagissa, Mekonassa ja sen tytärkaupungeissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'Een-Rimmonissa, Sorassa, Jarmutissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Saanoahissa, Adullamissa ja niihin kuuluvissa kylissä, Laakiissa ja sen peltomailla, Asekassa ja sen tytärkaupungeissa. He asettuivat siis asumaan Beersebasta aina Hinnomin laaksoon saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Benjaminilaiset asuivat, Gebasta alkaen, Mikmaassa, Aijassa, Beetelissä ja sen tytärkaupungeissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'Anatotissa, Noobissa, Ananjassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Haasorissa, Raamassa, Gittaimissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Haadidissa, Seboimissa, Neballatissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Loodissa, Oonossa, Seppäinlaaksossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Leeviläisistä asui eräitä Juudan osastoja Benjaminissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Nämä olivat ne papit ja leeviläiset, jotka lähtivät Serubbaabelin, Sealtielin pojan, ja Jeesuan kanssa: Seraja, Jeremia, Esra,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amarja, Malluk, Hattus,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Sekanja, Rehum, Meremot,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Iddo, Ginnetoi, Abia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Miijamin, Maadja, Bilga,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semaja, Joojarib, Jedaja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallu, Aamok, Hilkia ja Jedaja. Nämä olivat pappien ja heidän veljiensä päämiehet Jeesuan aikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Leeviläisiä olivat: Jeesua, Binnui, Kadmiel, Seerebja, Juuda ja Mattanja, joka yhdessä veljiensä kanssa johti kiitosvirren veisua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'Heidän veljensä Bakbukja ja Unni seisoivat vastapäätä heitä tehtäviään suorittamassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Jeesualle syntyi Joojakim, Joojakimille syntyi Eljasib, Eljasibille syntyi Joojada,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Joojadalle syntyi Joonatan ja Joonatanille syntyi Jaddua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'Joojakimin aikana olivat seuraavat papit perhekuntien päämiehinä: Serajalla Meraja, Jeremialla Hananja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'Esralla Mesullam, Amarjalla Joohanan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'Mallukilla Joonatan, Sebanjalla Joosef,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'Haarimilla Adna, Merajotilla Helkai,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'Iddolla Sakarja, Ginnetonilla Mesullam,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'Abialla Sikri, Minjaminilla, Mooadjalla Piltai,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'Bilgalla Sammua, Semajalla Joonatan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'Joojaribilla Mattenai, Jedajalla Ussi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'Sallailla Kallai, Aamokilla Eeber,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'Hilkialla Hasabja ja Jedajalla Netanel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Leeviläisistä merkittiin Eljasibin, Joojadan, Joohananin ja Jadduan aikana perhekuntien päämiehet muistiin, ja samoin papit persialaisen Daarejaveksen hallitusaikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Leevin jälkeläisistä ovat perhekuntien päämiehet merkittyinä aikakirjaan Joohananin, Eljasibin pojan, aikaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Leeviläisten päämiehet olivat Hasabja, Seerebja ja Jeesua, Kadmielin poika, sekä heidän veljensä, jotka seisoivat heitä vastapäätä ylistämässä ja kiittämässä, niin kuin Jumalan mies Daavid oli käskenyt, osasto osaston vieressä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'ja Mattanja, Bakbukja, Obadja, Mesullam, Talmon ja Akkub, ovenvartijat, jotka vartioivat porttien varastohuoneita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Nämä olivat Joojakimin, Jeesuan pojan, Joosadakin pojanpojan, aikalaisia ja käskynhaltija Nehemian ja pappi Esran, kirjanoppineen, aikalaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Kun Jerusalemin muuri oli vihittävä, haettiin leeviläiset kaikista heidän asuinpaikoistaan ja tuotiin Jerusalemiin viettämään vihkimisjuhlaa iloiten, kiitosvirsiä ja lauluja laulaen, symbaaleja, harppuja ja lyyroja soittaen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Niin kokoontuivat veisaajien pojat Lakeudelta, Jerusalemin ympäristöstä, netofalaisten kylistä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'Beet-Gilgalista ja Geban ja Asmavetin peltomailta, sillä veisaajat olivat rakentaneet itselleen kyliä Jerusalemin ympäristöön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Papit ja leeviläiset puhdistautuivat ja puhdistivat kansan sekä portit ja muurin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Vein Juudan päämiehet rinteelle, muurin yläpuolelle, ja järjestin kaksi suurta laulukuntaa ja juhlakulkuetta muurin yläpuolelle, oikealle kädelle Lantaportille päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Heidän jäljessään kulkivat Hoosaja ja toinen puoli Juudan päämiehiä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'sekä Asarja, Esra, Mesullam,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juuda, Benjamin, Semaja ja Jeremia');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'sekä pappien poikia torvineen, ja Sakarja, Joonatanin poika, joka oli Semajan poika, joka Mattanjan poika, joka Miikajan poika, joka Sakkurin poika, joka Aasafin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'sekä hänen veljensä Semaja, Asarel, Milalai, Gilalai, Maai, Netanel, Juuda ja Hanani Daavidin, Jumalan miehen, soittimia kantaen. Esra, kirjanoppinut, kulki heidän edellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'He menivät Lähdeportin ohi ja nousivat suoraan Daavidin kaupungin portaita sinne, mistä noustaan muurille, Daavidin palatsin yläpuolelle, aina Vesiportille asti idässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Toinen laulukunta kulki vastakkaiseen suuntaan, ja sen jäljessä minä ja toinen puoli kansaa muurin yläpuolitse, Uunitornin yläpuolitse, aina Leveälle muurille asti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'ja Efraimin-portin yläpuolitse ja Vanhanportin, Kalaportin, Hananelin-tornin ja Hammea-tornin ohi aina Lammasportille saakka. He asettuivat Vankilaportin luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Molemmat laulukunnat asettuivat Jumalan temppeliin, ja samoin minä ja toinen puoli esimiehiä kanssani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'sekä papit Eljakim, Maaseja, Minjamin, Miikaja, Eljoenai, Sakarja ja Hananja torvineen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'ja Maaseja, Semaja, Eleasar, Ussi, Joohanan, Malkia, Eelam ja Eser. Veisaajat kaiuttivat virsiään, ja Jisrahja oli johtajana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'He uhrasivat sinä päivänä suuria uhreja ja iloitsivat, sillä Jumala oli suuresti ilahduttanut heitä. Myös vaimot ja lapset iloitsivat. Ilo kuului Jerusalemista kauas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Sinä päivänä asetettiin miehiä valvomaan varastokammioita, joissa annit, ensisato ja kymmenykset säilytettiin. Niihin oli koottava kaupunkien peltomailta papeille ja leeviläisille lain mukaan tulevat osuudet. Sillä Juuda iloitsi palvelusta toimittavista papeista ja leeviläisistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Nämä toimittivat tehtävänsä Jumalaansa palvellen ja puhdistuksia suorittaen, samoin veisaajat ja ovenvartijat, niin kuin Daavid ja hänen poikansa Salomo olivat käskeneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Sillä jo muinoin, Daavidin ja Aasafin aikana, oli veisaajilla johtajia, ja veisattiin ylistys- ja kiitosvirsiä Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Koko Israel antoi Serubbaabelin ja Nehemian aikana veisaajille ja ovenvartijoille heidän osuutensa, heidän jokapäiväiset tarpeensa. He pyhittivät lahjoja myös leeviläisille, ja leeviläiset pyhittivät lahjoja Aaronin pojille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'Sinä päivänä luettiin Mooseksen kirjaa kansan kuullen, ja siihen havaittiin kirjoitetun, ettei ammonilainen eikä mooabilainen koskaan pääse Jumalan seurakuntaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'sen tähden että he eivät tulleet leipää ja vettä tuoden israelilaisia vastaan ja koska hän palkkasi heitä vastaan Bileamin kiroamaan heidät, vaikka Jumalamme muuttikin kirouksen siunaukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Kuultuaan lain he erottivat kaiken sekakansan Israelista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Mutta sitä ennen oli pappi Eljasib, Tobian sukulainen, joka oli asetettu Jumalamme temppelin kammionhoitajaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'sisustanut Tobialle suuren kammion, johon ennen oli pantu ruokauhri, suitsuke, kalusto ja jyvä-, viini- ja öljykymmenykset, jotka olivat määrätyt leeviläisille, veisaajille ja ovenvartijoille, sekä papeille tuleva anti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Tämän kaiken tapahtuessa en ollut Jerusalemissa, sillä olin mennyt Artahsastan, Baabelin kuninkaan, kolmantenakymmenentenä toisena hallitusvuotena kuninkaan luo. Mutta jonkin ajan kuluttua pyysin kuninkaalta vapaata');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'ja palasin Jerusalemiin. Kun huomasin, minkä pahan Eljasib oli tehnyt Tobian eduksi sisustaessaan hänelle kammion Jumalan temppelin esipihoissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'pahastuin suuresti, ja heitin kaikki Tobian huonekalut ulos kammiosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'Käskin puhdistaa kammiot ja panetin niihin takaisin Jumalan temppelin kaluston, ruokauhrin ja suitsukkeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Vielä sain tietää, ettei leeviläisille ollut annettu heidän osuuksiaan, ja niin leeviläiset ja veisaajat, joiden olisi ollut määrä tehdä palvelusta, olivat vetäytyneet kukin maatilalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Nuhtelin siitä esimiehiä ja sanoin: \"Minkä tähden Jumalan temppeli on laiminlyöty?\" Sitten kokosin leeviläiset ja veisaajat ja asetin heidät paikoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Koko Juuda toi kymmenykset jyvistä, viinistä ja öljystä varastohuoneisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Asetin Selemjan, papin, ja Saadokin, kirjanoppineen, ja Pedajan, leeviläisen, valvomaan varastohuoneita ja annoin heidän apulaisekseen Haananin, Sakkurin pojan, Mattanjan pojanpojan. Sillä heitä pidettiin luotettavina, ja heidän tehtävänään oli toimittaa jako veljiensä kesken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Muista tämän tähden minua, Jumalani, äläkä pyyhi pois laupeuden tekojani, jotka olen tehnyt Jumalani temppelin ja siinä toimitettavan palveluksen hyväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'Siihen aikaan näin Juudassa niitä, jotka sapattina polkivat viinikuurnaa ja jotka kuljettivat viljaa ja kuormittivat aaseja sillä sekä viinillä, rypäleillä, viikunoilla ja kaikenlaisella muulla kuormatavaralla. He toivat niitä Jerusalemiin sapatinpäivänä. Varoitin heitä, kun he myivät elintarpeita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Sinne oli myös asettunut tyyrolaisia, jotka toivat kalaa ja kaikenlaista kauppatavaraa ja myivät Juudan kansalle sapattina ja Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Nuhtelin Juudan ylimyksiä ja sanoin heille: \"Kuinka te teette näin pahasti ja saastutatte sapatinpäivän?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Eikö Jumalamme juuri sen tähden, että isänne näin tekivät, antanut kaiken tämän onnettomuuden kohdata meitä ja tätä kaupunkia? Mutta nyt te tuotatte vielä suuremman vihan Israelin ylitse, kun saastutatte sapatinpäivän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Sitten heti, kun oli tullut pimeä ennen sapattia Jerusalemin porteissa, käskin sulkea ovet ja kielsin avaamasta niitä ennen kuin vasta sapatin jälkeen. Asetin palvelijoitani porteille, ettei yhtään kuormaa pääsisi kaupunkiin sapatinpäivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Kauppiaat ja kaikenlaisen tavaran myyjät jäivät yöksi Jerusalemin ulkopuolelle, kerran ja toisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Mutta varoitin heitä ja sanoin heille: \"Minkä tähden te jäätte yöksi muurin edustalle? Jos vielä kerran teette sen, niin käyn teihin käsiksi.\" Sen jälkeen he eivät enää tulleet sapattina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Minä käskin leeviläisten puhdistautua ja tulla vartioimaan portteja, että sapatinpäivä pyhitettäisiin. Muista minua, Jumalani, tämänkin tähden ja sääli minua suuressa laupeudessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Siihen aikaan näin myös juutalaisia, jotka olivat naineet asdodilaisia, ammonilaisia ja mooabilaisia vaimoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'Heidän lapsistaan puolet puhui asdodinkieltä tai jonkin muun kansan kieltä, eivätkä osanneet puhua juudankieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Nuhtelin heitä ja kirosin heidät, jopa löin muutamia heistä, revin heitä parrasta ja vannotin heitä Jumalan kautta: \"Älkää antako tyttäriänne heidän pojilleen älkääkä ottako heidän tyttäriään vaimoiksi pojillenne tai itsellenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Eikö Salomo, Israelin kuningas, tehnyt juuri tuollaista syntiä? Ei yhdelläkään monien kansojen joukossa ollut hänen vertaistaan kuningasta. Hän oli Jumalalleen rakas, ja Jumala asetti hänet koko Israelin kuninkaaksi. Kuitenkin muukalaiset vaimot saattoivat hänetkin tekemään syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Nytkö meidän täytyy kuulla teistä, että olette tehneet kaiken tämän suuren pahan ja olleet uskottomat meidän Jumalaamme kohtaan, kun olette naineet muukalaisia vaimoja?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Yksi ylipappi Eljasibin pojan Joojadan pojista oli hooronilaisen Sanballatin vävy. Hänet minä karkotin luotani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Muista heidät, Jumalani, sillä he ovat saastuttaneet pappeuden sekä pappeus- ja leeviläisliiton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Puhdistin heidät kaikesta muukalaisuudesta. Järjestin virkatehtävät papeille ja leeviläisille, kullekin hänen toimensa mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'niin myös polttopuita koskevan uhrilahjan määräaikoina ja ensisadon lahjat. Muista minua, Jumalani, hyvyydelläsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Ahasveroksen aikana – sen Ahasveroksen, joka hallitsi Intiasta Kuusin maahan saakka, sataa kahtakymmentä seitsemää maakuntaa – siihen aikaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'kun kuningas Ahasveros istui kuninkaallisella valtaistuimellaan, joka oli Suusanin linnassa, tapahtui tämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'Kolmantena hallitusvuotenaan hän laittoi pidot kaikille ruhtinailleen ja palvelijoilleen. Persian ja Meedian hallitseva voima, ylimykset ja maaherrat olivat hänen luonaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'ja hän näytti heille kuninkaallisen kunniansa rikkautta ja suuruutensa loistavaa komeutta monta päivää, sata kahdeksankymmentä päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Kun ne päivät olivat kuluneet, kuningas laittoi kaikelle Suusanin linnan väelle, niin pienille kuin suurillekin, kuninkaan palatsin puutarhan esipihaan seitsemän päivän pidot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Pellava-, puuvilla- ja sinipunaverhoja oli kiinnitetty valkoisilla pellavanauhoilla ja purppuranpunaisilla nauhoilla hopeatankoihin ja valkoisiin marmoripylväisiin. Kultaisia ja hopeisia lepovuoteita oli pihalla, joka oli päällystetty vihreällä ja valkoisella marmorilla, helmiäisellä ja kirjavalla marmorilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Juotavaa tarjottiin kulta-astioissa, ja astiat olivat erimuotoisia. Kuninkaan viiniä oli runsaasti kuninkaalliseen tapaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Juomisessa oli lakina, ettei saanut olla mitään pakkoa, sillä niin kuningas oli käskenyt kaikkia hovimestareitaan, että oli tehtävä kunkin oman halun mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Kuningatar Vastikin laittoi naisille pidot kuningas Ahasveroksen kuninkaalliseen palatsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Seitsemäntenä päivänä, kun kuninkaan sydän oli viinistä iloinen, hän käski Mehumanin, Bistan, Harbonan, Bigtan, Abagtan, Seetarin ja Karkaan, niiden seitsemän hoviherran, jotka toimittivat palvelusta kuningas Ahasveroksen luona,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'tuoda kuningatar Vastin kuninkaallinen kruunu päässä kuninkaan eteen, että hän saisi näyttää kansoille ja ruhtinaille hänen kauneutensa, sillä hän oli ulkonäöltään ihana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Mutta kuningatar Vasti kieltäytyi tulemasta, vaikka kuningas hoviherrojen välityksellä oli käskenyt. Kuningas suuttui kovin, ja hänessä syttyi viha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Kuningas puhui viisaille, jotka tunsivat ajat – sillä näin oli tapana esittää kuninkaan sana kaikille lain ja oikeuden tuntijoille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'ja hänen lähimpänsä olivat Karsena, Seetar, Admata, Tarsis, Meres, Marsena ja Memukan, seitsemän Persian ja Meedian ruhtinasta, jotka näkivät kuninkaan kasvot ja istuivat valtakunnan ensimmäisinä –:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, '\"Mitä lain mukaan on tehtävä kuningatar Vastille, koska hän ei ole noudattanut käskyä, jonka kuningas Ahasveros on antanut hoviherrojen kautta?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Memukan sanoi kuninkaan ja ruhtinaiden edessä: \"Kuningatar Vasti ei ole rikkonut ainoastaan kuningasta vastaan, vaan myös kaikkia ruhtinaita vastaan ja kaikkia kansoja vastaan kuningas Ahasveroksen kaikissa maakunnissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Kun kuningattaren teko tulee kaikkien vaimojen tietoon, se saattaa heidät halveksimaan aviomiehiään, he kun voivat sanoa: \'Kuningas Ahasveros käski tuoda kuningatar Vastin eteensä, mutta tämä ei tullut.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Jo tänä päivänä voivat Persian ja Meedian ruhtinattaret, jotka kuulevat kuningattaren teon, puhua siitä kaikille kuninkaan ruhtinaille, ja siitä tulee halveksimista ja suuttumusta riittämiin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Jos kuningas hyväksi näkee, julkaistakoon kuninkaallinen käsky ja kirjoitettakoon muuttumattomana Persian ja Meedian lakeihin, ettei Vasti enää saa tulla kuningas Ahasveroksen eteen ja että kuningas antaa hänen kuninkaallisen arvonsa toiselle, häntä paremmalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Kuninkaan antama säädös tulee tunnetuksi koko hänen valtakunnassaan, vaikka se onkin suuri, ja kaikki vaimot, sekä suuret että pienet, antavat kunnian aviomiehilleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Tämä puhe miellytti kuningasta ja ruhtinaita, ja kuningas teki Memukanin sanan mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Hän lähetti kaikkiin kuninkaan maakuntiin – kuhunkin maakuntaan sen omalla kirjoituksella ja kullekin kansalle sen omalla kielellä – kirjeet, että jokainen mies olkoon herra talossaan ja saakoon puhua oman kansansa kieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Näiden tapausten jälkeen, kun kuningas Ahasveroksen viha oli asettunut, hän muisti Vastia ja mitä tämä oli tehnyt ja mitä hänestä oli päätetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Kuninkaan palvelijat, jotka toimittivat hänelle palvelusta, sanoivat: \"Etsittäköön kuninkaalle nuoria neitsyitä, ihania näöltään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'Asettakoon kuningas kaikkiin valtakuntansa maakuntiin käskyläiset keräämään kaikki nuoret neitsyet, näöltään ihanat, Suusanin linnaan, vaimojen taloon, Heegain, kuninkaan hoviherran ja vaimojen vartijan, huostaan, ja annettakoon heille heidän kauneudenhoitonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'Neitsyt, johon kuningas mieltyy, tulkoon kuningattareksi Vastin sijaan.\" Tämä puhe miellytti kuningasta, ja hän teki niin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Suusanin linnassa oli juutalainen mies, nimeltä Mordokai, Jaairin poika, joka oli Siimein poika, joka Kiisin poika, benjaminilainen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'joka oli viety Jerusalemista karkotukseen niiden karkotettujen joukossa, jotka vietiin samalla kuin Jekonja, Juudan kuningas, jonka Nebukadnessar, Baabelin kuningas, vei karkotukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Hän [Mordokai] oli setänsä tyttären Hadassan, se on Esterin, kasvatusisä, sillä tämä oli isätön ja äiditön. Tyttö oli vartaloltaan kaunis ja näöltään ihana, ja hänen isänsä ja äitinsä kuoltua Mordokai oli ottanut hänet tyttärekseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Kun kuninkaan käsky ja laki tuli tunnetuksi ja kun kerättiin paljon tyttöjä Suusanin linnaan Heegain huostaan, otettiin Esterkin kuninkaan palatsiin Heegain, vaimojen vartijan, huostaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Tyttö miellytti häntä ja sai armon hänen edessään, ja hän antoi hänelle joutuin hänen kauneudenhoitonsa ja määrätyn ravinto-osansa sekä seitsemän valiopalvelijatarta kuninkaan palatsista ja siirsi hänet palvelijattarineen vaimojen taloon parhaaseen paikkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Ester ei ilmaissut kansaansa eikä syntyperäänsä, sillä Mordokai oli häntä kieltänyt sitä ilmaisemasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Mutta Mordokai kuljeskeli joka päivä vaimojen talon esipihan edustalla saadakseen tietää, voiko Ester hyvin ja mitä hänelle on tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Kun jonkun tytön vuoro tuli mennä kuningas Ahasveroksen luo, sitten kun hänelle oli kaksitoista kuukautta tehty, niin kuin vaimoista oli määrätty – sillä niin pitkä aika kului heidän kauneudenhoitoonsa: kuusi kuukautta mirhaöljyllä, toiset kuusi kuukautta hajuaineilla sekä muilla naisten kauneudenhoitokeinoilla – meni tyttö kuninkaan luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Kaikki, mitä hän pyysi, annettiin hänelle mukaan vaimojen talosta kuninkaan palatsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Illalla hän meni, ja aamulla hän palasi toiseen vaimojen taloon kuninkaan hoviherran Saasgan, sivuvaimojen vartijan, huostaan. Hän ei enää mennyt kuninkaan luo, paitsi jos kuningas oli häneen mieltynyt ja häntä kutsuttiin nimellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Kun Esterille, Mordokain sedän Abihailin tyttärelle, jonka Mordokai oli ottanut tyttärekseen, tuli vuoro mennä kuninkaan luo, hän ei halunnut mukaansa muuta, kuin mitä Heegai, kuninkaan hoviherra, vaimojen vartija, neuvoi. Ester sai armon kaikkien niiden edessä, jotka näkivät hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Ester vietiin kuningas Ahasveroksen luo hänen kuninkaalliseen palatsiinsa kymmenennessä kuussa, se on teebet-kuussa, hänen seitsemäntenä hallitusvuotenaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Ester tuli kuninkaalle kaikkia muita naisia rakkaammaksi ja sai hänen edessään armon ja suosion ennen kaikkia muita neitsyitä, niin että tämä pani kuninkaallisen kruunun hänen päähänsä ja teki hänet kuningattareksi Vastin sijaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Kuningas laittoi suuret pidot kaikille ruhtinailleen ja palvelijoilleen, pidot Esterin kunniaksi, ja myönsi maakunnille verohuojennusta ja jakeli lahjoja, kuninkaalliseen tapaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Kun neitsyitä koottiin toinen kerta ja Mordokai istuskeli kuninkaan portissa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, '– eikä Ester ollut ilmaissut syntyperäänsä eikä kansaansa, sillä Mordokai oli häntä siitä kieltänyt. Ester näet teki, mitä Mordokai käski, samoin kuin ollessaan hänen kasvattinaan –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'niin siihen aikaan Mordokain istuskellessa kuninkaan portissa Bigtan ja Teres, kaksi kuninkaan hoviherraa, ovenvartijoita, suuttuivat ja etsivät tilaisuutta käydäkseen käsiksi kuningas Ahasverokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Mutta se tuli Mordokain tietoon, ja hän ilmaisi sen kuningatar Esterille, ja Ester sanoi sen Mordokain nimessä kuninkaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Asia tutkittiin, ja kun se havaittiin todeksi, ripustettiin heidät molemmat hirsipuuhun. Se kirjoitettiin aikakirjaan kuningasta varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Näiden tapausten jälkeen kuningas Ahasveros korotti agagilaisen Haamanin, Hammedatan pojan, ylensi hänet ja antoi hänelle ylimmän sijan kaikkien ruhtinaiden joukossa, jotka olivat hänen luonaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Kaikki kuninkaan palvelijat, jotka olivat kuninkaan portissa, polvistuivat ja heittäytyivät maahan Haamanin edessä, sillä niin oli kuningas käskenyt häntä kohdella. Mutta Mordokai ei polvistunut eikä heittäytynyt maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Kuninkaan palvelijat, jotka olivat kuninkaan portissa, sanoivat Mordokaille: \"Miksi sinä rikot kuninkaan käskyn?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Kun he joka päivä sanoivat hänelle näin, mutta hän ei totellut heitä, he ilmoittivat tämän Haamanille nähdäkseen oliko Mordokain sanoma syy pätevä, sillä hän oli ilmoittanut heille olevansa juutalainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Kun Haaman näki, ettei Mordokai polvistunut eikä heittäytynyt maahan hänen edessään, Haaman tuli kiukkua täyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Kun hänelle ilmoitettiin, mitä kansaa Mordokai oli, hän väheksyi käydä käsiksi yksinomaan Mordokaihin: Haaman etsi tilaisuutta hävittääkseen koko Ahasveroksen valtakunnasta kaikki juutalaiset, Mordokain kansan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Ensimmäisessä kuussa, se on niisan-kuussa, kuningas Ahasveroksen kahdentenatoista vuotena, heitettiin Haamanin edessä puuria, se on arpaa, jokaisesta päivästä ja jokaisesta kuukaudesta, kahdenteentoista kuukauteen, se on adar-kuuhun, asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Haaman sanoi kuningas Ahasverokselle: \"Eräs kansa on hajallaan ja erillään muiden kansojen seassa valtakuntasi kaikissa maakunnissa. Heidän lakinsa ovat toisenlaiset kuin kaikkien muiden kansojen. He eivät noudata kuninkaan lakeja, eikä kuninkaan sovi jättää heitä rauhaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Jos kuningas näkee hyväksi, kirjoitettakoon määräys, että heidät on tuhottava. Minä punnitsen kymmenentuhatta talenttia hopeaa virkamiehille vietäväksi kuninkaan aarrekammioihin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Kuningas otti kädestään sinettisormuksensa ja antoi sen agagilaiselle Haamanille, Hammedatan pojalle, juutalaisten vastustajalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Kuningas sanoi Haamanille: \"Hopea olkoon annettu sinulle, ja samoin se kansa, tehdäksesi sille, mitä hyväksi näet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Kutsuttiin kuninkaan kirjurit ensimmäisessä kuussa, sen kolmantenatoista päivänä, ja kirjoitettiin, aivan kuten Haaman käski, määräys kuninkaan satraapeille ja jokaisen maakunnan käskynhaltijoille ja jokaisen kansan ruhtinaille, kuhunkin maakuntaan sen omalla kirjoituksella ja kullekin kansalle sen omalla kielellä. Kuningas Ahasveroksen nimessä se kirjoitettiin ja sinetöitiin kuninkaan sinettisormuksella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Juoksijoiden mukana lähetettiin kaikkiin kuninkaan maakuntiin kirjeet, että oli hävitettävä, tapettava ja tuhottava kaikki juutalaiset, nuoret ja vanhat, lapset ja naiset, samana päivänä, kahdennentoista kuun, se on adar-kuun, kolmantenatoista päivänä, ja että oli ryöstettävä, mitä heiltä oli saalista saatavana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Kirjeen jäljennös oli julkaistava lakina jokaisessa maakunnassa tiedoksi kaikille kansoille, että olisivat valmiit tuona päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Juoksijat lähtivät kuninkaan käskystä kiireisesti matkaan heti, kun laki oli annettu Suusanin linnassa. Kuningas ja Haaman istuivat juomaan, mutta Suusanin kaupunki oli hämmästyksissään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Kun Mordokai sai tietää kaiken, mitä oli tapahtunut, Mordokai repäisi vaatteensa, pukeutui säkkiin ja tuhkaan ja meni keskelle kaupunkia ja huuteli kovia ja katkeria valitushuutoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Hän meni kuninkaan portin edustalle asti, sillä sisälle kuninkaan porttiin ei saanut mennä säkkiin puettuna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Jokaisessa maakunnassa, joka paikassa, mihin kuninkaan käsky ja hänen lakinsa tuli, syntyi juutalaisten keskuudessa suuri suru: paastottiin, itkettiin ja valitettiin. Monet levittivät alleen säkin ja tuhkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Kun Esterin palvelijattaret ja hänen hoviherransa tulivat ja kertoivat hänelle tämän, kuningatar joutui suureen tuskaan, ja hän lähetti vaatteita, että Mordokai puettaisiin niihin ja että hän riisuisi säkin yltään, mutta hän ei ottanut niitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Ester kutsui Hatakin, joka oli kuninkaan hoviherroja ja jonka tämä oli asettanut häntä palvelemaan, ja käski hänet Mordokain luo saadakseen tietää, mitä ja mistä syystä tämä kaikki oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Hatak meni Mordokain luo kaupungin torille, joka on kuninkaan portin edustalla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'ja Mordokai ilmoitti hänelle kaikki, mitä hänelle oli tapahtunut, ja myös tarkasti, kuinka paljon hopeaa Haaman oli luvannut punnita kuninkaan aarrekammioihin juutalaisten tuhoamisesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Myös jäljennöksen sen lain sanamuodosta, joka Suusanissa oli annettu heidän hävittämisekseen, hän antoi hänelle, että hän näyttäisi sen Esterille ja ilmoittaisi tälle asian sekä velvoittaisi häntä menemään kuninkaan luo anomaan armoa ja rukoilemaan häntä kansansa puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Hatak meni ja kertoi Esterille Mordokain sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Ester puhui Hatakille ja käski hänen sanoa Mordokaille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, '\"Kaikki kuninkaan palvelijat ja kuninkaan maakuntien kansa tietävät, että kuka ikinä, mies tai nainen, kutsumatta menee kuninkaan luo sisimpään esipihaan, on laki sama jokaiselle: hänet surmataan. Vain se, jota kohti kuningas ojentaa kultavaltikkansa, jää eloon. Mutta minua ei ole kolmeenkymmeneen päivään kutsuttu tulemaan kuninkaan luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Kun Mordokaille kerrottiin Esterin sanat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Mordokai käski vastata Esterille: \"Älä luulekaan, että sinä, kun olet kuninkaan linnassa, pelastut yksin kaikista juutalaisista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Jos sinä tänä aikana olet vaiti, tulee apu ja pelastus juutalaisille muualta, mutta sinä ja sinun isäsi perhe tuhoudutte. Kuka tietää, etkö sinä juuri tällaista aikaa varten ole päässyt kuninkaalliseen arvoon?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Ester käski vastata Mordokaille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, '\"Mene ja kokoa kaikki Suusanin juutalaiset, ja paastotkaa puolestani. Olkaa syömättä ja juomatta kolme vuorokautta yötä päivää. Myös minä palvelijattarineni paastoan samoin. Sitten minä menen kuninkaan luo, vaikka se on vastoin lakia. Jos tuhoudun, niin tuhoudun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Niin Mordokai meni ja teki, aivan kuten Ester oli häntä käskenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Kolmantena päivänä Ester pukeutui kuninkaallisesti ja astui kuninkaan linnan sisimpään esipihaan vastapäätä kuninkaan linnaa. Kuningas istui kuninkaallisella valtaistuimellaan kuninkaallisessa linnassa vastapäätä linnan ovea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Kun kuningas näki kuningatar Esterin seisovan esipihassa, tämä sai armon hänen silmiensä edessä, ja kuningas ojensi Esteriä kohti kultavaltikan, joka hänellä oli kädessä. Ester astui esiin ja kosketti valtikan päätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Kuningas sanoi hänelle: \"Mikä sinun on, kuningatar Ester, ja mitä pyydät? Se sinulle annetaan, olkoon vaikka puoli valtakuntaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Ester vastasi: \"Jos kuningas hyväksi näkee, tulkoon kuningas ja myös Haaman tänä päivänä pitoihin, jotka olen hänelle laittanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Kuningas sanoi: \"Noutakaa kiireesti Haaman tehdäksemme Esterin toivomuksen mukaan.\" Kun kuningas ja Haaman olivat tulleet pitoihin, jotka Ester oli laittanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'kuningas kysyi viinin juonnin aikana Esteriltä: \"Mitä pyydät? Se sinulle annetaan, ja mitä haluat, se täytetään, olkoon vaikka puoli valtakuntaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Ester vastasi sanoen: \"Tätä minä pyydän ja haluan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'jos olen saanut armon kuninkaan silmien edessä ja jos kuningas näkee hyväksi antaa minulle, mitä pyydän, ja täyttää, mitä haluan, niin tulkoot kuningas ja Haaman vielä pitoihin, jotka heille laitan. Huomenna teen kuninkaan toivomuksen mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Haaman lähti sieltä sinä päivänä iloisena ja hyvillä mielin. Kun Haaman näki Mordokain kuninkaan portissa eikä tämä noussut ylös eikä näyttänyt pelkäävän häntä, täytti viha Mordokaita kohtaan Haamanin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Mutta Haaman hillitsi itsensä ja meni kotiinsa. Sitten hän lähetti noutamaan ystävänsä ja vaimonsa Sereksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Haaman kehuskeli heille rikkautensa loistoa ja poikiensa paljoutta, ja kuinka kuningas kaikessa oli korottanut hänet ja ylentänyt hänet ylemmäksi ruhtinaita ja kuninkaan palvelijoita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Haaman sanoi: \"Eipä kuningatar Esterkään antanut laittamiinsa pitoihin kuninkaan kanssa tulla kenenkään muun kuin minun. Huomiseksikin olen kuninkaan kanssa kutsuttu hänen luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Mutta tämä kaikki ei minua tyydytä, niin kauan kuin minä näen juutalaisen Mordokain istuvan kuninkaan portissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Hänen vaimonsa Seres ja kaikki hänen ystävänsä sanoivat hänelle: \"Tehtäköön hirsipuu viisikymmentä kyynärää korkea, ja pyydä huomenaamulla kuninkaalta, että Mordokai ripustetaan siihen, niin voit mennä kuninkaan kanssa pitoihin iloisena.\" Tämä puhe miellytti Haamania, ja hän teetti hirsipuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Sinä yönä uni pakeni kuningasta. Hän käski tuoda muistettavien tapahtumien kirjan, aikakirjan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Kun sitä luettiin kuninkaalle, huomattiin kirjoitetun, kuinka Mordokai oli ilmaissut, että Bigtan ja Teres, kaksi kuninkaan hoviherraa, ovenvartijoita, oli etsinyt tilaisuutta käydäkseen käsiksi kuningas Ahasverokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Kuningas kysyi: \"Mitä kunniaa ja korotusta Mordokai on tästä saanut?\" Kuninkaan palvelijat, jotka toimittivat hänelle palvelusta, vastasivat: \"Ei hän ole saanut mitään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Kuningas kysyi: \"Kuka on esipihassa?\" Mutta Haaman oli tullut kuninkaan palatsin ulompaan esipihaan pyytämään kuninkaalta, että Mordokai ripustettaisiin hirsipuuhun, jonka hän oli pystyttänyt Mordokaita varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Kuninkaan palvelijat vastasivat hänelle: \"Katso, esipihassa seisoo Haaman.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Kuningas sanoi: \"Tulkoon sisään.\" Kun Haaman oli tullut, kuningas kysyi häneltä: \"Mitä on tehtävä miehelle, jota kuningas tahtoo kunnioittaa?\" Niin Haaman ajatteli sydämessään: \"Kenellepä muulle kuningas tahtoisi osoittaa kunniaa kuin minulle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Haaman vastasi kuninkaalle: \"Miehelle, jota kuningas tahtoo kunnioittaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'tuotakoon kuninkaallinen puku, johon kuningas on ollut puettuna, ja hevonen, jolla kuningas on ratsastanut ja jonka päähän on pantu kuninkaallinen kruunu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'Puku ja hevonen annettakoon jollekin kuninkaan ruhtinaista, ylimyksistä. Puettakoon siihen mies, jota kuningas tahtoo kunnioittaa, ja kuljetettakoon häntä sen hevosen selässä kaupungin torilla ja huudettakoon hänen edellään: \'Näin tehdään miehelle, jota kuningas tahtoo kunnioittaa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Kuningas sanoi Haamanille: \"Hae joutuin puku ja hevonen, kuten sanoit, ja tee näin juutalaiselle Mordokaille, joka istuu kuninkaan portissa. Älä jätä tekemättä mitään kaikesta, mitä olet puhunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Haaman otti puvun ja hevosen, puki Mordokain ja kuljetti häntä hevosen selässä kaupungin torilla ja huusi hänen edellään: \"Näin tehdään miehelle, jota kuningas tahtoo kunnioittaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Sitten Mordokai palasi takaisin kuninkaan porttiin, mutta Haaman kiiruhti kotiinsa murehtien ja pää peitettynä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Kun Haaman kertoi vaimolleen Serekselle ja kaikille ystävilleen kaiken, mitä hänelle oli tapahtunut, sanoivat hänen viisaansa ja hänen vaimonsa Seres hänelle: \"Jos Mordokai, jonka edessä olet alkanut kaatua, on syntyjään juutalainen, et sinä voi hänelle mitään, vaan kaadut hänen eteensä maahan asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Heidän vielä puhuessaan hänen kanssaan tulivat kuninkaan hoviherrat ja veivät Haamanin kiireen vilkkaa pitoihin, jotka Ester oli laittanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Kuningas ja Haaman olivat saapuneet kuningatar Esterin kanssa juomaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Kuningas sanoi myös viinin juonnin toisena päivänä Esterille: \"Mitä pyydät, kuningatar Ester? Se sinulle annetaan, ja mitä haluat? Se täytetään, olkoon vaikka puoli valtakuntaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Kuningatar Ester vastasi ja sanoi: \"Jos olen saanut armon silmiesi edessä, kuningas, ja jos kuningas hyväksi näkee, annettakoon minulle oma henkeni, kun sitä pyydän, ja kansani, kun sitä haluan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Sillä meidät on myyty, minut ja kansani, hävitettäviksi, tapettaviksi ja tuhottaviksi. Jos meidät olisi myyty vain orjiksi ja orjattariksi, olisin siitä vaiti, sillä sen vaivan takia ei kannattaisi kuningasta vaivata.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Kuningas Ahasveros sanoi ja kysyi kuningatar Esteriltä: \"Kuka se on, ja missä se on, joka on rohjennut tehdä sellaista?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Ester vastasi: \"Se vastustaja ja vihamies on tuo paha Haaman.\" Silloin Haaman pelästyi kuningasta ja kuningatarta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Kuningas nousi vihoissaan juomasta viiniä ja meni linnan puutarhaan, mutta Haaman jäi siihen pyytääkseen henkeänsä kuningatar Esteriltä, sillä hän näki, että kuninkaalla oli paha mielessä häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Kun kuningas tuli linnan puutarhasta takaisin linnaan, jossa viiniä juotiin, Haaman oli juuri heittäytymässä lepovuoteelle, jolla kuningatar Ester lepäsi. Kuningas sanoi: \"Vai tekee hän vielä väkivaltaa kuningattarelle linnassa läsnä ollessani!\" Tuskin tämä sana oli päässyt kuninkaan suusta, kun jo Haamanin kasvot peitettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Silloin Harbona, yksi kuningasta palvelevista hoviherroista, sanoi: \"Katso, seisoohan Haamanin talon edessä hirsipuu viisikymmentä kyynärää korkea, se, minkä Haaman on teettänyt Mordokaita varten, jonka puhe kerran koitui kuninkaan hyväksi.\" Kuningas sanoi: \"Ripustakaa hänet siihen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Haaman ripustettiin hirsipuuhun, jonka hän oli pystyttänyt Mordokain varalle. Kuninkaan viha asettui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Sinä päivänä kuningas Ahasveros lahjoitti kuningatar Esterille Haamanin, juutalaisten vastustajan, talon. Mordokai pääsi kuninkaan eteen, sillä Ester oli ilmoittanut, mikä Mordokai oli hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Kuningas otti kädestään sinettisormuksensa, jonka hän oli otattanut pois Haamanilta, ja antoi sen Mordokaille, ja Ester pani Mordokain Haamanin talon hoitajaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Mutta Ester puhui vielä kuninkaan edessä ja lankesi hänen jalkojensa juureen, itki ja rukoili häntä torjumaan agagilaisen Haamanin pahuuden ja sen juonen, jonka tämä oli punonut juutalaisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Kuningas ojensi Esteriä kohti kultavaltikan, ja Ester nousi ja seisoi kuninkaan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'Hän sanoi: \"Jos kuningas hyväksi näkee ja jos minä olen löytänyt armon hänen edessään ja kuningas katsoo sen soveliaaksi ja minä olen hänen silmissään otollinen, kirjoitettakoon määräys ja peruutettakoon agagilaisen Haamanin, Hammedatan pojan, juoni, ne kirjeet, jotka hän kirjoitutti tuhotakseen juutalaiset kaikissa kuninkaan maakunnissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Sillä kuinka jaksaisin nähdä kansaani kohtaavan onnettomuuden, kuinka jaksaisin nähdä sukuni surman!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Kuningas Ahasveros sanoi kuningatar Esterille ja juutalaiselle Mordokaille: \"Katso, Haamanin talon olen lahjoittanut Esterille, ja hänet itsensä on ripustettu hirsipuuhun, koska hän oli käynyt käsiksi juutalaisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Mutta nyt kirjoittakaa kuninkaan nimessä sellainen juutalaisia koskeva määräys, kuin hyväksi näette, ja sinetöikää se kuninkaan sinettisormuksella. Sillä kirjelmä, joka on kirjoitettu kuninkaan nimessä ja sinetöity kuninkaan sinettisormuksella, on peruuttamaton.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Niin kutsuttiin kuninkaan kirjurit silloin kolmannessa kuussa, se on siivan-kuussa, sen kahdentenakymmenentenä kolmantena päivänä, ja kirjoitettiin, aivan niin kuin Mordokai käski, määräys juutalaisille sekä satraapeille, käskynhaltijoille ja maaherroille sataan kahteenkymmeneen seitsemään maakuntaan, Intiasta Kuusin maahan saakka, kuhunkin maakuntaan sen omalla kirjoituksella ja kullekin kansalle sen omalla kielellä, myös juutalaisille heidän kirjoituksellaan ja kielellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Hän kirjoitutti kuningas Ahasveroksen nimessä ja sinetöi kuninkaan sinettisormuksella. Hän lähetti ratsulähettien mukana, jotka ratsastivat tammatarhoissa kasvatetuilla hovin hevosilla, kirjeet:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, '\"Kuningas sallii juutalaisten jokaisessa kaupungissa, missä heitä onkin, kokoontua puolustamaan henkeään hävittämällä, tappamalla ja tuhoamalla kansan ja maakunnan kaiken aseväen, joka heitä ahdistaa, sekä myös lapset ja naiset, ja ryöstämään, mitä heiltä on saatavana saalista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'samana päivänä kaikissa kuningas Ahasveroksen maakunnissa, kahdennentoista kuun, se on adar-kuun, kolmantenatoista päivänä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Kirjeen jäljennös oli julkaistava lakina jokaisessa maakunnassa tiedoksi kaikille kansoille, ja että juutalaiset olisivat valmiit sinä päivänä kostamaan vihollisilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Hovin hevosilla ratsastavat lähetit lähtivät kuninkaan käskystä kiireen vilkkaa ja nopeasti matkaan kohta, kun laki oli annettu Suusanin linnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Mutta Mordokai lähti kuninkaan luota puettuna kuninkaalliseen sinipunaiseen purppuraan ja pellavapukuun, ja hänellä oli suuri kultakruunu ja viitta, tehty valkoisesta pellavakankaasta ja purppuranpunaisesta kankaasta. Silloin Suusanin kaupunki riemuitsi ja oli iloissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Juutalaisille oli tullut onni, ilo, riemu ja kunnia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'ja jokaisessa maakunnassa ja kaupungissa, joka paikassa, mihin kuninkaan käsky ja hänen lakinsa tuli, oli juutalaisilla ilo ja riemu, pidot ja juhlat. Paljon oli maan kansoista niitä, jotka kääntyivät juutalaisiksi, sillä kauhu juutalaisia kohtaan oli vallannut heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Kahdennessatoista kuussa, se on adar-kuussa, sen kolmantenatoista päivänä, jona kuninkaan käsky ja hänen lakinsa oli toimeenpantava, sinä päivänä, jona juutalaisten viholliset olivat toivoneet saavansa heidät valtaansa, mutta jona päinvastoin juutalaiset saivat valtaansa vihamiehensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'kokoontuivat juutalaiset kaupungeissaan kaikissa kuningas Ahasveroksen maakunnissa käydäkseen käsiksi niihin, jotka olivat hankkineet heille onnettomuutta, eikä kukaan kestänyt heidän edessään, sillä kauhu heitä kohtaan oli vallannut kaikki kansat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Silloin kaikki maaherrat, satraapit ja käskynhaltijat ja kuninkaan virkamiehet auttoivat juutalaisia, sillä kauhu Mordokaita kohtaan oli vallannut heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Sillä Mordokai oli mahtava kuninkaan palatsissa, ja hänen maineensa levisi kaikkiin maakuntiin, sillä tämä mies, Mordokai, tuli yhä mahtavammaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Juutalaiset voittivat kaikki vihollisensa lyöden miekoilla, surmaten ja tuhoten, ja tekivät vihamiehilleen, mitä tahtoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Suusanin linnassa juutalaiset tappoivat ja tuhosivat viisisataa miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Parsandatan, Dalfonin, Aspatan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Pooratan, Adaljan, Aridatan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Parmastan, Arisain, Aridain ja Vaisatan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'kymmenen Haamanin, Hammedatan pojan, juutalaisten vastustajan, poikaa, he tappoivat, mutta saaliiseen he eivät käyneet käsiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Sinä päivänä tuli Suusanin linnassa tapettujen luku kuninkaan tietoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Niin kuningas sanoi kuningatar Esterille: \"Suusanin linnassa juutalaiset ovat tappaneet ja tuhonneet viisisataa miestä ja Haamanin kymmenen poikaa, muissa kuninkaan maakunnissa mitä lienevätkään tehneet! Mitä nyt pyydät? Se sinulle annetaan, ja mitä vielä haluat? Se täytetään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Niin Ester sanoi: \"Jos kuningas hyväksi näkee, sallittakoon Suusanin juutalaisten huomennakin tehdä saman lain mukaan kuin tänä päivänä. Ripustettakoon Haamanin kymmenen poikaa hirsipuuhun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Kuningas käski tehdä niin. Sitten siitä annettiin laki Suusanissa, ja Haamanin kymmenen poikaa ripustettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Suusanin juutalaiset kokoontuivat myös adar-kuun neljäntenätoista päivänä ja tappoivat Suusanissa kolmesataa miestä, mutta saaliiseen he eivät käyneet käsiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Myös muut juutalaiset, jotka olivat kuninkaan maakunnissa, olivat kokoontuneet puolustamaan henkeään ja päässeet rauhaan vihollisistaan tapettuaan vihamiehiään seitsemänkymmentäviisi tuhatta – käymättä käsiksi saaliiseen –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'adar-kuun kolmantenatoista päivänä. He lepäsivät sen kuun neljännentoista päivän viettäen sen pito- ja ilopäivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Mutta Suusanin juutalaiset olivat kokoontuneet sen kuun kolmantenatoista ja neljäntenätoista päivänä, ja he lepäsivät sen kuun viidennentoista päivän viettäen sen pito- ja ilopäivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Sen tähden maaseudun juutalaiset, jotka asuvat maaseutukaupungeissa, viettävät adar-kuun neljännentoista päivän ilo-, pito- ja juhlapäivänä ja lähettävät toisilleen maistiaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Mordokai pani kirjaan nämä tapaukset. Hän lähetti kirjeet kaikille juutalaisille kuningas Ahasveroksen kaikkiin maakuntiin, lähellä ja kaukana oleville,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'säätäen heille, että heidän oli vietettävä adar-kuun neljättätoista päivää ja saman kuun viidettätoista päivää joka vuosi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'koska juutalaiset niinä päivinä olivat päässeet rauhaan vihollisistaan ja siinä kuussa murhe oli kääntynyt heille iloksi ja suru juhlaksi – että heidän oli vietettävä ne päivät pito- ja ilopäivinä ja lähetettävä toisilleen maistiaisia ja köyhille lahjoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Juutalaiset ottivat pysyväksi tavaksi, mitä jo olivat alkaneet tehdä ja mitä Mordokai oli heille kirjoittanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Koska agagilainen Haaman, Hammedatan poika, kaikkien juutalaisten vastustaja, oli punonut juonen juutalaisia vastaan tuhotakseen heidät ja oli heittänyt puurin, se on arvan, hävittääkseen ja tuhotakseen heidät,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'ja koska sen tultua kuninkaan tietoon tämä oli kirjeellisesti määrännyt, että Haamanin pahan juonen, jonka hän oli punonut juutalaisia vastaan, tuli kääntyä hänen omaan päähänsä ja että hänet ja hänen poikansa oli ripustettava hirsipuuhun,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'sen tähden antoivat he näille päiville nimeksi puurim, puur-sanan mukaan. Sen tähden, tuon käskykirjeen koko sisällyksen johdosta ja sen johdosta, mitä he itse olivat näin nähneet ja mitä heille oli tapahtunut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'juutalaiset säätivät ja ottivat itselleen ja jälkeläisilleen ja kaikille heihin liittyville muuttumattomaksi ja pysyväksi tavaksi, että näitä kahta päivää oli vietettävä määräyksen mukaisesti ja määräaikana joka vuosi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'ja että jokaisen sukupolven ja suvun oli näitä päiviä muistettava ja vietettävä joka maakunnassa ja kaupungissa sekä että näiden puurim-päivien tuli säilyä muuttumattomina juutalaisten keskuudessa eikä niiden muisto saanut hävitä heidän jälkeläisiltään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Kuningatar Ester, Abihailin tytär, ja juutalainen Mordokai kirjoittivat kaiken valtansa nojalla kirjoituksia saattaakseen säädöksenä voimaan tämän toisen puurim-käskykirjeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Mordokai lähetti kirjeet, ystävällisin ja vilpittömin sanoin, kaikille juutalaisille Ahasveroksen valtakunnan sataan kahteenkymmeneen seitsemään maakuntaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'saattaakseen säädöksenä voimaan nämä puurim-päivät niiden määräaikoina, kuten juutalainen Mordokai ja kuningatar Ester olivat niistä säätäneet ja niin kuin juutalaiset itse olivat säätäneet itselleen ja jälkeläisilleen määräykset niihin kuuluvista paastoista ja valitushuudoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Näin säädettiin Esterin käskystä nämä puurim-määräykset ja kirjoitettiin kirjaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Kuningas Ahasveros saattoi työveron alaiseksi sekä mannermaan että merensaaret.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Kaikki hänen valta- ja urotyönsä ja kertomus Mordokain suuruudesta, johon kuningas hänet korotti, ovat kirjoitettuina Meedian ja Persian kuningasten aikakirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Sillä juutalainen Mordokai oli kuningas Ahasveroksen lähin mies ja oli suuri juutalaisten keskuudessa ja rakas lukuisille veljilleen, koska hän toimi kansansa parhaaksi ja puhui koko heimonsa onnen puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Uusin maassa oli mies, jonka nimi oli Job. Mies oli nuhteeton ja rehellinen, pelkäsi Jumalaa ja karttoi pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Hänelle syntyi seitsemän poikaa ja kolme tytärtä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Karjaa hänellä oli seitsemäntuhatta lammasta, kolmetuhatta kamelia, viisisataa härkäparia ja viisisataa aasintammaa sekä hyvin paljon palvelijoita. Tämä mies oli kaikista Idän miehistä mahtavin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Hänen pojillaan oli tapana laittaa pitoja. Kullakin oli pidot talossaan omana vuoropäivänään. He lähettivät silloin sanan ja kutsuivat kolme sisartaan syömään ja juomaan kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Kun pitopäivät olivat kiertonsa kiertäneet, Job lähetti sanan ja pyhitti heidät. Hän nousi varhain aamulla ja uhrasi polttouhreja, yhtä monta kuin heitä oli. Sillä Job ajatteli: \"Ehkä poikani ovat tehneet syntiä ja sydämessään kironneet Jumalan.\" Näin Job teki aina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Kun eräänä päivänä Jumalan pojat tulivat ja asettuivat Herran eteen, myös saatana tuli heidän joukossaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Herra kysyi saatanalta: \"Mistä sinä tulet?\" Saatana vastasi Herralle ja sanoi: \"Maata kiertämästä ja siellä kuljeksimasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Herra sanoi saatanalle: \"Oletko pannut merkille palvelijani Jobin? Sillä ei ole maan päällä hänen vertaistaan. Hän on nuhteeton ja rehellinen mies, pelkää Jumalaa ja karttaa pahaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Saatana vastasi Herralle ja sanoi: \"Turhaanko Job pelkää Jumalaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Olethan itse kaikilta puolin suojannut hänet, hänen talonsa ja kaiken, mitä hänellä on. Olet siunannut hänen kättensä työn, ja hänen karjalaumansa ovat levinneet ympäri maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Mutta ojennapa kätesi ja koske kaikkeen, mitä hänellä on, eikö hän kiroa sinua vasten kasvojasi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Herra sanoi saatanalle: \"Katso, kaikki, mitä hänellä on, olkoon käsissäsi. Älä vain koske kädelläsi häneen itseensä.\" Saatana meni pois Herran edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Kun sitten eräänä päivänä hänen poikansa ja tyttärensä söivät ja joivat viiniä vanhimman veljensä talossa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'sanansaattaja tuli Jobin luo ja sanoi: \"Naudoilla kynnettiin, ja aasintammat kävivät niiden vieressä laitumella,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'sabalaiset hyökkäsivät ja ryöstivät ne ja surmasivat palvelijat miekan terällä. Vain minä yksin pelastuin kertomaan tämän sinulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Hänen vielä puhuessaan tuli toinen ja sanoi: \"Jumalan tuli iski alas taivaasta, sytytti palamaan lampaat ja palvelijat ja kulutti heidät. Vain minä yksin pelastuin kertomaan tämän sinulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Hänen vielä puhuessaan tuli toinen ja sanoi: \"Kaldealaiset asettuivat kolmeen joukkoon ja kävivät kamelien kimppuun, ryöstivät ne ja surmasivat palvelijat miekan terällä. Vain minä yksin pelastuin kertomaan tämän sinulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Hänen vielä puhuessaan tuli toinen ja sanoi: \"Poikasi ja tyttäresi söivät ja joivat viiniä vanhimman veljensä talossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'Katso, silloin suuri tuulispää tuli tuolta puolen erämaan ja iski talon neljään nurkkaan, ja se luhistui nuorukaisten päälle, niin että he kuolivat. Vain minä yksin pelastuin kertomaan tämän sinulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Silloin Job nousi, repäisi viittansa ja leikkasi hiuksensa, heittäytyi maahan ja rukoili.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'Hän sanoi: \"Alastomana minä tulin äitini kohdusta, ja alastomana minä sinne palaan. Herra antoi, ja Herra otti; kiitetty olkoon Herran nimi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'Missään tässä Job ei tehnyt syntiä eikä puhunut sopimattomasti Jumalaa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Kun sitten eräänä päivänä Jumalan pojat tulivat ja asettuivat seisomaan Herran eteen, saatanakin tuli heidän joukossaan ja asettui Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Herra kysyi saatanalta: \"Mistä sinä tulet?\" Saatana vastasi Herralle ja sanoi: \"Maata kiertämästä ja siellä kuljeksimasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Herra sanoi saatanalle: \"Oletko pannut merkille palvelijani Jobin? Sillä ei ole maan päällä hänen vertaistaan; hän on nuhteeton ja rehellinen mies, pelkää Jumalaa ja karttaa pahaa. Vieläpä hän pysyy nuhteettomuudessaan, vaikka sinä olet yllyttänyt minut häntä vastaan tuhoamaan hänet syyttömästi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Saatana vastasi Herralle ja sanoi: \"Nahan nahasta; ja kaiken, mitä ihmisellä on, hän antaa hengestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Mutta ojennapa kätesi ja koske hänen luihinsa ja lihaansa, hän varmaan kiroaa sinua vasten kasvojasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Herra sanoi saatanalle: \"Katso, hän olkoon käsissäsi. Säästä kuitenkin hänen henkensä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Saatana meni pois Herran kasvojen edestä ja löi Jobiin pahoja paiseita kantapäästä kiireeseen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Tämä otti saviastian sirun kaapiakseen sillä itseään ja istui tuhkaläjään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Hänen vaimonsa sanoi hänelle: \"Vieläkö pysyt nuhteettomuudessasi? Kiroa Jumala ja kuole.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Mutta hän vastasi hänelle: \"Sinä puhut kuin mikäkin typerä nainen. Otammehan vastaan Jumalalta hyvää, emmekö ottaisi vastaan pahaakin?\" Missään tässä Job ei tehnyt syntiä huulillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Kun Jobin kolme ystävää kuuli kaiken onnettomuuden, joka oli häntä kohdannut, he tulivat kukin kotipaikastaan: teemanilainen Elifas, suuhilainen Bildad ja naemalainen Soofar; ja he sopivat keskenään ja menivät ottamaan osaa ja lohduttamaan häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Mutta kun he jonkin matkan päästä nostivat silmänsä, he eivät voineet enää tuntea häntä. He korottivat äänensä ja itkivät, repäisivät kukin viittansa ja heittivät tomua taivasta kohti päänsä päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'He istuivat hänen kanssaan maassa seitsemän päivää ja seitsemän yötä, eikä kukaan heistä puhunut sanaakaan hänelle, sillä he näkivät, että hänen tuskansa oli hyvin suuri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Sen jälkeen Job avasi suunsa ja kirosi syntymäpäivänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Job lausui ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, '\"Kadotkoon päivä, jona synnyin, ja yö, joka sanoi: \'Poika on siinnyt.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Se päivä muuttukoon pimeydeksi. Älköön Jumala korkeudessa sitä kysykö, älköönkä valonsäde sille paistako.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Omistakoon sen pimeys ja kuoleman varjo, pilvi laskeutukoon sen päälle, ja päivän pimentymiset sitä pelästyttäkööt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Sen yön ryöstäköön pimeys. Älköön se iloitko vuoden päivien joukossa älköönkä tulko kuukausien lukuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Katso, hedelmätön olkoon se yö. Älköön siinä riemuhuuto raikuko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Kirotkoot sen päivän kiroajat, ne, jotka ovat valmiina herättämään leviatanin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Pimentykööt sen kointähdet, odottakoon se valoa, jota ei tule, älköön se päivänkoiton silmäripsiä nähkö,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'koska se ei sulkenut minulta kohdun ovia eikä kätkenyt vaivaa silmiltäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Miksi en kuollut heti äidin helmaan, miksi en menehtynyt kohdusta tullessani?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Miksi olivat minua vastaanottamassa polvet, minkä tähden rinnat imeäkseni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Sillä makaisinhan rauhassa silloin, nukkuisin ja saisin levätä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'kuningasten ja maan neuvonantajien kanssa, jotka ovat rakentaneet itselleen raunioita,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'päämiesten kanssa, joilla on ollut kultaa, jotka ovat täyttäneet talonsa hopealla;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'tai olisin olematon kuin maahan kätketty keskonen, kuin sikiöt, jotka eivät ole päivänvaloa nähneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Siellä lakkaavat jumalattomat raivoamasta, siellä saavat uupuneet levätä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'kaikki vangit ovat rauhassa eivätkä kuule käskijän ääntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Yhtäläiset ovat siellä pieni ja suuri, ja orja on vapaa herrastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Miksi hän antaa vaivatulle valoa ja elämää murhemielisille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'jotka odottavat kuolemaa, eikä se tule, jotka etsivät sitä enemmän kuin aarretta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'jotka iloitsisivat riemastuksiin asti, riemuitsisivat, jos löytäisivät haudan –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'miehelle, jonka tie on ummessa, jonka Jumala on sulkenut aitaukseen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Sillä huokailuni on tullut leiväkseni, valitukseni valuu kuin vesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Sillä se, mitä kauhistuin, kohtasi minua, ja se, mitä pelkäsin, tapahtui minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Ennen kuin tyynnyin, ja sain rauhan ja levon, tuli tuska jälleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Silloin teemanilainen Elifas lausui ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, '\"Ethän pahastu, jos sinulle puhutaan? Kuka voi vaietakaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Katso, monia sinä olet ojentanut, ja hervonneita käsiä olet vahvistanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Sanasi ovat nostaneet kompastuneen ja rauenneita polvia olet voimistanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Mutta nyt, kun itseäsi kohtaa kova, sinä tuskastut, ja kun se sinuun sattuu, sinä kauhistut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Eikö jumalanpelkosi ole uskalluksesi ja nuhteeton vaelluksesi toivosi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Ajattele, kuka viaton on koskaan hukkunut, ja missä ovat rehelliset joutuneet perikatoon?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Minkä minä olen nähnyt, niin ne, jotka vääryyttä kyntävät ja turmiota kylvävät, ne sitä niittävätkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Jumalan henkäyksestä he hukkuvat, hänen vihansa hengestä he häviävät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Leijonan ärjyntä, suurenkin leijonan ääni vaiennetaan, ja nuorten leijonien hampaat murskataan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Urosleijona menehtyy saaliin puutteesta, ja naarasleijonan pennut hajaantuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Minulle tuli salaa sana, korvani kuuli kuiskauksen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'kun ajatukset liikkuivat öisissä näyissä, kun raskas uni oli vallannut ihmiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Pelko ja vapina yllättivät minut ja pelästyttivät kaikki luuni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Tuulen henkäys hyväili kasvojani, ihokarvani nousivat pystyyn.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Siinä seisoi – sen näköä en erottanut – hahmo silmieni edessä. Minä kuulin kuiskaavan äänen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, '\'Onko ihminen Jumalaa vanhurskaampi, onko mies Luojaansa puhtaampi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Katso, palvelijoihinsakaan hän ei luota, läheteissäänkin hän havaitsee vikoja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'saati niissä, jotka asuvat savimajoissa, joiden perustus on maan tomussa ja jotka koit murskaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Ennen kuin aamu vaihtuu illaksi, heidät muserretaan. Kenenkään huomaamatta he hukkuvat ainiaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Eikö heidän kanssaan oteta loputkin pois, ja eivätkö he kuole viisaudesta osattomina?\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, '\"Huuda vain! Onko ketään, joka sinulle vastaisi, ja kenen pyhän puoleen kääntyisit?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Mielettömän tappaa suuttumus, tyhmän surmaa kiivaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Minä näin mielettömän juurtuvan, mutta äkkiä kirosin hänen asuinsijaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Hänen lapsensa ovat onnesta kaukana, heitä poljetaan portissa, eikä auttajaa ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Sen, minkä he ovat leikanneet, syö nälkäinen – ottaa sen vaikka orjantappuroista – ja janoiset tavoittelevat heidän tavaraansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Sillä onnettomuus ei kasva tomusta eikä vaiva verso maasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'vaan ihminen syntyy vaivaan, ja kipinät, liekin lapset, lentävät korkealle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Mutta minä ainakin etsisin Jumalaa ja asettaisin asiani Jumalan eteen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'hänen, joka tekee suuria, tutkimattomia tekoja, ihmeitä ilman määrää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'joka antaa sateen maan päälle ja lähettää vettä pelloille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'että hän korottaisi alhaiset ja nostaisi surevat autuuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Hän tekee kavalien hankkeet tyhjiksi, niin ettei mikään menesty heidän kättensä alla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'hän vangitsee viisaat heidän viekkauteensa; ovelien juonet raukeavat:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'päivällä he joutuvat pimeään ja hapuilevat keskipäivällä kuin yöllä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Mutta köyhän hän pelastaa heidän suunsa miekasta ja auttaa väkevän kädestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Vaivaisella on toivoa, mutta vääryyden täytyy sulkea suunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Katso, autuas se ihminen, jota Jumala rankaisee! Älä siis pidä halpana Kaikkivaltiaan kuritusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Sillä hän haavoittaa, ja hän sitoo, lyö murskaksi, mutta hänen kätensä myös parantavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Kuudesta hädästä hän pelastaa sinut, ja seitsemässä onnettomuus ei kohtaa sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'Nälänhädässä hän vapahtaa sinut kuolemasta ja sodassa miekan terästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Kielen ruoskalta sinä olet turvassa, etkä pelkää, kun hävitys tulee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Hävitykselle ja kalliille ajalle sinä naurat, etkä pelkää metsän petoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Sillä kedon kivien kanssa sinä olet liitossa, ja aron pedot elävät kanssasi rauhassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Saat huomata, että telttamajasi on rauhoitettu, ja kun tarkastat asuinsijaasi, et kaipaa sinne mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Niin saat huomata, että siemenesi on runsas ja vesasi monet kuin ruoho maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Ikäsi kypsyydessä sinä menet hautaan, kuin lyhde korjataan ajallaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Katso, tämän olemme tutkineet, ja niin se on. Kuule se, ja ota sinäkin vaari siitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, '\"Oi, jospa suruni punnittaisiin ja kova onneni pantaisiin sen kanssa vaakaan!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Sillä se on nyt raskaampi kuin meren hiekka. Sen tähden sanani menevät hukkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Sillä Kaikkivaltiaan nuolet ovat sattuneet minuun, henkeni juo niiden myrkkyä ja Jumalan kauhut ahdistavat minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Huutaako villiaasi vihannassa ruohikossa, ammuuko härkä rehuviljansa ääressä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Voiko mautonta syödä ilman suolaa, ja onko munanvalkuaisessa makua ilman suolaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Sieluni ei tahdo koskea sellaiseen. Se on minulle kuin saastainen ruoka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Oi, jospa pyyntöni täyttyisi ja Jumala toteuttaisi, mitä häneltä toivon!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Jospa Jumala suvaitsisi musertaa minut, ojentaa kätensä ja katkaista elämäni langan!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Vielä olisi lohdutuksenani ja iloitsisin ahdistuksessani, ettei hän säästäisi minua, sillä enhän ole kätkenyt Pyhän sanoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Mikä on voimani, että enää toivoisin, ja mikä on loppuni, että sieluni olisi kärsivällinen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Onko voimani vahva kuin kivi, onko ruumiini vaskea?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Eikö minulla ole enää mitään apua, ja enkö voi enää mitään?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Tuleehan ystävän olla laupias nääntyvälle, vaikka tämä olisikin hylännyt Kaikkivaltiaan pelon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Veljeni ovat petolliset kuin purot, kuin purojen uomat, jotka juoksevat kuiviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Ne ovat sohjosta sameat, ja lumi ne peittää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Auringon paahteessa ne ehtyvät ja häviävät paikaltaan helteen tullen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Niiden juoksu-urat mutkistuvat, ne haihtuvat tyhjiin ja katoavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Teeman karavaanit tähystelivät, Seban karavaanit odottivat niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Ne, jotka niihin luottavat, joutuvat häpeään ja pettyvät perille tullessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Te olette nyt tyhjän veroiset: te näitte kauhun ja pelästyitte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Olenko sanonut: \'Tuokaa minulle ja suorittakaa varoistanne lahjus puolestani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'pelastakaa minut vihollisen vallasta ja lunastakaa minut väkivaltaisten käsistä\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Opettakaa minua, niin minä vaikenen, ja neuvokaa minulle, missä olen erehtynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Kuinka tehoaakaan oikea puhe! Mutta mitä merkitsee teidän nuhtelunne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Te mietitte sanoja nuhdellaksenne? Tuuleen häipyvät epätoivon sananne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Orvostakin te heittäisitte arpaa ja hieroisitte kauppaa ystävästänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Mutta suvaitkaa nyt kääntyä minuun. En totisesti valehtele vasten kasvojanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Palatkaa, älköön vääryyttä tapahtuko. Palatkaa, vielä minä olen oikeassa siinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Olisiko kielelläni vääryys? Eikö kitalakeni tuntisi, mikä on turmioksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, '\"Eikö ihmisen olo maan päällä ole sotapalvelusta, eivätkö hänen päivänsä ole kuin palkkalaisen päivät?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Hän on orjan kaltainen, joka haluaa varjoon, ja kuin palkkalainen, joka odottaa palkkaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Minä olen perinyt kurjuuden kuukaudet, ja vaivan yöt ovat tulleet osakseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Maata mennessäni ajattelen: Milloin saan nousta? Ilta venyy, ja kyllästyn kääntelehtiessäni aamuhämärään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Ruumiini verhoutuu matoihin ja tomuun, ihoni kovettuu ja märkii.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Päiväni kiitävät nopeammin kuin sukkula, ne katoavat toivottomuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Muista, että elämäni on tuulen henkäys eikä silmäni saa enää nähdä onnea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Sen silmä, joka minut näki, ei minua enää näe. Silmäsi etsivät minua, mutta minua ei enää ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Pilvi häipyy ja menee menojaan; niin ei myöskään hautaan vaipunut sieltä nouse.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Hän ei palaa enää taloonsa, eikä hänen asuinsijansa häntä enää tunne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Niin en minäkään hillitse suutani, puhun henkeni ahdistuksessa ja valitan sieluni murheessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Olenko minä meri tai lohikäärme, että asetat vartioston minua vastaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Kun ajattelen: leposijani lohduttaa minua, vuoteeni huojentaa tuskaani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'niin sinä kauhistutat minua unilla ja pelästytät minua näyillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Mieluummin tukehdun, mieluummin kuolen, kuin näin kidun luurankona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Olen kyllästynyt, en tahdo elää iän kaiken, anna minun olla rauhassa, sillä tuulen henkäystä ovat päiväni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Mikä on ihminen, että hänestä niin suurta lukua pidät ja että kiinnität häneen huomiosi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'tarkastat häntä joka aamu, tutkit häntä joka hetki?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Etkö koskaan käännä katsettasi minusta pois, etkö hellitä minusta sen vertaa, että saan sylkeni nielaistuksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Jos olenkin syntiä tehnyt, niin mitä sillä olen sinulle tehnyt, sinä ihmisten vartija? Minkä tähden asetit minut maalitauluksesi, ja minkä tähden tulin itselleni taakaksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Minkä tähden et anna rikostani anteeksi etkä poista pahaa tekoani? Sillä nyt menen levolle maan tomuun, ja jos etsit minua, ei minua enää ole.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Sitten suuhilainen Bildad lausui ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, '\"Kuinka kauan sinä puhut sellaisia ja suusi sanat ovat kuin rajumyrsky?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Jumalako vääristäisi oikeuden, Kaikkivaltiasko vääristäisi vanhurskauden?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Jos lapsesi tekivät syntiä häntä vastaan, hän hylkäsi heidät heidän rikoksensa valtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Jos sinä etsit Jumalaa ja anot Kaikkivaltiaalta armoa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'jos olet puhdas ja rehellinen, silloin hän varmasti herää avuksesi ja asettaa entiselleen asuntosi vanhurskautesi tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Silloin alkusi näyttää vähäiseltä, mutta loppuaikasi kasvaa hyvin suureksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Sillä kysy aikaisemmalta sukupolvelta ja ota selvää, mitä heidän isänsä ovat tutkineet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Mehän olemme eilispäivän lapsia emmekä tiedä mitään, ja päivämme ovat vain varjo maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'He opettavat sinua ja puhuvat sinulle, tuovat ilmi sanat sydämestään:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, '\'Kasvaako kaisla siinä, missä ei ole suota? Rehottaako ruoko siinä, missä ei ole vettä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Vielä vihreänä ollessaan, ja ennen kuin se on valmis leikattavaksi, se kuivettuu ennen kuin mikään muu heinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Niin käy kaikkien niiden, jotka unohtavat Jumalan, ja jumalattoman toivo katoaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'hänen, jonka uskallus on langan varassa, jonka turvana on hämähäkinverkko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Hän nojaa taloonsa, mutta se ei pysy pystyssä, hän tarttuu siihen, mutta se ei kestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Hän on rehevänä auringon paisteessa, ja hänen vesansa leviävät yli puutarhan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Hänen juurensa kietoutuvat kivikkoon, ja hän kiinnittää katseensa kivitaloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Mutta kun Jumala hävittää hänet hänen paikaltaan, se kieltää hänet: En ole koskaan sinua nähnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Katso, siinä oli hänen vaelluksensa ilo, ja tomusta kasvaa toisia.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Katso, Jumala ei hylkää nuhteetonta eikä tartu pahantekijöiden käteen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'kunnes hän täyttää suusi naurulla ja huulesi riemulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Vihamiehesi verhotaan häpeällä, eikä jumalattomien telttamajaa enää ole.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, '\"Totisesti minä tiedän, että niin on. Kuinka ihminen voi olla oikeassa Jumalaa vastaan!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Jos ihminen tahtoisi riidellä hänen kanssaan, hän ei voisi vastata hänelle yhteenkään tuhannesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Hän on viisas mieleltään ja väkevä voimaltaan. Kuka on onnistunut nousemaan häntä vastaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Hän siirtää vuoret äkkiarvaamatta ja kukistaa ne vihassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Hän järkyttää maan paikaltaan, ja sen perustukset vapisevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Hän kieltää aurinkoa, eikä se nouse, ja hän lukitsee tähdet sinetillään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Hän yksinään levittää taivaat ja tallaa meren kukkuloita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Hän loi Ašin, Kesilin, Kiiman, ja etelän tähtitarhat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Hän tekee suuria, tutkimattomia tekoja, ihmeitä ilman määrää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Katso, hän käy ohitseni, enkä häntä näe; hän liitää ohi, enkä häntä huomaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Katso, hän tempaa saaliinsa, kuka voi häntä estää, kuka sanoa hänelle: \'Mitä sinä teet?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Jumala ei käänny vihastaan. Hänen alleen vaipuivat Rahabin auttajat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Minäkö sitten voisin vastata hänelle ja valita sanani häntä vastaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Vaikka olisinkin oikeassa, en saisi vastatuksi. Minun täytyisi anoa armoa tuomariltani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Jos huutaisin ja hän vastaisikin minulle, en usko, että hän ottaisi huutoani korviinsa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'hän, joka ajaa minua takaa myrskytuulessa ja lisää haavojeni lukua syyttä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'joka ei anna minun vetää henkeä, vaan täyttää minut katkeralla tuskalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Jos väkevän voimaa kysytään, hän sanoo: \'Tässä olen!\' mutta jos oikeutta, niin: \'Kuka vetää minut tilille?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Vaikka olisin oikeassa, oma suuni tuomitsisi minut syylliseksi. Vaikka olisin syytön, hän kuitenkin tekisi minut vääräksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Syytön minä olen. En välitä hengestäni, elämäni on minulle halpa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Yhdentekevää kaikki. Sen tähden sanon: hän lopettaa niin syyttömän kuin syyllisenkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Jos ruoska äkkiä surmaa, hän pilkkaa viattomien epätoivoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Maa on jätetty jumalattoman valtaan. Hän peittää sen tuomarien kasvot – ellei hän, kuka sitten?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Minun päiväni rientävät juoksijaa nopeammin ja pakenevat onnea näkemättä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Ne kiitävät pois kuin ruokoveneet, kuin kotka, joka iskee saaliiseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Jos ajattelen: tahdon unohtaa tuskani, muuttaa muotoni ja tulla iloiseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'niin minä kauhistun kaikkia kipujani, tiedän, ettet julista minua viattomaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Syyllisenä täytyy minun olla. Miksi vaivaan itseäni turhaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Jos vaikka lumessa peseytyisin ja puhdistaisin käteni lipeällä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'silloinkin sinä upottaisit minut likakuoppaan, niin että omat vaatteeni inhoaisivat minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Sillä hän ei ole ihminen kuten minä voidakseni vastata hänelle ja käydäksemme oikeutta keskenämme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Meillä ei ole riidanratkaisijaa, joka laskisi kätensä meidän molempien päälle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'ja ottaisi hänen vitsansa pois päältäni, niin ettei hänen kauhunsa pelästyttäisi minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'Puhuisin enkä häntä pelkäisi, sillä vääryys ei olisi kanssani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, '\"Sieluni on kyllästynyt elämään. Päästän valitukseni valloilleen ja puhun sieluni murheessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'sanon Jumalalle: \'Älä tuomitse minua syylliseksi; ilmaise minulle, miksi vaadit minut tilille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Onko sinulla hyötyä siitä, että teet väkivaltaa, että oman käsialasi hylkäät, mutta valaiset jumalattomien neuvoa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Onko sinulla lihan silmät, katsotko, niin kuin ihminen katsoo?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Ovatko päiväsi kuin ihmisen päivät ja ovatko vuotesi kuin miehen vuodet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'koska etsit vääryyttä minusta ja tutkit syntiäni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'vaikka tiedät, etten ole syyllinen ja että ei ole ketään, joka auttaa käsistäsi?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Kätesi ovat minut luoneet ja tehneet. Yhtä kaikki sinä tuhoat minut perin juurin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Muista, että sinä olet muovaillut minua kuin savea, ja nyt muutat minut tomuksi jälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Etkö sinä valanut minua kuin maitoa ja juoksuttanut kuin juustoa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Sinä puetit minut nahalla ja lihalla ja kudoit minut kokoon luista ja jänteistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Elämän ja armon sinä olet minulle suonut, ja huolenpitosi on varjellut henkeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Mutta sinä kätkit sydämeesi tämän. Tiedän, että tämä oli mielessäsi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'jos minä syntiä tein, sinä vartioit minua, etkä antanut rikostani anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Jos olisin syyllinen, niin voi minua! Ja vaikka olisin oikeassa, en kuitenkaan voisi päätäni nostaa, häpeästä kylläisenä ja kurjuuttani katsellen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Jos pääni nousee, sinä ajat minua kuin leijona ja teet yhä ihmeitäsi minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Sinä hankit yhä uusia todistajia minua vastaan, ja vihasi minuun kasvaa, ja sinä tuot toiset joukot kimppuuni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Miksi toit minut ilmoille äitini kohdusta? Jospa olisin kuollut ihmissilmän näkemättä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Olisin, kuin minua ei olisi ollutkaan, ja minut olisi kannettu äidin kohdusta hautaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Ovathan päiväni vähän aikaa kestävät. Hän antakoon minun olla rauhassa, hän kääntyköön minusta pois, että voisin iloita vähän aikaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'ennen kuin lähden pimeyden ja kuoleman varjon maahan sieltä koskaan palaamatta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'maahan, jonka pimeys on synkkä kuoleman varjo ja sekasorto ja jossa valkeneminenkin on pimeyttä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Sitten naemalainen Soofar lausui ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, '\"Jäisikö suulas puhe vastausta vaille, ja saisiko suupaltti olla vanhurskas?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Saattaisivatko jaarituksesi miehet vaikenemaan, niin että saisit pilkata eikä kukaan saattaisi sinua häpeään?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Sanothan: \'Opetukseni on selkeää, ja olen puhdas silmissäsi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Mutta jospa Jumala puhuisi ja avaisi huulensa sinua vastaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'ja ilmaisisi sinulle viisauden salaisuudet, että sinulle olisi tarvinnut tuoda viisautta kaksi kertaa enemmän, että huomaisit, että Jumala on unohtanut syntejäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Tutkimallako löytäisit Jumalan tutkimattomuuden ja yltäisit Kaikkivaltiaan täydellisyyteen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Se on korkea kuin taivas – mitä voit tehdä, syvempi kuin helvetti – mitä voit ymmärtää?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Se on pitempi kuin maa ja laajempi kuin meri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Jos hän kääntäisi ne toisinpäin tai peittäisi tai kokoaisi yhteen, kuka voi saattaa sen ennalleen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Sillä hän tuntee turhuuden miehet ja vääryyden hän näkee tutkimattakin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Tyhjä mies viisastuu, vaikka ihminen syntyy villiaasin varsana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Jos sinäkin valmistat sydämesi ja ojennat kätesi hänen puoleensa –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'mutta jos kädessäsi on vääryys, heitä se kauas äläkä anna petoksen asua majoissasi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, '– silloin saat kohottaa kasvosi ilman häpeän tahraa, olet luja etkä pelkää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Silloin sinä unohdat vaivasi ja muistelet sitä kuin vettä, joka on virrannut pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'Elämäsi nousee keskipäivää kirkkaampana, pimeänkin aika on kuin aamu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Silloin olet turvassa, sillä sinulla on toivo; tähystelet – käyt turvallisesti levolle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'asetut makaamaan kenenkään pelottamatta, ja monet kääntyvät puoleesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Mutta jumalattomien silmät raukeavat, turvapaikka on heiltä mennyt, ja heidän toivonsa on kuin huokaus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, '\"Totisesti, te olette kansa, ja teidän mukananne kuolee viisaus!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Onhan minullakin ymmärrystä yhtä hyvin kuin teillä. Minä en ole teitä huonompi, ja kukapa ei noita tietäisi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Minä, jota hänen ystävänsä pilkkasi, huusin Jumalaa avuksi, ja hän vastasi minulle. Pilkattu on vanhurskas ja nuhteeton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Turvassa elävä ajattelee, että onnettomuus on valmiina niille, joiden jalka kompastelee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Rauhassa ovat väkivaltaisten teltat, turvassa ne, jotka vihoittavat Jumalan, ne, jotka kantavat jumalaa kädessään. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Mutta kysypä eläimiltä, niin ne opettavat sinua, ja taivaan linnuilta, niin ne ilmoittavat sinulle;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'tai tutkistele maata, niin se opettaa sinua, ja meren kalat kertovat sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Kuka kaikista näistä ei tietäisi, että Herran käsi on tämän tehnyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'hänen, jonka kädessä on kaiken elävän sielu ja kaiken ihmisen lihan henki?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Eikö korva koettele sanoja ja kitalaki maista ruuan makua?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Vanhuksissa on viisaus, ja pitkään eläneissä ymmärrys. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Jumalalla on viisaus ja voima, neuvo ja ymmärrys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Minkä hän repii maahan, sitä ei rakenneta. Kenet hän telkeää sisälle, sille ei avata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Katso, kun hän salpaa vedet, syntyy kuivuus. Kun hän laskee ne irti, ne mullistavat maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Hänen on väkevyys ja ymmärrys. Hänen on sekä eksynyt että eksyttäjä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Hän vie neuvonantajat paljasjalkaisiksi riisuttuina ja tekee tuomarit tyhmiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Kuningasten kurituksesta hän kirvoittaa ja vyöttää heidät yhteen heidän vyötäisiinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Hän vie papit pois paljasjalkaisiksi riisuttuina, ja pitkään eläneet hän kukistaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Hän hämmentää luotettavien puheen ja ottaa pois vanhoilta arviointikyvyn.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Hän vuodattaa ylenkatseen ruhtinaiden päälle ja heikentää mahtavien voiman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Hän paljastaa syvyydet pimeyden peitosta ja tuo sieltä valoon kuolemanvarjon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Hän korottaa kansat, ja hän hävittää ne. Hän laajentaa kansakunnat, ja hän kuljettaa ne pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Maan kansan päämiehiltä hän ottaa ymmärryksen ja panee heidät harhailemaan tiettömissä autiomaissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'He haparoivat pimeässä valoa vailla, ja hän saattaa heidät eksyksiin kuin juopuneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Katso, kaikkea tätä silmäni on nähnyt, korvani kuullut ja olen sen ymmärtänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Minkä te tiedätte, sen tiedän minäkin. Minä en ole teitä huonompi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Mutta minä haluan puhua Kaikkivaltiaalle ja mielelläni mitellä Jumalan kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Mutta te voitelette väärin ja olette kaikki puoskareita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Jospa edes osaisitte vaieta, se olisi teille viisaudeksi!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Kuulkaa perusteluani ja ottakaa huomioon, mitä huuleni väittävät vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Tahdotteko puolustaa Jumalaa väärällä puheella ja puhua petollisesti hänen puolestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Tahdotteko olla puolueellisia hänen hyväkseen ja ajaa Jumalan asiaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Koituuko siitä silloin hyvää, kun hän käy teitä tutkimaan; tai voitteko pettää hänet, niin kuin ihminen petetään?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Hän rankaisee teitä ankarasti, jos salassa olette puolueellisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Eikö hänen korkeutensa pelästytä teitä ja hänen kauhunsa valtaa teidät?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Tuhkaa ovat mietelauseenne, savea selustanne linnakkeet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Vaietkaa minusta, minä puhun, käyköön minun miten tahansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Miksi otan lihani hampaisiini ja panen henkeni kämmenelleni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Katso, vaikka hän minut surmaisi, häneen panen toivoni. Tahdon kuitenkin puolustaa vaellustani häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Jo sekin on minulle pelastukseksi, sillä jumalaton ei voi astua hänen kasvojensa eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Kuulkaa tarkasti puhettani, ja sitä, mitä lausun korvienne kuullen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Katso, olen jo langettanut tuomiopäätöksen. Tiedän, että minä olen vanhurskas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Kuka saattaa käräjöidä minua vastaan? Sillä nyt vaikenen ja kuolen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Kahta vain älä minulle tee, niin en kätkeydy kasvojesi edestä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Ota kätesi pois päältäni älköönkä kauhusi minua pelottako.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Kutsu, minä vastaan, tai minä puhun, ja sinä vastaat minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Mikä on minun pahojen tekojeni ja syntieni luku? Ilmaise minulle rikkomukseni ja syntini.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Miksi peität kasvosi ja pidät minua vihollisenasi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Lentävää lehteäkö pelästytät, kuivunutta korttako vainoat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'koskapa kirjoitat katkeruuden osakseni ja perinnökseni nuoruuteni pahat teot,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'koska panet jalkani jalkapuuhun, vartioit kaikkia polkujani ja seuraat jalkapohjieni jälkiä? –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'Hän hajoaa kuin lahopuu, kuin koinsyömä vaate.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Ihminen, vaimosta syntynyt, elää vähän aikaa ja on täynnä levottomuutta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'kasvaa kuin kukkanen ja lakastuu, pakenee kuin varjo eikä pysy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Sellaista sinä pidät silmällä ja viet minut käymään oikeutta kanssasi!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Kuka synnyttäisi saastaisesta puhtaan? Ei yhden yksikään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Hänen päivänsä ovat määrätyt, ja hänen kuukausiensa luku on sinulla tiedossa. Sinä olet asettanut hänelle määrän, jonka yli hän ei pääse.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Käännä katseesi pois hänestä, että hän pääsisi rauhaan. Sitä hän odottaa kuin palkkalainen päivän päättymistä siihen asti, kunnes hänen aikansa tulee täyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Onhan puullakin toivo: vaikka se maahan kaadetaan, se kasvaa uudelleen, eikä siltä puutu vesaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Vaikka sen juuri vanhenee maassa ja sen kanto kuolee multaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'se veden tuoksusta versoo jälleen ja tekee oksia kuin istukas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Mutta kun mies kuolee, hän makaa elottomana. Kun ihminen on henkensä heittänyt, missä hän on?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Vesi juoksee pois järvestä, ja joki tyhjenee ja kuivuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Niin ihminen makaa eikä enää nouse. Niin kauan kun taivaat ovat, he eivät herää eivätkä havahdu unestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Oi, jospa kätkisit minut hautaan ja piilottaisit minut, kunnes vihasi on asettunut, panisit minulle aikamäärän ja sitten muistaisit minua!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Kun mies kuolee, virkoaako hän jälleen henkiin? Odottaisin kaikki sotapalvelukseni päivät, kunnes minut vapautettaisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Sinä kutsuisit, ja minä vastaisin sinulle, sinä ikävöisit kättesi tekoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Sillä nyt sinä lasket askeleeni etkä pidä vaaria synnistäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Rikokseni olisi sinetillä lukittuna kukkaroon, ja pahat tekoni sinä peittäisit piiloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Mutta vuorikin vyöryy ja hajoaa, ja kallio siirtyy sijaltaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'vesi kuluttaa kivet, ja rankkasade huuhtoo pois maan mullan, mutta ihmisen toivon sinä hävität.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Sinä masennat hänet iäksi, ja hän lähtee. Sinä muutat hänen kasvojensa ilmeen ja lähetät hänet menemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Ovatko hänen lapsensa kunniassa – sitä hän ei tiedä, vai ovatko he pieniä – siitä hän ei pääse perille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Hänen ruumistaan särkee, ja hänen sielunsa kärsii.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Sitten teemanilainen Elifas lausui ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, '\"Vastaako viisas tuulta pieksämällä, täyttääkö hän rintansa itätuulella?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Puolustautuuko hän puheella, joka ei auta, ja sanoilla, joista ei ole hyötyä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Itse jumalanpelonkin sinä teet tyhjäksi ja pidät vähäisenä asiana puhua Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Sillä pahuutesi panee sanat suuhusi, ja olet valinnut viekasten kielen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Oma suusi julistaa sinut syylliseksi, enkä minä. Omat huulesi vastatkoot sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Sinäkö synnyit ihmisistä ensimmäisenä, luotiinko sinut ennen kukkuloita?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Olitko sinä kuulijana Jumalan neuvottelussa ja pidätkö Viisautta itseäsi vähäisempänä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Mitä tiedät, jota me emme tietäisi? Mitä ymmärrät, josta meillä ei olisi tietoa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Onpa meidänkin joukossamme harmaapää ja vanhus, isääsi vanhempi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Väheksytkö Jumalan lohdutuksia ja sanaa, joka oli sinulle hellä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Miksi sydämesi vie sinua mukanaan ja miksi silmäsi välkehtivät,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'niin että käännät henkesi Jumalaa vastaan ja syydät suustasi sanoja?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Kuinka voisi ihminen olla puhdas, kuinka vaimosta syntynyt olla vanhurskas!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Katso, pyhiinsäkään hän ei luota eivätkä taivaatkaan ole puhtaat hänen silmissään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'saati sitten ihminen, inhottava ja kelvoton, joka juo vääryyttä kuin vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Julistan sinulle, kuule minua, kerron, mitä olen nähnyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'mitä viisaat ilmoittavat, salaamatta, mitä olivat isiltään saaneet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'niiltä, joille maa oli yksinomaan annettu ja joiden seassa ei muukalainen liikkunut:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Jumalattomalla on tuska kaikkina elinpäivinään, ja valtiaan vuosien luku on häneltä salattu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Kauhun äänet kuuluvat hänen korvissaan, keskellä rauhaakin saapuu hävityksen tuoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Hän ei usko pääsevänsä pimeydestä, ja hänet on miekalle määrätty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Hän etsii leipää kaikkialta ja kysyy: missä sitä on? Hän tietää, että pimeyden päivä on jo valmiina käsillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Tuska ja ahdistus kauhistuttavat häntä, lyövät hänet kuin kuningas valmiina hyökkäykseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Koska hän ojensi kätensä Jumalaa vastaan ja pöyhkeili Kaikkivaltiasta vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'hän ryntäsi häntä vastaan niska jäykkänä paksu kilpi suojanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Koska hän kasvatti ihraa kasvoihinsa ja teki lanteensa lihaviksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'hän tulee asumaan hävitetyissä kaupungeissa, taloissa, jotka ovat raunioina,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'sen tähden hän ei rikastu, eikä hänen omaisuutensa ole pysyvää, eikä hänen viljansa notku maata kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Hän ei pääse pimeydestä. Tulen liekki kuivattaa hänen vesansa, ja hän hukkuu suunsa henkäyksestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Hän ei kestä, sillä hän pettyy ja hänen voittonsa on oleva turhuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Hänen päivänsä eivät täyty, eikä hänen lehvänsä vihannoi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Hän on kuin viinipuu, joka pudottaa raakileensa, kuin öljypuu, joka varistaa kukkansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Sillä jumalattoman joukko on hedelmätön, ja tuli kuluttaa lahjusten ottajan teltat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'He ovat raskaana tuhosta ja synnyttävät turmiota, ja heidän kohtunsa valmistaa petosta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, '\"Tuollaista olen paljon kuullut. Surkeita lohduttajia olette kaikki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Eikö tule jo loppua tuuleen puhumisesta, vai mikä panee sinut noin vastaamaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Minäkin puhuisin kuin te, jos te olisitte minun sijassani. Voisin sommitella sanoja teitä vastaan ja ilkkuen nyökytellä teille päätäni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'rohkaista teitä suullani ja tuottaa huojennusta huuliani liikuttamalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Jos puhun, ei tuskani helpotu, ja jos lakkaan, lähteekö se sillä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Mutta nyt hän on minut uuvuttanut. Sinä olet hävittänyt koko joukkoni');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'ja olet tehnyt minut kurttuiseksi todisteena minua itseäni vastaan. Myös raihnaisuuteni nousee minua vastaan syyttäen minua vasten kasvoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Hänen vihansa repi ja vainosi minua, ja hän kiristeli minulle hampaitaan. Viholliseni hioo katsettaan minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'He ovat avanneet minulle kitansa ja lyövät häväisten minua poskelle. Kaikki he ovat yhtyneet minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Jumala on jättänyt minut pahojen valtaan ja syössyt minut jumalattomien käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Elin rauhassa, mutta hän pelästytti minut. Hän tarttui minua niskasta ja murskasi minut. Hän asetti minut maalitaulukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Hänen ampujansa ovat piirittäneet minut. Hän on halkaissut munuaiseni säälimättä ja vuodattaa maahan sappeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Hän murtaa minuun aukon toisensa jälkeen ja ryntää kimppuuni kuin sankari.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Minä ompelin säkin iholleni ja painoin sarveni tomuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Kasvoni punottavat itkusta, ja silmäluomillani on kuoleman varjo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'vaikka käsissäni ei ole vääryyttä ja vaikka rukoukseni on puhdas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Maa, älä peitä vertani, ja älköön valitukselleni olko paikkaa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Katso, nytkin on todistajani taivaassa ja puolustajani korkeudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Ystäväni pitävät minua pilkkanaan – mutta silmäni katsoo kyynelehtien Jumalaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Jospa mies voisi käydä oikeutta Jumalan kanssa kuin ihmislapsi lähimmäisensä kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Sillä vuosieni määrälle tulee loppu, ja sitten menen tietä, jota en palaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, '\"Henkeni on rikki raastettu, päiväni sammuvat, hautausmaa on osani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Totisesti, pilkka piirittää minua ja silmäni täytyy katsella, kun he nousevat minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Asetu itse takaamaan minut. Kuka muu ryhtyisi kättä lyöden takaajakseni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Sillä sinä olet sulkenut heidän sydämensä ymmärrykseltä. Sen tähden sinä et päästä heitä voitolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Ystäviä kutsutaan osajaolle, mutta omilta lapsilta raukeavat silmät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Minut on pantu kansoille sananlaskuksi. Olen kasvoille syljettävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Silmäni on hämärtynyt surusta, ja kaikki jäseneni ovat kuin varjo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Tästä oikeamieliset hämmästyvät, ja viattomat nousevat jumalattomia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Mutta vanhurskas pysyy tiellään, ja se, jolla on puhtaat kädet, kasvaa voimassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Mutta te kaikki, tulkaa jälleen tänne. En löydä viisasta joukostanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Päiväni ovat menneet, rauenneet ovat sydämeni ajatukset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Yöstä he ovat tehneet päivän, ja valo muka lähenee yön kasvoilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Jos kuinka toivon, hauta on kuitenkin asuntoni. Levitän vuoteeni pimeyteen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'sanon haudalle: \'Sinä olet isäni\', ja madoille: \'Äitini ja sisareni.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Missä silloin on toivoni, ja kuka saa katsella toivoani?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Ne astuvat alas hautaan, kun yhdessä lepäämme tomussa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Sitten suuhilainen Bildad lausui ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, '\"Kuinka kauan te asetatte sanoille ansoja? Tulkaa järkiinne, sitten puhumme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Miksi meitä pidetään nautoina, olemmeko silmissänne epäpuhtaita?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Sinä, joka raivossasi raatelet itseäsi – sinunko tähtesi jätettäisiin maa autioksi ja kallio siirtyisi paikaltaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Myös jumalattomien valo sammuu, eikä sellaisen tulen liekki loista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'Valo pimenee hänen teltassaan, ja lamppu sammuu hänen päänsä päältä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Hänen väkevät askeleensa lyhenevät, ja hänen oma neuvonsa langettaa hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Sillä hänen omat jalkansa vievät hänet verkkoon, ja hän käyskentelee katetun pyyntihaudan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Paula tarttuu hänen kantapäähänsä, ja ansa tarttuu häneen lujasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Häntä varten on maahan kätketty pyydys ja polulle silmukka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Kauhut pelästyttävät hänet kaikkialla ja saavat hänet harhailemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Häntä vaivaa nälkä, ja onnettomuus on valmiina kaatamaan hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Hänen ruumiinsa jäseniä kalvaa, hänen jäseniään kalvaa kuoleman esikoinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Hänet temmataan pois toivonsa teltasta, ja hänet pannaan astumaan kauhujen kuninkaan luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Hänen teltassaan ei ole asujia, ja hänen asuinpaikalleen sirotellaan rikkiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Alhaalta kuivuvat hänen juurensa, ja ylhäältä kuihtuvat hänen oksansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Hänen muistonsa katoaa maasta, eikä hänen nimeään kadulla mainita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Hänet sysätään valosta pimeyteen ja karkotetaan maan piiristä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Ei lapsia eikä jälkeläisiä ole hänellä kansansa seassa, eikä ketään jää jäljelle hänen asuinpaikalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Ne, jotka ovat hänen jälkeensä, hämmästyvät hänen päiväänsä, ja ne jotka ovat olleet ennen häntä, pelästyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Näin käy väärintekijöiden huoneelle, näin sen asuinpaikalle, joka ei Jumalaa tunne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, '\"Kuinka kauan te vaivaatte sieluani ja runtelette minua sanoillanne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Te olette jo kymmenenkin kertaa minua häväisseet, ja häpeämättä te minua ahdistatte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Jos olen todella hairahtunut, jääkö hairahdukseni luokseni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Tai voitteko todella ylvästellä minua vastaan ja todistaa minun ansainneen häpeäni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Tietäkää siis, että Jumala tekee minulle vääryyttä ja on kietonut minut verkkoonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Katso, minä huudan: \'Väkivaltaa!\' enkä saa vastausta. Huudan apua, mutta ei ole oikeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Hän on aidannut tieni, niin etten pääse yli, ja hän on levittänyt pimeyden poluilleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Hän on riisunut minulta kunniani ja ottanut kruunun päästäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Hän repi minut maahan joka puolelta, niin että olen mennyttä, ja hän tempasi irti toivoni kuin puun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Hän on päästänyt vihansa syttymään minua vastaan ja pitää minua vihollisenaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Hänen sotajoukkonsa tulivat yhdessä ja tekivät tiensä minua vastaan ja leiriytyivät telttani ympärille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Veljeni hän on minusta loitontanut. Tuttavani ovat minusta aivan vieraantuneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Läheiseni ovat minusta luopuneet, ja uskottuni ovat unohtaneet minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Ne, jotka talossani majailevat, ja palvelijattareni pitävät minua muukalaisena, minä olen tullut vieraaksi heidän silmissään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Minä kutsuin palvelijaani, eikä hän vastannut. Omalla suullani minun täytyy nöyrästi häntä rukoilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Hengitykseni on vastenmielinen vaimolleni, ja minun täytyy pyydellä lastenlasteni suosiota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Poikasetkin halveksivat minua. Kun nousen, he pilkkaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Kaikki uskotut ystäväni inhoavat minua, ja ne, joita rakastin, ovat kääntyneet minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Luuni ovat tarttuneet kiinni nahkaani, ihooni, eikä minusta ole enää kuin ikenet jäljellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Armahtakaa minua, armahtakaa minua, te, minun ystäväni, sillä Jumalan käsi on minuun koskenut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Miksi vainoatte minua Jumalan tavoin ettekä tule kylläisiksi lihastani?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Kunpa sanani kirjoitettaisiin muistiin ja jospa ne piirrettäisiin kirjaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'kaiverrettaisiin ainiaaksi kallioon rautataltalla ja lyijyllä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Mutta minä tiedän Lunastajani elävän, ja hän on nouseva takaajana multien päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'Sitten minut kiedotaan tähän nahkaani ja olen ruumiistani käsin näkevä Jumalan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Häntä minä katselen, silmäni näkevät hänet, eikä hän ole minulle outo. Munuaiseni aivan pakahtuvat sisimmässäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Kun sanotte: \'Miksi vainoamme häntä!\' – ikään kuin minusta löydettäisiin asian juuri –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'niin pelätkää miekkaa, sillä viha kohtaa miekanalaisia pahoja töitä, tietääksenne, että on tuomio.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Haamatilainen Soofar lausui ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, '\"Tuohon ajatukseni tuovat vastauksen, ja kiirehdin vastaamaan siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Häpäisevää nuhdetta minun täytyy kuulla, mutta ymmärrykseni henki antaa minulle vastauksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Tuoko on sinulla tietona ikiajoista asti, siitä saakka, kun ihminen maan päälle pantiin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'Ei, vaan jumalattomien riemu loppuu lyhyeen, ja teeskentelijän ilo on vain silmänräpäys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Vaikka hänen suuruutensa kohoaisi taivaaseen ja hänen päänsä ulottuisi pilviin asti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'hän kuitenkin katoaa ainiaaksi oman saastansa lailla. Ne, jotka näkivät hänet, kysyvät: \'Missä hän on?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Kuin uni hän lentää pois, eikä häntä enää löydetä, ja hän häipyy kuin öinen näky.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Silmä, joka häntä katseli, ei katsele häntä enää, eikä hänen paikkansa häntä enää näe.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Hänen poikiensa täytyy etsiä köyhien suosiota, ja hänen kättensä on annettava pois hänen omaisuutensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Nuoruuden voimaa olivat täynnä hänen luunsa, mutta nyt ne makaavat tomussa hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Jos paha on makeaa hänen suussaan, hän kätkee sen kielensä alle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'säästää sitä eikä siitä luovu, vaan pitää sitä suussaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'niin tämä ruoka hänen sisällään muuttuu käärmeen myrkyksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Hän nieli rikkautta, ja hänen täytyy oksentaa se pois. Jumala ajaa sen ulos hänen vatsastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Käärmeiden myrkkyä hän imi, kyyn kieli hänet tappaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Hän ei saa katsella ilokseen puroja, ei hunaja- ja kermajokia ja -vadeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Hänen on annettava pois hankkimansa, eikä hän saa sitä itse niellä. Hänen ilonsa ei ole hänen voittamansa rikkauden veroinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Sillä hän on sortanut köyhiä ja hylännyt heidät. Hän ryösti itselleen taloja, joita hän ei rakentanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Sillä hän ei tuntenut vatsaansa kylläiseksi, eikä saa itseään himossaan täyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Mikään ei säilynyt hänen ahneudeltaan. Sen tähden hänen onnensa ei kestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Yltäkylläisyytensä runsaudessa hänellä on hätä, kaikkien köyhien kädet nousevat häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Kun hän on täyttämässä vatsaansa, Jumala lähettää hänen kimppuunsa vihansa hehkun ja antaa sen sataa hänen päälleen hänen syödessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Jos hän pakenee rautaisia aseita, hänet lävistää vaskijousi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Kun hän vetää ulos selästään nuolen, hänen sappensa lävitse käy miekan salama, ja kuoleman kauhut valtaavat hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Kaikki pimeys on varattu hänen aarteilleen. Hänet kuluttaa tuli kenenkään lietsomatta. Se syö, mitä on säilynyt hänen teltassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Taivas paljastaa hänen pahat tekonsa, ja maa nousee häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Se, mitä hänen talonsa tuotti, menee menojaan vihan päivänä kuin tulvavedet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Tämä on jumalattoman ihmisen osa Jumalalta, perintöosa, jonka Jumala hänelle määrää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, '\"Kuulkaa, kuulkaa sanojani ja olkoon se minulle teiltä lohdutuksena!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Kärsikää minua, että saan puhua. Kun olen puhunut, pilkatkaa sitten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Ihmisellekö minä valitan? Tai kuinka en kävisi kärsimättömäksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Kääntykää minuun, niin kauhistutte ja pankaa kätenne suullenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Kun sitä ajattelen, pelästyn, ja vapina valtaa ruumiini:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Miksi jumalattomat saavat elää, vanheta, jopa vahvistua voimassa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Heidän siemenensä on vankkana heidän edessään ja heidän jälkeläisensä heidän silmiensä alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Heidän kotinsa ovat rauhassa, kauhuista kaukana, eikä Jumalan ruoska ole heidän yllään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Hänen sonninsa astuu eikä turhaan, hänen lehmänsä poikii eikä mene kesken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Poikansa he laskevat ulos kuin lammaslauman, ja heidän lapsensa hyppelehtivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'He virittävät laulujaan tamburiinein ja lyyran kaikuessa ja iloitsevat huilun soidessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'He viettävät päivänsä onnessa, mutta hetkessä he ovat helvetissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'He sanoivat Jumalalle: \'Mene pois luotamme, sinun teistäsi emme tahdo tietää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Mikä on Kaikkivaltias, että häntä palvelisimme? Ja mitä hyötyä meillä on siitä, että häntä rukoilemme?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Katso, heidän onnensa ei ole heidän omassa kädessään. Jumalattomien neuvo olkoon minusta kaukana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Kuinka usein jumalattomien lamppu sammuu ja heidät yllättää heidän turmionsa? Kuinka usein hän jakelee osat vihassaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'He ovat kuin tuulen viemät oljet, kuin akanat, jotka tuulispää tempaa mukaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Jumala muka säästää hänen lapsilleen hänen onnettomuutensa. Kostakoon Jumala hänelle itselleen, että hän sen tuntee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Nähköön hän perikatonsa omin silmin, juokoon itse Kaikkivaltiaan vihan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Sillä mitä hän välittää perheestään, jälkeensä jäävistä, kun hänen kuukausiensa luku on täysi!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Jumalalleko on opetettava tietoa, hänelle, joka tuomitsee korkeatkin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Toinen kuolee täysissä voimissaan, kaikessa rauhassa ja levossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Hänen astiansa ovat maitoa täynnä, ja hänen luunsa juotetaan ydinrasvalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Toinen kuolee katkeralla mielellä saamatta maistaa onnea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Yhdessä he panevat makaamaan multaan, ja madot peittävät heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Katso, minä tunnen teidän ajatuksenne ja juonet, joilla mielitte minua sortaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Kun sanotte: \'Missä on nyt ruhtinaan talo, missä teltta, jossa jumalattomat asuivat?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'niin ettekö ole kysyneet teitä kulkeneilta? Ettekö tunne heidän havaintojaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'että paha säästetään onnettomuuden päivälle, hänet kannetaan vihan päivään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Kuka ilmoittaa hänelle vasten kasvoja hänen tiensä, kuka kostaa hänelle hänen tekonsa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Hänet viedään hautaan, ja hänen hautapaikkaansa vartioidaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Makeaa oli hänelle laakson multa. Kaikki ihmiset seuraavat hänen jäljessään, ja niitä, jotka ovat menneet hänen edellään, on suuri joukko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Kuinka tuotte minulle niin turhaa lohdutusta? Vastauksistanne jää jäljelle pelkkä petos.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Teemanilainen Elifas lausui ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, '\"Taitaako ihminen hyödyttää Jumalaa? Ei, vaan ymmärtäväinen hyödyttää ainoastaan itseään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Onko Kaikkivaltiaalla etua siitä, jos olet vanhurskas, tai voittoa siitä, jos vaellat nuhteettomana?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Pelkäisikö hän nuhdella sinua ja astua kanssasi oikeuteen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Eikö pahuutesi ole suuri eikä synneilläsi ole loppua?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Sillä otithan veljiltäsi pantin syyttä ja riistit vaatteet alastomilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Et antanut nääntyvälle vettä juoda, ja nälkäiseltä kielsit leivän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Maa tuli vahvan miehen omaksi, ja vain korkea-arvoinen sai siinä asua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Lesket sinä lähetit luotasi tyhjin käsin, ja orpojen käsivarret murskattiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Sen tähden paulat nyt sinua ympäröivät, ja äkillinen pelko kauhistuttaa sinua –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'vai etkö näe pimeyttä? – ja vesitulva peittää sinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Eikö Jumala ole korkea kuin taivas? Katso, kuinka korkealla on tähtien laki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Mutta sinä sanot: \'Mitä Jumala tietää? Voiko hän tuomita paksujen pilvien takaa?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Pilvet ovat hänellä verhona, niin ettei hän näe; ja taivaanrannalla hän kuljeskelee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Tahdotko seurata iänikuista polkua, jota pahantekijät vaelsivat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'ne, jotka hävitettiin ennen aikojaan ja joiden perustuksen virta huuhtoi pois,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'jotka sanoivat Jumalalle: \'Poistu meistä. Mitä Kaikkivaltias voisi meille tehdä?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Kuitenkin hän oli täyttänyt heidän talonsa hyvyydellä. Mutta minusta olkoon kaukana jumalattomien neuvo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Vanhurskaat näkevät sen ja iloitsevat, ja viaton pilkkaa heitä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, '\'Totisesti, vastustajamme ovat hävinneet, ja mitä heistä jäi, sen kulutti tuli.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Tee siis sovinto ja elä rauhassa hänen kanssaan, niin siitä koituu sinulle paljon hyvää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Ota opetusta hänen suustaan ja kätke hänen sanansa sydämeesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Kun palaat Kaikkivaltiaan luo, tulet rakennetuksi ja karkotat vääryyden kauaksi teltaltasi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'panet kulta-aarteesi tomuun ja Oofirin kullan purojen kivien joukkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'Kaikkivaltias tulee kulta-aarteeksesi ja välkkyväksi hopeaksesi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'silloin on ilosi oleva Kaikkivaltiaassa, ja sinä nostat kasvosi Jumalan puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Kun rukoilet häntä, hän kuulee sinua, ja sinä saat täyttää lupauksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Jos mitä päätät, se sinulle onnistuu, ja sinun teillesi loistaa valo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Sinä sanot niistä, jotka nöyrtyvät, sanot: se on ylentämiseni, ja hän pelastaa nöyrtyneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Hän pelastaa senkin, joka ei ole viaton. Hän pelastuu kättesi puhtauden tähden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, '\"Tänäänkin on valitukseni katkeraa, ja käteni on raskas huokaukseni tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Oi, jospa tietäisin, kuinka voin löytää hänet, jospa pääsisin hänen asunnolleen!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Esittäisin hänen edessään riita-asian ja täyttäisin suuni todisteilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Tahtoisinpa tietää, mitä hän minulle vastaisi, ja kuulla, mitä hän minulle sanoisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Riitelisikö hän kanssani suurella voimallaan? Ei, hän vain tarkastelisi minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Silloin käräjöisi hänen kanssaan rehellinen mies, ja pelastuisin tuomaristani ainiaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Katso, menen itään, mutta hän ei ole siellä; menen länteen, enkä häntä huomaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Jos hän on vasemmalla, en häntä erota, jos hän kääntyy etelään, en häntä näe.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Sillä hän tietää tieni. Jos hän tutkisi minut, kullan kaltainen olisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Hänen askeleissaan on jalkani pysynyt, hänen tietään olen noudattanut siltä poikkeamatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Hänen huultensa käskystä en ole luopunut, hänen suunsa sanat olen kätkenyt tarkemmin kuin omat säädökseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Mutta hän on yksi, kuka voi häntä estää? Mitä hän tahtoo, sen hän tekee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Niin, hän panee täytäntöön minulle määrätyn osan, ja sellaista on hänellä vielä paljon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Sen tähden minut valtaa kauhu hänen kasvojensa edessä. Kun sitä ajattelen, pelästyn häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Jumala on tehnyt minut araksi, ja Kaikkivaltias on saattanut minut kauhun valtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Sillä en ole menehtynyt pimeään, eikä hän ole peittänyt pimeyttä kasvoiltani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, '\"Senkö tähden Kaikkivaltias ei ole varannut tuomion aikoja, ja miksi ne, jotka hänet tuntevat, eivät saa nähdä hänen päiviään?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'He siirtävät rajoja, ryöstävät laumoja ja laskevat ne laitumelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Orpojen aasin he vievät ja ottavat lesken lehmän pantiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'He työntävät tieltä köyhät, kaikkien maan kurjien täytyy piileskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Katso, nämä ovat kuin villiaasit erämaassa: lähtevät työhönsä saalista etsien, aro on heidän ja heidän lastensa leipä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Kedolta he korjaavat rehuviljaa ruuakseen, ja poimivat jumalattoman viinitarhasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Alastomina, ilman vaatteita, he viettävät yönsä, eikä heillä ole peittoa kylmässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'He ovat likomärkiä vuorilla vuotavasta sateesta, ja vailla suojaa he syleilevät kalliota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Äidin rinnoilta riistetään orpo, ja köyhältä otetaan pantti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'He kuljeskelevat alastomina, ilman vaatteita, ja nälkäisinä he kantavat lyhteitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'Jumalattomien tarhoissa he pusertavat öljyä ja polkevat viinikuurnaa ja ovat itse janoissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Kaupungista kuuluu miesten voihkina, ja haavoitettujen sielu huutaa, mutta Jumala ei ota pois heidän taakkaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Nuo ovat valon vihaajia, eivät tunne sen teitä eivätkä palaa sen poluille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Ennen päivän valkenemista nousee murhaaja, tappaa kurjan ja köyhän ja on yöllä kuin varas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Avionrikkojan silmä tähyilee hämärää ja sanoo: \'Yksikään silmä ei minua näe\', ja hän peittää kasvonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'He murtautuvat pimeässä taloihin, päivällä he sulkeutuvat sisään tahtomatta tietää valosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Sillä kuoleman varjo on heille kaikille aamun vertainen, koska he tuntevat kuoleman varjon kauhut.\" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, '\"Hän kiitää pois vetten viemänä. Kirottu on hänen peltopalstansa maassa. Hän ei enää käänny viinitarhojen tielle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Kuivuus ja kuumuus ahmaisevat lumiveden, samoin helvetti ne, jotka syntiä tekevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Äidin kohtu unohtaa hänet, madot syövät hänet herkkunaan. Häntä ei enää muisteta, ja vääryys murskataan kuin puu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Hän ryösti hedelmättömältä, joka ei synnytä, eikä hän tehnyt hyvää leskelle.\" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, '\"Hän vetää mahtavia voimallaan. Kun hän nousee, kukaan ei ole varma hengestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Hän antaa heidän olla turvassa, ja heillä on vahva tuki, ja hänen silmänsä valvovat heidän teitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'He ovat kohonneet korkealle vain vähäksi aikaa eikä heitä sitten enää ole. Heidät painetaan alas ja heidät korjataan pois kuten kaikki muutkin. He lakastuvat kuin tähkä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Eikö niin? Kuka osoittaa minut valehtelijaksi ja saattaa sanani tyhjiksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Sitten suuhilainen Bildad lausui ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, '\"Valta ja pelottavuus on sillä, joka luo rauhaa korkeuksissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Onko määrää hänen joukoillaan, ja kenellepä hänen valonsa ei koita?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Kuinka siis ihminen olisi vanhurskas Jumalan edessä, ja kuinka vaimosta syntynyt olisi puhdas?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Katso, ei kuukaan ole kirkas, eivätkä tähdetkään ole puhtaat hänen silmissään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'saati sitten ihminen, tuo mato, ja ihmisen poika, tuo toukka!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Siihen Job vastasi ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, '\"Kuinka oletkaan auttanut voimatonta ja tukenut heikkoa käsivartta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Kuinka oletkaan neuvonut sitä, jolla ei ole viisautta ja tehnyt tiettäväksi paljon terveellistä tietoa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Kenelle oikein olet sanasi puhunut, ja kenen henki on sinusta lähtenyt?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Vainajien henget värisevät vesien alla ja ne, jotka niissä asuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Helvetti on paljastettuna hänen edessään, eikä kadotuksella ole peitettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Pohjoisen hän kaarruttaa autiuden ylle ja ripustaa maan tyhjyyden päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Hän sitoo vedet pilviinsä, eivätkä pilvet halkea niiden alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Hän peittää valtaistuimensa näkyvistä ja levittää pilvensä sen yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Hän on vetänyt rajan vetten pinnalle, siihen missä valo päättyy pimeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Taivaan perustukset huojuvat ja hämmästyvät hänen nuhtelustaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Voimallaan hän kuohutti meren, ja taidollaan hän ruhjoi Rahabin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Hänen henkäyksestään kirkastui taivas; hänen kätensä lävisti pakenevan käärmeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Katso, nämä ovat ainoastaan hänen tekojensa ääriä, ja kuinka hiljainen onkaan kuiskaus, jonka hänestä kuulemme! Mutta kuka käsittää hänen väkevyytensä jyrinän?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Job jatkoi lausuen julki mietelmiään ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, '\"Niin totta kuin Jumala elää, joka on ottanut minulta oikeuteni, ja Kaikkivaltias, joka on murehduttanut sieluni:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'niin kauan kuin minussa vielä on henkeä ja Jumalan henkäystä sieraimissani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'eivät huuleni puhu petosta, eikä kieleni lausu vilppiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Pois se! En myönnä teidän olevan oikeassa. Siihen asti, kunnes heitän henkeni, en luovu syyttömyydestäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Pidän kiinni vanhurskaudestani, en hellitä. Yhdestäkään elämäni päivästä sydämeni ei minua soimaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Viholliselleni käy kuin jumalattomalle ja vastustajalleni kuin väärälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Mitä toivoa on pilkkaajalla, kun Jumala katkaisee hänen elämänsä ja tempaa pois hänen sielunsa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Kuuleeko Jumala hänen huutonsa, kun häntä kohtaa ahdistus?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Tai voiko hän iloita Kaikkivaltiaasta ja huutaa Jumalaa avukseen joka aika?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Opetan teille, mitä tekee Jumalan käsi, enkä salaa, mitä Kaikkivaltiaalla on mielessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Katso, itse olette kaikki sen nähneet. Miksi te kuvittelette turhia?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Tämä on jumalattoman ihmisen osa, Jumalan hänelle varaama. Tämä on perintöosa, jonka väkivaltaiset saavat Kaikkivaltiaalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Jos hänellä on paljonkin lapsia, he ovat miekan omia, eikä hänen jälkeläisilleen ole leipää ravinnoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Hänen jälkeenjääneensä haudataan, mutta hänen leskensä eivät pidä valittajaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Jos hän kokoaa hopeaa kuin multaa ja kasaa vaatteita kuin savea,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'mutta sen, minkä hän valmistaa, vanhurskas pukee päälleen, ja viaton perii hopean.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Hän rakentaa talonsa kuin koi ja kuin vartija katoksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Kun rikas menee levolle, hän ei saa mitään mukaansa, mutta kun hän avaa silmänsä, on kaikki mennyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Kauhut saavuttavat hänet kuin vesitulva, yöllä tempaa hänet mukaansa rajuilma.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Itätuuli vie hänet, niin että hän menee menojaan, ja se puhaltaa hänet pois paikaltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Hän käy häneen käsiksi eikä sääli häntä, että hän voisi paeta hänen käsistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Silloin paukutetaan hänelle kämmeniä ja vihelletään hänelle hänen asuinpaikaltaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, '\"Hopeallakin on suonensa ja löytöpaikkansa kullalla, joka puhdistetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Rauta otetaan maasta, ja kivestä sulatetaan vaski.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Tehdään loppu pimeydestä, ja tutkitaan tarkasti pimeässä ja kuolemanvarjossa ollut kivi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Kaivos louhitaan syvälle paikkoihin, joissa ei ole kuljettu. He riippuvat ja heiluvat poissa ihmisten ilmoilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Maa, josta kasvaa leipä, möyritään kuin tulen voimalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Sen kivissä on safiirilla sijansa, siellä on kultahiekkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Polkua sinne ei tiedä kotka, eikä haukan silmä sitä havaitse.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'Sitä eivät astu ylväät eläimet, eikä leijona sitä kulje.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'Siellä käydään käsiksi kovaan kiveen, ja vuoret mullistetaan juuriaan myöten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Kallioihin murretaan käytäviä, ja silmä näkee kaikenlaisia kalleuksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Vesisuonet estetään tihkumasta, ja salassa olleet saatetaan päivänvaloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Mutta viisaus – mistä se löytyy, ja missä on ymmärryksen olinpaikka?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Ihminen ei tiedä sille tietä, eikä sitä löydy elävien maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Syvyys sanoo: \'Se ei ole minussa\', ja meri sanoo: \'Se ei ole minunkaan luonani.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Sitä ei voida ostaa puhtaalla kullalla, eikä sen hintaa punnita hopeassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Sitä ei korvaa Oofirin kulta, ei kallis onyks-kivi eikä safiiri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Sille ei vedä vertoja kulta eikä lasi, eivät riitä sen vaihtohinnaksi aidosta kullasta tehdyt esineet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Koralleja ja kristalleja ei mainita sen rinnalla, ja viisauden omistaminen on helmiä kalliimpaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Sille ei vedä vertoja Kuusin topaasi, eikä sitä korvaa puhdas kulta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Mistä siis tulee viisaus ja missä on ymmärryksen olinpaikka?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Se on peitetty kaikkien elossa olevien silmiltä, ja se on salattu taivaan linnuiltakin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Kadotus ja kuolema sanovat: \'Korvamme ovat kuulleet siitä vain kerrottavan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Jumala tietää tien sen luo ja tuntee sen olinpaikan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Sillä hän katsoo maan ääriin saakka ja näkee kaiken, mitä taivaan alla on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Kun hän antoi tuulelle voiman ja asetti vedelle rajansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'kun hän sääti lain sateelle ja ukkospilvelle tien,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'silloin hän sen näki ja ilmoitti, toi sen esille ja sen myös tutki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Mutta ihmiselle hän sanoi: \'Katso, Herran pelko on viisautta, ja pahan karttaminen on ymmärrystä.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Job jatkoi lausuen mietelmiään ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, '\"Oi, jospa olisin, niin kuin olin tätä ennen kuluneina kuukausina, niin kuin niinä päivinä, joina Jumala minua varjeli,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'jolloin hänen lamppunsa loisti pääni päällä ja hänen valossaan vaelsin pimeydessä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'Jospa olisin kuin kukoistukseni päivinä, jolloin Jumalan ystävyys oli telttani yllä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'jolloin Kaikkivaltias oli vielä kanssani ja poikani minua ympäröivät,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'jolloin askeleeni kylpivät kermassa ja kallio vierelläni vuoti öljyvirtoja!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Kun menin kaupunkiin porttiaukealle, kun asetin istuimeni torille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'nuorukaiset väistyivät nähdessään minut, vanhukset nousivat ja jäivät seisomaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'päämiehet lakkasivat puhumasta ja panivat kätensä suulleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'Ruhtinaiden ääni vaikeni, ja heidän kielensä tarttui suulakeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Sillä kenen korva minusta kuuli, hän ylisti minua autuaaksi, kenen silmä minut näki, hän minusta todisti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Sillä pelastin kurjan, joka apua huusi, ja orvon, jolla ei ollut auttajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Menehtyvän siunaus tuli osakseni, ja lesken sydämen saatoin riemuitsemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Vanhurskaudella vaatetin itseni, ja se verhosi minut. Oikeus oli minulla viittana ja päähineenä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Olin sokean silmä ja ontuvan jalka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Minä olin köyhille isänä, ja oikeusasiaa, jota en tuntenut, tutkin tarkasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'Särjin väärintekijän leukaluut ja tempasin saaliin hänen hampaistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Silloin sanoin: \'Pesääni minä saan kuolla, ja lisään päiväni paljoiksi kuin hiekka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Onhan juureni vedelle avoinna, ja kaste yöpyy oksillani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Kunniani uudistuu alati, ja jouseni nuortuu kädessäni.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'He kuuntelivat minua, odottivat ja vaikenivat neuvoa antaessani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Puhuttuani he eivät enää sanaa sanoneet, ja puheeni meni heihin kuin vesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'He odottivat minua kuin sadetta ja avasivat suunsa kuin myöhäissateelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Nauroin heille, kun he eivät uskoneet. Kasvojeni loiste ei saanut heitä lankeamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Valitsin heidän tiensä, istuin päällikkönä ja elin kuin kuningas sotajoukkonsa keskellä, kuin murheellisten lohduttaja.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, '\"Mutta nyt minulle nauravat elinpäiviltään nuoremmat, joiden isiä minä pidin liian halpoina pantaviksi paimenkoirieni pariin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Mitäpä silloin hyödyttäisi minua heidän kättensä voima, koska heidän nuoruutensa väkevyys on hävinnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Puute ja kova nälänhätä saa heidät kaluamaan kuivaa maata, hiljan autioitunutta ja asumatonta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'He poimivat suolaheiniä pensaiden ympäriltä, ja pensaan juuria lämmitykseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Heidät karkotetaan ihmisten parista ja heitä vastaan nostetaan hälytys kuin varasta vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Heidän on asuttava kaameissa purouomissa, maakoloissa ja kallioluolissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'Pensaiden keskellä he ulisevat, nokkospehkojen suojaan he sulloutuvat –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'nuo houkkien ja kunniattomien lapset, maasta karkotetut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Mutta nyt olen tullut heille pilkkalauluksi, olen joutunut heidän puheenaiheekseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'He inhoavat minua, väistyvät minusta kauas eivätkä häikäile sylkeä silmilleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Sillä Jumala on höllentänyt jouseni jänteen ja nöyryyttänyt minut. He ovat ottaneet minulta pois ohjat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Oikealta puoleltani nousee tuo joukkio. He lyövät jalat altani ja ovat tehneet teitään tuhotakseen minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'He hävittävät polkuni, ovat apuna minua tuhottaessa, vaikka itse ovat ilman auttajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'He tulevat kuin leveästä muurin aukosta, raunioiden alta he vyöryvät esiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Kauhut ovat kääntyneet minua vastaan; niin kuin tuuli sinä pyyhkäiset pois arvoni, ja pelastukseni katoaa kuin pilvi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Nyt sieluni vuotaa tyhjiin, kurjuuden päivät ovat saavuttaneet minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Yö kaivaa luut ruumiistani, eivätkä kalvavat tuskani lepää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Suurella voimalla hän on tarttunut vaatteeseeni. Se kiristyy ympärilleni kuin viittani pääntie.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Hän on heittänyt minut lokaan, ja olen tullut tomun ja tuhkan kaltaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Huudan sinua, mutta et vastaa minulle. Seison tässä, mutta et huomaa minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Muutut tylyksi minulle, vainoat minua väkevällä kädelläsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Kohotat minut myrskytuuleen, kiidätät minut menemään ja murskaat minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Sillä tiedän: sinä viet minua kohti kuolemaa, paikkaan, minne kaikki elävä kokoontuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Mutta eikö saisi ojentaa kättänsä raunioihin ja huutaa apua onnettomuudessa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Vai enkö itkenyt kovaosaisen kohtaloa, eikö sieluni säälinyt köyhää?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Sillä odotin onnea, mutta tuli onnettomuus, vartosin valoa, mutta tuli pimeys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Sisukseni kuohuvat lakkaamatta, kurjuuden päivät ovat kohdanneet minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Käyn surupuvussa, eikä aurinko minulle paista. Nousen seurakunnassa ja huudan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Minusta on tullut sakaalien veli ja strutsien kumppani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Nahkani on mustunut ja lähtee päältäni, ja luuni ovat kuumuuden polttamat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Lyyrani soitto muuttui valitukseksi ja huiluni itkun ääneksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, '\"Olen tehnyt liiton silmieni kanssa: Kuinka voisinkaan katsoa neitsyen puoleen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Minkä osan antaisi silloin Jumala ylhäältä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Tuleehan väärälle turmio ja onnettomuus väärintekijöille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Eikö hän näkisi teitäni ja laskisi kaikkia askeleitani?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Jos olen koskaan turhuudessa vaeltanut, jos jalkani on kiiruhtanut petokseen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'punnitkoon minut Jumala oikealla vaa\'alla, ja hän on huomaava nuhteettomuuteni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Jos askeleeni ovat poikenneet tieltä ja sydämeni seurannut silmiäni tai tahra tarttunut käsiini,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'syököön toinen, mitä kylvän, ja vesani revittäköön juurineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Jos sydämeni hullaantui toisen vaimoon ja väijyin lähimmäiseni ovella,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'jauhakoon oma vaimoni vieraalle, ja halailkoot muut häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Sillä se olisi ollut paha teko ja raskaasti rangaistava rikos,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'tuli, joka kuluttaisi kadotukseen asti ja hävittäisi kaiken, minkä olen saanut hankituksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Jos pidin halpana palvelijani ja palvelijattareni oikeuden, kun heillä oli riita-asia kanssani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'niin mitä tekisin, jos Jumala nousisi, ja mitä vastaisin hänelle, jos hän kävisi tutkimaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Eikö sama, joka loi minut kohdussa, luonut häntäkin, eikö sama meitä kohdussa valmistanut?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Olenko kieltänyt puutteessa olevilta heidän tarpeensa ja saattanut lesken silmät sammumaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'Olenko syönyt leipäpalani yksin, orvon saamatta syödä siitä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'En, vaan nuoruudestani saakka kasvatin häntä kuin oma isä ja äitini kohdusta asti holhosin häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Jos näin menehtyvän ilman vaatteita ja köyhän verhoa vailla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'jos hänen lanteensa eivät minua siunanneet eikä hän saanut lämmitellä karitsojeni villoilla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'jos puin nyrkkiä orvolle, kun näin pidettävän puoltani portissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'irtautukoon olkapääni hartiastani, ja murtukoon käsivarteni sijoiltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Sillä silloin pelättävä olisi minulle Jumalan rangaistus enkä kestäisi hänen valtasuuruutensa edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Jos minä panin uskallukseni kultaan ja sanoin kultakimpaleelle: \'Sinä olet turvani\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'jos iloitsin siitä, että rikkauteni oli suuri ja että käteni oli saanut paljon hankituksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'jos katsellessani aurinkoa, kuinka se loisti, ja kuuta, kun se kulki mahtavana,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'sydämeni antautui salaa vieteltäväksi ja annoin suudelmia kädelleni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'sekin olisi rangaistava rikos, sillä olisin kieltänyt korkeuden Jumalan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Olenko iloinnut vihamieheni vahingosta ja huutanut riemusta, kun häntä kohtasi onnettomuus?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'En ole sallinut suuni tehdä syntiä ja toivottaa kirousta hänen sielulleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Eikö telttani väen pidä myöntää, että jokainen on saanut lihaa kyllikseen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'Muukalaisen ei tarvinnut viettää yötä ulkona, vaan pidin oveni auki tielle päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Olenko ihmisten tavoin peitellyt rikoksiani ja kätkenyt poveeni pahat tekoni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'Olenko säikkynyt suurta joukkoa ja pelännyt koko heimon ylenkatsetta, niin että pysyin hiljaa menemättä ovestani ulos?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Oi, jospa joku kuuntelisi minua! Katso, tuossa on kruksini! Kaikkivaltias vastatkoon minulle! Jospa vastapuoleni kirjoittaisi riita-asiani kirjaan!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Totisesti, olkapäälläni sitä kantaisin, sitoisin sen kruunuksi päähäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Tekisin hänelle tilin kaikista askeleistani ja astuisin hänen eteensä kuin ruhtinas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Jos peltoni huutaisi minua vastaan ja sen vaot yhdessä itkisivät,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'jos kulutin sen voiman maksamatta ja saatoin sen haltijat huokaamaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'kasvakoon vehnän sijaan orjantappuroita ja ohran sijaan rikkaruohoa.\" Tähän päättyvät Jobin puheet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Kun nämä kolme miestä eivät enää vastanneet Jobille, koska hän oli omissa silmissään vanhurskas,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'vihastui buusilainen Elihu, Baarakelin poika, joka oli Raamin sukua. Hän vihastui Jobiin, koska tämä piti itseään Jumalaa vanhurskaampana,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'ja tämän kolmeen ystävään hän vihastui, koska he eivät löytäneet vastausta, ja kuitenkin syyttivät Jobia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Elihu oli odottanut kunnes toiset olivat puhuneet puhuttavansa Jobille, koska toiset olivat iältään häntä vanhempia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Mutta kun Elihu näki, ettei noilla kolmella miehellä ollut sanaa suussaan vastaukseksi, hän vihastui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Niin buusilainen Elihu, Baarakelin poika, lausui ja sanoi: \"Nuori minä olen iältäni, ja te olette vanhoja. Sen tähden minä arkailin ja pelkäsin ilmoittaa tietoani teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Ajattelin: \'Puhukoon ikä, ja vuosien paljous julistakoon viisautta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Mutta onhan ihmisissä henki, ja Kaikkivaltiaan Henkäys antaa heille ymmärrystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Eivät iäkkäät ole viisaimmat, eivätkä vanhat ymmärrä, mikä on oikein.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Sen tähden sanon: Kuule minua; minäkin ilmoitan, mitä tiedän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Katso, olen odottanut, mitä teillä olisi sanomista, kuullakseni, kunnes olette käsittäneet asian ja kunnes löydätte sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'Niin, tarkkailin teitä, mutta katso, kukaan teistä ei korjannut Jobin puheita eikä kukaan teistä vastannut hänen puheisiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Älkää sanoko: \'Olemme löytäneet viisauden: Jumala on hänet hylännyt, ei ihminen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Hän ei ole suunnannut sanojaan minua vastaan, enkä minä vastaa hänelle teidän puheillanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'He pelästyivät eivätkä enää vastaa, sanat puuttuvat heiltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Odottaisinko, kun he eivät puhu, kun he seisovat eivätkä enää vastaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Vastaanpa minäkin osaltani, minäkin ilmoitan tietoni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Sillä olen sanoja täynnä, henki rinnassani ahdistaa minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Katso, rintani on kuin avaamaton viinileili, se on pakahtumaisillaan kuin nuorella viinillä täytetyt leilit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Tahdon puhua saadakseni helpotusta, avata huuleni ja vastata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'En pidä kenenkään puolta enkä ketään ihmistä imartele.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Sillä en osaa imarrella. Silloin Luojani ottaisi minut kohta pois.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, '\"Mutta kuule nyt, Job, puhettani, ja ota korviisi kaikki sanani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Katso, olen avannut suuni, kieleni puhuu kitalakeni alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Vilpittömästä sydämestä lähtevät sanani. Mitä tietävät, sen huuleni tuovat julki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Jumalan Henki on minut luonut, ja Kaikkivaltiaan Henkäys on antanut minulle elämän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Vastaa minulle, jos osaat. Asetu eteeni ja nouse minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Katso, minä olen Jumalan oma kuten sinäkin: savea olen minäkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Katso, en kauhistuta sinua eikä painoni ole raskaana ylläsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Mutta olet puhunut korvieni kuullen, olen kuullut sanojesi äänen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, '\'Puhdas minä olen, rikoksesta vapaa. Olen viaton, eikä minulla ole syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Katso, hän on löytänyt kanteen minua vastaan ja hän pitää minua vihollisenaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Hän panee jalkani jalkapuuhun ja vartioi kaikkia polkujani.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Katso, tässä et ole oikeassa – vastaan sinulle – sillä Jumala on suurempi kuin ihminen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Miksi olet riidellyt häntä vastaan, vaikka hän ei vastaa kaikkiin ihmisen sanoihin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Sillä Jumala puhuu tavalla ja puhuu toisella; ihminen ei vain sitä huomaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'Unessa, öisessä näyssä, kun raskas uni valtaa ihmiset ja he nukkuvat vuoteillaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'silloin hän avaa ihmisten korvat ja sinetillä vahvistaa heidän saamansa kurituksen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'kääntääkseen ihmisen pois siitä, mitä hän on tekemässä ja varjellakseen miestä ylpeydestä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'säästääkseen hänen sielunsa haudasta ja hänen henkensä syöksymästä peitsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Häntä kuritetaan myös tuskalla vuoteessa ja kovilla kivuilla hänen luissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'Hänen henkensä inhoaa leipää ja hänen sielunsa herkkuruokaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Hänen lihansa kuihtuu näkymättömiin, ja hänen luunsa, ennen näkymättömät, paljastuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'Näin lähenee hänen sielunsa hautaa ja hänen henkensä kuolemaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Jos silloin hänen puolellaan on enkeli, välittäjä, yksi tuhansista, todistamassa ihmisen puolesta hänen vilpittömyyttään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'Jumala armahtaa häntä ja sanoo: \'Vapauta hänet, ettei hän mene hautaan. Minä löysin lunastusmaksun.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Silloin taas hänen ruumiinsa palaa nuoruuden voimaan ja hän palaa nuoruutensa päiviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Hän rukoilee Jumalaa, ja Jumala mielistyy häneen ja antaa hänen riemuiten katsella hänen kasvojaan. Hän palauttaa ihmiselle hänen vanhurskautensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Hän tunnustaa ihmisille ja sanoo: \'Minä olin tehnyt syntiä ja vääristänyt oikean, mutta hän ei tehnyt minulle ansioni mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Hän pelasti minun sieluni joutumasta hautaan, ja henkeni saa katsella valkeutta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Katso, kaiken tämän tekee Jumala kahdesti ja kolmekin kertaa ihmiselle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'palauttaakseen hänen sielunsa haudasta ja antaakseen loistaa hänelle elämän valkeuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Tarkkaa, Job, kuule minua; vaikene ja anna minun puhua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Mutta jos sinulla on, mitä sanoa, vastaa minulle. Puhu, sillä mielelläni soisin sinulle vanhurskautesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Ellei, niin kuule minua. Vaikene, niin opetan sinulle viisautta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Sitten Elihu lausui ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, '\"Te viisaat kuulkaa sanojani, ja kuunnelkaa minua, te tietomiehet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Sillä korva koettelee sanat, ja kitalaki maistaa ruuan maun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Tutkikaamme, mikä on oikein, koettakaamme yhdessä ymmärtää, mikä on hyvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Sillä Job on sanonut: \'Olen vanhurskas, mutta Jumala on ottanut minulta oikeuteni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Pitäisikö minun valehdella oikeuteeni vedoten? Kuolettava nuoli on osunut minuun, vaikka en ole rikosta tehnyt.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Kuka mies on sellainen kuin Job, joka juo pilkkaa kuin vettä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'joka yhtyy väärintekijöiden seuraan ja vaeltaa jumalattomien miesten parissa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Sillä hän sanoo: \'Ei mies hyödy siitä, että on mieliksi Jumalalle.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Sen tähden kuulkaa minua, te ymmärtäväiset miehet: Pois se! Jumalattomuus ei ole Jumalan eikä vääryys Kaikkivaltiaan ominaisuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Vaan hän kostaa ihmiselle hänen tekonsa ja maksaa miehelle hänen vaelluksensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Totisesti, Jumala ei tee väärin, Kaikkivaltias ei vääristä oikeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Kuka on asettanut maan hänen valvontaansa, ja kuka on perustanut koko maanpiirin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Jos hän ajattelisi vain itseään ja palauttaisi luokseen Henkensä ja Henkäyksensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'niin kaikki liha yhdessä menehtyisi, ja ihminen tulisi tomuksi jälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Jos sinulla on ymmärrystä, kuule tätä, ota korviisi sanojeni ääni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Taitaisiko todella se hallita, joka vihaa oikeutta? Vai tuomitsetko syylliseksi tuon hyvin Vanhurskaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'joka sanoo kuninkaalle: \'Sinä kelvoton\', ruhtinaille: \'Sinä jumalaton\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'joka ei katso ruhtinaiden henkilöön eikä aseta rikasta köyhän edelle, koska he kaikki ovat hänen kättensä tekoa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Tuossa tuokiossa he kuolevat, keskellä yötä; kansat järkkyvät ja häviävät, valtias siirretään pois käden koskematta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Sillä hänen silmänsä valvoo ihmisen teitä, ja hän näkee kaikki hänen askeleensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Ei ole pimeyttä, ei kuoleman varjoa, johon väärintekijät voisivat piiloutua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Sillä Jumalan ei tarvitse kauan ihmistä tarkkailla, ennen kuin tämän on astuttava tuomiolle hänen eteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Hän musertaa mahtavat tutkimatta ja asettaa toiset heidän sijaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Niinpä hän tuntee heidän tekonsa ja kukistaa heidät yöllä, ja he ovat murskatut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Kuin jumalattomia hän kurittaa heitä julkisella paikalla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'koska he luopuivat häntä seuraamasta eivätkä huolineet ensinkään hänen teistään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'vaan saattoivat köyhien huudon kohoamaan hänen eteensä, ja hän kuuli kurjien huudon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Jos hän on hiljaa, kuka häntä siitä tuomitsee? Jos hän peittää kasvonsa, kuka voi häntä katsella? Sekä kansaa että jokaista ihmistä hän valvoo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'ettei pääse hallitsemaan jumalaton kansalle ansaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Sillä onko tässä sanottava Jumalalle: \'Kyllä kärsin, en enää tee väärin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Mitä en näe, neuvo minulle. Jos olen tehnyt vääryyttä, en enää tee.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Sinunko mielesi mukaan Jumalan tulisi kostaa? Sinäkö hylkäät, sinäkö valitset, enkä minä? Puhu, mitä tiedät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Ymmärtäväiset miehet puhuvat minulle, viisas mies, joka minua kuulee, lausuu:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, '\'Job puhuu vailla tietoa, ja hänen sanansa ovat ymmärrystä vailla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Jospa Jobia tutkittaisiin perusteellisesti, koska hän kääntyy väärintekijöiden puoleen!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Sillä hän lisää syntiä syntiin, lyö kämmentä keskellämme ja syytää sanoja Jumalaa vastaan.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Elihu lausui ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, '\"Pidätkö oikeana, että sanoit olevasi Jumalaa vanhurskaampi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'että kysyt, mitä se sinua hyödyttää: \'Hyödynkö siitä sen enempää, kuin jos olisin tehnyt syntiä?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Siihen vastaan sinulle sekä ystävillesi, jotka ovat luonasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Katso taivasta ja näe, katsele pilviä, jotka ovat korkealla yläpuolellasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Jos syntiä teet, ja vaikka sinulla olisi paljonkin rikoksia, mitä hänelle aiheutat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Jos olet vanhurskas, mitä sillä hänelle annat, tai ottaako hän mitään kädestäsi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Ihmistä, kaltaistasi, koskee jumalattomuutesi ja ihmislasta vanhurskautesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Sorron suuruutta valitetaan ja huudetaan apua suurten käsivartta vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'ei kysytä: \'Missä on Jumala, Luojani, joka yöllä saa viriämään ylistysvirret,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'joka opettaa meille enemmän kuin aron eläimille ja antaa meille viisautta enemmän kuin taivaan linnuille?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Siinä he valittavat, mutta hän ei vastaa pahojen ylvästelyn tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Todellakaan Jumala ei kuule turhia puheita eikä Kaikkivaltias katso niihin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'vaikka sanot, ettet voi häntä nähdä, tuomio on hänen edessään: odota häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Mutta nyt, kun hänen vihansa ei kosta eikä hän ylvästelystä suuria välitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Job avaa suunsa joutaviin ja syytää suuria sanoja taitamattomasti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Elihu jatkoi puhettaan ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, '\"Maltahan vähän, niin julistan sinulle, sillä vielä on minulla Jumalan puolesta puhuttavaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Noudan tietoni kaukaa ja osoitan Luojani vanhurskauden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Sillä totisesti, sanani eivät ole valhetta – mies, jolla on täydellinen tieto, on edessäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Katso, Jumala on voimallinen eikä hylkää voimakkaita sydämensä voimassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Hän ei pidä jumalatonta elossa, vaan antaa köyhille oikeuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Hän ei käännä silmiään pois vanhurskaista, vaan antaa heidän istua kuningasten kanssa valtaistuimella ikuisesti. He kohoavat korkealle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Vaikka olisivat kahleissa ja sidottuina kurjuuden köysillä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'niin hän sillä ilmaisee heille, mitä he ovat tehneet ja mitä rikkoneet ylvästelyllään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'avaa heidän korvansa nuhtelulle ja käskee heidän kääntyä pois vääryydestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Jos he kuulevat ja palvelevat häntä, he saavat viettää päivänsä onnessa ja ikävuotensa ihanasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Mutta jos eivät kuule, niin he syöksyvät surman peitsiin ja menehtyvät ymmärtämättömyyteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Mutta teeskentelijät pitävät vihaa, he eivät huuda apua, kun hän on heidät vanginnut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Heidän sielunsa kuolee nuoruudessa, heidän elämänsä loppuu haureellisten pyhäkköpoikien kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Kurjan hän vapahtaa hänen kurjuudessaan ja avaa hänen korvansa ahdistuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Sinutkin hän veti ahdingosta avaraan tilaan, jossa ei ahtautta ollut, ja pöytäsi notkui rasvaisista ruuista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Sinua kohtasi jumalattoman tuomio. Tuomio ja oikeus ovat käyneet sinuun kiinni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Älköön viha viekö sinua lyönteihin, älköönkä lunastusmaksun suuruus taivutelko sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Voiko huutosi tai kaikki voimanponnistuksesi auttaa sinut ahdingosta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Älä halua yötä, joka siirtää kansat aloiltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Varo, ettet käänny vääryyteen, sillä se on sinulle mieluisampi kuin kärsimys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Katso, Jumala on korkea, hän vallitsee voimallaan; kuka on hänen kaltaisensa opettaja?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Kuka voi koetella hänen tiensä, ja kuka sanoo: \'Sinä teit väärin\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Muista sinäkin ylistää hänen töitään, joista ihmiset veisaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Kaikki ihmiset ihailevat niitä, ja ihminen katselee niitä kaukaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Katso, Jumala on suuri, hänen vuosiensa luku on tuntematon ja hän on tutkimaton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Hän kokoaa vedenpisarat pilviksi, ja ne vihmovat virtanaan sadetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'Pilvet valuttavat vettä ihmisjoukkojen päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Kuka ymmärtää pilvien levittäytymisen, kuka hänen majansa jyrinän?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Katso, hän levittää sen päälle salaman leimahduksen ja peittää meren pohjat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Sillä niin hän tuomitsee kansat ja antaa runsaan ravinnon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Hän peittää molemmat kätensä salamalla ja käskee niiden lyödä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Hänet ilmoittaa hänen jyrinänsä ja karjakin hänen tulonsa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, '\"Niin, siitä värähtää sydämeni ja hypähtää paikoiltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Kuulkaa, kuulkaa hänen äänensä jyrinää ja kohinaa, joka käy hänen suustaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Hän laskee sen kaikumaan kaiken taivaan alla, lähettää leimauksensa maan ääriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Sen perässä ärjyy ääni, hän jyrisee valtasuuruutensa jyrinällä, eikä häntä pysäytetä hänen äänensä raikuessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Ihmeellisesti Jumala korottaa äänensä jyrinän ja hän tekee suuria, meille käsittämättömiä tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Hän näet sanoo lumelle: \'Putoa maahan\', samoin sadekuurolle, rankkasateittensa ryöpylle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Niin hän on sulkenut jokaisen käteensä, että kaikki ihmiset tuntisivat hänen tekonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Pedot vetäytyvät piiloon ja pysyvät luolissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Etelästä tulee myrsky, pohjoisesta pakkanen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Jumalan henkäyksestä syntyy jää, ja veden pinta jäätyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'Hän myös kuormittaa pilvet kosteudella ja hajottaa välähtelevät ukkospilvensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Ne vyöryvät sinne tänne hänen ohjauksessaan, tehdäkseen maanpiirin päällä kaiken, mitä hän niille määrää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Hän antaa niiden tulla maalle milloin vitsaukseksi, milloin siunaukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Ota tämä korviisi, Job, pysähdy ja ymmärrä Jumalan ihmeelliset teot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Tiedätkö, kuinka Jumala niillä tekonsa teettää ja kuinka hän antaa loistaa pilviensä leimahdusten?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Käsitätkö pilvien tasapainon, Kaikkitietävän ihmeen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Sinä, jonka vaatteet kuumenevat, kun maa on tyyni etelätuulessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Teetkö hänen kanssaan vahvoiksi pilvet, jotka ovat lujia kuin valettu peili?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Neuvo, mitä meidän on hänelle sanottava. Pimeydessämme emme voi tuoda esiin mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Olisiko hänelle ilmoitettava, että puhun? Kukapa vaatisi omaa tuhoaan!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Mutta nyt ei nähdä valoa, joka loisti kirkkaana pilvissä, kun tuuli oli puhaltanut puhdistaen taivaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Pohjoisesta tulee kultainen hohde. Jumalan yllä on pelättävä valtasuuruus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Kaikkivaltiasta emme voi käsittää, häntä, joka on niin suuri voimassaan ja tuomioissaan. Hänen vanhurskautensa on suuri eikä hän sorra ketään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Sen tähden pelätkööt häntä ihmiset. Hän ei katso keneenkään, joka on omasta mielestään viisas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Silloin Herra vastasi Jobille myrskytuulesta ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, '\"Kuka olet sinä, joka pimennät taitamattomilla puheilla ajatukseni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Vyötä nyt kupeesi kuin mies. Minä kysyn sinulta, opeta sinä minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Missä olit silloin, kun perustin maan? Ilmoita se, jos tiedät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Kuka on asettanut sille mitat – tottapa sen tiedät – tai kuka on vetänyt mittanuoran sen yli?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Mihin upotettiin sen perustukset, tai kuka laski sen kulmakiven,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'kun aamutähdet kaikki iloitsivat ja kaikki Jumalan pojat riemuitsivat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Kuka sulki ovilla meren, kun se puhkesi ja lähti kohdusta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'kun minä panin sille pilven vaatteeksi ja synkeyden kapaloksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'kun minä rakensin sille rajani, asetin sille teljet ja ovet');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'ja sanoin: \'Tähän asti saat tulla, mutta edemmäksi et. Tässä täytyy ylväiden aaltojesi asettua\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Oletko eläissäsi käskenyt päivän koittaa tai osoittanut aamuruskolle paikkansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'että se tarttuisi maan reunoihin ja pudistaisi jumalattomat siitä pois?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Silloin se muuttuu kuin savi sinetin alla, ja kaikki tulee esille kuin vaatteeseen puettuna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'Jumalattomilta riistetään heidän valonsa, ja kohonnut käsivarsi murskataan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Oletko astunut alas meren lähteille asti ja kierrellyt tutkimassa syvyyden?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Ovatko kuoleman portit sinulle paljastuneet, oletko nähnyt kuoleman varjon portit?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Käsitätkö, kuinka avara maa on? Ilmoita se, jos kaiken tämän tiedät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Mikä on tie sinne, missä valo asuu ja missä on pimeyden asuinsija,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'että saattaisit sen alueelleen ja tuntisit polut sen huoneelle?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Kaiketi sen tiedät, sillä synnyithän jo silloin, ja onhan päiviesi luku suuri!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Oletko käynyt lumen varastoissa, ja oletko nähnyt rakeiden varastot,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'jotka olen säästänyt ahdingon ajaksi, sodan ja taistelun päiväksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Mitä tietä kulkee valo ja itätuuli leviää yli maan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Kuka on avannut kulun rankkasateelle ja tien ukkospilvelle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'niin että sataa maahan, joka on asumaton, erämaahan, jossa ei ihmistä ole,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'niin että autio erämaa saa kyllikseen ja maa kasvaa vihannan ruohon?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Onko sateella isää, tai kuka on synnyttänyt kastepisarat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Kenen kohdusta on jää tullut, ja kuka on synnyttänyt taivaan härmän?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Vesi tiivistyy kuin kiveksi, ja syvyyden pinta sulkeutuu kiinni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Taidatko solmia Kiiman siteet tai irrottaa Kesilin köysistä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Voitko tuoda esiin eläinradan tähdet aikanaan ja johdattaa Seulaset lapsineen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Tunnetko taivaan lait, tai sinäkö säädät, miten se maata hallitsee?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Korotatko äänesi pilviin ja saat vesitulvan peittämään itsesi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Lähetätkö salamat menemään, niin että ne sanovat sinulle: \'Katso, tässä olemme\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Kuka on pannut viisauden sisimpään, tai kuka antoi mieleen ymmärrystä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Kuka on niin viisas, että laskee pilvien luvun, kuka vuodattaa tyhjiksi taivaan leilit,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'kun multa on kuivunut kovaksi kuin valettu ja maakokkareet takertuneet toisiinsa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, '\"Sinäkö ajat saaliin naarasleijonalle ja tyydytät nuorten leijonien nälän,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'kun ne kyyristyvät luoliinsa ja ovat väijyksissä tiheikössä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'Kuka hankkii ravinnon korpille, kun sen poikaset huutavat Jumalan puoleen ja lentelevät sinne tänne ruokaa vailla?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Tiedätkö vuorikauristen poikimisajat, valvotko peurojen synnytyskipuja?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Lasketko, milloin niiden kuukaudet täyttyvät, ja tiedätkö ajan, milloin ne poikivat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Ne painautuvat maahan, synnyttävät vasikkansa ja pääsevät synnytystuskistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Niiden vasikat vahvistuvat, kasvavat kedolla. Ne lähtevät tiehensä eivätkä palaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Kuka on laskenut villiaasin vapaaksi, kuka irrottanut aron aasin siteet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'sen, jolle minä annoin aavikon asunnoksi ja suola-aron asuinsijaksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Se nauraa kaupungin tungokselle eikä kuule ajajan huutoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Se tähystelee vuorilta laiduntansa ja etsii kaikkea vihantaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Taipuuko oryx-antilooppi sinua palvelemaan, ja yöpyykö se seimesi ääreen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Voitko ohjaksilla pakottaa oryx-antiloopin vaolle, tai äestääkö se laaksoja sinua seuraten?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Voitko siihen luottaa, siksi että sen voima on suuri, voitko jättää sen haltuun työsi hedelmät?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Voitko uskoa, että se palaa ja kokoaa viljasi puimatantereellesi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Strutsin siipi lepattaa iloisesti, mutta asuuko sen sulissa ja höyhenissä haikaran hellyys?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Se jättää munansa maahan, hiekalle helteen haudottaviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'Se ei ajattele, että jalka voi ne särkeä ja kedon eläimet polkea ne rikki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Se on tyly poikasilleen, niin kuin ne eivät olisikaan sen omia, eikä pelkää työnsä menevän hukkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Sillä Jumala on jättänyt sen viisautta vaille ja tehnyt sen ymmärryksestä osattomaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Kun se kiitää ilmaa piesten, nauraa se hevoselle ja ratsumiehelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Sinäkö annoit hevoselle voiman, puetit sen kaulaan liehuvan harjan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Sinäkö panet sen hyppimään kuin heinäsirkka? Sen uljas korskunta on pelottavaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Se kuopii lakeutta ja iloitsee, lähtee voimalla asevarustuksia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Se nauraa pelolle, ei säiky eikä väisty miekan edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Sen yllä kalisee nuolikotelo, välkähtää keihäs ja peitsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Käy jyrinä ja jytinä, kun se ahmii laukaten taivalta. Mikään ei pidätä sitä sotatorven pauhatessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Milloin vain sotatorvi soi, se hirnuu: ihahaa! Jo kaukaa se vainuaa taistelun, päälliköiden jyrisevän äänen ja sotahuudon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Sinunko ymmärryksesi voimasta jalohaukka kohoaa korkealle ja levittää siipensä kohti etelää?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Tai sinunko käskystäsi kotka lentää ylös ja tekee pesänsä korkeuteen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Kalliolla se asuu ja yöpyy, kallion kärjellä, vuorilinnassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'Sieltä se tähyää saalista. Kauas katsovat sen silmät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Sen poikaset juovat verta, ja missä on kaatuneita, siellä on sekin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Herra vastasi Jobille ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, '\"Tahtooko vikoilija riidellä Kaikkivaltiasta vastaan? Jumalan syyttäjä vastatkoon tähän!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Job vastasi Herralle ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, '\"Katso, olen siihen liian halpa. Mitäpä sinulle vastaisin? Panen käteni suulleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Kerran olen puhunut, enkä enää lausu mitään, kahdestikin, enkä enää sitä tee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Herra vastasi Jobille myrskystä ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, '\"Vyötä nyt kupeesi kuin mies. Minä kysyn sinulta, opeta sinä minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Sinäkö teet tyhjäksi oikeuteni, tuomitset minut syylliseksi ollaksesi itse oikeassa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Tai onko käsivartesi kuin Jumalan, ja voitko korottaa äänesi jylinän kuin hän?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Kaunistaudu kunnialla ja korkeudella, pukeudu loistoon ja kirkkauteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Anna vihasi kiivastuksen purkautua, ja masenna katseellasi kaikki ylpeät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Nöyryytä katseellasi kaikki ylpeät, ja muserra jumalattomat siihen paikkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Kätke heidät tomuun kaikki tyynni ja sulje heidän kasvonsa salaiseen kätköön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'Silloin minäkin ylistän sinua, kun oikea kätesi on hankkinut sinulle vapautuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Katso behemotia, jonka minä loin kuten sinutkin. Se syö ruohoa kuin nauta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Katso, sen voima on lanteissa ja sen väkevyys vatsalihaksissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Se ojentaa jäykäksi häntänsä kuin setripuun, sen jänteet ovat lujiksi punotut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Sen luut ovat kuin vaskiputket, sen nikamat kuin raudasta taotut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Se on Jumalan töiden esikoinen. Sen luoja ojentaa sille miekan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Sille kantavat satonsa vuoret, joilla kaikki metsän eläimet leikkivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Lootuspensaiden alla se makaa, ruovikon ja suon kätkössä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Lootuspensaat peittävät sen varjoonsa, puron pajut ympäröivät sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Jos virta hätyyttää, se ei säikähdä. Se on huoleton, kuohukoon vaikka itse Jordan sen kitaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Kukapa ottaisi sitä kiinni silmistä tai lävistäisi heittoaseella sen suun?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 25, 'Voitko onkia koukulla leviatanin ja siimaan kietoa sen kielen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 26, 'Voitko kiinnittää kaislaköyden sen kuonoon ja väkäraudalla lävistää siltä posken?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 27, 'Aneleeko se kovasti suosiotasi ja puhutteleeko se sinua lempeästi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 28, 'Tekeekö se liiton kanssasi, että saisit sen olemaan orjanasi ainaisesti?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 29, 'Voitko leikkiä sillä kuin linnulla tai sitoa sen tyttöjesi pidellä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 30, 'Hierovatko kauppakumppanit siitä kauppaa, jakavatko he sen keskenään?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 31, 'Voitko iskeä sen nahan täyteen harppuunoita ja sen pään kala-ahraimia?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 32, 'Laskehan vain kätesi sen päälle, niin muistat sen ottelun. Et sitä toiste yritä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Katso, siinä toivo pettää. Jo sen näkemisestä se sortuu maahan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, '\"Ei ole niin rohkeaa, joka sitä ärsyttäisi. Kuka sitten kestäisi minun edessäni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Kuka on minulle ensin antanut jotakin, joka minun olisi korvattava? Mitä kaiken taivaan alla on, se on minun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'En vaikene sen jäsenistä, sen voimasta ja sopusuhtaisuudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Kuka voi riisua siltä päällysvaatteen, kuka tunkeutua sen kaksoisleukojen väliin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Kuka on avannut sen kasvojen kaksoisoven? Sen hampaiden ympärillä on kauhu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Sen ylpeytenä ovat uurteiset selkäkilvet, kiinnitetyt lujalla sinetillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Ne käyvät tarkoin toinen toiseensa, niin ettei edes ilma pääse välitse.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Ne ovat toisiinsa liitetyt, pysyvät kiinni erkanematta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Sen aivastuksesta välähtää valo, sen silmät ovat kuin aamuruskon silmäripset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Sen kidasta lähtevät liekit, sinkoilevat kipinät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Sen sieraimista käy savu kuin kiehuvan padan ja kattilan alta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Sen puhallus polttaa kuin tuliset hiilet, ja sen suusta lähtee liekki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Sen kaulassa asuu voima, ja sen edellä juoksee kauhu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Sen pahkuraiset lihat ovat kiinteät, kuin valetut, järkkymättömät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Sen sydän on valettu kovaksi kuin kivi, kovaksi kuin alempi jauhinkivi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Kun se nousee, pelästyvät sankarit ja tyrmistyvät kauhusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Miekka, joka siihen osuu, ei kestä, ei keihäs, ei heittoase eikä panssari.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'Sille rauta on kuin oljenkortta, vaski kuin lahoa puuta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'Sitä ei aja pakoon nuoli, jousen poika, akanoiksi muuttuvat sille linkokivet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Kuin oljenkorsi on sille nuija, keihästen ryskeelle se nauraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Sen vatsapuolessa on terävät piikit, se kyntää mutaa leveälti kuin äes.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Se panee syvyyden kiehumaan kuin padan, tekee meren voidekattilan kaltaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Sen perässä polku loistaa, ja syvyydellä on kuin hopeahapset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Maan päällä ei ole sen vertaista. Se on luotu pelottomaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, 'Se halveksii kaikkea, mikä on korkeaa. Se on kaikkien ylväitten kuningas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Job vastasi Herralle ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, '\"Minä tiedän, että voit kaiken ja ettei mikään päätöksesi jää toteutumatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, '\'Mikä minä olen, joka peitän tiedon taitamattomasti?\' Siis niin on: puhuin ymmärtämättömästi asioista, jotka ovat ihmeelliset minun käsittää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Kuule siis, minä puhun. Kysyn sinulta, opeta minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Korvakuulolta vain olin sinusta kuullut, mutta nyt on silmäni sinut nähnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Sen tähden minä peruutan puheeni ja kadun tomussa ja tuhkassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Mutta sen jälkeen kun Herra oli puhunut Jobille nämä sanat, Herra sanoi teemanilaiselle Elifaalle: \"Minun vihani on syttynyt sinua ja kahta ystävääsi kohtaan, koska ette ole puhuneet minusta oikein niin kuin palvelijani Job.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Ottakaa siis seitsemän mullia ja seitsemän pässiä, käykää palvelijani Jobin luo ja uhratkaa puolestanne polttouhri, ja palvelijani Job rukoilkoon teidän puolestanne. Sillä minä katson hänen puoleensa enkä saata teitä rangaistukseen siitä, ettette puhuneet minusta oikein kuten palvelijani Job.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Teemanilainen Elifas, suuhilainen Bildad ja naemalainen Soofar menivät ja tekivät, niin kuin Herra oli heille puhunut, ja Herra teki Jobille mieliksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Kun sitten Job rukoili ystäviensä puolesta, Herra käänsi Jobin kohtalon, ja Herra antoi Jobille kaikkea kaksi kertaa enemmän, kuin hänellä oli ennen ollut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Kaikki hänen veljensä ja sisarensa ja kaikki hänen entiset tuttavansa tulivat hänen luokseen ja aterioivat hänen kanssaan hänen talossaan, ja he surkuttelivat ja lohduttivat häntä kaikesta siitä onnettomuudesta, jonka Herra oli antanut kohdata häntä. Sitten he antoivat kukin hänelle yhden kesitan ja yhden kultarenkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Herra siunasi Jobin elämän loppupuolta vielä enemmän kuin sen alkua, niin että hän sai neljätoista tuhatta lammasta, kuusi tuhatta kamelia, tuhat härkäparia ja tuhat aasintammaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Hän sai seitsemän poikaa ja kolme tytärtä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'Ensimmäiselle hän antoi nimen Jemima, toiselle nimen Kesia ja kolmannelle nimen Keren-Happuk.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Koko maassa ei ollut niin kauniita naisia kuin Jobin tyttäret, ja heidän isänsä antoi heille perintöosan heidän veljiensä rinnalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Tämän jälkeen Job eli vielä sataneljäkymmentä vuotta ja sai nähdä lapsensa ja lastensa lapset neljänteen polveen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Job kuoli vanhana ja elämästä kyllänsä saaneena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Autuas se mies, joka ei vaella jumalattomien neuvossa eikä kulje syntisten tietä eikä istu pilkkaajien kokouksessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'vaan jonka ilona on Herran laki ja joka mietiskelee hänen lakiaan päivin ja öin!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Hän on kuin istutettu puu vesiojien luona, joka antaa hedelmänsä ajallaan ja jonka lehti ei lakastu, ja kaikki, mitä hän tekee, menestyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Niin eivät ole jumalattomat, vaan he ovat kuin akanat, joita tuuli ajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Sen tähden jumalattomat eivät kestä tuomiolla eivätkä syntiset vanhurskasten seurakunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Sillä Herra tuntee vanhurskasten tien, mutta jumalattomien tie hukkuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Miksi pakanat pauhaavat ja kansat turhia ajattelevat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Maan kuninkaat nousevat, vallanpitäjät yhdessä neuvottelevat Herraa ja hänen Messiastaan vastaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, '\"Katkaiskaamme heidän siteensä, heittäkäämme päältämme heidän köytensä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Hän, joka taivaassa asuu, nauraa. Herra pilkkaa heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Silloin hän on puhuva heille vihassaan, saattava heidät kiivaudessaan kauhun valtaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, '\"Minä olen asettanut kuninkaani Siioniin pyhälle vuorelleni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Kerron Herran säädöksen, jonka hän minulle lausui: \"Sinä olet minun Poikani, tänä päivänä minä sinut synnytin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Ano minulta, niin minä annan pakanakansat sinulle perinnöksi ja maan ääret omiksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Rautaisella valtikalla sinä heidät muserrat, kuin saviastian sinä särjet heidät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Tulkaa siis järkiinne, kuninkaat, maan tuomarit, ottakaa nuhteesta vaari.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Palvelkaa Herraa pelolla ja iloitkaa vavisten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Tervehtikää Poikaa suudelmalla, ettei hän vihastuisi ettekä te hukkuisi tiellänne. Sillä lyhyen ajan jälkeen hänen vihansa syttyy. Autuaat ovat kaikki, jotka häneen turvaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Daavidin psalmi hänen paetessaan poikaansa Absalomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Herra, kuinka paljon minulla on vihollisia, kuinka paljon niitä, jotka nousevat minua vastaan!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Monet sanovat sielustani: \"Hänellä ei ole pelastusta Jumalassa.\" Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Mutta, Herra, sinä olet kilpeni, sinä olet kunniani, sinä korotat minun pääni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Ääneen minä huudan Herraa, ja hän vastaa minulle pyhältä vuoreltaan. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Minä käyn levolle ja nukun, minä herään, sillä Herra tukee minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'En pelkää kymmentuhantista kansaa, joka minua piirittää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Nouse, Herra, pelasta minut, Jumalani! Sillä sinä lyöt poskelle kaikkia vihollisiani, sinä murskaat jumalattomien hampaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 9, 'Herrassa on pelastus. Olkoon kansallasi siunauksesi. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Veisuunjohtajalle, kielisoittimilla, Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Vastaa minulle, kun minä huudan, sinä, vanhurskauteni Jumala, joka autat minut ahdingosta. Armahda minua, kuule rukoukseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Te miehet, kuinka kauan kunniani on pilkkana, kuinka kauan te rakastatte turhuutta ja etsitte valhetta? Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Tietäkää: ihmeellinen on Herra pyhäänsä kohtaan, Herra kuulee, kun minä häntä huudan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Vaviskaa, mutta älkää syntiä tehkö. Puhukaa sydämissänne vuoteillanne ja olkaa hiljaa. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Uhratkaa vanhurskauden uhreja ja luottakaa Herraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Moni sanoo: \"Kuka osoittaa meille, mikä hyvä on?\" Herra, käännä meihin kasvojesi valkeus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Sinä annat sydämeeni suuremman ilon, kuin heillä on runsaan viljan ja viinin aikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 9, 'Minä käyn rauhassa levolle ja nukun, sillä yksin sinä, Herra, annat minun asua turvassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Veisuunjohtajalle, huilusoittimilla, Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Ota korviisi minun sanani, Herra, huomaa huokaukseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Kuuntele huutoni ääntä, kuninkaani ja Jumalani, sillä sinua minä rukoilen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Herra, aamulla sinä kuulet ääneni, aamulla minä tuon sinulle pyyntöni ja odotan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Sillä sinä et ole Jumala, joka mieltyy jumalattomuuteen. Paha ei saa asua luonasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Kerskurit eivät kestä silmiesi edessä. Sinä vihaat kaikkia vääryydentekijöitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Sinä hukutat valheenpuhujat. Murhamiehet ja petolliset ovat Herralle kauhistus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Mutta suuresta armostasi minä saan tulla huoneeseesi, saan kumartaa pyhään temppeliisi päin sinun pelossasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Herra, johdata minua vanhurskaudessasi vihamiesteni tähden, tee tiesi suoraksi eteeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Sillä heidän suussaan ei ole luotettavaa sanaa, heidän sisimpänsä on turmiota täynnä, heidän kurkkunsa on avoin hauta ja kielellään he pettävät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Tuomitse, Jumala, heidät syyllisiksi. Rauetkoot heidän hankkeensa. Kukista heidät heidän rikostensa paljouden tähden, sillä he ovat kapinassa sinua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Iloitkoot siis kaikki, jotka sinuun turvaavat, ja riemuitkoot iankaikkisesti, sillä sinä olet heidän suojansa. Iloitkoot sinussa ne, jotka nimeäsi rakastavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 13, 'Sillä sinä, Herra, siunaat vanhurskasta, sinä ympäröit hänet armollasi kuin kilvellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Veisuunjohtajalle. Säestetään kahdeksankielisillä soittimilla. Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Herra, älä rankaise minua vihassasi, älä kurita minua kiivastuksessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Herra, armahda minua, sillä minä olen näännyksissä. Paranna minut, Herra, sillä minun luuni ovat pelästyneet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'ja sieluni on kovin peloissaan. Voi, Herra, kuinka kauan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Käänny, Herra, vapahda sieluni, pelasta minut armosi tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Sillä kuolemassa ei sinua muisteta. Kuka sinua haudassa ylistää?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Olen uupunut huokaamisesta. Joka yö itken vuoteeni vesille ja kastelen leposijani kyynelilläni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Silmäni ovat voipuneet surusta ja vanhentuneet kaikkien vastustajieni tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Väistykää minusta, kaikki väärintekijät, sillä Herra kuulee itkuni äänen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Herra kuulee anomiseni. Herra ottaa rukoukseni vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 11, 'Kaikki viholliseni joutuvat häpeään ja suuren pelon valtaan. He joutuvat häpeään yhtäkkiä. He kääntyvät pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Daavidin virsi, jonka hän veisasi Herralle benjaminilaisen Kuusin sanojen johdosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Herra, Jumalani, sinuun minä turvaan. Pelasta minut kaikista vainoojistani ja vapahda minut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'etteivät he raatelisi minua kuin leijona ja tempaisi pois – eikä pelastajaa olisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Herra, Jumalani, jos näin olen tehnyt, jos vääryys tahraa käsiäni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'jos olen tehnyt pahaa niille, jotka elivät rauhassa kanssani, tai jos olen ryöstänyt niiltä, jotka syyttä minua ahdistivat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'vainotkoon vihollinen henkeäni, saakoon minut kiinni ja polkekoon maahan elämäni ja painakoon kunniani tomuun. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Nouse, Herra, vihassasi. Kohoa vastustajieni raivoa vastaan ja herää avukseni, sinä, joka olet säätänyt tuomion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Ympäröikööt sinua kansojen joukot, ja palaa heidän ylitseen korkeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Herra tuomitsee kansat. Auta minut oikeuteeni, Herra, vanhurskauteni ja viattomuuteni mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Loppukoon jumalattomien pahuus, ja vahvista vanhurskaita. Sillä sinä, joka tutkit sydämet ja munuaiset, olet vanhurskas Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Jumala on kilpeni. Hän on oikeamielisten pelastaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Jumala on vanhurskas tuomari, ja hän on Jumala, joka on vihassaan ankara joka päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Jos kääntymystä ei tule, hän teroittaa miekkansa, jännittää jousensa ja tähtää sillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Hän valmistaa surma-aseet ja tekee nuolensa palaviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Katso, tuolla on paha mielessä, hän kantaa tuhoa sisällään, mutta synnytti itselleen pettymyksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Hän kaivoi hautaa ja sai sen valmiiksi, mutta itse hän kaatui tekemäänsä kuoppaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Hänen turmionhankkeensa kääntyi hänen omaan päähänsä, ja hänen vääryytensä lankesi hänen päälaelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 18, 'Minä kiitän Herraa hänen vanhurskaudestaan ja veisaan Herran, Korkeimman, nimen kiitosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Veisuunjohtajalle. Gatilaisten tapaan. Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Herra, Herramme, kuinka majesteetillinen onkaan nimesi kaikessa maassa, sinun, joka olet asettanut valtasuuruutesi taivaitten yli!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Lasten ja imeväisten suusta sinä perustit voiman vastustajiesi tähden, että kukistaisit vihollisen ja kostonhimoisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Kun katselen taivastasi, sormiesi tekoa, kuuta ja tähtiä, jotka olet luonut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'mikä on ihminen, että häntä muistat, tai Ihmisen Poika, että pidät hänestä huolen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Kuitenkin sinä, Jumala, hylkäät hänet vähäksi aikaa, mutta seppelöit hänet kunnialla ja kirkkaudella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Sinä panet hänet hallitsemaan kättesi tekoja, asetat kaikki hänen jalkojensa alle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'lampaat ja karjan, ne kaikki, niin myös aron eläimet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'taivaan linnut ja meren kalat ja kaiken, mikä kulkee meren polkuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 10, 'Herra, meidän Herramme, kuinka korkea onkaan nimesi kaikessa maassa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Veisuunjohtajalle; veisataan kuin: \"Pojan kuoleman johdosta\"; Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Ylistän Herraa kaikesta sydämestäni, ilmoitan kaikki ihmetekosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Iloitsen ja riemuitsen sinussa, veisaan nimesi kiitosta, sinä Korkein.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Sillä viholliseni peräytyivät, kaatuivat maahan ja hukkuivat kasvojesi edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Sinä hankit minulle oikeuden ja ajoit asiani, sinä istuit vanhurskaan tuomarin istuimelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Sinä nuhtelit pakanoita, tuhosit jumalattomat. Sinä pyyhit pois heidän nimensä iäksi ja ainiaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Viholliset ovat tuhotut, he ovat tulleet ikuisiksi raunioiksi. Kaupungit sinä kukistit, heidän muistonsa on kadonnut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Mutta Herra hallitsee iankaikkisesti. Hän on pystyttänyt istuimensa pitääkseen tuomion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Hän tuomitsee maanpiirin vanhurskaasti. Hän hallitsee kansoja oikeuden mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Herra on sorretun linna, linna ahdingon aikoina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Sinuun turvaavat ne, jotka nimesi tuntevat. Sillä sinä et hylkää niitä, jotka sinua etsivät, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Veisatkaa kiitosta Herralle, joka Siionissa asuu, julistakaa kansojen keskuudessa hänen suuria tekojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Sillä hän, verenkostaja, muistaa heitä eikä unohda kurjien huutoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Armahda minua, Herra, katso, kuinka vihamieheni minua vaivaavat, sinä, joka nostat minut kuoleman porteista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'että minä julistaisin kaikkia ylistettäviä tekojasi tytär Siionin porteissa, ja riemuitsisin pelastuksestasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Pakanat ovat vajonneet kaivamaansa hautaan. Heidän jalkansa on takertunut verkkoon, jonka he olivat virittäneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Herra on tehnyt itsensä tunnetuksi. Hän on pitänyt tuomiot ja kietonut jumalattoman hänen kättensä tekoihin. – Välisoitto. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Jumalattomat peräytyvät helvettiin, kaikki pakanat, ne, jotka unohtavat Jumalan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Sillä köyhää ei unohdeta iäksi, eikä kurjien toivo huku ainiaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Nouse, Herra, älä salli ihmisten uhitella. Tuomittakoon pakanat kasvojesi edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 21, 'Saata, Herra, heidät pelkoon. Pakanat tietäkööt olevansa vain ihmisiä. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Miksi, Herra, seisot niin kaukana, miksi kätkeydyt ahdingon aikoina?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Jumalattomien ylpeyden tähden kurja kärsii. Takertukoot punomiinsa juoniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Sillä jumalaton kerskailee omista himoistaan, ja kiskuri kiroaa, pilkkaa Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Jumalaton sanoo ylvästellen: \"Ei hän kosta.\" \"Ei Jumalaa ole\" – siinä kaikki hänen ajatuksensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Hänen hankkeensa menestyvät joka aika. Sinun tuomiosi ovat korkealla, hänestä kaukana. Kaikkia vastustajiaan hän sortaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Hän sanoo sydämessään: \"Minä en horju enkä joudu koskaan onnettomuuteen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Hänen suunsa on täynnä kirousta, petosta, sortoa. Tuhoa ja turmiota on hänen kielensä alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Hän istuu kylien väijytyspaikoissa ja murhaa syyttömän salaisessa paikassa. Hänen silmänsä vaanivat onnetonta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Hän väijyy piilopaikassaan kuin leijona pensaikossa. Hän väijyy hyökätäkseen kurjan kimppuun. Kun hän saa kurjan kiinni, hän vetää hänet verkkoonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Hän kyyristyy, painautuu maahan, ja onnettomat joutuvat hänen kynsiinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Hän sanoo sydämessään: \"Jumala unohtaa sen, hän on peittänyt kasvonsa eikä ikinä sitä näe.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Nouse, Herra, kohota kätesi, Jumala! Älä unohda kurjia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Miksi jumalaton pilkkaa Jumalaa? Miksi hän sanoo sydämessään: \"Et sinä kosta?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Sinä olet sen nähnyt, sillä sinä havaitset vaivan ja tuskan, ja sinä otat sen oman kätesi huomaan. Sinulle onneton uskoo asiansa, sinä olet orpojen auttaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Murskaa jumalattoman käsivarsi ja kosta pahan jumalattomuus, niin ettei häntä enää löydetä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Herra on kuningas aina ja iankaikkisesti. Pakanat ovat hävinneet hänen maastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Sinä kuulet kurjien halajamisen, Herra, sinä vahvistat heidän sydämensä, sinä herkistät korvasi kuulemaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'auttaaksesi orvon ja sorretun oikeuteensa, ettei ihminen, joka on maasta, enää saisi aikaan kauhua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Veisuunjohtajalle; Daavidin virsi. Herraan minä turvaan, kuinka te sanotte minulle: \"Paetkaa vuorellenne kuin linnut!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Sillä katso, jumalattomat jännittävät jousensa. He ovat asettaneet nuolensa jännitykseen ampuakseen pimeässä oikeamielisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Kun perustukset murretaan maahan, mitä voi vanhurskas tehdä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Herra pyhässä temppelissään, Herra, jonka istuin on taivaassa – hänen silmänsä näkevät, hänen katseensa tutkii ihmislapset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Herra tutkii vanhurskaat, mutta jumalattomia ja niitä, jotka vääryyttä rakastavat, hänen sielunsa vihaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Hän antaa sataa jumalattomien päälle ansoja, tulta ja rikkiä. Polttava tuuli on heidän maljansa osa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Sillä Herra on vanhurskas ja rakastaa vanhurskautta. Oikeamieliset saavat katsella hänen kasvojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Veisuunjohtajalle. Säestetään kahdeksankielisillä soittimilla. Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Auta, Herra, sillä pyhät ovat hävinneet, uskolliset ovat kadonneet ihmislasten joukosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'He puhuvat valhetta toinen toiselleen, puhuvat liukkain huulin, monimielisin sydämin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Hävittäköön Herra kaikki liukkaat huulet, kielen, joka puhuu kerskaten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'ne, jotka sanovat: \"Kielemme voimalla olemme väkevät. Huulemme ovat tukemme. Kuka on meille Herra?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, '\"Kurjien sorron tähden, köyhien huokausten tähden minä nyt nousen\", sanoo Herra, \"tuon pelastuksen, jotta voidaan opettaa rohkeasti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Herran sanat ovat selkeitä sanoja, hopeaa, joka kirkkaana valuu sulattimesta maahan, seitsenkertaisesti puhdistettua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Sinä, Herra, varjelet heitä ja suojelet iäti tältä sukukunnalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 9, 'Kaikkialla ympärillä jumalattomat rehentelevät, kun kataluus pääsee valtaan ihmislapsissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Veisuunjohtajalle; Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Kuinka kauaksi aikaa, Herra, unohdat minut, iäksikö kätket kasvosi minulta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Kuinka kauan minun täytyy kärsiä sielussani, päivät päästään kestää murhetta sydämessäni? Kuinka kauan vihollinen ylvästelee minua vastaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Katso tänne, vastaa minulle, Herra, Jumalani. Valaise silmäni, etten nukkuisi kuolemaan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'ettei vihamieheni sanoisi: \"Minä voitin hänet\", etteivät ahdistajani riemuitsisi, kun horjun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Mutta minä turvaan armoosi. Riemuitkoon sydämeni pelastuksestasi. Minä laulan Herralle, sillä hän on tehnyt minulle hyvin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Veisuunjohtajalle. Daavidin virsi. Hullu sanoo sydämessään: \"Ei ole Jumalaa.\" Turmiollinen ja iljettävä on heidän menonsa. Ei ole ketään, joka tekee sitä, mikä hyvä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Herra katsoo taivaasta ihmislapsiin nähdäkseen, onko ketään ymmärtäväistä, ketään, joka etsii Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Mutta kaikki ovat poikenneet pois, kaikki tyynni kelvottomiksi käyneet. Ei ole ketään, joka tekee sitä, mikä hyvää on, ei yhden yhtäkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Eivätkö he mitään käsitä, kaikki nuo väärintekijät, jotka saavat leipänsä syömällä kansaani eivätkä huuda avukseen Herraa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Siinä heidät valtaa kauhu, sillä Jumala on läsnä vanhurskasten sukukunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Te saatatte häpeään sorretun aikeet, mutta Herra on heidän turvansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Kuka antaa Siionista pelastuksen Israelille! Kun Herra palauttaa kansansa karkotetut, silloin Jaakob riemuitsee, Israel iloitsee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Daavidin psalmi. Herra, kuka asettuu telttamajaasi, kuka asuu pyhällä vuorellasi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Se, joka vaeltaa nuhteettomasti, joka tekee vanhurskauden ja puhuu sydämessään totuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Se, joka ei panettele kielellään, joka ei tee toiselle pahaa eikä saata lähimmäistään häväistyksen alaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'Se, joka halveksii hylättyä, mutta kunnioittaa niitä, jotka pelkäävät Herraa. Se, joka ei valaansa riko, vaikka on vannonut vahingokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Se, joka ei anna rahaansa korolle eikä ota lahjuksia viatonta vastaan. Joka näin tekee, se ei ikinä horju.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Daavidin laulu. Varjele minua, Jumala, sillä sinun turviisi minä pakenen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Minä sanon Herralle: \"Sinä olet Herrani, ilman sinua minulla ei ole mitään hyvää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Mutta pyhille, jotka maassa ovat, minä sanon: \"Nämä ovat ne jalot, joihin on koko minun mielisuosioni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Monta tuskaa on niillä, jotka ottavat vieraan jumalan. Minä en uhraa niille verta juomauhriksi enkä päästä huulilleni niiden nimiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Herra on pelto- ja malja-osani. Sinä hoidat arpani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Arpa lankesi minulle ihanasta maasta, ja kaunis on perintöosani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Minä kiitän Herraa, joka on minua neuvonut; yölläkin minua siihen sisimpäni kehottaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Pidän Herran aina edessäni; kun hän on oikealla puolellani, en horju.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Sen tähden sydämeni iloitsee ja sieluni riemuitsee, ja myös ruumiini asuu turvassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Sillä [sinä] et hylkää sieluani kuolemaan etkä salli Pyhäsi nähdä katoavaisuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, '[Sinä] neuvot minulle elämän polun. Ylenpalttisesti on iloa kasvojesi edessä, ihanuutta oikealla kädelläsi iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Daavidin rukous. Kuule, Herra, oikeaa asiaani, ota vaari huudostani, ota korviisi rukoukseni, joka ei lähde petollisilta huulilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Sinulta tulee minulle oikeus, silmäsi katsovat sitä, mikä on oikein.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Koettelet sydäntäni, tarkkailet sitä yöllä, tutkit minua, mutta et löydä mitään. Mitä ajattelen, se ei tule suustani ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Mitä ihmisten tekoihin tulee, pysyn huultesi sanassa ja varjellun väkivaltaisen poluilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Askeleeni pysyvät poluillasi, jalkani eivät horju.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Minä huudan avukseni sinua, sillä sinä vastaat minulle, Jumala. Kallista korvasi puoleeni, kuule puheeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Osoita ihmeellinen armosi, sinä, joka pelastat vihamiesten vallasta ne, jotka turvaavat oikeaan käteesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Varjele minua kuin silmäterää, kätke minut siipiesi suojaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'jumalattomilta, jotka tahtovat minut tuhota, verivihollisiltani, jotka minua saartavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'He ovat sulkeneet tunnottomat sydämensä, heidän suunsa puhuu ylvästellen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'He ovat kintereillämme, he jo kiertävät meidät, he vaanivat silmillään lyödäkseen maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Hän on kuin saalista himoitseva leijona, kuin nuori leijona, joka väijyy piilossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Nouse, Herra, astu hänen eteensä. Paiskaa hänet maahan. Vapahda miekallasi sieluni jumalattomista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'Vapahda minut kädelläsi ihmisistä, Herra, tämän maailman ihmisistä, joiden osa on tässä elämässä, joiden vatsan sinä täytät antimillasi, joiden pojat tulevat ravituiksi ja jotka jättävät yltäkylläisyytensä lapsilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Minä saan nähdä kasvosi vanhurskaudessa, herätessäni ravita itseni muotosi katselemisella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Veisuunjohtajalle; Herran palvelijan Daavidin virsi, jonka sanat hän puhui Herralle sinä päivänä, jona Herra oli pelastanut hänet kaikkien hänen vihollistensa vallasta ja Saulin kädestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Hän sanoi: Sydämestäni minä rakastan sinua, Herra, minun voimani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Herra, kallioni, linnani ja pelastajani, Jumalani, vuoreni, jonka turviin minä pakenen, kilpeni, autuuteni sarvi ja varustukseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Ylistetty olkoon Herra! – niin minä huudan, ja vihollisistani minä pelastun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Kuoleman paulat piirittivät minut, turmion virrat pelästyttivät minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'Helvetin paulat kietoivat minut, kuoleman ansat piirittivät minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Ahdistuksessani rukoilin Herraa ja huusin avuksi Jumalaani. Hän kuuli ääneni temppelistään, ja huutoni hänen edessään kohosi hänen korviinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Silloin maa huojui ja järisi, vuorten perustukset järkkyivät. Ne horjuivat, sillä hänen vihansa syttyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Savu suitsusi hänen sieraimistaan, kuluttava tuli hänen suustaan, palavat hiilet hehkuivat hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Hän notkisti taivaan ja astui alas, synkkä pilvi jalkojensa alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Silloin hän ajoi kerubin kannattamana ja lensi, ja hän liiti tuulen siivin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Hän pani pimeyden verhokseen, majakseen joka puolelle mustat vedet, paksut pilvet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Hohteesta, joka kävi hänen edellään, purkautuivat pilvet rakeiksi ja palaviksi hiiliksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Herra jylisi taivaassa, Korkein antoi äänensä kaikua ja tulla rakeita ja palavia hiiliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Hän lennätti nuolensa ja hajotti heidät. Salamien paljous sai heidät sekasortoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Vetten syvyydet tulivat näkyviin, ja maanpiirin perustukset paljastuivat nuhtelustasi, Herra, Henkesi vihanpuuskasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Hän ojensi kätensä korkeudesta ja tarttui minuun, veti minut ylös suurista vesistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Hän pelasti minut voimakkaasta vihollisestani, vihamiehistäni, sillä he olivat minua väkevämmät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'He hyökkäsivät kimppuuni hätäni päivänä, mutta Herra tuli minun tuekseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Hän toi minut avaraan paikkaan, hän vapautti minut, sillä hän oli mielistynyt minuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Herra tekee minulle vanhurskauteni mukaan, kätteni puhtauden mukaan hän minulle maksaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Sillä noudatan Herran teitä enkä luovu Jumalastani jumalattomuuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Kaikki hänen oikeutensa ovat silmieni edessä, enkä sysää syrjään hänen käskyjään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Olen vilpitön häntä kohtaan ja varon itseni pahoista teoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Herra palkitsee minulle vanhurskauteni mukaan, sen mukaan kuin käteni ovat puhtaat hänen silmiensä edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Pyhää kohtaan sinä olet pyhä, nuhteetonta kohtaan nuhteeton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Puhdasta kohtaan sinä olet puhdas, mutta kieroa kohtaan nurja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Sillä sinä pelastat nöyrän kansan, mutta ylpeät silmät sinä painat alas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Sillä sinä saatat lamppuni loistamaan. Herra, Jumalani, valaisee pimeyteni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Sinun avullasi minä hyökkään rosvojoukkoa vastaan. Jumalani avulla minä ryntään muurin yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Jumalan tie on nuhteeton, Herran sana tulessa koeteltu. Hän on kaikkien kilpi, jotka häneen turvaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Sillä kuka muu on Jumala kuin Herra, ja kuka pelastuksen kallio, paitsi Jumalamme –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'se Jumala, joka minut vyöttää voimalla ja tekee tieni nuhteettomaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'tekee jalkani nopeiksi kuin peurat ja asettaa minut kukkuloilleni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'joka opettaa käteni sotimaan ja käsivarteni jännittämään vaskijousta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Sinä annat minulle pelastuksen kilven, ja oikea kätesi tukee minua. Nöyryyttämisesi tekee minut suureksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Sinä annat askeleilleni avaran tilan, eivätkä jalkani horju.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Minä ajan vihollisiani takaa ja saavutan heidät enkä palaa, ennen kuin teen heistä lopun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Minä murskaan heidät, niin etteivät voi nousta. He sortuvat jalkojeni alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Sinä vyötät minut voimalla sotaan, sinä painat vastustajani alleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Sinä ajat viholliseni pakoon, ja vihamieheni minä hukutan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'He huutavat, mutta pelastajaa ei ole. He huutavat Herraa, mutta hän ei vastaa heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Survon heidät tomuksi tuuleen, heitän heidät kuin loan kadulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Sinä pelastat minut kansan riidoista. Sinä asetat minut pakanoiden pääksi. Kansa, jota en tunne, palvelee minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Jo korvan kuulemalta he tottelevat minua. Muukalaiset matelevat edessäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Muukalaiset käyvät heikoiksi ja tulevat vavisten varustuksistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Herra elää! Kiitetty olkoon kallioni ja ylistetty pelastukseni Jumala,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Jumala, joka hankkii minulle koston ja saattaa kansat valtani alle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'sinä, joka pelastat minut vihollisistani ja korotat minut vastustajieni yli ja päästät minut väkivaltaisesta miehestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Sen tähden minä ylistän sinua, Herra, pakanakansojen keskuudessa ja veisaan sinun nimesi kiitosta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 51, 'sinun, joka annat kuninkaallesi suuren avun ja teet laupeuden voidellullesi, Daavidille ja hänen jälkeläisilleen, iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Veisuunjohtajalle. Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Taivaat julistavat Jumalan kunniaa. Taivaanvahvuus ilmoittaa hänen kättensä tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Päivä sanoo päivälle, ja yö ilmoittaa yölle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Se ei ole puhetta, se ei ole kieltä, jonka ääni ei kuulu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'Niiden mittanuora ulottuu yli kaiken maan ja niiden sanat maanpiirin ääriin. Auringolle hän on tehnyt niihin majan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Se on kuin ylkä, joka tulee kammiostaan. Se riemuitsee kuin sankari rataansa juostessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Se nousee taivasten ääristä ja kiertää niiden toisiin ääriin, eikä mikään voi mennä piiloon sen helteeltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Herran laki on täydellinen. Se virvoittaa sielun. Herran todistus on vahva. Se tekee tyhmästä viisaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Herran asetukset ovat oikeat. Ne ilahduttavat sydämen. Herran käskyt ovat selkeät. Ne valaisevat silmät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Herran pelko on puhdas, se pysyy iäti. Herran oikeudet ovat todet, kaikki tyynni vanhurskaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Ne ovat kalliimmat kultaa ja puhtaan kullan paljoutta, makeammat hunajaa ja mehiläisen mettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Myös palvelijasi ottaa niistä vaarin, niiden noudattamisesta on suuri palkka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Erehdykset kuka ymmärtää? Anna anteeksi salaiset syntini.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Myös varjele palvelijasi röyhkeiltä. Älä anna heidän hallita minua. Niin minä pysyn nuhteettomana ja olen paljosta synnistä puhdas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 15, 'Kelvatkoot sinulle suuni sanat ja sydämeni ajatukset edessäsi, Herra, kallioni ja lunastajani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Veisuunjohtajalle; Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Kuulkoon Herra sinua hädän päivänä, varjelkoon sinua Jaakobin Jumalan nimi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Hän lähettäköön sinulle avun pyhäköstä ja tukekoon sinua Siionista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Muistakoon hän kaikki uhrilahjasi, ja olkoon polttouhrisi lihava hänen silmissään. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Hän antakoon sinulle, mitä sydämesi toivoo, ja täyttäköön kaikki aikeesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Me riemuitsemme pelastuksestasi ja nostamme lippumme Jumalamme nimeen. Täyttäköön Herra kaikki pyyntösi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Nyt minä tiedän, että Herra auttaa voideltuaan, vastaa hänelle pyhästä taivaastaan, auttaa häntä oikean kätensä voimallisilla teoilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Toiset turvaavat vaunuihin, toiset hevosiin, mutta me muistamme Herran, Jumalamme, nimeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'He vaipuvat maahan ja kaatuvat, mutta me nousemme ja pysymme pystyssä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 10, 'Herra, auta! Vastatkoon kuningas meille sinä päivänä, kun häneltä apua pyydämme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Veisuunjohtajalle; Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Herra, sinun voimassasi kuningas iloitsee. Kuinka suuresti hän riemuitseekaan autuudessasi!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Mitä hänen sydämensä halusi, sen sinä hänelle annoit, etkä kieltänyt, mitä hänen huulensa anoivat. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Sinä varustat hänet siunauksella ja onnella, panet hänen päähänsä kultaisen kruunun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Hän anoi sinulta elämää, sinä annoit hänelle pitkän, ainaisen, iankaikkisen elämän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Suuri on hänen kunniansa autuudessasi. Sinä annoit hänelle valtasuuruuden ja kirkkauden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Sillä sinä asetat hänet suureksi siunaukseksi ikiajoiksi. Sinä ilahdutat häntä kasvojesi riemulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Sillä kuningas luottaa Herraan, eikä hän horju Kaikkivaltiaan armossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Sinun kätesi löytää kaikki vihollisesi, oikea kätesi tavoittaa ne, jotka sinua vihaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Sinä teet heidät tulisen pätsin kaltaisiksi, kun näytät kasvosi. Herra nielee heidät vihassaan, ja tuli syö heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Sinä hävität maan päältä heidän hedelmänsä ja heidän jälkeläisensä ihmislasten keskuudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Vaikka he aikovat pahaa sinua vastaan ja miettivät juonia, he eivät mahda mitään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'sillä sinä teet heidän olkapäänsä tueksi jännitetylle jousellesi heidän kasvojaan vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 14, 'Nouse voimassasi, Herra! Laulaen ja soittaen me ylistämme väkevyyttäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Veisuunjohtajalle. Veisataan kuin: \"Aamuruskon peura.\" Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Jumalani, Jumalani, miksi minut hylkäsit? Miksi olet kaukana, et auta minua, et kuule valitukseni sanoja?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Jumalani, huudan päivällä, mutta sinä et vastaa, ja yöllä, enkä vaikene.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Kuitenkin sinä olet Pyhä, jonka istuin on Israelin kiitosvirsien keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Isämme luottivat sinuun, he luottivat, ja sinä pelastit heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'He huusivat sinua ja pelastuivat. He luottivat sinuun eivätkä joutuneet häpeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Mutta minä olen mato enkä ihminen, ihmisten pilkka ja kansan hylkäämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Kaikki, jotka minut näkevät, pilkkaavat minua, levittelevät suutaan, nyökyttävät ilkkuen päätään:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, '\"Jätä asiasi Herran haltuun. Hän vapahtakoon hänet, hän pelastakoon hänet, koska on häneen mieltynyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Sinähän vedit minut äitini kohdusta, sinä annoit minun olla turvassa äitini rinnoilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Sinun huomaasi minut jätettiin syntymästäni saakka. Sinä olet minun Jumalani hamasta äitini kohdusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Älä ole minusta kaukana, sillä ahdistus on läsnä, eikä auttajaa ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Minua saartavat väkevät sonnit, Baasanin härät piirittävät minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Ne avaavat kitansa minua vastaan, kuin raatelevat, kiljuvat leijonat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Kuin vesi minut on maahan vuodatettu. Kaikki luuni ovat irti toisistaan. Sydämeni on kuin vaha, se on sulanut rinnassani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Voimani on kuivettunut kuin saviastian siru, ja kieleni tarttuu suuni lakeen, ja sinä lasket minut alas kuoleman tomuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Sillä koirat minua piirittävät, pahojen parvi saartaa minut, käteni ja jalkani ovat lävistetyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Voin laskea kaikki luuni. He katselevat minua ilkkuen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'He jakavat keskenään vaatteeni ja heittävät puvustani arpaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Mutta sinä, Herra, älä ole kaukana, sinä, väkevyyteni, riennä avukseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Vapahda sieluni miekasta, ainokaiseni koirien kynsistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Pelasta minut leijonan kidasta, re\'eem-eläinten sarvista – vastaa minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Minä julistan nimeäsi veljilleni, ylistän sinua seurakunnan keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Te, jotka pelkäätte Herraa, ylistäkää häntä. Kunnioittakaa häntä, kaikki Jaakobin siemen, kaikki Israelin siemen, pelätkää häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Sillä hän ei halveksi kurjan kärsimystä, ei katso sitä ylen eikä kätke häneltä kasvojaan, vaan kuulee hänen avunhuutonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Sinusta on ylistyslauluni suuressa seurakunnassa. Minä täytän lupaukseni häntä pelkäävien edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Nöyrät saavat syödä ja tulevat ravituiksi. Ne, jotka etsivät Herraa, ylistävät häntä. Teidän sydämenne on elävä iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Kaikki maan ääret muistavat tämän ja palaavat Herran luo. Kaikki pakanoiden sukukunnat kumartavat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Sillä Herran on kuninkuus, ja hän on hallitseva pakanoita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Kaikki maan mahtavat syövät ja kumartavat. Hänen edessään polvistuvat kaikki, jotka mullan alle astuvat eivätkä voi pysyä elossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Jälkipolvet palvelevat häntä, tuleville polville kerrotaan Herrasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 32, 'He tulevat ja julistavat vastedes syntyvälle kansalle hänen vanhurskauttaan, että hän on tämän tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Daavidin psalmi. Herra on minun paimeneni, ei minulta mitään puutu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Vihreille niityille hän vie minut lepäämään; virvoittavien vetten luo hän minut johdattaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Hän virvoittaa sieluni. Hän kääntää minut vanhurskauden tielle nimensä tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Vaikka vaeltaisin kuoleman varjon laaksossa, en pelkäisi mitään pahaa, sillä sinä olet kanssani. Sinun valtikkasi ja sauvasi minua lohduttavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Sinä valmistat minulle pöydän vihollisteni silmien eteen. Sinä voitelet pääni öljyllä, maljani on ylitsevuotavainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Sula hyvyys ja laupeus seuraavat minua kaiken elinaikani, ja minä saan asua Herran huoneessa päivieni loppuun asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Daavidin psalmi. Herran on maa ja kaikki, mitä siinä on, maanpiiri ja ne, jotka siinä asuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Sillä hän on perustanut sen merien yläpuolelle, vahvistanut sen virtojen ylle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Kuka saa astua Herran vuorelle, kuka seisoa hänen pyhässä paikassaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Se, jolla on viattomat kädet ja puhdas sydän, joka ei halua turhuutta eikä vanno väärin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Hän saa siunauksen Herralta ja vanhurskauden pelastuksensa Jumalalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Tämä on se suku, joka häntä kysyy, joka etsii kasvojasi – tämä on Jaakob. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Nostakaa päänne, te portit, nostakaa päänne, te ikuiset ovet, kunnian kuninkaan käydä sisälle!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Kuka on se kunnian kuningas? Hän on Herra, väkevä ja vahva, Herra, vahva sodassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Nostakaa päänne, te portit, nostakaa päänne, te ikuiset ovet, kunnian kuninkaan käydä sisälle!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Kuka on se kunnian kuningas? Hän on Herra Sebaot, hän on kunnian kuningas. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Daavidin psalmi. Sinun luoksesi, Herra, minä ylennän sieluni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Jumalani, sinuun minä turvaan. Älä salli minun joutua häpeään, älkööt viholliseni saako riemuita minusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Ei yksikään, joka sinua odottaa, joudu häpeään. Häpeään joutuvat ne, jotka ovat syyttä uskottomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Herra, neuvo minulle tiesi, opeta minulle polkusi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Kuljeta minua totuudessasi ja opeta minua, sillä sinä olet autuuteni Jumala. Sinua minä odotan kaiken päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Muista laupeuttasi, Herra, ja armoasi, sillä ne ovat olleet iankaikkisuudesta asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Älä muista nuoruuteni syntejä äläkä rikoksiani. Muista minua armosi mukaan, hyvyytesi tähden, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Hyvä ja vakaa on Herra. Sen tähden hän neuvoo syntiset tielle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Hän johdattaa nöyriä oikein ja opettaa nöyrille tiensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Kaikki Herran polut ovat armo ja totuus niille, jotka pitävät hänen liittonsa ja todistuksensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Nimesi tähden, Herra, anna anteeksi syntivelkani, sillä se on suuri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Kuka on se mies, joka Herraa pelkää – sen hän neuvoo tielle, joka hänen on valittava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Hänen sielunsa saa nauttia hyvää, ja hänen jälkeläisensä perivät maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Herran neuvo on tunnettu niille, jotka häntä pelkäävät, ja hän ilmoittaa heille liittonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Silmäni katsovat alati Herraan, sillä hän päästää jalkani verkosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Käänny puoleeni, armahda minua, sillä minä olen yksinäinen ja kurja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Sydämeni pakahtuu tuskasta; päästä minut ahdistuksistani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Katso kurjuuttani ja vaivaani, anna kaikki syntini anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Katso vihollisiani, kuinka heitä on paljon, ja he vihaavat minua väkivaltaisella vihalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Varjele sieluni ja pelasta minut. Älä salli minun tulla häpeään, sillä turvaan sinuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Nuhteettomuus ja oikeamielisyys varjelkoot minua, sillä sinua minä odotan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Jumala, vapahda Israel kaikista sen ahdistuksista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Daavidin virsi. Hanki minulle oikeus, Herra, sillä minä olen vaeltanut vilpittömästi, turvannut Herraan enkä horju.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Tutki minua, Herra, ja pane minut koetukselle, koettele munuaiseni ja sydämeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Sillä armosi on silmieni edessä, ja olen vaeltanut totuudessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'En istu valheellisten miesten seurassa enkä kulje salakavalien kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Vihaan pahojen seuraa enkä istu jumalattomien parissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Pesen käteni viattomuudessa, ja astun kulkueessa alttarisi ympäri, Herra,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'antaakseni kuulua kiitokseni äänen ja julistaakseni kaikkia ihmeitäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Herra, rakastan sinun huoneesi asuinsijaa, sitä paikkaa, jossa kirkkautesi asuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Älä tempaa pois sieluani syntisten kanssa äläkä henkeäni verenvuodattajien kanssa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'joiden käsiä ilkityö tahraa ja joiden oikea käsi on lahjuksia täynnä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Mutta minä vaellan vilpittömästi. Vapahda minut ja ole minulle armollinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Jalkani seisoo tasaisella maalla. Seurakunnan kokouksissa kiitän Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Daavidin virsi. Herra on valkeuteni ja autuuteni: ketä minä pelkään! Herra on elämäni turva. Ketä minä vapisen!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Kun pahat käyvät kimppuuni syömään lihaani, niin he, ahdistajani ja vihamieheni, kompastuvat ja kaatuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Vaikka sotajoukko asettuisi minua vastaan, sydämeni ei pelkäisi. Vaikka sota nousisi minua vastaan, siinäkin olisin turvassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Yhtä minä anon Herralta, sitä minä pyydän, että saisin asua Herran huoneessa kaikki elämäni päivät, katsella Herran suloisuutta ja tutkia hänen temppelissään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Sillä hän kätkee minut majaansa pahana päivänä, hän suojaa minua telttansa suojassa ja korottaa minut kalliolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Pääni kohoaa nyt vihollisteni yli, jotka minua ympäröivät, ja uhraan riemu-uhreja hänen telttamajassaan. Minä laulan ja soitan Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Herra, kuule ääneni, kun huudan, armahda minua ja vastaa minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Sydämeni vetoaa omaan sanaasi: \"Etsikää minun kasvojani.\" Herra, minä etsin sinun kasvojasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Älä kätke minulta kasvojasi, älä työnnä vihassa pois palvelijaasi. Sinä olet apuni, älä minua jätä, älä hylkää minua, pelastukseni Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Vaikka isäni ja äitini hylkäisivät minut, niin Herra ottaa minut suojaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Neuvo, Herra, minulle tiesi ja johdata minua tasaista polkua vihamiesteni tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Älä anna minua alttiiksi ahdistajani vimmalle, sillä väärät todistajat nousevat minua vastaan ja puhkuvat väkivaltaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Mutta minä totisesti uskon näkeväni Herran hyvyyden elävien maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Odota Herraa. Ole luja, ja vahva olkoon sydämesi. Odota Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Daavidin virsi. Sinua, Herra, minä huudan, minun kallioni. Älä ole minua kohtaan äänetön, etten minä, kun sinä olet vaiti, joutuisi hautaan vaipuneiden kaltaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Kuule rukousteni ääni, kun sinua avuksi huudan, kun nostan käteni kaikkeinpyhintäsi kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Älä tempaa minua pois jumalattomien kanssa, älä väärintekijöiden kanssa, jotka puhuvat lähimmäisilleen rauhan puheita, vaikka heidän sydämessään on pahuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Anna heille heidän tekojensa mukaan ja heidän tekojensa pahuuden mukaan. Anna heille heidän kättensä tekojen mukaan, kosta heille, mitä he ovat tehneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Sillä eivät he ota vaarin Herran töistä eivätkä hänen kättensä teoista. Hän kukistakoon heidät älköönkä heitä rakentako.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Kiitetty olkoon Herra, sillä hän on kuullut rukousteni äänen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Herra on voimani ja kilpeni. Häneen sydämeni turvasi, ja sain avun. Siitä sydämeni riemuitsee, ja veisuullani ylistän häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Herra on kansansa väkevyys, hän on voideltunsa pelastus ja turva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Pelasta kansasi ja siunaa perikuntasi. Kaitse heitä ja kanna heitä iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Daavidin psalmi. Antakaa Herralle, te Jumalan pojat, antakaa Herralle kunnia ja väkevyys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Antakaa Herralle hänen nimensä kunnia, kumartakaa Herraa pyhässä kaunistuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Herran ääni käy vetten päällä; kunnian Jumala jylisee, Herra suurten vetten päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Herran ääni käy voimallisesti, Herran ääni käy valtavasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Herran ääni särkee setrit, Herra särkee Libanonin setrit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'Hän hypittää niitä kuin vasikkaa, Libanonia ja Sirjonia kuin nuorta re\'eem-eläintä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Herran ääni halkoo tulen liekit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Herran ääni vapisuttaa erämaan, Herra vapisuttaa Kaadeksen erämaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Herran ääni saattaa peurat poikimaan. Se raastaa paljaiksi metsät. Kaikki hänen temppelissään sanovat: \"Kunnia!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Herra istui valtaistuimellaan, ja vedenpaisumus tuli. Herra istuu kuninkaana iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Herra antaa kansalleen voiman, Herra siunaa kansaansa rauhalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Daavidin psalmi. Herran asumuksen vihkimislaulu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Minä ylistän sinua, Herra, sillä sinä vedit minut ylös vedestä etkä sallinut viholliseni iloita minusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Herra, Jumalani, sinua minä huusin, ja sinä paransit minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Herra, sinä nostit sieluni haudasta, sinä herätit minut henkiin hautaan vaipuvien joukosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Veisatkaa kiitosta Herralle, te hänen pyhänsä, ylistäkää hänen pyhää nimeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Sillä silmänräpäyksen kestää hänen vihansa, eliniän hänen armonsa. Illalla on itku vieraana, mutta aamulla ilo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Minä sanoin menestykseni päivinä: \"En minä ikinä horju.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Herra, armossasi sinä vahvistit vuoreni. Mutta kun sinä kätkit kasvosi, minä pelästyin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Sinua, Herra, minä huusin ja Herraa minä rukoilin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, '\"Mitä etua on verestäni, jos minä vaivun hautaan? Ylistääkö tomu sinua, julistaako se uskollisuuttasi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Kuule, Herra, ja armahda minua, Herra, ole auttajani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Sinä muutit murheeni ilokarkeloksi, sinä riisuit surupukuni ja vyötit minut riemulla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 13, 'jotta sieluni veisaisi sinulle kiitosta, eikä vaikenisi. Herra, Jumalani, sinua minä ylistän iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Veisuunjohtajalle; Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Herra, sinuun minä turvaan. Älä salli minun ikinä häpeään joutua, vapahda minut vanhurskaudessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Kallista korvasi puoleeni, riennä, pelasta minut. Ole minulle turvakallio, vuorilinna, johon minut pelastat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Sillä sinä olet kallioni ja linnani, ja nimesi tähden sinä minua johdat ja talutat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Sinä päästät minut verkosta, jonka he ovat virittäneet eteeni, sillä sinä olet turvani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Sinun käteesi annan henkeni, sinä, Herra, lunastat minut, sinä uskollinen Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Vihaan niitä, jotka seuraavat turhia epäjumalia, mutta minä turvaan Herraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Iloitsen ja riemuitsen armostasi. Kun sinä katsoit kurjuuttani, sinä tunsit sieluni ahdistukset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'etkä jättänyt minua vihollisen valtaan, vaan asetit jalkani aukealle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Armahda minua, Herra, sillä minulla on ahdistus. Silmäni on surusta riutunut, niin myös sieluni ja ruumiini.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Sillä elämäni kuluu murheessa ja vuoteni huokauksissa. Voimani on rauennut pahojen tekojeni tähden, ja luuni ovat riutuneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Kaikkien ahdistajieni tähden minä olen tullut pilkaksi, ylenpalttiseksi pilkaksi naapureilleni, kauhuksi tuttavilleni. Ne, jotka minut kadulla näkevät, pakenevat minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Olen unohtunut ihmisten mielistä kuin kuollut, olen kuin rikottu astia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Sillä minä kuulen monen parjaukset, kauhua kaikkialta, kun he keskenään pitävät neuvoa minua vastaan ja aikovat ottaa minulta hengen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Mutta sinuun, Herra, minä turvaan; minä sanon: \"Sinä olet Jumalani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Aikani ovat kädessäsi, pelasta minut vihollisteni kädestä ja vainoojistani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Valaise kasvosi palvelijallesi, pelasta minut armossasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Herra, älä saata minua häpeään, sillä sinua minä huudan avukseni. Jumalattomat tulkoot häpeään ja vaietkoot helvetissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Mykistykööt valheen huulet, jotka puhuvat vanhurskasta vastaan röyhkeästi, ylpeästi ja ylenkatseellisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Kuinka suuri on sinun hyvyytesi, jonka talletat sinua pelkääville ja jota osoitat sinuun turvaaville ihmislasten edessä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Sinä peität heidät kasvojesi suojaan ihmisten juonitteluilta. Sinä kätket heidät turvaan kielten riidalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Kiitetty olkoon Herra, sillä hän osoitti minulle ihmeellisen armonsa piiritetyssä kaupungissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Minä sanoin hädässäni: \"Minut on sysätty pois silmiesi edestä.\" Kuitenkin sinä kuulit rukousteni äänen, kun sinua huusin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Rakastakaa Herraa, kaikki hänen pyhänsä. Herra varjelee vilpittömät, mutta ylpeille hän kostaa ankarasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 25, 'Olkaa lujat, ja olkoon sydämenne rohkea, te kaikki, jotka Herraa odotatte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Daavidin mietevirsi. Autuas se, jonka rikokset ovat anteeksi annetut, jonka synti on peitetty!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Autuas se ihminen, jolle Herra ei lue syntiä ja jonka hengessä ei ole vilppiä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Kun minä vaikenin, riutuivat luuni jokapäiväisestä valituksestani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Sillä yötä päivää kätesi oli raskaana päälläni. Nesteeni kuivui kuin kesän helteessä. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Tunnustin sinulle syntini enkä peittänyt pahoja tekojani. Sanoin: \"Tunnustan Herralle rikokseni\", ja sinä annoit anteeksi syntivelkani. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Sen tähden rukoilkoot sinua kaikki pyhät aikana, jona sinut voidaan löytää. Vaikka suuret vedet tulvisivat, ne eivät ulotu heihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Sinä olet suojani, sinä varjelet minut hädästä, sinä ympäröit minut pelastuksen riemulla. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, '\"Opetan sinua ja osoitan sinulle tien, jota sinun tulee vaeltaa. Neuvon sinua, silmäni sinua ohjaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Älkää olko kuin järjettömät oriit ja muulit, joita suitsilla ja ohjaksilla, niiden valjailla, suistetaan. Muuten ne eivät sinua lähesty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Jumalattomalla on monta vaivaa, mutta joka Herraan turvaa, häntä ympäröi armo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Iloitkaa Herrassa ja riemuitkaa, te vanhurskaat, ja veisatkaa ilovirsiä, kaikki te oikeamieliset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Riemuitkaa Herrassa, te vanhurskaat. Oikeamielisten on soveliasta häntä kiittää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Ylistäkää Herraa lyyroilla, soittakaa hänelle kymmenkielisillä harpuilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Veisatkaa hänelle uusi virsi, helkyttäkää kieliä ihanasti ja riemullisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Sillä Herran sana on oikea, ja kaikki hänen tekonsa ovat tehdyt uskollisuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Hän rakastaa vanhurskautta ja oikeutta. Maa on täynnä Herran armoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Herran sanalla ovat taivaat tehdyt, ja kaikki niiden joukot hänen suunsa Hengellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Hän kokoaa meren vedet kuin röykkiöksi, panee syvyydet säiliöihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Pelätköön Herraa kaikki maa, hänen edessään vaviskoot kaikki maanpiirin asukkaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Sillä hän sanoi, ja tapahtui niin, hän käski, ja oli tehty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Herra särkee pakanoiden neuvon ja tekee turhiksi kansojen aikeet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Mutta Herran neuvo pysyy iankaikkisesti ja hänen sydämensä aivoitukset suvusta sukuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Autuas se kansa, jonka Jumala Herra on, se kansa, jonka hän on perinnökseen valinnut!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Herra katsoo alas taivaasta ja näkee kaikki ihmislapset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Hän katselee asumuksestaan, valtaistuimeltaan kaikkia maan asukkaita,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'hän, joka on luonut kaikkien heidän sydämensä ja joka tarkastelee kaikkia heidän tekojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Ei kuningas voita paljolla väellään, ei sankari pelastu suurella voimallaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Turha on sotaratsu auttajaksi eikä sen suuri voima pelasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Katso, Herran silmä valvoo niitä, jotka häntä pelkäävät ja panevat toivonsa hänen laupeuteensa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'että hän pelastaisi heidän sielunsa kuolemasta ja elättäisi heitä nälän aikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Sielumme odottaa Herraa. Hän on apumme ja kilpemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Sillä hänessä sydämemme iloitsee. Me turvaamme hänen pyhään nimeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Armosi, Herra, olkoon suojanamme, niin kuin panemme toivomme sinuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Daavidin virsi, kun hän tekeytyi mielipuoleksi Abimelekin edessä ja tämä karkotti hänet luotaan ja meni pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Minä kiitän aina Herraa, hänen ylistyksensä on alati suussani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Herra on sieluni ylistys, nöyrät kuulevat sen ja iloitsevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Ylistäkää kanssani Herraa, kiittäkäämme yhdessä hänen nimeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Minä etsin Herraa, ja hän vastasi minulle, hän vapahti minut kaikista kauhuistani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Jotka häneen katsovat, ne säteilevät iloa, heidän kasvonsa eivät häpeästä punastu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Tässä on kurja, joka huusi, ja Herra kuuli ja pelasti hänet kaikista hänen ahdistuksistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Herran enkeli asettuu niiden ympärille, jotka häntä pelkäävät, ja pelastaa heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Maistakaa ja katsokaa, kuinka Herra on hyvä. Autuas se mies, joka häneen turvaa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Pelätkää Herraa, te hänen pyhänsä, sillä häntä pelkääviltä ei puutu mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Nuoret leijonat kärsivät puutetta ja näkevät nälkää, mutta Herraa etsiviltä ei puutu mitään hyvää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Tulkaa, lapset, kuulkaa minua! Herran pelkoon minä opetan teidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Kuka oletkin, joka olet mieltynyt elinpäiviisi ja rakastat niitä nähdäksesi onnea:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'varjele kielesi pahasta ja huulesi vilppiä puhumasta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'sekä vältä pahaa ja tee hyvää, etsi rauhaa ja pyri siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Herran silmät katselevat vanhurskaita ja hänen korvansa [ottavat vaarin] heidän huudostaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Herran kasvot ovat pahantekijöitä vastaan hävittääkseen maasta heidän muistonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Vanhurskaat huutavat, ja Herra kuulee ja vapahtaa heidät kaikista heidän ahdistuksistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Lähellä on Herra niitä, joilla on särjetty sydän, ja hän pelastaa ne, joilla on murtunut mieli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Monta kärsimystä on vanhurskaalla, mutta Herra vapahtaa hänet niistä kaikista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Hän varjelee kaikki hänen luunsa. Niistä ei yksikään murru.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Pahuus tappaa jumalattoman, ja ne, jotka vanhurskasta vihaavat, tulevat syynalaisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 23, 'Herra lunastaa palvelijoidensa sielut, eikä yksikään, joka häneen turvaa, tule syynalaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Daavidin virsi. Riitele, Herra, riitaveljiäni vastaan. Sodi niitä vastaan, jotka minua vastaan sotivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Tempaa pieni kilpi, suuri kilpi ja nouse avukseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Vedä esiin keihäs ja salpaa tie vainoojiltani. Sano sielulleni: \"Minä olen pelastuksesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Joutukoot häpeään ja pilkkaan ne, jotka henkeäni väijyvät. Peräytykööt ja punastukoot ne, jotka aikovat minulle pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Olkoot he kuin akanat tuulessa, ja Herran enkeli syösköön heidät maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Heidän tiensä olkoon pimeä ja liukas, ja Herran enkeli ajakoon heitä takaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Sillä he ovat syyttä virittäneet verkkonsa eteeni. Syyttä he ovat kaivaneet sielulleni haudan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Tulkoon hänelle turmio aavistamatta, tarttukoon virittämäänsä verkkoon, langetkoon siihen surmakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Mutta minun sieluni iloitkoon Herrassa, riemuitkoon hänen avustaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Kaikki luuni sanokoot: \" Herra, kuka on vertaisesi, sinun, joka vapahdat kurjan väkevämmästään, kurjan ja köyhän raatelijastaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Väärät todistajat astuvat esiin. He kyselevät minulta, mitä en tiedä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'He palkitsevat minulle hyvän pahalla. Sieluni on orpo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Minä puolestani puin päälleni surupuvun, kun he sairastivat. Minä vaivasin itseäni paastolla ja rukoilin pää painuksissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Minä kuljin ikään kuin he olisivat olleet ystäviäni, omia veljiäni. Minä kävin surupuvussa, kumarruksissa kuin äitiään sureva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Mutta he iloitsevat kompastuksestani ja kokoontuvat – kokoontuvat minua vastaan, nuo lyöjät, joita en tunne. He herjaavat herkeämättä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'nuo konnat pilkkaavat minua ja kiristelevät minulle hampaitaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Herra, kuinka kauan sinä tätä katselet? Päästä sieluni turmiosta, jota he hankkivat, päästä minun ainokaiseni nuorista leijonista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Kiitän sinua suuressa seurakunnassa, ylistän sinua paljon kansan keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Älkööt ne minusta iloitko, jotka ovat syyttä vihamiehiäni. Älkööt iskekö silmää ne, jotka aiheetta vihaavat minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Sillä he eivät puhu rauhan puheita, vaan miettivät petoksen sanoja maan hiljaisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'He avaavat suunsa ammolleen minua vastaan ja sanovat: \"Kas niin, kas niin! Nyt me sen omin silmin näemme!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Sinä, Herra, näet sen, älä ole vaiti! Herra, älä ole minusta kaukana!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Herää ja nouse, Jumalani ja Herrani, hankkimaan minulle oikeus ja ajamaan asiaani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Tuomitse minut vanhurskautesi mukaan, Herra, Jumalani, älä salli heidän minusta riemuita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Älä salli heidän sanoa sydämessään: \"Kas niin! Sitä me halusimmekin.\" Älä salli heidän sanoa: \"Me olemme hänet nielleet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Hävetkööt ja punastukoot kaikki, jotka onnettomuudestani iloitsevat, saakoot puvukseen häpeän ja pilkan ne, jotka ylvästelevät minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Iloitkoot ja riemuitkoot ne, jotka suovat minulle oikeuteni, ja sanokoot aina: \"Ylistetty olkoon Herra, joka tahtoo palvelijansa parasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Kieleni julistakoon vanhurskauttasi, kiitostasi kaiken päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Veisuunjohtajalle; Herran palvelijan Daavidin virsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Synti sanoo jumalattomalle: sydämessäni ei ole Jumalan pelkoa hänen silmiensä edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Sillä se tekee kaiken sileäksi hänen silmissään, että hänen pahuutensa havaittaisiin ja häntä vihattaisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Hänen suunsa sanat ovat vääryyttä ja petosta. Hän on lakannut tekemästä sitä, mikä on taidollista ja hyvää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Hän miettii vuoteessaan turmiota. Hän pysyy tiellä, joka ei ole hyvä. Hän ei kammo pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Herra, armosi ulottuu taivaisiin, totuutesi pilviin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Vanhurskautesi on kuin Jumalan vuoret, sinun tuomiosi kuin suuri syvyys, ihmistä ja eläintä sinä autat, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Kuinka kallis onkaan armosi, Jumala! Ihmislapset etsivät siipiesi suojaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Heidät ravitaan huoneesi lihavuudella. Sinä annat heidän juoda suloisuutesi virrasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Sillä luonasi on elämän lähde. Valkeudessasi me näemme valkeuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Säilytä armosi niille, jotka tuntevat sinut, ja vanhurskautesi oikeamielisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Älköön ylpeyden jalka minua tallatko, älköönkä jumalattomien käsi minua karkottako.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 13, 'Katso, pahantekijät kaatuvat. He suistuvat maahan, eivätkä voi nousta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Daavidin virsi. Älä vihastu pahojen tähden, älä kadehdi väärintekijöitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Sillä kuin heinä niitetään heidät pian pois, ja he lakastuvat kuin vihanta ruoho.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Turvaa Herraan ja tee sitä, mikä on hyvää, asu maassa ja noudata totuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Silloin sinulla on ilo Herrassa, ja hän antaa sinulle, mitä sydämesi ikävöi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Anna tiesi Herran haltuun ja turvaa häneen, kyllä hän sen tekee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'Hän antaa vanhurskautesi nousta kuin valkeuden ja sinun oikeutesi kuin keskipäivän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Hiljenny Herran edessä ja odota häntä. Älä vihastu siihen, jonka tie menestyy, mieheen, joka punoo juonia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Herkeä vihasta ja heitä kiukku, älä kiivastu, se on vain pahaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Sillä pahat hävitetään, mutta jotka Herraa odottavat, ne perivät maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Hetki vielä, niin jumalatonta ei enää ole; kun katsot hänen sijaansa, hän on jo poissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Mutta nöyrät perivät maan ja iloitsevat suuresta rauhasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Jumalaton miettii vanhurskaalle pahaa ja kiristelee hänelle hampaitaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Mutta Herra nauraa hänelle, sillä hän näkee hänen päivänsä joutuvan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Jumalattomat paljastavat miekkansa ja jännittävät jousensa kaataakseen kurjan ja köyhän, teurastaakseen ne, jotka ovat oikealla tiellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Mutta heidän miekkansa käy heidän omaan sydämeensä, ja heidän jousensa särkyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Vanhurskaan vähäinen varallisuus on parempi kuin monen jumalattoman omaisuuden paljous.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Sillä jumalattomien käsivarret särjetään, mutta Herra tukee vanhurskaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Herra tuntee nuhteettomien päivät, ja heidän perintönsä pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Pahana aikana he eivät joudu häpeään, ja nälän päivinä heillä on kylliksi syötävää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Sillä jumalattomat hukkuvat, ja Herran viholliset ovat kuin niittyjen koreus: he katoavat, katoavat kuin savu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Jumalaton ottaa lainan eikä maksa, mutta vanhurskas on armahtavainen ja antelias.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Sillä hänen siunaamansa perivät maan, mutta hänen kiroamansa hävitetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Herra vahvistaa sen miehen askeleet, jonka tie hänelle kelpaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Jos hän lankeaa, hän ei maahan sorru, sillä Herra tukee hänen kättään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Olen ollut nuori ja olen tullut vanhaksi, mutta en ole nähnyt vanhurskasta hylättynä enkä hänen lastensa kerjäävän leipää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Aina hän on armahtavainen ja antaa lainaksi, ja hänen lapsensa ovat siunaukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Karta pahaa ja tee hyvää, niin sinä pysyt iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Sillä Herra rakastaa oikeutta eikä hylkää pyhiään. Heidät varjellaan iankaikkisesti, mutta jumalattomien siemen hävitetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Vanhurskaat perivät maan ja asuvat siinä iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Vanhurskaan suu lausuu viisautta, ja hänen kielensä puhuu oikeuden sanoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'Hänen Jumalansa laki on hänen sydämessään, hänen askeleensa eivät horju.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Jumalaton väijyy vanhurskasta ja etsii häntä tappaakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Mutta Herra ei jätä häntä hänen käsiinsä eikä tuomitse häntä syylliseksi, kun hänen asiansa on oikeudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Odota Herraa ja ota vaari hänen tiestään, niin hän korottaa sinut, ja sinä perit maan ja näet, kuinka jumalattomat hävitetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Minä näin jumalattoman, väkivaltaisen, rehevänä kuin viheriöivä puu, juurtuneena paikoilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Mutta kun ohi kuljettiin, katso, häntä ei enää ollut. Minä etsin häntä, mutta häntä ei löytynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Ota nuhteettomasta vaari, katso rehellistä: rauhan miehellä on tulevaisuus,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'mutta luopuneet hukkuvat kaikki, ja jumalattomien tulevaisuus leikataan pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Mutta vanhurskasten pelastus tulee Herralta, hän on heidän linnansa ahdingon aikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Herra auttaa heitä ja vapahtaa heidät, vapahtaa jumalattomista ja pelastaa heidät, sillä he turvaavat häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Daavidin psalmi. Muistoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Herra, älä rankaise minua vihassasi, älä kurita minua kiivaudessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Sillä nuolesi ovat uponneet minuun, kätesi painaa minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Ei ole lihassani tervettä paikkaa vihastuksesi tähden eikä luissani rauhaa syntieni tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Sillä pahat tekoni käyvät pääni yli, kuin painava kuorma ne ovat minulle liian raskaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Haavani haisevat ja märkivät hulluuteni tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Minä käyn kumarassa, aivan kyyryssä, kuljen murheellisena kaiken päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Sillä lanteeni ovat polttavaa kipua täynnä eikä lihassani ole tervettä paikkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Olen voimaton ja aivan runneltu, itken sydämeni tuskassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Herra, edessäsi on kaikki, mitä toivon, eikä huokaukseni ole sinulta salassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Sydämeni värisee, voimani on minusta luopunut, silmieni valo – sekin on minulta mennyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Ystäväni ja läheiseni pysyvät syrjässä vaivastani, ja omaiseni seisovat kaukana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Ne, jotka etsivät henkeäni, virittävät pauloja. Ne, jotka minulle pahaa tahtovat, puhuvat turmion puheita ja miettivät petosta kaiket päivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Mutta minä olen kuin kuuro, enkä kuule mitään, kuin mykkä, joka ei avaa suutaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Olen kuin mies, joka ei kuule mitään ja jonka suussa ei ole vastausta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Sillä sinua, Herra, minä odotan, sinä vastaat, Herra, Jumalani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Sillä sanon: älkööt iloitko minusta, älkööt ylvästelkö minua vastaan, kun jalkani horjuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Minä olen näet kaatumaisillani, ja tuskani on aina edessäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Sillä minä tunnustan pahat tekoni, murehdin syntieni tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Mutta viholliseni elävät ja ovat väkevät, ja paljon on niitä, jotka vihaavat minua syyttä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'jotka palkitsevat hyvän pahalla ja vihaavat minua, koska teen hyvää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Älä hylkää minua, Herra, Jumalani, älä ole minusta kaukana');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 23, 'Riennä avukseni, Herra, sinä, autuuteni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Veisuunjohtajalle; Jedutunin tapaan. Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Sanoin: \"Pidän vaelluksestani vaarin, etten tekisi kielelläni syntiä. Pidän suustani vaarin ja tukin sen, niin kauan kuin jumalaton on edessäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Olin vaiti, olin ääneti enkä puhunut siitä, mikä on hyvä, mutta tuskani yltyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Sydämeni hehkui rinnassani, kun huokailin. Minussa syttyi tuli, ja puhuin kielelläni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Herra, opeta minua ajattelemaan loppuani, ja sitä, mikä päivieni mitta on, että ymmärtäisin, kuinka katoava minä olen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Katso, kämmenen leveydeksi sinä teit päiväni, ja elämäni on edessäsi kuin ei mitään. Vain tuulen henkäys ovat kaikki ihmiset, kuinka lujina seisovatkin. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Varjona vain ihminen vaeltaa, turhaan vain he touhuavat, kokoavat, eivätkä tiedä, kuka ne saa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Mutta nyt, mitä minä odotan, Herra? Sinuun minä panen toivoni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Päästä minut kaikista synneistäni, älä pane minua tyhmien pilkaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Minä vaikenen enkä suutani avaa, sillä sinä sen teit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Käännä vitsauksesi minusta pois, sillä minä menehdyn kätesi kuritukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Kun sinä kuritat ihmistä synnin tähden rangaistuksilla, sinä kulutat hänen kauneutensa kuin koinsyömän. Vain tuulen henkäys ovat kaikki ihmiset. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Kuule rukoukseni, Herra, ota korviisi huutoni. Älä ole kuuro kyyneleilleni. Sillä minä olen muukalainen luonasi, vieras, kuten kaikki isänikin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 14, 'Käännä katseesi pois minusta, että ilahtuisin, ennen kuin menen pois eikä minua enää ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Veisuunjohtajalle; Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Hartaasti minä odotin Herraa, ja hän kumartui puoleeni ja kuuli huutoni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'Hän nosti minut ylös turmion kuopasta, lokaisesta liejusta, ja asetti jalkani kalliolle, hän vahvisti askeleeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Hän antoi suuhuni uuden virren, kiitoslaulun Jumalallemme. Sen näkevät monet ja pelkäävät ja turvaavat Herraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Autuas se mies, joka panee turvansa Herraan eikä käänny ylpeiden puoleen eikä niiden, jotka kääntyvät valheeseen!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Herra, Jumalani, suuret ovat ihmetekosi ja ajatuksesi, joita sinä meille osoitat. Ei ole ketään vertaistasi. Niitä minä tahdon julistaa, niistä puhua, niiden paljous on suurempi, kuin osaan luetella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Teurasuhriin ja ruokauhriin sinä et mielisty. Korvani sinä avasit, polttouhria ja syntiuhria sinä et vaadi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Silloin minä sanoin: \"Katso, minä tulen; kirjakääröön on kirjoitettu minusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Sinun tahtosi, Jumalani, teen mielelläni, ja lakisi on sisimmässäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Minä julistan vanhurskautta suuressa seurakunnassa. Katso, minä en sulje huuliani. Herra, sinä sen tiedät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Minä en peitä vanhurskauttasi omaan sydämeeni, vaan puhun sinun uskollisuudestasi ja avustasi. Minä en salaa armoasi ja totuuttasi suurelta seurakunnalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Sinä, Herra, älä sulje minulta laupeuttasi, armosi ja totuutesi varjelkoon minua aina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Sillä lukemattomat vaivat minua saartavat, rikokseni ovat ottaneet minut kiinni, niin etten voi nähdä. Ne ovat useammat kuin pääni hiukset, ja rohkeus on minulta mennyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Kelvatkoon sinulle, Herra, pelastaa minut, Herra, riennä avukseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Hävetkööt ja punastukoot kaikki, jotka etsivät henkeäni hukuttaakseen sen. Peräytykööt ja tulkoot häpeään ne, jotka tahtovat minulle onnettomuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Kauhistukoot häpeästään ne, jotka sanovat minulle: \"Kas niin, kas niin!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Iloitkoot ja riemuitkoot sinussa kaikki, jotka sinua etsivät; ne, jotka autuuttasi rakastavat, sanokoot aina: \"Ylistetty olkoon Herra!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 18, 'Minä olen kurja ja köyhä, mutta Herra pitää minusta huolen. Sinä olet apuni ja pelastajani. Jumalani, älä viivy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Veisuunjohtajalle; Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Autuas se, joka ottaa köyhän hoiviinsa! Herra pelastaa hänet pahana päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Herra varjelee häntä ja pitää hänet hengissä, ja maassa ylistetään häntä autuaaksi, etkä sinä anna häntä alttiiksi hänen vihollistensa haluille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Herra tukee häntä tautivuoteessa. Sinä päästät hänet hänen sairasvuoteestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Minä sanoin: \" Herra, ole minulle armollinen, paranna sieluni, sillä olen tehnyt syntiä sinua vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Viholliseni puhuvat minusta pahaa: \"Milloin hän kuolee ja hänen nimensä katoaa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Jos joku tulee minua katsomaan, hän puhuu petosta. Hänen sydämensä kerää itseensä pahuutta. Hän menee ulos kadulle ja puhuu sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Kaikki vihamieheni kuiskuttelevat minusta keskenään ja suunnittelevat minulle pahaa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, '\"Jokin paha on häneen iskenyt, ja siitä, missä hän makaa, hän ei enää nouse.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Ystävänikin, johon luotin, joka söi leipääni, nostaa kantapäänsä minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Mutta sinä, Herra, armahda minua ja auta minut ylös pystyyn, niin sen heille maksan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Siitä tiedän sinun mieltyneen minuun, ettei viholliseni saa minusta riemuita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Nuhteettomuuteni tähden sinä minua tuet ja annat minun seistä kasvojesi edessä iäti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 14, 'Kiitetty olkoon Herra, Israelin Jumala, iankaikkisesta iankaikkiseen. Aamen. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Veisuunjohtajalle; koorahilaisten mietevirsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Kuin peura ikävöi vesipuroille, niin sieluni ikävöi sinua, Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Sieluni janoaa Jumalaa, elävää Jumalaa. Milloin tulen ja minut nähdään Jumalan kasvojen edessä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Kyyneleeni ovat ruokani päivin ja öin, kun minulle joka päivä sanotaan: \"Missä on Jumalasi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Näitä minä muistelen ja vuodatan sydämeni: minä kuljin väentungoksessa, astuin sen kanssa Jumalan huoneeseen riemun ja kiitoksen raikuessa juhlivasta joukosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Miksi, sieluni, murehdit ja olet minussa niin levoton? Odota Jumalaa. Sillä vielä minä saan häntä kiittää hänen kasvojensa avusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Jumalani, sieluni on murheellinen minussa, sen tähden minä muistan sinua Jordanin maalla, Hermonin kukkuloilla ja Misarin vuorella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Sinun koskiesi pauhussa syvyys huutaa syvyydelle. Kaikki kuohusi ja aaltosi käyvät ylitseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Päivällä Herra säätää armonsa, ja yöllä laulan hänelle ja rukoilen elämäni Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Minä sanon Jumalalle, kalliolleni: \"Miksi olet unohtanut minut? Miksi minun täytyy käydä murhepuvussa vihollisen ahdistamana?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Luitani jäytää, kun viholliseni minua häpäisevät, sanoen minulle kaiken päivää: \"Missä on Jumalasi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 12, 'Miksi murehdit, sieluni, ja miksi olet minussa levoton? Odota Jumalaa. Sillä vielä minä saan kiittää häntä, kasvojeni apua, Jumalaani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Auta minut oikeuteeni, Jumala, ja aja asiani armotonta kansaa vastaan. Päästä minut kavalista ja vääristä ihmisistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Sillä sinä olet Jumalani, linnani. Miksi olet minut hylännyt? Miksi minun täytyy käydä murhepuvussa vihollisen ahdistamana?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Lähetä valkeutesi ja totuutesi. Ne minua johdattakoot, viekööt minut pyhälle vuorellesi, asuntoihisi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'että minä saisin tulla Jumalan alttarin eteen, Jumalan eteen, joka on iloni ja riemuni, ja kiittäisin sinua lyyroilla, Jumala, minun Jumalani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Miksi murehdit, sieluni, ja miksi olet minussa niin levoton? Odota Jumalaa. Sillä vielä minä kiitän häntä, kasvojeni apua, Jumalaani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Veisuunjohtajalle; koorahilaisten mietevirsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Jumala, olemme omin korvin kuulleet, isämme ovat meille kertoneet, minkä teon sinä teit heidän päivinään, muinaisina päivinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Sinä karkotit pakanat kädelläsi, mutta heidät sinä istutit, sinä hävitit kansat, mutta heidät sinä levitit laajalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Sillä he eivät itse valloittaneet miekallaan maata eikä heidän käsivartensa heitä auttanut, vaan sinun oikea kätesi, sinun käsivartesi ja sinun kasvojesi valkeus, koska sinä olit heihin mieltynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Sinä, Jumala, sinä olet kuninkaani, toimita Jaakobille apu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Sinun avullasi syöksemme ahdistajamme maahan, sinun nimessäsi tallaamme vastustajamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Sillä minä en luota jouseeni, eikä miekkani minua auta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'vaan sinä pelastat meidät vihollisistamme, ja saatat vihamiehemme häpeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Jumala on meidän kerskauksemme kaikkina päivinä, ja sinun nimeäsi me ylistämme iankaikkisesti. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Kuitenkin sinä hylkäsit meidät ja saatoit meidät häpeään etkä lähtenyt sotaan meidän joukkojemme kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Sinä käänsit meidät vihollista pakoon, ja vihamiehemme ryöstivät saalista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Sinä annoit meidät syötäviksi kuin lampaat, ja hajotit meidät pakanoiden sekaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Sinä myit kansasi halvasta etkä heidän hinnastaan paljoa hyötynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Sinä annat meidät naapuriemme häväistäviksi, ympärillämme asuvien pilkaksi ja ivaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Sinä saatat meidät sananparreksi pakanoille, pään pudistukseksi kansoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Joka päivä on häväistykseni edessäni, ja kasvojeni häpeä peittää minut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'herjaajan ja pilkkaajan puheen tähden, vihollisen ja kostonhimoisen katseitten tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Tämä kaikki on meitä kohdannut, vaikka emme ole sinua unohtaneet emmekä liittoasi rikkoneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Sydämemme ei ole sinusta luopunut, eivätkä askeleemme poikenneet pois polultasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Kuitenkin sinä runtelit meidät sakaalien asuinsijoilla ja peitit meidät kuoleman varjolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Jos me olisimme unohtaneet Jumalamme nimen ja ojentaneet kätemme vieraan jumalan puoleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'eikö Jumala olisi sitä saanut tutkituksi, sillä hän tuntee sydämen salaisuudet?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Ei, vaan sinun tähtesi meitä surmataan kaiken päivää, meitä pidetään teuraslampaina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Herää, miksi nukut, Herra? Nouse, älä iäksi hylkää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Miksi peität kasvosi, unohdat kurjuutemme ja ahdistuksemme?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Sillä sielumme on vaipunut tomuun ja ruumiimme painunut maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 27, 'Nouse, auta meitä ja lunasta meidät armosi tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Veisuunjohtajalle. Veisataan kuin: \"Liljat\". Koorahilaisten mietevirsi. Laulu rakkaudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Sydämeni tulvii ihania sanoja. Minä lausun: kuninkaasta on lauluni, ja kieleni on nopean kirjurin kynä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Sinä olet ihmislapsista ihanin, suloisuus on vuodatettu huulillesi. Sen tähden Jumala siunaa sinua iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'Vyötä miekka vyöllesi, sankari, vyöttäydy valtasuuruuteesi ja kunniaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Menesty kunniassasi. Ratsasta totuuden, nöyryyden ja vanhurskauden tähden, ja oikea kätesi opettakoon sinulle pelättäviä tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Nuolesi ovat terävät. Kansat kaatuvat allesi, ne, jotka ovat sydämeltään kuninkaan vihollisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Jumala, sinun valtaistuimesi pysyy aina ja iankaikkisesti. Sinun valtakuntasi valtikka on oikeuden valtikka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Sinä rakastat vanhurskautta ja vihaat vääryyttä; sen tähden on Jumala, Jumalasi, voidellut sinua iloöljyllä enemmän kuin tovereitasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Mirhaa, aloeta ja kassiaa tuoksuvat kaikki vaatteesi, lyyrat helisevät iloksesi norsunluisista palatseista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Kuningasten tyttäriä on kaunistuksenasi, kuningatar seisoo oikealla puolellasi Oofirin kullassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Kuule, tytär, katso ja kallista korvasi, unohda kansasi ja isäsi huone,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'ja saakoon kuningas halun kauneuteesi, sillä hän on sinun Herrasi. Kumarra häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Tytär Tyyro ja kansan rikkaimmat etsivät lahjoillaan suosiotasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'Hyvin ihana on kuninkaan tytär sisäkammiossa, kultakudosta on hänen pukunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Kirjailluissa vaatteissa hänet saatetaan kuninkaan luo. Neitsyet seuraavat häntä, hänen ystävättärensä tuodaan luoksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Ilolla ja riemulla heitä saatetaan. He astuvat kuninkaan palatsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Sinun poikasi tulkoot isiesi sijaan. Aseta heidät ruhtinaiksi kaikkeen maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 18, 'Minä teen nimesi kuuluisaksi suvusta sukuun. Sen tähden kansat sinua ylistävät aina ja iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Veisuunjohtajalle; koorahilaisten laulu, korkeassa äänialassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Jumala on turvamme ja väkevyytemme, apumme hädässä aivan vahva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Sen tähden emme pelkää, vaikka maa järkkyisi ja vuoret vajoaisivat meren pohjaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'vaikka sen vedet pauhaisivat ja kuohuisivat ja vuoret vapisisivat sen raivosta. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Virta lähteineen ilahduttaa Jumalan kaupungin, Korkeimman pyhät asunnot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Jumala on sen keskellä. Se ei horju. Jumala auttaa sitä jo aamun koitteessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Pakanat pauhaavat, valtakunnat horjuvat. Kun hän jyrisee, huojuu maa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Herra Sebaot on meidän kanssamme. Jaakobin Jumala on linnamme. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Tulkaa, katsokaa Herran töitä, hänen, joka tekee hämmästyttäviä tekoja maan päällä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'hän lopettaa sodat maan ääriin saakka, hän särkee jousen, taittaa keihään, polttaa sotavaunut tulessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, '\"Vaietkaa ja tietäkää, että minä olen Jumala, korkea kansojen keskellä, korkea maan päällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 12, 'Herra Sebaot on kanssamme. Jaakobin Jumala on linnamme. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Veisuunjohtajalle; koorahilaisten psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Lyökää käsiänne yhteen, kaikki kansat, kohottakaa Jumalalle riemuhuuto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Sillä Herra on korkein, pelottava, koko maailman suuri kuningas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Hän kukistaa kansat allemme ja kansakunnat jalkojemme alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Hän on valinnut meille perintömaamme, joka on Jaakobin, hänen rakkaansa, kunnia. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Jumala astuu ylös riemun raikuessa, Herra torvien pauhatessa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Veisatkaa Jumalalle, veisatkaa, veisatkaa kuninkaallemme, veisatkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Sillä Jumala on koko maailman kuningas. Veisatkaa hänelle virsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Jumala on kansojen kuningas, Jumala istuu pyhällä istuimellaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 10, 'Kansojen päämiehet kokoontuvat Aabrahamin Jumalan kansaksi. Sillä maan kilvet ovat Jumalan. Hän on hyvin korkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Laulu, koorahilaisten psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Suuri on Herra ja korkeasti ylistettävä meidän Jumalamme kaupungissa, pyhällä vuorellaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Kauniina kohoaa, kaiken maan ilona, pohjoisen puolella Siionin vuori, suuren kuninkaan kaupunki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Jumala tunnetaan sen linnoissa turvana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Sillä katso, kuninkaat kokoontuivat, mutta kulkivat ohi yhdessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'He näkivät sen, hämmästyivät, pelästyivät ja pakenivat pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Vapina valtasi heidät siellä kuin tuska synnyttäjän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Itätuulella sinä särjet Tarsiin laivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Niin kuin olimme kuulleet, niin sen nyt näimme Herran Sebaotin kaupungissa, Jumalamme kaupungissa: Jumala pitää sen perustuksillaan iankaikkisesti. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Jumala, me tutkistelemme sinun armoasi sinun temppelissäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Jumala, kuten sinun nimesi, niin ulottuu sinun ylistyksesi maan ääriin saakka. Sinun oikea kätesi on vanhurskautta täynnä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Siionin vuori iloitsee, Juudan tyttäret riemuitsevat tuomioistasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Kiertäkää Siion, käykää sen ympäri, laskekaa sen tornit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Kiinnittäkää sydämenne sen muureihin, kulkekaa sen linnat, kertoaksenne niistä tulevalle polvelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 15, 'Sillä tämä on Jumala, Jumalamme, aina ja iankaikkisesti; hän johdattaa meitä kuolemaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Veisuunjohtajalle; koorahilaisten psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Kuulkaa tämä, kaikki kansat, ottakaa korviinne, kaikki maailman asukkaat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'sekä alhaiset että ylhäiset, niin rikkaat kuin köyhät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Suuni puhuu viisautta, sydämeni miettii ymmärrystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Kallistan korvani kuulemaan mietelauseita, selitän ongelmani lyyraa soittaen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Miksi pelkäisin pahoina päivinä, kun vainoojani vääryys piirittää minua?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'He luottavat tavaroihinsa ja kerskuvat suuresta rikkaudestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'Kukaan ei voi veljeään lunastaa eikä hänestä Jumalalle sovitusta maksaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'Sillä heidän sielujensa lunastus on hyvin kallis ja jää heiltä iäti suorittamatta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'vaikka hän eläisi iankaikkisesti eikä näkisi hautaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Vaan hänen täytyy nähdä, että viisaat kuolevat, että tyhmät ja järjettömätkin hukkuvat ja jättävät toisille omaisuutensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'He luulevat, että heidän huoneensa pysyvät iäti ja heidän asuntonsa polvesta polveen. He nimittävät maatiloja nimensä mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Mutta ihminen, mahtavinkaan, ei pysy: hän on kuin eläimet, jotka hukkuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Näin käy niiden, jotka luottavat itseensä, ja samoin heidän jäljessään niiden, jotka mieltyvät heidän puheisiinsa. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Kuin lammaslauma heidät viedään hautaan, kuolema heitä kaitsee. Jo huomenna oikeamieliset astuvat heidän ylitseen. Hauta kalvaa heidän hahmonsa, eikä heillä ole asuntoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Mutta minun sieluni Jumala lunastaa kuoleman vallasta, sillä hän ottaa minut hoivaansa. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Älä pelkää, jos joku rikastuu, jos hänen talonsa komeus karttuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Sillä kuollessaan hän ei ota mitään mukaansa, eikä hänen komeutensa astu alas hänen jäljessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Vaikka hän eläessään kiittää itseään siunatuksi, vaikka sinua ylistetään, kun vietät hyviä päiviä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'sinun täytyy mennä isiesi suvun luo, jotka eivät enää ikinä näe valoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 21, 'Ihminen, mahtavinkin, on ymmärrystä vailla, hän on kuin eläimet, jotka hukkuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Aasafin psalmi. Jumala, Herra Jumala, puhuu ja kutsuu maan esiin auringon noususta sen laskuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Siionista, jonka kauneus on täydellinen, Jumala ilmestyy kirkkaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Jumalamme tulee eikä vaikene, hänen edellään käy kuluttava tuli ja hänen ympärillään väkevä myrsky.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Hän kutsuu taivaat ylhäältä ja maan, tuomitakseen kansansa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, '\"Kootkaa eteeni pyhäni, jotka teurasuhreja uhraten ovat tehneet kanssani liiton.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Silloin taivaat julistavat hänen vanhurskauttaan, sillä Jumala on tuomari. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, '\"Kuule, kansani, minä puhun; kuule, Israel, minä todistan sinun keskelläsi. Minä olen Jumala, sinun Jumalasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'En minä nuhtele sinua teurasuhreistasi, ja sinun polttouhrisi ovat aina edessäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'En minä ota härkiä talostasi enkä pukkeja tarhoistasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Sillä minun ovat kaikki metsän eläimet ja tuhansien vuorten karjat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Minä tunnen kaikki vuorten linnut, ja kaikki, mikä kedolla liikkuu, on edessäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Jos minun olisi nälkä, en minä sitä sinulle sanoisi, sillä minun on maanpiiri ja kaikki, mitä siinä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Minäkö söisin härkien lihaa tai joisin pukkien verta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Uhraa Jumalalle kiitos ja täytä lupauksesi Korkeimmalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'ja avuksesi huuda minua hädän päivänä, niin minä tahdon auttaa sinua, ja sinun pitää kunnioittaa minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Mutta jumalattomalle Jumala sanoo: \"Mikä sinä olet puhumaan minun käskyistäni ja ottamaan liittoni suuhusi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Sinä, joka vihaat kuritusta ja heität sanani selkäsi taakse!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Jos sinä näet varkaan, sinä miellyt häneen, ja sinä pidät yhtä avionrikkojien kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Sinä päästät suusi puhumaan pahaa, ja kielesi punoo petosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Sinä istut ja puhut veljeäsi vastaan, sinä panettelet äitisi poikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Näitä sinä teet, ja minäkö olisin vaiti? Luuletko, että minä olen kaltaisesi? Minä nuhtelen sinua ja asetan nämä silmiesi eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Ymmärtäkää tämä, te, jotka Jumalan unohdatte, etten minä raatelisi, eikä olisi pelastajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Se, joka kiitosta uhraa, kunnioittaa minua. Sen, joka ottaa tiestään vaarin, annan nähdä Jumalan autuuden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Veisuunjohtajalle. Daavidin psalmi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'kun profeetta Naatan tuli hänen luokseen, sen jälkeen kun hän oli yhtynyt Batsebaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Jumala, ole minulle armollinen hyvyytesi tähden. Pyyhi pois syntini suuren laupeutesi tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Pese minut puhtaaksi rikoksestani, puhdista minut synnistäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Sillä minä tunnen rikokseni, ja syntini on aina edessäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Sinua ainoaa vastaan olen syntiä tehnyt, tehnyt sitä, mikä on pahaa silmissäsi, jotta sinä olisit vanhurskas puheessasi ja puhdas tuomitessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Katso, olen synnissä syntynyt, ja äitini on minut synnissä alulle saattanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Katso, sinä miellyt totuuteen, joka on salassa, ja sisimmässäni sinä ilmoitat minulle viisauden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Puhdista minut iisopilla, että puhdistuisin, pese minut, että minä tulisin lunta valkeammaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Anna minun kuulla iloa ja riemua, että ilahtuisivat ne luut, jotka olet särkenyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Peitä kasvosi näkemästä syntejäni, pyyhi pois kaikki pahat tekoni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Jumala, luo minuun puhdas sydän ja anna minulle uusi, vahva henki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Älä heitä minua pois kasvojesi edestä, äläkä ota minulta pois Pyhää Henkeäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Anna minulle jälleen autuutesi ilo, ja tue minua alttiuden hengellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Minä tahdon opettaa laittomuuden tekijöille tiesi, että syntiset palaisivat luoksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Päästä minut veriveloista, Jumala, autuuteni Jumala, että kieleni riemuitsisi vanhurskaudestasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Herra, avaa huuleni, että suuni julistaisi kiitostasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Sillä sinulle ei kelpaa teurasuhri, sen minä kyllä antaisin. Polttouhri ei ole sinulle mieleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Jumalalle kelpaava uhri on särjetty henki. Särjettyä ja murtunutta sydäntä et sinä, Jumala, hylkää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 20, 'Osoita armossasi hyvyyttä Siionille, rakenna Jerusalemin muurit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 21, 'Silloin sinulle kelpaavat oikeat teurasuhrit, polttouhrit ja kokonaisuhrit. Silloin uhrataan härkiä sinun alttarillasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Veisuunjohtajalle; Daavidin mietevirsi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'kun edomilainen Dooeg tuli ja ilmoitti Saulille, sanoen hänelle: \"Daavid on mennyt Ahimelekin taloon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Miksi kerskailet pahuudestasi, sinä väkivaltainen? Jumalan armo pysyy joka päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Kielesi punoo turmiota, se on kuin terävä partaveitsi, sinä petoksen tekijä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Sinä rakastat pahaa enemmän kuin hyvää, valhetta enemmän kuin vanhurskauden puhumista. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Sinä rakastat kaikkia surman sanoja, sinä kavala kieli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Sen tähden myös Jumala kukistaa sinut ainiaaksi. Hän tarttuu sinuun ja raastaa sinut telttamajastasi, repäisee sinut juurinesi elävien maasta. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Vanhurskaat näkevät sen ja pelkäävät, ja he nauravat hänelle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, '\"Katso, siinä on mies, joka ei pitänyt Jumalaa turvanаan, vaan luotti suureen rikkauteensa ja vahvistui pahuudessaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 10, 'Mutta minä olen kuin viheriöivä öljypuu Jumalan huoneessa. Minä turvaan Jumalan armoon aina ja iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 11, 'Kiitän sinua iäti, että sen teit, ja odotan nimeäsi, sillä se on hyvä pyhiesi edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Veisuunjohtajalle. Veisataan kuin: \"Sairaus\". Daavidin mietevirsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Hullu sanoo sydämessään: \"Ei ole Jumalaa.\" Turmiollinen ja iljettävä on heidän väärä menonsa. Ei ole ketään, joka tekee sitä, mikä hyvä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Jumala katsoo taivaasta ihmislapsiin, jotta näkisi, onko ketään ymmärtäväistä, onko ketään, joka etsii Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Mutta he ovat kaikki poikenneet pois, kaikki tyynni he ovat käyneet kelvottomiksi. Ei ole ketään, joka tekee sitä, mikä hyvä on, ei yhden yhtäkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Eivätkö he mitään käsitä, nuo väärintekijät, jotka saavat leipänsä syömällä kansaani eivätkä huuda avukseen Jumalaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Siinä heidät valtaa kauhu, missä kauhistavaa ei ole, sillä Jumala hajottaa niiden luut, jotka sinua piirittävät. Sinä saatat heidät häpeään, sillä Jumala hylkää heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 7, 'Oi, että Israelille tulisi pelastus Siionista! Kun Jumala vapauttaa vangitun kansansa, silloin Jaakob riemuitsee, Israel iloitsee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Veisuunjohtajalle; kielisoittimilla; Daavidin mietevirsi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'kun siifiläiset tulivat ja sanoivat Saulille: \"Daavid piileskelee luonamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Jumala, pelasta minut nimesi voimalla, aja asiani väkevyydelläsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Jumala, kuule rukoukseni, ota korviisi suuni sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Sillä muukalaiset nousevat minua vastaan, ja väkivaltaiset väijyvät henkeäni. He eivät pidä Jumalaa silmiensä edessä. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Katso, Jumala on auttajani, Herra on sieluni tuki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Kohdatkoon vihamiehiäni paha, hävitä heidät uskollisuudessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 8, 'Minä uhraan sinulle alttiisti ja ylistän nimeäsi, Herra, sillä se on hyvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 9, 'Sillä hän pelastaa minut kaikesta hädästä, ja silmäni katselee pelotta vihollisiani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Veisuunjohtajalle. Kielisoittimilla. Daavidin mietevirsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Jumala, ota korviisi rukoukseni. Älä kätkeydy, kun anon armoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Kuuntele minua ja vastaa minulle. Minä kuljen rauhattomana murheessani ja huokaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'koska vihamies huutaa ja jumalaton ahdistaa. Sillä he vyöryttävät päälleni turmiota ja vainoavat minua vihassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Sydämeni rinnassani vapisee, kuoleman kauhut lankeavat päälleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Pelko ja vapina on vallannut minut, ja kauhu on peittänyt minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Sanon: Olisipa minulla siivet kuin kyyhkysellä, niin lentäisin pois ja pääsisin lepoon!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Katso, pakenisin kauas ja yöpyisin erämaassa. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Minä rientäisin pakopaikkaani rajuilman ja myrskyn alta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Sekoita, Herra, tee eripuraiseksi heidän kielensä, sillä näen väkivaltaa ja riitaa kaupungissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Yötä päivää he kiertävät sitä sen muureja pitkin, vääryys ja vaiva ovat sen keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Sen keskellä on turmio. Sorto ja petos eivät väisty sen torilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Sillä minua ei herjaa vihollinen – sen kestäisin – eikä minua vastaan ylvästele vihamieheni – hänen edestään voisin piiloutua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Vaan sinä, vertaiseni, sinä, ystäväni ja uskottuni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'jonka kanssa me elimme suloisessa sovussa, yhdessä vaelsimme Jumalan huoneeseen kohinassa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Karatkoon kuolema heidän kimppuunsa, menkööt he elävältä alas helvettiin, sillä heidän asunnoissaan ja sydämissään vallitsee pelkkä pahuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Mutta minä huudan Jumalaa, ja Herra pelastaa minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Illoin, aamuin ja keskipäivällä valitan ja huokaan, ja hän kuulee ääneni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Hän päästää sieluni heistä rauhaan, etteivät he saavuta minua. Sillä paljon on niitä, jotka ovat minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Jumala kuulee sen ja vastaa heille, hän, joka hallitsee alusta lähtien. Sela. Sillä he eivät muuta mieltään eivätkä pelkää Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Tuo mies käy käsiksi niihin, jotka elävät hänen kanssaan rauhassa. Hän rikkoo liittonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Hänen suunsa on voita sulavampi, mutta hänellä on sota mielessä. Hänen sanansa ovat öljyä lauhkeammat, mutta ovat kuin paljastetut miekat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Heitä murheesi Herran huomaan, hän pitää sinusta huolen. Hän ei salli vanhurskaan ikinä horjua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 24, 'Mutta heidät sinä, Jumala, syökset helvetin syvyyteen. Murhamiehet ja petturit eivät pääse puoleen ikäänsä. Mutta minä turvaan sinuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Veisuunjohtajalle; veisataan kuin: \"Mykkä kyyhkynen kaukaisessa maassa.\" Daavidin laulu, kun filistealaiset ottivat hänet kiinni Gatissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Jumala, ole minulle armollinen, sillä ihmiset tahtovat minut niellä, joka päivä he sotivat minua vastaan ja ahdistavat minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Joka päivä vihamieheni tahtovat minut niellä, sillä paljon on niitä, jotka ylpeästi sotivat minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Mutta sinä päivänä, jota minä pelkään, minä turvaan sinuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Jumalaan luotan ja ylistän hänen sanaansa, Jumalaan turvaan enkä pelkää. Mitä liha minulle tekisi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Joka päivä he vääntelevät sanojani, kaikki heidän ajatuksensa tarkoittavat minulle pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'He ahdistavat, väijyvät minua ja vakoilevat askeleitani, sillä he tavoittelevat henkeäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Hekö pahuudessaan pelastuisivat? Syökse, Jumala, vihassasi kansat maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Sinä olet lukenut pakolaispäiväni. Pane leiliisi kyyneleeni, ovathan ne kirjassasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Kerran väistyvät viholliseni, sinä päivänä, jona huudan. Tiedän, että Jumala on puolellani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'Jumalaan minä luotan ja ylistän hänen sanaansa, Herraan minä luotan ja ylistän hänen sanaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Jumalaan turvaan enkä pelkää. Mitä ihminen minulle tekisi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Minulla on lupaus täytettävänä sinulle, Jumala: annan sinulle kiitosuhrit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 14, 'Sillä sinä pelastit sieluni kuolemasta ja jalkani kompastumasta, että minä vaeltaisin Jumalan edessä, elävien valkeudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Veisuunjohtajalle. Veisataan kuin \"Älä turmele\". Daavidin laulu, kun hän pakeni Saulia luolaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Jumala, ole minulle armollinen, ole minulle armollinen, sillä sieluni turvaa sinuun. Turvaan siipiesi suojaan, kunnes onnettomuudet ovat ohi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Huudan avukseni Jumalaa, Korkeinta, Jumalaa, joka vie asiani päätökseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Hän lähettää taivaasta minulle pelastuksen, kun ne, jotka haluavat minut niellä, herjaavat minua. Sela. Jumala lähettää armonsa ja totuutensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Sieluni on leijonien keskellä. Minun täytyy maata raatelevien petojen keskellä, ihmisten, joiden hampaat ovat keihäitä ja nuolia, ja joiden kieli on terävä miekka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Korota itsesi yli taivaitten, Jumala, ja kunniasi yli kaiken maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'He virittivät verkon askelteni tielle, painoivat sieluni maahan, kaivoivat eteeni kuopan, mutta itse he siihen suistuivat. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Jumala, sydämeni on luja, sydämeni on luja: minä tahdon laulaa ja soittaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Herää, kunniani; herää, harppu ja lyyra. Haluan herätä varhain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Herra, kiitän sinua kansojen joukossa, veisaan kiitostasi niiden keskellä, jotka eivät ole kansakuntia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Sillä suuri on sinun armosi ja ulottuu taivaisiin asti, ja sinun totuutesi pilviin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 12, 'Korota itsesi yli taivaitten, Jumala, ja kunniasi yli kaiken maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Veisuunjohtajalle. Veisataan kuin \"Älä turmele\". Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Totisesti, onko vanhurskaus mykkä, ja te puhutte? Tekö tuomitsette oikein, te ihmislapset?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Ei, vaan te hankitte sydämessänne vääryyttä, teidän kätenne käyttävät maassa väkivallan vaakaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Luopuneita ovat jumalattomat äidin kohdusta asti, eksyneitä valehtelijat äidin helmasta asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Heidän myrkkynsä on kuin käärmeen myrkky, he ovat kuin kuuro kyy, joka tukkii korvansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'ettei kuulisi lumoajan ääntä, taitavan lumoajan lumoussanoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Jumala, särje hampaat heidän suustaan, Herra, murra nuorten leijonien raateluhampaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Haihtukoot he tyhjiin kuin vesi, joka valuu kuiviin. Kun he ampuvat nuolensa, olkoot ne kuin kärjettömät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Olkoot he kuin etana, joka sulaa madellessaan, kuin vaimon keskoset, jotka eivät näe aurinkoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Ennen kuin teidän patanne tuntevat orjantappuroista tulevan tulen allaan, hän myrskyllään puhaltaa pois kaiken, niin raa\'an kuin kypsänkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Vanhurskas iloitsee, kun hän näkee koston. Hän pesee jalkansa jumalattoman veressä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 12, 'Silloin ihmiset sanovat: \"Totisesti, vanhurskaalla on hedelmä. Totisesti, on Jumala, joka tuomitsee maan päällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Veisuunjohtajalle; veisataan kuin \"Älä turmele\". Daavidin psalmi, kun Saul lähetti vartioimaan hänen taloaan tappaakseen hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Jumalani, pelasta minut vihollisistani, suojele minua niiltä, jotka nousevat minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Pelasta minut pahantekijöistä, vapahda minut murhamiehistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Sillä, katso, he väijyvät henkeäni. Väkevät kokoontuvat minua vastaan, vaikka en ole rikkonut enkä syntiä tehnyt, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Ilman minun syytäni he juoksevat ja valmistautuvat. Herää, käy minua kohden ja katso.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Sinä, Herra, Jumala Sebaot, Israelin Jumala, herää kostamaan kaikille pakanoille. Älä säästä ketään epäuskoista väärintekijää. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'He tulevat ehtoolla, ulvovat kuin koirat ja kiertävät kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Katso, heidän suustaan lähtee sanatulva, miekat ovat heidän huulillaan, sillä: \"Kenen on sitä kuunneltava?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Mutta, Herra, sinä naurat heille, sinä pidät pilkkanasi kaikkia pakanoita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Sinä, väkevyyteni, sinusta minä otan vaarin, sillä Jumala on linnani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Armollinen Jumalani käy minua kohden. Jumala on antava minun kokea iloa vihollisistani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Älä heitä tapa, ettei kansani sitä unohda. Saata voimallasi heidät harhailemaan ja syökse heidät maahan, Herra, kilpemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Heidän huultensa puhe on heidän suunsa synti. Otettakoon heidät kiinni heidän ylpeydessään kirousten ja valheiden tähden, joita he puhuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Hävitä heidät vihassasi, hävitä olemattomiin, ja tietäkööt, että Jumala hallitsee Jaakobissa maan ääriin asti. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'He tulevat ehtoolla, ulvovat kuin koirat ja kiertävät kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'He harhailevat ruuan haussa. Elleivät tule ravituiksi, he murisevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Mutta minä laulan väkevyydestäsi ja riemuitsen aamulla armostasi, sillä sinä olet minun linnani ja pakopaikkani hätäni päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 18, 'Sinä, väkevyyteni, sinulle minä veisaan kiitosta, sillä Jumala on linnani ja armollinen Jumalani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Veisuunjohtajalle. Veisataan kuin \"Todistuksen lilja\". Daavidin psalmi, opetettavaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'kun hän taisteli Mesopotamian aramilaisia ja Sooban aramilaisia vastaan ja Jooab palasi ja voitti Suolalaaksossa edomilaiset, kaksitoista tuhatta miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Jumala, sinä hylkäsit meidät, sinä hajotit meidät ja olit vihastunut. Auta meidät ennallemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Sinä saatoit maan järkkymään ja halkeilemaan. Korjaa sen repeämät, sillä se horjuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Sinä olet antanut kansasi nähdä kovia päiviä. Olet juottanut meitä päihdyttävällä viinillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Mutta sinä olet antanut lipun niille, jotka sinua pelkäävät, että he kokoontuisivat jousta pakoon lippusi turviin. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Jotta sinun rakkaasi tulisivat pelastetuiksi, auta oikealla kädelläsi ja vastaa meille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Jumala on puhunut pyhäkössään! Minä riemuitsen, minä jaan Sikemin ja mittaan Sukkotin laakson.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Minun on Gilead, minun on Manasse, Efraim on pääni suojus, Juuda valtikkani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Mooab on pesuastiani. Edomiin minä heitän sandaalini. Filistea, nosta minulle riemuhuuto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Kuka vie minut varustettuun kaupunkiin? Kuka saattaa minut Edomiin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Etkö sinä, Jumala, hylännyt meidät? Jumala, sinä et lähtenyt sotajoukkojemme kanssa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 13, 'Anna meille apu ahdistajaa vastaan, sillä turha on ihmisten apu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 14, 'Jumalan voimalla teemme väkeviä tekoja. Hän tallaa vihollisemme maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Veisuunjohtajalle. Kielisoittimilla. Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Kuule, Jumala, huutoni, huomaa rukoukseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Maan ääristä sinua huudan, kun sydämeni nääntyy. Saata minut kalliolle, joka on minulle liian korkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Sillä sinä olet turvapaikkani, vahva torni vihollista vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Suo minun asua telttamajassasi iankaikkisesti ja turvautua siipiesi suojaan. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Sillä sinä, Jumala, kuulet lupaukseni, sinä annat perinnön niille, jotka pelkäävät nimeäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Sinä lisäät kuninkaalle päiviä päiviin. Hänen vuotensa jatkukoot polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Hallitkoon hän iankaikkisesti Jumalan kasvojen edessä. Säädä armo ja totuus häntä varjelemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 9, 'Niin veisaan iankaikkisesti nimesi kiitosta ja täytän lupaukseni päivästä päivään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Veisuunjohtajalle. Jedutunin tapaan. Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Jumalaa yksin sieluni odottaa hiljaisuudessa. Häneltä tulee minulle apu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Hän yksin on kallioni, apuni ja turvani: en suuresti horju.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Kuinka kauan te yhtä miestä ahdistatte hänet yhdessä surmataksenne, niin kuin hän olisi kaatuva seinä, kuin luhistuva muuri?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'He vain pitävät neuvoa, miten syöstä hänet korkeudestaan. He rakastavat valhetta, he siunaavat suullaan ja kiroavat sydämessään. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Odota yksin Jumalaa hiljaisuudessa, sieluni, sillä häneltä tulee toivoni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Hän yksin on kallioni, apuni ja turvani: en horju.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Jumalassa on apuni ja kunniani. Väkevyyteni kallio ja turvani on Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Turvatkaa häneen joka aika, te kansa. Vuodattakaa hänen eteensä sydämenne. Jumala on turvamme. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Todella tuulen henkäystä ovat ihmiset, valhetta ylhäisten lapset: kaikki he nousevat vaa\'assa ylös kevyempinä kuin tuulenhenkäys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Älkää luottako väkivaltaan älkääkä turhaan panko toivoanne ryöstettyyn tavaraan. Jos rikkautta karttuu, älkää siihen sydäntänne kiinnittäkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Kerran on Jumala sanonut, kahdesti olen sen kuullut: voima on Jumalan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 13, 'Sinun, Herra, on myös armo, sillä sinä maksat kullekin hänen tekojensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Daavidin psalmi, kun hän oli Juudan erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Jumala, sinä olet Jumalani, sinua minä etsin varhain. Sinua sieluni janoaa, sinua ikävöi ruumiini kuivassa ja janoon nääntyvässä, vedettömässä maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Niin minä katselin sinua pyhäkössä, nähdäkseni voimasi ja kunniasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Sillä armosi on parempi kuin elämä. Huuleni ylistäkööt sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Minä kiitän sinua elinaikani ja nostan käteni nimesi puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Sieluni ravitaan kuin lihavuudella ja rasvalla, ja suuni ylistää sinua riemuitsevin huulin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'kun vuoteessani sinua muistan ja ajattelen sinua yön vartiohetkinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Sillä sinä olet apuni, ja siipiesi suojassa minä riemuitsen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Sieluni riippuu sinussa kiinni ja oikea kätesi tukee minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Mutta he etsivät henkeäni omaksi turmiokseen ja menevät maan syvyyksiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Heidät annetaan miekalle alttiiksi, ja he joutuvat sakaalien saaliiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 12, 'Mutta kuningas on iloitseva Jumalassa. Hän on jokaisen ylistys, joka hänen kauttaan vannoo. Sillä valehtelijoiden suu tukitaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Veisuunjohtajalle. Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Kuule, Jumala, ääneni, kun valitan, varjele elämäni vihollisen pelosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Suojaa minut pahojen kokoukselta, pahantekijäin meluavalta joukolta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'jotka hiovat kielensä kuin miekan, ja jännittävät jousensa nuolinaan karvaat sanat');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'ampuakseen salaa nuhteettoman. He ampuvat häntä äkkiä eivätkä kavahda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'He pysyvät lujina pahoissa aikeissaan. He kehuvat, kuinka he virittävät pauloja. He sanovat: \"Kuka ne näkee?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'He miettivät vääryyksiä: \"Meillä on juoni valmiiksi mietittynä.\" Syvä on miehen sisin ja sydän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Mutta Jumala ampuu heidät nuolella. Äkkiä heitä kohtaavat iskut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'He kompastuvat, heidän oma kielensä langettaa heidät. Kaikki, jotka heidät näkevät, nyökyttävät ilkkuen päätään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Mutta kaikki ihmiset pelästyvät. He julistavat Jumalan töitä ja ottavat vaarin hänen teoistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 11, 'Vanhurskas iloitsee Herrassa ja turvaa häneen, ja kaikki oikeamieliset ylistävät häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Veisuunjohtajalle. Daavidin psalmi, laulu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Jumala, hiljaisuudessa kiitetään sinua Siionissa, ja sinulle täytetään lupaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Sinä kuulet rukouksen: luoksesi tulee kaikki liha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Syntivelkani ovat raskaat. Olemme rikkoneet, mutta sinä sovitat rikoksemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Autuas se, jonka valitset ja otat luoksesi esikartanoihisi asumaan! Salli meidän tulla ravituiksi huoneesi hyvyydellä, temppelisi pyhyydellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Ihmeellisillä teoilla vastaat meille vanhurskaudessa, sinä, autuutemme Jumala, sinä, kaikkien maan äärten ja kaukaisen meren turva,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'joka voimallasi vahvistat vuoret ja olet vyötetty väkevyydellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Sinä, joka hiljennät merten kohinan, niiden aaltojen pauhun ja kansojen metelin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'niin että ne, jotka niiden äärillä asuvat, hämmästyvät ihmeitäsi. Aamun ja illan sinä täytät riemulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Sinä pidät maasta huolen, kastelet sen runsaasti, sinä teet sen hyvin rikkaaksi. Jumalan virta on vettä täynnä. Sinä valmistat heidän viljansa, sillä niin sinä vahvistat maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Sinä kastelet sen vaot, sinä muhennat sen mullan, sadekuuroilla sinä sen pehmität ja siunaat sen viljan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Sinä kaunistat vuoden hyvyydelläsi, ja polkusi vuotaa lihavuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Erämaan laitumet saavat vettä, ja kukkulat vyöttäytyvät riemuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 14, 'Kedot verhoutuvat lammaslaumoihin, ja vilja peittää laaksot. Riemuitaan ja lauletaan!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Veisuunjohtajalle. Laulu, psalmi. Kohottakaa Jumalalle riemuhuuto, kaikki maa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Veisatkaa hänen nimensä kunniaa, antakaa hänelle kunnia ja ylistys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Sanokaa Jumalalle: \"Kuinka pelottavat ovatkaan tekosi!\" Suuren voimasi tähden vihollisesi lyyhistyvät edessäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Kaikki maa kumartakoon sinua ja veisatkoon kiitostasi, veisatkoon nimesi kiitosta. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Tulkaa ja katsokaa Jumalan töitä: hän on pelottava teoissaan ihmisten lapsia kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Hän muutti meren kuivaksi maaksi: jalan mentiin virran poikki. Silloin me iloitsimme hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Hän hallitsee voimallaan iankaikkisesti, hänen silmänsä vartioivat kansoja. Niskoittelijat älkööt nousko. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Kiittäkää, te kansat, Jumalaamme, kaiuttakaa korkealle hänen ylistystään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'Hän antaa sielullemme elämän eikä salli jalkamme horjua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Sillä sinä, Jumala, olet koetellut meitä, olet sulattanut meitä, niin kuin hopea sulatetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Sinä veit meidät verkkoon, panit kuorman lanteillemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Sinä annoit ihmisten ajaa päämme yli, me jouduimme tuleen ja veteen. Mutta sinä veit meidät yltäkylläisyyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Minä tuon huoneeseesi polttouhreja, täytän sinulle lupaukseni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'joihin huuleni avautuivat ja jotka suuni hädässäni lausui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Lihavat polttouhrit sinulle uhraan sekä pässien uhrituoksun. Uhraan sinulle härkiä ja vuohia. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Tulkaa, kuulkaa, kerron teille, kaikki te Jumalaa pelkäävät, mitä hän on sielulleni tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Häntä suullani huusin, ja ylistys tuli kielelleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Jos minulla olisi vääryys sydämessäni, Herra ei minua kuulisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Mutta Jumala kuuli minua ja otti vaarin rukoukseni äänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Kiitetty olkoon Jumala, joka ei hylännyt rukoustani eikä ottanut minulta pois armoaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Veisuunjohtajalle. Kielisoittimilla. Psalmi, laulu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Jumala olkoon meille armollinen ja siunatkoon meitä, hän valaiskoon kasvonsa meille, – sela –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'että maan päällä tunnettaisiin tiesi ja kaikissa pakanakansoissa autuutesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Sinua, Jumala, kansat kiittäkööt, sinua kaikki kansat kiittäkööt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Iloitkoot ja riemuitkoot kansakunnat, sillä sinä tuomitset kansat oikein ja johdatat kansakunnat maan päällä. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Sinua, Jumala, kansat kiittäkööt, sinua kaikki kansat kiittäkööt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Maa on satonsa antanut. Siunatkoon meitä Jumala, Jumalamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 8, 'Siunatkoon meitä Jumala, ja pelätkööt häntä kaikki maan ääret.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Veisuunjohtajalle. Daavidin psalmi, laulu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Jumala nousee, hänen vihollisensa hajaantuvat, hänen vihamiehensä pakenevat hänen kasvojensa edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Sinä hajotat heidät, kuin savu hajoaa, kuin vaha sulaa tulen hohteessa, niin jumalattomat häviävät Jumalan kasvojen edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Mutta vanhurskaat iloitsevat ja riemuitsevat Jumalan kasvojen edessä ja ihastuvat ilosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Laulakaa Jumalalle, veisatkaa hänen nimensä kiitosta. Ylistäkää häntä, joka ratsastaa taivaitten päällä. Hänen nimensä on Herra. Riemuitkaa hänen kasvojensa edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Hän on orpojen isä ja leskien puolustaja, Jumala pyhässä asunnossaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Jumala, joka antaa hylätyille kodin ja johtaa vangitut onneen. Vain niskoittelijat asuvat kuivassa maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Jumala, kun kävit kansasi edellä, kun kuljit erämaassa, – sela –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'maa vapisi ja taivaat vuotivat Jumalan kasvojen edessä, Siinai vapisi Jumalan, Israelin Jumalan, kasvojen edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Runsaalla sateella sinä, Jumala, kostutit perintömaasi. Sinä virvoitit sen, kun se oli näännyksissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Sinun laumasi asettui siihen. Hyvyydessäsi, Jumala, sinä valmistit sen kurjille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Herra antaa sanoman. Suuri on evankeliumin julistajien joukko:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, '\"Sotajoukkojen kuninkaat pakenevat. He pakenevat, ja perheen emäntä jakaa saaliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Jäättekö makailemaan karjatarhojen vaiheille? Kyyhkysen siivet ovat hopealla silatut, sen sulat keltaisella kullalla!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Kun Kaikkivaltias siellä hajotti kuninkaat, satoi lunta Salmonilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Baasanin vuori on Jumalan vuori, Baasanin vuori on monihuippuinen vuori.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Miksi te, monihuippuiset vuoret, karsaasti katsotte vuorta, jolla Jumala on mieltynyt asumaan? Totisesti, Herra asuu siellä iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Jumalan sotavaunuja on kymmenet tuhannet, on tuhat kertaa tuhat. Herra on niiden keskellä, pyhyydessään kuin Siinai.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Sinä astuit ylös korkeuteen, otit vankeja saaliiksesi, sait ihmisiä lahjoiksesi: niskoittelijatkin joutuvat asumaan Herran Jumalan luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Kiitetty olkoon Herra joka päivä. Meitä kantaa Jumala, autuutemme. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Meillä on Jumala, Jumala, joka pelastaa, ja Herra, Herra, joka kuolemasta vapahtaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Mutta Jumala murskaa vihollistensa pään, niiden karvaisen päälaen, jotka synneissään vaeltavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Herra sanoo: \"Baasanista minä heidät palautan, palautan heidät meren syvyyksistä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'että polkisit jalkasi vereen ja että koiriesi kieli saisi osansa vihollisista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'He näkivät juhlasaattosi, Jumala, Jumalani, kuninkaani, juhlasaatot pyhäkössä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'Laulajat käyvät edellä, lyyransoittajat jäljessä, keskellä neitsyet tamburiineja lyöden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Kiittäkää Jumalaa seurakunnan kokouksissa, kiittäkää Herraa te, jotka olette Israelin lähteestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Tuolla on Benjamin, nuorin, heitä johtaen, Juudan ruhtinaat joukkoineen, Sebulonin ruhtinaat, ja Naftalin ruhtinaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Jumalasi on säätänyt sinulle vallan. Vahvista, Jumala, minkä olet hyväksemme tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Temppeliäsi varten, joka kohoaa Jerusalemissa, kuninkaat tuovat lahjoja sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Käske ankarasti ruovikon petoa, härkien laumaa sekä vasikoita, kansoja, lankeamaan maahan hopeaharkkoineen. Hän hajottaa kansat, jotka sotia rakastavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Mahtavat saapuvat Egyptistä ja Kuus kiirehtii ojentamaan käsiään Jumalan puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Te maan valtakunnat, laulakaa Jumalalle, veisatkaa Herralle kiitosta, – sela –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'hänen, joka ratsastaa ikuisten taivaitten taivaissa! Katso, hän antaa äänellään väkevän jyrinän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Antakaa väkevyys Jumalalle! Hänen valtasuuruutensa on Israelin yllä ja hänen voimansa pilvien tasalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 36, 'Pelottava on Jumala, joka ilmestyy pyhäköstäsi, Israelin Jumala. Hän antaa kansalleen voiman ja väkevyyden. Kiitetty olkoon Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Veisuunjohtajalle. Veisataan kuin: \"Liljat\"; Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Pelasta minut, Jumala, sillä vedet käyvät sieluuni asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Olen vajonnut syvään, pohjattomaan liejuun, olen joutunut vetten syvyyksiin, ja virta tulvii ylitseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Olen väsynyt huutamisesta, kurkkuni kuivettuu ja silmäni ovat rauenneet odottaessani Jumalaani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Enemmän kuin hiuksia päässäni on niitä, jotka vihaavat minua syyttä. Paljon on niitä, jotka tahtovat tuhota minut, jotka ovat syyttä vihollisiani. Mitä en ole ryöstänyt, se minun täytyy maksaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Jumala, sinä tunnet hulluuteni, eivätkä vikani ole sinulta salassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Älä anna minussa häpeään joutua niiden, jotka odottavat sinua, Herra, Herra Sebaot. Älä salli minussa pettyä niiden, jotka etsivät sinua, Israelin Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Sillä sinun tähtesi minä kärsin herjausta ja pilkka peittää kasvoni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Veljilleni minä olen tullut vieraaksi, olen tullut oudoksi äitini lapsille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Sillä kiivaus huoneesi puolesta on minut kuluttanut, ja niiden herjaukset, jotka sinua herjaavat, ovat sattuneet minuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Minä, minun sieluni itki ja paastosi, mutta siitä koitui minulle vain herjausta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Minä pukeuduin säkkipukuun, mutta tulin sananparreksi heidän suussaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Porteissa istujat minusta jaarittelevat, ja juomarit minusta laulavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Mutta minä rukoilen sinua, Herra, otollisella ajalla, sinua, Jumala, suureen laupeuteesi turvaten. Vastaa minulle pelastavan uskollisuutesi tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Päästä minut loasta, etten siihen vajoa, auta, että pääsen vihollisistani ja syvistä vesistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Älä anna vetten vuon minua upottaa, syvyyden minua niellä äläkä kuilun sulkea suutaan ylitseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Vastaa minulle, Herra, sillä armosi on hyvä, käänny puoleeni suuressa laupeudessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Älä peitä kasvojasi palvelijaltasi, sillä minä olen ahdistuksessa. Joudu, vastaa minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Lähesty sieluani ja lunasta se, vapahda minut vihollisteni tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Sinä tiedät häväistykseni, häpeäni ja pilkkani, edessäsi ovat julki kaikki ahdistajani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Häväistys on särkenyt sydämeni. Olen käynyt heikoksi. Odotin sääliä, mutta en saanut, ja lohduttajia, mutta en löytänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Koiruohoa he antoivat syödäkseni ja juottivat minulle janooni hapanviiniä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Tulkoon heidän pöytänsä heille paulaksi, ansaksi noille suruttomille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Sokaistukoot heidän silmänsä, niin etteivät näe, ja saata heidän lanteensa alati horjumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Vuodata vihastuksesi heidän päälleen, ja yllättäköön heidät vihasi hehku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Joutukoon heidän leiripaikkansa autioksi, älköönkä heidän teltoissaan asukasta olko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Sillä he vainoavat sitä, jota sinä olet lyönyt, ja kerskuvat niiden tuskista, joita sinä olet haavoittanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Lisää heille rikosta rikoksen päälle, mutta vanhurskauteesi he älkööt pääskö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Pyyhittäköön heidät pois elämän kirjasta, älköönkä heitä kirjoitettako vanhurskasten lukuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Mutta minä olen kurja ja vaivattu, suojatkoon minua sinun apusi, Jumala,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'niin minä veisuulla kiitän Jumalan nimeä ja ylistän häntä kiitosvirsillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Se on Herralle otollisempi kuin härkä, kuin mulli, sarvipää ja sorkkajalka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Nöyrät näkevät sen ja riemuitsevat. Elpyköön sydämenne, teidän, jotka etsitte Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Sillä Herra kuulee köyhiä eikä halveksi vankejaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Kiittäkööt häntä taivaat ja maa, meret ja kaikki, mitä niissä liikkuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Sillä Jumala on pelastava Siionin ja rakentava Juudan kaupungit, niin että he asettuvat niihin ja omistavat ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 37, 'Hänen palvelijoidensa jälkeläiset saavat sen perinnökseen, ja ne, jotka hänen nimeään rakastavat, saavat asua siinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Veisuunjohtajalle. Daavidin kirjoittama. Syntiä tunnustettaessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Jumala, riennä pelastamaan minut, riennä avukseni, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Joutukoot häpeään ja punastukoot ne, jotka väijyvät henkeäni. Peräytykööt ja saakoot häpeän ne, jotka tahtovat minulle onnettomuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Kääntykööt takaisin häpeissään ne, jotka sanovat: \"Kas niin, kas niin!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Iloitkoot ja riemuitkoot sinussa kaikki, jotka sinua etsivät ja joille autuutesi on rakas. He sanokoot aina: \"Ylistetty olkoon Jumala!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 6, 'Mutta minä olen kurja ja köyhä. Jumala, riennä luokseni. Sinä olet apuni ja vapauttajani. Herra, älä viivy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Sinuun, Herra, minä turvaan, älä salli minun ikinä joutua häpeään');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Pelasta minut, vapahda minut vanhurskaudessasi, kallista korvasi puoleeni ja auta minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Ole minulle kallio, jolla saan asua ja jonne saan aina mennä, sinä, joka olet säätänyt minulle pelastuksen. Sillä sinä olet kallioni ja linnani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Jumalani, vapauta minut jumalattoman kädestä, väärän ja väkivaltaisen kourista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Sillä sinä olet toivoni, Herra, Herra, turvani nuoruudestani asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Sinä olet ollut tukeni syntymästäni saakka, sinä päästit minut äitini kohdusta. Sinua minä alati ylistän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Monelle minä olen kuin ihme, mutta sinä olet minun vahva turvapaikkani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Minun suuni on täynnä kiitostasi, täynnä ylistystäsi kaiken päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Älä heitä minua pois vanhalla iälläni äläkä hylkää minua, kun voimani loppuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Sillä viholliseni puhuvat minusta. Ne, jotka väijyvät henkeäni, neuvottelevat keskenään:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, '\"Jumala on hänet hylännyt. Ajakaa häntä takaa ja ottakaa kiinni, sillä pelastajaa hänellä ei ole.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Jumala, älä ole minusta kaukana, Jumalani, riennä avukseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Joutukoot häpeään ja hukkukoot ne, jotka vainoavat sieluani. Peittäköön häpeä ja pilkka ne, jotka hankkivat minulle onnettomuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Mutta minä odotan alati, ja yhä minä sinua kiitän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Suuni on julistava vanhurskauttasi, pelastustekojasi kaiken päivää, sillä niiden määrää en tunne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Herran, Herran väkeviä tekoja tuon julki, ylistän vanhurskauttasi, sinun ainoan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Jumala, sinä olet opettanut minua nuoruudestani asti, ja yhä vielä minä julistan ihmeitäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Älä, Jumala, hylkää minua vanhaksi ja harmaaksi tultuani, niin julistan käsivartesi voimaa nousevalle polvelle, väkevyyttäsi kaikille vielä tuleville.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Jumala, vanhurskautesi ulottuu korkeuksiin asti, sinun, joka teet niin suuria. Jumala, kuka on vertaisesi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Sinä, joka olet antanut meidän kokea paljon ahdistusta ja onnettomuutta, sinä virvoitat meidät jälleen henkiin, ja maan syvyyksistä sinä tuot meidät takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Sinä korotit minut ja lohdutit minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Minä myös ylistän harpulla sinua, sinun uskollisuuttasi, Jumalani, soitan lyyralla kiitosta sinulle, sinä Israelin Pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Huuleni riemuitsevat, kun sinulle soitan, ja myös sieluni, jonka sinä olet lunastanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Kieleni julistaa vanhurskauttasi kaiken päivää, sillä häpeään ja pilkkaan ovat joutuneet ne, jotka hankkivat minulle onnettomuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Salomon kirjoittama. Jumala, anna kuninkaan tuomita, niin kuin sinä tuomitset, anna vanhurskautesi kuninkaan pojalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Tuomitkoon hän kansaasi vanhurskaasti ja kurjiasi oikeuden mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Vuoret kantakoot rauhaa kansalle, niin myös kukkulat vanhurskaudella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Auttakoon hän kansan kurjat oikeuteen, pelastakoon köyhien lapset ja musertakoon sortajan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Niin he pelkäävät sinua, niin kauan kuin aurinko ja kuu ovat polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Hän olkoon kuin sade, joka nurmikolle vuotaa, kuin sadekuuro, joka kostuttaa maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'Hänen päivinään vanhurskas kukoistaa, ja rauha on oleva runsas siihen asti, kun kuuta ei enää ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Hallitkoon hän merestä mereen ja virrasta maan ääriin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Hänen edessään erämaan asujat polvistuvat, ja hänen vihollisensa nuolevat tomua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Tarsiin ja saarten kuninkaat tuovat lahjoja, Saban ja Seban kuninkaat tuovat antejaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Häntä kumartavat kaikki kuninkaat, kaikki kansakunnat palvelevat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Sillä hän pelastaa köyhän, joka huutaa apua, kurjan ja sen, jolla ei ole auttajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Hän armahtaa vaivaista ja köyhää ja pelastaa köyhien sielun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Hän lunastaa heidän sielunsa sorrosta ja väkivallasta, ja heidän verensä on hänen silmissään kallis.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Hän eläköön, ja hänelle tuotakoon Saban kultaa. Hänen puolestaan rukoiltakoon alati ja siunattakoon häntä lakkaamatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Maa kasvakoon runsaasti viljaa vuorten huippuja myöten. Sen vilja huojukoon kuin Libanon. Kansaa nouskoon kaupungeista kuin kasveja maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Pysyköön hänen nimensä iankaikkisesti, ja versokoon hänen nimensä, niin kauan kuin aurinko paistaa. Hänessä he itseään siunatkoot, ja kaikki kansakunnat ylistäkööt häntä autuaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Kiitetty olkoon Herra Jumala, Israelin Jumala, ainoa, joka ihmeitä tekee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Kiitetty olkoon hänen kunniansa nimi iankaikkisesti, ja kaikki maa olkoon täynnä hänen kunniaansa. Aamen, aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Daavidin, Iisain pojan, rukoukset päättyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Aasafin psalmi. Totisesti Jumala on hyvä Israelille, niille, joilla on puhdas sydän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Mutta jalkani olivat vähällä kompastua, askeleeni olivat aivan liukastua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Sillä minussa nousi kateus ylvästelijöitä kohtaan, kun näin jumalattomien menestyvän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Sillä he ovat vaivoista vapaat kuolemaansa asti, he ovat voimakkaat ja lihavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Heillä ei ole muiden ihmisten tuskia, eikä heitä vaivata kuin muita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Sen tähden ylpeys on heillä kaulakoristeena ja väkivalta on puku, joka heitä verhoaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Heidän silmänsä pullistuvat ulos heidän lihavuudestaan, heidän sydämensä kuvittelut kulkevat valtoimina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'He pilkkaavat ja puhuvat väkivallan puheita pahuudessaan. He puhuvat kuin korkeuksista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Heidän suunsa tavoittelee taivasta, ja heidän kielensä kulkee pitkin maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Sen tähden heidän kansansa kääntyy heihin ja juo vettä täyttäen sillä itsensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Niinpä he sanovat: \"Kuinka Jumala sen tietäisi, onko tietoa Korkeimmalla?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Katso, nämä ovat jumalattomia. Kuitenkin heillä on ainainen rauha, ja he yhä rikastuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Turhaan minä olen pitänyt sydämeni puhtaana ja pessyt käteni viattomuudessa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'minua vaivataan joka päivä, ja saan kuritusta joka aamu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Jos olisin sanonut: \"Noin minäkin puhun\", katso, niin olisin ollut petollinen koko sinun lastesi sukua kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Minä mietin päästäkseni tästä selvyyteen, mutta se oli minulle hyvin vaikeaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'kunnes minä pääsin sisälle Jumalan pyhiin salaisuuksiin ja käsitin, mikä heidän loppunsa on oleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Totisesti, sinä panet heidät liukkaalle, perikatoon sinä heidät syökset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Kuinka he joutuvatkaan äkisti turmioon! He hukkuvat, heidän loppunsa on kauhistava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Niin kuin unen käy herätessä, niin sinä, Herra, noustessasi hylkäät heidän valhekuvansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Kun sydämeni katkeroitui ja munuaisiani pisti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'silloin minä olin järjetön enkä älynnyt mitään, olin edessäsi kuin nauta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Kuitenkin minä pysyn alati sinun luonasi, sinä pidät minua kiinni oikeasta kädestäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Sinä talutat minua neuvosi mukaan ja korjaat minut viimein kunniaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Ketä muuta minulla olisi taivaassa! Mutta kun sinä olet kanssani, mikään maan päällä ei minua miellytä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Vaikka ruumiini ja sieluni nääntyisi, Jumala on sydämeni kallio ja osani iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Sillä katso, jotka sinusta eroavat, ne hukkuvat. Sinä tuhoat kaikki, jotka haureudessa sinusta luopuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Mutta minun onneni on olla Jumalaa lähellä, minä panen turvani Herraan, Herraan, kertoakseni kaikkia sinun tekojasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Aasafin mietevirsi. Miksi sinä, Jumala, hylkäsit meidät ainiaaksi? Miksi vihasi suitsuaa laitumesi lampaita vastaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Muista seurakuntaasi, jonka otit muinoin omaksesi ja lunastit perintösuvuksesi. Muista Siionin vuorta, jolla sinä asut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Ohjaa askeleesi ikuisille raunioille. Vihollinen on raiskannut kaiken pyhäkössä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Sinun vihollisesi huusivat kokoushuoneessasi, he pystyttivät omat merkkinsä merkeiksi sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Näytti, kuin olisi tiheässä metsässä kirveitä heilutettu korkealle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'He löivät kaikki sen veistokset rikki kirveillä ja nuijilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'He pistivät pyhäkkösi tuleen, he häpäisivät ja panivat maan tasalle nimesi asumuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'He sanoivat sydämessään: \"Me hävitämme heidät kaikki tyynni.\" He polttivat kaikki jumalanpalvelushuoneet maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Merkkejämme emme näe, ei ole enää profeettaa, eikä ole joukossamme ketään, joka tietäisi, kuinka kauan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Kuinka kauan, Jumala, vihollinen saa herjata, kuinka kauan vihamies saa pilkata nimeäsi lakkaamatta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Miksi pidätät kätesi, oikean kätesi? Vedä se povestasi ja hävitä heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Jumala on kuninkaani muinaisista ajoista, hän toimittaa pelastuksen maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Sinä halkaisit voimallasi meren, sinä musersit lohikäärmeitten päät vetten päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Sinä ruhjoit rikki leviatanin päät, sinä annoit hänet ruuaksi erämaan eläinten laumalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Sinä puhkaisit lähteen ja puron kuohumaan ja kuivasit väkevät virrat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Sinun on päivä, sinun on yö, sinä valmistit valon ja auringon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Sinä määräsit kaikki maan rajat. Sinä asetit kesän ja talven.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Muista tämä: vihollinen herjaa Herraa, tyhmä kansa pilkkaa nimeäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Älä anna pedolle alttiiksi metsäkyyhkysesi sielua, älä iäksi unohda kurjiesi elämää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Katso liittoasi. Sillä maan pimennot ovat täynnä väkivallan pesiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Älä salli sorretun kääntyä häväistynä takaisin. Kurja ja köyhä saakoot ylistää nimeäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Nouse, Jumala, aja asiasi. Muista, miten houkat herjaavat sinua kaiken aikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Älä unohda vihollistesi huutoa, älä vastustajiesi melua, joka kohoaa lakkaamatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Veisuunjohtajalle. Veisataan kuin \"Älä turmele\". Psalmi. Aasafin laulu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Me kiitämme sinua, Jumala, me kiitämme sinua; lähellä on nimesi, ihmeitäsi kerrotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, '\"Vaikka minä valitsenkin ajan, minä tuomitsen oikein.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Vaikka maa kaikkine asukkaineen menehtyy pelkoon, minä pidän lujina sen perustukset.\" Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, '\"Ylvästelijöille minä sanon: älkää ylvästelkö, ja jumalattomille: älkää sarvea nostako.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Älkää nostako sarveanne korkealle, älkää puhuko niskoitellen, julkeasti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Ei tule apua idästä, ei lännestä, ei vuorisesta erämaasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'vaan Jumala on se, joka tuomitsee: yhden hän alentaa, toisen ylentää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Sillä Herran kädessä on malja, joka vaahtoaa täynnä höystettyä viiniä, ja siitä hän kaataa. Kaikkien maan jumalattomien täytyy se juoda, imeä tyhjiin pohjia myöten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Mutta minä julistan iäti ja veisaan kiitosta Jaakobin Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 11, 'Mutta kaikki jumalattomien sarvet minä katkaisen. Korkealle kohoavat vanhurskaan sarvet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Veisuunjohtajalle. Kielisoittimilla. Psalmi, Aasafin laulu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Jumala on tunnettu Juudassa, hänen nimensä on suuri Israelissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Saalemissa on hänen majansa ja hänen asumuksensa Siionissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Siellä hän mursi jousen salamat, kilven, miekan ja sodan. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Kirkkaudessa, valtasuuruudessa sinä tulit valona voittosaaliin vuorilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Urhoollisilta ryöstettiin aseet. He uupuivat uneen. Kaikkien sankarien kädet herposivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Sinun nuhtelustasi, Jaakobin Jumala, vaipuivat raskaaseen uneen vaunut ja hevoset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Sinä olet pelottava. Kuka kestää edessäsi, kun sinä vihastut?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Taivaasta sinä annoit tuomiosi kuulua. Maa pelästyi ja vaikeni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'kun Jumala nousi tuomiolle pelastaakseen kaikki maan nöyrät. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Sillä ihmisten viha tulee sinulle ylistykseksi: sinä vyöttäydyt viimeiseen vihaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Tehkää lupauksia ja täyttäkää ne Herralle, Jumalallenne. Kaikki hänen ympärillään asuvat tuokoot lahjoja hänelle, jolle kuuluu pelko,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 13, 'joka nöyryyttää ruhtinaitten rohkeuden ja joka on pelottava maan kuninkaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Veisuunjohtajalle. Jedutunin tapaan. Aasafin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Minä korotan ääneni Jumalan puoleen ja huudan. Minä korotan ääneni Jumalan puoleen, ja hän kuulee minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Ahdistukseni aikana minä etsin Herraa. Käteni on yöllä ojennettuna eikä väsy. Sieluni ei huoli lohdutusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Muistan Jumalaa ja huokaan. Tutkistelen, ja henkeni nääntyy. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Sinä pidät silmäni valveilla. Olen niin levoton, etten voi puhua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Ajattelen muinaisia päiviä, entisaikojen menneitä vuosia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Muistan yöllä lyyraani. Mietiskelen sydämessäni, ja henkeni tutkii:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Hylkääkö Herra ikuisesti eikä enää osoita mielisuosiota?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Onko hänen armonsa lakannut ainiaaksi? Onko hänen sanansa päättynyt eikä jatku polvesta polveen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Onko Jumala unohtanut olla armollinen? Onko hän vihassaan lukinnut laupeutensa? Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Minä sanoin: Olen haavoilla. Korkeimman oikea käsi sen muuttaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Muistelen Herran tekoja. Muistelen sinun entisiä ihmetöitäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Minä tutkin kaikkia töitäsi ja mietin suuria tekojasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Jumala, sinun tiesi on pyhä. Kuka on jumala, suuri kuin sinä, Jumala?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Sinä olet Jumala, joka teet ihmeitä. Sinä olet ilmoittanut voimasi kansojen seassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Käsivarrellasi sinä lunastit kansasi, Jaakobin ja Joosefin lapset. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Vedet näkivät sinut, Jumala. Vedet näkivät sinut ja vapisivat, ja syvyydet värisivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Pilvet purkivat vettä. Pilvet antoivat jylinänsä, nuolesi lensivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Jyrinäsi ääni vyöryi, salamat valaisivat maanpiirin ja maa vapisi ja järkkyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Meren halki kävi tiesi, polkusi läpi suurten vetten, eivätkä jälkesi tuntuneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 21, 'Sinä kuljetit kansaasi kuin lammaslaumaa Mooseksen ja Aaronin kädellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Aasafin mietevirsi. Kuuntele, kansani, opetustani. Kallistakaa korvanne suuni sanoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Minä avaan suuni mietelmiin, tuon ilmi entisaikojen arvoituksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Mitä olemme kuulleet, minkä olemme saaneet tietää ja mitä isämme ovat meille kertoneet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'sitä emme salaa heidän lapsiltaan, vaan kerromme tulevalle polvelle Herran ylistettävistä teoista, hänen voimastaan ja ihmeistään, jotka hän on tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Hän asetti todistuksen Jaakobiin, sääti Israeliin lain ja käski meidän isiemme julistaa ne lapsilleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'että jälkipolvi saisi ne tietää, saisivat tietää vastedes syntyvät lapset, ja nekin nousisivat ja kertoisivat niistä lapsilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Niin nämä panisivat uskalluksensa Jumalaan eivätkä unohtaisi Jumalan tekoja, vaan ottaisivat hänen käskyistään vaarin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'Silloin heistä ei tulisi, kuten heidän isistään, kapinoiva ja niskoitteleva polvi, sukupolvi, jonka sydän ei pysynyt lujana ja jonka henki ei pysynyt uskollisena Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Efraimin lapset, aseistetut jousimiehet, kääntyivät pakoon taistelun päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'He eivät pitäneet Jumalan liittoa eivätkä tahtoneet vaeltaa hänen lakinsa mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'vaan he unohtivat hänen suuret tekonsa ja hänen ihmeensä, jotka hän heille näytti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Heidän isiensä nähden hän teki ihmeitä Egyptin maassa, Sooanin kedolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Hän halkaisi meren ja vei heidät sen läpi. Hän seisautti vedet röykkiöksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Hän johdatti heitä päivän aikaan pilvellä ja tulen valolla kaiket yöt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Hän halkoi kalliot erämaassa ja juotti heitä runsaasti kuin syvistä vesistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Hän juoksutti puroja kalliosta ja vuodatti vettä virtanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'He tekivät kuitenkin yhä syntiä häntä vastaan ja olivat uppiniskaisia Korkeimmalle erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'He kiusasivat Jumalaa sydämessään vaatien ruokaa himonsa tyydyttämiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'He puhuivat Jumalaa vastaan sanoen: \"Voikohan Jumala kattaa pöydän erämaassa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Katso, hän iski kyllä kallioon, ja vedet vuotivat ja purot tulvivat; mutta voiko hän antaa myös leipää tai hankkia lihaa kansalleen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Sen tähden Herra, kun hän sen kuuli, julmistui. Silloin Jaakobissa syttyi tuli, ja Israelia vastaan nousi viha,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'koska he eivät uskoneet Jumalaan eivätkä luottaneet hänen apuunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Hän käski pilviä korkeudessa ja avasi taivaan ovet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'Hän antoi sataa heille ruuaksi mannaa. Hän antoi heille taivaan viljaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Ihmiset söivät enkelien leipää. Hän lähetti heille evästä yllin kyllin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Hän nosti taivaalle itätuulen ja ajoi etelätuulen esiin voimallaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Hän antoi sataa heille lihaa kuin tomua, siivekkäitä lintuja kuin meren hiekkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Hän pudotti ne leiriin, kaikkialle heidän asumustensa ympärille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Niin he söivät ja tulivat kylläisiksi. Mitä he olivat himoinneet, sitä hän salli heidän saada.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'He eivät olleet vielä himoaan tyydyttäneet, ja ruoka oli vielä heidän suussaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'kun jo heitä vastaan nousi Jumalan viha: hän tappoi heidän voimakkaimpansa ja kaatoi maahan Israelin nuoret miehet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Mutta sittenkin he yhä vielä tekivät syntiä eivätkä uskoneet hänen ihmeitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Sen tähden hän lopetti heidän päivänsä kuin tuulahduksen ja antoi heidän vuosiensa päättyä äkilliseen perikatoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Kun hän surmasi heitä, he kysyivät häntä, kääntyivät ja etsivät Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'He muistivat, että Jumala oli heidän kallionsa ja että Jumala, Korkein, oli heidän lunastajansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Mutta he pettivät häntä suullaan ja valehtelivat hänelle kielellään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'sillä heidän sydämensä ei ollut luja häntä kohtaan, eivätkä he olleet uskollisia hänen liitossaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Mutta hän on laupias, antaa anteeksi rikokset eikä tahdo hukuttaa. Sen tähden hän usein kääntyi vihastaan eikä antanut kaiken kiivautensa nousta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Sillä hän muisti, että he ovat liha, tuulahdus, joka menee eikä enää palaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Kuinka usein he niskoittelivat häntä vastaan korvessa ja murehduttivat hänen mielensä erämaassa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Niin he yhä edelleen kiusasivat Jumalaa ja vihoittivat Israelin Pyhän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'He eivät muistaneet hänen kättään, eivät sitä päivää, jona hän päästi heidät ahdistajasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'jona hän teki tunnustekonsa Egyptissä ja ihmeensä Sooanin kedolla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'muutti heidän virtansa vereksi, niin etteivät he voineet juoda vesiojistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Hän lähetti heidän keskelleen paarmoja, jotka purivat heitä, ja sammakoita, jotka vaivasivat heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Hän antoi heidän satonsa tuhosirkoille ja heidän vaivannäkönsä heinäsirkoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Hän hävitti rakeilla heidän viiniköynnöksensä ja huurteella heidän metsäviikunapuunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Hän antoi heidän karjansa alttiiksi rakeille ja heidän laumansa salamoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Hän lähetti heitä vastaan vihansa hehkun, kiivastuksen, vihastuksen ja ahdistuksen, parven pahoja enkeleitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Hän raivasi tien vihalleen eikä säästänyt kuolemasta heidän sielujaan, vaan antoi heidän henkensä ruton valtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'Hän surmasi kaikki esikoiset Egyptistä, miehuuden ensimmäiset Haamin majoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Mutta kansansa hän pani liikkeelle kuin lampaat ja johdatti heitä erämaassa kuin laumaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Hän johti heitä turvallisesti. Heidän ei tarvinnut pelätä, mutta heidän vihollisensa peitti meri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Hän vei heidät pyhälle alueelleen, vuorelle, jonka hänen oikea kätensä oli hankkinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Hän karkotti pakanat pois heidän tieltään, jakoi ne heille arvalla perintöosaksi ja antoi Israelin sukukuntien asua niiden telttamajoissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Mutta niskoittelullaan he kiusasivat Jumalaa, Korkeinta, eivätkä ottaneet vaarin hänen todistuksistaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'vaan luopuivat pois, olivat uskottomia isiensä lailla ja kävivät kelvottomiksi kuin veltto jousi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'He vihoittivat hänet uhrikukkuloillaan ja herättivät hänen kiivautensa epäjumaliensa kuvilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Jumala kuuli sen ja julmistui ja hylkäsi Israelin suuressa määrin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Hän hylkäsi asumuksensa Siilossa, telttamajan, jonka hän oli pystyttänyt ihmisten keskelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Hän salli väkevyytensä joutua vankeuteen ja kunniansa vihollisten käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Hän antoi kansansa alttiiksi miekalle ja syttyi vihaan perintöosalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Heidän nuorukaisensa kulutti tuli, ja neitsyensä jäivät häälauluja vaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Heidän pappinsa kaatuivat miekkaan, eivätkä heidän leskensä voineet itkeä itkuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Silloin Herra heräsi kuin nukkuja, kuin viinin voittama sankari.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'Hän löi vihollisensa pakoon ja tuotti heille ikuisen häpeän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Hän hylkäsi myös Joosefin telttamajan eikä valinnut Efraimin sukukuntaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'vaan valitsi Juudan sukukunnan, Siionin vuoren, jota hän rakastaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Sitten hän rakensi pyhäkkönsä korkeuksien tasalle, rakensi sen kuin maan, jonka hän on perustanut ikiajoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Hän valitsi Daavidin, palvelijansa, ja otti hänet lammastarhoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'Hän toi hänet imettävien lammasten jäljestä kaitsemaan kansaansa, Jaakobia, ja Israelia, perintöosaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Daavid kaitsi heitä eheällä sydämellä ja johti heitä taitavalla kädellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Aasafin psalmi. Jumala, pakanat ovat tunkeutuneet perintöosaasi. He ovat saastuttaneet pyhän temppelisi ja ovat tehneet Jerusalemista kiviraunion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'He antoivat palvelijoittesi ruumiit ruuaksi taivaan linnuille, maan pedoille pyhiesi lihan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'He vuodattivat heidän vertaan kuin vettä ympäri Jerusalemia, eikä heitä kukaan haudannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Me olemme joutuneet naapuriemme häväistäviksi, niiden pilkattaviksi ja ivattaviksi, jotka asuvat ympärillämme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Kuinka kauan sinä, Herra, olet yhä vihoissasi, kuinka kauan sinun kiivautesi palaa tulena?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Vuodata vihasi pakanoiden päälle, jotka eivät sinua tunne, ja valtakuntien päälle, jotka eivät huuda nimeäsi avukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Sillä he ovat syöneet Jaakobin ja tehneet hänen asuinsijansa autioksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Älä lue meille syyksi isiemme rikoksia, anna armosi pian kohdata meitä, sillä me olemme sangen viheliäisiksi tulleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Auta meitä sinä, pelastuksemme Jumala, nimesi kunnian tähden, pelasta meidät ja anna syntimme anteeksi nimesi tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Miksi pakanat saisivat sanoa: \"Missä on heidän Jumalansa?\" Tulkoon tunnetuksi pakanoiden keskuudessa silmiemme nähden palvelijoittesi vuodatetun veren kosto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Tulkoon vankien huokaus kasvojesi eteen. Pidä kuoleman lapset elossa suuren käsivartesi voimalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Maksa naapureillemme, heidän helmaansa, seitsenkertaisesti se herjaus, jolla he ovat herjanneet sinua, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Mutta me, kansasi, laitumesi lampaat, kiitämme sinua iankaikkisesti, julistamme kiitostasi polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Veisuunjohtajalle. Veisataan kuin \"Liljat\". Aasafin todistus, psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Kuuntele, Israelin paimen. Sinä, joka johdat Joosefia kuin lammaslaumaa, sinä, jonka valtaistuinta kerubit kannattavat, ilmesty kirkkaudessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Efraimin, Benjaminin ja Manassen edessä herätä voimasi, tule avuksemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Jumala, saata meidät entisellemme, valaise kasvosi, niin tulemme autetuiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Herra, Jumala Sebaot, kuinka kauan sinä annat vihasi suitsuta, kun kansasi rukoilee?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Sinä olet syöttänyt heille kyynelten leipää, olet juottanut heille maljoittain kyyneleitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Sinä olet pannut meidät riidaksi naapureillemme. Vihollisemme pilkkaavat meitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Jumala Sebaot, saata meidät entisellemme, valaise kasvosi, niin me tulemme autetuiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Sinä siirsit viinipuun Egyptistä, sinä karkotit pakanat ja istutit sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Sinä raivasit sille sijan, ja se todella juurtui ja täytti maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Se peitti vuoret varjollaan ja oksillaan Jumalan setrit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Se levitti köynnöksensä mereen asti ja vesansa Eufrat-virtaan saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Miksi sinä särjit aidan sen ympäriltä, niin että kaikki tienkulkijat sitä repivät?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Villisika sitä kalvaa, ja kedon eläimet sitä syövät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Jumala Sebaot, käänny takaisin, katso alas taivaasta ja näe. Ota hoitaaksesi tämä viinipuu');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'ja suojaa se, minkä oikea kätesi istutti, ja Vesa, jonka teit vahvaksi itseäsi varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Se on tulen polttama, se on karsittu. He hukkuvat kasvojesi uhkauksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Olkoon kätesi oikean kätesi miehen suojana, Ihmisen Pojan, jonka teit vahvaksi itseäsi varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Silloin me emme sinusta luovu. Suo meidän elää, niin huudamme avuksemme nimeäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 20, 'Herra, Jumala Sebaot, saata meidät entisellemme, valaise kasvosi, niin tulemme autetuiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Veisuunjohtajalle. Gatilaisten tapaan. Aasafin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Nostakaa ilohuuto Jumalalle, joka on väkevyytemme. Nostakaa riemuhuuto Jaakobin Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Virittäkää kiitosvirsi, lyökää tamburiineja, soittakaa suloisesti lyyroja ja harppuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Puhaltakaa torveen uudenkuun aikana ja täyden kuun aikana juhlapäiviemme kunniaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Sillä tämä on käsky Israelille, Jaakobin Jumalan säädös.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Hän asetti sen todistukseksi Joosefille käydessään Egyptin maata vastaan. Kuulen puhetta, jota en tunne:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, '\"Nostin taakan hänen hartioiltaan, hänen kätensä pääsivät kantokorin kuormasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Hädässäsi sinä huusit, ja minä vapautin sinut: Ukkospilven peitosta minä vastasin sinulle. Minä koettelin sinua Meriban veden luona.\" Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, '\"Kuule, kansani, minä varoitan sinua. Israel, kunpa minua kuulisit!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Älköön sinulla olko muukalaista jumalaa, äläkä kumarra vierasta jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Minä olen Herra, Jumalasi, joka toin sinut Egyptin maasta. Avaa suusi, niin minä sen täytän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Mutta kansani ei kuullut ääntäni, eikä Israel noudattanut mieltäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'Minä lähetin heidät pois sydämensä paatumuksessa. He vaelsivat omien neuvojensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Oi, jospa kansani minua kuulisi ja Israel vaeltaisi minun teilläni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'niin minä lyhyessä ajassa nöyryyttäisin heidän vihollisensa ja kääntäisin käteni heidän vihamiehiään vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Ne, jotka Herraa vihaavat, nöyrtyisivät hänen edessään, mutta heidän aikansa kestäisi iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 17, 'Mutta kansaansa hän ruokkisi parhaalla vehnällä. Minä ravitsisin sinua hunajalla kalliosta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Aasafin psalmi. Jumala seisoo jumalien kokouksessa, hän on tuomari jumalien keskellä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, '\"Kuinka kauan te tuomitsette väärin ja pidätte jumalattomien puolta?\" Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, '\"Auttakaa oikeuteensa alhainen ja orpo, antakaa kurjalle ja puutteessa olevalle oikeus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Vapauttakaa alhainen ja köyhä. Pelastakaa hänet jumalattomien käsistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Heillä ei ole älyä eikä ymmärrystä. He vaeltavat pimeydessä, niin että kaikki maan perustukset horjuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Minä sanon: Te olette jumalia ja kaikki tyynni Korkeimman poikia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Kuitenkin te kuolette, niin kuin ihmiset kuolevat, ja kaadutte kuin kuka ruhtinas tahansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Nouse, Jumala, tuomitse maa, sillä sinä perit kaikki pakanakansat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Laulu. Aasafin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Jumala, älä ole niin ääneti äläkä ole vaiti. Älä, Jumala, ole niin hiljaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Sillä, katso, vihollisesi pauhaavat, ja vihaajasi nostavat päätään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Heillä on kavalat hankkeet kansaasi vastaan, ja he pitävät neuvoa niitä vastaan, jotka olet ottanut suojaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'He sanovat: \"Tulkaa, hävittäkäämme heidät olemasta kansa, niin ettei Israelin nimeä enää muisteta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Sillä he neuvottelevat keskenään yksimielisesti. He tekevät liiton sinua vastaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Edomin teltat ja ismaelilaiset, Mooab ja hagrilaiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'Gebal, Ammon ja Amalek, Filistea sekä Tyyron asukkaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Myös Assur on liittynyt heihin. Nämä ovat käsivartena Lootin lapsilla. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Tee heille, kuten teit Midianille, niin kuin Siiseralle, niin kuin Jaabinille Kiison-joen rannalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Heidät tuhottiin Eendorissa. He joutuivat lannaksi maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Anna heidän ylhäisilleen käydä, niin kuin kävi Oorebille ja Seebille, ja kaikille heidän ruhtinailleen, niin kuin Seballe ja Salmunnalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'koska he sanovat: \"Anastakaamme itsellemme Jumalan asunnot.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Jumalani, tee heidät lentäviksi lehdiksi, kuiviksi korsiksi tuulen viedä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Niin kuin kulovalkea polttaa metsää, niin kuin liekit kärventävät vuoria,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'niin aja sinä heitä rajuilmallasi ja kauhistuta heitä tuulispäälläsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Täytä heidän kasvonsa häpeällä, että he etsisivät sinun nimeäsi, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Joutukoot he häpeään ja kauhistukoot ikuisesti, tulkoot häpeään ja hukkukoot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 19, 'Tulkoot tuntemaan, että sinun ainoan nimi on Herra, että sinä olet Korkein kaikessa maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Veisuunjohtajalle. Gatilaisten tapaan. Koorahilaisten psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Kuinka ihanat ovat asuinsijasi, Herra Sebaot!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Sieluni ikävöi ja haluaa Herran esikartanoihin. Sydämeni ja ruumiini huutaa riemuiten elävän Jumalan puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Löysihän lintunen majan ja pääskynen pesän, johon se poikasensa laskee, sinun alttarisi, Herra Sebaot, minun kuninkaani ja minun Jumalani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Autuaat ne, jotka huoneessasi asuvat! He kiittävät sinua alati. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Autuaat ne ihmiset, joilla on voimansa sinussa, joiden sydämissä ovat tiesi!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Kun he käyvät Kyynellaakson kautta, he tekevät sinne lähteitä, ja opettaja peittää sen siunauksilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'He käyvät voimasta voimaan. He astuvat Jumalan eteen Siionissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Herra, Jumala Sebaot, kuule rukoukseni, ota se korviisi, Jaakobin Jumala. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Jumala, sinä, meidän kilpemme, käännä katseesi, katso voideltusi kasvoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Sillä yksi päivä esikartanoissasi on parempi kuin tuhat muualla. Mieluummin olen vartijana Jumalani huoneen kynnyksellä, kuin asun jumalattomien telttamajoissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Sillä Herra Jumala on aurinko ja kilpi; Herra antaa armon ja kunnian. Hän ei kiellä hyvää niiltä, jotka vaeltavat nuhteettomasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 13, 'Herra Sebaot, autuas se ihminen, joka sinuun turvaa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Veisuunjohtajalle; koorahilaisten psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Herra, ennen sinä osoitit suosiota maallesi ja käänsit Jaakobin kohtalon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Sinä annoit anteeksi kansasi pahat teot ja peitit kaikki heidän syntinsä. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Sinä panit pois kaiken kiivastuksesi ja lauhduit vihasi hehkusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Käänny taas puoleemme, sinä pelastuksemme Jumala, älä ole enää meille vihainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Oletko ainiaaksi vihastunut meihin, pidätkö vihaa polvesta polveen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Etkö virvoita meitä jälleen eloon, että kansasi iloitsisi sinussa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Herra, suo meidän nähdä armosi, anna apusi meille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Tahdon kuulla, mitä Jumala, Herra, puhuu: hän puhuu rauhaa kansalleen, pyhilleen. Älkööt he kääntykö jälleen tyhmyyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Totisesti, hänen autuutensa on lähellä niitä, jotka häntä pelkäävät, ja niin kunnia asuu maassamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Armo ja totuus tapaavat toisensa täällä, vanhurskaus ja rauha antavat suuta toisilleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'uskollisuus versoo maasta, ja vanhurskaus katsoo taivaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Herra antaa meille kaikkea hyvää, ja meidän maamme antaa satonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 14, 'Vanhurskaus käy hänen edellään ja seuraa hänen askeltensa jälkiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Daavidin rukous. Kallista, Herra, korvasi puoleeni ja vastaa minulle, sillä minä olen kurja ja köyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Varjele sieluni, sillä olen pyhäsi. Sinä, Jumalani, pelasta palvelijasi, joka sinuun turvaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Ole minulle armollinen, Herra, sillä sinua minä huudan kaiken päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Ilahduta palvelijasi sielu, sillä sinun puoleesi, Herra, minä ylennän sieluni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Sillä sinä, Herra, olet hyvä ja anteeksiantavainen, suuri armossa kaikille, jotka sinua avukseen huutavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Ota, Herra, korviisi rukoukseni, tarkkaa anomiseni ääntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Hätäni päivänä minä sinua avukseni huudan, sillä sinä vastaat minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Ei ole vertaistasi, Herra, jumalien joukossa, eikä ole vertaa sinun töillesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Kaikki kansat, jotka sinä olet tehnyt, tulevat ja kumartuvat edessäsi, Herra, ja kunnioittavat nimeäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Sillä sinä olet suuri ja teet ihmeitä, sinä ainoa olet Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Neuvo minulle tiesi, Herra, että minä vaeltaisin totuudessasi. Kiinnitä sydämeni siihen yhteen, että minä nimeäsi pelkäisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Kaikesta sydämestäni minä kiitän sinua, Herra, Jumalani, ja kunnioitan nimeäsi iankaikkisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'sillä sinun armosi on suuri minua kohtaan, sinä olet pelastanut sieluni helvetin syvyydestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Jumala, julkeat ovat nousseet minua vastaan, väkivaltaisten joukko etsii henkeäni. He eivät pidä sinua silmiensä edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Mutta sinä, Herra, olet laupias ja armahtavainen Jumala, pitkämielinen, suuri armossa ja totuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Käänny puoleeni, ole minulle armollinen, anna voimasi palvelijallesi, auta palvelijattaresi poikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Tee merkki minulle, minun hyväkseni. Häpeäkseen vihamieheni nähkööt, että sinä, Herra, autat ja lohdutat minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Koorahilaisten psalmi, laulu. Hän on perustanut sen pyhille vuorille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Herra rakastaa enemmän Siionin portteja, kuin Jaakobin kaikkia muita asuinsijoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'On kunniakasta, mitä sinusta sanotaan, sinä Jumalan kaupunki: – Sela. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, '\"Minä mainitsen Rahabin ja Baabelin tuntevan minut. Katso, Filisteasta, Tyyrosta ja Kuusista minä mainitsen: Sekin on syntynyt siellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Mutta Siionista sanotaan: \"Joka ainoa on syntynyt siellä.\" Korkein on sen perustanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Herra luettelee kirjoittaessaan kirjaan kansat: \"Tämäkin on syntynyt siellä.\" Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Veisaajat ja karkeloivat: \"Kaikki minun lähteeni ovat sinussa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Koorahilaisten laulu, psalmi. Veisuunjohtajalle. Veisataan kuten \"Sairaus\", esrahilaisen Heemanin mietevirsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Herra, pelastukseni Jumala, päivin ja öin minä huudan edessäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Salli rukoukseni tulla kasvojesi eteen, kallista korvasi huutoni puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Sillä sieluni on saanut kärsimyksistä tarpeeksi, ja elämäni on lähellä hautaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Minut luetaan hautaan menevien joukkoon. Olen kuin mies, jolta voima on poissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Minut on jätetty kuolleiden joukkoon. Olen kuin kaatuneet, jotka makaavat haudassa ja joita sinä et enää muista ja jotka ovat kädestäsi erotetut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Sinä olet laskenut minut syvimpään hautaan, pimeyteen, syviin kuiluihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Vihasi painaa minua, ja kaikki kuohusi sinä vyörytät ylitseni. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Sinä olet karkottanut tuttavani minusta kauas, olet tehnyt minut heille inhoksi. Minut on suljettu sisään enkä pääse ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Kasvoni ovat kuihtuneet kurjuudesta. Joka päivä minä huudan sinua, Herra, ja ojennan käteni sinun puoleesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Teetkö sinä ihmeitä kuolleille, tai nousevatko kuolleiden henget sinua kiittämään? Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Kerrotaanko haudassa armostasi, kadotuksessa uskollisuudestasi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Tunnetaanko ihmeesi pimeydessä ja vanhurskautesi unohduksen maassa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Mutta minä huudan avukseni sinua, Herra, ja rukoukseni tulee varhain eteesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Miksi, Herra, hylkäät sieluni, miksi peität kasvosi minulta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Minä olen ollut kurja ja lähellä kuolemaa nuoruudestani alkaen. Minä kärsin kauhujasi ja olen neuvoton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Vihasi vyöryy ylitseni, kauhusi hukuttavat minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Ne saartavat minua kaiken päivää kuin vedet. Ne kaikki yhdessä piirittävät minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 19, 'Ystävät ja toverit sinä olet karkottanut minusta kauas. Pimeys on ainoa tuttavani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Esrahilaisen Eetanin mietevirsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Minä laulan lakkaamatta Herran armoteoista, julistan suullani uskollisuuttasi polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'Minä sanon: ikiajoiksi on armo rakennettu, sinä olet perustanut uskollisuutesi taivaisiin. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, '\"Minä olen tehnyt liiton valittuni kanssa, olen palvelijalleni Daavidille vannonut:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, '\'Minä vahvistan jälkeläisesi ikiajoiksi ja rakennan sinulle valtaistuimen polvesta polveen.\'\" Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Silloin taivaat ylistävät ihmeitäsi, Herra, ja pyhien seurakunta uskollisuuttasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Sillä kuka pilvissä on Herran vertainen, kuka Jumalan lasten joukossa on kuin Herra?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Hän on Jumala, hyvin pelottava pyhien kokouksessa, pelottavampi kaikkia, jotka hänen ympärillään ovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Herra, Jumala Sebaot, kuka on vertaisesi voimassa, Herra? Uskollisuutesi ympäröi sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Sinä hallitset meren raivon. Kun sen aallot kohoavat, sinä ne hiljennät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Sinä ruhjoit Rahabin kuin sodassa kaatuneen. Väkevällä käsivarrellasi sinä ajoit vihollisesi hajalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Sinun ovat taivaat, sinun on myös maa. Maanpiirin ja kaiken, mitä siinä on, sinä olet perustanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Sinä loit pohjoisen ja etelän. Sinun nimestäsi riemuitsevat Taabor ja Hermon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Sinulla on käsivarsi voimaa täynnä. Väkevä on kätesi ja korotettu oikea kätesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Vanhurskaus ja oikeus on valtaistuimesi perustus, armo ja totuus käy kasvojesi edellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Autuas se kansa, joka tuntee juhlariemun, ne, jotka vaeltavat kasvojesi valkeudessa, Herra!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'He riemuitsevat nimestäsi kaikkina päivinään, ja vanhurskautesi voimasta heidät korotetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Sillä sinä olet heidän väkevyytensä, heidän kaunistuksensa, ja sinä korotat armossasi sarvemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Sillä kilpemme on Herran huomassa, kuninkaamme on Israelin Pyhän huomassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Silloin sinä puhuit näyssä pyhillesi ja sanoit: \"Minä olen pannut avun sankarin käteen, olen kansan keskeltä korottanut valittuni:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'minä olen löytänyt Daavidin, palvelijani, olen voidellut hänet pyhällä öljylläni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Käteni on lujasti tukeva häntä, käsivarteni on vahvistava häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Vihollinen ei yllätä häntä, eikä vääryyden mies häntä sorra,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'vaan minä hävitän hänen ahdistajansa hänen edestään ja lyön hänen vihamiehensä maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Uskollisuuteni ja armoni on hänen kanssaan, ja minun nimessäni kohoaa hänen sarvensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Minä asetan hänen kätensä vallitsemaan merta ja virtoja, hänen oikean kätensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Hän kutsuu minua: \'Sinä olet minun Isäni, sinä Jumalani ja pelastukseni kallio.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Minä asetan hänet esikoiseksi, maan kuninkaista korkeimmaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Minä säilytän armoni hänelle iankaikkisesti, ja liittoni hänen kanssaan on luja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Minä annan hänen siemenensä säilyä iäti ja hänen valtaistuimensa niin kauan, kuin taivaat pysyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Jos hänen poikansa hylkäävät lakini eivätkä vaella oikeuksieni mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'jos he rikkovat säädökseni eivätkä noudata käskyjäni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'minä rankaisen vitsalla heidän rikoksensa ja vitsauksilla heidän pahat tekonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Mutta armoani en minä ota häneltä pois enkä ole vilpillinen uskollisuudessani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Minä en riko liittoani, enkä muuta sitä, mikä on lähtenyt huuliltani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Minä olen kerran vannonut pyhyyteni kautta, ja totisesti, minä en Daavidille valehtele:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, '\'Hänen siemenensä pysyy iankaikkisesti, ja hänen valtaistuimensa on edessäni kuin aurinko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Se pysyy lujana ikuisesti kuin kuu, ja todistaja pilvissä on uskollinen.\'\" Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Kuitenkin sinä hylkäsit Voideltusi ja pidit hänet halpana ja olit vihastunut häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Sinä olet purkanut palvelijasi liiton, olet häväissyt hänen kruununsa, olet heittänyt sen maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Sinä olet särkenyt kaikki hänen muurinsa, olet pannut raunioiksi hänen linnoituksensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Kaikki tienkulkijat ovat häntä ryöstäneet. Hän on joutunut naapuriensa häväistäväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Sinä olet korottanut hänen vihollistensa oikean käden, olet tuottanut ilon kaikille hänen vihamiehilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Sinä olet kääntänyt takaisin hänen miekkansa terän etkä ole sodassa pitänyt häntä pystyssä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Sinä olet tehnyt hänen loistostaan lopun ja olet syössyt maahan hänen valtaistuimensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Sinä olet lyhentänyt hänen nuoruutensa päivät, olet hänet häpeällä peittänyt. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Kuinka kauan sinä, Herra, yhä kätkeydyt? Kuinka kauan vihasi palaa tulena?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Muista, kuinka lyhyt on elämäni, kuinka katoavaisiksi sinä olet luonut kaikki ihmislapset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Kuka on se mies, joka jää eloon eikä näe kuolemaa, joka pelastaa sielunsa helvetin kädestä? Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Herra, missä ovat entiset armotekosi, jotka vannoit uskollisuudessasi Daavidille?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Ajattele, Herra, palvelijoittesi häpäisyä ja mitä minun kaikilta noilta monilta kansoilta täytyy kestää povessani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'kun, Herra, sinun vihollisesi herjaavat, herjaavat sinun Voideltusi askeleita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 53, 'Kiitetty olkoon Herra iankaikkisesti. Aamen, aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Mooseksen, Jumalan miehen, rukous. Herra, sinä olet turvamme polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Ennen kuin vuoret syntyivät ja sinä loit maan ja maanpiirin, iankaikkisesta iankaikkiseen olet sinä, Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Sinä palautat ihmiset takaisin tomuun ja sanot: \"Palatkaa jälleen, te ihmisten lapset.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Sillä tuhat vuotta on silmissäsi kuin eilinen päivä, joka meni ohi, ja kuin öinen vartiohetki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Sinä huuhdot heidät pois. He ovat kuin uni, ovat kuin ruoho, joka aamulla kukoistaa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'aamulla se kasvaa ja kukoistaa, mutta illalla se leikataan ja se kuivuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Sillä meistä tulee loppu vihasi voimasta, ja kiivautesi voimasta häviämme pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Pahat tekomme sinä asetat eteesi, salaiset syntimme kasvojesi valkeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Sillä kaikki päivämme kuluvat vihasi alla, vuotemme päättyvät meiltä kuin huokaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Elinpäivämme ovat seitsemänkymmentä vuotta tai kahdeksankymmentä vuotta, jos pysymme voimissamme, ja kaikki, mitä niistä ylpeillään, on vaivaa ja turhuutta, sillä ne kiitävät ohi, kuin me lentäisimme pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Kuka tuntee vihasi ankaruuden, kiivautesi, niin että hän sinua pelkäisi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Opeta meitä laskemaan päivämme oikein, että saisimme viisaan sydämen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Herra, palaa jälleen. Voi, kuinka kauan? Armahda palvelijoitasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Ravitse aamulla meitä armollasi. Suo meille iloa ja riemua kaikkina päivinämme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Suo meidän iloita yhtä monta päivää, kuin olet nöyryyttänyt meitä, yhtä monta vuotta, kuin olemme kokeneet kovaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Saakoot palvelijasi nähdä tekosi ja heidän lapsensa kunniasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Tulkoon osaksemme Herran, Jumalamme, laupeus. Suo menestyä meille kättemme työn. Suo menestyä kättemme työn.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Joka Korkeimman suojassa istuu ja Kaikkivaltiaan varjossa yöpyy,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'sanoo: \" Herra on turvani ja linnani, hän on Jumalani, johon turvaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Sillä hän päästää sinut linnustajan paulasta ja turmiollisesta rutosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Sulillaan hän suojaa sinua, ja sinä saat turvan hänen siipiensä alla. Hänen uskollisuutensa on kilpi ja suojus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Sinä et pelkää yön kauhuja, et päivällä lentävää nuolta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'et ruttoa, joka kulkee pimeässä, etkä kulkutautia, joka keskellä päivää tekee hävitystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Vaikka tuhat kaatuisi sivultasi, kymmenen tuhatta oikealta puoleltasi, se ei sinuun satu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Silmäsi saavat vain katsella ja nähdä, kuinka jumalattomille kostetaan. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Sillä: \"Sinä, Herra, olet turvani.\" – Korkeimman sinä olet ottanut suojaksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Sinua ei kohtaa onnettomuus, eikä vitsaus lähesty telttamajaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Sillä hän antaa enkeleilleen sinusta käskyn varjella sinua kaikilla teilläsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'He kantavat sinua käsillään, ettet jalkaasi kiveen loukkaisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Sinä kuljet leijonan ja kyykäärmeen yli, sinä tallaat nuorta jalopeuraa ja lohikäärmettä. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, '\"Koska hän riippuu minussa kiinni, minä hänet pelastan. Minä suojelen hänet, sillä hän tuntee nimeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Hän huutaa minua avukseen, ja vastaan hänelle. Minä olen hänen luonaan, kun hänellä on ahdistus. Vapautan hänet ja saatan hänet kunniaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Ravitsen hänet pitkällä iällä ja suon hänen nähdä autuuteni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Psalmi, sapatinpäivän laulu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Hyvä on Herraa kiittää ja veisata kiitosta nimellesi, sinä Korkein,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'aamulla julistaa armoasi ja yön tullen totuuttasi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'kymmenkielisillä soittimilla ja harpuilla, lyyralla soittaen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Sillä sinä ilahdutat minut, Herra, töilläsi. Minä riemuitsen kättesi teoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Kuinka suuret ovatkaan tekosi, Herra! Ajatuksesi ovat hyvin syvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Järjetön mies ei tätä ymmärrä, eikä tyhmä sitä älyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Kun jumalattomat rehottavat kuin ruoho ja väärintekijät kaikki kukoistavat, se on heille ikuiseksi häviöksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Mutta sinä, Herra, olet korkea iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Sillä katso, vihollisesi, Herra, katso, vihollisesi hukkuvat, kaikki väärintekijät joutuvat hajaantumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Mutta minun sarveni sinä kohotat kuin re\'eem-eläimen sarvet. Minut voidellaan tuoreella öljyllä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Silloin silmäni katsovat vainoojiani, korvani kuulevat noista pahoista, jotka ovat nousseet minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Vanhurskas viheriöitsee kuin palmupuu ja kasvaa kuin Libanonin setri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'He ovat istutetut Herran huoneeseen. He viheriöivät Jumalamme kartanoissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Vielä vanhuudessaan he tekevät hedelmää, ovat mehevät ja vihannat');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 16, 'ja julistavat, että Herra on vanhurskas, hän, kallioni, ja ettei hänessä ole vääryyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Herra on kuningas. Hän on pukeutunut valtasuuruuteen. Herra on pukeutunut, vyöttäytynyt voimaan. Maanpiiri pysyy lujana eikä horju.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Sinun valtaistuimesi on vahva aikojen alusta, iankaikkisuudesta asti olet sinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Vesivirrat nostavat, Herra, vesivirrat nostavat pauhinansa, niin, vesivirrat nostavat kuohunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Mutta yli suurten, voimallisten vetten pauhinan, yli meren kuohujen Herra on korkeudessa voimallinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Todistuksesi ovat aivan vahvat ja pyhyys on huoneesi kaunistus, Herra, aina päivien loppuun saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Sinä koston Jumala, Herra, sinä koston Jumala, ilmesty kirkkaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Nouse, maan tuomari, kosta ylpeille heidän tekonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Kuinka kauan jumalattomat, Herra, kuinka kauan jumalattomat saavat riemuita?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'He suoltavat julkeita sanoja, kaikki väärintekijät kerskuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Herra, he runtelevat kansaasi, ja rasittavat perintöosaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'He tappavat leskiä ja muukalaisia ja murhaavat orpoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'Vieläpä he sanovat: \" Herra ei sitä näe eikä Jaakobin Jumala sitä huomaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Ymmärtäkää, te järjettömät kansassa, ja te houkat – milloin viisastutte?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Joka on korvan istuttanut, hänkö ei kuulisi? Joka on silmän luonut, hänkö ei näkisi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Eikö se, joka kurittaa kansoja, rankaisisi, hän, joka ihmisille opettaa tiedon?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Herra tuntee ihmisten ajatukset, sillä he ovat kuin tuulen henkäys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Autuas se mies, jota sinä, Herra, kuritat ja jolle sinä opetat lakisi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'antaaksesi hänelle rauhan pahoilta päiviltä, kunnes jumalattomalle on kaivettu hauta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Sillä Herra ei hylkää kansaansa eikä heitä pois perintöosaansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'vaan oikeus on palaava vanhurskauden luo, ja kaikki oikeamieliset seuraavat sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Kuka nousee puolelleni pahoja vastaan, kuka asettuu rinnalleni väärintekijöitä vastaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Ellei Herra olisi apuni, sieluni asuisi kohta hiljaisuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Kun sanoin: \"Jalkani horjuu\", niin armosi, Herra, tuki minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Kun minulla on sisälläni paljon murheita, lohdutuksesi ilahduttaa sieluani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Onko turmion tuomioistuimella yhteyttä sinuun, kun väkivaltaa tehdään lakiin vedoten?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'He hyökkäävät vanhurskaan sielua vastaan ja tuomitsevat viattoman veren syylliseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Mutta Herra on linnani, Jumalani on suojakallioni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Hän kostaa heille heidän vääryytensä ja hävittää heidät heidän pahuutensa tähden. Herra, meidän Jumalamme, hävittää heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Tulkaa, kohottakaamme ilohuuto Herralle, riemuhuuto pelastuksemme kalliolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Käykäämme kiittäen hänen kasvojensa eteen, veisatkaamme hänelle riemuvirsiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Sillä Herra on suuri Jumala, suuri kuningas yli kaikkien jumalien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'Maan syvyydet ovat hänen kädessään, ja hänen ovat vuorten kukkulat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Hänen on meri, sillä hän on sen tehnyt, ja kuiva maa, jonka hänen kätensä ovat valmistaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Tulkaa, kumartukaamme ja polvistukaamme, langetkaamme polvillemme Herran, meidän Luojamme, eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Sillä hän on Jumalamme, ja me olemme kansa, jota hän paimentaa, lauma, jota hänen kätensä kaitsee. Jospa tänä päivänä kuulisitte hänen äänensä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, '\"Älkää paaduttako sydäntänne kuten Meribassa, niin kuin Massan päivänä erämaassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'jossa isänne minua kiusasivat, jossa he koettelivat minua, vaikka olivat nähneet tekoni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Neljäkymmentä vuotta minä olin kyllästynyt siihen sukuun ja sanoin: \'He ovat kansa, jonka sydän on eksynyt, eivätkä he tahdo tietää teistäni.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Niin minä vihassani vannoin: \'He eivät pääse minun lepooni.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Veisatkaa Herralle uusi virsi, veisatkaa Herralle, kaikki maa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Veisatkaa Herralle, ylistäkää hänen nimeään. Julistakaa päivästä päivään hänen autuuttaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'ilmoittakaa pakanoiden keskuudessa hänen kunniaansa, hänen ihmeitään kaikkien kansojen seassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Sillä Herra on suuri ja sangen ylistettävä, hän on pelottava yli kaikkien jumalien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Sillä kaikki kansojen jumalat ovat epäjumalia, mutta Herra on tehnyt taivaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Valtasuuruus ja kunnia on hänen kasvojensa edessä. Hänen pyhäkössään on voima ja ihanuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Antakaa Herralle, te kansojen sukukunnat, antakaa Herralle kunnia ja voima.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Antakaa Herralle hänen nimensä kunnia, tuokaa lahjoja, tulkaa hänen esikartanoihinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Kumartakaa Herraa pyhässä kaunistuksessa, vaviskaa hänen kasvojensa edessä, kaikki maa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Sanokaa pakanoiden keskuudessa: \" Herra on kuningas.\" Niin pysyy maanpiiri lujana, se ei horju. Hän tuomitsee kansat oikeuden mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Iloitkoot taivaat, ja riemuitkoon maa. Pauhatkoon meri ja kaikki, mitä siinä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Ihastukoot kedot ja kaikki, mitä kedolla on. Riemuitkoot silloin kaikki metsän puut');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'Herran edessä, sillä hän tulee, sillä hän tulee tuomitsemaan maata: hän tuomitsee maanpiirin vanhurskaudessa ja kansat uskollisuudessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Herra on kuningas! Riemuitkoon maa. Iloitkoot saaret, niin monta kuin niitä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Pilvi ja pimeys on hänen ympärillään, vanhurskaus ja oikeus on hänen valtaistuimensa perustus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Tuli käy hänen edellään ja polttaa hänen vihollisensa kaikkialta hänen ympäriltään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Hänen salamansa valaisevat maanpiiriä. Maa näkee sen ja vapisee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Vuoret sulavat kuin vaha Herran edessä, kaiken maan Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Taivaat julistavat hänen vanhurskauttaan, ja kaikki kansat näkevät hänen kunniansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Kaikki kuvien kumartajat joutuvat häpeään, kaikki, jotka epäjumalista kerskuvat. Kumartakaa häntä, kaikki jumalat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Siion kuulee sen ja iloitsee, ja Juudan tyttäret riemuitsevat tuomioistasi, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Sillä sinä, Herra, olet Korkein yli kaiken maan, sinä olet hyvin korkea, yli kaikkien jumalien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Te, jotka Herraa rakastatte, vihatkaa pahaa. Hän varjelee pyhien sielut. Hän pelastaa heidät jumalattomien kädestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Vanhurskaalle kylvetään valkeutta ja oikeamielisille iloa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Iloitkaa Herrassa, te vanhurskaat. Kiittäkää hänen pyhyytensä muistoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Psalmi. Veisatkaa Herralle uusi virsi, sillä hän on ihmeitä tehnyt. Hän on saanut voiton oikealla kädellään ja pyhällä käsivarrellaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Herra on tehnyt tiettäväksi autuutensa. Hän on tehnyt tiettäväksi vanhurskautensa pakanoiden silmien eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Hän on muistanut armonsa ja uskollisuutensa Israelin huonetta kohtaan. Kaikki maan ääret ovat nähneet Jumalamme autuuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Kohottakaa riemuhuuto Herralle, kaikki maa, iloitkaa ja riemuitkaa ja veisatkaa kiitosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Veisatkaa Herran kiitosta lyyroilla – lyyroilla ja ylistysvirren sävelillä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'vaskitorvilla ja torven äänellä. Kohottakaa riemuhuuto Herran, kuninkaan, edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Pauhatkoon meri ja kaikki, mitä siinä on, maanpiiri ja ne, jotka siinä asuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Lyökööt virrat käsiään yhteen, ja vuoret yhdessä riemuitkoot');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'Herran edessä, sillä hän tulee tuomitsemaan maan. Hän tuomitsee maanpiirin vanhurskaudessa ja kansat oikeuden mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Herra on kuningas. Kansat vapisevat. Hän istuu kerubien yläpuolella. Maa järkkyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Suuri on Herra Siionissa, hän on korkea yli kaikkien kansojen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'He ylistävät sinun suurta ja pelättävää nimeäsi. Hän on pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Kuninkaan voimana on, että hän rakastaa oikeutta. Sinä olet saattanut oikeuden voimaan. Sinä panet toimeen oikeuden ja vanhurskauden Jaakobissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Ylistäkää Herraa, meidän Jumalaamme. Kumartukaa hänen jalkojensa astinlaudan eteen. Hän on pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Mooses ja Aaron hänen pappiensa joukossa ja Samuel niiden joukossa, jotka avuksi huusivat hänen nimeään. He huusivat Herraa, ja hän vastasi heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Hän puhui heille pilvenpatsaasta. He noudattivat hänen todistuksiaan ja käskyjä, jotka hän oli heille antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Herra, Jumalamme, sinä vastasit heille, ja olit heille anteeksiantava Jumala, vaikka sinä kostit heidän pahat tekonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Ylistäkää Herraa, Jumalaamme, rukoilkaa kumartuneina hänen pyhää vuortaan kohti, sillä Herra, Jumalamme, on pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Kiitosuhripsalmi. Kohottakaa riemuhuuto Herralle, kaikki maa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Palvelkaa Herraa ilolla, tulkaa hänen kasvojensa eteen riemulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Tietäkää, että Herra on Jumala. Hän on meidät tehnyt, ja hänen me olemme, hänen kansansa ja hänen laitumensa lampaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Käykää hänen portteihinsa kiittäen, hänen esikartanoihinsa ylistystä veisaten. Ylistäkää häntä, kiittäkää hänen nimeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Sillä Herra on hyvä. Hänen armonsa pysyy iankaikkisesti ja hänen uskollisuutensa polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Daavidin psalmi. Laulan armosta ja oikeudesta ja veisaan ylistystäsi, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Minä tahdon katsella nuhteetonta tietä. Milloin tulet luokseni? Minä tahdon vaeltaa huoneessani eheällä sydämellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'En aseta silmieni eteen mitään turhaa. Eksyttävää menoa minä vihaan. Se ei saa minuun tarttua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Nurja sydän väistyköön minusta. Pahasta en tahdo tietää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Joka salaa panettelee lähimmäistään, sen minä hukutan. Sitä, jolla on ylpeät silmät ja kopea sydän, minä en siedä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Maan uskollisiin ovat silmäni, että he asuisivat kanssani. Se, joka vaeltaa nuhteettomuuden tietä, on palveleva minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Vilpin tekijä älköön asuko huoneessani, valheen puhuja ei kestä silmieni edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Joka aamu minä hävitän kaikki jumalattomat maasta lopettaakseni kaikki väärintekijät Herran kaupungista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Kurjan rukous, kun hän on näännyksissä ja vuodattaa valituksensa Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Herra, kuule rukoukseni, ja huutoni tulkoon eteesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Älä kätke kasvojasi minulta, kun minulla on ahdistus. Kallista korvasi puoleeni, kun huudan, riennä ja vastaa minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Sillä päiväni ovat haihtuneet kuin savu, ja luitani polttaa kuin ahjossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Sydäntäni on taottu ja se on kuivunut kuin ruoho, sillä minä unohdan syödä leipääni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Vaikerrukseni äänestä luuni tarttuvat lihaani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Olen kuin pelikaani erämaassa. Olen kuin huuhkaja raunioissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Olen uneton, olen kuin yksinäinen lintu katolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Kaiken päivää viholliseni minua häpäisevät. Ne, jotka riehuvat minua vastaan, kiroavat nimeni kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Sillä minä syön tuhkaa kuin leipää ja sekoitan juomani kyynelillä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'sinun vihasi ja kiivastuksesi tähden, sillä sinä olet nostanut minut ylös ja heittänyt pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Päiväni ovat kuin pitenevä varjo, ja minä kuivun kuin ruoho.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Mutta sinä, Herra, hallitset iankaikkisesti, sinun muistosi pysyy polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Nouse ja armahda Siionia, sillä aika on tehdä sille laupeus ja sen hetki on tullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Sillä sen kivet ovat palvelijoillesi rakkaat, ja sen sorakasoja heidän on sääli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Pakanat pelkäävät Herran nimeä ja kaikki maan kuninkaat kunniaasi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'kun Herra rakentaa Siionin, hän ilmestyy kunniassaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'ja kun hän kääntyy niiden rukouksen puoleen, jotka ovat kaikkensa menettäneet, eikä enää hylkää heidän rukoustaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Tämä kirjoitettakoon tulevalle polvelle, ja kansa, joka vastedes luodaan, on kiittävä Herraa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'että hän katseli pyhästä korkeudestaan, että Herra katsoi taivaasta maahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'kuullakseen vankien huokaukset, vapauttaakseen kuoleman lapset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'jotta Siionissa julistettaisiin Herran nimeä ja hänen ylistystään Jerusalemissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'kun kaikki kansat ja valtakunnat kokoontuvat yhteen, palvelemaan Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Hän on lannistanut matkalla voimani ja lyhentänyt päiväni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Minä sanon: Jumalani, älä tempaa minua pois kesken ikääni. Sinun vuotesi kestävät polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Muinoin sinä perustit maan, ja taivaat ovat sinun käsialaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Ne katoavat, mutta sinä pysyt, ja ne vanhenevat kaikki kuin vaate. Sinä muutat ne, niin kuin vaatteet muutetaan, ja ne muuttuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Mutta sinä pysyt samana, eivätkä vuotesi lopu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 29, 'Sinun palvelijasi lapset asuvat turvassa, ja heidän jälkeläisensä pysyvät edessäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Daavidin psalmi. Kiitä Herraa, sieluni, ja kaikki, mitä minussa on, hänen pyhää nimeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Kiitä Herraa, sieluni, äläkä unohda, mitä hyvää hän on sinulle tehnyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'hän, joka antaa kaikki syntisi anteeksi ja parantaa kaikki sairautesi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'joka lunastaa elämäsi haudasta ja kruunaa sinut armolla ja laupeudella,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'joka tyydyttää halajamisesi hyvyydellään, niin että nuoruutesi uudistuu kuin kotkan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Herra tekee vanhurskauden ja oikeuden kaikille sorretuille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Hän on tehnyt Moosekselle tunnetuksi tiensä, Israelin lapsille suuret tekonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Laupias ja armahtavainen on Herra, pitkämielinen ja suuri armossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Hän ei aina riitele eikä pidä vihaa iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Hän ei tee meille syntiemme mukaan eikä kosta meille pahojen tekojemme mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Sillä niin korkealla kuin taivas on maasta, niin voimallinen on hänen armonsa niitä kohtaan, jotka häntä pelkäävät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Niin kaukana kuin itä on lännestä, niin kauas hän siirtää meistä rikoksemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Niin kuin isä armahtaa lapsiaan, niin Herrakin armahtaa pelkääväisiään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Sillä hän tietää, millaisia me olemme. Hän muistaa meidät tomuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Ihmisen päivät ovat kuin ruoho. Hän kukoistaa kuin kukkanen kedolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Kun tuuli käy hänen ylitseen, häntä ei enää ole, eikä hänen asuinsijansa häntä enää tunne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Mutta Herran armo pysyy iankaikkisesta iankaikkiseen niille, jotka häntä pelkäävät, ja hänen vanhurskautensa lasten lapsille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'niille, jotka pitävät hänen liittonsa ja muistavat hänen käskynsä noudattaakseen niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Herra on perustanut valtaistuimensa taivaisiin, ja hänen kuninkuutensa hallitsee kaikkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Kiittäkää Herraa, te hänen enkelinsä, te väkevät sankarit, jotka toteutatte hänen sanansa, kun kuulette hänen sanansa äänen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Kiittäkää Herraa, kaikki hänen sotaväkensä, te hänen palvelijansa, jotka hänen tahtonsa teette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Kiittäkää Herraa, kaikki hänen tekonsa hänen valtakuntansa kaikissa paikoissa. Kiitä, sieluni, Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Kiitä Herraa, sieluni. Herra, Jumalani, sinä olet sangen suuri. Valtasuuruus ja kirkkaus ovat pukunasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Sinä verhoudut valoon kuin viittaan, sinä levität taivaat kuin teltan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Sinä rakennat salisi vetten päälle, teet pilvet vaunuiksesi ja kuljet tuulen siivin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Sinä teet enkelisi tuuliksi ja palvelijasi tulen liekeiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Sinä asetit maan perustuksilleen, niin että se pysyy horjumatta ikuisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Sinä peitit sen syvyyden vesillä kuin vaatteella. Vuorten yläpuolella seisoivat vedet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Mutta ne pakenivat nuhteluasi. Sinun jyrinääsi ne pakenivat;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'vuoret kohosivat ja laaksot laskeutuivat paikkoihin, jotka olit niille valmistanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Panit rajan, jonka yli vedet eivät käy eivätkä palaa peittämään maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Lähetit laaksoihin lähteitä, jotka virtaavat vuorten välissä puroina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Ne antavat juoman kaikille metsän eläimille, villiaasit sammuttavat niistä janonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Taivaan linnut asuvat niiden partailla ja visertävät lehvien välissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Saleistasi [sinä] kastelet vuoret, töittesi hedelmistä maa saa ravintonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, '[Sinä] kasvatat ruohon karjalle ja kasvit ihmisen tarpeeksi tuottaaksesi maasta leivän');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'ja viinin, joka ilahduttaa ihmisen sydämen. Saatat kasvot öljystä kiiltäviksi, ja leipä vahvistaa ihmisen sydäntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Ravintonsa saavat myös Herran puut, Libanonin setrit, jotka hän on istuttanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Niissä linnut pesivät, ja haikaroilla on majansa sypresseissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Korkeat vuoret ovat kauristen hallussa, kallionkolot ovat tamaanien suojana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Kuun sinä olet tehnyt näyttämään aikoja. Aurinko tietää laskunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Teet pimeän, ja tulee yö. Silloin lähtevät liikkeelle kaikki metsän eläimet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Nuoret leijonat kiljuvat saalista ja pyytävät Jumalalta elatustaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Aurinko nousee. Ne vetäytyvät pois ja laskeutuvat luoliinsa makaamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Silloin ihminen menee töihinsä ja hoitaa askareitaan iltaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Kuinka monenlaiset ovat tekosi, Herra! Olet tehnyt ne kaikki viisaasti, maa on täynnä luotujasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Merikin, suuri ja aava – siinä vilisee lukemattomat laumat pieniä ja suuria eläimiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Siellä kulkevat laivat, siellä leviatan, jonka sinä olet luonut siinä leikkimään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Ne kaikki odottavat sinua, että antaisit niille ruuan ajallaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Annat niille, ja ne kokoavat, avaat kätesi, ja ne ravitaan hyvyydellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Peität kasvosi, ja ne pelästyvät. Otat pois niiden hengen, ne kuolevat ja palaavat tomuun jälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Lähetät Henkesi, ja ne luodaan, ja uudistat maan muodon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Pysyköön Herran kunnia iankaikkisesti. Saakoon Herra iloita teoistaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'hän, joka luo silmänsä maahan, ja se vapisee, joka koskettaa vuoria, ja ne syöksevät savua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Kaiken ikäni ylistän Herraa, ja veisaan Jumalani kiitosta, niin kauan kuin elän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Olkoot tutkisteluni hänelle otolliset. Minä iloitsen Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Hävitkööt syntiset maasta, älköön jumalattomia enää olko. Kiitä Herraa, sieluni. Halleluja!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Kiittäkää Herraa, julistakaa hänen nimeään, tehkää hänen suuret tekonsa tiettäviksi kansojen keskuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Laulakaa hänelle, soittakaa hänelle, puhukaa kaikista hänen ihmeistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Hänen pyhä nimensä olkoon kerskauksenne. Iloitkoon niiden sydän, jotka Herraa etsivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Kysykää Herraa ja hänen voimaansa, etsikää alati hänen kasvojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Muistakaa hänen ihmetöitään, jotka hän on tehnyt, hänen ihmeitään ja hänen suunsa tuomioita,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'te Aabrahamin, hänen palvelijansa, siemen, Jaakobin lapset, te hänen valittunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Hän, Herra, on Jumalamme. Hänen tuomionsa käyvät yli kaiken maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Hän muistaa liittonsa iankaikkisesti, säätämänsä sanan tuhansiin polviin asti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'liittonsa, jonka hän teki Aabrahamin kanssa, ja Iisakille vannomansa valan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'Hän vahvisti sen säädökseksi Jaakobille, Israelille iankaikkiseksi liitoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'Hän sanoi: \"Sinulle minä annan Kanaanin maan, olkoon se teidän perintöosanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Heitä oli vähäinen joukko, vain harvoja, ja he olivat siellä muukalaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Silloin he vaelsivat kansasta kansaan ja yhdestä valtakunnasta toiseen kansaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Hän ei sallinut kenenkään heitä vahingoittaa, ja hän rankaisi kuninkaita heidän tähtensä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, '\"Älkää koskeko voideltuihini älkääkä tehkö pahaa profeetoilleni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Kun hän oli kutsunut nälänhädän maahan ja kokonaan murtanut leivän tuen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'hän oli lähettänyt heidän edellään miehen: Joosef oli myyty orjaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Hänen jalkojaan vaivattiin kahleilla, hän joutui rautoihin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'siksi kunnes hänelle annettu sana kävi toteen ja Herran puhe osoitti hänet puhtaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Kuningas lähetti ja vapautti hänet, kansojen hallitsija laski hänet irti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Hän pani hänet talonsa herraksi ja kaiken omaisuutensa haltijaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'sitomaan mielensä mukaan hänen ruhtinaitaan ja opettamaan viisautta vanhimmille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Niin joutui Israel Egyptiin, Jaakob muukalaiseksi Haamin maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Sitten Herra teki kansansa hyvin hedelmälliseksi ja heidän vihamiehiään väkevämmäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Hän käänsi näiden sydämen vihaamaan hänen kansaansa ja kohtelemaan kavalasti hänen palvelijoitaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Hän lähetti Mooseksen, palvelijansa, ja Aaronin, jonka hän oli valinnut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Nämä tekivät hänen tunnustekonsa heidän keskellään ja tekivät ihmeitä Haamin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Hän lähetti pimeyden ja pimensi kaiken, eivätkä he vastustaneet hänen sanojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Hän muutti heidän vetensä vereksi ja tappoi heiltä kalat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Heidän maansa vilisi sammakoita aina kuningasten huoneita myöten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Hän käski, ja paarmoja ja sääskiä tuli koko heidän alueelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Hän antoi heille rakeita sateen sijaan ja tulen leimauksia heidän maahansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Hän myös hävitti heidän viini- ja viikunapuunsa ja murskasi puut heidän alueeltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Hän käski, ja heinäsirkkoja ja tuhosirkkoja tuli lukematon joukko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'Ne söivät kaiken ruohon heidän maastaan, söivät sadon heidän vainioiltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Sitten hän surmasi kaikki heidän maansa esikoiset, kaikki heidän miehuutensa ensimmäiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Sitten hän vei Israelin sieltä varustettuna hopealla ja kullalla, eikä ollut hänen sukukunnissaan kompastuvaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Egypti iloitsi heidän lähdöstään, koska sen oli vallannut pelko heidän tähtensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Hän levitti suojaksi pilven ja tulen valaisemaan yötä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'He pyysivät, ja hän pani tulemaan viiriäisiä, ja hän ravitsi heitä taivaan leivällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Hän avasi kallion, ja vettä vuoti. Se juoksi virtana kautta erämaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Sillä hän muisti pyhän sanansa, muisti Aabrahamia, palvelijaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Hän vei kansansa pois sen iloitessa, valittunsa heidän riemuitessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'Sitten hän antoi heille pakanoiden maita, ja he ottivat omakseen kansojen vaivannäköjä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'että he noudattaisivat hänen säädöstään ja säilyttäisivät hänen lakinsa. Halleluja!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Halleluja! Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Kuka voi kertoa Herran voimalliset teot, julistaa kaiken hänen ylistyksensä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Autuaat ne, jotka noudattavat oikeutta, jotka tekevät aina vanhurskauden!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Muista minua, Herra, suosiosi tähden kansaasi kohtaan, etsi minua autuudellasi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'että näkisin valittujesi onnen, iloitsisin kansasi ilossa ja kerskaisin perintöosasi kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Me olemme tehneet syntiä isiemme kanssa, olemme tehneet väärin ja olleet jumalattomat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Isämme eivät ymmärtäneet Egyptissä ihmeitäsi eivätkä muistaneet monia armotekojasi, vaan niskoittelivat meren rannalla, Kaislameren rannalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Kuitenkin hän pelasti heidät nimensä tähden tehdäkseen voimansa tiettäväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Hän nuhteli Kaislamerta, ja se kuivui. Hän kuljetti heitä syvyyksissä kuin erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Hän pelasti heidät vihamiehen kädestä ja lunasti heidät vihollisen vallasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Vedet peittivät heidän ahdistajansa eikä yhtään jäänyt heistä jäljelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'He uskoivat hänen sanansa ja veisasivat hänen ylistystään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Mutta pian he unohtivat hänen tekonsa eivätkä odottaneet hänen neuvoaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Heissä syttyi himo erämaassa, ja he kiusasivat Jumalaa korvessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Silloin hän antoi heille, mitä he pyysivät, mutta hän myös lähetti heihin hivuttavan taudin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Heissä syttyi leirissä kateus Moosesta vastaan ja Aaronia, Herran pyhää, vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Maa aukeni ja nieli Daatanin ja peitti Abiramin joukkion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'Heidän joukkiossaan syttyi tuli ja liekki poltti jumalattomat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'He tekivät vasikan Hoorebin juurella ja kumarsivat valettua kuvaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'He vaihtoivat Kunniansa ruohoa syövän härän kuvaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'He unohtivat Jumalan, pelastajansa, joka oli tehnyt Egyptissä suuria tekoja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'ihmeitä Haamin maassa, pelottavia tekoja Kaislameren rannalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Silloin hän aikoi hävittää heidät, mutta Mooses, hänen valittunsa, seisoi suojana hänen edessään ja käänsi pois hänen vihansa tuhoa tuottamasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'He pitivät halpana ihanan maan eivätkä uskoneet hänen sanaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'He napisivat teltoissaan eivätkä kuulleet Herran ääntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Silloin hän nosti kätensä heitä vastaan kaataakseen heidät erämaassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'kaataakseen heidän jälkeläisensä pakanoiden sekaan ja sirotellakseen heidät muihin maihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'He liittyivät Baal-Peoriin ja söivät kuolleitten jumalien uhreja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'He vihoittivat hänet teoillaan, ja vitsaus alkoi riehua heidän keskuudessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Mutta Piinehas astui esiin ja pani tuomion toimeen, ja vitsaus taukosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Se luettiin hänelle vanhurskaudeksi, polvesta polveen, iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'He vihoittivat hänet [Herran] Meriban vetten luona, ja Mooseksen kävi pahoin heidän tähtensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Sillä he niskoittelivat Jumalan Henkeä vastaan, ja hän puhui huulillaan ajattelemattomasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'He eivät hävittäneet niitä kansoja, jotka Herra oli käskenyt heidän hävittää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'vaan pitivät yhteyttä pakanoiden kanssa ja oppivat heidän tekonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'He palvelivat heidän jumalankuviaan, ja niistä tuli heille paula.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'He uhrasivat poikiaan ja tyttäriään riivaajille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'He vuodattivat viatonta verta, poikiensa ja tyttäriensä verta, uhraten heitä Kanaanin epäjumalille, ja maa saastui veriveloista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'He saastuttivat itsensä töillään ja olivat haureelliset teoissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Herran viha syttyi hänen kansaansa vastaan, ja hän kyllästyi perintöosaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'Hän jätti heidät pakanoiden käsiin, ja heidän vihamiehensä vallitsivat heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'Heidän vihollisensa ahdistivat heitä, ja he alistuivat heidän kätensä alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Monet kerrat hän pelasti heidät, mutta he olivat uppiniskaisia omissa arvioinneissaan ja sortuivat pahojen tekojensa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Mutta hän katsoi heihin heidän ahdistuksessansa kuullessaan heidän valitushuutonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'Hän muisti heidän hyväkseen liittonsa ja armahti heitä suuressa laupeudessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Hän myös salli heidän saada armon kaikilta, jotka olivat vieneet heidät vankeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Pelasta meidät, Herra, Jumalamme, ja kokoa meidät pakanoiden seasta, että kiittäisimme pyhää nimeäsi ja kerskauksenamme olisi ylistyksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Kiitetty olkoon Herra, Israelin Jumala, iankaikkisesta iankaikkiseen. Niin kaikki kansa sanokoon: \"Aamen. Halleluja!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Niin sanokoot Herran lunastetut, jotka hän on lunastanut vihollisen kädestä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'ja koonnut pakanamaista, idästä ja lännestä, pohjoisesta ja meren puolelta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'He harhailivat erämaassa, autiossa, tiettömässä maassa löytämättä asuttua kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Heidän oli nälkä ja jano ja heidän sielunsa nääntyi heissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Mutta hädässään he huusivat Herraa, ja hän pelasti heidät heidän ahdistuksistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'Hän ohjasi heidät oikealle tielle, niin että he pääsivät asuttuun kaupunkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Kiittäkööt he Herraa hänen armostaan, hänen ihmeellisistä teoistaan ihmislapsia kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Sillä hän ravitsee nääntyvän sielun ja täyttää nälkäisen sielun hyvyydellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'He istuivat pimeydessä ja kuoleman varjossa, vangittuina kurjuuteen ja rautoihin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'koska olivat nousseet Jumalan sanoja vastaan ja katsoneet halvaksi Korkeimman neuvon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Hän masensi heidän sydämensä kärsimyksellä, ja he sortuivat, eikä ollut auttajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Mutta hädässään he huusivat Herraa, ja hän pelasti heidät heidän ahdistuksistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Hän vei heidät ulos pimeydestä ja kuoleman varjosta, hän katkaisi heidän kahleensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Kiittäkööt he Herraa hänen armostaan ja hänen ihmeellisistä teoistaan ihmislapsia kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Sillä hän särkee vaskiset ovet ja rikkoo rautaiset salvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Houkkia vaivattiin heidän rikostensa ja pahojen tekojensa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Heidän sielunsa inhosi kaikkea ruokaa, ja he olivat lähellä kuoleman portteja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Mutta hädässään he huusivat Herraa, ja hän pelasti heidät heidän ahdistuksistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Hän lähetti sanansa ja paransi heidät ja pelasti heidät haudasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Kiittäkööt he Herraa hänen armostaan ja hänen ihmeellisistä teoistaan ihmislapsia kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'Uhratkoot kiitosuhreja ja kertokoot riemuiten hänen töistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'He lähtivät laivoilla merelle ja kävivät kauppaa suurilla vesillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'He näkivät Herran työt ja hänen ihmeelliset tekonsa meren syvyyksissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Hän nosti sanalla myrskytuulen, joka kohotti korkealle sen aallot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'He kohosivat taivasta kohti, he vajosivat syvyyksiin, ja heidän sielunsa menehtyi tuskasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'He horjuivat ja hoippuivat kuin juopunut, ja kaikki heidän viisautensa oli raunioina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Mutta hädässään he huusivat Herraa, ja hän päästi heidät heidän ahdistuksistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Hän tyynnytti myrskyn, ja meren aallot hiljenivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'He iloitsivat, kun tuli tyyntä, ja hän vei heidät toivottuun satamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Kiittäkööt he Herraa hänen armostaan ja hänen ihmeellisistä teoistaan ihmislapsia kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Kunnioittakoot he häntä kansan seurakunnassa ja ylistäkööt häntä vanhinten kokouksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Hän muutti virrat erämaaksi ja vesilähteet kuivaksi maaksi ja');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'hedelmällisen maan suola-aroksi sen asukasten pahuuden tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Hän muutti erämaan vesilammikoiksi ja kuivan maan vesilähteiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'Sitten hän asetti nälkäiset sinne asumaan ja he rakensivat kaupungin asuttavakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'He myös kylvivät peltoja ja istuttivat viinitarhoja, jotka tuottivat runsaan sadon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Hän siunasi heitä, ja he lisääntyivät suuresti, ja hän antoi heille paljon karjaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Mutta kun he vähentyivät ja vaipuivat onnettomuuden ja huolten painamina,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'niin se, joka vuodattaa ylenkatsetta ruhtinasten päälle ja panee heidät harhailemaan tiettömissä autiomaissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'kohotti köyhän kurjuudesta ja teki suvut suuriksi kuin lammaslaumat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Oikeamieliset näkevät sen ja riemuitsevat, ja kaiken vääryyden täytyy tukkia suunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Se, joka on viisas, ottakoon näistä vaarin ja ajatelkoon Herran armotekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Laulu. Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Sydämeni on vahva, Jumala, tahdon veisata ja soittaa, myös omaa kunniaani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Herää, harppu ja lyyra. Tahdon herättää aamuruskon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Herra, sinua kiitän kansojen joukossa ja veisaan kiitostasi kansakuntien keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Sillä suuri on armosi ja se ulottuu yli taivasten ja totuutesi pilviin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Korota itsesi yli taivaitten, Jumala, ja kunniasi yli kaiken maan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'jotta rakkaasi tulisivat pelastetuiksi. Auta oikealla kädelläsi ja vastaa minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Jumala on puhunut pyhäkössään. Riemuitsen ja jaan Sikemin ja mittaan Sukkotin laakson.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Minun on Gilead, ja minun on Manasse. Efraim on pääni suojus ja Juuda valtikkani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Mooab on pesuastiani, Edomiin minä heitän sandaalini ja riemuitsen Filistean maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Kuka vie minut varustettuun kaupunkiin? Kuka saattaa minut Edomiin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Etkö sinä, Jumala, hylännyt meitä etkä lähtenyt, Jumala, sotajoukkojemme kanssa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Anna meille apu ahdistajaa vastaan, sillä turha on ihmisten apu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 14, 'Jumalan voimalla teemme väkeviä tekoja. Hän tallaa vihollisemme maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Veisuunjohtajalle. Daavidin psalmi. Jumala, minun ylistykseni, älä ole vaiti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Sillä he ovat avanneet minua vastaan jumalattoman ja petollisen suun ja puhuttelevat minua valheen kielellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Vihan sanoilla he ovat piirittäneet minut, ja syyttä he sotivat minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Rakkauteni palkaksi he minua vainoavat, mutta minä rukoilen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'He kostavat minulle hyvän pahalla ja rakkauteni vihalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Aseta jumalaton mies häntä vastaan, ja seisokoon saatana hänen oikealla puolellaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Kun häntä tuomitaan, todettakoon hänet syylliseksi, ja hänen rukouksensa tulkoon synniksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Hänen päivänsä olkoot harvat. Ottakoon toinen mies hänen kaitsijantoimensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Tulkoot hänen lapsensa orvoiksi ja hänen vaimonsa leskeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Kierrelkööt hänen lapsensa alati kerjäten ja etsikööt turvaa autioilta seuduilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Anastakoon koronkiskuri kaiken hänen omansa, ja riistäkööt vieraat hänen vaivannäkönsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Älköön kukaan osoittako hänelle laupeutta, älköön kukaan armahtako hänen orpojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Hänen jälkeläisensä hävitkööt sukupuuttoon, pyyhittäköön heidän nimensä pois toisessa polvessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Hänen isiensä rikokset pysykööt Herran muistossa, älköönkä hänen äitinsä syntiä pyyhittäkö pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Olkoot ne Herran edessä alati, ja hävittäköön hän heidän muistonsa maan päältä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Sillä mies ei muistanut tehdä laupeutta, vaan vainosi kurjaa ja köyhää ja sydämen tuskassa olevaa tappaakseen hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Hän rakasti kirousta, ja se kohtasi häntä. Hän ei huolinut siunauksesta, ja se väistyi hänestä kauas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Hän puki kirouksen ylleen kuin vaatteensa, ja se meni hänen sisuksiinsa kuin vesi ja hänen luihinsa kuin öljy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Se olkoon hänellä viittana, johon hän verhoutuu, ja vyönä, johon hän vyöttäytyy aina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Tämä olkoon Herralta minun vainoojieni palkka ja niiden, jotka puhuvat pahaa minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Mutta sinä, Herra, Herra, auta minua nimesi tähden, sillä armosi on hyvä, pelasta minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Sillä minä olen kurja ja köyhä, ja sydämeni on haavoitettu rinnassani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Katoan pois kuin pitenevä varjo, minut pudistetaan pois kuin heinäsirkka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Polveni horjuvat paastoamisesta, ja ruumiini on laihtunut lihattomaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Minä olen joutunut heidän herjattavakseen, minut nähdessään he nyökyttävät päätään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Auta minua, Herra, Jumalani, pelasta minut armosi mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'ja he saakoot tuntea, että tämä on kätesi, että sinä, Herra, sen teit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Jos he kiroavat, siunaa sinä, jos he nousevat, joutukoot häpeään, mutta palvelijasi saakoon iloita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Olkoon häväistys vainoojieni pukuna, ja verhotkoon heitä heidän häpeänsä kuin viitta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Kiitän suullani suuresti Herraa ja ylistän häntä monien keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Sillä hän seisoo kurjan oikealla puolella pelastaakseen hänet niistä, jotka hänet tuomitsevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Daavidin psalmi. Herra sanoi minun Herralleni: \"Istu oikealle puolelleni, kunnes minä panen vihollisesi jalkojesi astinlaudaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Herra ojentaa valtasi valtikan Siionista. Hallitse vihollistesi keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Altis on kansasi voimasi päivänä: pyhässä asussa nuoresi ovat edessäsi kasteena aamuruskon helmasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Herra on vannonut eikä kadu: \"Sinä olet pappi iankaikkisesti Melkisedekin järjestyksen mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Herra on oikealla puolellasi ja musertaa kuninkaat vihansa päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Hän tuomitsee pakanat: ruumiita viruu kaikkialla. Hän murskaa päitä laajalti maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Hän juo purosta tien varrelta. Sen tähden hän kohottaa päänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Halleluja! Kiitän Herraa. Ylistän Herraa kaikesta sydämestäni vanhurskasten kokouksessa ja seurakunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Suuret ovat Herran teot, kaikkien niiden tutkittavat, jotka niitä rakastavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Kunnialliset ja majesteetilliset ovat hänen työnsä, ja hänen vanhurskautensa pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Hän on säätänyt ihmeellisten tekojensa muiston; armollinen ja laupias on Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Hän antaa ruuan pelkäävilleen ja muistaa liittonsa iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Hän ilmoitti kansalleen tekojensa voiman. Hän antoi heille pakanoiden perintöosan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Hänen kättensä teot ovat totuutta ja noudattavat oikeutta. Kaikki hänen asetuksensa ovat luotettavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Ne pysyvät järkkymättä aina ja iankaikkisesti. Ne ovat tehdyt totuudessa ja oikeudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Hän lähetti kansalleen lunastuksen, sääti liittonsa ikuisiksi ajoiksi. Pyhä ja pelättävä on hänen nimensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Herran pelko on viisauden alku, hyvä ymmärrys kaikille, jotka sitä noudattavat. Hänen ylistyksensä pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Halleluja! Autuas se mies, joka Herraa pelkää ja jolla on suuri rakkaus hänen käskyihinsä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Hänen jälkeläisensä tulevat voimallisiksi maassa, oikeamielisten suku tulee siunatuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Varallisuus ja rikkaus on hänen huoneessaan, ja hänen vanhurskautensa pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Oikeamielisille koittaa pimeydessä valo, armollinen, laupias ja vanhurskas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Hyvin käy sen miehen, joka on laupias ja antaa lainaksi, joka hoitaa asiansa oikeuden mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Sillä hän ei koskaan horju. Vanhurskas säilyy ikuisessa muistossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Hän ei pelkää pahaa sanomaa. Hänen sydämensä on vahva, sillä hän turvaa Herraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Hänen sydämensä on luja ja peloton, kunnes hän ilolla katselee vihollisiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Hän sirottelee ja antaa köyhille. Hänen vanhurskautensa pysyy iankaikkisesti. Hänen sarvensa kohoaa kunniassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Jumalaton näkee sen ja närkästyy. Hän kiristelee hampaitaan ja menehtyy. Jumalattomien halut raukeavat tyhjiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Halleluja! Ylistäkää Herraa, ylistäkää, te Herran palvelijat, ylistäkää Herran nimeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Siunattu olkoon Herran nimi nyt ja iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Auringon noususta sen laskuun saakka olkoon Herran nimi ylistetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Herra on korkea yli kaikkien pakanakansojen ja yli taivasten on hänen kunniansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Kuka on kuin Herra, meidän Jumalamme, joka asuu korkealla');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'ja katsoo alas taivaassa ja maassa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Hän, joka nostaa tomusta alhaisen ja korottaa loasta köyhän');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'asettaakseen hänet ylhäisten rinnalle, kansansa ylhäisten rinnalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'joka antaa hedelmättömän asua kodissa, iloisena lasten äitinä! Halleluja!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Kun Israel lähti Egyptistä, Jaakobin huone vieraskielisestä kansasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'silloin Juuda tuli hänen pyhäkökseen, Israel hänen valtakunnakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'Sen näki meri ja pakeni, Jordan kääntyi takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Vuoret hyppivät kuin pässit, kukkulat kuin lammasten karitsat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Mikä sinun on, meri, kun pakenet, mikä sinun, Jordan, kun käännyt takaisin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Te vuoret, miksi hypitte kuin pässit, ja te kukkulat, kuin lammasten karitsat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Vapise, maa, Herran kasvojen edessä, Jaakobin Jumalan kasvojen edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'joka muuttaa kallion vesilammikoksi, kovan kiven vesilähteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Älä meille, Herra, älä meille, vaan omalle nimellesi anna kunnia armosi ja totuutesi tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Miksi pakanat saisivat sanoa: \"Missä on heidän Jumalansa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Meidän Jumalamme on taivaissa; mitä ikinä hän tahtoo, sen hän tekee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Mutta heidän epäjumalansa ovat hopeaa ja kultaa, ihmiskätten tekoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Niillä on suu, mutta ne eivät puhu, niillä on silmät, mutta ne eivät näe.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Niillä on korvat, mutta ne eivät kuule, niillä on nenä, mutta ne eivät haista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Niiden kädet eivät koske, niiden jalat eivät astu, eikä niiden kurkusta tule ääntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Niiden kaltaisia ovat niiden tekijät ja kaikki, jotka turvaavat niihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Israel, turvaa Herraan. Hän on heidän apunsa ja kilpensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Te, Aaronin huone, turvatkaa Herraan – hän on heidän apunsa ja kilpensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Te, Herraa pelkäävät, turvatkaa Herraan – hän on heidän apunsa ja kilpensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Herra muistaa meitä ja siunaa, hän siunaa Israelin huonetta, hän siunaa Aaronin huonetta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'hän siunaa niitä, jotka Herraa pelkäävät, sekä pieniä että suuria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Herra lisätköön teille, sekä teille että lapsillenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Te olette Herran siunatut, hänen, joka on tehnyt taivaan ja maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Taivas on Herran taivas, mutta maan hän on antanut ihmisten lapsille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Eivät kuolleet ylistä Herraa, ei kukaan hiljaisuuteen astuneista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Mutta me, me kiitämme Herraa, nyt ja iankaikkisesti. Halleluja!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Minä rakastan Herraa, sillä hän kuulee ääneni ja rukoukseni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'sillä hän on kallistanut korvansa puoleeni, ja minä huudan häntä avuksi kaiken elinaikani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Kuoleman paulat piirittivät minut, helvetin ahdistukset kohtasivat minua. Minä kohtasin hädän ja murheen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Mutta minä huusin avukseni Herran nimeä: \"Oi, Herra, pelasta sieluni!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Herra on armollinen ja vanhurskas, Jumalamme on laupias.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Herra varjelee yksinkertaiset. Minä olin viheliäinen, mutta hän auttoi minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Palaa, sieluni, takaisin lepoosi, sillä Herra on tehnyt sinulle hyvää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Sillä olet pelastanut sieluni kuolemasta, silmäni kyynelistä ja jalkani kompastumasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Vaellan Herran kasvojen edessä elävien maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Uskon, sen tähden minä puhun. Minä olin kovin vaivattu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Minä sanoin hädässäni: \"Kaikki ihmiset ovat valehtelijoita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Kuinka maksan Herralle kaikki hänen hyvät tekonsa minua kohtaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Kohotan pelastuksen maljan ja saarnaan Herran nimestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Täytän lupaukseni Herralle kaiken hänen kansansa edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Kallis on Herran silmissä hänen pyhiensä kuolema.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Oi, Herra, minä olen palvelijasi. Minä olen palvelijasi ja palvelijattaresi poika! Sinä avasit siteeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Sinulle uhraan kiitosuhrin ja saarnaan Herran nimestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Täytän lupaukseni Herralle kaiken hänen kansansa edessä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'Herran huoneen esikartanoissa, sinun keskelläsi, Jerusalem. Halleluja!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Kiittäkää Herraa, kaikki pakanat, ylistäkää häntä, kaikki kansat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Sillä hänen armonsa meitä kohtaan on voimallinen, ja Herran uskollisuus pysyy iankaikkisesti. Halleluja!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Kiittäkää Herraa, sillä hän on hyvä; sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Sanokoon nyt Israel että hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Sanokoon nyt Aaronin huone, että hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Sanokoot nyt Herraa pelkäävät, että hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Ahdistuksessani huusin Herraa. Herra vastasi minulle ja asetti minut avaraan paikkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Herra on puolellani, en pelkää. Mitä ihmiset voivat minulle tehdä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Herra on puolellani ja auttaa minua, ja minä saan iloiten katsella vihamiehiäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Parempi on luottaa Herraan kuin turvata ihmisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Parempi on luottaa Herraan kuin turvata ruhtinaihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Kaikki pakanat piirittivät minua, mutta Herran nimessä lyön heidät maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'He piirittivät minua joka taholta, mutta Herran nimessä lyön heidät maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Kuin mehiläiset he minua piirittivät, mutta he sammuvat kuin tuli orjantappuroissa. Herran nimessä lyön heidät maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Sinä sysäsit minua kovasti, että kaatuisin, mutta Herra auttoi minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Herra on voimani ja ylistysvirteni, ja hän tuli minulle autuudeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Riemun ja autuuden ääni kuuluu vanhurskaitten teltoissa: Herran oikea käsi tekee väkeviä tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Herran oikea käsi on korotettu. Herran oikea käsi tekee väkeviä tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'En kuole, vaan elän ja julistan Herran töitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Herra kuritti minua kurittamalla, mutta kuolemalle hän ei minua antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Avatkaa minulle vanhurskauden portit käydäkseni niistä sisälle kiittämään Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Tämä on Herran portti: vanhurskaat menevät siitä sisälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Kiitän sinua siitä, että vastasit minulle ja tulit minulle autuudeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Herralta tämä on tullut. Se on ihmeellinen silmissämme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Tämä on se päivä, jonka Herra on tehnyt. Riemuitkaamme ja iloitkaamme siitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Oi Herra, auta, oi Herra, anna menestys!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Siunattu olkoon hän, joka tulee Herran nimeen. Siunaamme teitä Herran huoneesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Herra on Jumala, ja hän antoi valon meille loistaa. Sitokaa juhlalehvät alttarin sarviin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Sinä olet Jumalani, ja sinua minä kiitän. Jumalani, sinua minä kunnioitan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Kiittäkää Herraa, sillä hän on hyvä; sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Autuaat ne, joiden tie on nuhteeton, jotka Herran laissa vaeltavat!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Autuaat ne, jotka ottavat vaarin hänen todistuksistaan, jotka etsivät häntä kaikesta sydämestään');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'eivätkä tee vääryyttä, vaan vaeltavat hänen teitään!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Sinä olet säätänyt asetuksesi, että niitä tarkasti noudatettaisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Oi, jospa vaellukseni olisi vakaa, niin että noudattaisin säädöksiäsi!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Silloin en joudu häpeään, kun katselen kaikkia käskyjäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Kiitän sinua vilpittömällä sydämellä, kun opin vanhurskautesi oikeudet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Noudatan käskyjäsi, älä minua peräti hylkää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Kuinka voi nuorukainen pitää tiensä puhtaana? Siten, että hän noudattaa sanaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Etsin sinua kaikesta sydämestäni. Älä salli minun eksyä pois käskyistäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'Kätken sanasi sydämeeni, etten tekisi syntiä sinua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Kiitetty ole sinä, Herra, opeta minulle käskysi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Huulillani julistan kaikki sinun suusi oikeudet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Iloitsen todistustesi tiestä kuin kaikesta rikkaudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Tutkin asetuksiasi ja katselen polkujasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Iloitsen käskyistäsi enkä unohda sanaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Tee palvelijallesi hyvin, että eläisin ja noudattaisin sanaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Avaa silmäni näkemään lakisi ihmeitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Minä olen muukalainen maan päällä. Älä salaa minulta käskyjäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Sieluni nääntyy ikävöidessäni alati oikeuksiasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Nuhtelet julkeita, kirottuja, jotka poikkeavat käskyistäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Poista päältäni häväistys ja halveksunta, sillä otan todistuksistasi vaarin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Ruhtinaatkin istuvat ja pitävät neuvoa minua vastaan, mutta palvelijasi tutkii käskyjäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Sinun todistuksesi ovat iloni ja neuvonantajani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Sieluni on vaipunut tomuun. Virvoita minua sanasi mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Kerron vaellukseni, ja sinä vastaat minulle. Opeta minulle käskysi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Saata minut ymmärtämään asetustesi tie, niin tutkin ihmeitäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Sieluni itkee murheesta, vahvista minua sanasi mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Käännä minusta pois valheen tie, ja anna armostasi minulle lakisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Olen valinnut totuuden tien, olen asettanut eteeni oikeutesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Riipun kiinni todistuksissasi, Herra, älä anna minun joutua häpeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Juoksen käskyjesi tietä, sillä sinä avarrat sydämeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Opeta minulle, Herra, käskyjesi tie, niin seuraan sitä loppuun asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Anna minulle ymmärrys ottaakseni laistasi vaarin ja noudattaakseni sitä kaikesta sydämestäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Anna minun vaeltaa käskyjesi polkua, sillä sitä haluan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Taivuta sydämeni todistuksiisi, älä väärän voiton puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Käännä silmäni pois katselemasta turhuutta, virvoita minua teilläsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Tee sanasi lujaksi palvelijallesi, että sinua pelkäisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Poista minusta häväistys, jota pelkään, sillä oikeutesi ovat hyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Katso, ikävöin asetuksiasi. Virvoita minua vanhurskaudellasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Tulkoon minulle armosi, Herra, apusi sanasi mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'että voisin sanalla vastata herjaajalleni; sillä turvaan sanaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Älä ota peräti pois suustani totuuden sanaa, sillä sinun oikeuteesi panen toivoni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Tahdon alati noudattaa lakiasi, aina ja iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'Vaellan avaralla paikalla, sillä kysyn asetuksiasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Puhun todistuksistasi kuningasten edessä, enkä häpeään joudu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Iloitsen käskyistäsi, jotka ovat minulle rakkaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Nostan käteni käskyjesi puoleen, jotka ovat minulle rakkaat, ja tutkin säädöksiäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Muista sana, jonka olet palvelijallesi puhunut, sillä siinä sinä olet antanut minulle toivon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Lohdutuksenani kurjuudessani on, että sanasi minua virvoittaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Julkeat pilkkaavat minua kovin, mutta laistasi en poikkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Herra, ajattelen ikiaikaisia tuomioitasi ja saan lohdutuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Minut valtaa palava viha jumalattomien tähden, jotka hylkäävät lakisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Käskysi ovat ylistysvirteni muukalaisuuteni huoneessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Yöllä ajattelen nimeäsi, Herra, ja noudatan lakiasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Tämä on suotu osakseni: että otan vaarin asetuksistasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Perintöosani, Herra, sanoin, on pitää sanasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Etsin mielisuosiotasi kaikesta sydämestäni. Ole minulle armollinen lupauksesi mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Tutkin teitäni, ja käännän askeleeni todistustesi puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Riennän viivyttelemättä noudattamaan käskyjäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Jumalattomien paulat piirittävät minua, mutta lakiasi en unohda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Puoliyöstä nousen kiittämään sinua vanhurskautesi oikeuksista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Olen kaikkien niiden ystävä, jotka pelkäävät sinua ja noudattavat asetuksiasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Maa on täynnä laupeuttasi, Herra. Opeta minulle käskysi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Osoitat palvelijallesi hyvyyttä sanasi mukaan, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Opeta minulle hyvä ymmärrys ja tieto, sillä luotan käskyihisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Ennen kuin minut nöyryytettiin, eksyin, mutta nyt noudatan sanaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Sinä olet hyvä, ja hyvin teet. Opeta minulle käskysi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Julkeat tahraavat minua valheillaan, mutta minä otan asetuksistasi vaarin kaikesta sydämestäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Heidän sydämensä on tunnoton kuin ihra, mutta minä iloitsen laistasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Hyvä oli minulle, että minut nöyryytettiin: jotta opin käskysi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Suusi laki on minulle kalliimpi kuin tuhannet kappaleet kultaa ja hopeaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Kätesi ovat minut tehneet ja valmistaneet. Anna minulle ymmärrystä oppiakseni käskysi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Sinua pelkäävät näkevät minut ja iloitsevat, sillä panen toivoni sanaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Herra, tiedän, että tuomiosi ovat vanhurskaat, ja uskollisuudessasi olet minut nöyryyttänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Armosi olkoon lohdutukseni, kuten olet palvelijallesi luvannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Tulkoon minulle laupeutesi ja suokoon se minulle elämän, sillä lakisi on iloni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Joutukoot julkeat häpeään, sillä he sortavat minua syyttä. Minä tutkin sinun asetuksiasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Kääntykööt puolelleni ne, jotka sinua pelkäävät ja jotka todistuksesi tuntevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Pysyköön sydämeni eheästi käskyissäsi, etten häpeään joutuisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Apuasi sieluni ikävöitsee, sanaasi panen toivoni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Silmäni ikävöitsevät sanaasi sanoen: \"Milloin lohdutat minua?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Sillä olen kuin nahkaleili savussa, mutta käskyjäsi en unohda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Kuinka harvat ovat palvelijasi päivät! Milloin tuomitset vainoojani?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Julkeat kaivavat minulle kuoppia, ne, jotka eivät elä lakisi mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Kaikki käskysi ovat todet. Syyttä he minua vainoavat, auta minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'He ovat minut lähes tuhonneet tässä maassa, mutta minä en ole hylännyt asetuksiasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Virvoita minua armosi mukaan, niin noudatan suusi todistuksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Herra, sanasi pysyy vahvana taivaissa iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Uskollisuutesi kestää polvesta polveen, sinä perustit maan, ja se pysyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Päätöksesi mukaan ne pysyvät vielä tänä päivänä, sillä ne kaikki ovat palvelijoitasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Ellei lakisi olisi ollut iloni, olisin menehtynyt kurjuuteeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'En unohda koskaan asetuksiasi, sillä niillä sinä virvoitat minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Sinun omasi minä olen, pelasta minut, sillä etsin asetuksiasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Jumalattomat väijyvät minua tuhotakseen minut, mutta otan vaarin todistuksistasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Olen nähnyt, että kaikella täydellisellä on rajansa, mutta sinun käskysi on hyvin avara.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Kuinka lakisi onkaan minulle rakas! Kaiken päivää sitä tutkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Sinun käskysi tekevät minut vihollisiani viisaammaksi, sillä ne ovat omani iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Olen kaikkia opettajiani taitavampi, sillä mietin todistuksiasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Olen ymmärtäväisempi kuin vanhat, sillä otan vaarin asetuksistasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Pidätän jalkani kaikilta pahoilta teiltä noudattaakseni sanaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'En poikkea oikeuksistasi, sillä sinä neuvot minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Kuinka makeat ovatkaan minulle lupauksesi! Ne ovat suussani hunajaa makeammat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Asetuksistasi saan ymmärrystä; sen tähden vihaan kaikkia valheen teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Sinun sanasi on jalkojeni lamppu ja valo tielleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Olen vannonut ja tahdon sen täyttää noudattaakseni vanhurskautesi oikeuksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Olen peräti vaivattu. Herra, virvoita minua sanasi mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Kelvatkoon sinulle, Herra, suuni vapaaehtoiset uhrit, ja opeta minulle oikeutesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Sieluni on alati kämmenelläni, mutta lakiasi en unohda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Jumalattomat virittävät pauloja eteeni, mutta asetuksistasi en eksy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Todistuksesi ovat ikuinen perintöosani, sillä ne ovat sydämeni ilo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Olen taivuttanut sydämeni pitämään käskysi aina ja loppuun asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Kaksiselitteisiä vihaan, mutta lakiasi rakastan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Sinä olet suojani ja kilpeni, sanaasi panen toivoni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Luopukaa minusta, te pahantekijät, tahdon ottaa vaarin Jumalani käskyistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Tue minua lupauksesi mukaan, että eläisin, äläkä anna minun joutua häpeään toivossani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Vahvista minua, että pelastuisin, niin pidän alati käskysi mielessäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Sinä hylkäät kaikki, jotka eksyvät käskyistäsi, sillä heidän kavaluutensa on pettävää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Kaikki maan jumalattomat sinä heität pois kuin kuonan. Sen tähden rakastan todistuksiasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Ruumiini värisee pelottavuutesi tähden, ja pelkään tuomioitasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Teen oikeuden ja vanhurskauden, älä jätä minua sortajieni käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Ole palvelijasi puolustaja hänen parhaakseen äläkä salli julkeiden minua sortaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Silmäni ikävöivät kaiholla autuuttasi ja vanhurskaita lupauksiasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Tee palvelijallesi armosi mukaan ja opeta minulle käskysi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Minä olen palvelijasi, anna minulle ymmärrystä, että tuntisin todistuksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Herran on aika toimia: he ovat rikkoneet lakisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Sen tähden rakastan käskyjäsi enemmän kuin kultaa, enemmän kuin puhtainta kultaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Sen tähden vaellan kaikessa suoraan, kaikkien asetuksiesi mukaan, ja vihaan kaikkia valheen polkuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Ihmeelliset ovat todistuksesi, sen tähden sieluni ottaa niistä vaarin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Kun sanasi avautuvat, ne valaisevat ja antavat yksinkertaiselle ymmärrystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Avaan suuni ja huokailen, sillä ikävöin käskyjäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Käänny puoleeni, ole minulle armollinen, kuten on oikein niitä kohtaan, jotka nimeäsi rakastavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Tee askeleeni vakaviksi sanallasi äläkä salli minkään vääryyden minua hallita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Vapauta minut ihmisten sorrosta, niin noudatan asetuksiasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Kirkasta kasvosi palvelijallesi ja opeta minulle käskysi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Silmistäni vuotavat kyynelvirrat, kun lakiasi ei noudateta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Sinä olet vanhurskas, Herra, ja tuomiosi ovat oikeat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Olet säätänyt todistuksesi vanhurskaudessa ja suuressa uskollisuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Kiivauteni kuluttaa minut, sillä vihamieheni unohtavat sanasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Sanasi on hyvin koeteltu, ja palvelijasi rakastaa sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Minä olen vähäinen ja halveksittu, mutta en unohda asetuksiasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Vanhurskautesi on iankaikkinen vanhurskaus, ja lakisi on totuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Hätä ja ahdistus ovat minut saavuttaneet, mutta käskysi ovat iloni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Todistuksesi ovat iankaikkisesti vanhurskaat. Anna minulle ymmärrystä, niin elän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Kaikesta sydämestäni huudan. Vastaa minulle, Herra. Tahdon ottaa käskyistäsi vaarin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Huudan sinua, pelasta minut, niin noudatan todistuksiasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Jo ennen aamun valkenemista huudan, sinun sanoihisi panen toivoni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Jo ennen yön vartiohetkiä silmäni tutkivat puhettasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Kuule ääneni armosi mukaan, Herra, ja virvoita minua oikeutesi mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Lähellä ovat ilkeät vainoojat, jotka ovat kaukana laistasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Sinä, Herra olet lähellä, ja kaikki käskysi ovat totuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Jo kauan olen tiennyt todistuksistasi, että olet ne perustanut iäti pysyviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Katso kurjuuttani ja pelasta minut, sillä lakiasi en unohda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Aja asiani ja lunasta minut, virvoita minua lupauksesi mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Kaukana on autuus jumalattomista, sillä he eivät kysy käskyjäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Herra, armahtavaisuutesi on suuri, virvoita minua oikeutesi mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Monta minulla on vainoajaa ja vihamiestä, mutta todistuksistasi en poikkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Näen uskottomat, ja minua iljettää, sillä he eivät noudata sanaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Huomaa, että rakastan asetuksiasi. Herra, virvoita minua armosi mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Sinun sanasi on kokonaan totuus, ja kaikki sinun vanhurskautesi oikeudet pysyvät iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Ruhtinaat vainoavat minua syyttä, mutta sydämeni pelkää sanojasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Riemuitsen puheestasi kuin suuren saaliin saanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Valhetta vihaan ja inhoan, mutta lakiasi rakastan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Seitsemästi päivässä ylistän sinua vanhurskautesi oikeuksien tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Suuri rauha on niillä, jotka rakastavat lakiasi, eikä heille tule kompastusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Odotan autuuttasi, Herra, ja täytän käskysi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Sieluni noudattaa todistuksiasi, ja rakastan niitä hyvin paljon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Noudatan asetuksiasi ja todistuksiasi, sillä kaikki tieni ovat edessäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Herra, suo valitukseni tulla kasvojesi eteen, anna minulle ymmärrystä sanasi mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Tulkoon anomiseni kasvojesi eteen, pelasta minut sanasi mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Vuodattakoot huuleni ylistystä, sillä opetat minulle käskysi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Kieleni veisatkoon sanastasi, sillä kaikki käskysi ovat vanhurskaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Kätesi olkoon apuni, sillä olen valinnut asetuksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Ikävöin autuuttasi, Herra, ja lakisi on iloni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Saakoon sieluni elää ja ylistää sinua, ja oikeutesi minua auttakoot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Olen eksynyt kuin kadonnut lammas. Etsi palvelijaasi, sillä en unohda käskyjäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Matkalaulu. Ahdistuksessani huudan Herraa, ja hän vastaa minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Herra, pelasta sieluni valheellisista huulista ja petollisesta kielestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Mitä petollinen kieli voi antaa sinulle ja mitä siihen vielä lisätä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Väkivaltaisen teräviä nuolia sekä kinsteripensaan tulisia hiiliä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Voi minua, että minun täytyy oleskella muukalaisena Mesekissä, asua Keedarin telttojen keskellä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Kauan on sieluni täytynyt asua niiden seurassa, jotka vihaavat rauhaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Minä olen rauhan ihminen, mutta jos puhun, he nostavat sodan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Matkalaulu. Nostan silmäni vuoria kohti: mistä tulee minulle apu?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Apu minulle tulee Herralta, joka on tehnyt taivaan ja maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Hän ei salli jalkasi horjua, varjelijasi ei torku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Katso, hän, joka Israelia varjelee, ei torku eikä nuku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Herra on varjelijasi, Herra on suojaava varjosi oikealla puolellasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Aurinko ei vaivaa sinua päivällä, eikä kuu yöllä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Herra varjelee sinut kaikesta pahasta, hän varjelee sielusi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Herra varjelee lähtemisesi ja tulemisesi, nyt ja aina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Matkalaulu. Daavidin kirjoittama. Minä iloitsin, kun minulle sanottiin: \"Menkäämme Herran huoneeseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Jalkamme saavat seisoa sinun porteissasi, Jerusalem,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'sinä Jerusalem, rakennettu kaupungiksi, johon kokoonnutaan yhteen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'jonne sukukunnat vaeltavat, Herran sukukunnat, kuten Israelille on säädetty, kiittämään Herran nimeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Sillä siellä ovat tuomioistuimet, Daavidin huoneen istuimet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Toivottakaa rauhaa Jerusalemille. Menestykööt ne, jotka sinua rakastavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Rauha olkoon muuriesi sisällä ja onni linnoissasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Veljieni ja ystävieni tähden sanon: olkoon sinulla rauha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Herran, Jumalamme, huoneen tähden tahdon etsiä parastasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Matkalaulu. Nostan silmäni sinun puoleesi, joka asut taivaissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Katso, kuin palvelijoiden silmät katsovat heidän isäntiensä käsiin, ja kuin palvelijattaren silmät katsovat hänen emäntänsä käsiin, niin silmämme katsovat Herran, Jumalamme, puoleen, kunnes hän armahtaa meitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Ole meille armollinen, Herra, ole meille armollinen. Sillä kylliksi olemme jo saaneet halveksuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Sielumme on jo saanut tarpeekseen suruttomien pilkasta, ylpeitten halveksunnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Matkalaulu. Daavidin kirjoittama. Ellei Herra olisi kanssamme – näin sanokoon Israel –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'ellei Herra olisi kanssamme, kun ihmiset nousevat meitä vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'he nielisivät meidät elävältä, kun heidän vihansa syttyy meitä vastaan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'vedet upottaisivat meidät, virta tulvisi sielumme yli;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'vedet tulvisivat sielumme yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Kiitetty olkoon Herra, joka ei antanut meitä heidän hammastensa raadeltaviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Sielumme pääsi kuin lintu pyydystäjien paulasta: paula katkesi, ja me pääsimme pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Apumme on Herran nimi, hänen, joka on tehnyt taivaan ja maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Matkalaulu. Jotka Herraan turvaavat, ovat kuin Siionin vuori: se ei horju, vaan pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Vuoret ympäröivät Jerusalemia, ja Herra ympäröi kansaansa, nyt ja iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Sillä jumalattomuuden valtikka ei saa vallita vanhurskasten arpaosaa, jotta vanhurskaat eivät ojentaisi käsiään vääryyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Herra, tee hyvää sydämeltään hyville ja oikeamielisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Mutta ne, jotka poikkeavat mutkaisille teilleen, Herra hukuttakoon yhdessä väärintekijöiden kanssa. Rauha Israelille!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Matkalaulu. Kun Herra palautti Siionin vangitut, olimme kuin unta näkeviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Silloin oli suumme naurua täynnä, ja kielemme riemua täynnä; silloin sanottiin pakanoiden keskuudessa: \" Herra on tehnyt suuria heitä kohtaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Niin, Herra on tehnyt suuria meitä kohtaan. Siitä iloitsemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Herra, käännä vankeutemme kuin purot Negevissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Ne, jotka kyynelin kylvävät, riemuiten leikkaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'He menevät itkien, kun kylvösiemenen vievät. He palaavat riemuiten, kun lyhteensä tuovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Matkalaulu. Salomon kirjoittama. Jos Herra ei huonetta rakenna, turhaan sen rakentajat näkevät vaivaa. Jos Herra ei kaupunkia varjele, turhaan vartija valvoo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Turhaan te nousette varhain ja myöhään menette levolle ja syötte leipänne murheella: Yhtä hyvin hän antaa ystävilleen heidän nukkuessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Katso, lapset ovat Herran lahja, ja kohdun hedelmä on anti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Kuin nuolet sankarin kädessä ovat nuoruuden pojat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Onnellinen se mies, jonka viini on niitä täynnä! He eivät joudu häpeään, kun puhuttelevat portissa vihamiehiään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Matkalaulu. Autuas on jokainen, joka pelkää Herraa, joka vaeltaa hänen teillään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Sinä syöt kättesi ansion. Olet onnellinen, omanasi on hyvä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Kuin hedelmällinen viiniköynnös on vaimosi huoneesi perällä, kuin öljypuun vesat ovat lapsesi pöytäsi ympärillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Sillä katso, näin siunataan miestä, joka Herraa pelkää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Siunatkoon Herra sinua Siionista, että näet kaikkina elinpäivinäsi Jerusalemin onnellisena ja');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'näet lastesi lapset. Rauha Israelille!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Matkalaulu. He ovat ahdistaneet minua paljon nuoruudestani asti – näin sanokoon Israel –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'he ovat ahdistaneet minua paljon nuoruudestani asti, mutta he eivät ole päässeet minusta voitolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Kyntäjät ovat selkääni kyntäneet ja vetäneet siihen pitkät vaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Mutta Herra on vanhurskas, hän on katkonut jumalattomien köydet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Joutukoot häpeään ja kääntykööt takaisin kaikki Siionin vihamiehet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Olkoot he kuin ruoho katoilla, joka kuivuu ennen korrelle puhkeamistaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'josta ei leikkaaja täytä kättänsä eikä lyhteen sitoja syliään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'Älkööt ohikulkijat sanoko: \" Herran siunaus tulkoon teille. Siunaamme teitä Herran nimeen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Matkalaulu. Syvyydestä huudan sinua, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Herra, kuule ääneni. Tarkatkoot korvasi rukousteni ääntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Jos sinä, Herra, pidät mielessäsi synnit, Herra, kuka silloin kestää?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Mutta sinun luonasi on anteeksiantamus, että sinua pelättäisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Odotan Herraa, sieluni odottaa, ja panen toivoni hänen sanaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Sieluni odottaa Herraa hartaammin kuin vartijat aamua, kuin vartijat aamua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Pane toivosi Herraan, Israel. Sillä Herran luona on armo, runsas lunastus hänen luonaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'ja hän lunastaa Israelin kaikista sen synneistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Matkalaulu; Daavidin kirjoittama. Herra, sydämeni ei ole ylpeä, silmäni eivät ole korskeat, enkä tavoittele asioita, jotka ovat minulle kovin suuria ja käsittämättömiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Totisesti, olen rauhoittanut ja tyynnyttänyt sieluni. Kuin äidin rinnoilta vieroitettu lapsi, kuin vieroitettu lapsi, niin on sieluni minussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Pane toivosi Herraan, Israel, nyt ja iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Matkalaulu. Muista, Herra, Daavidin hyväksi kaikkia hänen vaivojaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'hänen, joka vannoi valan Herralle ja teki lupauksen Jaakobin Väkevälle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, '\"En mene telttaan, joka on kotini, enkä nouse vuoteeseeni, joka on leposijani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'en suo silmilleni unta enkä silmäluomilleni lepoa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'ennen kuin löydän paikan Herralle, asumuksen Jaakobin Väkevälle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Katso, kuulimme sen olevan Efratassa, löysimme sen Jaarin kedoilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Menkäämme hänen asumukseensa, kumartukaamme hänen jalkojensa astinlaudan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Nouse, Herra, leposijaasi, sinä ja väkevyytesi arkki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Pappisi olkoot puetut vanhurskauteen, ja pyhäsi riemuitkoot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Palvelijasi Daavidin tähden älä käännä pois voideltusi kasvoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Herra on vannonut Daavidille totisen valan, jota hän ei peruuta: \"Ruumiisi hedelmän asetan valtaistuimellesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Jos poikasi pitävät liittoni ja todistukseni, jotka heille opetan, niin heidänkin poikansa saavat istua valtaistuimellasi iankaikkisesti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Sillä Herra on valinnut Siionin, halunnut sen asunnokseen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, '\"Tämä on leposijani iankaikkisesti. Tässä asun, sillä tänne on ollut haluni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Siionin ravinnon runsaasti siunaan, ruokin sen köyhät leivällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Sen papit puetan autuuteen, ja sen pyhät riemuiten riemuitkoot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Siellä annan yletä Daavidille sarven, sytytän voidellulleni lampun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Hänen vihollisensa puetan häpeään, mutta hänen päässään loistaa hänen kruununsa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Matkalaulu; Daavidin kirjoittama. Katso, kuinka hyvää ja suloista on, että veljekset sovussa asuvat!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Se on kuin kallis öljy pään päällä, jota valuu partaan – Aaronin partaan, jota valuu hänen viittansa liepeille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'Se on kuin Hermonin kaste, joka valuu Siionin vuorille. Sillä sinne on Herra säätänyt siunauksen, elämän, ikuisiksi ajoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Matkalaulu. Katso, kiittäkää Herraa, kaikki te Herran palvelijat, jotka öisin seisotte Herran huoneessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Kohottakaa kätenne pyhäkköön päin ja kiittäkää Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Herra siunatkoon sinua Siionista, hän, joka on tehnyt taivaan ja maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Halleluja! Ylistäkää Herran nimeä. Ylistäkää, te Herran palvelijat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'jotka seisotte Herran huoneessa, Jumalamme huoneen esikartanoissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Ylistäkää Herraa, sillä Herra on hyvä, veisatkaa kiitosta hänen nimelleen, sillä se on suloinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Sillä Herra on valinnut Jaakobin omakseen, Israelin omaisuudekseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Sillä minä tiedän, että Herra on suuri, ja meidän Herramme on korkeampi kaikkia jumalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Kaiken, mikä Herralle on mieleen, hän tekee, sekä taivaassa että maassa, merissä ja kaikissa syvyyksissä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'hän, joka nostaa pilvet maan ääristä, tekee salamat ja sateen ja tuo tuulen sen säilytyspaikoista;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'hän, joka surmasi Egyptin esikoiset, sekä ihmisten että eläinten;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'hän, joka lähetti tunnusteot ja ihmeet keskellesi, Egyptiä, faraota ja kaikkia hänen palvelijoitaan vastaan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'hän, joka kukisti suuret kansat ja tuotti surman väkeville kuninkaille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Siihonille, amorilaisten kuninkaalle, ja Oogille, Baasanin kuninkaalle, ja kaikille Kanaanin valtakunnille');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'ja antoi heidän maansa perintöosaksi, perintöosaksi kansalleen Israelille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Herra, nimesi pysyy iankaikkisesti, Herra, muistosi polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Sillä Herra hankkii oikeuden kansalleen ja armahtaa palvelijoitaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Pakanoiden epäjumalat ovat hopeaa ja kultaa, ihmiskätten tekoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Niillä on suu, mutta ne eivät puhu. Niillä on silmät, mutta ne eivät näe,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'niillä on korvat, mutta ne eivät kuule, eikä niiden suussa ole henkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Niiden kaltaisia ovat niiden tekijät ja kaikki, jotka niihin turvaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Te, Israelin suku, kiittäkää Herraa, te, Aaronin suku, kiittäkää Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Te, Leevin suku, kiittäkää Herraa, te, Herraa pelkäävät, kiittäkää Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Kohotkoon Herralle kiitos Siionista, hänelle, joka Jerusalemissa asuu. Halleluja!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Kiittäkää jumalien Jumalaa, sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Kiittäkää herrojen Herraa, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'häntä, joka yksin tekee suuria ihmeitä, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'häntä, joka on taidolla tehnyt taivaat, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'häntä, joka on vetten yli levittänyt maan, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'häntä, joka on tehnyt suuret valot, sillä hänen armonsa pysyy iankaikkisesti:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'auringon hallitsemaan päivää, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'kuun ja tähdet hallitsemaan yötä, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'häntä, joka löi Egyptiä surmaten sen esikoiset, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'ja vei Israelin pois heidän keskeltään, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'väkevällä kädellä ja ojennetulla käsivarrella, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'häntä, joka jakoi Kaislameren kahtia, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'ja kuljetti Israelin sen keskitse, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'ja syöksi faraon sotajoukkoineen Kaislamereen, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'häntä, joka johdatti kansaansa erämaassa, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'häntä, joka voitti suuret kuninkaat, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'ja surmasi mahtavat kuninkaat, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Siihonin, amorilaisten kuninkaan, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'ja Oogin, Baasanin kuninkaan, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'ja antoi heidän maansa perintöosaksi, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'perintöosaksi palvelijalleen Israelille, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'häntä, joka muisti meitä alennuksessamme, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'ja kirvoitti meidät vihollisistamme, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'häntä, joka antaa ravinnon kaikelle lihalle, sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Kiittäkää taivaan Jumalaa, sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Baabelin virtojen rannoilla – siellä istuimme ja itkimme, kun Siionia muistelimme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Pajuihin, joita siellä oli, ripustimme lyyramme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Sillä vangitsijamme vaativat meiltä siellä lauluja ja orjuuttajamme iloa: \"Veisatkaa meille Siionin virsiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Kuinka voisimme veisata Herran virsiä vieraalla maalla?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Jos unohdan sinut, Jerusalem, unohda oikea käteni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Tarttukoon kieleni suuni lakeen, ellen sinua muista, ellen pidä Jerusalemia ylimpänä ilonani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Muista, Herra, Jerusalemin tuhopäivä, kosta se Edomin lapsille, jotka sanoivat: \"Hajottakaa se, hajottakaa perustuksia myöten!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Tytär Baabel, sinä häviöön tuomittu, autuas se, joka sinulle kostaa tekosi, minkä olet meille tehnyt!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Autuas se, joka ottaa pienet lapsesi ja murskaa heidät kallioon!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Daavidin kirjoittama. Kiitän sinua kaikesta sydämestäni, veisaan kiitostasi jumalien edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Rukoilen sinua kumartuneena pyhään temppeliisi päin ja kiitän nimeäsi armosi ja totuutesi tähden, sillä olet sanallasi tehnyt nimesi suureksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'Sinä päivänä, jona huusin, vastasit minulle. Rohkaisit minua, ja sieluni sai voimaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Herra, kaikki maan kuninkaat ylistävät sinua, kun kuulevat suusi sanat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'ja he veisaavat Herran teistä, sillä suuri on Herran kunnia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Sillä vaikka Herra on korkea, hän katsoo alhaisen puoleen, mutta ylpeän hän tuntee kaukaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Vaikka vaellan ahdistuksen keskellä, virvoitat minut. Ojennat kätesi vihamiesteni vihaa vastaan, ja oikea kätesi auttaa minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Herra vie asiani päätökseen. Herra, armosi pysyy iankaikkisesti. Älä jätä kesken kättesi työtä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Veisuunjohtajalle; Daavidin psalmi. Herra, [sinä] tutkit minut ja tunnet minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Istun tai nousen, sinä sen tiedät. [Sinä] ymmärrät ajatukseni kaukaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Käyn tai makaan, sen havaitset, ja kaikki tieni ovat sinulle tutut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Sillä, katso, ei ole sanaa kielelläni, jota sinä, Herra, et täysin tunne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Olet saartanut minut edestä ja takaa ja laskenut kätesi päälleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Sellainen tieto on minulle kovin ihmeellinen, sangen korkea käsittääkseni sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Minne voisin mennä, missä ei Henkesi olisi, minne paeta kasvojesi edestä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Jos taivaaseen nousisin, sinä olet siellä; jos helvettiin vuoteeni tekisin, niin katso, olet siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Jos kohoaisin aamuruskon siivillä ja asettuisin asumaan meren ääriin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'sielläkin kätesi minua taluttaisi, oikea kätesi tarttuisi minuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Mutta jos sanoisin: \"Peittäköön minut pimeys, ja valkeus minun ympärilläni tulkoon yöksi\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'pimeyskään ei olisi sinulle pimeä: yö valaisisi kuin päivä, pimeys olisi kuin valkeus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Sillä sinä olet luonut munuaiseni, kudoit minut kokoon äitini kohdussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Kiitän sinua siitä, että olen tehty hyvin ihmeellisesti. Ihmeelliset ovat tekosi, sen sieluni kyllä tietää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Luuni eivät olleet sinulta salatut, kun minut salassa valmistettiin, kun minut taiten tehtiin maan syvyyksissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Silmäsi näkivät minut jo idussani. Päiväni olivat määrätyt ja kirjoitetut kaikki kirjaasi jo ennen, kuin ainoakaan niistä oli tullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Mutta kuinka kalliit ovat minulle sinun ajatuksesi, Jumala, kuinka suuri on niiden luku!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Jos tahtoisin ne lukea, niitä olisi enemmän kuin hiekan jyviä. – Herään ja olen vielä luonasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Jumala, jospa surmaisit jumalattomat! Mutta te, murhamiehet, väistykää minusta pois!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Sillä he puhuvat sinusta petollisesti ja lausuvat turhaan nimesi – nuo sinun vihollisesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Herra, enkö vihaisi niitä, jotka sinua vihaavat, enkö inhoaisi niitä, jotka sinua vastustavat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Kaikella vihalla heitä vihaan, he ovat omia vihollisiani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Tutki minua, Jumala, ja tunne sydämeni, koettele minua, tunne ajatukseni');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'ja katso: jos tieni on vaivaan vievä, johdata minut iankaikkiselle tielle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Veisuunjohtajalle. Daavidin psalmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Päästä minut, Herra, pahoista ihmisistä, varjele minut väkivaltaisilta miehiltä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'jotka ajattelevat sydämessään pahaa ja joka päivä yllyttävät sotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'He hiovat kielensä kuin käärmeet. Kyykäärmeen myrkkyä on heidän huultensa alla. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Suojaa minut, Herra, jumalattomien käsiltä, varjele minut väkivaltaisilta miehiltä, jotka tahtovat saada jalkani lankeamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Nuo ylpeät virittävät minulle ansoja ja pauloja, levittävät verkkoja tielleni, asettavat minulle pyydyksiä. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Minä sanon Herralle: \"Sinä olet minun Jumalani.\" Herra, ota korviisi rukousteni ääni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Herra, Herra, vahva apuni, [sinä] suojaat pääni taistelun päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Herra, älä salli, mitä jumalattomat haluavat, älä anna heidän aikeittensa onnistua. Muuten he ylvästelevät. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Sattukoon saartajieni omaan päähän onnettomuus, jota heidän huulensa hankkivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Tulkoon tulisia hiiliä heidän päälleen. Hän syösköön heidät tuleen, vesivirtoihin, joista he älkööt nousko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Suulas mies ei pysy vahvana maassa. Väkivaltaista ajaa onnettomuus, ja se iskemällä iskee häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Tiedän, että Herra ajaa kurjan asian ja hankkii köyhille oikeuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 14, 'Totisesti, vanhurskaat saavat kiittää nimeäsi, ja oikeamieliset saavat asua kasvojesi edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Daavidin virsi. Herra, huudan sinua, riennä luokseni. Ota korviisi ääneni, kun sinua avuksi huudan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Rukoukseni olkoon suitsutusuhri kasvojesi edessä. Kätteni kohottaminen rukoukseen olkoon iltauhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Herra, pane suulleni vartija ja vartioi huulteni ovea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Älä salli sydämeni taipua pahaan, pitämään jumalatonta menoa väärintekijöiden kanssa. En tahdo syödä heidän herkkupalojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Lyököön minua vanhurskas lempeydellä. Kurittakoon hän minua. Se on öljyä päähäni. Siitä älköön pääni kieltäytykö. Sillä vielä vähän aikaa, niin rukoukseni täyttyy, mutta heidän käy huonosti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Heidän päämiehensä syöstään kalliolta alas, ja silloin kuullaan minun sanani suloisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Kuin maa kynnetään ja kuokitaan, niin luumme ovat hajotettuina haudan suulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Mutta sinuun, Herra, Herra, silmäni katsovat, sinuun turvaan. Älä hylkää sieluani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Varjele minua niiden pauloista, jotka minua pyydystävät, väärintekijöiden ansoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Kaatukoot kaikki jumalattomat omiin kuoppiinsa, mutta suo minun välttää ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Daavidin mietevirsi, hänen ollessaan luolassa. Rukous.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Korotan ääneni ja huudan Herraa, Korotan ääneni ja rukoilen Herralta armoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Vuodatan hänen eteensä valitukseni ja kerron hänelle ahdistukseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Kun henkeni minussa nääntyy, sinä tunnet tieni. Polulle, jota käyn, he ovat virittäneet paulan eteeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Katso oikealle puolelleni ja näe: kukaan ei minua tunne. Minulla ei ole pakopaikkaa, eikä kukaan välitä sielustani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Huudan puoleesi, Herra. Sanon: Sinä olet turvani ja osani elävien maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Tarkkaa huutoani, sillä olen sangen viheliäinen, pelasta minut vainoojistani, sillä he ovat minua väkevämmät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 8, 'Vie sieluni ulos vankilasta kiittämään nimeäsi. Vanhurskaat kokoontuvat ympärilleni, kun teet minulle hyvin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Daavidin psalmi. Herra, kuule rukoukseni, ota korviisi anomiseni. Vastaa minulle uskollisuudessasi ja vanhurskaudessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Älä käy tuomiolle palvelijasi kanssa, sillä yksikään elävä ei ole vanhurskas edessäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Sillä vihollinen vainoaa sieluani. Hän on ruhjonut elämäni maahan ja pannut minut pimeään kuin muinoin kuolleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Henkeni on minussa ahdistunut, ja sydämeni jähmettyy rinnassani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Muistelen entisiä päiviä, tutkin kaikkia töitäsi ja ajattelen kättesi tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Levitän käteni puoleesi. Kuin kuiva maa sieluni janoaa sinua. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Vastaa minulle pian, Herra, henkeni nääntyy. Älä peitä minulta kasvojasi, etten tulisi niiden kaltaiseksi, jotka vaipuvat hautaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Suo minun varhain kuulla armoasi, sillä turvaan sinuun. Osoita minulle tie, jota minun tulee kulkea, sillä sinun luoksesi ylennän sieluni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Pelasta minut vihollisistani, Herra. [Sinä] minut suojaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Opeta minut tekemään sitä, mikä sinulle kelpaa, sillä sinä olet Jumalani. Sinun hyvä Henkesi johdattakoon minua tasaista maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Herra, virvoita minua nimesi tähden, ja vanhurskaudessasi auta sieluni ahdistuksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'Tuhoa viholliseni armosi tähden ja hukuta kaikki, jotka sieluani ahdistavat, sillä minä olen palvelijasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Daavidin kirjoittama. Kiitetty olkoon Herra, kallioni, joka opettaa käteni taistelemaan ja sormeni sotimaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'hän, joka antaa minulle armon, hän, linnani, varustukseni ja pelastajani, hän, kilpeni, jonka turviin pakenen, hän, joka laskee kansani valtani alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Herra, mikä on ihminen, että pidät hänestä lukua, mikä ihmisen poika, että häntä ajattelet!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Kuin tuulen henkäys on ihminen, kuin pakeneva varjo ovat hänen päivänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Herra, notkista taivaasi ja astu alas, kosketa vuoria, niin että ne suitsuavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Iske salamoita ja hajota heidät, lennätä nuolesi ja kauhistuta heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Ojenna kätesi korkeudesta, tempaa ja pelasta minut suurista vesistä, muukalaisten kädestä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'joiden suu puhuu vilppiä ja joiden oikea käsi on valheen käsi!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Jumala, minä veisaan sinulle uuden virren, soitan sinulle kymmenkielisellä harpulla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'sinulle, joka annat kuninkaille voiton ja tempaat palvelijasi Daavidin turvaan pahalta miekalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Tempaa ja pelasta minut muukalaisten käsistä, niiden, joiden suu puhuu vilppiä ja joiden oikea käsi on valheen käsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Silloin poikamme ovat nuoruudessaan kuin korkealle kohoavat kasvit, tyttäremme kuin temppelin veistetyt kulmapatsaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Aittamme ovat täynnä ja antavat kaikenlaista viljaa. Lampaamme lisääntyvät laitumillamme tuhansin ja kymmenin tuhansin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Härkiemme kuormat ovat runsaat. Muurissa ei ole aukkoa, ei ole pakolaista, eikä kuulu valitushuutoa kaduillamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Autuas se kansa, jolle näin käy. Autuas se kansa, jonka Jumala Herra on!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Daavidin kirjoittama ylistysvirsi. Kunnioitan sinua, Jumalani, sinä kuningas, ja kiitän nimeäsi aina ja iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Joka päivä kiitän sinua ja ylistän nimeäsi aina ja iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Suuri on Herra ja sangen ylistettävä, ja hänen suuruutensa on tutkimaton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Sukupolvi ylistää sukupolvelle tekojasi, ja he julistavat voimallisia töitäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Valtasuuruutesi kirkkautta ja kunniaa ja ihmeellisiä tekojasi tahdon tutkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Pelättävien töittesi voimasta puhutaan, suurista teoistasi kerron.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Julistettakoon suuren hyvyytesi muistoa ja riemuittakoon vanhurskaudestasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Herra on armahtavainen ja laupias, pitkämielinen ja suuri armossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Herra on hyvä kaikille ja armahtaa kaikkia tekojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Kaikki tekosi ylistävät sinua, Herra, ja pyhäsi kiittävät sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'He puhuvat valtakuntasi kunniasta ja kertovat voimastasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'He ilmoittavat ihmislapsille hänen voimalliset tekonsa ja hänen valtakuntansa kirkkauden ja kunnian.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Valtakuntasi on iankaikkinen valtakunta, ja valtiutesi pysyy polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Herra tukee kaikkia kaatuvia, ja kaikki sorronalaiset hän nostaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Kaikkien silmät katsovat sinuun, ja sinä annat heille heidän ruokansa ajallaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Sinä avaat kätesi ja ravitset suosiollasi kaikki, jotka elävät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Herra on vanhurskas kaikilla teillään ja armollinen kaikissa teoissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Herra on lähellä kaikkia, jotka häntä avukseen huutavat, kaikkia, jotka huutavat häntä avukseen totuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Hän tekee, mitä häntä pelkäävät haluavat, hän kuulee heidän huutonsa ja auttaa heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Herra varjelee kaikkia, jotka häntä rakastavat, mutta kaikki jumalattomat hän hukuttaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Suuni lausukoon Herran ylistystä, ja kaikki liha kiittäköön hänen pyhää nimeään, aina ja iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Halleluja! Ylistä, sieluni, Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Ylistän Herraa kaiken ikäni, veisaan kiitosta Jumalalleni, niin kauan kuin elän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Älkää luottako ruhtinaihin älkääkä ihmislapseen, sillä hän ei voi auttaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Kun hänen henkensä lähtee hänestä, hän tulee maaksi jälleen. Sinä päivänä hänen hankkeensa raukeavat tyhjiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Autuas se, jonka apuna on Jaakobin Jumala, se, joka panee toivonsa Herraan Jumalaansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'häneen, joka on tehnyt taivaan ja maan, meren ja kaiken, mitä niissä on, joka pysyy uskollisena iankaikkisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'joka hankkii oikeuden sorretuille, joka antaa leivän nälkäisille. Herra vapauttaa vangitut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Herra avaa sokeiden silmät, Herra nostaa sorretut, Herra rakastaa vanhurskaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Herra varjelee muukalaiset, ottaa hoivaansa orvot ja lesket, mutta jumalattomien tien hän tekee mutkaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Herra on kuningas iankaikkisesti, sinun Jumalasi, Siion, polvesta polveen. Halleluja!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Halleluja! Hyvä on veisata kiitosta Jumalallemme. Se on suloista, ylistäminen on soveliasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Herra rakentaa Jerusalemin, hän kokoaa Israelin karkotetut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Hän parantaa ne, joilla on särjetty sydän, ja sitoo heidän haavansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Hän on määrännyt tähtien luvun ja kutsuu niitä kaikkia nimeltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Herramme on suuri, suuri voimassaan, hänen ymmärryksensä on mittaamaton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Herra ylentää nöyrät, mutta jumalattomat hän painaa maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Veisatkaa Herralle kiitosvirsi, soittakaa lyyroilla kiitosta Jumalallemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Hän peittää pilvillä taivaan ja valmistaa sateen maalle. Hän kasvattaa ruohon vuorille');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'ja antaa ruuan eläimille, korpin poikasillekin, kun ne huutavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Hänelle ei kelpaa hevosen voima, eikä hän mielisty miehen sääriin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Herra mielistyy niihin, jotka häntä pelkäävät, jotka panevat toivonsa hänen armoonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Kiitä Herraa, Jerusalem. Ylistä Jumalaasi, Siion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Sillä hän tekee lujiksi porttiesi salvat ja siunaa lapsesi keskuudessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Hän hankkii rauhan rajojesi sisälle ja ravitsee sinut parhaalla vehnällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Hän lähettää sanansa maahan, nopeasti kiitää hänen sanansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Hän antaa sataa lunta kuin villaa ja sirottelee härmää kuin tuhkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Hän heittelee rakeitaan kuin leivänmuruja. Kukapa kestää hänen pakkastaan!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Hän lähettää sanansa ja sulattaa rakeet. Hän panee tuulensa puhaltamaan, ja vedet virtaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Hän ilmoittaa sanansa Jaakobille, säädöksensä ja oikeutensa Israelille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Niin hän ei ole tehnyt yhdellekään pakanakansalle, ja hänen oikeuksiaan ne eivät tunne. Halleluja!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Halleluja! Ylistäkää Herraa taivaista, ylistäkää häntä korkeuksissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Ylistäkää häntä, kaikki hänen enkelinsä, ylistäkää häntä, kaikki hänen sotajoukkonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Ylistäkää häntä, aurinko ja kuu, ylistäkää häntä, kaikki kirkkaat tähdet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Ylistäkää häntä, te taivaitten taivaat, te vedet, jotka olette ylhäältä taivaalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Ylistäkööt ne Herran nimeä, sillä hän käski, ja ne tulivat luoduiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Hän asetti ne olemaan aina ja iankaikkisesti. Hän antoi niille lain, josta ne eivät poikkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Ylistäkää Herraa maasta, te merieläimet ja kaikki syvyydet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'tuli ja rakeet, lumi ja sumu, sinä myrskytuuli, joka panet toimeen hänen sanansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'te vuoret ja kaikki kukkulat, te hedelmäpuut ja kaikki setrit,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'te pedot ja kaikki karja, te matelijat ja siivekkäät linnut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'te maan kuninkaat ja kaikki kansakunnat, te ruhtinaat ja kaikki maan tuomarit,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'te nuorukaiset sekä neitsyet, te vanhat yhdessä nuorten kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Ylistäkööt he Herran nimeä, sillä hänen nimensä yksin on korkea, hänen valtasuuruutensa ulottuu yli maan ja taivaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Hän on korottanut sarven kansalleen, että häntä ylistäisivät kaikki hänen pyhänsä, Israelin lapset, kansa, joka on häntä lähellä. Halleluja!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Halleluja! Veisatkaa Herralle uusi virsi: ylistysvirsi hänelle pyhien seurakunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Iloitkoon Israel tekijästään, Siionin lapset riemuitkoot kuninkaastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Ylistäkööt he karkeloiden hänen nimeään, soittakoot hänelle kiitosta tamburiineilla ja lyyroilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Sillä Herra on mieltynyt kansaansa, hän kaunistaa nöyrät autuudella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Iloitkoot pyhät kunniassa ja riemuitkoot vuoteissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Jumalan ylistys on heidän suussaan, ja heidän kädessään kaksiteräinen miekka,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'että he kostaisivat pakanoille, kurittaisivat kansakuntia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'panisivat kahleisiin heidän kuninkaansa ja jalkarautoihin heidän ylhäisensä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'ja täyttäisivät heissä tuomion, joka on jo kirjoitettu. Tämä on kaikkien hänen pyhiensä kunnia. Halleluja!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Halleluja! Ylistäkää Jumalaa hänen pyhäkössään, ylistäkää häntä hänen voimansa taivaanvahvuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Ylistäkää häntä hänen voimallisista teoistaan, ylistäkää häntä hänen suuren kunniansa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Ylistäkää häntä torven pauhulla, ylistäkää häntä harpuilla ja lyyroilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Ylistäkää häntä tamburiineilla ja karkelolla, ylistäkää häntä kielisoittimilla ja huiluilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Ylistäkää häntä helisevillä symbaaleilla, ylistäkää häntä kumisevilla symbaaleilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Kaikki, joissa henki on, ylistäkää Herraa! Halleluja!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Salomon, Daavidin pojan, Israelin kuninkaan, sananlaskut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'viisauden ja kurin oppimiseksi, ymmärryksen sanojen ymmärtämiseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'taitoa tuovan kurin, vanhurskauden, oikeuden ja vilpittömyyden saamiseksi sekä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'antamaan viisautta yksinkertaisille, tietoa ja taitoa nuorille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Viisas kuulkoon ja saakoon oppia lisää, ja ymmärtäväinen hankkikoon elämänohjeita');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'ymmärtääkseen sananlaskuja ja vertauksia, viisasten sanoja ja heidän arvoituksiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Herran pelko on tiedon alku. Tyhmät pitävät halpana viisauden ja kurin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Kuule, poikani, isäsi kuritusta äläkä hylkää äitisi opetusta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'sillä ne ovat ihana seppele päähäsi ja ketjut kaulaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Poikani, jos pahantekijät sinua viekoittelevat, älä suostu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Jos he sanovat: \"Lähde mukaamme! Väijykäämme verta, vaanikaamme viatonta ilman syytä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Nielaiskaamme kuin helvetti heidät elävältä, kokonaisina kuin hautaan vaipuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Saamme kaikenlaista kallista tavaraa ja täytämme talomme saaliilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Heitä arpasi kanssamme, yhteinen kukkaro olkoon meillä kaikilla.\" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Älä lähde, poikani, samalle tielle kuin he. Pidätä jalkasi heidän poluiltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Sillä heidän jalkansa juoksevat pahuuteen ja kiiruhtavat vuodattamaan verta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Sillä turhaa on levittää verkko kaikille siivekkäille, niin että ne sen näkevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Omaa vertaan he väijyvät ja vaanivat omaa henkeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Näin käy jokaiselle, joka himoitsee toisen omaa. Se vie haltijaltaan hengen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Viisaus huutaa kadulla ja antaa äänensä kuulua toreilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'Meluisten katujen kulmissa se kutsuu, kaupungissa se lausuu sanansa porttien ovilta:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Kuinka kauan te, yksinkertaiset, rakastatte yksinkertaisuutta, kuinka kauan teillä pilkkaajilla on halu pilkkaan ja te, tyhmät, vihaatte tietoa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Kääntykää minun nuhdeltavikseni. Katso, minä vuodatan teille Henkeni ja saatan sanani tiedoksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Mutta kun kutsuin, te estelitte, kun ojensin kättäni, kukaan ei ottanut vaarin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'vaan te hylkäsitte kaikki neuvoni ettekä suostuneet nuhteisiini,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'niin minäkin nauran teidän hädällenne, pilkkaan, kun tulee se, mitä te kauhistutte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'Kun myrskynä tulee se, mitä te kauhistutte, kun hätänne saapuu tuulispäänä, kun päällenne tulee vaiva ja ahdistus,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'silloin he kutsuvat minua, mutta en vastaa, he etsivät minua, mutta eivät löydä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Koska he vihasivat tietoa, eivät valinneet Herran pelkoa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'eivätkä suostuneet neuvooni, vaan pitivät kaikkea nuhdettani halpana,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'he saavat syödä oman vaelluksensa hedelmiä ja saavat tarpeekseen omista hankkeistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Sillä yksinkertaiset tappaa heidän oma luopumuksensa, ja tyhmät tuhoaa heidän oma suruttomuutensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Mutta se, joka minua kuulee, asuu turvassa ja on rauhassa onnettomuuden kauhuilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Poikani, jos otat sanoistani vaarin ja kätket mieleesi käskyni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'niin että käännät korvasi viisaudelle ja taivutat sydämesi taitoon –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'niin, jos kutsut ymmärrystä ja ääneesi huudat taitoa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'jos haet sitä kuin hopeaa ja etsit sitä kuin aarretta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'silloin pääset ymmärtämään Herran pelon ja löydät Jumalan tuntemisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Sillä Herra antaa viisautta, hänen suustaan lähtee tieto ja taito.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Vilpittömille hänellä on tallella pelastus, kilpi suoraan vaeltaville,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'niin että hän suojaa oikeuden polut ja varjelee pyhiensä tien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Silloin ymmärrät vanhurskauden, oikeuden ja suoruuden – koko autuuden tien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Sillä viisaus tulee sydämeesi, ja tieto tulee sielullesi suloiseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'taito on sinua varjeleva ja ymmärrys on suojeleva sinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Se pelastaa sinut pahojen tiestä, miehestä, joka kavalasti puhuu,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'niistä, jotka ovat hylänneet oikeat polut vaeltaakseen pimeyden teitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'niistä, jotka iloitsevat pahanteosta, riemuitsevat kavaluudestaan, kun tekevät pahaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'joiden polut ovat mutkaisia ja jotka joutuvat harhaan teillään. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Se pelastaa sinut irstaasta naisesta, vieraasta vaimosta, joka liehakoi sanoillaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'joka on hylännyt nuoruutensa ystävän ja unohtanut Jumalansa liiton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Sillä hänen huoneensa kallistuu kohti kuolemaa, hänen tiensä vainajien luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Kukaan, joka hänen luokseen menee, ei palaa eikä saavu elämän poluille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Niin sinä vaellat autuaitten tietä ja noudatat vanhurskaitten polkuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Sillä sydämeltään suorat saavat asua maassa, ja nuhteettomat jäävät siihen jäljelle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'mutta jumalattomat hävitetään maasta, ja uskottomat reväistään siitä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Poikani, älä unohda opetustani, vaan säilyttäköön sydämesi käskyni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'sillä pitkää ikää, elinvuosia ja rauhaa ne sinulle kartuttavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Armo ja uskollisuus älkööt hylätkö sinua. Sido ne kaulaasi, kirjoita ne sydämesi tauluun,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'niin löydät suosion ja hyvän ymmärryksen Jumalan ja ihmisten silmien edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Turvaa Herraan kaikesta sydämestäsi äläkä nojaudu omaan ymmärrykseesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Tunne hänet kaikilla teilläsi, niin hän polkusi suoristaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Älä ole viisas omissa silmissäsi. Pelkää Herraa ja karta pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Se on terveellistä ruumiillesi ja virkistävää luillesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Kunnioita Herraa antamalla varoistasi ja kaiken satosi parhaimmasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'niin jyväaittasi täyttyvät runsaudella, ja nuori viini pursuu tynnyreistäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Poikani, älä pidä Herran kuritusta halpana äläkä kyllästy hänen nuhteluunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Sillä sitä, jota Herra rakastaa, hän kurittaa kuin isä poikaa, joka on hänelle rakas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Autuas se ihminen, joka on löytänyt viisauden, ihminen, joka on saanut ymmärryksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Sillä parempi on hankkia sitä kuin hopeaa, ja siitä saatu voitto on kultaa jalompi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Se on helmiä kalliimpi eivätkä mitkään kalleutesi vedä sille vertaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Pitkä ikä on sen oikeassa kädessä, vasemmassa rikkaus ja kunnia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Sen tiet ovat suloiset tiet, ja sen kaikki polut ovat rauha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Se on elämän puu niille, jotka siihen tarttuvat; onnellisia ne, jotka siitä pitävät kiinni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Herra on viisaudella perustanut maan ja vahvistanut taivaat taidolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Hänen toimestaan syvyydet kuohuivat esiin ja pilvet pisaroivat kastetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Poikani, nämä älkööt häipykö näkyvistäsi, säilytä terve viisaus ja taito,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'niin ne ovat elämä sielullesi ja kaunistus kaulaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Silloin kuljet tiesi turvallisesti etkä loukkaa jalkaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Kun menet maata, et pelkää mitään, ja maata mentyäsi on unesi makea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Pääset pelästymästä äkillisiä kauhuja ja turmiota, joka yllättää jumalattomat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Sillä sinä saat luottaa Herraan, hän varjelee jalkasi joutumasta kiinni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Älä kiellä tarvitsevalta hyvää silloin, kun Jumala on antanut sinulle siihen mahdollisuuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Älä sano lähimmäisellesi: \"Mene nyt ja tule toiste, huomenna minä annan\", kun sinulla kuitenkin on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Älä mieti pahaa lähimmäistäsi vastaan, kun hän asuu luottavasti luonasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Älä riitele kenenkään kanssa syyttä, kun toinen ei ole tehnyt sinulle pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Älä kadehdi väkivaltaista miestä äläkä valitse hänen teitään omiksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Sillä väärämielinen on Herralle kauhistus, mutta oikeamielisille hän on ystävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Herran kirous on jumalattoman huoneessa, mutta vanhurskaiden asuinsijaa hän siunaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Pilkkaajille hänkin on pilkallinen, mutta nöyrille hän antaa armon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Viisaat perivät kunnian, mutta tyhmien osa on häpeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Kuulkaa, lapset, isän kasvatusta ja kuunnelkaa oppiaksenne ymmärrystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Sillä minä annan teille hyvän opetuksen, älkää hylätkö lakiani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Olinhan minäkin isäni poika, hento ja äitini ainoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'Isä minua opetti ja sanoi minulle: \"Pitäköön sydämesi sanoistani kiinni, noudata käskyjäni, niin elät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Omista viisaus, pidä omanasi ymmärrys, älä sitä unohda, älä väisty pois suuni sanoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Älä sitä hylkää, niin se varjelee sinut. Rakasta sitä, niin se suojaa sinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Viisauden alku on: hanki viisautta, ja kaikella hankkimallasi osta ymmärrystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Anna sille korkea arvo, niin se sinut korottaa. Se kunnioittaa sinua, jos suljet sen syleilyysi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Se panee päähäsi kauniin seppeleen ja lahjoittaa sinulle kunnian kruunun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Kuule, poikani, ja ota sanani varteen, niin elämäsi vuodet enentyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Ohjaan sinut viisauden tielle, johdatan sinut suorille teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Kävellessäsi askeleesi eivät ahdista, juostessasi et kompastu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Tartu kiinni kuriin äläkä hellitä. Säilytä se, sillä se on elämäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Älä lähde jumalattomien polulle, älä astu pahojen tielle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Anna sen olla, älä mene sille, poikkea pois ja mene ohi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Sillä he eivät saa nukutuksi, elleivät tee pahaa. Se riistää heiltä unen, jos he eivät ole saaneet ketään lankeamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'He syövät leipänään jumalattomuutta ja juovat viininään väkivaltaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Mutta vanhurskasten polku on kuin aamurusko, joka kirkastuu kirkastumistaan sydänpäivään saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Jumalattomien tie on kuin pimeys. He eivät tiedä, mihin kompastuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Poikani, kuuntele sanoja, kallista korvasi kuulemaan puhettani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Älkööt ne väistykö silmistäsi, kätke ne sydämeesi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'sillä ne ovat elämä sille, joka ne löytää, ja lääke koko hänen ruumiilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Yli kaiken varottavan varjele sydämesi, sillä sieltä elämä lähtee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Poista itsestäsi suun kavaluus, ja karkota luotasi huulten vääryys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Katsokoot silmäsi suoraan, olkoon katseesi luotu eteenpäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Tasoita polku jaloillesi, ja kaikki tiesi olkoot vakaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Älä poikkea oikeaan, älä vasempaan, väistä jalkasi pahasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Poikani, kuuntele viisauttani, kallista korvasi taidolleni');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'ottaaksesi vaarin viisaudesta, ja huulesi säilyttäkööt tiedon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Sillä hunajaa pisaroivat vieraan vaimon huulet, ja hänen suunsa on öljyä liukkaampi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Mutta lopulta hän on karvas kuin koiruoho, terävä kuin kaksiteräinen miekka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Hänen jalkansa kulkevat alas kuolemaan, helvettiin vetävät hänen askeleensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Hän ei välitä elämän polusta, hänen tiensä horjuvat eikä hän sitä tiedä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Niinpä, lapset, kuulkaa minua, älkää väistykö suuni sanoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Pidä tiesi kaukana tuollaisesta äläkä lähesty hänen talonsa ovea,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'ettet antaisi muille kunniaasi etkä vuosiasi armottomalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'ettei tavarasi ravitsisi vieraita, eikä vaivannäkösi joutuisi toisen taloon');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'ja ettet lopulta päätyisi huokailemaan ruumiisi ja lihasi riutuessa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'ja sanomaan: \"Miksi vihasin kuria ja sydämeni halveksi nuhdetta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Miksi en kuullut neuvojieni ääntä, kallistanut korvaani opettajilleni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Olin joutunut vähäksi aikaa turmion omaksi seurakunnan ja sen kokouksen keskellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Juo vettä omasta säiliöstäsi, sitä, mikä omasta kaivostasi juoksee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Vuotaisivatko lähteesi kadulle, vesiojasi toreille!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Olkoot ne yksin sinun omasi, älkööt vieraitten sinun lisäksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Olkoon lähteesi siunattu, ja iloitse nuoruutesi vaimosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Armas peura, suloinen vuorikauris – hänen rintansa sinua aina riemulla ravitkoot, hurmaannu alati hänen rakkaudestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Miksi, poikani, hurmautuisit irstaaseen naiseen ja syleilisit vieraan vaimon povea?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Sillä Herran silmien edessä ovat miehen tiet, ja hän tutkii kaikki hänen polkunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Jumalattoman vangitsevat hänen rikoksensa, ja hän tarttuu oman syntinsä pauloihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Hän kuolee, koska hän hylkää kurin, ja menee harhaan suuressa hulluudessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Poikani, jos olet lähimmäistäsi taannut ja lyönyt kättä vieraalle;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'jos olet kietoutunut oman suusi sanoihin, joutunut suusi sanoista kiinni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'niin tee toki, poikani, pelastuaksesi tämä, koska olet joutunut lähimmäisesi kouriin: Mene, heittäydy maahan ja ahdista lähimmäistäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Älä suo silmillesi unta äläkä silmäluomillesi lepoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Pelastaudu käsistä kuin gaselli, kuin lintu pyydystäjän käsistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Mene, laiska, muurahaisen luo, katso sen menoa ja viisastu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Vaikka sillä ei ole ruhtinasta, ei päämiestä eikä hallitsijaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'se kuitenkin hankkii leipänsä kesällä ja kokoaa varastoon ruokansa elonaikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Kuinka kauan sinä, laiska, makaat, milloin nouset unestasi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Nuku vielä vähän aikaa, torku vähän aikaa, makaa vähän aikaa ristissä käsin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'niin köyhyys käy päällesi kuin kulkuri ja puute kuin aseistettu mies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Petollinen ihminen, epärehellinen mies on se, joka kulkee suu täynnä vilppiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'iskee silmää, antaa merkkiä jaloillaan ja viittoaa sormillaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'jolla on kavaluus sydämessä, aikoo pahaa joka aika ja rakentaa riitoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Sen tähden hänen turmionsa tulee yhtäkkiä, tuokiossa hänet rusennetaan, eikä apua ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Näitä kuutta Herra vihaa, ja seitsemää hänen sielunsa kauhistuu:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'ylpeitä silmiä, valheellista kieltä, käsiä, jotka vuodattavat viatonta verta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'sydäntä, joka miettii jumalattomia juonia, jalkoja, jotka kiiruhtavat juosten pahaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'väärää todistajaa, joka valheita puhuu, ja riidan rakentajaa veljien kesken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Säilytä, poikani, isäsi käsky äläkä hylkää äitisi opetusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Pidä ne aina sydämellesi sidottuina, kääri ne kaulasi ympärille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Kulkiessasi ne sinua taluttakoot, maatessasi sinua vartioikoot ja herätessäsi sinua puhutelkoot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Sillä käsky on lamppu, opetus on valo, ja nuhteleva kuri on elämän tie,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'että varjeltuisit pahasta naisesta, vieraan vaimon liukkaasta kielestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Älköön sydämesi himoitko hänen kauneuttaan, älköönkä hän sinua katseillaan vangitko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Sillä porttonaisen tähden menee leipäkakkukin, mutta aviovaimo pyydystää kalliin sielun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Voiko kukaan kuljettaa tulta helmassaan puvun häneltä palamatta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Voiko kukaan kävellä hiilloksella jalkojen häneltä kärventymättä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Samoin käy sen, joka menee lähimmäisensä vaimon luo. Kukaan ei jää rankaisematta, joka häneen koskee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Eikö halveksita varasta, vaikka hän olisi nälissään varastanut hengenpitimikseen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Onhan hänen, jos tavataan, seitsenkertaisesti se korvattava ja annettava kaikki talonsa varat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Joka tekee huorin naisen kanssa, on mieletön, ja se, joka niin tekee, kadottaa sielunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Hän saa vaivan ja häpeän, eikä hänen häväistystään pyyhitä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Sillä mustasukkaisuus nostaa miehen vihan, ja hän on säälimätön koston päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Ei hän huoli mistään lunastusmaksusta, eikä suostu, vaikka kuinka lahjustasi lisäät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Poikani, noudata sanojani ja kätke mieleesi käskyni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Noudata käskyjäni, niin elät, säilytä opetukseni kuin silmäteräsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Sido ne kiinni sormiisi, kirjoita ne sydämesi tauluun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Sano viisaudelle: \"Sinä olet sisareni\", kutsu ymmärrystä sukulaiseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'että varjeltuisit vieraalta naiselta, joka sanoillaan imartelee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Sillä katselin taloni ikkunasta ristikon läpi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'ja näin yksinkertaisten joukossa, havaitsin poikien seassa nuorukaisen, joka oli mieltä vailla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Hän kulki katua erään naisen kulmaukseen ja astui tielle hänen taloaan kohden');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'päivän illaksi hämärtyessä, yön aikana, pimeässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Katso, nainen tulee häntä vastaan, porton puvussa, kavala sydämeltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Hän on levoton ja hillitön, eivät pysy hänen jalkansa kotona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Milloin hän on kadulla, milloin toreilla, ja väijyy joka kulmassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Hän tarttui nuorukaiseen, suuteli häntä ja julkeasti katsoen sanoi hänelle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, '\"Minun oli uhrattava rauhanuhri, tänä päivänä olen täyttänyt lupaukseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Sen tähden lähdin ulos sinua vastaan etsiäkseni sinua, ja olen sinut löytänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Olen leposijalleni peitteitä levittänyt, kirjavaa Egyptin pellavakangasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Vuoteeseeni olen pirskotellut mirhaa, aloea ja kanelia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Tule, nauttikaamme lemmestä aamuun asti, riemuitkaamme rakkaudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Sillä mieheni ei ole kotona, hän meni matkalle kauas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Rahakukkaron hän otti mukaansa ja tulee kotiin vasta täydenkuun päiväksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Hän taivutti hänet paljolla houkuttelullaan, vietteli liukkailla huulillaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'äkkiä hän lähti hänen jälkeensä, kuin härkä menee teuraaksi, kuin hullu jalkaraudoissa kuritettavaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'kuin lintu kiiruhtaa paulaan, eikä tiennyt, että oli hengenvaarassa, kunnes nuoli lävisti hänen maksansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Sen tähden, poikani, kuulkaa minua, kuunnelkaa suuni sanoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Älköön sydämesi poiketko tuon naisen teille, älä eksy hänen poluilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Sillä paljon on surmattuja, hänen kaatamiaan, lukuisa joukko niitä, jotka kaikki hän on tappanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Hänen talostaan käyvät helvetin tiet, jotka vievät alas kuoleman kammioihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Eikö Viisaus kutsu, eikö ymmärrys anna äänensä kuulua?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Ylös kummuille, tien viereen, polkujen risteyksiin hän on asettunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'Porttien pielissä, kaupungin portilla, oviaukoissa hän huutaa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, '\"Teitä minä kutsun, miehet, ja ääneni kaikuu ihmislapsille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Tulkaa, yksinkertaiset, ymmärtäväisiksi. Tulkaa järkeviksi, te tyhmät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Kuulkaa, sillä jalosti minä puhun, ja avaan huuleni puhumaan sitä, mikä on oikein.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Sillä suuni puhuu totuutta, ja jumalattomuus on huulilleni kauhistus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Vanhurskaat ovat kaikki suuni sanat, ei ole niissä mitään petollista eikä väärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Ne ovat kaikki oikeita ymmärtäväiselle, suoria niille, jotka löysivät tiedon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Ottakaa vastaan opetukseni, älkääkä hopeaa, ja tieto ennen valituinta kultaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Sillä parempi on Viisaus kuin helmet. Mitkään kalleudet eivät vedä sille vertaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Minä, Viisaus, asun sen luona, mikä on mielekästä, olen löytänyt tiedon ja taidon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Herran pelko on pahan vihaamista. Kopeutta ja ylpeyttä, pahaa tietä ja kavalaa suuta minä vihaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Minulla on neuvo ja neuvokkuus. Minä olen ymmärrys, minulla on voima.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Minun avullani kuninkaat hallitsevat, ja ruhtinaat säätävät säädöksensä vanhurskaasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Minun avullani päämiehet ja kaikki ylhäiset sekä maan tuomarit hallitsevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Minä rakastan niitä, jotka minua rakastavat, ja ne, jotka minua varhain etsivät, löytävät minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Luonani on rikkaus ja kunnia, ikivanha varallisuus ja vanhurskaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Hedelmäni on parempi kuin kulta, kuin puhtain kulta, ja antamani voitto on valituinta hopeaa parempi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Minä vaellan vanhurskauden polkua, oikeuden teitten keskikohtaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'antaakseni niille, jotka minua rakastavat, pysyvän perinnön ja täyttääkseni heidän aarrekammionsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Herra omisti minut tiensä alussa, ennen hänen tekojaan, ennen aikojen alkua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Iankaikkisuudesta minut on asetettu olemaan, alusta asti, ennen kuin maa oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Ennen kuin syvyyksiä oli, synnyin minä, ennen kuin oli lähteitä, vedestä rikkaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Ennen kuin vuoret upotettiin paikoilleen, ennen kukkuloita minä synnyin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'kun hän ei vielä ollut tehnyt maata, ei sen kamaraa eikä maanpiirin tomujen alkuakaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Minä olin siinä, kun hän valmisti taivaat. Kun hän veti piirin syvyyden pinnalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'kun hän teki vahvoiksi pilvet korkeudessa, kun syvyyden lähteet saivat voiman,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'kun hän asetti merelle sen rajat, että vedet eivät kävisi hänen käskynsä yli, kun hän vahvisti maan perustukset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'olin mestarina hänen vierellään, ihastuksissani olin päivästä päivään ja leikin hänen edessään kaiken aikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'Leikin hänen maanpiirinsä päällä, ja ihastukseni olivat ihmislapset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Siis te, lapset, kuulkaa minua. Autuaat ne, jotka noudattavat teitäni!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Kuria kuulkaa, niin viisastutte. Älkää antako sen mennä menojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Autuas se ihminen, joka minua kuulee, valvoo ovillani päivästä päivään ja vartioi ovieni pieliä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Sillä joka minut löytää, löytää elämän ja saa Herran mielisuosion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Mutta joka menee minusta harhaan, saa vahingon sielulleen. Kaikki, jotka minua vihaavat, rakastavat kuolemaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Viisaus on talonsa rakentanut ja veistänyt seitsemän pylvästään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Hän on teurastanut teuraansa, sekoittanut viininsä ja myös kattanut pöytänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Hän on lähettänyt palvelijansa kuuluttamaan kutsua kaupungin kumpujen rinteiltä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, '\"Joka on yksinkertainen, poiketkoon tänne.\" Hän sanoo sille, joka on mieltä vailla:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, '\"Tulkaa, syökää leipääni ja juokaa viiniä, minun sekoittamaani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Hylätkää yksinkertaisuus, niin elätte, ja astukaa ymmärryksen tielle.\" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Se, joka ojentaa pilkkaajaa, saa itselleen häpeän, ja häpeätahran se, joka jumalatonta nuhtelee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Älä nuhtele pilkkaajaa, ettei hän sinua vihaisi. Nuhtele viisasta, niin hän sinua rakastaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Anna viisaalle, niin hän yhä viisastuu. Opeta vanhurskasta, niin hän kasvaa opissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Herran pelko on viisauden alku, ja Pyhimmän tunteminen on ymmärrystä. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, '\"Sillä minun avullani päiväsi enenevät ja elämäsi vuodet jatkuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Jos olet viisas, olet omaksi hyväksesi viisas. Mutta jos olet pilkkaaja, saat sen yksin kestää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Tyhmä nainen on levoton ja yksinkertainen, eikä hän tiedä mistään mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Hän istuu talonsa ovella, istuimella kaupungin kummuilla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'kutsumassa ohikulkijoita, jotka käyvät polkujansa suoraan eteenpäin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, '\"Joka on yksinkertainen, poiketkoon tänne.\" Ja sille, joka on mieltä vailla, hän sanoo:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, '\"Varastettu vesi on makeaa, ja salainen leipä on suloista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Eikä tämä tiedä, että siellä on vainajia, ja että hänen kutsumansa ovat helvetin rotkoissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Salomon sananlaskut. Viisas poika on isälleen ilo, mutta tyhmä poika on äitinsä murhe.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Vääryyden aarteet eivät auta, mutta vanhurskaus vapahtaa kuolemasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Herra ei salli vanhurskaan nähdä nälkää, mutta jumalattomien himon hän työntää luotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Se, joka laiskasti käyttää kättään, köyhtyy, mutta ahkerien käsi tuo vaurautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Taitava poika kokoaa kesällä, kunnoton poika nukkuu elonaikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Siunaus on vanhurskaan pään päällä, mutta jumalattomien suu sisältää väkivaltaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Vanhurskaan muistoa siunataan, mutta jumalattomien nimi lahoaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Viisassydäminen ottaa käskyt varteen, mutta huuliltaan tyhmä joutuu lankeemukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Se, joka nuhteettomasti vaeltaa, vaeltaa turvassa, mutta se, jonka tiet ovat väärät, joutuu ilmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Joka silmää iskee, saa aikaan tuskaa, ja huuliltaan tyhmä kukistuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Vanhurskaan suu on elämän lähde, mutta jumalattomien suu sisältää väkivaltaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Viha virittää riitoja, mutta rakkaus peittää kaikki rikokset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Ymmärtäväisen huulilta löytyy viisaus, mutta sille, joka on mieltä vailla, kuuluu antaa vitsaa selkään!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Viisaat tallettavat tiedon, mutta houkan suun lähellä on turmio.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Rikkaan vauraus on hänen vahva kaupunkinsa, mutta köyhien puute on heidän turmionsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Vanhurskaan hankkima on elämäksi, jumalattoman kokoama koituu synniksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Kuria noudattava on elämän polulla, mutta nuhteet hylkäävä eksyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Sen huulilla, joka pitää salavihaa, on valhe, ja se, joka parjausta levittää, on tyhmä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Missä on paljon sanoja, siitä ei puutu syntiä, mutta se, joka huulensa hillitsee, on taitava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Vanhurskaan kieli on valituinta hopeaa, jumalattomien äly on tyhjän veroinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Vanhurskaan huulet kaitsevat monia, mutta hullut kuolevat mielettömyyteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Herran siunaus tekee rikkaaksi eikä lisää siihen murheita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Tyhmälle on iloksi ilkityön tekeminen, mutta ymmärtäväiselle miehelle viisaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Se, mitä jumalaton pelkää, kohtaa häntä, mutta se, mitä vanhurskaat haluavat, heille annetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Tuulispään mentyä ei jumalatonta enää ole, mutta vanhurskaan perustus pysyy iäti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Mitä hapan hampaille ja savu silmille, sitä laiska lähettäjilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Herran pelko jatkaa elinpäiviä, mutta jumalattomien vuodet lyhenevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Vanhurskaiden odotus koituu iloksi, mutta jumalattomien toivo hukkuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Herran johdatus on nuhteettoman turva, mutta väärintekijäin turmio.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Vanhurskas ei ikinä horju, mutta jumalattomat eivät asuta maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Vanhurskaan suu kasvaa viisauden hedelmän, mutta kavala kieli hävitetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Vanhurskaan huulet tietävät, mikä on otollista, mutta jumalattomien suu on sulaa kavaluutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Väärä vaaka on Herralle kauhistus, mutta täysi paino on hänelle otollinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Sinne, minne ylpeys tulee, tulee häpeäkin, mutta nöyrien luona on viisaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Oikeamielisiä ohjaa heidän nuhteettomuutensa, mutta uskottomat hävittää heidän vilppinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Tavara ei auta vihan päivänä, mutta vanhurskaus pelastaa kuolemasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Nuhteettoman vanhurskaus tasoittaa hänen tiensä, mutta jumalaton sortuu jumalattomuuteensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Oikeamieliset pelastaa heidän vanhurskautensa, mutta uskottomat vangitsee heidän oma himonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Jumalattoman ihmisen kuollessa hukkuu hänen toivonsa, ja väärien toivo hukkuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Vanhurskas pelastetaan hädästä, ja jumalaton joutuu hänen sijaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Jumalaton turmelee suullaan lähimmäisensä, mutta taito on vanhurskaitten pelastus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Vanhurskaitten onnesta kaupunki iloitsee, ja jumalattomien hukkumisesta syntyy riemu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Oikeamielisten siunauksesta kaupunki kohoaa, mutta jumalattomien suu sitä hajottaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Mieltä vailla on se, joka lähimmäistään halveksii, mutta ymmärtäväinen mies on vaiti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Se, joka kulkee panettelijana, ilmaisee salaisuuden, mutta se, jolla on luotettava henki, säilyttää sanan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Siellä, missä ei ole ohjausta, sortuu kansa, mutta neuvonantajien runsaus tuo menestyksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Sen, joka vierasta takaa, käy pahoin, mutta se, joka kädenlyöntiä vihaa, on turvattu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Armollinen nainen saa kunniaa, ja valtiaat saavat rikkautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Armelias mies tekee hyvää itselleen, mutta armoton syöksee onnettomuuteen oman lihansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Jumalaton hankkii petollista voittoa, mutta se, joka vanhurskautta kylvää, saa varman palkan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Sillä vanhurskaus on elämäksi, mutta joka tavoittelee pahaa, sille se on kuolemaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Väärämieliset ovat Herralle kauhistus, mutta nuhteettomasti vaeltaviin hän mielistyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Totisesti: paha ei jää rankaisematta, mutta vanhurskaitten jälkeläiset pelastuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Kultarengas sian kärsässä on kaunis nainen, älyä vailla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Vanhurskaitten toivo vie onneen, jumalattomien toivo vihaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Toinen on antelias ja saa yhä lisää, toinen säästää yli kohtuuden ja vain köyhtyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Hyvää tekevä sielu tulee ravituksi, ja se, joka muita virvoittaa, itse kostuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Sitä, joka viljan pitää takanaan, kansa kiroaa, mutta sen pään päälle, joka antaa viljan myytäväksi, tulee siunaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Se, joka etsii hyvää, löytää suosion, mutta joka tavoittelee pahaa, sitä paha kohtaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Se, joka luottaa rikkauteensa, kukistuu, mutta vanhurskaat viheriöivät kuin lehvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Se, joka päästää talonsa rappiolle, perii tuulta, ja tyhmä joutuu viisaan orjaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Vanhurskaan hedelmä on elämän puu, ja viisas voittaa sieluja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Katso, vanhurskas saa palkkansa maan päällä, saati sitten jumalaton ja syntinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Se rakastaa tietoa, joka rakastaa kuria, mutta järjetön on se, joka vihaa nuhdetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Hyvä saa Herran mielisuosion, mutta juonittelijan hän tuomitsee syylliseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Ihminen ei kestä jumalattomuuden varassa, mutta vanhurskaitten juuri on horjumaton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Kelpo vaimo on puolisonsa kruunu, mutta kunnoton on kuin mätä hänen luissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Vanhurskaitten ajatukset ovat oikeat, jumalattomien hankkeet ovat petolliset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Jumalattomien puheet väijyvät verta, mutta oikeamieliset pelastaa heidän suunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Jumalattomat kukistuvat olemattomiin, mutta vanhurskaitten huone pysyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Ymmärryksensä mukaan miestä kiitetään, mutta kieroa halveksitaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Parempi halpa-arvoinen, jolla on palvelija, kuin rehentelijä, joka on vailla leipää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Vanhurskas tuntee, mitä hänen karjansa kaipaa, mutta jumalattomien sydän on armoton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Joka peltonsa viljelee, saa leipää kyllin, mutta tyhjän tavoittelija on mieltä vailla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Jumalaton himoitsee pahojen saalista, mutta vanhurskaitten juuri on antoisa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Huulten rikos on paha ansa, mutta vanhurskas pääsee hädästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Suunsa hedelmästä saa kyllikseen hyvää, ja ihmisen eteen palaavat hänen kättensä teot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Tyhmän tie on hänen omissa silmissään oikea, mutta joka neuvoa kuulee, on viisas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Tyhmän suuttumus tulee heti ilmi, mutta ymmärtäväinen peittää kärsimänsä häpeän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Toden puhuja lausuu oikeuden, mutta väärä todistaja pettää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Moni viskoo sanoja kuin miekanpistoja, mutta viisasten kieli on lääke.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Totuuden huulet pysyvät iäti, mutta valheen kieli vain tuokion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Niillä, jotka pahaa miettivät, on mielessä petos, mutta niille, jotka rauhaan neuvovat, tulee ilo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Turmiota ei tule vanhurskaalle, mutta jumalattomat ovat onnettomuutta täynnä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Valheelliset huulet ovat Herralle kauhistus, mutta teoissaan uskolliset ovat hänelle otolliset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Ymmärtäväinen ihminen peittää tietonsa, mutta tyhmien sydän huutaa julki mielettömyytensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Ahkerien käsi saa hallita, mutta laiska joutuu työveron alaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Huoli painaa alas miehen mielen, mutta hyvä sana sen ilahduttaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Vanhurskas opastaa lähimmäistään, mutta jumalattomat eksyttää heidän oma tiensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Laiska ei saa itselleen riistaa, mutta ahkeruus on ihmiselle kallis omaisuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Vanhurskauden polulla on elämä, eikä sen tien kulkeminen ole kuolemaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Viisas poika kuulee isän kuritusta, mutta pilkkaaja ei ota nuhdetta kuullakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Suunsa hedelmästä saa nauttia hyvää, mutta uskottomilla on halu väkivaltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Se, joka varjelee suunsa, säilyttää henkensä, mutta suulas joutuu turmioon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Laiskan sielu haluaa saamatta mitään, mutta ahkerien sielu tulee ravituksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Vanhurskas vihaa valheellista puhetta, mutta jumalattoman meno on iljettävä ja häpeällinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Vanhurskaus varjelee nuhteettomasti vaeltavan, mutta jumalattomuus syöksee syntisen kumoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Toinen on olevinaan rikas, vaikka ei omista mitään, toinen on olevinaan köyhä, vaikka hänellä on paljon rikkautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Mies saa antaa rikkautensa henkensä lunnaiksi, mutta köyhän ei tarvitse kuunnella uhkauksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Vanhurskaitten valo loistaa iloisesti, mutta jumalattomien lamppu sammuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Ylpeys tuottaa pelkkää toraa, mutta niillä, jotka ottavat neuvon varteen, on viisaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Vaivatta saatu tavara vähenee, mutta se, joka vähin erin kokoaa, saa sen karttumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Pitkä täyttymätön odotus tekee sydämen sairaaksi, mutta täyttynyt toivo on elämän puu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Se, joka sanaa halveksii, joutuu sanan pantiksi; mutta se, joka käskyä pelkää, palkitaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Viisaan opetus on elämän lähde kuoleman ansojen välttämiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Hyvä ymmärrys tuottaa suosiota, mutta uskottomien tie vie alas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Jokainen ymmärtäväinen toimii taitavasti, mutta tyhmä levittää hulluutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Jumalaton sanansaattaja lankeaa pahaan, mutta uskollinen lähetti tuo paranemisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Köyhyys ja häpeä tulevat kuria vierovalle, kunnia nuhdetta noudattavalle!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Tyydytetty halu on sielulle suloinen, pahan karttaminen tyhmille kauhistus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Vaella viisasten kanssa, niin viisastut; tyhmien toverin käy huonosti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Syntisiä vainoaa onnettomuus, mutta vanhurskaat palkitaan hyvällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Hyvä jättää perinnön lastensa lapsillekin, mutta synnintekijän vauraus talletetaan vanhurskaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Köyhien uudiskyntö antaa runsaan ruuan, mutta moni, joka ei pysy oikeudessa, tuhoutuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Se, joka vitsaansa säästää, vihaa lastaan, mutta joka häntä rakastaa, se häntä varhain kurittaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Vanhurskas saa syödä kyllikseen, mutta jumalattomien vatsa kärsii nälästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Vaimojen viisaus rakentaa talon, mutta typerä sen omin käsin purkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Se, joka vaeltaa oikein, pelkää Herraa, mutta se, jonka tiet ovat väärät, katsoo hänet ylen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'Typerän suussa on ylpeydelle vitsa, mutta viisaita vartioivat heidän huulensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Missä härkiä puuttuu, on seimi tyhjä, mutta runsas sato saadaan härkien voimasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Uskollinen todistaja ei valehtele, mutta väärä todistaja syytää suustaan valheita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Pilkkaaja etsii turhaan viisautta, mutta ymmärtäväisen on helppo saada tietoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Mene pois tyhmän luota, et tullut tuntemaan tiedon puhetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Ymmärtäväisen viisaus on pitää vaelluksesta vaarin. Tyhmien typeryys on petosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Typerät tekevät syntiä pilkaten, mutta vilpittömien kesken on mielisuosio.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Sydän tuntee oman surunsa, eikä sen iloa voi vieras jakaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Jumalattomien talo hävitetään, mutta vilpittömien telttamaja kukoistaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Miehen mielestä on oikea monikin tie, joka lopulta on kuoleman tie.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Nauraessakin voi sydän kärsiä, ja ilon lopuksi tulee murhe.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Omiin teihinsä kyllästyy se, jolla on Jumalasta luopunut sydän, mutta hyvä on tyytyväinen tiehensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Yksinkertainen uskoo joka sanan, mutta ymmärtäväinen ottaa askeleistaan vaarin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Viisas pelkää ja karttaa pahaa, mutta tyhmä on huoleton ja suruton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Pikavihainen tekee hullun tekoja, ja juonittelija joutuu vihatuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Yksinkertaiset saavat osakseen hulluuden, mutta ymmärtäväiset seppelöidään tiedolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Pahojen täytyy kumartua hyvien edessä ja jumalattomien vanhurskaan porteilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Köyhää vihaa hänen ystävänsäkin, mutta rikasta rakastavat monet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Syntiä tekee, joka lähimmäistään halveksii, mutta autuas se, joka köyhiä armahtaa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Eivätkö ne eksy, jotka aikovat pahaa? Mutta armo ja totuus niille, jotka pyrkivät hyvään!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'Kaikesta vaivannäöstä tulee hyötyä, mutta tyhjästä puheesta vain vahinkoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Viisasten kruunu on heidän rikkautensa, mutta tyhmien hulluus jää hulluudeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Uskollinen todistaja on hengen pelastaja, mutta valheiden puhuja on täynnä petosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'Herran pelossa on vahva varmuus ja turva vielä lapsillekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Herran pelko on elämän lähde kuoleman ansojen välttämiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'Kansan paljous on kuninkaan kunnia, väen vähyys ruhtinaan turmio.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Pitkämielisellä on paljon taitoa, mutta pikavihaisen osa on hulluus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Sävyisä sydän on ruumiin elämä, mutta kateus on mätä luissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Se, joka kurjaa sortaa, herjaa hänen Luojaansa, mutta se, joka köyhää armahtaa, kunnioittaa Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Jumalaton sortuu omaan pahuuteensa, mutta vanhurskaalla on turva kuollessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'Ymmärtäväisen sydämessä lepää viisaus, mutta tyhmien keskellä se tekee itsensä tiettäväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Vanhurskaus kansan korottaa, mutta synti on kansakuntien häpeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Taitava palvelija saa kuninkaan suosion, mutta kunnoton hänen vihansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Lempeä vastaus taltuttaa kiukun, mutta loukkaava sana nostaa vihan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Viisasten kieli puhuu tietoa taitavasti, mutta tyhmien suu purkaa hulluutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Herran silmät ovat joka paikassa. Ne vartioitsevat hyviä ja pahoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Sävyisä kieli on elämän puu, mutta vilpillinen kieli haavoittaa mielen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Hullu pitää halpana isänsä kasvatuksen, mutta joka nuhdetta noudattaa, tulee ymmärtäväiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Vanhurskaan talossa on suuret aarteet, mutta jumalattoman hankkima on sekasorron vallassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Viisasten huulet kylvävät tietoa, mutta tyhmien sydän ei ole sellainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Jumalattomien uhri on Herralle kauhistus, mutta oikeamielisten rukous on hänelle otollinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Jumalattoman tie on Herralle kauhistus, mutta sitä, joka tavoittelee vakavasti vanhurskautta, hän rakastaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Kuri on sille paha, joka hylkää tien, ja se, joka nuhdetta vihaa, saa osakseen kuoleman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Helvetin ja kadotuksen Herra näkee, saati sitten ihmislasten sydämet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Pilkkaaja ei pidä siitä, että häntä nuhdellaan; viisasten luo hän ei mene.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Iloinen sydän kaunistaa kasvot, mutta sydämen tuskassa mieli murtuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Ymmärtäväisen sydän etsii tietoa, mutta tyhmien suu ahmii hulluutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Kurjalle ovat pahoja kaikki päivät, mutta hyvä mieli on alituiset pidot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Parempi vähä Herran pelossa kuin paljot varat levottomuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Parempi vihannesruoka rakkaudessa kuin syöttöhärkä vihassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Kiukkuinen nostaa riidan, mutta pitkämielinen lopettaa riidan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Laiskan tiellä on orjantappuroita, mutta vilpittömien polku on raivattu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Viisas poika on isälleen iloksi, mutta tyhmä ihminen halveksii äitiään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Hulluus on ilo sille, joka on mieltä vailla, mutta ymmärtäväinen mies kulkee suoraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Hankkeet sortuvat, missä neuvonpito puuttuu; mutta ne toteutuvat, missä on runsaasti neuvonantajia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Miehellä on ilo suunsa vastauksesta; ja kuinka hyvä onkaan sana ajallaan!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Taitava käy elämän tietä ylöspäin välttääkseen helvetin, joka on alhaalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Ylpeitten huoneen Herra hajottaa, mutta lesken rajan hän vahvistaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Ilkeät juonet ovat Herralle kauhistus, mutta puhtaitten sanat ovat hänelle mieleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Väärän voiton pyytäjä hävittää talonsa, mutta se, joka lahjuksia vihaa, saa elää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Vanhurskaan sydän miettii, mitä vastata, mutta jumalattomien suu purkaa pahuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Jumalattomista on Herra kaukana, mutta vanhurskaitten rukouksen hän kuulee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Valoisa katse ilahduttaa sydämen, ja hyvä saarna voitelee luut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Korva, joka kuuntelee elämän nuhdetta, majailee viisasten keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Joka kasvatusta vieroo, pitää sielunsa halpana; mutta joka nuhdetta kuuntelee, se saa ymmärrystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Herran pelko on kuri viisauteen, ja kunnian edellä käy nöyryys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Ihminen ajattelee mielessään, mutta Herralta tulee kielelle vastaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Kaikki miehen tiet ovat hänen omissa silmissään puhtaat, mutta Herra tutkii henget.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Heitä työsi Herran haltuun, niin hankkeesi menestyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Kaiken Herra on tehnyt itseään varten, jumalattomankin onnettomuuden päiväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Jokainen ylpeä on Herralle kauhistus: totisesti, sellainen ei jää rankaisematta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Laupeudella ja uskollisuudella rikos sovitetaan, ja Herran pelolla paha vältetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Jos miehen tiet ovat Herralle otolliset, hän saattaa vihamiehetkin sovintoon hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Parempi on vähä vanhurskaudessa kuin suuret tuotot vääryydessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Ihmisen sydän miettii hänen tiensä, mutta Herra ohjaa hänen askeleensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Kuninkaan huulilla on Jumalan sana, eikä hänen suunsa petä hänen tuomitessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Puntari ja oikea vaaka ovat Herran, hänen tekoaan ovat kaikki painot kukkarossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Jumalaton teko on kuninkaille kauhistus, sillä vanhurskaudesta valtaistuin vahvistuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Vanhurskaat huulet ovat kuninkaille mieleen, ja oikein puhuvaa he rakastavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Kuninkaan viha on kuoleman sanansaattaja, mutta viisas mies sen lepyttää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'Kuninkaan kasvojen valo on elämäksi, ja hänen suosionsa on kuin keväinen sadepilvi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Parempi on hankkia viisautta kuin kultaa, ja jalompaa on hankkia ymmärrystä kuin hopeaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Vilpittömien tie välttää onnettomuuden, ja henkensä saa pitää se, joka pitää vaelluksestaan vaarin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Kopeus käy kukistumisen edellä, ja ylpeys lankeemuksen edellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Parempi nöyränä kurjien parissa kuin jakamassa saalista ylpeitten kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Se, joka johtaa viisaasti, löytää onnen, ja autuas se, joka Herraan turvaa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Sitä, jolla on viisas sydän, sanotaan ymmärtäväiseksi, ja huulten suloisuus lisää oppimista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Ymmärrys on omistajalleen elämän lähde, mutta hullujen opetus on typeryyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Viisaan sydän tekee taitavaksi hänen suunsa ja lisää oppimista hänen huuliltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Lempeät sanat ovat hunajaleipää. Ne ovat makeat sielulle ja lääkitys luille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Miehen mielestä on oikea monikin tie, joka lopulta on kuoleman tie.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Työmiehen nälkä tekee työtä hänen hyväkseen, sillä oma suu panee hänelle pakon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Kelvoton mies kaivaa toiselle onnettomuutta, ja hänen huulillaan on kuin polttava tuli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Kavala mies rakentaa riitaa, ja panettelija erottaa ystävykset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Väkivallan mies viekoittelee lähimmäisensä ja vie hänet tielle, joka ei ole hyvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Sillä, joka silmillään kyräilee, on kavaluus mielessä. Joka huulensa yhteen puristaa, toteuttaa pahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Harmaat hapset ovat kunnian kruunu, joka saadaan vanhurskauden tiellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Pitkämielinen on parempi kuin sankari, ja mielensä hillitsevä parempi kuin kaupungin valloittaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Helmassa pudistellen arpa heitetään, mutta Herralta tulee aina sen ratkaisu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Parempi kuiva kannikka rauhassa kuin talon täysi uhrilihaa riidassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Taitava palvelija hallitsee kunnotonta poikaa ja pääsee perinnönjaolle veljesten rinnalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Hopealle sulatin, kullalle uuni, mutta sydämet koettelee Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Paha kuuntelee ilkeitä huulia, ja petollinen mieli kuulee tuhon kieliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Se, joka köyhää pilkkaa, herjaa hänen luojaansa, eikä se, joka toisen onnettomuudesta iloitsee, jää rankaisematta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Vanhusten kruunu on lastenlapset, ja isät ovat lasten kunnia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Ei sovi typerälle ylevä puhe, saati ruhtinaalle valhe.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Lahjus on käyttäjänsä silmissä kallis kivi: mihin vain hän kääntyy, hän menestyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Se, joka peittää rikoksen, etsii rakkautta, mutta se, joka asioita kaivelee, erottaa ystävykset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Nuhde pystyy paremmin ymmärtäväiseen kuin sata lyöntiä tyhmään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Pelkkää pahaa hankkii kapinoitsija, mutta häntä vastaan lähetetään julma enkeli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Miehen on parempi kohdata karhu, jolta on riistetty poikaset, kuin tyhmä typeryydessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Sen kodista, joka palkitsee hyvän pahalla, ei onnettomuus väisty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Aloittaa tora on päästää vedet valloilleen. Lopeta, ennen kuin riita syttyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Kumpikin on Herralle kauhistus: se, joka julistaa syyllisen syyttömäksi, ja se, joka julistaa syyttömän syylliseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Mitä hyötyä on rahasta tyhmän käsissä? Viisauden hankkimiseen ei ole ymmärrystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'Ystävä rakastaa ainiaan ja veli syntyy varaksi hädässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Mieltä vailla on mies, joka lyö kättä ja menee toista takaamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Se, joka riitoja rakastaa, rakastaa syntiä. Se, joka ovensa korottaa, hankkii kukistumistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Väärämielinen ei löydä onnea, ja kavalakielinen suistuu onnettomuuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Tyhmä on murheeksi siittäjälleen, ja typerän isä on iloa vailla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Terveydeksi on iloinen sydän, mutta murtunut mieli kuivaa luut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Jumalaton ottaa lahjuksen vastaan toisen povelta vääristääkseen oikeuden tiet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Ymmärtäväisellä on viisaus kasvojensa edessä, mutta tyhmän silmät kiertävät maailman rantaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Tyhmä poika on isälleen suruksi ja synnyttäjälleen murheeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Ei ole oikein syyttää vanhurskasta ja lyödä ruhtinasta, joka oikein hallitsee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Se, joka hillitsee sanansa, on taitava, ja mielensä malttava on ymmärtäväinen mies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Hullukin käy viisaasta, jos on vaiti. Se, joka huulensa sulkee, on ymmärtäväinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Eriseurainen noudattaa omia halujaan. Hän asettuu kaikkea järkevää vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Tyhmällä ei ole halua ymmärrykseen, vaan hän haluaa tuoda julki oman mielensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Sinne, minne jumalaton tulee, tulee ylenkatsekin, ja häpeällisen menon mukana häväistys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Syviä vesiä ovat sanat miehen suusta. Viisauden lähde on virtaava puro.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Ei ole hyvä pitää syyllisen puolta ja vääntää syyttömän asia vääräksi oikeudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Tyhmän huulet tuovat mukanaan riidan, ja hänen suunsa kutsuu lyöntejä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Oma suu on tyhmälle turmioksi ja omat huulet ovat ansaksi hänelle itselleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Panettelijan puheet ovat kuin herkkupalat ja painuvat sydämen kammioihin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Se, joka on veltto toimessaan, on jo tuhontekijän veli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Herran nimi on vahva torni. Hurskas juoksee sinne ja saa turvan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Rikkaan vauraus on hänen vahva kaupunkinsa, ja korkean muurin kaltainen hänen mielikuvissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Kukistumisen edellä miehen sydän ylpistyy, mutta kunnian edellä käy nöyryys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'On typeryyttä, jos joku vastaa, ennen kuin on kuullut. Se koituu hänelle häpeäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Miehekäs henki on sairaan tuki, mutta kuka kantaa murtunutta henkeä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Tietoa hankkii ymmärtäväisen sydän, ja tietoa etsii viisasten korva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Lahja tekee tilaa ihmiselle ja vie hänet suurten pariin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Käräjissä on kukin ensiksi oikeassa, mutta sitten tulee hänen riitapuolensa ja ottaa hänestä selvän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Arpa asettaa riidat ja ratkaisee väkevien välit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Petetty veli on vaikeampi voittaa kuin vahva kaupunki, ja riidat ovat kuin linnan salvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Suunsa hedelmästä mies saa vatsansa kylläiseksi ja tulee ravituksi huultensa hedelmästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Kielellä on vallassaan kuolema ja elämä. Ne, jotka sitä rakastavat, saavat syödä sen hedelmää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Se, joka vaimon löysi, onnen löysi, sai Herralta mielisuosion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Köyhä puhuu pyydellen, mutta rikas vastaa tylysti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Häviökseen mies on monien ystävä, mutta on myös ystävä, veljiäkin uskollisempi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Parempi on köyhä, joka vaeltaa nuhteettomasti, kuin huuliltaan kiero, joka on vielä tyhmäkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Ilman taitoa ei ole intokaan hyväksi, ja kiirehtivän jalka astuu harhaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Ihmisen oma hulluus turmelee hänen tiensä, mutta Herralle hän sydämessään vihoittelee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Vauraus lisää paljon ystäviä, mutta köyhä joutuu ystävästään eroon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Väärä todistaja ei jää rankaisematta, eikä se, joka valheita puhuu, pelastu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Monet etsivät ylhäisen suosiota, ja kaikki ovat anteliaan ystäviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Köyhä on kaikkien veljiensä vihaama, vieläpä hänen ystävänsä etääntyvät hänestä. Turhaan hän puhuu heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Se, joka hankkii ymmärrystä, rakastaa sieluaan. Se, joka ymmärryksen säilyttää, löytää onnen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Väärä todistaja ei jää rankaisematta, ja se, joka valheita puhuu, hukkuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Tyhmälle eivät sovi hyvät päivät, saati sitten palvelijalle hallita ruhtinaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Ymmärrys tekee ihmisen pitkämieliseksi, ja hänen kunniansa on antaa rikos anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Kuninkaan viha on kuin nuoren leijonan ärjyntää, mutta hänen suosionsa on kuin kaste ruoholle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Tyhmä poika on isälleen onnettomuus, ja riitaisa vaimo on kuin katosta tippuva vesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Talo ja tavara peritään isiltä, mutta toimellinen vaimo tulee Herralta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Laiskuus vaivuttaa sikeään uneen, ja veltto joutuu näkemään nälkää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Se, joka pitää käskyt, saa pitää henkensä, mutta se, joka ei tiestään välitä, on kuoleman oma.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Se, joka köyhää armahtaa, lainaa Herralle, ja hän maksaa takaisin hänen hyvän tekonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Kasvata poikaasi, kun on vielä toivoa. Ethän halua hänen kuolemaansa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Se, jonka viha on suuri, kantakoon rangaistuksensa. Jos hänet vapautat, hän vain yltyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Kuule neuvoa, ota opetus varteen, että olisit vasta viisaampi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Monet ovat miehen sydämen ajatukset, mutta Herran neuvo pysyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Ihmisen ilo on hänen laupeutensa, ja köyhä on parempi kuin valehtelija.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Herran pelko on elämäksi: saa levätä yönsä ravittuna, eikä mikään paha kohtaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Laiska pistää kätensä vatiin, mutta ei saa viedyksi sitä takaisin suuhunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Lyö pilkkaajaa, niin yksinkertainen viisastuu, ja jos ymmärtäväistä nuhdellaan, hän käsittää tiedon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Se, joka pitelee pahoin isäänsä ja ajaa äitinsä pois, on hävettävä ja kunniaton poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Jos, poikani, lakkaat kuulemasta opetusta, eksyt pois tiedon sanoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Kelvoton todistaja pitää oikeuden pilkkanaan, ja jumalattomien suu nielee vääryyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Tuomiot ovat valmiina pilkkaajille ja lyönnit tyhmien selkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Viini on pilkkaaja, väkijuoma remuaja, eikä yksikään, joka siitä hoipertelee, ole viisas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Kuninkaan pelottavuus on kuin nuoren leijonan ärjyntää. Se, joka vihoittaa hänet, tekee syntiä omaa henkeään vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Miehelle on kunniaksi riidan lopettaminen, mutta kaikki tyhmät sen alkavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Laiska ei kynnä syksyllä. Elonkorjuun aikana hän korjaa tyhjää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Kuin syvät vedet ovat miehen sydämen ajatukset, ja ymmärtäväinen mies ammentaa niitä esiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Monet huutavat hyvyyttään kukin, mutta kuka löytää luotettavan miehen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Vanhurskas vaeltaa nuhteettomasti, onnellisia ovat lapset hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Kuningas istuu tuomioistuimella ja perkaa silmillään kaiken pahan pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Kuka voi sanoa: \"Olen puhdistanut sydämeni, olen puhdas synnistäni\"?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Kahtalainen paino ja kahtalainen mitta – molemmat ovat Herralle kauhistus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Teoistaan tuntee jo poikasenkin, sen, onko hän teoissaan puhdas ja oikea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Kuulevan korvan ja näkevän silmän – molemmat on Herra luonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Älä unta rakasta, ettet köyhtyisi. Pidä silmäsi auki, niin saat leipää kyllin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, '\"Huonoa, huonoa\", sanoo ostaja, mutta mentyään pois hän kiittelee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Olkoon kultaa, olkoon helmiä paljon, kallein työkalu ovat tiedon huulet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Ota vaatteet siltä, joka toista takasi, ja ota pantti häneltä vieraan puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Makea on miehelle petoksella saatu leipä, mutta perästäpäin hän saa suunsa täyteen soraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Neuvotellen suunnitelmat vahvistuvat, ja sotaa on sinun käytävä neuvokkuudella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Se, joka liikkuu panettelijana, ilmaisee salaisuuden. Älä siis antaudu suulaan ihmisen pariin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Sen lamppu, joka isäänsä ja äitiään kiroaa, sammuu pilkkopimeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Tavara, jota aluksi kiivaasti tavoitellaan, ei lopulta tuo siunausta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Älä sano: \"Minä kostan pahan\"; odota Herraa, hän auttaa sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Kahtalainen paino on Herralle kauhistus, ja väärä vaaka ei ole hyvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Herralta tulevat miehen askeleet. Mitäpä ihminen itse ymmärtäisi tiestään?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Ihmiselle on ansaksi luvata hätiköiden pyhä lahja ja vasta perästäpäin harkita lupauksiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Viisas kuningas perkaa jumalattomat pois viskimellään ja antaa puimajyrän käydä heidän ylitseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Ihmisen henki on Herran lamppu: se tutkistelee sydämen kaikki kammiot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Laupeus ja uskollisuus ovat kuninkaan turva, ja laupeudella hän tukee valtaistuimensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Voima on nuorukaisten kunnia, ja harmaat hapset ovat vanhusten kaunistus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Mustelmat ja haavat puhdistavat pahantekijän, lyönnit puhdistavat sydämen kammiot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Kuninkaan sydän on Herran kädessä kuin vesiojat. Hän taivuttaa sen, minne tahtoo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Kaikki miehen tiet ovat hänen omissa silmissään suorat, mutta Herra tutkii sydämet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Vanhurskauden ja oikeuden harjoittaminen on Herralle otollisempaa kuin uhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Ylpeät silmät ja pöyhkeä sydän – jumalattomien lamppu – ovat syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Vain ahkeran ajatukset ovat hyödyksi, mutta kaikki touhuajat saavat aikaan vain vahinkoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Ne, jotka hankkivat aarteita petollisin kielin, ovat haihtuva tuulahdus, ja he etsivät kuolemaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Jumalattomat tempaa pois heidän väkivaltansa, sillä he eivät tahdo tehdä oikeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Rikollisen tie on mutkainen, mutta puhtaan teot ovat oikeat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Parempi on asua katon kulmalla kuin toraisan vaimon huonetoverina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Jumalattoman sielu himoitsee pahaa eikä lähimmäinen saa armoa hänen silmiensä edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Kun pilkkaajaa rangaistaan, viisastuu yksinkertainen. Kun viisasta neuvotaan, hän ottaa sen opikseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Vanhurskas tarkkaa jumalattoman taloa: jumalattomat syöksyvät onnettomuuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Se, joka tukkii korvansa köyhän huudolta, joutuu itse huutamaan vastausta saamatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Salainen lahja lepyttää vihan ja poveen kätketty lahjus kiivaan kiukun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Vanhurskaalle on ilo, kun oikeutta tehdään, mutta väärintekijöille kauhu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Ihminen, joka eksyy ymmärryksen tieltä, joutuu vainajien seuraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Puutteen mieheksi päätyy riemujen rakastaja, eikä se, joka viiniä ja öljyä rakastaa, rikastu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Jumalaton joutuu lunnaiksi vanhurskaan puolesta ja uskoton oikeamielisten sijaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Parempi asua erämaassa kuin riitaisan ja vihaisen vaimon kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Kalliita aarteita ja öljyä on viisaan majassa, mutta tyhmä ihminen hotkaisee ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Se, joka tavoittelee vanhurskautta ja laupeutta, löytää elämän, vanhurskauden ja kunnian.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Viisas ryntää sankarien kaupunkiin ja kukistaa linnoituksen, joka oli sen turva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Se, joka suunsa ja kielensä varoo, varjelee henkensä onnettomuuksilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Pilkkaajan nimen saa julkea röyhkeä henkilö, jonka meno on röyhkeää ja julkeaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Oma halu tappaa laiskan, sillä hänen kätensä kieltäytyvät työn teosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Aina on hartaasti haluavia, mutta vanhurskas antaa säästelemättä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Jumalattomien uhri on kauhistus, sillä se tuodaan synnissä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Valheellinen todistaja hukkuu, mutta kuunteleva mies saa puhua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Jumalaton tekee kasvonsa julkeiksi, mutta vilpitön pitää tiensä lujana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Ei auta viisaus, ei ymmärrys, ei mikään neuvo Herraa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Hevonen varustetaan taistelun päiväksi, mutta voitto on Herran hallussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Maine on suurta rikkautta kalliimpi, suosio parempi hopeaa ja kultaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Rikas ja köyhä kohtaavat toisensa. Herra on luonut kummankin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Ymmärtäväinen näkee vaaran ja kätkeytyy, mutta yksinkertaiset käyvät kohti ja saavat vahingon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Nöyryyden ja Herran pelon seuraus on vauraus, kunnia ja elämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Orjantappuroita ja ansoja on väärän tiellä. Henkensä varjelee se, joka pysyy niistä kaukana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Totuta poika tiensä suuntaan, niin hän ei vanhanakaan siitä poikkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Rikas hallitsee köyhiä, mutta se, joka ottaa velkaa, joutuu velkojan orjaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Se, joka vääryyttä kylvää, niittää turmiota, ja hänen vihansa vitsa häviää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Armelias saa siunauksen, sillä hän antaa leivästään köyhälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Aja pois pilkkaaja, niin poistuu tora ja loppuu riita ja häväistys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Kuningas on sen ystävä, joka sydämen puhtautta rakastaa ja jolla on suloiset huulet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Herran silmät suojelevat tietoa, mutta uskottoman sanat hän kääntää nurin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Laiska sanoo: \"Ulkona on leijona. Minut tapetaan keskellä toria.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Irstaitten vaimojen suu on syvä kuoppa. Herran vihan alainen kaatuu siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Hulluus on kiertynyt kiinni pojan sydämeen, mutta kasvatuksen vitsa sen hänestä kauas karkottaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Sen, joka sortaa köyhää enentääkseen omaansa, pitää antaa rikkaalle ja köyhtyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Kallista korvasi ja kuuntele viisaitten sanoja ja pane oppini sydämeesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Sillä suloista on, jos kätket ne sisimpääsi. Olkoot ne kaikki huulillasi valmiina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Jotta Herra olisi turvanasi, olen nyt neuvonut juuri sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Olenhan ennenkin sinulle kirjoittanut ja antanut neuvoja ja tietoa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'opettaakseni sinulle totuutta, totuuden sanoja, että voisit totuuden sanoilla vastata lähettäjällesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Älä raasta köyhää, siksi että hän on köyhä, äläkä polje kurjaa portissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'sillä Herra ajaa hänen asiansa ja riistää hänen riistäjiltään hengen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Älä rupea pikavihaisen ystäväksi äläkä seurustele kiukkuisen kanssa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'että et tottuisi hänen teihinsä ja saattaisi sieluasi ansaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Älä ole niitä, jotka kättä lyövät ja jotka menevät takuuseen veloista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Jollei sinulla ole, millä maksaa, mitäpä muuta, kuin viedään vuode altasi!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Älä siirrä ikivanhaa rajaa, jonka esi-isäsi ovat asettaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Jos näet miehen, aikaansaavan toimissaan, hänen paikkansa on kuningasten, ei alhaisten, palveluksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Kun istut aterialle hallitsijan seuraan, pidä tarkoin mielessä, kuka edessäsi on,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'ja pane veitsi kurkullesi, jos olet kovin nälkäinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Älä himoitse hänen herkkujaan, sillä ne ovat petollisia ruokia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Älä näe vaivaa rikastuaksesi ja lakkaa käyttämästä ymmärrystäsi siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Kun silmäsi siihen lentävät, rikkaus on mennyttä, sillä se saa siivet kuin kotka, joka lentää taivaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Älä syö pahansuovan leipää äläkä himoitse hänen herkkujaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Sillä niin kuin hän mielessään laskee, niin hän menettelee. Hän sanoo sinulle: \"Syö ja juo\", mutta hänen sydämensä ei ole puolellasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Syömäsi palan sinä olet oksentava, ja suloiset sanasi sinä tuhlasit turhaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Älä puhu tyhmän kuullen, sillä hän katsoo ymmärtävät sanasi ylen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Älä siirrä ikivanhaa rajaa äläkä mene orpojen pelloille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Sillä heidän sukulunastajansa on väkevä, ja hän ajaa heidän riita-asiansa sinua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Tuo sydämesi opetettavaksi ja korvasi tiedon sanojen ääreen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Älä kiellä pojalta kuria, sillä jos lyöt häntä vitsalla, hän säästyy kuolemasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Vitsalla sinä häntä lyöt ja helvetistä hänen sielunsa pelastat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Poikani, jos sydämesi on viisas, minunkin sydämeni iloitsee,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'ja munuaiseni riemuitsevat huultesi puhuessa vilpittömästi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Älköön sydämesi kadehtiko synnintekijöitä, vaan pysy joka päivä Herran pelossa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'niin sinulla totisesti on tulevaisuus, eikä toivoasi hävitetä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Kuule, poikani, ja ole viisas, ja ohjaa sydämesi autuuden tielle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Älä oleskele juopottelijoiden äläkä ylensyöjien parissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'Sillä juopottelija ja ylensyöjä köyhtyvät, ja unisuus puettaa ryysyihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Kuule isääsi, joka on sinut siittänyt, äläkä halveksi äitiäsi, kun hän tulee vanhaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Osta totuutta, älä myy, osta viisautta, opetusta ja ymmärrystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Ääneen saa riemuita vanhurskaan isä, joka on siittänyt viisaan, sillä hänestä on iloa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Olkoon isälläsi ja äidilläsi ilo, synnyttäjäsi riemuitkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Anna, poikani, minulle sydämesi, ja olkoot tieni silmissäsi mieluiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Sillä portto on syvä kuoppa, ja vieras nainen on ahdas kaivo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Vieläpä hän väijyy kuin rosvo, ja hän kartuttaa uskottomia ihmisten seassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Kenellä on voivotus, kenellä vaikerrus? Kenellä riidat, kenellä valitus? Kenellä haavat ilman syytä? Kenellä sameat silmät?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Niillä, jotka viinin ääressä viipyvät ja jotka etsivät sekoitettuja juomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Älä katsele viiniä, kuinka se punoittaa, kuinka se maljassa hohtaa ja helposti valahtaa alas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Lopulta se puree kuin käärme ja pistää kuin myrkkylisko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Silmäsi katselevat vieraita naisia, ja sydämesi puhuu sopimattomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'Sinusta on kuin makaisit keskellä merta, on kuin makaisit maston huipussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, '\"Löivät minua, mutta se ei sattunut minuun. Pieksivät minua, mutta en tuntenut mitään. Milloin herään? Tahdon hakea sitä vielä lisää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Älä kadehdi pahoja ihmisiä äläkä halua heidän seuraansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Sillä heidän mielensä miettii väkivaltaa, ja heidän huulensa puhuvat onnettomuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Viisaudella talo rakennetaan ja ymmärryksellä se pidetään lujana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'Taidolla täytetään kammiot kaikkea kallista ja ihanaa tavaraa täyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Viisas mies on väkevä, ja taidon mies on vahva voimiltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Neuvokkuudella näet sinun on käytävä sotaa, ja neuvonantajien runsaus tuo menestyksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Liian korkea on hullulle viisaus, hän ei saa avata suutaan portissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Sitä, jolla on pahanteko mielessä, sanotaan juonittelijaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Synti on hulluuden työ, ja pilkkaaja on ihmisille kauhistus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Jos olet ollut veltto, ahtaana aikana voimasi joutuu ahtaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Pelasta ne, joita kuolemaan viedään, mene apuun niille, jotka surmapaikalle hoippuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Jos sanot: \"Katso, emme tienneet siitä\", niin ymmärtäähän asian sydänten tutkija. Sielusi vartija sen tietää, ja hän kostaa ihmiselle hänen tekojensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Syö hunajaa, poikani, sillä se on hyvää, ja mesi on makeaa suussasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Samankaltaiseksi tunne viisaus sielullesi. Jos sen löydät, sinulla on tulevaisuus, eikä toivosi mene hukkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Älä väijy, jumalaton, vanhurskaan majaa, älä hävitä hänen leposijaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Sillä seitsemän kertaa vanhurskas lankeaa ja nousee jälleen, mutta jumalattomat suistuvat onnettomuuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Älä iloitse vihamiehesi langetessa, älköön sydämesi riemuitko hänen kompastuessaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'ettei Herra, kun sen näkee, pitäisi sitä pahana, ja kääntäisi hänestä pois vihaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Älä vihastu pahantekijöiden tähden äläkä kadehdi jumalattomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'Sillä pahalla ei ole tulevaisuutta ja jumalattomien lamppu sammuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Pelkää, poikani, Herraa ja kuningasta, älä sekaannu kapinallisten seuraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Sillä heille tulee yhtäkkiä onnettomuus, häviö kummallekin, kuka tietää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Nämäkin ovat viisaitten sanoja. Ei ole hyvä tuomitessa katsoa henkilöön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Joka sanoo syylliselle: \"Sinä olet syytön\", sitä kansat kiroavat ja kansakunnat vihaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'Mutta niiden, jotka oikein tuomitsevat, käy hyvin, ja heitä siunataan hyvällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Se huulille suutelee, joka antaa oikean vastauksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Toimita tehtäväsi ulkona ja tee valmista pellollasi, sen jälkeen perusta itsellesi perhe.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Älä ole syyttä todistajana lähimmäistäsi vastaan, vai petätkö huulillasi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Älä sano: \"Niin kuin hän teki minulle, teen minäkin hänelle ja kostan miehelle hänen tekojensa mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Minä kuljin laiskurin pellon ohi, mieltä vailla olevan miehen viinitarhan vierestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'Katso: se kasvoi kaikkialla ohdakkeita. Sen pinta oli nokkosten peitossa ja sen kiviaita luhistunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Minä katselin ja painoin sydämeeni, havaitsin ja otin opikseni:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Nuku vielä vähän aikaa, torku vähän aikaa, makaa vähän aikaa ristissä käsin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'niin köyhyys käy päällesi kuin rosvo ja puute kuin aseistettu mies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Nämäkin ovat Salomon sananlaskuja, Hiskian, Juudan kuninkaan, miesten kokoamia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Jumalan kunnia on salata asia, ja kuningasten kunnia on tutkia asia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Taivaan korkeus, maan syvyys ja kuningasten sydän on tutkimaton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Kun hopeasta poistetaan kuona, puhdistuu astia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Kun jumalaton poistetaan kuninkaan luota, hänen valtaistuimensa vahvistuu vanhurskaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Älä tavoittele kunniaa kuninkaan edessä äläkä asetu suurten paikalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Sillä parempi on, jos sinulle sanotaan: \"Käy tänne ylös\", kuin että sinut alennetaan ylhäisen edessä, jonka silmäsi olivat nähneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Älä ole kärkäs käräjöimään. Muuten sinulla ei lopulta ole, mitä tehdä, kun lähimmäisesi on saattanut sinut häpeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Riitele oma riitasi lähimmäisesi kanssa, mutta toisen salaisuutta älä ilmaise.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'Muuten sinut häpäisee, kuka sen kuuleekin, eikä huono huuto sinusta lakkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Kultaomenia hopeamaljoissa ovat sanat, oikeaan aikaan sanotut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Kultainen korvarengas ja hienokultainen koru ovat viisas nuhtelija kuulevalle korvalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Kuin lumen viileys elonaikana on luotettava lähetti lähettäjälleen. Isäntänsä sielun hän virvoittaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Kuin pilvet ja tuuli, jotka eivät tuo sadetta, on mies, joka kerskuu lahjoista, jotka ovat petosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Kärsivällisyydellä taivutetaan ruhtinas, ja lempeä kieli murskaa luut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Jos hunajaa löydät, syö kohtuudella, ettet kyllästyisi siihen ja oksentaisi sitä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Astu jalallasi harvoin lähimmäisesi kotiin, ettei hän kyllästyisi sinuun ja alkaisi sinua vihata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Nuija, miekka ja terävä nuoli on mies, joka todistaa väärin lähimmäistään vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Kuin mureneva hammas ja horjuva jalka on epäuskoisen turva ahdingon päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Kuin se, joka riisuu vaatteet kylmällä, kuin etikka lipeän sekaan, on se, joka laulaa lauluja raskasmieliselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Jos vihamiehelläsi on nälkä, anna hänelle leipää syödä, ja jos hänellä on jano, anna hänelle vettä juoda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'Sillä niin sinä kokoat tulisia hiiliä hänen päänsä päälle, ja Herra korvaa sen sinulle takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Pohjoistuuli saa aikaan sateen ja salainen panettelu vihaiset kasvot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Parempi on asua katon kulmalla kuin riitaisan vaimon huonetoverina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Kuin nääntyvälle raikas vesi on hyvä sanoma kaukaisesta maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Kuin sekoitettu lähde ja turmeltu kaivo on vanhurskas, joka horjuu jumalattoman edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Liika hunajan syönti ei ole hyväksi, ja kohtuuden tutkiminen on todella kunniaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Kuin hajotettu kaupunki muuria vailla, on mies, joka ei hillitse mieltään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Yhtä vähän kuin kesään soveltuu lumi ja elonaikaan sade, soveltuu tyhmälle kunnia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Kuin liitävä lintu, kuin lentävä pääskynen on aiheeton kirous: se ei käy toteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Hevoselle ruoska, aasille suitset, tyhmälle vitsa selkään!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Älä vastaa tyhmälle hänen typeryytensä mukaan, ettet sinäkin olisi hänen kaltaisensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Vastaa tyhmälle hänen typeryytensä mukaan, ettei hän pitäisi itseään viisaana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Se, joka lähettää sanan tyhmän mukana, katkaisee jalat altaan ja juo väkivaltaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Velttoina riippuvat halvaantuneen sääret, samoin on sananlaskun laita tyhmien suussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Yhtä kuin sitoisi kiven linkoon kiinni, on antaa kunniaa tyhmälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Kuin ohdake, joka on osunut juopuneen käteen, on sananlasku tyhmien suussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Kuin jousimies, joka kaikkia haavoittaa, on se, joka tyhmän pestaa, se kulkureita pestaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Kuin koira, joka palaa oksennukselleen, on tyhmä, joka toistaa typeryyksiään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Näet miehen, viisaan omissa silmissään – enemmän on toivoa tyhmästä kuin hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Laiska sanoo: \"Tiellä on nuori leijona, leijona torien vaiheilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Ovi kääntyilee saranoillaan, laiska vuoteellaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Laiska pistää kätensä vatiin, mutta ei viitsi viedä sitä suuhunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Laiska on omissa silmissään viisaampi kuin seitsemän, jotka vastaavat taitavasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Kulkukoiraa korvista tarttuu se, joka suuttuu riidasta, joka ei hänelle kuulu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Kuin mieletön, joka ammuskelee tulisia surmannuolia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'on mies, joka vahingoittaa lähimmäistään ja sanoo: \"Leikillähän minä sen tein.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Puiden loppuessa sammuu tuli, ja panettelijan poistuessa taukoaa riita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Hehkuksi hiilet, tuleksi puut, riidan lietsomiseksi toraisa mies.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Panettelijan puheet ovat kuin herkkupalat, ne painuvat sisusten kammioihin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Kuin hopeasilaus saviastian pinnalla ovat hehkuvat huulet ja paha sydän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Vihamies teeskentelee huulillaan, mutta hautoo petosta sydämessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Jos hän muuttaa suloiseksi äänensä, älä häntä usko, sillä seitsemän kauhistusta hänellä on sydämessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Vihamielisyys kätkeytyy kavalasti, mutta seurakunnassa sen pahuus paljastuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Se, joka toiselle kuoppaa kaivaa, itse siihen lankeaa, ja sen päälle, joka kiveä vierittää, se takaisin pyörähtää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Valheellinen kieli vihaa haavoittamiaan, ja liukas suu saa aikaan tuhoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Älä huomispäivästä kersku, sillä et tiedä, mitä mikin päivä synnyttää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Kehukoon sinua toinen, ei oma suusi, vieras, eivätkä omat huulesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Raskas on kivi ja painava hiekka, mutta molempia raskaampi hullun suuttumus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Kiukku on julma, viha on kuin tulva; mutta kuka voi kestää mustasukkaisuutta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Parempi julkinen nuhde kuin salattu rakkaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Ystävän lyönnit ovat luotettavat, mutta vihamiehen suudelmat ylenpalttiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Kylläinen polkee hunajaakin, nälkäiselle on kaikki karvaskin makeaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Kuin pesästään paennut lintu, on mies paennut paikaltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Öljy ja suitsuke ilahduttavat sydämen, samoin ystävän sydämellisyys, kun hän antaa neuvoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Ystävääsi ja isäsi ystävää älä hylkää, äläkä onnettomuutesi päivänä mene veljesi taloon: parempi naapuri lähellä kuin veli kaukana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Viisastu, poikani, ja ilahduta sydämeni, niin voin antaa herjaajalleni vastauksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Viisas näkee vaaran ja kätkeytyy, mutta yksinkertaiset käyvät kohti ja saavat rangaistuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Ota siltä vaatteet, joka toista takasi, ja ota häneltä pantti vieraan naisen tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Joka siunaa ystäväänsä isoäänisesti aamulla varhain, sille se luetaan kiroukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Räystäästä tippuva vesi sadepäivänä ja toraisa vaimo ovat yhdenveroiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Se, joka tahtoo pitää hänet salassa, pitää tuulta salassa ja tavoittaa öljyä oikeaan käteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Rauta rautaa hioo, ja ihminen toistaan hioo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Se, joka hoitaa viikunapuuta, saa syödä sen hedelmää. Se, joka isännästään pitää vaarin, tulee kunniaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Kuin kasvot kuvastuvat vedestä, niin ihmisen sydän toisesta ihmisestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Helvetti ja kadotus eivät saa kyllikseen. Myöskään ihmisen silmät eivät saa kyllikseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Hopealle sulatin, kullalle uuni, mutta mies koetellaan maineellaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Survo hullua huhmaressa, survimella jyvien seassa: hänen hulluutensa ei hänestä lähde.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Tiedä tarkasti, miltä pikkukarjasi näyttää, ja pidä huoli laumoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Sillä vauraus ei säily iäti, ja pysyykö kruunukaan polvesta polveen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Kun ruoho on korjattu ja tuore odelma tulee näkyviin ja vuorten vihanta on koottu,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'sinulla on karitsoita puvuksesi ja vuohipukkeja pellon ostohinnaksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'sekä vuohenmaitoa kyllin ravinnoksesi, perheesi ravinnoksi ja palvelijatartesi elatukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Jumalaton pakenee, vaikka kukaan ei aja takaa, mutta vanhurskaat ovat turvassa kuin nuori leijona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Rikkomisellaan maa saa paljon ruhtinaita, mutta ymmärtäväisen ja taitavan miehen toimesta se säilyy kauan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Köyhä mies, joka vaivaisia sortaa, on kuin sade, joka lyö lakoon eikä anna leipää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Lain hylkijät kehuvat jumalattomia, mutta lain noudattajat kauhistuvat heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Pahat ihmiset eivät ymmärrä oikeutta, mutta Herraa etsivät ymmärtävät kaiken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Parempi on köyhä, joka vaeltaa nuhteettomasti, kuin kahdella tiellä mutkitteleva rikas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Joka ottaa vaarin laista, on ymmärtäväinen poika, mutta joka pitää yhtä elostelijoiden kanssa, saattaa isänsä häpeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Joka kartuttaa varojaan korolla ja voitolla, kokoaa niitä sille, joka armahtaa köyhiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Kauhistus on sellaisen rukouskin, joka kääntää korvansa kuulemasta lakia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Se, joka eksyttää oikeamielisiä pahalle tielle, lankeaa omaan kuoppaansa, mutta nuhteettomat perivät onnen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Rikas mies on omissa silmissään viisas, mutta ymmärtäväinen köyhä ottaa hänestä selvän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Kun vanhurskaat riemuitsevat, on ihanuus suuri, mutta kun jumalattomat nousevat, saa ihmisiä hakea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Joka rikoksensa salaa, se ei menesty, mutta joka ne tunnustaa ja hylkää, se saa armon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Autuas se ihminen, joka on aina aralla tunnolla; mutta se, joka paaduttaa sydämensä, lankeaa onnettomuuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Kuin ärjyvä leijona ja ahnas karhu on köyhän kansan jumalaton hallitsija.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Ruhtinas ymmärrystä vailla on suuri sortaja, mutta väärän voiton vihaaja saa elää kauan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Ihmisen, jota verivelka painaa, on pakoiltava hautaan asti. Älköön häntä suojeltako.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Nuhteettomasti vaeltava saa avun, mutta kahdella tiellä mutkittelija kaatuu kerralla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Se, joka peltonsa viljelee, saa leipää riittävästi, mutta tyhjän tavoittelija saa köyhyyttä kyllin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Luotettava mies saa runsaan siunauksen, mutta se, jolla on kiihko rikastua, ei jää rankaisematta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Ei ole hyvä katsoa henkilöön, sellainen mies tekee rikoksen leipäpalankin tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Se, joka haluaa kiihkeästi rikkautta ja on kateellinen, ei tiedä, että häntä kohtaa puute.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Se, joka toista nuhtelee, saa suosiota enemmän kuin se, joka kielellään imartelee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Se, joka isältään ja äidiltään riistää ja sanoo: \"Ei tämä ole rikos\", on tuhontekijän toveri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Ylpeä nostattaa riidan, mutta Herraan luottava tulee ravituksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Omaan sydämeensä luottava on tyhmä, mutta viisaudessa vaeltava pelastuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Se, joka köyhälle antaa, ei joudu puutteeseen, mutta se, joka silmänsä häneltä sulkee, saa paljon kirousta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Kun jumalattomat nousevat, ihmiset piiloutuvat. Mutta kun he hukkuvat, hurskaat enentyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Nuhteita saanut mies, joka pysyy niskurina, rusennetaan äkisti, eikä hän tervehdy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Vanhurskaitten enentyessä kansa iloitsee, mutta jumalattoman hallitessa kansa huokaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Viisautta rakastava on isälleen iloksi, mutta porttojen toveri tuhlaa varansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Oikeudella kuningas pitää maan pystyssä, mutta lahjusten ottaja sen hävittää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Mies, joka lähimmäistään liehakoi, virittää verkon hänen askeleilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'Pahan miehen rikoksessa on ansa, mutta vanhurskas riemuitsee ja iloitsee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Vanhurskas tuntee köyhien asian, mutta jumalaton ei välitä siitä mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Pilkkaajat kaupungin villitsevät, mutta viisaat hillitsevät vihan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Kun viisas mies käräjöi hullun miehen kanssa, tämä reuhtoo ja nauraa eikä asetu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Verenhimoiset vihaavat nuhteetonta, mutta oikeamieliset etsivät hänen sieluaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Tyhmä päästää ulos kaiken sisältään, mutta viisas sen tyynnyttää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Hallitsija, joka kuuntelee valhepuheita, saa palvelijoikseen pelkkiä jumalattomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Köyhä ja sortaja kohtaavat toisensa. Kummankin silmille Herra antaa valon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Kuninkaalla, joka tuomitsee köyhiä oikein, on valtaistuin iäti vahva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Vitsa ja nuhde antavat viisautta, mutta kasvattamaton poika on äitinsä häpeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Kun jumalattomat lisääntyvät, lisääntyy rikos, mutta vanhurskaat saavat nähdä, kuinka he kukistuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Kasvata poikaasi, niin hän sinua virvoittaa ja tarjoaa sielullesi herkkuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Missä profeetallinen sana puuttuu, siinä kansa käy kurittomaksi. Autuas se, joka noudattaa lakia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Palvelija ei ojennu sanoista: hän kyllä ymmärtää, mutta ei tottele.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Näet miehen, nopean puhumaan – enemmän on toivoa tyhmästä kuin hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Jos palvelijaansa nuoresta pitäen hemmottelee, hänestä tulee lopulta kiittämätön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Pikavihainen mies nostaa riidan, ja kiukkuinen tulee rikkoneeksi paljon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Ihmisen alentaa hänen oma ylpeytensä, mutta nöyrä saa kunnian.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Se, joka käy osille varkaan kanssa, vihaa sieluaan. Hän kuulee vannotuksen, mutta ei ilmaise mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Ihmispelko vie loukkuun, mutta Herraan luottava on turvattu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Hallitsijan suosiota etsivät monet, mutta Herralta tulee miehelle oikeus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Vääryyden mies on kauhistus vanhurskaille, mutta suoran tien kulkija on kauhistus jumalattomalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Aagurin, Jaaken pojan, sanat, profeettasana, jonka mies puhui Iitielille, nimittäin Iitielille ja myös Ukalille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Sillä järjetön olen minä mieheksi, minulla ei ole ihmisen ymmärrystä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'enkä ole oppinut viisautta tullakseni tuntemaan Pyhimmän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Kuka on noussut taivaaseen ja astunut sieltä alas? Kuka on koonnut kouriinsa tuulen? Kuka on sitonut vedet vaatteeseen? Kuka on asettanut kohdalleen kaikki maan ääret? Mikä on hänen nimensä ja mikä hänen Poikansa nimi? Senhän tiedät?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Jokainen Jumalan sana on taattu. Hän on niiden kilpi, jotka häneen turvaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Älä lisää hänen sanoihinsa mitään, ettei hän ota sinua nuhdeltavaksi ja ettet joutuisi valehtelijaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Kahta minä sinulta pyydän, älä niitä minulta koskaan kiellä kuolemaani saakka:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Turha ja valheellinen puhe pidä minusta kaukana. Älä köyhyyttä, älä rikkautta minulle anna. Anna minulle ravinnoksi määräosani leipää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'etten kylläisenä tulisi kieltäjäksi ja sanoisi: \"Kuka on Herra?\" ja etten köyhtyneenä varastaisi ja rikkoisi Jumalani nimeä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Älä kieli palvelijasta hänen isännälleen; muutoin hän sinut kiroaa, ja sinä saat siitä kärsiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'On suku, joka isäänsä kiroaa eikä siunaa äitiään;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'suku, joka on omissa silmissään puhdas, vaikka ei ole pesty liastaan!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Suku – kuinka ylpeät ovatkaan sen silmät ja kuinka kopeasti se iskee silmää –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'suku, jonka hampaat ovat miekkoja ja leukaluut veitsiä syödäkseen kurjat pois maasta ja köyhät ihmisten joukosta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Verenimijällä on kaksi tytärtä: \"Anna vielä!\" \"Anna vielä!\" Kolme on, jotka eivät kyllikseen saa, neljä, jotka eivät sano: \"Jo riittää\":');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'helvetti, hedelmätön kohtu, maa, joka ei saa kyllikseen vedestä, ja tuli, joka ei sano: \"Jo riittää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Joka isäänsä pilkkaa ja pitää halpana totella äitiään, häneltä korpit hakkaavat silmän puron luona, ja kotkan poikaset syövät sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Kolme on minusta ihmeellistä, ja neljä on, joita en käsitä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'kotkan tie taivaalla, käärmeen tie kalliolla, laivan tie keskellä merta ja miehen tie neitsyen sydämeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Samoin ovat aviorikoksen tehneen vaimon jäljet: hän syö, pyyhkii suunsa ja sanoo: \"En ole pahaa tehnyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Kolmen alla järisee maa, ja neljän alla se ei kestä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'orjan alla, kun hän kuninkaaksi pääsee, typerän alla, kun hän saa tarpeeksi leipää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'hyljeksityn alla, kun hän saa miehen, ja palvelijattaren, kun hän syrjäyttää emäntänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Neljä on maassa vähäisintä, mutta viisaan viisasta silti:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'Muurahaiset ovat voimaton kansa, mutta ne hankkivat leipänsä kesällä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'tamaanit ovat heikko kansa, mutta ne laittavat pesänsä kallioihin;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'heinäsirkkaparvella ei ole kuningasta, mutta kaikki lähtevät samalla liikkeelle;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'lisko pitää käsillään kiinni ja oleskelee kuninkaan linnoissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Kolmella on komea askel, ja neljällä uljas käynti:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'leijona, sankari eläinten joukossa, joka ei väisty ketään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'solakka hevonen, tai pässi ja kuningas joukkonsa johdossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Jos korottaessasi itseäsi menettelit typerästi ja ajattelit pahaa, laske käsi suullesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Sillä maitoa pusertamalla saa voin, nenää pusertamalla saa veren, ja vihoja pusertamalla saa riidan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Lemuelin, Massan kuninkaan, sanat, joilla hänen äitinsä kasvatti häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Mitä, poikani, mitä, kohtuni poika, mitä, lupausteni poika?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Älä anna voimaasi naisille, älä elämääsi niiden valtaan, jotka tuhoavat kuninkaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Ei sovi kuningasten, Lemuel, ei sovi kuningasten juoda viiniä eikä hallitsijoiden kysellä: \"Mistä väkijuomaa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'Muuten hän juodessaan unohtaa säädökset ja vääristää kaikkien köyhien lasten oikeuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Antakaa väkevää juomaa menehtyvälle ja viiniä murhemielisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Hän juo ja unohtaa köyhyytensä eikä enää muistele vaivaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Avaa suusi mykän hyväksi, oikeuden hankkimiseksi kaikille onnettomille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Avaa suusi, tuomitse oikein, hanki kurjalle ja köyhälle oikeus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Kunnon vaimon kuka löytää? Sellaisen arvo on helmiä paljon kalliimpi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Hänen miehensä sydän luottaa häneen, eikä mieheltä puutu riistaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Hän tekee miehelleen hyvää, ei pahaa, kaikkina elinpäivinään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Hän hankkii villat ja pellavat ja tekee työtä mielellään käsillään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Hän on kauppiaan laivojen kaltainen: leipänsä hän noutaa kaukaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Kun on vielä yö, hän nousee ja antaa ravinnon perheelleen ja palvelustytöilleen heidän osansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Hän haluaa peltoa ja hankkii sen ja istuttaa viinitarhan kättensä hedelmällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Hän vyöttää kupeensa voimalla ja vahvistaa käsivartensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Hän huomaa hankkeensa käyvän hyvin, eikä hänen lamppunsa sammu yöllä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Hän ojentaa kätensä kehräpuuhun ja pyörittää värttinää kämmenissään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Hän avaa kätensä kurjalle ja ojentaa köyhälle molemmat kätensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Hän ei pelkää perheensä puolesta lunta, sillä koko hänen perheensä on puettu kaksiin vaatteisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Hän valmistaa itselleen peitteitä. Hienoa pellavaa ja purppuraa on hänen pukunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Hänen miehensä tunnetaan porteissa maan vanhinten joukossa istuessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Hän valmistaa ja myy pellavapaitoja ja toimittaa vöitä kauppiaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Vallalla ja kunnialla hänet on vaatetettu, ja hän nauraa tulevalle päivälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Hän avaa suunsa viisauden sanoihin, ja hänen kielellään on lempeä opetus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Hän tarkkailee talonsa menoa, eikä hän syö laiskan leipää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Hänen poikansa nousevat ja kiittävät hänen onneaan. Hänen miehensä nousee ja ylistää häntä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, '\"Paljon on tyttäriä toimellisia menoissaan, mutta yli niiden kaikkien kohoat sinä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Pettävä on sulous, ja kauneus on katoavaa. Ylistetty se vaimo, joka Herraa pelkää!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Suokaa hänen nauttia kättensä hedelmiä. Hänen tekonsa ylistäkööt häntä porteissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Saarnaajan, Daavidin pojan, sanat, joka oli kuninkaana Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Turhuuksien turhuus, sanoi saarnaaja, turhuuksien turhuus; kaikki on turhuutta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Mitä hyötyä on ihmiselle kaikesta vaivastaan, jolla hän rasittaa itseään auringon alla?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Sukupolvi menee, ja sukupolvi tulee, mutta maa pysyy ainiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Myös aurinko nousee, ja aurinko laskee ja kiiruhtaa sille sijalleen, josta se jälleen nousee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Tuuli menee etelään ja kiertää pohjoiseen, kiertää yhä kiertämistään, ja samalle kierrolleen tuuli palaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Kaikki purot laskevat mereen, mutta meri ei siitä täyty. Samaan paikkaan, johon purot ovat laskeneet, ne laskevat edelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Kaikki asiat ovat vaivaa täynnä, niin ettei kukaan voi kertoa sitä. Silmä ei saa kyllikseen näkemisestä eikä korva täyty kuulemastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Mitä on ollut, sitä vastakin on, ja mitä on tehty, sitä vastakin tehdään. Ei ole mitään uutta auringon alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Jos jotakin on, josta sanotaan: \"Katso, tämä on uutta\", niin on sitä kuitenkin ollut jo ennen, muinaisina aikoina, jotka ovat olleet ennen meitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Ei jää muistoa esi-isistä. Myöskään jälkeläisistä, jotka tulevat, ei jää muistoa niille, jotka heidän jälkeensä tulevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Minä, saarnaaja, olin Israelin kuningas Jerusalemissa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'ja käänsin sydämeni viisaudella tutkimaan ja miettimään kaikkea, mitä auringon alla tapahtuu. Tämä on vaikea työ, jonka Jumala on antanut ihmislapsille, jotta he rasittaisivat sillä itseään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Minä katselin kaikkia tekoja, mitä tehdään auringon alla, ja katso, se on kaikki turhuutta ja tuulen tavoittelua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Väärä ei voi suoristua, eikä sitä, mikä puuttuu, voi laskea lukuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Minä puhuin sydämessäni näin: Katso, minä olen hankkinut suuren viisauden ja sitä lisännyt, jopa yli kaikkien, jotka ovat ennen minua hallinneet Jerusalemissa, ja paljon on sydämeni nähnyt viisautta ja tietoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Niin käänsin sydämeni tutkimaan viisautta ja tietoa, mielettömyyttä ja tyhmyyttä, ja tulin tietämään, että sekin oli tuulen tavoittelua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Sillä missä on paljon viisautta, siinä on paljon surua, ja se, joka lisää tietoa, lisää tuskaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Minä sanoin sydämessäni: Tule, tahdon koetella sinua ilolla, nauti hyvää. Mutta katso, sekin oli turhuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Naurusta sanoin: \"Mieletöntä!\" ja ilosta: \"Mitä se toimittaa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Mietin mielessäni virkistää ruumistani viinillä kuitenkin niin, että sydämeni harrastaisi viisautta ja pidättyisi tyhmyydestä, kunnes saisin nähdä, mikä olisi ihmislapsille hyvä heidän tehdäkseen sitä taivaan alla lyhyinä elämänsä päivinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Tein suuria töitä. Rakensin itselleni taloja, istutin itselleni viinitarhoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Laitoin itselleni puutarhoja ja puistoja ja istutin niihin kaikkia hedelmäpuita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Tein itselleni vesilammikoita kastellakseni niistä lehtoja, joissa kasvoi puita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Ostin orjia ja orjattaria, ja kotona syntyneitäkin minulla oli. Minulla oli karjaa, nautoja ja lampaita, paljon enemmän kuin kenelläkään niistä, jotka olivat olleet ennen minua Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Kokosin itselleni myös hopeaa ja kultaa ja kuninkaitten ja maakuntien aarteita sekä hankin itselleni laulajia ja laulajattaria ja ihmislasten iloja, erilaisia nautintoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Tulin suureksi ja yhä suuremmaksi, yli kaikkien, jotka olivat olleet ennen minua Jerusalemissa. Minussa pysyi kuitenkin viisauteni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'En pidättänyt silmiäni mistään, mitä ne pyysivät, enkä kieltänyt sydämeltäni mitään iloa, sillä minun sydämeni iloitsi kaikesta vaivannäöstäni, ja se oli minun osani kaikesta vaivastani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Mutta kun minä käänsin huomioni kaikkiin töihin, joita käteni olivat tehneet, ja vaivannäköön, jolla olin vaivannut itseäni niitä tehdessäni, niin katso: se oli kaikki turhuutta ja tuulen tavoittelua, eikä siitä ollut hyötyä auringon alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Kun minä käännyin katsomaan viisautta ja mielettömyyttä ja tyhmyyttä – sillä mitä ihminen, joka tulee kuninkaan jälkeen, osaa muuta kuin tehdä, mitä on jo ennen tehty? –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'niin minä näin, että viisaus on tyhmyyttä hyödyllisempi, samoin kuin valo on pimeyttä hyödyllisempi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Viisaalla on silmät päässä, tyhmä taas vaeltaa pimeässä. Mutta minä tulin tietämään senkin, että toisen käy niin kuin toisenkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Silloin minä sanoin sydämessäni: Se, mikä kohtaa tyhmää, kohtaa minuakin. Miksi sitten olen tullut niin perin viisaaksi? Sanoin sydämessäni: Tämäkin on turhuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Sillä viisaasta, niin kuin ei tyhmästäkään, ei jää ikuista muistoa, kun kerran tulevina päivinä kaikki unohdetaan, ja viisas kuolee niin kuin tyhmäkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Vihasin elämää, sillä minusta oli pahaa se, mikä tapahtuu auringon alla, koska kaikki on turhuutta ja tuulen tavoittelua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Minä vihasin kaikkea vaivannäköäni, jolla olin vaivannut itseäni auringon alla, koska minun täytyy se jättää ihmiselle, joka tulee jälkeeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Kuka tietää, onko hän viisas vai tyhmä? Mutta hän tulee vallitsemaan kaikkia vaivannäköni tuloksia, joiden tähden minä olen vaivannut itseäni ja ollut viisas auringon alla. Tämäkin on turhuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Sydämeni vaipui epätoivoon kaikesta vaivannäöstäni, jolla olin vaivannut itseäni auringon alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Sillä niin on: ihmisen, joka on vaivan nähnyt toimien viisaudella, tiedolla ja taidolla, täytyy antaa kaikki perinnöksi ihmiselle, joka ei ole siitä vaivaa nähnyt. Sekin on turhuutta ja on suuri onnettomuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Sillä mitä ihminen saa kaikesta vaivannäöstään ja sydämensä pyrkimyksestä, jolla hän on vaivannut itseään auringon alla?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Ovathan kaikki hänen päivänsä olleet pelkkää tuskaa ja hänen työnsä surua, eikä yölläkään hänen sydämensä saanut lepoa. Tämäkin on turhuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Ihmisellä ei ole muuta onnea kuin syödä ja juoda ja antaa sielunsa nauttia hyvää vaivannäkönsä ohessa. Mutta minä tulin näkemään, että sekin tulee Jumalan kädestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, '– \"Sillä kuka voi syödä ja kuka nauttia ilman minua?\" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Sillä hän antaa ihmiselle, joka on hänelle otollinen, viisautta, tietoa ja iloa. Mutta syntiselle hän antaa työksi koota ja kartuttaa annettavaksi sille, joka on otollinen Jumalalle. Sekin on turhuutta ja tuulen tavoittelua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Kaikella on määräaika, ja joka asialla on aikansa taivaan alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Aika on syntyä ja aika kuolla. Aika on istuttaa ja aika repiä istutus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Aika on surmata ja aika parantaa. Aika on purkaa ja aika rakentaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Aika on itkeä ja aika nauraa. Aika on valittaa ja aika hypellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Aika on heitellä kiviä ja aika kerätä kivet. Aika on syleillä ja aika olla syleilemättä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Aika on etsiä ja aika kadottaa. Aika on säilyttää ja aika heittää pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Aika on reväistä rikki ja aika ommella yhteen. Aika on olla vaiti ja aika puhua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Aika on rakastaa ja aika vihata. Aika on sodalla ja aika rauhalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Mitä hyötyä tekijällä on siitä, mistä hän näkee vaivaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Olen katsellut työtä, minkä Jumala on antanut ihmislapsille heidän sillä itseään rasittaakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Kaiken hän on tehnyt kauniisti aikanaan, myös iankaikkisuuden hän on pannut heidän sydämeensä. Ihminen ei vain käsitä tekoja, jotka Jumala on tehnyt, ei alkua eikä loppua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Tulin tietämään, ettei heillä ole muuta onnea kuin iloita ja tehdä hyvää eläessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'Mutta jokaiselle ihmiselle on Jumalan lahja sekin, että hän syö ja juo ja nauttii hyvää kaiken vaivannäkönsä ohessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Tulin tietämään, että kaikki, mitä Jumala tekee, pysyy iäti. Siihen ei ole lisäämistä eikä siitä vähentämistä. Jumala on tehnyt sen niin, että häntä pelättäisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Mitä nyt on, sitä on ollut jo ennen; ja mitä vasta tulee olemaan, sitä on ollut jo ennenkin. Jumala etsii jälleen sen, mikä on mennyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Vielä minä näin auringon alla oikeuspaikan, ja siinä oli vääryys, ja vanhurskauden paikan, ja siinä oli vääryys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Minä sanoin sydämessäni: Vanhurskaan ja väärän tuomitsee Jumala, sillä jokaisella asialla ja jokaisella teolla on siellä aikansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Minä sanoin sydämessäni: Ihmislasten tähden niin on, jotta Jumala heitä koettelisi ja he tulisivat näkemään, että he ovat omassa olossaan eläimiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Sillä ihmislasten käy niin kuin eläintenkin. Sama on kumpienkin kohtalo. Niin kuin toiset kuolevat, niin kuolevat toisetkin. Yhtäläinen henki on kaikilla. Ihmisillä ei ole mitään etua eläinten edellä, sillä kaikki on turhuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Kaikki menee samaan paikkaan. Kaikki on tomusta tullut, ja kaikki palaa tomuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Kuka tietää ihmisen hengestä, kohoaako se ylös, ja eläimen hengestä, vajoaako se alas maahan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Tulin näkemään, ettei ole mitään parempaa, kuin että ihminen iloitsee teoistaan, sillä se on hänen osansa. Sillä kuka tuo hänet takaisin näkemään ilokseen sitä, mikä tulee hänen jälkeensä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Taas minä katselin kaikkea sortoa, jota harjoitetaan auringon alla, ja katso, siinä on sorrettujen kyyneleet, eikä heillä ole lohduttajaa. Väkivaltaa tekee heidän sortajiensa käsi, eikä heillä ole lohduttajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Ylistin vainajia, jotka ovat jo kuolleet, onnellisemmiksi kuin eläviä, jotka ovat vielä elossa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'ja näitä molempia onnellisemmaksi sitä, joka ei vielä ole olemassa eikä ole nähnyt sitä pahaa, mikä tapahtuu auringon alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Minä näin kaikesta vaivannäöstä ja työn kunnollisuudesta, että se on toisen kateutta toista kohtaan. Sekin on turhuutta ja tuulen tavoittelua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Tyhmä panee kädet ristiin ja kalvaa omaa lihaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Parempi on koura täynnä lepoa kuin kädet täynnä vaivannäköä ja tuulen tavoittelua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Minä näin turhuuden auringon alla:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Tuossa on yksinäinen, hänellä ei ole toista, hänellä ei ole poikaa eikä veljeäkään, mutta millään hänen vaivannäöllään ei ole loppua, eikä hänen silmänsä saa kylläänsä rikkaudesta. Kenen hyväksi sitten vaivaa näen ja pidätän itseni nautinnoista? Tämäkin on turhuutta ja on paha asia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Kahden on parempi kuin yksin, sillä heillä on vaivannäöstään hyvä palkka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Jos he lankeavat, niin toinen nostaa ylös toverinsa, mutta voi yksinäistä, jos hän lankeaa! Ei ole toista nostamassa häntä ylös.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Myös, jos kaksi makaa yhdessä, heillä on lämmin, mutta kuinka voi yksinäisellä olla lämmin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Yksinäisen kimppuun voi joku käydä, mutta kaksi pitää sille puolensa. Eikä kolmisäikeinen lanka helposti katkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Parempi on köyhä, mutta viisas nuorukainen, kuin vanha ja tyhmä kuningas, joka ei enää ymmärrä ottaa neuvoista vaarin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Sillä vankilasta tuo lähti tullakseen kuninkaaksi, vaikka oli syntynyt köyhänä edellisen kuninkaan hallitessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Näin kaikkien, jotka elivät ja vaelsivat auringon alla, olevan nuorukaisen puolella, tuon toisen, joka oli astuva hänen sijaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Ei ollut loppua kaikella sillä väellä, niillä kaikilla, joita hän johti. Mutta jälkipolvet eivät hänestä iloitse. Sillä sekin on turhuutta ja tuulen tavoittelua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 17, 'Varo jalkasi, kun menet Jumalan huoneeseen. Tulo kuulemaan on parempi kuin tyhmien teurasuhrin anto, sillä he ovat tietämättömiä, ja niin he tekevät pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Älä ole nopea puhumaan, älköönkä sydämesi kiirehtikö lausumaan sanaa Jumalan edessä, sillä Jumala on taivaassa ja sinä olet maan päällä. Sen tähden olkoot sanasi vähäiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Sillä paljosta työstä tulee uni, ja missä on paljon sanoja, siinä on tyhmä äänessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Kun teet lupauksen Jumalalle, täytä se viivyttelemättä. Sillä hänellä ei ole mielisuosiota tyhmiin. Täytä, mitä lupaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'On parempi, ettet lupaa, kuin että lupaat etkä täytä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Älä anna suusi saattaa ruumistasi syylliseksi, äläkä sano Jumalan enkelin edessä: \"Se oli erehdys\"; miksi Jumalan pitäisi vihastua puheestasi ja hävittää kättesi työt?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Sillä paljot unet ovat pelkkää turhuutta, samoin paljot puheet. Mutta pelkää Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Jos näet köyhää sorrettavan sekä oikeutta ja vanhurskautta poljettavan maakunnassa, älä sitä asiaa ihmettele, sillä ylhäistä vartioi vielä ylhäisempi, ja sitäkin ylhäisemmät heitä molempia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Maalle on kaikessa hyödyksi, että viljellyllä maalla on kuningas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Se, joka rakastaa rahaa, ei saa rahaa kylliksi, eikä voittoa se, joka rakastaa suurta vaurautta. Sekin on turhuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Omaisuuden karttuessa karttuvat sen syöjätkin, ja mitä muuta etua siitä on omistajalleen, kuin että silmillään sen näkee?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Työntekijän uni on makea, söipä hän vähän tai paljon, mutta yltäkylläisyys ei salli rikkaan nukkua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'On raskas vaiva, jonka näin auringon alla: rikkaus, joka on säilytetty onnettomuudeksi omistajalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Se rikkaus katoaa onnettoman tapauksen kautta, ja jos hänelle on syntynyt poika, hänen käsiinsä ei jää mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Niin kuin hän tuli äitinsä kohdusta, niin hänen on alastomana jälleen mentävä pois, samoin kuin tulikin. Hän ei saa vaivannäöstään mitään, minkä veisi täältä kädessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Raskas vaiva on tämäkin: aivan niin kuin hän tuli, hänen on lähdettävä. Mitä hyötyä hänellä sitten on siitä, että on nähnyt vaivaa tuulen hyväksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Myös hän kuluttaa kaikki päivänsä pimeydessä, ja hänellä on paljon surua, kärsimystä ja mielipahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Katso, minkä minä olen tullut näkemään: on hyvää ja kaunista syödä ja juoda ja nauttia hyvää kaiken vaivannäkönsä ohessa, jolla ihminen vaivaa itseään auringon alla elämänsä lyhyinä päivinä, jotka Jumala on hänelle antanut. Sillä se on hänen osansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Sekin on Jumala lahja, jos Jumala kenelle ihmiselle antaa rikkautta ja tavaraa ja sallii hänen syödä siitä ja saada osansa ja iloita vaivannäkönsä ohessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Sillä hän ei tule niin paljon muistelleeksi elämänsä päiviä, kun Jumala vastaa hänen sydämensä iloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Tämäkin on paha, jonka olen nähnyt auringon alla ja joka raskaasti painaa ihmistä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'että Jumala antaa miehelle rikkautta, tavaraa ja kunniaa, niin ettei hänen sielultaan puutu mitään kaikesta siitä, mitä hän toivoo, mutta Jumala ei salli hänen nauttia siitä, vaan siitä nauttii vieras. Se on turhuutta ja raskas kärsimys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Vaikka syntyisi miehelle sata lasta ja hän eläisi monia vuosia ja hänen vuosiensa päivät olisivat paljot, mutta hän ei saisi tyydyttää omaa haluaan omaisuudellaan eikä saisi edes hautaustakaan, niin sanon, että keskenmennyt on häntä onnellisempi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Sillä hän tuli turhaan ja meni pimeyteen, ja pimeyteen peittyi hänen nimensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Hän ei nähnyt aurinkoa eikä sitä tuntenut. Keskenmenneen lepo on parempi kuin hänen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Vaikka hän eläisi kaksi kertaa tuhat vuotta, mutta ei saisi nähdä onnea – eikö kuitenkin kaikki mene samaan paikkaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Sillä kaikki ihmisen vaivannäkö tapahtuu hänen oman suunsa hyväksi, eikä kuitenkaan hänen halunsa täyty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Sillä mitä etua on viisaalla tyhmään nähden, ja mitä köyhällä siitä, että hän osaa vaeltaa elävien edessä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Parempi on silmän näkö kuin halun haihattelu. Tämäkin on turhuutta ja tuulen tavoittelua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Mitä on olemassa, sille on pantu nimi jo muinoin, ja on ollut edeltä tunnettua, mikä ihminen on. Ei hän voi riidellä väkevämpänsä kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Sillä niin on: puheen paljous lisää turhuutta. Mitä etua ihmiselle on siitä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Sillä kuka tietää, mikä on ihmiselle hyvä elämässä hänen elämänsä lyhyinä, turhina päivinä, jotka hän viettää kuin varjo. Ja kuka ilmaisee ihmiselle, mitä on tuleva hänen jälkeensä auringon alla?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Hyvä nimi on parempi kuin kallis öljy, ja kuolinpäivä parempi kuin syntymäpäivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Parempi kuin pitotaloon on mennä surutaloon, sillä siinä on kaikkien ihmisten loppu, ja elossa oleva painaa sen mieleensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Suru on parempi kuin nauru, sillä sydämelle on hyväksi, että kasvot ovat murheelliset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Viisaitten sydän on surutalossa, tyhmien sydän ilonpidossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Parempi on kuulla viisaan nuhdetta, kuin olla kuulemassa tyhmien laulua,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'sillä niin kuin orjantappuroiden rätinä padan alla on tyhmän nauru. Sekin on turhuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Sillä väärä voitto tekee viisaan hulluksi, ja lahja turmelee sydämen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Asian loppu on parempi kuin sen alku, ja pitkämielinen on parempi kuin ylevämielinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Älköön mielesi olko nopea vihaan, sillä viha pesiytyy tyhmien poveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Älä sano: \"Mikä siinä on, että entiset ajat olivat paremmat kuin nykyiset?\" Sillä sitä et viisaudesta kysy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Viisaus on parempi kuin perintöosa ja etu niille, jotka ovat näkemässä aurinkoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Sillä viisauden varjossa on kuin rahan varjossa, mutta tieto on hyödyllisempi: viisaus pitää haltijansa elossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Katso Jumalan tekoja, sillä kuka voi suoristaa sen, minkä hän on vääräksi tehnyt?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Hyvänä päivänä ole hyvillä mielin, ja pahana päivänä ymmärrä, että toisen niin kuin toisenkin on Jumala tehnyt, koska ihminen ei saa mitään siitä, mikä hänen jälkeensä tulee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Kaikkea olen tullut näkemään turhina päivinäni: on vanhurskaita, jotka hukkuvat vanhurskaudessaan, ja on jumalattomia, jotka elävät kauan pahuudessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Älä ole kovin vanhurskas äläkä esiinny hyvin viisaana: miksi tuhoaisit itsesi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Älä ole kovin jumalaton, äläkä ole tyhmä: miksi kuolisit ennen aikaasi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Hyvä on, että pidät kiinni toisesta etkä hellitä kättäsi toisestakaan, sillä Jumalaa pelkäävä selviää näistä kaikista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Viisaus auttaa viisasta voimakkaammin kuin kymmenen vallanpitäjää, jotka ovat kaupungissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Sillä ei ole maan päällä ihmistä niin vanhurskasta, että hän tekisi vain hyvää eikä tekisi syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Älä myöskään pane mieleesi kaikkia puheita, mitä puhutaan, ettet kuulisi palvelijasi sinua kiroilevan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Sillä oma sydämesikin tietää, että myös sinä olet monta kertaa kiroillut muita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Kaiken tämän olen viisaudella koetellut. Minä sanoin: \"Tahdon tulla viisaaksi\", mutta se pysyi minusta kaukana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Kaukana on kaiken olemus ja syvällä, syvällä; kuka sen löytää?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Minä ryhdyin sydämessäni oppimaan, miettimään ja etsimään viisautta ja tutkistelun tuloksia tullakseni tuntemaan jumalattomuuden typeryydeksi ja tyhmyyden mielettömyydeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'Minä löysin sen, mikä on kuolemaa katkerampi: naisen, joka on verkko, jonka sydän on ansa ja jonka kädet ovat kahleet. Se, joka on otollinen Jumalan edessä, pelastuu hänestä, mutta synnintekijä häneen takertuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Katso, tämän olen löytänyt, sanoi saarnaaja, pyrkiessäni kohta kohdalta löytämään järkevän tuloksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Sitä, mitä sieluni on yhä etsinyt, mutta mitä en ole löytänyt, on tämä: olen löytänyt tuhannesta yhden miehen, mutta heistä kaikista en ole löytänyt yhtään naista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Katso, tämän ainoastaan olen löytänyt: että Jumala on tehnyt ihmiset suoriksi, mutta itse he keksivät monia juonia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Kuka on viisaan vertainen, ja kuka osaa selittää asian? Ihmisen viisaus kirkastaa hänen kasvonsa, ja hänen kasvojensa ankaruus muuttuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Minä sanon: Ota vaari kuninkaan käskystä, varsinkin Jumalan kautta vannotun valan tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Älä ole nopea luopumaan hänestä, äläkä asetu pahan asian puolelle, sillä hän tekee, mitä tahtoo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'Sillä kuninkaan sana on voimakas, ja kuka voi sanoa hänelle: Mitä teet?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Se, joka käskyn pitää, ei tiedä pahasta asiasta, ja viisaan sydän tietää ajan ja tuomion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Sillä jokaisella asialla on aikansa ja tuomionsa, ihmistä näet painaa raskaasti hänen pahuutensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Hän ei tiedä, mitä on tuleva, sillä kuka ilmaisee hänelle, mitä on tuleva?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Ihminen ei ole tuulen valtias, että hän voisi sulkea tuulen. Kukaan ei hallitse kuolinpäivää, ei ole pääsyä sodasta, eikä jumalattomuus pelasta harjoittajaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Kaiken tämän tulin näkemään, kun käänsin sydämeni tutkimaan kaikkea, mitä auringon alla tapahtuu aikana, jolloin ihminen vallitsee toista ihmistä hänen onnettomuudekseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Sitten minä näin, kuinka jumalattomat haudattiin ja menivät lepoon, mutta ne, jotka olivat oikein tehneet, saivat lähteä pois pyhästä paikasta ja joutuivat unohduksiin kaupungissa, jossa olivat sitä harjoittaneet. Sekin on turhuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Jos tuomio pahasta teosta ei tule pian, ihmislapset rohkaistuvat tekemään pahaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'koska syntinen saa tehdä pahaa sata kertaa ja elää kauan. Tosin tiedän, että Jumalaa pelkääville käy hyvin, sen tähden että he häntä pelkäävät,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'mutta että jumalattomalle ei käy hyvin eikä hän saa jatkaa päiviään pitkiksi kuin varjo, sen tähden ettei hän pelkää Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Turhuutta on sekin, mitä tapahtuu maan päällä, kun on vanhurskaita, joiden käy, kuin olisivat tehneet jumalattomien tekoja, ja on jumalattomia, joiden käy, kuin olisivat tehneet vanhurskaitten tekoja. Sanoin: sekin on turhuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Niin minä ylistin iloa, koska ihmisellä ei ole auringon alla mitään parempaa kuin syödä ja juoda ja olla iloinen. Se seuraa häntä hänen vaivannäkönsä ohessa hänen elämänsä päivinä, jotka Jumala on antanut hänelle auringon alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Kun käänsin sydämeni oppimaan viisautta ja katsomaan työtä, jota tehdään maan päällä saamatta untakaan silmiin päivällä tai yöllä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'niin tulin näkemään kaikista Jumalan teoista, ettei ihminen voi käsittää sitä, mitä tapahtuu auringon alla. Sillä ihminen kyllä näkee vaivaa etsiessään, mutta hän ei käsitä. Jos viisas luuleekin tietävänsä, hän ei kuitenkaan voi käsittää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Sillä painoin mieleeni kaiken tämän ja pyrin saamaan selvän tästä kaikesta, kuinka näet vanhurskaat ja viisaat ja heidän tekonsa ovat Jumalan kädessä. Ei rakkaus eikä vihakaan ole ihmisen tiedettävissä. Kaikkea hänellä voi olla edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Kaikkea voi tapahtua kaikille. Sama kohtalo on vanhurskaalla ja jumalattomalla, hyvällä, puhtaalla ja saastaisella, uhraajalla ja sillä, joka ei uhraa. Hyvän käy samoin kuin syntisen ja vannojan kuin valaa pelkäävänkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Tämä on pahaa kaikessa, mitä tapahtuu auringon alla, että kaikilla on sama kohtalo, ja myös se, että ihmislasten sydän on täynnä pahaa ja että mielettömyys on heillä sydämessä heidän elinaikansa, ja sen jälkeen he menevät vainajien luo!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Onhan sillä, joka on valittu olemaan kaikkien elävien seurassa, toivoa. Sillä elävä koira on parempi kuin kuollut leijona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Sillä elävät tietävät, että heidän on kuoltava, mutta kuolleet eivät tiedä mitään, eikä heitä palkita, vaan heidän muistonsa on unohdettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Myös heidän rakkautensa, vihansa ja intohimonsa ovat jo aikoja sitten menneet, eikä heillä ole milloinkaan enää osaa missään, mitä tapahtuu auringon alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Tule siis, syö leipäsi ilolla ja juo viinisi hyvillä mielin, sillä jo aikaa on Jumala hyväksynyt nuo tekosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Vaatteesi olkoot aina valkoiset, ja öljyä älköön puuttuko päästäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Nauti elämää vaimon kanssa, jota rakastat, kaikkina turhan elämäsi päivinä, jotka Jumala on sinulle antanut auringon alla – kaikkina turhina päivinäsi. Sillä se on sinun osasi elämässä ja vaivannäössäsi, jolla vaivaat itseäsi auringon alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Tee kaikki, mitä voimallasi saat tehdyksi, sillä ei ole tekoa, ei ajatusta, ei tietoa eikä viisautta haudassa, jonne olet menevä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Taas minä tulin näkemään auringon alla, ettei juokseminen ole kerkiävien vallassa, ei sota sankareitten, ei leipä viisaitten, ei rikkaus ymmärtäväisten eikä suosio taitavien vallassa, vaan aika ja kohtalo kohtaavat kaikkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Sillä ihminen ei tiedä aikaansa, niin kuin eivät kalatkaan, jotka tarttuvat pahaan verkkoon, eivätkä linnut, jotka käyvät kiinni paulaan. Niin kuin ne, niin pyydystetään ihmislapsetkin pahana aikana, joka äkkiä yllättää heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Tämänkin tulin näkemään viisaudeksi auringon alla, ja se oli minusta suuri:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Oli pieni kaupunki ja siinä vähän miehiä. Ja suuri kuningas tuli sitä vastaan, saartoi sen ja rakensi sitä vastaan suuria vallituksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'Mutta siellä oli köyhä, viisas mies, ja hän pelasti kaupungin viisaudellaan. Mutta ei kukaan ihminen muistanut köyhää miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Minä sanoin: Viisaus on parempi kuin voima, mutta köyhän viisautta halveksitaan, eikä hänen sanojaan kuulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Viisaitten sanat, hiljaisuudessa kuullut, ovat paremmat kuin hallitsijoiden huuto tyhmien joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Viisaus on parempi kuin sota-aseet, mutta yksi ainoa syntinen hävittää paljon hyvää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Kuolleet kärpäset pilaavat voiteentekijän voiteen ja saavat sen haisemaan. Pieni tyhmyys painaa enemmän kuin viisaus ja kunnia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Viisaan sydän vetää oikealle, tyhmän vasemmalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Tietä kävellessäkin tyhmältä puuttuu mieltä: jokaiselle hän ilmaisee olevansa tyhmä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Jos hallitsijan henki nousee sinua vastaan, älä jätä paikkaasi, sillä sävyisyys pidättää suurista synneistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Se, minkä olen nähnyt auringon alla, on onnettomuus, vallanpitäjästä lähtenyt erehdys:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'tyhmyys asetetaan ylhäiseen korkeuteen, ja rikkaat saavat istua alhaalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Olen nähnyt palvelijat hevosten selässä ja ruhtinaat kävelemässä kuin palvelijat maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Se, joka kuoppaa kaivaa, siihen putoaa. Sitä käärme puree, joka muuria purkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Se, joka kiviä louhii, niihin loukkaantuu. Se, joka puita pilkkoo, joutuu siinä vaaraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Jos rauta on tylsä eikä terää tahkota, täytyy ponnistaa voimia. Mutta viisaudesta on hyötyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Jos käärme puree silloin, kun sitä ei ole lumottu, lumoajalla ei ole hyötyä taidostaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Sanat viisaan suusta saavat suosiota, mutta tyhmän nielevät hänen omat huulensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Hänen suunsa sanojen alku on tyhmyyttä, ja hänen puheensa loppu pahaa mielettömyyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Tyhmä puhuu paljon. Mutta ihminen ei tiedä, mitä tuleva on. Kuka ilmaisee hänelle, mitä hänen jälkeensä tulee?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Oma vaivannäkö väsyttää tyhmän, joka ei osaa kulkea kaupunkiinkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Voi sinua, maa, jolla on kuninkaana poikanen ja jonka ruhtinaat jo aamulla aterioivat!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Onnellinen sinä, maa, jolla on jalosukuinen kuningas ja jonka ruhtinaat aterioivat oikeaan aikaan voimissaan ollen eikä juopotellen!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Missä laiskuus on, siinä kattovasat vaipuvat; ja missä kädet velttoina riippuvat, huoneeseen tippuu vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Hauskuudeksi ateria laitetaan, ja viini ilahduttaa elämää, mutta rahalla saa kaikkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Älä ajatuksissasikaan kiroile kuningasta, äläkä makuuhuoneessasikaan kiroile rikasta, sillä taivaan linnut kuljettavat äänesi ja siivelliset ilmaisevat sanasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Lähetä leipäsi vetten yli, sillä ennen pitkää löydät sen jälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Anna osa seitsemälle, kahdeksallekin, sillä et tiedä, mitä onnettomuutta tulee maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Jos pilvet tulevat täyteen sadetta, ne tyhjentävät sen maahan. Ja jos puu kaatuu kohden etelää tai pohjoista, niin mihin paikkaan puu kaatuikin, siihen se jää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Se, joka tuulta tarkkailee, ei kylvä, eikä se, joka pilviä katselee, leikkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Niin kuin et tiedä tuulen teitä etkä luitten rakentumista raskaana olevan kohdussa, niin et myöskään tiedä Jumalan tekoja, hänen, joka tekee kaiken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Kylvä siemenesi aamulla äläkä hellitä kättäsi ehtoollakaan. Sillä et tiedä, onnistuuko tuo vai tämä vai onko kumpikin yhtä hyvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Suloinen on valo, ja silmille tekee hyvää nähdä aurinkoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Niin, jos ihminen elää moniakin vuosia, iloitkoon hän niistä kaikista, mutta muistakoon pimeitä päiviä, sillä niitä tulee paljon. Kaikki, mikä tulee, on turhuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Iloitse, nuorukainen, nuoruudessasi, ja sydämesi ilahduttakoon sinua nuoruusikäsi päivinä. Vaella sydämesi teitä ja silmiesi halun mukaan, mutta tiedä: Jumala tuo sinut tuomiolle kaikesta tästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Karkota suru sydämestäsi ja torju kärsimys ruumiistasi, sillä nuoruus ja elämän aamurusko ovat turhuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Vielä, muista Luojaasi nuoruudessasi ennen kuin pahat päivät tulevat ja joutuvat ne vuodet, joista olet sanova:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, '\"Nämä eivät minua miellytä\" siihen asti, kunnes aurinko, päivänvalo, kuu ja tähdet pimenevät ja uudet pilvet tulevat sateen jälkeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'Silloin huoneen vartijat vapisevat ja voimamiehet käyvät koukkuisiksi ja jauhajanaiset ovat joutilaina, kun ovat vähissä, ja ikkunoista kurkistelijat jäävät pimeään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'ja kadulle vievät ovet sulkeutuvat, myllyn ääni vaimenee, noustaan linnun lauluun ja kaikki laulun tyttäret hiljentyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'Myös pelätään mäkiä, tiellä on kauhuja, mantelipuu kukkii, heinäsirkalla on taakkansa, ja kapriisin nuppu puhkeaa. Sillä ihminen menee iankaikkiseen majaansa, ja valittajat kiertelevät kaduilla –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'siihen asti, kunnes hopealanka katkeaa, kultamalja särkyy, vesiastia rikkoutuu lähteellä ja ammennuspyörä putoaa särkyneenä kaivoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'Tomu palaa maahan, niin kuin on ollutkin, ja henki palaa Jumalan luo, joka on sen antanutkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Turhuuksien turhuus, sanoi saarnaaja. Kaikki on turhuutta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Sen lisäksi, että saarnaaja oli viisas, hän myös opetti kansalle tietoa, punnitsi, harkitsi ja sommitteli paljon sananlaskuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Saarnaaja etsi löytääkseen kelvollisia sanoja, vilpittömässä mielessä kirjoitettuja, totuuden sanoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Viisaitten sanat ovat kuin tutkaimet ja kootut lauseet kuin isketyt naulat. Ne ovat saman Paimenen antamia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Vielä näiden lisäksi: Poikani, ota varoituksesta vaari. Paljolla kirjojen tekemisellä ei ole loppua, ja paljo tutkistelu väsyttää ruumiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Loppusana kaikesta, mitä on kuultu, on tämä: Pelkää Jumalaa ja pidä hänen käskynsä, sillä niin tulee jokaisen ihmisen tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Sillä Jumala tuo kaikki teot tuomiolle, joka kohtaa kaikkea salassa olevaa, olkoon hyvää tai pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Laulujen laulu Salomon kirjoittama.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Hän suudelkoon minua suunsa suudelmilla. Sillä rakkautesi on suloisempi kuin viini.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Suloinen on voiteittesi tuoksu, vuodatettu öljy on nimesi. Sen tähden nuoret neitsyet rakastavat sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Vedä minut mukaasi, rientäkäämme! Kuningas on tuonut minut kammioihinsa. Riemuitsemme ja iloitsemme sinusta ja ylistämme rakkauttasi enemmän kuin viiniä. Vilpittömästi he sinua rakastavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, '\"Minä olen musta, mutta ihana, te Jerusalemin tyttäret, kuin Keedarin teltat, kuin Salomon seinäverhot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Älkää katsoko sitä, että minä olen musta, päivän paahtama. Äitini pojat vihastuivat minuun, panivat minut viinitarhojen vartijaksi – omaa viinitarhaani en vartioinut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, '\"Sano minulle sinä, jota sieluni rakastaa, missä laumaasi paimennat, missä annat sen keskipäivällä levätä. Miksi hunnutettuna joutuisin toveriesi laumojen luo!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, '\"Jos et sitä tiedä, sinä naisista kaunein, käy lammasten jälkiä ja kaitse kilejäsi paimenten telttapaikoilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, '\"Tammaani, joka on faraon vaunujen edessä, sinut, armaani, vertaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Ihanat ovat poskesi ketjuineen ja kaulasi helminauhoineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Teemme sinulle kultaketjut sekä hopeasta niihin nastat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, '\"Kuninkaan istuessa pöydässään nardukseni levitti tuoksuaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Rakkaani on minulle mirhakimppu, joka lepää yön rintojeni välissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Rakkaani on kooferpensaan kukkaterttu Een-Gedin viinitarhoista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, '\"Katso, kaunis sinä olet, armaani. Katso, kaunis olet, silmäsi ovat kyyhkyset.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, '\"Katso, kaunis sinä olet, rakkaani. Kuinka suloinen, kuinka ihana on vuoteemme!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Huoneittemme seininä ovat setripuut, kattonamme sypressit.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, '\"Minä olen Saaronin kukka, olen laaksojen lilja.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, '\"Kuin lilja orjantappuroiden keskellä, on armaani tyttärien keskellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, '\"Kuin omenapuu metsän puiden keskellä on rakkaani nuorukaisten keskellä. Minä haluan istua sen varjossa, ja sen hedelmä on suussani makea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Hän on vienyt minut viinimajaan. Rakkaus on hänellä lippuna ylläni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Vahvistakaa minua rypälekakuilla, virvoittakaa minua omenilla, sillä minä olen rakkaudesta sairas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Hänen vasen kätensä on pääni alla, ja hänen oikea kätensä halaa minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Minä vannotan teitä, te Jerusalemin tyttäret, gasellien tai kedon peurojen kautta: älkää herätelkö, älkää häiritkö rakkautta, ennen kuin se itse haluaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Rakkaani ääni! Katso, tuolla hän tulee hypellen vuorilla ja loikkien kukkuloilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Rakkaani on gasellin kaltainen tai nuoren peuran. Katso, tuolla hän seisoo seinämme takana katsellen ikkunasta sisään ja kurkistellen ristikoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Rakkaani vastasi ja sanoi minulle: \"Nouse, armaani, sinä kaunoiseni, ja tule.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Sillä katso, talvi on väistynyt, sateet ovat ohi ja menneet menojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Kukkaset ovat puhjenneet maahan, laulun aika on tullut, ja metsäkyyhkysen ääni kuuluu maassamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Viikunapuu tekee keväthedelmää, viiniköynnökset ovat kukassa ja tuoksuvat. Nouse, armaani, sinä kaunoiseni, ja tule.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Kyyhkyseni, joka piileksit kallionkoloissa ja vuorenjyrkänteillä, anna minun nähdä kasvosi, anna minun kuulla äänesi, sillä suloinen on äänesi ja ihanat ovat kasvosi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Ottakaamme ketut kiinni, pienet ketut, jotka turmelevat viinitarhoja, sillä viinitarhamme ovat kukassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Rakkaani on minun, ja minä hänen. Hän paimentaa liljojen keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Kunnes päivä kallistuu iltaan ja varjot pakenevat. Kiertele, rakkaani, kuin gaselli, kuin nuori peura tuoksuvilla vuorilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Yöllä vuoteellani minä etsin häntä, jota sieluni rakastaa. Minä etsin häntä, mutta en löytänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, '\"Nousen ja kiertelen kaupunkia, katuja ja toreja, etsin häntä, jota sieluni rakastaa.\" Etsin, mutta en löytänyt häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Minut kohtasivat vartijat, jotka kaupungilla kiertelevät. \"Oletteko nähneet häntä, jota sieluni rakastaa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Tuskin olin kulkenut heidän ohitseen, kun löysin hänet, jota sieluni rakastaa. Tartuin häneen enkä hellittänyt hänestä, ennen kuin olin saattanut hänet äitini taloon, synnyttäjäni kammioon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Minä vannotan teitä, te Jerusalemin tyttäret, gasellien tai kedon peurojen kautta: älkää herätelkö, älkää häiritkö rakkautta, ennen kuin se itse haluaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Mikä tuolla tulee erämaasta kuin savupatsaat tuoksuen mirhalta ja suitsukkeelta, kaikenlaisilta kauppiaan hajujauheilta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Katso, siinä on Salomon kantotuoli ja sen ympärillä kuusikymmentä sankaria, Israelin sankareita,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'kaikki miekkamiehiä, sotaan harjoitettuja. Jokaisella on miekka kupeellaan öiden kauhuja vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Kuningas Salomo teetti itselleen kantotuolin Libanonin puista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Sen patsaat hän teetti hopeasta, sen selustan kullasta, sen istuimen purppurasta, ja sisältä sen koristeli Jerusalemin tyttärien rakkaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Tulkaa ulos, Siionin tyttäret, ja katsokaa kuningas Salomoa, katsokaa kruunua, jolla hänen äitinsä hänet kruunasi hänen hääpäivänään, hänen sydämensä ilonpäivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, '\"Katso, kaunis sinä olet, armaani. Katso, kaunis sinä olet. Kyyhkyset ovat silmäsi huntusi takana. Hiuksesi ovat kuin vuohilauma, joka laskeutuu Gileadin vuorilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Hampaasi ovat kuin lauma kerittyjä lampaita, pesusta nousseita, kaikilla kaksoset, eikä yhtään karitsatonta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Kuin purppuranauha ovat huulesi, ja suusi on suloinen. Kuin halkaistu granaattiomena on ohimosi huntusi takana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Kaulasi on kuin Daavidin torni, asevarastoksi rakennettu. Siitä riippuu tuhat kilpeä, kaikki sankarien varustuksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Rintasi ovat kuin kaksi nuorta peuraa, kuin gasellikaksoset, jotka käyvät laitumella liljojen keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Siksi kunnes päivä alenee ja varjot pakenevat, kävelen mirhavuorelle ja suitsukekukkulalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Kaikin puolin olet kaunis, armaani. Sinussa ei ole ainoatakaan virhettä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, '\"Tule kanssani Libanonilta, morsiameni, tule kanssani Libanonilta. Lähde pois Amanan huipulta, Senirin ja Hermonin huipuilta, leijonien leposijoilta ja panttereiden vuorilta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, '\"Olet lumonnut minut, siskoni, morsiameni, lumonnut minut yhdellä silmäykselläsi, yhdellä kaulakoristeesi osalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Kuinka ihana onkaan rakkautesi, siskoni, morsiameni! Kuinka paljon viiniä suloisempaa on rakkautesi, kaikkia balsameja suloisempi voiteittesi tuoksu!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Huulesi pisaroivat hunajaa, morsiameni. Mesi ja maito ovat kielesi alla, ja vaatteittesi tuoksu on kuin Libanonin tuoksu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, '\"Suljettu puutarha on siskoni, morsiameni, suljettu kaivo, lukittu lähde.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Sinä versot kuin paratiisi, jossa on granaattiomenia sekä erinomaisia hedelmiä, kooferpensaan kukkia ja narduksia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'nardusta ja sahramia, kalmoruokoa ja kanelia sekä kaikenlaisia suitsukepuita, mirhaa ja aloeta sekä kaikkia parhaita balsamikasveja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Sinä olet puutarhojen lähde, elävien vetten kaivo, jotka Libanonilta virtaavat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, '\"Herää, pohjatuuli, tule, etelätuuli. Puhalla puutarhaani, että sen balsamituoksut tulvahtaisivat. Tulkoon puutarhaansa rakkaani ja syököön sen erinomaisia hedelmiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, '\"Tulen puutarhaani, siskoni, morsiameni. Poimin mirhani ja balsamini, syön mesileipäni ja hunajani, juon viinini ja maitoni.\" Syökää, ystävät, juokaa, juokaa runsain määrin, rakkaat veljeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Minä nukuin, mutta sydämeni valvoi. Kuule, rakkaani kolkuttaa: \"Avaa minulle, siskoseni, armaani, kyyhkyseni, puhtoiseni. Sillä pääni on kastetta täynnä, kiharani yön pisaroita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, '\"Olen viittani riisunut; pukisinko sitä enää päälleni? Olen jalkani pessyt; likaisinko ne taas?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Rakkaani pisti kätensä ovenreiästä sisään. Silloin sydämeni liikkui häntä kohden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Minä nousin avaamaan rakkaalleni, ja käteni pisaroivat mirhaa ja sormeni sulaa mirhaa ovensalvan kädensijoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Minä avasin rakkaalleni, mutta rakkaani oli kadonnut, mennyt menojaan. Hänen puhuessaan oli sieluni vallannut hämmennys. Etsin häntä, mutta en häntä löytänyt. Huusin häntä, mutta hän ei minulle vastannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Minut kohtasivat vartijat, jotka kaupunkia kiertelevät. He löivät minua ja haavoittivat minua. Päällystakin riistivät yltäni muurien vartijat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, '\"Minä vannotan teitä, te Jerusalemin tyttäret: jos löydätte rakkaani, mitä hänelle sanotte? Sanokaa, että minä olen rakkaudesta sairas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, '\"Mikä tekee rakkaasi muita paremmaksi, sinä naisista kaunein? Mikä tekee rakkaasi muita paremmaksi, että meitä näin vannotat?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, '\"Rakkaani on valkoinen ja punainen, kymmentä tuhatta jalompi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Hänen päänsä on kultaa, puhtainta kultaa, hänen kiharansa kuin palmunlehvät, mustat kuin korppi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Hänen silmänsä ovat kuin kyyhkyset purojen partaalla, jotka ovat maidossa kylpeneet ja istuvat runsauden ääressä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Hänen poskensa ovat kuin balsamilava, kuin tuoksuvat voiteet. Hänen huulensa ovat liljat ja pisaroivat sulaa mirhaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Hänen käsivartensa ovat kultatangot täynnä krysoliitteja. Hänen lantionsa on safiireilla peitettyä norsunluuta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Hänen jalkansa ovat marmoripatsaat aitokultaisilla jalustoilla. Hän on näöltään kuin Libanon valiosetripuineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Hänen suunsa on sula makeus. Hän on pelkkää suloutta. Sellainen on rakkaani, sellainen on ystäväni, te Jerusalemin tyttäret.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, '\"Minne rakkaasi on mennyt, sinä naisista kaunein? Minne rakkaasi on kääntynyt? Etsikäämme häntä kanssasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, '\"Rakkaani on mennyt puutarhaansa, balsamilavojen luo, paimentamaan puutarhoissa ja poimimaan liljoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Minä olen rakkaani oma, ja rakkaani on minun – hän, joka paimentaa liljojen keskellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, '\"Kaunis kuin Tirsa olet sinä, armaani, suloinen kuin Jerusalem, pelottava kuin sotajoukot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Käännä pois silmäsi minusta, sillä ne kiehtovat minua. Hiuksesi ovat kuin vuohilauma, joka laskeutuu Gileadilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Hampaasi ovat kuin lauma uuhia, pesulta nousseita, kaikilla kaksoset, ei yhtään karitsatonta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Kuin halkaistu granaattiomena on ohimosi huntusi takana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Kuusikymmentä on kuningatarta ja kahdeksankymmentä sivuvaimoa ja neitsyitä määrättömästi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'yksi ainoa on kyyhkyseni, puhtoiseni, äitinsä ainoa, synnyttäjänsä valittu. Hänet nähdessään tyttäret kiittävät hänen autuuttaan, kuningattaret ja sivuvaimot ylistävät häntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, '\"Kuka on neito, joka nousee kuin aamunkoi, kauniina kuin kuu, kirkkaana kuin päivänpaiste, pelottavana kuin sotajoukot?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, '\"Pähkinätarhaan menin katselemaan laakson vihreyttä, katsomaan, joko viiniköynnös versoo ja joko granaattipuut kukkivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Tietämättäni sieluni asetti minut jalon kansani vaunuihin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, '\"Palaa, palaa, suulemitar! Palaa, palaa katsellaksemme sinua!\" \"Mitä katselette suulemittaressa? Mahanaimin karkeloa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, '\"Kuinka kauniisti astelet kengissäsi, sinä ruhtinaan tytär! Lanteesi kaartuvat kuin kaulakorut, taitajan kätten tekemät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Povesi on pyöreä malja, josta sekoitettua viiniä älköön puuttuko. Sinun uumasi on vehnäkuhilas, liljojen ympäröimä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Sinun molemmat rintasi ovat kuin kaksi nuorta peuraa, kuin gasellin kaksoset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Kaulasi on kuin norsunluutorni. Silmäsi kuin Hesbonin lammikot Bat-Rabbimin portin luona. Nenäsi on kuin Libanonin torni, joka katselee Damaskoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Pääsi kohoaa kuin Karmel, ja pääsi palmikot ovat kuin purppura. Kuningas on kiedottu kutreihisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, '\"Kuinka kaunis olet, kuinka suloinen, sinä rakkaus, riemuinesi! –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Vartalosi on kuin palmupuu, ja rintasi kuin rypäleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Minä sanoin: nousen palmupuuhun, tartun sen oksiin. Olkoot silloin rintasi kuin viinirypäleet ja hengityksesi tuoksu kuin omenien tuoksu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Olkoon suusi kuin hyvä viini.\" \"Viini, joka helposti valahtaa rakkaaseeni ja kostuttaa nukkuvien huulet!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Minä olen rakkaani oma, ja minuun on hänen halunsa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, '\"Tule, rakkaani, lähtekäämme maalle, yöpykäämme kyliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Käykäämme varhain viinitarhoihin katsomaan, joko viiniköynnös kukkii ja nuput aukeavat, joko granaattipuut kukkivat. Siellä annan sinulle rakkauteni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 14, 'Lemmenmarjat tuoksuvat, ja oviemme edessä kasvaa kaikenlaisia jaloja hedelmiä. Olen säästänyt ne, sekä uudet että vanhat, sinulle, rakkaani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, '\"Olisitpa kuin oma veljeni, äitini rintoja imenyt! Tapaisin sinut ulkona, suutelisin sinua, eikä kukaan halveksisi minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Johdattaisin sinut, veisin äitini taloon, ja hän neuvoisi minua. Antaisin mausteviiniä juodaksesi, granaattiomenani mehua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Hänen vasen kätensä on pääni alla, ja hänen oikea kätensä halaa minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Minä vannotan teitä, te Jerusalemin tyttäret: älkää herätelkö, älkää häiritkö rakkautta, ennen kuin se itse haluaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Kuka tuolla tulee erämaasta rakkaaseensa nojaten? \"Omenapuun alla sinut herätin. Siellä sai sinut äitisi kerran, siellä sai sinut synnyttäjäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Pane minut sinetiksi sydämellesi, sinetiksi käsivarrellesi. Sillä rakkaus on väkevä kuin kuolema, ankara kuin helvetti on sen kiivaus, sen hehku on tulen hehku, on polttava liekki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Eivät suuret vedet voi rakkautta sammuttaa, eivät virrat sitä tulvaansa upottaa. Jos joku tarjoaisi kaikki talonsa tavarat rakkauden hinnaksi, häntä vain halveksittaisiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, '\"Meillä on pieni sisko, jolla ei ole vielä rintoja. Mitä teemme siskollemme sinä päivänä, jona häntä kositaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Jos hän on muuri, rakennamme sen päälle hopealinnan. Jos hän on ovi, suljemme sen setrilaudoilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, '\"Minä olen muuri, ja rintani ovat kuin tornit; vaan nyt olen hänen silmissään kuin se, joka löysi rauhan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, '\"Salomolla on viinitarha Baal-Haamonissa. Hän on jättänyt viinitarhan vartijoiden huostaan. Sen hedelmistä mies tuo tuhat hopeasekeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Viinitarhani on omassa hallussani. Sinulle, Salomo, tulkoot ne tuhat, ja sen hedelmän vartijoille kaksisataa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, '\"Sinä puutarhani asukas, toverit kuuntelevat ääntäsi. Anna minunkin kuulla sitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, '\"Riennä, rakkaani, kuin gaselli, kuin nuori peura balsamivuorille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Jesajan, Aamosin pojan, näky, jonka hän näki Juudasta ja Jerusalemista Juudan kuningasten Ussian, Jootamin, Aahaan ja Hiskian päivinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Kuulkaa, taivaat, ota korviisi, maa, sillä Herra puhuu: Minä kasvatin lapset suuriksi, mutta he luopuivat minusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Härkä tuntee omistajansa ja aasi isäntänsä seimen, mutta Israel ei tunne, kansani ei ymmärrä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Voi syntistä kansaa, raskaasti rikkonutta kansakuntaa, pahantekijöiden siementä, kelvottomia lapsia! He ovat hylänneet Herran, pitäneet Israelin Pyhää pilkkanaan, he ovat kääntyneet takaisin luopumukseensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Mihin teitä pitäisi vielä lyödä, kun yhä jatkatte luopumustanne? Koko pää on kipeä, koko sydän sairas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Kantapäästä kiireeseen ei ole tervettä paikkaa, ainoastaan haavoja, mustelmia ja vereksiä lyömiä, joita ei ole puserrettu, ei sidottu eikä öljyllä pehmitetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Maanne on autiona, kaupunkinne ovat tulella poltetut. Peltojanne syövät muukalaiset silmienne edessä. Ne ovat autioina muukalaisten hävittäminä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Jäljelle on jäänyt tytär Siion yksinään kuin maja viinitarhassa, kuin lehvämaja kurkkumaassa, kuin saarrettu kaupunki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Ellei Herra Sebaot olisi jättänyt meistä jäännöstä, meidän olisi käynyt lyhyessä ajassa kuin Sodoman, olisimme tulleet Gomorran kaltaisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Kuulkaa Herran sana, te Sodoman päämiehet, ota korviisi Jumalamme opetus, sinä Gomorran kansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Mitä ovat minulle teidän paljot teurasuhrinne? sanoo Herra. Olen kyllästynyt pässipolttouhreihin ja juottovasikkojen rasvaan. Mullien, karitsojen ja kauristen vereen en mielly.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Kuka teitä vaatii tulemaan kasvojeni eteen tallaamaan esikartanoitani?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Älkää enää tuoko minulle turhaa ruokauhria. Suitsutus on minulle kauhistus. En kärsi uudenkuun juhlaa enkä sapattia, en kokouksen kuuluttamista, en vääryyttä enkä juhlakokousta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Sieluni vihaa uusiakuitanne ja juhla-aikojanne. Ne ovat käyneet minulle kuormaksi, jota olen väsynyt kantamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Kun te ojentelette käsiänne, minä peitän silmäni teiltä. Vaikka kuinka paljon rukoilisitte, en kuule. Kätenne ovat verta täynnä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Peseytykää, puhdistautukaa. Pankaa pois pahat tekonne silmieni edestä, lakatkaa tekemästä pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Oppikaa tekemään hyvää. Toimikaa oikeuden mukaan, ojentakaa väkivaltaista, hankkikaa orvolle oikeus, ajakaa lesken asia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Tulkaa, käykäämme oikeutta keskenämme, sanoo Herra. Vaikka syntinne ovat veriruskeat, ne tulevat lumivalkeiksi. Vaikka ne ovat purppuranpunaiset, ne tulevat villanvalkoisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Jos suostutte ja olette kuuliaisia, tulette syömään maan hyvyyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Mutta jos vastustatte ja niskoittelette, miekka syö teidät. Sillä Herran suu on puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Voi, kuinka onkaan portoksi tullut uskollinen kaupunki! Se oli täynnä oikeutta, siellä asui vanhurskaus, mutta nyt murhamiehet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Hopeasi on muuttunut kuonaksi, jaloviinisi on vedellä laimennettua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Johtajasi ovat niskureita ja varkaiden tovereita. He kaikki rakastavat lahjuksia ja tavoittelevat palkkioita. He eivät hanki orvolle oikeutta, lesken asia ei pääse heidän eteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Sen tähden sanoo Herra, Herra Sebaot, Israelin Väkevä: Voi! Minä hankin lohdutuksen vastustajistani ja kostan vihollisilleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Käännän käteni sinua vastaan ja puhdistan sinusta kuonan kuin lipeällä ja poistan sinusta kaiken lyijyn.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'Palautan tuomarisi entiselleen ja neuvonantajasi sellaisiksi, kuin he olivat alkuaan. Sitten sinua kutsutaan \"vanhurskauden linnaksi\" ja \"uskolliseksi kaupungiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Siion lunastetaan oikeudella ja sen kääntyneet vanhurskaudella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Mutta luopiot ja syntiset sortuvat kaikki yhdessä, ja ne, jotka hylkäävät Herran, hukkuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Sillä he saavat häpeän niistä tammista, joita te himoitsitte, ja pettymyksen puutarhoista, jotka te valitsitte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Sillä teidän käy kuin tammen, jonka lehdet lakastuvat, ja kuin puutarhan, joka on vettä vailla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'Niin taitaja tulee rohtimeksi ja hänen tekonsa kipinäksi, ja molemmat palavat yhdessä, eikä sammuttajaa ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Sana, jonka Jesaja, Aamosin poika, näki Juudasta ja Jerusalemista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'On oleva aikojen lopulla: Herran temppelin vuori on oleva vahva, kaikkia muita vuoria ylempänä, kukkuloista korkeimpana, ja kaikista pakanakansoista vaeltaa virtanaan sinne väkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Monet kansakunnat vaeltavat sinne ja sanovat: Tulkaa mukaan ja nouskaamme Herran vuorelle, Jaakobin Jumalan temppeliin, niin hän opettaa meille tiensä ja me vaellamme hänen polkujaan, sillä Siionista lähtee laki ja Jerusalemista Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Hän tuomitsee pakanoiden kesken ja myöntää oikeuden monille kansakunnille. Silloin he takovat miekkansa aurankärjiksi ja keihäänsä viinivesoimiksi eikä kansa nosta miekkaa toistaan vastaan eivätkä he enää opettele käymään sotia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Jaakobin heimo, lähtekää mukaan! Vaeltakaamme Herran valkeudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Sillä sinä olet hylännyt kansasi, Jaakobin heimon, koska he ovat täynnä idän menoa, täynnä noitia filistealaisten tapaan ja he ovat liittoutuneet muukalaisten kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Hänen maansa on täynnä kultaa ja hopeaa eikä hänen aarteillaan ole loppua. Hänen maansa on täynnä oriita eikä hänen vaunuillaan ole loppua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Hänen maansa on täynnä epäjumalia, ja he kumartavat kättensä tekoja, omien sormiensa luomuksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Mutta ihminen nöyryytetään ja miehen uhma masennetaan, etkä sinä anna heille anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Astu kallion sisään ja kätkeydy tomuun Herran kasvojen kauhulta ja hänen Majesteettinsa kirkkaudelta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Ihmisten kopeat silmät kokevat nöyryytyksen ja ihmisten mahtavuus painetaan alas, ja Herra yksin on korkea sinä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Sillä päivä on Herran Sebaotin, ja se on kaikkea ylvästelyä ja mahtavuutta vastaan ja kaikkea itsekorotusta vastaan, niin että se menee matalaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'ja kaikkia korkeita ja pitkiä Libanonin setrejä vastaan ja kaikkia Baasanin tammia vastaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'ja kaikkia korkeita vuoria ja ylhäisiä kukkuloita vastaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'ja kaikkia korkeita torneja ja kaikkia lujia muureja vastaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'ja kaikkia Tarsiin laivoja ja kaikkea sitä vastaan, mitä mielitellen katsellaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Ihmisten kopeus masentuu ja heidän mahtavuutensa painuu alas. Herra yksin on korkea sinä päivänä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'mutta epäjumalat katoavat kaikki tyynni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'He menevät vuorten onkaloihin ja maaluoliin Herran kauhua ja hänen Majesteettinsa kirkkautta pakoon, kun hän nousee saattamaan maan kauhun valtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'Sinä päivänä ihmiset heittävät myyrille ja lepakoille hopea- ja kultajumalansa, joita he olivat tehneet rukoiltavikseen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'mennäkseen vuorten onkaloihin ja kallioluoliin Herran kauhua ja hänen Majesteettinsa kirkkautta pakoon, kun hän nousee saattamaan maan kauhun valtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Luopukaa siis ihmisistä, jotka ovat henkäys sieraimessa, sillä sellaisiksi heidät on arvioitu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Sillä katso, Herra, Herra Sebaot ottaa pois Jerusalemilta ja Juudalta tuen ja turvan, kaikki leipävarastot ja kaikki vesivarastot,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'sankarin ja soturin, tuomarin ja profeetan, tietäjän ja vanhimman,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'viidenkymmenenpäällikön ja arvossapidetyn, neuvonantajan, tietomiehen ja taikurin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Annan nuorukaiset heille johtajiksi, ja poikaset hallitsevat heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Kansassa toinen sortaa toistaan, jokainen lähimmäistään. Nuorukainen rehentelee vanhusta vastaan, alhainen kunnioitettavaa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Kun veli tarttuu veljeensä isänsä talossa sanoen: \"Sinulla on vielä vaatteet, ryhdy ruhtinaaksemme ja ota huostaasi tämä raunioläjä\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'niin tämä sinä päivänä korottaa äänensä sanoen: \"Ei minusta ole haavoja sitomaan. Talossani ei ole leipää, ei vaatetta, älkää panko minua kansan ruhtinaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Sillä Jerusalem kaatuu ja Juuda kukistuu, koska heidän kielensä ja heidän tekonsa ovat Herraa vastaan ja he uhittelevat hänen kunniansa kasvoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Heidän kasvojensa hahmo todistaa heitä vastaan; syntinsä he tuovat julki kuin sodomalaiset eivätkä niitä salaa. Voi heitä! Itselleen he pahaa tekevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Sanokaa hurskaasta, että hänen käy hyvin, sillä he saavat nauttia tekojensa hedelmiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Voi jumalatonta! Hänen käy pahoin, sillä hänen kättensä teot kostetaan hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Kansani käskijät ovat lapsia, ja naiset sitä hallitsevat. Kansani, autuuttajasi ovat eksyttäjiä. He ovat häivyttäneet sinun polkujesi suunnan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Herra asettuu käymään oikeutta, nousee tuomitsemaan kansoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Herra käy tuomiolle kansansa vanhinten ja sen johtajien kanssa: \"Te olette raiskanneet viinitarhan. Teidän taloissanne on köyhiltä ryöstettyä tavaraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Kuinka saatatte runnella kansaani ja ruhjoa köyhien kasvot?\" sanoo Herra, Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Herra sanoi: Koska Siionin tyttäret ylpeilevät, kulkevat kaula kenossa ja silmillään vilkuillen, astua sipsuttelevat ja nilkkarenkaitaan kilistelevät,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'tekee Herra Siionin tyttärien päälaen rupiseksi, ja Herra paljastaa heidän häpynsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'Sinä päivänä Herra poistaa koreat nilkkarenkaat, otsanauhat, puolikuukorut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'korvarenkaat, rannerenkaat, hunnut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'juhlapäähineet, jalkaketjut, koruvyöt, hajupullot, taikahelyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'sormukset, nenärenkaat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'juhlavaatteet, kaavut, viitat, kukkarot,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'kuparipeilit, pellavapaidat, turbaanit ja päällysharsot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'Tuoksun sijaan tulee löyhkä, vyön sijaan nuora, käherretyn tukan sijaan kaljuus, korupuvun sijaan säkkiverho, kauneuden sijaan polttomerkki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Miehesi kaatuvat miekkaan ja sankarisi sotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Siionin portit valittavat ja vaikeroivat, ja hän [Siion] istuu tyhjäksi tehtynä maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Sinä päivänä seitsemän naista tarttuu yhteen mieheen sanoen: \"Me syömme omaa leipäämme ja vaatetamme itsemme omilla vaatteilla, kunhan vain meidät otetaan sinun nimiisi. Poista häpeämme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'Sinä päivänä Herran Vesa on oleva Israelin pelastuneille kaunistus ja kunnia ja maan hedelmä heille korkeus ja loisto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Silloin niitä, jotka Siionissa ovat säilyneet ja Jerusalemista jäljelle jääneet, sanotaan pyhiksi, kaikkia, jotka ovat kirjoitetut Jerusalemissa elävien lukuun –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'silloin kun Herra on pessyt pois Siionin tyttärien saastan ja huuhtonut Jerusalemista sen verenviat tuomion ja puhdistuksen Hengellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Silloin Herra luo Siionin vuorelle koko asuinsijansa ylle ja sen juhlakokousten ylle pilven päivän ajaksi ja savun sekä tulenliekin hohteen yöksi, sillä kaiken kirkkauden yllä on oleva peite');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'ja verho varjoamassa päivän helteeltä sekä turvana ja suojana rajuilmalta ja sateelta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Minä laulan ystävästäni, rakkaani laulun hänen viinitarhastaan. Ystävälläni oli viinitarha lihavalla vuorenrinteellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Hän kuokki ja kivesi sen ja istutti siihen jaloja köynnöksiä, rakensi sen keskelle tornin ja hakkasi sinne myös kuurnan. Niin hän odotti sen kasvavan rypäleitä, mutta se kasvoi villimarjoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Mutta nyt, te Jerusalemin asukkaat ja Juudan miehet, tuomitkaa minun ja viinitarhani välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Mitä viinitarhalleni olisi vielä ollut tehtävä, jota en olisi sille tehnyt? Miksi se kasvoi villimarjoja, kun odotin sen kasvavan rypäleitä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Niin nyt ilmoitan teille, mitä teen viinitarhalleni: poistan siitä aidan, että se jää hävitettäväksi, särjen siitä muurin, että se jää tallattavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Hävitän sen: sitä ei enää vesota eikä kuokita, vaan se on kasvava ohdaketta ja orjantappuraa, ja kiellän pilvet sille vettä satamasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Sillä Israelin heimo on ollut Herran Sebaotin viinitarha, ja Juudan miehet hänen istutuksensa, josta hän iloitsi. Niinpä hän odotti oikeutta, mutta katso, tuli oikeudettomuus, ja vanhurskautta, mutta katso, tuli vaikerrus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Voi niitä, jotka liittävät talon taloon, yhdistävät pellon peltoon, kunnes ei jää enää tilaa ja te yksin asutte maassa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Minun korviini kuului Herran Sebaotin sana: Totisesti, monet talot tulevat autioiksi, suuret ja kauniit asumattomiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Sillä kymmenen auranalaa viinitarhaa on antava yhden bat-mitan, ja hoomerin kylvö on antava eefan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Voi niitä, jotka juoksevat aamuvarhaisesta väkijuoman perässä ja viipyvät iltamyöhään viinistä hehkuvina!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Lyyrat, harput, tamburiinit, huilut ja viinit heillä on pidoissaan, mutta Herran tekoja he eivät tutki, eivät näe hänen kättensä töitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Sen tähden kansani siirretään maastaan äkkiarvaamatta, sen ylhäiset kärsivät nälkää, ja sen remuava joukko nääntyy janoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Sen tähden helvetti levittää kitansa ammolleen, avaa suunsa suunnattomaksi. Sinne menee sen loisto, sen remuava ja pauhaava joukko, kaikki sen ilonpitäjät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Ihminen masentuu ja mies painuu maahan, maahan painuvat ylpeitten silmät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Mutta Herra Sebaot on oleva korkea tuomiossa, pyhä Jumala on oleva pyhä vanhurskaudessa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Karitsat käyvät siellä kuin laitumillaan, ja vieraat syöttävät rikkaitten rauniosijoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Voi niitä, jotka vetävät perässään rangaistusta turhuuden köysillä, synnin palkkaa kuin vaunujen valjailla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'Voi niitä, jotka sanovat: \"Tulkoon joutuin hänen tekonsa, että sen näemme. Täyttyköön ja tapahtukoon Israelin Pyhän suunnitelma, että sen tiedämme\"!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Voi niitä, jotka sanovat pahan hyväksi ja hyvän pahaksi, jotka tekevät pimeyden valkeudeksi ja valkeuden pimeydeksi, jotka tekevät karvaan makeaksi ja makean karvaaksi!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Voi niitä, jotka ovat viisaita omissa silmissään ja ymmärtäväisiä omasta mielestään!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Voi niitä, jotka ovat sankareita viinin juonnissa ja voiman miehiä väkijuoman sekoittamisessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'jotka lahjuksesta julistavat syyllisen syyttömäksi ja ottavat oikeuden siltä, joka on oikeassa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Sen tähden, niin kuin tulen kieli syö oljet ja kuloheinä raukeaa liekkiin, niin heidän juurensa mätänee, ja heidän kukkansa hajoaa tomuna ilmaan, sillä he ovat ylenkatsoneet Herran Sebaotin lain ja pitäneet pilkkanaan Israelin Pyhän sanan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Sen tähden Herran viha syttyi hänen kansaansa kohtaan: hän ojensi kätensä sitä vastaan ja löi sitä, niin että vuoret vapisivat ja heidän raatonsa olivat tunkiona keskellä katuja. Tästä kaikesta hänen vihansa ei asettunut, vaan hänen kätensä on vielä ojennettuna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Niinpä hän pystyttää viirin kaukaiselle kansalle ja viheltää sen luokseen maan äärestä. Katso, se tulee viipymättä, nopeasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Kukaan heistä ei väsy eikä kompastu, ei kukaan torku eikä nuku, ei vyö aukene vyötäisiltä, eikä sandaalin nyöri katkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Sen nuolet ovat teroitetut, sen jouset kaikki jännitetyt, sen oriiden kaviot ovat kuin pii, ja sen rattaat kuin rajuilma.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Sen karjunta on kuin naarasleijonan, se karjuu kuin nuoret leijonat, se ärjyy ja tempaa saaliin ja vie sen pois, eikä pelastajaa ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'Se ärjyy sille sinä päivänä, niin kuin meri ärjyy. Silloin tähyillään maata, mutta katso, on pimeys, on ahdistus, ja valo on pimentynyt sen pilvissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Kuningas Ussian kuolinvuotena minä näin Herran istuvan korkealla ja ylhäisellä istuimella, ja hänen vaatteensa liepeet täyttivät temppelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Serafit seisoivat hänen ympärillään; kullakin oli kuusi siipeä: kahdella he peittivät kasvonsa, kahdella he peittivät jalkansa, ja kahdella he lensivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'He huusivat toisilleen ja sanoivat: \"Pyhä, pyhä, pyhä Herra Sebaot. Kaikki maa on täynnä hänen kunniaansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Kynnysten perustukset vapisivat heidän huutonsa äänestä, ja huone täyttyi savulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Sanoin: \"Voi minua, sillä hukun, sillä minulla on saastaiset huulet, ja asun kansan keskellä, jolla on saastaiset huulet; sillä silmäni ovat nähneet kuninkaan, Herran Sebaotin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Yksi serafeista lensi luokseni kädessään hehkuva kivi, jonka hän oli ottanut pihdeillä alttarilta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'ja kosketti sillä suutani sanoen: \"Katso, tämä on koskettanut huuliasi; niin on velkasi poistettu ja syntisi sovitettu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Kuulin Herran äänen sanovan: \"Kenet lähetän? Kuka lähtee puolestamme?\" Minä sanoin: \"Katso, tässä olen, lähetä minut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Hän sanoi: \"Mene ja sano tälle kansalle: \'Kuulemalla kuulkaa, älkääkä ymmärtäkö, näkemällä nähkää, älkääkä käsittäkö.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Paaduta tämän kansan sydän, koveta sen korvat, sokaise sen silmät, ettei se näkisi silmillään, ei kuulisi korvillaan, ei ymmärtäisi sydämellään eikä kääntyisi ja tulisi parannetuksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Silloin sanoin: \"Kuinka kauaksi aikaa, Herra?\" Hän vastasi: \"Siihen asti, kunnes kaupungit tulevat autioiksi, asumattomiksi, ja talot tyhjiksi ihmisistä ja pellot on hävitetty erämaaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'kunnes Herra on karkottanut ihmiset kauas ja suuri autius on tullut keskelle maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Jos siellä on jäljellä kymmenesosa, hävitetään vielä sekin. Mutta niin kuin terebintistä ja tammesta jää kaadettaessa kanto, niin siitäkin: se kanto on pyhä siemen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Aahaan, Jootamin pojan, Ussian pojanpojan, Juudan kuninkaan, aikana lähtivät Resin, Aramin kuningas, ja Pekah, Remaljan poika, Israelin kuningas, sotimaan Jerusalemia vastaan, mutta eivät voineet valloittaa sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Kun Daavidin huoneelle ilmoitettiin sanoma: \"Aram on leiriytynyt Efraimiin\", kuninkaan ja hänen kansansa sydän vapisi, niin kuin metsän puut vapisevat tuulessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Herra sanoi Jesajalle: \"Mene Aahasta vastaan, sinä ja poikasi Sear-Jaasub, Ylälammikon vesijohdon päähän, Vanuttajankedon tielle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'ja sano hänelle: Ole valpas ja pysy rauhallisena, älä pelkää, älköönkä sydämesi säikkykö noita kahta savuavaa kekäleenpätkää: Resinin ja Aramin sekä Remaljan pojan vihan vimmaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Koska Aram, Efraim ja Remaljan poika ovat hankkineet pahaa sinua vastaan sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, '\'Lähtekäämme Juudaa vastaan, täyttäkäämme se kauhulla, vallatkaamme se itsellemme ja asettakaamme sinne kuninkaaksi Taabalin poika\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Herra, Herra sanoo näin: Se ei onnistu eikä tapahdu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Sillä Aramin pää on Damasko, ja Damaskon pää on Resin – mutta kuusikymmentä viisi vuotta vielä, ja Efraim muserretaan eikä se ole enää kansakunta – ja Efraimin pää on Samaria,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'ja Samarian pää on Remaljan poika. Ellette usko, ette kestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Sitten Herra puhui jälleen Aahaalle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, '\"Pyydä itsellesi merkki Herralta, Jumalaltasi, pyydä alhaalta syvyydestä tai ylhäältä korkeudesta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Mutta Aahas vastasi: \"En pyydä enkä kiusaa Herraa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Hän lausui: \"Kuulkaa, te Daavidin suku, eikö riitä, että te ihmiset väsytätte, kun väsytätte vielä minun Jumalanikin itseenne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Sen tähden Herra itse antaa teille merkin: Katso, neitsyt on raskaana ja synnyttää pojan ja antaa hänelle nimen Immanuel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Voita ja hunajaa hän syö siinä iässä, jolloin hän oppii hylkäämään pahan ja valitsemaan hyvän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Sillä ennen kuin poika on oppinut hylkäämään pahan ja valitsemaan hyvän, tulee autioksi maa, jonka kahta kuningasta sinä kauhistut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Herra antaa tulla sinulle, kansallesi ja isäsi suvulle ne päivät, joita ei ole ollut siitä asti, kun Efraim luopui Juudasta. Hän antaa tulla Assurin kuninkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Sinä päivänä Herra viheltää kärpäset Egyptin virtojen suulta ja mehiläiset Assurin maasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'ja ne tulevat ja laskeutuvat kaikki vuorenrotkoihin ja kallionkoloihin, kaikkiin orjantappurapensaisiin ja kaikille juottopaikoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'Sinä päivänä Herra ajattaa virran tuolta puolen palkatulla partaveitsellä, Assurin kuninkaalla, pään ja häpykarvat. Se vie vielä parrankin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'Siihen aikaan pitää mies nuorta lehmää ja paria lammasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'mutta runsaan maidon tulon tähden hän syö kokkelipiimää, sillä kokkelipiimää ja hunajaa syövät kaikki maahan jäljelle jääneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Siihen aikaan jokainen paikka, jossa kasvaa tuhat viinipuuta, arvoltaan tuhat hopeasekeliä, joutuu orjantappuroiden ja ohdakkeiden valtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Sinne on mentävä nuolet ja jousi mukana, sillä koko maa on pelkkää orjantappuraa ja ohdaketta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Ei yhdellekään niistä vuorista, joita nyt kuokalla kuokitaan, enää mennä orjantappuroiden ja ohdakkeiden pelosta. Ne jäävät härkien laitumeksi ja lammasten tallattaviksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Herra sanoi minulle: \"Ota iso taulu ja kirjoita siihen suurella kirjoituksella: Maher-Saalal Haas-Bas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Otin itselleni luotettavat todistajat, pappi Uurian ja Sakarjan, Jeberekjan pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Lähestyin profeettavaimoani, ja hän tuli raskaaksi ja synnytti pojan. Herra sanoi minulle: \"Pane hänelle nimeksi Maher-Saalal Haas-Bas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Sillä ennen kuin poika oppii sanomaan: \'isä\' ja \'äiti\', viedään Damaskon tavarat ja Samarian saalis Assurin kuninkaan eteen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Herra puhui jälleen minulle ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, '\"Koska tämä kansa halveksii Siiloan hiljaa virtaavia vesiä ja iloitsee Resinin ja Remaljan pojan kanssa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'katso, sen tähden Herra antaa tulla heidän ylitseen virran vedet, valtavat ja suuret, Assurin kuninkaan ja kaiken hänen kunniansa. Se nousee kaikkien uomiensa yli ja menee yli kaikkien äyräidensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'Se tunkeutuu Juudaan, paisuu, tulvii ja ulottuu kaulaan saakka. Siipensä levittäen se peittää kaikkialta maasi, Immanuel.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Riehukaa, kansat, kuitenkin kukistutte. Kuulkaa, kaikki kaukaiset maat. Varustautukaa, kuitenkin kukistutte. Varustautukaa, kuitenkin kukistutte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Pitäkää neuvoa: se raukeaa. Sopikaa sopimus: se ei pysy. Sillä tässä on Immanuel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Sillä näin sanoi minulle Herra, kun hänen kätensä valtasi minut ja hän varoitti minua vaeltamasta tämän kansan tietä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, '\"Älkää sanoko salaliitoksi kaikkea, mitä tämä kansa sanoo salaliitoksi. Älkää pelätkö, mitä se pelkää, älkääkä kauhistuko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Herra Sebaot pitäkää pyhänä ja häntä pelätkää ja kauhistukaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'Hän on oleva pyhäkkö, loukkauskivi ja kompastuksen kallio molemmille Israelin huonekunnille, paula ja ansa Jerusalemin asukkaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'Monet heistä kompastuvat, kaatuvat ja ruhjoutuvat, monet kiedotaan ja vangitaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Sido todistus talteen, lukitse laki sinetillä opetuslapsiini.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Odotan Herraa, joka kätkee kasvonsa Jaakobin heimolta, ja panen toivoni häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Katso, minä ja lapset, jotka Herra on minulle antanut, me olemme Herran Sebaotin merkkeinä ja ihmeinä Israelissa, hänen, joka asuu Siionin vuorella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Kun he sanovat teille: \"Kysykää vainaja- ja tietäjähengiltä, jotka supisevat ja mumisevat\", eikö kansa kysyisi Jumalaltaan? Kuolleiltako elävien sijaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, '\"Pysykää laissa ja todistuksessa!\" Jos he eivät näin sano, heille ei aamunkoittoa ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Siellä he kuljeskelevat vaivattuina ja nälkäisinä, ja nälissään he vihastuvat ja kiroavat Kuninkaansa ja Jumalansa. He luovat silmänsä korkeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'He katsahtavat maan puoleen, mutta katso, on ainoastaan ahdistusta ja pimeyttä. Heidät on syösty tuskan synkeyteen ja pimeyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 23, 'Mutta se, mikä nyt on vaivan alla, ei jää pimeään. Entiseen aikaan hän saattoi halveksituksi Sebulonin maan ja Naftalin maan, mutta tulevaisuudessa hän saattaa kunniaan merentien, Jordanin tuonpuoleisen maan, pakanain alueen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Kansa, joka pimeydessä vaeltaa, näkee suuren valon. Niille, jotka asuvat kuoleman varjon maassa, loistaa valo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Sinä lisäät kansan, annat sille suuren ilon. He iloitsevat edessäsi, kuin elonaikana iloitaan, kuin saaliinjaossa riemuitaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Sillä heidän kuormansa ikeen, heidän olkainsa vitsan ja heidän käskijänsä sauvan sinä särjet kuin Midianin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Sillä kaikki taistelun pauhussa tallatut sotakengät ja verellä tahratut sotilaspuvut poltetaan ja kulutetaan tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Sillä lapsi on meille syntynyt, Poika on meille annettu, jonka hartioilla on valtius, ja hänen nimensä on: Ihmeellinen neuvonantaja, Voimallinen Jumala, Iankaikkinen isä, Rauhanruhtinas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Valtius on oleva suuri ja rauha loputon Daavidin valtaistuimella ja hänen valtakunnallaan. Se perustetaan ja vahvistetaan tuomiolla ja vanhurskaudella nyt ja iankaikkisesti. Herran Sebaotin kiivaus on sen tekevä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'Herra lähetti sanan Jaakobia vastaan, ja se iski Israeliin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'ja sen sai tuntea koko kansa, Efraim ja Samarian asukkaat, mutta he sanoivat ylpeydessään ja sydämensä kopeudessa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, '\"Tiilikivet sortuivat maahan, mutta me rakennamme hakatuista kivistä. Metsäviikunapuut hakattiin poikki, mutta me panemme setripuita niiden tilalle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Silloin Herra nostatti sitä vastaan Resinin ahdistajat ja kiihotti sen viholliset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'aramilaiset edestä ja filistealaiset takaa, ja he söivät Israelia suun täydeltä. Kaiken tämän takia hänen vihansa ei ole asettunut, ja vieläkin hänen kätensä on ojennettuna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Mutta kansa ei palannut kurittajansa luo, eivätkä he etsineet Herraa Sebaotia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Sen tähden Herra katkaisi Israelilta pään ja hännän, palmunlehvän ja kaislan, yhtenä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Vanhin ja arvossapidetty on pää, mutta profeetta, joka valhetta opettaa, on häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Tämän kansan johtajista tuli eksyttäjiä, ja johdettavat joutuivat hämminkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Sen tähden Herra ei iloitse sen nuorista miehistä eikä armahda sen orpoja ja leskiä, sillä he ovat kaikki jumalattomia ja pahantekijöitä, ja jokainen suu puhuu hulluutta. Kaiken tämän takia hänen vihansa ei ole asettunut, ja vieläkin hänen kätensä on ojennettuna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Sillä jumalattomuus palaa tulena, kuluttaa orjantappurat ja ohdakkeet ja sytyttää sankan metsän, niin että se tupruaa savuna ilmaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Herran Sebaotin vihasta maa syttyy palamaan, ja kansa on kuin tulen syötävänä. Toinen ei sääli toistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Ahmivat oikealta, mutta on yhä nälkä, syövät vasemmalta, mutta eivät saa kylläänsä. Jokainen syö oman käsivartensa lihaa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Manasse Efraimia ja Efraim Manassea, molemmat yhdessä käyvät Juudan kimppuun. Kaiken tämän tähden hänen vihansa ei ole asettunut, ja vieläkin hänen kätensä on ojennettuna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Voi lainsäätäjiä, jotka laativat jumalattomia lakeja ja kirjoittelevat vääriä tuomioita');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'vääntääkseen köyhien asian ja riistääkseen kansani kurjien oikeuden, että lesket joutuisivat heidän saaliikseen ja orvot heidän ryöstettävikseen!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Mutta mitä teette koston päivänä, rajumyrskyssä, joka tulee kaukaa? Kenen turviin pakenette apua saamaan ja minne talletatte tavaranne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Ei muuta kuin vaivutte vangittujen joukkoon tai kaadutte surmattujen sekaan. Kaiken tämän tähden hänen vihansa ei ole asettunut, ja vieläkin hänen kätensä on ojennettuna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Voi Assuria, joka on vihani vitsa ja jolla on kädessään vihastumiseni sauva!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Lähetän hänet jumalattoman kansakunnan kimppuun, käsken hänet kansaa vastaan, johon olen vihastunut, saalista saamaan, ryöstämään ja tallaamaan sitä kuin katujen lokaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Mutta hän ei ajattele niin. Se ei ole hänen sydämensä ajatus, vaan hänen sydämensä halu on hävittää ja tuhota paljon kansoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Sillä hän sanoo: \"Eivätkö ruhtinaani ole kaikki kuninkaita?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Eikö käynyt Kalnon niin kuin Karkemiin, eikö Hamatin kuin Arpadin ja Samarian kuin Damaskon?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Niin kuin käteni on saavuttanut epäjumalien valtakunnat, joiden jumalankuvat olivat paremmat kuin Jerusalemin ja Samarian –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'enkö tekisi Jerusalemille ja sen epäjumalankuville, samoin kuin tein Samarialle ja sen epäjumalille?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Mutta kun Herra on päättänyt kaiken työnsä Siionin vuorella ja Jerusalemissa, kostan Assurin kuninkaalle hänen sydämensä ylpeyden hedelmän ja hänen kopeitten silmiensä ylvästelyn.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Sillä hän sanoo: \"Oman käteni voimalla sen tein ja omalla viisaudellani, sillä olen ymmärtäväinen. Siirsin kansojen rajat ja ryöstin heidän aarteensa ja puskin ne kumoon kuin härkä valtaistuimella istujat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Käteni tavoitti kansojen rikkaudet kuin linnun pesän. Kuten hylätyt munat kootaan, minä olen koonnut kaikki maat, eikä ketään ollut, joka olisi siipeä räpyttänyt tai nokkansa avannut ja piipittänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Ylpeileekö kirves hakkaajaansa vastaan, tai rehenteleekö saha olevansa sahaajaa suurempi? Ikään kuin vitsa heiluttaisi kohottajaansa ja sauva nostaisi koholle sen, mikä ei ole puuta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Sen tähden Herra, Herra Sebaot, lähettää hänen lihavuuteensa näivetystaudin, ja hänen kunniansa alle syttyy tuli kuin tulipalo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Israelin valo on tuleva tuleksi ja hänen Pyhänsä liekiksi, joka polttaa ja kuluttaa hänen ohdakkeensa ja orjantappuransa yhtenä päivänä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'ja hänen metsänsä ja puutarhansa ihanuuden, luihin ja ytimiin asti, ja hän tulee riutuvan sairaan kaltaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'On helppo laskea ne puut, jotka jäävät jäljelle hänen metsästään. Poika voi kirjoittaa ne muistiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'Sinä päivänä ei Israelin jäännös eivätkä Jaakobin heimon pelastuneet enää turvaudu lyöjäänsä, vaan he turvautuvat totuudessa Herraan, Israelin Pyhään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Jäännös, Jaakobin jäännös, palaa voimallisen Jumalan luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Sillä vaikka kansaasi, Israel, olisi kuin meren hiekkaa, siitä palaa ainoastaan jäännös. Päätetty on hävitys, joka tulee, vanhurskautta tulvillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Sillä hävityksen ja tuomiopäätöksen panee toimeen Herra, Herra Sebaot, kaikessa maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Sen tähden Herra, Herra Sebaot, sanoo näin: \"Kansani, sinä, joka asut Siionissa, älä pelkää Assuria, kun hän lyö sinua vitsalla ja kohottaa sauvansa sinua vastaan Egyptin tavalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Sillä lyhyt hetki vielä, niin suuttumus täyttyy, ja vihani kääntyy hävittämään heidät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Silloin Herra Sebaot heiluttaa ruoskaa häntä vastaan, kuten silloin, kun Midian lyötiin Oorebin kalliolla, ja hänen sauvansa oli ojennettuna meren yli, ja hän kohottaa sen kuin muinoin Egyptiä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'Sinä päivänä kirpoaa hänen kuormansa hartioiltasi ja hänen ikeensä niskaltasi, sillä ies särkyy lihavuudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Hän tulee Aijatiin, kulkee Migronin kautta, ja jättää kuormastonsa Mikmaaseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'He kulkevat solatien poikki: \"Geba on yöpaikkamme.\" Raama vapisee, Saulin Gibea pakenee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Huuda kimakasti, tytär Gallim! Kuuntele, Laisa! Poloinen Anatot!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmena menee pakoon, Geebimin asukkaat vievät tavaransa turvaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Vielä samana päivänä hän pysähtyy Noobiin, hän kohottaa kätensä tytär Siionin vuorta, Jerusalemin kukkulaa, vastaan –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'katso, silloin Herra, Herra Sebaot, katkaisee hänen latvansa kauhistavalla voimalla, vartevat rungot kaadetaan, ja korkeat kukistuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Metsän tiheikkö hakataan kirveellä maahan, ja Libanon kaatuu Valtasuuruuden edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Mutta Iisain kannosta puhkeaa Virpi, ja Vesa versoo hänen juuristaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'Hänen päällään lepää Herran Henki, viisauden ja ymmärryksen Henki, neuvon ja voiman Henki, tiedon ja Herran pelon Henki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Hän haluaa Herran pelkoa. Hän ei tuomitse silmän näöltä eikä jaa oikeutta korvan kuulolta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'vaan tuomitsee kurjat vanhurskaasti ja jakaa oikein oikeutta maan nöyrille. Suunsa sauvalla hän lyö maata, surmaa jumalattoman huultensa Henkäyksellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Vanhurskaus on hänen lanteittensa vyö ja totuus hänen lanteittensa side.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Susi asuu karitsan kanssa, ja pantteri makaa kilin vieressä. Vasikka, nuori leijona ja syöttöhärkä ovat yhdessä, ja pieni poika niitä paimentaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Lehmä ja karhu käyvät laitumella, niiden vasikat ja pennut makaavat yhdessä, ja leijona syö rehua kuin nauta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Imeväinen leikittelee kyyn kololla, ja vieroitettu kurottaa kätensä käärmeen luolaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Ei missään pyhällä vuorellani tehdä pahaa eikä vahinkoa, sillä maa on täynnä Herran tuntemusta, niin kuin vedet peittävät meren.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'Sinä päivänä pakanat etsivät Iisain juurta, joka on kansojen lippuna, ja hänen asumuksensa on oleva kunniaa täynnä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Sinä päivänä Herra vielä toisen kerran ojentaa kätensä hankkiakseen itselleen kansansa jäännöksen, joka on jäljellä Assurissa, Egyptissä, Patroksessa, Kuusissa, Eelamissa, Sinearissa, Hamatissa ja merensaarilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Hän nostaa viirin pakanakansoille ja kokoaa Israelin karkotetut miehet, ja Juudan hajotetut naiset hän kerää maan neljästä äärestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Silloin katoaa Efraimin kateus, ja Juudan vihat häviävät. Efraim ei kadehdi Juudaa, eikä Juuda vihaa Efraimia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Niin he lentävät länteen päin filistealaisten niskaan. Yhdessä he ryöstävät Idän miehiä. Edom ja Mooab joutuvat heidän käsiinsä, ammonilaiset heidän alamaisikseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Herra vihkii tuhon omaksi Egyptin merenlahden ja vihansa hehkussa kohottaa kätensä Eufrat-virtaa vastaan, lyö sen hajalle seitsemäksi puroksi ja tekee sen sandaalein kuljettavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'Siitä tulee valtatie hänen kansansa jäännökselle, joka on jäljellä Assurissa, niin kuin tuli Israelille silloin, kun se lähti Egyptin maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'Sinä päivänä sanot: \"Kiitän sinua, Herra, sillä olit minuun vihastunut, mutta vihasi asettui, ja lohdutit minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Katso, Jumala on pelastukseni, olen turvassa enkä pelkää, sillä Herra, Herra on voimani ja ylistysvirteni, hän tuli minulle pelastukseksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Te saatte ilolla ammentaa vettä pelastuksen lähteistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'Sinä päivänä te sanotte: \"Kiittäkää Herraa, julistakaa hänen nimeään, tehkää hänen tekonsa tiettäviksi pakanakansojen keskuudessa, tunnustakaa, että hänen nimensä on korkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Veisatkaa ylistystä Herralle, sillä valtavia tekoja hän on tehnyt. Tulkoot ne tunnetuiksi kaikessa maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Huutakaa ja riemuitkaa, Siionin asukkaat, sillä suuri on keskellänne Israelin Pyhä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Profeettasana Baabelista, Jesajan, Aamosin pojan, näkemä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Pystyttäkää viiri paljaalle vuoren laelle, korottakaa äänenne heille, viittokaa heitä kädellä menemään sisälle ruhtinaiden porteista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Minä olen antanut käskyn pyhitetyilleni ja kutsunut sankarini vihani työhön, ne, jotka riemuitsevat valtasuuruudestani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Kuule, vuorilla käy kuin paljojen kansojen pauhu. Kuule valtakuntien, kokoontuneitten kansojen kohinaa: Herra Sebaot katsastaa sotajoukkoaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'He tulevat kaukaisesta maasta, taivaan ääristä, Herra ja hänen vihansa aseet, hävittämään kaiken maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Valittakaa, sillä Herran päivä on lähellä, se tulee hävityksenä Kaikkivaltiaalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Sen tähden kaikki kädet herpoavat, ja kaikki ihmissydämet raukeavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'He pelästyvät, kivut ja tuskat valtaavat heidät, he vääntelehtivät kuin synnyttäjä, tuijottavat toisiinsa kauhistuneina ja kasvot tulta leiskuen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Katso, Herran päivä tulee, tulee armottomana, tulee kiivaus ja vihan hehku, tekemään autioksi maan ja hävittämään siitä syntiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Sillä taivaan tähdet ja Orionin tähdet eivät loista valollaan, aurinko on pimeä noustessaan, kuu ei kajasta kirkkaana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'Kostan maanpiirille sen pahuuden ja jumalattomille heidän pahat tekonsa. Lopetan julkeitten kopeuden ja painan maahan väkivaltaisten ylpeyden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Teen kuolevaiset harvinaisemmiksi kuin puhdas kulta, ihmiset harvinaisemmiksi kuin Oofirin kulta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Sen tähden järisytän taivaat, ja maa järkkyy paikaltaan Herran Sebaotin kiivaudesta, hänen vihansa hehkun päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'Kuin säikytetyt gasellit ja kuin lampaat, joilla ei ole kokoajaa, he kääntyvät kukin kansansa luo, pakenevat kukin omalle maalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Kuka ikinä tavoitetaan, se lävistetään. Se, joka joutuu kiinni, kaatuu miekkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Heidän pienet lapsensa murskataan heidän silmiensä edessä, heidän talonsa ryöstetään, ja heidän vaimonsa raiskataan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Katso, herätän heitä vastaan meedialaiset, jotka eivät huoli hopeasta eivätkä välitä kullasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Heidän jousensa kaatavat nuoria miehiä. He eivät armahda kohdun hedelmää eivätkä sääli lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Silloin Baabelin, valtakuntien kaunistuksen, kaldealaisten ylpeyden ja loiston, käy kuin Sodoman ja Gomorran, jotka Jumala hävitti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Sitä ei ikinä enää asuta. Se jää autioksi polvesta polveen. Arabi ei tee sinne telttaansa, eivätkä paimenet lepuuta siellä laumaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Erämaan eläimet lepäävät siellä, sen huoneet ovat pöllöjä täynnä, strutsit asuvat siellä, ja vuohipukit siellä hyppelevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'Sakaalit ulvovat sen palatseissa ja hyeenat huvilinnoissa. Sen aika on lähellä, tulemaisillaan. Sen päiviä ei pidennetä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Sillä Herra armahtaa Jaakobia ja valitsee vielä Israelin ja sijoittaa heidät heidän omaan maahansa. Muukalaiset liittyvät heihin ja yhtyvät Jaakobin heimoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Kansat ottavat heidät ja tuovat heidät heidän kotiinsa, ja Israelin heimo saa heidät Herran maassa omikseen, orjiksi ja orjattariksi, ja he vangitsevat vangitsijansa ja hallitsevat käskijöitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'Sinä päivänä, jona Herra päästää sinut rauhaan vaivastasi, tuskastasi ja siitä kovasta työstä, jota sinulla teetettiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'virität tämän pilkkalaulun Baabelin kuninkaasta ja sanot: \"Kuinka on käskijästä tullut loppu, tullut loppu ahdistuksesta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Herra on murtanut jumalattomien sauvan, valtiaitten vitsan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'joka löi kansoja vihan vimmassa, löi lakkaamatta, joka vihassa vallitsi kansakuntia ja vainosi niitä säälimättä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Kaikki maa on saanut levon ja rauhan. He puhkeavat riemuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Sypressitkin sekä Libanonin setrit iloitsevat sinusta: \'Sinun maata mentyäsi ei nouse kukaan meitä hakkaamaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Helvetti tuolla alhaalla värisi tähtesi ottaakseen sinut vastaan, kun tulet. Se herättää kuolleet sinulle, kaikki maan johtomiehet, nostattaa valtaistuimiltaan kaikki kansojen kuninkaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Kaikki he lausuvat ja sanovat sinulle: \'Myös sinä olet riutunut niin kuin mekin, olet tullut meidän kaltaiseksemme.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Alas helvettiin on vaipunut komeutesi ja harppujesi helinä. Allasi ovat vuoteena madot. Toukat ovat peittonasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Kuinka olet taivaalta pudonnut, sinä kointähti, aamuruskon poika! Kuinka olet maahan syösty, sinä kansojen kukistaja!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Sinä sanoit sydämessäsi: \'Nousen taivaaseen, korkeammalle Jumalan tähtiä korotan istuimeni ja istun kokoontumisvuorelle pohjoisen puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Nousen pilvien kukkuloille, teen itseni Korkeimman vertaiseksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Mutta alas helvettiin sinä joudut, syvimpään kuiluun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Ne, jotka sinut näkevät, katsovat pitkään, tarkastelevat sinua: \'Onko tämä se mies, joka järisytti maan ja järkytti valtakunnat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'joka teki maanpiirin erämaaksi ja hävitti sen kaupungit, joka ei päästänyt vankejaan kotiin?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Kansojen kuninkaat lepäävät kaikki kunniassa, kukin kammiossaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Mutta sinä olet kaukana haudastasi, viskattuna pois kuin hylätty vesa, olet peittynyt surmattujen, miekalla lävistettyjen, kiviseen kuoppaan suistuneitten alle, olet kuin tallattu raato.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Et saa yhtyä heihin haudassa, sillä olet maasi hävittänyt, kansasi tappanut. Ikinä enää ei mainita pahantekijöiden sukua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Laittakaa hänen lapsilleen verilöyly heidän isiensä pahojen tekojen tähden, etteivät he nousisi ottamaan omakseen maata ja täyttäisi maanpiiriä kaupungeilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Nousen heitä vastaan, sanoo Herra Sebaot, ja hävitän Baabelilta nimen ja jäännöksen, suvun ja jälkeläiset, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'Teen sen siilien perinnöksi ja vesirämeeksi, lakaisen sen pois hävityksen luudalla, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Herra Sebaot on vannonut sanoen: Totisesti, mitä olen ajatellut, se tapahtuu, mitä olen päättänyt, se toteutuu:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'muserran Assurin maassani ja tallaan hänet vuorillani, niin että hänen ikeensä heltiää heidän päältään ja hänen kuormansa heltiää heidän hartioiltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Tämä on päätös, päätetty kaikesta maasta, tämä on käsi, ojennettu kaikkien kansojen yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Sillä Herra Sebaot on päättänyt, – kuka sen tyhjäksi tekee? Hänen kätensä on ojennettu, – kuka sen torjuu?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'Kuningas Aahaan kuolinvuotena tuli tämä profeettasana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Älä, Filistea kaikkinesi, iloitse siitä, että sauva, joka sinua löi, on murtunut. Sillä käärmeen juuresta kasvaa kyy, ja sen hedelmä on lentävä käärme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Vaivaisista kurjimmat löytävät laitumen, ja köyhät saavat levätä turvassa, mutta sinun juuresi tapan nälkään, ja sinun jäännöksesi surmataan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Valita, portti, huuda, kaupunki. Menehdy pelkoon, Filistea kaikkinesi, sillä pohjoisesta tulee savu; eikä yksikään erkane vihollisen riveistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Mutta mitä vastataan pakanakansan sanansaattajille? \" Herra on perustanut Siionin, ja hänen kansansa kurjat saavat siinä turvan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Ennustus Mooabista. Hävityksen yönä tuhoutuu Aar-Mooab; hävityksen yönä tuhoutuu Kiir-Mooab.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Bait ja Diibon nousevat uhrikukkuloille itkemään, Nebolla ja Meedebassa Mooab valittaa; kaikki päät ovat paljaiksi ajettuja, kaikki parrat ovat leikattuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Kaduilla he kääriytyvät säkkeihin, katoilla ja toreilla kaikki valittavat, he menehtyvät itkuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Hesbon ja Elale huutavat. Niiden itku kuuluu Jahaaseen asti. Sen tähden Mooabin varustetut miehet vaikeroivat, sen sielu vapisee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Sydämeni huutaa Mooabin tähden. Sen pakolaisia on aina Sooariin saakka, aina Eglat-Selisijjaan asti. Luuhitin solatietä he nousevat itkien, Hooronaimin tiellä he puhkeavat itkuun hävityksen tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Nimrimin vedet ehtyvät erämaaksi, heinä kuivuu, ruoho lakastuu eikä vihantaa ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Sen tähden he kantavat hankkimansa säästön ja tallettamansa tavaran Pajupuron yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Itku kiertää Mooabin rajoja, voihke kuuluu Eglaimiin asti, valitus Beer-Eelimiin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Sillä Diimonin vedet ovat verta täynnä, ja vielä muutakin tuon Diimonille: leijonan Mooabin pelastuneiden ja maahan jääneiden kimppuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, '\"Lähettäkää maan hallitsijalle tulevat lampaat Selasta erämaan kautta tytär Siionin vuorelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Kuin pakenevat linnut, säikytetty pesue, ovat Mooabin tyttäret Arnonin kahlauspaikoilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, '\"Anna neuvo, ryhdy välittäjäksi, tee varjosi yön kaltaiseksi keskellä päivää, kätke karkotetut äläkä ilmaise pakenevia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Salli minun karkotettujeni asua luonasi, Mooab, ole heille suojana hävittäjää vastaan. Sillä sortajalle tulee loppu, hävitys lakkaa, ja tallaaja on maasta poissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'Valtaistuin vahvistetaan laupeudella, ja sillä istuu vakaasti Daavidin majassa Tuomari, joka harrastaa oikeutta ja ahkeroi vanhurskautta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, '\"Me olemme kuulleet Mooabin ylpeilyn, tuon hyvin korskean, hänen kopeilunsa, ylpeilynsä ja vihansa, hänen väärät puheensa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Sen tähden Mooab valittaa Mooabille, kaikki he valittavat. Kiir-Haresetin rypälekakkuja te huokailette, ja olette aivan murtuneita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Sillä kuihtuneet ovat Hesbonin viinitarhat, Sibman viiniköynnökset. Niiden jalot rypäleet kaatoivat kansojen valtiaita, ne ulottuivat Jaeseriin asti, harhailivat halki erämaan, niiden vesat levisivät ja menivät yli meren.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Sen tähden minä itken Jaeserin kanssa, itken Sibman viiniköynnöksiä, kastelen kyyneleilläni sinua, Hesbon, ja sinua, Elale, sillä hedelmän- ja viininkorjuun keskelle on kajahtanut sotahuuto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'Ilo ja riemu on tauonnut puutarhasta, viinitarhoissa ei riemuita, ei ratketa nauruun; ei poljeta viiniä viinikuurnissa. \"Minä olen vaientanut ilohuudon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Siksi sisimpäni värisee Mooabin tähden kuin lyyra, sydämeni Kiir-Hereksen tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'Vaikka Mooab kuinka astuisi uhrikukkulalle ja uuvuttaisi itsensä sillä ja vaikka kuinka menisi pyhäkköönsä rukoilemaan, se ei häntä auta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Tämä on sana, jonka Herra oli jo ennen puhunut Mooabille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Mutta nyt Herra lausuu sanoen: Ennen kuin kolme vuotta on kulunut – kolme palkkalaisen vuotta – Mooabin kunnia suurine joukkoineen tehdään halvaksi, ja jäännös on oleva hyvin pieni ja mitätön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Ennustus Damaskosta. Katso, Damasko poistetaan kaupunkien luvusta ja luhistuu raunioiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Aroerin kaupungit jäävät autioiksi karjalaumojen haltuun. Ne lepäävät siellä kenenkään pelottelematta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Efraimilta menee suojavarustus ja Damaskolta kuninkuus ja Aramista jäännöskin. Niiden käy kuin israelilaisten kunnian, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'Sinä päivänä Jaakobin kunnia köyhtyy, ja hänen ruumiinsa lihavuus laihtuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Silloin käy kuin leikkaajan kahmaistessa viljaa ja hänen käsivartensa leikatessa tähkiä. Silloin käy kuin tähkiä poimittaessa Refaimin tasangolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Sen verran jää jälkikorjuuta kuin öljypuuta karistettaessa: pari, kolme marjaa korkealle latvaan, neljä, viisi hedelmäpuun oksiin, sanoo Herra, Israelin Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'Sinä päivänä ihminen luo katseen Luojaansa, ja hänen silmänsä katsovat Israelin Pyhään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'eikä hän luo katsettaan alttareihin, heidän omien kättensä tekoon, eikä katso niihin, mitä hänen sormensa ovat tehneet, ei aseroihin eikä auringonpatsaisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'Sinä päivänä hänen linnoitetut kaupunkinsa ovat kuin autioituneet paikat metsissä ja kukkuloilla, jotka jätettiin autioiksi israelilaisten tullessa, ja maa muuttuu erämaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Sillä unohdit pelastuksesi Jumalan etkä muistanut turvakalliotasi. Sen tähden istutat ihania istutuksia ja kylvät vieraita viiniköynnöksiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'Istutuspäivänä saat ne kasvamaan, ja aamulla saat kylvösi kukoistamaan – mutta poissa on sato sairauden päivänä, ja parantumaton on kipu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Voi paljojen kansojen pauhua – ne pauhaavat, kuin meri pauhaa, ja kansakuntien kohinaa – ne kohisevat, kuin valtavat vedet kohisevat!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Kansakunnat kohisevat, kuin suuret vedet kohisevat. Mutta hän nuhtelee niitä, ja ne pakenevat kauas. Ne karkotetaan kuin akanat tuulessa vuorilla, kuin lentävät lehdet rajuilmassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Katso, ehtoolla on oleva kauhu, aamun tullen ei heitä enää ole. Tämä on riistäjiemme osa, ryöstäjiemme arpa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Voi siipien surinan maata, joka on tuolla puolen Kuusin jokien,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'joka lähettää sanansaattajat virralle, ruokoveneissä vesiä myöten! Lähtekää, te nopeat sanansaattajat, kookkaan ja kiiltäväihoisen kansan luo, lähellä ja kaukana pelätyn kansan luo, voimakkaan sortajakansan luo, jonka maata joet halkovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Te kaikki maanpiirin asukkaat, te maan asuttajat, katsokaa, milloin viiri nostetaan vuorille, ja kuunnelkaa, kun puhalletaan torveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Sillä näin Herra on minulle sanonut: \"Pysyn hiljaa ja katselen asunnostani kuin hehkuva helle päivän paistaessa ja kuin kastepilvi elonajan helteessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Sillä ennen viininkorjuuta, kun kukinta on päättynyt ja kukasta on tullut kypsyvä marja, hän hakkaa vesoimella köynnökset, hävittää ja katkoo varret.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Ne jätetään kaikki vuorten petolintujen ja maan eläinten haltuun. Petolinnut pitävät siellä kesää, ja kaikenlaiset maan eläimet siellä talvehtivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'Siihen aikaan kookas ja kiiltäväihoinen kansa, lähellä ja kaukana pelätty kansa, voimakas sortajakansa, jonka maata joet halkovat, tuodaan lahjaksi Herralle Sebaotille siihen paikkaan, missä asuu Herran Sebaotin nimi: Siionin vuorelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Profeettasana Egyptistä. Katso, Herra ajaa nopealla pilvellä ja tulee Egyptiin. Silloin vapisevat Egyptin epäjumalat hänen edessään, ja sydän raukeaa Egyptin rinnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Kiihotan Egyptin Egyptiä vastaan, niin että he sotivat keskenään, ystävä ystävää vastaan, kaupunki kaupunkia vastaan, valtakunta valtakuntaa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Silloin Egyptiltä katoaa rohkeus rinnasta, ja hämmennän hänen neuvonsa. He kysyvät epäjumalilta, henkienmanaajilta, vainaja- ja tietäjähengiltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Annan Egyptin tylyn herran käsiin, ja kova kuningas on hallitseva heitä, sanoo Herra, Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Vedet loppuvat virrasta, joki ehtyy ja kuivuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'Joet levittävät löyhkää, Egyptin kanavat madaltuvat ja ehtyvät, ruoko ja kaisla lakastuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Ruohikot Niilivirran varsilla, virran suussa, ja kaikki Niilivirran kylvömaat kuivuvat, kuihtuvat ja häviävät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Kalastajat valittavat ja murehtivat. Kaikki, jotka heittävät onkea virtaan ja laskevat verkkoa veteen, nääntyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Häpeään joutuvat ne, jotka pitelevät häkilöityjä pellavia ja jotka kutovat pellavakankaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Maan peruspylväät murskataan, ja kaikki palkkalaiset ovat murheellisella mielellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Hulluina ovat Sooanin päämiehet kaikki, viisaimmat faraon neuvonantajista ovat neuvossaan tulleet tyhmiksi. Kuinka voitte sanoa faraolle: \"Olen viisaitten poika, muinaisajan kuninkaitten jälkeläinen\"?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Missä ovat viisaasi? Ilmoittakoot sinulle – hehän sen tietävät – mitä Herra Sebaot on Egyptin osalle päättänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Sooanin päämiehet ovat käyneet typeriksi, Noofin päämiehet ovat pettyneet. Egyptiä horjuttavat sen sukukuntien kulmakivet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Herra on vuodattanut sen keskuuteen sekasorron hengen, ja niin he saattavat Egyptin horjumaan kaikissa menoissaan, kuin juopunut horjahtaa oksennukseensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Eikä menesty Egyptille mikään teko, tekipä sen pää tai häntä, palmunlehvä tai kaisla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'Sinä päivänä Egypti on oleva naisten kaltainen. Se vapisee ja pelkää Herran Sebaotin käden heilutusta, kun hän heiluttaa kättään sitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Juudan maa on oleva Egyptille kauhuksi. Niin usein kuin sitä sille mainitaan, se pelkää Herran Sebaotin päätöstä, jonka hän on siitä päättänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'Sinä päivänä on viisi kaupunkia Egyptin maassa puhuva Kanaanin kieltä ja vannova valan Herralle Sebaotille. Yhtä niistä mainitaan nimellä Iir-Heres.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'Sinä päivänä on oleva Herran alttari keskellä Egyptin maata ja sen rajalla Herran patsas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'Se on oleva merkkinä ja todistuksena Herralle Sebaotille Egyptin maassa. Sillä he huutavat Herraa sortajien tähden, ja hän lähettää heille vapauttajan ja puolustajan, joka pelastaa heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Silloin Herra tekee itsensä tunnetuksi egyptiläisille, ja egyptiläiset tuntevat Herran sinä päivänä ja palvelevat häntä teuras- ja ruokauhreilla, ja he tekevät Herralle lupauksia ja täyttävät ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'Herra lyö egyptiläisiä, lyö ja parantaa. He palaavat Herran luo, ja hän kuulee heidän rukouksensa ja parantaa heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'Sinä päivänä on oleva valtatie Egyptistä Assuriin, ja Assur yhtyy Egyptiin ja Egypti Assuriin, ja ne, Egypti sekä Assur, palvelevat Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'Sinä päivänä Israel on oleva kolmantena Egyptin ja Assurin rinnalla, siunauksena keskellä maata,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'sillä Herra Sebaot siunaa sitä sanoen: \"Siunattu olkoon Egypti, kansani, ja Assur, kätteni teko, ja Israel, perintöosani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'Sinä vuonna, jona Tartan, Sargonin, Assurin kuninkaan, lähettämänä, tuli Asdodiin, ryhtyi taisteluun Asdodia vastaan ja valloitti sen –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'siihen aikaan Herra puhui Jesajan, Aamosin pojan, kautta sanoen: \"Mene, riisu säkkipuku lanteiltasi ja vedä sandaalit jalastasi.\" Hän teki niin: kulki ilman viittaa ja avojaloin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Herra sanoi: \"Niin kuin palvelijani Jesaja on kolme vuotta kulkenut ilman viittaa ja avojaloin, merkiksi ja enteeksi Egyptille ja Kuusille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'niin on Assurin kuningas kuljettava Egyptin sotavankeja ja Kuusin karkotettuja, sekä nuoria että vanhoja, ilman viittaa ja avojaloin, takapuolet paljaina – Egyptin häpeä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'He kauhistuvat ja joutuvat häpeään Kuusin tähden, joka oli heidän toivonsa, ja Egyptin tähden, joka oli heidän ylpeytensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Tämän rantamaan asukkaat sanovat sinä päivänä: \'Katso, näin on käynyt toivomme, jonka turviin pakenimme apua saamaan vapautuaksemme Assurin kuninkaasta. Kuinka me pelastumme?\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Profeettasana meren viereisestä erämaasta. Niin kuin myrskytuulet kiitävät Negevissä, niin se tulee erämaasta, pelottavasta maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Julma näky ilmoitettiin minulle: \"Ryöstäjä ryöstää, hävittäjä hävittää. Hyökkää, Eelam! Piiritä, Meedia! Kaiken huokailun lopetan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Sen tähden lanteeni ovat täynnä vapinaa, minut valtaavat tuskat kuin synnyttäjän tuskat. Minua huimaa, niin etten kuule, kauhistuttaa, niin etten näe.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Sydämeni värisee, kauhu pelästyttää minut. Ikävöimäni iltahämärän se muuttaa minulle vavistukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Pöytä katetaan, matto levitetään, syödään, juodaan. Nouskaa, te ruhtinaat, voidelkaa kilvet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Sillä näin on Herra minulle sanonut: \"Mene, aseta tähystäjä. Hän ilmoittakoon, mitä näkee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Kun hän näkee jonon ratsastajia pareittain, jonon aaseja, jonon kameleja, niin kuunnelkoon tarkasti, hyvin tarkasti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Hän huusi kuin leijona: \"Tähystyspaikalla, Herra, minä seison alati, päivät pitkät, pysyn vartiopaikallani kaiket yöt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'Katso, tuolla tulee jonossa miehiä, parivaljakoita.\" Sitten hän lausui sanoen: \"Kukistunut, kukistunut on Baabel, ja kaikki sen jumalien kuvat hän on murskannut maahan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Maahan puitu kansani, puimatantereella poljettuni! Mitä olen kuullut Herralta Sebaotilta, Israelin Jumalalta, sen teille ilmoitan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Ennustus Duumasta. Minulle huudetaan Seiristä: \"Vartija, mikä hetki yöstä on? Vartija, mikä hetki yöstä on?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Vartija vastaa: \"Aamu on tullut, mutta silti on yö. Jos vielä kyselette, kyselkää. Tulkaa uudelleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Profeettasana Arabiaa vastaan. Yöpykää Arabian viidakoissa, te dedanilaiset karavaanit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Menkää vastaan, viekää vettä janoaville. Teeman maan asukkaat ottavat pakolaiset vastaan leipää tarjoten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Sillä he ovat miekkoja paossa, paljastettua miekkaa, jännitettyä jousta ja sodan raskautta paossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Sillä näin on Herra minulle sanonut: Vielä vuosi – sellainen kuin on palkkalaisen vuosi – niin kaikki Keedarin kunnia on kadonnut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'ja Keedarin sankarien jousiluvun jäännös on oleva vähäinen. Sillä Herra, Israelin Jumala, on puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Ennustus Näkylaaksosta. Mikä sinun on, kun nouset katoille kaikki mukanasi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'sinä kohiseva, pauhaava kaupunki, sinä remuava kylä? Surmattusi eivät ole miekan surmaamia, eivät sotaan kuolleita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Kaikki sinun johtajasi ovat yhdessä paenneet, vangeiksi joutuneet, jousta vailla. Keitä vain sinun omiasi tavattiin, heidät kaikki vangittiin, kuinka kauas pakenivatkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Sen tähden sanon: \"Kääntäkää katseenne minusta pois: itken katkerasti; älkää tungeksiko minua lohduttamaan, kun tytär, kansani, tuhoutuu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Sillä hämmingin, hävityksen ja häiriön päivän on Herra, Herra Sebaot, pitävä Näkylaaksossa. Muurit ovat murretut, vuorille on kohonnut huuto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Eelam nosti viinen saapuen vaunuineen, väkineen ja ratsumiehineen, ja Kiir paljasti kilven.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'Ihanimmat laaksosi täyttyivät vaunuista, ratsumiehet asettuivat asemiin portin eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Hän riisui Juudalta verhon, ja sinä päivänä loit katseesi Metsätalon asevarastoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'Huomasitte monta repeämää Daavidin kaupungin muurissa ja kokositte vedet Alalammikkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Luitte Jerusalemin talot ja hajotitte taloja vahvistaaksenne muurin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'ja teitte molempien muurien välille paikan, johon Vanhan lammikon vedet koottiin. Mutta sen puoleen ette katsoneet, joka tämän tuotti, häntä ette nähneet, joka tämän kauan sitten valmisti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Sinä päivänä Herra, Herra Sebaot, kutsui itkuun ja valitukseen, ajamaan pään paljaaksi ja vyöttäytymään säkkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'Mutta katso: on iloa ja riemua, nautojen tappamista ja lammasten teurastusta, lihan syöntiä ja viinin juontia! \"Syökäämme ja juokaamme, sillä huomenna kuolemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Korviini kuului Herran Sebaotin ilmoitus: \"Totisesti, tämä syntinne ei tule sovitetuksi, ei kuolemaanne saakka, sanoo Herra, Herra Sebaot.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Näin sanoo Herra, Herra Sebaot: Mene tuon huoneenhaltijan luo, Sebnan luo, joka on linnan päällikkönä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, '\"Mitä sinulla täällä on asiaa, ja keitä sinulla täällä on, kun hakkautat tänne itsellesi haudan, hakkautat hautasi korkeuteen, koverrat kalliolle itsellesi asunnon?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Katso, Herra heittää sinua, mies, rajusti: hän kahmaisee sinut kokoon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'kääräisee sinut keräksi ja paiskaa pallona menemään maahan, jossa on laajuutta joka suuntaan. Sinne kuolet, ja sinne jäävät kunniavaunusi, sinä Herrasi huoneen häpeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Syöksen sinut pois paikastasi. Hän kukistaa sinut asemastasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Mutta sinä päivänä kutsun palvelijani Eljakimin, Hilkian pojan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'ja puetan hänen päälleen paitasi, vyötän hänet vyölläsi ja panen valtasi hänen käteensä, niin että hän on oleva isänä Jerusalemin asukkaille ja Juudan suvulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Panen Daavidin huoneen avaimen hänen olalleen. Hän avaa, eikä kukaan sulje, ja hän sulkee, eikä kukaan avaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Lyön hänet vaarnaksi vahvaan paikkaan, ja hänestä tulee kunniaistuin isänsä suvulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'Hänen varaansa ripustautuu hänen isänsä suvun kaikki paljous, vesat ja versot, kaikki pienet astiat, kaikki maljat ja ruukut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'Sinä päivänä, sanoo Herra Sebaot, vahvaan paikkaan lyöty vaarna pettää, se katkeaa ja putoaa, ja kuorma, joka oli sen varassa, särkyy. Sillä Herra on sen puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Profeettasana Tyyrosta. Valittakaa, te Tarsiin laivat, sillä se on hävitetty talottomaksi, paikaksi, johon ei kuljeta. Kittiläisten maasta he saivat tämän tiedon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Mykistykää, te rantamaan asukkaat! Siidonin kauppamiehet, merenkulkijat, täyttivät sinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'Suuria vesiä kulki Siihorin siemen, Niilivirran vilja. Se oli Tyyron sato, ja siitä tuli kansojen kauppatavara.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Häpeä, Siidon, sillä näin sanoo meri, meren linnoitus: \"En ole kivuissa ollut, en ole synnyttänyt, en ole kasvattanut nuorukaisia enkä saattanut neitsyitä suuriksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Kun tämä kuullaan Egyptissä, vavistaan Tyyron kuulumisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Menkää Tarsiiseen. Valittakaa, te rantamaan asukkaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Onko tämä remuava kaupunkinne, jonka alku on kaukaa menneisyydestä, se, jonka jalat kuljettivat kauas muukalaisena asumaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Kuka on tämän päättänyt Tyyron osalle, kruunujen jakelijan, jonka kauppamiehet olivat ruhtinaita, kauppiaat kunnioitettuja kautta maan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Herra Sebaot on sen päättänyt häväistäkseen kaiken ylvästelyn koreuden tähden ja saattaakseen kaikki maan kunnioitetut halveksituiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Tulvi yli maasi, tytär Tarsis kuin Niilivirta. Enää ei ole patoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Hän on ojentanut kätensä meren yli ja järkyttänyt valtakunnat. Herra on antanut käskyn Kanaania vastaan, että sen linnoitukset hävitettäkööt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'Hän sanoo: \"Älä enää ilakoi, sinä häväisty neitsyt, tytär Siidon. Nouse, mene kittiläisten maahan; et sinä sielläkään saa levätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Katso, kaldealaisten maa, kansa, jota ei ollut enää olemassa, jonka Assur oli valmistanut erämaan eläimille, – he pystyttävät vartiotorninsa, he kukistavat sen palatsit, tekevät sen raunioiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Valittakaa, te Tarsiin laivat, sillä hävitetty on teidän linnoituksenne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'Siihen aikaan Tyyro unohdetaan seitsemäksikymmeneksi vuodeksi, jotka ovat kuin saman kuninkaan aikaa. Seitsemänkymmenen vuoden kuluttua käy Tyyron, niin kuin porton laulussa sanotaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, '\"Ota lyyra, kierrä kaupunkia, sinä unohdettu portto; soita kauniisti, laula vireästi, että sinut muistettaisiin!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Sitten seitsemänkymmenen vuoden kuluttua Herra katsoo Tyyron puoleen, ja se pääsee jälleen portonpalkoilleen ja tekee huorin kaikkien maan valtakuntien kanssa, mitä maan päällä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Mutta sen voitto ja palkka on oleva Herralle pyhitetty. Sitä ei koota eikä talleteta, vaan sen voitto on tuleva niille, jotka Herran edessä asuvat, runsaaksi ravinnoksi ja jaloksi vaatetukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Katso, Herra tekee maan tyhjäksi ja autioksi, mullistaa sen muodon ja hajottaa sen asukkaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Kuten kansan käy, niin papinkin, kuten orjan, niin hänen isäntänsä, kuten orjattaren, niin hänen emäntänsä, kuten ostajan, niin myyjän, kuten lainanottajan, niin lainanantajan, kuten velallisen, niin velkojankin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Maa tyhjentämällä tyhjennetään ja ryöstämällä ryöstetään. Sillä Herra on tämän sanan puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Maa murehtii ja lakastuu, maanpiiri nääntyy ja lakastuu; kansan ylhäiset nääntyvät maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Maa on saastunut asukkaittensa alla, sillä he ovat rikkoneet lait, muuttaneet käskyt, hylänneet iankaikkisen liiton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Sen tähden kirous kalvaa maata, ja sen asukkaat kärsivät omasta syystään. Sen tähden maan asukkaat korventuvat kuumuudesta, ja ihmisiä jää jäljelle vain vähän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Viini murehtii, viiniköynnös kuihtuu, kaikki sydämeltään iloiset huokaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Loppunut on tamburiinien riemu, lakannut remuavien melu, loppunut lyyrojen riemu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Ei juoda viiniä laulaen, väkijuoma käy juojilleen karvaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Kukistettu on autio kaupunki, jokainen talo on teljetty ja sisään pääsemätön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Viinistä on kaduilla valitus, kaikki ilo on mennyt mailleen, riemu on paennut maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Jäljellä on kaupungissa hävitys, portti on lyöty pirstaleiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Sillä niin on käyvä maan päällä kansojen keskuudessa, kuin öljypuuta karistettaessa, kuin jälkikorjuussa viininkorjuun päätyttyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'He korottavat äänensä ja riemuitsevat. He huutavat mereltä päin Herran valtasuuruudessa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, '\"Sen tähden kunnioittakaa Herraa valon mailla, ja meren saarilla Herran, Israelin Jumalan, nimeä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Maan äärestä kuulemme ylistysvirret: \"Ihana on vanhurskaan osa!\" Mutta sanon: \"Riutuminen, riutuminen on osani, voi minua: ryöstäjät ryöstävät, repien ryöstäjät ryöstävät!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Kauhu, kuoppa ja ansa ovat edessäsi, sinä maan asukas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'Se, joka pakenee kauhun ääntä, putoaa kuoppaan, ja se, joka kuopasta nousee, tarttuu paulaan. Sillä korkeuden ikkunat aukeavat ja maan perustukset järkkyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Maa musertuu murskaksi, maa halkeaa ja hajoaa, maa horjuu ja huojuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Maa hoippuu ja hoipertelee kuin juopunut, huojuu kuin lehvämaja. Raskaana painaa sitä sen rikos, se kaatuu eikä enää nouse.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'Sinä päivänä Herra kostaa korkeuden sotajoukolle korkeudessa ja maan kuninkaille maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'Heidät kootaan sidottuina vankikuoppaan ja suljetaan vankeuteen. Pitkän ajan kuluttua heille kostetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Silloin kuu punastuu, ja aurinko häpeää, sillä Herra Sebaot on kuningas Siionin vuorella ja Jerusalemissa, ja hänen vanhintensa edessä loistaa kirkkaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Herra, sinä olet Jumalani; kunnioitan sinua, kiitän nimeäsi, sillä olet tehnyt ihmeitä, suunnitelmasi kaukaisilta päiviltä ovat todet ja vakaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Sillä olet tehnyt kaupungin kivikasaksi, varustetun kaupungin raunioiksi. Muukalaisten linna on kadonnut kaupunkien luvusta. Sitä ei enää ikinä rakenneta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Sen tähden sinua kunnioittaa voimakas kansa, väkivaltaisten pakanoiden kaupunki sinua pelkää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Sillä olit turvana kurjalle, turvana köyhälle hänen ahdingossaan, suojana rankkasateelta ja varjona helteeltä. Sillä väkivaltaisten vihan vimma on kuin rankkasade seinää vasten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Kuin helteen kuivassa maassa vaimensit muukalaisten melun. Kuin helle pilven varjossa vaipuu väkivaltaisten voittolaulu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Herra Sebaot laittaa kaikille kansoille tällä vuorella pidot rasvasta, pidot viinistä, ydinrasvasta, puhtaasta viinistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'Hän hävittää tällä vuorella verhon, joka verhoaa kaikki kansat, ja peiton, joka peittää kaikki kansakunnat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Hän hävittää kuoleman ainiaaksi, ja Herra, Herra pyyhkii kyyneleet kaikkien kasvoilta ja ottaa pois kansansa häväistyksen kaikesta maasta. Sillä Herra on puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Sinä päivänä sanotaan: \"Katso, tämä on Jumalamme, jota odotimme meitä pelastamaan; tämä on Herra, jota odotimme: iloitkaamme ja riemuitkaamme pelastuksesta, jonka hän toi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Sillä Herran käsi lepää tällä vuorella. Mutta Mooab tallataan siihen paikkaansa, niin kuin oljet tallautuvat lantaveteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'Hän haroo siinä käsiään, kuin uimari haroo uidessaan, mutta Herra painaa alas hänen ylpeytensä sekä hänen käsiensä rimpuilut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Korkeitten muuriesi varustukset hän kukistaa, painaa ne alas ja syöksee maahan tomuun asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'Sinä päivänä lauletaan Juudan maassa tätä laulua: \"Meillä on vahva kaupunki. Pelastuksen hän on pannut sille muuriksi ja varustukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Avatkaa portit vanhurskaan kansan astua sisään, sen, joka pysyy uskollisena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Säilytät eheän rauhan sille, joka sinussa pysyy, sillä hänen turvansa on sinussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Turvatkaa Herraan ainiaan, sillä Herra, Herra on iankaikkinen kallio.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Sillä hän on kukistanut korkealla asuvat, ylhäisen kaupungin. Hän painoi sen alas, painoi maan tasalle ja syöksi sen tomuun asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Sitä tallaa jalka, kurjan jalat, vaivaisten askeleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Vanhurskaan polku on suora, sinä teet vanhurskaan tien tasaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Niin, sinun tuomioittesi tiellä odotamme sinua, Herra. Nimeäsi ja muistoasi sielu ikävöi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Sieluni ikävöi sinua yöllä, henkeni sisimmässäni etsii sinua varhain. Sillä kun tuomiosi kohtaavat maata, maanpiirin asukkaat oppivat vanhurskautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Jos jumalaton saa armon, hän ei opi vanhurskautta. Oikeuden maassa hän tekee vääryyttä eikä näe Herran korkeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Herra, kätesi on kohotettu, mutta he eivät sitä näe. He saakoot häpeäkseen nähdä kiivautesi kansan puolesta. Kuluttakoon heidät tuli, joka vihollisesi kuluttaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Herra, sinä saatat meille rauhan, sillä myös kaikki meidän tekomme sinä olet tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Herra, meidän Jumalamme, meitä ovat vallinneet muut herrat, et sinä. Sinua yksin me ylistämme, sinun nimeäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Kuolleet eivät virkoa eloon, vainajat eivät nouse: niin olet heille kostanut, tuhonnut heidät ja hävittänyt kaiken heidän muistonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Olet lisännyt kansan, Herra, olet lisännyt kansan, olet kunniasi näyttänyt ja laajentanut kaikki maan rajat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Herra, ahdistuksessa he ovat etsineet sinua, vuodattaneet hiljaisia rukouksia, kun heitä kuritit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Kuin raskaana oleva vaimo, joka on synnyttämäisillään, vääntelehtii ja huutaa kivuissaan, niin olimme edessäsi, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Olimme raskaina, vääntelehdimme, mutta oli kuin olisimme synnyttäneet tuulta: emme saaneet aikaan pelastusta maalle eivätkä maanpiirin asukkaat synnyttäneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Mutta sinun kuolleesi virkoavat eloon, minun ruumiini nousevat ylös. Herätkää ja riemuitkaa, te jotka tomussa lepäätte, sillä kasteesi on valkeuksien kaste, ja maa tuo vainajat ilmoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Mene, kansani, kammioihisi ja sulje ovet jälkeesi, kätkeydy hetkeksi, kunnes viha on mennyt ohi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Sillä katso, Herra lähtee asuinsijastaan kostamaan maan asukkaille heidän pahat tekonsa, ja maa paljastaa verivelkansa eikä enää peitä surmattujaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'Sinä päivänä Herra kostaa kovalla, suurella ja väkevällä miekallaan leviatanille, kiitävälle käärmeelle, ja leviatanille, kiemurtelevalle käärmeelle, ja tappaa lohikäärmeen, joka on meressä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'Sinä päivänä sanotaan: \"On viinitarha, parhaan viinin tarha. Laulakaa siitä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, '\'Minä, Herra, olen sen vartija. Kastelen sitä hetkestä hetkeen. Vartioin sitä öin ja päivin, ettei mikään vahingoita sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Vihaa minulla ei ole. Olisipa vain orjantappuroita ja ohdakkeita, niiden kimppuun kävisin sodalla ja polttaisin ne kaikki yhdessä –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'tai säilyttäköön minut voimassani ja tehköön rauhan kanssani, tehköön rauhan kanssani.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Tulevina aikoina juurtuu Jaakob, Israel kukkii ja kukoistaa ja täyttää maanpiirin hedelmällään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Löikö hän sitä, kuten sen lyöjät lyötiin, tapettiinko se, kuten sen tappajat tapettiin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Karkottamalla sen, lähettämällä sen pois rankaisit sitä. Hän pyyhkäisi sen pois kovalla myrskyllään itätuulen päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Sen tähden sovitetaan Jaakobin pahat teot sillä, ja se on hänen syntiensä poistamisen täysi hedelmä, että hän tekee kaikki alttarikivet rikottujen kalkkikivien kaltaisiksi: eivät kohoa enää aserat eivätkä auringonpatsaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Sillä varustettu kaupunki on autio. Se on hylätty maja, tyhjäksi jätetty kuin erämaa. Siellä vasikat käyvät laitumella. Ne siellä makailevat ja kaluavat sieltä kaikki vesat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Kun oksat kuivuvat, ne taitetaan pois. Naiset tulevat ja tekevät niillä tulta. Sillä se ei ole ymmärtäväistä kansaa. Sen tähden sen tekijä ei armahda sitä eikä sen Luoja sääli sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Sinä päivänä Herra karistaa hedelmät maahan Eufrat-virrasta aina Egyptin puroon asti, ja teidät, te israelilaiset, poimitaan talteen yksitellen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Sinä päivänä puhalletaan suureen torveen, ja Assurin maahan häipyneet ja Egyptin maahan karkotetut tulevat ja kumartavat Herraa pyhällä vuorella Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Voi Efraimin juopuneitten ylvästä kruunua ja sen kunnian loisteen kuihtuvaa kukkaa, joka on kukkulan laella, viinistä päihtyneitten lihavan laakson keskellä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Katso, Herralta tulee se, joka on väkevä ja voimakas, kuin raesade, rajumyrsky. Rankkasateen, väkevien tulvavetten kuohun tavoin hän kaataa pilvet voimalla tyhjäksi maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Jalkoihin tallataan Efraimin juopuneitten ylväs kruunu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Sen kunnian loisteen kuihtuvan kukan, joka on kukkulan laella, lihavan laakson keskellä, käy kuin varhaisviikunan ennen kesää: kuka vain sen näkee, tuskin se on hänen kourassaan, niin hän sen jo nielee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'Sinä päivänä Herra Sebaot on oleva loistava kruunu ja kunnian seppele kansansa jäännökselle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'ja oikeuden henki sille, joka oikeutta istuu, ja voima niille, jotka torjuvat hyökkäyksen takaisin porttia kohden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Nämäkin horjuvat viinistä ja hoipertelevat väkijuomasta. Väkijuomasta horjuu pappi ja profeetta. He ovat sekaisin viinistä, hoipertelevat väkijuomasta. He horjuvat näyissä, huojuvat tuomioissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Sillä täynnä oksennusta ja saastaa ovat kaikki pöydät – ei ole puhdasta paikkaa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, '\"Keitähän tuokin luulee taitoon neuvovansa, keitä saarnalla opettavansa? Olemmeko me vasta maidosta vieroitettuja, äidin rinnoilta otettuja?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Käsky käskyn perään, käsky käskyn perään, höpötystä höpötyksen jälkeen, höpötystä höpötyksen jälkeen, milloin sitä, milloin tätä!\" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Niin, sopertavin huulin ja vieraalla kielellä hän on puhuva tälle kansalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'hän, joka on sanonut heille: \"Tässä on lepo; antakaa väsyneen levätä, tässä on levähdyspaikka.\" Mutta he eivät tahtoneet kuulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'Niinpä Herran sana on oleva heille: \"Käsky käskyn perään, käsky käskyn perään, höpötystä höpötyksen jälkeen, höpötystä höpötyksen jälkeen, milloin sitä, milloin tätä\", niin että he kulkiessaan kaatuvat selälleen ja ruhjoutuvat, jotta heidät kiedotaan ja vangitaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Sen tähden kuulkaa Herran sana, te pilkkaajat, te jotka hallitsette tätä kansaa Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Koska te sanotte: \"Olemme tehneet liiton kuoleman kanssa ja sopimuksen helvetin kanssa. Tulkoon vitsaus kuin tulva, se ei meitä saavuta, sillä olemme tehneet valheen turvaksemme ja piiloutuneet petokseen\" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'sen tähden, näin sanoo Herra, Herra: Katso, lasken Siioniin peruskiven, koetellun kiven, kalliin kulmakiven, lujasti perustetun. Joka uskoo, se ei pakene.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Panen oikeuden mittanuoraksi ja vanhurskauden vaa\'aksi. Silloin rakeet hävittävät valheturvan, ja vedet huuhtovat pois piilopaikan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Liittonne kuoleman kanssa pyyhkäistään pois, eikä teidän sopimuksenne helvetin kanssa kestä. Kun vitsaus tulee kuin tulva, se tallaa teidät maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Niin usein kuin se tulee, tempaa se teidät valtaansa, sillä se tulee aamu aamulta, se tulee sekä päivällä että yöllä: totisesti, kauhuksi on tämän saarnan opetus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Sillä vuode on oleva liian lyhyt ojentautua ja peitto liian kaita kääriytyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Sillä Herra nousee kuin Perasimin vuorella, hän kiivastuu kuin Gibeonin laaksossa tehdäkseen työnsä, oudon työnsä, ja toimittaakseen tekonsa, kumman tekonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Älkää siis pilkatko, etteivät teidän siteenne vielä kiristyisi. Sillä Herralta Sebaotilta olen kuullut hävitys- ja tuomiopäätöksen, joka on kohtaava kaikkea maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Kuunnelkaa ja kuulkaa ääntäni, tarkatkaa ja kuulkaa sanojani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Ainako kyntäjä kyntää, muokkaa ja äestää maataan saadakseen satoa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Eikö niin: kun hän on tasoittanut sen pinnan, hän kylvää mustaa kuminaa, sirottelee maustekuminaa, panee vehnänjyvät riviin, ohran omaan paikkaansa ja spelttivehnää vierelle?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Hänen Jumalansa on neuvonut hänelle oikean tavan ja opettaa häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Sillä ei mustaa kuminaa puida puimaäkeellä eikä puimajyrän tela pyöri maustekuminan yli, vaan musta kumina lyödään irti sauvalla ja maustekumina kepillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Puidaanko leipävilja murskaksi? Ei sitä kukaan pui loputtomiin eikä aina aja sen yli puimajyrällään ja hevosillaan. Sitä ei puida murskaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Tämäkin on tullut Herralta Sebaotilta. Hänen neuvonsa on ihmeellinen ja ymmärryksensä hyvin suuri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Voi Arielia, Arielia, kaupunkia, jonne Daavid asetti leirinsä! Liittäkää vuosi vuoteen, kiertäkööt juhlat kiertonsa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'ahdistan Arielia, ja se on oleva täynnä valitusta ja vaikerrusta. Se on oleva minulle kuin Jumalan uhriliesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Asetan leirini yltympäri sinua vastaan ja saarran sinut vartiostoilla ja luon vallit sinua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Puhut maasta matalalta, sanasi tulevat vaimeina tomusta, sopertelet kuin vainajahenki maasta, puheesi tulee supisten tomusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Mutta sinun vainolaistesi lauma on oleva kuin hieno pöly, ja väkivaltaisten lauma kuin lentävät akanat, ja tämä tapahtuu äkkiä, silmänräpäyksessä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Herra Sebaot etsii sinua ukkosenjylinässä ja maanjäristyksessä, kovassa pauhinassa, myrskyssä ja rajuilmassa, kuluttavan tulen liekissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Kuin yöllinen uninäky on oleva kansojen lauma, joka sotii Arielia vastaan, kaikki ne, jotka sotivat sitä ja sen varustuksia vastaan ja ahdistavat sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Kuin nälkäinen on unissaan syövinään, mutta herää nälkä sydämessä, ja kuin janoinen on unissaan juovinaan, mutta herää, ja katso, hän on nääntynyt ja hänellä on kova jano, niin on oleva kaikki kansojen lauma, joka sotii Siionin vuorta vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Hämmästykää ja ihmetelkää, tuijottakaa itsenne sokeiksi ja sokeiksi jääkää! He ovat juovuksissa, vaikkeivät viinistä. He hoipertelevat, vaikkeivät väkijuomasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Sillä Herra on vuodattanut teidän päällenne raskaan unen hengen ja sulkenut teidän silmänne – profeettanne, ja peittänyt päänne – näkijänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Kaikki ilmoitus on teille kuin lukitun kirjan sanat. Jos se annetaan lukutaitoiselle ja sanotaan: \"Lue tämä\", hän vastaa: \"En voi, sillä se on lukittu\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'Jos taas kirja annetaan lukutaidottomalle ja sanotaan: \"Lue tämä\", hän vastaa: \"En osaa lukea.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Niin Herra sanoi: Koska tämä kansa lähestyy minua suullaan ja kunnioittaa minua huulillaan, mutta pitää sydämensä minusta kaukana, ja koska heidän jumalanpelkonsa on vain opittuja ihmiskäskyjä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'sen tähden, katso, teen tälle kansalle vielä outoja tekoja – kummia ja ihmeitä, ja sen viisaitten viisaus häviää, ja sen ymmärtäväisten ymmärrys katoaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Voi niitä, jotka kätkevät syvälle hankkeensa Herralta, joiden teot tapahtuvat pimeässä ja jotka sanovat: \"Kuka meidät näkee, kuka meistä tietää?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Voi mielettömyyttänne! Onko savi savenvalajan veroinen? Ja sanooko työ tekijästään: \"Ei hän ole minua tehnyt\", tai sanooko kuva piirtäjästään: \"Ei hän mitään ymmärrä\"?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Vain lyhyt hetki enää, niin Libanon muuttuu puutarhaksi, ja puutarha on metsän veroinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'Sinä päivänä kuurot kuulevat kirjan sanat, ja sokeiden silmät näkevät vapaina synkästä pimeydestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Nöyrät saavat yhä uutta iloa Herrassa, ja ihmisistä köyhimmätkin riemuitsevat Israelin Pyhästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Sillä väkivaltaisista on tullut loppu, pilkkaajat ovat hävinneet, ja kaikki vääryyteen valppaat on tuhottu,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'ne, jotka sanallaan saattavat ihmisiä tekemään syntiä ja virittävät pauloja sille, joka oikeutta puolustaa portissa, ne, jotka vääntävät tekosyillä syyttömän asian vääräksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Sen tähden Herra, joka vapahti Aabrahamin, sanoo Jaakobin heimolle näin: Ei Jaakob enää joudu häpeään, eivätkä hänen kasvonsa enää kalpene.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Sillä kun hän näkee, kun hänen lapsensa näkevät keskellään kätteni työn, he pyhittävät nimeni, pitävät pyhänä Jaakobin Pyhän ja pelkäävät Israelin Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Silloin hengessään eksyvät käsittävät ymmärryksen ja kapinoivat ottavat opikseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Voi uppiniskaisia lapsia, sanoo Herra, niitä, jotka pitävät neuvoa, mikä ei ole minusta, ja hierovat liittoa ilman Henkeäni kooten syntiä synnin päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'Voi niitä, jotka menevät Egyptiin minulta kysymättä turvautuakseen faraoon ja etsiäkseen suojaa Egyptin varjossa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Faraon turva koituu teille häpeäksi ja suojan etsiminen Egyptin varjosta häväistykseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Sillä vaikka hänen ruhtinaansa ovat Sooanissa ja hänen sanansaattajansa ovat saapuneet Haanekseen asti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'he joutuvat kaikki häpeään kansan tähden, josta heillä ei ole hyötyä – ei apua, ei hyötyä, vaan häpeää ja pilkkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Profeettasana Eteläisen maan Behemotia vastaan. Halki ahdingon ja ahdistuksen maan, halki naarasleijonan ja leijonan maan, kyykäärmeen ja lentävän käärmeen maan he kuljettavat aasinvarsojen selässä rikkautensa ja kamelien kyttyrällä aarteensa kansalle, josta ei ole hyötyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Egyptin apu on turha ja tyhjä; sen tähden annan sille nimen: \"Rahab, joka ei pääse paikaltaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Mene siis nyt ja kirjoita se tauluun heidän läsnä ollessaan ja piirrä se kirjaan, että se säilyisi tuleviin aikoihin, ainiaan, ikuisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Sillä he ovat niskoitteleva kansa. He ovat vilpillisiä lapsia, lapsia, jotka eivät tahdo kuulla Herran lakia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'jotka sanovat näkijöille: \"Älkää nähkö\", ja ennustajille: \"Älkää ennustako meille tosia, puhukaa meille mieluisia, ennustakaa silmänlumeita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Poiketkaa tieltä, väistykää polulta; viekää pois silmistämme Israelin Pyhä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Sen tähden, näin sanoo Israelin Pyhä: Koska halveksitte tätä sanaa ja luotatte väkivaltaan ja vääryyteen ja turvaudutte siihen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'tämä synti on oleva kuin repeämä korkeassa muurissa, joka uhkaa sortua ja pullistuu. Se särkyy äkkiä, yhtäkkiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'Se särkyy, kuin särkyy savenvalajan astia, joka lyödään rikki säälimättä, niin ettei sen sirpaleista löydy palasta, millä ottaa tulta liedestä tai ammentaa vettä altaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Sillä näin sanoo Herra, Herra, Israelin Pyhä: Kääntymällä ja pysymällä hiljaa pelastutte, rauhallisuus ja luottamus on voimanne, mutta te ette tahtoneet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'vaan sanoitte: \"Ei! Hevosilla tahdomme kiitää\" – niinpä saatte kiitää pakoon. \"Nopean selässä me tahdomme ratsastaa\" – niinpä ovat vainoajanne nopeat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Tuhat pakenee yhden uhkaa. Viiden uhkaa te pakenette, kunnes se, mikä teistä jää, on kuin merkkipuu vuoren huipulla, kuin lipputanko kukkulalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Sen tähden Herra odottaa antaakseen teille armonsa, sen tähden hän nousee armahtaakseen teitä, sillä Herra on oikeuden Jumala. Autuaita kaikki, jotka häntä odottavat!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Sinä kansa, joka asut Siionissa, Jerusalemissa, älä itke! Jo häneltä apua huutaessasi hän on sinulle totisesti armollinen. Sen kuullessaan hän jo vastaa sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Vaikka Herra antaa teille hädän leipää ja ahdistuksen vettä, niin opettajasi ei enää kätkeydy, vaan silmäsi saavat nähdä opettajasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'Silloin korvasi kuulevat takaasi tämän sanan, milloin poikkeatte oikealle tai vasemmalle: \"Tässä on tie, sitä kulkekaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Silloin sinä julistat saastaiseksi veistettyjen jumalankuviesi hopeapäällyksen ja valettujen jumalankuviesi kultakuoren. Sinä heität ne pois kuin jonkin inhottavan ja sanot niille: \"Ulos!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Hän antaa sateen siemenellesi, jonka kylvät maahan, ja maan sadosta leivän, joka on oleva mehevä ja lihava, ja karjasi on sinä päivänä käyvä laajalla laitumella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Härät ja aasinvarsat, jotka tekevät peltotyötä, syövät suolaista rehuviljaa, joka on viskattu hangolla ja viskimellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Silloin kaikilla korkeilla vuorilla ja kaikilla ylhäisillä kukkuloilla on oleva puroja, vesivirtoja, suuren surmaamisen päivänä tornien sortuessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Silloin kuun valo on oleva kuin auringon valo, ja auringon valo on oleva seitsenkertainen. Se on oleva kuin seitsemän päivän valo, sinä päivänä, jona Herra sitoo kansansa vammat ja parantaa siihen isketyt haavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Katso, Herran nimi tulee kaukaa. Hänen vihansa leimuaa. Sankka savu tupruaa. Hänen huulensa ovat täynnä vihaa, ja hänen kielensä on kuin kuluttava tuli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'Hänen hengityksensä on kuin virta, joka tulvii ja ulottuu kaulaan asti. Se seuloo kansoja turmion seulalla ja panee eksyttävät suitset kansakuntien suupieliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Te veisaatte kuin yöllä, kun pyhä juhla alkaa, ja sydämenne riemuitsee niin kuin sen, joka huilujen soidessa astuu vaeltaen Herran vuorelle, Israelin kalliolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Herra antaa kuulla äänensä voiman ja nähdä käsivartensa laskeutuvan alas vihan tuimuudessa ja kuluttavan tulen liekissä, myrskysateina, rankkasateena ja raekivinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Sillä Herran äänestä pelästyy Assur. Hän lyö vitsalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'Silloin jokaisella ruoskan iskulla, jolla Herra häntä satuttaa, soivat tamburiinit ja harput, ja hän sotii häntä vastaan, sotii kättä heiluttaen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Sillä jo aikoja sitten on polttopaikka valmistettu. Kuninkaallekin se on varattu. Syvä ja leveä on sen valkea, tulta ja polttopuita on paljon. Herran Henki sytyttää sen kuin laavavirta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Voi niitä, jotka menevät alas Egyptiin etsimään apua ja turvautuvat hevosiin, luottavat sotavaunuihin, koska niitä on paljon, ja ratsumiehiin, koska niiden lukumäärä on hyvin suuri, mutta eivät katso Israelin Pyhään eivätkä kysy neuvoa Herralta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Mutta myös hän on viisas ja tuottaa onnettomuuden. Hän ei peruuta sanojaan, vaan nousee pahantekijöiden sukua vastaan ja väärintekijöiden apuun tuloa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Egypti on ihminen eikä Jumala, ja heidän hevosensa ovat lihaa eivätkä henkeä. Kun Herra ojentaa kätensä, suistuu auttaja, ja autettava kaatuu, ja yhdessä he kumpikin hukkuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Sillä näin on Herra minulle sanonut: Niin kuin leijona, nuori leijona, murisee saaliinsa ääressä, kun sitä vastaan hälytetään paimenten täysi joukko, eikä pelästy heidän huutoaan, ei huoli heidän hälinästään, niin Herra Sebaot on astuva alas sotimaan Siionin vuorelle ja sen kukkulalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Kuin liitelevät linnut, niin Herra Sebaot varjelee Jerusalemia – varjelee ja pelastaa, säästää ja vapahtaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Palatkaa, te israelilaiset, hänen luokseen, josta olette niin kauas luopuneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Sillä sinä päivänä jokainen hylkää hopeiset ja kultaiset epäjumalansa, jotka kätenne ovat tehneet teille synniksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Silloin Assur kaatuu miekkaan, joka ei ole miehen, ja hänet syö miekka, joka ei ole ihmisen. Hän pakenee miekkaa, ja hänen nuorukaisensa joutuvat työorjuuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Hänen kallionsa kukistuu kauhusta, ja hänen ruhtinaansa säikkyvät lipun luota pakoon, sanoo Herra, jonka tuli on Siionissa ja ahjo Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Katso, kuningas on hallitseva vanhurskaudessa, ja valtiaat vallitsevat oikeuden mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Jokainen heistä on oleva turvana tuulelta ja suojana rankkasateelta, kuin vesipurot kuivassa maassa, kuin korkean kallion varjo nääntyvässä maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Näkevien silmät eivät ole sokaistut, ja kuulevien korvat kuulevat tarkasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'Ajattelemattomien sydän käsittää taidon, ja änkyttävien kieli puhuu sujuvasti ja selkeästi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Houkkaa ei enää kutsuta jaloksi eikä petollista enää sanota yleväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Sillä houkka puhuu houkan lailla, ja hänen sydämensä hankkii turmiota, ja niin hän harjoittaa riettautta ja puhuu eksyttävästi Herrasta, jättää tyhjäksi nälkäisen sielun ja janoisen juomaa vaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Pahat ovat petollisen aseet, hän miettii ilkitöitä tuhotakseen kurjat valheen sanoilla, vaikka köyhä puhuisi miten oikeaa asiaa tahansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Mutta jalo miettii jaloja ja pysyy lujana jaloudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Nouskaa, te suruttomat naiset, kuulkaa ääntäni; te huolettomat tyttäret, tarkatkaa sanojani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Vielä vuosi ja joitakin päiviä sen päälle, niin vapisette, te huolettomat. Sillä silloin on viininkorjuusta tullut loppu, hedelmänkorjuuta ei tule.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Kauhistukaa, te suruttomat, vaviskaa, te huolettomat, riisuutukaa, paljastukaa, vyöttäkää säkki lanteillenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Silloin valitetaan ja lyödään rintoihin ihanien peltojen tähden ja hedelmällisten viiniköynnösten tähden,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'kansani maan tähden, joka kasvaa orjantappuraa ja ohdaketta, remuavan kaupungin kaikkien iloisten talojen tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Sillä palatsi on hylätty, kaupungin kohina lakannut, Oofel ja vartiotorni ovat jääneet ikuisesti luoliksi, villiaasien iloksi ja laumojen laitumeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'Näin on siihen asti, kunnes päällemme vuodatetaan Henki korkeudesta. Silloin erämaa muuttuu puutarhaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'ja puutarha on metsän veroinen. Silloin erämaassa asuu oikeus ja puutarhassa asustaa vanhurskaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'Silloin vanhurskauden hedelmä on rauha, vanhurskauden vaikutus on lepo ja turvallisuus iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Silloin kansani asuu rauhan majoissa, turvallisissa asunnoissa, huolettomissa lepopaikoissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Mutta raesade tulee, metsä kaatuu, ja kaupunki alennetaan alhaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Onnelliset te, jotka kylvätte kaikkien vetten vierille ja laskette härän ja aasin jalat kulkemaan valtoimina!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Voi sinua hävittäjää, sinua, jota itseäsi ei ole hävitetty, sinua ryöstäjää, jota kukaan ei ole ryöstänyt! Kun olet saanut päätökseen hävitystyösi, hävitetään sinut, kun olet ryöstösi ryöstänyt, ryöstetään sinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Herra, armahda meitä, sinua me odotamme. Ole näiden käsivarsi joka aamu, ole apumme hädän aikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Kansat pakenevat jyrinäsi ääntä. Kun sinä nouset, hajoavat kansakunnat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Saaliinne viedään, niin kuin tuhosirkat vievät. Niin kuin hyppysirkat hyökkäävät, niin sen kimppuun hyökätään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Herra on korkea, sillä hän asuu korkeudessa. Hän täyttää Siionin oikeudella ja vanhurskaudella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Silloin hän on sinun aikojesi vakuus, avun runsaus, viisaus ja ymmärrys. Herran pelko on oleva Siionin aarre.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Katso, sankarit huutavat ulkona, rauhan sanansaattajat itkevät katkerasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Tiet ovat autioina, polulta on kulkija poissa. Hän on rikkonut liiton, ylenkatsonut kaupungit, ei ole pitänyt ihmistä minään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Maa murehtii ja nääntyy, Libanon kuihtuu häpeästä, Saaron on aromaaksi tullut, Baasan ja Karmel varistavat lehtensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Nyt nousen, sanoo Herra, nyt korotan itseni, nyt kohoan korkealle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Olkia te kannatte kohdussanne, akanoita synnytätte. Teidän kiukkunne on tuli, joka kuluttaa teidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Kansat poltetaan kuin kalkki, kuin katkotut orjantappurat, jotka palavat tulessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Kuulkaa, te kaukaiset, mitä olen tehnyt, te lähellä olevat, tuntekaa voimani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Syntiset Siionissa pelästyvät, vapina valtaa jumalattomat: \"Kuka meistä voi asua kuluttavassa tulessa, kuka asua iankaikkisessa hehkussa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Joka vanhurskaudessa vaeltaa ja puhuu sitä, mikä on oikein, joka halveksii väärää voittoa, jonka käsi torjuu lahjukset luotaan, joka tukkii korvansa kuulemasta veritöitä ja sulkee silmänsä näkemästä pahaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'hän on asuva kukkuloilla, kalliolinnat ovat hänen turvansa, hänelle annetaan hänen leipänsä, eikä vesi häneltä ehdy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Silmäsi saavat katsoa kuningasta hänen ihanuudessaan. Ne saavat nähdä avaran maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Sydämesi muistelee kauhuja: missä on nyt veronlaskija, missä punnitsija, missä tornien lukija?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Et näe enää sitä röyhkeää kansaa, kansaa, jolla on outo, käsittämätön puhe, jonka sopertavaa kieltä ei kukaan ymmärrä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Katso Siionia, juhliemme kaupunkia. Silmäsi näkevät Jerusalemin, rauhan asuinsijan, telttamajan, jota ei muuteta, jonka vaarnoja ei ikinä reväistä irti, jonka köysistä ei katkaista yhtään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Sillä voimallinen meillä on siellä Herra, siellä ovat joet, ovat virrat, leveät rannasta toiseen, joita ei kulje soutualus, joiden poikki ei pääse uljas laiva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Sillä Herra on tuomarimme, Herra on johdattajamme, Herra on kuninkaamme. Hän pelastaa meidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Nyt ovat köytesi höltyneet. Ne eivät pidä mastoa kannassaan kiinni eivätkä vedä lippua liehumaan. Mutta silloin jaetaan riistosaalista runsaasti, rammatkin ryöstävät ja raastavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'Eikä yksikään asukas sano: \"Minä olen vaivanalainen.\" Kansa, joka siellä asuu, on saanut syntinsä anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Astukaa esiin, te kansat, ja kuulkaa; te kansakunnat, ottakaa varteen. Kuulkoon maa ja kaikki, mitä siinä on, maanpiiri ja kaikki, mikä siitä kasvaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Sillä Herra on vihastunut kaikkiin kansoihin ja kiivastunut kaikkiin heidän joukkoihinsa. Hän on vihkinyt heidät tuhon omiksi, jättänyt heidät teurastettaviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Heidän surmattunsa heitetään pois, ja niiden raadoista nousee löyhkä, ja vuoret valuvat heidän vertaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Kaikki taivaan joukot menehtyvät, taivas kääritään kokoon kuin kirja, ja kaikki sen joukot varisevat alas, niin kuin lehdet varisevat viinipuusta, niin kuin raakileet viikunapuusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Sillä miekkani taivaassa on juopunut. Katso, se iskee alas Edomiin tuomioksi kansalle, jonka olen vihkinyt tuhoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Herran miekka on verta täynnä, rasvaa helmeilevä, karitsojen ja kauristen verta, pässien munuaisrasvaa. Sillä Herralla on uhri Bosrassa, suuri teurastus Edomin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Re\'eem-eläimiä kaatuu yhteen joukkoon, mulleja härkien mukana. Heidän maansa juopuu verestä, ja heidän multansa helmeilee rasvaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Sillä Herralla on koston päivä, maksun vuosi Siionin asian puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Edomin purot muuttuvat pieksi ja sen multa laavaksi, sen maa tulee palavaksi pieksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Se ei sammu yöllä eikä päivällä, iäti nousee siitä savu. Se on oleva raunioina polvesta polveen, siellä ei kulje kukaan, iankaikkisesta iankaikkiseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Sen perivät pelikaanit ja siilit, pöllöt ja korpit asuvat siellä. Hän vetää sen yli autiuden mittanuoran ja tyhjyyden luotilangan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Siellä ei ole enää ylimyksiä huutamassa ketään kuninkaaksi, kaikki sen ruhtinaat ovat poissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Sen palatsit kasvavat orjantappuroita, sen linnat nokkosia ja ohdakkeita. Siitä tulee sakaalien asunto ja strutsien tyyssija.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Siellä erämaan eläimet ja sakaalit yhtyvät, vuohipukit tapaavat toisiaan. Siellä öinen kulkija saa yksin rauhan ja löytää lepopaikan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Siellä nuolikäärme pesii ja laskee munansa, kuorii ne ja kiertyy kerälle pimentoonsa. Sinne haarahaukatkin kokoontuvat yhteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Etsikää Herran kirjasta ja lukekaa: näistä ei tule puuttumaan yhtään eikä yksikään ole toistaan kaipaava. – \"Sillä minun suuni on niin käskenyt.\" – Hänen Henkensä on koonnut ne yhteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Hän on heittänyt arpaa niiden kesken, ja hänen kätensä on jakanut sen niille mittanuoralla. Ne perivät sen ikiajoiksi ja asuvat siellä polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Erämaa ja kuiva hietikko iloitsevat, aromaa riemuitsee ja kukoistaa kuin lilja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Se kukoistaa kauniisti ja iloitsee ilolla ja riemulla. Sille annetaan Libanonin kunnia, Karmelin ja Saaronin ihanuus. He saavat nähdä Herran kunnian, Jumalamme ihanuuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Vahvistakaa hervonneet kädet, voimistakaa horjuvat polvet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Sanokaa hätääntyneille sydämille: \"Olkaa lujat, älkää pelätkö. Katso, teidän Jumalanne! Kosto tulee, Jumalan rangaistus. Hän tulee ja pelastaa teidät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Silloin avautuvat sokeiden silmät ja kuurojen korvat aukeavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Silloin rampa hyppii kuin peura ja mykän kieli ratkeaa riemuun, sillä erämaahan puhkeavat vedet ja aromaahan purot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'Hehkuva hiekka tulee lammikoiksi ja kuiva maa vesilähteiksi. Sakaalien asunnossa, missä ne makasivat, kasvaa ruoho sekä ruoko ja kaisla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Silloin siellä on oleva valtatie, ja sen nimi on \"pyhä tie\". Sitä ei kulje saastainen. Se on heitä itseään varten. Se, joka sitä tietä kulkee, ei eksy – eivät hullutkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Ei siellä ole leijonaa, ei sinne nouse raateleva peto. Sellaista siellä ei tavata. Lunastetut sitä kulkevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Herran vapahdetut palaavat ja tulevat Siioniin riemuiten päänsä päällä iankaikkinen ilo. Riemu ja ilo saavuttavat heidät, mutta murhe ja huokaus pakenevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Kuningas Hiskian neljäntenätoista hallitusvuotena hyökkäsi Sanherib, Assurin kuningas, kaikkien Juudan varustettujen kaupunkien kimppuun ja valloitti ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Assurin kuningas lähetti Laakiista Rabsaken suuren sotajoukon kanssa kuningas Hiskiaa vastaan Jerusalemiin ja [Rabsake] pysähtyi Ylälammikon vesijohdolle, joka on Vanuttajankedon tien varrella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Eljakim, Hilkian poika, joka oli palatsin päällikkönä, ja kirjuri Sebna ja kansleri Jooah, Aasafin poika, menivät hänen luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Rabsake sanoi heille: \"Sanokaa Hiskialle: Näin sanoo suurkuningas, Assurin kuningas: \'Mitä on tuo luottamus, joka sinulla on?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Sanon: pelkkää huulten puhetta on tuollainen neuvo ja voima sodankäyntiin. Keneen sinä oikein luotat, kun kapinoit minua vastaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Katso, sinä luotat Egyptiin, tuohon särkyneeseen ruokosauvaan, joka tunkeutuu sen käteen, joka siihen nojaa, ja lävistää sen. Sellainen on farao, Egyptin kuningas, kaikille, jotka häneen luottavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Vai sanotko ehkä minulle: Me luotamme Herraan, Jumalaamme? Mutta eikö hän ole se, jonka uhrikukkulat ja alttarit Hiskia poisti, kun hän sanoi Juudalle ja Jerusalemille: Tämän alttarin edessä on teidän kumartaen rukoiltava?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Mutta lyö nyt vetoa herrani, Assurin kuninkaan, kanssa: annan sinulle kaksi tuhatta hevosta, jos voit antaa niille ratsastajat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Kuinka sitten voisit torjua ainoankaan käskynhaltijan, ainoankaan herrani vähimmän palvelijan, hyökkäyksen? Mutta sinä luotat Egyptiin, sen vaunuihin ja ratsumiehiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Olenko nyt Herran sallimatta hyökännyt tähän maahan hävittämään sitä? Herra itse on sanonut minulle: \'Hyökkää tähän maahan ja hävitä se.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Eljakim, Sebna ja Jooah sanoivat Rabsakelle: \"Puhu palvelijoillesi aramin kieltä, sillä me ymmärrämme sitä; älä puhu meille juudan kieltä kansan kuullen, jota on muurilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Mutta Rabsake vastasi: \"Onko herrani lähettänyt minut puhumaan näitä sanoja herrallesi ja sinulle? Eikö juuri niille miehille, jotka istuvat muurilla ja joutuvat kanssanne syömään omaa likaansa ja juomaan omaa vettänsä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Sitten Rabsake astui esiin, huusi kovalla äänellä juudan kielellä ja sanoi: \"Kuulkaa suurkuninkaan, Assurin kuninkaan, sanoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Näin sanoo kuningas: \'Älkää antako Hiskian pettää itseänne, sillä hän ei voi teitä pelastaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Älköön Hiskia saako teitä luottamaan Herraan, kun hän sanoo: Herra on varmasti pelastava meidät. Tätä kaupunkia ei anneta Assurin kuninkaan käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Älkää kuulko Hiskiaa.\' Sillä Assurin kuningas sanoo näin: \'Tehkää sovinto kanssani ja antautukaa minulle, niin saatte syödä kukin viinipuustanne ja viikunapuustanne ja juoda kukin kaivostanne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'kunnes tulen ja vien teidät maahan, joka on teidän maanne kaltainen, vilja- ja viinimaahan, leivän ja viinitarhojen maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Älköön Hiskia vietelkö teitä, sanoessaan: Herra pelastaa meidät. Onko muidenkaan kansojen jumalista kukaan pelastanut maatansa Assurin kuninkaan käsistä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Missä ovat Hamatin ja Arpadin jumalat? Missä ovat Sefarvaimin jumalat? Ovatko ne pelastaneet Samariaa minun käsistäni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Kuka näiden maiden kaikista jumalista on pelastanut maansa käsistäni? Kuinka sitten Herra pelastaisi Jerusalemin käsistäni?\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Mutta he olivat vaiti eivätkä vastanneet hänelle mitään, sillä kuningas oli käskenyt niin ja sanonut: \"Älkää vastatko hänelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Sitten palatsin päällikkö Eljakim, Hilkian poika, ja kirjuri Sebna ja kansleri Jooah, Aasafin poika, tulivat Hiskian luo vaatteet reväistyinä ja kertoivat hänelle, mitä Rabsake oli sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Kun kuningas Hiskia kuuli sen, hän repäisi vaatteensa, pukeutui säkkiin ja meni Herran temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Hän lähetti palatsin päällikön Eljakimin ja kirjuri Sebnan sekä pappien vanhimmat säkkeihin puettuina profeetta Jesajan, Aamosin pojan, luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'He sanoivat hänelle: \"Näin sanoo Hiskia: \'Hädän, kurituksen ja häväistyksen päivä on tämä päivä, sillä lapset ovat tulleet kohdun suulle saakka, mutta ei ole voimaa synnyttää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Ehkä Herra, Jumalasi, kuulee Rabsaken sanat, joilla hänen herransa, Assurin kuningas, on lähettänyt hänet herjaamaan elävää Jumalaa, ja rankaisee häntä näistä sanoista, jotka Herra, Jumalasi, on kuullut. Kohota nyt rukous jäännöksen puolesta, joka vielä on olemassa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Kun kuningas Hiskian palvelijat tulivat Jesajan luo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'Jesaja sanoi heille: \"Näin sanokaa herrallenne: \'Näin sanoo Herra: Älä pelkää niitä sanoja, jotka olet kuullut ja joilla Assurin kuninkaan poikaset ovat häväisseet minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Katso, annan sellaisen hengen mennä häneen, että hän kuultuaan sanoman palaa omaan maahansa. Annan hänen kaatua miekkaan omassa maassaan.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Niin Rabsake kääntyi takaisin ja tapasi Assurin kuninkaan sotimassa Libnaa vastaan. Hän oli näet kuullut, että tämä oli lähtenyt pois Laakiista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Mutta kun Sanherib kuuli Tirhakasta, Kuusin kuninkaasta, sanottavan: \"Hän on lähtenyt liikkeelle sotiakseen sinua vastaan\", hän sen kuultuaan lähetti sanansaattajat Hiskian luo ja käski sanoa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, '\"Sanokaa näin Hiskialle, Juudan kuninkaalle: \'Älä anna Jumalasi, johon luotat, pettää itseäsi äläkä ajattele: Jerusalem ei joudu Assurin kuninkaan käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Olethan kuullut, mitä Assurin kuninkaat ovat tehneet kaikille maille, kuinka he ovat vihkineet ne tuhon omiksi. Sinäkö pelastuisit!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Ovatko kansojen jumalat pelastaneet niitä, jotka isäni ovat tuhonneet: Goosania, Harrania, Resefiä ja Telassarin edeniläisiä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Missä on Hamatin kuningas ja Arpadin kuningas, Sefarvaimin kaupungin, Heenan ja Ivvan kuningas?\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Kun Hiskia oli ottanut kirjeen sanansaattajilta ja lukenut sen, hän meni Herran temppeliin, ja Hiskia levitti sen Herran eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Sitten Hiskia rukoili Herraa ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, '\" Herra Sebaot, Israelin Jumala, jonka valtaistuinta kerubit kannattavat, sinä yksin olet maan kaikkien valtakuntien Jumala. Sinä olet tehnyt taivaan ja maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Herra, kallista korvasi ja kuule; Herra, avaa silmäsi ja katso. Kuule kaikki Sanheribin sanat, jotka hän lähetti herjatakseen elävää Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Se on totta, Herra, että Assurin kuninkaat ovat hävittäneet kaikki maat ja omankin maansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'He ovat heittäneet niiden jumalat tuleen, sillä ne eivät olleet jumalia, vaan ihmiskätten tekoa, puuta ja kiveä, ja sen tähden he saattoivat hävittää ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Mutta pelasta nyt meidät, Herra, Jumalamme, hänen käsistään, että kaikki maan valtakunnat tietäisivät, että sinä, Herra, olet ainoa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Jesaja, Aamosin poika, lähetti Hiskialle tämän sanan: \"Näin sanoo Herra, Israelin Jumala: Koska olet rukoillut minua avuksi Sanheribia, Assurin kuningasta, vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'niin tämä on se sana, jonka Herra on puhunut hänestä: Neitsyt, tytär Siion, halveksii ja pilkkaa sinua. Tytär Jerusalem nyökyttää ilkkuen päätään sinun jälkeesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Ketä olet herjannut ja häväissyt, ja ketä vastaan olet korottanut äänesi? Korkealle olet kohottanut silmäsi Israelin Pyhää vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Palvelijaisi kautta sinä herjasit Herraa ja sanoit: \'Monilla vaunuillani minä nousin vuorten harjalle Libanonin ääriin saakka ja hakkasin maahan sen korkeat setrit, sen parhaat sypressit, ja tunkeuduin sen etäisimmälle harjalle, sen rehevimpään metsään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Minä kaivoin kaivoja ja join kuiviin vedet, ja jalkapohjallani kuivasin kaikki Egyptin virrat.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Etkö ole kuullut: kauan sitten olen tätä valmistellut, muinaisuudesta saakka olen tämän aikonut tehdä! Nyt olen sen toteuttanut, ja niin hävitit varustetut kaupungit autioiksi kivikasoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Niiden asukkaat olivat voimattomia, kauhistuivat ja joutuivat häpeään. Heidän kävi kuin kedon ruohon ja kuin vihannan heinän, kuin katolla kasvavien korsien ja kuin laihon ennen oljelle tulemista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Istuitpa tai lähdit tai tulit, sen tiedän, niin kuin senkin, että raivoat minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Koska minua vastaan raivoat ja koska ylpeytesi on tullut korviini, panen koukkuni nenääsi ja suitseni suuhusi ja vien sinut takaisin samaa tietä, jota tulitkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Tämä on oleva sinulle merkkinä: tänä vuonna syödään jälkikasvua ja toisena vuonna kylvämättä kasvanutta, mutta kolmantena vuonna kylväkää ja leikatkaa, istuttakaa viinitarhoja ja syökää niiden hedelmää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Juudan heimon pelastuneet, jotka ovat jääneet jäljelle, tekevät taas juurta alaspäin ja hedelmää ylöspäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Sillä Jerusalemista lähtee kasvamaan jäännös, pelastunut joukko Siionin vuorelta. Herran Sebaotin kiivaus on sen tekevä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Sen tähden, näin sanoo Herra Assurin kuninkaasta: Hän ei tule tähän kaupunkiin eikä ammu siihen nuolia. Hän ei tuo sitä vastaan kilpeä eikä luo sitä vastaan vallia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Samaa tietä, jota hän tuli, hän palaa, mutta tähän kaupunkiin hän ei tule, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Sillä varjelen tämän kaupungin ja pelastan sen itseni tähden ja palvelijani Daavidin tähden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Herran enkeli lähti ja löi Assurin leirissä sata kahdeksankymmentä viisi tuhatta miestä, ja kun noustiin aamulla varhain, katso, he olivat kaikki kuolleina ruumiina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Silloin Sanherib, Assurin kuningas, lähti liikkeelle ja meni pois. Hän palasi maahansa ja jäi Niiniveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Mutta kerran kun hän oli rukoilemassa jumalansa Nisrokin temppelissä, surmasivat hänen poikansa Adrammelek ja Sareser hänet miekalla. Sitten he pakenivat Araratin maahan. Silloin hänen poikansa Eesarhaddon tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'Niihin aikoihin Hiskia sairastui ja oli kuolemaisillaan; ja profeetta Jesaja, Aamosin poika, tuli hänen luokseen ja sanoi hänelle: \"Näin sanoo Herra: Järjestä asiasi; sillä sinä kuolet etkä enää parane.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Hiskia käänsi kasvonsa seinään päin ja rukoili Herraa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'ja sanoi: \"Oi Herra, muista, kuinka olen vaeltanut edessäsi uskollisesti ja ehyellä sydämellä ja tehnyt sitä, mikä on hyvää silmissäsi!\" Ja Hiskia itki katkerasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Jesajalle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, '\"Mene ja sano Hiskialle: \'Näin sanoo Herra, sinun isäsi Daavidin Jumala: Olen kuullut rukouksesi ja nähnyt kyyneleesi. Katso, lisään päiviisi viisitoista vuotta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'ja pelastan sinut ja tämän kaupungin Assurin kuninkaan käsistä ja varjelen tämän kaupungin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Tämä on oleva sinulle merkkinä Herralta siitä, että Herra tekee, mitä on sanonut:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'katso, annan aurinkokellon varjon siirtyä takaisin kymmenen astetta, jotka se jo on auringon mukana laskeutunut Aahaan aurinkokellossa.\'\" Niin aurinko siirtyi aurinkokellossa takaisin kymmenen astetta, jotka se jo oli laskeutunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Hiskian, Juudan kuninkaan, kirjoittama laulu, kun hän oli ollut sairaana ja toipunut taudistaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, '\"Minä sanoin: Kesken rauhallisten päivieni minun on mentävä haudan porteista. Jäljellä olevat vuoteni on minulta riistetty pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Sanoin: En saa enää nähdä Herraa, Herraa elävien maassa, enkä enää katsella ihmisiä maailman asukkaiden joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Majani puretaan ja viedään minulta pois kuin paimenen teltta. Olen kutonut loppuun elämäni kuin kankuri kankaansa, minut leikataan irti loimilangoista. Ennen kuin päivä muuttuu yöksi, teet minusta lopun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Rauhoittelin itseäni aamuun asti – kuin leijona hän murskaa kaikki luuni. Ennen kuin päivä vaihtuu yöksi, teet minusta lopun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Kuin pääskynen, kuin kurki valitan, kujerran kuin kyyhkynen. Voipuen katsovat silmäni korkeuteen. Herra, minulla on ahdistus, puolusta minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Mitä nyt sanonkaan? Hän lupasi minulle ja täytti myös: vaellan hiljaisesti kaikki elämäni vuodet sieluni murheen tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Herra, tämänkaltaiset ovat elämäksi, ja niissä on koko henkeni elämä. Sinä teet minut terveeksi. Suo minun elää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Katso, onneksi muuttui minulle katkera murhe: sinä rakastit sieluani, nostit sen kadotuksen kuopasta, sillä sinä heitit kaikki syntini selkäsi taakse.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Sillä ei hauta sinua kiitä, ei kuolema sinua ylistä. Hautaan vaipuneet eivät pane toivoaan totuuteesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Elävät, elävät sinua kiittävät, kuten minä tänä päivänä. Isä ilmoittaa lapsilleen totuutesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Herra on auttajani. Lyyrani soittoja soittakaamme kaikkina elinpäivinämme Herran temppelissä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Jesaja käski tuoda viikunakakkua ja hautoa paisetta, että hän tulisi terveeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Hiskia sanoi: \"Mikä merkki tämä onkaan, että voin mennä Herran temppeliin!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Siihen aikaan Merodak-Baladan, Baladanin poika, Baabelin kuningas, lähetti kirjeen ja lahjoja Hiskialle, kun oli kuullut hänen olleen sairaana ja parantuneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Hiskia iloitsi lähettiläistä ja näytti heille varastohuoneen, hopean ja kullan, hajuaineet ja kalliin öljyn ja koko asehuoneensa ja kaikki, mitä hänen aarrekammioissaan oli. Hiskian talossa ei ollut mitään eikä koko hänen valtakunnassaan, mitä hän ei olisi heille näyttänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Mutta profeetta Jesaja tuli kuningas Hiskian luo ja sanoi hänelle: \"Mitä nämä miehet ovat sanoneet, ja mistä he ovat tulleet luoksesi?\" Hiskia vastasi: \"He ovat tulleet luokseni kaukaisesta maasta, Baabelista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Hän sanoi: \"Mitä he ovat nähneet talossasi?\" Hiskia vastasi: \"Kaiken, mitä talossani on, he ovat nähneet. Aarrekammiossani ei ole mitään, mitä en olisi näyttänyt heille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Jesaja sanoi Hiskialle: \"Kuule Herran Sebaotin sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Katso, päivät tulevat, jolloin kaikki, mitä talossasi on ja mitä isäsi ovat koonneet tähän päivään asti, viedään pois Baabeliin. Tänne ei jää mitään, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Omia poikiasi, jotka polveutuvat sinusta ja jotka sinulle syntyvät, viedään hovipalvelijoiksi Baabelin kuninkaan palatsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Hiskia sanoi Jesajalle: \" Herran sana, jonka olet puhunut, on hyvä.\" Sillä hän ajatteli: \"Onpahan rauha ja turvallisuus minun päivinäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, '\"Lohduttakaa, lohduttakaa kansaani\", sanoo Jumalanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, '\"Puhukaa suloisesti Jerusalemille ja julistakaa sille, että sen vaivanaika on päättynyt, että sen velka on sovitettu, sillä se on saanut Herran kädestä kaksinkertaisesti kaikista synneistään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Airuen ääni kuuluu: \"Valmistakaa Herralle tie erämaahan, tehkää arolle tasaiset polut Jumalallemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Kaikki laaksot korotettakoot, kaikki vuoret ja kukkulat alennettakoot. Kivikot tulkoot tasangoksi ja kalliolouhikot tasaiseksi maaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Herran kunnia ilmestyy: kaikki liha saa sen nähdä. Sillä Herran suu on puhunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Ääni sanoo: \"Julista!\" Toinen vastaa: \"Mitä minun tulee julistaa?\" Kaikki liha on kuin ruoho, ja kaikki sen kauneus kuin kedon kukkanen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'ruoho kuivuu, kukkanen lakastuu, kun Herran Henki puhaltaa siihen. Totisesti, ruohoa on kansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Ruoho kuivuu, kukkanen lakastuu, mutta Jumalamme sana pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Nouse korkealle vuorelle, Siion, sinä ilosanoman tuoja. Korota voimakkaasti äänesi, Jerusalem, sinä ilosanoman tuoja. Korota, älä pelkää, sano Juudan kaupungeille: \"Katso, teidän Jumalanne!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Katso, Herra Herra tulee voimallisena, hänen käsivartensa vallitsee. Katso, hänen palkkansa on hänen mukanaan, hänen työnsä ansio käy hänen edellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Niin kuin paimen hän kaitsee laumaansa. Hän kokoaa karitsat käsivarrelleen, kantaa niitä sylissään ja johdattaa imettäviä lampaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Kuka on kourallaan mitannut vedet ja vaaksalla määrännyt taivaitten mitat? Kuka on kolmannesmittaan mahduttanut maan tomun, puntarilla punninnut vuoret, vaa\'alla kukkulat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Kuka on Herran Henkeä ohjannut, ollut hänen neuvonantajansa ja opettajansa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Kenen kanssa hän on neuvotellut, joka olisi antanut hänelle ymmärrystä ja opettanut oikean polun, opettanut hänelle tiedon ja osoittanut hänelle ymmärryksen tien?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Katso, kansakunnat ovat kuin pisara vesisangon uurteessa. Ne ovat kuin tomuhiukkanen vaa\'assa. Katso, merensaaret hän nostaa kuin hiekanjyvän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Libanon ei riittäisi polttopuiksi eikä sen riista polttouhriksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Kaikki kansakunnat ovat kuin ei mitään hänen edessään. Ne ovat hänelle kuin olematon ja tyhjä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Keneen te siis vertaatte Jumalan, ja minkä muotoiseksi te hänet teette?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Jumalankuvanko? – Sen valaa valaja, ja kultaseppä päällystää sen kullalla, ja muotoilee sille hopeaketjut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Kellä ei ole varaa sellaiseen antiin, se valitsee puun, joka ei lahoa, hakee taitavan tekijän pystyttämään jumalankuvan, joka ei horju.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Ettekö tiedä, ettekö kuule, eikö teille ole alusta asti ilmoitettu, ettekö ole ottaneet vaarin maan perustuksista?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Hän istuu korkealla maanpiirin päällä, kuin heinäsirkkoja ovat sen asukkaat. Hän levittää taivaan kuin harson, pingottaa sen kuin teltan asuttavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'Hän tekee ruhtinaat olemattomiksi ja maan tuomarit tyhjän veroisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Tuskin heidät on istutettu, tuskin kylvetty, tuskin heidän vartensa on juurtunut maahan, hän puhaltaa heihin, ja he kuivettuvat. Myrsky vie heidät kuin oljenkorret.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, '\"Keneen siis vertaatte minut, jonka kaltainen olisin\", sanoo Pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Nostakaa silmänne korkeuteen ja katsokaa: kuka on nämä luonut? Hän, joka johdattaa esiin niiden joukot täysilukuisina, joka kutsuu ne kaikki nimeltä. Niin suuri on hänen mahtinsa ja vahva hänen voimansa, ettei yksikään jää häneltä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Miksi sinä, Jaakob, sanot ja sinä, Israel, puhut: \"Tieni on Herralta salassa, oikeuteni on joutunut pois Jumalani huomasta\"?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Etkö tiedä, etkö ole kuullut: Herra on iankaikkinen Jumala, joka on luonut maan ääret? Ei hän väsy eikä näänny, hänen ymmärryksensä on tutkimaton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Hän voimistaa voipuneen ja antaa voimattomalle voimaa yltäkyllin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Nuorukaiset väsyvät ja nääntyvät, nuoret miehet kompastuvat ja kaatuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'Mutta ne, jotka Herraa odottavat, saavat uuden voiman. He kohottavat siipensä kuin kotkat. He juoksevat eivätkä näänny, he vaeltavat eivätkä väsy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Vaietkaa edessäni, te merensaaret. Kansat uudistakoot voimansa, astukoot esiin ja puhukoot sitten. Käykäämme oikeutta keskenämme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Kuka herätti päivänkoiton maasta sen, jota vanhurskaus seuraa joka askeleella? Kuka antaa kansat hänen valtaansa, kukistaa kuninkaat hänen jalkoihinsa? Kuka muuttaa heidän miekkansa tomuksi, heidän jousensa lentäviksi oljenkorsiksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Hän ajaa heitä takaa, kulkee turvallisesti polkua, jota hänen jalkansa eivät ole ennen kulkeneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Kuka on tämän tehnyt ja saanut aikaan? Hän, joka alusta asti kutsuu sukupolvet esiin: minä, Herra, joka olen ensimmäinen ja viimeisten luona vielä sama.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Merensaaret näkivät sen ja pelästyivät, maan ääret vapisivat. He lähestyivät, he tulivat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'he auttoivat toinen toistaan ja sanoivat toisilleen: \"Ole luja!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Valaja rohkaisee kultaseppää, levyseppä alasimen iskijää. Hän sanoo juotoksesta: \"Se on hyvä\", ja vahvistaa sen nauloilla, niin ettei siihen jää väljyyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Mutta sinä, Israel, palvelijani, sinä Jaakob, jonka olen valinnut, Aabrahamin, ystäväni, siemen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'jonka olen ottanut maan ääristä ja kutsunut maan kaukaisimmilta periltä, jolle sanoin: \"Sinä olet palvelijani, sinut olen valinnut enkä pitänyt sinua halpana\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'älä pelkää, sillä minä olen kanssasi. Älä arkaile, sillä minä olen Jumalasi: vahvistan sinua, autan sinua, tuen sinua vanhurskauteni oikealla kädellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Katso, häpeän ja pilkan saavat kaikki, jotka palavat vihasta sinua vastaan. Tyhjiin raukeavat ja hukkuvat ne, jotka sinua vastaan riitelevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Hakemallakaan et löydä niitä, jotka sinua vastaan taistelivat. Tyhjiin raukeavat ja lopun saavat ne, jotka sotivat sinua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Sillä minä, Herra, Jumalasi, tartun oikeaan käteesi, sanon sinulle: \"Älä pelkää, minä autan sinua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Älä pelkää, Jaakob, sinä mato, sinä Israelin vähäinen väki. Minä autan sinua, sanoo Herra, lunastajasi, Israelin Pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Katso, panen sinut raastavaksi puimaäkeeksi, uudeksi, monihampaiseksi. Sinä puit ja rouhennat vuoret, muutat kukkulat akanoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Heität ne pois, tuuli vie ne ja myrsky hajottaa. Mutta sinä iloitset Herrassa ja Israelin Pyhä on kerskauksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Kurjat ja köyhät etsivät vettä, eikä sitä ole. Heidän kielensä kuivuu janosta. Mutta minä, Herra, kuulen heitä, minä, Israelin Jumala, en heitä hylkää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Puhkaisen purot korkeille kallioille ja lähteet laaksojen pohjiin. Muutan erämaan vesilammikoiksi ja hietikon hetteiköksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Kasvatan erämaahan setripuita, akasioita, myrttejä ja öljypuita. Istutan arolle yhdessä sypressejä, jalavia sekä puksipuita,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'jotta he näkisivät ja tietäisivät, huomaisivat ja myös ymmärtäisivät, että Herran käsi on tämän tehnyt, Israelin Pyhä on sen luonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Tuokaa esiin riita-asianne, sanoo Herra, esittäkää todisteenne, sanoo Jaakobin kuningas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Esittäkööt ja ilmoittakoot meille, mitä on tapahtuva. Ilmoittakaa entiset, mitä ne olivat, tutkiaksemme ja tietääksemme, mitä niistä on tullut, tai antakaa meidän kuulla tulevia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Ilmoittakaa, mitä vastedes tapahtuu, tietääksemme, oletteko te jumalia. Tehkää hyvää tai tehkää pahaa, me katselemme ja ihmettelemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Katso, te olette pelkkää tyhjää, ja tekonne ovat turhia. Kauhistus se, joka teidät valitsee!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Herätin pohjoisesta hänet, ja hän tuli, päivänkoitosta hänet, joka rukoilee nimeäni, ja hän tallaa käskynhaltijoita kuin lokaa, kuin savenvalaja sotkee savea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Kuka on sen alun pitäen ilmoittanut, että olisimme sen tienneet, ja edeltäpäin, että voisimme sanoa: \"Hän oli oikeassa\"? Ei kukaan sitä ilmoittanut, ei kukaan sitä kuuluttanut, ei kukaan kuullut teiltä sanaakaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Ensimmäisenä sanon Siionille: \"Katso, siinä ne ovat!\" ja annan Jerusalemille ilosanomantuojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Katselen ympärilleni, mutta ei ole ketään; ei kukaan näistä voi antaa neuvoa, että kysyisin heiltä ja he vastaisivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Katso, kaikki he ovat pelkkää petosta, turhat ovat heidän työnsä. Tuulta ja tyhjää ovat heidän valetut kuvansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Katso, palvelijani, jota tuen, valittuni, johon sieluni on mieltynyt. Olen pannut Henkeni hänen päälleen, hän tuo pakanoille oikeuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Hän ei huuda eikä korota ääntään eikä anna sen kuulua kaduilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Särjettyä ruokoa hän ei muserra, ja suitsevaa lampun sydäntä hän ei sammuta. Hän levittää oikeutta uskollisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Hän ei itse sammu eikä murru, kunnes on saattanut oikeuden maan päälle, ja merensaaret odottavat hänen opetustaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Näin sanoo Jumala, Herra, joka on luonut taivaan ja levittänyt sen, joka on tehnyt maan laveuden ja mitä siinä kasvaa, antanut henkäyksensä kansalle, joka siinä on, ja hengen niille, jotka siellä vaeltavat:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Minä, Herra, olen vanhurskaudessa kutsunut sinut, olen tarttunut käteesi, varjellut sinut ja pannut sinut kansoille liitoksi ja pakanoille valkeudeksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'avaamaan sokeat silmät, päästämään sidotut vankeudesta ja pimeydessä istuvat vankilasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Minä, Herra, se on minun nimeni, en anna kunniaani toiselle enkä ylistystäni epäjumalille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Katso, entiset ovat toteen käyneet, ja uusia minä ilmoitan. Ennen kuin ne puhkeavat taimelle, annan teidän ne kuulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Veisatkaa Herralle uusi virsi, veisatkaa hänen ylistystään maan ääristä, te merenkulkijat ja meri kaikkineen, te merensaaret ja niissä asuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Korottakoot äänensä erämaa ja sen kaupungit, kylät, joissa Keedar asuu. Riemuitkoot kallioilla asuvat, huutakoot ilosta vuorten huipuilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Antakoot Herralle kunnian ja julistakoot hänen ylistystään merensaarissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Herra lähtee sotaan kuin sankari, kuin soturi hän kiihottaa kiivautensa. Hän nostaa sotahuudon ja jyrisee, hän kukistaa vihollisensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Olen ollut vaiti ikiajoista asti, olen ollut hiljaa ja pidättänyt itseni. Mutta nyt huudan kuin lapsensynnyttäjä, puhallan ja vapisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Teen autioiksi vuoret ja kukkulat ja kuihdutan niiltä kaiken ruohon. Muutan virrat saariksi ja kuivaan vesilammikot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Johdatan sokeat tietä, jota he eivät tunne. Kuljetan heidät polkuja, joita he eivät tunne. Muutan pimeyden heidän edellään valkeudeksi ja kivikot tasangoksi. Nämä sanat teen enkä niitä tekemättä jätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Mutta ne perääntyvät ja joutuvat häpeään, jotka turvaavat veistettyyn kuvaan, jotka sanovat valetuille kuville: \"Te olette jumalamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Te kuurot, kuulkaa, ja te sokeat, katsokaa ja nähkää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Kuka on sokea, ellei palvelijani, ja kuka niin kuuro kuin sanansaattajani, jonka lähetän? Kuka on niin sokea kuin palkkalaiseni, niin sokea kuin Herran palvelija?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Paljon sinä olet nähnyt, mutta et ole ottanut siitä vaarin. Korvat avattiin, mutta hän ei kuule.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Herra on nähnyt hyväksi vanhurskautensa tähden tehdä lain suureksi ja ihanaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Mutta tämä on raastettu ja ryöstetty kansa, kaikki nuoret miehet ovat sidotut ja kätketyt vankiloihin. He ovat joutuneet saaliiksi, eikä ole auttajaa, ryöstetyiksi, eikä ole, kuka sanoisi: \"Palauta!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Kuka teistä ottaa tämän korviinsa, ottaa sen varteen ja kuulee vastaisen varalta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Kuka on antanut Jaakobin ryöstettäväksi ja Israelin riistäjien valtaan? Eikö Herra, jota vastaan olemme syntiä tehneet, jonka teitä he eivät tahtoneet vaeltaa ja jonka lakia he eivät totelleet?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Niin hän vuodatti Israelin päälle vihansa hehkun ja sodan ankaruuden. Se liekehti hänen ympärillään, mutta hän ei ollut tietävinään. Se poltti häntä, mutta hän ei siitä välittänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Mutta nyt, näin sanoo Herra, joka loi sinut, Jaakob, joka valmisti sinut, Israel: Älä pelkää, sillä olen lunastanut sinut, olen kutsunut sinut nimeltä. Sinä olet minun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Kun kuljet vetten yli, minä olen kanssasi, jos virtojen yli, ne eivät sinua upota. Jos kuljet tulessa, et pala, eikä liekki sinua polta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Sillä minä olen Herra, Jumalasi, Israelin Pyhä, vapahtajasi. Annan lunnaiksesi Egyptin, sinun sijastasi Kuusin ja Seban.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Koska olet silmissäni kallis ja suuriarvoinen ja koska minä sinua rakastan, minä annan ihmisiä sijastasi ja kansakuntia hengestäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Älä pelkää, sillä minä olen kanssasi. Tuon siemenesi päivänkoiton ääriltä, päivän laskusta kokoan sinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Sanon pohjoiselle: Anna tänne! ja etelälle: Älä pidätä! Tuo poikani kaukaa ja tyttäreni maan ääristä –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'kaikki, jotka on otettu nimiini ja jotka olen kunniakseni luonut, jotka olen valmistanut ja tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Tuo esiin sokea kansa, jolla kuitenkin on silmät, ja kuurot, joilla kuitenkin on korvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Kaikki kansat ovat kokoontuneet yhteen ja kansakunnat tulleet kokoon. Kuka heistä voi ilmoittaa tällaista? Tai antakoot meidän kuulla entisiä. Asettakoot todistajansa ja näyttäkööt, että ovat oikeassa. Sittenpä kuullaan ja sanotaan: se on totuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Te olette todistajani, sanoo Herra, palvelijani, jonka olen valinnut, jotta tuntisitte minut ja uskoisitte minuun ja ymmärtäisitte, että minä se olen. Ennen minua ei ole tehty yhtään jumalaa, eikä minun jälkeeni tule toista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Minä, minä olen Herra, eikä ole muuta pelastajaa kuin minä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Minä olen ilmoittanut, olen pelastanut ja julistanut, eikä ollut vierasta jumalaa teidän keskuudessanne. Te olette todistajani, sanoo Herra, ja minä olen Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Tästedeskin minä olen sama. Kukaan ei voi vapauttaa kädestäni. Kuka peruuttaa sen, minkä teen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Näin sanoo Herra, lunastajanne, Israelin Pyhä: Teidän tähtenne lähetän sanan Baabeliin, syöksen heidät kaikki pakoon, syöksen kaldealaiset laivoihin, jotka olivat heidän ilonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Minä, Herra, olen Pyhänne, minä, Israelin Luoja, olen kuninkaanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Näin sanoo Herra, joka teki tien mereen ja polun valtaviin vesiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'joka vei sotaan vaunut ja hevoset, sotaväen ja kaikki sankarit. He makasivat maassa eivätkä nousseet, he raukesivat ja sammuivat kuin lampun sydän:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Älkää entisiä muistelko, älkää menneistä välittäkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Katso, teen uutta. Nyt se versoo, ettekö sitä huomaa? Teen tien autiomaahan, virrat erämaahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Minua kunnioittavat aron eläimet, sakaalit ja strutsit, koska annan vedet autiomaahan ja virrat erämaahan antaakseni kansani, valittuni, juoda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Kansa, jonka olen itselleni valmistanut, on julistava kiitostani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Mutta et sinä, Jaakob, ole minua kutsunut, et sinä, Israel, ole itseäsi minun tähteni vaivannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Et ole tuonut minulle lampaitasi polttouhriksi, et teurasuhreillasi minua kunnioittanut. En ole pannut sinua palvelemaan itseäni ruokauhrilla enkä vaivannut suitsutusuhrilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Et ole ostanut minulle kalmoruokoa hopealla etkä minua teurasuhriesi rasvalla ravinnut – et, vaan olet minua synneilläsi vaivannut ja rasittanut minua pahoilla teoillasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Minä, minä pyyhin pois rikoksesi itseni tähden enkä syntejäsi muista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Muistuta minua, käykäämme oikeutta keskenämme. Puhu sinä ja näytä, että olet oikeassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Esi-isäsi teki syntiä, välittäjäsi luopuivat minusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Häpäisin pyhät ruhtinaat, jätin Jaakobin tuhon omaksi, Israelin alttiiksi pilkalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Mutta nyt kuule, Jaakob, palvelijani, ja Israel, jonka olen valinnut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Näin sanoo Herra, Luojasi, joka on valmistanut sinut hamasta äidin kohdusta, joka sinua auttaa: Älä pelkää, palvelijani Jaakob, sinä Jesurun, jonka olen valinnut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Sillä vuodatan vedet janoisen päälle ja virrat kuivan maan päälle. Vuodatan Henkeni siemenesi päälle ja siunaukseni vesojesi päälle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'niin että ne kasvavat nurmikolla kuin pajut vesipurojen reunalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Kuka sanoo: \"Minä olen Herran oma\", kuka nimittää itsensä Jaakobin nimellä, kuka kirjoittaa käteensä: \" Herran oma\", ja ottaa Israelin kunnianimekseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Näin sanoo Herra, Israelin kuningas, ja sen lunastaja, Herra Sebaot: Minä olen ensimmäinen, ja minä olen viimeinen, eikä ole muuta Jumalaa kuin minä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Kuka on kaltaiseni? Hän julistakoon ja ilmoittakoon ja osoittakoon sen minulle, siitä alkaen kun perustin ikiaikojen kansan. He ilmoittakoot tulevat, ja mitä on tapahtuva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Älkää vavisko älkääkä pelätkö. Enkö minä aikoja sitten antanut sinun kuulla ja sinulle ilmoittanut, ja te olette minun todistajani: Onko muuta Jumalaa kuin minä? Ei ole muuta pelastuskalliota, minä en ketään tunne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Jumalankuvien tekijät ovat turhia kaikki tyynni, eivätkä nuo heidän rakkaansa auta mitään. Niiden todistajat eivät näe eivätkä tiedä mitään, ja niin he joutuvat häpeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Kuka tahansa muovatkoon jumalan ja valakoon kuvan. Se ei auta yhtään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Katso, kaikki sen seuraajat joutuvat häpeään, ja sen tekijät ovat vain ihmisiä. Tulkoot kokoon kaikki ja astukoot esiin: vaviskoot ja hävetkööt!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Rautaseppä ottaa työkalun, työskentelee hiilten hehkussa, muovailee kuvaa vasaralla ja takoo sitä käsivartensa voimalla. Hänen tulee nälkä, ja voima menee, hän ei saa vettä juodakseen, ja hän nääntyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Puuseppä jännittää mittanuoran, kaavailee piirtimellä, vuolee kovertimilla, mittailee harpilla ja tekee miehen kuvan inhimillisen kauneuden mukaan huoneeseen asumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Hän hakkaa itselleen setripuita, hän ottaa rautatammen ja tammen ja kasvattaa ne itselleen vahvoiksi metsän puiden seassa, istuttaa setrin, ja sade kasvattaa sen suureksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Se on ihmisillä polttopuuna. Hän ottaa sitä lämmitelläkseen, sytyttää uunin ja paistaa leipää, vieläpä veistää siitä jumalan ja kumartaa sitä, tekee siitä jumalankuvan ja lankeaa maahan sen eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Osan siitä hän polttaa tulessa, toisen osan vierellä hän syö lihaa, paistaa paistin ja tulee ravituksi. Hän myös lämmittelee itseään ja sanoo: \"Hyvä, minun on lämmin, näen liekin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Hän tekee lopusta jumalan, jumalankuvan, jonka eteen hän lankeaa maahan, jota hän kumartaa ja rukoilee sanoen: \"Pelasta minut, sillä sinä olet jumalani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'He eivät tajua eivätkä ymmärrä mitään, sillä heidän silmänsä ovat suljetut, niin etteivät he näe, ja heidän sydämensä on suljettu, niin etteivät he käsitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Heidän mieleensä ei tule, heillä ei ole järkeä eikä ymmärrystä, että sanoisivat: \"Osan siitä olen polttanut tulessa, olen paistanut sen hiilillä leipää, paistanut lihaa ja syönyt. Tekisinkö tähteestä kauhistuksen ja lankeaisinko maahan puupölkyn eteen!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Sen, joka riippuu kiinni tuhkassa, petetty sydän on vienyt harhaan. Hän ei pelasta sieluaan eikä sano: \"Eikö se, mikä on oikeassa kädessäni, ole petosta?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Muista tämä, Jaakob, ja sinä, Israel, sillä sinä olet palvelijani. Olen sinut valmistanut, sinä olet palvelijani. En unohda sinua, Israel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Pyyhin pois rikoksesi kuin pilven ja syntisi kuin sumun. Palaa luokseni, sillä lunastan sinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Iloitkaa, te taivaat, sillä Herra sen tekee. Riemuitkaa, te maan syvyydet. Puhjetkaa riemuun, te vuoret, sekä metsä ja kaikki sen puut. Sillä Herra lunastaa Jaakobin ja kirkastaa itsensä Israelissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Näin sanoo Herra, lunastajasi, joka on valmistanut sinut hamasta äidin kohdusta: Minä olen Herra, joka teen kaiken, joka yksin jännitin taivaan ja levitin maan – kuka oli kanssani? –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'joka teen tyhjäksi valehtelijoiden merkit ja teen taikurit tyhmiksi, joka panen tietäjät peräytymään ja muutan heidän tietonsa typeryydeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'Mutta palvelijani sanan minä toteutan ja saatan täyttymään sanansaattajieni neuvon. Olen se, joka sanon Jerusalemille: \"Sinussa asuttakoon!\" ja Juudan kaupungeille: \"Teidät rakennettakoon!\" Kohotan sen rauniot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Olen se, joka sanon syvyydelle: \"Kuivu; minä kuivaan sinun virtasi!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'joka sanon Koorekselle: \"Paimeneni!\" Hän täyttää kaiken tahtoni ja sanoo Jerusalemille: \"Sinut rakennettakoon!\" ja temppelille: \"Sinut perustettakoon!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Näin sanoo Herra voidellulleen Koorekselle, jonka oikeaan käteen olen tarttunut kukistaakseni kansat hänen edestään ja riisuakseni kuninkaitten vyötäisiltä vyöt, jotta ovet hänen edessään avautuisivat eivätkä portit sulkeutuisi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Minä käyn edelläsi ja tasoitan kukkulat, murran vaskiovet ja rikon rautasalvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'Annan sinulle aarteet pimeän peitosta, kalleudet niiden kätköistä tietääksesi, että minä, Herra, olen se, joka olen kutsunut sinut nimeltä, minä, Israelin Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Palvelijani Jaakobin ja valittuni Israelin tähden olen kutsunut sinut nimeltä ja antanut sinulle kunnianimen, vaikka et minua tuntenut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Minä olen Herra, eikä toista ole, minun lisäkseni ei ole yhtään Jumalaa. Vyötän sinut, vaikka et minua tunne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'jotta tiedettäisiin auringon noususta sen laskuun asti, että minun lisäkseni ei ole yhtään: minä olen Herra, eikä toista ole,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'minä, joka teen valkeuden ja luon pimeyden, joka tuotan onnen ja luon onnettomuuden; minä, Herra, teen kaiken tämän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Tihkukaa, te taivaat, ylhäältä, vuotakoot pilvet vanhurskautta. Avautukoon maa ja antakoon hedelmänään pelastuksen, versokoon se myös vanhurskautta. Minä, Herra, olen sen luonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Voi sitä, joka riitelee tekijänsä kanssa, saviastia saviastioiden joukossa – maasta tehtyjä kaikki! Sanooko savi valajalleen: \"Mitä teet? Työsi on kädettömän työtä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Voi sitä, joka sanoo isälleen: \"Mitä olet siittänyt?\" ja äidilleen: \"Mitä olet synnyttänyt?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Näin sanoo Herra, Israelin Pyhä, joka on hänet tehnyt: Kysykää tulevia minulta ja jättäkää minun haltuuni lapseni, kätteni teot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Minä olen tehnyt maan ja luonut ihmisen maan päälle; käteni ovat levittäneet taivaan, minä olen kutsunut koolle kaikki sen joukot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Minä herätin hänet vanhurskaudessa, ja minä tasoitin kaikki hänen tiensä. Hän rakentaa kaupunkini ja päästää vapaiksi karkotettuni ilman maksua ja ilman lahjusta, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Näin sanoo Herra: Egyptin työn tulos ja Kuusin kauppavoitto ja sebalaiset, kookkaat miehet, tulevat luoksesi, tulevat omiksesi. Sinun perässäsi he käyvät, kulkevat kahleissa, sinua kumartavat, sinua rukoilevat: \"Ainoastaan sinun luonasi on Jumala, ei ole toista, ei yhtään muuta jumalaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Totisesti, sinä olet salattu Jumala, sinä Israelin Jumala, sinä Vapahtaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Häpeän ja pilkan he saavat kaikki, pilkan alaisina he kulkevat kaikki, nuo kuvien tekijät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Mutta Israelin pelastaa Herra iankaikkisella pelastuksella. Ette joudu häpeään ettekä pilkan alaisiksi, ette ikinä, ette ikuisuuteen saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Sillä näin sanoo Herra, joka on luonut taivaan – hän on Jumala – joka on valmistanut maan ja tehnyt sen ja on sen vahvistanut. Hän ei luonut sitä autioksi, asuttavaksi hän sen valmisti. Minä olen Herra, eikä toista ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'En ole puhunut salassa, en pimeässä maan paikassa. En ole sanonut Jaakobin jälkeläisille: etsikää minua tyhjyydestä. Minä Herra puhun vanhurskautta, ilmoitan, mikä on oikein.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Kokoontukaa ja tulkaa, lähestykää kaikki, te kansakunnista pelastuneet. Eivät ne mitään ymmärrä, jotka kantavat puisia kuviaan ja rukoilevat jumalaa, joka ei voi auttaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Ilmoittakaa ja tuokaa esiin – neuvotelkoot keskenään – kuka on tämän julistanut hamasta muinaisuudesta, aikoja sitten ilmoittanut? Enkö minä, Herra! Minun lisäkseni ei ole yhtään Jumalaa; ei ole vanhurskasta ja pelastavaa Jumalaa muuta kuin minä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Kääntykää minun luokseni ja tulkaa osallisiksi pelastuksesta, te maan ääret kaikki, sillä minä olen Jumala, eikä toista ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Olen vannonut itseni kautta, suustani on lähtenyt totuus, peruuttamaton sana: Minun edessäni pitää kaikkien polvien notkistua, minulle jokaisen kielen tulee vannoa valansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Ainoastaan Herrassa – niin tulee minusta sanoa – on vanhurskaus ja voima. Hänen luokseen tulevat häveten kaikki, jotka ovat palaneet vihasta häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'Herrassa tulee vanhurskaaksi kaikki Israelin siemen, ja hän on heidän kerskauksensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Beel sortuu, Nebo taipuu. Niiden kuvat joutuvat eläinten ja juhtien selkään. Se, mitä te kulkueessa kannoitte, sälytetään kuormaksi uupuville.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Ne taipuvat, ne sortuvat molemmat. Ne eivät voi pelastaa kuormaa, ja itsekin ne vaeltavat vankeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Kuulkaa minua, te Jaakobin heimo, kaikki te Israelin heimon tähteet, te, joita on pitänyt kantaa äidinkohdusta asti, nostaa hamasta äidinhelmasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Vanhuuteenne asti minä olen sama, aina harmaantumiseenne saakka minä kannan. Niin minä olen tehnyt, ja vastedeskin minä nostan, minä kannan ja pelastan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Keneen te vertaatte minut, kenen rinnalle te asetatte minut, kenen kaltaisena te minua pidätte, että olisimme toistemme vertaisia?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'He kaatavat kultaa kukkarosta ja punnitsevat hopeaa vaa\'alla. He palkkaavat kultasepän, ja hän tekee siitä jumalan, jonka eteen he lankeavat maahan ja jota he kumartavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'He nostavat sen olalleen, kantavat sitä ja asettavat sen paikoilleen, ja se seisoo eikä liikahda paikaltaan. Sitä huudetaan avuksi, mutta se ei vastaa eikä pelasta hädästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Muistakaa tämä ja olkaa lujat. Menkää itseenne, te luopiot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Muistakaa ennen tapahtuneita ikiajoista asti, sillä minä olen Jumala, eikä toista ole. Minä olen Jumala, eikä ole minun vertaistani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Ilmoitan alusta asti, mitä on tuleva, paljon ennen kuin se on vielä tapahtunut. Sanon: neuvoni pysyy, kaiken, mitä tahdon, minä teen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Olen kutsunut kotkan päivänkoitosta, kaukaisesta maasta päätökseni toimeenpanijan. Minkä olen puhunut, sen myös toteutan. Sen, mitä olen ajatellut, myös teen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Kuulkaa minua, te kovasydämiset, jotka olette kaukana vanhurskaudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Olen antanut vanhurskauteni lähestyä, se ei ole kaukana. Pelastus, jonka tuon, ei viivy. Annan Siioniin pelastuksen, annan kirkkauteni Israelille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Astu alas ja istu tomuun, sinä neitsyt, tytär Baabel, istu maahan, valtaistuinta vailla, sinä Kaldean tytär. Sillä sinua ei sanota enää hienoksi ja kauniiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Tartu käsikiviin ja jauha jauhoja, riisu huntusi, nosta helmasi, paljasta sääresi, kahlaa jokien poikki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Häpysi paljastuu, häpeäsi näkyy. Minä kostan enkä armahda ainoatakaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Lunastajamme nimi on Herra Sebaot, Israelin Pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Istu vaieten ja väisty pimeään, sinä Kaldean tytär. Sillä sinua ei enää kutsuta valtakuntien valtiattareksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Vihastuin kansaani, annoin häväistä perintöni ja annoin heidät käsiisi. Et osoittanut heille sääliä, vanhuksellekin teit ikeesi hyvin raskaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'Silloin sanoit: \"Ikuisesti olen valtiaasi\", niin ettet näitä mieleesi pannut etkä loppua ajatellut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Mutta nyt kuule tämä, sinä hekumoitsija, joka istut turvallisena, joka sanot sydämessäsi: \"Minä, eikä kukaan muu! En ole leskenä istuva enkä lapsettomuudesta tietävä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Mutta nämä molemmat tulevat osaksesi äkkiä, yhtenä päivänä: lapsettomuus ja leskeys. Ne kohtaavat sinua täysimääräisinä huolimatta velhouksiesi paljoudesta ja loitsujesi suuresta voimasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Luotit pahuuteesi ja sanoit: \"Ei kukaan minua näe.\" Viisautesi ja tietosi eksyttivät sinut, ja sanoit sydämessäsi: \"Minä, eikä kukaan muu!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Sen tähden kohtaa sinua onnettomuus, etkä tiedä, milloin se tulee. Sinut yllättää tuho, josta et selviä lunnailla, sinut kohtaa äkkiä perikato, aavistamattasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Astu esiin loitsuinesi ja paljoine velhouksinesi, joilla olet vaivannut itseäsi nuoruudestasi asti: ehkä hyvinkin saat avun, ehkä herätät pelkoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Sinä olet väsyttänyt itsesi paljolla neuvottelemisellasi. Astukoot esiin ja auttakoot sinua taivaan mittaajat, tähtien tähystäjät, jotka kuu kuulta ilmoittavat, mitä sinulle on tapahtuva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Katso, he ovat kuin kuivat korret: tuli polttaa heidät. He eivät pelasta henkeään liekin vallasta. Se ei ole hiillos, jolla he lämmittelisivät eikä tuli, jonka ääressä istutaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Tämän saat sinä niistä, joista olet vaivaa nähnyt: He ovat niitä, joiden kanssa olet kauppaa käynyt nuoruudestasi asti. He harhailevat kukin taholleen, eikä kukaan sinua pelasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Kuulkaa tämä, Jaakobin heimo, te, joista käytetään nimeä Israel ja jotka olette lähteneet Juudan lähteestä, jotka vannotte Herran nimeen ja tunnustatte Israelin Jumalan, mutta ette totuudessa ettekä vanhurskaudessa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, '– sillä he saavat nimensä pyhän kaupungin mukaan ja he pitävät tukenaan Israelin Jumalaa, jonka nimi on Herra Sebaot:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Entiset olen jo ajat sitten ilmoittanut, ne ovat lähteneet suustani, ja olen ne kuuluttanut. Äkkiä panin ne täytäntöön, ja ne tapahtuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Koska tiesin, että sinä olet paatunut, että niskajänteesi on rautaa ja otsasi vaskea,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'niin ilmoitin ne sinulle jo ajat sitten, kuulutin ne sinulle, ennen kuin ne tapahtuivat, ettet sanoisi: \"Epäjumalankuvani on ne tehnyt, veistetty kuvani ja valettu kuvani on niin säätänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Olet ne kuullut, katso nyt kaikkea: ettekö sitä tunnusta? Tästä lähtien kuulutan sinulle uusia, salattuja asioita, joita et ole tiennyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Ne on luotu nyt eikä aikoja sitten, ennen tätä päivää et ole kuullut niistä, ettet sanoisi: \"Katso, olen ne tietänyt!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Et ole niistä kuullut etkä niistä tietänyt, eikä korvasi ole niille aikaisemmin auennut. Sillä tiesin, että olet aivan uskoton ja luopioksi sanottu jo äidin kohdusta asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Oman nimeni tähden olen kärsivällinen, ylistykseni tähden hillitsen vihani, etten sinua tuhoaisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Katso, olen sulattanut sinua hopeaa saamatta, olen sinua koetellut kärsimyksen pätsissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Itseni, itseni tähden sen teen. Sillä kuinka onkaan nimeäni häväisty! Mutta en anna kunniaani toiselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Kuule minua, Jaakob, ja sinä, Israel, jonka olen kutsunut: Minä olen aina sama, minä olen ensimmäinen, minä olen myös viimeinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Käteni on perustanut maan, oikea käteni on levittänyt taivaan. Minä kutsun ne, ja siinä ne ovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Kokoontukaa kaikki ja kuulkaa – kuka noista muista on ilmoittanut tämän: että se, jota Herra rakastaa, tekee hänen tahtonsa Baabelia vastaan ja on hänen käsivartenaan kaldealaisia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Minä, minä olen puhunut, minä olen hänet kutsunut, olen hänet tuonut, ja hän on menestynyt teillään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Lähestykää minua, kuulkaa tämä: Alkujaankaan en ole puhunut salassa. Kun nämä tapahtuivat, minä olin jo siellä. Mutta nyt Herra Herra on lähettänyt minut sekä oman Henkensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Näin sanoo Herra, lunastajasi, Israelin Pyhä: Minä olen Herra, Jumalasi, joka opetan sinulle, mikä on hyödyllistä, johdatan sinut sitä tietä, jota sinun tulee kulkea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'Jospa ottaisit käskyistäni vaarin, rauhasi olisi kuin virta ja vanhurskautesi kuin meren aallot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'Lastesi paljous olisi kuin hiekka, kohtusi hedelmä kuin hiekan jyvät. Sen nimi ei häviäisi eikä katoaisi kasvojeni edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Lähtekää Baabelista, paetkaa Kaldeasta; riemuhuudoin ilmoittakaa, kuuluttakaa tämä, viekää tieto siitä maan ääriin asti, sanokaa: \" Herra on lunastanut palvelijansa Jaakobin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'He eivät kärsineet janoa, kun hän kuljetti heitä erämaiden halki. Hän vuodatti heille vettä kalliosta ja halkaisi kallion, ja vettä virtasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Jumalattomilla ei ole rauhaa, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Kuulkaa minua, te merensaaret, ja ottakaa tästä vaarin, te, kaukaiset kansat. Herra on kutsunut minut jo äidinkohdusta asti, jo äitini helmasta hän on maininnut nimeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Hän teki suuni terävän miekan kaltaiseksi ja kätki minut kätensä varjoon. Hän teki minut hiotuksi nuoleksi ja talletti minut viineensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'Hän sanoi minulle: \"Sinä olet palvelijani, sinä Israel, jossa osoitan kirkkauteni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Mutta minä sanoin: \"Suotta olen itseäni vaivannut, kuluttanut voimani turhaan ja tyhjään. Kuitenkin oikeuteni on Herran huomassa, palkkani on Jumalan luona.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Mutta nyt sanoo Herra, joka on valmistanut minut palvelijakseen jo äitini kohdusta palauttamaan Jaakobin luokseen, niin että Israel koottaisiin hänen omakseen. Olen kallis Herran silmissä, ja Jumalani on voimani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'Hän sanoo: Sinulle, joka olet palvelijani, on liian vähäistä kohottaa ennalleen Jaakobin sukukunnat ja tuoda takaisin Israelin säilyneet: panen sinut pakanoille valkeudeksi, että minulta tulisi pelastus maan ääriin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Näin sanoo Herra, Israelin lunastaja, hänen Pyhänsä, syvästi halveksitulle, kansan inhoamalle, valtiaitten orjalle: Kuninkaat näkevät sen ja nousevat seisomaan, ruhtinaat näkevät ja kumartuvat maahan Herran tähden, joka on uskollinen, Israelin Pyhän tähden, joka on sinut valinnut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Näin sanoo Herra: Otollisella ajalla olen sinua kuullut ja pelastuksen päivänä sinua auttanut. Olen valmistanut sinut ja pannut sinut kansoille liitoksi kohottamaan ennalleen maan, jakamaan hävitetyt perintöosat ja');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'sanomaan vangituille: \"Käykää ulos!\" ja pimeässä oleville: \"Tulkaa esiin!\" Teiden varsilta he löytävät laitumen, kaikki kalliokukkulat ovat heillä laitumina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Heidän ei tule nälkä eikä jano, heihin ei satu hietikon helle eikä aurinko, sillä heidän armahtajansa johdattaa heitä ja vie heidät vesilähteille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Teen kaikki vuoreni teiksi, ja valtatieni kulkevat korkealla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Katso heitä, he tulevat kaukaa! Katso, nuo pohjoisesta, nuo lännestä, nuo Siinimin maalta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Riemuitkaa, te taivaat, iloitse, sinä maa, puhjetkaa riemuun, te vuoret, sillä Herra lohduttaa kansaansa ja armahtaa kurjiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Mutta Siion sanoo: \" Herra on minut hylännyt, Herra on minut unohtanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Unohtaako vaimo rintalapsensa, niin ettei hän armahda kohtunsa poikaa? Mutta vaikka he unohtaisivat, minä en sinua unohda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Katso, käsiini olen sinut piirtänyt, muurisi ovat aina edessäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Lapsesi tulevat rientäen, mutta hävittäjäsi ja raunioittajasi menevät pois luotasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Nosta silmäsi ja katso ympärillesi: he kokoontuvat, he tulevat kaikki luoksesi. Niin totta kuin minä elän, sanoo Herra, sinä puet heidät kaikki yllesi kuin korun ja sidot heidät vyöllesi kuin morsian vyönsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Sillä sinä – sinun rauniosi ja autiot paikkasi, sinun hävitetty maasi – sinä käyt silloin ahtaaksi asukkaille, ja kaukana ovat ne, jotka sinua söivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Vielä saavat lapsettomuutesi lapset sanoa korviesi kuullen: \"Paikka on minulle ahdas, tee tilaa, että voin asua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Silloin sanot sydämessäsi: \"Kuka on nämä minulle synnyttänyt? Olin lapseton ja hedelmätön, karkotettu ja hylätty. Kuka on heidät kasvattanut? Katso, minut oli jätetty yksin. Missä nämä silloin olivat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Näin sanoo Herra, Herra: Katso, nostan käteni kansakuntien puoleen, kohotan lippuni kansoja kohti, niin he tuovat poikasi sylissään ja kantavat tyttäresi olkapäillään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Kuninkaista tulee sinulle lastenhoitajia, heidän ruhtinattaristaan sinulle imettäjiä. Edessäsi he kumartuvat maahan kasvoilleen ja nuolevat tomun jaloistasi. Tiedät, että minä olen Herra ja että ne, jotka minua odottavat, eivät joudu häpeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Otetaanko sankarilta saalis, tai riistetäänkö vangit vanhurskaalta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Sillä näin sanoo Herra: Vaikka vangit otettaisiinkin sankarilta ja saalis riistettäisiin väkevältä, niin kuitenkin minä taistelen sitä vastaan, joka sinua vastaan taistelee, ja minä pelastan lapsesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Panen sortajasi syömään omaa lihaansa, ja he juopuvat omasta verestään kuin rypälemehusta. Silloin kaikki liha on tietävä, että minä, Herra, olen pelastajasi, että Jaakobin Väkevä on lunastajasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Näin sanoo Herra: Missä on äitinne erokirja, jolla olisin lähettänyt hänet pois? Tai kuka on velkojani, jolle olisin teidät myynyt? Katso, pahojen tekojenne tähden teidät on myyty, rikostenne tähden äitinne on lähetetty pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Miksi ei ollut ketään, kun saavuin, miksi kukaan ei vastannut, kun kutsuin? Onko käteni liian lyhyt vapahtamaan, olenko voimaton auttamaan? Katso, nuhtelullani kuivaan meren ja teen virrat erämaaksi, niin että niiden kalat mätänevät. Kun ei ole vettä, ne kuolevat janoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Puetan taivaat mustiin ja panen murhepuvun niiden verhoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Herra, Herra on antanut minulle opetuslasten kielen, niin että voin sanalla virvoittaa väsynyttä. Hän herättää aamu aamulta, herättää korvani kuulemaan opetuslasten tavoin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Herra, Herra on avannut korvani, en ole niskoitellut enkä vetäytynyt pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Selkäni annoin lyötäväksi ja poskieni parran revittäväksi, enkä peittänyt kasvojani pilkalta enkä syljeltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Herra, Herra auttaa minua. Sen tähden pilkka ei koskenut minuun. Siksi tein kasvoni koviksi kuin piikivi, sillä tiedän, etten joudu häpeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Lähellä on se, joka minut vanhurskaaksi tuomitsee. Kuka voi minua vastaan nostaa riita-asian? Astukaamme yhdessä esiin! Kuka on vastapuoleni? Tulkoon tänne lähelleni!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Katso, Herra, Herra auttaa minua. Kuka tuomitsee minut syylliseksi? Katso, kaikki he hajoavat kuin vaate. Koi heidät syö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Kuka teistä pelkää Herraa ja kuulee hänen palvelijansa ääntä? Se, joka vaeltaa pimeydessä ja valoa vailla, luottakoon Herran nimeen ja turvautukoon Jumalaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Mutta katso, te kaikki, jotka palon sytytätte, te palavilla nuolilla varustetut, suistukaa oman tulenne liekkeihin, niihin palaviin nuoliin, jotka olette sytyttäneet. Kädestäni tämä teille tulee: vaivassa te tulette asumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Kuulkaa minua, te jotka tavoittelette vanhurskautta, te jotka etsitte Herraa. Katsokaa kalliota, josta teidät on lohkaistu, ja kaivosonkaloa, josta teidät on kaivettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Katsokaa Aabrahamia, isäänne, ja Saaraa, joka teidät synnytti. Sillä Aabraham oli vain yksi, kun hänet kutsuin; mutta siunasin hänet ja enensin hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Sillä Herra lohduttaa Siionin, lohduttaa kaikki sen rauniot, hän tekee sen erämaasta kuin Eedenin ja sen arosta kuin Herran puutarhan. Siellä on oleva riemu ja ilo, kiitos ja ylistysvirren ääni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Kuuntele minua, kansani, kuule minua, kansakuntani, sillä minusta lähtee laki, ja minä panen oikeuteni valkeudeksi kansoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Lähellä on vanhurskauteni, autuuteni ilmestyy, käsivarteni tuomitsevat kansat. Minua odottavat merensaaret ja ne panevat toivonsa käsivarteeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Nostakaa silmänne taivasta kohti ja katsokaa maata, joka on alhaalla, sillä taivaat katoavat kuin savu ja maa hajoaa kuin vaate ja sen asukkaat kuolevat kuin sääsket, mutta autuuteni pysyy iankaikkisesti, eikä vanhurskauteni kukistu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Kuulkaa minua, te jotka vanhurskauden tunnette, kansa, jonka sydämessä on lakini: älkää pelätkö ihmisten pilkkaa älkääkä kauhistuko heidän herjauksiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Sillä koi syö heidät kuin vaatteen, koiperhonen syö heidät kuin villan, mutta vanhurskauteni pysyy iankaikkisesti ja autuuteni polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Nouse, nouse, pukeudu voimaan, sinä Herran käsivarsi. Nouse kuin muinaisina päivinä, menneiden sukupolvien aikoina. Etkö ole se, joka löit Rahabin kuoliaaksi, joka lävistit lohikäärmeen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Etkö sinä ole se, joka kuivasit meren, suuren syvyyden vedet, joka teit meren syvänteet tieksi lunastettujen kulkea?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Herran vapahdetut palaavat ja tulevat Siioniin riemuiten, päänsä päällä iankaikkinen ilo. Riemu ja ilo saavuttavat heidät, mutta murhe ja huokaus pakenevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Minä, minä olen teidän lohduttajanne. Mikä olet sinä, että pelkäät ihmistä, joka on kuolevainen, ihmislasta, jonka käy kuin ruohon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'ja unohdat Herran, joka on sinut tehnyt, joka on levittänyt taivaan ja perustanut maan, ja vapiset alati kaiket päivät sortajan vihaa, kun hän tähtää tuhotakseen? Mutta missä on sortajan viha?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Pian päästetään kumaraan koukistunut vapaaksi kahleistaan. Hän ei kuole, ei jää kuoppaan eikä häneltä puutu leipää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Minä olen Herra, Jumalasi, joka liikutan meren, niin että sen aallot pauhaavat, jonka nimi on Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Olen pannut sanani suuhusi. Olen kätkenyt sinut käteni varjoon pystyttääkseni taivaan ja perustaakseni maan ja sanoakseni Siionille: \"Sinä olet kansani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Nouse, nouse, lähde liikkeelle, Jerusalem, sinä joka olet juonut Herran kädestä hänen vihansa maljan, joka olet juonut päihdyttävän pikarin ja tyhjentänyt sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Ei kukaan kaikista lapsista, jotka hän oli synnyttänyt, ollut häntä taluttamassa. Ei kukaan kaikista lapsista, jotka hän oli kasvattanut, tarttunut hänen käteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Nämä kohtasivat sinua kaksittain – kuka sinua säälii? – tuho ja turmio, nälkä ja miekka. Millä voin sinua lohduttaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Poikasi makasivat tajuttomina joka kadun kulmassa, kuin antiloopit pyydyskuopassa, täynnä Herran vihaa, Jumalasi nuhtelua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Sen tähden kuule tätä, sinä kurja, joka olet juopunut, vaikka et viinistä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Näin sanoo Herrasi, Herra Jumalasi, joka ajaa kansansa asian: Katso, otan kädestäsi päihdyttävän maljan, vihani pikarin. Sinun ei tarvitse enää siitä juoda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Panen sen vaivaajiesi käteen, jotka sanoivat sinulle: \"Lankea maahan, jotta kulkisimme ylitsesi.\" Sinä panit selkäsi maaksi ja kaduksi kulkijoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Nouse, nouse, pukeudu voimaasi, Siion; pukeudu juhlapukuusi, Jerusalem, sinä pyhä kaupunki. Sillä ei koskaan enää astu sisällesi ympärileikkaamaton eikä saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Pudista päältäsi tomu, nouse istuimellesi, Jerusalem. Irrota kahleet kaulastasi, sinä, vangittu tytär Siion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Sillä näin sanoo Herra: Ilmaiseksi teidät myytiin, rahatta teidät lunastetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Sillä näin sanoo Herra, Herra: Kansani meni ensin alas Egyptiin asumaan siellä muukalaisena, ja sitten Assur sorti sitä syyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Nyt, mitä minulla on tekemistä täällä, sanoo Herra, kun kansani on viety pois ilmaiseksi? Sen valtiaat elämöivät, sanoo Herra, ja nimeäni pilkataan alati, kaiket päivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Sen tähden kansani on tunteva nimeni. Sen tähden se on sinä päivänä tunteva, että minä olen se, joka sanon: \"Katso, minä se olen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Kuinka suloiset ovat vuorilla ilosanoman tuojan jalat, hänen, joka julistaa rauhaa, ilmoittaa hyvän sanoman, joka julistaa pelastusta, sanoo Siionille: \"Sinun Jumalasi on kuningas!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Kuule! Vartijasi korottavat äänensä, kaikki he riemuitsevat, sillä he näkevät silmästä silmään, kuinka Herra palaa Siioniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Huutakaa ilosta, riemuitkaa, kaikki te Jerusalemin rauniot, sillä Herra lohduttaa kansansa, lunastaa Jerusalemin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Herra paljastaa pyhän käsivartensa kaikkien kansojen nähden, ja kaikki maan ääret saavat nähdä Jumalamme autuuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Pois, pois! Lähtekää sieltä, älkää koskeko saastaiseen. Lähtekää sen keskeltä, puhdistautukaa, te Herran astioiden kantajat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Sillä teidän ei tarvitse lähteä kiireellä eikä kulkea paeten, sillä Herra käy teidän edellänne, Israelin Jumala seuraa suojananne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Katso, palvelijani menestyy, hän on nouseva, kohoava ja sangen korkea oleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Niin kuin monet kauhistuivat häntä – sillä niin runneltu, ei enää ihmisen kaltainen, oli hänen muotonsa, hänen hahmonsa ei ollut ihmislasten hahmo –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'niin hän on vihmova monet kansat ja hänen tähtensä kuninkaat sulkevat suunsa. Sillä mitä heille ei ole koskaan kerrottu, sen he saavat nähdä, mitä he eivät ole kuulleet, sen he saavat tajuta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Kuka uskoo saarnamme, kenelle Herran käsivarsi ilmoitetaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Hän kasvoi Herran edessä kuin vesa, kuin juuri kuivasta maasta. Hänellä ei ollut muotoa eikä kauneutta. Me näimme hänet, mutta hänellä ei ollut sellaista muotoa, johon olisimme mieltyneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Hän oli ylenkatsottu, ihmisten hylkäämä, kipujen mies ja sairauden tuttava, jota näkemästä kaikki kasvonsa peittivät, halveksittu, jota emme pitäneet minään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Mutta, totisesti, meidän sairautemme hän kantoi, meidän kipumme hän sälytti päälleen. Me pidimme häntä rangaistuna, Jumalan lyömänä ja vaivaamana,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'mutta hänet on haavoitettu meidän rikostemme tähden, runneltu meidän pahojen tekojemme tähden. Rangaistus oli hänen päällään, että meillä rauha olisi, ja hänen haavojensa kautta me olemme parannetut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Me vaelsimme kaikki eksyksissä kuin lampaat, kukin meistä poikkesi omalle tielleen. Mutta Herra heitti hänen päälleen meidän kaikkien syntivelat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Häntä piinattiin, ja hän alistui siihen eikä suutaan avannut. Kuin karitsa, joka viedään teuraaksi, kuin lammas, joka on ääneti keritsijöidensä edessä, hän ei suutaan avannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Ahdistettuna ja tuomittuna hänet otettiin pois, mutta kuka ajatteli hänen sukukuntaansa? Sillä hänet temmattiin pois elävien maasta. Kansani rikoksen tähden hän kärsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Hänelle annettiin hauta jumalattomien kanssa, mutta rikkaan luo hän tuli kuoltuaan, sillä hän ei ollut vääryyttä tehnyt eikä petosta ollut ollut hänen suussaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Mutta Herra näki hyväksi runnella häntä, lyödä häntä sairaudella. Jos sinä panet hänen sielunsa syntiuhriksi, hän saa nähdä jälkeläisiä ja elää kauan, ja Herran tahto toteutuu hänen kauttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Sielunsa vaivan tähden hän saa nähdä sen ja tulee ravituksi. Tuntemuksensa kautta hän, vanhurskas palvelijani, vanhurskauttaa monet sälyttämällä päälleen heidän pahat tekonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Sen tähden jaan hänelle suuren määrän saalista, ja hän jakaa saaliin väkevien kanssa. Sillä hän antoi sielunsa alttiiksi kuolemaan, ja hänet luettiin rikollisten joukkoon, hän kantoi monien synnit, ja hän rukoili rikollisten puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Riemuitse, sinä hedelmätön, joka et ole synnyttänyt, huuda ilosta ja puhkea riemuun, sinä, joka et ole ollut synnytyskivuissa. Sillä hylätyllä on lapsia enemmän kuin aviovaimolla, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Tee avaraksi telttasi sija, levennettäköön majojesi seinäkangas. Älä säästele! Pidennä telttaköytesi ja vahvista vaarnasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Sillä olet leviävä oikealle ja vasemmalle, jälkeläisesi ottavat omikseen kansat ja tekevät autiot kaupungit asutuiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Älä pelkää, sillä et joudu häpeään. Älä häpeile, sillä et pety. Nuoruutesi häpeän sinä unohdat etkä enää muista leskeytesi pilkkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Sillä se, joka sinut teki, on aviomiehesi. Herra Sebaot on hänen nimensä. Lunastajasi on Israelin Pyhä, hän, jota kutsutaan kaiken maan Jumalaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Sillä kuin hylätyn, syvästi murheellisen vaimon Herra on sinut kutsunut – nuoruuden vaimon, joka on ollut halveksittu, sanoo Jumalasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Vähäksi silmänräpäykseksi minä hylkäsin sinut, mutta kokoan sinut jälleen suurella laupeudella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'Ylitsevuotavassa vihassani peitin sinulta kasvoni silmänräpäykseksi, mutta armahdan sinut iankaikkisella armolla, sanoo Herra, lunastajasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Sillä tämä on minulle, niin kuin olivat Nooan vedet: niin kuin minä vannoin, etteivät Nooan vedet enää tulvi yli maan, niin vannon, etten enää vihastu sinuun enkä sinua nuhtele.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Sillä vuoret väistykööt ja kukkulat horjukoot, mutta minun armoni ei sinusta väisty eikä rauhanliittoni horju, sanoo Herra, armahtajasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Sinä kurja, myrskyn raastama, sinä lohduton! Katso, minä muuraan kivesi kiiltokivestä, teen perustuksesi safiireista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'teen harjasi rubiineista ja porttisi kristalleista ja koko ympärysmuurisi jalokivistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Lapsesi ovat kaikki Herran opetuslapsia, ja suuri rauha lapsillasi on oleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Sinut vahvistetaan vanhurskaudella. Sinä olet oleva kaukana väkivallasta, sillä sinulla ei ole syytä pelkoon, ja sinä olet kaukana hävityksestä, sillä se ei sinua lähesty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Jos kimppuusi käydään, se ei ole minusta. Se, joka kimppuusi käy, kaatuu eteesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Katso, minä olen luonut sepän, joka lietsoo hiilivalkeaa ja valmistaa aseen käyttöön. Mutta minä olen myös luonut tuhoojan hävittämään sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Jokainen ase, joka valmistetaan sinun varallesi, on oleva tehoton; ja jokaisen kielen, joka nousee käymään oikeutta kanssasi, sinä osoitat vääräksi. Tämä on Herran palvelijoiden perintöosa, tämä heidän vanhurskautensa, minulta saatu, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Kuulkaa, kaikki te, joilla on jano, tulkaa veden ääreen. Tekin, joilla ei ole rahaa, tulkaa, ostakaa ja syökää; tulkaa, ostakaa ilman rahaa, ilman hintaa viiniä ja maitoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Miksi annatte rahan siitä, mikä ei ole leipää, ja työnne ansion siitä, mikä ei ravitse? Kuulkaa minua, niin tulette syömään hyvää, ja sielunne virkistyy yltäkylläisyyden ääressä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Kallistakaa korvanne ja tulkaa luokseni. Kuulkaa, niin sielunne elää. Teen kanssanne iankaikkisen liiton, annan lujat Daavidin armot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Katso, hänet minä asetin kansoille todistajaksi, kansojen ruhtinaaksi ja käskijäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Katso, olet kutsuva pakanoita, joita et tunne, ja pakanat, jotka eivät sinua tunne, rientävät luoksesi Herran, Jumalasi, tähden, Israelin Pyhän tähden, sillä hän kirkastaa sinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Etsikää Herraa silloin, kun hänet löytää voidaan. Huutakaa häntä avuksi, kun hän on läsnä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Jumalaton hylätköön tiensä ja väärintekijä ajatuksensa ja palatkoon Herran luo, niin hän armahtaa häntä, ja Jumalamme luo, sillä hänellä on paljon anteeksiantamusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Sillä minun ajatukseni eivät ole teidän ajatuksianne, eivätkä teidän tienne ole minun teitäni, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Vaan niin paljon korkeampi kuin taivas on maata, ovat minun tieni korkeammat teidän teitänne ja minun ajatukseni teidän ajatuksianne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Sillä niin kuin sade ja lumi, joka taivaasta tulee, ei sinne palaa, vaan kostuttaa maan, tekee sen hedelmälliseksi ja kasvavaksi, antaa kylväjälle siemenen ja syöjälle leivän,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'niin on myös sanani, joka suustani lähtee. Se ei palaa tyhjänä luokseni, vaan tekee sen, mikä on minulle otollista, ja saa menestymään sen, mitä varten sen lähetin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Sillä iloiten te lähdette, ja rauhassa teitä saatetaan. Vuoret ja kukkulat puhkeavat riemuun edessänne, ja kaikki kedon puut taputtavat käsiään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Orjantappuran sijaan kasvaa sypressi, nokkosen sijaan kasvaa myrtti. Se tulee Herran kunniaksi, iankaikkiseksi merkiksi, joka ei häviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Näin sanoo Herra: Noudattakaa oikeutta ja tehkää vanhurskaus, sillä autuuteni on lähellä ja vanhurskauteni ilmestyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Autuas se ihminen, joka tämän tekee, se ihmislapsi, joka tässä pysyy, joka pitää sapatin eikä sitä riko, joka varoo kätensä tekemästä mitään pahaa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Älköön muukalainen, joka on liittynyt Herraan, sanoko: \" Herra on erottanut minut kokonaan kansastaan\", älköönkä kuohittu sanoko: \"Minä olen kuiva puu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Sillä näin sanoo Herra: Kuohituille, jotka pitävät sapattini ja valitsevat sen, mikä on minulle otollista, ja pysyvät liitossani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'heille annan huoneessani ja muurieni sisällä muistomerkin ja nimen, joka on poikia ja tyttäriä parempi. Annan heille iankaikkisen nimen, joka ei häviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Silloin muukalaiset, jotka ovat liittyneet Herraan, palvellakseen häntä, rakastaakseen Herran nimeä ja ollakseen hänen palvelijoitaan, kaikki ne, jotka pitävät sapatin eivätkä sitä riko ja pysyvät liitossani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'tuon pyhälle vuorelleni ja ilahdutan heitä rukoushuoneessani, ja heidän polttouhrinsa ja teurasuhrinsa ovat otollisia alttarillani, sillä huoneeni nimenä on oleva kaikkien kansojen rukoushuone.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Herra, Herra sanoo, hän, joka kokoaa Israelin karkotetut: Kokoan vielä muitakin sinne koottujen lisäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Kaikki kedon eläimet, tulkaa syömään, te metsän eläimet kaikki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Israelin vartijat ovat kaikki sokeita, he eivät käsitä mitään. He ovat kaikki mykkiä koiria, jotka eivät osaa haukkua. He näkevät unta, makailevat ja nukkuvat mielellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Näillä koirilla on kauhea nälkä, mikään ei niitä täytä. Ja tällaisia ovat paimenet! He eivät ymmärrä mitään. He ovat kaikki kääntyneet omille teilleen ja etsivät kukin omaa voittoaan, kaikki tyynni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, '\"Tulkaa, noudan viiniä, juokaamme väkijuomaa. Olkoon huomispäivä kuin tämä ja sitäkin vielä suurempi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Vanhurskas tuhoutuu, eikä kukaan pane sitä sydämelleen. Armoon turvaavat otetaan pois kenenkään siitä välittämättä, sillä vanhurskas otetaan pois pahuutta näkemästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Hän menee rauhaan. Ne, jotka vakaasti vaeltavat, saavat levätä vuoteillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Mutta tulkaa tänne, te ennustajien lapset, te avionrikkojamiehen ja porttovaimon siemen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Kenen kustannuksella te iloanne pidätte? Kenelle suuta auotte ja kielenne pitkälle pistätte? Ettekö te ole rikoksen lapsia ja valheen siementä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Te, jotka hehkutte himosta tammien varjossa, jokaisen vihreän puun alla, te, jotka teurastatte lapsia laaksoissa ja kallionrotkoissa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Laakson sileät paadet ovat osasi, siinä on arpaosasi. Niillehän olet juomauhrit vuodattanut ja ruokauhrit uhrannut. Siihenkö olisin tyytyväinen!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Korkealle ja valtavalle vuorelle valmistit vuoteesi. Sinne nousit myös uhraamaan teurasuhria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Oven ja pihtipielen taakse panit omat merkkisi. Sillä minusta luopuen sinä paljastit itsesi ja nousit vuoteellesi, teit sen tilavaksi. Sinä sovit kaupoista heidän kanssaan, makasit heidän kanssaan mielelläsi ja näit heidän häpynsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Kuljit kuninkaan luo öljyinesi, runsaine voiteinesi. Lähetit sanansaattajasi kauas, laskeuduit alas hautaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Väsyit matkasi pituudesta, et kuitenkaan sanonut: \"Turhaa!\" Koska sait elpynyttä voimaa, et käynyt heikoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Ketä arkailit ja pelkäsit, koska olit vilpillinen etkä muistanut minua etkä minusta välittänyt? Eikö niin: minä olen ollut vaiti aina ikiajoista asti, ja niin sinä et minua pelkää?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Minä ilmoitan, mitä ovat vanhurskautesi ja tekosi. Ne eivät auta sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Kun huudat, auttakoon sinua jumaliesi joukko! Tuuli vie ne pois kaikki, henkäys ottaa ne pois. Mutta joka minuun turvaa, se perii maan ja ottaa omakseen pyhän vuoreni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'Hän sanoo: Tehkää, tehkää tie, tasoittakaa tie, poistakaa kompastuskivet kansani tieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Sillä näin sanoo Korkea ja Ylhäinen, jonka asumus on iankaikkinen ja jonka nimi on Pyhä, joka asun korkeudessa ja pyhyydessä ja niiden luona, joilla on särjetty ja nöyrä henki, että virvoittaisin nöyryytettyjen hengen ja tekisin eläviksi särjettyjen sydämet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Sillä en riitele loputtomiin enkä vihastu ainiaaksi. Muuten henki nääntyisi kasvojeni edessä, ne sielut, jotka olen tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Hänen ahneutensa synnin tähden vihastuin, löin häntä, kätkin itseni ja olin vihainen. Mutta hän luopui minusta ja kulki oman sydämensä tietä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Olen nähnyt hänen tiensä, mutta parannan hänet ja johdatan häntä ja annan jälleen lohdutuksen hänelle ja häntä sureville.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Luon huulten hedelmän, rauhan, rauhan kaukaisille ja läheisille, sanoo Herra, ja parannan hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Mutta jumalattomat ovat kuin kuohuva meri, joka ei voi tyyntyä ja jonka aallot kuohuttavat liejua ja mutaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Jumalattomilla ei ole rauhaa, sanoo Jumalani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Huuda täyttä kurkkua, älä säästä, korota äänesi kuin torvi, ilmoita kansalleni heidän rikoksensa ja Jaakobin huoneelle heidän syntinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Minua he muka etsivät joka päivä ja haluavat tietoa teistäni niin kuin kansa, joka on tehnyt vanhurskauden eikä ole hylännyt Jumalansa oikeutta. He vaativat minulta vanhurskaita tuomioita ja haluavat, että Jumala heitä lähestyisi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, '\"Miksi paastoamme, kun et sitä näe, ja kuritamme itseämme, kun et sitä huomaa?\" Katso, paastopäivänänne te ajatte omia asioitanne ja ahdistatte työhön kaiken työväkenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Katso, riidaksi ja toraksi te paastoatte lyödäksenne jumalattomalla nyrkillä. Te ette nyt paastoa niin, että teidän ääntänne kuultaisiin korkeudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Tällainenko on se paasto, johon miellyn, se päivä, jona ihminen kurittaa itseään? Jos kallistaa päänsä kuin kaisla ja makaa säkissä ja tuhkassa, sitäkö sanot paastoksi ja päiväksi, joka on otollinen Herralle?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Eikö tämä ole paasto, johon miellyn: että avaatte vääryyden siteet, irrotatte ikeen nuorat, ja päästätte sorretut vapaiksi, että särjette kaikki ikeet?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Eikö tämä: että taitat leipäsi nälkäiselle ja viet kurjat kulkijat kotiisi, kun näet alastoman, vaatetat hänet etkä kätkeydy siltä, joka on omaa lihaasi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Silloin valkeutesi puhkeaa esiin kuin aamurusko, ja haavasi kasvavat nopeasti umpeen. Vanhurskautesi käy edelläsi, ja Jumalan kunnia seuraa suojanasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Silloin rukoilet, ja Herra vastaa, huudat, ja hän sanoo: \"Katso, tässä olen.\" Jos keskuudestasi poistat ikeen, sormella osoittelun ja vääryyden puhumisen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'jos avaat sielusi nälkäiselle ja ravitset vaivatun sielun, valkeus koittaa sinulle pimeydessä, ja pilkkopimeäsi on oleva kuin keskipäivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Herra johdattaa sinua alati ja ravitsee sielusi kuivissa erämaissa. Hän vahvistaa luusi, ja olet oleva kuin runsaasti kasteltu puutarha, kuin lähde, josta ei koskaan puutu vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Jälkeläisesi jälleenrakentavat ikivanhat rauniot, kohotat perusmuurit, muinaisten polvien laskemat. Nimesi on oleva: \"halkeamien umpeenmuuraaja\" ja \"teitten korjaaja maan asuttamiseksi\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Jos pidätät jalkasi sapattia rikkomasta, niin ettet toimita omia asioitasi pyhäpäivänäni, vaan kutsut sapatin ilopäiväksi, Herran pyhäpäivän kunnioitettavaksi ja kunnioitat sitä, niin ettet toimita omia toimiasi, et aja omia asioitasi etkä puhu joutavia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'silloin ilosi on oleva Herrassa, ja vien sinut maan kukkuloiden yli ja annan sinun nauttia isäsi Jaakobin perintöosaa. Sillä Herran suu on puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Katso, Herran käsi ei ole liian lyhyt auttamaan, eikä hänen korvansa kuuro kuulemaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'vaan teidän pahat tekonne erottavat teidät Jumalastanne, ja syntinne peittävät teiltä hänen kasvonsa, ettei hän kuule.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Sillä kätenne ovat tahratut vereen ja sormenne vääryyteen, huulenne puhuvat valhetta ja kielenne miettii petosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Kukaan ei saarnaa vanhurskaasti eikä tuomitse rehellisesti. He turvautuvat tyhjään ja puhuvat vilppiä, kantavat sisällään tuhoa ja synnyttävät turmion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Myrkkyliskon munia he hautovat, hämähäkin verkkoja he kutovat. Se, joka niitä munia syö, kuolee, rikkipoljetusta tulee esiin kyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Heidän verkkonsa eivät kelpaa vaatteeksi, heidän tekemäänsä ei voi verhoutua. Heidän työnsä ovat vääryyden töitä, ja heidän käsissään on väkivallan tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Heidän jalkansa juoksevat pahuuteen ja kiiruhtavat vuodattamaan viatonta verta. Heidän ajatuksensa ovat vääryyden ajatuksia, tuho ja turmio on heidän teillään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Rauhan tietä he eivät tunne eikä oikeutta ole heidän askeleissaan. Polkunsa he tekevät mutkaisiksi. Kukaan niistä, joka niitä kulkee, ei tunne rauhaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Sen tähden oikeus on meistä kaukana eikä vanhurskaus saavuta meitä. Odotamme valoa, mutta katso, on pimeä, aamunkoittoa, mutta vaellamme yössä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Haparoimme seiniä pitkin kuin sokeat, haparoimme kuin silmiä vailla olevat. Kompastelemme sydänpäivällä kuin hämärässä, olemme terveiden keskellä kuin kuolleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Murisemme kaikki kuin karhut ja kujerramme kuin kyyhkyset. Odotamme oikeutta, mutta sitä ei tule, pelastusta, mutta se on kaukana meistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Sillä rikoksemme ovat monilukuiset sinun edessäsi, ja syntimme todistavat meitä vastaan. Sillä rikoksemme seuraavat meitä ja pahat tekomme tunnemme:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'olemme luopuneet Herrasta ja kieltäneet hänet, vetäytyneet pois Jumalaamme seuraamasta, puhuneet sortoa ja kapinaa, kantaneet sitä sisällämme ja purkaneet sisimmästämme valheen sanoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Oikeus työnnetään takaperin, ja vanhurskaus seisoo kaukana, sillä totuus kompastelee torilla, suoruus ei voi tulla sisälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Totuus oli kadonnut, ja joka pahasta luopui, se ryöstettiin paljaaksi. Herra näki sen, ja sen, ettei ollut oikeutta. Se oli hänen silmissään paha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Hän näki, ettei ollut yhtään miestä, ja hän ihmetteli, ettei kukaan astunut väliin. Silloin hänen oma käsivartensa auttoi häntä, ja hänen vanhurskautensa tuki häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Hän puki ylleen vanhurskauden kuin rintahaarniskan ja pani pelastuksen kypärän päähänsä. Hän puki koston vaatteet puvukseen ja verhoutui kiivauteen kuin viittaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Tekojen mukaan hän maksaa palkan: vihan vastustajilleen, koston vihollisilleen. Hän kostaa merensaarille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'Silloin he pelkäävät päivän laskun mailla Herran nimeä ja päivän koittamilla hänen kunniaansa. Sillä se tulee kuin padottu virta, jota Herran Henki ajaa eteenpäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Mutta Siionille tulee Lunastaja, niille Jaakobissa, jotka synnistä kääntyvät, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'Mutta minä teen tämän liittoni heidän kanssaan, sanoo Herra: minun Henkeni, joka on päälläsi, ja sanani, jonka panen suuhusi, eivät väisty suustasi, eivät lastesi suusta eivätkä lastesi lasten suusta, sanoo Herra, nyt ja iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Nouse, ole kirkas, sillä valkeutesi tulee, ja Herran kunnia koittaa ylitsesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Sillä katso, pimeys peittää maan ja synkeys kansat, mutta ylitsesi koittaa Herra, ja ylläsi näkyy hänen kunniansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Kansat vaeltavat valkeuttasi kohden, kuninkaat aamunkoittosi kirkkautta kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Nosta silmäsi, katso ympärillesi: kaikki nämä ovat kokoontuneet ja tulevat luoksesi. Poikasi tulevat kaukaa ja tyttäriäsi kainalossa kannetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Silloin sen näet, ja loistat ilosta, sydämesi sykkii ja avartuu, kun meren aarteet kääntyvät luoksesi ja kansojen rikkaudet tulevat sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Kamelien paljous peittää sinut, Midianin ja Eefan varsat. Ne kaikki tulevat Sabasta, kantavat kultaa ja suitsutusta ja kuuluttavat Herran ylistystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Kaikki Keedarin laumat kokoontuvat luoksesi, Nebajotin pässit palvelevat sinua. Minulle otollisina ne nousevat alttarilleni, ja kirkastan kirkkauteni huoneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Keitä ovat nuo, jotka lentävät kuin pilvet ja lakkoihinsa kuin kyyhkyt?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Merensaaret odottavat minua, ja etumaisina tulevat Tarsiin laivat tuodakseen lapsesi kaukaa. Heillä on mukanaan hopeansa ja kultansa Herran, sinun Jumalasi, nimelle, Israelin Pyhälle, sillä hän kirkastaa sinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Muukalaiset rakentavat muurisi, ja heidän kuninkaansa palvelevat sinua, sillä vihassani löin sinua, mutta mielisuosiossani sinut armahdan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Porttisi pidetään aina auki. Niitä ei suljeta päivällä eikä yöllä, jotta kansojen rikkaudet tuotaisiin ja heidän kuninkaansa saatettaisiin luoksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Sillä se kansa tai valtakunta, joka ei sinua palvele, hukkuu, ja ne kansat hävitetään perin juurin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Libanonin kunnia tulee luoksesi, sypressit, jalavat sekä hopeakuuset kaunistavat pyhäkköni paikkaa, ja saatan jalkojeni sijan kunniaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Kumarassa kulkien tulevat luoksesi sortajiesi pojat, ja kaikki pilkkaajasi heittäytyvät jalkojesi juureen. He nimittävät sinua \" Herran kaupungiksi\" ja \"Israelin Pyhän Siioniksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Sen sijaan, että olet ollut hylätty ja vihattu, niin ettei ollut kauttasi kulkijaa, teen sinut korkeaksi iankaikkisesti, iloksi polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Imet kansojen maidon, imet kuninkaiden rintoja, tunnet, että minä, Herra, olen auttajasi, että Jaakobin Väkevä on lunastajasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Tuon vasken sijaan kultaa, ja raudan sijaan tuon hopeaa, puun sijaan vaskea ja kiven sijaan rautaa. Asetan sinulle paimeneksi rauhan ja käskijäksi vanhurskauden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Enää ei kuulu väkivaltaa maastasi, ei tuhoa eikä turmiota rajojesi sisältä, ja kutsut pelastuksen muuriksesi ja kiitoksen portiksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Aurinko ei ole enää valonasi päivällä, eikä valaise sinua kuun paiste, vaan Herra on iankaikkinen valkeutesi, ja Jumalasi kirkkautesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Aurinkosi ei enää laske, eikä kuusi menetä valoaan, sillä Herra on iankaikkinen valkeutesi, ja päättyneet ovat murheesi päivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Kansassasi ovat kaikki vanhurskaita. He saavat periä maan iankaikkisesti, he, istutukseni vesa, kätteni teko, kirkkauteni ilmoitukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Pienimmästä kasvaa heimo, vähäisimmästä väkevä kansa. Minä, Herra, sen aikanaan nopeasti täytän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Herran, Herran Henki on päälläni, sillä hän on voidellut minut julistamaan ilosanomaa nöyrille, lähettänyt minut sitomaan särjettyjä sydämiä, julistamaan vangituille vapautusta ja kahlituille kirvoitusta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'julistamaan Herran otollista vuotta ja Jumalamme kostonpäivää, lohduttamaan kaikkia murheellisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'panemaan Siionin murheellisten päähän – antamaan heille – juhlapäähineen tuhkan sijaan, iloöljyä murheen sijaan, ylistyksen viitan masentuneen hengen sijaan, ja heidän nimensä on oleva \"vanhurskauden tammet\" ja \" Herran istutus\" ilmoittamassa hänen kirkkauttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'He jälleenrakentavat ikivanhat rauniot, kohottavat ennalleen esi-isien autiot paikat ja uudistavat rauniokaupungit, jotka ovat olleet autioita polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Vieraat ovat laumojenne paimenina, muukalaiset peltomiehinänne ja viinitarhureinanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Mutta teitä kutsutaan Herran papeiksi, sanotaan Jumalamme palvelijoiksi. Te nautitte kansojen rikkauksista ja peritte heidän kunniansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Häpeänne hyvitetään teille kaksin kerroin, ja pilkatut saavat riemuita osastaan. He saavat kaksinkertaisen perinnön maassaan. Heillä on oleva iankaikkinen ilo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Sillä minä, Herra, rakastan oikeutta, vihaan vääryyttä ja ryöstöä, annan heille palkan uskollisesti ja teen heidän kanssaan iankaikkisen liiton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Heidän siemenensä tulee tunnetuksi kansojen keskuudessa ja heidän jälkeläisensä kansakuntien keskellä. Kaikki, jotka näkevät heidät, tuntevat heidät Herran siunaamaksi siemeneksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Iloitsen suuresti Herrassa, sieluni riemuitsee Jumalassani, sillä hän pukee päälleni autuuden vaatteet ja verhoaa minut vanhurskauden viittaan, yljän kaltaiseksi, joka kantaa turbaania kuin pappi, ja morsiamen kaltaiseksi, joka on kaunistettu koruillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Sillä niin kuin maa tuottaa kasvunsa ja niin kuin kasvitarha saa siemenkylvönsä versomaan, niin saattaa Herra, Herra versomaan vanhurskauden ja kiitoksen kaikkien kansojen nähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Siionin tähden en voi vaieta, ja Jerusalemin tähden en saa lepoa, ennen kuin sen vanhurskaus nousee kuin aamunkoi ja sen autuus kuin palava tulisoihtu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Kansat näkevät vanhurskautesi, kaikki kuninkaat kunniasi ja sinulle annetaan uusi nimi, jonka Herran suu säätää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Tulet kauniiksi kruunuksi Herran kädessä ja kuninkaalliseksi päähineeksi Jumalasi kädessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Sinua ei enää sanota \"hylätyksi\", eikä maatasi enää sanota \"autioksi\"; vaan sinua kutsutaan \"minun rakkaakseni\" ja maatasi \"aviovaimoksi\", sillä Herra rakastaa sinua, ja maasi otetaan avioon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Sillä niin kuin nuori mies ottaa neitsyen aviovaimoksi, niin lapsesi ottavat sinut omakseen, ja niin kuin ylkä iloitsee morsiamesta, niin Jumalasi iloitsee sinusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Muureillesi, Jerusalem, asetan vartijat. Älkööt he koskaan vaietko, ei päivällä eikä yöllä. Te, jotka ylistätte Herraa, älkää suoko itsellenne lepoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'Älkää antako hänelle lepoa, ennen kuin hän on asettanut ennalleen Jerusalemin ja tehnyt sen ylistykseksi maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Herra on vannonut oikean kätensä ja voimansa käsivarren kautta: Totisesti, enää en anna jyviäsi vihollistesi ruuaksi, eivätkä muukalaiset enää juo viiniäsi, josta sinä olet nähnyt vaivan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Vaan ne, jotka viljan kokoavat, syövät sen ja ylistävät Herraa, ja ne, jotka viinin korjaavat, juovat sen pyhissä esikartanoissani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Käykää, käykää ulos porteista, tasoittakaa kansalle tie, tehkää, tehkää valtatie, raivatkaa kivet pois, kohottakaa kansoille lippu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Katso, Herra on kuuluttanut maan ääriin asti: Sanokaa tytär Siionille: Katso, pelastuksesi tulee. Katso, hänen palkkansa on hänen mukanaan ja hänen työnsä ansio käy hänen edellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Heitä kutsutaan \"pyhäksi kansaksi\", \" Herran lunastetuiksi\"; ja sinua kutsutaan \"halutuksi\", \"kaupungiksi, joka ei ole hylätty.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Kuka tuolla tulee Edomista, tulipunaisissa vaatteissa Bosrasta, tuo puvultaan komea, joka uljaana astelee suuressa voimassaan? \"Minä, joka puhun vanhurskautta, joka olen voimallinen auttamaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Miksi on punaa puvussasi, miksi vaatteesi ovat kuin viinikuurnan polkijan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, '\"Kuurnan poljin, yksinäni, kansakunnista ketään ei ollut kanssani. Poljin heidät vihassani, tallasin heidät kiivaudessani, ja niin roiskui heidän vertaan vaatteilleni, ja tahrin koko pukuni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Sillä koston päivä oli mielessäni ja lunastettujeni vuosi oli tullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Katselin, mutta ei ollut auttajaa, ja ihmettelin, kun kukaan ei tullut tueksi. Silloin oma käsivarteni auttoi minua, ja vihani tuki minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Tallasin kansat vihassani, juovutin heidät kiivaudellani ja vuodatin maahan heidän verensä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Herran armotöitä julistan, Herran ylistettäviä tekoja, kaikkea, mitä Herra on meille tehnyt, suurta hyvyyttä Israelin heimoa kohtaan, mitä hän on heille osoittanut laupeudessaan ja suuressa armossaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Hän sanoi: \"Ovathan he kansani ja ovathan he lapsia, joissa ei ole vilppiä\", ja hän tuli heille vapahtajaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'Kaikissa heidän ahdistuksissaan hänelläkin oli ahdistus, mutta hänen kasvojensa Enkeli vapahti heidät. Rakkaudessaan ja säälissään hän lunasti heidät, nosti heitä ja kantoi heitä kaikkina muinaisina päivinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Mutta he niskoittelivat ja saattoivat murheelliseksi hänen Pyhän Henkensä; ja hän muuttui heidän vihollisekseen. Hän itse soti heitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Hänen kansansa muisti entisiä päiviä, muisti Moosesta: Missä on hän, joka toi heidät ylös merestä, heidät sekä hänen laumansa paimenen? Missä on hän, joka pani tämän sydämeen Pyhän Henkensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'hän, joka antoi kunniansa käsivarren kulkea Mooseksen oikealla puolella, joka halkaisi vedet heidän edestään tehdäkseen itselleen iankaikkisen nimen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'hän, joka kuljetti heitä syvyyksissä kuin hevosia erämaassa, eivätkä he kompastelleet?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Niin kuin karja astuu alas laaksoon, niin Herran Henki vei heidät lepoon. Niin olet kansaasi johdattanut tehdäksesi itsellesi kunniallisen nimen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Katsele taivaasta, katso pyhyytesi ja kirkkautesi asunnosta. Missä ovat kiivautesi ja voimalliset tekosi? Sydämesi sääli ja armahtavaisuutesi ovat sulkeutuneet minulta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Sinähän olet isämme, sillä Aabraham ei meistä tiedä eikä Israel meitä tunne: sinä, Herra, olet isämme; \"Lunastajamme\" on ikiajoista nimesi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Minkä tähden olet sallinut meidän eksyä pois teiltäsi, Herra, ja olet antanut sydämemme paatua, niin ettemme sinua pelkää? Palaa takaisin palvelijoidesi tähden, perintöosasi sukukuntien tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Vähän aikaa vain pyhä kansasi omisti perintönsä. Ahdistajamme ovat tallanneet pyhäkköäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Olemme kuin ne, joita et ole ikinä hallinnut, olemme, kuin meitä ei olisi otettu nimiisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Oi, jospa sinä halkaisisit taivaat ja astuisit alas, niin että vuoret järkkyisivät edessäsi, niin kuin risut leimahtavat tuleen, niin kuin vesi kiehuu tulella, että tekisit nimesi tunnetuksi vastustajillesi ja kansat vapisisivat kasvojesi edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'kun teet pelottavia tekoja, joita emme voineet odottaa! Oi, jospa astuisit alas, niin että vuoret järkkyisivät edessäsi!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Ei ole ikiajoista kuultu, ei ole korviin tullut, ei ole silmä nähnyt muuta Jumalaa, paitsi sinut, joka tekisi sellaisia häntä odottavalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Sinä käyt niitä kohden, jotka tekevät ilolla vanhurskautta ja jotka teilläsi sinua muistavat. Katso, sinä vihastuit, ja me jouduimme synnin alaisiksi. Niin on ollut ikiajoista asti – saammeko avun?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Kaikki me olemme kuin saastaiset, ja kuin tahrattu vaate on kaikki vanhurskautemme. Kaikki olemme lakastuneita kuin lehdet, ja pahat tekomme heittelevät meitä kuin tuuli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Ei ole ketään, joka huutaa avukseen nimeäsi, joka herää pitämään sinusta kiinni, sillä olet peittänyt kasvosi meiltä ja jättänyt meidät menehtymään syntiemme valtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Mutta olethan sinä, Herra, Isämme; me olemme savi, ja sinä olet valajamme, kaikki me olemme kättesi tekoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Älä, Herra, vihastu aivan suuresti, äläkä ainiaan muistele pahoja tekoja. Katso ja huomaa, että me kaikki olemme sinun kansaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Pyhät kaupunkisi ovat tulleet erämaaksi, Siion on erämaaksi tullut, Jerusalem autioksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Pyhä ja ihana temppelimme, jossa isämme sinua ylistivät, on tulella poltettu, ja rauniona on kaikki meille kallisarvoinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Vaikka nämä näin ovat, voitko, Herra, hillitä itsesi, voitko olla vaiti ja vaivata meitä niin kovasti?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Olen niiden etsittävänä, jotka eivät minua kysyneet, niiden löydettävänä, jotka eivät minua etsineet. Olen sanonut kansalle, jota ei ole otettu minun nimiini: Katso, tässä olen, katso, tässä olen!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Koko päivän olen ojentanut käsiäni uppiniskaista kansaa kohden, joka vaeltaa omien ajatustensa mukaan tietä, joka ei ole hyvä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'kansaa kohden, joka vihoittaa minua alinomaa, vasten kasvojani, uhraa puutarhoissa ja suitsuttaa tiilikivialttareilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'He asustavat haudoissa ja yöpyvät salaisissa paikoissa. He syövät sianlihaa, ja heillä on saastaista lientä astioissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'He sanovat: \"Pysy erilläsi, älä tule minua lähelle, sillä olen sinulle pyhä.\" Nämä ovat savu sieraimissani, tuli, joka palaa kaiken päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Katso, se on kirjoitettuna edessäni. En ole vaiti, vaan maksan, maksan heille helmaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'heidän pahat tekonsa sekä teidän isienne pahat teot, sanoo Herra, niiden, jotka ovat vuorilla suitsuttaneet ja kukkuloilla minua häväisseet. Ensiksi mittaan heille palkan heidän helmaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Näin sanoo Herra: Niin kuin sanotaan rypäleestä, jos siinä on mehua: \"Älä hävitä sitä, sillä siinä on siunaus\", niin teen palvelijoideni tähden, etten kaikkea hävittäisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Tuotan Jaakobista siemenen ja Juudasta vuorteni perillisen, niin valittuni saavat periä maan ja palvelijani saavat asua siinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Saaron on oleva lammasten laitumena ja Aakorin laakso karjan lepopaikkana kansallani, joka minua etsii.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Mutta te, jotka hylkäätte Herran ja unohdatte pyhän vuoreni, jotka valmistatte Gadille pöydän ja vuodatatte uhrijuomaa Menille –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'teidät määrään miekan omiksi. Te kaikki kumarrutte teurastettaviksi, sen tähden ettette vastanneet, kun kutsuin, ettekä kuulleet, kun puhuin, vaan teitte sitä, mikä on pahaa silmissäni, ja valitsitte sen, mikä ei ole minulle otollista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Sen tähden, näin sanoo Herra, Herra: Katso, palvelijani syövät, mutta te näette nälkää. Katso, palvelijani juovat, mutta te kärsitte janoa. Katso, palvelijani iloitsevat, mutta te joudutte häpeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Katso, palvelijani riemuitsevat sydämen onnesta, mutta te huudatte sydämen tuskasta ja voivotatte henki murtuneena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'Te jätätte nimenne kiroukseksi valituilleni: \"Sinut surmatkoon Herra, Herra!\" Mutta palvelijoilleen hän on antava toisen nimen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Se, joka maassa itsensä siunaa, siunaa itsensä todellisen Jumalan nimeen, ja se, joka maassa vannoo, vannoo oikean Jumalan nimeen. Sillä entiset ahdistukset ovat unohdetut ja silmiltäni peitossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Sillä katso, luon uudet taivaat ja uuden maan. Entisiä ei enää muisteta, eivätkä ne enää astu ajatukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Vaan saatte iloita ja riemuita iankaikkisesti siitä, mitä minä luon. Sillä katso, iloksi minä luon Jerusalemin ja riemuksi sen kansan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'Minä iloitsen Jerusalemista ja riemuitsen kansastani, eikä siellä enää kuulla itkun ääntä eikä valituksen ääntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Siellä ei ole enää imeväistä, joka eläisi vain muutaman päivän, ei vanhusta, joka ei täyttäisi päiviensä määrää. Sillä nuori kuolee satavuotiaana, ja satavuotiaana synnintekijä joutuu kiroukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'He rakentavat taloja ja asuvat niissä, he istuttavat viinitarhoja ja syövät niiden hedelmät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'He eivät rakenna muiden asua, eivät istuta muiden syödä. Sillä niin kuin puiden päivät ovat, niin ovat elinpäivät kansassani. Valittuni kuluttavat itse kättensä työn.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'He eivät tee työtä turhaan eivätkä synnytä lapsia äkkikuoleman omiksi, sillä he ovat Herran siunattujen siemen, ja heidän vesansa ovat heidän luonaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Ennen kuin he huutavat, minä vastaan, heidän vielä puhuessaan minä kuulen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Susi ja lammas käyvät yhdessä laitumella, ja leijona syö rehua kuin nauta, ja käärmeen ruokana on maan tomu. Missään pyhällä vuorellani ei tehdä pahaa eikä vahinkoa, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Näin sanoo Herra: Taivas on valtaistuimeni, ja maa on jalkojeni astinlauta. Mikä olisi huone, jonka te minulle rakentaisitte, mikä paikka olisi leposijani?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Käteni on kaikki nämä tehnyt, ja niin ovat kaikki nämä syntyneet, sanoo Herra. Mutta katson sen puoleen, joka on nöyrä, jolla on särjetty henki ja arka tunto sanani edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Joka teurastaa härän, mutta myös tappaa miehen, joka uhraa lampaan, mutta myös taittaa koiralta niskan, joka uhraa ruokauhrin, mutta myös sian verta, joka polttaa suitsuketta, mutta myös ylistää epäjumalaa: he ovat valinneet omat tiensä. Niin kuin heidän sielunsa on mieltynyt heidän iljetyksiinsä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'minäkin valitsen heidän vaivaamisensa ja annan heille tulla sen, mitä he pelkäävät, koska kukaan ei vastannut, kun kutsuin, koska he eivät kuulleet, kun puhuin, vaan tekivät sitä, mikä on pahaa silmissäni, ja valitsivat sen, mikä ei ole minulle otollista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Kuulkaa Herran sana, te, jotka olette aralla tunnolla hänen sanansa edessä: Teidän veljenne, jotka vihaavat teitä ja työntävät teidät luotaan nimeni tähden, sanovat: \"Osoittakoon Herra kunniansa, että näemme teidän ilonne!\" Mutta he joutuvat häpeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Kohiseva ääni kaupungista! Ääni temppelistä! Herran ääni: hän maksaa palkan vihollisilleen!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Ennen kuin Siion tuntee kipuja, hän synnyttää. Ennen kuin hänelle tulevat tuskat, hän saa poikalapsen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Kuka on sellaista kuullut, kuka sellaista nähnyt? Syntyykö maa yhden päivän kivulla, tai synnytetäänkö kansa yhdellä kerralla? Siionhan tunsi kipuja ja samalla jo synnytti lapsensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Minäkö avaisin kohdun sallimatta synnyttää, sanoo Herra, tai minäkö, joka saatan synnyttämään, sulkisin kohdun?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Iloitkaa Jerusalemin kanssa ja riemuitkaa hänestä kaikki, jotka häntä rakastatte. Iloitsemalla iloitkaa hänen kanssaan, te, jotka olette surreet hänen tähtensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'että imisitte ja tulisitte ravituiksi hänen lohdutuksensa rinnoista, että joisitte ja virkistyisitte hänen kunniansa runsaudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Sillä näin sanoo Herra: Ohjaan hänen luokseen rauhan kuin virran ja kansojen kunnian kuin tulvivan joen. Te imette, kainalossa teitä kannetaan, ja polvilla pitäen teitä hyväillään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Niin kuin mies lohduttaa äitiään, niin minä lohdutan teitä, ja Jerusalemissa te saatte lohdutuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Te näette sen, ja teidän sydämenne iloitsee, ja teidän luunne virkistyvät kuin vihanta ruoho. Silloin Herran käsi tulee tunnetuksi hänen palvelijoissaan, mutta vihollistensa hän antaa tuntea vihansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Sillä, katso, Herra tulee tulessa, ja hänen vaununsa ovat kuin myrskytuuli. Hän antaa vihansa purkautua hehkussa ja nuhtelunsa tulenliekeissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Herra käy tuomiolle kaiken lihan kanssa tulella ja miekallaan, ja Herran surmaamia on oleva paljon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Niistä, jotka pyhittäytyvät ja puhdistautuvat puutarhamenoja varten, seuraten miestä, joka on heidän keskellään ja jotka syövät sianlihaa ja muuta inhottavaa sekä hiiriä, niistä kaikista tulee loppu, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Minä tunnen heidän tekonsa ja ajatuksensa. Tulee aika, jolloin kokoan kaikki kansat ja kielet, ja he tulevat ja näkevät kunniani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Teen tunnusteon heidän keskellään ja lähetän pakoon päässeitä heidän joukostaan pakanoiden luo Tarsiiseen, Puuliin ja Luudiin, jousimiesten luo, Tuubaliin ja Jaavaniin, kaukaisiin merensaariin, jotka eivät ole kuulleet minusta kerrottavan eivätkä nähneet kunniaani, ja he ilmoittavat kunniani pakanoiden keskuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'He tuovat kaikki veljenne kaikista kansoista uhrilahjana Herralle hevosilla, vaunuilla, kantotuoleilla, muuleilla ja ratsukameleilla pyhälle vuorelleni Jerusalemiin, sanoo Herra, niin kuin israelilaiset tuovat ruokauhrin puhtaassa astiassa Herran temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Heitäkin otan leeviläisiksi papeiksi, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Niin kuin uudet taivaat ja uusi maa, jotka minä teen, pysyvät kasvojeni edessä, sanoo Herra, pysyy siemenenne ja nimenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'Joka kuukausi uudenkuun päivänä ja joka viikko sapattina tulee kaikki liha kumartaen rukoilemaan minua, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'He käyvät ulos katselemaan niiden miesten ruumiita, jotka ovat luopuneet minusta. Sillä heidän matonsa ei kuole, eikä heidän tulensa sammu, ja he ovat kauhistukseksi kaikelle lihalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Jeremian, Hilkian pojan, sanat. Hän oli Anatotin pappeja Benjaminin maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'Hänelle tuli Herran sana Juudan kuninkaan Joosian, Aamonin pojan, päivinä, tämän kolmantenatoista hallitusvuotena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'Se tuli vielä Juudan kuninkaan Joojakimin, Joosian pojan, päivinä ja aina Juudan kuninkaan Sidkian, Joosian pojan, yhdennentoista vuoden loppuun asti. Silloin viidentenä kuukautena Jerusalemin asukkaat vietiin karkotukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, '\"Jo ennen kuin valmistin sinut kohdussa, tunsin sinut omakseni, ja ennen kuin lähdit kohdusta, pyhitin sinut, asetin sinut kansojen profeetaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Mutta sanoin: \"Voi Herra, Herra! Katso, en osaa puhua, sillä minä olen nuori.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Herra sanoi minulle: \"Älä sano: \'Minä olen nuori\', vaan mene, minne ikinä sinut lähetän, ja puhu kaikki, mitä käsken sinun puhua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Älä pelkää heitä, sillä minä olen kanssasi ja pelastan sinut, sanoo Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Herra ojensi kätensä ja kosketti suutani, ja Herra sanoi minulle: \"Katso, panen sanani suuhusi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Katso, asetan sinut tänä päivänä kansoja ja valtakuntia vastaan repimään maasta ja hajottamaan, hävittämään ja kukistamaan, rakentamaan ja istuttamaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Minulle tuli tämä Herran sana, ja se kuului: \"Mitä sinä näet, Jeremia?\" Vastasin: \"Minä näen mantelipuun oksan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Herra sanoi minulle: \"Olet nähnyt oikein, sillä minä valvon sanaani toteuttaakseni sen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Minulle tuli toistamiseen Herran sana, näin sanoen: \"Mitä sinä näet?\" Vastasin: \"Minä näen kiehuvan padan. Se näkyy pohjoisen puolelta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Herra sanoi minulle: \"Pohjoisesta onnettomuus kohtaa kaikkia tämän maan asukkaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Sillä katso, kutsun kaikki pohjoisten valtakuntien kansanheimot, sanoo Herra, ja ne tulevat ja asettavat kukin valtaistuimensa Jerusalemin porttien oville ja kaikkia sen muureja vastaan, ympäriinsä, ja kaikkia Juudan kaupunkeja vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Julistan heille tuomioni kaikesta heidän pahuudestaan, koska he ovat hylänneet minut, polttaneet uhreja muille jumalille ja kumartaneet kättensä tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Mutta sinä, vyötä lanteesi, nouse ja puhu heille kaikki, mitä minä käsken sinun puhua. Älä heitä kauhistu, etten kauhistuttaisi sinua heidän edessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Sillä katso, minä teen sinusta tänä päivänä varustetun kaupungin, rautapatsaan ja vaskimuurin koko maata vastaan, Juudan kuninkaita, sen ruhtinaita, sen pappeja ja maan kansaa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Niin he sotivat sinua vastaan, mutta eivät voita sinua, sillä minä olen kanssasi, sanoo Herra, ja pelastan sinut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, '\"Mene ja julista Jerusalemin kuullen ja sano: Näin sanoo Herra: Muistan nuoruutesi ystävällisyyden, morsiusaikasi rakkauden, kun sinä seurasit minua erämaassa, maassa, jossa ei kylvetä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Herran pyhäkkö oli Israel, hänen ensisatonsa. Kaikki, jotka sitä söivät, joutuivat syynalaisiksi, ja onnettomuus kohtasi heitä, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Kuulkaa Herran sana, Jaakobin heimo ja kaikki Israelin huoneen sukukunnat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Näin sanoo Herra: Mitä vääryyttä teidän isänne minusta löysivät, koska he loittonivat minusta kauas ja lähtivät seuraamaan turhia jumalia ja tulivat turhanpäiväisiksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'He eivät kysyneet: \'Missä on Herra, joka toi meidät pois Egyptin maasta, joka johdatti meitä erämaassa, arojen ja kuilujen maassa, kuivuuden ja kuoleman varjon maassa, maassa, jossa ei kukaan kulje eikä yksikään ihminen asu?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Sitten toin teidät hedelmätarhojen maahan syömään sen hedelmää ja hyvyyttä, mutta sinne tultuanne saastutitte maani ja teitte perintöosani kauhistukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Papit eivät kysyneet: \'Missä on Herra?\' Lainkäyttäjät eivät minua tunteneet, paimenet luopuivat minusta, profeetat ennustivat Baalin nimessä ja seurasivat niitä, joista ei ole apua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Sen tähden käyn vielä oikeutta teidän kanssanne, sanoo Herra, ja lastenne lasten kanssa käyn oikeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Menkää kittiläisten saarille katsomaan ja lähettäkää [lähettinne] Keedariin panemaan tarkasti merkille ja katsomaan, onko sellaista tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Onko mikään pakanakansa vaihtanut jumalia, vaikka ne eivät jumalia ole? Mutta minun kansani on vaihtanut Kunniansa siihen, josta ei ole apua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Hämmästykää tästä, te taivaat, kauhistukaa, aivan järkyttykää, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Sillä minun kansani on tehnyt kaksinkertaisen synnin: minut, elävän veden lähteen, he ovat hylänneet, ja ovat hakanneet itselleen vesisäiliöitä, särkyviä säiliöitä, jotka eivät pidä vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Onko Israel ostettu orja tai kotona syntynyt? Minkä tähden hän on joutunut saaliiksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Häntä vastaan karjuivat nuoret leijonat, antoivat äänensä kuulua. Ne tekivät hänen maansa autioksi, hänen kaupunkinsa hävitettiin, niin ettei siinä ole asukkaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Myös noofilaiset ja tahpanheelaiset pitivät päälakeasi laitumenaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Eikö tämän tee sinulle se, että hylkäät Herran, Jumalasi, silloin kun hän tahtoo kuljettaa sinua tietä pitkin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Mutta nyt, mitä menemistä Egyptiin sinulla on juomaan Siihorin vettä ja mitä menemistä Assuriin sinulla on juomaan Eufrat-virran vettä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Pahuutesi tuottaa sinulle kurituksen, ja luopumuksesi saattaa sinut rangaistukseen. Niin tiedä ja näe, kuinka onnetonta ja katkeraa on, että hylkäät Herran, Jumalasi, etkä minua pelkää, sanoo Herra, Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Sillä jo kaukaisista ajoista olet särkenyt ikeesi, katkaissut siteesi ja sanonut: \'En tahdo palvella.\' Sillä kaikilla korkeilla kukkuloilla ja kaikkien vihreiden puiden alla makailit porttona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Olin istuttanut sinut jaloksi viiniköynnökseksi, totuuden siemeneksi. Kuinka olet muuttunut minulle vieraan viinipuun villiköynnökseksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Vaikka pesisit itsesi saippualla ja käyttäisit paljon lipeää, saastaiseksi jää sittenkin syntisi edessäni, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Kuinka sanot: \'En ole saastuttanut itseäni enkä kulkenut baalien perässä\'! Katso menoasi laaksossa ja tiedä, mitä olet tehnyt, sinä nopea, nuori naaraskameli, joka juokset sinne tänne;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'sinä villiaasi, erämaahan tottunut, joka ahmit himossasi ilmaa! Kuka voi sitä pidätellä? Joka sitä etsii, sen ei tarvitse väsyttää itseään. Sen löytää, kun tulee sen kuukausi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Varo, ettet tallaa jalkojasi paljaiksi ja kurkkuasi janoiseksi. Mutta sanot: \'Ei pelkoa! Sillä minä rakastan vieraita ja seuraan niitä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Niin kuin teosta tavattu varas on häpeissään, niin joutuu Israelin huone häpeään, se ja sen kuninkaat, ruhtinaat, papit ja profeetat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'ne, jotka sanovat puulle: \'Sinä olet isäni\' ja kivelle: \'Sinä olet minut synnyttänyt.\' Sillä he ovat kääntäneet minulle selkänsä eivätkä kasvojaan. Mutta onnettomuutensa aikana he sanovat: \'Nouse ja pelasta meidät.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Mutta missä ovat jumalasi, jotka olet itsellesi tehnyt? Nouskoot ne, jos voivat pelastaa sinut onnettomuutesi aikana. Sillä yhtä monta, kuin sinulla on kaupunkeja, sinulla on jumalia, Juuda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Miksi riitelette minua vastaan? Olettehan te kaikki tehneet syntiä minua vastaan, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Turhaan olen lyönyt lapsianne. He eivät ole ottaneet kuritusta varteen. Miekkanne on syönyt profeettojanne kuin hävittävä leijona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Te sukukunta! Katsokaa Herran sanaa: olenko ollut Israelille erämaa, pimeyden maa? Miksi kansani sanoo: \'Me juoksemme valtoimina emmekä enää tule luoksesi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Unohtaako neitsyt korunsa, morsian koruvyönsä? Mutta minun kansani on unohtanut minut lukemattomina päivinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Kuinka ovelasti kuljet etsiessäsi rakkautta! Niinpä oletkin perehtynyt pahuuden teihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Vaatteesi liepeetkin ovat köyhien, viattomien veressä. Et tavannut heitä murtautumasta sisälle, mutta siitä huolimatta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Kuitenkin sanot: \'Olen syytön; hänen vihansa on kai kääntynyt minusta pois.\' Katso, käyn oikeutta kanssasi, koska sanot: \'En ole tehnyt syntiä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Miksi niin täysin käännyt vaihtamaan tiesi! Egyptistäkin olet saava häpeän, niin kuin sait häpeän Assurista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Senkin luota olet lähtevä kädet pääsi päällä, sillä Herra on hylännyt ne, joihin luotat, eikä heistä tule sinulle menestystä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'On sanottu: Katso, jos mies lähettää pois vaimonsa ja tämä lähtee hänen luotaan ja tulee toisen miehen vaimoksi, palaako mies enää hänen luokseen? Eikö maa tule saastutetuksi? Mutta sinä olet harjoittanut haureutta monen ystävän kanssa – palaa kuitenkin luokseni! – sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Nosta silmäsi kukkuloihin ja katso: missä ei olisi sinua maattu? Teitten vieressä sinä istuit heitä odotellen kuin arabialainen erämaassa, ja saastutit maan haureudellasi ja pahuudellasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Sadekuurot tyrehtyivät, kevätsade jäi tulematta, mutta sinulla oli porttonaisen otsa, et tahtonut hävetä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Kuitenkin huudat nyt minulle: \"Isäni! Sinä olet nuoruuteni ystävä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Pitääkö hän vihaa iankaikkisesti, kantaako hän sitä ainiaan?\" Katso, näin sinä puhut, mutta teet pahaa, ja siihen sinä pystyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Herra sanoi minulle kuningas Joosian päivinä: \"Oletko nähnyt, mitä tuo luopiovaimo, Israel, on tehnyt? Hän kuljeskeli kaikilla korkeilla vuorilla ja kaikkien vihreiden puiden alla ja harjoitti siellä haureutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Sanoin, sitten kun hän oli kaiken tämän tehnyt: \'Palaa luokseni.\' Mutta hän ei palannut, ja hänen uskoton sisarensa Juuda näki sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Näin, että vaikka olin lähettänyt pois luopiovaimo Israelin juuri sen tähden, että hän oli tehnyt aviorikoksen ja olin antanut hänelle erokirjan, uskoton Juuda, hänen sisarensa, ei kuitenkaan pelännyt, vaan meni ja harjoitti hänkin haureutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Haureutensa huudolla hän saastutti maan ja teki aviorikoksen kiven ja puun kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Kaikesta tästäkään huolimatta hänen uskoton sisarensa Juuda ei palannut luokseni kaikesta sydämestään, vaan petollisesti, sanoo Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Herra sanoi minulle: \"Luopiovaimo Israel on osoittautunut vanhurskaammaksi kuin uskoton Juuda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Mene ja julista nämä sanat pohjoiseen päin ja sano: Palaa, sinä luopiovaimo Israel, sanoo Herra. En synkistä teille kasvojani, sillä minä olen armollinen, sanoo Herra, enkä pidä vihaa iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Ainoastaan tunne rikoksesi, että olet rikkonut Herraa, Jumalaasi vastaan, ja juossut sinne tänne vieraiden jumalien luo, kaikkien vihreiden puiden alle, ettekä ole kuulleet ääntäni, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Palatkaa takaisin, te luopiolapset, sanoo Herra, sillä minä kihlaan teidät ja otan teidät omikseni, yhden ainoankin kaupungista ja kaksi sukukunnasta, ja tuon teidät Siioniin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'ja annan teille paimenet oman sydämeni mukaan, ja he kaitsevat teitä tiedolla ja taidolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Kun te lisäännytte ja tulette hedelmällisiksi maassa niinä päivinä, sanoo Herra, enää ei puhuta Herran liitonarkista, se ei enää nouse mieleen, eikä sitä enää muisteta. Sen luo ei enää tulla eikä sitä enää tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'Siihen aikaan sanotaan Jerusalemia Herran valtaistuimeksi, ja kaikki kansat kokoontuvat sinne, Jerusalemiin, Herran nimen tähden eivätkä enää vaella pahan sydämensä paatumuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'Niinä päivinä Juudan heimo on kulkeva Israelin heimon luo, ja he tulevat yhdessä pohjoisesta maasta siihen maahan, jonka annoin isillenne perinnöksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Minä sanoin: Kuinka asetankaan sinut lasten joukkoon ja annan sinulle suloisen maan, ihanan perintöosan, pakanoiden ihanimman joukon! Sanoin: Olet sanova minua Isäksi etkä ole koskaan kääntyvä minusta pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Mutta niin kuin vaimo on uskoton puolisolleen, niin te, Israelin heimo, olette olleet uskottomat minulle, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Kuule! Kallioilta kuuluu itku, israelilaisten valitus, sillä he ovat vaeltaneet väärää tietä ja ovat unohtaneet Herran, Jumalansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Palatkaa takaisin, te luopuneet lapset, niin parannan teidän luopumuksenne.\" – \"Katso, me tulemme luoksesi, sillä sinä olet Herra, Jumalamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Totisesti, petosta on, mitä kukkuloilta kuuluu, pauhina vuorilla. Totisesti, Herrassa, Jumalassamme, on Israelin pelastus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Häpeäjumala on syönyt isiemme vaivannäön nuoruudestamme asti, heidän lampaansa ja nautansa, poikansa ja tyttärensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Maatkaamme häpeässämme, ja häväistyksemme peittäköön meidät, sillä Herraa, Jumalaamme, vastaan me olemme syntiä tehneet, me ja isämme, aina nuoruudestamme tähän päivään asti, emmekä ole kuulleet Herran, Jumalamme, ääntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, '\"Jos sinä, Israel, käännyt, sanoo Herra, käänny minun luokseni, ja jos sinä poistat iljetyksesi kasvojeni edestä, niin et harhaile.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'Jos vannot: \'Niin totta kuin Herra elää\', totuudessa, oikeutta noudattaen ja vanhurskaasti, niin kansat siunaavat itsensä hänen nimeensä, ja hän on heidän kunniansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Sillä näin sanoo Herra Juudan miehille ja Jerusalemille: Raivatkaa itsellenne uudispelto, älkääkä kylväkö orjantappuroihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Ympärileikatkaa itsenne Herralle ja poistakaa sydämenne esinahka, te Juudan miehet ja Jerusalemin asukkaat, ettei vihani syttyisi tekojenne pahuuden tähden kuin tuli ja palaisi, eikä olisi sammuttajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Julistakaa Juudassa ja Jerusalemissa, saarnatkaa ja sanokaa: Puhaltakaa torveen kautta maan. Huutakaa täysin voimin ja sanokaa: \'Kokoontukaa, ja menkäämme varustettuihin kaupunkeihin.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Nostakaa lippu Siionia kohti, paetkaa pysähtymättä, sillä minä annan tulla pohjoisesta onnettomuuden ja suuren hävityksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Leijona on noussut tiheiköstään, kansojen hävittäjä on lähtenyt liikkeelle ja lähtenyt paikaltaan tekemään maasi autioksi. Kaupunkisi hävitetään niin, ettei niissä ole asukkaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Sen tähden kääriytykää säkkeihin, valittakaa ja itkekää, sillä Herran vihan hehku ei ole kääntynyt meistä pois.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Sinä päivänä tapahtuu, tämä on Herran sana: kuninkaan ja ruhtinaiden rohkeus katoaa, papit kauhistuvat ja profeetat hämmästyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Mutta minä sanoin: \"Voi, Herra, Herra! Totisesti, sinä olet pettänyt tätä kansaa ja Jerusalemia, kun sanoit: \'Teillä on oleva rauha!\' Kuitenkin miekka koskee sieluun asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'Siihen aikaan sanotaan tälle kansalle ja Jerusalemille: Kuuma tuuli tulee erämaan kallioilta tytärtä, kansaani, kohti – ei viljan viskaamiseksi eikä puhdistamiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Tuuli täydessä voimassaan tulee minulta. Nyt minä myös julistan heille tuomiot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Katso, hän nousee kuin pilvet, ja hänen vaununsa ovat kuin pyörremyrsky, hänen hevosensa ovat kotkia nopeammat. Voi meitä, sillä olemme tuhon omia!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Pese sydämesi puhtaaksi pahuudesta, sinä Jerusalem, että pelastuisit. Kuinka kauan sisimmässäsi asuvat väärät ajatuksesi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Sillä sanantuojan ääni kuuluu Daanista ja onnettomuuden julistus Efraimin vuorilta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Muistuttakaa kansoja. Katso, saarnatkaa Jerusalemia vastaan: \"Piirittäjät tulevat kaukaisesta maasta ja kohottavat äänensä Juudan kaupunkeja vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Kuin pellon vartijat he piirittävät sitä ympäriinsä, koska se kapinoi minua vastaan, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Vaelluksesi ja tekosi ovat tuottaneet sinulle tämän: tämän saat pahuudestasi, sillä se on katkeraa ja koskee sydämeesi asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Voi rintaani, voi rintaani! Vääntelehdin tuskasta. Voi sydämeni kammioita! Sydämeni väräjää minussa. En voi vaieta, sillä kuulen torven äänen, sotahuudon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Hävitystä hävityksen päällä, sillä koko maa on tuhottu. Äkisti ovat telttani tuhotut ja telttakankaani revityt silmänräpäyksessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Kuinka kauan minun täytyy nähdä sotalippua ja kuulla torven ääntä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Sillä kansani on typerä. He eivät tunne minua. He ovat tyhmiä lapsia eivätkä ymmärtäväisiä. He ovat viisaita tekemään pahaa, mutta hyvää he eivät osaa tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Katselin maata, ja katso, se oli autio ja tyhjä, ja katsoin taivaalle, eikä siinä ollut valoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Katselin vuoria, ja katso, ne järisivät, ja kaikki kukkulat huojuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Katselin, ja katso, ei ollut yhtään ihmistä, ja kaikki taivaan linnut olivat paenneet pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Katselin, ja katso, hedelmätarha oli erämaana, ja kaikki sen kaupungit olivat kukistuneet Herran edessä ja hänen vihansa hehkun edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Sillä näin sanoo Herra: Koko maa tulee autioksi, vaikka en tee siitä täysin loppua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Sen tähden maa suree, ja taivaat ylhäällä pukeutuvat mustiin, sillä olen puhunut, olen päättänyt, en kadu enkä siitä peräydy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Ratsu- ja jousimiesten huutoa pakenee koko kaupunki. He menevät metsän tiheikköihin ja nousevat kallioille. Jokainen kaupunki on hylätty, eikä niissä asu kukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Mutta sinä, tuhon oma, mitä teet, kun pukeudut purppuraan, kun kaunistat itseäsi kultakoruilla ja kun suurennat silmäsi ihomaalilla? Turhaan itseäsi kaunistat. Rakastajat ovat hylänneet sinut. He etsivät henkeäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Sillä kuulen huudon, kuin synnyttäjän tuskanhuudon, vaivan, kuin ensisynnyttäjän vaivan, tytär Siionin huudon. Hän vaikeroi ja levittää kätensä: \"Voi minua, sillä sieluni menehtyy murhaajien tähden!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Kiertäkää Jerusalemin katuja, katsokaa ja tiedustelkaa, ja etsikää sen toreilta. Jos löydätte yhdenkään, jos on ainoatakaan, joka tekee oikein, joka etsii totuutta, niin annan sille anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Mutta vaikka he sanovat: \"Niin totta kuin Herra elää\", he kuitenkin vannovat väärin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Herra, eivätkö silmäsi katso uskollisuutta? Olet lyönyt heitä, mutta he eivät tunteneet kipua. Olet aivan hävittänyt heidät, mutta he eivät tahtoneet ottaa kuritusta varteen. He ovat kovettaneet kasvonsa kalliota kovemmiksi eivätkä ole tahtoneet kääntyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Minä sanoin: Sellaisia ovat vain alhaiset. He ovat typeriä, sillä he eivät tunne Herran tietä eivätkä Jumalansa oikeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Menen ylhäisten luo ja puhuttelen heitä, sillä he kyllä tuntevat Herran tien ja Jumalansa oikeuden. Mutta he olivat kaikki särkeneet ikeen ja katkaisseet siteet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Sen tähden heidät surmaa metsän leijona, aavikon susi raatelee heidät, ja pantteri väijyy heidän kaupunkejaan. Kuka ikinä niistä lähtee, se raadellaan, sillä monet ovat heidän rikoksensa ja suuri on heidän luopumustensa luku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Kuinka antaisin sinulle anteeksi? Lapsesi ovat hylänneet minut ja vannoneet niiden kautta, jotka eivät ole jumalia. Ravitsin heitä, mutta he tekivät aviorikoksen ja menivät joukolla porton huoneeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'He ovat hyvinruokittuja, kiimaisia oriita. He hirnuvat kukin lähimmäisensä vaimoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Enkö rankaisisi tällaisista, sanoo Herra, eikö sieluni kostaisi tällaiselle kansalle?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Nouskaa sen muureille ja hävittäkää, älkää kuitenkaan siitä aivan loppua tehkö. Ottakaa pois sen köynnökset, sillä ne eivät ole Herran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Sillä he ovat olleet minulle aivan uskottomat, sekä Israelin heimo että Juudan heimo, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'He ovat olleet petollisia Herraa kohtaan ja sanoneet: \"Ei se ole hän! Meitä ei kohtaa onnettomuus, emmekä tule näkemään miekkaa emmekä nälkää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Profeetat ovat tuulta. Herra, joka puhuu, ei ole heissä. Tämä kohtaa heitä itseään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Sen tähden sanoo Herra, Jumala Sebaot, näin: Koska te tällaisia olette puhuneet, niin katso, teen sanani suussasi tuleksi ja tämän kansan polttopuiksi, ja se kuluttaa heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Katso, tuon teitä vastaan, te Israelin heimo, kansan kaukaa, sanoo Herra. Se on horjumaton kansa, se on ikivanha kansa, kansa, jonka kieltä sinä et osaa ja jonka puhetta et käsitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Heidän viinensä on kuin avoin hauta, ja he ovat kaikki sankareita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'He syövät satosi ja leipäsi, syövät poikasi ja tyttäresi, syövät lampaasi ja nautasi, syövät viinipuusi ja viikunapuusi. He hävittävät miekalla varustetut kaupunkisi, joihin sinä luotat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Mutta niinäkään päivinä, sanoo Herra, en tee teistä loppua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Kun he kysyvät: \"Miksi Herra, Jumalamme, on tehnyt meille kaiken tämän?\" vastaa heille: \"Niin kuin te olette hylänneet minut ja palvelleet vieraita jumalia maassanne, niin teidän täytyy palvella muukalaisia maassa, joka ei ole teidän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Julistakaa tämä Jaakobin huoneessa ja kuuluttakaa se Juudassa sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Kuulkaa tämä, te tyhmä ja ymmärtämätön kansa, te, joilla on silmät, mutta ette näe, joilla on korvat, mutta ette kuule.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Ettekö pelkää minua, sanoo Herra, ettekö vapise edessäni, joka olen pannut hiekan meren rajaksi, ikuiseksi määräksi, jonka yli se ei pääse. Vaikka se kuohuu, se ei mahda mitään, ja vaikka sen aallot pauhaavat, ne eivät pääse sen yli?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Mutta tällä kansalla on uppiniskainen ja tottelematon sydän. He ovat poikenneet ja menneet pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'He eivät sano sydämessään: \"Pelätkäämme Herraa, Jumalaamme, joka antaa sateen, syyssateen ja kevätsateen ajallaan, ja säilyttää meille elonkorjuun määräviikot.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Pahat tekonne käänsivät nämä pois, ja syntinne estivät teitä saamasta niistä hyvää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Sillä kansassani on jumalattomia. He väijyvät, niin kuin linnunpyytäjät kyykistyvät, ja asettavat ansoja ja pyydystävät ihmisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Niin kuin häkki on täynnä lintuja, heidän huoneensa ovat täynnä petosta. Siitä he ovat tulleet suuriksi ja rikkaiksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'ovat tulleet lihaviksi ja kiiltäviksi. Myös heidän ilkeät puheensa käyvät yli kaiken määrän. He eivät aja orpojen asiaa, että nämä voittaisivat, eivätkä hanki köyhille oikeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Enkö rankaisisi näistä tällaisista, sanoo Herra, eikö sieluni kostaisi tällaiselle kansalle?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Kauheita ja hirvittäviä asioita tapahtuu maassa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'profeetat ennustavat valhetta, ja papit hallitsevat yksissä neuvoin heidän kanssaan, ja sitä kansani rakastaa. Mutta mitä teette, kun tästä tulee loppu?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Paetkaa, benjaminilaiset, Jerusalemista, puhaltakaa torveen Tekoassa ja nostakaa merkki Beet-Keremin kohdalle, sillä pohjoisesta nousee onnettomuus ja suuri hävitys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Hävitän suloisen ja hemmotellun tytär Siionin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Hänen luokseen tulee paimenia laumoineen, he pystyttävät telttansa häntä vastaan joka puolelle ja kaitsevat laumaansa kukin alallaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Pyhittäkää häntä vastaan sota. \"Nouskaa ja menkäämme puolipäivän aikaan! Voi meitä, sillä päivä painuu, sillä illan varjot pitenevät!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Nouskaa ja menkäämme yöllä ja hävittäkäämme hänen linnansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Sillä näin sanoo Herra Sebaot: Kaatakaa puita ja luokaa valli Jerusalemia vastaan. Se on kaupunki, jolle on kostettava. Siinä on pelkkää väkivaltaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Niin kuin kaivo pitää vetensä tuoreena, niin sekin pitää pahuutensa tuoreena. Väkivaltaa ja hävitystä kuuluu sieltä. Edessäni on aina kipu ja haavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Ota ojentuaksesi, Jerusalem, ettei sieluni vieraannu sinusta ja etten tee sinua autioksi, asumattomaksi maaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Näin sanoo Herra Sebaot: Israelin jäännöksestä pidetään jälkikorjuu kuin viinipuusta. Ojenna kätesi köynnöksiä kohti kuin viininkorjaaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Kenelle puhuisin, ketä varoittaisin, että he kuulisivat? Katso, heidän korvansa ovat ympärileikkaamattomat, he eivät voi kuunnella. Katso, Herran sana on tullut heille pilkaksi, se ei kelpaa heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Olen täynnä Herran vihaa, en jaksa sitä pidättää. Vuodata se lapsiin kadulla, myös nuorukaisjoukkoon. Sillä mies vangitaan vaimonsa kanssa ja vanhus päiviensä täydessä määrässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Heidän talonsa joutuvat vieraille, myös pellot ja vaimot, sillä ojennan käteni maan asukkaita vastaan, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Sillä kaikki pienistä suuriin pyytävät väärää voittoa, ja kaikki, niin profeetat kuin papitkin, harjoittavat petosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'He parantavat kansani vamman kevytmielisesti sanoen: \"Rauha, rauha!\" vaikka rauhaa ei ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'He joutuvat häpeään, sillä he ovat tehneet kauhistuksia, mutta heillä ei ole häpeän tuntoa eivätkä he osaa hävetä. Sen tähden he kaatuvat kaatuvien joukkoon ja sortuvat koston päivänä, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Näin on Herra sanonut: \"Astukaa teille ja katsokaa ja kysykää muinaisia polkuja, kysykää, mikä on hyvä tie, ja vaeltakaa sitä, niin löydätte levon sieluillenne.\" Mutta he vastasivat: \"Emme vaella.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Olen asettanut teille vartijat: \"Kuunnelkaa torven ääntä.\" Mutta he vastasivat: \"Emme kuuntele.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Sen tähden kuulkaa, te kansat, ja tiedä, seurakunta, mitä heille tapahtuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Kuule, maa! Katso, minä tuotan onnettomuuden tälle kansalle, heidän hankkeittensa hedelmän, sillä he eivät ole kuunnelleet sanojani, vaan ovat hylänneet lakini.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Mitä on minulle suitsutus, joka tulee Sabasta, ja paras kalmoruoko kaukaisesta maasta? Polttouhrinne eivät ole minulle otollisia, eivätkä teurasuhrinne minulle kelpaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Sen tähden, näin sanoo Herra: Katso, panen tälle kansalle kompastuskiviä, joihin he kompastuvat, isät ja pojat yhdessä, ja naapuri hukkuu naapurinsa kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Näin sanoo Herra: Katso, kansa tulee pohjoisesta maasta, suuri pakanakansa nousee maan ääriltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'He käyttävät jousta ja keihästä, ovat julmat ja armahtamattomat. Heidän äänensä on kuin pauhaava meri, ja he ratsastavat hevosilla, varustettuina kuin soturi taisteluun sinua vastaan, tytär Siion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Kun kuulemme siitä sanoman, kätemme herpoavat, ahdistus valtaa meidät ja tuska kuin synnyttäjän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Älkää menkö vainiolle, älkää vaeltako tiellä, sillä vihollisen miekka – kauhistus on kaikkialla!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Tytär, kansani! Kääriydy säkkiin, vieriskele tuhkassa, pidä valittajaiset, niin kuin ainoaa poikaa itketään, katkerat valittajaiset, sillä äkkiarvaamatta käy kimppuumme hävittäjä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Olen asettanut sinut kansani koettelijaksi, suojavarustukseksi, että oppisit tuntemaan ja koettelisit heidän vaelluksensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Kaikki he ovat niskoittelevia kapinoitsijoita ja liikkuvat panettelijoina. He ovat vaskea ja rautaa ja ovat kaikki kelvottomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Palkeet puhkuvat, tulesta lähtee vain lyijyä. Turhaan on heitä sulateltu ja sulateltu: pahat eivät ole erottuneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Hylkyhopeaksi heitä sanotaan, sillä Herra on heidät hylännyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Sana, joka tuli Jeremialle Herralta:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, '\"Seiso Herran huoneen portilla ja saarnaa sieltä tämä sana ja sano: Kuulkaa Herran sana, koko Juuda, te jotka tulette näistä porteista kumartaen rukoilemaan Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Näin sanoo Herra Sebaot, Israelin Jumala: Parantakaa vaelluksenne ja tehkää hyviä tekoja, niin tulette asumaan tässä paikassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Älkää luottako valheen sanoihin, kun sanotaan: \'Tämä on Herran temppeli, Herran temppeli, Herran temppeli!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Vaan jos te todella parannatte vaelluksenne ja tekonne, jos te todella teette oikeuden lähimmäisillenne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'ette sorra muukalaista, orpoa ja leskeä, ette vuodata viatonta verta tässä paikassa ettekä seuraa muita jumalia itsellenne onnettomuudeksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'annan teidän asua tässä paikassa, maassa, jonka olen antanut isillenne kauan sitten ja pitkäksi aikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Katso, te luotatte valheen sanoihin, joista ei ole hyötyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Te varastatte, tapatte, rikotte avion, vannotte väärin, poltatte uhreja Baalille ja seuraatte vieraita jumalia, joita ette tunne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Te tulette ja astutte eteeni tähän huoneeseen, joka on otettu nimiini, ja sanotte: \'pelastumme\' – tehdäksenne yhä kaikkia näitä kauhistuksia!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Ryövärien luolaksiko te katsotte tämän huoneen, joka on otettu nimiini? Katso, sellaiseksi minäkin olen sen havainnut, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Menkääpä asuinpaikkaani, joka oli Siilossa, jossa ensin annoin nimeni asua, ja katsokaa, mitä olen sille tehnyt kansani Israelin pahuuden tähden!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Koska olette nyt kaikkia näitä tekoja tehneet, sanoo Herra, ettekä ole kuulleet, vaikka varhaisesta alkaen olen teille puhunut, koska ette vastanneet, vaikka teille huusin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'niin teen tälle huoneelle, joka on otettu nimiini, johon te luotatte, ja tälle paikalle, jonka olen antanut teille ja teidän isillenne, samoin kuin olen tehnyt Siilolle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'ja heitän teidät pois kasvojeni edestä, niin kuin olen heittänyt pois kaikki veljenne, kaikki Efraimin jälkeläiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Mutta sinä älä rukoile tämän kansan puolesta, älä kohota heidän puolestaan huutoa ja rukousta äläkä niillä ahdista minua, sillä en kuule sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Etkö näe, mitä he tekevät Juudan kaupungeissa ja Jerusalemin kaduilla?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Lapset kokoavat puita, isät sytyttävät tulen, ja vaimot sotkevat taikinaa valmistaaksensa uhrikakkuja taivaan kuningattarelle, ja he vuodattavat juomauhreja muille jumalille tuottaakseen minulle mielipahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Minulleko he tuottavat mielipahaa, sanoo Herra, eivätkö pikemmin itselleen, omaksi häpeäkseen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Sen tähden, näin sanoo Herra, Herra: Katso, vihani ja kiivauteni on vuotava tämän paikan ylle, ihmisten, eläinten, kedon puiden ja maan hedelmän ylle, ja se palaa sammumatta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Näin sanoo Herra Sebaot, Israelin Jumala: \"Lisätkää polttouhrinne teurasuhreihinne ja syökää lihaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Sillä en puhunut enkä antanut käskyä isillenne poltto- ja teurasuhrista silloin, kun vein heidät pois Egyptin maasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'vaan näin käskin heitä ja sanoin: Kuulkaa ääntäni, niin minä olen Jumalanne ja te olette kansani; ja vaeltakaa aina sitä tietä, jota käsken teidän vaeltaa, jotta teidän kävisi hyvin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Mutta he eivät kuulleet eivätkä kallistaneet korvaansa, vaan vaelsivat oman neuvonsa mukaan, pahan sydämensä paatumuksessa, ja käänsivät minulle selkänsä eivätkä kasvojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Siitä päivästä, jona isänne lähtivät Egyptin maasta, aina tähän päivään asti olen lähettänyt teille kaikki palvelijani, profeetat – lähettänyt varhaisesta alkaen, päivä päivältä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Mutta he eivät kuulleet minua eivätkä kallistaneet minulle korvaansa, vaan he olivat niskureita ja tekivät enemmän pahaa kuin heidän isänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Mutta kun sinä puhut heille kaiken tämän, niin he eivät kuule sinua, ja kun sinä julistat heille, he eivät sinulle vastaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Sen tähden sano heille: Tämä on kansa, joka ei kuullut Herran, Jumalansa, ääntä eikä ottanut opetusta vastaan. Kadonnut on totuus ja hävinnyt heidän suustaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Leikkaa hiuksesi ja heitä ne pois ja viritä kallioilla itkuvirsi, sillä Herra on hylännyt ja syössyt pois vihansa alaisen sukupolven.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Sillä Juudan miehet ovat tehneet sen, mikä on silmissäni paha, sanoo Herra. He ovat asettaneet iljetyksensä temppeliin, joka on otettu nimiini, ja saastuttaneet sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'He ovat rakentaneet Toofetin uhrikukkulat Ben-Hinnomin laaksoon polttaakseen tulessa poikiaan ja tyttäriään, mitä en ole käskenyt ja mikä ei ole mieleeni noussut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Sen tähden, katso, päivät tulevat, sanoo Herra, jolloin ei enää sanota \'Toofet\' ja \'Ben-Hinnomin laakso\', vaan \'Murhalaakso\', ja Toofetiin haudataan, kun muualla ei ole tilaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'Tämän kansan ruumiit joutuvat taivaan lintujen ja maan eläinten ruuaksi, eikä kukaan pelota niitä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Lopetan Juudan kaupungeista ja Jerusalemin kaduilta riemu- ja ilohuudot, huudon yljälle ja huudon morsiamelle, sillä maa on tuleva raunioiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, '\"Siihen aikaan, sanoo Herra, viedään Juudan kuningasten luut, sen ruhtinaiden luut, pappien luut, profeettojen luut ja Jerusalemin asukasten luut pois heidän haudoistaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'ja hajotetaan auringon, kuun ja kaiken taivaan joukon eteen, joita he rakastivat ja palvelivat, joita he seurasivat, etsivät ja kumartaen rukoilivat. Niitä ei koota eikä haudata, vaan ne tulevat maan lannaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Kuolema on oleva halutumpi kuin elämä koko sille jäännökselle, joka jää jäljelle tästä pahasta sukukunnasta, kaikissa paikoissa, mihin karkotan nämä jäljelle jääneet, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Sano heille: Näin sanoo Herra: Eivätkö ne, jotka lankeavat, nouse jälleen? Eikö se, joka kääntyy pois, palaa takaisin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Miksi tämä kansa, Jerusalem, kääntyy pois pysyvässä luopumuksessa? Miksi he pitävät kiinni petoksesta ja kieltäytyvät palaamasta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Olen tarkkaillut ja kuunnellut: he puhuvat sitä, mikä ei ole oikein; kukaan ei kadu pahuuttaan sanoen: Mitä olen tehnyt! Kaikki he kääntyvät juoksemaan suuntaansa, niin kuin ori kiitää taisteluun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Haikarakin taivaalla tietää aikansa. Metsäkyyhkynen, pääskynen ja kurki pitävät vaarin tuloajastaan, mutta kansani ei tunne Herran tuomiota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Kuinka saatatte sanoa: \'Olemme viisaita, ja Herran laki on kanssamme\'? Totisesti! Katso, valheen työtä on tehnyt kirjanoppineiden valhekynä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Viisaat saavat häpeän, kauhistuvat ja heidät vangitaan. Katso, he ovat hylänneet Herran sanan – mitä viisautta heillä on?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Sen tähden annan heidän vaimonsa vieraille ja heidän peltonsa valloittajille. Sillä kaikki pienimmästä suurimpaan pyytävät väärää voittoa, kaikki, sekä profeetat että papit harjoittavat petosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'He parantavat pinnallisesti tyttären, kansani, vamman, sanoen: \'Rauha, rauha!\' vaikka ei ole rauhaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'He joutuvat häpeään, sillä he ovat tehneet kauhistuksia. Heillä ei ole myöskään häpeän tuntoa eivätkä he osaa nöyrtyä. Sen tähden he kaatuvat kaatuvien joukkoon, sortuvat, kun heidän rangaistuksensa tulee, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Totisesti tempaan heidät pois, sanoo Herra. Rypäleitä ei ole viinipuussa eikä viikunoita viikunapuussa, ja lehtikin lakastuu. Se, mitä olen heille antanut, menee heiltä pois.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, '\"Miksi me istumme? Kokoontukaa! Menkäämme varustettuihin kaupunkeihin, ja olkaamme siellä hiljaa! Sillä Herra, Jumalamme, hiljentää meidät ja juottaa meille myrkkyvettä, sillä olemme tehneet syntiä Herraa vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, '\"Odotetaan rauhaa, mutta hyvää ei tule, ja paranemisen aikaa, mutta katso, tulee kauhu!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Daanista kuuluu hänen hevostensa korskunta, hänen oriittensa hirnunnasta vapisee koko maa. He tulevat ja syövät maan ja kaiken, mitä siinä on, kaupungin ja siinä asuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Sillä katso, lähetän keskellenne käärmeitä ja myrkkyliskoja, joita ei voi lumota, ja ne purevat teitä, sanoo Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Murheeseeni ei ole virvoitusta. Sydämeni on sairas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Katso, tyttären, kansani, avunhuuto kuuluu kaukaisesta maasta: \"Eikö Herra ole Siionissa, eikö siellä ole sen kuningas?\" Miksi he ovat vihoittaneet minut jumalankuvillaan, muukalaisten turhilla jumalilla?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Ohi on elonkorjuuaika, loppunut on kesä, mutta me emme ole saaneet apua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Tyttären, kansani, murtumisen tähden olen murtunut, kuljen mustissa, murhe on minut vallannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Eikö Gileadissa ole balsamia, eikö siellä ole parantajaa? Vai miksi tyttären, kansani, haavat eivät kasva umpeen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 23, 'Jos joku antaisi päähäni vettä ja tekisi silmäni kyynelten lähteeksi, itkisin päivät ja yöt tyttären, kansani, kaatuneita!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Oi, jospa joku antaisi minulle erämaassa matkamiehen yömajan, jättäisin kansani ja vaeltaisin pois heidän luotaan! Sillä he ovat kaikki avionrikkojia ja uskottomien joukko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'He jännittävät kielensä kuten jousen puhumaan valhetta, eivätkä käytä maassa valtaansa totuuden hyväksi, sillä he menevät pahuudesta pahuuteen, mutta minua he eivät tunne, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Varokaa kukin lähimmäistänne, älkää luottako yhteenkään veljeen, sillä jokainen veli pettämällä pettää ja jokainen lähimmäinen liikkuu panettelijana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'He pettävät toinen toistaan eivätkä puhu totta. He ovat totuttaneet kielensä puhumaan valhetta ja tehneet vääryyttä väsyksiin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Asut vilpin keskellä. Vilpillisyydessään he eivät tahdo tuntea minua, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Sen tähden, näin sanoo Herra Sebaot: Katso, tutkin heidät ja koettelen heitä, sillä mitä muuta voisin tehdä tyttären, kansani, tähden?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Tappava nuoli on heidän kielensä, vilppiä se puhuu. Suullaan he puhuvat rauhaa lähimmäisensä kanssa, mutta sisimmässään he punovat juoniaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Enkö näistä tällaisista rankaisisi heitä, sanoo Herra, eikö sieluni kostaisi tällaiselle kansalle?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Nostan vuorilla itkun ja valituksen. Erämaan laitumien tähden viritän itkuvirren. Sillä ne ovat poltetut, ei kukaan siellä kulje, eivätkä ne kuule karjan ääntä. Paenneet ovat taivaan linnut ja eläimet. Ne ovat menneet pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Teen Jerusalemin kivikasaksi, sakaalien asunnoksi, ja Juudan kaupungit teen autioiksi, joissa ei ole asukkaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Kuka on viisas mies, joka tämän ymmärtää ja jolle Herran suu on puhunut, että hän sen ilmoittaisi? Minkä tähden maa on hävitetty ja poltettu kuin erämaa, jossa ei kukaan kulje?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Herra sanoi: \"Sen tähden, että he ovat hylänneet lakini, jonka annoin heille, eivätkä ole kuulleet ääntäni eivätkä vaeltaneet sen mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'vaan ovat vaeltaneet sydämensä paatumuksessa ja seuranneet baaleja, niin kuin heidän isänsä olivat heille opettaneet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'sen tähden Herra Sebaot, Israelin Jumala, sanoo näin: Katso, syötän heille, tälle kansalle, koiruohoa ja juotan heille myrkkyvettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Hajotan heidät kansojen sekaan, joita eivät he eivätkä heidän isänsä ole tunteneet, ja lähetän heidän peräänsä miekan, kunnes teen heistä lopun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'Näin sanoo Herra Sebaot: Ottakaa vaari, kutsukaa itkijänaisia tulemaan tänne. Lähettäkää hakemaan taitavia naisia, jotta he tulisivat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'kiiruhtaisivat ja virittäisivät meistä valitusvirren, niin että silmämme vuotaisivat kyyneliä ja silmäripsistämme tippuisi vesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Sillä valitushuuto kuuluu Siionista: Kuinka olemmekaan hävitetyt! Olemme joutuneet suureen häpeään, sillä meidän täytyy jättää maa, sillä kukistuneet ovat asuntomme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Kuulkaa siis, te naiset, Herran sana, ottakoon korvanne vastaan hänen suunsa puheen. Opettakaa tyttärillenne valitusvirsi ja toisillenne itkuvirsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Sillä kuolema on noussut sisään ikkunoistamme ja tullut palatseihimme tuhotakseen kadulta lapset ja toreilta nuorukaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Puhu: Näin sanoo Herra: Ihmisten ruumiita makaa maassa kuin lantaa pelloilla, kuin lyhteitä leikkaajan jäljessä, eikä ole niille korjaajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Näin sanoo Herra: Älköön viisas kerskuko viisaudestaan, älköön voimakas kerskuko voimastaan älköönkä rikas kerskuko rikkaudestaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'vaan joka kerskaa, kerskatkoon siitä, että hän on ymmärtäväinen ja tuntee minut ja että minä, Herra, teen laupeuden, oikeuden ja vanhurskauden maan päällä. Sillä sellaisiin miellyn, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Katso, päivät tulevat, sanoo Herra, jolloin rankaisen kaikkia, jotka ovat ympärileikattuja, mutta kuitenkin ympärileikkaamattomia:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Egyptiä, Juudaa, Edomia, ammonilaisia, Mooabia ja kaikkia, joiden hiukset on ohimoilta ajettu, jotka asuvat erämaassa, sillä kaikki pakanakansat ovat ympärileikkaamattomia ja koko Israelin heimo on sydämeltään ympärileikkaamaton.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Kuulkaa sana, jonka Herra on puhunut teitä vastaan, te Israelin heimo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Näin sanoo Herra: \"Älkää opetelko kulkemaan pakanoiden tietä älkääkä kauhistuko taivaan merkkejä, sillä pakanat niitä kauhistuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Sillä kansat palvovat turhia jumalia. Nehän ovat puuta, joka hakataan metsästä, puusepän kätten tekemiä, kirveellä veistettyjä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Ne koristetaan hopealla ja kullalla sekä kiinnitetään nauloilla ja vasaroilla, niin etteivät ne horju.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Ne ovat kuin linnunpelätin kurkkumaalla. Ne eivät puhu, kantamalla täytyy niitä kantaa, sillä ne eivät kävele. Älkää pelätkö niitä, sillä ne eivät tee pahaa, mutta eivät ne myöskään tee hyvää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Ei ole ketään vertaistasi, Herra. Sinä olet suuri, ja suuri on nimesi voimassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Kuka ei sinua pelkäisi, sinä kansojen kuningas? Sillä siihen sinä olet arvollinen. Kaikissa kansojen viisaissa ja kaikissa heidän valtakunnissaan ei ole näet ketään sinun vertaistasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'He ovat kaikki typeriä ja tyhmiä, kasvatettu palvomaan turhia jumalia, jotka ovat puuta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'ohueksi taottua hopeaa, joka tuodaan Tarsiista, ja Uufaan kultaa, mestarin ja kultasepän kätten tekoa. Punasinistä ja punaista purppuraa on niiden puku. Taitavien tekoa ne ovat kaikki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Mutta Herra on tosi Jumala. Hän on elävä Jumala ja iankaikkinen kuningas. Hänen vihastaan järisee maa, eivätkä kansat kestä hänen suuttumustaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Sanokaa heille näin: Jumalat, jotka eivät ole tehneet taivasta eivätkä maata, katoavat maan päältä ja taivaan alta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Hän on tehnyt maan voimallaan, vahvistanut maanpiirin viisaudellaan ja levittänyt taivaat taidollaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Kun hän antaa äänensä kuulua, vetten pauhu käy taivaalla, ja hän nostaa pilvet maan ääristä, tekee salamat ja sateen ja tuo tuulen sen varastoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Typerä on jokainen ihminen, tietoa vailla, häpeän saa jokainen seppä veistetystä kuvasta, petosta on hänen valamansa kuva, eikä niissä ole henkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Turhuutta ne ovat, naurettavia tekeleitä. Kun niiden rangaistus tulee, ne hukkuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Näiden kaltainen ei ole Jaakobin osa, sillä hän on kaiken Luoja, ja Israel on hänen perintösukunsa: Herra Sebaot on hänen nimensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Kokoa omaisuutesi maasta pois, sinä, joka istut piiritettynä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Sillä näin sanoo Herra: Katso, tällä kertaa linkoan pois maan asukkaat ja ahdistan heitä, niin että saavat tarpeekseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Voi minua vammani tähden! Kipeä on haavani; mutta minä sanon: Tämä on minun vaivani, minun on se kannettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Telttani on hävitetty, ja kaikki telttaköyteni ovat katkotut. Lapseni ovat lähteneet luotani, eikä niitä enää ole. Ei ole enää, kuka telttani pystyttäisi ja nostaisi seinieni kankaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Sillä paimenet olivat järjettömiä eivätkä etsineet Herraa. Sen tähden he eivät menestyneet, vaan koko heidän laumansa hajotettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Ääni kuuluu! Katso, se tulee, suuri pauhina pohjoisesta maasta, tekemään Juudan kaupungit autioiksi, sakaalien asunnoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Tiedän, Herra, ettei ihmisen tie ole hänen vallassaan, eikä miehen vallassa, kuinka hän vaeltaa ja askeleensa ohjaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Kurita minua, Herra, mutta oikeuden mukaan, äläkä vihassasi, ettet tekisi minua mitättömäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Vuodata vihasi pakanoiden päälle, jotka eivät sinua tunne, ja sukukuntien yli, jotka eivät huuda avuksi nimeäsi. Sillä he ovat syöneet Jaakobin, ovat syöneet hänet ja tehneet hänestä lopun, ja tehneet autioksi hänen asuinsijansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Sana, joka tuli Herralta Jeremialle ja kuului näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, '\"Kuulkaa tämän liiton sanat ja puhukaa ne Juudan miehille ja Jerusalemin asukkaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Sano heille: Näin sanoo Herra, Israelin Jumala: Kirottu olkoon se mies, joka ei kuule tämän liiton sanoja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'jonka annoin käskynä isillenne silloin, kun vein heidät pois Egyptin maasta, rautapätsistä, sanoen: Kuulkaa ääntäni ja tehkää kaikki niin, kuin käsken teidän tehdä, niin olette kansani ja minä olen Jumalanne');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'ja pidän valan, jonka olen vannonut isillenne luvaten antaa heille maan, joka vuotaa maitoa ja hunajaa, niin kuin se teillä tänäkin päivänä on.\" Vastasin ja sanoin: \"Aamen, Herra!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Herra sanoi minulle: \"Saarnaa kaikki nämä sanat Juudan kaupungeissa ja Jerusalemin kaduilla ja sano: Kuulkaa tämän liiton sanat ja noudattakaa niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Sillä totisesti varoitin isiänne silloin, kun johdatin heidät pois Egyptin maasta, ja olen varoittanut varhaisesta alkaen tähän päivään saakka sanoen: \'Kuulkaa ääntäni.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Mutta he eivät kuulleet eivätkä korvaansa kallistaneet, vaan vaelsivat kukin pahan sydämensä paatumuksessa. Tuotin heidän päälleen kaikki tämän liiton sanat, joita olin käskenyt heidän noudattaa, mutta joita he eivät noudattaneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Herra sanoi minulle: \"Juudan miesten ja Jerusalemin asukkaiden keskuudessa on salaliitto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'He ovat kääntyneet takaisin ensimmäisten esi-isiensä pahoihin tekoihin, niiden, jotka kieltäytyivät kuulemasta sanojani, ja he ovat seuranneet muita jumalia ja palvelleet niitä. Israelin heimo ja Juudan heimo ovat rikkoneet liittoni, jonka tein heidän isiensä kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Sen tähden, näin sanoo Herra: Katso, tuotan heille onnettomuuden, josta heillä ei ole pääsyä; ja kun he minua huutavat, en kuule heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Juudan kaupungit ja Jerusalemin asukkaat menevät ja huutavat avuksi niitä jumalia, joille he ovat polttaneet uhreja, mutta ne eivät pelasta heitä heidän onnettomuutensa aikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Sillä yhtä paljon kuin sinulla on kaupunkeja, on sinulla, Juuda, jumalia, ja yhtä paljon kuin Jerusalemissa on katuja, olette pystyttäneet alttareita häpeäjumalalle, alttareita polttaaksenne uhreja Baalille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Mutta älä sinä rukoile tämän kansan puolesta, älä kohota heidän puolestaan huutoa ja rukousta, sillä en kuule, kun he minua avuksi huutavat onnettomuutensa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Mitä tekee rakkaani temppelissäni? Onko hänellä paljon juonia? Ottaako uhriliha sinusta pois pahuutesi? Silloin riemuitsisit!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, '\'Vihreä öljypuu, ihana, kaunishedelmäinen\': sillä nimellä Herra kutsui sinua. Suuren jyrinän pauhatessa hän sytytti sen tuleen, ja sen oksat turmeltuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Mutta Herra Sebaot, joka sinut istutti, on päättänyt osaksesi onnettomuuden Israelin heimon ja Juudan heimon pahuuden tähden, jota he ovat harjoittaneet ja jolla ovat vihoittaneet minut polttamalla uhreja Baalille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Herra ilmoitti minulle, ja sain tietää. Silloin näytit minulle heidän hankkeensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Silloin olin kuin kesy karitsa, joka viedään teurastettavaksi, enkä ollut tiennyt heidän pitäneen neuvoa minua vastaan: \"Tuhotkaamme puu hedelmineen, hävittäkäämme hänet elävien maasta, niin ettei hänen nimeään enää muisteta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Mutta Herra Sebaot on vanhurskas tuomari, joka tutkii munuaiset ja sydämen. Salli minun nähdä sinun kostavan heille, sillä haltuusi olen uskonut asiani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Sen tähden, näin sanoo Herra Anatotin miehistä, jotka väijyvät henkeäsi sanoen: \"Älä profetoi Herran nimeen, ettet kuolisi kättemme kautta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'Sen tähden, näin sanoo Herra Sebaot: \"Katso, kostan heille. Heidän nuoret miehensä kuolevat miekkaan, ja heidän poikansa ja tyttärensä kuolevat nälkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'Heistä ei jää jäännöstä, sillä tuotan onnettomuuden Anatotin miehille heidän kostonsa vuotena.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Sinä, Herra, olet vanhurskas, käyn oikeutta sinua vastaan. Kuitenkin kysyn sinulta, mikä on oikeus. Miksi jumalattomien tie menestyy? Miksi kaikki uskottomat saavat elää rauhassa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Sinä istutat heidät, he myös juurtuvat; he kasvavat, kantavat myös hedelmää. Heidän suussaan olet lähellä, mutta kaukana heidän sisimmästään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Mutta sinä, Herra, tunnet minut, näet minut ja tutkit sydämeni, millainen se on edessäsi. Tempaa heidät pois kuin lampaat teuraiksi ja vihi heidät tapon päivää varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Kuinka kauan täytyy maan surra ja kaiken kedon ruohon kuivua? Eläimet ja linnut hukkuvat siinä asuvien pahuuden tähden, sillä nämä sanovat: \"Hän ei tule näkemään loppuamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, '\"Sillä jos juokset jalkamiesten kanssa ja ne väsyttävät sinut, kuinka kävisit kilpaan hevosten kanssa? Mutta jos sinä vaarattomalla maalla oletkin turvassa, kuinka sinun käy Jordanin rantatiheikössä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Sillä omat veljesikin ja isäsi huone ovat petollisia sinua kohtaan. Hekin huutavat täysin voimin jälkeesi. Älä usko heitä, vaikka he puhuttelevat sinua ystävällisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Olen hylännyt huoneeni ja jättänyt perintöosani. Olen antanut sieluni rakkaimman hänen vihollistensa käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Hän, perintöosani, oli minulle kuin leijona metsässä. Hän karjui minua vastaan, sen tähden minä vihastuin häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Onko perintöosani kirjava petolintu, jonka ympärillä on petolintuja? Menkää, kootkaa kaikki kedon eläimet ja tuokaa ne ruualle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Monet paimenet ovat turmelleet viinitarhani, tallanneet peltoni, tehneet ihanan peltoni autioksi erämaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Se on tehty autioksi, ja se suree edessäni autiona. Koko maa on hävitetty, sillä ei ollut ketään, joka olisi pannut sitä sydämelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Kaikkien erämaan kukkuloiden yli tulivat hävittäjät, sillä Herran miekka syö maan toisesta äärestä toiseen, eikä millään lihalla ole rauhaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'He ovat kylväneet vehnää ja niittäneet ohdakkeita. He ovat nähneet vaivaa näännyksiin asti saamatta hyötyä. Niinpä saakaa häpeä sadostanne Herran vihan hehkun tähden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Näin sanoo Herra kaikista pahoista naapureistani, jotka koskevat siihen perintöosaan, minkä olen antanut kansalleni Israelille: \"Katso, minä tempaan heidät pois heidän maastaan, ja Juudan heimon tempaan pois heidän keskeltään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Mutta tapahtuu, että sen jälkeen kun olen temmannut heidät pois, jälleen armahdan heitä ja palautan heidät, kunkin perintöosaansa ja jokaisen maahansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Jos he oppivat kansani tiet, niin että vannovat nimeeni: \'Niin totta kuin Herra elää\', niin kuin he opettivat kansaani vannomaan Baalin kautta, niin heidät rakennetaan kansani keskuuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Mutta jos he eivät kuule, niin minä totisesti tempaan pois ja hukutan sellaisen kansan, sanoo Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Herra sanoi minulle näin: \"Mene ja osta itsellesi pellavavyö ja pane se vyötäisillesi, mutta älä laske sitä veteen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Ostin vyön Herran sanan mukaan ja panin sen vyötäisilleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Herran sana tuli minulle toisen kerran, tämä sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, '\"Ota vyö, jonka ostit ja joka on vyötäisilläsi, ja nouse, mene Eufratille ja kätke se siellä kallion koloon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Menin ja kätkin sen Eufratille, niin kuin Herra oli käskenyt minun tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Pitkän ajan kuluttua Herra sanoi minulle: \"Nouse, mene Eufratille ja ota vyö, jonka käskin sinun kätkeä sinne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Menin Eufratille, kaivoin ja otin vyön siitä paikasta, johon olin sen kätkenyt. Katso, vyö oli turmeltunut eikä kelvannut mihinkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, '\"Näin sanoo Herra: Samalla tavoin tuotan turmion Juudan ylpeydelle ja Jerusalemin suurelle ylpeydelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Tämä paha kansa, joka ei tahdo kuulla sanojani, joka vaeltaa sydämensä paatumuksessa, seuraa muita jumalia, palvelee ja kumartaa niitä, tulee tämän vyön kaltaiseksi, joka ei kelpaa mihinkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Sillä niin kuin vyö liittyy miehen vyötäisiin, niin liitin koko Israelin heimon ja koko Juudan heimon itseeni, sanoo Herra, että se olisi kansani, minulle maineeksi, ylistykseksi ja kirkkaudeksi; mutta he eivät totelleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Sen tähden sano heille tämä sana: Näin sanoo Herra, Israelin Jumala: Jokainen leili täytetään viinillä. Mutta jos he sanovat sinulle: \'Emmekö tiedä, että jokainen leili täytetään viinillä?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'sano heille: Näin sanoo Herra: Katso, täytän kaikki tämän maan asukkaat, kuninkaat, jotka istuvat Daavidin valtaistuimella, papit ja profeetat ja kaikki Jerusalemin asukkaat päihtymyksellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'Murskaan heidät toisiaan vasten, isät ja lapset yhdessä, sanoo Herra. En sääli, en säästä enkä armahda, niin että jättäisin heidät hävittämättä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Kuulkaa, ottakaa korviinne, älkää ylpeilkö, sillä Herra on puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Antakaa Herralle, Jumalallenne, kunnia, ennen kuin tulee pimeä ja jalkanne loukkaantuvat vuoriin hämärässä. Silloin odotatte valoa, mutta hän muuttaa sen kuoleman varjoksi, tekee sen synkeydeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Mutta ellette kuule tätä, niin sieluni salassa itkee sellaista ylpeyttä, itkee katkerasti, ja silmäni vuotavat kyyneliä, kun Herran lauma viedään vankeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, '\"Sano kuninkaalle ja kuningattarelle: Istukaa alhaiselle sijalle, sillä päästänne on pudonnut kunnian kruununne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Negevin kaupungit ovat suljetut, eikä ole avaajaa. Koko Juuda on viety karkotukseen, karkotukseen koko kansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Nostakaa silmänne ja katsokaa, ne tulevat pohjoisesta. Missä on lauma, joka oli annettu haltuusi, nuo lampaasi, kunniasi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Mitä sanot, kun hän kostaa sinulle? Olet opettanut heidät päälliköiksi. Eivätkö tuskat kourista sinua kuin synnyttävää vaimoa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Mutta jos sanot sydämessäsi: \'Miksi minulle on näin käynyt?\' – suuren syntisi tähden liepeesi kohotettiin ja tehtiin väkivaltaa kantapäillesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Voiko kuusilainen muuttaa ihonsa ja pantteri pilkkunsa? Voitteko te tehdä hyvää, te pahantekoon tottuneet?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Hajotan heidät kuin oljenkorret erämaan tuuleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Tämä on arpasi, mitattu osasi minulta, sanoo Herra, koska olet unohtanut minut ja luottanut valheeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Niinpä minäkin nostan sinulta liepeet kasvoillesi, ja häpeäsi näkyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Olen nähnyt aviorikoksesi, hirnumisesi, haureutesi ja iljetyksesi kedon kukkuloilla. Voi sinua, Jerusalem! Et puhdistu, et vielä pitkään aikaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Herran sana, joka tuli Jeremialle kuivuuden tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, '\"Juuda murehtii, sen portit murtuvat ja maatuvat mustiksi, ja Jerusalemista nousee valitushuuto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Heidän ylimyksensä lähettävät alaisiaan noutamaan vettä. Nämä tulevat kaivoille, eivät löydä vettä, palaavat astiat tyhjinä, ovat pettyneitä ja häpeissään ja peittävät päänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Viljelysmaan tähden, joka halkeilee, kun ei ole satanut maassa, viljelijät ovat pettyneinä ja peittävät päänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Peurakin poikii kedolla ja hylkää vasansa, kun ei ole mitään vihantaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Villiaasit seisovat kukkuloilla, haukkovat ilmaa kuin sakaalit. Niiden silmät ovat voipuneet, kun ei ole ruohoa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Vaikka pahat tekomme todistavat meitä vastaan, tee työsi, Herra, nimesi tähden, sillä luopumuksemme ovat monet ja sinua vastaan olemme tehneet syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Sinä Israelin toivo, sen vapahtaja ahdingon aikana, minkä tähden olet kuin muukalainen maassa, kuin ohikulkija, joka poikkeaa vain yöpyäkseen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Minkä tähden olet kuin kauhistunut mies, kuin sankari, joka ei voi pelastaa? Kuitenkin sinä olet keskellämme, Herra, ja olemme otetut sinun nimiisi. Älä jätä meitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Näin sanoo Herra tästä kansasta: Noin he mielellään harhailevat eivätkä pidätä jalkojaan. Herra ei mielly heihin. Hän muistaa nyt heidän pahat tekonsa ja kostaa heidän syntinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Herra sanoi minulle: \"Älä rukoile tämän kansan puolesta, sen hyväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Vaikka he paastoavat, en kuule heidän huutoaan, ja vaikka he uhraavat polttouhreja ja ruokauhreja, en heihin mielly, vaan miekalla, nälällä ja rutolla minä heidät lopetan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Sanoin: \"Voi, Herra, Herra! Katso, profeetat sanovat heille: \'Ette tule näkemään miekkaa ettekä kärsimään nälkää, vaan annan teille vakaan rauhan tässä paikassa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Mutta Herra sanoi minulle: \"Valhetta ennustavat profeetat nimessäni. En ole lähettänyt heitä, en käskenyt heitä enkä puhunut heille. Valhenäkyjä, turhia ennustuksia ja oman sydämensä petosta he ennustavat teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Sen tähden, näin sanoo Herra profeetoista, jotka ennustavat nimessäni, vaikka minä en ole heitä lähettänyt, ja jotka sanovat, että miekka ja nälkä eivät tule tähän maahan: miekkaan ja nälkään hukkuvat nämä profeetat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Myös kansa, jolle he ennustavat, suistuu Jerusalemin kaduilla nälkään ja miekkaan, eikä kukaan heitä hautaa – ei heitä, ei heidän vaimojaan, poikiaan eikä tyttäriään. Vuodatan heidän pahuutensa heidän päälleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Sano heille tämä sana: Silmistäni vuotavat kyyneleet yötä päivää eivätkä lakkaa. Sillä neitsyt, tytär, kansani, on kovin runneltu suurta kipua tuovalla iskulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Jos kedolle lähden, katso – miekan lävistämiä! Jos tulen kaupunkiin, katso, nälkään nääntyviä! Sillä sekä profeetat että papit kiertävät maata eivätkä tiedä mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Oletko totisesti hylännyt Juudan, kammoaako sielusi Siionia? Minkä tähden olet lyönyt meitä, niin ettemme voi parantua? Odotetaan rauhaa, mutta hyvää ei tule, paranemisen aikaa, mutta katso, tulee kauhu!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Herra, me tunnemme jumalattomuutemme ja isiemme pahat teot, sillä sinua vastaan olemme tehneet syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Älä hylkää, nimesi tähden! Älä anna kunniasi valtaistuinta häväistäväksi. Muista liittosi kanssamme äläkä sitä riko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Onko pakanoiden turhista jumalista sateen antajiksi, tai taivasko antaa sadekuurot? Etkö sinä ole Herra, Jumalamme? Sinua odotamme, sillä sinä olet tehnyt tämän kaiken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Herra sanoi minulle: \"Vaikka Mooses ja Samuel seisoisivat edessäni, sieluni ei taipuisi tämän kansan puoleen. Aja heidät pois kasvojeni edestä, he menkööt!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Jos he kysyvät sinulta: \'Minne meidän on mentävä?\' niin vastaa heille: Näin sanoo Herra: Joka ruton oma, se ruttoon, joka miekan, se miekkaan, joka nälän, se nälkään, joka vankeuden, se vankeuteen!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Rankaisen heitä neljällä tuomiolla, sanoo Herra: miekan surmaamaan, koirat raahaamaan, taivaan linnut ja maan eläimet syömään ja hävittämään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Panen heidät kauhistukseksi kaikille valtakunnille maan päällä Manassen, Hiskian pojan, Juudan kuninkaan, tähden, kaiken tähden, mitä hän teki Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Kuka säälii sinua, Jerusalem, kuka surkuttelee sinua, kuka poikkeaa kysymään, mitä rauhaasi sopii?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Olet hylännyt minut, sanoo Herra, olet kääntynyt pois. Olen ojentanut käteni sinua vastaan, ja hävitän sinut. Olen väsynyt armahtamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Viskaan viskimellä heidät maan porteilla, teen heidät lapsettomiksi ja hukutan kansani, kun he eivät ole kääntyneet teiltään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Heidän leskiään on oleva minulla enemmän kuin meren hiekkaa. Tuon heidän nuorukaistensa äitien kimppuun hävittäjän keskellä päivää, langetan äkkiä heidän kaupunkinsa päälle kauhun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Seitsemän pojan synnyttäjä menehtyy ja huokaisee henkensä pois. Hänen aurinkonsa laski, kun vielä oli päivä. Hän joutui häpeään ja sai hävetä. Mitä heistä jää, sen annan miekalle heidän vihollistensa edessä, sanoo Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Voi minua, äitini, kun minut synnytit riidan ja toran mieheksi koko maalle! En ole lainaksi antanut enkä lainaksi ottanut. Kuitenkin kaikki minua kiroavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Herra sanoi: \"Totisesti, jäännöksenne käy hyvin. Totisesti, saatan viholliset käyttäytymään hyvin sinua kohtaan onnettomuuden ja ahdistuksen aikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Murtuuko rauta, pohjoisen rauta, ja vaski? –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Omaisuutesi ja aarteesi annan ryöstettäviksi, ilman hintaa kaikkien syntiesi tähden, kaikkia rajojasi myöten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Panen sinut vihollistesi kanssa kulkemaan maata, jota et tunne. Sillä vihani tuli on syttynyt. Se leimuaa teitä vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Sinä, Herra, sen tiedät. Muista minua ja pidä minusta huoli ja kosta puolestani vainoojilleni. Älä tempaa minua pois pitkämielisyytesi tähden. Huomaa, että kannan häväistystä tähtesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Sanasi löytyivät, ja söin ne, ja sanasi olivat minulle riemu ja sydämeni ilo. Sillä minut on otettu nimiisi, Herra, Jumala Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'En ole istunut iloitsemassa ilonpitäjien seurassa. Kätesi tähden olen istunut yksin, sillä olet täyttänyt minut vihallasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Miksi kipuni on loputon ja haavani on paha eikä tahdo parantua? Olet minulle kuin petollinen lähde, kuin vesi, joka ei pysy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Sen tähden, näin sanoo Herra: \"Jos käännyt, käännän sinut, ja tulet seisomaan edessäni. Ja jos tuot esiin jaloa, et arvotonta, olet oleva suunani. He kääntyvät luoksesi, mutta sinä et käänny heidän luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Teen sinut vahvaksi vaskimuuriksi tätä kansaa vastaan, ja he sotivat sinua vastaan, mutta eivät voita sinua. Sillä minä olen kanssasi ja vapautan ja pelastan sinut, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Pelastan sinut pahojen käsistä ja päästän sinut väkivaltaisten kourista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, '\"Älä ota itsellesi vaimoa, älköönkä sinulle tulko poikia ja tyttäriä tässä paikassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Sillä näin sanoo Herra niistä pojista ja tyttäristä, jotka syntyvät tässä paikassa, ja heidän äideistään, jotka heidät synnyttävät, ja heidän isistään, jotka heidät siittävät tässä maassa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'He kuolevat tuskallisiin tauteihin, heille ei pidetä valittajaisia eikä heitä haudata. He tulevat pellon lannaksi. He hukkuvat miekkaan ja nälkään, ja heidän ruumiinsa tulevat taivaan lintujen ja maan eläinten ruuaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Sillä näin sanoo Herra: Älä mene surutaloon, älä käy valittajaisiin äläkä heitä sure, sillä otan tältä kansalta pois rauhani, armoni ja laupeuteni, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'He kuolevat, sekä suuret että pienet, tässä maassa. Heitä ei haudata eikä heille pidetä valittajaisia. Kukaan ei viileskele ihoaan eikä aja päätään paljaaksi heidän takiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Heille ei murreta leipää lohdutukseksi heidän surussaan kuolleen tähden, eikä heille anneta juotavaksi lohdutusmaljaa heidän isänsä ja äitinsä tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Älä mene pitotaloon istumaan heidän kanssaan, älä syömään äläkä juomaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Katso, lopetan tästä paikasta silmienne edessä ja teidän päivinänne riemu- ja ilohuudon, huudon yljälle ja huudon morsiamelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Kun ilmoitat tälle kansalle kaikki nämä sanat ja he sanovat sinulle: \'Minkä tähden Herra on julistanut meille kaiken tämän suuren onnettomuuden, ja mikä on rikoksemme, mikä syntimme, jonka olemme tehneet Herraa, Jumalaamme, vastaan?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'niin sano heille: Sen tähden että isänne hylkäsivät minut, sanoo Herra, ja seurasivat muita jumalia, palvelivat niitä ja kumarsivat niitä, mutta hylkäsivät minut eivätkä noudattaneet lakiani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Te taas olette tehneet pahemmin kuin isänne, ja katso, te vaellatte kukin pahan sydämenne paatumuksessa kuulematta minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Heitän teidät pois tästä maasta maahan, jota te ette tunne eivätkä teidän isänne tunteneet, ja siellä te palvelette muita jumalia päivät ja yöt, sillä en anna teille armoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Sen tähden, katso, päivät tulevat, sanoo Herra, jolloin ei enää sanota: \'Niin totta kuin Herra elää, joka johdatti israelilaiset Egyptin maasta\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'vaan: \'Niin totta kuin Herra elää, joka johdatti israelilaiset pohjoisesta maasta ja kaikista muista maista, joihin hän oli heidät karkottanut.\' Sillä palautan heidät heidän omaan maahansa, jonka annoin heidän isilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Katso, lähetän monta kalastajaa, sanoo Herra, ja he kalastavat heitä, ja sen jälkeen lähetän monta metsästäjää, ja he metsästävät heitä kaikilta vuorilta ja kaikilta kukkuloilta ja kallioiden rotkoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Sillä silmäni tarkkaavat kaikkia heidän teitään. Ne eivät ole minulta salassa, eikä heidän rikoksensa ole kätketty silmiltäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Silloin kostan ensin kaksinkertaisesti heidän rikoksensa ja syntinsä, koska he ovat saastuttaneet maani iljetystensä raadoilla ja täyttäneet perintöosani kauhistuksillaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Herra, voimani, varustukseni ja pakopaikkani hädän päivänä! Sinun luoksesi tulevat pakanat maan ääristä ja sanovat: \"Petosta vain ovat perineet isämme, turhuutta, josta ei ole hyötyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Voiko ihminen tehdä itselleen jumalia? Eivät ne ole jumalia!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, '\"Sen tähden, katso, saatan heidät tuntemaan – tuntemaan nyt tällä kertaa – käteni ja voimani, ja he tulevat tietämään, että nimeni on Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, '\"Juudan synti on kirjoitettu rautapiirtimellä, timanttikärjellä, kaiverrettu heidän sydämensä tauluun ja alttarienne sarviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Heidän lapsensa muistavat alttarinsa ja aseransa vihreiden puiden vieressä korkeilla kukkuloilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Oman vuoreni, joka on kedolla, omaisuutesi, kaikki aarteesi ja uhrikukkulasi annan ryöstettäviksi synnin tähden kaikkia rajojasi myöten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Sinun on luovuttava perintöosastasi, jonka olen antanut sinulle. Saatan sinut vihollistesi orjuuteen maassa, jota et tunne. Sillä olette sytyttäneet vihani tulen, ja se on palava ikuisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Näin sanoo Herra: Kirottu on se mies, joka turvaa ihmisiin ja tekee lihan käsivarrekseen ja jonka sydän luopuu Herrasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Hän jää alastomaksi arolle eikä näe hyvän tulemista. Hän asuu poudan polttamissa paikoissa erämaassa, asumattomassa suolamaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Siunattu on se mies, joka turvaa Herraan, jonka turvana on Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Hän on kuin veden partaalle istutettu puu, joka lähettää juurensa puroa kohti. Helteen tuloa se ei pelästy, vaan sen lehvä on vihanta. Poutavuotenakaan sillä ei ole huolta, eikä se lakkaa tekemästä hedelmää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Petollinen on sydän yli kaiken, eikä sitä voi parantaa. Kuka sen tuntee?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Minä, Herra, tutkin sydämen, koettelen munuaiset, ja annan jokaiselle hänen vaelluksensa mukaan, hänen tekojensa hedelmän mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Peltokana, joka hautoo, mitä ei ole muninut, on se, joka hankkii rikkautta vääryydellä. Päiviensä puolivälissä hänen täytyy se jättää, ja hänen loppunsa on houkan loppu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Kunnian valtaistuin, korkea alusta asti, on pyhäkkömme paikka!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Israelin toivo, sinä Herra! Kaikki, jotka sinut hylkäävät, joutuvat häpeään. \"Jotka minusta luopuvat, ne kirjoitetaan maahan. Sillä he ovat hylänneet elävän veden lähteen, Herran.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Paranna minut, Herra, niin paranen, pelasta minut, niin olen pelastettu. Sillä sinä olet ylistykseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Katso, he sanovat minulle: \"Missä on Herran sana? Toteutukoon se!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Mutta minä en ole vetäytynyt pois olemasta paimenena, en sinua seuraamasta enkä toivonut tuhon päivää, sinä tiedät sen. Se, mitä huuliltani on lähtenyt, on kasvojesi edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Älä tule minulle kauhuksi, sinä, turvani onnettomuuden päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Joutukoot häpeään ne, jotka minua vainoavat, mutta älä anna minun häpeään tulla. Pelästykööt he, mutta älä anna minun pelästyä. Tuota heille onnettomuuden päivä ja tuhoa heidät kaksinkertaisella tuholla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Näin sanoi Herra minulle: \"Mene ja seiso Kansanportissa, josta Juudan kuninkaat tulevat ja josta he menevät, ja kaikissa Jerusalemin porteissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'Sano heille: Kuulkaa Herran sana, te Juudan kuninkaat ja koko Juuda ja kaikki Jerusalemin asukkaat, jotka tulette näistä porteista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Näin sanoo Herra: Ottakaa sielustanne vaari, älkää sapatinpäivänä kantako mitään taakkaa älkääkä tuoko niitä Jerusalemin porteista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Älkää kantako sapatinpäivänä taloistanne mitään älkääkä tehkö mitään työtä, vaan pyhittäkää sapatinpäivä, kuten olen isillenne käskyn siitä antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Mutta he eivät kuulleet, eivät korvaansa kallistaneet, vaan olivat niskureita, niin etteivät kuulleet eivätkä ottaneet ojennusta varteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Jos kuulette minua, sanoo Herra, niin ettette tuo sapatinpäivänä mitään kantamusta tämän kaupungin porteista, vaan pyhitätte sapatinpäivän, niin ettette silloin tee mitään työtä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'niin tämän kaupungin porteista tulee sisälle vaunuilla ja hevosilla ajaen kuninkaita ja ruhtinaita, jotka istuvat Daavidin valtaistuimella, he ja heidän ruhtinaansa, Juudan miehet ja Jerusalemin asukkaat tulevat, ja tämä kaupunki on oleva asuttu iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Juudan kaupungeista ja Jerusalemin ympäriltä, Benjaminin maasta ja Alankomaasta, Vuoristosta ja Negevistä tulee niitä, jotka tuovat polttouhreja, teurasuhreja, ruokauhreja ja suitsutusuhreja, tuovat kiitosuhreja Herran huoneeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Mutta jos ette kuule minua ettekä pyhitä sapatinpäivää, vaan kannatte kantamuksia ja kuljette Jerusalemin porteista sapatinpäivänä, niin sytytän tuleen sen portit, ja tuli kuluttaa Jerusalemin palatsit, eikä sammu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Sana, joka tuli Jeremialle Herralta ja kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, '\"Nouse ja mene alas savenvalajan huoneeseen. Siellä annan sinun kuulla sanani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Menin alas savenvalajan huoneeseen, ja katso, hän teki työtä dreijan ääressä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Jos astia, jota hän valmisti, meni pilalle, niin kuin savi voi mennä savenvalajan käsissä, hän teki siitä toisen astian, miten vain savenvalaja näki parhaaksi tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Minulle tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, '\"Enkö voi tehdä teille, te Israelin heimo, niin kuin tekee tuo savenvalaja, sanoo Herra. Katso, niin kuin savi on savenvalajan kädessä, niin te olette kädessäni, te Israelin heimo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Yhden kerran sanon tempaavani pois, hajottavani ja hävittäväni kansan ja valtakunnan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Mutta jos kansa kääntyy pois pahuudestaan, josta sille puhuin, niin kadun sitä pahaa, jota ajattelin tehdä sille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Toisen kerran taas lupaan rakentaa ja istuttaa kansan ja valtakunnan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'mutta jos se tekee sitä, mikä on pahaa silmissäni, eikä kuule ääntäni, niin kadun sitä hyvää, jota olin luvannut tehdä sille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Sano siis nyt Juudan miehille ja Jerusalemin asukkaille: Näin sanoo Herra: Katso, minä hankin teille onnettomuutta ja pidän neuvoa teitä vastaan. Kääntykää siis pois kukin pahalta tieltänne ja parantakaa vaelluksenne ja tekonne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Mutta he sanovat: \'Se on turhaa! Sillä vaellamme omien neuvojemme mukaan ja teemme kukin oman pahan sydämensä paatumuksen mukaan.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Sen tähden, näin sanoo Herra: \"Kysykää kansojen keskuudessa, kuka on tällaista kuullut? Hyvin kauhistuttavia tekoja on tehnyt neitsyt Israel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Lähteekö aukealta kalliolta Libanonin lumi? Ehtyvätkö kaukaa virtaavat, kylmät, kuohuvat vedet?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Mutta kansani on minut unohtanut. He polttavat uhreja turhille jumalille. Nämä ovat saaneet heidät kompastumaan teillään, ikivanhoilla poluilla, niin että he ovat joutuneet kulkemaan syrjäpolkuja, raivaamatonta tietä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'Niin he tekevät maansa kauhistukseksi, ikuiseksi ivan vihellykseksi. Jokainen, joka kulkee ohi, kauhistuu ja pudistaa päätään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Kuin itätuuli hajotan heidät vihollisen edessä; näytän heille selkäni enkä kasvojani heidän hätänsä päivänä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Mutta he sanoivat: \"Tulkaa, pitäkäämme neuvoa Jeremiaa vastaan. Sillä ei laki lopu papilta, ei neuvo viisaalta eikä sana profeetalta. Tulkaa, lyökäämme hänet kielellä, älkäämme kuunnelko lainkaan hänen puheitaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Kuuntele sinä, Herra, minua ja kuule, mitä vastustajani puhuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Onko hyvä pahalla kostettava, sillä he ovat kaivaneet kuopan sielulleni? Muista, kuinka olen seisonut edessäsi ja puhunut hyvää heidän puolestaan kääntääkseni heistä pois vihasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Sen tähden jätä heidän lapsensa nääntymään nälkään ja anna heidät alttiiksi miekalle, ja tulkoot heidän vaimonsa lapsettomiksi ja leskiksi, heidän miehensä surmatkoon kuolema, ja heidän nuorukaisensa kaatakoon sodassa miekka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Kuulukoon huuto heidän huoneistaan, kun tuot äkkiä heidän kimppuunsa rosvojoukon. Sillä he ovat kaivaneet kuopan vangitakseen minut ja virittäneet piiloansoja jaloilleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Mutta sinä, Herra, tiedät kaikki heidän murha-aikeensa minua vastaan. Älä anna anteeksi heidän rikostaan äläkä pyyhi pois heidän syntiään kasvojesi edestä. Kaatukoot he kasvojesi edessä. Tee tämä heille vihasi aikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Herra sanoi näin: \"Mene ja osta savenvalajalta ruukku ja ota mukaasi kansan ja pappien vanhimpia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'Lähde sitten Ben-Hinnomin laaksoon, joka on Sirpaleportin edustalla, ja julista siellä sanat, jotka puhun sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'Sano: Kuulkaa Herran sana, te Juudan kuninkaat ja Jerusalemin asukkaat: Näin sanoo Herra Sebaot, Israelin Jumala: Katso, tuotan sellaisen onnettomuuden tälle paikalle, että jokaisen korvat soivat, joka sen kuulee,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'sen tähden että he ovat hylänneet minut ja muuttaneet vieraaksi tämän paikan, ovat polttaneet siinä uhreja muille jumalille, joita he eivät tunteneet, eivät he eivätkä heidän isänsä eivätkä Juudan kuninkaat, ja täyttäneet tämän paikan viattomien verellä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'ovat rakentaneet uhrikukkuloita Baalille ja polttaneet tulessa lapsiaan polttouhreiksi Baalille, mitä en ole käskenyt enkä puhunut ja mikä ei ole mieleeni noussut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Sen tähden, katso, päivät tulevat, sanoo Herra, jolloin tätä paikkaa ei enää sanota Toofetiksi eikä Ben-Hinnomin laaksoksi, vaan \'Murhalaaksoksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Silloin teen tyhjäksi Juudan ja Jerusalemin neuvon tässä paikassa, annan heidän kaatua miekkaan vihollistensa edessä, annan heidät niiden käsiin, jotka etsivät heidän henkeään ja annan heidän ruumiinsa ruuaksi taivaan linnuille ja maan eläimille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Teen tämän kaupungin kauhistukseksi ja pilkattavaksi. Jokainen, joka kulkee ohi, kauhistuu ja viheltää kaikille sen haavoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Panen heidät syömään poikiensa ja tyttäriensä lihaa, ja he syövät toistensa lihaa siinä hädässä ja ahdistuksessa, jolla heitä ahdistavat heidän vihollisensa, ne, jotka etsivät heidän henkeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Särje ruukku niiden miesten nähden, jotka ovat tulleet kanssasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'Sano heille: Näin sanoo Herra Sebaot: Näin särjen tämän kansan ja tämän kaupungin, kuin särjetään savenvalajan astia, niin ettei sitä enää saa ehjäksi. Silloin haudataan Toofetiin, kun muualla ei ole tilaa haudata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Niin teen tälle paikalle, sanoo Herra, samoin sen asukkaille: teen tämän kaupungin Toofetin kaltaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Jerusalemin talot ja Juudan kuningasten talot tulevat Toofetin paikan kaltaisiksi, kaikki nuo saastaiset talot, joiden katoilla he ovat polttaneet uhreja kaikelle taivaan joukolle ja vuodattaneet juomauhreja muille jumalille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Jeremia tuli Toofetista, johon Herra oli lähettänyt hänet profetoimaan, ja asettui Herran huoneen esipihalle ja sanoi kaikelle kansalle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, '\"Näin sanoo Herra Sebaot, Israelin Jumala: Katso, tuotan tämän kaupungin päälle ja kaikkien sen kaupunkien päälle kaiken sen onnettomuuden, jonka olen sille puhunut, koska he ovat olleet niskureita eivätkä ole kuulleet sanojani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Mutta pappi Pashur, Immerin poika, joka oli Herran temppelin ylivalvoja, kuuli Jeremian profetoivan nämä sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Niin Pashur löi profeetta Jeremiaa ja pani hänet jalkapuuhun, joka oli Herran huoneeseen kuuluvassa Benjaminin yläportissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Kun Pashur seuraavana päivänä päästi Jeremian jalkapuusta, Jeremia sanoi hänelle: \" Herra ei kutsu sinua nimellä Pashur, vaan Maagor-Missabib.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Sillä näin sanoo Herra: Katso, teen sinut kauhistukseksi sekä itsellesi että kaikille ystävillesi; he kaatuvat vihollistensa miekkaan silmiesi nähden, ja koko Juudan annan Baabelin kuninkaan käsiin, ja hän vie heidät Baabeliin karkotukseen ja surmaa heitä miekalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Annan kaikki tämän kaupungin rikkaudet, kaiken, mitä se on saanut aikaan, kaikki sen kalleudet ja kaikki Juudan kuningasten aarteet annan heidän vihollistensa käsiin. Nämä ryöstävät ne, ottavat ne ja vievät ne Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Sinä, Pashur, ja kaikki, jotka talossasi asuvat, vaellatte vankeuteen, ja tulet Baabeliin. Sinne sinä kuolet ja sinne sinut haudataan, sinut ja kaikki ystäväsi, joille olet ennustanut valhetta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Olet taivutellut minua, Herra, ja olen taipunut. Olet tarttunut minuun ja voittanut. Olen ollut nauruna kaiken päivää, ja kaikki pilkkaavat minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Sillä niin usein kuin puhun, minun täytyy itkeä, huutaa väkivaltaa ja sortoa. Sillä Herran sana on tullut minulle häväistykseksi ja pilkaksi kaiken päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Mutta kun sanoin: \"En tahdo muistella häntä enkä enää puhua hänen nimessään\", sydämessäni oli kuin polttava tuli, suljettuna luihini. Väsyksiin asti yritin sitä kestää, mutta en voinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Sillä monen kuulen parjaavan. Kauhistus joka puolella! \"Ilmiantakaa! Ilmiantakaamme hänet!\" Kaikki ystäväni vaanivat, milloin kompastuisin: \"Ehkäpä hän antaa viekoitella itsensä, niin että voitamme hänet ja saamme hänelle kostaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Mutta Herra on kanssani kuin väkevä sankari. Sen tähden vainoojani kompastuvat eivätkä voi mitään. He saavat suuren häpeän, sillä he ovat olleet ymmärtämättömiä, iankaikkisen pilkan, joka ei unohdu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Herra Sebaot, sinä, joka tutkit vanhurskaan, näet munuaiset ja sydämen, salli minun nähdä, että kostat heille, sillä sinun huomaasi olen jättänyt asiani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Veisatkaa Herralle, ylistäkää Herraa, sillä hän pelastaa köyhän sielun pahantekijöiden käsistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Kirottu olkoon se päivä, jona synnyin. Älköön se päivä, jona äitini minut synnytti, olko siunattu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Kirottu olkoon se mies, joka toi isälleni ilosanoman, sanoen: \"Sinulle on syntynyt poikalapsi\", ja toi hänelle suuren ilon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Käyköön sen miehen kuin niiden kaupunkien, jotka Herra kukisti armahtamatta. Hän kuulkoon huudon aamulla ja sotahuudon keskipäivän aikaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'koska ei surmannut minua äidinkohtuun, niin että äitini olisi ollut hautani ja hänen kohtunsa jäänyt iäti kantavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Miksi olen äitini kohdusta tullut näkemään tuskaa ja vaivaa, niin että päiväni päättyvät häpeässä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Sana, joka tuli Jeremialle Herralta, kun kuningas Sidkia lähetti hänen luokseen Pashurin, Malkian pojan, ja pappi Sefanjan, Maasejan pojan, sanomaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, '\"Kysy neuvoa Herralta puolestamme, sillä Nebukadressar, Baabelin kuningas, sotii meitä vastaan. Ehkäpä Herra tekee meille ihmeen, kaikkien ihmeittensä vertaisen, niin että tämä lähtee pois kimpustamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Jeremia vastasi heille: \"Sanokaa Sidkialle näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Näin sanoo Herra, Israelin Jumala: Katso, käännän takaisin sota-aseet, jotka ovat käsissänne ja joilla te muurin ulkopuolella taistelette piirittäjiänne, Baabelin kuningasta ja kaldealaisia, vastaan, ja kokoan ne tämän kaupungin keskelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Minä itse sodin teitä vastaan ojennetulla kädellä ja väkevällä käsivarrella vihassa, kiivastuksessa ja suuressa suuttumuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'Tuhoan tämän kaupungin asukkaat, ihmiset ja eläimet. He kuolevat suureen ruttoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Sen jälkeen, sanoo Herra, annan Sidkian, Juudan kuninkaan, ja hänen palvelijansa ja kansan ja ne, jotka ovat tähän kaupunkiin jääneet jäljelle rutolta, miekalta ja nälältä, Nebukadressarin, Baabelin kuninkaan, käsiin ja heidän vihollistensa käsiin, niiden, jotka etsivät heidän henkeään, ja hän surmaa heidät miekan terällä. Hän ei säästä heitä, ei sääli eikä armahda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Sano tälle kansalle: Näin sanoo Herra: Katso, panen eteenne elämän tien ja kuoleman tien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Joka jää tähän kaupunkiin, se kuolee miekkaan, nälkään ja ruttoon, mutta se, joka lähtee ulos ja menee kaldealaisten puolelle, jotka teitä piirittävät, jää eloon ja pitää henkensä saaliinaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Sillä olen kääntänyt kasvoni tätä kaupunkia vastaan sille onnettomuudeksi enkä onneksi, sanoo Herra. Baabelin kuninkaan käsiin se annetaan, ja hän polttaa sen tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Sano Juudan kuninkaan huoneelle: Kuulkaa Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Daavidin huone! Näin sanoo Herra: Tuomitkaa joka aamu oikeat tuomiot ja pelastakaa ryöstetty sortajan kädestä, ettei tekojenne pahuuden tähden vihani syttyisi kuin tuli ja palaisi, eikä olisi sammuttajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Katso, käyn kimppuusi, sinä laakson asujatar, sinä tasangon kalliolinna, sanoo Herra, teidän kimppuunne, jotka sanotte: \'Kuka voi astua alas meitä vastaan, kuka tulla asuntoihimme?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Rankaisen teitä tekojenne hedelmän mukaan, sanoo Herra, ja sytytän tuleen kaupungin metsän, ja tuli kuluttaa kaiken, mitä on sen ympärillä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Näin sanoo Herra: \"Mene alas Juudan kuninkaan taloon ja puhu siellä tämä sana,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'ja sano: Kuule Herran sana, sinä Juudan kuningas, joka istut Daavidin valtaistuimella, sinä ja palvelijasi ja kansasi, jotka käytte sisälle näistä porteista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Näin sanoo Herra: Tehkää oikeus ja vanhurskaus ja pelastakaa ryöstetty sortajan kädestä. Muukalaiselle, orvolle ja leskelle älkää tehkö vääryyttä ja väkivaltaa älkääkä vuodattako viatonta verta tässä paikassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Sillä jos teette tämän sanan mukaan, niin tulee tämän linnan porteista sisälle ajaen vaunuilla ja hevosilla kuninkaita, jotka istuvat Daavidin valtaistuimella, tulee kuningas sekä hänen palvelijansa ja kansansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Mutta jos ette kuule näitä sanoja, niin vannon itseni kautta, sanoo Herra, että tämä talo on tuleva raunioiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Sillä näin sanoo Herra Juudan kuninkaan talosta: Sinä olet minulle Gilead, olet Libanonin huippu; mutta totisesti, teen sinut erämaaksi, asumattomiksi kaupungeiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Vihin hävittäjät sinua vastaan, kunkin aseineen, ja he hakkaavat maahan valiosetrisi ja heittävät ne tuleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Monet kansat kulkevat tämän kaupungin ohi ja kysyvät toisiltaan: \'Miksi Herra on tehnyt näin tälle suurelle kaupungille?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Siihen vastataan: \'Siksi, että he hylkäsivät Herran, Jumalansa, liiton ja kumarsivat muita jumalia ja palvelivat niitä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Älkää kuollutta itkekö älkääkä häntä surko, vaan itkekää tuota pois kulkevaa, sillä hän ei enää palaa eikä näe synnyinmaataan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Sillä näin sanoo Herra Sallumista, Joosian pojasta, Juudan kuninkaasta, joka tuli kuninkaaksi isänsä Joosian jälkeen ja joka on vaeltanut pois tästä paikasta: Hän ei enää tänne palaa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'vaan sinne, minne hänet on viety vangiksi, hän kuolee eikä näe enää tätä maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Voi sitä, joka ei rakenna vanhurskaudella taloaan eikä ullakkohuoneitaan oikeudella; joka ilmaiseksi teettää työtä lähimmäisellään eikä maksa hänelle hänen työstään;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'joka sanoo: \'Rakennan itselleni tilavan talon ja avarat ullakkohuoneet\', joka hakkauttaa siihen ikkunat, laudoittaa sen setripuulla ja maalauttaa punavärillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Siksikö sinä olet kuningas, että sinulla on intoa setripuuhun? Eikö isäsikin syönyt ja juonut ja kuitenkin ollut oikeuden ja vanhurskauden tekijä? Silloin hänen kävi hyvin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Hän hankki oikeuden kurjalle ja köyhälle. Silloin kaikki kävi hyvin. Eikö tämä juuri ole minun tuntemistani, sanoo Herra?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Mutta sinun silmäsi ja sydämesi eivät pyydä muuta kuin omaa voittoasi, muuta kuin vuodattaa viatonta verta ja harjoittaa väkivaltaa ja sortoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Sen tähden, näin sanoo Herra Joojakimista, Joosian pojasta, Juudan kuninkaasta: Hänelle ei pidetä valittajaisia eikä huudeta: \'Voi veljeni! Voi sisareni!\' Ei hänelle pidetä valittajaisia eikä huudeta: \'Voi herraamme! Voi hänen majesteettiaan!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Hänet haudataan kuin aasi haudataan. Hänet raahataan pois ja viskataan Jerusalemin porttien ulkopuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Nouse Libanonille ja huuda, korota äänesi Baasanissa. Huuda Abarimin vuorilta, sillä kaikki sinun rakastajasi ovat murskatut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Puhuin sinulle onnesi päivinä. Sanoit: \'En halua kuulla.\' Tämä on ollut tapasi nuoruudestasi asti: et ole kuullut ääntäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Tuuli on kaitseva kaikkia kaitsijoitasi, ja rakastajasi menevät vankeuteen. Silloin saat häpeän ja pilkan kaiken pahuutesi tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Sinä, joka asut Libanonissa, pidät pesääsi setripuissa, kuinka oletkaan voihkiva, kun sinulle tuskat tulevat kuin synnyttäjälle kouristus!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Niin totta kuin minä elän, sanoo Herra: olkoon Konja, Joojakimin poika, Juudan kuningas, vaikka sinettisormus oikeassa kädessäni, sillä siitäkin repäisen sinut irti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'Annan sinut niiden käsiin, jotka etsivät henkeäsi, niiden käsiin, joita sinä kauhistut: Nebukadressarin, Baabelin kuninkaan, ja kaldealaisten käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Sitten heitän sinut ja äitisi, joka on sinut synnyttänyt, vieraalle maalle, missä ette ole syntyneet, ja sinne kuolette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Mutta siihen maahan, jonne heidän sielunsa haluaa palata, he eivät palaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Onko sitten tämä mies, Konja, tarpeeton, rikottu astia? Minkä tähden hänet ja hänen jälkeläisensä on heitetty pois, viskattu pois maahan, jota eivät tunne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Maa, maa, maa! Kuule Herran sana!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Näin sanoo Herra: Kirjoittakaa tämä mies lapsettomaksi, mieheksi, jolla ei ole onnea elinpäivinään. Sillä kenellekään hänen jälkeläisistään ei tule sitä onnea, että hän istuisi Daavidin valtaistuimella ja hallitsisi vielä Juudaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, '\"Voi paimenia, jotka tuhoavat ja hajottavat laitumeni lampaat, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Sen tähden näin sanoo Herra, Israelin Jumala, paimenista, jotka kaitsevat kansaani: Olette hajottaneet lampaani ja karkottaneet ne pois ettekä ole pitäneet niistä huolta. Katso, huolehdin teidän pahojen tekojenne rankaisemisesta, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Minä kokoan lampaitteni jäännöksen kaikista maista, joihin olen ne karkottanut, ja tuon ne takaisin laitumelleen, ja ne ovat hedelmälliset ja lisääntyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Herätän heille paimenia, ja ne kaitsevat heitä. He eivät enää pelkää eivätkä säiky, eikä heistä puutu yhtään, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Katso, päivät tulevat, sanoo Herra, jolloin herätän Daavidille vanhurskaan Vesan. Hän on hallitseva kuninkaana ja menestyvä, ja hän on tekevä oikeuden ja vanhurskauden maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'Hänen päivinään pelastetaan Juuda ja Israel asuu turvassa. Tämä on hänen nimensä, jolla häntä kutsutaan: \' Herra vanhurskautemme.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Sen tähden, katso, päivät tulevat, sanoo Herra, jolloin ei enää sanota: \'Niin totta kuin Herra elää, joka johdatti israelilaiset Egyptin maasta\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'vaan: \'Niin totta kuin Herra elää, joka johdatti ja toi Israelin heimon jälkeläiset pohjoisesta maasta ja kaikista muista maista, joihin olin heidät karkottanut.\' He asuvat omassa maassaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Profeettoja vastaan. Sydämeni on murtunut rinnassani, ja kaikki luuni ovat voipuneita. Olen kuin juopunut mies, kuin sankari, jonka viini on voittanut, Herran edessä ja hänen pyhien sanojensa edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, '\"Sillä maa on täynnä avionrikkojia, maa murehtii kirouksen tähden ja erämaan laitumet kuivuvat. Heidän pyrkimyksensä on paha ja heidän voimansa on väärä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Sillä he ovat jumalattomia, niin profeetta kuin pappikin. Omasta huoneestanikin olen löytänyt heidän pahuuttaan, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Sen tähden heidän tiensä on oleva heille kuin liukas polku pimeässä. He suistuvat sillä ja kaatuvat. Sillä tuotan heille onnettomuuden heidän rangaistusvuotenaan, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Samarian profeetoissa näin pahennuksen: he ennustivat Baalin nimessä ja eksyttivät kansani Israelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Jerusalemin profeetoissa olen taas nähnyt kauhistuksia: aviorikosta ja valheessa vaeltamista. He ovat vahvistaneet pahantekijöiden käsiä, niin ettei kukaan käänny pois pahuudestaan. He ovat edessäni kaikki kuin Sodoma, ja kaupungin asukkaat kuin Gomorra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Sen tähden, näin sanoo Herra Sebaot profeetoista: Katso, syötän heille koiruohoa ja juotan heille myrkkyvettä. Sillä Jerusalemin profeetoista on jumalattomuus lähtenyt koko maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Näin sanoo Herra Sebaot: Älkää kuulko profeettojen sanoja, noiden, jotka teille ennustavat täyttäen teidät tyhjillä toiveilla. Oman sydämensä näkyjä he puhuvat, mutta eivät sitä, mikä tulee Herran suusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'He hokevat halveksijoilleni: \' Herra on sen sanonut: Teillä on oleva rauha!\' Kaikille, jotka vaeltavat sydämensä paatumuksessa, he sanovat: \'Teitä ei kohtaa onnettomuus.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Mutta kuka on seisonut Herran neuvottelussa ja nähnyt ja kuullut hänen sanansa? Kuka on kiinnittänyt huomionsa hänen sanaansa ja sitä kuunnellut?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Katso, Herran myrsky, viha, puhkeaa, myrsky pyörii kohti jumalattomien päätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Eikä Herran viha käänny pois, ennen kuin hän on toteuttanut ja täyttänyt sydämensä ajatukset. Päivien lopulla te tulette sen ymmärtämään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, '\"En ole lähettänyt noita profeettoja, mutta silti he juoksevat. En ole puhunut heille, mutta kuitenkin he profetoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Jos he olisivat seisoneet neuvottelussani, niin he julistaisivat sanani kansalleni ja kääntäisivät heidät pois heidän pahalta tieltään ja pahoista teoistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Olenko minä Jumala vain lyhyeltä matkalta, sanoo Herra. Enkö ole Jumala myös kaukaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Saattaako joku niin piiloon piiloutua, etten minä häntä näe? sanoo Herra. Enkö minä täytä taivasta ja maata? sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Olen kuullut, mitä nuo profeetat sanovat, jotka ennustavat nimessäni valhetta sanoen: \'Olen nähnyt unta, olen nähnyt unta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Kuinka kauan? Mitä noilla profeetoilla, jotka ennustavat valhetta, on mielessä? He ennustavat oman sydämensä petosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'Aikovatko he unillaan, joita he kertovat toisilleen, saattaa kansani unohtamaan nimeni, niin kuin heidän isänsä unohtivat nimeni Baalin tähden?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Se profeetta, jolla on uni, kertokoon unensa. Mutta se, jolla on sanani, puhukoon sanani uskollisesti. Mitä tekevät oljet jyvien seassa? sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Eikö sanani ole kuin tuli, sanoo Herra, ja kuin vasara, joka kallion murtaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Katso, sen tähden käyn niiden profeettojen kimppuun, sanoo Herra, jotka varastavat sanani toinen toiseltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Katso, käyn niiden profeettojen kimppuun, sanoo Herra, jotka ottavat sanansa omalta kieleltään, mutta sanovat: \'Hänen sanansa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Katso, käyn niiden kimppuun, jotka ennustavat valheunia, sanoo Herra, ja kertovat niitä ja eksyttävät kansaani valheillaan ja kerskumisellaan, vaikka minä en ole heitä lähettänyt enkä käskenyt ja vaikka heistä ei ole mitään hyötyä tälle kansalle, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Kun tämä kansa tai profeetta tai pappi kysyy sinulta sanoen: \'Mikä on Herran kuorma?\' niin sano heille: \'Mikä kuorma? – Teidät heitän pois\', sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Sitä profeettaa, pappia ja kansaa, joka sanoo: \' Herran kuorma\' – sitä miestä ja hänen huonettaan rankaisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Näin sanokaa keskenänne, toinen toisellenne: \'Mitä on Herra vastannut?\' ja \'Mitä on Herra puhunut?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Mutta \' Herran kuormaa\' älkää enää mainitko, sillä kuormaksi on tuleva jokaiselle hänen oma sanansa. Te vääntelette elävän Jumalan, Herran Sebaotin, Jumalanne, sanoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Näin sano profeetalle: \'Mitä on Herra sinulle vastannut? Mitä on Herra puhunut?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Mutta jos te sanotte: \' Herran kuorma\', silloin Herra sanoo näin: Koska te sanotte tämän sanan: \' Herran kuorma\', vaikka olen lähettänyt luoksenne sanomaan: Älkää sanoko: \' Herran kuorma\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'sen tähden katso: minä unohdan kokonaan teidät ja heitän pois kasvojeni edestä teidät ja tämän kaupungin, jonka annoin teille ja isillenne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'ja panen päällenne iankaikkisen häpeän ja iankaikkisen pilkan, joka ei unohdu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Herra näytti minulle, ja katso, kaksi viikunakoria oli asetettu Herran temppelin edustalle, sen jälkeen kun Nebukadressar, Baabelin kuningas, oli siirtänyt pois Jekonjan, Joojakimin pojan, Juudan kuninkaan, ja Juudan johtomiehet sekä sepät ja lukkosepät Jerusalemista ja vienyt heidät Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Toisessa korissa oli erittäin hyviä viikunoita, ensi sadon viikunoiden kaltaisia, ja toisessa korissa oli erittäin huonoja viikunoita, niin huonoja, ettei niitä syödä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Herra sanoi minulle: \"Mitä sinä näet, Jeremia?\" Sanoin: \"Viikunoita. Hyvät viikunat ovat erityisen hyviä, mutta huonot ovat kovin huonoja, niin huonoja, ettei niitä syödä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, '\"Näin sanoo Herra, Israelin Jumala: Niin kuin näitä hyviä viikunoita, niin pidän hyvinä Juudan karkotettuja, jotka lähetin tästä paikasta kaldealaisten maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Käännän katseeni heihin heidän hyväkseen, ja tuon heidät takaisin tähän maahan. Rakennan heidät enkä hajota, istutan heidät enkä revi pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Annan heille sydämen heidän tunteakseen minut, että minä olen Herra; ja he ovat kansani, ja minä olen heidän Jumalansa; sillä he kääntyvät luokseni kaikesta sydämestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Mutta kuten tehdään huonoille viikunoille, joita ei syödä niiden huonouden tähden, niin samoin, sanoo Herra, teen Sidkialle, Juudan kuninkaalle, ja hänen ruhtinailleen ja Jerusalemin jäännökselle, niille, jotka ovat jääneet jäljelle tähän maahan, ja niille, jotka asuvat Egyptin maassa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Teen heidät kauhistukseksi ja onnettomuudeksi kaikille valtakunnille maan päällä, häväistykseksi ja sananparreksi, pistopuheeksi ja kirosanaksi kaikissa paikoissa, mihin heidät karkotan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Lähetän heihin miekan, nälän ja ruton, kunnes he ovat hävinneet siitä maasta, jonka annoin heille ja heidän isilleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Sana, joka tuli Jeremialle ja koko Juudan kansalle, Joojakimin, Joosian pojan, Juudan kuninkaan, neljäntenä vuotena, se on Nebukadressarin, Baabelin kuninkaan, ensimmäisenä vuotena –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'sana, jonka profeetta Jeremia lausui koko Juudan kansaa ja kaikkia Jerusalemin asukkaita vastaan sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Joosian, Aamonin pojan, Juudan kuninkaan, kolmannestatoista vuodesta alkaen tähän päivään asti – kaksikymmentä kolme vuotta – on Herran sana tullut minulle, ja olen puhunut teille aamuvarhaisesta alkaen, mutta te ette ole kuulleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Herra on lähettänyt luoksenne kaikki palvelijansa, profeetat, aamuvarhaisesta alkaen, mutta te ette ole kuulleet ettekä kallistaneet korvaanne kuullaksenne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'kun he sanoivat: \"Kääntykää itse kukin pahalta tieltänne ja pahoista teoistanne, niin tulette asumaan maassa, jonka Herra on antanut teille ja isillenne, iankaikkisesta iankaikkiseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Älkää seuratko muita jumalia, älkää palvelko ja kumartako niitä älkääkä vihoittako minua kättenne teoilla, etten tuottaisi teille onnettomuutta.\" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, '\"Mutta ette kuulleet minua, sanoo Herra, ja niin vihoititte minut kättenne töillä omaksi onnettomuudeksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Sen tähden näin sanoo Herra Sebaot: Koska ette ole kuulleet sanojani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'katso, lähetän sanan, nostan kaikki pohjoiset kansanheimot, sanoo Herra, sanan Nebukadressarille, Baabelin kuninkaalle, palvelijalleni, ja tuon heidät tätä maata ja sen asukkaita vastaan ja kaikkia näitä ympärillä olevia kansoja vastaan. Nämä vihin tuhon omiksi ja teen heidät kauhistukseksi, ivatuiksi ja ikuisiksi raunioiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'Hävitän heidän keskuudestaan riemu- ja ilohuudon, huudon yljälle ja huudon morsiamelle, käsikivien äänen ja lampun valon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'Koko tämä maa tulee raunioiksi ja autioksi. Nämä kansat palvelevat Baabelin kuningasta seitsemänkymmentä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Mutta kun seitsemänkymmentä vuotta on täyttynyt, niin kostan Baabelin kuninkaalle ja sille kansalle – sanoo Herra – heidän pahat tekonsa, kostan kaldealaisten maalle ja hävitän sen ikuisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Tuotan sen maan päälle kaikki sanani, jotka olen puhunut sitä vastaan, kaiken, mitä tähän kirjaan on kirjoitettu, mitä Jeremia on profetoinut kaikkia niitä kansoja vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Sillä hekin palvelevat monia kansoja ja suuria kuninkaita, ja maksan heille heidän tekojensa ja kättensä tekojen mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Sillä näin sanoi Herra, Israelin Jumala, minulle: \"Ota tämä vihan viinin malja kädestäni ja juota sillä kaikki kansat, joiden luo sinut lähetän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'He juovat ja horjuvat ja tulevat mielettömiksi miekan edessä, jonka lähetän heidän keskelleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Otin maljan Herran kädestä ja juotin kaikkia kansoja, joiden luo Herra minut lähetti:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Jerusalemia ja Juudan kaupunkeja, sen kuninkaita ja ruhtinaita tehdäkseni heidät raunioiksi, kauhistukseksi, ivatuksi ja kiroukseksi, kuin on tänä päivänä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'faraota, Egyptin kuningasta, ja hänen palvelijoitaan ja ruhtinaitaan ja koko hänen kansaansa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'kaikkea sekakansaa ja kaikkia Uusin maan kuninkaita ja kaikkia filistealaisten maan kuninkaita ja Askelonia, Gassaa, Ekronia ja Asdodin jäännöstä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Edomia, Mooabia ja ammonilaisia;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'kaikkia Tyyron kuninkaita ja kaikkia Siidonin kuninkaita ja rantamaan kuninkaita, jotka ovat meren tuolla puolen;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Dedania, Teemaa ja Buusia ja kaikkia, joiden ohimoilta hiukset on ajettu;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'kaikkia Arabian kuninkaita ja kaikkia sekakansan kuninkaita, jotka asuvat erämaassa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'kaikkia Simrin kuninkaita, kaikkia Eelamin kuninkaita ja kaikkia Meedian kuninkaita;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'kaikkia pohjoisen kuninkaita, läheisiä ja kaukaisia, toista toisensa jälkeen, ja kaikkia maan valtakuntia, mitä maan päällä on. Heidän jälkeensä on Seesakin kuningas juova.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, '\"Sano heille: Näin sanoo Herra Sebaot, Israelin Jumala: Juokaa ja juopukaa, oksentakaa ja kaatukaa, älkääkä enää nousko, – miekan edessä, jonka minä lähetän keskellenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Mutta jos he eivät tahdo ottaa maljaa kädestäsi ja juoda, niin sano heille: Näin sanoo Herra Sebaot: Teidän täytyy juoda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Sillä, katso, siitä kaupungista alkaen, joka on otettu nimiini, minä aloitan onnettomuuden tuottamisen, ja tekö jäisitte rankaisematta! Te ette jää rankaisematta, sillä minä kutsun miekan kaikkia maan asukkaita vastaan, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Mutta profetoi sinä heille kaikki nämä sanat ja sano heille: Herra huutaa korkeudesta, antaa äänensä kaikua pyhästä asunnostaan. Hän totisesti huutaa yli laitumensa. Hän nostaa huudon kuin viinikuurnan polkijat kaikkia maan asukkaita vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Pauhina käy maan ääriin asti, sillä Herralla on riita-asia kansoja vastaan, hän käy oikeutta kaiken lihan kanssa, ja antaa jumalattomat miekalle alttiiksi, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Näin sanoo Herra Sebaot: Katso, onnettomuus kulkee kansasta kansaan, ja suuri myrsky nousee maan ääristä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'Herran surmaamia on oleva sinä päivänä maan äärestä maan ääreen. Heille ei pidetä valittajaisia, heitä ei koota eikä haudata; he jäävät lannaksi maan pinnalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Itkekää, paimenet, ja huutakaa, vieriskelkää tuhkassa, te lauman johtajat; sillä teidän teuraaksi joutumisen päivänne ovat tulleet täyteen. Hajoatte pirstaleiksi, kaadutte kuin arvokas astia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Mennyt on paimenilta pakopaikka ja pelastus lauman johtajilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Kuule paimenten huutoa, lauman johtajien valitusta! Sillä Herra hävittää heidän laumansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'Heidän rauhalliset laitumensa ovat tuhoutuneet Herran vihan hehkusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Hän on lähtenyt kuin nuori leijona pensaikostaan. Heidän maansa on tullut autioksi hävittäjän vihan hehkusta, Herran vihan hehkusta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Joojakimin, Joosian pojan, Juudan kuninkaan, hallituksen alussa tuli Herralta tämä sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, '\"Näin sanoo Herra: Asetu Herran temppelin esipihaan ja puhu kaikkia Juudan kaupunkeja vastaan, jotka tulevat kumartaen rukoilemaan Herran temppeliin, kaikki ne sanat, jotka olen käskenyt sinun sanoa heille. Älä jätä pois sanaakaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Ehkäpä he kuulevat ja kääntyvät itse kukin pois pahalta tieltään, ja kadun sitä onnettomuutta, jonka olin aikonut tuottaa heille heidän pahojen tekojensa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Sano heille: Näin sanoo Herra: Jos ette kuule minua ja vaella laissani, jonka olen teille antanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'ettekä kuule palvelijoitteni, profeettojen, sanoja, niiden, jotka minä olen lähettänyt teille, varhaisesta aamusta alkaen, vaikka ette ole kuulleet heitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'niin teen tälle huoneelle kuin Siilolle, ja teen tämän kaupungin kirosanaksi kaikille maan kansoille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Papit ja profeetat ja koko kansa kuulivat Jeremian puhuvan nämä sanat Herran huoneessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'Kun Jeremia oli puhunut loppuun kaiken, minkä Herra oli käskenyt hänen puhua kaikelle kansalle, papit ja profeetat ja koko kansa ottivat hänet kiinni sanoen: \"Sinun on kuolemalla kuoltava!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Miksi olet profetoinut Herran nimessä sanoen: Tälle huoneelle käy kuin Siilolle, ja tämä kaupunki on tuleva autioksi eikä siinä ole asukkaita?\" Kaikki kansa kokoontui Jeremiaa vastaan Herran huoneeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Kun Juudan ruhtinaat tämän kuulivat, he nousivat kuninkaan palatsista Herran temppeliin ja istuivat Herran uuden portin ovelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Papit ja profeetat sanoivat ruhtinaille ja kaikelle kansalle näin: \"Kuolemantuomio tälle miehelle! Sillä hän on profetoinut tätä kaupunkia vastaan, kuten olette omin korvin kuulleet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Mutta Jeremia sanoi kaikille ruhtinaille ja kaikelle kansalle näin: \" Herra lähetti minut profetoimaan tätä huonetta ja tätä kaupunkia vastaan kaikki ne sanat, jotka olette kuulleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Parantakaa siis nyt vaelluksenne ja tekonne ja kuulkaa Herran, Jumalanne, ääntä, niin Herra katuu sitä onnettomuutta, jonka hän on teille puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Mutta katso, minä olen teidän käsissänne. Tehkää minulle, minkä katsotte hyväksi ja oikeaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Mutta se totisesti tietäkää, että te, jos minut surmaatte, saatatte viattoman veren päällenne ja tämän kaupungin ja sen asukkaiden päälle, sillä totisesti Herra lähetti minut luoksenne puhumaan kaikki nämä sanat korvienne kuullen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Silloin ruhtinaat ja kaikki kansa sanoivat papeille ja profeetoille: \"Ei kuoleman tuomiota tälle miehelle! Sillä hän on puhunut meille Herran, Jumalamme, nimessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Muutamat maan vanhimmista nousivat ja sanoivat kaikelle kansan joukolle näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, '\"Miika, mooresetilainen, ennusti Hiskian, Juudan kuninkaan, päivinä ja sanoi kaikelle Juudan kansalle näin: Näin sanoo Herra Sebaot: \'Siion kynnetään pelloksi, ja Jerusalem tulee kivikasaksi ja temppelivuori metsäkukkulaksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Surmasivatko hänet tosiaan silloin Hiskia, Juudan kuningas, ja koko Juuda? Eikö hän pelännyt Herraa ja lepyttänyt häntä, niin että Herra katui sitä onnettomuutta, jonka hän oli heille puhunut? Mutta mekö tuottaisimme suuren onnettomuuden sieluillemme?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Mutta oli toinenkin mies, joka profetoi Herran nimessä: Uuria, Semajan poika, Kirjat-Jearimista. Hän profetoi tätä kaupunkia ja tätä maata vastaan aivan kuin Jeremia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Kun kuningas Joojakim ja kaikki hänen sankarinsa ja kaikki ruhtinaat kuulivat hänen sanansa, niin kuningas etsi häntä tappaakseen. Sen kuultuaan Uuria pelästyi, pakeni ja meni Egyptiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Mutta kuningas Joojakim lähetti miehiä Egyptiin: Elnatanin, Akborin pojan, ja muita hänen kanssaan Egyptiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'He toivat Uurian Egyptistä ja veivät hänet kuningas Joojakimin eteen. Tämä surmautti hänet miekalla ja heitätti hänen ruumiinsa tavallisen kansan hautaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Mutta Ahikamin, Saafanin pojan, käsi oli Jeremian suojana, niin ettei häntä jätetty kansan käsiin surmattavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Joojakimin, Joosian pojan, Juudan kuninkaan, hallituksen alussa tuli Herralta tämä sana Jeremialle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Näin Herra sanoi minulle: \"Tee itsellesi ikeet siteineen ja pane ne niskasi päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Lähetä ne Edomin kuninkaalle, Mooabin kuninkaalle, ammonilaisten kuninkaalle, Tyyron kuninkaalle ja Siidonin kuninkaalle niiden lähettiläiden mukana, jotka ovat tulleet Jerusalemiin Sidkian, Juudan kuninkaan, luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'Käske heidän sanoa herroilleen: Näin sanoo Herra Sebaot, Israelin Jumala: Näin sanokaa herroillenne:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Minä olen tehnyt maan sekä ihmiset ja eläimet, jotka maan päällä ovat, suurella voimallani ja ojennetulla käsivarrellani, ja annan sen sille, kenelle näen sen oikeaksi antaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Nyt minä annan kaikki nämä maat Nebukadnessarin, Baabelin kuninkaan, palvelijani, käsiin, ja myös kedon eläimet annan hänelle palvelemaan häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Kaikki kansat palvelevat häntä ja hänen poikaansa ja hänen poikansa poikaa, kunnes tulee hänenkin maansa aika ja monet kansat ja suuret kuninkaat tekevät hänet palvelijakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Mutta sitä kansaa ja sitä valtakuntaa, joka ei tahdo palvella häntä, Nebukadnessaria, Baabelin kuningasta, ja joka ei anna niskaansa Baabelin kuninkaan ikeeseen, sitä kansaa minä rankaisen miekalla, nälällä ja rutolla, sanoo Herra, kunnes teen heistä lopun hänen kädellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Mutta te, älkää kuulko profeettojanne, tietäjiänne, unianne, ennustelijoitanne ja velhojanne, jotka sanovat teille näin: \'Ette joudu palvelemaan Baabelin kuningasta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Sillä valhetta he profetoivat teille ja toimittavat teidät kauas pois maastanne. Karkotan teidät, ja te hukutte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Mutta sen kansan, joka taivuttaa niskansa Baabelin kuninkaan ikeen alle ja palvelee häntä, annan jäädä omaan maahansa, sanoo Herra. Se viljelee sitä ja asuu siinä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Sidkialle, Juudan kuninkaalle, puhuin kaikki nämä sanat sanoen: Taivuttakaa niskanne Baabelin kuninkaan ikeen alle ja palvelkaa häntä ja hänen kansaansa, niin pysytte elossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Miksi teidän pitäisi kuolla, sinun ja sinun kansasi, miekkaan, nälkään ja ruttoon, niin kuin Herra on puhunut sille kansalle, joka ei tahdo palvella Baabelin kuningasta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Älkää kuulko niiden profeettojen sanoja, jotka sanovat teille näin: \"Te ette joudu palvelemaan Baabelin kuningasta\"; sillä valhetta he profetoivat teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Sillä en ole lähettänyt heitä, sanoo Herra, vaan he profetoivat minun nimessäni valhetta ja saattavat minut karkottamaan teidät, ja te hukutte, te ja nuo profeetat, jotka teille profetoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Papeille ja koko tälle kansalle puhuin sanoen: Näin sanoo Herra: Älkää kuulko profeettojenne sanoja, niiden, jotka profetoivat teille sanoen: \"Katso, Herran temppelin astiat tuodaan nyt kohta takaisin Baabelista\"; sillä valhetta he profetoivat teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Älkää kuulko heitä. Palvelkaa Baabelin kuningasta, niin pysytte elossa. Miksi pitäisi tämän kaupungin tulla raunioiksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Mutta jos he ovat profeettoja ja jos heillä on Herran sana, rukoilkoot Herraa Sebaotia, etteivät ne astiat, jotka vielä ovat jäljellä Herran temppelissä ja Juudan kuninkaan linnassa ja Jerusalemissa, joutuisi nekin Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Sillä näin sanoo Herra Sebaot pylväistä, vaskimerestä, altaiden telineistä ja muista esineistä, jotka vielä ovat jäljellä tässä kaupungissa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'ja joita Nebukadnessar, Baabelin kuningas, ei ottanut mukaansa, kun hän vei Jekonjan, Joojakimin pojan, Juudan kuninkaan, sekä kaikki Juudan ja Jerusalemin ylimykset Jerusalemista karkotukseen Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'Sillä näin sanoo Herra Sebaot, Israelin Jumala, astioista, jotka vielä ovat jäljellä Herran temppelissä, Juudan kuninkaan linnassa ja Jerusalemissa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, '\"Baabeliin ne viedään, ja sinne ne jäävät siihen päivään asti, jolloin katson niiden puoleen, sanoo Herra, ja annan tuoda ja palauttaa ne tähän paikkaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Sinä vuonna, Sidkian, Juudan kuninkaan, hallituksen alussa, hänen neljäntenä hallitusvuotenaan, viidennessä kuussa, sanoi profeetta Hananja, Assurin poika, joka oli kotoisin Gibeonista, minulle Herran huoneessa pappien ja kaiken kansan silmien edessä näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, '\"Näin sanoo Herra Sebaot, Israelin Jumala: Särjen Baabelin kuninkaan ikeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Vielä kaksi vuotta, ja minä palautan tähän paikkaan kaikki Herran temppelin astiat, jotka Nebukadnessar, Baabelin kuningas, otti tästä paikasta ja vei Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Myös Jekonjan, Joojakimin pojan, Juudan kuninkaan, ja kaikki Juudan karkotetut, jotka menivät Baabeliin, minä palautan tähän paikkaan, sanoo Herra; sillä särjen Baabelin kuninkaan ikeen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Mutta profeetta Jeremia puhui profeetta Hananjalle pappien ja kaiken Herran huoneessa seisovan kansan silmien edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Näin profeetta Jeremia sanoi: \"Aamen. Niin Herra tehköön. Täyttäköön Herra sanasi, jotka olet profetoinut, ja palauttakoon Herran temppelin astiat ja kaikki karkotetut Baabelista tähän paikkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Kuule kuitenkin tämä sana, jonka minä puhun kuultesi ja kaiken kansan kuullen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Ne profeetat, jotka ovat olleet ennen minua ja ennen sinua muinaisuudesta asti, ovat profetoineet sotaa, onnettomuutta ja ruttoa monia maita ja suuria valtakuntia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Mutta se profeetta, joka profetoi rauhaa, tunnetaan siitä, että hänen sanansa toteutuu, profeetaksi, jonka Herra totisesti on lähettänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Silloin profeetta Hananja otti ikeen profeetta Jeremian niskalta ja särki sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Mutta Hananja sanoi kaiken kansan silmien edessä: \"Näin sanoo Herra: Näin minä särjen Nebukadnessarin, Baabelin kuninkaan, ikeen kaikkien kansojen niskasta, ennen kuin kaksi vuotta on kulunut.\" Mutta profeetta Jeremia lähti matkaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Sitten tämä Herran sana tuli Jeremialle, sen jälkeen kun profeetta Hananja oli särkenyt ikeen profeetta Jeremian niskasta:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, '\"Mene ja sano Hananjalle: Näin sanoo Herra: Sinä olet särkenyt puisen ikeen, mutta tehnyt sen sijaan rautaisen ikeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: rautaisen ikeen olen pannut kaikkien näiden kansojen niskaan, että ne palvelisivat Nebukadnessaria, Baabelin kuningasta; ja niiden on palveltava häntä. Kedon eläimetkin olen antanut hänelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Profeetta Jeremia sanoi profeetta Hananjalle: \"Kuule, Hananja! Herra ei ole sinua lähettänyt, vaan sinä olet saattanut tämän kansan turvaamaan valheeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Sen tähden, näin sanoo Herra: Katso, toimitan sinut pois maan päältä: tänä vuonna sinä kuolet, sillä sinä olet julistanut luopumusta Herrasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Niin profeetta Hananja kuoli sinä vuonna, seitsemännessä kuussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Nämä ovat sen kirjeen sanat, jonka profeetta Jeremia lähetti Jerusalemista karkotettujen vanhimmille, mitä heitä vielä oli jäljellä, papeille ja profeetoille sekä kaikelle kansalle, jotka Nebukadnessar oli siirtänyt Jerusalemista pois Baabeliin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'sen jälkeen kun kuningas Jekonja ja kuninkaan äiti, hoviherrat, Juudan ja Jerusalemin ruhtinaat sekä sepät ja lukkosepät olivat lähteneet Jerusalemista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'Hän lähetti kirjeen Elasan, Saafanin pojan, ja Gemarjan, Hilkian pojan, mukana, jotka Sidkia, Juudan kuningas, lähetti Nebukadnessarin, Baabelin kuninkaan, luo Baabeliin. Se kuului näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, '\"Näin sanoo Herra Sebaot, Israelin Jumala, kaikille karkotetuille, jotka olen siirtänyt Jerusalemista pois Baabeliin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Rakentakaa taloja ja asukaa niissä, istuttakaa puutarhoja ja syökää niiden hedelmiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Ottakaa itsellenne vaimoja ja siittäkää poikia ja tyttäriä. Ottakaa pojillenne vaimoja ja naittakaa tyttärenne, että he synnyttäisivät poikia ja tyttäriä. Lisääntykää siellä älkääkä vähentykö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Etsikää sen kaupungin menestystä, johon olen teidät siirtänyt, ja rukoilkaa sen puolesta Herraa, sillä sen menestys on teidän menestyksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Älkää antako profeettojenne, joita on keskuudessanne, ja tietäjienne pettää itseänne, älkääkä totelko unianne, joita näette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Sillä valhetta he ennustavat teille minun nimessäni. En ole lähettänyt heitä, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Sillä näin sanoo Herra: Vasta kun ne seitsemänkymmentä Baabelin vuotta ovat täyttyneet, katson puoleenne ja panen täytäntöön teitä kohtaan hyvän lupaukseni ja palautan teidät tähän paikkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Sillä minä tunnen ajatukseni, jotka minulla on teitä kohtaan, sanoo Herra: rauhan eikä turmion ajatukset antaakseni teille tulevaisuuden ja toivon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Te huudatte minua avuksenne, tulette ja rukoilette minua, ja kuulen teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'Te etsitte minua ja löydätte minut, sillä te etsitte minua kaikesta sydämestänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'Annan teidän löytää itseni, sanoo Herra, ja käännän teidän kohtalonne ja kokoan teidät kaikista kansoista ja kaikista paikoista, joihin olen teidät karkottanut, sanoo Herra, ja palautan teidät tähän paikkaan, josta siirsin teidät pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Sillä te sanotte: \' Herra on herättänyt meille profeettoja Baabelissa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Mutta Herra sanoo näin kuninkaasta, joka istuu Daavidin valtaistuimella, ja kaikesta kansasta, joka asuu tässä kaupungissa, veljistänne, jotka eivät lähteneet kanssanne karkotukseen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'Näin sanoo Herra Sebaot: Katso, lähetän heidän sekaansa miekan, nälän ja ruton ja teen heidät inhottaviksi kuin viikunat, jotka ovat niin huonoja, ettei niitä syödä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Silloin ajan heitä takaa miekalla, nälällä ja rutolla ja teen heidät kauhuksi kaikille valtakunnille maan päällä, kiroukseksi ja kauhistukseksi, ivaksi ja häväistykseksi kaikkien kansojen keskuudessa, mihin heidät karkotan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'sen tähden etteivät he kuulleet sanojani, sanoo Herra, kun lähetin heidän luokseen palvelijoitani, profeettoja, varhaisesta aamusta alkaen. Te ette ole kuulleet, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Mutta, te, kuulkaa Herran sana, kaikki karkotetut, jotka olen lähettänyt Jerusalemista Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Näin sanoo Herra Sebaot, Israelin Jumala, Ahabista, Koolajan pojasta, ja Sidkiasta, Maasejan pojasta, jotka ennustavat teille nimessäni valhetta: Katso, annan heidät Nebukadressarin, Baabelin kuninkaan, käsiin, ja hän lyö heidät kuoliaiksi silmienne edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'Heistä tulee kirosana kaikille Juudan karkotetuille, jotka ovat Baabelissa. Sanotaan: \' Herra tehköön sinulle niin kuin Sidkialle ja Ahabille, jotka Baabelin kuningas poltti tulessa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'Koska he ovat tehneet häpeällisen teon Israelissa, ovat tehneet huorin lähimmäistensä vaimojen kanssa ja puhuneet nimessäni valhetta, jota en ole käskenyt heidän puhua. Minä olen se, joka sen tiedän ja olen sen todistaja, sanoo Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Nehelamilaiselle Semajalle puhu sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, '\"Näin sanoo Herra Sebaot, Israelin Jumala: Sen tähden että sinä olet lähettänyt omassa nimessäsi kirjeet kaikelle kansalle, joka on Jerusalemissa, ja pappi Sefanjalle, Maasejan pojalle, ja kaikille papeille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'Herra on asettanut sinut papiksi pappi Joojadan sijaan, että olisi järjestyksenvalvojia Herran huoneessa kaikille hulluille ja ennustajille, ja jotta voit panna sellaisen jalkapuuhun ja kaularautaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Miksi et siis ole nuhdellut anatotilaista Jeremiaa, joka profetoi teille?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Hän on lähettänyt meille Baabeliin tämän sanan: \'Se kestää vielä kauan. Rakentakaa taloja ja asukaa niissä, istuttakaa puutarhoja ja syökää niiden hedelmiä.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Pappi Sefanja luki tämän kirjeen profeetta Jeremian kuullen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Jeremialle tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, '\"Lähetä kaikille karkotetuille tämä sana: Näin sanoo Herra nehelamilaisesta Semajasta: Koska Semaja on profetoinut teille, vaikka minä en ole lähettänyt häntä, ja saattanut teidät turvaamaan valheeseen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'sen tähden, näin sanoo Herra: Katso, kostan nehelamilaiselle Semajalle ja hänen jälkeläisilleen. Hänellä ei ole oleva ketään, joka asuu tämän kansan keskuudessa, eikä hän ole näkevä sitä hyvää, jonka minä teen kansalleni, sanoo Herra; sillä hän on julistanut luopumusta Herrasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Sana, joka tuli Herralta Jeremialle ja kuului näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, '\"Näin sanoo Herra, Israelin Jumala: Kirjoita kirjaan kaikki sanat, jotka olen sinulle puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Sillä katso, aika tulee, sanoo Herra, jolloin käännän kansani Israelin ja Juudan kohtalon, sanoo Herra, ja palautan heidät maahan, jonka olen antanut heidän isilleen, ja he saavat periä sen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Nämä ovat ne sanat, jotka Herra on puhunut Israelista ja Juudasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Näin sanoo Herra: \"Pelon huutoa kuulemme: on kauhu, ei rauha!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Kysykää ja nähkää: synnyttääkö mies? Miksi näen kaikkien miesten pitelevän käsin lanteitaan synnyttävien tavalla, ja miksi kaikki kasvot ovat tulleet kalpeiksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Voi! Suuri on se päivä, sen kaltaista ei ole. Se on Jaakobille ahdistuksen aika, mutta hän on pelastuva siitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Sinä päivänä, sanoo Herra Sebaot, minä särjen ikeen niskaltasi, katkaisen siteesi eivätkä he enää palvele vieraita,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'vaan he palvelevat Herraa, Jumalaansa, ja Daavidia, kuningastaan, jonka heille herätän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Mutta sinä, palvelijani Jaakob, älä pelkää, sanoo Herra, älä säiky, Israel. Sillä, katso, pelastan sinut kaukaisesta maasta ja jälkeläisesi heidän vankeutensa maasta. Jaakob on palaava, elävä rauhassa ja turvassa kenenkään pelottelematta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Sillä minä olen kanssasi, sanoo Herra, ja pelastan sinut. Sillä teen lopun kaikista kansoista, joiden sekaan olen sinut hajottanut. Ainoastaan sinusta en tee loppua: kuritan sinua kohtuudella, mutta rankaisematta en sinua jätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Sillä näin sanoo Herra: Parantumaton on vammasi, haavasi on vaikea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Ei kukaan aja asiaasi. Haavaasi ei paranneta, eikä se kasva umpeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Kaikki rakastajasi ovat sinut unohtaneet. He eivät sinua kysele. Sillä niin kuin vihollista lyödään, olen lyönyt sinua kovalla kurituksella, koska rikoksesi on suuri ja syntisi monilukuiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Miksi valitat vammaasi ja kipusi kovuutta? Koska rikoksesi on suuri ja syntisi ovat monilukuiset, olen tämän sinulle tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Niin myös kaikki syöjäsi syödään, ja kaikki ahdistajasi, aivan kaikki, vaeltavat vankeuteen. Ryöstäjäsi tulevat ryöstetyiksi, ja kaikki saalistajasi annan saaliiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Sillä kasvatan umpeen haavasi ja parannan sinut saamistasi iskuista, sanoo Herra, sinut, Siion, jolla on nimenä \'hylätty\', \'se, jota ei kukaan etsi\'.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Näin sanoo Herra: Katso, käännän Jaakobin telttamajojen kohtalon, armahdan hänen asuntojaan. Kaupunki rakennetaan kukkulalleen, ja linna on oleva oikealla paikallaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'Niistä on kaikuva ylistyslaulu ja iloitsevien ääni. Lisään heitä, eivätkä he vähene. Saatan heidät kunniaan, eivätkä he jää halvoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Silloin hänen poikansa ovat kuin ennen, hänen seurakuntansa pysyy vahvana edessäni ja rankaisen kaikkia hänen sortajiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Hänen valtiaansa lähtee hänestä itsestään, hänen hallitsijansa hänen keskeltään, ja tuon hänet luokseni, ja hän tulee luokseni. Sillä kuka panee henkensä alttiiksi lähestyäkseen minua? sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'Te olette minun kansani, ja minä olen teidän Jumalanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Katso, Herran myrsky, kiivaus, puhkeaa, pyörremyrsky pyörii kohti jumalattomien päätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Eikä Herran vihan hehku asetu, ennen kuin hän on toteuttanut ja täyttänyt sydämensä ajatukset. Päivien lopulla te tulette ymmärtämään sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, '\"Siihen aikaan, sanoo Herra, olen kaikkien Israelin sukukuntien Jumala, ja he ovat kansani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Näin sanoo Herra: \"Kansa, miekalta säästynyt, löysi erämaassa armon. Menen saattamaan Israelin rauhaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Kaukaa ilmestyy minulle Herra: \"Iankaikkisella rakkaudella olen sinua rakastanut, sen tähden olen vetänyt sinua puoleeni armosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Rakennan sinut jälleen, ja sinä, neitsyt Israel, tulet rakennetuksi. Kaunistat itsesi jälleen käsirummuillasi ja lähdet iloitsevien karkeloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Istutat jälleen viinitarhoja Samarian vuorille. Istuttajat istuttavat ne ja nauttivat niistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Sillä päivä tulee, jolloin vartijat huutavat Efraimin vuorella: \'Nouskaa, lähtekäämme Siioniin Herran, Jumalamme, luo.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Sillä näin sanoo Herra: Riemuitkaa iloiten Jaakobista, kohottakaa riemuhuuto hänelle, joka on kansojen pää. Kuuluttakaa, kiittäkää ja sanokaa: \'Auta, Herra, kansaasi, Israelin jäännöstä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Katso, tuon heidät pohjoisesta maasta ja kokoan heidät maan ääristä. Heissä on sokeita, rampoja sekä raskaana olevia ja synnyttäviä yhdessä. He palaavat tänne suurena joukkona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Itkien he tulevat, ja johdatan heitä, kun he kulkevat rukoillen. Vien heidät vesipuroille, tasaista tietä, jolla he eivät kompastu. Sillä olen Israelin Isä, ja Efraim on esikoiseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Kuulkaa Herran sana, te kansat, ilmoittakaa kaukaisissa merensaarissa ja sanokaa: Hän, joka Israelin hajotti, on sen kokoava ja varjeleva sitä kuin paimen laumaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Sillä Herra on lunastanut Jaakobin ja vapahtanut hänet häntä väkevämmän kädestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Silloin he tulevat ja riemuitsevat Siionin kukkulalla. He tulevat virtanaan Herran hyvyyden luo, vehnän, viinin ja öljyn ääreen, karitsojen ja vasikoiden ääreen. Heidän sielunsa on oleva kuin kostea puutarha, eivätkä he enää näänny.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Silloin neitsyt iloitsee karkelossa ja nuorukaiset ja vanhukset yhdessä. Muutan heidän surunsa riemuksi, annan heille lohdutuksen ja ilon päästäen heidät heidän murheestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Virvoitan pappien sielut yltäkylläisyydellä, ja kansani ravitaan hyvyydelläni, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Näin sanoo Herra: Kuule, ääni on kuuluva Raamasta, itku ja kova valitus: Raakel itkee lapsiaan eikä lohdutuksesta huoli surressaan lastensa tähden, sillä heitä ei enää ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Näin sanoo Herra: Pidätä äänesi itkusta, silmäsi kyynelistä, sillä työstäsi on tuleva palkka, sanoo Herra, ja he palaavat vihollisen maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Sinulla on tulevaisuuden toivo, sanoo Herra: lapsesi palaavat omalle maalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Olen kuulemalla kuullut Efraimin valittavan: \'Olet kurittanut minua, olen saanut kuritusta kuin vikuroiva vasikka. Palauta minut, niin palaan, sillä sinä olet Herra, Jumalani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Sillä käännyttyäni kadun, ja päästyäni ymmärrykseen lyön lanteeseeni. Olen nöyryytetty ja tunnen häpeää, sillä kannan nuoruuteni pilkkaa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Eikö Efraim ole kallis poikani, lempilapseni? Sillä niin usein kuin puhunkin häntä vastaan, aina häntä muistan. Siksi sisimpäni väräjää hänen tähtensä: minun täytyy armahtaa häntä, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Pystytä itsellesi merkkejä, aseta itsellesi tienviittoja, paina mieleesi tie, polku, jota olet kulkenut. Palaa, neitsyt Israel, palaa näihin kaupunkeihisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Kuinka kauan sinä kuljet mutkitellen sinne tänne, sinä luopiotytär? Sillä Herra luo maahan uutta: nainen miestä piirittää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Näin sanoo Herra Sebaot, Israelin Jumala: Vielä sanotaan Juudan maassa ja sen kaupungeissa, kun käännän heidän kohtalonsa, tämä sana: \' Herra siunatkoon sinua, sinä vanhurskauden asuinsija, sinä pyhä vuori.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Juuda kaikkine kaupunkeineen asuu siellä yhdessä sekä peltomiehet ja ne, jotka vaeltavat laumoineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Sillä virvoitan voipuneen sielun, ja jokaisen nääntyvän sielun ravitsen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Siihen heräsin ja katselin, ja uneni oli minusta suloinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, '\"Katso, päivät tulevat, sanoo Herra, jolloin kylvän Israelin huoneeseen ja Juudan huoneeseen ihmisen siementä ja karjan siementä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'Niin kuin olen valvonut repiäkseni ja kukistaakseni heitä, hajottaakseni ja hävittääkseni, tuottaakseni onnettomuutta, niin olen valvova rakentaakseni ja istuttaakseni heitä, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'Niinä päivinä ei enää sanota: \'Isät söivät raakoja rypäleitä, ja lasten hampaat heltyivät\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'vaan jokaisen on kuoltava oman syntivelkansa tähden. Jokaiselta ihmiseltä, joka syö raakoja rypäleitä, heltyvät hänen omat hampaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Katso, päivät tulevat, sanoo Herra, jolloin teen Israelin heimon ja Juudan heimon kanssa uuden liiton,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'en sellaista liittoa kuin se, jonka tein heidän isiensä kanssa silloin, kun tartuin heidän käteensä ja vein heidät pois Egyptin maasta. Sen liittoni he ovat rikkoneet, vaikka olin kihlannut heidät, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Vaan tämä on se liitto, jonka teen Israelin heimon kanssa niiden päivien tultua, sanoo Herra: Panen lakini heidän sisimpäänsä ja kirjoitan sen heidän sydämiinsä; ja niin olen heidän Jumalansa, ja he ovat kansani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'Silloin ei enää toinen opeta toistaan eikä veli veljeään sanoen: \'Tuntekaa Herra.\' Sillä he kaikki pienimmästä suurimpaan tuntevat minut, sanoo Herra, sillä annan anteeksi heidän rikoksensa enkä enää muista heidän syntejään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Näin sanoo Herra, joka on pannut auringon valaisemaan päivää, säätänyt kuun ja tähdet valaisemaan lakiensa mukaan yötä, hän, joka liikuttaa meren, niin että sen aallot pauhaavat – Herra Sebaot on hänen nimensä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Jos nämä lait väistyvät kasvojeni edestä, silloin myös Israelin jälkeläiset lakkaavat olemasta kansa kasvojeni edessä ainiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Näin sanoo Herra: Jos voidaan mitata taivaat ylhäällä ja tutkia maan perustukset alhaalla, silloin vasta hylkään Israelin jälkeläiset kaikki, kaiken sen tähden, mitä he ovat tehneet, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Katso, päivät tulevat, sanoo Herra, jolloin Herran kaupunki rakennetaan jälleen Hananelin tornista Kulmaporttiin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'Silloin mittanuora kulkee edelleen suoraan Gaarebin kukkulalle ja kääntyy sitten Gooaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'Myös koko laakso, ruumiineen ja tuhkineen, ja koko pelto Kidronin purolle asti, Hevosportin kulmaan saakka itään päin, on oleva Herralle pyhitetty. Sitä ei enää ikinä hävitetä eikä kukisteta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Sana, joka tuli Jeremialle Herralta Sidkian, Juudan kuninkaan, kymmenentenä vuotena, se on Nebukadressarin kahdeksantenatoista vuotena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Silloin Baabelin kuninkaan sotajoukko piiritti Jerusalemia, ja profeetta Jeremia oli suljettuna vankilan pihaan, joka on Juudan kuninkaan linnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Sinne oli Sidkia, Juudan kuningas, hänet sulkenut sanoen: \"Miksi sinä profetoit näin: Näin sanoo Herra: Katso, annan tämän kaupungin Baabelin kuninkaan käsiin, ja hän valloittaa sen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'Mutta Sidkia, Juudan kuningas, ei pääse pakoon kaldealaisten käsistä, vaan hänet tosiaan annetaan Baabelin kuninkaan käsiin, ja hänen täytyy puhua hänen kanssaan suusta suuhun ja nähdä hänet silmästä silmään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'Hän kuljettaa Sidkian Baabeliin, ja sinne hän jää, kunnes katson hänen puoleensa, sanoo Herra. Kun taistelette kaldealaisia vastaan, teillä ei ole menestystä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Sitten Jeremia sanoi: \"Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Katso, Hanamel, setäsi Sallumin poika, tulee luoksesi ja sanoo: \'Osta peltoni, joka on Anatotissa, sillä sinulla on lunastusoikeus, niin että saat ostaa sen.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Niin Hanamel, setäni poika, tuli Herran sanan mukaan luokseni vankilan pihaan ja sanoi minulle: \"Osta peltoni, joka on Anatotissa, Benjaminin maassa, sillä sinulla on perintöoikeus ja sinulla on lunastusoikeus: osta se itsellesi.\" Ymmärsin, että se oli Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Ostin Hanamelilta, setäni pojalta, pellon, joka on Anatotissa, ja punnitsin hänelle rahat, seitsemäntoista sekeliä hopeaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'kirjoitin kauppakirjan ja sinetöin sen, otin todistajat ja punnitsin rahat vaa\'alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Sitten otin kauppakirjan, joka oli sinetöity lain ja määräysten mukaan, sekä avoimen kirjan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'ja annoin kauppakirjan Baarukille, Neerian, Mahsejan pojan, pojalle, serkkuni Hanamelin nähden ja todistajien nähden, jotka olivat allekirjoittaneet kauppakirjan, ja kaikkien juutalaisten nähden, jotka istuivat vankilan pihassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'ja käskin Baarukia heidän nähtensä sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, '\"Näin sanoo Herra Sebaot, Israelin Jumala: Ota nämä kirjat, tämä kauppakirja, sekä sinetöity että tämä avoin kirja, ja pane ne saviastiaan, että ne säilyisivät kauan aikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Vielä kerran ostetaan tässä maassa taloja ja peltoja ja viinitarhoja.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Rukoilin Herraa, kun olin antanut kauppakirjan Baarukille, Neerian pojalle, ja sanoin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, '\"Oi Herra, Herra! Katso, sinä olet tehnyt taivaan ja maan suurella voimallasi ja ojennetulla käsivarrellasi: ei mikään ole sinulle mahdotonta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'sinä, joka teet laupeuden tuhansille, mutta kostat isien pahat teot heidän jälkeensä heidän lapsilleen, sinä suuri, väkevä Jumala, jonka nimi on Herra Sebaot,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'suuri neuvossa ja voimakas teoissa, sinä, jonka silmät ovat avoimet seuraamaan kaikkia ihmislasten teitä antaaksesi jokaiselle hänen vaelluksensa ja hänen tekojensa hedelmän mukaan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'sinä, joka teit tunnustekoja ja ihmeitä Egyptin maassa ja olet tehnyt niitä aina tähän päivään asti sekä Israelissa että muiden ihmisten joukossa, ja joka olet tehnyt itsellesi nimen, sellaisen kuin se tänäkin päivänä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Sinä veit kansasi Israelin pois Egyptin maasta tunnusteoilla ja ihmeillä, väkevällä kädellä ja ojennetulla käsivarrella, suurella pelolla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'ja annoit heille tämän maan, jonka olit luvannut antaa heille heidän isilleen vannotulla valalla, maan, joka vuotaa maitoa ja hunajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Mutta kun he olivat tulleet ja ottaneet sen omakseen, he eivät kuulleet ääntäsi eivätkä vaeltaneet lakisi mukaan. He eivät tehneet mitään siitä, mitä olit käskenyt heidän tehdä, ja annoit kaiken tämän onnettomuuden kohdata heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Katso, piiritysvallit ovat edenneet aivan kaupunkiin asti, niin että se valloitetaan, ja kaupunki joutuu miekan, nälän ja ruton tähden kaldealaisten valtaan, jotka sotivat sitä vastaan. Mitä olet puhunut, on tapahtunut, ja katso, sinä näet sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Mutta kuitenkin sinä, Herra, Herra, sanoit minulle: \'Osta rahalla itsellesi pelto ja ota todistajat\', vaikka kaupunki joutuu kaldealaisten käsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Silloin Jeremialle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, '\"Katso, minä olen Herra, kaiken lihan Jumala; onko minulle mikään mahdotonta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Sen tähden, näin sanoo Herra: Katso, annan tämän kaupungin kaldealaisten käsiin ja Nebukadressarin, Baabelin kuninkaan, käsiin, ja hän valloittaa sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Niin kaldealaiset, jotka sotivat tätä kaupunkia vastaan, tulevat ja sytyttävät tämän kaupungin tuleen ja polttavat sen niine taloineen, joiden katoilla on poltettu uhreja Baalille ja vuodatettu juomauhreja vieraille jumalille, saadakseen vihani syttymään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Sillä Israelin ja Juudan miehet ovat nuoruudestaan asti tehneet vain sitä, mikä on pahaa silmissäni, sillä kättensä teoilla israelilaiset ovat kiihottaneet minua vain vihaan, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Sillä tämä kaupunki on ollut minulle vihaksi ja kiivastukseksi siitä päivästä lähtien, jona he sen rakensivat, aina tähän päivään asti. Heitän sen pois kasvojeni edestä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'kaiken sen pahan tähden, minkä israelilaiset ja Juudan miehet ovat tehneet minulle herättääkseen vihani – he, heidän kuninkaansa, ruhtinaansa, pappinsa ja profeettansa sekä Juudan miehet ja Jerusalemin asukkaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'He ovat kääntäneet minulle selkänsä eivätkä kasvojaan, ja vaikka olen opettanut heitä aamuvarhaisesta alkaen, he eivät ole kuulleet eivätkä ottaneet varteen opetusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'He ovat asettaneet iljetyksensä temppeliin, joka on otettu nimiini, ja saastuttaneet sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'He ovat myös rakentaneet Baalille uhrikukkulat, jotka ovat Ben-Hinnomin laaksossa, polttaakseen poikiaan ja tyttäriään uhrina Molokille, mitä en ole käskenyt ja mikä ei ole mieleeni tullut. Tällaisia kauhistuksia he tekivät ja saivat Juudan tekemään syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Mutta nyt sanoo Herra, Israelin Jumala, näin tästä kaupungista, jonka te sanotte annettavan Baabelin kuninkaan käsiin miekan, nälän ja ruton tähden:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Katso, kokoan heidät jälleen kaikista maista, joihin heidät vihassani, kiivastuksessani ja suuressa suuttumuksessani karkotan, ja palautan heidät tähän paikkaan ja saatan heidät asumaan turvassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'Silloin he ovat kansani, ja minä olen heidän Jumalansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'ja annan heille yhden sydämen ja yhden tien, niin että he pelkäävät minua kaiken elinaikansa heille ja heidän lapsilleen parhaaksi heidän jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'Teen heidän kanssaan iankaikkisen liiton, niin etten käänny heistä pois, vaan teen heille hyvää, ja annan pelkoni heidän sydämiinsä, niin etteivät he luovu minusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Iloitsen heistä, siitä, että teen heille hyvää, ja istutan heidät tähän maahan totuudessa kaikesta sydämestäni ja kaikesta sielustani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Sillä näin sanoo Herra: Samoin kuin olen tuottanut tälle kansalle kaiken tämän suuren onnettomuuden, niin minä myös tuotan heille kaiken sen hyvän, minkä minä heille sanon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Vielä ostetaan peltoja tässä maassa, josta te sanotte: \'Se on oleva autio, vailla ihmisiä ja eläimiä ja kaldealaisten käsiin annettu.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Peltoja ostetaan rahalla, kauppakirjoja kirjoitetaan ja sinetöidään ja todistajia otetaan Benjaminin maassa, Jerusalemin ympäristössä ja Juudan kaupungeissa, Vuoriston, Alankomaan ja Negevin kaupungeissa, sillä käännän heidän kohtalonsa, sanoo Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Herran sana tuli Jeremialle toistamiseen, kun hän oli vielä suljettuna vankilan pihalle. Se kuului näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, '\"Näin sanoo Herra, joka sen myös tekee, Herra, joka valmistaa sen ja vahvistaa sen – Herra on hänen nimensä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Huuda minua avuksesi, niin vastaan sinulle ja ilmoitan sinulle suuria ja salattuja asioita, joita et tiedä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Sillä näin sanoo Herra, Israelin Jumala, tämän kaupungin taloista ja Juudan kuningasten linnoista, jotka sortuvat piiritysvallien ja miekan edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'ja niistä, jotka ovat tulleet taistelemaan kaldealaisia vastaan, ja täyttämään talot ihmisten ruumiilla, jotka vihassani ja kiivastuksessani surmaan ja joiden kaiken pahuuden tähden olen kätkenyt kasvoni tältä kaupungilta:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Katso, kasvatan umpeen ja lääkitsen sen haavat, ja parannan heidät ja avaan heille rauhan ja totuuden yltäkylläisyyden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Käännän Juudan kohtalon ja Israelin kohtalon ja rakennan heidät entiselleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'Puhdistan heidät kaikista heidän pahoista teoistaan, joilla he ovat tehneet syntiä minua vastaan, ja annan anteeksi kaikki heidän pahat tekonsa, joilla he ovat rikkoneet minua vastaan ja nousseet kapinaan minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Tämä kaupunki on oleva minulle kunniaksi ja iloksi, ylistykseksi ja kirkkaudeksi kaikkien maan kansojen edessä, jotka kuulevat kaiken sen hyvän, minkä minä sille teen. He pelästyvät ja vapisevat kaiken sen hyvän ja kaiken sen rauhan tähden, jonka minä sille annan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Näin sanoo Herra: Vielä kerran kuullaan tässä paikassa, josta te sanotte: \'Se on oleva rauniona, vailla ihmisiä ja eläimiä.\' Juudan kaupungeissa ja Jerusalemin autioilla kaduilla, joilla ei nyt ole ihmistä, ei asukasta eikä eläintä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'riemun ja ilon huuto, huuto yljälle ja huuto morsiamelle, niiden huuto, jotka sanovat: \'Kiittäkää Herraa Sebaotia, sillä Herra on hyvä, sillä hänen armonsa pysyy iankaikkisesti\', ja niiden, jotka tuovat Herran huoneeseen kiitosuhreja. Sillä käännän maan kohtalon entiselleen, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Näin sanoo Herra Sebaot: Vielä kerran on tässä paikassa, joka on rauniona, vailla ihmisiä ja eläimiä, ja kaikilla sen kaupungeilla oleva laitumia, joilla paimenet antavat lampaittensa levätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'Vuoriston kaupungeissa, Alankomaan kaupungeissa ja Negevin kaupungeissa, Benjaminin maassa, Jerusalemin ympäristössä ja Juudan kaupungeissa on vielä kerran lampaita kulkeva laskijan käsien ohi, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Katso, päivät tulevat, sanoo Herra, jolloin toteutan sen hyvän lupauksen, jonka olen lausunut Israelin heimosta ja Juudan heimosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'Niinä päivinä ja siihen aikaan kasvatan Daavidille vanhurskauden Vesan, ja hän on tekevä oikeuden ja vanhurskauden maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'Niinä päivinä pelastetaan Juuda, ja Jerusalem asuu turvassa, ja tämä on se nimi, joksi sitä sanotaan: \' Herra, vanhurskautemme.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Sillä näin sanoo Herra: Aina on mies Daavidin suvusta istuva Israelin heimon valtaistuimella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Aina on myös mies leeviläisten pappien suvusta oleva edessäni uhraamassa polttouhria ja sytyttämässä ruokauhria ja toimittamassa teurasuhria joka päivä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Jeremialle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, '\"Näin sanoo Herra: Jos saatte rikotuksi liittoni päivän kanssa ja liittoni yön kanssa, niin että päivä ja yö eivät enää tule ajallaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'niin rikkoutuu myös liittoni palvelijani Daavidin kanssa, niin ettei hänellä enää ole poikaa, joka istuu kuninkaana hänen valtaistuimellaan, ja liittoni leeviläisten pappien, palvelijoitteni, kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Samoin kuin taivaan joukkoa ei voi lukea eikä meren hiekkaa mitata, niin monilukuisiksi teen palvelijani Daavidin jälkeläiset ja leeviläiset, jotka minua palvelevat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Sitten Jeremialle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, '\"Etkö ole huomannut, mitä tämä kansa puhuu sanoen: \'Ne kaksi sukukuntaa, jotka Herra valitsi, hän on hylännyt\'? He halveksivat kansaani, niin kuin se ei enää olisikaan kansa heidän silmissään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Näin sanoo Herra: Jos liittoni päivän ja yön kanssa on olematon, jos en ole säätänyt taivaan ja maan lakeja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'niin myös hylkään Jaakobin ja palvelijani Daavidin jälkeläiset, niin etten ota hänen jälkeläisistään hallitsijoita Aabrahamin, Iisakin ja Jaakobin jälkeläisille. Sillä käännän heidän kohtalonsa ja armahdan heitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Sana, joka tuli Jeremialle Herralta, kun Nebukadnessar, Baabelin kuningas, ja koko hänen sotajoukkonsa ja kaikki hänen valtaansa kuuluvan maan valtakunnat ja kaikki kansat sotivat Jerusalemia ja kaikkia siihen kuluvia kaupunkeja vastaan. Se kuului näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, '\"Näin sanoo Herra, Israelin Jumala: Mene ja sano Sidkialle, Juudan kuninkaalle, sano hänelle: Näin sanoo Herra: Katso, annan tämän kaupungin Baabelin kuninkaan käsiin, ja hän polttaa sen tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Mutta sinä et pääse pakoon hänen käsistään, vaan sinut otetaan kiinni ja annetaan hänen käsiinsä, ja sinun täytyy nähdä Baabelin kuningas silmästä silmään, ja hän puhuu kanssasi suusta suuhun, ja joudut Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Mutta kuule Herran sana, Sidkia, Juudan kuningas: Näin sanoo Herra sinusta: Et kuole miekkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'Kuolet rauhassa; ja niin kuin isillesi, aikaisemmille kuninkaille, jotka olivat ennen sinua, niin poltetaan kunniaksesi kuolinsuitsutus ja sinulle pidetään valittajaiset ja huudetaan: \'Voi herraamme!\' Sillä minä olen sen sanonut, sanoo Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Profeetta Jeremia puhui Sidkialle, Juudan kuninkaalle, kaikki nämä sanat Jerusalemissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'kun Baabelin kuninkaan sotajoukko taisteli Jerusalemia vastaan ja kaikkia vielä jäljellä olevia Juudan kaupunkeja vastaan, Laakista ja Asekaa vastaan, sillä nämä olivat jääneet jäljelle Juudan kaupungeista, nimittäin sen linnoitetuista kaupungeista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Sana, joka tuli Jeremialle Herralta, sen jälkeen kun kuningas Sidkia oli tehnyt liiton kaiken kansan kanssa, joka oli Jerusalemissa, ja julistanut heille vapautuksen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'että jokaisen tuli päästää vapaaksi orjansa ja orjattarensa, heprealainen mies ja heprealainen nainen, niin etteivät he pitäisi heitä orjinaan, kukaan ei juutalaista veljeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Sen kuulivat kaikki ruhtinaat ja kaikki kansa, jotka olivat menneet tähän liittoon, että jokaisen tuli päästää vapaaksi orjansa ja orjattarensa eikä enää pitää heitä orjinaan, ja he tottelivat ja päästivät heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Mutta jälkeenpäin he peräytyivät liitosta ja ottivat takaisin ne orjat ja orjattaret, jotka he olivat päästäneet vapaiksi, ja alistivat heidät orjikseen ja orjattarikseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Silloin tuli Jeremialle Herralta tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, '\"Näin sanoo Herra, Israelin Jumala: Minä tein isienne kanssa liiton sinä päivänä, kun vein heidät pois Egyptin maasta, orjuuden huoneesta sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Seitsemän vuoden kuluttua päästäkää veljenne, heprealainen: joka on myynyt itsensä sinulle ja palvellut sinua kuusi vuotta, päästä hänet luotasi vapaaksi. Mutta isänne eivät kuulleet minua eivätkä kallistaneet korvaansa puheelleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Vaan nyt te olette kääntyneet ja tehneet teon, joka on oikea silmissäni julistaessanne vapautuksen kukin lähimmäiselleen, ja olette tehneet liiton kasvojeni edessä huoneessa, joka on otettu nimiini.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Mutta sitten te olette jälleen kääntyneet pois ja häväisseet nimeni: olette ottaneet takaisin kukin orjanne ja orjattarenne, jotka olitte päästäneet vapaiksi ja itsenäisiksi, ja olette alistaneet heidät olemaan orjinanne ja orjattarinanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Sen tähden näin sanoo Herra: Te ette kuulleet minua ettekä julistaneetkaan vapautusta kukin veljelleen ja lähimmäiselleen. Katso, julistan teille vapautuksen, sanoo Herra: menon miekkaan, ruttoon ja nälkään, ja teen teidät kauhuksi kaikille valtakunnille maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Annan ne miehet, jotka ovat rikkoneet liittoni, jotka eivät ole pitäneet sen liiton sanoja, jonka he tekivät edessäni halkaisten kahtia uhrivasikan ja käyden sen puolikkaiden välitse, nämä miehet –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'Juudan ruhtinaat ja Jerusalemin ruhtinaat, hoviherrat ja papit sekä kaiken maan kansan, jotka kävivät vasikan puolikkaiden välitse –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'annan heidät heidän vihollistensa käsiin, niiden käsiin, jotka etsivät heidän henkeään; ja heidän ruumiinsa joutuvat taivaan lintujen ja maan eläinten ruuaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Sidkian, Juudan kuninkaan, ja hänen ruhtinaansa annan heidän vihollistensa käsiin, niiden käsiin, jotka etsivät heidän henkeään, Baabelin kuninkaan sotajoukon käsiin, joka on lähtenyt pois kimpustanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Katso, käsken heitä, sanoo Herra, ja palautan heidät tämän kaupungin kimppuun, ja he sotivat sitä vastaan, valloittavat sen ja polttavat sen tulella; ja Juudan kaupungit teen autioiksi, eikä niissä ole asukkaita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Sana, joka tuli Jeremialle Herralta Juudan kuninkaan Joojakimin, Joosian pojan, päivinä, ja kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, '\"Mene reekabilaisten luo ja puhuttele heitä ja vie heidät Herran temppeliin, yhteen sen kammioista, ja anna heille viiniä juoda.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Niin otin Jaasanjan, joka oli Jeremian, Habassinjan pojan, poika, sekä hänen veljensä ja kaikki hänen poikansa ja koko reekabilaisten heimon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'ja vein heidät Herran huoneeseen, Jumalan miehen Haananin, Jigdaljan pojan, poikien kammioon, joka on ruhtinaiden kammion vieressä, ovenvartija Maasejan, Sallumin pojan, kammion yläpuolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Asetin reekabilaisten eteen täysiä viiniruukkuja sekä maljoja ja sanoin heille: \"Juokaa viiniä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Mutta he vastasivat: \"Me emme juo viiniä; sillä meidän isämme Joonadab, Reekabin poika, on antanut meille tämän käskyn: Älkää te ja teidän lapsenne ikinä juoko viiniä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'Älkää rakentako taloja älkääkä kylväkö siementä. Älkää istuttako viinitarhoja, älköönkä niitä teillä olko, vaan asukaa teltoissa kaikkina elämänne päivinä, että eläisitte kauan siinä maassa, jossa te olette muukalaisina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Me kuulemme isämme Joonadabin, Reekabin pojan ääntä, kaikessa, mitä hän on käskenyt meidän tehdä, niin että emme koskaan juo viiniä elämämme päivinä, emme me eivätkä vaimomme, eivät poikamme eivätkä tyttäremme,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'emmekä rakenna taloja asuaksemme, eikä meillä ole viinitarhoja, ei peltoa eikä siementä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'Vaan me asumme teltoissa ja olemme kuuliaiset ja teemme kaiken, mitä isämme Joonadab on käskenyt meidän tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Mutta kun Nebukadressar, Baabelin kuningas, hyökkäsi maahan, niin sanoimme: \'Tulkaa, menkäämme Jerusalemiin kaldealaisten sotajoukkoa ja aramilaisten sotajoukkoa pakoon\', ja asetuimme Jerusalemiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Silloin Jeremialle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, '\"Näin sanoo Herra Sebaot, Israelin Jumala: Mene ja sano Juudan miehille ja Jerusalemin asukkaille: Ettekö ota ojennusta varteen ja kuule minun sanojani? sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Joonadabin, Reekabin pojan, sanat, joilla hän kielsi poikiansa juomasta viiniä, pidetään voimassa, ja niin he eivät ole juoneet tähän päivään asti, sillä he ovat kuuliaisia isänsä käskylle. Mutta minä olen puhunut teille aamuvarhaisesta alkaen, ja te ette ole kuulleet minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Olen lähettänyt teidän luoksenne kaikki palvelijani, profeetat, aamuvarhaisesta alkaen, sanoen: Kääntykää kukin pahalta tieltänne ja parantakaa tekonne, älkää seuratko muita jumalia älkääkä niitä palvelko, niin tulette asumaan siinä maassa, jonka olen antanut teille ja teidän isillenne. Mutta te ette ole kallistaneet korvaanne, ette ole kuulleet minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Joonadabin, Reekabin pojan, jälkeläiset ovat siis pitäneet voimassa isänsä käskyn, jonka hän heille antoi, mutta tämä kansa ei ole kuullut minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Sen tähden, näin sanoo Herra, Jumala Sebaot, Israelin Jumala: Katso, annan tulla Juudalle ja kaikille Jerusalemin asukkaille kaiken sen onnettomuuden, jolla olen heitä uhannut, koska he eivät kuulleet, kun puhuin heille, eivätkä vastanneet, kun heitä kutsuin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Mutta reekabilaisille Jeremia sanoi: \"Näin sanoo Herra Sebaot, Israelin Jumala: Koska olette olleet kuuliaisia isänne Joonadabin käskylle ja noudattaneet kaikkia hänen käskyjään ja tehneet kaiken, mitä hän käski teidän tehdä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'sen tähden, näin sanoo Herra Sebaot, Israelin Jumala: Joonadabin, Reekabin pojan, suvussa on aina oleva mies, joka seisoo kasvojeni edessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Juudan kuninkaan Joojakimin, Joosian pojan, neljäntenä hallitusvuotena tuli tämä sana Jeremialle Herralta ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, '\"Ota kirjakäärö ja kirjoita siihen kaikki sanat, jotka olen puhunut sinulle Israelista ja Juudasta ja kaikista pakanakansoista siitä päivästä asti, jolloin aloin sinulle puhua, Joosian päivistä, aina tähän päivään saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Ehkäpä Juudan heimo, kuultuaan kaiken sen onnettomuuden, jonka minä aion heille tuottaa, kääntyy, kukin pahalta tieltään, ja annan anteeksi heidän pahat tekonsa ja syntinsä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Silloin Jeremia kutsui Baarukin, Neerian pojan, ja Baaruk kirjoitti kirjakääröön Jeremian suusta kaikki ne sanat, jotka Herra oli hänelle puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Sitten Jeremia käski Baarukia sanoen: \"Minä olen estetty, en voi mennä Herran huoneeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Mene sinä ja lue kirjakääröstä, jonka olet kirjoittanut suustani, Herran sanat kansan kuullen Herran huoneessa paastopäivänä ja myös koko Juudan kuullen, niiden, jotka tulevat kaupungeistaan, on sinun ne julistettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Ehkäpä he rukouksessa lankeavat Herran eteen ja kääntyvät kukin pahalta tieltään. Sillä suuri on viha ja kiivaus, jonka Herra on julistanut tälle kansalle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Niin Baaruk, Neerian poika, teki kaikki, kuten profeetta Jeremia oli käskenyt hänen tehdä, ja luki kirjasta Herran sanat Herran huoneessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'Mutta Juudan kuninkaan Joojakimin, Joosian pojan, viidentenä hallitusvuotena, yhdeksännessä kuussa, oli kaikki Jerusalemin kansa ja kaikki se kansa, joka oli tullut Juudan kaupungeista Jerusalemiin, kutsuttu pitämään paastoa Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Silloin Baaruk luki kirjasta Jeremian sanat Herran huoneessa, kirjuri Gemarjan, Saafanin pojan, kammiossa ylemmässä esipihassa Herran huoneen uuden portin ovella kaiken kansan kuullen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Kun Miika, Gemarjan, Saafanin pojan, poika, oli kuullut kaikki Herran sanat kirjasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'hän meni alas kuninkaan linnaan, kirjurin kammioon, ja katso, siellä istuivat kaikki ruhtinaat: kirjuri Elisama ja Delaja, Semajan poika, ja Elnatan, Akborin poika, ja Gemarja, Saafanin poika, ja Sidkia, Hananjan poika, ja kaikki muut ruhtinaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Heille Miika ilmoitti kaikki sanat, jotka hän oli kuullut Baarukin lukevan kirjasta kansan kuullen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Kaikki ruhtinaat lähettivät Baarukin luo Jehudin, joka oli Netanjan poika, joka Selemjan poika, joka Kuusin poika, ja käskivät sanoa: \"Ota käteesi kirjakäärö, josta luit kansan kuullen, ja tule tänne.\" Niin Baaruk, Neerian poika, otti kirjakäärön käteensä ja meni heidän luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Silloin he sanoivat hänelle: \"Istu ja lue meidän kuultemme\", ja Baaruk luki heidän kuultensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Mutta kun he olivat kuulleet kaikki sanat, katsoivat he toisiinsa pelästyneinä ja sanoivat Baarukille: \"Meidän täytyy ilmoittaa kuninkaalle kaikki nämä sanat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Niin he kysyivät Baarukilta sanoen: \"Ilmoita meille, kuinka sinä kirjoitit kaikki nämä sanat hänen suustaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Baaruk vastasi heille: \"Hän saneli minulle suustaan kaikki nämä sanat, ja minä kirjoitin ne musteella kirjaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Ruhtinaat sanoivat Baarukille: \"Mene ja piiloudu, sinä ja Jeremia, älköönkä kukaan saako tietää, missä olette.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Niin he menivät kuninkaan luo esipihaan, mutta kirjakäärön he jättivät talteen kirjuri Elisaman kammioon, ja he puhuivat kaikki nämä sanat kuninkaan kuullen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Kuningas lähetti Jehudin hakemaan kirjakäärön, ja hän haki sen kirjuri Elisaman kammiosta. Jehudi luki sen kuninkaan kuullen ja kaikkien ruhtinaiden kuullen, jotka seisoivat kuninkaan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Mutta kuningas istui talvihuoneessa – oli yhdeksäs kuukausi – ja hänen edessään oli palamassa hiilipannu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Aina kun Jehudi oli lukenut kolme tai neljä palstaa, leikkasi kuningas ne pois kirjurinveitsellä ja heitti tuleen, joka oli hiilipannussa, kunnes koko kirjakäärö oli palanut loppuun tulessa, joka oli hiilipannussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Mutta ei kuningas eikä kukaan hänen palvelijoistaan, jotka kuulivat kaikki nämä sanat, pelästynyt eikä reväissyt vaatteitaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Vaikka Elnatan, Delaja ja Gemarja olivat pyytäneet hartaasti kuningasta, ettei hän polttaisi kirjakääröä, hän ei heitä kuullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Kuningas käski Jerahmeelin, kuninkaan pojan, ja Serajan, Asrielin pojan, ja Selemjan, Abdeelin pojan, ottaa kiinni kirjuri Baarukin ja profeetta Jeremian, mutta Herra kätki heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Mutta sen jälkeen kun kuningas oli polttanut kirjakäärön sekä sanat, jotka Baaruk oli kirjoittanut Jeremian suusta, Jeremialle tuli tämä Herran sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, '\"Ota vielä itsellesi toinen kirjakäärö ja kirjoita siihen kaikki entiset sanat, jotka olivat edellisessäkin kirjakäärössä, jonka Juudan kuningas Joojakim poltti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Sano Juudan kuninkaasta Joojakimista: Näin sanoo Herra: Sinä olet polttanut tämän kirjakäärön sanoen: \'Miksi olet kirjoittanut siihen näin: Baabelin kuningas on tuleva ja hävittävä tämän maan ja lopettava siitä ihmiset ja eläimet?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Sen tähden Herra sanoo Juudan kuninkaasta Joojakimista näin: Hänellä ei ole oleva ketään, joka istuisi Daavidin valtaistuimella, ja hänen ruumiinsa heitetään pois virumaan päivän helteessä ja yön kylmyydessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Rankaisen häntä ja hänen jälkeläisiään ja hänen palvelijoitaan heidän pahojen tekojensa tähden. Annan tulla heille ja Jerusalemin asukkaille ja Juudan miehille kaiken sen onnettomuuden, jonka heille julistin, mutta jota he eivät kuulleet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Sitten Jeremia otti toisen kirjakäärön ja antoi sen kirjuri Baarukille, Neerian pojalle; ja tämä kirjoitti siihen Jeremian suusta kaikki sen kirjan sanat, jonka Juudan kuningas Joojakim oli tulessa polttanut. Sitten niihin lisättiin vielä paljon samanlaisia sanoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Sidkia, Joosian poika, tuli kuninkaaksi Konjan, Joojakimin pojan, sijaan. Hänet Nebu-kadressar, Baabelin kuningas, asetti kuninkaaksi Juudan maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Mutta ei hän eivätkä hänen palvelijansa eikä maan kansa totelleet Herran sanoja, jotka hän puhui profeetta Jeremian kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Kuningas Sidkia lähetti Juukalin, Selemjan pojan, ja pappi Sefanjan, Maasejan pojan, profeetta Jeremian luo sanoen: \"Rukoile puolestamme Herraa, Jumalaamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Silloin vielä Jeremia tuli ja meni kansan keskellä, sillä häntä ei ollut pantu vankilaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Faraon sotajoukko oli lähtenyt liikkeelle Egyptistä, mutta kun kaldealaiset, jotka piirittivät Jerusalemia, kuulivat siitä sanoman, he lähtivät pois Jerusalemin kimpusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Silloin tuli profeetta Jeremialle tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, '\"Näin sanoo Herra, Israelin Jumala: Sanokaa näin Juudan kuninkaalle, joka on lähettänyt teidät luokseni kysymään minulta neuvoa: Katso, faraon sotajoukko, joka on lähtenyt avuksenne, palaa takaisin maahansa Egyptiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'Sitten kaldealaiset tulevat takaisin ja sotivat tätä kaupunkia vastaan, valloittavat sen ja polttavat tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Näin sanoo Herra: Älkää pettäkö itseänne sanoen: \'Kaldealaiset varmasti lähtevät pois kimpustamme.\' Sillä he eivät lähde.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Vaikka te voittaisitte koko kaldealaisten sotajoukon, joka sotii teitä vastaan, niin ettei heistä jäisi jäljelle kuin muutamia haavoitettuja miehiä, niin he nousisivat pystyyn kukin teltassaan ja polttaisivat tulella tämän kaupungin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Mutta kun kaldealaisten sotajoukko faraon sotajoukon tähden oli lähtenyt pois Jerusalemia piirittämästä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'Jeremia lähti Jerusalemista mennäkseen Benjaminin maahan ottamaan jaossa osansa sieltä kansan keskuudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Kun hän oli tullut Benjaminin portille, siinä oleva vartiopäällikkö, jonka nimi oli Jiiria, Selemjan, Hananjan pojan, poika, tarttui profeetta Jeremiaan sanoen: \"Sinä aiot karata kaldealaisten puolelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Jeremia vastasi: \"Se on valhe! Minä en karkaa kaldealaisten puolelle.\" Mutta Jiiria ei kuunnellut häntä, vaan otti Jeremian kiinni ja vei hänet ruhtinaiden luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Ruhtinaat vihastuivat Jeremiaan ja löivät häntä ja panivat hänet vankilaan kirjuri Joonatanin taloon, sillä he olivat tehneet siitä vankilan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Jeremia joutui vankiluolaan ja holveihin, ja Jeremia jäi sinne moniksi päiviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Kuningas Sidkia lähetti hakemaan häntä, ja kuningas kysyi häneltä salaa linnassaan ja sanoi: \"Onko sanaa Herralta?\" Jeremia vastasi: \"On.\" Niin hän sanoi: \"Sinut annetaan Baabelin kuninkaan käsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Jeremia sanoi kuningas Sidkialle: \"Mitä minä olen rikkonut sinua ja palvelijoitasi vastaan ja tätä kansaa vastaan, koska te olette panneet minut vankilaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Missä ovat teidän profeettanne, jotka profetoivat teille sanoen: \'Baabelin kuningas ei tule teidän kimppuunne eikä tämän maan kimppuun\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Kuule nyt, herrani kuningas, salli minun pyyntöni langeta eteesi äläkä lähetä minua takaisin kirjuri Joonatanin taloon sinne kuolemaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Kuningas Sidkia käski säilyttää Jeremiaa vankilan pihassa, ja hänelle annettiin leipäkakku päivässä Leipurienkadulta, kunnes kaikki leipä oli kaupungista loppunut. Jeremia jäi vankilan pihaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Mutta Sefatja, Mattanin poika, ja Gedalja, Pashurin poika, ja Juukal, Selemjan poika, ja Pashur, Malkian poika, kuulivat ne sanat, jotka Jeremia puhui kaikelle kansalle, ja ne kuuluivat:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, '\"Näin sanoo Herra: Se, joka jää tähän kaupunkiin, kuolee miekkaan, nälkään ja ruttoon. Mutta se, joka menee kaldealaisten luo, elää, pitää henkensä saaliinaan ja hän jää eloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Näin sanoo Herra: Tämä kaupunki totisesti annetaan Baabelin kuninkaan sotajoukon käsiin, ja hän valloittaa sen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Ruhtinaat sanoivat kuninkaalle: \"Tämä mies kuolkoon, sillä hän herpaisee niiden sotamiesten kädet, jotka ovat jäljellä tässä kaupungissa, ja kaiken kansan kädet, kun hän puhuu heille tällaisia sanoja. Sillä tämä mies ei etsi tämän kansan menestystä, vaan onnettomuutta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Kuningas Sidkia vastasi: \"Katso, hän on teidän käsissänne. Sillä eihän kuningas voi mitään teitä vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Silloin he ottivat Jeremian ja heittivät hänet Malkian, kuninkaan pojan, kaivoon, joka oli vankilan pihassa, laskivat Jeremian köysillä alas. Mutta kaivossa ei ollut vettä, vaan liejua, ja Jeremia vajosi liejuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Mutta kuusilainen Ebed-Melek, hoviherra, joka oli kuninkaan linnassa, kuuli, että he olivat panneet Jeremian kaivoon. Mutta kuningas istui Benjaminin portissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Niin Ebed-Melek lähti kuninkaan linnasta ja puhutteli kuningasta sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, '\"Herrani, kuningas! Nuo miehet ovat pahoin tehneet kaikessa, mitä ovat tehneet profeetta Jeremialle: he ovat heittäneet hänet kaivoon, kuolemaan nälkään siihen paikkaansa.\" Sillä kaupungissa ei ollut enää leipää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Silloin kuningas käski kuusilaista Ebed-Melekiä sanoen: \"Ota mukaasi täältä kolmekymmentä miestä ja nosta profeetta Jeremia kaivosta, ennen kuin hän kuolee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Niin Ebed-Melek otti miehet mukaansa ja meni kuninkaan linnaan, aarrekammion alla olevaan paikkaan, ja otti sieltä rikkinäisiä ja kuluneita riepuja ja laski ne köysillä Jeremialle kaivoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Kuusilainen Ebed-Melek sanoi Jeremialle: \"Pane nämä rikkinäiset ja kuluneet rievut kainaloihisi köysien alle\", ja Jeremia teki niin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'He vetivät Jeremian ylös ja nostivat hänet kaivosta, ja Jeremia jäi vankilan pihaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Mutta kuningas Sidkia lähetti hakemaan profeetta Jeremian luokseen Herran temppelin kolmanteen sisäänkäytävään. Kuningas sanoi Jeremialle: \"Minä kysyn sinulta jotakin. Älä salaa minulta mitään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Jeremia vastasi Sidkialle: \"Jos sinulle jotakin ilmoitan, sinä totisesti surmautat minut. Mutta jos sinua neuvon, et minua kuule.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Kuningas Sidkia vannoi salaa Jeremialle sanoen: \"Niin totta kuin Herra elää, joka on luonut tämän meidän elämämme: minä en sinua surmauta enkä jätä sinua näiden miesten käsiin, jotka etsivät henkeäsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Silloin Jeremia sanoi Sidkialle: \"Näin sanoo Herra, Jumala Sebaot, Israelin Jumala: Jos sinä tosiaan lähdet Baabelin kuninkaan ruhtinaiden luo, henkesi säilyy, eikä tätä kaupunkia polteta tulella, ja sinä ja huoneesi jäätte eloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Mutta jos et mene Baabelin kuninkaan ruhtinaiden luo, niin tämä kaupunki annetaan kaldealaisten käsiin, ja he polttavat sen tulella, etkä sinäkään pelastu heidän käsistään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Silloin kuningas Sidkia sanoi Jeremialle: \"Minä pelkään niitä juutalaisia, jotka ovat menneet kaldealaisten puolelle, pelkään, että minut jätetään heidän käsiinsä ja he pitävät minua pilkkanaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Mutta Jeremia sanoi: \"Ei jätetä. Kuule vain Herran ääntä, kuule, mitä minä sinulle puhun, niin sinun käy hyvin, ja pysyt hengissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Mutta jos sinä et mene, niin tämä on se sana, jonka Herra on minulle näyttänyt:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Katso, kaikki naiset, jotka ovat jäljellä Juudan kuninkaan linnassa, viedään Baabelin kuninkaan ruhtinaiden luokse, ja katso, he sanovat: \'Miesystäväsi ovat sinut viekoitelleet ja saaneet sinut valtaansa; sinun jalkasi vajosivat liejuun – he vetäytyivät pois.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Niin kaikki sinun vaimosi ja lapsesi viedään kaldealaisille, etkä sinä pelastu näiden käsistä, vaan Baabelin kuninkaan käsi tarttuu sinuun, ja sinä saatat tämän kaupungin tulella poltettavaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Silloin Sidkia sanoi Jeremialle: \"Älköön kukaan saako tietää näistä sanoista, muuten sinä kuolet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Mutta jos ruhtinaat kuulevat, että minä olen puhunut kanssasi, ja tulevat luoksesi ja sanovat sinulle: \'Ilmoita meille, mitä olet puhunut kuninkaalle ja mitä kuningas on puhunut sinulle – älä salaa sitä meiltä, muuten me surmaamme sinut\' –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'niin sano heille: \'Minä annoin rukoukseni langeta kuninkaan eteen, ettei hän lähettäisi minua takaisin Joonatanin taloon, kuolemaan sinne.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Kaikki ruhtinaat tulivat Jeremian luo ja kysyivät häneltä, ja hän ilmoitti heille kaiken, mitä kuningas oli käskenyt hänen ilmoittaa. He jättivät hänet rauhaan, sillä asiasta ei ollut mitään kuultu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Jeremia jäi olemaan vankilan pihaan siihen päivään asti, jona Jerusalem valloitettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Juudan kuninkaan Sidkian yhdeksäntenä hallitusvuotena, kymmenennessä kuussa, oli Nebukadressar, Baabelin kuningas, kaikkine sotajoukkoineen hyökännyt Jerusalemin kimppuun ja saartanut sen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'ja Sidkian yhdentenätoista hallitusvuotena, neljännessä kuussa, kuukauden yhdeksäntenä päivänä, kaupunki oli vallattu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, '– Niin kaikki Baabelin kuninkaan ruhtinaat tulivat ja asettuivat Keskiporttiin: Neergal-Sareser, Samgar-Nebo, Sarsekim, ylimmäinen hoviherra, Neergal-Sareser, ylimmäinen tietäjä, ja kaikki muut Baabelin kuninkaan ruhtinaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Kun Sidkia, Juudan kuningas, ja kaikki sotilaat näkivät heidät, he pakenivat ja lähtivät yöllä kaupungista kuninkaan puutarhaa kohti molempien muurien välisestä portista, ja hän lähti Aromaahan päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Mutta kaldealaisten sotajoukko ajoi heitä takaa, ja he saavuttivat Sidkian Jerikon aroilla. Niin he ottivat hänet kiinni ja veivät hänet Nebukadressarin, Baabelin kuninkaan, eteen Riblaan, joka on Hamatin maassa, ja tämä julisti hänelle tuomiot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Baabelin kuningas surmautti Sidkian pojat Riblassa hänen silmiensä edessä. Myös kaikki Juudan ylimykset Baabelin kuningas surmautti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Hän sokaisi Sidkian silmät ja sitoi hänet vaskikahleilla viedäkseen hänet Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Kuninkaan linnan ja kansan talot kaldealaiset polttivat tulella, ja Jerusalemin muurit he repivät maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Loput kansasta, jotka olivat jäljellä kaupungissa, sekä ne, jotka olivat menneet hänen puolelleen – loput kansasta, jotka olivat jäljellä – vei Nebusaradan, henkivartijoiden päällikkö, karkotukseen Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Mutta köyhimmät kansasta, joilla ei ollut mitään, Nebusaradan, henkivartijoiden päällikkö, jätti Juudan maahan ja antoi heille sinä päivänä viinitarhoja ja peltoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Nebukadressar, Baabelin kuningas, oli antanut Nebusaradanille, henkivartijoiden päällikölle, Jeremiasta tämän käskyn:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, '\"Ota hänet ja pidä hänestä huoli. Älä tee hänelle mitään pahaa, vaan tee hänelle niin, kuin hän itse sinulle sanoo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Silloin lähettivät Nebusaradan, henkivartijoiden päällikkö, Nebusasban, ylimmäinen hoviherra, Neergar-Sareser, ylimmäinen tietäjä, ja kaikki muut Baabelin kuninkaan päälliköt');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, '– nämä lähettivät noutamaan Jeremian vankilan pihasta ja antoivat hänet Gedaljalle, Saafanin pojan Ahikamin pojalle, että tämä veisi hänet kotiin, ja niin hän jäi kansan keskuuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Jeremialle oli tullut tämä Herran sana hänen ollessaan suljettuna vankilan pihaan ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, '\"Mene ja sano kuusilaiselle Ebed-Melekille näin: Näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä toteutan sanani tälle kaupungille onnettomuudeksi enkä onneksi. Tämä tapahtuu sinun edessäsi sinä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Mutta sinut pelastan sinä päivänä, sanoo Herra, etkä sinä joudu niiden miesten käsiin, joita pelkäät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Sillä pelastan sinut, niin ettet kaadu miekkaan, vaan saat pitää henkesi saaliinasi, sillä sinä turvasit minuun, sanoo Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Sana, joka tuli Jeremialle Herralta, sen jälkeen kun Nebusaradan, henkivartijoiden päällikkö, oli päästänyt hänet menemään Raamasta, jonne hän oli haettanut hänet, kun hän oli kahleilla sidottuna kaikkien Baabeliin siirrettävien Jerusalemin ja Juudan karkotettujen joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Henkivartijoiden päällikkö haetti Jeremian ja sanoi hänelle: \" Herra, sinun Jumalasi, on julistanut tämän onnettomuuden tälle paikalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'ja Herra on antanut sen tapahtua ja on tehnyt, kuten on puhunut. Sillä te olette tehneet syntiä Herraa vastaan ettekä ole kuulleet hänen ääntään, ja niin tämä sana kävi teille toteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Katso, nyt tänä päivänä päästän sinut kahleista, jotka ovat käsissäsi. Jos näet hyväksi lähteä kanssani Baabeliin, lähde, ja minä pidän sinusta huolen. Mutta jos et näe hyväksi lähteä kanssani Baabeliin, älä lähde. Katso, koko maa on edessäsi. Minne näet hyväksi ja oikeaksi mennä, sinne mene.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Mutta kun tämä ei ollut vielä lähtenyt takaisin, hän sanoi: \"Palaa Gedaljan luo, joka on Saafanin pojan Ahikamin poika, hänen, jonka Baabelin kuningas on asettanut Juudan kaupunkien käskynhaltijaksi, ja jää hänen luokseen kansan keskuuteen, tai mene, minne vain näet oikeaksi mennä.\" Niin henkivartijoiden päällikkö antoi hänelle evästä ja lahjoja ja päästi hänet menemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Jeremia meni Gedaljan, Ahikamin pojan, luo Mispaan ja asui hänen luonaan maahan jääneen kansan keskuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Kun kaikki sotaväen päälliköt, jotka olivat maaseudulla, he ja heidän sotamiehensä, kuulivat, että Baabelin kuningas oli asettanut Gedaljan, Ahikamin pojan, käskynhaltijaksi maahan ja jättänyt hänen haltuunsa ne miehet, vaimot ja lapset sekä ne maan köyhät, joita ei ollut siirretty Baabeliin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'he tulivat Gedaljan luo Mispaan: Ismael, Netanjan poika, Joohanan ja Joonatan, Kaareahin pojat, Seraja, Tanhumetin poika, netofalaisen Eefain pojat ja Jesanja, maakatilaisen poika, he ja heidän sotamiehensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Gedalja, Saafanin pojan Ahikamin poika, vannoi heille ja heidän miehilleen sanoen: \"Älkää pelätkö palvella kaldealaisia. Asukaa maassa ja palvelkaa Baabelin kuningasta, niin teidän käy hyvin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Katso, minä itse asun Mispassa palvellakseni niitä kaldealaisia, jotka tulevat luoksemme. Mutta te kootkaa viiniä ja hedelmiä ja öljyä ja pankaa astioihinne ja asukaa kaupungeissanne, jotka olette ottaneet haltuunne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Kaikki nekin juutalaiset, jotka olivat Mooabissa ja ammonilaisten keskuudessa ja Edomissa sekä kaikissa muissa maissa, saivat kuulla, että Baabelin kuningas oli jättänyt Juudaan jäännöksen ja asettanut näille käskynhaltijaksi Gedaljan, joka oli Saafanin pojan Ahikamin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Kaikki juutalaiset palasivat takaisin kaikista paikoista, joihin heitä oli karkotettu, ja tulivat Juudan maahan Mispaan, Gedaljan luo, ja korjasivat viiniä ja hedelmiä hyvin runsaasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Mutta Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt, jotka olivat maaseudulla, tulivat Gedaljan luo Mispaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'ja sanoivat hänelle: \"Tiedätkö tosiaan, että ammonilaisten kuningas Baalis on lähettänyt Ismaelin, Netanjan pojan, lyömään sinut kuoliaaksi?\" Mutta Gedalja, Ahikamin poika, ei uskonut heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Silloin Joohanan, Kaareahin poika, sanoi Gedaljalle Mispassa salaa näin: \"Minäpä menen ja lyön kuoliaaksi Ismaelin, Netanjan pojan, kenenkään tietämättä! Miksi hän saa lyödä sinut kuoliaaksi, niin että kaikki juutalaiset, jotka ovat kokoontuneet luoksesi, hajaantuvat ja Juudan jäännös hukkuu?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Mutta Gedalja, Ahikamin poika, vastasi Joohananille, Kaareahin pojalle: \"Älä tee mitä sanoit, sillä sinä puhut valhetta Ismaelista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Mutta seitsemännessä kuussa Ismael, Elisaman pojan Netanjan poika, joka oli kuninkaallista sukua ja kuninkaan ylimmäisiä, tuli Gedaljan, Ahikamin pojan, luo Mispaan kymmenen miestä mukanaan. Siellä Mispassa he söivät leipää yhdessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Ismael, Netanjan poika, sekä ne kymmenen miestä, jotka olivat hänen kanssaan, nousivat ja he löivät miekalla kuoliaaksi Gedaljan, joka oli Saafanin pojan Ahikamin poika. Ismael surmasi hänet, jonka Baabelin kuningas oli asettanut käskynhaltijaksi maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Myös kaikki juutalaiset, jotka olivat Gedaljan luona Mispassa, sekä kaldealaiset, jotka sieltä tavattiin, ja sotamiehet, Ismael löi kuoliaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Seuraavana päivänä, sen jälkeen kun hän oli surmannut Gedaljan, kun ei kukaan sitä vielä tietänyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'Sikemistä, Siilosta ja Samariasta tuli kahdeksankymmentä miestä, parta ajettuna, vaatteet revittyinä ja iho viileskeltynä, ja heillä oli käsissään ruokauhreja ja suitsutusta vietäväksi Herran huoneeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Niin Ismael, Netanjan poika, lähti Mispasta heitä vastaan itkien lakkaamatta kulkiessaan. Kun hän kohtasi heidät, hän sanoi heille: \"Tulkaa Gedaljan, Ahikamin pojan, luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Mutta kun he olivat tulleet keskelle kaupunkia, Ismael, Netanjan poika, ja ne miehet, jotka olivat hänen kanssaan, surmasivat heidät ja heittivät heidät kaivoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Mutta heidän joukossaan oli kymmenen miestä, jotka sanoivat Ismaelille: \"Älä surmaa meitä, sillä meillä on kedolla kätkössä vehnää, ohraa, öljyä ja hunajaa.\" Hän jätti sen tekemättä eikä surmannut heitä heidän veljiensä joukkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Kaivo, johon Ismael heitti kaikkien niiden miesten ruumiit, jotka hän oli lyönyt kuoliaaksi Gedaljan tähden, oli se, jonka kuningas Aasa oli teettänyt Baesan, Israelin kuninkaan, pelosta. Sen Ismael, Netanjan poika, täytti nyt surmatuilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Sitten Ismael otti vangeiksi kaikki kansan tähteet, mitä Mispassa oli, kuninkaan tyttäret ja kaiken Mispaan jäljelle jääneen kansan, jonka käskynhaltijaksi Nebusaradan, henkivartijoiden päällikkö, oli asettanut Gedaljan, Ahikamin pojan. Heidät Ismael, Netanjan poika, otti vangeiksi ja lähti kulkemaan siirtyäkseen yli ammonilaisten luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Mutta Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt, jotka olivat hänen kanssaan, saivat kuulla kaiken sen pahan, minkä Ismael, Netanjan poika, oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'He ottivat kaikki miehensä ja lähtivät taistelemaan Ismaelia, Netanjan poikaa, vastaan, ja he tapasivat hänet suurilta vesiltä, jotka ovat Gibeonissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Mutta kun kaikki kansa, joka oli Ismaelin mukana, näki Joohananin, Kaareahin pojan, ja kaikki sotaväen päälliköt, jotka olivat hänen kanssaan, niin he ilahtuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'Niin kaikki kansa, jonka Ismael oli ottanut vangiksi Mispasta, kääntyi takaisin ja meni Joohananin, Kaareahin pojan, puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Mutta Ismael, Netanjan poika, pääsi kahdeksan miehen kanssa Joohanania pakoon ja lähti ammonilaisten luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Niin Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt, jotka olivat hänen kanssaan, ottivat kaikki kansan tähteet, jotka hän oli palauttanut Ismaelin, Netanjan pojan, luota Mispasta, sen jälkeen kun tämä oli lyönyt Gedaljan, Ahikamin pojan, kuoliaaksi. Heitä oli miehiä, sotilaita, naisia ja lapsia ja hoviherroja, jotka hän oli palauttanut Gibeonista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'Sitten he kulkivat, mutta pysähtyivät Kimhamin majapaikkaan, joka on lähellä Beetlehemiä, lähteäkseen Egyptiin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'kaldealaisia pakoon, sillä he pelkäsivät heitä, koska Ismael, Netanjan poika, oli lyönyt kuoliaaksi Gedaljan, Ahikamin pojan, jonka Baabelin kuningas oli asettanut käskynhaltijaksi maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Kaikki sotaväen päälliköt ja Joohanan, Kaareahin poika, ja Jesanja, Hoosajan poika, sekä kaikki kansa, pienimmästä suurimpaan, astuivat esiin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'ja sanoivat profeetta Jeremialle: \"Langetkoon pyyntömme eteesi, ja rukoile puolestamme Herraa, Jumalaasi, kaiken tämän jäännöksen puolesta, sillä suuresta luvusta meitä on jäänyt jäljelle vain vähän, niin kuin omat silmäsi näkevät meitä olevan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'Herra, sinun Jumalasi, ilmoittakoon meille, mitä tietä meidän on kuljettava, ja sanan, jota meidän on noudatettava.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Silloin profeetta Jeremia vastasi heille: \"Minä kuulen. Katso, minä rukoilen Herraa, teidän Jumalaanne, niin kuin sanotte, ja kaiken sen, mitä Herra teille vastaa, ilmoitan teille enkä salaa teiltä mitään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'He sanoivat Jeremialle: \"Olkoon Herra totuudellinen ja luotettava todistaja meitä vastaan, jos emme tee aivan sen sanan mukaan, jonka Herra, sinun Jumalasi, lähettää sinut meille tuomaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Olkoon se hyvä tai paha: Herran, meidän Jumalamme ääntä, jonka luo me sinut lähetämme, tottelemme, että meidän kävisi hyvin, kun tottelemme Herran, meidän Jumalamme, ääntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Kymmenen päivän kuluttua Herran sana tuli Jeremialle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'ja hän kutsui Joohananin, Kaareahin pojan, ja kaikki sotaväen päälliköt, jotka olivat tämän kanssa, sekä kaiken kansan, pienimmästä suurimpaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'Hän sanoi heille: \"Näin sanoo Herra, Israelin Jumala, jonka luo te lähetitte minut laskemaan rukouksenne hänen eteensä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Jos tosiaan jäätte tähän maahan, rakennan teidät enkä hajota maahan, istutan teidät enkä revi pois, sillä kadun sitä onnettomuutta, jonka olen tuottanut teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Älkää pelätkö Baabelin kuningasta, jota te nyt pelkäätte. Älkää pelätkö häntä, sanoo Herra, sillä minä olen teidän kanssanne, minä autan teitä ja pelastan teidät hänen käsistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Annan teille armon, niin että hän armahtaa teitä ja antaa teidän palata takaisin maahanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Mutta jos te sanotte: \'Me emme jää tähän maahan\', ettekä tottele Herran, Jumalanne, ääntä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'vaan sanotte: \'Ei! Menemme Egyptiin, jossa emme näe sotaa, kuule torven ääntä emmekä kärsi leivän nälkää, ja sinne me jäämme asumaan\' –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'niin kuulkaa siis nyt Herran sana, te Juudan tähteet: Näin sanoo Herra Sebaot, Israelin Jumala: Jos te todella käännätte kasvonne Egyptiä kohti ja menette sinne asumaan muukalaisina,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'niin miekka, jota te pelkäätte, saavuttaa teidät siellä Egyptin maassa, ja nälkä, joka teitä huolettaa, seuraa perässänne Egyptiin, ja sinne te kuolette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Kaikki ne miehet, jotka kääntävät kasvonsa Egyptiä kohti asuakseen siellä muukalaisina, kuolevat miekkaan, nälkään ja ruttoon, eikä kukaan heistä pääse pakoon eikä pelastu siitä onnettomuudesta, jonka minä annan heille tulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Niin kuin vihani ja kiivauteni on vuodatettu Jerusalemin asukasten päälle, niin kiivastukseni vuotaa teidänkin päällenne, jos menette Egyptiin, ja tulette kiroukseksi ja kauhistukseksi, kirosanaksi ja häväistykseksi ettekä enää näe tätä paikkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Herra sanoo teille, te Juudan tähteet: Älkää menkö Egyptiin. Se tosiaan tietäkää, että olen tänä päivänä teitä varoittanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Eksytitte itsenne, kun te lähetitte minut Herran, teidän Jumalanne, luo sanoen: \'Rukoile puolestamme Herraa, meidän Jumalaamme; ja kaikki, mitä Herra, meidän Jumalamme, sanoo, ilmoita meille, niin me teemme sen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Olen sen tänä päivänä teille ilmoittanut, mutta te ette kuulleet Herran, teidän Jumalanne, ääntä kaikessa, mitä varten hän lähetti minut teidän luoksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Nyt siis totisesti tietäkää, että te kuolette miekkaan, nälkään ja ruttoon siinä paikassa, johon te haluatte mennä siellä muukalaisina asumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Mutta kun Jeremia oli loppuun asti puhunut kaikelle kansalle kaikki Herran, heidän Jumalansa, sanat, jotka Herra, heidän Jumalansa, oli lähettänyt hänet tuomaan heille – kaikki ne sanat –,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'niin Asarja, Hoosajan poika, ja Joohanan, Kaareahin poika, ja kaikki julkeat miehet sanoivat Jeremialle: \"Sinä puhut valhetta. Herra, meidän Jumalamme, ei ole lähettänyt sinua sanomaan: \'Älkää menkö Egyptiin asumaan siellä muukalaisina\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'vaan Baaruk, Neerian poika, kiihottaa sinua meitä vastaan antaakseen meidät kaldealaisten käsiin tapettaviksi tai vietäviksi karkotukseen Baabeliin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Joohanan, Kaareahin poika, kaikki sotaväen päälliköt ja kaikki kansa olivat tottelemattomia Herran äänelle eivätkä jääneet Juudan maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt ottivat kaikki Juudan tähteet, jotka olivat kaikista kansakunnista, jonne heidät oli karkotettu, ja jotka olivat palanneet asumaan Juudan maahan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'miehet, naiset ja lapset, kuninkaan tyttäret ja kaiken sen väen, jonka Nebusaradan, henkivartijoiden päällikkö, oli jättänyt Gedaljan huostaan, joka oli Saafanin pojan Ahikamin poika, sekä profeetta Jeremian ja Baarukin, Neerian pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'He menivät Egyptin maahan, sillä he eivät kuulleet Herran ääntä, ja tulivat Tahpanheeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Tämä Herran sana tuli Jeremialle Tahpanheessa, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, '\"Ota käsiisi suuria kiviä ja kätke ne muurilaastiin, tiilikivipenkereeseen, joka on faraon linnan oven edustalla Tahpanheessa, juutalaisten miesten nähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'Sano sitten heille: Näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä lähetän hakemaan palvelijani Nebukadressarin, Baabelin kuninkaan, ja asetan hänen valtaistuimensa näiden kivien päälle, jotka olen kätkenyt, ja hän panee niiden päälle kuninkaallisen paviljonkinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Hän tulee ja lyö Egyptin maata: sitä, joka on oleva kuoleman oma, kuolemalla, sitä, joka on oleva vankeuden oma, vankeudella, ja miekalla sitä, joka on oleva miekan oma!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Sytytän Egyptin jumalien huoneet tuleen, ja Baabelin kuningas polttaa ne ja vie jumalat pois. Hän pukee päälleen Egyptin maan, niin kuin paimen pukeutuu vaatteeseensa, ja lähtee sieltä rauhassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Hän murskaa patsaat Egyptin maan Beet-Semeksestä, ja Egyptin jumalien huoneet hän polttaa tulella.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Sana, joka tuli Jeremialle kaikista niistä juutalaisista, jotka asuivat Egyptin maassa, nimittäin Migdolissa, Tahpanheessa, Noofissa ja Patroksen maakunnassa. Se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, '\"Näin sanoo Herra Sebaot, Israelin Jumala: Te olette nähneet kaiken sen onnettomuuden, jonka olen tuottanut Jerusalemille ja kaikille Juudan kaupungeille. Katso, ne ovat nyt raunioina, eikä niissä asu ketään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'heidän pahuutensa tähden, jota he tekivät, vihoittaen minut, kun menivät ja polttivat uhreja muille jumalille, palvelivat niitä, joita he eivät tunteneet, eivät he ettekä te eivätkä teidän isänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Aamuvarhaisesta alkaen minä lähetin teidän luoksenne kaikki palvelijani, profeetat, sanomaan: \'Älkää tehkö näitä kauhistuksia, joita minä vihaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Mutta he eivät kuulleet eivätkä sille korvaansa kallistaneet, niin että olisivat kääntyneet pois pahuudestaan ja lakanneet polttamasta uhreja muille jumalille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Kiivauteni ja vihani vuoti alas ja paloi Juudan kaupungeissa ja Jerusalemin kaduilla, ja ne tulivat raunioiksi ja autioiksi, niin kuin ne tänä päivänä ovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Nyt sanoo Herra, Jumala Sebaot, Israelin Jumala, näin: Miksi te tuotatte itsellenne suuren onnettomuuden, hävitätte miehet ja vaimot, lapset ja imeväiset Juudasta ettekä jätä itsestänne jäännöstäkään?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Vihoitatte minut kättenne teoilla, kun poltatte uhreja muille jumalille Egyptin maassa, johon olette tulleet asumaan täällä muukalaisina. Niin tuotatte itsellenne häviön ja tulette kirosanaksi ja häväistykseksi kaikissa maan kansoissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Oletteko unohtaneet isienne pahat teot, Juudan kuningasten pahat teot ja heidän vaimojensa pahat teot, omat pahat tekonne ja vaimojenne pahat teot, joita he tekivät Juudan maassa ja Jerusalemin kaduilla?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'He eivät ole murtuneet tähän päivään asti, eivät pelkää eivätkä vaella minun lakini ja minun käskyjeni mukaan, jotka olen antanut teille ja teidän isillenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Sen tähden, näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä käännän kasvoni teitä vastaan onnettomuudeksi hävittääkseni koko Juudan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Tempaan pois Juudan jäännöksen, ne jotka käänsivät kasvonsa Egyptin maata kohti mennäkseen siellä asumaan muukalaisina, ja heistä kaikista tulee loppu Egyptin maassa. He kaatuvat miekkaan ja menehtyvät nälkään. Pienimmästä suurimpaan asti he kuolevat miekkaan ja nälkään ja tulevat kiroukseksi, kauhistukseksi, kirosanaksi ja häväistykseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Rankaisen niitä, jotka asuvat Egyptin maassa, niin kuin rankaisin Jerusalemia, miekalla, nälällä ja rutolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'Ei jää pakoon päässeitä, ei pelastuneita Juudan jäännöksestä, niistä, jotka ovat tulleet asumaan muukalaisina täällä Egyptin maassa, eivätkä he palaa Juudan maahan, jonne heidän sielunsa jälleen kaipaa heidän siellä asuakseen. Sinne on näet palaava vain muutamia pakolaisia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Mutta kaikki miehet, jotka tiesivät vaimojensa polttavan uhreja muille jumalille, ja kaikki naiset, jotka seisoivat siellä suurena joukkona, ja kaikki kansa, joka asui Egyptin maassa, Patroksessa, vastasivat Jeremialle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, '\"Sanaa, jonka puhuit meille Herran nimessä, emme siinä sinua tottele,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'vaan me totisesti täytämme jokaisen lupauksen, mikä suustamme on lähtenyt, poltamme uhreja taivaan kuningattarelle ja vuodatamme hänelle juomauhreja, niin kuin teimme me ja meidän isämme, meidän kuninkaamme ja ruhtinaamme Juudan kaupungeissa ja Jerusalemin kaduilla. Silloin meillä oli leipää yltäkyllin, meidän oli hyvä olla emmekä nähneet onnettomuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Mutta siitä asti, kun lakkasimme polttamasta uhreja taivaan kuningattarelle ja vuodattamasta hänelle juomauhreja, osanam-me on ollut kaiken puute ja kuoleminen miekkaan ja nälkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Kun poltamme uhreja taivaan kuningattarelle ja vuodatamme hänelle juomauhreja, teemmekö ilman miestemme lupaa hänelle uhrikakkuja, hänen kuvansa muotoisia, ja vuodatamme hänelle juomauhreja?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Silloin Jeremia sanoi kaikelle kansalle, miehille ja naisille, kaikelle kansalle, joka oli hänelle näin vastannut:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, '\"Eikö sitä uhrisavua, jota olette suitsuttaneet Juudan kaupungeissa ja Jerusalemin kaduilla, te ja teidän isänne, teidän kuninkaanne ja ruhtinaanne ja maan kansa, Herra muista ja pidä mielessään?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Eikä Herra voinut sitä enää kärsiä teidän tekojenne pahuuden tähden, kauhistusten tähden, joita teitte, ja niin teidän maanne tuli raunioiksi ja autioksi ja kirosanaksi, tuli asumattomaksi, niin kuin se tänä päivänä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Sen tähden että te poltitte uhreja ja teitte syntiä Herraa vastaan, ette totelleet Herran ääntä ettekä vaeltaneet hänen lakinsa, käskyjensä ja todistustensa mukaan, sen tähden tämä onnettomuus on kohdannut teitä, niin kuin nyt on tapahtunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Jeremia sanoi vielä kaikelle kansalle ja kaikille naisille: \"Kuulkaa Herran sana, kaikki Juuda, joka olet Egyptin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Näin sanoo Herra Sebaot, Israelin Jumala: Mitä te ja teidän vaimonne olette suullanne puhuneet, sen te panette käsillänne täytäntöön, sanoen: \'Täytämme lupauksemme, joilla olemme luvanneet polttaa uhreja taivaan kuningattarelle ja vuodattaa hänelle juomauhreja.\' Niinpä pitäkää lupauksenne, pankaa lupauksenne täytäntöön!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Sen tähden kuulkaa Herran sana, kaikki Juuda, te jotka asutte Egyptin maassa: Katso, minä vannon suuren nimeni kautta, sanoo Herra: Totisesti yksikään Juudan mies ei ole enää mainitseva suullaan nimeäni, niin että sanoisi: \'Niin totta kuin Herra, Herra elää\' – ei koko Egyptin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Katso, valvon, mutta heille onnettomuudeksi, en onneksi. Jokainen Juudan mies, joka on Egyptin maassa, hukkuu miekkaan ja nälkään, kunnes heistä on tullut loppu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Vain vähäinen joukko miekasta pelastuneita palaa Egyptin maasta Juudan maahan. Silloin Juudan koko jäännös, ne jotka tulivat Egyptin maahan, asumaan siellä muukalaisina, tulevat tietämään, kumman sana toteutuu, minun vai heidän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'Tämä on oleva sen merkkinä, sanoo Herra, että minä rankaisen teitä tässä paikassa, tietääksenne, että minun sanani teitä vastaan tosiaan toteutuvat teille onnettomuudeksi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Näin sanoo Herra: Katso, annan farao Hofran, Egyptin kuninkaan, hänen vihollistensa käsiin, niiden käsiin, jotka etsivät hänen henkeään, kuten annoin Sidkian, Juudan kuninkaan, Nebukadressarin, Baabelin kuninkaan, käsiin, joka oli hänen vihollisensa ja etsi hänen henkeään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Sana, jonka profeetta Jeremia puhui Baarukille, Neerian pojalle, kun tämä kirjoitti nämä sanat kirjaan Jeremian suusta Juudan kuninkaan Joojakimin, Joosian pojan, neljäntenä hallitusvuotena. Se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, '\"Näin sanoo Herra, Israelin Jumala, sinusta, Baaruk:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Sinä sanot: \'Voi minua! Sillä Herra on antanut minulle murhetta kipuni lisäksi; olen uupunut huokaamisestani enkä löydä lepoa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Sano hänelle näin: Näin sanoo Herra: Katso, minkä olen rakentanut, sen minä hajotan, ja minkä olen istuttanut, sen minä revin irti, ja se tapahtuu koko maalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'Sinä pyydät itsellesi suuria! Älä pyydä, sillä katso, tuotan onnettomuuden kaikelle lihalle, sanoo Herra. Mutta sinulle annan henkesi saaliiksi joka paikassa minne menetkin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Herran sana, joka tuli profeetta Jeremialle pakanakansoja koskien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Egyptiä koskien: Farao Nekon, Egyptin kuninkaan, sotajoukkoa koskien, joka oli Eufrat-virran rannalla Karkemiissa ja jonka Nebukadressar, Baabelin kuningas, voitti Juudan kuninkaan Joojakimin, Joosian pojan, neljäntenä hallitusvuotena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, '\"Pankaa kuntoon pienet ja suuret kilvet ja käykää taisteluun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Valjastakaa hevoset, nouskaa ratsaille, käykää esiin kypärät päässä. Kiillottakaa keihäät ja pukekaa päällenne haarniskat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Miksi näen heidän pelästyvän ja peräytyvän? Heidän sankarinsa sortuvat. He syöksyvät pakoon eivätkä käänny. Kauhu on kaikkialla, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Ei pääse nopea pakoon eikä sankari pelastu. Pohjoisessa Eufrat-virran luona he kompastuvat ja kaatuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Mikä on tuo, joka nousee kuin Niili, jonka vedet vyöryvät kuin virrat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Egypti nousee kuin Niili, sen vedet vyöryvät kuin virrat; se sanoo: \'Minä nousen ja peitän maan, hävitän kaupungin ja sen asukkaat.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Hyökätkää, hevoset, ajakaa hurjasti, vaunut! Lähtekööt liikkeelle sankarit, kuusilaiset ja puutilaiset, kilven käyttäjät, ja luudilaiset, jousen käyttäjät ja jousen jännittäjät!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Tämä päivä on Herran, Herran Sebaotin, päivä, koston päivä, jona hän kostaa vihollisilleen. Miekka syö, tulee kylläiseksi ja juopuu heidän verestään, kun Herralla, Herralla Sebaotilla, on uhriteurastus pohjoisessa maassa Eufrat-virran luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Nouse Gileadiin, hae balsamia, sinä neitsyt, tytär Egypti – turhaan sinä hankit paljon lääkkeitä: sinä et parane.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Kansat kuulevat häpeäsi, ja valitushuutosi täyttää maan, sillä sankari kompastuu sankariin ja yhdessä he molemmat kaatuvat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Tämä on se sana, jonka Herra puhui profeetta Jeremialle ja ilmoitti Nebukadressarin, Baabelin kuninkaan, tulevan lyömään Egyptin maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, '\"Julistakaa Egyptissä ja kuuluttakaa Migdolissa, kuuluttakaa Noofissa ja Tahpanheessa, ja sanokaa: \'Astu esiin, ole valmis, sillä miekka syö ympärilläsi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Miksi sankarisi ovat syöstyt maahan? He eivät pysyneet pystyssä, sillä Herra ajoi heidät pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Hän saattoi monet kompastumaan, ja he kaatuivat toinen toisensa päälle ja sanoivat: \'Nouse! Palatkaamme kansamme luo ja synnyinmaahamme hävittäjän miekkaa pakoon.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Siellä huudetaan: \'Farao, Egyptin kuningas, on hämillään! Hän on päästänyt määräaikansa menemään.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Niin totta kuin minä elän, sanoo kuningas – Herra Sebaot on hänen nimensä: hän tulee, hän joka on kuin Taabor vuorten joukossa ja kuin Karmel meren rannalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Tee itsellesi varusteet karkotusta varten, sinä Egyptissä asuva tytär, sillä Noof tulee autioksi ja hävitetään niin, ettei siinä ole asukkaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Hyvin kaunis nuori lehmä on Egypti. Paarma tulee pohjoisesta, se tulee!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Palkkasoturitkin, jotka sillä on keskellänsä, nuo syöttövasikoitten kaltaiset, kääntyvät nekin pakoon kaikki yhdessä. He eivät kestä. Heidän onnettomuutensa päivä on näet tullut heille ja on heidän rangaistuksensa aika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Ne pitävät mennessään ääntä kuin käärme, sillä ne tulevat sotavoimalla ja käyvät sen kimppuun kirveillä kuin puunkaatajat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'He kaatavat siltä metsän, sanoo Herra, tuon määrättömän suuren, sillä heitä on enemmän kuin heinäsirkkoja, ja he ovat lukemattomat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Häpeään joutuu tytär Egypti, hänet annetaan pohjoisen kansan käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Herra Sebaot, Israelin Jumala, sanoo: Katso, rankaisen Aamonia, joka on Noossa, niin myös faraota ja Egyptiä, sen jumalia ja sen kuninkaita, sekä faraota että niitä, jotka häneen turvaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'Annan heidät niiden käsiin, jotka etsivät heidän henkeään, Nebukadressarin, Baabelin kuninkaan, käsiin ja hänen palvelijoidensa käsiin. Mutta sen jälkeen siellä asutaan kuin entisinä aikoina, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Mutta sinä, palvelijani Jaakob, älä pelkää, älä arkaile, Israel. Sillä katso, pelastan sinut kaukaa ja jälkeläisesi heidän vankeutensa maasta. Jaakob palaa, elää rauhassa ja on turvassa eikä sillä ole pelättävää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Sinä, palvelijani Jaakob, älä pelkää, sanoo Herra, sillä minä olen kanssasi. Teen lopun kaikista kansoista, joiden sekaan sinut karkotin. Mutta sinusta en tee loppua. Kuritan sinua kohtuudella, mutta rankaisematta en sinua jätä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Herran sana filistealaisia vastaan, joka tuli profeetta Jeremialle, ennen kuin farao valloitti Gassan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, '\"Näin sanoo Herra: Katso, vedet nousevat pohjoisesta, ja niistä tulee tulvavirta. Ne tulvivat yli maan ja kaiken, mitä siinä on, yli kaupungin ja sen asukkaiden. Ihmiset huutavat ja kaikki maan asukkaat valittavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Kun kuuluu hänen hevostensa kavioiden töminä, hänen vaunujensa jyrinä ja hänen rattaittensa ryske, isät eivät käänny lastensa puoleen, sillä heidän kätensä ovat hervottomat');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'päivän tähden, joka tulee ja tuhoaa kaikki filistealaiset, hävittää Tyyrolta ja Siidonilta kaikki auttajat, mitä on jäljellä. Herra on näet tuhoava filistealaiset, kaikki, mitä on jäljellä Kaftorin saarelta tulleista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Kaljuksi on tullut Gassa, hävitetty on Askelon ja se mitä oli jäljellä heidän laaksossaan. Kuinka kauan sinä viileskelet ihoasi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Voi, Herran miekka! Milloin vihdoinkin lepäät? Mene takaisin tuppeesi, asetu ja ole hiljaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Mutta kuinka se saisi levätä, kun Herra on antanut sille käskyn? Askelonia ja meren rantaa vastaan hän on sen asettanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Mooabista. Näin sanoo Herra Sebaot, Israelin Jumala: \"Voi Neboa, sillä se on hävitetty! Häpeään joutunut, vallattu on Kirjataim, häpeään ja kauhun valtaan on joutunut vuorilinna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Enää ei ylistetä Mooabia, Hesbonissa suunnitellaan sille pahaa: \'Tulkaa hävittäkäämme se kansojen luvusta.\' Myös sinä, Madmena, kukistut, miekka kulkee perässäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Valittava ääni kuluu Hooronaimista! Tuho ja suuri hävitys!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Hävitetty on Mooab, sen pienokaisten parku kuuluu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'He nousevat itkien Luuhitiin, ja Hooronaimin rinteeltä kuuluu tuskan huuto hävityksen tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Paetkaa, pelastakaa henkenne ja olkaa kuin Aroer erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Sillä koska turvaat omiin tekoihisi ja aarteisiisi, sinutkin vallataan, ja Kemos lähtee karkotukseen ja hänen pappinsa ja ruhtinaansa hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Hävittäjä tulee jokaiseen kaupunkiin, eikä yksikään kaupunki pelastu. Laakso hävitetään ja tasanko tuhotaan, niin kuin Herra on puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Antakaa siivet Mooabille, sillä lentämällä on hänen lähdettävä pois. Hänen kaupunkinsa tulevat autioiksi, niin ettei niissä ole yhtään asukasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Kirottu olkoon se, joka tekee Herran työn laiskasti, kirottu olkoon se, joka pidättää miekkansa verestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Suruttomana on Mooab ollut nuoruudestaan asti ja levännyt rauhassa sakkansa päällä. Sitä ei ole tyhjennetty astiasta astiaan, eikä se ole karkotukseen vaeltanut. Sen tähden siihen on jäänyt sen oma maku, eikä sen haju ole muuttunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Sen tähden, katso, päivät tulevat, sanoo Herra, jolloin lähetän sille viininlaskijat, jotka sitä laskevat ja tyhjentävät sen astiat ja rikkovat sen leilit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Silloin Mooab joutuu häpeään Kemoksen tähden, niin kuin Israelin heimo joutui häpeään Beetelin tähden, johon se turvasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Kuinka te sanotte: \'Me olemme sankareita ja vahvoja miehiä taisteluun\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Mooab on hävitetty, sen kaupunkeihin on hyökätty, ja sen valionuorukaiset ovat voipuneet teurastettaviksi, sanoo kuningas – Herra Sebaot on hänen nimensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Lähellä tulossa on Mooabin hävitys. Sen onnettomuus tulee kovalla kiireellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Surkutelkaa sitä, kaikki sen naapurit, ja kaikki te, jotka tunnette sen nimen. Sanokaa: \'Voi, kuinka onkaan murrettu voiman valtikka, kunnian sauva!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Astu alas kunniasta ja istu janoiseen maahan, sinä valtiatar, tytär Diibon, sillä Mooabin hävittäjä hyökkää kimppuusi ja kukistaa linnoituksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Seiso tiellä ja tähystele, sinä Aroerin asukas; kysy pakolaisilta ja pelastuneilta, sano: \'Mitä on tapahtunut?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Häpeään on joutunut Mooab, sillä se on kukistettu. Valittakaa ja huutakaa, julistakaa Arnonilla, että Mooab on hävitetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Tuomio on tullut tasangon maalle, Hoolonille, Jahaalle ja Meefaa\'atille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'Diibonille, Nebolle ja Beet-Diblataimille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'Kirjataimille, Beet-Gaamulille ja Beet-Meonille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'Kerijotille, Bosralle ja kaikille Mooabin maan kaupungeille, kaukaisille ja läheisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Katkaistu on Mooabin sarvi ja murskattu hänen käsivartensa, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Juovuttakaa hänet, sillä hän on ylpeillyt Herraa vastaan, niin että Mooab suistuu omaan oksennukseensa ja tulee hänkin naurunalaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Vai eikö Israel ollut sinulle nauruksi? Onko hänet tavattu varkaiden joukosta, koska sinä, milloin vain hänestä puhuit, pudistit päätäsi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Jättäkää kaupungit ja asukaa kallioilla, te Mooabin asukkaat, ja olkaa kuin kyyhkynen, joka tekee pesänsä ammottavan kuilun taakse.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Me olemme kuulleet Mooabin ylpeilyn, tuon hyvin ylpeän, hänen korskeutensa, ylpeilynsä ja kopeilunsa ja hänen sydämensä pöyhkeyden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Minä tunnen, sanoo Herra, hänen ylimielisyytensä ja hänen tyhjät puheensa ja toisenlaiset tekonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Siksi valitan Mooabin tähden, koko Mooabin tähden minä huudan. Kiir-Hereksen miesten tähden huokaillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Itken sinua, Jaeser, itken sinua, Sibman viinipuu. Sinun köynnöksiäsi meni yli meren, Jaeserin merelle asti. Sinun hedelmän- ja viininkorjuuseesi on hävittäjä hyökännyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'Ilo ja riemu on otettu pois hedelmätarhoista ja Mooabin maasta. Viinin olen lopettanut viinikuurnista. Enää ei poljeta viiniä ilohuudoin eikä ilohuuto ole enää ilohuuto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Hesbonin parku kuuluu Elaleen, Jahaaseen asti. Heidän valituksensa kuuluu Sooarista Hooronaimiin, Eglat-Selisijjaan asti, jopa kolmivuotisesta lehmästä, sillä Nimrimin vedet ehtyvät erämaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Lopetan Mooabista, sanoo Herra, kukkuloilla-uhraajat, ne, jotka polttavat uhreja jumalilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Siksi sydämeni valittaa Mooabin tähden kuin huilu, sydämeni valittaa Kiir-Hereksen miesten tähden kuin huilu, sillä hävinnyt on heidän hankkimansa rikkaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Sillä kaikki päät ovat paljaiksi ajettuja, kaikki parrat leikattuja, kaikki kädet viileskeltyjä, ja lanteilla on säkit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Kaikilla Mooabin katoilla ja toreilla on pelkkää valitusta, sillä olen murskannut Mooabin kuin kelpaamattoman astian, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Miten murskattu se onkaan! Valittakaa! Kuinka Mooab kääntyikään selin ja häpesi! Mooab on tullut nauruksi ja kauhuksi kaikille naapureilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Sillä näin sanoo Herra: Katso, kotkan kaltainen liitelee siivet levitettyinä Mooabia kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Kerijotin ovat ottaneet haltuunsa ja vuorilinnat on vallattu. Sinä päivänä on Mooabin sankarien sydän kuin synnytystuskissa olevan vaimon sydän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Silloin Mooab hävitetään kansakuntien joukosta, sillä se on ylpeillyt Herraa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Kauhu, kuoppa ja ansa ovat edessäsi, sinä Mooabin asukas, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Joka pakenee kauhua, se putoaa kuoppaan, ja joka kuopasta nousee, se tarttuu ansaan. Sillä saatan Mooabille heidän rangaistusvuotensa, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'Hesbonin varjossa seisovat pakolaiset voimaa vailla. Sillä tuli lähti Hesbonista, liekki Siihonista, ja se kulutti Mooabin ohimon ja kapinoivien miesten päälaen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Voi sinua, Mooab! Hukkunut on Kemoksen kansa, sillä poikasi on otettu vangeiksi ja tyttäresi on viety vankeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Mutta käännän Mooabin kohtalon viimeisinä päivinä, sanoo Herra.\" Tähän asti Mooabin tuomiosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Ammonilaisista. Näin sanoo Herra: \"Eikö Israelilla olekaan lapsia, tai eikö hänellä ole perillistä? Miksi Malkam on perinyt Gaadin ja hänen kansansa on asettunut sen kaupunkeihin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Sen tähden, katso, päivät tulevat, sanoo Herra, jolloin annan sotahuudon kuulua ammonilaisten Rabbaa vastaan, ja siitä on tuleva autio rauniokumpu, ja sen tytärkaupungit palavat tulessa. Israel on perivä perijänsä, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Valita, Hesbon, sillä Ai on hävitetty. Huutakaa, te Rabban tyttäret, kääriytykää säkkeihin, pitäkää valittajaiset ja kuljeskelkaa ympäriinsä tarhoissa, sillä Malkam menee karkotukseen ja hänen pappinsa ja ruhtinaansa hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Miksi kerskut laaksoistasi? Laaksosi ovat virranneet tyhjiin, sinä luopiotytär, joka luotat aarteisiisi sanoen: \'Kuka käy kimppuuni?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Katso, tuotan sinulle kauhun joka taholta, sanoo Herra, Herra Sebaot, ja teidät karkotetaan, kuka minnekin, eikä pakenevilla ole kokoajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Mutta sen jälkeen käännän ammonilaisten kohtalon, sanoo Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Edomista. Näin sanoo Herra Sebaot: \"Eikö ole enää viisautta Teemanissa? Hävinnyt on ymmärtäväisiltä neuvo, ja loppunut on heidän viisautensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Paetkaa, kääntykää, piiloutukaa syvälle, te Dedanin asukkaat, sillä tuotan Eesaulle onnettomuuden, kun hänen rangaistuksensa aika tulee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Jos viininkorjaajat tulevat luoksesi, he eivät jätä jälkikorjuuta. Jos varkaat tulevat yöllä, he hävittävät, kunnes heillä on kylliksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Sillä paljastan Eesaun, tuon ilmi hänen kätkönsä, eikä hän voi piiloutua. Hänen lapsensa, veljensä ja naapurinsa hävitetään, niin ettei häntä enää ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Jätä orposi minun elätettävikseni, ja leskesi turvatkoot minuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Sillä näin sanoo Herra: Katso, niidenkin, jotka eivät ole tuomitut juomaan siitä maljasta, täytyy siitä juoda, ja sinäkö jäisit rankaisematta? Sinä et jää rankaisematta, vaan sinun täytyy juoda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Sillä olen vannonut itseni kautta, sanoo Herra, että Bosra on tuleva kauhuksi, häpeäksi, tyrmistykseksi ja kirosanaksi, ja kaikki sen tytärkaupungit tulevat ikuisiksi raunioiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Olen kuullut sanoman Herralta, ja sanansaattaja on lähetetty kansakuntiin: \"Kokoontukaa ja käykää sitä vastaan ja nouskaa sotaan.\" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, '\"Sillä katso, teen sinut vähäiseksi kansojen seassa ja halveksituksi ihmisten keskuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Sinun pelottavuutesi, sydämesi ylpeys on pettänyt sinut, joka asut kallion rotkoissa ja vallitset kukkuloiden korkeudet. Vaikka tekisit pesäsi korkealle kuin kotka, syöksen sinut sieltä alas, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Edom tulee kauhistukseksi; jokainen ohikulkija kauhistuu ja viheltää kaikille sen haavoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Kuten Sodoman ja Gomorran ja niiden naapurien tultua hävitetyiksi, sanoo Herra, niin ei täälläkään kukaan ole asuva eikä yksikään ihmislapsi oleskeleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Katso, niin kuin leijona syöksyy ylös Jordanin tiheiköstä lakastumattomalle laitumelle, niin äkisti karkotan heidät sieltä pois. Sen, joka on valittu, asetan sinne kaitsijaksi. Sillä kuka on minun vertaiseni, ja kuka vetää minut tilille? Kuka on se paimen, joka voi kestää edessäni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Sen tähden kuulkaa Herran päätös, jonka hän on päättänyt Edomista, ja hänen ajatuksensa, jotka hän on ajatellut Teemanin asukkaista: Totisesti, lauman vähäisimmät raastetaan pois. Totisesti, hän tekee autioiksi heidän asuinpaikkansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Heidän sortumisensa pauhusta järisee maa. Huudetaan, niin että ääni kuuluu Kaislamerelle asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Katso, kotkan kaltainen kohoaa ja liitelee siivet levitettyinä Bosraa kohti. Sinä päivänä on Edomin sankarien sydän kuin synnytystuskissa olevan vaimon sydän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Damaskosta. \"Hamat ja Arpad joutuvat häpeään, sillä he kuulevat pahan sanoman ja ovat epätoivoisia – on levottomuus meressä, joka ei voi tyyntyä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damasko lannistuu, kääntyy pakoon, kauhu on sen vallannut. Sillä on kova ahdistus ja tuska kuin synnyttäjällä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Kuinka hyljeksitty onkaan ylistetty kaupunki, minun iloni kaupunki!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Sen tähden sen nuorukaiset kaatuvat sen kaduilla, ja kaikki sotamiehet saavat surmansa sinä päivänä, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'Sytytän Damaskon muurit tuleen, ja se on kuluttava Benhadadin palatsit.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Keedarin ja Haasorin valtakunnasta, jotka Nebukadressar, Baabelin kuningas, kukisti. Näin sanoo Herra: \"Nouskaa, käykää Keedarin kimppuun ja hävittäkää se, te Idän miehet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Heidän telttansa ja lampaansa otetaan pois, heidän kankaansa, kaikki heidän tavaransa ja kamelinsa viedään heiltä, ja heistä huudetaan: \'Kauhu kaikkialla!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Lähtekää pakoon, paetkaa nopeasti, piiloutukaa syvälle, te Haasorin asukkaat, sanoo Herra, sillä Nebukadressar, Baabelin kuningas, on päättänyt teitä vastaan päätöksen, ja on pitänyt neuvoa teitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Nouskaa, käykää kansan kimppuun, joka asuu rauhassa ja turvallisena, sanoo Herra. Sillä ei ole ovia eikä salpoja, he asuvat yksinään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Heidän kamelinsa joutuvat ryöstettäviksi ja heidän karjansa paljous saaliiksi, ja he tulevat hajotetuiksi kaikkiin tuuliin, nuo, joiden tukka on ohimoilta leikattu, ja joka puolelta tuotan heille turmion, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Haasor tulee sakaalien asunnoksi, autioksi iankaikkisesti. Kukaan ei ole siellä asuva, ei yksikään ihmislapsi siellä oleskeleva.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Herran sana, joka tuli profeetta Jeremialle Eelamista Juudan kuninkaan Sidkian hallituksen alussa ja joka kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, '\"Näin sanoo Herra Sebaot: Katso, murran Eelamin jousen, heidän parhaimman voimansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'Tuon Eelamia vastaan neljä tuulta taivaan neljältä ääreltä ja hajotan heidät kaikkiin näihin tuuliin. Ei ole oleva kansaa, johon ei tulisi Eelamin karkotettuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Saatan Eelamin kauhistumaan vihollistensa edessä, niiden edessä, jotka etsivät heidän henkeään, ja annan onnettomuuden kohdata heitä, vihani hehkun, sanoo Herra, ja lähetän heidän jälkeensä miekan, kunnes heidät lopetan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Asetan valtaistuimeni Eelamiin ja hävitän sieltä kuninkaan ja ruhtinaat, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Mutta aikojen lopulla käännän Eelamin kohtalon, sanoo Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Sana, jonka Herra puhui Baabelista, se on, kaldealaisten maasta, profeetta Jeremian kautta:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, '\"Julistakaa kansojen keskuudessa ja kuuluttakaa, nostakaa lippu; kuuluttakaa, älkää salatko. Sanokaa: Baabel on vallattu, Beel on joutunut häpeään, kukistettu on Merodak. Sen jumalankuvat ovat joutuneet häpeään ja sen epäjumalat ovat maahan murskatut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Sillä sen kimppuun käy kansa pohjoisesta ja tekee sen maan autioksi, niin ettei siellä ole asukasta, ja ihmiset ja eläimet pakenevat ja menevät pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'Niinä päivinä ja siihen aikaan, sanoo Herra, tulevat israelilaiset yhdessä Juudan miesten kanssa. He kulkevat itkien ja etsivät Herraa, Jumalaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Siionia he kysyvät, sitä kohden he kääntävät kasvonsa. Tulkaa! He liittyvät Herran kanssa iankaikkiseen liittoon, jota ei unohdeta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Kadonnut lammaslauma oli kansani. Heidän paimenensa olivat vieneet heidät harhaan ja ajoivat heidät eksyksiin vuorilla. He kulkivat vuorelta kukkulalle ja unohtivat lepopaikkansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Kaikki, jotka heitä tapasivat, söivät heitä, ja heidän vihollisensa sanoivat: \'Emme ole syyllisiä, sillä he ovat tehneet syntiä Herraa vastaan, vanhurskauden asumusta, Herraa, heidän isiensä toivoa, vastaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Paetkaa Baabelin keskeltä ja lähtekää kaldealaisten maasta, ja käykää kuin vuohipukit lauman edellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Sillä katso, minä herätän ja nostan Baabelia vastaan suurten kansojen joukon pohjoisesta maasta, ja ne asettuvat sitä vastaan. Sieltä käsin se vallataan. Heidän nuolensa ovat kuin menestyvän sankarin, joka ei palaa tyhjin toimin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'Mutta Kaldea joutuu ryöstettäväksi, kaikki sen ryöstäjät saavat kyllikseen, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Iloitkaa vain, riemuitkaa vain, te perintöosani riistäjät, hypelkää kuin puiva hieho, ja hirnukaa kuin oriit:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'kuitenkin äitinne joutuu suureen häpeään, synnyttäjänne saa hävetä. Katso, pakanakansoista viimeinen! Erämaa, kuiva maa ja aromaa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Herran vihan tähden se on oleva asumaton, aivan autio. Jokainen, joka kulkee Baabelin ohi, kauhistuu ja viheltää kaikille sen haavoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Asettukaa rintamaan Baabelia vastaan, joka puolelta, kaikki jousimiehet. Ampukaa sitä, älkää nuolia säästäkö, sillä se on tehnyt syntiä Herraa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Nostakaa sotahuuto sitä vastaan joka taholta. Se on ojentanut kätensä, sen pylväät ovat kaatuneet, sen muurit sortuneet. Sillä tämä on Herran kosto. Kostakaa sille, tehkää sille, niin kuin sekin on tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Tuhotkaa kylväjät Baabelista ja ne, jotka elonkorjuun aikana sirppiin tarttuvat. Hävittäjän miekkaa pakoon he kääntyvät kukin oman kansansa luo ja pakenevat kukin omaan maahansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Israel on hajotettu lammaslauma, leijonat ovat sen ajaneet hajalle. Ensiksi Assurin kuningas söi sen, ja nyt viimeksi Nebukadressar, Baabelin kuningas, murskasi sen luut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Sen tähden, näin sanoo Herra Sebaot, Israelin Jumala: Katso, rankaisen Baabelin kuningasta ja hänen maatansa, niin kuin rankaisin Assurin kuningasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'Tuon Israelin takaisin sen omille laidunmaille, ja se on käyvä laitumella Karmelilla ja Baasanissa ja hänen sielunsa tulee ravituksi Efraimin vuorilla ja Gileadissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'Niinä päivinä ja siihen aikaan, sanoo Herra, etsitään Israelin rikosta, eikä sitä enää ole, ja Juudan syntiä, eikä sitä löydetä, sillä annan anteeksi niille, jotka jätän jäännökseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Käy niskurimaan kimppuun ja niiden asukkaiden kimppuun, joita kohtaa kosto. Hyökkää, hävitä heidän jälkeläisensä, sanoo Herra, ja tee kaikki, mitä olen käskenyt sinun tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Sotahuuto kuuluu maassa, ja on suuri hävitys!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Kuinka rikottu ja särjetty onkaan se vasara, joka löi kaikkea maata! Kuinka onkaan Baabel tullut kauhistavaksi kansojen seassa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Viritin sinulle pyydyksen, ja niin sinut, Baabel, vangittiin tietämättäsi. Sinut tavoitettiin ja otettiin kiinni, sillä sinä nousit vastustamaan Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Herra on avannut varastonsa ja tuonut esiin vihansa aseet. Sillä Herra, Herra Sebaot, on tekevä työnsä kaldealaisten maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Käykää sen kimppuun äärimmäisiltä rajoilta, avatkaa sen aitat, heittäkää ulos, mitä siinä on, pankaa ne läjiin kuin lyhteet. Vihkikää se tuhon omaksi, älköön siitä tähteitä jääkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Hävittäkää kaikki sen härät, astukoot ne teurastettaviksi. Voi heitä! Sillä heidän päivänsä on tullut, heidän rangaistuksensa aika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Kuule! Pakenevia ja pakolaisia tulee Baabelin maasta Siioniin ilmoittamaan Herran, meidän Jumalamme, kostoa, kostoa hänen temppelinsä tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Kutsukaa ampujat, kaikki jousimiehet, kokoon Baabelia vastaan: leiriytykää sen ympärille, älköön yksikään pääskö pakoon. Maksakaa sille sen tekojen mukaan. Kaiken sen mukaan, mitä se on tehnyt, tehkää sillekin. Sillä se on pöyhkeillyt Herraa, Israelin Pyhää vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Sen tähden sen nuorukaiset kaatuvat sen kaduilla, ja kaikki sotamiehet saavat surmansa sinä päivänä, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Katso, käyn kimppuusi, sinä ylpeä, sanoo Herra, Herra Sebaot, sillä päiväsi, rangaistuksesi aika, on tullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Ylpeä kompastuu ja kaatuu, eikä ole hänen nostajaansa. Sytytän hänen kaupunkinsa tuleen, ja se kuluttaa ne ja kaiken hänen ympäriltään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Näin sanoo Herra Sebaot: Sorrettuja ovat israelilaiset ja myös Juudan miehet yhdessä heidän kanssaan, ja kaikki heidän vangitsijansa pitävät heistä kiinni, he eivät suostu päästämään heitä irti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Mutta heidän lunastajansa on voimakas, Herra Sebaot on hänen nimensä. Hän toden totta ajaa heidän asiansa ja tuo rauhan maahan, mutta vapinan Baabelin asukkaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Miekka kaldealaisten kimppuun, sanoo Herra, ja Baabelin asukkaiden kimppuun, sen ruhtinaiden ja tietäjien kimppuun!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Miekka tyhjänpuhujien kimppuun, ja he käyvät typeriksi! Miekka sen sankarien kimppuun, ja he kauhistuvat!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Miekka sen hevosten ja vaunujen kimppuun ja kaiken sekakansan kimppuun, joka on sen keskellä, ja he tulevat naisiksi! Miekka sen aarteiden kimppuun, ja ne ryöstetään!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Helle sen vetten kimppuun, ja ne kuivuvat! Sillä se on jumalankuvien maa, ja he pöyhkeilevät kauheista epäjumalistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Sen tähden sen asukkaiksi tulevat erämaan eläimet ja sakaalit, ja strutsit siellä asuvat. Siellä ei ikinä enää asuta, autioksi se jää polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Niin kuin oli silloin, kun Jumala hävitti Sodoman ja Gomorran ja niiden naapurit, sanoo Herra, niin ei sielläkään ole kukaan asuva, ei yksikään ihmislapsi oleskeleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Katso, kansa tulee pohjoisesta: suuri kansa ja monet kuninkaat nousevat maan ääristä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'He tarttuvat jouseen ja keihääseen, ovat julmia ja armahtamattomia. Heidän äänensä on kuin pauhaava meri, ja he ratsastavat hevosilla, varustettuina kuin soturi taisteluun sinua vastaan, tytär Baabel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Kun Baabelin kuningas kuulee sanoman heistä, niin hänen kätensä vaipuvat. Ahdistus valtaa hänet kuin tuska synnyttäjän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Katso, niin kuin leijona syöksyy Jordanin tiheiköstä lakastumattomalle laitumelle, niin karkotan äkkiä heidät sieltä pois. Sen, joka on siihen valittu, asetan sinne kaitsijaksi. Sillä kuka on minun vertaiseni, ja kuka vetää minut tilille? Kuka on se paimen, joka kestää edessäni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Sen tähden kuulkaa Herran päätös, jonka hän on päättänyt Baabelia vastaan, ja hänen ajatuksensa, jotka hänellä on kaldealaisten maata vastaan: Totisesti, ne raastetaan pois, nuo lauman vähäiset. Hän totisesti tekee autioksi heidän asuinsijansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Baabelin valtauksen äänestä maa vapisee ja valitus kuuluu kansoissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Näin sanoo Herra: \"Katso, minä herätän hävittäjän hengen Baabelia vastaan, ja niitä asukkaita vastaan, jotka ovat nousseet minua vastustamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'Lähetän Baabeliin muukalaisia, jotka hajottavat sen ja tyhjentävät maan, sillä joka taholta he tulevat sitä vastaan onnettomuuden päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Jousimies jännittäköön jousensa sitä vastaan, joka jousen jännittää, ja sitä vastaan, joka ylpeilee haarniskassaan. Älkää säälikö sen nuorukaisia, vihkikää tuhon omaksi koko sen sotajoukko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Haavoitettuja kaatuu kaldealaisten maassa ja lävistettyjä sen kaduilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Sillä ei Israel eikä Juuda ole Jumalansa, Herran Sebaotin, hylkäämä, vaikka noiden maa on täynnä syntivelkaa Israelin Pyhän edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Paetkaa Baabelin keskeltä ja pelastakoon kukin henkensä, ettei hukkuisi sen syntiin. Sillä tämä on Herran koston aika, hän maksaa sille, mitä se on ansainnut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Baabel oli Herran kädessä kultamalja, joka juovutti kaiken maan. Sen viinistä joivat kansat. Sen tähden kansat käyttäytyivät kuin mielettömät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Äkkiä Baabel on kaatunut ja murskaantunut. Valittakaa hänen tähtensä! Pankaa balsamia hänen kipuunsa, ehkä hän paranee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, '\'Olemme parantaneet Baabelia, mutta se ei ole parantunut. Jättäkää se, ja menkäämme pois kukin omalle maalleen, sillä sen tuomio ulottuu taivaaseen asti ja kohoaa pilviin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Herra on tuonut ilmi vanhurskautemme. Tulkaa, julistakaamme Siionissa Herran, meidän Jumalamme, tekoja.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Terottakaa nuolet, täyttäkää viinikotelot! Herra on herättänyt Meedian kuningasten hengen, sillä hänen ajatuksensa käy Baabelia vastaan sen hävittämiseksi. Tämä on Herran kosto, kosto hänen temppelinsä puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Kohottakaa lippu Baabelin muureja vastaan, vahvistakaa vartiosto, asettakaa vartijat, valmistakaa väijytykset; sillä mitä Herra on ajatellut, sen hän tekeekin, sen, minkä hän on puhunut Baabelin asukkaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Sinä, joka asut suurten vetten varrella, joka olet aarteista rikas, loppusi on tullut, ahneutesi mitta on täysi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Herra Sebaot on vannonut itsensä kautta. Totisesti, täytän sinut ihmisillä niin kuin heinäsirkoilla, ja he virittävät sinusta voittolaulun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Hän on tehnyt maan voimallaan, vahvistanut maanpiirin viisaudellaan ja levittänyt taivaat taidollaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Kun hän antaa äänensä kuulua, käy vetten pauhina taivaalla, ja hän nostaa pilvet maan ääristä, tekee salamat ja sateen ja tuo tuulen sen säilytyspaikoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Typerä on jokainen ihminen ja tietoa vailla, häpeän saa jokainen kultaseppä veistetystä kuvasta, petosta on hänen valamansa kuva, eikä niissä ole henkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Turhuutta ne ovat, naurettavia tekeleitä. Kun niiden rangaistus tulee, ne hukkuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Näiden kaltainen ei ole Jaakobin osa, sillä hän on kaiken luoja, ja Jaakob on hänen perintösukunsa: Herra Sebaot on hänen nimensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Sinä olit minun vasarani, minun sota-aseeni, sinulla musersin kansoja, sinulla hävitin valtakuntia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Sinulla muserran hevosen ja ratsastajan, sinulla muserran vaunut ja ajajan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'Muserran sinulla miehen ja aviovaimon, muserran sinulla vanhan ja nuoren, sinulla muserran nuorukaisen ja neitsyen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Muserran sinulla paimenen ja hänen laumansa, muserran sinulla peltomiehen ja hänen juhtaparinsa, muserran sinulla käskynhaltijat ja päälliköt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Kostan Baabelille ja kaikille Kaldean asukkaille kaiken sen pahan, minkä he ovat tehneet Siionille teidän silmienne edessä, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Katso, käyn kimppuusi, sinä hävityksen vuori, joka hävitit koko maan, sanoo Herra. Ojennan käteni sinua vastaan ja vieritän sinut alas kalliolta ja teen sinusta poltetun vuoren.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'Eikä sinusta oteta enää kulmakiveä eikä kiveä perustusta varten, vaan sinä jäät ikuisesti autioksi, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Nostakaa lippu maassa, puhaltakaa torveen kansoissa, vihkikää kansat häntä vastaan, kutsukaa häntä vastaan Araratin, Minnin ja Askenaan valtakunnat, asettakaa päällikkö häntä vastaan, antakaa tulla hevosia kuin pörröisiä heinäsirkkoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Vihkikää kansoja häntä vastaan, Meedian kuninkaat, sen käskynhaltijat ja kaikki päälliköt ja koko sen valtaan kuuluva maa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Maa järisee ja vääntelehtii, sillä Herran ajatukset toteutuvat Baabelia vastaan: hän tekee Baabelin maan autioksi, jossa ei ole asukkaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Baabelin sankarit lakkaavat taistelemasta, he istuvat linnoituksissaan, heidän voimansa on voipunut, he ovat muuttuneet naisiksi. Sen asunnot on poltettu ja sen salvat rikottu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Juoksija juoksee juoksijaa vastaan, sanantuoja sanantuojaa vastaan ilmoittamaan Baabelin kuninkaalle, että hänen kaupunkinsa on vallattu reunasta toiseen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'ylikulkupaikat ovat vallatut, linnoitukset ovat tulella poltetut ja sotamiehet ovat kauhun vallassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Tytär Baabel on kuin puimatanner puintiaikaan. Vielä vähän aikaa niin sen elonkorjuuaika tulee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Nebukadressar, Baabelin kuningas, on minua syönyt ja sortanut minua, pannut syrjään kuin tyhjän astian. Hän on niellyt minut kuin lohikäärme, täyttänyt vatsansa herkuillani ja huuhtonut minut pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, '\'Kärsimäni väkivalta ja lihani tulkoon Baabelin päälle\', sanoo Siionin asukas. \'Vereni tulkoon Kaldean asukasten päälle\', sanoo Jerusalem.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Sen tähden näin sanoo Herra: Katso, ajan asiasi ja kostan kostosi. Kuivaan hänen virtansa ja ehdytän hänen lähteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'Baabelista tulee kivikasa, sakaalien asuinpaikka, kauhistus, jolle vihellellään ja jossa ei ole asukkaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'He karjahtelevat yhdessä kuin nuoret leijonat, murisevat kuin naarasleijonien pennut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Heidän kiihkoonsa teen heille juomingit ja juovutan heidät, että he riemastuvat ja nukahtavat hyvin pitkään uneen eivätkä enää herää, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Vien heidät teurastettaviksi, kuin karitsat, kuin pässit pukkien kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Kuinka onkaan vallattu Seesak, vallattu tuo, jota koko maailma ylisti! Kuinka onkaan Baabelista tullut kauhistus kansojen joukossa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Meri nousi Baabelin yli, sen aaltojen pauhuun se peittyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Sen kaupungit ovat tulleet autioiksi, kuivaksi maaksi ja aromaaksi, maaksi, jossa ei asu ketään, josta ihmislapsi ei kulje.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Kostan Beelille Baabelissa ja vedän ulos hänen suustaan sen, mitä hän on niellyt, eivätkä kansat enää virtaa hänen luokseen. Baabelin muurikin on kaatunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Lähde pois sen keskuudesta, kansani, ja pelastakoon kukin henkensä Herran vihan hehkusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'Älköön sydämenne voipuko, älkää pelätkö sanomaa, joka kuuluu maassa, kun tänä vuonna tulee sanoma ja sitten toisenakin vuonna sanoma, kun maassa on väkivaltaa ja hallitsija on hallitsijaa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Sen tähden katso, päivät tulevat, jolloin kostan Baabelin jumalankuville, ja koko sen maa joutuu häpeään ja kaikki sen surmatut kaatuvat sen keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Baabelin kohtalosta riemuitsevat taivas ja maa ja kaikki, mitä niissä on, kun sen surmatut saapuvat pohjoisesta, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Baabelinkin on kaatuminen, te Israelin surmatut, kuten Baabelin tähden kaatui surmattuja kautta koko maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Te miekasta pelastuneet, menkää, älkää seisahtuko, muistakaa Herraa kaukana ja pitäkää mielessänne Jerusalem.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, '\'Häpeämme, sillä kuulemme pilkkaa. Häpeä peittää kasvomme, sillä muukalaiset ovat käyneet käsiksi Herran huoneen pyhyyksiin.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Sen tähden katso, päivät tulevat, sanoo Herra, jolloin kostan sen jumalankuville ja sen maa on täynnä kuolettavasti haavoittuneiden valitusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Vaikka Baabel astuisi ylös taivaaseen, vaikka se vahvistaisi korkeuteen linnansa, sittenkin tulevat sille minulta hävittäjät, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Valitushuuto Baabelista, suuri hävitys kuuluu kaldealaisten maasta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Sillä Herra hävittää Baabelin ja lopettaa sieltä suuren melun. Heidän aaltonsa pauhaavat kuin suuret vedet, niiden äänestä nousee kohina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Sillä hävittäjä käy Baabelin kimppuun, ja sen sankarit vangitaan, heidän jousensa murretaan, sillä Herra on koston Jumala. Hän vaatii täyden koston.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Minä juovutan sen ruhtinaat ja tietäjät, sen käskynhaltijat, päämiehet ja sankarit; ja he nukkuvat hyvin pitkään uneen eivätkä herää, sanoo Kuningas; Herra Sebaot on hänen nimensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Näin sanoo Herra Sebaot: Baabelin leveä muuri hajotetaan maahan, ja sen korkeat portit poltetaan tulella. Niin ovat tehneet kansat työtä tyhjän tähden, kansakunnat tulen hyväksi, ja väsyttäneet itsensä tulen hyväksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Asia, jonka profeetta Jeremia käski Serajaa, Neerian poikaa, joka oli Mahsejan poika, toimittamaan, kun tämä lähti Sidkian, Juudan kuninkaan, kanssa Baabeliin hänen neljäntenä hallitusvuotenaan. Seraja oli majoituspäällikkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Jeremia kirjoitti kaiken sen onnettomuuden, joka oli tuleva Baabelille, yhteen kirjaan, kaikki nämä sanat, jotka ovat kirjoitetut Baabelista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'Jeremia sanoi Serajalle: \"Kun tulet Baabeliin, niin katso, että luet kaikki nämä sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'Sano: Herra, sinä olet puhunut tätä paikkaa vastaan. Sinä olet hävittävä sen, niin ettei siinä ole asukasta, ei ihmistä eikä eläintä, vaan se jää ikuiseksi erämaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Kun olet lukenut tämän kirjan loppuun, sido siihen kivi ja viskaa se keskelle Eufratia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'ja sano: Näin uppoaa Baabel eikä nouse enää siitä onnettomuudesta, jonka minä sille tuotan, vaan he voipuvat.\" Näin pitkälle Jeremian sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Sidkia oli kahdenkymmenen yhden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa yksitoista vuotta. Hänen äitinsä oli nimeltään Hamutal, Jeremian tytär, Libnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Hän teki sitä, mikä on pahaa Herran silmissä, samoin kuin Joojakim oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Sillä Herran vihan tähden kävi näin Jerusalemille ja Juudalle, kunnes hän heitti heidät pois kasvojensa edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Sidkia kapinoi Baabelin kuningasta vastaan. Hänen yhdeksäntenä hallitusvuotenaan, sen kymmenennessä kuussa, kuukauden kymmenentenä päivänä, tuli Nebukadressar, Baabelin kuningas, koko sotajoukollaan Jerusalemia vastaan, ja he asettuivat leiriin sitä vastaan ja rakensivat saartovarusteet sitä vastaan sen ympärille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Näin kaupunkia piiritettiin kuningas Sidkian yhdenteentoista hallitusvuoteen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Mutta neljännessä kuussa, kuukauden yhdeksäntenä päivänä, kun nälänhätä ahdisti kaupunkia eikä maan kansalla ollut leipää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'kaldealaiset mursivat kaupungin muuriin aukon, ja kaikki sotilaat pakenivat ja lähtivät ulos kaupungista yöllä molempien muurien välitse vievää porttitietä, joka on kuninkaan puutarhan puolella, kaldealaisten ollessa kaupungin ympärillä, ja he kulkivat Aromaan tietä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Mutta kaldealaisten sotajoukko ajoi kuningasta takaa, ja he saavuttivat Sidkian Jerikon aroilla, mutta koko hänen sotajoukkonsa oli jättänyt hänet ja hajaantunut hänen luotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'He ottivat kuninkaan kiinni ja veivät hänet Baabelin kuninkaan eteen Riblaan, joka on Hamatin maassa, ja tämä julisti hänelle tuomiot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Baabelin kuningas surmasi Sidkian pojat hänen silmiensä edessä, ja myös kaikki Juudan ruhtinaat hän surmasi Riblassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Mutta Sidkialta Baabelin kuningas sokaistutti silmät, kytki hänet vaskikahleisiin ja vei hänet Baabeliin, ja hän pani hänet vankihuoneeseen, jossa hän oli kuolinpäiväänsä asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Viidennessä kuussa, kuukauden kymmenentenä päivänä, Baabelin kuninkaan Nebukadressarin yhdeksäntenätoista hallitusvuotena, tuli Nebusaradan, henkivartijoiden päällikkö, joka oli Baabelin kuninkaan palveluksessa, Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'Hän poltti Herran huoneen ja kuninkaan talon ja kaikki Jerusalemin talot. Kaikki ylhäisten ruhtinaitten talot hän poltti tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Koko kaldealaisten sotajoukko, joka henkivartijoiden päälliköllä oli mukanaan, repi maahan kaikki Jerusalemin muurit joka puolelta ympäriinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Niin Nebusaradan, henkivartijoiden päällikkö, siirsi maasta pois osan kansan köyhiä ja kansan tähteitä, mitä oli jäljellä kaupungissa, sekä ne, jotka olivat menneet Baabelin kuninkaan puolelle, ja loput käsityöläisistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Mutta osan maan köyhiä Nebusaradan, henkivartijoiden päällikkö, jätti jäljelle viinitarhureiksi ja peltomiehiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Vaskipylväät, jotka olivat Herran huoneessa, altaiden telineet ja vaskimeren, jotka olivat Herran huoneessa, kaldealaiset särkivät ja veivät kaiken niissä olevan vasken Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Kattilat, lapiot, veitset, maljat, kupit ja kaikki vaskiesineet, joita siinä käytettiin, he veivät pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Henkivartijoiden päällikkö vei puolestaan vadit, hiilipannut, maljat, kattilat, lampunjalat, kupit ja kulhot, jotka olivat kokonaan kultaa tai hopeaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Hän vei myös molemmat pylväät, meren ja niiden kaksitoista vaskista härkää, jotka olivat telineiden alla – kaikki ne esineet, jotka Salomo oli teettänyt Herran temppeliin ja joiden vaski ei ollut punnittavissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Pylväistä oli toisen pylvään korkeus kahdeksantoista kyynärää, ja kahdentoista kyynärän pituinen nauha ulottui sen ympäri. Sen vahvuus oli neljä sormenleveyttä. Se oli ontto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Sen päässä oli pylväänpää vaskesta. Toisen pylväänpään korkeus oli viisi kyynärää, ja pylväänpään päällä oli ristikko ja granaattiomenia ympäriinsä, kaikki vaskea. Samanlaiset oli toisessa pylväässä sekä granaattiomenat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'Granaattiomenia oli yhdeksänkymmentä kuusi ulospäin. Kaikkiaan oli granaattiomenia sata ristikon päällä ympäriinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Henkivartijoiden päällikkö otti ylimmäisen papin Serajan ja kakkospapin Sefanjan sekä kolme ovenvartijaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'ja kaupungista hän otti yhden hoviherran, joka oli sotaväen tarkastaja, ja seitsemän miestä, jotka palvelivat kuningasta hänen edessään ja jotka tavattiin kaupungista, sekä sotapäällikön kirjurin, jonka tehtävänä oli ottaa maan kansaa sotapalvelukseen, ja kuusikymmentä miestä maan kansasta, jotka tavattiin kaupungista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Nämä Nebusaradan, henkivartijoiden päällikkö otti ja vei heidät Baabelin kuninkaan eteen Riblaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Baabelin kuningas löi heidät kuoliaaksi Riblassa Hamatin maassa. Juuda siirrettiin pois maastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Tämä on se kansa, jonka Nebukadressar vei karkotukseen: seitsemäntenä vuotena kolmetuhatta kaksikymmentä kolme juutalaista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'Nebukadressarin kahdeksantenatoista hallitusvuotena kahdeksansataa kolmekymmentä kaksi henkeä Jerusalemista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'Nebukadressarin kahdentenakymmenentenä kolmantena hallitusvuotena vei Nebusaradan, henkivartijoiden päällikkö, seitsemänsataa neljäkymmentä viisi juutalaista karkotukseen – yhteensä neljätuhatta kuusisataa henkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Mutta kolmantenakymmenentenä seitsemäntenä vuotena siitä, kun Joojakin, Juudan kuningas, oli viety karkotukseen, kahdennessatoista kuussa, kuukauden kahdentenakymmenentenä viidentenä päivänä, korotti Evil-Merodak, Baabelin kuningas, samana vuonna, jona hän tuli kuninkaaksi, Juudan kuninkaan Joojakinin pään ja päästi hänet vankilasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'Hän puhutteli häntä ystävällisesti ja asetti hänen istuimensa ylemmäksi muiden kuninkaiden istuimia, jotka olivat hänen luonaan Baabelissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Hän vaihtoi pois vanginpuvun ja aterioi aina hänen luonaan, niin kauan kuin eli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Hän sai Baabelin kuninkaalta elatuksensa, vakinaisen elatuksen, mitä kunakin päivänä tarvitsi, kuolinpäiväänsä asti, niin kauan kuin eli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Kuinka istuukaan yksinään tuo runsasväkinen kaupunki! Kuinka onkaan tullut lesken kaltaiseksi se, joka oli suuri kansakuntien joukossa! Ruhtinatar maakuntien joukossa on tullut pakkotyön alaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Se itkee katkerasti yössä, ja sillä on kyyneleet poskillaan. Sillä ei ole lohduttajaa kaikkien niiden joukossa, jotka sitä rakastivat. Uskottomia ovat sille olleet kaikki sen ystävät, ja he ovat tulleet sen vihamiehiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Juuda on mennyt vankeuteen kurjuudesta ja työn kovuudesta. Se istuu pakanakansojen joukossa eikä löydä lepoa. Kaikki sen vainoajat saavuttivat sen, kun se oli ahdistusten keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Siionin tiet surevat, sillä juhlille ei ole tulijoita. Kaikki sen portit ovat autioina, sen papit huokailevat, sen neitsyet ovat murheissaan, ja sillä itsellään on katkera mieli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Sen vastustajat ovat sen päällikköinä, ja sen viholliset menestyvät. Sillä Herra on saattanut sen murheelliseksi sen rikosten paljouden tähden. Sen pienet lapset ovat menneet vankeuteen vihollisen vieminä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Mennyt on tytär Siionilta kaikki hänen kauneutensa. Hänen ruhtinaansa ovat kuin peurat, jotka eivät löydä laidunta. He kulkivat voimattomina vainoojan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Jerusalem muistelee kurjuutensa päivinä ja kärsimyksissään kaikkea kallisarvoista, mitä sillä oli entisinä päivinä. Kun sen kansa on sortunut vihollisen käsiin eikä sillä ole auttajaa, viholliset katselevat sitä ja nauravat sen sapateille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Jerusalem on tehnyt syntiä synnin perään, sen tähden siitä on tullut saastaa. Kaikki, jotka sitä kunnioittivat, halveksivat sitä nyt, kun ovat nähneet sen alastomuuden. Itsekin se huokaa ja kääntyy pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Sen tahrat ovat sen liepeissä. Se ei ajatellut loppuaan, ja niin se sortui ihmeteltävästi. Sillä ei ole lohduttajaa. Katso, Herra, kurjuuttani, sillä vihollinen ylvästelee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Vihollinen levitti kätensä kaikkia sen kalleuksia kohti. Niin, sen täytyi nähdä, kuinka pakanat tunkeutuivat sen pyhäkköön, ne, joita sinä olit kieltänyt tulemasta seurakuntaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Kaikki sen kansa huokaa etsiessään leipää. Pysyäkseen hengissä he antavat ruuasta, mitä heillä on arvokasta. Katso, Herra, ja näe, kuinka halveksittu olen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Eikö tämä koske teihin, kaikki ohikulkijat? Katsokaa ja nähkää: onko kipua, minun kipuni vertaista, joka on pantu kannettavakseni, jolla Herra on murehduttanut minut vihansa hehkun päivänä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Hän lähetti tulen korkeudesta luihini ja kuritti niitä. Hän viritti verkon jalkojeni varalle, hän pani minut peräytymään, hän teki minut autioksi ja voimattomaksi kaiken päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Hänen kätensä sitoi rikosteni ikeen. Ne kiedottiin yhteen, ja ne tulivat niskani päälle. Hän saattoi voimani kompastumaan. Herra antoi minut niiden käsiin, joista en voi nousta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Herra hylkäsi kaikki vahvat miehet, joita keskuudessani oli. Hän kutsui kokoon juhlan minua vastaan murskatakseen nuorukaiseni. Herra polki viinikuurnan neitsyelle, tytär Juudalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Näitä minä itken, silmäni, silmäni vuotaa vettä, sillä kaukana on minusta lohduttaja, joka palauttaisi sieluni entiselleen. Hävitetyt ovat lapseni, sillä vihollinen on vahva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Siion levittelee käsiään. Hänellä ei ole lohduttajaa. Herra on käskenyt Jaakobia vastaan sen viholliset joka taholta. Jerusalem on tullut saastaksi heidän keskellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Vanhurskas on hän, Herra. Sillä hänen sanaansa vastaan olen niskoitellut. Kuulkaa, te kansat kaikki, ja katsokaa kipuani. Neitsyeni ja nuorukaiseni ovat menneet vankeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Kutsuin niitä, jotka minua rakastivat. He hylkäsivät minut. Pappini ja vanhimpani ovat kuolleet kaupungissa etsiessään ruokaa pysyäkseen hengissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Katso, Herra, kuinka ahdistettu olen, sisukseni kuohuvat, sydämeni vääntyy rinnassani, sillä olen ollut hyvin uppiniskainen. Ulkona miekka ja sisällä kuolema on minua riistänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'He ovat kuulleet, kuinka minä huokailen. Minulla ei ole lohduttajaa. Kaikki vihamieheni ovat kuulleet onnettomuuteni. He iloitsevat, kun sinä olet tämän tehnyt. Sinä olet antanut tulla sen päivän, jonka olit ilmoittanut. Mutta käyköön heidän samoin kuin minun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Tulkoon kaikki heidän pahuutensa sinun kasvojesi eteen, ja sälytä heille kannettavaksi se, minkä olet minulle pannut kaikkien rikoksieni tähden. Sillä monet ovat huokaukseni, ja sydämeni on voipunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Kuinka onkaan Herra vihallaan peittänyt tytär Siionin! Hän heitti taivaasta maahan Israelin kunnian eikä muistanut jalkojensa astinlautaa vihansa päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Herra on hävittänyt säälimättä kaikki Jaakobin asuinsijat. Hän on hajottanut vihassaan tytär Juudan linnoitukset ja hävittänyt ne maan tasalle. Hän on häväissyt valtakunnan ja sen ruhtinaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Hän on vihan hehkussa hakannut Israelin sarven kerrassaan poikki. Hän veti oikean kätensä takaisin vihamiehen edestä ja paloi Jaakobissa kuin tulenliekki, joka kuluttaa kaiken ympäriltään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Hän jännitti jousensa kuin vihamies, seisoi oikea käsi koholla kuin vihollinen ja tappoi kaiken, mikä oli silmälle ihanaa. Tytär Siionin telttamajaan hän vuodatti kiivautensa kuin tulen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Herra on ollut kuin vihamies ja on hävittänyt Israelin. Hän hävitti kaikki sen palatsit, turmeli sen linnoitukset ja tuotti tytär Juudalle paljon valitusta ja murhetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Hän särki aitauksensa kuin puutarhan aidan ja hävitti juhlanviettopaikkansa. Herra on saattanut unohduksiin Siionissa juhla-ajat ja sapatit ja on kiivaassa suuttumuksessaan saattanut häpeään kuninkaat ja papit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Herra on hylännyt alttarinsa, häväissyt pyhäkkönsä, luovuttanut vihamiehen käteen palatsiensa muurit. He nostivat huudon Herran huoneessa, huudon kuin juhlapäivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Herra oli päättänyt turmella tytär Siionin muurit. Hän on jännittänyt mittanuoran. Hän ei ole pidättänyt kättänsä hävittämästä ja on saattanut murheeseen varustukset ja muurit. Yhdessä ne menettävät voimansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Sen portit ovat vajonneet maahan. Hän särki ja mursi sen salvat. Sen kuningas ja ruhtinaat ovat pakanoiden seassa. Lakia ei ole, eivätkä sen profeetat saa näkyjä Herralta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Maassa istuvat ääneti tytär Siionin vanhimmat. He ovat heittäneet tomua päänsä päälle ja vyöttäytyneet säkkeihin. Maata kohden ovat painaneet päänsä Jerusalemin neitsyet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Silmäni ovat kyynelistä hiuenneet ja sisukseni kuohuvat. Maksani on maahan vuodatettu tyttären, kansani, sortumisen tähden. Sillä lapset ja imeväiset nääntyvät kaupungin kaduilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'He sanovat äideilleen: \"Missä on leipää ja viiniä?\" kun he nääntyvät kuin kaatuneet kaupungin kaduilla ja heittävät henkensä äitiensä syliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Mitä sinulle mainitsisin, mihin vertaisin sinua, tytär Jerusalem? Minkä asettaisin rinnallesi lohduttaakseni sinua, neitsyt, tytär Siion? Sillä suuri kuin meri on sortumisesi. Kuka sinut parantaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Profeettasi ovat nähneet sinulle turhia, mauttomia näkyjä. He eivät ole paljastaneet syntiäsi, niin että olisivat kääntäneet kohtalosi, vaan ovat nähneet sinulle turhia, eksyttäviä ennustuksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Sinulle lyövät yhteen kämmeniään kaikki ohikulkijat, he viheltävät ja nyökyttävät ilkkuen päätään tytär Jerusalemille: \"Tämäkö on kaupunki, jota sanottiin kauneuden täydellisyydeksi, kaiken maan iloksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Suu ammollaan sinua vastaan ovat kaikki vihamiehesi. He viheltävät, kiristelevät hampaitaan ja sanovat: \"Me olemme sen nielleet. Tämä on juuri se päivä, jota olemme toivoneet. Se on tullut meille, olemme sen nähneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Herra on tehnyt, mitä oli aikonut. Hän on täyttänyt sanansa, sen, josta hän oli antanut käskyn aikoja sitten. Hän on repinyt alas säälimättä, on antanut vihamiesten iloita sinusta ja kohottanut vihollistesi sarven. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Heidän sydämensä voihkii Herran puoleen. Sinä, tytär Siionin muuri, anna kyyneltesi vuotaa virtana yötä päivää! Älä suo itsellesi lepoa, älköön silmäteräsi olko toimeton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Nouse, kohota valitushuuto yöllä, kun yövartiot alkavat. Anna sydämesi vuotaa kuin vesi Herran kasvojen edessä. Kohota kätesi häntä kohden pienten lastesi elämän puolesta, kun ne nääntyvät nälkään kaikkien katujen kulmissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Katso, Herra, ja huomaa, ketä olet antanut tämän kohdata. Pitäisikö vaimojen syödä oma hedelmänsä, vaalimansa pienet lapset? Pitäisikö Herran pyhäkössä tappaa papit ja profeetat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Maassa, kaduilla, makaa nuoria ja vanhoja. Neitsyeni ja nuorukaiseni ovat kaatuneet miekkaan. Sinä olet surmannut vihasi päivänä, olet teurastanut säälimättä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Sinä kutsuit kuin juhlapäivän viettoon kauhistajani joka taholta. Herran vihan päivänä ei jäänyt pelastunutta eikä pakoon päässyttä. Ne, joita olin vaalinut ja jotka olin saanut isoiksi, ne minun vihamieheni lopetti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Minä olen mies, joka olen nähnyt kurjuutta hänen vihastuksensa vitsan alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Hän on ajanut ja kuljettanut minut pimeyteen eikä valkeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Juuri minua vastaan hän on kääntänyt kätensä kaiken päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Hän on kalvanut lihani ja nahkani ja musertanut luuni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Hän on rakentanut varustukset minua vastaan ja piirittänyt minut myrkyllä ja vaivalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Hän on pannut minut asumaan pimeydessä kuin entisajan kuolleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Hän on tehnyt muurin ympärilleni, niin etten pääse ulos. Hän on pannut minut raskaisiin vaskikahleisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Vaikka itken ja huudan apua, hän vaientaa rukoukseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Hakatuista kivistä hän on tehnyt teilleni muurin ja mutkistanut polkuni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Vaaniva karhu hän on ollut minulle, piilossa väijyvä leijona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Hän on vienyt harhaan tieni, repinyt minut kappaleiksi ja tehnyt minut autioksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Hän on jännittänyt jousensa ja asettanut minut nuoltensa maalitauluksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Hän on ampunut munuaisiini viinensä lapset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Minusta on tullut koko kansalleni naurun ja heidän jokapäiväisen pilkkalaulunsa aihe.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Hän on ravinnut minua katkeruudella, juottanut minua koiruoholla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Hän on murskannut hampaani soralla painaessaan minut alas tomuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Sinä olet syössyt sieluni pois rauhasta, olen unohtanut, mitä on onni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'Sanon: mennyt on voimani ja toivoni Herraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Muista, kuinka kurja ja hylätty olen, minulle on juotettu koiruohoa ja myrkkyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Sitä muistellessani sieluni vajoaa alas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Tämän panen sydämelleni, sen tähden odotan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Herran armoa on, ettemme ole aivan hävinneet, sillä hänen laupeutensa ei ole loppunut:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'se on joka aamu uusi, ja suuri on hänen uskollisuutensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Minun osani on Herra, sanoo sieluni. Sen tähden odotan häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Hyvä on Herra häntä odottaville, sielulle, joka häntä etsii.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Hyvä on hiljaisuudessa toivoa Herran apua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Hyvä on miehelle, että hän kantaa iestä nuoruudessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Istukoon hän yksin ja hiljaa, kun Herra on pannut sen hänen päällensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Laskekoon suunsa tomuun – ehkä on toivoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Ojentakoon hän posken sille, joka häntä lyö, saakoon häväistystä kylliksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Sillä Herra ei hylkää iankaikkisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'vaan jos hän on saattanut murheelliseksi, hän osoittaa laupeutta suuressa armossaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Sillä hän ei vaivaa sydämensä halusta eikä murehduta ihmislapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Kun jalkojen alle murskataan kaikki vangit maassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'kun väännetään miehen oikeus Korkeimman kasvojen edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'kun ihmiselle tehdään vääryyttä hänen riita-asiassaan – eikö Herra näkisi sitä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Onko kukaan sanonut, ja se on tapahtunut, mitä Herra ei ole käskenyt?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Korkeimman suusta lähtee paha ja hyvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Miksi tuskittelee ihminen eläessään, tuskitelkoon mies syntiensä tähden?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Koetelkaamme teitämme, tutkikaamme niitä ja palatkaamme Herran luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Kohottakaamme sydämemme ja kätemme Jumalan puoleen, joka on taivaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Me olimme luopuneet pois ja olleet kapinalliset. Sinä et ole antanut anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Sinä peitit itsesi vihaan, ajoit meitä takaa, surmasit etkä säälinyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Sinä olet peittänyt itsesi pilvellä, niin ettei rukous pääse läpi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Tunkioksi ja hylkytavaraksi sinä olet meidät tehnyt kansakuntien joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Kaikki vihamiehemme ovat avanneet suunsa meitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Osaksemme ovat tulleet kauhu ja kuoppa, autius ja hävitys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Vesipurot juoksevat silmistäni tyttären, kansani, sortumisen tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Silmäni vuotaa lakkaamatta, taukoamatta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'kunnes Herra katsoo ja näkee taivaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Silmäni tuottaa tuskaa sielulleni kaikkien kaupunkini tyttärien tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Kiihkeästi pyydystivät minua kuin lintua ne, jotka ovat syyttä vihamiehiäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'He sulkivat kuoppaan elämäni ja heittivät päälleni kiviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Vedet tulvivat pääni yli. Sanoin: olen hukassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Minä huusin, Herra, syvältä kaivosta nimeäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Kuulit huutoni. Älä peitä korvaasi huudoltani äläkä huokaukseltani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Olit läsnä silloin, kun sinua huusin. Sanoit: \"Älä pelkää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Sinä, Herra, ajoit sieluni asian ja lunastit henkeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Olethan nähnyt, Herra, kärsimäni sorron: hanki minulle oikeus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Olethan nähnyt kaiken heidän kostonsa ja kaikki heidän juonensa minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Olet kuullut heidän häväistyksensä, Herra ja kaikki heidän juonensa minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'Minun vastustajieni huulet ja heidän aikeensa ovat minua vastaan kaiken päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Istuivatpa he tai nousivat, katso: minä olen heille pilkkalauluna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Kosta heille, Herra, heidän kättensä teot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Anna heille pelko sydämeen, ja kohdatkoon heitä kirouksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Aja heitä takaa vihassasi ja hävitä heidät Herran taivaan alta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Kuinka onkaan kulta tummunut, muuttunut hyvä kulta. Kuinka pyhät kivet on viskelty kaikkiin kadunkulmiin!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Siionin pojat, nuo kalliit, punnitut puhtaimman kullan arvoisiksi – kuinka he ovatkaan saviastioiden, savenvalajan kätten tekojen, arvoisia!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Valaatkin tarjoavat nisiään ja imettävät poikasiaan, mutta tytär, minun kansani, on tullut tylyksi kuin strutsi erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Imeväisen kieli tarttuu suulakeen janon tähden. Lapsukaiset pyytävät leipää, eikä ole, kuka sitä heille taittaisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Ne, jotka söivät herkkuja, nääntyvät kaduilla. Ne, joita purppuran päällä kanneltiin, syleilevät tunkioita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Tyttären, kansani, syntivelka on Sodoman syntiä suurempi. Sodoma hävitettiin äkkiä käsien koskematta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Sen nasiirit olivat lunta puhtaammat ja maitoa valkoisemmat, heidän hahmonsa oli koralleja punaisempi ja he olivat näöltään kuin safiiri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Nyt heidän muotonsa on nokea mustempi, eikä heitä tunneta kaduilla. Heidän nahkansa on kiinni luissa ja on kuivettunut kuin puu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Parempi oli miekan kaatamien kuin nälän kaatamien, jotka menehtyivät kuin lävistetyt, pellon viljaa vailla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Armeliaat vaimot keittivät omin käsin lapsiaan. Ne tulivat heille ruuaksi tyttären, kansani, sortuessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Herra on pannut täytäntöön kiivautensa, vuodattanut vihansa hehkun. Hän on sytyttänyt Siioniin tulen, joka on kuluttanut sen perustukset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Eivät olisi uskoneet maan kuninkaat, eikä kukaan maanpiirin asukkaista, että vastustaja ja vihollinen hyökkää sisään Jerusalemin porteista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Se tapahtui profeettojen syntien ja sen pappien pahojen tekojen tähden, niiden, jotka siellä olivat vuodattaneet vanhurskaiden verta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'He harhailivat sokeina kaduilla, verellä tahrattuina, niin ettei heidän vaatteisiinsa voinut koskea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, '\"Väistykää! Saastainen!\" huudettiin heistä. \"Väistykää, väistykää, älkää koskeko!\" He pakenivat ja kulkivat. Pakanoiden seassa sanottiin: \"He eivät saa enää asua täällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Herran kasvot ovat hajottaneet heidät, eikä hän heihin enää katso. Pappeja ei kunnioitettu eikä vanhimpia armahdettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Vieläkin odotimme silmät rauenneina turhaan apua. Tähystyspaikastamme tähyilimme kansaa, josta ei tullut pelastusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Askeleitamme vaanittiin, niin ettemme voineet kulkea kaduillamme. Meidän loppumme lähestyi, päivämme täyttyivät – niin, loppumme tuli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Vainoojamme olivat nopeammat kuin kotkat taivaalla. Vuorilla he ajoivat meitä takaa ja väijyivät meitä erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Hän, elämämme turva, Herran voideltu, joutui vangiksi heidän kuoppiinsa, hän, josta me olimme sanoneet: hänen varjossaan elämme pakanakansojen joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Iloitse ja riemuitse, tytär Edom, joka asut Uusin maassa! Mutta malja on tuleva sinunkin kohdallesi: sinä juovut ja paljastat itsesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Sinun syntivelkasi, tytär Siion, on loppunut, eikä Herra enää siirrä sinua vankeuteen. Sinun syntivelkasi, tytär Edom, hän on kostava ja paljastava syntisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Muista, Herra, mitä meille on tapahtunut. Katso ja näe häväistyksemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Perintöosamme on siirtynyt vieraille ja talomme muukalaisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Olemme tulleet orvoiksi, isättömiksi, äitimme ovat kuin leskiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Oman juomavetemme ostamme rahalla. Saamme omat puumme, jos maksamme niistä hinnan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Vainoojamme ovat niskassamme. Kun uuvumme, meille ei ole lepoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Egyptille ja Assurille olemme lyöneet kättä saadaksemme tarpeeksi leipää ravinnoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Isämme ovat syntiä tehneet. Heitä ei enää ole. Me kannamme heidän syntiensä taakkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Orjat hallitsevat meitä. Ei ole sitä, joka tempaisi meidät heidän käsistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Henkemme kaupalla noudamme leipämme väistäen miekkaa erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Ihomme oli musta kuin uuni nälän poltteiden takia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Naisia raiskataan Siionissa, neitsyitä Juudan kaupungeissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Ruhtinaita heidän kätensä hirttävät, vanhinten kasvoja ei pidetä arvossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Nuorukaiset kantavat myllynkiviä, poikaset kompastelevat puutaakkojen alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Poissa ovat vanhukset porteista, nuorukaiset soittimiensa äärestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Poissa on ilo sydämistämme, karkelomme on muuttunut valitukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Pudonnut on päästämme kruunu. Voi meitä, sillä olemme syntiä tehneet!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Tästä syystä on sydämemme tullut sairaaksi, näiden tähden ovat silmämme pimenneet –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Siionin vuoren tähden, joka on autiona, jolla ketut juoksentelevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Sinä, Herra, pysyt iankaikkisesti ja valtaistuimesi polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Miksi unohdat meidät ainiaaksi, hylkäät meidät pitkiksi ajoiksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Palauta meidät, Herra, luoksesi, niin palaamme. Uudista päivämme entiselleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Vai oletko meidät kokonaan hylännyt ja vihastunut meihin yli määrän?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Kolmantenakymmenentenä vuotena, neljännessä kuussa, kuukauden viidentenä päivänä, kun minä olin karkotettujen joukossa Kebar-joen varrella, tapahtui, että taivaat aukenivat, ja näin Jumalan näkyjä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Kuukauden viidentenä päivänä, kuningas Joojakinin karkotuksen viidentenä vuotena,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'Jumalan sana tuli pappi Hesekielille, Buusin pojalle, Kaldean maassa Kebar-joen varrella, ja hänen päälleen tuli siellä Herran käsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Näin, ja katso: myrskytuuli tuli pohjoisesta, suuri pilvi ja leimahteleva tuli, ja pilveä ympäröi hohde, ja tulen keskeltä näkyi ikään kuin hehkuvaa malmia, keskeltä tulta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Sen keskeltä näkyivät neljän olennon hahmot. Näöltään ne olivat tällaiset: niillä oli ihmisen hahmo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Niillä oli kullakin neljät kasvot ja kullakin oli neljä siipeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Niiden sääret olivat suorat ja jalkaterät kuin vasikan sorkat, ja ne välkkyivät kuin kiiltävä vaski.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Siipiensä alla niillä oli, neljällä eri puolellaan, ihmiskädet. Kasvot ja siivet niillä neljällä olivat näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Niiden siivet koskettivat toisiaan. Kulkiessaan ne eivät kääntyneet. Ne kulkivat kukin suoraan eteenpäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Niiden kasvot olivat ihmiskasvojen kaltaiset. Mutta oikealla puolella niillä neljällä oli leijonankasvot, vasemmalla puolen niillä neljällä oli häränkasvot, myös niillä neljällä oli kotkankasvot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Niin olivat niiden kasvot. Mutta siivet niillä oli levitettyinä ylöspäin. Kullakin oli kaksi, jotka koskettivat toisen siipiä, ja kaksi, joilla ne peittivät ruumistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Ne kulkivat suoraan eteenpäin. Minne Henki vaati kulkemaan, sinne ne kulkivat. Kulkiessaan ne eivät kääntyneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Olentojen hahmo oli näöltään kuin tuliset hiilet, jotka paloivat tulisoihtujen näköisinä. Tulta liekehti olentojen välissä, ja tuli hohti, ja tulesta lähti salamoita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Olennot kiitivät edestakaisin ja olivat nähdä kuin salaman leimaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Mutta kun katselin olentoja, niin katso: yksi pyörä oli maassa olentojen kohdalla, kunkin niiden neljän etupuolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Pyörät olivat näöltään ja teoltaan kuin krysoliittia, ja niillä neljällä oli sama muoto, ja ne olivat näöltään ja teoltaan, kuin olisi ollut sisäkkäin pyörä pyörässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Ne kulkivat neljään eri suuntaan, kun kulkivat. Kulkiessaan ne eivät kääntyneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Niiden kehät olivat korkeat ja pelottavat. Niiden kehät olivat täynnä silmiä, ympäriinsä niissä neljässä pyörässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Kun olennot kulkivat, pyörät kulkivat niiden mukana, ja kun olennot kohosivat ylös maasta, kohosivat pyörätkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Minne Henki meni, sinne ne kulkivat – minne vain Henki kulkemaan vaati. Pyörät kohosivat samalla kuin nekin, sillä olentojen henki oli pyörissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Kun olennot kulkivat, kulkivat nämäkin; kun ne seisoivat, seisoivat nämäkin. Kun ne kohosivat ylös maasta, kohosivat pyörät samalla kuin nekin, sillä olentojen henki oli pyörissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Olentojen päiden yläpuolelle hahmottui taivaanvahvuus kuin pelottava kristalli kaartuen ylös niiden päiden yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'Taivaanvahvuuden alla niillä oli siivet suorina, toisen siipi toisen siipeä kohden. Kullakin oli kaksi, jotka sitä peittivät – kaksi, jotka peittivät sen ruumista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Minä kuulin niiden siipien kohinan kuin paljojen vetten kohinan, kuin Kaikkivaltiaan äänen, kun ne kulkivat. Niiden ääni oli kuin sotaleirin ääni. Kun ne seisoivat, ne laskivat siipensä alas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Kuului ääni ylhäältä taivaanvahvuudesta, joka oli niiden pään päällä. Kun ne seisoivat, ne laskivat siipensä alas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Taivaanvahvuuden yläpuolella, joka oli niiden pään päällä, oli valtaistuimen muotoinen, näöltään kuin safiirikiveä. Valtaistuimen muotoisella istui hahmo, ihmisen näköinen, kohoten korkealle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Näin ikään kuin hehkuvaa malmia, tulen näköistä, jota ympäröi kehä ylöspäin siitä, mikä näytti hänen lanteiltaan. Taas alaspäin siitä, mikä näytti hänen lanteiltaan, näin kuin tulen näköistä, ja sitä ympäröi hohde.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Kuin kaari, joka on pilvessä sadepäivänä, niin oli näöltään sitä ympäröivä hohde. Sellainen oli katsoa Herran kirkkauden hahmo. Kun sen näin, lankesin kasvoilleni. Kuulin äänen, kun joku puhui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Hän sanoi minulle: \"Ihmislapsi, nouse jaloillesi, puhun sinulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Minuun tuli Henki, kun hän puhui minulle, ja nosti minut jaloilleni, ja kuulin hänen puhuvan minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Hän sanoi minulle: \"Ihmislapsi, lähetän sinut israelilaisten luo, kapinallisten pakanoiden luo, jotka ovat kapinoineet minua vastaan. He ja heidän isänsä ovat luopuneet minusta, aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Nuo lapset, joilla on kovat kasvot ja paatuneet sydämet – niiden luo sinut lähetän, ja sinun on sanottava heille: Näin sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Kuulkoot tai olkoot kuulematta – sillä uppiniskainen suku he ovat – he tulevat kuitenkin tietämään, että profeetta on ollut heidän keskellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Mutta sinä, ihmislapsi, älä pelkää heitä, äläkä pelkää heidän sanojaan, vaikka edessäsi on ohdakkeita ja orjantappuroita ja asut skorpionien seassa. Älä pelkää heidän sanojaan äläkä arkaile heidän kasvojaan, sillä he ovat kapinoiva suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Vaan puhu heille minun sanani, kuulkoot tai olkoot kuulematta, sillä kapinallisia he ovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Mutta sinä, ihmislapsi, kuule, mitä sinulle sanon. Älä ole kapinallinen, niin kuin kapinallinen suku on. Avaa suusi ja syö, mitä sinulle annan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Näin, ja katso: käsi ojennettiin minua kohti, ja katso: siinä oli kirjakäärö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Hän levitti sen eteeni, ja katso: se oli kirjoitettu täyteen sisältä ja päältä. Siihen oli kirjoitettu itkuvirret, huokaukset ja voi-huudot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Sitten hän sanoi minulle: \"Ihmislapsi, syö, minkä tästä löydät. Syö tämä kirjakäärö, mene ja puhu Israelin heimolle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Avasin suuni, ja hän antoi tämän kirjakäärön minulle syötäväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Hän sanoi minulle: \"Ihmislapsi, ravitse vatsasi ja täytä itsesi tällä kirjakääröllä, jonka sinulle annan.\" Minä söin, ja se oli minun suussani makea kuin hunaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Hän sanoi minulle: \"Ihmislapsi, mene nyt Israelin heimon luo ja puhu heille minun sanani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Sillä sinua ei lähetetä outokielisen ja kankeapuheisen kansan luo, vaan Israelin heimon luo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'ei monien kansojen luo, outokielisten ja kankeapuheisten, joiden puhetta et ymmärrä. Jos niiden luo lähettäisin sinut, he sinua kuulisivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Mutta Israelin heimo ei tahdo sinua kuulla, koska he eivät tahdo kuulla minua. Sillä koko Israelin heimolla on kova otsa ja paatunut sydän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Katso, teen kasvosi yhtä koviksi kuin heidän kasvonsa ja otsasi yhtä kovaksi kuin heidän otsansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Timantin kaltaiseksi, kiveä kovemmaksi teen otsasi. Älä pelkää heitä äläkä arkaile heidän kasvojaan, sillä he ovat kapinoiva suku.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Sitten hän sanoi minulle: \"Ihmislapsi, kaikki sanani, jotka sinulle puhun, ota sydämeesi ja kuule korvillasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Mene ja saavu karkotettujen luo, kansasi lasten luo. Puhu heille ja sano heille: Näin sanoo Herra, Herra – kuulkoot he tai olkoot kuulematta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Niin Henki nosti minut, ja minä kuulin takaani suuren, jylisevän äänen: \"Kiitetty olkoon Herran kirkkaus, siinä missä se on!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'ja olentojen siipien äänen, kun ne löivät toisiinsa, samalla pyörien äänen ja suuren, jylisevän äänen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Silloin Henki nosti minut ja otti minut, ja minä kuljin murheellisena henkeni kiivaudessa, ja Herran käsi oli väkevänä päälläni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Tulin Tell-Aabibiin karkotettujen luo, jotka asuivat Kebar-joen varrella; ja siellä, missä he asuivat, istuin hämilläni heidän keskuudessaan seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Mutta seitsemän päivän kuluttua minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, '\"Ihmislapsi, olen asettanut sinut Israelin heimolle vartijaksi. Kun kuulet sanan suustani, on sinun varoitettava heitä puolestani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Jos sanon jumalattomalle: sinun on kuolemalla kuoltava, mutta sinä et häntä varoita etkä puhu varoittaaksesi jumalatonta hänen jumalattomasta tiestään, että pelastaisit hänen henkensä, niin jumalaton kuolee synnissään, mutta hänen verensä vaadin sinun kädestäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Mutta jos sinä varoitat jumalatonta eikä hän käänny jumalattomuudestaan eikä jumalattomalta tieltään, niin hän kuolee synnissään, mutta sinä olet sielusi pelastanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Jos taas vanhurskas kääntyy pois vanhurskaudestaan ja tekee vääryyttä ja panen kompastuksen hänen eteensä, niin hän kuolee – kun et häntä varoittanut, niin hän kuolee synnissään, ja vanhurskautta, jota hän oli harjoittanut, ei muisteta – mutta hänen verensä vaadin sinun kädestäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Mutta jos sinä varoitat vanhurskasta, ettei vanhurskas tekisi syntiä, eikä hän tee syntiä, niin hän totisesti on elävä, koska otti varoituksesta vaarin, ja sinä olet sielusi pelastanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Herran käsi tuli siellä minun päälleni, ja hän sanoi minulle: \"Nouse ja mene laaksoon, niin puhun siellä sinulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Nousin ja menin laaksoon, ja katso, siellä seisoi Herran kirkkaus, samanlainen kuin se kirkkaus, jonka olin nähnyt Kebar-joen varrella. Lankesin kasvoilleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Mutta minuun tuli Henki ja nosti minut jaloilleni, ja hän puhui minulle ja sanoi minulle: \"Mene, sulkeudu sisälle huoneeseesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Sinä, ihmislapsi! Katso, sinut pannaan köysiin ja sidotaan niillä, niin ettet voi mennä ulos heidän keskuuteensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Tartutan kielesi suusi lakeen, niin että mykistyt etkä voi olla heille nuhtelijana, sillä he ovat kapinallinen suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Mutta kun puhun sinulle, avaan suusi, ja sinun on sanottava heille: Näin sanoo Herra, Herra. Kuulkoon, joka kuulee, ja olkoon kuulematta, joka ei kuule, sillä he ovat kapinoiva suku.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, '\"Sinä ihmislapsi, ota tiili ja aseta se eteesi ja piirrä siihen kaupunki, Jerusalem.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Pane se piiritykseen, rakenna sitä vastaan saartovarusteet, luo sitä vastaan valli, aseta sitä vastaan sotaleirejä ja pane sitä ympäröimään muurinmurtajia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Ota sitten rautainen leivinlevy ja aseta se rautamuuriksi itsesi ja kaupungin väliin ja suuntaa kasvosi kaupunkia kohti, niin että se tulee piiritykseen, ja piiritä sitä. Tämä on oleva merkki Israelin heimolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Pane sitten maata vasemmalle kyljellesi ja aseta sitä painamaan Israelin heimon syntivelka. Yhtä monta päivää, kuin sinä makaat sillä, sinä kannat heidän syntivelkaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Minä panen sinulle saman luvun päiviä, kuin on heidän syntivelkansa vuosia: kolmesataa yhdeksänkymmentä päivää. Niin kannat Israelin heimon syntivelkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Kun olet saanut ne päättymään, sinun on pantava maata toistamiseen, oikealle kyljellesi, ja kannettava Juudan heimon syntivelkaa neljäkymmentä päivää. Päivän kutakin vuotta kohden olen sinulle pannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Suuntaa kasvosi ja paljastettu käsivartesi piiritettyä Jerusalemia kohti ja profetoi sitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Katso, panen sinut köysiin, niin ettet voi kääntyä kyljeltä toiselle, kunnes piirityspäiväsi ovat päättyneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Ota myös itsellesi vehnää, ohria, papuja, linssiä, hirssiä ja spelttiä, pane ne samaan astiaan ja tee niistä itsellesi leipää. Yhtä monta päivää, kuin makaat kyljelläsi, kolmesataa yhdeksänkymmentä päivää, sinun tulee sitä syödä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Ruoka, jota syöt, sinun tulee syödä painon mukaan: kaksikymmentä sekeliä päivässä. Sinun on syötävä se määräaikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Vettä sinun on juotava mitan mukaan: kuudennes hiin-mittaa sinun on juotava määräajoin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Ohrarieskana sinun on se syötävä, ja ihmisen ulosteella sinun on se paistettava heidän silmiensä edessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Herra sanoi: \"Näin tulevat israelilaiset syömään leipänsä saastaisena pakanoiden seassa, jonne heidät karkotan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Mutta minä sanoin: \"Voi Herra, Herra! Katso, milloinkaan sieluni ei ole ollut saastutettu. En ole syönyt itsestään kuollutta enkä kuoliaaksi raadeltua nuoruudestani tähän asti, eikä mitään saastaista lihaa ole tullut suuhuni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Hän sanoi minulle: \"Katso, annan sinulle eläimen lantaa ihmisen ulosteen sijaan. Valmista leipäsi sen päällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Hän sanoi minulle: \"Ihmislapsi, katso, murran leivän tuen Jerusalemilta, ja he tulevat syömään leipää painon mukaan ja huolissaan sekä juomaan vettä mitan mukaan ja kauhuissaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'niin että heillä on puute leivästä ja vedestä ja yhdessä he nääntyvät ja voipuvat syntivelkansa tähden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, '\"Sinä, ihmislapsi, ota terävä miekka. Ota se partaveitseksesi, ja aja sillä hiuksesi ja partasi. Ota sitten vaaka ja jaa ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Polta kolmannes tulessa keskellä kaupunkia, sitten kun piirityspäivät ovat lopussa. Kolmannes ota ja lyö miekalla sen ympärillä. Kolmannes hajota tuuleen, ja minä ajan niitä takaa paljastetulla miekalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Ota sitten niitä pieni määrä ja sido ne helmaasi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'ja ota niitä vielä, heitä ne tuleen ja polta ne tulessa. Siitä lähtee tuli koko Israelin heimoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Näin sanoo Herra, Herra: Tämä on Jerusalem. Pakanoiden keskelle olen sen asettanut ja niiden maat sen ympärille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Mutta se on kapinoinut minun oikeuksiani vastaan jumalattomammin kuin pakanat ja minun käskyjäni vastaan jumalattomammin kuin ne maat, jotka ovat sen ympärillä. Sillä oikeuksiani he ovat pitäneet halpoina eivätkä ole vaeltaneet säädöksieni mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Sen tähden, näin sanoo Herra, Herra: Koska teidän napinanne on ollut pahempi kuin pakanoiden, jotka ovat ympärillänne, ja koska te ette ole vaeltaneet käskyjeni mukaan, ette ole noudattaneet oikeuksiani ettekä ole tehneet niiden pakanoidenkaan oikeuksien mukaan, jotka ympärillänne ovat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'sen tähden, näin sanoo Herra, Herra: Katso, minäkin käyn sinun kimppuusi ja toteutan tuomiot keskelläsi pakanoiden silmien edessä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'ja teen sinulle kaikkien kauhistustesi tähden, mitä en ole vielä ennen tehnyt ja millaista en ole vastakaan tekevä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Sen tähden isät tulevat keskelläsi syömään lapsiaan, ja lapset tulevat syömään isiään, ja minä toteutan sinussa tuomiot ja hajotan jäännöksesi kaikkiin tuuliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Sen tähden, niin totta kuin minä elän, sanoo Herra, Herra: Totisesti, koska olet saastuttanut pyhäkköni kaikilla iljetyksilläsi ja kaikilla kauhistuksillasi, minäkin käännyn pois, en sääli enkä armahda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Kolmannes sinusta kuolee ruttoon ja nääntyy nälkään keskelläsi. Kolmannes kaatuu miekkaan ympärilläsi. Kolmanneksen hajotan kaikkiin tuuliin, ja ajan niitä takaa paljastetulla miekalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Minun vihani täyttyy, ja tyydytän kiivauteni heissä ja kostan. He tulevat tietämään, että minä, Herra, olen puhunut kiivaudessani, kun toteutan heissä vihani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Teen sinut raunioksi ja häväistyksi jokaisen ohikulkijan silmissä pakanoiden keskuudessa, jotka ovat ympärilläsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Se on oleva häväistys ja herjaus, varoitus ja pelästys pakanoiden joukossa, jotka ovat ympärilläsi, kun toteutan sinussa tuomiot vihassa ja kiivaudessa ja kovin rangaistuksin – minä, Herra, olen puhunut –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'kun lähetän heidän kimppuunsa nälän pahat nuolet, joista tulee tuhooja ja jotka lähetän teitä tuhoamaan. Lisään teille nälkää ja murran teiltä leivän tuen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Lähetän kimppuunne nälän ja pahat petoeläimet, jotka riistävät sinulta lapset. Rutto ja veri käyvät päällesi, ja annan miekan tulla kimppuusi. Minä, Herra, olen puhunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, '\"Ihmislapsi, käännä kasvosi Israelin vuoria kohti ja profetoi niitä vastaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'ja sano: Israelin vuoret, kuulkaa Herran, Herran sana. Näin sanoo Herra, Herra vuorille ja kukkuloille, puroille ja laaksoille: Katso, minä annan miekan tulla päällenne ja hävitän uhrikukkulanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Alttarinne jäävät autioiksi, auringonpatsaanne murskataan, ja surmattujenne annan kaatua epäjumalienne eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Panen israelilaisten ruumiit heidän epäjumaliensa eteen ja hajotan heidän luunsa heidän alttariensa ympärille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Kaikilla asuinpaikoillanne tulevat kaupungit raunioiksi ja uhrikukkulat autioiksi. Alttarinne jäävät raunioiksi ja autioiksi, epäjumalanne murskataan ja hävitetään, auringonpatsaanne särjetään, ja aikaansaannoksenne pyyhkäistään pois,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'surmattuja kaatuu keskellänne, ja te tulette tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Mutta jätän jäännöksen: teillä on oleva miekasta pelastuneita pakanoiden joukossa, kun teidät hajotetaan niiden maihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Silloin ne teistä, jotka pelastuvat, muistavat minut pakanoiden seassa, mihin heidät on viety vangeiksi. Särjen heidän haureellisen sydämensä, joka poikkesi minusta pois, ja heidän silmänsä, jotka haureellisina kulkivat heidän epäjumaliensa perässä. Heitä etoo oma itsensä pahojen tekojen tähden, joita he ovat tehneet, kaikkien heidän kauhistustensa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Silloin he tulevat tietämään, että minä olen Herra. En ole sanonut turhaan tuottavani teille tätä onnettomuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Näin sanoo Herra, Herra: lyö käsiäsi yhteen, polje jalkaasi ja sano: \'Voi!\' kaikille Israelin heimon pahoille kauhistuksille, heidän, jotka kaatuvat miekkaan, nälkään ja ruttoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Kaukainen kuolee ruttoon, läheinen kaatuu miekkaan, jäljelle jäänyt ja säilynyt kuolee nälkään, ja panen vihani täytäntöön heissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Tulette tietämään, että minä olen Herra, kun heitä on surmattuina heidän epäjumaliensa keskellä, heidän alttariensa ympärillä, jokaisella korkealla kukkulalla, kaikilla vuorten huipuilla, jokaisen vihreän puun alla ja jokaisen tuuhean tammen alla, missä paikassa vain he ovat tarjonneet suloista tuoksua kaikille epäjumalilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Ojennan käteni heitä vastaan ja teen maan autiommaksi ja hävitetymmäksi, kuin on Diblatan erämaa, kaikilla heidän asuinpaikoillaan, ja he tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, '\"Sinä, ihmislapsi, näin sanoo Herra, Herra Israelin maalle: Loppu! Tämän maan neljälle äärelle tulee loppu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Nyt tulee sinulle loppu, ja lähetän vihani sinua vastaan, tuomitsen sinut vaelluksesi mukaan ja annan kaikkien kauhistustesi kohdata sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'En sääli sinua enkä armahda, vaan annan vaelluksesi kohdata sinua, ja kauhistuksesi tulevat keskuuteesi, ja tulette tietämään, että olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Näin sanoo Herra, Herra: Onnettomuus! Yksi ja ainoa onnettomuus! Katso, se tulee!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Loppu tulee, tulee loppu! Se herää sinua vastaan! Katso, se tulee!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Vuoro tulee sinulle, maan asuja. Aika tulee, päivä on lähellä. On hämminki, ilohuutoa ei kaiu vuorilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Nyt kohta vuodatan kiivauteni päällesi, panen vihani täytäntöön sinussa, tuomitsen sinut vaelluksesi mukaan ja annan kaikkien kauhistustesi kohdata sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'En sääli enkä armahda. Annan vaelluksesi kohdata sinua, ja kauhistuksesi tulevat keskellesi, ja te tulette tietämään, että minä, Herra, olen se, joka lyön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Katso, päivä! Katso, se tulee! Vuoro on tullut, ruoska kukkii ja julkeus versoo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Väkivalta on noussut ruoskaksi jumalattomuudelle. Heistä ei jää mitään, ei heidän pauhaavasta joukostaan eikä heidän melustaan. Poissa on heidän pöyhkeytensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Tullut on aika, joutunut päivä, älköön ostaja iloitko, älköönkä myyjä murehtiko, sillä viha tulee kaiken siellä pauhaavan joukon päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Sillä myyjä ei enää palaa myymään tavaroitaan, vaikka he vielä jäisivätkin henkiin. Sillä näky kaikkea sen pauhaavaa joukkoa vastaan ei peräydy, eikä kukaan synnillään vahvista elämäänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Puhalletaan torviin, varustetaan kaikki, mutta ei ole lähtijää sotaan, sillä minun vihani tulee kaiken siellä pauhaavan joukon päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Miekka on ulkona, sisällä rutto ja nälkä. Kedolla oleva kuolee miekkaan, kaupungissa olevan syö nälkä ja rutto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Mutta jos heitä joitakin pelastuu ja pääsee pakoon, he ovat vuorilla kuin laaksojen kyyhkyset, ja he vaikertavat kaikki, kukin syntiään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Kaikki kädet voipuvat, kaikki polvet käyvät veltoiksi kuin vesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'He kääriytyvät säkkeihin, heidät peittää vavistus, kaikilla kasvoilla on häpeä, ja kaikki päät ovat paljaiksi ajetut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Hopeansa he heittävät kaduille, ja heidän kultansa tulee heille saastaksi. Heidän kultansa ja hopeansa eivät voi heitä pelastaa Herran vihan päivänä. He eivät sillä tyydytä nälkäänsä eivätkä täytä vatsaansa, sillä siitä tuli heille kompastus syntiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'Korujen loistolla he ylpeilivät ja tekivät siitä kauhistavat kuvansa ja iljetyksensä. Sen tähden teen sen heille saastaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'Annan sen vieraitten käsiin ryöstettäväksi ja maan jumalattomien saaliiksi, ja he häpäisevät sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Käännän kasvoni heistä pois, niin että minun aarteeni häväistään. Väkivaltaiset menevät sinne ja häpäisevät sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Valmista kahle, sillä maa on täynnä verivelkojen tuomiota, ja kaupunki on täynnä väkivaltaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Tuon pakanoista pahimmat, ja he ottavat talonne omikseen. Teen lopun voimallisten ylpeydestä, ja heidän pyhäkkönsä häväistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Tulee hätä, ja he etsivät pelastusta, mutta sitä ei ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Häviö tulee häviön jälkeen, sanoma tulee sanoman jälkeen. He havittelevat näkyä profeetalta. Papilta katoaa opetus ja vanhimmilta neuvo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Kuningas murehtii, päämies pukeutuu kauhuun, ja maan kansan kädet vapisevat. Teen heille heidän teittensä mukaan, ja tuomitsen heidät heidän tuomioittensa mukaan, ja he tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'Kuudentena vuotena, kuudennessa kuussa, kuukauden viidentenä päivänä istuin huoneessani, ja Juudan vanhimmat istuivat edessäni, ja Herran, Herran käsi laskeutui siellä päälleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Näin, ja katso: tulennäköinen hahmo! Alaspäin siitä, mikä näytti sen lanteilta, oli tulta, ja ylöspäin sen lanteista näkyi loiste, joka oli nähdä kuin hehkuva malmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Hän ojensi ikään kuin käden ja tarttui minuun pääni hiussuortuvasta, ja Henki nosti minut maan ja taivaan välille ja vei minut Jerusalemiin Jumalan näyissä, sisimmän portin ovelle, joka on pohjoista kohden, sinne missä oli kiivauspatsas, joka oli herättänyt Herran kiivauden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Katso, siellä oli Israelin Jumalan kirkkaus, samanlainen nähdä kuin se, minkä olin nähnyt laaksossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Hän sanoi minulle: \"Ihmislapsi, nosta silmäsi pohjoista kohti.\" Nostin silmäni pohjoista kohti, ja katso: pohjoiseen päin alttarin portista oli tuo kiivauspatsas sisäänkäytävässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Hän sanoi minulle: \"Ihmislapsi, näetkö sinä, mitä he tekevät – suuria kauhistuksia, joita Israelin heimo tekee täällä, että menisin kauas pois pyhäköstäni? Mutta palaa vielä ja näet vielä suurempia kauhistuksia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Sitten hän vei minut esipihan ovelle, ja näin, ja katso: seinässä oli jokin aukko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Hän sanoi minulle: \"Ihmislapsi, murtaudu läpi seinän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Murtauduin seinän läpi, ja katso: jokin ovi! Hän sanoi minulle: \"Mene ja katso hirveitä kauhistuksia, joita he täällä tekevät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Menin ja näin, ja katso: kaikenlaisia inhottavia matelijoiden ja karjaeläinten kuvia ja kaikenlaisia Israelin heimon epäjumalia oli piirretty seinään ympäri kaikkialle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'Niiden edessä seisoi seitsemänkymmentä miestä, Israelin heimon vanhimpia, ja näiden keskellä seisoi Jaasanja, Saafanin poika. Kullakin heillä oli suitsutusastiansa kädessään, ja suitsutuspilvestä nousi tuoksu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Hän sanoi minulle: \"Näetkö, ihmislapsi, mitä Israelin heimon vanhimmat tekevät pimeässä, itse kukin kuvakammiossaan? Sillä he sanovat:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, '\' Herra ei meitä näe: Herra on hylännyt tämän maan.\'\" Hän sanoi minulle: \"Tulet näkemään vielä suurempia kauhistuksia, joita he tekevät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Hän vei minut Herran huoneen portin ovelle, joka on pohjoista kohden, ja katso, siellä istui naisia itkemässä Tammusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Sitten hän sanoi minulle: \"Näetkö, ihmislapsi? Tulet näkemään vielä kauhistuksia, suurempia kuin nämä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Sitten hän vei minut Herran huoneen sisemmälle esipihalle, ja katso: Herran temppelin ovella, eteisen ja alttarin välillä, oli noin kaksikymmentä viisi miestä. Heillä oli selät Herran temppeliin päin ja kasvot itään päin, ja he kumarsivat aurinkoa kohti itää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Hän sanoi minulle: \"Näitkö, ihmislapsi? Eikö ole Juudan heimolle kylliksi, että he tekevät kauhistuksia, joita he ovat täällä tehneet, koska he täyttävät maan väkivallalla ja aina uudelleen vihoittavat minut? Katso, kuinka he vievät viiniköynnöksen lehvää nenänsä eteen!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Mutta minäkin teen, minkä teen, vihassani: en sääli enkä armahda; ja vaikka he huutavat korviini suurella äänellä, en heitä kuule.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Sitten hän huusi suurella äänellä korviini ja sanoi: \"Tulkaa, kaupungin rankaisijat, ja olkoon kullakin kädessään tuhoaseensa!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Katso, kuusi miestä tuli Yläportilta päin, joka on pohjoista kohden, ja kullakin oli kädessä tuhoaseensa. Mutta yksi mies oli heidän keskellään, puettu pellavavaatteisiin ja vyötäisillään kirjoitustarvikkeet. He tulivat ja asettuivat seisomaan vaskialttarin ääreen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Mutta Israelin Jumalan kirkkaus oli kohonnut kerubin yläpuolelta, jonka yllä se oli ollut, huoneen kynnykselle ja huusi pellavavaatteisiin puetulle miehelle, jolla oli kirjoitustarvikkeet vyötäisillään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'Herra sanoi hänelle: \"Kierrä kaupungin, Jerusalemin, läpi ja tee merkki niiden miesten otsiin, jotka huokaavat ja valittavat kaikkia kauhistuksia, mitä sen keskuudessa tehdään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Niille toisille hän sanoi kuulteni: \"Kiertäkää kaupungin läpi hänen jäljessään ja surmatkaa. Älkää säälikö, älkää armahtako,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'tappakaa vanhukset, nuorukaiset, neitsyet, lapset ja vaimot, mutta älkää koskeko kehenkään, jolla on otsassaan merkki, ja aloittakaa pyhäköstäni.\" He aloittivat niistä miehistä, vanhimmista, jotka olivat temppelin edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Hän sanoi heille: \"Saastuttakaa temppeli ja täyttäkää esipihat surmatuilla. Menkää!\" Ja he menivät ja surmasivat kaupungissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Mutta kun minä heidän surmatessaan olin jäänyt jäljelle, lankesin kasvoilleni, huusin ja sanoin: \"Voi Herra, Herra! Hävitätkö sinä Israelin koko jäännöksen, kun vuodatat vihasi Jerusalemin päälle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Hän sanoi minulle: \"Israelin ja Juudan heimon syntivelka on erityisen suuri. Maa on täynnä verivelkoja, ja kaupunki on täynnä oikeuden vääristelyä, sillä he sanovat: \' Herra on hylännyt tämän maan, ei Herra näe.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Niinpä minäkään en sääli enkä armahda. Annan heidän vaelluksensa tulla heidän oman päänsä päälle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Katso, pellavavaatteisiin puettu mies, jolla oli kirjoitustarvikkeet vyötäisillään, toi tämän sanan: \"Olen tehnyt kaiken, kuten käskit minun tehdä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Näin, ja katso: taivaanvahvuuden yläpuolella, joka oli kerubien pään päällä, oli ikään kuin safiirikivi, näöltään valtaistuimen kaltainen. Se näkyi heidän yläpuolellaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Hän sanoi pellavavaatteisiin puetulle miehelle näin: \"Mene rattaiden väliin, kerubin alle ja täytä kourasi tulisilla hiilillä kerubien välistä ja sirottele ne yli kaupungin.\" Niin hän meni silmieni edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Kerubit seisoivat temppelin oikealla puolella, kun mies meni, ja pilvi peitti sisemmän esipihan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Silloin Herran kirkkaus kohosi kerubin yltä temppelin kynnykselle, ja pilvi täytti temppelin, ja esipiha tuli täyteen Herran kirkkauden hohdetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'Kerubien siipien kohina kuului uloimpaan esipihaan asti kuin kaikkivaltiaan Jumalan ääni, kun hän puhuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Kun hän käski pellavavaatteisiin puettua miestä sanoen: \"Ota tulta rattaiden välistä, kerubien välistä\", tämä meni ja seisahtui pyörän ääreen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Kerubi ojensi kätensä kerubien välitse tuleen, joka oli kerubien välissä, otti sitä ja antoi pellavavaatteisiin puetun kouraan. Tämä otti sen ja meni ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Kerubeilla näkyi ikään kuin ihmiskäsi heidän siipiensä alta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Näin, ja katso: kerubien kohdalla oli neljä pyörää, yksi pyörä aina yhden kerubin vierellä, ja pyörät olivat näöltään kuin krysoliittikivi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Niillä neljällä näytti olevan sama muoto, niin kuin olisi ollut pyörä pyörässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Ne kulkivat neljään eri suuntaan, kun kulkivat. Kulkiessaan ne eivät kääntyneet, sillä minne ensimmäinen meni, sinne ne kulkivat sen jäljessä. Ne eivät kääntyneet kulkiessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Niillä oli koko ruumis ja selät ja kädet ja siivet ja pyörät, kaikki neljä pyörää, täynnä silmiä, ympäriinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Niillä neljällä oli pyöränsä; ja pyöriä nimitettiin minun kuulteni \"rattaiksi\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Kullakin oli neljät kasvot: yhdet kerubinkasvot, toiset ihmiskasvot, kolmannet leijonankasvot ja neljännet kotkankasvot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'Kerubit kohosivat – ne olivat samat olennot, jotka olin nähnyt Kebar-joen varrella. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Kun kerubit kulkivat, kulkivat pyörät niiden lähellä, ja kun kerubit nostivat siipensä kohotakseen ylös maasta, eivät myöskään pyörät kääntyneet pois niiden läheltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Kun ne seisahtuivat, seisahtuivat nämäkin, ja kun ne kohosivat, kohosivat nämä niiden kanssa, sillä olentojen henki oli näissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Sitten Herran kirkkaus lähti temppelin kynnykseltä ja asettui kerubien ylle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Lähtiessään kerubit nostivat siipensä ja kohosivat maasta silmieni edessä, ja pyörät samalla kuin ne. Ne seisahtuivat Herran huoneen itäportin ovelle, ja niiden yläpuolella oli Israelin Jumalan kirkkaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Nämä olivat samat olennot, jotka olin nähnyt Israelin Jumalan alla Kebar-joen varrella, ja tulin tietämään, että ne olivat kerubeja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Neljät kasvot oli kullakin ja neljä siipeä kullakin, ja niiden siipien alla oli ikään kuin ihmiskädet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Niiden kasvot olivat ulkomuodoltaan samat, jotka olin nähnyt Kebar-joen varrella – sekä ulkonäön puolesta että itsessään. Ne kulkivat kukin suoraan eteenpäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Henki nosti minut ja vei minut Herran huoneen itäportille, joka on itään päin. Katso: portin ovella oli kaksikymmentä viisi miestä, ja minä näin niiden keskellä Jaasanjan, Assurin pojan, ja Pelatjan, Benajan pojan, kansan ruhtinaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Hän sanoi minulle: \"Ihmislapsi, nämä miehet miettivät turmiota ja pitävät pahaa neuvoa tätä kaupunkia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'He sanovat: \'Ei nyt kohta tule rakentaa taloja: se on pata, me olemme liha.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Sen tähden profetoi heitä vastaan, profetoi, ihmislapsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Herran Henki laskeutui päälleni ja sanoi minulle: \"Sano: Näin sanoo Herra: Näin te, Israelin heimo, sanotte, ja minä tunnen, mitä teidän hengestänne nousee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Paljon on teidän surmaamianne tässä kaupungissa, ja olette täyttäneet sen kadut surmatuilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Sen tähden, näin sanoo Herra, Herra: Surmattunne, jotka olette heittäneet sen keskelle, ovat liha, ja tämä kaupunki on pata, mutta teidät vien pois sen keskeltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Miekkaa pelkäätte, mutta miekan annan tulla päällenne, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'Vien teidät pois sen keskeltä ja annan teidät muukalaisten käsiin ja toteutan teidän keskellänne tuomiot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Te kaadutte miekkaan. Israelin rajalla teidät tuomitsen. Tulette tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Ei tämä tule teille padaksi ettekä te siihen lihaksi: Israelin rajalla tuomitsen teidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'Te tulette tietämään, että minä olen Herra – te, jotka ette ole vaeltaneet käskyjeni mukaan ettekä ole tehneet oikeuksieni mukaan, vaan olette tehneet niiden pakanoiden oikeuksien mukaan, jotka ovat teidän ympärillänne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Kun profetoin, niin Pelatja, Benajan poika, kuoli. Lankesin kasvoilleni, huusin kovalla äänellä ja sanoin: \"Voi Herra, Herra! Aivanko sinä teet lopun Israelin jäännöksestä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Minulle tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, '\"Ihmislapsi, sinun veljesi, sinun veljesi, sukulaisesi ja koko Israelin heimo, kaikki, joille Jerusalemin asukkaat sanovat: \'Olkaa vain kaukana Herrasta, meille tämä maa on annettu perinnöksi!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Sano sen tähden: Näin sanoo Herra, Herra: Koska olen vienyt heidät kauas pakanoiden sekaan ja hajottanut heidät muihin maihin, ja olen ollut heille pyhäkkönä vähän aikaa niissä maissa, joihin he ovat joutuneet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'sano sen tähden: Näin sanoo Herra, Herra: Kokoan teidät kansakuntien seasta ja kerään teidät maista, joihin teidät on hajotettu, ja annan teille Israelin maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'He tulevat sinne ja poistavat siitä kaikki sen iljetykset ja kaikki sen kauhistukset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Annan heille yhden sydämen, ja uuden hengen annan teidän sisimpäänne, ja poistan kivisydämen heidän ruumiistaan ja annan heille lihasydämen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'niin että he vaeltavat säädöksieni mukaan ja noudattavat oikeuksiani ja pitävät ne. He ovat minun kansani, ja minä olen heidän Jumalansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Mutta joiden sydän vaeltaa heidän iljetystensä ja kauhistustensa mieltä myöten, niiden vaelluksen annan tulla heidän päänsä päälle, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Kerubit nostivat siipensä ja pyörät samalla kuin ne, ja Israelin Jumalan kirkkaus oli heidän yläpuolellaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'ja Herran kirkkaus kohosi ylös, pois kaupungin keskeltä, ja asettui vuorelle, joka on kaupungista itään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Mutta Henki nosti ja vei minut Kaldeaan karkotettujen luo näyssä Jumalan Hengen voimalla. Näky, jonka olin nähnyt, katosi minulta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Puhuin karkotetuille kaikki Herran sanat, jotka hän oli minulle näyttänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Minulle tuli tämä Herran sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, '\"Ihmislapsi, sinä asut kapinallisen suvun keskellä, niiden, joilla on silmät nähdä, mutta eivät näe, ja korvat kuulla, mutta eivät kuule, sillä he ovat kapinallinen suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Sinä, ihmislapsi, tee itsellesi varusteet mennäksesi karkotukseen, mutta mene päiväaikaan heidän silmiensä edessä karkotukseen. Sinun on mentävä karkotukseen omalta paikkakunnaltasi toiselle paikkakunnalle heidän silmiensä edessä. Ehkäpä he näkevät sen, sillä he ovat kapinallinen suku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Vie ulos varusteesi, niin kuin karkotetut varusteensa, päiväaikaan heidän silmiensä edessä. Mutta lähde sinä itse illalla heidän silmiensä edessä, niin kuin karkotetut lähtevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Murtaudu muurin läpi heidän silmiensä edessä ja vie varusteesi siitä ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Nosta ne hartioillesi heidän silmiensä edessä ja vie ulos pilkkopimeässä. Peitä kasvosi, niin ettet näe maata. Sillä ennusmerkiksi olen pannut sinut Israelin heimolle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'Tein, kuten minua oli käsketty ja vein ulos päiväaikaan varusteeni, niin kuin karkotetut varusteensa, mutta illalla murtauduin käsin muurin läpi. Pilkkopimeässä ne vein ulos ja nostin ne hartioilleni heidän silmiensä edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Mutta aamulla minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, '\"Ihmislapsi, eikö Israelin heimo, kapinallinen suku, ole sinulle sanonut: \'Mitä sinä teet?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Sano heille: Näin sanoo Herra, Herra: Ruhtinasta, joka on Jerusalemissa, koskee tämä profeettasana ja koko Israelin heimoa, mikä on heidän keskuudessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Sano: Minä olen teille ennusmerkki. Kuten tein, niin heille tehdään. Karkotukseen, vankeuteen he menevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'Ruhtinas, joka on heidän keskellään, nostaa kantamuksensa hartioilleen ja lähtee ulos pilkkopimeässä. Muurista he murtautuvat läpi viedäkseen siitä ulos vietävänsä. Kasvonsa hän peittää, koska hän ei ole silmillään näkevä maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Levitän verkkoni hänen ylitseen, ja hän tarttuu pyydykseeni. Vien hänet Baabeliin, kaldealaisten maahan, mutta sitä hän ei saa nähdä, ja sinne hän kuolee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Kaikki, keitä hänellä on ympärillään apunaan, ja kaikki hänen sotajoukkonsa hajotan kaikkiin tuuliin, ja minä ajan niitä takaa paljastetulla miekalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'He tulevat tietämään, että minä olen Herra, kun hajotan heidät pakanoiden sekaan ja sirotan heidät heidän maihinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Mutta minä jätän heitä jonkin määrän miekasta, nälästä ja rutosta jäljelle kertomaan pakanoiden seassa, siellä, minne he tulevat, kaikista kauhistuksistaan. He tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Sitten minulle tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, '\"Ihmislapsi, syö leipäsi vavisten ja juo vetesi täristen ja huolestuneena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'Sano maan kansalle: Näin sanoo Herra, Herra Jerusalemin asukkaista Israelin maassa: He tulevat syömään leipänsä huolestuneina ja juomaan vetensä kauhun vallassa, ja sen maa tulee autioksi kaikesta, mitä siinä on, kaikkien siinä asuvien väkivallan tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Asutut kaupungit tulevat raunioiksi, ja maa tulee autioksi, ja te tulette tietämään, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Minulle tuli tämä Herran sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, '\"Ihmislapsi, miksi teillä on tämä sananparsi Israelin maasta, kun sanotte: \'Aika venyy pitkälle, ja tyhjiin raukeavat kaikki näyt?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Sen tähden sano heille: Näin sanoo Herra, Herra: Minä teen lopun tästä sananparresta, niin ettei sitä enää lausuta Israelissa, vaan sano heille: Lähellä on aika ja kaikkien näkyjen täyttymys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Sillä ei ole oleva enää petollista näkyä eikä mielistelevää ennustelua Israelin heimon keskuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Sillä minä, Herra, minä puhun; ja minkä sanan puhun, se tapahtuu eikä enää viivy. Sillä teidän päivinänne, kapinallinen suku, sanan puhun ja sen myös täytän, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Minulle tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, '\"Ihmislapsi, katso, Israelin heimo sanoo: \'Niihin näkyihin, joita tämä näkee, on paljon päiviä, ja hän profetoi kaukaisista ajoista.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Sen tähden sano heille: Näin sanoo Herra, Herra: Ei viivy enää yksikään minun sanani: Minkä sanan minä puhun, se tapahtuu, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'Minulle tuli tämä Herran sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, '\"Ihmislapsi, profetoi Israelin ennustavista profeetoista ja sano noille, jotka ovat profeettoja oman sydämensä johtamina: Kuulkaa Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Näin sanoo Herra, Herra: voi profeettatyperyksiä, jotka seuraavat omaa henkeään ja sitä, mitä eivät ole nähneet!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Kuin ketut raunioissa ovat profeettasi, Israel.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Te ette ole nousseet muurin aukkoihin ettekä korjanneet muuria Israelin heimon ympäriltä, että se kestäisi sodassa, Herran päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Se, mitä he ovat nähneet, on petosta, ja heidän ennustelunsa on valhetta, kun he sanovat: \'Näin sanoo Herra \', vaikka Herra ei ole heitä lähettänyt, niin he odottavat, että hän toteuttaisi heidän sanansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Ettekö ole petollisia näkyjä nähneet ja valheellisia ennusteluja puhuneet, kun olette sanoneet: \'Näin sanoo Herra \', vaikka minä en ole puhunut?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Sen tähden, näin sanoo Herra, Herra: Koska olette puhuneet petosta ja nähneet valheellisia näkyjä, niin sen tähden, katso, minä olen teitä vastaan, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Käteni on profeettoja vastaan, jotka näkevät petosnäkyjä ja ennustavat valhetta. Heidän ei pidä olla kansani kokouksessa eikä heitä pidä kirjoittaa Israelin heimon kirjaan, eivätkä he tule Israelin maahan. Te tulette tietämään, että minä olen Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Koska he, koska he vievät kansani harhaan, sanoen: \'rauha!\', vaikka ei rauhaa ole, ja katso, koska he, kun kansa rakentaa seinän, valkaisevat sen kalkilla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'niin sano noille kalkilla valkaisijoille, että se kaatuu. Tulee kaatosade, tulee suuria rakeita, jotka sen kaatavat, ja myrskynpuuska hajottaa sen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'ja katso, seinä kaatuu! Eikö silloin teiltä kysytä: \'Missä on valkaisu, jolla sen valkaisitte?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Sen tähden, näin sanoo Herra, Herra: Annan kiivaudessani puhjeta myrskynpuuskan, kaatosade tulee vihastani ja raekivet kiivaudestani tekemään siitä lopun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Hajotan seinän, jonka olitte kalkilla valkaisseet, ja syöksen sen maahan, niin että sen perustus paljastuu. Se kaatuu, ja saatte siinä lopun. Mutta tulette tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Minä panen kiivauteni täytäntöön seinässä ja niissä, jotka sen kalkilla valkaisivat, ja sanon teille: Ei ole enää seinää eikä sen valkaisijoita,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'Israelin profeettoja, jotka ennustivat Jerusalemista ja näkivät sille rauhan näkyjä, vaikka ei rauhaa ollut, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Mutta sinä, ihmislapsi, käännä kasvosi kansasi tyttäriä vastaan, jotka joutuvat hurmoksiin oman sydämensä johtamina, ja profetoi heitä vastaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'ja sano: Näin sanoo Herra, Herra: Voi niitä naisia, jotka sitovat taikasiteitä kaikkiin ranteisiin ja tekevät huntuja kaikenkorkuisiin päihin pyydystääkseen sieluja! Toisia sieluja te pyydystätte kansaltani pois, toisten sielujen annatte elää omaksi eduksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Häpäisette minut kansani edessä kourallisista ohria ja leipäpalasista, kun kuoletatte sieluja, joiden ei olisi kuoltava ja annatte elää sielujen, jotka eivät saisi elää ja kun valehtelette kansalleni, joka kuuntelee valhetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Sen tähden, näin sanoo Herra, Herra: Käyn käsiksi teidän taikasiteisiinne, joilla olette pyydystäneet sieluja kuin lintuja, ja revin ne käsivarsistanne ja lasken sielut lentoon – sielut, jotka te olette pyydystäneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Revin huntunne ja pelastan kansani käsistänne, niin etteivät he enää joudu kättenne saaliiksi; ja te tulette tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Koska olette valheella murehduttaneet vanhurskaan sydämen, vaikka en tahtonut häntä murehduttaa, ja olette vahvistaneet jumalattoman käsiä, ettei hän kääntyisi pahalta tieltään ja eläisi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'sen tähden ette enää tule näkemään petosnäkyjä ettekä ennustelemaan ennustelujanne, vaan pelastan kansani käsistänne, ja tulette tietämään, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Luokseni tuli miehiä Israelin vanhinten joukosta, ja he istuutuivat eteeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, '\"Ihmislapsi, nämä miehet ovat nostaneet epäjumalansa sydämeensä ja asettaneet kasvojensa eteen sen, mikä heille oli kompastukseksi syntiin. Antaisinko tosiaan heidän kysyä neuvoa itseltäni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Sen tähden puhuttele heitä ja sano heille: Näin sanoo Herra, Herra: Kuka tahansa Israelin heimosta nostaa epäjumalansa sydämeensä ja asettaa kasvojensa eteen sen, mikä hänelle oli kompastukseksi syntiin, ja menee profeetan luo, hänelle minä, Herra, kyllä annan vastauksen – hänelle ja hänen monille epäjumalilleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'ja tartun Israelin heimoa sydämeen, koska he ovat kääntyneet minusta pois kaikki seuraamalla epäjumaliaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Sen tähden sano Israelin heimolle: Näin sanoo Herra, Herra: Kääntykää, ja kääntykää pois epäjumalistanne ja kääntäkää kasvonne pois kaikista kauhistuksistanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Sillä kuka ikinä Israelin heimosta tai muukalainen, joka asuu Israelissa, luopuu minusta ja nostaa epäjumalansa sydämeensä ja asettaa kasvojensa eteen sen, mikä hänelle oli kompastukseksi syntiin, ja menee profeetan luo kysymään itselleen neuvoa minulta, hänelle minä, Herra, itse annan vastauksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'Käännän kasvoni sitä miestä vastaan, teen hänet merkiksi ja sananparreksi ja hävitän hänet kansani keskeltä. Tulette tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Mutta jos profeetta antaa viekoitella itsensä ja sanoo sanan, niin minä, Herra, olen sen profeetan viekoitellut. Ojennan käteni häntä vastaan ja hävitän hänet kansastani Israelista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'He tulevat kantamaan syntinsä – niin kuin kysyjän synti, on profeetankin synti –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'etteivät he, Israelin heimo, enää eksyisi minusta pois eivätkä enää saastuttaisi itseään kaikilla rikkomisillaan, vaan olisivat kansani ja minä olisin heidän Jumalansa; sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Minulle tuli tämä Herran sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, '\"Ihmislapsi! Jos maa tekisi syntiä minua vastaan olemalla uskoton ja ojentaisin sitä vastaan käteni ja murtaisin siltä leivän tuen ja lähettäisin siihen nälän ja hävittäisin siitä ihmiset ja eläimet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'ja sen keskellä olisivat nämä kolme miestä: Nooa, Daniel ja Job, he vanhurskaudellaan pelastaisivat oman henkensä, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Jos antaisin pahojen petoeläinten käydä halki maan ja ne riistäisivät siltä lapset ja se tulisi autioksi, niin ettei siellä olisi kulkijaa petoeläinten tähden,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'niin nämä kolme miestä, jos olisivat sen keskellä, eivät voisi – niin totta kuin minä elän, sanoo Herra, Herra – pelastaa poikiaan eikä tyttäriään. Vain he itse pelastuisivat, mutta maa tulisi autioksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Tai jos antaisin miekan tulla tämän maan yli ja sanoisin: \'Miekka, käy halki maan!\' ja hävittäisin siitä ihmiset ja eläimet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'ja sen keskellä olisivat nämä kolme miestä, eivät he voisi – niin totta kuin minä elän, sanoo Herra, Herra – pelastaa poikiaan eikä tyttäriään, vaan vain he itse pelastuisivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Tai jos lähettäisin ruton tähän maahan ja vuodattaisin vihani sen yli verenä, niin että hävittäisin siitä ihmiset ja eläimet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'ja Nooa, Daniel ja Job olisivat sen keskellä, eivät he voisi – niin totta kuin minä elän, sanoo Herra, Herra – pelastaa poikaansa eikä tytärtään. Vain he vanhurskaudellaan pelastaisivat henkensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Sillä näin sanoo Herra, Herra: Mitä sitten, kun lähetän Jerusalemin päälle neljä kovaa tuomiotani: miekan, nälän, pahat petoeläimet ja ruton hävittämään siitä ihmiset ja eläimet!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'Mutta katso, sinne on jäävä jäljelle pelastuneita, poikia ja tyttäriä, jotka viedään pois. Katso, he tulevat luoksenne, ja te näette heidän vaelluksensa ja tekonsa ja tulette lohdutetuiksi siitä onnettomuudesta, jonka olen tuottanut Jerusalemille, kaikesta, minkä olen sille tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'He lohduttavat teitä, kun näette heidän vaelluksensa ja tekonsa. Te tulette tietämään, etten syyttä suotta ole tehnyt sitä kaikkea, minkä olen sille tehnyt, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, '\"Ihmislapsi, miksi viinipuu on parempi kuin kaikki muut puut, tuo köynnös, joka on metsän puiden seassa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Otetaanko siitä puuta mihinkään tarkoitukseen? Tehdäänkö siitä tappiakaan, johon ripustetaan kaikkea tavaraa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Katso, se annetaan tulen kulutettavaksi. Sen molemmat päät on tuli kuluttanut, ja sen keskiosa hiiltynyt. Kelpaako se tarve-esineeksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Katso, silloinkaan, kun se oli ehjä, siitä ei voinut valmistaa tarve-esinettä, saati sitten, kun tuli sen kulutti ja se hiiltyi – silloinko siitä tehtäisiin tarve-esine?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Sen tähden, näin sanoo Herra, Herra: Niin kuin metsän puiden seassa käy viinipuulle, jonka olen antanut tulen kulutettavaksi, niin annan käydä myös Jerusalemin asukkaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Käännän kasvoni heitä vastaan. Tulesta he ovat päässeet, mutta tuli heidät kuluttaa. Niin tulette tietämään, että minä olen Herra, kun käännän kasvoni heitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Teen maan autioksi, koska he ovat olleet uskottomat; sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, '\"Ihmislapsi, ilmoita Jerusalemille sen kauhistukset');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'ja sano: Näin sanoo Jerusalemille Herra, Herra: Sinun alkuperäsi ja syntysi on kanaanilaisten maasta. Isäsi oli amorilainen ja äitisi heettiläinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Näin oli syntymäsi: sinä päivänä, jona synnyit, sinulta ei leikattu napanuoraa, sinua ei pesty vedellä, että olisit puhdistunut, sinua ei hierottu suolalla eikä sinua kääritty kapaloihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Kukaan ei sinua säälinyt, niin että olisi tehnyt sinulle mitään tällaista ja armahtanut sinua, vaan sinut pantiin heitteille kedolle. Niin halpana pidettiin sinun henkesi sinä päivänä, jona synnyit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Mutta kuljin ohitsesi ja näin sinut, kun sätkyttelit verissäsi. Sanoin sinulle, kun olit siinä verissäsi: \'Sinun pitää elää\' – niin sanoin sinulle, kun olit siinä verissäsi: \'Sinun pitää elää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'teen sinut kymmeniksi tuhansiksi kuin pellon sadon.\' Vartuit, tulit isoksi ja ehdit kauneimpaan kukoistukseesi, rintasi paisuivat, ja hiuksesi kasvoivat; mutta vielä sinä olit alaston ja paljas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Kuljin ohitsesi ja näin sinut, ja katso, sinun aikasi oli lemmen aika. Levitin liepeeni ylitsesi ja peitin häpysi. Vannoin sinulle ja menin liittoon kanssasi, sanoo Herra, Herra. Tulit omakseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Pesin sinut vedellä, huuhtelin sinut verestäsi ja voitelin sinut öljyllä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Puetin sinut kirjailtuihin vaatteisiin, panin jalkaasi tahašin nahasta tehdyt sandaalit, sidoin päähäsi hienopellavaisen siteen ja hunnutin sinut silkillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'Koristin sinut koruilla, panin rannerenkaat käsiisi ja ketjut kaulaasi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'panin nenärenkaan nenääsi, korvarenkaat korviisi ja päähäsi kauniin kruunun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Niin sinut koristeltiin kullalla ja hopealla, sinun pukusi oli hienoa pellavaa, silkkiä ja kirjailtua vaatetta, ja söit ydinjauhoja, hunajaa ja öljyä. Sinusta tuli erittäin kaunis, ja sinä kelpasit kuninkaalliseen arvoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Maineesi kulki pakanakansoihin kauneutesi tähden, sillä se oli täydellinen niiden kaunistusten takia, jotka puin yllesi, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Mutta luotit kauneuteesi ja harjoitit haureutta maineesi nojalla ja vuodatit haureuttasi jokaiselle ohikulkijalle: \'Saakoon tuokin!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Otit vaatteistasi kangasta ja teit itsellesi kirjavia uhrikukkuloita ja harjoitit haureutta niiden päällä. Sellaista ei ole tapahtunut eikä ole tapahtuva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Otit korujasi, kultaani ja hopeaani, joita olin sinulle antanut, ja teit itsellesi miehenkuvia ja harjoitit haureutta niiden kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Otit kirjailtuja vaatteitasi ja verhosit ne niillä ja öljyni ja suitsukkeeni panit niiden eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Ruokani, jota sinulle annoin –syötinhän sinua ydinjauhoilla, öljyllä ja hunajalla – sinä panit niiden eteen suloiseksi tuoksuksi. Näin tapahtui, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Otit poikasi ja tyttäresi, jotka olit minulle synnyttänyt, ja teurastit heidät niiden syödä. Oliko haureudessasi sinulle liian vähän,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'kun vielä teurastit poikani ja annoit heidät poltettaviksi niille uhrina?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Kaikkien kauhistustesi ja haureutesi parissa et muistanut nuoruutesi päiviä, jolloin olit alaston ja paljas ja sätkyttelit verissäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Kaiken muun pahuutesi lisäksi – voi, voi sinua! sanoo Herra, Herra –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'rakensit itsellesi korokkeita ja teit itsellesi kumpuja kaikille toreille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'Kaikkiin kadunkulmiin rakensit kumpujasi ja häpäisit kauneutesi, levitit jalkasi jokaiselle ohikulkijalle ja yhä lisäsit haureuttasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Harjoitit haureutta naapuriesi, Egyptin isoelimisten poikien, kanssa ja yhä lisäsit haureuttasi ja niin vihoitit minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Katso, ojensin käteni sinua vastaan ja vähensin sinun määräosasi ja jätin sinut vihollistesi, filistealaisten tyttärien, raivon valtaan, jotka häpesivät sinun kauheaa vaellustasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Harjoitit haureutta Assurin poikien kanssa, koska et voinut saada kylliksesi. Vaikka harjoitit haureutta heidän kanssaan, et sittenkään saanut tarpeeksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Lisäsit yhä haureuttasi Kanaanin maassa, Kaldeaan asti, mutta et siitäkään saanut tarpeeksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Kuinka himosta voipuva olikaan sydämesi, sanoo Herra, Herra, kun teit tämän kaiken, niin kuin tekee portoista pahin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'kun rakensit korokkeesi kaikkiin kadunkulmiin ja teit kumpusi kaikille toreille! Mutta siinä et ollut porton kaltainen, että halveksit portonpalkkaa –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'avionrikkojavaimo, joka miehensä sijaan ottaa vieraita!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Kaikille portoille annetaan lahja, mutta annoit portonlahjojasi kaikille rakastajillesi ja haureudessasi lahjoit heitä tulemaan luoksesi joka taholta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Sinun laitasi oli haureudessasi päinvastoin kuin muiden naisten. Perässäsi ei juostu haureuteen, vaan sinä maksoit portonpalkkaa, mutta sinulle portonpalkkaa ei maksettu. Näin se oli päinvastoin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Sen tähden, sinä portto, kuule Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Näin sanoo Herra, Herra: Koska olet vuodattanut häpysi ja riisunut sen paljaaksi haureudessasi kaikille rakastajillesi ja kaikille kauhistaville epäjumalillesi, sekä lastesi veren tähden, jonka olet niille antanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'sen tähden, katso, kokoan kaikki rakastajasi, jotka olivat sinulle mieleen, kaikki, joita rakastit, ja kaikki, joihin kyllästyit, ne kokoan sinua vastaan joka taholta ja paljastan heille alastomuutesi, niin että he näkevät koko alastomuutesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'Tuomitsen sinut sen mukaan, mitä on säädetty avionrikkoja- ja verenvuodattajanaisista, ja annan vihassa ja kiivaudessa veresi vuotaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Annan sinut heidän käsiinsä, ja he hajottavat korokkeesi, kukistavat kumpusi, raastavat sinulta vaatteesi, ottavat korusi ja jättävät sinut alastomaksi ja paljaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'He nostattavat kansanjoukon sinua vastaan, ja ne kivittävät sinut ja hakkaavat sinut maahan miekoillaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'polttavat tulella talosi ja panevat sinussa toimeen tuomiot monien naisten silmien edessä. Teen lopun porttona olostasi, etkä enää sitten maksa portonpalkkoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Tyydytän vihani sinussa, niin että kiivauteni väistyy sinusta, ja tyynnyn enkä enää ole vihastunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Koska et ole muistanut nuoruutesi päiviä, vaan vihoitit minut kaikilla näillä – niin katso, minäkin annan vaelluksesi tulla oman pääsi päälle, sanoo Herra, Herra. Etkö sinä ole tehnyt näitä iljetyksiä kaikkien kauhistustesi lisäksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Katso, jokainen, joka lausuu sananparsia, on tekevä sinusta sananparren: \'Tytär tulee äitiinsä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Sinä olet äitisi tytär, hänen, joka hyljeksi miestään ja lapsiaan, ja olet sisartesi sisar, heidän, jotka hyljeksivät miehiään ja lapsiaan. Äitinne oli heettiläinen ja isänne amorilainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Isosiskosi oli Samaria tyttärineen, joka asui vasemmalla puolellasi, ja pikkusiskosi, joka asui oikealla puolellasi, oli Sodoma tyttärineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Mutta et vaeltanut heidän teitään etkä tehnyt kauhistuksia samalla tavoin kuin he. Vähän aikaa vain, niin jo teit kaikilla teilläsi kelvottomammin kuin he.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Niin totta kuin minä elän, sanoo Herra, Herra: sisaresi Sodoma tyttärineen ei totisesti tehnyt sitä, mitä sinä tyttärinesi olet tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Katso, tämä oli sisaresi Sodoman synti: ylpeys, leivän yltäkylläisyys ja huoleton lepo hänellä ja hänen tyttärillään. Mutta kurjaa ja köyhää hän ei kädestä tarttunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'He ylpeilivät ja tekivät kauhistuksia edessäni, ja kun sen näin, toimitin heidät pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Samaria ei tehnyt puoltakaan syntiesi määrästä, mutta sinä olet tehnyt kauhistuksia paljon enemmän kuin he, niin että olet kaikilla kauhistuksillasi, joita olet tehnyt, saanut sisaresi näyttämään vanhurskailta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Niinpä kanna myös häpeäsi, kun olet hankkinut tuollaisen hyvityksen sisarillesi. Syntiesi takia, kun olet menetellyt vielä kauhistavammin kuin he, he ovat vanhurskaampia kuin sinä. Häpeä sinäkin ja kanna häpeäsi, kun olet saanut sisaresi näyttämään vanhurskailta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Mutta käännän heidän kohtalonsa: Sodoman ja hänen tyttäriensä kohtalon sekä Samarian ja hänen tyttäriensä kohtalon, ja käännän sinun kohtalosi, sinun, joka olet heidän keskellään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'että kantaisit häpeäsi ja olisit häpeissäsi kaikesta, mitä teit, kun lohdutit heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Sisaresi, Sodoma tyttärineen, palaa entiselleen, ja Samaria tyttärineen palaa entiselleen. Myös sinä palaat tyttärinesi entisellesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Eikö sisaresi Sodoma ollut puheenaiheena suussasi ylpeytesi aikana,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'ennen kuin oma pahuutesi paljastui, silloin kun jouduit Aramin tyttärien ja kaikkien heidän ympärillään asuvien, filistealaisten tyttärien, häväistäväksi, jotka joka taholta pilkkasivat sinua?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Sinä saat kantaa iljetyksesi ja kauhistuksesi, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Sillä näin sanoo Herra, Herra: Olen tehnyt sinulle sen mukaan, kuin sinä olet tehnyt, kun olet pitänyt valan halpana ja rikkonut liiton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Mutta minä muistan liittoni, jonka tein kanssasi nuoruutesi päivinä, ja pystytän kanssasi iankaikkisen liiton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Muistat vaelluksesi ja häpeät, kun otat vastaan sisaresi, ne, jotka ovat sinua isommat, sekä ne, jotka ovat sinua pienemmät, ja annan heidät sinulle tyttäriksi, mutta en sinun liittosi nojalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Minä pystytän liittoni kanssasi, ja tulet tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'Muistat ja häpeät etkä voi häpeäsi tähden enää avata suutasi, kun annan sinulle anteeksi kaiken, mitä tehnyt olet, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Minulle tuli tämä Herran sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, '\"Ihmislapsi, esitä arvoitus ja lausu sananparsi Israelin heimolle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'ja sano: Näin sanoo Herra, Herra: Suuri kotka, suurisiipinen, pitkäsulkainen, täysihöyheninen, kirjava, tuli Libanonille ja otti latvuksen setripuusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Hän taittoi siitä latvalehvän ja vei sen Kanaanin maahan, asetti sen kauppiaiden kaupunkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Hän otti siitä maasta taimen ja pani sen kylvöpeltoon. Hän otti sen ja istutti sen kuin pajun runsaan veden ääreen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Se versoi, ja siitä tuli rehevä viinipuu, matalakasvuinen. Sen oksien tuli kääntyä kotkaan päin ja sen juurten olla hänen allaan. Siitä tuli viinipuu. Se teki haaroja ja työnsi oksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Mutta oli toinen suuri kotka, suurisiipinen, runsashöyheninen; ja katso, tämä viinipuu ojensi juurensa sitä kotkaa kohti ja työnsi oksansa siihen päin sen kasteltaviksi siitä penkereestä, johon se oli istutettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Se oli istutettu hyvään peltoon runsaan veden ääreen, että se tekisi lehviä, kantaisi hedelmää ja tulisi ihanaksi viinipuuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Sano: Näin sanoo Herra, Herra: Menestyyköhän se? Eiköhän kotka kisko ylös sen juuria ja raasta sen hedelmiä, niin että kaikki siitä versoneet lehdet kuivuvat ja puu kuivuu? Eikä tarvita suurta voimaa eikä paljoa väkeä sen nostamiseksi juuriltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Katso, se on istutettu – menestyyköhän se? Eikö se kuivu, kun siihen käy itätuuli, ja kuivu penkereessä, jossa se versoi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Sitten minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, '\"Sano kapinoivalle suvulle: Ettekö tiedä, mitä tämä tarkoittaa? Sano: Katso, Baabelin kuningas tuli Jerusalemiin, otti sen kuninkaan ja ruhtinaat ja vei heidät luokseen Baabeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Hän otti yhden kuninkaallisesta suvusta, teki hänen kanssaan liiton ja otti häneltä valan, mutta maan mahtavat hän vei mukanaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'että valtakunta tulisi vähäpätöiseksi eikä kohoaisi, että se pitäisi liittonsa ja liitto pysyisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Mutta hän kapinoi häntä vastaan ja laittoi lähettiläänsä Egyptiin, että hänelle annettaisiin hevosia ja paljon väkeä. Menestyykö se, pelastuuko se, joka tekee tällaista? Pelastuuko se, joka rikkoo liiton?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Niin totta kuin minä elän, sanoo Herra, Herra: sen kuninkaan asuinpaikalla, joka hänet kuninkaaksi teki, jonka valan hän on halpana pitänyt ja jonka liiton hän on rikkonut, sen luona, keskellä Baabelia, hänen on totisesti kuoltava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Mutta farao suurella sotajoukollaan ja paljolla väellään ei tee mitään hänen hyväkseen sodassa, kun luodaan valli ja rakennetaan saartovarusteet monien sielujen tuhoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Hän piti halpana valan ja rikkoi liiton. Katso, vaikka hän oli kättä lyönyt, hän teki kaiken tämän – hän ei pelastu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Sen tähden, näin sanoo Herra, Herra: Niin totta kuin minä elän, niin valani, jonka hän piti halpana, ja liittoni, jonka hän rikkoi, annan tulla hänen päänsä päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Levitän verkkoni hänen ylitseen, ja hän takertuu pyydykseeni. Vien hänet Baabeliin ja käyn siellä oikeutta hänen kanssaan hänen uskottomuudestaan, jota hän on osoittanut minua kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Kaikki hänen pakolaisensa kaikista hänen sotajoukoistaan kaatuvat miekkaan, ja jäljellejääneet hajotetaan kaikkiin tuuliin. Niin te tulette tietämään, että minä, Herra, olen puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Näin sanoo Herra, Herra: Mutta minä otan yhden latvuksen siitä korkeasta setripuusta ja istutan sen. Hennon latvalehvän minä siitä taitan ja istutan korkealle ja jyrkälle vuorelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Israelin vuoren korkeuteen sen istutan. Niin se kantaa lehviä ja tekee hedelmää, ja siitä tulee mahtava setri. Sen alla asuvat kaikki linnut, ja kaikki siivekkäät asuvat sen oksien varjossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Kaikki metsän puut tulevat tietämään, että minä olen Herra, joka teen korkean puun matalaksi ja matalan puun korkeaksi, tuoreen puun kuivaksi ja kuivan puun kukoistavaksi. Minä, Herra, Herra, olen puhunut ja sen teen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Minulle tuli tämä Herran sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, '\"Mikä teillä on, kun te lausutte tätä sananpartta Israelin maasta: \'Isät söivät raakoja rypäleitä, lasten hampaat heltyivät\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Niin totta kuin minä elän, sanoo Herra, Herra, teidän ei tule enää lausua tätä sananpartta Israelissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Katso, kaikki sielut ovat minun: niin kuin isän sielu, niin pojankin sielu – ne ovat minun. Sen sielu, joka syntiä tekee – sen on kuoltava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Jos mies on vanhurskas ja tekee oikeuden ja vanhurskauden:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'ei syö uhrivuorilla, ei luo silmiään Israelin heimon epäjumaliin, ei saastuta lähimmäisensä vaimoa, ei lähesty vaimoaan, joka on kuukautistilassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'ei sorra toista, vaan antaa takaisin velkapantin, ei riistä eikä raasta, vaan antaa leipäänsä nälkäiselle, verhoaa vaatteella alastonta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'ei anna rahaansa korolle, ei ota voittoa, vaan pidättää kätensä vääryydestä, tekee oikean tuomion miesten välillä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'vaeltaa käskyjeni mukaan ja noudattaa oikeuksiani, niin että tekee sitä, mikä on oikein – hän on vanhurskas, hän totisesti on elävä, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Mutta jos hänelle on syntynyt poika, väkivaltainen, verenvuodattaja, joka tekee yhtäkin näistä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'mitä hän itse ei ole tehnyt: syö uhrivuorilla, saastuttaa lähimmäisensä vaimon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'sortaa kurjaa ja köyhää, riistää ja raastaa, ei anna takaisin panttia, luo silmänsä epäjumaliin, tekee kauhistuksia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'antaa rahansa korolle ja ottaa voittoa – saisiko tämä elää? Hän ei tule elämään. Kaikkia näitä kauhistuksia hän on tehnyt, hänet on kuolemalla rangaistava. Hän on verivelan alainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Mutta katso, jos tälle on syntynyt poika ja hän näkee kaikki isänsä synnit, jotka tämä on tehnyt – näkee ne eikä tee sellaisia:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'ei syö uhrivuorilla, ei luo silmiään Israelin heimon epäjumaliin, ei saastuta lähimmäisensä vaimoa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'ei sorra toista, ei ota panttia, ei riistä eikä raasta, vaan antaa leipäänsä nälkäiselle, verhoaa vaatteella alastonta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'pidättää kätensä koskemasta kurjaan, ei ota korkoa eikä voittoa, vaan tekee minun oikeuksieni mukaan, vaeltaa käskyjeni mukaan – hänen ei ole kuoltava isänsä syntivelan tähden, hän totisesti on elävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Hänen isänsä taas kun teki väkivallan töitä, riisti ja raastoi veljeltään ja teki kansansa keskuudessa sitä, mikä ei ole hyvää, niin katso, hänen oli kuoltava syntivelkansa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Mutta vielä te kysytte: \'Minkä tähden poika ei kanna isän syntivelkaa?\' Kun poika on tehnyt oikeuden ja vanhurskauden, noudattanut kaikkia käskyjäni ja tehnyt niiden mukaan, hän totisesti on elävä. Sen sielun, joka syntiä tekee – sen on kuoltava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Poika ei kanna isän syntivelkaa, eikä isä kanna pojan syntivelkaa. Vanhurskaan ylle on tuleva hänen vanhurskautensa, ja jumalattoman ylle on tuleva hänen jumalattomuutensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Jos jumalaton kääntyy pois kaikesta synnistään, mitä hän on tehnyt, ja noudattaa kaikkia käskyjäni ja tekee oikeuden ja vanhurskauden, hän totisesti tulee elämään eikä hänen ole kuoltava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Yhtään hänen synneistään, jotka hän on tehnyt, ei muisteta. Vanhurskautensa tähden, jota hän on noudattanut, hän on elävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Olisiko minulle mieleen jumalattoman kuolema, sanoo Herra, Herra, eikö se, että hän kääntyy pois teiltään ja elää?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Mutta jos vanhurskas kääntyy pois vanhurskaudestaan ja tekee vääryyttä, tekee kaikkien niiden kauhistusten kaltaisia, joita jumalaton tekee – hänkö on elävä? Ei yhtään hänen vanhurskasta tekoaan, jonka hän on tehnyt, muisteta. Uskottomuutensa tähden, johon hän on langennut, ja syntinsä tähden, jota hän on tehnyt, hänen on kuoltava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Vielä te sanotte: \' Herran tie ei ole oikea.\' Kuulkaa siis, te Israelin heimo! Minunko tieni ei olisi oikea? Eikö niin: teidän omat tienne eivät ole oikeat!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Jos vanhurskas kääntyy pois vanhurskaudestaan ja tekee vääryyttä, sen tähden hänen on kuoltava. Vääryytensä tähden, jota hän on tehnyt, hänen on kuoltava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Jos jumalaton kääntyy pois jumalattomuudestaan, jota hän on harjoittanut, ja tekee oikeuden ja vanhurskauden, hän säilyttää sielunsa elossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Koska hän näki ja kääntyi pois kaikista synneistään, joita oli tehnyt, hän totisesti tulee elämään. Hänen ei ole kuoltava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Mutta Israelin heimo sanoo: \' Herran tie ei ole oikea.\' Minunko tieni eivät olisi oikeat, te Israelin heimo? Eikö niin: teidän omat tienne eivät ole oikeat!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Niinpä tuomitsen teidät, te Israelin heimo, itse kunkin hänen teittensä mukaan, sanoo Herra, Herra. Kääntykää, palatkaa pois kaikista synneistänne, ja älköön syntivelka tulko teille lankeemukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Heittäkää pois päältänne kaikki syntinne, joilla te olette rikkoneet, ja tehkää itsellenne uusi sydän ja uusi henki. Minkä tähden te kuolisitte, Israelin heimo?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Sillä ei ole minulle mieleen kuolevan kuolema, sanoo Herra, Herra. Kääntykää, niin elätte.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, '\"Mutta sinä, viritä itkuvirsi Israelin ruhtinaista');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'ja sano: Mikä naarasleijona äitisi olikaan leijonien joukossa! Se makasi nuorten leijonien keskellä ja kasvatti pentujaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'ja kasvatti isoksi yhden pennuistaan, ja siitä tuli nuori leijona. Se oppi saalistamaan ja söi ihmisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Mutta kansat kuulivat siitä: se pyydystettiin heidän kuoppaansa ja vietiin koukusta vetäen Egyptin maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Kun sen viipyessä emo näki, että hänen toivonsa oli mennyttä, se otti toisen pennuistaan, ja kasvatti sen nuoreksi leijonaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Se käyskenteli leijonien keskellä, siitä tuli nuori leijona, se oppi saalistamaan, ja se söi ihmisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Se yhtyi heidän leskiinsä ja teki autioiksi heidän kaupunkinsa, ja maa ja kaikki, mitä siinä on, kauhistui sen ärjynnän äänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Silloin kansat sen ympärillä olevilta alueilta asettivat ja virittivät sille verkkonsa, ja se pyydystettiin heidän kuoppaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'Se pantiin häkkiin vetämällä koukusta ja vietiin Baabelin kuninkaan eteen. Se vietiin vuorilinnoihin, ettei sen ääni enää kuuluisi Israelin vuorille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Äitisi oli sinulle kuin mehevä veden ääreen istutettu viinipuu. Se tuli runsaasta vedestä hedelmälliseksi ja siinä oli paljon oksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'Siihen tuli vahvoja oksia hallitsijoiden valtikoiksi, ja sen runko kohosi korkealle tiheän oksaston keskellä ja näkyi kauas korkeana ja runsasoksaisena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Mutta se temmattiin vihaisesti irti, heitettiin maahan, ja itätuuli kuivasi sen hedelmät. Ne revittiin hajalle, ja sen vahvat oksat kuivuivat, ja tuli kulutti ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Nyt se on istutettuna erämaahan, kuivaan ja janoiseen maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Sen vahvasta oksasta on lähtenyt tuli. Se on kuluttanut sen hedelmät, ja vahvaa oksaa, josta olisi hallitusvaltikaksi, siinä ei enää ole.\" Itkuvirsi tämä oli oleva, ja itkuvirsi siitä on tullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'Seitsemäntenä vuotena, viidennessä kuussa, kuukauden kymmenentenä päivänä tuli miehiä Juudan vanhinten joukosta kysymään neuvoa Herralta, ja he istuutuivat eteeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Minulle tuli tämä Herran sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, '\"Ihmislapsi, puhu Israelin vanhimmille ja sano heille: Näin sanoo Herra, Herra: Tekö tulette minulta kysymään neuvoa? Niin totta kuin minä elän, en anna teidän kysyä neuvoa itseltäni, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Etkö tuomitse heitä, etkö tuomitse, ihmislapsi? Tee heille tiettäviksi heidän isiensä kauhistukset');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'ja sano heille: Näin sanoo Herra, Herra: Sinä päivänä, jona valitsin Israelin, kättä kohottaen lupasin Jaakobin heimon jälkeläisille, tein itseni heille tunnetuksi Egyptin maassa ja kättä kohottaen lupasin heille sanoen: \'Minä olen Herra, teidän Jumalanne.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'Sinä päivänä kohotin käteni, että vien heidät pois Egyptin maasta siihen maahan, jonka olin heille katsonut ja joka vuotaa maitoa ja hunajaa. Se on kaunistus kaikkien maiden joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Sanoin heille: \'Heittäkää, itse kukin, pois silmienne iljetykset älkääkä saastuttako itseänne Egyptin epäjumalilla. Minä olen Herra, teidän Jumalanne.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Mutta he kapinoivat minua vastaan, eivät tahtoneet kuulla minua eivätkä heittäneet pois itse kukin silmiensä iljetyksiä eivätkä hylänneet Egyptin epäjumalia. Sanoin vuodattavani kiivauteni heidän päälleen ja panevani vihani täytäntöön heissä keskellä Egyptin maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Mutta tein tekoni oman nimeni tähden, jotta se ei tulisi häväistyksi pakanoiden silmissä, joiden keskellä he olivat ja joiden silmien edessä olin tehnyt itseni heille tunnetuksi viemällä heidät pois Egyptin maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Kun olin vienyt heidät pois Egyptin maasta ja tuonut heidät erämaahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'annoin heille säädökseni ja tein heille tiettäviksi oikeuteni: ihminen, joka ne pitää, on niistä elävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Myös sapattini annoin heille olemaan merkkinä minun ja heidän välillään, että he tulisivat tietämään, että minä olen Herra, joka pyhitän heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Mutta Israelin heimo kapinoi minua vastaan erämaassa. He eivät vaeltaneet käskyjeni mukaan ja halveksivat oikeuksiani, jotka ihmisen on pidettävä, että hän niistä eläisi, ja sapattini he rikkoivat kovin. Niin sanoin vuodattavani kiivauteni heidän päälleen erämaassa ja lopettavani heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Mutta tein tekoni oman nimeni tähden, ettei se tulisi häväistyksi pakanoiden silmissä, joiden silmien edessä olin vienyt heidät pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Myös kättä kohottaen vannoin heille erämaassa, etten tuo heitä siihen maahan, jonka olin antanut heille, joka vuotaa maitoa ja hunajaa – se on kaunistus kaikkien maitten joukossa –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'koska he pitivät oikeuteni halpoina, eivät vaeltaneet säädöksieni mukaan, vaan rikkoivat sapattini, sillä heidän sydämensä vaelsi heidän epäjumaliensa jäljessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Mutta säälin heitä, niin etten heitä hävittänyt enkä tehnyt heistä loppua erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Sanoin heidän lapsilleen erämaassa: Älkää vaeltako isienne säädöksien mukaan, heidän oikeuksiansa älkää noudattako älkääkä saastuttako itseänne heidän epäjumalillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Minä olen Herra, teidän Jumalanne; minun säädöksieni mukaan vaeltakaa, minun oikeuksiani noudattakaa, ne pitäkää');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'ja pyhittäkää sapattini. Ne olkoot merkkinä välillämme, minun ja teidän, että tulisitte tietämään, että minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Mutta lapset kapinoivat minua vastaan, eivät vaeltaneet säädöksieni mukaan eivätkä noudattaneet oikeuksiani, niin että olisivat ne pitäneet, – jotka ihmisen on pidettävä, että hän niistä eläisi – ja rikkoivat sapattini. Sanoin vuodattavani kiivauteni heidän päälleen ja panevani vihani heissä täytäntöön erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Mutta vedin käteni takaisin ja tein tekoni oman nimeni tähden, ettei se tulisi häväistyksi pakanoiden silmissä, joiden silmien edessä olin vienyt heidät pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Kättä kohottaen myös vannoin heille erämaassa, että hajotan heidät pakanoiden sekaan ja sirotan heidät muihin maihin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'koska he eivät pitäneet säädöksiäni, vaan halveksivat säädöksiäni, rikkoivat sapattini ja heidän silmänsä vilkuilivat heidän isiensä epäjumalien perään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Minäkin annoin heille käskyjä, jotka eivät olleet hyviä, ja oikeuksia, joista he eivät voineet elää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'ja annoin heidän saastua lahjoistaan, siitä, että polttivat uhrina kaiken, mikä avasi äidinkohdun, jotta saattaisin heidät kauhun valtaan ja he tulisivat tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Sen tähden puhu Israelin heimolle, ihmislapsi, ja sano heille: Näin sanoo Herra, Herra: Vielä niinkin ovat isänne minua herjanneet, että ovat olleet uskottomia minua kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Kun toin heidät maahan, jonka olin kättä kohottaen luvannut heille antaa, niin missä vain he näkivät korkean kukkulan tai tuuhean puun, siinä he uhrasivat teurasuhrinsa ja antoivat vihastuttavat uhrilahjansa, siinä he panivat esiin suloisesti tuoksuvat uhrinsa ja siinä vuodattivat juomauhrinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Niin sanoin heille: \'Mikä tämä uhrikukkula on, jolle te menette?\' Niin sellainen sai nimen uhrikukkula aina tähän päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Sen tähden sano Israelin heimolle: Näin sanoo Herra, Herra: Ettekö te saastuta itseänne isienne tiellä? Ettekö kulje uskottomina heidän iljetystensä perässä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Ettekö ole saastuttaneet itseänne kaikilla epäjumalillanne aina tähän päivään asti, kun tuotte lahjojanne ja panette lapsenne käymään tulen läpi? Minäkö antaisin teidän kysyä neuvoa itseltäni, te Israelin heimo? Niin totta kuin minä elän, sanoo Herra, Herra, en anna teidän kysyä neuvoa itseltäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'Se, mikä on tullut teidän mieleenne, ei totisesti tapahdu – se, mitä sanotte: \'Me tahdomme olla pakanoiden kaltaisia, muiden maiden sukukuntien kaltaisia, niin että palvelemme puuta ja kiveä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Niin totta kuin minä elän, sanoo Herra, Herra: totisesti olen hallitseva teitä väkevällä kädellä, ojennetulla käsivarrella ja vuodatetulla vihalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'Vien teidät pois kansojen seasta ja kokoan teidät maista, joihin olitte hajotetut, väkevällä kädellä, ojennetulla käsivarrella ja vuodatetulla vihalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'Tuon teidät kansakuntien erämaahan, ja käyn siellä oikeutta kanssanne kasvoista kasvoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Niin kuin kävin oikeutta isienne kanssa Egyptin erämaassa, niin käyn oikeutta teidän kanssanne, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'Panen teidät kulkemaan ruoskan ali ja saatan teidät liiton siteeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'Puhdistan teistä ne, jotka kapinoivat minua vastaan ja luopuvat minusta. Muukalaisuutensa maasta vien heidät pois, mutta Israelin maahan he eivät tule, ja te tulette tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Mutta te, Israelin heimo! Näin sanoo Herra, Herra: Menkää vain ja palvelkaa itse kukin omia epäjumalianne. Mutta vastedes te totisesti kuulette minua ettekä enää häpäise pyhää nimeäni lahjoillanne sekä epäjumalillanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Sillä pyhällä vuorellani, Israelin korkealla vuorella, sanoo Herra, Herra, siellä he palvelevat minua, koko Israelin heimo, kaikki tyynni, mitä maassa on. Siellä miellyn heihin, siellä otan mielelläni vastaan antimenne, ensi sadon lahjanne ja teidän pyhät lahjanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Niin kuin suloisesti tuoksuvaan uhriin miellyn teihin, kun vien teidät pois kansojen seasta ja kokoan teidät maista, joihin olette hajotetut, ja osoitan teissä pyhyyteni pakanoiden silmien edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'Niin tulette tietämään, että minä olen Herra, kun tuon teidät Israelin maahan, siihen maahan, jonka kättä kohottaen olin luvannut antaa teidän isillenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Muistatte siellä vaelluksenne ja kaikki tekonne, joilla olette itsenne saastuttaneet, ja teitä inhottaa oma itsenne kaikkien pahojen tekojenne tähden, mitä olette tehneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Mutta tulette tietämään, että minä olen Herra, kun teen teille tekoni, oman nimeni tähden, en teidän pahan vaelluksenne enkä riettaiden tekojenne ansion mukaan, te Israelin heimo, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Sitten minulle tuli tämä Herran sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, '\"Ihmislapsi, käännä kasvosi etelää kohti, vuodata sanasi etelää vastaan ja profetoi kedon metsikköä vastaan, joka on Negevissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'Sano Negevin metsikölle: Kuule Herran sana. Näin sanoo Herra, Herra: Katso, sytytän sinut tuleen, ja se kuluttaa kaikki tuoreet puusi ja kuivat puusi. Leimuava liekki ei sammu, ja siitä kärventyvät kaikki kasvot etelästä pohjoiseen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Kaikki liha on näkevä, että minä, Herra, olen sen sytyttänyt: se ei sammu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Minä sanoin: \"Voi Herra, Herra! Ne sanovat minusta: \'Tämähän puhuu pelkkiä vertauksia.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Sitten minulle tuli tämä Herran sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, '\"Ihmislapsi, käännä kasvosi Jerusalemia kohti, vuodata sanasi pyhäköitä vastaan ja profetoi Israelin maata vastaan ja sano Israelin maalle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Näin sanoo Herra: Katso, käyn sinun kimppuusi, vedän miekkani tupesta ja hävitän sinusta vanhurskaan ja jumalattoman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Koska hävitän sinusta vanhurskaan ja jumalattoman, sen tähden miekkani lähtee tupestaan kaiken lihan kimppuun etelästä pohjoiseen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Kaikki liha tulee tietämään, että minä, Herra, olen vetänyt miekkani tupesta, eikä se siihen enää palaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Mutta sinä, ihmislapsi, huokaile! Lanteet murtuneina, katkerassa tuskassa huokaile heidän silmiensä edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Kun he sinulta kysyvät: \'Minkä tähden sinä huokailet?\' niin sano: Sanoman tähden, sillä se saapuu, ja kaikki sydämet raukeavat, kaikki kädet herpoavat, kaikkien henki voipuu, kaikki polvet käyvät veltoiksi kuin vesi. Katso, se tulee, se tapahtuu; sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, '\"Ihmislapsi, profetoi ja sano: Näin sanoo Herra. Sano: Miekka, miekka on teroitettu ja myös kirkkaaksi hiottu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Sen tähden se on teroitettu teurastamaan, välkehtiväksi se on hiottu. Vai iloitsisimmeko? Vitsa, joka lyö poikaani, pitää halpana kaikkia puisia vitsoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Hän on antanut sen hioa käteen otettavaksi. Miekka on teroitettu ja hiottu annettavaksi surmaajan käteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Huuda ja valita, ihmislapsi, sillä tämä tapahtuu kansaani vastaan, kaikkia Israelin ruhtinaita vastaan. He ovat annetut alttiiksi miekalle, he ja kansani. Lyö sen vuoksi lanteisiisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Sillä vitsaa on jo koeteltu. Mutta entä, jos vitsa halveksiikin tätä kaikkea? Se ei tapahdu, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'Mutta sinä, ihmislapsi, profetoi ja lyö käsiäsi yhteen. Tulkoon miekasta kaksi miekkaa, tulkoon kolme. Se on surmamiekka, miekka, joka surmaa suuretkin, joka kiertää heitä joka taholta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'että sydän menehtyisi pelkoon, että kompastuksia olisi paljon. Kaikille heidän porteillensa olen asettanut miekan välkkymään. Voi, se on tehty salamaksi ja on hiottu teurastusta varten!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Lyö terävästi oikealle, ojennu vasemmalle, mihin vain kasvosi käännät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Minäkin lyön käsiäni yhteen ja tyydytän kiivauteni. Minä, Herra, olen puhunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, '\"Sinä, ihmislapsi, laita kaksi tietä, Baabelin kuninkaan miekan tulla. Samasta maasta lähtekööt molemmat. Veistä viitta. Veistä se kaupunkiin vievän tien alkuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Laita tie miekan tulla ammonilaisten Rabbaan sekä Juudaan, varustettuun Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Sillä Baabelin kuningas pysähtyy tienhaaraan, molempien teiden alkuun, taikojansa taikomaan. Hän pudistaa nuolia, kysyy kotijumalilta ja katsoo maksasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Hänen oikeaan käteensä tulee Jerusalemin arpa. Sinne on pantava muurinmurtajia, siellä hänen on kohotettava sotahuuto, pantava muurinmurtajat porteille, luotava valtausluiska ja rakennettava piiritysvalli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Mutta Jerusalemin asukkaiden silmissä tämä on pettävää taikomista. Onhan heillä valojen valat. Mutta hän saattaa muistoon syntivelan, että he joutuisivat kiinni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'Sen tähden, näin sanoo Herra, Herra: Koska olette saattaneet muistoon syntivelkanne rikoksenne tultua julki, niin että teidän syntinne on näkyvissä kaikissa teidän teoissanne, niin – koska te olette saatetut muistoon – teidät otetaan kiinni käsin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Sinä saastutettu, jumalaton Israelin ruhtinas, jonka päivä on silloin tullut, kun syntivelka on saavuttanut viimeisen määränsä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'Näin sanoo Herra, Herra: Ota pois turbaani ja riisu kruunu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Tämä ei pysy samana: alhainen korotetaan, korkea alennetaan. Murskaksi, murskaksi, murskaksi panen tämän kruunun. Siitä ei ole jäävä mitään, kunnes tulee se, jolla on oikeus, ja annan sen hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 33, 'Mutta sinä, ihmislapsi, profetoi ja sano: Näin sanoo Herra, Herra ammonilaisia ja heidän herjauksiaan vastaan: Sano näin: Miekka, miekka on paljastettu, teurastukseen hiottu, pantu kuntoon käyttöä varten ja välkehtimään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 34, 'silloin kun sinulle nähdään petollisia näkyjä ja ennustellaan valheita, että sinut muka pannaan tallaamaan saastaisten, jumalattomien niskaa, joiden päivä on silloin tullut, kun syntivelka on saavuttanut viimeisen määränsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 35, 'Pane se tuppeensa takaisin. Paikassa, jossa olet luotu, synnyinmaassasi, minä sinut tuomitsen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 36, 'Vuodatan päällesi kiivauteni, puhallan sinuun vihani tulen ja annan sinut raakojen miesten ja tuhontekijöiden käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 37, 'Tulen kulutettavaksi sinut annetaan, sinun veresi on oleva keskellä maata, eikä sinua enää muisteta. Sillä minä, Herra, olen puhunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, '\"Sinä, ihmislapsi, etkö tuomitse, etkö tuomitse verivelkojen kaupunkia ja tee sille tiettäväksi kaikkia sen kauhistuksia?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'Sano: Näin sanoo Herra, Herra: Voi kaupunkia, joka on vuodattanut keskuudessaan verta, että tulisi sen aika, ja joka on tehnyt saastuakseen itselleen epäjumalia!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Verestäsi, jonka olet vuodattanut, olet tullut syylliseksi, ja epäjumalistasi, jotka olet tehnyt, olet saastunut. Olet jouduttanut päiviäsi ja olet päässyt vuosiesi määrään. Sen tähden annan sinut pakanoiden häväistäväksi ja kaikkien maiden pilkattavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Läheiset ja kaukaiset pilkkaavat sinua, jonka nimi on saastutettu ja jossa on paljon sekasortoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Katso, Israelin ruhtinaat sinussa luottavat kukin omaan käsivarteensa vuodattaakseen verta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Isää ja äitiä sinussa halveksitaan, muukalaiselle tehdään keskuudessasi väkivaltaa, orpoa ja leskeä sinussa sorretaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Mikä on minulle pyhitettyä, sitä halveksit ja rikot sapattini.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Sinussa on niitä, jotka panettelevat vuodattaakseen verta. Uhrivuorilla he syövät keskuudessasi, ja ilkitöitä tehdään keskelläsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'Isän häpy sinussa paljastetaan. Naiselle, joka on saastainen kuukautistilansa tähden, tehdään keskuudessasi väkivaltaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Toinen harjoittaa kauhistusta lähimmäisensä vaimon kanssa, mies saastuttaa häpeällisesti miniänsä, ja mies tekee keskelläsi väkivaltaa sisarelleen, isänsä tyttärelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Keskuudessasi otetaan lahjuksia veren vuodattamiseksi, sinä otat korkoa ja voittoa, kiskot väkivaltaisesti lähimmäiseltäsi, mutta minut unohdat, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Mutta katso, lyön käsiäni yhteen sinun väärän voittosi tähden, jota olet hankkinut, ja sinun verivelkojesi tähden, joita keskuudessasi on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Kestääköhän rohkeutesi, pysyvätköhän kätesi lujina niinä päivinä, joina teen sinulle tekoni? Minä, Herra, olen puhunut, ja minä sen teen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Hajotan sinut pakanoiden sekaan ja sirottelen sinut muihin maihin ja poistan sinusta saastaisuutesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'Tulit saastaiseksi oman itsesi takia kansojen silmissä, mutta tulet tietämään, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Sitten minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, '\"Ihmislapsi, Israelin heimo on kuonaksi tullut. He ovat kaikki vaskea, tinaa, rautaa ja lyijyä ahjossa. Heistä on tullut hopean kuonaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Sen tähden, näin sanoo Herra, Herra: Koska te kaikki olette tulleet kuonaksi, sen tähden, katso, kokoan teidät keskelle Jerusalemia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Niin kuin hopea, vaski, rauta, lyijy ja tina kootaan keskelle ahjoa, että niihin lietsottaisiin tulta ja ne sulatettaisiin, niin vihassani ja kiivaudessani kokoan teidät ja asetan ahjoon ja sulatan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Kerään teidät ja lietson teihin vihani tulta, ja sulatte keskellä Jerusalemia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Niin kuin hopea sulatetaan keskellä ahjoa, niin sulatetaan teidät sen keskellä. Tulette tietämään, että minä, Herra, olen vuodattanut kiivauteni teidän päällenne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, '\"Ihmislapsi, sano sille: Sinä olet maa, jota ei ole puhdistettu, joka ei ole saanut sadetta vihan päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Profeettojen salaliitto sen keskellä on kuin ärjyvä, saalista raateleva leijona. He syövät sieluja, ottavat aarteet ja kalleudet ja lisäävät sen keskuudessa sen leskien lukua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Sen papit tekevät väkivaltaa lailleni ja häpäisevät sitä, mikä on minulle pyhitettyä, eivät tee erotusta pyhän ja epäpyhän välillä, eivät tee tiettäväksi, mikä on saastaista, mikä puhdasta, ja sulkevat silmänsä sapateiltani, niin että tulen häväistyksi heidän keskellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Sen ruhtinaat siellä ovat kuin saalista raatelevat sudet. He vuodattavat verta ja hukuttavat sieluja kiskoakseen väärää voittoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Sen profeetat valkaisevat heille kaiken kalkilla, kun näkevät petollisia näkyjä ja ennustelevat heille valheita sanoen: \'Näin sanoo Herra, Herra \', vaikka Herra ei ole puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Maan kansa harjoittaa väkivaltaa, riistää ja raastaa. Kurjaa ja köyhää he sortavat ja tekevät muukalaiselle väkivaltaa oikeudesta välittämättä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Etsin heidän joukostaan miestä, joka korjaisi muurin ja seisoisi muurinaukossa edessäni maan puolesta, etten sitä hävittäisi, mutta en löytänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Sen tähden vuodatan heidän päälleen kiivauteni, hukutan heidät vihani tulella ja annan heidän vaelluksensa tulla heidän päänsä päälle, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, '\"Ihmislapsi, oli kaksi naista, saman äidin tyttäriä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'He harjoittivat haureutta Egyptissä. Nuoruudessaan he haureutta harjoittivat. Siellä heidän rintojaan likisteltiin ja heidän neitseellisiä nännejään puristeltiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Heidän nimensä olivat: vanhemman Ohola ja hänen sisarensa Oholiba. He tulivat omikseni ja synnyttivät poikia ja tyttäriä. – Heidän nimensä: Samaria on Ohola ja Jerusalem Oholiba.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Mutta Ohola harjoitti haureutta, vaikka oli minun, ja himoitsi rakastajiaan, assurilaisia, naapureita,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'jotka olivat sinipunaiseen purppuraan puettuja ja olivat käskynhaltijoita ja päälliköitä, komeita nuorukaisia kaikki, ratsumiehiä ja hevosella ratsastajia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Hän antautui haureuteen näiden kanssa, jotka olivat kaikki Assurin valioita. Keitä vain hän himoitsi, niiden kaikkien kanssa hän saastutti itsensä kaikilla heidän epäjumalillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Mutta egyptinaikaista haureuttaan hän ei jättänyt, sillä he olivat maanneet hänen kanssaan hänen nuoruudessaan, olivat puristelleet hänen neitseellisiä nännejään ja vuodattaneet hänen päälleen haureuttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Sen tähden annoin hänet rakastajiensa käsiin, assurilaisten käsiin, joita hän oli himoinnut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'He paljastivat hänen häpynsä ja ottivat hänen poikansa ja tyttärensä ja tappoivat hänet itsensä miekalla, niin että hänestä tuli varoittava esimerkki muille naisille, ja panivat hänessä toimeen tuomiot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Mutta hänen sisarensa Oholiba, vaikka näki tämän, oli himossaan häntäkin riettaampi ja oli haureudessaan riettaampi, kuin hänen sisarensa oli ollut haureudessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Hän himoitsi Assurin poikia, jotka olivat käskynhaltijoita, päälliköitä, naapureita, loisteliaasti puettuja, ratsumiehiä, hevosella ratsastajia, komeita nuorukaisia kaikki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Silloin näin, että hän saastutti itsensä. Sama tie oli kummallakin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Mutta hän meni haureudessaan vielä pidemmälle. Kun hän näki seinään piirrettyjä miehiä, kaldealaisten kuvia, punavärillä piirrettyjä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'vyö vyötettynä vyötäisillä, päässä hieno turbaani, kaikki päälliköiden näköisiä, Baabelin poikien muotoisia, joiden synnyinmaa on Kaldea,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'niin hän silmän näkemältä sai himon heihin ja lähetti lähettiläitä heidän luokseen Kaldeaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Baabelin pojat tulivat ja makasivat hänen kanssaan hekumassa ja saastuttivat hänet haureudellaan, niin että hän saastui heistä. Sitten hänen sielunsa vieraantui heistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Mutta kun hän paljasti haureutensa ja paljasti häpynsä, niin sieluni vieraantui hänestä, niin kuin sieluni oli vieraantunut hänen sisarestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Mutta hän yhä lisäsi haureuttaan, kun muisti nuoruutensa päivät, jolloin oli haureutta harjoittanut Egyptin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'Hän sai himon heidän rakastajiinsa, joiden liha on kuin aaseilla ja vuoto kuin oriilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Sinä etsit nuoruutesi iljettävyyttä, jolloin egyptiläiset puristelivat nännejäsi nuoruutesi rintojen tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Sen tähden, Oholiba, näin sanoo Herra, Herra: Katso, nostatan kimppuusi rakastajasi, joista sielusi on vieraantunut, ja tuon heidät kimppuusi joka taholta:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Baabelin pojat ja kaikki kaldealaiset, Pekodin, Sooan ja Kooan ja heidän kanssaan kaikki Assurin pojat – kaikki komeita nuorukaisia, käskynhaltijoita ja päälliköitä, aseenkantajia ja mainioita miehiä, kaikki he ratsastavat hevosella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'He tulevat kimppuusi aseineen, vaunuineen ja rattaineen ja suurine kansanjoukkoineen. Suurine ja pienine kilpineen ja kypärineen he käyvät sinua vastaan joka taholta. Annan heille tuomiovallan, ja he tuomitsevat sinut oikeuksiensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Osoitan sinussa kiivauteni, niin että he kohtelevat sinua ankarasti. He leikkaavat sinulta nenän ja korvat, ja jälkeläisesi kaatuvat miekkaan. He ottavat poikasi ja tyttäresi, ja jälkeläisesi kuluttaa tuli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'He riisuvat sinulta vaatteesi ja ottavat korusi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Niin teen lopun iljettävyydestäsi ja Egyptin haureudestasi, etkä sitten luo silmiäsi heihin etkä enää muistele Egyptiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Sillä näin sanoo Herra, Herra: Katso, annan sinut niiden käsiin, joita vihaat, niiden käsiin, joista sielusi on vieraantunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'He kohtelevat sinua vihamielisesti, ottavat kaiken vaivannäkösi ja jättävät sinut alastomaksi ja paljaaksi, ja haureellinen häpysi ja iljettävyytesi ja haureutesi paljastuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Näin sinulle tehdään sen tähden, että uskottomana juoksit pakanoiden perässä ja että saastutit itsesi heidän epäjumalillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Vaelsit sisaresi tietä, ja annan hänen maljansa käteesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Näin sanoo Herra, Herra: Sisaresi maljan sinä juot, syvän ja leveän. Tulet nauruksi ja pilkaksi. Malja vetää paljon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Tulet juopumusta ja murhetta täyteen. Kauhun ja häviön malja on sisaresi Samarian malja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Sen juot kuiviin, sen sirpaleita kaluat ja revit niillä rintasi. Sillä minä olen puhunut, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Sen tähden, näin sanoo Herra, Herra: Koska olet minut unohtanut ja heittänyt minut selkäsi taakse, niin kanna myös iljettävyytesi ja haureutesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Herra sanoi minulle: \"Ihmislapsi, tuomitsetko Oholan ja Oholiban? Ilmoita siis heille heidän kauhistuksensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Sillä he ovat rikkoneet avion, ja heidän käsissään on verta. Epäjumalillaan he ovat avion rikkoneet, lapsensakin, jotka he minulle synnyttivät, he ovat polttaneet niiden ruuaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Vielä tämänkin he ovat minulle tehneet: ovat samana päivänä saastuttaneet pyhäkköni ja rikkoneet sapattini.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Teurastettuaan lapsiaan epäjumalilleen he samana päivänä tulivat pyhäkkööni ja häpäisivät sen. Katso, näin he ovat tehneet keskellä huonettani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Vieläpä he lähettivät noutamaan miehiä, jotka tulivat kaukaa. Katso, kun he saapuivat, sinä peseydyit heitä varten, maalasit silmäluomesi ja panit päällesi korut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'Istuit komealle vuoteelle, sen ääressä oli katettu pöytä, ja sille panit suitsukkeeni ja öljyni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Sitten sieltä kuului ilohuuto. Ihmisjoukosta otettujen miesten lisäksi tuotiin erämaasta juomareita, ja he panivat naisten käsiin rannerenkaat ja heidän päähänsä kauniit kruunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Mutta sanoin: \'Aviorikoksesta kuihtuneen kanssa he harjoittavat haureutta ja hän heidän kanssaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Hänen luokseen tultiin, aivan kuin tullaan porttonaisen luo. Niin tultiin Oholan ja Oholiban luo – noiden julkeiden naisten luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Mutta vanhurskaat miehet tulevat tuomitsemaan heidät avionrikkojille säädetyllä tuomiolla ja verenvuodattajille määrätyllä tuomiolla, sillä he ovat rikkoneet avion ja heidän käsissään on verta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Sillä näin sanoo Herra, Herra: Nostatettakoon kansanjoukko heitä vastaan, ja heidät pantakoon kauhistukseksi ja ryöstettäköön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'Kansanjoukko kivittäköön heidät ja hakatkoon kappaleiksi miekoillaan, tappakoon heidän poikansa ja tyttärensä ja polttakoon heidän talonsa tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Lopetan iljettävän menon maasta, ja kaikki naiset ottavat siitä ojentuakseen, niin etteivät harjoita iljettävää menoa, kuten te.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Teidän iljettävyytenne pannaan teidän päällenne, ja saatte kantaa epäjumalienne kanssa tehdyt syntinne. Tulette tietämään, että minä olen Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'Tämä Herran sana tuli minulle yhdeksäntenä vuotena, kymmenennessä kuussa, kuukauden kymmenentenä päivänä ja kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, '\"Ihmislapsi, kirjoita muistiisi päivän nimi – juuri tämän päivän nimi: Baabelin kuningas rynnistää Jerusalemia vastaan juuri tänä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'Lausu kapinoivalle suvulle vertaus ja sano heille: Näin sanoo Herra, Herra: Pane pata [tulelle], pane. Kaada myös siihen vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Kokoa siihen lihankappaleet – kaikki hyvät kappaleet, reittä ja lapaa – ja täytä se valituilla luilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Ota parasta lammasta, pane padan alle tuli. Anna sen kiehua kiehumistaan, niin että luutkin tulevat siinä keitetyiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Sen tähden, näin sanoo Herra, Herra: Voi verivelkojen kaupunkia, pataa, joka on ruostunut ja josta sen ruoste ei lähde! Tyhjennä se kappale kappaleelta: sille ei ole langennut arpaosaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Sillä sen vuodattama veri on sen keskellä, paljaalle kalliolle se on sen koonnut, eikä ole vuodattanut sitä maahan tomun peitettäväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Nostattaakseni kiivauden ja tuottaakseni koston olen pannut sen veren paljaalle kalliolle, ettei se peittyisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Sen tähden, näin sanoo Herra, Herra: Voi verivelkojen kaupunkia! Minäkin panen lisää puita tuleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Lisää puita, sytytä tuli, kypsennä liha, sekoita pataa, kunnes luut hiiltyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Anna sen sitten olla tyhjänä hiiltensä päällä, niin että se kuumenee, sen vaski hehkuu ja sen saastat siitä sulavat ja sen ruosteesta tulee loppu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Siitä on ollut vaivaa väsymykseen asti, mutta sen ruosteen paljous ei ole lähtenyt siitä. Tuleen sen ruoste!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'Sinun iljettävän saastaisuutesi takia – koska puhdistin sinua, mutta et puhdistunut saastaisuudestasi – et enää puhdistu, ennen kuin tyydytän kiivauteni sinussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Minä, Herra, olen puhunut. Se tapahtuu, ja minä teen sen. En luovu, en säästä enkä kadu: teittesi ja tekojesi mukaan sinut tuomitaan, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, '\"Ihmislapsi, katso, otan sinulta äkkiä pois silmiesi ihastuksen, mutta älä valita, älä itke, älköönkä sinulta tulko kyyneleitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Huokaile hiljaa, mutta älä pane toimeen kuolleelle valittajaisia. Sido turbaani päähäsi, pane sandaalit jalkaasi, älä peitä partaasi äläkä syö murehtivien leipää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Puhuin kansalle aamulla, mutta illalla vaimoni kuoli. Sitten aamulla tein, niin kuin minun oli käsketty tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'Kansa sanoi minulle: \"Etkö ilmoita meille, mitä se tietää meille, kun sinä noin toimit?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Sanoin heille: \"Minulle tuli tämä Herran sana, ja se kuului: Sano Israelin heimolle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Näin sanoo Herra, Herra: Katso, häpäisen pyhäkköni, joka on varustuksenne ja ylpeytenne, silmienne ihastus ja sielujenne mieltymys. Poikanne ja tyttärenne, jotka teidän on jätettävä, kaatuvat miekkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Teette, niin kuin olen tehnyt: ette peitä partaanne ettekä syö surevien leipää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'turbaanin pidätte päässänne ja sandaalit jaloissanne, ette valita ettekä itke, mutta te voivutte syntivelkanne tähden ja huokailette toinen toisellenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Hesekiel on oleva teille ennusmerkki: aivan niin, kuin hän on tehnyt, niin tekin teette. Kun tämä tapahtuu, tulette tietämään, että minä olen Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Mutta sinä, ihmislapsi! Sinä päivänä, jona otan heiltä heidän varustuksensa, ihanan ilonsa, silmiensä ihastuksen, elämänsä toivon, heidän poikansa ja tyttärensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'sinä päivänä tulee pakolainen luoksesi ilmoittamaan tämän korviesi kuullen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'Sinä päivänä avaat suusi yhdessä pakolaisen kanssa, ja puhut etkä enää ole mykkänä ja olet oleva heille ennusmerkki, ja he tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, '\"Ihmislapsi, käännä kasvosi ammonilaisia kohti ja profetoi heitä vastaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'ja sano ammonilaisille: Kuulkaa Herran, Herran sana: Näin sanoo Herra, Herra: Sinä sanoit: pyhäköstäni, kun se häväistiin, ja Israelin maasta, kun se hävitettiin, ja Juudan heimosta, kun he menivät karkotukseen: \"Kas noin!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'Koska niin sanoit, sen tähden, katso, annan sinut Idän miesten omaksi, ja he laittavat sinuun leiripaikkansa ja asettavat sinuun asuntonsa. He syövät hedelmäsi ja juovat maitosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Rabban panen kamelien laitumeksi ja ammonilaisten maan lampaiden levähdyspaikaksi. Tulette tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Sillä näin sanoo Herra, Herra: Koska sinä taputit käsiä ja poljit jalkaa ja sielu täynnä halveksuntaa pidit iloa Israelin maasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'sen tähden, katso, ojennan käteni sinua vastaan ja annan sinut pakanoiden ryöstettäväksi ja hävitän sinut kansakuntien joukosta ja hukutan sinut maiden luvusta ja tuhoan sinut. Tulet tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Näin sanoo Herra, Herra: Koska Mooab ja Seir ovat sanoneet: \'Katso, Juudan heimon käy kuin kaikkien muiden kansojen\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'sen tähden, katso, teen avonaiseksi pääsyn Mooabin sivustan kaupungeista – sen rajoille kaupungeista, jotka ovat maan kaunistus: Beet-Jesimot, Baal-Meon ja Kirjataim.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'Idän miesten omaksi annan sen ammonilaisten kanssa, niin ettei ammonilaisia enää muisteta kansojen joukossa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'ja Mooabissa panen toimeen tuomiot. He tulevat tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Näin sanoo Herra, Herra: Koska Edom menetteli kovin kostonhimoisesti Juudan heimoa kohtaan ja rikkoi raskaasti kostaessaan heille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'sen tähden, näin sanoo Herra, Herra: Ojennan käteni Edomia vastaan ja hävitän siitä ihmiset ja eläimet. Teemanista lähtien teen sen raunioiksi, ja Dedania myöten he kaatuvat miekkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'Mutta kostoni, joka Edomia kohtaa, annan kansani Israelin käteen, ja he tekevät Edomia kohtaan vihani ja kiivauteni mukaan. Edom saa tuntea kostoni, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Näin sanoo Herra, Herra: Koska filistealaiset menettelivät kostonhimoisesti ja halveksunta sielussaan, kostivat kovasti, ikivihassa tuottaakseen tuhon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'sen tähden, näin sanoo Herra, Herra: Katso, ojennan käteni filistealaisia vastaan, hävitän kreetit, hukutan, mitä on jäljellä meren rannikolla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'ja teen heille suuret kostoteot rangaisten kiivaudessa. He tulevat tietämään, että minä olen Herra, kun annan kostoni kohdata heitä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'Yhdentenätoista vuotena, kuukauden ensimmäisenä päivänä tuli minulle tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, '\"Ihmislapsi, koska Tyyro sanoi Jerusalemista: \'Kas noin! Murrettu on kansojen ovi, minuun päin se on kääntynyt, tulen täyteen – se on raunioina!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'sen tähden, näin sanoo Herra, Herra: Katso, käyn kimppuusi, Tyyro, ja nostatan monet kansat sinua vastaan, niin kuin meri nostaa aaltonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'Ne hävittävät Tyyron muurit, repivät maahan sen tornit, ja lakaisen siitä pois sen tomutkin ja panen sen paljaaksi kallioksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Siitä tulee verkkojen kuivauspaikka keskelle merta. Sillä minä olen puhunut, sanoo Herra, Herra; ja se joutuu kansojen ryöstettäväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'Sen tytärkaupungit, jotka ovat mantereella, surmataan miekalla, ja he tulevat tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Sillä näin sanoo Herra, Herra: Katso, tuon Tyyron kimppuun Nebukadressarin, Baabelin kuninkaan pohjoisesta, kuninkaitten kuninkaan, hevosten ja vaunujen ja ratsumiesten ja suuren väenpaljouden kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Sinun tytärkaupunkisi, jotka ovat mantereella, hän surmaa miekalla ja asettaa sinua vastaan saartovarusteet, rakentaa sinua vastaan vallin, asettaa sinua vastaan kilvet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'suuntaa muureihisi murtajansa iskut ja kukistaa tornisi aseillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Hänen hevostensa paljous peittää sinut pölyyn. Ratsumiesten, pyörien ja vaunujen ryskeestä sinun muurisi vapisevat, kun hän hyökkää sisälle porteistasi, niin kuin valloitettuun kaupunkiin hyökätään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Hevostensa kavioilla hän tallaa rikki kaikki katusi, surmaa miekalla kansasi, ja mahtavat patsaasi kaatuvat maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'He riistävät rikkautesi ja ryöstävät kauppatavarasi, repivät muurisi maahan ja kukistavat kauniit talosi, sekä kivesi, puusi ja tomusi he heittävät mereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'Lakkautan laulujesi helinän, eikä kuulu enää lyyrojesi soitto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Teen sinut paljaaksi kallioksi, sinusta tulee verkkojen kuivauspaikka, eikä sinua enää rakenneta. Sillä minä, Herra, olen puhunut, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Näin sanoo Herra, Herra Tyyrolle: Eivätkö saaret vapise kukistumisesi pauhusta, kun haavoitetut voihkivat, kun surman omat surmataan keskelläsi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Valtaistuimiltaan astuvat alas kaikki meren ruhtinaat. He heittävät pois viittansa ja riisuvat kirjaillut vaatteensa, he pukeutuvat kauhuun ja istuvat maahan, vapisevat joka hetki, murheissaan tähtesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'He virittävät sinusta itkuvirren ja sanovat sinulle: \'Kuinka olet sinä, joka olit asuttu, hävinnyt meriltä, sinä ylistetty kaupunki, väkevä merellä, sinä ja asukkaasi, jotka levittivät kauhuaan kaikkiin siellä asuviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Nyt saaret värisevät häviösi päivänä, merensaaret kauhistuvat loppuasi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Sillä näin sanoo Herra, Herra: Kun teen sinusta aution kaupungin, niin kuin asumattomat kaupungit ovat, kun annan syvyyden käydä ylitsesi ja paljot vedet peittävät sinut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'silloin syöksen sinut alas hautaan vaipuneiden pariin, ennen eläneen kansan luo, ja annan sinulle asunnon maan syvyyksissä, niin kuin siellä ovat vanhat rauniot, hautaan vaipuneiden parissa, ettei sinussa asuttaisi. Mutta ihanuuden annan elävien maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Panen sinut kauhuksi, sinua ei sitten enää ole. Jos sinua etsitään, sinua ei enää koskaan löydy, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, '\"Sinä, ihmislapsi! Viritä itkuvirsi Tyyrosta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'ja sano Tyyrolle, joka asuu meren porteilla ja käy kauppaa kansojen kanssa, monilukuisilla saarilla: Näin sanoo Herra, Herra: Tyyro, sinä sanot: \'Minä olen kauneuden täydellisyys!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Meren sydämessä on alueesi, rakentajasi tekivät sinun kauneutesi täydelliseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Senirin sypresseistä he rakensivat sinuun kaiken, mikä laudoista on, ottivat Libanonin setrin tehdäkseen sinuun maston,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'tekivät Baasanin tammista airosi, kansilankkusi tekivät norsunluusta ja kittiläisten saarten puusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Kirjailtua Egyptin pellavaa oli purjeesi, ja se oli sinulla lippuna. Katoksesi oli sinipunaista ja purppuranpunaista Elisa-saarten kangasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Siidonin ja Arvadin asukkaat olivat sinulla soutajina. Omat viisaasi, Tyyro, olivat sinussa – he olivat päällikköinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Gebalin vanhimmat ja viisaat olivat sinulla vuotokohtien korjaajia. Meren kaikki laivat merimiehineen olivat sinussa tavaroitasi vaihtamassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Persia, Luud ja Puut olivat sotajoukossasi sotureinasi. He ripustivat sinuun kypäriä ja kilpiä. Ne sinua koristivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Arvadilaiset ja muu sotajoukkosi olivat muureillasi ympäriinsä ja gammadilaiset torneissasi. He ripustivat varustuksensa pitkin ympäri muurejasi. Ne tekivät kauneutesi täydelliseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Tarsis oli kauppatuttavasi kaikkinaisten rikkauksiesi runsauden takia: hopealla, raudalla, tinalla ja lyijyllä he maksoivat tavarasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Jaavan, Tuubal ja Mesek kävivät kauppaa kanssasi. Elävillä ihmisillä ja vaskiesineillä he maksoivat vaihtotavarasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Toogarman heimo maksoi tavarasi hevosilla, ratsuilla ja muuleilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Dedanilaiset kävivät kauppaa kanssasi. Monilukuisten rannikkojen asukkaat olivat kauppatuttaviasi ja alaisiasi. Norsunluuta ja ebenpuuta ne toivat sinulle maksuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Aram oli kauppatuttavasi tuotteittesi runsauden takia. Rubiineilla, purppuralla, kirjaillulla kankaalla, valkopellavalla, koralleilla ja jaspiksella he maksoivat tavarasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Juuda ja Israelin maa kävivät kauppaa kanssasi: Minnitin vehnällä, leivoksilla, hunajalla, öljyllä ja balsamilla he maksoivat vaihtotavarasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damasko oli kauppatuttavasi tuotteittesi runsauden ja kaikenlaisten rikkauksiesi runsauden takia: Helbonin viiniä ja Saharin villoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Vedan ja Jaavan Usalasta maksoivat ostoksesi taotulla raudalla. Kassiaa ja kalmoruokoa tuli sinulle vaihtotavarana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedan kävi kauppaa kanssasi ratsastussatuloiden loimilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arabia ja kaikki Keedarin ruhtinaat kävivät kanssasi kauppaa. Lampaita, pässejä ja vuohipukkeja he myivät sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Saban ja Raman kauppiaat kävivät kauppaa kanssasi. Kaikenlaisilla parhailla balsameilla, kaikilla kalliilla kivillä ja kullalla he maksoivat tavarasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Haaran ja Kanne ja Eden, Saban kauppiaat, Assur ja Kilmad kävivät kauppaa kanssasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'He kävivät kanssasi kauppaa markkinoillasi kauniilla vaatteilla, punasinisillä ja kirjailluilla viitoilla, kirjavakuteisilla matoilla ja punotuilla, kestävillä köysillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Tarsiin laivat kuljettivat vaihtotavaroitasi. Niin sinä tulit täyteen ja olit hyvin kuulu merten sydämessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Soutajasi vievät sinut suurille vesille, ja itätuuli särkee sinut merten sydämessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Sinun rikkautesi, tavarasi, vaihtotavarasi, merimiehesi ja laivurisi, vuotokohtien korjaajasi, tavaranvaihtajasi ja kaikki sotamiehesi, jotka ovat sinussa ja koko suuressa joukossasi, joka on keskuudessasi, painuvat merten sydämeen kukistumisesi päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Laivan päälliköiden itkun äänestä vapisevat tantereet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'Alas laivoistaan astuvat kaikki soutajat, merimiehet ja kaikki merilaivan päälliköt astuvat maihin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'huutavat tähtesi suurella äänellä ja itkevät katkerasti, heittävät tomua päänsä päälle ja kieriskelevät tuhkassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'He ajavat tähtesi päänsä paljaaksi, kääriytyvät säkkeihin ja itkevät tähtesi mieli murheellisena ja valittaen katkerasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Valittaessaan he virittävät sinusta itkuvirren ja laulavat sinusta: \'Kuka oli Tyyron vertainen, hänen, joka on nyt niin hiljaa meren keskellä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Kun tavarasi saapuivat meriltä, sinä ravitsit monet kansat. Rikkauksiesi ja vaihtotavaroittesi runsaudella sinä teit rikkaiksi maan kuninkaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Nyt, kun jouduit haaksirikkoon, vetten syvyyksiin, mukanasi vajosivat sinne vaihtotavarasi ja koko suuri joukkosi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Sinun tähtesi tulivat murheellisiksi kaikki saarten asukkaat, ja heidän kuninkaansa ovat kauhun vallassa vapina kasvoillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Kansojen kauppiaat viheltävät sinulle. Kauhuksi olet tullut, eikä sinua enää koskaan ole.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Sitten minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, '\"Ihmislapsi, sano Tyyron ruhtinaalle: Näin sanoo Herra, Herra: Koska sydämesi on ylpistynyt ja sanot: \'Minä olen jumala ja istun jumalien istuimella merten sydämessä\', ja olet kuitenkin ihminen, et jumala, vaikka sydämeltäsi olet viisaudessa jumalan vertainen –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'ja katso, Danielia viisaampi sinä oletkin, mikään salaisuus ei ole sinulta pimitetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'Viisaudessasi ja ymmärtäväisyydessäsi olet hankkinut itsellesi rikkautta, hankkinut kultaa ja hopeaa aarreaittoihisi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'ja suuressa viisaudessasi olet kaupankäynnillä kartuttanut rikkautesi, ja sydämesi on ylpistynyt rikkaudestasi –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'sen tähden, näin sanoo Herra, Herra: Koska vertaat sydäntäsi Jumalan sydämeen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'sen tähden, katso, tuon kimppuusi muukalaiset, julmimmat pakanoista. He paljastavat miekkansa viisautesi kauneutta vastaan ja saattavat häpeään ihanuutesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'He syöksevät sinut alas kuoppaan, ja kuolet, niin kuin surmatut kuolevat merten sydämessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Sanotko surmaajasi edessä: \'Minä olen Jumala\', kun kuitenkin kaatajiesi käsissä olet ihminen etkä Jumala?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Niin kuin ympärileikkaamattomat kuolevat, sinä kuolet muukalaisten käden kautta. Sillä minä olen puhunut, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Sitten minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, '\"Ihmislapsi, viritä itkuvirsi Tyyron kuninkaasta ja sano hänelle: Näin sanoo Herra, Herra: Sinä olet sopusuhtaisuuden sinetti, täynnä viisautta, täydellinen kauneudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Eedenissä, Jumalan puutarhassa, sinä olit. Peitteenäsi olivat kaikenlaiset kalliit kivet. Karneolia, topaasia ja jaspista, krysoliittia, onyksia ja berylliä, safiiria, rubiinia ja smaragdia sekä kultaa olivat upotus- ja syvennystyöt sinussa, valmistetut sinä päivänä, jona sinut luotiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Olit kerubi, joka suojasi laajalti, ja minä asetin sinut Jumalan pyhälle vuorelle käyskentelemään tulisten kivien keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Sinä olit nuhteeton vaellukseltasi siitä päivästä, jona sinut luotiin, siihen saakka, kunnes sinussa löydettiin vääryys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Suuressa kaupankäynnissäsi tuli sydämesi täyteen väkivaltaa, ja teit syntiä. Karkotan sinut häväistynä Jumalan vuorelta ja hävitän sinut, suojaava kerubi, pois tulisten kivien keskeltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Sydämesi ylpistyi kauneudestasi, ihanuutesi tähden kadotit viisautesi. Heitän sinut maahan, annan sinut häpeään kuninkaille heidän silmiensä edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Paljoilla synneilläsi ja tekemällä vääryyttä kaupoissasi olet häväissyt pyhäkkösi. Annan keskeltäsi puhjeta tulen. Se kuluttaa sinut. Panen sinut tuhkaksi maahan kaikkien silmien edessä, jotka sinut näkivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Kaikki tuttavasi kansojen seassa hämmästyvät tähtesi. Kauhuksi sinä tulet, eikä sinua enää koskaan ole oleva.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, '\"Ihmislapsi, käännä kasvosi Siidonia kohti ja profetoi sitä vastaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'ja sano: Näin sanoo Herra, Herra: Katso, käyn kimppuusi, Siidon, ja näytän kunniani keskuudessasi. He tulevat tietämään, että minä olen Herra, kun panen siinä toimeen tuomiot ja näytän siinä pyhyyteni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Lähetän sinne ruton ja verta kaduille, ja kaatuneita on viruva sen keskellä, miekkaan kaatuneita. Se käy sen kimppuun joka taholta. Niin he tulevat tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Israelin heimolle ei enää ole pistävänä orjantappurana eikä vaivaavana ohdakkeena yksikään sen naapureista, jotka ovat heitä halveksineet. He tulevat tietämään, että minä olen Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Näin sanoo Herra, Herra: Kun kokoan Israelin heimon kansakunnista, joiden sekaan heidät on hajotettu, silloin näytän pyhyyteni heissä pakanakansojen silmien edessä, ja he saavat asua maassaan, jonka annoin palvelijalleni Jaakobille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'He asuvat siinä turvallisesti ja rakentavat taloja ja istuttavat viinitarhoja. Turvassa he asuvat, kun panen toimeen tuomiot kaikille heidän naapureilleen, jotka ovat heitä halveksineet. Silloin he tulevat tietämään, että minä olen Herra, heidän Jumalansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'Kymmenentenä vuotena, kymmenennessä kuussa, kuukauden kahdentenatoista päivänä minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, '\"Ihmislapsi, käännä kasvosi faraota, Egyptin kuningasta, kohti ja profetoi häntä ja koko Egyptiä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Puhu ja sano: Näin sanoo Herra, Herra: Katso, käyn kimppuusi, farao, Egyptin kuningas, suuri krokotiili, joka makaat virtojesi keskellä, joka sanot: \'Niilivirtani on minun, ja olen sen itselleni tehnyt.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Panen koukut leukoihisi, tartutan virtojesi kalat suomuihisi ja nostan sinut ylös virtojesi keskeltä sekä kaikki virtojesi kalat, jotka ovat suomuihisi tarttuneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Heitän erämaahan sinut ja kaikki virtojesi kalat. Putoat kedolle, sinua ei korjata eikä koota. Metsän pedoille ja taivaan linnuille annan sinut ruuaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'Kaikki Egyptin asukkaat tulevat tietämään, että minä olen Herra. Sillä he ovat ruokosauva Israelin heimolle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'kun he kädellä tarttuvat sinuun, sinä säryt ja lävistät heiltä kaikki olkapäät. Kun he nojaavat sinuun, sinä murrut ja jäykistät heiltä kaikki lanteet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Sen tähden, näin sanoo Herra, Herra: Katso, minä tuon kimppuusi miekan ja hävitän sinusta ihmiset ja eläimet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'Egyptin maa tulee autioksi ja raunioiksi. He tulevat tietämään, että minä olen Herra. Sillä hän on sanonut: \'Niilivirta on minun, ja minä olen sen tehnyt.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Sen tähden, katso, käyn sinun ja virtojesi kimppuun ja teen Egyptin maan raunioiksi, kuivaksi ja autioksi Migdolista Seveneen ja aina Kuusin rajaan saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Siellä ei kulje ihmisen jalka, eikä siellä kulje karjaeläimen jalka, eikä siellä asuta neljäänkymmeneen vuoteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Autioksi teen Egyptin maan autioitettujen maiden joukossa, ja sen kaupungit tulevat olemaan autioina raunioitettujen kaupunkien joukossa neljäkymmentä vuotta, ja egyptiläiset hajotan kansojen sekaan ja sirottelen heidät muihin maihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Sillä näin sanoo Herra, Herra: Neljänkymmenen vuoden kuluttua kokoan egyptiläiset kansakunnista, joiden sekaan he olivat hajotetut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'käännän Egyptin kohtalon ja tuon heidät takaisin Patroksen maahan, josta he ovat lähtöisin. Siellä he tulevat olemaan vähäpätöinen valtakunta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'He tulevat olemaan vähäpätöisin valtakunnista, eivätkä enää kohoa kansakuntien yläpuolelle. Vähennän heidät niin, etteivät he enää vallitse kansoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'He eivät ole enää Israelin heimon turvana. He saattavat muistoon Israelin syntivelan, kun se kääntyi heidän puoleensa. He tulevat tietämään, että minä olen Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Kahdentenakymmenentenä seitsemäntenä vuotena, ensimmäisessä kuussa, kuukauden ensimmäisenä päivänä tuli minulle tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, '\"Ihmislapsi, Baabelin kuningas Nebukadressar on teettänyt sotajoukoillaan suuren työn Tyyroa vastaan. Kaikki päät ovat käyneet kaljuiksi ja kaikki hartiat ovat hiertyneet. Mutta palkkaa ei Tyyrosta ole tullut hänelle eikä hänen sotajoukoilleen työstä, jota he ovat tehneet sitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Sen tähden, näin sanoo Herra, Herra: Katso, minä annan Baabelin kuninkaalle Nebukadressarille Egyptin maan. Hän vie sen rikkaudet, saa sen saaliikseen, ryöstää sen ryöstettävät, ja se on oleva hänen sotajoukkojensa palkka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Palkaksi, jonka toivossa hän on työtä tehnyt, annan hänelle Egyptin maan, sillä minun hyväkseni he ovat sitä tehneet, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'Sinä päivänä annan puhjeta Israelin heimolle sarven, ja avaan suusi heidän keskellään. He tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Sitten minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, '\"Ihmislapsi, profetoi ja sano: Näin sanoo Herra, Herra: Valittakaa: \'Voi sitä päivää!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Sillä lähellä on päivä, lähellä Herran päivä. Se on pilvinen päivä, pakanakansojen aika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Miekka tulee Egyptiin, ja kauhu leviää Kuusiin, kun surmattuja kaatuu Egyptissä, kun siltä viedään sen rikkaudet ja revitään perustukset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Kuus, Puut ja Luud, kaikki sekakansa, Kuub ja liittoutuneen maan miehet kaatuvat heidän kanssaan miekkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Näin sanoo Herra: Egyptin tuet kaatuvat, ja sen ylpeä mahti alenee. Migdolista Seveneen asti he siellä kaatuvat miekkaan, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'Autioiksi he joutuvat autioiksi tehtyjen maitten joukkoon, ja heidän kaupunkinsa tulevat olemaan raunioiksi pantujen kaupunkien joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'He tulevat tietämään, että minä olen Herra, kun sytytän Egyptin tuleen ja kaikki sen auttajat sortuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'Sinä päivänä lähtee luotani laivoilla lähettiläitä pelästyttämään turvassa elävää Kuusia. Heille tulee tuska kuin Egyptin päivänä, sillä katso, se tulee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Näin sanoo Herra, Herra: Teen lopun Egyptin joukoista Baabelin kuninkaan Nebukadressarin kädellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Hän ja hänen väkensä hänen kanssaan, julmimmat pakanoista, tuodaan hävittämään maata, ja he paljastavat miekkansa Egyptiä vastaan ja täyttävät maan surmatuilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Teen virrat kuiviksi ja myyn maan pahojen käsiin ja teen autioksi maan ja kaiken, mitä siinä on, muukalaisten kädellä. Minä, Herra, olen puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Näin sanoo Herra, Herra: Tuhoan epäjumalat ja lopetan epäjumalat Noofista ja ruhtinaat Egyptistä. Niitä ei ole enää oleva, ja saatan Egyptin maan pelon valtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Teen Patroksen autioksi, sytytän Sooanin tuleen ja panen toimeen tuomiot Noossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Vuodatan kiivauteni Siiniin, Egyptin linnoitukseen, ja hävitän Noon meluavat joukot');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'ja sytytän Egyptin tuleen. Siin kieriskelee tuskasta, Noo murskataan, ja Noofiin ahdistajat hyökkäävät keskellä päivää!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Aavenin ja Piibesetin nuorukaiset kaatuvat miekkaan, ja muut menevät vankeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'Tehafneheessa päivä pimenee, kun särjen siellä Egyptin ikeen, ja siinä saa lopun sen ylpeä mahti. Sen itsensä peittää pilvi, ja sen tyttäret menevät vankeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Panen tuomiot toimeen Egyptissä, ja he tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Yhdentenätoista vuotena, ensimmäisessä kuussa, kuukauden seitsemäntenä päivänä tuli minulle tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, '\"Ihmislapsi, olen murskannut faraon, Egyptin kuninkaan, käsivarren, ja katso, sitä ei sidota, ei hoideta eikä panna kääreeseen, että se sidottuna vahvistuisi tarttuakseen miekkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Sen tähden, näin sanoo Herra, Herra: Katso, käyn faraon, Egyptin kuninkaan, kimppuun ja murskaan häneltä käsivarret, sekä voimakkaan että murskatun käden, ja pudotan miekan hänen kädestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Hajotan egyptiläiset kansojen sekaan ja sirottelen heidät muihin maihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Baabelin kuninkaan käsivarret vahvistan ja annan miekkani hänen käteensä. Mutta faraolta murskaan käsivarret, ja hän voihkii hänen edessään, niin kuin nujerrettu voihkii.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Vahvistan Baabelin kuninkaan käsivarret, mutta faraon käsivarret vaipuvat alas. He tulevat tietämään, että minä olen Herra, kun annan miekkani Baabelin kuninkaan käteen, että hän ojentaisi sen Egyptin maata vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'Hajotan egyptiläiset kansojen sekaan ja sirottelen heidät muihin maihin. He tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Yhdentenätoista vuotena, kolmannessa kuussa, kuukauden ensimmäisenä päivänä tuli minulle tämä Herran sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, '\"Ihmislapsi, sano faraolle, Egyptin kuninkaalle, ja hänen meluaville joukoilleen: Kenen kaltainen olet suuruudessasi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Katso, Assur oli setri Libanonilla, kauniine oksineen, varjoisine lehvineen, korkeakasvuinen, ja sen latva oli tiheän oksaston keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Vedet olivat kasvattaneet sen suureksi, korkeaksi sen oli saanut syvyys, joka virtoineen kiersi sen istutusmaata ja lähetti ojiaan kaikille metsän puille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Sen tähden siitä tuli korkeakasvuisin kaikista kedon puista. Se sai paljon haaroja, ja oksat, joita se levitti, tulivat pitkiksi runsaista vesistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Sen lehvillä pesivät kaikki taivaan linnut, sen oksien alla synnyttivät kaikki kedon eläimet, ja sen varjossa asuivat kaikki suuret kansat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Kaunis se oli suuruudessaan ja oksiensa pituudessa, sillä sen juuri oli runsaiden vetten ääressä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Setrit eivät olleet sen vertaisia Jumalan puutarhassa, eivät sypressit sen oksien veroisia, eivät plataanit niin kuin sen haarat. Ei yksikään puu Jumalan puutarhassa ollut kauneudessa sen veroinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Minä tein sen niin kauniiksi oksien runsaudessa, että kaikki Eedenin puut Jumalan puutarhassa sitä kadehtivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Sen tähden, näin sanoo Herra, Herra: Koska se tuli korkeakasvuiseksi ja sen latva oli tiheän lehvästön keskellä ja sen sydän ylpistyi sen korkeudesta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'annoin sen pakanoista mahtavimman käsiin, ja hän teki sille, mitä teki. Jumalattomuutensa tähden karkotin sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'Sen hakkasivat muukalaiset, julmimmat pakanoista, ja heittivät maahan. Vuorille ja kaikkiin laaksoihin kaatuivat sen haarat, ja sen oksat murskaantuivat kaikkiin maan puroihin. Kaikki maan kansat laskeutuivat alas sen varjosta ja jättivät sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Sen kaatuneella rungolla asuvat kaikki taivaan linnut, ja sen oksien ääressä oleskelevat kaikki kedon eläimet –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'ettei yksikään puu vesien äärellä kasvaisi niin korkeaksi eikä nostaisi latvaansa paksujen oksien keskeltä ja etteivät mahtavimmatkaan niistä, ei mitkään, jotka juovat vettä, olisi korkeudessaan pysyviä, sillä ne ovat kaikki annetut alttiiksi kuolemalle, menemään maan syvyyteen, hautaan vaipuneiden pariin yhdessä ihmislasten kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Näin sanoo Herra, Herra: Sinä päivänä, jona hän astui alas hautaan, verhosin syvyyden suruun hänen tähtensä, pidätin virrat, niin että paljot vedet pysähtyivät juoksussaan, ja puin Libanonin hänen tähtensä mustiin, ja kaikki kedon puut olivat näännyksissä hänen tähtensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Hänen kaatumisensa ryskeestä panin kansakunnat vapisemaan, kun syöksin sen alas hautaan, hautaan vaipuneiden pariin. Mutta lohdutetuiksi tulivat maan syvyydessä kaikki Eedenin puut, Libanonin valiot ja parhaat, kaikki, jotka juovat vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Myös ne astuivat alas hänen kanssaan hautaan, miekalla kaadettujen pariin, samoin hänen auttajansa, ne, jotka istuivat hänen varjossaan kansojen joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Oliko yksikään Eedenin puista vertaisesi kunniassa ja suuruudessa? Mutta sinut syöstiin Eedenin puiden kanssa alas maan syvyyteen. Ympärileikkaamattomien keskellä makasit miekalla kaadettujen kanssa. Samoin käy faraon ja koko hänen meluavan joukkonsa, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'Kahdentenatoista vuotena, kahdennessatoista kuussa, kuukauden ensimmäisenä päivänä tuli minulle tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, '\"Ihmislapsi, viritä itkuvirsi faraosta, Egyptin kuninkaasta, ja sano hänelle: Olet kuin nuori leijona kansojen joukossa, sinä olet kuin lohikäärme meressä, joka pärskyttelet vettä virroissasi, loiskutat vettä jaloillasi ja sotket sen virtoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Näin sanoo Herra, Herra: Minä levitän verkkoni päällesi monien kansojen suurella joukolla, ja ne vetävät sinut ylös pyydykselläni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Heitän sinut maahan kedolle ja panen asumaan päälläsi kaikenlaiset taivaan linnut ja teen sinusta kylläisiksi kaiken maan eläimet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'Annan lihasi vuorille ja täytän suurella ruumiillasi laaksot,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'juotan maan sillä, mikä sinusta valuu, verelläsi aina vuorille asti, ja purojen uomat tulevat sinusta täyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Peitän taivaan, kun sinut sammutan, ja pimennän sen tähdet. Auringon peitän pilviin, eikä kuu anna valonsa loistaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Kaikki taivaan loistavat valot pimennän takiasi ja teen maasi pimeäksi, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Murehdutan monien kansojen sydämet, kun saatan tiedoksi sinun murskaamisesi kansakunnille, maihin, joita et tuntenut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Saatan kauhun valtaan sinun tähtesi monet kansat, ja heidän kuninkaansa ovat suuresti peloissaan tähtesi, kun heilutan miekkaani heidän nähtensä, ja he vapisevat joka hetki kukin oman henkensä tähden kukistumisesi päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Sillä näin sanoo Herra, Herra: Baabelin kuninkaan miekka tulee päällesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Kaadan meluisan joukkosi sankarien miekoilla. He kaikki ovat pakanoista julmimpia. He kukistavat Egyptin ylpeyden. Koko sen meluisa joukko tuhotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Hävitän siitä kaiken karjan runsaiden vetten ääreltä. Niitä ei enää tallaa ihmisen jalka eivätkä niitä sotke karjan sorkat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Silloin annan sen vesien laskeutua kirkkaiksi, ja panen sen virrat juoksemaan kuin öljyn, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Teen Egyptin maan autioksi ja maa tulee autioksi kaikesta, mitä siinä on. Surmaan kaikki sen asukkaat. He tulevat tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Itkuvirsi tämä on, ja sitä kyllä viritetään. Pakanakansojen tyttäret sitä virittävät. Ne virittävät sitä Egyptistä ja kaikesta sen meluisasta joukosta, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Kahdentenatoista vuotena, kuukauden viidentenätoista päivänä minulle tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, '\"Ihmislapsi, veisaa kuolinvalitus Egyptin meluisasta joukosta, saata se ja mahtavien pakanakansojen tyttäret alas maan syvyyksiin, hautaan vaipuneiden pariin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Oletko vielä kaikkia muita ihanampi? Astu alas ja anna laittaa makuusijasi ympärileikkaamattomien pariin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'He kaatuvat miekalla surmattujen joukkoon. Miekka on jo annettu! Temmatkaa pois Egypti kaikkine meluisine joukkoineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Mahtavimmat sankareista puhuvat hautojen keskeltä sille ja sen auttajille: \'Alas ovat astuneet, siellä makaavat ympärileikkaamattomat, miekalla surmatut.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Siellä on Assur kaikkine joukkoineen. Niiden haudat ovat hänen ympärillään. Kaikki he ovat surmattuja, miekkaan kaatuneita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Hänen hautansa ovat pohjimmaisessa kuopassa, ja hänen joukkonsa on hänen hautansa ympärillä. He ovat kaikki surmattuja, miekkaan kaatuneita, nuo, jotka levittivät kauhua elävien maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Siellä on Eelam, ja koko hänen meluisa joukkonsa on hänen hautansa ympärillä. Kaikki he ovat surmattuja, miekkaan kaatuneita, jotka ympärileikkaamattomina astuivat alas maan syvyyksiin, nuo, jotka levittivät kauhuaan elävien maassa, mutta kantavat häpeäänsä hautaan vaipuneiden parissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Surmattujen keskellä on makuusija annettu hänelle sekä kaikelle hänen meluisalle joukolleen. Niiden haudat ovat hänen ympärillään. Kaikki tyynni ne ovat ympärileikkaamattomia, miekalla surmattuja, sillä he olivat kauhuna elävien maassa, mutta saavat kantaa häpeänsä hautaan vaipuneitten parissa. Surmattujen keskelle on hänet pantu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Siellä on Mesek-Tuubal kaikkine meluisine joukkoineen. Niiden haudat ovat hänen ympärillään. He ovat kaikki ympärileikkaamattomia, miekalla surmattuja, sillä ne levittivät kauhuaan elävien maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'He eivät makaa sankarien parissa, jotka ovat kaatuneet ympärileikkaamattomien joukosta, jotka ovat astuneet alas hautaan sota-aseineen, joiden pään alle on pantu heidän miekkansa ja joiden luiden päällä on heidän syntivelkansa, sillä sankarien kauhu oli elävien maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Sinutkin muserretaan ympärileikkaamattomien joukossa, ja saat maata miekalla surmattujen parissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Siellä on Edom, sen kuninkaat ja kaikki sen ruhtinaat, jotka sankaruudessaan pantiin miekalla surmattujen pariin. He makaavat ympärileikkaamattomien ja hautaan vaipuneiden parissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Siellä ovat kaikki pohjoisen maan ruhtinaat ja kaikki siidonilaiset, jotka ovat astuneet surmattujen pariin kauhistavuudessaan, ovat tulleet häpeään sankaruudessaan ja makaavat ympärileikkaamattomina miekalla surmattujen parissa ja saavat kantaa häpeänsä hautaan vaipuneiden parissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Heidät on farao näkevä ja tuleva lohdutetuksi kaikesta meluisasta joukostaan. Miekalla on surmattu farao kaikkine sotaväkineen, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Sillä levitin hänen kauhuaan elävien maassa, mutta faraolle ja kaikelle hänen meluisalle joukolleen laitetaan makuusija ympärileikkaamattomien sekaan, miekalla surmattujen pariin, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, '\"Ihmislapsi, puhu kansasi lapsille ja sano heille: Jos annan miekan tulla maan kimppuun ja maan kansa on ottanut yhden miehen joukostaan ja asettanut hänet vartijakseen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'ja jos hän näkee miekan tulevan maan kimppuun ja puhaltaa torveen ja varoittaa kansaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'ja joku kuulee torven äänen, mutta ei ota varoituksesta vaarin, ja miekka tulee ja ottaa hänet pois, niin hänen verensä tulee hänen oman päänsä päälle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'hän kuuli torven äänen, mutta ei ottanut varoituksesta vaarin; hänen verensä tulee hänen päälleen. Jos hän olisi ottanut varoituksesta vaarin, hän olisi pelastanut sielunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Jos taas vartija näkee miekan tulevan, mutta ei puhalla torveen eikä kansa saa varoitusta, ja miekka tulee ja ottaa pois jonkun sielun heistä, hänet otettiin pois synnissään, mutta hänen verensä vaadin vartijan kädestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Mutta sinä, ihmislapsi! Olen asettanut sinut Israelin heimolle vartijaksi. Kun kuulet sanan suustani, sinun on varoitettava heitä minun puolestani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Jos sanon jumalattomalle: jumalaton, sinun on kuolemalla kuoltava, mutta et puhu varoittaaksesi jumalatonta hänen tiestään, niin jumalaton kuolee synnissään, mutta hänen verensä vaadin sinun kädestäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Mutta jos varoitat jumalatonta hänen tiestään, että hän kääntyisi siltä pois, eikä hän tieltään käänny, hän kuolee synnissään, mutta sinä olet sielusi pelastanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Sinä, ihmislapsi! Sano Israelin heimolle: Näin te sanotte: \'Niin, rikoksemme ja syntimme ovat päällämme, ja riudumme niiden tähden. Kuinka voisimme pysyä elossa?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Sano heille: Niin totta kuin minä elän, sanoo Herra, Herra, minulle ei ole mieleen jumalattoman kuolema, vaan se, että jumalaton kääntyy tieltään ja elää. Kääntykää, kääntykää pois pahoilta teiltänne, ja minkä tähden te kuolisitte, Israelin heimo!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Mutta sinä, ihmislapsi! Sano kansasi lapsille: Vanhurskasta ei pelasta hänen vanhurskautensa sinä päivänä, jona hän rikkoo, ja jumalaton pääsee suistumasta turmioon jumalattomuutensa tähden sinä päivänä, jona hän kääntyy pois jumalattomuudestaan, ja vanhurskas ei voi elää vanhurskautensa turvin sinä päivänä, jona hän syntiä tekee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Jos sanon vanhurskaalle, että hän totisesti on elävä, mutta hän luottaa vanhurskauteensa ja tekee vääryyttä, hänen vanhurskauttaan ei muisteta, vaan hän kuolee vääryydessään, jota on tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Mutta jos sanon jumalattomalle, että hänen totisesti on kuoltava, mutta hän kääntyy pois synnistään ja tekee oikeuden ja vanhurskauden,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'antaa takaisin, tuo jumalaton, pantin, korvaa riistämänsä ja vaeltaa elämän käskyjen mukaan, niin ettei tee vääryyttä, totisesti hän tulee elämään, hänen ei ole kuoltava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Hänen syntejään, jotka hän on tehnyt, ei lainkaan muisteta: hän on tehnyt oikeuden ja vanhurskauden, hän totisesti on elävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Mutta vielä sinun kansasi lapset sanovat: \' Herran tie ei ole oikea.\' Juuri heidän omat tiensä eivät ole oikeat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Jos vanhurskas kääntyy pois vanhurskaudestaan ja tekee vääryyttä, hänen on sen tähden kuoltava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Jos taas jumalaton kääntyy pois jumalattomuudestaan ja tekee oikeuden ja vanhurskauden, hän on sen tähden elävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Mutta sanotte: \' Herran tie ei ole oikea\': minä tuomitsen teidät, te Israelin heimo, itse kunkin hänen teittensä mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'Kahdentenatoista karkotuksemme vuotena, kymmenennessä kuussa, kuukauden viidentenä päivänä tuli luokseni pakolainen Jerusalemista ja sanoi: \"Kaupunki on vallattu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Herran käsi oli tullut päälleni jo illalla ennen pakolaisen tuloa, ja hän avasi suuni ennen tämän tuloa aamulla. Suuni avautui, enkä enää ollut mykkänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, '\"Ihmislapsi, ne, jotka asuvat noilla raunioilla Israelin maassa, sanovat näin: \'Aabraham oli vain yksi, ja hän peri maan. Meitä on paljon, meille on annettu maa perinnöksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Sano sen tähden heille: Näin sanoo Herra, Herra: Te syötte lihaa verineen, luotte silmänne epäjumaliinne ja vuodatatte verta. Tekö perisitte maan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Seisotte miekkanne varassa, harjoitatte kauhistuksia ja saastutatte toistenne vaimoja, ja tekö perisitte maan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Näin on sinun heille sanottava: Näin sanoo Herra, Herra: Niin totta kuin minä elän, niin ne, jotka ovat raunioilla, kaatuvat miekkaan, ja ne, jotka ovat kedolla, annan eläinten syötäväksi, ja ne, jotka ovat vuorenhuipuilla ja luolissa, kuolevat ruttoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Teen maan autioksi ja hävitetyksi, ja heidän ylpeästä mahdistaan tulee loppu, ja Israelin vuoret joutuvat autioiksi, niin ettei siellä kulje kukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'He tulevat tietämään, että minä olen Herra, kun teen maan autioksi ja hävitetyksi kaikkien kauhistusten tähden, joita he ovat harjoittaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Sinä, ihmislapsi! Sinun kansasi lapset puhuvat sinusta seinänvierustoilla ja talojen ovilla ja sanovat keskenään toisilleen, näin: \'Lähtekää kuulemaan, millainen sana nyt on tullut Herralta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'He tulevat luoksesi joukoittain, istuvat edessäsi kansanani ja kuuntelevat sanojasi, mutta he eivät tee niiden mukaan, sillä he osoittavat rakkautta suullaan, mutta heidän sydämensä kulkee väärän voiton perässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Katso, sinä olet heille kuin ilolaulu, kauniisti laulettu ja hyvin soitettu. He tosin sanojasi kuuntelevat, mutta eivät tee niiden mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Mutta kun se toteutuu – ja katso, se toteutuu – he tulevat tietämään, että heidän keskuudessaan on ollut profeetta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, '\"Ihmislapsi, profetoi Israelin paimenia vastaan, profetoi ja sano heille, paimenille: Näin sanoo Herra, Herra: Voi Israelin paimenia, jotka ovat olleet itsensä paimenia! Eikö paimenten ole kaittava lampaita?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Te olette syöneet rasvat, pukeneet päällenne villat, teurastaneet lihavat; mutta lampaita ette ole kainneet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'ette ole vahvistaneet heikkoja, ette ole parantaneet sairaita, sitoneet haavoittuneita, tuoneet takaisin eksyneitä ettekä etsineet kadonneita, vaan olette vallinneet niitä tylysti ja väkivaltaisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Ne ovat hajaantuneet paimenta vailla ja joutuneet kaikkien kedon eläinten syötäviksi. Hajaantuneet ne ovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Lampaani harhailevat kaikilla vuorilla ja kaikilla korkeilla kukkuloilla. Pitkin koko maata lampaani ovat hajallaan, eikä kukaan välitä niistä eikä etsi niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Sen tähden, paimenet, kuulkaa Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Niin totta kuin minä elän, sanoo Herra, Herra, totisesti, koska lampaani ovat ryöstettävinä ja koska lampaani ovat kaikkien kedon eläinten syötävinä, kun paimenta ei ole ja kun paimeneni eivät etsi lampaitani, vaan paimeneni kaitsevat itseään, eivätkä kaitse minun lampaitani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'sen tähden, paimenet, kuulkaa Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Näin sanoo Herra, Herra: Katso, minä olen paimenia vastaan, vaadin lampaani heidän kädestään ja teen lopun heidän lammasten kaitsennastaan, eivätkä paimenet saa enää kaita itseään. Minä pelastan lampaani heidän suustaan, eivätkä ne sitten enää ole heidän syötävinään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Sillä näin sanoo Herra, Herra: Katso, minä itse etsin lampaani ja pidän niistä huolen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Niin kuin paimen pitää huolen laumastaan, kun hän on lampaittensa keskellä ja ne ovat hajallaan, niin minä pidän huolen lampaistani ja pelastan ne joka paikasta, minne ne ovat hajaantuneet pilvisenä ja pimeänä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Vien ne pois kansakuntien joukosta ja kokoan ne kaikista maista, tuon ne maahansa ja kaitsen niitä Israelin vuorilla, purojen varsilla ja kaikissa maan asuttavissa paikoissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Hyvillä laitumilla niitä kaitsen, ja Israelin korkeilla vuorilla niillä on oleva laitumensa. Siellä ne saavat levätä hyvällä laitumella, ja lihava ruokamaa niillä on oleva Israelin vuorilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Minä itse kaitsen lampaani ja vien itse ne lepäämään, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Etsin kadonneet, eksyneet tuon takaisin, haavoittuneet sidon, heikkoja vahvistan, mutta lihavat ja väkevät minä hävitän. Kaitsen niitä niin, kuin oikein on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Mutta te, minun lampaani! Näin sanoo Herra, Herra: Katso, tuomitsen lampaan ja lampaan, pässien ja vuohipukkien välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Eikö teille riitä, että olette hyvällä laitumella, kun vielä tallaatte jaloillanne loput laitumestanne, ja se, että juotte kirkasta vettä, kun vielä sekoitatte jaloillanne loput?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'Lampaani käyvät laitumella siinä, mitä jalkanne ovat tallanneet, ja juovat sitä, minkä jalkanne ovat sotkeneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Sen tähden sanoo Herra, Herra niille näin: Katso, minä, minä tuomitsen lihavan lampaan ja laihan lampaan välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Koska te sysitte kyljillänne ja hartioillanne sekä puskette sarvillanne kaikkia heikkoja, kunnes olette saaneet ne ajetuiksi ulos ja hajalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'niin pelastan lampaani, etteivät ne enää ole ryöstettävinä, ja tuomitsen lampaan ja lampaan välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'Herätän heille yhden paimenen heitä kaitsemaan, palvelijani Daavidin. Hän on kaitseva heitä ja oleva heidän paimenensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Minä, Herra, olen heidän Jumalansa, ja palvelijani Daavid on ruhtinas heidän keskellään. Minä, Herra, olen puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Teen heidän kanssaan rauhan liiton. Lopetan maasta pahat eläimet, niin että he asuvat turvallisesti erämaassa ja nukkuvat metsiköissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Teen siunatuiksi heidät ja kaiken, mitä on kukkulani ympärillä, ja vuodatan sateen ajallaan. Ne ovat siunauksen sateita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Kedon puut kantavat hedelmänsä, ja maa antaa satonsa, ja he saavat olla turvassa maassaan. He tulevat tietämään, että minä olen Herra, kun särjen heidän ikeensä puut ja pelastan heidät heidän orjuuttajiensa käsistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Eivätkä he enää ole pakanoiden ryöstettävinä, eivätkä maan eläimet heitä syö, vaan he asuvat turvassa, kenenkään pelottelematta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Annan nousta heille istutuksen, joka on oleva kunniaksi, niin etteivät he menehdy siinä maassa nälkään eivätkä enää kärsi pakanoiden pilkkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'He tulevat tietämään, että minä, Herra, heidän Jumalansa, olen heidän kanssaan ja että he, Israelin heimo, ovat kansani, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Te olette lampaani, laitumeni lampaat, te ihmiset. Minä olen Jumalanne, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, '\"Ihmislapsi, käännä kasvosi Seirin vuorta kohti ja profetoi sitä vastaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'ja sano sille: Näin sanoo Herra, Herra: Katso, minä käyn kimppuusi, Seirin vuori, ojennan käteni sinua vastaan ja teen sinut autioksi ja hävitetyksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Kaupunkisi teen raunioiksi ja sinä itse tulet autioksi. Tulet tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Koska pidit ikuista vihaa ja annoit israelilaiset alttiiksi miekalle heidän onnettomuutensa aikana, aikana, jolloin syntivelka tuli viimeiseen määräänsä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'sen tähden, niin totta kuin minä elän, sanoo Herra, Herra, teen sinut verta vuotavaksi, ja veri on sinua vainoava. Koska totisesti et kammonnut verta, veri on vainoava sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Teen Seirin vuoren tyhjäksi ja autioksi ja hävitän sieltä menijän ja tulijan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Sen vuoret täytän sen surmatuilla. Miekalla surmattuja kaatuu kukkuloillasi ja laaksoissasi ja kaikilla purojesi varsilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Teen sinut ikuisesti autioksi, ja kaupunkisi jäävät asumattomiksi. Tulette tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Koska sinä olet sanonut: \'Ne kaksi kansaa ja kaksi maata ovat minun, otamme ne omiksemme\', vaikka siellä on Herra,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'sen tähden, niin totta kuin minä elän, sanoo Herra, Herra, teen vihasi ja kiivautesi mukaan, teen sen, minkä sinä vihassasi olet heille tehnyt. Teen itseni heille tunnetuksi, kun tuomitsen sinut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'ja sinä tulet tietämään, että minä olen Herra. Olen kuullut kaikki pilkkaamisesi, jotka olet puhunut Israelin vuoria vastaan, kun olet sanonut: \'Ne ovat autioina, ne ovat annetut meille syötäviksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Te suurentelitte minua vastaan suullanne, ja ylenpalttiset olivat teidän puheenne minua vastaan. Olen ne kuullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Näin sanoo Herra, Herra: Iloksi kaikelle maalle teen sinut autioksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Niin kuin iloitsit Israelin heimon perintöosasta, kun se tuli autioksi, niin teen minäkin sinulle. Autioksi tulet sinä, Seirin vuori, samoin koko Edom kaikkineen. He tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, '\"Sinä, ihmislapsi, profetoi Israelin vuorista ja sano:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Israelin vuoret, kuulkaa Herran sana: Näin sanoo Herra, Herra: Koska vihollinen on sanonut teistä: \'Kas noin!\' ja: \'Ikuiset kukkulat ovat tulleet omistukseemme\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'sen tähden profetoi ja sano: Näin sanoo Herra, Herra: Koska – niin, koska teitä on hävitetty ja poljettu joka taholta, että joutuisitte muiden kansojen omaisuudeksi, ja koska olette joutuneet pahojen kielten ja kansan panettelun alaisiksi, –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'sen tähden, Israelin vuoret, kuulkaa Herran, Herran sana: Näin sanoo Herra, Herra vuorille ja kukkuloille, puronvarsille ja laaksoille, autioille raunioille ja hylätyille kaupungeille, jotka ovat joutuneet saaliiksi ja pilkaksi muille kansoille, mitä ympärillä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'Sen tähden sanoo Herra, Herra näin: Totisesti, kiivauteni tulessa puhun muita kansoja vastaan ja koko Edomia vastaan, jotka ovat kaikesta sydämestään iloiten ja sielu täynnä halveksuntaa ottaneet omakseen maani karkottaakseen siitä ihmiset ja ryöstääkseen sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Sen tähden profetoi Israelin maasta ja sano vuorille ja kukkuloille, puronvarsille ja laaksoille: Näin sanoo Herra, Herra: Katso, puhun kiivaudessani ja vihassani, koska teidän täytyy kärsiä pakanoiden pilkkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Sen tähden, näin sanoo Herra, Herra: Minä kohotan käteni. Totisesti pakanakansat ympärillänne itse kärsivät oman pilkkansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Mutta te, Israelin vuoret, teette lehvänne ja kannatte hedelmänne kansalleni Israelille, sillä he ovat aivan lähellä tulossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Sillä katso, tulen luoksenne ja käännyn puoleenne, ja teidät viljellään ja teihin kylvetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'Lisään teille ihmisiä runsaasti – koko Israelin heimolle kokonaan – ja kaupungit asutetaan ja rauniot rakennetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Lisään teille ihmisiä ja karjaa runsaasti, ja ne lisääntyvät ja ovat hedelmälliset. Teen teidät asutuiksi, niin kuin olitte entisinä päivinänne, ja teen hyvää vielä enemmän kuin alkuaikoina. Tulette tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Tuon luoksenne, kansaani Israeliin, ihmisiä, ja he ottavat sinut omakseen, ja tulet heille perintöosaksi, etkä enää tästä lähin riistä heidän lapsiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Näin sanoo Herra, Herra: Koska teille on sanottu: \'Sinä olet ihmissyöjä ja oman kansasi lasten riistäjä\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'sen tähden et ole enää syövä ihmisiä etkä enää riistävä lapsia omalta kansaltasi, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Enkä enää anna sinun joutua kuulemaan pakanakansojen pilkkaa, etkä kärsi kansojen herjauksia, etkä enää myöskään pane omaa kansaasi kompastumaan, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, '\"Ihmislapsi, kun Israelin heimo asui maassaan, he saastuttivat sen vaelluksellaan ja teoillaan. Heidän vaelluksensa oli edessäni kuin kuukautistilan saastaisuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Vuodatin kiivauteni heidän päälleen veren tähden, jota he olivat vuodattaneet maassa, ja heidän epäjumaliensa tähden, joilla he olivat sen saastuttaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'Hajotin heidät pakanakansojen sekaan, ja heidät siroteltiin kaikkiin maihin. Vaelluksensa ja tekojensa mukaan heidät tuomitsin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'He tulivat pakanakansojen sekaan. Minne tulivatkin, he häpäisivät pyhän nimeni, kun heistä sanottiin: \'Nämä ovat Herran kansa, mutta he ovat lähteneet pois hänen maastaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Minun tuli sääli pyhää nimeäni, jonka Israelin heimo saastutti pakanakansojen seassa, minne tulivatkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Sen tähden sano Israelin heimolle: Näin sanoo Herra, Herra: Minä en tee teidän tähtenne, Israelin heimo, sitä minkä teen, vaan oman pyhän nimeni tähden, jonka olette häväisseet pakanakansojen seassa, minne tulittekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Pyhitän suuren nimeni, joka on häväisty pakanakansojen keskuudessa, jonka olette häväisseet heidän keskellään. Pakanakansat tulevat tietämään, että minä olen Herra, sanoo Herra, Herra, kun osoitan teissä pyhyyteni heidän silmiensä edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Otan teidät pois pakanakansoista ja kokoan teidät kaikista maista ja tuon teidät maahanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Vihmon päällenne puhdasta vettä, niin että puhdistutte. Kaikista saastaisuuksistanne ja kaikista epäjumalistanne teidät puhdistan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Annan teille uuden sydämen, ja uuden Hengen annan teidän sisimpäänne. Poistan ruumiistanne kivisydämen ja annan teille lihasydämen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Henkeni annan sisimpäänne ja vaikutan sen, että vaellatte käskyjeni mukaan, noudatatte oikeuksiani ja pidätte ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Asutte maassa, jonka annoin teidän isillenne, ja olette kansani, ja minä olen Jumalanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Vapautan teidät kaikista saastaisuuksistanne. Kutsun esiin viljan ja teen sen runsaaksi enkä anna teille nälänhätää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Teen runsaaksi puiden hedelmän ja pellon sadon, niin ettette enää tule herjatuiksi kansojen seassa nälän takia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Muistatte väärät tienne ja tekonne, jotka eivät olleet hyvät, ja teitä inhottaa oma itsenne rikostenne ja kauhistustenne tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'En tee sitä teidän tähtenne, sanoo Herra, Herra. Se olkoon teille tiettävä. Hävetkää ja punastukaa vaelluksenne tähden, te Israelin heimo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Näin sanoo Herra, Herra: Sinä päivänä, jona teidät puhdistan kaikista pahoista teoistanne, asutan kaupungit, ja rauniot rakennetaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'ja autiomaa viljellään, sen sijaan että se on ollut autiona jokaisen ohikulkijan silmien edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'Silloin sanotaan: \'Tästä maasta, joka oli autiona, on tullut kuin Eedenin puutarha. Raunioina olleet, autiot ja maahan revityt kaupungit ovat varustettuja ja asuttuja.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Pakanakansat tulevat, joita on jäljellä ympärillänne, tietämään, että minä, Herra, rakennan jälleen alasrevityn ja istutan aution: minä, Herra, olen puhunut, ja minä teen sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Näin sanoo Herra, Herra: Vielä tätäkin annan Israelin heimon minulta anoa, että tekisin heille sen. Lisään heille ihmisiä runsaasti kuin lammaslaumaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Niin kuin on pyhitettyjen uhrilammasten laumaa, niin kuin on Jerusalemin lammaslaumaa sen kokouksissa, niin tulevat raunioina olleet kaupungit täyteen ihmislaumoja. He tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Herran käsi oli päälläni ja vei minut pois Herran Hengessä ja laski minut keskelle laaksoa, joka oli täynnä luita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'Hän kuljetti minua ympäriinsä niiden ohi, ja katso, niitä oli hyvin paljon laaksossa maan päällä, ja katso, ne olivat hyvin kuivia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Hän sanoi minulle: \"Ihmislapsi, voivatkohan nämä luut tulla eläviksi?\" Mutta minä sanoin: \"Herra, Herra, sinä sen tiedät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Niin hän sanoi minulle: \"Profetoi näistä luista ja sano niille: Kuivat luut, kuulkaa Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Näin sanoo Herra, Herra näille luille: Katso, minä annan tulla teihin hengen, ja te tulette eläviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'Panen teihin jänteet, kasvatan teihin lihan, vedän yllenne nahan ja annan teihin hengen, ja te tulette eläviksi. Tulette tietämään, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Sitten lausuin profetian, kuten minua oli käsketty. Kuului ääni, kun profetoin. Katso, järinää, ja luut lähestyivät toisiaan, luu luuta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Näin, ja katso: niihin tulivat jänteet ja kasvoi liha, ja niiden päälle kasvoi nahka, mutta henkeä niissä ei ollut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Hän sanoi minulle: \"Profetoi Hengestä, profetoi, ihmislapsi, ja sano Hengelle: Näin sanoo Herra, Herra: Tule, Henki, neljästä tuulesta ja puhalla näihin surmattuihin, että ne tulisivat eläviksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Profetoin, niin kuten hän oli minua käskenyt, ja niihin tuli henki, ja ne tulivat eläviksi ja nousivat ylös jaloilleen. Niitä oli tavattoman suuri joukko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Hän sanoi minulle: \"Ihmislapsi, nämä luut ovat koko Israelin heimo. Katso, he sanovat: \'Meidän luumme ovat kuivettuneet, toivomme on mennyttä, olemme hukassa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Sen tähden profetoi ja sano heille: Näin sanoo Herra, Herra: Katso, minä avaan hautanne ja nostan teidät, kansani, ylös haudoistanne ja vien teidät Israelin maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'Siitä te tulette tietämään, että minä olen Herra, kun minä avaan hautanne ja nostan teidät, kansani, ylös haudoistanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Annan teihin Henkeni, niin että te tulette eläviksi, ja sijoitan teidät maahanne. Te tulette tietämään, että minä olen Herra. Olen puhunut, ja sen teen, sanoo Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, '\"Sinä, ihmislapsi, ota puusauva ja kirjoita siihen: \'Juudalle ja häneen liittyneille israelilaisille.\' Ota sitten toinen puusauva ja kirjoita siihen: \'Joosefille; Efraimin ja kaiken häneen liittyneen Israelin heimon sauva.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Yhdistä ne toisiinsa, niin että ne tulevat yhdeksi kädessäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'Kun sitten kansasi lapset sanovat sinulle näin: \'Etkö ilmoita meille, mitä tällä tarkoitat?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'puhu heille: Näin sanoo Herra, Herra: Katso, minä otan Joosefin sauvan, joka on Efraimin kädessä, ja häneen liittyneet Israelin sukukunnat, ja asetan ne yhteen Juudan sauvan kanssa ja teen niistä yhden sauvan, niin että ne tulevat yhdeksi minun kädessäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Kun sauvat, joihin olet kirjoittanut, ovat kädessäsi, heidän silmiensä edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'puhu heille: Näin sanoo Herra, Herra: Katso, minä otan israelilaiset pois pakanoiden keskuudesta, minne vain he ovat kulkeneet, kokoan heidät joka taholta ja tuon heidät maahansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'Teen heidät yhdeksi kansaksi siinä maassa, Israelin vuorilla, ja yksi kuningas on oleva kuninkaana heillä kaikilla. Eivätkä he enää ole kahtena kansana eivätkä enää jakaantuneina kahdeksi valtakunnaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'He eivät myöskään enää saastuta itseään epäjumalillaan, iljetyksillään eivätkä millään rikoksillaan, vaan pelastan heidät heidän kaikista asuinpaikoistaan, joissa he ovat syntiä tehneet, ja puhdistan heidät. He ovat kansani, ja minä olen heidän Jumalansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Palvelijani Daavid on oleva heidän kuninkaansa, ja heillä kaikilla on oleva yksi paimen. Silloin he vaeltavat oikeuksieni mukaan ja noudattavat käskyjäni ja pitävät ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'He asuvat maassa, jonka annoin palvelijalleni Jaakobille ja jossa teidän isänne ovat asuneet. He, heidän lapsensa ja lastensa lapset asuvat siinä iankaikkisesti, ja palvelijani Daavid on oleva heidän ruhtinaansa iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Teen heidän kanssaan rauhan liiton – se on oleva iankaikkinen liitto heidän kanssaan – istutan ja runsaasti kartutan heidät ja asetan pyhäkköni olemaan heidän keskellään iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Asumukseni on oleva heidän luonaan, ja olen heidän Jumalansa, ja he ovat kansani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'Pakanat tulevat tietämään, että minä olen Herra, joka pyhitän Israelin, kun pyhäkköni on heidän keskellään iankaikkisesti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'Minulle tuli tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, '\"Ihmislapsi, käännä kasvosi kohti Googia Maagogin maassa, Roosin, Mesekin ja Tuubalin ruhtinasta, ja profetoi häntä vastaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'ja sano: Näin sanoo Herra, Herra: Katso, käyn kimppuusi, Goog, sinä Roosin, Mesekin ja Tuubalin ruhtinas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Kuljetan sinua, panen koukut leukaasi ja nostatan sotaan sinut ja kaiken sotaväkesi: hevoset ja ratsumiehet, kaikki loisteliaasti puettuja, suuren joukon suurine ja pienine kilpineen, miekankantajia kaikki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Persia, Kuus ja Puut ovat heidän kanssaan, heillä kaikilla on kilvet ja kypärät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Goomer ja kaikki sen sotajoukot, Toogarman heimo pohjoisesta ja kaikki sen sotajoukot – lukuisat kansat ovat kanssasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Ole valmis, varustaudu, sinä ja kaikki joukkosi, jotka ovat kokoontuneet luoksesi, ja ole sinä niiden vartija.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Monien päivien jälkeen saat määräyksen tulla vuosien lopulla maahan, joka on palautunut miekan jäljiltä ja koottu monien kansojen seasta, – mennä Israelin vuorille, jotka kauan aikaa ovat olleet raunioina. Se on tuotu pois kansojen seasta, ja he kaikki asuvat turvassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Käyt päälle kuin rajuilma ja tulet kuin pilvi peittääksesi maan, sinä ja kaikki sotajoukkosi ja lukuisat kansat, jotka ovat kanssasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Näin sanoo Herra, Herra: Mutta sinä päivänä nousee mieleesi jotakin, ja mietit pahan juonen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'ja sanot: Hyökkään avoimeen maahan, käyn rauhallisten ihmisten kimppuun, jotka asuvat turvallisina – asuvat ilman muuria kaikki tyynni, ja joilla ei ole salpoja eikä ovia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'Etsit saalista ja ryöstettävää sekä ojennat kätesi raunioita kohti, jotka on saatu asutuiksi, ja kansaa kohti, joka on koottu pakanoiden seasta, joka on hankkinut karjaa ja omaisuutta ja asuu keskellä maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Saba ja Dedan ja Tarsiin kauppiaat ja kaikki heidän nuoret leijonansa kyselevät sinulta: \'Oletko sinä menossa saalista saamaan, ryöstettävää ryöstämään? Oletko koonnut joukkosi kantamaan hopeaa ja kultaa, ottamaan karjaa ja omaisuutta, saamaan suurta saalista?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Sen tähden profetoi, ihmislapsi, ja sano Googille: Näin sanoo Herra, Herra: Eikö niin? Sinä päivänä sinä huomaat, että kansani Israel asuu turvassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'ja lähdet asuinpaikastasi pohjoisesta, sinä ja monet kansat kanssasi, jotka kaikki ratsastavat hevosilla: suuri joukko, monilukuinen sotajoukko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'Hyökkäät kansani Israelin kimppuun kuin pilvi peittääksesi maan. Päivien lopulla tämä tapahtuu. Annan sinun karata maahani, että pakanakansat tulisivat tuntemaan minut, kun osoitan pyhyyteni sinussa, Goog, heidän silmiensä edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Näin sanoo Herra, Herra: Etkö se ole sinä, josta muinaisina päivinä puhuin palvelijoitteni, Israelin profeettojen, kautta, jotka niinä päivinä profetoivat vuodesta toiseen, että annan sinun käydä heidän kimppuunsa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Mutta sinä päivänä, jona Goog menee Israelin maahan, sanoo Herra, Herra, nousee vihani hehku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Kiivaudessani, vihani tulessa sanon: Totisesti sinä päivänä tulee suuri maanjäristys Israelin maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'Minun edessäni vapisevat meren kalat ja taivaan linnut ja kedon eläimet ja kaikki maassa liikkuvat matelijat ja kaikki ihmiset, jotka maan pinnalla ovat. Vuoret luhistuvat, ja vuorenrinteet sortuvat, ja kaikki muurit sortuvat maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Kutsun häntä vastaan kaikille vuorilleni miekan, sanoo Herra, Herra. Toisen miekka on oleva toista vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Käyn oikeutta hänen kanssaan rutolla ja verellä. Annan sataa kaatosadetta, raekiviä, tulta ja laavaa hänen päälleen, hänen sotajoukkojensa päälle ja lukuisten kansojen päälle, jotka ovat hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Osoitan suuruuteni ja pyhyyteni sekä teen itseni tunnetuksi monien pakanakansojen silmien edessä. He tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, '\"Sinä, ihmislapsi, profetoi Googia vastaan ja sano: Näin sanoo Herra, Herra: Katso, tulen luoksesi, Goog, sinä Roosin, Mesekin ja Tuubalin ruhtinas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Tuon sinut, talutan sinua, nostatan sinut pohjoisen puolelta ja annan sinun tulla Israelin vuorille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Mutta lyön pois jousesi vasemmasta kädestäsi ja pudotan nuolesi oikeasta kädestäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Israelin vuorille sinä olet kaatuva, samoin kaikki sotajoukkosi ja kansat, jotka ovat kanssasi: annan sinut ruuaksi petolinnuille, kaikille siivekkäille ja kedon eläimille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Kedolle sinä kaadut. Sillä minä olen puhunut, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Lähetän tulen Maagogiin ja rannikolla turvassa asuvien keskuuteen. Silloin he tulevat tietämään, että minä olen Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Pyhän nimeni teen tunnetuksi kansani Israelin keskuudessa enkä enää salli häväistä pyhää nimeäni. Pakanat tulevat tietämään, että minä olen Herra, Israelin Pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Katso, se tulee, se tapahtuu, sanoo Herra, Herra. Se tapahtuu sinä päivänä, josta olen puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Israelin kaupunkien asukkaat menevät ulos ja sytyttävät ja polttavat aseita, pieniä ja suuria kilpiä, jousia, nuolia, nuijia ja keihäitä. He pitävät niitä polttopuina seitsemän vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'He eivät kanna puita kedolta eivätkä hakkaa metsistä, vaan pitävät polttopuinaan aseita. Näin he saalistavat saalistajiaan ja ryöstävät ryöstäjiään, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'Sinä päivänä annan Googille siellä, Israelissa, hautapaikan, \'Kulkijain laakson\', itää kohden merestä. Se sulkee tien noilta kulkijoilta. Sinne haudataan Goog ja koko hänen meluisa joukkonsa, ja sille pannaan nimeksi: \'Googin meluisan joukon laakso.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Israelin heimo hautaa heitä seitsemän kuukautta puhdistaakseen maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'Koko maan kansa hautaa heitä, ja se on koituva heille kiitokseksi sinä päivänä, jona näytän kunniani, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'Valitaan vakinaiset miehet, jotka kulkevat maata ja hautaavat noita kulkijoita, mitä heitä vielä on jäljellä maan pinnalla, puhdistaakseen sen. Seitsemässä kuukaudessa he saavat sen tutkituksi läpikotaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Kun nämä kulkijat kulkevat maata ja joku heistä näkee ihmisen luut, hän panee niille kiven merkiksi, siihen asti kunnes haudankaivajat ovat ne haudanneet \'Googin meluisan joukon laaksoon.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Erään kaupungin nimenäkin on Hamona. – Niin he puhdistavat maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Mutta sinä, ihmislapsi! Näin sanoo Herra, Herra: Käske lintuja, kaikkia siivekkäitä, ja kaikkia kedon eläimiä: Kokoontukaa, tulkaa, yhtykää joka taholta teurasuhrilleni, jonka teitä varten uhraan, suurelle teurasuhrille Israelin vuorille. Syökää lihaa ja juokaa verta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Syökää sankarien lihaa ja juokaa maan ruhtinaiden verta – pässejä, lampaita, vuohia ja härkiä, kaikki Baasanissa syötettyjä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Syökää itsenne kylläisiksi rasvasta ja juokaa itsenne juovuksiin verestä, teurasuhrista, jonka teitä varten uhraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Tulkaa kylläisiksi pöydässäni ratsuista ja vaunuhevosista, sankareista ja kaikenlaisista sotamiehistä, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'Asetan kunniani pakanoiden keskuuteen, ja kaikki pakanakansat saavat nähdä tuomioni, jonka panen toimeen, ja käteni, jonka lasken heidän päälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'Mutta Israelin heimo tulee tietämään, että minä, Herra, olen heidän Jumalansa siitä päivästä lähtien ja aina eteenpäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'Pakanakansat tulevat tietämään, että Israelin heimo joutui karkotukseen syntivelkansa tähden, koska olivat olleet minulle uskottomat, ja kätkin heiltä kasvoni, ja annoin heidät heidän vihollistensa käsiin, ja he kaikki kaatuivat miekkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Tein heille heidän saastaisuutensa ja rikostensa mukaan ja kätkin heiltä kasvoni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Sen tähden, näin sanoo Herra, Herra: Nyt käännän Jaakobin kohtalon ja armahdan kaikkea Israelin heimoa ja kiivailen pyhän nimeni puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Häpeänsä ja kaiken uskottomuutensa, jota he ovat minulle osoittaneet, he kantavat asuessaan nyt turvassa maassaan kenenkään pelottelematta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Kun tuon heidät takaisin kansojen seasta ja kokoan heidät heidän vihamiestensä maista, niin osoitan heissä pyhyyteni monien pakanakansojen silmien edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'He tulevat tietämään, että minä, Herra, olen heidän Jumalansa, kun minä vietyäni heidät karkotukseen pakanoiden keskuuteen kokoan heidät maahansa, en jätä niihin jäljelle ainoatakaan heistä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'enkä enää kätke heiltä kasvojani, sillä vuodatan Henkeni Israelin heimon päälle, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'Meidän karkotuksemme kahdentenakymmenentenä viidentenä vuotena, vuoden alussa, kuukauden kymmenentenä päivänä, neljäntenätoista vuotena kaupungin valloituksen jälkeen, juuri sinä päivänä tuli minun päälleni Herran käsi, ja hän vei minut sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'Jumalan näyissä hän vei minut Israelin maahan ja laski minut hyvin korkealle vuorelle, jolla oli ikään kuin kaupunki rakennettuna etelään päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Hän vei minut sinne. Katso, oli mies, näöltään vasken kaltainen, ja pellavanuora oli hänellä kädessä sekä mittaruoko, ja hän seisoi portilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Mies puhui minulle: \"Ihmislapsi, katso silmilläsi, kuule korvillasi ja ota huomioosi kaikki, mitä minä sinulle näytän. Sitä varten näet sinut on tuotu tänne, että nämä sinulle näytettäisiin. Ilmoita kaikki, mitä näet, Israelin heimolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Katso, temppelin ulkopuolella sen ympäri oli muuri. Miehen kädessä oli mittaruoko, kuusikyynäräinen, kyynärään luettuna kyynärä ja kämmenenleveys. Hän mittasi muurirakennuksen leveyden, joka oli yksi ruoko, ja korkeuden, joka oli yksi ruoko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Hän meni portille, jonka etupuoli oli itää kohden, nousi ylös sen portaita ja mittasi portin kynnyksen: se oli yhden ruovon levyinen. Ensimmäinen kynnys oli yhden ruovon levyinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'Sivuhuone oli aina yhden ruovon pituinen ja yhden ruovon levyinen, ja sivuhuoneiden väliä oli viisi kyynärää. Portin kynnys porttieteisen laidassa, sisäpuolella oli yksi ruoko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Hän mittasi porttieteisen, joka oli sisäpuolella. Se oli yksi ruoko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Hän mittasi porttieteisen, joka oli kahdeksan kyynärää, ja sen pilasterit, jotka olivat kaksi kyynärää. Porttieteinen oli sisemmällä puolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Itää kohden antavan portin sivuhuoneita oli kolme kummallakin puolella. Ne kolme olivat yhtä suuria, ja niiden pilasterit kummallakin puolella olivat yhtä suuria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Hän mittasi portin oviaukon leveyden, joka oli kymmenen kyynärää, ja portin pituuden, joka oli kolmetoista kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Mutta sivuhuoneiden edessä oli aitaus, joka oli yhden kyynärän korkuinen, samoin toisella puolella oleva aitaus oli yhden kyynärän korkuinen, ja kukin sivuhuone kummallakin puolella oli suuntaansa kuusi kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Hän mittasi portin, sivuhuoneen katosta toisen kattoon: leveys oli kaksikymmentä viisi kyynärää, ovelta ovelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Hän otti mitan pilasterista: kaksikymmentä kyynärää. Seinän pilastereihin ulottui esipiha portin ympärillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'Sisäänkäyntiportin edestä sisäportin eteisen eteen oli viisikymmentä kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Portissa oli sisäänpäin ympäriinsä sivuhuoneisiin ja niiden seinien pilastereihin päin ikkuna-aukkoja, samoin eteisissä. Ikkuna-aukot ympäriinsä laajenivat sisäänpäin. Seinien pilastereissa oli palmukoristeita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Sitten hän vei minut ulompaan esipihaan. Katso: ympäri esipihan oli kammioita ja kivillä päällystetty lattia. Kivillä päällystetyn lattian laidassa oli kolmekymmentä kammiota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Kivillä päällystetty lattia oli porttien sivuseinillä, porttien pituuden mukaisesti. Tämä oli alempi kivillä päällystetty lattia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Hän mittasi leveyden alemman portin edestä sisemmän esipihan edustalle, sen ulkopuolelle: sata kyynärää sekä itä- että pohjoispuolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Hän mittasi sen portin pituuden ja leveyden, jonka etupuoli oli pohjoista kohden ja joka vei ulompaan esipihaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'Siinä oli kolme sivuhuonetta kummallakin puolella, ja sen pilasterit ja eteinen olivat yhtä suuret kuin ensimmäisessä portissa. Sen pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Sen ikkunat, eteinen ja palmukoristeet olivat yhtä suuret kuin portin, jonka etupuoli oli itää kohden, ja sinne noustiin seitsemää porrasta, ja niistä eteenpäin oli sen eteinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Sisemmällä esipihalla oli portit vastakkain pohjoista ja itää kohden. Hän mittasi portista porttiin: sata kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Hän kuljetti minua etelää kohden, ja katso, tuli portti, joka antoi etelään. Hän mittasi sen pilasterit ja eteisen: ne olivat yhtä suuret kuin nuo toiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'Siinä ja sen eteisessä oli ikkuna-aukkoja ympäriinsä, samanlaisia kuin nuo toiset ikkuna-aukot. Pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Sen ylös menevässä käytävässä oli seitsemän porrasta, ja niistä eteenpäin oli sen eteinen. Siinä oli palmukoristeet, yksi kummallakin puolella, sen pilastereissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Sisemmässä esipihassa oli portti etelää kohden. Hän mittasi portista porttiin etelää kohden: sata kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Sitten hän vei minut sisempään esipihaan eteläportin kautta. Hän mittasi eteläportin. Se oli yhtä suuri kuin nuo toiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'Sen sivuhuoneet, pilasterit ja eteinen olivat yhtä suuret kuin nuo toiset. Siinä ja sen eteisessä oli ikkuna-aukkoja ympäriinsä. Pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Eteisiä oli ympäriinsä. Niiden pituus oli kaksikymmentä viisi kyynärää, leveys viisi kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Sen eteinen oli ulompaan esipihaan päin, ja sen pilastereissa oli palmukoristeita. Sen portaissa oli kahdeksan porrasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Hän vei minut sisempään esipihaan itää kohden. Hän mittasi portin. Se oli yhtä suuri kuin nuo toiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Sen sivuhuoneet, pilasterit ja eteinen olivat yhtä suuret kuin nuo toiset. Siinä ja sen eteisessä oli ikkuna-aukkoja ympäriinsä. Pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Sen eteinen oli ulompaan esipihaan päin, ja sen pilastereissa oli palmukoristeita kummallakin puolella. Sen portaissa oli kahdeksan porrasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Sitten hän vei minut pohjoisportille ja mittasi. Yhtä suuret kuin nuo toiset');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'olivat sen sivuhuoneet, pilasterit ja eteinen. Ikkuna-aukkoja oli siinä ympäriinsä. Pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Sen eteinen oli ulompaan esipihaan päin, ja sen pilastereissa oli palmukoristeita kummallakin puolella. Sen portaissa oli kahdeksan porrasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Sitten oli kammio, jonka ovi oli pilastereissa, porteissa. Siellä oli polttouhri huuhdottava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'Portin eteisessä oli kaksi pöytää kummallakin puolella. Niillä oli polttouhri, syntiuhri ja vikauhri teurastettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Ulkopuolisella sivuseinällä, portin ovelle noustaessa, pohjoispuolella, oli kaksi pöytää, samoin porttieteisen toisella sivuseinällä kaksi pöytää:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'neljä pöytää portin sivuseinillä kummallakin puolella, siis kahdeksan pöytää. Niillä oli teurastettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Ylös johtavan käytävän ääressä oli neljä pöytää hakatuista kivistä. Ne olivat puolentoista kyynärän pituisia, puolentoista kyynärän levyisiä ja yhden kyynärän korkuisia. Niille oli laskettava ne välineet, joilla teurastettiin polttouhri ja teurasuhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Haarukkakoukkuja, yhden kämmenenleveyden pituisia, oli kiinnitetty ympäri huonetta, mutta uhriliha pantiin pöydille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Sisemmän portin ulkopuolella oli kaksi huonetta sisemmässä esipihassa, toinen pohjoisen portin sivuseinällä, etupuoli etelää kohden, ja toinen eteläisen portin sivuseinällä, etupuoli pohjoista kohden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Hän puhui minulle: \"Tämä huone, jonka etupuoli on etelää kohden, on pappeja varten, jotka hoitavat temppelitehtäviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'Huone, jonka etupuoli on pohjoista kohden, on pappeja varten, jotka hoitavat alttaritehtäviä. Heitä ovat Saadokin jälkeläiset, ne leeviläisistä, jotka saavat lähestyä Herraa häntä palvellakseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'Hän mittasi esipihan: pituus oli sata kyynärää ja leveys sata kyynärää. Se oli neliön muotoinen. Alttari oli temppelin edustalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Hän vei minut temppelin eteiseen ja mittasi eteisen pilasterin: viisi kyynärää kummallakin puolella, ja portin leveyden: kolme kyynärää kummallakin puolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'Eteisen pituus oli kaksikymmentä kyynärää ja leveys yksitoista kyynärää. Sinne noustiin kymmentä porrasta. Pilastereiden ääressä oli pylväät, yksi kummallakin puolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Hän vei minut temppelisaliin ja mittasi pilasterit. Ne olivat kuusi kyynärää leveitä kummallakin puolella: ilmestysmajan leveys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'Oviaukko oli kymmenen kyynärää leveä, ja oviaukon sivuseinät kummallakin puolella olivat viisi kyynärää. Hän mittasi temppelisalin pituuden: neljäkymmentä kyynärää, ja leveyden: kaksikymmentä kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Hän meni sisimpään ja mittasi oviaukon pilasterin: kaksi kyynärää, oviaukon: kuusi kyynärää, ja oviaukon leveyden: seitsemän kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Hän mittasi sen pituuden, joka oli kaksikymmentä kyynärää, ja leveyden: kaksikymmentä kyynärää temppelisalin puolelta. Hän sanoi minulle: \"Tämä on kaikkeinpyhin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Sitten hän mittasi temppelin seinän: kuusi kyynärää, ja sivukammion leveyden, joka oli neljä kyynärää, yltympäri temppelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Sivukammioita oli: kolme sivukammiota päällekkäin, kolmeenkymmeneen kertaan. Ne kulkivat ympäri sen temppeliseinän varassa, joka oli sivukammioihin päin, niin että pysyivät siinä kiinni, mutta ne eivät olleet kiinnitetyt temppeliseinän sisään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Sivukammiot olivat aina sitä leveämpiä kiertäessään, mitä ylempänä ne olivat, sillä temppelin ympäryskammiot ulottuivat ylemmäksi ja ylemmäksi ympäri temppelin, ollen siten ylhäällä leveämmät sisäänpäin. Alakerrasta noustiin yläkertaan keskikerroksen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Näin, että temppelillä oli koroke ympäriinsä: sivukammioiden perustukset, koko ruovon korkuiset, kuusi kyynärää, reunustaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Sivukammioiden ulkoseinän paksuus oli viisi kyynärää; yhtä leveä oli avoin tila sivukammiorakennuksen ääressä, joka kuului temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'Välimatkaa pihakammiorakennuksiin oli kaksikymmentä kyynärää leveälti ympäri temppelin – yltympäri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Sivukammioista vei ovi avoimeen tilaan: yksi ovi pohjoista kohden ja toinen ovi etelää kohden. Avoimen tilan leveys oli viisi kyynärää yltympäri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Rakennus, joka oli eristetyn alueen laidassa lännen puoleisella sivulla, oli seitsemänkymmentä kyynärää leveä. Rakennuksen seinän paksuus oli viisi kyynärää, ympäriinsä, ja sen pituus oli yhdeksänkymmentä kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Hän mittasi temppelin: pituus oli sata kyynärää, sekä eristetyn alueen ja rakennuksen seinineen: pituus sata kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'Temppelin etupuolen ja eristetyn alueen leveys itään päin oli sata kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Sitten hän mittasi sen rakennuksen pituuden, joka oli eristetyn alueen laidassa, sen takana, sekä sen käytävät, kummallakin puolella: sata kyynärää; ja sisemmän temppelisalin, esipihan eteiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'kynnykset, sisäänpäin avartuvat ikkunat, käytävät niiden kolmen ympärillä – kynnyksen edessä oli puulaudoitus yltympäri – ja välin maasta ikkuna-aukkoihin. Ikkuna-aukot olivat peitetyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Oviaukkojen yläpuolelta lähtien sekä sisempään temppeliin asti että ulos asti, koko seinällä yltympäri, sisä- ja ulkopuolella, olivat mitatut alat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'ja niihin oli tehty kerubeja ja palmuja, palmu aina kahden kerubin väliin. Kullakin kerubilla oli kahdet kasvot:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'ihmisen kasvot palmuun päin toisaalle ja leijonan kasvot palmuun päin toisaalle. Niin oli tehty koko temppelissä yltympäri:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'maasta alkaen ja aina oviaukkojen yläpuolelle oli tehty kerubeja ja palmuja, samoin temppelisalin seinälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Temppelisalissa oli nelikulmaiset ovenpielet. Mutta pyhimmän edessä näkyi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'ikään kuin alttari, puinen, kolme kyynärää korkea, ja sen pituus oli kaksi kyynärää. Siinä oli nurkkaukset, ja sen jalusta ja seinät olivat puuta. Hän sanoi minulle: \"Tämä on pöytä, joka on Herran edessä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Sekä temppelisalissa että pyhimmässä oli kaksoisovet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'Ovissa oli kaksi ovipuoliskoa, kaksi kääntyvää ovipuoliskoa: kumpaisessakin ovessa oli kaksi ovipuoliskoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Niihin, temppelisalin oviin, oli tehty kerubeja ja palmuja, samoin kuin oli tehty seiniin. Ulkona, eteisen edessä, oli puinen porraskatos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Eteisen sivuseinissä, kummallakin puolella, oli sisäänpäin avartuvia ikkuna-aukkoja ja palmuja, samoin temppelin sivukammioissa ja porraskatoksissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Hän vei minut ulompaan esipihaan pohjoista kohden vievää tietä myöten. Hän vei minut pihakammiorakennuksen luo, joka oli vastapäätä eristettyä aluetta ja pohjoisen puoleista rakennusta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'satakyynärää pitkän sivun edustalle, jossa oli oviaukko pohjoiseen päin. Sen leveys taas oli viisikymmentä kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Sen kaksikymmentäkyynäräisen paikan edustalla, joka kuului sisempään esipihaan, ja vastapäätä sitä kiveystä, joka oli ulommassa esipihassa, oli käytävä käytävää vastassa, kolmessa kerroksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Kammioiden editse meni kulkutie, kymmenen kyynärää leveä, sisempään esipihaan, ja tie oville yhden kyynärän leveä, ja oviaukot olivat pohjoiseen päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Mutta ylimmät kammiot olivat kapeimmat, sillä käytävät veivät niiltä tilaa enemmän kuin alimmilta ja keskimmäisiltä kammioilta rakennuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Sillä nämä olivat kolminkertaiset, mutta niissä ei ollut pylväitä, niin kuin esipihoissa oli pylväät. Sen vuoksi ne tulivat olemaan kapeammat kuin alimmat ja keskimmäiset maasta lukien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Oli myös muuri, joka ulkopuolella kulki samaan suuntaan kammioiden kanssa ulompaa esipihaa kohden kammioiden editse. Sen pituus oli viisikymmentä kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Sillä niiden kammioiden pituus, jotka olivat ulompaan esipihaan päin, oli yhteensä viisikymmentä kyynärää, mutta, katso, temppelisalin puolella sata kyynärää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Näiden kammioiden alapuolella oli sisäänkäynti idästä, kun tultiin niiden luo uloimmasta esipihasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Esipihaa ympäröivän muurin leveällä puolella itää kohden, eristetyn alan edustalla ja rakennuksen edustalla, oli kammioita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'Niiden editse kulki tie. Ne olivat samanmuotoisia kuin ne kammiot, jotka olivat pohjoista kohden: yhtä pitkiä ja leveitä. Samanlaisia olivat kaikki näiden ulos johtavat käytävät, rakennelmat ja oviaukot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Samoin kuin olivat niiden kammioiden oviaukot, jotka olivat etelää kohden, oli se oviaukko, joka oli tien päässä – tien, joka kulki senpuolisen muurin viertä itää kohden, sinne tultaessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Hän sanoi minulle: \"Pohjoiskammiot ja eteläkammiot, jotka ovat eristetyn alan edustalla, ovat pyhiä kammioita, joissa papit, jotka lähestyvät Herraa, syövät sitä, mikä on korkeasti pyhää. Sinne he pankoot korkeasti pyhän: ruokauhrin, syntiuhrin ja vikauhrin; sillä se paikka on pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Kun papit ovat tulleet, älkööt he menkö pyhäköstä ulos esipihaan muuten, kuin että panevat sinne vaatteensa, joissa toimittavat virkaansa, sillä ne ovat pyhät, ja pukeutuvat toisiin vaatteisiin. Sitten lähestykööt paikkaa, mikä on kansaa varten.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Kun hän oli saanut loppuun sisemmän temppelin mittaamisen, hän vei minut ulos sille portille, jonka etupuoli oli itää kohden. Hän mittasi sen ympärysmitan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Hän mittasi idän puolelta mittaruovolla: viisisataa ruokoa mittaruovon mukaan ympäriinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Hän mittasi pohjoisen puolelta: viisisataa ruokoa mittaruovon mukaan ympäriinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Hän mittasi etelän puolelta: viisisataa ruokoa mittaruovon mukaan ympäriinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Hän mittasi lännen puolelta: viisisataa ruokoa mittaruovon mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Neljältä ilmansuunnalta hän sen mittasi. Siinä oli muuri yltympäri: pituutta viisisataa ja leveyttä viisisataa. Sen tuli erottaa pyhä epäpyhästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Sitten hän kuljetti minut portille – sille portille, joka antoi itään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'Katso: Israelin Jumalan kunnia tuli idän tietä. Sen kohina oli kuin paljojen vetten kohina, ja maa tuli valoisaksi hänen kunniastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'Näky, jonka näin, oli samanlainen kuin se näky, jonka olin nähnyt tullessani hävittämään kaupungin. Samanlaiset olivat näyt kuin se näky, jonka olin nähnyt Kebar-joen varrella. Silloin lankesin kasvoilleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Herran kunnia kulki temppeliin sen portin kautta, jonka etupuoli oli itään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Henki nosti minut ja vei minut sisempään esipihaan. Katso: Herran kunnia täytti temppelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'Kuulin jonkun puhuttelevan minua temppelistä, mutta mies seisoi vieressäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'Hän sanoi minulle: \"Ihmislapsi, tämä on valtaistuimeni paikka ja jalkapohjieni sija, jossa asun israelilaisten keskellä iankaikkisesti. Israelin heimo ei ole enää saastuttava pyhää nimeäni – eivät he eivätkä heidän kuninkaansa – haureudellaan, kuninkaittensa ruumiilla ja uhrikukkuloillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Kun he asettivat kynnyksensä kynnykseni vierelle, ovenpielensä ovenpielteni viereen, niin että muuri vain oli minun ja heidän välillään, niin he saastuttivat pyhän nimeni kauhistuksillaan, joita he harjoittivat, ja tein heistä lopun vihassani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Nyt he vievät haureutensa ja kuninkaittensa ruumiit minusta kauas, ja asun heidän keskellään iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Sinä, ihmislapsi, saata Israelin heimolle sanoma tästä temppelistä, että he häpeäisivät rikoksiaan, ja he ottakoot siitä mallia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Jos he häpeävät kaikkea, mitä ovat tehneet, niin tee heille tiettäväksi temppelin muoto sekä sen sisustus, uloskäytävät, sisäänkäytävät, kaikki muodot, kaikki säädökset, kaikki muodot ja kaikki lait. Kirjoita ne heidän silmiensä eteen, että he ottaisivat vaarin sen koko muodosta ja kaikista säädöksistä ja tekisivät niiden mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Tämä on temppelin laki: sen koko alue vuoren laella yltympäri on korkeasti pyhä. Katso, tämä on temppelin laki.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Nämä olivat alttarin mitat kyynäröinä, kyynärään luettuna kyynärä ja kämmenenleveys: sen alusta oli kyynärän korkuinen ja kyynärän levyinen, ja sen reunusta ympäri sen laidan oli yhden vaaksan mittainen. Tämä oli alttarin koroke.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Alustasta, joka oli maassa, alimmalle välireunalle: kaksi kyynärää sekä leveyttä yksi kyynärä; ja pienemmältä välireunalta suuremmalle välireunalle: neljä kyynärää sekä leveyttä kyynärä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Jumalan lieteen oli neljä kyynärää, ja Jumalan liedestä ylöspäin oli neljä sarvea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'Jumalan lieden pituus oli kaksitoista kyynärää ja leveys kaksitoista, niin että sen neljästä sivusta tuli neliö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Välireunan pituus oli neljätoista kyynärää ja leveys neljätoista, sen neljältä sivulta. Sitä ympäröivä reunusta oli puoli kyynärää, ja sen alusta oli kyynärän ympäriinsä. Sen portaat olivat idän puolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Hän sanoi minulle: \"Ihmislapsi, näin sanoo Herra, Herra: Nämä ovat alttaria koskevat säädökset: Sinä päivänä, jona se on saatu tehdyksi, niin että sillä voidaan uhrata polttouhri ja vihmoa sille verta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'anna mulli syntiuhriksi papeille, leeviläisille, jotka ovat Saadokin jälkeläisiä ja saavat lähestyä minua palvellakseen minua, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Ota sen verta ja sivele alttarin neljään sarveen ja välireunan neljään kulmaan ja reunustaan yltympäri. Sinun on puhdistettava se ja toimitettava sen sovitus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Ota sitten syntiuhrimulli ja polta se säädetyssä, temppelille kuuluvassa paikassa, pyhäkön ulkopuolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Tuo seuraavana päivänä virheetön vuohipukki syntiuhriksi. Alttari on puhdistettava, samoin kuin se puhdistettiin mullin verellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Suoritettuasi loppuun puhdistuksen tuo virheetön mulli ja virheetön pässi pikkukarjasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'Tuo ne Herran eteen, ja papit heittäkööt niiden päälle suolaa ja uhratkoot ne polttouhriksi Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Uhraa joka päivä, seitsemänä päivänä, syntiuhripukki. Myös on uhrattava virheettömät mulli ja pässi pikkukarjasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Seitsemänä päivänä toimitettakoon alttarin sovitus ja puhdistettakoon ja vihittäköön se.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Niiden päivien kuluttua papit kahdeksantena päivänä ja aina edelleen uhratkoot alttarilla polttouhrejaan ja rauhanuhrejaan, ja minä mielistyn teihin, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Hän vei minut takaisin pyhäkön ulommalle portille, sille, joka antoi itään, mutta joka oli suljettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Herra sanoi minulle: \"Tämä portti on oleva suljettuna. Sitä ei saa avata, eikä kukaan saa käydä siitä sisälle, sillä Herra, Israelin Jumala, on käynyt siitä sisälle. Se on oleva suljettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Ruhtinas ainoastaan ruhtinaana istukoon siellä ja syököön leipää Herran edessä. Hän käyköön sisään porttieteisen kautta ja tulkoon ulos samaa tietä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Hän toi minut pohjoisportin kautta temppelin edustalle, ja näin, ja katso: Herran kunnia täytti Herran huoneen. Lankesin kasvoilleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Herra sanoi minulle: \"Ihmislapsi, pane sydämeesi, katso silmilläsi ja kuule korvillasi kaikki, mitä sinulle puhun kaikista Herran huoneen säädöksistä ja kaikista sen laeista, ja ota huomioosi, kuinka temppeliin on mentävä kustakin pyhäkön uloskäytävästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'Sano niille kapinoiville, sano Israelin heimolle: Näin sanoo Herra, Herra: Jo riittävät kaikki teidän kauhistuksenne, te Israelin heimo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'kun olette tuoneet muukalaisia, sydämeltään ja ruumiiltaan ympärileikkaamattomia, pyhäkkööni olemaan siellä ja häpäisemään huoneeni, samalla kun olette uhranneet leipääni ja rasvaa ja verta. Olette rikkoneet liittoni – kaikkien muiden kauhistustenne lisäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Ette ole hoitaneet minulle suoritettavia pyhiä tehtäviä, vaan olette panneet heitä puolestanne hoitamaan minulle pyhäkössäni suoritettavia tehtäviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Näin sanoo Herra, Herra: Yksikään muukalainen, sydämeltään ja ruumiiltaan ympärileikkaamaton, ei saa tulla pyhäkkööni, olkoon kuka tahansa israelilaisten keskuudessa oleva muukalainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Vaan ne leeviläiset, jotka menivät minusta kauas, silloin kun Israel oli joutunut eksyksiin, nuo, jotka eksyivät pois minusta epäjumaliensa perään, kantakoot syntinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'He toimittakoot pyhäkössäni vartioinnin temppelin porteilla ja toimittakoot temppelipalveluksen. He teurastakoot polttouhrit ja teurasuhrit kansalle ja seisokoot heidän edessään heitä palvelemassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Koska he ovat heitä palvelleet heidän epäjumaliensa edessä ja olleet Israelin heimolle kompastuksena syntiin, sen tähden olen kohottanut käteni heitä vastaan, sanoo Herra, Herra, ja heidän on kannettava syntinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'He eivät saa lähestyä minua, niin että toimittaisivat edessäni papinvirkaa ja lähestyisivät mitään minulle pyhitettyä, mitään korkeasti pyhää, vaan heidän on kannettava häpeänsä ja kauhistuksensa, joita ovat tehneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Panen heidät hoitamaan temppelissä suoritettavia tehtäviä, mitä siellä on palvelijantyötä ja muuta toimitettavaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Mutta ne leeviläiset papit, Saadokin jälkeläiset, jotka hoitivat pyhäkössäni suoritettavat tehtävät silloin, kun israelilaiset olivat eksyneet minusta pois, he saavat lähestyä minua, palvella minua ja seisoa edessäni uhraamassa minulle rasvaa ja verta, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'He saavat tulla pyhäkkööni ja saavat lähestyä pöytääni palvellen minua ja hoitaen minulle suoritettavat tehtävät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Tullessaan sisemmän esipihan porteille he pukeutukoot pellavavaatteisiin älköötkä pitäkö päällään villaista vaatetta toimittaessaan virkaansa sisemmän esipihan porteissa ja sisällä temppelissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Pellavaiset turbaanit olkoot heillä päässä ja pellavaiset housut lanteilla. Älkööt he panko vyötäisilleen mitään hiostuttavaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Kun he menevät pois ulompaan esipihaan, kansan luo ulompaan esipihaan, riisukoot vaatteensa, joissa ovat virkaa toimittaneet, jättäkööt ne pyhäkön kammioihin ja pukekoot päälleen toiset vaatteet, etteivät pyhittäisi kansaa vaatteillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Älkööt ajako päätänsä paljaaksi, mutta älkööt myöskään antako tukkansa kasvaa valtoimenaan. Heidän on leikattava hiuksensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Viiniä älköön kukaan pappi juoko tultuaan sisempään esipihaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Leskeä ja hylättyä älkööt ottako vaimokseen, vaan ottakoot neitsyen Israelin heimon jälkeläisistä tai lesken, joka on leskenä papin jälkeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Opettakoot he kansalleni erotuksen pyhän ja epäpyhän välillä sekä tehkööt heille tiettäväksi, mikä on saastaista, mikä puhdasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Riita-asioissa seisokoot tuomitsemassa ja tuomitkoot niissä oikeuksieni mukaan. Lakejani ja säädöksiäni noudattakoot kaikkien juhlieni vietossa ja pyhittäkööt sapattini.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Älköön menkö kuolleen ihmisen luo ja siten tulko saastaiseksi. Ainoastaan isästä ja äidistä, pojasta ja tyttärestä, veljestä ja sisaresta, jos tämä ei ollut naitu, hän saa saastua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Mutta puhdistuksensa jälkeen luettakoon hänelle vielä seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'Sinä päivänä, jona hän tulee pyhäkköön, sisempään esipihaan, toimittamaan virkaansa pyhäkössä, hän uhratkoon syntiuhrinsa, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'Tämä on oleva heidän perintöosansa: minä olen heidän perintöosansa. Teidän ei tule antaa heille perintömaata Israelissa: minä olen heidän perintömaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Ruokauhrin, syntiuhrin ja vikauhrin he saavat syödä, ja kaikki tuhoon vihitty Israelissa on tuleva heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Paras kaikesta ensisadosta, kaikenlaatuisesta, ja kaikki annit, mitä laatua hyvänsä antinne ovatkin, tulevat papeille. Parhaat ryyneistänne teidän on annettava papille, että tuottaisit siunauksen huoneellesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Papit älkööt syökö mitään itsestään kuollutta tai kuoliaaksi raadeltua, ei lintua eikä nautaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, '\"Kun arvotte maata perintöosiksi, niin antakaa Herralle anti, pyhä osa maasta, kaksikymmentäviisi tuhatta kyynärää pitkä ja kymmenen tuhatta kyynärää leveä. Se olkoon pyhä koko alueeltaan, yltympäri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Siitä tulkoon pyhäkölle neliö, viisisataa ja viisisataa kyynärää joka taholta, ja sen lisäksi avointa tilaa viisikymmentä kyynärää joka taholta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Mittaa tästä mitatusta alueesta kaksikymmentäviisi tuhatta kyynärää pituutta ja kymmenentuhatta kyynärää leveyttä, ja siinä olkoon pyhäkkö, korkeasti pyhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Se olkoon pyhä osa maasta papeille, jotka palvelevat pyhäkössä, jotka lähestyvät ja palvelevat Herraa. Se olkoon talojen sijaintipaikkana heitä varten ja pyhänä paikkana pyhäkköä varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Kaksikymmentäviisi tuhatta pituutta ja kymmenentuhatta leveyttä on tuleva leeviläisille, jotka toimittavat palvelusta pyhäkössä, heille perintömaaksi – kaksikymmentä kammiota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Kaupungille antakaa perintömaata viisituhatta kyynärää leveyttä ja kaksikymmentäviisi tuhatta kyynärää pituutta, pyhän anniksi annetun maan viereltä. Se olkoon koko Israelin heimon oma.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Ruhtinaalle: molemmilta puolin pyhää anniksi annettua maata ja kaupungin perintömaata, pyhän anniksi annetun maan sivusta ja kaupungin perintömaan sivusta, lännen puolelta länteen päin ja idän puolelta itään päin, maata yhtä pitkälti kuin on yhden sukukunnan osuuden pituus länsirajasta itärajaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Se olkoon hänellä maana, perintömaana Israelissa. Älkööt ruhtinaani enää sortako kansaani, vaan jättäkööt muun maan Israelin heimolle sukukunnittain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Näin sanoo Herra, Herra: Jo riittää, te Israelin ruhtinaat! Pankaa pois väkivalta ja sorto, noudattakaa oikeutta ja vanhurskautta, lakatkaa häätämästä kansaani sen mailta, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Olkoon teillä oikea paino, oikea eefa-mitta ja oikea bat-mitta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Eefa- ja bat-mitta olkoot tarkasti yhtä suuret: bat vetäköön kymmenenneksen hoomer-mittaa ja eefa kymmenenneksen hoomer-mittaa. Hoomerin mukaan määrättäköön kummankin suuruus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Sekelissä olkoon kaksikymmentä geeraa. Miina olkoon teillä kaksikymmentä sekeliä, kaksikymmentäviisi sekeliä, viisitoista sekeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Tämä on anti, joka teidän on annettava: kuudennes eefaa vehnähoomerista ja kuudennes eefaa ohrahoomerista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Öljyn määrä bat-mitasta öljyä: kymmenennes batia koor-mitasta – kymmenestä batista, hoomerista – sillä hoomer on kymmenen batia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'ja pikkukarjasta: kahdestasadasta yksi lammas Israelin runsasvetisiltä laitumilta ruokauhriksi, polttouhriksi ja rauhanuhriksi, että voitaisiin toimittaa heille sovitus, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Koko maan kansa on velvollinen antamaan tämän annin Israelin ruhtinaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Mutta ruhtinas toimittakoon polttouhrit, ruokauhrin ja juomauhrin juhlina, uusinakuina ja sapatteina, kaikkina Israelin heimon juhla-aikoina. Hän uhratkoon syntiuhrin, ruokauhrin, polttouhrin ja rauhanuhrin toimittaakseen sovituksen Israelin heimolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Näin sanoo Herra, Herra: Ota ensimmäisessä kuussa, kuukauden ensimmäisenä päivänä virheetön mulli ja puhdista pyhäkkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Pappi ottakoon syntiuhrin verta ja sivelköön sitä temppelin ovenpieliin ja alttarin neljään kulmaan ja sisemmän esipihan portin ovenpieliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Samoin tee kuukauden seitsemäntenä päivänä sen varalta, että joku olisi erehdyksestä tai tietämättömyydestä rikkonut, ja toimitatte temppelin sovituksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Ensimmäisessä kuussa, kuukauden neljäntenätoista päivänä, on teillä pääsiäinen. Se on seitsemän päivää kestävä juhla. Syötäköön silloin happamatonta leipää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Sinä päivänä uhratkoon ruhtinas omasta puolestaan ja maan kaiken kansan puolesta mullin syntiuhriksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Mutta kunakin seitsemänä juhlapäivänä hän uhratkoon polttouhriksi Herralle seitsemän mullia ja seitsemän pässiä, virheettömiä, joka päivä seitsemänä päivänä, ja syntiuhriksi vuohipukin joka päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Ruokauhriksi hän uhratkoon eefa-mitan mullia ja eefa-mitan pässiä kohti sekä öljyä hiin-mitan eefaa kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Seitsemännessä kuussa, kuukauden viidentenätoista päivänä, juhlana, hän uhratkoon samalla tavoin – niin seitsemänä päivänä – samankaltaisen syntiuhrin, polttouhrin ja ruokauhrin sekä saman määrän öljyä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, '\"Näin sanoo Herra, Herra: Sisemmän esipihan portti, se, joka antaa itään päin, olkoon suljettuna kuusi työpäivää. Mutta sapatinpäivänä se avattakoon, ja avattakoon se myös uudenkuun päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'Silloin tulkoon ruhtinas porttieteisen kautta ulkoa ja asettukoon portin ovipieleen. Kun papit uhraavat hänen polttouhriaan ja rauhanuhriaan, niin hän kumartaen rukoilkoon portin kynnyksellä ja menköön sitten ulos. Mutta porttia älköön suljettako ennen iltaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Mutta maan kansa kumartaen rukoilkoon sen portin ovella sapatteina ja uusinakuina Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Polttouhrina, jonka ruhtinas tuo Herralle sapatinpäivänä, olkoon kuusi virheetöntä karitsaa ja virheetön pässi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'ja ruokauhrina eefa-mitta pässiä kohti, mutta ruokauhrina karitsoita kohti se, mitä hän voi ja tahtoo antaa, sekä hiin-mitta öljyä eefaa kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Uudenkuun päivänä olkoon polttouhrina: virheetön mulli, kuusi karitsaa ja pässi, kaikki virheettömiä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'ja ruokauhrina hän uhratkoon eefan mullia kohti ja eefan pässiä kohti sekä karitsoita kohti sen, mitä hän saa hankituksi, sekä öljyä hiin-mitan eefaa kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Kun ruhtinas tulee, tulkoon porttieteisen kautta ja menköön ulos samaa tietä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Mutta kun maan kansa tulee juhlina Herran eteen, niin se, joka pohjoisportin kautta tuli kumartaen rukoilemaan, menköön ulos eteläportin kautta, ja se, joka tuli eteläportin kautta, menköön ulos pohjoisportin kautta. Kukaan älköön palatko sen portin kautta, josta tuli, vaan menköön ulos vastakkaisesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Ruhtinas tulkoon heidän joukossaan, kun he tulevat, ja menköön ulos, kun he menevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Juhlina ja juhla-aikoina olkoon ruokauhri: eefa mullia kohti ja eefa pässiä kohti sekä karitsoita kohti se, mitä kukin voi antaa, sekä öljyä hiin-mitta eefaa kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Milloin ruhtinas uhraa vapaaehtoisia lahjoja, polttouhrin tai rauhanuhrin vapaaehtoisena lahjana Herralle, avattakoon hänelle portti, joka antaa itään, ja hän uhratkoon polttouhrinsa sekä rauhanuhrinsa samoin, kuin hän uhraa sapatinpäivänä, ja menköön ulos. Hänen lähdettyään suljettakoon portti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Uhraa vuoden vanha virheetön karitsa joka päivä polttouhriksi Herralle. Uhraa se joka aamu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Sen lisäksi uhraa ruokauhriksi joka aamu kuudennes eefaa sekä öljyä kolmannes hiin-mittaa ydinjauhojen kostuttamiseksi. Tämä on ruokauhri Herralle – ikiaikainen, pysyvä säädös.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Uhratkaa joka aamu karitsa, ruokauhri ja öljy jokapäiväiseksi polttouhriksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Näin sanoo Herra, Herra: Jos ruhtinas antaa jollekin pojistaan lahjan, se on tämän perintöosa. Se on tuleva hänen pojilleen. Se on perintöosana heidän omaisuuttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Mutta jos hän antaa lahjan perintöosastaan jollekin palvelijoistaan, olkoon se tämän oma vapautusvuoteen saakka, mutta sitten palatkoon ruhtinaalle. Sehän on hänen perintöosaansa ja on tuleva hänen pojilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Älköönkä ruhtinas ottako kansan perintöosia, niin että sortaisi heitä pois heidän perintömaaltaan. Omasta perintömaastaan hän antakoon perintöosia pojilleen, ettei kukaan kansastani tulisi häädetyksi pois omalta perintömaaltaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Hän vei minut siitä sisäänkäytävästä, joka oli portin sivuseinämällä, niiden kammioiden luo, jotka olivat pyhitettyjä papeille ja jotka antoivat pohjoiseen. Katso, siellä oli eräs paikka kauimpana länttä kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Hän sanoi minulle: \"Tämä on paikka, missä pappien on keitettävä vikauhri ja syntiuhri sekä leivottava ruokauhri, etteivät veisi ulos sitä ulompaan esipihaan pyhittääkseen kansan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Sitten hän vei minut ulompaan esipihaan ja johdatti minut esipihan neljän nurkkauksen ohi, ja katso, esipihan joka nurkkauksessa oli piha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'Esipihan neljässä nurkkauksessa oli suljetut pihat, neljänkymmenen pituiset ja kolmenkymmenen levyiset. Nämä neljä nurkkapihaa olivat yhtä suuret.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'Niissä neljässä oli ympäriinsä kivikehä, ja alas kivikehään oli tehty keittoliesiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'Sitten hän sanoi minulle: \"Nämä ovat keittiötilat, joissa temppelipalvelijat keittävät kansan teurasuhrit.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Hän vei minut takaisin temppelin ovelle. Katso, vettä tuli temppelin kynnyksen alta itään päin, sillä temppelin etusivu oli itään. Vesi juoksi alas temppelin oikeanpuoleisen sivuseinän ali alttarin eteläpuolitse.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Hän toi minut ulos pohjoisportin kautta ja kierrätti minut ulkopuolelta ulkoportille, joka antoi itään. Katso, vesi virtasi oikeanpuoleiselta sivuseinältä päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Mennessään itää kohti mittanuora kädessään mies mittasi tuhat kyynärää ja antoi minun käydä veden poikki. Vettä oli nilkkoihin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Hän mittasi tuhat ja antoi minun kävellä veden poikki: vettä oli polviin asti. Hän mittasi tuhat ja antoi minun kävellä poikki: vettä oli vyötäisille asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Ja hän mittasi tuhat. Tuli virta, jota en voinut ylittää. Sillä vesi nousi uimavedeksi, virraksi, jonka yli ei pääse.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Hän kysyi minulta: \"Oletko nähnyt, ihmislapsi?\" Ja hän kuljetti minua ja toi takaisin virran rannalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Mutta kun tulin takaisin, katso: virran rannalla oli hyvin paljon puita molemmilla puolin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Hän sanoi minulle: \"Nämä vedet juoksevat itäiselle alueelle, virtaavat alas Aromaahan ja tulevat mereen. Niiden tultua mereen vesi siinä paranee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'Kaikki elolliset, kaikki, jotka liikkuvat, virkoavat elämään kaikkialla, mihin tämä kaksoisvirta tulee. Kaloja on oleva hyvin paljon. Sillä kun nämä vedet tulevat sinne ja vesi paranee, niin kaikki virkoaa elämään, minne vain virta tulee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Kalastajia seisoo sen rannalla. Een-Gedistä Een-Eglaimiin asti he levittävät verkkojaan. Siinä on kaikenlaisia kaloja, aivan kuin suuren meren kaloja, hyvin paljon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Sen suot ja lammikot eivät parane. Ne jätetään suolan valtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Mutta virran varrella, sen molemmilla rannoilla, kasvaa kaikenlaisia hedelmäpuita. Niistä eivät lehdet lakastu eivätkä hedelmät lopu. Joka kuukausi ne kantavat tuoreet hedelmät, sillä niiden vedet juoksevat pyhäköstä, ja niiden hedelmät ovat ravitsevia ja niiden lehdet parantavia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Näin sanoo Herra, Herra: Tämä on raja, jonka mukaan teidän on jaettava maa perintöosiksi kahdelletoista Israelin sukukunnalle – Joosef saakoon kaksi osaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Te saatte siitä perintöosan jokainen kohdaltaan. Sillä olen kättä kohottaen luvannut antaa sen teidän isillenne, ja niin tämä maa tulee teille perintöosaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Tämä on maan pohjoisraja: Suuresta merestä Hetlonin tietä siihen asti, mistä mennään Sedadiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Hamat, Beerota, Sibraim, joka on Damaskon alueen ja Hamatin alueen välissä, keskimmäinen Haaser, joka on Hauranin rajalla;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'ja näin menee raja merestä Hasar-Eenoniin – Damaskon alue jää siitä pohjoiseen ja pohjoiseen siitä jää myös Hamatin alue. Tämä on pohjoispuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Itäpuoli: Hauranin ja Damaskon välistä sekä Gileadin ja Israelin maan välistä, Jordania pitkin. Mitatkaa se rajasta itäiseen mereen. Tämä on itäpuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'Eteläpuoli, etelään päin: Taamarista Meriban veteen, joka on Kaadeksessa, virtaan, joka laskee Suureen mereen. Tämä on eteläpuoli, etelään päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Meren puoli: Suuri meri rajasta sen paikan kohdalle, mistä mennään Hamatiin. Tämä on meren puoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Jakakaa tämä maa keskenänne Israelin sukukuntien mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'Arpokaa se perintöosiksi itsellenne ja muukalaisille, jotka asuvat muukalaisina keskuudessanne ja ovat synnyttäneet lapsia keskuudessanne. Olkoot he keskuudessanne samanarvoisia israelilaisten kanssa. He saakoot arvalla perintöosan Israelin sukukuntien keskuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'Missä sukukunnassa muukalainen asuu, siinä antakaa hänelle perintöosa, sanoo Herra, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, '\"Nämä ovat sukukuntien nimet: Pohjoisreunalta Hetlonista Hamatiin johtavaa tietä, ja siitä Hasar-Eenamiin Damaskon alueen jäädessä siitä pohjoiseen Hamatin sivulle. Tämä on Daanille idästä länteen asti tuleva osuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Daanin alueen ollessa rajana idästä länteen asti tulee Asserille yksi osuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Asserin alueen ollessa rajana idästä länteen asti tulee Naftalille yksi osuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Naftalin alueen ollessa rajana idästä länteen asti tulee Manasselle yksi osuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Manassen alueen ollessa rajana idästä länteen asti tulee Efraimille yksi osuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Efraimin alueen ollessa rajana idästä länteen asti tulee Ruubenille yksi osuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Ruubenin alueen ollessa rajana idästä länteen asti tulee Juudalle yksi osuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'Juudan alueen ollessa rajana idästä länteen asti on oleva se lahjoitusmaa, joka teidän on annettava, kaksikymmentäviisi tuhatta kyynärää leveä ja niin pitkä kuin on yksi sukukunnan osa idästä länteen, ja pyhäkkö olkoon sen keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Lahjoitusmaa, joka teidän on annettava Herralle, olkoon kaksikymmentäviisi tuhatta pitkä ja kaksikymmentä tuhatta leveä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Pyhää lahjoitusmaata tulkoon seuraaville: papeille pohjoisesta kaksikymmentäviisi tuhatta, lännestä kymmenentuhatta leveälti, idästä kymmenentuhatta leveälti ja etelästä kaksikymmentäviisi tuhatta pitkälti, ja Herran pyhäkkö olkoon siinä keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Papeille, niille Saadokin jälkeläisistä, jotka ovat pyhitettyjä, jotka ovat hoitaneet minulle suoritettavat tehtävät ja jotka eivät eksyneet, niin kuin leeviläiset eksyivät, silloin kun israelilaiset joutuivat eksyksiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'heille se tulkoon verona lahjoitusmaasta, korkeasti pyhänä; tulkoon se leeviläisten alueen vierestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Leeviläiset saakoot samanlaisen alueen kuin papit, kaksikymmentäviisi tuhatta pitkän ja kymmenentuhatta leveän. Koko pituus olkoon kaksikymmentäviisi tuhatta ja leveys kaksikymmentä tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Älkööt he myykö siitä mitään, älköönkä maan ensi hedelmää vaihdettako tai luovutettako, sillä se on pyhitetty Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Mutta viisituhatta leveä maa, mikä jää yli kahdenkymmenenviiden tuhannen sivusta, on kaupungin yhteisomaisuutta asumuksia ja avointa tilaa varten, ja kaupunki olkoon sen keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Nämä olkoot sen mitat: pohjoispuoli neljätuhatta viisisataa, eteläpuoli neljätuhatta viisisataa, itäpuoli neljätuhatta viisisataa ja länsipuoli neljätuhatta viisisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Kaupungilla olkoon avoin tila: pohjoiseen kaksisataa viisikymmentä, etelään kaksisataa viisikymmentä, itään kaksisataa viisikymmentä ja länteen kaksisataa viisikymmentä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Mutta niin pitkälti kuin jää pyhän lahjoitusmaan viereltä yli, kymmenentuhatta itään ja kymmenen tuhatta länteen, se olkoon pyhän lahjoitusmaan vierellä, ja sen sato tulkoon leiväksi kaupungin työmiehille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'ja sitä viljelkööt kaupungin työmiehet kaikista Israelin sukukunnista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Koko lahjoitusmaa on kaksikymmentäviisi tuhatta ja kaksikymmentäviisi tuhatta. Neliönmuotoisena on teidän annettava pyhä lahjoitusmaa sekä kaupungin perintömaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Mikä jää yli, se tulkoon ruhtinaalle: molemmilta puolilta pyhää lahjoitusmaata ja kaupungin perintömaata, niiden kahdenkymmenenviiden tuhannen – lahjoitusmaan – sivusta itärajaan asti, sekä länteen päin niiden kahdenkymmenenviiden tuhannen sivusta länsirajaan asti, on ruhtinaalle tuleva sukukuntaosia vastaava maa. Pyhä lahjoitusmaa sekä temppelipyhäkkö olkoot sen keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Leeviläisten perintömaasta ja kaupungin perintömaasta asti, jotka ovat ruhtinaalle tulevan maan keskellä, tulee ruhtinaalle se, mikä on Juudan alueen ja Benjaminin alueen välissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Muut sukukunnat: Idästä länteen asti Benjaminille tulee yksi osuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Benjaminin alueen ollessa rajana idästä länteen asti tulee Simeonille yksi osuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Simeonin alueen ollessa rajana idästä länteen asti tulee Isaskarille yksi osuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Isaskarin alueen ollessa rajana idästä länteen asti tulee Sebulonille yksi osuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Sebulonin alueen ollessa rajana idästä länteen asti tulee Gaadille yksi osuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Gaadin alueen eteläraja menee Taamarista Meriban veteen, Kaadekseen, Egyptin puroon ja Suureen mereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Tämä on maa, joka teidän on arvottava perintöosiksi Israelin sukukunnille, ja nämä ovat heidän osuutensa, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'Nämä ovat kaupungin uloskäytävät: Pohjoispuolella on mitta neljätuhatta viisisataa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'Kaupungin portteja, jotka ovat nimitetyt Israelin sukukuntien mukaan, on pohjoisessa kolme: Ruubenin portti yksi, Juudan portti toinen ja Leevin portti kolmas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Itäpuolella: neljätuhatta viisisataa, ja portteja kolme: Joosefin portti yksi, Benjaminin portti toinen ja Daanin portti kolmas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Eteläpuolella on mitta neljätuhatta viisisataa, ja portteja kolme: Simeonin portti yksi, Isaskarin portti toinen ja Sebulonin portti kolmas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Länsipuolella: neljätuhatta viisisataa, ja portteja kolme: Gaadin portti yksi, Asserin portti toinen ja Naftalin portti kolmas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Ympärysmitta on kahdeksantoista tuhatta. Kaupungin nimi on tästedes oleva: Herra on täällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Joojakimin, Juudan kuninkaan, kolmantena hallitusvuotena tuli Nebukadnessar, Baabelin kuningas, Jerusalemin edustalle ja piiritti sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Herra antoi hänen käsiinsä Joojakimin, Juudan kuninkaan, sekä loput Jumalan huoneen astioista, ja hän vei ne Sinearin maahan jumalansa huoneeseen. Hän vei astiat jumalansa aarrekammioon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Kuningas käski ylimmäisen hoviherransa Aspenaan tuoda israelilaisia poikia, jotka olivat kuninkaallista sukua tai ylimysperheistä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'nuorukaisia, joissa ei ollut mitään virhettä ja jotka olivat muodoltaan kauniita, jotka kykenivät käsittämään kaikkea viisautta, olivat terävä-älyisiä ja hyväoppisia ja jotka olisivat kelvollisia palvelemaan kuninkaan hovissa. Heille hänen tuli opettaa kaldealaisten kirjoitusta ja kieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Kuningas määräsi heille jokapäiväiseksi ravinnoksi ruokaa kuninkaan pöydästä ja viiniä, jota hän itse joi. Niin heitä oli kasvatettava kolme vuotta, ja niiden kuluttua heidän tuli astua kuninkaan palvelukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Heidän joukossaan olivat juutalaiset pojat Daniel, Hananja, Miisael ja Asarja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Hoviherrojen päällikkö antoi heille nimet: Danielille hän antoi nimen Beltsassar, Hananjalle nimen Sadrak, Miisaelille nimen Meesak ja Asarjalle nimen Abednego.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Daniel päätti lujasti olla saastuttamatta itseään kuninkaan pöydän ruualla ja viinillä, jota tämä joi, ja anoi hoviherrojen päälliköltä, ettei hänen tarvitsisi saastuttaa itseään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Jumala salli Danielin saada suosion ja armon hoviherrojen päällikön edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Hoviherrojen päällikkö sanoi Danielille: \"Minä pelkään, että jos herrani, kuningas, joka on määrännyt ruokanne ja juomanne, huomaa kasvonne laihemmiksi kuin muiden ikäistenne nuorukaisten, te saatatte minun pääni vaaraan kuninkaan edessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Silloin Daniel sanoi katsastajalle, jonka hoviherrojen päällikkö oli määrännyt pitämään silmällä Danielia, Hananjaa, Miisaelia ja Asarjaa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, '\"Koettele palvelijoitasi kymmenen päivää, ja annettakoon meille vihannesruokaa syödäksemme ja vettä juodaksemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Sitten tarkastettakoon edessäsi, miltä näytämme ja miltä näyttävät ne nuorukaiset, jotka syövät kuninkaan pöydän ruokaa. Tee sitten palvelijoillesi sen mukaan, mitä silloin havaitset.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Hän kuuli heitä tässä asiassa ja koetteli heitä kymmenen päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Mutta kymmenen päivän kuluttua havaittiin heidät muodoltaan kauniimmiksi ja ruumiiltaan lihavammiksi kuin yksikään niistä nuorukaisista, jotka söivät kuninkaan pöydän ruokaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Katsastaja jätti pois heille määrätyn ruuan ja heidän juotavansa viinin ja antoi heille vihannesruokaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Jumala antoi näille neljälle nuorukaiselle taidon käsittää kaikki kirjoitukset ja kaiken viisauden; ja Daniel ymmärsi myös kaikki näyt ja unet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Kun ne päivät olivat kuluneet, joiden jälkeen kuningas oli käskenyt tuoda heidät esiin, niin hoviherrojen päällikkö toi heidät Nebukadnessarin eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'Kun nyt kuningas keskusteli heidän kanssaan, heidän joukossaan ei ollut yhtään Danielin, Hananjan, Miisaelin ja Asarjan veroista. Niin he tulivat kuninkaan palvelijoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Kaikissa viisautta ja ymmärrystä vaativissa asioissa, joita kuningas heiltä kyseli, hän havaitsi heidät kymmenen kertaa etevämmiksi kuin kaikki tietäjät ja noidat, mitä oli koko hänen valtakunnassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Daniel oli siellä kuningas Kooreksen ensimmäiseen vuoteen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Nebukadnessarin toisena hallitusvuotena Nebukadnessar näki unia, ja hänen mielensä oli levoton eikä hän saanut enää unta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Kuningas käski kutsua tietäjät ja noidat, velhot ja kaldealaiset ilmoittamaan kuninkaalle hänen unensa. He tulivat ja astuivat kuninkaan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Kuningas sanoi heille: \"Olen nähnyt unen, ja mieleni on levoton ja haluan tietää unen merkityksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Kaldealaiset puhuivat kuninkaalle arameaksi: \"Eläköön kuningas iankaikkisesti! Kerro uni palvelijoillesi, niin ilmoitamme sen selityksen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Kuningas vastasi ja sanoi kaldealaisille: \"Tämä sanani on luja: Ellette ilmoita minulle unta ja sen selitystä, teidät hakataan kappaleiksi ja teidän talonne tehdään soraläjiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Mutta jos ilmoitatte minulle unen ja sen selityksen, saatte minulta lahjoja ja antimia ja suuren kunnian. Sen tähden ilmoittakaa minulle uni ja sen selitys.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'He vastasivat toistamiseen ja sanoivat: \"Kuningas sanokoon unen palvelijoilleen, niin ilmoitamme sen selityksen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Kuningas vastasi ja sanoi: \"Minä huomaan selvästi, että te vain koetatte voittaa aikaa, koska näette, että tämä sanani on luja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'että ellette ilmoita minulle unta, teillä on edessä vain yksi tuomio. Sillä te olette sopineet keskenänne, että puhutte edessäni valheellista ja turmiollista puhetta toivoen, että aika muuttuu. Sen tähden sanokaa minulle uni. Silloin tiedän, että osaatte ilmoittaa minulle siihen selityksen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Kaldealaiset vastasivat kuninkaan edessä ja sanoivat: \"Ei ole maan päällä ihmistä, joka kykenisi selittämään sen, mitä kuningas sanoi. Eikä yksikään suuri ja voimallinen kuningas ole koskaan vaatinut tällaista asiaa keneltäkään tietäjältä, noidalta tai kaldealaiselta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Sillä asia, jota kuningas vaatii, on vaikea, eikä ole ketään, joka voisi sen kuninkaalle selittää, paitsi jumalat, joiden asuinsija ei ole ihmisten luona.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Tästä kuningas suuttui ja vihastui kovin ja käski tappaa kaikki Baabelin viisaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Kun tästä oli käsky annettu, että viisaat piti tappaa, etsittiin Danielia ja hänen tovereitaan tapettaviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Daniel antoi viisaan ja taitavan vastauksen Arjokille, kuninkaan henkivartioston päällikölle, joka oli lähtenyt tappamaan Baabelin viisaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Hän vastasi ja sanoi Arjokille, kuninkaan päällikölle: \"Miksi kuningas on antanut niin ankaran käskyn?\" Arjok kertoi Danielille asian.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Daniel meni palatsiin ja pyysi kuningasta antamaan hänelle aikaa, että hän ilmoittaisi kuninkaalle selityksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Daniel meni kotiinsa ja kertoi asian tovereilleen Hananjalle, Miisaelille ja Asarjalle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'kehottaen heitä rukoilemaan armoa taivaan Jumalalta tämän salaisuuden tähden, ettei Danielia ja hänen tovereitaan tapettaisi muiden Baabelin viisaiden kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Salaisuus ilmoitettiin Danielille yöllisessä näyssä, ja Daniel kiitti taivaan Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Daniel lausui ja sanoi: \"Olkoon Jumalan nimi kiitetty iankaikkisesta iankaikkiseen, sillä hänen on viisaus ja voima.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Hän muuttaa ajat ja hetket, hän syöksee kuninkaat vallasta ja korottaa kuninkaat valtaan, hän antaa viisaille viisauden ja taidollisille ymmärryksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Hän paljastaa syvät ja salatut asiat, hän tietää, mitä pimeydessä on, ja valkeus asuu hänen luonaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Sinua, minun isieni Jumala, minä kiitän ja ylistän siitä, että olet antanut minulle viisauden ja voiman ja että nyt annoit minun tietää, mitä sinulta rukoilimme. Sillä annoit meidän tietää kuninkaan asian.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Daniel meni Arjokin tykö, jolla oli kuninkaan määräys tappaa Baabelin viisaat. Hän meni ja sanoi hänelle näin: \"Älä tapa Baabelin viisaita. Vie minut kuninkaan eteen, niin ilmoitan kuninkaalle selityksen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Silloin Arjok vei kiireesti Danielin kuninkaan eteen ja sanoi tälle näin: \"Olen löytänyt juutalaisten karkotettujen joukosta miehen, joka ilmoittaa kuninkaalle selityksen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Kuningas vastasi ja sanoi Danielille, jonka nimenä oli Beltsassar: \"Voitko ilmoittaa minulle unen, jonka näin, ja sen selityksen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel vastasi kuninkaalle ja sanoi: \"Salaisuutta, jonka kuningas tahtoo tietää, eivät viisaat, noidat, tietäjät eivätkä tähtienselittäjät voi ilmoittaa kuninkaalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Mutta taivaassa on Jumala. Hän paljastaa salaisuudet ja ilmoittaa kuningas Nebukadnessarille, mitä tapahtuu aikojen lopulla. Tämä on sinun unesi, sinun pääsi näky, joka sinulla oli vuoteessasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Kun sinä, kuningas, olit vuoteessasi, nousi mieleesi ajatus, mitä tämän jälkeen tapahtuu. Hän, joka paljastaa salaisuudet, ilmoitti sinulle, mitä on tapahtuva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Mutta tätä salaisuutta ei ole paljastettu minulle oman viisauteni voimasta, ikään kuin minulla olisi sitä enemmän kuin kellään toisella ihmisellä, vaan sen tähden että selitys ilmoitettaisiin kuninkaalle ja saisit selville sydämesi ajatukset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Sinä näit, kuningas, katso, oli iso kuvapatsas. Se kuvapatsas oli suuri, ja sen kirkkaus oli ylenpalttinen. Se seisoi edessäsi, ja se oli hirvittävä nähdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Kuvan pää oli parasta kultaa, sen rinta ja käsivarret hopeaa, ja sen vatsa ja lanteet vaskea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'Sen sääret olivat rautaa, sen jalat osaksi rautaa, osaksi savea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Sitä katsellessasi irtautui kivilohkare – ei kuitenkaan käsien irrottamana – ja iski kuvapatsasta jalkoihin, jotka olivat rautaa ja savea, ja murskasi ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Silloin musertuivat yhdellä kertaa rauta, savi, vaski, hopea ja kulta, ja niiden kävi kuin akanoiden kesäisillä puimatantereilla. Tuuli vei ne, eikä niistä löytynyt jälkeäkään. Mutta kivestä, joka oli kuvapatsaan murskannut, tuli suuri vuori, ja se täytti koko maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Tämä oli se uni, ja nyt sanomme kuninkaalle sen selityksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Sinä, kuningas, olet kuningasten kuningas, jolle taivaan Jumala on antanut vallan, voiman, väkevyyden ja kunnian');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'ja jonka käteen hän on antanut ihmiset, missä ikinä heitä asuu, ja kedon eläimet ja taivaan linnut, asettaen sinut kaikkien niiden valtiaaksi. Sinä olet se kultainen pää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Mutta sinun jälkeesi nousee toinen valtakunta, joka on halvempi kuin sinun, ja sitten kolmas valtakunta, joka on vaskea ja joka hallitsee koko maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Myös neljäs valtakunta on luja kuin rauta. Niin kuin rauta musertaa ja särkee kaiken, niin kuin rauta murskaa, niin se on musertava ja murskaava ne kaikki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Mutta se, että näit jalkojen ja varpaiden olevan osittain savenvalajan savea, osittain rautaa, merkitsee, että se on oleva hajanainen valtakunta. Kuitenkin siinä on oleva raudan lujuutta, niin kuin näit rautaa olevan saven seassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Se taas, että jalkojen varpaat olivat osaksi rautaa, osaksi savea, merkitsee, että osa valtakuntaa on oleva luja, osa sitä on oleva hauras.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Että näit rautaa olevan saven seassa, se merkitsee, että ne sekaantuvat toisiinsa ihmisen siemenen kautta, ne eivät yhdisty toinen toiseensa, niin kuin ei rautakaan sekaannu saveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Mutta niiden kuningasten päivinä on taivaan Jumala pystyttävä valtakunnan, joka on kukistumaton iankaikkisesti ja jonka valtaa ei toiselle kansalle anneta. Se on musertava kaikki ne muut valtakunnat ja tekevä niistä lopun, mutta se itse on pysyvä iankaikkisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'niin kuin näit, että kivilohkare irtautui vuoresta – ei kuitenkaan käsien irrottamana – ja murskasi raudan, vasken, saven, hopean ja kullan. Suuri Jumala on ilmoittanut kuninkaalle, mitä tämän jälkeen tapahtuu. Uni on tosi ja sen selitys luotettava.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Kuningas Nebukadnessar lankesi kasvoilleen ja kumartui maahan Danielin edessä ja käski uhrata hänelle ruokauhria ja suitsutusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Kuningas vastasi Danielille ja sanoi: \"Totisesti teidän Jumalanne on jumalien Jumala ja kuningasten herra ja se, joka paljastaa salaisuudet. Olethan voinut paljastaa tämän salaisuuden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Kuningas korotti Danielin ja antoi hänelle paljon suuria lahjoja ja asetti hänet koko Baabelin maakunnan herraksi ja kaikkien Baabelin viisaitten ylimmäksi päämieheksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Sitten Danielin anomuksesta kuningas antoi Sadrakin, Meesakin ja Abednegon hoitoon Baabelin maakunnan hallinnon. Mutta Daniel jäi kuninkaan hoviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Kuningas Nebukadnessar teetti kultaisen kuvapatsaan, jonka korkeus oli kuusikymmentä kyynärää ja leveys kuusi kyynärää. Hän pystytti sen Duuran lakeudelle Baabelin maakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Kuningas Nebukadnessar lähetti kokoamaan satraapit, maaherrat, käskynhaltijat, neuvonantajat, aarteiden hoitajat, lainoppineet, tuomarit ja kaikki muut maakuntien virkamiehet, että he tulisivat sen kuvapatsaan vihkiäisiin, jonka kuningas Nebukadnessar oli pystyttänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Silloin kokoontuivat satraapit, maaherrat, käskynhaltijat, neuvonantajat, aarteiden hoitajat, lainoppineet, tuomarit ja kaikki muut maakuntien virkamiehet sen kuvapatsaan vihkiäisiin, jonka kuningas Nebukadnessar oli pystyttänyt, ja asettuivat sen kuvapatsaan eteen, jonka kuningas Nebukadnessar oli pystyttänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Kuuluttaja huusi kovalla äänellä: \"Teille, kansat, sukukunnat ja kielet, julistetaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'heti kun kuulette torvien, huilujen, sitrojen, harppujen, luuttujen, säkkipillien ja kaikenlaisten muiden soittimien äänen, langetkaa maahan ja kumartaen rukoilkaa kultaista kuvapatsasta, jonka kuningas Nebukadnessar on pystyttänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Mutta se, joka ei lankea maahan ja kumarra, heitetään heti tuliseen pätsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Sen tähden, heti kun kaikki kansat kuulivat torvien, huilujen, sitrojen, harppujen, luuttujen, säkkipillien ja kaikenlaisten muiden soittimien äänen, lankesivat kaikki kansat, sukukunnat ja kielet maahan ja kumartaen rukoilivat kultaista kuvapatsasta, jonka kuningas Nebukadnessar oli pystyttänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Silloin astui heti kaldealaisia miehiä esiin syyttämään juutalaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'He lausuivat ja sanoivat kuningas Nebukadnessarille: \"Kuningas eläköön iankaikkisesti!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Sinä, kuningas, olet antanut käskyn, että jokainen, joka kuulee torvien, huilujen, sitrojen, harppujen, luuttujen, säkkipillien ja kaikenlaisten muiden soittimien äänen, langetkoon maahan ja kumartaen rukoilkoon kultaista kuvapatsasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'ja että joka ei lankea maahan ja kumarra, se heitetään tuliseen pätsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'On juutalaisia miehiä, joiden hoitoon sinä olet antanut Baabelin maakunnan hallinnon, Sadrak, Meesak ja Abednego: nämä miehet eivät välitä käskystäsi, kuningas. He eivät palvele jumaliasi eivätkä kumartaen rukoile kultaista kuvapatsasta, jonka olet pystyttänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Silloin Nebukadnessar vihan vimmassa käski tuoda Sadrakin, Meesakin ja Abednegon. Kun nämä miehet oli tuotu kuninkaan eteen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Nebukadnessar lausui ja sanoi heille: \"Aivanko tahallanne te, Sadrak, Meesak ja Abednego, ette tahdo palvella minun jumalaani ettekä kumartaen rukoilla kultaista kuvapatsasta, jonka olen pystyttänyt?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Nyt, jos siinä silmänräpäyksessä, kun kuulette torvien, huilujen, sitrojen, harppujen, psalttarien, säkkipillien ja kaikenlaisten muiden soittimien äänen, olette valmiit lankeamaan maahan ja kumartaen rukoilemaan kuvapatsasta, jonka olen teettänyt, niin hyvä! Mutta ellette kumarra, niin teidät heti paikalla heitetään tuliseen pätsiin, ja kuka on se jumala, joka pelastaa teidät kädestäni?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Sadrak, Meesak ja Abednego vastasivat ja sanoivat kuninkaalle: \"Nebukadnessar! Ei ole tarpeellista meidän vastata sinulle tähän sanaakaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Jos niin käy, voi Jumalamme kyllä pelastaa meidät tulisesta pätsistä, ja hän pelastaa myös sinun kädestäsi, kuningas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Ja vaikka ei pelastaisikaan, niin tiedä se, kuningas, että me emme palvele jumaliasi emmekä kumartaen rukoile kultaista kuvapatsasta, jonka olet pystyttänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Nebukadnessar tuli kiukkua täyteen Sadrakia, Meesakia ja Abednegoa kohtaan ja hänen hahmonsa muuttui. Hän käski ja sanoi, että pätsi oli kuumennettava seitsemän kertaa kuumemmaksi kuin tavallisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Hän käski sotajoukkonsa väkevimpien miesten sitoa Sadrakin, Meesakin ja Abednegon ja heittää heidät tuliseen pätsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Nämä sidottiin viittoineen, takkeineen, päähineineen ja muine vaatteineen ja heitettiin tuliseen pätsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Koska nyt kuninkaan sana oli niin ankara ja pätsi niin kovin kuumennettu, tulen liekki tappoi ne miehet, jotka veivät ylös Sadrakin, Meesakin ja Abednegon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Mutta nämä kolme miestä, Sadrak, Meesak ja Abednego, suistuivat sidottuina tuliseen pätsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Kuningas Nebukadnessar hämmästyi ja nousi kiireesti ylös ja lausui hallitusmiehilleen sanoen: \"Emmekö heittäneet kolme miestä sidottuina tuleen?\" He vastasivat ja sanoivat kuninkaalle: \"Totisesti, kuningas!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Hän vastasi ja sanoi: \"Katso, minä näen neljän miehen kävelevän vapaina tulessa, eivätkä he ole vahingoittuneet, ja neljäs on näöltään kuin Jumalan Poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Nebukadnessar meni tulisen pätsin aukolle, lausui ja sanoi: \"Sadrak, Meesak ja Abednego, te korkeimman Jumalan palvelijat, astukaa ulos ja tulkaa tänne.\" Sadrak, Meesak ja Abednego astuivat ulos tulesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Satraapit, maaherrat, käskynhaltijat ja kuninkaan hallitusmiehet kokoontuivat ja näkivät, ettei tuli ollut voinut mitään näiden miesten ruumiille, etteivät heidän päänsä hiukset olleet kärventyneet eivätkä heidän vaatteensa vioittuneet, eikä heissä tuntunut tulen käryä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Silloin Nebukadnessar lausui ja sanoi: \"Kiitetty olkoon Sadrakin, Meesakin ja Abednegon Jumala, joka lähetti enkelinsä ja pelasti palvelijansa, jotka häneen turvasivat eivätkä totelleet kuninkaan käskyä, vaan antoivat ruumiinsa alttiiksi, ennemmin kuin palvelivat ja kumartaen rukoilivat muuta jumalaa kuin omaa Jumalaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Minä annan käskyn: jokainen, olkoon mitä kansaa, kansakuntaa ja kieltä tahansa, joka puhuu pilkaten Sadrakin, Meesakin ja Abednegon Jumalasta, hakattakoon kappaleiksi ja hänen talonsa tehtäköön soraläjäksi, sillä ei ole muuta jumalaa, joka niin voi pelastaa kuin tämä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Kuningas asetti Sadrakin, Meesakin ja Abednegon suureen valtaan Baabelin maakunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 31, '\"Kuningas Nebukadnessar kaikille kansoille, kansakunnille ja kielille, jotka asuvat kaiken maan päällä! Suuri olkoon rauhanne!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 32, 'Olen nähnyt hyväksi ilmoittaa ne tunnusteot ja ihmeet, jotka korkein Jumala on minulle tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 33, 'Kuinka suuret ovat hänen tunnustekonsa ja kuinka voimalliset hänen ihmeensä! Hänen valtakuntansa on iankaikkinen valtakunta ja hänen valtansa pysyy polvesta polveen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, '\"Minä Nebukadnessar elin rauhassa huoneessani ja onnellisena palatsissani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Näin unen, ja se pelästytti minut. Unikuvat, joita minulla oli vuoteellani, pääni näyt, kauhistuttivat minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Minä annoin käskyn tuoda eteeni kaikki Baabelin viisaat, että he ilmoittaisivat minulle unen selityksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Sitten tietäjät, noidat, kaldealaiset ja tähtienselittäjät tulivat, ja minä kerroin heille unen, mutta he eivät voineet ilmoittaa minulle sen selitystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Mutta viimein tuli eteeni Daniel, jonka nimi on jumalani nimen mukaan Beltsassar ja jossa on pyhien jumalien henki, ja kerroin hänelle unen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, '\'Beltsassar, sinä tietäjien päämies, jossa minä tiedän olevan pyhien jumalien hengen ja jolle mikään salaisuus ei ole liian vaikea! Sano, mitä olivat ne näyt, jotka unessani näin, ja mikä on selitys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Nämä olivat pääni näyt, jotka minulla oli vuoteessani. Minä näin: Katso, oli puu keskellä maata, ja sen korkeus oli suuri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Puu kasvoi ja vahvistui, niin että sen latva ulottui taivaaseen ja se näkyi kaiken maan ääriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Sen lehvät olivat kauniit ja sen hedelmät suuret, ja siinä oli ravintoa kaikille. Sen alla etsivät varjoa kedon eläimet, ja sen oksilla asuivat taivaan linnut, ja kaikki liha sai siitä ravintonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Näin pääni näyissä, joita minulla oli vuoteessani: Katso, pyhä olento astui alas taivaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Hän huusi voimallisesti ja sanoi näin: \'Hakatkaa puu poikki ja karsikaa sen oksat, riipikää sen lehvät ja hajottakaa sen hedelmät. Paetkoot eläimet sen alta ja linnut sen oksilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Mutta kanto juurineen jättäkää maahan, rauta- ja vaskikahleissa kedon ruohikkoon. Taivaan kasteesta se kastukoon, ja niin kuin eläinten olkoon osanaan maan ruoho.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Hänen sydämensä muutetaan, niin ettei se ole ihmisen sydän, ja hänelle annetaan eläimen sydän. Niin kulukoon häneltä seitsemän aikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Tämä on säädetty vartioivien enkelien päätöksellä, ja niin ovat tästä asiasta pyhät sanoneet, että elossa olevat tietäisivät Korkeimman hallitsevan ihmisten valtakuntaa ja antavan sen, kenelle hän tahtoo, ja asettavan sen päämieheksi ihmisistä halvimman.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Tämän unen näin minä, kuningas Nebukadnessar. Mutta sinä, Beltsassar, sano sen selitys, koska ei yksikään valtakuntani viisaista voi minulle ilmoittaa sen selitystä. Mutta sinä sen voit, sillä sinussa on pyhien jumalien henki.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Silloin Daniel, jonka nimenä oli Beltsassar, hämmästyi hetkeksi, ja hänen ajatuksensa pelästyttivät häntä. Kuningas lausui ja sanoi: \"Beltsassar, älköön uni ja sen selitys sinua pelästyttäkö.\" Beltsassar vastasi ja sanoi: \"Herrani, koskekoon uni vihollisiasi ja sen selitys vastustajiasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Puu, jonka näit ja joka kasvoi ja vahvistui, niin että sen latva ulottui taivaaseen ja se näkyi kaikkeen maahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'jonka lehvät olivat kauniit ja hedelmät suuret ja jossa oli ravintoa kaikille, jonka alla kedon eläimet asuivat ja jonka oksilla taivaan linnut oleskelivat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, '– se puu olet sinä, kuningas, joka olet kasvanut ja vahvistunut. Sinun suuruutesi on kasvanut ja ulottuu taivaaseen ja valtasi maan ääriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Mutta se, että kuningas näki vartioivan ja pyhän olennon astuvan alas taivaasta ja sanovan: \'Hakatkaa puu poikki ja turmelkaa se, mutta jättäkää sen kanto juurineen maahan rauta- ja vaskikahleissa kedon ruohikkoon. Taivaan kasteesta hän kastukoon, ja niin kuin kedon eläinten olkoon hänen osansa, kunnes häneltä on kulunut seitsemän aikaa\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'sen selitys, oi kuningas, ja ylimmäisen päätös, joka on kohdannut herraani, kuningasta, on tämä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'Sinut ajetaan pois ihmisten parista, ja asuinpaikkasi on oleva kedon eläinten. Joudut syömään ruohoa kuin naudat, ja olet kastuva taivaan kasteesta. Sitten sinulta kuluu seitsemän aikaa, kunnes tulet tuntemaan, että Korkein hallitsee ihmisten valtakuntaa ja antaa sen, kenelle tahtoo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Mutta se, että käskettiin jättää maahan puun kanto juurineen, tietää, että valtakuntasi säilytetään sinulla, ja sinä saat sen, niin pian kuin tulet tuntemaan, että valta on taivaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Sen tähden, kuningas, kelvatkoon sinulle neuvoni. Kirvoita synnit itsestäsi vanhurskaudella ja pahat tekosi vaivaisia armahtamalla. Ehkäpä silloin onnesi jatkuu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Tämä kaikki kohtasi kuningas Nebukadnessaria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Kaksitoista kuukautta tämän jälkeen, kun kuningas oli kävelemässä kuninkaallisen palatsinsa katolla Baabelissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'hän puhkesi puhumaan sanoen: \"Eikö tämä ole se suuri Baabel, jonka minä väkevällä voimallani olen rakentanut kuninkaalliseksi linnaksi, valtasuuruuteni kunniaksi!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Vielä oli sana kuninkaan suussa, kun taivaasta tuli ääni: \"Sinulle, kuningas Nebukadnessar, julistetaan: Sinun valtakuntasi on otettu sinulta pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Sinut ajetaan pois ihmisten parista, ja kedon eläinten joukossa on oleva asuinpaikkasi. Joudut syömään ruohoa kuin naudat, ja sinulta kuluu seitsemän aikaa, kunnes tulet tuntemaan, että Korkein hallitsee ihmisten valtakuntaa ja antaa sen, kenelle tahtoo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'Sillä hetkellä sana toteutui Nebukadnessarissa. Hänet ajettiin pois ihmisten parista, ja hän söi ruohoa kuin naudat, ja hänen ruumiinsa kastui taivaan kasteesta, kunnes hänen hiuksensa kasvoivat pitkiksi kuin kotkan sulat ja hänen kyntensä kuin lintujen kynnet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, '\"Mutta sen ajan kuluttua minä, Nebukadnessar, nostin silmäni taivasta kohti, ja minun järkeni palasi. Niin minä kiitin Korkeinta, minä ylistin ja kunnioitin häntä, joka elää iankaikkisesti, jonka hallitus on iankaikkinen hallitus ja jonka valtakunta pysyy polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'Kaikki maan asukkaat ovat tyhjänveroisia, ja hän tekee, niin kuin tahtoo, taivaan joukoille ja maan asukkaille, eikä ole sitä, joka pidättää hänen kätensä ja sanoo hänelle: \'Mitä teet?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'Siihen aikaan palasi järkeni, ja palasi valtasuuruuteni ja loistoni, valtakuntani kunniaksi. Hallitusmieheni ja ylimykseni etsivät minut, ja minut pantiin jälleen hallitsemaan valtakuntaani, ja valtani kasvoi vielä lisää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Nyt minä, Nebukadnessar, kiitän, ylistän ja kunnioitan taivaan kuningasta. Sillä kaikki hänen työnsä ovat totiset ja hänen tiensä oikeat, ja hän voi nöyryyttää ne, jotka vaeltavat ylpeydessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Kuningas Belsassar laittoi suuret pidot tuhannelle ylimykselleen, ja hän joi viiniä näiden tuhannen edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Belsassar käski viiniä maistellessaan tuoda ne kulta- ja hopea-astiat, jotka hänen isänsä Nebukadnessar oli ottanut Jerusalemin temppelistä, että kuningas ja hänen ylimyksensä, hänen puolisonsa ja sivuvaimonsa joisivat niistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Silloin tuotiin ne kulta-astiat, jotka oli otettu temppelistä, Jumalan huoneesta, Jerusalemista, ja niistä joivat kuningas ja hänen ylimyksensä, hänen puolisonsa ja sivuvaimonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'He joivat viiniä ja ylistivät kultaisia ja hopeisia, vaskisia, rautaisia, puisia ja kivisiä jumalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Sillä hetkellä ilmestyivät ihmiskäden sormet ja kirjoittivat kuninkaan palatsin kalkitulle seinälle, vastapäätä lampunjalkaa, ja kuningas näki käden, joka kirjoitti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Silloin kuninkaan kasvot kalpenivat, ja hänen ajatuksensa pelästyttivät hänet. Hänen lanteittensa nivelet herposivat, ja hänen polvensa tutisivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Kuningas huusi kovalla äänellä ja käski tuoda noidat, kaldealaiset ja tähtienselittäjät. Kuningas lausui ja sanoi Baabelin tietäjille: \"Kuka ikinä voi lukea tämän kirjoituksen ja ilmoittaa minulle sen selityksen, hänet puetaan purppuraan, ja hänen kaulaansa pannaan kultakäädyt, ja hän on oleva yksi valtakunnan kolmesta valtamiehestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Silloin tulivat kaikki kuninkaan viisaat, mutta he eivät voineet lukea kirjoitusta eivätkä ilmoittaa kuninkaalle sen selitystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Kuningas Belsassar pelästyi silloin suuresti, ja hänen kasvonsa kalpenivat, ja hänen ylimyksensä kauhistuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Kuninkaan äiti tuli kuninkaan ja hänen ylimystensä puheen tähden pitohuoneeseen. Kuninkaan äiti lausui ja sanoi: \"Eläköön kuningas iankaikkisesti! Älkööt ajatuksesi pelästyttäkö sinua, älköötkä kasvosi kalvetko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Sinun valtakunnassasi on mies, jossa on pyhien jumalien henki ja jolla isäsi päivinä havaittiin olevan valistus ja ymmärrys sekä viisaus, samanlainen kuin jumalien. Hänet isäsi, kuningas Nebukadnessar, asetti tietäjien, noitien, kaldealaisten ja tähtienselittäjien päämieheksi – isäsi, kuningas –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'sen tähden, että erinomainen henki ja tieto sekä myös taito selittää unia, arvata arvoituksia ja ratkaista ongelmia havaittiin juuri hänessä, Danielissa, jolle kuningas oli antanut nimen Beltsassar. Kutsuttakoon nyt Daniel, niin hän ilmoittaa selityksen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Silloin Daniel tuotiin kuninkaan eteen. Kuningas lausui ja sanoi Danielille: \"Oletko sinä Daniel, joka on niitä juutalaisia karkotettuja, jotka isäni, kuningas, on tuonut Juudasta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Olen kuullut sinusta, että sinussa on jumalien henki ja että sinussa on havaittu valistus, taito ja erinomainen viisaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Nyt tuotiin eteeni viisaat ja noidat lukemaan tätä kirjoitusta ja ilmoittamaan minulle sen selitys, mutta he eivät voineet ilmoittaa sen selitystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Mutta sinun minä olen kuullut voivan antaa selityksiä ja ratkaista ongelmia. Nyt siis, jos voit lukea kirjoituksen ja ilmoittaa minulle sen selityksen, sinut puetaan purppuraan, ja kultakäädyt pannaan kaulaasi, ja sinä olet oleva yksi valtakunnan kolmesta valtamiehestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Silloin Daniel vastasi ja sanoi kuninkaalle: \"Lahjasi pidä itse, ja antimesi anna toiselle. Mutta kirjoituksen luen kuninkaalle ja ilmoitan hänelle sen selityksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Sinä kuningas! Korkein Jumala antoi isällesi Nebukadnessarille kuninkuuden, voiman, kunnian ja valtasuuruuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'Sen voiman tähden, jonka hän oli hänelle antanut, vapisivat kaikki kansat, kansakunnat ja kielet ja pelkäsivät hänen edessään. Hän tappoi, kenet tahtoi, hän jätti henkiin, kenet tahtoi, hän ylensi, kenet tahtoi, ja hän alensi, kenet tahtoi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Mutta kun hänen sydämensä paisui ja hänen henkensä kävi korskeaksi ja ylpeäksi, syöstiin hänet kuninkaalliselta valtaistuimeltaan, ja hänen kunniansa otettiin häneltä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Hänet ajettiin pois ihmisten parista, ja hänen sydämensä tuli eläinten sydämen kaltaiseksi. Hänen asuntonsa oli villiaasien joukossa, ja hän joutui syömään ruohoa kuin naudat. Hänen ruumiinsa kastui taivaan kasteesta, kunnes hän tuli tuntemaan, että korkein Jumala hallitsee ihmisten valtakuntaa ja asettaa päämieheksi sen, kenet tahtoo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Mutta sinä, hänen poikansa Belsassar, et ole nöyryyttänyt sydäntäsi, vaikka tämän kaiken tiesit;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'vaan olet korottanut itsesi taivaan Herraa vastaan. Hänen huoneensa astiat on tuotu eteesi, ja sinä ja ylimyksesi, puolisosi ja sivuvaimosi olette juoneet niistä viiniä, ja sinä olet ylistänyt hopeisia ja kultaisia, vaskisia, rautaisia, puisia ja kivisiä jumalia, jotka eivät näe, eivät kuule eivätkä tiedä mitään. Mutta sitä Jumalaa, jonka kädessä on henkesi ja kaikki tiesi, sinä et ole kunnioittanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Sen tähden tämä käsi on lähetetty hänen luotaan ja tämä kirjoitus kirjoitettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Tämä on kirjoitus, joka on tuonne kirjoitettu: \'Mene, mene, tekel, ufarsin.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Tämä on sen selitys: mene merkitsee: Jumala on laskenut sinun valtakuntasi luvun ja on tehnyt siitä lopun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Tekel: sinut on vaa\'alla punnittu ja köykäiseksi havaittu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Peres: sinun valtakuntasi on pirstottu ja annettu meedialaisille ja persialaisille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Silloin Belsassar antoi käskyn, että Daniel oli puettava purppuraan ja kultakäädyt pantava hänen kaulaansa ja julistettava, että hän oli yksi valtakunnan kolmesta valtamiehestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Samana yönä tapettiin Belsassar, kaldealaisten kuningas,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'ja Daarejaves, meedialainen, sai haltuunsa valtakunnan ollessaan noin kuudenkymmenen kahden vuoden ikäinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Daarejaves näki hyväksi asettaa valtakuntaansa sata kaksikymmentä satraappia, että heitä olisi kaikkialla valtakunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Heidän yläpuolellaan oli kolme valtaherraa, joista Daniel oli yksi. Heille tuli satraappien tehdä tili, ettei kuningas kärsisi vahinkoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Mutta Daniel oli etevämpi muita valtaherroja sekä satraappeja, sillä hänessä oli erinomainen henki. Kuningas aikoi asettaa hänet koko valtakunnan päämieheksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Silloin toiset valtaherrat sekä satraapit etsivät Danielia vastaan syytä valtakunnan hallinnossa. Mutta he eivät voineet löytää mitään syytä eivätkä rikosta, sillä hän oli uskollinen, eikä hänestä löydetty laiminlyöntiä eikä rikosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Silloin nämä miehet sanoivat: \"Me emme löydä tuossa Danielissa mitään syytä – ellemme löydä sitä hänen jumalanpalveluksessaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Sen jälkeen nämä valtaherrat ja satraapit riensivät kiireesti kuninkaan tykö ja sanoivat hänelle näin: \"Kuningas Daarejaves eläköön iankaikkisesti!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Kaikki kuninkaalliset valtaherrat, maaherrat, satraapit, hallitusmiehet ja käskynhaltijat ovat keskenään neuvotelleet, että olisi annettava kuninkaallinen julistus ja vahvistettava kielto, että kuka ikinä kolmenkymmenen päivän kuluessa rukoilee jotakin yhdeltäkään jumalalta tai ihmiseltä, paitsi sinulta, kuningas, se heitettäköön leijonien luolaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Nyt, kuningas! Säädä kielto ja kirjoita kirjoitus, jota meedialaisten ja persialaisten lain mukaan ei voida muuttaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Kuningas Daarejaves kirjoitti kirjoituksen ja kiellon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Niin pian kuin Daniel oli saanut tietää, että kirjoitus oli kirjoitettu, hän meni taloonsa, jonka yläsalin ikkunat olivat avatut Jerusalemiin päin. Hän lankesi kolmena hetkenä päivässä polvilleen, rukoili ja kiitti Jumalaansa, aivan kuten hän ennenkin oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Silloin nuo miehet riensivät kiireesti sinne ja tapasivat Danielin rukoilemasta ja huutamasta avuksi Jumalaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Sitten he astuivat kuninkaan eteen ja muistuttivat kuninkaan kiellosta: \"Etkö ole kirjoittanut kieltoa, että kuka ikinä kolmenkymmenen päivän kuluessa rukoilee jotakin yhdeltäkään jumalalta tai ihmiseltä, paitsi sinulta, kuningas, se heitettäköön leijonien luolaan?\" Kuningas vastasi ja sanoi: \"Kielto on luja, meedialaisten ja persialaisten peruuttamattoman lain mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Silloin he vastasivat ja sanoivat kuninkaalle: \"Daniel, joka on karkotettuja juutalaisia, ei välitä sinusta, kuningas, eikä kiellosta, jonka olet kirjoittanut, vaan hän toimittaa rukouksensa kolmena hetkenä päivässä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Mutta kun kuningas sen kuuli, hän tuli sangen murheelliseksi ja mietti, miten voisi pelastaa Danielin. Auringon laskuun asti hän vaivasi itseään vapauttaakseen hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Silloin ne miehet riensivät kiireesti kuninkaan tykö ja sanoivat kuninkaalle: \"Tiedä, kuningas, meedialaisten ja persialaisten laki on, ettei mitään kuninkaan vahvistamaa kieltoa tai julistusta peruuteta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Silloin kuningas käski tuoda Danielin ja heittää hänet leijonien luolaan. Sitten kuningas puhui Danielille ja sanoi: \"Sinun Jumalasi, jota sinä lakkaamatta palvelet, pelastakoon sinut.\" Sitten tuotiin kivi ja pantiin luolan suulle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'ja kuningas sinetöi sen omallaan ja ylimystensä sineteillä, ettei Danielin asiassa muutosta tapahtuisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Sitten kuningas meni palatsiinsa ja vietti yönsä paastoten eikä sallinut tuoda eteensä naisia, ja hänen unensa pakeni häneltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Aamun sarastaessa kuningas sitten nousi ja meni kiireesti leijonien luolalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Mutta lähestyessään luolaa hän huusi Danielille murheellisella äänellä, ja kuningas lausui ja sanoi Danielille: \"Daniel, sinä elävän Jumalan palvelija, onko Jumalasi, jota lakkaamatta palvelet, voinut pelastaa sinut leijonilta?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Silloin Daniel vastasi kuninkaalle: \"Kuningas eläköön iankaikkisesti!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Jumalani on lähettänyt enkelinsä ja sulkenut leijonien kidat, niin etteivät ne ole minua vahingoittaneet, sillä minut on havaittu nuhteettomaksi hänen edessään, enkä minä ole sinuakaan vastaan, kuningas, rikosta tehnyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Silloin kuningas ilahtui suuresti ja käski ottaa Danielin ylös luolasta. Kun Daniel oli otettu ylös luolasta, hänessä ei havaittu mitään vammaa, sillä hän oli turvannut Jumalaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Mutta kuningas käski tuoda ne miehet, jotka olivat syyttäneet Danielia, ja heittää heidät lapsineen ja vaimoineen leijonien luolaan. He eivät ehtineet luolan pohjaan, ennen kuin leijonat hyökkäsivät heidän kimppuunsa ja murskasivat kaikki heidän luunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Sitten kuningas Daarejaves kirjoitti kaikille kansoille, kansakunnille ja kielille, mitä koko maan päällä asuu: \"Suuri olkoon rauhanne!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Minä olen antanut käskyn, että valtakuntani koko valtapiirissä vavistakoon ja pelättäköön Danielin Jumalaa. Sillä hän on elävä Jumala ja pysyy iankaikkisesti. Hänen valtakuntansa ei häviä, eikä hänen valtansa lopu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Hän pelastaa ja vapahtaa, hän tekee tunnustekoja ja ihmeitä taivaassa ja maan päällä, hän, joka pelasti Danielin leijonien kynsistä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 29, 'Sitten tämä Daniel oli korkeassa arvossa ja kunniassa Daarejaveksen valtakunnassa sekä persialaisen Kooreksen valtakunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Belsassarin, Baabelin kuninkaan, ensimmäisenä hallitusvuotena Daniel näki unen, päänsä näyn, vuoteessaan. Sitten hän kirjoitti tämän unen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Kertomuksen alku on tämä: Daniel lausui ja sanoi: Näin yöllä näyssäni, ja katso, taivaan neljä tuulta kuohutti suurta merta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Merestä nousi neljä suurta petoa, kukin erilainen kuin toinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Ensimmäinen oli kuin leijona, mutta sillä oli kotkan siivet. Sitä katsellessani reväistiin siltä siivet, ja se nostettiin maasta pystyyn ja asetettiin kahdelle jalalle niin kuin ihminen, ja sille annettiin ihmisen sydän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Katso, oli toinen peto, joka oli karhun näköinen. Se nostettiin toiselle kyljelleen, ja sillä oli suussa kolme kylkiluuta hammasten välissä. Sitten sille sanottiin näin: \"Nouse ja syö paljon lihaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Tämän jälkeen näin, ja katso, oli taas toinen peto, pantterin kaltainen, ja sen selässä oli neljä linnunsiipeä. Pedolla oli neljä päätä, ja sille annettiin valta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Sen jälkeen näin yöllisessä näyssäni, ja katso, oli neljäs peto, kauhea, hirmuinen ja hyvin väkevä. Sillä oli suuret rautaiset hampaat, ja se söi, murskasi ja tallasi tähteet jalkoihinsa. Se oli erilainen kuin kaikki edelliset pedot, ja sillä oli kymmenen sarvea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Tarkkailin sarvea, ja katso, eräs muu pieni sarvi puhkesi niiden välistä, ja kolme edellisistä sarvista reväistiin pois sen edestä. Katso, sarvella oli silmät kuin ihmisen silmät, ja suu, joka puhui herjaten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Sitä katsellessani valtaistuimet asetettiin, ja Ikivanha istuutui. Hänen vaatteensa olivat valkoiset kuin lumi ja hänen päänsä hiukset kuin puhdas villa. Hänen valtaistuimensa oli tulen liekkejä, ja sen pyörät olivat palavaa tulta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Tulivirta virtasi ja kävi ulos hänen edestään. Tuhannen tuhatta palveli häntä, ja kymmenen tuhatta kertaa kymmenen tuhatta seisoi hänen edessään. Oikeus istui tuomiolle, ja kirjat avattiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Katselin, ja silloin niiden herjaavien sanojen tähden, joita sarvi puhui, sitä katsellessani peto tapettiin, ja sen ruumis hävitettiin ja heitettiin tuleen palamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Muiltakin pedoilta otettiin valta pois. Niiden elämän pituus oli määrätty aikaa ja hetkeä myöten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Näin yöllisessä näyssä, ja katso, taivaan pilvissä tuli Ihmisen Pojan kaltainen. Hän saapui Ikivanhan luo, ja hänet saatettiin tämän eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Hänelle annettiin valta, kunnia ja valtakunta, ja kaikki kansat, kansakunnat ja kielet palvelivat häntä. Hänen valtansa on iankaikkinen valta, joka ei lakkaa, ja hänen valtakuntansa on valtakunta, joka ei häviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Minä, Daniel, tunsin henkeni tulevan murheelliseksi ruumiissani, ja näkemäni näyt pelästyttivät minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Lähestyin yhtä siellä seisovista ja pyysin häneltä varmaa tietoa kaikista näistä asioista. Hän vastasi minulle ja ilmoitti minulle niiden selityksen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, '\"Nuo suuret pedot, joita on neljä, on neljä kuningasta, jotka nousevat maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Mutta Korkeimman pyhät saavat valtakunnan ja omistavat valtakunnan iankaikkisesti – iankaikkisesta iankaikkiseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Sen jälkeen halusin saada varmuuden neljännestä pedosta, joka oli erilainen kuin kaikki muut ja hyvin kauhea, jolla oli rautaiset hampaat ja vaskiset kynnet, joka söi ja murskasi ja tallasi tähteet jalkoihinsa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'sekä pedon pään kymmenestä sarvesta sekä siitä sarvesta, joka puhkesi ja jonka edestä kolme putosi, jolla sarvella oli silmät ja herjauksia puhuva suu ja joka näytti suuremmalta kuin ne muut;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'se sarvi, jonka näin sotivan pyhiä vastaan ja voittavan heidät,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'siihen asti kunnes Ikivanha tuli ja oikeus annettiin Korkeimman pyhille ja aika joutui ja pyhät saivat omakseen valtakunnan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Hän vastasi näin: \"Neljäs peto on neljäs valtakunta, joka syntyy maan päälle, erilainen kuin kaikki muut valtakunnat. Se syö kaiken maan ja tallaa ja murskaa sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Ne kymmenen sarvea ovat kymmenen kuningasta, jotka nousevat siitä valtakunnasta. Heidän jälkeensä nousee eräs muu, ja hän on erilainen kuin edelliset, ja hän kukistaa kolme kuningasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Hän puhuu sanoja Korkeinta vastaan ja hävittää Korkeimman pyhiä. Hän pyrkii muuttamaan ajat ja lain, ja ne annetaan hänen käteensä ajaksi ja kahdeksi ajaksi ja puoleksi ajaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Sitten oikeus istuu tuomiolle, ja hänen valtansa otetaan pois ja hävitetään ja tuhotaan lopullisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Valtakunta ja valta ja valtakuntien voima kaiken taivaan alla annetaan Korkeimman pyhien kansalle. Hänen valtakuntansa on iankaikkinen valtakunta, ja kaikki vallat palvelevat häntä ja ovat hänelle alamaisia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Tähän loppuu kertomus. Minua, Danielia, pelästyttivät ajatukseni suuresti, ja kasvoni kalpenivat, ja kätkin asian sydämeeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Kuningas Belsassarin kolmantena hallitusvuotena minä, Daniel, näin näyn, sen jälkeen kun minulla jo ennen oli ollut näky.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Kun minä näyssä katselin, havaitsin olevani Suusanin linnassa, Eelamin maakunnassa; ja kun näyssä katselin, minä olin Uulai-joen rannalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Nostin silmäni ja katsoin. Ja katso, pässi seisoi joen rannalla, ja sillä oli kaksi sarvea. Sarvet olivat korkeat, ja toinen oli toista korkeampi, ja korkeampi puhkesi esiin myöhemmin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Näin pässin puskevan länteen, pohjoiseen ja etelään päin, eikä yksikään eläin kestänyt sen edessä, eikä kukaan voinut pelastaa sen vallasta. Se teki, mitä tahtoi, ja tuli suureksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Sitten minä havaitsin, ja katso: pukki tuli päivän laskun puolelta, meni koko maan yli eikä koskettanut maata, ja pukilla oli silmien välissä iso sarvi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Sitten se tuli aivan kaksisarvisen pässin luo, jonka olin nähnyt seisovan joen rannalla, ja syöksyi sen kimppuun vihansa voimalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Sitten näin sen käyvän kiinni pässiin ja kiukuissaan puskevan pässiä ja murskaavan sen molemmat sarvet. Pässillä ei ollut voimaa kestää sen edessä, vaan pukki heitti sen maahan ja tallasi sitä, eikä ollut ketään, joka olisi voinut pelastaa pässin sen vallasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Niin pukki tuli hyvin suureksi. Mutta kun se oli väkevimmillään, särkyi suuri sarvi, ja sen sijalle kasvoi neljä suurta sarvea taivaan neljään tuuleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Sitten yhdestä niistä puhkesi esiin yksi vähäpätöinen sarvi. Se kasvoi suuresti etelään, itään ja Ihanaan maahan päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Se kasvoi taivaan sotajoukkoon asti ja pudotti maahan osan siitä sotajoukosta ja tähdistä ja tallasi niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Hän ylpeili sotajoukon Ruhtinastakin vastaan, ja tältä otettiin pois jokapäiväinen uhri, ja hänen pyhäkkönsä perustuksesta luovuttiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Jokapäiväisen uhrin lisäksi sotajoukkokin annettiin rikollisesti alttiiksi tuholle. Se sarvi heitti totuuden maahan, ja mitä se teki, siinä se menestyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Sitten kuulin yhden pyhän puhuvan, ja toinen pyhä sanoi sille, joka puhui: \"Kuinka pitkää aikaa tarkoittaa näky jokapäiväisestä uhrista ja kauhistavasta rikoksesta: pyhäkön ja sotajoukon alttiiksi antamisesta tallattavaksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Niin hän sanoi minulle: \"Kahtatuhatta kolmeasataa iltaa ja aamua. Sitten pyhäkkö asetetaan jälleen oikeuteensa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Kun minä, Daniel, olin nähnyt tämän näyn ja koetin sitä ymmärtää, niin katso, edessäni seisoi miehen näköinen olento.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Sitten kuulin ihmisen äänen Uulain keskeltä, ja se huusi ja sanoi: \"Gabriel, selitä tälle näky!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Silloin hän tuli aivan lähelle sitä paikkaa, jossa seisoin; ja hänen tullessaan minut valtasi pelko, ja lankesin kasvoilleni. Hän sanoi minulle: \"Ymmärrä, ihmislapsi, että näky tarkoittaa lopun aikaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Kun hän puhui minulle, olin horroksissa kasvot maata vasten, mutta hän tarttui minuun ja nosti minut seisomaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Sitten hän sanoi: \"Katso, minä ilmoitan sinulle, mitä tapahtuu viimeisenä vihan aikana, sillä se tarkoittaa määrättyä lopun aikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Kaksisarvinen pässi, jonka näit, on: Meedian ja Persian kuninkaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Mutta vuohipukki on Jaavanin kuningas, ja suuri sarvi, joka sillä oli keskellä otsaa, on ensimmäinen kuningas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Se, että se särkyi ja neljä nousi sen sijaan, on: neljä valtakuntaa nousee siitä kansasta, ei kuitenkaan niin väkevää kuin hän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Heidän valtansa lopulla, kun luopiot ovat täyttäneet syntiensä mitan, nousee kuningas, kasvoilta röyhkeä ja juonissa taitava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Väkevä on hänen voimansa, vaikka ei tosin hänen omasta voimastaan, ja ihmeellisen paljon hän saa aikaan hävitystä. Hän menestyy siinä, mitä hän tekee, ja hän tuottaa turmion väkeville ja pyhien kansalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Ja hänen oveluutensa tähden onnistuu petos hänen kädessään. Hän hautoo suuria sydämessään, ja keskellä rauhaa hän tuottaa turmion monille. Ruhtinasten Ruhtinastakin vastaan hän nousee, mutta ilman ihmiskättä hänet muserretaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Näky illoista ja aamuista, josta oli puhe, on tosi. Mutta lukitse sinä näky, sillä se tarkoittaa kaukaista aikaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Sitten minä, Daniel, olin raukea ja sairastin jonkin aikaa. Sitten nousin ja toimitin palvelusta kuninkaan luona. Olin hämmästynyt näyn tähden enkä sitä ymmärtänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Daarejaveksen, Ahasveroksen pojan, ensimmäisenä hallitusvuotena, hänen, joka oli meedialaista sukua ja oli tullut kaldealaisten valtakunnan kuninkaaksi –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'hänen ensimmäisenä hallitusvuotenaan, minä, Daniel, huomasin Kirjoituksista vuosien luvun, josta Herran sana oli tullut profeetta Jeremialle, että Jerusalem oli oleva raunioina seitsemänkymmentä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Käänsin kasvoni Herran Jumalan puoleen etsiäkseni häntä rukouksessa ja anomisessa, paastossa, säkissä ja tuhkassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Minä rukoilin Herraa, Jumalaani, tunnustin ja sanoin: \"Oi Herra, sinä suuri ja pelottava Jumala, joka pidät liiton ja säilytät laupeuden niille, jotka sinua rakastavat ja pitävät käskysi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Me olemme tehneet syntiä, olemme tehneet väärin, olleet jumalattomat ja uppiniskaiset, olemme poikenneet pois käskyistäsi ja oikeuksistasi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'emmekä ole kuulleet palvelijoitasi, profeettoja, jotka puhuivat nimessäsi kuninkaillemme, ruhtinaillemme ja isillemme ja kaikelle maan kansalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Sinun, Herra, on vanhurskaus, mutta meidän on häpeä, niin kuin se on tänä päivänä Juudan miesten ja Jerusalemin asukkaiden ja koko Israelin, läheisten ja kaukaisten, kaikissa maissa, joihin sinä olet heidät karkottanut heidän uskottomuutensa tähden, jota he ovat sinulle osoittaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Herra, meidän on häpeä, kuninkaittemme, ruhtinaittemme ja isiemme, koska olemme tehneet syntiä sinua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Herran, meidän Jumalamme, on armo ja anteeksiantamus, sillä häntä kohtaan me olemme olleet uppiniskaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'Emme ole kuulleet Herran, meidän Jumalamme, ääntä emmekä vaeltaneet hänen laissaan, jonka hän asetti eteemme palvelijoidensa, profeettojen, kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Vaan koko Israel rikkoi lakisi ja poikkesi pois eikä kuullut ääntäsi, ja niin vuodatettiin päällemme se kirous ja vala, joka on kirjoitettu Mooseksen, Jumalan palvelijan, laissa, sillä me olimme tehneet syntiä Jumalaa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Hän toteutti sanansa, jonka hän on puhunut meitä ja tuomareitamme vastaan, jotka meitä tuomitsivat, ja antoi tulla päällemme niin suuren onnettomuuden, ettei sellaista, mitä Jerusalemissa tapahtui, ole tapahtunut koko taivaan alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Niin kuin on kirjoitettu Mooseksen laissa, niin kaikki tämä onnettomuus tuli päällemme. Mutta emme koettaneet lepyttää Herraa, Jumalaamme, niin että olisimme kääntyneet pois synneistämme ja ottaneet vaarin totuudestasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Sen tähden Herra valvoi ja antoi tämän onnettomuuden tulla päällemme, sillä Herra, meidän Jumalamme, on vanhurskas kaikissa töissään, jotka hän tekee, mutta emme ole kuulleet hänen ääntään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Mutta nyt, Herra, meidän Jumalamme, joka toit kansasi pois Egyptin maasta väkevällä kädellä ja teit itsellesi nimen, niin kuin se vielä tänä päivänä on:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Herra, kaiken vanhurskautesi tähden, kääntyköön vihasi ja kiivautesi pois kaupungistasi Jerusalemista, pyhästä vuorestasi. Sillä meidän syntiemme tähden ja isiemme pahojen tekojen tähden on Jerusalem ja kansasi tullut kaikkien häväistäväksi, jotka ympärillämme ovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Mutta nyt, Jumalamme, kuule palvelijasi rukous ja hänen anomisensa ja valista kasvosi pyhäkkösi yli, joka on autiona, Herran tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Jumalani, kallista korvasi ja kuule, avaa silmäsi ja katso hävitystämme ja sitä kaupunkia, joka on otettu nimiisi, sillä me annamme rukoustemme langeta eteesi, emme omaan vanhurskauteemme, vaan sinun suureen armoosi luottaen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Herra, kuule, Herra, anna anteeksi, Herra, huomaa ja tee tekosi itsesi tähden, älä viivyttele, Jumalani, sillä kaupunkisi ja kansasi ovat otetut nimiisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Vielä minä puhuin, rukoilin ja tunnustin syntini ja kansani Israelin synnit ja annoin rukoukseni langeta Herran, Jumalani, eteen Jumalani pyhän vuoren puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'Mutta kun minä vielä puhuin rukouksessa, tuli se mies, Gabriel, jonka olin nähnyt ennen näyssä, nopeasti lentäen luokseni ja kosketti minua iltauhrin aikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Hän opetti minua, puhui minulle ja sanoi: \"Daniel, nyt olen lähtenyt neuvomaan sinua ymmärrykseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Kun aloit rukoilla, lähti liikkeelle sana, ja minä olen tullut sitä ilmoittamaan, sillä sinä olet rakas. Käsitä siis se sana ja ymmärrä näky.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Seitsemänkymmentä viikkoa on säädetty kansallesi ja pyhälle kaupungillesi. Silloin luopumus päättyy, ja synti sinetillä lukitaan, ja pahat teot sovitetaan, ja iankaikkinen vanhurskaus tuodaan, ja näky ja profeetta sinetillä vahvistetaan, ja kaikkeinpyhin voidellaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Niin tiedä ja käsitä: siitä ajasta, jolloin tuli se sana, että Jerusalem on jälleen rakennettava, Voideltuun, Ruhtinaaseen, asti, on kuluva seitsemän vuosiviikkoa; ja kuusikymmentäkaksi vuosiviikkoa, niin se jälleen rakennetaan toreineen ja vallihautoineen, mutta keskellä ahtaita aikoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Sitten kuudenkymmenen kahden vuosiviikon mentyä tuhotaan Voideltu, mutta ei hänen itsensä tähden. Kaupungin ja pyhäkön hävittää hyökkäävän ruhtinaan väki, ja sen loppu on kuin tulvassa. Sodan loppuun asti on säädetty hävitys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Hän vahvistaa liiton monille yhden vuosiviikon ajaksi, ja puoleksi vuosiviikoksi hän lakkauttaa teurasuhrin ja ruokauhrin. Silloin hävittäjä tulee kauhistuksen siivillä. Tämä loppuu vasta, kun säädetty tuomio vuodatetaan hävittäjän yli.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Persian kuninkaan Kooreksen kolmantena hallitusvuotena ilmoitettiin sana Danielille, jota kutsuttiin Beltsassariksi, ja tämä sana on tosi ja merkitsee suurta sodankäyntiä. Niin hän ymmärsi sanan, ja näky oli hänelle ymmärrettävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'Niinä päivinä minä, Daniel, murehdin kolmen viikon päivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Herkullista ruokaa en syönyt, liha ja viini eivät tulleet suuhuni, enkä voidellut itseäni öljyllä, ennen kuin kolmen viikon päivät olivat kuluneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'Ensimmäisen kuun kahdentenakymmenentenä neljäntenä päivänä minä olin suuren virran, Hiddekelin, rannalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'Nostin silmäni ja näin, ja katso: oli eräs mies, puettuna pellavavaatteisiin ja lanteet vyötettyinä Uufaan kullalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Hänen ruumiinsa oli kuin krysoliitti, hänen kasvonsa olivat näöltään kuin salama, hänen silmänsä kuin tulisoihdut, hänen käsivartensa ja jalkansa kuin välkehtivä vaski, ja hänen sanojensa ääni oli kuin kansanjoukon pauhina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Niin minä, Daniel, yksin näin näyn, mutta miehet, jotka olivat kanssani, eivät näkyä nähneet. Kuitenkin heidät valtasi suuri pelko, ja he pakenivat ja piiloutuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Silloin minä jäin yksin ja katselin tätä suurta näkyä, mutta minussa ei ollut enää voimaa. Kasvojeni loiste hävisi, eikä minussa ollut voimaa mihinkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Kuulin hänen sanojensa äänen ja kuullessani hänen sanojensa äänen vaivuin horroksiin kasvoilleni, kasvot maata vasten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Katso, käsi kosketti minua ja asetti minut polvieni ja kämmenteni varaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Sitten hän sanoi minulle: \"Daniel, sinä rakastettu mies, ymmärrä sanat, jotka sinulle puhun, ja nouse seisomaan, sillä minut on nyt lähetetty luoksesi.\" Kun hän oli puhunut minulle tämän sanan, nousin vavisten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Mutta hän sanoi minulle: \"Älä pelkää, Daniel, sillä ensimmäisestä päivästä asti, jona sinä taivutit sydämesi ymmärrykseen ja nöyryyteen Jumalasi edessä, ovat sanasi tulleet kuulluiksi, ja sanojesi tähden minä olen tullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Persian valtakunnan ruhtinas seisoi vastustamassa minua kaksikymmentäyksi päivää, mutta katso, Miikael, yksi ensimmäisistä enkeliruhtinaista, tuli avukseni. Minä olin näet jäänyt yksin sinne, Persian kuningasten luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Mutta tulin opettamaan sinulle, mitä tapahtuu kansallesi päivien lopulla; sillä vielä tämäkin näky koskee niitä päiviä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Niin hänen näitä minulle puhuessaan käänsin kasvoni maahan päin ja olin vaiti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Katso, olento, ihmislasten muotoinen, kosketti huuliani. Silloin avasin suuni ja puhuin ja sanoin edessäni seisovalle: \"Herrani, nähdessäni näyn valtasi minut tuska eikä minussa ollut enää voimaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Kuinka herrani palvelija, tällainen kuin minä, voi puhutella sellaista, kuin herrani on? Sillä siitä asti minussa ei ole voimaa, ja hengitykseni on salpautunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Silloin kosketti minua jälleen se ihmisen muotoinen ja vahvisti minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'Hän sanoi: \"Älä pelkää, sinä rakastettu mies, rauha sinulle. Vahvistu! Vahvistu!\" Niin hänen puhuessaan minulle vahvistuin ja sanoin: \"Puhukoon herrani, sillä sinä olet minua vahvistanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Sitten hän sanoi: \"Tiedätkö, mitä varten olen tullut luoksesi? Nyt minä käyn jälleen sotimaan Persian ruhtinasta vastaan, ja kun poistun, niin katso: tulee Jaavanin ruhtinas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Mutta totisesti ilmoitan sinulle, mitä on kirjoitettuna totuuden kirjassa. Eikä ole ketään muuta vahvistamassa minua heitä vastaan paitsi ruhtinaanne Miikael.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Minä seisoin meedialaisen Daarejaveksen ensimmäisenä hallitusvuotena vahvistamassa ja suojelemassa häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Ja nyt ilmoitan sinulle totuuden: Katso, vielä nousee kolme kuningasta Persiassa, ja neljäs rikastuu kaikkia muita rikkaammaksi. Ja kun hän on vahvistunut rikkaudessaan, hän panee kaiken liikkeelle Jaavanin valtakuntaa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Sitten nousee sankarikuningas. Hän hallitsee suurella vallalla ja tekee, mitä tahtoo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Mutta juuri kun hän on noussut, hänen valtakuntansa hajoaa ja jakaantuu neljään taivaan tuuleen. Se ei siirry hänen jälkeläisilleen eikä ole niin mahtava kuin hänen hallitessaan. Sillä hänen valtakuntansa kukistuu ja joutuu muille, ei heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Sitten Etelän kuningas on voimistuva sekä yksi hänen ruhtinaistaan. Tämä on voimistuva vielä enemmän kuin hän, ja hänen valtansa on oleva suuri valta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Ja vuosien kuluttua he tekevät keskenään liiton, ja Etelän kuninkaan tytär menee Pohjoisen kuninkaan luo saadakseen aikaan sopimuksen. Mutta häneltä menee hänen käsivartensa voima, eikä Pohjoisen kuningas ja hänen käsivartensa pysy. Mutta tytär itse annetaan alttiiksi ja ne, jotka olivat hänet tuoneet, ja hänen siittäjänsä ja se, joka auttoi häntä noina aikoina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Sitten hänen juurtensa vesoista eräs nousee hänen sijaansa ja tulee sotajoukon mukana, tulee Pohjoisen kuninkaan linnoitukseen ja toimii heitä vastaan ja voimistuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Myös heidän jumalansa ja valetut kuvansa ja kallisarvoiset astiansa, hopeat ja kullat hän vie saaliinaan Egyptiin. Sitten hän kestää muutaman vuoden Pohjoisen kuninkaan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Tämä hyökkää Etelän kuninkaan valtakuntaan, mutta palaa takaisin maahansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Sitten hänen poikansa varustautuvat ja kokoavat suuret sotavoimat, ja yksi heistä hyökkää tulvana, tulee toistamiseen ja tunkeutuu hänen turvapaikkaansa asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Silloin Etelän kuningas julmistuu ja lähtee sotimaan häntä, Pohjoisen kuningasta vastaan. Tämä nostattaa suuren joukon, mutta joukko joutuu hänen valtaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Kun hän on sitten raivannut pois tuon joukon, hänen sydämensä paisuu. Hän kaataa kymmeniä tuhansia, mutta ei vahvistu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Pohjoisen kuningas palaa ja tuo sotajoukon, ensimmäistä suuremman, ja muutaman ajan, muutaman vuoden kuluttua tulee suurella sotavoimalla ja runsaasti varustettuna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'Niinä aikoina monet nousevat Etelän kuningasta vastaan, ja omasta kansastasi nousee väkivallan miehiä, että näky kävisi toteen, mutta he itse lankeavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Silloin Pohjoisen kuningas tulee, luo vallin ja valloittaa linnoitetun kaupungin. Sitä eivät kestä Etelän käsivarret, ei sen valioväki, eikä sillä ole voimaa seistä sitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Mutta se, joka hyökkää sitä vastaan, tekee, mitä tahtoo, eikä kukaan kestä hänen edessään. Hän asettuu Ihanaan maahan, ja hävitys tulee hänen kätensä kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Ja hän aikoo hyökätä valtakuntansa koko voimalla ja oikeamieliset hänen kanssaan, ja toteuttaa sen. Hän antaa hänelle tyttärensä vaimoksi tuhotakseen sen. Mutta se ei onnistu eikä siitä ole hänelle etua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Sitten hän kääntyy rantamaita vastaan ja ottaa valtaansa monet. Mutta eräs sotapäällikkö tekee hänen herjauksistaan lopun ja kostaa hänelle hänen herjauksensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Silloin hän kääntyy oman maansa linnoituksiin, mutta kompastuu ja kaatuu, eikä häntä enää ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Mutta hänen sijaansa nousee eräs, joka antaa veronkantajan käydä läpi valtakunnan ihanimman maan. Mutta muutamien päivien kuluttua hänet tuhotaan, ei kuitenkaan vihalla eikä sodalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Sitten hänen sijaansa nousee kelvoton, joka ei ollut saava kuninkaallista arvoa. Hän tulee keskellä rauhaa ja anastaa juonilla kuninkuuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Mutta sotajoukkojen tulva huuhtoutuu pois hänen edestään ja menee murskaksi, niin myös liiton ruhtinas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Siitä lähtien kun liittoudutaan hänen kanssaan, hän harjoittaa petosta. Hän lähtee liikkeelle ja saa ylivallan vähällä väellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Hän tulee maakunnan rauhallisiin ja hedelmällisiin seutuihin ja tekee, mitä eivät hänen isänsä eivätkä hänen isiensä isät olleet tehneet: ryöstösaalista ja tavaraa hän jakelee, ja linnoituksia vastaan hän punoo juoniaan säädettyyn aikaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Sitten hän panee liikkeelle voimansa ja rohkeutensa Etelän kuningasta vastaan hyökäten suurella sotajoukolla. Mutta Etelän kuningas varustautuu sotaan suurella ja erittäin väkevällä sotajoukolla. Hän ei kuitenkaan kestä, sillä häntä vastaan juonitellaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Ne, jotka syövät hänen ruokaansa, tuhoavat hänet, ja hänen sotajoukkonsa huuhdotaan pois, ja monet kaatuvat surmattuina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Kumpikin kuningas punoo juonia toinen toistaan vastaan. Samassa pöydässä he puhuvat valhetta. Mutta se ei onnistu, sillä määräaika ei ole vielä lopussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Hän palaa maahansa paljoine tavaroineen ja miettii juonia pyhää liittoa vastaan. Hän toteuttaa ne ja palaa maahansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Määräaikana hän palaa ja tulee Etelämaahan, mutta tällä viimeisellä retkellä ei käy kuin ensimmäisellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Häntä vastaan hyökkäävät kittiläisten laivat, ja hän menettää rohkeutensa, kääntyy takaisin ja purkaa kiukkuaan pyhää liittoa vastaan. Kotiin palattuaan hän suo huomiota niille, jotka hylkäävät pyhän liiton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Hänen lähettämänsä sotajoukot nousevat ja häpäisevät pyhäkön linnoituksineen, poistavat jokapäiväisen uhrin ja asettavat sinne hävityksen kauhistuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Liitonrikkojat hän viettelee luopumukseen houkutuksillaan, mutta niiden joukko, jotka tuntevat Jumalansa, pysyy lujana ja tekee tehtävänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Taidolliset kansan seassa opettavat monia, mutta heitä ahdistetaan miekalla, tulella, vankeudella ja ryöstöllä jonkin aikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Mutta keskellä sortoa heille suodaan vähäksi aikaa menestystä, ja monet liittyvät heihin teeskennellen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Taidollisista jotkut kompastuvat, että heidän joukkonsa koeteltaisiin, kirkastettaisiin ja puhdistettaisiin lopun ajaksi, sillä vielä kestää, ennen kuin määräaika on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Kuningas tekee, mitä tahtoo, ja korottaa itsensä ja ylpeilee jokaista jumalaa vastaan ja itse jumalien Jumalaa vastaan hän puhuu outoja. Hän menestyy, kunnes vihan aika on lopussa. Sillä se, mitä on säädetty, tapahtuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Hän ei välitä isiensä jumalista, ei naisten lempijumalasta, eikä hän välitä mistään muustakaan jumalasta, sillä hän ylvästelee niitä kaikkia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Mutta sen sijaan hän kunnioittaa linnoitusten jumalaa. Sitä jumalaa, jota hänen isänsä eivät tunteneet, hän kunnioittaa kullalla ja hopealla, kalliilla kivillä ja muilla kalleuksilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'Tätä hän tekee vahvoille linnoituksille – hän vieraan jumalansa kanssa. Niille, jotka hän tuntee omikseen, hän osoittaa suurta kunniaa ja panee heidät monien hallitsijaksi ja jakaa heille maata palkaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Mutta lopun ajalla Etelän kuningas iskee yhteen hänen kanssaan. Pohjoisen kuningas käy tuulispäänä tämän kimppuun vaunuilla ja ratsuilla ja monilla laivoilla, hyökkää hänen maihinsa tulvana leviten niiden yli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Hän hyökkää myös Ihanaan maahan, ja monta kaatuu. Mutta hänen kädestään pelastuvat Edom ja Mooab ja ammonilaisten pääosa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Hän ojentaa kätensä maita kohti. Egyptin maa ei ole säästyvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Hän valtaa kulta- ja hopea-aarteet ja kaikki Egyptin kalleudet, ja libyalaiset ja kuusilaiset liittyvät häntä seuraamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Mutta sanomat idästä ja pohjoisesta säikähdyttävät hänet, ja hän lähtee täynnä kiukkua hävittämään monia ja vihkimään heitä tuhon omiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Hän pystyttää hovitelttansa meren ja pyhäkön ihanan vuoren välille. Mutta hänen loppunsa tulee, eikä kukaan auta häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'Siihen aikaan nousee Miikael, suuri enkeliruhtinas, joka seisoo kansasi lasten suojana. Se on oleva ahdistuksen aika, jonka kaltaista ei ole ollut siitä asti, kuin kansoja on ollut, siihen aikaan asti. Mutta siihen aikaan pelastetaan kansasi, kaikki, jotka ovat kirjaan kirjoitetut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Monet maan tomussa nukkuvista heräävät, toiset iankaikkiseen elämään, toiset häpeään ja iankaikkiseen kauhuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Taidolliset loistavat, niin kuin taivaanvahvuus loistaa, ja ne, jotka monta vanhurskauteen saattavat, niin kuin tähdet, aina ja iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Mutta sinä, Daniel, lukitse nämä sanat ja sinetöi tämä kirja lopun aikaan asti. Monet sitä tutkivat, ja tieto lisääntyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Minä, Daniel, näin, ja katso, siellä seisoi kaksi muuta, toinen virran tällä rannalla, toinen virran tuolla rannalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Toinen sanoi pellavapukuiselle miehelle, joka oli virran vetten yläpuolella: \"Kuinka kauan on vielä näiden ihmeellisten asioiden loppuun?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Kuuntelin pellavapukuista miestä, joka oli virran vetten yläpuolella, ja hän nosti oikean ja vasemman kätensä taivasta kohti ja vannoi hänen kauttansa, joka elää iankaikkisesti: \"Siihen on vielä aika, kaksi aikaa ja puoli aikaa, ja kun pyhän kansan hajaannus on päättynyt, silloin nämä kaikki täyttyvät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Minä kuulin, mutta en ymmärtänyt, ja sanoin: \"Herrani, mikä on oleva näiden loppu?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Hän sanoi: \"Mene, Daniel, sillä nämä sanat pysyvät lukittuina ja sinetöityinä lopun aikaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Monet puhdistetaan, kirkastetaan ja koetellaan, mutta jumalattomat pysyvät jumalattomina, eikä yksikään jumalaton ymmärrä tätä, mutta taidolliset ymmärtävät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Mutta siitä ajasta, jolloin jokapäiväinen uhri poistetaan ja hävityksen kauhistus asetetaan, on oleva tuhat kaksisataa yhdeksänkymmentä päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Autuas se, joka odottaa ja saavuttaa tuhat kolmesataa kolmekymmentäviisi päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Mutta sinä, mene, siihen asti kunnes loppu tulee, ja lepää, ja nouse osaasi päivien lopussa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Herran sana, joka tuli Hoosealle, Beerin pojalle, Juudan kuningasten Ussian, Jootamin, Aahaan ja Hiskian päivinä ja Israelin kuninkaan Jerobeamin, Jooaan pojan, päivinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Herran sanojen alku Hoosealle. Herra sanoi Hoosealle: \"Mene, ota itsellesi haureellinen vaimo ja haureudesta syntyneet lapset, sillä maa on rikkomalla rikkonut avion luopumalla Herrasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Hän lähti ja otti Goomerin, Diblaimin tyttären. Tämä tuli raskaaksi ja synnytti hänelle pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Herra sanoi hänelle: \"Pane hänelle nimeksi Jisreel, sillä vähän aikaa vielä, ja kostan Jisreelin verivelat Jeehun suvulle ja teen lopun Israelin heimon kuningaskunnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'Sinä päivänä särjen Israelin jousen Jisreelin laaksossa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Vaimo tuli jälleen raskaaksi ja synnytti tyttären, ja Herra sanoi Hoosealle: \"Pane hänelle nimeksi Loo-Ruhama, sillä en enää tästedes armahda Israelin heimoa, niin että antaisin heille todella anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Mutta Juudan heimoa armahdan: pelastan heidät Herran, heidän Jumalansa, toimesta, mutta en pelasta heitä jousella, miekalla enkä sodalla, en hevosilla enkä ratsumiehillä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Kun vaimo oli vieroittanut Loo-Ruhaman, hän tuli raskaaksi ja synnytti pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Herra sanoi: \"Pane hänelle nimeksi Loo-Ammi, sillä te ette ole kansani, enkä minä ole teidän omanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Mutta israelilaisten luku on oleva kuin meren hiekka, jota ei mitata eikä lueta. Siinä paikassa, jossa heille on sanottu: \'Te ette ole kansani\', heille sanotaan: \'Elävän Jumalan lapset!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Silloin Juudan miehet ja Israelin miehet kokoontuvat yhteen ja asettavat itselleen yhden Pään; ja he lähtevät siitä maasta liikkeelle, sillä suuri on Jisreelin päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Sanokaa veljiänne Ammiksi ja sisarianne Ruhamaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, '\"Käykää oikeutta äitinne kanssa, käykää oikeutta, sillä hän ei ole vaimoni, enkä minä ole hänen miehensä. Poistakoon hän haureutensa kasvoistaan ja aviorikoksensa rintojensa välistä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'etten riisu häntä alasti ja aseta häntä sellaiseksi, kuin hän oli syntymänsä päivänä, etten tee häntä erämaan kaltaiseksi ja saata häntä kuivan maan kaltaiseksi ja anna hänen kuolla janoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Mutta hänen lapsiaan en armahda, sillä he ovat haureuden lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Sillä heidän äitinsä on harjoittanut haureutta. Se, josta he ovat siinneet, on häpeällisesti elänyt, ja hän on sanonut: \'Kuljen rakastajieni perässä, jotka antavat minulle leipäni ja veteni, villani ja pellavani, öljyni ja juomani.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Sen tähden, katso, aitaan tiesi orjantappuroilla, ja muuraan muurin hänen eteensä, niin ettei hän löydä polkujaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Hän ajaa takaa rakastajiaan, mutta ei saavuta heitä, ja etsii heitä, mutta ei löydä. Hän sanoo: \'Palaan entisen mieheni luo, sillä minulla oli paremmin silloin kuin nyt.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Hän ei ole tiennyt, että minä olen hänelle antanut jyvät, rypälemehun ja öljyn, olen lisännyt hänelle paljon hopeaa ja myös kultaa, mitä he ovat käyttäneet Baalia varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Sen tähden otan takaisin jyväni ajallaan ja rypälemehuni määräaikanaan ja tempaan pois villani ja pellavani peittämästä hänen alastomuuttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Nyt paljastan hänen häpynsä hänen rakastajiensa silmien eteen, eikä kukaan pelasta häntä kädestäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Teen lopun kaikesta hänen ilonpidostaan: hänen juhlistaan, uudenkuunjuhlistaan, sapateistaan ja kaikista hänen pyhäpäivistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Hävitän hänen viiniköynnöksensä ja viikunapuunsa, joista hän on sanonut: \'Ne ovat portonpalkkani rakastajiltani.\' Teen ne metsäksi, ja kedon eläimet syövät niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'Kostan hänelle baalien päivät, joina hän poltti niille uhreja, koristi itsensä renkaillaan ja kaulaketjuillaan ja kulki rakastajiensa perässä, mutta unohti minut, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'Sen tähden, katso, minä taivuttelen häntä, vien hänet erämaahan ja puhun hänelle suloisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Annan hänelle sieltä hänen viinitarhansa sekä Aakorin laakson toivon oveksi, ja hän on laulava siellä kuin nuoruutensa päivinä, kuin sinä päivänä, jona hän lähti Egyptin maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Sinä päivänä tapahtuu, sanoo Herra, että puhuttelet minua: \'Mieheni\', etkä enää puhuttele minua: \'Baalini\'.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Poistan baalien nimet hänen suustaan, eikä niiden nimiä enää muisteta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Sinä päivänä teen heidän hyväkseen liiton kedon eläinten ja taivaan lintujen kanssa ja maan matelijoiden kanssa. Mutta jousen, miekan ja sodan särjen maasta ja annan heidän asua turvassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Kihlaan sinut itselleni ikiajoiksi, kihlaan sinut itselleni vanhurskaudella ja tuomiolla, armolla ja laupeudella,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'kihlaan sinut itselleni uskon kautta, ja sinä olet tunteva Herran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Sinä päivänä kuulen, sanoo Herra, kuulen taivasta, ja se kuulee maata,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 24, 'ja maa kuulee jyviä, rypälemehua ja öljyä, ja nämä kuulevat Jisreeliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 25, 'Kylvän hänet itselleni tähän maahan, armahdan Loo-Ruhamaa ja sanon Loo-Ammille: \'Sinä olet kansani\'; ja hän vastaa: \'Jumalani.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Herra sanoi minulle: \"Mene vielä ja rakasta naista, jota hänen puolisonsa rakastaa, mutta joka rikkoo avion, niin kuin Herra rakastaa israelilaisia, mutta nämä kääntyvät muiden jumalien puoleen ja rakastavat rypälekakkuja.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Ostin hänet itselleni viidellätoista sekelillä hopeaa sekä hoomer-mitalla ja letek-mitalla ohria');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'ja sanoin hänelle: \"Ole kauan aikaa minua varten. Älä harjoita haureutta äläkä mene muille miehille. Minäkin teen samoin sinua kohtaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Sillä kauan aikaa saavat israelilaiset olla ilman kuningasta ja ruhtinasta, ilman uhria ja patsasta, ilman kasukkaa ja kotijumalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Sen jälkeen israelilaiset kääntyvät ja etsivät Herraa, Jumalaansa, ja Daavidia, kuningastaan. Vavisten he lähestyvät Herraa ja hänen hyvyyttään päivien lopulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Kuulkaa Herran sana, te israelilaiset, sillä Herralla on oikeudenkäynti maan asukkaiden kanssa. Maassa ei näet ole uskollisuutta, ei laupeutta eikä Jumalan tuntemusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Vannoskelu, valehtelu, murhat, varkaudet ja aviorikokset saavat vallan, ja verityö seuraa verityötä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Sen tähden maa murehtii, ja kaikki sen asukkaat nääntyvät kedon eläinten ja taivaan lintujen kanssa. Kalatkin merestä kuolevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Älköön vain kukaan nuhdelko, älköön kukaan ojentako, vaikka kansasi on kuin pappien nuhtelijoita!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Kompastut päivällä, myös profeetta kompastuu kanssasi yöllä, ja hävitän äitisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Kansani joutuu häviöön tietoa vailla. Koska sinä olet hylännyt tiedon, hylkään sinut, niin ettet saa olla pappinani. Koska olet unohtanut Jumalasi lain, unohdan minäkin lapsesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Mitä enemmän heitä on, sitä enemmän he tekevät syntiä minua vastaan. Muutan heidän kunniansa häpeäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Kansani synnistä he saavat ruokansa, heidän pahoja tekojaan heidän sielunsa himoitsee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Mutta papin käy niin kuin kansankin. Rankaisen häntä hänen vaelluksestaan ja kostan hänelle hänen tekonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'He syövät, mutta eivät tule ravituiksi, he harjoittavat haureutta, mutta eivät lisäänny, sillä he eivät ole ottaneet vaarin Herrasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Haureus, viini ja rypälemehu vievät ymmärryksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Kansani kysyy puultaan, ja sen sauva vastaa sille. Sillä haureuden henki eksyttää. Haureudessa he ovat luopuneet Jumalastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Vuorten huipuilla he uhraavat, polttavat uhreja kukkuloilla, rautatammen, poppelin ja tammen alla, sillä niiden varjo on suloinen. Sen tähden tyttäristänne tulee porttoja, ja miniänne rikkovat avion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'En rankaise tyttäriänne siitä, että he ovat porttoja, enkä miniöitänne siitä, että he rikkovat avion, sillä miehet itse poikkeavat syrjään porttojen kanssa ja uhraavat pyhäkköporttojen kanssa, ja ymmärtämätön kansa kukistuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Jos sinä, Israel, harjoitatkin haureutta, älköön Juuda saattako itseään syynalaiseksi. Älkää lähtekö Gilgaliin, älkää menkö ylös Beet-Aaveniin älkääkä vannoko: \"Niin totta kuin Herra elää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Sillä niin kuin niskuri lehmä on Israel niskoitellut. Nyt Herra on kaitseva heitä kuin karitsaa avaralla laitumella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Efraim on liitossa epäjumalien kanssa – anna hänen olla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Heidän juomansa on käynyt vastenmieliseksi. He harjoittavat törkeää haureutta. Ne, jotka ovat hänen kilpensä, rakastavat häpeää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Tuuli siivillään ahdistaa häntä, ja he saavat häpeän uhreistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Kuulkaa tämä, te papit, pankaa merkille, te Israelin heimo, ja ottakaa korviinne, te kuninkaan huone: teille on tämä tuomio. Sillä te olette olleet paula Mispalle, verkko, joka on levitetty Taaborille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Luopiot ovat vajonneet syvälle turmioon, mutta minä olen kuritus heille kaikille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Minä tunnen Efraimin, eikä Israel ole minulta piilossa. Sillä nyt sinä, Efraim, olet haureutta harjoittanut, Israel on itsensä saastuttanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Heidän tekonsa eivät salli heidän kääntyä heidän Jumalansa puoleen, sillä haureuden henki on heidän sisimmässään eivätkä he tunne Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Israelin ylpeys syyttää häntä vasten kasvoja, ja Israel ja Efraim kompastuvat syntivelkaansa. Myös Juuda kompastuu heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Lampaittensa ja nautojensa kanssa he tulevat etsimään Herraa, mutta eivät löydä. Hän on vetäytynyt heistä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'He ovat olleet uskottomia Herralle, sillä he ovat synnyttäneet vieraita lapsia. Nyt uudenkuun juhla syö heidät maineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Puhaltakaa torveen Gibeassa, trumpettiin Raamassa, nostakaa sotahuuto Beet-Aavenissa. Ovat jo kintereilläsi, Benjamin!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Efraim on tuleva autioksi kurituksen päivänä. Israelin heimokunnille olen ilmoittanut, mikä on totta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Juudan ruhtinaat ovat tulleet rajansiirtäjien kaltaisiksi. Vuodatan heidän päälleen vihani kuin vedet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Sorrettu on Efraim ja loukattu hänen oikeutensa, sillä hän tahtoi vaeltaa ihmiskäskyjen mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Mutta minä olen Efraimille kuin koi ja Juudan heimolle kuin mätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Mutta kun Efraim näki sairautensa ja Juuda haavansa, Efraim meni Assuriin, lähetti sanan suurkuninkaalle. Mutta tämä ei voinut teitä parantaa eikä tehdä terveeksi haavaanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Sillä minä olen Efraimille kuin leijona, Juudan heimolle kuin nuori leijona. Minä, minä raatelen, menen ja kannan pois, eikä pelastajaa ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Lähden ja palaan takaisin paikoilleni, kunnes he ovat tunnustaneet syyllisyytensä ja etsivät kasvojani. Ahdistuksessaan he etsivät minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Tulkaa, palatkaamme Herran tykö, sillä hän on raadellut meitä, mutta parantaa meidät, hän on lyönyt, mutta sitoo meidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Hän tekee meidät eläviksi kahden päivän kuluttua, kolmantena päivänä hän meidät herättää, ja me tulemme elämään hänen kasvojensa edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Tuntekaamme, ahkeroikaamme tuntea Herra. Hänen ilmestymisensä on varma kuin aamurusko, hän tulee meille kuin sade, kuin kevätsade, joka kostuttaa maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Mitä minun on tehtävä sinulle, Efraim, mitä minun on tehtävä sinulle, Juuda, kun teidän laupeutenne on kuin aamun pilvi ja kuin varhain haihtuva kaste?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Sen tähden olen lyönyt heitä profeettojen kautta ja kuolettanut heitä suuni sanoilla, ja tuomiosi nousevat kuin valo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Sillä haluan laupeutta enkä uhria, ja Jumalan tuntemista enemmän kuin polttouhreja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'mutta he ovat Aadamin tavoin rikkoneet liiton ja olleet siinä minulle uskottomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Gilead on pahantekijöiden kaupunki, täynnä veritahroja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Väijyvän rosvojoukon kaltainen on pappien joukko. He murhaavat Sikemin tiellä ja tekevät häpeällisiä tekojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Israelin huoneessa olen nähnyt kauhistuttavia tekoja. Siellä on Efraimin haureus, Israel on itsensä saastuttanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Myös sinua varten, Juuda, on asetettu elonkorjuu, silloin kun palautan kansani vankeudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Kun parannan Israelia, silloin tulevat julki Efraimin rikokset ja Samarian pahuudet. Sillä he harjoittavat petosta, varas tulee sisään, ja rosvojoukko ryöstää ulkona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'He eivät sano sydämessään, että muistan kaiken heidän pahuutensa. Nyt heidän tekonsa piirittävät heidät, ne ovat kasvojeni edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'He ilahduttavat pahuudellaan kuningasta ja valheillaan ruhtinaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'He ovat kaikki avionrikkojia. He ovat kuin leipojan lämmittämä uuni. Hän jättää tulen kohentamatta taikinan sotkemisesta sen happanemiseen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Kuninkaamme päivänä ruhtinaat ovat sairaina viinin hehkusta. Hän lyö kättä pilkkaajien kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Sillä he ovat juonillaan saattaneet sydämensä kuumaksi kuin uuni. Koko yön heidän leipojansa nukkuu, aamulla se palaa kuin loimuava tuli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'He ovat kaikki kuumia kuin uuni. He syövät tuomarinsa. Kaikki heidän kuninkaansa ovat kaatuneet, eikä kukaan heistä ole huutanut minua avuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Efraim sekoittuu kansojen joukkoon. Efraim on tullut leivän kaltaiseksi, jota ei ole käännetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Muukalaiset syövät hänen voimansa, mutta ei hän sitä ymmärrä. Hänen hiuksensakin ovat jo harmaantuneet, mutta hän ei ymmärrä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Israelin ylpeys syyttää häntä vasten kasvoja. He eivät palaa Herran, Jumalansa, tykö eivätkä etsi häntä kaiken tämän tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Efraim on tullut kyyhkysen kaltaiseksi, joka on tyhmä ja ymmärtämätön. He huutavat apuun Egyptiä ja menevät Assuriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Juuri kun he ovat menossa, heitän verkkoni heidän päälleen ja pudotan heidät alas kuin taivaan linnut. Kuritan heitä, niin kuin on julistettu heidän seurakunnalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Voi heitä, sillä he ovat menneet minua pakoon! Häviö heille, sillä he ovat luopuneet minusta! Olen lunastanut heidät, mutta he puhuvat valheita minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'He eivät huuda puoleeni sydämestään, vaan ulvovat vuoteissaan. Jyvien ja viinin tähden he kokoontuvat. Minua vastaan he niskoittelevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Minä olen heitä kurittanut, olen vahvistanut heidän käsivartensa, mutta minua vastaan he ovat aikoneet pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'He kääntyvät, mutta eivät korkeutta kohti. He ovat kuin pettävä jousi. Heidän ruhtinaansa kaatuvat miekkaan kieltensä kiukkuisuuden tähden. Tämä koituu heille pilkaksi Egyptin maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Aseta torvi suullesi! Kotkan lailla Herran huonetta vastaan – koska he ovat rikkoneet liittoni ja luopuneet laistani!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Minun puoleeni he huutavat: \"Minun Jumalani!\" – \"Me Israel, tunnemme sinut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Israel on hylännyt hyvän. Vihollinen sitä vainotkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'He ovat asettaneet kuninkaita, mutta se ei ole ollut minusta. He ovat asettaneet ruhtinaita, mutta en ole siitä tiennyt. Hopeansa ja kultansa he ovat tehneet epäjumalikseen, että tulisi hävitys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Inhottava on vasikkasi, Samaria. Vihani on syttynyt heitä vastaan. Kuinka kauan he voivat olla rankaisematta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Sillä se on Israelista ja seppä on sen tehnyt. Se ei ole jumala, vaan pirstaleiksi on menevä Samarian vasikka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Sillä tuulta he ovat kylväneet, ja myrskyä he leikkaavat. Se ei anna satoa, laiho ei tuota jauhoja, ja minkä tuottaa, sen muukalaiset nielevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Nielty on Israel. He ovat nyt pakanoiden seassa kuin astia, joka ei kelpaa mihinkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Sillä Assuriin he ovat menneet kuin yksinäinen villiaasi. Efraim ostelee lahjoilla rakasteluja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Vaikka he ovat ostelleet pakanoiden seassa, niin nyt heidät kokoan, ja he ovat alkaneet vähäksi aikaa kärsiä ruhtinaiden kuninkaan taakasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Koska Efraim on rakentanut paljon alttareita tehdäkseen syntiä, alttarit ovatkin tulleet hänelle synniksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Kirjoitinpa hänelle lakejani vaikka kymmeniä tuhansia, vieraina niitä pidetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Uhrilahjoikseni he uhraavat lihaa ja syövät. Herra ei niihin mielly. Nyt hän muistaa heidän rikoksensa ja rankaisee heidän syntinsä: Egyptiin on heidän palattava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Israel on unohtanut tekijänsä ja rakentanut palatseja, ja Juuda on rakentanut paljon varustettuja kaupunkeja. Mutta lähetän tulen hänen kaupunkeihinsa, ja se kuluttaa niiden palatsit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Israel, älä iloitse äläkä riemuitse, niin kuin muut kansat, sillä olet haureudessa luopunut Jumalastasi ja olet rakastanut portonpalkkoja kaikilla viljan puimatanterilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Puimatanner ja viinikuurna eivät heitä elätä, rypälemehu hänet pettää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'He eivät tule asumaan Herran maassa, vaan Efraimin on palattava Egyptiin, ja Assurissa he syövät saastaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'He eivät vuodata viiniä juomauhriksi Herralle, eivätkä heidän teurasuhrinsa hänelle kelpaa. Ne ovat heille kuin murheen leipä. Kaikki, jotka sitä syövät, saastuttavat itsensä, sillä heidän leipänsä on heitä itseään varten. Se ei tule Herran temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Mitä teette, kun tulee juhla-aika, Herran juhlapäivä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Sillä katso, he menevät hävitystä pakoon. Egypti kokoaa heidät, ja Moof hautaa heidät. Orjantappurat valtaavat heidän hopeakalleutensa, ohdakkeita on oleva heidän teltoissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Rangaistuksen päivät tulevat, koston päivät tulevat, Israel on sen tunteva. Hulluna on oleva profeetta, mieltä vailla hengen mies paljojen rikoksiesi ja suuren vihamielisyytesi tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Efraim on väijyjä Jumalaani vastaan. Profeetta – hänen kaikilla teillään on pyydystäjän paula, ja vainoa on hänen Jumalansa huoneessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'He ovat syvälle vajonneet turmiontekoon kuin Gibean päivinä. Hän muistaa heidän rikoksensa ja kostaa heidän syntinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Kuin rypäleet erämaasta löysin Israelin. Kuin varhaishedelmät viikunapuussa sen alkurunsaudessa näin teidän isänne. He tulivat Baal-Peoriin, vihkiytyivät häpeäjumalalle ja tulivat kauhistaviksi, niin kuin heidän rakastettunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Efraimilta lentää pois heidän kunniansa kuin lintu: ei synnyttämistä, ei raskautta, ei sikiämistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Vaikka he kasvattaisivat lapsensa isoiksi, teen heidät lapsettomiksi, niin ettei ihmisiä jää. Voi heitä itseänsäkin, kun heistä luovun!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Efraim on, kun katselen sitä Tyyroa kohti, istutettu laidunmaalle, mutta Efraim vie lapsensa surmaajalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Anna heille, Herra – mitä antaisitkaan? – anna heille hedelmätön kohtu ja kuivettuneet rinnat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Kaikki heidän pahuutensa on Gilgalissa, sillä siellä vihastuin heihin. Heidän tekojensa pahuuden tähden karkotan heidät pois huoneestaan. En enää rakasta heitä. Kaikki heidän ruhtinaansa ovat niskureita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Efraim on hakattu maahan, ja heidän juurensa on kuivettunut. Hedelmää he eivät tee. Jos synnyttävätkin, kuoletan heidän kohtunsa kalleimmat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Jumalani on hylkäävä heidät, sillä he eivät ole häntä totelleet. He tulevat olemaan pakolaisia pakanoiden seassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Israel oli rehevä viiniköynnös, joka teki hedelmiä. Mitä runsaampi sen hedelmä oli, sitä enemmän se teki alttareita, ja mitä parempi sen maa oli, sitä parempia patsaita se pystytti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Liukas oli heidän sydämensä. Nyt heitä siitä rangaistaan. Hän särkee heidän alttarinsa ja hävittää heidän patsaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Sillä nyt he sanovat: \"Meillä ei ole kuningasta, sillä emme ole pelänneet Herraa, ja mitä kuningas meille tekisi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'He pitävät puheita, vannovat väärin ja tekevät liittoja, mutta tuomio versoo kuin myrkkyruoho pellon vaosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Beet-Aavenin vasikoiden tähden Samarian asukkaat joutuvat pelkoon. Sillä niiden tähden sen kansa murehtii ja myös papit, jotka ennen siitä iloitsivat, sen kunnian tähden, kun se on viety siltä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Se itsekin viedään Assuriin lahjaksi suurkuninkaalle. Häpeän saa Efraim, ja häpeään joutuu Israel neuvoistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Hukassa on Samaria kuninkaineen. Se on kuin lastu veden pinnalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Aavenin uhrikukkulat, Israelin synti, hävitetään. Orjantappuraa ja ohdaketta on kasvava heidän alttareillaan. Niin he sanovat vuorille: \"Peittäkää meidät\", ja kukkuloille: \"Langetkaa päällemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Gibean päivistä asti olet, Israel, tehnyt syntiä. Sinne he ovat asettuneet. Eikö heitä Gibeassa saavuttaisi sota, sota vääryyden miehiä vastaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Haluni mukaan olen heitä kurittava, ja heitä vastaan kokoontuvat kansat, kun heidät sidotaan kiinni heidän kahteen rikokseensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Efraim on lehmä, joka on opetettu puimaan mielellään, mutta minä panen hänen kauniin kaulansa päälle ikeen. Valjastan Efraimin: Juuda kyntää, ja Jaakob äestää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Kylväkää itsellenne vanhurskauden kylvö, niin saatte leikata laupeutta. Raivatkaa itsellenne uudispelto, sillä on aika etsiä Herraa, kunnes hän tulee ja antaa sataa teille vanhurskautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Te olette kyntäneet jumalattomuutta, korjanneet vääryyttä ja syöneet valheen hedelmää. Sillä olet luottanut omaan tiehesi ja sankariesi paljouteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Nousee pauhina kansojesi keskelle, ja kaikki linnoituksesi hävitetään, niin kuin Salman hävitti Beet-Arbelin sodan päivänä: äiti ruhjotaan lastensa päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Tämän tekee teille Beetel ylenpalttisen pahuutenne tähden. Aamunkoitossa Israelin kuningas tuhoamalla tuhotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Kun Israel oli nuori, minä rakastin häntä, ja Egyptistä minä kutsuin Poikani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Kun he heitä kutsuivat, he menivät pois heidän kasvojensa edestä, uhrasivat baaleille ja polttivat uhreja epäjumalille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Minä opetin Efraimin kävelemään. – Hän otti heidät käsivarsilleen. – Mutta he eivät ymmärtäneet, että paransin heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Ihmissiteillä heitä vedin, rakkauden köysillä. Nostin ikään kuin ikeen heidän leukapieliltään, kumarruin heidän puoleensa ja syötin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'He eivät palaa Egyptin maalle, vaan Assur on heidän kuninkaansa, sillä he ovat kieltäytyneet kääntymästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Miekka on riehuva hänen kaupungeissaan. Se hävittää hänen salpansa ja syö ne heidän neuvojensa takia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Kansani haluaa kääntyä minusta pois, ja vaikka sitä kutsutaan Korkeimman puoleen, kukaan heistä ei ylene.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Kuinka minä jättäisin sinut, Efraim, heittäisin sinut, Israel? Kuinka jättäisin sinut kuin Adman, tekisin sinulle kuin Seboimille? Sydämeni kääntyy, säälini herää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'En pane täytäntöön vihani hehkua enkä enää hävitä Efraimia. Sillä minä olen Jumala enkä ihminen, olen Pyhä keskelläsi. En tule kaupunkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'He vaeltavat Herran jäljessä. Hän ärjyy kuin leijona – niin, hän ärjyy, ja vavisten tulevat lapset lännestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Vavisten he tulevat Egyptistä kuin linnut, Assurin maasta kuin kyyhkyset, ja minä saatan heidät asumaan kodeissaan, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Efraim on ympäröinyt minut valheella ja Israelin huone vilpillä. Juuda juoksee yhä valtoimena, välittämättä Jumalasta, Pyhästä ja Totisesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Efraim ruokkii tuulta, ajaa takaa itätuulta ja kartuttaa kaiken aikaa valhetta ja hävitystä. Tehdään liittoja Assurin kanssa, ja viedään öljyä Egyptiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Mutta Herralla on oikeudenkäynti Juudan kanssa, ja hän on rankaiseva Jaakobille sen vaelluksen mukaan ja kostava sille sen tekojen mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Äidin kohdussa tämä petti veljensä, ja miehuutensa voimassa hän taisteli Jumalan kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Hän taisteli Enkelin kanssa ja voitti, hän itki ja rukoili tätä. Beetelissä tämä löysi hänet ja puhui siellä kanssamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Herra, Jumala Sebaot – Herra on hänen nimensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Mutta sinä – käänny Jumalasi tykö, noudata laupeutta ja oikeutta ja pane alati toivosi Jumalaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Kanaan – hänen kädessään on petollinen vaaka, ja hän rakastaa sortoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Efraim sanoo: \"Olen rikastunut, olen saanut itselleni omaisuutta, enkä havaitse teoissani vääryyttä, joka olisi syntiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Mutta minä, joka olen Herra, Jumalasi, Egyptin maasta lähtien, saatan sinut vielä asumaan teltoissa kuin juhlapäivinä. Hoos');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Olen puhunut profeetoille, minä olen antanut paljon näkyjä ja puhunut vertauksia profeettojen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Jos Gilead onkin ollut pelkkää petosta, niin he tulevat pelkäksi turhuudeksi. Gilgalissa on uhrattu härkiä, niinpä heidän alttareistaan tulee kuin kivikasoja, joita on pellon vaoilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Jaakob pakeni Aramin kedoille, ja Israel palveli naisen tähden, naisen tähden hän paimensi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Mutta profeetan kautta Herra vei Israelin pois Egyptistä, ja profeetta sitä paimensi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 15, 'Efraim vihastutti Herran katkerasti, ja sen vuoksi hänen verivelkansa jäävät hänen päälleen ja Herra kääntää hänen häpäisevän pilkkansa häneen itseensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Kun Efraim puhui, syntyi kauhu. Hän kohosi korkealle Israelissa, mutta hän tuli syynalaiseksi Baalin takia ja kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Nyt he jatkavat synnintekoa, tekevät itselleen valettuja kuvia hopeastaan, epäjumalankuvia ymmärryksensä mukaan, seppien tekemiä kaikki. Niille he puhuvat, teurastavat ihmisiä ja suutelevat vasikoita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Sen tähden he ovat kuin aamun pilvi, kuin kaste, joka haihtuu varhain, kuin akanat, jotka tuuli vie puimatantereelta kuin savun ikkunasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Mutta minä olen Herra, Jumalasi, hamasta Egyptin maasta lähtien. Muuta Jumalaa et tunne kuin minut, eikä ole muuta Vapahtajaa kuin minä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Minä tunsin sinut erämaassa, kuivassa maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Laidunmaittensa mukaan he tulivat kylläisiksi. He tulivat kylläisiksi, ja heidän sydämensä tuli ylpeäksi, ja sen tähden he unohtivat minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Sen tähden tulen olemaan heille kuin leijona, kuin leopardi väijyn heitä tien varressa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Käyn heidän kimppuunsa kuin karhu, jolta on riistetty poikaset, revin heidän sydänkalvonsa ja syön heidät siinä paikassa kuin naarasleijona. Kedon pedot raatelevat heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Israel, se on tuhosi, että olet minua vastaan, joka olen apusi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Missä on nyt kuninkaasi, että hän auttaisi sinua kaikissa kaupungeissasi, ja tuomarisi, joista olet sanonut: \"Anna minulle kuningas ja ruhtinaat\"?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Kuninkaan annoin sinulle vihassani ja otin pois kiivastuksessani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Efraimin rikos on sidottu kokoon, talteen on pantu hänen syntinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Hänelle tulevat synnyttäjän tuskat. Hän on älytön lapsi, sillä hän ei tule ajallaan kohdusta esiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Helvetin kädestä heidät pelastan, kuolemasta heidät lunastan. Missä on sinun ruttosi, kuolema, missä sinun surmasi, helvetti? Katumus on peitetty silmiltäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Vaikka hän on veljien keskellä hedelmällinen, itätuuli tulee, Herran tuuli nousee erämaasta, ja hänen kaivonsa kuivuu ja lähteensä ehtyy: se ryöstää hänen aarteensa, kaikki hänen kallisarvoiset esineensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Samaria hävitetään, koska se on noussut Jumalaansa vastaan: he kaatuvat miekkaan, heidän pienet lapsensa ruhjotaan, ja heidän raskaana olevat vaimonsa halkaistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Palaa, Israel, Herran, Jumalasi, tykö, sillä olet kompastunut rikoksiisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Ottakaa mukaanne sanoja ja palatkaa Herran tykö ja sanokaa hänelle: \"Anna anteeksi kaikki rikokset, ota armoihisi, niin tuomme sinulle uhrimulleiksi huultemme uhrit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Assur ei meitä pelasta, hevosilla emme ratsasta emmekä enää sano kättemme teoille: \'Meidän jumalamme\'; sillä sinulta orpo löytää armon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Parannan luopumuksenne, rakastan heitä tahtoni mukaan, sillä vihani on kääntynyt heistä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Olen oleva Israelille kuin kaste. Se on kukoistava kuin lilja ja juurtuva syvälle kuin Libanon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Sen vesat leviävät, sen kauneus on oleva kuin öljypuun ja sen tuoksu kuin Libanonin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Sen varjossa asuvat kasvattavat jälleen viljaa ja kukoistavat kuin viiniköynnös. Sen maine on oleva kuin Libanonin viinin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Efraim! Mitä on minulla enää tekemistä epäjumalien kanssa? Minä kuulen häntä ja katson hänen puoleensa, minä, joka olen kuin viheriöivä sypressi: minusta on hedelmäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 10, 'Kuka on viisas ja nämä ymmärtää? Kuka osaa ja tuntee nämä? Sillä Herran tiet ovat suorat, vanhurskaat niillä vaeltavat, mutta luopiot niillä kompastuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Herran sana, joka tuli Jooelille, Petuelin pojalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Kuulkaa tämä, te vanhimmat, ja ottakaa korviinne, kaikki maan asukkaat. Onko tällaista tapahtunut teidän päivinänne tai isienne päivinä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Kertokaa tämä lapsillenne, ja lapsenne kertokoot sen lapsilleen ja heidän lapsensa tulevalle polvelle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Mitä kalvajasirkalta jäi, sen söi heinäsirkka. Mitä heinäsirkalta jäi, sen söi syöjäsirkka. Mitä syöjäsirkalta jäi, sen söi tuhosirkka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Herätkää, te juopuneet, ja itkekää ja valittakaa, kaikki viininjuojat, makean viinin tähden, sillä se on otettu pois suustanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Sillä maahani on hyökännyt väkevä ja monilukuinen kansa. Sen hampaat ovat leijonan hampaat, ja sillä on naarasleijonan leukaluut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Se on hävittänyt viiniköynnökseni ja katkonut viikunapuuni. Se on kuorinut ne paljaiksi ja heittänyt menemään. Niiden oksat ovat kuoritut valkoisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Valita kuin neitsyt, joka on vyöttäytynyt säkkiin nuoruutensa yljän tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Pois on otettu ruokauhri ja juomauhri Herran huoneesta. Papit, jotka toimittavat Herran palvelusta, murehtivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Hävitetty on pelto, maa murehtii, sillä vilja on hävitetty. Viinistä on tullut kato, ja öljy on kuivunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Hävetkää, peltomiehet, valittakaa, viinitarhurit, vehnän ja ohran tähden, sillä pellon sato on mennyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Viiniköynnös on kuivunut, lakastuneet ovat viikunapuu, granaattipuu sekä myös palmu ja omenapuu. Kaikki kedon puut ovat kuivettuneita. Niin ilo on joutunut häpeään pois ihmislapsilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Vyöttäytykää säkkiin, pitäkää valittajaiset, te papit. Valittakaa, te alttaripalvelijat. Käykää sisälle, viettäkää yö säkkeihin pukeutuneina, te jotka toimitatte Jumalani palvelusta. Sillä poissa on Jumalanne huoneesta ruokauhri ja juomauhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Kuuluttakaa pyhä paasto, kutsukaa koolle juhlakokous, kootkaa vanhimmat ja kaikki maan asukkaat Herran, Jumalanne, huoneeseen ja huutakaa Herran puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Voi sitä päivää! Sillä lähellä on Herran päivä, ja se tulee kuin hävitys Kaikkivaltiaalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Eikö ruoka ole otettu meiltä pois silmiemme edessä sekä Jumalamme huoneesta ilo ja riemu?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Surkastuneet ovat siemenjyvät multiensa alla, varastohuoneet ovat autioita ja aitat purettuja, kun kuivuus on vienyt viljasadon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Kuinka huokaakaan karja, kuinka hädissään ovatkaan karjalaumat, sillä niillä ei ole laidunta! Myös lammaslaumat voipuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Sinua, Herra, minä huudan, sillä tuli on syönyt erämaan laitumet ja liekki on polttanut kaikki kedon puut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Kedon eläimetkin sinua ikävöivät, sillä vesipurot ovat kuivuneet ja tuli on syönyt erämaan laitumet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Puhaltakaa torveen Siionissa, toitottakaa torvia pyhällä vuorellani. Kaikki maan asukkaat vapisevat, sillä Herran päivä tulee, ja se on lähellä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'pimeyden ja synkeyden päivä, pilvien ja pilkkopimeän päivä. Kuin aamurusko vuorille on levinnyt lukuisa ja väkevä kansa, jonka vertaista ei ole ollut ikiajoista asti eikä tämän jälkeen enää tule, tulevien polvien vuosiin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Sen edellä käy kuluttava tuli, sen perässä polttava liekki. Kuin Eedenin puutarha on maa sen edessä, mutta sen jäljessä on autio erämaa, eikä ole ketään, joka siltä pelastuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Ne ovat näöltään kuin hevoset, ja ne juoksevat kuin ratsut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Ryskyen kuin sotavaunut ne hyppivät vuorten huipuilla, rätisten kuin tulen liekki, joka kuluttaa oljet. He ovat kuin väkevä, taisteluun asettunut kansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Heidän edessään kansat vapisevat, ja kaikki kasvot kalpenevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'He juoksevat kuin sankarit, kuin soturit he nousevat muurille. Jokainen kulkee tietään suoraan eikä mutkittele polullaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Toinen ei sysi toistaan. Mies kulkee omaan suuntaansa. Heittoaseiden välitse he tunkeutuvat vahingoittumattomina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'He ryntäävät kaupunkiin, juoksevat muurille, nousevat taloihin ja tulevat ikkunoista sisään kuin varas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Niiden edessä maa vapisee ja taivaat järkkyvät, aurinko ja kuu käyvät mustiksi, ja tähdet pidättävät valonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Herra antaa äänensä jyristä sotajoukkonsa edellä, sillä hyvin monilukuinen on hänen väkensä, sillä voimakas on hänen sanansa täyttäjä, sillä suuri on Herran päivä ja hyvin pelottava. Kuka voi sen kestää?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Mutta vielä nytkin, sanoo Herra, kääntykää luokseni kaikesta sydämestänne, paastoten, itkien ja valittaen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Reväiskää rikki sydämenne, älkää vaatteitanne, ja kääntykää Herran, Jumalanne, luo; sillä hän on armahtavainen ja laupias, pitkämielinen ja suuri armossa, ja hän katuu pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Ehkä hän vielä katuu ja jättää jälkeensä siunauksen: ruokauhrin ja juomauhrin Herralle, Jumalallenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Puhaltakaa torveen Siionissa, kuuluttakaa pyhä paasto, kutsukaa koolle juhlakokous.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Kootkaa kansa, pitäkää pyhä kokous, kerätkää vanhukset, kootkaa lapset ja rintoja imeväiset. Lähteköön ylkä huoneestaan ja morsian kammiostaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Papit, jotka toimittavat Herran palvelusta, itkekööt eteisen ja alttarin välillä ja sanokoot: \"Sääli, Herra, kansaasi äläkä anna perintöosaasi häväistäväksi, pakanoiden pilkattavaksi. Miksi sanottaisiin kansojen keskuudessa: \'Missä on heidän Jumalansa?\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Herra kiivailee maansa puolesta ja säälii kansaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Herra vastaa ja sanoo kansalleen: Katso, lähetän teille viljaa, viiniä ja öljyä, niin että tulette niistä ravituiksi. Enkä anna enää häväistä teitä pakanoiden keskuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Pohjoisesta tulevan karkotan teistä kauas ja syöksen kuivaan ja autioon maahan, sen alkupään Idänmereen ja sen loppupään Länsimereen. Mutta siitä nousee löyhkä ja kohoaa lemu. Sillä suurta pahaa se on tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Älä pelkää, maa. Iloitse ja riemuitse, sillä Herra on tehnyt suuria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Älkää pelätkö, kedon eläimet, sillä erämaan laitumet viheriöivät, sillä puu kantaa hedelmänsä, viikunapuu ja viiniköynnös antavat satonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Siionin lapset, iloitkaa ja riemuitkaa Herrassa, Jumalassanne, sillä hän antaa teille vanhurskauden Opettajan ja vuodattaa teille sateen, syyssateen ja kevätsateen kuten entisaikaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'Silloin puimatantereet tulevat jyviä täyteen, ja kuurnat pursuavat viiniä ja öljyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'Korvaan teille ne vuodentulot, jotka heinäsirkka, syöjäsirkka, tuhosirkka ja kalvajasirkka söivät, tuo suuri sotajoukkoni, jonka lähetin teitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Todella syötte kylliksi ja tulette ravituiksi ja kiitätte Herran, Jumalanne, nimeä, hänen, joka on tehnyt ihmeitä teitä kohtaan. Eikä kansani joudu iankaikkiseen häpeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Tulette tietämään, että Israelin keskellä olen minä, ja minä olen Herra, Jumalanne, eikä toista ole. Eikä kansani joudu enää häpeään, iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Näiden jälkeen tapahtuu, että vuodatan Henkeni kaiken lihan päälle, ja poikanne ja tyttärenne ennustavat, vanhuksenne unia uneksuvat, nuorukaisenne näkyjä näkevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Mutta myös palvelijoiden ja palvelijattarien päälle niinä päivinä vuodatan Henkeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Annan näkyä merkkejä taivaalla ja maassa: verta, tulta ja savupatsaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Aurinko muuttuu pimeydeksi ja kuu vereksi, ennen kuin Herran päivä tulee, se suuri ja pelottava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Tapahtuu, että jokainen, joka huutaa avuksi Herran nimeä, pelastuu. Sillä Siionin vuorella ja Jerusalemissa ovat pelastuneet, kuten Herra on sanonut, ja pakoon päässeiden joukossa ovat ne, jotka Herra kutsuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 1, 'Sillä katso, niinä päivinä ja siihen aikaan, kun käännän Juudan ja Jerusalemin kohtalon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 2, 'kokoan kaikki pakanakansat, vien ne alas Joosafatin laaksoon ja käyn siellä oikeutta niiden kanssa kansani ja perintöosani, Israelin, tähden. Sillä he ovat hajottaneet sen pakanakansojen sekaan, ja ovat jakaneet maani');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 3, 'ja heittäneet kansastani arpaa. He ovat antaneet pojan porttoa vastaan sekä myyneet tytön viinistä, jonka ovat juoneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 4, 'Mitä teilläkin on sanomista minulle, teillä Tyyro ja Siidon ja kaikki filistealaisten rannikot? Tahdotteko te kostaa minulle? Jos kostatte minulle, käännän koston nopeasti ja kiireesti omaan päähänne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 5, 'teille, jotka olette ottaneet hopeani ja kultani, vieneet ihanat kalleuteni temppeleihinne');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 6, 'sekä myyneet Juudan ja Jerusalemin lapsia jaavanilaisille viedäksenne heidät pois kauas omalta maaltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 7, 'Katso, tuon heidät pois siitä paikasta, johon te olette heidät myyneet, ja annan koston kohdata omaa päätänne:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 8, 'myyn poikianne ja tyttäriänne Juudan poikien käsiin, ja he myyvät heitä sabalaisille, kaukaiselle kansalle. Sillä Herra on puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 9, 'Julistakaa tämä pakanakansoissa, alkakaa pyhä sota, innostakaa sankareita, lähestykööt, hyökätkööt kaikki soturit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 10, 'Takokaa aurankärkenne miekoiksi ja vesurinne keihäiksi. Sanokoon heikko: \"Minä olen sankari.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 11, 'Käykää avuksi, tulkaa, kaikki kansakunnat joka taholta. He kokoontuvat sinne. Anna, Herra, sankariesi astua sinne alas');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 12, 'Lähtekööt liikkeelle, hyökätkööt kansakunnat Joosafatin laaksoon, sillä siellä hän istuu tuomitsemassa kaikkia pakanakansoja, joka taholta tulleita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 13, 'Lähettäkää sirppi, sillä sato on kypsynyt. Tulkaa polkemaan, sillä kuurna on täynnä ja viinialtaat pursuavat yli, sillä heidän pahuutensa on suuri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 14, 'Meluavia joukkoja, meluavia joukkoja tuomion laaksossa! Sillä lähellä on Herran päivä tuomion laaksossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 15, 'Aurinko ja kuu käyvät mustiksi, ja tähdet pidättävät valonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 16, 'Herra karjahtelee Siionista ja antaa äänensä kuulua Jerusalemista, ja taivaat ja maa järkkyvät, mutta Herra on kansansa suoja, Israelin lasten turva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 17, 'Tulette tietämään, että minä olen Herra, Jumalanne, joka asun Siionissa, pyhällä vuorellani. Jerusalem on oleva pyhä, eivätkä vieraat enää kulje sen läpi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 18, 'Sinä päivänä vuoret tihkuvat rypälemehua ja kukkulat vuotavat maitoa. Kaikissa Juudan puroissa virtaa vesi, ja Herran huoneesta juoksee lähde ja kastelee Akasialaakson.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 19, 'Egypti tulee autioksi, ja Edom tulee autioksi erämaaksi väkivallan tähden, jota ne ovat tehneet Juudan lapsille, kun ovat vuodattaneet viatonta verta heidän maassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 20, 'Mutta Juuda on oleva asuttu iankaikkisesti ja Jerusalem polvesta polveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 21, 'Julistan heidät puhtaiksi verivelasta, josta en ole heitä puhtaiksi julistanut, ja Herra on asuva Siionissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Aamoksen sanat, hänen, joka oli Tekoan paimenia ja joka näki näyn Israelista kaksi vuotta ennen maanjäristystä, kun Juudan kuninkaana oli Ussia ja Israelin kuninkaana oli Jerobeam, Jooaksen poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Näin hän sanoi: Herra karjahtelee Siionista, korottaa äänensä Jerusalemista, ja paimenten laitumet lakastuvat, ja Karmelin selänne kuivuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Näin sanoo Herra: Damaskon kolmen rikoksen ja neljänkin tähden en sitä peru, sillä se on jyrännyt Gileadia rautaisilla puimaäkeillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Lähetän tulen Hasaelin linnaan, ja se syö Benhadadin palatsit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Murran Damaskon portinsalvan, hävitän Bikat-Aavenin hallitsijan ja Beet-Edenin valtikan, ja Aramin kansaa karkotetaan Kiiriin, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Näin sanoo Herra: Gassan kolmen rikoksen, neljän rikoksen tähden en sitä peru, koska he ovat vanginneet kaiken väen karkotusta varten ja luovuttaneet sen Edomille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'vaan lähetän tulen Gassan muuriin, ja se kuluttaa sen palatsit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Hävitän Asdodin hallitsijan ja Askelonin valtikan, ja ojennan käteni Ekronia vastaan, ja loputkin filistealaisista hukkuvat, sanoo Herra, Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Näin sanoo Herra: Tyyron kolmen rikoksen ja neljänkin tähden en peru sitä. Sillä he ovat luovuttaneet kaikki karkotettavat Edomille eivätkä ole muistaneet veljeysliittoa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'ja lähetän tulen Tyyron muuriin ja se kuluttaa sen palatsit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Näin sanoo Herra: Edomin kolmen rikoksen ja neljänkin tähden en peru sitä. Sillä se on vainonnut miekalla veljeään, tukahduttanut säälinsä, pitänyt ikuista vihaa ja säilyttänyt ainaisen raivonsa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'vaan lähetän tulen Teemania vastaan, ja se syö Bosran palatsit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Näin sanoo Herra: Ammonilaisten kolmen rikoksen ja neljänkin tähden en peru sitä, sillä he ovat viiltäneet auki Gileadin raskaana olevat vaimot laajentaakseen aluettaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'vaan sytytän tulen Rabban muuriin, ja se syö sen palatsit, kun sotahuuto raikuu sodan päivänä, ja hirmumyrsky pauhaa myrskyn päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'Heidän kuninkaansa vaeltaa karkotukseen, hän yhdessä ruhtinaidensa kanssa, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Näin sanoo Herra: Mooabin kolmen rikoksen, neljän rikoksen tähden en peru sitä, sillä he ovat polttaneet kalkiksi Edomin kuninkaan luut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Lähetän tulen Mooabiin, ja se kuluttaa Kerijotin palatsit ja Mooab kuolee sodan pauhussa sotahuudon kiiriessä ja torven soidessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Hävitän tuomarin sen keskeltä, ja kaikki sen päämiehet tapan yhdessä sen kanssa, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Näin sanoo Herra: Juudan kolmen rikoksen ja neljänkin tähden en sitä peru, sillä he ovat hylänneet Herran lain eivätkä ole pitäneet hänen säädöksiään, vaan harhaan ovat vieneet heidät heidän valheensa, joiden perässä jo heidän isänsä kulkivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Lähetän tulen Juudaan, ja se syö Jerusalemin palatsit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Näin sanoo Herra: Israelin kolmen rikoksen ja neljänkin tähden en sitä peru. Sillä he myyvät vanhurskaan rahasta ja köyhän sandaaliparista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'He polkevat maan tomuun köyhien pään ja vääristelevät kurjien asian ja poika ja isä käyvät saman naisen luona siten häväisten pyhän nimeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'He loikoilevat pantiksi otetuilla vaatteilla jokaisen alttarin vierellä ja juovat jumaliensa huoneessa sakkomaksuksi annettua viiniä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Minä hävitin heidän tieltään amorilaiset, jotka olivat pitkiä kuin isokasvuiset setrit ja vahvoja kuin tammet, mutta jotka tuhosin ylhäältä hedelmineen ja alhaalta juurineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Minä toin teidät Egyptin maasta ja kuljetin teitä erämaassa neljäkymmentä vuotta, että saatoitte ottaa omaksenne amorilaisten maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Poikienne joukosta olen herättänyt teille profeettoja ja nuorukaisistanne nasiireja. Eikö juuri näin ole tapahtunut, israelilaiset? Tämä on Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Mutta te juotatte nasiireille viiniä, ja profeettojanne kiellätte sanoen: \"Älkää profetoiko.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Katso, minä estän teitä liikkumasta paikaltanne. Teidän käy kuin vankkureiden, jotka juuttuvat, kun ne ahdetaan täyteen viljaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Silloin nopeakin menettää turvapaikkansa, väkevällä ei ole apua voimastaan eikä sankari pelasta henkeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'Jousimies ei kestä paikallaan, nopeajalkainen ei pelastu, eikä ratsumies pelasta henkeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'Sankareista rohkeinkin pakenee sinä päivänä sonnustautumatta, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Kuulkaa tämä sana, jonka Herra on puhunut teistä, te israelilaiset, koko siitä sukukunnasta, jonka johdatin Egyptin maasta, sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Yksin teidät valitsin kaikista maan sukukunnista. Sen tähden kostan teille kaikki pahat tekonne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Kulkeeko kaksi yhdessä siitä keskenään sopimatta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Karjahteleeko leijona metsässä, ellei sillä ole saalista? Ärjyykö nuori leijona luolastaan, ellei sillä ole saalista?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Käykö lintu maassa satimeen, ellei sen varalle ole pantu pyydystä? Onko ansa maasta koholla saaliin siihen tarttumatta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Puhalletaanko torveen kaupungissa, niin ettei kansa vapise? Tapahtuisiko kaupungissa onnettomuutta, jota Herra ei ole tehnyt?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Sillä Herra, Herra, ei tee mitään ilmoittamatta päätöstään palvelijoilleen profeetoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Leijona karjahtelee, kukapa ei pelkäisi? Herra, Herra puhuu, kukapa ei profetoisi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Julistakaa Asdodin palatseille ja Egyptin maan palatseille ja sanokaa: Kokoontukaa Samarian vuorille ja katselkaa, mikä hirveä meteli on sen keskellä ja millainen sorto sen sisällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'He eivät ymmärrä tehdä sitä, mikä on oikein – tämä on Herran sana – he kokoavat tavaraa palatseihinsa väkivallalla ja sorrolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Sen tähden, näin sanoo Herra, Herra: Vihollinen piirittää maan ja kukistaa mahtisi, ja palatsisi ryöstetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Näin sanoo Herra: Samoin kuin paimen saa pelastetuksi leijonan kidasta pari koipea tai palan korvaa, niin pelastuu israelilaisiakin, niitä, jotka istuvat Samariassa vuoteen kulmalla ja damaskoslaisella sohvan peitteellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Kuulkaa ja todistakaa Jaakobin heimoa vastaan – tämä on Herran, Herran Jumalan Sebaotin sana –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Sillä sinä päivänä kostan Israelille sen rikokset, kostan myös Beetelin alttareille, alttarin sarvet hakataan irti ja ne putoavat maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Sorran talvihuoneen kesähuoneen päälle, ja norsunluukoristeiset huoneet luhistuvat, ja paljoista huoneista tulee loppu. Tämä on Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Kuulkaa tämä sana, te Baasanin hiehot, jotka olette Samarian vuorella, jotka sorratte heikkoja ja kohtelette väärin köyhiä, jotka sanotte herroillenne: \"Tuokaa meille juotavaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Herra, Herra on vannonut pyhyytensä kautta: Totisesti, katso, päivät tulevat teille, jolloin teidät nostetaan ylös koukuilla ja loputkin ongenkoukuilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Te lähdette ulos, kuka mistäkin muurin halkeamasta, suin päin, ja teidät heitetään Harmoniin. Tämä on Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Menkää Beeteliin ja tehkää rikoksia, ja Gilgaliin ja tehkää vielä enemmän rikoksia. Tuokaa teurasuhrinne aamulla ja kymmenyksenne kolmantena päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Uhratkaa hapanta kiitosuhriksi, julistakaa vapaaehtoisia uhreja ja pitäkää niistä ääntä, sillä sehän on teille mieluista, te israelilaiset. Tämä on Herran, Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Minäkin tein hampaanne joutilaiksi kaikissa kaupungeissanne ja tuotin leivän puutteen kaikkiin paikkakuntiinne. Mutta te ette kääntyneet luokseni, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Minä pidätin teiltä sateen, kun vielä oli kolme kuukautta sadonkorjuuseen. Jollekin kaupungille annoin sadetta, mutta toiselle en. Jokin pelto sai sadetta, mutta toinen, jolle ei satanut, kuivui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'Silloin kaksi, kolmekin kaupunkia hoippui yhteen kaupunkiin vettä juomaan saamatta kyllikseen. Mutta ette kääntyneet luokseni, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Löin teitä nokitähkillä ja viljanruosteella. Teidän paljot puutarhanne, viinitarhanne, viikunapuunne ja öljypuunne söi kalvajasirkka. Mutta ette kääntyneet luokseni. Tämä on Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Lähetin teihin ruton, Egyptin ruton. Tapoin miekalla nuoret miehenne, ja ratsunne otettiin saaliiksi; ja nostatin löyhkän omasta leiristänne sieraimiinne. Mutta ette palanneet luokseni. Tämä on Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Panin toimeen hävityksen keskuudessanne, niin kuin Jumala hävitti Sodoman ja Gomorran, ja olitte kuin tulesta temmattu kekäle. Mutta ette palanneet luokseni. Tämä on Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Sen tähden teen sinulle, Israel, näin. Koska tämän sinulle teen, valmistaudu, Israel, kohtaamaan Jumalasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Sillä katso: hän on se, joka on tehnyt vuoret ja luonut tuulen, joka ilmoittaa ihmiselle ajatuksensa, joka tekee aamuruskon ja pimeyden ja joka kulkee maan kukkuloilla. Herra, Jumala Sebaot, on hänen nimensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Kuulkaa tämä sana. Se on kuolinvirsi, jonka minä laulan teistä, te Israelin heimo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Kaatunut on neitsyt Israel eikä enää nouse. Hän viruu maassaan hylättynä, eikä ole ketään, joka nostaisi hänet ylös.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Sillä näin sanoo Herra, Herra: Kaupunkiin, josta lähti liikkeelle tuhat, jää jäljelle sata; ja josta lähti sata, jää jäljelle kymmenen Israelin heimosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Sillä näin sanoo Herra Israelin heimolle: Etsikää minua, niin teillä on elämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Mutta älkää etsiytykö Beeteliin, älkää menkö Gilgaliin älkääkä vaeltako Beersebaan. Sillä Gilgal viedään karkotukseen, ja Beetel tuottaa pettymyksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Etsikää Herraa, niin teillä on oleva elämä, ettei hän tunkeutuisi tulena Joosefin huoneeseen ja kuluttaisi sitä tulella eikä olisi ketään, joka sammuttaisi Beetelin –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'te, jotka muutatte oikeuden koiruohoksi ja poljette maahan vanhurskauden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Hän on luonut Kiiman ja Kesilin ja muuttaa aamuksi kuoleman varjon ja pimentää päivän yöksi ja kutsuu meren vedet ja vuodattaa ne maan pinnalle. Herra on hänen nimensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Hän antaa hävityksen välähtää varustuksen yllä, ja linnoitus luhistuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'He vihaavat sitä, joka puolustaa portissa oikeutta, ja totuuden puhuja on heille kauhistus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Koska sorratte köyhää ottamalla häneltä viljasuorituksia, niin vaikka rakennatte taloja hakatusta kivestä, ette niissä asu, ja vaikka istutatte ihania viinitarhoja, ette juo niiden viiniä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Sillä tiedän, että rikoksenne ovat monet ja syntinne raskaat. Sorratte vanhurskasta, otatte lahjuksia ja väännätte vääräksi portissa köyhien asian.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Sen tähden viisas vaikenee tällaisena aikana, sillä aika on paha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Etsikää hyvää älkääkä pahaa, että eläisitte, ja Herra, Jumala Sebaot, on oleva kanssanne, kuten te sanotte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Vihatkaa pahaa ja rakastakaa hyvää ja saattakaa oikeus voimaan portissa. Ehkäpä Herra, Jumala Sebaot, armahtaa Joosefin jäännöstä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Sillä näin sanoo Herra, Jumala Sebaot, Herra: Joka torilla valitetaan ja joka kujalla sanotaan: \"Voi! Voi!\" Peltomiehiä kutsutaan surun viettoon ja itkuvirren taitajia valittajaisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Jokaisessa viinitarhassakin on valitus, sillä kuljen sinun keskitsesi, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Voi teitä, jotka toivotte Herran päivää. Miksi se olisi teille Herran päivä? Pimeä se on eikä valoisa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Teidän käy kuin miehen, joka pakeni leijonaa, mutta tuli karhu vastaan, tai miehen, joka kotiin tultuaan nojasi kädellään seinään ja häntä pisti käärme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Eikö Herran päivä ole pimeä eikä valoisa, eikö se ole synkkä eikä kirkas?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Vihaan ja inhoan juhlianne enkä mielly juhlakokouksiinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Sillä vaikka te tuotte minulle polttouhreja ja ruokauhreja, en niihin mielly, enkä katso teidän rauhanuhrinne, syöttövasikoittenne, puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Vie pois edestäni virsiesi pauhina, en tahdo kuulla harppujesi soittoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Mutta oikeus virratkoon kuin vesi ja vanhurskaus kuin ehtymätön puro.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Minulleko te uhrasitte erämaassa teurasuhreja ja ruokauhreja neljänkymmenen vuoden aikana, te Israelin heimo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'kun kannoitte Molokin majaa ja Kijjunia, noita epäjumalan kuvianne ja noiden jumalienne tähteä, jotka te itse teitte itsellenne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Vien teidät karkotukseen tuolle puolelle Damaskon, sanoo Herra Jumala Sebaot. Se on hänen nimensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Voi suruttomia Siionissa ja itsevarmoja Samarian vuorella, parhaan kansakunnan johtajia, ja heidän luokseen Israelin heimo menee!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Poiketkaa Kalneen ja katselkaa, kulkekaa sieltä Suureen Hamatiin ja laskeutukaa filistealaisten Gatiin. Ovatko ne paremmat kuin nämä valtakunnat, onko niiden alue suurempi teidän aluettanne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Olette karkottaneet kauas pahan päivän, mutta vedätte luoksenne väkivallan istumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Makaatte norsunluuvuoteilla ja loikoilette sohvillanne, syötte karitsoja laumasta ja vasikoita navetasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Sävellätte harpulle ja keksitte soittimia kuin Daavid.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Juotte viiniä maljoista ja voitelette itsenne parhaalla öljyllä, mutta ette murehdi Joosefin vammaa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Sen tähden he menevät nyt karkotukseen karkotettujen kärjessä ja loikoilijoiden ilakointi loppuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Herra, Herra on vannonut itsensä kautta, – tämä on Herran, Jumalan Sebaotin sana – minua etoo Jaakobin ylpeys, minä vihaan sen palatseja ja luovutan pois kaupungin ja kaiken, mitä siinä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Tapahtuu näin: Jos silloin johonkin taloon on jäänyt kymmenen miestä jäljelle, he kuolevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Omainen, joka huolehtii ruumiiden polttamisesta, kantaa ruumiita ulos ja kysyy talon perällä olevalta: \"Onko luonasi enää ketään?\" niin tämä vastaa: \"Ei ole\", ja hän sanoo: \"Hiljaa!\" – sillä Herran nimeä ei mainita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Sillä katso, Herra on antanut käskyn: hän lyö suuren talon palasiksi ja pienen talon säpäleiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Juoksevatko hevoset vuorenseinämää, kynnetäänkö sitä härillä? Sillä te muutatte oikeuden myrkyksi ja vanhurskauden hedelmän koiruohoksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'te, jotka iloitsette turhaan, kun sanotte: \"Emmekö omin voimin ottaneet haltuumme Karnaimia?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Sillä katso, nostan teitä vastaan, te Israelin heimo, – tämä on Herran, Jumalan Sebaotin sana – pakanakansan, joka ahdistaa teitä Hamatin tien päästä Araban puroon asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Tämän Herra, Herra näytti minulle: Katso, hän loi heinäsirkkoja, kun odelma alkoi nousta; ja katso, odelma oli nousemassa kuninkaan heinänkorjuun jäljiltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Tapahtui, että kun heinäsirkat olivat syöneet maan paljaaksi, sanoin: \"Herra, Herra, anna anteeksi. Kuinka Jaakob, joka on niin vähäinen, kestää?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Herra katui sitä. \"Se ei tapahdu\", Herra sanoi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Tämän jälkeen Herra, Herra näytti minulle: Katso, Herra, Herra kutsui tulen panemaan tuomion täytäntöön, ja se kulutti suuren syvyyden. Se kulutti myös peltomaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Sanoin: \"Herra, Herra, lakkaa jo. Kuinka voi Jaakob, joka on niin vähäinen, kestää?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Herra katui sitä. \"Ei sekään tapahdu\", Herra, Herra sanoi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Tämän hän näytti minulle: Katso, Herra seisoi luotisuoralla muurilla kädessään luotilanka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Herra kysyi minulta: \"Mitä sinä näet, Aamos?\" Vastasin: \"Luotilangan.\" Herra sanoi minulle: \"Katso, asetan luotilangan kansani Israelin keskelle. En säästä sitä enää kulkemalla sen ohi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Iisakin uhrikukkulat tulevat autioiksi ja Israelin pyhäköt raunioiksi. Käyn miekalla Jerobeamin suvun kimppuun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Silloin Amasja, Beetelin pappi, lähetti Jerobeamille, Israelin kuninkaalle, sanan: \"Aamos on tehnyt salaliiton sinua vastaan Israelin heimon keskuudessa. Ei maa kestä kaikkea, mitä hän puhuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Sillä näin Aamos on sanonut: \'Jerobeam kuolee miekkaan, ja Israel viedään karkotukseen pois omasta maastaan.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Amasja sanoi Aamokselle: \"Näkijä, mene matkoihisi, pakene Juudan maalle, syö leipäsi siellä ja profetoi siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Mutta Beetelissä et enää profetoi, sillä tämä on kuninkaan pyhäkkö ja valtakunnan temppeli.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Aamos vastasi Amasjalle sanoen: \"En minä ole profeettoja enkä profeetanoppilaita, vaan minä olen karjapaimen ja metsäviikunoiden poimija.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Mutta Herra otti minut laumojeni äärestä, ja Herra sanoi minulle: \'Mene profetoimaan kansaani Israelia vastaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Kuule siis nyt Herran sana: Sinä sanot: \'Älä profetoi Israelia vastaan äläkä saarnaa Iisakin heimoa vastaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Sen tähden, näin sanoo Herra: Sinun vaimostasi tulee portto kaupunkiin, poikasi ja tyttäresi kaatuvat miekkaan, maasi jaetaan mittanuoralla, sinä kuolet saastaisella maalla, ja Israel totisesti karkotetaan maastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Tämän Herra, Herra näytti minulle: Katso, oli korillinen kesän hedelmiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Hän sanoi: \"Mitä sinä näet, Aamos?\" Minä vastasin: \"Korillisen kesän hedelmiä.\" Herra sanoi minulle: \"Kansalleni Israelille on tullut loppu: en enää mene sen ohi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Sinä päivänä temppelin virret muuttuvat valitukseksi – tämä on Herran, Herran sana – ruumiita on paljon, kaikkialle heiteltyjä. Hiljaa!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Kuulkaa tämä, te jotka sorratte vähäosaisia ja tuhoatte maan köyhiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'sanoen: \"Milloin päättyy uusikuu, että voimme myydä viljaa, ja milloin sapatti, jotta voimme avata jyväaitan, pienentää eefa-mitan ja suurentaa sekelin painon ja pettää väärällä vaa\'alla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'ja jotta saamme ostaa vähäosaiset rahalla ja köyhät sandaaliparilla ja myydä akanoita jyvinä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Herra on vannonut Jaakobin kunnian kautta: Totisesti, en unohda yhtään heidän tekoaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Eikö tämän tähden maa järky ja sen jokainen asukas murehdi? Eikö se nouse kaikkineen kuin Niili, kohoa ja laske kuin Egyptin virta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'Sinä päivänä tapahtuu – tämä on Herran, Herran sana – että annan auringon laskea keskipäivällä ja maan pimetä keskellä kirkasta päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Muutan juhlanne murheeksi ja kaikki laulunne kuolinvirsiksi. Puetan kaikkien lanteille säkkipuvun ja ajatan paljaaksi jokaisen pään. Saatan teidät suremaan, kuin ainoaa poikaa surraan, ja se päättyy kuin katkera päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Katso, päivät tulevat, sanoo Herra, Herra, jolloin lähetän nälän maahan: en leivän nälkää enkä veden janoa, vaan Herran sanojen kuulemisen nälän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'He hoippuvat merestä mereen, pohjoisesta itään. He etsivät Herran sanaa, mutta eivät löydä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'Sinä päivänä nääntyvät janoon kauniit neitsyet ja nuorukaiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'ne, jotka vannovat Samarian syntivelan nimeen, ja sanovat: \"Niin totta kuin jumalasi, Daab, elää, ja niin totta kuin Beerseban tie on elämä!\" – He kaatuvat eivätkä enää nouse.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Näin Herran seisovan alttarin ääressä, ja hän sanoi: Lyö pylväänpäihin, niin että kynnykset vapisevat. Lyö niillä heitä kaikkia päähän niin, että ne menevät säpäleiksi. Tapan miekalla heistä viimeisetkin. Yksikään heistä ei pääse pakoon eikä kukaan heistä pelastu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Vaikka he kaivautuisivat helvettiin, sielläkin käteni tarttuisi heihin. Vaikka he nousisivat taivaaseen, sieltäkin syöksisin heidät alas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'Vaikka he menisivät Karmelin harjanteelle, sieltäkin etsisin ja sieppaisin heidät. Vaikka he piiloutuisivat meren pohjaan silmieni edestä, sielläkin käskisin käärmeen heitä pistää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Vaikka he kulkisivat vihollistensa edellä vankeuteen, käskisin miekan heitä tappamaan. Sillä luon katseeni heihin, heille pahaksi, en hyväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Herra, Herra Sebaot, hän, joka koskettaa maata, niin että se sulaa, että kaikki sen asukkaat murehtivat, että se nousee kaikkineen kuin Niili ja alenee kuin Egyptin virta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'hän, joka on rakentanut yläsalinsa taivaisiin ja laskenut joukkonsa perustuksen maan päälle, ja joka kutsuu meren vedet ja vuodattaa ne maan pinnalle – Herra on hänen nimensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Ettekö te, israelilaiset, ole minulle kuin kuusilaisetkin? – tämä on Herran sana – enkö johdattanut Israelia Egyptin maasta ja filistealaisia Kaftorista ja aramilaisia Kiiristä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Katso, Herran, Herran silmät ovat sitä valtakuntaa vastaan, joka syntiä tekee, ja hävitän sen maan päältä. Kuitenkaan en hävitä kokonaan Jaakobin heimoa, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Sillä katso, minä käsken seuloa Israelin heimoa kaikkien kansojen seassa, niin kuin seulalla seulotaan: jyväkään ei putoa maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Miekkaan kuolevat kaikki kansani syntiset, jotka sanovat: \"Ei saavuta, ei meitä kohtaa onnettomuus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'Sinä päivänä pystytän jälleen Daavidin sortuneen majan ja korjaan sen repeämät ja pystytän sen luhistumat, ja rakennan sen sellaiseksi, kuin se oli entisinä päivinä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'niin että he saavat omikseen Edomin jäännöksen ja kaikki pakanakansat, joiden keskellä nimeäni julistetaan – tämä on Herran sana – hän sen tekee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Katso, päivät tulevat, sanoo Herra, jolloin kyntäjä tavoittaa sadonkorjaajan ja rypäleiden polkija siemenen kylväjän, jolloin vuoret vuotavat nuorta viiniä ja kaikki kukkulat ovat hedelmällisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Palautan kansani Israelin vankeudesta. He rakentavat jälleen autiot kaupungit ja asuvat niissä. He istuttavat viinitarhoja ja juovat niiden viiniä. He perustavat puutarhoja ja syövät niiden hedelmiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Istutan heidät heidän maahansa, eikä heitä enää revitä pois maasta, jonka olen heille antanut, sanoo Herra, Jumalasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Obadjan näky. Herra, Herra sanoo Edomista näin: Olemme kuulleet sanoman Herralta, ja sanansaattaja on lähetetty kansakuntiin: \"Nouskaa, nouskaamme sotaan sitä vastaan!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Katso, pieneksi teen sinut kansojen joukossa, kovin halveksittu olet oleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Sydämesi ylpeys on pettänyt sinut, joka asut kallionrotkoissa ja istut korkealla ja sanot sydämessäsi: \"Kuka voi syöstä minut maahan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Vaikka nousisit korkealle kuin kotka ja asettaisit pesäsi tähtien väliin, sieltäkin syöksisin sinut alas, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Jos varkaat ja yölliset rosvot tulisivat kimppuusi, kuinka voisit tulla niin hävitetyksi: eivätkö he varastaisi vain sen, mitä tarvitsevat? Jos rypäleiden poimijat tulisivat luoksesi, eivätkö he jättäisi jälkikorjuuta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Mutta kuinka onkaan Eesau läpikotaisin etsitty ja hänen kätkönsä pengottu!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Sinut on ajettu rajalle asti, kaikki liittolaisesi ovat sinut pettäneet. Ne, jotka asuivat rauhassa kanssasi, ovat vieneet sinusta voiton, ja panneet tarjoamasi leivän paulaksi eteesi. – Hänessä ei ole ymmärrystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Enkö sinä päivänä, sanoo Herra, lopeta viisaat Edomista ja ymmärryksen Eesaun vuorelta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Silloin sankarisi, Teeman, kauhistuvat, että jokainen mies hävitettäisiin Eesaun vuorelta tappamalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Väkivallan tähden veljeäsi Jaakobia kohtaan peittää sinut häpeä, ja sinut hävitetään ikiajoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Sinä päivänä, jona sinäkin olit läsnä, päivänä, jona vieraat veivät vankeuteen hänen sotajoukkonsa ja muukalaiset tunkeutuivat sisään hänen porteistaan ja heittivät arpaa Jerusalemista, sinäkin olit kuin yksi heistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Mutta älä katso iloiten veljesi päivää, hänen onnettomuutensa päivää; älä ilku Juudan lapsille heidän turmionsa päivänä äläkä ylvästele suullasi heidän ahdistuksensa päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Älä tule sisään kansani portista sen onnettomuuden päivänä äläkä sinäkään iloiten katsele hänen onnettomuuttaan hänen hätäpäivänään äläkä ojenna kättäsi hänen rikkauteensa hänen hätäpäivänään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Älä seiso tienhaarassa hävittämässä hänen pelastuneitaan. Älä luovuta hänen pakoon päässeitään ahdistuksen päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Sillä lähellä on Herran päivä kaikkia pakanakansoja: Niin kuin olet tehnyt, niin sinulle tehdään. Kosto teostasi kääntyy takaisin omaan päähäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Sillä niin kuin olette juoneet pyhällä vuorellani, niin tulevat kaikki pakanakansat juomaan ainiaan. He juovat, nielevät ja ovat, kuin ei heitä olisi ollutkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Mutta Siionin vuorella on pelastus, ja se on oleva pyhä, ja Jaakobin heimo saa haltuunsa perintönsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Jaakobin heimo on oleva tuli ja Joosefin heimo liekki, mutta Eesaun heimo kuin olki, ja ne polttavat sen ja kuluttavat sen, eikä ketään jää jäljelle Eesaun heimosta. Sillä Herra on puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Silloin he ottavat perinnökseen Negevin sekä Eesaun vuoren, Alankomaan sekä filistealaiset. He ottavat perinnökseen Efraimin maan ja Samarian maan, Benjaminin sekä Gileadin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Tästä väestä, israelilaisista, viedyt karkotetut ottavat perinnökseen kanaanilaiset Sarpatiin asti. Jerusalemin karkotetut, jotka ovat Sefaradissa, ottavat perinnökseen Negevin kaupungit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Pelastajia nousee Siionin vuorelle tuomitsemaan Eesaun vuorta, ja kuninkuus on oleva Herran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Joonalle, Amittain pojalle, tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, '\"Nouse, mene Niiniveen, siihen suureen kaupunkiin, ja saarnaa sitä vastaan, sillä heidän pahuutensa on noussut kasvojeni eteen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Mutta Joona nousi paetakseen Tarsiiseen Herran kasvojen edestä ja meni alas Jaafoon ja löysi laivan, joka oli lähdössä Tarsiiseen. Hän suoritti laivamaksun ja astui siihen mennäkseen heidän kanssaan Tarsiiseen, pois Herran kasvojen edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Mutta Herra heitti suuren tuulen merelle, niin että merellä nousi suuri myrsky ja laiva oli särkymäisillään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Merimiehet pelkäsivät ja huusivat avuksi itse kukin jumalaansa, ja heittivät mereen tavaroita, mitä laivassa oli, keventääkseen sitä. Mutta Joona oli mennyt alas laivan pohjalle ja pannut maata, ja nukkui raskaasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Laivuri tuli hänen luokseen ja sanoi hänelle: \"Miksi nukut? Nouse ja huuda jumalaasi. Ehkäpä se jumala muistaa meitä, niin ettemme huku.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Sitten he sanoivat toisilleen: \"Tulkaa, heittäkäämme arpaa, saadaksemme tietää, kenen tähden tämä onnettomuus on meille tullut.\" Mutta kun he heittivät arpaa, arpa lankesi Joonalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Niin he sanoivat hänelle: \"Ilmoita meille, kenen tähden tämä onnettomuus on meille tullut. Mikä on toimesi ja mistä tulet? Mikä on maasi ja mistä kansasta olet?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Hän vastasi heille: \"Minä olen heprealainen, ja minä pelkään Herraa, taivaan Jumalaa, joka on tehnyt meren ja kuivan maan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Miehet pelästyivät suuresti ja sanoivat hänelle: \"Miksi olet tehnyt näin?\" Sillä miehet tiesivät, että hän oli pakenemassa Herran kasvojen edestä. Hän oli näet ilmaissut sen heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'He sanoivat hänelle: \"Mitä meidän on tehtävä sinulle, että meri tyyntyisi meille?\" Sillä meri myrskysi myrskyämistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Hän vastasi heille: \"Ottakaa minut ja heittäkää minut mereen, niin meri teille tyyntyy. Sillä minä tiedän, että tämä suuri myrsky on tullut teille minun tähteni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Miehet soutivat päästäkseen jälleen kuivalle maalle, mutta eivät voineet, sillä meri myrskysi myrskyämistään heitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'He huusivat Herraa ja sanoivat: \"Voi, Herra, älä anna meidän hukkua tämän miehen hengen tähden äläkä lue syyksemme viatonta verta, sillä sinä, Herra, teet, niin kuin sinulle on otollista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'He ottivat Joonan ja heittivät hänet mereen, ja meri asettui raivostaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Miehet pelkäsivät suuresti Herraa, uhrasivat Herralle teurasuhrin ja tekivät lupauksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Herra toimitti suuren kalan nielaisemaan Joonan. Joona oli kalan sisällä kolme päivää ja kolme yötä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Joona rukoili Herraa, Jumalaansa, kalan sisällä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'ja sanoi: \"Huusin ahdistuksessani Herraa, ja hän vastasi minulle. Haudan helmasta huusin apua, ja kuulit ääneni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Syöksit minut syvyyteen, merten sydämeen, ja virta ympäröi minua, kaikki sinun kuohusi ja aaltosi nousivat ylitseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Minä ajattelin: Olen karkotettu pois silmiesi edestä. Kuitenkin minä vielä tulen katselemaan pyhää temppeliäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Vedet piirittivät minut sieluun asti, syvyys ympäröi minua, kaisla kietoutui päähäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Vajosin alas vuorten perustuksiin asti, maan salvat sulkeutuivat ylitseni iankaikkisesti. Mutta sinä, Herra, Jumalani, nostit henkeni ylös haudasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Kun sieluni nääntyi minussa, muistin Herraa, ja rukoukseni tuli luoksesi, pyhään temppeliisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Ne, jotka kunnioittavat turhia jumalia, hylkäävät armonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Mutta minä tahdon uhrata sinulle kiitoksen kaikuessa, kuten olen luvannut. Herrassa on pelastus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 11, 'Herra käski kalaa, ja se oksensi Joonan kuivalle maalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Joonalle tuli toistamiseen tämä Herran sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, '\"Nouse ja mene Niiniveen, siihen suureen kaupunkiin, ja saarnaa sille se saarna, minkä minä sinulle puhun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Joona nousi ja meni Niiniveen Herran sanan mukaan. Niinive oli suuri kaupunki Jumalan edessä: kolme päivämatkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Joona tultuaan kaupunkiin käveli aluksi yhden päivämatkan ja saarnasi sanoen: \"Vielä neljäkymmentä päivää, ja Niinive hävitetään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Niiniven miehet uskoivat Jumalaan, kuuluttivat paaston ja pukeutuivat säkkeihin, suurista pieniin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Kun sana tästä saavutti Niiniven kuninkaan, hän nousi valtaistuimeltaan, riisui viittansa päältään, verhoutui säkkiin ja istuutui tuhkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Hän kuulutti ja sanoi Niinivessä: \"Kuninkaan ja hänen ylimystensä määräys kuuluu: Älkööt ihmiset älköötkä eläimet – naudat ja lampaat – maistako mitään, käykö laitumella tai juoko vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Verhoutukoot ihmiset ja eläimet säkkeihin, huutakoot voimakkaasti Jumalaa ja kääntykööt itse kukin pois pahalta tieltään sekä kättensä väkivallasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Ehkä Jumala jälleen katuu ja kääntyy pois vihansa hehkusta, niin ettemme huku.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Kun Jumala näki heidän tekonsa, että he kääntyivät pois pahalta tieltään, Jumala katui sitä pahaa, minkä hän oli sanonut tekevänsä heille, eikä tehnyt sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Joona pahastui tästä kovasti ja vihastui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Hän rukoili Herraa ja sanoi: \"Voi Herra! Enkö sitä sanonut, kun olin vielä omassa maassani? Siksi kiirehdin pakenemaan Tarsiiseen. Sillä tiesin, että sinä olet armahtavainen ja laupias Jumala, pitkämielinen, ja että armosi on suuri, ja että kadut onnettomuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Nyt, Herra, ota henkeni, sillä kuolema on minulle parempi kuin elämä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Mutta Herra sanoi: \"Onko vihastumisesi oikea?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Joona lähti kaupungista ja asettui kaupungin itäpuolelle. Hän teki itselleen sinne lehtimajan ja istuutui sen alle varjoon, kunnes näkisi, miten kaupungin käy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Herra Jumala antoi risiinikasvin kasvaa Joonan pään ylle varjostamaan hänen päätään ja päästämään häntä hänen mielipahastaan. Joona iloitsi suuresti risiinikasvista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Seuraavana päivänä aamun sarastaessa Jumala toimitti madon kalvamaan risiinikasvia, niin että se kuivui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Auringon noustua Jumala toimitti tulikuuman itätuulen, ja aurinko paahtoi Joonan päähän, niin että hän oli nääntyä. Hän toivotti itselleen kuolemaa ja sanoi: \"Parempi on minulle kuolema kuin elämä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Jumala sanoi Joonalle: \"Onko vihastumisesi risiinikasvin tähden oikea?\" Tämä vastasi: \"Oikea on vihastumiseni kuolemaan asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Herra sanoi: \"Sinä säälit risiinikasvia, josta et ollut vaivaa nähnyt ja jota et ollut kasvattanut, joka yhden yön lapsena syntyi ja yhden yön lapsena kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'Enkö minä säälisi Niiniveä, sitä suurta kaupunkia, jossa on enemmän kuin sata kaksikymmentä tuhatta ihmistä, jotka eivät vielä tiedä, kumpi käsi on oikea, kumpi vasen, niin myös paljon eläimiä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Herran sana, joka tuli mooresetilaiselle Miikalle Jootamin, Aahaan ja Hiskian, Juudan kuninkaiden, päivinä, se, mitä hän näki Samariasta ja Jerusalemista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Kuulkaa, kaikki kansakunnat, ota korviisi, maa, ja kaikki, mitä maassa on. Olkoon Herra Herra todistaja teitä vastaan, Herra pyhästä temppelistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Sillä, katso, Herra lähtee paikaltaan, astuu alas ja tallaa maan kukkuloita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Vuoret sulavat hänen allaan, ja laaksot halkeavat kuin vaha tulen loimussa ja kuin vedet, jotka syöksyvät jyrkännettä alas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Tämä kaikki tapahtuu Jaakobin rikoksen tähden ja Israelin heimon syntien tähden. Mikä on Jaakobin rikos? Eikö Samaria! Entä mikä Juudan uhrikukkuloiden? Eikö Jerusalem!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Teen Samarian raunioksi kedolle, viinitarhan istutusmaaksi, syöksen laaksoon sen kivet ja paljastan sen perustukset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Kaikki sen jumalankuvat murskataan, kaikki sen portonpalkat poltetaan tulessa, ja kaikki sen epäjumalankuvat hävitän, sillä portonpalkoista se on ne koonnut, ja portonpalkoiksi pitää niiden jälleen tulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Tämän tähden itken ja olen murheellinen, kuljen avojaloin ja alasti, vaikeroin kuin sakaalit ja valitan kuin strutsit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Sillä parantumaton on sen haava. Se ulottuu Juudaan asti, se on saavuttanut kansani portin ja on tullut aina Jerusalemiin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Älkää ilmoittako sitä Gatissa, älkää, älkää itkekö. Kieriskelen tuhkassa Beet-Leafrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Mene matkoihisi, Saafirin asujatar, häpeällisesti paljastettuna! Saananin asujatar ei lähde. Beet-Eselin valitus ei anna teidän siihen pysähtyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Onnea odottaa tuskaisesti Maarotin asujatar; sillä onnettomuus tulee Herralta Jerusalemin portille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Valjasta hevoset vaunujen eteen, Laakiin asujatar. Sieltä on alku tytär Siionin syntiin, sillä sinusta löydettiin Israelin rikokset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Sen tähden annat eron Mooreset-Gatille. Aksibin talot tulevat olemaan pettymys Israelin kuninkaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Tuon vielä perijän sinulle, Maaresan asujatar. Adullamiin asti menee Israelin kunnia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Aja ja keritse pääsi paljaaksi lasten tähden, jotka olivat ilosi. Aja pääsi leveälti paljaaksi, kuten on korppikotkalla, sillä he menevät luotasi pois karkotukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Voi niitä, jotka miettivät vääryyttä ja valmistelevat pahaa vuoteillaan! Aamun valjettua he sen tekevät, sillä siihen heillä on valta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'He himoitsevat peltoja ja ryöstävät ne, ja taloja, ja anastavat ne. He sortavat miestä ja hänen taloaan, miestä ja hänen perintöosaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Sen tähden, näin sanoo Herra: Katso, mietin tätä sukua vastaan onnettomuutta, josta ette saa irti niskaanne ettekä voi kävellä ylpeästi, sillä se on oleva paha aika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'Sinä päivänä teistä tehdään sananparsi ja valitetaan surkeasti. Sanotaan: \"Olemme aivan hävitetyt, hän on antanut pois kansani perintöosan. Kuinka hän siirtää sen minulta pois ja jakaa peltomme muille!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Sen tähden sinulla ei ole oleva ketään, joka heittäisi arpaa maaosuudesta Herran seurakunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, '\"Älkää ennustako, ennustajat, älkää sellaista ennustako, ettei teitä kohtaisi häpeä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Onko tämä Jaakobin heimon puhetta? Onko Herran Henki kärsimätön? Ovatko hänen tekonsa lyhytnäköisiä? Eivätkö hänen sanansa ole hyviä sitä kohtaan, joka vaeltaa suoraan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Mutta kansani, joka ennen oli minun, on noussut viholliseksi. Vaatteiden päältä te kiskotte viitan niiltä, jotka kulkevat rauhassa ja palaavat sodasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Kansani naiset te ajatte pois heidän kodeistaan, jotka ovat heidän ilonsa. Heidän pieniltä lapsiltaan te viette kunniani ainiaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Nouskaa ja menkää! Sillä tämä ei ole leposija saastutuksen tähden, joka on saanut aikaan tuhon, hirvittävän tuhon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Jos tulisi tuulen tavoittelija ja valehtelisi petollisuudessaan ja sanoisi: \"Saarnaan sinulle viinistä ja väkijuomasta\", siinä olisi ennustaja tälle kansalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Kokoan sinut kokoamalla, Jaakob, kaikkinesi ja kerään huolella Israelin jäännöksen, saatan heidät yhteen kuin lampaat tarhaan, kuin lauman laitumelleen. On oleva ihmisten kohina!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Tien aukaisija käy heidän edellään. He aukaisevat tiensä, ohittavat portin ja lähtevät siitä ulos. Heidän Kuninkaansa kulkee heidän edellään, ja Herra johdattaa heitä heidän edellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Sanoin: Kuulkaa, Jaakobin johtajat ja Israelin heimon ruhtinaat! Eikö teidän tulisi tuntea oikeus,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'teidän, jotka vihaatte hyvää ja rakastatte pahaa, jotka raastatte ihmisten nahan heidän päältään ja lihan irti heidän luistaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'He syövät kansani lihan ja nylkevät nahan heidän päältään ja murskaavat heidän luunsa, paloittelevat kuin pataan, kuin lihan kattilaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Kun he huutavat Herran puoleen, hän ei vastaa heille, vaan kätkee kasvonsa heiltä sinä aikana, koska he ovat tehneet pahoja tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Näin sanoo Herra niitä profeettoja vastaan, jotka eksyttävät kansaani ja huutavat: \"Rauha!\", kun heidän hampaissaan on purtavaa, mutta julistavat pyhän sodan sille, joka ei anna mitään heidän suuhunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Sen tähden teille tulee yö näyistänne, pimeys ennusteluistanne. Aurinko laskee näiltä profeetoilta, ja päivä heiltä pimenee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Näkijät joutuvat häpeään, ja ennustelijat joutuvat pilkatuiksi. Kaikki he sulkevat suunsa, sillä Jumalan vastausta ei tule.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Mutta minä olen todella täynnä voimaa, Herran Henkeä, tuomiota ja väkevyyttä ilmoittaakseni Jaakobille sen rikokset ja Israelille sen synnit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Kuulkaa tämä, Jaakobin huoneen johtajat ja Israelin huoneen ruhtinaat, te, jotka halveksitte oikeutta ja vääristätte kaiken suoran,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'rakennatte Siionia veritöillä ja Jerusalemia vääryydellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Sen johtajat jakavat oikeutta lahjuksia vastaan, sen papit opettavat maksusta, ja sen profeetat ennustelevat rahasta. Mutta Herraan he turvautuvat sanoen: \"Eikö Herra ole keskellämme? Ei tule meille onnettomuutta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Siitä syystä teidän tähtenne Siion kynnetään pelloksi, Jerusalem tulee kiviraunioksi ja temppelivuori metsäiseksi kukkulaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'On oleva päivien lopulla: Herran temppelin vuori on oleva vahva, kaikkia muita vuoria ylempänä, kukkuloista korkeimpana, ja kaikista pakanakansoista virtaa sinne väkeä solkenaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Niin monet pakanakansat lähtevät liikkeelle sanoen: \"Tulkaa mukaan, nouskaamme Herran vuorelle, Jaakobin Jumalan huoneeseen, että hän opettaisi meille teitään ja vaeltaisimme hänen polkujaan; sillä Siionista lähtee laki ja Jerusalemista Herran sana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Hän tuomitsee monien kansakuntien kesken, säätää oikeutta väkeville pakanakansoille kaukaisiin maihin asti. He takovat miekkansa aurankärjiksi ja keihäänsä viinivesoimiksi eikä kansa nosta miekkaa toisiaan vastaan, eivätkä he enää opettele käymään sotia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'He istuvat kukin oman viinipuunsa ja viikunapuunsa alla kenenkään pelottelematta. Sillä Herran Sebaotin suu on puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Sillä kaikki kansakunnat vaeltavat jumalansa nimessä kukin, mutta me vaellamme Herran, meidän Jumalamme, nimessä aina ja iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'Sinä päivänä – tämä on Herran sana – tahdon koota ontuvat ja kerätä hajalle ajetut ja ne, joille olin tuottanut onnettomuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Teen ontuvista jäännöksen ja kauas hajotetuista väkevän kansan. Silloin Herra on oleva heidän kuninkaansa Siionin vuorella siitä alkaen ja iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Sinä Karjatorni, tytär Siionin kukkula! Sinun luoksesi tulee ja saapuu entinen hallitus, tytär Jerusalemin kuninkuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Nyt – miksi vaikeroit ääneen? Eikö sinulla ole kuningasta, onko sinun neuvonantajasi kadonnut, koska kipu on vallannut sinut kuin synnyttäjän?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Vääntelehdi vain kouristuksissasi, tytär Siion, kuin synnyttäjä, sillä nyt sinun on lähdettävä ulos kaupungista ja asuttava kedolla ja mentävä Baabeliin asti. Siellä sinut pelastetaan. Siellä Herra lunastaa sinut vihamiestesi käsistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Nyt kokoontuu sinua vastaan paljon pakanoita, jotka sanovat: \"Se saastutettakoon. Katselkoon silmämme Siionia!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Mutta he eivät tunne Herran ajatuksia eivätkä ymmärrä hänen neuvoaan, sillä hän kokoaa heidät kuin lyhteet puimatantereelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Nouse ja pui, tytär Siion, sillä annan sinulle rautasarvet ja vaskisorkat sinulle annan, ja sinä murskaat monet kansat. Vihin Herralle, tuhon omaksi, heidän väärän voittonsa, kaiken maan Herralle heidän rikkautensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 14, 'Nyt yhdy laumaksi, sinä hyökkääjien ahdistama tytär! Meitä piiritetään, he lyövät sauvalla poskelle Israelin tuomaria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Mutta sinä, Beetlehem Efrata, joka olet vähäinen olemaan Juudan sukujen joukossa, sinusta minulle tulee se, joka on oleva hallitsija Israelissa, jonka alkuperä on muinaisuudesta, iankaikkisista päivistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Sen tähden Herra antaa heidät alttiiksi siihen aikaan asti, jolloin synnyttäjä on synnyttänyt. Silloin jäljellejääneet hänen veljistään palaavat israelilaisten luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Hän on astuva esiin ja kaitseva Herran voimassa, Herran, Jumalansa, nimen valtasuuruudessa. He asuvat alallaan, sillä hän on oleva suuri maan ääriin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Hän on oleva rauha. Kun Assur saapuu maahamme ja kun se tulee palatseihimme, asetamme sitä vastaan seitsemän paimenta ja kahdeksan ruhtinasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'Nämä kaitsevat miekalla Assurin maata, Nimrodin maata aivan sen omilla porteilla. Hän on pelastava meidät Assurilta, kun se tulee maahamme ja kun se astuu alueellemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Ne, jotka ovat jäljellä Jaakobista monien kansojen seassa, ovat kuin kaste Herralta, kuin rankkasade ruohikolle. Se ei odota miestä eikä varro ihmislapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Ne, jotka ovat jäljellä Jaakobista pakanoiden seassa monien kansojen keskellä, ovat kuin leijona metsän eläinten seassa, kuin nuori leijona lammaslaumojen keskellä. Jos se hyökkää, tallaa maahan ja raatelee, pelastajaa ei ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Kohotkoon kätesi vihollisiasi vastaan, ja vihamiehesi joutukoot häviöön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Tapahtuu, että sinä päivänä, – tämä on Herran sana – hävitän keskuudestasi hevosesi ja teen lopun sotavaunuistasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'Hävitän maasi kaupungit ja hajotan maahan kaikki linnoituksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'Hävitän sinulta käsistä povaamisen eikä sinulla ole enää ennustelijoita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Hävitän keskuudestasi jumalankuvasi ja patsaasi, etkä sinä enää kumarra kättesi tekoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Kukistan aserasi keskuudestasi ja tuhoan kaupunkisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Kostan vihassa ja kiivaudessa pakanakansoille, jotka eivät olleet kuuliaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Kuulkaa, mitä Herra sanoo: Nouse ja käy oikeutta vuorten kanssa, ja kukkulat kuulkoot äänesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Kuulkaa Herran oikeudenkäyntiä, vuoret, te iäti kestävät, maan perustukset, sillä oikeudenkäynti on Herralla kansaansa vastaan ja Israelille hän pitää tuomion:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, '\"Kansani, mitä olen sinulle tehnyt, ja millä olen sinut väsyttänyt? Vastaa minulle!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Olenhan johdattanut sinut Egyptin maasta, vapahtanut sinut orjuuden pesästä ja lähettänyt Mooseksen, Aaronin ja Mirjamin käymään edelläsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Muista, kansani, mitä Baalakilla, Mooabin kuninkaalla, oli mielessä, ja mitä Bileam, Beorin poika, hänelle vastasi, Sittimistä Gilgaliin asti, että käsittäisit Herran vanhurskaat teot.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, '\"Mitä uhraan, kun käyn Herran eteen ja kumarrun korkeuden Jumalan puoleen? Käynkö hänen eteensä tuoden polttouhreja, vuodenvanhoja vasikoita?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Ovatko Herralle mieleen tuhannet pässit, kymmenettuhannet öljyvirrat? Annanko esikoiseni rikoksestani ja ruumiini hedelmän sieluni syntiuhriksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Hän on ilmoittanut sinulle, ihminen, mikä hyvä on, ja mitä muuta Herra sinulta vaatii, kuin että teet sitä, mikä on oikein, rakastat laupeutta ja vaellat nöyrästi Jumalasi kanssa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Herran ääni huutaa kaupungille – ja on ymmärrystä ottaa nimestäsi vaari. Totelkaa vitsaa ja häntä, joka on sen määrännyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Vieläkö ovat jumalattoman talossa vääryyden aarteet ja vajaa, kirottu eefa-mitta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Olisinko puhdas, jos minulla olisi väärä vaaka ja kukkarossa petolliset punnukset?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Sen rikkaat ovat täynnä väkivaltaa, sen asukkaat puhuvat valhetta, kieli heidän suussaan on petollinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Niinpä minäkin lyön sinut sairaaksi, teen sinut autioksi syntiesi tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Sinä syöt, mutta et tule ravituksi, ja vatsassasi on tyhjyys. Minkä viet pois, sitä et saa pelastetuksi, ja minkä pelastetuksi saat, sen annan miekan omaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Sinä kylvät, mutta et leikkaa. Sinä puserrat öljyä, mutta et voitele itseäsi öljyllä, ja puserrat rypälemehua, mutta et juo viiniä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Mutta Omrin ohjeita noudatetaan ja kaikkia Ahabin suvun tekoja. Heidän neuvojensa mukaan te vaellatte, että saattaisin sinut autioksi ja sen asukkaat pilkaksi. Te tulette kantamaan kansani häväistyksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Voi minua, sillä minun käy kuin hedelmänkorjuussa, kuin viinisadon jälkikorjuussa: ei ole rypälettä syödäkseni, ei varhaisviikunaa, jota sieluni haluaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Hävinneet ovat pyhät maasta, eikä oikeamielisiä ole ihmisten joukossa. Kaikki he väijyvät verta ja pyydystävät verkolla toinen toistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Heidän kätensä ovat taitavia tekemään pahaa. Ruhtinas ja tuomari vaativat lahjuksia, ja mahtavat puhuvat julki sielunsa himon ja vääristelevät asian.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Paras heistä on kuin orjantappura, oikeamielisin pahempi kuin teräväokainen aita. Vartijoidesi ilmoittama päivä, kosto sinulle, tulee. Nyt he joutuvat sekasortoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Älkää uskoko ystävää, älkää luottako uskottuun. Siltä, joka sylissäsi lepää, varjele suusi ovet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Sillä poika halveksii isää, tytär nousee äitiään vastaan ja miniä anoppiaan vastaan. Ihmisen vihamiehiä ovat hänen omat perhekuntalaisensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Mutta minä panen toivoni Herraan ja odotan pelastukseni Jumalaa. Jumalani on minua kuuleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Älkää iloitko, viholliseni, minusta. Jos olen langennut, niin nousen. Jos istun pimeydessä, Herra on valkeuteni.:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Kannan Herran vihaa, sillä olen tehnyt syntiä häntä vastaan, siihen asti, että hän hoitaa riita-asiani ja hankkii minulle oikeuden. Hän tuo minut valkeuteen, ja katselen hänen vanhurskauttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Viholliseni näkevät sen, ja häpeä peittää ne, jotka sanovat minulle: \"Missä on Herra, Jumalasi?\" Silmäni katselevat heitä. Nyt he joutuvat tallattaviksi kuin katujen loka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Tulee päivä, jolloin muurisi rakennetaan. Sinä päivänä rajasi on oleva kaukana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'sinä päivänä tullaan luoksesi Assurista ja Egyptin kaupungeista, kaikkialta, Egyptistä aina Eufrat-virtaan, merestä mereen, vuoresta vuoreen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Mutta tapahtuu, että maa tulee autioksi asukkaittensa tähden, heidän tekojensa hedelmien takia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Kaitse kansaasi sauvallasi, perintölaumaasi, joka asuu erillään metsässä keskellä Karmelia. Käykööt laitumella Baasanissa ja Gileadissa kuin ennen ikiaikoina. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, '\"Niin kuin Egyptin maasta lähtösi päivinä annan hänen nähdä ihmeitä.\" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Sen näkevät pakanakansat ja saavat häpeän kaikesta väkevyydestään. He panevat käden suulleen, heidän korvansa menevät lukkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'He nuolevat tomua kuin käärme, kuin maan matelijat. Vavisten he tulevat linnoituksistaan, lähestyvät väristen Herraa, Jumalaamme, ja pelkäävät sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Kuka on Jumala niin kuin sinä, joka annat pahat teot anteeksi ja käyt ohi perintösi jäännöksen rikosten? Ei hän pidä vihaa iäti, sillä hänellä on mielihalu laupeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Hän armahtaa meitä jälleen, polkee maahan pahat tekomme ja kaikki heidän syntinsä sinä heität meren syvyyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Sinä osoitat Jaakobille uskollisuutta, Aabrahamille armoa, kuten olet vannonut isillemme muinaisista päivistä asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Profeettasana Niinivestä. Elkosilaisen Naahumin näyn kirja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Kiivas Jumala ja kostaja on Herra. Herra on kostaja ja vihastuva. Herra kostaa vihollisilleen ja on vihainen vihamiehilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Herra on pitkämielinen ja suuri voimassaan, mutta Herra ei jätä rankaisematta. Hänen tiensä käy tuulispäässä ja myrskyssä, ja pilvi on hänen jalkojensa tomua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Hän nuhtelee merta ja kuivaa sen, ja kaikki virrat hän ehdyttää. Baasan ja Karmel kuihtuvat, ja Libanonin kukoistus lakastuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Vuoret järkkyvät hänen edessään ja kukkulat sulavat. Hänen kasvojensa voimasta kohoaa maa, maanpiiri ja kaikki siinä asuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Kuka kestää hänen vihastumistaan, ja kuka pysyy hänen vihansa palaessa? Hänen vihastuksensa vuotaa kuin tuli, ja kalliot halkeilevat hänen edessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Hyvä on Herra, turva ahdistuksen päivänä, ja hän tuntee ne, jotka häneen luottavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Mutta ylipaisuvalla tulvalla hän tekee lopun sen paikasta ja ahdistaa vihamiehiään pimeydellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Mitä teillä on mielessä Herraa vastaan? Lopun hän tekee: ahdistus ei nouse kahta kertaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Sillä vaikka he olisivat kietoutuneita yhteen kuin orjantappurat ja yhtä märkiä viinistä kuin heidän viininsä, heidät syö tuli kokonaan kuin kuivat oljet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Sinusta on lähtenyt se, jolla on paha mielessä Herraa vastaan, turmion suunnittelija.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Näin sanoo Herra: Olkoot kuinka täysissä voimissa, olkoon heitä miten paljon tahansa, heidät tuhotaan. He ovat mennyttä. Mutta jos olenkin vaivannut sinua, en sinua enää vaivaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Nyt särjen hänen ikeensä päältäsi ja katkaisen kahleesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Mutta sinusta Herra on antanut käskyn: Ei kasva enää nimellesi siementä. Hävitän epäjumalan temppelistäsi veistetyt ja valetut jumalankuvat. Teen sinulle haudan, sillä sinä raukeat tyhjiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Katso, jo ovat vuorilla ilosanoman tuojan jalat, hänen, joka julistaa rauhaa: \"Juhli, Juuda, juhliasi, maksa lupauksesi, sillä enää ei käy kimppuusi turmiontuoja, hänet on hävitetty kokonaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Hajottaja hyökkää sinua vastaan! Vartioi varustuksia, tähystä tietä, vahvista vyötäiset, kokoa voimasi äärimmilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Sillä Herra saattaa entiselleen Jaakobin korkeuden ja Israelin korkeuden, sillä ryöstäjät ovat niitä ryöstäneet ja hävittäneet niiden viiniköynnökset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Hänen sankariensa kilvet ovat punaiset, sotilaat purppurapukuiset, sotavaunut säihkyvät teräksen tulta hänen sotaan varustautumispäivänään, ja sypressikeihäät heiluvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Sotavaunut välkehtivät kaduilla ja ryntäilevät toreilla. Ne ovat kuin soihdut ja kiitävät kuin salamat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Hän muistaa ylhäisensä. Ne kaatuilevat kiiruhtaessaan sen muurille, ja suojakatos on pantu kuntoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Virranpuoleiset portit on aukaistu, ja palatsi menehtyy pelkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Karkotuspäätös on tehty: se viedään vankeuteen, ja sen neitoset huokailevat valittaen kuin kyyhkyset ja lyövät rintaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Niinive on ollut kuin vesilammikko päiviensä alusta asti. Nyt ne pakenevat! – \"Seis! pysähtykää!\" Mutta yksikään ei käänny takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Ryöstäkää hopeaa, ryöstäkää kultaa. Loppumattomat ovat varat, on runsaasti kaikenlaisia kalliita esineitä. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Se on tyhjennetty, riisuttu ja hävitetty! Sydämet raukeavat, polvet tutisevat, kaikki lanteet vapisevat, ja kaikkien kasvot synkkenevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Missä on leijonien asuinsija, nuorten jalopeurojen elinpiiri, jossa leijona ja naarasleijonat pentuineen kulkivat kenenkään pelottelematta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Leijona raateli, mitä sen pennut tarvitsivat, ja surmasi naarasleijonilleen. Se täytti luolansa saaliilla ja olinpaikkansa sillä, minkä oli raadellut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 14, 'Katso, minä käyn kimppuusi, – tämä on Herran Sebaotin sana, – poltan savuksi sen sotavaunut, ja nuoret leijonasi syö miekka. Minä lopetan maan päältä raatelusi, eikä enää kuulla sanansaattajiesi ääntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Voi verivelkojen kaupunkia, joka on täynnä valhetta ja riistoa. Ryöstäminen ei lopu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Kuuluu ruoskien ja vaunujen pyörien ääni. Hevoset kiitävät, vaunut hyppivät,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'ratsut karkaavat pystyyn, miekat välkkyvät, keihäät salamoivat. On paljon kaatuneita, kasapäin vainajia ja loppumattomasti ruumiita, niin että niihin kompastutaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Kaikki tämä porton paljon haureuden tähden, tuon ihanan sulottaren, ovelan velhottaren, joka myi kansakunnat haureudellaan ja sukukunnat velhouksillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Katso, minä käyn kimppuusi, sanoo Herra Sebaot, nostan liepeesi kasvoillesi ja näytän kansakunnille alastomuutesi ja valtakunnille häpeäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Heitän likaa päällesi, häpäisen sinut ja panen sinut julkisesti nähtäväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Niin tapahtuu, että kaikki, jotka näkevät sinut, kaikkoavat sinusta kauas ja sanovat: \"Hävitetty on Niinive! Kuka sitä surkuttelee, mistä etsin sinulle lohduttajia?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Oletko sinä parempi, kuin oli Noo-Ammon, joka istui hallitsijana virtojen äärellä vetten ympäröimänä, jolla oli virta linnoituksena ja meri muurina?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Sen väkevyytenä oli Kuus ja egyptiläiset, joilla ei ollut määrää. Auttajinasi olivat Puut ja libyalaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Sekin meni karkotukseen, vankeuteen. Senkin pienet lapset murskattiin kaikkien katujen kulmissa, sen ylhäisistä heitettiin arpaa, ja kaikki sen suurmiehet pantiin kahleisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Myös sinä olet juopuva ja vaipuva pimeyteen; myös sinä olet etsivä suojaa vihollisilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Kaikki sinun linnoituksesi ovat viikunapuita, joissa on varhaisviikunoita. Jos niitä pudistellaan, ne putoavat syöjän suuhun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Katso, sotaväkesi keskelläsi on naisia. Maasi portit ovat avoinna vihamiehillesi. Tuli kuluttaa salpasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Ammenna itsellesi vettä piirityksen varalta, vahvista linnoituksiasi, astu liejuun, polje savea, käy kiinni tiilenmuottiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Siinä tuli sinut kuluttaa ja miekka sinut tuhoaa. Se syö sinut kuin syöjäsirkat, vaikka lisääntyisit kuin syöjäsirkat, vaikka lisääntyisit heinäsirkkojen tavoin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Sinä olet lisännyt kauppiaasi lukuisammiksi kuin taivaan tähdet. Syöjäsirkat ryöstävät ja lentävät pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Sinulla on ruhtinaita kuin heinäsirkkoja, kirjureita kuin sirkkaparvea, joka asettuu muurinrakoihin kylmänä päivänä. Auringon noustua ne pakenevat, eikä kukaan tiedä paikkaa, missä ne ovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Paimenesi, Assurin kuningas, ovat nukkuneet, ylhäisesi jääneet liikkumattomiksi. Sinun väkesi on hajaantunut vuorille, eikä ole kokoajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Auttamaton on tuhosi ja parantumaton haavasi. Kaikki, jotka kuulevat sanoman sinusta, taputtavat sinulle käsiään. Sillä ketäpä pahuutesi ei olisi jatkuvasti kohdannut?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Profeettasana, jonka profeetta Habakuk näki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Kuinka kauan, Herra, huudan apua, etkä kuule, valitan sinulle väkivallan tähden etkä auta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Minkä tähden annat minun nähdä vääryyttä ja itse katselet turmiota? Edessäni on hävitystä ja väkivaltaa. On syntynyt riita, ja on noussut tora.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Sen tähden laki on heikko, eikä oikeus tule koskaan voimaan. Sillä jumalaton saartaa vanhurskaan. Siksi oikeus vääristetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Katsokaa kansojen joukkoon, katselkaa ja kauhistukaa, sillä minä teen teidän päivinänne teon, jota ette uskoisi, jos siitä kerrottaisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Sillä katso, nostan kaldealaiset, ankaran ja rajun kansan, joka kulkee maata lavealti ja ottaa omakseen asuinsijat, jotka eivät ole sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Se on hirvittävä ja pelottava, siitä itsestään tulee sille oikeus ja arvovalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Sen hevoset ovat nopeammat kuin pantterit. Ne juoksevat joutuisammin kuin sudet illoin. Sen ratsumiehet kiitävät. Kaukaa tulevat sen ratsumiehet. Ne lentävät kuin kotka, joka syöksyy saaliinsa kimppuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'He tulevat kaikki väkivallan tekoon. Heidän kasvojensa suunta on suoraan eteenpäin, ja he kokoavat vankeja kuin hiekkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Pilkkanaan se pitää kuninkaita ja naurunaan ruhtinaita. Se nauraa kaikille linnoituksille, kasaa valliksi maata ja valloittaa ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Sitten se tuulena kiitää ja hyökkää, mutta joutuu syynalaiseksi, tuo, jolla oma voimansa on jumalana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Etkö sinä ole ikiajoista asti Herra, pyhä Jumalani? Me emme kuole! Sinä, Herra, olet pannut sen tuomioksi. Sinä, kallio, olet asettanut sen kuritukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Sinun silmäsi ovat puhtaat, niin ettet voi katsoa pahaa etkä saata katsella kurjuutta. Minkä tähden sinä katselet uskottomia, olet vaiti, kun jumalaton nielee hurskaampansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'teet ihmiset samanlaisiksi kuin meren kalat, kuin matelijat, joilla ei ole hallitsijaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Se nostaa heidät kaikki ylös koukulla, vetää heitä verkollaan ja kokoaa heidät pyydykseensä. Sen tähden se iloitsee ja riemuitsee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Sen tähden se uhraa pyydykselleen ja polttaa uhreja verkolleen, sillä niitten turvin sen osa on rasvainen ja sen ruoka lihava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Saako se sen nojalla tyhjentää pyydyksensä ja surmata jatkuvasti kansoja säälimättä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Minä seisoin vartiopaikallani, asetuin varustukseen ja tähystin nähdäkseni, mitä hän minulle puhuu ja mitä hän valitukseeni vastaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Niin Herra vastasi minulle ja sanoi: \"Kirjoita näky ja piirrä selvästi tauluihin, niin että sen voi juostessa lukea.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Sillä näky odottaa vielä aikaansa, mutta se rientää määränsä päähän, eikä se petä. Jos se viipyy, odota sitä, sillä varmasti se toteutuu eikä myöhästy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Katso, sen kansan sielu on kopea eikä suora; mutta vanhurskas on elävä uskonsa kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Vielä: viini pettää ylpeän miehen, niin ettei hän pysy. Hän levittää kitansa kuin helvetti ja on kuin kuolema, joka ei saa kylläänsä, vaan hän kokoaa itseensä kaikki kansakunnat ja haalii itseensä kaikki kansat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Mutta eivätkö ne kaikki sepitä hänestä sananpartta, ivarunoa ja arvoitusta? He sanovat: \"Voi sitä, joka hankkii paljon omaisuutta, mikä ei ole hänen ja kasaa itselleen pantteja! Kuinka pitkäksi aikaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Eivätkö vaivaajasi nouse äkkiä, eivätkö ravistelijasi herää? Niin sinä joudut niiden ryöstettäväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Sillä niin kuin olet riistänyt monia kansoja, niin riistävät sinua kaikki jäljellejääneet kansat ihmisveren tähden ja väkivallan tähden, jota on tehty maalle, kaupungille ja kaikille sen asukkaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Voi sitä, joka kiskoo väärää voittoa huoneensa hyväksi laittaakseen pesänsä korkealle ja pelastuakseen onnettomuuden kourista!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Sinä olet neuvoillasi tuottanut häpeää huoneellesi tuhoamalla paljon kansoja, ja olet tehnyt syntiä omaa sieluasi vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Sillä kivi seinästä on huutava ja puinen palkki on vastaava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Voi sitä, joka rakentaa kaupungin verivelkojen varaan ja perustaa linnoituksen vääryydelle!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Katso, eikö Herralta Sebaotilta tule se, että kansat näkevät vaivaa tulen hyväksi ja kansakunnat väsyttävät itsensä tyhjän takia?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Sillä maa on oleva täynnä Herran kunnian tuntemusta, niin kuin vedet peittävät meren.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Voi sitä, joka juottaa lähimmäistään, joka sekoittaa juoman vihallasi ja juovuttaa hänet nähdäkseen hänen alastomuutensa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Ravitset itsesi häpeällä etkä kunnialla: niinpä juo sinäkin ja paljasta ympärileikkaamattomuutesi. Sinulle on kiertyvä Herran oikean käden malja ja häväistys kunnian sijaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Sillä sinut on peittävä Libanonille tekemäsi väkivalta ja eläimiä kohdannut hävitys säikäyttää sinut, ihmisveren tähden ja väkivallan tähden, jota on tehty maalle, kaupungille ja sen kaikille asukkaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Mitä hyötyä on veistetystä kuvasta, että sen valmistaja veistää sen, ja valetusta kuvasta ja valheen opettajasta, että sen valmistaja siihen luottaa ja tekee mykkiä epäjumalia?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Voi sitä, joka sanoo puupalalle: \'Herää!\' ja mykälle kivelle: \'Nouse!\' Sekö voisi opettaa? Katso, se on silattu kullalla ja hopealla, mutta henkeä siinä ei ole lainkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Mutta Herra on pyhässä temppelissään. Hänen edessään vaietkoon kaikki maa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Profeetta Habakukin rukous. Valitusvirren tapaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Herra, minä olen kuullut sinulta sanoman, ja olen pelästynyt. Herra, herätä eloon tekosi määrävuosien keskellä, tee se tiettäväksi määrävuosien keskellä. Muista vihassasi laupeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Jumala tulee Teemanista, Pyhä Paaranin vuorelta. Sela. Hänen valtasuuruutensa peittää taivaat, ja hänen ylistyksensä täyttää maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Hänen hohteensa on kuin aurinko, hänen kädestään välkehtivät säteet. Se verhoaa hänen voimansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Hänen edellään kulkee rutto, ja liekit tulevat hänen perässään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Hän seisahtui ja mittasi maan, hän katsoi ja sai kansat vapisemaan. Ikivuoret särkyivät, ikuiset kukkulat vaipuivat, hänen polkunsa ovat iankaikkiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Vaivan alaisina näin Kuusanin telttamajat, Midianin maan telttavaatteet vapisivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Virtoihinko Herra on vihastunut? Kohtaako vihasi virtoja ja kiivastuksesi merta, koska ajat hevosillasi, pelastuksesi vaunuilla?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Paljas, paljastettu on jousesi: valat, ruoskat, sana. Sela. Virroilla halkaiset maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Vuoret näkevät sinut ja järkkyvät, rankkasade syöksee vettä, syvyys antaa äänensä ja kohottaa kätensä korkealle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Aurinko ja kuu pysähtyivät paikoilleen kiitävien nuoltesi valossa ja välkehtivien keihäiden valossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Kiivastuksessa sinä astut maata ja tallaat kansoja vihassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Olet lähtenyt auttamaan kansaasi, auttamaan Voideltuasi. Murskaat pään jumalattoman huoneesta ja paljastat perustukset kaulan tasalle. Sela.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Sinä lävistät heidän keihäillään pään heidän johtajiltaan, jotka hyökkäävät hajottamaan minua – se on heidän ilonsa – aivan kuin pääsisivät syömään kurjaa salassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Sinä tallaat hevosillasi merta, paljojen vetten kuohua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Kuulin tämän, ja ruumiini vapisi, huuleni värisivät huudosta, kipu tunkeutui luihini ja vapisin, kun minun täytyy hiljaa odottaa ahdistuksen päivää, jolloin kansan kimppuun käy hyökkääjä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Sillä ei viikunapuu kukoista, eikä viiniköynnöksissä ole rypäleitä, öljypuu ei tuota satoa eivätkä pellot tuota syötävää. Lampaat ovat kadonneet tarhasta, eikä karjaa ole vajoissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Mutta minä riemuitsen Herrassa ja iloitsen autuuteni Jumalassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Herra, Herra on voimani. Hän tekee jalkani nopeiksi kuin peurat ja antaa minun vaeltaa kukkuloillani. Veisuunjohtajalle. Kielisoittimillani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Herran sana, joka tuli Sefanjalle, Kuusin pojalle, joka oli Gedaljan poika, joka Amarjan poika, joka Hiskian poika, Juudan kuninkaan Joosian, Aamonin pojan, päivinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Totisesti otan pois maan pinnalta kaiken. Tämä on Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Otan pois ihmiset ja eläimet, otan pois taivaan linnut ja meren kalat, viettelykset ja jumalattomat. Minä hävitän ihmiset maan pinnalta. Tämä on Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Ojennan käteni Juudaa vastaan ja kaikkia Jerusalemin asukkaita vastaan, ja hävitän tästä paikasta Baalin jätteet, epäjumalien pappien nimet sekä myös papit,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'ne, jotka katoilla kumartaen rukoilevat taivaan joukkoa, sekä ne, jotka kumartaen rukoilevat Herraa ja vannovat hänen kauttaan, mutta myös vannovat Melekinsä kautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'sekä ne, jotka ovat luopuneet seuraamasta Herraa, eivät kysy Herraa eivätkä etsi häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Vaiti Herran, Herran edessä! Sillä Herran päivä on lähellä; sillä Herra on valmistanut teurasuhrin ja pyhittänyt kutsuttunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'Mutta Herran teurasuhrin päivänä rankaisen päämiehiä ja kuninkaan poikia ja kaikkia muukalaisten pukuun puettuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Rankaisen sinä päivänä kaikkia kynnyksen yli hyppiviä, jotka täyttävät Herransa huoneen väkivallalla ja petoksella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'Tapahtuu sinä päivänä, sanoo Herra, että kuuluu huuto Kalaportilta ja valitus toiselta portilta ja suuri hävitys kukkuloilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Valittakaa, te Maktesin asukkaat, sillä tuhottu on kaikki kauppaa käyvä väki ja hävitetty kaikki hopean punnitsijat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Tapahtuu siihen aikaan, että tutkin lampuilla Jerusalemin ja rankaisen niitä miehiä, jotka istuvat viinisakkansa päällä ja sanovat sydämessään: \" Herra ei tee hyvää eikä pahaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Tapahtuu myös, että heidän rikkautensa joutuu ryöstettäväksi, ja heidän talonsa jäävät autioiksi. He ovat rakentaneet taloja, mutta eivät tule niissä asumaan. He ovat istuttaneet viinitarhoja, mutta eivät tule juomaan niiden viiniä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Lähellä on Herran suuri päivä. Se on lähellä ja tulee hyvin nopeasti. Kuule, Herran päivä! Silloin sankari huutaa katkerasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Vihan päivä on se päivä, tuskan ja ahdistuksen päivä, tuhon ja hävityksen päivä, pimeyden ja synkeyden päivä, pilven ja mustien pilvien päivä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'sotatorven ja sotahuudon päivä luoksepääsemättömiä kaupunkeja ja korkeita muurinkulmia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Minä saatan ihmiset ahdistukseen, niin että he kulkevat kuin sokeat, sillä he ovat tehneet syntiä Herraa vastaan. Heidän verensä vuodatetaan kuin tomu, ja heidän elinnesteensä kuin uloste.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Heidän hopeansa ja kultansa eivät voi pelastaa heitä Herran vihan päivänä. Hänen kiivautensa tulessa kuluu koko maa. Sillä lopun, äkkilopun, hän tekee kaikista maan asukkaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Kokoontukaa, tulkaa yhteen, te häpeämätön kansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'ennen kuin määräys on toteutettu – päivä kiitää pois kuin akana – ennen kuin teidän päällenne tulee Herran vihan hehku, ennen kuin teidän päällenne tulee Herran vihan päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Etsikää Herraa, kaikki maan nöyrät, te, jotka noudatatte hänen oikeuttaan. Etsikää vanhurskautta, etsikää nöyryyttä. Ehkä te saatte suojan Herran vihan päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Sillä Gassa on oleva hylätty ja Askelon autio, Asdod ajetaan pois keskipäivällä, ja Ekron hävitetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Voi meren rannikon asukkaita, kreettien kansaa! Herran sana on sinua vastaan, Kanaan, filistealaisten maa. Minä hävitän sinut, niin ettei sinussa ole asukkaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Meren rannikko on oleva laitumina, joilla on paimenten majoja ja lammastarhoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Rannikko on oleva Juudan heimon jäännöksen hallussa. Siellä he laiduntavat. Askelonin taloihin he asettuvat makaamaan illoin. Sillä Herra, heidän Jumalansa, on pitävä heistä huolen ja kääntävä heidän kohtalonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Olen kuullut Mooabin ivat ja ammonilaisten pilkat, joilla he ovat häpäisseet kansaani ja ylvästelleet sen aluetta vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Sen tähden, niin totta kuin minä elän, – tämä on Herran Sebaotin, Israelin Jumalan, sana – Mooab on tuleva Sodoman kaltaiseksi ja ammonilaiset Gomorran kaltaisiksi, nokkosmaaksi, suolakuopaksi, autioksi iankaikkisesti. Kansani jäännös ryöstää heitä, ja kansakuntani jäljelle jääneet ottavat heidät perintöosakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Tämä tulee heille heidän ylpeytensä tähden, sillä he ovat herjanneet ja ylvästelleet Herran Sebaotin kansaa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Pelottava on Herra heille oleva, sillä hän tekee voimattomiksi kaikki maan jumalat; ja kaikki pakanoiden saaret kukin paikallaan tulevat häntä kumartaen rukoilemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Teidätkin, kuusilaiset, on miekkani kaatava!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Hän on ojentava kätensä pohjoista kohden, hukuttava Assurin ja tekevä Niiniven autioksi, kuivaksi kuin erämaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Sen keskellä makaa laumoja, kaikkia kansojen petoeläimiä. Pöllö ja siili yöpyvät sen patsaiden seassa. Kuule, kuinka ne laulavat ikkuna-aukossa! Kynnyksellä on tyhjyys. Setrilaudoituksen hän on paljastanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Tämä oli se riemuitseva kaupunki, joka asui turvallisena ja sanoi sydämessään: \"Minä, eikä ketään muuta!\" Kuinka autioksi se on tullut, villieläinten makuusijaksi! Jokainen, joka käy siitä ohi, viheltää ja heiluttaa kättään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Voi uppiniskaista, saastaista ja väkivaltaista kaupunkia!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Se ei ole totellut ääntä, ei huolinut ojennuksesta, ei luottanut Herraan eikä lähestynyt Jumalaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Ruhtinaat sen keskellä ovat ärjyviä leijonia. Sen tuomarit ovat kuin sudet illalla, jotka eivät säästä aamua varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Sen profeetat ovat huikentelijoita, uskottomia miehiä. Sen papit saastuttavat pyhän ja tekevät väkivaltaa laille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Herra on vanhurskas sen keskellä, hän ei tee vääryyttä. Joka aamu hän tuo valoon oikeutensa, se ei jää tulematta. Mutta väärintekijä ei tunne häpeää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Olen hävittänyt pakanakansat, niiden muurinkulmat ovat autioina. Olen tehnyt niiden kadut raunioiksi eikä niillä ole kulkijoita. Niiden kaupungit ovat hävitetyt, niin ettei niissä ole ihmisiä eikä niissä asuta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Olen sanonut: Pelkää ainoastaan minua ja ota varteen ojennus, niin tytär Siionin asumusta ei hävitetä eikä mitään siitä, mitä olen sille säätänyt. Kuitenkin he nousivat varhain turmellakseen kaikki tekonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Sen tähden odottakaa minua – tämä on Herran sana – odottakaa sitä päivää, jona nousen saaliille. Sillä tuomiopäätökseni on, että kokoan pakanakansat ja saatan koolle valtakunnat vuodattaakseni heidän päälleen ankaruuteni ja vihani koko hehkun, sillä kiivauteni tuli kuluttaa koko maan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Silloin annan kansoille puhdistetut huulet, niin että ne kaikki huutavat avuksi Herran nimeä ja palvelevat häntä yhdessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Kuusin virtojen tuolta puolen rukoilijani – hajalla oleva tyttäreni kantaa minulle lahjoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'Sinä päivänä sinä et enää häpeä mitään niistä teoistasi, joilla olet rikkonut minua vastaan, sillä silloin minä poistan keskuudestasi ylpeilijäsi, ne, jotka korottavat itsensä. Sitten et enää ylpeile pyhän vuoreni tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Mutta minä jätän jäljelle keskuuteesi kurjan ja köyhän kansan, ne, jotka panevat turvansa Herran nimeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Israelin jäännökset eivät tee vääryyttä eivätkä puhu valhetta, eikä heidän suussaan tavata valheellista kieltä. Sillä ne ovat laitumella ja makaavat kenenkään pelottelematta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Iloitse, tytär Siion, puhkea huutoon, Israel; ihastu ja riemuitse kaikesta sydämestäsi, tytär Jerusalem.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Herra on poistanut tuomiosi, kääntänyt pois vihollisesi. Israelin kuningas, Herra, on keskelläsi. Et tule enää näkemään onnettomuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'Sinä päivänä sanotaan Jerusalemille: \"Älä pelkää, Siion, älkööt kätesi väsykö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Herra, Jumalasi, asuu sinussa; hän on sankari, joka auttaa. Hän iloitsee sinusta ilolla, hän on ääneti, sillä hän rakastaa sinua, hän riemuitsee sinusta riemulla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Minä kokoan ne, jotka ovat murheellisia juhlakokousten tähden. Hehän ovat olleet erossa sinusta. Häväistys on taakkana heidän päällään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Katso, siihen aikaan teen tekoni kaikille nöyryyttäjillesi. Pelastan ontuvat ja kokoan karkotetut ja teen heidät ylistetyiksi ja kiitetyiksi jokaisessa maassa, jossa he olivat häpeän alaisina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'Siihen aikaan minä tuon teidät takaisin – siihen aikaan, jona teidät kokoan. Sillä teen teidät ylistetyiksi ja kiitetyiksi kaikissa maan kansoissa, kun käännän kohtalonne silmienne nähden, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Kuningas Daarejaveksen toisena vuotena, kuudennessa kuussa, kuukauden ensimmäisenä päivänä, tuli tämä Herran sana profeetta Haggain kautta Juudan käskynhaltijalle Serubbaabelille, Sealtielin pojalle, ja ylimmäiselle papille Joosualle, Joosadakin pojalle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, '\"Näin sanoo Herra Sebaot: Tämä kansa sanoo: Aika ei ole tullut rakentaa Herran huonetta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Mutta profeetta Haggain kautta tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, '\"Onko teidän aika asua paneloiduissa huoneissanne, kun tämä huone on autiona?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Mutta nyt Herra Sebaot sanoo näin: Ottakaa vaari teistänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Kylvätte paljon, mutta saatte vähän. Syötte, mutta ette tule kylläisiksi. Juotte, mutta jano ei sammu. Pukeudutte, mutta ei tule lämmin. Työmies panee palkkansa reikäiseen kukkaroon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Näin sanoo Herra Sebaot: Ottakaa vaari teistänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Nouskaa vuorelle, tuokaa puita ja rakentakaa temppeli, niin miellyn siihen ja näytän kunniani, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Odotatte saavanne paljon, mutta se jää vähiin. Tuotte kotiin, mutta minä puhallan sen pois. Minkä tähden? – Tämä on Herran Sebaotin sana. – Huoneeni tähden, koska se on autiona ja te juoksette kukin oman huoneenne hyväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Sen tähden taivas pidättää teiltä kasteen ja maa pidättää satonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Olen kutsunut kuivuuden maahan ja vuorille, viljalle, viinille ja öljylle, ja maan tuotteille, ihmisille, eläimille ja kaikille käden töille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Serubbaabel, Sealtielin poika, ja ylimmäinen pappi Joosua, Joosadakin poika, ja kansan koko jäännös kuuli Herran, Jumalansa ääntä ja profeetta Haggain sanoja, jota varten Herra, heidän Jumalansa, oli hänet lähettänyt, ja kansa pelkäsi Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Haggai, Herran sanansaattaja, tuodessaan Herran sanan sanoi kansalle näin: \"Minä olen kanssanne\" – tämä on Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Herra herätti Juudan käskynhaltijan Serubbaabelin, Sealtielin pojan, hengen ja ylimmäisen papin Joosuan, Joosadakin pojan, hengen ja kansan koko jäännöksen hengen, ja he tulivat ja ryhtyivät rakentamaan Herran Sebaotin, heidän Jumalansa, temppeliä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'kahdentenakymmenentenä neljäntenä päivänä kuudennessa kuussa, kuningas Daarejaveksen toisena vuotena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Seitsemännessä kuussa, kuukauden kahdentenakymmenentenä ensimmäisenä päivänä tuli profeetta Haggain kautta tämä Herran sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, '\"Sano Juudan käskynhaltijalle Serubbaabelille, Sealtielin pojalle, ja ylimmäiselle papille Joosualle, Joosadakin pojalle, ja kansan jäännökselle näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Kuka joukostanne on jäänyt jäljelle, joka on nähnyt tämän temppelin sen entisessä kunniassa? Miltä se nyt teistä näyttää? Eikö se ole tyhjänveroinen silmissänne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Mutta ole nyt luja, Serubbaabel – tämä on Herran sana – ja ole luja, Joosua, Joosadakin poika, ylimmäinen pappi, ja ole luja, maan koko kansa – tämä on Herran sana – ja tehkää työtä, sillä minä olen kanssanne – tämä on Herran Sebaotin sana,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'sen liiton sana, jonka tein kanssanne, kun lähditte Egyptistä, ja Henkeni pysyy keskellänne. Älkää pelätkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Sillä näin sanoo Herra Sebaot: Vielä vähän aikaa, ja minä liikutan taivaat ja maan, meren ja kuivan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Liikutan kaikki pakanakansat, ja kaikkien pakanakansojen rakastetut tulevat, ja täytän tämän temppelin kunnialla, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Minun on hopea, ja minun on kulta. Tämä on Herran Sebaotin sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Tämän temppelin myöhempi kunnia on oleva suurempi kuin ensimmäisen, sanoo Herra Sebaot. Tässä paikassa annan vallita rauhan. Tämä on Herran Sebaotin sana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Yhdeksännen kuun kahdentenakymmenentenä neljäntenä päivänä, Daarejaveksen toisena vuotena, profeetta Haggain kautta tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, '\"Näin sanoo Herra Sebaot: Kysy papeilta laista ja sano:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Katso, mies kantaa pyhää lihaa vaatteensa liepeessä ja koskettaa liepeellään leipää tai keittoa, viiniä, öljyä tai muuta ruokaa, mitä hyvänsä. Tuleeko se siitä pyhäksi?\" Niin papit vastasivat ja sanoivat: \"Ei.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Sitten Haggai sanoi: \"Jos joku, joka on kuolleesta saastunut, koskettaa jotakin näistä, tuleeko se saastaiseksi?\" Niin papit vastasivat: \"Tulee saastaiseksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Haggai vastasi ja sanoi: \"Sellaista on tämä väki, sellaista tämä kansa edessäni. – Tämä on Herran sana. – Sellaisia ovat kaikki heidän kättensä työt. Se, mitä he siellä tuovat uhriksi, on saastaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Mutta nyt tarkatkaa elämäänne tästä päivästä lähtien ja sitä ennen, kun ei vielä ollut pantu kiveä kiven päälle Herran temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Sitä ennen mentiin kahdenkymmenen mitan viljakasalle, mutta oli kymmenen, mentiin viinikuurnalle ammentamaan viittäkymmentä mittaa, mutta oli kaksikymmentä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Löin teitä, kaikkia teidän kättenne töitä, nokitähkällä ja viljanruosteella ja rakeilla, mutta te ette kääntyneet luokseni, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Tarkatkaa elämäänne tästä päivästä lähtien ja sitä ennen, yhdeksännen kuun kahdennestakymmenennestä neljännestä päivästä, Herran temppelin perustamispäivästä, lähtien. Tarkatkaa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Onko aitassa enää siementä? Myöskään viiniköynnös, viikunapuu, granaattiomenapuu ja öljypuu eivät ole kantaneet hedelmää. Tästä päivästä lähtien annan siunauksen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Sitten Herran sana tuli toistamiseen Haggaille kuukauden kahdentenakymmenentenä neljäntenä päivänä ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, '\"Sano Juudan käskynhaltijalle Serubbaabelille: Minä liikutan taivaat ja maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'Kukistan myös kuningaskuntien valtaistuimet, hävitän pakanoiden valtakuntien väkevyyden ja kukistan vaunut ajajineen. Hevoset ja niiden ratsastajat kaatuvat, kukin toinen toisensa miekkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'Sinä päivänä – tämä on Herran Sebaotin sana – otan sinut, palvelijani Serubbaabel, Sealtielin poika, sanoo Herra, ja panen sinut ikään kuin sinettisormukseksi. Sillä sinut olen valinnut. Tämä on Herran Sebaotin sana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Kahdeksannessa kuussa Daarejaveksen toisena vuotena tuli profeetta Sakarjalle, Berekjan pojalle, joka oli Iddon poika, tämä Herran sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, '\" Herra on toden totta vihastunut teidän isiinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Sano heille: Näin sanoo Herra Sebaot: Kääntykää luokseni, sanoo Herra Sebaot, niin minäkin käännyn teidän puoleenne, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Älkää olko isienne kaltaisia, joille aikaisemmat profeetat ovat saarnanneet sanoen: Näin sanoo Herra Sebaot: Kääntykää pois pahoilta teiltänne ja pahoista teoistanne; mutta he eivät kuulleet eivätkä kuunnelleet minua. – Tämä on Herran sana. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Teidän isänne – missä he ovat? Entä profeetat – ovatko he eläneet iäti?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Mutta minun sanani ja käskyni, jotka olen säätänyt palvelijoilleni profeetoille – eivätkö ne kohdanneet isiänne? He kääntyivät ja sanoivat: \'Niin kuin Herra Sebaot aikoi tehdä meille vaelluksemme ja tekojemme mukaan, niin hän on meille tehnyt.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Kahdentenakymmenentenä neljäntenä päivänä yhdennessätoista kuussa, joka on sebat-kuu, Daarejaveksen toisena vuotena, tuli profeetta Sakarjalle, Berekjan pojalle, joka oli Iddon poika, tämä Herran sana, ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Näin yöllä, katso, mies ratsasti punaruskealla hevosella ja seisahtui myrttien keskelle laaksoon, ja hänen perässään oli punaruskeita, punaisia ja valkoisia hevosia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Kysyin: \"Mitä nämä ovat, Herra?\" Enkeli, joka puhutteli minua, vastasi minulle: \"Minä näytän sinulle, mitä ne ovat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Mies, joka seisoi myrttien keskellä, lausui ja sanoi: \"Nämä ovat ne, jotka Herra on lähettänyt maata kuljeskelemaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Niin ne vastasivat Herran enkelille, joka seisoi myrttien keskellä, ja sanoivat: \"Me olemme maata kuljeskelleet, ja katso, koko maa on alallaan ja rauhassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Sitten Herran enkeli lausui ja sanoi: \" Herra Sebaot, kuinka kauan sinä viivyt etkä armahda Jerusalemia ja Juudan kaupunkeja, joille olet ollut vihainen nämä seitsemänkymmentä vuotta?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Herra vastasi enkelille, joka puhutteli minua, ja lausui hyviä, lohdullisia sanoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Enkeli, joka puhutteli minua, sanoi minulle: \"Saarnaa ja sano: Näin sanoo Herra Sebaot: Kiivailen Jerusalemin ja Siionin puolesta suurella kiivaudella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'Suurella vihalla minä olen vihastunut suruttomiin pakanoihin, jotka, kun minä vähäksi aikaa vihastuin, auttoivat onnettomuutta tapahtumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Sen tähden sanoo Herra näin: Tulen kääntymään Jerusalemin puoleen armahtavaisuudessa. Temppeliäni rakennetaan siellä – tämä on Herran Sebaotin sana – ja mittanuoraa jännitetään Jerusalemin yllä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Saarnaa vielä ja sano: Näin sanoo Herra Sebaot: Vielä kaupunkini ovat hyvyydestä ylitsevuotavia, ja vielä Herra lohduttaa Siionin ja valitsee taas Jerusalemin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Nostin silmäni ja katsoin. Katso, oli neljä sarvea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Sanoin enkelille, joka puhutteli minua: \"Mitä nämä ovat?\" Hän sanoi minulle: \"Nämä ovat ne sarvet, jotka ovat hajottaneet Juudan ja Israelin ja Jerusalemin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Herra näytti minulle neljä seppää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'Kysyin: \"Mitä nämä ovat tulleet tekemään?\" Niin hän vastasi ja sanoi: \"Nuo sarvet ovat ne, jotka ovat hajottaneet Juudan, niin ettei yksikään mies voi nostaa päätään. Mutta nämä ovat tulleet saattamaan ne pelkoon ja heittämään maahan niiden pakanakansojen sarvet, jotka ovat nostaneet sarven Juudan maata vastaan hajottaakseen sen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Nostin silmäni ja katsoin. Katso, oli mies ja hänen kädessään mittanuora.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Sanoin hänelle: \"Mihin sinä olet menossa?\" Hän vastasi minulle: \"Mittaamaan Jerusalemia nähdäkseni, kuinka leveä ja kuinka pitkä se on oleva.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Katso, sitten enkeli, joka puhutteli minua, lähti liikkeelle, ja toinen enkeli lähti häntä vastaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'ja sanoi tälle: \"Juokse, puhu tälle nuorukaiselle ja sano: Jerusalem on oleva avoin asua, sillä niin paljon siinä on ihmisiä ja eläimiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Mutta minä olen oleva – tämä on Herran sana – tulimuuri sen ympärillä ja kunnia sen keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Voi, voi, paetkaa pohjoisesta maasta – tämä on Herran sana! Sillä olen hajottanut teidät neljään taivaan tuuleen. Tämä on Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Voi, Siion, pelastaudu, sinä, joka asut tytär Baabelissa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Sillä näin sanoo Herra Sebaot: Kunniansa tähden hän on lähettänyt minut pakanakansojen luo, jotka ovat teitä saalistaneet. Sillä joka teihin koskee, se koskee hänen silmäteräänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Sillä katso, heilutan kättäni heitä vastaan, ja he joutuvat orjiensa saaliiksi. Tulette tietämään, että Herra Sebaot on lähettänyt minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 14, 'Riemuitse ja iloitse, tytär Siion! Sillä tulen ja asun keskelläsi, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 15, 'Sinä päivänä liittyy paljon pakanoita Herraan, ja he tulevat hänen kansakseen, ja asun keskelläsi, ja tulet tietämään, että Herra Sebaot on lähettänyt minut luoksesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 16, 'Herra ottaa Juudan perintöosakseen pyhässä maassa ja valitsee vielä Jerusalemin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 17, 'Vaiti Herran edessä, kaikki liha! Sillä hän on astunut esiin pyhästä asuinsijastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Hän näytti minulle ylimmäisen papin Joosuan seisomassa Herran enkelin edessä ja saatanan seisomassa hänen oikealla puolellaan häntä syyttämässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Niin Herra sanoi saatanalle: \" Herra nuhdelkoon sinua, saatana. Nuhdelkoon sinua Herra, joka on valinnut Jerusalemin. Eikö tämä ole kekäle, joka on tulesta temmattu');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Joosua oli puettu saastaisiin vaatteisiin, ja hän seisoi enkelin edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Tämä lausui ja sanoi näin niille, jotka seisoivat hänen edessään: \"Riisukaa häneltä pois saastaiset vaatteet.\" Hän sanoi hänelle: \"Katso, olen ottanut sinulta pois pahat tekosi, ja puetan sinut juhlavaatteisiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Sanoin: \"Pankoot puhtaan turbaanin hänen päähänsä.\" He panivat puhtaan turbaanin hänen päähänsä ja pukivat hänet vaatteisiin – ja Herran enkeli seisoi siinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Sitten Herran enkeli todisti Joosualle sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, '\"Näin sanoo Herra Sebaot: Jos vaellat teitäni ja hoidat säätämäni tehtävät, saat myös tuomita huonettani ja vartioida esikartanoitani, ja annan sinulle pääsyn tässä seisovien joukkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Kuule, Joosua, ylipappi, sinä ja ystäväsi, jotka edessäsi asuvat. Sillä he ovat ihmeellisiä miehiä, koska – katso – annan tulla palvelijani, Vesan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Sillä katso: kivi, jonka olen asettanut Joosuan eteen – siihen yhteen kiveen päin on seitsemän silmää! Katso, kaiverran kaiverrukset siihen – tämä on Herran Sebaotin sana – ja otan pois tämän maan pahat teot yhtenä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'Sinä päivänä – tämä on Herran Sebaotin sana – te kutsutte kukin ystävänne viinipuun ja viikunapuun alle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Herran enkeli, joka oli puhutellut minua, palasi ja herätti minut, niin kuin joku herätetään unestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'Hän sanoi minulle: \"Mitä sinä näet?\" Vastasin: \"Näen, katso: lampunjalka, kokonaan kultaa, ja sen yläpuolella öljyastia, ja lampunjalassa seitsemän lamppua, ja seitsemän öljyputkea lamppuihin, jotka ovat siinä ylinnä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'Näen myös kaksi öljypuuta sen vieressä, toinen öljyastian oikealla ja toinen vasemmalla puolella.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Lausuin ja sanoin enkelille, joka puhutteli minua näin: \"Mitä nämä ovat, herra?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Enkeli, joka puhutteli minua, vastasi ja sanoi minulle: \"Etkö tiedä, mitä ne ovat?\" Sanoin: \"En, herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Niin hän vastasi ja sanoi minulle näin: \"Tämä on Herran sana Serubbaabelille, näin kuuluva: Ei sotaväellä eikä voimalla, vaan minun Hengelläni, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Mikä olet sinä, suuri vuori? Serubbaabelin edessä sinä olet lakeus. Hän on paneva paikoilleen ylimmän kiven huutojen kaikuessa: \'Suosio, suosio sille!\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Sitten minulle tuli tämä Herran sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, '\"Serubbaabelin kädet ovat tämän temppelin perustaneet, ja hänen kätensä saattavat sen valmiiksi. Niin sinä tulet tietämään, että Herra Sebaot on lähettänyt minut teidän luoksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Sillä kuka pitää halpana pienten alkujen päivän, kun nuo seitsemän Herran silmää, jotka tarkastelevat koko maata, iloitsevat nähdessään luotilangan Serubbaabelin kädessä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Lausuin ja sanoin hänelle: \"Mitä ovat nämä kaksi öljypuuta lampunjalan oikealla ja vasemmalla puolella?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Lausuin ja sanoin hänelle toistamiseen: \"Mitä ovat nuo kaksi öljypuun oksaa kahden kultaisen putken kohdalla, jotka vuodattavat sisältään kultaa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Hän sanoi minulle näin: \"Etkö tiedä, mitä ne ovat?\" Vastasin: \"En, herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Hän sanoi: \"Nämä ovat ne molemmat öljyllä voidellut, jotka seisovat kaiken maan Herran edessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Nostin jälleen silmäni, ja katso, oli lentävä kirjakäärö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'Hän sanoi minulle: \"Mitä sinä näet?\" Vastasin: \"Minä näen lentävän kirjakäärön, kaksikymmentä kyynärää pitkän ja kymmenen kyynärää leveän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Hän sanoi minulle: \"Tämä on kirous, joka lähtee yli koko maan. Sillä tämän kirouksen mukaisesti siitä puhdistetaan pois jokainen varas, ja jokainen vannoskelija puhdistetaan siitä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Lasken sen irti – tämä on Herran Sebaotin sana – ja se menee varkaan kotiin ja sen kotiin, joka vannoo väärin nimeeni. Se jää sisälle hänen kotiinsa ja kalvaa sen loppuun asti, sekä sen puut että sen kivet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Enkeli, joka oli puhutellut minua, lähti liikkeelle ja sanoi minulle: \"Nosta silmäsi ja katso: mikä tuo on, joka lähtee liikkeelle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Kysyin: \"Mikä se on?\" Niin hän vastasi: \"Tämä on eefa-mitta, joka lähtee liikkeelle.\" Hän sanoi: \"Tämän näköisiä ne ovat koko maan päällä\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Niin katso, lyijykansi kohosi, ja eräs nainen istui eefa-mitan sisällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Enkeli sanoi: \"Tämä on jumalattomuus.\" Hän heitti hänet sisälle eefa-mittaan ja paiskasi lyijypainon sen suulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Kun nostin silmäni, näin, katso, kaksi naista lähti liikkeelle, ja heillä oli tuulta siivissään, ja niiden siivet olivat kuin haikaran siivet. Ja he kantoivat eefa-mittaa taivaan ja maan välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Sanoin enkelille, joka oli puhutellut minua: \"Mihin he kuljettavat eefa-mittaa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Hän vastasi minulle: \"He menevät rakentamaan sille taloa Sinearin maahan. Kun se on valmis, lasketaan se sinne paikalleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Nostin jälleen silmäni ja näin, katso, neljät vaunut, jotka lähtivät liikkeelle kahden vuoren välistä, ja vuoret olivat vaskivuoria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Ensimmäisten vaunujen edessä olivat punaruskeat hevoset, toisten vaunujen edessä olivat mustat hevoset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'kolmansien vaunujen edessä olivat valkoiset hevoset, ja neljänsien vaunujen edessä olivat täplikkäät, väkevät hevoset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Lausuin ja sanoin enkelille, joka oli puhutellut minua: \"Mitä nämä ovat, herra?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Enkeli vastasi ja sanoi minulle: \"Ne ovat neljä taivaan tuulta, jotka lähtevät liikkeelle seisottuaan kaiken maan Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Ne, joiden edessä ovat mustat hevoset, lähtevät pohjoiseen maahan, ja valkoiset lähtevät niiden perään. Täplikkäät lähtevät eteläiseen maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'Väkevät ovat lähdössä. Ne ovat innokkaita kiertelemään maata.\" Hän sanoi: \"Menkää kiertelemään maata\", ja ne kiertelivät maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Hän huusi minua ja sanoi minulle näin: \"Katso, ne, jotka lähtivät pohjoiseen maahan, saattavat Henkeni lepäämään pohjoisessa maassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Minulle tuli tämä Herran sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, '\"Ota vastaan karkotuksessa eläviltä Heldailta, Tobialta ja Jedajalta – mene tänä päivänä, mene Joosian, Sefanjan pojan, taloon, johon he ovat tulleet Baabelista –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'ja ota vastaan hopea ja kulta, tee kruunu ja pane se ylimmäisen papin Joosuan, Joosadakin pojan, päähän');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'ja sano hänelle näin: \"Näin sanoo Herra Sebaot: Katso, mies nimeltä Vesa! Omalta pohjaltaan hän on kasvava, ja hän on rakentava Herran temppelin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Herran temppelin hän on rakentava, ja valtasuuruutta hän on kantava, ja hän on istuva ja hallitseva valtaistuimellaan. Hän on oleva pappi valtaistuimellaan, ja rauhan neuvo on vallitseva niiden molempien kesken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Mutta kruunu on oleva muistona Herran temppelissä Helemistä, Tobiasta ja Jedajasta sekä Sefanjan pojan suosiollisuudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Kaukana asuvat tulevat ja rakentavat Herran temppeliä. Tulette tietämään, että Herra Sebaot on lähettänyt minut luoksenne. Näin tapahtuu, jos te todella kuulette Herran, Jumalanne, ääntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Kuningas Daarejaveksen neljäntenä vuotena tuli Herran sana Sakarjalle, neljäntenä päivänä yhdeksännessä kuussa, kislev-kuussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Beetel oli lähettänyt Sareserin ja Regem-Melekin miehineen rukoilemaan Herran kasvojen edessä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'ja kysymään Herran Sebaotin temppelin papeilta ynnä profeetoilta näin: \"Onko minun viidennessä kuussa itkettävä ja noudatettava pidättyvyyttä, niin kuin olen tehnyt jo monina vuosina?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Minulle tuli tämä Herran Sebaotin sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, '\"Sano kaikelle maan kansalle ja papeille näin: Kun olette paastonneet ja valittaneet viidennessä ja seitsemännessä kuussa, ja jo seitsemänäkymmenenä vuotena, niin minulleko olette paastonne paastonneet?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Kun olette syöneet ja juoneet, niin ettekö ole itsellenne syöneet ja juoneet?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Eikö niin: pitäkää ne sanat, jotka Herra on julistanut aikaisempien profeettojen kautta, kun Jerusalem vielä oli asuttuna ja levossa kuten myös sen ympärillä olevat kaupungit, ja Etelämaa ja Alankomaa olivat asuttuja?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Sakarjalle tuli tämä Herran sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, '\"Näin sanoo Herra Sebaot: Tuomitkaa oikea tuomio, tehkää laupeus ja olkaa armollisia kukin veljellenne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'leskeä, orpoa, muukalaista ja köyhää älkää sortako älkääkä miettikö mielessänne pahaa toinen toisellenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Mutta he kieltäytyivät ottamasta vaarin ja käänsivät uppiniskaisina selkänsä ja kovettivat korvansa, etteivät kuulisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'He tekivät sydämensä kovaksi kuin timantti, etteivät kuulisi lakia eivätkä niitä sanoja, jotka Herra Sebaot oli lähettänyt Hengellään entisten profeettojen kautta. Herralta Sebaotilta on tullut suuri viha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Samoin kuin hän julisti heille, mutta he eivät kuulleet, samoin he huutavat minulle, mutta en kuule, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'Minä karkotan myrskynä heidät kaikkien pakanakansojen sekaan, joita he eivät tunne, ja maa jää autioksi heidän jälkeensä menijöistä ja tulijoista. Ihanan maan he tekevät autioksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Tuli tämä Herran Sebaotin sana:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, '\"Näin sanoo Herra Sebaot: Olen kiivaillut Siionin puolesta suurella kiivaudella, suurella vihalla olen sen puolesta kiivaillut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Näin sanoo Herra: Käännyn jälleen Siionin puoleen ja tulen asumaan Jerusalemin keskelle, ja Jerusalemia kutsutaan \"Totuuden kaupungiksi\" ja Herran Sebaotin vuorta \"Pyhäksi vuoreksi\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Näin sanoo Herra Sebaot: Vielä on Jerusalemin toreilla istuva vanhuksia, miehiä ja naisia. Kullakin on sauvansa kädessään päivien paljouden vuoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'Silloin kaupungin torit tulevat olemaan täynnä nuoria poikia ja tyttöjä, jotka leikkivät sen toreilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Näin sanoo Herra Sebaot: Jos tämä onkin ihmeellistä tämän kansan jäännöksen silmissä niinä päivinä, onko se ihmeellistä myös minun silmissäni? – Tämä on Herran Sebaotin sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Näin sanoo Herra Sebaot: Katso, olen vapauttava kansani auringon nousun maasta ja laskun maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'Tuon heidät asumaan Jerusalemin keskelle. Niin he ovat kansani, ja minä olen heidän Jumalansa totuudessa ja vanhurskaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Näin sanoo Herra Sebaot: Olkoot kätenne vahvat, teidän, jotka näinä päivinä olette kuulleet nämä sanat profeettojen suusta, sinä päivänä, jona laskettiin Herran Sebaotin huoneen, rakennettavan temppelin, perustus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Sillä näiden päivien edellä ei saatu palkkaa ihmisen työstä, ei palkkaa eläinten työstä, eikä menijällä eikä tulijalla ollut rauhaa viholliselta, ja lähetin kaikki ihmiset toistensa kimppuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Nyt en ole tämän kansan jäännökselle samanlainen, kuin minä olin entisinä päivinä. – Tämä on Herran Sebaotin sana. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Sillä rauhan kylvö kylvetään, viiniköynnös antaa hedelmänsä, maa antaa satonsa, taivas antaa kasteensa, ja tämän kansan jäännökselle annan perintöosaksi kaiken tämän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'Niin kuin olette olleet kirouksena pakanakansojen seassa, te Juudan heimo ja Israelin heimo, niin te, kun teidät pelastan, tulette olemaan siunauksena. Älkää pelätkö, olkoot kätenne vahvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Sillä näin sanoo Herra Sebaot: Niin kuin aioin tehdä teille pahaa, kun teidän isänne vihoittivat minut, sanoo Herra Sebaot, enkä sitä katunut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'niin näinä päivinä sen sijaan minulla on mielessä tehdä hyvää Jerusalemille ja Juudan heimolle. Älkää pelätkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Näitä te tehkää: Puhukaa totuutta toinen toisellenne. Tuomitkaa porteissanne oikein, tuomitkaa rauhan tuomio.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'Älkää hautoko mielessänne pahaa toinen toisellenne älkääkä rakastako väärää valaa. Sillä kaikkia näitä minä vihaan. Tämä on Herran sana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Minulle tuli tämä Herran Sebaotin sana ja se kuului:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, '\"Näin sanoo Herra Sebaot: Neljännen kuun paasto, viidennen paasto, seitsemännen paasto ja kymmenennen paasto on oleva Juudan heimolle ilo ja riemu ja mieluinen juhla. Mutta rakastakaa totuutta ja rauhaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Näin sanoo Herra Sebaot: Vielä tulee kansoja, monien kaupunkien asukkaita,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'ja toisen asukkaat menevät toiseen kaupunkiin ja sanovat: \'Lähtekäämme rukoilemaan Herran edessä ja etsimään Herraa Sebaotia.\' – \'Minäkin lähden.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Niin monet kansat, väkevät pakanakansat, tulevat Jerusalemiin etsimään Herraa Sebaotia, etsimään Herran kasvoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Näin sanoo Herra Sebaot: Niinä päivinä tarttuu kymmenen miestä kaikista pakanakansojen kielistä, tarttuu Juudan miestä liepeeseen sanoen: \'Me tahdomme kulkea teidän kanssanne, sillä olemme kuulleet, että Jumala on teidän kanssanne.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Profeettasana, Herran sana, Hadrakin maata vastaan, ja Damaskossa se viipyy. Sillä Herran silmä katsoo ihmisiä, kaikkia Israelin sukukuntia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'myös Hamatia, joka on sen kanssa rajanaapurina, sekä Tyyroa ja Siidonia, sillä ne ovat hyvin viisaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Tyyro on rakentanut itselleen linnoituksia ja kasannut kokoon hopeaa kuin tomua ja kultaa kuin katujen lokaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Katso, Herra köyhdyttää sen ja syöksee mereen sen voiman, ja se itse poltetaan tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Sen näkee Askelon ja pelästyy, ja Gassa, ja vapisee kovin, ja Ekron, sillä sen toivo joutuu häpeään. Gassasta menehtyy kuningas, eikä Askelonissa enää asuta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'Asdodissa asuu sekakansaa, ja hävitän filistealaisten ylpeyden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Poistan veret hänen suustaan ja heidän iljetyksensä hänen hampaittensa välistä, ja hänestäkin jää jäännös Jumalallemme. Hän on oleva kuin sukuruhtinas Juudassa, ja Ekron on oleva kuin jebusilainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Teen leirini temppelini suojaksi sotajoukoilta, jotka tulevat ja menevät, eikä sortaja tule enää heidän kimppuunsa, sillä nyt olen katsellut sitä omin silmin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Iloitse suuresti, tytär Siion, riemuitse, tytär Jerusalem, sillä kuninkaasi tulee sinulle! Vanhurskas ja auttaja hän on, on nöyrä ja ratsastaa aasilla, aasintamman varsalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Hävitän vaunut Efraimista ja hevoset Jerusalemista. Sodan jousi hävitetään, ja hän julistaa rauhan kansoille. Hänen hallituksensa ulottuu merestä mereen ja virralta hamaan maan ääriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Myös vankisi päästän pois vedettömästä kuopasta liittosi verellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Palatkaa linnoitukseen, te vangit, joilla on toivo. Myös tänä päivänä julistan: kaksin verroin sinulle korvaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Sillä jännitän Juudan jousekseni, panen siihen nuoleksi Efraimin ja nostan poikasi, Siion, poikiasi vastaan, Jaavan, ja teen sinut sankarin miekan kaltaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Herra näkyy heidän yllään, ja hänen nuolensa lähtee kuin salama. Herra, Herra puhaltaa torveen ja kulkee etelän myrskytuulissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Tapahtuu myös, että Herra Sebaot suojelee heitä, ja he syövät ja he tallaavat linkokiviä, he juovat ja pauhaavat kuin viiniä nauttineet ja ovat täynnä kuin uhrimaljat, kuin alttarin kulmat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Herra, heidän Jumalansa, on sinä päivänä pelastava heidät, kansansa, joka on kuin hänen lammaslaumansa. He näet ovat kruunuun kiinnitettyjä kiviä, korotettuja hänen maansa ylle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Sillä kuinka suuri onkaan oleva heidän onnensa ja heidän ihanuutensa: vilja saa kasvamaan nuorukaiset ja rypälemehu neitsyet!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Rukoilkaa Herralta sadetta kevätsateen aikaan: Herra tekee ukkospilvet ja antaa heille sadekuurot, antaa kasvit jokaisen pellolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Sillä kotijumalat puhuvat jumalattomuutta, ja tietäjät näkevät petollisia näkyjä, puhuvat valheunia ja turhia sanoja. Sen tähden he saavat lähteä matkaan kuin lammaslauma ja kärsiä vaivaa, koska ei ole paimenta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Paimenia kohtaan on syttynyt vihani, ja rankaisen vuohipukkeja, sillä Herra Sebaot pitää huolen laumastaan, Juudan heimosta, ja asettaa sen ikään kuin kunniaratsukseen sodassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Siitä on lähtevä kulmakivi, siitä kiinnityspaalu, siitä sotajousi, siitä lähtevät kaikki käskijät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'He ovat kuin sankarit, jotka polkevat katujen lokaa sodassa. He sotivat, sillä Herra on heidän kanssaan, ja häpeään joutuvat hevosilla ratsastajat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Teen voimakkaaksi Juudan heimon ja pelastan Joosefin heimon. Palautan heidät, sillä armahdan heitä, ja he tulevat olemaan, kuin en olisi heitä hylännytkään. Sillä minä olen Herra, heidän Jumalansa, ja kuulen heidän rukouksensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Efraim on oleva kuin sankari, ja heidän sydämensä on iloitseva kuin viinistä. Heidän lapsensa näkevät sen ja iloitsevat; heidän sydämensä riemuitsee Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Olen viheltävä heille ja kokoava heidät, sillä lunastan heidät, ja he lisääntyvät, niin kuin lisääntyivät ennen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Kun sirottelen heitä kansojen sekaan, he muistavat minut kaukaisissa maissa, ja he elävät lastensa kanssa ja palaavat takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Tuon heidät takaisin Egyptin maasta ja kokoan heidät Assurista. Vien heidät Gileadin maahan ja Libanonille, eikä heille ole riittävästi tilaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Hän käy ahdistuksen meren halki, hän lyö meren aaltoja, ja kaikki Niilivirran syvyydet kuivuvat, Assurin ylpeys painuu alas, ja Egyptin valtikka väistyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Mutta heidät teen voimakkaiksi Herrassa, ja he vaeltavat hänen nimessään. Tämä on Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Avaa ovesi, Libanon! Tuli on kuluttava setrisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Vaikertakoon sypressi, sillä setri on kaatunut. Hävitetyt ovat nuo mahtavat. Valittakaa, te Baasanin tammet, sillä luoksepääsemätön metsä on sortunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Kuule paimenten valitusta, kun heidän mahtavansa on hävitetty. Kuule nuorten leijonien karjahtelua, kun Jordanin ylpeys on hävitetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Näin sanoi Herra, Jumalani:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, '\"Kaitse teuraslampaita, joita niiden ostajat teurastavat tuntematta syyllisyyttä, ja joista niiden myyjät sanovat: \'Kiitetty olkoon Herra, olen rikastunut\', ja joita niiden paimenet eivät sääli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Sillä en enää säästä maan asukkaita. Tämä on Herran sana. Katso, annan ihmisten joutua toistensa käsiin ja kuninkaansa käsiin, ja he hävittävät maan, enkä pelasta ketään heidän käsistään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Kaitsin teuraslampaita, lampaista kurjimpia. Otin itselleni kaksi sauvaa. Nimitin toisen \"Suloudeksi\", toisen nimitin \"Yhteydeksi\", ja kaitsin lampaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Hävitin kolme paimenta yhtenä kuukautena, mutta sieluni kävi kärsimättömäksi lampaille, ja heidänkin sielunsa kääntyi minusta pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Sanoin: \"En kaitse teitä enää. Kuolkoon, joka kuolee. Hävitköön, joka häviää, ja jäljellejäävät syökööt toistensa lihaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Otin sauvani Sulouden ja katkaisin sen purkaakseni liittoni, jonka olin tehnyt kaikkien kansojen kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Sinä päivänä se purkautui, ja lampaista kurjimmat, jotka ottivat minusta vaarin, tulivat tietämään, että se oli Herran sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Sanoin heille: \"Jos teille hyväksi näkyy, antakaa minulle palkkani; jollei, niin olkaa antamatta.\" He punnitsivat palkakseni kolmekymmentä hopearahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Herra sanoi minulle: \"Heitä se savenvalajalle, tuo kallis hinta, jonka arvoiseksi he ovat minut arvioineet.\" Otin ne kolmekymmentä hopearahaa ja heitin ne Herran huoneeseen savenvalajalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Sitten katkaisin toisen sauvani, Yhteyden, purkaakseni veljeyden Juudan ja Israelin väliltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Herra sanoi minulle: \"Ota vielä itsellesi hullun paimenen kapineet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Sillä katso, minä olen herättävä maahan paimenen: kadonneesta hän ei pidä huolta, hajaantunutta hän ei etsi, ruhjoutunutta hän ei paranna, pystyssä pysyvää hän ei tue. Mutta hän syö lihavien lihaa ja halkaisee niiden sorkat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Voi hullua paimenta, joka lampaat hylkää! Käyköön miekka hänen käsivarteensa ja oikeaan silmäänsä. Hänen käsivartensa kuivettukoon, ja hänen oikea silmänsä soetkoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Profeettasana. Herran sana Israelista. Tämä on Herran sana. Hän on jännittänyt taivaan ja perustanut maan sekä luonut ihmisen hengen hänen sisimpäänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Katso, minä teen Jerusalemin maljaksi, joka panee kaikki kansat horjumaan sen ympärillä, ja myös Juudalle se on tuleva, kun Jerusalemia piiritetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'Sinä päivänä tapahtuu, että teen Jerusalemin raskaaksi kiveksi kaikille kansoille. Kaikki, jotka sitä nostavat, telovat itsensä; ja kaikki maan kansakunnat kokoontuvat sitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'Sinä päivänä – tämä on Herran sana – lyön kaikki hevoset vauhkoudella ja niiden ratsastajat hulluudella. Mutta Juudan heimoa kohti avaan silmäni, ja kaikki kansojen hevoset lyön sokeudella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Silloin Juudan sukuruhtinaat sanovat sydämessään: \"Minun väkevyyteni ovat Jerusalemin asukkaat Herrassa Sebaotissa, heidän Jumalassaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'Sinä päivänä teen Juudan sukuruhtinaat ikään kuin tulipannuksi puiden sekaan ja ikään kuin tulisoihduksi lyhteiden sekaan, ja he kuluttavat oikealta ja vasemmalta, kuluttavat kaikki kansat ympäriltään. Jerusalem asuu yhä paikoillaan Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Herra on ensiksi pelastava Juudan telttamajat, ettei Daavidin suvun kunnia ja Jerusalemin asukkaiden kunnia ylvästelisi Juudaa vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'Sinä päivänä Herra suojaa Jerusalemin asukkaita. Se, joka heistä kompastuu, on sinä päivänä oleva kuin Daavid, ja Daavidin huone on oleva kuin Jumala, kuin Herran Enkeli heidän edessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'Mutta tapahtuu, että sinä päivänä minä hävitän kaikki pakanakansat, jotka hyökkäävät Jerusalemia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Vuodatan Daavidin huoneen päälle ja Jerusalemin asukkaiden päälle armon ja rukouksen Hengen. He katsovat minuun, jonka ovat lävistäneet. He valittavat häntä, niin kuin valitetaan ainoaa poikaa, murehtivat häntä katkerasti, niin kuin katkerasti murehditaan esikoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'Sinä päivänä pidetään Jerusalemissa suuret valittajaiset, niin kuin olivat Hadadrimmonin valittajaiset Megiddon laaksossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Maa pitää valittajaisia, kukin sukukunta erikseen: Daavidin huoneen sukukunta erikseen ja heidän naisensa erikseen, Naatanin huoneen sukukunta erikseen ja heidän naisensa erikseen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'Leevin huoneen sukukunta erikseen ja heidän naisensa erikseen, siimeiläisten sukukunta erikseen ja heidän naisensa erikseen. Kaikki muut sukukunnat, kukin sukukunta erikseen ja heidän naisensa erikseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, '');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'Sinä päivänä on Daavidin suvulla ja Jerusalemin asukkailla oleva avoin lähde syntiä ja saastaisuutta vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'Sinä päivänä tapahtuu – tämä on Herran Sebaotin sana – että hävitän epäjumalien nimet maasta, eikä niitä enää muisteta. Myös profeetat ja saastaisuuden hengen karkotan maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'Jos joku vielä ennustaa, hänen isänsä ja äitinsä, hänen vanhempansa, sanovat hänelle: \"Sinä et saa elää, koska olet puhunut valhetta Herran nimeen.\" Hänen isänsä ja äitinsä, hänen vanhempansa, lävistävät hänet hänen ennustamisensa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'Sinä päivänä tapahtuu, että profeetat häpeävät kukin näkyään, kun he ennustavat, eivätkä he valehdellakseen pue päälleen karvaista viittaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Hän sanoo: \"En ole profeetta, vaan peltomies, sillä eräs mies on ostanut minut orjaksi jo nuoruudessani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'Jos häneltä kysytään: \"Mitä ovat nuo haavat käsissäsi?\" hän vastaa: \"Ne lyötiin rakkaitten ystävieni huoneessa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Herää, miekka, paimentani vastaan ja lähintä miestäni vastaan. Tämä on Herran Sebaotin sana. Lyö paimenta, ja joutukoot lampaat hajalle, mutta käännän jälleen käteni pienimpiä kohden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Näin on käyvä koko maassa. – Tämä on Herran sana. – Kaksi osaa siitä hävitetään ja saa surmansa, mutta kolmas osa siitä jää jäljelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'Kolmannen osan vien tuleen. Sulatan heidät, kuin hopea sulatetaan, ja koettelen heitä, niin kuin kultaa koetellaan. He huutavat avuksi nimeäni, ja vastaan heille. Sanon: \"Se on kansani\", ja se sanoo: \" Herra, Jumalani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Katso, Herran päivä tulee, ja saaliisi jaetaan keskelläsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Kokoan kaikki pakanat sotaan Jerusalemia vastaan. Kaupunki valloitetaan, talot ryöstetään, naiset raiskataan, ja puoli kaupunkia lähtee karkotukseen, mutta jäljelle jäävää kansaa ei hävitetä kaupungista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Herra lähtee liikkeelle ja sotii näitä pakanoita vastaan, niin kuin sodan käyntinsä päivänä, taistelun päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'Hänen jalkansa seisovat sinä päivänä Öljymäellä, joka on Jerusalemin edustalla itää kohti. Öljymäki halkeaa kahtia idästä länteen hyvin suureksi laaksoksi: toinen puoli mäkeä siirtyy pohjoiseen ja toinen puoli etelään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Mutta te pakenette mäkieni väliseen laaksoon, sillä mäkien välinen laakso ulottuu Asaliin asti. Te pakenette, niin kuin pakenitte maanjäristystä Ussian, Juudan kuninkaan, päivinä. Herra, Jumalani, tulee ja kaikki pyhät kanssasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'Tapahtuu, ettei sinä päivänä ole valoa. Pimeys sammuttaa valon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Se on oleva yksi päivä – Herran tuntema. Ei ole päivää eikä yötä, ja ehtoolla on oleva valoisaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'Tapahtuu, että sinä päivänä elävät vedet virtaavat Jerusalemista: toiset puolet niistä Idänmerta kohti, toiset puolet Länsimerta kohti. Niin tapahtuu kesällä ja talvella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Herra on oleva koko maan kuningas. Sinä päivänä on Herra oleva yksi ja hänen nimensä yksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Koko maa muuttuu tasaiseksi kuin Aromaa Gebasta Rimmoniin asti Jerusalemin eteläpuolelle. Tämä on oleva korkea ja asuttu paikallaan Benjaminin portista entisen portin kohdalle asti, Kulmaporttiin ja Hananelin tornilta kuninkaan viinikuurniin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'He asuvat siellä, eikä sitä enää hävitetä, ja Jerusalem on oleva asuttu ja turvassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Mutta tämä on oleva vitsaus, jolla Herra rankaisee niitä kansoja, jotka sotivat Jerusalemia vastaan: hän mädättää siltä kansalta lihan, kun se vielä seisoo jaloillaan, sen silmät mätänevät kuopissaan, ja sen kieli mätänee sen suussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'Sinä päivänä on tuleva Herralta suuri hämminki heidän keskelleen, niin että he käyvät kiinni toinen toisensa käteen ja toisen käsi kohoaa toisen kättä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Myös Juuda on sotiva Jerusalemissa, ja kaikkien pakanakansojen rikkaudet kootaan joka taholta: kullat ja hopeat ja hyvin paljon vaatteita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Samoin on vitsaus kohtaava hevosia, muuleja, kameleja, aaseja ja kaikkea karjaa, mitä niissä leireissä on – kaikkia samanlainen vitsaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Mutta tapahtuu, että kaikki niiden pakanakansojen tähteet, jotka ovat hyökänneet Jerusalemia vastaan, nousevat vuosi vuodelta sinne kumartaen rukoilemaan kuningasta, Herraa Sebaotia, ja viettämään lehtimajanjuhlaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Tapahtuu, että niille maan sukukunnille, jotka eivät nouse Jerusalemiin kumartaen rukoilemaan kuningasta, Herraa Sebaotia, ei tule sadetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'Mutta jos egyptiläisten sukukunta ei nouse eikä tule sinne ylös, ei tule sitä heillekään, vaan heitä on kohtaava se vitsaus, millä Herra rankaisee niitä pakanakansoja, jotka eivät nouse sinne viettämään lehtimajanjuhlaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Tämä on oleva egyptiläisten synnin rangaistus ja kaikkien niiden pakanakansojen synnin rangaistus, jotka eivät nouse sinne viettämään lehtimajanjuhlaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'Sinä päivänä lukee hevosten kulkusissa: \"Pyhitetty Herralle.\" Padat Herran temppelissä ovat uhrimaljojen vertaisia, jotka ovat alttarin edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Silloin jokainen pata Jerusalemissa ja Juudassa on oleva pyhä Herralle Sebaotille, ja kaikki uhraajat tulevat ja ottavat niitä ja keittävät niissä. Eikä sinä päivänä ole enää yhtään kaupustelijaa Herran Sebaotin temppelissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Profeettasana. Herran sana Israelille, Malakian kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Olen rakastanut teitä, sanoo Herra. Mutta sanotte: \"Missä olet osoittanut rakkautesi meihin?\" Eikö Eesau ollut Jaakobin veli – tämä on Herran sana – ja Jaakobia rakastin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'mutta Eesauta vihasin; ja tein hänen vuorensa autioiksi ja annoin hänen perintöosansa erämaan sakaaleille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Jos Edom sanoo: \"Olemme ruhjotut, mutta rakennamme rauniot jälleen\", niin Herra Sebaot sanoo näin: He rakentakoot, mutta minä revin maahan. Heidän nimensä olkoon: \"jumalattomuuden maa\" ja \"kansa, johon Herra on vihastunut iankaikkisesti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Silmänne näkevät sen, ja sanotte: \" Herra on suuri Israelin rajojen ulkopuolellakin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Poika kunnioittakoon isää ja palvelija isäntäänsä. Mutta jos minä olen isä, missä on kunnioitukseni? Ja jos minä olen Herra, missä on pelkoni? sanoo Herra Sebaot teille, te papit, jotka pidätte halpana nimeni. Mutta te sanotte: \"Miten olemme pitäneet nimesi halpana?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Siten, että tuotte alttarilleni saastutettua leipää. Mutta sanotte: \"Miten olemme sinut saastuttaneet?\" Siten, että sanotte: \" Herran pöytä on pidettävä halpana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Kun te tuotte uhriksi sokean eläimen, se ei ole paha! Kun tuotte ontuvan ja sairaan, se ei ole paha! Vie se maaherrallesi: mieltyykö hän sinuun, ja onko hän sinulle suosiollinen? sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Mutta nyt: lepyttäkää Jumalaa, että hän meitä armahtaisi. Tällaista on kädestänne tullut. Olisiko hän teille suosiollinen? sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Jospa olisi teidän joukossanne joku, joka sulkisi ovet, ettette pitäisi alttarillani tulta turhaan! Ei ole minulla mielisuosiota teihin, sanoo Herra Sebaot, enkä mielly ruokauhriin, joka tulee kädestänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Sillä auringon noususta sen laskuun asti on nimeni oleva suuri pakanain seassa, ja joka paikassa uhrataan ja tuodaan nimeni kunniaksi puhdas ruokauhri. Sillä nimeni on oleva suuri pakanain seassa, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Mutta te häpäisette sen, kun sanotte: \"Herran pöytä on saastutettu, ja sen hedelmän syönti on pidettävä halpana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Mutta te sanotte: \"Mikä vaiva!\" ja halveksitte sitä, sanoo Herra Sebaot, ja tuotte ryöstettyä, ontuvaa ja sairasta – tuotte sellaista uhrilahjaksi. Minäkö miellyn ottamaan sen kädestänne? sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Kirottu olkoon pettäjä, jolla on laumassaan koiraspuoli ja joka on luvannut sen, mutta uhraakin Herralle viallisen. Sillä suuri kuningas olen minä, sanoo Herra Sebaot, ja nimeni on pelottava pakanain keskuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Mutta nyt teille tämä käsky, te papit!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Jos ette kuule ja paina sydämeenne, että annatte kunnian nimelleni, sanoo Herra Sebaot, lähetän teitä vastaan kirouksen ja kiroan teille suodut siunaukset. Olenkin ne jo kironnut, sillä te ette ole painaneet tätä sydämeenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Katso, kiellän teiltä jälkeläiset, ja viskelen sontaa kasvoillenne, ruokasulaa juhlauhreistanne, ja teidät kannetaan sen kanssa pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Tulette tietämään, että olen lähettänyt teille tämän käskyn, jotta liittoni Leevin kanssa pysyisi, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Liittoni hänen kanssaan oli elämä ja rauha, ja annoin sen hänelle peloksi, niin että hän pelkäsi minua ja kunnioitti nimeäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Oikea opetus oli hänen suussaan, eikä vääryyttä tavattu hänen huuliltaan. Rauhassa ja vilpittömästi hän vaelsi kanssani, ja monia hän käänsi pois syntiä tekemästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Sillä papin huulet säilyttävät tiedon, ja hänen suustaan etsitään opetus, sillä hän on Herran Sebaotin sanansaattaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Mutta te olette poikenneet tieltä, olette opetuksellanne saattaneet monet kompastumaan, ja olette turmelleet Leevin liiton, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Minäkin teen teidät halveksituiksi ja alhaisiksi koko kansalle, koska ette ole pitäneet teitäni, vaan olette katsoneet henkilöön opetuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Eikö meillä kaikilla ole sama Isä? Eikö sama Jumala ole meitä luonut? Miksi olemme uskottomia toisillemme ja rikomme isiemme liiton?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Juuda on ollut uskoton, Israelissa ja Jerusalemissa on tehty kauhistus. Sillä Juuda on häväissyt Herran pyhäkön, jota Herra rakastaa, ja on nainut vieraan jumalan tyttären.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Hävittäköön Herra siltä mieheltä, joka tämän tekee, Jaakobin telttamajoista valvojan, vastaajan ja Herran Sebaotin uhrilahjan tuojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Toiseksi olette tehneet tämän: olette saattaneet Herran alttarin peitetyksi kyynelillä, itkulla ja huokauksilla, niin ettei hän enää käänny uhrilahjojen puoleen eikä mielly ottamaan mitään kädestänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Mutta te sanotte: \"Kuinka niin?\" Sen tähden, että Herra on todistaja sinun ja nuoruutesi vaimon välillä, jolle sinä olet ollut uskoton, vaikka hän on puolisosi, laillinen aviovaimosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Ei kukaan, jolla on jäännös Hengestä, ole tehnyt niin. Mutta miksi se yksi? Hän etsi Jumalalta siementä? – Ottakaa vaari hengestänne älkääkä olko uskottomia nuoruutenne vaimolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Sillä minä vihaan hylkäämistä, sanoo Herra, Israelin Jumala, ja sitä, joka peittää vaatteensa väkivallalla, sanoo Herra Sebaot. Ottakaa vaari hengestänne älkääkä olko uskottomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Te väsytätte Herran puheillanne. Mutta te sanotte: \"Miten väsytämme?\" Siten, että sanotte: \"Jokainen, joka pahaa tekee, on hyvä Herran silmissä, ja niihin hänellä on mielisuosio\"; tai: \"Missä on tuomion Jumala?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Katso, lähetän sanansaattajani, ja hän on valmistava tien eteeni. Joutuin temppeliinsä on tuleva Herra, jota te etsitte, ja Liiton Enkeli, jota te rakastatte. Katso, hän tulee, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Mutta kuka kestää hänen tulemisensa päivän, ja kuka voi pysyä, kun hän ilmestyy? Sillä hän on kuin kultasepän tuli ja kuin pesijäin saippua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Hän istuu ja sulattaa ja puhdistaa hopean, hän puhdistaa Leevin pojat, saa ne puhtaiksi kuin kullan ja hopean ja sitten he tuovat Herralle uhrilahjoja vanhurskaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Silloin Herralle ovat otollisia Juudan ja Jerusalemin uhrilahjat kuin muinaisina päivinä ja entisinä vuosina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Lähestyn teitä pitääkseni tuomion ja tulen kiireesti todistajaksi velhoja, avionrikkojia ja väärinvannojia vastaan ja niitä vastaan, jotka sortavat palkkalaista palkanmaksussa, leskeä ja orpoa ja vääntävät vääräksi muukalaisen asian eivätkä pelkää minua, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Sillä minä, Herra, en muutu, ettekä te, Jaakobin lapset, lopeta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Isienne päivistä asti te olette poikenneet säädöksistäni ettekä ole noudattaneet niitä. Kääntykää luokseni, niin käännyn teidän luoksenne, sanoo Herra Sebaot. Mutta te sanotte: \"Missä asiassa meidän on käännyttävä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Riistääkö ihminen Jumalalta? Te kuitenkin riistätte minulta. Mutta te sanotte: \"Missä asiassa sinulta riistämme?\" Kymmenyksissä ja antimissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Te olette kirouksella kirotut, koska te, koko kansa, riistätte minulta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Tuokaa täydet kymmenykset varastohuoneeseen, että huoneessani olisi ravintoa, ja siten koetelkaa minua, sanoo Herra Sebaot, ettenkö avaa teille taivaan ikkunoita ja vuodata teille siunausta ylenpalttisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Karkotan nuhtelullani teiltä syöjät turmelemasta maanne hedelmää, eikä viiniköynnöksenne kedolla ole hedelmätön, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'Silloin teitä ylistävät autuaiksi kaikki pakanat, sillä te tulette olemaan ihana maa, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Julkeita ovat puheenne minua vastaan, sanoo Herra. Mutta te sanotte: \"Mitä olemme sinua vastaan puhuneet?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Te sanotte: \"Turhaa on palvella Herraa. Mitä hyötyä siitä on ollut, että olemme suorittaneet hänelle säädetyt tehtävät ja että olemme vaeltaneet murheellisina Herran Sebaotin kasvojen edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Nyt me kiitämme julkeitten onnea. Ne, jotka tekevät sitä, mikä on jumalatonta, tulevat rakennetuiksi. He kiusaavat Jumalaa, mutta pelastuvat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Silloin myös Herraa pelkäävät puhuvat toinen toisensa kanssa, ja Herra tarkkailee ja kuulee. Muistokirja kirjoitetaan hänen edessään niiden hyväksi, jotka pelkäävät Herraa ja pitävät hänen nimensä kunniassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'He ovat omaisuuteni, sanoo Herra Sebaot, sinä päivänä, jonka teen. Olen heille laupias, niin kuin mies on laupias pojalleen, joka häntä palvelee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Tulette jälleen näkemään, mikä on ero vanhurskaan ja jumalattoman välillä, sen välillä, joka palvelee Jumalaa, ja sen, joka ei häntä palvele.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 19, 'Sillä katso: tulee päivä, joka palaa kuin pätsi. Kaikki julkeat ja kaikki, jotka tekevät sitä, mikä on jumalatonta, ovat oljenkorsia. Heidät polttaa se päivä, joka tulee, sanoo Herra Sebaot, niin ettei se jätä heistä juurta eikä oksaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 20, 'Mutta teille, jotka nimeäni pelkäätte, koittaa vanhurskauden aurinko ja parantuminen sen siipien alla, ja käytte ulos ja hypitte kuin navetan syöttövasikat');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 21, 'ja tallaatte jumalattomat. He näet tulevat tomuksi jalkapohjienne alle sinä päivänä, jonka minä teen, sanoo Herra Sebaot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 22, 'Muistakaa palvelijani Mooseksen laki, jonka säädin Hoorebilla hänelle koko Israelia varten käskyiksi ja oikeuksiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 23, 'Katso, minä lähetän teille profeetta Elian, ennen kuin tulee Herran päivä, se suuri ja pelottava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 24, 'Hän kääntää jälleen isien sydämet lasten puoleen ja lasten sydämet heidän isiensä puoleen, etten tulisi ja löisi maata kirouksella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Jeesuksen Kristuksen, Daavidin pojan, Aabrahamin pojan, syntykirja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Aabrahamille syntyi Iisak, Iisakille syntyi Jaakob, Jaakobille syntyi Juuda ja tämän veljet;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Juudalle syntyi Faares ja Sera Taamarista, Faareelle syntyi Esrom, Esromille syntyi Aram;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Aramille syntyi Aminadab, Aminadabille syntyi Nahasson, Nahassonille syntyi Salmon;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Salmonille syntyi Booas Raahabista, Booalle syntyi Oobed Ruutista, Oobedille syntyi Iisai;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Iisaille syntyi Daavid, kuningas. Daavidille syntyi Salomo Uurian vaimosta;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Salomolle syntyi Rehabeam, Rehabeamille syntyi Abia, Abialle syntyi Aasa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Aasalle syntyi Joosafat, Joosafatille syntyi Jooram, Jooramille syntyi Ussia;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Ussialle syntyi Jootam, Jootamille syntyi Aahas, Aahaalle syntyi Hiskia;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Hiskialle syntyi Manasse, Manasselle syntyi Aamon, Aamonille syntyi Joosia;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Joosialle syntyi Jekonja ja tämän veljet Babyloniin siirtämisen aikoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Babyloniin siirtämisen jälkeen Jekonjalle syntyi Sealtiel, Sealtielille syntyi Serubbaabel;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Serubbaabelille syntyi Abiud, Abiudille syntyi Eljakim, Eljakimille syntyi Asor;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Asorille syntyi Saadok, Saadokille syntyi Akim, Akimille syntyi Eliud;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Eliudille syntyi Eleasar, Eleasarille syntyi Mattan, Mattanille syntyi Jaakob;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Jaakobille syntyi Joosef, Marian mies, hänen, josta syntyi Jeesus, jota kutsutaan Kristukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Näin on sukupolvia Aabrahamista Daavidiin kaikkiaan neljätoista polvea, ja Daavidista Babyloniin siirtämiseen neljätoista polvea, ja Babyloniin siirtämisestä Kristukseen asti neljätoista polvea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Jeesuksen Kristuksen syntyminen oli näin. Kun hänen äitinsä Maria oli kihlattu Joosefille, huomattiin hänen ennen heidän menoaan yhteen olevan raskaana Pyhästä Hengestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Mutta kun Joosef, hänen miehensä, oli hurskas, ja koska hän ei tahtonut saattaa häntä häpeään, hän aikoi hylätä hänet salaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Mutta kun hän tätä ajatteli, katso, hänelle ilmestyi unessa Herran enkeli, joka sanoi: \"Joosef, Daavidin poika, älä pelkää ottaa luoksesi Mariaa, vaimoasi, sillä se, mikä hänessä on siinnyt, on Pyhästä Hengestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Hän on synnyttävä pojan, ja sinun on annettava hänelle nimi Jeesus, sillä hän on vapahtava kansansa heidän synneistään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Tämä kaikki on tapahtunut, että kävisi toteen, minkä Herra on puhunut profeetan kautta, joka sanoo:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '\"Katso, neitsyt tulee raskaaksi ja synnyttää pojan, ja tälle annetaan nimi Immanuel\", mikä on käännettynä: Jumala meidän kanssamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Herättyään unesta Joosef teki, kuten Herran enkeli oli käskenyt hänen tehdä, ja otti vaimonsa luokseen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'eikä yhtynyt häneen, ennen kuin Maria oli synnyttänyt pojan, ja hän antoi hänelle nimen Jeesus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Kun Jeesus oli syntynyt Juudean Beetlehemissä kuningas Herodeksen aikana, katso, tietäjiä tuli Idän mailta Jerusalemiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'ja he sanoivat: \"Missä on äsken syntynyt juutalaisten kuningas? Sillä me näimme hänen tähtensä Idän mailla ja olemme tulleet häntä kumartamaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Kun kuningas Herodes sen kuuli, hän hämmästyi ja koko Jerusalem hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Koottuaan kaikki kansan ylipapit ja kirjanoppineet, hän kyseli heiltä, missä Kristus oli syntyvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'He sanoivat hänelle: \"Juudean Beetlehemissä, sillä näin on kirjoitettu profeetan kautta:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, '\'Sinä Beetlehem, sinä Juudan seutu, et suinkaan ole vähäisin Juudan ruhtinasten joukossa, sillä sinusta on lähtevä hallitsija, joka kaitsee kansaani Israelia.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Silloin Herodes kutsui tietäjät luokseen salaa ja tutki heiltä tarkasti, mihin aikaan tähti oli ilmestynyt');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'ja lähetti heidät Beetlehemiin sanoen: \"Menkää ja tiedustelkaa tarkasti lasta, ja kun löydätte hänet, ilmoittakaa minulle, että minäkin tulisin häntä kumartamaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Kuultuaan kuninkaan sanat he lähtivät matkalle; ja katso, tähti, jonka he olivat nähneet Idän mailla, kulki heidän edellään, kunnes se tuli sen paikan päälle, jossa lapsi oli, ja pysähtyi siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Nähdessään tähden he iloitsivat hyvin suurella ilolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Mentyään taloon he näkivät lapsen sekä Marian, hänen äitinsä, lankesivat maahan, kumarsivat häntä, avasivat aarteensa ja toivat hänelle lahjoja: kultaa, suitsuketta ja mirhaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Jumala kielsi heitä unessa Herodeksen luo palaamasta, ja he menivät toista tietä takaisin omaan maahansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Mutta heidän mentyään, katso, Herran enkeli ilmestyi Joosefille unessa ja sanoi: \"Nouse, ota lapsi ja hänen äitinsä ja pakene Egyptiin, ja ole siellä siihen asti, kuin sinulle sanon; sillä Herodes on etsivä lasta surmatakseen hänet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Noustuaan yöllä hän otti lapsen ja hänen äitinsä ja siirtyi Egyptiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'Hän oli siellä Herodeksen kuolemaan asti, jotta kävisi toteen, minkä Herra on puhunut profeetan kautta, joka sanoo: \"Egyptistä minä kutsuin Poikani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Silloin Herodes nähtyään, että tietäjät olivat hänet pettäneet, vihastui suuresti ja lähetti tappamaan kaikki poikalapset Beetlehemistä ja koko sen ympäristöstä, kaksivuotiaat ja nuoremmat, sen mukaan kuin hän oli tiedustellut tarkasti aikaa tietäjiltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Silloin kävi toteen, mikä on puhuttu profeetta Jeremian kautta, joka sanoo:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, '\"Ääni kuuluu Raamasta, itku ja suuri valitus. Raakel itkee lapsiaan eikä huoli lohdutuksesta, kun heitä ei enää ole.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Mutta kun Herodes oli kuollut, katso, Herran enkeli ilmestyi unessa Joosefille Egyptissä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'ja sanoi: \"Nouse, ota lapsi ja hänen äitinsä ja mene Israelin maahan, sillä ne, jotka etsivät lapsen henkeä, ovat kuolleet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Hän nousi, otti lapsen ja hänen äitinsä ja meni Israelin maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Mutta kuultuaan, että Arkelaus hallitsi Juudeaa isänsä Herodeksen jälkeen, hän pelkäsi mennä sinne. Hän sai unessa Jumalalta käskyn ja lähti Galilean alueelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'Sinne tultuaan hän asettui asumaan kaupunkiin, jonka nimi on Nasaret; että kävisi toteen, mikä on puhuttu profeettojen kautta, että hänet on kutsuttava Nasaretilaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'Niinä päivinä tuli Johannes Kastaja ja saarnasi Juudean erämaassa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'sanoen: \"Muuttakaa mielenne, sillä taivasten valtakunta on tullut lähelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Hän on näet se, josta on puhuttu profeetta Jesajan kautta sanoen: \"Airuen ääni kuuluu erämaassa: \'Valmistakaa Herralle tie, tehkää polut hänelle suoriksi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Johanneksella oli puku kamelinkarvoista ja vyötäisillään nahkavyö, ja ruokana hänellä oli heinäsirkat ja kedon hunaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Silloin hänen luokseen vaelsi Jerusalem ja koko Juudea ja kaikki Jordanin ympäristö,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'ja he saivat kasteen häneltä Jordanin virrassa, kun he tunnustivat syntinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Mutta nähdessään paljon fariseuksia ja saddukeuksia tulevan kasteelle hän sanoi heille: \"Te kyykäärmeitten sikiöt, kuka on neuvonut teitä pakenemaan tulevaa vihaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Tehkää sen tähden mielenmuutoksen soveliaita hedelmiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'älkääkä luulko voivanne sanoa mielessänne: \'Onhan meillä isänä Aabraham\'; sillä minä sanon teille, että Jumala voi näistä kivistä herättää lapsia Aabrahamille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Kirves on jo pantu puiden juurelle. Jokainen puu, joka ei tee hyvää hedelmää, hakataan siis pois ja heitetään tuleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Minä kastan teitä vedellä mielenmuutokseen, mutta se, joka minun jälkeeni tulee, on minua voimakkaampi, jonka sandaaleitakaan en ole kelvollinen kantamaan. Hän kastaa teitä Pyhällä Hengellä ja tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Hänellä on viskimensä kädessään, ja hän puhdistaa puimatanterensa ja kokoaa vehnänjyvänsä aittaan, mutta ruumenet hän polttaa sammumattomassa tulessa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Silloin Jeesus tuli Galileasta Jordanille Johanneksen luo hänen kastettavakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Mutta tämä esteli häntä sanoen: \"Minun tarvitsee saada sinulta kaste, ja sinä tulet minun luokseni!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Jeesus vastasi ja sanoi hänelle: \"Salli nyt; sillä näin meidän sopii täyttää kaikki vanhurskaus.\" Silloin hän salli sen hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Kun Jeesus oli kastettu, hän nousi heti vedestä, ja katso, taivaat aukenivat, ja hän näki Jumalan Hengen tulevan alas kyyhkysenä ja laskeutuvan hänen päälleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'ja katso, taivaista kuului ääni, joka sanoi: \"Tämä on minun rakas Poikani, johon olen mieltynyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Sitten Henki vei Jeesuksen ylös erämaahan perkeleen kiusattavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Kun Jeesus oli paastonnut neljäkymmentä päivää ja neljäkymmentä yötä, hänen tuli sen jälkeen nälkä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Silloin kiusaaja tuli hänen luokseen ja sanoi hänelle: \"Jos olet Jumalan Poika, käske näiden kivien muuttua leiviksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Mutta hän vastasi ja sanoi: \"Kirjoitettu on: \'Ei ihminen elä ainoastaan leivästä, vaan jokaisesta sanasta, joka Jumalan suusta lähtee.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Silloin perkele otti hänet kanssaan pyhään kaupunkiin ja asetti hänet pyhäkön harjalle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'ja sanoi hänelle: \"Jos olet Jumalan Poika, heittäydy tästä alas; sillä kirjoitettu on: \'Hän antaa enkeleilleen sinusta käskyn\', ja: \'He kantavat sinua käsillään, ettet jalkaasi kiveen loukkaisi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Jeesus sanoi hänelle: \"Taas on kirjoitettu: \'Älä kiusaa Herraa, sinun Jumalaasi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Taas perkele otti hänet kanssaan hyvin korkealle vuorelle ja näytti hänelle kaikki maailman valtakunnat ja niiden loiston');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'ja sanoi hänelle: \"Tämän kaiken annan sinulle, jos lankeat eteeni ja rukoilet minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Silloin Jeesus sanoi hänelle: \"Mene pois, saatana; sillä kirjoitettu on: \'Herraa, sinun Jumalaasi, pitää sinun kumartaen rukoilla ja häntä ainoaa palvella.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Silloin perkele jätti hänet; ja katso, enkeleitä tuli Jeesuksen luo, ja he palvelivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Mutta kun Jeesus kuuli, että Johannes oli pantu vankeuteen, hän poistui Galileaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Hän jätti Nasaretin ja meni asumaan Kapernaumiin, joka on meren rannalla, Sebulonin ja Naftalin alueella,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'että kävisi toteen, mikä on puhuttu profeetta Jesajan kautta, joka sanoo:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, '\"Sebulonin maa ja Naftalin maa, meren tie, Jordanin tuonpuoleinen maa, pakanain Galilea –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'kansa, joka pimeydessä istui, näki suuren valkeuden, ja jotka istuivat kuoleman maassa ja varjossa, niille koitti valkeus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Siitä lähtien Jeesus rupesi saarnaamaan ja sanomaan: \"Muuttakaa mielenne, sillä taivasten valtakunta on tullut lähelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Kulkiessaan Galilean järven rantaa hän näki kaksi veljestä, Simonin, jota kutsutaan Pietariksi, ja Andreaan, hänen veljensä, heittämässä verkkoa järveen; sillä he olivat kalastajia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Hän sanoi heille: \"Seuratkaa minua, niin teen teistä ihmisten kalastajia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Heti he jättivät verkot ja seurasivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Kulkiessaan siitä eteenpäin hän näki toiset kaksi veljestä, Jaakobin, Sebedeuksen pojan, ja Johanneksen, hänen veljensä, veneessä isänsä Sebedeuksen kanssa laittamassa verkkojaan kuntoon ja kutsui heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'He jättivät heti veneen ja isänsä ja seurasivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Hän kierteli kautta koko Galilean, opetti heidän synagogissaan, saarnasi valtakunnan evankeliumia ja paransi kaikkia tauteja ja kaikkea sairautta, mitä kansassa oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Maine levisi hänestä koko Syyriaan, ja hänen luokseen tuotiin kaikkia sairaita, monenlaisten tautien ja vaivojen rasittamia, riivattuja, kuunvaihetautisia ja halvaantuneita; ja hän paransi heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Häntä seurasi suuri kansan paljous Galileasta, Dekapolista, Jerusalemista, Juudeasta ja Jordanin toiselta puolen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Nähdessään kansanjoukot hän nousi vuorelle; ja kun hän oli istuutunut, hänen opetuslapsensa tulivat hänen luokseen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'ja hän avasi suunsa ja opetti heitä sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, '\"Autuaita ovat hengessä köyhät, sillä heidän on taivasten valtakunta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Autuaita ovat murheelliset, sillä he saavat lohdutuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Autuaita ovat hiljaiset, sillä he saavat periä maan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Autuaita ovat ne, joilla on vanhurskauden nälkä ja jano, sillä heidät ravitaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Autuaita ovat laupiaat, sillä he saavat laupeuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Autuaita ovat puhdassydämiset, sillä he saavat nähdä Jumalan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Autuaita ovat rauhantekijät, sillä heitä sanotaan Jumalan lapsiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Autuaita ovat ne, joita vanhurskauden tähden vainotaan, sillä heidän on taivasten valtakunta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Autuaita olette te, kun ihmiset minun tähteni teitä solvaavat, vainoavat ja valehdellen puhuvat teistä kaikenlaista pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Iloitkaa ja riemuitkaa, sillä teidän palkkanne on suuri taivaissa. Sillä samoin he vainosivat profeettoja, jotka olivat ennen teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Te olette maan suola, mutta jos suola käy mauttomaksi, millä se saadaan suolaiseksi? Se ei enää kelpaa mihinkään muuhun kuin pois heitettäväksi ja ihmisten tallattavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Te olette maailman valo. Ylhäällä vuorella oleva kaupunki ei voi olla piilossa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'eikä lamppua sytytetä ja panna vakan alle, vaan lampunjalkaan, ja loistamaan kaikille huoneessa oleville.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Samoin loistakoon teidän valonne ihmisten edessä, että he näkisivät hyvät tekonne ja ylistäisivät Isäänne, joka on taivaissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Älkää luulko, että olen tullut Lakia tai Profeettoja kumoamaan; en ole tullut kumoamaan, vaan täyttämään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Sillä totisesti sanon teille: kunnes taivas ja maa katoavat, laista ei katoa pieninkään kirjain, ei ainoakaan piirto, ennen kuin kaikki on tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Sen tähden joka purkaa yhdenkään näistä pienimmistä käskyistä ja sillä tavalla opettaa ihmisiä, kutsutaan pienimmäksi taivasten valtakunnassa, mutta joka niitä noudattaa ja niin opettaa, kutsutaan suureksi taivasten valtakunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Sillä sanon teille: ellei teidän vanhurskautenne ole paljon suurempi kuin kirjanoppineiden ja fariseusten, ette pääse taivasten valtakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Te olette kuulleet sanotuksi vanhoille: \'Älä tapa\', ja: \'Joka tappaa, se on ansainnut tuomion.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Mutta minä sanon teille: jokainen, joka vihastuu veljeensä, on ansainnut tuomion; ja joka sanoo veljelleen: \'Sinä kelvoton\', on ansainnut Suuren neuvoston tuomion; ja joka sanoo: \'Sinä hullu\', on ansainnut helvetin tulen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Sen tähden, jos tuot lahjaasi alttarille ja siellä muistat, että veljelläsi on jotakin sinua vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'jätä lahjasi siihen alttarin eteen, ja käy ensin sopimassa veljesi kanssa, ja tule sitten uhraamaan lahjasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Suostu pian sopimaan riitapuolesi kanssa, niin kauan kuin vielä olet hänen kanssaan tiellä, ettei riitapuolesi vetäisi sinua tuomarin eteen ja tuomari antaisi sinua oikeudenpalvelijalle, ja ettei sinua pantaisi vankilaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Totisesti sanon sinulle: sieltä et pääse, ennen kuin maksat viimeisenkin rovon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Te olette kuulleet sanotuksi: \'Älä tee huorin.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Mutta minä sanon teille: jokainen, joka katsoo naista himoiten häntä, on jo sydämessään tehnyt huorin hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Jos sinun oikea silmäsi viettelee sinua, repäise se pois ja heitä luotasi. Sillä sinulle on parempi, että yksi jäsenistäsi joutuu hukkaan, kuin että koko ruumiisi heitetään helvettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'Jos sinun oikea kätesi viettelee sinua, hakkaa se poikki ja heitä luotasi. Sillä sinulle on parempi, että yksi jäsenistäsi joutuu hukkaan, kuin että koko ruumiisi heitetään helvettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'On sanottu: \'Joka hylkää vaimonsa, antakoon hänelle erokirjan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Mutta minä sanon teille: jokainen, joka hylkää vaimonsa muun kuin huoruuden tähden, saattaa hänet tekemään huorin, ja joka nai hylätyn, tekee huorin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Vielä olette kuulleet sanotuksi vanhoille: \'Älä vanno väärin\', ja: \'Täytä Herralle valasi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Mutta minä sanon teille: älkää ensinkään vannoko, älkää taivaan kautta, sillä se on Jumalan valtaistuin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'älkääkä maan kautta, sillä se on hänen jalkojensa astinlauta, älkää myöskään Jerusalemin kautta, sillä se on suuren Kuninkaan kaupunki;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'äläkä vanno pääsi kautta, sillä sinä et voi yhtään hiusta tehdä valkeaksi etkä mustaksi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'vaan olkoon teidän puheenne: \'On, on\', tai: \'ei, ei.\' Se, mitä siihen lisätään, on pahasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Olette kuulleet sanotuksi: \'Silmä silmästä ja hammas hampaasta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Mutta minä sanon teille: älkää tehkö pahalle vastarintaa, vaan jos joku lyö sinua oikealle poskelle, käännä hänelle toinenkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'Jos joku tahtoo käydä kanssasi oikeutta ja ottaa paitasi, anna hänen saada viittasikin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'ja jos joku pakottaa sinua yhden virstan matkalle, kulje hänen kanssaan kaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Anna sille, joka sinulta anoo, äläkä käännä selkääsi sille, joka pyytää sinulta lainaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Olette kuulleet sanotuksi: \'Rakasta lähimmäistäsi ja vihaa vihollistasi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Mutta minä sanon teille: rakastakaa vihollisianne, siunatkaa niitä, jotka teitä kiroavat, tehkää hyvää niille, jotka teitä vihaavat, ja rukoilkaa niiden puolesta, jotka teitä parjaavat ja vainoavat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'että olisitte Isänne lapsia, joka on taivaissa. Sillä hän antaa aurinkonsa koittaa niin pahoille kuin hyvillekin, ja antaa sataa sekä väärille että vanhurskaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Jos te näet rakastatte niitä, jotka teitä rakastavat, mikä palkka teille on siitä tuleva? Eivätkö publikaanitkin tee samoin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'Jos osoitatte ystävällisyyttä ainoastaan veljillenne, mitä erinomaista siinä teette? Eivätkö pakanatkin tee samoin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Olkaa siis te täydelliset, niin kuin teidän Isänne taivaissa on täydellinen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, '\"Varokaa, ettette harjoita almujen antamista ihmisten edessä, että he teitä katselisivat, muuten ette saa palkkaa Isältänne, joka on taivaissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Sen tähden, kun annat almuja, älä soitata torvea edelläsi, kuten tekopyhät tekevät synagogissa ja kaduilla saadakseen ylistystä ihmisiltä. Totisesti minä sanon teille: he ovat saaneet palkkansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Vaan kun sinä annat almun, älköön vasen kätesi tietäkö, mitä oikea kätesi tekee,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'että almusi olisi salassa, ja Isäsi, joka salassa näkee, maksaa sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Kun rukoilette, älkää olko kuin tekopyhät; sillä mielellään he seisovat ja rukoilevat synagogissa ja katujen kulmissa, että ihmiset näkisivät heidät. Totisesti sanon teille: he ovat saaneet palkkansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Vaan sinä, kun rukoilet, mene kammioosi ja sulje ovesi ja rukoile Isääsi, joka on salassa, ja Isäsi, joka salassa näkee, maksaa sinulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Kun rukoilette, älkää tyhjiä hokeko kuin pakanat, jotka luulevat, että heitä heidän monisanaisuutensa tähden kuullaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Älkää siis olko heidän kaltaisiaan, sillä teidän Isänne kyllä tietää, mitä tarvitsette, ennen kuin te häneltä anottekaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Rukoilkaa siis te näin: Isä meidän, joka olet taivaissa! Pyhitetty olkoon sinun nimesi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'tulkoon sinun valtakuntasi; tapahtukoon sinun tahtosi myös maan päällä niin kuin taivaassa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'anna meille tänä päivänä jokapäiväinen leipämme;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'ja anna meille syntimme anteeksi, niin kuin mekin annamme anteeksi niille, jotka ovat meitä vastaan rikkoneet;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'äläkä saata meitä kiusaukseen, vaan päästä meidät pahasta, sillä sinun on valtakunta ja voima ja kunnia iankaikkisesti. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Sillä jos annatte anteeksi ihmisille heidän rikoksensa, niin taivaallinen Isänne myös antaa teille anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Mutta jos ette anna ihmisille anteeksi, myöskään teidän Isänne ei anna anteeksi teidän rikoksianne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Kun paastoatte, älkää olko synkkiä kuten tekopyhät, sillä he tekevät kasvonsa surkeiksi, että ihmiset näkisivät heidän paastoavan. Totisesti sanon teille: he ovat saaneet palkkansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Vaan kun sinä paastoat, voitele pääsi ja pese kasvosi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'etteivät paastoamistasi näkisi ihmiset, vaan Isäsi, joka on salassa; ja Isäsi, joka salassa näkee, maksaa sinulle julkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Älkää kootko itsellenne aarteita maan päälle, missä koi ja ruoste turmelevat ja missä varkaat murtautuvat sisään ja varastavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Vaan kootkaa itsellenne aarteita taivaaseen, missä ei koi eikä ruoste turmele ja missä varkaat eivät murtaudu sisään eivätkä varasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Sillä siellä, missä aarteesi on, on myös sydämesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'Silmä on ruumiin lamppu. Jos siis silmäsi on terve, koko ruumiisi on valaistu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Mutta jos silmäsi on sokea, koko ruumiisi on pimeä. Jos siis se valo, joka sinussa on, on pimeyttä, kuinka suuri onkaan pimeys!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Kukaan ei voi palvella kahta herraa, sillä hän on joko tätä vihaava ja toista rakastava tai tähän liittyvä ja toista halveksiva. Ette voi palvella Jumalaa ja mammonaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Sen tähden sanon teille: älkää murehtiko hengestänne, mitä söisitte tai mitä joisitte, älkääkä ruumiistanne, mitä päällenne pukisitte. Eikö henki ole enemmän kuin ruoka ja ruumis enemmän kuin vaatteet?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Katselkaa taivaan lintuja: eivät ne kylvä eivätkä leikkaa eivätkä kokoa aittoihin, ja teidän taivaallinen Isänne ruokkii ne. Ettekö te ole niitä paljoa suurempiarvoiset?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Kuka teistä voi murehtimisellaan lisätä ikäänsä edes yhden kyynärän verran?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Mitä te murehditte vaatteista? Katselkaa kedon liljoja, kuinka ne kasvavat: ne eivät tee työtä eivätkä kehrää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'Kuitenkin sanon teille: Salomo ei ollut kaikessa loistossaan niin vaatetettu kuin yksi niistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Jos siis Jumala näin vaatettaa kedon ruohon, joka tänään kasvaa ja huomenna heitetään uuniin, eikö paljoa ennemmin teitä, te vähäuskoiset?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Älkää siis murehtiko sanoen: \'Mitä syömme?\' tai: \'Mitä juomme?\' tai: \'Millä itsemme vaatetamme?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Sillä tätä kaikkea pakanat tavoittelevat. Taivaallinen Isänne kyllä tietää teidän kaikkea tätä tarvitsevan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Vaan etsikää ensin Jumalan valtakuntaa ja hänen vanhurskauttaan, niin kaikki tämä teille lisäksi annetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Älkää siis murehtiko huomisesta päivästä, sillä huominen päivä pitää murheen itsestään. Riittää kullekin päivälle oma vaivansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, '\"Älkää tuomitko, ettei teitä tuomittaisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Millä tuomiolla te näet tuomitsette, sillä teidät tuomitaan; ja millä mitalla te mittaatte, sillä teille mitataan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Kuinka näet rikan, joka on veljesi silmässä, mutta et huomaa parrua omassa silmässäsi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Tai kuinka saatat sanoa veljellesi: \'Anna, minä otan rikan silmästäsi\', ja katso, parru on omassa silmässäsi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Sinä tekopyhä, ota ensin parru omasta silmästäsi, ja sitten näet ottaa rikan veljesi silmästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Älkää antako pyhää koirille, älkääkä heittäkö helmiänne sikojen eteen, etteivät ne tallaisi niitä jalkoihinsa, kääntyisi ja repisi teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Anokaa, niin teille annetaan; etsikää, niin te löydätte; kolkuttakaa, niin teille avataan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Sillä jokainen anova saa, etsivä löytää, ja kolkuttavalle avataan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Vai kuka teistä on se ihminen, joka antaa pojalleen kiven, kun tämä pyytää häneltä leipää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'tai kun hän pyytää kalaa, antaako hän hänelle käärmeen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Jos siis te, jotka olette pahoja, osaatte antaa lapsillenne hyviä lahjoja, kuinka paljoa ennemmin teidän Isänne, joka on taivaissa, antaa hyvää niille, jotka sitä häneltä anovat!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Sen tähden, kaikki, mitä tahdotte ihmisten teille tekevän, tehkää myös te samoin heille, sillä tämä on Laki ja Profeetat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Menkää ahtaasta portista sisälle. Sillä se portti on avara ja tie leveä, joka vie kadotukseen, ja monta on, jotka siitä sisälle menevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Mutta se portti on ahdas ja tie kaita, joka vie elämään, ja harvat ovat ne, jotka sen löytävät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Varokaa vääriä profeettoja, jotka tulevat luoksenne lammasten vaatteissa, mutta sisältä ovat raatelevia susia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Heidän hedelmistään te tunnette heidät. Kootaanko orjantappuroista viinirypäleitä ja ohdakkeista viikunoita?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Näin jokainen hyvä puu tekee hyviä hedelmiä, mutta huono puu tekee pahoja hedelmiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Hyvä puu ei voi tuottaa pahoja hedelmiä eikä huono puu tuottaa hyviä hedelmiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Jokainen puu, joka ei tee hyvää hedelmää, hakataan pois ja heitetään tuleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Niin siis tunnette heidät heidän hedelmistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Ei jokainen, joka sanoo minulle: \'Herra, Herra!\', pääse taivasten valtakuntaan, vaan se, joka tekee Isäni tahdon, joka on taivaissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Moni sanoo minulle sinä päivänä: \'Herra, Herra, emmekö sinun nimesi kautta profetoineet, sinun nimesi kautta ajaneet ulos riivaajia ja sinun nimesi kautta tehneet monta voimallista tekoa?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Silloin lausun heille julki: \'En ole koskaan teitä tuntenut. Menkää pois minun luotani, te laittomuuden tekijät.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Sen tähden jokainen, joka kuulee nämä minun sanani ja noudattaa niitä, on verrattavissa viisaaseen mieheen, joka rakensi talonsa kalliolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'Satoi, virrat tulvivat, tuulet puhalsivat ja syöksyivät tuota taloa vastaan, mutta se ei sortunut, sillä se oli kalliolle perustettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Mutta jokainen, joka kuulee nämä minun sanani eikä tee niiden mukaan, on verrattavissa tyhmään mieheen, joka rakensi talonsa hiekalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'Satoi, virrat tulvivat, tuulet puhalsivat ja syöksyivät taloa vastaan, ja se luhistui, ja sen luhistuminen oli suuri.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Kun Jeesus lopetti nämä puheet, olivat kansanjoukot hämmästyksissään hänen opetuksestaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'sillä hän opetti heitä niin kuin se, jolla on valta, eikä niin kuin heidän kirjanoppineensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Kun hän astui alas vuorelta, häntä seurasi paljon kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Katso, tuli spitaalinen mies ja lankesi maahan hänen eteensä ja sanoi: \"Herra, jos tahdot, sinä voit minut puhdistaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Niin hän ojensi kätensä, kosketti häntä ja sanoi: \"Minä tahdon; puhdistu.\" Heti hän puhdistui spitaalistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Jeesus sanoi hänelle: \"Katso, ettet puhu tästä kenellekään, vaan mene ja näytä itsesi papille, ja uhraa lahja, jonka Mooses on säätänyt, todistukseksi heille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Kun hän oli saapunut Kapernaumiin, hänen luokseen tuli sadanpäällikkö ja rukoili häntä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'ja sanoi: \"Herra, palvelijani makaa kotona halvaantuneena ja on kovissa vaivoissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Hän sanoi hänelle: \"Minä tulen ja parannan hänet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Mutta sadanpäällikkö vastasi ja sanoi: \"Herra, en ole sen arvoinen, että tulisit kattoni alle, vaan sano ainoastaan sana ja palvelijani paranee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Sillä minäkin olen vallanalainen mies, ja minulla on sotilaita käskyni alla, ja sanon tälle: \'Mene\', ja hän menee, ja toiselle: \'Tule\', ja hän tulee, ja orjalleni: \'Tee tämä\', ja hän tekee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Kuultuaan tämän Jeesus ihmetteli ja sanoi niille, jotka häntä seurasivat: \"Totisesti sanon teille: en ole kenelläkään Israelissa tavannut näin suurta uskoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Mutta sanon teille: monet tulevat idästä ja lännestä ja aterioivat Aabrahamin, Iisakin ja Jaakobin kanssa taivasten valtakunnassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'mutta valtakunnan lapset heitetään ulkopuolelle pimeyteen. Siellä on oleva itku ja hammasten kiristys.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Jeesus sanoi sadanpäällikölle: \"Mene. Kuten olet uskonut, tapahtukoon sinulle.\" Palvelija parani sillä hetkellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Kun Jeesus tuli Pietarin kotiin, hän näki hänen anoppinsa makaavan kuumeessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Hän koski tämän käteen, ja kuume lähti hänestä, ja hän nousi ja palveli heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Illan tultua hänen luokseen tuotiin monta riivattua. Hän ajoi henget ulos sanalla, ja kaikki sairaat hän paransi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'jotta kävisi toteen, mikä on puhuttu profeetta Jesajan kautta, joka sanoo: \"Hän otti päälleen sairautemme ja kantoi tautimme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Mutta kun Jeesus näki paljon kansaa ympärillään, hän käski lähteä toiselle rannalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Eräs kirjanoppinut tuli ja sanoi hänelle: \"Opettaja, minä seuraan sinua, minne menetkin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Jeesus sanoi hänelle: \"Ketuilla on luolat ja taivaan linnuilla pesät, mutta Ihmisen Pojalla ei ole, mihin hän päänsä kallistaisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Eräs toinen hänen opetuslapsistaan sanoi hänelle: \"Herra, salli minun ensin käydä hautaamassa isäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Mutta Jeesus sanoi hänelle: \"Seuraa minua, ja anna kuolleiden haudata kuolleensa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Astuttuaan veneeseen hänen opetuslapsensa seurasivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'Katso, järvellä tapahtui suuri järistys, niin että vene peittyi aaltoihin, mutta hän nukkui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Hänen opetuslapsensa menivät hänen luokseen ja herättivät hänet sanoen: \"Herra, pelasta meidät, me hukumme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Hän sanoi heille: \"Te vähäuskoiset, miksi olette pelkureita?\" Silloin hän nousi ja nuhteli tuulia ja järveä, ja tuli täysin tyyntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Ihmiset ihmettelivät ja sanoivat: \"Millainen tämä on, kun sekä tuulet että meri häntä tottelevat?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Kun hän tuli toiselle rannalle, gadaralaisten alueelle, häntä vastaan tuli kaksi pahojen henkien vaivaamaa, jotka olivat lähteneet haudoista ja olivat kovin raivoisia, niin ettei kukaan voinut kulkea sitä tietä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'Katso, he huusivat sanoen: \"Mitä sinulla on meidän kanssamme tekemistä, sinä Jumalan Poika? Oletko tullut tänne vaivaamaan meitä ennen aikaa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Etäällä heistä oli suuri sikalauma laitumella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Niin riivaajat pyysivät häntä sanoen: \"Jos ajat meidät pois, lähetä meidät sikalaumaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Hän sanoi niille: \"Menkää.\" Silloin ne lähtivät heistä ja menivät sikoihin. Katso, koko lauma syöksyi jyrkännettä alas järveen ja hukkui veteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Mutta paimentajat pakenivat, menivät kaupunkiin ja ilmoittivat kaiken, myös sen, miten riivattujen oli käynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Katso, koko kaupunki lähti tapaamaan Jeesusta ja kun he näkivät hänet, he kehottivat häntä poistumaan alueeltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Sitten hän astui veneeseen, meni jälleen toiselle rannalle ja tuli omaan kaupunkiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Katso, hänen luokseen tuotiin halvaantunut mies, joka makasi vuoteella. Kun Jeesus näki heidän uskonsa, hän sanoi halvaantuneelle: \"Poikani, ole turvallisella mielellä; sinun syntisi ovat sinulle anteeksiannetut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Katso, muutamat kirjanoppineista sanoivat mielessään: \"Tämä pilkkaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Mutta Jeesus ymmärsi heidän ajatuksensa ja sanoi: \"Miksi ajattelette pahaa sydämessänne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Sillä kumpi on helpompaa sanoa: \'Syntisi ovat sinulle anteeksiannetut\', vai sanoa: \'Nouse ja kävele\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Mutta tietääksenne, että Ihmisen Pojalla on valta maan päällä antaa synnit anteeksi, niin\" – hän sanoi halvaantuneelle – \"nouse, ota vuoteesi ja mene kotiisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Hän nousi ja lähti kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Mutta kun kansanjoukot sen näkivät, he ihmettelivät ja ylistivät Jumalaa, joka oli antanut sellaisen vallan ihmisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Kulkiessaan siitä ohi Jeesus näki miehen, jonka nimi oli Matteus, istumassa tulliasemalla ja sanoi hänelle: \"Seuraa minua.\" Noustuaan tämä seurasi häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Hänen aterioidessaan tämän kodissa tapahtui, katso, että tuli monta publikaania ja syntistä, ja he aterioivat Jeesuksen ja hänen opetuslastensa kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Kun fariseukset näkivät sen, he sanoivat hänen opetuslapsilleen: \"Miksi opettajanne syö publikaanien ja syntisten kanssa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Mutta kun Jeesus sen kuuli, hän sanoi: \"Terveet eivät tarvitse parantajaa, vaan sairaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Mutta menkää ja oppikaa, mitä tämä on: \'Laupeutta minä tahdon enkä uhria.\' Sillä en ole tullut kutsumaan vanhurskaita, vaan syntisiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Silloin Johanneksen opetuslapset tulivat hänen luokseen ja sanoivat: \"Miksi me ja fariseukset paastoamme paljon, mutta sinun opetuslapsesi eivät paastoa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Niin Jeesus sanoi heille: \"Eiväthän häävieraat voi surra, niin kauan kuin ylkä on heidän kanssaan? Mutta päivät tulevat, jolloin ylkä otetaan heiltä pois, ja silloin he paastoavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Ei kukaan pane vanuttamattomasta kankaasta paikkaa vanhaan viittaan, sillä sellainen täytetilkku repii palan viitasta, ja reikä tulee pahemmaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Eikä nuorta viiniä lasketa vanhoihin leileihin. Muuten leilit halkeavat, ja viini vuotaa pois, ja leilit turmeltuvat. Nuori viini sitä vastoin lasketaan uusiin leileihin, ja [silloin] molemmat säilyvät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Kun hän tätä heille puhui, katso, eräs [synagogan] esimies tuli ja kumartui maahan hänen eteensä ja sanoi: \"Tyttäreni kuoli juuri äsken, mutta tule ja pane kätesi hänen päälleen, niin hän virkoaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Jeesus nousi ja seurasi häntä opetuslapsineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'Katso, nainen, joka oli sairastanut verenvuotoa kaksitoista vuotta, tuli takaapäin ja kosketti hänen viittansa tupsua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'Sillä hän sanoi itsekseen: \"Jos vain saan koskettaa hänen viittaansa, tulen terveeksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Jeesus kääntyi, näki hänet ja sanoi: \"Tyttäreni, ole turvallisin mielin; uskosi on tehnyt sinut terveeksi.\" Sillä hetkellä nainen tuli terveeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Kun Jeesus tuli esimiehen taloon ja näki huilunsoittajat ja hälisevän väkijoukon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'hän sanoi: \"Menkää pois, sillä tyttö ei ole kuollut, vaan nukkuu.\" Mutta he nauroivat hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Kun väkijoukko oli ajettu ulos, hän meni sisälle ja tarttui hänen käteensä; ja tyttö nousi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Sanoma tästä levisi koko sille seudulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Kun Jeesus kulki sieltä, häntä seurasi kaksi sokeaa huutaen ja sanoen: \"Daavidin poika, armahda meitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Hänen mentyään taloon sokeat tulivat hänen luokseen, ja Jeesus sanoi heille: \"Uskotteko, että voin sen tehdä?\" He sanoivat hänelle: \"Uskomme, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Silloin hän kosketti heidän silmiään ja sanoi: \"Tapahtukoon teille uskonne mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'Heidän silmänsä aukenivat, ja Jeesus varoitti heitä vakavasti sanoen: \"Katsokaa, ettei kukaan saa tästä tietää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Mutta he menivät pois ja levittivät hänen mainettaan koko sille seudulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Katso, näiden lähdettyä tuotiin hänen luokseen mykkä mies, jossa oli riivaaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Kun riivaaja oli ajettu ulos, mykkä puhui, ja kansa ihmetteli sanoen: \"Tällaista ei ole Israelissa koskaan ilmennyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Mutta fariseukset sanoivat: \"Riivaajien päämiehen voimalla hän ajaa ulos riivaajia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Jeesus vaelsi kaikki kaupungit ja kylät, opetti heidän synagogissaan, saarnasi valtakunnan evankeliumia ja paransi kaikkia tauteja ja kaikenlaista sairautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Nähdessään kansanjoukot hänen tuli heitä sääli, kun he olivat nääntyneet ja hylätyt kuin lampaat, joilla ei ole paimenta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Silloin hän sanoi opetuslapsilleen: \"Eloa on paljon, mutta työmiehiä vähän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Rukoilkaa siis elon Herraa, että hän lähettäisi työmiehiä elonkorjuuseensa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Hän kutsui ne kaksitoista opetuslastaan ja antoi heille vallan ajaa ulos saastaisia henkiä ja parantaa kaikenlaisia tauteja ja kaikenlaista sairautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Nämä ovat niiden kahdentoista apostolin nimet: ensimmäinen oli Simon, jota kutsuttiin Pietariksi, ja Andreas, hänen veljensä, sitten Jaakob Sebedeuksen poika, ja Johannes, hänen veljensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Filippos ja Bartolomeos, Tuomas ja Matteus, publikaani, Jaakob, Alfeoksen poika, ja Lebbeus, lisänimeltä Taddeus,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon Kananeus ja Juudas Iskariot, sama, joka hänet kavalsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Nämä kaksitoista Jeesus lähetti ja käski heitä sanoen: \"Älköön tienne viekö pakanoiden luo, älkääkä menkö samarialaisten kaupunkiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'vaan menkää ennemmin Israelin huoneen kadonneiden lammasten luo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'ja kulkiessanne saarnatkaa ja sanokaa: \'Taivasten valtakunta on tullut lähelle.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Parantakaa sairaita, puhdistakaa spitaalisia, herättäkää kuolleita, ajakaa ulos pahoja henkiä. Lahjaksi olette saaneet, lahjaksi antakaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Älkää varustako itsellenne kultaa, älkää hopeaa älkääkä vaskea vyöhönne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'älkää laukkua matkalle, älkää kahta paitaa, älkää sandaaleja älkääkä sauvaa; sillä työmies on ruokansa arvoinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Ja mihin kaupunkiin tai kylään tulettekin, tutkikaa, kuka siellä on kelvollinen, ja jääkää hänen luokseen, kunnes sieltä lähdette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Tullessanne taloon tervehtikää sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Jos talo on kelvollinen, tulkoon sille rauhanne, mutta jos se ei ole kelvollinen, palatkoon rauhanne teille takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Missä teitä ei oteta vastaan eikä teidän sanojanne kuulla, lähtekää pois siitä talosta tai siitä kaupungista ja pudistakaa tomu jaloistanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Totisesti sanon teille: Sodoman ja Gomorran maan on tuomiopäivänä oleva helpompi kuin sen kaupungin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Katso, minä lähetän teidät kuin lampaat susien keskelle; olkaa siis älykkäitä kuin käärmeet ja viattomia kuin kyyhkyset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Kavahtakaa ihmisiä, sillä he jättävät teidät tuomioistuimiin, ja synagogissaan he teitä ruoskivat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'ja teitä viedään maaherrojen ja kuningasten eteen minun tähteni todistukseksi heille ja pakanoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Mutta kun he jättävät teidät oikeuteen, älkää murehtiko, miten tai mitä puhuisitte, sillä teille annetaan sillä hetkellä, mitä puhutte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Sillä ette te itse puhu, vaan Isänne Henki puhuu teissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Veli antaa veljensä kuolemaan ja isä lapsensa, ja lapset nousevat vanhempiaan vastaan ja tappavat heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'Te olette kaikkien vihaamia minun nimeni tähden, mutta joka kestää loppuun asti, se pelastuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Kun teitä vainotaan yhdessä kaupungissa, paetkaa toiseen, sillä totisesti sanon teille: te ette ehdi saada työtänne päätökseen kaikissa Israelin kaupungeissa, ennen kuin Ihmisen Poika tulee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Opetuslapsi ei ole opettajaansa parempi, eikä palvelija parempi isäntäänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Opetuslapselle riittää, että hänelle käy kuin hänen opettajalleen, ja palvelijalle, että hänelle käy kuin hänen isännälleen. Jos he ovat sanoneet isäntää beelsebubiksi, kuinka paljoa ennemmin hänen perheväkeään!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Älkää siis pelätkö heitä. Sillä ei ole mitään peitettyä, mikä ei tule paljastetuksi, eikä mitään salattua, mikä ei tule tunnetuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Minkä sanon teille pimeässä, se puhukaa valossa. Minkä kuulette korvaanne puhuttavan, se julistakaa katoilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Älkääkä pelätkö niitä, jotka tappavat ruumiin, mutta eivät voi tappaa sielua, vaan ennemmin pelätkää häntä, joka voi sekä sielun että ruumiin hukuttaa helvettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Eikö kahta varpusta myydä yhteen ropoon? Eikä yksikään niistä putoa maahan ilman Isäänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Ovatpa kaikki päänne hiuksetkin luetut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Älkää siis pelätkö; te olette suurempiarvoiset kuin monta varpusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Sen tähden, jokaisen, joka tunnustaa minut ihmisten edessä, minäkin tunnustan Isäni edessä, joka on taivaissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Mutta sen, joka kieltää minut ihmisten edessä, minäkin kiellän Isäni edessä, joka on taivaissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Älkää luulko, että olen tullut tuomaan rauhaa maan päälle; en ole tullut tuomaan rauhaa, vaan miekan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Sillä olen tullut \'nostamaan pojan riitaan isäänsä vastaan ja tyttären äitiään vastaan ja miniän anoppiaan vastaan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'ja ihmisen vihamiehiksi tulevat hänen omat perhekuntalaisensa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Se, joka rakastaa isäänsä tai äitiään enemmän kuin minua, ei ole minulle kelvollinen; ja se, joka rakastaa poikaansa tai tytärtään enemmän kuin minua, ei ole minulle kelvollinen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'ja se, joka ei ota ristiään ja seuraa minua, ei ole minulle kelvollinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Se, joka löytää elämänsä, kadottaa sen, ja se, joka kadottaa elämänsä minun tähteni, löytää sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Se, joka ottaa luokseen teidät, ottaa luokseen minut; ja se, joka ottaa luokseen minut, ottaa luokseen hänet, joka on minut lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Se, joka ottaa profeetan luokseen profeetan nimen tähden, saa profeetan palkan, ja se, joka ottaa vanhurskaan luokseen vanhurskaan nimen tähden, saa vanhurskaan palkan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Kuka hyvänsä antaa yhdelle näistä pienistä maljallisen kylmää vettä hänen juodakseen opetuslapsen nimen tähden, totisesti sanon teille: hän ei kadota palkkaansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Sitten kun Jeesus oli antanut kahdelletoista opetuslapselleen kaikki nämä käskyt, hän lähti sieltä opettamaan ja saarnaamaan heidän kaupunkeihinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Mutta kun Johannes vankilassa ollessaan kuuli Kristuksen teot, hän lähetti kaksi opetuslastaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'sanomaan hänelle: \"Oletko sinä se tuleva, vai odotammeko toista?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Jeesus vastasi ja sanoi heille: \"Menkää ja kertokaa Johannekselle, mitä kuulette ja näette:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'sokeat saavat näkönsä, rammat kävelevät, spitaaliset puhdistuvat, kuurot kuulevat, kuolleita herätetään, ja köyhille julistetaan evankeliumia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'Autuas on se, joka ei loukkaannu minuun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Kun he olivat menneet, Jeesus alkoi puhua kansalle Johanneksesta: \"Mitä lähditte erämaahan katselemaan? Ruokoako, jota tuuli huojuttaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Vai mitä lähditte katsomaan? Ihmistäkö, hienoihin vaatteisiin pukeutunutta? Katso, hienopukuiset ovat kuningasten taloissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Vai mitä te lähditte katsomaan? Profeettaako? Totisesti, minä sanon teille: hän on enemmän kuin profeetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Sillä hän on se, josta on kirjoitettu: \'Katso, minä lähetän enkelini edelläsi, ja hän on valmistava tiesi sinun eteesi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Totisesti sanon teille: ei ole vaimoista syntyneiden joukosta noussut suurempaa kuin Johannes Kastaja, mutta vähäisin taivasten valtakunnassa on suurempi kuin hän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Mutta Johannes Kastajan päivistä tähän asti hyökätään taivasten valtakuntaa vastaan, ja hyökkääjät tempaavat sen itselleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Sillä kaikki Profeetat ja Laki ovat ennustaneet Johannekseen asti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'mutta jos tahdotte ottaa vastaan: hän on Elia, joka oli tuleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Jolla on korvat, se kuulkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Mutta mihin vertaan tämän sukupolven? Se on lasten kaltainen, jotka istuvat toreilla ja huutavat toisilleen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'sanoen: \'Soitimme teille huilua, ettekä karkeloineet, veisasimme itkuvirsiä, ettekä valittaneet.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Sillä Johannes tuli, hän ei syö eikä juo, ja he sanovat: \'Hänessä on riivaaja.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Ihmisen Poika tuli, hän syö ja juo, ja he sanovat: \'Katso ylensyöjää ja viininjuojaa, publikaanien ja syntisten ystävää!\' Mutta Viisauden lapset julistavat hänet vanhurskaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Sitten hän rupesi nuhtelemaan niitä kaupunkeja, joissa useimmat hänen voimalliset tekonsa olivat tapahtuneet, siitä, etteivät ne olleet muuttaneet mieltään:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, '\"Voi sinua, Korasin! Voi sinua, Beetsaida! Sillä jos ne voimalliset teot, jotka ovat tapahtuneet teissä, olisivat tapahtuneet Tyyrossa ja Siidonissa, nämä jo aikaa sitten olisivat säkissä ja tuhkassa muuttaneet mielensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Mutta sanon teille: Tyyron ja Siidonin on tuomiopäivänä oleva helpompi kuin teidän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Sinä, Kapernaum, korotetaankohan sinut taivaaseen? Helvettiin sinun on astuttava alas. Sillä jos ne voimalliset teot, jotka ovat tapahtuneet sinussa, olisivat tapahtuneet Sodomassa, se seisoisi vielä tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Kuitenkin sanon teille: Sodoman maan on tuomiopäivänä oleva helpompi kuin sinun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'Siihen aikaan Jeesus vielä puhui ja sanoi: \"Ylistän sinua, Isä, taivaan ja maan Herra, että olet salannut nämä viisailta ja ymmärtäväisiltä ja ilmoittanut ne lapsenmielisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Niin, Isä, sillä näin on ollut otollista sinun edessäsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Kaiken on Isäni antanut minun haltuuni, eikä kukaan muu tunne Poikaa kuin Isä, eikä Isää tunne kukaan muu kuin Poika ja se, kenelle Poika tahtoo hänet ilmoittaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Tulkaa minun tyköni, kaikki työtätekevät ja taakkojen kantajat, niin minä annan teille levon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Ottakaa minun ikeeni päällenne ja oppikaa minusta, sillä olen lempeä ja nöyrä sydämeltä, niin löydätte levon sieluillenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Sillä minun ikeeni on hyvä, ja minun taakkani on kevyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'Siihen aikaan Jeesus kulki sapattina viljavainioiden halki, ja hänen opetuslapsillaan oli nälkä, ja he rupesivat poimimaan tähkiä ja syömään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Mutta kun fariseukset sen näkivät, he sanoivat hänelle: \"Katso, opetuslapsesi tekevät, mitä ei ole lupa tehdä sapattina.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Hän sanoi heille: \"Ettekö ole lukeneet, mitä Daavid teki, kun hänellä ja hänen tovereillaan oli nälkä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'kuinka hän meni Jumalan huoneeseen, ja kuinka he söivät näkyleivät, joita ei hänen eikä hänen toveriensa ollut lupa syödä, vaan ainoastaan pappien?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Tai ettekö ole lukeneet Laista, että papit sapattina pyhäkössä rikkovat sapatin ja ovat kuitenkin syyttömiä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Mutta sanon teille: tässä on se, joka on enemmän kuin pyhäkkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Mutta jos tietäisitte, mitä tämä on: \'Laupeutta minä tahdon enkä uhria\', ette tuomitsisi syyttömiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Sillä Ihmisen Poika on sapatinkin herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Sitten hän lähti sieltä ja tuli heidän synagogaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Katso, siellä oli mies, jonka käsi oli kuivettunut. Niin he kysyivät häneltä sanoen: \"Onko luvallista parantaa sapattina?\" nostaakseen syytteen häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Mutta hän sanoi heille: \"Kuka teistä on se mies, joka ei, jos hänen ainoa lampaansa putoaa sapattina kuoppaan, tartu siihen ja nosta sitä ylös?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Kuinka paljon suurempiarvoinen onkaan ihminen kuin lammas! Sen tähden sapattina on lupa tehdä hyvää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Sitten hän sanoi miehelle: \"Ojenna kätesi!\" Ja hän ojensi, ja se tuli entiselleen, terveeksi kuten toinenkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Niin fariseukset lähtivät ulos ja pitivät neuvoa häntä vastaan surmatakseen hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Mutta kun Jeesus huomasi sen, hän väistyi sieltä. Monet seurasivat häntä, ja hän paransi heidät kaikki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'Hän varoitti vakavasti heitä tuomasta häntä julki,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'jotta kävisi toteen, mikä on puhuttu profeetta Jesajan kautta, joka sanoo:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, '\"Katso, palvelijani, jonka olen valinnut, rakkaani, johon sieluni on mielistynyt; panen Henkeni hänen päälleen, ja hän on julistava oikeutta pakanoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Ei hän riitele eikä huuda, ei hänen ääntänsä kuule kukaan kaduilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Särjettyä ruokoa hän ei muserra, ja suitsevaa lampunsydäntä hän ei sammuta, kunnes hän saattaa oikeuden voittoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'Hänen nimeensä pakanat panevat toivonsa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Silloin tuotiin hänen luokseen riivattu mies, sokea ja mykkä, ja hän paransi hänet, niin että sokea ja mykkä sekä puhui että näki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'Kaikki kansa hämmästyi ja sanoi: \"Eiköhän tämä ole Daavidin poika?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Mutta kun fariseukset sen kuulivat, he sanoivat: \"Tämä ei aja riivaajia ulos kenenkään muun kuin Beelsebulin, riivaajien päämiehen, voimalla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Mutta hän tiesi heidän ajatuksensa ja sanoi heille: \"Jokainen valtakunta, joka riitautuu itsensä kanssa, joutuu autioksi, eikä mikään kaupunki tai talo, joka riitautuu itsensä kanssa, pysy pystyssä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Jos nyt saatana ajaa ulos saatanan, hän on riitautunut itsensä kanssa, kuinka siis hänen valtakuntansa pysyy pystyssä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'Jos minä Beelsebulilla ajan ulos riivaajia, kenellä teidän lapsenne ajavat niitä ulos? Niinpä he tulevat olemaan teidän tuomarinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Mutta jos minä Jumalan Hengellä ajan ulos riivaajia, silloin Jumalan valtakunta on tullut teidän luoksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Tai miten kukaan voi mennä väkevän taloon ja ryöstää hänen tavaransa, ellei hän ensin sido väkevää? Vasta sitten hän ryöstää tyhjäksi hänen talonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Se, joka ei ole minun kanssani, on minua vastaan; ja joka ei kanssani kokoa, se hajottaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Sen tähden sanon teille: jokainen synti ja pilkka annetaan ihmisille anteeksi, mutta Hengen pilkkaa ei anneta anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Jos joku sanoo sanan Ihmisen Poikaa vastaan, hänelle annetaan anteeksi, mutta jos joku sanoo jotakin Pyhää Henkeä vastaan, hänelle ei anneta anteeksi, ei tässä maailmassa eikä tulevassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Joko tehkää puu hyväksi ja sen hedelmä hyväksi, tai tehkää puu huonoksi ja sen hedelmä huonoksi; sillä hedelmästä puu tunnetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Te kyykäärmeitten sikiöt, kuinka saattaisitte puhua hyvää, kun itse olette pahoja? Sillä sydämen kyllyydestä suu puhuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'Hyvä ihminen tuo hyvän runsaudesta esille hyvää, ja paha ihminen tuo pahan runsaudesta esille pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Mutta sanon teille: jokaisesta turhasta sanasta, minkä ihmiset puhuvat, heidän pitää tehdä tili tuomiopäivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Sillä sanoistasi sinut julistetaan vanhurskaaksi, ja sanoistasi sinut tuomitaan syylliseksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Silloin muutamat kirjanoppineista ja fariseuksista vastasivat hänelle sanoen: \"Opettaja, tahdomme nähdä sinulta merkin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Mutta hän vastasi heille ja sanoi: \"Tämä paha ja avion rikkova sukupolvi etsii merkkiä, mutta sille ei anneta muuta merkkiä kuin profeetta Joonan merkki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Sillä niin kuin Joona oli merieläimen vatsassa kolme päivää ja kolme yötä, niin myös Ihmisen Poika on oleva maan povessa kolme päivää ja kolme yötä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Niiniven miehet nousevat tuomiolle yhdessä tämän sukupolven kanssa ja tuomitsevat sen kadotukseen, sillä he muuttivat mielensä Joonan saarnan vaikutuksesta, ja katso, tässä on enemmän kuin Joona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Etelän kuningatar on heräävä tuomiolle tämän sukupolven kanssa ja tuomitsee sen kadotukseen; sillä hän tuli maan ääristä kuulemaan Salomon viisautta, ja katso, tässä on enemmän kuin Salomo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Kun saastainen henki lähtee ihmisestä, se kuljeskelee vedettömiä seutuja ja etsii lepoa eikä löydä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Silloin se sanoo: \'Palaan huoneeseeni, josta lähdin.\' Kun se tulee, se löytää huoneen tyhjänä ja lakaistuna ja kaunistettuna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Silloin se menee ja ottaa mukaansa seitsemän muuta henkeä, pahempaa kuin se itse, ja ne tulevat sisään ja asuvat siellä. Sen ihmisen viimeiset tulevat pahemmiksi kuin ensimmäiset. Niin käy myös tälle pahalle sukukunnalle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Hänen vielä puhuessaan kansanjoukoille, katso, hänen äitinsä ja veljensä seisoivat ulkona tahtoen puhutella häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'Joku sanoi hänelle: \"Katso, sinun äitisi ja veljesi seisovat ulkona ja tahtovat puhutella sinua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Mutta hän vastasi ja sanoi sille, joka sen hänelle sanoi: \"Kuka on äitini, ja keitä ovat veljeni?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'Hän ojensi kätensä opetuslastensa puoleen ja sanoi: \"Katso, äitini ja veljeni!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Sillä jokainen, joka tekee taivaallisen Isäni tahdon, on veljeni, sisareni ja äitini.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Tuona päivänä Jeesus lähti asunnostaan ja istuutui järven rannalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'Hänen luokseen kokoontui paljon kansaa. Sen tähden hän astui veneeseen ja istuutui, ja kaikki kansa seisoi rannalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Hän puhui heille paljon vertauksilla ja sanoi: \"Katso, kylväjä lähti kylvämään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'Hänen kylväessään muutamat siemenet putosivat tien viereen, ja linnut tulivat ja söivät ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Toiset putosivat kallioperälle, jossa niillä ei ollut paljon maata, ja ne nousivat heti oraalle, kun niillä ei ollut syvää maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Mutta auringon noustua ne paahtuivat, ja kun niillä ei ollut juurta, ne kuivuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Toiset taas putosivat orjantappuroihin, ja orjantappurat nousivat ja tukahduttivat ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Toiset putosivat hyvään maahan ja antoivat sadon, mitkä sata, mitkä kuusikymmentä, mitkä kolmekymmentä jyvää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Jolla on korvat, se kuulkoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Hänen opetuslapsensa tulivat ja sanoivat hänelle: \"Minkä tähden sinä puhut heille vertauksilla?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Hän vastasi ja sanoi: \"Sen tähden, että teidän on annettu tuntea taivasten valtakunnan salaisuudet, mutta heidän ei ole annettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Sillä sille, jolla on, annetaan, ja hänellä on oleva yltäkyllin, mutta siltä, jolla ei ole, otetaan pois sekin, mikä hänellä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Sen tähden puhun heille vertauksilla, jotta näkevät eivät näe ja kuulevat eivät kuule eivätkä ymmärrä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Heille toteutuu Jesajan ennustus, joka sanoo: \'Kuulemalla kuulkaa, älkääkä ymmärtäkö, ja näkemällä nähkää, älkääkä käsittäkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Sillä paatunut on tämän kansan sydän, ja korvillaan he haluttomasti kuulevat, ja silmänsä he ovat ummistaneet, etteivät näkisi silmillään, eivät kuulisi korvillaan, eivät ymmärtäisi sydämellään eivätkä kääntyisi ja etten heitä parantaisi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Mutta autuaat ovat teidän silmänne, koska ne näkevät, ja korvanne, koska ne kuulevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Sillä totisesti sanon teille: monet profeetat ja vanhurskaat ovat halunneet nähdä, mitä näette, eivätkä ole nähneet, ja kuulla, mitä kuulette, eivätkä ole kuulleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Kuulkaa te siis vertaus kylväjästä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Kun joku kuulee valtakunnan sanan eikä ymmärrä, niin paholainen tulee ja tempaa sen pois, mikä hänen sydämeensä kylvettiin. Tämä on se, mikä kylvettiin tien viereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Mikä kallioperälle kylvettiin, on se, joka kuulee sanan ja heti ottaa sen ilolla vastaan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'mutta hänellä ei ole juurta itsessään, vaan hän kestää vain jonkin aikaa, ja kun tulee ahdistus tai vaino sanan tähden, hän heti lankeaa pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Mikä taas orjantappuroihin kylvettiin, on se, joka kuulee sanan, mutta tämän maailman huoli ja rikkauden petollisuus tukahduttavat sanan, ja hän tulee hedelmättömäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Mutta mikä hyvään maahan kylvettiin, on se, joka kuulee sanan, ymmärtää sen ja myös kantaa hedelmää ja tekee, mikä sata jyvää, mikä kuusikymmentä, mikä kolmekymmentä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Toisen vertauksen hän esitti heille sanoen: \"Taivasten valtakunta on miehen kaltainen, joka kylvi hyvän siemenen peltoonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Mutta ihmisten nukkuessa hänen vihamiehensä tuli ja kylvi juolavehnää vehnän joukkoon ja meni pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Kun laiho kasvoi ja teki hedelmää, silloin juolavehnäkin tuli näkyviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Perheenisännän palvelijat tulivat ja sanoivat hänelle: \'Herra, etkö kylvänyt peltoosi hyvää siementä? Mistä siihen on tullut juolavehnää?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Hän sanoi heille: \'Sen on vihamies tehnyt.\' Niin palvelijat sanoivat hänelle: \'Tahdotko, että menemme ja kokoamme sen?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Mutta hän sanoi: \'En, ettette juolavehnää kootessanne repisi sen mukana vehnääkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Antakaa molempien kasvaa yhdessä elonleikkuuseen asti; ja elonaikana sanon leikkaajille: Kootkaa ensin juolavehnä ja sitokaa se kimppuihin poltettavaksi, mutta vehnä korjatkaa minun aittaani.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Vielä toisen vertauksen hän esitti heille sanoen: \"Taivasten valtakunta on sinapinsiemenen kaltainen, jonka mies otti ja kylvi peltoonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'Se on kaikista kylvösiemenistä pienin, mutta kun se on kasvanut, se on suurin puutarhakasveista ja tulee puuksi, niin että taivaan linnut tulevat ja tekevät pesänsä sen oksille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Hän puhui heille vertauksen: \"Taivasten valtakunta on hapatteen kaltainen, jonka nainen otti ja sekoitti kolmeen vakalliseen jauhoja, kunnes kaikki happani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Tämän kaiken Jeesus puhui kansalle vertauksilla, ja ilman vertausta hän ei heille puhunut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'jotta kävisi toteen, mikä on puhuttu profeetan kautta, joka sanoo: \"Minä avaan suuni vertauksiin, julistan sen, mikä on ollut salassa maailman perustamisesta asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Sitten hän laski kansan luotaan ja meni asuntoonsa, ja hänen opetuslapsensa tulivat hänen luokseen ja sanoivat: \"Selitä meille vertaus pellon juolavehnästä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Niin hän vastasi ja sanoi: \"Hyvän siemenen kylväjä on Ihmisen Poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'Pelto on maailma; mutta hyvä siemen on valtakunnan lapsia, juolavehnät taas ovat paholaisen lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'Vihamies, joka ne kylvi, on perkele, elonkorjuu on maailman loppu, ja leikkaajat ovat enkeleitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Kuten juolavehnät kootaan ja tulessa poltetaan, niin tapahtuu maailman lopussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Ihmisen Poika lähettää enkelinsä, ja he kokoavat hänen valtakunnastaan kaikki, jotka ovat pahennukseksi ja tekevät laittomuutta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'ja heittävät heidät tuliseen uuniin; siellä on oleva itku ja hammasten kiristys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Silloin vanhurskaat loistavat Isänsä valtakunnassa kuin aurinko. Jolla on korvat, kuulkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Taivasten valtakunta on peltoon kätketyn aarteen kaltainen, jonka mies löysi ja kätki. Siitä iloissaan hän meni ja myi kaikki, mitä hänellä oli, ja osti pellon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Vielä taivasten valtakunta on kuin kauppias, joka etsi kalliita helmiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'ja löydettyään yhden kallisarvoisen helmen hän meni ja myi kaikki, mitä hänellä oli, ja osti sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Vielä taivasten valtakunta on nuotan kaltainen, joka heitettiin mereen, ja se kokosi kaikkia kaloja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Kun se tuli täyteen, he vetivät sen rannalle, istuutuivat ja kokosivat hyvät astioihin, mutta kelvottomat he heittivät pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Näin on maailman lopussa: enkelit lähtevät ja erottavat pahat vanhurskaista');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'ja heittävät heidät tuliseen uuniin. Siellä on oleva itku ja hammasten kiristys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Oletteko ymmärtäneet tämän kaiken?\" He vastasivat hänelle: \"Olemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Hän sanoi heille: \"Niin jokainen kirjanoppinut, josta on tullut taivasten valtakunnan opetuslapsi, on perheenisännän kaltainen, joka tuo aarrekammiostaan esille uutta ja vanhaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Tapahtui, että lopetettuaan nämä vertaukset Jeesus lähti sieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'Hän tuli kotikaupunkiinsa ja opetti heitä heidän synagogassaan, niin että he hämmästyivät ja sanoivat: \"Mistä hänellä on tämä viisaus ja nämä voimateot?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Eikö tämä ole se rakentajan poika? Eikö hänen äitinsä ole nimeltään Maria ja hänen veljensä Jaakob, Joosef, Simon ja Juudas?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Eivätkö hänen sisarensa ole kaikki meidän luonamme? Mistä sitten hänellä on tämä kaikki?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'He loukkaantuivat häneen. Mutta Jeesus sanoi heille: \"Profeetta ei ole halveksittu muualla kuin kotikaupungissaan ja kodissaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Mutta hän ei tehnyt siellä monta voimatekoa heidän epäuskonsa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'Siihen aikaan neljännesruhtinas Herodes kuuli puhuttavan Jeesuksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'Hän sanoi palvelijoilleen: \"Se on Johannes Kastaja. Hän on noussut kuolleista, ja sen tähden nämä voimat vaikuttavat hänessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Sillä Herodes oli ottanut Johanneksen kiinni, kahlehtinut hänet ja pannut vankilaan veljensä Filippoksen vaimon, Herodiaan, tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Sillä Johannes oli sanonut hänelle: \"Sinun ei ole lupa pitää häntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Herodes olisi tahtonut tappaa Johanneksen, mutta pelkäsi kansaa, sillä he pitivät häntä profeettana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Mutta kun Herodeksen syntymäpäivä tuli, tanssi Herodiaan tytär heidän edessään, ja se miellytti Herodesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Sen tähden hän valalla vannoen lupasi antaa hänelle, mitä ikinä hän anoisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Äitinsä yllyttämänä hän sanoi: \"Anna tuoda minulle tänne lautasella Johannes Kastajan pää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Silloin kuningas tuli murheelliseksi, mutta valansa ja pöytävieraiden tähden hän käski antaa sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'Hän lähetti lyömään Johannekselta pään poikki vankilassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Hänen päänsä tuotiin lautasella ja annettiin tytölle, ja tämä vei sen äidilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Hänen opetuslapsensa tulivat ja ottivat hänen ruumiinsa ja hautasivat hänet. He menivät ja ilmoittivat asian Jeesukselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Kun Jeesus sen kuuli, hän lähti sieltä veneellä autioon paikkaan, yksinäisyyteen. Kun kansa sai siitä kuulla, se meni jalkaisin kaupungeista hänen jälkeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Poistuessaan Jeesus näki paljon kansaa, ja hänen tuli heitä sääli, ja hän paransi heidän sairaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Mutta kun ilta tuli, hänen opetuslapsensa menivät hänen luokseen ja sanoivat: \"Tämä paikka on autio, ja on jo myöhä. Laske siis kansa luotasi, että he menisivät kyliin ostamaan itselleen ruokaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Mutta Jeesus sanoi heille: \"Heidän ei tarvitse mennä pois, antakaa te heille syödä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'He sanoivat hänelle: \"Meillä ei ole täällä muuta kuin viisi leipää ja kaksi kalaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Mutta hän sanoi: \"Tuokaa ne tänne minulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Hän käski kansan asettua ruohikolle, otti ne viisi leipää ja kaksi kalaa, katsoi ylös taivaaseen, siunasi, mursi ja antoi leivät opetuslapsilleen, ja opetuslapset antoivat kansalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Kaikki söivät ja tulivat ravituiksi. Sitten he keräsivät jääneet palaset, kaksitoista täyttä korillista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Niitä, jotka aterioivat, oli noin viisituhatta miestä, lisäksi naisia ja lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Heti hän vaati opetuslapsiaan astumaan veneeseen ja kulkemaan edeltä toiselle rannalle, sillä aikaa kun hän laski kansan luotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Laskettuaan kansan hän nousi vuorelle yksinäisyyteen rukoilemaan. Kun ilta tuli, hän oli siellä yksinään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Mutta vene oli jo keskellä merta aaltojen ahdistamana, sillä tuuli oli vastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Mutta neljännellä yövartiolla Jeesus tuli heidän luokseen kävellen järven päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Kun opetuslapset näkivät hänen kävelevän järven päällä, he pelästyivät ja sanoivat: \"Se on aave\", ja huusivat pelosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Mutta Jeesus puhutteli heitä heti ja sanoi: \"Olkaa turvallisella mielellä, Minä olen; älkää pelätkö.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Pietari vastasi hänelle ja sanoi: \"Jos se olet sinä, Herra, niin käske minun tulla luoksesi veden päällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Hän sanoi: \"Tule.\" Pietari astui veneestä ja käveli veden päällä mennäkseen Jeesuksen luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Mutta huomatessaan voimakkaan tuulen hän pelästyi, alkoi vajota ja huusi sanoen: \"Herra, pelasta minut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Niin Jeesus ojensi heti kätensä, tarttui häneen ja sanoi hänelle: \"Vähäuskoinen, miksi epäilit?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'Kun he olivat astuneet veneeseen, tuuli asettui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Niin veneessä olijat tulivat kumartamaan häntä ja sanoivat: \"Totisesti sinä olet Jumalan Poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Mentyään yli he tulivat maihin Genetsaretiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Kun paikkakunnan miehet tunsivat hänet, he lähettivät sanan koko ympäristöön, ja hänen luokseen tuotiin kaikki sairaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'He pyysivät häneltä, että vain saisivat koskea hänen viittansa tupsuun, ja kaikki, jotka koskivat, paranivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Silloin fariseuksia ja kirjanoppineita tuli Jerusalemista Jeesuksen luo, ja he sanoivat:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, '\"Miksi opetuslapsesi rikkovat vanhinten perinnäissääntöä? Sillä he eivät pese käsiään, kun syövät leipää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Mutta hän vastasi ja sanoi heille: \"Miksi te itse rikotte Jumalan käskyn perinnäissääntönne tähden?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Sillä Jumala on antanut käskyn sanoen: \'Kunnioita isääsi ja äitiäsi\', ja: \'Joka kiroaa isäänsä tai äitiään, sen pitää kuolemalla kuoleman.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Mutta te sanotte: Joka sanoo isälleen tai äidilleen: \'Se, minkä sinä olisit ollut minulta saava, on annettu uhrilahjaksi\', sen ei tarvitse kunnioittaa isäänsä eikä äitiään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'Niin olette tehneet Jumalan sanan tyhjäksi perinnäissääntönne tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Te tekopyhät, oikein Jesaja on teistä ennustanut sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, '\'Tämä kansa lähestyy minua suullaan ja kunnioittaa minua huulillaan, mutta heidän sydämensä on kaukana minusta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'mutta turhaan he palvelevat minua opettaen oppeja, jotka ovat ihmiskäskyjä.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Hän kutsui kansan luokseen ja sanoi heille: \"Kuulkaa ja ymmärtäkää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Ihmistä ei saastuta se, mikä menee suusta sisään, vaan se, mikä suusta tulee ulos, saastuttaa ihmisen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Silloin opetuslapset tulivat ja sanoivat hänelle: \"Tiedätkö, että fariseukset loukkaantuivat kuullessaan tuon puheen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Mutta hän vastasi ja sanoi: \"Jokainen istutus, jota minun taivaallinen Isäni ei ole istuttanut, on juurineen revittävä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Älkää heistä välittäkö: he ovat sokeita sokeiden taluttajia. Mutta jos sokea sokeaa taluttaa, he lankeavat molemmat kuoppaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Niin Pietari vastasi ja sanoi hänelle: \"Selitä meille tämä vertaus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Mutta Jeesus sanoi: \"Vieläkö tekin olette ymmärtämättömiä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Ettekö käsitä, että kaikki, mikä käy suusta sisään, menee vatsaan ja ulostetaan käymälään?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Mutta mikä käy suusta ulos, se tulee sydämestä, ja sellainen saastuttaa ihmisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Sillä sydämestä lähtevät pahat ajatukset, murhat, aviorikokset, haureudet, varkaudet, väärät todistukset, jumalanpilkat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'Nämä ihmisen saastuttavat, mutta pesemättömin käsin syöminen ei saastuta ihmistä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Sitten Jeesus lähti sieltä ja vetäytyi Tyyron ja Siidonin tienoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'Katso, kanaanilainen nainen tuli niiltä seuduilta ja huusi sanoen: \"Herra, Daavidin poika, armahda minua. Riivaaja vaivaa kauheasti tytärtäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Mutta hän ei vastannut hänelle sanaakaan. Hänen opetuslapsensa tulivat ja rukoilivat häntä sanoen: \"Päästä hänet menemään, sillä hän huutaa peräämme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Hän vastasi ja sanoi: \"Minua ei ole lähetetty muiden kuin Israelin huoneen kadonneiden lampaiden luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Mutta nainen tuli ja lankesi hänen eteensä ja sanoi: \"Herra, auta minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Mutta hän vastasi ja sanoi: \"Ei ole oikein ottaa lasten leipä ja heittää se koiran penikoille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Mutta vaimo sanoi: \"Niin, Herra, mutta syöväthän penikatkin niitä muruja, jotka heidän isäntiensä pöydältä putoavat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Silloin Jeesus vastasi ja sanoi hänelle: \"Nainen, suuri on uskosi, tapahtukoon sinulle, kuten tahdot.\" Hänen tyttärensä oli siitä hetkestä terve.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'Sitten Jeesus lähti sieltä ja tuli Galilean järven rannalle, nousi vuorelle ja istuutui sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Hänen luokseen tuli paljon kansaa, ja he toivat mukanaan rampoja, raajarikkoja, sokeita, mykkiä ja paljon muita, ja laskivat heidät hänen jalkojensa juureen; ja hän paransi heidät,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'niin että kansa ihmetteli nähdessään mykkien puhuvan, raajarikkojen olevan terveitä, rampojen kävelevän ja sokeiden näkevän; ja he ylistivät Israelin Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Jeesus kutsui opetuslapsensa luokseen ja sanoi: \"Minun käy sääliksi kansaa, sillä he ovat jo kolme päivää olleet luonani, eikä heillä ole mitä syödä, enkä tahdo laskea heitä menemään syömättä, etteivät nääntyisi matkalla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Opetuslapset sanoivat hänelle: \"Mistä saamme erämaassa niin paljon leipiä, että voimme ravita noin suuren joukon?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Jeesus sanoi heille: \"Montako leipää teillä on?\" He sanoivat: \"Seitsemän, ja joitakin pieniä kaloja.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Hän käski kansan asettua maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'Hän otti ne seitsemän leipää ja kalat, kiitti, mursi ja antoi opetuslapsilleen, ja opetuslapset antoivat kansalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Kaikki söivät ja tulivat ravituiksi. Sitten he keräsivät jääneet palaset, seitsemän täyttä korillista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Niitä, jotka aterioivat, oli neljätuhatta miestä, lisäksi naisia ja lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Laskettuaan kansan luotaan hän astui veneeseen ja meni Magdalan alueelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Fariseukset ja saddukeukset tulivat hänen luokseen ja kiusasivat häntä pyytäen häntä näyttämään heille merkin taivaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Mutta hän vastasi ja sanoi heille: \"Kun ilta tulee, sanotte: \'Tulee selkeä ilma, sillä taivas ruskottaa\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'ja aamulla: \'Tänään tulee rajuilma, sillä taivas ruskottaa ja on synkkä.\' Taivaan muodon osaatte arvioida, mutta aikojen merkkejä ette osaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Tämä paha ja avion rikkova sukukunta tavoittelee merkkiä, mutta sille ei anneta muuta merkkiä kuin Joonan merkki.\" Hän jätti heidät ja meni pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Kun opetuslapset saapuivat toiselle rannalle, he olivat unohtaneet ottaa leipiä mukaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Jeesus sanoi heille: \"Varokaa ja kavahtakaa fariseusten ja saddukeusten hapatusta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'He puhuivat keskenään sanoen: \"Emme ottaneet leipiä mukaamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Mutta sen tietäen Jeesus sanoi: \"Te vähäuskoiset, miksi puhutte keskenänne siitä, ettei teillä ole leipiä mukananne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Ettekö vieläkään käsitä? Ettekö muista niitä viittä leipää viidelletuhannelle ja kuinka monta korillista otitte talteen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'ettekä niitä seitsemää leipää neljälletuhannelle ja kuinka monta korillista otitte talteen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Miksi ette käsitä, etten puhunut teille leivästä? Vaan siitä, että kavahtakaa fariseusten ja saddukeusten hapatusta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Silloin he ymmärsivät, ettei hän käskenyt kavahtamaan leivän hapatusta, vaan fariseusten ja saddukeusten oppia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Kun Jeesus tuli Filippoksen Kesarean alueelle, hän kysyi opetuslapsiltaan sanoen: \"Kenen ihmiset sanovat Ihmisen Pojan olevan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'He sanoivat: \"Muutamat Johannes Kastajan, toiset Elian, toiset taas Jeremian tai jonkun muun profeetoista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Hän sanoi heille: \"Kenenkä te sanotte minun olevan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Simon Pietari vastasi ja sanoi: \"Sinä olet Kristus, elävän Jumalan Poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Jeesus vastasi ja sanoi hänelle: \"Autuas olet sinä, Simon, Joonaan poika, sillä liha ja veri ei ole sitä sinulle ilmoittanut, vaan minun Isäni, joka on taivaissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'ja minä sanon sinulle: sinä olet Pietari, ja tälle kalliolle minä rakennan seurakuntani, eivätkä helvetin portit voita sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Olen antava sinulle taivasten valtakunnan avaimet, ja minkä sidot maan päällä, se on oleva sidottu taivaissa, ja minkä päästät maan päällä, se on oleva päästetty taivaissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Silloin hän varoitti vakavasti opetuslapsiaan sanomasta kenellekään, että hän on Jeesus Kristus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Siitä lähtien Jeesus alkoi ilmoittaa opetuslapsilleen, että hänen pitää mennä Jerusalemiin ja kärsiä paljon vanhimmilta, ylipapeilta ja kirjanoppineilta ja tulla tapetuksi ja kolmantena päivänä nousta ylös.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Silloin Pietari otti hänet erilleen ja rupesi nuhtelemaan häntä sanoen: \"Olkoon Jumala armollinen, Herra, älköön se sinulle tapahtuko.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Mutta hän kääntyi ja sanoi Pietarille: \"Mene pois minun luotani, saatana; olet minulle pahennukseksi, sillä et ajattele sitä, mikä on Jumalan, vaan sitä, mikä on ihmisten.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Silloin Jeesus sanoi opetuslapsilleen: \"Jos joku tahtoo kulkea minun perässäni, hän kieltäköön itsensä, ottakoon ristinsä ja seuratkoon minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Sillä se, joka tahtoo pelastaa elämänsä, kadottaa sen, mutta se, joka kadottaa elämänsä minun tähteni, löytää sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Sillä mitä ihminen siitä hyötyy, vaikka hän voittaisi omakseen koko maailman, mutta saisi sielulleen vahingon? Tai mitä ihminen voi antaa sielunsa lunnaiksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Sillä Ihmisen Poika on tuleva Isänsä kirkkaudessa enkeliensä kanssa, ja silloin hän maksaa kullekin hänen tekojensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Totisesti sanon teille: tässä seisovien joukossa on muutamia, jotka eivät maista kuolemaa, ennen kuin näkevät Ihmisen Pojan tulevan valtakunnassaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Sitten kuuden päivän kuluttua Jeesus otti mukaansa Pietarin sekä Jaakobin ja hänen veljensä Johanneksen ja vei heidät korkealle vuorelle yksinäisyyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'Hänen muotonsa muuttui heidän edessään, ja hänen kasvonsa loistivat kuin aurinko, ja hänen vaatteensa tulivat valkoisiksi kuin valo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'Katso, heille ilmestyivät Mooses ja Elia, jotka puhuivat hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Niin Pietari ryhtyi puhumaan ja sanoi Jeesukselle: \"Herra, meidän on tässä hyvä olla; jos tahdot, teemme tähän kolme majaa, sinulle yhden, Moosekselle yhden ja Elialle yhden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Hänen vielä puhuessaan, katso, heidät varjosi valoisa pilvi; ja katso, pilvestä kuului ääni, joka sanoi: \"Tämä on rakas Poikani, johon olen mieltynyt, kuulkaa häntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Kun opetuslapset sen kuulivat, he lankesivat kasvoilleen ja pelästyivät kovin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Jeesus tuli heidän luokseen, kosketti heitä ja sanoi: \"Nouskaa, älkääkä pelätkö.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Kun he nostivat silmänsä, he eivät nähneet ketään muuta kuin Jeesuksen yksinään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'Heidän kulkiessaan alas vuorelta Jeesus kielsi heitä sanoen: \"Älkää kertoko kenellekään tätä näkyä, ennen kuin Ihmisen Poika on noussut kuolleista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Hänen opetuslapsensa kysyivät häneltä sanoen: \"Miksi sitten kirjanoppineet sanovat, että Elian pitää tulla ensin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Jeesus vastasi ja sanoi: \"Elia tosin tulee ja asettaa kaiken ennalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Mutta sanon teille, että Elia on jo tullut. Mutta he eivät tunteneet häntä, vaan tekivät hänelle, mitä tahtoivat. Samoin myös Ihmisen Poika tulee kärsimään heiltä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Silloin opetuslapset ymmärsivät hänen puhuneen heille Johannes Kastajasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Kun he saapuivat kansan luo, hänen luokseen tuli eräs mies, polvistui hänen eteensä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'ja sanoi: \"Herra, armahda poikaani, sillä hän on kuunvaihetautinen ja kärsii kovin. Hän kaatuu usein tuleen ja usein veteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'Toin hänet opetuslastesi luo, mutta he eivät voineet häntä parantaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Jeesus vastasi ja sanoi: \"Voi sinä epäuskoinen ja nurja sukukunta, kuinka kauan minun täytyy olla kanssanne? Kuinka kauan kärsiä teitä? Tuokaa hänet tänne minulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Jeesus nuhteli riivaajaa, ja se lähti pojasta, ja poika oli siitä hetkestä terve.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Silloin opetuslapset menivät Jeesuksen luo erikseen ja sanoivat: \"Miksi me emme voineet ajaa sitä ulos?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Hän sanoi heille: \"Teidän epäuskonne tähden; sillä totisesti sanon teille: jos teillä olisi uskoa sinapinsiemenenkään verran, sanoisitte tälle vuorelle: \'Siirry täältä tuonne\', ja se siirtyisi, eikä mikään olisi teille mahdotonta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Mutta tätä lajia ei saa lähtemään ulos muulla kuin rukouksella ja paastolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Kun he vaelsivat Galileassa, Jeesus sanoi heille: \"Ihmisen Poika annetaan ihmisten käsiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'ja he tappavat hänet, ja kolmantena päivänä hän nousee ylös.\" He tulivat hyvin murheellisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Kun he saapuivat Kapernaumiin, tulivat temppeliveron kantajat Pietarin luo ja sanoivat: \"Eikö teidän opettajanne maksa temppeliveroa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Hän sanoi: \"Maksaa.\" Kun hän tuli huoneeseen, Jeesus kysyi häneltä heti kohta: \"Mitä arvelet, Simon? Keiltä maan kuninkaat ottavat tullia tai veroa? Lapsiltaan vai vierailta?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Kun hän vastasi: \"Vierailta\", Jeesus sanoi hänelle: \"Lapset ovat siis vapaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Mutta ettemme heitä loukkaisi, mene ja heitä onki järveen. Ota sitten ensiksi saamasi kala, ja kun avaat sen suun, löydät hopearahan. Ota se ja anna heille minun puolestani ja omasta puolestasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'Sillä hetkellä opetuslapset tulivat Jeesuksen luo ja sanoivat: \"Kuka sitten on suurin taivasten valtakunnassa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Hän kutsui luokseen lapsen, asetti sen heidän keskelleen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'ja sanoi: \"Totisesti sanon teille: ellette käänny ja tule lasten kaltaisiksi, ette tule taivasten valtakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Sen tähden, se, joka nöyrtyy tämän lapsen kaltaiseksi, on suurin taivasten valtakunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'Se, joka ottaa luokseen yhden tällaisen lapsen minun nimeeni, ottaa luokseen minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Mutta joka viettelee yhden näistä pienistä, jotka uskovat minuun, sen olisi parempi, että myllynkivi ripustettaisiin hänen kaulaansa ja hänet upotettaisiin meren syvyyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Voi maailmaa viettelysten tähden! Viettelysten täytyy kyllä tulla, mutta voi sitä ihmistä, jonka kautta viettelys tulee!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Mutta jos kätesi tai jalkasi viettelee sinua, hakkaa se pois ja heitä luotasi. Parempi on sinulle, että käsipuolena tai jalkapuolena tulet elämään sisälle, kuin että sinut, molemmat kädet tai molemmat jalat tallella, heitetään iankaikkiseen tuleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Jos silmäsi viettelee sinua, repäise se pois ja heitä luotasi; parempi on sinun silmäpuolena mennä elämään sisälle, kuin että sinut, molemmat silmät tallella, heitetään helvetin tuleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Katsokaa, ettette halveksi yhtään näistä pienistä; sillä sanon teille, että heidän enkelinsä taivaissa näkevät aina Isäni kasvot, joka on taivaissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Sillä Ihmisen Poika on tullut pelastamaan sitä, mikä on kadonnut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Mitä arvelette? Jos jollakin ihmisellä on sata lammasta ja yksi niistä eksyy, eikö hän jätä niitä yhdeksääkymmentä yhdeksää vuorille ja mene etsimään eksynyttä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'Ja jos hän sen löytää, totisesti sanon teille: hän iloitsee enemmän siitä kuin niistä yhdeksästäkymmenestä yhdeksästä, jotka eivät olleet eksyneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Niin ei myöskään teidän taivaallisen Isänne tahto ole, että yksikään näistä pienistä joutuisi kadotukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Mutta jos veljesi rikkoo sinua vastaan, mene ja nuhtele häntä kahden kesken; jos hän sinua kuulee, olet voittanut veljesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Mutta jos hän ei kuule sinua, ota vielä yksi tai kaksi kanssasi, \'että jokainen asia vahvistettaisiin kahden tai kolmen todistajan sanalla.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Mutta jos hän ei kuule heitä, ilmoita seurakunnalle. Mutta jos hän ei seurakuntaakaan kuule, olkoon hän sinulle, kuin olisi pakana ja publikaani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Totisesti sanon teille: kaikki, minkä te sidotte maan päällä, on oleva sidottu taivaassa, ja kaikki, minkä päästätte maan päällä, on oleva päästetty taivaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Vielä sanon teille: jos kaksi teistä maan päällä keskenään sopii mistä asiasta tahansa, että he sitä anovat, he saavat sen Isältäni, joka on taivaissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Sillä missä kaksi tai kolme on kokoontunut minun nimeeni, siinä olen heidän keskellään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Silloin Pietari meni hänen luokseen ja sanoi hänelle: \"Herra, kuinka monta kertaa minun on annettava anteeksi veljelleni, joka rikkoo minua vastaan? Aivanko seitsemän kertaa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Jeesus vastasi hänelle: \"En sano sinulle seitsemän kertaa, vaan seitsemänkymmentä kertaa seitsemän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'Sen tähden taivasten valtakunta on verrattavissa kuninkaaseen, joka vaati palvelijoiltaan tilin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Kun hän rupesi tilintekoon, hänen eteensä tuotiin eräs, joka oli hänelle velkaa kymmenentuhatta talenttia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Mutta kun tällä ei ollut, millä maksaa, hänen isäntänsä määräsi myytäväksi hänet, hänen vaimonsa, lapsensa ja kaikki, mitä hänellä oli, ja velan maksettavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Niin palvelija lankesi maahan ja rukoili häntä sanoen: \'Ole pitkämielinen minua kohtaan, niin maksan sinulle kaiken.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Isännän kävi sääliksi tuota palvelijaa, ja hän päästi hänet ja antoi hänelle velan anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Mutta mentyään ulos palvelija tapasi erään palvelustoverinsa, joka oli hänelle velkaa sata denaaria; ja tarttui häneen, kuristi häntä kurkusta ja sanoi: \'Maksa, minkä olet velkaa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Niin hänen palvelustoverinsa lankesi maahan ja pyysi häntä sanoen: \'Ole pitkämielinen minua kohtaan, niin maksan sinulle kaiken.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Mutta hän ei tahtonut, vaan meni ja heitti hänet vankilaan, kunnes hän maksaisi velkansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Kun nyt hänen palvelustoverinsa näkivät, mitä tapahtui, he tulivat kovin murheellisiksi ja menivät ja ilmoittivat isännälleen kaiken, mitä oli tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Silloin hänen isäntänsä kutsui hänet eteensä ja sanoi hänelle: \'Sinä paha palvelija! Annoin sinulle anteeksi kaiken sen velan, koska sitä minulta pyysit,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'eikö sinunkin olisi pitänyt armahtaa palvelustoveriasi, niin kuin minäkin armahdin sinua?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Hänen isäntänsä vihastui ja antoi hänet vanginvartijoille, kunnes hän maksaisi kaiken, minkä oli hänelle velkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Näin myös taivaallinen Isäni tekee teille, ellette kukin anna veljellenne sydämestänne anteeksi heidän rikkomisiaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'Tapahtui, että kun Jeesus oli lopettanut nämä puheet, hän poistui Galileasta ja tuli Juudean rajalle Jordanin tuolle puolen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'Paljon kansaa seurasi häntä, ja hän paransi heitä siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Myös fariseuksia tuli hänen luokseen, ja he kiusasivat häntä sanoen: \"Onko miehen lupa hylätä vaimonsa mistä syystä tahansa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Hän vastasi ja sanoi: \"Ettekö ole lukeneet, että Luoja jo alussa \'loi heidät mieheksi ja naiseksi\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'ja sanoi: \'Sen tähden mies luopukoon isästään ja äidistään ja liittyköön vaimoonsa, ja ne kaksi tulevat yhdeksi lihaksi\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'Niin siis he eivät ole enää kaksi, vaan yksi liha. Minkä siis Jumala on yhdistänyt, sitä älköön ihminen erottako.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'He sanoivat hänelle: \"Miksi sitten Mooses käski antaa erokirjan ja hylätä hänet?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Hän sanoi heille: \"Teidän sydämenne kovuuden tähden Mooses salli teidän hylätä vaimonne, mutta alusta niin ei ollut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Mutta sanon teille: se, joka hylkää vaimonsa muun kuin huoruuden tähden ja nai toisen, tekee huorin; ja se, joka nai hylätyn, tekee huorin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Opetuslapset sanoivat hänelle: \"Jos miehen on näin laita vaimoonsa nähden, ei ole hyvä avioitua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Mutta hän sanoi heille: \"Ei tämä sana kaikkiin sovellu, vaan ainoastaan niihin, joille se on suotu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Sillä on niitä, jotka syntymästään, äitinsä kohdusta asti, ovat syntyneet avioon kelpaamattomina, ja on niitä, jotka ihmiset ovat tehneet avioon kelpaamattomiksi, ja niitä, jotka taivasten valtakunnan tähden ovat tehneet itsensä avioon kelpaamattomiksi. Joka voi sen soveltaa itseensä, soveltakoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Silloin hänen luokseen tuotiin lapsia, että hän panisi kätensä heidän päälleen ja rukoilisi, mutta opetuslapset nuhtelivat tuojia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Jeesus sanoi: \"Antakaa lasten olla, älkääkä estäkö heitä tulemasta tyköni, sillä sellaisten on taivasten valtakunta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Laskettuaan kätensä heidän päälleen hän poistui sieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'Katso, eräs mies tuli ja sanoi hänelle: \"Hyvä opettaja, mitä hyvää minä tekisin, että omistaisin iankaikkisen elämän?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Niin hän sanoi hänelle: \"Miksi sanot minua hyväksi? On ainoastaan yksi, joka on hyvä, Jumala. Mutta jos tahdot tulla elämään sisälle, pidä käskyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Hän sanoi hänelle: \"Mitkä?\" Jeesus sanoi: \"Nämä: \'Älä tapa\', \'Älä tee huorin\', \'Älä varasta\', \'Älä sano väärää todistusta\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, '\'Kunnioita isääsi ja äitiäsi\', ja: \'Rakasta lähimmäistäsi niin kuin itseäsi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Nuorukainen sanoi hänelle: \"Kaikkia niitä olen noudattanut, mitä vielä puuttuu?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Jeesus sanoi hänelle: \"Jos tahdot olla täydellinen, mene, myy, mitä sinulla on, ja anna köyhille, niin sinulla on oleva aarre taivaissa, ja tule ja seuraa minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Mutta kun nuorukainen kuuli tämän sanan, hän lähti pois murheellisena, sillä hänellä oli paljon omaisuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Mutta Jeesus sanoi opetuslapsilleen: \"Totisesti sanon teille: rikkaan on vaikea käydä sisälle taivasten valtakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Vielä sanon teille: helpompi on kamelin mennä neulansilmän läpi kuin rikkaan käydä sisälle Jumalan valtakuntaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Kun opetuslapset sen kuulivat, he hämmästyivät kovin ja sanoivat: \"Kuka sitten voi pelastua?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Jeesus katsoi heihin ja sanoi heille: \"Ihmisille se on mahdotonta, mutta Jumalalle on kaikki mahdollista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Silloin Pietari vastasi ja sanoi hänelle: \"Katso, me olemme luopuneet kaikesta ja seuranneet sinua; mitä siitä saamme?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Jeesus sanoi heille: \"Totisesti sanon teille: siinä uudestisyntymisessä, jolloin Ihmisen Poika istuu kirkkautensa valtaistuimella, tekin, jotka olette minua seuranneet, saatte istua kahdellatoista valtaistuimella ja tuomita Israelin kahtatoista sukukuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'Jokainen, joka on luopunut taloista tai veljistä tai sisarista tai isästä tai äidistä tai lapsista tai pelloista nimeni tähden, on saava satakertaisesti takaisin ja perivä iankaikkisen elämän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Mutta monet ensimmäiset tulevat viimeisiksi, ja monet viimeiset ensimmäisiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, '\"Sillä taivasten valtakunta on perheenisännän kaltainen, joka varhain aamulla lähti ulos palkkaamaan työmiehiä viinitarhaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Sovittuaan työmiesten kanssa denaarista päivältä hän lähetti heidät viinitarhaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'Hän lähti ulos kolmannen tunnin vaiheilla, näki toisia seisomassa torilla joutilaina');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'ja sanoi heille: \'Menkää tekin viinitarhaan, ja mikä oikein on, sen annan teille.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'He menivät. Taas hän lähti ulos kuudennen ja yhdeksännen tunnin vaiheilla ja teki samoin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Kun hän lähti ulos yhdennentoista tunnin vaiheilla, hän tapasi vielä toisia siellä seisomassa. Hän sanoi heille: \'Miksi olette seisoneet täällä joutilaina koko päivän?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'He sanoivat hänelle: \'Kun kukaan ei ole meitä palkannut.\' Hän sanoi heille: \'Menkää tekin viinitarhaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Mutta kun ilta tuli, viinitarhan isäntä sanoi tilanhoitajalleen: \'Kutsu työmiehet ja maksa heille palkka, viimeisistä alkaen ensimmäisiin asti.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Kun nyt tulivat ne, jotka olivat saapuneet yhdennentoista tunnin vaiheilla, he saivat kukin denaarin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Kun ensimmäiset tulivat, he luulivat saavansa enemmän, mutta hekin saivat kukin denaarin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'Kun he sen saivat, he napisivat perheenisäntää vastaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'ja sanoivat: \'Nämä viimeiset ovat tehneet työtä vain yhden tunnin, ja sinä teit heidät meidän vertaisiksemme, jotka olemme kantaneet päivän kuorman ja helteen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Hän vastasi eräälle heistä ja sanoi: \'Ystäväni, en tee sinulle vääryyttä; etkö sopinut kanssani denaarista?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Ota omasi ja mene. Mutta minä tahdon tälle viimeiselle antaa kuten sinullekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Enkö saa tehdä omallani, mitä tahdon? Vai onko silmäsi paha sen tähden, että minä olen hyvä?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Näin viimeiset tulevat ensimmäisiksi ja ensimmäiset viimeisiksi. Monet näet ovat kutsuttuja, mutta harvat valittuja.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Kun Jeesus lähti kulkemaan ylös Jerusalemiin, hän otti ne kaksitoista erilleen ja sanoi heille matkalla:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, '\"Katso, me menemme ylös Jerusalemiin, ja Ihmisen Poika annetaan ylipapeille ja kirjanoppineille ja he tuomitsevat hänet kuolemaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'ja antavat hänet pakanoille pilkattavaksi, ruoskittavaksi ja ristiinnaulittavaksi, mutta kolmantena päivänä hän on nouseva ylös.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Silloin Sebedeuksen poikien äiti tuli poikineen hänen luokseen, polvistui hänen eteensä ja anoi häneltä jotakin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'Hän sanoi naiselle: \"Mitä tahdot?\" Tämä sanoi hänelle: \"Sano, että nämä kaksi poikaani saavat istua, toinen oikealla ja toinen vasemmalla puolellasi valtakunnassasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Mutta Jeesus vastasi ja sanoi: \"Ette tiedä, mitä anotte. Voitteko juoda sen maljan, jonka minä olen juova?\" He sanoivat hänelle: \"Voimme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Hän sanoi heille: \"Minun maljani te tosin juotte, ja kasteella, jolla minut kastetaan, kastetaan teidätkin, mutta oikealla ja vasemmalla puolellani istuminen ei ole minun annettavissani, vaan se annetaan niille, joille minun Isäni on sen valmistanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Kun ne kymmenen sen kuulivat, he närkästyivät näihin kahteen veljekseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Mutta Jeesus kutsui heidät luokseen ja sanoi: \"Te tiedätte, että kansojen ruhtinaat herroina hallitsevat heitä, ja että suuret käyttävät valtaansa heitä kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Näin älköön olko teillä keskenänne, vaan se, joka keskuudessanne tahtoo tulla suureksi, olkoon palvelijanne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'ja se, joka teidän keskuudessanne tahtoo olla ensimmäinen, olkoon orjanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'Ihmisen Poikakaan ei tullut palveltavaksi, vaan palvelemaan ja antamaan henkensä lunnaiksi monen edestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Heidän lähtiessään Jerikosta seurasi häntä paljon kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'Katso, kaksi sokeaa istui tien vieressä, ja kun he kuulivat, että Jeesus kulki ohi, he huusivat sanoen: \"Herra, Daavidin poika, armahda meitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Kansa nuhteli heitä saadakseen heidät vaikenemaan, mutta he huusivat sitä enemmän sanoen: \"Herra, Daavidin poika, armahda meitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Silloin Jeesus pysähtyi, kutsui heidät luokseen ja sanoi: \"Mitä tahdotte minun teille tekevän?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'He sanoivat hänelle: \"Herra, että silmämme aukenisivat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Niin Jeesuksen tuli heitä sääli, ja hän kosketti heidän silmiään, ja heti he saivat näkönsä ja seurasivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Kun he lähestyivät Jerusalemia ja saapuivat Beetfageen, Öljymäelle, silloin Jeesus lähetti kaksi opetuslasta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'ja sanoi heille: \"Menkää kylään, joka on edessänne, niin te heti löydätte aasintamman sidottuna ja varsan sen kanssa. Päästäkää ne ja tuokaa minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'Jos joku teille jotakin sanoo, vastatkaa: \'Herra tarvitsee niitä\', ja heti hän lähettää ne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Tämä kaikki tapahtui, että kävisi toteen, mikä on puhuttu profeetan kautta, joka sanoo:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, '\"Sanokaa tytär Siionille: \'Katso, sinun kuninkaasi tulee sinulle sävyisänä ja ratsastaen aasilla, ikeenalaisen aasin varsalla.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Niin opetuslapset menivät ja tekivät, kuten Jeesus oli heitä käskenyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'toivat aasintamman varsoineen ja panivat niiden selkään vaatteitaan, ja hän istuutui niiden päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Suurin osa kansasta levitti vaatteitaan tielle, ja toiset karsivat oksia puista ja hajottivat tielle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'Kansanjoukot, jotka kulkivat hänen edellään ja jotka seurasivat, huusivat sanoen: \"Hoosianna Daavidin pojalle! Siunattu olkoon hän, joka tulee Herran nimeen. Hoosianna korkeuksissa!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Kun hän tuli Jerusalemiin, koko kaupunki lähti liikkeelle ja sanoi: \"Kuka tämä on?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Niin kansa sanoi: \"Tämä on Jeesus, Profeetta Galilean Nasaretista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Jeesus meni Jumalan pyhäkköön ja ajoi ulos kaikki, jotka myivät ja ostivat pyhäkössä, ja kaatoi kumoon rahanvaihtajien pöydät ja kyyhkysten myyjien istuimet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'Hän sanoi heille: \"Kirjoitettu on: \'Minun huoneeni on kutsuttava rukoushuoneeksi\', mutta te olette tehneet siitä ryövärien luolan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'Hänen luokseen tuli pyhäkössä sokeita ja rampoja, ja hän paransi heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Mutta kun ylipapit ja kirjanoppineet näkivät ne ihmeet, joita hän teki, ja lapset, jotka huusivat pyhäkössä ja sanoivat: \"Hoosianna Daavidin pojalle\", he närkästyivät');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'ja sanoivat hänelle: \"Kuuletko, mitä nämä sanovat?\" Jeesus sanoi heille: \"Kuulen; ettekö ole koskaan lukeneet: \'Lasten ja imeväisten suusta olet valmistanut itsellesi kiitoksen\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'Hän jätti heidät ja meni ulos kaupungista Betaniaan ja yöpyi siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Kun hän palasi varhain aamulla kaupunkiin, hänen tuli nälkä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'Nähdessään tien vieressä viikunapuun hän meni sen luo, mutta ei löytänyt siitä muuta kuin pelkkiä lehtiä. Hän sanoi sille: \"Älköön sinusta ikinä enää hedelmää kasvako.\" Heti viikunapuu kuivui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Kun opetuslapset tämän näkivät, ihmettelivät he ja sanoivat: \"Kuinka viikunapuu kuivui niin pian?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Jeesus vastasi ja sanoi heille: \"Totisesti sanon teille: jos teillä olisi uskoa ettekä epäilisi, ette voisi ainoastaan tehdä sitä, mikä viikunapuussa tapahtui, vaan vieläpä, jos sanoisitte tälle vuorelle: \'Kohoa ja heittäydy mereen\', se tapahtuisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'Kaiken, mitä te anotte rukouksessa uskoen, te saatte.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Kun hän oli mennyt pyhäkköön, hänen opettaessaan ylipapit ja kansan vanhimmat tulivat hänen luokseen ja sanoivat: \"Millä vallalla näitä teet? Kuka sinulle on antanut tämän vallan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Jeesus vastasi ja sanoi heille: \"Minä myös teen teille yhden kysymyksen. Jos minulle siihen vastaatte, minäkin sanon teille, millä vallalla minä näitä teen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Mistä Johanneksen kaste oli? Taivaasta vai ihmisistä?\" He neuvottelivat keskenään sanoen: \"Jos sanomme: \'Taivaasta\', niin hän sanoo meille: \'Miksi ette siis uskoneet häntä?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Mutta jos sanomme: \'Ihmisistä\', meidän täytyy pelätä kansaa, sillä kaikki pitävät Johannesta profeettana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'He vastasivat Jeesukselle ja sanoivat: \"Emme tiedä.\" Hänkin sanoi heille: \"Niinpä en minäkään sano teille, millä vallalla näitä teen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Mutta miten teistä on? Miehellä oli kaksi poikaa, ja hän meni ensimmäisen luo ja sanoi: \'Poikani, mene tänään tekemään työtä viinitarhaani.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Tämä vastasi ja sanoi: \'En tahdo\', mutta myöhemmin hän katui ja meni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Hän meni toisen luo ja sanoi samoin. Tämä taas vastasi ja sanoi: \'Minä menen, herra\', mutta ei mennytkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Kumpi näistä kahdesta teki isänsä tahdon?\" He sanoivat: \"Ensimmäinen.\" Jeesus sanoi heille: \"Totisesti sanon teille: publikaanit ja portot menevät ennen teitä Jumalan valtakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Sillä Johannes tuli teidän luoksenne vanhurskauden tietä, ettekä uskoneet häntä. Mutta publikaanit ja portot uskoivat häntä. Vaikka sen näitte, ette katuneet myöhemminkään, niin että olisitte uskoneet häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Kuulkaa toinen vertaus: Oli perheenisäntä, joka istutti viinitarhan, teki aidan sen ympärille, kaivoi siihen viinikuurnan ja rakensi tornin. Sitten hän vuokrasi sen viinitarhureille ja matkusti ulkomaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Kun hedelmien aika lähestyi, hän lähetti palvelijoitaan viinitarhurien luo perimään hänelle tulevat hedelmät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Mutta viinitarhurit ottivat kiinni hänen palvelijansa: minkä he pieksivät, minkä tappoivat, minkä kivittivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Vielä hän lähetti toisia palvelijoita, useampia kuin ensimmäiset; ja näille he tekivät samoin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Mutta viimein hän lähetti heidän luokseen poikansa sanoen: \'Minun poikaani he kavahtavat.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Mutta kun viinitarhurit näkivät pojan, he sanoivat keskenään: \'Tämä on perillinen; tulkaa, tappakaamme hänet, niin saamme hänen perintönsä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'He ottivat hänet kiinni, heittivät ulos viinitarhasta ja tappoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Kun viinitarhan herra tulee, mitä hän tekee noille viinitarhureille?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'He sanoivat hänelle: \"Nuo pahat hän pahoin tuhoaa ja vuokraa viinitarhan toisille viinitarhureille, jotka antavat hänelle hedelmät ajallaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Jeesus sanoi heille: \"Ettekö ole koskaan lukeneet Kirjoituksista: \'Se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi. Herralta tämä on tullut ja on ihmeellinen silmissämme\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Sen tähden sanon teille: Jumalan valtakunta otetaan teiltä pois ja annetaan pakanoille, jotka tekevät sen hedelmiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'Se, joka tähän kiveen kaatuu, ruhjoutuu, mutta jonka päälle se kaatuu, sen se murskaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Kun ylipapit ja fariseukset kuulivat nämä hänen vertauksensa, he ymmärsivät, että hän puhui heistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'He olisivat tahtoneet ottaa hänet kiinni, mutta he pelkäsivät kansaa, koska se piti häntä profeettana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'Jeesus rupesi taas puhumaan heille vertauksilla ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, '\"Taivasten valtakunta on verrattava kuninkaaseen, joka laittoi häät pojalleen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'ja lähetti palvelijansa kutsumaan häihin kutsuvieraita, mutta nämä eivät tahtoneet tulla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Vielä hän lähetti toisia palvelijoita lausuen: \'Sanokaa kutsutuille: Katso, olen valmistanut ateriani, härkäni ja syöttilääni ovat teurastetut, ja kaikki on valmista. Tulkaa häihin!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Mutta he eivät siitä välittäneet, vaan menivät pois, mikä pellolleen, mikä liiketoimilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'Toiset ottivat kiinni hänen palvelijansa, pitelivät pahoin ja tappoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Mutta kuningas vihastui, lähetti sotajoukkonsa, tuhosi nuo murhamiehet ja poltti heidän kaupunkinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Silloin hän sanoi palvelijoilleen: \'Häät ovat valmistetut, mutta kutsutut eivät olleet kelvollisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Menkää siis teiden risteyksiin ja kutsukaa häihin, keitä tapaatte.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Palvelijat menivät ulos teille ja kokosivat kaikki, keitä vain tapasivat, sekä pahat että hyvät, ja häähuone tuli täyteen pöytävieraita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Mutta kun kuningas meni katsomaan pöytävieraita, hän näki siellä miehen, joka ei ollut pukeutunut häävaatteisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'Hän sanoi hänelle: \'Ystävä, kuinka olet tullut tänne sisälle, vaikka sinulla ei ole häävaatteita?\' Mutta hän jäi sanattomaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Silloin kuningas sanoi palvelijoille: \'Sitokaa hänen jalkansa ja kätensä ja heittäkää hänet ulos pimeyteen.\' Siellä on oleva itku ja hammasten kiristys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Sillä monet ovat kutsutut, mutta harvat valitut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Silloin fariseukset menivät ja neuvottelivat, kuinka saisivat hänet sanoissa kiedotuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'He lähettivät hänen luokseen opetuslapsensa herodeslaisten kanssa sanomaan: \"Opettaja, tiedämme, että olet totuudellinen ja opetat Jumalan tietä totuudessa kenestäkään välittämättä, sillä et katso henkilöön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Sano siis meille: miten arvelet? Onko luvallista antaa keisarille veroa vai ei?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Mutta Jeesus ymmärsi heidän pahuutensa ja sanoi: \"Miksi kiusaatte minua, te tekopyhät?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Näyttäkää minulle veroraha.\" Niin he toivat hänelle denaarin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'Hän sanoi heille: \"Kenen kuva ja päällekirjoitus tämä on?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'He vastasivat: \"Keisarin.\" Silloin hän sanoi heille: \"Antakaa siis keisarille, mikä keisarin on, ja Jumalalle, mikä Jumalan on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Kun he sen kuulivat, he ihmettelivät ja jättivät hänet ja menivät pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Sinä päivänä hänen luokseen tuli saddukeuksia, jotka sanovat, ettei ylösnousemusta ole, ja he kysyivät häneltä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'sanoen: \"Opettaja, Mooses on sanonut: \'Jos joku kuolee saamatta lapsia, hänen veljensä naikoon hänen vaimonsa ja herättäköön siemenen veljelleen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Keskuudessamme oli seitsemän veljestä. Ensimmäinen otti vaimon ja kuoli. Koska hänellä ei ollut jälkeläistä, hän jätti vaimonsa veljelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Samoin toinen ja kolmas, ja seitsemänteen asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Viimeiseksi kaikista kuoli vaimo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Kenen vaimo noista seitsemästä hän siis on oleva ylösnousemuksessa? Sillä kaikkien vaimona hän on ollut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Jeesus vastasi ja sanoi heille: \"Eksytte, koska ette tunne Kirjoituksia ettekä Jumalan voimaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Sillä ylösnousemuksessa ei oteta vaimoa eikä anneta vaimoksi, vaan he ovat kuin Jumalan enkelit taivaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Mutta mitä kuolleiden ylösnousemukseen tulee, ettekö ole lukeneet, mitä Jumala on puhunut teille sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, '\'Minä olen Aabrahamin Jumala ja Iisakin Jumala ja Jaakobin Jumala\'? Hän ei ole kuolleiden Jumala, vaan elävien.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Sen kuultuaan kansa hämmästyi hänen oppiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Mutta kun fariseukset kuulivat, että hän oli vaientanut saddukeukset, he kokoontuivat yhteen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'ja eräs heistä, lainoppinut, kysyi häneltä kiusaten:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, '\"Opettaja, mikä on suurin käsky laissa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Jeesus sanoi hänelle: \"\'Rakasta Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi ja kaikesta mielestäsi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'Tämä on suurin ja ensimmäinen käsky.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'Toinen, tämän vertainen, on: \'Rakasta lähimmäistäsi niin kuin itseäsi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'Näissä kahdessa käskyssä riippuu kaikki Laki ja Profeetat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Fariseusten ollessa koolla Jeesus kysyi heiltä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'sanoen: \"Mitä arvelette Kristuksesta? Kenen poika hän on?\" He sanoivat hänelle: \"Daavidin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Hän sanoi heille: \"Kuinka sitten Daavid Hengessä kutsuu häntä Herraksi, sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, '\'Herra sanoi minun Herralleni: Istu minun oikealle puolelleni, kunnes panen vihollisesi jalkojesi astinlaudaksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Jos siis Daavid kutsuu häntä Herraksi, kuinka hän on hänen poikansa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'Kukaan ei voinut vastata hänelle sanaakaan, eikä siitä päivästä lähtien yksikään uskaltanut kysyä häneltä enää mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Silloin Jeesus puhui kansanjoukoille ja opetuslapsilleen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'sanoen: \"Mooseksen istuimella istuvat kirjanoppineet ja fariseukset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Sen tähden, kaikki, mitä he sanovat teille, se tehkää ja pitäkää, mutta heidän tekojensa mukaan älkää tehkö, sillä he sanovat, mutta eivät tee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'He sitovat kokoon raskaita ja vaikeasti kannettavia taakkoja ja panevat ne ihmisten hartioille, mutta itse he eivät tahdo niitä liikuttaa sormellaankaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'He tekevät kaikki tekonsa sitä varten, että ihmiset heitä katselisivat. He tekevät raamatunlausekotelonsa leveiksi ja viittansa tupsut suuriksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'ja rakastavat ensimmäistä sijaa pidoissa ja etumaisia istuimia synagogissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'ja tahtovat mielellään, että heitä tervehditään toreilla, ja että ihmiset sanovat heille: \'rabbi, rabbi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Mutta te älkää antako kutsua itseänne rabbiksi, sillä yksi on teidän opettajanne, ja te olette kaikki veljiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'Isäksenne älkää kutsuko ketään maan päällä, sillä yksi on teidän Isänne, hän, joka on taivaissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Älkääkä antako kutsua itseänne rabbiksi, sillä yksi on teidän opettajanne, Kristus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Vaan se, joka teistä on suurin, olkoon teidän palvelijanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Se, joka itsensä ylentää, alennetaan; ja se, joka itsensä alentaa, ylennetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Mutta voi teitä, kirjanoppineet ja fariseukset, te tekopyhät, kun suljette taivasten valtakunnan ihmisiltä! Sillä itse te ette mene sisälle, ettekä salli sinne menevienkään mennä sisään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Voi teitä, kirjanoppineet ja fariseukset, te tekopyhät, kun syötte leskien talot, jopa pitäen näön vuoksi pitkiä rukouksia! Sen tähden saatte sitä kovemman tuomion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Voi teitä, kirjanoppineet ja fariseukset, te tekopyhät, kun kierrätte meret ja mantereet tehdäksenne yhden käännynnäisen. Kun joku on siksi tullut, teette hänestä helvetin lapsen, kaksi kertaa itseänne pahemman!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Voi teitä, te sokeat taluttajat, jotka sanotte: \'Jos joku vannoo temppelin kautta, se ei ole mitään, mutta jos joku vannoo temppelin kullan kautta, hän on valaansa sidottu\'!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Te tyhmät ja sokeat! Kumpi on suurempi, kulta vai temppeli, joka kullan pyhittää?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'Ja: \'Jos joku vannoo alttarin kautta, se ei ole mitään, mutta jos joku vannoo sen päällä olevan uhrilahjan kautta, hän on valaansa sidottu.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Te sokeat! Kumpi on suurempi, uhrilahja vai alttari, joka uhrilahjan pyhittää?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Sen tähden, joka vannoo alttarin kautta, vannoo sen kautta ja kaiken kautta, mitä sen päällä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'Joka vannoo temppelin kautta, vannoo sen kautta ja hänen kauttaan, joka siinä asuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'Joka vannoo taivaan kautta, vannoo Jumalan valtaistuimen kautta ja hänen kauttaan, joka sillä istuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Voi teitä, kirjanoppineet ja fariseukset, te tekopyhät, kun annatte kymmenykset mintuista, tilleistä ja kuminoista, mutta jätätte sikseen sen, mikä laissa on tärkeintä: oikeuden ja laupeuden ja uskon! Näitä tulisi noudattaa, eikä noitakaan jättää sikseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Te sokeat taluttajat, jotka siivilöitte hyttysen, mutta nielette kamelin!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Voi teitä, kirjanoppineet ja fariseukset, te tekopyhät, kun te puhdistatte maljan ja vadin ulkopuolen, mutta sisältä ne ovat täynnä ryöstöä ja hillittömyyttä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Sinä, sokea fariseus, puhdista ensin maljan ja vadin sisäpuoli, että sen ulkopuolikin tulisi puhtaaksi!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Voi teitä, kirjanoppineet ja fariseukset, te tekopyhät, kun olette valkoisiksi kalkittujen hautojen kaltaisia. Ulkoa ne kyllä näyttävät kauniilta, mutta ovat sisältä täynnä kuolleiden luita ja kaikkea saastaista!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Samoin tekin ulkoa kyllä näytätte ihmisten silmissä vanhurskailta, mutta sisältä olette täynnä teeskentelyä ja laittomuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Voi teitä, kirjanoppineet ja fariseukset, te tekopyhät, kun rakennatte profeettojen hautoja ja kaunistatte vanhurskasten hautakammioita,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'ja sanotte: \'Jos olisimme eläneet isiemme päivinä, emme olisi olleet osallisia heidän kanssaan profeettojen vereen\'!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Te siis todistatte itsestänne, että olette niiden lapsia, jotka tappoivat profeetat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'Täyttäkää siis isienne mitta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Te käärmeet, te kyykäärmeitten sikiöt, miten pakenette helvetin tuomiota?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Sen tähden, katso, minä lähetän luoksenne profeettoja ja viisaita ja kirjanoppineita. Heitä tapatte ja ristiinnaulitsette, ja toisia heistä ruoskitte synagogissanne ja vainoatte kaupungista kaupunkiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'jotta päällenne tulisi kaikki se vanhurskas veri, joka maan päällä on vuodatettu vanhurskaan Aabelin verestä Sakariaan, Barakiaan pojan, vereen asti, jonka tapoitte temppelin ja alttarin välillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Totisesti sanon teille: tämä kaikki on tuleva tämän sukukunnan päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jerusalem, Jerusalem, sinä, joka tapat profeetat ja kivität ne, jotka ovat luoksesi lähetetyt, kuinka usein olenkaan tahtonut koota lapsesi, niin kuin kana kokoaa poikasensa siipiensä alle! Mutta ette ole tahtoneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Katso, \'teidän huoneenne on tuleva autioksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Sillä sanon teille: tästedes ette näe minua, ennen kuin sanotte: \'Siunattu olkoon hän, joka tulee Herran nimeen.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Jeesus lähti ulos pyhäköstä ja meni pois; ja hänen opetuslapsensa tulivat hänen luokseen näyttämään hänelle pyhäkön rakennuksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Hän vastasi ja sanoi heille: \"Ettekö näe näitä kaikkia? Totisesti minä sanon teille: tähän ei ole jäävä kiveä kiven päälle maahan hajottamatta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Hänen istuessaan Öljymäellä opetuslapset tulivat erikseen hänen luokseen ja sanoivat: \"Sano meille: milloin se tapahtuu, ja mikä on tulemuksesi ja maailman lopun merkki?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Jeesus vastasi ja sanoi heille: \"Katsokaa, ettei kukaan teitä eksytä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Sillä monta tulee nimessäni sanoen: \'Minä olen Kristus\', ja he eksyttävät monta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Tulette kuulemaan taisteluiden ääniä ja sanomia sodista; katsokaa, ettette pelästy. Sillä näin täytyy tapahtua, mutta tämä ei ole vielä loppu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Sillä kansa nousee kansaa vastaan ja valtakunta valtakuntaa vastaan, ja nälänhätää ja maanjäristyksiä tulee paikoin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Mutta kaikki tämä on synnytystuskien alkua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Silloin teitä annetaan vaivaan, ja teitä tapetaan, ja joudutte kaikkien kansojen vihattaviksi minun nimeni tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'Silloin monet lankeavat pois, ja antavat toisensa ilmi ja vihaavat toinen toistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'Monta väärää profeettaa nousee, ja he eksyttävät monta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'Sen tähden, että laittomuus lisääntyy, kylmenee useimpien rakkaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Mutta se, joka vahvana pysyy loppuun asti, pelastuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Tämä valtakunnan evankeliumi saarnataan kaikessa maailmassa todistukseksi kaikille kansoille; ja sitten tulee loppu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Kun siis näette hävityksen kauhistuksen, josta on puhuttu profeetta Danielin kautta, seisovan pyhässä paikassa – joka tämän lukee, se ymmärtäköön –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'silloin ne, jotka Juudeassa ovat, paetkoot vuorille;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'joka on katolla, älköön astuko alas noutamaan, mitä hänen huoneessaan on,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'ja joka on pellolla, älköön palatko takaisin noutamaan viittaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Voi raskaana olevia ja imettäviä niinä päivinä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Mutta rukoilkaa, ettei teidän pakonne tapahtuisi talvella eikä sapattina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'Sillä silloin on oleva suuri ahdistus, jonka kaltaista ei ole ollut maailman alusta hamaan tähän asti eikä milloinkaan tule.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'Ellei niitä päiviä olisi lyhennetty, ei mikään liha pelastuisi, mutta valittujen tähden ne päivät lyhennetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Jos silloin joku sanoo teille: \'Katso, täällä on Kristus\', tai: \'Tuolla\', älkää uskoko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Sillä vääriä kristuksia ja vääriä profeettoja nousee, ja he tekevät suuria tunnustekoja ja ihmeitä, niin että eksyttävät, jos se olisi mahdollista, valitutkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Katso, olen sen teille edeltä sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Sen tähden, jos teille sanotaan: \'Katso, hän on erämaassa\', älkää menkö sinne, tai: \'Katso, hän on sisällä huoneessa\', älkää uskoko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Sillä niin kuin salama leimahtaa idästä ja näkyy länteen asti, niin on Ihmisen Pojan tulemus oleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Missä raato on, sinne korppikotkat kokoontuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Mutta heti niiden päivien ahdistuksen jälkeen aurinko pimenee, eikä kuu anna valoaan, ja tähdet putoavat taivaalta, ja taivaitten voimat järkkyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Silloin Ihmisen Pojan merkki näkyy taivaalla, ja silloin kaikki maan sukukunnat vaikeroivat. He näkevät Ihmisen Pojan tulevan taivaan pilvien päällä suurella voimalla ja kirkkaudella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Hän lähettää enkelinsä torven kovasti raikuessa, ja he kokoavat hänen valittunsa neljältä ilmansuunnalta taivasten ääristä toisiin ääriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Mutta oppikaa viikunapuusta vertaus: kun sen oksa on jo tuore ja lehdet puhkeavat, tiedätte, että kesä on lähellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'Samoin myös, kun näette tämän kaiken, tietäkää, että se on lähellä, aivan ovella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Totisesti sanon teille: tämä sukukunta ei katoa, ennen kuin kaikki nämä tapahtuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Taivas ja maa katoavat, mutta minun sanani eivät katoa koskaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Mutta siitä päivästä ja hetkestä ei tiedä kukaan, eivät taivasten enkelit, vaan Isä yksin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Sillä niin kuin oli Nooan päivinä, niin on Ihmisen Pojan tulemus oleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Sillä niin kuin ihmiset olivat niinä päivinä ennen vedenpaisumusta: söivät ja joivat, menivät naimisiin ja antoivat tyttäriään vaimoiksi, aina siihen päivään asti, jona Nooa meni arkkiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'eivätkä tienneet, ennen kuin vedenpaisumus tuli ja vei heidät kaikki. Niin on myös Ihmisen Pojan tulemus oleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Silloin on kaksi miestä pellolla. Toinen korjataan talteen, ja toinen jätetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Kaksi naista on jauhamassa käsikivillä; toinen korjataan talteen, ja toinen jätetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Valvokaa siis, sillä ette tiedä, minä päivänä Herranne tulee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Mutta se tietäkää: jos perheenisäntä tietäisi, millä yövartiolla varas tulee, toki hän valvoisi eikä sallisi taloonsa murtauduttavan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Sen tähden olkaa tekin valmiit, sillä sinä hetkenä, jona ette luule, Ihmisen Poika tulee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Kuka siis on se uskollinen ja ymmärtäväinen palvelija, jonka hänen isäntänsä on asettanut pitämään huolta palvelusväestään ja antamaan heille ruuan ajallaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Autuas se palvelija, jonka hänen isäntänsä tullessaan havaitsee näin tekevän!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Totisesti sanon teille: hän asettaa hänet kaiken omaisuutensa hoitajaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Mutta jos paha palvelija sanoo sydämessään: \'Herrani viipyy\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'ja alkaa lyödä palvelustovereitaan sekä syö ja juo juopuneiden kanssa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'niin sen palvelijan isäntä tulee päivänä, jona hän ei odota, ja hetkenä, jota hän ei arvaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'ja hakkaa hänet kappaleiksi ja määrää hänelle saman osan kuin tekopyhille. Siellä on oleva itku ja hammasten kiristys.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, '\"Silloin on taivasten valtakunta oleva kymmenen neitsyen kaltainen, jotka ottivat lamppunsa ja lähtivät ottamaan ylkää vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Mutta viisi heistä oli ymmärtäväistä ja viisi tyhmää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Tyhmät ottivat lamppunsa, mutta eivät ottaneet öljyä mukaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'Mutta ymmärtäväiset ottivat öljyä astioihinsa sekä lamppunsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Yljän viipyessä heille kaikille tuli uni, ja he nukkuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Mutta keskellä yötä kuului huuto: \'Katso, ylkä tulee! Tulkaa ottamaan häntä vastaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Silloin kaikki nämä neitsyet nousivat ja laittoivat lamppunsa kuntoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Tyhmät sanoivat ymmärtäväisille: \'Antakaa meille öljyänne, sillä lamppumme sammuvat.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Mutta ymmärtäväiset vastasivat ja sanoivat: \'Emme voi, se ei riitä meille ja teille. Menkää ennemmin myyjien luo ostamaan itsellenne.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Mutta heidän lähdettyään ostamaan ylkä tuli, ja ne, jotka olivat valmiit, menivät hänen kanssaan häihin, ja ovi suljettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Myöhemmin toisetkin neitsyet tulivat ja sanoivat: \'Herra, Herra, avaa meille!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Mutta hän vastasi ja sanoi: \'Totisesti sanon teille: en tunne teitä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Valvokaa siis, sillä ette tiedä päivää ettekä hetkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Sillä kun eräs mies oli lähtemässä ulkomaille, hän kutsui palvelijansa ja uskoi heille omaisuutensa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'yhdelle hän antoi viisi talenttia, toiselle kaksi ja kolmannelle yhden, kullekin hänen kykynsä mukaan, ja lähti heti muille maille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Se, joka oli saanut viisi talenttia, meni ja asioi niillä ja voitti toiset viisi talenttia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Samoin kaksi talenttia saanut voitti toiset kaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Mutta yhden talentin saanut meni pois ja kaivoi kuopan maahan ja kätki siihen isäntänsä hopean.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Pitkän ajan kuluttua näiden palvelijoiden isäntä palasi ja ryhtyi tilintekoon heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Se, joka oli saanut viisi talenttia, tuli ja toi toiset viisi talenttia ja sanoi: \'Herra, viisi talenttia sinä uskoit minulle, katso, toiset viisi talenttia olen niillä voittanut.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Hänen isäntänsä sanoi hänelle: \'Hyvä on, sinä hyvä ja uskollinen palvelija. Vähässä olet ollut uskollinen, panen sinut paljon haltijaksi. Tule herrasi iloon.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Myös se, joka oli saanut kaksi talenttia, tuli ja sanoi: \'Herra, kaksi talenttia sinä minulle uskoit, katso, toiset kaksi talenttia minä olen niillä voittanut.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Hänen isäntänsä sanoi hänelle: \'Hyvä on, sinä hyvä ja uskollinen palvelija. Vähässä olet ollut uskollinen, panen sinut paljon haltijaksi. Tule herrasi iloon.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Myös se, joka oli saanut yhden talentin, tuli ja sanoi: \'Herra, minä tiesin sinut kovaksi mieheksi. Leikkaat sieltä, mihin et ole kylvänyt, ja kokoat sieltä, missä et ole viskannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'Peloissani menin ja kätkin talenttini maahan; katso, tässä on omasi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Mutta hänen isäntänsä vastasi ja sanoi hänelle: \'Sinä paha ja laiska palvelija! Tiesit minun leikkaavan sieltä, mihin en ole kylvänyt, ja kokoavan sieltä, missä en ole viskannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Sinun olisi siis pitänyt jättää rahani rahanvaihtajille, niin minä tultuani olisin saanut omani takaisin korkoineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Ottakaa sen tähden häneltä talentti pois ja antakaa sille, jolla on kymmenen talenttia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Sillä jokaiselle, jolla on, annetaan, ja hänellä on oleva yllin kyllin. Mutta jolla ei ole, siltä otetaan pois sekin, mikä hänellä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Heittäkää tuo kelvoton palvelija ulos pimeyteen; siellä on oleva itku ja hammasten kiristys.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Mutta kun Ihmisen Poika tulee kirkkaudessaan ja kaikki enkelit hänen kanssaan, silloin hän istuutuu kirkkautensa valtaistuimelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'Hänen eteensä kootaan kaikki kansat, ja hän erottaa toiset toisista, niin kuin paimen erottaa lampaat vuohista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'Hän asettaa lampaat oikealle puolelleen, mutta vuohet vasemmalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Silloin Kuningas sanoo oikealla puolellaan oleville: \'Tulkaa, Isäni siunatut, ja perikää se valtakunta, joka on ollut teille valmistettuna maailman perustamisesta asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Sillä minun oli nälkä, ja annoitte minulle syödä, minun oli jano, ja annoitte minulle juoda, olin vieras, ja otitte minut huoneeseenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'Olin alaston, ja vaatetitte minut, sairastin, ja kävitte minua katsomassa, olin vankilassa, ja tulitte luokseni.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Silloin vanhurskaat vastaavat hänelle sanoen: \'Herra, milloin näimme sinut nälkäisenä ja ruokimme sinua, tai janoisena ja annoimme sinulle juoda?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Milloin näimme sinut vieraana ja otimme sinut huoneeseemme, tai alastomana ja vaatetimme sinut?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Milloin näimme sinun sairastavan tai olevan vankilassa ja tulimme luoksesi?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Kuningas vastaa ja sanoo heille: \'Totisesti sanon teille: kaiken, minkä olette tehneet yhdelle näistä vähimmistä veljistäni, sen olette tehneet minulle.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Silloin hän sanoo myös vasemmalla puolellaan oleville: \'Menkää pois luotani, te kirotut, siihen iankaikkiseen tuleen, joka on valmistettu perkeleelle ja hänen enkeleilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Sillä minun oli nälkä, ettekä antaneet minulle syödä; minun oli jano, ettekä antaneet minulle juoda;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'olin vieras, ettekä ottaneet minua huoneeseenne; olin alaston, ettekä vaatettaneet minua; sairaana ja vankilassa, ettekä te käyneet minua katsomassa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Silloin hekin vastaavat sanoen: \'Herra, milloin näimme sinut nälkäisenä, janoisena, vieraana, alastomana, sairaana tai vankilassa, emmekä sinua palvelleet?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Silloin hän vastaa heille ja sanoo: \'Totisesti sanon teille: kaiken, minkä olette jättäneet tekemättä yhdelle näistä vähimmistä, sen olette jättäneet tekemättä minulle.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'Nämä menevät pois iankaikkiseen rangaistukseen, mutta vanhurskaat iankaikkiseen elämään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'Tapahtui, kun Jeesus oli lopettanut kaikki nämä puheet, että hän sanoi opetuslapsilleen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, '\"Te tiedätte, että kahden päivän perästä on pääsiäinen; silloin Ihmisen Poika annetaan ristiinnaulittavaksi.\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Silloin ylipapit ja kansan vanhimmat kokoontuivat Kaifas-nimisen ylipapin palatsiin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'ja neuvottelivat, kuinka ottaisivat Jeesuksen kiinni kavaluudella ja tappaisivat hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Mutta he sanoivat: \"Ei juhlan aikana, ettei syntyisi meteliä kansassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Kun Jeesus oli Betaniassa spitaalisen Simonin asunnossa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'tuli hänen luokseen nainen, mukanaan alabasteripullo, jossa oli kallisarvoista voidetta, ja vuodatti sen Jeesuksen päähän hänen ollessaan aterialla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Mutta sen nähdessään hänen opetuslapsensa närkästyivät ja sanoivat: \"Mitä varten tämä haaskaus?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Olisihan sen voinut myydä kalliilla hinnalla ja antaa köyhille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Kun Jeesus sen huomasi, hän sanoi heille: \"Miksi pahoitatte naisen mielen? Sillä hän teki hyvän työn minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Köyhiä teillä on aina keskuudessanne, mutta minua teillä ei ole aina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Sillä kun hän valoi tämän voiteen ruumiilleni, hän teki sen hautaamistani varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Totisesti sanon teille: missä ikinä kaikessa maailmassa saarnataan tämä evankeliumi, siellä sekin, minkä hän teki, on mainittava hänen muistokseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Silloin yksi niistä kahdestatoista, nimeltä Juudas Iskariot, meni ylipappien luo');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'ja sanoi: \"Mitä tahdotte antaa minulle, niin saatan hänet teidän käsiinne?\" He sopivat hänen kanssaan kolmestakymmenestä hopearahasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'Siitä alkaen hän etsi sopivaa aikaa kavaltaakseen hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Mutta ensimmäisenä happamattoman leivän päivänä opetuslapset tulivat Jeesuksen luo ja sanoivat: \"Mihin tahdot, että valmistamme pääsiäislampaan syödäksesi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Hän sanoi: \"Menkää kaupunkiin sen ja sen luo ja sanokaa hänelle: \'Opettaja sanoo: Aikani on lähellä; sinun luonasi syön pääsiäisaterian opetuslasteni kanssa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Opetuslapset tekivät, kuten Jeesus oli heitä käskenyt, ja valmistivat pääsiäislampaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Mutta kun ilta tuli, hän asettui aterialle kahdentoista opetuslapsensa kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'Heidän syödessään hän sanoi: \"Totisesti sanon teille: yksi teistä kavaltaa minut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Silloin he tulivat hyvin murheellisiksi ja rupesivat toinen toisensa perästä sanomaan hänelle: \"Herra, enhän minä se ole?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'Hän vastasi ja sanoi: \"Se, joka pisti kanssani kätensä vatiin, kavaltaa minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Ihmisen Poika tosin menee pois, kuten hänestä on kirjoitettu, mutta voi sitä ihmistä, jonka kautta Ihmisen Poika kavalletaan! Parempi olisi sille ihmiselle, ettei hän olisi syntynyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Juudas, joka hänet kavalsi, vastasi ja sanoi: \"Rabbi, enhän minä se ole?\" Hän sanoi hänelle: \"Sinä sen sanoit.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Heidän syödessään Jeesus otti leivän, siunasi, mursi ja antoi opetuslapsilleen ja sanoi: \"Ottakaa ja syökää; tämä on minun ruumiini.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Hän otti maljan, kiitti, antoi heille ja sanoi: \"Juokaa tästä, te kaikki;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'sillä tämä on minun vereni, liiton veri, joka monen edestä vuodatetaan syntien anteeksiantamiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Mutta sanon teille: tästedes en juo tätä viinipuun antia ennen kuin sinä päivänä, jona juon sitä uutena kanssanne Isäni valtakunnassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'Veisattuaan kiitosvirren he lähtivät Öljymäelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Silloin Jeesus sanoi heille: \"Tänä yönä te kaikki loukkaannutte minuun, sillä kirjoitettu on: \'Minä lyön paimenta, ja lauman lampaat hajotetaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Mutta ylösnoustuani minä menen teidän edellänne Galileaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Pietari vastasi ja sanoi hänelle: \"Vaikka kaikki loukkaantuisivat sinuun, minä en koskaan loukkaannu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Jeesus sanoi hänelle: \"Totisesti sanon sinulle: tänä yönä, ennen kuin kukko laulaa, kolmesti minut kiellät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Pietari sanoi hänelle: \"Vaikka minun pitäisi kuolla kanssasi, en sittenkään sinua kiellä.\" Samoin sanoivat myös kaikki muut opetuslapset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Sitten Jeesus tuli heidän kanssaan Getsemane-nimiselle maatilalle; ja hän sanoi opetuslapsilleen: \"Istukaa tässä, sillä aikaa kun menen ja rukoilen tuolla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Hän otti mukaansa Pietarin ja ne kaksi Sebedeuksen poikaa. Murhe alkoi vaivata häntä, ja hän alkoi tulla tuskaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Silloin hän sanoi heille: \"Sieluni on syvästi murheellinen, kuolemaan asti; olkaa tässä ja valvokaa kanssani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'Hän meni vähän edemmäksi, lankesi kasvoilleen ja rukoili sanoen: \"Isäni, jos mahdollista on, menköön minulta pois tämä malja; ei kuitenkaan niin kuin minä tahdon, vaan niin kuin sinä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Hän tuli opetuslasten luo ja tapasi heidät nukkumasta ja sanoi Pietarille: \"Ette siis jaksaneet yhtä hetkeä valvoa kanssani!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Valvokaa ja rukoilkaa, ettette joutuisi kiusaukseen. Henki tosin on altis, mutta liha on heikko.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Taas hän meni pois toisen kerran ja rukoili sanoen: \"Isäni, jos tämä malja ei voi mennä ohitseni minun sitä juomattani, tapahtukoon sinun tahtosi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Tullessaan hän tapasi heidät taas nukkumasta, sillä uni painoi raskaasti heidän silmiään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Hän jätti heidät, meni taas ja rukoili kolmannen kerran ja sanoi samat sanat uudestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Sitten hän tuli opetuslasten luo ja sanoi heille: \"Te nukutte vielä ja lepäätte! Katso, hetki on lähellä, ja Ihmisen Poika annetaan syntisten käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Nouskaa, lähtekäämme; katso, se, joka minut kavaltaa, on lähellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Katso, hänen vielä puhuessaan tuli Juudas, yksi niistä kahdestatoista, ja hänen kanssaan suuri joukko miehiä ylipappien ja kansan vanhinten luota miekat ja seipäät käsissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Se, joka hänet kavalsi, oli antanut heille merkin sanoen: \"Se, jota tervehdin suudelmalla, hän se on. Ottakaa hänet kiinni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Heti hän meni Jeesuksen luo ja sanoi: \"Terve, rabbi!\" ja tervehti häntä suudelmalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Jeesus sanoi hänelle: \"Ystäväni, mitä varten tulit tänne?\" Silloin he tulivat Jeesuksen luo, kävivät häneen käsiksi ja ottivat hänet kiinni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'Katso, eräs niistä, jotka olivat Jeesuksen kanssa, ojensi kätensä, veti miekkansa ja iski ylipapin palvelijaa ja sivalsi häneltä korvan pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Silloin Jeesus sanoi hänelle: \"Pistä miekkasi tuppeen, sillä kaikki, jotka miekkaan tarttuvat, miekkaan hukkuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Vai luuletko, etten voisi rukoilla Isääni, että hän lähettäisi heti minulle enemmän kuin kaksitoista legioonaa enkeleitä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Mutta kuinka silloin toteutuisivat Kirjoitukset, jotka sanovat, että näin pitää tapahtua?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'Sillä hetkellä Jeesus sanoi joukolle: \"Niin kuin ryöväriä vastaan te olette lähteneet minua miekoin ja seipäin vangitsemaan. Joka päivä olen istunut pyhäkössä opettamassa, ettekä ole ottaneet minua kiinni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Mutta kaikki tämä on tapahtunut, että profeettojen Kirjoitukset kävisivät toteen.\" Silloin kaikki opetuslapset jättivät hänet ja pakenivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Mutta Jeesuksen kiinniottajat veivät hänet ylipapin, Kaifaksen, luo, minne kirjanoppineet ja vanhimmat olivat kokoontuneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Mutta Pietari seurasi häntä taaempana ylipapin esipihaan asti, meni sinne ja istuutui palvelijoiden joukkoon nähdäkseen lopun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Mutta ylipapit ja koko Neuvosto etsivät väärää todistusta Jeesusta vastaan tappaakseen hänet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'mutta eivät löytäneet, vaikka esille oli tullut monta väärää todistajaa. Mutta vihdoin tuli kaksi väärää todistajaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'ja he sanoivat: \"Tämä on sanonut: \'Minä voin hajottaa maahan Jumalan temppelin ja kolmessa päivässä sen rakentaa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Silloin ylipappi nousi ja sanoi hänelle: \"Etkö vastaa mitään siihen, mitä nämä todistavat sinua vastaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Mutta Jeesus oli vaiti. Ylipappi vastasi ja sanoi hänelle: \"Minä vannotan sinua elävän Jumalan kautta, että sanot meille, oletko sinä Kristus, Jumalan Poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Jeesus sanoi hänelle: \"Sinä sen sanoit. Mutta sanon teille: tästedes te saatte nähdä Ihmisen Pojan istuvan Voiman oikealla puolella ja tulevan taivaan pilvien päällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Silloin ylipappi repäisi vaatteensa ja sanoi: \"Hän on pilkannut Jumalaa. Mitä me enää todistajia tarvitsemme? Katso, nyt kuulitte hänen pilkkaamisensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Miten teistä on?\" He vastasivat sanoen: \"Hän on syyllinen kuolemaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Silloin he sylkivät häntä silmille ja löivät häntä nyrkillä kasvoihin, ja toiset sivalsivat häntä piiskalla');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'ja sanoivat: \"Profetoi meille, Kristus, kuka se on, joka sinua löi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Mutta Pietari istui ulkopuolella esipihassa. Hänen luokseen tuli muuan palvelustyttö ja sanoi: \"Sinäkin olit Jeesuksen, galilealaisen, seurassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Mutta hän kielsi kaikkien edessä ja sanoi: \"En ymmärrä, mitä sanot.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Kun hän oli mennyt ulos portille, näki hänet toinen nainen ja sanoi siellä oleville: \"Tämäkin oli Jeesuksen, Nasaretilaisen, seurassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Taas hän kielsi valalla vannoen: \"En tunne sitä miestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Vähän sen jälkeen tulivat ne, jotka siinä seisoivat, ja sanoivat Pietarille: \"Totisesti, sinä myös olet yksi heistä, sillä murteesikin ilmaisee sinut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Silloin hän rupesi kiroilemaan ja vannomaan: \"En tunne sitä miestä.\" Samassa lauloi kukko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Niin Pietari muisti Jeesuksen sanat, jotka hän oli sanonut: \"Ennen kuin kukko laulaa, sinä kiellät minut kolmesti.\" Hän meni ulos ja itki katkerasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Mutta aamun koittaessa kaikki ylipapit ja kansan vanhimmat pitivät neuvottelun Jeesusta vastaan tappaakseen hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'He sitoivat hänet, veivät pois ja antoivat hänet maaherran, Pilatuksen, käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Kun Juudas, hänen kavaltajansa, näki, että hänet oli tuomittu, silloin hän katui ja toi takaisin ne kolmekymmentä hopearahaa ylipapeille ja vanhimmille');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'ja sanoi: \"Minä tein synnin, kun kavalsin viattoman veren.\" Mutta he sanoivat: \"Mitä se meihin koskee? Katso itse eteesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Hän viskasi hopearahat temppeliin, lähti sieltä, meni pois ja hirttäytyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Ylipapit ottivat hopearahat ja sanoivat: \"Ei ole luvallista panna näitä temppelirahastoon, koska ne ovat veren hinta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Pidettyään neuvottelun he ostivat niillä savenvalajan pellon muukalaisten hautausmaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Sen tähden sitä peltoa kutsutaan vielä tänäkin päivänä Veripelloksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Silloin kävi toteen, mikä on puhuttu profeetta Jeremian kautta, joka sanoo: \"He ottivat ne kolmekymmentä hopearahaa, hinnan siitä arvioidusta miehestä, jonka he olivat israelilaisten puolesta arvioineet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'ja antoivat ne savenvalajan pellosta, niin kuin Herra oli minun kauttani käskenyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Jeesus seisoi maaherran edessä. Maaherra kysyi häneltä sanoen: \"Oletko sinä juutalaisten kuningas?\" Jeesus sanoi: \"Sinä sen sanot.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'Kun ylipapit ja vanhimmat häntä syyttivät, hän ei vastannut mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Silloin Pilatus sanoi hänelle: \"Etkö kuule, kuinka paljon he todistavat sinua vastaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Mutta hän ei vastannut yhteenkään hänen kysymykseensä, niin että maaherra suuresti ihmetteli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Oli tapana, että maaherra juhlan aikana vapautti kansalle yhden vangin, kenet he tahtoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Heillä oli silloin kuuluisa vanki, jota sanottiin Barabbaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Kun he nyt olivat koolla, Pilatus sanoi heille: \"Kummanko tahdotte, että vapautan teille, Barabbaan vai Jeesuksen, jota sanotaan Kristukseksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Sillä hän tiesi, että he kateudesta olivat antaneet hänet hänen käsiinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Mutta kun hän istui tuomarinistuimella, lähetti hänen vaimonsa hänelle sanan: \"Älköön sinulla olko mitään tekemistä tuon vanhurskaan [miehen] kanssa, sillä olen tänä yönä unessa paljon kärsinyt hänen tähtensä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Mutta ylipapit ja vanhimmat yllyttivät kansaa anomaan Barabbasta, mutta surmauttamaan Jeesuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Maaherra puhui heille ja sanoi: \"Kummanko näistä kahdesta tahdotte, että teille vapautan?\" He sanoivat: \"Barabbaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Pilatus sanoi heille: \"Mitä minun sitten on tehtävä Jeesukselle, jota sanotaan Kristukseksi?\" He sanoivat kaikki: \"Ristiinnaulittakoon!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Maaherra sanoi: \"Mitä pahaa hän sitten on tehnyt?\" Mutta he huusivat vielä kovemmin sanoen: \"Ristiinnaulittakoon!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Kun Pilatus näki, ettei mikään auttanut, vaan että meteli yhä yltyi, hän otti vettä, pesi kätensä kansan nähden ja sanoi: \"Viaton olen tämän vanhurskaan miehen vereen. Katsokaa itse eteenne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Kaikki kansa vastasi ja sanoi: \"Tulkoon hänen verensä meidän päällemme ja lastemme päälle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Silloin hän päästi heille Barabbaan, mutta Jeesuksen hän ruoskitti ja luovutti ristiinnaulittavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Silloin maaherran sotamiehet veivät Jeesuksen palatsiin ja keräsivät hänen ympärilleen koko kohortin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'He riisuivat hänet ja panivat hänen päälleen tulipunaisen viitan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'ja väänsivät orjantappuroista kruunun, panivat sen hänen päähänsä ja ruokokepin hänen oikeaan käteensä, polvistuivat hänen eteensä ja pilkkasivat häntä ja sanoivat: \"Terve, juutalaisten kuningas!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'He sylkivät häntä, ottivat ruokokepin ja löivät häntä päähän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Kun he olivat häntä pilkanneet, he riisuivat häneltä viitan, pukivat hänet hänen omiin vaatteisiinsa ja veivät hänet pois ristiinnaulittavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Mutta matkalla he tapasivat kyreneläisen miehen, jonka nimi oli Simon. Hänet he pakottivat kantamaan hänen ristiään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Tultuaan paikalle, jota sanotaan Golgataksi – se on: pääkallonpaikaksi –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'he tarjosivat hänelle juotavaksi sapella sekoitettua hapanviiniä, mutta maistettuaan hän ei tahtonut sitä juoda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Kun he olivat hänet ristiinnaulinneet, he jakoivat keskenään hänen vaatteensa heittäen niistä arpaa, jotta täyttyisi profeetan sana, joka sanoo: \"He jakoivat keskenään vaatteeni ja heittivät puvustani arpaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'He istuutuivat ja vartioivat häntä siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'He olivat panneet hänen päänsä yläpuolelle hänen [rangaistuksensa] syyn julki näin kirjoitettuna: \"Tämä on Jeesus, juutalaisten kuningas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Silloin ristiinnaulittiin hänen kanssaan kaksi ryöväriä, toinen oikealle ja toinen vasemmalle puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Mutta ohikulkijat herjasivat häntä, nyökyttivät päätään');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'ja sanoivat: \"Sinä, joka hajotat maahan temppelin ja kolmessa päivässä sen rakennat, auta itseäsi, jos olet Jumalan Poika, ja astu alas ristiltä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Samoin ylipapit, kirjanoppineet ja vanhimmat pilkkasivat häntä ja sanoivat:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, '\"Muita hän on auttanut, itseään hän ei voi auttaa. Onhan hän Israelin kuningas; astukoon nyt alas ristiltä, niin uskomme häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Hän on luottanut Jumalaan; vapahtakoon nyt Jumala hänet, jos on häneen mieltynyt, sillä hän on sanonut: \'Olen Jumalan Poika.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Samoin herjasivat häntä ryöväritkin, jotka olivat ristiinnaulitut hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Kuudennesta tunnista alkaen tuli pimeys yli koko maan, ja sitä kesti yhdeksänteen tuntiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Sitten yhdeksännen tunnin vaiheilla Jeesus huusi suurella äänellä sanoen: \"Eeli, Eeli, lama sabaktani?\" Se on: Jumalani, Jumalani, miksi minut hylkäsit?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Sen kuullessaan muutamat siinä seisovista sanoivat: \"Hän huutaa Eliaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Heti muuan heistä juoksi ja otti sienen, täytti sen hapanviinillä, pani sen ruokokepin päähän ja antoi hänelle juoda.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Mutta muut sanoivat: \"Annas, katsokaamme, tuleeko Elia pelastamaan häntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Jeesus huusi taas suurella äänellä ja antoi henkensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'Katso, temppelin esirippu repesi kahtia ylhäältä alas asti, maa järisi, ja kalliot halkesivat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'haudat aukenivat, ja monta nukkuneiden pyhien ruumista nousi ylös.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'He lähtivät haudoistaan ja tulivat hänen ylösnousemisensa jälkeen pyhään kaupunkiin ja ilmestyivät monille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Mutta kun sadanpäällikkö ja ne, jotka hänen kanssaan vartioivat Jeesusta, näkivät maanjäristyksen ja mitä muuta tapahtui, he pelästyivät suuresti ja sanoivat: \"Totisesti tämä oli Jumalan Poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Siellä oli monta naista, jotka olivat Galileasta seuranneet Jeesusta ja palvelleet häntä. He seisoivat taaempana katselemassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Heidän joukossaan oli Maria Magdaleena ja Maria, Jaakobin ja Jooseen äiti, ja Sebedeuksen poikien äiti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Illan tultua saapui rikas mies, Arimatiasta kotoisin, nimeltä Joosef, josta myös oli tullut Jeesuksen opetuslapsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Hän meni Pilatuksen luo ja pyysi Jeesuksen ruumista. Silloin Pilatus käski antaa sen hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Joosef otti ruumiin, kääri sen puhtaaseen liinavaatteeseen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'ja pani sen uuteen hautakammioonsa, jonka oli hakkauttanut kallioon. Sitten hän vieritti suuren kiven hautakammion ovelle ja lähti pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Siellä olivat Maria Magdaleena ja se toinen Maria, jotka istuivat vastapäätä hautaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Seuraavana päivänä, joka oli valmistuspäivän jälkeinen, ylipapit ja fariseukset kokoontuivat Pilatuksen luo');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'ja sanoivat: \"Herra, me muistamme sen villitsijän vielä eläessään sanoneen: \'Kolmen päivän kuluttua nousen ylös.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Käske siis vartioida hautaa tarkasti kolmanteen päivään asti, etteivät hänen opetuslapsensa tulisi ja varastaisi häntä ja sanoisi kansalle: \'Hän nousi kuolleista\', ja niin viimeinen villitys olisi pahempi kuin ensimmäinen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Pilatus sanoi heille: \" [Tuossa] teillä on vartio, menkää, vartioikaa niin hyvin kuin taidatte.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'He menivät ja turvasivat haudan lukitsemalla kiven sinetillä ja asettamalla vartion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Mutta kun sapatti oli päättynyt ja viikon ensimmäisen päivän aamu oli valkenemassa, tulivat Maria Magdaleena ja se toinen Maria katsomaan hautaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'Katso, tapahtui suuri maanjäristys, sillä Herran enkeli astui alas taivaasta, tuli ja vieritti kiven pois ovelta ja istui sille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Hän oli näöltään kuin salama, ja hänen vaatteensa olivat valkoiset kuin lumi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'Häntä pelästyen vartijat vapisivat ja kävivät ikään kuin kuolleiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Mutta enkeli puhutteli naisia ja sanoi heille: \"Älkää te pelätkö; sillä minä tiedän teidän etsivän Jeesusta, joka oli ristiinnaulittu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Hän ei ole täällä, sillä hän on noussut ylös, niin kuin hän sanoi. Tulkaa, katsokaa paikkaa, jossa Herra on maannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'Menkää kiireesti ja sanokaa hänen opetuslapsilleen, että hän on noussut kuolleista. Katso, hän menee edellänne Galileaan. Siellä te saatte hänet nähdä. Katso, olen sen teille sanonut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'He menivät kiireesti haudalta peloissaan ja suuresti iloiten ja juoksivat viemään sanaa hänen opetuslapsilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Mutta katso, Jeesus tuli heitä vastaan ja sanoi: \"Terve teille!\" He menivät hänen luokseen, syleilivät hänen jalkojaan ja kumartaen rukoilivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Silloin Jeesus sanoi heille: \"Älkää pelätkö; menkää ja viekää sana veljilleni, että he menisivät Galileaan: siellä he saavat minut nähdä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Mutta heidän mennessään, katso, muutamat vartiostosta tulivat kaupunkiin ja ilmoittivat ylipapeille kaiken, mitä oli tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Nämä kokoontuivat vanhinten kanssa, pitivät neuvottelun, antoivat sotilaille runsaat rahat');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'ja sanoivat: \"Sanokaa, että hänen opetuslapsensa tulivat yöllä ja veivät hänet varkain nukkuessamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'Jos tämä tulee maaherran korviin, lepytämme hänet ja järjestämme asian niin, että saatte olla huoleti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'He ottivat rahat ja tekivät, niin kuin heitä oli opetettu. Tätä puhetta on levitetty juutalaisten kesken, ja sitä kerrotaan vielä tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Mutta ne yksitoista opetuslasta vaelsivat Galileaan sille vuorelle, jonne Jeesus oli käskenyt heidän mennä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Kun he näkivät hänet, he kumartaen rukoilivat häntä, mutta muutamat epäilivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Jeesus tuli heidän luokseen, puhui heille ja sanoi: \"Minulle on annettu kaikki valta taivaassa ja maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Menkää siis ja tehkää kaikki kansat minun opetuslapsikseni, kastamalla heitä Isän ja Pojan ja Pyhän Hengen nimeen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'ja opettamalla heidät pitämään kaiken, minkä olen käskenyt teidän pitää. Katso, minä olen teidän kanssanne joka päivä maailman loppuun asti. Aamen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Jeesuksen Kristuksen, Jumalan Pojan, evankeliumin alku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Kuten Profeetoissa on kirjoitettuna: \"Katso, minä lähetän enkelini edelläsi, ja hän on valmistava tiesi sinun eteesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, '\"Airuen ääni kuuluu erämaassa: \'Valmistakaa Herralle tie, tehkää hänen polkunsa suoriksi\'\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Tapahtui, että Johannes kastoi erämaassa ja saarnasi mielenmuutoksen kastetta syntien anteeksiantamiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Koko Juudean maa ja kaikki jerusalemilaiset vaelsivat hänen luokseen, ja hän kastoi heitä Jordanin virrassa, kun he tunnustivat syntinsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Mutta Johanneksella oli puku kamelinkarvoista ja vyötäisillään nahkavyö, ja hän söi heinäsirkkoja ja metsähunajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Hän saarnasi sanoen: \"Minun jälkeeni tulee minua voimakkaampi, jonka sandaalien nyörejä en ole kelvollinen kumartuneena avaamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Minä kastan teidät vedellä, mutta hän kastaa teidät Pyhällä Hengellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'Tapahtui, että niinä päivinä Jeesus tuli Galilean Nasaretista, ja Johannes kastoi hänet Jordanissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Heti, vedestä noustessaan hän näki taivaitten aukeavan ja Hengen laskeutuvan kyyhkysenä päälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Taivaista tuli ääni: \"Sinä olet minun rakas Poikani, sinuun olen mieltynyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Heti sen jälkeen Henki ajoi hänet erämaahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Hän oli siellä erämaassa neljäkymmentä päivää saatanan kiusattavana, hän oli petojen seassa, ja enkelit palvelivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Mutta kun Johannes oli pantu vankeuteen, Jeesus meni Galileaan ja saarnasi Jumalan valtakunnan evankeliumia');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'ja sanoi: \"Aika on täyttynyt, ja Jumalan valtakunta on tullut lähelle. Muuttakaa mielenne ja uskokaa evankeliumi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Mutta kulkiessaan Galilean järven rantaa hän näki Simonin ja Andreaan, Simonin veljen, heittävän verkkoa järveen, sillä he olivat kalastajia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Jeesus sanoi heille: \"Seuratkaa minua, niin teen teistä ihmisten kalastajia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Heti he jättivät verkkonsa ja seurasivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'Kuljettuaan siitä vähän eteenpäin hän näki Jaakobin, Sebedeuksen pojan, ja Johanneksen, hänen veljensä, heidätkin veneessä, kunnostamassa verkkojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'Heti hän kutsui heidät, ja he jättivät isänsä, Sebedeuksen, palkkalaisineen veneeseen ja lähtivät seuraamaan häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'He saapuivat Kapernaumiin, ja hän meni heti sapattina synagogaan ja opetti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'He olivat hämmästyksissään hänen opetuksestaan, sillä hän opetti heitä niin kuin se, jolla on valta, eikä niin kuin kirjanoppineet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'Heidän synagogassaan oli mies, jossa oli saastainen henki, ja se huusi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'sanoen: \"Mitä sinulla on meidän kanssamme tekemistä, Jeesus Nasaretilainen? Oletko tullut meitä tuhoamaan? Tunnen sinut, kuka olet, sinä Jumalan Pyhä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Jeesus nuhteli sitä sanoen: \"Vaikene ja lähde hänestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Saastainen henki kouristi häntä ja lähti hänestä huutaen suurella äänellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'He hämmästyivät kaikki, niin että kyselivät toisiltaan sanoen: \"Mitä tämä on? Uusi, voimallinen oppi! Hän käskee saastaisia henkiäkin, ja ne tottelevat häntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'Hänen maineensa levisi heti koko ympäristöön, kaikkialle Galileaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'Tultuaan ulos synagogasta he menivät heti Simonin ja Andreaan taloon Jaakobin ja Johanneksen kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Simonin anoppi makasi sairaana kuumeessa, ja heti he puhuivat hänestä Jeesukselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Hän meni hänen luokseen ja nosti hänet ylös tarttuen hänen käteensä, ja kuume lähti hänestä, ja hän palveli heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Mutta illan tultua, kun aurinko oli laskenut, tuotiin hänen luokseen kaikki sairaat ja riivatut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'ja koko kaupunki oli kokoontunut oven eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'Hän paransi monta, jotka sairastivat monenlaisia tauteja, ja paljon riivaajia hän ajoi ulos eikä sallinut riivaajien puhua, koska ne tunsivat hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Varhain aamulla, kun vielä oli pimeä, hän nousi, lähti ulos ja meni autioon paikkaan, ja siellä hän rukoili.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Mutta Simon ja ne, jotka olivat hänen kanssaan, riensivät hänen jälkeensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'ja löydettyään hänet he sanoivat hänelle: \"Kaikki etsivät sinua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Hän sanoi heille: \"Menkäämme muualle, läheisiin kyliin, jotta sielläkin saarnaisin, sillä sitä varten olen tullut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'Hän meni ja saarnasi heidän synagogissaan koko Galileassa ja ajoi ulos riivaajat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Hänen luokseen tuli spitaalinen mies, rukoili häntä, polvistui ja sanoi hänelle: \"Jos tahdot, voit puhdistaa minut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Jeesuksen kävi häntä sääliksi, ja ojentaen kätensä hän kosketti häntä ja sanoi hänelle: \"Minä tahdon, puhdistu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'Hänen sanottuaan tämän spitaali heti lähti miehestä, ja hän puhdistui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Varoitettuaan ankarasti häntä hän laski hänet heti menemään');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'ja sanoi hänelle: \"Katso, ettet puhu kenellekään tästä mitään, vaan mene ja näytä itsesi papille ja uhraa puhdistumisestasi se, minkä Mooses on säätänyt, todistukseksi heille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Mutta mentyään pois tämä rupesi laajalti julistamaan ja levittämään asiasta tietoa, niin ettei Jeesus enää voinut julkisesti mennä kaupunkeihin, vaan oleskeli niiden ulkopuolella autioissa paikoissa, ja kaikkialta tultiin hänen luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Muutamien päivien kuluttua hän meni taas Kapernaumiin, ja kuultiin, että hän oli kotona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Silloin kokoontui heti paljon väkeä, niin etteivät he enää mahtuneet oven edustallekaan. Hän puhui heille sanaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'He olivat tulossa hänen luokseen ja tuomassa halvaantunutta, jota kantoi neljä miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Kun he kansanjoukon tähden eivät päässeet hänen luokseen, he purkivat katon siltä kohdalta, missä hän oli, ja kaivettuaan aukon laskivat alas vuoteen, jolla halvaantunut makasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Kun Jeesus näki heidän uskonsa, hän sanoi halvaantuneelle: \"Poikani, sinun syntisi ovat sinulle anteeksi annetut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Mutta siellä istui muutamia kirjanoppineita, ja he ajattelivat sydämessään:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, '\"Kuinka tämä tällä tavalla puhuu jumalanpilkkaa! Kuka voi antaa syntejä anteeksi paitsi Jumala yksin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Heti Jeesus tunsi hengessään, että he mielessään niin ajattelivat, ja sanoi heille: \"Miksi ajattelette sellaista sydämessänne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Kumpi on helpompaa, sanoa halvaantuneelle: \'Syntisi ovat anteeksi annetut\', vai sanoa: \'Nouse, ota vuoteesi ja kävele\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Mutta tietääksenne, että Ihmisen Pojalla on valta maan päällä antaa syntejä anteeksi, niin\" – hän sanoi halvaantuneelle –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, '\"sanon sinulle: nouse, ota vuoteesi ja mene kotiisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Hän nousi heti, otti vuoteensa ja meni ulos kaikkien editse, niin että kaikki hämmästyivät ja ylistivät Jumalaa sanoen: \"Tällaista emme ole ikinä nähneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Hän lähti taas pois ja kulki järven rantaa. Kaikki kansa tuli hänen luokseen, ja hän opetti heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Kulkiessaan ohi hän näki Leevin, Alfeoksen pojan, istumassa tulliasemalla ja sanoi hänelle: \"Seuraa minua.\" Tämä nousi ja seurasi häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Tapahtui hänen ollessaan aterialla hänen kodissaan, että myös monta publikaania ja syntistä aterioi Jeesuksen ja hänen opetuslastensa kanssa, sillä heitä oli paljon häntä seuraamassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Kun fariseukset ja kirjanoppineet näkivät, että hän söi syntisten ja publikaanien kanssa, he sanoivat hänen opetuslapsilleen: \"Miksi hän syö publikaanien ja syntisten kanssa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Sen kuullessaan Jeesus sanoi heille: \"Eivät terveet tarvitse parantajaa, vaan sairaat. En ole tullut kutsumaan vanhurskaita, vaan syntisiä mielenmuutokseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Johanneksen opetuslapset ja fariseusten opetuslapset paastosivat. Niin hänelle tultiin sanomaan: \"Miksi Johanneksen opetuslapset ja fariseusten opetuslapset paastoavat, mutta sinun opetuslapsesi eivät paastoa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Jeesus sanoi heille: \"Eiväthän häävieraat voi paastota silloin, kun ylkä on heidän kanssaan? Niin kauan kuin ylkä on heidän kanssaan, he eivät voi paastota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Mutta päivät tulevat, jolloin ylkä otetaan heiltä pois, ja silloin, niinä päivinä, he paastoavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Ei kukaan ompele vanuttamattomasta kankaasta paikkaa vanhaan vaatteeseen, muuten uusi paikka repii palan vanhasta vaatteesta, ja reikä tulee pahemmaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Eikä kukaan laske nuorta viiniä vanhoihin leileihin, muuten viini halkaisee leilit, ja viini vuotaa pois, ja leilit turmeltuvat, vaan nuori viini on laskettava uusiin leileihin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'Tapahtui, että hän sapattina kulki viljavainioiden halki, ja hänen opetuslapsensa rupesivat kulkiessaan poimimaan tähkiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Mutta fariseukset sanoivat hänelle: \"Katso, miksi he tekevät sapattina sitä, mikä ei ole luvallista?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Hän sanoi heille: \"Ettekö ole koskaan lukeneet, mitä Daavid teki, kun häneltä ja hänen tovereiltaan puuttui ruokaa ja heillä oli nälkä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'kuinka hän meni Jumalan huoneeseen ylipappi Abjatarin aikana ja söi näkyleivät, joita ei ollut lupa syödä muiden kuin pappien, ja antoi myös niille, jotka olivat hänen kanssaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Hän sanoi heille: \"Sapatti on ihmistä varten eikä ihminen sapattia varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'Niinpä Ihmisen Poika on sapatinkin herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Hän meni taas synagogaan, ja siellä oli mies, jonka käsi oli kuivettunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'He pitivät häntä silmällä, parantaisiko hän miehen sapattina, voidakseen nostaa syytteen häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Hän sanoi miehelle, jonka käsi oli kuivettunut: \"Nouse ja asetu esiin tähän keskelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Sitten hän sanoi heille: \"Kumpi on luvallista sapattina: tehdä hyvää vai tehdä pahaa, pelastaa sielu vai tappaa se?\" Mutta he olivat vaiti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Silloin hän katsahtaen ympärilleen loi vihassa silmänsä heihin murheellisena heidän sydämensä paatumuksen tähden, ja sanoi miehelle: \"Ojenna kätesi.\" Ja hän ojensi, ja hänen kätensä tuli ennalleen, terveeksi, kuten toinen käsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Mutta fariseukset lähtivät pois ja pitivät heti herodeslaisten kanssa neuvottelun häntä vastaan surmatakseen hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Mutta Jeesus vetäytyi opetuslapsineen järven rannalle, ja häntä seurasi suuri joukko kansaa Galileasta. Myös Juudeasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'Jerusalemista, Idumeasta, Jordanin tuolta puolen ja Tyyron ja Siidonin ympäristöstä tuli paljon kansaa hänen luokseen, kun he kuulivat, kuinka suuria tekoja hän teki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Hän sanoi opetuslapsilleen, että hänelle oli pidettävä vene varalla kansanjoukon tähden, ettei se ahdistaisi häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Sillä hän paransi monta, jonka tähden kaikki, joilla oli vaivoja, tungeksivat hänen päälleen koskettaakseen häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Kun saastaiset henget näkivät hänet, ne lankesivat hänen eteensä ja huusivat sanoen: \"Sinä olet Jumalan Poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Hän varoitti niitä ankarasti saattamasta häntä ilmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Hän nousi vuorelle ja kutsui luokseen ne, jotka hän itse tahtoi, ja he menivät hänen luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Hän asetti kaksitoista olemaan kanssaan ja lähettääkseen heidät saarnaamaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'ja heillä oli oleva valta parantaa sairauksia ja ajaa ulos riivaajia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Nämä kaksitoista hän asetti: Simonin, jolle hän antoi nimen Pietari,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'Jaakobin, Sebedeuksen pojan, Johanneksen, Jaakobin veljen, joille hän antoi nimen Boanerges, se on: ukkosenjylinän pojat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'Andreaan, Filippoksen, Bartolomeoksen, Matteuksen, Tuomaan, Jaakobin, Alfeoksen pojan, Taddeuksen, Simon Kananeuksen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'ja Juudas Iskariotin, saman, joka hänet kavalsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Sitten hän meni kotiin. Taas kokoontui paljon kansaa, niin etteivät he voineet syödäkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Kun hänen omaisensa sen kuulivat, he menivät ottamaan häntä huostaansa, sillä he sanoivat: \"Hän on poissa tolaltaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Mutta kirjanoppineet, jotka olivat tulleet Jerusalemista, sanoivat: \"Hänessä on Beelsebul\", ja: \"riivaajien päämiehen avulla hän ajaa ulos riivaajia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Hän kutsui heidät luokseen ja sanoi heille vertauksilla: \"Kuinka saatana voi ajaa ulos saatanan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Jos jokin valtakunta riitautuu itsensä kanssa, sellainen valtakunta ei voi pysyä pystyssä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'Jos talo riitautuu itsensä kanssa, sellainen talo ei voi pysyä pystyssä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Jos saatana nousee itseään vastaan ja riitautuu itsensä kanssa, hän ei voi pysyä, vaan hänen loppunsa on tullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Kukaan ei voi tunkeutua väkevän taloon ja ryöstää hänen tavaraansa, ellei hän ensin sido sitä väkevää ja vasta sitten ryöstä hänen taloaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Totisesti sanon teille: kaikki synnit annetaan ihmisten lapsille anteeksi, jumalanpilkatkin, kuinka paljon pilkannevatkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'Mutta se, joka pilkkaa Pyhää Henkeä, ei saa ikinä anteeksi, vaan on syypää iankaikkiseen syntiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Sillä he sanoivat: \"Hänessä on saastainen henki.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Hänen äitinsä ja veljensä tulivat, seisahtuivat ulkopuolelle ja lähettivät [erään miehen] hänen luokseen kutsumaan häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'Kansanjoukko istui hänen ympärillään, ja he sanoivat hänelle: \"Katso, äitisi ja veljesi ulkona kysyvät sinua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Hän vastasi heille sanoen: \"Kuka on minun äitini, ja ketkä ovat minun veljiäni?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Katsellen ympärilleen niihin, jotka istuivat hänen ympärillään, hän sanoi: \"Katso, äitini ja veljeni!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Sillä se, joka tekee Jumalan tahdon, on veljeni, sisareni ja äitini.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Sitten hän rupesi taas opettamaan järven rannalla. Hänen luokseen kokoontui paljon kansaa, jonka tähden hän astuttuaan veneeseen istui siinä järvellä, ja kaikki kansa oli maalla järven rannalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Hän opetti heitä monilla vertauksilla ja sanoi heille opettaessaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, '\"Kuulkaa! Katso, kylväjä lähti kylvämään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'Tapahtui hänen kylväessään, että osa putosi tien vierelle, ja taivaan linnut tulivat ja söivät sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Osa putosi kallioiselle paikalle, jossa sillä ei ollut paljon maata, ja se nousi heti oraalle, koska sillä ei ollut syvää maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'Mutta auringon noustua se paahtui, ja kun sillä ei ollut juurta, se kuivui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Osa putosi orjantappuroihin, ja orjantappurat nousivat ja tukahduttivat sen, eikä se tehnyt hedelmää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Mutta osa putosi hyvään maahan, nousi oraalle, kasvoi, antoi sadon ja tuotti mikä kolmekymmentä-, mikä kuusikymmentä- ja mikä satakertaisen sadon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Hän sanoi: \"Jolla on korvat kuulla, se kuulkoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Kun hän oli yksin, niin ne, jotka olivat hänen ympärillään, sekä ne kaksitoista kysyivät häneltä tästä vertauksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Hän sanoi heille: \"Teille on annettu tuntea Jumalan valtakunnan salaisuus, mutta noille ulkopuolella oleville kaikki tulee vertauksissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'että he näkisivät näkemällä, eivätkä huomaisi, ja kuulisivat kuulemalla, eivätkä ymmärtäisi, etteivät kääntyisi ja saisi anteeksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Hän sanoi heille: \"Jos ette käsitä tätä vertausta, kuinka sitten voitte ymmärtää kaikki muut vertaukset?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Kylväjä kylvää sanan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Mitkä tien vierelle putosivat, ovat niitä, joihin sana kylvetään, mutta kun he sen kuulevat, saatana tulee heti ja ottaa pois heihin kylvetyn sanan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'Mitkä kalliolle kylvettiin, ovat ne, jotka, kun kuulevat sanan, ottavat sen heti ilolla vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'mutta heillä ei ole juurta itsessään, vaan he kestävät ainoastaan jonkin aikaa. Kun sitten tulee ahdistus tai vaino sanan tähden, he heti lankeavat pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'Toisia ovat orjantappuroihin kylvetyt. Nämä ovat niitä, jotka kuulevat sanan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'mutta tämän maailman huolet ja rikkauden petollisuus ja muut himot pääsevät valtaan ja tukahduttavat sanan, ja se jää hedelmättömäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Mitkä hyvään maahan kylvettiin, ovat niitä, jotka kuulevat sanan ja ottavat sen vastaan ja kantavat hedelmän, mikä kolmekymmentä-, mikä kuusikymmentä-, mikä satakertaisen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Hän sanoi heille: \"Eihän lamppua oteta esiin pantavaksi vakan alle tai vuoteen alle? Eikö lampunjalkaan pantavaksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Sillä ei mikään ole salattua muuta varten, kuin jotta se tulisi ilmi, eikä kätkettynä muuta varten kuin tullakseen ilmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Jos jollakulla on korvat kuulla, kuulkoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'Hän sanoi heille: \"Katsokaa, mitä kuulette. Millä mitalla mittaatte, sillä teille mitataan, vieläpä teille, jotka tämän kuulette, lisätäänkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Sillä sille, jolla on, annetaan, mutta siltä, jolla ei ole, otetaan pois sekin, mitä hänellä on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'Hän sanoi: \"Niin on Jumalan valtakunta, kuin jos mies kylvää siemenen maahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'ja hän nukkuu, ja hän nousee, öin ja päivin, ja siemen orastaa ja kasvaa, hän ei itse tiedä, miten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Sillä itsestään maa tuottaa viljan: ensin korren, sitten tähkän, sitten täyden jyvän tähkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'Mutta kun vilja on tuleentunut, hän lähettää heti sinne sirpin, sillä korjuuaika on käsillä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'Hän sanoi: \"Mihin vertaamme Jumalan valtakunnan, eli mitä vertausta siitä käytämme?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Se on kuin sinapinsiemen, joka, kun se kylvetään maahan, on pienin kaikista kylvösiemenistä maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'Mutta kun se on kylvetty, se nousee ja tulee suurimmaksi kaikista puutarhakasveista ja tekee suuria oksia, niin että taivaan linnut voivat tehdä pesänsä sen varjoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'Monilla tällaisilla vertauksilla hän puhui heille sanaa, sen mukaan kuin he kykenivät kuulemaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'ja ilman vertausta hän ei puhunut heille. Mutta opetuslapsilleen hän selitti kaikki, kun he olivat muista erillään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Sinä päivänä hän illan tultua sanoi heille: \"Lähtekäämme yli toiselle rannalle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Niin he laskivat kansan luotaan ja ottivat hänet mukaansa hänen ollessaan jo veneessä, ja muitakin veneitä oli hänen seurassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Nousi kova myrskytuuli, ja aallot syöksyivät yli veneeseen, niin että se jo täyttyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'Mutta itse hän oli veneen perällä ja nukkui nojaten päänaluseen. Niin he herättivät hänet ja sanoivat hänelle: \"Opettaja, etkö välitä siitä, että hukumme?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Herättyään hän nuhteli tuulta ja sanoi järvelle: \"Vaikene, ole hiljaa.\" Tuuli asettui, ja tuli suuri tyyneys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Hän sanoi heille: \"Miksi olette sillä tavoin pelkureita? Kuinka teillä ei ole uskoa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Suuri pelko valtasi heidät, ja he sanoivat toisilleen: \"Kuka tämä onkaan, kun sekä tuuli että meri häntä tottelevat?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'He tulivat järven toiselle puolelle gadaralaisten alueelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Hänen lähdettyään veneestä häntä vastaan tuli heti haudoista mies, joka oli saastaisen hengen vallassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'Hän piti asuntoaan haudoissa, eikä kukaan enää voinut sitoa häntä kahleillakaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'Sillä hänet oli monta kertaa sidottu jalkanuoriin ja kahleisiin, mutta hän oli särkenyt kahleet ja katkonut jalkanuorat, eikä kukaan kyennyt häntä hillitsemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'Hän oleskeli aina yötä päivää vuorilla ja haudoissa huutaen ja runnellen itseään kivillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Kun hän näki Jeesuksen kaukaa, hän juoksi ja kumartui hänen eteensä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'ja huutaen suurella äänellä sanoi: \"Mitä sinulla on minun kanssani tekemistä, Jeesus, Jumalan, Korkeimman, Poika? Vannotan sinua Jumalan kautta, älä vaivaa minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Sillä hän oli sanomaisillaan sille: \"Lähde ulos miehestä, sinä, saastainen henki.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Jeesus kysyi siltä: \"Mikä on nimesi?\" Se vastasi hänelle ja sanoi hänelle: \"Legioona on nimeni, sillä meitä on monta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'Se pyysi pyytämällä häneltä, ettei hän lähettäisi niitä pois siltä seudulta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Niin siellä oli vuoren rinteellä suuri sikalauma laitumella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'Kaikki riivaajat pyysivät häntä sanoen: \"Lähetä meidät sikoihin, jotta menisimme niihin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Hän salli sen niille. Saastaiset henget lähtivät miehestä ja menivät sikoihin. Silloin lauma, noin kaksituhatta sikaa, syöksyi jyrkännettä alas järveen, ja ne hukkuivat järveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Mutta sikopaimenet pakenivat ja kertoivat siitä kaupungissa ja maalla, ja kansa lähti katsomaan, mitä oli tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'He tulivat Jeesuksen luo ja näkivät riivatun, jossa oli ollut legioona riivaajia, istuvan puettuna ja järjissään, ja he pelästyivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Näkijät kertoivat näille, mitä oli tapahtunut riivatulle ja kuinka sikojen oli käynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Niin ihmiset alkoivat pyytää häntä poistumaan heidän alueeltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Hänen astuessaan veneeseen riivaajien vallassa ollut pyysi häneltä saada olla hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Mutta Jeesus ei sallinut sitä, vaan sanoi hänelle: \"Mene kotiisi omaistesi luo ja kerro heille, kuinka suuria tekoja Herra on sinulle tehnyt ja kuinka hän on sinua armahtanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Hän lähti ja rupesi Dekapolin alueella julistamaan, kuinka suuria tekoja Jeesus oli hänelle tehnyt, ja kaikki ihmettelivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Kun Jeesus oli veneellä kulkenut takaisin toiselle puolelle, paljon kansaa kokoontui hänen luokseen, ja hän oli järven rannalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Katso, muuan synagogan esimies, nimeltä Jairos, tuli ja lankesi hänet nähdessään hänen jalkojensa juureen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'pyysi häntä hartaasti ja sanoi: \"Pieni tyttäreni on kuolemaisillaan, tule ja pane kätesi hänen päälleen, jotta hän tulisi terveeksi ja jäisi eloon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Hän lähti hänen kanssaan. Häntä seurasi suuri kansan paljous, ja he tunkeutuivat hänen ympärilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Siellä oli nainen, joka oli sairastanut verenjuoksua kaksitoista vuotta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'ja paljon kärsinyt monen lääkärin käsissä ja kuluttanut kaiken omaisuutensa saamatta mitään apua, pikemminkin käyden huonommaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Tämä oli kuullut Jeesuksesta ja tuli kansanjoukossa takaapäin ja koski hänen viittaansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'sillä hän sanoi: \"Jos vain kosken hänen vaatteisiinsa, tulen terveeksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'Heti hänen verensä lähde kuivui, ja hän tunsi ruumiissaan, että oli parantunut vaivastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Heti kun Jeesus tunsi itsessään, että voimaa oli lähtenyt hänestä, hän kääntyi väkijoukossa ja sanoi: \"Kuka koski vaatteisiini?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Hänen opetuslapsensa sanoivat hänelle: \"Sinä näet kansanjoukon tungeskelevan ympärilläsi ja sanot: \'Kuka minuun koski?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Mutta hän katseli ympärilleen nähdäkseen, kuka sen oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Nainen pelkäsi ja vapisi, koska hän tiesi, mitä hänelle oli tapahtunut, ja tuli, lankesi maahan hänen eteensä ja sanoi hänelle koko totuuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Mutta Jeesus sanoi hänelle: \"Tyttäreni, sinun uskosi on tehnyt sinut terveeksi. Mene rauhaan ja ole terve vaivastasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Hänen vielä puhuessaan tultiin sanomaan synagogan esimiehen kotoa: \"Tyttäresi kuoli, miksi enää opettajaa vaivaat?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Mutta Jeesus kuuli heti, mitä puhuttiin, ja sanoi synagogan esimiehelle: \"Älä pelkää, usko ainoastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'Hän ei sallinut kenenkään muun seurata mukanaan kuin Pietarin, Jaakobin ja Johanneksen, Jaakobin veljen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'He tulivat synagogan esimiehen taloon, ja hän näki hälisevän joukon sekä itkeviä ja suureen ääneen vaikeroivia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'Käydessään sisään hän sanoi heille: \"Miksi hälisette ja itkette? Lapsi ei ole kuollut, vaan nukkuu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'He nauroivat hänelle. Mutta hän ajoi kaikki ulos ja otti mukaansa lapsen isän ja äidin sekä ne, jotka olivat hänen kanssaan, ja meni sisälle sinne, missä lapsi makasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'Hän tarttui lapsen käteen ja sanoi hänelle: \"Talita kuum!\" Se on käännettynä: Tyttö, sanon sinulle, nouse.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'Heti tyttö nousi ja käveli. Sillä hän oli kaksitoistavuotias. Ja he joutuivat suuren hämmästyksen valtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Hän kielsi kovasti heitä antamasta kenellekään tietoa tästä ja käski antaa hänelle syötävää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Hän lähti sieltä ja meni kotikaupunkiinsa, ja hänen opetuslapsensa seurasivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Kun sapatti oli tullut, hän alkoi opettaa synagogassa. Häntä kuunnellessaan monet hämmästyivät ja sanoivat: \"Mistä tällä on kaikki tämä, ja mikä on se viisaus, joka on hänelle annettu? Mitä ovat sellaiset voimalliset teot, jotka tapahtuvat hänen kättensä kautta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Eikö tämä ole se rakentaja, Marian poika ja Jaakobin, Jooseen, Juudaan ja Simonin veli? Eivätkö hänen sisarensa ole täällä meidän parissamme?\" Ja he loukkaantuivat häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Jeesus sanoi heille: \"Profeetta ei ole halveksittu muualla kuin kotikaupungissaan, sukulaistensa kesken ja kodissaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Eikä hän voinut tehdä siellä yhtään voimallista tekoa, paitsi että paransi joitakuita harvoja sairaita panemalla kätensä heidän päälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'Hän ihmetteli heidän epäuskoaan. Hän kulki ympäristön kylät ja opetti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Hän kutsui ne kaksitoista ja alkoi lähettää heitä kaksittain ja antoi heille vallan saastaisiin henkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'Hän sääti heille, etteivät saaneet ottaa matkalle kuin yhden sauvan, ei leipää, ei laukkua eikä rahaa vyöhön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'He saivat kuitenkin sitoa sandaalit jalkaansa, mutta eivät pukea kahta paitaa päälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Hän sanoi heille: \"Missä tulette taloon, jääkää sinne, kunnes lähdette pois siltä paikkakunnalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'Missä teitä ei oteta vastaan eikä teitä kuulla, menkää sieltä pois ja pudistakaa tomu jalkojenne alta todistukseksi heille. Totisesti sanon teille: Helpompi on Sodoman tai Gomorran olla tuomiopäivänä kuin tuon kaupungin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'He lähtivät ja saarnasivat, jotta nuo muuttaisivat mielensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'He ajoivat ulos monta riivaajaa ja voitelivat monta sairasta öljyllä ja paransivat heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Kuningas Herodes sai kuulla hänestä, sillä hänen nimensä oli tullut tunnetuksi, ja hän sanoi: \"Johannes Kastaja on noussut kuolleista, ja sen tähden nämä voimat vaikuttavat hänessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Mutta toiset sanoivat: \"Se on Elia.\" Toiset taas sanoivat: \"Se on profeetta, niin kuin joku profeetoista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Mutta kun Herodes sen kuuli, hän sanoi: \"Johannes, jonka mestautin, on noussut kuolleista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Sillä hän, Herodes, oli lähettänyt ottamaan kiinni Johanneksen, sitonut ja pannut hänet vankilaan veljensä Filippoksen vaimon, Herodiaan, tähden. Sillä Herodes oli nainut hänet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'ja Johannes oli sanonut Herodekselle: \"Sinun ei ole lupa pitää veljesi vaimoa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Herodias piti vihaa häntä vastaan ja tahtoi tappaa hänet, mutta ei voinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Sillä Herodes pelkäsi Johannesta, koska tiesi hänet vanhurskaaksi ja pyhäksi mieheksi, ja suojeli häntä. Hän teki monia asioita, joita hän häneltä kuuli, ja kuunteli häntä mielellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Niin tuli sopiva päivä, kun Herodes syntymäpäivänään piti pitoja ylimyksilleen, tuhannenpäälliköille ja Galilean ensimmäisille miehille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'Herodiaan tytär tuli sisälle ja tanssi, ja se miellytti Herodesta ja hänen pöytävieraitaan. Kuningas sanoi tytölle: \"Ano minulta, mitä ikinä tahdot, niin annan sinulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Hän vannoi tytölle: \"Mitä ikinä minulta anot, sen annan sinulle, vaikka puolet valtakuntaani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Hän meni ulos ja sanoi äidilleen: \"Mitä pyydän?\" Tämä sanoi: \"Johannes Kastajan päätä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Hän meni heti kiireen vilkkaa sisälle kuninkaan luo, pyysi ja sanoi: \"Tahdon, että nyt heti annat minulle lautasella Johannes Kastajan pään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Silloin kuningas tuli hyvin murheelliseksi, mutta valansa ja pöytävieraiden tähden hän ei tahtonut hylätä hänen pyyntöään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Heti kuningas lähetti pyövelin ja käski tuoda Johanneksen pään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'Pyöveli lähti ja löi häneltä pään poikki vankilassa ja toi hänen päänsä lautasella ja antoi sen tytölle, ja tyttö antoi sen äidilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Kun hänen opetuslapsensa sen kuulivat, he tulivat ja ottivat hänen ruumiinsa ja panivat sen hautaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Apostolit kokoontuivat Jeesuksen luo ja kertoivat hänelle kaikki, mitä olivat tehneet ja mitä opettaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Hän sanoi heille: \"Tulkaa te yksinäisyyteen, autioon paikkaan, ja levähtäkää vähän.\" Sillä tulijoita ja menijöitä oli paljon, ja heillä ei ollut aikaa edes syödä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'He lähtivät veneellä autioon paikkaan, yksinäisyyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Heidän nähtiin lähtevän, ja monet saivat siitä tiedon ja tulivat sinne juoksujalkaa kaikista kaupungeista ja saapuivat ennen heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Astuessaan maihin hän näki paljon kansaa, ja hänen kävi heitä sääliksi, koska he olivat kuin lampaat ilman paimenta, ja hän rupesi opettamaan heille monia asioita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Kun päivä oli jo kulunut pitkälle, hänen opetuslapsensa menivät hänen luokseen ja sanoivat: \"Tämä paikka on autio, ja on jo myöhäinen ilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Laske heidät luotasi, että he menisivät ympäristöllä oleviin maataloihin ja kyliin ostamaan itselleen syötävää, sillä heillä ei ole mitä syödä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Mutta hän vastasi heille ja sanoi: \"Antakaa te heille syödä.\" Niin he sanoivat hänelle: \"Lähdemmekö ostamaan leipää kahdellasadalla denaarilla antaaksemme heille syödä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Mutta hän sanoi heille: \"Montako leipää teillä on? Menkää katsomaan.\" Otettuaan siitä selvän he sanoivat: \"Viisi, ja kaksi kalaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Hän määräsi heille, että kaikkien oli asetuttava ruokakunnittain vihantaan ruohikkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'He laskeutuivat ryhmä ryhmän viereen, toisiin sata, toisiin viisikymmentä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Hän otti ne viisi leipää ja kaksi kalaa, katsoi ylös taivaaseen, siunasi, mursi leivät ja antoi ne opetuslapsilleen kansan eteen pantaviksi, myös ne kaksi kalaa hän jakoi kaikille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Kaikki söivät ja tulivat ravituiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'He keräsivät palaset, kaksitoista täyttä korillista, ja tähteet kaloista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Niitä, jotka olivat syöneet näitä leipiä, oli viisituhatta miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Heti hän vaati opetuslapsiaan astumaan veneeseen ja kulkemaan edeltä toiselle rannalle Beetsaidaan, sillä aikaa kun hän laskisi kansan luotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Erottuaan heistä hän meni pois vuorelle rukoilemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Mutta kun ilta tuli, vene oli keskellä järveä, ja hän oli yksin maissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Kun hän näki heidän soutaessaan olevan hädässä, sillä tuuli oli heille vastainen, hän tuli neljännen yövartion vaiheilla heidän luokseen kävellen järven päällä ja aikoi kulkea heidän ohitseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Mutta nähdessään hänen kävelevän järven päällä he luulivat häntä aaveeksi ja alkoivat huutaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'sillä kaikki näkivät hänet ja pelästyivät. Mutta heti hän puhutteli heitä ja sanoi heille: \"Olkaa turvallisella mielellä, Minä olen, älkää pelätkö.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'Hän astui veneeseen heidän luokseen, ja tuuli asettui. He hämmästyivät aivan suunnattomasti sisimmässään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'Sillä he eivät olleet noista leivistäkään päässeet ymmärrykseen, vaan heidän sydämensä oli paatunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Päästyään yli toiselle rannalle he tulivat Genetsaretiin ja laskivat maihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Heidän noustessaan veneestä kansa heti tunsi hänet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'ja he riensivät kiertämään koko sitä paikkakuntaa ja ryhtyivät vuoteilla kantamaan sairaita sinne, missä kuulivat hänen olevan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'Missä vain hän meni kyliin, kaupunkeihin tai maataloihin, asetettiin sairaat aukeille paikoille ja pyydettiin häneltä, että he saisivat koskea edes hänen viittansa tupsuun. Kaikki, jotka koskivat häneen, tulivat terveiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Mutta fariseukset ja muutamat kirjanoppineet, jotka olivat tulleet Jerusalemista, kokoontuivat hänen luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'He näkivät, että muutamat hänen opetuslapsistaan söivät leipää epäpuhtain, se on pesemättömin, käsin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Sillä eivät fariseukset eivätkä ketkään juutalaiset syö, ennen kuin ovat pesseet tarkasti kätensä, noudattaen vanhinten perinnäissääntöä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'ja torilta tultuaan he eivät syö, ennen kuin ovat itseään vedellä vihmoneet. On paljon muutakin, mitä he ovat ottaneet noudattaakseen, kuten maljojen, kiviastioiden, vaskiastioiden ja vuoteiden pesemisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Fariseukset ja kirjanoppineet kysyivät häneltä: \"Miksi sinun opetuslapsesi eivät vaella vanhinten perinnäissäännön mukaan, vaan syövät leipää epäpuhtain käsin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Mutta hän sanoi heille: \"Oikein Jesaja on ennustanut teistä, tekopyhistä, kuten on kirjoitettu: \'Tämä kansa kunnioittaa minua huulillaan, mutta heidän sydämensä on minusta kaukana,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'mutta turhaan he palvelevat minua opettaen oppeja, jotka ovat ihmiskäskyjä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Hylkäätte Jumalan käskyn ja noudatatte ihmisten perinnäissääntöä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Hän sanoi heille: \"Taitavasti hylkäätte Jumalan käskyn noudattaaksenne omaa perinnäissääntöänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Sillä Mooses on sanonut: \'Kunnioita isääsi ja äitiäsi\', ja: \'Joka kiroaa isäänsä tai äitiään, sen pitää kuolemalla kuoleman.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Mutta te sanotte, että jos ihminen sanoo isälleen tai äidilleen: \'Se, minkä olisit saava minulta hyväksesi, on korban\' – se on uhrilahja –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'ettekä enää salli hänen antaa mitään isälleen tai äidilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Teette Jumalan sanan tyhjäksi perinnäissäännöllänne, jonka olette säätäneet. Paljon muuta samanlaista teette.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Hän kutsui taas kaiken kansan luokseen ja sanoi heille: \"Kuulkaa minua kaikki ja ymmärtäkää:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'ei mikään, mikä menee ihmisen ulkopuolelta hänen sisäänsä, voi häntä saastuttaa, vaan se, mikä lähtee hänestä ulos, saastuttaa ihmisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Jos jollakulla on korvat kuulla, kuulkoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Kun hän lähdettyään kansan luota oli mennyt erääseen taloon, hänen opetuslapsensa kysyivät häneltä tätä vertausta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Hän sanoi heille: \"Niinkö ymmärtämättömiä tekin olette? Ettekö käsitä, ettei mikään, mikä ulkoapäin menee ihmiseen, voi häntä saastuttaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'Sillä se ei mene hänen sydämeensä, vaan vatsaan, ja ulostetaan käymälään.\" Näin hän puhdisti kaikki ruuat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Hän sanoi: \"Mikä ihmisestä lähtee ulos, se saastuttaa ihmisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Sillä sisästä, ihmisten sydämestä, lähtevät pahat ajatukset, aviorikokset, haureudet, murhat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'varkaudet, ahneus, häijyys, petollisuus, irstaus, kateus, jumalanpilkka, ylpeys, mielettömyys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Kaikki tämä paha lähtee sisästä ulos ja saastuttaa ihmisen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Hän nousi ja lähti sieltä Tyyron ja Siidonin alueelle. Hän meni erääseen taloon eikä tahtonut, että kukaan saisi sitä tietää, mutta hän ei saanut olla salassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'vaan heti kun eräs nainen, jonka pienessä tyttäressä oli saastainen henki, kuuli hänestä, nainen tuli ja lankesi hänen jalkojensa juureen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Mutta nainen oli kreikatar, syntyperältään syyrialaisfoinikialainen, ja hän pyysi häntä ajamaan riivaajan pois tyttärestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Jeesus vastasi ja sanoi hänelle: \"Salli lasten tulla ensin ravituiksi, sillä ei ole hyvä ottaa lasten leipää ja heittää koiranpenikoille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Mutta hän vastasi ja sanoi hänelle: \"Niin, Herra, mutta syöväthän penikatkin pöydän alta lasten muruja.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Hän sanoi naiselle: \"Tämän sanan tähden, mene, riivaaja on lähtenyt tyttärestäsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Nainen meni kotiinsa ja havaitsi lapsen makaavan vuoteella ja riivaajan lähteneen hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Hän [Jeesus] lähti jälleen Tyyron ja Siidonin alueelta ja tuli Galilean järven rannalta ylös Dekapolin alueen keskelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'Hänen luokseen tuotiin kuuro, joka puhui epäselvästi, ja he pyysivät häntä panemaan kätensä hänen päälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Niin hän otti hänet erilleen kansasta, pisti sormensa hänen korviinsa, sylki ja koski hänen kieleensä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'ja katsoi ylös taivaaseen, huokasi ja sanoi hänelle: \"Effata\", se on: aukene.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Hänen korvansa aukenivat heti, ja hänen kielensä side irtautui, ja hän puhui oikein.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Jeesus kielsi heitä sitä kenellekään sanomasta. Mutta mitä enemmän hän heitä kielsi, sitä enemmän he julistivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'Ihmiset hämmästyivät suunnattomasti ja sanoivat: \"Hyvin hän on kaikki tehnyt: kuurot hän saa kuulemaan ja mykät puhumaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'Niinä päivinä, kun kansaa oli taas koolla varsin paljon eikä heillä ollut mitään syötävää, hän kutsui opetuslapsensa luokseen ja sanoi heille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, '\"Minun käy sääliksi kansaa, sillä he ovat jo kolme päivää olleet luonani, eikä heillä ole mitä syödä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'Jos minä lasken heidät menemään syömättä kotiinsa, he nääntyvät matkalla, sillä muutamat heistä ovat tulleet kaukaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Hänen opetuslapsensa vastasivat hänelle: \"Mistä täällä erämaassa kukaan voi saada leipää näiden ravitsemiseksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Hän kysyi heiltä: \"Montako leipää teillä on?\" He sanoivat: \"Seitsemän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Silloin hän käski kansan asettua maahan. Hän otti ne seitsemän leipää, kiitti, mursi ja antoi opetuslapsilleen, että he jakaisivat ne. He jakoivat ne kansalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Heillä oli myös joitakin pieniä kaloja, ja siunattuaan ne hän käski jakaa nekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'He söivät ja tulivat ravituiksi. Sitten he keräsivät jääneet palaset, seitsemän korillista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Heitä oli noin neljätuhatta. Hän laski heidät luotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Heti hän astui opetuslapsineen veneeseen ja meni Dalmanutan seuduille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Fariseukset lähtivät sinne ja rupesivat väittelemään hänen kanssaan ja vaativat häneltä merkkiä taivaasta kiusaten häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Hän huokasi hengessään ja sanoi: \"Miksi tämä sukukunta vaatii merkkiä? Totisesti minä sanon teille: tälle sukukunnalle ei anneta merkkiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Hän jätti heidät ja astui taas veneeseen ja lähti pois toiselle rannalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Mutta opetuslapset olivat unohtaneet ottaa mukaansa leipää, eikä heillä ollut mukanaan veneessä kuin yksi leipä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Hän käski heitä sanoen: \"Varokaa ja kavahtakaa fariseusten hapatusta ja Herodeksen hapatusta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'He puhelivat keskenään ja sanoivat: \"Meillä ei ole leipää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Kun Jeesus huomasi sen, hän sanoi heille: \"Mitä puhelette siitä, ettei teillä ole leipää? Ettekö vielä käsitä ettekä ymmärrä? Onko teidän sydämenne paatunut?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Silmät teillä on, ettekö näe? Korvat teillä on, ettekö kuule? Ettekö muista:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'kun minä mursin ne viisi leipää viidelletuhannelle, kuinka monta täyttä korillista palasia te keräsitte?\" He sanoivat hänelle: \"Kaksitoista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, '\"Kun minä mursin ne seitsemän neljälletuhannelle, kuinka monta täyttä korillista palasia te keräsitte?\" He sanoivat: \"Seitsemän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Hän sanoi heille: \"Ettekö vieläkään ymmärrä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'He tulivat Beetsaidaan. Hänen luokseen tuotiin sokea, ja he pyysivät, että hän koskisi häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Hän tarttui sokean käteen, talutti hänet kylän ulkopuolelle, sylki hänen silmiinsä ja pani kätensä hänen päälleen ja kysyi häneltä, näkikö hän jotakin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Tämä katsoi ylös ja sanoi: \"Näen ihmisten kävelevän, he ovat kuin puita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Hän pani kätensä taas hänen silmilleen ja teki hänet näkeväksi. Hän oli tullut jälleen terveeksi ja näki kaiken selvästi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Hän lähetti hänet hänen kotiinsa sanoen: \"Älä poikkea kylään äläkä kerro kenellekään kylässä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Jeesus lähti opetuslapsineen Filippoksen Kesarean kyliin. Tiellä hän kysyi opetuslapsiltaan ja sanoi heille: \"Kenen ihmiset sanovat minun olevan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'He vastasivat hänelle sanoen: \"Johannes Kastajan, ja toiset Eliaan, toiset taas jonkun profeetoista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Hän sanoi heille: \"Kenen te sanotte minun olevan?\" Pietari vastasi ja sanoi hänelle: \"Sinä olet Kristus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Hän varoitti heitä puhumasta kenellekään hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'Hän alkoi opettaa heille, että Ihmisen Pojan pitää paljon kärsiä ja joutua vanhinten, ylipappien ja kirjanoppineiden hylkimäksi ja tapetuksi, mutta kolmen päivän kuluttua hän on nouseva ylös.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Tämän hän puhui peittelemättä. Silloin Pietari otti hänet erilleen ja alkoi nuhdella häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Mutta hän kääntyi, katsoi opetuslapsiinsa ja nuhteli Pietaria sanoen: \"Mene pois minun edestäni, saatana, sillä sinä et ajattele sitä, mikä on Jumalan, vaan sitä, mikä on ihmisten.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Hän kutsui luokseen kansan sekä opetuslapsensa ja sanoi heille: \"Jos kuka tahansa tahtoo kulkea perässäni, hän kieltäköön itsensä ja ottakoon ristinsä ja seuratkoon minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Sillä se, joka tahtoo pelastaa elämänsä, kadottaa sen, mutta se, joka kadottaa elämänsä minun ja evankeliumin tähden, pelastaa sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Sillä mitä ihmistä hyödyttää, vaikka hän voittaisi omakseen koko maailman, mutta saisi sielulleen vahingon?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Sillä mitä ihminen voi antaa sielunsa lunnaiksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Sillä joka häpeää minua ja minun sanojani tässä avion rikkovassa ja syntisessä sukukunnassa, sitä myös Ihmisen Poika on häpeävä, kun hän tulee Isänsä kirkkaudessa pyhien enkelien kanssa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Hän sanoi heille: \"Totisesti minä sanon teille: tässä seisovien joukossa on muutamia, jotka eivät maista kuolemaa, ennen kuin näkevät Jumalan valtakunnan tulleena voimassaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Kuuden päivän kuluttua Jeesus otti mukaansa Pietarin, Jaakobin ja Johanneksen ja vei heidät erilleen muista korkealle vuorelle, yksinäisyyteen. Hänen muotonsa muuttui heidän edessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'Hänen vaatteensa tulivat hohtaviksi, niin kovin valkoisiksi, ettei kukaan vaatteenvalkaisija maan päällä pysty valkaisemaan sellaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Heille ilmestyi Elia Mooseksen kanssa, ja nämä keskustelivat Jeesuksen kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Pietari alkoi puhua ja sanoi Jeesukselle: \"Rabbi, meidän on tässä hyvä olla. Tehkäämme kolme majaa, sinulle yksi, Moosekselle yksi ja Elialle yksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Sillä hän ei tiennyt, mitä sanoa, koska he olivat pelästyneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Tuli pilvi, joka peitti heidät varjoonsa, ja pilvestä kuului ääni: \"Tämä on minun rakas Poikani, häntä kuulkaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Yhtäkkiä, kun he katsoivat ympärilleen, he eivät enää nähneet ketään muuta kuin Jeesuksen yksin heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Mutta heidän kulkiessaan alas vuorelta hän kielsi heitä kertomasta kenellekään, mitä olivat nähneet, ennen kuin vasta sitten, kun Ihmisen Poika oli noussut kuolleista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'He kiinnittivät huomionsa tähän sanaan ja tutkistelivat keskenään, mitä kuolleista nouseminen on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'He kysyivät häneltä sanoen: \"Kirjanoppineethan sanovat, että Elian pitää tulla ensin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Hän vastasi ja sanoi heille: \"Elia tosin tulee ensin ja asettaa kaikki kohdalleen. Mutta kuinka sitten on kirjoitettu Ihmisen Pojasta, että hän on paljon kärsivä ja tuleva halveksituksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Mutta minä sanon teille: Elia onkin tullut, ja he tekivät hänelle, mitä tahtoivat, kuten hänestä on kirjoitettu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Kun he tulivat opetuslasten luo, he näkivät paljon kansaa heidän ympärillään ja kirjanoppineita väittelemässä heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Heti kun kaikki kansa näki hänet, he hämmästyivät ja riensivät hänen luokseen ja tervehtivät häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Hän kysyi kirjanoppineilta: \"Mitä te väittelette heidän kanssaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Eräs mies kansanjoukosta vastasi hänelle ja sanoi: \"Opettaja, minä toin luoksesi poikani, jossa on mykkä henki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'Missä vain se käy hänen kimppuunsa, se riuhtoo häntä, hänestä lähtee vaahto, hän kiristelee hampaitaan, ja hän kuihtuu. Sanoin opetuslapsillesi, että he ajaisivat sen ulos, mutta he eivät kyenneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Hän vastasi heille sanoen: \"Voi, sinä epäuskoinen sukukunta, kuinka kauan minun täytyy olla teidän luonanne? Kuinka kauan kärsiä teitä? Tuokaa hänet luokseni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'He toivat hänet hänen luokseen. Heti kun hän näki Jeesuksen, kouristi henki häntä, ja hän kaatui maahan, kieriskeli siinä, ja hänestä lähti vaahto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Jeesus kysyi hänen isältään: \"Kuinka kauan tätä on ollut hänessä?\" Hän sanoi: \"Pienestä pitäen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'Monesti se on heittänyt hänet milloin tuleen, milloin veteen, tuhotakseen hänet. Mutta jos jotakin voit, auta meitä ja armahda meitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Jeesus sanoi hänelle: \"Jospa voisit uskoa. Kaikki on mahdollista sille, joka uskoo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Heti lapsen isä huusi ja sanoi kyynelin: \"Minä uskon, auta minua epäuskossani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Mutta kun Jeesus näki, että kansaa riensi sinne, hän nuhteli saastaista henkeä ja sanoi sille: \"Sinä mykkä ja kuuro henki, minä käsken sinua: lähde ulos hänestä, äläkä enää mene häneen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Se huusi, kouristi häntä kovasti ja lähti ulos. Hän kävi ikään kuin kuolleeksi, niin että monet sanoivat: \"Hän kuoli.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Mutta Jeesus tarttui hänen käteensä ja nosti hänet ylös, ja hän nousi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Kun Jeesus oli mennyt huoneeseen, hänen opetuslapsensa kysyivät häneltä erikseen: \"Miksi me emme voineet ajaa sitä ulos?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Hän sanoi heille: \"Tätä lajia ei saa lähtemään ulos muulla kuin rukouksella ja paastolla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'He lähtivät sieltä ja kulkivat Galilean kautta, mutta hän ei tahtonut, että kukaan saisi tietää sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Sillä hän opetti opetuslapsiaan ja sanoi heille: \"Ihmisen Poika annetaan ihmisten käsiin, ja he tappavat hänet, ja kun hänet on tapettu, hän nousee kolmantena päivänä ylös.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Mutta he eivät käsittäneet sitä puhetta ja pelkäsivät kysyä häneltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'He saapuivat Kapernaumiin. Kotiin tultuaan hän kysyi heiltä: \"Mistä te tiellä keskustelitte?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Mutta he olivat vaiti, sillä he olivat tiellä keskustelleet toistensa kanssa siitä, kuka oli suurin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'Istuuduttuaan hän kutsui ne kaksitoista ja sanoi heille: \"Jos joku tahtoo olla ensimmäinen, hänen on oltava kaikista viimeinen ja kaikkien palvelija.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'Hän otti lapsen, asetti sen heidän keskelleen ja otettuaan sen syliinsä sanoi heille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, '\"Se, joka ottaa luokseen yhden tällaisen lapsen minun nimeeni, ottaa luokseen minut. Se, joka ottaa luokseen minut, ei ota luokseen minua, vaan hänet, joka on minut lähettänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Johannes sanoi hänelle: \"Opettaja, me näimme erään, joka ei seuraa meitä, sinun nimessäsi ajavan ulos riivaajia, ja kielsimme häntä, koska hän ei seurannut meitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Mutta Jeesus sanoi: \"Älkää häntä kieltäkö, sillä ei kukaan, joka tekee voimateon minun nimeeni, voi heti sen jälkeen puhua minusta pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Sillä se, joka ei ole meitä vastaan, on meidän puolellamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Sillä se, joka antaa teille juodaksenne maljallisen vettä siinä nimessä, että olette Kristuksen omia, totisesti sanon teille: se ei jää palkkaansa vaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'Joka viettelee yhden näistä pienistä, jotka uskovat, sen olisi parempi, että myllynkivi olisi pantu hänen kaulaansa ja hänet olisi heitetty mereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Jos sinun kätesi viettelee sinua, hakkaa se poikki. Parempi on sinulle, että käsipuolena menet elämään sisälle kuin että molemmat kädet tallella menet helvettiin, sammumattomaan tuleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'jossa heidän matonsa ei kuole eikä tuli sammu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'Jos jalkasi viettelee sinua, hakkaa se poikki. Parempi on sinulle, että jalkapuolena menet elämään sisälle, kuin että sinut molemmat jalat tallella heitetään helvettiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'jossa heidän matonsa ei kuole eikä tulensa sammu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Jos sinun silmäsi viettelee sinua, heitä se pois. Parempi on sinulle, että silmäpuolena menet sisälle Jumalan valtakuntaan, kuin että sinut molemmat silmät tallella heitetään helvetin tuleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'jossa heidän matonsa ei kuole eikä tuli sammu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Sillä jokainen ihminen on tulella suolattava, ja jokainen uhri on suolalla suolattava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Suola on hyvä, mutta jos suola käy suolattomaksi, millä sen suolaatte? Olkoon teillä suola itsessänne, ja pitäkää keskenänne rauha.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Hän nousi sieltä ja tuli Juudean alueelle kulkien Jordanin toista puolta. Jälleen kokoontui paljon kansaa hänen luokseen, ja tapansa mukaan hän taas opetti heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Fariseuksia tuli hänen luokseen, ja kiusaten häntä he kysyivät häneltä, oliko miehen lupa hylätä vaimonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Hän vastasi ja sanoi heille: \"Mitä Mooses on teille säätänyt?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'He sanoivat: \"Mooses salli kirjoittaa erokirjan ja hylätä vaimon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Jeesus sanoi heille: \"Teidän sydämenne kovuuden tähden hän kirjoitti teille tämän säädöksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Mutta luomakunnan alusta Jumala \'on luonut heidät mieheksi ja naiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Sen tähden mies luopukoon isästään ja äidistään ja liittyköön vaimoonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'Ne kaksi tulevat yhdeksi lihaksi.\' Niin he eivät enää ole kaksi, vaan yksi liha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Sitä, minkä siis Jumala on yhdistänyt, älköön ihminen erottako.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Sisällä opetuslapset taas kysyivät häneltä tätä asiaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Hän sanoi heille: \"Se, joka hylkää vaimonsa ja nai toisen, tekee huorin häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'Jos vaimo hylkää miehensä ja menee naimisiin toisen kanssa, hän tekee huorin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'He toivat hänen luokseen lapsia, että hän koskisi heihin, mutta opetuslapset nuhtelivat tuojia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Mutta kun Jeesus sen näki, hän närkästyi ja sanoi heille: \"Sallikaa lasten tulla minun tyköni, älkääkä estäkö heitä, sillä sellaisten on Jumalan valtakunta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Totisesti sanon teille: joka ei ota vastaan Jumalan valtakuntaa kuin lapsi, se ei tule sinne sisälle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Hän otti heitä syliinsä, pani kätensä heidän päälleen ja siunasi heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Hänen sieltä tielle mennessään juoksi muuan hänen luokseen, polvistui hänen eteensä ja kysyi häneltä: \"Hyvä opettaja, mitä minun pitää tehdä, että iankaikkisen elämän perisin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Mutta Jeesus sanoi hänelle: \"Miksi sanot minua hyväksi? Kukaan ei ole hyvä paitsi Jumala yksin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Käskyt sinä tiedät: \'Älä tee huorin\', \'älä tapa\', \'älä varasta\', \'älä sano väärää todistusta\', \'älä anasta toiselta\', \'kunnioita isääsi ja äitiäsi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Mutta hän vastasi ja sanoi hänelle: \"Opettaja, niitä kaikkia olen noudattanut nuoruudestani asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Jeesus katsoi häneen, rakasti häntä ja sanoi hänelle: \"Yksi sinulta puuttuu: mene, myy kaikki, mitä sinulla on, ja anna köyhille, niin sinulla on oleva aarre taivaassa, ja tule ja seuraa minua ristiä kantaen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Mutta hän synkistyi siitä puheesta ja meni pois murheellisena, sillä hänellä oli paljon omaisuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Jeesus katsoi ympärilleen ja sanoi opetuslapsilleen: \"Kuinka vaikea onkaan niiden, joilla on omaisuutta, tulla Jumalan valtakuntaan!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Opetuslapset hämmästyivät hänen sanoistaan. Mutta Jeesus alkoi taas puhua ja sanoi heille: \"Lapset, kuinka vaikea onkaan niiden, jotka luottavat omaisuuteensa, tulla Jumalan valtakuntaan!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Helpompi on kamelin mennä neulansilmästä kuin rikkaan tulla Jumalan valtakuntaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'He hämmästyivät yhä enemmän ja sanoivat toisilleen: \"Kuka sitten voi pelastua?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Jeesus katsoi heihin ja sanoi: \"Ihmisille se on mahdotonta, mutta ei Jumalalle, sillä Jumalalle on kaikki mahdollista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Pietari rupesi puhumaan sanoen hänelle: \"Katso, me olemme luopuneet kaikesta ja seuranneet sinua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Jeesus sanoi: \"Totisesti sanon teille: ei ole ketään, joka minun tähteni ja evankeliumin tähden on luopunut talosta, veljistä, sisarista, äidistä, isästä, lapsista tai pelloista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'ja joka ei saisi satakertaisesti: nyt tässä ajassa taloja, veljiä, sisaria, äitejä, lapsia ja peltoja, vainojen keskellä, ja tulevassa maailmassa iankaikkista elämää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Mutta monet ensimmäiset tulevat viimeisiksi ja viimeiset ensimmäisiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'He olivat matkalla, menossa ylös Jerusalemiin, ja Jeesus kulki heidän edellään, ja heidät valtasi hämmästys, ja ne, jotka seurasivat, olivat peloissaan. Hän otti taas luokseen ne kaksitoista ja alkoi puhua heille, mitä hänelle oli tapahtuva:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, '\"Katso, menemme ylös Jerusalemiin, ja Ihmisen Poika annetaan ylipappien ja kirjanoppineiden käsiin, ja he tuomitsevat hänet kuolemaan ja antavat hänet pakanoiden käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'He pilkkaavat, sylkevät, ruoskivat häntä ja tappavat hänet, ja kolmen päivän perästä hän nousee ylös.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Jaakob ja Johannes, Sebedeuksen pojat, menivät hänen luokseen ja sanoivat hänelle: \"Opettaja, tahtoisimme, että tekisit meille, mitä sinulta anomme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'Mutta hän sanoi heille: \"Mitä tahdotte, että teille tekisin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Niin he sanoivat hänelle: \"Anna meidän istua, toisen oikealla ja toisen vasemmalla puolellasi kirkkaudessasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Mutta Jeesus sanoi heille: \"Te ette tiedä, mitä anotte. Voitteko juoda sen maljan, jonka minä juon, tai tulla kastetuiksi sillä kasteella, jolla minut kastetaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'He sanoivat hänelle: \"Voimme.\" Niin Jeesus sanoi heille: \"Sen maljan, jonka minä juon, tosin juotte, ja sillä kasteella, jolla minut kastetaan, kastetaan teidätkin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'mutta minun oikealla tai vasemmalla puolellani istuminen ei ole minun annettavissani, vaan se annetaan niille, joille se on valmistettu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'Kun ne kymmenen sen kuulivat, he alkoivat närkästyä Jaakobiin ja Johannekseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Mutta Jeesus kutsui heidät luokseen ja sanoi heille: \"Tiedätte, että ne, joita kansojen ruhtinaiksi katsotaan, herroina niitä hallitsevat, ja että kansojen mahtavat käyttävät valtaansa niitä kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Mutta näin ei tule olla teillä keskenänne, vaan se, joka teidän keskuudessanne tahtoo tulla suureksi, olkoon palvelijanne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'ja se, joka teidän keskuudessanne tahtoo olla ensimmäinen, olkoon kaikkien orja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Sillä ei Ihmisen Poikakaan tullut palveltavaksi, vaan palvelemaan ja antamaan henkensä lunnaiksi monen edestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'He tulivat Jerikoon. Kun hän vaelsi Jerikosta opetuslastensa ja suuren väkijoukon seuraamana, istui sokea kerjäläinen, Bartimeus, Timeuksen poika, tien vieressä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'Kun hän kuuli, että se oli Jeesus Nasaretilainen, hän alkoi huutaa ja sanoa: \"Jeesus, Daavidin poika, armahda minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Monet nuhtelivat häntä saadakseen hänet vaikenemaan. Mutta hän huusi vielä enemmän: \"Daavidin poika, armahda minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Silloin Jeesus pysähtyi ja sanoi: \"Kutsukaa hänet tänne.\" He kutsuivat sokean sanoen hänelle: \"Ole turvallisella mielellä, nouse, hän kutsuu sinua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Hän heitti viittansa päältään, nousi seisomaan ja tuli Jeesuksen luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Jeesus vastasi ja sanoi hänelle: \"Mitä tahdot, että tekisin sinulle?\" Sokea sanoi hänelle: \"Rabbuuni, että saisin näköni jälleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Jeesus sanoi hänelle: \"Mene, uskosi on sinut pelastanut.\" Heti hän sai näkönsä ja seurasi häntä tiellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Kun he sitten lähestyivät Jerusalemia tullen Beetfageen ja Betaniaan Öljymäen luona, hän lähetti kaksi opetuslastaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'ja sanoi heille: \"Menkää edessänne olevaan kylään, niin te heti, kun sinne tulette, löydätte sidottuna varsan, jonka selässä ei kukaan ihminen ole vielä istunut. Päästäkää se ja tuokaa tänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Jos joku teille sanoo: \'Miksi te noin teette?\', sanokaa: \'Herra tarvitsee sitä ja lähettää sen heti tänne.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Niin he menivät ja löysivät oven eteen ulos kujalle sidotun varsan ja päästivät sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Muutamat niistä, jotka siellä seisoivat, sanoivat heille: \"Mitä teette, kun päästätte varsan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Niin he sanoivat heille, kuten Jeesus oli käskenyt, ja he päästivät heidät menemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'He toivat varsan Jeesuksen luo ja heittivät vaatteensa sen päälle, ja hän istui sen selkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Monet levittivät vaatteensa tielle, ja toiset lehviä, joita katkoivat puista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Ne, jotka kulkivat edellä, ja jotka seurasivat, huusivat: \"Hoosianna, siunattu olkoon se, joka tulee Herran nimeen!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Siunattu olkoon isämme Daavidin valtakunta, joka tulee. Hoosianna korkeuksissa!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Jeesus kulki Jerusalemiin ja meni pyhäkköön, ja katseltuaan kaikkea hän lähti niiden kahdentoista kanssa Betaniaan, sillä oli jo myöhä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Kun he seuraavana päivänä lähtivät Betaniasta, hänen oli nälkä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'Kun hän näki kaukaa viikunapuun, jossa oli lehtiä, hän meni katsomaan, löytäisikö siitä jotakin, mutta tultuaan sen luo hän ei löytänyt muuta kuin lehtiä. Sillä ei ollut viikunoiden aika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Hän puhui ja sanoi sille: \"Älköön ikinä enää kukaan sinusta hedelmää syökö.\" Hänen opetuslapsensa kuulivat sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'He tulivat Jerusalemiin. Hän meni pyhäkköön ja ryhtyi ajamaan ulos niitä, jotka myivät ja ostivat pyhäkössä, ja kaatoi kumoon rahanvaihtajien pöydät ja kyyhkysten myyjien istuimet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'eikä sallinut kenenkään kantaa mitään astiaa pyhäkön kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Hän opetti ja sanoi heille: \"Eikö ole kirjoitettu: \'Minun huoneeni on kutsuttava kaikkien kansojen rukoushuoneeksi\'? Mutta te olette tehneet siitä rosvojen luolan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Ylipapit ja kirjanoppineet kuulivat sen ja miettivät, kuinka saisivat hänet surmatuksi, sillä he pelkäsivät häntä, koska kaikki kansa oli hämmästyksissään hänen opetuksestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Kun ilta tuli, he menivät kaupungin ulkopuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Kun he sitten varhain aamulla kulkivat ohi, he näkivät viikunapuun kuivuneen juuria myöten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Pietari muisti ja sanoi hänelle: \"Rabbi, katso, viikunapuu, jonka kirosit, on kuivunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Jeesus vastasi ja sanoi heille: \"Pitäkää usko Jumalaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Totisesti sanon teille: jos joku sanoisi tälle vuorelle: \'Kohoa ja heittäydy mereen\', eikä epäilisi sydämessään, vaan uskoisi sen tapahtuvan, minkä hän sanoo, niin se tapahtuisi hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Sen tähden sanon teille: kaikki, mitä te rukoilette ja anotte, uskokaa saaneenne, niin se on teillä oleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Kun seisotte ja rukoilette, niin antakaa anteeksi, jos jollakulla teistä on jotakin toistanne vastaan, että myös teidän Isänne, joka on taivaissa, antaisi teille anteeksi teidän rikkomisenne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Mutta jos te ette anna anteeksi, niin ei Isännekään, joka on taivaissa, anna anteeksi teidän rikkomisianne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'He tulivat taas Jerusalemiin. Kun hän käveli pyhäkössä, tulivat ylipapit ja kirjanoppineet ja vanhimmat hänen luokseen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'ja sanoivat hänelle: \"Millä vallalla sinä näitä teet? Tai kuka on antanut sinulle vallan näitä tehdä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Mutta Jeesus vastasi heille: \"Minäkin teen teille yhden kysymyksen. Vastatkaa minulle, niin sanon teille, millä vallalla näitä teen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Oliko Johanneksen kaste taivaasta vai ihmisistä? Vastatkaa minulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'He neuvottelivat keskenään sanoen: \"Jos sanomme: \'Taivaasta\', hän sanoo: \'Miksi ette siis uskoneet häntä?\'.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Vai sanommeko: \'Ihmisistä\'?\" – sitä he kansan tähden pelkäsivät sanoa, sillä kaikkien mielestä Johannes oli todella profeetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'He vastasivat ja sanoivat Jeesukselle: \"Emme tiedä.\" Silloin Jeesus vastasi ja sanoi heille: \"Niinpä minäkään en sano teille, millä vallalla näitä teen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Hän alkoi puhua heille vertauksilla: \"Mies istutti viinitarhan, teki aidan sen ympärille, kaivoi viinikuurnan ja rakensi tornin. Hän vuokrasi sen viinitarhureille ja matkusti ulkomaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Kun aika tuli, hän lähetti palvelijan viinitarhurien luo perimään tarhureilta viinitarhan hedelmiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Mutta he ottivat hänet kiinni, ruoskivat ja lähettivät tyhjänä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Vielä hän lähetti heidän luokseen toisen palvelijan. Mutta häntä he heittivät kivillä päähän ja häpäisivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Hän lähetti vielä toisen, ja hänet he tappoivat, ja samoin useita muita: toisia he löivät, toisia tappoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Vielä hänellä oli ainoa rakas poikansa. Hänet hän lähetti viimeiseksi heidän luokseen sanoen: \'Poikaani he kavahtavat.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Mutta viinitarhurit sanoivat toisilleen: \'Tämä on perillinen, tulkaa, tappakaamme hänet, niin perintö on meidän.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'He ottivat hänet kiinni, tappoivat ja heittivät hänet viinitarhan ulkopuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Mitä nyt viinitarhan isäntä tekee? Hän tulee ja tuhoaa viinitarhurit ja antaa viinitarhan muille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Ettekö ole lukeneet tätä kirjoitusta: \'Se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'Herralta tämä on tullut ja on ihmeellinen silmissämme\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'He etsivät häntä ottaakseen hänet kiinni, mutta he pelkäsivät kansaa, sillä he ymmärsivät, että hän oli puhunut tämän vertauksen heistä. He jättivät hänet ja menivät pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'He lähettivät hänen luokseen muutamia fariseuksia ja herodeslaisia kietomaan häntä sanoilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Nämä tulivat ja sanoivat hänelle: \"Opettaja, tiedämme, että sinä olet totuudellinen etkä välitä kenestäkään, sillä et katso henkilöön, vaan opetat Jumalan tietä totuudessa. Onko luvallista antaa keisarille veroa vai ei? Tuleeko meidän antaa vai ei?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Mutta hän tiesi heidän tekopyhyytensä ja sanoi heille: \"Miksi kiusaatte minua? Tuokaa denaari minun nähdäkseni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'He toivat. Hän sanoi heille: \"Kenen kuva ja päällekirjoitus tämä on?\" He vastasivat hänelle: \"Keisarin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Jeesus sanoi heille: \"Antakaa keisarille, mikä keisarin on, ja Jumalalle, mikä Jumalan on.\" He ihmettelivät häntä suuresti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Hänen luokseen tuli saddukeuksia, jotka sanovat, ettei ylösnousemusta ole, ja he kysyivät häneltä sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, '\"Opettaja, Mooses on kirjoittanut meille: \'Jos joltakulta kuolee veli, joka jättää jälkeensä vaimon, mutta ei jätä lasta, niin ottakoon hän veljensä vaimon ja herättäköön veljelleen siemenen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Oli seitsemän veljestä. Ensimmäinen otti vaimon, ja kun hän kuoli, häneltä ei jäänyt siementä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'Silloin toinen otti hänet, ja hänkin kuoli jättämättä siementä. Niin myös kolmas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'Samoin kävi kaikille seitsemälle: heiltä ei jäänyt siementä. Viimeiseksi kaikista vaimokin kuoli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Ylösnousemuksessa siis, kun he nousevat ylös, kenelle heistä hän joutuu vaimoksi, sillä hän oli ollut kaikkien noiden seitsemän vaimona?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Jeesus sanoi heille: \"Eikö niin: te eksytte siitä syystä, ettette tunne Kirjoituksia ettekä Jumalan voimaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Sillä kun kuolleista noustaan, ei naida eikä mennä miehelle, vaan he ovat kuin enkelit taivaissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Mutta mitä siihen tulee, että kuolleet herätetään, ettekö ole lukeneet Mooseksen kirjasta kertomuksessa orjantappurapensaasta, kuinka Jumala puhui hänelle sanoen: \'Minä olen Aabrahamin Jumala ja Iisakin Jumala ja Jaakobin Jumala\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Ei hän ole kuolleiden Jumala, vaan elävien Jumala. Te siis suuresti eksytte.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Hänen luokseen tuli eräs kirjanoppinut, joka oli kuullut heidän keskustelunsa ja huomannut hänen hyvin vastanneen heille, ja kysyi häneltä: \"Mikä on ensimmäinen kaikista käskyistä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Jeesus vastasi: \"Ensimmäinen on tämä: \'Kuule, Israel: Herra, Jumalamme, Herra on yksi ainoa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'ja rakasta Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi ja kaikesta mielestäsi ja kaikesta voimastasi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Toinen on tämä: \'Rakasta lähimmäistäsi niin kuin itseäsi.\' Mitään muuta näitä suurempaa käskyä ei ole.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Kirjanoppinut sanoi hänelle: \"Oikein sanoit, opettaja, totuuden mukaan, että Jumala on yksi, ja ettei ole ketään toista, paitsi hän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'Rakastaa häntä kaikesta sydämestään, kaikesta ymmärryksestään ja kaikesta voimastaan, ja rakastaa lähimmäistään niin kuin itseään on enemmän kuin kaikki polttouhrit ja muut uhrit.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Kun Jeesus näki, että hän vastasi ymmärtäväisesti, hän sanoi hänelle: \"Sinä et ole kaukana Jumalan valtakunnasta.\" Kukaan ei enää uskaltanut esittää hänelle kysymyksiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Opettaessaan pyhäkössä Jeesus puhui edelleen ja sanoi: \"Kuinka kirjanoppineet sanovat, että Kristus on Daavidin poika?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Onhan Daavid itse sanonut Pyhässä Hengessä: \'Herra sanoi minun Herralleni: Istu minun oikealle puolelleni, kunnes minä panen vihollisesi jalkojesi astinlaudaksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'Daavid itse sanoo häntä Herraksi, kuinka hän sitten on hänen poikansa?\" Suuri kansanjoukko kuunteli häntä mielellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Opettaessaan hän sanoi: \"Varokaa kirjanoppineita, jotka haluavat kulkea pitkissä viitoissa ja saada tervehdyksiä toreilla');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'ja etumaisia istuimia synagogissa ja ensimmäisiä sijoja pidoissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'noita, jotka syövät leskien huoneet ja näön vuoksi pitävät pitkiä rukouksia. He saavat sitä kovemman tuomion.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Hän istui vastapäätä uhriarkkua ja katseli, kuinka kansa pani rahaa uhriarkkuun. Monet rikkaat panivat paljon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'Tuli köyhä leski ja pani kaksi ropoa, se on, jonkin kolikon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Hän kutsui opetuslapsensa luokseen ja sanoi heille: \"Totisesti sanon teille: tämä köyhä leski pani enemmän kuin kaikki muut, jotka panivat uhriarkkuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Sillä he kaikki panivat liiastaan. Mutta tämä pani puutteestaan kaiken, mitä hänellä oli, koko toimeentulonsa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Kun hän meni ulos pyhäköstä, eräs hänen opetuslapsistaan sanoi hänelle: \"Opettaja, katso, millaiset kivet ja millaiset rakennukset!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Jeesus vastasi hänelle: \"Näet nämä suuret rakennukset. Niistä ei ole jäävä kiveä kiven päälle maahan hajottamatta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Kun hän istui Öljymäellä vastapäätä pyhäkköä, Pietari, Jaakob, Johannes ja Andreas kysyivät häneltä heidän ollessa keskenään:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, '\"Sano meille: milloin tämä tapahtuu, ja mikä on merkki siitä, että kaikki tämä alkaa lopullisesti toteutua?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Jeesus vastasi ja ryhtyi puhumaan heille: \"Katsokaa, ettei kukaan teitä eksytä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Monta tulee minun nimessäni sanoen: \' Minä olen \', ja he eksyttävät monta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Kun kuulette sodista ja sanomia sodista, älkää pelästykö. Näin täytyy tapahtua, mutta se ei ole vielä loppu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Sillä kansa nousee kansaa vastaan ja valtakunta valtakuntaa vastaan, tulee maanjäristyksiä monin paikoin, ja on nälänhätää. Tämä on synnytystuskien alkua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Mutta pitäkää te vaari itsestänne. Teitä vedetään oikeuteen, teitä ruoskitaan synagogissa, ja teitä viedään maaherrojen ja kuningasten eteen minun tähteni, todistukseksi heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Mutta ensiksi pitää evankeliumi saarnata kaikille kansoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Kun he vievät teitä ja jättävät tuomittaviksi, älkää edeltäpäin murehtiko, mitä puhuisitte, vaan mitä teille sillä hetkellä annetaan, se puhukaa. Sillä ette te ole puhumassa, vaan Pyhä Henki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Veli antaa veljensä kuolemaan ja isä lapsensa, ja lapset nousevat vanhempiaan vastaan ja tappavat heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'Joudutte kaikkien vihattaviksi minun nimeni tähden. Mutta se, joka vahvana pysyy loppuun asti, pelastuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Mutta kun näette hävityksen kauhistuksen seisovan siinä, missä ei tulisi – se, joka tämän lukee, tarkatkoon – silloin ne, jotka Juudeassa ovat, paetkoot vuorille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'Se, joka on katolla, älköön astuko alas älköönkä menkö sisälle noutamaan huoneestaan mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'Se, joka on mennyt pellolle, älköön palatko takaisin hakemaan viittaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Voi raskaana olevia ja imettäviä niinä päivinä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Mutta rukoilkaa, ettei se tapahtuisi talvella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Sillä niinä päivinä on oleva ahdistus, jollaista ei ole ollut Jumalan luoman luomakunnan alusta tähän asti, eikä milloinkaan tule.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Ellei Herra lyhentäisi niitä päiviä, mikään liha ei pelastuisi, mutta valittujen tähden, jotka hän on valinnut, hän on lyhentänyt ne päivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Jos silloin joku sanoo teille: \'Katso, täällä on Kristus\', tai: \'Katso, tuolla\', älkää uskoko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Sillä vääriä kristuksia ja vääriä profeettoja nousee, ja he tekevät tunnustekoja ja ihmeitä eksyttääkseen, jos mahdollista, valitutkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Mutta olkaa te varuillanne. Katso, olen edeltä sanonut teille kaiken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Mutta niinä päivinä, sen ahdistuksen jälkeen, aurinko pimenee, eikä kuu anna valoaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'ja tähtiä putoilee taivaalta, ja voimat, jotka ovat taivaissa, järkkyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'He näkevät Ihmisen Pojan tulevan pilvissä suurella voimalla ja kirkkaudella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'Hän lähettää enkelinsä ja kokoaa valittunsa neljältä ilmansuunnalta, maan äärestä aina taivaan ääreen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'Mutta oppikaa viikunapuusta vertaus: Kun sen oksa on jo tuore ja lehdet puhkeavat, tiedätte, että kesä on lähellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Samoin myös, kun näette tämän tapahtuvan, tietäkää, että se on lähellä, oven edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Totisesti sanon teille: tämä sukukunta ei katoa, ennen kuin kaikki nämä tapahtuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Taivas ja maa katoavat, mutta minun sanani eivät katoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Mutta siitä päivästä tai hetkestä ei tiedä kukaan, eivät enkelit taivaassa, eikä myöskään Poika, paitsi Isä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Olkaa varuillanne, valvokaa ja rukoilkaa, sillä ette tiedä, milloin se aika on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'On kuin matkoille lähteneen miehen: kun hän jätti talonsa ja valtuutti palvelijansa antaen kullekin oman tehtävänsä, hän käski myös ovenvartijan valvoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Valvokaa siis, sillä ette tiedä, milloin talon isäntä tulee, myöhään illalla, keskellä yötä, kukonlaulun aikaan vai varhain aamulla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'ettei hän tullessaan äkkiarvaamatta tapaisi teitä nukkumasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Mutta minkä teille sanon, sen sanon kaikille: valvokaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Sitten oli kahden päivän perästä pääsiäinen ja happamattoman leivän juhla, ja ylipapit ja kirjanoppineet etsivät, kuinka saisivat hänet otetuksi kavaluudella kiinni ja tapetuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Sillä he sanoivat: \"Ei juhlan aikana, ettei syntyisi meteliä kansassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Kun hän oli Betaniassa, spitaalisen Simonin asunnossa, tuli hänen aterialla ollessaan nainen, mukanaan alabasteripullo täynnä oikeaa, kallista nardusvoidetta. Hän rikkoi alabasteripullon ja vuodatti voiteen hänen päähänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Oli muutamia, jotka närkästyivät ja sanoivat keskenään: \"Miksi tämä voiteen haaskaus?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Olisihan tämän voinut myydä enempään kuin kolmeensataan denaariin ja antaa ne köyhille.\" He nuhtelivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Mutta Jeesus sanoi: \"Antakaa hänen olla. Miksi pahoitatte hänen mielensä? Hän teki hyvän työn minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Köyhät teillä on aina keskuudessanne, ja milloin tahdotte, voitte tehdä hyvää heille, mutta minua teillä ei ole aina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Hän teki, minkä voi. Edeltäkäsin hän voiteli ruumiini hautaamista varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Totisesti sanon teille: missä ikinä kaikessa maailmassa evankeliumia saarnataan, siellä sekin, minkä tämä teki, julistetaan hänen muistokseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Juudas Iskariot, yksi niistä kahdestatoista, meni ylipappien luo kavaltaakseen hänet heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Kun nämä sen kuulivat, he ihastuivat ja lupasivat antaa hänelle rahaa. Hän mietti, kuinka kavaltaisi hänet sopivassa tilaisuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Ensimmäisenä happamattoman leivän päivänä, kun pääsiäislammas teurastettiin, hänen opetuslapsensa sanoivat hänelle: \"Mihin tahdot, että menemme valmistamaan pääsiäislampaan sinun syödäksesi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Hän lähetti kaksi opetuslastaan ja sanoi heille: \"Menkää kaupunkiin, niin teitä vastaan tulee mies kantaen vesiastiaa, seuratkaa häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'Mihin hän menee, sanokaa talon isännälle: \'Opettaja sanoo: Missä on vierashuoneeni syödäkseni siinä pääsiäislampaan opetuslasteni kanssa?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Hän näyttää teille suuren huoneen yläkerrassa, valmiiksi laitetun, valmistakaa meille sinne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Opetuslapset lähtivät ja tulivat kaupunkiin ja havaitsivat niin olevan, kuin Jeesus oli heille sanonut, ja valmistivat pääsiäislampaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Kun ehtoo tuli, hän saapui sinne niiden kahdentoista kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Kun he olivat aterialla ja söivät, Jeesus sanoi: \"Totisesti sanon teille: yksi teistä kavaltaa minut, eräs, joka syö kanssani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'He tulivat murheellisiksi ja rupesivat toinen toisensa perästä sanomaan hänelle: \"Enhän minä se ole?\" Ja toinen: \"Enhän minä se ole?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Mutta hän vastasi ja sanoi heille: \"Yksi teistä kahdestatoista, se, joka kastaa [leipää] vatiin minun kanssani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Niin, Ihmisen Poika tosin menee pois, kuten hänestä on kirjoitettu, mutta voi sitä ihmistä, joka Ihmisen Pojan kavaltaa! Parempi olisi sille ihmiselle, ettei hän olisi syntynyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Heidän syödessään Jeesus otti leivän, siunasi, mursi, antoi heille ja sanoi: \"Ottakaa, tämä on minun ruumiini.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Hän otti maljan, kiitti ja antoi heille, ja he kaikki joivat siitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'Hän sanoi heille: \"Tämä on minun vereni, liiton veri, joka vuodatetaan monen edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Totisesti sanon teille: en juo enää viinipuun antia, ennen kuin sinä päivänä, jona juon sitä uutena Jumalan valtakunnassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Lausuttuaan kiitosvirren he lähtivät Öljymäelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Jeesus sanoi heille: \"Kaikki te loukkaannutte minuun tänä yönä, sillä kirjoitettu on: \'Lyön paimenta, ja lampaat hajotetaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Mutta ylösnoustuani menen edellänne Galileaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Pietari sanoi hänelle: \"Vaikka kaikki loukkaantuisivat, en kuitenkaan minä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Jeesus sanoi hänelle: \"Totisesti sanon sinulle: tänään, tänä yönä, ennen kuin kukko kahdesti laulaa, sinä kolmesti minut kiellät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Mutta hän vakuutti vielä lujemmin: \"Vaikka minun pitäisi kuolla sinun kanssasi, en sittenkään kiellä sinua.\" Ja samoin sanoivat kaikki muutkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'He tulivat maatilalle, jonka nimi on Getsemane, ja hän sanoi opetuslapsilleen: \"Istukaa tässä sillä aikaa, kun rukoilen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Hän otti mukaansa Pietarin, Jaakobin ja Johanneksen, ja hän alkoi kauhistua ja tulla tuskaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'Hän sanoi heille: \"Minun sieluni on syvästi murheellinen, kuolemaan asti, olkaa tässä ja valvokaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Hän meni vähän edemmäksi, lankesi maahan ja rukoili, että, jos mahdollista, se hetki menisi häneltä ohi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'ja sanoi: \"Abba, Isä, kaikki on mahdollista sinulle, ota pois minulta tämä malja. Mutta ei mitä minä tahdon, vaan mitä sinä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Hän tuli ja tapasi heidät nukkumasta ja sanoi Pietarille: \"Simon, nukutko? Etkö jaksanut yhtä hetkeä valvoa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Valvokaa ja rukoilkaa, ettette joutuisi kiusaukseen. Henki tosin on altis, mutta liha on heikko.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'Hän meni taas pois ja rukoili sanoen samat sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'Tullessaan hän tapasi taas heidät nukkumasta, sillä heidän silmänsä olivat käyneet kovin raskaiksi, eivätkä he tienneet, mitä vastaisivat hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'Hän tuli kolmannen kerran ja sanoi heille: \"Nukutte vielä ja lepäätte! Jo riittää! Hetki on tullut, katso, Ihmisen Poika annetaan syntisten käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Nouskaa, lähtekäämme, katso, se, joka kavaltaa minut, on lähellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Heti hänen vielä puhuessaan Juudas, yksi niistä kahdestatoista, saapui, ja hänen mukanaan suuri joukko ylipappien, kirjanoppineiden ja vanhinten luota, miekat ja seipäät käsissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Mutta se, joka hänet kavalsi, antoi heille merkin sanoen: \"Se, jota tervehdin suudelmalla, hän se on. Ottakaa hänet kiinni ja viekää tarkasti vartioituna pois.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Tultuaan hän heti astui hänen luokseen ja sanoi: \"Rabbi!\" ja tervehti häntä suudelmalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'He kävivät häneen käsiksi ja ottivat hänet kiinni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Mutta eräs niistä, jotka seisoivat lähellä, veti miekkansa, iski ylipapin palvelijaa ja sivalsi häneltä pois korvan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Niin Jeesus puhui heille ja sanoi: \"Niin kuin ryöväriä vastaan te olette lähteneet minua miekoilla ja seipäillä vangitsemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Joka päivä olen ollut luonanne opettaen pyhäkössä, ettekä ole ottaneet minua kiinni. Mutta tämä tapahtuu, että Kirjoitukset kävisivät toteen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'He kaikki jättivät hänet ja pakenivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Häntä seurasi eräs nuorukainen, jolla oli ympärillään liinavaate paljaalle iholle heitettynä, ja nuoret miehet ottivat hänet kiinni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'Mutta hän jätti liinavaatteen ja pakeni alasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'He veivät Jeesuksen ylipapin eteen, jonne kaikki ylipapit, vanhimmat ja kirjanoppineet kokoontuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Pietari seurasi häntä taaempana ylipapin palatsin esipihaan asti ja istuutui palvelijoiden joukkoon ja lämmitteli tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Mutta ylipapit ja koko neuvosto etsivät todistusta Jeesusta vastaan tappaakseen hänet, mutta eivät löytäneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Monet kyllä todistivat väärin häntä vastaan, mutta todistukset eivät olleet yhtäpitäviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Muutamat nousivat ja todistivat väärin häntä vastaan sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, '\"Me olemme kuulleet hänen sanovan: \'Minä hajotan maahan tämän käsillä tehdyn temppelin ja rakennan kolmessa päivässä toisen, joka ei ole käsillä tehty.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Mutta näinkään heidän todistuksensa eivät olleet yhtäpitäviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Silloin ylipappi nousi, astui esiin ja kysyi Jeesukselta sanoen: \"Etkö vastaa mitään? Mitä nämä todistavat sinua vastaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Mutta hän oli vaiti eikä vastannut mitään. Taas ylipappi kysyi häneltä ja sanoi hänelle: \"Oletko sinä Kristus, sen Ylistetyn Poika?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Jeesus sanoi: \" Minä olen, ja te saatte nähdä Ihmisen Pojan istuvan Voiman oikealla puolella ja tulevan taivaan pilvissä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Ylipappi repäisi vaatteensa ja sanoi: \"Mitä enää todistajia tarvitsemme?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Kuulitte hänen pilkkaamisensa. Mitä arvelette?\" Niin he kaikki tuomitsivat hänet syylliseksi kuolemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Muutamat rupesivat sylkemään hänen päälleen, peittivät hänen kasvonsa, löivät häntä nyrkillä ja sanoivat hänelle: \"Profetoi!\" Palvelijatkin löivät häntä poskelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Kun nyt Pietari oli alhaalla pihassa, sinne tuli eräs ylipapin palvelustytöistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'Nähdessään Pietarin lämmittelevän hän katsoi häneen ja sanoi: \"Sinäkin olit Jeesus Nasaretilaisen kanssa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Mutta hän kielsi sanoen: \"En tiedä enkä käsitä, mitä sanot.\" Hän meni ulos pihalle, ja kukko lauloi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Nähdessään hänet siellä palvelustyttö rupesi taas sanomaan lähellä seisoville: \"Tämä on yksi niistä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Mutta hän kielsi uudestaan. Vähän sen jälkeen lähellä seisoneet taas sanoivat Pietarille: \"Totisesti, olet yksi niistä, sillä olethan galilealainenkin. Puheesikin on sellaista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Mutta hän alkoi kirota itseään ja vannoa: \"En tunne sitä miestä, josta te puhutte.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Samassa kukko lauloi toisen kerran. Pietari muisti Jeesuksen sanat, jotka hän oli sanonut hänelle: \"Ennen kuin kukko kahdesti laulaa, [sinä] kiellät minut kolmesti.\" Ja hän purskahti itkuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Heti varhain aamulla ylipapit, vanhimmat, kirjanoppineet ja koko Neuvosto pidettyään neuvottelun sitoivat Jeesuksen, veivät hänet pois ja luovuttivat Pilatukselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Pilatus kysyi häneltä: \"Oletko sinä juutalaisten kuningas?\" Hän vastasi ja sanoi hänelle: \"Sinä sen sanot.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Ylipapit tekivät monta syytöstä häntä vastaan, mutta hän ei vastannut mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Pilatus kysyi taas häneltä sanoen: \"Etkö vastaa mitään? Katso, kuinka paljon syytöksiä he tekevät sinua vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Mutta Jeesus ei enää vastannut mitään, niin että se hämmästytti Pilatusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Mutta juhlan aikana hänellä oli tapana vapauttaa heille yksi vanki, se, jota he anoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Siellä oli eräs mies, jota sanottiin Barabbaaksi, vangittu muiden kapinoitsijoiden kanssa, jotka kapinassa olivat tehneet murhan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Kansa meni sinne ylös ja rupesi pyytämään, että hän tekisi heille, kuten hänellä oli tapana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Pilatus vastasi heille sanoen: \"Tahdotteko, että päästän teille juutalaisten kuninkaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Sillä hän tiesi, että ylipapit olivat kateudesta luovuttaneet hänet hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Mutta ylipapit kiihottivat kansaa anomaan, että hän ennemmin vapauttaisi heille Barabbaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Mutta Pilatus vastasi ja puhui taas heille ja sanoi: \"Mitä minun sitten on tehtävä sille, jota te sanotte juutalaisten kuninkaaksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Niin he taas huusivat: \"Ristiinnaulitse hänet!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Mutta Pilatus sanoi heille: \"Mitä pahaa hän on tehnyt?\" Mutta he huusivat vielä kovemmin: \"Ristiinnaulitse hänet!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Kun Pilatus tahtoi tehdä kansalle mieliksi, hän vapautti heille Barabbaan, mutta Jeesuksen hän ruoskitti ja luovutti ristiinnaulittavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Sotamiehet veivät hänet sisälle esipihaan, se on maaherran virka-asuntoon, ja kutsuivat sinne koko kohortin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'He pukivat hänen päälleen purppuravaatteen, väänsivät orjantappuroista kruunun ja panivat sen hänen päähänsä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'ja rupesivat tervehtimään häntä: \"Terve, juutalaisten kuningas!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'He löivät häntä päähän ruokokepillä, sylkivät hänen päälleen ja laskeutuen polvilleen kumarsivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Kun he olivat häntä pilkanneet, he riisuivat häneltä purppuraviitan, pukivat hänet hänen omiin vaatteisiinsa ja veivät hänet pois ristiinnaulitakseen hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'He pakottivat erään ohikulkevan miehen, Simonin, kyreneläisen, joka tuli pellolta, Aleksanterin ja Rufuksen isän, kantamaan hänen ristiään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'He veivät hänet paikalle, jonka nimi on Golgata, se on käännettynä: pääkallonpaikka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'He tarjosivat hänelle mirhalla sekoitettua viiniä, mutta hän ei ottanut sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'He ristiinnaulitsivat hänet ja jakoivat keskenään hänen vaatteensa heittäen niistä arpaa, mitä kukin oli saava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Oli kolmas tunti, kun he hänet ristiinnaulitsivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'Päällekirjoitukseksi oli merkitty hänen syynsä: \"Juutalaisten kuningas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'He ristiinnaulitsivat hänen kanssaan kaksi ryöväriä, toisen hänen oikealle ja toisen hänen vasemmalle puolelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'Niin kävi toteen Raamattu, joka sanoo: \"Hänet luettiin pahantekijöiden joukkoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Ohikulkijat herjasivat häntä ja nyökyttivät päätään ja sanoivat: \"Voi sinua, joka hajotat maahan temppelin ja kolmessa päivässä sen rakennat!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'Auta itseäsi ja astu alas ristiltä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Samoin ylipapitkin sekä kirjanoppineet pilkkasivat häntä keskenään ja sanoivat: \"Muita hän on auttanut, itseään ei voi auttaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Astukoon hän, Kristus, Israelin kuningas, nyt alas ristiltä, että näkisimme ja uskoisimme.\" Myös ne, jotka olivat ristiinnaulitut hänen kanssaan, herjasivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'Kuudennella tunnilla tuli pimeys yli koko maan, ja sitä kesti aina yhdeksänteen tuntiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'Yhdeksännellä tunnilla Jeesus huusi suurella äänellä: \"Eeli, Eeli, lama sabaktani?\" Se on käännettynä: Jumalani, Jumalani, miksi minut hylkäsit?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Sen kuullessaan sanoivat muutamat niistä, jotka siinä seisoivat: \"Katso, hän huutaa Eliaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Eräs mies juoksi ja täytti sienen hapanviinillä, pani sen ruokokepin päähän ja antoi hänelle juoda sanoen: \"Annahan olla, katsokaamme, tuleeko Elia ottamaan hänet alas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Mutta Jeesus huusi suurella äänellä ja antoi henkensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'Temppelin esirippu repesi kahtia ylhäältä alas asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Mutta kun sadanpäällikkö, joka seisoi häntä vastapäätä, näki hänen tällä tavalla antavan henkensä, hän sanoi: \"Totisesti tämä ihminen oli Jumalan Poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Siellä oli myös naisia taaempaa katselemassa. Näiden joukossa olivat Maria Magdaleena ja Maria, Jaakob nuoremman ja Jooseen äiti, sekä Salome,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'jotka hänen ollessaan Galileassa olivat seuranneet ja palvelleet häntä, sekä monia muita, jotka olivat tulleet hänen kanssaan ylös Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'Kun ilta oli jo tullut, ja koska oli valmistuspäivä, se on sapatin aattopäivä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'tuli Joosef, arimatialainen, arvossapidetty Neuvoston jäsen, joka hänkin odotti Jumalan valtakuntaa, rohkaisi mielensä ja meni sisälle Pilatuksen luo ja pyysi Jeesuksen ruumista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Pilatus ihmetteli, oliko hän jo kuollut, ja kutsuttuaan luokseen sadanpäällikön kysyi tältä, oliko hän jo kauan sitten kuollut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'Saatuaan sadanpäälliköltä tiedon siitä hän lahjoitti ruumiin Joosefille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Tämä osti liinavaatteen, otti hänet alas, kääri hänet liinavaatteeseen, pani hautaan, joka oli hakattu kallioon, ja vieritti kiven haudan ovelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Maria Magdaleena ja Maria, Jooseen äiti, katselivat, mihin hänet pantiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Sapatin mentyä ohi ostivat Maria Magdaleena ja Maria, Jaakobin äiti, sekä Salome hyvänhajuisia yrttejä mennäkseen voitelemaan hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Ani varhain viikon ensimmäisenä päivänä he tulivat haudalle, auringon noustessa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'ja sanoivat toisilleen: \"Kuka vierittää meille kiven haudan ovelta?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Kohotettuaan katseensa he näkivät kiven poisvieritetyksi, se oli näet hyvin suuri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Mentyään sisälle hautaan he näkivät nuorukaisen istuvan oikealla puolella puettuna pitkään, valkoiseen vaatteeseen, ja pelästyivät suuresti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Mutta hän sanoi heille: \"Älkää pelästykö, te etsitte Jeesusta, Nasaretilaista, joka oli ristiinnaulittu. Hänet on herätetty kuolleista, hän ei ole täällä. Katso, tässä on paikka, johon he hänet panivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Mutta menkää ja sanokaa hänen opetuslapsilleen ja Pietarille: \'Hän menee teidän edellänne Galileaan, siellä näette hänet, kuten hän teille sanoi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'He tulivat ulos nopeasti ja pakenivat haudalta, sillä he vapisivat järkyttyneinä eivätkä sanoneet kenellekään mitään, sillä he pelkäsivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Mutta ylösnoustuaan hän varhain aamulla viikon ensimmäisenä päivänä ilmestyi ensiksi Maria Magdaleenalle, josta hän oli ajanut ulos seitsemän riivaajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Tämä meni ja vei sanan niille, jotka olivat olleet Jeesuksen kanssa ja jotka nyt murehtivat ja itkivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Kun he kuulivat, että hän eli ja että Maria oli nähnyt hänet, he eivät uskoneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Mutta sen jälkeen hän toisenmuotoisena ilmestyi kahdelle heistä heidän kävellessään maaseudulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Hekin menivät ja veivät sanan toisille, jotka eivät kuitenkaan uskoneet heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Vihdoin hän ilmestyi myös niille yhdelletoista heidän ollessaan aterialla. Hän nuhteli heidän epäuskoaan ja heidän sydämensä kovuutta, kun he eivät olleet uskoneet niitä, jotka olivat nähneet hänet kuolleista herätettynä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Hän sanoi heille: \"Menkää kaikkeen maailmaan ja saarnatkaa evankeliumi kaikille luoduille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Joka uskoo ja tulee kastetuksi, se pelastuu, mutta se, joka ei usko, tuomitaan kadotukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Nämä merkit seuraavat niitä, jotka uskovat: minun nimessäni he ajavat ulos riivaajia, puhuvat uusilla kielillä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'nostavat käsin käärmeitä, ja jos he juovat jotakin kuolettavaa, se ei vahingoita heitä. He panevat kätensä sairaiden päälle, ja nämä paranevat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Kun nyt Herra Jeesus oli puhunut heille, otettiin hänet ylös taivaaseen, ja hän istuutui Jumalan oikealle puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Mutta he lähtivät ja saarnasivat kaikkialla, ja Herra vaikutti heidän kanssaan ja vahvisti sanan sitä seuraavien merkkien kautta. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Koska monet ovat ryhtyneet laatimaan kertomusta keskuudessamme toteutuneista tapahtumista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'sen mukaan kuin meille ovat kertoneet ne, jotka alusta asti ovat olleet silminnäkijöitä ja sananpalvelijoita,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'minäkin tarkkaan tutkittuani alusta alkaen kaikki olen nähnyt hyväksi kirjoittaa ne järjestyksessä sinulle, korkea-arvoinen Teofilos,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'että oppisit tuntemaan, kuinka varmat ovat ne asiat, jotka sinulle on opetettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Herodeksen, Juudean kuninkaan, aikana oli pappi, nimeltä Sakarias, Abian osastoa. Hänen vaimonsa oli Aaronin tyttäriä, ja hänen nimensä oli Elisabet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'He olivat molemmat vanhurskaita Jumalan edessä vaeltaen nuhteettomina kaikissa Herran käskyissä ja säädöksissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Mutta heillä ei ollut lasta, sillä Elisabet oli hedelmätön, ja he olivat molemmat tulleet vanhoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Tapahtui, kun hänen [Sakariaan] osastonsa palvelusvuoro tuli ja hän toimitti papillisia tehtäviä Jumalan edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'että tavanmukaisessa papintehtävien arvonnassa hän sai osakseen mennä Herran temppeliin suitsuttamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Koko kansanjoukko oli suitsuttamisen aikaan ulkopuolella rukoilemassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Hänelle ilmestyi Herran enkeli seisoen suitsutusalttarin oikealla puolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Hänet nähdessään Sakarias säikähti, ja hänet valtasi pelko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Mutta enkeli sanoi hänelle: \"Älä pelkää, Sakarias, sillä rukouksesi on kuultu, ja vaimosi Elisabet on synnyttävä sinulle pojan, ja sinä olet antava hänelle nimen Johannes.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Hän on oleva sinulle iloksi ja riemuksi, ja monet iloitsevat hänen syntymisestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Sillä hän on oleva suuri Herran edessä. Viiniä ja väkijuomaa hän ei juo, ja hän on oleva täytetty Pyhällä Hengellä jo äitinsä kohdusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'Hän kääntää israelilaisista monta Herran, heidän Jumalansa, luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Hän kulkee hänen edellään Eliaan hengessä ja voimassa kääntääkseen isien sydämet lasten puoleen ja tottelemattomat vanhurskasten mielenlaatuun toimittaakseen Herralle valmistetun kansan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Sakarias sanoi enkelille: \"Kuinka tämän käsittäisin? Sillä minä olen vanha, ja vaimoni on iäkäs.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'Enkeli vastasi ja sanoi hänelle: \"Minä olen Gabriel, joka seison Jumalan edessä, ja minut on lähetetty puhumaan sinulle ja julistamaan sinulle tämä ilosanoma.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Katso, tulet mykäksi etkä kykene puhumaan mitään siihen päivään asti, jona tämä tapahtuu, sen tähden ettet uskonut sanojani, jotka toteutuvat aikanaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Kansa oli odottamassa Sakariasta, ja he ihmettelivät, että hän viipyi temppelissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Mutta tullessaan ulos hän ei kyennyt puhumaan heille, ja he ymmärsivät, että hän oli nähnyt näyn temppelissä. Hän viittoi heille ja jäi mykäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'Tapahtui, että kun hänen virkatoimensa päivät olivat päättyneet, hän meni kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Niiden päivien jälkeen Elisabet, hänen vaimonsa, tuli raskaaksi ja pysyi kotona viisi kuukautta, sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, '\"Näin on Herra tehnyt minulle näinä päivinä, jolloin hän katsoi puoleeni ja poisti minusta ihmisten halveksunnan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'Kuudentena kuukautena sen jälkeen Jumala lähetti enkeli Gabrielin Galilean kaupunkiin, jonka nimi on Nasaret,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'neitsyen luo, joka oli kihlattu Joosef-nimiselle miehelle Daavidin huoneesta, ja neitsyen nimi oli Maria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'Tullessaan sisälle hänen luokseen enkeli sanoi: \"Terve, armoitettu! Herra olkoon kanssasi, sinä siunattu vaimojen joukossa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Mutta hän hämmästyi suuresti tästä puheesta ja mietti, mitä tämä tervehdys mahtoi tarkoittaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Enkeli sanoi hänelle: \"Älä pelkää, Maria, sillä olet saanut armon Jumalan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'Katso, tulet raskaaksi ja synnytät pojan, ja annat hänelle nimen Jeesus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Hän on oleva suuri, ja hänet tulee kutsua Korkeimman Pojaksi, ja Herra Jumala antaa hänelle Daavidin, hänen isänsä, valtaistuimen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'ja hän on oleva Jaakobin huoneen kuningas iankaikkisesti, eikä hänen valtakunnallaan ole loppua oleva.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Maria sanoi enkelille: \"Kuinka tämä tapahtuu, sillä en tiedä miehestä mitään?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'Enkeli vastasi ja sanoi hänelle: \"Pyhä Henki tulee päällesi, ja Korkeimman voima levittää varjonsa yllesi. Sen tähden myös se pyhä, mikä syntyy, kutsutaan Jumalan Pojaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Katso, sukulaisesi Elisabet, hänkin kantaa kohdussaan poikaa vanhalla iällään, ja tämä on kuudes kuukausi hänellä, jota sanottiin hedelmättömäksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'sillä Jumalalle ei ole mikään mahdotonta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Maria sanoi: \"Katso, olen Herran palvelijatar. Tapahtukoon minulle sinun sanasi mukaan.\" Ja enkeli lähti hänen luotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Niinä päivinä Maria nousi ja lähti kiireesti Vuorimaahan erääseen Juudan kaupunkiin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'ja meni Sakariaan kotiin ja tervehti Elisabetia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'Tapahtui, että kun Elisabet kuuli Marian tervehdyksen, hypähti lapsi hänen kohdussaan, ja Elisabet täytettiin Pyhällä Hengellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'Hän alkoi puhua kovalla äänellä ja sanoi: \"Siunattu sinä vaimojen joukossa, ja siunattu kohtusi hedelmä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Kuinka minulle tapahtuu tämä, että Herrani äiti tulee luokseni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Sillä katso, kun tervehdyksesi ääni tuli korviini, hypähti lapsi riemusta kohdussani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'Autuas se, joka uskoi, sillä se sana on täyttyvä, mikä hänelle on tullut Herralta!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Maria sanoi: \"Sieluni ylistää suuresti Herraa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'ja henkeni riemuitsee Jumalasta, vapahtajastani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'sillä hän on katsonut palvelijattarensa alhaisuuteen. Katso, tästedes kaikki sukukunnat ylistävät minua autuaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Sillä Voimallinen on tehnyt minulle suuria, ja hänen nimensä on Pyhä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'ja hänen laupeutensa pysyy polvesta polveen niille, jotka häntä pelkäävät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Hän on osoittanut voimansa käsivarrellaan. Hän on hajottanut ne, joilla oli ylpeät ajatukset sydämessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Hän on syössyt valtiaat valtaistuimilta ja korottanut alhaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Nälkäiset hän on täyttänyt hyvyyksillä, ja rikkaat hän on lähettänyt tyhjinä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Hän on ottanut huomaansa palvelijansa Israelin muistaakseen laupeutta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'Aabrahamia ja hänen siementään kohtaan iankaikkisesti, kuten hän on isillemme puhunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Mutta Maria viipyi hänen luonaan noin kolme kuukautta ja palasi kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Elisabetin synnyttämisen aika tuli, ja hän synnytti pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Kun sitten hänen naapurinsa ja sukulaisensa kuulivat, että Herra oli tehnyt hänelle suuren laupeuden, he iloitsivat hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Tapahtui kahdeksantena päivänä, että he tulivat ympärileikkaamaan lasta ja aikoivat antaa hänelle hänen isänsä mukaan nimen Sakarias.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'Mutta hänen äitinsä vastasi ja sanoi: \"Ei suinkaan, vaan hänen nimensä on oleva Johannes.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'He sanoivat hänelle: \"Eihän suvussasi ole ketään, jolla on se nimi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'He tiedustelivat viittomalla lapsen isältä, minkä nimen hän tahtoi hänelle annettavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Hän pyysi taulun ja kirjoitti siihen nämä sanat: \"Johannes on hänen nimensä.\" Ja kaikki ihmettelivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'Heti hänen suunsa aukeni, ja hänen kielensä vapautui, ja hän puhui kiittäen Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'Ja kaikille heidän ympärillään asuville tuli pelko, ja koko Juudean Vuorimaassa puhuttiin kaikista näistä tapahtumista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'Kaikki, jotka niistä kuulivat, panivat ne mieleensä ja sanoivat: \"Mikä tästä lapsesta tulee?\" Sillä Herran käsi oli hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'Sakarias, hänen isänsä, täytettiin Pyhällä Hengellä, ja hän profetoi sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, '\"Kiitetty olkoon Herra, Israelin Jumala, sillä hän on katsonut kansansa puoleen, valmistanut sille lunastuksen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'ja kohottanut meille pelastuksen sarven palvelijansa Daavidin huoneeseen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, '– kuten hän on puhunut ikiajoista asti pyhien profeettojensa suun kautta –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'pelastukseksi vihollisistamme ja kaikkien niiden kädestä, jotka meitä vihaavat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'tehdäkseen laupeuden isillemme ja muistaakseen pyhän liittonsa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'sen valan, jonka hän vannoi Aabrahamille, isällemme;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'suodakseen meidän vapahdettuina vihollistemme kädestä pelkäämättä palvella häntä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'pyhyydessä ja vanhurskaudessa hänen edessään kaikkina elinpäivinämme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Lapsukainen, sinua sanotaan Korkeimman profeetaksi, sillä sinä olet käyvä Herran edellä valmistaaksesi hänen teitään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'antaaksesi hänen kansalleen pelastuksen tuntemisen heidän syntiensä anteeksiantamisessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'Jumalamme sydämellisen laupeuden tähden, jonka kautta puoleemme katsoo aamun koitto korkeudesta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'loistaen meille, jotka istumme pimeydessä ja kuoleman varjossa, ja ohjaten jalkamme rauhan tielle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Mutta lapsi kasvoi ja vahvistui Hengessä. Hän oli erämaassa siihen päivään asti, jona hän oli astuva Israelin eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'Tapahtui niinä päivinä, että keisari Augustukselta lähti käsky, että koko maailma oli kirjoitettava veroluetteloihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Tämä merkitseminen oli ensimmäinen ja tapahtui Kyreniuksen ollessa Syyrian maaherrana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Kaikki lähtivät luetteloihin merkittäviksi, kukin omaan kaupunkiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Joosefkin lähti Galileasta, Nasaretin kaupungista, ylös Juudeaan, Daavidin kaupunkiin, jonka nimi on Beetlehem, hän kun oli Daavidin huonetta ja sukua,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'veroluetteloihin merkittäväksi Marian, hänelle kihlatun vaimon kanssa, joka oli raskaana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Tapahtui heidän siellä ollessaan, että Marian synnyttämisen aika täyttyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'Hän synnytti pojan, esikoisensa, kapaloi hänet ja pani hänet seimeen, koska heille ei ollut tilaa vierashuoneessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Sillä seudulla oli paimenia kedolla vartioimassa yöllä laumaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Katso, heidän edessään seisoi Herran enkeli, ja Herran kirkkaus loisti heidän ympärillään, ja heidät valtasi suuri pelko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Mutta enkeli sanoi heille: \"Älkää pelätkö; sillä katso, ilmoitan teille suuren ilon, joka on tuleva kaikelle kansalle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'teille on tänä päivänä syntynyt Vapahtaja, joka on Kristus, Herra, Daavidin kaupungissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Tämä on teille merkkinä: löydätte lapsen kapaloituna seimessä makaamassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Yhtäkkiä enkelin kanssa oli suuri joukko taivaallista sotaväkeä, ja he ylistivät Jumalaa ja sanoivat:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, '\"Jumalan on kunnia korkeuksissa, ja maassa rauha ihmisten kesken, joihin hänellä on mielisuosio!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Tapahtui, kun enkelit olivat menneet heidän luotaan taivaaseen, niin miehet, paimenet, puhuivat toisilleen: \"Menkäämme nyt Beetlehemiin katsomaan sitä, mikä on tapahtunut ja minkä Herra meille ilmoitti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'He menivät kiiruhtaen ja löysivät Marian ja Joosefin ja lapsen, joka makasi seimessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Kun he tämän olivat nähneet, he ilmoittivat sen sanan, joka oli puhuttu heille tästä lapsesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Kaikki, jotka sen kuulivat, ihmettelivät sitä, mitä paimenet heille puhuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Mutta Maria talletti kaikki nämä sanat ja tutkisteli niitä sydämessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Paimenet palasivat kiittäen ja ylistäen Jumalaa kaikesta, minkä olivat kuulleet ja nähneet, kuten heille oli puhuttu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Kun sitten kahdeksan päivää oli kulunut ja lapsi oli ympärileikattava, annettiin hänelle nimi Jeesus, jonka enkeli oli hänelle antanut, ennen kuin hän sikisi kohdussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Kun hänen [Marian] puhdistuspäivänsä Mooseksen lain mukaan olivat täyttyneet, he veivät hänet [Jeesuksen] ylös Jerusalemiin asettaakseen hänet Herran eteen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '– kuten on kirjoitettuna Herran laissa: \"Jokainen miehenpuoli, joka avaa äidinkohdun, luettakoon Herralle pyhitetyksi\" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'ja uhratakseen, kuten Herran laissa on säädetty, parin metsäkyyhkysiä tai kaksi kyyhkysenpoikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'Katso, Jerusalemissa oli mies, nimeltä Simeon; hän oli vanhurskas ja jumalinen mies, joka odotti Israelin lohdutusta, ja Pyhä Henki oli hänen päällään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'Pyhä Henki oli hänelle ilmoittanut, ettei hän ollut näkevä kuolemaa, ennen kuin hän oli nähnyt Herran Kristuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Ja hän tuli Hengessä pyhäkköön. Kun vanhemmat toivat Jeesus-lasta sisälle tehdäkseen hänelle, kuten tapa oli lain mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'hänkin otti hänet syliinsä ja kiitti Jumalaa ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, '\"Herra, nyt lasket palvelijasi rauhaan menemään, sanasi mukaan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'sillä silmäni ovat nähneet pelastuksesi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'jonka olet valmistanut kaikkien kansojen eteen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'valkeudeksi valaisemaan pakanoita ja kirkkaudeksi kansallesi Israelille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Joosef ja hänen äitinsä ihmettelivät sitä, mitä hänestä sanottiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Simeon siunasi heitä ja sanoi Marialle, hänen äidilleen: \"Katso, tämä on pantu lankeamiseksi ja nousemiseksi monelle Israelissa ja merkiksi, jota vastaan sanotaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, '– ja myös sinun sielusi lävitse on miekka käyvä, että monen sydämen ajatukset tulisivat ilmi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Oli naisprofeetta, Hanna, Fanuelin tytär, Asserin sukukuntaa. Hän oli tullut jo vanhaksi. Mentyään neitsyenä naimisiin hän oli elänyt miehensä kanssa seitsemän vuotta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'ja oli nyt leski, kahdeksankymmenen neljän vuoden ikäinen. Hän ei poistunut pyhäköstä, vaan palveli siellä Jumalaa paastoilla ja rukouksilla öin ja päivin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'Juuri sillä hetkellä hän tuli siihen, ylisti Jumalaa ja puhui lapsesta kaikille, jotka odottivat lunastusta Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Täytettyään kaiken, mikä Herran lain mukaan oli tehtävä, he palasivat Galileaan, kaupunkiinsa Nasaretiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Mutta lapsi kasvoi, vahvistui hengessä ja täyttyi viisaudella, ja Jumalan armo oli hänen päällään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Hänen vanhempansa vaelsivat joka vuosi Jerusalemiin pääsiäisjuhlille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Kun hän oli kaksitoistavuotias, he menivät sinne ylös juhlan tavan mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'Kun ne päivät olivat kuluneet ja he lähtivät kotiin, Jeesus-poika jäi Jerusalemiin, eivätkä Joosef ja hänen äitinsä tienneet sitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'vaan he olettivat hänen olevan matkaseurueessa ja kulkivat päivänmatkan ja etsivät häntä sukulaisten ja tuttavien joukosta;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'mutta kun eivät löytäneet, he palasivat Jerusalemiin etsimään häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'Tapahtui, että he kolmen päivän kuluttua löysivät hänet pyhäköstä istumassa opettajien keskellä heitä kuunnellen ja heiltä kysellen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'Kaikki, jotka häntä kuuntelivat, ihmettelivät hänen ymmärrystään ja vastauksiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Hänet nähdessään hänen vanhempansa hämmästyivät, ja hänen äitinsä sanoi hänelle: \"Poikani, miksi teit meille näin? Katso, sinun isäsi ja minä olemme huolestuneina etsineet sinua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'Hän sanoi heille: \"Mitä te minua etsitte? Ettekö tienneet, että minun pitää olla niissä, mitkä minun Isäni ovat?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Mutta he eivät ymmärtäneet sitä sanaa, jonka hän heille puhui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Hän lähti heidän kanssaan, tuli Nasaretiin ja oli heille alamainen. Mutta hänen äitinsä talletti kaikki nämä sanat sydämeensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Jeesus varttui viisaudessa, iässä ja armossa Jumalan ja ihmisten edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'Viidentenätoista keisari Tiberiuksen hallitusvuotena, kun Pontius Pilatus oli Juudean maaherrana ja Herodes Galilean neljännesruhtinaana ja hänen veljensä Filippos Iturean ja Trakonitiin maan neljännesruhtinaana ja Lysanias Abilenen neljännesruhtinaana,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'siihen aikaan kun Hannas oli ylipappina, sekä myös Kaifas, tuli Jumalan sana Johannekselle, Sakariaan pojalle, erämaassa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Hän meni kaikkiin Jordanin lähiseutuihin ja saarnasi mielenmuutoksen kastetta syntien anteeksisaamiseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'kuten on kirjoitettuna profeetta Jesajan sanojen kirjassa: \"Airuen ääni kuuluu erämaassa: \'Valmistakaa Herralle tie, tehkää hänen polkunsa tasaisiksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Kaikki rotkot täytettäköön, kaikki vuoret ja kukkulat alennettakoon, mutkat tulkoot suoriksi ja koleikot tasaisiksi teiksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'ja kaikki liha on näkevä Jumalan pelastuksen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Hän sanoi kansalle, joka vaelsi hänen kastettavakseen: \"Te kyykäärmeitten sikiöt, kuka on neuvonut teitä pakenemaan tulevaa vihaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Tehkää sen tähden mielenmuutoksen mukaisia hedelmiä, älkääkä ruvetko sanomaan mielessänne: \'Onhan meillä isänä Aabraham\', sillä sanon teille, että Jumala voi näistä kivistä herättää lapsia Aabrahamille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Kirves on jo pantu puitten juurelle: jokainen puu, joka ei tee hyvää hedelmää, hakataan siis pois ja heitetään tuleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Kansa kysyi häneltä sanoen: \"Mitä meidän siis pitää tehdä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Hän vastasi ja sanoi heille: \"Jolla on kaksi paitaa, antakoon toisen sille, joka on ilman; ja se, jolla on ruokaa, tehköön samoin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Tuli myös publikaaneja kastettaviksi, ja he sanoivat hänelle: \"Opettaja, mitä teemme?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Hän sanoi heille: \"Älkää ottako enempää, kuin teille on säädetty.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Myös sotamiehet kysyivät häneltä sanoen: \"Mitä meidän tulee tehdä?\" Hän sanoi heille: \"Älkää kiskoko keneltäkään älkääkä kiristäkö, vaan tyytykää palkkaanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Mutta kun kansa odotti ja kaikki ajattelivat sydämessään Johanneksesta, eikö hän ehkä ollut Kristus,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Johannes vastasi kaikille sanoen: \"Minä kastan teidät vedellä, mutta tulee minua väkevämpi, jonka sandaalin nyöriäkään en ole kelvollinen päästämään. Hän kastaa teidät Pyhällä Hengellä ja tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Hänellä on viskimensä kädessään, ja hän puhdistaa puimatanterensa ja kokoaa vehnät aittaansa, mutta ruumenet hän polttaa sammumattomassa tulessa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Antaen myös monia muita kehotuksia hän julisti kansalle evankeliumia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Mutta kun neljännesruhtinas Herodes sai häneltä nuhteita veljensä vaimon, Herodiaan, tähden ja kaiken sen pahan tähden, mitä Herodes oli tehnyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'hän kaiken muun lisäksi teki senkin, että sulki Johanneksen vankilaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Kun siis kaikkea kansaa kastettiin ja myös Jeesus oli saanut kasteen ja rukoili, tapahtui, että taivas aukeni');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'ja Pyhä Henki laskeutui hänen päälleen ruumiillisessa muodossa kuin kyyhkynen, ja taivaasta tuli ääni: \"Sinä olet rakas Poikani. Sinuun olen mieltynyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Hän, Jeesus, oli aloittaessaan toimintansa noin kolmenkymmenen vuoden vanha, ja oli, kuten luultiin, Joosefin poika. Joosef oli Eelin poika,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'Eeli Mattatin, tämä Leevin, tämä Melkin, tämä Jannain, tämä Joosefin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'tämä Mattatiaan, tämä Aamoksen, tämä Naahumin, tämä Eslin, tämä Naggain,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'tämä Maahatin, tämä Mattatiaan, tämä Semeinin, tämä Joosekin, tämä Joodan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'tämä Johananin, tämä Reesan, tämä Serubbaabelin, tämä Sealtielin, tämä Neerin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'tämä Melkin, tämä Addin, tämä Koosamin, tämä Elmadamin, tämä Eerin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'tämä Jeesuksen, tämä Elieserin, tämä Joorimin, tämä Mattatin, tämä Leevin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'tämä Simeonin, tämä Juudan, tämä Joosefin, tämä Joonamin, tämä Eliakimin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'tämä Melean, tämä Mennan, tämä Mattatan, tämä Naatanin, tämä Daavidin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'tämä Iisain, tämä Oobedin, tämä Booaan, tämä Saalan, tämä Nahassonin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'tämä Aminadabin, tämä Adminin, tämä Arnin, tämä Esromin, tämä Faareen, tämä Juudan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'tämä Jaakobin, tämä Iisakin, tämä Aabrahamin, tämä Taaran, tämä Naahorin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'tämä Serukin, tämä Ragaun, tämä Faalekin, tämä Eberin, tämä Saalan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'tämä Kainamin, tämä Arfaksadin, tämä Seemin, tämä Nooan, tämä Laamekin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'tämä Metusalahin, tämä Eenokin, tämä Jaaretin, tämä Mahalalelin, tämä Keenanin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'tämä Enoksen, tämä Seetin, tämä Aadamin, tämä Jumalan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Jeesus palasi Jordanilta täynnä Pyhää Henkeä, ja Henki kuljetti häntä erämaassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'ja perkele kiusasi häntä neljäkymmentä päivää. Hän ei syönyt mitään niinä päivinä, mutta kun ne olivat päättyneet, hänen tuli nälkä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Perkele sanoi hänelle: \"Jos sinä olet Jumalan Poika, sano tälle kivelle, että se muuttuu leiväksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Jeesus vastasi hänelle: \"Kirjoitettu on: \'Ei ihminen elä ainoastaan leivästä, vaan jokaisesta Jumalan sanasta.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Perkele vei hänet korkealle vuorelle ja näytti hänelle hetkessä kaikki maailman valtakunnat');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'ja sanoi hänelle: \"Sinulle annan kaiken tämän vallan ja näiden kunnian, sillä minun haltuuni se on annettu, ja annan sen, kenelle tahdon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Jos sinä siis kumarrut minun eteeni, niin kaikki on oleva sinun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Jeesus vastasi ja sanoi hänelle: \"Väisty luotani, saatana, sillä kirjoitettu on: \'Herraa, sinun Jumalaasi, tulee sinun kumartaa ja häntä ainoaa palvella.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Hän vei hänet Jerusalemiin ja asetti hänet pyhäkön harjalle ja sanoi hänelle: \"Jos sinä olet Jumalan Poika, heittäydy tästä alas,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'sillä kirjoitettu on: \'Hän antaa enkeleilleen käskyn sinusta, että he varjelevat sinua\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'ja: \'He kantavat sinua käsillään, ettet loukkaisi jalkaasi kiveen.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Jeesus vastasi ja sanoi hänelle: \"Sanottu on: \'Älä kiusaa Herraa, sinun Jumalaasi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Kun perkele oli kaiken kiusattavansa kiusannut, hän poistui hänen luotaan ajaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Sitten Jeesus palasi Hengen voimassa Galileaan, ja hänen maineensa levisi kaikkiin ympärillä oleviin seutuihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Hän opetti heidän synagogissaan, ja kaikki ylistivät häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Hän saapui Nasaretiin, jossa hänet oli kasvatettu, ja meni tapansa mukaan sapatinpäivänä synagogaan ja nousi lukemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'Hänelle annettiin profeetta Jesajan kirja, ja kun hän avasi kirjakäärön, hän löysi sen paikan, johon oli kirjoitettu:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, '\"Herran Henki on minun päälläni, sillä hän on voidellut minut julistamaan evankeliumia köyhille; hän on lähettänyt minut parantamaan särjettyjä sydämiä; hän on lähettänyt minut saarnaamaan vangituille vapautusta ja sokeille näkönsä saamista, päästämään ruhjotut vapauteen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'ja saarnaamaan Herran otollista vuotta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Käärittyään kirjakäärön kokoon hän antoi sen palvelijalle ja istuutui, ja kaikkien synagogassa olevien silmät olivat häneen kiinnitetyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Hän rupesi puhumaan heille: \"Tänä päivänä tämä kirjoitus on käynyt toteen teidän korvienne kuullen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Kaikki lausuivat hänestä hyvän todistuksen ja ihmettelivät niitä armon sanoja, jotka hänen suustaan lähtivät. He sanoivat: \"Eikö tämä ole Joosefin poika?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Hän sanoi heille: \"Kaiketi aiotte sanoa minulle tämän sananlaskun: \'Parantaja, paranna itsesi\'; \'tee täälläkin, isäsi kaupungissa, niitä suuria tekoja, joita olemme kuulleet tapahtuneen Kapernaumissa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Hän sanoi: \"Totisesti sanon teille: ei kukaan profeetta ole otollinen isänsä kaupungissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Sanon teille totuuden mukaisesti: monta leskeä oli Eliaan aikana Israelissa, kun taivas oli suljettuna kolme vuotta ja kuusi kuukautta ja suuri nälänhätä tuli koko maahan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'eikä Eliaa lähetetty kenenkään luo heistä, vaan ainoastaan leskinaisen luo Siidonin maan Sarpatiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'Monta spitaalista oli Israelissa profeetta Elisan aikana, eikä kukaan heistä tullut puhdistetuksi, vaan ainoastaan Naiman, syyrialainen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Tämän kuullessaan kaikki, jotka olivat synagogassa, tulivat kiukkua täyteen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'nousivat ja ajoivat hänet ulos kaupungista ja veivät hänet sen vuoren jyrkänteelle asti, jolle heidän kaupunkinsa oli rakennettu, syöstäkseen hänet alas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Mutta hän lähti pois kävellen heidän keskeltään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Hän meni alas Kapernaumiin, Galilean kaupunkiin, ja opetti heitä sapattina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'He olivat hämmästyksissään hänen opetuksestaan, sillä hänen sanansa oli sen puhetta, jolla siihen on valta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'Synagogassa oli mies, jossa oli saastaisen riivaajan henki. Tämä huusi suurella äänellä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, '\"Voi, mitä sinulla on meidän kanssamme tekemistä, Jeesus Nasaretilainen? Oletko tullut meitä tuhoamaan? Tunnen sinut, kuka olet, sinä Jumalan Pyhä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Jeesus nuhteli häntä sanoen: \"Vaikene ja lähde hänestä.\" Riivaaja viskasi hänet heidän keskelleen ja lähti hänestä häntä lainkaan vahingoittamatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'Heidät kaikki valtasi hämmästys, ja he puhuivat keskenään sanoen: \"Mitä tämä puhe on, sillä hän käskee vallalla ja voimalla saastaisia henkiä, ja ne lähtevät ulos?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'Maine hänestä levisi kaikkialle ympäristön seutuihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Hän nousi ja meni synagogasta Simonin kotiin. Simonin anopilla oli kova kuume, ja he rukoilivat Jeesusta hänen puolestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Hän kumartui hänen ylitseen ja nuhteli kuumetta, ja se lähti hänestä. Hän nousi heti ja palveli heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Mutta auringon laskiessa kaikki, joilla oli monenlaisia sairaita, veivät heidät hänen luokseen. Hän pani kätensä heidän itse kunkin päälle ja paransi heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Myös riivaajat lähtivät ulos monesta huutaen ja sanoen: \"Sinä olet Jumalan Poika!\" Mutta hän nuhteli niitä eikä sallinut niiden puhua, koska ne tiesivät hänen olevan Kristus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Päivän tultua hän lähti pois ja meni autioon paikkaan, mutta kansa etsi häntä, ja saavuttuaan hänen luokseen he pidättelivät häntä lähtemästä heidän luotaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Mutta hän sanoi heille: \"Minun tulee muillekin kaupungeille julistaa Jumalan valtakunnan evankeliumi, sillä sitä varten minut on lähetetty.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'Ja hän saarnasi Galilean synagogissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Tapahtui, että kun kansa tunkeutui hänen ympärilleen kuulemaan Jumalan sanaa ja hän seisoi Genetsaretin järven rannalla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'hän näki järven rannassa kaksi venettä, mutta kalastajat olivat lähteneet niistä ja huuhtoivat verkkojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Hän astui niistä toiseen, joka oli Simonin, ja pyysi häntä viemään sen vähän matkan päähän maasta, ja hän istui ja opetti kansaa veneestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Mutta lakattuaan puhumasta hän sanoi Simonille: \"Vie vene syvälle ja heittäkää verkkonne saadaksenne saalista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Simon vastasi ja sanoi hänelle: \"Mestari, koko yön olemme tehneet työtä emmekä ole saaneet mitään, mutta sinun käskystäsi heitän verkon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'Sen tehtyään he saivat kierretyksi suuren joukon kaloja, ja heidän verkkonsa repeili.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'He viittoivat toisessa veneessä oleville tovereilleen, että tulisivat auttamaan heitä; ja he tulivat. He täyttivät molemmat veneet, niin että ne olivat uppoamaisillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Kun Simon Pietari näki sen, hän lankesi Jeesuksen polvien eteen ja sanoi: \"Mene pois luotani, Herra, sillä olen syntinen mies.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Sillä kalansaaliin tähden, jonka he olivat saaneet, oli hämmästys vallannut hänet ja kaikki ne, jotka olivat hänen kanssaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'ja samoin myös Jaakobin ja Johanneksen, Sebedeuksen pojat, jotka olivat Simonin kalastuskumppaneita. Mutta Jeesus sanoi Simonille: \"Älä pelkää, tästä lähtien sinä saat saaliiksi ihmisiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'He veivät veneet maihin, jättivät kaikki ja seurasivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'Kun hän oli eräässä kaupungissa, katso, siellä oli mies täynnä spitaalia. Nähdessään Jeesuksen hän lankesi kasvoilleen ja rukoili häntä sanoen: \"Herra, jos tahdot, voit minut puhdistaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Hän ojensi kätensä, kosketti häntä ja sanoi: \"Tahdon, puhdistu.\" Heti spitaali lähti hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Hän kielsi häntä siitä kenellekään puhumasta ja sanoi: \"Mene, näytä itsesi papille, ja uhraa puhdistumisestasi, niin kuin Mooses on säätänyt, todistukseksi heille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Mutta sanoma hänestä levisi vielä enemmän, ja paljon kansaa kokoontui kuulemaan häntä ja sitä varten, että hän parantaisi heidät taudeistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Mutta hän vetäytyi erämaahan ja rukoili.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Tapahtui eräänä päivänä, että hänen opettaessaan siinä oli istumassa fariseuksia ja lainopettajia, joita oli tullut kaikista Galilean ja Juudean kylistä ja Jerusalemista; ja Herran voima oli parantamassa heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'Katso, miehet kantoivat vuoteella miestä, joka oli halvaantunut. He yrittivät viedä hänet sisälle ja asettaa Jeesuksen eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Kun he tungokselta eivät löytäneet, mistä voisivat viedä hänet sisään, he nousivat katolle ja laskivat hänet vuoteineen tiilikaton läpi heidän keskelleen Jeesuksen eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Nähdessään heidän uskonsa hän sanoi: \"Ihminen, sinun syntisi ovat sinulle anteeksi annetut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Kirjanoppineet ja fariseukset rupesivat ajattelemaan ja sanomaan: \"Kuka tämä on, joka puhuu jumalanpilkkaa? Kuka voi antaa syntejä anteeksi, paitsi yksin Jumala?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Mutta kun Jeesus tiesi heidän ajatuksensa, hän vastasi ja sanoi heille: \"Mitä ajattelette sydämessänne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Kumpi on helpompaa, sanoako: \'Sinun syntisi ovat sinulle anteeksi annetut\', vai sanoa: \'Nouse ja kävele\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Mutta tietääksenne, että Ihmisen Pojalla on valta antaa maan päällä syntejä anteeksi, – hän sanoi halvaantuneelle – sanon sinulle: nouse, ota vuoteesi ja mene kotiisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'Heti hän nousi heidän edessään, otti alustan, jolla oli maannut, ja lähti kotiinsa ylistäen Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Heidät kaikki valtasi hämmästys, ja he ylistivät Jumalaa; ja täynnä pelkoa he sanoivat: \"Tänään olemme nähneet ihmeellisiä [tekoja].\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Sen jälkeen hän lähti sieltä ja näki tulliasemalla istumassa publikaanin, jonka nimi oli Leevi, ja sanoi hänelle: \"Seuraa minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Tämä jätti kaiken, nousi ja seurasi häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Leevi valmisti hänelle suuret pidot kodissaan, ja siellä oli suuri joukko publikaaneja ja muita aterioimassa heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Heidän kirjanoppineensa ja fariseukset nurisivat hänen opetuslapsiaan vastaan ja sanoivat: \"Miksi te syötte ja juotte publikaanien ja syntisten kanssa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Jeesus vastasi ja sanoi heille: \"Eivät terveet tarvitse parantajaa, vaan sairaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'En ole tullut kutsumaan vanhurskaita, vaan syntisiä mielenmuutokseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'He sanoivat hänelle: \"Johanneksen opetuslapset paastoavat usein ja pitävät rukouksia, samoin fariseustenkin opetuslapset, mutta sinun opetuslapsesi syövät ja juovat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Jeesus sanoi heille: \"Ette voi saada häävieraita paastoamaan silloin, kun ylkä on heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Mutta päivät tulevat, jolloin ylkä otetaan heiltä pois, ja silloin, niinä päivinä, he paastoavat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Hän sanoi heille myös vertauksen: \"Ei kukaan pane paikkaa uudesta viitasta vanhaan viittaan. Muuten se rikkoo uuden viitan, eikä uudesta viitasta otettu paikka sovi vanhaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'Eikä kukaan laske nuorta viiniä vanhoihin nahkaleileihin. Muuten nuori viini rikkoo leilit, ja viini juoksee maahan, ja leilit turmeltuvat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'vaan nuori viini on laskettava uusiin leileihin. Silloin molemmat pysyvät ehjinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'Eikä kukaan, joka juo vanhaa viiniä, halua heti nuorta, sillä hän sanoo: \'Vanha on hyvää.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Tapahtui sapattina juhlan jälkeen, että hän kulki viljavainioiden halki, ja hänen opetuslapsensa katkoivat tähkiä, hiersivät niitä käsissään ja söivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Silloin muutamat fariseuksista sanoivat: \"Miksi teette sitä, mitä ei ole lupa tehdä sapatteina?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Mutta Jeesus vastasi heille ja sanoi: \"Ettekö ole lukeneet, mitä Daavid teki, kun hänellä ja niillä, jotka olivat hänen kanssaan, oli nälkä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'kuinka hän meni Jumalan huoneeseen, otti näkyleivät, söi ja antoi myös niille, jotka olivat hänen kanssaan, vaikka niitä ei ollut lupa syödä muiden kuin ainoastaan pappien?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'Hän sanoi heille: \"Ihmisen Poika on sapatinkin herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Tapahtui, että hän toisena sapattina meni synagogaan ja opetti. Siellä oli mies, jonka oikea käsi oli kuivettunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Kirjanoppineet ja fariseukset pitivät häntä silmällä, parantaisiko hän sapattina löytääkseen jonkin aiheen, mistä häntä syyttäisivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Mutta hän tiesi heidän ajatuksensa ja sanoi miehelle, jonka käsi oli kuivettunut: \"Nouse ja astu esiin.\" Hän nousi ja astui esiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Jeesus sanoi heille: \"Minä kysyn teiltä: kumpi on sapattina luvallista: tehdä hyvää vai tehdä pahaa, pelastaa henki vai kadottaa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'Hän katsoi ympärilleen heihin kaikkiin ja sanoi miehelle: \"Ojenna kätesi.\" Mies teki niin, ja hänen kätensä tuli ennalleen, yhtä terveeksi kuin toinenkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Mutta he vimmastuivat kovin ja puhelivat keskenään, mitä tekisivät Jeesukselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'Tapahtui niinä päivinä, että hän lähti vuorelle rukoilemaan, ja hän oli siellä koko yön rukoillen Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Päivän tultua hän kutsui luokseen opetuslapsensa ja valitsi heistä kaksitoista, joille hän antoi myös apostolin nimen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Simonin, jolle hän myös antoi nimen Pietari, Andreaan, hänen veljensä, Jaakobin ja Johanneksen, ja Filippoksen, Bartolomeoksen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Matteuksen, Tuomaan, Jaakobin, Alfeoksen pojan, Simonin, jota kutsuttiin Kiivailijaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Juudan, Jaakobin pojan, sekä Juudas Iskariotin, josta tuli kavaltaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Hän astui alas heidän kanssaan ja seisahtui tasaiselle paikalle. Siellä oli suuri joukko hänen opetuslapsiaan ja paljon kansaa koko Juudeasta ja Jerusalemista sekä Tyyron ja Siidonin rannikolta. He olivat saapuneet kuulemaan häntä ja hänen parannettavikseen taudeistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'Myös ne, jotka olivat saastaisten henkien vaivaamia, tulivat terveiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'Kaikki kansa tahtoi päästä koskettamaan häntä, koska hänestä lähti voima, joka paransi kaikki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Hän nosti silmänsä opetuslastensa puoleen ja sanoi: \"Autuaita olette te, köyhät, sillä teidän on Jumalan valtakunta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Autuaita te, joilla nyt on nälkä, sillä teidät ravitaan! Autuaita te, jotka nyt itkette, sillä te tulette nauramaan!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Autuaita olette te, kun ihmiset vihaavat teitä ja erottavat teidät yhteydestään, herjaavat teitä ja pyyhkivät pois teidän nimenne kuin jonkin pahan Ihmisen Pojan tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Iloitkaa sinä päivänä, riemusta hyppikää. Sillä, katso, teidän palkkanne on suuri taivaassa. Näin heidän isänsä näet tekivät profeetoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Mutta voi teitä, te rikkaat, sillä te olette jo saaneet lohdutuksenne!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Voi teitä, jotka nyt olette kylläiset, sillä teillä on oleva nälkä! Voi teitä, jotka nyt nauratte, sillä te saatte murehtia ja itkeä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Voi teitä, kun kaikki ihmiset puhuvat teistä hyvää! Sillä niin tekivät heidän isänsä väärille profeetoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Mutta teille, jotka kuulette, sanon: rakastakaa vihollisianne, tehkää hyvää niille, jotka teitä vihaavat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'siunatkaa niitä, jotka teitä kiroavat, rukoilkaa niiden edestä, jotka teitä parjaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Jos joku lyö sinua poskelle, tarjoa hänelle toinenkin, ja jos joku ottaa sinulta viitan, älä kiellä häneltä paitaakaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Anna jokaiselle, joka sinulta anoo, äläkä vaadi takaisin siltä, joka ottaa omaasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Niin kuin tahdotte ihmisten teille tekevän, tehkää tekin heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Jos te rakastatte niitä, jotka teitä rakastavat, mitä kiitosta teille siitä tulee? Rakastavathan syntisetkin niitä, jotka heitä rakastavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'Jos teette hyvää niille, jotka tekevät teille hyvää, mitä kiitosta teille siitä tulee? Niinhän syntisetkin tekevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'Jos lainaatte niille, joilta toivotte saavanne takaisin, mitä kiitosta teille siitä tulee? Syntisetkin lainaavat syntisille saadakseen saman verran takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Vaan rakastakaa vihollisianne ja tehkää hyvää ja lainatkaa toivomatta saavanne takaisin; niin teidän palkkanne on oleva suuri, ja te tulette Korkeimman lapsiksi, sillä hän on hyvä kiittämättömille ja pahoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Olkaa armahtavaisia, samoin kuin teidän Isänne on armahtavainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Älkääkä tuomitko, niin ei teitäkään tuomita; älkää kadotustuomiota lausuko, niin ei teillekään kadotustuomiota lausuta. Antakaa anteeksi, niin teillekin anteeksi annetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Antakaa, niin teille annetaan. Hyvä mitta, sullottu, pudistettu ja kukkurainen, annetaan teidän helmaanne; sillä millä mitalla mittaatte, sillä mitataan teille takaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Hän sanoi heille myös vertauksen: \"Voiko sokea taluttaa sokeaa? Eivätkö molemmat kaadu kuoppaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Opetuslapsi ei ole opettajaansa parempi. Täysin oppineena jokainen on oleva kuin hänen opettajansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Kuinka näet rikan, joka on veljesi silmässä, mutta et huomaa parrua omassa silmässäsi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Kuinka saatat sanoa veljellesi: \'Veljeni, salli, niin otan pois rikan, joka on silmässäsi\', sinä, joka et näe parrua omassa silmässäsi? Sinä ulkokullattu, poista ensin parru omasta silmästäsi, sitten näet ottaa pois rikan, joka on veljesi silmässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Sillä ei ole hyvää puuta, joka tekee huonon hedelmän, eikä huonoa puuta, joka tekee hyvän hedelmän,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'sillä jokainen puu tunnetaan hedelmästään. Eihän viikunoita koota piikkipensaista, eikä viinirypäleitä korjata orjantappuroista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'Hyvä ihminen tuo sydämensä hyvän varastosta esiin hyvää, ja paha tuo pahan varastostaan esiin pahaa, sillä sydämen kyllyydestä suu puhuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Miksi te sanotte minulle: \'Herra, Herra!\' ettekä tee, mitä sanon?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Jokainen, joka tulee minun luokseni ja kuulee sanani ja tekee niiden mukaan – osoitan teille, kenen kaltainen hän on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Hän on miehen kaltainen, joka taloa rakentaessaan kaivoi syvään ja laski perustuksen kalliolle. Kun tulva tuli, virta syöksyi taloa vasten, mutta ei voinut sitä horjuttaa, sillä se oli perustettu kalliolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Se taas, joka kuulee eikä tee, on miehen kaltainen, joka rakensi talonsa maan pinnalle ilman perustusta. Virta syöksyi sitä vasten, ja se sortui heti, ja sen talon luhistuminen oli suuri.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Kun hän oli puhunut kansan kuullen kaikki nämä puheensa, hän meni Kapernaumiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Eräällä sadanpäälliköllä oli palvelija, joka sairasti ja oli kuolemaisillaan ja jota hän piti suuressa arvossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Kuultuaan Jeesuksesta hän lähetti juutalaisten vanhimpia hänen luokseen pyytämään, että hän tulisi parantamaan hänen palvelijansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Kun nämä saapuivat Jeesuksen luo, he pyysivät häntä hartaasti ja sanoivat: \"Hän ansaitsee, että teet hänelle tämän,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'sillä hän rakastaa kansaamme ja on rakentanut meille synagogan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Jeesus lähti heidän kanssaan. Mutta kun hän ei enää ollut kaukana talosta, sadanpäällikkö lähetti ystäviään sanomaan hänelle: \"Herra, älä vaivaa itseäsi, sillä en ole sen arvoinen, että tulisit kattoni alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'Sen tähden en katsonutkaan itseäni arvolliseksi tulemaan luoksesi, vaan sano sana, niin palvelijani paranee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Sillä minut on asetettu esivallan alle, ja minulla on alaisina sotilaita. Kun sanon tälle: \'Mene\', hän menee, ja toiselle: \'Tule\', ja hän tulee, ja palvelijalleni: \'Tee tämä\', ja hän tekee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Tämän kuultuaan Jeesus ihmetteli häntä, kääntyi häntä seuranneen kansan puoleen ja sanoi: \"Sanon teille: en ole Israelissakaan löytänyt näin suurta uskoa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Kun lähetetyt palasivat taloon, he tapasivat palvelijan terveenä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Sen jälkeen tapahtui, että hän vaelsi Nain-nimiseen kaupunkiin, ja hänen kanssaan vaelsi monia hänen opetuslapsistaan sekä suuri kansanjoukko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Kun hän nyt lähestyi kaupungin porttia, katso, kannettiin ulos kuollutta, äitinsä ainoaa poikaa. Äiti oli leski, ja hänen kanssaan oli paljon ihmisiä kaupungista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Hänet nähdessään Herra armahti häntä ja sanoi hänelle: \"Älä itke.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Sitten hän meni ja kosketti paareja; niin kantajat pysähtyivät. Ja hän sanoi: \"Nuorukainen, sanon sinulle: nouse.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Kuollut nousi istumaan ja alkoi puhua. Ja Jeesus antoi hänet hänen äidilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Heidät kaikki valtasi pelko, ja he ylistivät Jumalaa sanoen: \"Suuri Profeetta on noussut keskellemme\", ja: \"Jumala on katsonut kansansa puoleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Tämä puhe levisi hänestä koko Juudeaan ja koko ympäristöön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'Hänen opetuslapsensa ilmoittivat tämän kaiken Johannekselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'Silloin Johannes kutsui luokseen opetuslapsistaan kaksi ja lähetti heidät Herran luo kysymään: \"Oletko sinä se tuleva, vai odotammeko toista?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Miehet saapuivat hänen luokseen ja sanoivat: \"Johannes Kastaja on lähettänyt meidät sinun luoksesi ja kysyy: \'Oletko sinä se tuleva, vai odotammeko toista?\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'Sillä hetkellä hän juuri paransi useita taudeista, vaivoista ja pahoista hengistä, ja monelle sokealle hän antoi näön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Hän vastasi ja sanoi heille: \"Menkää ja ilmoittakaa Johannekselle, mitä olette nähneet ja kuulleet: sokeat saavat näkönsä, rammat kävelevät, spitaaliset puhdistuvat, kuurot kuulevat, kuolleita herätetään, köyhille julistetaan evankeliumia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'Autuas on se, joka ei loukkaannu minuun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Kun Johanneksen lähettiläät olivat menneet, hän rupesi puhumaan kansalle Johanneksesta: \"Mitä lähditte erämaahan katselemaan? Ruokoako, jota tuuli huojuttaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Vai mitä lähditte katsomaan? Ihmistäkö, pehmeisiin vaatteisiin puettua? Katso, ne jotka ovat loistavissa vaatteissa ja elävät ylellisesti, ovat kuningasten parissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Vai mitä lähditte katsomaan? Profeettaako? Totisesti, sanon teille: hän on enemmän kuin profeetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'Tämä on se, josta on kirjoitettu: \'Katso, minä lähetän enkelini edelläsi, ja hän valmistaa tiesi sinun eteesi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Sanon teille: ei ole vaimoista syntyneiden joukossa ketään suurempaa kuin Johannes, mutta vähäisin Jumalan valtakunnassa on suurempi kuin hän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'Kaikki kansa, joka häntä kuuli, publikaanitkin, tunnustivat Jumalan vanhurskaaksi ottamalla vastaan kasteen Johannekselta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Mutta fariseukset ja lainoppineet hylkäsivät Jumalan tarkoituksen itseään kohtaan eivätkä ottaneet häneltä kastetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'Mihin siis vertaan tämän sukukunnan ihmiset, ja kenen kaltaisia he ovat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'He ovat lasten kaltaisia, jotka istuvat torilla ja huutavat toisilleen ja sanovat: \'Soitimme teille huilua, ettekä karkeloineet; veisasimme itkuvirsiä, ettekä itkeneet.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Sillä Johannes Kastaja on tullut. Hän ei syö leipää eikä juo viiniä, ja sanotte: \'Hänessä on riivaaja.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Ihmisen Poika on tullut, syö ja juo, ja sanotte: \'Katso ylensyöjää ja viininjuojaa, publikaanien ja syntisten ystävää!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Viisauden julistavat vanhurskaaksi kaikki Viisauden lapset.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Niin eräs fariseuksista pyysi häntä syömään kanssaan. Hän meni fariseuksen taloon ja asettui aterialle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'Katso, siinä kaupungissa oli nainen, joka oli syntinen; ja kun hän sai tietää, että Jeesus oli aterialla fariseuksen talossa, hän toi mukanaan alabasteripullon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'asettui hänen taakseen hänen jalkojensa kohdalle, itki ja rupesi kastelemaan hänen jalkojaan kyynelillään, kuivasi ne päänsä hiuksilla, suuteli hänen jalkojaan ja voiteli ne hajuvoiteella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Mutta kun fariseus, joka oli hänet kutsunut, näki sen, ajatteli hän mielessään: \"Jos tämä olisi profeetta, hän tietäisi, mikä ja millainen tuo nainen on, joka häneen koskee: että hän on syntinen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Jeesus vastasi ja sanoi hänelle: \"Simon, minulla on jotakin sanottavaa sinulle.\" Hän lausui: \"Opettaja, sano.\" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, '\"Lainanantajalla oli kaksi velallista; toinen oli velkaa viisisataa denaaria, toinen viisikymmentä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'Kun heillä ei ollut, millä maksaa, hän antoi molemmille velan anteeksi. Sano, kumpi heistä siis rakastaa häntä enemmän?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Simon vastasi ja sanoi: \"Minun mielestäni se, jolle hän antoi enemmän anteeksi.\" Hän sanoi hänelle: \"Oikein ratkaisit.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Naiseen kääntyen hän sanoi Simonille: \"Näetkö tämän naisen? Tulin sinun taloosi, et antanut vettä jaloilleni, mutta tämä kasteli kyynelillään jalkani ja kuivasi ne hiuksillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Sinä et antanut minulle suudelmaa, mutta tämä ei ole lakannut suutelemasta jalkojani siitä asti, kun tulin sisään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Sinä et voidellut päätäni öljyllä, mutta tämä voiteli hajuvoiteella jalkani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Sen tähden sanon sinulle: tämän monet synnit ovat anteeksi annetut: hänhän näet rakasti paljon, mutta jolle vähän anteeksi annetaan, se rakastaa vähän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Sitten hän sanoi naiselle: \"Sinun syntisi ovat anteeksi annetut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Ateriakumppanit rupesivat ajattelemaan mielessään: \"Kuka tämä on, joka synnitkin antaa anteeksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Mutta hän sanoi naiselle: \"Sinun uskosi on sinut pelastanut, mene rauhaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Tapahtui sen jälkeen, että hän vaelsi kaupungista kaupunkiin ja kylästä kylään saarnaten ja julistaen Jumalan valtakunnan evankeliumia; ja ne kaksitoista olivat hänen kanssaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'niin myös muutamia naisia, jotka olivat parannetut pahoista hengistä ja taudeista: Maria, jota sanottiin Magdaleenaksi ja josta seitsemän riivaajaa oli lähtenyt ulos,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'Johanna, Herodeksen taloudenhoitajan Kuusaan vaimo, ja Susanna sekä useita muita naisia, jotka palvelivat heitä varoillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Kun paljon kansaa kokoontui ja ihmisiä kulki joka kaupungista hänen luokseen, hän puhui käyttäen vertausta:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, '\"Kylväjä lähti kylvämään siementään. Hänen kylväessään putosi osa tien viereen ja tallautui, ja taivaan linnut söivät sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Osa putosi kalliolle, ja noustuaan oraalle se kuivettui, koska sillä ei ollut kosteutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Osa taas putosi orjantappuroiden sekaan, ja orjantappurat kasvoivat mukana ja tukahduttivat sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Mutta osa putosi hyvään maahan, kasvoi ja teki satakertaisen hedelmän.\" Tämän sanottuaan hän lausui suurella äänellä: \"Jolla on korvat kuulla, se kuulkoon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Hänen opetuslapsensa kysyivät häneltä, mitä tämä vertaus merkitsee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Hän sanoi: \"Teidän on annettu tuntea Jumalan valtakunnan salaisuudet, mutta muille ne esitetään vertauksilla, että he, vaikka näkevät, eivät näkisi, ja vaikka kuulevat, eivät ymmärtäisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Vertaus on tämä: siemen on Jumalan sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Se, mikä tien varteen putosi, on ne, jotka kuulevat, mutta sitten perkele tulee ja ottaa sanan pois heidän sydämestään, etteivät uskoisi ja pelastuisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Se osa, mikä kalliolle putosi, on ne, jotka kuullessaan sanan ottavat sen ilolla vastaan, mutta koska heillä ei ole juurta, he uskovat vain ajaksi ja luopuvat kiusauksen hetkellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Orjantappuroihin pudonnut osa on ne, jotka kuulevat, mutta vaeltaessaan tukehtuvat tämän elämän huoliin, rikkauteen ja nautintoihin, eivätkä tuota kypsää hedelmää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Mutta hyvään maahan pudonnut osa on ne, jotka sanan kuultuaan säilyttävät sen vilpittömässä ja hyvässä sydämessä ja tuottavat hedelmän kärsivällisyydessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Ei kukaan, joka sytyttää lampun, peitä sitä astialla tai pane vuoteen alle, vaan panee sen lampunjalkaan, että sisälle tulijat näkisivät valon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Sillä ei ole mitään salattua, mikä ei tule ilmi, eikä kätkettyä, mikä ei tule tunnetuksi ja joudu päivän valoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Katsokaa siis, kuinka kuulette. Sillä sille, jolla on, annetaan, mutta siltä, jolla ei ole, otetaan pois sekin, minkä hän luulee olevan itsellään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Hänen äitinsä ja veljensä tulivat häntä tapaamaan, mutta eivät päässeet väentungokselta hänen luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'Hänelle ilmoitettiin sanoen: \"Äitisi ja veljesi seisovat ulkona ja tahtovat nähdä sinua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Mutta hän vastasi ja sanoi heille: \"Äitini ja veljeni ovat nämä, jotka kuulevat Jumalan sanan ja sitä noudattavat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Tapahtui eräänä päivänä, että hän astui opetuslapsineen veneeseen ja sanoi heille: \"Menkäämme järven tuolle puolen!\" He lähtivät vesille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Heidän purjehtiessaan hän nukahti. Mutta alas järvelle syöksyi myrskytuuli, ja vene tuli vettä täyteen, ja he olivat vaarassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'He menivät ja herättivät hänet sanoen: \"Mestari, mestari, hukumme!\" Herättyään hän nuhteli tuulta ja veden aaltoja; ja ne asettuivat, ja tuli tyyntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Hän sanoi heille: \"Missä on teidän uskonne?\" Mutta pelko oli vallannut heidät, ja he ihmettelivät ja sanoivat toisilleen: \"Kuka tämä onkaan, kun hän käskee sekä tuulia että vettä, ja ne tottelevat häntä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'He purjehtivat gadaralaisten alueelle, joka on vastapäätä Galileaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Kun hän oli noussut maihin, häntä vastaan tuli kaupungista eräs mies, jossa oli riivaajia. Hän ei ollut pitkään aikaan pukenut viittaa ylleen eikä asunut huoneessa, vaan haudoissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Kun hän näki Jeesuksen, hän huusi ja lankesi maahan hänen eteensä ja sanoi kovalla äänellä: \"Mitä sinulla on minun kanssani tekemistä, Jeesus, Jumalan, Korkeimman, Poika? Rukoilen sinua: älä vaivaa minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Sillä hän oli käskemäisillään saastaista henkeä lähtemään ulos miehestä. Sillä pitkät ajat se oli temponut häntä mukaansa. Hänet oli sidottu kahleisiin ja jalkanuoriin, ja häntä oli vartioitu, mutta hän oli katkaissut siteet ja kulkeutunut riivaajan ajamana erämaihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Jeesus kysyi siltä sanoen: \"Mikä on nimesi?\" Hän vastasi: \"Legioona\"; sillä monta riivaajaa oli mennyt häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'Ne pyysivät häntä, ettei hän käskisi niiden mennä syvyyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Siellä oli vuorella suuri sikalauma laitumella. Ne pyysivät häntä, että hän sallisi heidän mennä sikoihin. Ja hän salli sen niille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Niin riivaajat lähtivät ulos miehestä ja menivät sikoihin. Silloin lauma syöksyi jyrkännettä alas järveen ja hukkui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Mutta nähtyään, mitä oli tapahtunut, paimenet pakenivat ja kertoivat siitä kaupungissa ja maataloissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Kansa lähti katsomaan, mitä oli tapahtunut, ja he tulivat Jeesuksen luo ja tapasivat miehen, josta riivaajat olivat lähteneet, istumassa Jeesuksen jalkojen juuressa puettuna ja täydessä ymmärryksessä, ja he pelästyivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Mutta silminnäkijät kertoivat heille, kuinka riivattu oli tullut terveeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'Koko gadaralaisten seudun kansa pyysi häntä poistumaan heidän luotaan, sillä suuri pelko oli vallannut heidät. Hän astui veneeseen ja palasi takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Mies, josta riivaajat olivat lähteneet, pyysi häneltä saada olla hänen kanssaan. Mutta Jeesus lähetti hänet luotaan sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, '\"Palaa kotiisi ja kerro, kuinka suuria Jumala on sinulle tehnyt.\" Hän meni ja julisti kaikkialla kaupungissa, kuinka suuria Jeesus oli hänelle tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Kun Jeesus palasi, kansa oli häntä vastassa; sillä kaikki odottivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'Katso, silloin tuli mies, nimeltä Jairos, joka oli synagogan esimies. Hän lankesi Jeesuksen jalkojen juureen ja pyysi häntä tulemaan kotiinsa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'sillä hänellä oli tytär, ainoa lapsi, noin kaksitoistavuotias, ja tämä oli kuolemaisillaan. Mutta hänen sinne mennessään väentungos ahdisti häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'Siellä oli nainen, joka oli sairastanut kaksitoista vuotta verenjuoksua ja kuluttanut lääkäreissä kaiken omaisuutensa, eikä kukaan ollut voinut häntä parantaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'Tämä lähestyi takaapäin ja kosketti hänen viittansa tupsua, ja heti hänen verenjuoksunsa asettui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Jeesus sanoi: \"Kuka minuun koski?\" Mutta kun kaikki kielsivät, sanoi Pietari ja ne, jotka olivat hänen kanssaan: \"Mestari, väentungos ahdistaa ja pusertaa sinua ja kysyt, kuka minuun koski.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Mutta Jeesus sanoi: \"Joku koski minuun; sillä minä tunsin, että voimaa lähti minusta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Kun nainen näki, ettei hän pysynyt salassa, hän tuli vavisten, lankesi hänen eteensä ja ilmoitti koko kansan kuullen syyn, miksi hän oli koskenut häneen ja kuinka hän oli heti tullut terveeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'Hän sanoi hänelle: \"Tyttäreni, ole rohkealla mielellä, uskosi on sinut pelastanut; mene rauhaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Hänen vielä puhuessaan tuli joku synagogan esimiehen kotoa ja sanoi tälle: \"Tyttäresi on kuollut; älä vaivaa opettajaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Mutta sen kuultuaan Jeesus vastasi ja sanoi hänelle: \"Älä pelkää; usko ainoastaan, ja hän paranee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Kun hän tuli taloon, hän ei sallinut kenenkään muun tulla sisään kanssaan kuin Pietarin, Johanneksen ja Jaakobin sekä lapsen isän ja äidin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Kaikki itkivät ja vaikeroivat tyttöä. Mutta Jeesus sanoi: \"Älkää itkekö, hän ei ole kuollut, vaan nukkuu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'He nauroivat hänelle tietäen tytön kuolleeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Mutta hän ajoi ulos kaikki, tarttui hänen käteensä ja sanoi kovalla äänellä: \"Lapsi, nouse!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'Hänen henkensä palasi, ja hän nousi heti ylös, ja Jeesus käski antaa hänelle syötävää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Hänen vanhempansa hämmästyivät, mutta Jeesus kielsi heitä sanomasta kenellekään, mitä oli tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Hän kutsui koolle ne kaksitoista ja antoi heille voiman ja vallan kaikkia riivaajia vastaan ja voiman parantaa tauteja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'Hän lähetti heidät julistamaan Jumalan valtakuntaa ja parantamaan sairaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'Hän sanoi heille: \"Älkää ottako matkalle mitään, ei sauvaa, ei laukkua, ei leipää, ei rahaa, älköön kenelläkään olko myöskään kahta paitaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'Kun tulette johonkin taloon, jääkää siihen ja lähtekää siitä matkalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Mutta siitä kaupungista, missä eivät ota teitä vastaan, lähtekää pois, ja pudistakaa tomu jaloistanne, todistukseksi heitä vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'He lähtivät ja kulkivat kylästä kylään julistaen evankeliumia ja parantaen sairaita kaikkialla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Mutta neljännesruhtinas Herodes sai kuulla kaikesta, mitä oli tapahtunut, eikä tiennyt, mitä ajatella; sillä muutamat sanoivat: \"Johannes on noussut kuolleista\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'mutta toiset: \"Elia on ilmestynyt\", toiset taas: \"Joku vanhoista profeetoista on noussut ylös.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Herodes sanoi: \"Johanneksen minä olen mestauttanut, mutta kuka tämä on, josta kuulen tuollaista?\" Ja hän yritti saada nähdä hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Apostolit palasivat ja kertoivat Jeesukselle kaiken, mitä olivat tehneet. Hän otti heidät mukaansa ja vetäytyi yksinäisyyteen erämaahan lähelle Beetsaida nimistä kaupunkia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Mutta kun kansa sai sen tietää, he seurasivat häntä. Hän otti heidät vastaan ja puhui heille Jumalan valtakunnasta ja teki terveiksi ne, jotka tarvitsivat parantamista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Päivä alkoi laskea. Ne kaksitoista tulivat ja sanoivat hänelle: \"Laske kansa luotasi, että menisivät ympärillä oleviin kyliin ja maataloihin majoittumaan ja saadakseen ruokaa, sillä olemme täällä autiossa paikassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Mutta hän sanoi heille: \"Antakaa te heille syötävää.\" He sanoivat: \"Meillä ei ole enempää kuin viisi leipää ja kaksi kalaa, mikäli emme lähde ostamaan ruokaa kaikelle tälle kansalle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Sillä heitä oli noin viisituhatta miestä. Hän sanoi opetuslapsilleen: \"Asettakaa heidät ruokakunnittain, noin viisikymmentä kuhunkin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'He tekivät niin ja asettivat kaikki aterioimaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Hän otti ne viisi leipää ja kaksi kalaa, katsoi ylös taivaaseen, siunasi ne, mursi ja antoi opetuslapsilleen pantaviksi kansan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'Kaikki söivät ja tulivat ravituiksi. Heiltä jääneet tähteet kerättiin, kaksitoista korillista palasia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'Tapahtui, kun hän oli yksinäisessä paikassa rukoilemassa ja hänen opetuslapsensa olivat hänen kanssaan, että hän kysyi heiltä ja sanoi: \"Kenen kansa sanoo minun olevan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'He vastasivat sanoen: \"Johannes Kastajan, mutta toiset Elian, toiset taas sanovat, että joku vanhoista profeetoista on noussut ylös.\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'Hän sanoi heille: \"Kenenkä te sanotte minun olevan?\" Pietari vastasi ja sanoi: \"Sinä olet Jumalan Kristus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Vakavasti varoittaen hän kielsi heitä tätä kenellekään sanomasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'Hän sanoi: \"Ihmisen Pojan pitää kärsiä paljon ja joutua vanhinten, ylipappien ja kirjanoppineiden hylkäämäksi ja tulla tapetuksi ja kolmantena päivänä hän on nouseva ylös.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Hän sanoi kaikille: \"Jos joku tahtoo minun perässäni kulkea, hän kieltäköön itsensä ja ottakoon joka päivä ristinsä ja seuratkoon minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Sillä se, joka tahtoo pelastaa elämänsä, kadottaa sen, mutta se, joka kadottaa elämänsä minun tähteni, pelastaa sen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Sillä mitä ihmistä hyödyttää, vaikka hän voittaisi omakseen koko maailman, mutta saattaisi itsensä kadotukseen tai turmioon?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Sillä joka häpeää minua ja minun sanojani, sitä Ihmisen Poika on häpeävä, kun hän tulee omassa ja Isänsä sekä pyhien enkelien kirkkaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Totisesti sanon teille: tässä seisovien joukossa on muutamia, jotka eivät maista kuolemaa, ennen kuin näkevät Jumalan valtakunnan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Noin kahdeksan päivää sen jälkeen, kun hän oli tämän puhunut, tapahtui, että hän otti mukaansa Pietarin, Johanneksen ja Jaakobin ja nousi vuorelle rukoilemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Tapahtui hänen rukoillessaan, että hänen kasvojensa näkö muuttui, ja hänen vaatteensa tulivat valkoisiksi ja sädehtivän kirkkaiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'Katso, hänen kanssaan puhui kaksi miestä, ja he olivat Mooses ja Elia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'He näkyivät kirkkaudessa ja puhuivat hänen poismenostaan, jonka hän oli saattava täytäntöön Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Mutta Pietari ja ne, jotka olivat hänen kanssaan, olivat unen raskauttamia, mutta herättyään he näkivät hänen kirkkautensa ja ne kaksi miestä, jotka seisoivat hänen luonaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Tapahtui, kun nämä olivat eroamassa hänestä, että Pietari sanoi Jeesukselle: \"Mestari, meidän on tässä hyvä olla; tehkäämme kolme majaa, sinulle yksi ja Moosekselle yksi ja Elialle yksi.\" Mutta hän ei tiennyt, mitä sanoi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Hänen tätä sanoessaan tuli pilvi ja peitti heidät varjoonsa, ja he pelästyivät joutuessaan pilveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'Pilvestä kuului ääni, joka sanoi: \"Tämä on minun rakas Poikani, kuulkaa häntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Äänen kuuluessa he huomasivat Jeesuksen olevan yksin. He olivat siitä vaiti eivätkä niinä päivinä ilmoittaneet kenellekään mitään siitä, mitä olivat nähneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Tapahtui, kun he seuraavana päivänä menivät alas vuorelta, että paljon kansaa tuli häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'Katso, eräs mies kansanjoukosta huusi sanoen: \"Opettaja, minä rukoilen sinua, katso poikani puoleen, sillä hän on ainoani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'Katso, hänen kimppuunsa käy henki, ja heti hän parkaisee, ja se riepottelee häntä, niin että vaahto valuu suusta, ja vain vaivoin se poistuu hänestä runnellen häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'Pyysin opetuslapsiasi ajamaan sen ulos, mutta he eivät voineet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Jeesus vastasi ja sanoi: \"Voi, sinä epäuskoinen ja nurja sukupolvi; kuinka kauan minun täytyy olla teidän luonanne ja kärsiä teitä? Tuo poikasi tänne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Vielä pojan tullessakin riivaaja retuutti häntä ja kiskoi häntä kovasti. Mutta Jeesus nuhteli saastaista henkeä, paransi pojan ja antoi hänet takaisin hänen isälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Kaikki hämmästyivät Jumalan valtasuuruutta. Kun kaikki ihmettelivät kaikkea sitä, mitä Jeesus teki, hän sanoi opetuslapsilleen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, '\"Ottakaa te korviinne nämä sanat, sillä Ihmisen Poika annetaan ihmisten käsiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Mutta he eivät käsittäneet tätä puhetta, ja se oli heiltä peitetty, niin etteivät he sitä ymmärtäneet, ja he pelkäsivät kysyä häneltä tämän puheen johdosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Heidän mieleensä tuli ajatus, kuka heistä olisi suurin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Mutta kun Jeesus tiesi heidän sydämensä ajatuksen, hän otti lapsen ja asetti hänet viereensä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'ja sanoi heille: \"Joka ottaa luokseen tämän lapsen minun nimeeni, se ottaa luokseen minut; ja joka ottaa minut luokseen, ottaa luokseen hänet, joka on minut lähettänyt. Sillä joka teistä kaikista on pienin, se on suuri.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Johannes vastasi ja sanoi: \"Mestari, näimme erään miehen sinun nimessäsi ajavan ulos riivaajia ja kielsimme häntä, koska hän ei seuraa meidän mukanamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Mutta Jeesus sanoi hänelle: \"Älkää kieltäkö; sillä se, joka ei ole meitä vastaan, on meidän puolellamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Tapahtui, kun hänen ylösottamisensa aika oli täyttymässä, että hän käänsi kasvonsa Jerusalemia kohti vaeltaakseen sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'Hän lähetti edellään sanansaattajia. He lähtivät matkaan ja menivät erääseen samarialaisten kylään tekemään valmisteluja häntä varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Mutta siellä ei otettu häntä vastaan, koska hän oli vaeltamassa kohti Jerusalemia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Kun hänen opetuslapsensa Jaakob ja Johannes sen näkivät, he sanoivat: \"Herra, tahdotko, niin sanomme, että tuli taivaasta tulkoon alas ja hävittäköön heidät, kuten Eliakin teki?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Mutta hän kääntyi, nuhteli heitä ja sanoi: \"Ettekö tiedä, millaisen Hengen omia te olette?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Sillä Ihmisen Poika ei ole tullut kadottamaan ihmissieluja, vaan pelastamaan.\" Ja he vaelsivat toiseen kylään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Heidän tietä vaeltaessaan eräs mies sanoi hänelle: \"Seuraan sinua, mihin ikinä menet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Jeesus sanoi hänelle: \"Ketuilla on luolat ja taivaan linnuilla pesät, mutta Ihmisen Pojalla ei ole, mihin hän päänsä kallistaisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Toiselle hän sanoi: \"Seuraa minua.\" Mutta tämä sanoi: \"Herra, salli minun ensin haudata isäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Mutta Jeesus sanoi hänelle: \"Anna kuolleitten haudata kuolleensa, mutta mene sinä ja julista Jumalan valtakuntaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Vielä eräs toinen sanoi: \"Minä tahdon seurata sinua, Herra, salli kuitenkin minun ensin käydä jättämässä jäähyväiset kotiväelleni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Mutta Jeesus sanoi hänelle: \"Ei kukaan, joka laskee kätensä auraan ja katsoo taakseen, ole sovelias Jumalan valtakuntaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Sen jälkeen Herra valitsi seitsemänkymmentä muuta ja lähetti heidät kaksittain edellään jokaiseen kaupunkiin ja paikkaan, jonne hän aikoi mennä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Hän sanoi heille: \"Korjattavaa satoa on paljon, mutta työmiehiä vähän. Rukoilkaa siis elon Herraa, että hän lähettäisi työmiehiä elonkorjuuseensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Menkää; katso, minä lähetän teidät niin kuin lampaat susien keskelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Älkää ottako mukaanne kukkaroa, älkää laukkua, älkää sandaaleja, älkääkä tervehtikö ketään tiellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'Kun tulette johonkin taloon, sanokaa ensiksi: \'Rauha tälle talolle!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Jos siellä on rauhan lapsi, rauhanne on lepäävä hänen päällään, mutta jos ei ole, se palaa teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'Pysykää talossa, syökää ja juokaa, mitä heillä on, sillä työmies on palkkansa ansainnut. Älkää siirtykö talosta taloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Mihin kaupunkiin tulettekin, jossa teidät otetaan vastaan, syökää, mitä eteenne pannaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'parantakaa sairaat siellä ja sanokaa heille: \'Jumalan valtakunta on tullut teitä lähelle.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Mutta kun tulette kaupunkiin, jossa teitä ei oteta vastaan, menkää sen kaduille ja sanokaa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, '\'Tomunkin, joka teidän kaupungistanne on tarttunut, pudistamme teille takaisin. Mutta se tietäkää, että Jumalan valtakunta on tullut lähelle.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Sanon teille: Sodoman on oleva sinä päivänä helpompi kuin sen kaupungin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Voi sinua, Korasin! Voi sinua, Beetsaida! Sillä jos ne voimalliset teot, jotka teissä ovat tapahtuneet, olisivat tapahtuneet Tyyrossa ja Siidonissa, nämä jo aikaa sitten olisivat säkissä ja tuhkassa istuen muuttaneet mielensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Mutta Tyyron ja Siidonin on oleva tuomiolla helpompi kuin teidän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'Sinä, Kapernaum, korotetaankohan sinut hamaan taivaaseen? Hamaan helvettiin sinun on astuttava alas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Se, joka kuulee teitä, kuulee minua, ja se, joka hylkää teidät, hylkää minut. Mutta se, joka minut hylkää, hylkää hänet, joka on minut lähettänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Niin ne seitsemänkymmentä palasivat iloiten ja sanoivat: \"Herra, riivaajatkin ovat meille alamaiset sinun nimessäsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Hän sanoi heille: \"Minä näin saatanan lankeavan taivaasta kuin salaman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Katso, olen antanut teille vallan tallata käärmeitä, skorpioneja ja kaikkea vihollisen voimaa, eikä mikään ole teitä vahingoittava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Älkää kuitenkaan siitä iloitko, että henget ovat teille alamaiset, vaan iloitkaa siitä, että teidän nimenne ovat kirjoitettuina taivaissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'Sillä hetkellä hän riemuitsi Pyhässä Hengessä ja sanoi: \"Minä ylistän sinua, Isä, taivaan ja maan Herra, että olet salannut nämä viisailta ja älykkäiltä ja ilmoittanut ne lapsenmielisille. Niin, Isä, sillä näin on sinulle hyväksi näkynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Kaikki minun Isäni on uskonut minun haltuuni, eikä kukaan muu tunne, kuka Poika on, kuin Isä; eikä kukaan muu tunne, kuka Isä on, kuin Poika ja se, kenelle Poika tahtoo hänet ilmoittaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'Hän kääntyi erikseen opetuslapsiinsa ja sanoi: \"Autuaat ovat ne silmät, jotka näkevät, mitä te näette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Sillä sanon teille: monet profeetat ja kuninkaat ovat tahtoneet nähdä, mitä te näette, eivätkä ole nähneet, ja kuulla, mitä kuulette, eivätkä ole kuulleet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'Katso, eräs lainoppinut nousi ja kysyi koetellen häntä: \"Opettaja, mitä minun pitää tehdä, että minä iankaikkisen elämän perisin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Hän sanoi hänelle: \"Mitä laissa on kirjoitettuna? Miten luet?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'Hän vastasi ja sanoi: \"Rakasta Herraa, Jumalaasi, kaikesta sydämestäsi, kaikesta sielustasi, kaikesta voimastasi ja kaikesta mielestäsi, ja lähimmäistäsi niin kuin itseäsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Hän sanoi hänelle: \"Oikein vastasit. Tee se, niin olet elävä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Mutta hän tahtoi näyttää olevansa vanhurskas ja sanoi Jeesukselle: \"Kuka sitten on lähimmäiseni?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Jeesus vastasi ja sanoi: \"Eräs mies vaelsi Jerusalemista alas Jerikoon ja joutui ryövärien käsiin, jotka riisuivat hänet alasti, löivät haavoille ja menivät pois jättäen hänet puolikuolleeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Eräs pappi sattui kulkemaan sitä tietä, näki hänet ja meni ohi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Samoin myös leeviläinen. Kun hän tuli paikalle ja näki hänet, hän meni ohi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Mutta kun eräs samarialainen, joka matkusti sitä tietä, tuli hänen kohdalleen ja näki hänet, hän armahti häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'Hän meni hänen luokseen, sitoi hänen haavansa, vuodatti niihin öljyä ja viiniä, pani hänet juhtansa selkään ja vei hänet majataloon ja hoivasi häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Seuraavana aamuna hän otti esiin kaksi denaaria, antoi majatalon isännälle ja sanoi: \'Hoida häntä, ja mitä sinulta muuta kuluu, sen palatessani sinulle maksan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Kuka näistä kolmesta mielestäsi osoitti olevansa sen lähimmäinen, joka oli joutunut ryövärien käsiin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Hän sanoi: \"Se, joka osoitti hänelle laupeutta.\" Jeesus sanoi hänelle: \"Mene ja tee sinä samoin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Heidän vaeltaessaan hän meni erääseen kylään. Eräs nainen, nimeltä Martta, otti hänet kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Hänellä oli sisar, nimeltään Maria, joka asettui istumaan Jeesuksen jalkojen juureen ja kuunteli hänen sanaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Mutta Martta puuhasi monissa palvelustoimissa, tuli ja sanoi: \"Herra, etkö sinä välitä siitä, että sisareni on jättänyt minut yksin palvelemaan? Sano siis hänelle, että hän auttaisi minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Jeesus vastasi ja sanoi hänelle: \"Martta, Martta, monista asioista huolehdit ja hätäilet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'mutta vain yksi on tarpeen. Maria on valinnut hyvän osan, jota ei oteta häneltä pois.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Tapahtui, kun hän oli eräässä paikassa rukoilemassa ja oli lakannut, että eräs hänen opetuslapsistaan sanoi hänelle: \"Herra, opeta meitä rukoilemaan, kuten Johanneskin opetti opetuslapsiaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Hän sanoi heille: \"Kun rukoilette, sanokaa: Isä, pyhitetty olkoon sinun nimesi; tulkoon sinun valtakuntasi; tapahtukoon sinun tahtosi myös maan päällä niin kuin taivaassa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'anna meille joka päivä jokapäiväinen leipämme;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'ja anna meille syntimme anteeksi, sillä mekin annamme anteeksi jokaiselle velallisellemme; äläkä saata meitä kiusaukseen, vaan päästä meidät pahasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Hän sanoi heille: \" [Olettakaamme:] jollakulla teistä on ystävä ja hän menee hänen luokseen keskellä yötä ja sanoo hänelle: \'Ystäväni, lainaa minulle kolme leipää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'sillä eräs ystäväni on matkallaan tullut luokseni, eikä minulla ole, mitä panna hänen eteensä\';');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'ja toinen vastaa sisältä ja sanoo: \'Älä vaivaa minua. Ovi on jo suljettu, ja lapseni ovat kanssani vuoteessa. En voi nousta antamaan sinulle.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Sanon teille: vaikka hän ei nousekaan antamaan hänelle sen tähden, että on hänen ystävänsä, hän nousee kuitenkin sen tähden, että toinen ei hellitä, ja antaa hänelle niin paljon, kuin hän tarvitsee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Niinpä minäkin sanon teille: anokaa, niin teille annetaan; etsikää, niin te löydätte; kolkuttakaa, niin teille avataan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Sillä jokainen anova saa, etsivä löytää, ja kolkuttavalle avataan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Kuka teistä on sellainen isä, joka poikansa häneltä pyytäessä kalaa antaa hänelle kalan sijasta käärmeen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'tai joka hänen pyytäessään munaa antaa hänelle skorpionin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Jos siis te, jotka olette pahoja, osaatte antaa lapsillenne hyviä lahjoja, kuinka paljoa ennemmin taivaallinen Isä antaa Pyhän Hengen niille, jotka tätä häneltä anovat!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Hän ajoi ulos riivaajan, ja se oli mykkä. Kun riivaaja oli lähtenyt, tapahtui, että mykkä mies puhui, ja kansa ihmetteli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Mutta muutamat heistä sanoivat: \"Beelsebulin, riivaajien päämiehen, kautta hän ajaa ulos riivaajia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Toiset taas kiusasivat häntä ja pyysivät häneltä merkkiä taivaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Mutta hän tiesi heidän ajatuksensa ja sanoi heille: \"Jokainen valtakunta, joka riitautuu itsensä kanssa, joutuu autioksi, ja talo kaatuu talon päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Jos nyt saatanakin on riitautunut itsensä kanssa, kuinka hänen valtakuntansa pysyy pystyssä? Tehän sanotte minun Beelsebulin kautta ajavan ulos riivaajia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Mutta jos minä Beelsebulin kautta ajan ulos riivaajia, kenen kautta sitten teidän lapsenne ajavat niitä ulos? Sen tähden he tulevat olemaan teidän tuomarinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Mutta jos Jumalan sormella ajan ulos riivaajia, onhan Jumalan valtakunta tullut teidän luoksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Kun väkevä aseellisena vartioi kartanoaan, hänen omaisuutensa on turvassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'Mutta kun häntä väkevämpi karkaa hänen päälleen ja voittaa hänet, hän ottaa häneltä kaikki aseet, joihin hän luotti, ja jakaa häneltä riistämänsä saaliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Se, joka ei ole minun kanssani, on minua vastaan, ja se, joka ei minun kanssani kokoa, hajottaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Kun saastainen henki lähtee ihmisestä, se kuljeskelee autioita paikkoja ja etsii lepoa; ja kun ei löydä, se sanoo: \'Minä palaan huoneeseeni, josta lähdin.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'Kun se tulee, se tapaa sen lakaistuna ja kaunistettuna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Se menee ja ottaa mukaansa seitsemän muuta henkeä, pahempaa kuin se itse, ja ne tulevat sisään ja asuvat siellä. Sen ihmisen viimeiset tulevat pahemmiksi kuin ensimmäiset.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Hänen tätä puhuessaan eräs nainen kansanjoukosta korotti äänensä ja sanoi hänelle: \"Autuas on se kohtu, joka on kantanut sinut, ja ne rinnat, joita olet imenyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Mutta hän sanoi: \"Niin, autuaat ovat ne, jotka kuulevat Jumalan sanan ja sen säilyttävät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Kun kansaa yhä kokoontui, hän rupesi puhumaan: \"Tämä sukupolvi on paha sukupolvi: se tavoittelee merkkiä, mutta sille ei anneta muuta merkkiä kuin Joonan merkki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Sillä niin kuin Joona tuli niiniveläisille merkiksi, Ihmisen Poikakin on oleva merkkinä tälle sukupolvelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'Etelän kuningatar on heräävä tuomiolle yhdessä tämän sukupolven miesten kanssa ja tuleva heille tuomioksi. Hän näet tuli maan ääristä kuulemaan Salomon viisautta, ja katso, tässä on enemmän kuin Salomo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Niiniven miehet nousevat tuomiolle yhdessä tämän sukupolven kanssa ja tulevat sille tuomioksi; sillä he muuttivat mielensä Joonan saarnasta, ja katso, tässä on enemmän kuin Joona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Ei kukaan, joka sytyttää lampun, pane sitä piiloon eikä vakan alle, vaan panee sen lampunjalkaan, että sisälle tulijat näkisivät valon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Silmä on ruumiin lamppu. Kun silmäsi on terve, koko ruumiisi on valaistu. Mutta jos se on viallinen, ruumiisikin on pimeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Katso siis, ettei valo, joka sinussa on, ole pimeyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Jos siis koko ruumiisi on valoisa eikä osaksikaan pimeä, se on oleva kokonaan valoisa, niin kuin lampun valaistessa sinua loisteellaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Hänen sitä puhuessaan pyysi eräs fariseus häntä luokseen aamuaterialle. Hän meni sinne ja asettui aterioimaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Mutta kun fariseus näki, ettei hän peseytynyt ennen ateriaa, hän ihmetteli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Herra sanoi hänelle: \"Kyllä te, fariseukset, puhdistatte maljan ja vadin ulkopuolen, mutta sisältä te olette täynnä ryöstöä ja pahuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Te typerykset, eikö se, joka on tehnyt ulkopuolen, ole tehnyt sisäpuoltakin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Mutta antakaa almuksi se, mikä on sisällä. Katso, silloin kaikki on teille puhdasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Voi kuitenkin teitä, te fariseukset, kun annatte kymmenykset mintusta ja ruudasta ja kaikista vihanneksista, mutta sivuutatte oikeuden ja Jumalan rakkauden! Näitä tulee noudattaa eikä noitakaan hylätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Voi teitä, te fariseukset, kun rakastatte etummaista istuinta synagogissa ja tervehdyksiä toreilla!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Voi teitä, kun olette kuin merkittömät haudat, joiden päällä ihmiset kävelevät niistä tietämättä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Eräs lainoppineista rupesi puhumaan ja sanoi hänelle: \"Opettaja, kun noin puhut, loukkaat myös meitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Mutta hän sanoi: \"Voi teitäkin, te lainoppineet, kun sälytätte ihmisten päälle vaikeasti kannettavia taakkoja ettekä itse sormellannekaan koske niihin taakkoihin!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Voi teitä, kun te rakennatte profeettojen hautakammioita, ja teidän isänne ovat heidät tappaneet!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Olette siis isienne tekojen todistajia ja hyväksytte ne: sillä he tappoivat profeetat, ja rakennatte heille hautakammioita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Sen tähden Jumalan Viisaus sanookin: \'Minä lähetän heille profeettoja ja apostoleja, ja joitakuita heistä he tappavat ja toisia vainoavat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'että tältä sukukunnalta vaadittaisiin kaikkien profeettojen veri, mikä on vuodatettu maailman perustamisesta asti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'aina Aabelin verestä Sakariaan vereen saakka, hänen, joka surmattiin alttarin ja temppelin välillä.\' Niin, minä sanon teille, se tullaan vaatimaan tältä sukukunnalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Voi teitä, te lainoppineet, kun olette vieneet tiedon avaimen! Itse ette ole menneet sisälle, ja sisälle meneviä olette estäneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Mutta kun hän puhui heille sellaista, kirjanoppineet ja fariseukset alkoivat ahdistaa häntä kovasti ja urkkia häneltä monia asioita,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'vaanien, miten saisivat hänet päästämään suustaan jotakin, mistä voisivat syyttää häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Kun sillä välin kansaa oli kokoontunut tuhatmäärin, niin että he tallasivat toisiaan, hän ryhtyi puhumaan opetuslapsilleen: \"Ennen kaikkea kavahtakaa fariseusten hapatusta, se on, tekopyhyyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Ei ole mitään peitettyä, mikä ei tule paljastetuksi, eikä mitään salattua, mikä ei tule tunnetuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Sen tähden, kaikki, mitä sanotte pimeässä, kuullaan valossa, ja mitä puhutte korvaan kammioissa, se julistetaan katoilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Mutta sanon teille, ystävilleni: älkää pelätkö niitä, jotka tappavat ruumiin, eivätkä sen lisäksi voi muuta tehdä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'vaan osoitan teille, ketä teidän on pelättävä: pelätkää häntä, jolla on valta tapettuaan syöstä helvettiin. Niin, sanon teille, häntä pelätkää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Eikö viittä varpusta myydä kahteen ropoon? Eikä Jumala ole unohtanut yhtäkään niistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Ovatpa teidän päänne hiuksetkin kaikki luetut. Älkää pelätkö; olette suurempiarvoiset kuin monta varpusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Mutta sanon teille: jokaisen, joka tunnustaa minut ihmisten edessä, myös Ihmisen Poika tunnustaa Jumalan enkelien edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'Mutta se, joka kieltää minut ihmisten edessä, kielletään Jumalan enkelien edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'Jokaiselle, joka sanoo sanan Ihmisen Poikaa vastaan, annetaan anteeksi. Mutta sille, joka pilkkaa Pyhää Henkeä, ei anneta anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Mutta kun he vievät teitä synagogien, hallitusten ja esivaltojen eteen, älkää huolehtiko siitä, miten tai mitä vastaisitte puolestanne tai mitä sanoisitte;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'sillä Pyhä Henki opettaa teille sillä hetkellä, mitä teidän tulee sanoa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Eräs mies kansanjoukosta sanoi hänelle: \"Opettaja, sano veljelleni, että hän jakaisi perinnön kanssani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Mutta hän vastasi hänelle: \"Ihminen, kuka on asettanut minut teille tuomariksi tai jakomieheksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Hän sanoi heille: \"Katsokaa eteenne ja kavahtakaa ahneutta, sillä ihminen ei elä siitä, että hänellä on paljon omaisuutta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Hän puhui heille vertauksen sanoen: \"Rikkaan miehen maa kasvoi hyvin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'Hän mietti mielessään ja sanoi: \'Mitä teen, kun minulla ei ole, mihin kokoaisin satoni?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Hän sanoi: \'Tämän teen: revin maahan aittani ja rakennan suuremmat, kokoan niihin koko satoni ja omaisuuteni');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'ja sanon sielulleni: sielu, sinulla on paljon hyvää tallessa moneksi vuodeksi: nauti lepoa, syö, juo ja iloitse.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Mutta Jumala sanoi hänelle: \'Sinä mieletön, tänä yönä sielusi vaaditaan sinulta pois; kenelle sitten tulee se, minkä olet hankkinut?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Näin käy sen, joka kokoaa aarteita itselleen, mutta jolla ei ole rikkautta Jumalan luona.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Hän sanoi opetuslapsilleen: \"Sen tähden sanon teille: älkää murehtiko hengestänne, mitä söisitte, älkääkä ruumiistanne, mitä päällenne pukisitte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Sillä henki on enemmän kuin ruoka, ja ruumis enemmän kuin vaatteet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Katselkaa korppeja: ne eivät kylvä eivätkä leikkaa, eikä niillä ole varastoa eikä aittaa, ja Jumala ruokkii ne. Kuinka paljoa suurempiarvoisia te olette kuin linnut!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Kuka teistä voi murehtimisellaan lisätä ikäänsä kyynäränkään vertaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Jos siis ette voi sitäkään, mikä on vähintä, mitä murehditte muusta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Katselkaa liljoja, kuinka ne kasvavat: eivät ne tee työtä eivätkä kehrää. Kuitenkin sanon teille: Salomo ei kaikessa loistossaan ollut vaatetettu kuin yksi niistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Jos siis Jumala näin vaatettaa kedon ruohon, joka tänään kasvaa ja huomenna heitetään uuniin, kuinka paljoa ennemmin teidät, te vähäuskoiset!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Älkää siis tekään etsikö, mitä söisitte ja mitä joisitte, älkääkä murehtiko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Sillä näitä kaikkia maailman pakanat tavoittelevat, mutta teidän Isänne kyllä tietää teidän näitä tarvitsevan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'vaan etsikää Jumalan valtakuntaa, niin nämäkin teille annetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Älä pelkää, sinä pieni lauma; sillä teidän Isänne on nähnyt hyväksi antaa teille valtakunnan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Myykää sitä, mitä teillä on, ja antakaa almuja; hankkikaa itsellenne kulumattomat kukkarot, loppumaton aarre taivaisiin, mihin varas ei pääse ja missä koi ei turmele.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Sillä missä aarteenne on, siellä on myös sydämenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Olkoot kupeenne vyötetyt ja lamppunne palamassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'ja olkaa te niiden ihmisten kaltaisia, jotka herraansa odottavat, milloin hän palaa häistä, että he hänen tullessaan ja kolkuttaessaan avaisivat heti hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Autuaat ne palvelijat, jotka heidän herransa tullessaan tapaa valvomasta! Totisesti sanon teille: hän vyöttäytyy ja asettaa heidät aterioimaan ja menee ja palvelee heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Jos hän tulee toisella yövartiolla tai kolmannella ja havaitsee heidän näin tekevän, niin autuaita ovat ne palvelijat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Mutta se tietäkää: jos perheenisäntä tietäisi, millä hetkellä varas tulee, hän ei sallisi taloonsa murtauduttavan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Olkaa tekin valmiit, sillä sinä hetkenä, jona ette luule, Ihmisen Poika tulee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Pietari sanoi: \"Herra, meistäkö sinä sanot tämän vertauksen vai myös kaikista muista?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Herra sanoi: \"Kuka siis on se uskollinen ja viisas huoneenhaltija, jonka hänen herransa asettaa pitämään huolta palvelusväestään, antamaan heille ajallaan heidän ruokaosansa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Autuas se palvelija, jonka hänen herransa tullessaan havaitsee näin tekevän!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Totisesti sanon teille: hän asettaa hänet kaiken omaisuutensa hoitajaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Mutta jos palvelija sanoo sydämessään: \'Herrani tulo viivästyy\', ja rupeaa lyömään palvelijoita ja palvelijattaria sekä syömään, juomaan ja päihdyttämään itseään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'sen palvelijan herra tulee päivänä, jona hän ei odota, ja hetkenä, jota hän ei arvaa, hakkaa hänet kappaleiksi ja määrää hänelle saman osan kuin uskottomille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Sitä palvelijaa, joka tiesi herransa tahdon, mutta ei tehnyt valmisteluja eikä toiminut hänen tahtonsa mukaan, rangaistaan monilla lyönneillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'Sitä taas, joka ei tiennyt, mutta teki sellaista, mikä ansaitsee lyöntejä, rangaistaan vain muutamilla lyönneillä. Sillä jokaiselta, jolle on paljon annettu, myös paljon vaaditaan; ja jolle on paljon uskottu, siltä sitä enemmän kysytään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Tulta olen tullut heittämään maan päälle. Kuinka tahtoisinkaan, että se olisi jo syttynyt!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Mutta minut on kasteella kastettava, ja kuinka olenkaan ahdistettu, kunnes se on täytetty!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Luuletteko, että olen tullut tuomaan rauhan maan päälle? Ei, sanon teille, vaan eripuran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Sillä tästedes riitautuu viisi samassa talossa keskenään, kolme joutuu riitaan kahta vastaan ja kaksi kolmea vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'isä poikaansa vastaan ja poika isäänsä vastaan, äiti tytärtään vastaan ja tytär äitiään vastaan, anoppi miniäänsä vastaan ja miniä anoppiaan vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Hän sanoi myös kansalle: \"Kun näette pilven nousevan lännestä, sanotte heti: \'Tulee sade\'; ja niin tuleekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'Kun näette etelätuulen puhaltavan, sanotte: \'Tulee helle\'; ja niin tuleekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Te ulkokullatut, maan ja taivaan muodon osaatte arvioida, mutta kuinka ette arvioi tätä aikaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Miksi ette jo itsestänne päätä, mikä on oikein?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Kun kuljet riitapuolesi kanssa hallitusmiehen eteen, tee matkalla voitavasi päästäksesi hänestä sovussa eroon, ettei hän raahaisi sinua tuomarin eteen ja tuomari antaisi sinua oikeudenpalvelijalle, ja ettei oikeudenpalvelija heittäisi sinua vankeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Sanon sinulle: sieltä et pääse, ennen kuin olet maksanut viimeisenkin rovon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Samaan aikaan oli paikalle tullut muutamia, jotka kertoivat hänelle niistä galilealaisista, joiden veren Pilatus oli sekoittanut heidän uhriensa vereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Jeesus vastasi ja sanoi heille: \"Luuletteko, että nämä galilealaiset olivat syntisempiä kuin kaikki muut galilealaiset, koska he kärsivät tämän?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Eivät, sanon teille, mutta ellette muuta mieltänne, samoin te kaikki hukutte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Tai ne kahdeksantoista, jotka saivat surmansa, kun torni Siloassa kaatui heidän päälleen, luuletteko, että he olivat syyllisempiä kuin kaikki muut ihmiset, jotka asuvat Jerusalemissa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Eivät, sanon teille, mutta ellette muuta mieltänne, samoin te kaikki hukutte.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Hän puhui tämän vertauksen: \"Eräällä miehellä oli viikunapuu istutettuna viinitarhassaan; ja hän tuli etsimään siitä hedelmää, mutta ei löytänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Hän sanoi viinitarhurille: \'Katso, kolmena vuotena olen käynyt etsimässä hedelmää tästä viikunapuusta, mutta en ole löytänyt. Hakkaa se pois! Miksi se vielä laihduttaa maata?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Mutta tämä vastasi ja sanoi hänelle: \'Herra, anna sen olla vielä tämä vuosi. Sillä aikaa muokkaan ja lannoitan maan sen ympäriltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'Ehkä se ensi vuonna tekee hedelmää, mutta jos ei, niin hakkaa se pois.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Hän oli opettamassa eräässä synagogassa sapattina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'Katso, siellä oli nainen, jossa oli ollut heikkouden henki kahdeksantoista vuotta. Hän oli kumarassa eikä voinut suoristaa itseään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Hänet nähdessään Jeesus kutsui hänet luokseen ja sanoi hänelle: \"Nainen, olet päässyt heikkoudestasi\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'ja pani kätensä hänen päälleen. Heti nainen oikaisi itsensä suoraksi ja ylisti Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Mutta synagogan esimies, joka närkästyi siitä, että Jeesus paransi sapattina, rupesi puhumaan ja sanoi kansalle: \"Kuusi päivää on, joina tulee tehdä työtä. Tulkaa siis niinä päivinä parannuttamaan itseänne, älkääkä sapatinpäivänä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Mutta Herra vastasi hänelle ja sanoi: \"Sinä tekopyhä, eikö jokainen teistä sapattina päästä härkäänsä tai aasiaan seimestä ja vie sitä juomaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Tätä naista, joka on Aabrahamin tytär ja jota saatana on pitänyt sidottuna, katso, jo kahdeksantoista vuotta, tätäkö ei olisi pitänyt päästää siitä siteestä sapatinpäivänä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Hänen näin sanoessaan kaikki hänen vastustajansa häpesivät, ja kaikki kansa iloitsi kaikista niistä valtavista teoista, joita hän teki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Hän sanoi: \"Minkä kaltainen on Jumalan valtakunta, ja mihin sen vertaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Se on sinapinsiemenen kaltainen, jonka mies otti ja kylvi puutarhaansa. Se kasvoi, ja siitä tuli puu, ja taivaan linnut tekivät pesänsä sen oksille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'Taas hän sanoi: \"Mihin vertaan Jumalan valtakunnan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Se on hapatteen kaltainen, jonka nainen otti ja sekoitti kolmeen vakalliseen vehnäjauhoja, kunnes kaikki happani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'Hän vaelsi kaupungista kaupunkiin ja kylästä kylään ja opetti kulkien Jerusalemia kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Joku kysyi häneltä: \"Herra, onko niitä vähän, jotka pelastuvat?\" Hän sanoi heille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, '\"Kilvoitelkaa päästäksenne sisälle ahtaasta portista, sillä monet, sanon teille, koettavat päästä sisälle, mutta eivät voi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Sen jälkeen kun perheenisäntä on noussut ja sulkenut oven ja rupeatte seisomaan ulkona ja kolkuttamaan ovea sanoen: \'Herra, avaa meille\', hän vastaa ja sanoo teille: \'En tunne teitä enkä tiedä, mistä olette.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Silloin alatte sanoa: \'Mehän söimme ja joimme sinun seurassasi, ja meidän kaduillamme sinä opetit.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'Mutta hän lausuu: \'Sanon teille: en tiedä, mistä olette. Menkää pois luotani, kaikki vääryyden tekijät.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Siellä on oleva itku ja hammasten kiristys, kun näette Aabrahamin, Iisakin ja Jaakobin ja kaikkien profeettojen olevan Jumalan valtakunnassa, mutta huomaatte itsenne heitetyiksi ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'Tulijoita saapuu idästä ja lännestä sekä pohjoisesta ja etelästä, ja he aterioivat Jumalan valtakunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'Katso, on viimeisiä, jotka tulevat ensimmäisiksi, ja on ensimmäisiä, jotka tulevat viimeisiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'Samalla hetkellä tuli hänen luokseen muutamia fariseuksia, ja he sanoivat hänelle: \"Lähde ja mene täältä pois, sillä Herodes tahtoo tappaa sinut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'Hän sanoi heille: \"Menkää ja sanokaa sille ketulle: \'Katso, ajan ulos riivaajia ja parannan sairaita tänään ja huomenna, ja kolmantena päivänä tulen määränpäähän.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Kuitenkin minun pitää vaeltaa tänään, huomenna ja ylihuomenna, sillä ei sovi, että profeetta saa surmansa muualla kuin Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jerusalem, Jerusalem, sinä, joka tapat profeetat ja kivität ne, jotka ovat lähetetyt luoksesi, kuinka usein olenkaan tahtonut koota lapsesi, niin kuin kana kokoaa poikasensa siipiensä alle! Mutta [te] ette ole tahtoneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Katso, \'teidän huoneenne jää autioksi.\' Mutta sanon teille: ette näe minua, ennen kuin tulee se aika, jolloin sanotte: \'Siunattu olkoon hän, joka tulee Herran nimeen.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'Tapahtui, että kun hän tuli sapattina erään fariseusten johtomiehen taloon aterialle, he pitivät häntä silmällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Katso, siellä oli vesitautinen mies hänen edessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Jeesus alkoi puhua lainoppineille ja fariseuksille ja sanoi: \"Onko luvallista parantaa sapattina?\" Mutta he olivat vaiti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Hän tarttui häneen, paransi hänet ja laski menemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'Hän sanoi heille: \"Jos joltakulta teistä putoaa aasi tai härkä kaivoon, eikö hän heti vedä sitä ylös sapatinpäivänäkin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Mutta he eivät kyenneet vastaamaan tähän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Huomatessaan, kuinka kutsutut valitsivat itselleen ensimmäisiä sijoja, hän puhui heille vertauksen ja sanoi heille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, '\"Kun joku on kutsunut sinut häihin, älä asetu aterioimaan ensimmäiselle sijalle; sillä, jos hän on kutsunut sinua arvollisemman,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'niin se, joka on sinut ja hänet kutsunut, tulee ja sanoo sinulle: \'Anna tälle sija\', ja sinun on häveten siirryttävä viimeiselle paikalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Vaan kun olet kutsuttu, mene ja asetu viimeiselle sijalle, ja se, joka on sinut kutsunut, sanoo sinulle sisään tullessaan: \'Ystäväni, astu ylemmäksi.\' Silloin tulee sinulle kunnia kaikkien pöytäkumppaniesi edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Sillä jokainen, joka itsensä ylentää, alennetaan, ja se, joka itsensä alentaa, ylennetään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Mutta hän sanoi myös sille, joka oli hänet kutsunut: \"Kun laitat lounaan tai illallisen, älä kutsu ystäviäsi, veljiäsi, sukulaisiasi äläkä rikkaita naapureita, etteivät hekin vuorostaan kutsuisi sinua, ja saisit korvauksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Vaan kun laitat pidot, kutsu köyhiä, raajarikkoja, rampoja ja sokeita;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'niin olet oleva autuas, koska he eivät voi maksaa sinulle, sillä sinulle maksetaan vanhurskasten ylösnousemuksessa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Tämän kuullessaan eräs pöytävieraista sanoi hänelle: \"Autuas se, joka aterioi Jumalan valtakunnassa!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Hän sanoi hänelle: \"Eräs mies laittoi suuret illalliset ja kutsui monta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'Illallisajan tullessa hän lähetti palvelijansa sanomaan kutsutuille: \'Tulkaa, sillä kaikki on jo valmista.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Mutta he alkoivat kaikki yksimielisesti estellä. Ensimmäinen sanoi hänelle: \'Ostin pellon, ja minun täytyy lähteä sitä katsomaan; pyydän sinua, pidä minut estettynä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Toinen sanoi: \'Ostin viisi paria härkiä ja menen niitä kokeilemaan; pyydän sinua, pidä minut estettynä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Vielä toinen sanoi: \'Otin vaimon enkä sen tähden voi tulla.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Palvelija tuli takaisin ja ilmoitti herralleen tämän. Silloin isäntä vihastui ja sanoi palvelijalleen: \'Mene kiireesti kaupungin kaduille ja kujille ja tuo köyhät, raajarikot, sokeat ja rammat tänne sisälle.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'Palvelija sanoi: \'Herra, on tehty, minkä käskit, ja vielä on tilaa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Herra sanoi palvelijalle: \'Mene kiireen vilkkaa teille ja kujille ja pakota heitä tulemaan sisälle, että taloni täyttyisi;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'sillä sanon teille, ettei yksikään niistä miehistä, jotka olivat kutsutut, maista illallistani.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Hänen mukanaan kulki paljon kansaa, ja hän kääntyi ja sanoi heille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, '\"Jos joku tulee luokseni eikä vihaa isäänsä ja äitiään, vaimoaan, lapsiaan, veljiään ja sisariaan, vieläpä omaa elämäänsäkin, hän ei voi olla minun opetuslapseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'Se, joka ei kanna ristiään ja seuraa minua, ei voi olla minun opetuslapseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Sillä jos joku teistä tahtoo rakentaa tornin, eikö hän ensin istu laskemaan kustannuksia nähdäkseen, onko hänellä varaa rakentaa se valmiiksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'etteivät, kun hän on laskenut perustuksen, mutta ei kykene saamaan rakennusta valmiiksi, kaikki, jotka sen näkevät, alkaisi pilkata häntä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'sanoen: \'Tuo mies ryhtyi rakentamaan, mutta ei kyennyt saamaan valmiiksi\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Tai jos joku kuningas tahtoo lähteä sotimaan toista kuningasta vastaan, eikö hän ensin istu ja neuvottele, voiko hän kymmenellä tuhannella kohdata sen, joka tulee häntä vastaan kahdellakymmenellä tuhannella?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Ellei voi, hän toisen vielä ollessa kaukana lähettää hänen luokseen lähettilään pyytämään rauhaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Niin ei myöskään teistä yksikään, joka ei luovu kaikesta, mitä hänellä on, voi olla minun opetuslapseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Suola on hyvä, mutta jos suola käy mauttomaksi, millä se saadaan suolaiseksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Se ei kelpaa maahan eikä lannaksi; se heitetään pois. Jolla on korvat kuulla, se kuulkoon!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Kaikki publikaanit ja syntiset tulivat hänen luokseen kuulemaan häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Mutta fariseukset ja kirjanoppineet nurisivat ja sanoivat: \"Tämä ottaa vastaan syntisiä ja syö heidän kanssaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Hän puhui heille tämän vertauksen sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, '\"Kuka teistä, jolla on sata lammasta, ja joka kadottaa niistä yhden, ei jätä niitä yhdeksääkymmentä yhdeksää erämaahan ja mene etsimään kadonnutta, kunnes löytää sen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'Löydettyään hän panee sen hartioilleen iloiten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'Kun hän tulee kotiin, hän kutsuu kokoon ystävänsä ja naapurinsa ja sanoo heille: \'Iloitkaa kanssani, sillä löysin kadonneen lampaani.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Sanon teille: niin on ilo taivaassa suurempi yhdestä syntisestä, joka muuttaa mielensä, kuin yhdeksästäkymmenestä yhdeksästä vanhurskaasta, jotka eivät tarvitse mielenmuutosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Tai jos jollakulla naisella on kymmenen hopearahaa ja hän kadottaa niistä yhden, eikö hän sytytä lamppua ja lakaise huonetta ja etsi tarkasti, kunnes sen löytää?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'Löydettyään hän kutsuu kokoon ystävättärensä ja naapurinaiset ja sanoo: \'Iloitkaa kanssani, sillä löysin rahan, jonka olin kadottanut.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Niin myös, sanon teille, Jumalan enkeleillä on ilo yhdestä syntisestä, joka muuttaa mielensä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Vielä hän sanoi: \"Eräällä miehellä oli kaksi poikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'Nuorempi heistä sanoi isälleen: \'Isä, anna minulle se osa omaisuudesta, mikä minulle on tuleva.\' Hän jakoi heille omaisuutensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Eikä kulunut montakaan päivää, kun nuorempi poika kokosi kaiken omansa, matkusti pois kaukaiseen maahan ja hävitti siellä omaisuutensa eläen irstaasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Mutta kun hän oli kaiken tuhlannut, koko siihen maahan tuli kova nälkä, ja hän alkoi kärsiä puutetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Hän meni palvelukseen eräälle sen maan kansalaiselle, ja tämä lähetti hänet tiluksilleen kaitsemaan sikoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Hän halusi täyttää vatsansa niillä paloilla, joita siat söivät, mutta kukaan ei antanut hänelle niitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Hän meni itseensä ja sanoi: \'Kuinka monella isäni palkkalaisella on leipää yllin kyllin, mutta minä kärsin täällä nälkää!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Nousen ja menen isäni luo ja sanon hänelle: Isä, olen tehnyt syntiä taivasta vastaan ja sinun edessäsi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'enkä enää ansaitse, että minua sinun pojaksesi kutsutaan. Tee minut yhdeksi palkkalaisistasi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Hän nousi ja meni isänsä luo. Mutta kun hän vielä oli kaukana, hänen isänsä näki hänet, sääli häntä, juoksi häntä vastaan, lankesi hänen kaulaansa ja suuteli häntä rakkaasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Mutta poika sanoi hänelle: \'Isä, olen tehnyt syntiä taivasta vastaan ja sinun edessäsi enkä enää ansaitse, että minua pojaksesi kutsutaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Mutta isä sanoi palvelijoilleen: \'Tuokaa pian parhaat vaatteet ja pukekaa hänet niihin, ja pankaa sormus hänen sormeensa ja sandaalit hänen jalkaansa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'ja noutakaa syöttövasikka ja teurastakaa, ja syökäämme ja iloitkaamme,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'sillä tämä minun poikani oli kuollut ja virkosi eloon, hän oli kadonnut ja on jälleen löytynyt.\' Ja he iloitsivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Mutta hänen vanhempi poikansa oli pellolla. Kun hän tuli ja lähestyi kotia, hän kuuli laulun ja karkelon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'Hän kutsui luokseen yhden palvelijoista ja tiedusteli, mitä se oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'Tämä sanoi hänelle: \'Sinun veljesi on tullut, ja isäsi teurastutti syöttövasikan, kun sai hänet terveenä takaisin.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Hän vihastui eikä tahtonut mennä sisälle, mutta hänen isänsä tuli ulos ja kutsui häntä sisään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Mutta hän vastasi ja sanoi isälleen: \'Katso, niin monta vuotta olen palvellut sinua enkä ole milloinkaan lyönyt laimin käskyäsi, ja kuitenkaan et ole minulle koskaan antanut kiliäkään pitääkseni iloa ystävieni kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Mutta kun tämä sinun poikasi tuli, joka on tuhlannut omaisuutesi porttojen kanssa, hänelle sinä teurastit syöttövasikan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'Hän sanoi hänelle: \'Poikani, sinä olet aina luonani ja kaikki, mikä on minun omaani, on sinun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Mutta pitihän nyt riemuita ja iloita, sillä tämä sinun veljesi oli kuollut ja virkosi eloon, hän oli kadonnut ja on jälleen löytynyt.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Mutta hän puhui myös opetuslapsilleen: \"Oli rikas mies, jolla oli huoneenhaltija, ja hänelle kanneltiin, että tämä hävitti hänen omaisuuttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Hän kutsui hänet eteensä ja sanoi hänelle: \'Mitä kuulenkaan sinusta? Tee tili taloudenhoidosta, sillä et voi enää hallita taloani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Huoneenhaltija sanoi mielessään: \'Mitä teen, kun isäntäni ottaa minulta pois taloudenhoidon? Kaivaa en jaksa, kerjäämistä häpeän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Tiedän, mitä teen, että ottaisivat minut taloihinsa, kun minut pannaan pois taloudenhoidosta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Hän kutsui luokseen jokaisen herransa velallisista ja sanoi ensimmäiselle: \'Paljonko olet velkaa herralleni?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Tämä sanoi: \'Sata astiaa öljyä.\' Hän sanoi hänelle: \'Ota velkakirjasi, istu ja kirjoita pian viisikymmentä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Hän sanoi toiselle: \'Entä sinä, paljonko olet velkaa?\' Tämä sanoi: \'Sata tynnyriä vehnää.\' Hän sanoi hänelle: \'Ota velkakirjasi, kirjoita kahdeksankymmentä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'Herra kehui väärää huoneenhaltijaa siitä, että hän oli menetellyt ovelasti. Sillä tämän maailman lapset ovat omaa sukukuntaansa kohtaan ovelampia kuin valkeuden lapset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Sanon teille: tehkää itsellenne ystäviä väärällä mammonalla, että he, kun se loppuu, ottaisivat teidät iäisiin majoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Se, joka vähimmässä on uskollinen, on paljossakin uskollinen, ja se, joka vähimmässä on väärä, on paljossakin väärä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Jos siis ette ole olleet uskollisia väärässä mammonassa, kuka teille uskoo sitä, mikä on oikeaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Jos ette ole olleet uskollisia siinä, mikä on toisen omaa, kuka teille antaa sitä, mikä on teidän omaanne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Kukaan palvelija ei voi palvella kahta herraa, sillä hän on joko tätä vihaava ja toista rakastava, tai tähän liittyvä ja toista halveksiva. Ette voi palvella Jumalaa ja mammonaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Tämän kaiken kuulivat fariseukset, jotka olivat rahanahneita, ja he ivasivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Hän sanoi heille: \"Te juuri olette ne, jotka teette itsenne vanhurskaiksi ihmisten edessä. Mutta Jumala tuntee teidän sydämenne, sillä se, mikä ihmisten kesken on korkeaa, on Jumalan edessä kauhistus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Laki ja profeetat olivat Johannekseen asti. Siitä lähtien julistetaan Jumalan valtakuntaa, ja jokainen tunkeutuu sinne väkisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Mutta ennemmin taivas ja maa katoavat, kuin yksikään lain piirto häviää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Jokainen, joka hylkää vaimonsa ja nai toisen, tekee huorin, ja joka nai miehensä hylkäämän, tekee huorin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Oli rikas mies, joka pukeutui purppuraan ja hienoihin pellavavaatteisiin ja eli joka päivä ilossa loisteliaasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Mutta eräs köyhä, nimeltä Lasarus, makasi hänen porttinsa luona täynnä paiseita');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'ja halusi ravita itseään niillä muruilla, joita putosi rikkaan pöydältä, ja koiratkin tulivat ja nuolivat hänen paiseitaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Tapahtui, että köyhä kuoli, ja enkelit veivät hänet Aabrahamin helmaan. Rikaskin kuoli, ja hänet haudattiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Kun hän nosti silmänsä helvetissä tuskissa ollessaan, hän näki kaukana Aabrahamin ja Lasaruksen hänen helmassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'Hän huusi sanoen: \'Isä Aabraham, armahda minua ja lähetä Lasarus kastamaan sormensa pää veteen ja jäähdyttämään kieltäni, sillä minulla on kova tuska tässä liekissä!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Mutta Aabraham sanoi: \'Poikani, muista, että sinä eläessäsi sait hyväsi, ja Lasarus puolestaan sai pahaa, mutta nyt hän saa täällä lohdutusta, sinä taas kärsit tuskaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'Kaiken tämän lisäksi on meidän välillemme ja teidän vahvistettu suuri kuilu, että ne, jotka tahtovat mennä täältä teidän luoksenne, eivät voisi, eivätkä ne, jotka siellä ovat, pääsisi yli meidän luoksemme.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Hän sanoi: \'Niin rukoilen siis sinua, isä, että lähetät hänet isäni taloon');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, '– sillä minulla on viisi veljeä – todistamaan heille, etteivät hekin joutuisi tähän vaivan paikkaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Mutta Aabraham sanoi: \'Heillä on Mooses ja profeetat; kuulkoot niitä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'Hän sanoi: \'Ei, isä Aabraham, vaan jos joku kuolleista menisi heidän luokseen, he muuttaisivat mielensä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Mutta Aabraham sanoi hänelle: \'Jos he eivät kuule Moosesta ja profeettoja, he eivät usko, vaikka joku kuolleistakin nousisi ylös.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Mutta opetuslapsilleen hän sanoi: \"Mahdotonta on viettelysten jäädä tulematta, mutta voi sitä, jonka kautta ne tulevat!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Hänen olisi parempi, että myllynkivi pantaisiin hänen kaulaansa ja hänet heitettäisiin mereen, kuin että hän viettelee yhden näistä pienistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Pitäkää itsestänne vaari! Jos sinun veljesi tekee syntiä, nuhtele häntä, ja jos hän katuu, anna hänelle anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'Jos hän seitsemän kertaa päivässä tekee syntiä sinua vastaan ja seitsemän kertaa kääntyy puoleesi ja sanoo: \'Kadun\', niin anna hänelle anteeksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Apostolit sanoivat Herralle: \"Lisää meille uskoa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Herra sanoi: \"Jos teillä olisi uskoa sinapinsiemenen verran, niin sanoisitte tälle silkkiäispuulle: \'Nouse juurinesi ja istuta itsesi mereen\', ja se tottelisi teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Jos jollakulla teistä on palvelija kyntämässä tai paimentamassa, sanooko hän tälle tämän tullessa pellolta: \'Käy heti aterialle\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Eikö hän pikemminkin sano hänelle: \'Valmista minulle ateria, vyöttäydy ja palvele minua, sillä aikaa kun syön ja juon; ja sitten syö ja juo sinä\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Eihän hän kiitä palvelijaa siitä, että tämä teki, mitä oli käsketty? Mielestäni ei.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Myös te, kun olette tehneet kaiken, mitä teidän on käsketty tehdä, sanokaa: \'Olemme ansiottomia palvelijoita; olemme tehneet vain sen, minkä olimme velvolliset tekemään.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'Tapahtui hänen ollessaan matkalla Jerusalemiin, että hän kulki Samarian ja Galilean välistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Hänen mennessään erääseen kylään tuli häntä vastaan kymmenen spitaalista miestä, jotka seisahtuivat kauemmaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'He korottivat äänensä ja sanoivat: \"Jeesus, mestari, armahda meitä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Heidät nähdessään hän sanoi heille: \"Menkää ja näyttäkää itsenne papeille.\" Heidän mennessään tapahtui, että he puhdistuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Mutta yksi heistä, kun näki olevansa parannettu, palasi takaisin, ylisti Jumalaa suurella äänellä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'lankesi kasvoilleen hänen jalkojensa juureen ja kiitti häntä, ja mies oli samarialainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Jeesus vastasi ja sanoi: \"Eivätkö kaikki kymmenen puhdistuneet? Missä ne yhdeksän ovat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Eikö ollut muita, jotka olisivat palanneet antamaan ylistyksen Jumalalle, kuin tämä muukalainen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'Hän sanoi hänelle: \"Nouse ja mene; sinun uskosi on sinut pelastanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Fariseusten kysyessä häneltä milloin Jumalan valtakunta oli tuleva, hän vastasi heille ja sanoi: \"Jumalan valtakunta ei tule nähtävällä tavalla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'eikä sanota: \'Katso, täällä se on\', tai: \'Tuolla\'; sillä katso, Jumalan valtakunta on sisäisesti teissä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Hän sanoi opetuslapsilleen: \"Tulee aika, jolloin te haluaisitte nähdä edes yhden Ihmisen Pojan päivän, mutta ette näe.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'Teille sanotaan: \'Katso, tuolla hän on!\' \'Katso, täällä!\' Älkää menkö sinne älkääkä juosko perässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Sillä niin kuin salaman leimaus loistaa taivaan äärestä taivaan ääreen, niin on Ihmisen Poika päivänään oleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Mutta sitä ennen pitää hänen kärsiä paljon ja joutua tämän sukupolven hylkäämäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'Samoin kuin kävi Nooan päivinä, käy myös Ihmisen Pojan päivinä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'he söivät, joivat, naivat ja menivät miehelle, aina siihen päivään asti, jona Nooa meni arkkiin, ja vedenpaisumus tuli ja hukutti heidät kaikki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Samoin kuin tapahtui Lootin päivinä: he söivät, joivat, ostivat, myivät, istuttivat ja rakensivat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'mutta sinä päivänä, jona Loot lähti Sodomasta, satoi tulta ja rikkiä taivaasta, ja se hukutti heidät kaikki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Samoin käy sinä päivänä, jona Ihmisen Poika ilmestyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'Sinä päivänä älköön se, joka on katolla ja jolla on tavaransa huoneessa, astuko alas niitä noutamaan. Älköön myöskään se, joka on pellolla, palatko takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Muistakaa Lootin vaimoa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Se, joka yrittää pelastaa sielunsa, kadottaa sen, mutta se, joka kadottaa sen, pelastaa sen elämään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Sanon teille: sinä yönä on kaksi miestä yhdellä vuoteella: toinen korjataan talteen, ja toinen jätetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Kaksi naista jauhaa yhdessä; toinen korjataan talteen, mutta toinen jätetään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'Kaksi on pellolla, toinen otetaan, toinen jätetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'He vastasivat ja sanoivat hänelle: \"Missä, Herra?\" Hän sanoi heille: \"Missä on ruumis, sinne myös korppikotkat kokoontuvat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Hän puhui heille vertauksen siitä, että heidän tuli aina rukoilla eikä väsyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Hän sanoi: \"Eräässä kaupungissa oli tuomari, joka ei pelännyt Jumalaa eikä hävennyt ketään ihmistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'Siinä kaupungissa oli naisleski, joka tuli hänen luokseen ja sanoi: \'Auta minut oikeuteeni riitapuoltani vastaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Mutta pitkään aikaan hän ei tahtonut. Vaan sitten hän sanoi mielessään: \'Vaikka en pelkää Jumalaa enkä häpeä ihmisiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'kuitenkin, koska tämä leski tuottaa minulle vaivaa, autan hänet oikeuteensa, ettei hän lopulta tule ja lyö minua kasvoihin.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Herra sanoi: \"Kuulkaa, mitä tuo väärä tuomari sanoo!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Eikö Jumala toimittaisi oikeutta valituilleen, jotka huutavat häntä avuksi yötä päivää, ja olisi pitkämielinen heitä kohtaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Sanon teille: hän toimittaa heille oikeuden pian. Kuitenkin, kun Ihmisen Poika tulee, löytääkö hän uskoa maan päältä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Hän puhui vielä tämän vertauksen muutamille, jotka luottivat itseensä luullen olevansa vanhurskaita, ja halveksivat muita:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, '\"Kaksi miestä meni ylös pyhäkköön rukoilemaan, toinen fariseus ja toinen publikaani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Fariseus seisoi ja rukoili itsekseen näin: \'Jumala, kiitän sinua, etten ole kuin muut ihmiset, rosvot, vääryyden harjoittajat, huorintekijät enkä myöskään kuin tuo publikaani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Paastoan kahdesti viikossa ja annan kymmenykset kaikista tuloistani.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Mutta publikaani seisoi takana eikä edes tahtonut nostaa silmiään taivasta kohti, vaan löi rintaansa ja sanoi: \'Jumala, ole minulle, syntiselle, leppynyt.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Sanon teille: tämä meni kotiinsa vanhurskautettuna, mutta se toinen ei; sillä jokainen, joka itsensä ylentää, alennetaan, mutta joka itsensä alentaa, se ylennetään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'He kantoivat hänen luokseen pieniäkin lapsia, että hän koskisi heihin, mutta sen nähdessään opetuslapset nuhtelivat tuojia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Mutta Jeesus kutsui lapset luokseen ja sanoi: \"Sallikaa lasten tulla minun tyköni älkääkä estäkö heitä, sillä sellaisten on Jumalan valtakunta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Totisesti sanon teille: se, joka ei ota vastaan Jumalan valtakuntaa kuin lapsi, ei mene sinne sisälle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Eräs hallitusmies kysyi häneltä sanoen: \"Hyvä opettaja, mitä minun pitää tehdä, että iankaikkisen elämän perisin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Jeesus sanoi hänelle: \"Miksi sanot minua hyväksi? Ei kukaan ole hyvä, paitsi Jumala yksin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Käskyt sinä tiedät: \'Älä tee huorin\', \'Älä tapa\', \'Älä varasta\', \'Älä sano väärää todistusta\', \'Kunnioita isääsi ja äitiäsi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'Mutta hän sanoi: \"Tätä kaikkea minä olen noudattanut nuoruudestani asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Kun Jeesus sen kuuli, hän sanoi hänelle: \"Yksi sinulta vielä puuttuu: myy kaikki, mitä sinulla on, ja jakele köyhille, niin sinulla on oleva aarre taivaissa; ja tule ja seuraa minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Mutta tämän kuullessaan hän tuli kovin murheelliseksi, sillä hän oli erittäin rikas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Kun Jeesus näki hänen olevan murheissaan, hän sanoi: \"Kuinka vaikeaa onkaan niiden, joilla on rikkautta, päästä Jumalan valtakuntaan!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Helpompi on kamelin käydä neulansilmän läpi kuin rikkaan päästä Jumalan valtakuntaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Ne, jotka sen kuulivat, sanoivat: \"Kuka sitten voi pelastua?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Mutta hän sanoi: \"Se, mikä on ihmisille mahdotonta, on Jumalalle mahdollista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Silloin Pietari sanoi: \"Katso, me olemme luopuneet siitä, mitä meillä oli, ja seuranneet sinua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Hän sanoi heille: \"Totisesti sanon teille: ei ole ketään, joka Jumalan valtakunnan tähden on luopunut talosta, vaimosta, veljistä, vanhemmista tai lapsista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'ja joka ei saisi monin verroin takaisin tässä ajassa, ja tulevassa maailmassa iankaikkista elämää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Hän otti luokseen ne kaksitoista ja sanoi heille: \"Katso, menemme ylös Jerusalemiin, ja kaikki on täysin toteutuva, mitä profeettojen kautta on kirjoitettu Ihmisen Pojasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Sillä hänet annetaan pakanoiden käsiin, ja häntä pilkataan, häväistään ja syljetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'Ruoskittuaan he tappavat hänet, mutta kolmantena päivänä hän nousee ylös.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Mutta he eivät ymmärtäneet tästä mitään, ja tämä puhe oli heiltä salattu eivätkä he käsittäneet, mitä sanottiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Hänen lähestyessään Jerikoa eräs sokea istui tien vieressä kerjäten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'Kuullessaan, että siitä kulki kansaa ohi, hän kyseli, mitä se oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'He ilmoittivat hänelle Jeesuksen, Nasaretilaisen, menevän ohi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Hän huusi sanoen: \"Jeesus, Daavidin poika, armahda minua!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Edellä kulkijat nuhtelivat häntä saadakseen hänet vaikenemaan, mutta hän huusi vielä enemmän: \"Daavidin poika, armahda minua!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Silloin Jeesus pysähtyi ja käski taluttaa hänet luokseen. Hänen tultuaan lähelle Jeesus kysyi häneltä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, '\"Mitä tahdot, että sinulle tekisin?\" Hän sanoi: \"Herra, että saisin näköni jälleen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Jeesus sanoi hänelle: \"Saa näkösi takaisin. Uskosi on sinut pelastanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'Heti hän sai näkönsä ja seurasi häntä ylistäen Jumalaa. Sen nähdessään kaikki kansa kiitti Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'Hän tuli Jerikon kaupunkiin ja kulki sen läpi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'Katso, siellä oli mies, nimeltä Sakkeus. Hän oli publikaanien esimies ja rikas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'Hän yritti nähdä Jeesusta, kuka hän oli, mutta ei voinut kansalta, sillä hän oli pienikokoinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'Hän juoksi edelle ja nousi viikunapuuhun nähdäkseen hänet, sillä Jeesus oli kulkemassa siitä ohi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Tultuaan sille paikalle Jeesus katsoi ylös ja sanoi hänelle: \"Sakkeus, tule nopeasti alas, sillä tänään minun pitää tulla kotiisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'Hän tuli nopeasti alas ja otti hänet vastaan iloiten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Sen nähdessään kaikki nurisivat sanoen: \"Syntisen miehen luo hän meni majailemaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Mutta Sakkeus pysähtyi ja sanoi Herralle: \"Katso, Herra, puolet omaisuudestani annan köyhille, ja jos joltakulta olen jotakin petoksella ottanut, annan nelinkertaisesti takaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Jeesus sanoi hänestä: \"Tänään on pelastus tullut tälle huoneelle, koska hänkin on Aabrahamin poika;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'sillä Ihmisen Poika on tullut etsimään ja pelastamaan sitä, mikä on kadonnut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Heidän tätä kuunnellessaan hän puhui vielä vertauksen, koska hän oli lähellä Jerusalemia, ja he luulivat, että Jumalan valtakunta ilmestyy aivan pian.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Hän sanoi näin: \"Eräs jalosukuinen mies lähti matkalle kaukaiseen maahan ottaakseen itselleen kuninkuuden ja sitten palatakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Hän kutsui luokseen kymmenen palvelijaansa, antoi heille kymmenen miinaa ja sanoi heille: \'Asioikaa näillä, kunnes tulen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Mutta hänen kansalaisensa vihasivat häntä ja lähettivät lähettiläät hänen jälkeensä sanomaan: \'Emme tahdo häntä kuninkaaksemme.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Tapahtui, kun hän oli palannut takaisin ja ottanut kuninkuuden, että hän kutsui eteensä ne palvelijat, joille hän oli antanut hopearahat tietääkseen, mitä kukin oli asioimisellaan ansainnut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Ensimmäinen tuli esiin ja sanoi: \'Herra, sinun miinasi on tuottanut kymmenen miinaa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Hän sanoi hänelle: \'Hyvä on, sinä hyvä palvelija; koska olet ollut uskollinen vähimmässä, olkoon sinulla valta hallita kymmentä kaupunkia.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Tuli toinen ja sanoi: \'Herra, sinun miinasi on tuottanut viisi miinaa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Niin hän sanoi tällekin: \'Hallitse sinä viittä kaupunkia.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'Sitten tuli eräs toinen ja sanoi: \'Herra, katso, tässä on sinun miinasi, jota olen säilyttänyt liinassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'Sillä pelkäsin sinua, koska olet ankara mies: sinä otat, mitä et ole talteen pannut, ja korjaat satoa siitä, mitä et ole kylvänyt.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Hän sanoi hänelle: \'Oman sanasi mukaan sinut tuomitsen, sinä paha palvelija. Sinä tiesit minut ankaraksi mieheksi, joka otan, mitä en ole talteen pannut, ja korjaan satoa siitä, mitä en ole kylvänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Miksi et siis antanut hopearahaani rahanvaihtajan pöytään, että tultuani olisin saanut sen korkoineen?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'Hän sanoi vieressä seisoville: \'Ottakaa miina häneltä pois ja antakaa sille, jolla on kymmenen miinaa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, '– He sanoivat hänelle: \'Herra, hänellä on jo kymmenen miinaa.\' –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, '\'Minä sanon teille: jokaiselle, jolla on, annetaan, mutta siltä, jolla ei ole, otetaan pois sekin, mikä hänellä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Mutta viholliseni, jotka eivät tahtoneet minua kuninkaakseen, tuokaa tänne ja teurastakaa edessäni.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'Tämän sanottuaan hän kulki edellä vaeltaen ylös Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'Tapahtui, kun hän tuli lähelle Beetfagea ja Betaniaa, sille vuorelle, jonka nimenä on Öljymäki, että hän lähetti kaksi opetuslastaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'sanoen: \"Menkää edessä olevaan kylään, sinne tullessanne löydätte sidottuna varsan, jonka selässä ei ole vielä istunut yksikään ihminen. Päästäkää se ja tuokaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'Jos joku kysyy teiltä: \'Miksi päästätte sen?\' sanokaa näin: \'Herra tarvitsee sitä.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Lähetetyt menivät ja havaitsivat niin olevan, kuin hän oli heille sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Heidän päästäessään varsaa sen omistajat sanoivat heille: \"Miksi päästätte varsan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'He sanoivat: \"Herra tarvitsee sitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'He veivät sen Jeesuksen luo ja heittivät viittansa varsan selkään ja asettivat Jeesuksen niiden päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'Hänen kulkiessaan kansa levitti viittansa tielle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Kun hän jo oli lähellä laskeutuen Öljymäeltä, koko opetuslasten joukko alkoi iloiten kiittää Jumalaa suurella äänellä kaikista voimallisista teoista, jotka he olivat nähneet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'sanoen: \"Siunattu olkoon hän, joka tulee, Kuningas Herran nimessä. Rauha taivaassa ja kunnia korkeuksissa!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Muutamat fariseukset kansanjoukosta sanoivat hänelle: \"Opettaja, nuhtele opetuslapsiasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Mutta hän vastasi ja sanoi: \"Sanon teille: jos nämä olisivat vaiti, kivet huutaisivat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Kun hän tuli lähemmäksi ja näki kaupungin, hän itki sitä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'ja sanoi: \"Jospa tietäisit sinäkin tänä päivänä, mitä rauhaasi kuuluu! Mutta nyt se on silmiltäsi salattu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Sillä sinulle tulevat ne päivät, jolloin sinun vihollisesi sinut saartavat vallilla ja piirittävät sinut ja ahdistavat sinua joka puolelta;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'ja he kukistavat sinut maan tasalle ja lapsesi, jotka sinussa ovat, eivätkä jätä sinuun kiveä kiven päälle, sen tähden ettet tuntenut tilintekosi aikaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'Hän meni pyhäkköön ja rupesi ajamaan myyjiä ja ostajia ulos');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'ja sanoi heille: \"Kirjoitettu on: \'Minun huoneeni on oleva rukoushuone\', mutta te olette tehneet siitä ryövärien luolan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Hän opetti joka päivä pyhäkössä. Mutta ylipapit ja kirjanoppineet sekä kansan ensimmäiset etsivät, miten saisivat hänet surmatuksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'mutta eivät keksineet, mitä tekisivät, sillä kaikki kansa riippui hänessä ja kuunteli häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'Tapahtui eräänä päivänä, kun hän opetti kansaa pyhäkössä ja julisti evankeliumia, että ylipapit ja kirjanoppineet astuivat yhdessä vanhinten kanssa esiin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'ja puhuivat hänelle sanoen: \"Sano meille, millä valtuudella näitä teet, tai kuka on se, joka on antanut sinulle tämän vallan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Hän vastasi ja sanoi heille: \"Minäkin kysyn teiltä yhtä asiaa. Sanokaa minulle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'oliko Johanneksen kaste taivaasta vai ihmisistä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'He neuvottelivat keskenään sanoen: \"Jos sanomme: \'Taivaasta\', hän sanoo: \'Miksi ette siis uskoneet häntä?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Mutta jos sanomme: \'Ihmisistä\', kaikki kansa kivittää meidät, sillä se uskoo lujasti, että Johannes oli profeetta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'He vastasivat, etteivät tienneet, mistä se oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'Jeesus sanoi heille: \"Niinpä en minäkään sano teille, millä vallalla näitä teen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Hän rupesi puhumaan kansalle tämän vertauksen: \"Mies istutti viinitarhan ja vuokrasi sen viinitarhureille ja matkusti muille maille kauaksi aikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'Mutta satoaikana hän lähetti palvelijan viinitarhurien luo, että he antaisivat tälle osan viinitarhan hedelmistä, mutta viinitarhurit löivät häntä ja lähettivät tyhjänä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Hän lähetti vielä toisen palvelijan, mutta hänetkin he pieksivät, häpäisivät ja lähettivät tyhjänä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Sen jälkeen hän lähetti vielä kolmannen palvelijan, mutta tätäkin he haavoittivat ja heittivät hänet ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Viinitarhan isäntä sanoi: \'Mitä teen? Lähetän rakkaan poikani. Häntä he kaiketi kavahtavat.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Mutta kun viinitarhurit näkivät hänet, neuvottelivat he keskenään ja sanoivat: \'Tämä on perillinen; tappakaamme hänet, että perintö tulisi meidän omaksemme.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'He heittivät hänet ulos viinitarhasta ja tappoivat. Mitä nyt viinitarhan isäntä tekee heille?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Hän tulee ja tuhoaa nämä viinitarhurit ja antaa viinitarhan muille.\" Sen kuullessaan he sanoivat: \"Pois se!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Mutta hän katsoi heihin ja sanoi: \"Mitä siis on tämä, mikä on kirjoitettu: \'Se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Jokainen, joka kaatuu siihen kiveen, ruhjoutuu, mutta jonka päälle se kaatuu, sen se murskaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'Kirjanoppineet ja ylipapit tahtoivat käydä häneen käsiksi sillä hetkellä. Mutta he pelkäsivät kansaa, sillä he ymmärsivät, että hän oli puhunut vertauksen heistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'He pitivät häntä silmällä ja lähettivät hänen luokseen hurskaiksi tekeytyneitä urkkijoita saadakseen hänet kiinni jostakin sanasta, niin että voisivat antaa hänet esivallalle ja maaherran valtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'He kysyivät häneltä sanoen: \"Opettaja, tiedämme, että puhut ja opetat oikein etkä katso henkilöön, vaan opetat Jumalan tietä totuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Onko meidän lupa antaa keisarille veroa vai ei?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Mutta hän havaitsi heidän kavaluutensa ja sanoi heille: \"Miksi kiusaatte minua?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Näyttäkää minulle denaari. Kenen kuva ja päällekirjoitus siinä on?\" He vastasivat: \"Keisarin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Hän sanoi heille: \"Antakaa siis keisarille, mikä keisarin on, ja Jumalalle, mikä Jumalan on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'Eivätkä he kyenneet saamaan häntä hänen puheestaan kiinni kansan edessä ja ihmettelivät hänen vastaustaan ja vaikenivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Muutamia saddukeuksia astui esiin, jotka väittävät, ettei ylösnousemusta ole, ja he kysyivät häneltä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'sanoen: \"Opettaja, Mooses on säätänyt meille: \'Jos joltakulta kuolee veli, jolla on vaimo, mutta ei ole lapsia, niin ottakoon hän veljensä vaimon ja herättäköön siemenen veljelleen.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Nyt oli seitsemän veljestä. Ensimmäinen otti vaimon ja kuoli lapsettomana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'Niin toinen otti sen vaimon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'ja sitten kolmas, ja samoin kaikki seitsemän; ja he kuolivat jättämättä lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Lopulta he kaikki kuolivat ja niin myös vaimo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Kenelle heistä siis tämä vaimo ylösnousemuksessa tulee vaimoksi? Sillä kaikkien seitsemän vaimona hän oli ollut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Jeesus sanoi heille: \"Tämän maailmanajan lapset naivat ja menevät miehelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'Mutta ne, jotka on arvollisiksi nähty pääsemään tuohon maailmaan ja ylösnousemukseen kuolleista, eivät nai eivätkä mene miehelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'Sillä he eivät enää voi kuolla, kun ovat enkelien kaltaisia. He ovat Jumalan lapsia, koska ovat ylösnousemuksen lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Mutta että kuolleet nousevat ylös, sen Mooseskin on osoittanut puhuessaan orjantappurapensaasta, kun hän sanoo Herraa Aabrahamin Jumalaksi ja Iisakin Jumalaksi ja Jaakobin Jumalaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Mutta Jumala ei ole kuolleiden, vaan elävien Jumala; sillä kaikki elävät hänelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Muutamat kirjanoppineista vastasivat ja sanoivat: \"Opettaja, hyvin sanoit.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Eivätkä he enää rohjenneet kysyä häneltä mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Hän sanoi heille: \"Kuinka he sanovat, että Kristus on Daavidin poika?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'Sanoohan Daavid itse Psalmien kirjassa: \'Herra sanoi Herralleni: Istu oikealle puolelleni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'kunnes panen vihollisesi jalkojesi astinlaudaksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'Daavid siis kutsuu häntä Herraksi. Miten hän on hänen poikansa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Kaiken kansan kuullen hän sanoi opetuslapsilleen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, '\"Kavahtakaa kirjanoppineita, jotka tahtovat kulkea pitkissä viitoissa ja haluavat tervehdyksiä toreilla, etumaisia istuimia synagogissa ja ensimmäisiä sijoja pidoissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'noita, jotka syövät leskien talot ja näön vuoksi pitävät pitkiä rukouksia. He saavat sitä kovemman tuomion.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Hän katseli ja näki rikkaiden panevan lahjoja uhriarkkuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Hän näki myös köyhän lesken panevan siihen kaksi ropoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'Hän sanoi: \"Totisesti sanon teille: tämä köyhä leski pani kaikkein eniten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Sillä kaikki nuo panivat lahjansa liiastaan, mutta tämä pani puutteestaan, koko elämisensä, mitä hänellä oli.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'Kun muutamat puhuivat pyhäköstä, kuinka se oli kauniilla kivillä ja esille pannuilla lahjoilla kaunistettu, hän sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, '\"Päivät tulevat, jolloin tästä, mitä katselette, ei jää kiveä kiven päälle, maahan hajottamatta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'He kysyivät häneltä sanoen: \"Opettaja, milloin tämä sitten tapahtuu? Mikä on oleva merkki siitä, kun se tulee tapahtumaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Hän sanoi: \"Katsokaa, ettei teitä eksytetä. Sillä monta tulee minun nimessäni sanoen: \' Minä olen \', ja: \'Aika on lähellä.\' Mutta älkää menkö heidän perässään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Kun kuulette sodista ja kapinoista, älkää pelästykö. Sillä näiden täytyy ensin tapahtua, mutta se ei ole heti loppu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Hän sanoi heille: \"Kansa nousee kansaa vastaan ja valtakunta valtakuntaa vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'ja tulee paikoin suuria maanjäristyksiä, ruttoa ja nälänhätää, ja on oleva pelottavia näkyjä ja taivaalta tulevia suuria merkkejä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Mutta ennen tätä kaikkea he käyvät teihin käsiksi, vainoavat teitä, luovuttavat teitä synagogiin ja vankiloihin ja vievät teitä kuningasten ja hallitsijoiden eteen minun nimeni tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'Mutta näin te joudutte todistamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Pankaa siis sydämellenne, ettette edeltäpäin huolehdi, miten vastaatte puolestanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'Sillä minä annan teille suun ja viisauden, jota vastaan ei yksikään teidän vastustajistanne kykene asettumaan tai väittämään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Myös vanhemmat, veljet, sukulaiset ja ystävät antavat teitä alttiiksi, muutamia teistä tapetaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'ja olette kaikkien vihaamia minun nimeni tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Mutta hiuskarvakaan ei katoa päästänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'Kestäväisyydellänne saatte omaksenne elämän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Mutta kun näette Jerusalemin sotajoukkojen ympäröimänä, silloin tietäkää, että sen hävitys on lähellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Silloin ne, jotka Juudeassa ovat, paetkoot vuorille, ne, jotka ovat kaupungissa, lähtekööt sieltä pois, ja ne, jotka ovat maalla, älkööt menkö kaupunkiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Sillä ne ovat koston päiviä, että kaikki täyttyisi, mikä on kirjoitettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Voi raskaita ja imettäväisiä niinä päivinä! Sillä suuri hätä on oleva maan päällä ja viha tätä kansaa kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'Heitä kaatuu miekan terään, heitä viedään vangeiksi kaikkien kansojen sekaan, ja Jerusalem on oleva pakanoiden tallattavana, kunnes pakanain ajat täyttyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'On oleva merkkejä auringossa, kuussa ja tähdissä, ja ahdistus kansoilla maan päällä ja epätoivo meren aaltoillessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'Ihmisiä menehtyy heidän pelätessään ja odottaessaan sitä, mikä maanpiiriä kohtaa; sillä taivaitten voimat järkkyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Silloin he näkevät Ihmisen Pojan tulevan pilvessä suuressa voimassa ja kirkkaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Mutta kun nämä alkavat tapahtua, nouskaa pystyyn ja nostakaa päänne, sillä teidän vapautuksenne on lähellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'Hän puhui heille vertauksen: \"Katsokaa viikunapuuta ja kaikkia puita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'Kun ne jo puhkeavat lehteen, siitä näette ja itsestänne ymmärrätte, että kesä on jo lähellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Samoin myös, kun näette tämän tapahtuvan, tietäkää, että Jumalan valtakunta on lähellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Totisesti sanon teille: tämä sukukunta ei katoa, ennen kuin kaikki tapahtuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Taivas ja maa katoavat, mutta minun sanani eivät katoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Mutta pitäkää vaari itsestänne, ettei teidän sydämiänne raskauta päihtymys ja juoppous eivätkä elatuksen murheet, että se päivä yllättää teidät äkkiarvaamatta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'kuin ansa; sillä se saavuttaa kaikki, jotka koko maan päällä asuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Valvokaa siis joka aika ja rukoilkaa, että teidät katsottaisiin arvollisiksi pakenemaan tätä kaikkea, mikä on tuleva, ja seisoaksenne Ihmisen Pojan edessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Hän opetti päivät pyhäkössä, mutta öiksi hän lähti pois ja vietti ne vuorella, jota sanotaan Öljymäeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'Kaikki kansa tuli varhain hänen luokseen pyhäkköön kuulemaan häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Mutta happamattoman leivän juhla, jota sanotaan pääsiäiseksi, oli lähellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Ylipapit ja kirjanoppineet miettivät, kuinka saisivat hänet surmatuksi, sillä he pelkäsivät kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Saatana meni Juudakseen, jota kutsuttiin Iskariotiksi ja joka oli yksi niistä kahdestatoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'Tämä meni ja puhui ylipappien ja pyhäkön vartioston päällikköjen kanssa, miten hän kavaltaisi hänet heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'He ihastuivat ja sitoutuivat antamaan hänelle rahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'Hän lupautui ja etsi sopivaa tilaisuutta kavaltaakseen hänet heille kansan tietämättä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Tuli se happamattoman leivän päivistä, jona pääsiäislammas tulee teurastaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Hän lähetti Pietarin ja Johanneksen sanoen: \"Menkää ja valmistakaa meille pääsiäislammas syödäksemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'He kysyivät häneltä: \"Mihin tahdot, että valmistamme sen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Hän vastasi heille: \"Katso, saapuessanne kaupunkiin tulee teitä vastaan mies kantaen vesiastiaa. Seuratkaa häntä siihen taloon, johon hän menee,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'ja sanokaa talon isännälle: \'Opettaja sanoo sinulle: Missä on vierashuone syödäkseni siinä pääsiäislampaan opetuslasteni kanssa?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Hän näyttää teille suuren, aterioiville kalustetun huoneen yläkerrassa. Sinne valmistakaa!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'He menivät ja havaitsivat niin olevan, kuin Jeesus oli heille sanonut, ja valmistivat pääsiäislampaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Kun hetki tuli, hän asettui aterialle ja apostolit hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Hän sanoi heille: \"Olen hartaasti halunnut syödä tämän pääsiäislampaan teidän kanssanne ennen kärsimystäni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'sillä sanon teille, etten sitä enää syö, ennen kuin sen täyttymys tapahtuu Jumalan valtakunnassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'Hän otti maljan, kiitti ja sanoi: \"Ottakaa tämä ja jakakaa keskenänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Sillä sanon teille: tästedes en juo viinipuun antia, ennen kuin Jumalan valtakunta tulee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Hän otti leivän, kiitti, mursi ja antoi heille ja sanoi: \"Tämä on minun ruumiini, joka teidän edestänne annetaan. Tehkää se minun muistokseni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Samoin myös maljan, aterian jälkeen, ja sanoi: \"Tämä malja on uusi liitto minun veressäni, joka teidän edestänne vuodatetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Mutta, katso, kavaltajani käsi on kanssani pöydällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Sillä Ihmisen Poika tosin menee pois, kuten on säädetty, mutta voi sitä ihmistä, jonka kautta hänet kavalletaan!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'He rupesivat keskenään kyselemään, kuka heistä mahtoi olla se, joka sen tekee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Mutta heidän välilleen syntyi myös kiista siitä, kuka heistä oli katsottava suurimmaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Hän sanoi heille: \"Kansojen kuninkaat hallitsevat niitä herroina, ja niiden vallanpitäjiä sanotaan hyväntekijöiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Mutta älkää te niin, vaan se, joka teidän keskuudessanne on suurin, olkoon kuin nuorin, ja johtaja kuin se, joka palvelee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Sillä kumpi on suurempi, se, joka aterioi, vai se, joka palvelee? Eikö se, joka aterioi? Mutta minä olen teidän keskellänne kuin se, joka palvelee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Mutta te olette pysyneet minun kanssani kiusauksissani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'ja minä säädän teille, niin kuin minun Isäni on minulle säätänyt, valtakunnan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'että syötte ja juotte minun pöydässäni valtakunnassani, istutte valtaistuimilla ja tuomitsette Israelin kahtatoista sukukuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Simon, Simon, katso, saatana on pyrkinyt seulomaan teitä kuin vehnänjyviä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'mutta minä olen rukoillut sinun puolestasi, ettei sinun uskosi lakkaisi. Kun sinä kerran palaat, vahvista veljiäsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'Simon sanoi hänelle: \"Herra, sinun kanssasi olen valmis menemään sekä vankilaan että kuolemaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'Mutta hän sanoi: \"Minä sanon sinulle, Pietari: ei laula tänään kukko, ennen kuin sinä kolmesti kiellät tuntevasi minut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'Hän sanoi heille: \"Kun lähetin teidät ilman rahakukkaroa, laukkua ja sandaaleja, puuttuiko teiltä mitään?\" He vastasivat: \"Ei mitään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Hän sanoi heille: \"Mutta nyt, se, jolla on kukkaro, ottakoon sen mukaansa, samoin laukun. Se, jolla ei ole, myyköön viittansa ja ostakoon miekan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Sillä sanon teille, että minussa pitää käydä toteen tämän, mikä on kirjoitettu: \'Hänet luettiin ryövärien joukkoon.\' Sillä se, mikä minusta on sanottu, täyttyy nyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'He sanoivat: \"Herra, katso, tässä on kaksi miekkaa.\" Mutta hän vastasi heille: \"Riittää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'Hän meni ulos ja lähti tapansa mukaan Öljymäelle, ja hänen opetuslapsensa seurasivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Tultuaan siihen paikkaan hän sanoi heille: \"Rukoilkaa, ettette joutuisi kiusaukseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'Hän vetäytyi heistä noin kivenheiton päähän, laskeutui polvilleen ja rukoili');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'sanoen: \"Isä, jos tahdot, ota pois minulta tämä malja. Älköön kuitenkaan tapahtuko minun tahtoni, vaan sinun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Hänelle ilmestyi taivaasta enkeli, joka vahvisti häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'Kun hän oli suuressa tuskassa, hän rukoili yhä hartaammin. Ja hänen hikensä putosi maahan veripisaroina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'Kun hän nousi rukoilemasta ja meni opetuslastensa luo, hän tapasi heidät murheen tähden nukkumasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'Hän sanoi heille: \"Miksi nukutte? Nouskaa ja rukoilkaa, ettette joutuisi kiusaukseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Katso, hänen vielä puhuessaan tuli joukko kansaa, ja yksi niistä kahdestatoista, se, jonka nimi oli Juudas, kulki heidän edellään. Hän tuli Jeesuksen luo tervehtimään häntä suudelmalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Mutta Jeesus sanoi hänelle: \"Juudas, suudelmallako sinä Ihmisen Pojan kavallat?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Kun nyt ne, jotka olivat hänen ympärillään, näkivät, mitä oli tulossa, he sanoivat: \"Herra, iskemmekö miekalla?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'Eräs heistä iski ylipapin palvelijaa ja sivalsi häneltä pois oikean korvan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Mutta Jeesus vastasi sanoen: \"Sallikaa vielä tämäkin.\" Hän koski hänen korvaansa ja paransi hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Niin Jeesus sanoi ylipapeille ja temppelivartioston päälliköille ja vanhimmille, jotka olivat tulleet häntä vastaan: \"Niin kuin ryöväriä vastaan olette lähteneet miekkojen ja seipäitten kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Olen joka päivä ollut teidän kanssanne pyhäkössä, ettekä ole ojentaneet käsiänne minua vastaan. Mutta tämä on teidän hetkenne ja pimeyden valta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'He ottivat hänet kiinni, kuljettivat pois ja veivät hänet ylipapin taloon, mutta Pietari seurasi etäältä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'He sytyttivät tulen keskelle esipihaa ja asettuivat yhdessä istumaan, ja Pietari istui heidän joukkoonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Eräs palvelustyttö nähdessään hänen istuvan tulen ääressä, katsoi häneen ja sanoi: \"Tämäkin oli hänen kanssaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Mutta hän kielsi hänet sanoen: \"Nainen, en tunne häntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'Hetken kuluttua hänet näki toinen, eräs mies, ja sanoi: \"Sinäkin olet yksi heistä.\" Mutta Pietari sanoi: \"Mies, en ole.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'Noin tunnin kuluttua vakuutti vielä eräs toinen sanoen: \"Totisesti, tämä oli myös hänen kanssaan; sillä onhan hän galilealainenkin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Mutta Pietari sanoi: \"Mies, en ymmärrä, mitä sanot.\" Samassa hänen vielä puhuessaan lauloi kukko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'Herra kääntyi ja katsoi Pietariin, ja Pietari muisti Herran sanat, kuinka hän oli hänelle sanonut: \"Ennen kuin kukko tänään laulaa, sinä kiellät minut kolmesti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'Ja hän meni ulos ja itki katkerasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Miehet, jotka pitivät Jeesuksesta kiinni, pilkkasivat häntä ja löivät häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'He peittivät hänen kasvonsa ja kysyivät häneltä sanoen: \"Profetoi, kuka sinua löi!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Paljon muitakin herjauksia he puhuivat häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'Päivän koittaessa kansan vanhimmat, ylipapit ja kirjanoppineet kokoontuivat ja veivät hänet Neuvostonsa eteen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'ja sanoivat: \"Jos sinä olet Kristus, sano se meille.\" Hän vastasi heille: \"Jos teille sanon, ette usko;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'ja jos kysyn, ette vastaa tai vapauta minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Mutta tästedes Ihmisen Poika on istuva Jumalan voiman oikealla puolella.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'He kaikki sanoivat: \"Sinä siis olet Jumalan Poika?\" Hän vastasi heille: \"Te sen sanotte, että Minä olen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'He sanoivat: \"Mitä todistusta enää tarvitsemme? Sillä olemme itse kuulleet sen hänen omasta suustaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'He, koko joukko, nousivat ja veivät hänet Pilatuksen eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'He alkoivat syyttää häntä sanoen: \"Olemme havainneet tämän villitsevän kansaamme, kieltävän antamasta veroja keisarille ja sanovan itseään Kristukseksi, kuninkaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Pilatus kysyi häneltä sanoen: \"Oletko sinä juutalaisten kuningas?\" Hän vastasi hänelle ja sanoi: \"Sinä sen sanot.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Pilatus sanoi ylipapeille ja kansalle: \"En löydä mitään syytä tästä miehestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Mutta he ahdistivat yhä enemmän ja sanoivat: \"Hän yllyttää kansaa opettaen kaikkialla Juudeassa, Galileasta alkaen tänne asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Mutta kun Pilatus kuuli mainittavan Galilean, hän kysyi, oliko mies galilealainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'Saatuaan tietää hänen olevan Herodeksen hallintoalueelta hän lähetti hänet Herodeksen eteen, joka hänkin oli niinä päivinä Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Kun Herodes näki Jeesuksen, hän ilahtui suuresti. Hän oli näet jo kauan aikaa halunnut nähdä hänet, koska oli kuullut hänestä, ja toivoi saavansa nähdä häneltä jonkin merkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Hän teki Jeesukselle monia kysymyksiä, mutta tämä ei vastannut hänelle mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Ylipapit ja kirjanoppineet seisoivat siinä ja syyttivät häntä kiivaasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Mutta Herodes joukkoineen kohteli häntä halveksivasti ja pilkkasi häntä. Puettuaan hänet loistavaan pukuun hän lähetti hänet takaisin Pilatuksen eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'Herodes ja Pilatus ystävystyivät sinä päivänä keskenään. He olivat näet ennen olleet toistensa vihamiehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Pilatus kutsui kokoon ylipapit, hallitusmiehet ja kansan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'ja sanoi heille: \"Te olette tuoneet minulle tämän miehen kansan yllyttäjänä. Katso, minä olen teidän läsnä ollessanne häntä tutkinut enkä ole havainnut tätä miestä syylliseksi mihinkään, mistä te häntä syytätte,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'eikä Herodeskaan, sillä hän lähetti hänet takaisin meille. Katso, hän ei ole tehnyt mitään, mikä ansaitsee kuoleman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Kuritettuani häntä siis hänet päästän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'Mutta hänen piti kunakin juhlana päästää vapaaksi yksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'He huusivat kaikki yhdessä sanoen: \"Vie tämä pois, mutta päästä meille Barabbas!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Tämä oli heitetty vankilaan kaupungissa tehdystä kapinasta sekä murhasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Pilatus puhui taas heille, koska hän tahtoi vapauttaa Jeesuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Mutta he huusivat vastaan ja sanoivat: \"Ristiinnaulitse, ristiinnaulitse hänet!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'Hän puhui heille kolmannen kerran: \"Mitä pahaa hän sitten on tehnyt? En ole havainnut hänessä mitään, mistä hän ansaitsisi kuoleman. Kuritettuani häntä siis hänet päästän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Mutta he ahdistivat häntä suurilla huudoilla, vaatien Jeesusta ristiinnaulittavaksi, ja heidän ja ylipappien huudot pääsivät voitolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Pilatus tuomitsi heidän vaatimuksensa täytettäväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'Hän päästi heille irti sen, joka oli heitetty vankilaan kapinasta ja murhasta ja jota he vaativat, mutta Jeesuksen hän luovutti heidän tahtoonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Viedessään häntä pois he saivat käsiinsä Simonin, erään kyreneläisen, joka tuli pellolta, ja panivat ristin hänen kannettavakseen Jeesuksen jäljessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Häntä seurasi suuri joukko kansaa, myös naisia, jotka valittivat ja itkivät häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Jeesus kääntyi heihin ja sanoi: \"Jerusalemin tyttäret, älkää minua itkekö, vaan itkekää itseänne ja lapsianne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Sillä katso, päivät tulevat, jolloin sanotaan: \'Autuaita ovat hedelmättömät ja ne kohdut, jotka eivät ole synnyttäneet, ja rinnat, jotka eivät ole imettäneet.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Silloin aletaan sanoa vuorille: \'Langetkaa päällemme\', ja kukkuloille: \'Peittäkää meidät.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Sillä jos tämä tehdään tuoreelle puulle, mitä kuivalle tapahtuu?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Myös kaksi muuta, kaksi pahantekijää, vietiin hänen kanssaan surmattaviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Kun saavuttiin paikalle, jota sanotaan Pääkallonpaikaksi, siellä he ristiinnaulitsivat hänet sekä pahantekijät, toisen oikealle ja toisen vasemmalle puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Mutta Jeesus sanoi: \"Isä, anna heille anteeksi, sillä he eivät tiedä, mitä tekevät.\" He jakoivat keskenään hänen vaatteensa heittäen niistä arpaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Kansa seisoi ja katseli. Hallitusmiehetkin ivasivat häntä heidän kanssaan ja sanoivat: \"Muita hän on auttanut. Auttakoon itseään, jos hän on Kristus, Jumalan valittu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Myös sotamiehet pilkkasivat häntä, menivät hänen luokseen ja tarjosivat hänelle hapanviiniä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'ja sanoivat: \"Jos sinä olet juutalaisten kuningas, pelasta itsesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Hänen päänsä päällä oli myös kreikkalaisin, roomalaisin ja heprealaisin kirjaimin kirjoitus: \"Tämä on juutalaisten kuningas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Toinen pahantekijöistä, jotka siinä riippuivat, herjasi häntä: \"Jos olet Kristus, pelasta itsesi ja meidät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Mutta toinen vastasi ja nuhteli häntä sanoen: \"Etkö pelkää Jumalaa, sinä, joka olet saman rangaistuksen alainen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Me tosin kärsimme oikeuden mukaan, sillä saamme, mitä tekomme ansaitsevat, mutta tämä ei ole tehnyt mitään pahaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'Hän sanoi: \"Jeesus, muista minua, kun tulet valtakuntaasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'Jeesus sanoi hänelle: \"Totisesti sanon sinulle: tänä päivänä pitää sinun olla minun kanssani paratiisissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Oli jo noin kuudes tunti. Yli koko maan tuli pimeys, jota kesti yhdeksänteen tuntiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'sillä aurinko oli pimentynyt. Temppelin esirippu repesi keskeltä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'ja Jeesus huusi suurella äänellä ja sanoi: \"Isä, sinun käsiisi annan henkeni.\" Sen sanottuaan hän antoi henkensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Mutta kun sadanpäällikkö näki, mitä tapahtui, hän kunnioitti Jumalaa ja sanoi: \"Totisesti, tämä oli vanhurskas mies.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Kun kaikki kansa, ne, jotka olivat kokoontuneet tätä katselemaan, näkivät, mitä tapahtui, he löivät rintaansa ja palasivat kukin kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Mutta kaikki hänen tuttavansa seisoivat taaempana, myös naiset, jotka olivat seuranneet häntä Galileasta, ja katselivat tätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'Katso, oli Neuvoston jäsen, nimeltä Joosef, hyvä ja vanhurskas mies, joka ei antanut suostumustaan heidän päätökselleen ja teolleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, 'Tämä oli kotoisin juutalaisten kaupungista Arimatiasta, ja hän odotti Jumalan valtakuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Hän meni Pilatuksen luo ja pyysi Jeesuksen ruumista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'Otettuaan sen alas hän kääri sen pellavavaatteeseen ja pani sen hautaan, joka oli hakattu kallioon ja johon ei ollut vielä pantu ketään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'Silloin oli valmistuspäivä, ja sapatti oli alkamaisillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Mutta naiset, jotka olivat tulleet hänen kanssaan Galileasta, seurasivat jäljessä ja katselivat hautaa ja kuinka hänen ruumiinsa pantiin sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Palattuaan kotiinsa he valmistivat hyvänhajuisia yrttejä ja voiteita, mutta sapatin he viettivät hiljaisuudessa lain käskyn mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'Mutta viikon ensimmäisenä päivänä he ja eräitä muita naisia tuli hyvin varhain haudalle tuoden mukanaan valmistamansa hyvänhajuiset yrtit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'He huomasivat kiven vieritetyksi pois haudalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'He menivät sisälle, mutta eivät löytäneet Herran Jeesuksen ruumista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'Tapahtui, että kun he olivat tästä ymmällä, katso, kaksi miestä seisoi heidän edessään säteilevissä vaatteissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'He pelästyivät ja kumartuivat kasvoilleen maahan. Miehet sanoivat heille: \"Miksi etsitte elävää kuolleiden joukosta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Ei hän ole täällä, hän on noussut ylös. Muistakaa, kuinka hän puhui teille vielä ollessaan Galileassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'sanoen: \'Ihmisen Poika pitää antaa syntisten ihmisten käsiin ja ristiinnaulita ja kolmantena päivänä hän on nouseva ylös.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'He muistivat hänen sanansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'Ja he palasivat haudalta ja ilmoittivat tämän kaiken niille yhdelletoista ja kaikille muille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Ne, jotka kertoivat tämän apostoleille, olivat Maria Magdaleena, Johanna ja Maria, Jaakobin äiti, sekä muut naiset heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Mutta näiden puheet näyttivät heistä turhilta, eivätkä he uskoneet heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Mutta Pietari nousi, juoksi haudalle ja kun hän kurkisti sisään, hän näki siellä olevan ainoastaan käärinliinat. Hän meni pois ihmetellen mielessään, mitä oli tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'Katso, kaksi heistä kulki sinä päivänä Emmaus-nimiseen kylään, joka on kuudenkymmenen stadionin päässä Jerusalemista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'He keskustelivat kaikesta tästä, mitä oli tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'Heidän keskustellessaan ja tutkistellessaan tapahtui, että Jeesus itse lähestyi heitä ja liittyi kulkemaan heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Mutta heidän silmänsä olivat estetyt, niin etteivät he tunteneet häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Hän sanoi heille: \"Mistä te kävellessänne puhutte keskenänne ja miksi olette murheellisia?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Toinen heistä, nimeltä Kleopas, vastasi ja sanoi hänelle: \"Oletko sinä ainoa muukalainen Jerusalemissa, joka et tiedä, mitä siellä näinä päivinä on tapahtunut?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'Hän sanoi heille: \"Mitä?\" Niin he sanoivat hänelle: \"Sitä, mikä tapahtui Jeesukselle, Nasaretilaiselle, joka oli profeetta, voimallinen teossa ja sanassa Jumalan ja kaiken kansan edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'kuinka meidän ylipappimme ja hallitusmiehemme antoivat hänet tuomittavaksi kuolemaan ja ristiinnaulitsivat hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Mutta me toivoimme hänen olevan sen, joka oli lunastava Israelin. Onhan kaiken tämän lisäksi nyt jo kolmas päivä siitä, kun nämä tapahtuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Ovatpa vielä muutamat naiset joukostamme saattaneet meidät hämmästyksiin. He menivät aamulla varhain haudalle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'eivätkä löytäneet hänen ruumistaan, ja tulivat ja sanoivat myös nähneensä enkelinäyn, ja enkelit olivat sanoneet hänen elävän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'Muutamat niistä, jotka olivat kanssamme, menivät haudalle ja havaitsivat niin olevan, kuin naiset olivat sanoneet, mutta häntä he eivät nähneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Hän sanoi heille: \"Oi, te ymmärtämättömät ja hitaat sydämeltä uskomaan kaiken sen, minkä profeetat ovat puhuneet!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Eikö Kristuksen pitänyt tätä kärsimän ja menemän kirkkauteensa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'Hän alkoi Mooseksesta ja kaikista profeetoista ja selitti heille, mitä hänestä oli kaikissa Kirjoituksissa sanottu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Kun he lähestyivät kylää, johon olivat menossa, niin hän oli kulkevinaan edemmäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Mutta he vaativat häntä sanoen: \"Jää luoksemme, sillä on jo ilta ja päivä on jo laskenut.\" Hän meni sisään ja jäi heidän luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'Tapahtui, kun hän oli aterialla heidän kanssaan, että hän otti leivän, siunasi, mursi ja antoi heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Heidän silmänsä aukenivat, ja he tunsivat hänet, ja hän katosi heidän näkyvistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'He sanoivat toisilleen: \"Eikö sydämemme ollut meissä palava, kun hän puhui meille tiellä ja avasi meille Kirjoitukset?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'He nousivat sillä hetkellä ja palasivat Jerusalemiin ja tapasivat ne yksitoista kokoontuneina ja ne, jotka olivat heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'He sanoivat: \"Herra on totisesti noussut ylös ja on ilmestynyt Simonille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'He kertoivat, mitä oli tapahtunut tiellä ja kuinka he olivat tunteneet hänet, kun hän mursi leivän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Mutta heidän tätä puhuessaan Jeesus itse seisoi heidän keskellään ja sanoi heille: \"Rauha teille!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Heidät valtasi säikähdys ja pelko, ja he luulivat näkevänsä hengen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Mutta hän sanoi heille: \"Miksi olette hämmästyneet, ja miksi nousee sellaisia ajatuksia sydämiinne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Katsokaa käsiäni ja jalkojani ja nähkää, että minä itse [tässä] olen. Kosketelkaa minua ja katsokaa, sillä ei hengellä ole lihaa eikä luita, niin kuin te näette minulla olevan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'Tämän sanottuaan hän näytti heille kätensä ja jalkansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Mutta kun he eivät vielä uskoneet, ilon tähden, vaan ihmettelivät, hän sanoi heille: \"Onko teillä täällä jotakin syötävää?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'He antoivat hänelle palan paistettua kalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'Hän otti sen ja söi heidän nähtensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Hän sanoi heille: \"Tätä tarkoittivat minun sanani, jotka puhuin teille ollessani vielä kanssanne, että kaiken pitää käydä toteen, mikä minusta on kirjoitettu Mooseksen Laissa ja Profeetoissa ja Psalmeissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Silloin hän avasi heidän ymmärryksensä käsittämään Kirjoitukset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'Hän sanoi heille: \"Niin on kirjoitettu, ja näin Kristuksen piti kärsiä ja kolmantena päivänä nousta kuolleista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'ja että mielenmuutosta syntien anteeksiantamiseksi on saarnattava hänen nimessään kaikille kansoille alkaen Jerusalemista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Te olette tämän todistajat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'Katso, minä lähetän teille sen, jonka minun Isäni on luvannut. Mutta te pysykää tässä kaupungissa, Jerusalemissa, kunnes päällenne puetaan voima korkeudesta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Hän vei heidät pois, ulkopuolelle Betaniaan asti, nosti kätensä ja siunasi heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'Tapahtui, että hän siunatessaan heitä loittoni heistä, ja hänet otettiin ylös taivaaseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'He kumarsivat häntä ja palasivat Jerusalemiin suuresti iloiten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'He olivat alati pyhäkössä kiittäen ja ylistäen Jumalaa. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Alussa oli Sana, ja Sana oli Jumalan luona, ja Sana oli Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Hän oli alussa Jumalan luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Kaikki on saanut syntynsä hänen kauttaan, ja ilman häntä ei ole syntynyt mitään, mikä on syntynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'Hänessä oli elämä, ja elämä oli ihmisten valkeus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Ja valkeus loistaa pimeydessä, mutta pimeys ei ottanut sitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Oli mies, Jumalan lähettämä. Hänen nimensä oli Johannes.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Hän tuli todistamaan todistaakseen valkeudesta, että kaikki uskoisivat hänen kauttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Hän ei ollut se valkeus, vaan hän tuli todistaakseen valkeudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Todellinen valkeus, joka valaisee jokaista ihmistä, oli tulossa maailmaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Maailmassa hän oli, ja maailma on hänen kauttaan saanut syntynsä, mutta maailma ei tuntenut häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Hän tuli omiensa luo, ja hänen omansa eivät ottaneet häntä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Mutta kaikille, jotka ottivat hänet vastaan, hän antoi vallan tulla Jumalan lapsiksi, niille, jotka uskovat hänen nimeensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'jotka eivät ole syntyneet verestä eivätkä lihan tahdosta eivätkä miehen tahdosta, vaan Jumalasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Sana tuli lihaksi ja asui keskellämme, ja katselimme hänen kirkkauttaan, sellaista kirkkautta, kuin Ainosyntyisellä on Isältä, ja hän oli täynnä armoa ja totuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Johannes todisti hänestä ja julisti sanoen: \"Tämä on se, josta sanoin: se, joka tulee minun jälkeeni, on ollut minun edelläni, sillä hän on ollut ennen kuin minä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Hänen täyteydestään me kaikki olemme saaneet, ja armoa armon sijaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Sillä laki on annettu Mooseksen kautta, armo ja totuus on tullut Jeesuksen Kristuksen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Jumalaa ei ole kukaan koskaan nähnyt. Ainosyntyinen Poika, joka on Isän helmassa, on hänet ilmoittanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Tämä on Johanneksen todistus, kun juutalaiset lähettivät hänen luokseen Jerusalemista pappeja ja leeviläisiä kysymään häneltä: \"Kuka sinä olet?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Hän tunnusti eikä kieltänyt, ja hän tunnusti: \"Minä en ole Kristus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'He kysyivät häneltä: \"Kuka sitten? Oletko sinä Elia?\" Hän sanoi: \"En ole.\" \"Se Profeettako olet?\" Hän vastasi: \"En.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'He sanoivat hänelle: \"Kuka olet, että voisimme antaa vastauksen niille, jotka meidät lähettivät? Mitä sanot itsestäsi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Hän sanoi: \"Minä olen airuen ääni erämaassa: \'Tehkää tie suoraksi Herralle\', kuten profeetta Jesaja on sanonut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Lähetetyt olivat fariseuksia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'ja he kysyivät häneltä ja sanoivat hänelle: \"Miksi sitten kastat, jos et ole Kristus etkä Elia etkä se Profeetta?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Johannes vastasi heille sanoen: \"Minä kastan vedellä, mutta teidän keskellänne seisoo hän, jota te ette tunne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'Hän on se, joka tulee minun jälkeeni ja jonka sandaalien nyörejä minä en ole arvollinen päästämään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Tämä tapahtui Beet-Baarassa, Jordanin tuolla puolella, jossa Johannes oli kastamassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Seuraavana päivänä hän näki Jeesuksen tulevan luokseen ja sanoi: \"Katso, Jumalan Karitsa, joka kantaa pois maailman synnin!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Tämä on se, josta minä sanoin: \'Minun jälkeeni tulee mies, joka on ollut edelläni, sillä hän on ollut ennen kuin minä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Minä en tuntenut häntä, mutta sitä varten, että hän tulisi julki Israelille, minä olen tullut vedellä kastamaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'Johannes todisti sanoen: \"Näin Hengen laskeutuvan taivaasta alas kyyhkysenä, ja hän jäi hänen päälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'Minä en tuntenut häntä, mutta hän, joka lähetti minut vedellä kastamaan, sanoi minulle: \'Se, jonka päälle sinä näet Hengen laskeutuvan ja jäävän, on se, joka kastaa Pyhällä Hengellä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Minä olen nähnyt sen ja olen todistanut, että tämä on Jumalan Poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Seuraavana päivänä Johannes taas seisoi siellä ja kaksi hänen opetuslapsistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'Luoden katseensa Jeesukseen, joka käveli siellä, hän sanoi: \"Katso, Jumalan Karitsa!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Ne kaksi opetuslasta kuulivat hänen näin puhuvan ja seurasivat Jeesusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Jeesus kääntyi ja nähdessään heidän seuraavan sanoi heille: \"Mitä etsitte?\" He vastasivat hänelle: \"Rabbi\" – se on käännettynä: opettaja – \"missä on majapaikkasi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Hän sanoi heille: \"Tulkaa ja katsokaa.\" He menivät ja näkivät, missä hän majaili, ja viipyivät hänen luonaan sen päivän. Silloin oli noin kymmenes tunti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Andreas, Simon Pietarin veli, oli toinen niistä kahdesta, jotka olivat kuulleet nämä Johannekselta ja seuranneet Jeesusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Hän tapasi ensin veljensä Simonin ja sanoi hänelle: \"Olemme löytäneet Messiaan\", se on käännettynä: Kristus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Hän vei hänet Jeesuksen luo. Jeesus kiinnitti katseensa häneen ja sanoi: \"Sinä olet Simon, Joonan poika. Nimesi on oleva Keefas\", joka käännettynä on Pietari.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'Seuraavana päivänä Jeesus tahtoi lähteä Galileaan, ja hän löysi Filippoksen ja sanoi hänelle: \"Seuraa minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Filippos oli Beetsaidasta, Andreaan ja Pietarin kaupungista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Filippos löysi Natanaelin ja sanoi hänelle: \"Olemme löytäneet sen, josta Mooses Laissa ja Profeetat ovat kirjoittaneet, Jeesuksen, Joosefin pojan, Nasaretista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Natanael sanoi hänelle: \"Voiko Nasaretista tulla mitään hyvää?\" Filippos sanoi hänelle: \"Tule ja katso.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Jeesus näki Natanaelin tulevan luokseen ja sanoi hänestä: \"Katso, oikea israelilainen, jossa ei ole vilppiä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Natanael sanoi hänelle: \"Mistä minut tunnet?\" Jeesus vastasi ja sanoi hänelle: \"Ennen kuin Filippos sinua kutsui, kun olit viikunapuun alla, näin sinut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Natanael vastasi ja sanoi hänelle: \"Rabbi, sinä olet Jumalan Poika, sinä olet Israelin kuningas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Jeesus vastasi ja sanoi hänelle: \"Sen tähden, että sanoin sinulle: \'näin sinut viikunapuun alla\', sinä uskot. Tulet näkemään suurempia, kuin nämä ovat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Hän sanoi hänelle: \"Totisesti, totisesti sanon teille: tästä lähtien näette taivaan avoinna ja Jumalan enkelien nousevan ylös ja laskeutuvan alas Ihmisen Pojan päälle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Kolmantena päivänä oli häät Galilean Kaanassa, ja Jeesuksen äiti oli siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Myös Jeesus ja hänen opetuslapsensa olivat kutsutut häihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Kun viini loppui, Jeesuksen äiti sanoi hänelle: \"Heillä ei ole viiniä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Jeesus sanoi hänelle: \"Nainen, mitä minulla on tekemistä kanssasi? Aikani ei ole vielä tullut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Hänen äitinsä sanoi palvelijoille: \"Mitä hän sanookin teille, se tehkää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Juutalaisten puhdistamistavan mukaan siinä oli kuusi kivistä vesiastiaa, kukin kahden tai kolmen mitan vetoinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Jeesus sanoi heille: \"Täyttäkää astiat vedellä.\" He täyttivät ne reunoja myöten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Hän sanoi heille: \"Ammentakaa nyt ja viekää pitovastaavalle.\" Ja he veivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Mutta kun pitovastaava maistoi vettä, joka oli muuttunut viiniksi, eikä tiennyt, mistä se oli tullut – mutta palvelijat, jotka veden olivat ammentaneet, tiesivät – kutsui pitovastaava yljän');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'ja sanoi hänelle: \"Jokainen panee ensin esille hyvän viinin ja sitten, kun ovat juoneet paljon, huonomman. Sinä olet säästänyt hyvän viinin tähän asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Tämän ensimmäisen tunnustekonsa Jeesus teki Galilean Kaanassa ja ilmoitti kirkkautensa, ja hänen opetuslapsensa uskoivat häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Sen jälkeen hän meni alas Kapernaumiin, hän ja hänen äitinsä, veljensä ja opetuslapsensa, mutta he eivät viipyneet siellä montakaan päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Juutalaisten pääsiäinen oli lähellä, ja Jeesus meni ylös Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Hän tapasi pyhäkössä ne, jotka myivät härkiä, lampaita ja kyyhkysiä, sekä rahanvaihtajat istumassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Hän teki nuorista ruoskan ja ajoi ulos pyhäköstä heidät kaikki lampaineen ja härkineen ja kaatoi vaihtajien rahat maahan ja työnsi heidän pöytänsä kumoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'Kyyhkysten myyjille hän sanoi: \"Viekää nämä täältä pois. Älkää tehkö Isäni huonetta markkinahuoneeksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Mutta hänen opetuslapsensa muistivat, että on kirjoitettu: \"Kiivaus sinun huoneesi puolesta kuluttaa minut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Juutalaiset vastasivat ja sanoivat hänelle: \"Minkä merkin näytät meille, koska näitä teet?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Jeesus vastasi ja sanoi heille: \"Hajottakaa maahan tämä temppeli, niin pystytän sen kolmessa päivässä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Juutalaiset sanoivat: \"Neljäkymmentä kuusi vuotta tätä temppeliä on rakennettu, ja sinäkö pystytät sen kolmessa päivässä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Mutta hän puhui ruumiinsa temppelistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Kun hän sitten oli noussut kuolleista, muistivat hänen opetuslapsensa, että hän oli tämän sanonut, ja he uskoivat Raamatun ja sen sanan, jonka Jeesus oli sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Kun hän oli Jerusalemissa pääsiäisenä, juhlan aikana, uskoivat monet hänen nimeensä nähdessään hänen tunnustekonsa, joita hän teki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Mutta Jeesus itse ei uskonut heille itseään, koska hän tunsi kaikki');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'eikä tarvinnut kenenkään todistusta ihmisestä, sillä hän tiesi itse, mitä ihmisessä oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Oli mies, fariseusten joukosta, nimeltä Nikodeemus, juutalaisten hallitusmiehiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Hän tuli yöllä Jeesuksen luo ja sanoi hänelle: \"Rabbi, tiedämme, että sinun opettajaksi tulemisesi on Jumalasta, sillä kukaan ei voi tehdä niitä tunnustekoja, joita sinä teet, ellei Jumala ole hänen kanssaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jeesus vastasi ja sanoi hänelle: \"Totisesti, totisesti sanon sinulle: joka ei synny ylhäältä, ei voi nähdä Jumalan valtakuntaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nikodeemus sanoi hänelle: \"Kuinka ihminen voi vanhana syntyä? Eihän hän voi jälleen mennä äitinsä kohtuun ja syntyä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Jeesus vastasi: \"Totisesti, totisesti sanon sinulle: jos joku ei synny vedestä ja Hengestä, hän ei voi päästä sisälle Jumalan valtakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Lihasta syntynyt on liha, ja Hengestä syntynyt on henki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Älä ihmettele, että sanoin sinulle: teidän täytyy syntyä ylhäältä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Tuuli puhaltaa, missä tahtoo, ja sinä kuulet sen äänen, mutta et tiedä, mistä se tulee ja minne se menee. Niin on jokaisen laita, joka on syntynyt Hengestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nikodeemus vastasi ja sanoi hänelle: \"Kuinka tämä voi tapahtua?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jeesus vastasi ja sanoi hänelle: \"Sinä olet Israelin opettaja etkä tätä tiedä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Totisesti, totisesti sanon sinulle: puhumme, mitä tiedämme, ja todistamme, mitä olemme nähneet, ettekä te ota vastaan todistustamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Jos ette usko, kun puhun teille maallisista, kuinka uskoisitte, jos puhun teille taivaallisista?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Ei kukaan ole noussut ylös taivaaseen, paitsi hän, joka taivaasta tuli alas, Ihmisen Poika, joka on taivaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Niin kuin Mooses ylensi käärmeen erämaassa, niin täytyy Ihmisen Poika ylentää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'jotta jokaisella, joka uskoo häneen, olisi iankaikkinen elämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Sillä niin on Jumala maailmaa rakastanut, että hän antoi ainosyntyisen Poikansa, ettei yksikään, joka häneen uskoo, joutuisi kadotukseen, vaan hänellä olisi iankaikkinen elämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Sillä ei Jumala lähettänyt Poikaansa maailmaan tuomitsemaan maailmaa, vaan sitä varten, että maailma pelastuisi hänen kauttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Sitä, joka uskoo häneen, ei tuomita. Mutta se, joka ei usko, on jo tuomittu, koska hän ei ole uskonut Jumalan ainosyntyisen Pojan nimeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Mutta tämä on tuomio, että valkeus on tullut maailmaan, ja ihmiset rakastivat pimeyttä enemmän kuin valkeutta, sillä heidän tekonsa olivat pahat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Sillä jokainen, joka tekee pahaa, vihaa valkeutta eikä tule valkeuteen, ettei hänen tekojaan nuhdeltaisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Mutta se, joka totuutta noudattaa, tulee valkeuteen, että hänen tekonsa tulisivat julki, sillä ne ovat Jumalassa tehdyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Sen jälkeen Jeesus meni opetuslapsineen Juudean maaseudulle ja oleskeli siellä heidän kanssaan ja kastoi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Mutta Johanneskin kastoi Ainonissa lähellä Salimia, koska siellä oli paljon vettä, ja ihmisiä tuli sinne kastettavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Sillä Johannesta ei ollut vielä heitetty vankeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Johanneksen opetuslapsille tuli kiistaa juutalaisten kanssa puhdistuksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'He tulivat Johanneksen luo ja sanoivat hänelle: \"Rabbi, se, joka oli kanssasi Jordanin tuolla puolella ja josta sinä olet todistanut, katso, hän kastaa, ja kaikki menevät hänen luokseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Johannes vastasi ja sanoi: \"Ihminen ei voi ottaa mitään, ellei sitä ole annettu hänelle taivaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Te itse todistatte minusta, että sanoin: minä en ole Kristus, vaan minut on lähetetty hänen edellään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Se, jolla on morsian, on ylkä. Mutta yljän ystävä, joka seisoo ja kuuntelee häntä, iloitsee suuresti yljän äänestä. Tämä minun iloni on nyt tullut täydelliseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Hänen tulee kasvaa, mutta minun vähetä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Hän, joka ylhäältä tulee, on yli kaikkien. Se, joka on maasta, on maasta, ja maasta on, mitä hän puhuu. Hän, joka taivaasta tulee, on yli kaikkien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'Sen, minkä hän on nähnyt ja kuullut, hän todistaa, mutta hänen todistustaan kukaan ei ota vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Se, joka ottaa vastaan hänen todistuksensa, vahvistaa sinetillä, että Jumala on totuudellinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Sillä hän, jonka Jumala on lähettänyt, puhuu Jumalan sanoja, sillä Jumala ei anna Henkeä mitalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Isä rakastaa Poikaa ja on antanut kaiken hänen käteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Sillä, joka uskoo Poikaan, on iankaikkinen elämä. Mutta se, joka ei ole kuuliainen Pojalle, ei ole elämää näkevä, vaan Jumalan viha pysyy hänen päällään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Kun nyt Herra sai tietää fariseusten kuulleen, että Jeesus teki opetuslapsiksi ja kastoi useampia kuin Johannes');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '– vaikka Jeesus ei itse kastanut, vaan hänen opetuslapsensa –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'hän jätti Juudean ja meni taas Galileaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Mutta hänen täytyi kulkea Samarian kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Niinpä hän tuli Syykar-nimiseen Samarian kaupunkiin, joka on lähellä Jaakobin pojalleen Joosefille antamaa maa-aluetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Siellä oli Jaakobin lähde. Kun nyt Jeesus oli matkasta väsynyt, hän istuutui lähteen reunalle. Oli noin kuudes tunti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Eräs Samarian nainen tuli ammentamaan vettä. Jeesus sanoi hänelle: \"Anna minulle juoda.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Sillä hänen opetuslapsensa olivat lähteneet kaupunkiin ostamaan ruokaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Samarialainen nainen sanoi hänelle: \"Kuinka sinä, joka olet juutalainen, pyydät juotavaa minulta, samarialaiselta naiselta?\" Sillä juutalaiset eivät seurustele samarialaisten kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jeesus vastasi ja sanoi hänelle: \"Jos tuntisit Jumalan lahjan, ja kuka se on, joka sinulle sanoo: \'Anna minulle juoda\', sinä pyytäisit häneltä, ja hän antaisi sinulle elävää vettä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Nainen sanoi hänelle: \"Herra, eihän sinulla ole ammennusastiaa, ja kaivo on syvä, mistä sitten olet saanut elävää vettä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Et kai sinä ole suurempi kuin isämme Jaakob, joka antoi meille tämän kaivon ja joi siitä, hän itse sekä hänen poikansa ja karjansa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jeesus vastasi ja sanoi hänelle: \"Jokaiselle, joka juo tätä vettä, tulee jälleen jano,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'mutta sille, joka juo sitä vettä, jota hänelle annan, ei tule koskaan jano, vaan se vesi, jonka hänelle annan, tulee hänessä sen veden lähteeksi, joka kumpuaa iankaikkiseen elämään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Nainen sanoi hänelle: \"Herra, anna minulle sitä vettä, ettei minun tulisi jano eikä minun tarvitsisi käydä täällä ammentamassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Jeesus sanoi hänelle: \"Mene, kutsu miehesi ja tule tänne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Nainen vastasi ja sanoi: \"Ei minulla ole miestä.\" Jeesus sanoi hänelle: \"Oikein sinä sanoit: \'Minulla ei ole miestä\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'sillä viisi miestä sinulla on ollut, ja se, joka sinulla nyt on, ei ole sinun miehesi. Siinä sanoit totuuden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Nainen sanoi hänelle: \"Herra, näen, että sinä olet profeetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Meidän isämme ovat kumartaen rukoilleet tällä vuorella, mutta te sanotte, että Jerusalemissa on se paikka, jossa tulee kumartaen rukoilla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Jeesus sanoi hänelle: \"Nainen, usko minua! Tulee aika, jolloin ette rukoile Isää tällä vuorella ettekä Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Te kumarratte sitä, mitä ette tunne. Me kumarramme sitä, minkä tunnemme. Sillä pelastus on juutalaisista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Mutta tulee aika ja on jo, jolloin totiset rukoilijat rukoilevat Isää hengessä ja totuudessa, sillä sellaisia rukoilijoita Isä etsii itselleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Jumala on henki, ja niiden, jotka häntä rukoilevat, tulee rukoilla hengessä ja totuudessa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Nainen sanoi hänelle: \"Tiedän, että Messias on tuleva, hän, jota sanotaan Kristukseksi. Kun hän tulee, hän ilmoittaa meille kaiken.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Jeesus sanoi hänelle: \" Minä olen, joka puhun kanssasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Silloin hänen opetuslapsensa tulivat ja ihmettelivät, että hän puhui naisen kanssa. Kuitenkaan kukaan ei sanonut: \"Mitä etsit?\" tai: \"Mitä puhelet hänen kanssaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Nainen jätti vesiastiansa ja meni kaupunkiin ja sanoi ihmisille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, '\"Tulkaa katsomaan miestä, joka on sanonut minulle kaikki, mitä olen tehnyt. Eihän hän vain ole Kristus?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'He lähtivät kaupungista ja tulivat hänen luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Sillä välin opetuslapset pyysivät häntä sanoen: \"Rabbi, syö!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Mutta hän sanoi heille: \"Minulla on syötävänä ruokaa, josta te ette tiedä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Opetuslapset sanoivat keskenään: \"Onko joku tuonut hänelle syötävää?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Jeesus sanoi heille: \"Minun ruokani on se, että teen lähettäjäni tahdon ja täytän hänen tekonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Ettekö sano: \'Vielä on neljä kuukautta, niin on elonleikkuun aika\'? Katso, sanon teille: nostakaa silmänne ja katselkaa vainioita, kuinka ne ovat valjenneet leikattaviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Jo nyt leikkaaja saa palkan ja kokoaa hedelmää iankaikkiseen elämään, että kylväjä ja leikkaaja saisivat iloita yhdessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Sillä tässä on tosi se sana, että toinen on kylväjä, ja leikkaaja toinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Minä olen lähettänyt teidät leikkaamaan sitä, mistä te ette ole vaivaa nähneet. Toiset ovat vaivan nähneet, ja te olette päässeet heidän vaivansa hedelmille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Monet samarialaiset siitä kaupungista uskoivat häneen naisen puheen tähden, kun tämä todisti: \"Hän on sanonut minulle kaikki, mitä olen tehnyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Kun nyt samarialaiset tulivat hänen luokseen, he pyysivät häntä viipymään heidän luonaan, ja hän viipyi siellä kaksi päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'Vielä paljon useammat uskoivat Jeesuksen sanan tähden,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'ja he sanoivat naiselle: \"Emme enää usko sinun puheesi tähden, sillä olemme itse kuulleet ja tiedämme, että tämä totisesti on maailman Vapahtaja, Kristus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Mutta niiden kahden päivän kuluttua hän lähti sieltä Galileaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Sillä Jeesus itse todisti, ettei profeettaa kunnioiteta isiensä maassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Kun hän siis tuli Galileaan, ottivat galilealaiset hänet vastaan, koska olivat nähneet kaiken, mitä hän oli tehnyt Jerusalemissa juhlan aikana, sillä hekin olivat tulleet juhlille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Hän tuli taas Galilean Kaanaan, jossa hän oli tehnyt veden viiniksi. Kapernaumissa oli eräs kuninkaan virkamies, jonka poika sairasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Kun hän kuuli Jeesuksen tulleen Juudeasta Galileaan, hän meni hänen luokseen ja pyysi häntä tulemaan ja parantamaan pojan, sillä tämä oli kuolemaisillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Jeesus sanoi hänelle: \"Ellette näe merkkejä ja ihmeitä, ette usko.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Kuninkaan virkamies sanoi hänelle: \"Herra, tule, ennen kuin lapseni kuolee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Jeesus sanoi hänelle: \"Mene, poikasi elää.\" Mies uskoi sanan, jonka Jeesus sanoi hänelle, ja meni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Kun hän oli jo paluumatkalla, hänen palvelijansa kohtasivat hänet ja sanoivat, että hänen poikansa eli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Hän tiedusteli heiltä, millä hetkellä hän oli alkanut toipua. He sanoivat hänelle: \"Eilen seitsemännellä tunnilla kuume lähti hänestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Isä ymmärsi, että se oli tapahtunut sillä hetkellä, jolloin Jeesus oli sanonut hänelle: \"Poikasi elää.\" Hän uskoi, hän ja koko hänen perhekuntansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Tämä oli jo toinen tunnusteko, jonka Jeesus teki, tultuaan Juudeasta Galileaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Sen jälkeen oli juutalaisten juhla, ja Jeesus meni ylös Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Jerusalemissa on Lammasportin luona lammikko, jonka nimi on hepreaksi Betesda, ja sen reunalla on viisi pylväskäytävää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'Niissä makasi suuri joukko sairaita, sokeita, rampoja ja kuivetustautisia, jotka odottivat veden liikuttamista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Sillä enkeli ajallaan astui alas lammikkoon ja kuohutti veden. Se, joka sitten veden kuohuttamisen jälkeen ensimmäisenä astui siihen, tuli terveeksi, sairastipa mitä tautia tahansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Siellä oli mies, joka oli sairastanut kolmekymmentä kahdeksan vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Kun Jeesus näki hänen makaavan siinä ja tiesi hänen jo kauan aikaa olleen sairaana, hän sanoi hänelle: \"Tahdotko tulla terveeksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Sairas vastasi hänelle: \"Herra, minulla ei ole ketään, joka veisi minut lammikkoon, kun vesi on kuohutettu. Kun minä olen menemässä, toinen menee sinne ennen minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Jeesus sanoi hänelle: \"Nouse, ota vuoteesi ja kävele.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Mies tuli heti terveeksi, otti vuoteensa ja käveli. Mutta tuo päivä oli sapatti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Sen tähden juutalaiset sanoivat parannetulle: \"On sapatti, sinun ei ole lupa kantaa vuodetta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Hän vastasi heille: \"Se, joka teki minut terveeksi, sanoi minulle: \'Ota vuoteesi ja kävele.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'He kysyivät häneltä: \"Kuka on se mies, joka sanoi sinulle: \'Ota vuoteesi ja kävele\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Mutta parannettu ei tiennyt, kuka se oli, sillä Jeesus oli poistunut, kun siinä paikassa oli paljon kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Sen jälkeen Jeesus tapasi hänet pyhäkössä ja sanoi hänelle: \"Katso, olet tullut terveeksi. Älä enää tee syntiä, ettei sinulle jotakin pahempaa tapahtuisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Mies meni ja ilmoitti juutalaisille, että Jeesus oli tehnyt hänet terveeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Sen tähden juutalaiset vainosivat Jeesusta, koska hän teki sellaista sapattina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Mutta Jeesus vastasi heille: \"Minun Isäni on tehnyt työtä alusta tähän asti, ja minä myös teen työtä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Sen tähden juutalaiset vielä enemmän tavoittelivat häntä tappaakseen, kun hän ei ainoastaan kumonnut sapattia, vaan myös sanoi Jumalaa Isäkseen tehden itsensä Jumalan vertaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Niin Jeesus vastasi ja sanoi heille: \"Totisesti, totisesti sanon teille: Poika ei voi tehdä itsestään mitään, vaan ainoastaan sen, minkä hän näkee Isän tekevän, sillä mitä Isä tekee, sitä myös Poika samoin tekee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Sillä Isä rakastaa Poikaa ja näyttää hänelle kaikki, mitä hän itse tekee, ja hän on näyttävä hänelle suurempia tekoja kuin nämä, niin että te ihmettelette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Sillä niin kuin Isä herättää kuolleita ja tekee eläviksi, myös Poika tekee eläviksi, ketkä tahtoo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Sillä Isä ei myöskään tuomitse ketään, vaan hän on antanut kaiken tuomion Pojalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'että kaikki kunnioittaisivat Poikaa, niin kuin he kunnioittavat Isää. Se, joka ei kunnioita Poikaa, ei kunnioita Isää, joka on lähettänyt hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Totisesti, totisesti sanon teille: joka kuulee minun sanani ja uskoo häneen, joka on minut lähettänyt, sillä on iankaikkinen elämä, eikä hän mene tuomiolle, vaan on siirtynyt kuolemasta elämään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Totisesti, totisesti sanon teille: aika tulee ja on jo, jolloin kuolleet kuulevat Jumalan Pojan äänen, ja niillä, jotka sen kuulevat, on iankaikkinen elämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Sillä niin kuin Isällä on elämä itsessään, niin hän on antanut elämän myös Pojalle, että myös hänellä on elämä itsessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'Hän on antanut hänelle vallan tuomita, koska hän on Ihmisen Poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Älkää ihmetelkö tätä, sillä hetki tulee, jolloin kaikki, jotka ovat haudoissa, kuulevat hänen äänensä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'ja tulevat esiin, ne, jotka ovat hyvää tehneet, elämän ylösnousemukseen, mutta ne, jotka ovat pahaa tehneet, tuomion ylösnousemukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Minä en voi itsestäni tehdä mitään. Niin kuin kuulen, niin tuomitsen. Tuomioni on oikea, sillä en kysy omaa tahtoani, vaan sen tahtoa, joka on minut lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Jos minä todistan itsestäni, todistukseni ei ole tosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'On toinen, joka todistaa minusta, ja tiedän, että se todistus, jonka hän minusta todistaa, on tosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Te lähetitte lähettiläät Johanneksen luo, ja hän todisti sen, mikä on totta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Mutta minä en ota vastaan todistusta ihmiseltä, vaan puhun tämän, että te pelastuisitte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Hän oli palava ja loistava lamppu, mutta te tahdoitte vain hetken ilotella hänen valossaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Mutta minulla on todistus, joka on suurempi kuin Johanneksen, sillä ne teot, jotka Isä on antanut minun täytettävikseni, ne teot, jotka minä teen, todistavat minusta, että Isä on minut lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'Isä, joka on minut lähettänyt, on todistanut minusta. Te ette ole koskaan kuulleet hänen ääntään ettekä nähneet hänen muotoaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'eikä teillä ole hänen sanaansa teissä pysyvänä, sillä te ette usko sitä, jonka hän on lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Tutkikaa Kirjoituksia, sillä teillä on niissä mielestänne iankaikkinen elämä, ja ne juuri todistavat minusta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'mutta ette tahdo tulla minun tyköni, että teillä olisi elämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'En ota vastaan kunniaa ihmisiltä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'mutta tunnen teidät, ettei teillä ole Jumalan rakkautta itsessänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Minä olen tullut Isäni nimessä, ja ette ota minua vastaan. Jos toinen tulee omassa nimessään, niin hänet otatte vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Kuinka te voisitte uskoa, te, jotka otatte vastaan kunniaa toinen toiseltanne, ettekä etsi sitä kunniaa, mikä tulee häneltä, joka yksin on Jumala?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Älkää luulko, että minä olen syyttävä teitä Isän luona. Teillä on syyttäjänne, Mooses, johon te panette toivonne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Sillä jos uskoisitte Moosesta, uskoisitte minua, sillä minusta hän on kirjoittanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Mutta jos ette usko hänen Kirjoituksiaan, kuinka uskoisitte minun sanojani?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Sen jälkeen Jeesus meni Galilean, se on Tiberiaan, meren tuolle puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Häntä seurasi paljon kansaa, koska he näkivät ne tunnusteot, joita hän teki sairaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Jeesus nousi vuorelle ja istui sinne opetuslapsineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Pääsiäinen, juutalaisten juhla, oli lähellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Kun Jeesus nosti silmänsä ja näki paljon kansaa tulevan luokseen, hän sanoi Filippokselle: \"Mistä ostamme leipää heidän syödäkseen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Mutta sen hän sanoi koetellakseen häntä, sillä itse hän tiesi, mitä aikoi tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Filippos vastasi hänelle: \"Eivät kahdensadan denaarin leivät riittäisi heille, niin että kukin saisi edes vähän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Niin eräs hänen opetuslapsistaan, Andreas, Simon Pietarin veli, sanoi hänelle:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, '\"Täällä on pieni poika, jolla on viisi ohraleipää ja kaksi kalaa, mutta mitä ne ovat näin monelle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Jeesus sanoi: \"Asettakaa ihmiset aterioimaan.\" Siinä paikassa oli paljon ruohoa. Niin miehet, luvultaan noin viisituhatta, asettuivat aterioimaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Jeesus otti leivät, kiitti ja jakeli istuville, samoin kaloistakin, niin paljon kuin he tahtoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Mutta kun heidät oli ravittu, hän sanoi opetuslapsilleen: \"Kootkaa yli jääneet palaset, ettei mitään joutuisi hukkaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'He kokosivat ne ja täyttivät kaksitoista koria palasilla, mitkä olivat jääneet yli viidestä ohraleivästä niiltä, jotka olivat aterioineet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Ihmiset sanoivat nähtyään sen tunnusteon, jonka Jeesus oli tehnyt: \"Tämä on totisesti se Profeetta, joka oli tuleva maailmaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Huomattuaan, että he aikoivat tulla ja väkisin ottaa hänet tehdäkseen hänet kuninkaaksi, Jeesus vetäytyi taas pois vuorelle, hän yksinään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Mutta kun ilta tuli, hänen opetuslapsensa menivät alas merelle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'astuivat veneeseen ja lähtivät menemään meren toiselle puolelle, Kapernaumiin. Oli tullut jo pimeä, eikä Jeesus ollut vielä saapunut heidän luokseen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'ja meri aaltoili ankarasti kovan tuulen puhaltaessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Kun he olivat soutaneet noin kaksikymmentä tai kolmekymmentä stadionia, he näkivät Jeesuksen kävelevän meren päällä ja tulevan lähelle venettä, ja he pelästyivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Mutta hän sanoi heille: \" Minä olen, älkää pelätkö.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'He tahtoivat ottaa hänet veneeseen, ja pian vene oli sillä rannalla, jonne he olivat matkalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Seuraavana päivänä kansa oli yhä vielä meren toisella puolella. He olivat näet nähneet, ettei siellä ollut muuta kuin yksi vene ja ettei Jeesus mennyt opetuslastensa kanssa veneeseen, vaan että hänen opetuslapsensa olivat lähteneet yksin pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'Kuitenkin oli veneitä tullut Tiberiasta lähelle sitä paikkaa, jossa he olivat syöneet leipää, sitten kun Herra oli lausunut kiitoksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Kun siis kansa näki, ettei Jeesus ollut siellä eivätkä hänen opetuslapsensa, hekin astuivat veneisiin ja menivät Kapernaumiin ja etsivät Jeesusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Kun he löysivät hänet meren toiselta puolelta, he sanoivat hänelle: \"Rabbi, milloin tulit tänne?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Jeesus vastasi heille ja sanoi: \"Totisesti, totisesti sanon teille: ette etsi minua sen tähden, että olette nähneet tunnustekoja, vaan sen tähden, että söitte leipiä ja tulitte ravituiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Älkää tehkö työtä saadaksenne sitä ruokaa, joka katoaa, vaan sitä ruokaa, joka pysyy iankaikkiseen elämään ja jonka Ihmisen Poika on teille antava, sillä häneen on Isä, Jumala itse, painanut sinettinsä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'He sanoivat hänelle: \"Mitä meidän tulee tehdä, että tekisimme Jumalan tekoja?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Jeesus vastasi ja sanoi heille: \"Se on Jumalan teko, että uskotte häneen, jonka Jumala on lähettänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'He sanoivat hänelle: \"Minkä tunnusteon sinä teet, että näkisimme sen ja uskoisimme sinua? Minkä teon teet?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Meidän isämme söivät mannaa erämaassa, kuten on kirjoitettu: \'Hän antoi leipää taivaasta heille syötäväksi.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Jeesus sanoi heille: \"Totisesti, totisesti sanon teille: Mooses ei antanut teille sitä leipää taivaasta, vaan minun Isäni antaa teille taivaasta todellisen leivän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Sillä Jumalan leipä on se, joka tulee alas taivaasta ja antaa maailmalle elämän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'He sanoivat hänelle: \"Herra, anna meille aina sitä leipää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Jeesus sanoi heille: \" Minä olen elämän leipä. Sille, joka tulee minun tyköni, ei tule koskaan nälkä, eikä sille, joka uskoo minuun, tule koskaan jano.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Mutta olen sanonut teille, että olette nähneet minut, ettekä kuitenkaan usko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Kaikki, minkä Isä antaa minulle, tulee tyköni, ja sitä, joka tulee tyköni, en heitä ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Sillä olen tullut taivaasta, en tekemään omaa tahtoani, vaan hänen tahtonsa, joka on minut lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'Tämä on lähettäjäni, Isän, tahto, etten kadota ketään niistä, jotka hän on minulle antanut, vaan herätän hänet viimeisenä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Sillä lähettäjäni tahto on, että jokaisella, joka näkee Pojan ja uskoo häneen, on iankaikkinen elämä, ja minä herätän hänet viimeisenä päivänä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Juutalaiset nurisivat häntä vastaan, koska hän sanoi: \" Minä olen se leipä, joka on tullut alas taivaasta\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'He sanoivat: \"Eikö tämä ole Jeesus, Joosefin poika, jonka isän ja äidin me tunnemme? Kuinka hän sitten sanoo: \'Olen tullut alas taivaasta\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Jeesus vastasi ja sanoi heille: \"Älkää nurisko keskenänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Ei kukaan tule tyköni, ellei Isä, joka on lähettänyt minut, vedä häntä, ja minä herätän hänet viimeisenä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Profeetoissa on kirjoitettuna: \'He tulevat kaikki Jumalan opettamiksi.\' Jokainen, joka on Isältä kuullut ja oppinut, tulee tyköni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Ei niin, että kukaan olisi nähnyt Isän, ainoastaan hän, joka on Jumalasta, on nähnyt Isän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Totisesti, totisesti sanon teille: sillä, joka uskoo minuun, on iankaikkinen elämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Minä olen elämän leipä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Teidän isänne söivät mannaa erämaassa ja kuolivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Tämä on se leipä, joka tulee alas taivaasta, ettei se, joka sitä syö, kuolisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Minä olen elävä leipä, joka on tullut alas taivaasta. Jos joku syö tätä leipää, hän elää iankaikkisesti. Leipä, jonka minä annan, on lihani, jonka minä annan maailman elämän edestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Silloin juutalaiset riitelivät keskenään sanoen: \"Kuinka hän voi antaa lihansa meille syötäväksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Jeesus sanoi heille: \"Totisesti, totisesti sanon teille: ellette syö Ihmisen Pojan lihaa ja juo hänen vertansa, teillä ei ole elämää itsessänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Joka syö minun lihani ja juo minun vereni, sillä on iankaikkinen elämä, ja minä herätän hänet viimeisenä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Sillä minun lihani on oikea ruoka, ja minun vereni on oikea juoma.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Joka syö minun lihani ja juo minun vereni, se pysyy minussa, ja minä hänessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Niin kuin Isä, joka elää, on minut lähettänyt, ja minä elän Isän kautta, niin myös se, joka minut syö, elää minun kauttani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Tämä on se leipä, joka tuli alas taivaasta. Ei ole, niin kuin oli teidän isienne laita: he söivät ja kuolivat. Se, joka tätä leipää syö, elää iankaikkisesti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Tämän hän puhui synagogassa opettaessaan Kapernaumissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Monet hänen opetuslapsistaan sen kuultuaan sanoivat: \"Tämä on kovaa puhetta, kuka voi sitä kuulla?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Mutta kun Jeesus sisimmässään tiesi, että hänen opetuslapsensa siitä nurisivat, hän sanoi heille: \"Loukkaako tämä teitä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Mitä sitten, jos näette Ihmisen Pojan nousevan sinne, missä hän oli ennen!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'Henki on se, joka tekee eläväksi, liha ei mitään hyödytä. Ne sanat, jotka minä puhun teille, ovat henki ja ovat elämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Mutta teissä on muutamia, jotka eivät usko.\" Sillä Jeesus tiesi alusta asti, ketkä ne olivat, jotka eivät uskoneet, ja kuka oli kavaltava hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'Hän sanoi: \"Sen tähden olen sanonut teille, että kukaan ei voi tulla minun tyköni, ellei sitä anneta hänelle minun Isältäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Tämän tähden monet hänen opetuslapsistaan vetäytyivät pois eivätkä enää vaeltaneet hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Jeesus sanoi niille kahdelletoista: \"Tahdotteko tekin mennä pois?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Simon Pietari vastasi hänelle: \"Herra, kenen luo menisimme? Sinulla on iankaikkisen elämän sanat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'ja olemme uskoneet ja ymmärtäneet, että sinä olet Jumalan Pyhä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Jeesus vastasi heille: \"Enkö minä ole valinnut teitä, te kaksitoista? Ja yksi teistä on perkele.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Mutta sen hän sanoi Juudaksesta, Simon Iskariotin pojasta, sillä tämä oli hänet kavaltava ja oli yksi niistä kahdestatoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Sen jälkeen Jeesus vaelsi ympäri Galileassa, sillä hän ei tahtonut vaeltaa Juudeassa, koska juutalaiset tavoittelivat häntä tappaakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Juutalaisten juhla, lehtimajanjuhla, oli lähellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Hänen veljensä sanoivat hänelle: \"Lähde täältä ja mene Juudeaan, että myös opetuslapsesi näkisivät tekojasi, joita sinä teet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'sillä ei kukaan, joka itse tahtoo tulla julki, tee mitään salassa. Jos näitä tekoja teet, ilmoita itsesi maailmalle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Sillä hänen veljensäkään eivät uskoneet häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Jeesus sanoi heille: \"Minun aikani ei ole vielä, mutta teille aika on aina sopiva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Teitä maailma ei voi vihata, mutta minua se vihaa, sillä minä todistan siitä, että sen teot ovat pahat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Menkää te ylös tähän juhlaan, minä en vielä mene tähän juhlaan, sillä aikani ei ole vielä täyttynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Tämän hän sanoi heille ja jäi Galileaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Mutta kun hänen veljensä olivat menneet juhlaan, silloin hänkin meni sinne, ei julkisesti, vaan ikään kuin salaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Juutalaiset etsivät häntä juhlan aikana ja sanoivat: \"Missä hän on?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Ja kansa kiisteli hänestä paljon. Muutamat sanoivat: \"Hän on hyvä\", mutta toiset sanoivat: \"Ei ole, vaan hän eksyttää kansaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Kuitenkaan kukaan ei puhunut hänestä julkisesti, koska he pelkäsivät juutalaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Mutta kun jo puoli juhlaa oli kulunut, Jeesus meni ylös pyhäkköön ja opetti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Juutalaiset ihmettelivät ja sanoivat: \"Kuinka tämä osaa Kirjoituksia, vaikka ei ole saanut oppia?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Jeesus vastasi heille ja sanoi: \"Minun oppini ei ole minun, vaan hänen, joka on minut lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Jos joku tahtoo tehdä hänen tahtonsa, hän tulee tuntemaan, onko tämä oppi Jumalasta vai puhunko minä omiani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Se, joka puhuu itsestään, etsii omaa kunniaansa, mutta se, joka etsii lähettäjänsä kunniaa, on totuudellinen, eikä hänessä ole vääryyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Eikö Mooses ole antanut teille lakia? Eikä kukaan teistä täytä lakia. Miksi tavoittelette minua tappaaksenne?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Kansa vastasi: \"Sinussa on riivaaja, kuka sinua tavoittelee tappaakseen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jeesus vastasi ja sanoi heille: \"Yhden teon tein, ja kaikki kummastelette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Tätä varten Mooses antoi teille ympärileikkauksen – ei niin, että se olisi Moosekselta, vaan se on isiltä – ja sapattinakin ympärileikkaatte ihmisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Jos ihminen saa ympärileikkauksen sapattina, ettei Mooseksen lakia rikottaisi, miksi olette vihoissanne minulle siitä, että tein koko ihmisen terveeksi sapattina?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Älkää tuomitko näön mukaan, vaan tuomitkaa oikea tuomio.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Muutamat jerusalemilaisista sanoivat: \"Eikö tämä ole se, jota he tavoittelevat tappaakseen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Katso, hän puhuu vapaasti, eivätkä he sano hänelle mitään. Olisivatko hallitusmiehet tosiaan saaneet tietoonsa, että tämä on Kristus?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Kuitenkin, tiedämme, mistä tämä on, mutta kun Kristus tulee, kukaan ei tiedä, mistä hän on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Jeesus huusi pyhäkössä, opetti ja sanoi: \"Tunnette minut ja tiedätte, mistä olen, enkä ole tullut itsestäni, vaan hän, joka on minut lähettänyt, on oikea lähettäjä, jota te ette tunne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Mutta minä tunnen hänet, sillä hänestä olen, ja hän on minut lähettänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'He aikoivat ottaa hänet kiinni, mutta kukaan ei käynyt häneen käsiksi, sillä hänen hetkensä ei ollut vielä tullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Mutta monet kansasta uskoivat häneen ja sanoivat: \"Kun Kristus tulee, mahtaako hän tehdä enemmän tunnustekoja, kuin tämä on tehnyt?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Fariseukset kuulivat kansan näin kiistelevän hänestä, ja ylipapit ja fariseukset lähettivät palvelijoita ottamaan hänet kiinni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Mutta Jeesus sanoi: \"Olen vielä vähän aikaa teidän kanssanne, ja menen pois hänen luokseen, joka on minut lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Silloin etsitte minua, mutta ette löydä, ja missä Minä olen, sinne te ette voi tulla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Niin juutalaiset sanoivat keskenään: \"Minne tämä aikoo mennä, koska emme voi löytää häntä? Aikooko hän mennä niiden luo, jotka asuvat hajallaan kreikkalaisten keskellä, ja opettaa kreikkalaisia?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Mitä tämä sana on, jonka hän sanoi: \'Etsitte minua, mutta ette löydä\', ja: \'Missä Minä olen, sinne te ette voi tulla\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'Mutta juhlan viimeisenä, suurena päivänä Jeesus seisoi, huusi ja sanoi: \"Jos joku janoaa, tulkoon minun tyköni ja juokoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Joka uskoo minuun, kuten Raamattu sanoo, hänen sisimmästään on juokseva elävän veden virrat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'Mutta sen hän sanoi Hengestä, jonka ne saavat, jotka uskoivat häneen, sillä Henki ei ollut vielä tullut, koska Jeesusta ei ollut vielä kirkastettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Monet kansasta kuultuaan nämä sanat sanoivat: \"Tämä on totisesti se Profeetta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Toiset sanoivat: \"Tämä on Kristus.\" Mutta toiset sanoivat: \"Eihän Kristus tule Galileasta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Eikö Raamattu sano, että Kristus on Daavidin siementä ja tulee Beetlehemin kylästä, jossa Daavid oli?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Silloin syntyi kansassa erimielisyyttä hänen tähtensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Muutamat heistä tahtoivat ottaa hänet kiinni. Mutta kukaan ei käynyt häneen käsiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Palvelijat palasivat ylipappien ja fariseusten luo, ja nämä sanoivat heille: \"Miksi ette tuoneet häntä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Palvelijat vastasivat: \"Ihminen ei ole koskaan puhunut niin, kuin tämä mies puhuu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Niin fariseukset vastasivat heille: \"Onko teidätkin eksytetty?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Onko kukaan hallitusmiehistä uskonut häneen tai kukaan fariseuksista?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Mutta tuo kansa, joka ei tunne lakia, on kirottu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Nikodeemus, joka oli aikaisemmin käynyt Jeesuksen luona ja joka oli yksi heistä, sanoi heille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, '\"Tuomitseeko lakimme ketään, ennen kuin häntä on kuulusteltu ja tiedetään, mitä hän on tehnyt?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'He vastasivat ja sanoivat hänelle: \"Oletko sinäkin Galileasta? Tutki ja näe, ettei Galileasta nouse profeettaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'Ja he menivät kukin kotiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Mutta Jeesus meni Öljymäelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Varhain aamulla hän taas saapui pyhäkköön, ja kaikki kansa tuli hänen luokseen, ja hän istuutui ja opetti heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Mutta kirjanoppineet ja fariseukset toivat hänen luokseen aviorikoksesta kiinniotetun naisen, asettivat hänet keskelle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'ja sanoivat Jeesukselle: \"Opettaja, tämä nainen on tavattu itse teosta tekemässä aviorikosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'Mooses on laissa antanut meille käskyn, että tuollaiset on kivitettävä. Mitä siis sinä sanot?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Mutta sen he sanoivat kiusaten häntä päästäkseen häntä syyttämään. Jeesus kumartui alas ja kirjoitti sormellaan maahan kiinnittämättä heihin huomiota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Mutta kun he yhä edelleen kysyivät häneltä, hän ojensi itsensä suoraksi ja sanoi heille: \"Joka teistä on synnitön, se heittäköön häntä ensimmäisenä kivellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Taas hän kumartui alas ja kirjoitti maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Kun he tämän kuulivat ja heidän omatuntonsa todisti heidät syyllisiksi, he menivät pois, toinen toisensa perästä, vanhimmista alkaen viimeisiin asti. Siihen jäi ainoastaan Jeesus sekä nainen, joka oli seisonut siinä keskellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Kun Jeesus ojensi itsensä eikä nähnyt ketään muuta kuin naisen, hän sanoi hänelle: \"Nainen, missä ne ovat, sinun syyttäjäsi? Eikö kukaan ole sinua tuominnut?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Hän vastasi: \"Herra, ei kukaan.\" Jeesus sanoi hänelle: \"En minäkään sinua tuomitse, mene, äläkä enää syntiä tee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Jeesus puhui taas heille sanoen: \" Minä olen maailman valkeus. Se, joka minua seuraa, ei vaella pimeydessä, vaan hänellä on oleva elämän valkeus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Fariseukset sanoivat hänelle: \"Sinä todistat itsestäsi, sinun todistuksesi ei ole oikea.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jeesus vastasi ja sanoi heille: \"Vaikka minä todistankin itsestäni, on todistukseni oikea, sillä tiedän, mistä olen tullut ja mihin menen, mutta te ette tiedä, mistä tulen, ettekä, mihin menen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Te tuomitsette lihan mukaan, minä en tuomitse ketään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Vaikka minä tuomitsisinkin, niin minun tuomioni olisi pätevä, sillä en ole yksin, vaan minä ja Isä, joka on minut lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Onhan teidän laissannekin kirjoitettuna, että kahden ihmisen todistus on pätevä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Minä olen se, joka todistan itsestäni, ja minusta todistaa myös Isä, joka on minut lähettänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'He sanoivat hänelle: \"Missä sinun isäsi on?\" Jeesus vastasi: \"Te ette tunne minua ettekä Isääni. Jos te tuntisitte minut, niin te tuntisitte myös Isäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Nämä sanat Jeesus puhui uhriarkun lähellä, opettaessaan pyhäkössä. Kukaan ei ottanut häntä kiinni, sillä hänen hetkensä ei ollut vielä tullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Jeesus sanoi taas heille: \"Minä menen pois, ja [te] etsitte minua ja kuolette syntiinne. Mihin minä menen, sinne te ette voi tulla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Juutalaiset sanoivat: \"Ei kai hän aio tappaa itseään, koska sanoo: \'Mihin minä menen, sinne te ette voi tulla\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Hän sanoi heille: \"Te olette alhaalta, minä olen ylhäältä. Te olette tästä maailmasta, minä en ole tästä maailmasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Sen tähden sanoin teille, että kuolette synteihinne, sillä ellette usko, että Minä olen, kuolette synteihinne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'He sanoivat hänelle: \"Kuka sinä olet?\" Jeesus sanoi heille: \"Alusta alkaen se, mitä minä puhunkin teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Paljon on minulla teistä puhuttavaa ja teissä tuomittavaa. Mutta hän, joka on minut lähettänyt, on totuudellinen, ja minkä minä olen kuullut häneltä, sen puhun maailmaa varten.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Mutta he eivät ymmärtäneet, että hän puhui heille Isästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Jeesus sanoi heille: \"Kun olette ylentäneet Ihmisen Pojan, silloin ymmärrätte, että Minä olen ja että en tee itsestäni mitään, vaan puhun tätä sen mukaan, kuin Isäni on minulle opettanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'Hän, joka on minut lähettänyt, on kanssani. Hän ei ole jättänyt minua yksin, koska minä teen aina sitä, mikä on hänelle otollista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Kun hän näin puhui, monet uskoivat häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Jeesus sanoi niille juutalaisille, jotka uskoivat häneen: \"Jos te pysytte minun sanassani, te olette totisesti minun opetuslapsiani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'ja tulette tuntemaan totuuden, ja totuus on tekevä teidät vapaiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'He vastasivat hänelle: \"Me olemme Aabrahamin siementä emmekä ole koskaan olleet kenenkään orjia. Kuinka sinä sitten sanot: \'Tulette vapaiksi\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Jeesus vastasi heille: \"Totisesti, totisesti sanon teille: jokainen, joka tekee syntiä, on synnin orja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'Mutta orja ei pysy talossa iäti, Poika pysyy iäti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Jos siis Poika tekee teidät vapaiksi, niin olette todellisesti vapaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Tiedän, että olette Aabrahamin siementä, mutta tavoittelette minua tappaaksenne, koska minun sanani ei saa tilaa teissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Minä puhun, mitä olen nähnyt Isäni luona, niin tekin teette, mitä olette nähneet omalta isältänne.\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'He vastasivat ja sanoivat hänelle: \"Aabraham on meidän isämme.\" Jeesus sanoi heille: \"Jos olisitte Aabrahamin lapsia, tekisitte Aabrahamin tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Mutta nyt tavoittelette minua tappaaksenne, miestä, joka on puhunut teille totuuden, jonka hän on kuullut Jumalalta. Sitä Aabraham ei tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Te teette isänne tekoja.\" He sanoivat hänelle: \"Me emme ole aviorikoksesta syntyneitä, meillä on yksi Isä, Jumala.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Jeesus sanoi heille: \"Jos Jumala olisi teidän Isänne, rakastaisitte minua, sillä minä olen Jumalasta lähtenyt ja tullut. En ole tullut itsestäni, vaan hän on minut lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Minkä tähden ette ymmärrä minun puhettani? Sen tähden, että ette voi kuulla minun sanaani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Te olette isästä perkeleestä ja isänne himoja tahdotte noudattaa. Hän on ollut murhaaja alusta asti, ja totuudessa hän ei pysynyt, koska hänessä ei totuutta ole. Kun hän puhuu valhetta, hän puhuu omaansa, sillä hän on valehtelija ja sen isä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Mutta minua ette usko sen tähden, että minä sanon totuuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Kuka teistä voi näyttää minut syylliseksi syntiin? Jos minä totuutta puhun, miksi ette usko minua?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Joka on Jumalasta, se kuulee Jumalan sanat. Sen tähden te ette kuule, koska ette ole Jumalasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Niin juutalaiset vastasivat ja sanoivat hänelle: \"Emmekö sanoneet sinulle oikein, että sinä olet samarialainen ja että sinussa on riivaaja?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jeesus vastasi: \"Minussa ei ole riivaajaa, vaan kunnioitan Isääni, ja te häpäisette minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Mutta minä en etsi omaa kunniaani. Yksi on, joka etsii ja tuomitsee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Totisesti, totisesti sanon teille: jos joku pitää minun sanani, hän ei ikinä näe kuolemaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Juutalaiset sanoivat hänelle: \"Nyt me ymmärrämme, että sinussa on riivaaja. Aabraham on kuollut ja profeetat, ja sinä sanot: \'Jos joku pitää minun sanani, hän ei ikinä maista kuolemaa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Oletko sinä suurempi kuin isämme Aabraham, joka on kuollut? Ja profeetat ovat kuolleet, keneksi sinä teet itsesi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jeesus vastasi: \"Jos minä otan itse itselleni kunnian, kunniani ei ole mitään. Isäni on se, joka minulle antaa kunnian, hän, josta te sanotte: \'Hän on meidän Jumalamme\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'ettekä tunne häntä, mutta minä tunnen hänet. Jos sanoisin, etten tunne häntä, niin olisin teidän kaltaisenne ja valehtelija. Mutta tunnen hänet ja pidän hänen sanansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Aabraham, teidän isänne, riemuitsi siitä, että hän oli näkevä minun päiväni. Hän näki sen ja iloitsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Niin juutalaiset sanoivat hänelle: \"Et ole vielä viidenkymmenen vuoden vanha, ja olet nähnyt Aabrahamin!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jeesus sanoi heille: \"Totisesti, totisesti sanon teille: ennen kuin Aabraham syntyi, Minä olen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Silloin he poimivat kiviä heittääkseen häntä niillä, mutta Jeesus lähti pyhäköstä kulkien heidän keskeltään ja meni pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Kulkiessaan ohi hän näki miehen, joka oli syntymästään saakka ollut sokea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Hänen opetuslapsensa kysyivät häneltä sanoen: \"Rabbi, kuka teki syntiä, tämä vai hänen vanhempansa, että hän syntyi sokeana?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jeesus vastasi: \"Ei tämä tehnyt syntiä eivätkä hänen vanhempansa, vaan Jumalan tekojen piti tulla hänessä julki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Niin kauan kuin on päivä, minun tulee tehdä sen tekoja, joka on minut lähettänyt. Tulee yö, jolloin kukaan ei voi työtä tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Niin kauan kuin olen maailmassa, olen maailman valkeus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Tämän sanottuaan hän sylki maahan, teki syljestä tahnan ja siveli tahnan hänen silmilleen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'ja sanoi hänelle: \"Mene ja peseydy Siiloan lammikossa\" – se on käännettynä: lähetetty. – Niin hän meni, peseytyi ja palasi näkevänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Niin naapurit ja ne, jotka ennen olivat nähneet, että hän oli sokea, sanoivat: \"Eikö tämä istunut tuolla ja kerjännyt?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Toiset sanoivat: \"Hän se on\", toiset sanoivat: \"Hän on vain hänen näköisensä.\" Tämä itse sanoi: \"Minä se olen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Niin he sanoivat hänelle: \"Miten sinun silmäsi ovat auenneet?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Tämä vastasi: \"Mies, jota kutsutaan Jeesukseksi, teki tahnan, voiteli silmäni ja sanoi minulle: \'Mene ja peseydy Siiloan lammikossa\', minä menin, peseydyin ja sain näköni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'He sanoivat hänelle: \"Missä hän on?\" Hän vastasi: \"En tiedä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'He veivät hänet, entisen sokean, fariseusten luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Mutta se päivä, jona Jeesus teki tahnan ja avasi hänen silmänsä, oli sapatti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Myös fariseukset kysyivät häneltä, miten hän oli saanut näkönsä. Hän sanoi heille: \"Hän siveli tahnan silmilleni, ja peseydyin, ja nyt näen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Muutamat fariseuksista sanoivat: \"Se mies ei ole Jumalasta, koska hän ei pidä sapattia.\" Toiset sanoivat: \"Kuinka syntinen ihminen voi tehdä sellaisia tunnustekoja?\" He olivat keskenään eri mieltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'He sanoivat taas sokealle: \"Mitä sinä sanot hänestä, koska hän avasi silmäsi?\" Hän sanoi: \"Hän on Profeetta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Mutta juutalaiset eivät uskoneet hänestä, että hän oli ollut sokea ja saanut näkönsä, ennen kuin kutsuivat näkönsä saaneen vanhemmat');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'ja kysyivät heiltä sanoen: \"Onko tämä teidän poikanne, jonka sanotte syntyneen sokeana? Kuinka hän sitten nyt näkee?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Hänen vanhempansa vastasivat ja sanoivat: \"Tiedämme, että tämä on poikamme ja että hän on syntynyt sokeana,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'mutta sitä, kuinka hän nyt näkee, emme tiedä. Emme myöskään tiedä, kuka on avannut hänen silmänsä. Kysykää häneltä. Hän on tarpeeksi vanha, puhukoon itse puolestaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Hänen vanhempansa sanoivat näin, koska pelkäsivät juutalaisia. Sillä juutalaiset olivat jo sopineet keskenään, että se, joka tunnusti hänet Kristukseksi, oli erotettava synagogasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Sen tähden hänen vanhempansa sanoivat: \"Hän on tarpeeksi vanha, kysykää häneltä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'He kutsuivat toistamiseen miehen, joka oli ollut sokea, ja sanoivat hänelle: \"Anna kunnia Jumalalle. Tiedämme, että mies on syntinen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Hän vastasi: \"Onko hän syntinen, sitä en tiedä. Tiedän vain yhden asian, että minä, joka olin sokea, nyt näen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'He sanoivat hänelle: \"Mitä hän sinulle teki? Miten hän avasi silmäsi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Hän vastasi heille: \"Johan minä sen teille sanoin, ettekä kuulleet. Miksi taas tahdotte sen kuulla? Tahdotteko tekin ruveta hänen opetuslapsikseen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'He herjasivat häntä ja sanoivat: \"Sinä olet hänen opetuslapsensa, mutta me olemme Mooseksen opetuslapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Tiedämme Jumalan puhuneen Moosekselle, mutta mistä tämä on, sitä emme tiedä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Mies vastasi ja sanoi heille: \"Sehän tässä on ihmeellistä, että te ette tiedä, mistä hän on, ja kuitenkin hän on avannut minun silmäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Tiedämme, ettei Jumala kuule syntisiä, vaan hän kuulee sitä, joka on jumalaapelkäävä ja tekee hänen tahtonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Maailman alusta ei ole kuultu kenenkään avanneen sokeana syntyneen silmiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Jos hän ei olisi Jumalasta, hän ei voisi tehdä mitään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'He vastasivat ja sanoivat hänelle: \"Sinä olet kokonaan synneissä syntynyt ja tahdot opettaa meitä!\" Ja he ajoivat hänet ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Jeesus sai kuulla heidän ajaneen hänet ulos. Tavatessaan hänet hän sanoi hänelle: \"Uskotko sinä Jumalan Poikaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Hän vastasi ja sanoi: \"Herra, kuka hän on, että uskoisin häneen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Jeesus sanoi hänelle: \"Olet hänet nähnyt, ja hän on se, joka puhuu kanssasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'Hän sanoi: \"Uskon, Herra\", ja hän rukoili kumartaen häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Jeesus sanoi: \"Tuomioksi olen tullut tähän maailmaan, että ne, jotka eivät näe, näkisivät, ja ne, jotka näkevät, tulisivat sokeiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Muutamat fariseukset, jotka olivat siinä häntä lähellä, kuulivat tämän ja sanoivat hänelle: \"Olemmeko mekin sokeita?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Jeesus sanoi heille: \"Jos olisitte sokeita, teillä ei olisi syntiä, mutta nyt sanotte: \'Me näemme\', sen tähden teidän syntinne pysyy.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, '\"Totisesti, totisesti sanon teille: se, joka ei mene ovesta lammastarhaan, vaan nousee sinne muualta, on varas ja ryöväri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Mutta se, joka menee ovesta sisälle, on lammasten paimen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Hänelle ovenvartija avaa, ja lampaat kuulevat hänen äänensä. Hän kutsuu omat lampaansa nimeltä ja vie heidät ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Laskettuaan kaikki omansa ulos hän kulkee niiden edellä, ja lampaat seuraavat häntä, sillä ne tuntevat hänen äänensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Mutta vierasta ne eivät seuraa, vaan pakenevat häntä, koska eivät tunne vierasten ääntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Tämän kuvauksen Jeesus puhui heille, mutta he eivät ymmärtäneet, mitä hänen puheensa tarkoitti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Jeesus sanoi heille vielä: \"Totisesti, totisesti minä sanon teille: Minä olen lammasten ovi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Kaikki, jotka ovat tulleet ennen minua, ovat varkaita ja ryöväreitä, mutta lampaat eivät ole kuulleet heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Minä olen ovi: jos joku minun kauttani menee sisälle, hän pelastuu, ja hän käy sisälle ja käy ulos ja löytää laitumen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Varas ei tule muuta kuin varastamaan, tappamaan ja tuhoamaan. Minä olen tullut, että heillä olisi elämä ja olisi yltäkyllin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Minä olen se hyvä paimen. Hyvä paimen antaa henkensä lammasten edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Mutta palkkalainen, joka ei ole paimen ja jonka omia lampaat eivät ole, kun hän näkee suden tulevan, [hän] jättää lampaat ja pakenee, ja susi ryöstää ja hajottaa ne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Hän pakenee, sillä hänet on palkattu eikä hän pidä huolta lampaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Minä olen se hyvä paimen, ja tunnen omani, ja minun omani tuntevat minut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'niin kuin Isä tuntee minut ja minä tunnen Isän, ja annan henkeni lampaiden edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Minulla on myös muita lampaita, jotka eivät ole tästä lammastarhasta. Myös niitä minun tulee johdattaa, ja ne tulevat kuulemaan minun ääneni, ja on oleva yksi lauma ja yksi paimen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Sen tähden Isä minua rakastaa, koska minä annan henkeni, että sen jälleen ottaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Kukaan ei ota sitä minulta, vaan minä annan sen itsestäni. Minulla on valta antaa se, ja minulla on valta ottaa se jälleen. Sen käskyn olen saanut Isältäni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Taas syntyi erimielisyyttä juutalaisten kesken näiden sanojen tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Useat heistä sanoivat: \"Hänessä on riivaaja, ja hän on järjiltään, mitä te häntä kuuntelette?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Toiset sanoivat: \"Nämä eivät ole riivatun sanoja, eihän riivaaja voi avata sokeiden silmiä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Oli temppelin vihkimisen muistojuhla Jerusalemissa, ja oli talvi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'Jeesus käveli pyhäkössä Salomon pylväskäytävässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Juutalaiset tulivat hänen ympärilleen ja sanoivat hänelle: \"Kuinka kauan pidät meidän mieltämme kiihdyksissä? Jos sinä olet Kristus, sano se meille suoraan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Jeesus vastasi heille: \"Olen sanonut sen teille, ettekä usko. Ne teot, joita minä teen Isäni nimessä, ne todistavat minusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Mutta te ette usko, sillä te ette ole minun lampaitani, kuten olen sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Minun lampaani kuulevat minun ääneni, ja minä tunnen heidät, ja he seuraavat minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'Minä annan heille iankaikkisen elämän, eivätkä he ikinä huku, eikä kukaan ryöstä heitä minun kädestäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Minun Isäni, joka on antanut heidät minulle, on suurempi kaikkia, eikä kukaan voi ryöstää heitä minun Isäni kädestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Minä ja Isä olemme yksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Juutalaiset ottivat taas kiviä maasta kivittääkseen hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Jeesus vastasi heille: \"Olen näyttänyt teille monta hyvää tekoa, jotka ovat Isästä. Mikä niistä on se, jonka tähden te minut kivitätte?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Juutalaiset vastasivat hänelle: \"Hyvän teon tähden emme kivitä sinua, vaan jumalanpilkan tähden, ja koska sinä, joka olet ihminen, teet itsesi Jumalaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jeesus vastasi heille: \"Eikö teidän laissanne ole kirjoitettuna: \'Minä sanoin: te olette jumalia\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Jos hän sanoo jumaliksi niitä, joille Jumalan sana tuli – eikä Raamattu voi raueta tyhjiin –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'kuinka te sanotte sille, jonka Isä on pyhittänyt ja lähettänyt maailmaan: \'Pilkkaat Jumalaa\', sen tähden että sanoin: \'Olen Jumalan Poika\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Jos en tee Isäni tekoja, älkää uskoko minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Mutta jos niitä teen, niin, vaikka ette uskoisikaan minua, uskokaa minun tekojani, että tulisitte tuntemaan ja ymmärtäisitte Isän olevan minussa ja minun olevan Isässä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Taas he tahtoivat ottaa hänet kiinni, mutta hän lähti pois heidän käsistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'Hän meni jälleen Jordanin tuolle puolelle siihen paikkaan, missä Johannes ensin kastoi, ja viipyi siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Monet tulivat hänen luokseen ja sanoivat: \"Johannes ei tehnyt yhtään tunnustekoa, mutta kaikki, mitä Johannes sanoi hänestä, on totta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Monet siellä uskoivat häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Eräs mies, Lasarus Betaniasta, Marian ja hänen sisarensa Martan kylästä, oli sairaana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Tämä Maria oli se, joka voiteli hajuvoiteella Herran ja pyyhki hiuksillaan hänen jalkansa, ja Lasarus, joka sairasti, oli hänen veljensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Sisaret lähettivät Jeesukselle tämän sanan: \"Herra, katso, se, joka on sinulle rakas, sairastaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Mutta sen kuultuaan Jeesus sanoi: \"Tämä tauti ei ole kuolemaksi, vaan Jumalan kunniaksi, että Jumalan Poika sen kautta kirkastuisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Jeesus rakasti Marttaa, hänen sisartaan ja Lasarusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Kun hän siis kuuli hänen sairastavan, hän viipyi siinä paikassa, missä oli, vielä kaksi päivää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'mutta niiden kuluttua hän sanoi opetuslapsilleen: \"Menkäämme taas Juudeaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Opetuslapset sanoivat hänelle: \"Rabbi, äsken juutalaiset yrittivät kivittää sinut, ja taas sinä menet sinne!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jeesus vastasi: \"Eikö päivässä ole kaksitoista tuntia? Se, joka vaeltaa päivällä, ei loukkaa itseään, sillä hän näkee tämän maailman valon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Mutta se, joka vaeltaa yöllä, loukkaa itsensä, sillä hänessä ei ole valoa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Näin hän puhui, ja sitten hän sanoi heille: \"Ystävämme Lasarus nukkuu, mutta menen herättämään hänet unesta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Opetuslapset sanoivat hänelle: \"Herra, jos hän nukkuu, hän tulee terveeksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Mutta Jeesus oli puhunut hänen kuolemastaan, he taas luulivat hänen puhuneen unessa nukkumisesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Silloin Jeesus sanoi heille suoraan: \"Lasarus on kuollut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'ja iloitsen teidän tähtenne siitä, etten ollut siellä, jotta uskoisitte, mutta menkäämme hänen luokseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Tuomas, jota sanottiin Didymokseksi, sanoi toisille opetuslapsille: \"Menkäämme mekin sinne kuollaksemme hänen kanssaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Jeesus tuli ja sai tietää, että hän oli ollut jo neljä päivää haudassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Betania oli lähellä Jerusalemia, noin viidentoista stadionin päässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'Useita juutalaisia oli tullut Martan ja Marian luo lohduttamaan heitä heidän veljensä kuolemasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Kun Martta kuuli, että Jeesus oli tulossa, hän meni häntä vastaan, mutta Maria istui kotona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Martta sanoi Jeesukselle: \"Herra, jos sinä olisit ollut täällä, veljeni ei olisi kuollut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Mutta nytkin tiedän, että Jumala antaa sinulle kaiken, mitä Jumalalta anot.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Jeesus sanoi hänelle: \"Sinun veljesi on nouseva ylös.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Martta sanoi hänelle: \"Tiedän hänen nousevan ylösnousemuksessa, viimeisenä päivänä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Jeesus sanoi hänelle: \" Minä olen ylösnousemus ja elämä. Se, joka uskoo minuun, elää, vaikka olisi kuollut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'eikä yksikään, joka elää ja uskoo minuun, ikinä kuole. Uskotko sen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Hän sanoi hänelle: \"Uskon, Herra. Minä olen uskonut, että sinä olet Kristus, Jumalan Poika, se, joka oli tuleva maailmaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Tämän sanottuaan hän meni ja kutsui salaa sisarensa Marian sanoen: \"Opettaja on täällä ja kutsuu sinua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Kun Maria sen kuuli, hän nousi nopeasti ja meni hänen luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Mutta Jeesus ei ollut vielä saapunut kylään, vaan oli yhä siinä paikassa, missä Martta oli kohdannut hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Kun nyt juutalaiset, jotka olivat Marian kanssa talossa häntä lohduttamassa, näkivät hänen nopeasti nousevan ja lähtevän ulos, he seurasivat häntä luullen hänen menevän haudalle itkemään siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Kun siis Maria saapui sinne, missä Jeesus oli, ja näki hänet, hän lankesi hänen jalkojensa eteen ja sanoi hänelle: \"Herra, jos olisit ollut täällä, veljeni ei olisi kuollut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Kun Jeesus näki hänen itkevän ja hänen kanssaan tulleiden juutalaisten itkevän, hän joutui hengessään syvän liikutuksen valtaan ja vapisi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'ja hän sanoi: \"Minne panitte hänet?\" He sanoivat hänelle: \"Herra, tule ja katso.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Jeesus itki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Juutalaiset sanoivat: \"Katso, kuinka rakas hän oli hänelle!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Mutta muutamat heistä sanoivat: \"Eikö hän, joka avasi sokean silmät, olisi voinut tehdä sitäkin, ettei tämä olisi kuollut?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Jeesus joutui taas liikutuksen valtaan ja meni haudalle. Mutta se oli luola, ja sen suulla oli kivi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Jeesus sanoi: \"Ottakaa kivi pois.\" Martta, kuolleen sisar, sanoi hänelle: \"Herra, hän haisee jo, sillä hän on ollut haudassa neljättä päivää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Jeesus sanoi hänelle: \"Enkö sanonut sinulle, että jos uskoisit, niin näkisit Jumalan kirkkauden?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'He ottivat kiven pois sieltä, missä kuollut makasi. Jeesus loi silmänsä ylös ja sanoi: \"Isä, kiitän sinua, että olet kuullut minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Minä kyllä tiesin, että minua aina kuulet, mutta kansan tähden, joka seisoo tässä ympärillä, tämän sanon, että he uskoisivat sinun lähettäneen minut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Sen sanottuaan hän huusi suurella äänellä: \"Lasarus, tule ulos!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'Kuollut tuli ulos, jalat ja kädet siteisiin käärittyinä, ja hänen kasvojensa ympärille oli kääritty hikiliina. Jeesus sanoi heille: \"Päästäkää hänet ja antakaa hänen mennä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Useat juutalaisista, jotka olivat tulleet Marian luo ja nähneet, mitä Jeesus teki, uskoivat häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Mutta muutamat heistä menivät fariseusten luo ja sanoivat heille, mitä Jeesus oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Niin ylipapit ja fariseukset kokosivat Neuvoston ja sanoivat: \"Mitä teemme, sillä tuo mies tekee paljon tunnustekoja?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Jos sallimme hänen näin tehdä, kaikki uskovat häneen, ja roomalaiset tulevat ja ottavat meiltä sekä maan että kansan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Mutta eräs heistä, Kaifas, joka sinä vuonna oli ylipappi, sanoi heille: \"Te ette tiedä mitään');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'ettekä ajattele, että meille on parempi, että yksi ihminen kuolee kansan edestä, kuin että koko kansa hukkuu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Mutta sitä hän ei sanonut itsestään, vaan koska hän oli sinä vuonna ylipappi, hän ennusti, että Jeesus oli kuoleva kansan edestä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'eikä ainoastaan tämän kansan edestä, vaan myös kootakseen yhdeksi hajalla olevat Jumalan lapset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Siitä päivästä lähtien heillä oli siis tehtynä päätös tappaa hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Sen tähden Jeesus ei enää vaeltanut julkisesti juutalaisten keskellä, vaan lähti sieltä lähellä erämaata olevaan paikkaan, Efraim-nimiseen kaupunkiin, ja siellä hän oleskeli opetuslapsineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Mutta juutalaisten pääsiäinen oli lähellä, ja monet menivät maaseudulta ylös Jerusalemiin ennen pääsiäisjuhlaa puhdistamaan itsensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'He etsivät Jeesusta ja sanoivat toisilleen seisoessaan pyhäkössä: \"Mitä arvelette? Eikö hän kenties tulekaan juhlille?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Mutta ylipapit ja fariseukset olivat antaneet käskyn, että jos joku tietäisi, missä hän oli, hänen oli annettava se ilmi, jotta he ottaisivat hänet kiinni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Kuusi päivää ennen pääsiäistä Jeesus saapui Betaniaan, jossa Lasarus asui, hän, jonka Jeesus oli herättänyt kuolleista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Siellä valmistettiin hänelle ateria, ja Martta palveli, mutta Lasarus oli yksi niistä, jotka aterioivat hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Maria otti naulan oikeaa, kallisarvoista nardusvoidetta, voiteli Jeesuksen jalat ja pyyhki ne hiuksillaan, ja huone tuli täyteen voiteen tuoksua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Silloin sanoi yksi hänen opetuslapsistaan, Juudas Iskariot, joka oli hänet kavaltava:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, '\"Miksi tätä voidetta ei myyty kolmella sadalla denaarilla ja annettu niitä köyhille?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Mutta tätä hän ei sanonut sen tähden, että olisi pitänyt huolta köyhistä, vaan sen tähden, että hän oli varas ja että hän rahakukkaron hoitajana otti itselleen, mitä siihen oli pantu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Jeesus sanoi: \"Anna hänen olla, että hän saisi toimittaa tämän hautaamispäivääni varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Sillä köyhät teillä on aina keskuudessanne, mutta minua teillä ei ole aina.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Silloin suuri joukko juutalaisia sai tietää, että hän oli siellä. He menivät sinne, ei ainoastaan Jeesuksen tähden, vaan myös nähdäkseen Lasaruksen, jonka hän oli herättänyt kuolleista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Mutta ylipapit päättivät tappaa Lasaruksenkin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'koska monet juutalaiset hänen tähtensä menivät sinne ja uskoivat Jeesukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Seuraavana päivänä, kun suuri kansanjoukko, joka oli saapunut juhlille, kuuli, että Jeesus oli tulossa Jerusalemiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'he ottivat palmujen oksia ja menivät häntä vastaan ja huusivat: \"Hoosianna, siunattu olkoon hän, joka tulee Herran nimeen, Israelin kuningas!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Saatuaan nuoren aasin Jeesus istui sen selkään, kuten on kirjoitettu:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, '\"Älä pelkää, tytär Siion. Katso, sinun kuninkaasi tulee istuen aasin varsan selässä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Tätä hänen opetuslapsensa eivät aluksi ymmärtäneet, mutta kun Jeesus oli kirkastettu, silloin he muistivat, että tämä oli hänestä kirjoitettu ja että he olivat tämän hänelle tehneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Niin kansa, joka oli ollut hänen kanssaan, kun hän kutsui Lasaruksen haudasta ja herätti hänet kuolleista, todisti hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Sen tähden kansa menikin häntä vastaan, koska he kuulivat, että hän oli tehnyt sen tunnusteon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Niin fariseukset sanoivat keskenään: \"Te näette, ettette saa aikaan mitään. Katso, koko maailma kulkee hänen perässään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Oli muutamia kreikkalaisia niiden joukosta, jotka tulivat ylös juhlaan rukoilemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Nämä menivät Filippoksen luo, joka oli Galilean Beetsaidasta, ja pyysivät häntä sanoen: \"Herra, me haluamme nähdä Jeesuksen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Filippos meni ja sanoi sen Andreaalle. Andreas ja Filippos menivät ja sanoivat Jeesukselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Mutta Jeesus vastasi heille sanoen: \"On tullut hetki, jolloin Ihmisen Poika kirkastetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Totisesti, totisesti sanon teille: jos ei vehnänjyvä putoa maahan ja kuole, se jää yksin, mutta jos se kuolee, se tuottaa paljon hedelmää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Joka elämäänsä rakastaa, kadottaa sen. Mutta joka vihaa elämäänsä tässä maailmassa, säilyttää sen iankaikkiseen elämään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Jos joku minua palvelee, seuratkoon minua, ja missä Minä olen, siellä on myös minun palvelijani oleva. Jos joku minua palvelee, Isä on kunnioittava häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Nyt minun sieluni on järkytetty, ja mitä minun pitäisi sanoa? Isä, pelasta minut tästä hetkestä. Kuitenkin: sitä varten olen tähän hetkeen tullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Isä, kirkasta nimesi!\" Niin taivaasta tuli ääni: \"olen sen kirkastanut ja olen sen vielä kirkastava.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Kansa, joka seisoi siinä ja kuuli sen, sanoi ukkosen jyrisseen. Toiset sanoivat: \"Häntä puhutteli enkeli.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Jeesus vastasi ja sanoi: \"Tämä ääni ei tullut minun tähteni, vaan teidän tähtenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Nyt tulee tuomio tälle maailmalle. Nyt tämän maailman ruhtinaan pitää tulla heitetyksi ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'Kun minut ylennetään maasta, vedän kaikki tyköni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'Mutta sen hän sanoi osoittaen, millaisella kuolemalla hän oli kuoleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Kansa vastasi hänelle: \"Me olemme laista kuulleet, että Kristus pysyy iäti. Kuinka sinä sanot, että Ihmisen Poika on ylennettävä? Kuka on Ihmisen Poika?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Jeesus sanoi heille: \"Vielä vähän aikaa valkeus on teidän keskuudessanne. Vaeltakaa, niin kauan kuin teillä on valkeus, ettei pimeys saisi teitä valtaansa. Se, joka pimeässä vaeltaa, ei tiedä, mihin menee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Niin kauan kuin teillä on valkeus, uskokaa valkeuteen, että valkeuden lapsiksi tulisitte.\" Tämän Jeesus puhui, lähti pois ja kätkeytyi heiltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Vaikka hän oli tehnyt niin suuria tunnustekoja heidän nähtensä, he eivät uskoneet häneen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'että kävisi toteen profeetta Jesajan sana, jonka hän on sanonut: \"Herra, kuka uskoo saarnamme, ja kenelle Herran käsivarsi ilmoitetaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Sen tähden he eivät voineet uskoa, koska Jesaja on vielä sanonut:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, '\"Hän on sokaissut heidän silmänsä ja paaduttanut heidän sydämensä, että he eivät näkisi silmillään eivätkä ymmärtäisi sydämellään eivätkä kääntyisi ja etten heitä parantaisi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Tämän Jesaja sanoi, kun näki hänen kirkkautensa ja puhui hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Kuitenkin useat hallitusmiehistäkin uskoivat häneen, mutta fariseusten tähden he eivät tunnustaneet sitä, etteivät joutuisi erotetuiksi synagogasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'sillä he rakastivat ihmiskunniaa enemmän kuin Jumalan kunniaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Mutta Jeesus huusi ja sanoi: \"Joka uskoo minuun, se ei usko minuun, vaan häneen, joka on minut lähettänyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'ja se, joka näkee minut, näkee hänet, joka on minut lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Minä olen tullut valkeudeksi maailmaan, ettei yksikään, joka uskoo minuun, jäisi pimeyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'Jos joku kuulee minun sanani eikä niitä usko, minä en häntä tuomitse. En ole näet tullut maailmaa tuomitsemaan, vaan pelastamaan maailman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Joka halveksii minua eikä ota vastaan minun sanojani, hänellä on tuomitsijansa: se sana, jonka olen puhunut, on tuomitseva hänet viimeisenä päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Sillä en minä ole puhunut itsestäni, vaan Isä, joka on minut lähettänyt, on itse antanut minulle käskyn, mitä minun pitää sanoa ja mitä puhua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'Tiedän, että hänen käskynsä on iankaikkinen elämä. Sen tähden, minkä minä puhun, sen puhun niin, kuin Isä on minulle sanonut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Mutta ennen pääsiäisjuhlaa, kun Jeesus tiesi hetkensä tulleen, että hän oli siirtyvä tästä maailmasta Isän luo, niin hän, joka oli rakastanut omiaan, jotka olivat maailmassa, rakasti heitä loppuun asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Oltaessa ilta-aterialla, kun perkele oli jo pannut Juudaksen, Simon Iskariotin pojan, sydämeen, että hän kavaltaisi Jeesuksen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Jeesus, tietäen, että Isä oli antanut kaikki hänen käsiinsä ja että hän oli lähtenyt Jumalan luota ja menee Jumalan luo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'nousi aterialta, riisui viittansa, otti liinavaatteen ja vyötti itsensä sillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Sitten hän kaatoi vettä pesumaljaan ja ryhtyi pesemään opetuslastensa jalkoja ja pyyhkimään niitä liinavaatteella, johon oli vyöttäytynyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'ja hän tuli Simon Pietarin luo. Mutta tämä sanoi hänelle: \"Herra, sinäkö peset minun jalkani?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jeesus vastasi ja sanoi hänelle: \"Mitä minä teen, sitä et nyt käsitä, mutta myöhemmin sinä sen ymmärrät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Pietari sanoi hänelle: \"Sinä et ikinä saa pestä minun jalkojani.\" Jeesus vastasi hänelle: \"Ellen sinua pese, sinulla ei ole osuutta minun kanssani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Simon Pietari sanoi hänelle: \"Herra, älä pese ainoastaan minun jalkojani, vaan myös kädet ja pää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Jeesus sanoi hänelle: \"Joka on kylpenyt, ei tarvitse muuta, kuin että jalat pestään, ja niin hän on kokonaan puhdas, ja te olette puhtaita, ette kuitenkaan kaikki.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Sillä hän tiesi kavaltajansa. Sen tähden hän sanoi: \"Ette kaikki ole puhtaita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Kun hän siis oli pessyt heidän jalkansa ja ottanut viittansa ja asettunut taas aterialle, hän sanoi heille: \"Ymmärrättekö, mitä olen teille tehnyt?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Te puhuttelette minua opettajaksi ja Herraksi, ja oikein te sanotte, sillä se olen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Jos siis minä, teidän Herranne ja opettajanne, olen pessyt teidän jalkanne, tekin olette velvollisia pesemään toistenne jalat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Sillä annoin teille esikuvan, että myös te tekisitte, kuten minä tein teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Totisesti, totisesti sanon teille: palvelija ei ole herraansa suurempi eikä apostoli lähettäjäänsä suurempi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Jos tämän tiedätte, olette autuaita, jos sen teette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'En sano tätä teistä kaikista. Minä tiedän, ketkä olen valinnut. Mutta jotta Raamattu kävisi toteen... \'Se, joka syö minun leipääni, on nostanut kantapäänsä minua vastaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Jo nyt sanon sen teille, ennen kuin se tapahtuu, että te, kun se tapahtuu, uskoisitte, että Minä olen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Totisesti, totisesti sanon teille: Se, joka ottaa vastaan sen, jonka lähetän, ottaa vastaan minut. Mutta se, joka ottaa vastaan minut, ottaa vastaan hänet, joka on lähettänyt minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Tämän sanottuaan Jeesus järkyttyi hengessään, todisti ja sanoi: \"Totisesti, totisesti sanon teille: yksi teistä on kavaltava minut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Opetuslapset katsoivat toisiinsa epätietoisina, kenestä hän puhui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Eräs hänen opetuslapsistaan, se, jota Jeesus rakasti, lepäsi aterioitaessa Jeesuksen rintaa vasten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Simon Pietari nyökkäsi hänelle päätään ja sanoi hänelle: \"Sano, kuka se on, josta hän puhuu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Tämä nojautuen Jeesuksen rintaa vasten sanoi hänelle: \"Herra, kuka se on?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Jeesus vastasi: \"Se on se, jolle minä kastan ja annan tämän palan.\" Hän otti palan, kastoi sen ja antoi Juudakselle, Simon Iskariotin pojalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'Silloin, sen palan jälkeen, häneen meni saatana. Jeesus sanoi hänelle: \"Minkä teet, se tee pian.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Mutta kukaan aterioivista ei ymmärtänyt, mitä varten hän sen hänelle sanoi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Sillä muutamat luulivat, koska rahakukkaro oli Juudaksella, Jeesuksen sanoneen hänelle: \"Osta, mitä tarvitsemme juhlaa varten\", tai että hän antaisi jotakin köyhille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Otettuaan palan hän lähti heti ulos, ja oli yö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Kun hän oli mennyt ulos, Jeesus sanoi: \"Nyt Ihmisen Poika on kirkastettu, ja Jumala on kirkastettu hänessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Jos Jumala on kirkastettu hänessä, Jumala kirkastaa hänet myös itsessään ja kirkastaa hänet pian.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Lapset, vielä vähän aikaa olen teidän kanssanne. Tulette etsimään minua, ja kuten sanoin juutalaisille: \'Mihin minä menen, sinne te ette voi tulla\', niin sanon nyt myös teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Uuden käskyn annan teille, että rakastatte toisianne, niin kuin olen rakastanut teitä – että tekin niin rakastatte toisianne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Siitä kaikki tulevat tuntemaan teidät minun opetuslapsikseni, jos teillä on keskenänne rakkaus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Simon Pietari sanoi hänelle: \"Herra, mihin menet?\" Jeesus vastasi hänelle: \"Mihin menen, sinne et voi nyt minua seurata, mutta myöhemmin seuraat minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Pietari sanoi hänelle: \"Herra, miksi en voi seurata sinua nyt? Henkeni annan edestäsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jeesus vastasi: \"Sinäkö annat henkesi minun edestäni? Totisesti, totisesti sanon sinulle: kukko ei laula, ennen kuin kiellät minut kolme kertaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, '\"Älkää olko aralla mielin. Uskokaa Jumalaan, ja uskokaa minuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Minun Isäni kodissa on monta asuntoa. Jos ei niin olisi, sanoisinko teille, että menen valmistamaan teille paikan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Vaikka menen valmistamaan teille paikan, tulen takaisin ja otan teidät tyköni, että tekin olisitte siellä, missä Minä olen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Tiedätte, minne minä menen – myös tien tiedätte.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Tuomas sanoi hänelle: \"Herra, me emme tiedä, mihin sinä menet, kuinka sitten voisimme tietää tien?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jeesus sanoi hänelle: \" Minä olen tie, totuus ja elämä. Kukaan ei tule Isän luo muuten kuin minun kauttani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Jos olisitte tunteneet minut, tuntisitte myös Isäni. Tästä lähin tunnette hänet ja olette nähneet hänet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Filippos sanoi hänelle: \"Herra, näytä meille Isä, niin se riittää meille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Jeesus sanoi hänelle: \"Niin kauan aikaa olen ollut kanssanne, etkä tunne minua, Filippos! Joka on nähnyt minut, on nähnyt Isän, kuinka sinä sanot: \'Näytä meille Isä\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Etkö usko, että minä olen Isässä, ja että Isä on minussa? Niitä sanoja, jotka minä teille puhun, en puhu itsestäni, ja Isä, joka minussa asuu, tekee teot, jotka ovat hänen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Uskokaa minua, että minä olen Isässä, ja että Isä on minussa, mutta jos ette, niin uskokaa itse tekojen tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Totisesti, totisesti sanon teille: joka uskoo minuun, myös hän on tekevä niitä tekoja, joita minä teen, ja suurempiakin, kuin ne ovat, hän on tekevä, sillä minä menen Isän luo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'ja mitä hyvänsä te anotte minun nimessäni, sen teen, että Isä kirkastettaisiin Pojassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Jos anotte minulta jotakin minun nimessäni, minä sen teen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Jos rakastatte minua, pidätte minun käskyni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'Minä olen rukoileva Isää, ja hän antaa teille toisen Puolustajan pysymään kanssanne iankaikkisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'totuuden Hengen, jota maailma ei voi ottaa vastaan, koska se ei näe häntä eikä tunne häntä. Mutta te tunnette hänet, sillä hän pysyy teidän luonanne ja on teissä oleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'En jätä teitä orvoiksi, tulen teidän luoksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Vielä vähän aikaa, niin maailma ei enää minua näe, mutta te näette minut. Koska minä elän, tekin elätte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'Sinä päivänä te ymmärrätte, että minä olen Isässäni, ja että te olette minussa ja minä teissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Jolla on minun käskyni ja joka pitää ne, se rakastaa minua. Mutta sitä, joka minua rakastaa, minun Isäni rakastaa, ja minä rakastan häntä ja ilmoitan itseni hänelle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Juudas, ei Iskariot, sanoi hänelle: \"Herra, miksi tapahtuu, että ilmoitat itsesi meille etkä maailmalle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jeesus vastasi ja sanoi hänelle: \"Jos joku rakastaa minua, hän pitää minun sanani, ja minun Isäni rakastaa häntä, ja [me] tulemme hänen luokseen ja jäämme hänen luokseen asumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Joka ei minua rakasta, se ei pidä minun sanojani, ja se sana, jonka kuulette, ei ole minun, vaan Isän, joka on minut lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Tämän olen puhunut teille ollessani luonanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Mutta Puolustaja, Pyhä Henki, jonka Isä on lähettävä minun nimessäni, hän opettaa teille kaikki ja muistuttaa teitä kaikesta, minkä olen teille puhunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Rauhan jätän teille: minun rauhani – sen annan teille. En minä anna teille, niin kuin maailma antaa. Älkää olko aralla mielin älkääkä pelätkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Kuulitte minun sanovan teille: \'Menen pois ja palaan luoksenne.\' Jos te minua rakastaisitte, iloitsisitte siitä, että menen Isän luo, sillä Isä on minua suurempi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Nyt olen sanonut sen teille, ennen kuin se on tapahtunut, jotta uskoisitte, kun se tapahtuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'En puhu enää paljon teidän kanssanne, sillä tämän maailman ruhtinas tulee, ja minussa hänellä ei ole mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Mutta että maailma ymmärtäisi minun rakastavan Isää ja tekevän niin, kuin Isä on minua käskenyt: nouskaa, lähtekäämme täältä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, '\" Minä olen oikea viinipuu, ja minun Isäni on viinitarhuri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Jokaisen oksan minussa, joka ei kanna hedelmää, hän karsii pois. Mutta jokaisen, joka kantaa hedelmää, hän puhdistaa, jotta se kantaisi runsaamman hedelmän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Te olette jo puhtaita sen sanan tähden, jonka olen puhunut teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Pysykää minussa, niin minä pysyn teissä. Kuten oksa ei voi kantaa hedelmää itsestään, ellei se pysy viinipuussa, ette tekään, ellette pysy minussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Minä olen viinipuu, te olette oksat. Se, joka pysyy minussa ja jossa minä pysyn, kantaa paljon hedelmää, sillä ilman minua ette voi tehdä mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Jos joku ei pysy minussa, hänet heitetään pois kuin oksa, ja hän kuivuu, ja ne kootaan yhteen ja heitetään tuleen, ja ne palavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Jos te pysytte minussa ja minun sanani pysyvät teissä, anokaa, mitä ikinä tahdotte, ja se tapahtuu teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Siinä minun Isäni kirkastetaan, että te kannatte paljon hedelmää ja tulette minun opetuslapsikseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Niin kuin Isä on rakastanut minua, niin minäkin olen rakastanut teitä. Pysykää minun rakkaudessani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Jos pidätte minun käskyni, pysytte minun rakkaudessani, niin kuin minä olen pitänyt Isäni käskyt ja pysyn hänen rakkaudessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Tämän olen puhunut teille, että minun iloni olisi teissä ja teidän ilonne tulisi täydelliseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Tämä on minun käskyni, että rakastatte toisianne, niin kuin minä olen teitä rakastanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Sen suurempaa rakkautta ei ole kenelläkään, kuin että hän antaa henkensä ystäviensä edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Te olette ystäviäni, jos teette sen, minkä minä käsken teidän tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'En enää sano teitä palvelijoiksi, sillä palvelija ei tiedä, mitä hänen herransa tekee, vaan sanon teitä ystäviksi, sillä olen ilmoittanut teille kaiken, mitä olen kuullut Isältäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Te ette valinneet minua, vaan minä valitsin teidät ja asetin teidät, jotta te menisitte ja kantaisitte hedelmää ja että teidän hedelmänne pysyisi: että mitä ikinä anotte Isältä minun nimessäni, hän sen teille antaisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Sen teille käsken, että rakastatte toisianne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Jos maailma teitä vihaa, tietäkää, että se on vihannut minua ennen kuin teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Jos te maailmasta olisitte, maailma omaansa rakastaisi. Mutta koska ette ole maailmasta, vaan minä olen valinnut teidät maailmasta, sen tähden maailma teitä vihaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Muistakaa se sana, jonka minä teille sanoin: \'Ei ole palvelija herraansa suurempi.\' Jos he ovat minua vainonneet, he teitäkin vainoavat. Jos he ovat pitäneet minun sanani, he pitävät myös teidän sananne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Mutta kaiken tämän he tekevät teille minun nimeni tähden, koska he eivät tunne häntä, joka on minut lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Jos en olisi tullut ja puhunut heille, heillä ei olisi syntiä, mutta nyt heillä ei ole, millä puolustaisivat syntiään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Joka vihaa minua, se vihaa myös minun Isääni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Jos en olisi tehnyt heidän keskuudessaan niitä tekoja, joita kukaan muu ei ole tehnyt, heillä ei olisi syntiä, mutta nyt he ovat nähneet ne ja ovat vihanneet sekä minua että minun Isääni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Mutta se sana oli käyvä toteen, joka on kirjoitettuna heidän laissaan: \'He ovat vihanneet minua syyttä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Mutta kun Puolustaja tulee, jonka minä lähetän teille Isän luota, totuuden Henki, joka lähtee Isän luota, hän on todistava minusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'Te myös todistatte, sillä te olette olleet kanssani alusta asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, '\"Tämän olen puhunut teille, ettette loukkaantuisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'He erottavat teidät synagogasta, ja tulee aika, jolloin jokainen, joka tappaa teitä, luulee tekevänsä uhripalveluksen Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Sen he tekevät teille, koska he eivät tunne Isää eivätkä minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Mutta tämän olen puhunut teille, että kun se aika tulee, muistaisitte, mitä olen sanonut teille. Tätä en ole sanonut teille alusta, koska olin teidän kanssanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Mutta nyt menen hänen luokseen, joka on minut lähettänyt, eikä kukaan teistä kysy minulta: \'Minne menet?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Mutta koska olen tämän teille puhunut, murhe täyttää sydämenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Kuitenkin minä sanon teille totuuden: teille on hyväksi, että minä menen pois. Sillä ellen mene pois, Puolustaja ei tule teidän luoksenne, mutta jos menen, niin lähetän hänet teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Kun hän tulee, hän nuhtelee maailmaa synnin, vanhurskauden ja tuomion tähden:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'synnin, koska he eivät usko minuun;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'vanhurskauden, koska menen Isän luo, ettekä enää näe minua;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'ja tuomion, koska tämän maailman ruhtinas on tuomittu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Minulla on vielä paljon sanottavaa teille, mutta ette voi nyt sitä kantaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Mutta kun hän tulee, totuuden Henki, hän johdattaa teidät kaikkeen totuuteen. Sillä se, mitä hän puhuu, ei ole hänestä itsestään, vaan minkä hän kuulee, sen hän puhuu, ja julistaa teille, mitä on tuleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Hän on minut kirkastava, sillä hän ottaa minun omastani ja julistaa teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Kaikki, mitä Isällä on, on minun. Sen tähden sanoin, että hän ottaa minun omastani ja julistaa teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Vähän aikaa, niin ette enää näe minua, ja taas vähän aikaa, niin näette minut, sillä minä menen Isän luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Silloin muutamat hänen opetuslapsistaan sanoivat toisilleen: \"Mitä tarkoittaa, kun hän sanoo meille: \'Vähän aikaa, niin ette minua näe, ja taas vähän aikaa, niin näette minut\', ja: \'Minä menen Isän luo\'?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Niin he sanoivat: \"Mitä tarkoittaa, kun hän sanoo: \'Vähän aikaa\'? Emme tiedä, mitä hän puhuu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Jeesus huomasi, että he tahtoivat kysyä häneltä, ja sanoi heille: \"Sitäkö kyselette keskenänne, että sanoin: \'Vähän aikaa, niin ette minua näe, ja taas vähän aikaa, niin näette minut\'?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Totisesti, totisesti sanon teille: te tulette itkemään ja valittamaan, mutta maailma on iloitseva. Te tulette murheellisiksi, mutta teidän murheenne on muuttuva iloksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Kun nainen synnyttää, hänellä on murhe, koska hänen hetkensä on tullut. Mutta kun hän on synnyttänyt lapsen, hän ei enää muista ahdistustaan sen ilon tähden, että ihminen on syntynyt maailmaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Niin teilläkin on nyt murhe. Mutta olen taas näkevä teidät, ja teidän sydämenne on iloitseva, eikä kukaan ota teiltä pois teidän iloanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'Sinä päivänä ette kysy minulta mitään. Totisesti, totisesti sanon teille: mitä tahansa anottekin Isältä minun nimessäni, hän antaa sen teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Tähän asti ette ole anoneet mitään minun nimessäni. Anokaa, niin saatte, jotta teidän ilonne olisi täydellinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Tämän olen puhunut teille kuvauksilla, mutta tulee aika, jolloin en puhu teille enää kuvauksilla, vaan julistan teille avoimesti Isästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'Sinä päivänä anotte minun nimessäni, enkä sano teille, että olen rukoileva Isää teidän edestänne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'sillä Isä itse rakastaa teitä, sen tähden että olette minua rakastaneet ja uskoneet minun lähteneen Jumalan luota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Olen lähtenyt Isästä ja tullut maailmaan. Nyt jätän maailman ja menen takaisin Isän luo.\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Hänen opetuslapsensa sanoivat: \"Katso, nyt puhut avoimesti etkä käytä mitään kuvausta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Nyt me tiedämme, että tiedät kaiken, etkä tarvitse, että kukaan sinulta kysyy. Sen tähden uskomme sinun lähteneen Jumalan luota.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Jeesus vastasi heille: \"Nyt uskotte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Katso, tulee hetki ja on jo tullut, jolloin teidät hajotetaan kukin tahollenne ja jätätte minut yksin. En kuitenkaan ole yksin, sillä Isä on minun kanssani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Tämän olen puhunut teille, että teillä olisi minussa rauha. Maailmassa teillä on ahdistus, mutta olkaa turvallisin mielin: minä olen voittanut maailman.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Tämän Jeesus puhui, nosti silmänsä taivasta kohti ja sanoi: \"Isä, hetki on tullut, kirkasta Poikasi, että Poikasi kirkastaisi sinut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'Koska sinä olet antanut hänen valtaansa kaiken lihan, jotta hän antaisi iankaikkisen elämän kaikille, jotka olet hänelle antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Mutta tämä on iankaikkinen elämä, että he tuntevat sinut, ainoan oikean Jumalan, ja hänet, jonka olet lähettänyt, Jeesuksen Kristuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Minä olen kirkastanut sinut maan päällä: olen täyttänyt sen työn, jonka annoit tehtäväkseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'Nyt, Isä, kirkasta sinä minut luonasi sillä kirkkaudella, joka minulla oli sinun luonasi, ennen kuin maailma olikaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Olen ilmoittanut sinun nimesi ihmisille, jotka annoit minulle maailmasta. He olivat sinun, ja annoit heidät minulle, ja he ovat pitäneet sinun sanasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Nyt he ovat tulleet tietämään, että kaikki, minkä olet minulle antanut, on sinulta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Sillä ne sanat, jotka minulle annoit, olen antanut heille. He ovat ottaneet ne vastaan ja ovat totisesti tulleet tietämään minun lähteneen sinun luotasi ja uskovat, että sinä olet minut lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Minä rukoilen heidän edestään. En rukoile maailman edestä, vaan niiden edestä, jotka sinä olet minulle antanut, koska he ovat sinun –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'ja kaikki minun omani ovat sinun, ja sinun omasi ovat minun – ja olen kirkastettu heissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'En ole enää maailmassa, mutta he ovat maailmassa, ja minä tulen sinun luoksesi. Pyhä Isä, varjele heidät nimessäsi, jonka olet minulle antanut, että he olisivat yksi kuten mekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Kun minä olin heidän kanssaan, minä varjelin heidät nimessäsi, jonka olet minulle antanut, ja suojelin heitä, eikä heistä joutunut kadotetuksi yksikään muu kuin se kadotuksen lapsi, jotta Raamattu kävisi toteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Mutta nyt tulen luoksesi ja puhun tätä maailmassa, että heillä olisi minun iloni täydellisenä heissä itsessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Minä olen antanut heille sinun sanasi, ja maailma vihaa heitä, koska he eivät ole maailmasta, niin kuin en minäkään maailmasta ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'En rukoile, että ottaisit heidät pois maailmasta, vaan että sinä varjelisit heidät pahasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'He eivät ole maailmasta, niin kuin en minäkään maailmasta ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Pyhitä heidät totuudessa, sinun sanasi on totuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Niin kuin olet lähettänyt minut maailmaan, niin olen minäkin lähettänyt heidät maailmaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'ja minä pyhitän itseni heidän tähtensä, että hekin olisivat pyhitetyt totuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Mutta en rukoile ainoastaan näiden edestä, vaan myös niiden edestä, jotka heidän sanansa kautta uskovat minuun,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'että he kaikki olisivat yksi, niin kuin sinä, Isä, olet minussa ja minä sinussa, että hekin meissä olisivat, että maailma uskoisi, että sinä olet minut lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Minä olen antanut heille sen kirkkauden, jonka sinä annoit minulle, että he olisivat yksi, niin kuin me olemme yksi –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'minä heissä, ja sinä minussa – että he olisivat täydellisesti yksi, että maailma ymmärtäisi, että sinä olet minut lähettänyt ja rakastanut heitä, niin kuin olet minua rakastanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Isä, minä tahdon, että missä Minä olen, siellä nekin, jotka olet minulle antanut, olisivat kanssani, että he näkisivät kirkkauteni, jonka olet minulle antanut, koska olet rakastanut minua jo ennen maailman perustamista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Vanhurskas Isä, maailma ei ole sinua tuntenut, mutta minä tunnen sinut, ja nämä ovat tulleet tuntemaan, että sinä olet minut lähettänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Olen tehnyt sinun nimesi heille tunnetuksi ja teen vastakin tunnetuksi, että se rakkaus, jolla olet minua rakastanut, olisi heissä ja minä olisin heissä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Tämän puhuttuaan Jeesus lähti pois opetuslastensa kanssa Kidronin puron tuolle puolelle. Siellä oli puutarha, johon hän meni opetuslapsineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Mutta myös Juudas, joka hänet kavalsi, tiesi sen paikan, koska Jeesus ja hänen opetuslapsensa olivat usein kokoontuneet sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Juudas otti sotilasjoukon sekä ylipappien ja fariseusten palvelijoita ja tuli sinne soihdut, lamput ja aseet mukanaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Silloin Jeesus, joka tiesi kaiken, mikä oli kohtaava häntä, astui esiin ja sanoi heille: \"Ketä etsitte?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'He vastasivat hänelle: \"Jeesusta, Nasaretilaista.\" Jeesus sanoi heille: \" Minä olen.\" Juudas, joka hänet kavalsi, seisoi myös heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Kun hän siis sanoi heille: \" Minä olen \", he perääntyivät ja kaatuivat maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Hän kysyi taas heiltä: \"Ketä etsitte?\" He sanoivat: \"Jeesusta, Nasaretilaista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jeesus vastasi: \"Minä sanoin jo teille, että Minä olen. Jos siis minua etsitte, sallikaa näiden mennä\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'että toteutuisi se sana, jonka hän oli sanonut: \"En ole kadottanut ketään niistä, jotka olet minulle antanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Simon Pietari, jolla oli miekka, veti sen esiin ja iski ylipapin palvelijaa ja sivalsi häneltä pois oikean korvan. Palvelijan nimi oli Malkus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Jeesus sanoi Pietarille: \"Pistä miekkasi tuppeen. Enkö joisi sitä maljaa, jonka Isä on antanut minulle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Sotilasjoukko, tuhannenpäällikkö ja juutalaisten palvelijat ottivat Jeesuksen kiinni ja sitoivat hänet');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'ja veivät hänet ensiksi Hannaan luo, sillä hän oli Kaifaksen appi, ja Kaifas oli sinä vuonna ylipappina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Mutta Kaifas oli antanut juutalaisille sen neuvon, että on hyödyllistä, että yksi ihminen kuolee kansan edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Jeesusta seurasi Simon Pietari ja eräs toinen opetuslapsi. Tämä opetuslapsi oli ylipapin tuttava ja meni Jeesuksen kanssa sisään ylipapin pihaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Mutta Pietari seisoi portilla ulkona. Se toinen opetuslapsi, joka oli ylipapin tuttava, meni ulos ja puhutteli portinvartijaa ja toi Pietarin sisäpuolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Palvelustyttö, joka vartioi porttia, sanoi Pietarille: \"Etkö sinäkin ole tuon miehen opetuslapsia?\" Hän sanoi: \"En ole.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Palvelijat ja käskyläiset olivat tehneet hiilivalkean, koska oli kylmä, ja seisoivat ja lämmittelivät. Myös Pietari seisoi heidän kanssaan lämmittelemässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Ylipappi kyseli Jeesukselta hänen opetuslapsistaan ja opistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jeesus vastasi hänelle: \"Minä olen julkisesti puhunut maailmalle. Minä olen aina opettanut synagogassa ja pyhäkössä, joihin kaikki juutalaiset kokoontuvat, enkä ole puhunut mitään salassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Miksi minulta kysyt? Kysy niiltä, jotka ovat kuulleet, mitä olen heille puhunut. Katso, he tietävät, mitä olen sanonut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Mutta kun hän oli tämän sanonut, löi eräs palvelija, joka seisoi vieressä, häntä kasvoihin sanoen: \"Niinkö sinä vastaat ylipapille?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Jeesus vastasi hänelle: \"Jos puhuin pahasti, näytä toteen, että se on pahaa, mutta jos oikein, miksi minua lyöt?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Hannas lähetti hänet sidottuna ylipappi Kaifaan luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Mutta Simon Pietari seisoi lämmittelemässä. He sanoivat hänelle: \"Etkö sinäkin ole hänen opetuslapsiaan?\" Hän kielsi ja sanoi: \"En ole.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Eräs ylipapin palvelijoista, sen sukulainen, jolta Pietari oli sivaltanut pois korvan, sanoi: \"Enkö minä nähnyt sinua puutarhassa hänen kanssaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Niin Pietari taas kielsi, ja siinä samassa lauloi kukko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'He veivät Jeesuksen Kaifaan luota päämajaan, ja oli varhainen aamu. Mutta itse he eivät menneet sisälle päämajaan, etteivät saastuisi, vaan voisivat syödä pääsiäislammasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Pilatus meni ulos heidän luokseen ja sanoi: \"Mikä syytös teillä on tätä miestä vastaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'He vastasivat ja sanoivat hänelle: \"Jos tämä ei olisi pahantekijä, emme olisi luovuttaneet häntä sinulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Pilatus sanoi heille: \"Ottakaa te hänet ja tuomitkaa hänet lakinne mukaan.\" Juutalaiset sanoivat hänelle: \"Meidän ei ole lupa tappaa ketään\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'että se Jeesuksen sana kävisi toteen, jonka hän oli sanonut antaessaan tietää, millaisella kuolemalla hän oli kuoleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Pilatus meni taas sisälle päämajaan ja kutsui Jeesuksen ja sanoi hänelle: \"Oletko sinä juutalaisten kuningas?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jeesus vastasi hänelle: \"Itsestäsikö sen sanot, vai ovatko muut sanoneet sen sinulle minusta?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilatus vastasi: \"Olenko minä juutalainen? Oma kansasi ja ylipapit ovat antaneet sinut minulle. Mitä olet tehnyt?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jeesus vastasi: \"Minun kuninkuuteni ei ole tästä maailmasta. Jos minun kuninkuuteni olisi tästä maailmasta, palvelijani olisivat taistelleet, ettei minua olisi annettu juutalaisten käsiin, mutta nyt minun kuninkuuteni ei ole täältä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Pilatus sanoi hänelle: \"Sinä siis olet kuningas?\" Jeesus vastasi: \"Sinä sen sanot, että minä olen kuningas. Sitä varten minä olen syntynyt ja sitä varten tullut maailmaan, että todistaisin totuuden puolesta. Jokainen, joka on totuudesta, kuulee minun ääneni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Pilatus sanoi hänelle: \"Mikä on totuus?\" Sen sanottuaan hän taas meni ulos juutalaisten luo ja sanoi heille: \"Minä en löydä hänestä mitään syytä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Mutta teillä on tapana, että vapautan teille yhden pääsiäisenä. Tahdotteko siis, että vapautan teille juutalaisten kuninkaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'He huusivat taas sanoen: \"Älä häntä, vaan Barabbas!\" Mutta Barabbas oli ryöväri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Silloin Pilatus otti Jeesuksen ja ruoskitti hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Sotamiehet väänsivät kruunun orjantappuroista, panivat sen hänen päähänsä ja kietoivat hänet purppuraviittaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'ja sanoivat: \"Terve, juutalaisten kuningas\", ja löivät häntä kasvoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Pilatus meni taas ulos ja sanoi heille: \"Katso, tuon hänet ulos teille tietääksenne, etten löydä hänestä mitään syytä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Niin Jeesus tuli ulos, orjantappurakruunu päässä ja purppuraviitta yllä. Pilatus sanoi heille: \"Katso ihmistä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Kun siis ylipapit ja palvelijat näkivät hänet, he huusivat sanoen: \"Ristiinnaulitse, ristiinnaulitse!\" Pilatus sanoi heille: \"Ottakaa te hänet ja ristiinnaulitkaa, sillä minä en löydä hänestä mitään syytä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Juutalaiset vastasivat hänelle: \"Meillä on laki, ja lain mukaan hänen pitää kuolla, koska hän on tehnyt itsensä Jumalan Pojaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Kun nyt Pilatus kuuli tämän sanan, hän pelkäsi vielä enemmän');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'ja meni taas sisälle päämajaan ja sanoi Jeesukselle: \"Mistä sinä olet?\" Mutta Jeesus ei vastannut hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Pilatus sanoi hänelle: \"Etkö puhu minulle? Etkö tiedä, että minulla on valta ristiinnaulita sinut ja minulla on valta päästää sinut vapaaksi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jeesus vastasi: \"Sinulla ei olisi mitään valtaa minuun, ellei sitä olisi annettu sinulle ylhäältä. Sen tähden sen synti on suurempi, joka luovutti minut sinulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Tämän tähden Pilatus koetti vapauttaa hänet. Mutta juutalaiset huusivat sanoen: \"Jos päästät hänet, et ole keisarin ystävä. Jokainen, joka tekee itsensä kuninkaaksi, asettuu keisaria vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Kun Pilatus kuuli nämä sanat, hän antoi viedä Jeesuksen ulos ja istuutui tuomarinistuimelle, paikalle, jonka nimi on Lito-stroton, hepreaksi Gabbata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Oli pääsiäisen valmistuspäivä, noin kuudes tunti. Hän sanoi juutalaisille: \"Katso, teidän kuninkaanne!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'He huusivat: \"Vie pois, vie pois, ristiinnaulitse hänet!\" Pilatus sanoi heille: \"Onko minun ristiinnaulittava teidän kuninkaanne?\" Ylipapit vastasivat: \"Meillä ei ole kuningasta, vaan keisari.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Silloin hän luovutti hänet heille ja antoi ristiinnaulittavaksi, ja he ottivat Jeesuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Kantaen itse omaa ristiään hän meni ulos niin sanotulle Pääkallonpaikalle, jota sanotaan hepreaksi Golgataksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Siellä he ristiinnaulitsivat hänet ja hänen kanssaan kaksi muuta, yhden kummallekin puolelle, ja Jeesuksen keskelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Pilatus kirjoitti myös päällekirjoituksen ja kiinnitti sen ristiin. Siihen oli näin kirjoitettu: \"Jeesus Nasaretilainen, juutalaisten kuningas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Tämän päällekirjoituksen lukivat monet juutalaiset, sillä paikka, jossa Jeesus ristiinnaulittiin, oli lähellä kaupunkia. Se oli kirjoitettu hepreaksi, latinaksi ja kreikaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Juutalaisten ylipapit sanoivat Pilatukselle: \"Älä kirjoita: \'Juutalaisten kuningas\', vaan että hän on sanonut: \'Olen juutalaisten kuningas.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilatus vastasi: \"Minkä kirjoitin, sen kirjoitin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Kun sotamiehet olivat ristiinnaulinneet Jeesuksen, he ottivat hänen vaatteensa ja jakoivat ne neljään osaan, kullekin sotamiehelle osansa, sekä paidan. Mutta paita oli saumaton, kauttaaltaan ylhäältä asti kudottu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Sen tähden he sanoivat toisilleen: \"Älkäämme leikatko sitä rikki, vaan heittäkäämme siitä arpaa, kenen se on oleva\", että Raamattu kävisi toteen: \"He jakoivat keskenään vaatteeni ja heittivät puvustani arpaa.\" Sotamiehet tekivät niin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'Mutta Jeesuksen ristin ääressä seisoivat hänen äitinsä ja hänen äitinsä sisar Maria, Kloopaan vaimo, ja Maria Magdaleena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Kun Jeesus näki äitinsä ja sen opetuslapsen, jota hän rakasti, seisovan siinä vieressä, hän sanoi äidilleen: \"Nainen, katso, poikasi!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Sitten hän sanoi opetuslapselle: \"Katso, äitisi!\" Siitä hetkestä opetuslapsi otti hänet luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Sen jälkeen, kun Jeesus tiesi, että kaikki oli jo täytetty, hän sanoi, että Raamattu kävisi toteen: \"Minun on jano.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Siinä oli astia täynnä hapanviiniä. Niin he täyttivät hapanviinillä sienen ja panivat sen iisoppikorren päähän ja ojensivat sen hänen suunsa eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Kun nyt Jeesus oli ottanut hapanviinin, hän sanoi: \"Se on täytetty\", ja kallisti päänsä ja antoi henkensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Koska silloin oli valmistuspäivä, niin – etteivät ruumiit jäisi ristille sapatiksi, sillä se sapatinpäivä oli suuri – juutalaiset pyysivät Pilatukselta, että ristiinnaulittujen sääriluut rikottaisiin ja ruumiit otettaisiin alas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Niin sotamiehet tulivat ja rikkoivat sääriluut ensin toiselta ja sitten toiselta hänen kanssaan ristiinnaulitulta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Mutta kun he tulivat Jeesuksen luo ja näkivät, että hän oli jo kuollut, he eivät rikkoneet hänen luitaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'vaan yksi sotamiehistä puhkaisi keihäällä hänen kylkensä, ja siitä vuoti heti verta ja vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Joka sen näki, on sen todistanut, ja hänen todistuksensa on tosi, ja hän tietää totta puhuvansa, että te uskoisitte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Sillä tämä tapahtui, että Raamattu kävisi toteen: \"Älköön häneltä luuta rikottako.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'Vielä Raamattu sanoo toisessa kohdassa: \"He luovat katseensa häneen, jonka ovat lävistäneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Mutta sen jälkeen Joosef, joka oli Arimatiasta ja oli Jeesuksen opetuslapsi, vaikka salaa, juutalaisten pelosta, pyysi Pilatukselta saada ottaa Jeesuksen ruumiin, ja Pilatus salli sen. Hän tuli ja otti Jeesuksen ruumiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Tuli myös Nikodeemus, joka ensi kerran oli tullut yöllä Jeesuksen luo, ja toi mirhan ja aloen seosta noin sata naulaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'He ottivat Jeesuksen ruumiin ja käärivät sen hyvänhajuisten yrttien kanssa käärinliinoihin, niin kuin juutalaisilla on tapana haudata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Sillä paikalla, missä hänet ristiinnaulittiin, oli puutarha, ja puutarhassa uusi hauta, johon ei vielä ollut pantu ketään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Siihen he nyt panivat Jeesuksen, koska oli juutalaisten valmistuspäivä ja hauta oli lähellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'Mutta viikon ensimmäisenä päivänä Maria Magdaleena meni varhain, kun vielä oli pimeä, haudalle ja näki, että kivi oli otettu pois haudan suulta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Hän riensi pois ja tuli Simon Pietarin luo ja sen toisen opetuslapsen luo, joka oli Jeesukselle rakas, ja sanoi heille: \"Ovat ottaneet Herran pois haudasta, emmekä tiedä, mihin ovat panneet hänet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Pietari ja se toinen opetuslapsi lähtivät ja menivät haudalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'He juoksivat molemmat yhdessä, mutta se toinen opetuslapsi juoksi edellä Pietaria nopeammin ja saapui ensin haudalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'Kun hän kurkisti sisälle, hän näki käärinliinat. Kuitenkaan hän ei mennyt sisälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Simon Pietarikin tuli hänen perässään ja meni sisälle hautaan ja näki käärinliinat siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'Hikiliina, joka oli ollut hänen päässään, ei ollut käärinliinojen joukossa, vaan erillään toisessa paikassa kokoon käärittynä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Silloin toinenkin opetuslapsi, joka oli tullut ensiksi haudalle, meni sisään, näki ja uskoi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Sillä he eivät vielä ymmärtäneet Raamattua, että hänen piti nousta kuolleista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Opetuslapset menivät takaisin majapaikkaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Mutta Maria seisoi haudan edessä ja itki ulkopuolella. Kun hän näin itki, hän kurkisti hautaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'ja näki kaksi enkeliä valkoisissa vaatteissa istumassa, toisen pääpuolessa ja toisen jalkapuolessa, siinä, missä Jeesuksen ruumis oli maannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Nämä sanoivat hänelle: \"Nainen, mitä itket?\" Hän sanoi heille: \"Ovat ottaneet pois Herrani, enkä tiedä, mihin ovat panneet hänet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'Tämän sanottuaan hän kääntyi taaksepäin ja näki Jeesuksen seisovan siinä, eikä tiennyt, että se oli Jeesus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Jeesus sanoi hänelle: \"Nainen, mitä itket? Ketä etsit?\" Tämä luuli häntä puutarhuriksi ja sanoi hänelle: \"Herra, jos sinä olet kantanut hänet pois, sano minulle, mihin olet hänet pannut, niin minä otan hänet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Jeesus sanoi hänelle: \"Maria!\" Tämä kääntyi ja sanoi hänelle hepreaksi: \"Rabbuuni!\" se on: opettaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Jeesus sanoi hänelle: \"Älä koske minuun, sillä en ole vielä mennyt ylös Isäni luo, mutta mene veljieni luo ja sano heille, että menen ylös, minun Isäni luo ja teidän Isänne luo, minun Jumalani luo ja teidän Jumalanne luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Maria Magdaleena meni ja ilmoitti opetuslapsille, että hän oli nähnyt Herran ja että Herra oli hänelle näin sanonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Samana päivänä, viikon ensimmäisenä, myöhään illalla, kun opetuslapset olivat koolla lukittujen ovien takana juutalaisten pelosta, Jeesus tuli ja seisoi heidän keskellään ja sanoi heille: \"Rauha teille!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Sen sanottuaan hän näytti heille kätensä ja kylkensä. Opetuslapset iloitsivat nähdessään Herran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Niin Jeesus sanoi heille jälleen: \"Rauha teille! Niin kuin Isä on lähettänyt minut, niin lähetän minäkin teidät.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Tämän sanottuaan hän puhalsi heidän päälleen ja sanoi heille: \"Ottakaa Pyhä Henki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Joiden synnit annatte anteeksi, niille ne ovat anteeksi annetut. Joiden synnit pidätätte, niille ne ovat pidätetyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Mutta Tuomas, jota sanottiin Didymokseksi, yksi niistä kahdestatoista, ei ollut heidän kanssaan, kun Jeesus tuli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Muut opetuslapset sanoivat hänelle: \"Näimme Herran.\" Mutta hän sanoi heille: \"Ellen näe hänen käsissään naulojen jälkiä ja pistä sormeani naulojen sijoihin ja pistä kättäni hänen kylkeensä, en usko.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Kahdeksan päivän kuluttua hänen opetuslapsensa olivat taas sisällä, ja Tuomas oli heidän kanssaan. Jeesus tuli ovien ollessa lukittuina ja seisoi heidän keskellään ja sanoi: \"Rauha teille!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Sitten hän sanoi Tuomaalle: \"Ojenna sormesi tänne ja katso minun käsiäni, ja ojenna kätesi ja pistä se kylkeeni, äläkä ole epäuskoinen, vaan uskova.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Tuomas vastasi ja sanoi hänelle: \"Minun Herrani ja minun Jumalani!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Jeesus sanoi hänelle: \"Sen tähden, että minut näit, sinä uskot. Autuaat ne, jotka eivät näe ja uskovat!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Paljon muitakin tunnustekoja, joita ei ole kirjoitettu tähän kirjaan, Jeesus teki opetuslastensa nähden,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'mutta nämä ovat kirjoitetut, että uskoisitte, että Jeesus on Kristus, Jumalan Poika, ja että teillä uskoessanne olisi elämä hänen nimessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Sen jälkeen Jeesus taas ilmestyi opetuslapsilleen Tiberiaan järven rannalla. Hän ilmestyi näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Simon Pietari, Tuomas, jota sanottiin Didymokseksi, Natanael, joka oli Galilean Kaanasta, Sebedeuksen pojat sekä kaksi muuta hänen opetuslastaan olivat yhdessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Simon Pietari sanoi heille: \"Lähden kalaan.\" He sanoivat hänelle: \"Mekin lähdemme kanssasi.\" Niin he lähtivät ja astuivat heti veneeseen, mutta eivät saaneet sinä yönä mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Kun oli jo aamu, Jeesus seisoi rannalla. Opetuslapset eivät kuitenkaan tienneet, että se oli Jeesus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Jeesus sanoi heille: \"Lapset, onko teillä mitään syötävää?\" He vastasivat hänelle: \"Ei.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Hän sanoi heille: \"Heittäkää verkko oikealle puolelle venettä, niin saatte.\" He heittivät verkon, mutta eivät jaksaneet vetää sitä kalojen paljouden tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Silloin se opetuslapsi, jota Jeesus rakasti, sanoi Pietarille: \"Se on Herra.\" Kun Simon Pietari kuuli, että se oli Herra, hän vyötti ympärilleen viittansa, sillä hän oli ilman vaatteita, ja heittäytyi järveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Mutta muut opetuslapset tulivat veneellä ja vetivät perässään verkkoa kaloineen, sillä he eivät olleet maasta kauempana kuin noin kahdensadan kyynärän päässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Kun he astuivat maihin, he näkivät siellä hiilloksen ja kalan sen päällä sekä leipää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Jeesus sanoi heille: \"Tuokaa tänne kaloja, joita nyt saitte.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Niin Simon Pietari astui veneeseen ja veti maalle verkon täynnä suuria kaloja, sata viisikymmentä kolme. Vaikka niitä oli niin paljon, verkko ei revennyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Jeesus sanoi heille: \"Tulkaa aamiaiselle.\" Mutta kukaan opetuslapsista ei rohjennut kysyä häneltä: \"Kuka sinä olet?\", koska he tiesivät, että se oli Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Jeesus meni, otti leivän ja antoi heille, ja samoin kalan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Tämä oli jo kolmas kerta, jolloin Jeesus noustuaan kuolleista ilmestyi opetuslapsilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Kun he olivat syöneet, Jeesus sanoi Simon Pietarille: \"Simon, Joonan poika, rakastatko minua enemmän kuin nämä?\" Hän vastasi hänelle: \"Rakastan, Herra, sinä tiedät, että olet minulle rakas.\" Hän sanoi hänelle: \"Ruoki minun karitsoitani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Hän sanoi hänelle taas toistamiseen: \"Simon, Joonan poika, rakastatko minua?\" Hän vastasi hänelle: \"Rakastan, Herra, sinä tiedät, että olet minulle rakas.\" Hän sanoi hänelle: \"Kaitse minun lampaitani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Hän sanoi hänelle kolmannen kerran: \"Simon, Joonan poika, olenko minä sinulle rakas?\" Pietari tuli murheelliseksi siitä, että hän kolmannen kerran sanoi hänelle: \"Rakastatko minua?\" ja vastasi hänelle: \"Herra, sinä tiedät kaikki. Sinä tiedät, että rakastan sinua.\" Jeesus sanoi hänelle: \"Ruoki minun lampaitani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Totisesti, totisesti sanon sinulle: kun olit nuori, vyötit itsesi ja kuljit, minne tahdoit. Mutta kun vanhenet, ojennat kätesi, ja sinut vyöttää toinen ja vie sinut, minne et tahdo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Mutta sen hän sanoi osoittaen, millaisella kuolemalla Pietari oli kirkastava Jumalaa. Tämän sanottuaan hän lausui hänelle: \"Seuraa minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Pietari kääntyi ja näki sen opetuslapsen seuraavan, jota Jeesus rakasti ja joka myös oli aterioitaessa nojannut hänen rintaansa vasten ja sanonut: \"Herra, kuka kavaltajasi on?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Kun Pietari näki hänet, hän sanoi Jeesukselle: \"Herra, kuinka hänen käy?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Jeesus sanoi hänelle: \"Jos tahtoisin, että hän jää tänne siihen asti, kunnes tulen, mitä se sinua koskee? Seuraa sinä minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Niin sellainen puhe levisi veljien keskuuteen, ettei se opetuslapsi kuole. Mutta Jeesus ei sanonut hänelle, ettei hän kuole, vaan: \"Jos tahtoisin, että hän jää tänne siihen asti, kunnes tulen, mitä se sinua koskee?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Tämä on se opetuslapsi, joka todistaa näistä ja on nämä kirjoittanut, ja tiedämme, että hänen todistuksensa on tosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'On paljon muutakin, mitä Jeesus teki, ja jos se kohta kohdalta kirjoitettaisiin, luulen, etteivät koko maailmaan mahtuisi ne kirjat, jotka pitäisi kirjoittaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Ensimmäisessä puheessani kirjoitin, oi Teofilos, kaikesta, mitä Jeesus alkoi tehdä ja opettaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'siihen päivään asti, jona hänet otettiin ylös, hänen annettuaan Pyhän Hengen kautta käskyn apostoleille, jotka hän oli valinnut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'ja joille hän myös kärsimisensä jälkeen monin kiistattomin todistein osoitti elävänsä ilmestyen heille neljänkymmenen päivän aikana ja puhuen Jumalan valtakunnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Kun hän oli yhdessä heidän kanssaan, hän käski heitä ja sanoi: \"Älkää lähtekö Jerusalemista, vaan odottakaa Isältä sen lupauksen täyttymistä, jonka kuulitte minulta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Sillä Johannes kastoi vedellä, mutta teidät kastetaan Pyhällä Hengellä, ei kauan näiden päivien jälkeen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Ollessaan koolla he kysyivät häneltä sanoen: \"Herra, tälläkö ajalla rakennat jälleen Israelille valtakunnan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Hän sanoi heille: \"Teidän asianne ei ole tietää aikoja eikä hetkiä, jotka Isä on omassa vallassaan asettanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'vaan saatte voiman, kun Pyhä Henki tulee päällenne, ja tulette olemaan minun todistajani sekä Jerusalemissa että koko Juudeassa, Samariassa ja aina maan ääriin saakka.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Kun hän oli tämän sanonut, hänet kohotettiin ylös heidän nähtensä, ja pilvi vei hänet pois heidän näkyvistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Kun he katselivat taivaalle hänen mennessään, katso, heidän luonaan seisoi kaksi miestä valkoisissa vaatteissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'Nämä sanoivat: \"Galilean miehet, mitä seisotte ja katsotte taivaalle? Tämä Jeesus, joka otettiin teiltä ylös taivaaseen, on tuleva samalla tavalla, kuin näitte hänen taivaaseen menevän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Silloin he palasivat Jerusalemiin vuorelta, jota kutsutaan Öljymäeksi ja joka on lähellä Jerusalemia, sapatinmatkan päässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Kun he olivat tulleet kaupunkiin, he menivät siihen yläsaliin, jossa he oleskelivat: Pietari, Johannes, Jaakob, Andreas, ja Filippos, Tuomas, Bartolomeos, Matteus ja Jaakob Alfeoksen poika, Simon, kiivailija, ja Juuda Jaakobin poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Nämä kaikki pysyivät yksimielisesti rukouksessa ja anomisessa naisten kanssa ja Marian, Jeesuksen äidin, kanssa ja Jeesuksen veljien kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'Niinä päivinä Pietari nousi opetuslasten keskellä, kun oli väkeä koolla noin sadan kahdenkymmenen nimen joukko, ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, '\"Miehet, veljet, sen Raamatun sanan piti käydä toteen, jonka Pyhä Henki on Daavidin suun kautta edeltä puhunut Juudaksesta, joka rupesi Jeesuksen kiinniottajien oppaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Sillä hän oli meidän joukkoomme luettu ja oli saanut osalleen tämän viran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Hän hankki itselleen pellon väärintekonsa palkalla, ja hän suistui alas ja halkesi keskeltä, niin että kaikki hänen sisälmyksensä valuivat ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Se tuli kaikkien Jerusalemin asukkaiden tietoon, ja niin peltoa kutsutaan heidän omalla kielellään Akeldamaksi, se on: Veripelloksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Sillä Psalmien kirjassa on kirjoitettuna: \'Tulkoon hänen talonsa autioksi, älköönkä siinä olko asukasta\', ja: \'Ottakoon toinen [mies] hänen kaitsijantoimensa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Niin pitää siis yhden niistä miehistä, jotka ovat vaeltaneet kanssamme koko sen ajan, jona Herra Jeesus kävi sisään ja ulos luonamme,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'Johanneksen kasteesta alkaen siihen päivään asti, jona hänet otettiin meiltä ylös, tulla yhdeksi hänen ylösnousemisensa todistajaksi meidän kanssamme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'He panivat ehdolle kaksi, Joosefin, jota sanottiin Barsabbaaksi, lisänimeltä Justukseksi, ja Mattiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'He rukoilivat ja sanoivat: \"Herra, sinä, joka tunnet kaikkien sydämet, osoita, kumman näistä kahdesta olet valinnut');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'ottamaan sen osan tässä palveluksessa ja apostolinvirassa, josta Juudas luopui mennäkseen omaan paikkaansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'He heittivät heistä arpaa, ja arpa lankesi Mattiaalle, ja hänet luettiin niiden yhdentoista kanssa apostolien joukkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Kun helluntaipäivä oli tullut, he olivat kaikki yksimielisesti yhdessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Silloin tuli yhtäkkiä humaus taivaasta, niin kuin olisi käynyt kova tuulenpuuska, ja se täytti koko talon, jossa he istuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'He näkivät ikään kuin tulisia kieliä, jotka jakaantuivat ja asettuivat heidän itse kunkin päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'He tulivat kaikki Pyhällä Hengellä täytetyiksi ja alkoivat puhua muilla kielillä, sen mukaan mitä Henki antoi heille puhuttavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Jerusalemissa asui juutalaisia, jumalaapelkääviä miehiä, kaikista kansoista, mitä taivaan alla on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Kun tämä ääni kuului, kokoontui paljon kansaa. He olivat ihmeissään, sillä kukin kuuli heidän puhuvan hänen omaa kieltään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'He hämmästyivät ja ihmettelivät sanoen: \"Katso, eivätkö nämä kaikki, jotka puhuvat, ole galilealaisia?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Kuinka me kuulemme kukin sen maan kieltä, jossa olemme syntyneet?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Me parttilaiset, meedialaiset, eelamilaiset ja me, jotka asumme Mesopotamiassa, Juudeassa ja Kappadokiassa, Pontossa ja Aasiassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Frygiassa ja Pamfyliassa, Egyptissä ja me, jotka olemme Libyasta Kyrenen seudulta, ja täällä oleskelevat roomalaiset, juutalaiset ja käännynnäiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'kreetalaiset ja arabialaiset, kuulemme heidän puhuvan meidän kielillämme Jumalan suuria tekoja.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'He olivat kaikki aivan ihmeissään eivätkä tienneet, mitä ajatella, ja sanoivat toinen toiselleen: \"Mitä tämä oikein on?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Mutta toiset sanoivat pilkaten: \"He ovat täynnä makeaa viiniä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Pietari astui esiin niiden yhdentoista kanssa, korotti äänensä ja puhui heille: \"Miehet, juutalaiset ja kaikki Jerusalemissa asuvat, olkoon tämä teille tiettävä, ja ottakaa sanani korviinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Eivät nämä ole juovuksissa, niin kuin te oletatte, sillä nyt on vasta kolmas tunti päivästä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'vaan tämä on se, mikä on sanottu profeetta Jooelin kautta:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, '\'Tapahtuu viimeisinä päivinä, sanoo Jumala, että vuodatan Henkeni kaiken lihan päälle, ja teidän poikanne ja tyttärenne ennustavat, ja nuorukaisenne näkyjä näkevät, ja vanhuksenne unia uneksivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'Myös palvelijoitteni ja palvelijattarieni päälle niinä päivinä vuodatan Henkeni, ja he profetoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'Annan näkyä ihmeitä ylhäällä taivaalla ja merkkejä alhaalla maan päällä, verta, tulta ja savupatsaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Aurinko muuttuu pimeydeksi ja kuu vereksi, ennen kuin Herran päivä tulee, se suuri ja julkinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'Tapahtuu, että jokainen, joka huutaa avuksi Herran nimeä, pelastuu.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Te Israelin miehet, kuulkaa nämä sanat: Jeesuksen, Nasaretilaisen, sen miehen, josta Jumala todisti teille voimallisilla teoilla, ihmeillä ja merkeillä, joita Jumala hänen kauttaan teki teidän keskellänne, kuten itse tiedätte,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'hänet, joka teille luovutettiin, Jumalan säätämän päätöksen ja edeltätietämisen mukaan, te laista tietämättömien miesten kätten kautta naulasitte ristiin ja tapoitte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Hänet Jumala herätti ja päästi kuoleman kivuista, koska ei ollutkaan mahdollista, että kuolema olisi voinut pitää hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Sillä Daavid sanoo hänestä: \'Näen alati Herran edessäni, sillä hän on oikealla puolellani, etten horjahtaisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Sen tähden sydämeni iloitsee ja kieleni riemuitsee, ja myös ruumiini on lepäävä toivossa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'sillä sinä et hylkää sieluani kuolemaan etkä salli Pyhäsi nähdä katoavaisuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Sinä teet minulle tiettäviksi elämän tiet, sinä täytät minut ilolla kasvojesi edessä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Miehet, veljet, on lupa sanoa rohkeasti teille kantaisä Daavidista, että hän on sekä kuollut että haudattu, onhan hänen hautansa keskuudessamme vielä tänäkin päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Koska hän nyt oli profeetta ja tiesi, että Jumala oli luvannut hänelle valalla vannoen herättävänsä Kristuksen hänen lanteittensa hedelmästä lihan mukaan istumaan hänen valtaistuimelleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'hän edeltä nähden puhui Kristuksen ylösnousemuksesta, sanoen, ettei hänen sieluaan jätetä kuoleman valtaan eikä hänen ruumiinsa näe katoavaisuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Tämän Jeesuksen Jumala on nostanut kuolleista, minkä todistajia me kaikki olemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Koska hän siis on Jumalan oikean käden voimalla korotettu ja on saanut Pyhän Hengen lupauksen Isältä, hän on vuodattanut sen, minkä te nyt näette ja kuulette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Sillä ei Daavid ole astunut ylös taivaisiin, vaan hän sanoo itse: \'Herra sanoi minun Herralleni: Istu minun oikealle puolelleni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'kunnes panen vihollisesi jalkojesi astinlaudaksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Varmasti tietäköön siis koko Israelin huone, että Jumala on hänet Herraksi ja Kristukseksi tehnyt, tämän Jeesuksen, jonka te ristiinnaulitsitte.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Tämän kuultuaan he saivat piston sydämeensä ja sanoivat Pietarille ja muille apostoleille: \"Miehet, veljet, mitä meidän pitää tehdä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Pietari sanoi heille: \"Muuttakaa mielenne ja tulkoon jokainen teistä kastetuksi Jeesuksen Kristuksen nimeen syntienne anteeksiantamiseksi, niin saatte Pyhän Hengen lahjan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Sillä teille ja teidän lapsillenne tämä lupaus on annettu, myös kaikille kaukana oleville, ketkä ikinä Herra, meidän Jumalamme, kutsuu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Monilla muillakin sanoilla hän vakaasti todisti ja kehotti heitä sanoen: \"Antakaa pelastaa itsenne tästä nurjasta sukukunnasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Ne, jotka nyt ottivat ilolla hänen sanansa vastaan, kastettiin, ja heitä tuli sinä päivänä lisää noin kolmetuhatta sielua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'He pysyivät apostolien opetuksessa, keskinäisessä yhteydessä, leivän murtamisessa ja rukouksissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'Jokaiselle sielulle tuli pelko. Monta ihmettä ja tunnustekoa tapahtui apostolien kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Kaikki, jotka uskoivat, olivat yhdessä ja pitivät kaikkea yhteisenä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'myivät maansa ja tavaransa ja jakelivat kaikille, sen mukaan kuin kukin tarvitsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'He olivat joka päivä yksimielisesti temppelissä, mursivat kodeissa leipää ja nauttivat ruokansa riemulla ja sydämen yksinkertaisuudella,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'kiittäen Jumalaa ja ollen kaiken kansan suosiossa. Herra lisäsi joka päivä pelastuneita seurakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Pietari ja Johannes menivät yhdessä temppeliin yhdeksännellä tunnilla, rukoushetkellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Silloin kannettiin sinne erästä miestä, joka oli ollut rampa äitinsä kohdusta ja jonka he joka päivä panivat temppelin niin sanotun Kauniin portin pieleen anomaan almua temppeliin meneviltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Nähdessään Pietarin ja Johanneksen menevän temppeliin, hän pyysi heiltä almua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Niin Pietari ja Johannes katsoivat häneen kiinteästi, ja Pietari sanoi: \"Katso meihin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Hän katsoi heitä tarkasti odottaen saavansa heiltä jotakin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Pietari sanoi: \"Hopeaa ja kultaa minulla ei ole, mutta annan sinulle sitä, mitä minulla on: Jeesuksen Kristuksen, Nasaretilaisen, nimessä, nouse ja kävele.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Hän tarttui hänen oikeaan käteensä ja nosti hänet ylös. Heti hänen jalkansa ja nilkkansa vahvistuivat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'ja hän hyppäsi pystyyn, seisoi ja käveli. Hän meni heidän kanssaan temppeliin, kävellen, hypellen ja ylistäen Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Kaikki kansa näki hänen kävelevän ja ylistävän Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'He tunsivat hänet siksi, joka oli istunut almuja saadakseen temppelin Kauniin portin pielessä ja olivat täynnä hämmästystä ja ihmetystä siitä, mitä hänelle oli tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Kun parannettu rampa pysytteli yhä Pietarin ja Johanneksen seurassa, kaikki kansa riensi hämmästyksen vallassa heidän luokseen niin sanottuun Salomon pylväskäytävään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Sen nähdessään Pietari rupesi puhumaan kansalle ja sanoi: \"Israelin miehet, mitä tätä ihmettelette, tai mitä meitä katselette, ikään kuin omalla voimallamme tai hurskaudellamme olisimme saaneet hänet kävelemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Aabrahamin ja Iisakin ja Jaakobin Jumala, meidän isiemme Jumala, on kirkastanut Poikansa Jeesuksen, jonka te annoitte alttiiksi ja kielsitte Pilatuksen edessä, kun tämä oli tuominnut hänet vapautettavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Te kielsitte Pyhän ja Vanhurskaan ja anoitte, että teille annettaisiin murhamies,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'mutta elämän ruhtinaan te tapoitte. Hänet Jumala on herättänyt kuolleista, minkä todistajia me olemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'Uskon turvautuessa hänen nimeensä on hänen nimensä vahvistanut tämän miehen, jonka näette ja tunnette, ja usko, jonka Jeesus vaikuttaa, on antanut hänelle hänen jäsentensä terveyden kaikkien teidän nähtenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Nyt, veljet, tiedän, että olette tietämättömyydestä tehneet sen, kuten hallitusmiehennekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Mutta Jumala on näin täyttänyt sen, minkä hän oli edeltä ilmoittanut kaikkien profeettojen suun kautta, että nimittäin hänen Voideltunsa oli kärsivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Muuttakaa siis mielenne ja kääntykää, että teidän syntinne pyyhittäisiin pois,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'että virvoituksen ajat tulisivat Herran kasvoista ja hän lähettäisi hänet, joka on teille edeltä julistettu, Kristuksen Jeesuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'Hänen piti ottaa taivas haltuunsa niihin aikoihin asti, jolloin kaikki jälleen asetetaan kohdalleen, mistä Jumala on ikiajoista saakka puhunut pyhien profeettojensa suun kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Sillä Mooses on sanonut isille: \'Profeetan, minun kaltaiseni, Herra Jumala on teille herättävä veljienne joukosta. Kuulkaa häntä kaikessa, mitä hän teille puhuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'On tapahtuva, että jokainen, joka ei kuule sitä Profeettaa, hävitetään kansasta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Kaikki profeetat Samuelista alkaen ja hänen jälkeensä, jotka ovat puhuneet, ovat myös ennustaneet näitä päiviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Te olette profeettojen ja sen liiton lapsia, jonka Jumala teki meidän isillemme sanoen Aabrahamille: \'Sinun siemenessäsi tulevat siunatuiksi kaikki maan sukukunnat.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Teille ensiksi Jumala on herättänyt Poikansa ja lähettänyt hänet siunaamaan teitä kääntyessänne kukin pois pahuudestanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Mutta heidän puhuessaan kansalle astuivat papit, temppelivartioston päällikkö ja saddukeukset heidän eteensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'närkästyneinä siitä, että he opettivat kansaa ja julistivat Jeesuksessa ylösnousemusta kuolleista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'he kävivät heihin käsiksi ja panivat heidät vankilaan seuraavaan päivään asti, sillä oli jo ilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Mutta monet niistä, jotka olivat kuulleet sanan, uskoivat, ja miesten luku oli noin viisituhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Seuraavana päivänä tapahtui, että heidän hallitusmiehensä, vanhimpansa ja kirjanoppineensa kokoontuivat Jerusalemissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'myös ylipappi Hannas sekä Kaifas, Johannes ja Aleksander sekä kaikki, jotka olivat ylipapillista sukua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'He asettivat heidät eteensä ja kysyivät: \"Millä voimalla tai kenen nimessä te tämän teitte?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Silloin Pietari täytettynä Pyhällä Hengellä sanoi heille: \"Kansan hallitusmiehet ja vanhimmat!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Jos meitä tänään kuulustellaan sairaalle miehelle tehdystä hyvästä teosta ja siitä, kenen kautta hän on parantunut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'olkoon teille kaikille ja koko Israelin kansalle tiettävä, että Jeesuksen Kristuksen, Nasaretilaisen, nimessä, hänen, jonka te ristiinnaulitsitte, mutta jonka Jumala herätti kuolleista, hänen nimessään tämä seisoo terveenä edessänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Hän on \'se kivi, jonka te, rakentajat, hylkäsitte, ja joka on tullut kulmakiveksi\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'eikä ole pelastusta yhdessäkään toisessa, sillä taivaan alla ei ole muuta nimeä ihmisille annettu, jossa meidän pitää pelastua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Mutta kun he näkivät Pietarin ja Johanneksen rohkeuden ja havaitsivat heidän olevan koulunkäymättömiä ja oppimattomia miehiä, he ihmettelivät. He tunsivat heidät niiksi, jotka olivat olleet Jeesuksen kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Nähdessään parannetun miehen seisovan heidän kanssaan he eivät voineet sanoa mitään vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'vaan käskettyään heidän astua ulos Neuvostosta he neuvottelivat keskenään');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'ja sanoivat: \"Mitä teemme näille miehille? Sillä se, että heidän kauttaan on tapahtunut ilmeinen ihme, on kaikille Jerusalemin asukkaille selviö, emmekä voi kieltää sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Mutta ettei se leviäisi laajemmalle kansaan, kieltäkäämme ankarasti heitä enää puhumasta tässä nimessä yhdellekään ihmiselle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'He kutsuivat heidät ja kielsivät heitä puhumasta ja opettamasta mitään Jeesuksen nimessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Mutta Pietari ja Johannes vastasivat heille ja sanoivat: \"Arvioikaa itse, onko oikein Jumalan edessä kuulla teitä enemmän kuin Jumalaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'mutta me emme voi olla puhumatta siitä, mitä olemme nähneet ja kuulleet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'He uhkasivat heitä vielä enemmän ja päästivät heidät, koska eivät kansan tähden keksineet, miten rangaista heitä, sillä kaikki ylistivät Jumalaa siitä, mitä oli tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Sillä mies, jossa tämä parantumisen ihme oli tapahtunut, oli jo yli neljäkymmentävuotias.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Päästyään vapaiksi he menivät omiensa luo ja kertoivat kaiken, mitä ylipapit ja vanhimmat olivat sanoneet heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Sen kuultuaan he yksimielisesti korottivat äänensä Jumalan puoleen ja sanoivat: \"Valtias, sinä, joka olet tehnyt taivaan, maan ja meren sekä kaikki, mitä niissä on!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'Sinä, joka Pyhän Hengen kautta, Daavidin, palvelijasi, suun kautta, olet puhunut: \'Miksi pakanat pauhaavat ja kansat turhia ajattelevat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Maan kuninkaat nousevat, ja ruhtinaat kokoontuvat yhteen Herraa ja hänen Voideltuaan vastaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Sillä totisesti, sinun pyhää Poikaasi Jeesusta vastaan, jonka sinä olet voidellut, kokoontuivat sekä Herodes että Pontius Pilatus pakanoiden ja Israelin sukukuntien kanssa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'tekemään kaiken, minkä sinun kätesi ja päätöksesi oli nähnyt edeltä tapahtuvan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Nyt, Herra, katso heidän uhkauksiaan ja anna palvelijoittesi kaikella rohkeudella puhua sanaasi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'ja ojenna kätesi, että sairaat parantuvat ja tunnustekoja ja ihmeitä tapahtuu pyhän Poikasi Jeesuksen nimen kautta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Kun he olivat rukoilleet, vapisi se paikka, jossa he olivat koolla, ja he kaikki täyttyivät Pyhällä Hengellä ja puhuivat Jumalan sanaa rohkeasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Uskovien suuressa joukossa oli yksi sydän ja yksi sielu. Kukaan heistä ei sanonut omakseen mitään, mitä hänellä oli, vaan kaikki oli heillä yhteistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Apostolit todistivat suurella voimalla Herran Jeesuksen ylösnousemuksesta, ja suuri armo oli heidän kaikkien päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Heidän joukossaan ei ollut myöskään ketään puutteenalaista, sillä kaikki, joilla oli maatiloja tai taloja, myivät ne ja toivat myytyjen hinnan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'ja panivat apostolien jalkojen juureen. Jokaiselle jaettiin sen mukaan, kuin hän tarvitsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Niinpä Jooses, jota apostolit kutsuivat Barnabaaksi – se on käännettynä: lohduttaja – leeviläinen, syntyisin Kyprokselta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'myi omistamansa pellon, toi rahat ja pani ne apostolien jalkojen juureen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Mutta eräs mies, nimeltä Ananias, myi maatilan yhdessä vaimonsa Safiran kanssa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'ja mies kätki vaimonsa tieten osan hinnasta, ja toi siitä osan ja pani apostolien jalkojen juureen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Mutta Pietari sanoi: \"Ananias, miksi saatana on täyttänyt sydämesi, niin että valehtelit Pyhälle Hengelle ja kätkit osan tilan hinnasta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Eikö se ollut omasi, ja eikö sen myynnistä saatu hintakin ollut vallassasi? Miksi päätit sydämessäsi tehdä tämän? Et ole valehdellut ihmisille, vaan Jumalalle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Kun Ananias kuuli nämä sanat, hän kaatui maahan ja heitti henkensä. Suuri pelko valtasi kaikki, jotka sen kuulivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Nuoret miehet nousivat, peittivät hänet, kantoivat pois ja hautasivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Noin kolmen tunnin kuluttua hänen vaimonsa tuli sisään tietämättä, mitä oli tapahtunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Pietari kysyi häneltä: \"Sano minulle: siihenkö hintaan te myitte maatilan?\" Hän vastasi: \"Kyllä, siihen hintaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Mutta Pietari sanoi hänelle: \"Miksi olette yhdessä päättäneet kiusata Herran Henkeä? Katso, niiden jalat, jotka hautasivat miehesi, ovat oven takana, ja he kantavat pois sinutkin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Hän kaatui heti hänen jalkojensa eteen ja heitti henkensä. Kun nuorukaiset tulivat sisään, he löysivät hänet kuolleena, kantoivat pois ja hautasivat hänet hänen miehensä viereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Suuri pelko valtasi koko seurakunnan ja kaikki ne, jotka tämän kuulivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Apostolien kätten kautta tapahtui kansan keskuudessa monta tunnustekoa ja ihmettä, ja he olivat kaikki yksimielisesti koolla Salomon pylväskäytävässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Muista kukaan ei uskaltanut liittyä heihin, mutta kansa piti heitä suuressa kunniassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Yhä enemmän tuli lisää Herraan uskovia, suuret joukot sekä miehiä että naisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'Sen tähden kannettiin sairaita kaduillekin ja pantiin vuoteille ja paareille, että Pietarin tullessa edes hänen varjonsa osuisi johonkuhun heistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Ympärillä olevista kaupungeista tuli Jerusalemiin paljon kansaa, ja he toivat sairaita ja saastaisten henkien vaivaamia, ja kaikki tulivat parannetuiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Ylipappi nousi ja kaikki, jotka olivat hänen kanssaan, saddukeusten lahko, ja he tulivat kiihkoa täyteen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'ja kävivät käsiksi apostoleihin ja panivat heidät yleiseen vankilaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Mutta yöllä avasi Herran enkeli vankilan ovet, vei heidät ulos ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, '\"Menkää, astukaa esiin ja puhukaa temppelissä kansalle kaikki tämän elämän sanat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Sen kuultuaan he menivät päivän koittaessa temppeliin ja opettivat. Ylipappi saapui ja ne, jotka olivat hänen kanssaan, ja he kutsuivat koolle Neuvoston ja israelilaisten vanhinten kokouksen, ja lähettivät hakemaan heitä vankilasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Mutta kun palvelijat tulivat vankilaan, he eivät löytäneet heitä sieltä, vaan palasivat takaisin ja kertoivat');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'sanoen: \"Havaitsimme tosin, että vankila oli hyvin tarkasti suljettu ja että vartijat seisoivat ovien edessä, mutta kun avasimme, emme löytäneet sisältä ketään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Kun ylipappi, temppelivartioston päällikkö ja muut korkeat papit kuulivat nämä sanat, he ihmettelivät, mitä tämä merkitsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Joku tuli ja kertoi heille sanoen: \"Katso, miehet, jotka panitte vankilaan, seisovat temppelissä ja opettavat kansaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Silloin päällikkö meni oikeudenpalvelijoiden kanssa ja nouti heidät, ei kuitenkaan väkisin, sillä he pelkäsivät, että kansa kivittäisi heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'He toivat heidät ja asettivat Neuvoston eteen, ja ylipappi kuulusteli heitä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'ja sanoi: \"Olemme kieltämällä kieltäneet teitä opettamasta tähän nimeen. Mutta katso, olette täyttäneet Jerusalemin opetuksellanne ja tahdotte saattaa päällemme tämän miehen veren.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Mutta Pietari ja apostolit vastasivat ja sanoivat: \"Enemmän tulee totella Jumalaa kuin ihmisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Meidän isiemme Jumala on herättänyt Jeesuksen, jonka te ripustitte puuhun ja surmasitte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Hänet Jumala on oikealla kädellään korottanut Päämieheksi ja Vapahtajaksi antamaan Israelille mielenmuutosta ja syntien anteeksiantamusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'Me olemme kaiken tämän todistajia, niin myös Pyhä Henki, jonka Jumala on antanut niille, jotka häntä tottelevat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Kun he sen kuulivat, se viilsi heidän sydäntään, ja he tahtoivat tappaa heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Mutta Neuvostossa nousi eräs fariseus, nimeltä Gamaliel, lainopettaja, jota koko kansa piti arvossa, ja hän käski viedä apostolit vähäksi aikaa ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'Hän sanoi Neuvostolle: \"Israelin miehet, varokaa, mitä aiotte tehdä näille miehille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Sillä ennen näitä päiviä nousi Teudas, sanoen jokin olevansa, ja häneen liittyi noin neljäsataa miestä. Hänet tapettiin, ja kaikki, jotka olivat häneen liittyneet, hajotettiin, ja asia raukesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Hänen jälkeensä nousi Juudas, galilealainen, verollepanon päivinä ja vietteli kansaa luopumaan puolelleen. Hänetkin hävitettiin, ja kaikki, jotka olivat liittyneet häneen, hajotettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Nyt sanon teille: pysykää erillänne näistä miehistä ja antakaa heidän olla. Jos näet tämä hanke eli tämä teko on ihmisistä, se raukeaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'mutta jos se on Jumalasta, ette voi kukistaa heitä, ettei teitä havaittaisi sotiviksi Jumalaa vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'He noudattivat hänen neuvoaan. He kutsuivat apostolit sisään, ruoskivat heitä ja kielsivät heitä puhumasta Jeesuksen nimeen ja päästivät heidät menemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'He lähtivät pois Neuvostosta iloissaan siitä, että heidät oli katsottu arvollisiksi kärsimään häväistystä hänen nimensä tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'Eivätkä he lakanneet opettamasta joka päivä temppelissä ja kodeissa ja julistamasta evankeliumia Kristuksesta Jeesuksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'Niinä päivinä, kun opetuslasten lukumäärä kasvoi, syntyi hellenisteissä nurinaa heprealaisia vastaan siitä, että heidän leskiään syrjittiin päivittäisessä palvelussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Ne kaksitoista kutsuivat kokoon opetuslasten joukon ja sanoivat: \"Ei ole sopivaa, että me laiminlyömme Jumalan sanan toimittaaksemme pöytäpalvelusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Valitkaa sen tähden, veljet, keskuudestanne seitsemän miestä, joista on hyvä todistus ja jotka ovat täynnä Henkeä ja viisautta, niin asetamme heidät tähän tarpeeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Mutta me tahdomme omistautua rukoukseen ja sanan palveluun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Se puhe oli koko joukon mieleen. He valitsivat Stefanoksen, miehen, joka oli täynnä uskoa ja Pyhää Henkeä, sekä Filippoksen, Prokoroksen, Nikanorin, Timonin, Parmenaksen ja Nikolaoksen, antiokialaisen käännynnäisen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'ja asettivat heidät apostolien eteen, ja nämä rukoilivat ja panivat kätensä heidän päälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Jumalan sana menestyi, ja opetuslasten luku lisääntyi suuresti Jerusalemissa. Suuri joukko pappeja tuli uskolle kuuliaisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Stefanos, täynnä armoa ja voimaa, teki suuria ihmeitä ja tunnustekoja kansan keskuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Niin nousi muutamia niin kutsutusta libertiinien, kyreneläisten ja aleksandrialaisten synagogasta sekä niiden joukosta, jotka olivat Kilikiasta ja Aasiasta, väittelemään Stefanoksen kanssa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'mutta he eivät kyenneet pitämään puoliaan sitä viisautta ja Henkeä vastaan, jolla hän puhui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Silloin he hankkivat salaa miehiä sanomaan: \"Olemme kuulleet hänen puhuvan pilkkasanoja Moosesta ja Jumalaa vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'He yllyttivät kansan vanhimmat ja kirjanoppineet ja astuivat esiin, raastoivat hänet mukaansa ja veivät Neuvoston eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'He toivat esiin vääriä todistajia, jotka sanoivat: \"Tämä mies ei lakkaa puhumasta pilkkapuheita tätä pyhää paikkaa vastaan ja lakia vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'sillä me olemme kuulleet hänen sanovan, että Jeesus, tuo Nasaretilainen, on hajottava maahan tämän paikan ja muuttava ne säädökset, jotka Mooses on meille antanut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Kaikki, jotka istuivat Neuvostossa, loivat katseensa häneen, ja näkivät, että hänen kasvonsa olivat kuin enkelin kasvot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Ylipappi sanoi: \"Onko asia niin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Stefanos sanoi: \"Miehet, veljet ja isät, kuulkaa! Kirkkauden Jumala ilmestyi meidän isällemme Aabrahamille hänen ollessaan Mesopotamiassa, ennen kuin hän oli asettunut asumaan Harraniin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'ja sanoi hänelle: \'Lähde maastasi ja suvustasi ja mene siihen maahan, jonka sinulle osoitan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Silloin hän lähti kaldealaisten maasta ja asettui asumaan Harraniin. Kun hänen isänsä oli kuollut, Jumala siirsi hänet asumaan tähän maahan, jossa te nyt asutte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'Eikä hän antanut hänelle siinä perintöosaa, ei jalan leveyttäkään, vaan lupasi Aabrahamin vielä ollessa lapseton antaa sen hänelle ja hänen siemenelleen hänen jälkeensä, kun hänellä ei ollut vielä lasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Jumala puhui näin: \'Hänen siemenensä tulee olemaan muukalaisina vieraalla maalla, ja siellä heidät tehdään orjiksi ja heitä sorretaan neljäsataa vuotta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'mutta sen kansan, jonka orjiksi he tulevat, minä tuomitsen\', sanoi Jumala, \'ja sen jälkeen he lähtevät sieltä ja palvelevat minua tässä paikassa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Hän antoi hänelle ympärileikkauksen liiton. Aabrahamille syntyi Iisak, ja hän ympärileikkasi hänet kahdeksantena päivänä, ja Iisakille syntyi Jaakob, ja Jaakobille kaksitoista kantaisää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Kantaisät kadehtivat Joosefia ja myivät hänet Egyptiin. Mutta Jumala oli hänen kanssaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'ja päästi hänet kaikista hänen ahdingoistaan. Hän antoi hänelle armon ja viisauden faraon, Egyptin kuninkaan, edessä. Tämä asetti hänet Egyptin ja kaiken huoneensa haltijaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Mutta koko Egyptiin ja Kanaaniin tuli nälänhätä ja suuri ahdinko, eivätkä isämme saaneet mistään ruokaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Mutta kun Jaakob kuuli Egyptissä olevan vehnää, hän lähetti isämme sinne ensimmäisen kerran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'Toisella kerralla Joosef teki itsensä tunnetuksi veljilleen, ja farao sai tietää Joosefin syntyperän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Joosef lähetti kutsumaan luokseen isänsä Jaakobin ja koko sukunsa, seitsemänkymmentä viisi henkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Jaakob meni Egyptiin. Sitten hän kuoli, ja myös isämme kuolivat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'ja heidät siirrettiin Sikemiin ja pantiin siihen hautaan, jonka Aabraham oli ostanut hopealla Hamorin pojilta Sikemissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Mutta sitä mukaa kun lähestyi sen lupauksen aika, jonka Jumala oli luvannut valalla Aabrahamille, kansa kasvoi ja lisääntyi Egyptissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'kunnes Egyptiä hallitsemaan nousi toinen kuningas, joka ei tiennyt Joosefista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Tämä kohteli kavalasti sukuamme ja sorti isiämme ja pani heidät jättämään heitteille pienet lapsensa, etteivät ne jäisi eloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'Siihen aikaan syntyi Mooses, ja hän oli Jumalalle otollinen. Häntä elätettiin kolme kuukautta isänsä kodissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'Mutta kun hänet oli pantu heitteille, otti faraon tytär hänet ja kasvatti hänet pojakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Mooses kasvatettiin kaikkeen egyptiläiseen viisauteen, ja hän oli voimallinen sanoissa ja teoissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Mutta kun hän oli täyttänyt neljäkymmentä vuotta, nousi hänen sydämeensä ajatus mennä katsomaan veljiään israelilaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'Nähdessään eräälle heistä tehtävän vääryyttä hän puolusti häntä ja kosti pahoinpidellyn puolesta ja löi egyptiläisen hengiltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Hän luuli veljiensä ymmärtävän, että Jumala hänen kätensä kautta oli antava heille pelastuksen, mutta he eivät sitä ymmärtäneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Seuraavana päivänä hän ilmestyi heidän luokseen heidän riidellessään ja yritti saada heitä sopimaan sanoen: \'Tehän olette veljiä, miehet, miksi teette vääryyttä toisillenne?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Mutta se, joka teki vääryyttä lähimmäiselleen, työnsi hänet pois ja sanoi: \'Kuka sinut on asettanut päämieheksemme ja tuomariksemme?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Aiotko tappaa minutkin, kuten tapoit eilen egyptiläisen?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Tämän puheen tähden Mooses pakeni ja oli muukalaisena Midianin maassa, ja siellä hänelle syntyi kaksi poikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Kun neljäkymmentä vuotta oli täynnä, hänelle ilmestyi Siinain vuoren erämaassa enkeli palavan orjantappurapensaan liekissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Kun Mooses näki sen, hän ihmetteli tätä näkyä. Kun hän meni katsomaan tarkemmin, kuului Herran ääni, joka sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, '\'Minä olen isiesi Jumala, Aabrahamin ja Iisakin ja Jaakobin Jumala.\' Mooses alkoi vapista eikä rohjennut katsoa sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Mutta Herra sanoi hänelle: \'Riisu kengät jaloistasi, sillä paikka, jossa seisot, on pyhää maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Olen totisesti nähnyt kansani kurjuuden Egyptissä ja kuullut heidän huokauksensa, ja olen astunut alas vapauttamaan heidät. Nyt, tule tänne, lähetän sinut Egyptiin.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Tämän Mooseksen, jonka he kielsivät sanoen: \'Kuka sinut on asettanut päämieheksi ja tuomariksi?\', hänet Jumala lähetti päämieheksi ja lunastajaksi sen enkelin kädellä, joka oli ilmestynyt hänelle orjantappurapensaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Hän johdatti heidät sieltä pois tehden ihmeitä ja tunnustekoja Egyptin maassa, Punaisella merellä ja erämaassa neljänäkymmenenä vuotena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'Tämä on se Mooses, joka sanoi israelilaisille: \'Profeetan Jumala on herättävä teille veljienne joukosta, minun kaltaiseni. Häntä kuulkaa!\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'Hän oli erämaassa seurakunnassa enkelin kanssa, joka puhui hänelle Siinain vuorella, ja isiemme kanssa. Hän sai eläviä sanoja meille annettaviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'Mutta häntä isämme eivät tahtoneet totella, vaan työnsivät hänet pois ja kääntyivät sydämessään jälleen Egyptiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'sanoen Aaronille: \'Tee meille jumalia, jotka kulkevat edellämme, sillä emme tiedä, mitä on tapahtunut Moosekselle, hänelle, joka johdatti meidät Egyptin maasta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'He tekivät niinä päivinä vasikan ja toivat uhreja epäjumalalleen ja riemuitsivat kättensä töistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Mutta Jumala kääntyi heistä pois ja hylkäsi heidät palvelemaan taivaan sotajoukkoa, niin kuin on kirjoitettu Profeettojen kirjassa: \'Toitteko te minulle teurasuhreja ja muita uhreja erämaassa neljänäkymmenenä vuotena, te, Israelin heimo?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Te kannoitte Molokin majaa ja Romfa-jumalan tähteä, niitä kuvia, jotka te olitte tehneet kumarrettaviksenne? [Minä] siirrän teidät pois Babylonin toiselle puolelle.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Todistuksen maja oli isillämme erämaassa, niin kuin hän, joka puhui Moosekselle, oli määrännyt sen tehtäväksi, sen mallin mukaan, minkä Mooses oli nähnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Isämme ottivat sen perintönä vastaan ja toivat sen Joosuan johdolla maahan, jonka he valtasivat pakanoilta, jotka Jumala karkotti isiemme tieltä. Näin oli Daavidin päiviin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'Hän löysi armon Jumalan edessä ja anoi, että hän saisi valmistaa majan Jaakobin Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Mutta Salomo rakensi hänelle huoneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Korkein ei kuitenkaan asu käsillä tehdyissä temppeleissä, sillä näin sanoo profeetta:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, '\'Taivas on valtaistuimeni ja maa jalkojeni astinlauta. Millaisen huoneen minulle rakentaisitte, sanoo Herra, tai mikä paikka olisi minun leposijani?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Eikö minun käteni ole tehnyt tätä kaikkea?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Te niskurit ja sydämeltä ja korvilta ympärileikkaamattomat, aina te vastustatte Pyhää Henkeä – kuten teidän isänne, niin tekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Ketä profeetoista teidän isänne eivät vainonneet? He tappoivat ne, jotka ennustivat sen Vanhurskaan tulemista, jonka kavaltajiksi ja murhaajiksi te olette nyt tulleet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'te, jotka enkelien toimen kautta saitte lain, mutta ette sitä pitäneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Mutta kun he tämän kuulivat, viilsi se heidän sydäntään, ja he kiristelivät hampaitaan hänelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Mutta täynnä Pyhää Henkeä hän loi katseensa taivaaseen ja näki Jumalan kirkkauden ja Jeesuksen seisovan Jumalan oikealla puolella');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'ja sanoi: \"Katso, näen taivaat auenneina ja Ihmisen Pojan seisovan Jumalan oikealla puolella.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'He huusivat suurella äänellä, tukkivat korvansa, ryntäsivät kaikki yhdessä hänen kimppuunsa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'ajoivat hänet ulos kaupungista ja kivittivät. Todistajat riisuivat viittansa Saul-nimisen nuorukaisen jalkojen juureen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'He kivittivät Stefanoksen, joka rukoili ja sanoi: \"Herra Jeesus, ota minun henkeni!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Hän laskeutui polvilleen ja huusi suurella äänellä: \"Herra, älä pidätä heille tätä syntiä!\" Sen sanottuaan hän nukkui pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Saul hyväksyi hänen surmaamisensa. Sinä päivänä tuli suuri vaino Jerusalemin seurakuntaa vastaan. Kaikki hajaantuivat ympäri Juudean ja Samarian paikkakuntien, paitsi apostolit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Muutamat jumalaapelkäävät miehet hautasivat Stefanoksen ja pitivät hänelle suuret valittajaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Mutta Saul raateli seurakuntaa, kulki talosta taloon, raastoi ulos miehiä ja naisia ja luovutti heitä vankilaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Ne, jotka olivat siis hajaantuneet, vaelsivat ja julistivat evankeliumin sanaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Filippos meni Samarian kaupunkiin ja saarnasi heille Kristusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'Kansa otti yksimielisesti vaarin siitä, mitä Filippos puhui, kun he kuulivat hänen sanansa ja näkivät tunnusteot, jotka hän teki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Sillä monista, joissa oli saastaisia henkiä, ne lähtivät huutaen suurella äänellä, ja monia halvaantuneita ja rampoja parani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'Syntyi suuri ilo siinä kaupungissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Mutta ennestään kaupungissa oli eräs mies, nimeltä Simon, joka harjoitti noituutta ja hämmästytti Samarian kansaa sanoen olevansa jokin suuri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Hänen perässään kulkivat kaikki, pienet ja suuret, ja sanoivat: \"Tämä mies on suuri Jumalan voima.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'He kulkivat hänen perässään sen tähden, että hän oli pitkän aikaa hämmästyttänyt heitä noituuksillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Mutta kun he uskoivat Filipposta, joka julisti evankeliumia Jumalan valtakunnasta ja Jeesuksen Kristuksen nimestä, kastettiin sekä miehet että naiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Simon itsekin uskoi, ja kasteen saatuaan hän pysyi Filippoksen seurassa. Nähdessään ihmeitä ja suuria, voimallisia tekoja hän hämmästyi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Mutta kun Jerusalemissa olevat apostolit kuulivat, että Samaria oli ottanut vastaan Jumalan sanan, he lähettivät heidän luokseen Pietarin ja Johanneksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Tultuaan sinne nämä rukoilivat heidän edestään, että he saisivat Pyhän Hengen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'sillä hän ei ollut vielä tullut yhdenkään heidän päälleen, vaan heidät oli ainoastaan kastettu Herran Jeesuksen nimeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Silloin he panivat kätensä heidän päälleen, ja he saivat Pyhän Hengen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Mutta kun Simon näki, että Henki annettiin sille, jonka päälle apostolit panivat kätensä, hän toi heille rahaa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'sanoen: \"Antakaa minullekin se valta, että kenen päälle panen käteni, se saa Pyhän Hengen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Mutta Pietari sanoi hänelle: \"Menkööt rahasi mukanasi kadotukseen, koska luulet Jumalan lahjan olevan rahalla saatavissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Sinulla ei ole osaa eikä arpaa tähän sanaan, sillä sydämesi ei ole oikea Jumalan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Muuta siis mielesi ja käänny tästä pahuudestasi ja rukoile Herraa – jos ehkä vielä sydämesi ajatus sinulle annetaan anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Sillä näen sinun olevan täynnä katkeruuden sappea ja sidottuna vääryyden siteisiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Simon vastasi ja sanoi: \"Rukoilkaa te minun edestäni Herraa, ettei minulle tapahtuisi mitään siitä, mitä olette sanoneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Kun he olivat todistaneet ja puhuneet Herran sanaa, he vaelsivat kohti Jerusalemia ja julistivat evankeliumia monessa Samarian kylässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Mutta Herran enkeli puhui Filippokselle sanoen: \"Nouse ja mene puolipäivään päin sille tielle, joka vie Jerusalemista alas Gassaan ja on autio.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'Hän nousi ja lähti. Katso, siellä kulki etiopialainen mies, Etiopian kuningattaren Kandaken hoviherra, mahtava mies ja koko hänen aarteistonsa hoitaja. Hän oli tullut Jerusalemiin rukoilemaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'ja oli paluumatkalla. Hän istui vaunuissaan ja luki profeetta Jesajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Henki sanoi Filippokselle: \"Mene noiden vaunujen luo ja pysyttele lähellä niitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Filippos juoksi luo, kuuli hänen lukevan profeetta Jesajaa ja sanoi: \"Ymmärräthän, mitä luet?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'Hän sanoi: \"Kuinka voisin, ellei kukaan minua opasta?\" Hän pyysi Filipposta nousemaan ja istumaan viereensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Kirjoitus, jota hän luki, oli tämä: \"Niin kuin lammas hänet viedään teuraaksi, ja niin kuin karitsa on ääneti keritsijänsä edessä, ei hänkään suutaan avaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'Hänen alentumisensa kautta hänen tuomionsa otetaan pois. Kuka kertoo hänen syntyperänsä? Sillä hänen elämänsä otetaan pois maan päältä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Hoviherra vastasi Filippokselle sanoen: \"Pyydän sinua: sano, kenestä profeetta puhuu näin, itsestään vai jostakusta toisesta?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Filippos avasi suunsa ja lähtien tästä kirjoituksesta julisti hänelle evankeliumia Jeesuksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Kulkiessaan tietä he tulivat veden ääreen. Hoviherra sanoi: \"Katso, tässä on vettä. Mikä estää kastamasta minua?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'Mutta Filippos sanoi: \"Jos sinä uskot kaikesta sydämestäsi, se tapahtukoon. Hän vastasi ja sanoi: \"Uskon, että Jeesus Kristus on Jumalan Poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Hän käski pysäyttää vaunut, ja he astuivat kumpikin veteen, sekä Filippos että hoviherra, ja hän kastoi hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Kun he olivat astuneet ylös vedestä, tempasi Herran Henki Filippoksen pois, eikä hoviherra häntä enää nähnyt, ja hän jatkoi matkaansa iloiten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Mutta Filippos tavattiin Asdodissa. Hän julisti evankeliumia vaeltaen kaikissa kaupungeissa, kunnes tuli Kesareaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Mutta Saul puhisi yhä uhkaa ja murhaa Herran opetuslapsia vastaan ja meni ylipapin luo');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'ja pyysi häneltä kirjeitä Damaskon synagogille, että keitä vain hän löytäisi sillä tiellä olevia, miehiä tai naisia, hän toisi heidät sidottuina Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Hänen ollessaan matkalla tapahtui, kun hän lähestyi Damaskoa, että yhtäkkiä valo taivaasta leimahti hänen ympärillään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'Hän kaatui maahan ja kuuli äänen, joka sanoi hänelle: \"Saul, Saul, miksi vainoat minua?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Hän sanoi: \"Kuka olet, herra?\" Hän vastasi: \"Minä olen Jeesus, jota sinä vainoat. Työlästä sinun on potkia tutkainta vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'Mutta nouse ja mene kaupunkiin, niin sinulle sanotaan, mitä sinun pitää tehdä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Miehet, jotka matkustivat hänen kanssaan, seisoivat sanattomina: he kuulivat kyllä ääntä, mutta eivät nähneet ketään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Saul nousi maasta, mutta kun hän avasi silmänsä, hän ei nähnyt mitään, vaan he taluttivat häntä kädestä ja veivät hänet Damaskoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Hän oli kolme päivää näkemättä mitään, ei syönyt eikä juonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Damaskossa oli eräs opetuslapsi, nimeltä Ananias. Hänelle Herra sanoi näyssä: \"Ananias!\" Hän vastasi: \"Katso, tässä olen, Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Herra sanoi hänelle: \"Nouse ja mene sille kadulle, jota sanotaan Suoraksi kaduksi, ja kysy Juudan talosta Saul-nimistä tarsolaista miestä. Sillä katso, hän rukoilee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'Hän on nähnyt näyssä Ananias-nimisen miehen tulevan sisälle ja panevan kätensä hänen päälleen, että hän saisi näkönsä takaisin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Mutta Ananias vastasi: \"Herra, olen monelta kuullut siitä miehestä, kuinka paljon pahaa hän on tehnyt sinun pyhillesi Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'Täälläkin hänellä on ylipapeilta valtuutus vangita kaikki, jotka huutavat avuksi sinun nimeäsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Mutta Herra sanoi hänelle: \"Mene, sillä hän on minulle valittu työkalu kantamaan nimeäni pakanoiden, kuningasten ja Israelin lasten eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Sillä minä tahdon näyttää hänelle, kuinka paljon hänen pitää kärsiä minun nimeni tähden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Ananias meni, astui huoneeseen, pani molemmat kätensä hänen päälleen ja sanoi: \"Veljeni Saul, Herra lähetti minut – Jeesus, joka ilmestyi sinulle tiellä, jota tulit – että saisit näkösi takaisin ja tulisit täytetyksi Pyhällä Hengellä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'Heti putosivat hänen silmistään ikään kuin suomukset, ja hän sai näkönsä, nousi ja hänet kastettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'Otettuaan ruokaa hän vahvistui. Hän oli opetuslasten seurassa Damaskossa joitakin päiviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'Heti hän saarnasi synagogissa Jeesusta, että hän on Jumalan Poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Mutta kaikki, jotka kuulivat, hämmästyivät ja sanoivat: \"Eikö tämä ole se, joka Jerusalemissa tuhosi ne, jotka huutavat avuksi tätä nimeä? Eikö hän ole tullut tänne viedäkseen heidät sidottuina ylipapeille?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Mutta Saul sai yhä enemmän voimaa ja saattoi Damaskossa asuvat juutalaiset ymmälle näyttäen toteen, että Jeesus on Kristus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Sitten pitkän ajan kuluttua juutalaiset pitivät keskenään neuvottelun tappaakseen hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Mutta heidän salahankkeensa tuli Saulin tietoon. He vartioivat porttejakin yötä päivää tappaakseen hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Mutta hänen opetuslapsensa ottivat hänet yöllä, päästivät hänet alas muurilta ja laskivat maahan isossa korissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Kun hän oli tullut Jerusalemiin, hän yritti liittyä opetuslapsiin, mutta he kaikki pelkäsivät häntä eivätkä uskoneet, että hän oli opetuslapsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Mutta Barnabas otti hänet turviinsa, vei hänet apostolien luo ja kertoi heille, kuinka Saul tiellä oli nähnyt Herran, ja että Herra oli puhunut hänelle, ja kuinka hän Damaskossa oli rohkeasti julistanut Jeesuksen nimeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'Hän oli heidän keskuudessaan käyden sisälle ja ulos Jerusalemissa ja julistaen rohkeasti Herran nimeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'Hän puhui ja väitteli hellenistien kanssa, mutta he yrittivät tappaa hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Kun veljet sen huomasivat, he veivät hänet Kesareaan ja lähettivät hänet sieltä Tarsoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'Niin oli seurakunnilla koko Juudeassa, Galileassa ja Samariassa rauha rakentuen ja vaeltaen Herran pelossa sekä lisääntyen Pyhän Hengen lohduttavasta vaikutuksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Tapahtui, että Pietari kiertäessään kaikkien luona tuli myös Lyddassa asuvien pyhien luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Siellä hän tapasi Aineas-nimisen miehen, joka kahdeksan vuotta oli maannut vuoteessaan ja oli halvautunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'Pietari sanoi hänelle: \"Aineas, Jeesus Kristus parantaa sinut, nouse ja sijaa vuoteesi\" ja heti hän nousi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'Kaikki Lyddan ja Saaronin asukkaat näkivät hänet ja kääntyivät Herran luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'Mutta Joppessa oli naisopetuslapsi, nimeltä Tabita, mikä on käännettynä Dorkas. Hän teki paljon hyviä töitä ja antoi runsaasti almuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Tapahtui niinä päivinä, että hän sairastui ja kuoli. He pesivät hänet ja panivat yläsaliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Koska Lydda oli lähellä Joppea, opetuslapset kuultuaan Pietarin olevan siellä lähettivät kaksi miestä hänen luokseen pyytämään: \"Tule viipymättä luoksemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Pietari nousi ja meni heidän kanssaan. Sinne saavuttuaan he veivät hänet yläsaliin, ja kaikki lesket tulivat hänen luokseen itkien ja näyttäen hänelle paitoja ja vaatteita, joita Dorkas oli tehnyt ollessaan heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Mutta Pietari toimitti kaikki ulos, laskeutui polvilleen ja rukoili. Sitten hän kääntyi ruumiin puoleen ja sanoi: \"Tabita, nouse ylös!\" Tämä avasi silmänsä, ja nähdessään Pietarin hän nousi istumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'Pietari ojensi hänelle kätensä, nosti hänet seisomaan, kutsui sisään pyhät ja lesket ja asetti hänet elävänä heidän eteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'Tapahtuma tuli tietoon koko Joppessa, ja monet uskoivat Herraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'Pietari viipyi Joppessa jonkin aikaa erään nahkuri Simonin luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Kesareassa oli mies, nimeltä Kornelius, sadanpäällikkö niin sanotusta italialaisesta kohortista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Hän oli hurskas ja jumalaapelkäävä, kuten hänen koko perhekuntansakin. Hän antoi paljon almuja kansalle ja rukoili alati Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Hän näki selvästi näyssä, noin yhdeksännellä tunnilla päivästä, Jumalan enkelin, joka tuli sisään hänen luokseen ja sanoi hänelle: \"Kornelius!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Tämä loi katseensa häneen ja sanoi pelästyneenä: \"Mikä on, herra?\" Enkeli sanoi hänelle: \"Rukouksesi ja almusi ovat tulleet muistetuiksi Jumalan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Lähetä nyt miehiä Joppeen noutamaan eräs Simon, jota sanotaan Pietariksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Hän on majoittunut nahkuri Simonin luo, jonka talo on meren rannalla. Hän sanoo sinulle, mitä sinun tulee tehdä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Kun enkeli, joka oli puhunut Korneliukselle, oli mennyt pois, tämä kutsui kaksi palvelijaansa ja erään hurskaan sotilaan niistä, jotka häntä palvelivat');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'ja kertoi heille kaikki ja lähetti heidät Joppeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Seuraavana päivänä, kun he olivat matkalla ja lähestyivät kaupunkia, Pietari nousi noin kuudennen tunnin vaiheilla katolle rukoilemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Tapahtui, että hänen tuli nälkä, ja hän halusi syödä. Mutta ruokaa valmistettaessa hän joutui hurmoksiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'Hän näki taivaan avoinna ja astian kuin suuren liinavaatteen tulevan alas. Liina oli neljästä kulmasta sidottu ja laskettiin alas maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'Siinä oli kaikkia maan nelijalkaisia eläimiä, matelijoita ja taivaan lintuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'Silloin tuli ääni, joka sanoi hänelle: \"Nouse, Pietari, teurasta ja syö.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Mutta Pietari sanoi: \"En missään tapauksessa, Herra, sillä en ole koskaan syönyt mitään epäpyhää enkä saastaista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Taas ääni sanoi hänelle toisen kerran: \"Sitä, minkä Jumala on puhdistanut, älä tee epäpyhäksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Tämä tapahtui kolme kertaa. Sitten liinavaate otettiin takaisin taivaaseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Mutta kun Pietari oli epätietoinen siitä, mitä hänen näkemänsä näky merkitsi, katso, miehet, jotka Kornelius oli lähettänyt ja jotka olivat kyselleet Simonin taloa, seisoivat portilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'He tiedustelivat kuuluvalla äänellä, oliko Simon, jota sanottiin Pietariksi, majoitettu sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Mutta kun Pietari yhä pohti tuota näkyä, Henki sanoi hänelle: \"Katso, kolme miestä etsii sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Nouse nyt, mene alas ja lähde empimättä heidän kanssaan, sillä minä olen heidät lähettänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Pietari meni alas miesten luo, jotka Kornelius oli lähettänyt hänen luokseen, ja sanoi: \"Katso, minä olen se, jota te etsitte. Mitä varten olette tulleet?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'He sanoivat: \"Sadanpäällikkö Kornelius, vanhurskas ja jumalaapelkäävä mies, josta koko Juudan kansa todistaa hyvää, on pyhältä enkeliltä saanut käskyn hakea sinut kotiinsa ja kuulla, mitä sinulla on sanottavana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Hän kutsui heidät sisään ja piti heitä vierainaan. Seuraavana päivänä Pietari nousi ja lähti heidän kanssaan, ja muutamat veljet Joppesta lähtivät hänen mukaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'Seuraavana päivänä he saapuivat Kesareaan. Kornelius odotti heitä ja oli kutsunut koolle sukulaisensa ja lähimmät ystävänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Tapahtui, kun Pietari oli astumassa sisään, että Kornelius meni häntä vastaan, lankesi hänen jalkojensa juureen ja kumartui maahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Mutta Pietari nosti hänet ylös sanoen: \"Nouse, minäkin olen ihminen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'Puhellen hänen kanssaan hän meni sisään ja tapasi monta koolle tulleina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'Hän sanoi heille: \"Te tiedätte, että juutalainen mies ei saa seurustella vierasheimoisen kanssa tai mennä hänen luokseen, mutta minulle Jumala on osoittanut, etten saa sanoa ketään ihmistä epäpyhäksi enkä saastaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Sen tähden kun minua haettiin, lähdin vastaansanomatta. Nyt kysyn: \"Mitä varten olette minut hakeneet?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Kornelius sanoi: \"Neljä päivää sitten tälle tunnille asti paastosin ja rukoilin kodissani tällä yhdeksännellä tunnilla, ja katso, edessäni seisoi mies loistavissa vaatteissa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'ja sanoi: \'Kornelius, rukouksesi on kuultu, ja almusi ovat tulleet muistoon Jumalan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Siis lähetä nyt [joku] Joppeen ja kutsu luoksesi Simon, jota sanotaan myös Pietariksi. Hän on majoittunut nahkuri Simonin taloon meren rannalle. Hän saapuu puhumaan sinulle.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Sen tähden lähetin heti sinulle sanan, ja sinä teit hyvin, kun tulit. Nyt olemme siis tässä kaikki Jumalan edessä kuullaksemme kaiken, mitä Herra on käskenyt sinun puhua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Pietari avasi suunsa ja sanoi: \"Nyt totisesti käsitän, ettei Jumala katso henkilöön,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'vaan että jokaisessa kansassa se, joka häntä pelkää ja noudattaa vanhurskautta, on hänelle otollinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'Te tiedätte sen sanan, jonka hän lähetti Israelin lapsille julistaen evankeliumia rauhasta Jeesuksessa Kristuksessa, joka on kaikkien Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Se sana, joka alkoi Galileasta, on levinnyt koko Juudeaan, sen kasteen jälkeen, jota Johannes saarnasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'Te tiedätte, kuinka Jumala Pyhällä Hengellä ja voimalla oli voidellut Jeesuksen Nasaretilaisen, hänet, joka vaeltaen ympäri teki hyvää ja paransi kaikki perkeleen valtaan joutuneet, sillä Jumala oli hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'Me olemme sen kaiken todistajat, mitä hän teki juutalaisten maassa ja Jerusalemissa. Hänet he ripustivat puuhun ja tappoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Hänet Jumala herätti kolmantena päivänä ja antoi hänen ilmestyä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'ei kaikelle kansalle, vaan Jumalan ennen valitsemille todistajille, meille, jotka söimme ja joimme hänen kanssaan sen jälkeen, kun hän oli noussut kuolleista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'Hän käski meidän saarnata kansalle ja todistaa, että hän on se, jonka Jumala on määrännyt elävien ja kuolleiden tuomariksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Hänestä kaikki Profeetat todistavat, että jokainen, joka uskoo häneen, saa syntien anteeksiantamuksen hänen nimensä kautta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Pietarin näitä vielä puhuessa laskeutui Pyhä Henki kaikkien päälle, jotka kuulivat puheen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'Kaikki ne uskovat, jotka olivat ympärileikattuja ja olivat tulleet Pietarin mukana, hämmästyivät, että Pyhän Hengen lahja vuodatettiin pakanoidenkin päälle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'sillä he kuulivat heidän puhuvan kielillä ja ylistävän Jumalaa. Silloin Pietari vastasi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, '\"Eihän kukaan voi kieltää kastamasta vedellä näitä, jotka ovat saaneet Pyhän Hengen kuten mekin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'Hän käski kastaa heidät Jeesuksen Kristuksen nimeen. Silloin he pyysivät häntä viipymään siellä joitakin päiviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Apostolit ja veljet kuulivat kaikkialla Juudeassa, että pakanatkin olivat ottaneet vastaan Jumalan sanan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Kun sitten Pietari tuli Jerusalemiin, ympärileikatut vastustivat häntä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'sanoen: \"Sinä olet käynyt ympärileikkaamattomien miesten luona ja syönyt heidän kanssaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Niin Pietari selitti heille alusta alkaen asiat järjestyksessä ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, '\"Minä olin Joppen kaupungissa ja rukoilin. Silloin näin hurmoksissa näyn: Tuli alas astia kuin suuri liinavaate, joka laskettiin taivaasta neljästä kulmastaan, ja se tuli aivan minun eteeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Kun katsoin sitä tarkasti, näin siinä maan nelijalkaisia, petoja, matelijoita ja taivaan lintuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Kuulin myös äänen, joka sanoi minulle: \'Nouse, Pietari, teurasta ja syö.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Mutta sanoin: \'En missään tapauksessa, Herra, sillä koskaan ei ole mitään epäpyhää eikä saastaista tullut suuhuni.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Ääni taivaasta vastasi toistamiseen ja sanoi: \'Sitä, minkä Jumala on puhdistanut, älä sano epäpyhäksi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Tämä tapahtui kolme kertaa. Sitten kaikki vedettiin takaisin ylös taivaaseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Katso, samassa seisoi sen talon edessä, jossa olimme, kolme miestä, jotka oli lähetetty Kesareasta luokseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Niin Henki käski minun mennä epäröimättä heidän mukaansa. Myös nämä kuusi veljeä lähtivät kanssani, ja menimme sen miehen taloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Hän kertoi meille, kuinka hän oli nähnyt enkelin seisovan huoneessaan ja sanovan: \'Lähetä Joppeen hakemaan Simon, jota sanotaan Pietariksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'Hän puhuu sinulle sanoja, joiden kautta pelastut, sinä ja koko perhekuntasi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Kun rupesin puhumaan, Pyhä Henki tuli heidän päälleen, niin kuin alussa meidänkin päällemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Silloin muistin Herran sanan, jonka hän sanoi: \'Johannes kastoi vedellä, mutta teidät kastetaan Pyhällä Hengellä.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Koska siis Jumala antoi yhtäläisen lahjan heille kuin meillekin, kun olimme uskoneet Herraan Jeesukseen Kristukseen, niin mikä minä olin voidakseni estää Jumalaa?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Tämän kuultuaan he rauhoittuivat ja ylistivät Jumalaa sanoen: \"Jumala on siis antanut pakanoillekin mielenmuutoksen elämäksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Ne, jotka olivat hajaantuneet sen ahdingon vuoksi, joka oli syntynyt Stefanoksen tähden, vaelsivat ympäri Foinikiaan, Kyproon ja Antiokiaan saakka, mutta eivät puhuneet sanaa muille kuin ainoastaan juutalaisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Heidän joukossaan oli kuitenkin muutamia kyprolaisia ja kyreneläisiä miehiä, jotka tultuaan Antiokiaan puhuivat kreikkalaisillekin ja julistivat evankeliumia Herrasta Jeesuksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'Herran käsi oli heidän kanssaan, ja suuri oli se joukko, joka uskoi ja kääntyi Herran puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Sitten sanoma heistä tuli Jerusalemin seurakunnan korviin, ja he lähettivät Barnabaan Antiokiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Kun hän saapui sinne ja näki Jumalan armon, hän iloitsi ja kehotti kaikkia vakaalla sydämellä pysymään Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Sillä hän oli hyvä mies ja täynnä Pyhää Henkeä ja uskoa, ja Herralle lisääntyi paljon kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Hän lähti Tarsoon etsimään Saulia, ja kun hän oli hänet löytänyt, hän toi hänet Antiokiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'Sitten he vaikuttivat yhdessä kokonaisen vuoden seurakunnassa, ja oli suuri joukko, joka sai heiltä opetusta. Antiokiassa ruvettiin opetuslapsia ensiksi nimittämään kristityiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'Siihen aikaan tuli profeettoja Jerusalemista Antiokiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'Eräs heistä, nimeltä Agabus, nousi ja antoi Hengen vaikutuksesta tiedoksi, että tulee suuri nälänhätä koko maanpiiriin. Se tulikin Klaudiuksen aikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Opetuslapset päättivät kukin varojensa mukaan lähettää avustusta Juudeassa asuville veljille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'Sen he tekivätkin ja lähettivät sen vanhimmille Barnabaan ja Saulin käden kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Siihen aikaan kuningas Herodes otatti muutamia seurakunnasta kiinni kiduttaakseen heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Hän mestautti miekalla Jaakobin, Johanneksen veljen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Kun hän näki sen olevan juutalaisille mieleen, hän vangitutti lisäksi Pietarinkin. Silloin olivat happamattoman leivän päivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Otettuaan hänet kiinni hän pani hänet vankilaan ja jätti neljän nelimiehisen sotilasvartioston vartioitavaksi tahtoen pääsiäisen jälkeen viedä hänet kansan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Pietaria pidettiin siis vankilassa, mutta seurakunta rukoili lakkaamatta Jumalaa hänen edestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'Kun Herodes halusi tuoda hänet oikeuden eteen, Pietari nukkui yöllä kahden sotamiehen välissä sidottuna kaksilla kahleilla, ja vartijat vartioivat oven edessä vankilaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Katso, hänen edessään seisoi Herran enkeli, huoneessa loisti valo, enkeli sysäsi Pietaria kylkeen ja herätti hänet sanoen: \"Nouse nopeasti!\" Ja kahleet putosivat hänen käsistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'Sitten enkeli sanoi hänelle: \"Vyöttäydy ja sido sandaalit jalkaasi.\" Hän teki niin. Vielä enkeli sanoi hänelle: \"Kiedo viitta yllesi ja seuraa minua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Pietari lähti ja seurasi häntä, mutta ei tiennyt, että se, mikä enkelin vaikutuksesta tapahtui, oli totta, vaan hän luuli näkevänsä näyn.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'He kulkivat läpi ensimmäisen vartion ja toisen ja tulivat rautaportille, joka vei kaupunkiin. Se aukeni heille itsestään, ja he menivät ulos ja kulkivat eteenpäin erästä katua. Yhtäkkiä enkeli erosi hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Kun Pietari tointui, hän sanoi: \"Nyt totisesti tiedän, että Herra on lähettänyt enkelinsä ja pelastanut minut Herodeksen käsistä ja kaikesta, mitä Juudan kansa odotti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Päästyään siitä selville hän kulki kohti Marian, Johanneksen äidin, taloa, sen Johanneksen, jota sanottiin Markukseksi. Siellä oli monta koolla rukoilemassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Kun Pietari koputti eteisen oveen, tuli siihen palvelustyttö, nimeltä Rode, ottamaan tulijasta selvää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'Tunnettuaan Pietarin äänen hän ei iloissaan avannut eteistä, vaan juoksi sisään ja kertoi Pietarin seisovan portilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'He sanoivat hänelle: \"Sinä hourit.\" Mutta hän väitti asian niin olevan. He sanoivat: \"Se on hänen enkelinsä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Mutta Pietari koputti yhä. Kun he avasivat, he näkivät hänet ja hämmästyivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Hän viittasi kädellään heitä vaikenemaan ja kertoi heille, kuinka Herra oli vienyt hänet ulos vankilasta, ja sanoi: \"Ilmoittakaa tämä Jaakobille ja veljille.\" Hän lähti pois ja meni toiseen paikkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Mutta kun päivä koitti, tuli sotilaille kova hätä siitä, mihin Pietari oli joutunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Kun Herodes oli haettanut häntä eikä löytänyt, hän tutki vartijoita ja käski viedä heidät pois. Hän meni Juudeasta Kesareaan ja oleskeli siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Herodes oli suuresti vihoissaan tyyrolaisille ja siidonilaisille. Mutta nämä tulivat yksissä neuvoin hänen luokseen, ja suostuteltuaan puolelleen Blastuksen, kuninkaan kamaripalvelijan, he anoivat rauhaa, sillä heidän maakuntansa sai elatuksensa kuninkaan maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'Herodes pukeutui määrättynä päivänä kuninkaalliseen pukuun, istui istuimelleen ja piti heille virallisen puheen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'Mutta kansa huusi: \"Jumalan ääni, eikä ihmisen!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'Mutta heti häntä löi Herran enkeli, koska hän ei antanut kunniaa Jumalalle, ja madot söivät hänet, ja hän heitti henkensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Mutta Jumalan sana kasvoi ja levisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Barnabas ja Saul palasivat Jerusalemista toimitettuaan avustustehtävän ja toivat sieltä mukanaan myös Johanneksen, jota sanottiin Markukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Antiokian seurakunnassa oli profeettoja ja opettajia: Barnabas ja Simeon, jota sanottiin Nigeriksi, ja Lukius, kyreneläinen, ja Manaen, neljännesruhtinas Herodeksen kasvinkumppani, ja Saul.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Heidän toimittaessaan palvelusvirkaansa Herralle ja paastotessaan Pyhä Henki sanoi: \"Erottakaa minulle Barnabas ja Saul siihen työhön, johon olen heidät kutsunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Silloin he paastosivat, rukoilivat, panivat kätensä heidän päälleen ja laskivat heidät menemään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Pyhän Hengen lähettäminä he menivät Seleukiaan ja purjehtivat sieltä Kyprokselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Tultuaan Salamiiseen he julistivat Jumalan sanaa juutalaisten synagogissa, ja heillä oli mukanaan myös Johannes, palvelijana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Kun he olivat vaeltaneet kautta koko saaren Pafoon asti, he tapasivat erään juutalaisen miehen, noidan ja väärän profeetan, jonka nimi oli Barjeesus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'Hän oleskeli käskynhaltijan, Sergius Pauluksen, luona, joka oli ymmärtäväinen mies. Tämä kutsui luokseen Barnabaan ja Saulin pyrkien kuulemaan Jumalan sanaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Mutta Elymas, noita – sillä niin tulkitaan hänen nimensä – vastusti heitä, yrittäen kääntää käskynhaltijan pois uskosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Saul, myös Paavaliksi kutsuttu, täynnä Pyhää Henkeä loi häneen tiukan katseen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'ja sanoi: \"Voi sinua, joka olet kaikkea vilppiä ja kavaluutta täynnä, sinä perkeleen lapsi, kaiken vanhurskauden vihollinen, etkö lakkaa vääristelemästä Herran suoria teitä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Nyt, katso, Herran käsi on päälläsi, ja tulet sokeaksi etkä näe aurinkoa säädettyyn aikaan asti.\" Heti lankesi hänen päälleen synkkä pimeys, ja hän kulki ympäriinsä ja etsi taluttajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Kun käskynhaltija näki, mitä oli tapahtunut, hän uskoi, ihmetellen Herran oppia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Kun Paavali oli matkatovereineen purjehtinut Pafosta, he tulivat Pamfylian Pergeen. Siellä Johannes erosi heistä ja palasi Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Mutta he jatkoivat matkaa Pergestä eteenpäin, saapuivat Pisidian Antiokiaan ja menivät synagogaan sapatinpäivänä ja istuutuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Kun Lakia ja Profeettoja oli luettu, lähettivät synagogan esimiehet sanomaan heille: \"Miehet, veljet, jos teillä on jokin kehotuksen sana kansalle, puhukaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Paavali nousi ja viittasi kädellään ja sanoi: \"Te Israelin miehet ja jumalaapelkäävät, kuulkaa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Tämän Israelin kansan Jumala valitsi isämme, korotti tämän kansan heidän ollessaan muukalaisina Egyptin maassa ja vei heidät sieltä pois kohotetulla käsivarrella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'Hän kärsi heidän tapojaan noin neljäkymmentä vuotta erämaassa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'ja hävitti seitsemän kansaa Kanaanin maasta ja jakoi niiden maan heille perinnöksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'Näin kului noin neljäsataa viisikymmentä vuotta. Sen jälkeen hän antoi heille tuomareita profeetta Samueliin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Sitten he anoivat kuningasta, ja Jumala antoi heille Saulin, Kiisin pojan, miehen Benjaminin sukukunnasta, neljäksikymmeneksi vuodeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'Mutta hän pani hänet viralta ja herätti heille kuninkaaksi Daavidin, josta hän myös todisti ja sanoi: \'Olen löytänyt Daavidin, Iisain pojan, sydämeni mukaisen miehen, joka on tekevä kaiken tahtoni.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Tämän siemenestä Jumala on lupauksensa mukaan tuonut Jeesuksen Israelille Vapahtajaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'sitten kun Johannes ennen hänen tuloaan oli saarnannut mielenmuutoksen kastetta koko Israelin kansalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Mutta kun Johannes oli tuleva juoksunsa päähän, hän sanoi: \'Minä en ole se, joksi minua luulette, mutta katso, minun jälkeeni tulee se, jonka sandaaleja en ole arvollinen jaloista riisumaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Miehet, veljet, te Aabrahamin suvun lapset, ja jumalaapelkäävät, meille on lähetetty sana tästä pelastuksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Sillä koska Jerusalemin asukkaat ja heidän hallitusmiehensä eivät Jeesusta tunteneet, he hänet tuomitessaan toteuttivat profeettojen sanat, joita joka sapatti luetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'Vaikka he eivät löytäneet mitään syytä kuolemaan, he anoivat Pilatukselta, että hänet surmattaisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'Kun he olivat täyttäneet kaiken, mikä hänestä on kirjoitettu, he ottivat hänet alas puusta ja panivat hautaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Mutta Jumala herätti hänet kuolleista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'Hän ilmestyi useina päivinä niille, jotka olivat tulleet hänen kanssaan Galileasta Jerusalemiin ja jotka ovat hänen todistajiaan kansan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'Me julistamme teille sen hyvän sanoman, että Jumala on isille annetun lupauksen täyttänyt meille, heidän lapsilleen, herättäen Jeesuksen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'niin kuin myös toisessa psalmissa on kirjoitettu: \'Sinä olet minun Poikani, tänä päivänä minä olen sinut synnyttänyt.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Siitä, että hän herätti hänet kuolleista, niin ettei hän enää palaa katoavaisuuteen, hän on sanonut näin: \'Annan teille pyhät ja lujat Daavidin armot.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Sen tähden hän myös toisessa paikassa sanoo: \'Sinä et salli Pyhäsi nähdä katoavaisuutta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Sillä kun Daavid oli aikanaan Jumalan tahtoa palvellut, hän nukkui ja tuli otetuksi isiensä luo ja näki katoavaisuuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Mutta hän, jonka Jumala herätti, ei nähnyt katoavaisuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Olkoon siis teille tiettävä, miehet ja veljet, että hänen kauttaan julistetaan teille syntien anteeksiantamus');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'ja että jokainen, joka uskoo, tulee hänessä vanhurskaaksi, vapaaksi kaikesta, mistä te ette voineet Mooseksen lain kautta tulla vanhurskaiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Kavahtakaa siis, ettei teissä täyty se, mikä on puhuttu profeetoissa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, '\'Katsokaa, te halveksijat, ja ihmetelkää ja hukkukaa, sillä minä teen teidän päivinänne teon, teon, jota ette uskoisi, jos joku kertoisi sen teille.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'Kun he lähtivät ulos juutalaisten synagogasta, pyysivät pakanat heitä puhumaan näitä asioita tulevanakin sapattina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Kun synagogasta hajaannuttiin, seurasivat monet juutalaiset ja jumalaapelkäävät käännynnäiset Paavalia ja Barnabasta, jotka puhuivat heille ja kehottivat heitä pysymään Jumalan armossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'Seuraavana sapattina kokoontui lähes koko kaupunki kuulemaan Jumalan sanaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Mutta nähdessään kansanjoukot juutalaiset tulivat kiihkoa täyteen ja väittelivät Paavalin puheita vastaan ja pilkkasivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Silloin Paavali ja Barnabas puhuivat rohkeasti ja sanoivat: \"Teille oli Jumalan sana ensiksi puhuttava, mutta koska työnnätte sen luotanne ettekä katso itseänne mahdollisiksi iankaikkiseen elämään, katso, [me] käännymme pakanoiden puoleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Sillä näin on Herra meitä käskenyt: \'Olen pannut sinut pakanoille valkeudeksi, että sinä olisit pelastukseksi maan ääriin asti.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Sen kuullessaan pakanat iloitsivat ja ylistivät Herran sanaa ja uskoivat, kaikki ne, jotka olivat säädetyt iankaikkiseen elämään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'Herran sanaa levitettiin koko siihen maakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Mutta juutalaiset yllyttivät jumalaapelkääviä ylhäisiä naisia ja kaupungin ensimmäisiä miehiä ja nostivat vainon Paavalia ja Barnabasta vastaan, ja ajoivat heidät pois alueeltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Niin he pudistivat tomun jaloistaan heitä vastaan ja menivät Ikonioniin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'Mutta opetuslapset tulivat täytetyiksi ilolla ja Pyhällä Hengellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Ikonionissa he menivät samoin juutalaisten synagogaan ja puhuivat, niin että suuri joukko sekä juutalaisia että kreikkalaisia uskoi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Mutta epäuskoiset juutalaiset yllyttivät ja kiihdyttivät pakanoiden mieliä veljiä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'He oleskelivat siellä kauan aikaa ja puhuivat rohkeasti luottaen Herraan, joka armonsa sanan todistukseksi antoi tapahtua tunnustekoja ja ihmeitä heidän kättensä kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Mutta kaupungin väestö jakaantui: toiset olivat juutalaisten puolella, toiset taas apostolien puolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Tapahtui, että pakanat ja juutalaiset sekä heidän hallitusmiehensä yrittivät ryhtyä pahoinpitelemään ja kivittämään heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'Sen huomattuaan he pakenivat Lykaonian kaupunkeihin, Lystraan ja Derbeen, ja niiden ympäristöön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'Sielläkin he julistivat evankeliumia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'Lystrassa oli mies, joka istui siellä. Hän oli hervoton jaloistaan ja rampa äitinsä kohdusta eikä ollut koskaan kävellyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Hän kuunteli Paavalin puhetta. Kun Paavali loi katseensa häneen ja näki hänellä olevan uskon, että hän voisi tulla terveeksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'hän sanoi suurella äänellä: \"Nouse pystyyn jaloillesi.\" Hän hyppäsi ylös ja käveli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Kun kansa näki, mitä Paavali oli tehnyt, he korottivat äänensä ja sanoivat lykaonian kielellä: \"Jumalat ovat ihmishahmossa astuneet alas luoksemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'He sanoivat Barnabasta Zeukseksi ja Paavalia Hermeeksi, koska hän puhui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Kaupungin edustalla olevan Zeuksen pappi toi härkiä ja seppeleitä porttien eteen ja tahtoi väkijoukon kanssa uhrata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Mutta kun apostolit Barnabas ja Paavali sen kuulivat, he repäisivät vaatteensa, ryntäsivät ulos kansanjoukkoon, huusivat');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'ja sanoivat: \"Miehet, miksi näin teette? Mekin olemme ihmisiä, sellaisia kuin tekin, ja julistamme teille evankeliumia, että kääntyisitte noista turhista jumalista elävän Jumalan puoleen, joka on tehnyt taivaan, maan, meren ja kaikki, mitä niissä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'Menneitten sukupolvien aikoina hän on sallinut kaikkien pakanoiden vaeltaa omia teitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Kuitenkaan hän ei ole ollut antamatta todistusta itsestään, sillä hän on tehnyt teille hyvää antaen teille taivaasta sateita ja hedelmällisiä aikoja ja raviten teidän sydämenne ruualla ja ilolla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Näin puhuen he vaivoin saivat kansan estetyksi uhraamasta heille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Mutta sinne tuli Antiokiasta ja Ikonionista juutalaisia. He suostuttivat kansan puolelleen, kivittivät Paavalia ja raastoivat hänet kaupungin ulkopuolelle, luullen hänet kuolleeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Mutta kun opetuslapset olivat kokoontuneet hänen ympärilleen, hän nousi ja meni kaupunkiin. Mutta seuraavana päivänä hän lähti Barnabaan kanssa Derbeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Julistettuaan evankeliumia siinä kaupungissa ja tehtyään monta opetuslapsiksi he palasivat Lystraan, Ikonioniin ja Antiokiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'He vahvistivat opetuslasten sieluja ja kehottivat heitä pysymään uskossa ja sanoivat: \"Monen ahdistuksen kautta meidän pitää mennä sisälle Jumalan valtakuntaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Kun he olivat valinneet heille äänestyksellä vanhimmat seurakunnittain, he rukoillen ja paastoten jättivät heidät Herran haltuun, johon he nyt uskoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'He kulkivat Pisidian halki ja tulivat Pamfyliaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'Julistettuaan sanaa Pergessä he menivät Attaliaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'Sieltä he purjehtivat Antiokiaan, josta olivat lähteneet annettuina Jumalan armon haltuun sitä työtä varten, jonka he olivat suorittaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Sinne saavuttuaan he kutsuivat seurakunnan koolle ja kertoivat, kuinka Jumala oli ollut heidän kanssaan, tehnyt suuria ja kuinka hän oli avannut pakanoille uskon oven.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'He viipyivät siellä pitkän aikaa opetuslasten luona.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Juudeasta tuli sinne eräitä, jotka opettivat veljiä: \"Ellette ympärileikkauta itseänne Mooseksen säätämällä tavalla, ette voi pelastua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Kun siitä syntyi riita ja kun Paavali ja Barnabas väittelivät kiivaasti heitä vastaan, päätettiin, että Paavalin, Barnabaan ja muutamien muiden heistä tuli mennä tämän riitakysymyksen tähden apostolien ja vanhinten luo Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Seurakunta lähetti heidät matkalle, ja he kulkivat Foinikian ja Samarian kautta ja kertoivat pakanoiden kääntymyksestä ja ilahduttivat sillä suuresti kaikkia veljiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'Kun he saapuivat Jerusalemiin, seurakunta, apostolit ja vanhimmat ottivat heidät vastaan. He kertoivat, kuinka Jumala oli ollut heidän kanssaan ja tehnyt suuria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Mutta fariseusten lahkosta nousi muutamia, jotka olivat tulleet uskoviksi, ja sanoivat: \"Heidät on ympärileikattava ja heitä on käskettävä noudattamaan Mooseksen lakia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Apostolit ja vanhimmat kokoontuivat tutkimaan tätä asiaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Kun oli paljon väitelty, Pietari nousi ja sanoi heille: \"Miehet, veljet, te tiedätte, että Jumala jo kauan sitten teki teidän keskuudessanne sen valinnan, että pakanat minun suustani kuulevat evankeliumin sanan ja uskovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'Jumala, sydänten tuntija, antoi heille todistuksen lahjoittaen heille Pyhän Hengen samoin kuin meillekin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'eikä tehnyt mitään erotusta meidän ja heidän välillä, sillä hän puhdisti heidän sydämensä uskolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Miksi siis nyt kiusaatte Jumalaa ja tahdotte panna opetuslasten niskaan ikeen, jota eivät meidän isämme emmekä mekään ole jaksaneet kantaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Mutta uskomme Herran Jeesuksen armon kautta pelastuvamme samalla tapaa kuin hekin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Koko joukko hiljeni, ja he kuuntelivat Barnabasta ja Paavalia, jotka kertoivat, kuinka suuria tunnustekoja ja ihmeitä Jumala oli tehnyt pakanoiden keskuudessa heidän kauttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Kun he olivat vaienneet, lausui Jaakob: \"Miehet, veljet, kuulkaa minua!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Simon on kertonut, kuinka Jumala ensi kerran katsoi pakanoiden puoleen ottaakseen heistä kansan omalle nimelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'Tämän kanssa pitävät yhtä profeettojen sanat, sillä näin on kirjoitettu:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, '\'Sen jälkeen palaan ja rakennan uudestaan Daavidin sortuneen majan, korjaan sen repeämät ja nostan sen jälleen pystyyn,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'jotta jäljelle jääneet ihmiset etsisivät Herraa, sekä kaikki pakanat, joille minun nimeäni on julistettu, sanoo Herra, joka tämän tekee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'Jumalalle ovat tunnettuja kaikki hänen tekonsa iankaikkisuudesta asti.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Sen tähden minä päätän, ettei tule rasittaa niitä, jotka kääntyvät pakanuudesta Jumalan puoleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'vaan heille kirjoitettakoon kirje, että heidän täytyy karttaa epäjumalien saastuttamaa, haureutta ja lihaa, josta veri ei ole laskettu pois, sekä verta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Sillä Mooseksella on monen polven ajan joka kaupungissa julistajansa. Luetaanhan häntä synagogissa joka sapatti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Silloin apostolit, vanhimmat ja koko seurakunta näkivät hyväksi valita keskuudestaan muutamia miehiä ja lähettää heidät Antiokiaan Paavalin ja Barnabaan mukana, nimittäin Juudaan, jota sanottiin Barsabbaaksi, ja Silaan, jotka olivat johtavia miehiä veljien joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'He kirjoittivat omakätisesti heidän mukaansa näin kuuluvan kirjeen: \"Me apostolit ja vanhimmat, teidän veljenne, lähetämme teille, pakanuudesta kääntyneille veljille Antiokiassa, Syyriassa ja Kilikiassa, tervehdyksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Koska olemme kuulleet, että muutamat meistä lähteneet ovat puheillaan tehneet teidät levottomiksi ja saattaneet sielunne hämmennyksiin sanoen, että teidän tulee ympärileikkauttaa itsenne ja pitää laki, mistä emme ole käskyä antaneet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'niin me olemme yksimielisesti nähneet hyväksi valita miehiä ja lähettää heidät teidän luoksenne rakkaiden veljiemme Barnabaan ja Paavalin kanssa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'jotka ovat panneet henkensä alttiiksi meidän Herramme Jeesuksen Kristuksen nimen tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Lähetämme siis Juudaksen ja Silaan, jotka myös suullisesti ilmoittavat teille saman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Sillä Pyhä Henki ja me olemme nähneet hyväksi, ettei teidän päällenne ole pantava enempää kuormaa kuin nämä välttämättömät:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'että kartatte epäjumalille uhrattua, verta, lihaa, josta [kaikkea] verta ei ole laskettu pois, ja haureutta. Jos te näitä vältätte, teette hyvin. Jääkää hyvästi!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Niin siis heidät lähetettiin matkaan, ja he tulivat Antiokiaan. Siellä he kutsuivat koolle koko joukon ja antoivat heille kirjeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'Kun nämä olivat lukeneet sen, he iloitsivat tästä lohdutuksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Mutta Juudas ja Silas, jotka itsekin olivat profeettoja, kehottivat veljiä monin sanoin ja vahvistivat heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'Heidän viivyttyään siellä jonkin aikaa veljet päästivät heidät rauhassa palaamaan niiden luo, jotka olivat heidät lähettäneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, 'Mutta Silas halusi jäädä sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Paavali ja Barnabas viipyivät Antiokiassa opettaen ja julistaen useiden muidenkin kanssa Herran sanaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Mutta muutamien päivien kuluttua Paavali sanoi Barnabaalle: \"Lähtekäämme takaisin kaikkiin niihin kaupunkeihin, joissa olemme julistaneet Herran sanaa, katsomaan veljiä, miten heidän on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Barnabas tahtoi ottaa mukaan Johanneksenkin, jota sanottiin Markukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Mutta Paavali katsoi oikeaksi olla ottamatta häntä mukaan, koska hän oli luopunut heistä Pamfyliassa eikä ollut heidän kanssaan lähtenyt työhön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'He kiivastuivat niin, että erosivat toisistaan, ja Barnabas otti mukaansa Markuksen ja purjehti Kyprokselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Mutta Paavali valitsi Silaan, ja veljet jättivät hänet Jumalan armon haltuun, ja hän lähti matkalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'Hän vaelsi Syyrian ja Kilikian halki vahvistaen seurakuntia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Hän saapui myös Derbeen ja Lystraan. Katso, siellä oli eräs opetuslapsi, nimeltä Timoteus, joka oli uskovan juutalaisen naisen poika, mutta isä oli kreikkalainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Hänestä veljet Lystrasta ja Ikonionista todistivat hyvää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Paavali tahtoi hänen lähtevän mukaansa, otti hänet ja ympärileikkasi hänet juutalaisten tähden, joita oli niillä paikkakunnilla, sillä kaikki tiesivät, että hänen isänsä oli kreikkalainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Sitä mukaa kuin he vaelsivat kaupungista toiseen, he antoivat heille noudatettaviksi ne säädökset, jotka apostolit ja Jerusalemin vanhimmat olivat hyväksyneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Seurakunnat vahvistuivat uskossa ja niiden jäsenmäärä kasvoi päivä päivältä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'He kulkivat Fryygian ja Galatian maan kautta Pyhän Hengen estettyä heitä julistamasta sanaa Aasian maakunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Tultuaan Mysian kohdalle he yrittivät lähteä Bityniaan, mutta Henki ei sallinut heidän tehdä sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'He vaelsivat ohi Mysian ja menivät Trooaaseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Paavalille näytettiin yöllä näky. Makedonialainen mies seisoi ja pyysi häntä sanoen: \"Tule yli Makedoniaan ja auta meitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Kun hän oli nähnyt näyn, tahdoimme heti päästä lähtemään Makedoniaan, sillä käsitimme, että Jumala oli kutsunut meitä julistamaan heille evankeliumia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Kun siis olimme purjehtineet Trooaasta, riensimme suoraan Samotrakeen, ja seuraavana päivänä Neapoliin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'ja sieltä Filippiin, joka on ensimmäinen kaupunki siinä osassa Makedoniaa, siirtokunta. Siinä kaupungissa viivyimme muutamia päiviä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'Sapatinpäivänä menimme kaupungin portin ulkopuolelle joen rannalle, jossa arvelimme olevan rukouspaikan, istuuduimme ja puhuimme kokoontuneille naisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'Eräs Lyydia-niminen purppuranmyyjä Tyatiran kaupungista, jumalaapelkäävä nainen, oli kuulemassa. Herra avasi hänen sydämensä ottamaan vastaan sen, mitä Paavali puhui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Kun hänet ja hänen perhekuntansa oli kastettu, hän pyysi meitä sanoen: \"Jos te pidätte minua Herraan uskovana, tulkaa kotiini ja majoittukaa sinne.\" Ja hän vaati meitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Niin tapahtui mennessämme rukouspaikalle, että meitä vastaan tuli eräs palvelustyttö, jossa oli tietäjähenki ja joka tuotti paljon tuloja isännilleen ennustamisellaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Hän seurasi Paavalia ja meitä ja huusi sanoen: \"Nämä miehet ovat korkeimman Jumalan palvelijoita, jotka julistavat meille pelastuksen tien.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Tätä hän teki monta päivää. Mutta se vaivasi Paavalia, ja hän kääntyi ja sanoi hengelle: \"Jeesuksen Kristuksen nimessä käsken sinua lähtemään hänestä.\" Se lähti sillä hetkellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Mutta kun hänen isäntänsä näkivät, että tulojen toivo oli heiltä kadonnut, he ottivat Paavalin ja Silaan kiinni ja vetivät heidät torille hallitusmiesten eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'Vietyään heidät päällikköjen eteen he sanoivat: \"Nämä miehet häiritsevät kaupunkimme rauhaa. He ovat juutalaisia');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'ja opettavat tapoja, joita meidän ei ole lupa omaksua eikä noudattaa, koska olemme roomalaisia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'Kansa nousi heitä vastaan, ja päälliköt repivät heiltä vaatteet ja käskivät lyödä heitä raipoilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Kun he olivat heitä paljon ruoskineet, heittivät he heidät vankilaan ja käskivät vanginvartijan tarkasti vartioida heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Sellaisen käskyn saatuaan tämä heitti heidät sisimpään vankihuoneeseen ja pani heidät jalkapuuhun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Mutta keskiyön aikaan Paavali ja Silas olivat rukouksissa ja veisasivat ylistystä Jumalalle, ja vangit kuuntelivat heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Silloin tapahtui yhtäkkiä suuri maanjäristys, niin että vankilan perustukset vapisivat, ja samassa kaikki ovet aukenivat, ja kaikkien kahleet irtosivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Kun vanginvartija heräsi ja näki vankilan ovien olevan auki, hän veti miekkansa ja aikoi surmata itsensä luullen vankien karanneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Mutta Paavali huusi suurella äänellä sanoen: \"Älä tee itsellesi mitään pahaa, sillä olemme kaikki täällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Hän pyysi valoa, juoksi sisälle ja lankesi vavisten Paavalin ja Silaan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'Hän vei heidät ulos ja sanoi: \"Herrat, mitä minun pitää tehdä, että pelastuisin?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'He sanoivat: \"Usko Herraan Jeesukseen, niin sinä pelastut, myös perhekuntasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'He puhuivat Jumalan sanaa hänelle sekä kaikille, jotka olivat hänen kodissaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'Hän otti heidät mukaansa samalla yön hetkellä ja pesi heidän haavansa, ja hänet ja kaikki hänen omaisensa kastettiin heti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'Hän vei heidät ylös kotiinsa, laittoi heille aterian ja riemuitsi siitä, että hän ja koko hänen perheensä oli tullut Jumalaan uskovaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Päivän tultua päälliköt lähettivät oikeudenpalvelijat sanomaan: \"Päästä miehet irti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'Vanginvartija ilmoitti tämän Paavalille sanoen: \"Päälliköt ovat lähettäneet sanan, että teidät on päästettävä vapaiksi. Lähtekää siis nyt ulos ja menkää rauhassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Mutta Paavali sanoi heille: \"He ovat julkisesti, vieläpä ilman tuomiota, ruoskineet meitä, jotka olemme Rooman kansalaisia, ja ovat heittäneet meidät vankilaan, ja nytkö he ajaisivat salaa meidät tiehemme! Ei niin, vaan tulkoot itse viemään meidät ulos.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Oikeudenpalvelijat kertoivat sanat päälliköille. Silloin nämä pelästyivät kuullessaan heidän olevan roomalaisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'ja he tulivat, suostuttelivat heitä, veivät heidät ulos ja pyysivät heitä lähtemään pois kaupungista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'He lähtivät vankilasta ja menivät Lyydian luo. Nähtyään veljet ja rohkaistuaan heitä he lähtivät pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Matkustettuaan Amfipolin ja Apollonian kautta he tulivat Tessalonikaan, jossa oli juutalaisten synagoga.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Tapansa mukaan Paavali meni sisälle heidän luokseen ja keskusteli kolmena sapattina heidän kanssaan Kirjoituksista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'selitti ne ja osoitti, että Kristuksen piti kärsiä ja nousta kuolleista, ja sanoi: \"Tämä Jeesus, jota minä teille julistan, on Kristus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Muutamat heistä uskoivat ja liittyivät Paavaliin ja Silaaseen, myös suuri joukko jumalaapelkääviä kreikkalaisia sekä useita ylhäisiä naisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Mutta epäuskoiset juutalaiset joutuivat kiihkoon ja ottivat avukseen muutamia pahoja miehiä joutoväestä, haalivat kansaa kokoon ja nostivat kaupungissa mellakan. He asettuivat Jaasonin talon edustalle ja etsivät Paavalia ja Silasta viedäkseen heidät kansan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Mutta kun he eivät heitä löytäneet, he raastoivat Jaasonin ja muutamia veljiä kaupungin hallitusmiesten eteen ja huusivat: \"Nuo koko maailman villitsijät ovat tulleet tännekin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'ja heidät Jaason on ottanut vastaan. Nämä kaikki tekevät vastoin keisarin asetuksia, sanoen erään toisen, Jeesuksen, olevan kuninkaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Kun kansa ja hallitusmiehet tämän kuulivat, he tulivat levottomiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'He ottivat takuun Jaasonilta ja muilta ja päästivät heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Mutta veljet lähettivät heti yötä myöten Paavalin ja Silaan Bereaan. Kun he olivat saapuneet sinne, he menivät juutalaisten synagogaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Nämä olivat jalompia kuin Tessalonikan juutalaiset. He ottivat sanan vastaan hyvin halukkaasti ja tutkivat joka päivä Kirjoituksia, oliko asia niin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Monet heistä uskoivat, niin myös useat ylhäiset kreikkalaiset naiset ja miehet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Mutta kun Tessalonikan juutalaiset saivat tietää, että Paavali Bereassakin julisti Jumalan sanaa, he tulivat sinnekin kiihottamaan kansaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Silloin veljet lähettivät heti Paavalin menemään meren rantaan, mutta sekä Silas että Timoteus jäivät Bereaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Paavalin saattajat veivät hänet Ateenaan saakka, ja saatuaan vietäväksi Silaalle ja Timoteukselle käskyn mitä pikimmin tulla hänen luokseen, he lähtivät sieltä pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Mutta Paavalin odottaessa heitä Ateenassa hänen henkensä kiivastui hänessä, kun hän näki, että kaupunki oli täynnä epäjumalankuvia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Hän keskusteli synagogassa juutalaisten ja jumalaapelkäävien kanssa ja torilla joka päivä niiden kanssa, joita hän siellä tapasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Muutamat epikurolaiset ja stoalaiset filosofit väittelivät hänen kanssaan, ja toiset sanoivat: \"Mitähän tuo lavertelija oikein tahtoo sanoa?\" Toiset taas sanoivat: \"Näkyy olevan vieraiden demonien julistaja\", koska hän julisti heille evankeliumia Jeesuksesta ja ylösnousemuksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'He ottivat hänet ja veivät Areiopagille ja sanoivat: \"Voimmeko saada tietää, mikä on se uusi oppi, jota sinä ilmoitat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Sillä outoja asioita tuot korviemme kuultavaksi. Tahdomme siis tietää, mitä ne oikein ovat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Sillä ateenalaisilla ja siellä oleskelevilla muukalaisilla ei ollut kenelläkään aikaa muuhun kuin uutta puhumaan ja uutta kuulemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Niin Paavali astui keskelle Areiopagia ja sanoi: \"Ateenan miehet, näen kaikesta, että te suuresti kunnioitatte jumalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Sillä kävellessäni ympäri ja katsellessani pyhiä paikkojanne löysin myös alttarin, johon oli kirjoitettu: \'Tuntemattomalle jumalalle.\' Sen, mitä siis tuntemattanne palvelette, minä teille ilmoitan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Jumala, joka on tehnyt maailman ja kaikki, mitä siinä on, hän, joka on taivaan ja maan Herra, ei asu käsillä tehdyissä temppeleissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'eikä häntä voida ihmisten käsillä palvella, ikään kuin hän tarvitsisi jotakin, hän, joka itse antaa kaikille elämän, hengen ja kaiken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'Hän on tehnyt koko ihmissuvun yhdestä verestä asumaan kaikkea maanpiiriä ja on säätänyt heille määrätyt ajat ja heidän asumisensa rajat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'että he etsisivät Jumalaa, jos ehkä voisivat hapuilemalla hänet löytää, hänet, joka kuitenkaan ei ole kaukana yhdestäkään meistä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'sillä hänessä [me] elämme, liikumme ja olemme, niin kuin myös muutamat teidän runoilijoistanne ovat sanoneet: \'Sillä olemme myös hänen sukuaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Koska siis olemme Jumalan sukua, emme saa luulla, että jumaluus on samanlainen kuin kulta, hopea tai kivi, kuin inhimillisen taiteen ja ajatuksen kuvaama.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Noita tietämättömyyden aikoja Jumala on kärsinyt, mutta nyt hän tekee tiettäväksi, että kaikkien ihmisten kaikkialla on muutettava mielensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'Sillä hän on säätänyt päivän, jona hän tuomitsee maanpiirin vanhurskaudessa sen miehen kautta, jonka hän on siihen määrännyt, ja tarjoaa kaikille uskoa herätettyään hänet kuolleista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Kuultuaan kuolleitten ylösnousemuksesta toiset ivasivat, toiset taas sanoivat: \"Haluamme kuulla sinulta tästä vielä toistekin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'Paavali lähti heidän keskeltään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Mutta muutamat liittyivät häneen ja uskoivat. Niiden joukossa oli Dionysios, Areiopagin jäsen, ja eräs nainen, nimeltä Damaris, sekä muita heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Sen jälkeen Paavali lähti Ateenasta ja meni Korinttoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'Siellä hän tapasi erään Akylas-nimisen juutalaisen, joka oli syntyisin Pontosta ja tullut hiljan Italiasta, ja hänen vaimonsa Priskillan. Klaudius oli näet käskenyt kaikkien juutalaisten poistua Roomasta. Paavali meni heidän luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'Kun hänellä oli sama ammatti kuin heillä, hän jäi heidän luokseen. He tekivät työtä yhdessä, sillä he olivat ammatiltaan teltantekijöitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Hän keskusteli synagogassa jokaisena sapattina ja vakuutti sekä juutalaiset että kreikkalaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Kun Silas ja Timoteus tulivat Makedoniasta, Paavali Hengen kehottamana todisti juutalaisille, että Jeesus on Kristus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Mutta kun he vastustivat ja herjasivat, hän pudisti vaatteitaan ja sanoi heille: \"Tulkoon teidän verenne oman päänne päälle! Viaton olen minä, tästedes menen pakanoiden luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Hän lähti sieltä ja meni erään Justus-nimisen jumalaapelkäävän miehen luo, jonka talo oli aivan synagogan vieressä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Mutta synagogan esimies Krispus ja koko hänen perhekuntansa uskoivat Herraan. Myös monet korinttolaiset, jotka olivat kuulemassa, uskoivat, ja heidät kastettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Herra sanoi yöllä näyssä Paavalille: \"Älä pelkää, vaan puhu, äläkä vaikene,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'sillä minä olen kanssasi, eikä kukaan käy sinuun käsiksi tehdäkseen sinulle pahaa, sillä minulla on paljon kansaa tässä kaupungissa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Hän viipyi siellä vuoden ja kuusi kuukautta opettaen heidän keskuudessaan Jumalan sanaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Mutta Gallionin ollessa Akaian käskynhaltijana juutalaiset yksimielisesti nousivat Paavalia vastaan ja veivät hänet tuomioistuimen eteen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'ja sanoivat: \"Tämä viettelee ihmisiä palvelemaan Jumalaa lain vastaisella tavalla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Kun Paavali aikoi avata suunsa, Gallion sanoi juutalaisille: \"Jos olisi tehty rikos tai häijy ilkityö, olisi syytä, että kärsivällisesti kuuntelisin teitä, juutalaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Mutta jos teillä on riitakysymyksiä opista ja nimistä ja teidän laistanne, olkoot ne teidän huolenanne. Niiden tuomari minä en tahdo olla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Hän ajoi heidät pois tuomioistuimen edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Kaikki kreikkalaiset ottivat kiinni Soosteneen, synagogan esimiehen, ja löivät häntä tuomioistuimen edessä, eikä Gallion välittänyt mitään siitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Mutta Paavali viipyi siellä vielä jonkin aikaa. Hän sanoi veljille jäähyväiset ja purjehti Syyriaan mukanaan Priskilla ja Akylas. Hän oli leikkauttanut tukkansa Kenkreassa, sillä hän oli tehnyt lupauksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'He saapuivat Efesoon. Sinne hän jätti heidät. Hän meni synagogaan ja keskusteli juutalaisten kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'He pyysivät häntä viipymään luonaan kauemmin, mutta hän ei suostunut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'vaan sanoi heille jäähyväiset ja lausui: \"Minun pitää joka tapauksessa mennä Jerusalemiin tulevan juhlan aikaan, mutta palaan luoksenne, jos Jumala suo.\" Ja hän lähti purjehtimaan Efesosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'Tultuaan Kesareaan hän nousi ja tervehti seurakuntaa ja meni sitten alas Antiokiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Oltuaan siellä jonkin aikaa hän lähti matkaan ja kulki järjestään Galatian maakunnan ja Fryygian kautta vahvistaen kaikkia opetuslapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Efesoon saapui eräs juutalainen, nimeltä Apollo, syntyisin Aleksandriasta, puhetaitoinen mies ja väkevä Kirjoituksissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Tälle oli opetettu Herran tie, ja hän puhui palavana hengessä ja opetti tarkoin Jeesuksesta, mutta tunsi ainoastaan Johanneksen kasteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Hän rupesi rohkeasti puhumaan synagogassa. Mutta kun Priskilla ja Akylas olivat häntä kuunnelleet, he ottivat hänet luokseen ja selittivät hänelle tarkemmin Jumalan tien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Kun hän tahtoi mennä Akaiaan, veljet kehottivat häntä siihen ja kirjoittivat opetuslapsille, että nämä ottaisivat hänet vastaan. Sinne saavuttuaan hän oli armon kautta suureksi hyödyksi uskoon tulleille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Sillä hän kumosi suurella voimalla julkisesti juutalaisten väitteet ja näytti Kirjoituksista toteen, että Jeesus on Kristus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Tapahtui Apollon ollessa Korinttossa, että Paavali kuljettuaan läpi ylämaakuntien tuli Efesoon ja tapasi siellä muutamia opetuslapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Hän sanoi heille: \"Saitteko Pyhän Hengen tullessanne uskoviksi?\" Niin he sanoivat hänelle: \"Emme ole edes kuulleet, että Pyhä Henki on olemassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Hän sanoi: \"Millä kasteella teidät sitten on kastettu?\" He vastasivat: \"Johanneksen kasteella.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Niin Paavali sanoi: \"Johannes kastoi mielenmuutoksen kasteella kehottaen kansaa uskomaan häneen, joka oli tuleva hänen jälkeensä, se on, Jeesukseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Kun he olivat sen kuulleet, heidät kastettiin Herran Jeesuksen nimeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'Kun Paavali pani kätensä heidän päälleen, tuli Pyhä Henki heidän päälleen, ja he puhuivat kielillä ja profetoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Heitä oli kaikkiaan noin kaksitoista miestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Hän meni synagogaan, ja kolmen kuukauden ajan hän puhui heidän kanssaan rohkeasti ja vakuuttaen heitä Jumalan valtakunnan asioista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Mutta kun muutamat paaduttivat itsensä eivätkä uskoneet, vaan puhuivat pahaa Herran tiestä kansan edessä, hän meni pois heidän luotaan ja erotti opetuslapset heistä ja piti joka päivä keskusteluja erään Tyrannoksen koulussa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Sitä kesti kaksi vuotta, niin että kaikki Aasian maakunnan asukkaat, sekä juutalaiset että kreikkalaiset, saivat kuulla Herran sanan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'Jumala teki hyvin voimallisia tekoja Paavalin kätten kautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'niin että vieläpä hikiliinoja ja esiliinoja vietiin hänen iholtaan sairaiden päälle, ja taudit lähtivät heistä ja pahat henget pakenivat pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Myös muutamat kiertelevät juutalaiset loitsijat rupesivat lausumaan Herran Jeesuksen nimeä niiden yli, joissa oli pahoja henkiä, sanoen: \"Vannotamme teitä sen Jeesuksen kautta, jota Paavali julistaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Niiden joukossa, jotka näin tekivät, oli myös erään juutalaisen ylipapin, Skeuaan, seitsemän poikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Mutta paha henki vastasi heille sanoen: \"Jeesuksen tunnen, ja Paavalin tiedän, mutta keitä te olette?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'Silloin mies, jossa oli paha henki, karkasi heidän kimppuunsa, voitti heidät toinen toisensa perästä ja runteli heitä, niin että he vähissä vaatteissa ja haavoitettuina pakenivat talosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Tämän saivat tietää kaikki Efeson asukkaat, sekä juutalaiset että kreikkalaiset. Heidät kaikki valtasi pelko, ja Herran Jeesuksen nimeä ylistettiin suuresti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Monet niistä, jotka olivat tulleet uskoviksi, menivät ja tunnustivat ja ilmoittivat tekonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Useat niistä, jotka olivat harjoittaneet taikuutta, kantoivat kirjansa kokoon ja polttivat ne kaikkien nähden. Kun niiden arvo laskettiin yhteen, huomattiin sen olevan viisikymmentä tuhatta hopearahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Herran sana kasvoi voimallisesti ja vahvistui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Kun kaikki tämä oli tapahtunut, Paavali päätti Hengessä kulkea Makedonian ja Akaian kautta ja matkustaa Jerusalemiin ja sanoi: \"Oltuani siellä minun pitää nähdä myös Rooma.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Hän lähetti Makedoniaan kaksi apulaistaan, Timoteuksen ja Erastuksen, mutta jäi itse joksikin aikaa Aasiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Tähän aikaan syntyi varsin suuri melu siitä tiestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Sillä eräs hopeaseppä, nimeltä Demetrios, joka valmisti hopeisia Artemiin temppeleitä, hankki sillä ammattilaisille melkoisia tuloja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Hän kutsui kokoon nämä sekä muut, jotka tekivät sellaista työtä, ja sanoi: \"Miehet, te tiedätte, että meillä on hyvä toimeentulo tästä työstä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'Mutta nyt näette ja kuulette, että tuo Paavali on, ei ainoastaan Efesossa, vaan melkein koko Aasian maakunnassa, uskotellut ja vietellyt paljon kansaa, sanoen, etteivät ne ole jumalia, jotka käsin tehdään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Nyt on vaarana, ettei ainoastaan tämä elinkeinomme joudu halveksituksi, vaan myös, ettei suuren Artemis-jumalattaren temppeliä pidetä minään ja että hän menettää suuruutensa, hän, jota koko Aasian maakunta ja koko maanpiiri palvelee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Kun he sen kuulivat, he tulivat vihaa täyteen ja huusivat sanoen: \"Suuri on efesolaisten Artemis!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'Koko kaupunki joutui sekasortoon, ja he ryntäsivät kaikki yhdessä teatteriin ja tempasivat mukaansa Gaiuksen ja Aristarkuksen, kaksi makedonialaista, jotka olivat Paavalin matkatovereita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Kun Paavali tahtoi mennä kansanjoukkoon, opetuslapset eivät sallineet sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Myös muutamat Aasian maakunnan hallitusmiehistä, jotka olivat hänen ystäviään, lähettivät hänelle sanan ja pyysivät, ettei hän menisi teatteriin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'He huusivat, kuka mitäkin, sillä kokous oli sekasortoinen, ja useimmat eivät tienneet, minkä tähden he olivat tulleet kokoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Silloin vedettiin joukosta esille Aleksander, jota juutalaiset työnsivät esiin. Niin Aleksander viittoili kädellään merkiksi, että hän tahtoi pitää puolustuspuheen kansan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Mutta havaitessaan hänen olevan juutalainen he huusivat kaikki yhteen ääneen noin kaksi tuntia: \"Suuri on efesolaisten Artemis!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Mutta kun kaupungin kansleri oli saanut kansan rauhoittumaan, hän sanoi: \"Efeson miehet, onko ketään, joka ei tiedä, että efesolaisten kaupunki on suuren Artemiin temppelin ja hänen taivaasta pudonneen kuvansa vaalija?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Koska tämä on kiistatonta, teidän tulee siis pysyä rauhallisina eikä tehdä mitään harkitsematonta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Olette kuitenkin tuoneet tänne nämä miehet, jotka eivät ole temppelin ryöstäjiä eivätkä ole meidän jumalatartamme pilkanneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Jos siis Demetriuksella ja hänen ammattitovereillaan on riita-asiaa jotakuta vastaan, niin pidetäänhän oikeudenistuntoja ja onhan käskynhaltijoita. Vetäkööt toisensa oikeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Jos teillä on vielä jotakin muuta vaadittavaa, niin ratkaistakoon asia laillisessa kansankokouksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Sillä tämänpäiväisen tapahtuman tähden olemme vaarassa joutua syytteeseen kapinasta, vaikkei mitään aihetta olekaan. Silloin emme voi vastata tästä mellakasta.\" Näin puhuen hän sai kokouksen hajaantumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Kun meteli oli asettunut, Paavali kutsui opetuslapset luokseen, hyvästeli heidät ja lähti matkustamaan Makedoniaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Kuljettuaan niiden paikkakuntien läpi ja puhuttuaan siellä monta kehotuksen sanaa hän tuli Kreikkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'Siellä hän oleskeli kolme kuukautta. Kun juutalaiset olivat tehneet häntä vastaan salahankkeen hänen aikoessaan lähteä purjehtimaan Syyriaan, hän päätti palata Makedonian kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Häntä seurasivat Aasian maakuntaan asti berealainen Soopater, tessalonikalaisista Aristarkus ja Sekundus, derbeläinen Gaius, Timoteus sekä Aasian maakuntalaiset Tykikus ja Trofimus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Nämä menivät edeltä ja odottivat meitä Trooaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Me taas purjehdimme happamattoman leivän juhlan jälkeen Filippistä ja tulimme viidentenä päivänä heidän luokseen Trooaaseen ja viivyimme siellä seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'Kun viikon ensimmäisenä päivänä olimme kokoontuneet murtamaan leipää, Paavali, joka seuraavana päivänä aikoi matkustaa pois, keskusteli heidän kanssaan ja pitkitti puhettaan puoliyöhön asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Monta lamppua oli palamassa yläsalissa, jossa olimme koolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Eräs nuorukainen, nimeltä Eutykos, istui ikkunalla, ja kun Paavalin puhe kesti niin kauan, hän vaipui sikeään uneen ja putosi uneen vaipuneena kolmannesta kerroksesta alas, ja hänet nostettiin maasta kuolleena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Mutta Paavali meni alas, kumartui hänen ylitseen, kiersi kätensä hänen ympärilleen ja sanoi: \"Älkää hätäilkö, sillä hänessä on vielä henki.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Hän meni jälleen ylös, mursi leipää ja söi. Hän puhui kauan heidän kanssaan, päivän koittoon asti, ja lähti sitten matkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'He veivät pojan sieltä elävänä ja tulivat suuresti lohdutetuiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Mutta me menimme edeltä ja astuimme laivaan ja purjehdimme Assoon. Sieltä aioimme ottaa Paavalin laivaan, sillä hän oli niin määrännyt aikoen itse kulkea maitse.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Kun hän liittyi meihin Assossa, otimme hänet laivaan ja tulimme Mityleneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'Sieltä purjehdimme ja saavuimme seuraavana päivänä Kion kohdalle. Seuraavana päivänä saavuimme Samoon ja viivyttyämme Trogyllionissa tulimme seuraavana päivänä Miletoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Sillä Paavali oli päättänyt purjehtia Efeson ohi, ettei häneltä kuluisi aikaa Aasiassa. Hän näet piti kiirettä ehtiäkseen, jos mahdollista, helluntaiksi Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Mutta Miletosta hän lähetti sanan Efesoon ja kutsui luokseen seurakunnan vanhimmat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Kun he saapuivat hänen luokseen, hän sanoi heille: \"Te tiedätte ensimmäisestä päivästä asti, kun tulin Aasian maakuntaan, miten olen kaiken aikaa ollut kanssanne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'kuinka olen palvellut Herraa kaikella nöyryydellä ja monin kyynelin ja koettelemuksissa, jotka ovat kohdanneet minua juutalaisten salahankkeiden tähden;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'kuinka en ole vetäytynyt pois julistamasta teille sitä, mikä on hyödyllistä, ja opettamasta teitä julkisesti ja huone huoneelta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'Olen todistanut sekä juutalaisille että kreikkalaisille parannusta kääntymyksessä Jumalan puoleen ja uskoa meidän Herraamme Jeesukseen Kristukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'Nyt, katso, minä matkustan Hengen sitomana Jerusalemiin, enkä tiedä, mikä siellä kohtaa minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'Sen vain tiedän, että Pyhä Henki jokaisessa kaupungissa todistaa minulle ja sanoo, että kahleet ja ahdistukset odottavat minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'En kuitenkaan pidä henkeäni itselleni minkään arvoisena, kunhan vain täytän juoksuni ilolla ja sen viran, jonka olen saanut Herralta Jeesukselta: Jumalan armon evankeliumin todistamisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'Nyt, katso, minä tiedän, ettette enää saa nähdä kasvojani, ei kukaan teistä, joiden keskuudessa olen vaeltanut ja saarnannut Jumalan valtakuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Sen tähden todistan teille tänä päivänä, että minä olen viaton kaikkien vereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Sillä en ole vetäytynyt pois julistamasta teille Jumalan koko neuvoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Ottakaa siis vaari itsestänne ja kaikesta laumasta, johon Pyhä Henki on pannut teidät kaitsijoiksi paimentamaan Jumalan seurakuntaa, jonka hän omalla verellään on itselleen ansainnut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Minä tiedän, että lähtöni jälkeen keskuuteenne tulee julmia susia, jotka eivät laumaa säästä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'ja teidän omasta joukostanne nousee miehiä, jotka väärää oppia puhuvat vetääkseen opetuslapset mukaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Valvokaa sen tähden ja muistakaa, että olen kolme vuotta lakkaamatta yötä ja päivää kyynelin neuvonut teitä itse kutakin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'Nyt uskon teidät, veljet, Jumalan ja hänen armonsa sanan haltuun, hänen, joka on voimallinen rakentamaan teitä ja antamaan teille perintöosan kaikkien pyhitettyjen joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'En ole halunnut kenenkään hopeaa, kultaa tai vaatteita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Tiedätte itse, että nämä käteni ovat työllään hankkineet, mitä tovereitteni kanssa olen tarvinnut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'Kaikessa olen osoittanut teille, että näin työtä tehden tulee huolehtia heikoista ja muistaa nämä Herran Jeesuksen sanat, jotka hän itse sanoi: \'Autuaampaa on antaa kuin ottaa vastaan.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'Tämän sanottuaan hän polvistui ja rukoili heidän kaikkien kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'He ratkesivat kaikki haikeasti itkemään ja lankesivat Paavalin kaulaan ja suutelivat häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'Eniten heitä suretti se sana, jonka hän oli sanonut, etteivät he enää saisi nähdä hänen kasvojaan. He saattoivat hänet laivaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Tapahtui, että erosimme heistä ja lähdimme purjehtimaan kiireesti suoraa päätä Koos-saareen, mutta seuraavana päivänä Rodoon ja sieltä Pataraan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Sieltä löysimme Foinikiaan menevän laivan, astuimme siihen ja lähdimme purjehtimaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Kun Kypros alkoi näkyä ja oli jäänyt vasemmalle, purjehdimme Syyriaan ja laskimme maihin Tyyroon. Siellä laivan oli näet määrä purkaa lastinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Tavattuamme opetuslapset viivyimme siellä seitsemän päivää. He sanoivat Hengen vaikutuksesta Paavalille, ettei hän menisi Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Mutta kun ne päivät olivat kuluneet, lähdimme matkaan, ja kaikki saattoivat vaimoineen ja lapsineen meitä kaupungin ulkopuolelle saakka. Laskeuduimme rannalla polvillemme ja rukoilimme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'Sanottuamme jäähyväiset toisillemme astuimme laivaan, ja he palasivat koteihinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Tyyrosta me saavuimme Ptolemaihin, ja siihen päättyi purjehduksemme. Tervehdimme veljiä siellä ja viivyimme päivän heidän luonaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Mutta seuraavana päivänä me, jotka olimme olleet Paavalin mukana, lähdimme sieltä ja tulimme Kesareaan, jossa menimme evankelista Filippoksen taloon, joka oli yksi niistä seitsemästä, ja jäimme hänen luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Hänellä oli neljä tytärtä, neitsyttä, jotka profetoivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Siellä viivyimme useita päiviä. Sinne tuli Juudeasta eräs profeetta, nimeltä Agabus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Tultuaan luoksemme hän otti Paavalin vyön, sitoi sillä hänen jalkansa ja kätensä ja lausui: \"Näin sanoo Pyhä Henki: \'Sen miehen, jonka vyö tämä on, juutalaiset sitovat näin Jerusalemissa ja luovuttavat pakanoiden käsiin.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Kun sen kuulimme, kehotimme, sekä me että ne, jotka siellä asuivat, ettei hän menisi Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Silloin Paavali vastasi ja sanoi: \"Mitä teette, kun itkette ja särjette sydäntäni? Sillä minä olen valmis, en ainoastaan tulemaan sidotuksi, vaan myös kuolemaan Jerusalemissa Herran Jeesuksen nimen tähden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'Mutta kun hän ei taipunut, rauhoituimme ja sanoimme: \"Tapahtukoon Herran tahto.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Niiden päivien kuluttua valmistauduimme matkaan ja menimme ylös Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Kanssamme lähti myös opetuslapsia Kesareasta, jotka veivät meidät majapaikkaamme erään vanhan opetuslapsen, kyproslaisen Mnasonin, luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Saavuttuamme Jerusalemiin veljet ottivat meidät iloiten vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Seuraavana päivänä Paavali meni kanssamme Jaakobin luo, ja kaikki vanhimmat saapuivat sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Kun hän oli heitä tervehtinyt, hän kertoi kohta kohdalta kaikki, mitä Jumala hänen palvelusvirkansa kautta oli tehnyt pakanoiden keskuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Sen kuultuaan he ylistivät Jumalaa ja sanoivat Paavalille: \"Sinä näet, veli, kuinka monta tuhatta juutalaista on niitä, jotka ovat uskoneet, ja he ovat kaikki lainkiivailijoita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Mutta heille on kerrottu sinusta, että opetat kaikkia pakanoiden keskuudessa asuvia juutalaisia luopumaan Mooseksesta sanoen, etteivät ympärileikkaisi lapsiaan ja vaeltaisi tapojen mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Mitä siis on tehtävä? Varmaankin on suuri joukko kokoontuva, sillä he saavat kuulla sinun tulleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Tee siis tämä, minkä sinulle sanomme. Meillä on täällä neljä miestä, joilla on lupaus täytettävänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Ota heidät luoksesi ja puhdistaudu heidän kanssaan ja maksa kulut heidän puolestaan, että he leikkauttaisivat tukkansa. Siitä kaikki huomaavat, ettei ole mitään perää siinä, mitä heille on kerrottu sinusta, vaan että sinäkin vaellat lain mukaan ja noudatat sitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Mutta pakanoista, jotka ovat uskoneet, me olemme päättäneet ja kirjoittaneet kirjeen, että heidän täytyy karttaa epäjumalille uhrattua, verta ja lihaa, jonka veri ei ole laskettu pois, sekä haureutta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Silloin Paavali otti miehet luokseen, ja kun hän seuraavana päivänä oli puhdistautunut heidän kanssaan, hän meni temppeliin ja ilmoitti, milloin heidän puhdistumispäivänsä tulisivat päättymään, jota ennen heidän oli tuotava uhri itse kunkin edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Mutta kun ne seitsemän päivää olivat päättymässä, näkivät Aasian maakunnasta tulleet juutalaiset hänet temppelissä, saattoivat koko kansan kiihdyksiin ja kävivät häneen käsiksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'ja huusivat: \"Israelin miehet, auttakaa! Tämä on se mies, joka opettaa kaikkialla kaikkia ihmisiä kansaamme, lakiamme ja tätä paikkaa vastaan, onpa vielä tuonut kreikkalaisia temppeliinkin ja saastuttanut tämän pyhän paikan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Sillä he olivat ennen nähneet efesolaisen Trofimoksen kaupungilla hänen kanssaan ja luulivat, että Paavali oli tuonut hänet temppeliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Koko kaupunki lähti liikkeelle, ja väkeä juoksi kokoon. He ottivat Paavalin kiinni, raastoivat hänet ulos temppelistä, ja heti portit suljettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Mutta kun he tahtoivat tappaa hänet, sai sotaväenosaston tuhannenpäällikkö sanan, että koko Jerusalem oli kuohuksissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Tämä otti heti paikalla mukaansa sotilaita ja sadanpäälliköitä ja juoksi alas heidän luokseen. Kun he näkivät tuhannenpäällikön ja sotilaat, he lakkasivat lyömästä Paavalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Silloin päällikkö astui esiin, otatti hänet kiinni, käski sitoa hänet kaksilla kahleilla ja kysyi, kuka hän oli ja mitä hän oli tehnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'Mutta kansanjoukosta huusivat toiset sitä, toiset tätä. Koska hän melun tähden ei voinut saada varmuutta, hän käski viedä hänet kasarmiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Mutta kun Paavali tuli portaille, täytyi sotamiesten kantaa häntä kansan väkivallan tähden,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'sillä suuri kansanpaljous seurasi perässä ja huusi: \"Vie pois hänet!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Kun oltiin kuljettamassa Paavalia sisälle kasarmiin, hän sanoi tuhannenpäällikölle: \"Onko minun lupa sanoa sinulle jotakin?\" Niin tämä sanoi: \"Osaatko kreikkaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Etkö sitten olekaan se egyptiläinen, joka hiljan nosti kapinaan ne neljätuhatta murhamiestä ja vei heidät erämaahan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Paavali sanoi: \"Minä olen juutalainen mies, Tarson, huomattavan Kilikian kaupungin, kansalainen. Pyydän sinua, salli minun puhua kansalle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Kun hän sen salli, Paavali, seisoen portailla viittasi kädellään kansalle. Kun oli syntynyt syvä hiljaisuus, hän puhui heille heprean kielellä ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, '\"Miehet, veljet ja isät, kuulkaa puolustuspuhettani, jonka nyt teille pidän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Kun he kuulivat hänen puhuvan heille hepreankielellä, syntyi vielä suurempi hiljaisuus. Hän sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, '\"Minä olen juutalainen, syntynyt Kilikian Tarsossa, mutta kasvatettu tässä kaupungissa ja opetettu Gamalielin jalkojen juuressa noudattamaan tarkasti isien lakia. Olin Jumalan puolesta kiivailija, niin kuin te kaikki tänä päivänä olette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'Vainosin tätä tietä aina kuolemaan asti, sitoen ja luovuttaen vankiloihin sekä miehiä että naisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'kuten myös ylipappi minusta todistaa, ja koko vanhimmisto. Sain heiltä myös kirjeitä veljille, ja matkustin Damaskoon tuodakseni sidottuina Jerusalemiin rangaistaviksi ne, jotka siellä olivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Niin tapahtui, kun matkalla ollessani lähestyin Damaskoa, että keskipäivän aikaan leimahti yhtäkkiä taivaasta kirkas valo ympärilläni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Kaaduin maahan ja kuulin äänen sanovan minulle: \'Saul, Saul, miksi vainoat minua?\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Minä vastasin: \'Kuka olet, herra?\' Hän sanoi minulle: \'Minä olen Jeesus Nasaretilainen, jota sinä vainoat.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Ne, jotka olivat kanssani, näkivät tosin valon, mutta eivät saaneet selvää äänestä, joka minulle puhui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Sanoin: \'Herra, mitä minun pitää tehdä?\' Herra sanoi minulle: \'Nouse ja mene Damaskoon, siellä sinulle sanotaan kaikki, mikä sinulle on tehtäväksi asetettu.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Kun valon kirkkaudesta tulin näkemättömäksi, taluttivat toverini minua kädestä, ja saavuin Damaskoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Eräs mies, hurskas lain mukaan, nimeltä Ananias, josta kaikki siellä asuvat juutalaiset todistivat hyvää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'tuli luokseni, astui eteeni ja sanoi minulle: \'Saul, veljeni, näe jälleen.\' Siitä hetkestä minä näin hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Hän sanoi: \'Isiemme Jumala on valinnut sinut tuntemaan hänen tahtonsa ja näkemään Vanhurskaan ja kuulemaan hänen suunsa äänen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'sillä sinä olet oleva hänen todistajansa kaikkien ihmisten edessä, sen, mitä olet nähnyt ja kuullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Nyt, mitä viivyttelet? Nouse, huuda avuksi Herran nimeä, ota kaste ja pese pois syntisi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Kun olin palannut Jerusalemiin, tapahtui rukoillessani temppelissä, että jouduin hurmoksiin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'ja näin hänet. Hän sanoi minulle: \'Riennä ja lähde pian pois Jerusalemista, sillä he eivät ota vastaan todistustasi minusta.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'Minä sanoin: \'Herra, he tietävät itse, että minä panin vankilaan ja ruoskin jokaisessa synagogassa niitä, jotka uskoivat sinuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'Kun Stefanoksen, sinun todistajasi, veri vuodatettiin, olin itsekin läsnä, hyväksyin hänen murhaamisensa ja vartioin hänen surmaajiensa vaatteita.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Mutta hän sanoi minulle: \'Mene, sillä minä lähetän sinut kauas pakanoiden luo.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Tähän sanaan asti he kuuntelivat häntä. Mutta silloin he korottivat äänensä ja sanoivat: \"Pois maan päältä tuollainen! Sillä hänen ei sovi elää.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Kun he huusivat ja heittelivät vaatteitaan ja viskelivät tomua ilmaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'käski tuhannenpäällikkö viedä hänet kasarmiin, ja saadakseen tietää, mistä syystä he niin hänelle huusivat, hän määräsi hänet ruoskimalla tutkittavaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Mutta kun he olivat oikaisseet hänet ruoskittavaksi, Paavali sanoi siinä seisovalle sadanpäällikölle: \"Onko teidän lupa ruoskia Rooman kansalaista, vieläpä ilman tuomiota?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Kun sadanpäällikkö sen kuuli, hän meni ilmoittamaan tuhannenpäällikölle ja sanoi: \"Mitä aiot tehdä? Tämä mies on Rooman kansalainen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Niin päällikkö meni Paavalin luo ja sanoi hänelle: \"Sano minulle: oletko sinä Rooman kansalainen?\" Hän sanoi: \"Olen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'Niin tuhannenpäällikkö vastasi: \"Minä olen paljolla rahalla hankkinut itselleni tämän kansalaisoikeuden.\" Paavali sanoi: \"Mutta minulla se on syntymästäni asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Silloin ne, jotka aikoivat tutkia häntä, lähtivät heti hänen luotaan. Myös päällikkö pelästyi saatuaan tietää, että Paavali oli Rooman kansalainen, kun oli sitonut hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Mutta seuraavana päivänä – koska hän tahtoi saada varman tiedon, mistä juutalaiset häntä syyttivät – hän päästi hänet siteistä ja käski ylipappien ja koko Neuvoston kokoontua, vei Paavalin alas ja asetti hänet heidän eteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Paavali loi katseensa Neuvostoon ja sanoi: \"Miehet, veljet, minä olen kaikessa hyvällä omallatunnolla vaeltanut Jumalan edessä tähän päivään asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Mutta ylipappi Ananias käski lähellä seisovia lyömään häntä vasten suuta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Silloin Paavali sanoi hänelle: \"Jumala on lyövä sinua, sinä valkeaksi kalkittu seinä. Istutko sinä tuomitsemassa minua lain mukaan ja käsket vastoin lakia lyödä minua?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Niin ne, jotka seisoivat lähellä, sanoivat: \"Solvaatko sinä Jumalan ylipappia?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Paavali sanoi: \"En tiennyt, veljet, että hän on ylipappi, sillä kirjoitettu on: \'Kansasi ruhtinasta älä kiroa.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Mutta koska Paavali tiesi osan heistä olevan saddukeuksia ja toisen osan fariseuksia, hän huusi Neuvoston edessä: \"Miehet, veljet, minä olen fariseus, fariseuksen poika. Toivon ja kuolleitten ylösnousemuksen tähden minä olen tuomittavana.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Kun hän oli tämän sanonut, nousi riita fariseusten ja saddukeusten kesken, ja kokous jakaantui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Sillä saddukeukset sanovat, ettei ylösnousemusta ole, ei enkeliä eikä henkeä, mutta fariseukset tunnustavat kummatkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Syntyi suuri huuto, ja muutamat kirjanoppineet fariseusten puolueesta nousivat ja väittelivät kiivaasti ja sanoivat: \"Emme löydä mitään pahaa tästä miehestä. Entä jos henki tai enkeli on puhunut hänelle? Älkäämme taistelko Jumalaa vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Kun riita yhä kiihtyi, tuhannenpäällikkö pelkäsi, että he repisivät Paavalin kappaleiksi, ja käski sotaväen tulla alas ja temmata hänet heidän keskeltään ja viedä hänet kasarmiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'Mutta seuraavana yönä Herra seisoi Paavalin luona ja sanoi: \"Ole turvallisella mielellä, sillä niin kuin olet todistanut minusta Jerusalemissa, niin sinun pitää todistaa minusta myös Roomassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Mutta päivän tultua juutalaiset tekivät salaliiton ja vannoivat valan, etteivät söisi eivätkä joisi, ennen kuin olivat tappaneet Paavalin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Niitä oli yli neljäkymmentä miestä, jotka tekivät tämän salaliiton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'He menivät ylipappien ja vanhinten luo ja sanoivat: \"Me olemme kirotuksi tulemisen uhalla vannoneet, ettemme maista mitään, ennen kuin olemme tappaneet Paavalin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Pyytäkää te siis nyt yhdessä Neuvoston kanssa tuhannenpäälliköltä, että hän toisi hänet alas luoksenne, ikään kuin aikoisitte tarkemmin tutkia hänen asiaansa. Mutta me olemme valmiita tappamaan hänet, ennen kuin hän pääsee perille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Paavalin sisarenpoika, joka oli saanut kuulla väijytyksestä, saapui kasarmille, meni sisälle ja ilmoitti sen Paavalille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Niin Paavali kutsui luokseen erään sadanpäällikön ja sanoi: \"Vie tämä nuorukainen tuhannenpäällikön luo, sillä hänellä on hänelle jotakin ilmoitettavaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Hän otti hänet mukaansa, vei hänet tuhannenpäällikön luo ja sanoi: \"Vanki Paavali kutsui minut luokseen ja pyysi tuomaan luoksesi tämän nuorukaisen, jolla on jotakin puhuttavaa sinulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Tuhannenpäällikkö tarttui hänen käteensä, vei hänet erilleen ja kysyi: \"Mitä ilmoitettavaa sinulla on minulle?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Hän sanoi: \"Juutalaiset ovat päättäneet anoa sinulta, että veisit Paavalin huomenna alas Neuvostoon, ikään kuin aikoisit vielä tarkemmin tutkia hänen asiaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Mutta älä sinä suostu siihen, sillä yli neljäkymmentä miestä heidän joukostaan on häntä väijymässä, ja he ovat vannoneet valan, etteivät syö eivätkä juo, ennen kuin ovat tappaneet hänet. Nyt he ovat valmiina ja odottavat suostumustasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Tuhannenpäällikkö päästi nuorukaisen menemään ja sanoi hänelle: \"Älä kerro kenellekään, että olet ilmaissut tämän minulle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Sitten hän kutsui luokseen kaksi sadanpäällikköä ja sanoi heille: \"Pitäkää yön kolmannesta hetkestä lähtien kaksisataa sotilasta valmiina lähtemään Kesareaan ja seitsemänkymmentä ratsumiestä ja kaksisataa keihäsmiestä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'ja varatkaa ratsuja pannaksenne Paavalin ratsaille ja viedäksenne hänet vahingoittumattomana maaherra Feeliksin luo.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Hän kirjoitti kirjeen, joka kuului näin:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, '\"Klaudius Lysias lausuu tervehdyksen korkea-arvoiselle maaherra Feeliksille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Tämän miehen ottivat juutalaiset kiinni ja aikoivat tappaa hänet. Tulin paikalle sotaväen kanssa ja pelastin hänet, saatuani tietää, että hän on Rooman kansalainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'Koska tahdoin tietää, mistä asiasta he häntä syyttivät, vein hänet heidän Neuvostoonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'Havaitsin, että häntä syytettiin heidän lakiaan koskevista riitakysymyksistä, mutta ettei ollut kannetta mistään, mikä ansaitsisi kuoleman tai kahleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Mutta kun minulle on annettu ilmi, että miestä vastaan on tekeillä salahanke, lähetän hänet nyt heti luoksesi. Olen myös kehottanut hänen syyttäjiään sanomaan sanottavansa häntä vastaan sinun edessäsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Sotamiehet saamansa käskyn mukaan ottivat Paavalin ja veivät hänet yötä myöten Antipatrikseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'Seuraavana päivänä he antoivat ratsumiesten jatkaa hänen kanssaan matkaa, mutta itse he palasivat kasarmiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Kun ratsumiehet tulivat Kesareaan, he antoivat kirjeen maaherralle ja veivät myös Paavalin hänen eteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Luettuaan kirjeen hän kysyi, mistä maakunnasta Paavali oli. Saatuaan tietää, että hän oli Kilikiasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'hän sanoi: \"Kuulustelen sinua, kun syyttäjäsikin saapuvat.\" Hän käski vartioida häntä Herodeksen linnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Viiden päivän kuluttua ylipappi Ananias meni sinne alas vanhinten ja erään asianajajan, Tertulluksen, kanssa, ja he ilmoittivat maaherralle syyttävänsä Paavalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Kun Paavali oli kutsuttu esille, Tertullus ryhtyi syyttämään ja sanoi:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, '\"Runsasta rauhaa olemme saaneet kauttasi nauttia, ja sinun toimestasi on saatu aikaan parannuksia tämän kansan hyväksi, sen kaikin puolin, kaikkialla ja kaikella kiitollisuudella tunnustamme, korkea-arvoinen Feeliks.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Mutta etten kauan sinua viivyttäisi, pyydän sinua hetkisen meitä suosiollisesti kuulemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Olemme havainneet, että tämä mies on ruttotauti ja kapinannostaja kaikkien koko maanpiirin juutalaisten keskuudessa ja nasaretilaisten lahkon päämies,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'ja hän on yrittänyt saastuttaa temppelinkin. Sen tähden otimme hänet kiinni ja halusimme tuomita hänet meidän lakimme mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Mutta Lysias, tuhannenpäällikkö, tuli ja vei hänet pois suurta voimaa käyttäen käsistämme');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'ja määräsi hänen syyttäjiensä tulemaan luoksesi. Voit itse häntä tutkimalla saada tietää kaiken, mistä me häntä syytämme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Myös juutalaiset olivat samaa mieltä ja vakuuttivat asian niin olevan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Paavali vastasi, kun maaherra oli nyökännyt, että hän sai puhua: \"Koska tiedän sinun monta vuotta olleen tämän kansan tuomarina, puhun luottamuksella asiani puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Niin kuin voit saada tietää, ei ole kuin kaksitoista päivää siitä, kun menin Jerusalemiin rukoilemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'He eivät tavanneet minua kenenkään kanssa väittelemästä eivätkä väentungoksia aikaansaamasta, ei temppelissä, synagogissa eikä kaupungilla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'eivätkä myöskään voi näyttää sinulle toteen sitä, mistä he nyt syyttävät minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Mutta sen sinulle tunnustan, että sen tien mukaisesti, jota he lahkoksi sanovat, niin palvelen isieni Jumalaa, että uskon kaiken, mitä on kirjoitettuna Laissa ja Profeetoissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'pitäen sen toivon Jumalaan, että on oleva ylösnousemus, jota nämä itsekin odottavat, sekä vanhurskasten että väärien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'Sen tähden myös ahkeroin, että minulla olisi aina loukkaamaton omatunto Jumalan ja ihmisten edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Mutta nyt useampien vuosien kuluttua tulin tuomaan almuja kansalleni ja toimittamaan uhreja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'Näitä toimittaessani muutamat Aasian maakunnasta tulleet juutalaiset tapasivat minut puhdistautuneena temppelissä, eikä ollut mitään väentungosta tai kapinaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Heidän tulisi nyt olla saapuvilla sinun edessäsi ja syyttää, jos heillä olisi jotakin minua vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Tai sanokoot nämä läsnä olevat, mitä rikollista he minussa huomasivat, kun seisoin Neuvoston edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'jollei siksi luettane tätä ainoaa lausetta, jonka huusin seisoessani heidän keskellään: \'Kuolleitten ylösnousemuksen tähden minä olen tänään teidän tuomittavananne.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Mutta Feeliks, jolla oli hyvin tarkka tieto tästä tiestä, lykkäsi heidän asiansa toistaiseksi, sanoen: \"Kun tuhannenpäällikkö Lysias tulee tänne, tutkin teidän asianne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Hän käski sadanpäällikön pitää Paavalia vartioituna, mutta lievässä vankeudessa estämättä ketään hänen omaisistaan tekemästä hänelle palvelusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Muutamien päivien kuluttua Feeliks tuli vaimonsa Drusillan kanssa, joka oli juutalainen, haetti Paavalin ja kuunteli hänen puhettaan uskosta Kristukseen Jeesukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Mutta kun Paavali puhui vanhurskaudesta ja itsensähillitsemisestä ja tulevasta tuomiosta, Feeliks pelästyi ja sanoi: \"Mene tällä kertaa pois, mutta kun minulle sopii, kutsun sinut taas.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Sen lisäksi hän myös toivoi, että Paavali antaisi hänelle rahaa, jotta hän päästäisi hänet vapaaksi. Sen tähden hän useita kertoja haetti hänet luokseen ja puhui hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Mutta kahden vuoden kuluttua Porkius Festus tuli Feeliksin sijaan. Kun Feeliks tavoitteli juutalaisten suosiota, hän jätti Paavalin kahleisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Kun nyt Festus oli astunut maaherran virkaan, hän lähti kolmen päivän kuluttua Kesareasta ylös Jerusalemiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Ylipapit ja juutalaisten ensimmäiset miehet ilmoittivat hänelle syyttävänsä Paavalia ja pyysivät häneltä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'ja anoivat suosionosoitusta Paavalia vastaan, että hän lähettäisi hakemaan hänet Jerusalemiin. He näet valmistelivat väijytystä tappaakseen hänet matkalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Mutta Festus vastasi, että Paavalia pidettiin Kesareassa ja että hän itse aikoi heti lähteä sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'Hän sanoi: \"Tulkoot siis teidän johtajanne mukanani sinne alas, ja jos siinä miehessä on jotakin väärää, syyttäkööt häntä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Viivyttyään heidän luonaan runsaat kymmenen päivää hän meni alas Kesareaan. Seuraavana päivänä hän istui tuomarinistuimelle ja käski tuoda Paavalin eteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Kun hän oli saapunut, asettuivat ne juutalaiset, jotka olivat tulleet Jerusalemista, hänen ympärilleen ja tekivät useita ja raskaita syytöksiä, joita he eivät kyenneet näyttämään toteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Paavali näet torjui syytökset ja sanoi: \"En ole rikkonut mitään juutalaisten lakia, temppeliä enkä keisaria vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Festus, joka tavoitteli juutalaisten suosiota, vastasi Paavalille ja sanoi: \"Tahdotko lähteä Jerusalemiin ja siellä vastata näihin syytöksiin minun edessäni?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Mutta Paavali sanoi: \"Seison keisarin tuomioistuimen edessä, ja sen edessä minut tulee tuomita. Juutalaisia vastaan en ole mitään rikkonut, niin kuin sinä hyvin tiedät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Vaan jos muuten olen rikkonut ja tehnyt jotakin, mikä ansaitsee kuoleman, en pyri pääsemään kuolemasta. Mutta jos ei ole tapahtunut mitään siitä, mistä nämä minua syyttävät, kukaan ei voi luovuttaa minua heille. Vetoan keisariin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Silloin Festus, neuvoteltuaan neuvoskuntansa kanssa, vastasi: \"Keisariin olet vedonnut, mene keisarin eteen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Muutamien päivien kuluttua kuningas Agrippa ja Bernike saapuivat Kesareaan tervehtimään Festusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Kun he viipyivät siellä useampia päiviä, Festus kertoi Paavalin asian kuninkaalle ja sanoi: \"Täällä on eräs mies, jonka Feeliks on jättänyt vankeuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'Käydessäni Jerusalemissa juutalaisten ylipapit ja vanhimmat ilmoittivat syyttävänsä häntä ja pyysivät, että hänet tuomittaisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Mutta vastasin heille: \'Roomalaisten tapa ei ole antaa ketään alttiiksi, ennen kuin syytetty on asetettu vastakkain syyttäjiensä kanssa ja on saanut puolustautua syytöstä vastaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Kun he olivat kokoontuneet tänne, istuin viivyttelemättä seuraavana päivänä tuomarinistuimelle ja käskin tuoda miehen eteeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Mutta kun hänen syyttäjänsä seisoivat hänen ympärillään, he eivät syyttäneet häntä mistään sellaisesta rikoksesta, kuin minä olin odottanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'vaan heillä oli häntä vastaan riitaa joistakin heidän uskonasioistaan ja jostakin Jeesuksesta, joka oli kuollut, mutta jonka Paavali väitti elävän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Kun olin epätietoinen, miten tällainen asia oli tutkittava, kysyin, tahtoiko hän mennä Jerusalemiin ja siellä vastata näihin syytöksiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Mutta kun Paavali vetosi ja vaati, että hänet oli säilytettävä majesteetin tutkittavaksi, käskin vartioida häntä, kunnes lähetän hänet keisarin eteen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Agrippa sanoi Festukselle: \"Tahtoisin itsekin kuulla sitä miestä.\" Tämä sanoi: \"Huomenna saat häntä kuulla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Seuraavana päivänä Agrippa ja Bernike saapuivat suurella loistolla ja menivät oikeussaliin tuhannenpäälliköiden ja kaupungin ylhäisten miesten kanssa, ja Paavali tuotiin Festuksen käskystä sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Festus sanoi: \"Kuningas Agrippa ja kaikki muut, jotka meidän kanssamme olette läsnä, tässä näette sen miehen, jonka tähden koko juutalaisten joukko sekä Jerusalemissa että täällä on ahdistanut minua huutaen, ettei hänen pidä enää saada elää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Minä kuitenkin huomasin, ettei hän ole tehnyt mitään, mikä ansaitsisi kuoleman. Mutta kun hän itse vetosi majesteettiin, päätin lähettää hänet sinne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Mitään varmaa minulla ei kuitenkaan ole, mitä hänestä herralleni kirjoittaisin. Sen vuoksi tuotin hänet teidän eteenne ja varsinkin sinun eteesi, kuningas Agrippa, että minulla tutkinnan tapahduttua olisi, mitä kirjoittaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Sillä mielettömältä näyttää minusta lähettää vanki, antamatta tietää häntä vastaan tehtyjä syytöksiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Agrippa sanoi Paavalille: \"Sinun on lupa puhua puolestasi.\" Silloin Paavali ojensi kätensä ja lausui puolustuksekseen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, '\"Pidän itseäni onnellisena, kuningas Agrippa, kun sinun edessäsi saan tänä päivänä puolustautua kaikesta siitä, mistä juutalaiset minua syyttävät,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'varsinkin, koska sinä tarkkaan tunnet kaikki juutalaisten tavat ja riitakysymykset. Sen tähden pyydän sinua kärsivällisesti kuulemaan minua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Kaikki juutalaiset tuntevat elämäni nuoruudestani asti, koska alusta alkaen olen elänyt kansani keskuudessa ja Jerusalemissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'He tuntevat minut jo entuudestaan, jos tahtovat sen todistaa, että meidän uskontomme ankarimman lahkon mukaan olen elänyt fariseuksena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Nyt seison oikeuden edessä sen tähden, että panen toivoni siihen lupaukseen, jonka Jumala on isillemme antanut');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'ja jonka meidän kaksitoista sukukuntaamme, yötä päivää hartaasti palvellen Jumalaa, toivovat heille toteutuvan. Tämän toivon tähden, kuningas, juutalaiset minua syyttävät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Miksi teistä on uskomatonta, että Jumala herättää kuolleet?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Luulin minäkin, että minun tuli paljon taistella Jeesuksen, Nasaretilaisen, nimeä vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'ja niin teinkin Jerusalemissa. Paljon pyhiä minä suljin vankiloihin saatuani ylipapeilta siihen valtuuden, ja kun heitä tapettiin, annoin ääneni sen puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'Kaikkialla synagogissa usein koetin rankaisemalla pakottaa heitä pilkkaamaan, ja menin niin pitkälle raivossani heitä vastaan, että vainosin heitä aina ulkomaan kaupunkeihin saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'Kun näissä asioissa matkustin Damaskoon ylipappien valtuudella ja suostumuksella,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'kuningas, näin tiellä keskellä päivää taivaasta tulevan valon, auringon paistetta kirkkaamman, loistavan minun ja matkatoverieni ympärillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'Me kaaduimme kaikki maahan, ja kuulin äänen sanovan minulle heprean kielellä: \'Saul, Saul, miksi vainoat minua? Työlästä sinun on potkia tutkainta vastaan.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Minä sanoin: \'Kuka olet, herra?\' Herra sanoi: \'Minä olen Jeesus, jota sinä vainoat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Mutta nouse ja seiso jaloillasi, sillä sitä varten olen sinulle ilmestynyt, että asettaisin sinut palvelijakseni ja sen todistajaksi, mitä olet nähnyt, niin myös sen, minkä sinulle ilmoitan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Pelastan sinut sekä oman kansasi että pakanoiden käsistä, joiden luo sinut nyt lähetän');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'avaamaan heidän silmänsä, että he kääntyisivät pimeydestä valkeuteen ja saatanan vallasta Jumalan luo ja ottaisivat vastaan syntien anteeksiantamuksen ja perintöosan pyhitettyjen joukossa uskossa minuun.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Sen tähden, kuningas Agrippa, en voinut olla tottelematta taivaallista näkyä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'vaan saarnasin ensin sekä Damaskon että Jerusalemin asukkaille, sitten koko Juudean maalle ja pakanoille mielenmuutosta ja kääntymystä Jumalan puoleen, ja että he tekisivät mielenmuutoksen soveliaita tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Tämän tähden juutalaiset ottivat minut kiinni temppelissä ja yrittivät väkivalloin minut surmata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Mutta Jumalan avulla, jota olen saanut tähän päivään asti, seison todistamassa sekä pienille että suurille, enkä puhu mitään muuta, kuin minkä profeetat ja Mooses ovat sanoneet tulevan tapahtumaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'että nimittäin Kristuksen piti kärsiä ja kuolleitten ylösnousemuksen esikoisena julistaa valoa sekä tälle kansalle että pakanoille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Mutta kun hän näin puolustautui, Festus sanoi suurella äänellä: \"Olet hullu, Paavali, suuri oppineisuutesi tekee sinut hulluksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Mutta hän sanoi: \"En ole hullu, korkea-arvoinen Festus, vaan puhun totuuden ja terveellisen opin sanoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Kuningas kyllä nämä tietää, jonka tähden puhunkin hänelle rohkeasti. Sillä en usko minkään näistä asioista olevan häneltä salassa. Eiväthän nämä ole missään nurkassa tapahtuneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Uskotko, kuningas Agrippa, profeettoja? Tiedän, että uskot.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Niin Agrippa sanoi Paavalille: \"Oletpa vähällä vakuuttaa minut kristityksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Mutta Paavali sanoi: \"Rukoilen Jumalaa, että, olipa vähällä tai paljolla, et ainoastaan sinä, vaan myös kaikki te, jotka minua tänään kuulette, tulisitte sellaisiksi, kuin minäkin olen, näitä kahleita lukuun ottamatta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'Kuningas nousi, samoin maaherra ja Bernike sekä ne, jotka istuivat heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'Mennessään he puhuivat keskenään sanoen: \"Tämä mies ei ole tehnyt mitään, mikä ansaitsisi kuoleman tai kahleet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Agrippa sanoi Festukselle: \"Tämän miehen olisi voinut päästää irti, jos hän ei olisi vedonnut keisariin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Kun oli päätetty, että meidän oli purjehdittava Italiaan, luovutettiin Paavali ja muutamia muita vankeja erään Julius-nimisen, keisarilliseen sotilasosastoon kuuluvan sadanpäällikön haltuun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Astuimme adramyttionilaiseen laivaan, jonka oli määrä purjehtia Aasian maakunnan rannikkopaikkoihin, ja lähdimme merelle, ja seurassamme oli makedonialainen Aristarkus Tessalonikasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Seuraavana päivänä laskimme Siidoniin. Julius kohteli Paavalia ystävällisesti ja salli hänen mennä ystäviensä luo saamaan hoitoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Sieltä laskeuduttuamme merelle purjehdimme Kyproksen suojaan, koska tuulet olivat vastaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'Kun olimme sivuuttaneet avomerta purjehtien Kilikian ja Pamfylian, tulimme maihin Lykian Myrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Sieltä sadanpäällikkö löysi aleksandrialaisen Italiaan menevän laivan ja siirsi meidät siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Monta päivää purjehdimme hitaasti ja pääsimme vaivoin Knidon kohdalle. Mutta kun tuulelta emme päässeet sinne, purjehdimme Salmonen editse Kreetan suojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'Kuljettuamme vaivalloisesti lähellä sen rantaa saavuimme erääseen paikkaan, jonka nimi oli Kauniit Satamat ja jota lähellä oli Lasaian kaupunki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Mutta koska oli kulunut paljon aikaa ja purjehtiminen oli jo vaarallista, sillä paastokin oli jo ohi, Paavali varoitti heitä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'ja sanoi: \"Miehet, näen, että purjehtimisesta tulee aiheutumaan vahinkoa ja suurta tuhoa, ei ainoastaan lastille ja laivalle, vaan myös hengellemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Mutta sadanpäällikkö uskoi enemmän perämiestä ja laivan omistajaa kuin Paavalin sanoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'Koska satama oli sopimaton talvehtimiseen, useimmat olivat sitä mieltä, että heidän oli sieltä lähdettävä voidakseen päästä talvehtimaan Foiniksiin, erääseen Kreetan satamaan, joka antaa lounaaseen ja luoteeseen päin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Kun etelätuuli alkoi puhaltaa, he luulivat pääsevänsä perille, nostivat ankkurin ja kulkivat aivan Kreetan läheltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Mutta ennen pitkää syöksyi saaren yli raju tuuli, niin sanottu koillismyrsky.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Kun laiva ryöstäytyi sen mukaan eikä voinut nousta tuuleen, jätimme sen valtoihinsa ja jouduimme tuuliajolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Päästyämme erään pienen, Klauda-nimisen saaren suojaan töin tuskin saimme laivaveneen talteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Vedettyään sen ylös he ryhtyivät varokeinoihin ja sitoivat veneen köysillä kiinni, ja kun he pelkäsivät ajautuvansa Syrtteihin, he laskivat ajoankkurin, ja niin he ajelehtivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Mutta kun rajuilma ahdisti meitä ankarasti, he heittivät seuraavana päivänä lastin mereen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'ja kolmantena päivänä omin käsin viskasimme mereen laivan varusteet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Mutta kun ei näkynyt aurinkoa eikä tähtiä moneen päivään ja kova myrsky painoi päälle, meiltä katosi viimein kaikki pelastumisen toivo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Kun oli oltu kauan syömättä, Paavali nousi heidän keskellään ja sanoi: \"Miehet, teidän olisi pitänyt totella minua ja olla lähtemättä Kreetalta. Siten olisitte säästyneet tästä vaivasta ja vahingosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Mutta nyt kehotan teitä olemaan rohkealla mielellä, sillä yksikään teistä ei huku, ainoastaan laiva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Sillä tänä yönä seisoi luonani Jumalan Enkeli, jonka oma olen ja jota myös palvelen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'ja sanoi: \'Älä pelkää, Paavali, keisarin edessä sinun pitää seistä. Katso, Jumala on lahjoittanut sinulle kaikki, jotka purjehtivat kanssasi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Olkaa sen tähden rohkealla mielellä, miehet, sillä minulla on se usko Jumalaan, että niin käy, kuin minulle on puhuttu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Mutta jollekin saarelle meidän täytyy ajautua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Kun tuli neljästoista yö ajelehtiessamme Adrianmerellä, merimiehistä tuntui keskiyön aikaan, että lähestyttiin jotakin maata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Luodattuaan he huomasivat syvyyden olevan kaksikymmentä syltä, ja vähän matkaa kuljettuaan he taas luotasivat ja huomasivat syvyyden viideksitoista syleksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'He pelkäsivät meidän ajautuvan karille, laskivat laivan perästä neljä ankkuria ja toivoivat päivän tulevan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Mutta merimiehet yrittivät paeta laivasta ja laskivat veneen mereen sillä tekosyyllä, että muka aikoivat keulapuolesta laskea ankkureita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Silloin Paavali sanoi sadanpäällikölle ja sotilaille: \"Jos nuo eivät pysy laivassa, te ette voi pelastua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Silloin sotamiehet hakkasivat poikki veneen köydet ja antoivat sen pudota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Ennen päivän tuloa Paavali kehotti kaikkia nauttimaan ruokaa, sanoen: \"Tänään olette jo neljättätoista päivää odottaneet ja olleet syömättä ettekä ole ottaneet mitään ruokaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Sen tähden kehotan teitä nauttimaan ruokaa, sillä se on tarpeen pelastuaksenne, sillä yhdeltäkään teistä ei hiuskarvakaan katoa päästä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'Tämän sanottuaan hän otti leivän ja kiitti Jumalaa kaikkien nähden, mursi ja alkoi syödä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Silloin kaikki tulivat rohkealle mielelle, ja he ottivat ruokaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Meitä oli laivassa kaikkiaan kaksisataa seitsemänkymmentä kuusi henkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Kun he olivat tulleet ravituiksi, he kevensivät laivaa heittämällä vehnän mereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Päivän tultua he eivät tunteneet maata, mutta huomasivat lahden, jossa oli sopiva ranta. Siihen he päättivät, jos mahdollista, laskea laivan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'Nostettuaan ankkurit he antoivat niiden painua. Samalla he päästivät peräsinten köydet, nostivat keulapurjeen tuuleen ja ohjasivat rantaa kohti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Mutta he joutuivat karille ja laiva törmäsi siihen. Keula tarttui kiinni ja jäi liikkumattomaksi, mutta laivan perä hajosi aaltojen voimasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Mutta sotilailla oli aikomus tappaa vangit, ettei kukaan karkaisi uimalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Mutta sadanpäällikkö, joka tahtoi pelastaa Paavalin, esti heitä ja käski uimataitoisten ensiksi heittäytyä veteen ja lähteä maihin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'ja sitten muiden, kenen laudoilla, kenen laivankappaleilla. Näin tapahtui, ja kaikki pelastuivat maihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Kun olimme pelastuneet, saimme tietää, että saaren nimi oli Melite.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Barbaarit osoittivat meille suurta ystävällisyyttä, sytyttivät nuotion ja ottivat meidät kaikki sen ääreen, kun oli alkanut sataa ja oli kylmä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Mutta Paavali kokosi kasan risuja, ja kun hän pani ne nuotioon, tuli kyy kuumuuden tähden esiin ja kävi kiinni hänen käteensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Kun asukkaat näkivät elukan riippuvan kiinni hänen kädessään, he sanoivat toisilleen: \"Varmaan tuo mies on murhaaja, koska kostotar ei sallinut hänen elää, vaikka hän pelastuikin merestä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Mutta hän pudisti elukan tuleen, eikä hänelle tapahtunut mitään pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'He odottivat hänen [kätensä] tulehtuvan tai hänen kaatuvan äkkiä kuolleena maahan. Mutta kun he olivat kauan odottaneet ja näkivät, ettei hänelle tapahtunut mitään pahaa, he muuttivat mielensä ja sanoivat hänen olevan jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'Lähellä sitä paikkaa oli saaren ensimmäisellä miehellä, jonka nimi oli Publius, maatiloja. Hän otti meidät vastaan ja piti meitä ystävällisesti kolme päivää vierainaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Mutta tapahtui, että Publiuksen isä makasi sairaana kuumeessa ja punataudissa, ja Paavali meni hänen luokseen, rukoili ja pani kätensä hänen päälleen ja paransi hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Kun tämä siis oli tapahtunut, muutkin saarella olevat sairaat tulivat, ja heidät parannettiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'He osoittivat meille myös monin tavoin kunniaa, ja lähtiessämme merelle he panivat mukaan, mitä tarvitsimme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Kolmen kuukauden kuluttua purjehdimme sieltä aleksandrialaisessa laivassa, joka oli talvehtinut saarella ja jolla oli merkkinä Dioskurien kuva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Rantauduimme Syrakuusaan ja viivyimme siellä kolme päivää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'ja sieltä kierrettyämme saavuimme Regioniin, ja kun yhden päivän perästä nousi etelätuuli, tulimme seuraavana päivänä Puteoliin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Siellä tapasimme veljiä, jotka pyysivät meitä viipymään luonaan seitsemän päivää. Niin lähdimme Roomaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Kun veljet siellä saivat kuulla meistä, he tulivat meitä vastaan Forum Appiumiin ja Tres Tabernaen kohdalle saakka. Heidät nähdessään Paavali kiitti Jumalaa ja sai rohkeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Kun tulimme Roomaan, sadanpäällikkö luovutti vangit henkivartioston päällikölle. Mutta Paavalin sallittiin asua erikseen häntä vartioivan sotilaan kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Kolmen päivän kuluttua Paavali kutsui kokoon juutalaisten ensimmäiset. Kun he olivat kokoontuneet, hän sanoi heille: \"Miehet, veljet! Vaikka en ole tehnyt mitään kansaamme tai isiemme tapoja vastaan, minut annettiin Jerusalemista vankina roomalaisten käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Kun he olivat minua tutkineet, he tahtoivat vapauttaa minut, koska minussa ei ollut mitään kuoleman aihetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Mutta kun juutalaiset sitä vastustivat, minun oli pakko vedota keisariin – ei kuitenkaan niin, että minulla olisi mitään kannetta kansaani vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Tästä syystä olen nyt kutsunut teidät saadakseni nähdä ja puhutella teitä, sillä Israelin toivon tähden kannan tätä kahletta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'He sanoivat hänelle: \"Emme ole saaneet kirjeitä sinusta Juudean maalta, eikä kukaan tänne saapunut veli ole ilmoittanut eikä puhunut sinusta pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Katsomme kuitenkin olevan syytä kuulla sinulta, mitä ajattelet. Sillä tästä lahkosta on meillä tiedossamme, että sitä vastaan kaikkialla puhutaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'He määräsivät hänelle päivän, ja silloin tuli heitä vielä useampia hänen luokseen majapaikkaan. Näille hän aamuvarhaisesta iltaan saakka selitti ja todisti Jumalan valtakunnasta, lähtien Mooseksen Laista ja Profeetoista, vakuuttaakseen heidät Jeesuksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Se, mitä sanottiin, vakuutti toiset, mutta toiset eivät uskoneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Kun he olivat keskenään erimielisiä, he erosivat toisistaan. Paavali sanoi ainoastaan yhden sanan: \"Oikein on Pyhä Henki puhunut profeetta Jesajan kautta teidän isillenne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'sanoessaan: \'Mene tämän kansan luo ja sano: Kuulemalla kuulkaa älkääkä ymmärtäkö, katselemalla katselkaa, älkääkä nähkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Sillä paatunut on tämän kansan sydän, ja korvillaan he työläästi kuulevat, ja silmänsä he ovat ummistaneet, etteivät näkisi silmillään, eivät kuulisi korvillaan, eivät ymmärtäisi sydämellään eivätkä kääntyisi ja etten heitä parantaisi.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Olkoon siis teille tiettävä, että Jumalan pelastus on lähetetty pakanoille, ja he kuulevat sen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'Kun hän oli tämän sanonut, juutalaiset lähtivät pois kiistellen paljon keskenään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Paavali asui omassa vuokra-asunnossaan kaksi täyttä vuotta ja otti vastaan kaikki, jotka hänen luokseen tulivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'Hän julisti Jumalan valtakuntaa ja opetti Herraa Jeesusta Kristusta kaikella rohkeudella kenenkään estämättä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paavali, Jeesuksen Kristuksen palvelija, kutsuttu apostoli, erotettu Jumalan evankeliumia varten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'jonka Jumala on edeltä luvannut Profeettojensa kautta Pyhissä Kirjoituksissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'hänen Pojastaan – joka lihan puolesta on syntynyt Daavidin siemenestä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'ja pyhyyden hengen puolesta kuolleistanousemisen kautta asetettu Jumalan Pojaksi voimassa – Jeesuksesta Kristuksesta, meidän Herrastamme,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'jonka kautta olemme saaneet armon ja apostolinviran, jotta syntyisi uskon kuuliaisuus hänen nimeään kohtaan kaikissa pakanakansoissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'joihin tekin, Jeesuksen Kristuksen kutsumat, kuulutte:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'kaikille Roomassa oleville Jumalan rakkaille, kutsutuille pyhille. Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Ensiksikin kiitän Jumalaani Jeesuksen Kristuksen kautta teidän kaikkien tähden, koska teidän uskoanne julistetaan kaikessa maailmassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Sillä Jumala, jota hengessäni palvelen hänen Poikansa evankeliumilla, on todistajani, kuinka teitä lakkaamatta muistan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'aina rukouksissani anoen, että jo vihdoinkin, jos Jumala tahtoo, pääsisin tulemaan luoksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Sillä ikävöin nähdä teitä voidakseni antaa teille jonkin hengellisen lahjan, että tulisitte lujiksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'se on, että minäkin saisin lohdutusta teidän keskuudessanne yhteisen uskomme kautta, teidän ja minun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Veljet, en tahdo teiltä salata, että jo monta kertaa olen päättänyt tulla luoksenne saadakseni jonkin hedelmän teidänkin keskuudestanne, niin kuin muidenkin pakanoiden, mutta olen ollut estetty tähän asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Kreikkalaisille ja barbaareille, viisaille ja tyhmille olen velassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Omasta puolestani siis olen halukas julistamaan evankeliumin teillekin, Roomassa asuville.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Sillä en häpeä Kristuksen evankeliumia, sillä se on Jumalan voima, jokaiselle uskovalle pelastukseksi, juutalaiselle ensin, sitten myös kreikkalaiselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Sillä Jumalan vanhurskaus ilmoitetaan siinä uskosta tulevana uskoa varten, niin kuin on kirjoitettu: \"Vanhurskas on elävä uskosta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Sillä Jumalan viha on ilmestyvä taivaasta kaikkea ihmisten jumalattomuutta ja vääryyttä vastaan, niiden, jotka pitävät totuutta vääryyden vallassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'sen tähden että se, mikä Jumalasta voidaan tietää, on heillä tiedossa, sillä Jumala on sen heille ilmoittanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Sillä hänen näkymätön olemuksensa, hänen iankaikkinen voimansa ja jumalallisuutensa, ovat, kun niitä hänen teoissaan katsellaan, maailman luomisesta nähtävinä, niin etteivät he voi millään itseään puolustaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'koska he, vaikka ovat tunteneet Jumalan, eivät ole häntä Jumalana kunnioittaneet eivätkä kiittäneet, vaan ovat tulleet ajatuksiltaan turhanpäiväisiksi, ja heidän ymmärtämätön sydämensä on pimentynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Väittäessään viisaita olevansa he ovat tulleet tyhmiksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'ja ovat vaihtaneet katoamattoman Jumalan kirkkauden katoavan ihmisen, lintujen, nelijalkaisten ja matelijoiden kuvan kaltaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Sen tähden Jumala on heidät heidän sydämensä himoissa hylännyt saastaisuuteen häpäisemään itse omat ruumiinsa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'nuo, jotka ovat vaihtaneet Jumalan totuuden valheeseen ja kunnioittaneet ja palvelleet luotua enemmän kuin Luojaa, joka on ylistetty iankaikkisesti, aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Sen tähden Jumala on hylännyt heidät häpeällisiin himoihin. Sillä heidän naisensa ovat vaihtaneet luonnollisen yhteyden luonnonvastaiseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'Samoin miehetkin luopuen luonnollisesta yhteydestä naisten kanssa ovat kiimoissaan syttyneet toisiinsa ja harjoittaneet miehet miesten kanssa kauheaa siveettömyyttä ja saaneet eksymyksestään itseensä sen palkan, mikä saada piti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'Koska heille ei kelvannut pitää kiinni Jumalan tuntemisesta, Jumala hylkäsi heidät heidän kelvottomaan mieleensä tekemään sopimattomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'He ovat täynnä kaikkea vääryyttä, haureutta, pahuutta, ahneutta, häijyyttä, täynnä kateutta, murhaa, riitaa, petosta, ilkeyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'He ovat korvaan kuiskuttelijoita, panettelijoita, Jumalaa vihaavia, väkivaltaisia, ylvästelijöitä, kerskureita, kekseliäitä pahassa, vanhemmilleen tottelemattomia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'ymmärtämättömiä, epäluotettavia, riitaisia, rakkaudettomia ja armottomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'He tuntevat Jumalan vanhurskaan säädöksen, että ne, jotka sellaista harjoittavat, ovat kuoleman ansainneet. Silti he eivät ainoastaan itse niitä tee, vaan antavat myös hyväksymisensä niille, jotka sellaista harjoittavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Sen tähden, ihminen, et voi millään itseäsi puolustaa, olitpa kuka hyvänsä, joka tuomitset. Sillä mistä toista tuomitset, siihen sinä tuomitset itsesi syylliseksi, koska sinä, joka tuomitset, teet samoja tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Tiedämme, että Jumalan tuomio on totuuden mukainen niille, jotka sellaista tekevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Vai luuletko, ihminen, sinä, joka tuomitset niitä, jotka sellaista tekevät, ja itse teet samoja tekoja, että sinä pääset Jumalan tuomiota pakoon?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Vai halveksitko hänen hyvyytensä, kärsivällisyytensä ja pitkämielisyytensä runsautta, etkä tiedä, että Jumalan hyvyys ajaa sinua mielenmuutokseen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Kovuudellasi ja katumattomalla sydämelläsi sinä kokoat päällesi vihaa vihan ja Jumalan vanhurskaan tuomion ilmestymisen päiväksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'hänen, \"joka maksaa kullekin hänen tekojensa mukaan\":');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'iankaikkisen elämän niille, jotka hyvässä työssä kestävinä etsivät kirkkautta, kunniaa ja katoamattomuutta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'mutta kiivaus ja viha tulevat niiden osaksi, jotka ovat riidanhaluisia eivätkä tottele totuutta, vaan tottelevat vääryyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Tuska ja ahdistus jokaisen ihmisen sielulle, joka tekee pahaa, juutalaiselle ensin, sitten myös kreikkalaiselle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'mutta kirkkaus, kunnia ja rauha jokaiselle, joka tekee sitä, mikä on hyvää, juutalaiselle ensin, sitten myös kreikkalaiselle!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Sillä Jumalan edessä ei ole puolueellisuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Sillä kaikki ne, jotka ilman lakia ovat syntiä tehneet, myös ilman lakia joutuvat kadotukseen, ja kaikki ne, jotka lain piirissä ollen ovat syntiä tehneet, lain mukaan tuomitaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'Eivät näet lain kuulijat ole vanhurskaita Jumalan edessä, vaan lain noudattajat vanhurskautetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Sillä kun pakanat, joilla ei lakia ole, luonnostaan tekevät, mitä laki vaatii, niin he, vaikka heillä ei lakia ole, ovat itse itselleen laki');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'ja osoittavat, että lain teot ovat kirjoitetut heidän sydämiinsä, kun heidän omatuntonsa yhdessä todistaa ja heidän ajatuksensa keskenään syyttävät tai myös puolustavat heitä –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'sinä päivänä, jona Jumala on tuomitseva ihmisten salaisuudet Jeesuksen Kristuksen kautta minun evankeliumini mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Katso, sinä sanot itseäsi juutalaiseksi ja luotat lakiin ja kerskut Jumalassa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'ja tunnet hänen tahtonsa ja laista opetuksen saatuasi tutkit, mikä on parasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'ja luulet kykeneväsi olemaan sokeiden taluttaja, pimeydessä olevien valo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'ymmärtämättömien kasvattaja, alaikäisten opettaja, sinulla kun on laissa tiedon ja totuuden muoto:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'niin sinäkö, joka toista opetat, et itseäsi opeta; joka julistat, ettei saa varastaa, itse varastat;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'joka sanot, ettei saa tehdä huorin, itse teet huorin; joka kauhistut epäjumalia, kuitenkin olet temppelin ryöstäjä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'joka laista kerskaat, häpäiset lainrikkomisella Jumalaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Sillä \"teidän tähtenne Jumalan nimi tulee pilkatuksi pakanoiden keskuudessa\", kuten on kirjoitettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Ympärileikkaus tosin on hyödyllinen, jos noudatat lakia, mutta jos olet lainrikkoja, niin ympärileikkauksesi on tullut ympärileikkaamattomuudeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Jos siis ympärileikkaamaton noudattaa lain säädöksiä, eikö hänen ympärileikkaamattomuutensa ole luettava ympärileikkaukseksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'Ja luonnostaan ympärileikkaamaton, joka täyttää lain, on tuomitseva sinut, joka lainkirjaiminesi ja ympärileikkauksinesi olet lainrikkoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Sillä ei se ole juutalainen, joka vain ulkonaisesti on juutalainen, eikä ympärileikkaus se, joka tapahtuu ulkonaisesti lihassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'vaan se on juutalainen, joka salassa on juutalainen, ja oikea ympärileikkaus on sydämen ympärileikkaus Hengessä, ei kirjaimessa, ja hän saa kiitoksensa, ei ihmisiltä, vaan Jumalalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Mitä etuja siis on juutalaisilla tai mitä hyötyä ympärileikkauksesta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Paljonkin, kaikin tavoin, ennen kaikkea se, että heille on uskottu Jumalan sanat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Mutta kuinka? Jos jotkut ovat olleet epäuskoisia, eihän heidän epäuskonsa ole tekevä Jumalan uskollisuutta tyhjäksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Ei ikinä! Olkoon Jumala totinen, mutta jokainen ihminen valehtelija, niin kuin kirjoitettu on: \"Että sinut julistettaisiin vanhurskaaksi sanoissasi ja että voittaisit, kun kanssasi käydään oikeutta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Mutta jos meidän vääryytemme todistaa Jumalan vanhurskautta, mitä sanomme? Ei kaiketi Jumala ole väärä, kun hän rankaisee vihassaan? Puhun ihmisten tavalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Ei ikinä! Sillä kuinka Jumala silloin on tuomitseva maailman?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Sillä jos Jumalan totuus on minun valheeni kautta tullut runsaammin hänen kirkkaudekseen, miksi sitten minutkin vielä tuomitaan syntisenä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Ja miksi ei ole, niin kuin herjaten syyttävät meidän tekevän ja kuten muutamat väittävät meidän sanovan: \"Tehkäämme pahaa, että siitä tulisi hyvää\"? Niille tuleva tuomio on oikea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Miten siis on? Olemmeko parempia? Emme suinkaan. Olemme edellä osoittaneet, että kaikki, niin hyvin juutalaiset kuin kreikkalaiset, ovat synnin alla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'niin kuin kirjoitettu on: \"Ei ole ketään vanhurskasta, ei ainoatakaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'ei ole ketään ymmärtäväistä, ei ketään, joka etsii Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Kaikki ovat poikenneet pois, kaikki tyynni kelvottomiksi käyneet. Ei ole ketään, joka tekee sitä, mikä hyvää on, ei yhden yhtäkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Heidän kurkkunsa on avoin hauta, kielellään he pettävät, kyyn myrkkyä on heidän huultensa alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Heidän suunsa on täynnä kirousta ja katkeruutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Heidän jalkansa ovat nopeat vuodattamaan verta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Hävitystä ja kurjuutta on heidän teillään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'eivätkä he tunne rauhan tietä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Jumalan pelko ei ole heidän silmiensä edessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Mutta tiedämme, että kaiken, minkä laki sanoo, sen se puhuu niille, jotka ovat lain alla, että jokainen suu tukittaisiin ja koko maailma tulisi syylliseksi Jumalan edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'sen tähden, ettei mitään lihaa julisteta hänen edessään vanhurskaaksi lain teoista, sillä lain kautta tulee synnintunto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Mutta nyt Jumalan vanhurskaus, josta Laki ja Profeetat todistavat, on ilmoitettu ilman lakia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'se Jumalan vanhurskaus, joka uskon kautta Jeesukseen Kristukseen tulee kaikkiin ja kaikille, jotka uskovat, sillä ei ole yhtään erotusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'Sillä kaikki ovat syntiä tehneet ja ovat Jumalan kirkkautta vailla');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'ja saavat lahjaksi vanhurskauden hänen armostaan sen lunastuksen kautta, joka on Kristuksessa Jeesuksessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'jonka Jumala on asettanut armoistuimeksi uskon kautta hänen vereensä osoittaakseen vanhurskautensa, koska hän oli jättänyt rankaisematta ennen tehdyt synnit');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'jumalallisessa kärsivällisyydessään, osoittaakseen vanhurskautensa nykyajassa, sen, että hän itse on vanhurskas ja julistaa vanhurskaaksi sen, jolla on usko Jeesukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Missä siis on kerskaaminen? Se on suljettu pois. Minkä lain kautta? Tekojenko lain? Ei, vaan uskon lain kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Niin päätämme siis, että ihminen julistetaan vanhurskaaksi uskon kautta, ilman lain tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Vai onko Jumala yksistään juutalaisten Jumala? Eikö pakanoidenkin? On pakanoidenkin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'koskapa Jumala on yksi, joka julistaa ympärileikatut vanhurskaiksi uskosta ja ympärileikkaamattomat uskon kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Teemmekö siis lain mitättömäksi uskon kautta? Ei ikinä! Vaan vahvistamme lain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Mitä siis sanomme isämme Aabrahamin saavuttaneen lihan mukaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Sillä jos Aabraham on teoista julistettu vanhurskaaksi, hänellä on kerskaamista, mutta ei Jumalan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Sillä mitä Raamattu sanoo? \"Aabraham uskoi Jumalaa, ja se luettiin hänelle vanhurskaudeksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Mutta työtä tekevälle ei lueta palkkaa armosta, vaan ansiosta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'mutta sille, joka ei tee työtä, vaan uskoo häneen, joka julistaa jumalattoman vanhurskaaksi, luetaan hänen uskonsa vanhurskaudeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Samoin myös Daavid ylistää autuaaksi sitä ihmistä, jolle Jumala lukee vanhurskauden ilman tekoja:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, '\"Autuaita ne, joiden lain rikkomiset ovat anteeksi annetut ja joiden synnit ovat peitetyt!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Autuas se mies, jolle Herra ei lue syntiä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Koskeeko sitten tämä autuaaksi ylistäminen ainoastaan ympärileikattuja vai eikö ympärileikkaamattomiakin? Sanommehan: \"Aabrahamille luettiin usko vanhurskaudeksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Kuinka se sitten siksi luettiin? Hänen ollessaan ympärileikattuna vai ympärileikkaamattomana? Ei ympärileikattuna, vaan ympärileikkaamattomana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'Hän sai ympärileikkauksen merkin sinetiksi sille uskon vanhurskaudelle, joka hänellä oli ympärileikkaamattomana, että hän olisi kaikkien isä, jotka uskovat ympärileikkaamattomina, jotta vanhurskaus luettaisiin heillekin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'ja että hän olisi myös ympärileikattujen isä, niiden, jotka eivät ainoastaan ole ympärileikattuja, vaan myös vaeltavat sen uskon jälkiä, mikä meidän isällämme Aabrahamilla oli ympärileikkaamattomana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Sillä se lupaus, että Aabraham perii maailman, ei tullut hänelle eikä hänen siemenelleen lain kautta, vaan uskonvanhurskauden kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Sillä jos perillisiä ollaan lain nojalla, usko on tyhjäksi tehty ja lupaus on mitätön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Sillä laki saa aikaan vihaa, mutta missä lakia ei ole, siellä ei ole rikkomistakaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Sen tähden se on uskosta, että se olisi armosta ja että lupaus olisi luja kaikelle siemenelle, ei ainoastaan sille, joka on lain piiristä, vaan myös sille, jolla on Aabrahamin usko, hänen, joka on meidän kaikkien isä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '– kuten on kirjoitettu: \"Monen kansan isäksi olen sinut asettanut\" – sen Jumalan edessä, johon hän uskoi ja joka tekee kuolleet eläviksi ja kutsuu olemattomat olemassa olevina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Aabraham uskoi toivon varassa, kun mitään toivoa ei ollut, tulevansa monen kansan isäksi, tämän sanan mukaan: \"Niin on siemenesi oleva\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'eikä hän heikentynyt uskossa, vaikka näki, että hänen ruumiinsa oli kuoleutunut – sillä hän oli jo noin satavuotias – ja että Saaran kohtu oli kuoleutunut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'mutta Jumalan lupausta hän ei epäillyt epäuskossa, vaan vahvistui uskossa antaen kunnian Jumalalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'ja oli täysin varma siitä, että minkä Jumala on luvannut, sen hän voi myös tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Sen tähden se luettiinkin hänelle vanhurskaudeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Mutta ei ainoastaan hänen tähtensä ole kirjoitettu, että se hänelle luettiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'vaan myös meidän tähtemme, joille se on luettava, meille, jotka uskomme häneen, joka kuolleista herätti Jeesuksen, meidän Herramme,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'joka on alttiiksi annettu meidän [lain] rikkomisiemme tähden ja kuolleista herätetty meidän vanhurskauttamisemme tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Koska meidät on siis uskosta vanhurskaiksi julistettu, meillä on rauha Jumalan kanssa meidän Herramme Jeesuksen Kristuksen kautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'jonka kautta myös olemme uskossa saaneet pääsyn tähän armoon, jossa seisomme, ja kerskauksenamme on Jumalan kirkkauden toivo');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'eikä vain se, vaan kerskaamme myös ahdistuksissa, sillä tiedämme, että ahdistus saa aikaan kärsivällisyyttä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'mutta kärsivällisyys harjaantumista, ja harjaantuminen toivoa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'mutta toivo ei saata häpeään, sillä Jumalan rakkaus on vuodatettu sydämiimme Pyhän Hengen kautta, joka on meille annettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Sillä meidän vielä ollessamme heikkoja kuoli Kristus oikeaan aikaan jumalattomien edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Tuskin näet kukaan kuolee jonkun vanhurskaan edestä. Hyvän edestähän joku mahdollisesti uskaltaakin kuolla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Mutta Jumalan rakkaus meitä kohtaan on siinä, että Kristus, kun vielä olimme syntisiä, kuoli meidän edestämme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Paljon ennemmin siis nyt, kun olemme julistetut vanhurskaiksi hänen veressään, pelastumme hänen kauttaan vihasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Sillä jos tulimme sovitetuiksi Jumalan kanssa hänen Poikansa kuoleman kautta, kun vielä olimme vihan alaisia, paljon ennemmin pelastumme hänen elämänsä kautta nyt, kun olemme sovitetut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'emmekä ainoastaan sovitetut, vaan vieläpä Jumala on kerskauksemme Herramme Jeesuksen Kristuksen kautta, jonka kautta nyt olemme sovituksen saaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Sen tähden, niin kuin yhden ihmisen kautta synti tuli maailmaan, ja synnin kautta kuolema, samoin kuolema on tullut kaikkiin ihmisiin, koska kaikki ovat syntiä tehneet –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'sillä jo ennen lakiakin oli synti maailmassa, mutta syntiä ei lueta, missä lakia ei ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Kuitenkin kuolema hallitsi Aadamista Moosekseen asti niitäkin, jotka eivät olleet tehneet syntiä samanlaisella rikkomisella kuin Aadam, joka on sen esikuva, joka oli tuleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Mutta armolahjan laita ei ole samoin kuin rikkomisen, sillä joskin yhden rikkomisen kautta monet ovat kuolleet, niin paljoa ennemmin on Jumalan armo ja lahja yhden ihmisen, Jeesuksen Kristuksen, armon kautta ylenpalttisesti tullut monien osaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Eikä lahjan laita ole, niin kuin on sen, mikä tuli yhden synnintekijän kautta, sillä tuomio tuli yhdestä ihmisestä kadotukseksi, mutta armolahja on tullut monien rikkomisista vanhurskauttamiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Ja jos yhden ihmisen lankeamisen tähden kuolema on hallinnut yhden kautta, niin paljoa ennemmin ne, jotka saavat armon ja vanhurskauden lahjan runsauden, tulevat elämässä hallitsemaan yhden, Jeesuksen Kristuksen, kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Niinpä siis, samoin kuin yhden ihmisen lankeemus on tullut kaikille ihmisille kadotustuomioksi, niin myös yhden ihmisen vanhurskaus on tullut kaikille ihmisille elämän vanhurskauttamiseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'sillä niin kuin yhden ihmisen tottelemattomuuden kautta monet ovat luetut syntisiksi, niin myös yhden kuuliaisuuden kautta monet ovat luetut vanhurskaiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Mutta laki tuli väliin, että rikkominen tulisi suureksi; mutta missä synti on tullut suureksi, siinä armo on tullut ylenpalttiseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'että niin kuin synti on hallinnut kuolemassa, samoin armokin hallitsisi vanhurskauden kautta iankaikkiseksi elämäksi Jeesuksen Kristuksen, meidän Herramme, kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Mitä siis sanomme? Onko meidän pysyttävä synnissä, että armo tulisi suureksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Ei ikinä! Kuinka me, jotka olemme kuolleet pois synnistä, vielä eläisimme siinä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Vai ettekö tiedä, että kaikki, jotka olemme kastetut Kristukseen Jeesukseen, olemme hänen kuolemaansa kastetut?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Olemme siis yhdessä hänen kanssaan haudatut kasteen kautta kuolemaan, että kuten Kristus herätettiin kuolleista Isän kirkkauden kautta, mekin samalla tavalla vaeltaisimme uudessa elämässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Sillä jos olemme hänen kanssaan kasvaneet yhteen yhtäläisessä kuolemassa, samoin olemme myös yhtäläisessä ylösnousemuksessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'koska tiedämme, että vanha ihmisemme on hänen kanssaan ristiinnaulittu, jotta synnin ruumis kukistettaisiin, että me emme enää syntiä palvelisi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'sillä se, joka on kuollut, on vanhurskautunut pois synnistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Mutta jos olemme kuolleet Kristuksen kanssa, uskomme, että tulemme myös elämään hänen kanssaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'tietäen, että Kristus, sitten kun hänet herätettiin kuolleista, ei enää kuole. Kuolemalla ei ole enää valtaa häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Sillä minkä hän kuoli, sen hän kerta kaikkiaan kuoli pois synnistä, mutta minkä hän elää, sen hän elää Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Samalla tavalla tekin pitäkää itsenne synnille kuolleina, mutta Jumalalle elävinä Kristuksessa Jeesuksessa meidän Herrassamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Älköön siis synti hallitko teidän kuolevaisessa ruumiissanne, niin että olette kuuliaisia sen himoille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'älkääkä antako jäseniänne vääryyden aseiksi synnille, vaan antakaa itsenne kuolleista eläviksi tulleina Jumalalle ja jäsenenne vanhurskauden aseiksi Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Sillä synti ei ole teitä vallitseva, koska ette ole lain alla, vaan armon alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Kuinka siis on? Saammeko tehdä syntiä, koska emme ole lain alla, vaan armon alla? Ei ikinä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Ettekö tiedä, että kenen orjiksi, ketä tottelemaan, te antaudutte, sen orjia te olette, jota te tottelette, joko synnin orjia kuolemaksi tai kuuliaisuuden vanhurskaudeksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Mutta kiitos Jumalalle, että te, jotka olitte synnin orjia, nyt olette tulleet sydämestänne kuuliaisiksi sille opin muodolle, jonka johtoon teidät on annettu,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'ja että te synnistä vapautettuina olette tulleet vanhurskauden orjiksi!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Puhun ihmisten tavalla teidän lihanne heikkouden tähden. Sillä niin kuin ennen annoitte jäsenenne saastaisuuden ja laittomuuden orjiksi laittomuuteen, antakaa nyt jäsenenne vanhurskauden orjiksi pyhitykseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Sillä kun olitte synnin orjia, olitte vapaita vanhurskaudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Minkä hedelmän te siitä silloin saitte? Sen, jota nyt häpeätte. Sillä sen loppu on kuolema.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Mutta nyt, kun olette synnistä vapautetut ja Jumalan orjiksi tulleet, teidän hedelmänne on pyhitys, ja sen loppu on iankaikkinen elämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Sillä synnin palkka on kuolema, mutta Jumalan armolahja on iankaikkinen elämä Kristuksessa Jeesuksessa, meidän Herrassamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Vai ettekö tiedä, veljet – puhun lain tunteville – että laki vallitsee ihmistä koko sen ajan, jonka hän elää?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Niinpä laki sitoo naimisissa olevan naisen hänen elossa olevaan mieheensä, mutta jos mies kuolee, vaimo on vapaa tästä miehen laista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Sen tähden hän saa avionrikkojan nimen, jos miehensä eläessä menee toiselle miehelle. Mutta jos mies kuolee, hän on vapaa laista, niin ettei hän ole avionrikkoja, jos menee toiselle miehelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Niin, veljeni, teidätkin on kuoletettu laista Kristuksen ruumiin kautta tullaksenne toisen omiksi, hänen, joka on kuolleista herätetty, jotta kantaisimme hedelmää Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Sillä kun olimme lihan vallassa, niin synnin himot, jotka laki herättää, vaikuttivat jäsenissämme, niin että kannoimme hedelmää kuolemalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'mutta nyt olemme vapaat laista ja kuolleet pois siitä, mikä piti meidät vankeina, niin että palvelemme Jumalaa Hengen uudessa tilassa emmekä kirjaimen vanhassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Mitä siis sanomme? Onko laki syntiä? Ei ikinä! Mutta syntiä en olisi tullut tuntemaan muuten kuin lain kautta. Sillä en olisi tiennyt himosta, ellei laki olisi sanonut: \"Älä himoitse.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Mutta kun synti otti käskystä aiheen, se herätti minussa kaikkia himoja, sillä ilman lakia synti on kuollut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Minä taas elin ennen ilman lakia, mutta kun käsky tuli, synti sitä vastoin virkosi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'mutta minä kuolin. Kävi ilmi, että käsky, jonka oli määrä olla minulle elämäksi, olikin minulle kuolemaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Sillä kun synti otti käskystä aiheen, se petti minut ja kuoletti minut käskyn kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Niin, laki on kuitenkin pyhä ja käsky pyhä, vanhurskas ja hyvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Onko siis hyvä tullut minulle kuolemaksi? Pois se! Vaan synti, jotta se synniksi nähtäisiin, on hyvän kautta tuottanut minulle kuoleman, että synti tulisi ylenmäärin synnilliseksi käskyn kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Sillä tiedämme, että laki on hengellinen, mutta minä olen lihallinen, myyty synnin alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Sillä en tunne omakseni sitä, mitä teen, sillä en toteuta sitä, mitä tahdon, vaan mitä vihaan, sitä teen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Mutta jos teen sitä, mitä en tahdo, niin myönnän, että laki on hyvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Niin nyt sitä en enää tee minä, vaan synti, joka minussa asuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Sillä tiedän, ettei minussa, se on minun lihassani, asu mitään hyvää. Tahtoa minussa on, mutta hyvän toteuttamista en itsestäni löydä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'sillä sitä hyvää, mitä tahdon, en tee, vaan sitä pahaa, mitä en tahdo, teen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Jos minä siis teen sitä, mitä en tahdo, niin sen tekijä en enää ole minä, vaan synti, joka minussa asuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Huomaan siis itsessäni, minä, joka tahdon hyvää tehdä, sen lain, että paha on minussa läsnä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'sillä sisäisen ihmiseni puolesta iloitsen Jumalan laista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'mutta jäsenissäni näen toisen lain, joka sotii mieleni lakia vastaan ja pitää minut vangittuna synnin laissa, joka on jäsenissäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Minä kurja ihminen, kuka pelastaa minut tästä kuoleman ruumiista?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Kiitos Jumalalle Jeesuksen Kristuksen, meidän Herramme, kautta! Minä siis tällaisena palvelen mielellä Jumalan lakia, mutta lihalla synnin lakia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Nyt ei siis ole mitään kadotustuomiota niille, jotka Kristuksessa Jeesuksessa ovat, niille, jotka eivät vaella lihan mukaan, vaan Hengen mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Sillä elämän hengen laki Kristuksessa Jeesuksessa on vapauttanut minut synnin ja kuoleman laista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Sillä mihin laki oli voimaton, koska se oli lihan kautta tullut heikoksi, sen Jumala teki lähettämällä oman Poikansa syntisen lihan kaltaisuudessa ja synnin tähden ja tuomitsi synnin lihassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'että lain vanhurskaus täytettäisiin meissä, jotka emme vaella lihan mukaan, vaan Hengen mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Sillä niillä, jotka elävät lihan mukaan, on lihan mieli, mutta niillä, jotka elävät Hengen mukaan, on Hengen mieli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Sillä lihan mieli on kuolema, mutta Hengen mieli on elämä ja rauha,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'sen tähden että lihan mieli on vihollisuus Jumalaa vastaan, sillä se ei alistu Jumalan lain alle, eikä se voikaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Ne, jotka ovat lihan vallassa, eivät voi olla Jumalalle otollisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Mutta te ette ole lihan vallassa, vaan Hengen, jos kerran Jumalan Henki asuu teissä. Mutta se, jolla ei ole Kristuksen Henkeä, ei ole hänen omansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Mutta jos Kristus on teissä, niin ruumis tosin on kuollut synnin tähden, mutta henki on elämä vanhurskauden tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Jos nyt hänen Henkensä, hänen, joka herätti Jeesuksen kuolleista, asuu teissä, niin hän, joka herätti kuolleista Kristuksen Jeesuksen, on tekevä eläviksi myös teidän kuolevaiset ruumiinne Henkensä kautta, joka teissä asuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Niin siis, veljet, olemme nyt velassa, mutta emme lihalle lihan mukaan elääksemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'Sillä jos lihan mukaan elätte, on teidän kuoltava, mutta jos Hengellä kuoletatte ruumiin teot, on teillä oleva elämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Sillä kaikki, joita Jumalan Henki kuljettaa, ovat Jumalan lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Sillä ette ole ottaneet vastaan orjuuden henkeä ollaksenne jälleen pelossa, vaan te olette ottaneet vastaan lapseuden Hengen, jossa huudamme: \"Abba! Isä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Henki itse todistaa henkemme kanssa, että olemme Jumalan lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Mutta jos olemme lapsia, olemme myös perillisiä, Jumalan perillisiä ja Kristuksen kanssaperillisiä, jos kerran yhdessä hänen kanssaan kärsimme, että yhdessä myös kirkastuisimme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Sillä päätän, että tämän nykyisen ajan kärsimykset eivät ole verrattavissa tulevaan kirkkauteen, joka on ilmestyvä meihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Sillä luomakunnan harras ikävöiminen odottaa Jumalan lasten ilmestymistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Sillä luomakunta on alistettu turhuuden alle – ei omasta tahdostaan, vaan alistajan – toivon varaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'koska itse luomakuntakin on tuleva vapautetuksi turmeluksen orjuudesta Jumalan lasten kirkkauden vapauteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Sillä tiedämme, että koko luomakunta yhdessä huokaa ja on synnytystuskissa tähän asti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'eikä ainoastaan se, vaan myös me, joilla on Hengen esikoislahja, mekin huokaamme sisimmässämme odottaen lapseksi ottamista, ruumiimme lunastusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Sillä toivossa olemme pelastetut, mutta toivo, jonka näkee täyttyneen, ei ole mikään toivo. Kuinka kukaan toivoo sitä, minkä näkee?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Mutta jos toivomme, mitä emme näe, odotamme sitä kärsivällisyydellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Samoin myös Henki auttaa heikkouksissamme. Sillä emme tiedä, mitä rukoilisimme, kuten pitää, mutta Henki itse rukoilee puolestamme sanomattomin huokauksin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'Mutta sydänten tutkija tietää, mikä Hengen mieli on, sillä Henki rukoilee Jumalan tahdon mukaan pyhien edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Mutta tiedämme, että kaikki yhdessä vaikuttaa niiden parhaaksi, jotka Jumalaa rakastavat, niiden, jotka hänen päätöksensä mukaan ovat kutsutut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Sillä ne, jotka hän on ennalta omikseen tuntenut, hän on myös ennalta määrännyt Poikansa kuvan kaltaisiksi, että hän olisi esikoinen monien veljien joukossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'Mutta ne, jotka hän on ennalta määrännyt, hän on myös kutsunut. Ne, jotka hän on kutsunut, hän on myös julistanut vanhurskaiksi, mutta ne, jotka hän on julistanut vanhurskaiksi, hän on myös kirkastanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Mitä siis tähän sanomme? Jos Jumala on puolellamme, kuka on meitä vastaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Hän, joka ei säästänyt omaa Poikaansakaan, vaan antoi hänet alttiiksi kaikkien meidän edestä, kuinka hän ei lahjoittaisi meille kaikkea muutakin hänen kanssaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Kuka on syyttävä Jumalan valittuja? Jumala on se, joka julistaa vanhurskaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Kuka tuomitsee kadotukseen? Kristus Jeesus on se, joka on kuollut, onpa vielä herätettykin, ja hän on Jumalan oikealla puolella, ja hän myös rukoilee meidän edestämme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Mikä erottaa meidät Kristuksen rakkaudesta? Tuska vai ahdistus, vai vaino, vai nälkä, vai alastomuus, vai vaara, vai miekka?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Niin kuin kirjoitettu on: \"Sinun tähtesi meitä surmataan kaiken päivää, meitä pidetään teuraslampaina.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Mutta näissä kaikissa saamme jalon voiton hänen kauttaan, joka on meitä rakastanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Sillä olen varma siitä, ettei kuolema eikä elämä, eivät enkelit eivätkä henkivallat, eivät nykyiset eivätkä tulevaiset, eivät voimat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'ei korkeus eikä syvyys, eikä mikään muu luotu erota meitä Jumalan rakkaudesta, joka on Kristuksessa Jeesuksessa, meidän Herrassamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Sanon totuuden Kristuksessa, en valehtele – sen todistaa minulle omatuntoni Pyhässä Hengessä –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'että minulla on suuri murhe ja jatkuva kipu sydämessäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Sillä minä soisin itse olevani kirottu pois Kristuksesta veljieni hyväksi, jotka ovat sukulaisiani lihan puolesta ja');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'ovat israelilaisia. Heidän on lapseus, kirkkaus, liitot, lain antaminen, jumalanpalvelus ja lupaukset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'Heidän ovat isät, ja heistä on Kristus lihan puolesta, hän, joka on yli kaiken, Jumala, ylistetty iankaikkisesti, aamen!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Mutta ei niin, että Jumalan sana olisi harhaan mennyt. Sillä eivät kaikki ne, jotka ovat Israelista, ole Israel,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'eivät kaikki ole lapsia sen tähden, että ovat Aabrahamin siementä, vaan: \"Iisakista kutsutaan sinulle siemen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'Se on: eivät ne, jotka lihan puolesta ovat lapsia, ole Jumalan lapsia, vaan lupauksen lapset, ne luetaan siemeneksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Sillä lupauksen sana oli tämä: \"Minä palaan tähän aikaan, ja silloin Saaralla on poika.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Eikä ainoastaan näin ollut hänellä, vaan samoin Rebekallakin, joka oli tullut raskaaksi yhdestä, meidän isästämme Iisakista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'Ennen kuin kaksoset olivat syntyneetkään ja ennen kuin olivat tehneet mitään, hyvää tai pahaa, niin – että Jumalan valinnan mukainen edeltävä päätös pysyisi, ei tekojen tähden, vaan kutsujan tähden –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'sanottiin hänelle: \"Vanhempi on palveleva nuorempaa\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'niin kuin on kirjoitettu: \"Jaakobia minä rakastin, mutta Eesauta minä vihasin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Mitä siis sanomme? Ei kaiketi Jumalassa ole vääryyttä? Ei ikinä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Sillä Moosekselle hän sanoo: \"Olen armollinen, kenelle olen armollinen, ja armahdan, ketä armahdan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Se ei siis riipu siitä, joka tahtoo, eikä siitä, joka juoksee, vaan Jumalasta, joka on armollinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Sillä Raamattu sanoo faraolle: \"Juuri sitä varten nostin sinut esiin, että näyttäisin sinussa voimani ja että nimeäni julistettaisiin kaikessa maassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Hän on siis armollinen, kenelle tahtoo, ja paaduttaa, kenet tahtoo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Sinä kaiketi sanot minulle: \"Miksi hän sitten vielä syyttää? Sillä kuka voi vastustaa hänen tahtoaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Tosiaan, ihminen, mikä sinä olet väittelemään Jumalaa vastaan? Ei kaiketi saviastia sano valajalleen: \"Miksi minusta tällaisen teit?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Vai eikö savenvalajalla ole valta tehdä samasta saviseoksesta toinen astia jaloa, toinen halpaa käyttöä varten?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Mutta entä jos Jumala – vaikka tahtookin näyttää vihansa ja tehdä tiettäväksi voimansa – on suurella pitkämielisyydellä kärsinyt vihan astioita, jotka olivat valmiita hävitettäviksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'ja on tehnyt sen saattaakseen kirkkautensa runsauden tiettäväksi laupeuden astioille, jotka hän on valmistanut edeltä kirkkauteen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'Sellaisiksi hän on kutsunut meidätkin, ei ainoastaan juutalaisista, vaan myös pakanoista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'niin kuin hän myös Hoosean kirjassa sanoo: \"Minä olen kutsuva kansakseni sen, joka ei ollut minun kansani, ja rakkaakseni sen, joka ei ollut minun rakkaani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'On tapahtuva, että siinä paikassa, jossa heille on sanottu: \'Te ette ole minun kansani\', siinä heitä kutsutaan elävän Jumalan lapsiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Mutta Jesaja huudahtaa Israelista: \"Vaikka Israelin lapsia olisi määrältään kuin meren hiekkaa, pelastuu heistä vain jäännös.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'Sillä sanansa Herra on toteuttava maan päällä vanhurskaudessa lopullisesti ja äkkiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'Kuten Jesaja on myös ennustanut: \"Ellei Herra Sebaot olisi jättänyt meille siementä, meidän olisi käynyt kuin Sodoman, ja olisimme Gomorran kaltaisia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Mitä me siis sanomme? Että pakanat, jotka eivät tavoitelleet vanhurskautta, ottivat vastaan vanhurskauden, mutta sen vanhurskauden, joka tulee uskosta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'mutta Israel, joka tavoitteli vanhurskauden lakia, ei vanhurskauden lakia saavuttanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Minkä tähden? Sen tähden, ettei se tapahtunut uskosta, vaan ikään kuin lain teoista, sillä he loukkaantuivat loukkauskiveen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'niin kuin on kirjoitettu: \"Katso, panen Siioniin loukkauskiven ja kompastuksen kallion, eikä kukaan, joka häneen uskoo, joudu häpeään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Veljet, minä toivon sydämeni pohjasta ja rukoilen Jumalaa Israelin puolesta, että he pelastuisivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Sillä todistan heistä, että heillä on kiivaus Jumalan puoleen, mutta ei oikean tiedon mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'sillä kun he eivät tunne Jumalan vanhurskautta, vaan yrittävät pystyttää omaa vanhurskauttaan, he eivät ole alistuneet Jumalan vanhurskauden alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Sillä Kristus on lain loppu, vanhurskaudeksi jokaiselle, joka uskoo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Kirjoittaahan Mooses siitä vanhurskaudesta, joka tulee laista, että ihminen, joka sen täyttää, on siitä elävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Mutta se vanhurskaus, joka tulee uskosta, sanoo näin: \"Älä sano sydämessäsi: Kuka nousee taivaaseen?\" se on: tuomaan Kristusta alas,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'tai: \"Kuka astuu alas syvyyteen?\" se on: nostamaan Kristusta kuolleista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Mutta mitä se sanoo? \"Sana on sinua lähellä, sinun suussasi ja sinun sydämessäsi.\" Se on se uskon sana, jota saarnaamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Sillä jos tunnustat suullasi Jeesuksen Herraksi ja uskot sydämessäsi, että Jumala on hänet kuolleista herättänyt, pelastut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'sillä sydämellä uskotaan vanhurskaudeksi, mutta suulla tunnustaen pelastutaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Sanoohan Raamattu: \"Ei yksikään, joka uskoo häneen, joudu häpeään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Tässä ei ole erotusta juutalaisen eikä kreikkalaisen välillä, sillä yksi ja sama on kaikkien Herra, rikas antaja kaikille, jotka häntä avuksi huutavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'Sillä \"jokainen, joka huutaa avuksi Herran nimeä, pelastuu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Kuinka he sitten huutavat avukseen sitä, johon eivät usko? Kuinka he taas voivat uskoa siihen, josta eivät ole kuulleet? Mutta kuinka he voivat kuulla, ellei ole julistajaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Kuinka he julistavat, ellei heitä lähetetä? Niin kuin on kirjoitettu: \"Kuinka suloiset ovat niiden jalat, jotka julistavat rauhaa ja tuovat hyvän sanoman!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Mutta kaikki eivät ole olleet kuuliaisia evankeliumille. Sillä Jesaja sanoo: \"Herra, kuka uskoo meidän saarnamme?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Usko tulee siis saarnasta, mutta saarna Jumalan sanasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Mutta sanon: eivätkö he ole kuulleet? Kyllä ovat: \"Heidän äänensä on kulkenut kaikkiin maihin, ja heidän sanansa maanpiirin ääriin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Sanon: eikö Israelilla ole ollut siitä tietoa? Ensiksi jo Mooses sanoo: \"Minä herätän teidän kiivautenne kansalla, joka ei ole kansa, ymmärtämättömällä kansalla teitä kiihotan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'Jesaja taas sanookin rohkeasti: \"Minut ovat löytäneet ne, jotka eivät minua etsineet. Olen ilmestynyt niille, jotka eivät minua kysyneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Mutta Israelista hän sanoo: \"Koko päivän olen ojentanut käsiäni tottelematonta ja vastaan sanovaa kansaa kohden.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Sanon siis: ei kai Jumala ole hylännyt kansaansa? Ei ikinä! Sillä olenhan minäkin israelilainen, Aabrahamin siementä, Benjaminin sukukuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Ei Jumala ole hylännyt kansaansa, jonka hän on edeltä tuntenut omakseen. Vai ettekö tiedä, mitä Raamattu sanoo Eliasta puhuessaan, kuinka hän Jumalan edessä syyttää Israelia:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, '\"Herra, he ovat tappaneet sinun profeettasi ja hajottaneet sinun alttarisi, ja minä yksin olen jäänyt jäljelle, ja he tavoittelevat minunkin henkeäni\"?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Mutta mitä sanoo hänelle Jumalan vastaus? \"Olen jättänyt itselleni seitsemäntuhatta miestä, jotka eivät ole notkistaneet polvea Baalille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Samoin on nyt tänäkin aikana olemassa jäännös armon valinnan mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Mutta jos valinta on armosta, se ei ole enää teoista, sillä silloin armo ei enää olisi armo. Mutta jos se on teoista, se ei ole armoa, sillä muuten teko ei enää ole teko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Miten siis on? Mitä Israel tavoittelee, sitä se ei ole saavuttanut, mutta valitut ovat sen saavuttaneet. Muut ovat paatuneet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'kuten on kirjoitettu: \"Jumala on antanut heille uneliaisuuden hengen, silmät, etteivät näkisi, ja korvat, etteivät kuulisi, tähän päivään asti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Ja Daavid sanoo: \"Tulkoon heidän pöytänsä heille paulaksi, ansaksi, lankeemukseksi ja kostoksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'tulkoot heidän silmänsä sokeiksi, etteivät näkisi, ja paina aina heidän selkäänsä kumaraan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Sanon siis: eivät he kaiketi ole kompastuneet sitä varten, että lankeaisivat? Ei ikinä! Vaan heidän lankeemuksensa on pakanoille pelastukseksi, jotta he syttyisivät kateuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Mutta jos heidän lankeemuksensa on maailmalle rikkaudeksi ja heidän tappionsa pakanoille rikkaudeksi, kuinka paljon enemmän heidän täyteytensä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Teille, pakanoille, sanon: Koska minä olen pakanain apostoli, pidän virkani kunniassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'sytyttääkseni, jos mahdollista, kiivauteen niitä, jotka ovat lihaani, ja pelastaakseni joitakin heistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Jos näet heidän hylkäämisensä on sovitukseksi maailmalle, mitä heidän armoon ottamisensa on muuta kuin elämä kuolleista?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Mutta jos uutisleipä on pyhä, niin on myös koko taikina, ja jos juuri on pyhä, niin ovat myös oksat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Mutta jos muutamat oksista on taitettu pois ja sinä, joka olet metsäöljypuu, olet oksastettu oikeiden oksien joukkoon ja olet päässyt niiden kanssa osalliseksi öljypuun mehevästä juuresta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'niin älä ylpeile oksien rinnalla, mutta jos ylpeilet, niin et sinä kuitenkaan kannata juurta, vaan juuri sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Ehkäpä sanot: \"Nuo oksat taitettiin pois, jotta minut oksastettaisiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Oikein. Epäuskonsa tähden ne taitettiin pois, mutta sinä pysyt uskosi kautta. Älä ole ylpeä, vaan pelkää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Sillä jos Jumala ei ole säästänyt luonnollisia oksia, hän ei ole säästävä sinuakaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Katso siis Jumalan hyvyyttä ja ankaruutta: Jumalan ankaruutta langenneita kohtaan, mutta hänen hyvyyttään sinua kohtaan, jos hänen hyvyydessään pysyt. Muuten sinutkin hakataan pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Mutta nuo toisetkin, jos eivät jää epäuskoonsa, tulevat oksastettaviksi, sillä Jumala on voimallinen oksastamaan ne jälleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Sillä jos sinut on leikattu luonnollisesta metsäöljypuusta ja vasten luontoa oksastettu jaloon öljypuuhun, kuinka paljoa ennemmin nämä luonnolliset oksat oksastetaan omaan öljypuuhunsa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Sillä en tahdo, veljet – ettette olisi oman viisautenne varassa – pitää teitä tietämättöminä tästä salaisuudesta, että Israelia on kohdannut osaksi paatumus – aina siihen asti, kunnes pakanain täysi luku on tullut sisälle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'ja tällä tavalla kaikki Israel on pelastuva, kuten on kirjoitettu: \"Siionista on tuleva pelastaja, hän poistaa jumalattoman menon Jaakobista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'Tämä on oleva minun liittoni heidän kanssaan, kun otan pois heidän syntinsä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Evankeliumin kannalta he ovat tosin vihollisia teidän tähtenne, mutta valinnan kannalta he ovat rakastettuja isien tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Sillä Jumala ei kadu armolahjojaan eikä kutsumistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Samoin kuin te ennen olitte Jumalalle tottelemattomia, mutta nyt olette saaneet laupeuden näiden tottelemattomuuden kautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'samoin nämäkin ovat nyt olleet tottelemattomia, että myös he teille tulleen armahtamisen kautta nyt saisivat laupeuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Sillä Jumala on sulkenut kaikki tottelemattomuuteen, että hän kaikkia armahtaisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'Oi sitä Jumalan rikkauden ja viisauden ja tiedon syvyyttä! Kuinka tutkimattomat ovat hänen tuomionsa ja käsittämättömät hänen tiensä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Sillä kuka on tuntenut Herran mielen? Tai kuka on ollut hänen neuvonantajansa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Tai kuka on ensin antanut hänelle jotakin, joka olisi antajalle korvattava?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Sillä hänestä ja hänen kauttaan ja häntä varten on kaikki. Hänelle kunnia iankaikkisesti! Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Jumalan armahtavan laupeuden kautta kehotan siis teitä, veljet, antamaan ruumiinne eläväksi, pyhäksi, Jumalalle otolliseksi uhriksi. Se olkoon teidän järjellinen jumalanpalveluksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'Älkääkä mukautuko tämän maailmanajan mukaan, vaan muuttukaa mielenne uudistuksen kautta, tutkiaksenne, mikä on Jumalan tahto, mikä hyvää, otollista ja täydellistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Sillä sen armon kautta, mikä minulle on annettu, sanon teille jokaiselle, ettei tule ajatella itsestään enempää, kuin ajatella sopii, vaan ajatella kohtuullisesti sen uskonmäärän mukaan, minkä Jumala on kullekin jakanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Sillä niin kuin meillä yhdessä ruumiissa on monta jäsentä, mutta kaikilla jäsenillä ei ole sama tehtävä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'niin vaikka meitä on monta, olemme yksi ruumis Kristuksessa, mutta itse kukin olemme toistemme jäseniä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Meillä on erilaisia armolahjoja sen armon mukaan, mitä meille on annettu. Jos jollakulla on profetoimisen lahja, käyttäköön sitä uskon mukaisesti;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'jos virka, pitäköön virastaan vaarin; jos joku opettaa, olkoon uskollinen opettamisessaan;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'jos kehottaa, kehottamisessaan; joka antaa, antakoon vakaasta sydämestä; joka on johtaja, johtakoon toimellisesti; joka laupeutta harjoittaa, tehköön sen iloiten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Olkoon rakkaus vilpitön, kammotkaa pahaa, riippukaa hyvässä kiinni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Olkaa veljellisessä rakkaudessa helläsydämiset toisianne kohtaan. Kunnioittamisessa asettakaa toinen itsenne edelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'Intoon nähden älkää olko velttoja. Olkaa hengessä palavia, palvelkaa Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Olkaa toivossa iloiset, ahdistuksessa kärsivälliset, rukouksessa kestävät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Pitäkää pyhien tarpeet ominanne. Harrastakaa vieraanvaraisuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Siunatkaa vainoojianne, siunatkaa, älkääkä kirotko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Iloitkaa iloitsevien kanssa, itkekää itkevien kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Olkaa keskenänne yksimieliset. Älkää korkeita havitelko, vaan tyytykää alhaisiin oloihin. Älkää olko omasta mielestänne viisaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Älkää kenellekään pahalla pahaa kostako. Ahkeroikaa sitä, mikä on hyvää kaikkien ihmisten edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Jos on mahdollista ja mikäli teistä riippuu, eläkää rauhassa kaikkien ihmisten kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Älkää itse kostako, rakkaani, vaan antakaa sijaa vihalle, sillä kirjoitettu on: \"Minun on kosto, minä olen maksava, sanoo Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Vaan \"jos vihamiehelläsi on nälkä, ruoki häntä, jos hänellä on jano, juota häntä, sillä näin tehden sinä kokoat tulisia hiiliä hänen päänsä päälle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Älä anna pahan itseäsi voittaa, vaan voita sinä paha hyvällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Jokainen sielu olkoon alamainen niille valloille, joiden vallan alla hän on. Sillä ei ole esivaltaa muuten kuin Jumalalta. Vallat, jotka ovat, ovat Jumalan asettamia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Sen tähden se, joka asettuu esivaltaa vastaan, nousee Jumalan säätämystä vastaan, mutta jotka nousevat vastaan, tuottavat itselleen tuomion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Sillä hallitusmiehet eivät ole niiden pelkona, jotka tekevät hyvää, vaan niiden, jotka tekevät pahaa. Jos siis tahdot olla esivaltaa pelkäämättä, tee sitä, mikä on hyvää, ja sinä saat siltä kiitoksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'Sillä se on Jumalan palvelija sinulle hyväksi. Mutta jos pahaa teet, pelkää, sillä se ei kanna miekkaa turhaan, koska se on Jumalan palvelija, kostaja sen rankaisemiseksi, joka pahaa tekee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Siksi tulee olla alamainen, ei ainoastaan rangaistuksen tähden, vaan myös omantunnon tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Sen tähden maksakaa myös veroja. Sillä he ovat Jumalan palvelijoita ja tekevät työtään juuri sitä varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Antakaa kaikille, mitä annettava on: kenelle vero, sille vero, kenelle tulli, sille tulli, kenelle pelko, sille pelko, kenelle kunnia, sille kunnia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Älkää olko kenellekään mitään velkaa, muuta kuin että toisianne rakastatte, sillä se, joka toistansa rakastaa, on lain täyttänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Sillä nämä: \"Älä tee huorin, älä tapa, älä varasta, älä himoitse\", ja mikä muu käsky tahansa, sisältyvät kaikki tähän sanaan: \"Rakasta lähimmäistäsi kuin itseäsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Rakkaus ei tee lähimmäiselle mitään pahaa. Sen tähden rakkaus on lain täyttämys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Tehkää tämä, koska tunnette tämän ajan, että on jo hetki teidän nousta unesta. Sillä pelastus on nyt meitä lähempänä kuin silloin, kun uskoon tulimme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Yö on pitkälle kulunut, ja päivä on lähellä. Pankaamme sen tähden pois pimeyden teot, ja pukeutukaamme valkeuden aseisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Vaeltakaamme säädyllisesti niin kuin päivällä, ei mässäillen ja juopotellen, ei haureudessa ja irstaudessa, ei riidassa ja kateudessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'vaan pukekaa päällenne Herra Jeesus Kristus, älkääkä hellikö lihaanne niin, että himot heräävät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Uskossa heikko ottakaa yhteyteenne väittelemättä mielipiteistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Joku toinen uskoo saavansa syödä kaikkea, mutta heikko syö vihanneksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Se, joka syö, älköön halveksiko sitä, joka ei syö, ja se, joka ei syö, älköön tuomitko sitä, joka syö, sillä Jumala on ottanut hänet omakseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Mikä sinä olet tuomitsemaan toisen palvelijan? Oman isäntänsä edessä hän seisoo tai kaatuu. Mutta hän on pysyvä pystyssä, sillä Herra on voimallinen pitämään hänet pystyssä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Toinen pitää yhden päivän toista parempana, toinen pyhittää kaikki päivät. Olkoon jokainen omassa mielessään täysin varma.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Se, joka valikoi päiviä, valikoi Herralle. Se, joka syö, syö Herralle, sillä hän kiittää Jumalaa. Se, joka ei syö, on Herralle syömättä ja kiittää Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Sillä ei kukaan meistä elä itselleen, eikä kukaan kuole itselleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Jos elämme, elämme Herralle, ja jos kuolemme, kuolemme Herralle. Sen tähden, elimme tai kuolimme, olemme Herran omat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Sillä sitä varten Kristus kuoli, heräsi eloon ja nousi kuolleista, että hän olisi sekä kuolleitten että elävien Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Mutta sinä, minkä tähden tuomitset veljeäsi? Tai sinä toinen, minkä tähden halveksit veljeäsi? Sillä kaikki meidät asetetaan Jumalan tuomioistuimen eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Sillä kirjoitettu on: \"Niin totta kuin minä elän, sanoo Herra, minun edessäni on jokainen polvi notkistuva ja jokainen kieli ylistävä Jumalaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Niin on siis meidän jokaisen tehtävä Jumalalle tili itsestämme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Älkäämme siis enää toisiamme tuomitko, vaan päättäkää pikemmin olla panematta veljenne eteen loukkauskiveä tai pahennusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Tiedän ja olen varma Herrassa Jeesuksessa, ettei mikään ole epäpyhää itsessään, vaan ainoastaan sille, joka pitää jotakin epäpyhänä, sille se on epäpyhää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Mutta jos veljesi tulee murheelliseksi ruokasi tähden, niin et enää vaella rakkauden mukaan. Älä saata ruuallasi turmioon sitä, jonka edestä Kristus on kuollut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Älkää siis antako sen hyvän, mikä teillä on, tulla häväistyksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'sillä ei Jumalan valtakunta ole syömistä ja juomista, vaan vanhurskautta, rauhaa ja iloa Pyhässä Hengessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Se, joka tässä kohden palvelee Kristusta, on Jumalalle otollinen ja ihmisille kelvollinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Tavoitelkaamme siis sitä, mikä edistää rauhaa ja keskinäistä rakentumista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Älä ruuan tähden turmele Jumalan työtä. Kaikki tosin on puhdasta, mutta sille ihmiselle, joka syö omaatuntoaan loukaten, se on pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Hyvä on olla lihaa syömättä ja viiniä juomatta sekä karttaa sitä, mistä veljesi loukkaantuu tai joutuu lankeemukseen tai tulee heikoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Pidä itselläsi Jumalan edessä se usko, mikä sinulla on. Onnellinen on se, joka ei tuomitse itseään siitä, mitä pitää oikeana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Mutta joka epäröi ja kuitenkin syö, on tuomittu, koska se ei tapahdu uskosta, sillä kaikki, mikä ei ole uskosta, on syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Mutta meidän, vahvojen, tulee kantaa heikkojen vajavuuksia, eikä olla itsellemme mieliksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Olkoon kukin meistä lähimmäiselleen mieliksi hänen parhaakseen, että hän rakentuisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Sillä ei Kristuskaan elänyt itselleen mieliksi, vaan niin kuin kirjoitettu on: \"Niiden solvaukset, jotka sinua parjaavat, ovat sattuneet minuun.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Sillä kaikki, mikä ennen on kirjoitettu, on kirjoitettu meille opiksi, että meillä kärsivällisyyden ja Kirjoitusten lohdutuksen kautta olisi toivo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Mutta kärsivällisyyden ja lohdutuksen Jumala suokoon teille, että olisitte yksimieliset keskenänne, Kristuksen Jeesuksen mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'niin että yksimielisesti yhdestä suusta ylistäisitte Jumalaa ja meidän Herramme Jeesuksen Kristuksen Isää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Ottakaa sen vuoksi toinen toisenne keskinäiseen yhteyteen, niin kuin Kristuskin on teidät luokseen ottanut, Jumalan kunniaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Sillä minä sanon, että Kristus on tullut ympärileikattujen palvelijaksi Jumalan totuuden tähden vahvistaakseen isille annetut lupaukset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'mutta että pakanat laupeuden tähden ovat ylistäneet Jumalaa, kuten on kirjoitettu: \"Sen tähden ylistän sinua pakanain keskellä ja laulan kiitosta sinun nimellesi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'Vielä hän sanoo: \"Riemuitkaa, pakanat, hänen kansansa kanssa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'Ja taas: \"Kiittäkää Herraa, kaikki pakanat, ja ylistäkööt häntä kaikki kansat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'Myös Jesaja sanoo: \"On tuleva Iisain juurivesa, hän, joka nousee hallitsemaan pakanoita. Häneen pakanat panevat toivonsa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Mutta toivon Jumala täyttäköön teidät uskoessanne kaikella ilolla ja rauhalla, että teillä olisi runsas toivo Pyhän Hengen voimassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Veljeni, minä itsekin olen varma teistä, että te itse olette täynnä hyvyyttä ja kaikkinaista tietoa, niin että myös kykenette neuvomaan toisianne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Kuitenkin olen paikka paikoin jotenkin rohkeasti teille kirjoittanut muistuttaakseni teille näitä asioita sen armon tähden, jonka Jumala on minulle antanut');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'ollakseni Jeesuksen Kristuksen palvelija pakanoita varten toimittaakseni papillisesti Jumalan evankeliumin palvelusta, niin että pakanoista tulisi otollinen Pyhässä Hengessä pyhitetty uhri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Minulla on siis kerskaukseni Kristuksessa Jeesuksessa palvellessani Jumalaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'sillä minä en rohkene puhua mistään muusta kuin siitä, mitä Kristus on saattaakseen pakanat kuuliaisiksi kauttani vaikuttanut sanalla ja teolla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'tunnustekojen ja ihmeiden voimalla, Jumalan Hengen voimalla, niin että minä Jerusalemista ja sen ympäristöstä alkaen Illyrikoniin asti olen suorittanut Kristuksen evankeliumin julistamisen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'sillä tavoin, että olen pitänyt kunnianani olla julistamatta evankeliumia siellä, missä Kristuksen nimi on jo mainittu, etten rakentaisi toisen laskemalle perustukselle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'vaan kuten on kirjoitettu: \"Ne, joille ei ole hänestä kerrottu, saavat nähdä hänet, ja ne, jotka eivät ole kuulleet, tajuavat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Sen tähden olenkin niin usein ollut estetty tulemasta teidän luoksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Mutta koska minulla nyt ei ole enää tilaa näissä paikkakunnissa ja kun jo monta vuotta olen halunnut tulla teidän luoksenne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'niin jos milloin menen Hispaniaan, tulen luoksenne, sillä toivon sieltä kautta matkustaessani näkeväni teidät ja teidän lähettävän minut sinne, kunhan ensin olen jonkin verran virkistynyt teistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Mutta nyt menen Jerusalemiin viemään pyhille avustusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Sillä Makedonia ja Akaia ovat nähneet hyväksi kerätä yhteisen lahjan niille Jerusalemin pyhille, jotka ovat köyhyydessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Niin he ovat nähneet hyväksi, ja he ovatkin sen heille velkaa, sillä jos pakanat ovat tulleet osallisiksi heidän hengellisistä aarteistaan, he ovat puolestaan velvollisia auttamaan heitä maallisilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Kun olen tämän suorittanut ja vienyt heille tämän hedelmän perille, lähden teidän kauttanne Hispaniaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Tiedän, että tullessani luoksenne tulen Kristuksen evankeliumin täydellinen siunaus mukanani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Mutta kehotan teitä, veljet, Herramme Jeesuksen Kristuksen kautta ja Hengen rakkauden kautta taistelemaan kanssani rukouksissa ja puolestani rukoilemaan Jumalaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'että pelastuisin Juudean epäuskoisilta ja että Jerusalemia varten tuomani avustus olisi pyhille otollinen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'niin että jos Jumala tahtoo, ilolla saapuisin luoksenne ja virkistyisin kanssanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Rauhan Jumala olkoon teidän kaikkien kanssa. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Suosittelemme teille sisartamme Foibea, joka on Kenkrean seurakunnan palvelija,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'että otatte hänet vastaan Herrassa, niin kuin pyhien sopii, ja autatte häntä kaikessa, missä hän teitä tarvitsee, sillä hän on ollut monelle avuksi ja jopa minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Tervehtikää Priskaa ja Akylasta, työtovereitani Kristuksessa Jeesuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'He ovat minun henkeni puolesta panneet oman kaulansa alttiiksi. En ainoastaan minä kiitä heitä, vaan myös kaikki pakanain seurakunnat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Tervehtikää myös seurakuntaa, joka kokoontuu heidän kodissaan. Tervehtikää Epainetosta, rakasta veljeäni, joka on Aasian maakunnan ensi hedelmä Kristukselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Tervehtikää Mariaa, joka on nähnyt paljon vaivaa teidän hyväksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Tervehtikää Andronikosta ja Juniaa, heimolaisiani ja vankeustovereitani, joilla on suuri maine apostolien keskuudessa ja jotka jo ennen minua ovat olleet Kristuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Tervehtikää Ampliatusta, rakasta veljeäni Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Tervehtikää Urbanusta, työtoveriamme Kristuksessa, ja Stakysta, rakasta veljeäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Tervehtikää Apelleeta, koetuksen kestänyttä Kristuksessa. Tervehtikää Aristobuloksen perhekuntalaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Tervehdys Herodionille, heimolaiselleni. Tervehdys Narkissuksen perhekuntalaisille, jotka ovat Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Tervehtikää Tryfainaa ja Tryfosaa, jotka ovat nähneet vaivaa Herrassa. Tervehtikää Persistä, rakasta sisarta, joka on nähnyt paljon vaivaa Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Tervehtikää Rufusta, valittua Herrassa, ja hänen äitiään, joka on kuin äiti minullekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Tervehtikää Asynkritosta, Flegonia, Hermestä, Patrobasta, Hermasta ja veljiä, jotka ovat heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Tervehtikää Filologosta ja Juliaa, Nereusta ja hänen sisartaan ja Olympasta ja kaikkia pyhiä, jotka ovat heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Tervehtikää toisianne pyhällä suudelmalla. Kaikki Kristuksen seurakunnat tervehtivät teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Mutta kehotan teitä, veljet, pitämään silmällä niitä, jotka saavat aikaan erimielisyyttä ja pahennusta vastoin sitä oppia, jonka te olette saaneet. Vetäytykää pois heistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Sillä sellaiset eivät palvele Herraamme Kristusta, vaan omaa vatsaansa, ja he pettävät mielistelevillä sanoilla ja ylistävillä puheilla vilpittömien sydämet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Onhan teidän kuuliaisuutenne tullut kaikkien tietoon. Niinpä iloitsen teistä, mutta tahtoisin teidän olevan viisaita hyvään, mutta puhtaita pahaan nähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Mutta rauhan Jumala on pian musertava saatanan jalkojenne alle. Herramme Jeesuksen armo olkoon kanssanne. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Teitä tervehtivät Timoteus, työtoverini, ja heimolaiseni Lukius, Jaason ja Soosipater.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Minä Tertius, joka olen kirjoittanut tämän kirjeen, tervehdin teitä Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Gaius, minun ja koko seurakunnan majoittaja, tervehtii teitä. Erastus, kaupungin varainhoitaja, ja veli Quartus tervehtivät teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'Herramme Jeesuksen Kristuksen armo olkoon teidän kanssanne. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Mutta hänen, joka voi teitä vahvistaa minun evankeliumini ja Jeesuksen Kristuksen saarnan mukaan, sen ilmoitetun salaisuuden mukaan, joka kautta ikuisten aikojen on ollut ilmoittamatta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'mutta joka nyt on saatettu julki ja profeetallisten Kirjoitusten kautta iankaikkisen Jumalan käskystä tehty tiettäväksi kaikille kansoille uskon kuuliaisuuden aikaansaamiseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'Jumalan, ainoan viisaan, olkoon kunnia Jeesuksen Kristuksen kautta iankaikkisesti. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paavali, Kristuksen Jeesuksen kutsuttu apostoli Jumalan tahdosta, ja veli Soostenes');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'Korinttossa olevalle Jumalan seurakunnalle, Kristuksessa Jeesuksessa pyhitetyille, kutsutuille pyhille, sekä kaikille, jotka huutavat avuksi Herramme Jeesuksen Kristuksen nimeä kaikissa paikkakunnissa, niin omissaan kuin meidänkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Armo teille ja rauha Jumalalta, Isältämme, ja Herralta Jeesukselta Kristukselta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Kiitän Jumalaani aina teidän tähtenne siitä Jumalan armosta, joka on annettu teille Kristuksessa Jeesuksessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'että kaikessa olette rikastuneet hänessä, kaikessa sanassa ja kaikessa tiedossa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'sen mukaan kuin todistus Kristuksesta on vahvistettu teissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'niin ettei teiltä puutu mitään missään armolahjassa teidän odottaessanne Herramme Jeesuksen Kristuksen ilmestymistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'Hän on myös vahvistava teitä loppuun asti, niin että olette nuhteettomat meidän Herramme Jeesuksen Kristuksen päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Jumala on uskollinen, hän, jonka kautta olette kutsutut hänen Poikansa Jeesuksen Kristuksen, meidän Herramme yhteyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Mutta kehotan teitä, veljet, meidän Herramme Jeesuksen Kristuksen nimeen, että kaikki olisitte puheessa yksimieliset, ettei keskuudessanne olisi eriseuroja, vaan että teillä olisi täysin sama mieli ja sama ajatus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Sillä Kloen perheväeltä olen saanut kuulla teistä, veljeni, että teillä on riitoja keskuudessanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Tarkoitan sitä, että itse kukin teistä sanoo: \"minä olen Paavalin\", \"minä Apolloksen\", \"minä Keefaan\" tai: \"minä Kristuksen\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Onko Kristus jaettu? Eihän Paavalia ole ristiinnaulittu teidän edestänne? Vai oletteko te kastetut Paavalin nimeen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Kiitän Jumalaa, etten ole kastanut teistä ketään paitsi Krispuksen ja Gaiuksen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'niin ettei kukaan sanoisi, että te olette minun nimeeni kastetut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Kastoinhan myös Stefanaan perhekunnan. Sitten en tiedä, olenko ketään muuta kastanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Sillä Kristus ei lähettänyt minua kastamaan, vaan evankeliumia julistamaan – ei puheen viisaudella, ettei Kristuksen risti menisi mitättömäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Sillä sana rististä on hullutus niille, jotka kadotukseen joutuvat, mutta meille, jotka pelastumme, se on Jumalan voima.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Onhan kirjoitettu: \"Hävitän viisaiden viisauden, ja hylkään ymmärtävien ymmärryksen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Missä on viisas? Missä kirjanoppinut? Missä tämän maailman tutkija? Eikö Jumala ole tehnyt maailman viisautta hullutukseksi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Sillä koska maailma ei oppinut Jumalan viisaudesta viisauden avulla tuntemaan Jumalaa, Jumala näki hyväksi hullun saarnan kautta pelastaa ne, jotka uskovat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'koskapa juutalaiset vaativat merkkiä ja kreikkalaiset etsivät viisautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'me taas saarnaamme ristiinnaulittua Kristusta, joka on juutalaisille pahennus ja pakanoille hulluutta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'mutta joka niille, jotka ovat kutsutut, olkoot juutalaisia tai kreikkalaisia, on Kristus, Jumalan voima ja Jumalan viisaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Sillä Jumalan hulluus on viisaampi kuin ihmiset, ja Jumalan heikkous on väkevämpi kuin ihmiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Sillä katsokaa, veljet, omaa kutsumistanne: ei ole monta viisasta lihan mukaan, ei monta vaikutusvaltaista, ei monta jalosukuista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'vaan sen, mikä on hulluutta maailmalle, sen Jumala valitsi saattaakseen viisaat häpeään, ja sen, mikä on heikkoa maailmassa, Jumala valitsi saattaakseen häpeään sen, mikä on vaikutusvaltaista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'ja sen, mikä maailmassa on halpasukuista ja halveksittua, Jumala valitsi, sen, joka ei ole mitään, tehdäkseen mitättömäksi sen, joka jotakin on,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'ettei mikään liha kerskuisi Jumalan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Mutta hänestä on teidän olemisenne Kristuksessa Jeesuksessa, joka on tullut meille viisaudeksi Jumalalta, vanhurskaudeksi, pyhitykseksi ja lunastukseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'että kävisi, kuten on kirjoitettu: \"Se, joka kerskaa, kerskatkoon Herrassa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Tullessani luoksenne, veljet, en tullut suurenmoisella puheella tai viisaudella teille Jumalan todistusta julistamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Sillä olin päättänyt olla luonanne tuntematta mitään muuta paitsi Jeesuksen Kristuksen, ja hänet ristiinnaulittuna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'Ja olin luonanne heikkoudessa, pelossa ja vapisin kovin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'eikä puheeni ja saarnani ollut kiehtovia viisauden sanoja, vaan Hengen ja voiman osoittamista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'ettei uskonne olisi ihmisten viisaudessa, vaan Jumalan voimassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Kuitenkin puhumme viisautta täydellisten seurassa, mutta emme tämän maailmanajan viisautta emmekä tämän maailman valtiaiden, jotka kukistuvat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'vaan puhumme salattua Jumalan viisautta, sitä kätkettyä, jonka Jumala on edeltämäärännyt ennen maailmanaikoja meidän kirkkaudeksemme,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'sitä, jota kukaan tämän maailman valtiaista ei ole tuntenut – sillä jos he olisivat sen tunteneet, he eivät olisi kirkkauden Herraa ristiinnaulinneet –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'vaan kuten on kirjoitettu: \"mitä silmä ei ole nähnyt eikä korva kuullut, mikä ei ole ihmisen sydämeen noussut ja minkä Jumala on valmistanut niille, jotka häntä rakastavat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Mutta meille Jumala on sen ilmoittanut Henkensä kautta, sillä Henki tutkii kaiken, Jumalan syvyydetkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Sillä kuka ihmisistä tietää, mitä ihmisessä on, paitsi ihmisen henki, joka hänessä on? Samoin ei myöskään kukaan tiedä, mitä Jumalassa on, paitsi Jumalan Henki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Mutta me emme ole saaneet maailman henkeä, vaan sen Hengen, joka on Jumalasta, että tietäisimme, mitä Jumala on meille lahjoittanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'Sitä myös puhumme, emme inhimillisen viisauden opettamilla sanoilla, vaan Pyhän Hengen opettamilla, selittäen hengelliset hengellisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Mutta luonnollinen ihminen ei ota vastaan sitä, mikä Jumalan Hengen on. Sillä se on hänelle hulluutta, eikä hän voi sitä ymmärtää, koska sitä on tutkittava hengellisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Hengellinen ihminen sitä vastoin tutkii kaiken, mutta häntä itseään ei tutki kukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Sillä: \"kuka on tullut tuntemaan Herran mielen, että voisi häntä opettaa?\" Mutta meillä on Kristuksen mieli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Niinpä, veljet, minä en voinut puhua teille kuin hengellisille, vaan kuin lihallisille, kuin pienille lapsille Kristuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Maitoa juotin teille, en antanut ruokaa, sillä sitä ette silloin kestäneet, ettekä vielä nytkään kestä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'olettehan vielä lihallisia. Sillä kun keskuudessanne on kateutta, riitaa ja erimielisyyttä, ettekö silloin ole lihallisia ja vaella ihmisten tavoin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Kun yksi sanoo: \"minä olen Paavalin\", ja toinen: \"minä olen Apollon\", ettekö silloin ole lihallisia?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Mikä Paavali sitten on ja mikä taas Apollo? Palvelijoita, joiden kautta te olette tulleet uskoviksi, palvelijoita sen mukaan, mitä Herra on heille kullekin antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Minä istutin, Apollo kasteli, mutta Jumala on antanut kasvun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Niin ei siis istuttaja ole mitään, eikä kastelijakaan, vaan Jumala, joka antaa kasvun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Mutta istuttaja ja kastelija ovat yhtä, kuitenkin kumpikin on saava oman palkkansa oman työnsä mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Sillä olemme Jumalan työtovereita. Olette Jumalan viljapelto, Jumalan rakennus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Sen Jumalan armon mukaan, joka on minulle annettu, olen viisaan rakentajan tavoin pannut perustuksen, mutta toinen sille rakentaa. Kuitenkin jokainen katsokoon, kuinka hän sille rakentaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Sillä muuta perustusta ei kukaan voi panna sen tilalle, mikä on pantu, ja se on Jeesus Kristus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Mutta jos joku rakentaa tälle perustukselle, rakensipa kullasta, hopeasta, jalokivistä, puusta, heinistä tai oljista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'niin kunkin teko on tuleva näkyviin. Sillä sen saattaa ilmi se päivä, joka tulessa ilmestyy, ja tuli koettelee, millainen kunkin teko on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Jos jonkun sille tekemä rakennus kestää, hän saa palkan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Mutta jos jonkun tekemä palaa, hän kärsii vahingon. Mutta hän itse pelastuu, kuitenkin kuin tulen läpi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Ettekö tiedä, että te olette Jumalan temppeli ja että Jumalan Henki asuu teissä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Jos joku turmelee Jumalan temppelin, Jumala turmelee hänet, sillä Jumalan temppeli on pyhä. Sellaisia te olette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Älköön kukaan pettäkö itseään. Jos joku joukossanne luulee olevansa viisas tässä maailmassa, tulkoon tyhmäksi, että tulisi viisaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Sillä tämän maailman viisaus on hullutusta Jumalan edessä. Sillä kirjoitettu on: \"Hän vangitsee viisaat heidän viekkauteensa\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'ja vielä: \"Herra tietää viisasten ajatusten olevan turhia.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Älköön siis kukaan kerskatko ihmisistä, sillä kaikki on teidän,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'olkoon Paavali, Apollo, Keefas, maailma, elämä, kuolema, nykyiset tai tulevaiset, kaikki on teidän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'Mutta te olette Kristuksen, ja Kristus on Jumalan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Niin pitäköön jokainen meitä Kristuksen palvelijoina ja Jumalan salaisuuksien huoneenhaltijoina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Mutta huoneenhaltijoilta edellytetään ennen muuta, että heidät havaitaan uskollisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Mutta minulle on pikkuasia, että te minua tuomitsette tai jokin ihmisten tuomiopäivä. En minäkään itseäni tuomitse,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'sillä minulla ei ole mitään tunnollani, mutta ei minua siitä syystä ole vanhurskaaksi julistettu, vaan minun tuomitsijani on Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Älkää sen tähden lausuko mitään tuomiota, ennen kuin aika on, ennen kuin Herra tulee, joka myös on saattava valoon pimeyden kätköt ja tuova julki sydänten ajatukset. Silloin kukin saa kiitoksensa Jumalalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Tämän olen, veljet, sovittanut itseeni ja Apolloon, teidän tähtenne, että meistä oppisitte tämän: \"Ei pidä järkeillä yli sen, mikä on kirjoitettu\", ettette pöyhkeillen asettuisi mikä minkin puolelle toista vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Sillä kuka antaa sinulle etusijan? Ja mitä sinulla on, jota et ole saanut lahjaksi? Mutta jos olet sen saanut, niin miksi kerskaat, ikään kuin se ei olisi saatua?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Te olette jo ravitut, teistä on jo tullut rikkaita, ilman meitä teistä on tullut kuninkaita! Kunpa teistä olisikin tullut kuninkaita, niin että mekin tulisimme kuninkaiksi teidän kanssanne!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Sillä minusta näyttää, että Jumala on asettanut meidät apostolit viimeisiksi, ikään kuin kuolemaan tuomituiksi. Meistä on tullut kaiken maailman katseltava, sekä enkelien että ihmisten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'me olemme houkkia Kristuksen tähden, mutta te viisaita Kristuksessa, me olemme heikkoja, mutta te vahvoja. Te olette kunnioitettuja, mutta me halveksittuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Yhä edelleen me kärsimme sekä nälkää että janoa, olemme vähissä vaatteissa, meitä ruoskitaan, ja kuljemme kodittomina,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'näemme vaivaa tehden työtä omin käsin. Kun meitä panetellaan, siunaamme. Kun meitä vainotaan, kestämme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'Kun meitä pilkataan, puhumme lempeästi. Meistä on tullut kuin maailman tunkio, kaikkien törkykasa, aina tähän asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'En kirjoita tätä häväistäkseni teitä, vaan kuin rakkaita lapsiani neuvoen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Sillä vaikka teillä olisi kymmenentuhatta kasvattajaa Kristuksessa, teillä kuitenkaan ei ole monta isää, sillä Kristuksessa Jeesuksessa minä teidät synnytin evankeliumilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Kehotan siis teitä: olkaa minun seuraajiani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Sen vuoksi lähetin teille Timoteuksen, joka on minun rakas ja uskollinen lapseni Herrassa. Hän on muistuttava teitä minun teistäni Kristuksessa Jeesuksessa, sen mukaan kuin kaikkialla, joka seurakunnassa, opetan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Muutamat teistä ovat paisuneet pöyhkeiksi, niin kuin minä en olisikaan tulossa luoksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Mutta tulen luoksenne pian, jos Herra tahtoo, ja silloin otan selon, en noiden pöyhkeiden sanoista, vaan voimasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Sillä Jumalan valtakunta ei ole sanoissa, vaan voimassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Kumman tahdotte? Tulenko luoksenne ruoska kädessä vai sävyisyyden hengessä rakkaudessa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Yleensä kuuluu, että keskuudessanne on haureutta, jopa sellaista haureutta, jota ei ole pakanoidenkaan keskuudessa, että eräskin pitää isänsä vaimoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Te olette paisuneet pöyhkeiksi! Eikö teidän pikemminkin olisi pitänyt tulla murheellisiksi, että se, joka on tehnyt tuollaisen teon, poistettaisiin keskuudestanne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Sillä minä, joka tosin ruumiillisesti olen poissa, mutta hengessä kuitenkin läsnä, olen jo kuin läsnä ollen puolestani päättänyt, että se, joka tuollaisen teon on tehnyt, on');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, '– sitten kun te ja minun henkeni sekä meidän Herramme Jeesuksen voima, olemme tulleet yhteen –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'Herran Jeesuksen nimessä hylättävä saatanan haltuun lihan turmioksi, että hänen henkensä pelastuisi Herran päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Ei ole hyvä, että kerskaatte. Ettekö tiedä, että vähäinen hapate hapattaa koko taikinan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Peratkaa pois vanha hapantaikina, että olisitte uusi taikina, niin kuin olettekin happamattomat, sillä onhan meidän pääsiäislampaamme, Kristus, teurastettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Viettäkäämme siis juhlaa, ei vanhassa hapantaikinassa eikä ilkeyden ja pahuuden hapantaikinassa, vaan puhtauden ja totuuden happamattomuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Kirjoitin teille kirjeessäni, ettette seurustelisi huorintekijöiden kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'En tarkoittanut yleensä tämän maailman huorintekijöitä, ahneita, anastajia tai epäjumalanpalvelijoita, sillä silloinhan teidän täytyisi lähteä pois maailmasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Vaan minä kirjoitin teille, että jos joku, jota kutsutaan veljeksi, on huorintekijä, ahne, epäjumalanpalvelija, pilkkaaja, juomari tai anastaja, te ette seurustelisi ettekä söisikään sellaisen kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Sillä onko minun asiani tuomita niitä, jotka ovat ulkopuolella? Ettekö tekin tuomitse vain niitä, jotka ovat sisäpuolella?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Mutta ulkopuolella olevat tuomitsee Jumala. \"Poistakaa paha keskuudestanne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Rohkeneeko kukaan teistä, jolla on riita-asia toisen kanssa, käydä oikeutta väärien edessä eikä pyhien edessä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Vai ettekö tiedä, että pyhät tulevat tuomitsemaan maailman? Jos te tuomitsette maailman, ettekö kelpaa ratkaisemaan aivan vähäpätöisiä asioita?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Ettekö tiedä, että tulemme tuomitsemaan enkeleitä, emmekö sitten maallisia asioita?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Jos teillä siis on maallisia asioita ratkaistavina, nekö te asetatte tuomareiksi, jotka ovat halveksittuja seurakunnassa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Teidän häpeäksenne tämän sanon. Eikö teidän joukossanne sitten ole ketään viisasta, joka voisi ratkaista veljien välin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Vaan veli käy oikeutta veljeä vastaan, vieläpä uskosta osattomien edessä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Teille on jo yleensä vaurioksi, että käräjöitte keskenänne. Miksi ette ennemmin salli tehdä vääryyttä itsellenne? Miksi ette ennemmin anna riistää omaanne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Sen sijaan te itse teette vääryyttä ja riistätte toisen omaa, vieläpä veljien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Vai ettekö tiedä, etteivät väärät peri Jumalan valtakuntaa? Älkää eksykö. Eivät huorintekijät, eivät epäjumalanpalvelijat, eivät avionrikkojat, eivät elostelijat eivätkä miehen kanssa makaavat miehet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'eivät varkaat, eivät ahneet, eivät juomarit, eivät pilkkaajat eivätkä rosvot peri Jumalan valtakuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Tuollaisia tekin olitte, jotkut teistä. Mutta olette vastaanottaneet pesun, olette pyhitetyt, olette vanhurskaiksi julistetut Herramme Jeesuksen Kristuksen nimessä ja Jumalamme Hengessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Kaikki on minulle luvallista, mutta kaikki ei ole hyödyksi. Kaikki on minulle luvallista, mutta minä en saa antaa minkään itseäni vallita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Ruuat ovat vatsaa varten ja vatsa ruokia varten, ja Jumala on tekevä lopun niin toisesta kuin toisestakin. Mutta ruumis ei ole haureutta varten, vaan Herraa varten, ja Herra ruumista varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Jumala, joka herätti kuolleista Herran, on herättävä meidätkin voimallaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Ettekö tiedä, että teidän ruumiinne ovat Kristuksen jäseniä? Ottaisinko siis Kristuksen jäsenet ja tekisin ne porton jäseniksi? Ei ikinä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Vai ettekö tiedä, että joka yhtyy porttoon, tulee yhdeksi ruumiiksi hänen kanssaan? Onhan sanottu: \"Ne kaksi tulevat yhdeksi lihaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Mutta joka yhtyy Herraan, on yksi henki [hänen kanssaan].');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Paetkaa haureutta. Kaikki muu synti, mitä ikinä ihminen tekee, on ruumiin ulkopuolella, mutta haureuden harjoittaja tekee syntiä omaa ruumistaan vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Vai ettekö tiedä, että teidän ruumiinne on Pyhän Hengen temppeli, joka Henki teissä on ja joka teillä on Jumalalta, ja ettette ole itsenne omat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Sillä te olette kalliisti ostetut. Kirkastakaa siis Jumala ruumiissanne ja hengessänne, jotka ovat Jumalan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Mutta mitä siihen tulee, mistä minulle kirjoititte, niin hyvä on miehen olla menemättä avioon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'mutta haureuden välttämiseksi olkoon kullakin miehellä oma vaimonsa ja kullakin naisella aviomiehensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Täyttäköön mies suosiollisesti aviovelvollisuutensa vaimoaan kohtaan, ja samoin vaimo miestään kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Vaimon ruumis ei ole hänen omassa, vaan hänen miehensä vallassa. Samoin ei miehenkään ruumis ole hänen omassa, vaan vaimon vallassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Älkää vetäytykö pois toisistanne, paitsi ehkä keskinäisestä sopimuksesta ajaksi, niin että teillä olisi aikaa rukoukseen ja sitten taas tulisitte yhteen, ettei saatana kiusaisi teitä, kun ette voi itseänne hillitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Mutta tämän sanon myönnytyksenä, en käskynä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Haluan kaikkien ihmisten olevan niin kuin minäkin, mutta kullakin on oma armolahjansa Jumalalta, yhdellä näin, toisella noin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Mutta naimattomille ja leskille sanon: heille on hyvä, jos pysyvät sellaisina kuin minäkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Mutta jos eivät voi itseään hillitä, menkööt naimisiin, sillä parempi on avioitua kuin palaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Mutta naimisissa oleville julistan, en minä, vaan Herra, ettei vaimo saa erota miehestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'Mutta jos hän eroaa, pysyköön naimattomana tai sopikoon miehensä kanssa, eikä mies saa hylätä vaimoaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Mutta muille sanon minä, ei Herra: jos jollakulla veljellä on vaimo, joka ei usko, ja tämä suostuu asumaan hänen kanssaan, älköön mies hylätkö häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'Samoin älköön vaimokaan, jos hänellä on mies, joka ei usko, ja tämä suostuu asumaan hänen kanssaan, hylätkö miestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Sillä mies, joka ei usko, on pyhitetty vaimonsa kautta, ja vaimo, joka ei usko, on pyhitetty miehensä kautta. Muutenhan teidän lapsenne olisivat saastaisia, mutta nyt he ovat pyhiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Mutta jos se, joka ei usko, eroaa, erotkoon. Veli ja sisar eivät ole sellaisissa tapauksissa orjuutetut, sillä rauhaan on Jumala teidät kutsunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Sillä mistä tiedät, vaimo, voitko pelastaa miehesi? Tai mistä tiedät, mies, voitko pelastaa vaimosi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Vaeltakoon vain kukin sen mukaan, millaisen osan Herra on hänelle antanut, ja siinä asemassa, missä Jumala on hänet kutsunut. Näin säädän kaikissa seurakunnissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Jos joku on kutsuttu ympärileikattuna, älköön pyrkikö ympärileikkaamattomaksi. Jos joku on kutsuttu ympärileikkaamattomana, älköön ympärileikkauttako itseään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Ei ympärileikkaus ole mitään, eikä ympärileikkaamattomuus ole mitään, vaan Jumalan käskyjen pitäminen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Pysyköön kukin siinä kutsumuksessa, missä hänet on kutsuttu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Jos olet kutsuttu orjana, älä siitä murehdi. – Mutta jos voit päästä vapaaksi, käytä tilaisuutta ennemmin hyväksesi. –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Sillä se, joka on kutsuttu orjana Herrassa, on Herran vapautettu. Samoin vapaana kutsuttu on Kristuksen orja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Te olette kalliisti ostetut, älkää olko ihmisten orjia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Pysyköön kukin, veljet, Jumalan edessä siinä asemassa, missä hänet on kutsuttu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Mutta neitsyistä minulla ei ole Herran käskyä, vaan lausun mielipiteeni niin kuin se, joka on Herralta saanut sen laupeuden, että hän on luotettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Olen siis sitä mieltä, että lähestyvän ahdingon tähden jokaisen on hyvä pysyä siten kuin on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Jos olet sidottu vaimoon, älä etsi eroa. Jos et ole sidottu vaimoon, älä etsi vaimoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Mutta jos menetkin naimisiin, et tee syntiä. Jos neitsyt menee naimisiin, hänkään ei tee syntiä. Mutta ne, jotka niin tekevät, joutuvat kärsimään ruumiillista vaivaa, ja siitä minä tahtoisin teidät säästää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Mutta sen sanon, veljet: aika on lyhennetty. Olkoot tästedes nekin, joilla on vaimot, kuin heillä ei heitä olisi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'ja ne, jotka itkevät, kuin eivät itkisi, ja ne, jotka iloitsevat, kuin eivät iloitsisi, ja ne, jotka ostavat, kuin eivät omistaisi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'ja ne, jotka tätä maailmaa hyödykseen käyttävät, kuin eivät sitä käyttäisi, sillä tämän maailman olemus on katoamassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Haluan, että olisitte vapaita huolista. Naimaton mies huolehtii siitä, mikä on Herran ja kuinka olisi Herralle mieliksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Mutta nainut huolehtii ajallisista, kuinka olisi vaimolleen mieliksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'On eroa vaimon ja neitsyen välillä. Vaimo, jolla ei ole enää miestä, ja neitsyt huolehtivat siitä, mikä on Herran, että olisivat pyhät sekä ruumiin että hengen puolesta. Mutta naimisissa oleva huolehtii ajallisista, kuinka olisi miehelleen mieliksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Tämän sanon teidän omaksi hyödyksenne, en heittääkseni ansaa kaulaanne, vaan sitä varten, että eläisitte säädyllisesti ja pysyisitte häiriintymättä Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Mutta jos joku arvelee olevansa armoton tytärtään kohtaan, joka on täydessä naimaiässä, ja jos kerran sen pitää tapahtua, niin tehköön, kuten tahtoo. Hän ei tee syntiä. Menkööt naimisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Se taas, joka pysyy sydämessään lujana eikä ole minkään pakon alainen, vaan voi noudattaa omaa tahtoaan ja on sydämessään päättänyt pitää tyttärensä naimattomana, tekee hyvin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Siis, joka naittaa tyttärensä, tekee hyvin, ja joka ei naita, tekee paremmin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Vaimo on sidottu lakiin, niin kauan kuin hänen miehensä elää, mutta jos mies nukkuu pois, hän on vapaa menemään naimisiin, kenen kanssa tahtoo, mutta vain Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Mutta hän on onnellisempi, jos pysyy sillä tavoin kuin on. Se on minun mielipiteeni, ja luulen, että minullakin on Jumalan Henki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Mitä sitten epäjumalille uhrattuun tulee, tiedämme, että meillä kaikilla on tieto. Tieto paisuttaa, mutta rakkaus rakentaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Jos joku luulee jotakin tietävänsä, hän ei vielä tiedä, kuten tulee tietää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Mutta sen, joka rakastaa Jumalaa, Jumala tuntee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'Mitä nyt epäjumalille uhratun syömiseen tulee, tiedämme, ettei maailmassa ole yhtään epäjumalaa ja ettei ole muuta Jumalaa kuin yksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Sillä vaikka onkin niin sanottuja jumalia, olipa heitä sitten taivaassa tai maan päällä, kuten onkin paljon jumalia ja herroja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'meillä on kuitenkin ainoastaan yksi Jumala, Isä, josta kaikki on ja jota varten me olemme, ja yksi Herra, Jeesus Kristus, jonka kautta kaikki on, myös me hänen kauttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Mutta kaikilla ei ole tätä tietoa, vaan epäjumalaan sidotulla omallatunnolla muutamat vielä nytkin syövät uhrilihaa pitäen sitä uhrina epäjumalille, ja heidän heikko omatuntonsa tahraantuu siitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Mutta ruoka ei lähennä meitä Jumalaan. Jos syömme, emme siitä hyödy. Jos olemme syömättä, emme siitä vahingoitu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Katsokaa kuitenkin, ettei tämä valtanne koidu heikoille loukkaukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Sillä jos joku näkee sinun, jolla on tieto, aterioivan epäjumalan huoneessa, eikö hänen omatuntonsa, kun hän on heikko, vahvistu epäjumalille uhratun syömiseen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'Sinun tietoosi vedoten turmeltuu heikko veli, jonka tähden Kristus on kuollut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Mutta kun te näin teette syntiä veljiä vastaan ja haavoitatte heidän heikkoa omaatuntoaan, teette syntiä Kristusta vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Sen tähden, jos ruoka on lankeemukseksi veljelleni, en ikinä enää syö lihaa, etten olisi lankeemukseksi veljelleni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Enkö ole apostoli? Enkö ole vapaa? Enkö ole nähnyt Jeesusta Kristusta, meidän Herraamme? Ettekö te ole minun tekoni Herrassa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Jos en olekaan apostoli muille, olen ainakin teille, sillä te olette apostolinvirkani sinetti Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Tämä on puolustukseni niitä vastaan, jotka asettuvat minua tutkimaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Eikö meillä ole oikeus syödä ja juoda?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Eikö meillä ole oikeus kuljettaa mukanamme vaimoa, sisarta, kuten muillakin apostoleilla, Herran veljillä ja Keefaalla?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Vai ainoastaanko minulla ja Barnabaalla ei ole oikeutta olla tekemättä työtä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Kuka tekee koskaan sotapalvelusta omalla kustannuksellaan? Kuka istuttaa viinitarhan, eikä syö sen hedelmää? Tai kuka kaitsee karjaa, eikä nauti karjansa maitoa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Puhunko tätä vain ihmisten tavalla? Eikö lakikin sano samaa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Onhan Mooseksen laissa kirjoitettuna: \"Älä sido puivan härän suuta.\" Eihän Jumala häristä näin huolta pitäne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Eikö hän sano sitä kaiketikin meidän tähtemme? Meidän tähtemmehän on kirjoitettu, että kyntäjän tulee kyntää toivossa ja puivan puida osansa saamisen toivossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Jos me olemme kylväneet teille hengellistä hyvää, onko paljon, jos me niitämme teiltä aineellista?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Jos muilla on teihin tällainen oikeus, eikö paljoa enemmän meillä? Mutta emme ole käyttäneet tätä oikeutta, vaan kestämme kaiken, ettemme panisi mitään estettä Kristuksen evankeliumille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Ettekö tiedä, että ne, jotka hoitavat pyhäkön toimia, saavat ravintonsa pyhäköstä, ja jotka ovat asetetut uhrialttarin palvelukseen, saavat osansa silloin kuin alttarikin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Samoin myös Herra on säätänyt, että evankeliumin julistajien tulee saada evankeliumista elatuksensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Mutta minä en ole käyttänyt hyväkseni ainoatakaan näistä oikeuksistani. Enkä kirjoitakaan tätä siinä mielessä, että niitä sovitettaisiin minuun, sillä minun olisi parempi mieluummin kuolla, kuin että joku tekisi tyhjäksi kerskaukseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Sillä jos julistan evankeliumia, minulla ei ole siitä kerskaamista, minun täytyy se tehdä. Voi minua, ellen evankeliumia julista!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Sillä jos teen sitä halusta, minulla on palkka. Mutta jos en tee sitä halusta, on huoneenhaltijan virka kuitenkin minulle uskottu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Mikä siis on palkkani? Se, että kun julistan Kristuksen evankeliumia, teen sen ilmaiseksi, niin etten käytä evankeliumin minulle antamaa oikeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Sillä vaikka olen riippumaton kaikista, olen tehnyt itseni kaikkien palvelijaksi voittaakseni niin monta kuin suinkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'Olen ollut juutalaisille kuin juutalainen voittaakseni juutalaisia, lain alaisille kuin lain alainen voittaakseni lain alaiset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'ilman lakia oleville kuin olisin ilman lakia – vaikka en ole ilman Jumalan lakia, vaan olen Kristuksen laissa – voittaakseni ne, jotka ovat ilman lakia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Heikoille olen ollut heikko voittaakseni heikot. Kaikille olen ollut kaikkea pelastaakseni edes muutamia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Mutta kaiken teen evankeliumin tähden, että minäkin tulisin siitä osalliseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Ettekö tiedä, että ne, jotka stadionilla juoksevat, tosin kaikki juoksevat, mutta yksi saa voittopalkinnon? Juoskaa niin kuin se, että sen saavuttaisitte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Mutta jokainen kilpailija noudattaa itsehillintää kaikessa, he saadakseen katoavan seppeleen, mutta me katoamattoman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Minä en siis juokse umpimähkään enkä nyrkkeile kuin ilmaan huitoen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'vaan kuritan ruumistani ja orjuutan sitä, etten minä, joka muille saarnaan, itse ehkä joutuisi hylätyksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'En tahdo, veljet, pitää teitä tietämättöminä siitä, että isämme olivat kaikki pilven alla ja kulkivat kaikki meren halki,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'saivat kaikki kasteen Moosekseen pilvessä ja meressä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'söivät kaikki samaa hengellistä ruokaa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'ja joivat kaikki samaa hengellistä juomaa. Sillä he joivat hengellisestä kalliosta, joka heitä seurasi, ja se kallio oli Kristus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Mutta useimpiin heistä Jumala ei mieltynyt, koska he saivat surmansa erämaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Tämä tapahtui varoittavaksi esimerkiksi meille, ettemme himoitsisi pahaa, kuten he himoitsivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Älkää myöskään olko epäjumalanpalvelijoita kuten muutamat heistä, kuten on kirjoitettu: \"Kansa istui syömään ja juomaan, ja he nousivat karkeloimaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Älkäämme myöskään harjoittako haureutta, niin kuin muutamat heistä harjoittivat haureutta, ja heitä kaatui yhtenä päivänä kaksikymmentä kolme tuhatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Älkäämme myöskään kiusatko Kristusta, niin kuin muutamat heistä kiusasivat ja saivat käärmeiltä surmansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Älkääkä napisko, niin kuin muutamat heistä napisivat ja saivat surmansa tuhoojalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Mutta kaikki nämä, mitä heille tapahtui, ovat esikuvia, ja ne on kirjoitettu varoitukseksi meille, joille maailmanaikojen loppukausi on tullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Sen tähden, joka luulee seisovansa, katsokoon, ettei kaadu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Teitä ei ole kohdannut muu kuin inhimillinen kiusaus. Mutta Jumala on uskollinen: hän ei salli teitä kiusattavan yli voimienne, vaan kiusauksen ohella hän valmistaa myös pääsyn siitä, että voitte sen kestää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Sen tähden, rakkaani, paetkaa epäjumalanpalvelusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Puhun kuin viisaille. Arvioikaa itse, mitä sanon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Siunauksen malja, jonka siunaamme, eikö se ole osallisuus Kristuksen vereen? Se leipä, jonka murramme, eikö se ole osallisuus Kristuksen ruumiiseen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Koska leipä on yksi, me monet olemme yksi ruumis, sillä olemme kaikki yhdestä leivästä osallisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Katsokaa Israelia lihan mukaan. Eivätkö ne, jotka syövät uhreja, ole uhrialttarista osallisia?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Mitä siis sanon? Niinkö, että epäjumala on jotakin, tai että epäjumalanuhri on jotakin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Ei, vaan että sen, mitä pakanat uhraavat, he uhraavat riivaajille eivätkä Jumalalle, mutta minä en tahdo teidän olevan osallisia riivaajista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Ette voi juoda Herran maljasta ja riivaajien maljasta, ette voi olla osallisia Herran pöydästä ja riivaajien pöydästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Vai tahdommeko herättää Herran kiivauden? Emme kaiketi ole häntä vahvempia?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Kaikki on minulle luvallista, mutta ei kaikki ole hyödyksi. Kaikki on minulle luvallista, mutta ei kaikki rakenna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Älköön kukaan etsikö omaansa, vaan toisen etua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Syökää kaikkea, mitä lihatorilla myydään, kyselemättä mitään omantunnon tähden,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'sillä: \"Herran on maa ja kaikki, mitä siinä on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Jos joku uskosta osaton kutsuu teidät ja haluatte mennä, niin syökää kaikkea, mitä eteenne pannaan, kyselemättä mitään omantunnon tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Mutta jos joku sanoo teille: \"Tämä on epäjumalanuhria\", älkää syökö sitä hänen tähtensä, joka sen ilmaisi, eikä omantunnon tähden. Maa on Herran ja kaikki, mitä siinä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'En puhu sinun itsesi omastatunnosta, vaan tuon toisen, sillä miksi toisen omatunto saisi tuomita minun vapauteni?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Jos minä nautin sen kiitoksella, miksi minua pilkataan siitä, mistä minä kiitän?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Söittepä siis tai joitte tai teitte mitä hyvänsä, tehkää kaikki Jumalan kunniaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Älkää olko pahennukseksi juutalaisille, älkää kreikkalaisille älkääkä Jumalan seurakunnalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'kuten minäkin olen kaikille kaikessa mieliksi enkä etsi omaa hyötyäni, vaan monien hyötyä, että he pelastuisivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Olkaa minun seuraajiani, kuten minäkin olen Kristuksen seuraaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Kiitän teitä, että muistatte minua kaikessa ja pidätte kiinni opetuksistani sellaisina, kuin olen ne teille antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Mutta tahdon teidän tietävän, että Kristus on jokaisen miehen pää ja että mies on vaimon pää ja että Jumala on Kristuksen pää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Jokainen mies, joka rukoilee tai profetoi pää peitettynä, häpäisee päänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Mutta jokainen vaimo, joka rukoilee tai profetoi pää peittämättömänä, häpäisee päänsä, sillä se on aivan sama, kuin jos hänen päänsä olisi ajettu paljaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Sillä jos vaimo ei verhoa päätään, leikatkoon hiuksensakin. Mutta koska on häpeäksi vaimolle leikata tai ajaa hiuksensa, peittäköön päänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Miehen ei tule peittää päätään, koska hän on Jumalan kuva ja kunnia. Mutta vaimo on miehen kunnia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Sillä mies ei ole vaimosta, vaan vaimo miehestä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'eikä miestä luotu vaimoa varten, vaan vaimo miestä varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Sen tähden vaimon tulee pitää päässään vallan merkkiä enkelien tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Herrassa ei ole kuitenkaan vaimoa ilman miestä eikä miestä ilman vaimoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Sillä niin kuin vaimo on miehestä, samoin myös mies on vaimon kautta, mutta kaikki on Jumalasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Päättäkää itse: sopiiko vaimon rukoilla Jumalaa pää peittämättömänä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Eikö itse luontokin opeta teille, että jos miehellä on pitkät hiukset, se on hänelle häpeäksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'ja että jos vaimolla on pitkät hiukset, se on hänelle kunniaksi? Sillä ovathan hiukset annetut hänelle hunnuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Mutta jos joku haluaa kiistellä, niin meillä ei ole sellaista tapaa eikä Jumalan seurakunnilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Mutta tätä käskiessäni en kiitä sitä, että kokoontumisenne ei tee teitä paremmiksi, vaan pahemmiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Sillä ensiksikin olen kuullut, että kun kokoonnutte seurakunnassa, teillä on eriseuroja keskuudessanne, ja osittain sen uskonkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Täytyyhän teidän keskuudessanne olla puolueitakin, että koetuksen kestävät tulisivat ilmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Kun te näin kokoonnutte yhteen, se ei ole Herran illallisen nauttimista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'sillä syömään ruvettaessa kukin rientää ottamaan eteensä oman illallisensa, ja niin toinen on nälissään ja toinen juovuksissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Eikö teillä sitten ole muita huoneita, niissä syödäksenne ja juodaksenne? Vai halveksitteko Jumalan seurakuntaa ja tahdotteko häväistä niitä, joilla ei ole mitään? Mitä teille sanoisin? Tulisiko minun teitä tästä kiittää? En kiitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Sillä minä olen saanut Herralta sen, minkä myös olen teille tiedoksi antanut, että Herra Jeesus sinä yönä, jona hänet kavallettiin, otti leivän,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'kiitti, mursi ja sanoi: \"Tämä on minun ruumiini, teidän edestänne murrettu. Tehkää tämä minun muistokseni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Samoin hän otti myös maljan aterian jälkeen ja sanoi: \"Tämä malja on uusi liitto minun veressäni. Niin usein kuin te juotte, tehkää se minun muistokseni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Sillä niin usein kuin te syötte tätä leipää ja juotte tämän maljan, te julistatte Herran kuolemaa, siihen asti kuin hän tulee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Sen tähden se, joka kelvottomasti syö tätä leipää tai juo Herran maljan, on oleva syyllinen Herran ruumiiseen ja vereen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Koetelkoon siis ihminen itsensä, ja niin syököön tätä leipää ja juokoon tästä maljasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'sillä joka syö ja juo kelvottomasti erottamatta Herran ruumista muusta, syö ja juo itselleen tuomion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Sen tähden onkin teidän joukossanne paljon heikkoja ja sairaita, ja monet ovat nukkuneet [pois].');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Mutta jos tutkisimme itseämme, meitä ei tuomittaisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Mutta kun meitä tuomitaan, se on meille Herran kuritusta, ettei meitä maailman kanssa kadotukseen tuomittaisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Sen tähden, veljeni, kun kokoonnutte yhdessä aterioimaan, odottakaa toisianne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Jos jollakulla on nälkä, syököön kotonaan, jotta ette kokoontuisi tuomioksenne. Muista seikoista säädän, kun tulen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Mutta hengellisistä lahjoista, veljet, en tahdo pitää teitä tietämättöminä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Te tiedätte, että kun olitte pakanoita, teitä ikään kuin ajamalla vietiin mykkien epäjumalien luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Sen tähden teen teille tiettäväksi, ettei kukaan, joka puhuu Jumalan Hengessä, sano: \"Jeesus olkoon kirottu\", ja ettei kukaan voi sanoa: \"Jeesus on Herra\", paitsi Pyhässä Hengessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Armolahjat ovat erilaisia, mutta Henki on sama.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'Palvelusvirat ovat erilaisia, mutta Herra on sama.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'Voimavaikutukset ovat erilaisia, mutta Jumala, joka kaiken kaikissa vaikuttaa, on sama.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Mutta kullekin annetaan Hengen ilmoitus yhteiseksi hyödyksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Niinpä toiselle annetaan Hengen kautta viisauden sanat, toiselle tiedon sanat saman Hengen mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'toiselle usko samassa Hengessä, toiselle taas terveeksi tekemisen armolahjoja siinä yhdessä Hengessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'toiselle voimateot, toiselle profetoiminen, toiselle henkien erottaminen, toiselle eri kielillä puhuminen, toiselle taas kielien selittäminen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Mutta kaiken tämän vaikuttaa yksi ja sama Henki, jakaen kullekin erikseen, niin kuin tahtoo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Sillä niin kuin ruumis on yksi ja siinä on monta jäsentä, mutta kaikki ruumiin jäsenet, vaikka niitä on monta, ovat yksi ruumis, niin on Kristuskin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Sillä me olemme kaikki kastetut yhdessä Hengessä yhdeksi ruumiiksi, olimmepa juutalaisia tai kreikkalaisia, orjia tai vapaita, ja kaikki olemme saaneet juoda samaa Henkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Sillä eihän ruumiskaan ole yksi jäsen, vaan monta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Jos jalka sanoisi: \"Koska en ole käsi, en kuulu ruumiiseen\", se ei silti olisi ruumiiseen kuulumaton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'Jos korva sanoisi: \"Koska en ole silmä, en kuulu ruumiiseen\", se ei silti olisi ruumiiseen kuulumaton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Jos koko ruumis olisi silmänä, missä sitten olisi kuulo? Jos taas kokonaan kuulona, missä silloin hajuaisti?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Mutta nyt Jumala on asettanut jäsenet, jokaisen niistä, ruumiiseen, niin kuin on tahtonut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Vaan jos ne kaikki olisivat yhtenä jäsenenä, missä sitten olisi ruumis?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Nytpä onkin monta jäsentä, mutta vain yksi ruumis.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Silmä ei voi sanoa kädelle: \"En tarvitse sinua\", eikä myöskään pää jaloille: \"En tarvitse teitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Päinvastoin ne ruumiin jäsenet, jotka näyttävät olevan heikompia, ovat välttämättömiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'Ne ruumiin jäsenet, jotka meistä ovat vähemmän kunniakkaita, verhoamme sitä kunniallisemmin, ja niitä, joita häpeämme, sitä häveliäämmin peitämme,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'mutta ne, joita emme häpeä, eivät sitä tarvitse. Mutta Jumala on liittänyt ruumiin yhteen niin, että antoi halvempiarvoiselle suuremman kunnian,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'ettei ruumiissa olisi eripuraa, vaan että jäsenet pitäisivät yhtäläistä huolta toisistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'Jos yksi jäsen kärsii, kaikki jäsenet kärsivät sen kanssa, tai jos jollekulle jäsenelle annetaan kunnia, kaikki jäsenet iloitsevat sen kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Mutta te olette Kristuksen ruumis ja kukin osaltanne hänen jäseniään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'Niinpä Jumala asetti seurakuntaan ensiksi apostoleja, toiseksi profeettoja, kolmanneksi opettajia, sitten voimatekoja, sitten armolahjoja parantaa tauteja, avustaa, hallita ja puhua kielillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Eivät suinkaan kaikki ole apostoleja? Eivät kaikki profeettoja? Eivät kaikki opettajia? Eiväthän kaikki tee voimatekoja?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Eihän kaikilla ole parantamisen armolahjoja? Eiväthän kaikki puhu kielillä? Eiväthän kaikki niitä selitä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Pyrkikää osallisiksi parhaimmista armolahjoista. Vielä minä osoitan teille suurenmoisen tien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Jos puhuisin ihmisten ja enkelien kielillä, mutta minulla ei olisi rakkautta, olisin kumiseva vaski tai helisevä symbaali.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'Jos minulla olisi profetia ja tietäisin kaikki salaisuudet ja kaiken tiedon, ja jos minulla olisi kaikki usko, että voisin siirtää vuoria, mutta minulla ei olisi rakkautta, en olisi mikään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'Jos jakelisin kaiken omaisuuteni, ja jos antaisin ruumiini poltettavaksi, mutta minulla ei olisi rakkautta, en siitä mitään hyötyisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Rakkaus on pitkämielinen, rakkaus on lempeä. Rakkaus ei kadehdi, ei kersku, ei pöyhkeile,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'ei käyttäydy sopimattomasti, ei etsi omaansa, ei ärsyynny, ei muistele pahaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'ei iloitse vääryydestä, vaan iloitsee yhdessä totuuden kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Kaikki se kestää, kaikki se uskoo, kaikki se toivoo, kaikki se kärsii.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Rakkaus ei koskaan häviä. Mutta profetiat loppuvat, ja kielet lakkaavat, ja tieto katoaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Sillä tietomme on osittaista, ja profetoimisemme on osittaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'Mutta kun tulee se, mikä on täydellistä, katoaa se, mikä on osittaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Kun olin lapsi, puhuin kuin lapsi, minulla oli lapsen mieli, ja ajattelin kuin lapsi. Kun tulin mieheksi, hylkäsin sen, mikä lapsen on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Sillä nyt näemme kuin kuvastimesta arvoituksen tavoin, mutta silloin kasvoista kasvoihin. Nyt minulla on osittainen tieto, mutta silloin minulla on oleva täydellinen tieto, kuten minut itsenikin täysin tunnetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Niin pysyvät nyt usko, toivo ja rakkaus, nämä kolme, mutta suurin niistä on rakkaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Tavoitelkaa rakkautta ja olkaa innokkaita saamaan hengellisiä lahjoja, mutta etenkin profetoimaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Sillä kielellä puhuva ei puhu ihmisille, vaan Jumalalle. Häntä näet ei kuuntele kukaan, sillä hän puhuu salaisuuksia hengessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Mutta profetoiva puhuu ihmisille rakennukseksi, kehotukseksi ja lohdutukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Kielellä puhuva rakentaa itseään, mutta profetoiva rakentaa seurakuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Soisin teidän kaikkien puhuvan kielillä, mutta vielä mieluummin soisin teidän profetoivan. Sillä profetoiva on suurempi kuin kielillä puhuva, ellei tämä samalla selitä, niin että seurakunta rakentuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Jos nyt, veljet, tulisin luoksenne kielillä puhuen, minkä hyödyn sillä toisin, ellen puhuisi teille antaen ilmoituksen, tiedon, profetian tai opetuksen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Niinhän on elottomien soittimienkin laita, huilujen tai sitrojen: kuinka tiedetään, mitä huilulla tai sitralla soitetaan, elleivät ne soi toisistaan erottuvin sävelin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Niin ikään, jos torvi antaa epäselvän äänen, kuka valmistautuu taisteluun?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Samoin tekin: jos ette kielellänne saa esiin selvää puhetta, kuinka sellainen puhe tulee ymmärretyksi? Tehän puhutte tuuleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Maailmassa on monta eri kieltä, mutta mikään ei ole ilman merkitystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Mutta jos en tiedä sanojen merkitystä, olen puhujalle muukalainen, ja puhuja on minulle muukalainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Samoin tekin, koska tavoittelette hengellisiä lahjoja, pyrkikää seurakunnan rakennukseksi saamaan niitä runsaasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Sen tähden rukoilkoon se, joka puhuu kielellä, että hän osaisi selittää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Sillä jos rukoilen kielellä puhuen, henkeni kyllä rukoilee, mutta ymmärrykseni on hedelmätön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Kuinka siis on? Minun on rukoiltava hengelläni, mutta minun on rukoiltava myös ymmärrykselläni. Minun on veisattava kiitosta hengelläni, mutta minun on veisattava myös ymmärrykselläni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Sillä jos ylistät Jumalaa hengessä, kuinka oppimattoman paikalla istuva saattaa sanoa \"aamen\" sinun kiitokseesi, koska hän ei tiedä, mitä sanot?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Sinä tosin kiität hyvin, mutta toinen ei siitä rakennu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Kiitän Jumalaa, että puhun kielillä enemmän kuin kukaan teistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'Mutta seurakunnassa tahdon mieluummin puhua viisi sanaa ymmärrykselläni opettaakseni muitakin kuin kymmenentuhatta sanaa kielillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Veljet, älkää olko lapsia ymmärrykseltänne, vaan pahuudessa olkaa lapsia, mutta ymmärrykseltä olkaa täysi-ikäisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Laissa on kirjoitettuna: \"Vieraskielisten kautta ja vieraiden huulilla olen puhuva tälle kansalle, eivätkä he sittenkään minua kuuntele, sanoo Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Niinpä kielet eivät ole merkiksi uskoville, vaan uskosta osattomille, mutta profetia ei ole merkiksi uskosta osattomille, vaan uskoville.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Jos nyt koko seurakunta kokoontuisi yhteen ja kaikki puhuisivat kielillä ja sinne tulisi opetuksesta tai uskosta osattomia, eivätkö he sanoisi teidän olevan järjiltänne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Mutta jos kaikki profetoisivat ja joku uskosta osaton tai oppimaton tulisi sisään, kaikki nuhtelisivat häntä ja kaikki tutkisivat häntä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'ja hänen sydämensä salaisuudet tulisivat ilmi, ja niin hän kasvoilleen langeten rukoilisi Jumalaa ja julistaisi, että Jumala totisesti on teissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Kuinka siis on, veljet? Kun tulette yhteen, on jokaisella jotakin annettavaa: kenellä on virsi, kenellä opetus, kenellä ilmoitus, kuka puhuu kielellä, kuka selittää. Kaikki tapahtukoon rakennukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Jos joku puhuu kielellä, puhukoon kullakin kertaa vain kaksi tai enintään kolme, ja yksi kerrallaan, ja yksi selittäköön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Mutta jos ei ole selittäjää, niin olkoon vaiti seurakunnassa ja puhukoon itselleen ja Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Profeetoista saakoon kaksi tai kolme puhua, ja muut arvioikoot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Mutta jos joku toinen siinä istuva saa ilmoituksen, vaietkoon ensimmäinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Sillä te voitte kaikki profetoida, toinen toisenne jälkeen, että kaikki saisivat opetusta ja kaikki kehotusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'Profeettojen henget ovat profeetoille alistetut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'sillä Jumala ei ole epäjärjestyksen, vaan rauhan Jumala. Niin kuin kaikissa pyhien seurakunnissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'naiset olkoot vaiti teidänkin seurakunnissanne, sillä heidän ei ole lupa puhua, vaan olkoot alamaisia, kuten lakikin sanoo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Mutta jos he tahtovat oppia, kysykööt kotonaan omalta mieheltään, sillä häpeällistä on naisten puhua seurakunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Vai teistäkö Jumalan sana on lähtenyt? Vai ainoastaan teidänkö luoksenne se on tullut?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Jos joku luulee olevansa profeetta tai hengellinen, tietäköön, että mitä kirjoitan teille, se on Herran käsky.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Mutta jos joku ei sitä ymmärrä, olkoon ymmärtämättä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Sen tähden, veljeni, harrastakaa profetoimista älkääkä estäkö kielillä puhumista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Mutta kaikki tapahtukoon säädyllisesti ja järjestyksessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Veljet, ilmoitan teille sen evankeliumin, jonka teille julistin, jonka myös otitte vastaan ja jossa myös pysytte');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'ja jonka kautta myös pelastutte, jos pidätte siitä kiinni sen sanan mukaisena, jonka minä teille julistin, ellette ole turhaan uskoneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Sillä annoin teille ennen kaikkea tiedoksi sen, minkä itse olin saanut: että Kristus on kuollut meidän syntiemme tähden Kirjoitusten mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'ja että hänet haudattiin ja että hän nousi kuolleista kolmantena päivänä Kirjoitusten mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'ja että hän ilmestyi Keefaalle, sitten niille kahdelletoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Sen jälkeen hän ilmestyi yhdellä kertaa yli viidellesadalle veljelle, joista useimmat vielä nytkin ovat elossa, mutta muutamat ovat nukkuneet pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Sen jälkeen hän ilmestyi Jaakobille, sitten kaikille apostoleille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'Mutta kaikkein viimeiseksi hän ilmestyi minullekin, joka olen kuin keskosena syntynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Sillä minä olen apostoleista vähäisin enkä ole sen arvoinen, että minua apostoliksi kutsutaan, koska vainosin Jumalan seurakuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Mutta Jumalan armosta olen se, mikä olen, eikä hänen armonsa minua kohtaan ole ollut turha, vaan enemmän kuin he kaikki olen työtä tehnyt, en kuitenkaan minä, vaan Jumalan armo, joka on kanssani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Olinpa siis minä tai olivatpa nuo: tällä tavalla saarnaamme, ja näin te olette uskoneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Mutta jos Kristuksesta saarnataan, että hän on noussut kuolleista, kuinka eräät teistä sanovat, ettei kuolleiden ylösnousemusta ole?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Mutta jos ei ole kuolleiden ylösnousemusta, Kristuskaan ei ole noussut ylös.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'Mutta jos Kristus ei ole noussut ylös, turha on silloin meidän saarnamme, turha myös teidän uskonne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Silloin meidät myös havaitaan vääriksi Jumalan todistajiksi, koska olemme todistaneet Jumalaa vastaan, että hän herätti Kristuksen, jota hän ei ole herättänyt, jos kerran kuolleita ei herätetä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Sillä jos kuolleita ei herätetä, ei Kristustakaan ole herätetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'Mutta jos Kristusta ei ole herätetty, teidän uskonne on turha, ja te olette vielä synneissänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Silloinhan Kristuksessa nukkuneet olisivat kadotetut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Jos olemme panneet toivomme Kristukseen ainoastaan tätä elämää koskien, olemme kaikkia muita ihmisiä kurjemmat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Mutta nytpä Kristus on noussut kuolleista, ensi hedelmänä kuoloon nukkuneista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Sillä koska kuolema on tullut ihmisen kautta, on myös kuolleiden ylösnousemus tullut ihmisen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Sillä niin kuin kaikki kuolevat Aadamissa, niin myös kaikki tehdään eläviksi Kristuksessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'mutta jokainen vuorollaan: ensi hedelmänä Kristus, sitten Kristuksen omat hänen tulemuksessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'Sitten tulee loppu, kun hän antaa valtakunnan Jumalalle ja Isälle kukistettuaan kaiken hallituksen, kaiken vallan ja voiman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Sillä hänen pitää hallita \"siihen asti, kunnes hän on pannut kaikki viholliset jalkojensa alle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'Vihollisista viimeisenä kukistetaan kuolema.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Sillä: \"kaikki hän on alistanut hänen jalkojensa alle.\" Mutta kun hän sanoo: \"kaikki on alistettu\", ei tietenkään ole alistettu se, joka on alistanut kaiken hänen alleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Kun kaikki on alistettu Pojan valtaan, silloin itse Poikakin alistetaan sen valtaan, joka on alistanut hänen valtaansa kaiken, että Jumala olisi kaikki kaikissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Mitä muuten ne, jotka kastattavat itsensä vainajien yläpuolella, sillä saavat aikaan? Jos kuolleet eivät herää, miksi nämä sitten kastattavat itsensä heidän yläpuolellaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Miksi mekin olemme joka hetki vaarassa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Joka päivä olen kuoleman vaarassa, niin totta kuin te, veljet, olette minun kerskaukseni Kristuksessa Jeesuksessa, meidän Herrassamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Jos ihmisten tavoin olen taistellut petojen kanssa Efesossa, mitä hyötyä minulle siitä on? Jos kuolleita ei herätetä, niin: \"syökäämme ja juokaamme, sillä huomenna kuolemme.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Älkää eksykö. \"Huono seura hyvät tavat turmelee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Raitistukaa oikealla tavalla älkääkä syntiä tehkö, sillä niitä on, joilla ei ole tietoa Jumalasta. Teidän häpeäksenne tämän sanon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Mutta joku ehkä kysyy: \"Millä tavoin kuolleet nousevat ylös, ja millaisessa ruumiissa he tulevat?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Sinä typerä, se, minkä kylvät, ei virkoa eloon, ellei se kuole!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'Kun kylvät, et kylvä koko tulevaa ruumista [kasvia], vaan pelkän jyvän, vehnän jyvän tai muun minkä tahansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Mutta Jumala antaa sille ruumiin [varren], sellaisen kuin tahtoo, ja kullekin siemenelle sen oman ruumiin [varren].');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Ei kaikki liha ole samaa lihaa, vaan toista on ihmisten, toista taas karjan liha, toista on lintujen liha, toista kalojen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'On taivaallisia ruumiita [taivaankappaleita] ja maallisia ruumiita. Mutta toinen on taivaallisten kirkkaus, toinen taas maanpäällisten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Toinen on auringon kirkkaus, toinen kuun kirkkaus ja toinen tähtien kirkkaus, ja toinen tähti eroaa toisesta kirkkaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Samalla tavalla on myös kuolleiden ylösnousemus: kylvetään katoavaisuudessa, nousee katoamattomuudessa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'kylvetään häpeässä, nousee kunniassa; kylvetään heikkoudessa, nousee voimassa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'kylvetään sielullinen ruumis, nousee hengellinen ruumis. Jos kerran on sielullinen ruumis, on myös hengellinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'Näinhän on myös kirjoitettu: \"Ensimmäisestä ihmisestä, Aadamista, tuli elävä sielu\", viimeisestä Aadamista eläväksi tekevä henki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Mutta mikä on hengellistä, se ei ole ensimmäinen, vaan se, mikä on sielullista, on ensimmäinen. Sitten on se, mikä on hengellistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Ensimmäinen ihminen oli maasta, maan tomusta, toinen ihminen, Herra, on taivaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Millaista tomu on, sellaisia ovat myös ne, jotka ovat tomusta, ja millainen taivaallinen on, sellaisia ovat myös taivaalliset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'Niin kuin olemme kantaneet itsessämme tomun kuvaa, tulemme myös kantamaan itsessämme taivaallisen kuvaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Mutta tämän sanon, veljet, ettei liha ja veri voi periä Jumalan valtakuntaa, eikä katoavaisuus peri katoamattomuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Katso, sanon teille salaisuuden: emme kaikki kuolemaan nuku, mutta kaikki muutumme,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'yhtäkkiä, silmänräpäyksessä, viimeisen torven soidessa. Sillä torvi soi, ja kuolleet nousevat katoamattomina, ja muutumme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Sillä tämän katoavaisen pitää pukeutua katoamattomuuteen, ja tämän kuolevaisen pitää pukeutua kuolemattomuuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Mutta kun tämä katoavainen pukeutuu katoamattomuuteen ja tämä kuolevainen pukeutuu kuolemattomuuteen, silloin toteutuu se sana, joka on kirjoitettu: \"Kuolema on nielty voitossa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, '\"Kuolema, missä on sinun piikkisi? Helvetti, missä on sinun voittosi?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Mutta kuoleman piikki on synti, ja synnin voima on laki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Mutta kiitos olkoon Jumalan, joka antaa meille voiton meidän Herramme Jeesuksen Kristuksen kautta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Sen tähden, rakkaat veljeni, olkaa lujat, järkähtämättömät ja aina innokkaat Herran työssä tietäen, että vaivannäkönne ei ole turhaa Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Mitä tulee keräykseen pyhiä varten, tehkää tekin samalla tavoin, kuin määräsin Galatian seurakunnille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Viikon ensimmäisenä päivänä pankoon jokainen teistä kotonaan jotakin talteen menestymisensä mukaan, ettei keräyksiä tehtäisi vasta sitten, kun tulen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Mutta kun olen saapunut, lähetän hyväksymänne henkilöt saatekirjeet mukanaan viemään rakkaudenlahjanne Jerusalemiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'ja jos asia on sen arvoinen, että minäkin lähden, heidän tulee lähteä kanssani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Tulen luoksenne kuljettuani läpi Makedonian, sillä kuljen Makedonian kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'Mutta teidän luonanne viivyn ehkä jonkin aikaa tai vietän talvenkin, että te sitten varustaisitte minut matkaan, minne matkustankin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Sillä en tahdo nyt vain ohimennen käydä teitä katsomassa, toivon näet saavani viipyä luonanne jonkin aikaa, jos Herra sallii.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Mutta Efesossa viivyn helluntaihin asti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'sillä minulle on avautunut ovi suureen ja hedelmälliseen työhön, ja vastustajia on paljon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Mutta jos Timoteus saapuu, katsokaa, että hän voi olla luonanne pelkäämättä, sillä Herran työtä hän tekee kuten minäkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Älköön siis kukaan häntä halveksiko, vaan varustakaa hänet rauhassa matkalle, että hän tulisi luokseni, sillä odotan häntä veljien kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Mitä veli Apolloon tulee, olen kovasti kehottanut häntä lähtemään veljien kanssa luoksenne. Mutta hän ei ole ollenkaan halukas lähtemään nyt, vaan tulee, kun hänelle sopii.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Valvokaa, pysykää lujina uskossa, olkaa miehuulliset, olkaa vahvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Kaikki, mitä teette, tapahtukoon rakkaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Mutta kehotan teitä, veljet: te tunnette Stefanaan perhekunnan ja tiedätte, että se on Akaian ensi hedelmä ja että he ovat antautuneet pyhien palvelukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'Olkaa tekin kuuliaisia heidän kaltaisilleen ja jokaiselle, joka tekee työtä ja näkee vaivaa heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Iloitsen Stefanaan, Fortunatoksen ja Akaikoksen tulosta tänne, koska he korvaavat teidän poissaolonne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'He ovat virkistäneet minun henkeäni niin kuin teidänkin. Antakaa siis sellaisille tunnustusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Aasian seurakunnat tervehtivät teitä. Monet tervehdykset Herrassa lähettävät teille Akylas ja Priskilla sekä heidän kodissaan kokoontuva seurakunta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Kaikki veljet lähettävät teille tervehdyksen. Tervehtikää toisianne pyhällä suudelmalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Tervehdys minulta, Paavalilta, omakätisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Jos joku ei rakasta Herraa Kristusta, hän olkoon kirottu! Maran ata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Herran Jeesuksen armo olkoon kanssanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Rakkauteni on teidän kaikkien kanssa Kristuksessa Jeesuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paavali, Jumalan tahdosta Kristuksen Jeesuksen apostoli, ja veli Timoteus Korinttossa olevalle Jumalan seurakunnalle sekä kaikille pyhille koko Akaiassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Kiitetty olkoon Herramme Jeesuksen Kristuksen Jumala ja Isä, laupeuden Isä ja kaiken lohdutuksen Jumala,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'joka lohduttaa meitä kaikessa ahdistuksessamme, että sillä lohdutuksella, jolla Jumala meitä itseämme lohduttaa, voisimme lohduttaa niitä, jotka kaikessa ahdistuksessa ovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Sillä samoin kuin Kristuksen kärsimykset tulevat osaksemme runsaina, samoin on myös lohdutuksemme runsas Kristuksen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Mutta jos olemme ahdistuksessa, se on teille lohdutukseksi ja pelastukseksi sekä vaikuttaa, että kestätte samat kärsimykset, joita mekin kärsimme, ja toivomme teistä on vahva. Jos taas saamme lohdutusta, tapahtuu sekin teille lohdutukseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'koska tiedämme, että niin kuin olette osallisia kärsimyksistä, olette samoin osallisia myös lohdutuksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Sillä emme tahdo, veljet, pitää teitä tietämättöminä siitä ahdistuksesta, jossa olimme Aasiassa, kuinka hyvin suuret, yli voimiemme käyvät, rasituksemme olivat, niin että olimme jo epätoivoisia hengestämmekin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'ja itse me jo luulimme olevamme kuolemaan tuomittuja, ettemme luottaisi itseemme, vaan Jumalaan, joka kuolleet herättää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'Hän pelasti meidät niin suuresta kuolemanvaarasta, ja yhä pelastaa, ja häneen olemme panneet toivomme, että hän vielä vastakin pelastaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'kun tekin autatte meitä esirukouksillanne, että monien joukosta meidän tähtemme lähtisi runsas kiitos siitä armolahjasta, joka on tullut osaksemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Sillä kerskauksemme on tämä: omantuntomme todistus siitä, että maailmassa ja varsinkin teidän luonanne olemme vaeltaneet rehellisesti ja Jumalan antamalla puhtaalla mielellä, emme lihallisessa viisaudessa, vaan Jumalan armossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Sillä eihän siinä, mitä teille kirjoitamme, ole muuta, kuin mikä siinä on luettavana ja minkä te myös ymmärrätte, ja toivon teidän loppuun asti ymmärtävän');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, '– niin kuin olette osaksi myös oppineet meitä ymmärtämään – että olemme teidän kerskauksenne, samoin kuin tekin meidän, Herramme Jeesuksen päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Tässä luottamuksessa tahdoin ensin tulla teidän tykönne, että saisitte vielä toisenkin armon suosiostani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'ja sitten teidän kauttanne matkustaa Makedoniaan, ja taas Makedoniasta palata teidän tykönne ja lähteä matkalle Juudeaan teidän varustamananne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Kun minulla siis oli tämä aikomus, enhän ole menetellyt kevytmielisesti? Vai päätänkö lihan mukaan, minkä päätän, niin että päätökseni on sekä \"on, on\", että \"ei, ei\"?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Mutta Jumala on uskollinen, niin ettei puheemme teille ole \"on\" ja \"ei.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Sillä Jumalan Poika, Kristus Jeesus, jota me, minä, Silas ja Timoteus, olemme keskellänne saarnanneet, ei tullut ollakseen \"on\" ja \"ei\", vaan hänessä tuli \"on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Sillä niin monta kuin on Jumalan lupausta, ne ovat hänessä kaikki \"on\". Sen tähden tulee hänen kauttaan myös niiden \"aamen\", Jumalalle kunniaksi meidän kauttamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Mutta se, joka lujittaa meidät yhdessä teidän kanssanne Kristukseen ja joka on voidellut meidät, on Jumala,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'joka myös on painanut meihin sinettinsä ja antanut Hengen vakuudeksi sydämiimme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Mutta minä kutsun Jumalan sieluni todistajaksi, että teitä säästääkseni en vielä tullut Korinttoon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'ei niin, että vallitsemme teidän uskoanne, vaan yhdessä edistämme teidän iloanne, sillä uskossa olette lujat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Mutta olin päättänyt mielessäni, etten taas tulisi luoksenne murhe mukanani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Sillä jos minä teen teidät murheellisiksi, minut voi tehdä iloiseksi vain se, jonka olen murehduttanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Juuri sen kirjoitin sitä varten, etten tullessani saisi murhetta niistä, joista minun piti saada iloa, koska minulla on teihin kaikkiin se luottamus, että minun iloni on kaikkien teidän ilonne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Sillä suuressa sydämen ahdistuksessa ja hädässä kirjoitin teille monin kyynelin, en sitä varten, että te tulisitte murheellisiksi, vaan että tuntisitte sen suuren rakkauden, joka minulla on teihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Mutta jos eräs on tuottanut murhetta, hän ei ole tuottanut murhetta minulle, vaan teille kaikille, jossakin määrin, etten liioittelisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Semmoiselle riittää se rangaistus, jonka hän on useimmilta saanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'niin että teidän ennemmin tulee antaa anteeksi ja lohduttaa, ettei hän ehkä menehtyisi suureen murheeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Sen tähden kehotan teitä, että päätätte osoittaa häntä kohtaan rakkautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'sillä sitä varten kirjoitinkin, että saisin tietää koetellun mielenne, oletteko kaikessa kuuliaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Mutta kenelle annatte jotakin anteeksi, sille minäkin. Sillä mitä minä olen anteeksi antanut – jos minulla on ollut jotakin anteeksiannettavaa – sen olen antanut anteeksi teidän tähtenne Kristuksen kasvojen edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'ettei saatana pääsisi meistä voitolle, sillä hänen juonensa eivät ole meille tuntemattomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Tultuani Trooaaseen julistamaan Kristuksen evankeliumia avautui minulle siihen ovi Herrassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'mutta en saanut lepoa hengessäni, kun en tavannut Tiitusta, veljeäni. Sen tähden hyvästelin heidät ja lähdin Makedoniaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Mutta kiitos olkoon Jumalan, joka aina kuljettaa meitä voittosaatossa Kristuksessa ja meidän kauttamme tuo joka paikassa ilmi hänen tuntemisensa tuoksun!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Sillä olemme Kristuksen tuoksu Jumalalle sekä pelastuvien että kadotukseen joutuvien joukossa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'näille tosin kuoleman haju kuolemaksi, mutta noille elämän tuoksu elämäksi. Ja kuka on tällaiseen kelvollinen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Sillä me emme ole kuin nuo monet, jotka myyskentelevät Jumalan sanaa, vaan puhtaasta mielestä, Jumalasta lähtevänä, Jumalan edessä, Kristuksessa puhumme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Alammeko taas suositella itseämme? Vai tarvitsemmeko, kuten muutamat, suosituskirjeitä teille tai teiltä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Te itse olette kirjeemme, joka on sydämeemme kirjoitettu ja jonka kaikki ihmiset tuntevat ja lukevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Sillä on selvää, että te olette Kristuksen kirje, palvelusvirkamme aikaansaama. Sitä ei ole kirjoitettu musteella, vaan elävän Jumalan Hengellä, ei kivitauluihin, vaan sydämen lihatauluihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Tämmöinen luottamus meillä on Kristuksen kautta Jumalaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'ei niin, että meillä itsellämme olisi kykyä ajatella jotakin, ikään kuin se tulisi meistä itsestämme, vaan se kyky, mikä meillä on, on Jumalasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'joka myös on tehnyt meidät kykeneviksi olemaan Uuden liiton palvelijoita, ei kirjaimen, vaan Hengen, sillä kirjain kuolettaa, mutta Henki tekee eläväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Mutta jos jo kuoleman virka, joka oli kaiverrettu kirjaimin kiviin, ilmeni kirkkaudessa, niin etteivät Israelin lapset voineet katsella Mooseksen kasvoja hänen kasvojensa kirkkauden tähden, joka oli katoavaista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'kuinka paljoa enemmän onkaan Hengen virka oleva kirkkaudessa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Sillä jos kadotustuomion virka jo oli kirkkautta, niin on vanhurskauden virka vielä paljon runsaammassa määrin kirkkautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Sillä se, millä ennen oli kirkkaus, on tämän rinnalla kirkkautta vailla, tämän ylenpalttisen kirkkauden tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Jos sillä, mikä on katoavaa, oli kirkkautta, niin vielä paljoa enemmän on sillä, mikä on pysyvää, oleva kirkkautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Koska meillä on siis tällainen toivo, olemme aivan rohkeat');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'emmekä tee kuten Mooses, joka pani peitteen kasvoilleen, etteivät Israelin lapset näkisi sen loppua, mikä on katoavaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Mutta heidän mielensä paatuivat, sillä vielä tänäkin päivänä sama peite, Vanhan liiton Kirjoituksia luettaessa, pysyy paikallaan, sillä vasta Kristuksessa se katoaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Vielä tänäkin päivänä, kun Moosesta luetaan, on peite heidän sydämensä päällä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'mutta kun heidän sydämensä kääntyy Herran luo, otetaan peite pois.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Sillä Herra on Henki, ja missä Herran Henki on, siinä on vapaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Mutta me kaikki, jotka peittämättömin kasvoin katselemme Herran kirkkautta kuin kuvastimesta, muutumme saman kuvan kaltaisiksi kirkkaudesta kirkkauteen, niin kuin muuttaa Herra, joka on Henki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Sen tähden, kun meillä on tämä virka saamamme laupeuden mukaan, emme lannistu,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'vaan olemme hylänneet häpeälliset salatiet, niin ettemme vaella kavaluudessa emmekä väärennä Jumalan sanaa, vaan tuomalla julki totuuden suositamme itseämme jokaisen ihmisen omalletunnolle Jumalan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Mutta jos meidän evankeliumimme on peitettynä, niin se on peitettynä kadotukseen menevissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'niissä epäuskoisissa, joiden mielet tämän maailman jumala on niin sokaissut, ettei heille loista valo Kristuksen kirkkauden evankeliumista, hänen, joka on Jumalan kuva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Sillä emme saarnaa itseämme, vaan Kristusta Jeesusta, että hän on Herra, mutta me itse olemme teidän palvelijoitanne Jeesuksen tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Sillä Jumala, joka käski valon loistaa pimeydestä, on se, joka loisti sydämiimme, että Jumalan kirkkauden tunteminen, sen kirkkauden, joka loistaa Kristuksen kasvoissa, levittäisi valoaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Mutta tämä aarre meillä on saviastioissa, että tuo suunnattoman suuri voima olisi Jumalan eikä olisi lähtöisin meistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Olemme kaikin tavoin ahdingossa, mutta emme umpikujassa, neuvottomia, mutta emme toivottomia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'vainottuja, mutta emme hylättyjä, maahan lyötyjä, mutta emme tuhottuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Kannamme aina Jeesuksen kuolemaa ruumiissamme, että Jeesuksen elämäkin tulisi ruumiissamme näkyviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Sillä me, jotka elämme, olemme alati annetut kuolemaan Jeesuksen tähden, että Jeesuksen elämäkin tulisi ilmi kuolevaisessa lihassamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Niinpä siis kuolema tekee työtään meissä, mutta elämä teissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Mutta koska meillä on sama uskon Henki, niin kuin kirjoitettu on: \"Uskon, sen tähden puhun\", niin mekin uskomme, ja sen tähden myös puhumme,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'tietäen, että hän, joka herätti Herran Jeesuksen, on herättävä meidätkin Jeesuksen kanssa ja asettava esiin yhdessä teidän kanssanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Sillä kaikki tapahtuu teidän tähtenne, että aina enenevä armo yhä useampien kautta saisi aikaan yhä runsaampaa kiitosta Jumalan kunniaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Sen tähden emme lannistu, vaan vaikka ulkonainen ihmisemme menehtyykin, sisäinen kuitenkin päivä päivältä uudistuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Sillä tämä hetken kestävä ja kevyt ahdistuksemme tuottaa meille iankaikkisen ja määrättömän kirkkauden, ylenpalttisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'meille, jotka emme katso näkyväisiä, vaan näkymättömiä, sillä näkyvät ovat ohimeneviä, mutta näkymättömät iankaikkisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Sillä tiedämme, että vaikka tämä maallinen majamme tuhotaankin, meillä on asumus Jumalalta, iankaikkinen maja taivaissa, joka ei ole käsin tehty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Sen tähden huokaamme ja ikävöimme pukeutua taivaalliseen majaamme,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'sillä kun olemme siihen pukeutuneet, meitä ei havaita alastomiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Sillä me, jotka olemme tässä telttamajassa, huokaamme raskautettuina, koska emme tahdo riisuutua, vaan pukeutua, että elämä nielisi sen, mikä on kuolevaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Mutta se, joka on valmistanut meidät juuri tähän, on Jumala, joka on antanut meille Hengen vakuudeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Sen tähden olemme aina turvallisella mielellä ja tiedämme, että, niin kauan kuin olemme kotona tässä ruumiissamme, olemme poissa kotoa Herran luota,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'sillä vaellamme uskossa emmekä näkemisessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Mutta olemme turvallisella mielellä ja haluamme mieluummin muuttaa pois ruumiista ja tulla kotiin Herran luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Sen tähden olimmepa kotona tai poissa, ahkeroimme olla hänelle mieliksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Sillä kaikkien meidän pitää ilmestyä Kristuksen tuomioistuimen eteen, että kukin saisi sen mukaan, kuin hän ruumiissa ollessaan on tehnyt, joko hyvää tai pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Kun siis tiedämme, mitä Herran pelko on, koetamme saada ihmisiä uskomaan, mutta Jumala kyllä meidät tuntee, ja toivon, että tekin omissatunnoissanne meidät tunnette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Emme nyt taas suosittele itseämme teille, vaan tahdomme antaa teille tilaisuuden kerskata meistä, että teillä olisi mitä vastata niille, jotka kerskuvat siitä, mikä näkyy silmään, eivätkä siitä, mikä on sydämessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Sillä jos olemme olleet suunniltamme, olemme olleet Jumalan tähden. Jos taas maltamme mielemme, teemme sen teidän tähtenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Sillä Kristuksen rakkaus vaatii meitä, jotka olemme tulleet tähän päätökseen, että yksi on kuollut kaikkien edestä, siis myös kaikki ovat kuolleet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'ja hän on kuollut kaikkien edestä, että ne, jotka elävät, eivät enää eläisi itselleen, vaan hänelle, joka heidän edestään on kuollut ja ylösnoussut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Sen tähden me emme tästä lähtien tunne ketään lihan mukaan. Jos olemmekin tunteneet Kristuksen lihan mukaan, emme kuitenkaan nyt enää tunne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Siis, jos joku on Kristuksessa, hän on uusi luomus. Se, mikä on vanhaa, on kadonnut, katso, kaikki on uudeksi tullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Mutta kaikki on Jumalasta, joka sovitti meidät itsensä kanssa Kristuksen kautta ja antoi meille sovituksen viran.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Sillä Jumala oli Kristuksessa ja sovitti maailman itsensä kanssa eikä lukenut heille heidän rikkomisiaan, ja hän asetti keskuuteemme sovituksen sanan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Kristuksen puolesta olemme siis lähettiläinä, ja Jumala kehottaa meidän kauttamme. Pyydämme Kristuksen puolesta: ottakaa vastaan tämä sovinto Jumalan kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Sen, joka ei synnistä tiennyt, hän meidän tähtemme teki synniksi, että me hänessä tulisimme Jumalan vanhurskaudeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Hänen työtovereinaan myös kehotamme teitä vastaanottamaan Jumalan armon niin, ettei se jää turhaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'Sillä hän sanoo: \"Otollisella ajalla olen sinua kuullut ja pelastuksen päivänä sinua auttanut.\" Katso, nyt on otollinen aika, katso, nyt on pelastuksen päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Missään kohden emme aiheuta pahennusta, ettei palvelusvirkaa moitittaisi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'vaan kaikessa suosittelemme itseämme Jumalan palvelijoina: suuressa kärsivällisyydessä, ahdistuksissa, hädissä, ahdingoissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'ruoskittaessa, vankeudessa, meteleissä, vaivannäöissä, valvomisissa, paastoissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'puhtaudessa, tiedossa, pitkämielisyydessä, ystävällisyydessä, Pyhässä Hengessä, vilpittömässä rakkaudessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'totuuden sanassa, Jumalan voimassa, vanhurskauden aseet oikeassa ja vasemmassa kädessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'kunniassa ja häpeässä, pahassa maineessa ja hyvässä, eksyttäjinä ja kuitenkin totta puhuvina,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'tuntemattomina ja kuitenkin hyvin tunnettuina, kuolemaisillamme, ja katso, [me] elämme, kuritettuina emmekä kuitenkaan tapettuina,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'murheellisina, mutta aina iloisina, köyhinä, mutta kuitenkin monia rikkaiksi tekevinä, mitään omistamatta, mutta kuitenkin omistaen kaiken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Suumme on auennut puhumaan teille, korinttolaiset, sydämemme on avartunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Teillä ei ole ahdasta meidän sydämessämme, vaan ahdasta on teidän omassa sydämessänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Maksakaa samalla mitalla – puhun kuin lapsille – avartukaa tekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Älkää antautuko kantamaan vierasta iestä yhdessä epäuskoisten kanssa, sillä mitä yhteistä on vanhurskaudella ja laittomuudella? Tai mitä yhteyttä on valolla ja pimeydellä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Miten sopivat yhteen Kristus ja Belial? Tai mitä yhteistä osaa uskovalla on epäuskoisen kanssa?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Ja miten soveltuvat yhteen Jumalan temppeli ja epäjumalat? Sillä te olette elävän Jumalan temppeli, niin kuin Jumala on sanonut: \" [Minä] olen heissä asuva ja vaeltava heidän keskellään ja oleva heidän Jumalansa, ja he ovat minun kansani.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Sen tähden: \"Lähtekää pois heidän keskeltään ja erotkaa heistä, sanoo Herra, älkääkä koskeko saastaiseen, niin minä otan teidät omikseni');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'ja olen teidän Isänne, ja te olette minun poikiani ja tyttäriäni, sanoo Herra, Kaikkivaltias.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Koska meillä siis on nämä lupaukset, rakkaani, puhdistautukaamme kaikesta lihan ja hengen saastaisuudesta vieden pyhityksemme päätökseen Jumalan pelossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Antakaa meille tilaa sydämessänne. Emme ole tehneet kenellekään vääryyttä, emme ole olleet kenellekään turmioksi emmekä ole tuottaneet kenellekään vahinkoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'En sano tätä tuomitakseni teitä, sillä olenhan jo aikaisemmin sanonut, että olette meidän sydämessämme yhdessä kuollaksemme ja yhdessä elääksemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Paljon minulla on luottamusta teihin, paljon minulla on kerskattavaa teistä. Olen täynnä lohdutusta, minulla on ylenpalttinen ilo kaikessa ahdingossamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Sillä Makedoniaan tultuammekaan lihamme ei saanut mitään lepoa, vaan olimme kaikin tavoin ahdistetut: ulkoapäin taisteluita, sisältäpäin pelkoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Mutta Jumala, joka masentuneita lohduttaa, lohdutti meitä Tiituksen tulolla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'eikä ainoastaan hänen tulollaan, vaan myös sillä lohdutuksella, jonka hän oli saanut teistä, sillä hän on kertonut meille teidän ikävöinnistänne, valittelustanne ja innostanne minun hyväkseni, niin että iloitsin vielä enemmän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Sillä vaikka murehdutinkin teitä kirjeelläni, en sitä kadu, ja jos kaduinkin, niin – kun näen, että tuo kirje, vaikka vain vähäksi aikaa, on murehduttanut teitä –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'nyt iloitsen, en siitä, että tulitte murheellisiksi, vaan siitä, että murheenne oli teille mielenmuutokseksi. Sillä tulitte murheellisiksi Jumalan mielen mukaan, ettei teillä olisi mitään vahinkoa meistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Sillä Jumalan mielen mukainen murhe saa aikaan mielenmuutoksen, joka koituu pelastukseksi ja jota ei kukaan kadu, mutta maailman murhe tuottaa kuoleman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Sillä katsokaa, kuinka suurta intoa juuri tuo Jumalan mielen mukainen murehtimisenne on saanut teissä aikaan, mitä puolustautumista, mitä paheksumista, mitä pelkoa, ikävöintiä, kiivautta, mitä kurittamista! Olette kaikin tavoin osoittaneet olevanne puhtaita tässä asiassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Vaikka siis kirjoitinkin teille, en kirjoittanut vääryyttä tehneen enkä vääryyttä kärsineen vuoksi, vaan sen tähden, että intonne hyväksemme tulisi julki keskuudessanne Jumalan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Sen tähden olemme nyt lohdutetut. Mutta tämän lohdutuksemme lisäksi on meitä vielä paljoa enemmän ilahduttanut Tiituksen ilo, sillä hänen henkensä on saanut virvoitusta teiltä kaikilta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Sillä jos olenkin jossakin kohden teitä hänelle kehunut, en ole joutunut häpeään, vaan niin kuin kaikki, mitä olemme teille puhuneet, on totta, niin on myös se, mistä olemme teitä Tiitukselle kehuneet, osoittautunut todeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'Hänen sydämensä heltyy yhä enemmän teitä kohtaan, kun hän muistelee kaikkien teidän kuuliaisuuttanne, kuinka pelolla ja vavisten otitte hänet vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Minä iloitsen, että kaikessa voin olla teistä turvallisella mielellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Mutta saatamme tietoonne, veljet, sen Jumalan armon, jonka hän on suonut Makedonian seurakunnissa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'että, vaikka he olivat monessa ahdistuksen koetuksessa ja syvässä köyhyydessä, heidän ilonsa ylenpalttisuus vaikutti, että he antoivat alttiisti runsaita lahjoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Sillä voimiensa mukaan, sen todistan, jopa yli voimiensakin he antoivat omasta halustaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'paljolla pyytämisellä anoen meiltä sitä suosiota, että heidät otettaisiin mukaan pyhien avustamiseen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'eivätkä he vain tehneet, kuten olimme toivoneet, vaan antoivat itsensäkin, ensiksi Herralle ja sitten meille Jumalan tahdosta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'niin että me kehotimme Tiitusta, niin kuin hän oli jo alkanut, saattamaan keskuudessanne päätökseen tämänkin rakkaudentyön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Mutta niin kuin teillä on ylenpalttisesti kaikkea: uskoa, sanaa, tietoa, kaikkinaista intoa ja meistä teihin tullutta rakkautta, olkaa ylenpalttiset tässäkin rakkaudentyössä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'En sano tätä käskynä, vaan viittaamalla muiden intoon koettelen teidänkin rakkautenne vilpittömyyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Sillä te tunnette meidän Herramme Jeesuksen Kristuksen armon, että hän, vaikka oli rikas, tuli teidän tähtenne köyhäksi, että te hänen köyhyydestään rikastuisitte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'Annan vain neuvon tässä asiassa, sillä se on hyödyksi teille, jotka jo viime vuonna olitte ensimmäiset, ette ainoastaan tekemässä, vaan myös tahtomassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Saattakaa nyt siis tekonne päätökseen, niin että, yhtä alttiisti kuin olitte sitä halunneet, myös veisitte sen loppuun asti varojenne mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Sillä jos on alttiutta, se on otollista sen mukaan, kuin on varoja, ei sen mukaan, kuin niitä ei ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Sillä ei ole tarkoitus, että muilla olisi huojennus, teillä rasitus, vaan tasauksen vuoksi tulkoon tätä nykyä teidän yltäkylläisyytenne heidän puutteensa hyväksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'että heidänkin yltäkylläisyytensä tulisi teidän puutteenne hyväksi, että syntyisi tasaus,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'kuten on kirjoitettu: \"Sille, jolla oli paljon, ei jäänyt liikaa, ja siltä, jolla oli vähän, ei puuttunut mitään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Mutta kiitos Jumalalle, joka antaa Tiituksen sydämeen saman innon teidän hyväksenne!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Sillä hän otti vastaan kehotukseni innostuen lähtemään omasta halustaan luoksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Ja me lähetämme hänen kanssaan veljen, jota kiitetään evankeliumista kaikissa seurakunnissa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'ja jonka seurakunnat vielä sen lisäksi ovat myös valinneet matkatoveriksemme viemään tätä rakkauden lahjaa, joka on meidän toimitettavanamme itse Herran kunniaksi ja teidän alttiutenne osoitukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Näin vältämme, ettei kukaan pääse moittimaan meitä mistään, mikä koskee tätä runsasta avustusta, joka on meillä toimitettavana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'Sillä ahkeroimme sitä, mikä on hyvää, ei ainoastaan Herran, vaan myös ihmisten edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Näiden kanssa lähetämme vielä erään veljemme, jonka intoa usein ja monessa asiassa olemme koetelleet ja joka nyt on entistä paljon innokkaampi, koska hänellä on suuri luottamus teihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Jos siis on puhe Tiituksesta, niin hän on minun toverini ja työkumppanini teidän hyväksenne. Veljemme taas ovat seurakuntien lähettiläitä ja Kristuksen kunnia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Osoittakaa siis heille myös seurakuntien edessä todistus rakkaudestanne ja kerskauksestamme teihin nähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Pyhien avustamisesta minun on tosin tarpeetonta kirjoittaa teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Tunnenhan alttiutenne, ja siitä kehun teitä makedonialaisille, että näet Akaia on ollut valmiina viime vuodesta saakka, ja teidän intonne on saanut monia innostumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Lähetän nyt kuitenkin nämä veljet, ettei kerskaamisemme teistä tässä kohden näyttäisi olevan turhaa, vaan olisitte valmiita, kuten olen sanonut teidän olevan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'Muuten, jos makedonialaisia tulee kanssani ja he havaitsevat teidän olevan valmistautumattomia, me – ettemme sanoisi te – joutuisimme häpeään tässä luottamuksessa, kun teistä kerskaamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Olen siis katsonut välttämättömäksi kehottaa veljiä lähtemään edeltä luoksenne ja toimittamaan valmiiksi ennen lupaamanne kiitoslahjan, että se olisi valmis runsaana eikä kitsaana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Mutta se, joka niukasti kylvää, myös niukasti niittää, ja se, joka runsaasti kylvää, myös runsaasti niittää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Antakoon kukin, niin kuin hänen sydämensä vaatii, ei surkeillen eikä pakosta, sillä iloista antajaa Jumala rakastaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Jumala on voimallinen antamaan teille ylenpalttisesti kaikkea armoa, että teillä kaikessa aina olisi kaikkea riittävästi voidaksenne ylenpalttisesti tehdä kaikkea hyvää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'niin kuin on kirjoitettu: \"Hän sirottelee, hän antaa köyhille, hänen vanhurskautensa pysyy iankaikkisesti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Ja hän, joka antaa siemenen kylväjälle ja leivän ruuaksi, on enentävä kylvönne ja kasvattava vanhurskautenne hedelmät,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'niin että kaikessa rikastuisitte kaikella vilpittömyydellä, joka meidän kauttamme saa aikaan kiitosta Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Sillä tämä avustamispalvelus ei ainoastaan poista pyhien puutteita, vaan tulee vieläkin runsaammaksi Jumalalle annettujen monien kiitosten kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Tämä teidän koeteltu mielenne ja palveluksenne osoittaa teidän ylistävän Jumalaa, kun alistuvasti tunnustaudutte Kristuksen evankeliumiin ja olette vilpittömästi ruvenneet yhteyteen heidän kanssaan ja kaikkien kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'Hekin rukoilevat teidän edestänne ja ikävöivät teitä hyvin runsaan Jumalan armon tähden teidän keskuudessanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Kiitos Jumalalle hänen sanomattomasta lahjastaan!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Minä, Paavali, itse kehotan teitä Kristuksen laupeuden ja lempeyden kautta, minä, joka olen kuulemma nöyrä kasvokkain kanssanne, mutta poissa ollessani rohkea teitä kohtaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'ja pyydän, ettei minun ollessani luonanne tarvitsisi turvautua siihen lujaan rohkeuteen, jolla aion vastustaa eräitä, jotka ajattelevat meidän vaeltavan lihan mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Vaikka vaellammekin lihassa, emme lihan mukaan sodi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'Sillä sota-aseemme eivät ole lihallisia, vaan ne ovat voimakkaita Jumalan edessä hajottamaan maahan linnoituksia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'Hajotamme maahan järjen päätelmät ja jokaisen korkean rakennelman, joka nostetaan Jumalan tuntemista vastaan, ja vangitsemme jokaisen ajatuksen kuuliaiseksi Kristukselle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'ja olemme valmiita rankaisemaan kaikkea tottelemattomuutta, sitten kun teidän kuuliaisuutenne on tullut täydelliseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Katseletteko asioita henkilön mukaan? Jos joku on mielessään varma siitä, että hän on Kristuksen oma, ajatelkoon edelleen mielessään, että samoin kuin hän on Kristuksen, samoin olemme mekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Ja vaikka jonkin verran enemmänkin kerskaisin siitä vallastamme, jonka Herra on antanut meille rakentaaksemme teitä eikä kukistaaksemme, en häpeään joudu');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, '– ettei näyttäisi siltä, kuin pelottelisin teitä kirjeilläni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Sillä hänen kirjeensä ovat, sanotaan, kyllä ankaria ja voimakkaita, mutta ruumiillisesti läsnä ollessaan hän on heikko, ja hänen puheensa on arvotonta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Sellainen tietäköön, että samaa, mitä poissaolevina olemme kirjeissämme sanoissa, samaa olemme läsnä olevina teoissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Sillä emme rohkene lukeutua emmekä verrata itseämme eräisiin, jotka suosittelevat itseään, mutta ovat ymmärtämättömiä, kun mittaavat itseään omalla itsellään ja vertailevat itseään omaan itseensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Me taas emme kerskaa rajattomasti, vaan ainoastaan sen vaikutusalan mitan mukaan, minkä Jumala on asettanut meille määräksi ulottuaksemme teihinkin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Sillä emme kurota itseämme liiaksi, ikään kuin emme teihin ulottuisikaan, sillä olemmehan ehtineet Kristuksen evankeliumilla teihinkin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'Emme kerskaa yli määrän muiden vaivannäöistä, mutta meillä on se toivo, että teidän uskonne lisääntyessä oman vaikutusalamme mukaan kasvamme teidän keskuudessanne niin suuriksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'että saamme viedä evankeliumin myös tuolla puolen teitä oleviin seutuihin – tahtomatta kerskata siitä, mikä on valmista toisten vaikutusalalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Mutta joka kerskaa, kerskatkoon Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Sillä ei se ole koetuksen kestävä, joka itseään suosittelee, vaan se, jota Herra suosittelee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Jospa kärsisitte minulta hiukan mielettömyyttäkin! Ja niinhän te minua kärsittekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Sillä kiivailen teidän puolestanne Jumalan kiivaudella. Olenhan kihlannut teidät yhdelle miehelle asettaakseni Kristuksen eteen pyhän neitsyen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Mutta pelkään, että niin kuin käärme kavaluudellaan petti Eevan, samoin teidän mielenne turmeltuu pois vilpittömyydestä, joka teillä on Kristusta kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Sillä jos joku tulee ja saarnaa jotakin toista Jeesusta, jota emme ole saarnanneet, tai jos te saatte toisen hengen, jota ette ole saaneet, tai toisen evankeliumin, jota ette ole vastaanottaneet, sitä te hyvin siedätte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Mutta en pidä itseäni missään kohden noita hyvin korkeita apostoleja huonompana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Jos olenkin oppimaton puheessa, en kuitenkaan tiedossa. Olenhan tuonut sen teille kaikin tavoin ilmi kaikissa asioissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Vai olenko tehnyt syntiä siinä, että – alentaessani itseni, jotta te ylenisitte – olen ilmaiseksi julistanut teille Jumalan evankeliumia?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Muita seurakuntia riistin, kun otin heiltä palkkaa palvellakseni teitä. Kun olin luonanne ja kärsin puutetta, en rasittanut ketään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Sillä mitä minulta puuttui, sen täyttivät veljet, jotka tulivat Makedoniasta, ja kaikessa pidätyin teitä rasittamasta, ja pidätyn vastakin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Koska Kristuksen totuus on minussa, tätä kerskausta ei riistetä minulta Akaian maakunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Minkä tähden? Senkö tähden, etten rakasta teitä? Jumala tietää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Mutta mitä teen, sen teen vastakin, poistaakseni aiheen niiltä, jotka etsivät aihetta, että heidät siinä, missä kerskuvat, havaittaisiin sellaisiksi kuin mekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Sillä sellaiset ovat vääriä apostoleja, petollisia työntekijöitä, jotka tekeytyvät Kristuksen apostoleiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'Eikä ihme, sillä itse saatana tekeytyy valkeuden enkeliksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Ei ole siis paljon, jos hänen palvelijansakin tekeytyvät vanhurskauden palvelijoiksi. Heidän loppunsa on oleva heidän tekojensa mukainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Taas sanon: älköön kukaan ajatelko, että olen mieltä vailla, mutta vaikka olisinkin, ottakaa minut mieltä vailla olevanakin vastaan, että minäkin hiukan kerskaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Sitä, mitä nyt puhun, en puhu Herran mielen mukaan, vaan kuin mieltä vailla, kun tässä luottamuksessa kerskaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Koska monet kerskaavat lihan mukaan, kerskaan minäkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Te siedätte mielellänne mieltä vailla olevia, kun itse olette viisaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Tehän suvaitsette, jos joku teitä orjuuttaa, jos joku teitä ryöstää, jos joku saa teidät pauloihinsa, jos joku itsensä korottaa, ja jos joku lyö teitä kasvoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Häpeäkseni sanon: tähän kyllä olemme olleet heikkoja. Mutta minkä joku toinen uskaltaa – puhun mieltä vailla – sen uskallan minäkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'He ovat heprealaisia, minä myös. He ovat israelilaisia, minä myös. He ovat Aabrahamin siementä, minä myös.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'He ovat Kristuksen palvelijoita – puhun mieltä vailla – minä vielä enemmän. Olen nähnyt vaivaa enemmän, minua on ruoskittu ylenmäärin, olen ollut useammin vankiloissa, olen monta kertaa ollut kuoleman vaarassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Juutalaisilta olen viidesti saanut neljäkymmentä lyöntiä, yhtä vaille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'kolme kertaa olen saanut raippoja, kerran minua kivitettiin, kolme kertaa olen joutunut haaksirikkoon, vuorokauden olen meressä ajelehtinut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'olen usein ollut matkoilla, vaaroissa virtojen vesillä, vaaroissa rosvojen keskellä, vaaroissa heimoni puolelta, vaaroissa pakanoiden puolelta, vaaroissa kaupungeissa, vaaroissa erämaassa, vaaroissa merellä, vaaroissa valheveljien keskellä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'ollut työssä ja vaivannäössä, paljon valvonut, kärsinyt nälkää ja janoa, paljon paastonnut, kärsinyt kylmää ja vaatteiden puutetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Kaiken muun lisäksi [minulla on ollut] jokapäiväistä tunkeilua luonani, huolta kaikista seurakunnista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Kuka on heikko, etten minäkin olisi heikko? Kuka lankeaa, ettei se minua polttaisi?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Jos minun täytyy kerskata, kerskaan heikkoudestani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Herran Jeesuksen Jumala ja Isä, joka on ylistetty iankaikkisesti, tietää, etten valehtele.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'Damaskossa kuningas Aretaan käskynhaltija vartioi damaskolaisten kaupunkia haluten ottaa minut kiinni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'ja minut laskettiin ikkunasta korissa maahan, ja pääsin hänen käsistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Minun täytyy kerskata. Se tosin ei ole hyödyllistä, mutta siirryn nyt näkyihin ja Herran ilmestyksiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Tunnen miehen Kristuksessa: neljätoista vuotta sitten hänet temmattiin kolmanteen taivaaseen – oliko hän ruumiissa, en tiedä, vai poissa ruumiista, en tiedä, Jumala tietää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'Tiedän, että tämä mies – oliko hän ruumiissa vai poissa ruumiista, en tiedä, Jumala tietää –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'temmattiin paratiisiin ja kuuli lausumattomia sanoja, joita ihmisen ei ole lupa puhua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Tästä miehestä kerskaan, mutta itsestäni en kerskaa, paitsi heikkoudestani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Sillä jos tahtoisinkin kerskata, en olisi vailla mieltä, sillä puhuisin totta. Mutta pidätyn siitä, ettei kukaan ajattelisi minusta enempää, kuin mitä näkee minun olevan tai mitä hän minusta kuulee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'Etten ylenpalttisten ilmestysten tähden ylpeilisi, minulle on annettu pistin lihaan, saatanan enkeli, lyömään minua, etten ylpeilisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Tämän tähden olen kolmesti rukoillut Herraa, että se jättäisi minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Hän sanoi minulle: \"Minun armossani on sinulle kyllin, sillä voimani tulee täydelliseksi heikkoudessa.\" Sen tähden mieluimmin kerskaan heikkoudestani, että Kristuksen voima asettuisi minuun asumaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Sen tähden minä olen mielistynyt heikkouksiin, pahoinpitelyihin, hätään, vainoihin, ahdistuksiin, Kristuksen tähden, sillä kun olen heikko, silloin olen vahva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Olen kerskannut mieltä vailla. Te olette pakottaneet minut siihen. Minunhan olisi pitänyt saada suositusta teiltä, sillä en ole ollut missään noita hyvin korkeita apostoleja huonompi, vaikka en olekaan mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Onhan apostolin tunnusteot keskuudessanne tehty kaikella kestävyydellä, tunnusmerkeillä, ihmeillä ja voimateoilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Sillä missä muussa te olette jääneet muita seurakuntia vähemmälle kuin siinä, etten minä itse rasittanut teitä? Antakaa minulle anteeksi tämä vääryys.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Katso, kolmannen kerran olen valmis tulemaan luoksenne, enkä ole oleva teille rasitukseksi, sillä en etsi teidän omaanne, vaan teitä. Eiväthän lapset ole velvollisia kokoamaan tavaraa vanhemmilleen, vaan vanhemmat lapsilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Minä olen mielelläni uhraava kaikki, uhraava itsenikin, teidän sielujenne hyväksi, siitä huolimatta, että vaikka rakastan teitä ylenpalttisesti, saan teiltä vähemmän rakkautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Olkoon niin, etten minä ole rasittanut teitä, mutta entä jos olen ollut viekas ja olen kavaluudella saanut teidät omikseni!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Olenkohan kenenkään kautta, joita olen lähettänyt luoksenne, pyrkinyt hyötymään teistä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Kehotin Tiitusta menemään ja lähetin veljen hänen kanssaan. Eihän Tiitus ole pyrkinyt teistä hyötymään? Emmekö ole vaeltaneet samassa hengessä? Emmekö samoja jälkiä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Ajatteletteko taas, että teidän edessänne puolustaudumme? Jumalan edessä, Kristuksessa puhumme, mutta kaikki teille rakennukseksi, rakkaani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Sillä pelkään, että tullessani en ehkä tapaa teitä sellaisina, kuin tahdon, ja että tapaatte minut sellaisena, kuin ette tahdo. Keskuudessanne ehkä on riitaa, kateutta, vihaa, juonia, panetteluja, juoruja, pöyhkeilyä ja eriseuroja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Pelkään, että kun tulen, Jumalani on taas nöyryyttävä minua luonanne, ja että tulen suremaan monen tähden, jotka ennen ovat synnissä eläneet eivätkä ole kääntyneet pois siitä saastaisuudesta, haureudesta ja irstaudesta, jota ovat harjoittaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Tämä on kolmas kerta kun tulen luoksenne. Kahden tai kolmen todistajan suulla on jokainen asia vahvistettava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Olen edeltäpäin sanonut ja sanon etukäteen niin kuin toisella kerralla läsnä ollessani ja kirjoitan nyt poissa ollessani niille, jotka ennen ovat syntiä tehneet, ja kaikille muille, että kun taas tulen, en ole heitä säästävä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'koska etsitte todistetta siitä, että minussa puhuu Kristus, joka ei ole heikko teitä kohtaan, vaan on teissä voimakas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Sillä vaikka hänet ristiinnaulittiin, kun hän oli heikko, hän elää kuitenkin Jumalan voimasta. Olemmehan mekin hänessä heikot, mutta elämme hänen kanssaan Jumalan voimasta teitä varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Koetelkaa itseänne, oletteko uskossa, tutkikaa itseänne. Vai ettekö tunne itseänne, että Jeesus Kristus on teissä? Ellette, ette kestä koetusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Toivon teidän tulevan tuntemaan, että me emme ole niitä, jotka eivät kestä koetusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Mutta rukoilemme Jumalaa, ettette tekisi mitään pahaa, emme sitä varten, että näyttäisi siltä, kuin me olisimme koetuksen kestäviä, vaan että te tekisitte hyvää ja me olisimme ikään kuin ne, jotka eivät koetusta kestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Sillä emme voi mitään totuutta vastaan, vaan totuuden puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Sillä iloitsemme, kun me olemme heikkoja, mutta te olette vahvoja. Sitä rukoilemmekin, että tulisitte täydellisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Sen tähden kirjoitan tämän poissa ollessani, ettei minun läsnä ollessani tarvitsisi käyttää ankaruutta sen vallan mukaan, minkä Herra on minulle antanut rakentamiseksi, ei kukistamiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Lopuksi, veljet, iloitkaa, tulkaa täydellisiksi, ottakaa vastaan kehotuksia, olkaa yhtä mieltä, eläkää sovussa, ja rakkauden ja rauhan Jumala on oleva kanssanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Tervehtikää toisianne pyhällä suudelmalla. Kaikki pyhät tervehtivät teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Herran Jeesuksen Kristuksen armo ja Jumalan rakkaus ja Pyhän Hengen osallisuus olkoon teidän kaikkien kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paavali, apostoli, ei ihmisten toimesta eikä ihmisen kautta, vaan Jeesuksen Kristuksen kautta ja Isän Jumalan, joka on hänet kuolleista herättänyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'ja kaikki veljet, jotka ovat kanssani, Galatian seurakunnille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Armo teille ja rauha Jumalalta, Isältämme, ja Herralta Jeesukselta Kristukselta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'joka antoi itsensä alttiiksi syntiemme tähden pelastaakseen meidät nykyisestä pahasta maailmanajasta Jumalamme ja Isämme tahdon mukaan!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'Hänelle kunnia iäisyyksien iäisyyksiin! Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Ihmettelen, että te niin äkkiä käännytte hänestä, joka on kutsunut teidät Kristuksen armossa, pois toiseen evankeliumiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'joka ei ole toinen. On vain eräitä, jotka hämäävät teitä ja tahtovat muuttaa Kristuksen evankeliumin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Mutta vaikka me, tai vaikka enkeli taivaasta julistaisi teille evankeliumia toisin kuin me olemme teille julistaneet, hän olkoon kirottu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Niin kuin olemme ennenkin sanoneet, ja taas nytkin sanon: jos joku julistaa teille evankeliumia vastoin sitä, minkä te olette saaneet, hän olkoon kirottu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Sillä etsinkö nyt ihmisten suosiota vai Jumalan? Vai ihmisillekö pyrin olemaan mieliksi? Jos vielä olen ihmisten mieliksi, en ole Kristuksen palvelija.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Sillä teen teille tiettäväksi, veljet, että julistamani evankeliumi ei ole ihmisten mukainen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'sillä en olekaan sitä ihmisiltä saanut enkä oppinut, vaan Jeesuksen Kristuksen ilmestyksen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Olettehan kuulleet aikaisemmasta vaelluksestani juutalaisuudessa, että vainosin ylenmäärin Jumalan seurakuntaa ja hävitin sitä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'ja että edistyin juutalaisuudessa pidemmälle kuin monet samanikäiset heimossani ja kiivailin hyvin innokkaasti isieni perinnäissääntöjen puolesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Mutta kun hän, joka äitini kohdusta saakka on minut erottanut ja kutsunut armonsa kautta, näki hyväksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'ilmoittaa minussa Poikansa, että julistaisin evankeliumia hänestä pakanoiden seassa, niin en ensinkään kysynyt neuvoa lihalta ja vereltä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'enkä lähtenyt ylös Jerusalemiin niiden luo, jotka ennen minua olivat apostoleja, vaan menin pois Arabiaan ja palasin taas Damaskoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Sitten, kolmen vuoden kuluttua, menin ylös Jerusalemiin tutustuakseni Keefaaseen ja viivyin hänen luonaan viisitoista päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Mutta ketään toista apostolia en nähnyt paitsi Jaakobin, Herran veljen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Sen, minkä teille kirjoitan, katso, kirjoitan Jumalan edessä, sillä en valehtele.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Sitten menin Syyrian ja Kilikian seudulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Mutta olin kasvoiltani tuntematon Juudean seurakunnille, jotka ovat Kristuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'He olivat vain kuulleet: \"Meidän entinen vainoojamme julistaa nyt sitä uskoa, jota hän ennen hävitti\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'ja he ylistivät Jumalaa minun tähteni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Sitten neljäntoista vuoden kuluttua menin taas ylös Jerusalemiin Barnabaan kanssa ja otin mukaani Tiituksenkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Mutta menin sinne ilmestyksen johdosta ja esitin heille sen evankeliumin, jota julistan pakanoiden keskuudessa. Esitin sen yksityisesti heistä arvostetuimmille, etten ehkä juoksisi tai olisi juossut turhaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Mutta ei edes Tiitusta, joka oli kanssani ja oli kreikkalainen, pakotettu ympärileikkauttamaan itseään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'Noiden sisään tunkeutuneiden valheveljien tähden, jotka orjuuttaakseen meitä olivat tulleet salaa vakoilemaan vapauttamme, mikä meillä on Kristuksessa Jeesuksessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'emme hetkeksikään alistuneet antamaan heille myöden, jotta evankeliumin totuus säilyisi keskuudessanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Mutta noista arvostetuista – millaisia olivat ennen olleetkin, ei kuulu minulle, Jumala ei katso henkilöön – nuo arvossapidetyt eivät lisänneet siihen mitään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'vaan päinvastoin, kun näkivät, että minulle oli uskottu evankeliumin julistaminen ympärileikkaamattomille, samoin kuin Pietarille sen julistaminen ympärileikatuille –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, 'sillä hän, joka antoi Pietarille voimaa hänen apostolinvirkaansa ympärileikattujen keskuudessa, antoi minullekin siihen voimaa pakanoiden parissa –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'ja kun olivat tulleet tuntemaan sen armon, mikä minulle oli annettu, niin Jaakob, Keefas ja Johannes, joita pidettiin pylväinä, antoivat minulle ja Barnabaalle kättä yhteyden merkkinä sopien, että me teemme työtä pakanoille ja he ympärileikatuille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Meidän tuli vain muistaa köyhiä, ja sitä olenkin ahkeroinut tehdä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Mutta kun Keefas tuli Antiokiaan, vastustin häntä julkisesti, koska häntä vastaan oli esitetty syytöksiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Sillä ennen kuin Jaakobin luota oli tullut muutamia miehiä, hän oli syönyt yhdessä pakanoiden kanssa, mutta heidän tultuaan hän vetäytyi pois ja pysytteli erillään peläten ympärileikattuja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'ja hänen kanssaan lankesivat ulkokultaisuuteen muutkin juutalaiset, niin että heidän ulkokultaisuutensa tempasi mukaansa Barnabaankin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Mutta kun näin, etteivät he vaeltaneet suoraan evankeliumin totuuden mukaan, sanoin Keefaalle kaikkien edessä: \"Jos sinä, joka olet juutalainen, noudatat pakanoiden tapoja etkä juutalaisten, miksi pakotat pakanoita noudattamaan juutalaisten tapoja?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Me olemme luonnostamme juutalaisia emmekä pakanasyntisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'Mutta koska tiedämme, ettei ihmistä julisteta vanhurskaaksi lain teoista, vaan uskon kautta Jeesukseen Kristukseen, mekin olemme uskoneet Kristukseen Jeesukseen, että meidät julistettaisiin vanhurskaiksi uskosta Kristukseen eikä lain teoista, koska mitään lihaa ei julisteta vanhurskaaksi lain teoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Mutta jos meidät itsemmekin on havaittu syntisiksi tavoitellessamme sitä, että meidät julistetaan vanhurskaiksi Kristuksessa, onko sitten Kristus synnin palvelija? Ei ikinä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Sillä jos uudestaan rakennan sitä, minkä olen hajottanut maahan, osoitan olevani lainrikkoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Sillä minä olen lain kautta kuollut pois laista, jotta eläisin Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Olen Kristuksen kanssa ristiinnaulittu, mutta elän, en enää minä, vaan Kristus elää minussa, ja minkä nyt elän lihassa, sen elän uskossa Jumalan Poikaan, häneen, joka on rakastanut minua ja antanut itsensä minun edestäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'En tee mitättömäksi Jumalan armoa, sillä jos vanhurskaus on lain kautta, silloin Kristus on turhaan kuollut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Voi teitä, te typerät galatalaiset! Kuka on lumonnut teidät luottamasta totuuteen, teidät, joiden silmien eteen Jeesus Kristus oli kirjoitettu ristiinnaulittuna?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Tahdon saada teiltä tietää vain tämän: lain teoistako saitte Hengen vai uskon saarnasta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Niinkö typeriä olette? Te aloititte Hengessä, lihassako nyt lopetatte?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Niin paljonko olette turhaan kärsineet? – jos se on ollut turhaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Joka siis antaa teille Hengen ja tekee voimatekoja keskuudessanne, saako hän sen aikaan lailla vai uskon saarnalla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'samalla tavalla kuin \"Aabraham uskoi Jumalaa, ja se luettiin hänelle vanhurskaudeksi\"?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Tietäkää siis, että ne, jotka ovat uskosta, ovat Aabrahamin lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Raamatun nähdessä edeltä, että Jumala lukee pakanat vanhurskaiksi uskosta, se julisti Aabrahamille edeltä tämän hyvän sanoman: \"Sinussa kaikki kansat tulevat siunatuiksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Näin ollen ne, jotka ovat uskosta, siunataan uskovan Aabrahamin kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Sillä kaikki, jotka ovat lain teoista, ovat kirouksen alaisia, sillä kirjoitettu on: \"Kirottu on jokainen, joka ei pysy kaikessa, mikä on kirjoitettuna lain kirjassa, niin että hän sen tekee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Selvää on, ettei ketään julisteta vanhurskaaksi Jumalan edessä lain kautta, koska \"vanhurskas on elävä uskosta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Mutta laki ei ole uskosta, vaan: \"Se, joka ne täyttää, on niistä elävä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Kristus on lunastanut meidät lain kirouksesta, kun hän tuli kiroukseksi edestämme – sillä kirjoitettu on: \"Kirottu on jokainen, joka on puuhun ripustettu \" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'että Aabrahamin siunaus tulisi Jeesuksessa Kristuksessa pakanoiden osaksi ja uskon kautta saisimme luvatun Hengen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Veljet, puhun ihmisten tavalla. Eihän kukaan voi kumota ihmisenkään vahvistettua testamenttia eikä siihen mitään lisätä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Mutta nyt lausuttiin lupaukset Aabrahamille ja hänen siemenelleen. Hän ei sano: \"Ja siemenille\", ikään kuin monesta, vaan ikään kuin yhdestä: \"Ja sinun siemenellesi\", joka on Kristus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Tarkoitan tätä: Jumalan ennen vahvistamaa testamenttia ei neljänsadan kolmenkymmenen vuoden perästä tullut laki voi kumota, niin että se tekisi lupauksen mitättömäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Sillä jos perintö olisi laista, se ei olisi lupauksesta. Mutta Aabrahamille Jumala on lahjoittanut sen lupauksen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Mitä varten sitten on laki? Se on rikosten tähden perästäpäin lisätty olemaan siihen asti, kunnes oli tuleva se siemen, jolle lupaus oli annettu. Se säädettiin enkelien kautta, välimiehen kädellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Välimies taas ei ole yhtä varten, mutta Jumala on yksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Onko sitten laki vastoin Jumalan lupauksia? Ei ikinä! Sillä jos olisi annettu laki, joka voisi tehdä eläväksi, niin vanhurskaus olisi laista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Mutta Raamattu on sulkenut kaikki synnin alle, että lupaus uskosta Jeesukseen Kristukseen annettaisiin niille, jotka uskovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Mutta ennen kuin usko tuli, vartioitiin meitä lain alle suljettuina tulevaa uskoa varten, joka oli vastedes ilmestyvä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Niin ollen laista on tullut meille kurittaja Kristukseen, että meidät julistettaisiin uskosta vanhurskaiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Mutta uskon tultua me emme enää ole kurittajan alaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Sillä te olette kaikki uskon kautta Jumalan lapsia Kristuksessa Jeesuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Sillä kaikki te, jotka olette Kristukseen kastetut, olette Kristuksen päällenne pukeneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Ei ole tässä juutalaista eikä kreikkalaista, ei ole orjaa eikä vapaata, ei ole miestä eikä naista, sillä kaikki te olette yksi Kristuksessa Jeesuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Mutta jos te olette Kristuksen omat, olette siis Aabrahamin siementä ja perillisiä lupauksen mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Mutta sanon: niin kauan kuin perillinen on alaikäinen, hän ei missään kohden eroa orjasta, vaikka onkin kaiken herra,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'vaan hän on holhoojien ja taloudenhoitajien alainen isän määräämään aikaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Samoin mekin, kun olimme alaikäisiä, olimme orjuutetut maailman alkeisvoimien alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Mutta kun aika täyttyi, Jumala lähetti Poikansa, vaimosta syntyneen, lain alaiseksi syntyneen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'lunastamaan lain alaiset, että saisimme lapsen aseman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Mutta koska olette lapsia, Jumala on lähettänyt sydämiinne Poikansa Hengen, joka huutaa: \"Abba! Isä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Niinpä et siis enää ole orja, vaan lapsi. Mutta jos olet lapsi, olet myös perillinen Jumalan kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Mutta silloin, kun ette tunteneet Jumalaa, palvelitte jumalia, jotka eivät ole luonnoltaan jumalia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Nyt sitä vastoin, kun olette tulleet tuntemaan Jumalan – paremminkin, kun Jumala tuntee teidät, – kuinka te jälleen käännytte noiden heikkojen ja köyhien alkeisvoimien puoleen, joiden orjiksi tahdotte taas uudestaan tulla?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Te otatte vaarin päivistä, kuukausista, juhla-ajoista ja vuosista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Pelkään teidän tähtenne, että olen ehkä nähnyt turhaan teistä vaivaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Tulkaa kaltaisikseni, koska minäkin olen kuin te, veljet, sitä teiltä pyydän. Ette ole minua millään tavoin loukanneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Tiedättehän, että lihan heikkouden tähden ensi kerralla julistin teille evankeliumia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'Mutta te ette halveksineet ettekä hylkineet minun koetustani lihassa, vaan otitte minut vastaan kuin Jumalan enkelin, jopa kuin Kristuksen Jeesuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Kuinka autuaita te silloin olitte? Sillä minä annan teistä sen todistuksen, että te, jos olisi ollut mahdollista, olisitte kaivaneet silmät päästänne ja antaneet minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Onko minusta siis tullut teidän vihamiehenne sen tähden, että puhun teille totuuden?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Heillä on intoa teidän hyväksenne, mutta ei oikeaa, vaan he tahtovat eristää teidät, että teillä olisi intoa heidän hyväkseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'On hyvä olla innokas aina hyvässä, eikä ainoastaan silloin, kun olen teidän luonanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Lapsukaiseni, jotka minun täytyy jälleen kivulla synnyttää, kunnes Kristus saa muodon teissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'tahtoisinpa nyt olla teidän luonanne ja äänenikin muuttaa! Sillä olen teistä aivan ymmällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Sanokaa minulle te, jotka tahdotte olla lain alaisia, ettekö kuule lakia?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Onhan kirjoitettu, että Aabrahamilla oli kaksi poikaa, toinen orjattaresta, toinen vapaasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Mutta orjattaren poika oli syntynyt lihan mukaan, vapaan taas lupauksen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Tämä on kuvaannollista puhetta: naiset ovat kaksi liittoa: toinen on Siinain vuorelta, joka synnyttää orjuuteen, ja se on Haagar.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Haagar on näet Siinain vuori Arabiassa ja vastaa nykyistä Jerusalemia, joka elää orjuudessa lapsineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Mutta se Jerusalem, joka ylhäällä on, on vapaa, ja se on meidän äitimme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Sillä kirjoitettu on: \"Iloitse, sinä hedelmätön, joka et synnytä, puhkea riemuun ja huuda sinä, jolla ei ole synnytyskipuja. Sillä yksinäisellä on paljon lapsia, enemmän kuin sillä, jolla on mies.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Mutta me, veljet, olemme Iisakin mukaan lupauksen lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Mutta niin kuin lihan mukaan syntynyt silloin vainosi Hengen mukaan syntynyttä, niin nytkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Mutta mitä sanoo Raamattu? \"Aja pois orjatar poikineen, sillä orjattaren poika ei saa periä vapaan vaimon pojan kanssa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Niin siis, veljet, emme ole orjattaren lapsia, vaan vapaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Vapauteen Kristus siis vapautti meidät. Seisokaa lujina, älkääkä antako uudestaan sitoa itseänne orjuuden ikeeseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Katso, minä, Paavali, sanon teille, että jos ympärileikkautatte itsenne, Kristus ei ole teille miksikään hyödyksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Mutta todistan taas jokaiselle ihmiselle, joka ympärileikkauttaa itsensä, että hän on velvollinen täyttämään koko lain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Olette joutuneet pois Kristuksesta, te, jotka tahdotte lain kautta tulla vanhurskaiksi, olette langenneet pois armosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Sillä me odotamme Hengessä uskosta vanhurskauden toivoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Sillä Kristuksessa Jeesuksessa ei auta ympärileikkaus eikä ympärileikkaamattomuus, vaan usko, joka vaikuttaa rakkauden kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Te juoksitte hyvin, kuka esti teitä noudattamasta totuutta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Houkutus siihen ei ole hänestä, joka teitä kutsuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Vähäinen hapate hapattaa koko taikinan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Minulla on teihin se luottamus Herrassa, ettette missään kohden tule ajattelemaan toisin. Mutta teidän eksyttäjänne saa kantaa tuomionsa, olkoon kuka hyvänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Mutta jos minä, veljet, vielä saarnaan ympärileikkausta, miksi minua vielä vainotaan? Silloinhan ristin pahennus olisi poistettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Kunpa teidän kiihottajanne leikkaisivat itsensä pois!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Te olette näet kutsutut vapauteen, veljet, älkää vain salliko vapauden tuoda tilaisuutta lihalle, vaan palvelkaa toisianne rakkaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Sillä kaikki laki on täytetty yhdessä sanassa, tässä: \"Rakasta lähimmäistäsi niin kuin itseäsi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Mutta jos te purette ja syötte toisianne, katsokaa, ettette toinen toistanne hävitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Sanon: vaeltakaa Hengessä, niin ette lihan himoa täytä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Sillä liha himoitsee Henkeä vastaan, ja Henki lihaa vastaan. Nämä ovat nimittäin toisiaan vastaan, niin ettette tee sitä, mitä tahdotte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Mutta jos olette Hengen kuljetettavina, ette ole lain alla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Mutta lihan teot ovat ilmeiset, ja niitä ovat: aviorikos, haureus, saastaisuus, irstaus,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'epäjumalanpalvelus, noituus, vihamielisyys, riita, kateuden teot, vihat, juonet, eriseurat, lahkot,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'kateus, juomingit, ylensyömiset ja muut sellaiset, joista teille edeltäpäin sanon, niin kuin jo ennenkin olen sanonut, että ne, jotka sellaista harjoittavat, eivät peri Jumalan valtakuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Mutta Hengen hedelmä on rakkaus, ilo, rauha, pitkämielisyys, ystävällisyys, hyvyys, uskollisuus, sävyisyys, itsehillintä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'Sellaista vastaan ei ole laki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Mutta ne, jotka ovat Kristuksen Jeesuksen omat, ovat ristiinnaulinneet lihansa himoineen ja haluineen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Jos Hengessä elämme, Hengessä myös vaeltakaamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Älkäämme olko turhan kunnian pyytäjiä, niin että toisiamme ärsytämme, toisiamme kadehdimme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Veljet, jos joku tavataan jostakin rikoksesta, ojentakaa te, hengelliset, häntä sävyisyyden hengessä, ja ole varuillasi, ettet sinäkin joutuisi kiusaukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Kantakaa toistenne kuormia, ja niin täytätte Kristuksen lain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Sillä jos joku luulee olevansa jotakin, vaikka ei ole mitään, hän pettää itsensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Mutta tutkikoon kukin omat tekonsa, ja silloin hänen kerskaamisensa on vain siinä, mitä hän itse on, ei siinä, mitä toinen on,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'sillä jokaisen on kannettava oma taakkansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Mutta se, jolle sanaa opetetaan, jakakoon kaikkea hyvää opettajalleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Älkää eksykö, Jumala ei salli itseään pilkata, sillä mitä ihminen kylvää, sitä hän myös niittää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Se, joka lihaansa kylvää, lihasta turmeluksen niittää, mutta se, joka Henkeen kylvää, Hengestä iankaikkisen elämän niittää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Kun hyvää teemme, älkäämme lannistuko, sillä saamme ajan tullen niittää, jos emme väsy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Sen tähden, kun meillä vielä on aikaa, tehkäämme hyvää kaikille, mutta varsinkin uskon perheväelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Katsokaa, kuinka suurilla kirjaimilla omakätisesti teille kirjoitan!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Kaikki ne, jotka pyrkivät lihassa olemaan mieliksi, pakottavat teitä ympärileikkauttamaan itsenne vain siksi, ettei heitä Kristuksen ristin tähden vainottaisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Eiväthän nekään, jotka ympärileikkauttavat itsensä, itse noudata lakia, vaan he tahtovat teitä ympärileikkauttamaan itsenne saadakseen kerskua lihastanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Mutta pois se minusta, että minä muusta kerskaan kuin meidän Herramme Jeesuksen Kristuksen rististä, jonka kautta maailma on ristiinnaulittu minulle, ja minä maailmalle!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Sillä Kristuksessa Jeesuksessa ei ympärileikkaus ole mitään eikä ympärileikkaamattomuus, vaan uusi luomus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'Kaikille, jotka tämän säännön mukaan vaeltavat, kaikille heille rauha ja laupeus, ja Jumalan Israelille!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Tästedes älköön kukaan tuottako minulle vaivoja, sillä minä kannan Jeesuksen arpia ruumiissani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Meidän Herramme Jeesuksen Kristuksen armo olkoon teidän henkenne kanssa, veljet. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paavali, Jumalan tahdosta Kristuksen Jeesuksen apostoli, pyhille, jotka ovat Efesossa, ja uskoville Kristuksessa Jeesuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Armo teille ja rauha Jumalalta, Isältämme, ja Herralta Jeesukselta Kristukselta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Ylistetty olkoon Herramme Jeesuksen Kristuksen Jumala ja Isä, joka on siunannut meitä kaikella hengellisellä siunauksella taivaallisissa Kristuksessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'niin kuin hän ennen maailman perustamista oli hänessä valinnut meidät olemaan pyhiä ja moitteettomia hänen edessään, rakkaudessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'edeltä määräten meidät lapseuteen hänelle itselleen Jeesuksen Kristuksen kautta, hänen oman tahtonsa mielisuosion mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'sen armonsa kirkkauden kiitokseksi, jonka hän on lahjoittanut meille siinä rakastetussa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'jossa meillä on lunastus hänen verensä kautta, rikkomisten anteeksisaaminen hänen armonsa rikkauden mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'jota hän on antanut ylenpalttisesti meitä varten suodakseen kaikkea viisautta ja ymmärrystä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'tehden meille tiettäväksi tahtonsa salaisuuden mielisuosionsa mukaan, jonka hän oli säätänyt edeltä itsessään toteutuvaksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'että hän aikojen täytyttyä tapahtuvaa armotaloutta varten yhdistäisi Kristuksessa yhdeksi kaikki, mikä on taivaissa ja mikä maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'Hänessä myös olemme saaneet perintöosan, ollen siihen edeltä määrätyt hänen suunnitelmansa mukaan, hänen, joka vaikuttaa kaiken oman tahtonsa ja päätöksensä mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'että me olisimme hänen kirkkautensa kiitokseksi, me, jotka jo edeltä olimme panneet toivomme Kristukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'Hänessä on teihinkin, sitten kun olitte kuulleet totuuden sanan, pelastuksenne evankeliumin, uskoviksi tultuanne pantu luvatun Pyhän Hengen sinetti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'sen, joka on meidän perintömme vakuutena, hänen omaisuutensa lunastamista varten hänen kirkkautensa kiitokseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Sen tähden, kun kuulin siitä uskosta, joka teillä on Herraan Jeesukseen, ja teidän rakkaudestanne kaikkia pyhiä kohtaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'minäkään en lakkaa kiittämästä teidän tähtenne, kun muistelen teitä rukouksissani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'anoen, että meidän Herramme Jeesuksen Kristuksen Jumala, kirkkauden Isä, antaisi teille viisauden ja ilmoituksen Hengen hänen tuntemisessaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'ja valaisisi teidän sydämenne silmät, että tietäisitte, mikä on se toivo, johon hän on teidät kutsunut, kuinka suuri hänen perintönsä kirkkauden runsaus hänen pyhissään');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'ja mikä hänen voimansa ylenpalttinen suuruus meitä uskovia kohtaan sen hänen väkevyytensä voiman vaikutuksen mukaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'jonka hän vaikutti Kristuksessa, kun hän herätti hänet kuolleista ja asetti hänet istumaan oikealle puolelleen taivaissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'korkeammalle kaikkea hallitusta, valtaa, voimaa, herruutta ja jokaista nimeä, mikä mainitaan, ei ainoastaan tässä maailmanajassa, vaan myös tulevassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'Kaiken hän on asettanut hänen jalkojensa alle ja antanut hänet kaiken pääksi seurakunnassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'joka on hänen ruumiinsa, sen täyteys, joka kaiken kaikessa täyttää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Jumala on eläviksi tehnyt teidät, jotka olitte kuolleet rikoksiinne ja synteihinne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'joissa te ennen vaelsitte tämän maailman menon mukaan, ilmapiirin hallitsijan, sen hengen hallitsijan, mukaan, joka nyt tekee työtään epäuskon lapsissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'joiden joukossa mekin kaikki ennen vaelsimme lihamme himoissa, noudattaen lihan ja järjen tahtoa, ja olimme luonnostamme vihan lapsia kuten muutkin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'mutta Jumala, joka on laupeudesta rikas, suuren rakkautensa tähden, jolla hän on meitä rakastanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'on tehnyt meidät, jotka olimme kuolleet rikoksiimme, eläviksi Kristuksen kanssa – armosta te olette pelastetut –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'ja yhdessä hänen kanssaan herättänyt ja yhdessä hänen kanssaan asettanut meidät taivaallisiin Kristuksessa Jeesuksessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'osoittaakseen tulevina maailmanaikoina armonsa ylenpalttista runsautta, hyvyydessään meitä kohtaan Kristuksessa Jeesuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Sillä armosta te olette pelastetut uskon kautta. Se ei ole teistä. Se on Jumalan lahja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Se ei ole teoista, ettei kukaan kerskaisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Sillä olemme hänen tekonsa, luodut Kristuksessa Jeesuksessa hyviä töitä varten, jotka Jumala on edeltäpäin valmistanut, jotta niissä vaeltaisimme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Muistakaa sen tähden, että te ennen, te lihanne puolesta pakanat, jotka olette saaneet ympärileikkaamattomien nimen niiltä, joita lihaan käsillä tehdyn ympärileikkauksen mukaisesti sanotaan ympärileikatuiksi –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'että te siihen aikaan olitte ilman Kristusta, olitte vailla Israelin kansalaisoikeutta ja vieraat lupauksen liitoille, ilman toivoa ja ilman Jumalaa maailmassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Mutta nyt, kun olette Kristuksessa Jeesuksessa, olette te, jotka ennen olitte kaukana, tulleet lähelle Kristuksen veressä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Sillä hän on meidän rauhamme, hän, joka teki molemmat yhdeksi ja purki erottavan väliseinän, nimittäin vihollisuuden,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'kun hän lihassaan teki tehottomaksi käskyjen lain säädöksineen, luodakseen itsessään nuo kaksi yhdeksi uudeksi ihmiseksi, tehden rauhan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'ja yhdessä ruumiissa sovittaakseen molemmat Jumalan kanssa ristin kautta kuolettaen itsessään vihollisuuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Ja hän tuli ja julisti rauhaa teille, jotka olitte kaukana, ja rauhaa niille, jotka olitte lähellä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'sillä hänen kauttaan meillä molemmilla on pääsy yhdessä Hengessä Isän luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Niin ette siis enää ole vieraita ettekä muukalaisia, vaan olette pyhien kansalaisia ja Jumalan perheväkeä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'apostolien ja profeettojen perustukselle rakennettuja, kulmakivenä itse Kristus Jeesus,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'jossa koko rakennus liittyy yhteen ja kasvaa pyhäksi temppeliksi Herrassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'ja hänessä tekin yhdessä muitten kanssa rakennutte Jumalan asumukseksi Hengessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Sen takia minä, Paavali, teidän, pakanoiden, tähden Kristuksen Jeesuksen vanki, notkistan polveni –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'olettehan kuulleet siitä Jumalan armon taloudenhoidosta, mikä on minulle annettu teitä varten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'että näet tämä salaisuus on ilmoituksen kautta tehty minulle tiettäväksi, niin kuin olen siitä edellä lyhyesti kirjoittanut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'josta te sitä lukiessanne voitte havaita perehtyneisyyteni Kristuksen salaisuuteen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'jota muiden sukupolvien aikana ei ole ihmisten lapsille tiettäväksi tehty, niin kuin se nyt on ilmoitettu Hengessä hänen pyhille apostoleilleen ja profeetoille:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'että näet pakanatkin ovat kanssaperillisiä ja yhtä ruumista ja osallisia lupaukseen Kristuksessa Jeesuksessa evankeliumin kautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'jonka palvelijaksi olen tullut Jumalan armon lahjan kautta, joka minulle on annettu hänen voimansa vaikutuksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Minulle, kaikista pyhistä halvimmalle, on annettu tämä armo: julistaa pakanoiden keskuudessa evankeliumia Kristuksen tutkimattomasta rikkaudesta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'ja tehdä kaikille selväksi, mitä on sen salaisuuden taloudenhoito, joka ikuisista ajoista asti on ollut kätkettynä Jumalassa, joka on kaiken luonut Jeesuksen Kristuksen kautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'että Jumalan moninainen viisaus seurakunnan kautta nyt tulisi taivaallisten hallitusten ja valtojen tietoon');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'sen iankaikkisen päätöksen mukaisesti, jonka hän oli säätänyt Kristuksessa Jeesuksessa, meidän Herrassamme,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'jossa meillä uskon kautta häneen on rohkeus ja oikeus lähestyä häntä luottamuksella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Siksi pyydän, ettette lannistuisi niiden ahdistusten vuoksi, joita minulla on teidän tähtenne. Ne ovat teidän kunnianne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Sen tähden notkistan polveni Herramme Jeesuksen Kristuksen Isän edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'josta kaikki, millä isä on, taivaissa ja maan päällä, saa nimensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'että hän kirkkautensa runsauden mukaisesti antaisi teidän, sisäisen ihmisenne puolesta, voimassa vahvistua Henkensä kautta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'ja Kristuksen asua uskon kautta teidän sydämissänne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'jotta rakkauteen juurtuneina ja perustuneina voisitte kaikkien pyhien kanssa käsittää, mikä leveys, pituus, korkeus ja syvyys on,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'ja oppia tuntemaan Kristuksen rakkauden, joka ylittää kaiken tiedon, että tulisitte täyteen Jumalan kaikkea täyteyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Mutta hänelle, joka voi tehdä enemmän, monin verroin enemmän kuin kaikki, mitä anomme tai ymmärrämme, sen voiman mukaan, joka meissä vaikuttaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'hänelle kunnia seurakunnassa ja Kristuksessa Jeesuksessa kautta kaikkien sukupolvien, iankaikkisuuden iankaikkisuuksiin! Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Kehotan siis minä, vanki Herrassa, teitä vaeltamaan kutsumuksenne arvon mukaisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'kaikessa nöyryydessä ja lempeydessä pitkämielisesti sietäen toinen toistanne rakkaudessa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'ja pyrkien säilyttämään hengen yhteyden rauhan yhdyssiteellä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'yksi ruumis ja yksi henki, kuten olette kutsututkin yhteen ja samaan kutsumuksenne antamaan toivoon;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'yksi Herra, yksi usko, yksi kaste;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'yksi Jumala ja kaikkien Isä, joka on yli kaikkien, kaikkien kautta ja kaikissa teissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Mutta itse kullekin meistä on armo annettu Kristuksen lahjan mitan mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Sen tähden on sanottu: \"Hän astui ylös korkeuteen, hän otti vankeja saaliikseen, hän antoi lahjoja ihmisille.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Mutta että hän astui ylös, mitä se on muuta, kuin että hän oli astunut alaskin, maan alimpiin paikkoihin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Hän, joka on astunut alas, on se, joka myös astui ylös, kaikkia taivaita ylemmäksi, täyttääkseen kaiken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'Ja hän antoi muutamat apostoleiksi, toiset profeetoiksi, toiset evankelistoiksi, mutta toiset paimeniksi ja opettajiksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'varustaakseen pyhät palveluksen työhön, Kristuksen ruumiin rakentamiseen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'kunnes kaikki pääsemme uskon yhteyteen ja Jumalan Pojan tuntemiseen, täydelliseksi mieheksi, Kristuksen täyteyden täysi-ikäisyyden määrään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'ettemme enää olisi alaikäisiä, jotka ajelehtivat ja joita viskellään kaikissa opintuulissa ja ihmisten arpapelissä ja eksytyksen kavalissa juonissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'vaan että totuutta noudattaen rakkaudessa kaikessa kasvaisimme häneen, joka on pää, Kristus,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'josta koko ruumis yhteen liitettynä ja koossa pysyen jokaisen jänteensä avulla kasvaa rakentuakseen rakkaudessa sen voiman määrän mukaan, mikä kullakin osalla on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Sen siis sanon ja todistan Herrassa: älkää enää vaeltako, niin kuin muut pakanat vaeltavat mielensä turhuudessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'nuo, jotka pimentyneinä ymmärrykseltään ja vieraantuneina Jumalan elämästä heissä olevan tietämättömyyden tähden ja sydämensä paatumuksen tähden');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'ovat tuntonsa paaduttaneet ja heittäytyneet irstauden valtaan harjoittamaan kaikenlaista saastaisuutta ahneudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Mutta näin te ette ole oppineet Kristusta tuntemaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'jos muuten olette hänestä kuulleet ja hänessä opetusta saaneet, niin kuin totuus on Jeesuksessa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'että teidän tulee panna pois vanha ihmisenne, jonka mukaan ennen vaelsitte ja joka turmelee itsensä petollisia himoja seuraten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'ja uudistua mielenne hengeltä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'ja pukea päällenne uusi ihminen, joka Jumalan mukaan on luotu totuuden vanhurskauteen ja pyhyyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Pankaa sen tähden pois valhe ja puhukaa totta, kukin lähimmäisensä kanssa, sillä olemme toistemme jäseniä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, '\"Vihastukaa, mutta älkää syntiä tehkö.\" Älkää antako auringon laskea vihanne yli,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'älkääkä antako perkeleelle sijaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Joka on varastanut, älköön enää varastako, vaan tehköön ennemmin työtä ja toimittakoon käsillään sitä, mikä hyvää on, että hänellä olisi, mitä antaa tarvitsevalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Mikään sopimaton puhe älköön lähtekö suustanne, vaan ainoastaan sellainen, mikä rakentaa ja on tarpeellista sekä mieluista niille, jotka kuulevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'Älkääkä saattako murheelliseksi Jumalan Pyhää Henkeä, jolla teidät on sinetöity lunastuksen päivään asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Kaikki katkeruus, kiivastus, viha, huuto ja pilkka sekä kaikki pahuus olkoon kaukana teistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Olkaa sen sijaan toisianne kohtaan ystävällisiä, hyväsydämisiä, anteeksiantavaisia toinen toisellenne, niin kuin Jumalakin on Kristuksessa teille antanut anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Olkaa siis Jumalan seuraajia, niin kuin rakkaat lapset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'ja vaeltakaa rakkaudessa, niin kuin Kristuskin rakasti teitä ja antoi itsensä meidän edestämme lahjaksi ja uhriksi, Jumalalle \"suloiseksi tuoksuksi\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Mutta haureutta eikä minkäänlaista saastaisuutta tai ahneutta älköön edes mainittako keskuudessanne – niin kuin pyhille sopii –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'älköön myöskään rivoutta, tyhmyyksiä tai ilvehtimistä, jotka ovat sopimattomia, vaan pikemminkin kiitosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Sillä sen te tiedätte ja tunnette, ettei yhdelläkään haureellisella eikä saastaisella eikä ahneella – sillä hän on epäjumalanpalvelija – ole perintöosaa Kristuksen ja Jumalan valtakunnassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Älköön kukaan pettäkö teitä tyhjillä puheilla, sillä niiden tähden Jumalan viha tulee tottelemattomuuden lasten päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Älkää siis olko niihin osallisia heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Ennen te olitte pimeys, mutta nyt olette valkeus Herrassa. Vaeltakaa valkeuden lapsina');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '– sillä kaikki hyvyys, vanhurskaus ja totuus on Hengen hedelmää –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'ja tutkikaa, mikä on otollista Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'Älkää myöskään olko osallisia pimeyden hedelmättömiin tekoihin, vaan päinvastoin nuhdelkaakin niistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Sillä häpeällistä on sanoakin, mitä he salassa tekevät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Mutta tämä kaikki tulee ilmi, kun valkeus siitä nuhtelee, sillä kaikki, mikä tulee ilmi, on valkeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Sen tähden sanotaan: \"Herää sinä, joka nukut, ja nouse kuolleista, niin Kristus sinua valaisee!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Katsokaa siis tarkoin, kuinka vaellatte: ei niin kuin tyhmät, vaan niin kuin viisaat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'ja ottakaa vaari oikeasta hetkestä, sillä aika on paha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Älkää sen tähden olko tyhmiä, vaan ymmärtäkää, mikä Herran tahto on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Älkääkä juopuko viinistä, sillä siitä tulee paha meno, vaan täyttykää Hengellä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'puhuen keskenänne psalmeilla, kiitosvirsillä ja hengellisillä lauluilla veisaten ja laulaen sydämessänne Herralle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'kiittäen aina Jumalaa ja Isää kaikesta meidän Herramme Jeesuksen Kristuksen nimessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Ja olkaa toinen toisellenne alamaisia Kristuksen pelossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Vaimot, olkaa kukin omalle miehellenne alamaisia niin kuin Herralle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'sillä mies on vaimon pää, niin kuin myös Kristus on seurakunnan pää, hän, ruumiin vapahtaja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Mutta niin kuin seurakunta on Kristukselle alamainen, samoin olkoot vaimotkin kukin miehelleen kaikessa alamaiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Miehet, rakastakaa vaimoanne, niin kuin Kristuskin rakasti seurakuntaa ja antoi itsensä alttiiksi sen edestä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'että hän sen pyhittäisi puhdistaen sen vesipesussa sanalla');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'saadakseen asetetuksi eteensä kirkastettuna seurakunnan, jossa ei olisi tahraa eikä ryppyä eikä mitään muuta sellaista, vaan joka olisi pyhä ja nuhteeton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Samalla tavoin tulee myös miesten rakastaa vaimoaan kuin omaa ruumistaan. Se, joka rakastaa vaimoaan, rakastaa itseään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Sillä eihän kukaan koskaan ole vihannut omaa lihaansa, vaan hän ravitsee ja vaalii sitä, niin kuin Kristuskin seurakuntaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'sillä me olemme hänen ruumiinsa jäseniä hänen lihastaan ja hänen luistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, '\"Sen tähden mies luopukoon isästään ja äidistään ja liittyköön vaimoonsa, ja ne kaksi tulevat yhdeksi lihaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Tämä salaisuus on suuri. Mutta minä tarkoitan Kristusta ja seurakuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Mutta myös teistä kukin kohdaltaan rakastakoon vaimoaan samoin kuin itseään, mutta vaimo pelätköön miestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Lapset, olkaa vanhemmillenne kuuliaiset Herrassa, sillä se on oikein.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, '\"Kunnioita isääsi ja äitiäsi.\" Tämä on ensimmäinen käsky, jolla on lupaus:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, '\"että menestyisit ja kauan eläisit maan päällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Ja te isät, älkää kiihottako lapsianne vihaan, vaan kasvattakaa heidät Herran opetuksessa ja nuhteessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Palvelijat, olkaa kuuliaisia maallisille isännillenne pelolla ja vavisten sydämenne yksinkertaisuudessa kuin Kristukselle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'ei silmänpalvelijoina, ihmisille mieliksi, vaan Kristuksen palvelijoina, sydämestänne tehden Jumalan tahdon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'hyvillä mielin, kuin palvelisitte Herraa ettekä ihmisiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'tietäen, että mitä hyvää kukin tekee, hän saa siitä palkan Herralta, olkoon orja tai vapaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Ja te isännät, tehkää samoin heille, jättäkää pois uhkailu, sillä tiedättehän, että sekä heidän että teidän Herranne on taivaissa ja ettei hän katso henkilöön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Lopuksi, vahvistukaa Herrassa ja hänen väkevyytensä voimassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Pukekaa yllenne Jumalan koko sota-asu voidaksenne kestää perkeleen kavalat juonet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Sillä meillä ei ole taistelu verta ja lihaa vastaan, vaan hallituksia vastaan, valtoja vastaan, tässä pimeydessä hallitsevia maailmanvaltiaita vastaan, pahuuden henkiolentoja vastaan taivaan avaruuksissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Sen tähden ottakaa päällenne Jumalan koko sota-asu voidaksenne pahana päivänä tehdä vastarintaa ja kaiken suoritettuanne pysyä pystyssä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Seisokaa siis lanteet totuuteen vyötettyinä, ja olkoon pukunanne vanhurskauden haarniska,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'ja kenkinä jaloissanne alttius rauhan evankeliumille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'Kaikessa ottakaa uskon kilpi, jolla voitte sammuttaa kaikki pahan palavat nuolet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'ja ottakaa vastaan pelastuksen kypärä ja Hengen miekka, joka on Jumalan sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'Ja tehkää tämä kaikella rukouksella ja anomisella rukoillen kaiken aikaa Hengessä ja sitä varten valvoen kaikessa kestävyydessä ja anomisessa kaikkien pyhien puolesta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'ja minunkin puolestani, että minulle, kun suuni avaan, annettaisiin sana rohkeasti julistaakseni evankeliumin salaisuutta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'jonka tähden olen lähettiläänä kahleissa, että puhuisin rohkeasti hänessä, niin kuin minun tulee puhua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Mutta että tekin tietäisitte, kuinka minun on ja mitä teen, niin Tykikus, rakas veljeni ja uskollinen palvelija Herrassa, antaa teille siitä kaikesta tiedon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Lähetän hänet luoksenne juuri sitä varten, että saisitte tietää tilamme ja että hän lohduttaisi sydämiänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Rauha veljille ja rakkaus, uskon kanssa, Isältä Jumalalta ja Herralta Jeesukselta Kristukselta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Armo olkoon kaikkien kanssa, jotka rakastavat meidän Herraamme Jeesusta Kristusta katoamattomuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paavali ja Timoteus, Kristuksen Jeesuksen palvelijat, kaikille pyhille Kristuksessa Jeesuksessa, jotka ovat Filipissä, sekä myös seurakunnan kaitsijoille ja diakoneille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Kiitän Jumalaani joka kerta kun teitä muistelen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'aina kaikissa rukouksissani ilolla rukoillen teidän kaikkien puolesta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'kiitän siitä, että olette olleet osallisia evankeliumiin sen ensi päivästä alkaen tähän päivään saakka,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'varmasti luottaen siihen, että hän, joka on alkanut teissä hyvän työn, on sen saattava päätökseen Kristuksen Jeesuksen päivään saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Ja oikein onkin minun näin ajatella teistä kaikista, koska olette sydämessäni, te, jotka sekä ollessani kahleissa että evankeliumia puolustaessani ja vahvistaessani olette kaikki kanssani armosta osallisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Sillä Jumala on todistajani, kuinka teitä kaikkia ikävöin Kristuksen Jeesuksen sydämellisellä rakkaudella');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'ja sitä rukoilen, että teidän rakkautenne tulisi yhä runsaammaksi tiedossa ja kaikessa käsittämisessä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'voidaksenne tutkia, mikä on parasta, että Kristuksen päivään saakka olisitte puhtaat ettekä kenellekään loukkaukseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'täynnä vanhurskauden hedelmää Jeesuksen Kristuksen kautta Jumalan kunniaksi ja ylistykseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Mutta tahdon teidän tietävän, veljet, että se, mitä minulle on tapahtunut, onkin koitunut evankeliumin menestykseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'niin että koko henkivartioston ja kaikkien muiden tietoon on tullut, että olen kahleissa Kristuksen tähden,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'ja että useimmat veljistä saaden Herrassa uskallusta kahleistani rohkenevat yhä enemmän pelkäämättä puhua Jumalan sanaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Muutamat tosin julistavat Kristusta kateudestakin ja riidan halusta, mutta toiset hyvässä tarkoituksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Ne, jotka julistavat Kristusta riidan halusta, eivät tee sitä puhtaasta mielestä ja luulevat tuottavansa minulle murhetta kahleissani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Mutta nämä tekevät sitä rakkaudesta, koska tietävät, että minut on pantu evankeliumia puolustamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Vaan mitäpä tuosta, kunhan Kristusta vain tavalla tai toisella julistetaan, joko näön vuoksi tai totuudessa! Ja siitä iloitsen ja vastakin iloitsen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Sillä tiedän, että tämä on päättyvä minulle pelastukseksi teidän rukoustenne kautta ja Jeesuksen Kristuksen Hengen avulla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'minun hartaan odotukseni ja toivoni mukaan, etten ole missään joutuva häpeään, vaan että Kristus nytkin, niin kuin aina, tulee ylistetyksi ruumiissani kaikella rohkeudella, joko elämän tai kuoleman kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Sillä eläminen on minulle Kristus ja kuoleminen on voitto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Mutta jos eläminen lihassa tuo työlleni hedelmää, en tiedä, minkä valitsen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Ahtaalla olen näiden kahden välissä: halu minulla on päästä täältä pois ja olla Kristuksen kanssa, sillä se olisi monin verroin parempi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'mutta teidän tähtenne on lihassa viipymiseni tarpeellisempaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Ja kun olen tästä varma, tiedän jääväni eloon ja viipyväni kaikkien teidän luonanne teidän edistymiseksenne ja iloksenne uskossa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'että teidän kerskaamisenne minusta olisi yhä runsaampaa Kristuksessa Jeesuksessa, kun taas tulen luoksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Käyttäytykää vain Kristuksen evankeliumin arvon mukaisesti, että tulenpa sitten luoksenne ja näen teidät tai olen tulematta, saan kuulla teistä, että pysytte samassa hengessä ja yksimielisinä taistelette kanssani evankeliumin uskon puolesta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'vastustajia missään kohden säikähtämättä. Se on heille kadotuksen, mutta teille pelastuksen merkki. Se on merkki Jumalalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Sillä teidän on suotu Kristuksen tähden, ei ainoastaan uskoa häneen, vaan myös kärsiä hänen tähtensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'teidän, joilla on sama taistelu, jota olette minulla nähneet ja nyt kuulette minulla olevan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Jos siis on jotakin kehotusta Kristuksessa, jos jotakin rakkauden lohdutusta, jos jotakin Hengen yhteyttä, jos jotakin sydämellisyyttä ja laupeutta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'niin tehkää iloni täydelliseksi niin, että ajattelette samoin, että teillä on sama rakkaus, että teillä on sama henki ja että teillä on yksi ja sama ajatus,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'ettekä tee mitään riidanhalusta tai turhan kunnian pyynnöstä, vaan että nöyryydessä pidätte toista parempana kuin itseänne');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'ja että katsotte, ette vain omaa etuanne, vaan jokainen toistenkin parasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Olkoon teillä se mieli, joka myös Kristuksella Jeesuksella oli,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'joka ei, vaikka hänellä olikin Jumalan muoto, katsonut saaliikseen olla Jumalan kaltainen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'vaan tyhjensi itsensä ottamalla orjan muodon, tuli ihmisten kaltaiseksi, ja hänet havaittiin olemukseltaan sellaiseksi kuin ihminen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'Hän nöyryytti itsensä ja oli kuuliainen kuolemaan asti, aina ristin kuolemaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Sen tähden onkin Jumala hänet korkealle korottanut ja antanut hänelle nimen, kaikkia muita nimiä korkeamman,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'jotta kaikki polvet notkistuisivat Jeesuksen nimeen, sekä niiden, jotka taivaissa ovat, että niiden, jotka maan päällä ovat, ja niiden, jotka maan alla ovat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'ja jokainen kieli tunnustaisi Isän Jumalan kunniaksi, että Jeesus Kristus on Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Siis, rakkaani, samoin kuin aina olette olleet kuuliaisia, niin ahkeroikaa, ei ainoastaan ollessani teidän luonanne, vaan paljoa enemmän nyt ollessani poissa, pelolla ja vavistuksella, että pelastuisitte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Sillä Jumala on se, joka teissä vaikuttaa sekä tahtomisen että tekemisen, että hänen hyvä tahtonsa tapahtuisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Tehkää kaikki nurisematta ja järkeilemättä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'jotta olisitte moitteettomia ja puhtaita, olisitte tahrattomia Jumalan lapsia kieron ja nurjan sukukunnan keskellä, joiden joukossa te loistatte kuin tähdet maailmassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'tarjolla pitäessänne elämän sanaa minulle kerskaukseksi Kristuksen päivänä siitä, etten ole turhaan juossut enkä turhaan vaivaa nähnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Vaikka minut vuodatettaisiin juomauhriksi toimittaessani palvelusta uskonne hyväksi, iloitsen kuitenkin ja iloitsen kaikkien teidän kanssanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Siitä tekin iloitkaa, ja iloitkaa kanssani!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Toivon Herrassa Jeesuksessa pian voivani lähettää Timoteuksen luoksenne, että minäkin tulisin rohkaistuksi, kun saan tietää, kuinka teidän on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Sillä minulla ei ole ketään samanmielistä, joka huolehtisi vilpittömästi tilastanne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'sillä kaikki he etsivät omaansa eivätkä sitä, mikä on Kristuksen Jeesuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Mutta hänen koetellun mielensä tunnette, että, niin kuin poika isänsä rinnalla hän on palvellut kanssani evankeliumin hyväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Hänet siis toivon voivani lähettää heti, kun olen saanut nähdä, miten minun käy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Ja luotan Herrassa, että itsekin olen pian tuleva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Katson kuitenkin välttämättömäksi lähettää luoksenne veljeni, työtoverini ja taistelutoverini Epafroditoksen, teidän lähettinne ja palvelijanne tarpeissani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Sillä hän ikävöi teitä kaikkia ja on kovin levoton siitä, että olitte kuulleet hänen olevan sairaana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'Ja hän olikin sairaana, kuoleman kielissä, mutta Jumala armahti häntä, eikä ainoastaan häntä, vaan myös minua, etten saisi murhetta murheen päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Lähetän hänet sen tähden mitä kiireimmin, että te hänet nähdessänne taas iloitsisitte ja minäkin olisin murheettomampi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Ottakaa siis hänet vastaan Herrassa kaikella ilolla, ja pitäkää sellaisia kunniassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Sillä Kristuksen työn tähden hän joutui aivan kuoleman partaalle, kun pani henkensä alttiiksi tehdäkseen minulle sen palveluksen, mikä teiltä puuttui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Sitten vielä, veljeni, iloitkaa Herrassa! Samoista asioista teille kirjoittaminen ei kyllästytä minua, ja teille se on turvaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Varokaa noita koiria, varokaa noita pahoja työntekijöitä, varokaa noita leikeltyjä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Sillä me olemme ympärileikattuja, me, jotka Jumalan Hengessä palvelemme Jumalaa ja kerskaamme Kristuksessa Jeesuksessa, emmekä luota lihaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'vaikka minulla on, mihin luottaa lihassakin. Jos kuka muu luulee voivansa luottaa lihaan, niin voin vielä enemmän minä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'joka olen ympärileikattu kahdeksanpäiväisenä ja olen Israelin kansaa, Benjaminin sukukuntaa, heprealainen heprealaisista, lakiin nähden fariseus,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'intoon nähden seurakunnan vainooja, lain vanhurskauteen nähden nuhteeton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Mutta mikä minulle oli voitto, sen olen lukenut tappioksi Kristuksen tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Niinpä todella luen kaikki tappioksi tuon hyvin kalliin, Kristuksen Jeesuksen, minun Herrani, tuntemisen rinnalla, sillä hänen tähtensä minä olen menettänyt kaiken ja pidän sen roskana, jotta voittaisin omakseni Kristuksen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'ja minun havaittaisiin olevan hänessä ja omistavan, ei omaa vanhurskautta, sitä, joka laista tulee, vaan sen, joka tulee uskon kautta Kristukseen, sen vanhurskauden, joka tulee Jumalasta uskolle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'tunteakseni hänet ja hänen ylösnousemisensa voiman ja hänen kärsimystensä osallisuuden tullakseni hänen kuolemansa kaltaiseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'kunhan jollain tavalla pääsen ylösnousemiseen kuolleista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Ei niin, että jo olisin sen omakseni saanut tai että jo olisin täydellinen, vaan pyrin saamaan sen omakseni, koska Kristus Jeesus on ottanut omakseen minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Veljet, minä en katso sitä vielä omistavani. Mutta yhden teen: unohtaen sen, mikä on takana, ja kurottautuen sitä kohti, mikä on edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'minä riennän maaliin saamaan voittopalkinnon, johon Jumala on minut taivaallisella kutsumisella kutsunut Kristuksessa Jeesuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Olkoon siis meillä, niin monta kuin meitä on täydellistä, tämä mieli, ja jos teillä on jossakin kohden toinen mieli, Jumala on teille senkin ilmoittava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Kunhan vain, mihin saakka olemme ehtineetkin, vaellamme säännön mukaan ja ajattelemme samoin!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Olkaa minun seuraajiani, veljet, ja katselkaa niitä, jotka näin vaeltavat, niin kuin me olemme teille esikuvana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Sillä monet, joista usein olen sen teille sanonut ja nyt aivan itkien sanon, vaeltavat Kristuksen ristin vihollisina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'Heidän loppunsa on kadotus, vatsa on heidän jumalansa, heidän kunnianaan on heidän häpeänsä, ja maallisiin on heidän mielensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Meidän kansalaisuutemme näet on taivaissa, ja sieltä myös odotamme Vapahtajaa, Herraa Jeesusta Kristusta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'joka on muuttava alennustilamme ruumiin olemuksen kirkkautensa ruumiin kaltaiseksi sillä voimallaan, jolla hän myös voi tehdä kaiken itselleen alamaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Sen tähden, rakkaat ja ikävöidyt veljeni, te, minun iloni ja kruununi, seisokaa näin lujina Herrassa, rakkaat!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Euodiaa kehotan ja Syntykeä kehotan olemaan yksimielisiä Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Myös sinua, oikea Synsygukseni, pyydän: ole avuksi näille naisille, sillä he ovat taistelleet kanssani evankeliumin hyväksi yhdessä sekä Klemensin että muiden työtoverieni kanssa, joiden nimet ovat elämän kirjassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Iloitkaa aina Herrassa! Vieläkin sanon: iloitkaa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Tulkoon lempeytenne kaikkien ihmisten tietoon. Herra on lähellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Älkää murehtiko mistään, vaan saattakaa kaikessa pyyntönne rukouksella ja anomisella kiitoksen kanssa tietoon Jumalan edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'ja Jumalan rauha, joka on kaikkea ymmärrystä ylempi, on varjeleva sydämenne ja ajatuksenne Kristuksessa Jeesuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Ja vielä, veljet, kaikki, mikä on totta, mikä kunnioitettavaa, mikä oikeaa, mikä pyhää, mikä rakastettavaa, millä on hyvä maine, jos on jokin hyve ja jos on jotakin kiitettävää, sitä ajatelkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Tehkää sitä, mitä olette myös minulta oppineet, vastaanottaneet, kuulleet ja minussa nähneet, niin rauhan Jumala on oleva teidän kanssanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Ilahduin suuresti Herrassa, että olitte vihdoin uudestaan alkaneet pitää minusta huolta, jota olitte ennenkin ajatelleet, mutta teillä ei ollut ollut siihen tilaisuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Ei niin, että sanon tämän puutteen vuoksi. Sillä olen oppinut tyytymään oloihini.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Osaan elää niukkuudessa, osaan myös elää runsaudessa. Kaikkeen ja kaikenlaisiin oloihin olen tottunut, sekä olemaan ravittuna että näkemään nälkää, elämään sekä runsaudessa että puutteessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Kaikki voin hänessä, joka minua vahvistaa Kristuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Kuitenkin teitte hyvin, kun otitte osaa ahdinkooni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Tiedättehän tekin, filippiläiset, että evankeliumin alussa, kun lähdin Makedoniasta, mikään muu seurakunta kuin te yksin ei osallistunut kanssani tilinpitoon annetusta ja vastaanotetusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Sillä Tessalonikaankin minulle kerran, jopa kahdesti, lähetitte, mitä tarvitsin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Ei niin, että haluaisin lahjaa, vaan haluan teidän hyväksenne karttuvaa hedelmää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Olen nyt saanut kaikkea, jopa ylenpalttisesti. Minulla on yllin kyllin saatuani Epafroditukselta lähetyksenne, \"suloisen tuoksun\", otollisen, Jumalalle mieluisen uhrin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Mutta Jumalani on täyttävä kaikki tarpeenne rikkautensa mukaisesti kirkkaudessa, Kristuksessa Jeesuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Mutta meidän Jumalallemme ja Isällemme kunnia iäisyyksien iäisyyksiin! Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Tervehtikää jokaista pyhää Kristuksessa Jeesuksessa. Tervehdyksen lähettävät teille kanssani olevat veljet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Tervehdyksen lähettävät teille kaikki pyhät, mutta varsinkin ne, jotka ovat keisarin hovista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Herran Jeesuksen Kristuksen armo olkoon teidän henkenne kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paavali, Jumalan tahdosta Kristuksen Jeesuksen apostoli, ja veli Timoteus');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'Kolossassa asuville pyhille ja uskoville veljille Kristuksessa. Armo teille ja rauha Jumalalta, meidän Isältämme!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Kiitämme Jumalaa, Herramme Jeesuksen Kristuksen Isää, aina kun rukoilemme teidän edestänne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'kuultuamme uskostanne Kristukseen Jeesukseen ja rakkaudesta, mikä teillä on kaikkia pyhiä kohtaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'sen toivon tähden, joka on talletettuna teille taivaissa ja josta jo ennen olette kuulleet sen evankeliumin totuuden sanassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'joka on tullut luoksenne, niin kuin se on myös kaikessa maailmassa ja kantaa hedelmää, samoin kuin teidänkin keskuudessanne siitä päivästä alkaen, jona kuulitte ja opitte tuntemaan Jumalan armon totuudessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'niin kuin te opitte sen Epafraalta, rakkaalta kanssapalvelijaltamme, joka on uskollinen Kristuksen palvelija teidän hyväksenne');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'ja joka myös on kertonut meille rakkaudestanne Hengessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Sen tähden emme mekään, siitä päivästä alkaen, jona sen kuulimme, ole lakanneet rukoilemasta ja anomasta teidän edestänne, että tulisitte täyteen hänen tahtonsa tuntemista kaikessa hengellisessä viisaudessa ja ymmärtämisessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'vaeltaaksenne Herran edessä arvollisesti, hänelle kaikessa mieliksi, kaikessa hyvässä työssä hedelmää kantaen ja kasvaen Jumalan tuntemiseen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'ja hänen kirkkautensa väkevyyden mukaan kaikella voimalla vahvistettuina olemaan kaikessa kestäviä ja pitkämielisiä ilolla');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'kiittäen Isää, joka on tehnyt teidät soveliaiksi pyhien perintöosaan valkeudessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'häntä, joka on pelastanut meidät pimeyden vallasta ja siirtänyt meidät rakkaan Poikansa valtakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'Hänessä meillä on lunastus, syntien anteeksiantaminen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'ja hän on näkymättömän Jumalan kuva, esikoinen ennen kaikkea luomakuntaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Sillä hänessä luotiin kaikki, mitä on taivaissa ja mitä on maan päällä, näkyvät ja näkymättömät, olkoot valtaistuimia, herruuksia, hallituksia tai valtoja, kaikki on luotu hänen kauttaan ja häntä varten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'ja hän on ennen kaikkia, ja kaikki pysyy hänessä voimassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'Ja hän on ruumiin, se on: seurakunnan, pää, hän, joka on alku, kuolleista nousseitten esikoinen, että hän olisi kaikessa ensimmäinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Sillä Jumala näki hyväksi, että kaikki täyteys hänessä asuisi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'ja että hän, tehden rauhan hänen ristinsä veren kautta, hänen kauttaan sovittaisi itsensä kanssa kaikki, hänen kauttaan kaikki sekä maan päällä että taivaissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Teidätkin, jotka ennen olitte vieraantuneet ja mieleltänne hänen vihamiehiään pahoissa teoissanne, hän on nyt sovittanut');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'Poikansa lihan ruumiissa kuoleman kautta, asettaakseen teidät pyhinä, nuhteettomina ja moitteettomina eteensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'jos vain pysytte uskossa, siihen perustuneina ja siinä lujina horjahtamatta pois sen evankeliumin toivosta, jonka olette kuulleet, jota on julistettu kaikessa luomakunnassa taivaan alla ja jonka palvelijaksi minä, Paavali, olen tullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Nyt iloitsen kärsiessäni teidän tähtenne. Mitä vielä puuttuu Kristuksen ahdistuksista, sen puolestani täytän lihassani hänen ruumiinsa hyväksi, joka on seurakunta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'Sen palvelijaksi minä olen tullut Jumalan armotalouden mukaan, joka minulle on annettu teitä varten täydellisesti julistaakseni Jumalan sanan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'sen salaisuuden, joka on ollut kätkettynä ikuisista ajoista ja polvesta polveen. Mutta nyt se on ilmoitettu hänen pyhilleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'Heille Jumala tahtoi tehdä tiettäväksi, kuinka suuri pakanoiden keskuudessa on tämän salaisuuden kirkkaus: Kristus teissä, kirkkauden toivo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'Häntä me julistamme neuvoen jokaista ihmistä ja opettaen jokaista ihmistä kaikella viisaudella, asettaaksemme esiin jokaisen ihmisen täydellisenä Kristuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'Sitä varten näenkin vaivaa taistellen hänen vaikutuksensa mukaan, joka minussa voimallisesti vaikuttaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Sillä tahdon, että tiedätte, kuinka suuri kilvoittelu minulla on teidän ja laodikealaisten tähden sekä kaikkien tähden, jotka eivät ole nähneet ruumiillisia kasvojani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'jotta heidän sydämensä rakkauteen yhdistyneinä saisivat kehotusta täydellisen ymmärryksen kaikkeen rikkauteen tunteakseen Jumalan ja Isän ja Kristuksen salaisuuden,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'jossa kaikki viisauden ja tiedon aarteet ovat kätkettyinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Tämän sanon, ettei kukaan pettäisi teitä suostuttelevilla puheilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Sillä jos ruumiillisesti olenkin poissa, olen kuitenkin teidän kanssanne hengessä ja iloitsen nähdessäni järjestyksenne ja lujan uskonne Kristukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Niin kuin te siis olette omaksenne ottaneet Kristuksen Jeesuksen, Herran, vaeltakaa hänessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'juurtuneina häneen ja hänessä rakentuen ja uskossa vahvistuen, niin kuin teille on opetettu, ja olkoon teidän kiitoksenne siinä ylitsevuotava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Varokaa, ettei kukaan saa teitä saaliikseen filosofialla ja tyhjällä petoksella ihmisten perinnäissääntöjä ja maailman alkuvoimia seuraten eikä Kristusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Sillä hänessä asuu jumaluuden koko täyteys ruumiillisesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'ja olette täytetyt hänessä, joka on kaiken hallituksen ja vallan pää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'ja hänessä myös olette ympärileikatut, ette käsintehdyllä ympärileikkauksella, vaan syntisen ruumiin poisriisumisella lihassa, Kristuksen ympärileikkauksella:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'ollen haudattuina hänen kanssaan kasteessa, jossa myös olette hänen kanssaan herätetyt uskon kautta, jonka vaikuttaa Jumala, joka herätti hänet kuolleista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Ja teidät, jotka olitte kuolleet rikoksiinne ja lihanne ympärileikkaamattomuuteen, hän teki eläviksi yhdessä hänen kanssaan antaen teille anteeksi kaikki rikokset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'ja pyyhki pois sen kirjoituksen säädöksineen, joka oli meidän vastustajamme. Sen hän otti pois tieltämme ja naulitsi ristiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'Hän riisui aseet hallituksilta ja valloilta ja asetti heidät julkisen häpeän alaisiksi, hän sai heistä hänen kauttaan riemuvoiton.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Älköön siis kukaan teitä tuomitko syömisestä tai juomisesta, älköön myös minkään juhlan tai uudenkuun tai sapatin johdosta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'jotka vain ovat tulevien varjo, mutta ruumis on Kristuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Älköön teiltä riistäkö voittopalkintoanne kukaan, joka tahtoo [viedä] teidät nöyryyteen ja enkelien palveluun ja tunkeutua asioihin, joita ei ole nähnyt, ja on lihallisen mielensä turhaan paisuttama');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'eikä pitäydy häneen, joka on pää ja josta koko ruumis nivelten ja jänteiden avulla koossa pysyen ja vahvistuen kasvaa Jumalan antamaa kasvua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Jos siis olette Kristuksen kanssa kuolleet pois maailman alkuvoimista, miksi te, ikään kuin eläisitte maailmassa, sallitte määrätä itsellenne säädöksiä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, '\"Älä tartu, älä maista, älä koske!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, '– sehän on kaikki tarkoitettu katoamaan kuluttamalla – ihmisten käskyjen ja oppien mukaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Tällä kaikella tosin on viisauden maine omatekoisen jumalanpalveluksen ja nöyryyden vuoksi ja sen tähden, ettei se ruumista säästä. Mutta se on ilman mitään arvoa ja tapahtuu lihan tyydyttämiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Jos siis olette herätetyt Kristuksen kanssa, niin etsikää sitä, mikä on ylhäällä, jossa Kristus on, istuen Jumalan oikealla puolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Olkoon mielenne siihen, mikä on ylhäällä, älköön siihen, mikä on maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Sillä olette kuolleet, ja teidän elämänne on kätkettynä Kristuksen kanssa Jumalassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Kun Kristus, meidän elämämme, ilmestyy, silloin tekin ilmestytte hänen kanssaan kirkkaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Kuolettakaa siis maanpäälliset jäsenenne: haureus, saastaisuus, kiihko, paha himo ja ahneus, joka on epäjumalanpalvelusta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'sillä niiden tähden tulee Jumalan viha tottelemattomuuden lapsille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'ja niissä tekin ennen vaelsitte, kun niissä elitte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Mutta nyt pankaa tekin pois ne kaikki: viha, kiivastus, pahuus, herjaus ja häpeällinen puhe suustanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Älkää valehdelko toisillenne, te, jotka olette riisuneet pois vanhan ihmisen tekoineen');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'ja pukeutuneet uuteen, joka uudistuu tietoon, Luojansa kuvan mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Tässä ei ole kreikkalaista eikä juutalaista, ei ympärileikkausta eikä ympärileikkaamattomuutta, ei barbaaria, ei skyyttalaista, ei orjaa, ei vapaata, vaan kaikki ja kaikissa on Kristus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Pukeutukaa siis te, jotka olette Jumalan valittuja, pyhiä ja rakkaita, sydämelliseen armahtavaisuuteen, ystävällisyyteen, nöyryyteen, sävyisyyteen, pitkämielisyyteen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'sietäkää toinen toistanne ja antakaa toisillenne anteeksi, jos kenellä on moitetta toista vastaan. Niin kuin Herrakin on teille antanut anteeksi, niin tekin antakaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Mutta kaiken tämän lisäksi pukeutukaa rakkauteen, mikä on täydellisyyden side.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Ja hallitkoon sydämissänne Jumalan rauha, johon olette kutsututkin yhdessä ruumiissa, ja olkaa kiitollisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Runsaasti asukoon teidän luonanne Kristuksen sana kaikessa viisaudessa: Opettakaa ja neuvokaa toinen toistanne psalmeilla, kiitosvirsillä ja hengellisillä lauluilla veisaten kiitollisesti sydämissänne Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Ja kaikki, minkä teette sanalla tai työllä, kaikki tehkää Herran Jeesuksen nimessä, kiittäen Jumalaa ja Isää hänen kauttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Vaimot, olkaa miehillenne alamaisia, niin kuin sopii Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Miehet, rakastakaa kukin vaimoanne, älkääkä olko heitä kohtaan katkeria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Lapset, olkaa vanhemmillenne kuuliaisia kaikessa, sillä se on otollista Herralle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Isät, älkää kiihottako lapsianne, etteivät he kävisi aroiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Palvelijat, olkaa maallisille isännillenne kaikessa kuuliaisia, ei silmänpalvojina, ihmisille mieliksi, vaan sydämen yksinkertaisuudessa peläten Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Kaikki, mitä teettekin, tehkää sydämestänne, kuin Herralle eikä ihmisille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'tietäen, että te saatte Herralta palkaksi perinnön, palvelette Herraa Kristusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Sillä se, joka tekee väärin, saa takaisin väärintekonsa mukaan, eikä henkilöön katsota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Isännät, tehkää palvelijoillenne, mitä oikeus ja kohtuus vaatii, sillä tiedätte, että teilläkin on Herra taivaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Olkaa kestävät rukouksessa ja siinä kiittäen valvokaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'rukoillen samalla meidänkin edestämme, että Jumala avaisi meille sanan oven puhuaksemme Kristuksen salaisuutta, jonka tähden olen myös sidottuna,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'jotta sen ilmoittaisin, niin kuin minun tulee puhua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Vaelluksessanne olkaa viisaita ulkopuolella olevia kohtaan, ja ottakaa vaari oikeasta hetkestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Olkoon puheenne aina suloista, suolalla höystettyä, ja tietäkää, kuinka teidän tulee itse kullekin vastata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Kaikista oloistani antaa teille tiedon Tykikus, rakas veli ja uskollinen palvelija, kanssapalvelijani Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Lähetän hänet luoksenne juuri sitä varten, että saisitte tietää tilamme ja että hän lohduttaisi sydämiänne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Onesimoksen, uskollisen ja rakkaan veljen kanssa, joka on teikäläisiä. He ilmoittavat teille, kuinka kaikki täällä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Teille lähettää terveisiä Aristarkus, minun vankitoverini, ja Markus, Barnabaan serkku, josta olette saaneet ohjeita – jos hän tulee luoksenne, ottakaa hänet vastaan –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'ja Jeesus, jota sanotaan Justukseksi. Nämä ovat ympärileikatuista ainoat, jotka ovat olleet työtovereitani Jumalan valtakunnan hyväksi, ja he ovat olleet minulle lohdutukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Terveisiä lähettää teille teikäläinen Epafras, Kristuksen Jeesuksen palvelija, joka aina taistelee rukouksissaan teidän puolestanne, että pysyisitte täydellisinä ja täysin vahvoina kaikessa, mikä on Jumalan tahto.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Sillä annan hänestä sen todistuksen, että hänellä on paljon intoa teidän hyväksenne ja niiden hyväksi, jotka ovat Laodikeassa, sekä niiden, jotka ovat Hierapolissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Luukas, rakas lääkäri, lähettää teille terveisiä, niin myös Deemas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Terveisiä Laodikeassa oleville veljille ja Nymfalle sekä hänen kodissaan kokoontuvalle seurakunnalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Ja kun tämä kirje on luettu teille, niin toimittakaa, että se luetaan Laodikeankin seurakunnassa ja että tekin luette Laodikeasta tulevan kirjeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'Ja sanokaa Arkippukselle: \"Ota vaari virasta, jonka olet saanut Herrassa, että sen täysin toimitat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Omakätiset terveiset minulta, Paavalilta. Muistakaa kahleitani. Armo olkoon teidän kanssanne. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paavali, Silas ja Timoteus tessalonikalaisten seurakunnalle Isässä Jumalassa ja Herrassa Jeesuksessa Kristuksessa. Armo teille ja rauha!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Kiitämme Jumalaa aina kaikkien teidän tähtenne mainiten teitä rukouksissamme lakkaamatta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'ja muistaen työtänne uskossa ja vaivannäköänne rakkaudessa ja kärsivällisyyttänne toivossa Herraamme Jeesukseen Kristukseen Jumalamme ja Isämme edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Tiedämme, Jumalan rakastamat veljet, teidän valitsemisenne:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'että evankeliumimme tuli luoksenne, ei ainoastaan sanana, vaan myös voimana ja Pyhässä Hengessä ja suurella varmuudella – niin kuin tiedätte, millaisia olimme teidän keskuudessanne, teidän tähtenne –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'ja teistä tuli meidän seuraajiamme ja Herran, kun suuressa ahdingossa otitte sanan vastaan Pyhän Hengen vaikuttamalla ilolla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'niin että teistä on tullut esikuvia kaikille uskoville Makedoniassa ja Akaiassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Sillä teidän toimestanne Herran sana on kaikunut, ei ainoastaan Makedoniaan ja Akaiaan, vaan kaikkialle uskonne Jumalaan on levinnyt, niin ettei meidän tarvitse puhua siitä mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Sillä itse he kertovat meistä, millainen tulomme oli luoksenne ja kuinka te epäjumalista käännyitte Jumalan luo palvelemaan elävää ja oikeaa Jumalaa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'ja odottamaan taivaista hänen Poikaansa, jonka hän herätti kuolleista, Jeesusta, joka pelastaa meidät tulevasta vihasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Tiedättehän itsekin, veljet, ettei tulomme teidän luoksenne ollut turha,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'vaan, vaikka olimme ennen kärsineet, kuten tiedätte, Filipissä ja meitä oli siellä pidelty pahoin, meillä oli kuitenkin Jumalassamme rohkeutta puhua teille Jumalan evankeliumia suuressa kilvoituksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Sillä meidän kehotuspuheemme ei lähde eksytyksestä eikä epäpuhtaasta mielestä eikä ole kavaluudessa puhuttua,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'vaan niin kuin Jumala on katsonut meidät kelvollisiksi siihen, että meille uskottiin evankeliumi, puhumme, emme ollaksemme ihmisille mieliksi, vaan Jumalalle, joka koettelee sydämemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Sillä emme esiintyneet koskaan mielistelevin puhein, kuten tiedätte, emmekä tekosyillä ahnehtineet. Jumala on todistajamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Emme ole etsineet kunniaa ihmisiltä, emme teiltä emmekä muilta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'vaikka Kristuksen apostoleina olisimme voineet saada teiltä arvonantoa. Olimme sen sijaan keskuudessanne lempeitä kuin imettävä äiti, joka vaalii lapsiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Niin mekin teitä hellien halusimme antaa teille, emme ainoastaan Jumalan evankeliumia, vaan oman henkemmekin, sillä olitte meille rakkaita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Muistattehan, veljet, meidän työmme ja rasituksemme: yötä päivää työtä tehden saarnasimme teille Jumalan evankeliumia, niin ettemme ketään teistä rasittaisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Te olette todistajamme, ja Jumala, kuinka pyhät, vanhurskaat ja nuhteettomat olimme teitä kohtaan, jotka uskotte,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'samoin kuin tiedätte, kuinka me, niin kuin isä lapsiaan, kehotimme itse kutakin teistä ja rohkaisimme teitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'ja todistimme teille, että teidän tulee vaeltaa arvollisesti Jumalan edessä, hänen, joka kutsuu teitä valtakuntaansa ja kirkkauteensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Sen tähden me myös kiitämme lakkaamatta Jumalaa siitä, että saatuanne saarnaamamme Jumalan sanan otitte sen vastaan, ette ihmisten sanana, vaan, niin kuin se totisesti on, Jumalan sanana, joka myös vaikuttaa teissä, jotka uskotte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Sillä teistä, veljet, on tullut niiden Kristuksessa Jeesuksessa olevien Jumalan seurakuntien seuraajia, jotka ovat Juudeassa, sillä tekin olette kärsineet omilta heimolaisiltanne samaa kuin he juutalaisilta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'jotka tappoivat Herrankin, Jeesuksen, ja omia profeettojaan ja ovat vainonneet meitä, eivätkä ole Jumalalle otollisia, vaan ovat kaikkien ihmisten vihollisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'kun estävät meitä puhumasta pakanoille heidän pelastumisekseen täyttääkseen kaiken aikaa syntiensä mittaa. Viha onkin jo saavuttanut heidät viimeiseen määräänsä asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Mutta kun meidät nyt, veljet, on hetkeksi aikaa erotettu teistä, kasvoilta, ei sydämeltä, on meille tullut yhä suurempi halu nähdä pian kasvonne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Sen tähden olemme tahtoneet tulla luoksenne, minä, Paavali puolestani kerran ja kahdestikin, mutta saatana on estänyt meitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Sillä kuka on toivomme, ilomme tai kerskauksemme kruunu? Ettekö tekin, Herramme Jeesuksen edessä hänen tulemuksessaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Sillä te olette kunniamme ja ilomme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Sen tähden, kun emme enää kestäneet, katsoimme parhaaksi jäädä yksin Ateenaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'ja lähetimme Timoteuksen, veljemme ja Jumalan palvelijan Kristuksen evankeliumissa, vahvistamaan ja rohkaisemaan teitä uskossanne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'ettei kukaan horjuisi näissä ahdingoissa. Sillä itse tiedätte, että meidät on sellaisiin pantu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Kun olimme luonanne, sanoimme teille jo edeltäpäin, että joudumme ahdistuksiin, kuten myös tiedätte tapahtuneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Sen tähden minäkin, kun en enää kestänyt kauempaa, lähetin tiedustelemaan teidän uskoanne, olisiko ehkä kiusaaja vietellyt teidät ja olisiko vaivannäkömme mennyt hukkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Mutta nyt, kun Timoteus tuli luoksemme luotanne ja kertoi meille hyviä uutisia uskostanne ja rakkaudestanne ja siitä, että aina säilytätte meistä hyvän muiston ikävöiden nähdä meitä niin kuin mekin teitä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'sen tähden olemme saaneet lohdutusta teistä, veljet, kaikkeen ahdistukseemme ja ahdinkoomme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Nyt näet elämme, jos te seisotte lujina Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Sillä miten voimme kylliksi osoittaa kiitollisuutta Jumalaa kohtaan teidän tähtenne kaikesta siitä ilosta, mikä meillä on teistä Jumalamme edessä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Yötä päivää rukoilemme erittäin paljon saadaksemme nähdä kasvonne ja täyttää sen, mitä uskostanne puuttuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Mutta hän itse, Jumalamme ja Isämme, ja Herramme Jeesus ohjatkoon tiemme luoksenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Herra antakoon teille yhä enemmän ja runsaammin rakkautta toisianne kohtaan ja kaikkia kohtaan, niin kuin meilläkin on teitä kohtaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'vahvistaakseen sydämenne nuhteettomiksi pyhyydessä Jumalamme ja Isämme edessä, Herramme Jeesuksen tullessa kaikkien pyhiensä kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Sitten vielä, veljet, pyydämme ja kehotamme teitä Herrassa Jeesuksessa, että kuten olette meiltä oppineet, miten teidän tulee vaeltaa ja olla Jumalalle otollisia, niin kuin vaellattekin, kasvaisitte siinä yhä enemmän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Tiedättehän, mitkä käskyt olemme Herran Jeesuksen kautta teille antaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Sillä tämä on Jumalan tahto, teidän pyhityksenne, että pysytte erossa haureudesta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'että kukin teistä tietää ottaa itselleen vaimon pyhyydessä ja kunniassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'ei himon kiihkossa kuin pakanat, jotka eivät Jumalaa tunne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'ettei kukaan sorra veljeään eikä tuota hänelle vahinkoa missään asiassa. Herra on näet kaiken tämän kostaja, niin kuin myös ennen olemme teille sanoneet ja todistaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Sillä Jumala ei ole kutsunut meitä saastaisuuteen, vaan pyhitykseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Sen tähden, joka nämä hylkää, ei hylkää ihmistä, vaan Jumalan, joka myös antaa Pyhän Henkensä teihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Veljesrakkaudesta teille ei tarvitse kirjoittaa, sillä Jumala on itse opettanut teidät rakastamaan toisianne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'Sillä niin teettekin kaikkia veljiä kohtaan koko Makedoniassa. Mutta kehotamme teitä, veljet, kasvamaan siinä yhä enemmän');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'ja katsomaan kunniaksenne, että elätte hiljaisuudessa ja toimitatte omia tehtäviänne ja teette työtä käsillänne, niin kuin olemme teitä käskeneet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'että vaelluksessanne olisitte säädyllisiä ulkopuolella olevia kohtaan ettekä olisi kenenkään avun tarpeessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Mutta en tahdo pitää teitä, veljet, tietämättöminä siitä, kuinka poisnukkuneiden on, ettette murehtisi niin kuin muut, joilla ei ole toivoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Sillä jos uskomme, että Jeesus on kuollut ja noussut ylös, niin samoin on Jumalakin Jeesuksen kautta tuova poisnukkuneet esiin yhdessä hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Sillä sen sanomme teille Herran sanana, että me, jotka olemme elossa, jotka jäämme tänne Herran tulemukseen, emme suinkaan ehdi ennen niitä, jotka ovat nukkuneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Sillä itse Herra on tuleva alas taivaasta käskyhuudon, ylienkelin äänen ja Jumalan torven kuuluessa. Kristuksessa kuolleet nousevat ylös ensin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'sitten meidät, jotka olemme elossa, jotka olemme jääneet tänne, temmataan yhdessä heidän kanssaan pilvissä Herraa vastaan ilmaan, ja niin saamme aina olla Herran kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Näin lohduttakaa toisianne näillä sanoilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Mutta aikakausista ja määrähetkistä ei ole tarpeen kirjoittaa teille, veljet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'sillä hyvin tiedätte, että Herran päivä tulee kuin varas yöllä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Kun he sanovat: \"Nyt on rauha ja turvallista\", silloin heille tulee yhtäkkiä turmio kuin poltot raskaana olevalle vaimolle, eivätkä he pääse pakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Mutta te, veljet, ette ole pimeydessä, niin että se päivä veisi teidät kuin varas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Te kaikki olette nimittäin valkeuden lapsia ja päivän lapsia. Emme ole yön emmekä pimeyden lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Älkäämme siis nukkuko kuten muut, vaan valvokaamme ja olkaamme raittiit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Sillä ne, jotka nukkuvat, yöllä nukkuvat, ja jotka juopuvat, ovat yöllä juovuksissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Mutta me, jotka olemme päivän lapsia, olkaamme raittiita, ja olkoon pukunamme uskon ja rakkauden haarniska ja kypäränämme pelastuksen toivo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Sillä Jumala ei ole määrännyt meitä vihaan, vaan saamaan omaksemme pelastuksen Herramme Jeesuksen Kristuksen kautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'joka on kuollut meidän edestämme, että olimmepa hereillä tai nukuimme, eläisimme yhdessä hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Sen tähden kehottakaa toisianne ja rakentakaa toinen toistanne, kuten teettekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Mutta pyydämme teitä, veljet, antamaan tunnustusta niille, jotka tekevät työtä teidän keskuudessanne ja ovat johtajianne Herrassa ja neuvovat teitä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'sekä pitämään heitä erityisen rakkaina heidän työnsä tähden. Eläkää rauhassa heidän kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Kehotamme teitä, veljet: nuhdelkaa kurittomia, rohkaiskaa alakuloisia, holhotkaa heikkoja, olkaa pitkämielisiä kaikkia kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Katsokaa, ettei kukaan kosta kenellekään pahaa pahalla, vaan pyrkikää aina tekemään hyvää toinen toisellenne ja kaikille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Olkaa aina iloiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Rukoilkaa lakkaamatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Kiittäkää joka tilassa. Sillä se on Jumalan tahto teihin nähden Kristuksessa Jeesuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Henkeä älkää sammuttako,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'profetoimista älkää halveksiko,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'mutta koetelkaa kaikki, pitäkää hyvä ja');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'karttakaa kaikkea pahalta näyttävää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Mutta itse rauhan Jumala pyhittäköön teidät kokonaan, ja säilyköön koko teidän henkenne, sielunne ja ruumiinne nuhteettomana meidän Herramme Jeesuksen Kristuksen tuloon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Hän, joka teitä kutsuu, on uskollinen, ja hän on myös sen tekevä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Veljet, rukoilkaa edestämme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Tervehtikää kaikkia veljiä pyhällä suudelmalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Minä vannotan teitä Herran kautta, että luetatte tämän kirjeen kaikille veljille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Herramme Jeesuksen Kristuksen armo olkoon teidän kanssanne. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paavali, Silas ja Timoteus tessalonikalaisten seurakunnalle Jumalassa, meidän Isässämme, ja Herrassa Jeesuksessa Kristuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Olemme aina velvollisia kiittämään Jumalaa teidän tähtenne, veljet, kuten oikein onkin, koska teidän uskonne kasvaa runsaasti ja keskinäinen rakkautenne lisääntyy itse kussakin, kaikissa teissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'niin että me itsekin Jumalan seurakunnissa kerskaamme teistä, teidän kärsivällisyydestänne ja uskostanne kaikissa vainoissanne ja ahdistuksissa, joita teillä on kestettävänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'Ne ovat osoituksena Jumalan vanhurskaasta tuomiosta, että teidät on katsottu arvollisiksi Jumalan valtakuntaan, jonka tähden kärsittekin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'koska Jumalan edessä on oikein kostaa ahdistuksella niille, jotka teitä ahdistavat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'ja antaa teille, joita ahdistetaan, lepo yhdessä meidän kanssamme, kun Herra Jeesus ilmestyy taivaasta voimansa enkelien kanssa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'liekehtivässä tulessa ja kostaa niille, jotka eivät tunne Jumalaa eivätkä ole kuuliaisia Herramme Jeesuksen Kristuksen evankeliumille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Heitä kohtaa rangaistukseksi iankaikkinen kadotus Herran kasvoista ja hänen voimansa kirkkaudesta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'kun hän sinä päivänä tulee, että hänet kirkastettaisiin pyhissään ja hän olisi ihmeteltävä kaikissa uskovissa sinä päivänä, sillä te olette uskoneet meidän todistuksemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Sitä varten aina rukoilemmekin teidän puolestanne, että meidän Jumalamme katsoisi teidät kutsumisensa arvoisiksi ja tekisi täydelliseksi kaiken halunne hyvään ja uskonne teot voimassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'jotta meidän Herramme Jeesuksen Kristuksen nimi kirkastuisi teissä ja te hänessä, meidän Jumalamme ja Herran Jeesuksen Kristuksen armon mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Mutta pyydämme teitä, veljet, mitä tulee Herramme Jeesuksen Kristuksen tulemiseen ja meidän kokoontumiseemme hänen luokseen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'ettette aivan heti anna minkään hengen ettekä sanan ettekä minkään muka meidän lähettämämme kirjeen järkyttää itseänne ja saattaa pois tolaltanne ja pelästyttää itseänne, ikään kuin Herran päivä olisi jo käsillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Älkää antako kenenkään vietellä itseänne millään tavalla. Sillä hän ei tule, ellei luopumus ensin tapahdu ja ilmesty laittomuuden ihminen, kadotuksen lapsi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'tuo vastustaja, joka korottaa itsensä yli kaiken, mitä jumalaksi tai jumaloitavaksi sanotaan, niin että hän istuu Jumalan temppeliin, kuin olisi Jumala, ja esiintyy Jumalana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Ettekö muista, että sanoin tämän teille, kun vielä olin luonanne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Ja nyt tiedätte, mikä pidättää, niin että hän vasta ajallaan ilmaantuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Sillä laittomuuden salaisuus on jo vaikuttamassa, kunhan vain tulee tieltä poistetuksi se, joka nyt vielä pidättää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'niin silloin ilmestyy tuo laiton, jonka Herra Jeesus on hävittävä suunsa henkäyksellä ja tuhoava tulonsa ilmestymisellä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'tuo, jonka tulo tapahtuu saatanan vaikutuksesta valheen kaikella voimalla, tunnusteoilla ja ihmeillä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'ja kaikilla vääryyden viettelyksillä niille, jotka joutuvat kadotukseen, sen tähden etteivät ottaneet vastaan rakkautta totuuteen, voidakseen pelastua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Sen tähden Jumala lähettää heille voimakkaan eksytyksen, niin että he uskovat valheen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'että kaikki ne tuomittaisiin, jotka eivät ole uskoneet totuutta, vaan ovat mieltyneet vääryyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Mutta me olemme velvollisia aina kiittämään Jumalaa teidän tähtenne, veljet, te Herran rakastetut, sen tähden että Jumala alusta alkaen valitsi teidät pelastukseen Hengen pyhityksessä ja uskossa totuuteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'Siihen hän on myös kutsunut teidät evankeliumillamme omistamaan Herramme Jeesuksen Kristuksen kirkkauden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Niin seisokaa siis, veljet, lujina ja pitäkää kiinni niistä opetuksista, joita olette oppineet joko puheestamme tai kirjeestämme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Itse Herramme Jeesus Kristus ja Jumala, meidän Isämme, joka on rakastanut meitä ja antanut meille armossa iankaikkisen lohdutuksen ja hyvän toivon,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'lohduttakoon sydämiänne ja vahvistakoon teitä kaikessa puheessa ja hyvässä työssä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Sitten vielä, veljet, rukoilkaa meidän edestämme, että Herran sana leviäisi nopeasti ja tulisi kirkastetuksi kuten teidänkin keskuudessanne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'ja jotta pelastuisimme nurjista ja pahoista ihmisistä, sillä usko ei ole kaikkien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Mutta Herra on uskollinen, ja hän vahvistaa teitä ja varjelee teidät pahasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Luotamme teihin Herrassa, että te sekä nyt että vasta teette, mitä käskemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Herra ohjatkoon sydämenne Jumalan rakkauteen ja Kristuksen kärsivällisyyteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Mutta Herran Jeesuksen Kristuksen nimessä käskemme teitä, veljet, vetäytymään pois jokaisesta veljestä, joka vaeltaa kurittomasti eikä sen opetuksen mukaan, jonka olette meiltä saaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Tiedättehän itse, kuinka tulee seurata meitä, sillä emme ole olleet kurittomia keskuudessanne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'emmekä ilmaiseksi syöneet kenenkään leipää, vaan ahkeroimme työtä tehden ja vaivaa nähden yötä päivää, ettemme olisi rasitukseksi kenellekään teistä, –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'ei niin, ettei meillä olisi siihen valtaa, vaan tahdoimme antaa teille esikuvan seuraamiseemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Sillä jo silloin, kun olimme luonanne, säädimme teille, että sen, joka ei tahdo tehdä työtä, ei pidä syödäkään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Sillä olemme kuulleet, että muutamat keskuudessanne vaeltavat kurittomasti, eivät tee työtä, vaan puuhailevat heille kuulumattomissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Sellaisia käskemme ja kehotamme Herrassa Jeesuksessa Kristuksessa tekemään työtä hiljaisuudessa ja syömään omaa leipäänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Mutta te, veljet, älkää väsykö tekemään hyvää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Mutta jos kuka tahansa ei tottele sitä, mitä tässä kirjeessä olemme sanoneet, merkitkää hänet älkääkä seurustelko hänen kanssaan, että hän häpeäisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Älkää kuitenkaan pitäkö häntä vihollisena, vaan ojentakaa kuin veljeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Mutta itse rauhan Herra antakoon teille rauhan, aina ja kaikella tavalla. Herra olkoon teidän kaikkien kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Tervehdys minulta, Paavalilta, omakätisesti. Se on merkkinä jokaisessa kirjeessäni. Näin kirjoitan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Meidän Herramme Jeesuksen Kristuksen armo olkoon teidän kaikkien kanssa. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paavali, Kristuksen Jeesuksen apostoli, Jumalan, meidän vapahtajamme, ja Kristuksen Jeesuksen, meidän toivomme, käskystä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Timoteukselle, oikealle pojalleen uskossa. Armo, laupeus ja rauha Jumalalta Isältämme ja Kristukselta Jeesukselta, Herraltamme!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Niin kuin Makedoniaan lähtiessäni kehotin sinua jäämään Efesoon käskeäksesi, etteivät opettaisi muita oppeja');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'eivätkä kiinnittäisi huomiota taruihin ja loputtomiin sukuluetteloihin, jotka saavat aikaan ennemmin riitoja kuin rakentavat Jumalan huonetta uskossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Mutta käskyn päämäärä on rakkaus, joka tulee puhtaasta sydämestä, hyvästä omastatunnosta ja teeskentelemättömästä uskosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Muutamat ovat hairahtuneet niistä pois ja kääntyneet puhumaan turhia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'tahtoen olla lainopettajia, vaikka eivät ymmärrä, mitä puhuvat ja minkä varmaksi väittävät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Mutta tiedämme, että laki on hyvä, kun sitä lain mukaisesti käytetään');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'ja tiedetään, että lakia ei ole pantu vanhurskaalle, vaan laittomille ja niskoitteleville, jumalattomille ja syntisille, epähurskaille ja epäpyhille, isänsä tappajille ja äitinsä tappajille, murhaajille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'haureellisille, miesten kanssa makaaville miehille, ihmiskauppiaille, valehtelijoille, valansa rikkojille ja kaikelle muulle, mikä on tervettä oppia vastaan –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'autuaan Jumalan kirkkauden evankeliumin mukaisesti, joka on minulle uskottu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Minä kiitän häntä, joka on minulle voimaa antanut, Kristusta Jeesusta, meidän Herraamme, siitä, että hän katsoi minut uskolliseksi ja asetti palvelusvirkaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'minut, entisen pilkkaajan, vainoojan ja väkivallantekijän. Mutta sain laupeuden, koska olin tehnyt sitä tietämättömänä, epäuskossa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'ja meidän Herramme armo oli ylitsepursuava uskon ja rakkauden kanssa, joka on Kristuksessa Jeesuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Varma on se sana ja kaikin puolin vastaanottamisen arvoinen, että Kristus Jeesus on tullut maailmaan pelastamaan syntisiä, joista minä olen ensimmäinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Mutta sen tähden sain laupeuden, jotta Jeesus Kristus minussa ennen muita osoittaisi kaiken pitkämielisyytensä esikuvaksi niille, jotka tulevat uskomaan häneen itselleen iankaikkiseksi elämäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Mutta iankaikkiselle kuninkaalle, katoamattomalle, näkymättömälle, Jumalalle, ainoalle viisaalle, kunnia ja kirkkaus iäisyyksien iäisyyksiin! Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Tämän käskyn annan sinulle, poikani Timoteus, aikaisempien, sinulle lausuttujen profetioiden mukaisesti, että niiden mukaisesti taistelisit hyvän taistelun,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'säilyttäen uskon ja hyvän omantunnon, jonka eräät ovat hylänneet ja uskossaan haaksirikkoutuneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Niitä ovat Hymeneus ja Aleksander, jotka olen antanut saatanan kuritettaviksi, etteivät enää pilkkaisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Kehotan siis ennen kaikkea anomaan, rukoilemaan, pitämään esirukouksia ja kiittämään kaikkien ihmisten puolesta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'kuningasten ja kaiken esivallan puolesta, että saisimme viettää rauhallista ja hiljaista elämää kaikessa jumalanpelossa ja kunniallisuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Sillä se on hyvää ja otollista Jumalalle, vapahtajallemme,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'joka tahtoo, että kaikki ihmiset pelastuisivat ja tulisivat tuntemaan totuuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Sillä yksi on Jumala, yksi myös välimies Jumalan ja ihmisten välillä, ihminen Kristus Jeesus,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'joka antoi itsensä lunnaiksi kaikkien edestä ja josta todistus oli annettava ajallaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'ja sitä varten minut on saarnaajaksi ja apostoliksi asetettu – puhun totta, en valehtele – pakanain opettajaksi uskossa ja totuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Tahdon siis, että miehet rukoilevat, joka paikassa kohottaen pyhät kädet ilman vihaa ja epäilystä;.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'samoin, että naiset ovat säädyllisessä puvussa, kaunistavat itseään kainosti ja kohtuullisesti, ei palmikoiduilla hiuksilla, kullalla, helmillä eikä kallisarvoisilla vaatteilla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'vaan hyvillä teoilla, kuten on soveliasta naisille, jotka tunnustautuvat jumalaapelkääviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Oppikoon nainen hiljaisuudessa, kaikin puolin alistuvana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Mutta en salli, että nainen opettaa, enkä että hän vallitsee miestä, vaan olkoon hiljaisuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Sillä Aadam luotiin ensin, sitten Eeva,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'eikä Aadamia petetty, vaan nainen petettiin ja rikkoi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Mutta hän on pelastuva lastensynnyttämisen kautta, jos hän pysyy uskossa, rakkaudessa ja pyhityksessä noudattaen itsehillintää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Varma on tämä sana: jos joku pyrkii kaitsijan virkaan, hän haluaa jaloon toimeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Kaitsijan tulee siis olla nuhteeton, yhden vaimon mies, raitis, hurskas, kunniallinen, vieraanvarainen, kykenevä opettamaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'ei juomari, ei tappelija, ei häpeällistä voittoa tavoitteleva, vaan lempeä, ei riitaisa, ei rahanahne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'vaan oman kotinsa hyvin hallitseva ja kaikella kunniallisuudella lapsensa kuuliaisina pitävä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'Sillä jos joku ei osaa hallita omaa kotiaan, kuinka hän huolehtii Jumalan seurakunnasta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Älköön hän olko äsken kääntynyt, ettei paisuisi ja joutuisi perkeleen tuomion alaiseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Hänellä tulee myös olla hyvä todistus ulkopuolella olevilta, ettei hän joutuisi perkeleen häväistäväksi ja hänen paulaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Samoin diakonien tulee olla arvokkaita, ei kahdella tavalla puhuvia, ei paljon viinin nauttijoita, ei häpeällisen voiton pyytäjiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'sellaisia, jotka pitävät uskon salaisuuden puhtaassa omassatunnossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Mutta heitäkin koeteltakoon ensin, sitten palvelkoot, jos ovat nuhteettomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Samoin tulee naistenkin olla arvokkaita, ei panettelijoita, vaan raittiita, uskollisia kaikessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Diakonit olkoot yhden vaimon miehiä, lapsensa ja oman kotinsa hyvin hallitsevia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Sillä ne, jotka ovat hyvin palvelleet, saavuttavat itselleen kunnioitettavan aseman ja suuren rohkeuden uskossa Kristukseen Jeesukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Kirjoitan tämän sinulle – vaikka toivonkin pian pääseväni luoksesi –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'että, jos viivyn, tietäisit, miten tulee olla Jumalan huoneessa, joka on elävän Jumalan seurakunta, totuuden pylväs ja perustus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Tunnustetusti suuri on jumalanpelon salaisuus: Jumala on ilmestynyt lihassa, vanhurskaaksi julistettu Hengessä, näyttäytynyt enkeleille, saarnattu pakanoiden keskuudessa, uskottu maailmassa, otettu ylös kirkkauteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Mutta Henki sanoo selvästi, että tulevina aikoina monet luopuvat uskosta ja noudattavat villitseviä henkiä ja riivaajien oppeja');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'valheenpuhujien ulkokultaisuuden vaikutuksesta, joiden omatunto on poltinraudalla merkitty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'He kieltävät menemästä naimisiin ja nauttimasta ruokia, jotka Jumala on luonut niiden nautittavaksi kiitoksella, jotka uskovat ja ovat tulleet totuuden tuntemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Sillä kaikki, minkä Jumala on luonut, on hyvää, eikä mikään ole hylättävää, kun se kiitoksella vastaanotetaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'sillä se pyhitetään Jumalan sanalla ja rukouksella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Kun tätä veljille opetat, olet hyvä Kristuksen Jeesuksen palvelija, joka ravitset itseäsi uskon ja sen hyvän opin sanoilla, jota olet noudattanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Mutta epäpyhiä akkojen taruja karta ja harjoita itseäsi jumalanpelkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Sillä ruumiillisesta harjoituksesta on hyötyä vain vähään, mutta jumalanpelosta on hyötyä kaikkeen, koska sillä on elämän lupaus, sekä nykyisen että tulevan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Varma on se sana ja kaikin puolin vastaanottamisen arvoinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Sillä siksi näemme vaivaa ja kilvoittelemme, että olemme panneet toivomme elävään Jumalaan, joka on kaikkien ihmisten vapahtaja, varsinkin uskovien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Tätä käske ja opeta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Älköön kukaan halveksiko nuoruuttasi, vaan ole sinä uskovien esikuva puheessa, vaelluksessa, rakkaudessa, hengessä, uskossa, puhtaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Lue, kehota ja opeta ahkerasti, kunnes tulen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Älä lyö laimin armolahjaa, joka sinussa on ja joka sinulle annettiin profetian kautta vanhinten pannessa kätensä päällesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Harrasta näitä, elä näissä, jotta edistymisesi olisi kaikkien nähtävissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Valvo itseäsi ja opetustasi, ole siinä kestävä. Sillä jos sen teet, olet pelastava sekä itsesi että ne, jotka sinua kuulevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Älä nuhtele kovasti vanhaa miestä, vaan kehota häntä kuin isää, nuorempia kuin veljiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'vanhoja naisia kuin äitejä, nuorempia kuin sisaria, kaikessa puhtaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Kunnioita leskiä, jotka ovat oikeita leskiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Mutta jos jollakulla leskellä on lapsia tai lapsenlapsia, oppikoot nämä ensin jumalisesti hoitamaan omaa perhekuntaansa ja maksamaan velkansa vanhemmilleen, sillä se on oikein ja otollista Jumalan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Oikea leski ja yksinäiseksi jäänyt panee toivonsa Jumalaan, anoo ja rukoilee alinomaa, yötä päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Mutta se, joka haluaa viettää ylellistä elämää, on jo eläessään kuollut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Käske tätäkin, että olisivat nuhteettomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Mutta jos joku ei pidä huolta omaisistaan ja varsinkaan perhekuntalaisistaan, hän on kieltänyt uskon ja on epäuskoista pahempi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Luetteloon otettakoon ainoastaan sellainen leski, joka ei ole kuuttakymmentä vuotta nuorempi ja joka on ollut yhden miehen vaimo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'josta on todistettu, että hän on tehnyt hyviä töitä, on kasvattanut lapsia, holhonnut vieraita, pessyt pyhien jalkoja, auttanut ahdistettuja ja harrastanut kaiken hyvän tekemistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Mutta nuorehkot lesket hylkää, sillä kun he himokkaiksi käyden vieraantuvat Kristuksesta, he tahtovat mennä naimisiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'ja ovat tuomion alaisia, koska ovat hylänneet ensimmäisen uskonsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'He oppivat taloissa kierrellessään laiskoiksikin, eikä ainoastaan laiskoiksi, vaan myös juoruamaan, sekaantumaan toisten asioihin ja puhumaan sopimattomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Tahdon sen tähden nuorempien menevän naimisiin, synnyttävän lapsia, hoitavan kotiaan ja etteivät anna vastustajalle mitään aihetta solvaamiseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Sillä muutamat ovat jo kääntyneet pois seuraamaan saatanaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Jos jollakulla uskovalla naisella on leskiä, pitäköön heistä huolen, älköönkä seurakuntaa rasitettako, että se voisi pitää huolta oikeista leskistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Vanhimpia, jotka seurakuntaa hyvin hoitavat, pidettäköön kaksinkertaisen kunnian ansainneina, varsinkin niitä, jotka tekevät työtä sanassa ja opetuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Sillä Raamattu sanoo: \"Älä sido puivan härän suuta\", ja: \"Työmies on palkkansa ansainnut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Älä ota käsiteltäväksi syytöstä vanhinta vastaan, ellei ole kahta tai kolmea todistajaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Syntiä tekeviä nuhtele kaikkien edessä, että muutkin pelkäisivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Vannotan sinua Jumalan ja Herran Kristuksen Jeesuksen ja valittujen enkelien edessä, että noudatat tätä tekemättä etukäteen päätöstä ja ketään suosimatta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Älä ole liian hätäinen panemaan käsiäsi kenenkään päälle, äläkä osallistu muiden synteihin. Pidä itsesi puhtaana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Älä enää juo vain vettä, vaan käytä vähän viiniä vatsasi tähden ja usein uudistuvien vaivojesi vuoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Muutamien ihmisten synnit ovat ilmeiset ja joutuvat ennen tuomittaviksi, toisten taas seuraavat perästäpäin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Samoin myös hyvät teot ovat ilmeiset, eivätkä nekään, jotka eivät ole sellaisia, voi pysyä salassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Kaikki, jotka ovat orjina ikeen alla, pitäkööt isäntiään kaiken kunnioituksen arvoisina, jotta Jumalan nimeä ja oppia ei häväistäisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Mutta ne, joilla on uskovat isännät, älkööt pitäkö heitä vähemmässä arvossa sen tähden, että he ovat veljiä, vaan palvelkoot heitä sitä mieluummin, koska he ovat uskovia ja rakastettuja ja ottavat osaa hyvän tekemiseen. Tätä opeta ja kehota.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Jos joku opettaa muuta oppia eikä pitäydy Herramme Jeesuksen Kristuksen terveisiin sanoihin eikä siihen oppiin, joka on jumalanpelon mukainen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'hän on ylpistynyt eikä ymmärrä mitään, vaan on riitakysymysten ja sanakiistojen kipeä. Niistä syntyy kateutta, riitaa, herjauksia, pahoja epäluuloja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'alituisia kiistoja niiden ihmisten kesken, jotka ovat turmeltuneet mieleltään ja totuuden menettäneet ja jotka pitävät jumalanpelkoa keinona voiton saamiseen. Pysy erossa sellaisista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Mutta suuri voitto onkin jumalanpelko yhdessä tyytyväisyyden kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Sillä emme ole tuoneet mitään maailmaan. Selvää on, ettemme voi myöskään täältä mitään viedä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Mutta kun meillä on elatus ja vaatteet, tyytykäämme niihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Mutta ne, jotka rikastua tahtovat, lankeavat kiusaukseen ja ansaan sekä moniin mielettömiin ja vahingollisiin himoihin, jotka upottavat ihmiset turmioon ja kadotukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Sillä rahan himo on kaiken pahan juuri. Sitä haluten monet ovat eksyneet pois uskosta ja lävistäneet itsensä monella tuskalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Mutta sinä, Jumalan ihminen, pakene sellaista ja tavoittele vanhurskautta, jumalanpelkoa, uskoa, rakkautta, kärsivällisyyttä ja hiljaisuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Kilvoittele hyvä uskon kilvoitus, tartu kiinni iankaikkiseen elämään, johon olet kutsuttu ja johon olet hyvällä tunnustuksella tunnustautunut monen todistajan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Jumalan edessä, joka kaiken eläväksi tekee, ja Kristuksen Jeesuksen edessä, joka Pontius Pilatuksen edessä todisti, tunnustaen hyvän tunnustuksen, kehotan sinua,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'että pidät tahrattomasti ja moitteettomasti käskyn meidän Herramme Jeesuksen Kristuksen ilmestymiseen saakka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'Sen on aikanaan antava meidän nähdä autuas ja ainoa valtias, kuningasten Kuningas ja herrojen Herra,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'jolla ainoalla on kuolemattomuus; joka asuu valkeudessa, mitä kukaan ei voi lähestyä; jota yksikään ihminen ei ole nähnyt eikä voi nähdä – hänen olkoon kunnia ja iankaikkinen valta. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Kehota niitä, jotka nykyisessä maailmanajassa ovat rikkaita, etteivät ylpeilisi eivätkä panisi toivoaan epävarmaan rikkauteen, vaan elävään Jumalaan, joka antaa meille runsaasti kaikkea nautittavaksemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Kehota heitä, että tekevät hyvää, hyvissä töissä rikastuvat, ovat anteliaita ja jakavat omastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'kooten itselleen aarteen, hyvän perustuksen tulevaisuuden varalle, jotta tarttuisivat kiinni iankaikkiseen elämään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Timoteus, talleta se, mikä sinulle on uskottu, ja pysy erossa tiedon nimellä kulkevan valhetiedon epäpyhistä ja tyhjistä puheista ja vastaväitteistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'Siihen tunnustautuen muutamat ovat uskosta hairahtuneet. Armo kanssasi! Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paavali, Kristuksen Jeesuksen apostoli Jumalan tahdosta sen elämän lupauksen mukaan, joka on Kristuksessa Jeesuksessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Timoteukselle, rakkaalle pojalleni. Armo, laupeus ja rauha Jumalalta, Isältä, ja Kristukselta Jeesukselta, Herraltamme!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Kiitän Jumalaa, jota esivanhemmistani asti palvelen puhtaalla omallatunnolla – samalla kun lakkaamatta muistan sinua rukouksissani yötä päivää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'ja muistaessani kyyneleitäsi haluan nähdä sinut, jotta täyttyisin ilolla –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'kun mieleeni muistuu se vilpitön usko, joka sinulla on, joka oli ensin isoäidilläsi Looiksella ja äidilläsi Eunikella ja joka, siitä olen varma, on sinullakin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Siitä syystä muistutan sinua virittämään palavaksi Jumalan armolahjan, joka sinussa on suorittamani kättenpäällepanon kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Sillä Jumala ei ole antanut meille pelkuruuden henkeä, vaan voiman, rakkauden ja maltillisuuden hengen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Älä siis häpeä todistusta Herrastamme äläkä minua, hänen vankiaan, vaan kärsi yhdessä kanssani vaivaa evankeliumin hyväksi, sen mukaan kuin Jumala antaa voimaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Hän on pelastanut meidät ja kutsunut pyhällä kutsumuksella, ei tekojemme mukaan, vaan oman päätöksensä ja armonsa mukaan, joka on annettu meille Kristuksessa Jeesuksessa ennen ikuisia aikoja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'mutta nyt saatettu julki Vapahtajamme Kristuksen Jeesuksen ilmestymisen kautta, joka kukisti kuoleman ja toi valoon elämän ja katoamattomuuden evankeliumin kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'Minut on asetettu julistajaksi, apostoliksi ja opettajaksi pakanoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Siitä syystä myös kärsin näitä enkä sitä häpeä. Tunnen näet hänet, johon uskon, ja olen varma siitä, että hän on voimallinen siihen päivään asti säilyttämään sen, mikä on uskottu minulle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Ota esikuvaksi ne terveelliset sanat, jotka olet minulta kuullut, uskossa ja rakkaudessa, joka on Kristuksessa Jeesuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Säilytä se hyvä, mikä on sinulle uskottu Pyhän Hengen kautta, joka meissä asuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Tiedät, että kaikki ne, jotka ovat Aasian maakunnassa, ovat kääntyneet minusta pois. Niiden joukossa ovat Fygellos ja Hermogenes.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Antakoon Herra laupeutta Onesiforoksen huonekunnalle, sillä usein hän on minua virvoittanut eikä ole kahlettani hävennyt,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'vaan kun hän tuli Roomaan, hän etsi minua ahkerasti ja löysi minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Suokoon Herra, että hän löytää laupeuden Herran luona sinä päivänä. Ja kuinka suuria olivatkaan ne palvelukset, joita hän teki Efesossa, sinä sen paremmin tiedät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Sinä, poikani, vahvistu siis siinä armossa, joka on Kristuksessa Jeesuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'Ja minkä olet kuullut minulta monen todistajan ollessa läsnä, usko se luotettaville miehille, jotka sitten ovat kykeneviä opettamaan muitakin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Kärsi siis kovia kuin jalo Kristuksen Jeesuksen sotilas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Ei kukaan, joka sodassa palvelee, sekaannu elatuksen toimiin, sillä hän tahtoo olla mieliksi sille, joka on hänet palkannut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Eihän sitäkään, joka kilpailee, seppelöidä, ellei hän kilpaile sääntöjen mukaisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Viljelijän, joka työn tekee, tulee ensimmäisenä saada osansa hedelmistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Ajattele, mitä sanon. Herra antakoon sinulle ymmärrystä kaikkeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Muista Jeesusta Kristusta, joka on kuolleista herätetty ja on Daavidin siementä evankeliumini mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'Siinä kärsin kovia kahleisiin asti kuin pahantekijä, mutta Jumalan sana ei ole kahlehdittu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Siitä syystä kestän kaiken valittujen tähden, että hekin saisivat pelastuksen, joka on Kristuksessa Jeesuksessa, sekä iankaikkisen kirkkauden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Varma on tämä sana. Sillä jos olemme kuolleet yhdessä hänen kanssaan, tulemme myös hänen kanssaan elämään;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'jos kestämme, tulemme hänen kanssaan myös hallitsemaan; jos kiellämme hänet, hän on kieltävä meidät;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'jos olemme uskottomia, pysyy kuitenkin hän uskollisena. Itseään hän ei voi kieltää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Muistuta tästä, ja todista heille Herran edessä, etteivät kiistelisi sanoista. Se ei ole miksikään hyödyksi, vaan niiden turmioksi, jotka kuulevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Ahkeroi osoittautumaan Jumalalle sellaiseksi, joka kestää koetuksen, työntekijäksi, joka ei työtään häpeä, joka jakaa oikein totuuden sanaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Mutta pysy erilläsi epäpyhistä ja tyhjistä puheista, sillä ne menevät yhä pidemmälle jumalattomuudessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'ja heidän puheensa jäytää ympäristöään kuin syöpä. Niitä ovat Hymenaios ja Filetos,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'jotka ovat totuudesta eksyneet, kun sanovat, että ylösnousemus on jo tapahtunut, ja he turmelevat eräiden uskon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Kuitenkin Jumalan vahva perustus pysyy lujana, ja siinä on tämä sinetti: \"Herra tuntee omansa\", ja: \"Luopukoon vääryydestä jokainen, joka Kristuksen nimeä mainitsee\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Mutta suuressa talossa ei ole ainoastaan kulta- ja hopea-astioita, vaan myös puu- ja saviastioita, ja toiset ovat jaloa, toiset halpaa käyttöä varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Jos nyt joku puhdistaa itsensä tällaisista, hänestä tulee astia jaloa käyttöä varten, pyhitetty, isännälleen hyödyllinen, kaikkiin hyviin tekoihin valmis.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Pakene nuoruuden himoja, mutta tavoittele vanhurskautta, uskoa, rakkautta, rauhaa niiden kanssa, jotka huutavat avukseen Herraa puhtaasta sydämestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Mutta vältä typeriä ja taitamattomia väittelyitä tietäen, että ne synnyttävät riitoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Mutta Herran palvelijan ei sovi riidellä, vaan hänen tulee olla lempeä kaikkia kohtaan, kyetä opettamaan ja pahaa sietämään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'Hänen tulee lempeästi ojentaa vastustelijoita. Ehkä Jumala antaa heille mielenmuutoksen, niin että tulevat tuntemaan totuuden');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'ja selviävät perkeleen ansasta, johon hän on vanginnut heidät noudattamaan tahtoaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Mutta tiedä, että viimeisinä päivinä on vaikeita aikoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Sillä ihmiset ovat silloin itserakkaita, rahanahneita, kerskureita, ylpeitä, Jumalaa pilkkaavia, vanhemmilleen tottelemattomia, kiittämättömiä, epähurskaita,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'rakkaudettomia, liiton rikkojia, panettelijoita, hillittömiä, raakoja, hyvää vihaavia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'pettureita, rajuja, pöyhkeitä, hekumaa enemmän kuin Jumalaa rakastavia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Heissä on jumalanpelon ulkokuori, mutta he kieltävät sen voiman. Sellaisia karta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Sillä niitä ovat ne, jotka tungettelevat taloihin ja kietovat pauloihinsa syntien rasittamia ja monenlaisten himojen heiteltäviä naisparkoja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'jotka ovat aina ottamassa opetusta eivätkä koskaan voi tulla totuuden tuntemiseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Ja niin kuin Jannes ja Jambres vastustivat Moosesta, niin nuokin vastustavat totuutta, nuo mieleltään turmeltuneet ihmiset, jotka eivät uskonkoetusta kestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Mutta he eivät edisty pitemmälle, sillä heidän mielettömyytensä on käyvä ilmeiseksi kaikille, niin kuin noidenkin mielettömyys kävi ilmi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Mutta sinä olet seurannut minun oppiani, vaellustani, harkintaani, uskoani, pitkämielisyyttäni, rakkauttani ja kärsivällisyyttäni,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'vainoissa ja kärsimyksissä, samanlaisissa kuin osakseni tuli Antiokiassa, Ikonionissa ja Lystrassa. Millaisia vainoja olenkaan kärsinyt, ja kaikista Herra on minut pelastanut!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Mutta kaikki, jotka tahtovat elää jumalanpelossa Kristuksessa Jeesuksessa, joutuvat vainottaviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Mutta pahat ihmiset ja petturit menevät yhä pidemmälle pahuudessa eksyttäen ja eksyen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Mutta pysy sinä siinä, minkä olet oppinut ja mistä olet varma, koska tiedät, keneltä olet sen oppinut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'ja koska jo pienestä pitäen tunnet Pyhät Kirjoitukset, jotka voivat tehdä sinut viisaaksi, että pelastut uskon kautta, joka on Kristuksessa Jeesuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Koko Raamattu on Jumalan Hengen vaikutuksesta syntynyt ja hyödyllinen opetukseksi, nuhteeksi, ojennukseksi ja kasvatukseksi vanhurskaudessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'jotta Jumalan ihminen olisi täydellinen, täysin valmiina kaikkiin hyviin tekoihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Minä vannotan sinua Jumalan ja Herran Kristuksen Jeesuksen edessä, joka on tuomitseva elävät ja kuolleet ilmestyessään ja valtakunnassaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'saarnaa sanaa, astu esiin sopivalla ja sopimattomalla ajalla, nuhtele, varoita, kehota, kaikella pitkämielisyydellä ja opetuksella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Sillä aika tulee, jolloin he eivät siedä tervettä oppia, vaan omien himojensa mukaan haalivat itselleen opettajia korvasyyhyynsä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'ja kääntävät korvansa pois totuudesta ja kääntyvät taruihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Mutta ole sinä raitis kaikessa, kärsi vaivaa, tee evankelistan työ, toimita virkasi täydellisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Sillä minut jo uhrataan, ja lähtöni aika on jo tullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Olen kilvoitellut hyvän kilvoituksen, juoksun päättänyt, uskon säilyttänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Tästedes minulle on talletettuna vanhurskauden seppele, jonka Herra, vanhurskas tuomari, antaa minulle sinä päivänä, eikä ainoastaan minulle, vaan myös kaikille, jotka rakastavat hänen ilmestymistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Kiirehdi pian tulemaan luokseni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Sillä tähän nykyiseen maailmaan rakastuneena Deemas jätti minut ja matkusti Tessalonikaan, Kreskes meni Galatiaan ja Tiitus Dalmatiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Vain Luukas on kanssani. Ota Markus mukaasi ja tuo hänet tänne, sillä hän on minulle hyvin tarpeellinen palvelukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Mutta Tykikuksen olen lähettänyt Efesoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Tuo tullessasi päällysviitta, jonka jätin Trooaaseen Karpoksen luo, ja kirjat, ennen kaikkea pergamentit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Aleksander, vaskiseppä, on tehnyt minulle paljon pahaa. Herra on maksava hänelle hänen tekojensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Pysy sinäkin erossa hänestä, sillä hän on kovasti vastustanut sanojamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Ensi kertaa puolustautuessani kukaan ei tullut avukseni, vaan kaikki jättivät minut. Älköön sitä heille syyksi luettako.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Mutta Herra oli tukenani ja vahvisti minua, että sanan julistaminen kauttani tulisi täysin suoritetuksi, ja kaikki pakanat sen kuulisivat, ja pelastuin leijonan kidasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Herra on vapauttava minut kaikesta ilkivallasta ja pelastava minut taivaalliseen valtakuntaansa. Hänelle kunnia iäisyyksien iäisyyksiin. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Tervehdys Priskalle, Akylaalle ja Onesiforoksen huonekunnalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erastos jäi Korinttoon, mutta Trofimoksen jätin Miletoon sairastamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Yritä päästä tulemaan ennen talvea. Tervehdyksen lähettävät sinulle Eubulos, Pudes, Linos, Klaudia ja kaikki veljet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Herra Jeesus Kristus olkoon henkesi kanssa. Armo olkoon kanssanne. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paavali, Jumalan palvelija ja Jeesuksen Kristuksen apostoli Jumalan valittujen uskoa ja jumalanpelon mukaista totuuden tuntemista varten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'sen iankaikkisen elämän toivon perusteella, jonka Jumala, joka ei valehtele, on luvannut ennen ikuisia aikoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'Mutta hän ilmoitti sanansa omalla ajallaan saarnassa, joka uskottiin minulle Jumalan, meidän vapahtajamme käskyn mukaan:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Tiitukselle, oikealle pojalleni yhteisen uskomme mukaan. Armo ja rauha Isältä Jumalalta ja Vapahtajaltamme Kristukselta Jeesukselta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Minä jätin sinut Kreetalle sitä varten, että järjestäisit, mitä vielä jäi järjestämättä, ja että asettaisit, niin kuin minä sinulle määräsin, joka kaupunkiin vanhimmat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'jos olisi joku nuhteeton, yhden vaimon mies, jonka lapset ovat uskovia, eivät irstaudesta syytettyjä eivätkä niskoittelevia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Sillä kaitsijan on, niin kuin Jumalan huoneenhaltijan tulee, oltava nuhteeton, ei itserakas, ei äkkipikainen, ei juomari, ei riitelijä, ei häpeällisen voiton pyytäjä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'vaan vieraanvarainen, hyvää rakastava, maltillinen, vanhurskas, pyhä, itsensä hillitsevä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'Hänen tulee pysyä kiinni opinmukaisessa, luotettavassa sanassa, että olisi kykenevä sekä lohduttamaan terveellä opilla että nuhtelemaan vastaansanojia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Sillä paljon on niskoittelevia, turhanpuhujia ja eksyttäjiä, varsinkin ympärileikatuista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Sellaisilta on suu tukittava, sillä he kääntävät ylösalaisin kokonaisia huonekuntia opettamalla sopimattomia häpeällisen voiton vuoksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Eräs heistä, heidän oma profeettansa, on sanonut: \"Petturi Kreetan mies, peto ilkeä, ahmatti laiska.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Tämä todistus on tosi. Sen tähden nuhtele heitä ankarasti, että tulisivat uskossa terveiksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'eivätkä kiinnittäisi huomiotaan juutalaisiin taruihin eivätkä totuudesta pois kääntyvien ihmisten käskyihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Kaikki on puhdasta puhtaille, mutta saastaisille ja uskottomille mikään ei ole puhdasta, vaan heidän sekä mielensä että omatuntonsa on saastainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'He väittävät tuntevansa Jumalan, mutta kieltävät hänet teoillaan, sillä he ovat inhottavia, tottelemattomia ja kaikkiin hyviin tekoihin kelvottomia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Mutta puhu sinä sitä, mikä sopii terveeseen oppiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Vanhat miehet olkoot raittiita, arvokkaita, hurskaita ja uskossa, rakkaudessa ja kärsivällisyydessä terveitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'Samoin vanhat naiset olkoot käytöksessään kuten pyhien sopii, ei panettelijoita, ei paljon viinin orjia, vaan hyvään opettajia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'voidakseen neuvoa nuoria naisia rakastamaan miehiään ja lapsiaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'olemaan itsensä hillitseviä, puhtaita, hyviä kotinsa hoitajia, alamaisia omille miehilleen, ettei Jumalan sana tulisi pilkatuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Nuorempia miehiä kehota samoin käyttäytymään itsensä hilliten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'Aseta itsesi kaikessa hyvien tekojen esikuvaksi, puhtaassa opissa, arvokkuudessa ja turmeltumattomuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'Olkoon puheesi tervettä ja moitteetonta, että vastustaja häpeäisi, kun hänellä ei ole mitään pahaa sanottavana meistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Kehota palvelijoita olemaan isännilleen kaikessa alamaisia, heille mieliksi, etteivät vastustele,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'etteivät näpistele, vaan kaikin tavoin osoittavat rehtiä uskollisuutta, että he kaunistaisivat kaikessa Jumalan, meidän vapahtajamme, opin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Sillä Jumalan pelastava armo on ilmestynyt kaikille ihmisille');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'ja kasvattaa meitä, jotta hyläten jumalattomuuden ja maailmalliset himot eläisimme itsemme hilliten vanhurskaasti ja jumalanpelossa nykyisessä maailmanajassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'odottaessamme autuaan toivon täyttymistä ja suuren Jumalamme ja Vapahtajamme Kristuksen Jeesuksen kirkkauden ilmestymistä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'hänen, joka antoi itsensä edestämme lunastaakseen meidät kaikesta laittomuudesta ja puhdistaakseen itselleen omaisuudeksi kansan, joka tekee ahkerasti hyviä tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Puhu tätä, kehota ja nuhtele kaikella käskyvallalla. Älköön kukaan halveksiko sinua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Muistuta heitä olemaan hallituksille ja esivalloille alamaisia ja kuuliaisia sekä kaikkiin hyviin tekoihin valmiita,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'etteivät ketään herjaa, eivät riitele, vaan ovat lempeitä ja osoittavat kaikkea sävyisyyttä kaikkia ihmisiä kohtaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Olimmehan mekin ennen ymmärtämättömiä, tottelemattomia, eksyksissä, monien himojen ja nautintojen orjia, elimme pahuudessa ja kateudessa, olimme inhottavia ja vihasimme toisiamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Mutta kun Jumalan, meidän vapahtajamme, hyvyys ja ihmisrakkaus ilmestyi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'hän pelasti meidät, ei vanhurskaudessa tekemiemme tekojen ansiosta, vaan laupeutensa mukaan uudestisyntymisen pesun ja Pyhän Hengen uudistuksen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'Tämän Hengen hän runsaasti vuodatti meihin Vapahtajamme Jeesuksen Kristuksen kautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'että me vanhurskaiksi julistettuina hänen armonsa kautta tulisimme iankaikkisen elämän perillisiksi toivon mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Tämä sana on varma, ja tahdon, että sinä näitä teroitat lujasti mieliin, niin että ne, jotka ovat Jumalaan uskoneet, harjoittaisivat ahkerasti hyviä tekoja. Ne ovat hyviä ja hyödyllisiä ihmisille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Mutta vältä typeriä riitakysymyksiä ja sukuluetteloita sekä kinastelua ja kiistoja laista, sillä ne ovat hyödyttömiä ja turhia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Harhaoppista ihmistä karta, varoitettuasi häntä kerran tai kahdesti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'sillä tiedät, että sellainen ihminen on joutunut harhaan ja tekee syntiä itse itsensä tuominneena.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Kun lähetän luoksesi Artemaan tai Tykikoksen, tule viipymättä luokseni Nikopoliin, sillä olen päättänyt viettää talven siellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Varusta huolellisesti matkalle Zeenas, lainoppinut, ja Apollos, ettei heiltä puuttuisi mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Oppikoot meikäläisetkin tarpeen vaatiessa harjoittamaan hyviä tekoja, etteivät olisi hedelmättömiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Tervehdyksen lähettävät sinulle kaikki, jotka ovat kanssani. Sano tervehdys niille, jotka pitävät meitä rakkaina uskossa. Armo olkoon teidän kaikkien kanssa. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paavali, Kristuksen Jeesuksen vanki, ja veli Timoteus rakkaalle Filemonille, työtoverillemme,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'ja Appialle, rakkaalle sisarellemme, ja Arkippokselle, taistelutoverillemme, ja kodissasi kokoontuvalle seurakunnalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Armo teille ja rauha Jumalalta, Isältämme, ja Herralta Jeesukselta Kristukselta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Kiitän Jumalaani aina muistaessani sinua rukouksissani,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'sillä minä olen kuullut rakkaudestasi ja uskostasi, joka sinulla on Herraan Jeesukseen ja kaikkia pyhiä kohtaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'että uskosi, se usko, joka on meille yhteinen, olisi voimallinen kaiken hyvän tuntemisessa, mikä teillä on Kristuksessa Jeesuksessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Sillä olemme saaneet paljon iloa ja lohdutusta rakkaudestasi, koska pyhien sydämet ovat virkistyneet kauttasi, veljeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Sen tähden, vaikka minulla on Kristuksessa paljonkin rohkeutta käskeä sinua tekemään, mitä tulee tehdä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'niin rakkauden tähden mieluummin pyydän ollen tämmöinen kuin olen, vanha Paavali, ja nyt myös Kristuksen Jeesuksen vanki –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'pyydän sinua poikani puolesta, jonka kahleissani synnytin, Onesimoksen puolesta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'sinulle ennen hyödyttömän, mutta nyt sekä sinulle että minulle hyödyllisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Hänet lähetän takaisin, että ottaisit hänet vastaan, se on: oman sydämeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Minä olisin tahtonut pitää hänet luonani, että hän sinun sijastasi olisi palvellut minua, joka olen evankeliumin tähden kahleissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Ilman suostumustasi en kuitenkaan tahtonut tehdä mitään, ettei hyvyytesi olisi ikään kuin pakollista, vaan vapaaehtoista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Sillä ehkäpä hänet sen tähden erotettiin sinusta ajaksi, että saisit hänet takaisin iäksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'ei enää orjana, vaan orjaa enempänä: rakkaana veljenä, varsinkin minulle, kuinka paljoa enemmän sitten sinulle, sekä lihassa että Herrassa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Jos siis pidät minua toverinasi, ota hänet luoksesi kuin minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Mutta jos hän on tehnyt jotakin vääryyttä sinulle tai on sinulle jotakin velkaa, pane se minun laskuuni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Minä, Paavali, kirjoitan omalla kädelläni: \"Minä sen korvaan\"; sanoisinko sinulle, että olet minulle velkaa oman itsesikin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Niin, veljeni, jospa minä hyötyisin sinusta Herrassa: virkistä sydäntäni Herrassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Luottaen kuuliaisuuteesi kirjoitan sinulle tietäen, että teet enemmänkin, kuin mitä sanon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Lisäksi vielä: valmista minulle majoitus luonasi. Toivon näet, että minut rukoustenne kautta lahjoitetaan teille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Tervehdyksen lähettävät sinulle Epafras, vankitoverini Kristuksessa Jeesuksessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Markus, Aristarkus, Deemas ja Luukas, jotka ovat työtovereitani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Herran Jeesuksen Kristuksen armo olkoon teidän henkenne kanssa. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Kun Jumala oli muinoin puhunut monta kertaa ja monella tapaa isille profeettojen kautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'hän on puhunut näinä viimeisinä päivinä meille Pojan kautta. Hänet hän on asettanut kaiken perilliseksi, jonka kautta hän on myös luonut maailman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Hän on hänen kirkkautensa säteily ja hänen olemuksensa kuva ja kantaa kaiken sanansa voimalla. Toimitettuaan puhdistuksen synneistämme hän on istuutunut Majesteetin oikealle puolelle korkeuksissa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'ja tullut enkeleitä niin paljon korkeammaksi, kuin hänen perimänsä nimi on jalompi kuin heidän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Sillä kenelle enkeleistä hän on koskaan sanonut: \"Sinä olet minun Poikani, tänä päivänä minä sinut synnytin\", ja: \"Minä olen oleva hänen Isänsä, ja hän on oleva minun Poikani\"?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Siitä, kun hän tuo jälleen esikoisensa maailmaan, hän sanoo: \"Kumartakoot häntä kaikki Jumalan enkelit.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Enkeleistä hän sanoo: \"Hän tekee enkelinsä tuuliksi ja palvelijansa liekehtiväksi tuleksi\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'mutta Pojasta: \"Jumala, sinun valtaistuimesi on iankaikkisesta iankaikkiseen, ja sinun valtakuntasi valtikka on oikeuden valtikka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Sinä rakastit vanhurskautta ja vihasit laittomuutta. Sen tähden Jumala, sinun Jumalasi, on voidellut sinua iloöljyllä enemmän kuin tovereitasi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Ja: \"Sinä, Herra, olet alussa maan perustanut, ja taivaat ovat kättesi tekoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Ne katoavat, mutta sinä pysyt, ja ne vanhenevat kaikki kuin vaate,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'ja kuin viitan käärit ne, kuin vaatteen, ja ne muuttuvat, mutta sinä olet sama, eivätkä sinun vuotesi lopu.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Kenelle enkeleistä hän on koskaan sanonut: \"Istu oikealle puolelleni, kunnes panen vihollisesi jalkojesi astinlaudaksi\"?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Eivätkö he kaikki ole palvelevia henkiä, palvelukseen lähetettyjä niitä varten, jotka perivät autuuden?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Sen tähden meidän tulee mitä tarkimmin ottaa vaari siitä, mitä olemme kuulleet, ettemme ajaudu siitä ohi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Sillä jos enkelien kautta puhuttu sana pysyi lujana, ja jokainen rikkominen ja tottelemattomuus sai oikeudenmukaisen palkkansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'kuinka me pääsemme pakoon, jos emme välitä tuosta niin suuresta pelastuksesta, jonka Herra alkuaan julisti ja jonka vahvistivat meille ne, jotka olivat sen kuulleet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'kun Jumala yhdessä heidän kanssaan todisti tunnusmerkeillä, ihmeillä ja monilla voimateoilla sekä jakamalla Pyhää Henkeä tahtonsa mukaan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Sillä hän ei alistanut enkelien alle tulevaa maailmaa, josta puhumme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Vaan joku on jossakin todistanut sanoen: \"Mikä on ihminen, että häntä muistat, tai Ihmisen Poika, että pidät hänestä huolen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Sinä teit hänet vähäksi aikaa enkeleitä halvemmaksi, kirkkaudella ja kunnialla sinä hänet seppelöit, ja asetit hänet hallitsemaan kättesi tekoja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'asetit kaiken hänen jalkojensa alle.\" Sillä, asettaessaan kaiken hänen valtansa alle, hän ei jättänyt mitään hänen alleen alistamatta. Mutta nyt emme vielä näe kaikkea hänen valtansa alle asetettuna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Mutta hänet, joka vähäksi aikaa oli tehty enkeleitä halvemmaksi, Jeesuksen, me näemme hänen kuolemansa kärsimyksen tähden kirkkaudella ja kunnialla seppelöitynä, että hän Jumalan armosta olisi kaikkien edestä maistanut kuoleman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Sillä hänen, jonka tähden kaikki on ja jonka kautta kaikki on, sopi, saattaessaan paljon lapsia kirkkauteen, kärsimysten kautta tehdä heidän pelastuksensa päämies täydelliseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Sillä sekä hän, joka pyhittää, että ne, jotka pyhitetään, ovat kaikki lähtöisin yhdestä. Siitä syystä hän ei häpeä kutsua heitä veljiksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'sanoessaan: \"Julistan sinun nimeäsi veljilleni, laulan ylistystä sinulle seurakunnan keskellä\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'ja taas: \"Minä panen uskallukseni häneen\", ja taas: \"Katso, minä ja lapset, jotka Jumala on minulle antanut!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Koska siis lapsilla on veri ja liha, hänkin tuli niistä yhtäläisellä tavalla osalliseksi kukistaakseen kuoleman kautta sen, jolla oli kuolema vallassaan, se on perkeleen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'ja vapauttaakseen kaikki ne, jotka kuoleman pelosta koko elämänsä olivat olleet orjuuden alaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Sillä tosiaankaan hän ei ota huostaansa enkeleitä, vaan Aabrahamin siemenen hän ottaa huostaansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Sen tähden hänen piti tulla kaikessa veljiensä kaltaiseksi, että hän olisi laupias ja uskollinen ylipappi tehtävissään Jumalan edessä sovittaakseen kansan synnit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Sillä sen tähden, että hän itse on kärsinyt ja ollut kiusattu, hän voi kiusattuja auttaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Sen tähden, pyhät veljet, jotka olette taivaallisesta kutsumuksesta osallisia, kiinnittäkää mielenne tunnustuksemme apostoliin ja ylipappiin, Jeesukseen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'joka on uskollinen asettajalleen, niin kuin Mooseskin oli \"uskollinen koko hänen talossaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Sillä hänen on katsottu ansaitsevan niin paljon Moosesta suuremman kirkkauden, kuin talon rakentajan kunnia on suurempi kuin talon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Sillä jokainen talo on jonkun rakentama, mutta kaiken rakentaja on Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Mooses tosin oli \"palvelijana uskollinen koko hänen talossaan\", todistukseksi siitä, mitä tullaan puhumaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'mutta Kristus on uskollinen Poikana, hänen talonsa hallitsijana. Hänen talonsa olemme me, jos loppuun asti pidämme vahvana toivon rohkeuden ja kerskauksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Sen tähden, niin kuin Pyhä Henki sanoo: \"Tänä päivänä, jos te kuulette hänen äänensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'älkää paaduttako sydämiänne, niin kuin teitte vihoittaessanne minut kiusauksen päivänä erämaassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'jossa isänne kiusasivat ja koettelivat minua, vaikka näkivät tekojani neljäkymmentä vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Sen tähden vihastuin tähän sukukuntaan ja sanoin: \'Jatkuvasti he eksyvät sydämessään\', mutta he eivät oppineet tuntemaan minun teitäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Niin vannoin vihassani: \'He eivät pääse lepooni.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Katsokaa, veljet, ettei vain kenelläkään teistä ole paha, epäuskoinen sydän, niin että hän luopuu elävästä Jumalasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'vaan kehottakaa toisianne joka päivä, niin kauan kuin sanotaan: \"tänä päivänä\", ettei teistä kukaan synnin pettämänä paatuisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Sillä olemme tulleet osallisiksi Kristuksesta, kunhan vain pysymme luottamuksessa, joka meillä oli alussa, vahvoina loppuun asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Sanotaanhan: \"Tänä päivänä, jos te kuulette hänen äänensä, älkää paaduttako sydämiänne, niin kuin silloin, kun vihoititte hänet\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Ketkä sitten, vaikka kuulivat, vihoittivat hänet? Eivätkö kaikki, jotka olivat Mooseksen johdolla lähteneet Egyptistä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Mutta keihin hän oli vihastunut neljäkymmentä vuotta? Eikö niihin, jotka olivat syntiä tehneet, joiden kuolleet ruumiit kaatuivat erämaahan?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Keille hän vannoi, etteivät he pääse hänen lepoonsa? Eikö tottelemattomille?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Havaitsemme, etteivät he epäuskon tähden voineet siihen päästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Pelätkäämme siis, koska lupaus päästä hänen lepoonsa vielä pysyy, ettei kenenkään teistä havaittaisi myöhästyneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Sillä hyvä sanoma on julistettu meille niin kuin heillekin. Mutta heidän kuulemansa sana ei hyödyttänyt heitä, koska se ei uskossa yhdistynyt niihin, jotka sen kuulivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Sillä pääsemme lepoon, me, jotka olemme uskoneet, niin kuin hän on sanonut: \"Niin minä vihassani vannoin: \'He eivät pääse minun lepooni\'\", vaikka hänen tekonsa ovat olleet valmiina maailman perustamisesta asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Sillä hän on jossakin sanonut seitsemännestä päivästä näin: \"Jumala lepäsi seitsemäntenä päivänä kaikista teoistaan\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'ja tässä taas: \"He eivät pääse minun lepooni.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Koska siis pysyy voimassa, että muutamat pääsevät siihen, ja ne, joille evankeliumi ensin julistettiin, eivät päässeet siihen tottelemattomuuden tähden,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'hän jälleen määrää tietyn päivän, \"tämän päivän\", sanomalla Daavidin kautta niin pitkän ajan jälkeen, kuten on sanottu: \"Tänä päivänä, jos te kuulette hänen äänensä, älkää paaduttako sydämiänne.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Sillä jos Joosua olisi saattanut heidät lepoon, hän ei puhuisi toisesta, sen jälkeisestä päivästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Niin on sapatinlepo Jumalan kansalle vielä jäljellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Sillä se, joka on päässyt hänen lepoonsa, on saanut levon teoistaan, hänkin, niin kuin Jumala omista teoistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Ahkeroikaamme siis päästä siihen lepoon, ettei kukaan lankeaisi seuraamaan samaa tottelemattomuuden esimerkkiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Sillä Jumalan sana on elävä ja voimallinen ja terävämpi kuin mikään kaksiteräinen miekka ja tunkee lävitse, kunnes se erottaa sielun ja hengen, nivelet sekä ytimet, ja on sydämen ajatusten ja aikeitten tuomitsija.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Mikään luotu ei ole hänelle näkymätön, vaan kaikki on alastonta ja paljastettua hänen silmiensä edessä, jolle meidän on tehtävä tili.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Kun meillä siis on suuri ylipappi, läpi taivaitten kulkenut, Jeesus, Jumalan Poika, pitäkäämme kiinni tunnustuksesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Sillä meillä ei ole sellainen ylipappi, joka ei voi sääliä heikkouksiamme, vaan joka on ollut kaikessa kiusattu samalla lailla kuin mekin, kuitenkin ilman syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Tulkaamme sen tähden rohkeasti armon valtaistuimen eteen, että saisimme laupeuden ja löytäisimme armon avuksemme oikeaan aikaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Sillä jokainen ihmisten joukosta otettu ylipappi asetetaan ihmisten puolesta toimittamaan sitä, mikä Jumalalle tulee: uhraamaan lahjoja ja uhreja syntien edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Hän voi kohdella säälien tietämättömiä ja eksyviä, koska hän on itsekin heikkouden alainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'Tämän heikkoutensa tähden hänen täytyy, samoin kuin kansan puolesta, uhrata itsensäkin puolesta syntien edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Kukaan ei ota sitä arvoa itselleen, vaan Jumala kutsuu hänet kuten Aaroninkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Samoin Kristuskaan ei itse asettanut itseään kunniaan ollakseen ylipappi, vaan hän, joka sanoi hänelle: \"Sinä olet minun Poikani, tänä päivänä minä sinut synnytin\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'niin kuin hän toisessakin paikassa sanoo: \"Sinä olet pappi iankaikkisesti Melkisedekin järjestyksen mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Lihansa päivinä hän väkevällä huudolla ja kyynelillä uhrasi rukouksia ja anomuksia sille, joka voi hänet kuolemasta pelastaa, ja hänen rukouksensa kuultiin hänen jumalanpelkonsa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Vaikka hän oli Poika, hän oppi siitä, mitä hän kärsi, kuuliaisuuden,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'ja kun oli täydelliseksi tullut, hän tuli iankaikkisen autuuden aikaansaajaksi kaikille, jotka ovat hänelle kuuliaisia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'hän, jota Jumala nimittää \"ylipapiksi Melkisedekin järjestyksen mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Tästä meillä on paljon sanottavaa, ja sitä on vaikea selittää, koska olette tulleet hitaiksi kuulemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Sillä te, joiden olisi aika olla jo opettajia, olette taas sen tarpeessa, että teille opetetaan Jumalan sanojen ensimmäisiä alkeita, ja olette maitoa tarvitsevia, ette vahvaa ruokaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Sillä jokainen, joka vielä nauttii maitoa, on kokematon vanhurskauden sanassa, sillä hän on lapsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Vahva ruoka taas on täysi-ikäisiä varten, niitä varten, joiden aistit ovat harjaantuneet erottamaan hyvän ja pahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Jättäkäämme sen tähden Kristuksen opin alkeet ja kulkekaamme kohti täydellisyyttä ryhtymättä taas uudestaan laskemaan perustusta: parannusta kuolleista töistä ja uskoa Jumalaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'ja oppia kasteista, sekä kättenpäällepanosta, kuolleitten ylösnousemisesta ja iankaikkisesta tuomiosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Niin teemmekin, jos vain Jumala sallii.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Sillä mahdotonta on niitä, jotka kerran ovat valaistut ja taivaallista lahjaa maistaneet ja tulleet osallisiksi Pyhästä Hengestä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'ja maistaneet Jumalan hyvää sanaa ja tulevan maailman voimia,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'ja luopuneet – taas uudistaa parannukseen, he kun jälleen ristiinnaulitsevat itselleen Jumalan Pojan ja julkisesti häpäisevät häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Sillä maa, joka imee sisäänsä sen päälle usein tulevan sateen ja kantaa kasvun hyödyksi niille, joita varten sitä viljelläänkin, saa siunauksen Jumalalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Mutta maa, joka tuottaa orjantappuroita ja ohdakkeita, on kelvoton ja lähellä kirousta, jonka loppu on se, että se poltetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Mutta teistä, rakkaat, uskomme sitä, mikä on parempaa ja on pelastukseksi – vaikka puhummekin näin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Sillä Jumala ei ole väärä, että hän unohtaisi työnne ja rakkautenne vaivannäön, jota olette osoittaneet hänen nimeään kohtaan, kun olette palvelleet pyhiä ja yhä palvelette.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Mutta me pyrimme siihen, että jokainen teistä osoittaa samaa intoa säilyttääkseen varman toivon loppuun asti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'ettette olisi laiskoja, vaan että olisitte niiden seuraajia, jotka uskon ja kärsivällisyyden kautta perivät luvatun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Sillä Jumala oli luvannut Aabrahamille vannoen itsensä kautta, koska ei ollut ketään suurempaa, jonka kautta vannoa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'sanoen: \"Totisesti, siunaamalla sinut siunaan, ja enentämällä sinut enennän.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Näin Aabraham kärsivällisesti odotettuaan sai, mitä oli luvattu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Sillä ihmiset vannovat suurempansa kautta, ja vala on heille asian vahvistus ja tekee lopun kaikista vastaväitteistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Sen tähden, kun Jumala tahtoi lupauksen perillisille osoittaa vielä vakuuttavammin, että hänen päätöksensä on muuttumaton, hän vakuutti sen valalla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'että me näistä kahdesta muuttumattomasta asiasta, joissa Jumala ei ole voinut valehdella, saisimme voimakkaan kehotuksen, me, jotka olemme paenneet pitämään kiinni edessä olevasta toivosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Se toivo on meille kuin sielun ankkuri, varma ja luja, joka ulottuu esiripun sisäpuolelle asti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'jonne Jeesus edeltä juoksijana meidän puolestamme on mennyt tultuaan ylipapiksi Melkisedekin järjestyksen mukaan, iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Sillä tämä Melkisedek, Saalemin kuningas, Jumalan, Korkeimman, pappi, meni Aabrahamia vastaan, kun tämä palasi lyötyään kuninkaat, ja siunasi hänet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'Hänelle Aabraham myös antoi kymmenykset kaikesta. Kuten hänen nimensäkin merkitsee, hän on ensiksikin \"vanhurskauden kuningas\" ja sen lisäksi vielä \"Saalemin kuningas\", se on \"rauhan kuningas\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Hänellä ei ole isää, äitiä, sukuluetteloa, ei päivien alkua eikä elämän loppua, vaan hän on verrattavissa Jumalan Poikaan, ja pysyy jatkuvasti pappina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Katsokaa, kuinka suuri hän on, jolle itse kantaisä Aabraham antoi kymmenykset saaliistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Onhan niillä Leevin pojista, jotka saavat pappeuden, käsky lain mukaan ottaa kymmenyksiä kansalta, se on veljiltään, vaikka nämä ovatkin Aabrahamin lanteista lähteneitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'mutta se, jonka sukua ei johdeta heistä, otti kymmenykset Aabrahamilta ja siunasi sen, jolla oli lupaukset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Onhan kiistatonta, että halvempi saa siunauksen korkeammaltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Täällä kuolevaiset ihmiset ottavat kymmenyksiä, mutta siellä se, jonka todistetaan elävän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Aabrahamin kautta, niin sanoakseni, on Leevikin, joka ottaa kymmenyksiä, maksanut kymmenyksiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'sillä hän oli vielä isänsä lanteissa, kun Melkisedek meni Aabrahamia vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Jos siis täydellisyys olisi leeviläisen pappeuden kautta, sillä tähän on kansa laissa sidottu, miksi oli vielä tarpeen, että nousi toinen pappi Melkisedekin järjestyksen mukaan eikä tullut nimitetyksi Aaronin järjestyksen mukaan?.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Pappeuden muuttuessa tapahtuu näet välttämättä myös lain muutos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Sillä se, josta tämä sanotaan, oli toista sukukuntaa, josta kukaan ei ole hoitanut alttaria.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Onhan selvää, että Herramme on noussut Juudasta, jonka sukukunnan pappeudesta Mooses ei ole puhunut mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Tämä tulee vielä paljon selvemmäksi, kun nousee toinen pappi, Melkisedekin kaltainen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'joka ei ole pappi lihallisen käskyn lain mukaan, vaan katoamattoman elämän voimasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Sillä hänestä todistetaan: \"Sinä olet pappi iankaikkisesti Melkisedekin järjestyksen mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Täten kyllä edellinen käsky kumotaan, koska se oli heikko ja hyödytön');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, '– sillä laki ei tehnyt ketään täydelliseksi, mutta tilalle tulee parempi toivo, jonka kautta lähestymme Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Ja niin kuin tämä ei tapahtunut ilman valan vannomista – nuo taas ovat tulleet papeiksi ilman heistä vannottua valaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'mutta tämä sen valalla, joka sanoi hänelle: \"Herra on vannonut eikä kadu: \'Sinä olet pappi iankaikkisesti Melkisedekin järjestyksen mukaan\'\" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Niin on myös parempi se liitto, jonka takaajaksi Jeesus on tullut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Noita toisia pappeja onkin ollut useampia, koska kuolema esti heitä pysymästä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'mutta sen tähden että hän pysyy iankaikkisesti, hänellä on pysyvä pappeus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Sen tähden hän myös voi täydellisesti pelastaa ne, jotka hänen kauttaan tulevat Jumalan luo, koska hän aina elää rukoillakseen heidän puolestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Sellainen ylipappi meille sopikin: pyhä, viaton, tahraton, syntisistä erotettu ja taivaita korkeampi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'jonka ei tarvitse joka päivä, niin kuin ylipappien, ensiksi uhrata omien syntiensä edestä ja sitten kansan, sillä tämän hän teki kerta kaikkiaan uhratessaan itsensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Sillä laki asettaa ylipapeiksi ihmisiä, jotka ovat heikkoja, mutta valan sana, joka on myöhempi kuin laki, asettaa Pojan, iankaikkisesti täydelliseksi tulleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Mutta pääasia siinä, mistä puhumme, on: meillä on sellainen ylipappi, joka istuu Majesteetin valtaistuimen oikealla puolella taivaissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'pyhäkön, sen oikean telttamajan palvelijana, jonka on rakentanut Herra eikä ihminen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Sillä jokainen ylipappi asetetaan uhraamaan lahjoja ja uhreja, jonka tähden on välttämätöntä, että tälläkin on uhraamista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Jos hän näet olisi maan päällä, hän ei olisikaan pappi, koska jo ovat olemassa ne papit, jotka lain mukaan kantavat esiin lahjoja,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'ja jotka palvelevat siinä, mikä on taivaallisten kuva ja varjo, niin kuin ilmoitettiin Moosekselle, kun hänen oli valmistettava maja. Sillä hänelle sanottiin: \"Katso, että teet kaiken sen kaavan mukaan, joka näytettiin sinulle vuorella.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Mutta tämä taas on saanut niin paljon jalomman viran, kuin hän on myös paremman liiton välimies, liiton, joka on säädetty lailla paremmille lupauksille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Sillä jos ensimmäinen liitto olisi ollut moitteeton, ei olisi etsitty sijaa toiselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Sillä moittien heitä hän sanoo: \"Katso, päivät tulevat, sanoo Herra, jolloin solmin Israelin heimon ja Juudan heimon kanssa uuden liiton,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'en sellaista liittoa kuin se, jonka minä tein heidän isiensä kanssa sinä päivänä, kun tartuin heitä kädestä ja vein heidät pois Egyptin maasta. Sillä he eivät pysyneet minun liitossani, enkä minäkään heistä huolinut, sanoo Herra.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Sillä tämä on se liitto, jonka teen Israelin heimon kanssa näiden päivien jälkeen, sanoo Herra: Panen lakini heidän mieleensä, ja kirjoitan ne heidän sydämiinsä, ja olen heidän Jumalansa, ja he ovat minun kansani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Silloin kukaan ei enää opeta lähimmäistään eikä veli veljeään sanoen: \'Tunne Herra\', sillä he kaikki, pienimmästä suurimpaan, tuntevat minut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Sillä olen armahtavainen heidän vääryyksiään ja syntejään kohtaan enkä enää muista heidän laittomuuksiaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Sanoessaan \"uuden\" hän on julistanut ensimmäisen liiton vanhentuneeksi. Mutta se, mikä on tullut vanhaksi ja on yliaikaista, on lähellä häviämistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Olihan tosin ensimmäiselläkin liitolla jumalanpalvelussäännöt ja maallinen pyhäkkö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Sillä maja oli valmistettu niin, että siinä oli etuosa, jossa oli sekä lampunjalka että pöytä ja näkyleivät, ja sen nimi on \"pyhä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Mutta toisen esiripun takana oli se maja, jonka nimi on \"kaikkeinpyhin\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Siinä oli kultainen suitsutusalttari ja liiton arkki, ympäriinsä kullalla päällystetty, jossa olivat mannaa sisältävä kultaruukku, Aaronin viheriöinyt sauva ja liiton taulut,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'ja arkin päällä kirkkauden kerubit varjostamassa armoistuinta. Mutta näistä nyt ei ole syytä puhua jokaisesta erikseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Kun nyt kaikki on näin järjestetty, menevät papit joka kerta etumaiseen majaan jumalanpalvelusta toimittamaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'mutta toiseen majaan menee ainoastaan ylipappi kerran vuodessa, ei ilman verta, jonka hän uhraa itsensä edestä ja kansan tahattomien syntien edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Näin Pyhä Henki osoittaa, että tie kaikkeinpyhimpään on vielä ilmoittamatta, niin kauan kuin etumainen maja on vielä pystyssä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Tämä on nykyistä aikaa tarkoittava vertauskuva, ja sen mukaisesti uhrataan lahjoja ja uhreja, jotka eivät kykene tekemään omassatunnossaan täydelliseksi jumalanpalveluksen pitäjää,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'vaan jotka, niin kuin ruuat ja juomat ja erilaiset pesutkin ja lihaa koskevat säännöt ovat voimassa uuden järjestyksen aikaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Mutta kun Kristus tuli esiin tulevaisen hyvän ylipappina, hän suuremman ja täydellisemmän majan kautta, jota ei ole käsillä tehty, se on: joka ei ole tätä luomakuntaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'meni, ei pukkien ja vasikkain veren kautta, vaan oman verensä kautta kerta kaikkiaan pyhään ja sai aikaan iankaikkisen lunastuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Sillä jos pukkien ja härkien veri ja hiehon tuhka saastaisten päälle vihmottuna pyhittää lihanpuhtauteen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'kuinka paljoa enemmän on Kristuksen veri, hänen, joka iankaikkisen Hengen kautta uhrasi itsensä viattomana Jumalalle, puhdistava omantuntonne kuolleista teoista palvelemaan elävää Jumalaa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Sen tähden hän on Uuden liiton välimies, että ne, jotka ovat kutsutut, saisivat luvatun iankaikkisen perinnön, koska hänen kuolemansa on tapahtunut lunastukseksi ensimmäisen liiton aikaisista rikkomisista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Sillä siinä, missä on testamentti, on sen tekijän kuolema näytettävä toteen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'vasta kuoleman jälkeen testamentti on näet pitävä, koska se ei ole milloinkaan voimassa testamentintekijän eläessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Sen tähden ensimmäistä liittoakaan ei vihitty ilman verta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Sillä kun Mooses oli lukenut koko kansalle julki kaikki käskyt, niin kuin ne laissa kuuluvat, hän otti vasikoiden ja pukkien veren sekä vettä, purppuravillaa ja iisopin ja vihmoi sekä itse kirjakäärön että kaiken kansan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'sanoen: \"Tämä on sen liiton veri, jonka Jumala on teille säätänyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Samoin hän vihmoi verellä myös majan ja kaikki palvelusesineet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Niin puhdistetaan lain mukaan lähes kaikki verellä, ja ilman verenvuodatusta ei ole anteeksiantamusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'On siis välttämätöntä, että taivaallisten esikuvat puhdistetaan tällä tavalla, mutta että itse taivaalliset puhdistetaan paremmilla uhreilla kuin nämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Sillä Kristus ei mennyt käsillä tehtyyn kaikkeinpyhimpään, joka on vain oikean kuva, vaan itse taivaaseen, nyt ilmestyäkseen Jumalan kasvojen edessä meidän hyväksemme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Eikä hän mennyt uhratakseen itsensä monta kertaa, niin kuin ylipappi joka vuosi menee kaikkeinpyhimpään vierasta verta mukanaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'sillä muuten hänen olisi pitänyt kärsiä monta kertaa maailman perustamisesta asti, mutta nyt hän on yhden ainoan kerran maailmanaikojen lopulla ilmestynyt poistamaan synnin uhrillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Ja samoin kuin ihmisille on määrätty, että heidän on kerran kuoltava, mutta sen jälkeen tulee tuomio,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'samoin Kristuskin, joka kerran uhrattuna otti pois monien synnit, on toisen kerran ilman syntiä ilmestyvä pelastukseksi niille, jotka häntä odottavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Sillä koska laissa on vain varjokuva tulevasta hyvästä, ei itse tosiasioiden tarkkaa kuvaa, se ei voi koskaan samoilla jokavuotisilla uhreilla, joita he kantavat toistuvasti esiin, tehdä niiden tuojia täydellisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Sillä eikö niitä muuten olisi lakattu uhraamasta, koska näillä, jotka jumalanpalvelusta toimittavat, kerran puhdistettuina ei enää olisi ollut mitään tuntoa synneistä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Mutta niissä on jokavuotinen muistutus synneistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Eihän härkien ja pukkien veri voi ottaa pois syntejä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Sen tähden hän maailmaan tullessaan sanoo: \"Uhria ja antia et tahtonut, mutta ruumiin minulle valmistit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Polttouhreihin ja syntiuhreihin sinä et mieltynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Silloin minä sanoin: \'Katso, minä tulen – kirjakääröön on minusta kirjoitettu – tekemään sinun tahtosi, Jumala.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Kun hän ensin sanoo: \"Uhreja, anteja, polttouhreja ja syntiuhreja et tahtonut etkä niihin mielistynyt\", vaikka niitä lain mukaan uhrataankin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'hän sitten sanoo: \"Katso, minä tulen tekemään sinun tahtosi.\" Hän poistaa ensimmäisen pystyttääkseen toisen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'Ja tämän tahdon perusteella me olemme pyhitetyt Jeesuksen Kristuksen ruumiin uhrilla kerta kaikkiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Kaikki papit seisovat joka päivä toimittamassa palvelustaan ja usein uhraamassa samoja uhreja, jotka eivät koskaan voi poistaa syntejä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'mutta tämä on uhrattuaan yhden uhrin syntien edestä ainiaaksi istuutunut Jumalan oikealle puolelle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'ja odottaa nyt vain, kunnes hänen vihollisensa pannaan hänen jalkojensa astinlaudaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Sillä hän on yhdellä uhrilla iäksi tehnyt täydellisiksi ne, jotka pyhitetään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Todistaahan sen meille myös Pyhä Henki, sillä sen jälkeen on edeltä sanottu:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, '\"Tämä on se liitto, jonka minä niiden päivien jälkeen teen heidän kanssaan\", sanoo Herra: \"Minä panen lakini heidän sydämiinsä ja kirjoitan ne heidän mieleensä\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'ja: \"heidän syntejään ja laittomuuksiaan en enää muista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Mutta missä on niiden anteeksiantamus, siihen ei enää sovi uhri synnin edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Koska meillä siis, veljet, on luja luottamus siihen, että meillä Jeesuksen veren kautta on pääsy kaikkeinpyhimpään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'jonka pääsyn hän on vihkinyt meille uudeksi ja eläväksi tieksi, joka käy esiripun, se on hänen lihansa, kautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'ja koska meillä on \"suuri pappi Jumalan huoneen haltijana\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'käykäämme esiin vakain sydämin, täydessä uskon varmuudessa, sydän vihmottuna puhtaaksi pahasta omastatunnosta ja ruumis puhtaalla vedellä pestynä;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'pitäkäämme järkähtämättä kiinni toivon tunnustuksesta, sillä hän, joka antoi lupauksen, on uskollinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'Valvokaamme toinen toistamme rohkaisuksi rakkauteen ja hyviin tekoihin;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'älkäämme jättäkö omaa seurakunnan kokoontumistamme, niin kuin muutamien on tapana, vaan kehottakaamme toisiamme, sitä enemmän, mitä enemmän näette tuon päivän lähestyvän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Sillä jos me tahallamme teemme syntiä tultuamme tuntemaan totuuden, ei ole enää jäljellä uhria syntiemme edestä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'vaan pelottava tuomion odotus ja tulen kiivaus, joka on kuluttava vastustajat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Joka hylkää Mooseksen lain, se kuolee armotta kahden tai kolmen todistajan todistuksen nojalla:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'kuinka paljon ankaramman rangaistuksen luulettekaan sen ansaitsevan, joka tallaa jalkoihinsa Jumalan Pojan ja pitää epäpyhänä liiton veren, jossa hänet on pyhitetty, ja pilkkaa armon Henkeä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Sillä me tunnemme hänet, joka on sanonut: \"Minun on kosto, minä olen maksava, sanoo Herra\", ja vielä: \"Herra on tuomitseva kansansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Pelottavaa on langeta elävän Jumalan käsiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Mutta muistakaa entisiä päiviä, jolloin te tultuanne valaistuiksi kestitte monet kärsimysten kilvoitukset,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'kun te toisaalta olitte pilkan, ahdistusten ja julkisen häpeän alaisina, toisaalta taas jaoitte niiden osan, joiden kävi samalla tavalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Sillä kahleitteni kanssa te olette kärsineet ja sietäneet ilolla omaisuutenne ryöstön tietäen, että teillä on taivaassa parempi omaisuus, joka pysyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Älkää siis heittäkö pois luottamustanne, jonka palkka on suuri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Sillä tarvitsette kestävyyttä tehdäksenne Jumalan tahdon ja saadaksenne sen, mikä on luvattu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Sillä \"vähän, aivan vähän aikaa vielä, niin hän, joka tuleva on, tulee eikä viivyttele,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'mutta vanhurskas on elävä uskosta, ja jos hän vetäytyy pois, minun sieluni ei mielly häneen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Mutta me emme ole niitä, jotka vetäytyvät pois kadotuksekseen, vaan niitä, jotka uskovat sielunsa pelastukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Mutta usko on luja luottamus siihen, mitä toivotaan, todiste tosiasioista, jotka eivät näy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Sillä sen kautta annettiin todistus vanhoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Uskon kautta ymmärrämme, että maailma on rakennettu Jumalan sanalla, niin että se, mikä nähdään, ei ole tullut näkyvästä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Uskon kautta Aabel uhrasi Jumalalle paremman uhrin kuin Kain, ja sen kautta hän sai todistuksen, että hän oli vanhurskas, kun Jumala antoi todistuksen hänen uhrilahjoistaan, ja sen kautta hän vielä kuoltuaankin puhuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Uskon kautta Haanok siirrettiin täältä näkemättä kuolemaa, \"eikä häntä löydetty, koska Jumala oli siirtänyt hänet luokseen.\" Sillä ennen poissiirtämistään hän oli saanut todistuksen, että hän oli otollinen Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Mutta ilman uskoa on mahdotonta olla otollinen, sillä sen, joka Jumalan luo tulee, täytyy uskoa, että hän on ja että hän palkitsee ne, jotka häntä etsivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Uskon kautta valmisti Nooa saatuaan ilmoituksen siitä, mikä ei vielä näkynyt, pyhässä pelossa arkin perhekuntansa pelastukseksi. Ja uskonsa kautta hän tuomitsi maailman, ja hänestä tuli vanhurskauden perillinen uskon mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Uskon kautta Aabraham oli kuuliainen, kun hänet kutsuttiin lähtemään siihen paikkaan, jonka hän oli saava perinnöksi, ja hän lähti tietämättä, minne oli saapuva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Uskon kautta hän oli muukalaisena lupauksen maassa kuin vieraassa maassa asuen teltoissa, kuten Iisak ja Jaakob, jotka olivat saman lupauksen perillisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Sillä hän odotti sitä kaupunkia, jolla on perustukset ja jonka suunnittelija ja rakentaja on Jumala.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Uskon kautta Saarakin sai voimaa siemenen perustamiseen, ja synnytti yli-ikäisenä, koska hän luotti lupauksen antajaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Sen tähden syntyikin yhdestä miehestä, vieläpä kuoleutuneesta, niin suuri joukko, kuin on tähtiä taivaalla ja kuin hiekkaa meren rannalla, lukematon määrä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Uskossa nämä kaikki kuolivat eivätkä saavuttaneet luvattua, vaan he olivat nähneet sen kaukaa, siitä iloinneet ja tunnustaneet olevansa vieraita ja muukalaisia maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Sillä ne, jotka näin puhuvat, ilmaisevat etsivänsä isänmaata.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Ja jos he olisivat tarkoittaneet sitä maata, josta olivat lähteneet, olisihan heillä ollut aikaa palata takaisin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'mutta nytpä he pyrkivät parempaan, se on taivaalliseen. Sen tähden Jumala ei häpeä heitä, vaan sallii kutsua itseään heidän Jumalakseen, sillä hän on valmistanut heille kaupungin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Uskon kautta Aabraham uhrasi koetukselle pantuna Iisakin, uhrasi ainosyntyisen poikansa, hän, joka oli ottanut vastaan lupaukset');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'ja jolle oli sanottu: \"Iisakista on kutsuttava sinulle siemen\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'sillä hän päätteli, että Jumala on voimallinen herättämään kuolleistakin, minkä vertauskuvana hän saikin hänet takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Uskon kautta Iisak antoi Jaakobille ja Eesaulle siunauksen, joka koski tulevia asioita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Uskon kautta Jaakob siunasi kuollessaan molemmat Joosefin pojat ja rukoili sauvansa päähän nojaten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Uskon kautta Joosef muistutti kuoleman lähestyessä Israelin lasten lähdöstä ja antoi määräyksen luistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Uskon kautta Mooseksen vanhemmat pitivät häntä heti hänen syntymänsä jälkeen piilossa kolme kuukautta, sillä he näkivät, että lapsi oli ihana, eivätkä he pelänneet kuninkaan käskyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Uskon kautta Mooses kieltäytyi suureksi tultuaan siitä, että häntä kutsuttaisiin faraon tyttären pojaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'Hän valitsi mieluummin vaivan kärsimisen yhdessä Jumalan kansan kanssa kuin saada synnistä lyhytaikaista nautintoa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'katsoen Kristuksen pilkan suuremmaksi rikkaudeksi kuin Egyptin aarteet, sillä hän käänsi katseensa palkintoa kohden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Uskon kautta hän jätti Egyptin pelkäämättä kuninkaan vihaa, sillä koska hän ikään kuin näki hänet, joka on näkymätön, hän kesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Uskon kautta hän pani toimeen pääsiäisen ja verensivelyn, ettei esikoisten surmaaja koskisi heihin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Uskon kautta he kulkivat Punaisen meren yli kuin kuivalla maalla, jota yrittäessään egyptiläiset hukkuivat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Uskon kautta Jerikon muurit kaatuivat, kun niiden ympäri oli kuljettu seitsemän päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Uskon kautta portto Raahab pelastui joutumasta tuhoon yhdessä epäuskoisten kanssa, kun oli rauha mielessään ottanut vakoojat luokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Ja mitä vielä sanoisin? Sillä minulta loppuisi aika, jos kertoisin Gideonista, Baarakista, ja myös Simsonista, Jeftasta, Daavidista ja Samuelista ja profeetoista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'jotka uskon kautta kukistivat valtakuntia, pitivät vanhurskautta voimassa, saivat kokea lupausten toteutumista, tukkivat leijonien kidat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'sammuttivat tulen voiman, pääsivät miekanteriä pakoon, voimistuivat heikkoudesta, tulivat voimakkaiksi sodassa, ajoivat pakoon muukalaisten sotajoukkoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'On ollut naisia, jotka ylösnousemuksen kautta saivat kuolleensa takaisin. Toisia kidutettiin, eivätkä he ottaneet vastaan vapautusta, että saisivat paremman ylösnousemuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'Toiset taas saivat kokea pilkkaa ja ruoskimista, vieläpä kahleita ja vankeutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Heitä kivitettiin, sahattiin rikki, kiusattiin ja surmattiin miekalla. He kiertelivät ympäri lampaannahoissa ja vuohennahoissa, puutteessa, ahdistettuina ja pahoinpideltyinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, '– Maailma ei ollut heidän arvoisensa. – He harhailivat erämaissa, vuorilla, luolissa ja maakuopissa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'Ja vaikka nämä kaikki uskon kautta olivat saaneet todistuksen, he eivät kuitenkaan saavuttaneet luvattua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'Jumala on näet varannut meitä varten jotakin parempaa, ettei heitä ilman meitä tehtäisi täydellisiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Sen tähden, kun meillä on näin suuri pilvi todistajia ympärillämme, pankaamme mekin pois kaikki, mikä meitä painaa, ja synti, joka niin helposti meidät kietoo, ja juoskaamme kestävinä edessämme olevassa kilvoituksessa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'silmät luotuina uskon alkajaan ja täyttäjään, Jeesukseen, joka hänelle tarjolla olevan ilon sijasta kärsi ristin häpeästä välittämättä, ja istuutui Jumalan valtaistuimen oikealle puolelle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Ajatelkaa häntä, joka on syntisiltä kärsinyt sellaista vastustusta itseään kohtaan, ettette väsyisi ja lannistuisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Ette ole vielä verille asti tehneet vastarintaa taistellessanne syntiä vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'ja te olette unohtaneet kehotuksen, joka puhuu teille kuin lapsille: \"Poikani, älä pidä halpana Herran kuritusta, äläkä lannistu, kun hän sinua nuhtelee,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'sillä jota Herra rakastaa, sitä hän kurittaa, ja hän ruoskii jokaista lasta, jonka hän ottaa hoivaansa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Kun te kärsitte kuritusta, Jumala kohtelee teitä kuin lapsia. Sillä mikä on sellainen lapsi, jota isä ei kurita?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Mutta jos te olette ilman kuritusta, josta kaikki ovat osallisia, silloinhan te olette äpäriä ettekä lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Ja vielä: meillä oli maalliset isämme kurittajina, ja heitä kavahdimme. Emmekö paljoa ennemmin olisi alamaisia henkien Isälle, että eläisimme?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Sillä nuo kurittivat meitä vain muutamia päiviä varten oman ymmärryksensä mukaan, mutta tämä kurittaa meitä parhaaksemme, että tulisimme osallisiksi hänen pyhyydestään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Mikään kuritus ei sillä hetkellä tosin näytä olevan iloksi, vaan murheeksi, mutta myöhemmin se antaa vanhurskauden rauhanhedelmän niille, jotka ovat harjoitetut sen kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Sen tähden: Ojentakaa hervonneet kätenne ja rauenneet polvenne');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'ja tehkää polut suoriksi jaloillenne, ettei ontuvan jalka vääntyisi, vaan ennemmin parantuisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Pyrkikää rauhaan kaikkien kanssa ja pyhitykseen, sillä ilman sitä kukaan ei ole näkevä Herraa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Pitäkää huoli siitä, ettei kukaan jää osattomaksi Jumalan armosta, \"ettei mikään katkeruuden juuri kasvaisi ja tekisi häiriötä\", ja monet sen kautta tulisi saastutetuiksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'ja ettei kukaan olisi haureellinen tai epäpyhä niin kuin Eesau, joka yhdestä ateriasta myi esikoisuutensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Sillä te tiedätte, että hänet myöhemmin hylättiin, kun hän tahtoi periä siunauksen. Sillä hän ei löytänyt sijaa peruutukselle, vaikka hän sitä kyynelin pyysi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Sillä ette ole tulleet sen vuoren luo, johon voi koskea ja joka palaa tulessa, ettekä synkeyden, ette pimeyden, ette myrskyn,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'ette torven kaiun ettekä sanojen äänen luo, joka puhui niin, että ne, jotka sen kuulivat, pyysivät, ettei heille enää puhuttaisi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'sillä he eivät voineet kestää käskyä: \"Koskettakoon vuorta vaikka vain eläinkin, se kivitettäköön tai ammuttakoon kuoliaaksi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Niin hirveä oli näky, että Mooses sanoi: \"Olen pelästynyt ja vapisen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Sen sijaan olette tulleet Siionin vuoren luo ja elävän Jumalan kaupungin, taivaallisen Jerusalemin luo, ja kymmenien tuhansien enkelien luo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'taivaissa kirjoitettujen esikoisten juhlajoukon ja seurakunnan luo, ja tuomarin luo, joka on kaikkien Jumala, ja täydellisiksi tulleitten vanhurskasten henkien luo,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'ja uuden liiton välimiehen, Jeesuksen, luo, ja vihmontaveren luo, joka puhuu parempaa kuin Aabelin veri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Katsokaa, ettette torju luotanne häntä, joka puhuu. Sillä jos nuo, jotka torjuivat luotaan hänet, joka puhui maan päällä, eivät päässeet pakoon, paljoa vähemmän me, jos käännymme pois hänestä, joka puhuu taivaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Silloin hänen äänensä järisytti maata, mutta nyt hän on luvannut sanoen: \"Vielä kerran minä järisytän en ainoastaan maata, vaan taivaankin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Mutta tuo \"vielä kerran\" osoittaa, että ne, jotka järkkyvät, koska ovat luotuja, tulevat muuttumaan, että ne, jotka eivät järky, pysyisivät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Sen tähden, koska saamme järkkymättömän valtakunnan, omistakaamme armo ja siten palvelkaamme Jumalaa hänelle mieliksi, pyhällä arkuudella ja kunnioituksella,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'sillä meidän Jumalamme on kuluttava tuli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Pysyköön veljesrakkaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Älkää unohtako vieraanvaraisuutta, sillä sitä osoittamalla eräät ovat tietämättään saaneet pitää enkeleitä vierainaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Muistakaa vankeja, niin kuin olisitte itsekin heidän kanssaan vangittuina. Muistakaa pahoinpideltyjä, sillä onhan teillä itsellännekin ruumis.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Avioliitto pidettäköön kunniassa kaikkien kesken, ja aviovuode saastuttamattomana, sillä huorintekijät ja avionrikkojat Jumala tuomitsee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Älkää olko vaelluksessanne ahneita. Tyytykää siihen, mitä teillä on, sillä hän on itse sanonut: \"En sinua hylkää enkä sinua jätä\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'niin että turvallisin mielin sanomme: \"Herra on minun auttajani. En pelkää. Mitä ihminen voi minulle tehdä?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Muistakaa johtajianne, jotka ovat puhuneet teille Jumalan sanaa. Katsokaa, kuinka heidän vaelluksensa on päättynyt, ja seuratkaa heidän uskoaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jeesus Kristus on sama eilen, tänään ja iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Älkää antako monenlaisten ja vieraiden oppien itseänne eksyttää, sillä on hyvä, että sydän saa vahvistusta armosta eikä ruuista. Ne, jotka niissä vaeltavat, eivät ole niistä mitään hyötyneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Meillä on uhrialttari, josta majassa palvelevilla ei ole valta syödä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Sillä niiden eläinten ruumiit, joiden veren ylipappi syntien sovitukseksi kantaa kaikkeinpyhimpään, poltetaan leirin ulkopuolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Sen tähden myös Jeesus, pyhittääkseen kansan omalla verellään, kärsi portin ulkopuolella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Menkäämme siis hänen luokseen \"leirin ulkopuolelle\", hänen pilkkaansa kantaen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'sillä meillä ei ole täällä pysyvää kaupunkia, vaan etsimme tulevaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Uhratkaamme siis hänen kauttaan Jumalalle aina kiitosuhria, se on: niiden huulten hedelmää, jotka tunnustavat hänen nimeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Mutta älkää unohtako tehdä hyvää ja jakaa omastanne, sillä sellaisiin uhreihin Jumala mieltyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Olkaa kuuliaisia johtajillenne ja tottelevaisia, sillä he valvovat teidän sielujanne niin kuin ne, joiden on tehtävä tili, että he voisivat tehdä sitä ilolla eikä huokaillen, sillä se ei ole teille hyödyllistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Rukoilkaa meidän edestämme, sillä olemme varmoja siitä, että meillä on hyvä omatunto ja tahdomme kaikessa vaeltaa oikein.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Vielä hartaammin kehotan teitä näin tekemään, että minut sitä pikemmin annettaisiin teille takaisin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Mutta rauhan Jumala, joka on kuolleista nostanut hänet, joka iankaikkisen liiton veren kautta on suuri lammasten paimen, meidän Herramme Jeesuksen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'hän tehköön teidät kykeneviksi kaikessa hyvässä teossa tekemään hänen tahtonsa ja vaikuttakoon teissä sen, mikä on hänelle otollista, Jeesuksen Kristuksen kautta. Hänelle kunnia iäisyyksien iäisyyksiin! Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Pyydän teitä, veljet: kestäkää tämä kehotuksen sana. Sillä lyhyesti olen teille kirjoittanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Tietäkää, että veljemme Timoteus on päästetty vapaaksi. Jos hän pian tulee, näen hänen kanssaan teidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Tervehdys kaikille johtajillenne ja kaikille pyhille. Teitä tervehtivät ne, jotka ovat Italiasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Armo olkoon teidän kaikkien kanssa. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jaakob, Jumalan ja Herran Jeesuksen Kristuksen palvelija, lähettää tervehdyksen kahdelletoista hajalla asuvalle sukukunnalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Veljeni, pitäkää pelkkänä ilona, kun joudutte monenlaisiin kiusauksiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'tietäen, että teidän uskonne koetuksenkestävyys saa aikaan kärsivällisyyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Kärsivällisyys tuottakoon täydellisen teon, että olisitte täydelliset ja eheät eikä teiltä puuttuisi mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Mutta jos joltakulta teistä puuttuu viisautta, anokoon sitä Jumalalta, joka antaa kaikille auliisti ja syyttelemättä, ja se hänelle annetaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Mutta anokoon uskossa lainkaan epäilemättä. Sillä joka epäilee, on meren tyrskyn kaltainen, jota tuuli ajaa ja heittelee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Älköön sellainen ihminen odottako Herralta mitään saavansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'kaksiselitteinen mies, horjuva kaikilla teillään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Alhainen veli kerskatkoon ylhäisyydestään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'mutta rikas alhaisuudestaan, sillä hän katoaa kuin ruohon kukka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Aurinko nousee helteineen ja kuivaa ruohon, sen kukka varisee, ja sen muodon kauneus häviää. Samoin rikaskin lakastuu matkoillaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Autuas se mies, joka kiusauksen kestää. Sillä kun hänet on koeteltu, hän saa elämän kruunun, jonka Herra on luvannut niille, jotka häntä rakastavat!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Älköön kukaan kiusauksessa ollessaan sanoko: \"Jumala minua kiusaa\", sillä Jumala ei voi kiusata pahaan eikä hän kiusaa ketään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Vaan jokaista kiusaa hänen oma himonsa, joka vetää ja houkuttelee häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Kun sitten himo on tullut raskaaksi, se synnyttää synnin, mutta kun synti on täytetty, se synnyttää kuoleman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Älkää eksykö, rakkaat veljeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Jokainen hyvä anti ja jokainen täydellinen lahja on ylhäältä, valkeuksien Isältä, jonka luona ei ole muutosta tai vaihtelun varjoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Tahtonsa mukaan hän synnytti meidät totuuden sanalla, että olisimme hänen luotujensa ensi hedelmä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Niinpä, rakkaat veljeni, olkoon jokainen ihminen nopea kuulemaan, hidas puhumaan, hidas vihaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'sillä miehen viha ei tee vanhurskautta Jumalan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Sen tähden pankaa pois kaikki saastaisuus ja kaikki pahan runsaus ja ottakaa hiljaisuudella vastaan sana, joka on teihin istutettu ja joka voi teidän sielunne pelastaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Mutta olkaa sanan tekijöitä, eikä vain sen kuulijoita pettäen itsenne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Sillä jos joku on sanan kuulija eikä sen tekijä, hän on miehen kaltainen, joka katselee kuvastimesta luonnollisia kasvojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Hän katselee itseään, lähtee pois ja unohtaa heti, millainen oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Mutta se, joka katsoo täydelliseen lakiin, vapauden lakiin, ja pysyy siinä, eikä ole muistamaton kuulija, vaan todellinen tekijä, on oleva autuas tekemisessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Jos joku luulee palvelevansa Jumalaa, mutta ei hillitse kieltään, vaan pettää sydämensä, hänen jumalanpalvelemisensa on turhaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Puhdasta ja tahratonta jumalanpalvelusta Jumalan ja Isän edessä on käydä katsomassa orpoja ja leskiä heidän ahdistuksessaan ja varjella itsensä maailman saastutukselta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Veljeni, älköön uskonne kirkkauden Herraamme, Jeesukseen Kristukseen, olko henkilöön katsovaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Sillä jos kokoukseenne tulee mies, kultasormus sormessa ja loistavassa puvussa, ja tulee myös köyhä ryysyissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'ja te katsotte loistavapukuisen puoleen ja sanotte: \"Istu sinä tähän mukavasti\", ja köyhälle sanotte: \"Seiso sinä tuossa\", tai: \"Istu tähän alas jalkajakkarani viereen\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'niin ettekö ole joutuneet ristiriitaan itsenne kanssa, ja eikö teistä ole tullut väärämielisiä tuomareita?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Kuulkaa, rakkaat veljeni. Eikö Jumala ole valinnut tämän maailman köyhiä olemaan rikkaita uskossa ja valtakunnan perillisiä, jonka hän on luvannut niille, jotka häntä rakastavat?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Mutta te olette häväisseet köyhän. Eivätkö juuri rikkaat teitä sorra, ja eivätkö juuri he vedä teitä tuomioistuinten eteen?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Eivätkö juuri he pilkkaa sitä hyvää nimeä, joka on lausuttu teidän ylitsenne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Vaan jos täytätte kuninkaallisen lain Raamatun mukaan: \"Rakasta lähimmäistäsi niin kuin itseäsi\", teette hyvin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Jos taas henkilöön katsotte, teette syntiä, ja laki osoittaa teidät lainrikkojiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Sillä se, joka pitää koko lain, mutta rikkoo yhtä kohtaa vastaan, on syypää kaikissa kohdin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Sillä hän, joka on sanonut: \"Älä tee huorin\", on myös sanonut: \"Älä tapa\". Jos et teekään huorin, mutta tapat, olet lainrikkoja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Puhukaa niin ja tehkää niin kuin ne, jotka vapauden laki on tuomitseva.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Sillä tuomio on armoton sille, joka ei ole laupeutta tehnyt, mutta laupeus kerskaa tuomiota vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Mitä hyötyä, veljeni, siitä on, jos joku sanoo itsellään olevan uskon, mutta hänellä ei ole tekoja? Eihän sellainen usko häntä pelasta?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Jos veli tai sisar on vähissä vaatteissa ja jokapäiväistä ravintoa vailla');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'ja joku teistä sanoo heille: \"Menkää rauhassa, lämmitelkää ja ravitkaa itsenne\", mutta ette anna heille ruumiin tarpeita, mitä se hyödyttää?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Samoin uskokin, jos sillä ei ole tekoja, on itsessään kuollut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Joku ehkä sanoo: \"Sinulla on usko, ja minulla on teot.\" Näytä sinä minulle uskosi ilman tekoja, niin minä teoistani näytän sinulle uskon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Sinä uskot, että Jumala on yksi. Siinä teet oikein. Riivaajatkin sen uskovat ja vapisevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Mutta tahdotko tietää, sinä turha ihminen, että usko ilman tekoja on kuollut?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Eikö Aabrahamia, meidän isäämme, julistettu vanhurskaaksi teoista, kun hän vei poikansa Iisakin uhrialttarille?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Sinä näet, että usko vaikutti hänen tekojensa mukana, ja teoista usko tuli täydelliseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'ja täyttyi Raamattu, joka sanoo: \"Aabraham uskoi Jumalaa, ja se luettiin hänelle vanhurskaudeksi\", ja häntä sanottiin Jumalan ystäväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Näette siis, että ihminen julistetaan vanhurskaaksi teoista eikä ainoastaan uskosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Eikö samoin myös portto Raahabia luettu vanhurskaaksi teoista, kun hän otti lähettiläät luokseen ja päästi heidät toista tietä pois?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Sillä niin kuin ruumis ilman henkeä on kuollut, samoin usko ilman tekoja on kuollut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Veljeni, älkööt monet tulko opettajiksi, sillä tiedätte, että saamme sitä kovemman tuomion.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Sillä monessa kohden kaikki hairahdumme. Jos joku ei hairahdu puheessa, hän on täydellinen mies ja kykenee hallitsemaan myös koko ruumiinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Katso, panemme suitset hevosille suihin, että ne meitä tottelisivat, ja voimme ohjata niiden koko ruumiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Katso, laivojakin, vaikka ovat niin suuria ja kovien tuulten kuljetettavia, ohjataan pienellä peräsimellä, minne vain perämies tahtoo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Samoin kielikin on pieni jäsen ja kerskuu suurista asioista. Katso, miten suuren metsän pieni tuli sytyttää!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Myös kieli on tuli, se on vääryyden maailma. Kieli on meidän jäsenistämme se, joka tahraa koko ruumiin, sytyttää tuleen elämän pyörän itse syttyen helvetistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Sillä kaiken luonnon, sekä petojen että lintujen, sekä matelijoiden että merieläinten luonnon, voi ihmisluonto kesyttää ja onkin kesyttänyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'Mutta kieltä kukaan ihminen ei voi kesyttää. Se on levoton ja paha, täynnä kuolettavaa myrkkyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Sillä kiitämme Jumalaa ja Isää, ja sillä me kiroamme ihmisiä, Jumalan kaltaisiksi luotuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Samasta suusta lähtee kiitos ja kirous. Näin ei saa olla, veljeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Pulppuaako lähde samasta silmästä makeaa ja karvasta vettä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Eihän, veljeni, viikunapuu voi tuottaa oliiveja eikä viiniköynnös viikunoita? Samoin myöskään suolainen lähde ei voi antaa makeaa vettä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Kuka on viisas ja ymmärtäväinen teidän joukossanne? Tuokoon näkyviin tekonsa hyvällä vaelluksellaan viisauden sävyisyydessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Mutta jos teillä on katkera kiivaus ja riitaisuus sydämessänne, älkää kerskuko älkääkä valehdelko totuutta vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Se ei ole sitä viisautta, joka ylhäältä tulee, vaan se on maallista, sielullista, riivaajien viisautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Sillä missä on kiivautta ja riitaa, siellä on epäjärjestystä ja kaikenlaista pahaa menoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Mutta ylhäältä tuleva viisaus on ensiksikin puhdasta, sitten rauhaisaa, lempeää, taipuisaa, täynnä laupeutta ja hyviä hedelmiä, puolueetonta ja teeskentelemätöntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Vanhurskauden hedelmä kylvetään rauhassa rauhan tekijöille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Mistä taistelut ja riidat tulevat keskuuteenne? Eivätkö himoistanne, jotka sotivat jäsenissänne?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Himoitsette, eikä teillä kuitenkaan ole. Tapatte ja kiivailette, ettekä voi saavuttaa. Riitelette ja taistelette, mutta teillä ei ole, sen tähden ettette ano.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Anotte, ettekä saa, sen tähden että anotte kelvottomasti kuluttaaksenne sen himoissanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Te avionrikkojat, miehet ja naiset, ettekö tiedä, että maailman ystävyys on vihollisuutta Jumalaa vastaan? Se, joka siis tahtoo olla maailman ystävä, asettuu Jumalan viholliseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Vai luuletteko, että Raamattu sanoo turhan päiten: Kateuteen asti hän halajaa henkeä, jonka hän on pannut asumaan meihin?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Mutta hän antaa sitä suuremman armon. Sen tähden sanotaan: \"Jumala on ylpeitä vastaan, mutta nöyrille hän antaa armon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Olkaa siis Jumalalle alamaisia, mutta vastustakaa perkelettä, niin hän teistä pakenee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Lähestykää Jumalaa, niin hän lähestyy teitä. Puhdistakaa kätenne, te syntiset, ja tehkää sydämenne puhtaiksi, te kaksiselitteiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Tuntekaa kurjuutenne, murehtikaa ja itkekää. Naurunne muuttukoon murheeksi ja ilonne suruksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Nöyrtykää Herran edessä, niin hän teidät korottaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Älkää panetelko toisianne, veljet. Joka panettelee veljeään tai tuomitsee veljeään, se panettelee lakia ja tuomitsee lain. Mutta jos tuomitset lain, et ole lain noudattaja, vaan sen tuomari.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Yksi on lainantaja, hän, joka voi pelastaa ja hukuttaa. Mutta mikä olet sinä, joka toista tuomitset?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Kuulkaa nyt, te, jotka sanotte: \"Tänään tai huomenna lähdemme siihen ja siihen kaupunkiin ja viivymme siellä vuoden ja teemme kauppaa ja saamme voittoa\" –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'te, jotka ette tunne huomista, sillä mikä on teidän elämänne? Savu te olette, joka hetken näkyy, mutta sitten haihtuu –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'sen sijaan, että teidän tulisi sanoa: \"Jos Herra tahtoo ja me elämme, teemme tämän tai tuon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Mutta nyt te kerskutte ylpeydessänne. Kaikki sellainen kerskuminen on pahaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Sille, joka siis ymmärtää tehdä hyvää, eikä tee, se on synniksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Mutta nyt, te rikkaat: itkekää ja vaikeroikaa teille tulevaa kurjuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Teidän rikkautenne on mädännyt, ja teidän vaatteenne ovat koinsyömiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Kultanne ja hopeanne ovat ruostuneet, ja niiden ruoste on oleva todistuksena teitä vastaan ja syövä teidän lihanne kuin tuli. Te olette koonneet aarteita viimeisinä päivinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Katso, työmiesten palkka, jonka te vainioittenne niittäjiltä olette pidättäneet, huutaa, ja leikkaajien valitukset ovat tulleet Herran Sebaotin korviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Olette maan päällä herkutelleet ja eläneet ylellisesti, olette ruokkineet sydäntänne kuin teurastuspäivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Vanhurskaan te tuomitsitte ja tapoitte. Hän ei vastustanut teitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Olkaa siis kärsivällisiä, veljet, Herran tulemukseen asti. Katso, viljelijä odottaa maan kallista hedelmää ja on kärsivällinen, kunnes maa saa varhaisen sateen ja myöhäissateen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Olkaa tekin kärsivällisiä, vahvistakaa sydämenne, sillä Herran tulo on lähellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Älkää huokailko, veljet, toisianne vastaan, ettei teitä tuomittaisi. Katso, tuomari seisoo ovella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Ottakaa, veljet, pahan kestämisen ja kärsivällisyyden esikuvaksi profeetat, jotka ovat puhuneet Herran nimessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Katso, ylistämme autuaiksi niitä, jotka ovat kestäneet. Jobin kärsivällisyyden te olette kuulleet, ja Herran lopun olette nähneet. Sillä Herra on hyvin laupias ja armollinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Mutta ennen kaikkea, veljeni, älkää vannoko, älkää taivaan kautta älkääkä maan, älkää mitään muutakaan valaa, vaan \"on\" olkoon teillä \"on\", ja \"ei\" olkoon teillä \"ei\", ettette joutuisi tuomion alle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Jos joku teistä kärsii pahaa, rukoilkoon. Jos joku on iloisella mielellä, laulakoon kiitosta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Jos joku teistä sairastaa, kutsukoon luokseen seurakunnan vanhimmat, ja he rukoilkoot hänen edestään voidellen häntä öljyllä Herran nimessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Ja uskon rukous pelastaa sairaan, ja Herra antaa hänen nousta jälleen. Jos hän on syntejä tehnyt, ne annetaan hänelle anteeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Tunnustakaa siis toisillenne syntinne ja rukoilkaa toistenne puolesta, että parantuisitte. Paljon voi vanhurskaan toimellinen rukous.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elia oli ihminen, samojen kärsimysten alainen kuin mekin, ja hän rukoili rukoilemalla, ettei sataisi, eikä maan päällä satanut kolmeen vuoteen ja kuuteen kuukauteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Ja hän rukoili uudestaan, ja taivas antoi sateen, ja maa tuotti hedelmänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Veljeni, jos joku teistä eksyy totuudesta ja hänet joku palauttaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'tietäkää, että se, joka palauttaa syntisen hänen eksymyksensä tieltä, pelastaa hänen sielunsa kuolemasta ja peittää syntien paljouden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Pietari, Jeesuksen Kristuksen apostoli, valituille muukalaisille, jotka asuvat hajallaan Pontossa, Galatiassa, Kappadokiassa, Aasian maakunnassa ja Bityniassa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'ja jotka Isän Jumalan edeltämääräämisen mukaan ovat Hengen pyhityksessä valitut kuuliaisuuteen Jeesusta Kristusta kohtaan ja hänen verellään vihmottaviksi. Lisääntyköön teille armo ja rauha!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Ylistetty olkoon meidän Herramme Jeesuksen Kristuksen Jumala ja Isä. Hän on suuren laupeutensa mukaan uudestisynnyttänyt meidät elävään toivoon Jeesuksen Kristuksen kuolleistanousemisen kautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'turmeltumattomaan, saastumattomaan ja katoamattomaan perintöön. Se on taivaissa säilytettynä teitä varten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'jotka Jumalan voimasta uskon kautta varjellutte pelastukseen, joka on valmiina ilmoitettavaksi viimeisenä aikana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Siitä [te] riemuitsette, vaikka nyt, jos se on tarpeen, kärsittekin vähän aikaa murhetta monenlaisissa kiusauksissa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'että teidän uskonne koetuksenkestävyys havaittaisiin paljoa kallisarvoisemmaksi kuin katoava kulta, joka kuitenkin tulessa koetellaan, ja koituisi kiitokseksi, ylistykseksi ja kunniaksi Jeesuksen Kristuksen ilmestyessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Häntä [te] rakastatte, vaikka ette ole häntä nähneet, häneen [te] uskotte, vaikka ette häntä nyt näe, ja riemuitsette sanomattomalla ja kirkastuneella ilolla,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'sillä [te] saavutatte uskonne päämäärän, sielujen pelastuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Tätä pelastusta ovat etsineet ja tutkineet profeetat, jotka ovat profetoineet teille tulevasta armosta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'ovat tutkineet, mihin tai millaiseen aikaan heissä oleva Kristuksen Henki osoitti todistaessaan edeltäpäin Kristusta kohtaavista kärsimyksistä ja niiden jälkeen tulevasta kunniasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Heille, koska he eivät palvelleet itseään, vaan meitä, ilmoitettiin se, mikä on nyt teille julistettu niiden kautta, jotka taivaasta lähetetyssä Pyhässä Hengessä ovat teille evankeliumia julistaneet. Sitä enkelitkin haluavat kumartua katsomaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Vyöttäkää sen tähden mielenne lanteet ja olkaa raittiit. Pankaa täysi toivonne siihen armoon, joka tuodaan teille Jeesuksen Kristuksen ilmestymisessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Niin kuin kuuliaisten lasten tulee, älkää mukautuko niiden himojen mukaan, joissa elitte ennen tietämättömyydessänne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'vaan sen Pyhän mukaan, joka on teidät kutsunut. Olkaa tekin kaikessa vaelluksessanne pyhiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Sillä kirjoitettu on: \"Olkaa pyhät, sillä minä olen pyhä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Ja jos Isänänne huudatte avuksi häntä, joka tuomitsee henkilöön katsomatta jokaisen hänen tekonsa mukaan, niin vaeltakaa pelossa tämä muukalaisuutenne aika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Tietäkää, ettette ole millään katoavalla, ette hopealla ettekä kullalla, lunastetut turhasta, isiltä peritystä vaelluksestanne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'vaan Kristuksen kalliilla verellä, niin kuin virheettömän ja tahrattoman karitsan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Hänet oli tosin edeltä tiedetty jo ennen maailman perustamista, mutta vasta viimeisinä aikoina hänet on ilmoitettu teitä varten,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'jotka uskotte hänen kauttaan Jumalaan, joka herätti hänet kuolleista ja antoi hänelle kirkkauden, niin että uskonne on myös toivo Jumalaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Puhdistakaa sielunne totuuden kuuliaisuudessa vilpittömään veljesrakkauteen ja rakastakaa toisianne hartaasti puhtaasta sydämestä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'te, jotka olette uudestisyntyneet, ette katoavasta, vaan katoamattomasta siemenestä, Jumalan elävän ja iäti pysyvän sanan kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Sillä: \"kaikki liha on kuin ruoho, ja kaikki ihmiskunnia kuin ruohon kukka. Ruoho kuivuu, ja sen kukka varisee,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'mutta Herran sana pysyy iankaikkisesti.\" Tämä on se sana, joka on teille ilosanomana julistettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Pankaa siis pois kaikki pahuus ja kaikki vilppi, teeskentely ja kateus sekä kaikki panettelu,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'ja halutkaa kuin vastasyntyneet lapset sanan väärentämätöntä maitoa, jotta siitä kasvaisitte,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'jos \"olette maistaneet, että Herra on hyvä\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Tulkaa hänen luokseen, elävän kiven luo, jonka ihmiset tosin ovat hylänneet, mutta joka on Jumalan edessä valittu, kallis,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'ja rakentukaa itsekin elävinä kivinä hengelliseksi rakennukseksi, pyhäksi papistoksi uhraamaan hengellisiä uhreja, jotka Jeesuksen Kristuksen kautta ovat Jumalalle mieluisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Sillä Raamatussa sanotaan: \"Katso, minä lasken Siioniin valitun, kallisarvoisen kulmakiven. Se, joka häneen uskoo, ei joudu häpeään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Teille siis, jotka uskotte, se on kallis, mutta niille, jotka eivät usko, \"se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'ja \"kompastuskiveksi ja loukkauskallioksi.\" He kompastuvat sanaan, koska eivät tottele sitä. Siihen heidät on pantukin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Mutta te olette \"valittu suku, kuninkaallinen papisto, pyhä kansa ja omaisuuskansa julistaaksenne sen suuria tekoja\", joka on pimeydestä kutsunut teidät ihmeelliseen valkeuteensa;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'te, jotka ennen \"ette olleet kansa\", mutta nyt olette \"Jumalan kansa\", jotka ennen \"ette olleet armahdettuja\", mutta nyt \"olette armahdetut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Rakkaani, kuin vieraita ja muukalaisia minä kehotan teitä pidättymään lihallisista himoista, jotka sotivat sielua vastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'ja vaeltamaan oikein pakanoiden keskuudessa, että he siitä, mistä he parjaavat teitä kuin pahantekijöitä, teidän hyvien tekojenne tähden niitä katsellessaan, ylistäisivät Jumalaa tilinteon päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Olkaa siis alamaisia kaikelle inhimilliselle järjestykselle Herran tähden, sekä kuninkaalle, joka on ylin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'että käskynhaltijoille, jotka hän on lähettänyt pahaa tekeville rangaistukseksi, mutta hyvää tekeville kiitokseksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'koskapa näin on Jumalan tahto, että hyvää tekemällä vaiennatte typerien ihmisten tietämättömyyden –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'niin kuin vapaat, ei niin kuin ne, joilla vapaus on pahuuden verhona, vaan niin kuin Jumalan orjat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Kunnioittakaa kaikkia, rakastakaa veljiä, pelätkää Jumalaa, kunnioittakaa kuningasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Palvelijat, olkaa kaikella pelolla isännillenne alamaisia, ei ainoastaan hyville ja lempeille, vaan tylyillekin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Sillä on armoa, että joku omantunnon tähden Jumalan edessä kestää vaivoja syyttömästi kärsien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Sillä mitä kiitettävää siinä on, jos olette kärsivällisiä silloin, kun teitä ruoskitaan syntienne tähden? Mutta jos olette kärsivällisiä, kun hyvien tekojenne tähden kärsitte, se on armoa Jumalan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Sillä siihen [te] olette kutsutut, koska Kristuskin kärsi meidän puolestamme jättäen meille esikuvan, jotta noudattaisitte hänen jälkiään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'joka \"ei syntiä tehnyt ja jonka suusta ei petosta löytynyt\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'joka häntä herjattaessa ei herjannut takaisin, joka kärsiessään ei uhannut, vaan jätti asiansa sen haltuun, joka tuomitsee vanhurskaasti,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'joka \"itse kantoi syntimme\" ruumiissaan ristinpuulle, jotta me synneistä pois kuolleina eläisimme vanhurskaudelle. Hänen \"haavojensa kautta [te] olette parannetut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Sillä [te] olitte \"eksyksissä kuin lampaat\", mutta nyt olette palanneet sielujenne paimenen ja kaitsijan luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Samoin, vaimot, olkaa alamaisia omille miehillenne, että nekin, jotka ehkä eivät ole kuuliaisia sanalle, vaimojen vaelluksen kautta ilman sanojakin voitettaisiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'kun he katselevat, kuinka te vaellatte puhtaina ja pelossa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Älköön kaunistuksenne olko ulkonaista: ei hiusten palmikointia, kultakorujen kantamista tai hienoihin vaatteisiin pukeutumista,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'vaan se olkoon salassa oleva sydämen ihminen, hiljaisen ja rauhaisan hengen katoamattomuudessa. Tämä on Jumalan silmissä kallis.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Sillä näin myös ennen pyhät vaimot, jotka panivat toivonsa Jumalaan, kaunistivat itsensä ja olivat omille miehilleen alamaisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Niinpä Saara oli kuuliainen Aabrahamille kutsuen häntä herraksi. Hänen lapsikseen olette tulleet, kun teette sitä, mikä on hyvää, ettekä anna minkään kauhistavan pelästyttää itseänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Samoin, miehet, eläkää viisaasti kukin vaimonne kanssa, kuin heikomman astian kanssa, ja osoittakaa heille kunnioitusta, koska he ovat kanssanne elämän armon perillisiä, etteivät rukouksenne estyisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Lopuksi: olkaa kaikki yksimielisiä, helläsydämisiä, veljiä rakastavia, armahtavia, ystävällisiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Älkää kostako pahaa pahalla, älkää herjausta herjauksella, vaan sitä vastoin siunatkaa, sillä siihen olette kutsutut, että perisitte siunauksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Sillä: \"joka haluaa rakastaa elämää ja nähdä hyviä päiviä, varjelkoon kielensä pahasta ja huulensa puhumasta vilppiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'kääntyköön pois pahasta ja tehköön hyvää, etsiköön rauhaa ja pyrkiköön siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Sillä Herran silmät ovat vanhurskaihin päin ja hänen korvansa heidän rukouksiinsa, mutta Herran kasvot ovat pahantekijöitä vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Ja kuka voi teitä vahingoittaa, jos olette hyvän seuraajia?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Vaan vaikka kärsisittekin vanhurskauden tähden, olette autuaita. \"Mutta älkää antako heidän pelkonsa pelästyttää itseänne älkääkä hämmentykö\",');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'vaan pyhittäkää Herra Jumala sydämissänne ja olkaa aina valmiit vastaamaan lempeydellä ja pelolla jokaiselle, joka pyytää teiltä selkoa toivosta, joka teissä on,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'pitäen hyvän omantunnon, että ne, jotka parjaavat teidän hyvää vaellustanne Kristuksessa, joutuisivat häpeään siinä, mistä he teitä panettelevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Sillä parempi on hyvää tehden kärsiä, jos se on Jumalan tahto, kuin pahaa tehden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Sillä myös Kristus kärsi kerran syntien tähden, vanhurskas väärien puolesta johdattaakseen meidät Jumalan luo. Hänet tosin kuoletettiin lihassa, mutta tehtiin eläväksi hengessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'jossa hän myös meni pois ja saarnasi vankeudessa oleville hengille,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'jotka muinoin eivät olleet kuuliaisia, kun Jumalan pitkämielisyys odotti Nooan päivinä, silloin kun valmistettiin arkkia, jossa vain jotkut, se on kahdeksan sielua, pelastuivat veden kautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Tämän vertauskuvan mukaan vesi pelastaa meidätkin nyt kasteena – joka ei ole lian poistamista ruumiista, vaan hyvän omantunnon liitto Jumalan kanssa – Jeesuksen Kristuksen ylösnousemuksen kautta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'hänen, joka on mennyt taivaaseen ja on Jumalan oikealla puolella. Hänen alleen on alistettu enkelit, vallat ja voimat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Koska siis Kristus on kärsinyt edestämme lihassa, niin ottakaa tekin aseeksenne sama mieli – sillä joka lihassa kärsii, se lakkaa synnistä –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'ettette enää eläisi tätä lihassa vielä elettävää aikaa ihmisten himojen, vaan Jumalan tahdon mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Riittäähän meille, että menneen elämän ajan olette täyttäneet pakanoiden tahtoa vaeltaessanne siveettömyydessä, himoissa, juoppoudessa, ylensyömisissä, juomingeissa ja kauheassa epäjumalien palvelemisessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Sen tähden he pitävät outona, ettette juokse heidän kanssaan samaan riettauden virtaan, ja herjaavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Mutta he tulevat tekemään tilin hänelle, joka on valmis tuomitsemaan elävät ja kuolleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Sillä sitä varten kuolleillekin on julistettu evankeliumi, että he tosin olisivat tuomitut lihassa ihmisten tavalla, mutta että heillä olisi hengessä elämä, kuten Jumala elää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Mutta kaiken loppu on lähellä. Sen tähden olkaa maltillisia ja raittiita rukoilemaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Ennen kaikkea olkoon teidän rakkautenne toisianne kohtaan harras, sillä \"rakkaus peittää syntien paljouden\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Olkaa vieraanvaraisia toisianne kohtaan nurisematta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Palvelkaa toisianne, kukin sillä armolahjalla, minkä on saanut, Jumalan monenlaisen armon hyvinä huoneenhaltijoina.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Jos joku puhuu, puhukoon kuin Jumalan sanoja. Jos joku palvelee, palvelkoon sen voiman mukaan, minkä Jumala antaa, että Jumala tulisi kaikessa kirkastetuksi Jeesuksen Kristuksen kautta. Hänen on kunnia ja valta iäisyyksien iäisyyksiin. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Rakkaani, älkää pitäkö outona sitä hellettä, jossa olette ja joka on teille koetukseksi, ikään kuin teille tapahtuisi jotain outoa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'vaan iloitkaa, sitä myöten kuin olette osallisia Kristuksen kärsimyksistä, että te myös iloitsisitte riemuiten hänen kirkkautensa ilmestyessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Jos teitä solvataan Kristuksen nimen tähden, olette autuaita, sillä kirkkauden ja Jumalan Henki lepää päällänne. Tosin hän tulee noissa pilkatuksi, mutta teissä kirkastetuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Älköön näet kukaan teistä kärsikö murhaajana, varkaana, pahantekijänä tai sen tähden, että sekaantuu toisen virkaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Mutta jos hän kärsii kristittynä, älköön hävetkö, vaan ylistäköön siinä osassaan Jumalaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Sillä aika on tuomion alkaa Jumalan huoneesta. Mutta jos se alkaa ensiksi meistä, mikä on niiden loppu, jotka eivät ole kuuliaisia Jumalan evankeliumille?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Ja \"jos vanhurskas vaivoin pelastuu, mihin joutuukaan jumalaton ja syntinen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Sen tähden, uskokoot myös ne, jotka Jumalan tahdon mukaan kärsivät, sielunsa uskolliselle Luojalle, tehden sitä, mikä on hyvää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Vanhimpia teidän joukossanne siis kehotan, minä, joka myös olen vanhin ja Kristuksen kärsimysten todistaja ja myös osallinen siihen tulevaan kirkkauteen, joka on ilmestyvä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'kaitkaa teille uskottua Jumalan laumaa, ei pakosta, vaan vapaaehtoisesti, ei häpeällisen voiton tähden, vaan sydämen halusta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'ei herroina halliten niitä, jotka ovat teidän osallenne tulleet, vaan ollen laumalle esikuvina,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'niin Ylipaimenen ilmestyessä saatte kirkkauden kuihtumattoman seppeleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Samoin te, nuoremmat, olkaa vanhimmille alamaisia ja olkaa kaikki toinen toisellenne alamaisia, pukeutukaa keskinäiseen nöyryyteen, sillä \"Jumala on ylpeitä vastaan, mutta nöyrille hän antaa armon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Nöyrtykää siis Jumalan väkevän käden alle, että hän ajallaan teidät korottaisi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'ja: \"heittäkää kaikki murheenne hänen päälleen, sillä hän pitää teistä huolen\".');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Olkaa raittiit, valvokaa. Teidän vastustajanne, perkele, käy ympäri kuin karjuva leijona etsien, kenet nielisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Vastustakaa häntä lujina uskossa, tietäen, että samat kärsimykset täytyy teidän veljiennekin maailmassa kestää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Mutta kaiken armon Jumala, joka on kutsunut meidät iankaikkiseen kirkkauteensa Kristuksessa Jeesuksessa, vähän aikaa kärsittyänne hän on teitä valmistava, teitä tukeva, vahvistava ja lujittava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Hänen olkoon kunnia ja valta iäisyyksien iäisyyksiin! Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Silaksen, uskollisen veljen, kautta jona häntä pidän, olen kirjoittanut lyhyesti teille, kehottaen teitä ja vakuuttaen, että armo, jossa olette, on Jumalan todellinen armo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Tervehdyksen lähettää teille Babylonissa oleva seurakunta, valittu niin kuin tekin, ja poikani Markus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Tervehtikää toisianne rakkauden suudelmalla. Rauha teille kaikille, jotka Kristuksessa Jeesuksessa olette! Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Simon Pietari, Jeesuksen Kristuksen orja ja apostoli, niille, jotka ovat saaneet yhtä kalliin uskon kuin mekin Jumalamme ja Vapahtajamme Jeesuksen Kristuksen vanhurskaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Armo ja rauha lisääntyköön teille Jumalan ja meidän Herramme Jeesuksen tuntemisessa!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Koska hänen jumalallinen voimansa on lahjoittanut meille kaiken, mitä elämään ja jumalanpelkoon tarvitaan, hänen tuntemisensa kautta, joka on kutsunut meidät kirkkaudellaan ja täydellisyydellään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'joiden kautta hän on lahjoittanut meille mitä suurimmat ja kalliit lupaukset, että niiden kautta olisitte jumalallisesta luonnosta osallisia paeten pois maailmassa olevasta turmeluksesta, joka vallitsee himojen tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Niin pyrkikää sen tähden kaikella ahkeruudella osoittamaan uskossanne avuja, avuissa tietoa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'tiedossa itsehillintää, itsehillinnässä kärsivällisyyttä, kärsivällisyydessä jumalanpelkoa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'jumalanpelossa veljellistä rakkautta ja veljellisessä rakkaudessa yhteistä rakkautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Sillä jos teillä on nämä ja ne yhä enenevät, ne eivät salli teidän olla toimettomia eivätkä hedelmättömiä Herramme Jeesuksen Kristuksen tuntemisessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Se, jolla sitä vastoin niitä ei ole, on sokea, likinäköinen, ja on unohtanut puhdistuneensa entisistä synneistään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Pyrkikää sen tähden, veljet, sitä enemmän tekemään kutsumisenne ja valitsemisenne lujaksi. Jos näet sen teette, ette koskaan lankea,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'sillä näin teille runsain määrin tarjotaan pääsy Herramme ja Vapahtajamme Jeesuksen Kristuksen iankaikkiseen valtakuntaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Sen tähden aina muistutan teitä tästä, vaikka sen tiedättekin ja olette vahvistettuja totuudessa, joka teillä on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Ja pidän oikeana, niin kauan kuin olen tässä majassa, näin muistuttamalla saada teidät täysin hereille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Sillä tiedän, että majani paneminen pois tapahtuu nopeasti, niin kuin myös meidän Herramme Jeesus Kristus sanoi minulle selvästi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Mutta ahkeroin, että te minun lähtöni jälkeenkin aina voisitte tämän muistaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Sillä me emme seuranneet viekkaasti sommiteltuja taruja tehdessämme teille tiettäväksi Herramme Jeesuksen Kristuksen voimaa ja tulemista, vaan olimme hänen valtasuuruutensa silminnäkijöitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Sillä hän sai Isältä Jumalalta kunnian ja kirkkauden, kun tältä majesteettiselta kirkkaudelta tuli hänelle tämä ääni: \"Tämä on minun rakas Poikani, johon minä olen mieltynyt.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Ja tämän äänen me kuulimme tulevan taivaasta ollessamme hänen kanssaan pyhällä vuorella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Meillä on [sitä] lujempi profeetallinen sana, ja teette hyvin, jos otatte siitä vaarin, kuin pimeässä paikassa loistavasta lampusta, kunnes päivä valkenee ja aamutähti nousee.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Sydämissänne tietäkää ennen kaikkea, ettei yksikään Raamatun profetia ole kenenkään omin neuvoin selitettävissä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'sillä mitään profetiaa ei ole koskaan tuotu esiin ihmisen tahdosta, vaan Pyhän Hengen johtamina ihmiset ovat puhuneet sen, minkä saivat Jumalalta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Mutta myös vääriä profeettoja oli kansan seassa, niin kuin teidänkin keskuudessanne on oleva valheenopettajia, jotka tuovat salaa sisään turmiollisia harhaoppeja, kieltävätpä Herrankin, joka on heidät ostanut, ja tuottavat itselleen äkillisen perikadon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Moni on seuraava heidän turmiollisia teitään, ja heidän tähtensä totuuden tie tulee häväistyksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Ahneudessaan he valheellisilla sanoilla kiskovat teistä hyötyä, mutta jo ikiajoista heidän tuomionsa valvoo eikä heidän perikatonsa torku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Sillä Jumala ei säästänyt enkeleitä, jotka olivat tehneet syntiä, vaan syöksi heidät pimeyden kahleissa helvettiin ja hylkäsi heidät tuomiota varten säilytettäviksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Hän ei säästänyt muinaista maailmaa, vaikka varjelikin kahdeksantena Nooan, vanhurskauden saarnaajan, ja antoi vedenpaisumuksen tulla jumalattomien maailman päälle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'Hän poltti poroksi Sodoman ja Gomorran kaupungit ja tuomitsi ne hävitettäviksi asettaen ne varoitukseksi niille, jotka vastedes elävät jumalattomasti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'Kuitenkin hän pelasti vanhurskaan Lootin, jota vaivasi riettaiden elämä haureudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Sillä asuessaan heidän keskuudessaan tämä vanhurskas mies kärsi tuskaa vanhurskaassa sielussaan heidän pahojen tekojensa tähden, joita hän näki ja kuuli joka päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Herra tietää pelastaa jumaliset koetuksista, mutta säilyttää tuomiopäivään rangaistuksen alaisina väärät,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'ja varsinkin ne, jotka lihan mukaan vaeltavat saastaisissa himoissa ja halveksivat herruutta. Nuo uhkarohkeat ja itserakkaat eivät pelkää pilkata mahtavia henkiä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'vaikka enkelitkään, jotka ovat väkevyydeltään ja voimaltaan suuremmat, eivät lausu heitä vastaan herjaavaa tuomiota Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Mutta niin kuin järjettömät, luonnostaan pyydystettäviksi ja häviämään syntyneet eläimet, nämäkin herjatessaan sitä, mitä eivät tunne, tuhoutuvat omaan turmelukseensa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'ja saavat vääryyden palkan. He pitävät nautintonaan herkutella päivällä. He ovat tahra- ja häpeäpilkkuja herkutellen petoksillaan pidoissa kanssanne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Heidän silmänsä ovat täynnä haureutta eivätkä saa kyllikseen synnistä. He viettelevät horjuvia sieluja, heillä on ahneuteen harjaantunut sydän. He ovat kirouksen lapsia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Hylätessään suoran tien he ovat eksyneet ja seuranneet Bileamin, Beorin pojan, tietä, hänen, joka rakasti vääryyden palkkaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'mutta sai pahasta teostaan ojennuksen: mykkä juhta puhui ihmisen äänellä ja esti profeetan mielettömyyden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Sellaiset ovat vedettömiä lähteitä ja myrskytuulen ajamia pilviä, joille on varattu pimeyden synkeys iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Sillä he puhuvat mahtailevia turhuuden sanoja ja viettelevät lihan himoissa haureuksilla niitä, jotka tuskin ovat päässeet eksyksissä vaeltavia pakoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'He lupaavat heille vapautta, vaikka itse ovat turmeluksen orjia. Sillä kenen voittama joku on, sen orja hän on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Sillä jos he Herran ja Vapahtajan Jeesuksen Kristuksen tuntemisessa ovat päässeetkin maailman saastutuksia pakoon, mutta niihin taas kietoutuneina tulevat voitetuiksi, niin viimeinen on tullut heille ensimmäistä pahemmaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Parempi olisi ollut heille, etteivät olisi tulleet tuntemaan vanhurskauden tietä, kuin että sen tunnettuaan kääntyvät pois heille annetusta pyhästä käskystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Heille on tapahtunut, mitä tosi sananlasku sanoo: \"Koira palaa oksennukselleen\", ja: \"Pesty sika rypee rapakossa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Tämä on jo toinen kirje, jonka kirjoitan teille, rakkaani, ja näissä molemmissa muistuttamalla herätän teidän puhdasta mieltänne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'että muistaisitte niitä sanoja, joita pyhät profeetat ovat ennen puhuneet, ja Herran ja Vapahtajan käskyä, jonka olette meiltä, apostoleiltanne, saaneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Ennen kaikkea tietäkää, että viimeisinä päivinä tulee pilkkaajia, jotka vaeltavat omien himojensa mukaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'ja sanovat: \"Missä on lupaus hänen tulostaan? Sillä onhan siitä asti, kun isät nukkuivat pois, kaikki pysynyt, niin kuin se on ollut luomakunnan alusta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Sillä tahallaan he eivät halua tietää, että taivaat ja samoin maa, vedestä ja veden kautta rakennettu, olivat vanhastaan olemassa Jumalan sanan voimasta');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'ja että niiden kautta silloinen maailma hukkui vedenpaisumukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Mutta nykyiset taivaat ja maa ovat samalla sanalla säilytettyjä tulelle, säästettyjä jumalattomien ihmisten tuomion ja kadotuksen päivään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Mutta tämä yksi älköön olko teiltä, rakkaani, salassa, että yksi päivä on Herran edessä kuin tuhat vuotta ja tuhat vuotta kuin yksi päivä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Ei Herra viivytä lupauksensa täyttämistä, niin kuin muutamat pitävät sitä viivyttelemisenä, vaan hän on pitkämielinen meitä kohtaan, sillä hän ei tahdo, että kukaan hukkuu, vaan että kaikki tulevat mielenmuutokseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Mutta Herran päivä on tuleva kuin varas, ja silloin taivaat katoavat ryskyen, tähdet kuumuudesta hajoavat, ja maa ja kaikki, mitä siihen on tehty, palavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Kun siis nämä kaikki näin hajoavat, millaisia tuleekaan teidän olla pyhässä vaelluksessa ja jumalanpelossa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'teidän, jotka odotatte ja joudutatte Jumalan päivän tuloa, jonka voimasta taivaat hehkuen hajoavat ja tähdet kuumuudesta sulavat!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Mutta hänen lupauksensa mukaan odotamme uusia taivaita ja uutta maata, joissa vanhurskaus asuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Sen tähden, rakkaani, pyrkikää tätä odottaessanne siihen, että teidät havaittaisiin tahrattomiksi ja nuhteettomiksi rauhassa hänen edessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Lukekaa meidän Herramme pitkämielisyys pelastukseksi, josta myös meidän rakas veljemme Paavali hänelle annetun viisauden mukaan on teille kirjoittanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Niin hän tekee kaikissa kirjeissään, kun hän puhuu niissä näistä asioista, vaikka niissä tosin on jonkin verran vaikeatajuista, jota oppimattomat ja vakaantumattomat vääristelevät niin kuin muitakin Kirjoituksia, omaksi kadotuksekseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Koska te siis, rakkaani, tämän jo edeltäpäin tiedätte, olkaa varuillanne, ettette jumalattomien eksymyksen mukaansa tempaamina lankeaisi pois omalta lujalta pohjaltanne,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'ja kasvakaa meidän Herramme ja Vapahtajamme Jeesuksen Kristuksen armossa ja tuntemisessa. Hänen olkoon kunnia sekä nyt että iankaikkisuuden päivään saakka. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Mikä on ollut alusta, minkä olemme kuulleet, minkä omin silmin nähneet, mitä katselimme ja käsin kosketimme, siitä puhumme: elämän Sanasta –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'ja elämä ilmestyi, ja olemme nähneet sen ja todistamme siitä ja julistamme teille sen iankaikkisen elämän, joka oli Isän luona ja ilmestyi meille –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'minkä olemme nähneet ja kuulleet, sen myös julistamme teille, että teilläkin olisi yhteys meidän kanssamme. Meillä on yhteys Isän ja hänen Poikansa, Jeesuksen Kristuksen, kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Tämän kirjoitamme, jotta ilonne olisi täydellinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Tämä on se sanoma, jonka olemme häneltä kuulleet ja jonka teille julistamme: että Jumala on valkeus ja ettei hänessä ole mitään pimeyttä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Jos sanomme, että meillä on yhteys hänen kanssaan, mutta vaellamme pimeydessä, valehtelemme emmekä tee totuutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Mutta jos vaellamme valkeudessa, niin kuin hän on valkeudessa, meillä on yhteys keskenämme, ja Jeesuksen Kristuksen, hänen Poikansa, veri puhdistaa meidät kaikesta synnistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Jos sanomme, ettei meillä ole syntiä, eksytämme itsemme, eikä totuus ole meissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Jos tunnustamme syntimme, hän on uskollinen ja vanhurskas, niin että hän antaa meille synnit anteeksi ja puhdistaa meidät kaikesta vääryydestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Jos sanomme, ettemme ole tehneet syntiä, teemme hänet valehtelijaksi, eikä hänen sanansa ole meissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Lapsukaiseni, tämän kirjoitan teille, ettette syntiä tekisi. Mutta jos joku syntiä tekeekin, meillä on puolustaja Isän luona, Jeesus Kristus, joka on vanhurskas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'Hän on meidän syntiemme sovitus, eikä ainoastaan meidän, vaan myös koko maailman syntien.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Siitä tiedämme hänet tuntevamme, että pidämme hänen käskynsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Joka sanoo: \"Tunnen hänet\", eikä pidä hänen käskyjään, on valehtelija, ja totuus ei ole hänessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Mutta siinä, joka pitää hänen sanansa, on Jumalan rakkaus tullut totisesti täydelliseksi. Siitä tiedämme hänessä olevamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Joka sanoo hänessä pysyvänsä, on velvollinen vaeltamaan, niin kuin hän vaelsi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Veljet, en kirjoita teille uutta käskyä, vaan vanhan käskyn, joka teillä on ollut alusta. Tämä vanha käsky on se sana, jonka olette kuulleet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Kirjoitan teille taas uuden käskyn, sen, mikä on totta hänessä ja teissä, sillä pimeys katoaa, ja todellinen valkeus jo loistaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Se, joka sanoo valkeudessa olevansa, mutta vihaa veljeään, on yhä vielä pimeydessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Joka rakastaa veljeään, pysyy valkeudessa, eikä hänessä ole pahennusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Mutta joka vihaa veljeään, on pimeydessä ja vaeltaa pimeydessä, eikä tiedä, minne menee, sillä pimeys on sokaissut hänen silmänsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Kirjoitan teille, lapsukaiset, sillä synnit ovat teille anteeksi annetut hänen nimensä tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Kirjoitan teille, isät, sillä olette oppineet tuntemaan hänet, joka on alusta. Kirjoitan teille, nuorukaiset, sillä olette voittaneet pahan. Kirjoitan teille, lapsukaiset, sillä olette oppineet tuntemaan Isän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Olen kirjoittanut teille, isät, sillä olette oppineet tuntemaan hänet, joka on alusta. Olen kirjoittanut teille, nuorukaiset, sillä olette voimakkaat, ja Jumalan sana pysyy teissä, ja olette voittaneet pahan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Älkää rakastako maailmaa älkääkä sitä, mikä on maailmassa. Jos joku rakastaa maailmaa, Isän rakkaus ei ole hänessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Sillä mikään siitä, mitä maailmassa on, lihan himo, silmien himo ja mahtaileva elämä, ei ole Isästä, vaan maailmasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Maailma katoaa ja sen himo, mutta joka tekee Jumalan tahdon, pysyy iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Lapsukaiset, nyt on viimeinen aika. Ja kuten olette kuulleet, että antikristus tulee, niin onkin nyt monta antikristusta ilmaantunut. Siitä tiedämme, että nyt on viimeinen aika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Meistä he ovat lähteneet, mutta he eivät olleet yhtä meidän kanssamme. Sillä jos he olisivat olleet yhtä kanssamme, he olisivat pysyneet kanssamme. Mutta heissä oli tuleva ilmi, että kaikki eivät ole meistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Teillä on voitelu Pyhältä, ja tiedätte kaiken.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'En ole kirjoittanut teille sen tähden, ettette totuutta tiedä, vaan sen tähden, että tiedätte sen ja ettei mikään valhe ole totuudesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Kuka on valehtelija, ellei se, joka kieltää, että Jeesus on Kristus? Hän on antikristus, se, joka kieltää Isän ja Pojan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Kenelläkään, joka kieltää Pojan, ei ole Isääkään. Joka tunnustaa Pojan, sillä on myös Isä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Minkä olette alusta asti kuulleet, pysyköön teissä. Jos teissä pysyy se, minkä olette alusta asti kuulleet, tekin pysytte Pojassa ja Isässä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Ja tämä on se lupaus, minkä hän on meille luvannut: iankaikkinen elämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Tämän olen kirjoittanut teille eksyttäjistänne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Teissä pysyy se voitelu, jonka olette saaneet häneltä, ettekä tarvitse kenenkään opetusta. Sitä vastoin niin kuin hänen voitelunsa opettaa teitä kaikesta ja on totta eikä ole valetta, ja kuten se on opettanut teidät, pysykää siinä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Ja nyt, lapsukaiset, pysykää hänessä, että meillä hänen ilmestyessään olisi turva eikä meitä karkotettaisi häpeällä pois hänen luotaan hänen tulemuksessaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Jos tiedätte, että hän on vanhurskas, niin te ymmärrätte, että jokainen, joka tekee vanhurskauden, on syntynyt hänestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Katsokaa, millaisen rakkauden Isä on meille antanut, että meitä kutsutaan Jumalan lapsiksi. Sen tähden maailma ei tunne meitä, sillä se ei tunne häntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Rakkaani, nyt olemme Jumalan lapsia, eikä vielä ole käynyt ilmi, mitä meistä tulee. Mutta tiedämme, että kun hän ilmestyy, tulemme olemaan hänen kaltaisiaan, sillä tulemme näkemään hänet sellaisena, kuin hän on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Ja jokainen, jolla on häneen tämä toivo, puhdistaa itsensä, niin kuin hän on puhdas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Jokainen, joka tekee synnin, tekee myös laittomuuden, ja synti on laittomuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Tiedätte, että hän ilmestyi ottamaan pois syntimme, eikä hänessä ole syntiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Ei kukaan, joka hänessä pysyy, tee syntiä. Kukaan, joka tekee syntiä, ei ole häntä nähnyt eikä häntä tuntenut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Lapsukaiset, älköön kukaan saako teitä eksyttää. Joka vanhurskauden tekee, on vanhurskas, niin kuin hän on vanhurskas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Joka tekee synnin, on perkeleestä, sillä perkele on tehnyt syntiä alusta asti. Sitä varten Jumalan Poika ilmestyi, että tekisi tyhjäksi perkeleen teot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Yksikään Jumalasta syntynyt ei tee syntiä, sillä Jumalan siemen pysyy hänessä, eikä hän voi tehdä syntiä, sillä hän on Jumalasta syntynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Siitä käy ilmi, ketkä ovat Jumalan lapsia ja ketkä perkeleen lapsia. Ei kukaan, joka ei tee vanhurskautta, ole Jumalasta, ei myöskään se, joka ei rakasta veljeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Sillä tämä on se sanoma, jonka olette kuulleet alusta asti, että meidän tulee rakastaa toisiamme');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'eikä olla Kainin kaltaisia, joka oli pahasta ja tappoi veljensä. Ja minkä tähden hän tappoi hänet? Sen tähden, että hänen tekonsa olivat pahat, mutta hänen veljensä teot vanhurskaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Älkää ihmetelkö, veljeni, jos maailma teitä vihaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Me tiedämme siirtyneemme kuolemasta elämään, sillä rakastamme veljiä. Joka ei rakasta veljeä, pysyy kuolemassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Jokainen, joka vihaa veljeään, on murhaaja, ja tiedätte, ettei kenessäkään murhaajassa ole iankaikkista elämää, joka hänessä pysyisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Siitä olemme oppineet tuntemaan Jumalan rakkauden, että hän antoi henkensä edestämme. Mekin olemme velvollisia antamaan henkemme veljien edestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Jos nyt jollakin on aineellista hyvää ja hän näkee veljensä olevan puutteessa, mutta sulkee häneltä sydämensä, kuinka Jumalan rakkaus pysyy hänessä?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Lapsukaiset, älkäämme rakastako sanalla tai kielellä, vaan teossa ja totuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Siitä tiedämme, että olemme totuudesta, ja rauhoitamme sydämemme hänen edessään sillä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'että jos sydämemme syyttää meitä, niin Jumala on suurempi kuin sydämemme ja tietää kaikki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Rakkaani, jos sydämemme ei meitä syytä, meillä on uskallus Jumalaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'ja mitä ikinä anomme, sen saamme häneltä, koska pidämme hänen käskynsä ja teemme sitä, mikä on hänelle otollista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Ja tämä on hänen käskynsä, että meidän tulee uskoa hänen Poikansa Jeesuksen Kristuksen nimeen ja rakastaa toisiamme, niin kuin hän on meille käskyn antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Joka pitää hänen käskynsä, pysyy Jumalassa ja Jumala hänessä. Siitä tiedämme hänen meissä pysyvän, siitä Hengestä, jonka hän on meille antanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Rakkaani, älkää jokaista henkeä uskoko, vaan koetelkaa henget, ovatko ne Jumalasta, sillä monta väärää profeettaa on lähtenyt maailmaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Tästä tunnette Jumalan Hengen: jokainen henki, joka tunnustaa Jeesuksen Kristukseksi, lihaan tulleeksi, on Jumalasta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'eikä yksikään henki, joka ei tunnusta Jeesusta, ole Jumalasta. Se on antikristuksen henki, jonka olette kuulleet olevan tulossa ja joka on jo nyt maailmassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Lapsukaiset, te olette Jumalasta ja olette voittaneet heidät. Sillä hän, joka on teissä, on suurempi kuin se, joka on maailmassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'He ovat maailmasta. Sen tähden he puhuvat sitä, mikä on maailmasta, ja maailma kuulee heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Me olemme Jumalasta. Se, joka tuntee Jumalan, kuulee meitä. Joka ei ole Jumalasta, ei kuule meitä. Siitä tunnemme totuuden Hengen ja eksytyksen hengen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Rakkaani, rakastakaamme toinen toistamme, sillä rakkaus on Jumalasta. Jokainen, joka rakastaa, on Jumalasta syntynyt ja tuntee Jumalan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Joka ei rakasta, ei tunne Jumalaa, sillä Jumala on rakkaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Siinä ilmestyi meille Jumalan rakkaus, että Jumala lähetti ainosyntyisen Poikansa maailmaan, että eläisimme hänen kauttaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Siinä on rakkaus – ei siinä, että me rakastimme Jumalaa, vaan siinä, että hän rakasti meitä ja lähetti Poikansa syntiemme sovitukseksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Rakkaani, jos Jumala on näin meitä rakastanut, mekin olemme velvollisia rakastamaan toisiamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Jumalaa ei ole kukaan koskaan nähnyt. Jos rakastamme toisiamme, Jumala pysyy meissä, ja hänen rakkautensa on tullut täydelliseksi meissä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Siitä tiedämme pysyvämme hänessä ja hänen pysyvän meissä, että hän on antanut meille Henkensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Ja me olemme nähneet ja todistamme, että Isä on lähettänyt Poikansa maailman Vapahtajaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Siinä, joka tunnustaa, että Jeesus on Jumalan Poika, Jumala pysyy, ja hän Jumalassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Ja me olemme oppineet tuntemaan ja uskomme sen rakkauden, mikä Jumalalla on meihin. Jumala on rakkaus, ja se, joka pysyy rakkaudessa, pysyy Jumalassa, ja Jumala pysyy hänessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Tässä on rakkaus tullut täydelliseksi meissä, jotta meillä olisi turvallinen luottamus tuomiopäivänä. Sillä sellainen kuin hän on, sellaisia mekin olemme tässä maailmassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Pelkoa rakkaudessa ei ole, vaan täydellinen rakkaus karkottaa pelon, sillä pelossa on rangaistusta. Mutta se, joka pelkää, ei ole tullut täydelliseksi rakkaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Me rakastamme häntä, sillä hän on ensin rakastanut meitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Jos joku sanoo: \"Rakastan Jumalaa\", mutta vihaa veljeään, hän on valehtelija. Sillä joka ei rakasta veljeään, jonka hän on nähnyt, ei voi rakastaa Jumalaa, jota hän ei ole nähnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Tämä käsky meillä on häneltä, että joka rakastaa Jumalaa, rakastakoon myös veljeään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Jokainen, joka uskoo, että Jeesus on Kristus, on Jumalasta syntynyt. Jokainen, joka rakastaa häntä, joka on synnyttänyt, rakastaa myös sitä, joka on hänestä syntynyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Siitä tiedämme, että rakastamme Jumalan lapsia, kun rakastamme Jumalaa ja pidämme hänen käskynsä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Sillä rakkaus Jumalaan on se, että pidämme hänen käskynsä, eivätkä hänen käskynsä ole raskaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Sillä kaikki, mikä on syntynyt Jumalasta, voittaa maailman. Ja tämä on se voitto, joka on maailman voittanut, meidän uskomme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Kuka voittaa maailman, ellei se, joka uskoo, että Jeesus on Jumalan Poika?');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Hän on se, joka on tullut veden ja veren kautta, Jeesus Kristus, ei ainoastaan vedessä, vaan vedessä ja veressä. Ja Henki on se, joka todistaa, sillä Henki on totuus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Sillä kolme on, jotka todistavat taivaassa: Isä ja Sana ja Pyhä Henki. Ja nämä kolme ovat yksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'Ja kolme on, jotka todistavat maan päällä: Henki ja vesi ja veri, ja ne kolme ovat yksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Jos otamme vastaan ihmisten todistuksen, niin onhan Jumalan todistus suurempi. Ja tämä on Jumalan todistus, sillä hän on todistanut Pojastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Joka uskoo Jumalan Poikaan, hänellä on todistus itsessään. Joka ei usko Jumalaa, tekee hänet valehtelijaksi, koska hän ei ole uskonut sitä todistusta, jonka Jumala on todistanut Pojastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Ja tämä on se todistus: Jumala on antanut meille iankaikkisen elämän, ja tämä elämä on hänen Pojassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Jolla on Poika, sillä on elämä. Jolla ei ole Jumalan Poikaa, sillä ei ole elämää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Tämän olen kirjoittanut teille, jotka uskotte Jumalan Pojan nimeen, tietääksenne, että teillä on iankaikkinen elämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Tämä on se rohkea luottamus, joka meillä on häneen, että jos jotakin anomme hänen tahtonsa mukaan, hän kuulee meitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Ja jos tiedämme hänen kuulevan meitä, mitä anommekin, tiedämme, että meillä on myös kaikki se, mitä olemme häneltä anoneet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Jos joku näkee veljensä tekevän syntiä, joka ei ole kuolemaksi, rukoilkoon, ja Jumala on antava hänelle elämän, niille nimittäin, jotka eivät tee syntiä kuolemaksi. On syntiä, joka on kuolemaksi. Siitä en sano, että olisi rukoiltava.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Kaikki vääryys on syntiä. Ja on syntiä, joka ei ole kuolemaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Tiedämme, ettei yksikään Jumalasta syntynyt tee syntiä, vaan Jumalasta syntynyt pitää itsestään vaarin, eikä paha koske häneen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Tiedämme, että olemme Jumalasta, ja koko maailma on pahassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Mutta tiedämme, että Jumalan Poika on tullut ja antanut meille ymmärryksen tunteaksemme Todellisen, ja olemme siinä Todellisessa, hänen Pojassaan, Jeesuksessa Kristuksessa. Hän on tosi Jumala ja iankaikkinen elämä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Lapsukaiset, varokaa epäjumalia. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Vanhin valitulle rouvalle ja hänen lapsilleen, joita minä totuudessa rakastan – enkä ainoastaan minä, vaan myös kaikki, jotka ovat tulleet tuntemaan totuuden –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'totuuden tähden, joka meissä pysyy ja on oleva kanssamme iankaikkisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Armo, laupeus ja rauha Isältä Jumalalta ja Jeesukselta Kristukselta, Isän Pojalta, on oleva teidän kanssanne, totuudessa ja rakkaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Minua on suuresti ilahduttanut, että olen lastesi joukossa havainnut olevan niitä, jotka vaeltavat totuudessa sen käskyn mukaan, jonka olemme saaneet Isältä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Nyt, rouva, minulla on sinulle pyyntö, ei ikään kuin kirjoittaisin sinulle uuden käskyn, vaan sen, joka meillä on ollut alusta asti, että meidän tulee rakastaa toisiamme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'Ja tämä on rakkaus, että vaellamme hänen käskyjensä mukaan. Tämä on käsky, kuten olette alusta kuulleet, että siinä vaellatte.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Sillä monta eksyttäjää on lähtenyt maailmaan, jotka eivät tunnusta Jeesusta Kristukseksi, joka oli lihaan tuleva. Sellainen on eksyttäjä ja antikristus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Ottakaa vaari itsestänne, ettette menetä sitä, minkä olemme työllämme aikaansaaneet, vaan että saamme täyden palkan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Kenelläkään, joka rikkoo eikä pysy Kristuksen opissa, ei ole Jumalaa. Sillä, joka pysyy siinä opissa, on sekä Isä että Poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Jos joku tulee luoksenne eikä tuo mukanaan tätä oppia, älkää ottako häntä huoneeseenne älkääkä lausuko häntä tervetulleeksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Se näet, joka lausuu hänet tervetulleeksi, tulee osalliseksi hänen pahoihin tekoihinsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Minulla olisi paljon kirjoitettavaa teille, mutta en tahdo tehdä sitä papyruksella ja musteella, vaan toivon pääseväni luoksenne ja voivani puhua kasvotusten kanssanne, että ilomme olisi täydellinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Valitun sisaresi lapset lähettävät sinulle terveisiä. Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Vanhin rakkaalle Gaiukselle, jota minä totuudessa rakastan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Rakkaani, rukoilen, että kaikessa menestyt ja pysyt terveenä, niin kuin sielusikin menestyy.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Minua ilahdutti suuresti, kun veljet tulivat ja antoivat todistuksen sinun totuudestasi, niin kuin sinä vaellat totuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Minulla ei ole suurempaa iloa kuin se, että kuulen lasteni vaeltavan totuudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Rakkaani, sinä toimit uskollisesti kaikessa, mitä teet sekä veljien että vieraiden hyväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'He ovat seurakunnan edessä antaneet todistuksen rakkaudestasi. Teet hyvin, kun varustat heitä matkaan, kuten Jumalan edessä sopii.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Sillä hänen nimensä tähden he ovat lähteneet matkaan eivätkä ota pakanoilta mitään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Me olemme siis velvollisia ottamaan sellaisia vastaan, jotta tekisimme työtä yhdessä totuuden hyväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Kirjoitin seurakunnalle, mutta Diotrefes, joka haluaa olla ensimmäinen heidän joukossaan, ei ota meitä vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Sen tähden, jos tulen, muistutan hänen teoistaan, mitä hän tekee, kun juoruaa meistä pahoilla sanoilla. Hän ei tyydy siihenkään: hän ei itse ota veljiä vastaan, vaan estää niitäkin, jotka haluavat sen tehdä, ja työntää heidät pois seurakunnasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Rakkaani, älä seuraa pahaa, vaan hyvää. Se, joka tekee hyvin, on Jumalasta. Se, joka tekee pahoin, ei ole Jumalaa nähnyt.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Demetrius on kaikilta, itse totuudeltakin, saanut hyvän todistuksen, ja mekin todistamme, ja tiedätte, että meidän todistuksemme on tosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Paljon minulla olisi kirjoittamista sinulle, mutta en tahdo kirjoittaa sinulle musteella ja kynällä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'sillä toivon pian näkeväni sinut ja voivamme puhella suullisesti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, 'Rauha sinulle! Ystävät tervehtivät sinua. Tervehdi ystäviä nimeltä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Juuda, Jeesuksen Kristuksen palvelija ja Jaakobin veli, kutsutuille, jotka ovat Isässä Jumalassa pyhitettyjä ja Jeesukselle Kristukselle varjeltuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Lisääntyköön teille laupeus, rauha ja rakkaus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Rakkaani! Kun minulla on ollut kaikkea halua kirjoittaa teille yhteisestä pelastuksestamme, minulle tuli pakko kirjoittaa ja kehottaa teitä kilvoittelemaan sen uskon puolesta, joka on annettu kerta kaikkiaan pyhille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Sillä teidän keskuuteenne on pujahtanut eräitä ihmisiä, joiden jo aikoja sitten on kirjoitettu tulevan tähän tuomioon, jumalattomia, jotka kääntävät Jumalamme armon riettaudeksi ja kieltävät ainoan Valtiaamme ja Herramme, Jeesuksen Kristuksen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Vaikka jo kerran olette saaneet tietää tämän, tahdon kuitenkin muistuttaa teitä siitä, että Herra, joka oli pelastanut kansan Egyptistä, toisella kertaa hukutti ne, jotka eivät uskoneet;');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Hän myös pani ne enkelit, jotka eivät säilyttäneet alkutilaansa, vaan jättivät oman asumuksensa, pimeyteen iankaikkisissa kahleissa säilytettäviksi suuren päivän tuomioon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Samoin ovat Sodoma ja Gomorra ja niiden ympärillä olevat kaupungit, jotka harjoittivat haureutta samalla tavalla kuin nekin ja eksyivät vieraan lihan perään, varoittavana esimerkkinä kärsiessään iankaikkisen tulen rangaistusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Yhtäkaikki nämä uneksijat samoin saastuttavat lihan. He halveksivat herruutta ja herjaavat voimakkaita henkiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Mutta ylienkeli Miikaelkaan, kun riiteli ja väitteli perkeleen kanssa Mooseksen ruumiista, ei rohjennut lausua herjaavaa tuomiota, vaan sanoi: \"Rangaiskoon sinua Herra!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Nämä herjaavat sitä vastoin kaikkea sitä, mitä eivät tunne, mutta minkä he järjettömien eläinten tavoin luonnostaan ymmärtävät ja turmelevat sillä itsensä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Voi heitä, sillä he ovat lähteneet Kainin tielle ja heittäytyneet palkan tähden Bileamin eksytykseen ja hukkuvat kapinoidessaan kuin Koora!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'He ovat likapilkkuja rakkauden aterioillanne ja kestitsevät itseään arkailematta. He ovat vedettömiä, tuulten ajamia pilviä, paljaita, syksyisiä puita, hedelmättömiä, kahdesti kuolleita, juurineen reväistyjä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'rajuja meren aaltoja, jotka vaahtoavat omia häpeitään, harhailevia tähtiä, joille pimeyden synkeys on ikuisesti varattu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Heistäkin Heenok, Aadamista seitsemäs, on ennustanut sanoen: \"Katso, Herra tulee kymmenien tuhansien pyhiensä kanssa');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'tuomitsemaan kaikkia ja rankaisemaan kaikkia jumalattomia kaikista heidän jumalattomista teoistaan, joita he ovat tehneet jumalattomuudessaan, ja kaikista kovista sanoista, mitä nuo jumalattomat syntiset ovat puhuneet häntä vastaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'He ovat napisijoita, kohtaloonsa tyytymättömiä ja vaeltavat himojensa mukaan. Heidän suunsa puhuu kopeita sanoja, ja he mielistelevät ihmisiä oman etunsa tähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Mutta te, rakkaani, muistakaa näitä sanoja, jotka meidän Herramme Jeesuksen Kristuksen apostolit ovat edeltä puhuneet,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'sanoen teille: \"Viimeisenä aikana on oleva pilkkaajia, jotka vaeltavat jumalattomien himojensa mukaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Nämä itse aiheuttavat hajaannusta. He ovat sielullisia, Henkeä heillä ei ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Mutta te, rakkaani, rakentukaa pyhimmän uskonne varaan, rukoilkaa Pyhässä Hengessä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'ja pysykää Jumalan rakkaudessa odottaessanne meidän Herramme Jeesuksen Kristuksen laupeutta iankaikkiseksi elämäksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Ja armahtakaa toisia, niitä, jotka epäilevät. Pelastakaa heidät, tulesta temmaten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'Toisia taas armahtakaa pelolla inhoten lihan tahraamaa vaatettakin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Mutta hänelle, joka voi varjella teidät lankeamasta ja asettaa teidät nuhteettomina, riemuitsevina, kirkkautensa eteen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'hänelle, ainoalle viisaalle Jumalalle ja Vapahtajallemme, hänelle kunnia, valtasuuruus, voima ja valta sekä nyt että kaikkiin iankaikkisuuksiin! Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Jeesuksen Kristuksen ilmoitus, jonka Jumala antoi hänelle näyttääkseen palvelijoilleen, mitä pitää pian tapahtua, ja minkä hän lähettämänsä enkelin kautta ilmoitti näkyinä palvelijalleen Johannekselle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Hän on todistanut tässä Jumalan sanan ja Jeesuksen Kristuksen todistuksen, kaiken sen, minkä hän näki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Autuas se, joka lukee, ja autuaat ne, jotka kuulevat tämän profetian sanat ja pitävät sen, mitä siihen on kirjoitettu, sillä aika on lähellä!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Johannes seitsemälle Aasian maakunnan seurakunnalle: Armo teille ja rauha häneltä, joka on ja joka oli ja joka tuleva on, ja niiltä seitsemältä hengeltä, jotka ovat hänen valtaistuimensa edessä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'ja Jeesukselta Kristukselta, uskolliselta todistajalta, häneltä, joka on kuolleitten esikoinen ja maan kuningasten hallitsija! Hänelle, joka meitä rakastaa ja on pessyt meidät synneistämme verellään');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'ja tehnyt meidät kuninkaiksi, papeiksi Jumalalleen ja Isälleen, hänelle [olkoon] kunnia ja voima aina ja iäisyyksien iäisyyksiin! Aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Katso, hän tulee pilvissä, ja jokainen silmä tulee näkemään hänet, nekin, jotka hänet lävistivät, ja kaikki maan sukukunnat vaikeroivat hänen tullessaan. Totisesti, aamen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, '\"Minä olen A ja O\", alku ja loppu, sanoo Herra Jumala, joka on ja joka oli ja joka tuleva on, Kaikkivaltias.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Minä, Johannes, teidän veljenne, joka olen kanssanne osallinen ahdistukseen, valtakuntaan ja Jeesuksen Kristuksen kärsivällisyyteen, olin Jumalan sanan ja Jeesuksen todistuksen tähden saaressa, jonka nimi on Patmos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Olin Hengessä Herran päivänä, ja kuulin takaani suuren äänen, kuin torven äänen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'joka sanoi: \"Minä olen A ja O, ensimmäinen ja viimeinen. Kirjoita kirjakääröön, mitä näet, ja lähetä niille seitsemälle seurakunnalle Aasian maakunnassa, Efesoon, Smyrnaan, Pergamoon, Tyatiraan, Sardeeseen, Filadelfiaan ja Laodikeaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Käännyin katsomaan kohti ääntä, joka puhui kanssani, ja kääntyessäni näin seitsemän kultaista lampunjalkaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'ja seitsemän lampunjalan keskellä Ihmisen Pojan muotoisen, pitkäliepeiseen viittaan puetun ja rinnan kohdalta kultaisella vyöllä vyötetyn.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Hänen päänsä ja hiuksensa olivat valkoiset kuin valkoinen villa, kuin lumi, ja hänen silmänsä kuin tulen liekki.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'Hänen jalkansa olivat ahjossa tulella puhdistetun, sulan vasken kaltaiset, ja hänen äänensä oli kuin paljojen vetten ääni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'Hänellä oli oikeassa kädessään seitsemän tähteä, ja hänen suustaan lähti kaksiteräinen, terävä miekka, ja hänen kasvonsa olivat kuin aurinko, kun se paistaa voimassaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Kun näin hänet, kaaduin kuin kuolleena hänen jalkojensa juureen. Mutta hän pani oikean kätensä päälleni sanoen: \"Älä pelkää! Minä olen ensimmäinen ja viimeinen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'ja elän, ja olin kuollut, ja katso, elän iäisyyksien iäisyyksiin, ja minulla on helvetin ja kuoleman avaimet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Kirjoita, mitä olet nähnyt, mitä nyt on ja mitä tämän jälkeen tapahtuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Seitsemän tähden salaisuus, jotka näit oikeassa kädessäni, ja seitsemän kultaisen lampunjalan salaisuus on tämä: ne seitsemän tähteä ovat seitsemän seurakunnan enkelit, ja ne seitsemän lampunjalkaa ovat seitsemän seurakuntaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, '\"Efeson seurakunnan enkelille kirjoita: \'Näin sanoo se, joka pitää seitsemää tähteä oikeassa kädessään, se, joka kulkee seitsemän kultaisen lampunjalan keskellä:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Tiedän tekosi, vaivannäkösi ja kärsivällisyytesi, ja ettet voi sietää pahoja. Sinä olet koetellut niitä, jotka väittävät olevansa apostoleja eivätkä ole, ja olet havainnut heidät valehtelijoiksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Olet kestänyt ja sinulla on kärsivällisyyttä, ja olet tehnyt työtä nimeni tähden, etkä ole uupunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Mutta se minulla on sinua vastaan, että olet hylännyt ensimmäisen rakkautesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Muista siis, mistä olet langennut, ja tee parannus, ja tee ensimmäisiä tekoja. Mutta jos et, tulen pian luoksesi ja työnnän lampunjalkasi paikaltaan, ellet tee parannusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Mutta se sinulla on, että vihaat nikolaiittojen tekoja, joita minäkin vihaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Jolla on korva, kuulkoon, mitä Henki seurakunnille sanoo. Sen, joka voittaa, annan syödä elämän puusta, joka on Jumalan paratiisissa.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Smyrnan seurakunnan enkelille kirjoita: \'Näin sanoo ensimmäinen ja viimeinen, joka kuoli ja virkosi eloon:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Minä tiedän tekosi, ahdistuksesi ja köyhyytesi – sinä olet kuitenkin rikas – ja tiedän kärsimäsi pilkan niiltä, jotka sanovat olevansa juutalaisia, eivätkä ole, vaan ovat saatanan synagoga.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Älä pelkää sitä, mitä tulet kärsimään. Katso, perkele heittää muutamia teistä vankilaan, että teidät pantaisiin koetukselle, ja teillä tulee olemaan ahdistusta kymmenen päivää. Ole uskollinen kuolemaan asti, niin annan sinulle elämän kruunun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Jolla on korva, kuulkoon, mitä Henki sanoo seurakunnille. Sitä, joka voittaa, toinen kuolema ei vahingoita.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Pergamon seurakunnan enkelille kirjoita: \'Näin sanoo se, jolla on kaksiteräinen, terävä miekka:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Tiedän tekosi ja sen, missä asut, nimittäin siellä, missä on saatanan valtaistuin, ja pidät nimestäni kiinni etkä ole kieltänyt uskoa minuun niinäkään päivinä, jolloin Antipas, uskollinen todistajani, tapettiin luonanne, siellä, missä saatana asuu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Mutta minulla on jotakin sinua vastaan: sinulla on siellä niitä, jotka pitävät kiinni Bileamin opista, sen, joka opetti Baalakille Israelin lasten edessä viettelystä syödä epäjumalille uhrattua ja harjoittaa haureutta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Niin myös sinulla on niitä, jotka pitävät kiinni nikolaiittojen opista, jota vihaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Muuta siis mielesi. Mutta jos et, niin tulen luoksesi pian ja sodin heitä vastaan suuni miekalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Jolla on korva, kuulkoon, mitä Henki seurakunnille sanoo. Sille, joka voittaa, annan salattua mannaa ja annan hänelle valkoisen kiven ja kiveen kirjoitetun uuden nimen, jota ei tiedä kukaan muu kuin sen saaja.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Tyatiran seurakunnan enkelille kirjoita: \'Näin sanoo Jumalan Poika, jonka silmät ovat kuin tulen liekki ja jonka jalat ovat kuin kiiltävä vaski:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Tiedän tekosi, rakkautesi, palveluksesi, uskosi, kärsivällisyytesi ja että viimeiset tekosi ovat useammat kuin ensimmäiset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Mutta minulla on sinua vastaan jotakin, se, että sallit tuon naisen, Iisebelin, joka sanoo itseään profeetaksi, opettaa ja eksyttää palvelijoitani harjoittamaan haureutta ja syömään epäjumalille uhrattua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Olen antanut hänelle aikaa mielenmuutokseen, mutta hän ei ole tehnyt parannusta haureudestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Katso, minä syöksen hänet tautivuoteeseen, ja suureen ahdistukseen ne, jotka hänen kanssaan tekevät huorin, jos eivät muuta mieltään eivätkä luovu hänen teoistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'Hänen lapsensa surmaan kuolemalla, ja kaikki seurakunnat saavat tuntea, että minä olen se, joka tutkin munuaiset ja sydämet, ja annan teille kullekin tekojenne mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Mutta teille muille Tyatirassa oleville, kaikille, joilla ei ole tätä oppia, teille, jotka ette ole tulleet tuntemaan, niin kuin he sanovat, saatanan syvyyksiä, sanon: en pane päällenne muuta kuormaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Pitäkää vain se, mitä teillä on, siihen asti kunnes tulen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Sille, joka voittaa ja ottaa loppuun asti vaarin teoistani, annan vallan hallita pakanoita,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'ja hän on kaitseva heitä rautaisella valtikalla, kuin saviastiat heidät särjetään – kuten minäkin sain siihen Isältäni vallan –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'ja annan hänelle aamutähden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Jolla on korva, kuulkoon, mitä Henki seurakunnille sanoo.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, '\"Sardeen seurakunnan enkelille kirjoita: \'Näin sanoo se, jolla on Jumalan seitsemän henkeä ja seitsemän tähteä: Tiedän tekosi: sinulla on se nimi, että elät, mutta olet kuollut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Herää valvomaan ja vahvista jäljellejääneitä, niitä, jotka ovat olleet kuolemaisillaan, sillä en ole havainnut tekojasi täydellisiksi Jumalani edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Muista siis, kuinka olet saanut ja kuullut, ja säilytä se ja muuta mielesi. Jos et valvo, tulen päällesi kuin varas, etkä tiedä, millä hetkellä tulen päällesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Sinulla on Sardeessakin muutamia harvoja nimiä, jotka eivät ole tahrineet vaatteitaan, ja he tulevat vaeltamaan kanssani valkoisissa vaatteissa, sillä he ovat siihen arvollisia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Joka voittaa, puetaan valkoisiin vaatteisiin, enkä pyyhi pois hänen nimeään elämän kirjasta, ja olen tunnustava hänen nimensä Isäni edessä ja hänen enkeliensä edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Jolla on korva, kuulkoon, mitä Henki seurakunnille sanoo.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Filadelfian seurakunnan enkelille kirjoita: \'Näin sanoo Pyhä ja Tosi, jolla on Daavidin avain, se, joka avaa, eikä kukaan sulje, ja joka sulkee, eikä kukaan avaa:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Tiedän tekosi. Katso, olen pannut eteesi avoimen oven, eikä kukaan voi sitä sulkea, sillä voimasi on vähäinen, ja olet pitänyt sanani etkä ole kieltänyt nimeäni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Katso, annan sinulle saatanan synagogasta niitä, jotka sanovat olevansa juutalaisia, eivätkä ole, vaan valehtelevat. Katso, olen pannut heidät tulemaan ja kumartumaan jalkojesi eteen ja tietämään, että minä olen sinua rakastanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Koska olet pitänyt kärsivällisyyteni sanan, minäkin otan vaarin sinusta ja varjelen sinut koetuksen hetkestä, joka on tuleva yli koko maanpiirin koettelemaan niitä, jotka asuvat maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Katso, tulen pian. Pidä kiinni siitä, mitä sinulla on, ettei kukaan ottaisi kruunuasi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Sen, joka voittaa, teen pylvääksi Jumalani temppeliin, eikä hän koskaan enää lähde sieltä ulos, ja kirjoitan häneen Jumalani nimen ja Jumalani kaupungin nimen, sen uuden Jerusalemin, joka laskeutuu alas taivaasta Jumalani luota, ja uuden nimeni.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Jolla on korva, kuulkoon, mitä Henki seurakunnille sanoo.\'');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Laodikean seurakunnan enkelille kirjoita: \'Näin sanoo Aamen, uskollinen ja tosi todistaja, Jumalan luomakunnan alku:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Tiedän tekosi: et ole kylmä etkä kuuma. Oi, jospa olisit kylmä tai kuuma!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Näin ollen, koska olet haalea, etkä kylmä etkä kuuma, oksennan sinut suustani ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Sillä sanot: Olen rikas, olen rikastunut enkä tarvitse mitään, etkä tiedä, että sinä olet kurja, säälittävä, köyhä, sokea ja alaston.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Neuvon sinua ostamaan minulta kultaa, tulessa puhdistettua, että rikastuisit, ja valkoiset vaatteet, jotta pukeutuisit niihin eikä alastomuutesi häpeä näkyisi, ja silmävoidetta voidellaksesi silmäsi, jotta näkisit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Kaikkia niitä, joita rakastan, nuhtelen ja kuritan. Ahkeroi siis ja muuta mielesi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Katso, seison ovella ja kolkutan. Jos joku kuulee ääneni ja avaa oven, käyn sisälle hänen luokseen ja aterioin hänen kanssaan, ja hän minun kanssani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Sen, joka voittaa, annan istua kanssani valtaistuimellani, niin kuin minäkin olen voittanut ja istunut Isäni kanssa hänen valtaistuimellaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Jolla on korva, kuulkoon, mitä Henki sanoo seurakunnille.\'\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Sen jälkeen näin, ja katso: taivaassa oli ovi avattuna, ja ensimmäinen ääni, jonka olin kuullut puhuvan minulle kuin torven, sanoi: \"Nouse ylös tänne, niin näytän sinulle, mitä tämän jälkeen pitää tapahtua.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Heti olin Hengessä. Katso, taivaassa oli valtaistuin, ja valtaistuimella oli istuja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Istuja oli näöltään jaspis- ja sardionkiven kaltainen, ja valtaistuimen ympärillä oli sateenkaari, näöltään smaragdin kaltainen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Valtaistuimen ympärillä oli kaksikymmentä neljä valtaistuinta, ja valtaistuimilla istui kaksikymmentä neljä vanhinta, puettuina valkoisiin vaatteisiin, ja heillä oli päässään kultakruunut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Valtaistuimesta lähti salamoita, ukkosen jyrinää ja ääniä, ja valtaistuimen edessä paloi seitsemän tulisoihtua, jotka ovat Jumalan seitsemän henkeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Valtaistuimen edessä oli lasimeri, kristallin näköinen. Valtaistuimen keskellä ja valtaistuimen ympärillä oli neljä olentoa, täynnä silmiä edestä ja takaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Ensimmäinen olento oli leijonan näköinen, toinen olento nuoren härän näköinen, kolmannella olennolla oli kuin ihmisen kasvot, ja neljäs olento oli lentävän kotkan näköinen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Niillä neljällä olennolla oli kullakin kuusi siipeä, ja ne olivat ympäriinsä ja sisältä silmiä täynnä. Ne sanoivat lakkaamatta yötä päivää: \"Pyhä, pyhä, pyhä on Herra Jumala, Kaikkivaltias, joka oli ja joka on ja joka tuleva on.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Kun olennot antavat ylistyksen, kunnian ja kiitoksen hänelle, joka valtaistuimella istuu, joka elää iäisyyksien iäisyyksiin,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'kaksikymmentä neljä vanhinta lankeaa hänen eteensä, joka valtaistuimella istuu, ja kumartaen rukoilee häntä, joka elää iäisyyksien iäisyyksiin, ja heittää kruununsa valtaistuimen eteen sanoen:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, '\"Sinä, Herra, olet arvollinen saamaan ylistyksen ja kunnian ja voiman, sillä sinä olet luonut kaiken, ja sinun tahdostasi ne ovat olemassa ja ovat luodut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Sitten näin valtaistuimella istuvan oikeassa kädessä kirjakäärön, sisältä ja päältä täyteen kirjoitetun, seitsemällä sinetillä suljetun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Näin väkivahvan enkelin suurella äänellä kuuluttavan: \"Kuka on arvollinen avaamaan tämän kirjan ja päästämään sen sinetit?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Eikä kukaan taivaassa, ei maan päällä eikä maan alla voinut avata kirjaa eikä katsoa siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Minä itkin kovasti, ettei ketään havaittu arvolliseksi avaamaan kirjaa eikä katsomaan siihen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Mutta yksi vanhimmista sanoi minulle: \"Älä itke! Katso, leijona Juudan sukukunnasta, Daavidin juurivesa, on voittanut avatakseen kirjan ja irrottaakseen sen seitsemän sinettiä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Ja näin, että valtaistuimen ja niiden neljän olennon ja vanhinten keskellä seisoi Karitsa, ikään kuin teurastettu. Hänellä oli seitsemän sarvea ja seitsemän silmää, jotka ovat seitsemän Jumalan henkeä, lähetetyt kaikkeen maailmaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Hän tuli ja otti kirjan valtaistuimella istuvan oikeasta kädestä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Kun hän oli ottanut kirjan, neljä olentoa ja kaksikymmentä neljä vanhinta lankesivat Karitsan eteen. Heillä oli kullakin sitra, ja heillä oli kultamaljat täynnä suitsutuksia, jotka ovat pyhien rukoukset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'He veisasivat uutta virttä, sanoen: \"Sinä olet arvollinen ottamaan kirjan ja avaamaan sen sinetit, sillä sinut on teurastettu ja olet verelläsi ostanut Jumalalle ihmiset kaikista sukukunnista, kielistä, [Israelin] kansasta ja pakanoista');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'ja tehnyt meidät Jumalallemme kuninkaiksi ja papeiksi, ja tulemme hallitsemaan maan päällä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, '[Minä] näin ja kuulin monien enkelien äänen valtaistuimen, olentojen ja vanhinten ympäriltä, ja heidän lukunsa oli kymmenentuhatta kertaa kymmenentuhatta ja tuhat kertaa tuhat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'sanovan suurella äänellä: \"Karitsa, joka on teurastettu, on arvollinen saamaan voiman, rikkauden, viisauden, väkevyyden, kunnian, kirkkauden ja ylistyksen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Kaikkien luotujen, jotka ovat taivaassa ja maan päällä ja maan alla ja merellä, ja kaikkien niissä olevien kuulin sanovan: \"Hänelle, joka valtaistuimella istuu, ja Karitsalle ylistys, kunnia, kirkkaus ja valta iäisyyksien iäisyyksiin!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Ja neljä olentoa sanoi: \"Aamen\", ja vanhimmat lankesivat kasvoilleen ja kumartaen rukoilivat sitä, joka elää iäisyyksien iäisyyksiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Sitten näin, kuinka Karitsa avasi yhden sineteistä, ja kuulin yhden neljästä olennosta sanovan kuin ukkosen äänellä: \"Tule ja katso!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Näin, ja katso: valkoinen hevonen, ja sen selässä istuvalla oli jousi, ja hänelle annettiin seppele, ja hän lähti voittajana ja voittamaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Kun Karitsa avasi toisen sinetin, kuulin toisen olennon sanovan: \"Tule ja katso!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Niin lähti toinen hevonen, tulipunainen, ja sen selässä istuvalle annettiin valta ottaa pois rauha maasta, että ihmiset surmaisivat toisiaan, ja hänelle annettiin suuri miekka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Kun Karitsa avasi kolmannen sinetin, kuulin kolmannen olennon sanovan: \"Tule ja katso!\" Ja näin, ja katso: musta hevonen, ja sen selässä istuvalla oli kädessään vaaka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'Kuulin ikään kuin äänen neljän olennon keskeltä sanovan: \"Koiniks-mitta vehnää yhden denaarin, ja kolme koiniksia ohria yhden denaarin! Mutta älä turmele öljyä äläkä viiniä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Kun Karitsa avasi neljännen sinetin, kuulin neljännen olennon äänen sanovan: \"Tule ja katso!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Näin, ja katso: harmahtava hevonen! Sen selässä istuvan nimi oli Kuolema, ja Kadotus seurasi hänen mukanaan, ja heidän valtaansa annettiin neljäs osa maasta, annettiin valta tappaa miekalla, nälällä, rutolla ja maan pedoilla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Kun Karitsa avasi viidennen sinetin, näin alttarin alla niiden sielut, jotka olivat surmatut Jumalan sanan tähden ja sen todistuksen tähden, joka heillä oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'He huusivat suurella äänellä sanoen: \"Kuinka kauaksi aikaa sinä, pyhä ja tosi Valtias, jätät tuomitsematta ja kostamatta veremme niille, jotka maan päällä asuvat?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Heille annettiin kullekin pitkä valkoinen viitta, ja heille sanottiin, että pysyisivät levollisina vielä vähän aikaa, kunnes täyttyy myös heidän palvelustovereidensa ja veljiensä luku, jotka tullaan tappamaan niin kuin heidätkin [tapettiin].');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Näin, kuinka Karitsa avasi kuudennen sinetin. Tuli suuri maanjäristys, ja aurinko meni mustaksi kuin karvainen säkkipuku, ja kuu tuli kuin vereksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'ja taivaan tähdet putosivat maahan, niin kuin viikunapuu varistaa raakileensa, kun suuri tuuli sitä ravistelee,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'ja taivas väistyi pois kuin kirjakäärö, joka kääritään kokoon, ja kaikki vuoret ja saaret siirtyivät sijoiltaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Maan kuninkaat, ylimykset, rikkaat, sotapäälliköt, mahtimiehet, ja kaikki orjat ja vapaat kätkeytyivät luoliin ja vuorten rotkoihin');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'ja sanoivat vuorille ja kallioille: \"Langetkaa päällemme ja kätkekää meidät hänen kasvoiltaan, joka valtaistuimella istuu, ja Karitsan vihalta!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Sillä hänen vihansa suuri päivä on tullut, ja kuka voi kestää?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Sen jälkeen näin neljän enkelin seisovan maan neljällä kulmalla ja pitelevän kiinni maan neljää tuulta, ettei tuuli puhaltaisi maan päälle, meren päälle eikä yhteenkään puuhun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'Näin erään muun enkelin kohoavan auringonnoususta, ja hänellä oli elävän Jumalan sinetti, ja hän huusi suurella äänellä niille neljälle enkelille, joille oli annettu maan ja meren vahingoittaminen,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'ja sanoi: \"Älkää vahingoittako maata älkääkä merta, älkää myöskään puita, ennen kuin olemme painaneet sinetin Jumalamme palvelijoiden otsaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'Kuulin sinetillä merkittyjen luvun, sata neljäkymmentä neljä tuhatta merkittyä kaikista israelilaisten sukukunnista:');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'Juudan sukukunnasta kaksitoista tuhatta sinetillä merkittyä, Ruubenin sukukunnasta kaksitoista tuhatta sinetillä merkittyä, Gaadin sukukunnasta kaksitoista tuhatta sinetillä merkittyä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'Asserin sukukunnasta kaksitoista tuhatta sinetillä merkittyä, Naftalin sukukunnasta kaksitoista tuhatta sinetillä merkittyä, Manassen sukukunnasta kaksitoista tuhatta sinetillä merkittyä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'Simeonin sukukunnasta kaksitoista tuhatta sinetillä merkittyä, Leevin sukukunnasta kaksitoista tuhatta sinetillä merkittyä, Isaskarin sukukunnasta kaksitoista tuhatta sinetillä merkittyä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'Sebulonin sukukunnasta kaksitoista tuhatta sinetillä merkittyä, Joosefin sukukunnasta kaksitoista tuhatta sinetillä merkittyä ja Benjaminin sukukunnasta kaksitoista tuhatta sinetillä merkittyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Tämän jälkeen näin, ja katso, oli suuri joukko, jota kukaan ei voinut laskea, kaikista kansanheimoista, sukukunnista, kansakunnista ja kielistä, ja he seisoivat valtaistuimen edessä ja Karitsan edessä puettuina pitkiin valkoisiin vaatteisiin palmut käsissään,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'ja he huusivat suurella äänellä sanoen: \"Autuus on Jumalallamme, joka valtaistuimella istuu, ja Karitsalla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'Kaikki enkelit seisoivat piirissä valtaistuimen, vanhinten ja neljän olennon ympärillä ja lankesivat kasvoilleen valtaistuimen eteen ja kumartaen rukoilivat Jumalaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'sanoen: \"Aamen! Ylistys, kirkkaus, viisaus, kiitos, kunnia, voima ja väkevyys meidän Jumalallemme iäisyyksien iäisyyksiin, aamen!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Niin yksi vanhimmista puhui minulle ja sanoi: \"Keitä ovat nämä pitkiin valkoisiin vaatteisiin puetut, ja mistä he ovat tulleet?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Sanoin hänelle: \"Herrani, sinä sen tiedät.\" Ja hän sanoi minulle: \"Nämä ovat ne, jotka tulevat suuresta ahdistuksesta, ja he ovat pesseet vaatteensa ja valkaisseet ne Karitsan veressä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Sen tähden he ovat Jumalan valtaistuimen edessä ja palvelevat häntä yötä päivää hänen temppelissään, ja hän, joka valtaistuimella istuu, on levittävä telttamajansa heidän ylitseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Heidän ei tule enää nälkä eikä enää jano, eikä aurinko satu heihin, eikä mikään helle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'sillä Karitsa, joka on valtaistuimen keskellä, on kaitseva heitä ja johdattava heidät elämän vetten lähteille, ja Jumala on pyyhkivä pois kaikki kyyneleet heidän silmistään.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'Kun hän avasi seitsemännen sinetin, taivaaseen tuli äänettömyys noin puoleksi tunniksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'Ja näin ne seitsemän enkeliä, jotka seisoivat Jumalan edessä, ja heille annettiin seitsemän torvea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'Tuli eräs muu enkeli ja asettui alttarin ääreen pitäen kultaista suitsutusastiaa, ja hänelle annettiin paljon suitsukkeita pantavaksi kaikkien pyhien rukouksiin kultaiselle alttarille, joka oli valtaistuimen edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'Suitsukkeiden savu nousi pyhien rukousten kanssa enkelin kädestä Jumalan eteen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Sitten enkeli otti suitsutusastian ja täytti sen alttarin tulella ja heitti maan päälle. Silloin syntyi ukkosenjyrinää, ääniä, salamoita ja maanjäristystä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'Seitsemän enkeliä, joilla oli seitsemän torvea, valmistautui puhaltamaan torviin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Ensimmäinen enkeli puhalsi torveen. Tuli rakeita ja tulta, verellä sekoitettuja, ja ne heitettiin maan päälle. Ja kolmas osa maata paloi, ja kolmas osa puita paloi, ja kaikki vihertävä ruoho paloi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Toinen enkeli puhalsi torveen. Mereen heitettiin kuin suuri, tulena palava vuori, ja kolmas osa merta muuttui vereksi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'ja kolmas osa luoduista, mitä meressä on ja joissa on henki, kuoli, ja kolmas osa laivoista hukkui.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'Kolmas enkeli puhalsi torveen. Niin taivaasta putosi suuri tähti, palava kuin tulisoihtu, ja se putosi kolmanteen osaan virtoja ja vesilähteisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'Tähden nimi oli Koiruoho. Kolmas osa vesistä muuttui koiruohoksi, ja paljon ihmisiä kuoli vedestä, koska se oli tullut karvaaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Neljäs enkeli puhalsi torveen. Silloin kolmas osa auringosta, kolmas osa kuusta ja kolmas osa tähdistä lyötiin vitsauksella, niin että kolmas osa niistä pimeni ja päivä kolmannelta osaltaan oli valoton ja samoin myös yö.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'Sitten näin ja kuulin erään enkelin keskitaivaalla sanovan suurella äänellä: \"Voi, voi, voi maan päällä asuvia niiden jäljellä olevien torvien äänten tähden, joihin kolme enkeliä vielä puhaltaa!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Viides enkeli puhalsi torveen, ja näin taivaasta maahan pudonneen tähden, ja sille annettiin syvyyden kaivon avain.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'Se avasi syvyyden kaivon, ja kaivosta nousi savua, kuin savua suuresta pätsistä, ja kaivon savu pimitti auringon ja ilman.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'Savusta lähti heinäsirkkoja maan päälle, ja niille annettiin valta, niin kuin maan skorpioneilla on valta,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'ja niille sanottiin, etteivät ne saa vahingoittaa maan ruohoa, mitään vihantaa eivätkä yhtään puuta, vaan ainoastaan niitä ihmisiä, joilla ei ole otsassaan Jumalan sinettiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'Niiden annettiin vaivata heitä viisi kuukautta, mutta ei tappaa heitä, ja ne vaivasivat, niin kuin vaivaa skorpioni, kun se pistää ihmistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'Niinä päivinä ihmiset etsivät kuolemaa, eivätkä sitä löydä. He haluavat kuolla, mutta kuolema pakenee heitä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Heinäsirkat olivat sotaan valmistautuneiden hevosten kaltaisia, ja niillä oli päässään kuin seppeleet, kullan näköiset, ja niiden kasvot olivat kuin ihmisten kasvot.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'Niiden hiukset olivat kuin naisten hiukset, ja niiden hampaat olivat kuin leijonien hampaat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'Niillä oli haarniskat ikään kuin rautahaarniskat, ja niiden siipien kohina oli kuin sotavaunujen ryske monien hevosten juostessa taisteluun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'Niillä oli pyrstöt kuin skorpioneilla, ja pyrstöissään niillä oli pistimet. Niillä oli valta vahingoittaa ihmisiä viisi kuukautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Niillä oli kuninkaanaan syvyyden enkeli, jonka nimi hepreaksi on Abaddon ja kreikaksi nimi on Apollyon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Ensimmäinen \"voi!\" on mennyt. Katso, tulee vielä kaksi voi-huutoa tämän jälkeen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Kuudes enkeli puhalsi torveen. Kuulin yhden äänen tulevan kultaisen alttarin neljästä sarvesta, Jumalan edestä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'ja ääni sanoi kuudennelle enkelille, jolla oli torvi: \"Päästä ne neljä enkeliä, jotka ovat sidottuina suurella Eufrat-virralla.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Silloin päästettiin neljä enkeliä, jotka hetkelleen, päivälleen, kuukaudelleen ja vuodelleen olivat valmiina tappamaan kolmannen osan ihmisistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'Ratsuväen joukkojen luku oli kaksikymmentä tuhatta kertaa kymmenen tuhatta. Kuulin niiden luvun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Tällaisilta näyttivät minusta hevoset ja niiden selässä istujat näyssä: ratsastajilla oli tulipunaiset, hyasintin väriset ja rikinkeltaiset haarniskat, ja hevosten päät olivat kuin leijonien päät, ja niiden suusta lähti tulta, savua ja rikkiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Näistä kolmesta sai kolmas osa ihmisiä surmansa: tulesta, savusta ja rikistä, jotka lähtivät niiden suusta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Sillä niiden voima on niiden suussa ja niiden hännässä. Niiden hännät näet ovat käärmeitten kaltaisia, ja niissä on päät, joilla ne vahingoittavat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Jäljelle jääneet ihmiset, ne, joita ei tapettu näillä vitsauksilla, eivät tehneet parannusta kättensä teoista, niin että olisivat lakanneet kumartamasta riivaajia sekä kultaisia, hopeaisia, vaskisia, kivisiä ja puisia epäjumalankuvia, jotka eivät voi nähdä, kuulla eivätkä kävellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'He eivät tehneet parannusta murhistaan, taioistaan, haureudestaan eivätkä varkauksistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Näin erään toisen, väkivahvan enkelin tulevan alas taivaasta. Hänellä oli pilvi verhona, ja sateenkaari oli hänen päänsä päällä. Hänen kasvonsa olivat kuin aurinko, ja hänen jalkansa kuin tuliset pilarit.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'Hänellä oli kädessään avattu pieni kirjakäärö, ja hän laski oikean jalkansa meren päälle ja vasemman maan päälle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'ja huusi suurella äänellä, niin kuin leijona karjahtelee. Kun hän huusi, antoi seitsemän ukkosenjyrinää ääntensä puhua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'Kun seitsemän ukkosenjyrinää oli puhunut, aioin kirjoittaa, mutta kuulin äänen taivaasta sanovan: \"Sinetöi, mitä seitsemän ukkosenjyrinää puhui, äläkä sitä kirjoita.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Enkeli, jonka näin seisovan meren päällä ja maan päällä, kohotti kätensä taivasta kohti');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'ja vannoi hänen kauttaan, joka elää iäisyyksien iäisyyksiin, hänen, joka on luonut taivaan ja mitä siinä on, ja maan ja mitä siinä on, ja meren ja mitä siinä on, ettei enää ole oleva aikaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'vaan että niinä päivinä, jolloin seitsemännen enkelin ääni kuuluu hänen puhaltaessaan torveen, Jumalan salaisuus käy täytäntöön sen hyvän sanoman mukaan, jonka hän on ilmoittanut palvelijoilleen profeetoille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'Sen äänen, jonka olin kuullut taivaasta, kuulin taas puhuvan minulle ja sanovan: \"Mene ja ota avattu pieni kirjakäärö, joka on meren ja maan päällä seisovan enkelin kädessä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'Lähdin enkelin luo ja pyysin, että hän antaisi minulle pienen kirjakäärön. Hän sanoi minulle: \"Ota ja syö se. Se karvastelee vatsassasi, mutta suussasi se on makea kuin hunaja.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Otin kirjakäärön enkelin kädestä ja söin sen. Se oli suussani makea kuin hunaja, mutta sen syötyäni vatsaani karvasteli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'Minulle sanottiin: \"Sinun tulee taas profetoida monista kansakunnista, pakanakansoista, kielistä ja kuninkaista.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Minulle annettiin sauvan kaltainen ruoko. Enkeli oli noussut seisomaan ja sanoi: \"Nouse ja mittaa Jumalan temppeli ja alttari ja ne, jotka siinä kumartaen rukoilevat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Mutta temppelin ulkopuolella oleva esikartano jätä ulkopuolelle äläkä sitä mittaa, sillä se on annettu pakanoille. He tallaavat pyhää kaupunkia neljäkymmentäkaksi kuukautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Annan kahdelle todistajalleni toimeksi säkkipukuihin puettuina profetoida tuhannen kahdensadan kuudenkymmenen päivän ajan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Nämä ovat ne kaksi öljypuuta ja ne kaksi lampunjalkaa, jotka seisovat maan Herran edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Jos joku tahtoo heitä vahingoittaa, lähtee tuli heidän suustaan ja nielee heidän vihollisensa. Jos joku tahtoo heitä vahingoittaa, hänen täytyy saada surmansa sillä tavalla.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Heillä on valta sulkea taivas, niin ettei sadetta tule heidän profetoimisensa päivinä, ja heillä on valta muuttaa vedet vereksi ja lyödä maata kaikilla vitsauksilla, niin usein kuin tahtovat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Kun he ovat lopettaneet todistamisensa, peto, joka nousee syvyydestä, ryhtyy sotaan heitä vastaan, voittaa heidät ja tappaa heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'Heidän ruumiinsa viruvat sen suuren kaupungin kadulla, jota hengellisesti kutsutaan Sodomaksi ja Egyptiksi ja jossa ristiinnaulittiin myös heidän Herransa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Ihmiset eri kansoista, sukukunnista, kielistä ja pakanakansoista näkevät heidän ruumiinsa kolme ja puoli päivää, eivätkä salli, että heidän ruumiinsa pannaan hautaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Ne, jotka maan päällä asuvat, iloitsevat heistä ja riemuitsevat. He lähettävät lahjoja toisilleen. Sillä nämä kaksi profeettaa olivat vaivanneet niitä, jotka maan päällä asuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Niiden kolmen ja puolen päivän kuluttua tuli Jumalasta elämän henki heidän päälleen, ja he nousivat jaloilleen, ja suuri pelko valtasi ne, jotka näkivät heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'He kuulivat suuren äänen taivaasta sanovan heille: \"Nouskaa tänne!\" Niin he nousivat taivaaseen pilvessä, ja heidän vihollisensa näkivät heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'Sillä hetkellä tapahtui suuri maanjäristys, ja kymmenes osa kaupunkia luhistui, ja maanjäristyksessä sai surmansa seitsemäntuhatta nimeä, ja muut pelästyivät ja antoivat kunnian taivaan Jumalalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Toinen \"voi!\" on mennyt. Katso, kolmas \"voi!\" tulee pian.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'Seitsemäs enkeli puhalsi torveen. Silloin kuului taivaassa suuria ääniä, jotka sanoivat: \"Maailman kuninkuus on tullut Herrallemme ja hänen Voidellulleen, ja hän on hallitseva iäisyyksien iäisyyksiin.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Kaksikymmentä neljä vanhinta, jotka istuivat valtaistuimillaan Jumalan edessä, lankesi kasvoilleen ja rukoili kumartaen Jumalaa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'sanoen: \"Kiitämme sinua, Herra Jumala, Kaikkivaltias, joka olet ja joka olit, siitä, että olet ottanut suuren voimasi ja hallitset.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'Pakanat olivat pitäneet vihaa, mutta nyt sinun vihasi on tullut, ja on tullut aika tuomita kuolleet ja maksaa palkka palvelijoillesi profeetoille, pyhille ja niille, jotka sinun nimeäsi pelkäävät, pienille ja suurille, ja saattaa turmioon maan turmelijat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Jumalan temppeli taivaassa aukeni, ja hänen liittonsa arkki näkyi hänen temppelissään, ja tuli salamoita, ääniä, ukkosen jyrinää, maanjäristystä ja suuria rakeita.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Näkyi suuri merkki taivaassa: vaimo, vaatetettu auringolla, ja kuu hänen jalkojensa alla, ja hänen päässään seppeleenä kaksitoista tähteä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Hän oli raskaana ja huusi synnytyskivuissaan, kun hänen oli tuskallista synnyttää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Näkyi myös toinen merkki taivaassa: katso: suuri, tulipunainen lohikäärme, jolla oli seitsemän päätä ja kymmenen sarvea, ja sen päissä seitsemän kruunua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'Sen pyrstö pyyhkäisi pois kolmannen osan taivaan tähtiä ja heitti ne maan päälle. Lohikäärme seisoi synnyttämäisillään olevan vaimon edessä nielläkseen hänen lapsensa, kun hän sen synnyttäisi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'Ja vaimo synnytti pojan, joka on kaitseva kaikkia pakanakansoja rautaisella valtikalla, ja hänen lapsensa temmattiin Jumalan luo ja hänen valtaistuimensa luo.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'Vaimo pakeni erämaahan, jossa hänellä oli Jumalan valmistama paikka, että häntä elätettäisiin siellä tuhat kaksisataa kuusikymmentä päivää.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'Oli sota taivaassa: Miikael ja hänen enkelinsä sotivat lohikäärmettä vastaan, ja lohikäärme ja hänen enkelinsä sotivat,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'mutta ne eivät voittaneet, eikä niillä enää ollut sijaa taivaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'Suuri lohikäärme, se vanha käärme, jota perkeleeksi ja saatanaksi kutsutaan, koko maanpiirin villitsijä, heitettiin maan päälle, ja hänen enkelinsä heitettiin hänen kanssaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'Kuulin suuren äänen taivaassa sanovan: \"Nyt on tullut pelastus, voima ja meidän Jumalamme valtakunta ja hänen Voideltunsa valta, sillä meidän veljiemme syyttäjä, joka yötä päivää syytti heitä Jumalamme edessä, on heitetty ulos.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'He ovat voittaneet hänet Karitsan veren kautta ja todistuksensa sanan kautta, ja olleet rakastamatta henkeään kuolemaan asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Sen tähden riemuitkaa, taivaat, ja te, jotka niissä asutte! Voi maata ja merta, sillä perkele on astunut alas luoksenne pitäen suurta vihaa, koska tietää, että hänellä on vähän aikaa!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Ja kun lohikäärme näki olevansa heitetty maan päälle, se ajoi takaa vaimoa, joka oli synnyttänyt miehen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Mutta vaimolle annettiin suuren kotkan kaksi siipeä hänen lentääkseen erämaahan sille paikalleen, jossa häntä elätetään aika ja kaksi aikaa ja puoli aikaa poissa käärmeen näkyvistä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'Käärme syöksi kidastaan vaimon jälkeen vettä niin kuin virran saattaakseen hänet virran vietäväksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Mutta maa auttoi vaimoa: maa avasi suunsa ja nieli virran, jonka lohikäärme oli syössyt kidastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Lohikäärme vihastui vaimoon, lähti käymään sotaa muita hänen jälkeläisiään vastaan, jotka pitävät Jumalan käskyt ja joilla on Jeesuksen todistus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 18, '');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'Seisoin meren hiekalla ja näin merestä nousevan pedon. Sillä oli seitsemän päätä ja kymmenen sarvea, ja sarvissaan kymmenen kruunua, ja päissään pilkkaava nimi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'Peto, jonka näin, oli leopardin näköinen. Sen jalat olivat kuin karhun, ja sen kita kuin leijonan kita. Lohikäärme antoi sille voimansa, valtaistuimensa ja suuren vallan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'Näin yhden sen päistä olevan kuin kuoliaaksi haavoitetun, mutta sen kuolinhaava parani, ja koko maa seurasi ihmetellen petoa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'He kumarsivat lohikäärmettä, koska se oli antanut sellaisen vallan pedolle, ja kumarsivat petoa sanoen: \"Kuka on pedon kaltainen, ja kuka voi sotia sitä vastaan?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'Sille annettiin suu puhua suuria sanoja ja pilkkapuheita, ja sille annettiin valta tehdä sitä neljäkymmentä kaksi kuukautta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Se avasi suunsa pilkkaamaan Jumalaa pilkatakseen hänen nimeään ja hänen majaansa, niitä, jotka taivaassa asuvat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Sille annettiin valta käydä sotaa pyhiä vastaan ja voittaa heidät, ja sen valtaan annettiin jokainen sukukunta, kieli ja kansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Kaikki maan päällä asuvat tulevat kumartamaan sitä, jokainen, jonka nimeä ei ole kirjoitettu teurastetun Karitsan elämänkirjaan, aina maailman perustamisesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Jos kenellä on korva, kuulkoon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Jos joku vie vankeuteen, hän joutuu itse vankeuteen. Jos joku tappaa miekalla, hänet pitää miekalla tappaa. Tässä on pyhien kärsivällisyys ja usko.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Näin toisen pedon nousevan maasta, ja sillä oli kaksi sarvea kuin karitsan sarvet, ja se puhui kuin lohikäärme.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Se käyttää kaikkea ensimmäisen pedon valtaa sen nähden ja saattaa maan ja siinä asuvat kumartamaan ensimmäistä petoa, sitä, jonka kuolinhaava parani.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'Se tekee suuria ihmeitä, niin että saa tulenkin taivaasta lankeamaan maahan ihmisten edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'Se villitsee maan päällä asuvia niillä ihmeillä, joita sen annettiin tehdä pedon edessä. Se saa maan päällä asuvat tekemään sen pedon kuvan, jossa oli miekanhaava ja joka virkosi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Sille annettiin valta antaa pedon kuvalle henki, että pedon kuva myös puhuisi ja saisi aikaan, että ketkä tahansa eivät kumartaneet pedon kuvaa, ne tapettaisiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Se saa kaikki, pienet ja suuret, sekä rikkaat että köyhät, sekä vapaat että orjat, panemaan merkin oikeaan käteensä tai otsaansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'ettei kukaan muu voisi ostaa eikä myydä kuin se, jossa on merkki: pedon nimi tai sen nimen luku.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Tässä on viisaus. Jolla on ymmärrystä, laskekoon pedon luvun, sillä se on ihmisen luku. Sen luku on kuusisataa kuusikymmentä kuusi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'Sitten näin, ja katso, Karitsa seisoi Siionin vuorella, ja hänen kanssaan sata neljäkymmentä neljä tuhatta, joiden otsaan oli kirjoitettu hänen Isänsä nimi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, '[Minä] kuulin äänen taivaasta ikään kuin paljojen vetten kohinan ja ikään kuin suuren ukkosenjyrinän, ja ääni, jonka kuulin, oli kuin sitransoittajien, kun he soittavat sitrojaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'He veisasivat uutta virttä valtaistuimen edessä ja neljän olennon ja vanhinten edessä, eikä kukaan voinut oppia sitä virttä, paitsi kaikki ne sata neljäkymmentä neljä tuhatta, jotka ovat ostetut maasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Nämä ovat ne, jotka eivät ole saastuttaneet itseään naisten kanssa, sillä he ovat neitsyitä. Nämä ovat ne, jotka seuraavat Karitsaa, mihin ikinä hän menee. Nämä ovat ostetut ihmisistä ensi hedelmänä Jumalalle ja Karitsalle,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'eikä heidän suussaan ole havaittu petosta. He ovat tahrattomia Jumalan valtaistuimen edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Näin keskitaivaalla lentävän erään toisen enkelin, jolla oli iankaikkinen evankeliumi julistettavana maan päällä asuville, jokaiselle kansalle, sukukunnalle, kielelle ja kansakunnalle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'Hän sanoi suurella äänellä: \"Pelätkää Jumalaa ja antakaa hänelle kunnia, sillä hänen tuomionsa hetki on tullut. Kumartakaa häntä, joka on tehnyt taivaan, maan, meren ja vetten lähteet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'Seurasi vielä toinen enkeli, joka sanoi: \"Kukistunut, kukistunut on suuri Babylon, joka haureutensa vihan viinillä on juottanut kaikkia kansoja.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'Heitä seurasi kolmas enkeli, joka sanoi suurella äänellä: \"Jos joku kumartaa petoa ja sen kuvaa ja ottaa sen merkin otsaansa tai käteensä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'niin hänkin on juova Jumalan vihan viiniä, joka sekoittamattomana on kaadettu hänen vihansa maljaan, ja häntä vaivataan tulella ja rikillä pyhien enkelien edessä ja Karitsan edessä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'Heidän vaivaamisensa savu on nouseva iäisyyksien iäisyyksiin, eikä niillä ole lepoa päivällä eikä yöllä, jotka kumartavat petoa ja sen kuvaa, eikä kenelläkään, joka ottaa sen nimen merkin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Tässä on pyhien kärsivällisyys. Tässä ovat ne, jotka pitävät Jumalan käskyt ja uskon Jeesukseen.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'Kuulin äänen taivaasta sanovan: \"Kirjoita: Autuaat ovat ne kuolleet, jotka kuolevat Herrassa tästedes. Totisesti – sanoo Henki – he saavat levätä vaivannäöstään, sillä heidän tekonsa seuraavat heitä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'Näin, ja katso: valkoinen pilvi, ja pilvellä istui Ihmisen Pojan kaltainen päässään kultakruunu ja kädessään terävä sirppi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'Eräs toinen enkeli tuli temppelistä huutaen suurella äänellä pilvellä istuvalle: \"Lähetä sirppisi ja leikkaa, sillä leikkuuaika on tullut, ja maan vilja on tuleentunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Pilvellä istuva heitti sirppinsä maan päälle, ja maa tuli leikatuksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'Eräs toinen enkeli lähti taivaan temppelistä, ja hänelläkin oli terävä sirppi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Alttarilta lähti vielä toinen enkeli, jolla oli tuli vallassaan, ja hän huusi suurella äänellä sille, jolla oli terävä sirppi, sanoen: \"Lähetä terävä sirppisi ja korjaa tertut maan viiniköynnöksestä, sillä sen rypäleet ovat kypsyneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Enkeli heitti sirppinsä alas maahan ja korjasi maan viiniköynnöksen hedelmät ja heitti ne suureen Jumalan vihan kuurnaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'Kuurna poljettiin kaupungin ulkopuolella, ja kuurnasta kuohui veri hevosten kuolaimiin asti, tuhannen kuudensadan stadionin päähän.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Näin toisen merkin taivaassa, suuren ja ihmeellisen: seitsemän enkeliä, joilla oli seitsemän viimeistä vitsausta, sillä niissä täyttyy Jumalan viha.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Näin kuin lasisen meren, tulella sekoitetun, ja niiden, jotka olivat saaneet voiton pedosta, sen kuvasta, sen merkistä ja sen nimen luvusta, seisovan lasisella merellä, ja heillä oli Jumalan sitrat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'He veisasivat Mooseksen, Jumalan palvelijan, virttä ja Karitsan virttä, sanoen: \"Suuret ja ihmeelliset ovat tekosi, Herra Jumala, Kaikkivaltias. Vanhurskaat ja todet ovat tiesi, sinä pyhien kuningas.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Kuka ei pelkäisi sinua, Herra, ja ylistäisi nimeäsi? Sillä sinä yksin olet Pyhä, sillä kaikki kansat tulevat ja kumartuvat edessäsi, koska vanhurskaat tuomiosi ovat tulleet julki.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Sen jälkeen minä näin: todistuksen majan temppeli avattiin taivaassa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'Seitsemän enkeliä, joilla oli ne seitsemän vitsausta, lähti temppelistä puettuina puhtaisiin, hohtaviin pellavavaatteisiin ja vyötettyinä rinnoilta kultaisilla vöillä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'Yksi neljästä olennosta antoi seitsemälle enkelille seitsemän kultamaljaa täynnä Jumalan vihaa, hänen, joka elää iäisyyksien iäisyyksiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'Temppeli tuli savua täyteen Jumalan kirkkaudesta ja hänen voimastaan, eikä kukaan voinut mennä sisälle temppeliin, ennen kuin seitsemän enkelin seitsemän vitsausta oli käynyt täytäntöön.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'Kuulin suuren äänen temppelistä sanovan seitsemälle enkelille: \"Menkää ja vuodattakaa seitsemän Jumalan vihan maljaa maan päälle.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'Ensimmäinen lähti ja vuodatti maljansa maan päälle. Tuli pahoja ja kamalia paiseita niihin ihmisiin, joissa oli pedon merkki ja jotka kumarsivat sen kuvaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Toinen enkeli vuodatti maljansa mereen, ja se tuli vereksi, ikään kuin kuolleen vereksi. Jokainen elävä sielu kuoli, mitä meressä oli.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Kolmas enkeli vuodatti maljansa jokiin ja vesilähteisiin, ja ne tulivat vereksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Kuulin vesien enkelin sanovan: \"Vanhurskas olet sinä, joka olet ja joka olit, kun näin olet tuominnut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Sillä pyhien ja profeettojen verta he ovat vuodattaneet, ja verta sinä olet antanut heidän juotavakseen. Sen he ovat ansainneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'Kuulin toisen alttarilta sanovan: \"Totisesti, Herra Jumala, Kaikkivaltias, oikeat ja vanhurskaat ovat sinun tuomiosi.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Neljäs enkeli vuodatti maljansa aurinkoon, ja sille annettiin valta paahtaa ihmisiä tulella.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'Ihmiset paahtuivat kovassa helteessä ja pilkkasivat Jumalan nimeä, hänen, jolla on vallassaan nämä vitsaukset, mutta he eivät tehneet parannusta, niin että olisivat antaneet hänelle kunnian.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Viides enkeli vuodatti maljansa pedon valtaistuimelle, ja sen valtakunta pimeni. He pureskelivat kielensä rikki tuskissaan');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'ja pilkkasivat taivaan Jumalaa tuskiensa ja paiseittensa tähden, mutta eivät tehneet parannusta teoistaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Kuudes enkeli vuodatti maljansa suureen Eufrat-virtaan, ja sen vesi kuivui, että tie valmistuisi auringon noususta tuleville kuninkaille.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, '[Minä] näin lohikäärmeen suusta, pedon suusta ja väärän profeetan suusta lähtevän kolme saastaista henkeä, sammakon kaltaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Sillä ne ovat riivaajien henkiä, jotka tekevät merkkejä. Ne lähtevät maan ja koko maanpiirin kuningasten luo kokoamaan heitä sotaan Jumalan, Kaikkivaltiaan, suurena päivänä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, '– Katso, minä tulen kuin varas. Autuas joka valvoo ja pitää vaatteistaan vaarin, ettei kulkisi alastomana eikä hänen häpeäänsä nähtäisi! –');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'Ne kokosivat heidät siihen paikkaan, jonka nimi hepreaksi on Harmageddon.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Seitsemäs enkeli vuodatti maljansa ilmaan, ja temppelistä, valtaistuimelta, lähti suuri ääni, joka sanoi: \"Se on tapahtunut.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'Tuli salamoita, ääniä ja ukkosenjyrinää. Tuli suuri maanjäristys, niin ankara ja suuri maanjäristys, ettei sellaista ole ollut siitä asti, kun ihmisiä on ollut maan päällä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'Se suuri kaupunki meni kolmeen osaan, ja kansojen kaupungit luhistuivat. Suuri Babylon tuli muistetuksi Jumalan edessä, niin että hän antoi sille vihansa kiivauden viinimaljan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Jokainen saari pakeni, eikä vuoria löydetty.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'Suuria talentin painoisia rakeita satoi taivaalta ihmisten päälle, ja ihmiset pilkkasivat Jumalaa raesateen vitsauksen tähden, sillä vitsaus oli hyvin suuri.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'Sitten tuli yksi niistä seitsemästä enkelistä, joilla oli seitsemän maljaa, ja puhui minulle sanoen: \"Tule, näytän sinulle sen suuren porton tuomion, joka istuu paljojen vetten päällä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'hänet, jonka kanssa maan kuninkaat ovat haureutta harjoittaneet ja jonka haureuden viinistä maan asukkaat ovat juopuneet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'Hän vei minut Hengessä erämaahan. Siellä näin naisen istuvan helakanpunaisen pedon selässä. Peto oli täynnä pilkkaavia nimiä, ja sillä oli seitsemän päätä ja kymmenen sarvea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Nainen oli puettu purppuraan ja helakanpunaan sekä koristeltu kullalla, jalokivillä ja helmillä ja piti kädessään kultaista maljaa, joka oli täynnä kauhistuksia ja hänen haureutensa saastaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'Hänen otsaansa oli kirjoitettu nimi, salaisuus: \"Suuri Babylon, maan porttojen ja kauhistusten äiti.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'Näin naisen olevan juovuksissa pyhien verestä ja Jeesuksen todistajien verestä. Hänet nähdessäni ihmettelin suuresti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'Enkeli sanoi minulle: \"Miksi ihmettelet? Sanon sinulle naisen salaisuuden ja sen pedon salaisuuden, joka häntä kantaa ja jolla on seitsemän päätä ja kymmenen sarvea.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'Peto, jonka näit, on ollut, eikä sitä enää ole, mutta se on nouseva syvyydestä ja menevä kadotukseen. Ne maan päällä asuvat, joiden nimet eivät ole kirjoitettuja elämän kirjaan, aina maailman perustamisesta, ihmettelevät, kun he näkevät pedon, että se on ollut eikä sitä enää ole, vaikka se on.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Tässä on ymmärrys, jolla on viisaus: Seitsemän päätä ovat seitsemän vuorta, joiden päällä nainen istuu. Ne ovat myös seitsemän kuningasta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'Heistä viisi on kaatunut, yksi on, toinen ei ole vielä tullut, ja kun hän tulee, hänen pitää vähän aikaa pysyä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'Peto, joka on ollut ja jota ei enää ole, on itse kahdeksas, ja on yksi noista seitsemästä, ja menee kadotukseen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Kymmenen sarvea, jotka näit, on kymmenen kuningasta, jotka eivät ole vielä saaneet kuninkuutta, mutta saavat vallan niin kuin kuninkaat yhdeksi hetkeksi pedon kanssa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Näillä on yksi ja sama mieli, ja he antavat voimansa ja valtansa pedolle.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'He sotivat Karitsaa vastaan, mutta Karitsa on voittava heidät, sillä hän on herrojen Herra ja kuningasten Kuningas. Kutsutut, valitut ja uskolliset voittavat hänen kanssaan.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'Hän sanoi minulle: \"Vedet, jotka näit siellä, missä portto istuu, ovat kansakuntia, väkijoukkoja, pakanoita ja kieliä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'Kymmenen sarvea, jotka näit, ja peto, ne vihaavat porttoa ja riisuvat hänet paljaaksi ja alastomaksi ja syövät hänen lihansa ja polttavat hänet tulessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Sillä Jumala on pannut heidän sydämeensä, että he täyttävät hänen ajatuksensa yksimielisesti, ja antavat kuninkuutensa pedolle, kunnes Jumalan sanat täyttyvät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'Nainen, jonka näit, on se suuri kaupunki, jolla on maan kuninkaitten kuninkuus.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Sen jälkeen näin tulevan taivaasta alas erään toisen enkelin, jolla oli suuri valta, ja maa valkeni hänen kirkkaudestaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'Hän huusi kovaa suurella äänellä sanoen: \"Luhistunut, luhistunut on suuri Babylon. Siitä on tullut riivaajien asuinpaikka ja kaikkien saastaisten henkien vankila ja kaikkien saastaisten ja vihattavien lintujen vankila.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Sillä hänen haureutensa vihan viiniä ovat kaikki kansat juoneet, ja maan kuninkaat ovat haureutta harjoittaneet hänen kanssaan, ja maan kauppiaat ovat rikastuneet hänen ylellisyytensä voimasta.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'Sitten kuulin toisen äänen taivaasta sanovan: \"Lähtekää siitä ulos, te minun kansani, ettette tulisi osallisiksi hänen synteihinsä ja saisi osaksenne hänen vitsauksiaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'Sillä hänen syntinsä ulottuvat taivaaseen asti, ja Jumala on muistanut hänen rikoksensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Kostakaa hänelle sen mukaan, kuin hän on tehnyt teille, ja antakaa hänelle kaksinkertaisesti hänen teoistaan. Siihen maljaan, johon hän on kaatanut, kaatakaa te hänelle kaksin verroin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Niin paljon kuin hän on hankkinut itselleen kunniaa ja ylellisyyttä, niin paljon antakaa hänelle vaivaa ja surua. Koska hän sanoo sydämessään: \'Minä istun kuningattarena enkä ole leski enkä ole surua näkevä\',');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'sen tähden hänen vitsauksensa tulevat yhtenä päivänä: kuolema, suru ja nälkä, ja hänet poltetaan tulessa, sillä väkivahva on Herra Jumala, joka hänet tuomitsee.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'Maanpiirin kuninkaat, jotka harjoittivat hänen kanssaan haureutta ja elivät ylellisesti, itkevät ja valittavat häntä, kun näkevät hänen palonsa savun.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'He seisovat loitolla kauhistuen hänen vaivaansa ja sanovat: \"Voi, voi sinua, Babylon, sinä suuri kaupunki, sinä vahva kaupunki, sillä sinun tuomiosi tuli yhdessä hetkessä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Maanpiirin kauppiaat itkevät ja surevat häntä, kun kukaan ei enää osta heidän tavaraansa,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'kaupaksi tuotua kultaa, hopeaa, jalokiviä, helmiä, pellavakangasta, purppuraa, silkkiä, helakanpunaa, kaikenlaista hajupuuta, kaikenlaisia norsunluuesineitä, kaikenlaisia kalleimmasta puusta, vaskesta, raudasta ja marmorista tehtyjä esineitä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'kanelia, hiusvoidetta, suitsuketta, hajuvoidetta, suitsutuspihkaa, viiniä, öljyä, ydinjauhoja, viljaa, karjaa, lampaita, hevosia, vaunuja, orjia ja ihmissieluja.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'Hedelmät, joita sielusi himoitsi, ovat sinulta menneet, ja kaikki kalleutesi ja kimalluksesi ovat sinulta hävinneet, etkä löydä niitä enää koskaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Niiden kauppiaat, ne, jotka rikastuivat tästä kaupungista, seisovat loitolla kauhistuen hänen vaivaansa, itkien ja surren,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'ja sanovat: \"Voi, voi sitä suurta kaupunkia, joka oli puettu pellavaan, purppuraan ja helakanpunaan sekä koristeltu kullalla, jalokivillä ja helmillä, kun sellainen rikkaus tuhoutui yhdessä hetkessä!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'Kaikki laivurit, kaikki rannikkopurjehtijat, merimiehet ja kaikki merenkulkijat seisoivat loitolla');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'ja huusivat nähdessään hänen palonsa savun ja sanoivat: \"Mikä on tämän suuren kaupungin kaltainen?\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'He heittivät tomua päänsä päälle ja huusivat itkien ja surren ja sanoivat: \"Voi, voi sitä suurta kaupunkia, jonka kalleuksista rikastuivat kaikki, joilla oli laivoja merellä, kun se yhdessä hetkessä tuhoutui!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Riemuitse hänestä, taivas, ja pyhät ja apostolit ja profeetat, sillä Jumala on tuominnut hänet ja kostanut hänelle teidän tuomionne.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Väkivahva enkeli otti kiven, kuin suuren myllynkiven, ja heitti sen mereen sanoen: \"Näin heitetään vauhdilla pois Babylon, se suuri kaupunki, eikä sitä enää löydetä.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'Sinussa ei enää kuulla sitransoittajien ja laulajien, huilun- ja torvensoittajien ääntä, sinusta ei enää löydetä minkään ammatin taitajaa eikä sinussa kuulla enää myllyn ääntä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'Sinussa ei loista enää lampun valo. Sinussa ei kuulla enää huutoa yljälle eikä huutoa morsiamelle, sillä kauppiaasi olivat maan mahtavia, ja noituutesi eksytti kaikki kansat.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'Ja hänestä on löydetty profeettojen ja pyhien veri ja kaikkien veri, jotka maan päällä ovat tapetut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Sen jälkeen kuulin kuin kansan paljouden suuren äänen taivaassa sanovan: \"Halleluja! Pelastus, kunnia, ylistys ja voima Herralle, Jumalallemme!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Sillä oikeat ja vanhurskaat ovat hänen tuomionsa, sillä hän on tuominnut suuren porton, joka turmeli maan haureudellaan, ja on kostanut hänen kätensä vuodattaman palvelijoidensa veren.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'He sanoivat toisen kerran: \"Halleluja!\" Hänen savunsa nousee iäisyyksien iäisyyksiin asti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'Kaksikymmentä neljä vanhinta ja neljä olentoa lankesivat maahan ja kumartaen rukoilivat Jumalaa, joka valtaistuimella istuu, ja sanoivat: \"Aamen, halleluja!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Valtaistuimelta lähti ääni, joka sanoi: \"Ylistäkää meidän Jumalaamme, kaikki hänen palvelijansa, te, jotka häntä pelkäätte, sekä pienet että suuret.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'Kuulin kuin kansan paljouden äänen ja kuin paljojen vetten kohinan ja kuin suurten ukkosen jyrähdysten sanovan: \"Halleluja! Sillä Herra, meidän Jumalamme, Kaikkivaltias, on ottanut kuninkuuden.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Iloitkaamme ja riemuitkaamme ja antakaamme kunnia hänelle, sillä Karitsan häät ovat tulleet, ja hänen vaimonsa on itsensä valmistanut.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'Hänen annettiin pukeutua liinavaatteeseen, hohtavaan ja kirkkaaseen: liina on pyhien vanhurskaudet.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'Hän sanoi minulle: \"Kirjoita: Autuaat ne, jotka ovat kutsutut Karitsan hääaterialle!\" Vielä hän sanoi minulle: \"Nämä sanat ovat todet Jumalan sanat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'Silloin lankesin hänen jalkojensa juureen kumartaen rukoillakseni häntä. Mutta hän sanoi minulle: \"Varo, ettet tee sitä. Olen sinun ja veljiesi työtoveri, niiden, joilla on Jeesuksen todistus. Kumartaen rukoile Jumalaa. Sillä Jeesuksen todistus on profetian henki.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, '[Minä] näin taivaan avoinna. Ja katso: valkoinen hevonen, ja sen selässä istuvan nimi on Uskollinen ja Tosi, ja hän tuomitsee ja sotii vanhurskaudessa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Hänen silmänsä olivat kuin tulen liekit, ja hänen päässään oli monta kruunua. Hänellä oli kirjoitettuna nimi, jota ei tiedä kukaan muu kuin hän itse,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'ja hänellä oli yllään vereen kastettu viitta, ja nimi, jolla häntä kutsutaan, on Jumalan Sana.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'Häntä seurasivat ratsastaen valkoisilla hevosilla taivaassa olevat sotajoukot puettuina valkoiseen ja puhtaaseen pellavaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'Hänen suustaan lähtee terävä miekka hänen sillä lyödäkseen pakanakansoja. Hän on kaitseva heitä rautaisella valtikalla, ja hän polkee kaikkivaltiaan Jumalan vihan kiivauden viinikuurnan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'Hänellä on viitassa lanteillaan kirjoitettuna nimi: \"Kuningasten Kuningas ja herrojen Herra.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'Näin enkelin seisovan auringossa, ja hän huusi suurella äänellä sanoen kaikille keskitaivaalla lentäville linnuille: \"Tulkaa, kokoontukaa suuren Jumalan aterialle');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'syömään kuningasten lihaa, sotapäälliköiden lihaa, mahtavien lihaa ja hevosten sekä niiden selässä istuvien lihaa ja kaikkien vapaitten ja orjien lihaa, sekä pienten että suurten.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'Näin pedon, maan kuninkaat ja heidän sotajoukkonsa kokoontuneina sotiakseen hevosen selässä istuvaa vastaan ja hänen sotajoukkoaan vastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'Peto otettiin kiinni, ja sen kanssa väärä profeetta. Hän oli sen nähden tehnyt ihmetekonsa, joilla hän oli eksyttänyt ne, jotka olivat ottaneet pedon merkin, ja ne, jotka olivat kumartaneet sen kuvaa. Ne molemmat heitettiin tuliseen järveen, joka palaa rikkiä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'Muut saivat surmansa hevosen selässä istuvan miekasta, joka lähti hänen suustaan, ja kaikki linnut tulivat ravituiksi heidän lihastaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Näin tulevan taivaasta alas enkelin, jolla oli syvyyden avain ja suuri kahle kädessään.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'Hän otti kiinni lohikäärmeen, sen vanhan käärmeen, joka on perkele ja saatana, ja sitoi hänet tuhanneksi vuodeksi');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'ja heitti hänet syvyyteen ja sulki ja lukitsi sen sinetillä hänen jälkeensä, ettei hän enää villitsisi pakanoita, siihen asti kunnes ne tuhat vuotta ovat kuluneet loppuun. Sen jälkeen hänet pitää päästää irti vähäksi aikaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Näin valtaistuimia, ja he istuivat niillä, ja heille annettiin tuomiovalta. Näin niiden sielut, jotka olivat teloitetut Jeesuksen todistuksen ja Jumalan sanan tähden, ja niiden, jotka eivät olleet kumartaneet petoa, eivät sen kuvaa eivätkä ottaneet sen merkkiä otsaansa eivätkä käteensä. He elivät ja hallitsivat Kristuksen kanssa tuhat vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Muut kuolleet eivät alkaneet elää, ennen niiden tuhannen vuoden päättymistä. Tämä on ensimmäinen ylösnousemus.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Autuas ja pyhä on se, jolla on osa ensimmäisessä ylösnousemuksessa. Heihin toisella kuolemalla ei ole valtaa, vaan he tulevat olemaan Jumalan ja Kristuksen pappeja ja hallitsevat hänen kanssaan tuhat vuotta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Kun ne tuhat vuotta ovat lopullisesti päättymässä, päästetään saatana vankilastaan,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'ja hän lähtee villitsemään maan neljällä kulmalla olevia kansoja, Googia ja Maagogia, kootakseen heidät sotaan, ja niiden luku on kuin meren hiekka.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'He nousevat yli maan avaruuden ja piirittävät pyhien leirin ja sen rakastetun kaupungin. Mutta tuli lankeaa taivaasta ja syö heidät.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'Perkele, heidän villitsijänsä, heitettiin tuli- ja rikkijärveen, jossa myös peto ja väärä profeetta ovat, ja heitä vaivataan yötä päivää iäisyyksien iäisyyksiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'Näin suuren, valkoisen valtaistuimen ja sillä istuvan, jonka kasvoja maa ja taivas pakenivat, eikä niille löytynyt paikkaa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'Näin kuolleet, suuret ja pienet, seisomassa valtaistuimen edessä, ja kirjat avattiin, ja avattiin toinen kirja, joka on elämän kirja, ja kuolleet tuomittiin sen perusteella, mitä kirjoihin oli kirjoitettu, tekojensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'Meri antoi ne kuolleet, jotka siinä olivat, ja kuolema ja helvetti antoivat ne kuolleet, jotka niissä olivat, ja heidät tuomittiin, kukin tekojensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'Kuolema ja helvetti heitettiin tuliseen järveen. Tämä on toinen kuolema, tulinen järvi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'Joka ei ollut elämän kirjaan kirjoitettu, heitettiin tuliseen järveen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Näin uuden taivaan ja uuden maan, sillä ensimmäinen taivas ja ensimmäinen maa ovat kadonneet, eikä merta enää ole.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'Minä, Johannes, näin pyhän kaupungin, uuden Jerusalemin, laskeutuvan alas taivaasta Jumalan luota, valmistettuna kuin morsian, miehelleen kaunistettuna.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'Kuulin suuren äänen valtaistuimelta sanovan: \"Katso, Jumalan maja ihmisten keskellä! Hän on asuva heidän keskellään, ja he ovat hänen kansojaan, ja Jumala itse on oleva heidän kanssaan, heidän Jumalansa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'Hän on pyyhkivä pois kaikki kyyneleet heidän silmistään, eikä kuolemaa ole enää oleva, ei murhetta, ei itkua eikä kipua ole enää oleva, sillä entinen on mennyt pois.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Valtaistuimella istuva sanoi: \"Katso, uudeksi minä teen kaikki.\" Sitten hän sanoi: \"Kirjoita, sillä nämä sanat ovat todet ja luotettavat.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'Hän sanoi minulle: \"Se on tapahtunut. Minä olen A ja O, alku ja loppu. Minä annan janoavalle elämän veden lähteestä lahjaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Joka voittaa, on perivä kaiken, ja olen oleva hänelle Jumala, ja hän on oleva minulle poika.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Mutta pelkurien, epäuskoisten, saastaisten, murhaajien, huorintekijöiden, noitien, epäjumalanpalvelijoiden ja kaikkien valehtelijoiden osa on oleva siinä järvessä, joka palaa tulta ja rikkiä. Tämä on toinen kuolema.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Sitten tuli yksi niistä seitsemästä enkelistä, joilla oli seitsemän maljaa täynnä seitsemää viimeistä vitsausta, ja puhui kanssani sanoen: \"Tule, näytän sinulle morsiamen, Karitsan vaimon.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'Hän vei minut Hengessä suurelle ja korkealle vuorelle ja näytti minulle pyhän kaupungin, Jerusalemin, joka laskeutui alas taivaasta Jumalan luota,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'ja siinä oli Jumalan kirkkaus. Sen hohto oli kaikkein kalleimman kiven kaltainen, kuin kristallinkirkas jaspiskivi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'Sillä oli suuri ja korkea muuri, jossa oli kaksitoista porttia ja porteilla kaksitoista enkeliä, ja niihin oli kirjoitettu nimiä, ja ne ovat Israelin lasten kahdentoista sukukunnan nimet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'Idässä oli kolme porttia ja pohjoisessa kolme porttia ja etelässä kolme porttia ja lännessä kolme porttia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'Kaupungin muurilla oli kaksitoista perustusta, ja niissä Karitsan kahdentoista apostolin kaksitoista nimeä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'Sillä, joka minulle puhui, oli kultainen ruoko mitatakseen kaupungin, sen portit ja sen muurin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'Kaupunki oli neliskulmainen, ja sen pituus oli yhtä suuri kuin sen leveys. Hän mittasi mittakepillä kaupungin: se oli kaksitoista tuhatta stadionia. Sen pituus, leveys ja korkeus olivat yhtä suuret.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Hän mittasi myös sen muurin: se oli sata neljäkymmentä neljä kyynärää ihmismitan mukaan, joka on enkelinkin mitta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'Sen muuri oli rakennettu jaspiksesta, ja kaupunki oli puhdasta kultaa, puhtaan lasin kaltaista.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Kaupungin muurin perustukset oli koristeltu kaikenlaisilla kalliilla kivillä. Ensimmäinen perustus oli jaspis, toinen safiiri, kolmas kalkedon, neljäs smaragdi,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'viides sardonyks, kuudes sardion, seitsemäs krysoliitti, kahdeksas berylli, yhdeksäs topaasi, kymmenes krysoprasi, yhdestoista hyasintti ja kahdestoista ametisti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Kaksitoista porttia oli kaksitoista helmeä. Jokainen portti oli yhdestä helmestä. Kaupungin katu oli puhdasta kultaa, kuin läpinäkyvää lasia.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Mutta temppeliä en siinä nähnyt, sillä Herra Jumala, Kaikkivaltias, on sen temppeli, ja Karitsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'Eikä kaupunki tarvitse valokseen aurinkoa eikä kuuta, sillä Jumalan kirkkaus valaisee sen, ja sen lamppu on Karitsa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'Autuaat pakanat vaeltavat sen valossa, ja maan kuninkaat vievät sinne kunniansa ja kalleutensa.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'Sen portteja ei suljeta päivällä, eikä siellä ole yötä,');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'ja sinne viedään kansojen kunnia ja kalleudet.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'Sinne ei mene mitään epäpyhää, ei ketään kauhistusten eikä valheiden tekijää, vaan ainoastaan ne, jotka ovat kirjoitetut Karitsan elämänkirjaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'Hän näytti minulle elämän veden virran, joka kirkkaana kuin kristalli lähtee Jumalan ja Karitsan valtaistuimesta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Keskellä sen katua ja virran molemmilla puolilla oli elämän puu, joka kantoi kahdettoista hedelmät, antaen joka kuukausi hedelmänsä, ja puun lehdet ovat kansojen tervehtymistä varten.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'Eikä mitään kirousta ole enää oleva. Ja Jumalan ja Karitsan valtaistuin on siellä oleva, ja hänen palvelijansa palvelevat häntä');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'ja näkevät hänen kasvonsa, ja hänen nimensä on heidän otsallaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'Eikä siellä ole yötä, eivätkä he tarvitse lampun valoa eivätkä auringon valoa, sillä Herra Jumala on valaiseva heitä, ja he hallitsevat iäisyyksien iäisyyksiin.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'Hän sanoi minulle: \"Nämä sanat ovat luotettavat ja todet, ja Herra, profeettojen henkien Jumala, on lähettänyt enkelinsä näyttämään palvelijoilleen, mitä pian täytyy tapahtua.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Katso, minä tulen pian. Autuas se, joka ottaa vaarin tämän kirjan profetian sanoista!\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'Minä, Johannes, olen se, joka olen tämän nähnyt ja kuullut. Kun olin sen kuullut ja nähnyt, lankesin maahan kumartuakseni sen enkelin jalkojen eteen, joka tämän minulle näytti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Mutta hän sanoi minulle: \"Varo, ettet sitä tee. Minä olen sinun ja veljiesi, profeettojen, työtoveri, ja niiden, jotka ottavat tämän kirjan sanoista vaarin. Rukoile kumartaen Jumalaa.\"');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Sitten hän sanoi minulle: \"Älä sinetöi tämän kirjan profetian sanoja, sillä aika on lähellä.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Vääryyden tekijä tehköön edelleen vääryyttä, ja saastainen saastukoon edelleen, ja vanhurskas tehköön edelleen vanhurskautta, ja pyhä pyhittyköön edelleen.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'Katso, tulen pian, ja palkkani on mukanani maksaakseni kullekin hänen tekojensa mukaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Minä olen A ja O, ensimmäinen ja viimeinen, alku ja loppu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Autuaat ne, jotka pitävät hänen käskynsä, että heillä olisi valta elämän puuhun ja valta käydä porteista sisälle kaupunkiin!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Ulkopuolella ovat koirat, noidat, huorintekijät, murhaajat, epäjumalanpalvelijat ja kaikki, jotka rakastavat ja tekevät valhetta.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Minä, Jeesus, lähetin enkelini todistamaan näitä teille seurakunnissa. Minä olen Daavidin juurivesa ja hänen sukuaan, kirkas tähti ja aamutähti.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'Henki ja morsian sanovat: \"Tule!\" Joka kuulee, sanokoon: \"Tule!\" Joka janoaa, tulkoon, ja joka tahtoo, ottakoon elämän vettä lahjaksi.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Minä todistan jokaiselle, joka tämän kirjan profetian sanat kuulee: Jos joku panee niihin jotakin lisää, Jumala panee hänen päälleen ne vitsaukset, jotka ovat kirjoitetut tähän kirjaan.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'Jos joku taas ottaa pois jotakin tämän profetian kirjan sanoista, niin Jumala ottaa pois hänen osansa elämän kirjaan, pyhään kaupunkiin ja siihen, mitä tähän kirjaan on kirjoitettu.');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Hän, joka näitä todistaa, sanoo: \"Totisesti, tulen pian.\" Aamen, niin, tule, Herra Jeesus!');
INSERT INTO `FinSTLK2017_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Herramme Jeesuksen armo on teidän kaikkien kanssa. Aamen.');
